INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'У почетку створи Бог небо и земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'А земља бјеше без обличја и пуста, и бјеше тама над безданом; и дух Божји дизаше се над водом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'И рече Бог: нека буде свјетлост. И би свјетлост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'И видје Бог свјетлост да је добра; и растави Бог свјетлост од таме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'И свјетлост назва Бог дан, а таму назва ноћ. И би вече и би јутро, дан први.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Потом рече Бог: нека буде свод посред воде, да раставља воду од воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'И створи Бог свод, и растави воду под сводом од воде над сводом; и би тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'А свод назва Бог небо. И би вече и би јутро, дан други.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Потом рече Бог: нека се сабере вода што је под небом на једно мјесто, и нека се покаже сухо. И би тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'И сухо назва Бог земља, а зборишта водена назва мора; и видје Бог да је добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Опет рече Бог: нека пусти земља из себе траву, биље, што носи сјеме, и дрво родно, које рађа род по својим врстама, у којем ће бити сјеме његово на земљи. И би тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'И пусти земља из себе траву, биље, што носи сјеме по својим врстама, и дрво, које рађа род, у којем је сјеме његово по његовијем врстама. И видје Бог да је добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'И би вече и би јутро, дан трећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Потом рече Бог: нека буду видјела на своду небеском, да дијеле дан и ноћ, да буду знаци временима и данима и годинама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'И нека свијетле на своду небеском, да обасјавају земљу. И би тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'И створи Бог два видјела велика: видјело веће да управља даном, и видјело мање да управља ноћу, и звијезде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'И постави их Бог на своду небеском да обасјавају земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'И да управљају даном и ноћу, и да дијеле свјетлост од таме. И видје Бог да је добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'И би вече и би јутро, дан четврти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Потом рече Бог: нека врве по води живе душе, и птице нека лете изнад земље под свод небески.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'И створи Бог китове велике и све живе душе што се мичу, што проврвјеше по води по врстама својим, и све птице крилате по врстама њиховијем. И видје Бог да је добро;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'И благослови их Бог говорећи: рађајте се и множите се, и напуните воду по морима, и птице нека се множе на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'И би вече и би јутро, дан пети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Потом рече Бог: нека земља пусти из себе душе живе по врстама њиховијем, стоку и ситне животиње и звијери земаљске по врстама њиховијем. И би тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'И створи Бог звијери земаљске по врстама њиховијем, и стоку по врстама њезинијем, и све ситне животиње на земљи по врстама њиховијем. И видје Бог да је добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Потом рече Бог: да начинимо човјека по својему обличју, као што смо ми, који ће бити господар од риба морских и од птица небеских и од стоке и од цијеле земље и од свијех животиња што се мичу по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'И створи Бог човјека по обличју својему, по обличју Божијему створи га; мушко и женско створи их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'И благослови их Бог, и рече им Бог: рађајте се и множите се, и напуните земљу, и владајте њом, и будите господари од риба морских и од птица небеских и од свега звјериња што се миче по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'И још рече Бог: ево, дао сам вам све биље што носи сјеме по свој земљи, и сва дрвета родна која носе сјеме; то ће вам бити за храну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'А свему звјерињу земаљском и свјема птицама небеским и свему што се миче на земљи и у чем има душа жива, дао сам сву траву да једу. И би тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Тада погледа Бог све што је створио, и гле, добро бјеше веома. И би вече и би јутро, дан шести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Тако се доврши небо и земља и сва војска њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'И сврши Бог до седмога дана дјела своја, која учини; и почину у седми дан од свијех дјела својих, која учини;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'И благослови Бог седми дан, и посвети га, јер у тај дан почину од свијех дјела својих, која учини;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'То је постање неба и земље, кад посташе, кад Господ Бог створи земљу и небо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'И сваку биљку пољску, докле је још не бјеше на земљи, и сваку травку пољску, докле још не ницаше; јер Господ Бог још не пусти дажда на земљу, нити бјеше човјека да ради земљу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Али се подизаше пара са земље да натапа сву земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'А створи Господ Бог човјека од праха земаљскога, и дуну му у нос дух животни; и поста човјек душа жива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'И насади Господ Бог врт у Едему на истоку; и ондје намјести човјека, којега створи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'И учини Господ Бог, те никоше из земље свакојака дрвета лијепа за гледање и добра за јело, и дрво од живота усред врта и дрво од знања добра и зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'А вода тецијаше из Едема натапајући врт, и оданде се дијељаше у четири ријеке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Једној је име Фисон, она тече око цијеле земље Евилске, а ондје има злата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'И злато је оне земље врло добро; ондје има и бдела и драгога камена ониха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'А другој је ријеци име Геон, она тече око цијеле земље Хуске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'А трећој је ријеци име Хидекел, она тече к Асирској. А четврта је ријека Ефрат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'И узевши Господ Бог човјека намјести га у врту Едемском, да га ради и да га чува.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'И запријети Господ Бог човјеку говорећи: једи слободно са свакога дрвета у врту;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Али с дрвета од знања добра и зла, с њега не једи; јер у који дан окусиш с њега, умријећеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'И рече Господ Бог: није добро да је човјек сам; да му начиним друга према њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Јер Господ Бог створи од земље све звијери пољске и све птице небеске, и доведе к Адаму да види како ће коју назвати, па како Адам назове коју животињу онако да јој буде име;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'И Адам надједе име сваком живинчету и свакој птици небеској и свакој звијери пољској; али се не нађе Адаму друг према њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'И Господ Бог пусти тврд сан на Адама, те заспа; па му узе једно ребро, и мјесто попуни месом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'И Господ Бог створи жену од ребра, које узе Адаму, и доведе је к Адаму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'А Адам рече: сада ето кост од мојих кости, и тијело од мојега тијела. Нека јој буде име човјечица, јер је узета од човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'За то ће оставити човјек оца својега и матер своју, и прилијепиће се к жени својој, и биће двоје једно тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'А бјеху обоје голи, Адам и жена му, и не бјеше их срамота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Али змија бјеше лукава мимо све звијери пољске, које створи Господ Бог; па рече жени: је ли истина да је Бог казао да не једете са свакога дрвета у врту?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'А жена рече змији: ми једемо рода са свакога дрвета у врту;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Само рода с онога дрвета усред врта, казао је Бог, не једите и не дирајте у њ, да не умрете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'А змија рече жени: нећете ви умријети;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Него зна Бог да ће вам се у онај дан кад окусите с њега отворити очи, па ћете постати као богови и знати што је добро што ли зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'И жена видећи да је род на дрвету добар за јело и да га је милина гледати и да је дрво врло драго ради знања, узабра рода с њега и окуси, па даде и мужу својему, те и он окуси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Тада им се отворише очи, и видјеше да су голи; па сплетоше лишћа смокова и начинише себи прегаче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'И зачуше глас Господа Бога, који иђаше по врту кад захлади; и сакри се Адам и жена му испред Господа Бога међу дрвета у врту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'А Господ Бог викну Адама и рече му: гдје си?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'А он рече: чух глас твој у врту, па се поплаших, јер сам го, те се сакрих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'А Бог рече: ко ти каза да си го? да нијеси јео с онога дрвета што сам ти забранио да не једеш с њега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'А Адам рече: жена коју си удружио са мном, она ми даде с дрвета, те једох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'А Господ Бог рече жени: зашто си то учинила? А жена одговори: змија ме превари, те једох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Тада рече Господ Бог змији: кад си то учинила, да си проклета мимо свако живинче и мимо све звијери пољске; на трбуху да се вучеш и прах да једеш до својега вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'И још мећем непријатељство између тебе и жене и између сјемена твојега и сјемена њезина; оно ће ти на главу стајати а ти ћеш га у пету уједати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'А жени рече: теби ћу многе муке задати кад затрудниш, с мукама ћеш дјецу рађати, и воља ће твоја стајати под влашћу мужа твојега, и он ће ти бити господар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Па онда рече Адаму: што си послушао жену и окусио с дрвета с којега сам ти забранио рекавши да не једеш с њега, земља да је проклета с тебе, с муком ћеш се од ње хранити до својега вијека;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Трње и коров ће ти рађати, а ти ћеш јести зеље пољско;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Са знојем лица својега јешћеш хљеб, докле се не вратиш у земљу од које си узет; јер си прах, и у прах ћеш се вратити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'И Адам надједе жени својој име Јева, зато што је она мати свјема живима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'И начини Господ Бог Адаму и жени његовој хаљине од коже, и обуче их у њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'И рече Господ Бог: ето, човјек поста као један од нас знајући што је добро што ли зло; али сада да не пружи руке своје и узбере и с дрвета од живота, и окуси, те до вијека живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'И Господ Бог изагна га из врта Едемскога да ради земљу, од које би узет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'И изагнав човјека постави пред вртом Едемским херувима с пламенијем мачем, који се вијаше и тамо и амо, да чува пут ка дрвету од живота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Иза тога Адам позна Јеву жену своју, а она затрудње и роди Кајина, и рече: добих човјека од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'И роди опет брата његова Авеља. И Авељ поста пастир а Кајин ратар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'А послије некога времена догоди се, те Кајин принесе Господу принос од рода земаљскога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'А и Авељ принесе од првина стада својега и од њихове претилине. И Господ погледа на Авеља и на његов принос,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'А на Кајина и на његов принос не погледа. Зато се Кајин расрди веома, и лице му се промијени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Тада рече Господ Кајину: што се срдиш? што ли ти се лице промијени?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Нећеш ли бити мио, кад добро чиниш? а кад не чиниш добро, гријех је на вратима. А воља је његова под твојом влашћу, и ти си му старији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Послије говораше Кајин с Авељем братом својим. Али кад бијаху у пољу, скочи Кајин на Авеља брата својега, и уби га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Тада рече Господ Кајину: гдје ти је брат Авељ? А он одговори: не знам; зар сам ја чувар брата својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'А Бог рече: шта учини! глас крви брата твојега виче са земље к мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'И сада, да си проклет на земљи, која је отворила уста своја да прими крв брата твојега из руке твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Кад земљу узрадиш, неће ти више давати блага својега. Бићеш потукач и бјегунац на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'А Кајин рече Господу: кривица је моја велика да ми се не може опростити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Ево ме тјераш данас из ове земље да се кријем испред тебе, и да се скитам и потуцам по земљи, па ће ме убити ко ме удеси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'А Господ му рече: за то ко убије Кајина, седам ће се пута то покајати. И начини Господ знак на Кајину да га не убије ко га удеси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'И отиде Кајин испред Господа, и насели се у земљи Наидској на истоку према Едему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'И позна Кајин жену своју, а она затрудње и роди Еноха. И сазида град и прозва га по имену сина својега Енох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'А Еноху роди се Гаидад; а Гаидад роди Малелеила: а Малелеило роди Матусала; а Матусал роди Ламеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'И узе Ламех двије жене: једној бјеше име Ада а другој Села.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'И Ада роди Јовила; од њега се народише који живе под шаторима и стоку пасу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'А брату његову бјеше име Јувал; од њега се народише гудачи и свирачи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'А и Села роди Товела, који бјеше вјешт ковати свашта од мједи и од гвожђа; а сестра Товелу бјеше Ноема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'И рече Ламех својима женама, Ади и Сели: чујте глас мој, жене Ламехове, послушајте ријечи моје: убићу човјека за рану своју и младића за масницу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Кад ће се Кајин осветити седам пута, Ламех ће седамдесет и седам пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'А Адам опет позна жену своју, и она роди сина, и надје му име Сит, јер ми, рече, Бог даде другога сина за Авеља, којега уби Кајин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'И Ситу се роди син, којему надједе име Енос. Тада се поче призивати име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Ово је племе Адамово. Кад Бог створи човјека, по обличју својему створи га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Мушко и женско створи их, и благослови их, и назва их човјек, кад бише створени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'И поживје Адам сто и тридесет година, и роди сина по обличју својему, као што је он, и надједе му име Сит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'А родив Сита поживје Адам осам стотина година, рађајући синове и кћери;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Тако поживје Адам свега девет стотина и тридесет година; и умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'А Сит поживје сто и пет година, и роди Еноса;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'А родив Еноса поживје Сит осам стотина и седам година, рађајући синове и кћери;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Тако поживје Сит свега девет стотина и дванаест година; и умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'А Енос поживје деведесет година, и роди Кајинана;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'А родив Кајинана поживје Енос осам стотина и петнаест година, рађајући синове и кћери;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Тако поживје Енос свега девет стотина и пет година; и умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'А Кајинан поживје седамдесет година, и роди Малелеила;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'А родив Малелеила поживје Кајинан осам стотина и четрдесет година, рађајући синове и кћери;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Тако поживје Кајинан свега девет стотина и десет година; и умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'А Малелеило поживје шездесет и пет година, и роди Јареда;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'А родив Јареда поживје Малелеило осам стотина и тридесет година, рађајући синове и кћери;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Тако поживје Малелеило свега осам стотина и деведесет и пет година; и умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'А Јаред поживје сто и шездесет и двије године, и роди Еноха;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'А родив Еноха поживје Јаред осам стотина година, рађајући синове и кћери;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Тако поживје Јаред свега девет стотина и шездесет и двије године, и умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'А Енох поживје шездесет и пет година, и роди Матусала;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'А родив Матусала поживје Енох једнако по вољи Божјој триста година, рађајући синове и кћери;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Тако поживје Енох свега триста и шездесет и пет година;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'И живећи Енох једнако по вољи Божјој, нестаде га, јер га узе Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'А Матусал поживје сто и осамдесет и седам година, и роди Ламеха;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'А родив Ламеха поживје Матусал седам стотина и осамдесет и двије године, рађајући синове и кћери;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Тако поживје Матусал свега девет стотина и шездесет и девет година; и умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'А Ламех поживје сто и осамдесет и двије године, и роди сина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'И надједе му име Ноје говорећи: овај ће нас одморити од посала наших и од труда руку наших на земљи, коју прокле Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'А родив Ноја поживје Ламех пет стотина и деведесет и пет година, рађајући синове и кћери;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Тако поживје Ламех свега седам стотина и седамдесет и седам година; и умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'А Ноју кад би пет стотина година, роди Ноје Сима, Хама и Јафета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'А кад се људи почеше множити на земљи, и кћери им се народише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Видећи синови Божји кћери човјечије како су лијепе узимаше их за жене које хтјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'А Господ рече: неће се дух мој до вијека прети с људима, јер су тијело; нека им још сто и двадесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'А бијаше тада дивова на земљи; а и послије, кад се синови Божји састајаху са кћерима човјечијим, па им оне рађаху синове; то бијаху силни људи, од старине на гласу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'И Господ видећи да је неваљалство људско велико на земљи, и да су све мисли срца њихова свагда само зле,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Покаја се Господ што је створио човјека на земљи, и би му жао у срцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'И рече Господ: хоћу да истријебим са земље људе, које сам створио, од човјека до стоке и до ситне животиње и до птица небеских; јер се кајем што сам их створио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Али Ноје нађе милост пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Ово су догађаји Нојеви: Ноје бјеше човјек праведан и безазлен својега вијека; по вољи Божјој свагда живљаше Ноје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'И роди Ноје три сина: Сима, Хама и Јафета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'А земља се поквари пред Богом, и напуни се земља безакоња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'И погледа Бог на земљу, а она бјеше покварена; јер свако тијело поквари пут свој на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'И рече Бог Ноју: крај свакоме тијелу дође преда ме, јер напунише земљу безакоња; и ево хоћу да их затрем са земљом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Начини себи ковчег од дрвета гофера, и начини прегратке у ковчегу; и затопи га смолом изнутра и споља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'И начини га овако; у дужину нека буде триста лаката, у ширину педесет лаката, и у висину тридесет лаката;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Пусти доста свјетлости у ковчег; и кров му сведи озго од лакта; и удари врата ковчегу са стране; и начини га на три боја: доњи, други и трећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Јер ево пустићу потоп на земљу, да истријебим свако тијело, у којем има жива душа под небом; што је год на земљи све ће изгинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Али ћу с тобом учинити завјет свој: и ући ћеш у ковчег ти и синови твоји и жена твоја и жене синова твојих с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'И од свега жива, од свакога тијела, узећеш у ковчег по двоје, да сачуваш у животу са собом, а мушко и женско нека буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Од птица по врстама њиховијем, од стоке по врстама њезинијем, и од свега што се миче на земљи по врстама његовијем, од свега по двоје нека уђе с тобом, да их сачуваш у животу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'И узми са собом свега што се једе, и чувај код себе, да буде хране теби и њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'И Ноје учини, како му заповједи Бог, све онако учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'И рече Господ Ноју: уђи у ковчег ти и сав дом твој; јер те нађох праведна пред собом овога вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Узми са собом од свијех животиња чистих по седморо, све мужјака и женку његову; а од животиња нечистих по двоје, мужјака и женку његову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Такођер и од птица небеских по седам, мужјака и женку његову, да им се сачува сјеме на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Јер ћу до седам дана пустити дажд на земљу за четрдесет дана и четрдесет ноћи, и истријебићу са земље свако тијело живо, које сам створио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'И Ноје учини све што му заповједи Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'А бјеше Ноју шест стотина година кад дође потоп на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'И уђе Ноје у ковчег и синови његови и жена његова и жене синова његових с њим ради потопа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Од животиња чистих и од животиња нечистих и од птица и од свега што се миче по земљи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'Уђе к Ноју у ковчег по двоје, мушко и женско, као што бјеше Бог заповједио Ноју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'А у седми дан дође потоп на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Кад је било Ноју шест стотина година, те године другога мјесеца, седамнаести дан тога мјесеца, тај дан развалише се сви извори великога бездана, и отворише се уставе небеске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'И удари дажд на земљу за четрдесет дана и четрдесет ноћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Тај дан уђе у ковчег Ноје и Сим и Хам и Јафет, синови Нојеви, и жена Нојева и три жене синова његовијех с њима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Они, и свакојаке звијери по врстама својим, и свакојака стока по врстама својим, и што се год миче по земљи по врстама својим, и птице све по врстама својим, и што год лети и има крила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Дође к Ноју у ковчег по двоје од свакога тијела, у којем има жива душа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Мушко и женско од свакога тијела уђоше, као што бјеше Бог заповједио Ноју; па Господ затвори за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'И би потоп на земљи за четрдесет дана; и вода дође и узе ковчег, и подиже га од земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'И навали вода, и уста јако по земљи, и ковчег стаде пловити водом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'И наваљиваше вода све већма по земљи, и покори сва највиша брда што су под цијелијем небом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Петнаест лаката дође вода изнад брда, пошто их покри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Тада изгибе свако тијело што се мицаше на земљи, птице и стока, и звијери и све што гамиже по земљи, и сви људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Све што имаше душу живу у носу, све што бијаше на суху, помрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'И истријеби се свако тијело живо на земљи, и људи и стока и што год гамиже и птице небеске, све, велим, истријеби се са земље; само Ноје оста и што с њим бјеше у ковчегу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'И стајаше вода поврх земље сто и педесет дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'А Бог се опомену Ноја и свијех звијери и све стоке што бјеху с њим у ковчегу; и посла Бог вјетар на земљу да узбије воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'И затворише се извори бездану и уставе небеске, и дажд с неба престаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'И стаде вода опадати на земљи, и једнако опадаше послије сто и педесет дана;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Те се устави ковчег седмога мјесеца дана седамнаестога на планини Арарату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'И вода опадаше све већма до десетога мјесеца; и првога дана десетога мјесеца показаше се врхови од брда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'А послије четрдесет дана отвори Ноје прозор на ковчегу, који бјеше начинио;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'И испусти гаврана, који једнако одлијеташе и долијеташе докле не пресахну вода на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Па пусти и голубицу да би видио је ли опала вода са земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'А голубица не нашавши гдје би стала ногом својом врати се к њему у ковчег, јер још бјеше вода по свој земљи; и Ноје пруживши руку ухвати је и узе к себи у ковчег.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'И почека још седам дана, па опет испусти голубицу из ковчега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'И пред вече врати се к њему голубица, и гле, у кљуну јој лист маслинов, који бјеше откинула; тако позна Ноје да је опала вода са земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Али почека још седам дана, па опет испусти голубицу, а она му се више не врати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Шест стотина прве године вијека Нојева први дан првога мјесеца усахну вода на земљи; и Ноје откри кров на ковчегу, и угледа земљу суху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'А другога мјесеца двадесет седмога дана бјеше сва земља суха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Тада рече Бог Ноју говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Изиди из ковчега ти и жена твоја и синови твоји и жене синова твојих с тобом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Све звијери што су с тобом од свакога тијела, птице и стоку и што год гамиже по земљи, изведи са собом, нека се разиђу по земљи, и нека се плоде и множе на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'И изиде Ноје и синови његови и жена његова и жене синова његовијех с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Све звијери, све ситне животиње, све птице и све што се миче по земљи по својим врстама изидоше из ковчега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'И начини Ноје жртвеник Господу, и узе од сваке чисте стоке и од свијех птица чистијех, и принесе на жртвенику жртве паљенице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'И Господ омириса мирис угодни, и рече у срцу својем: нећу више клети земље с људи, што је мисао срца човјечијега зла од малена; нити ћу више убијати свега што живи, као што учиних.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Отселе докле буде земље, неће нестајати сјетве ни жетве, студени ни врућине, љета ни зиме, дана ни ноћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'И Бог благослови Ноја и синове његове, и рече им; рађајте се и множите се и напуните земљу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'И све звијери земаљске и све птице небеске и све што иде по земљи и све рибе морске нека вас се боје и страше; све је предано у ваше руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Што се год миче и живи, нека вам буде за јело, све вам то дадох као зелену траву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Али не једите меса с душом његовом, а то му је крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Јер ћу и вашу крв, душе ваше, искати; од сваке ћу је звијери искати; из руке самога човјека, из руке свакога брата његова искаћу душу човјечију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Ко пролије крв човјечију, његову ће крв пролити човјек; јер је Бог по својему обличју створио човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Рађајте се дакле и множите се; народите се веома на земљи и намножите се на њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'И рече Бог Ноју и синовима његовијем с њим, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'А ја ево постављам завјет свој с вама и с вашим сјеменом након вас,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'И са свијем животињама, што су с вама од птица, од стоке и од свега звијерја земаљскога што је с вама, са свачим што је изашло из ковчега, и са свијем звијерјем земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Постављам завјет свој с вама, те отселе неће ниједно тијело погинути од потопа, нити ће више бити потопа да затре земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'И рече Бог: ево знак завјета који постављам између себе и вас и сваке живе твари, која је с вама до вијека:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Метнуо сам дугу своју у облаке, да буде знак завјета између мене и земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Па кад облаке навучем на земљу, видјеће се дуга у облацима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'И опоменућу се завјета својега који је између мене и вас и сваке душе живе у сваком тијелу, и неће више бити од воде потопа да затре свако тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Дуга ће бити у облацима, па ћу је погледати, и опоменућу се вјечнога завјета између Бога и сваке душе живе у сваком тијелу које је на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'И рече Бог Ноју: то је знак завјета који сам учинио између себе и свакога тијела на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'А бијаху синови Нојеви који изидоше из ковчега: Сим и Хам и Јафет; а Хам је отац Хананцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'То су три сина Нојева, и од њих се насели сва земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'А Ноје поче радити земљу, и посади виноград.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'И напив се вина опи се, и откри се насред шатора својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'А Хам, отац Хананцима, видје голотињу оца својега, и каза обојици браће своје на пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'А Сим и Јафет узеше хаљину, и огрнуше је обојица на рамена своја, и идући натрашке покрише њом голотињу оца својега, лицем натраг окренувши се да не виде голотиње оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'А кад се Ноје пробуди од вина, дозна шта му је учинио млађи син,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'И рече: проклет да је Ханан, и да буде слуга слугама браће своје!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'И још рече: благословен да је Господ Бог Симов, и Ханан да му буде слуга!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Бог да рашири Јафета да живи у шаторима Симовијем, а Ханан да им буде слуга!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'И поживје Ноје послије потопа триста и педесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'А свега поживје Ноје девет стотина и педесет година; и умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'А ово су племена синова Нојевијех, Сима, Хама и Јафета, којима се родише синови послије потопа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Синови Јафетови: Гомер и Магог и Мадај и Јаван и Товел и Месех и Тирас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'А синови Гамерови: Асхенас и Рифат и Тогарма.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'А синови Јаванови: Елиса и Тарсис, Китим и Доданим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Од њих се раздијелише острва народна на земљама својим, свако по језику својему и по породицама својим, у народима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'А синови Хамови: Хус и Месраин, Фуд и Ханан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'А синови Хусови: Сава и Евила и Савата и Регма и Саватака. А синови Регмини: Сава и Дадан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Хус роди и Неврода; а он први би силан на земљи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Бјеше добар ловац пред Господом; зато се каже: добар ловац пред Господом као Неврод.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'А почетак царству његову бјеше Вавилон и Орех и Архад и Халани у земљи Сенару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Из те земље изађе Асур, и сазида Ниневију и Ровот град и Халах,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'И Дасем између Ниневије и Халаха; то је град велик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'А Месраин роди Лудеје и Енемеје и Лавеје и Нефталеје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'И Патросеје и Хасмеје, одакле изађоше Филистеји и Гафтореји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'А Ханан роди Сидона, првенца својега, и Хета,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'И Јевусеја и Амореја и Гергесеја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'И Евеја и Арукеја и Асенеја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'И Арадеја и Самареја и Аматеја. А послије се расијаше племена Хананејска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'И бјеху међе Хананејске од Сидона идући на Герар па до Газе, и идући на Содом и Гомор и Адаму и Севојим па до Даса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'То су синови Хамови по породицама својим и по језицима својим, у земљама својим и у народима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'И Симу родише се синови, најстаријему брату Јафетову, оцу свијех синова Еверовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Синови Симови бјеху: Елам и Асур и Арфаксад и Луд и Арам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'А синови Арамови: Уз и Ул и Гатер и Мас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'А арфаксад роди Салу, а Сала роди Евера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'А Еверу се родише два сина: једном бјеше име Фалек, јер се у његово вријеме раздијели земља, а брату његову име Јектан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'А Јектан роди Елмодада и Салета и Сармота и Јараха,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'И Одора и Евила и Деклу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'И Евала и Авимаила и Саву,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'И Уфира и Евилу и Јовава; ти сви бјеху синови Јектанови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'И живљаху од Масе, како се иде на Сафир до гора источнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'То су синови Симови по породицама својим и по језицима својим, у земљама својим и у народима својим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'То су породице синова Нојевијех по племенима својим, у народима својим; и од њих се раздијелише народи по земљи послије потопа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'А бијаше на цијелој земљи један језик и једнаке ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'А кад отидоше од истока, нађоше равницу у земљи Сенарској, и населише се ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Па рекоше међу собом: хајде да правимо плоче и да их у ватри печемо. И бјеху им опеке мјесто камена и смола земљана мјесто креча.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Послије рекоше: хајде да сазидамо град и кулу, којој ће врх бити до неба, да стечемо себи име, да се не бисмо расијали по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'А Господ сиђе да види град и кулу, што зидаху синови човјечији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'И рече Господ: гле, народ један, и један језик у свијех, и то почеше радити, и неће им сметати ништа да не ураде што су наумили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Хајде да сиђемо, и да им пометимо језик, да не разумију један другога што говоре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Тако их Господ расу оданде по свој земљи, те не сазидаше града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Зато се прозва Вавилон, јер ондје помете Господ језик цијеле земље, и оданде их расу Господ по свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Ово је племе Симово: бијаше Симу сто година, кад роди Арфаксада, друге године послије потопа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'А родив Арфаксада поживје Сим пет стотина година, рађајући синове и кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'А Арфаксад поживје тридесет и пет година, и роди Салу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'А родив Салу поживје Арфаксад четири стотине и три године, рађајући синове и кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'А Сала поживје тридесет година, и роди Евера;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'А родив Евера поживје Сала четири стотине и три године, рађајући синове и кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'А Евер поживје тридесет и четири године, и роди Фалека;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'А родив Фалека поживје Евер четири стотине и тридесет година, рађајући синове и кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'А Фалек поживје тридесет година и роди Рагава;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'А родив Рагава поживје Фалек двјеста и девет година, рађајући синове и кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'А Рагав поживје тридесет и двије године и роди Серуха;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'А родив Серуха поживје Рагав двјеста и седам година, рађајући синове и кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'А Серух поживје тридесет година, и роди Нахора;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'А родив Нахора поживје Серух двјеста година, рађајући синове и кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'А Нахор поживје двадесет и девет година, и роди Тару;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'А родив Тару поживје Нахор сто и деветнаест година, рађајући синове и кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'А Тара поживје седамдесет година, и роди Аврама, Нахора и Арана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'А ово је племе Тарино: Тара роди Аврама, Нахора и Арана; а Аран роди Лота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'И умрије Аран прије Таре оца својега на постојбини својој, у Уру Халдејском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'И ожени се Аврам и Нахор, и жени Аврамовој бјеше име Сара а жени Нахоровој име Мелха, кћи Арама оца Мелхе и Јесхе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'А Сара бјеше нероткиња, и не имаше порода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'И узе Тара сина својега Аврама и Лота сина Аронова, унука својега, и Сару снаху своју, жену Аврама сина својега; и пођоше заједно из Ура Халдејскога да иду у земљу Хананску, и дођоше до Харана, и ондје се настанише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'И поживје Тара свега двјеста и пет година; и умрије Тара у Харану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'И рече Господ Авраму: иди из земље своје и од рода својега и из дома оца својега у земљу коју ћу ти ја показати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'И учинићу од тебе велик народ, и благословићу те, и име твоје прославићу, и ти ћеш бити благослов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Благословићу оне који тебе узблагосиљају, и проклећу оне који тебе успроклињу; и у теби ће бити благословена сва племена на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Тада пође Аврам, као што му каза Господ, и с њим пође Лот. А бјеше Авраму седамдесет и пет година кад пође из Харана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'И узе Аврам Сару жену своју и Лота сина брата својега са свијем благом које бјеху стекли и с душама које бјеху добили у Харану; и пођоше у земљу Хананску, и дођоше у њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'И прође Аврам ту земљу до мјеста Сихема и до равнице Морешке; а бијаху тада Хананеји у тој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'И јави се Господ Авраму и рече: твојему сјемену даћу земљу ову. И Аврам начини ондје жртвеник Господу, који му се јавио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Послије отиде оданде на брдо које је према истоку од Ветиља, и ондје разапе шатор свој, те му Ветиљ бјеше са запада а Гај с истока; и ондје начини Господу жртвеник, и призва име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Оданде отиде Аврам даље идући на југ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Али наста глад у оној земљи, те Аврам сиђе у Мисир да се ондје склони; јер глад бјеше велика у оној земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'А кад се приближи да већ уђе у Мисир, рече Сари жени својој: гле, знам да си жена лијепа у лицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Зато кад те виде Мисирци рећи ће: ово му је жена. Па ће ме убити, а тебе ће оставити у животу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Него хајде кажи да си ми сестра, те ће мени бити добро тебе ради и остаћу у животу уз тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'И кад дође Аврам у Мисир, видјеше Мисирци жену да је врло лијепа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'И видјеше је кнезови Фараонови, и хвалише је пред Фараоном. И узеше је у двор Фараонов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'И он чињаше добро Авраму ње ради, те имаше оваца и говеда и магараца и слуга и слушкиња и магарица и камила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Али Господ пусти велика зла на Фараона и на дом његов ради Саре жене Аврамове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Тада дозва Фараон Аврама и рече му: шта ми то учини? зашто ми нијеси казао да ти је жена?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Зашто си казао: сестра ми је? те је узех за жену. Сад ето ти жене, узми је, па иди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'И Фараон заповједи људима за њ, те га испратише и жену његову и што год имаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Тако отиде Аврам из Мисира горе на југ, он и жена му и све што имаше, такођер и Лот с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'А бијаше Аврам врло богат стоком, сребром и златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'И иђаше својим путовима од југа све до Ветиља, до мјеста гдје му прво бијаше шатор, између Ветиља и Гаја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'До мјеста, гдје пређе бјеше начинио жртвеник; и ондје призва Аврам име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'А и Лот који иђаше с Аврамом имаше оваца и говеда и шатора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'И земља не могаше их носити заједно, јер благо њихово бијаше велико да не могаху живјети заједно,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'И бијаше свађа међу пастирима Аврамове стоке и пастирима Лотове стоке. А у то вријеме живљаху Хананеји и Ферезеји у оној земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Па Аврам рече Лоту: немој да се свађамо ја и ти, ни моји пастири и твоји пастири; јер смо браћа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Није ли ти отворена цијела земља? Одијели се од мене. Ако ћеш ти на лијево, ја ћу на десно; ако ли ћеш ти на десно, ја ћу на лијево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Тада Лот подиже очи своје и сагледа сву равницу Јорданску, како цијелу натапаше ријека, бјеше као врт Господњи, као земља Мисирска, све до Загора, прије него Господ затр Содом и Гомор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'И Лот изабра себи сву равницу Јорданску, и отиде Лот на исток; и раздијелише се један од другога:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Аврам живљаше у земљи Хананској, а Лот живљаше по градовима у оној равници премјештајући своје шаторе до Содома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'А људи у Содому бијаху неваљали, и гријешаху Господу веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'А Господ рече Авраму, пошто се Лот одијели од њега: подигни сада очи своје, па погледај с мјеста гдје си на сјевер и на југ и на исток и на запад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Јер сву земљу што видиш теби ћу дати и сјемену твојему до вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'И учинићу да сјемена твојега буде као праха на земљи; ако ко узможе избројити прах на земљи, моћи ће избројити и сјеме твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Устани, и пролази ту земљу у дужину и у ширину; јер ћу је теби дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'И Аврам диже шаторе, и дође и насели се у равници Мамријској, која је код Хеврона, и ондје начини жртвеник Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'А кад бјеше Амарфал цар Сенарски, Арион цар Еласарски, Ходологомор цар Еламски и Таргал цар Гојимски,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Завојштише на Валу цара Содомскога, и на Варсу цара Гоморскога, и на Сенара цара Адамскога, и на Симовора цара Севојимскога и на цара од Валаке, који је сада Сигор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Сви се ови скупише у долини Сидимској, која је сада слано море.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Дванаест година бјеху служили Ходологомору, па тринаесте године одметнуше се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'А четрнаесте године дође Ходологомор и цареви који бијаху с њим, и побише Рафаје у Астароту Карнајимском и Зузеје у Аму и Омеје у пољу Киријатајском,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'И Хореје у планини њиховој Сиру до равнице Фаранске покрај пустиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Отуда вративши се дођоше у Ен-Миспат, који је сада Кадис, и исјекоше све који живљаху у земљи Амаличкој, и Амореје који живљаху у Асасон-Тамару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Тада изиде цар Содомски и цар Гоморски и цар Адамски и цар Севојимски и цар од Валахе, која је сада Сигор, изидоше на њих у долину Сидимску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'На Ходологомора цара Еламскога, и на Таргала цара Гојимскога, и на Амарфала цара Сенарскога, и на Ариоха цара Еласарскога, четири цара на пет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'А у долини Сидимској бијаше много рупа из којих се вадила смола; и побјеже цар Содомски и цар Гоморски, и ондје падоше, а што оста побјеже у планину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'И узеше све благо у Содому и Гомору и сву храну њихову, и отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Узеше и Лота, синовца Аврамова, и благо његово, и отидоше, јер живљаше у Содому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'А дође један који бјеше утекао, те јави Авраму Јеврејину, који живљеше у равни Мамрија Аморејина, брата Есхолу и брата Авнану, који бјеху у вјери с Аврамом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'А кад Аврам чу да му се заробио синовац, наоружа слуге своје, триста осамнаест, који се родише у његовој кући, и пође у потјеру до Дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Ондје разредивши своје удари на њих ноћу са слугама својим, и разби их, и отјера их до Ховала, који је на лијево од Дамаска,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'И поврати све благо; поврати и Лота синовца својега с благом његовијем, и жене и људе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'А цар Содомски изиде му на сусрет кад се врати разбивши Ходологомора и цареве што бијаху с њим, у долину Савину, које је сада долина царева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'А Мелхиседек цар Салимски изнесе хљеб и вино; а он бијаше свештеник Бога вишњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'И благослови га говорећи: благословен да је Аврам Богу вишњему, чије је небо и земља!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'И благословен да је Бог вишњи, који предаде непријатеље твоје у руке твоје! И даде му Аврам десетак од свега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'А цар Содомски рече Авраму: дај мени људе, а благо узми себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'А Аврам рече цару Содомском: дижем руку своју ка Господу Богу вишњему, чије је небо и земља, заклињући се:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Ни конца ни ремена од обуће нећу узети од свега што је твоје, да не речеш: ја сам обогатио Аврама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Осим што су појели момци, и осим дијела људима који су ишли са мном, Есхолу, Авнану и Мамрију, они нека узму свој дио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Послије овијех ствари дође Авраму ријеч Господња у утвари говорећи: не бој се, Авраме, ја сам ти штит, и плата је твоја врло велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'А Аврам рече: Господе, Господе, шта ћеш ми дати кад живим без дјеце, а на ком ће остати моја кућа то је Елијезер овај Дамаштанин?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Још рече Аврам: ето мени нијеси дао порода, па ће слуга рођен у кући мојој бити мој нашљедник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'А гле, Господ му проговори: неће тај бити нашљедник твој, него који ће изаћи од тебе тај ће ти бити нашљедник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Па га изведе напоље и рече му: погледај на небо и преброј звијезде, ако их можеш пребројити. И рече му: тако ће ти бити сјеме твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'И повјерова Аврам Богу, а он му прими то у правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'И рече му: ја сам Господ, који те изведох из Ура Халдејскога да ти дам земљу ову да буде твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'А он рече: Господе, Господе, по чему ћу познати да ће бити моја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'И рече му: принеси ми јуницу од три године и козу од три године и овна од три године и грлицу и голупче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'И он узе све то, и расијече на поле, и метну све поле једну према другој; али не расијече птица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'А птице слијетаху на те мртве животиње; а Аврам их одгоњаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'А кад сунце бјеше на заходу, ухвати Аврама тврд сан, и гле, страх и мрак велик обузе га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'И Господ рече Авраму: знај зацијело да ће сјеме твоје бити дошљаци у земљи туђој, па ће јој служити, и она ће их мучити четири стотине година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Али ћу судити и народу којему ће служити; а послије ће они изаћи с великим благом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'А ти ћеш отићи к оцима својим у миру, и бићеш погребен у доброј старости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'А они ће се у четвртом кољену вратити овамо; јер гријесима Аморејским још није крај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'А кад се сунце смири и кад се смрче, гле, пећ се димљаше, и пламен огњени пролажаше између онијех дијелова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Тај дан учини Господ завјет с Аврамом говорећи: сјемену твојему дадох земљу ову од воде Мисирске до велике воде, воде Ефрата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Кенејску, Кенезејску и Кедмонејску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'И Хетејску и Ферезејску и Рафајску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'И Аморејску и Хананејску и Гергесејску и Јевусејску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Али Сара жена Аврамова не рађаше му дјеце. А имаше робињу Мисирку, по имену Агару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Па рече Сара Авраму: Господ ме је затворио да не родим; него иди к робињи мојој, не бих ли добила дјеце од ње. И Аврам приста на ријеч Сарину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'И Сара жена Аврамова узе Агару Мисирку робињу своју, и даде је за жену Авраму мужу својему послије десет година откако се настани Аврам у земљи Хананској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'И он отиде к Агари, и она затрудње; а кад видје да је трудна, понесе се од госпође своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'А Сара рече Авраму: увреда моја паде на тебе; ја ти метну на крило робињу своју, а она видјевши да је трудна понесе се од мене. Господ ће судити мени и теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'А Аврам рече Сари: ето, робиња је твоја у твојим рукама, чини с њом што ти је воља. И Сара је стаде злоставити, те она побјеже од ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Али анђео Господњи нађе је код студенца у пустињи, код студенца на путу у Сур.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'И рече јој: Агаро, робињо Сарина, откуда идеш, куда ли идеш? А она рече: бјежим од Саре госпође своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'А анђео јој Господњи рече: врати се госпођи својој и покори јој се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Опет јој рече анђео Господњи: умножићу веома сјеме твоје, да се неће моћи пребројити од множине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Јоште јој рече анђео Господњи: ето си трудна, и родићеш сина, и надјени му име Исмаило; јер је Господ видио муку твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'А биће човјек убојица; рука ће се његова дизати на свакога а свачија на њега, и наставаће на погледу свој браћи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Тада Агара призва име Господа који говори с њом: ти си Бог, који види. Јер говораше: зар још гледам иза онога који ме видје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Тога ради зове се студенац онај студенац живога који ме види; а он је између Кадиса и Варада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'И роди Агара Авраму сина; и надједе Аврам сину својему, којега му роди Агара, име Исмаило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'А бјеше Авраму осамдесет и шест година кад му Агара роди Исмаила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'А кад Авраму би деведесет и девет година, јави му се Господ и рече му: ја сам Бог свемогући, по мојој вољи живи и буди поштен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'И учинићу завјет између себе и тебе, и врло ћу те умножити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'А Аврам паде ничице. И Господ му још говори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Од мене ево завјет мој с тобом да ћеш бити отац многим народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Зато се више нећеш звати Аврам него ће ти име бити Авраам, јер сам те учинио оцем многих народа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Даћу ти породицу врло велику, и начинићу од тебе народе многе, и цареви ће изаћи од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'А постављам завјет свој између себе и тебе и сјемена твојега након тебе од кољена до кољена, да је завјет вјечан, да сам Бог теби и сјемену твојему након тебе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'И даћу теби и сјемену твојему након тебе земљу у којој си дошљак, сву земљу Хананску у државу вјечну, и бићу им Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'И рече Бог Авраму: ти пак држи завјет мој, ти и сјеме твоје након тебе од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'А ово је завјет мој између мене и вас и сјемена твојега након тебе, које ће те држати: да се обрезује између вас све мушкиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'А обрезиваћете окрајак тијела својега, да буде знак завјета између мене и вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Свако мушко дијете кад му буде осам дана да се обрезује од кољена до кољена, родило се у кући или било купљено за новце од којих год странаца, које не буде од сјемена твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Да се обрезује које се роди у кући твојој и које се купи за новце твоје; тако ће бити завјет мој на тијелу вашем завјет вјечан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'А необрезано мушко, којему се не обреже окрајак тијела његова, да се истријеби из народа својега јер поквари завјет мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'И још рече Бог Авраму: а Сару жену своју не зови је више Сара него нека јој буде име Саара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'И ја ћу је благословити, и даћу ти сина од ње; благословићу је, и биће мати многим народима, и цареви народима изаћи ће од ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Тада паде Аврам ничице и насмија се говорећи у срцу својему: еда ће се човјеку од сто година родити син? и Сари? еда ће жена од деведесет година родити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'И Аврам рече Богу: нека жив буде Исмаило пред тобом!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'И рече Бог: заиста Сара жена твоја родиће ти сина, и надјећеш му име Исак; и поставићу завјет свој с њим да буде завјет вјечан сјемену његову након њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'А и за Исмаила услишио сам те; ево благословио сам га, и даћу му породицу велику, и умножићу га веома; и родиће дванаест кнезова, и учинићу од њега велик народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'А завјет свој учинићу с Исаком кад ти га роди Сара, до године у ово доба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'И Бог изговоривши отиде од Аврама горе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'И Аврам узе Исмаила сина својега и све који се родише у дому његову и које год бјеше купио за своје новце, све мушкиње од домаћих својих; и обреза окрајак тијела њихова у исти дан, као што му каза Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'А бијеше Авраму деведесет и девет година кад обреза окрајак тијела својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'А Исмаилу сину његову бјеше тринаест година кад му се обреза окрајак тијела његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'У један дан обреза се Аврам и син му Исмаило,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'И сви домашњи његови, рођени у кући и купљени за новце од странаца, бише обрезани с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Послије му се јави Господ у равници Мамријској кад сјеђаше на вратима пред шатором својим у подне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Подигавши очи своје погледа, и гле, три човјека стајаху према њему. И угледавши их потрча им у сусрет испред врата шатора својега, и поклони се до земље;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'И рече: Господе, ако сам нашао милост пред тобом, немој проћи слуге својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Да вам донесемо мало воде и оперите ноге, те се наслоните мало под овијем дрветом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'И изнијећу мало хљеба, те поткријепите срце своје, па онда пођите, кад идете поред слуге својега. И рекоше: учини што си казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'И Аврам отрча у шатор к Сари, и рече: брже замијеси три копање бијелога брашна и испеци погаче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Па отрча ка говедима и ухвати теле младо и добро, и даде га момку да га брже зготови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Па онда изнесе масла и млијека и теле које бјеше зготовио, и постави им, а сам стајаше пред њима под дрветом докле јеђаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'И они му рекоше: гдје је Сара жена твоја? А он рече: ено је под шатором.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'А један између њих рече: до године у ово доба опет ћу доћи к теби, а Сара ће жена твоја имати сина. А Сара слушаше на вратима од шатора иза њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'А Аврам и Сара бијаху стари и временити, и у Саре бјеше престало што бива у жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Зато се насмија Сара у себи говорећи: пошто сам остарјела, сад ли ће ми доћи радост? а и господар ми је стар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Тада рече Господ Авраму: што се смије Сара говорећи: истина ли је да ћу родити кад сам остарјела?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Има ли што тешко Господу? До године у ово доба опет ћу доћи к теби, а Сара ће имати сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'А Сара удари у бах говорећи: нијесам се смијала. Јер се уплаши. Али он рече: није истина, него си се смијала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Потом усташе људи оданде, и пођоше пут Содома; а Аврам пође с њима да их испрати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'А Господ рече: како бих тајио од Аврама шта ћу учинити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Кад ће од Аврама постати велик и силан народ, и у њему ће се благословити сви народи на земљи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Јер знам да ће заповиједити синовима својима и дому својему након себе да се држе путева Господњих и да чине што је право и добро, да би Господ навршио на Авраму што му је обећао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'И рече Господ: вика је у Содому и Гомору велика, и гријех је њихов грдан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Зато ћу сићи да видим еда ли све чине као што вика дође преда ме; ако ли није тако, да знам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'И људи окренувши се пођоше пут Содома; али Аврам још стајаше пред Господом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'И приступив Аврам рече: хоћеш ли погубити и праведнога с неправедним?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Може бити да има педесет праведника у граду; хоћеш ли и њих погубити, и нећеш опростити мјесту за онијех педесет праведника што су у њему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Немој то чинити, ни губити праведника с неправедником, да буде праведнику као и неправеднику; немој; еда ли судија цијеле земље неће судити право?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'И рече Господ: ако нађем у Содому педесет праведника у граду, опростићу цијелом мјесту њих ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'А Аврам одговори и рече: гле, сада бих проговорио Господу, ако и јесам прах и пепео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Може бити праведника педесет мање пет, хоћеш ли за овијех пет потрти сав град? Одговори: нећу, ако нађем четрдесет и пет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'И стаде даље говорити, и рече: може бити да ће се наћи четрдесет. Рече: нећу ради онијех четрдесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Потом рече: немој се гњевити, Господе, што ћу рећи; може бити да ће се наћи тридесет. И рече: нећу, ако нађем тридесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Опет рече: гле, сада бих проговорио Господу; може бити да ће се наћи двадесет. Рече: нећу их погубити за онијех двадесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Најпослије рече: немој се гњевити, Господе, што ћу још једном проговорити; може бити да ће се наћи десет. Рече: нећу их погубити ради онијех десет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'И Господ отиде свршивши разговор са Аврамом; а Аврам се врати на своје мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'А увече дођоше два анђела у Содом; а Лот сјеђаше на вратима Содомским; и кад их угледа, устаде те их срете, и поклони се лицем до земље,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'И рече: ходите, господо, у кућу слуге својега, и преноћите и оперите ноге своје; па сјутра рано кад устанете пођите својим путем. А они рекоше: не, него ћемо преноћити на улици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Али он навали на њих, те се увратише к њему и уђоше у кућу његову, и он их угости, и испече хљебова пријеснијех, и једоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'И још не бјеху легли, а грађани Содомљани слегоше се око куће, старо и младо, сав народ са свијех крајева,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'И викаху Лота и говораху му: гдје су људи што дођоше синоћ к теби? изведи их к нама да их познамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'А Лот изиде к њима пред врата затворив врата за собом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'И рече им: немојте, браћо, чинити зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Ево имам двије кћери, које још не познаше човјека; њих ћу вам извести, па чините с њима што вам је воља; само не дирајте у оне људе, јер су зато ушли под мој кров.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'А они му рекоше: ходи амо. Па онда рекоше: овај је сам дошао амо да живи као дошљак, па још хоће да нам суди; сад ћемо теби учинити горе него њима. Па навалише јако на човјека, на Лота, и стадоше истављати врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'А она два човјека дигоше руке, и увукоше Лота к себи у кућу, и затворише врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'А људи што бијаху пред вратима кућним уједанпут ослијепише од најмањега до највећега, те не могаху наћи врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Тада она два човјека рекоше Лоту: ако имаш овдје још кога свога, или зета или сина или кћер, или кога год свога у овом граду, гледај нек иду одавде;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Јер хоћемо да затремо мјесто ово, јер је вика њихова велика пред Господом, па нас посла Господ да га затремо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'И изиде Лот, и каза зетовима својим, за које шћаше дати кћери своје, и рече им: устајте, идите из мјеста овога, јер ће сада затрти Господ град овај. Али се зетовима његовијем учини да се шали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'А кад зора забијеље, навалише анђели на Лота говорећи: устани, узми жену своју и двије кћери своје које су ту, да не погинеш у безакоњу града тога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'А он се стаде шчињати, те људи узеше за руку њега и жену његову и двије кћери његове, јер га бјеше жао Господу, и изведоше га и пустише иза града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'И кад их изведоше напоље, рече један: избави душу своју и не обзири се натраг, и у цијелој овој равни да нијеси стао; бјежи на оно брдо да не погинеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'А Лот им рече: немој, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Гле, слуга твој нађе милости пред тобом, и милост је твоја превелика коју ми учини сачувавши ми живот; али не могу утећи на брдо да ме не стигне зло и не погинем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Ено град близу; онамо се може утећи, а мали је; да бјежимо онамо; та мали је, те ћу остати жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'А он му рече: ето послушаћу те и зато, и нећу затрти града, за који рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Брже бјежи онамо; јер не могу чинити ништа док не стигнеш онамо. Зато се прозва онај град Сигор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'И кад сунце ограну по земљи, Лот дође у Сигор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Тада пусти Господ на Содом и на Гомор од Господа с неба дажд од сумпора и огња,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'И затр оне градове и сву ону раван, и све људе у градовима и род земаљски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Али жена Лотова бјеше се обазрела идући за њим, и поста слан камен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'А сјутрадан рано уставши Аврам, отиде на мјесто гдје је стајао пред Господом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'И погледа на Содом и Гомор и сву околину по оној равни, и угледа, а то се дизаше дим од земље као дим из пећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Али кад Бог затираше градове у оној равни, опомену се Бог Аврама, и изведе Лота из пропасти кад затр градове гдје живљаше Лот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'А Лот отиде из Сигора и стани се на оном брду с двије кћери своје, јер се бојаше остати у Сигору; и живљаше у пећини с двије кћери своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'А старија рече млађој: наш је отац стар, а нема никога на земљи да дође к нама као што је обичај по свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Хајде да дамо оцу вина нека се опије, па да легнемо с њим, еда бисмо сачувале сјеме оцу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'И дадоше оцу вина ону ноћ; и дошавши старија леже с оцем својим, и он не осјети ни кад она леже ни кад устаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'А сјутрадан рече старија млађој: гле, ноћас спавах с оцем својим. Да му дамо вина и довече, па иди ти и лези с њим, еда бисмо сачувале сјеме оцу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Па и то вече дадоше оцу вина и уставши млађа леже с њим, и он не осјети ни кад она леже ни кад устаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'И обје кћери Лотове затрудњеше од оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'И старија роди сина, и надједе му име Моав; од њега су Моавци до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Па и млађа роди сина, и надједе му име Вен-Амије; од њега су Амонци до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'А Аврам отиде оданде на југ, и стани се између Кадиса и Сура; и живљаше као дошљак у Герару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'И говораше за жену своју Сару: сестра ми је. А цар Герарски Авимелех посла те узе Сару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Али дође Бог Авимелеху ноћу у сну, и рече му: гле, погинућеш са жене коју си узео, јер има мужа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'А Авимелех не бјеше се ње дотакао, и зато рече: Господе, еда ли ћеш и праведан народ погубити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Није ли ми сам казао: сестра ми је? А и она сама каза: брат ми је. Учинио сам у чистоти срца својега и у правди руку својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Тада му рече Бог у сну: знам да си учинио у чистоти срца својега, зато те сачувах да ми не сагријешиш, и не дадох да је се дотакнеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'А сада врати човјеку жену његову, јер је пророк, и молиће се за те, те ћеш остати жив. Ако ли не вратиш, знај да ћеш умријети ти и сви твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'И ујутру рано уста Авимелех, и сазва све слуге своје, и каза им све ово да чују. И уплашише се људи веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Тада Авимелех дозва Аврама и рече му: шта си нам учинио? шта ли сам ти згријешио, те навуче на ме и на царство моје толико зло? Учинио си ми што не ваља чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'И још рече Авимелех Авраму: шта ти је било, те си то учинио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'А Аврам одговори: вељах: јамачно нема страха Божијега у овом мјесту, па ће ме убити ради жене моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'А управо и јест ми сестра, кћи оца мојега; али није кћи моје матере, па пође за ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'А кад ме Бог изведе из дома оца мојега, ја јој рекох: учини добро, и кажи за ме гдје год дођемо: брат ми је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Тада Авимелех узе оваца и говеда и слуга и слушкиња, те даде Авраму, и врати му Сару жену његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'И рече Авимелех Авраму: ево, земља ти је моја отворена, живи слободно гдје ти је воља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'А Сари рече: ево дао сам твојему брату тисућу сребрника; гле, он ти је очима покривало пред свима који буду с тобом; и то све да ти је за науку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'И Аврам се помоли Богу, и исцијели Бог Авимелеха и жену његову и слушкиње његове, те рађаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Јер Господ бјеше сасвијем затворио сваку материцу у дому Авимелеху ради Саре жене Аврамове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'И Господ походи Сару, као што бјеше рекао, и учини Господ Сари као што бјеше казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Јер затрудње и роди Сара Авраму сина у старости његовој у исто вријеме кад каза Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'И Аврам надједе име сину који му се роди, којега му роди Сара, Исак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'И обреза Аврам сина својега Исака кад би од осам дана, као што му заповједи Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'А Авраму бјеше сто година кад му се роди син Исак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'А Сара рече: Бог ми учини смијех; ко год чује, смијаће ми се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'И рече: ко би рекао Авраму да ће Сара дојити дјецу? ипак му родих сина у старости његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'А кад дијете дорасте да се одбије од сисе, учини Аврам велику гозбу онај дан кад одбише Исака од сисе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'И Сара видје сина Агаре Мисирке, која га роди Авраму, гдје се потсмијева;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Па рече Авраму: отјерај ову робињу са сином њезинијем, јер син ове робиње неће бити нашљедник с мојим сином, с Исаком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'А то Авраму би врло криво ради сина његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Али Бог рече Авраму: немој да ти је криво ради дјетета и ради робиње твоје. Што ти је год казала Сара, послушај; јер ће ти се у Исаку сјеме прозвати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Али ћу и од сина робињина учинити народ, јер је твоје сјеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'И Аврам устав ујутру рано, узе хљеба и мјешину воде, и даде Агари метнувши јој на леђа, и дијете, и отпусти је. А она отишавши луташе по пустињи Вирсавској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'А кад неста воде у мјешини, она баци дијете под једно дрво,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Па отиде колико се може стријелом добацити, и сједе према њему; јер говораше: да не гледам како ће умријети дијете. И сједећи према њему стаде иза гласа плакати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'А Бог чу глас дјетињи, и анђео Божји викну с неба Агару, и рече јој: што ти је, Агаро? не бој се, јер Бог чу глас дјетињи оданде гдје је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Устани, дигни дијете и узми га у наручје; јер ћу од њега учинити велик народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'И Бог јој отвори очи, те угледа студенац; и отишавши напуни мјешину воде, и напоји дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'И Бог бијаше с дјететом, те одрасте, и живљаше у пустињи, и поста стријелац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'А живљаше у пустињи Фарану. И мати га ожени из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'У то вријеме рече Авимелех и Фихол војвода његов Авраму говорећи: Бог је с тобом у свему што радиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Закуни ми се сада Богом да нећеш преварити мене ни сина мојега ни унука мојега, него да ћеш добро онако како сам ја теби чинио и ти чинити мени и земљи у којој си дошљак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'А Аврам рече: хоћу се заклети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Али Аврам прекори Авимелеха за студенац, који узеше на силу слуге Авимелехове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'А Авимелех рече: не знам ко је то учинио; нити ми ти каза, нити чух до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Тада Аврам узе оваца и говеда, и даде Авимелеху, и ухватише вјеру међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'А Аврам одлучи седам јагањаца из стада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'А Авимелех рече Авраму: шта ће оно седам јагањаца што си одлучио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'А он одговори: да примиш из моје руке оно седам јагањаца, да ми буде свједочанство да сам ја ископао овај студенац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Отуда се прозва оно мјесто Вир-Савеја, јер се ондје заклеше обојица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Тако ухватише вјеру на Вирсавеји. Тада се диже Авимелех и Фихол војвода његов, и вратише се у земљу Филистејску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'А Аврам посади луг на Вирсавеји, и ондје призва име Господа Бога вјечнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'И Аврам живљаше као дошљак у земљи Филистејској много времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Послије тога шћаше Бог окушати Аврама, па му рече: Авраме! А он одговори: ево ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'И рече му Бог: узми сада сина својега, јединца својега милога, Исака, па иди у земљу Морију, и спали га на жртву тамо на брду гдје ћу ти казати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'И сјутрадан рано уставши Аврам осамари магарца својега, и узе са собом два момка и Исака сина својега; и нацијепавши дрва за жртву подиже се и пође на мјесто које му каза Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Трећи дан подигавши очи своје Аврам угледа мјесто из далека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'И рече Аврам момцима својим: останите ви овдје с магарцем, а ја и дијете идемо онамо, па кад се помолимо Богу, вратићемо се к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'И узевши Аврам дрва за жртву напрти Исаку сину својему, а сам узе у своје руке огња и нож; па отидоше обојица заједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Тада рече Исак Авраму оцу својему: оче! А он рече: што, сине! И рече Исак: ето огња и дрва, а гдје је јагње за жртву?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'А Аврам одговори: Бог ће се, синко, постарати за јагње себи на жртву. И иђаху обојица заједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'А кад дођоше на мјесто које му Бог каза, Аврам начини ондје жртвеник, и метну дрва на њ, и свезавши Исака сина својега метну га на жртвеник врх дрва;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'И измахну Аврам руком својом и узе нож да закоље сина својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Али анђео Господњи викну га с неба, и рече: Авраме! Авраме! А он рече: ево ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'А анђео рече: не дижи руке своје на дијете, и не чини му ништа; јер сада познах да се бојиш Бога, кад нијеси пожалио сина својега, јединца својега, мене ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'И Аврам подигавши очи своје погледа; и гле, ован иза њега заплео се у чести роговима; и отишавши Аврам узе овна и спали га на жртву мјесто сина својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'И назва Аврам оно мјесто: Господ ће се постарати. Зато се и данас каже: на брду, гдје ће се Господ постарати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'И анђео Господњи опет викну с неба Аврама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'И рече: собом се заклех, вели Господ: кад си тако учинио, и нијеси пожалио сина својега, јединца својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Заиста ћу те благословити и сјеме твоје веома умножити, да га буде као звијезда на небу и као пијеска на бријегу морском; и наслиједиће сјеме твоје врата непријатеља својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'И благословиће се у сјемену твојем сви народи на земљи, кад си послушао глас мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Тада се Аврам врати к момцима својим, те се дигоше, и отидоше заједно у Вирсавеју, јер Аврам живљаше у Вирсавеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Послије тога јавише Авраму говорећи: гле, и Мелха роди синове брату твојему Нахору:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Уза првенца и Вуза брата му, и Камуила, оца Аврамова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'И Хазада и Азава и Фалдеса и Јелдафа и Ватуила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'А Ватуило роди Ревеку. Осам их роди Мелха Нахору брату Аврамову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'И иноча његова, по имену Ревма, роди и она Тавека и Гама и Тохоса и Моха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'А поживје Сара сто и двадесет и седам година; то су године вијека Сарина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'И умрије Сара у Киријат-Арви, а то је Хеврон, у земљи Хананској. И дође Аврам да ожали Сару и оплаче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'А кад уста Аврам од мртваца својега, рече синовима Хетовијем говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Странац сам и дошљак код вас; дајте ми да имам гроб код вас да погребем мртваца својега испред очију својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'А синови Хетови одговорише Авраму говорећи му:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Чуј нас, господару; ти си кнез од Бога међу нама; у најбољем гробу нашем погреби мртваца својега; нико између нас неће ти затворити гроба својега да не погребеш мртваца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Тада уста Аврам и поклони се народу земље оне, синовима Хетовијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'И рече им говорећи: ако хоћете да погребем мртваца својега испред очију својих, послушајте ме, и говорите за мене Ефрону сину Сарову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Нека ми да пећину у Макпели, која је накрај њиве његове; за новце нека ми је да међу вама колико вриједи, да имам гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'А Ефрон сјеђаше усред синова Хетовијех. Па рече Ефрон Хетејин Авраму пред синовима Хетовијем, који слушаху, пред свијем који улажаху на врата града његова, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Не, господару; чуј ме: поклањам ти њиву, и пећину код ње поклањам ти; пред синовима народа својега поклањем ти је, погреби мртваца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'А Аврам се поклони народу земље оне,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'И рече Ефрону пред народом земље оне говорећи: ако си вољан чуј ме; да ти дам шта вриједи њива, узми од мене, па ћу онда погрепсти мртваца својега ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'А Ефрон одговори Авраму говорећи му:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Господару, чуј ме; земља вриједи четири стотине сикала сребра између мене и тебе; шта је то? само ти погреби мртваца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'А Аврам чувши Ефрона измјери му сребро, које рече пред синовима Хетовијем, четири стотине сикала сребра, како су ишли међу трговцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'И њива Ефронова у Макпели према Мамрији, њива с пећином која је на њој, и сва дрвета на њиви и по међи њезиној унаоколо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Поста Аврамова пред синовима Хетовијем, пред свјема који улазе на врата града онога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Потом погребе Аврам Сару жену своју у пећини на њиви Макпели према Мамрији, а то је Хеврон, у земљи Хананској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'И потврдише синови Хетови њиву и пећину на њој Авраму да има гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'А Аврам бјеше стар и временит, и Господ бјеше благословио Аврама у свему;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'И рече Аврам слузи својему најстаријему у кући својој, који бјеше над свијем добром његовијем: метни руку своју под стегно моје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Да те закунем Господом Богом небеским и Богом земаљским да нећеш довести жене сину мојему између кћери овијех Хананеја, међу којима живим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Него да ћеш отићи у земљу моју и у род мој и довести жену сину мојему Исаку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'А слуга му рече: и ако дјевојка не хтједбуде поћи са мном у ову земљу; хоћу ли одвести сина твојега у земљу из које си се иселио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'А Аврам му рече: пази да не одведеш сина мојега онамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Господ Бог небески, који ме је узео из дома оца мојега и из земље рода мојега, и који ми је рекао и заклео ми се говорећи: сјемену ћу твојему дати земљу ову, он ће послати анђела својега пред тобом да доведеш жену сину мојему оданде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Ако ли дјевојка не хтједбуде поћи с тобом, онда да ти је проста заклетва моја; само сина мојега немој одвести онамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'И метну слуга руку своју под стегно Авраму господару својему, и закле му се за ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Тада слуга узе десет камила између камила господара својега да иде, јер све благо господара његова бјеше под његовом руком; и отишав дође у Месопотамију до града Нахорова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'И пусти камиле да полијежу иза града код студенца пред вече кад излазе грађанке да захватају воде;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'И рече: Господе Боже господара мојега Аврама, дај ми срећу данас и учини милост господару мојему Авраму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Ево, ја ћу стајати код овога студенца, а грађанке ће доћи да захватају воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Којој дјевојци речем: нагни крчаг свој да се напијем, а она рече: на пиј, и камиле ћу ти напојити; дај то да буде она коју си намијенио слузи својему Исаку; и по томе да познам да си учинио милост господару мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'И он још не изговори, а то Ревека, кћи Ватуила сина Мелхе жене Нахора брата Аврамова, дође с крчагом на рамену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'И бјеше врло лијепа, још дјевојка, још је човјек не бјеше познао. Она сиђе на извор, и наточи крчаг, и пође;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'А слуга искочи пред њу, и рече; дај ми да се напијем мало воде из крчага твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'А она рече: на пиј, господару. И брже спусти крчаг на руку своју, и напоји га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'И кад га напоји, рече: и камилама ћу твојим налити нека се напију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'И брже изручи крчаг свој у појило, па опет отрча на студенац да налије, и нали свијем камилама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'А човјек јој се дивљаше, и ћуташе, неће ли познати је ли Господ дао срећу путу његову или није.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'А кад се камиле напише, извади човјек златну гривну од по сикла и метну јој око чела, и двије наруквице метну јој на руке од десет сикала злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'И рече: чија си кћи? кажи ми. Има ли у кући оца твојега мјеста за нас да преноћимо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'А она му рече: ја сам кћи Ватуила сина Мелшина, којега роди Нахору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Још рече: има у нас много сламе и пиће и мјеста за ноћиште.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Тада човјек савивши се поклони се Господу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'И рече: благословен да је Господ Бог господара мојега Аврама, што не остави милости своје и вјере своје према господару мојем, и путем доведе ме Господ у дом родбине господара мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'А дјевојка отрча и све ово каза у дому матере своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'А Ревека имаше брата, којему име бјеше Лаван; и истрча Лаван к човјеку на студенац,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Како видје гривну и наруквице на рукама сестре своје и чу гдје Ревека сестра му рече: тако ми каза човјек; дође к човјеку; а он стајаше код камила на студенцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'И рече: ходи, који си благословен од Господа; што би стајао напољу? спремио сам кућу, има мјеста и за камиле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'И доведе човјека у кућу, и растовари камиле; и додаше сламе и пиће камилама, и донесоше воде за ноге њему и људима што бијаху с њим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'И поставише му да једе; али он рече: нећу јести докле не кажем ствар своју. А Лаван му рече: говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Тада рече: ја сам слуга Аврамов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'А Господ је благословио господара мојега веома, те је постао велик, и дао му је оваца и говеда, и сребра и злата, и слуга и слушкиња, и камила и магараца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'И још Сара жена господара мојега роди сина господару мојему у старости његовој, и он му даде све што има.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'А мене закле господар мој говорећи: немој довести сину мојему жене између кћери овијех Хананеја, међу којима живим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Него иди у дом оца мојега и у род мој, да доведеш жену сину мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'А ја рекох господару својему: може бити да дјевојка неће хтјети поћи са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'А он ми рече: Господ, по чијој вољи свагда живљах, послаће анђела својега с тобом, и даће срећу твојему путу да доведеш жену сину мојему од рода мојега, из дома оца мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Онда ће ти бити проста заклетва моја, кад отидеш у род мој; ако ти је и не даду, опет ће ти бити проста заклетва моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'И кад дођох данас на студенац, рекох: Господе Боже господара мојега Аврама, ако си дао срећу путу мојему, којим идем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Ево, ја ћу стајати код студенца: која дјевојка дође да захвати воде, и ја јој кажем: дај ми да се напијем мало воде из крчага твојега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'А она ми одговори: и ти пиј и камилама ћу твојим налити; то нека буде жена коју је намијенио Господ сину господара мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Ја још не изговорих у срцу својем, а дође Ревека с крчагом на рамену, и сишавши на извор захвати; и ја јој рекох: дај ми да се напијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'А она брже спустивши са себе крчаг рече: на пиј, и камиле ћу ти напојити. И кад се напих, напоји и камиле моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'И запитах је говорећи: чија си кћи? а она одговори: ја сам кћи Ватуила сина Нахорова, којега му роди Мелха. Тада јој метнух гривну око чела и наруквице на руке;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'И падох и поклоних се Господу, и захвалих Господу Богу господара мојега Аврама, што ме доведе правијем путем да нађем кћер брата господара својега за сина његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Ако ћете дакле учинити љубав и вјеру господару мојему, кажите ми; ако ли нећете, кажите ми, да идем на десно или на лијево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'А Лаван и Ватуило одговарајући рекоше: од Господа је ово дошло; ми ти не можемо казати ни зло ни добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Ето, Ревека је у твојој власти, узми је па иди, и нека буде жена сину твојега господара, као што каза Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'А кад чу слуга Аврамов ријечи њихове, поклони се Господу до земље;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'И извади закладе сребрне и златне и хаљине, и даде Ревеци; такођер и брату њезину и матери њезиној даде дарове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Потом једоше и пише он и људи који бијаху с њим, и преноћише. А кад ујутру усташе, рече слуга: пустите ме господару мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'А брат и мати њезина рекоше: нека остане дјевојка код нас који дан, барем десет дана, па онда нека иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'А он им рече: немојте ме задржавати, кад је Господ дао срећу мојему путу; пустите ме да идем господару својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Тада рекоше: да зовемо дјевојку, и упитамо шта она вели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'И дозваше Ревеку и рекоше јој: хоћеш ићи с овијем човјеком? А она одговори: хоћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'И пустише Ревеку сестру своју и дојкињу њезину са слугом Аврамовијем и људима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'И благословише Ревеку и рекоше јој: сестро наша, да се намножиш на тисуће тисућа, и сјеме твоје да наслиједи врата својих непријатеља!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'И подиже се Ревека с дјевојкама својим, и посједаше на камиле, и пођоше с човјеком; и слуга узев Ревеку отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'А Исак иђаше враћајући се од студенца живога који ме види (јер живљаше у јужном крају);');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'А бјеше изашао Исак у поље пред вече да се помоли Богу; и подигав очи своје угледа камиле гдје иду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'И Ревека подигавши очи своје угледа Исака, те скочи с камиле,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'И рече слузи: ко је онај човјек што иде преко поља пред нас? А слуга рече: оно је господар мој. И она узе покривало и покри лице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'И приповједи слуга Исаку све што је свршио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'И одведе је Исак у шатор Саре матере своје; и узе Ревеку, и она му поста жена, и омиље му. И Исак се утјеши за матером својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'А Аврам узе другу жену, по имену Хетуру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'И она му роди Зомрана и Јоксана и Мадана и Мадијама и Јесвока и Соијена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'А Јоксан роди Савана и Дедана. А Деданови синови бише Асурим и Латусим и Лаомим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'А синови Мадијамови: Ефар и Афир и Енох и Авида и Елдага. Сви бјеху дјеца Хетурина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'А Аврам даде све што имаше Исаку;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'А синовима својих иноча даде Аврам даре, и оправи их од Исака сина својега још за живота својега на исток, у источни крај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'И вијека Аврамова што поживје бјеше сто и седамдесет и пет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'И онемоћав умрије Аврам у доброј старости, сит живота, и би прибран к роду својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'И погребоше га Исак и Исмаило у пећини Макпелској на њиви Ефрона сина Сара Хетејина, која је према Мамрији;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'На њиви коју купи Аврам од синова Хетовијех, ондје је погребен Аврам са Саром женом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'И по смрти Аврамовој благослови Бог Исака сина његова; а Исак живљаше код студенца живога који ме види.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'А ово је племе Исмаила сина Аврамова, којега роди Авраму Агара Мисирка робиња Сарина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'И ово су имена синова Исмаиловијех, како се зваху у племенима својим; првенац Исмаилов Навајот, па Кидар и Навдеило и Масам,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'И Масма и Дума и Маса,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'И Хадар и Теман и Јетур и Нафес и Кедма.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'То су синови Исмаилови, и то су им имена по селима и градовима њиховијем, дванаест кнезова над својим народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'А године су вијека Исмаилова сто и тридесет и седам година. Послије онемоћав умрије, и би прибран к роду својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'И живљаху од Евилата до Сура према Мисиру, како се иде у Асирију; и допаде му према свој браћи својој да живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'А ово је племе Исака сина Аврамова: Аврам роди Исака;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'А Исаку бјеше четрдесет година кад се ожени Ревеком, кћерју Ватуила Сирина из Месопотамије, сестром Лавана Сирина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'И Исак се мољаше Господу за жену своју, јер бјеше нероткиња; и умоли Господа, те затрудње Ревека жена његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Али удараху једно о друго дјеца у утроби њезиној, те рече: ако је тако, на што сам? И отиде да пита Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'А Господ јој рече: два су племена у утроби твојој, и два ће народа изаћи из тебе; и један ће народ бити јачи од другога народа, и већи ће служити мањему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'И кад дође вријеме да роди, а то близанци у утроби њезиној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'И први изађе црвен, сав као руно рутав, и надјеше му име Исав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'А послије изађе брат му, држећи руком за пету Исава; и надјеше му име Јаков. А бјеше Исаку шездесет година, кад их роди Ревека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'И дјеца одрастоше, и Исав поста ловац и ратар, а Јаков бјеше човјек кротак и бављаше се у шаторима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'И Исак миловаше Исава, јер радо јеђаше лова његова; а Ревека миловаше Јакова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Једном Јаков скуха јело, а Исав дође из поља уморан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'И рече Исав Јакову: дај ми да једем тога јела црвенога, јер сам уморан. Отуда се прозва Едом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'А Јаков му рече: продај ми данас првенаштво своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'А Исав одговори: ево, хоћу да умрем, па што ће ми првенаштво?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'А Јаков рече: закуни ми се данас. И он му се закле; тако продаде своје првенаштво Јакову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'И Јаков даде Исаву хљеба и скуханога лећа, и он се наједе и напи, па уста и отиде. Тако Исав није марио за првенаштво своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Али наста глад у земљи сврх прве глади која бјеше за времена Аврамова; и Исак отиде к Авимелеху цару Филистејском у Герар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'И јави му се Господ и рече: немој ићи у Мисир, него сједи у земљи коју ћу ти казати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Сједи у тој земљи, и ја ћу бити с тобом, и благословићу те; јер ћу теби и сјемену твојему дати све ове земље, и потврдићу заклетву, којом сам се заклео Авраму оцу твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'И умножићу сјеме твоје да га буде као звијезда на небу, и даћу сјемену твојему све ове земље; и у сјемену твојем благословиће се сви народи на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Зато што је Аврам слушао глас мој и чувао наредбу моју, заповјести моје и правила моја и законе моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'И оста Исак у Герару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'А људи у мјесту оном питаху за жену његову, а он говораше: сестра ми је. Јер се бојаше казати: жена ми је; да ме, вели, не убију ови људи ради Ревеке, јер је лијепа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'И кад проведе много времена ондје, догоди се, те погледа Авимелех цар Филистејски с прозора, и видје Исака гдје се шали с Ревеком женом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'И дозва Авимелех Исака и рече: та то ти је жена; како си казао: сестра ми је? А Исак му одговори: рекох: да не погинем с ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'А Авимелех рече: шта си нам учинио? Лако је могао ко од народа овога лећи с твојом женом, те би нас ти увалио у гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'И заповједи Авимелех свему народу својему говорећи: ко се дотакне овога човјека или жене његове, погинуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'И Исак стаде сијати у оној земљи, и доби оне године по сто, тако га благослови Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'И обогати се човјек, и напредоваше све већма, те поста силан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'И имаше оваца и говеда и много слуга; а Филистеји му завиђаху,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Па све студенце које бјеху ископале слуге оца његова за времена Аврама оца његова заронише Филистеји, и засуше их земљом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'И Авимелех рече Исаку: иди од нас, јер си постао силнији од нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'И Исак отиде оданде, и разапе шаторе у долини Герарској, и настани се ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'И стаде Исак откопавати студенце, који бјеху ископани за времена Аврама оца његова, и које заронише Филистеји по смрти Аврамовој; и прозва их именима која им бјеше надио отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'И копајући слуге Исакове у оном долу нађоше студенац живе воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Али се свадише пастири Герарски с пастирима Исаковим говорећи: наша је вода. И надједе име оном студенцу Есек, јер се свадише с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Послије ископаше други студенац, па се и око њега свадише, зато га назва Ситна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Тада се подиже оданде, и ископа други студенац, и око њега не би свађе; зато га назва Реховот, говорећи: сад нам даде Господ простора да растемо у овој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'И отиде оданде горе у Вирсавеју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'И исту ноћ јави му се Господ, и рече: ја сам Бог Аврама оца твојега. Не бој се, јер сам ја с тобом, и благословићу те и умножићу сјеме твоје Аврама ради слуге својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'И начини ондје жртвеник, и призва име Господње; и ондје разапе шатор свој; и слуге Исакове ископаше ондје студенац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'И дође к њему Авимелех из Герара с Охозатом пријатељем својим и с Филохом војводом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'А Исак им рече: што сте дошли к мени, кад мрзите на ме и отјерасте ме од себе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'А они рекоше: видјесмо заиста да је Господ с тобом, па рекосмо: нека буде заклетва између нас, између нас и тебе; хајде да ухватимо вјеру с тобом:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Да нам не чиниш зла, као што се ми тебе не дотакосмо и као што ми теби само добро чинисмо, и пустисмо те да идеш на миру, и ето си благословен од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Тада их он угости; те једоше и пише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'А сјутрадан уставши рано, заклеше се један другоме, и отпусти их Исак и отидоше од њега с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Исти дан дошавши слуге Исакове казаше му за студенац који ископаше, и рекоше му: нађосмо воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'И назва га Савеја; отуда се зове град онај Вирсавеја до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'А кад би Исаву четрдесет година, узе за жену Јудиту кћер Веоха Хетејина, и Васемату кћер Елона Хетејина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'И оне задаваху много јада Исаку и Ревеци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Кад Исак остарје и очи му потамњеше, те не виђаше, дозва Исава старијега сина својега, и рече му: сине! А он одговори: ево ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Тада рече: ево остарио сам, не знам кад ћу умријети;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Узми оружје своје, тул и лук, и изиди у планину, те ми улови лова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'И зготиви ми јело по мојој вољи, и донеси ми да једем, па да те благослови душа моја док нијесам умро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'А Ревека чу шта Исак рече сину својему Исаву. И Исав отиде у планину да улови лова и донесе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'А Ревека рече Јакову сину својему говорећи: гле, чух оца твојега, гдје бесједи с Исавом братом твојим и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Донеси ми лова, и зготови јело да једем, па да те благословим пред Господом док нијесам умро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Него сада, сине, послушај ме што ћу ти казати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Иди сада к стаду и донеси два добра јарета, да зготовим оцу твојему јело од њих, како радо једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Па ћеш унијети оцу да једе и да те благослови док није умро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'А Јаков рече Ревеци матери својој: али је Исав брат мој рутав, а ја сам гладак;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Може ме опипати отац, па ће се осјетити да сам га хтио преварити, те ћу навући на се проклетство мјесто благослова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'А мати му рече: нека проклетство твоје, сине, падне на мене; само ме послушај, и иди и донеси ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Тада отишав узе и донесе матери својој; а мати његова зготови јело како јеђаше радо отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Па онда узе Ревека најљепше хаљине старијега сина својега, које бијаху у ње код куће, и обуче Јакова млађега сина својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'И јарећим кожицама обложи му руке и врат гдје бјеше гладак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'И даде Јакову сину својему у руке јело и хљеб што зготови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'А он уђе к оцу својему и рече: оче. А он одговори: ево ме; који си ти, сине?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'И Јаков рече оцу својему: ја, Исав твој првенац; учинио сам како си ми рекао; дигни се, посади се да једеш лова мојега, па да ме благослови душа твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'А Исак рече сину својему: кад брже нађе, сине? А он рече: Господ Бог твој даде, те изађе преда ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Тада рече Исак Јакову: ходи ближе, сине да те опипам јеси ли син мој Исав или не.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'И приступи Јаков к Исаку оцу својему, а он га опипа, па рече: глас је Јаковљев, али руке су Исавове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'И не позна га, јер му руке бјеху као у Исава брата његова рутаве; зато га благослови;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'И рече му: јеси ли ти син мој Исав? А он одговори: ја сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Тада рече: а ти дај сине, да једем лова твојега, па да те благослови душа моја. И даде му, те једе; па му донесе и вина, те пи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Потом Исак отац његов рече му: ходи сине, цјелуј ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'И он приступи и цјелива га; а Исак осјети мирис од хаљина његовијех, и благослови га говорећи: гле, мирис сина мојега као мирис од поља које благослови Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Бог ти дао росе небеске, и добре земље и пшенице и вина изобила!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Народи ти служили и племена ти се клањала! Био господар браћи својој и клањали ти се синови матере твоје! Проклет био који тебе успроклиње а благословен који тебе узблагосиља!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'А кад Исак благослови Јакова, и Јаков отиде испред Исака оца својега, у тај час дође Исав брат његов из лова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Па зготови и он јело и унесе оцу својему, и рече му: устани, оче, да једеш што ти је син уловио, па да ме благослови душа твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'А Исак отац његов рече му: ко си ти? А он рече: ја, син твој, првенац твој Исав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Тада се препаде Исак, и рече: ко? да гдје је онај који улови и донесе ми лова, и од свега једох прије него ти дође, и благослових га? он ће и остати благословен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'А кад чу Исав ријечи оца својега, вриште иза гласа и ожалости се веома, и рече оцу својему: благослови и мене, оче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'А он му рече: дође брат твој с пријеваром, и однесе твој благослов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'А Исав рече: право је што му је име Јаков, јер ме већ другом превари. Првенаштво ми узе, па ето сада ми узе и благослов. Потом рече: нијеси ли и мени оставио благослов?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'А Исак одговори, и рече Исав: ето сам га поставио теби за господара; и сву браћу његову дадох му да му буду слуге; пшеницом и вином укријепих га; па шта бих сада теби учинио, сине?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'И Исав рече оцу својему: еда ли је само један благослов у тебе, оче? благослови и мене, оче. И стаде иза гласа плакати Исав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'А Исак отац његов одговарајући рече му: ево, стан ће ти бити на родној земљи и роси небеској озго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Али ћеш живјети од мача својега, и брату ћеш својему служити; али ће доћи вријеме, те ћеш пошто се наплачеш скршити јарам његов с врата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'И Исав омрзе љуто на Јакова ради благослова, којим га благослови отац, и говораше у срцу својем: близу су жалосни дани оца мојега, тада ћу убити Јакова брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'И казаше Ревеци ријечи Исава сина њезина старијега, а она пославши дозва Јакова млађега сина својега, и рече му: гле, Исав брат твој тјеши се тијем што хоће да те убије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Него, сине, послушај што ћу ти казати; устани и бјежи к Лавану брату мојему у Харан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'И остани код њега неко вријеме докле прође срдња брата твојега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Докле се гњев брата твојега одврати од тебе, те заборави што си му учинио; а онда ћу ја послати да те доведу оданде. Зашто бих остала без обојице вас у један дан?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'А Исаку рече Ревека: омрзао ми је живот ради овијех Хетејака. Ако се Јаков ожени Хетејком, каком између кћери ове земље, да што ми живот?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Тада Исак дозва Јакова, и благослови га, и заповједи му и рече: немој да се ожениш којом између кћери Хананејских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Устани, иди у Падан-Арам у дом Ватуила оца матере своје, и оданде се ожени између кћери Лавана ујака својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'А Бог свемогући да те благослови, и да ти да велику породицу и умножи те, да од тебе постане мноштво народа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'И да ти да благослов Аврамов, теби и сјемену твојему с тобом, да наслиједиш земљу у којој си дошљак, коју Бог даде Авраму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Тако оправи Исак Јакова, и он пође у Падан-Арам к Лавану сину Ватуила Сирина, брату Ревеке матере Јаковљеве и Исавове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'А Исав видје гдје Исак благослови Јакова и оправи га у Падан-Арам да се оданде ожени, и гдје благосиљајући га заповједи му и рече: немој да се ожениш којом између кћери Хананејских,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'И гдје Јаков послуша оца својега и матер своју, и отиде у Падан-Арам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'И видје Исав да кћери Хананејске нијесу по вољи Исаку оцу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Па отиде Исав к Исмаилу, и узе за жену преко жена својих Маелету, кћер Исмаила сина Аврамова, сестру Навајотову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'А Јаков отиде од Вирсавеје идући у Харан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'И дође на једно мјесто, и ондје заноћи, јер сунце бјеше зашло; и узе камен на оном мјесту, и метну га себи под главу, и заспа на оном мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'И усни, а то љестве стајаху на земљи а врхом тицаху у небо, и гле, анђели Божји по њима се пењаху и слажаху;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'И гле, на врху стајаше Господ, и рече: ја сам Господ Бог Аврама оца твојега и Бог Исаков; ту земљу на којој спаваш теби ћу дати и сјемену твојему;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'И сјемена ће твојега бити као праха на земљи, те ћеш се раширити на запад и на исток и на сјевер и на југ, и сви народи на земљи благословиће се у теби и у сјемену твојем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'И ево, ја сам с тобом, и чуваћу те куда год пођеш, и довешћу те натраг у ову земљу, јер те нећу оставити докле год не учиним што ти рекох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'А кад се Јаков пробуди од сна, рече: зацијело је Господ на овом мјесту; а ја не знах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'И уплаши се, и рече: како је страшно мјесто ово! овдје је доиста кућа Божја, и ово су врата небеска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'И уста Јаков ујутру рано, и узе камен што бјеше метнуо себи под главу, и утврди га за спомен и прели га уљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'И прозва оно мјесто Ветиљ, а пређе бјеше име ономе граду Луз.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'И учини Јаков завјет, говорећи: ако Бог буде са мном и сачува ме на путу којим идем и да ми хљеба да једем и одијела да се облачим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'И ако се вратим на миру у дом оца својега, Господ ће ми бити Бог;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'А камен овај који утврдих за спомен биће дом Божји; и што ми год даш, од свега ћу десето дати теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Тада се подиже Јаков и отиде у земљу источну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'И обзирући се угледа студенац у пољу; и гле, три стада оваца лежаху код њега, јер се на оном студенцу појаху стада, а велики камен бијаше студенцу на вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Ондје се скупљаху сва стада, те пастири одваљиваху камен с врата студенцу и појаху стада, и послије опет приваљиваху камен на врата студенцу на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'И Јаков им рече: браћо, одакле сте? Рекоше: из Харана смо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'А он им рече: познајете ли Лавана сина Нахорова? Они рекоше: познајемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Он им рече: је ли здрав? Рекоше: јест, и ево Рахиље кћери његове, гдје иде са стадом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'И он рече: ето још је рано, нити је вријеме враћати стоку; напојте стоку па идите и пасите је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'А они рекоше: не можемо, докле се не скупе сва стада, да одвалимо камен с врата студенцу, онда ћемо напојити стоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Док он још говораше с њима, дође Рахиља са стадом оца својега, јер она пасијаше овце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'А кад Јаков видје Рахиљу кћер Лавана ујака својега, и стадо Лавана ујака својега, приступи Јаков и одвали камен студенцу с врата, и напоји стадо Лавана ујака својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'И пољуби Јаков Рахиљу, и повикавши заплака се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'И каза се Јаков Рахиљи да је род оцу њезину и да је син Ревечин; а она отрча те јави оцу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'А кад Лаван чу за Јакова сина сестре своје, истрча му на сусрет, и загрли га и пољуби, и уведе у своју кућу. И он приповједи Лавану све ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'А Лаван му рече: та ти си кост моја и тијело моје. И оста код њега цио мјесец дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Тада рече Лаван Јакову: зар бадава да ми служиш, што си ми род? Кажи ми шта ће ти бити плата?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'А Лаван имаше двије кћери: старијој бјеше име Лија, а млађој Рахиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'И у Лије бјеху кварне очи, а Рахиља бјеше лијепа стаса и лијепа лица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'И Јакову омиље Рахиља, те рече: служићу ти седам година за Рахиљу, млађу кћер твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'А Лаван му рече: боље теби да је дам него другом; остани код мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'И отслужи Јаков за Рахиљу седам година, и учинише му се као неколико дана, јер је љубљаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'И рече Јаков Лавану: дај ми жену, јер ми се наврши вријеме, да легнем с њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'И сазва Лаван све људе из онога мјеста и учини гозбу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'А увече узе Лију кћер своју и уведе је к Јакову, и он леже с њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'И Лаван даде Зелфу робињу своју Лији кћери својој да јој буде робиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'А кад би ујутру, гле, оно бјеше Лија; те рече Јаков Лавану: шта си ми то учинио? не служим ли за Рахиљу код тебе? зашто си ме преварио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'А Лаван му рече: не бива у нашем мјесту да се уда млађа прије старије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Наврши недјељу дана с том, па ћемо ти дати и другу за службу што ћеш служити код мене још седам година других.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Јаков учини тако, и наврши с њом недјељу дана, па му даде Лаван Рахиљу кћер своју за жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'И даде Лаван Рахиљи кћери својој робињу своју Валу да јој буде робиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'И тако леже Јаков с Рахиљом; и вољаше Рахиљу него Лију, и стаде служити код Лавана још седам других година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'А Господ видећи да Јаков не мари за Лију, отвори њојзи материцу, а Рахиља оста нероткиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'И Лија затрудње, и роди сина, и надједе му име Рувим, говорећи: Господ погледа на јаде моје, сада ће ме љубити муж мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'И опет затрудње, и роди сина и рече: Господ чу да сам презрена, па ми даде и овога. И надједе му име Симеун.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'И опет затрудње, и роди сина, и рече: да ако се сада већ приљуби к мени муж мој, кад му родих три сина. Зато му надјеше име Левије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'И затрудње опет, и роди сина, и рече: сада ћу хвалити Господа. Зато му надједе име Јуда; и преста рађати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'А Рахиља видјевши гдје не рађа дјеце Јакову, позавидје сестри својој; и рече Јакову: дај ми дјеце, или ћу умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'А Јаков се расрди на Рахиљу, и рече: зар сам ја а не Бог који ти не да порода?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'А она рече: ето робиње моје Вале, лези с њом, нека роди на мојим кољенима, па ћу и ја имати дјеце од ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'И даде му Валу робињу своју за жену, и Јаков леже с њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'И затрудње Вала, и роди Јакову сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'А Рахиља рече: Господ ми је судио и чуо глас мој, те ми даде сина. Зато му надједе име Дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'И Вала робиња Рахиљина затрудње опет, и роди другога сина Јакову;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'А Рахиља рече: борах се жестоко са сестром својом, али одољех. И надједе му име Нефталим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'А Лија видјевши гдје преста рађати узе Зелфу робињу своју и даде је Јакову за жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'И роди Зелфа робиња Лијина Јакову сина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'И Лија рече: дође чета. И надједе му име Гад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Опет роди Зелфа робиња Лијина другога сина Јакову;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'И рече Лија: благо мени, јер ће ме блаженом звати жене. Зато му надједе име Асир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'А Рувим изиде у вријеме жетве пшеничне и нађе мандрагору у пољу, и донесе је Лији матери својој. А Рахиља рече Лији: дај ми мандрагору сина својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'А она јој рече: мало ли ти је што си ми узела мужа? хоћеш да ми узмеш и мандрагору сина мојега? А Рахиља јој рече: нека ноћас спава с тобом за мандрагору сина твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'И увече кад се Јаков враћаше из поља, изиде му Лија на сусрет и рече: спаваћеш код мене, јер те купих за мандрагору сина својега. И спава код ње ону ноћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'А Бог услиши Лију, те она затрудње, и роди Јакову петога сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'И рече Лија: Господ ми даде плату моју што дадох робињу своју мужу својему. И надједе му име Исахар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'И затрудње Лија опет, и роди Јакову шестога сина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'И рече Лија: дарива ме Господ даром добријем; да ако се сада већ приљуби к мени муж мој, јер му родих шест синова. Зато му надједе име Завулон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Најпослије роди кћер, и надједе јој има Дина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Али се Господ опомену Рахиље; и услишив је отвори јој материцу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'И затрудње, и роди сина, и рече: узе Бог срамоту моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'И надједе му име Јосиф, говорећи: нека ми дода Господ још једнога сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'А кад Рахиља роди Јосифа, рече Јаков Лавану: пусти ме да идем у своје мјесто и у своју земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Дај ми жене моје, за које сам ти служио, и дјецу моју, да идем, јер знаш како сам ти служио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'А Лаван му рече: немој, ако сам нашао милост пред тобом; видим да ме је благословио Господ тебе ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'И још рече: ишти колико хоћеш плате, и ја ћу ти дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'А Јаков му одговори: ти знаш како сам ти служио и каква ти је стока постала код мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Јер је мало било што си имао докле ја не дођох; али се умножи веома, јер те Господ благослови кад ја дођох. Па кад ћу и ја тако себи кућу кућити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'И рече му Лаван: шта хоћеш да ти дам? А Јаков одговори: не треба ништа да ми даш; него ћу ти опет пасти стоку и чувати, ако ћеш ми учити ово:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Да зађем данас по свој стоци твојој, и одлучим све што је шарено и с биљегом, и све што је црно између оваца, и што је с биљегом и шарено између коза, па што послије буде тако, оно да ми је плата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Тако ће ми се послије посвједочити правда моја пред тобом кад дођеш да видиш заслугу моју: што год не буде шарено ни с биљегом ни црно између оваца и коза у мене, биће крадено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'А Лаван рече: ето, нека буде како си казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'И одлучи Лаван исти дан јарце с биљегом и шарене и све козе с биљегом и шарене, и све на чем бијаше што бијело, и све црно између оваца, и предаде синовима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'И остави даљине три дана хода између себе и Јакова. И Јаков пасијаше осталу стоку Лаванову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'И узе Јаков зеленијех прутова тополовијех и љесковијех и кестеновијех, и нагули их до бјелине која бјеше на прутовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'И меташе нагуљене прутове пред стоку у жљебове и корита кад долажаше стока да пије, да би се упаљивала кад дође да пије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'И упаљиваше се стока гледајући у прутове, и што се млађаше бијаше с биљегом, прутасто и шарено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'И Јаков одлучиваше млад, и обраћаше стадо Лаваново да гледа у шарене и у све црне; а своје стадо одвајаше и не обраћаше га према стаду Лаванову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'И кад се год упаљиваше стока рана, меташе Јаков прутове у корита пред очи стоци да би се упаљивала гледајући у прутове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'А кад се упаљиваше позна стока, не меташе; тако позне биваху Лаванове а ране Јаковљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'И тако се тај човјек обогати врло, те имаше много стоке и слуга и слушкиња и камила и магараца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'А Јаков чу гдје синови Лаванови говоре: Јаков узе све што бјеше нашега оца, и од онога што бјеше нашега оца стече све ово благо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'И видје Јаков гдје лице Лаваново није према њему као прије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'И Господ рече Јакову: врати се у земљу отаца својих и у род свој, и ја ћу бити с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'И послав Јаков дозва Рахиљу и Лију у поље к стаду својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'И рече им: видим гдје лице оца вашега није према мени као прије; али је Бог оца мојега био са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'И ви знате да сам служио оцу вашему како сам год могао;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'А отац ме је ваш варао и мијењао ми плату десет пута; али му Бог не даде да ме оштети;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Кад он рече: што буде шарено нека ти је плата, онда се младило све шарено; а кад рече: с биљегом што буде нека ти је плата, онда се младило све с биљегом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Тако Бог узе стоку оцу вашему и даде је мени;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Јер кад се упаљиваше стока, подигох очи своје и видјех у сну, а то овнови и јарци што скачу на овце и козе бијаху шарени, с биљегама прутастим и коластим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'А анђео Господњи рече ми у сну: Јакове! А ја одговорих: ево ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'А он рече: подигни сад очи своје и гледај, овнови и јарци што скачу на овце и козе, шарени су, с биљегама прутастим и коластим; јер видјех све што ти чини Лаван.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ја сам Бог од Ветиља, гдје си прелио камен и учинио ми завјет; устани сада и иди из ове земље, и врати се на постојбину своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Тада одговори Рахиља и Лија, и рекоше му: еда ли још имамо какав дио и нашљедство у дому оца својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Није ли нас држао као туђинке кад нас је продао? па је још и наше новце једнако јео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Јер све ово благо што узе Господ оцу нашему, наше је и наше дјеце. Зато чини све што ти је Господ казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'И подиже се Јаков, и метну дјецу своју и жене своје на камиле;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'И одведе сву стоку своју и све благо што бјеше стекао, стоку коју бјеше стекао у Падан-Араму, и пође к Исаку оцу својему у земљу Хананску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'А Лаван бјеше отишао да стриже овце своје; и Рахиља украде идоле оцу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'И Јаков отиде крадом од Лавана Сирина не јавивши му да хоће да иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'И побјеже са свијем благом својим, и подиже се те пријеђе преко воде, и упути се ка гори Галаду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'А трећи дан јавише Лавану да је побјегао Јаков.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'И узе са собом браћу своју, и пође за њим у потјеру, и за седам дана стиже га на гори Галаду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Али Бог дође Лавану Сирину ноћу у сну, и рече му: чувај се да не говориш с Јаковом ни лијепо ни ружно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'И стиже Лаван Јакова; а Јаков бјеше разапео шатор свој на гори, па и Лаван такођер разапе свој с браћом својом на гори Галаду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'И Лаван рече Јакову: шта учини те крадом побјеже од мене и одведе кћери моје као на мач отете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Зашто тајно побјеже и крадом отиде од мене? нити ми рече да те испратим с весељем и с пјесмама, с бубњима и гуслама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Нити ми даде да изљубим синове своје и кћери своје? лудо си радио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Могао бих вам досадити; али Бог оца вашега ноћас ми рече говорећи: чувај се да не говориш с Јаковом ни лијепо ни ружно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Иди дакле кад си се тако ужелио куће оца својега; али зашто украде богове моје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'А Јаков одговори и рече: бојах се и мишљах: хоћеш силом отети кћери своје од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'А богове своје у кога нађеш, онај нека не живи више; пред нашом браћом тражи што је твоје у мене, па узми. Јер Јаков није знао да их је украла Рахиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'И уђе Лаван у шатор Јаковљев и у шатор Лијин и у шатор двију робиња, и не нађе их; и изашав из шатора Лијина уђе у шатор Рахиљин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'А Рахиља узе идоле и сакри их под самар камиле своје и сједе озго; и Лаван пипаше по цијелом шатору, и не нађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'А она рече оцу својему: немој се срдити, господару, што ти не могу устати, јер ми је што у жена бива. Тражив дакле не нађе идола својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'И Јаков се расрди, и стаде корити Лавана, и говорећи рече му: шта сам учинио, шта сам скривио, те си ме тако жестоко тјерао?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Пипао си сав пртљаг мој, па шта си нашао из своје куће? дај овамо пред моју и своју браћу, нека расуде између нас двојице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Ево двадесет година бијах код тебе: овце твоје и козе твоје не јаловише се, а овнова из стада твојега не једох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Што би звијерје заклало нијесам ти доносио, сам сам подмиривао; од мене си искао што би ми било украдено дању или ноћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Дању ме убијаше врућина а ноћу мраз; и сан ми не падаше на очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Тако ми је био двадесет година у твојој кући; служио сам ти четрнаесет година за двије кћери твоје и шест година за стоку твоју, и плату си ми мијењао десет пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Да није Бог оца мојега, Бог Аврамов, и страх Исаков био са мном, би ме зацијело отпустио празна. Али је Бог видио невољу моју и труд руку мојих, па те укори ноћас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'А Лаван одговори Јакову и рече: ове су кћери моје кћери, и ови су синови моји синови, и ова стока моја стока, и што год видиш све је моје; па шта бих учинио данас кћерима својим или синовима њиховијем које родише?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Него хајде да ухватимо вјеру, ја и ти, да буде свједочанство између мене и тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'И Јаков узе камен и утврди га за спомен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'И рече Јаков браћи својој: накупите камења. И накупише камења и сложише на гомилу, и једоше на гомили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'И Лаван га назва Јегар-Сахадут, а Јаков га назва Галед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'И рече Лаван: ова гомила нека буде свједок између мене и тебе данас. Зато се прозва Галед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'А прозва се и Миспа, јер рече Лаван: нека Господ гледа између мене и тебе, кад не узможемо видјети један другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Ако уцвијелиш кћери моје и ако узмеш жене преко мојих кћери, неће човјек бити између нас, него гле Бог свједок између мене и тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'И још рече Лаван Јакову: гледај ову гомилу и гледај овај споменик, који подигох између себе и тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Свједок је ова гомила и свједок је овај споменик: да ни ја нећу пријећи преко ове гомиле к теби ни ти к мени да нећеш пријећи преко ове гомиле и споменика овога на зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Бог Аврамов и богови Нахорови, богови оца њихова, нека суде међу нама. А Јаков се закле страхом оца својега Исака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'И Јаков принесе жртву на гори, и сазва браћу своју на вечеру; и једоше па ноћише на гори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'А ујутру рано уста Лаван, и изљуби своју унучад и кћери своје, и благослови их, па отиде, и врати се у своје мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'А Јаков отиде својим путем; и сретоше га анђели Божији;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'А кад их угледа Јаков, рече: ово је око Божји. И прозва оно мјесто Маханаим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'И Јаков посла пред собом гласнике к Исаву брату својему у земљу Сир, крајину Едомску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'И заповједи им говорећи: овако кажите господару мојему Исаву: слуга твој Јаков овако каже: био сам дошљак код Лавана и бавио се досад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'А имам волова и магараца, оваца и слуга и слушкиња, и послах да јавим теби господару својему, еда бих нашао милост пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'И вратише се гласници к Јакову и рекоше му: идосмо до брата твојега Исава, и ето он ти иде на сусрет с четири стотине момака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'А Јаков се уплаши јако и забрину се; па раздијели своје људе и овце и говеда и камиле у двије чете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'И рече: ако Исав удари на једну чету и разбије је, да ако друга утече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'И рече Јаков: Боже оца мојега Аврама и Боже оца мојега Исака, Господе, који си ми казао: врати се у земљу своју и у род свој, и ја ћу ти бити добротвор!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Нијесам вриједан толике милости и толике вјере што си учинио слузи својему; јер само са штапом својим пријеђох преко Јордана, а сада сам господар од двије чете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Избави ме из руке брата мојега, из руке Исавове, јер се бојим да не дође и убије мене и матер с дјецом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'А ти си казао: заиста ја ћу ти бити добротвор, и учинићу сјеме твоје да буде као пијеска морскога, који се не може избројити од множине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'И заноћи ондје ону ноћ, и узе што му дође до руке, да пошље на дар Исаву брату својему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Двјеста коза с двадесет јараца, двјеста оваца с двадесет овнова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Тридесет камила дојилица с камиладима, четрдесет крава с десеторо телади, двадесет магарица с десеторо магаради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'И предаде их слугама својим, свако стадо напосе, и рече слугама: идите напријед преда мном, остављајући доста мјеста између једнога стада и другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'И заповједи првому говорећи: кад сретеш Исава брата мојега, па те запита: чији си? и куда идеш? и чије је то што гониш пред собом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'А ти реци: слуге твојега Јакова, а ово шаље на дар господару својему Исаву, а ето и сам иде за нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Тако заповједи и другому и трећему и свијема који иђаху за стадом, и рече: тако кажите Исаву кад наиђете на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'И још кажите: ето, Јаков слуга твој иде за нама. Јер говораше: ублажићу га даром који иде преда мном, па ћу му онда видјети лице, да ако ме лијепо прими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Тако отиде дар напријед, а он преноћи ону ноћ код чете своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'И по ноћи уста, и узе обје жене и двије робиње и једанаесторо дјеце своје; и преброди брод Јавок.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'А пошто њих узе и преведе преко потока, претури и остало што имаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'А кад оста Јаков сам, тада се један човјек рваше с њим до зоре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'И кад видје да га не може свладати, удари га по зглавку у стегну, те се Јакову ишчаши стегно из зглавка, кад се човјек рваше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Па онда рече: пусти ме, зора је. А Јаков му рече: нећу те пустити докле ме не благословиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'А човјек му рече: како ти је име. А он одговори: Јаков.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Тада му рече: отселе се нећеш звати Јаков, него Израиљ; јер си се јуначки борио и с Богом и с људима, и одолио си.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'А Јаков запита и рече: кажи ми како је теби име. А он рече: што питаш како ми је име? И благослови га ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'И Јаков надједе име оному мјесту Фануил; јер, вели, Бога видјех лицем к лицу, и душа се моја избави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'И сунце му се роди кад прође Фануил, и храмаше на стегно своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Зато синови Израиљеви не једу крајева од мишића на зглавку у стегну до данашњега дана, што се Јакову повриједише крајеви од мишића на зглавку у стегну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'А Јаков подигав очи своје погледа, а то Исав иде, и четири стотине људи с њим. И раздијели дјецу уз Лију и уз Рахиљу и уз двије робиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'И намјести напријед робиње и њихову дјецу, па Лију и њезину дјецу за њима, а најпослије Рахиљу и Јосифа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'А сам прође напријед, и поклони се до земље седам пута докле дође до брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'А Исав притрча преда њ и загрли га и паде му око врата и цјелива га, и обојица се заплакаше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'И Исав подигав очи угледа жене и дјецу, па рече: ко су ти оно? А Јаков рече: дјеца, коју Бог милостиво дарова слузи твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'И приступише робиње с дјецом својом, и поклонише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Потом приступи и Лија и дјеца њезина, и поклонише се; а најпослије приступи Јосиф и Рахиља, и поклонише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'А Исав рече: шта ће ти читава војска она коју сретох? А он рече: да нађем милост пред господаром својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'А Исав рече: има, брате, у мене доста; нека теби што је твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'А Јаков рече: не; ако сам сада нашао милост пред тобом, прими дар из моје руке, јер видјех лице твоје као да видјех лице Божје, тако си ме лијепо дочекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Прими дар мој, који ти је доведен; јер ме је обилато обдарио Бог, и имам свега. И навали на њ, те прими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Послије рече Исав: хајде да идемо, ићи ћу и ја с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'А Јаков му рече: зна господар мој да су ова дјеца нејака, и имам оваца и крава дојилица, па ако их устјерам један дан, погинући ми све стадо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Него господар мој нека иде пред слугом својим, а ја ћу полако ићи колико могу дјеца и стока, докле дођем ка господару својему у Сир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'А Исав рече: а оно да ти оставим неколико људи што су са мном. А он рече: нашто? дај да нађем милост пред господаром својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'И тако Исав врати се исти дан својим путем у Сир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'А Јаков отиде у Сокот, и ондје начини себи кућу а стоци својој начини стаје; зато назва оно мјесто Сокот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Послије дође Јаков здраво у град Сихем у земљи Хананској, вратив се из Падан-Арама, и намјести се према граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'И купи комад земље, гдје разапе шатор свој, од синова Емора оца Сихемова за сто новаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'И начини ондје жртвеник, и назва га: Силни Бог Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'А Дина кћи Лијина, коју роди Јакову, изађе да гледа дјевојке у оном крају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'А угледа је Сихем, син Емора Евејина, кнеза од оне земље, и узе је и леже с њом и осрамоти је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'И приону срце његово за Дину кћер Јаковљеву, и дјевојка му омиље, и он јој се умиљаваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'И рече Сихем Емору оцу својему говорећи: ожени ме овом дјевојком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'А Јаков чу да је осрамотио Дину кћер његову; а синови његови бијаху у пољу са стоком његовом, и Јаков оћутје докле они не дођу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'А Емор отац Сихемов изиде к Јакову да се разговори с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'А кад дођоше синови Јаковљеви из поља и чуше шта је било, жао би људима врло и разгњевише се веома, што учини срамоту Израиљу облежав кћер Јаковљеву, како не би ваљало чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Тада им рече Емор говорећи: син мој Сихем срцем приону за вашу кћер; подајте му је за жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'И опријатељите се с нама; кћери своје удајите за нас и кћерима нашим жените се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Па живите с нама, и земља ће вам бити отворена; настаните се и тргујте и држите баштине у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'И рече Сихем оцу дјевојчину и браћи јој: да нађем милост пред вама, и даћу што ми год кажете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Иштите ми колико год хоћете уздарја и дара, ја ћу дати што год кажете; само ми дајте дјевојку за жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'А синови Јаковљеви одговорише Сихему и Емору оцу његову пријеварно, јер осрамоти Дину сестру њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'И рекоше им: не можемо то учинити ни дати сестре своје за човјека необрезана, јер је то срамота нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Него ћемо вам учинити по вољи, ако ћете се изједначити с нама и обрезати све мушкиње између себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Онда ћемо удавати своје кћери за вас и женићемо се вашим кћерима, и постаћемо један народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Ако ли не пристанете да се обрежете, ми ћемо узети своју дјевојку и отићи ћемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'И по вољи бише ријечи њихове Емору и Сихему сину Еморову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'И момак не оклијеваше учинити то; јер му кћи Јаковљева омиље веома; и он бјеше највише поштован између свијех у кући оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'И отиде Емор и син му Сихем на врата града својега, и рекоше грађанима говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Ови људи хоће мирно да живе с нама, да се настане у овој земљи и да тргују по њој; а ево земља је широка и за њих; па ћемо се кћерима њиховијем женити и своје ћемо кћери удавати за њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Али ће тако пристати да живе с нама и да постанемо један народ, ако се све мушкиње међу нама обреже, као што су они обрезани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Њихова стока и њихово благо и сва говеда њихова неће ли бити наша? сложимо се само с њима, па ће остати код нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'И који излажаху на врата града његова, сви послушаше Емора и Сихема сина његова; и обреза се све мушкиње, сви који излажаху на врата града његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'А трећи дан кад они бијаху у боловима, узеше два сина Јаковљева Симеун и Левије, браћа Динина, сваки свој мач и уђоше слободно у град и побише све мушкиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Убише и Емора и сина му Сихема оштрим мачем, и узевши Дину из куће Сихемове отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Тада дођоше синови Јаковљеви на побијене, и оплијенише град, јер у њему би осрамоћена сестра њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'И узеше овце њихове и говеда њихова и магарце њихове, што год бјеше у граду и што год бјеше у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'И све благо њихово, и сву дјецу и жене њихове похваташе и одведоше, и што год бјеше у којој кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'А Јаков рече Симеуну и Левију; сметосте ме, и омразисте ме народу ове земље, Хананејима и Ферезејима; у мене има мало људи, па ако се скупе на ме, хоће ме убити те ћу се истријебити ја и дом мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'А они рекоше: зар са сестром нашом да раде као с курвом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'А Бог рече Јакову: устани, иди горе у Ветиљ и ондје стани; и начини ондје жртвеник Богу, који ти се јавио кад си бјежао од Исава брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'И Јаков рече породици својој и свијема који бијаху с њим: баците туђе богове што су у вас, и очистите се и преобуците се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Па да се дигнемо и идемо горе у Ветиљ, да начиним ондје жртвеник Богу, који ме чуо у дан невоље моје и био са мном на путу којим сам ишао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'И дадоше Јакову све богове туђе који бијаху у њиховијем рукама, и обоце, које имаху у ушима; и Јаков их закопа под храстом код Сихема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Потом отидоше. А страх Божји дође на градове који бијаху око њих, те се не дигоше у потјеру за синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'И Јаков и сва чељад што бијаше с њим дођоше у Луз у земљи Хананској, а то је Ветиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'И ондје начини жртвеник, и назва оно мјесто: Бог Ветиљски, јер му се ондје јави Бог, кад је бјежао од брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Тада умрије Девора дојкиња Ревечина, и погребоше је испод Ветиља под храстом, који назва Јаков Алон-Вакут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'И јави се Бог Јакову опет, пошто изиде из Падан-Арама, и благослови га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'И рече му Бог: име ти је Јаков; али се отселе нећеш звати Јаков, него ће ти име бити Израиљ. И надједе му име Израиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'И још му рече Бог: ја сам Бог свемогући; расти и множи се; народ и многи ће народи постати од тебе, и цареви ће изаћи из бедара твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'И даћу ти земљу коју сам дао Авраму и Исаку, и након тебе сјемену твојему даћу земљу ову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Потом отиде од њега Бог с мјеста гдје му говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'А Јаков метну споменик на истом мјесту гдје му Бог говори; споменик од камена, и покропи га кропљењем, и прели га уљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'И Јаков прозва мјесто гдје му говори Бог Ветиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'И отидоше од Ветиља. А кад им оста још мало пута до Ефрате, породи се Рахиља, и бјеше јој тежак порођај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'И кад се веома мучаше, рече јој бабица: не бој се, имаћеш још једнога сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'А кад се растављаше с душом те умираше, назва га Венонија; али му отац надједе име Венијамин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'И умрије Рахиља, и погребоше је на путу који иде у Ефрату, а то је Витлејем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'И метну Јаков споменик на гроб њезин. То је споменик на гробу Рахиљину до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Одатле отишав Израиљ разапе шатор свој иза куле Мигдоледерске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'И кад Израиљ живљаше у оној земљи, отиде Рувим и леже с Валом иночом оца својега. И то дочу Израиљ. А имаше Јаков дванаест синова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Синови Лијини бјеху: Рувим првенац Јаковљев, и Симеун и Левије и Јуда и Исахар и Завулон;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'А синови Рахиљини: Јосиф и Венијамин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'А синови Вале робиње Рахиљине: Дан и Нефталим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'А синови Зелфе робиње Лијине: Гад и Асир. То су синови Јаковљеви, који му се родише у Падан-Араму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'И Јаков дође к Исаку оцу својему у Мамрију у Киријат-Арву, које је Хеврон, гдје Аврам и Исак бијаху дошљаци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'А Исаку бјеше сто и осамдесет година;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'И онемоћав умрије Исак, и би прибран к роду својему стар и сит живота; и погребоше га Исав и Јаков синови његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'А ово је племе Исавово, а он је Едом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Исав се ожени између кћери Хананејских Адом кћерју Елома Хетејина, и Оливемом кћерју Ане сина Севегона Евејина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'И Васематом кћерју Исмаиловом, сестром Наваотовом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'И роди Ада Исаву Елифаса, а Васемата роди Рагуила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'А Оливема роди Јеуса и Јеглома и Кореја. То су синови Исавови, који му се родише у земљи Хананској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'И Исав узе жене своје и синове своје и кћери своје и све домашње своје, и стада своја и сву стоку своју и све благо своје што бјеше стекао у земљи Хананској; па отиде у другу земљу далеко од Јакова брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Јер им благо бијаше врло велико, те не могаху живјети заједно; нити их земља гдје бијаху дошљаци могаше носити од множине стоке њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'И Исав живљаше на планини Сиру. Исав је Едом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'А ово је племе Исава оца Едомцима на планини Сиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Ово су имена синова Исавовијех: Елифас син Аде жене Исавове, и Ратуило син Васемате жене Исавове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'А Елифасови синови бјеху: Теман, Омар, Софар, Готом и Кенез.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'А Тамна бјеше иноча Елифасу сину Исавову, и роди Елифасу Амалика. то су синови Аде жене Исавове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'А ово су синови Рагуилови: Нахот, Заре, Соме и Мозе. То бјеху синови Васемате жене Исавове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'А ово су синови Оливеме кћери Ане сина Севегонова, жене Исавове. Она роди Исаву Јеуса и Јеглома и Кореја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Ово су старјешине синовима Исавовијем: синови Елифаса првенца Исавова: старјешина Теман, старјешина Омар, старјешина Софар, старјешина Кенез,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Старјешина Кореј, старјешина Готим, старјешина Амалик. То су старјешине од Елифаса у земљи Едомској. То су синови Адини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'А синови Рагуила сина Исавова: старјешина Нахот, старјешина Заре, старјешина Соме, старјешина Мозе. То су старјешине од Рагуила у земљи Едомској. То су синови Васемате жене Исавове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'А синови Оливеме жене Исавове: старјешина Јеус, старјешина Јеглом, старјешина Кореј. То су старјешине од Оливеме кћери Анине, жене Исавове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'То су синови Исавови, и то су старјешине њихове; а он је Едом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'А ово су синови Сира Хорејина, који живљаху у оној земљи: Лотан и Совал и Севегон и Ана,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'И Дисон и Асар и Рисон. То су старјешине Хорејима, синови Сирови у земљи Едомској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'А синови Лотанови бјеху Хорија и Еман, а сестра Лотанова бјеше Тамна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'А ово су синови Савалови: Голам и Манахат и Гевил и Софар и Омар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'А ово су синови Севегонови: Аије и Ана. А тај је Ана који пронађе топле изворе у пустињи пасући магарце Севегона оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'А ово су дјеца Анина: Дисон и Оливема кћи Анина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'А ово су синови Дисонови: Амада и Асван и Итран и Харан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'А ово су синови Асарови: Валам и Заван и Акан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'А ово су синови Рисонови: Уз и Аран.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'И ово су старјешине Хорејима: старјешина Лотан, старјешина Совал, старјешина Севегон, старјешина Ана,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Старјешина Дисон, старјешина Асар, старјешина Рисон. То су старјешине Хорејима, како им старјешоваху у земљи Сиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'А ово су цареви који цароваше у земљи Едомској прије него се зацари цар над синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Царова у Едомској Валак син Веоров, а граду му бјеше име Денава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'А кад умрије Валак, зацари се на његово мјесто Јовав син Зарин од Восоре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'А кад умрије Јовав, зацари се на његово мјесто Асом од земље Темановске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'А кад умрије Асом, зацари се на његово мјесто Адад син Варадов, који исијече Мадијанце у пољу Моавском, а граду му бјеше име Гетен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'А кад умрије Адад, зацари се на његово мјесто Самада, из Масекаса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'А кад умрије Самада, зацари се на његово мјесто Саул из Ровота на ријеци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'А кад умрије Саул, зацари се на његово мјесто Валенон син Аховоров.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'А кад умрије Валенон син Аховоров, зацари се на његово мјесто Адар, а град му се зваше Фогор, а жени му бјеше име Метевеила, која бјеше кћи Матраиде кћери Мезевове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'И ово су племена старјешинама од Исава по породицама њиховијем, по мјестима њиховијем, по именима њиховијем: старјешина Тамна, старјешина Гола, старјешина Јетер,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Старјешина Оливема, старјешина Ила, старјешина Финон,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Старјешина Кенез, старјешина Теман, старјешина Мазар,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Старјешина Магедило, старјешина Зафој. То су старјешине Едомске како наставаху у својој земљи. Овај Исав би отац Едомцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'А Јаков живљаше у земљи гдје му је отац био дошљак, у земљи Хананској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Ово су догађаји Јаковљеви. Јосиф кад бјеше момак од седамнаест година, пасијаше стоку с браћом својом, коју родише Вала и Зелфа жене оца његова; и доношаше Јосиф зле гласове о њима оцу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'А Израиљ љубљаше Јосифа највећма измећу свијех синова својих, јер му се родио под старост; и начини му шарену хаљину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'А браћа видећи гдје га отац љуби највећма између све браће његове, стадоше мрзити на њ тако да му не могаху лијепе ријечи проговорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Уз то усни Јосиф сан и приповједи браћи својој, те они још већма омрзну на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Јер им рече: да чујете сан што сам снио:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Везасмо снопље у пољу, па мој сноп уста и исправи се, а ваши снопови иђаху унаоколо и клањаху се снопу мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Тада му браћа рекоше: да нећеш још бити цар над нама и заповједати нам? Стога још већма стадоше мрзити на њ ради санова његовијех и ради ријечи његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Послије опет усни други сан, и приповједи браћи својој говорећи: усних опет сан, а то се сунце и мјесец и једанаест звијезда клањаху мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'А приповједи и оцу својему и браћи својој; али га отац прекори и рече му: какав је то сан што си снио? еда ли ћемо доћи ја и мати твоја и браћа твоја да се клањамо теби до земље?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'И завиђаху му браћа; али отац његов чуваше ове ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'А кад браћа његова отидоше да пасу стоку оца својега код Сихема,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Рече Израиљ Јосифу: не пасу ли браћа твоја стоку код Сихема? хајде да те пошаљем к њима. А он рече: ево ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'А он му рече: иди, види како су браћа твоја и како је стока, па дођи да ми јавиш. И оправи га из долине Хевронске, и он отиде пут Сихема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'И човјек један нађе га а он лута по пољу, те га запита говорећи: шта тражиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'А он рече: тражим браћу своју; кажи ми, молим те, гдје су са стоком?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'А човјек рече: отишли су одавде, јер чух гдје рекоше: хајдемо у Дотаим. И отиде Јосиф за браћом својом, и нађе их у Дотаиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'А они га угледаше издалека; и док још не дође близу њих, стадоше се договарати да га убију,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'И рекоше међу собом: гле, ево онога што сне сања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Хајде сада да га убијемо и да га бацимо у коју од овијех јама, па ћемо казати: љута га је звјерка изјела. Онда ћемо видјети шта ће бити од његовијех санова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Али Рувим кад чу то, избави га из руку њиховијех рекав: немојте да га убијемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'И још им рече Рувим: немојте крви прољевати; баците га у ову јаму у пустињи, а не дижите руке на њ. А он га шћаше избавити из руку њиховијех и одвести к оцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'И кад Јосиф дође к браћи својој, свукоше с њега хаљину његову, хаљину шарену, коју имаше на себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'И ухвативши га бацише га у јаму; а јама бјеше празна, не бјеше воде у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Послије сједоше да једу. И подигавши очи угледаше, а то гомила Исмаиљаца иђаше од Галада с камилама натовареним мирисавога коријења и тамјана и смирне, те ношаху у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'И рече Јуда браћи својој: кака ће бити корист што ћемо убити брата својега и затајити крв његову?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Хајде да га продамо овијем Исмаиљцима па да не дижемо руке своје на њ, јер нам је брат, наше је тијело. И послушаше га браћа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Па кад трговци Мадијамски бијаху поред њих, они извукоше и извадише Јосифа из јаме, и продадоше Јосифа Исмаиљцима за двадесет сребрника; и они одведоше Јосифа у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'А кад се Рувим врати к јами, а то нема Јосифа у јами; тада раздрије хаљине своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Па се врати к браћи својој, и рече: нема дјетета; а ја куда ћу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Тада узеше хаљину Јосифову, и заклавши јаре замочише хаљину у крв,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Па онда послаше шарену хаљину оцу његову поручивши: нађосмо ову хаљину, види је ли хаљина сина твојега или није.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'А он је позна и рече: сина је мојега хаљина; љута га је звјерка изјела; Јосиф је доиста раскинут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'И раздрије Јаков хаљине своје, и веза костријет око себе; и тужаше за сином својим дуго времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'И сви синови његови и све кћери његове устадоше око њега тјешећи га, али се он не дадијаше утјешити, него говораше: с тугом ћу у гроб лећи за сином својим. Па и његов отац плакаше за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'А Мадијанци продадоше га у Мисир Петефрију, дворанину Фараонову, заповједнику стражарском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'А у то вријеме догоди се, те Јуда отиде од браће своје и уврати се код некога Одоламејца, којему име бјеше Ирас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'И ондје видје Јуда кћер некога Хананејца, којему име бјеше Сава, и узе је и леже с њом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'И она затрудње и роди сина, којему надједе име Ир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'И опет затрудњевши роди сина, којему надједе име Авнан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'И опет роди сина, и надједе му име Силом; а Јуда бијаше у Хасви кад она тога роди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'И Јуда ожени првенца својега Ира дјевојком по имену Тамаром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Али Ир првенац Јудин бјеше неваљао пред Господом, и уби га Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'А Јуда рече Авнану: уђи к жени брата својега и ожени се њом на име братово, да подигнеш сјеме брату својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'А Авнан знајући да неће бити његов пород, кад лијегаше са женом брата својега просипаше на земљу, да не роди дјеце брату својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Али Господу не би мило што чињаше, те уби и њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'И Јуда рече Тамари снаси својој: остани удовицом у кући оца својега докле одрасте Силом син мој. Јер говораше: да не умре и он као браћа му. И отиде Тамара, и живљаше у кући оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'А кад прође много времена, умрије кћи Савина, жена Јудина. И кад се Јуда утјеши, пође у Тамну к људима што му стризијаху овце, сам с Ирасом пријатељем својим Одоламејцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'И јавише Тамари говорећи: ето свекар твој иде у Тамну да стриже овце своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'А она скиде са себе удовичко рухо своје, и узе покривало и покри лице, и сједе на раскршће на путу који иде у Тамну. Јер видје да је Силом одрастао а њу још не удаше за њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'А Јуда када видје, помисли да је курва, јер бјеше покрила лице своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Па сврну с пута к њој и рече јој: пусти да легнем с тобом. Јер није познао да му је снаха. А она рече: шта ћеш ми дати да легнеш са мном?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'А он рече: послаћу ти јаре из стада. А она рече: али да ми даш залог докле га не пошљеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'А он рече: какав залог да ти дам? А она рече: ето, прстен и рубац, и штап што ти је у руци. И он јој даде, те леже с њом, и она затрудње од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Послије уставши Тамара отиде и скиде покривало са себе и обуче удовичко рухо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'А Јуда посла јаре по пријатељу свом Одоламејцу да му донесе натраг од жене залог. Али је он не нађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Па питаше људе по оном мјесту гдје је она била говорећи: гдје је она курва што је била на раскршћу на овом путу? А они рекоше: није овдје било курве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'И врати се к Јуди и рече: не нађох је, него још рекоше мјештани: није овдје било курве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'А Јуда рече: нека јој да се не срамотимо; ја сам слао јаре, али је ти не нађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'А кад прође до три мјесеца дана, јавише Јуди говорећи: Тамара снаха твоја учини прељубу, и ево затрудње од прељубе. А Јуда рече: изведите је да се спали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'А кад је поведоше, посла к свекру својему и поручи: с човјеком чије је ово затрудњела сам. И рече: тражи чији је овај прстен и рубац и штап.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'А Јуда позна и рече: правија је од мене, јер је не дадох сину својему Силому. И више не леже с њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'А кад дође вријеме да роди, а то близанци у утроби њезиној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'И кад се порађаше, једно дијете помоли руку, а бабица узе и веза му црвен конац око руке говорећи: овај је први.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Али он увуче руку, и гле изађе брат његов, а она рече: како продрије? продирање нека ти буде. И надјеше му име Фарес.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'А послије изађе брат му, којему око руке бијаше црвени конац, и надјеше му име Зара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'А Јосифа одведоше у Мисир; и Петефрије дворанин Фараонов, заповједник стражарски, човјек Мисирац, купи га од Исмаиљаца, који га одведоше онамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'И Господ бјеше с Јосифом, те би срећан, и живљаше у кући господара својега Мисирца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'И господар његов видје да је Господ с њим и да све што ради Господ води у напредак у руци његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'И Јосиф стече милост у њега, и двораше га; а најпослије постави га над цијелијем домом својим, и што год имаше њему даде у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'А кад га постави над домом својим и над свијем што имаше, од тада Господ благослови дом тога Мисирца ради Јосифа; и благослов Господњи бјеше на свему што имаше у кући и у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'И остави у Јосифовијем рукама све што имаше, и не разбираше ни за што осим јела које јеђаше. А Јосиф бијаше лијепа стаса и лијепа лица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'И догоди се послије, те се жена господара његова загледа у Јосифа, и рече: лези са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'А он не хтје, него рече жени господара својега: ето господар мој не разбира ни за што што је у кући, него што год има даде мени у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Ни сам није већи од мене у овој кући, и ништа не крије од мене осим тебе, јер си му жена; па како бих учинио тако грдно зло и Богу згријешио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'И она говораше таке ријечи Јосифу сваки дан, али је не послуша да легне с њом ни да се бави код ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'А један дан кад дође Јосиф у кућу да ради свој посао, а не бјеше никога од домашњих у кући,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Она га ухвати за хаљину говорећи: лези са мном. Али он оставив јој у рукама хаљину своју побјеже и отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'А кад она видје гдје јој остави у рукама хаљину своју и побјеже,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Викну чељад своју, и рече им говорећи: гледајте, довео нам је човјека Јеврејина да нас срамоти; дође к мени да легне са мном, а ја повиках иза гласа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'А он кад чу гдје вичем, остави хаљину своју код мене и побјеже и отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'И она остави хаљину његову код себе док му господар дође кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'А тада му рече овако говорећи: слуга Јеврејин, којега си нам довео, дође к мени да ме осрамоти;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'А ја повиках иза гласа, те он оставив хаљину своју код мене побјеже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'А кад господар његов чу ријечи жене своје гдје му рече: то ми је учинио слуга твој, разгњеви се врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'И господар Јосифов ухвати га, и баци га у тамницу, гдје лежаху сужњи царски; и би ондје у тамници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Али Господ бјеше с Јосифом и рашири милост своју над њим и учини те омиље тамничару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'И повјери тамничар Јосифу све сужње у тамници, и што је год требало ондје чинити он уређиваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'И тамничар не надгледаше ништа што бјеше у Јосифовој руци, јер Господ бјеше с њим; и што год чињаше, Господ вођаше у напредак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Послије тога догоди се, те пехарник цара Мисирскога и хљебар скривише господару својему, цару Мисирском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'И Фараон се разгњеви на та два дворанина, на старјешину над пехарницима и на старјешину над хљебарима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'И баци их у тамницу у кући заповједника стражарскога, гдје Јосиф бјеше сужањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'А заповједник стражарски одреди им Јосифа да их служи; и бијаху дуго у тамници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'И уснише сан обојица у једну ноћ, сваки по значењу својега сна за себе, и пехарник и хљебар цара Мисирскога, који бијаху сужњи у тамници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'И сјутрадан кад дође Јосиф к њима, погледа их, а они бјеху врло невесели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Па запита дворане Фараонове, који бијаху сужњи с њим у кући господара његова, и рече: што сте данас лица невесела?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'А они му рекоше: сан уснисмо обојица, а нема ко да нам каже шта значе. А Јосиф им рече: шта значе, није ли у Бога? али приповједите ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'И старјешина над пехарницима приповједи сан свој Јосифу говорећи: сних, а преда мном чокот;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'И на чокоту бјеху три лозе, и напупи и процвате, и грожђе на њему узре;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'А у руци ми бјеше чаша Фараонова, те побрах зрело грожђе и исциједих га у чашу Фараонову, и додадох чашу Фараону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'А Јосиф му рече: ово значи: три су лозе три дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Још три дана, и Фараон бројећи своје дворане узеће и тебе, и опет те поставити у пређашњу службу, и опет ћеш му додавати чашу као и пређе док си му био пехарник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Али немој заборавити мене кад будеш у добру, учини милост и помени за ме Фараону, и изведи ме из ове куће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Јер су ме украли из земље Јеврејске, а овдје нијесам ништа учинио да ме баце у ову јаму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'А кад видје старјешина над хљебарима како лијепо каза сан, рече Јосифу: и ја сних, а мени на глави три котарице бијеле;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'И у најгорњој котарици бијаше свакојаких колача за Фараона, и птице јеђаху из котарице на мојој глави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'А Јосиф одговори и рече: ово значи: три котарице три су дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Још три дана, и Фараон бројећи дворане своје избациће те и објесиће те на вјешала, и птице ће јести с тебе месо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'И кад дође трећи дан, то бјеше дан у који се родио Фараон, и учини Фараон гозбу свима слугама својим, и наиђе међу слугама својим на старјешину над пехарницима и на старјешину над хљебарима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'И поврати старјешину над пехарницима у службу да додаје чашу Фараону;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'А старјешину над хљебарима објеси, као што каза Јосиф.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'И старјешина над пехарницима не опомену се Јосифа, него га заборави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'А послије двије године дана усни Фараон, а он стоји на једној ријеци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'И гле, из ријеке изађе седам крава лијепијех и дебелијех, и стадоше пасти по обали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'И гле, иза њих изађе из ријеке седам других крава, ружнијех и мршавијех, и стадоше поред онијех крава на обали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'И ове краве ружне и мршаве поједоше онијех седам крава лијепијех и дебелијех. У том се пробуди Фараон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Па опет заспав усни другом, а то седам класова израсте из једнога стабла једријех и лијепијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'А иза њих исклија седам класова малијех и штуријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Па ови класови мали поједоше онијех седам великијех и једријех. У том се пробуди Фараон и видје да је сан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'И кад би ујутру, он се забрину у духу, и послав сазва све гатаре Мисирске и све мудраце, и приповједи им шта је снио; али нико не може казати Фараону шта значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Тада проговори старјешина над пехарницима Фараону и рече: данас се опоменух гријеха својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Кад се Фараон расрди на слуге своје и баци у тамницу у кући заповједника стражарскога мене и старјешину над хљебарима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Уснисмо једну ноћ ја и он, сваки за себе по значењу сна својега уснисмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'А ондје бијаше с нама момче Јеврејче, слуга заповједника стражарскога, и ми му приповједисмо сне, а он нам каза шта чији сан значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'И зби се како нам каза: мене поврати Фараон у службу, а онога објеси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Тада Фараон посла по Јосифа, и брже га изведоше из тамнице, а он се обрија и преобуче се, те изађе пред Фараона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'А Фараон рече Јосифу: усних сан, па ми нико не умије да каже шта значи; а за тебе чујем да умијеш казивати сне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'А Јосиф одговори Фараону и рече: то није у мојој власти, Бог ће јавити добро Фараону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'И рече Фараон Јосифу: усних, а ја стојим крај ријеке на обали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'И гле, из ријеке изађе седам крава дебелијех и лијепијех, те стадоше пасти по обали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'И гле, иза њих изађе седам других крава рђавијех, и врло ружнијех и мршавијех, каквијех нијесам видио у цијелој земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'И ове краве мршаве и ружне поједоше онијех седам дебелијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'И кад им бише у трбуху, не познаваше се да су им у трбуху, него опет бјеху онако ружне као прије. У том се пробудих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Па опет усних, а то седам класова израсте из једнога стабла једријех и лијепијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'А иза њих исклија седам малијех, танкијех и штуријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'И ови танки класови прождријеше онијех седам лијепијех. И ово приповједих гатарима, али ми ни један не зна казати шта значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'А Јосиф рече Фараону: оба су сна Фараонова једнака; Бог јавља Фараону шта је наумио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Седам лијепијех крава јесу седам година, и седам лијепијех класова јесу седам година; оба су сна једнака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'А седам крава мршавијех и ружнијех, што изађоше иза онијех, јесу седам година; и седам класова ситнијех и штуријех биће седам година гладнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'То је што рекох Фараону: Бог каже Фараону шта је наумио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Ево доћи ће седам година врло роднијех свој земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'А иза њих настаће седам гладнијех година, гдје ће се заборавити све обиље у земљи Мисирској, јер ће глад сатрти земљу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Те се неће знати то обиље у земљи од глади потоње, јер ће бити врло велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'А што је два пута засопце Фараон снио, то је зато што је зацијело Бог тако наумио, и на скоро ће то учинити Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Него сада нека потражи Фараон човјека мудра и разумна, па нека га постави над земљом Мисирском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'И нека гледа Фараон да постави старјешине по земљи, и покупи петину по земљи Мисирској за седам роднијех година;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Нека скупљају од свакога жита за роднијех година које иду, и нека снесу под руку Фараонову свакога жита у све градове, и нека чувају,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Да се нађе хране земљи за седам година гладнијех, кад настану, да не пропадне земља од глади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'И ово се учини добро Фараону и свијем слугама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'И рече Фараон слугама својим: можемо ли наћи човјека какав је овај, у којем би дух био Божји?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Па рече Фараон Јосифу: кад је теби јавио Бог све ово, нема никога тако мудра и разумна као што си ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Ти ћеш бити над домом мојим, и сав ће ти народ мој уста љубити; само ћу овијем пријестолом бити већи од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'И још рече Фараон Јосифу: ево, постављам те над свом земљом Мисирском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'И скиде Фараон прстен с руке своје и метну га Јосифу на руку, и обуче га у хаљине од танкога платна, и објеси му златну верижицу о врату,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'И посади га на кола која бијаху друга за његовијем, и заповједи да пред њим вичу: клањајте се! и да га је поставио над свом земљом Мисирском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'И још рече Фараон Јосифу: ја сам Фараон, али без тебе неће нико маћи руке своје ни ноге своје у свој земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'И надје Фараон Јосифу име Псонтомфаних, и ожени га Асенетом кћерју Потифере свештеника Онскога. И пође Јосиф по земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'А бијаше Јосифу тридесет година кад изађе пред Фараона цара Мисирскога. И отишав од Фараона обиђе сву земљу Мисирску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'И за седам роднијех година роди земља свашта изобила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'И стаде Јосиф купити за тијех седам година свакога жита што бјеше по земљи Мисирској, и сносити жито у градове; у сваки град сношаше жито с њива које бјеху око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Тако накупи Јосиф жита врло много колико је пијеска морскога, тако да га преста мјерити, јер му не бјеше броја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'И докле још не наста гладна година, родише се Јосифу два сина, које му роди Асенета кћи Потифере свештеника Онскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'И првенцу надједе Јосиф име Манасија, говорећи: јер ми Бог даде да заборавим сву муку своју и сав дом оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'А другоме надједе име Јефрем, говорећи: јер ми Бог даде да растем у земљи невоље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Али прође седам година роднијех у земљи Мисирској;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'И наста седам година гладнијех, као што је Јосиф напријед казао. И бјеше глад по свијем земљама, а по свој земљи Мисирској бјеше хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Али најпослије наста глад и по свој земљи Мисирској, и народ повика к Фараону за хљеб; а Фараон рече свима Мисирцима: идите к Јосифу, па што вам он каже оно чините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'И кад глад бјеше по свој земљи, отвори Јосиф све житнице, и продаваше Мисирцима. И глад поста врло велика у земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'И из свијех земаља долажаху у Мисир к Јосифу да купују; јер поста глад у свакој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'А Јаков видећи да има жита у Мисиру, рече синовима својим: шта гледате један на другога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'И рече: ето чујем да у Мисиру има жита; идите онамо те нам купите отуда, да останемо живи и не помремо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'И десеторица браће Јосифове отидоше да купе жита у Мисиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'А Венијамина брата Јосифова не пусти отац с браћом говорећи: да га не би задесило како зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'И дођоше синови Израиљеви да купе жита с осталима који долажаху; јер бјеше глад у земљи Хананској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'А Јосиф управљаше земљом, и продаваше жито свему народу по земљи. И браћа Јосифова дошавши поклонише му се лицем до земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'А Јосиф угледав браћу позна их; али се учини да их не познаје, и оштро им проговори и рече: одакле сте дошли? А они рекоше: из земље Хананске, да купимо хране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Јосиф дакле позна браћу своју; али они њега не познаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'И опомену се Јосиф санова које је снио за њих; и рече им: ви сте уходе; дошли сте да видите гдје је земља слаба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'А они му рекоше: нијесмо, господару; него слуге твоје дођоше да купе хране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Сви смо синови једнога човјека, поштени људи, нигда нијесу слуге твоје биле уходе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'А он им рече: није истина, него сте дошли да видите гдје је земља слаба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'А они рекоше: нас је било дванаест браће, слуга твојих, синова једнога човјека у земљи Хананској; и ено, најмлађи је данас код оца нашега, а једнога нема више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'А Јосиф им рече: кажем ја да сте ви уходе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Него хоћу да се увјерим овако: тако жив био Фараон, нећете изаћи одавде докле не дође амо најмлађи брат ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Пошљите једнога између себе нека доведе брата вашега, а ви ћете остати овдје у тамници, па ћу видјети је ли истина што говорите; иначе сте уходе, тако жив био Фараон!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'И затвори их у тамницу на три дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'А трећи дан рече им Јосиф: ако сте ради животу, ово учините, јер се ја Бога бојим:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Ако сте поштени људи, један брат између вас нека остане у тамници, а ви идите и однесите жита колико треба породицама вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Па онда доведите к мени најмлађега брата својега да се посвједоче ријечи ваше и да не изгинете. И они учинише тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'И рекоше један другом: доиста се огријешисмо о брата својега. јер видјесмо муку душе његове кад нам се мољаше, па га се оглушисмо; зато дође на нас ова мука.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'А Рувим одговори им говорећи: нијесам ли вам говорио: немојте се гријешити о дијете? али ме не послушасте; и зато се ево тражи од нас крв његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'А они не знадијаху да их Јосиф разумије, јер се с њим разговараху преко тумача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'А Јосиф окрете се од њих, и заплака се. Потом се опет окрете к њима, и проговори с њима, и узев између њих Симеуна веза га пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'И заповједи Јосиф да им наспу вреће жита, па и новце што је који дао да метну свакоме у врећу, и да им даду брашњенице на пут. И тако би учињено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'И натоваривши жито своје на магарце своје отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'А један од њих отворив своју врећу да нахрани магарца својега у једној гостионици, видје новце своје озго у врећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'И рече браћи својој: ја добих натраг новце своје, ево их у мојој врећи. И задрхта срце у њима и уплашише се говорећи један другоме: што нам то учини Бог?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'И дошавши к Јакову оцу својему у земљу Хананску, приповједише му све што им се догоди, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Оштро говораше с нама човјек, који заповједа у оној земљи, и дочека нас као уходе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'А кад му рекосмо: ми смо поштени људи, нигда нијесмо били уходе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Било нас је дванаест браће, синова оца нашега; једнога већ нема, а најмлађи је данас код оца нашега у земљи Хананској;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Рече нам човјек, који заповједа у оној земљи: овако ћу дознати јесте ли поштени људи: брата једнога између себе оставите код мене, а што вам треба за породице ваше глади ради, узмите и идите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Послије доведите к мени брата својега најмлађега, да се увјерим да нијесте уходе него поштени људи; брата ћу вам вратити, и моћи ћете трговати по овој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'А кад изручиваху вреће своје, гле, свакоме у врећи бјеху у завежљају новци његови; и видјевши завежљаје новаца својих уплашише се и они и отац им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'И рече им Јаков отац њихов: потрсте ми дјецу; Јосифа нема, Симеуна нема, па хоћете и Венијамина да узмете; све се скупило на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'А Рувим проговори и рече оцу својему: два сина моја убиј, ако ти га не доведем натраг; дај га у моје руке, и ја ћу ти га опет довести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'А он рече: неће ићи син мој с вама, јер је брат његов умро и он оста сам, па ако би га задесило како зло на путу на који ћете ићи, свалили бисте ме стара с тугом у гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Али глад бјеше врло велика у оној земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Па кад поједоше жито које бијаху донијели из Мисира, рече им отац: идите опет, и купите нам мало хране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'А Јуда му проговори и рече: тврдо нам се зарекао онај човјек говорећи: нећете видјети лица мојега, ако не буде с вама брат ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Ако ћеш пустити с нама брата нашега, ићи ћемо и купићемо ти хране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Ако ли нећеш пустити, нећемо ићи, јер нам је казао онај човјек: нећете видјети лица мојега, ако не буде с вама брат ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'А Израиљ рече: што ми то зло учинисте и казасте човјеку да имате још једнога брата?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'А они рекоше: човјек је потанко распитивао за нас и за род наш говорећи: је ли вам јоште жив отац? имате ли још браће? а ми му одговарасмо како нас питаше. Јесмо ли могли како знати да ће казати: доведите брата својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'И рече Јуда Израиљу оцу својему: пусти дијете са мном, па ћемо се подигнути и отићи, да останемо живи и не помремо и ми и ти и наша дјеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ја ти се јамчим за њ, из моје га руке ишти; ако ти га не доведем натраг и преда те не ставим, да сам ти крив довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Да нијесмо толико оклијевали, до сада бисмо се два пута вратили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Онда рече Израиљ отац њихов: кад је тако, учините ово: узмите што најљепше има у овој земљи у своје вреће, и понесите човјеку оном дар: мало тамјана и мало меда, мирисава коријења и смирне, урме и бадема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'А новаца понесите двојином, и узмите новце што бијаху озго у врећама вашим и однесите натраг, може бити да је погрјешка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'И узмите брата својега, па устаните и идите опет к оном човјеку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'А Бог свемогући да вам да да нађете милост у онога човјека, да вам пусти брата вашега другога и Венијамина; ако ли останем без дјеце, нек останем без дјеце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Тада узевши даре и новаца двојином, узевши и Венијамина, подигоше се и отидоше у Мисир, и изађоше пред Јосифа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'А Јосиф кад видје с њима Венијамина, рече човјеку који управљаше кућом његовом: одведи ове људе у кућу, па накољи меса и зготови, јер ће у подне са мном јести ови људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'И учини човјек како Јосиф рече, и уведе људе у кућу Јосифову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'А они се бојаху кад их човјек вођаше у кућу Јосифову, и рекоше: за новце који пређе бјеху метнути у вреће наше води нас, докле смисли како ће нас окривити, да нас зароби и узме наше магарце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Па приступивши к човјеку који управљаше кућом Јосифовом, проговорише му на вратима кућним,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'И рекоше: чуј, господару; дошли смо били и пређе, и куписмо хране;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Па кад дођосмо у једну гостионицу и отворисмо вреће, а то новци свакога нас бијаху озго у врећи његовој, новци наши на мјеру; и ево смо их донијели натраг;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'А друге смо новце донијели да купимо хране; не знамо ко нам метну новце наше у вреће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'А он им рече: будите мирни, не бојте се; Бог ваш и Бог оца вашега метнуо је благо у вреће ваше; новци су ваши били у мене. И изведе им Симеуна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'И уведе их човјек у кућу Јосифову, и донесе им воде те опраше ноге, и магарцима њиховијем положи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'И приправише дар чекајући докле дође Јосиф у подне, јер чуше да ће они ондје обједовати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'И кад Јосиф дође кући, изнесоше му дар који имаху код себе, и поклонише му се до земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'А он их запита како су, и рече: како је отац ваш стари, за кога ми говористе? је ли јоште жив?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'А они рекоше: добро је слуга твој, отац наш; још је жив. И поклонише му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'А он погледав видје Венијамина брата својега, сина матере своје, и рече: је ли вам то најмлађи брат ваш за којега ми говористе? И рече: Бог да ти буде милостив, синко!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'А Јосифу гораше срце од љубави према брату својему, те брже потражи гдје ће плакати, и ушав у једну собу плака ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Послије умив се изађе, и устежући се рече: дајте објед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'И донесоше њему напосе, и њима напосе, и Мисирцима који обједоваху у њега напосе, јер не могаху Мисирци јести с Јеврејима, јер је то нечисто Мисирцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'А сјеђаху пред њим старији по старјешинству својем а млађи по младости својој. И згледаху се од чуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'И узимајући јела испред себе слаше њима, и Венијамину допаде пет пута више него другима. И пише и напише се с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'И заповједи Јосиф човјеку што управљаше кућом његовом говорећи: наспи овијем људима у вреће жита колико могу понијети, и свакоме у врећу метни озго новце његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'И чашу моју, чашу сребрну, метни најмлађему у врећу озго и новце за његово жито. И учини како му Јосиф рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'А ујутру кад свану, отпустише људе с магарцима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'А кад изађоше из мјеста и још не бијаху далеко, рече Јосиф човјеку што управљаше кућом његовом: устани, иди брже за онијем људима, и кад их стигнеш реци им: зашто враћате зло за добро?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Није ли то чаша из које пије мој господар? и неће ли по њој зацијело познати какви сте? зло сте радили што сте то учинили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'И он их стиже, и рече им тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'А они му рекоше: зашто говориш, господару, таке ријечи? Сачувај Боже да слуге твоје учине тако што!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Ено смо ти донијели натраг из земље Хананске новце које нађосмо озго у врећама својим, па како бисмо украли из куће господара твојега сребро или злато?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'У којега се између слуга твојих нађе, онај нека погине, и сврх тога ми ћемо бити робови господару мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'А он рече: нека буде како рекосте; али у кога се нађе, онај да ми буде роб, а ви остали нећете бити криви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'И брже поскидаше сви на земљу вреће своје, и раздријешише сваки своју врећу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'А он стаде тражити почев од најстаријега, и кад дође на најмлађега, нађе се чаша у врећи Венијаминовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Тада раздријеше хаљине своје, и натоваривши сваки свој товар на својега магарца вратише се у град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'И дође Јуда с браћом својом Јосифу у кућу, док он још бијаше код куће, и падоше пред њим на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'А Јосиф им рече: шта сте то учинили? зар нијесте знали да човјек као што сам ја може зацијело дознати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Тада рече Јуда: шта да ти речемо, господару? шта да говоримо? како ли да се правдамо? Бог је открио злочинство твојих слуга. Ево, ми смо сви робови твоји, господару, и ми и овај у кога се нашла чаша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'А Јосиф рече: Боже сачувај! нећу ја то; у кога се нашла чаша он нека ми буде роб, а ви идите с миром оцу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Али Јуда приступив к њему рече: чуј ме, господару; допусти да проговори слуга твој господару својему, и нека се гњев твој не распали на слугу твојега, јер си ти као сам Фараон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Господар мој запита слуге своје говорећи: имати ли оца или брата?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'А ми рекосмо господару својему: имамо стара оца и брата најмлађега, који му се роди у старости; а његов је брат умро, и он оста сам од матере своје, и отац га пази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'А ти рече слугама својим: доведите ми га да видим својим очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'И рекосмо господару својему: неће моћи дијете оставити оца својега; да остави оца својега, одмах ће отац умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'А ти рече слугама својим: ако не дође брат ваш најмлађи, нећете видјети лица мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'А кад се вратисмо к слузи твојему а оцу мојему, казасмо му ријечи господара мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Послије рече нам отац: идите опет, купите нам хране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'А ми рекосмо: не можемо ићи, осим ако буде брат наш најмлађи с нама, онда ћемо ићи, јер не можемо видјети лица онога човјека, ако не буде с нама брат наш најмлађи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'А слуга твој, отац мој, рече нам: знате да ми је жена родила два сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'И један од њих отиде од мене, и рекох: зацијело га је раскинула звјерка; и до сада га не видјех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Ако и овога одведете од мене и задеси га како зло, свалићете ме стара у гроб с тугом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Па сада да отидем к слузи твојему, оцу својему, а ово дијете да не буде с нама, како је душа онога везана за душу овога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Умријеће кад види да нема дјетета, те ће слуге твоје свалити старога слугу твојега а оца својега с тугом у гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'А твој се слуга подјемчио за дијете оцу својему рекав: ако ти га не доведем натраг, да сам крив оцу својему до вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Зато нека слуга твој остане мјесто дјетета да буде роб господару мојему а дијете нека иде с браћом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Јер како бих се вратио к оцу својему без дјетета, да гледам јаде који би ми оца задесили?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Тада Јосиф не могући се уздржати пред осталима који стајаху око њега, повика: изађите сви напоље. Тако не оста нико код њега кад се Јосиф показа браћи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Па бризну плакати тако да чуше Мисирци, чу и дом Фараонов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'И рече Јосиф браћи својој: ја сам Јосиф; је ли ми отац још у животу? Али му браћа не могаху одговорити, јер се препадоше од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'А Јосиф рече браћи својој: приступите ближе к мени. И приступише; а он рече ја сам Јосиф брат ваш, којега продадосте у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'А сада немојте жалити нити се кајати што ме продадосте овамо, јер Бог мене посла пред вама ради живота вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Јер је већ двије године дана глад у земљи, а биће још пет година, гдје неће бити ни орања ни жетве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'А Бог ме посла пред вама, да вас сачува на земљи и да вам избави живот избављењем превеликим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'И тако нијесте ме ви оправили овамо него сам Бог, који ме постави оцем Фараону и господарем од свега дома његова и старјешином над свом земљом Мисирском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Вратите се брже к оцу мојему и кажите му: овако вели син твој Јосиф: Бог ме је поставио господарем свему Мисиру, ходи к мени, немој оклијевати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Сједјећеш у земљи Гесемској и бићеш близу мене, ти и синови твоји и синови синова твојих, и овце твоје и говеда твоја и што је год твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'И ја ћу те хранити ондје, јер ће још пет година бити глад, да не погинеш од глади ти и дом твој и што је год твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'А ето видите очима својима, и брат мој Венијамин својима очима, да вам ја из уста говорим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Кажите оцу мојему сву славу моју у Мисиру и што сте год видјели; похитајте и доведите овамо оца мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Тада паде око врата Венијамину брату својему и плака. И Венијамин плака о врату његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'И изљуби сву браћу своју и исплака се над њима. Потом се браћа његова разговараху с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'И чу се глас у кући Фараоновој, и рекоше: дођоше браћа Јосифу. И мило би Фараону и слугама његовијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'И рече Фараон Јосифу: кажи браћи својој: овако учините: натоварите магарце своје, па идите и вратите се у земљу Хананску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Па узмите оца својега и чељад своју, и дођите к мени, и даћу вам најбоље што има у земљи Мисирској, и јешћете најбоље обиље ове земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'А ти им заповједи: овако учините: узмите са собом из земље Мисирске кола за дјецу своју и за жене своје, и поведите оца својега и дођите овамо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'А на покућство своје не гледајте, јер што има најбоље у свој земљи МИсирској ваше је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'И синови Израиљеви учинише тако; и Јосиф им даде кола по заповијести Фараоновој; даде им и брашњенице на пут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'И свакоме даде по двоје хаљине а Венијамину даде триста сребрника и петоре хаљине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'А оцу својему посла још десет магараца натоваренијех најљепшијех ствари што има у Мисиру, и десет магарица натоваренијех жита и хљеба и јестива оцу на пут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Тако оправи браћу своју, и пођоше; и рече им: немојте се корити путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Тако се вратише из Мисира, и дођоше у земљу Хананску к Јакову оцу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'И јавише му и рекоше: још је жив Јосиф, и заповједа над свом земљом Мисирском. А у њему срце пренеможе, јер им не вјероваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Али кад му казаше све ријечи Јосифове, које им је Јосиф рекао, и видје кола, која посла Јосиф по оца, тада оживје дух Јакова оца њихова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'И рече Израиљ: доста ми је кад је још жив син мој Јосиф; идем да га видим докле нијесам умро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Тада пође Израиљ са свијем што имаше, и дошав у Вирсавеју принесе жртву Богу оца својега Исака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'И Бог рече Израиљу ноћу у утвари: Јакове! Јакове! А он одговори: ево ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'И Бог му рече: ја сам Бог, Бог оца твојега; не бој се отићи у Мисир; јер ћу ондје начинити од тебе народ велик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ја ћу ићи с тобом у Мисир, и ја ћу те одвести онамо, и Јосиф ће метнути руку своју на очи твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'И пође Јаков од Вирсавеје; и синови Израиљеви посадише Јакова оца својега и дјецу своју и жене своје на кола која посла Фараон по њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'И узеше стоку своју и благо своје што бијаху стекли у земљи Хананској; и дођоше у Мисир Јаков и сва породица његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Синове своје и синове синова својих, кћери своје и кћери синова својих, и сву породицу своју доведе са собом у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'А ово су имена дјеце Израиљеве што дођоше у Мисир: Јаков и синови његови. Првенац Јаковљев Рувим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'И синови Рувимови: Енох, Фалуј, Есрон и Хармија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'А синови Симеунови: Јемуило, Јамин, Аод, Јахин, Соар и Саул, син једне Хананејке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Синови Левијеви: Гирсон, Кат и Мерарије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Синови Јудини: Ир, Авнан, Силом, Фарес и Зара; а умрли бјеху Ир и Авнан у земљи Хананској, али бијаху синови Фаресови Есром и Јемуило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Синови Исахарови: Тола, Фува, Јов, и Симрон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Синови Завулонови: Серед, Алон, и Ахојило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'То су синови Лијини, које роди Јакову у Падан-Араму, и јоште Дина кћи његова. Свега душа, синова његовијех и кћери његовијех бјеше тридесет и три.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Синови Гадови: Сифон, Агије, Суније, Есвон, Ирије, Ародије и Арилије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Синови Асирови: Јемна, Јесва, Јесвија и Верија, и сестра њихова Сара. А синови Веријини Ховор и Мелхило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'То су синови Зелфе, коју даде Лаван Лији кћери својој, и она их роди Јакову, шеснаест душа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'А синови Рахиље жене Јаковљеве: Јосиф и Венијамин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'А Јосифу се родише у Мисиру од Асенете кћери Потифере свештеника Онскога: Манасија и Јефрем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'А синови Венијаминови: Вела, Вехер, Асвил, Гира, Наман, Ихије, Рос, Мупим, Упим и Арад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'То су синови Рахиљини што се родише Јакову, свега четрнаест душа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'И син Данов: Асом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'А синови Нефталимови: Асило, Гуније, Јесер и Силим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'То су синови Вале, коју даде Лаван Рахиљи кћери својој и она их роди Јакову; свега седам душа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'А свега душа што дођоше с Јаковом у Мисир а изађоше од бедара његовијех, осим жена синова Јаковљевијех, свега душа бјеше шездесет и шест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'И два сина Јосифова који му се родише у Мисиру; свега дакле душа дома Јаковљева, што дођоше у Мисир, бјеше седамдесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'А Јуду посла Јаков напријед к Јосифу, да му јави да изађе преда њ у Гесем. И дођоше у земљу Гесемску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'А Јосиф упреже у кола своја, и изађе на сусрет Израиљу оцу својему у Гесем; и кад га видје Јаков, паде му око врата, и плака дуго о врату његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'И рече Израиљ Јосифу: сада не марим умријети кад сам те видио да си јоште жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'А Јосиф рече браћи својој и дому оца својега: идем да јавим Фараону; али ћу му казати: браћа моја и дом оца мојега из земље Хананске дођоше к мени;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'А ти су људи пастири и свагда су се бавили око стоке, и доведоше овце своје и говеда своја и што год имају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'А кад вас Фараон дозове, рећи ће вам: каку радњу радите?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'А ви кажите: пастири су биле слуге твоје од младости, и ми и стари наши; да бисте остали у земљи Гесемској; јер су Мисирцима сви пастири нечисти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'И отишав Јосиф јави Фараону и рече: отац мој и браћа моја с овцама својим и с говедима својим и са свијем што имају дођоше из земље Ханаске, и ево их у земљи Гесемској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'И узев неколицину браће своје, пет људи, изведе их пред Фараона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'А Фараон рече браћи његовој: каку радњу радите? А они рекоше Фараону: пастири су слуге твоје, и ми и наши стари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Још рекоше Фараону: дођосмо да живимо као дошљаци у овој земљи, јер нема паше за стоку твојих слуга, јер је велика глад у земљи Хананској; а сада допусти да живе у земљи Гесемској слуге твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'А Фараон рече Јосифу: отац твој и браћа твоје дођоше к теби;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'У твојој је власти земља Мисирска; на најбољем мјесту у овој земљи насели оца својега и браћу своју, нека живе у земљи Гесамској; и као које знаш између њих да су вриједни људи, постави их над мојом стоком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Послије доведе Јосиф и Јакова оца својега и изведе га пред Фараона, и благослови Јаков Фараона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'А Фараон рече Јакову: колико ти има година?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Одговори Јаков Фараону: мени има сто и тридесет година, како сам дошљак. Мало је дана живота мојега и зли су били, нити стижу вијека отаца мојих, колико су они живјели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'И благословив Јаков Фараона отиде од Фараона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'А Јосиф насели оца својега и браћу своју, и даде им добро у земљи Мисирској на најбољем мјесту те земље, у земљи Рамеској, као што заповједи Фараон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'И храњаше Јосиф хљебом оца својега и браћу своју и сав дом оца својега до најмањега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Али неста хљеба у свој земљи, јер глад бијаше врло велика, и узмучи се земља Мисирска и земља Хананска од глади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'И покупи Јосиф све новце што се налажаху по земљи Мисирској и по земљи Хананској за жито које куповаху, и слагаше новце у кућу Фараонову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'А кад неста новца у земљи Мисирској и у земљи Хананској, стадоше сви Мисирци долазити к Јосифу говорећи: дај нам хљеба; зашто да мремо код тебе, што новаца нема?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'А Јосиф им говораше: дајте стоку своју, па ћу вам дати хљеба за стоку, кад је нестало новца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'И довођаху стоку своју к Јосифу, и Јосиф им даваше хљеба за коње и за овце и за говеда и за магарце. Тако их прехрани ону годину хљебом за сву стоку њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'А кад прође она година, стадоше опет долазити к њему друге године говорећи: не можемо тајити од господара својега, али је новаца нестало, и стока коју имасмо у нашега је господара; и није остало ништа да донесемо господару својему осим тјелеса наших и њива наших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Зашто да мремо на твоје очи? ево и нас и наших њива; купи нас и њиве наше за хљеб, да с њивама својим будемо робови Фараону, и дај жита да останемо живи и не помремо и да земља не опусти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Тако покупова Јосиф Фараону све њиве у Мисиру, јер Мисирци продаваху сваки своју њиву, кад глад узе јако мах међу њима. И земља поста Фараонова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'А народ пресели у градове од једнога краја Мисира до другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Само не купи свештеничких њива; јер Фараон одреди дио свештеницима, и храњаху се од својега дијела, који им даде Фараон, те не продаше својих њива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'А Јосиф рече народу: ево купих данас вас и њиве ваше Фараону; ево вам сјемена, па засијте њиве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'А што буде рода, даћете пето Фараону, а четири дијела нека буду вама за сјеме по њивама и за храну вама и онијема који су по кућама вашим и за храну дјеци вашој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'А они рекоше: ти си нам живот сачувао; нека нађемо милост пред господарем својим да будемо робови Фараону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'И постави Јосиф закон до данашњега дана за њиве Мисирске да се даје пето Фараону; само њиве свештеничке не посташе Фараонове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'А дјеца Израиљева живљаху у земљи Мисирској у крају Гесемском, и држаху га, и народише се и намножише се веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'И Јаков поживје у земљи Мисирској седамнаест година; а свега би Јакову сто и четрдесет и седам година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'А кад се приближи вријеме Израиљу да умре, дозва сина својега Јосифа, и рече му: ако сам нашао милост пред тобом, метни руку своју под стегно моје, и учини ми милост и вјеру, немој ме погрепсти у Мисиру;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Него нека лежим код отаца својих; и ти ме однеси из Мисира и погреби ме у гробу њихову. А он рече: учинићу како си казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'И рече му Јаков: закуни ми се. И он му се закле. И поклони се Израиљ преко узглавља од одра својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Послије јавише Јосифу: ено, отац ти је болестан. А он поведе са собом два сина своја, Манасију и Јефрема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'И јавише Јакову и рекоше: ево син твој Јосиф иде к теби. А Израиљ се окријепи, те сједе на постељи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'И рече Јаков Јосифу: Бог свемогући јави се мени у Лузу у земљи Хананској, и благослови ме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'И рече ми: учинићу те да нарастеш и намножиш се; и учинићу од тебе мноштво народа, и даћу земљу ову сјемену твојему након тебе да је њихова довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Сада дакле два сина твоја, што ти се родише у земљи Мисирској прије него дођох к теби у Мисир, моји су, Јефрем и Манасија као Рувим и Симеун нека буду моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'А дјеца коју родиш послије њих, нека буду твоја и нека се по имену браће своје зову у нашљедству својем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Јер кад се вратих из Падана, умрије ми Рахиља у земљи Хананској на путу, кад бјеше још мало до Ефрате; и погребох је на путу у Ефрату, а то је Витлејем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'А видјев Израиљ синове Јосифове, рече: ко су ови?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'А Јосиф рече оцу својему: моји синови, које ми Бог даде овдје. А он рече: доведи их к мени, да их благословим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'А очи бјеху Израиљу отежале од старости, те не могаше добро видјети. А кад му их приведе, цијелива их и загрли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'И рече Израиљ Јосифу: нијесам мислио да ћу видјети лице твоје; а гле, Бог ми даде да видим и пород твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'А Јосиф одмаче их од кољена његовијех и поклони се лицем до земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Па их узе Јосиф обојицу, Јефрема себи с десне стране а Израиљу с лијеве, Манасију пак себи с лијеве стране а Израиљу с десне; и тако их примаче к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'А Израиљ пружив десну руку своју метну је на главу Јефрему млађему, а лијеву на главу Манасији, тако намјестив руке навлаш, ако и јест Манасија био првенац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'И благослови Јосифа говорећи: Бог, којему су свагда угађали оци моји Аврам и Исак, Бог, који ме је хранио од како сам постао до данашњега дана,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Анђео, који ме је избављао од свакога зла, да благослови дјецу ову, и да се по мојему имену и по имену отаца мојих Аврама и Исака прозову, и да се као рибе намноже на земљи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'А Јосиф кад видје гдје отац метну десну руку своју на главу Јефрему, не би му мило, па ухвати за руку оца својега да је премјести с главе Јефремове на главу Манасијину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'И рече Јосиф оцу својему: не тако, оче; ово је првенац, метни десницу њему на главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Али отац његов не хтје, него рече: знам, сине, знам; и од њега ће постати народ, и он ће бити велик; али ће млађи брат његов бити већи од њега, и сјеме ће његово бити велико мноштво народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'И благослови их у онај дан и рече: тобом ће Израиљ благосиљати говорећи: Бог да те учини као Јефрема и као Манасију. Тако постави Јефрема пред Манасију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Послије рече Израиљ Јосифу: ево ја ћу скоро умријети; али ће Бог бити с вама и одвешће вас опет у земљу отаца ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'И ја ти дајем један дио више него браћи твојој, који узех из руку Аморејских мачем својим и луком својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Послије сазва Јаков синове своје и рече: скупите се да вам јавим шта ће вам бити до пошљетка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Скупите се и послушајте, синови Јаковљеви, послушајте Израиља оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Рувиме, ти си првенац мој, крјепост моја и почетак силе моје; први господством и први снагом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Навро си као вода; нећеш бити први; јер си стао на постељу оца својега и оскврнио је легав на њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Симеун и Левије, браћа, мачеви су им оружје неправди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'У тајне њихове да не улази душа моја, са збором њиховијем да се не саставља слава моја; јер у гњеву својем побише људе, и за своје весеље покидаше волове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Проклет да је гњев њихов, што бјеше нагао, и љутина њихова, што бјеше жестока; раздијелићу их по Јакову, и расућу их по Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Јуда, тебе ће хвалити браћа твоја, а рука ће ти бити за вратом непријатељима твојим, и клањаће ти се синови оца твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Лавићу Јуда! с плијена си се вратио, сине мој; спусти се и леже као лав и као љути лав; ко ће га пробудити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Палица владалачка неће се одвојити од Јуде нити од ногу његовијех онај који поставља закон, докле не дође онај коме припада, и њему ће се покоравати народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Веже за чокот магаре своје, и за племениту лозу младе од магарице своје; у вину пере хаљину своју и огртач свој у соку од грожђа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Очи му се црвене од вина и зуби бијеле од млијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Завулон ће живјети покрај мора и гдје пристају лађе, а међа ће му бити до Сидона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Исахар је магарац јак у костима, који лежи у тору,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'И видјев да је почивање добро и да је земља мила, сагнуће рамена своја да носи, и плаћаће данак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Дан ће судити својему народу, као једно између племена Израиљевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Дан ће бити змија на путу и гуја на стази, која уједа коња за кичицу, те пада коњик наузнако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Господе, тебе чекам да ме избавиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'А Гад, њега ће војска свладати; али ће најпослије он надвладати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'У Асира ће бити обилата храна, и он ће давати сласти царске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Нефталим је кошута пуштена, и говориће лијепе ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Јосиф је родна грана, родна грана крај извора, којој се огранци раширише сврх зида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Ако га и уцвијелише љуто и стријељаше на њ, и бише му непријатељи стријелци,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Опет оста јак лук његов и ојачаше мишице руку његовијех од руку јакога Бога Јаковљева, одакле поста пастир, камен Израиљу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Од силнога Бога оца твојега, који ће ти помагати, и од свемогућега, који ће те благословити благословима озго с неба, благословима оздо из бездана, благословима од дојака и од материце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Благослови оца твојега надвисише благослове мојих старијех сврх брда вјечнијех, нека буду над главом Јосифовом и над тјеменом одвојенога између браће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Венијамин је вук грабљиви, јутром једе лов, а вечером дијели плијен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Ово су дванаест племена Израиљевих, и ово им отац изговори кад их благослови, свако благословом његовијем благослови их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Потом им заповједи и рече им: кад се приберем к роду својему, погребите ме код отаца мојих у пећини која је на њиви Ефрона Хетејина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'У пећини која је на њиви Макпелској према Мамрији у земљи Хананској, коју купи Аврам с њивом у Ефрона Хетејина да има свој гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Ондје погребоше Аврама и Сару жену његову, ондје погребоше Исака и Ревеку жену његову, и ондје погребох Лију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'А купљена је њива и пећина на њој у синова Хетовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'А кад изговори Јаков заповјести синовима совјим, диже ноге своје на постељу, и умрије, и прибран би к роду својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Тада Јосиф паде на лице оцу својему, и плака над њим цјелујући га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'И заповједи Јосиф слугама својим љекарима да мирисима помажу оца његова; и љекари помазаше мирисима Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'И наврши му се четрдесет дана, јер толико дана треба онијем које помажу мирисима; и плакаше за њим Мисирци седамдесет дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'А кад прођоше жалосни дани, рече Јосиф домашњима Фараоновијем говорећи: ако сам нашао милост пред вама, говорите Фараону и реците:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Отац ме је мој заклео говорећи: ево, ја ћу скоро умријети; у гробу мојем, који ископах у земљи Хананској, ондје ме погреби. Па сада да идем да погребем оца својега, а послије ћу опет доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'А Фараон му рече: иди, погреби оца својега како те је заклео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'И отиде Јосиф да погребе оца својега; и с њим пођоше све слуге Фараонове, старјешине од дома његова и све старјешине од земље Мисирске,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'И сав дом Јосифов и браћа његова и дом оца његова; само дјецу своју и овце своје и говеда своја оставише у земљи Гесемској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'А пође с њим кола и коњаника толико да бјеше војска врло велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'А кад дођоше на гумно Атадово, које је с ону страну Јордана, плакаше ондје много и врло тужно; и Јосиф учини жалост за оцем својим за седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'А људи из оне земље, Хананејци, кад видјеше плач на гумну Атадову, рекоше: у великој су жалости Мисирци. Зато прозваше оно мјесто с ону страну Јордана жалост Мисирска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'И учинише му синови његови како им бјеше заповједио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Однесоше га синови његови у земљу Хананску, и погребоше га у пећини на њиви Макпелској, коју купи Аврам да има свој гроб у Ефрона Хетејина према Мамрији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'И погребавши оца својега врати се Јосиф у Мисир и браћа његова и сви који бијаху изашли с њим да погребу оца његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'А браћа Јосифова видећи гдје им отац умрије, рекоше: може бити да се Јосиф срди на нас, па ће нам се осветити за све зло што му учинисмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Зато поручише Јосифу: отац твој заповједи на смрти и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Овако кажите Јосифу: молим те, опрости браћи својој безакоње и гријех, што ти пакостише; сада опрости безакоње слугама Бога оца твојега. А Јосиф заплака се кад му то рекоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Послије дођоше и браћа његова и падоше пред њим и рекоше: ево смо слуге твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'А Јосиф им рече: не бојте се, зар сам ја мјесто Бога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Ви сте мислили зло по ме, али је Бог мислио добро, да учини што се данас збива, да се сачува у животу многи народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Не бојте се дакле; ја ћу хранити вас и вашу дјецу. Тако их утјеши и ослободи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Тако живљаше Јосиф у Мисиру с домом оца својега, и поживје сто и десет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'И видје Јосиф синове Јефремове до трећега кољена; и синови Махира сина Манасијина родише се и одрастоше на кољенима Јосифовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'И рече Јосиф браћи својој: ја ћу скоро умријети; али ће вас зацијело Бог походити, и извешће вас из ове земље у земљу за коју се заклео Авраму, Исаку и Јакову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'И закле Јосиф синове Израиљеве и рече: заиста ће вас походити Бог; а ви онда однесите кости моје одавде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Потом умрије Јосиф, а бјеше му сто и десет година; и помазавши га мирисима метнуше га у ковчег у Мисиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Ово су имена синова Израиљевијех који дођоше у Мисир, дођоше с Јаковом, сваки са својом породицом:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Рувим, Симеун, Левије и Јуда,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Исахар, Завулон и Венијамин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Дан и Нефталим, Гад и Асир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'А свега бијаше их од бедара Јаковљевијех седамдесет душа с Јосифом, који бјеше у Мисиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'А Јосиф умрије и сва браћа његова и сав онај нараштај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'И синови Израиљеви народише се и умножише се, и напредоваше и осилише веома, да их се земља напуни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Тада наста нов цар у Мисиру, који не знадијаше за Јосифа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'И рече народу својему: гле, народ синова Израиљевијех већи је и силнији од нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Него хајде мудро да поступамо с њима, да се не множе, и кад настане рат да не пристану с непријатељима нашим и не ударе на нас и не отиду из земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'И поставише над њима настојнике да их муче тешким пословима; и грађаше народ Израиљев Фараону градове Питом и Рамесу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Али што га више мучаху то се више множаше и напредоваше, да се грожаху од синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'И жестоко нагоњаху Мисирци синове Израиљеве на послове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'И загрчиваху им живот тешким пословима, блатом и опекама и сваким радом у пољу, и сваким другим послом, на који их жестоко нагоњаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'И још заповједи цар Мисирски бабицама Јеврејским, од којих једној бјеше име Сефора а другој Фува,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'И рече: кад бабичите Јеврејке, и у порођају видите да је мушко, убијте га, а кад буде женско, нек остане живо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Али се бабице бојаху Бога, и не чињаху како им рече цар Мисирски, него остављаху дјецу у животу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'А цар Мисирски дозва бабице, и рече им: зашто то чините, те остављате у животу мушку дјецу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'А бабице рекоше Фараону: Јеврејке нису као жене Мисирке; јаче су; док им дође бабица, оне већ роде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'И Бог учини добро бабицама; и народ се умножи и осили веома;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'И што се бабице бојаху Бога, начини им куће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Тада заповједи Фараон свему народу својему говорећи: свакога сина који се роди баците у воду, а кћери све остављајте у животу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'А неко од племена Левијева отиде и ожени се кћерју Левијевом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'И она затрудње и роди сина; и видјећи га лијепа кријаше га три мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'А кад га не може више крити, уже ковчежић од сите, и обли га смолом и паклином, и метну дијете у њ, и однесе га у трску крај ријеке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'А сестра његова стаде подаље да види шта ће бити од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'А кћи Фараонова дође да се купа у ријеци, и дјевојке њезине ходаху крај ријеке; и она угледа ковчежић у трсци, и посла дворкињу своју те га извади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'А кад отвори, видје дијете, и гле, дијете плакаше; и сажали јој се, и рече: то је Јеврејско дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Тада рече сестра његова кћери Фараоновој: хоћеш ли да идем да ти дозовем дојкињу Јеврејку, да ти доји дијете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'А кћи Фараонова рече јој: иди. И отиде дјевојчица, и дозва матер дјетињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'И кћи Фараонова рече јој: узми ово дијете, и одој ми га, а ја ћу ти платити. И узе жена дијете и одоји га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'А кад дијете одрасте, одведе га ка кћери Фараоновој, а она га посини; и надједе му име Мојсије говорећи: јер га из воде извадих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'И кад Мојсије бијаше велик, изиде к браћи својој, и гледаше невољу њихову. И видје гдје некакав Мисирац бије човјека Јеврејина између браће његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'И обазрев се и тамо и амо, кад видје да нема никога, уби Мисирца, и закопа га у пијесак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'И сјутрадан изиде опет, а то се два Јеврејина свађаху, и рече оному који чињаше криво: зашто бијеш ближњега својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'А он рече: ко је тебе поставио кнезом и судијом над нама? хоћеш ли да ме убијеш као што си убио Мисирца? Тада се Мојсије уплаши и рече: заиста се дознало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'И Фараон чув за то тражаше да погуби Мојсија. Али Мојсије побјеже од Фараона и дође у земљу Мадијамску, и сједе код једнога студенца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'А свештеник Мадијамски имаше седам кћери, и оне дођоше и стадоше захватати воду и наљевати у појила да напоје стадо оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'А дођоше пастири, и отјераше их; а Мојсије уста и одбрани их, и напоји им стадо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'И оне се вратише к оцу својему Рагуилу; а он рече: што се данас тако брзо вратисте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'А оне рекоше: један Мисирац одбрани нас од пастира, и нали нам и напоји стадо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'А он рече кћерима својим: па гдје је? зашто остависте тога човјека? зовите га да једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'И Мојсије се склони да живи код онога човјека, и он даде Мојсију кћер своју Сефору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'И она роди сина, и он му надједе име Гирсам, јер сам, рече, дошљак у земљи туђој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'А послије много времена умрије цар Мисирски; и уздисаху од невоље синови Израиљеви и викаху; и вика њихова ради невоље дође до Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'И Бог чу уздисање њихово, и опомену се Бог завјета својега с Аврамом, с Исаком и с Јаковом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'И погледа Бог на синове Израиљеве, и видје их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'А Мојсије пасијаше стадо Јотору тасту својему, свештенику Мадијамскому, и одведе стадо преко пустиње, и дође на гору Божију Хорив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'И јави му се анђео Господњи у пламену огњеном из купине. И погледа, а то купина огњем гори а не сагоријева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'И Мојсије рече: идем да видим ту утвару велику, зашто не сагоријева купина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'А Господ кад га видје гдје иде да види, викну га Бог из купине, и рече: Мојсије! Мојсије! А он одговори: ево ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'А Бог рече: не иди овамо. Изуј обућу своју с ногу својих, јер је мјесто гдје стојиш света земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Још рече: ја сам Бог оца твојега, Бог Аврамов, Бог Исаков и Бог Јаковљев. А Мојсије заклони лице своје, јер га страх бијаше гледати у Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'И рече Господ: добро видјех невољу народа својега у Мисиру, и чух вику његову од зла које му чине настојници, јер познах муку његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'И сиђох да га избавим из руку Мисирских, и да га изведем из оне земље у земљу добру и пространу, у земљу гдје млијеко и мед тече, на мјесто гдје су Хананеји и Хетеји и Амореји и Ферезеји и Јевеји и Јевусеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'И сада ево вика синова Израиљевијех дође преда ме, и видјех муку, којом их муче Мисирци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Сада хајде да те пошљем к Фараону, да изведеш народ мој, синове Израиљеве, из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'А Мојсије рече Богу: ко сам ја да идем к Фараону и да изведем синове Израиљеве из Мисира?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'А Бог му рече: ја ћу бити с тобом, и ово нека ти буде знак да сам те ја послао: кад изведеш народ из Мисира, служићете Богу на овој гори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'А Мојсије рече Богу: ево, кад отидем к синовима Израиљевијем, па им речем: Бог отаца ваших посла ме к вама, ако ми реку: како му је име? шта ћу им казати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'А Господ рече Мојсију: ја сам онај што јест. И рече: тако ћеш казати синовима Израиљевијем: који јест, он ме посла к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'И опет рече Бог Мојсију: овако кажи синовима Израиљевијем: Господ Бог отаца ваших, Бог Аврамов, Бог Исаков и Бог Јаковљев посла ме к вама; то је име моје довијека, и то је спомен мој од кољена на кољено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Иди, и скупи старјешине Израиљске, па им реци: Господ Бог отаца ваших јави ми се, Бог Аврамов, Исаков и Јаковљев, говорећи: доиста обидох вас, и видјех како вам је у Мисиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Па рекох: извешћу вас из невоље Мисирске у земљу Хананејску и Хетејску и Аморејску и Ферезејску и Јевејску и Јевусејску, у земљу гдје тече млијеко и мед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'И они ће послушати глас твој; па ћеш ти и старјешине Израиљске отићи к цару Мисирском, и рећи ћете му: Господ Бог Јеврејски срете нас, па ти се молимо да изидемо три дана хода у пустињу да принесемо жртву Господу Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'А ја знам да вам неће допустити цар Мисирски да изидете без руке крјепке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Али ћу пружити руку своју, и ударићу Мисир свијем чудесима својим, која ћу учинити у њему: и послије ће вас пустити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'И учинићу да народ нађе љубав у Мисираца, па кад пођете, нећете поћи празни;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Него ће свака жена заискати у сусједе своје и у домаћице своје накита сребрнога и накита златнога и хаљина; и метнућете на синове своје и на кћери своје, и оплијенићете Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'А Мојсије одговори и рече: али неће ми вјеровати ни послушати гласа мојега; јер ће рећи: није ти се Господ јавио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'А Господ му рече: шта ти је то у руци? А он одговори: штап.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'А Бог му рече: баци га на земљу. И баци га на земљу, а он поста змија. И Мојсије побјеже од ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'А Господ рече Мојсију: пружи руку своју, па је ухвати за реп. И пружи руку своју, и ухвати је, и опет поста штап у руци његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'То учини, рече Господ, да вјерују да ти се јавио Господ Бог отаца њиховијех, Бог Аврамов, Бог Исаков и Бог Јаковљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'И опет му рече Господ: тури сада руку своју у њедра своја. И он тури руку своју у њедра своја; а кад је извади из њедара, а то рука му губава, бијела као снијег.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'А Бог му рече: тури опет руку своју у њедра своја. И опет тури руку своју у њедра своја; а кад је извади из њедара, а то опет постала као и остало тијело његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Тако, рече Бог, ако ти не узвјерују и не послушају гласа твојега за први знак, послушаће за други знак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Ако ли не узвјерују ни за та два знака и не послушају гласа твојега, а ти захвати воде из ријеке, и пролиј на земљу, и претвориће се вода коју захватиш из ријеке, и проврћи ће се у крв на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'А Мојсије рече Господу: молим ти се, Господе, нијесам рјечит човјек, нити сам прије био нити сам откако си проговорио са слугом својим, него сам споријех уста и спора језика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'А Господ му рече: ко је дао уста човјеку? или ко може створити нијема или глуха или оката или слијепа? зар не ја, Господ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Иди дакле, ја ћу бити с устима твојим, и учићу те шта ћеш говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'А Мојсије рече: молим те, Господе, пошљи онога кога треба да пошљеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'И разгњеви се Господ на Мојсија, и рече му: није ли ти брат Арон Левит? знам да је он рјечит; и ево он ће те срести, и кад те види обрадоваће се у срцу својем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Њему ћеш казати и метнућеш ове ријечи у уста његова, и ја ћу бити с твојим устима и с његовијем устима, и учићу вас шта ћете чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'И он ће мјесто тебе говорити народу, и он ће бити теби мјесто уста а ти ћеш бити њему мјесто Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'А тај штап узми у руку своју, њим ћеш чинити чудеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'И отиде Мојсије, и врати се к Јотору тасту својему, и рече му: пусти ме да идем, да се вратим к браћи својој у Мисиру, да видим јесу ли јоште у животу. И рече Јотор Мојсију: иди с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'И рече Господ Мојсију у земљи Мадијамској: иди, врати се у Мисир, јер су помрли сви који су тражили душу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'И узе Мојсије жену своју и синове своје, и посади их на магарца, и пође натраг у земљу Мисирску. И узе Мојсије штап Божји у руку своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'И рече Господ Мојсију: кад отидеш и вратиш се у Мисир, гледај да учиниш пред Фараоном сва чудеса која ти метнух у руку: а ја ћу учинити да му отврдне срце и не пусти народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'А ти ћеш рећи Фараону: овако каже Господ: Израиљ је син мој, првенац мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'И казах ти: пусти сина мојега да ми послужи. А ти га не хтје пустити; ево ја ћу убити сина твојега, првенца твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'И кад бијаше на путу у гостионици, дође к њему Господ и шћаше да га убије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'А Сефора узе оштар нож, и обреза сина својега, и окрајак баци к ногама његовијем говорећи: ти си ми крвав заручник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Тада га остави Господ; а она ради обрезања рече: крвав заручник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'А Господ рече Арону: изиди у пустињу на сусрет Мојсију. И отиде и срете га на гори Божијој, и пољуби га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'И Мојсије каза Арону све ријечи Господње, за које га посла, и све знаке које му заповједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'И отидоше Мојсије и Арон, и скупише све старјешине синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'И Арон каза све ријечи, које бјеше рекао Господ Мојсију, а Мојсије учини знаке пред народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'И народ вјерова; и разумјеше да је Господ походио синове Израиљеве и видио невољу њихову; и савивши се поклонише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'А послије изиде Мојсије и Арон пред Фараона, и рекоше му: овако вели Господ Бог Израиљев: пусти народ мој да ми празнују празник у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Али Фараон рече: ко је Господ да послушам глас његов и пустим Израиља? Не знам Господа, нити ћу пустити Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'А они рекоше: Бог Јеврејски срете нас; молимо ти се да отидемо три дана хода у пустињу да принесемо жртву Господу Богу својему, да не пошље на нас помор или мач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'А цар Мисирски рече им: Мојсије и Ароне, зашто одвлачите народ од рада његова? Идите на свој посао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Још рече Фараон: ето, народа је много у земљи; а ви још хоћете да оставља своје послове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'И у исти дан заповједи Фараон настојницима над народом и управитељима његовијем, и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Отселе немојте давати народу пљеве за опеке као дослије, нека иду сами и купе себи пљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'А колико су опека дослије начињали толико изгоните и отселе, нити што смањите; јер беспосличе, и зато вичу говорећи: да идемо да принесемо жртву Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Ваља навалити послове на те људе, па ће радити и неће слушати лажљивијех ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'И изашавши настојници народни и управитељи рекоше народу говорећи: тако вели Фараон: ја вам нећу давати пљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Идите сами и купите себи пљеве гдје нађете, а од посла вам се неће попустити ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'И разиде се народ по свој земљи Мисирској да чува стрњику мјесто пљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'А настојници наваљиваху говорећи: свршујте послове своје колико долази на дан, као кад је било пљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'И управитељи синова Израиљевијех, које поставише над њима настојници Фараонови, допадаху боја, и говораше им се: зашто ни јуче ни данас не начинисте онолико опека колико вам је одређено, као прије?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'И отидоше управитељи синова Израиљевијех, и повикаше к Фараону говорећи: зашто чиниш тако слугама својим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Пљева се не даје слугама твојим, па опет кажу нам: градите опеке. И ево бију слуге твоје, а крив је твој народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'А он рече: беспосличите, беспосличите, и зато говорите: да идемо да принесемо жртву Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Него идите, радите; пљева вам се неће давати, а опеке да дајете на број.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'И управитељи синова Израиљевијех видјеше да је зло по њих што им се каза: да не буде опека мање на дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'И отишавши од Фараона сретоше Мојсија и Арона, који изидоше пред њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Па им рекоше: Господ нека вас види и суди, што нас омразисте Фараону и слугама његовијем, и дадосте им мач у руку да нас побију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'И Мојсије се врати ка Господу и рече: Господе, зашто си навукао то зло на народ? зашто си ме послао?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Јер откако изидох пред Фараона и проговорих у твоје име, још горе поступа с народом овијем, а ти не избави народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'А Господ рече Мојсију: сад ћеш видјети шта ћу учинити Фараону; јер под руком крјепком пустиће их, и истјераће их из земље своје под руком крјепком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Још говори Бог Мојсију и рече му: ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'И јавио сам се Авраму, Исаку и Јакову именом Бог свемогући, а именом својим Господ не бих им познат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'И учиних завјет свој с њима да ћу им дати земљу Хананску, земљу у којој бијаху дошљаци, у којој живљаху као странци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'И чух уздисање синова Израиљевијех, које Мисирци држе у ропству, и опоменух се завјета својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Зато кажи синовима Израиљевијем: ја сам Господ, и извешћу вас испод бремена Мисирских, и опростићу вас ропства њихова, и избавићу вас мишицом подигнутом и судовима великим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'И узећу вас да ми будете народ, и ја ћу вам бити Бог, те ћете познати да сам ја Господ Бог ваш, који вас изводим испод бремена Мисирских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Пак ћу вас одвести у своју земљу, за коју подигох руку своју заклињући се да ћу је дати Авраму, Исаку и Јакову; и даћу вам је у нашљедство, ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'И Мојсије каза тако синовима Израиљевијем; али не послушаше Мојсија од слабости духа својега и од љутога ропства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'И Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Иди, кажи Фараону цару Мисирском нека пусти синове Израиљеве из земље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'А Мојсије проговори пред Господом и рече: ето, синови Израиљеви не послушаше ме, а како ће ме послушати Фараон, кад сам необрезанијех усана?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Али Господ говори Мојсију и Арону, и заповједи им да иду к синовима Израиљевијем и к Фараону, да изведу синове Израиљеве из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Ово су поглавице у домовима отаца својих: синови Рувима првенца Израиљева: Енох и Фалуј, Асрон и Хармија; то су породице Рувимове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'А синови Симеунови: Јемуило и Јамин и Аод и Ахин и Сар и Саул, син неке Хананејке; то су породице Симеунове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'А ово су имена синова Левијевих по породицама њиховијем: Гирсон и Кат и Мерарије; а Левије поживје сто и тридесет и седам година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'А ово су синови Гирсонови: Ловеније и Семеј по породицама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'А синови Катови: Амрам и Исар и Хеврон и Озило; а Кат поживје сто и тридесет и три године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'А синови Мераријеви: Молија и Мусија. То су породице Левијеве по лозама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'А Амрам се ожени Јохаведом братучедом својом, и она му роди Арона и Мојсија. А поживје Амрам сто и тридесет и седам година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'А синови Исарови бјеху: Кореј и Нафек и Зехрија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'А синови Озилови: Мисаило и Елисафан и Сегрија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'А Арон се ожени Јелисаветом кћерју Аминадавовом, сестром Насоновом; и она му роди Надава и Авијуда и Елеазара и Итамара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'А синови Корејеви бјеху: Асир и Елкана и Авијасар. То су породице Корејеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'И Елеазар син Аронов ожени се једном од кћери Футиловијех, и она му роди Финеса. То су поглавице између отаца Левитских по својим породицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'То је Арон и Мојсије, којима рече Господ: изведите синове Израиљеве из земље Мисирске у четама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'То су који говорише Фараону цару Мисирском да изведу синове Израиљеве из Мисира; то је Мојсије и то је Арон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'И кад Господ говораше Мојсију у земљи Мисирској,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Рече Господ Мојсију говорећи: ја сам Господ; кажи Фараону цару Мисирском све што сам ти казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'И Мојсије рече пред Господом: ево сам необрезанијех усана, па како ће ме послушати Фараон?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'И Господ рече Мојсију: ево, поставио сам те да си Бог Фараону; а Арон брат твој биће пророк твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Говорићеш све што ти заповједим; Арон пак брат твој говориће Фараону да пусти синове Израиљеве из земље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'А ја ћу учинити да отврдне срце Фараону, те ћу умножити знаке своје и чудеса своја у земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'И неће вас ипак послушати Фараон; а ја ћу метнути руку своју на Мисир, и извешћу војску своју, народ свој, синове Израиљеве из земље Мисирске судовима великим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'И познаће Мисирци да сам ја Господ, кад дигнем руку своју на Мисир, и изведем синове Израиљеве између њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'И учини Мојсије и Арон, како им заповједи Господ, тако учинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'А Мојсију бијаше осамдесет година, а Арону осамдесет и три године, кад говораху с Фараоном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'И рече Господ Мојсију и Арону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Кад вам каже Фараон и рече: учините како чудо, онда реци Арону: узми штап свој, и баци га пред Фараона; те ће се прометнути у змију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'И изађоше Мојсије и Арон пред Фараона, и учинише како заповједи Господ; и баци Арон штап свој пред Фараона и пред слуге његове, и прометну се у змију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'А Фараон дозва мудраце и врачаре; те и врачари Мисирски учинише тако својим врачањем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'И бацише сваки свој штап, и прометнуше се штапови у змије; али штап Аронов прождрије њихове штапове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'И отврдну срце Фараоново, и не послуша их, као што бјеше казао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'И рече Господ Мојсију: отежа срце Фараоново; неће да пусти народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Иди ујутру к Фараону. Гле, он ће изаћи на воду, па стани према њему на обали, а штап који се био прометнуо у змију узми у руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'И реци му: Господ Бог Јеврејски посла ме к теби да ти кажем: пусти народ мој да ми послужи у пустињи. Али ти ето још не послуша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Зато Господ овако вели: овако ћеш познати да сам ја Господ: ево, ударићу штапом што ми је у руци по води што је у ријеци, и прометнуће се у крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'И рибе у ријеци помријеће, и ријека ће се усмрдјети, и Мисирци ће се узмучити тражећи воде да пију из ријеке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'И Господ рече Мојсију: реци Арону: узми штап свој, и пружи руку своју на воде Мисирске, на потоке, на ријеке и на језера њихова и на сва зборишта вода њиховијех; и прометнуће се у крв, и биће крв по свој земљи Мисирској, и по судима дрвенијем и каменијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'И учинише Мојсије и Арон како им заповједи Господ; и подигав Арон штап свој удари по води која бјеше у ријеци пред Фараоном и слугама његовијем. И сва вода што бјеше у ријеци прометну се у крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'И помријеше рибе што бијаху у ријеци, и усмрдје се ријека тако да не могаху Мисирци пити воде из ријеке, и бјеше крв по свој земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Али и врачари Мисирски учинише тако својим врачањем; и срце Фараону отврдну, те их не послуша, као што бјеше казао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'И окренув се Фараон отиде кући својој, и не мари ни за то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'А Мисирци сви копаше око ријеке тражећи воде да пију; јер не могаху пити воде из ријеке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'И наврши се седам дана како ријеку удари Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'И рече Господ Мојсију: иди к Фараону, и реци му: овако вели Господ: пусти народ мој, да ми послужи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Ако ли нећеш пустити, ево ћу морити сву земљу жабама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'И ријека ће се напунити жаба, и оне ће изаћи и скакати теби по кући и по клијети гдје спаваш и по постељи твојој и по кућама слуга твојих и народа твојега и по пећима твојим и по наћвама твојим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'И на тебе и на народ твој и на све слуге твоје скакаће жабе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'И рече Господ Мојсију: кажи Арону: пружи руку своју са штапом својим на ријеке и на потоке и на језера, и учини нек изађу жабе на земљу Мисирску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'И пружи Арон руку своју на воде Мисирске, и изађоше жабе и покрише земљу Мисирску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Али и врачари Мисирски учинише тако својим врачањем, учинише те изађоше жабе на земљу Мисирску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'А Фараон дозва Мојсија и Арона и рече: молите Господа да уклони жабе од мене и од народа мојега, пак ћу пустити народ да принесу жртву Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'А Мојсије рече Фараону: част да ти је нада мном! докле да му се молим за те и за слуге твоје и за народ твој да одбије жабе од тебе и из кућа твојих, и само у ријеци да остану?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'А он рече: до сјутра. А Мојсије рече: биће како си казао, да познаш да нико није као Господ Бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Отићи ће жабе од тебе и из кућа твојих и од слуга твојих и од народа твојега; само ће у ријеци остати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'И отиде Мојсије и Арон од Фараона; и завапи Мојсије ка Господу за жабе које бјеше пустио на Фараона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'А Господ учини по ријечи Мојсијевој; и поцркаше жабе, и опростише их се куће и села и поља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'И на гомиле их гртаху, да је смрдјела земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'А кад Фараон видје гдје одахну, отврдну му срце, и не послуша их, као што бјеше казао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'А Господ рече Мојсију: кажи Арону: пружи штап свој, и удари по праху на земљи, нек се претвори у уши по свој земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'И учинише тако: Арон пружи руку своју са штапом својим, и удари по праху на земљи, и посташе уши по људима и по стоци, сав прах на земљи претвори се у уши по цијелој земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'А гледаше и врачари Мисирски врачањем својим да учине да постану уши, али не могоше. И бијаху уши по људима и по стоци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'И рекоше врачари Фараону: ово је прст Божји. Али опет отврдну срце Фараону, те их не послуша као што бјеше казао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'А Господ рече Мојсију: устани рано и изађи пред Фараона, ево, он ће изаћи к води, па му реци: овако вели Господ: пусти народ мој да ми послужи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Ако ли не пустиш народа мојега, ево, пустићу на тебе и на слуге твоје и на народ твој и на куће твоје свакојаке бубине, и напуниће се бубина куће Мисирске и земља на којој су.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Али ћу у тај дан одвојити земљу Гесемску, гдје живи мој народ, и ондје неће бити бубина, да познаш да сам ја Господ на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'И поставићу разлику између народа својега и народа твојега. Сјутра ће бити знак тај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'И учини Господ тако, и дођоше силне бубине у кућу Фараонову и у куће слуга његовијех и у сву земљу Мисирску, да се све у земљи поквари од бубина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'И Фараон дозва Мојсија и Арона, и рече им: идите, принесите жртву Богу својему овдје у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'А Мојсије рече: не ваља тако; јер бисмо принијели на жртву Господу Богу својему што је нечисто Мисирцима; а кад бисмо принијели на жртву што је нечисто Мисирцима на очи њихове, не би ли нас побили камењем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Три дана хода треба да идемо у пустињу да принесемо жртву Господу Богу својему, као што нам је казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'А Фараон рече: пустићу вас да принесете жртву Господу Богу својему у пустињи; али да не идете даље; па се молите за ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'А Мојсије рече: ево ја идем од тебе, и молићу се Господу да отиду бубине од Фараона и од слуга његовијех и од народа његова сјутра; али немој опет да превариш, и да не пустиш народа да принесе жртву Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'И отиде Мојсије од Фараона, и помоли се Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'И учини Господ по ријечи Мојсијевој, те отидоше бубине од Фараона и од слуга његовијех и од народа његова; не оста ни једна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Али опет отврдну срце Фараоново, и не пусти народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Тада рече Господ Мојсију: иди к Фараону, и реци му: овако вели Господ Бог Јеврејски: пусти народ мој да ми послужи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Ако ли их не пустиш него их још станеш задржавати,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Ево, рука Господња доћи ће на стоку твоју у пољу, на коње, на магарце, на камиле, на волове и на овце, с помором врло великим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'А одвојиће Господ стоку Израиљску од стоке Мисирске; те од свега што је синова Израиљевијех неће погинути ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'И поставио је Господ рок рекавши: сјутра ће то учинити на земљи Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'И Господ учини то сјутрадан, и сва стока Мисирска угину; а од стоке синова Израиљевијех не угину ниједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'И посла Фараон да виде, и гле, од стоке Израиљске не угину ниједно; ипак отврдну срце Фараону, и не пусти народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Тада рече Господ Мојсију и Арону: узмите пепела из пећи пуне прегршти, и Мојсије нека га баци у небо пред Фараоном;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'И постаће прах по свој земљи Мисирској, а од њега ће постати красте пуне гноја и на људима и на стоци по свој земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'И узеше пепела из пећи, и стадоше пред Фараона, и баци га Мојсије у небо, и посташе красте пуне гноја по људима и по стоци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'И врачари не могоше стајати пред Мојсијем од краста; јер бијаху красте и на врачарима и на свијем Мисирцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'И Господ учини те отврдну срце Фараоново, и не послуша их, као што бјеше казао Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Послије рече Господ Мојсију: устани рано и изађи пред Фараона, и реци му: овако вели Господ Бог Јеврејски: пусти народ мој да ми послужи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Јер ћу сада пустити сва зла своја на срце твоје и на слуге твоје и на народ твој, да знаш да нико није као ја на цијелој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Јер сада кад пружих руку своју, могах и тебе и народ твој ударити помором, па те не би више било на земљи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Али те оставих да покажем на теби силу своју, и да се приповиједа име моје по свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'И ти се још подижеш на мој народ, и нећеш да га пустиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Ево, сјутра ћу у ово доба пустити град врло велик, какога није било у Мисиру откако је постао па досада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Зато сада пошљи, те скупи стоку своју и што год имаш у пољу, јер ће пасти град на све људе и на стоку што се затече у пољу и не буде скупљено у кућу, и изгинуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Који се год између слуга Фараоновијех побоја ријечи Господње, он брже скупи слуге своје и стоку своју у кућу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'А који не мараше за ријеч Господњу, он остави слуге своје и стоку своју у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'И Господ рече Мојсију: пружи руку своју к небу, нека удари град по свој земљи Мисирској, на људе и на стоку и на све биље по пољу у земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'И Мојсије пружи штап свој к небу, и Господ пусти громове и град, да огањ скакаше на земљу. И тако Господ учини, те паде град на земљу Мисирску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'А бјеше град и огањ смијешан с градом силан веома, какога не бјеше у свој земљи Мисирској откако је људи у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'И поби град по свој земљи Мисирској што год бјеше у пољу од човјека до живинчета; и све биље у пољу потр град, и сва дрвета у пољу поломи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Само у земљи Гесемској, гдје бијаху синови Израиљеви, не бјеше града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Тада посла Фараон, те дозва Мојсија и Арона, и рече им: сада згријеших; Господ је праведан, а ја и мој народ јесмо безбожници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Молите се Господу, јер је доста, нека престану громови Божји и град, па ћу вас пустити, и више вас неће нико устављати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'А Мојсије му рече: кад изађем иза града, раширићу руке своје ка Господу, а громови ће престати и града неће више бити, да знаш да је Господња земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'А ти и слуге твоје знам да се још нећете бојати Господа Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'И пропаде лан и јечам, јер јечам бјеше класао, а лан се главичио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'А пшеница и крупник не пропаде, јер бјеше позно жито.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'И Мојсије отишав од Фараона иза града рашири руке своје ка Господу, и престаше громови и град, и дажд не падаше на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Али Фараон видјев гдје преста дажд и град и громови, стаде опет гријешити, и срце му отврдну и њему и слугама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Отврдну срце Фараону, те не пусти синова Израиљевијех, као што бјеше казао Господ преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'А Господ рече Мојсију: иди к Фараону, јер сам ја учинио да отврдне срце његово и срце слуга његовијех, да учиним ове знаке своје међу њима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'И да приповиједаш синовима својим и унуцима својим шта учиних у Мисиру и какве знаке своје показах на њима, да бисте знали да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'И отиде Мојсије и Арон к Фараону, и рекоше му: овако вели Господ Бог Јеврејски: докле ћеш се противити да се не понизиш преда мном? Пусти народ мој да ми послужи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Јер ако нећеш пустити народа мојега, ево сјутра ћу нанијети скакавце на земљу твоју;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'И покриће сву земљу да се неће видјети земље, и појешће остатак што се сачувао, који вам је остао иза града, и појешће сва дрвета што вам расту у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'И напуниће их се куће твоје и куће свијех слуга твојих и куће свијех Мисираца, што нијесу видјели оци твоји ни оци отаца твојих, откако су постали на земљи до данас. И окренув се отиде од Фараона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'А слуге рекоше Фараону: докле ће нас тај мучити? Пусти их нека послуже Господу Богу својему. Зар још не видиш гдје пропаде Мисир?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'И дозваше опет Мојсија и Арона пред Фараона, и рече им: идите, послужите Господу Богу својему. А који су што ће ићи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'А Мојсије рече: с дјецом својом и са старцима својим ићи ћемо, са синовима својим и са кћерима својим, са стоком својом ситном и крупном ићи ћемо, јер имамо празник Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'А он им рече: тако био Господ с вама, како ћу вас ја пустити с дјецом вашом! Видите да зло мислите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Неће бити тако; него ви људи идите и послужите Господу, јер то иштете. И отјера их од себе Фараон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Тада рече Господ Мојсију: пружи руку своју на земљу Мисирску, да дођу скакавци на земљу Мисирску и поједу све биље по земљи, што год оста иза града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'И пружи Мојсије штап свој на земљу Мисирску, и Господ наведе устоку на земљу, те дува цијели дан и цијелу ноћ; а кад свану, донесе устока скакавце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'И дођоше скакавци на сву земљу Мисирску, и попадаше по свијем крајевима Мисирским силни веома, каких прије нигда није било нити ће кад бити онаких.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'И покрише сву земљу, да се земља не виђаше, и поједоше сву траву на земљи и сав род на дрветима, што оста иза града, и не оста ништа зелено од дрвета и од биља пољскога у свој земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Тада Фараон брже дозва Мојсија и Арона, и рече: згријеших Господу Богу вашему и вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Али ми још сада само опрости гријех мој, и молите се Господу Богу својему да уклони од мене само ову смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'И отиде Мојсије од Фараона, и помоли се Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'И окрену Господ вјетар од запада врло јак, који узе скакавце и баци их у Црвено море, и не оста ниједан скакавац у цијелој земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Али Господ учини те отврдну срце Фараону, и не пусти синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'И рече Господ Мојсију: пружи руку своју к небу, и биће тама по земљи Мисирској така да ће је пипати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'И Мојсије пружи руку своју к небу, и поста густа тама по свој земљи Мисирској за три дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Не виђаху један другога, и нико се не маче с мјеста гдје бјеше за три дана; али се код свијех синова Израиљевијех видјело по становима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Тада Фараон дозва Мојсија, и рече: идите, послужите Господу; само стока ваша ситна и крупна нека остане, а дјеца ваша нека иду с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'А Мојсије рече: треба да нам даш и што ћемо принијети и сажећи на жртву Господу Богу својему;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Зато и стока наша нек иде с нама, да не остане ни папка, јер између ње треба да узмемо чим ћемо послужити Господу Богу својему, а не знамо којим ћемо послужити Господу докле не дођемо онамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Али Господ учини те отврдну срце Фараону, и не хтје их пустити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'И рече му Фараон: иди од мене, и чувај се да ми више не дођеш на очи, јер ако ми дођеш на очи, погинућеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'А Мојсије рече: право си казао; нећу ти више доћи на очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'А Господ рече Мојсију: још ћу једно зло пустити на Фараона и на Мисир, па ће вас онда пустити; пустиће сасвијем, и још ће вас тјерати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'А сада кажи народу нека сваки човјек иште у сусједа својега и свака жена у сусједе своје накита сребрнијех и накита златнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'И Господ учини те народ нађе љубав у Мисираца; и сам Мојсије бјеше врло велик човјек у земљи Мисирској код слуга Фараоновијех и код народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'И рече Мојсије: овако вели Господ: око поноћи проћи ћу кроз Мисир,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'И помријеће сви првенци у земљи Мисирској, од првенца Фараонова, који шћаше сједјети на пријестолу његову, до првенца слушкиње за жрвњем, и од стоке што је год првенац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'И биће вика велика по свој земљи Мисирској, какве још није било нити ће је кад бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'А код синова Израиљевијех нигдје неће ни пас језиком својим маћи ни међу људима ни међу стоком, да знате да је Господ учинио разлику између Израиљаца и Мисираца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'И доћи ће све те слуге твоје к мени, и поклониће ми се говорећи: иди, и ти и сав народ који је пристао за тобом. И онда ћу изаћи. И отиде Мојсије од Фараона с великим гњевом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'А Господ рече Мојсију: неће вас послушати Фараон, да бих умножио чудеса своја у земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'И Мојсије и Арон учинише сва ова чудеса пред Фараоном, а Господ учини те отврдну срце Фараону, и не пусти синова Израиљевијех из земље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'И рече Господ Мојсију и Арону у земљи Мисирској говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Овај мјесец да вам је почетак мјесецима, да вам је први мјесец у години.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Кажите свему збору Израиљеву и реците: десетога дана овога мјесеца сваки нека узме јагње или јаре, по породицама, по једно на дом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Ако ли је дом мали за јагње или јаре, нека узме к себи сусједа, који му је најближи, с онолико душа колико треба да могу појести јагње или јаре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'А јагње или јаре да вам буде здраво, мушко, од године; између оваца или између коза узмите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'И чувајте га до четрнаестога дана овога мјесеца, а тада савколики збор Израиљев нека га закоље увече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'И нека узму крви од њега и покропе оба довратка и горњи праг на кућама у којима ће га јести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'И нека једу месо исте ноћи, на ватри печено, с хљебом пријеснијем и са зељем горким нека једу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Немојте јести сирово ни у води кухано, него на ватри печено, с главом и с ногама и с дробом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'И ништа немојте оставити до јутра; ако ли би што остало до јутра, спалите на ватри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'А овако једите: опасани, обућа да вам је на ногу и штап у руци, и једите хитно, јер је пролазак Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Јер ћу проћи по земљи Мисирској ту ноћ, и побићу све првенце у земљи Мисирској од човјека до живинчета, и судићу свијем боговима Мисирским, ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'А крв она биће вам знак на кућама, у којима ћете бити; и кад видим крв, проћи ћу вас, те неће бити међу вама помора, кад станем убијати по земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'И тај ће вам дан бити за спомен, и празноваћете га Господу од кољена до кољена; празнујте га законом вјечнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Седам дана једите хљебове пријесне, и првога дана уклоните квасац из кућа својих; јер ко би год јео што с квасцем од првога дана до седмога, истријебиће се она душа из Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Први дан биће свети сабор; тако и седми дан имаћете свети сабор; никакав посао да се не ради у те дане, осим што треба за јело свакој души, то ћете само готовити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'И држите дан пријеснијех хљебова, јер у тај дан изведох војске ваше из земље Мисирске; држите тај дан од кољена до кољена законом вјечнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Првога мјесеца четрнаести дан увече почните јести пријесне хљебове па до двадесет првога дана истога мјесеца увече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'За седам дана да се не нађе квасца у кућама вашим; јер ко би год јео што с квасцем, истријебиће се она душа из збора Израиљева, био дошљак или рођен у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Ништа с квасцем немојте јести, него једите хљеб пријесан по свијем становима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'И сазва Мојсије све старјешине Израиљске, и рече им: изберите и узмите себи јагње или јаре по породицама својим, и закољите пасху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'И узмите киту исопа и замочите је у крв, која ће бити у здјели, и покропите горњи праг и оба довратка крвљу, која ће бити у здјели, и ниједан од вас да не излази на врата кућна до јутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Јер ће заћи Господ да бије Мисир, па кад види крв на горњем прагу и на оба довратка, проћи ће Господ мимо она врата, и неће дати крвнику да уђе у куће ваше да убија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'И држите ово као закон теби и синовима твојим довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'И кад дођете у земљу коју ће вам дати Господ, као што је казао, држите ову службу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'И кад вам реку синови ваши: каква вам је то служба?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Реците: ово је жртва за пролазак Господњи, кад прође куће синова Израиљевих у Мисиру убијајући Мисирце, а домове наше сачува. Тада народ сави главу и поклони се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'И отидоше и учинише синови Израиљеви, како заповједи Господ преко Мојсија и Арона, тако учинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'А око поноћи поби Господ све првенце у земљи Мисирској од првенца Фараонова који шћаше сједјети на пријестолу његову до првенца сужња у тамници, и што год бјеше првенац од стоке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Тада уста Фараон оне ноћи, он и све слуге његове и сви Мисирци, и би вика велика у Мисиру, јер не бјеше куће у којој не би мртваца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'И дозва Мојсија и Арона по ноћи и рече: устајте, идите из народа мојега и ви и синови Израиљеви, и отидите, послужите Господу, као што говористе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Узмите и овце своје и говеда своја, као што говористе, и идите, па и мене благословите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'И Мисирци наваљиваху на народ да брже иду из земље, јер говораху: изгибосмо сви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'И народ узе тијесто своје још неускисло, умотавши га у хаљине своје, на рамена своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'И учинише синови Израиљеви по заповијести Мојсијевој, и заискаше у Мисираца накита сребрнијех и накита златнијех и хаљина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'И Господ учини, те народ нађе љубав у Мисираца, те им дадоше; тако оплијенише Мисирце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'И отидоше синови Израиљеви из Рамесе у Сохот, око шест стотина тисућа пјешака, самијех људи осим дјеце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'И других људи много отиде с њима, и стоке ситне и крупне врло много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'И од тијеста које изнесоше из Мисира испекоше погаче пријесне, јер не бјеше ускисло кад их потјераше Мисирци, те не могаше оклијевати, нити спремише себи брашњенице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'А бавише се синови Израиљеви у Мисиру четири стотине и тридесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'И кад се наврши четири стотине и тридесет година, у исти дан изађоше све војске Господње из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Та се ноћ светкује Господу, у коју их изведе из Мисира; то је ноћ Господња, коју треба да светкују синови Израиљеви од кољена на кољено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'И рече Господ Мојсију и Арону: ово нека буде закон за пасху: ниједан туђин да је не једе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'А сваки слуга ваш купљен за новце, кад га обрежете, онда нека је једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Дошљак или најамник да је не једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'У истој кући да се једе, да не изнесете меса од ње из куће, и кости да јој не преломите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Сав збор Израиљев нека чини тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Ако би код тебе сједио туђин и хтио би светковати пасху Господњу, нека му се обреже све мушкиње, па онда нека приступи да је светкује, и нека буде као рођен у земљи; а нико необрезан да је не једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Закон један да је и рођеноме у земљи и дошљаку који сједи међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'И учинише сви синови Израиљеви како заповједи Господ Мојсију и Арону, тако учинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'И тај дан изведе Господ синове Израиљеве из земље Мисирске у четама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Посвети ми свакога првенца, што год отвора материцу у синова Израиљевијех, и од људи и од стоке; јер је моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'И Мојсије рече народу: памтите овај дан, у који изидосте из Мисира, из дома ропскога, јер вас руком крјепком изведе Господ оданде; нека се дакле не једе ништа с квасцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Данас излазите, мјесеца Авива;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Па кад те Господ уведе у земљу Хананејску и Хетејску и Аморејску и Јевејску и Јевусејску, за коју се заклео оцима твојим да ће ти је дати, земљу у којој тече млијеко и мед, тада да служиш службу ову овога мјесеца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Седам дана једи хљебове пријесне, а седми дан нека је празник Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Хљебови пријесни да се једу седам дана, и да се не види у тебе ништа с квасцем, нити да се види у тебе квасац у цијелом крају твом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'И казаћеш сину својему у тај дан говорећи: ово је за оно што ми је учинио Господ кад сам излазио из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'И нека ти буде као знак на руци твојој и као спомен пред очима твојима, да ти закон Господњи буде у устима; јер те је руком крјепком извео Господ из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Зато врши закон овај на вријеме, од године до године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'И кад те уведе Господ у земљу Хананејску, као што се заклео теби и твојим оцима, и да ти је,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Одвајаћеш Господу што год отвора материцу, и од стоке твоје што год отвора материцу, што је мушко, да буде Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'А свако магаре првенче откупи јагњетом или јаретом; ако ли га не би откупио, сломи му врат. Али свакога првенца човјечијега између синова својих откупи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'А кад те запита син твој у напредак говорећи: шта је то? реци му: руком крјепком изведе нас Господ из Мисира, из дома ропскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Јер кад отврдну Фараон, те нас не хтје пустити, поби Господ све првенце у земљи Мисирској од првенца човјечијега до првенца од стоке; зато приносим Господу све мушко што отвора материцу, а свакога првенца синова својих откупљујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'И то нека ти је као знак на руци и као почеоник међу очима твојима, да нас је руком крјепком извео Господ из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'А кад Фараон пусти народ, не одведе их Бог путем к земљи Филистејској, ако и бјеше краћи, јер Бог рече: да се не покаје народ кад види рат, и не врати се у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Него Бог заведе народ путем преко пустиње на Црвеном Мору. А војничким редом изидоше синови Израиљеви из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'И Мојсије узе кости Јосифове са собом; јер бјеше заклео синове Израиљеве рекавши: заиста ће вас походити Бог, а тада изнесите кости моје одавде са собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Тако отишавши из Сохота стадоше у око у Етаму, накрај пустиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'А Господ иђаше пред њима дању у ступу од облака водећи их путем, а ноћу у ступу од огња свијетлећи им, да би путовали дању и ноћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'И не уклањаше испред народа ступа од облака дању ни ступа од огња ноћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Кажи синовима Израиљевијем нека савију и стану у око пред Пи-Аирот између Мигдола и мора према Вел-Сефону; према њему нека стану у око покрај мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Јер ће Фараон рећи за синове Израиљеве: зашли су у земљу, затворила их је пустиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'И учинићу да отврдне срце Фараону, те ће поћи у потјеру за вама, и ја ћу се прославити на њему и на свој војсци његовој, и Мисирци ће познати да сам ја Господ. И учинише тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'А кад би јављено цару Мисирском да је побјегао народ, промијени се срце Фараоново и слуга његовијех према народу, те рекоше: шта учинисмо, те пустисмо Израиља да нам не служи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'И упреже у кола своја, и узе народ свој са собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'И узе шест стотина кола изабраних и што још бјеше кола Мисирских, и над свјема војводе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'И Господ учини, те отврдну срце Фараону цару Мисирском, и пође у потјеру за синовима Израиљевијем, кад синови Израиљеви отидоше под руком високом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'И тјеравши их Мисирци стигоше их, сва кола Фараонова, коњици његови и војска његова, кад бјеху у околу на мору код Пи-Аирота према Вел-Сефону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'И кад се приближи Фараон, подигоше синови Израиљеви очи своје а то Мисирци иду за њима, и уплашише се врло, и повикаше синови Израиљеви ка Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'И рекоше Мојсију: зар не бјеше гробова у Мисиру, него нас доведе да изгинемо у пустињи? Шта учини, те нас изведе из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Нијесмо ли ти говорили у Мисиру и рекли: прођи нас се, нека служимо Мисирцима? јер би нам боље било служити Мисирцима него изгинути у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'А Мојсије рече народу: не бојте се, станите па гледајте како ће вас Господ избавити данас; јер Мисирце које сте видјели данас, нећете их нигда више видјети до вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Господ ће се бити за вас, а ви ћете мучати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'А Господ рече Мојсију: што вичеш к мени? кажи синовима Израиљевијем нека иду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'А ти дигни штап свој и пружи руку своју на море, и расцијепи га, па нека иду синови Израиљеви посред мора сухим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'И гле, ја ћу учинити да отврдне срце Мисирцима, те ће поћи за њима; и прославићу се на Фараону и на свој војсци његовој, на колима његовијем и на коњицима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'И Мисирци ће познати да сам ја Господ, кад се прославим на Фараону, на колима његовијем и на коњицима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'И подиже се анђео Господњи, који иђаше пред војском Израиљском, и отиде им за леђа; и подиже се ступ од облака испред њих, и стаде им за леђа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'и дошав међу војску Мисирску и војску Израиљску бјеше онијем облак мрачан а овијем свијетљаше по ноћи, те не приступише једни другима цијелу ноћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'И пружи Мојсије руку своју на море, а Господ узби море вјетром источнијем, који јако дуваше цијелу ноћ, и осуши море, и вода се раступи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'И пођоше синови Израиљеви посред мора сухим, и вода им стајаше као зид с десне стране и с лијеве стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'И Мисирци тјерајући их пођоше за њима посред мора, сви коњи Фараонови, кола и коњици његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'А у стражу јутрењу погледа Господ на војску Мисирску из ступа од огња и облака, и смете војску Мисирску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'И позбаца точкове колима њиховијем, те их једва вуцијаху. Тада рекоше Мисирци: бјежимо од Израиља, јер се Господ бије за њих с Мисирцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'А Господ рече Мојсију: пружи руку своју на море, нека се врати вода на Мисирце, на кола њихова и на коњике њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'И Мојсије пружи руку своју на море, и дође опет море на силу своју пред зору, а Мисирци нагоше бјежати према мору; и Господ баци Мисирце усред мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'А вративши се вода потопи кола и коњике са свом војском Фараоновом, што их год бјеше пошло за њима у море, и не оста од њих ниједан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'И синови Израиљеви иђаху посред мора сухим; и стајаше им вода као зид с десне стране и с лијеве стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'И избави Господ Израиља у онај дан из руку Мисирских; и видје Израиљ мртве Мисирце на бријегу морском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'И видје Израиљ силу велику, коју показа Господ на Мисирцима, и народ се побоја Господа, и вјерова Господу и Мојсију слузи његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Тада запјева Мојсије и синови Израиљеви ову пјесму Господу, и рекоше овако: Пјеваћу Господу, јер се славно прослави; коња и коњика врже у море.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Сила је моја и пјесма моја Господ, који ме избави; он је Бог мој, и славићу га; Бога оца мојега, и узвишиваћу га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Господ је велик ратник; име му је Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Кола Фараонова и војску његову врже у море; избране војводе његове утопише се у црвеном мору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Бездани их покрише; падоше у дубину као камен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Десница твоја, Господе, прослави се у сили; десница твоја, Господе, сатр непријатеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'И мноштвом величанства својега оборио си оне који усташе на те; пустио си гњев свој, и прождрије их као сламу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Од даха ноздара твојих сабра се вода; стаде у гомилу вода која тече; стинуше се вали усред мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Непријатељ рече: тјераћу, стигнућу, дијелићу плијен; наситиће их се душа моја, извући ћу мач свој, истријебиће их рука моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Ти дуну вјетром својим, и море их покри, и утонуше као олово у дубокој води.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Ко је као ти међу силнима Господе? ко је као ти славан у светости, страшан у хвали, и да чини чудеса?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Ти пружи десницу своју, и прождрије их земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Водиш милошћу својом народ, који си искупио, водиш крјепошћу својом у стан светости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Чуће народи, и задрхтаће; мука ће спопасти оне који живе у земљи Филистејској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Тада ће се препасти старјешине Едомске, јунаке Моавске спопашће дрхат, уплашиће се сви који живе у Хананској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Спопашће их страх и трепет; од величине руке твоје замукнуће као камен, докле не прође народ твој, Господе, докле не прође народ, који си задобио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Одвешћеш их и посадићеш их на гори нашљедства својега, на мјесту које си себи за стан спремио, Господе, у светињи, Господе, коју су твоје руке утврдиле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Господ ће царовати довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Јер уђоше коњи Фараонови с колима његовијем и с коњицима његовијем у море, и Господ поврати на њих воду морску; а синови Израиљеви пријеђоше сухим посред мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'И Марија пророчица сестра Аронова узе бубањ у руку своју; а за њом изидоше све жене с бубњима и свиралама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'И отпијеваше им Марија: пјевајте Господу, јер се славно прослави; коња и коњика врже у море.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Потом крену Мојсије синове Израиљеве од Мора Црвенога, и пођоше у пустињу Сур; и три дана ишавши по пустињи не нађоше воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Оданде дођоше у Меру, али не могоше пити воде у Мери, јер бјеше горка; отуда се прозва мјесто Мера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Тада стаде народ викати на Мојсија говорећи: шта ћемо пити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'И Мојсије завапи ка Господу, а Господ му показа дрво, те га метну у воду, и вода поста слатка. Ондје му даде уредбу и закон, и ондје га окуша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'И рече: ако добро узаслушаш глас Господа Бога својега, и ушчиниш што је право у очима његовијем, и ако пригнеш ухо к заповијестима његовијем и ушчуваш све уредбе његове, ниједне болести коју сам пустио на Мисир нећу пустити на тебе; јер сам ја Господ, љекар твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'И дођоше у Елим, гдје бијаше дванаест извора и седамдесет палама; и ондје стадоше у око код воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Од Елима се подигоше, и сав збор синова Израиљевијех дође у пустињу Син, која је између Елима и Синаја, петнаестога дана другога мјесеца пошто изидоше из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'И стаде викати сав збор синова Израиљевијех на Мојсија и на Арона у пустињи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'И рекоше им синови Израиљеви: камо да смо помрли од руке Господње у земљи Мисирској, кад сјеђасмо код лонаца с месом и јеђасмо хљеба изобила! јер нас изведосте у ову пустињу да поморите сав овај збор глађу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'А Господ рече Мојсију: ево учинићу да вам дажди из неба хљеб, а народ нека излази и купи сваки дан колико треба на дан, да га окушам хоће ли ходити по моме закону или неће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'А шестога дана нека зготове што донесу, а нека буде двојином онолико колико накупе сваки дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'И рече Мојсије и Арон свијем синовима Израиљевијем: довече ћете познати да вас је Господ извео из земље Мисирске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'А сјутра ћете видјети славу Господњу; јер је чуо вику вашу на Господа. Јер шта смо ми да вичете на нас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'И рече Мојсије: довече ће вам дати Господ меса да једете а ујутру хљеба да се наситите; јер је чуо Господ вику вашу, којом вичете на њ. Јер што смо ми? Није на нас ваша вика него на Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'И рече Мојсије Арону: кажи свему збору синова Израиљевих: приступите пред Господа, јер је чуо вику вашу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'И кад рече Арон свему збору синова Израиљевих, погледаше у пустињу, и гле, слава Господња показа се у облаку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'И Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Чуо сам вику синова Израиљевих. Кажи им и реци: довече ћете јести меса, а сјутра ћете се наситити хљеба, и познаћете да сам ја Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'И увече долетјеше препелице и прекрилише око, а ујутру паде роса око окола;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'А кад се диже роса, а то по пустињи нешто ситно округло, ситно као слана по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'И кад видјеше синови Израиљеви, говораху један другому: шта је ово? Јер не знадијаху шта бјеше. А Мојсије им рече: то је хљеб што вам даде Господ да једете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'То је за што заповједи Господ: купите га сваки дан колико коме треба за јело, по гомор на главу, по броју душа ваших, сваки нека узме за оне који су му у шатору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'И учинише тако синови Израиљеви; и накупише који више који мање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Па мјерише на гомор, и не дође више оном који накупи много, нити мање оном који накупи мало, него сваки накупи колико му је требало да једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'И рече им Мојсије: нико да не оставља од тога за сјутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Али не послушаше Мојсија, него неки оставише од тога за сјутра, те се уцрва и усмрдје. И расрди се Мојсије на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Тако га купљаху свако јутро, сваки колико му требаше за јело; а кад сунце огријеваше, тада се растапаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'А у шести дан накупише хљеба двојином, по два гомора на свакога; и дођоше све старјешине од збора, и јавише Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'А он им рече: ово каза Господ: сјутра је субота, одмор свет Господу; што ћете пећи, пеците, и што ћете кухати, кухајте данас; а што претече, оставите и чувајте за сјутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'И оставише за сјутра, као што заповједи Мојсије, и не усмрдје се нити бјеше црва у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'И рече Мојсије: једите то данас, јер је данас субота Господња, данас нећете наћи у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Шест ћете дана купити, а седми је дан субота, тада га неће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'И у седми дан изидоше неки од народа да купе, али не нађоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'А Господ рече Мојсију: докле ћете се противити заповјестима мојим и законима мојим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Видите, Господ вам је дао суботу, зато вам даје шестога дана хљеба на два дана. Стојте сваки на свом мјесту, и нека не одлази нико са својега мјеста у седми дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'И почину народ у седми дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'И дом Израиљев прозва тај хљеб мана; а бијаше као сјеме коријандрово, бијела, и на језику као медени колачи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'И рече Мојсије: ово је заповједио Господ: напуни гомор тога, нека се чува од кољена до кољена вашега, да виде хљеб, којим сам вас хранио у пустињи кад вас изведох из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'И рече Мојсије Арону: узми крчаг и наспи пун гомор мане, и метни пред Господа да се чува од кољена до кољена вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'И остави га Арон пред свједочанством да се чува, као што заповједи Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'А синови Израиљеви једоше ману четрдесет година док не дођоше у земљу у којој ће живјети; једоше ману док не дођоше на међу земље Хананске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'А гомор је десетина ефе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'И подиже се из пустиње Сина сав збор синова Израиљевих путем својим по заповјести Господњој, и стадоше у око у Рафидину; а ондје не бјеше воде да народ пије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'И народ се свађаше с Мојсијем говорећи: дај нам воде да пијемо. А он им рече: што се свађате са мном? што кушате Господа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Али народ бјеше ондје жедан воде, те викаше народ на Мојсија, и говораше: зашто си нас извео из Мисира да нас и синове наше и стоку нашу помориш жеђу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'А Мојсије завапи ка Господу говорећи: шта ћу чинити с овијем народом? Још мало па ће ме засути камењем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'А Господ рече Мојсију: прођи пред народ, и узми са собом старјешине Израиљске, и штап свој којим си ударио воду узми у руку своју, и иди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'А ја ћу стајати пред тобом ондје на стијени на Хориву; а ти удари у стијену, и потећи ће из ње вода да пије народ. И учини Мојсије тако пред старјешинама Израиљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'А мјесто оно прозва Маса и Мерива зато што се свађаше синови Израиљеви и што кушаше Господа говорећи: је ли Господ међу нама или није?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Али дође Амалик да се бије с Израиљем у Рафидину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'А Мојсије рече Исусу: избери нам људе, те изађи и биј се с Амаликом; а ја ћу сјутра стати на врх брда са штапом Божјим у руци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'И учини Исус како му рече Мојсије, и поби се с Амаликом; а Мојсије и Арон и Ор изађоше на врх брда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'И докле Мојсије држаше у вис руке своје, надбијаху Израиљци, а како би спустио руке, одмах надбијаху Амаличани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Али руке Мојсију отежаше, зато узеше камен и подметнуше пода њ, те сједе; а Арон и Ор држаху му руке један с једне стране а други с друге, и не клонуше му руке до захода сунчанога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'И разби Исус Амалика и народ његов оштријем мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Потом рече Господ Мојсију: запиши то за спомен у књигу, и кажи Исусу нека памти да ћу сасвијем истријебити спомен Амаликов испод неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Тада начини Мојсије олтар, и назва га: Господ застава моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'И рече: што се рука бјеше подигла на пријесто Господњи, Господ ће ратовати на Амалика од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'А Јотор свештеник Мадијамски, таст Мојсијев, чу све што учини Господ Мојсију и Израиљу народу својему, како изведе Господ Израиља из Мисира;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'И узе Јотор таст Мојсијев Сефору жену Мојсијеву, коју бјеше послао натраг,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'И два сина њезина, од којих једном бјеше име Гирсам, јер рече: туђин сам у земљи туђој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'А другом бјеше име Елиезер, јер, рече, Бог оца мојега би ми у помоћи и оте ме од мача Фараонова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'И пође Јотор таст Мојсијев са синовима његовијем и са женом његовом к Мојсију у пустињу, гдје бјеше у околу под гором Божијом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'И поручи Мојсију: ја таст твој Јотор идем к теби и жена твоја и оба сина њезина с њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'И Мојсије изиде на сусрет тасту својему и поклони му се и цјелива га; и упиташе се за здравље, па уђоше под шатор његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'И приповједи Мојсије тасту својему све што учини Господ Фараону и Мисирцима ради Израиља, и све невоље, које их налазише путем, и како их избави Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'И радоваше се Јотор свему добру што учини Господ Израиљу избавивши га из руке Мисирске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'И рече Јотор: благословен да је Господ, који вас избави из руке Мисирске, и из руке Фараонове, који избави народ из ропства Мисирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Сад видим да је Господ већи од свијех богова, јер чим се поношаху онијем их самијем надвиси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'И узе Јотор таст Мојсијев и принесе Богу жртву паљеницу и принос; и дође Арон и све старјешине Израиљске, и једоше с тастом Мојсијевијем пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'А сјутрадан сједе Мојсије да суди народу; и стајаше народ пред Мојсијем од јутра до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'А таст Мојсијев гледајући све шта ради с народом, рече: шта то радиш с народом? зашто сједиш сам, а вас народ стоји пред тобом од јутра до вечера?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'А Мојсије рече тасту својему: јер долази народ к мени да пита Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Кад имају што међу собом, долазе к мени, те им судим и казујем наредбе Божје и законе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'А таст Мојсијев рече му: није добро што радиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Уморићеш се и ти и народ који је с тобом; јер је то тешко за тебе, нећеш моћи сам вршити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Него послушај мене; ја ћу те свјетовати, и Бог ће бити с тобом; ти буди пред Богом за народ, и ствари њихове јављај Богу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'И учи их наредбама и законима његовијем, и показуј им пут којим ће ићи и шта ће радити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'А из свега народа избери људе поштене, који се боје Бога, људе праведне, који мрзе на мито, па их постави над њима за поглаваре, тисућнике, стотинике, педесетнике и десетнике;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Они нека суде народу у свако доба; па сваку ствар велику нека јављају теби, а сваку ствар малу нека расправљају сами; тако ће ти бити лакше, кад и они стану носити терет с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Ако то учиниш, и Бог ти заповједи, можеш се одржати, и сав ће народ доћи мирно на своје мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'И Мојсије послуша таста својега, и учини све што рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'И изабра Мојсије из свега Израиља људе поштене, и постави их за поглаваре над народом, тисућнике, стотинике, педесетнике и десетнике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Који суђаху народу у свако доба, а ствари тешке јављаху Мојсију, а мале ствари расправљаху сами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Послије отпусти Мојсије таста својега, који се врати у своју земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Првога дана трећега мјесеца, пошто изађоше синови Израиљеви из Мисира, тога дана дођоше у пустињу Синајску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Кренувши се из Рафидина дођоше у пустињу Синајску, и стадоше у око у пустињи, а око начинише Израиљци ондје под гором.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'И Мојсије изађе на гору к Богу; и повика му Господ с горе говорећи: овако кажи дому Јаковљеву, и реци синовима Израиљевим:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Видјели сте шта сам учинио Мисирцима и како сам вас као на крилима орловијем носио и довео вас к себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'А сада ако добро узаслушате глас мој и ушчувате завјет мој, бићете моје благо мимо све народе, премда је моја сва земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'И бићете ми царство свештеничко и народ свет. То су ријечи које ћеш казати синовима Израиљевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'А Мојсије дође и сазва старјешине народне; и каза им све ове ријечи које му Господ заповједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'А сав народ одговори сложно и рече: што је год казао Господ чинићемо. И Мојсије јави Господу ријечи народне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'А Господ рече Мојсију: ево, ја ћу доћи к теби у густом облаку, да народ чује кад ти станем говорити и да ти вјерује до вијека. Јер Мојсије бјеше јавио Господу ријечи народне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'И рече Господ Мојсију: иди к народу, и освештај их данас и сјутра, и нека оперу хаљине своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'И нека буду готови за трећи дан, јер ће у трећи дан сићи Господ на гору Синајску пред свијем народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'А поставићеш народу међу унаоколо, и рећи ћеш: чувајте се да не ступите на гору и да се не дотакнете краја њезина; што се год дотакне горе, погинуће;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Тога да се нико не дотакне руком, него камењем да се заспе или да се устријели, било живинче или човјек, да не остане у животу. Кад рог затруби отежући онда нека пођу на гору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'И Мојсије сиђе с горе к народу; и освешта народ, и опраше хаљине своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'И рече народу: будите готови за трећи дан, и не лијежите са женама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'А трећи дан кад би ујутру, громови загрмјеше и муње засијеваше, и поста густ облак на гори, и затруби труба веома јако, да задрхта сав народ који бијаше у околу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Тада Мојсије изведе народ из окола пред Бога, и стадоше испод горе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'А гора се Синајска сва димљаше, јер сиђе на њу Господ у огњу; и дим се из ње подизаше као дим из пећи, и сва се гора тресијаше веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'И труба све јаче трубљаше, и Мојсије говораше а Бог му одговараше гласом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'И Господ сишавши на гору Синајску, на врх горе, позва Мојсија на врх горе; и изађе Мојсије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'А Господ рече Мојсију: сиђи, опомени народ да не преступе међе да виде Господа, да не би изгинули од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'И сами свештеници, који приступају ка Господу, нека се освештају, да их не би побио Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'А Мојсије рече Господу: неће моћи народ изаћи на гору Синајску, јер си нас ти опоменуо рекавши: начини међу гори и освештај је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'А Господ му рече: иди, сиђи, па онда дођи ти и Арон с тобом; а свештеници и народ нека не преступе међе да се попну ка Господу, да их не би побио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'И сиђе Мојсије к народу и каза им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Тада рече Бог све ове ријечи говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Ја сам Господ Бог твој, који сам те извео из земље Мисирске, из дома ропскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Немој имати других богова уза ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Не гради себи лика резана нити какве слике од онога што је горе на небу, или доље на земљи, или у води испод земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Немој им се клањати нити им служити, јер сам ја Господ Бог твој, Бог ревнитељ, који походим гријехе отачке на синовима до трећега и до четвртога кољена, онијех који мрзе на мене;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'А чиним милост на тисућама онијех који ме љубе и чувају заповијести моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Не узимај узалуд имена Господа Бога својега; јер неће пред Господом бити прав ко узме име његово узалуд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Сјећај се дана од одмора да га светкујеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Шест дана ради, и свршуј све послове своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'А седми је дан одмор Господу Богу твојему; тада немој радити ниједнога посла, ни ти, ни син твој, ни кћи твоја, ни слуга твој, ни слушкиња твоја, ни живинче твоје, ни странац који је међу вратима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Јер је за шест дана створио Господ небо и земљу, море и што је год у њима; а у седми дан почину; зато је благословио Господ дан од одмора и посветио га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Поштуј оца својега и матер своју, да ти се продуље дани на земљи, коју ти да Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Не убиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Не чини прељубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Не кради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Не свједочи лажно на ближњега својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Не пожели куће ближњега својега, не пожели жене ближњега својега, ни слуге његова, ни слушкиње његове, ни вола његова, ни магарца његова, нити ишта што је ближњега твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'И сав народ видје гром и муњу и трубу гдје труби и гору гдје се дими; и народ видјевши то узмаче се и стаде издалека,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'И рекоше Мојсију: говори нам ти, и слушаћемо; а нека нам не говори Бог, да не помремо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'А Мојсије рече народу: не бојте се, јер Бог дође да вас искуша и да вам пред очима буде страх његов да не бисте гријешили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'И народ стајаше издалека, а Мојсије приступи к мраку у којем бјеше Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'И Господ рече Мојсију: овако кажи синовима Израиљевим: видјели сте гдје вам с неба говорих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Не градите уза ме богова сребрнијех, ни богова златнијех не градите себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Олтар од земље начини ми, на којем ћеш ми приносити жртве своје паљенице и жртве своје захвалне, ситну и крупну стоку своју. На којем год мјесту заповједим да се спомиње име моје, доћи ћу к теби и благословићу те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Ако ли ми начиниш олтар од камена, немој начинити од тесанога камена; јер ако повучеш по њему гвожђем, оскврнићеш га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Немој уз басамаке ићи к олтару мојему, да се не би открила голотиња твоја код њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'А ово су закони које ћеш им поставити:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Ако купиш роба Јеврејина, шест година нека ти служи, а седме нек отиде слободан без откупа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Ако буде дошао инокосан, нека и отиде инокосан; ако ли буде имао жену, нека иде и жена с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Ако га господар његов ожени, и жена му роди синове или кћери, жена с дјецом својом нека буде господару његову, а он нека отиде сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Ако ли роб рече тврдо: љубим господара својега, жену своју и дјецу своју, нећу да идем да будем слободан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Онда нека га доведе господар његов пред судије и постави на вратима или код довратка, и ондје нека му господар пробуши ухо шилом, па нека му робује довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Ако ко прода кћер своју да буде робиња, да не одлази као робови што одлазе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Ако не буде по вољи господару својему, и он је не узме за жену, нека је пусти на откупе; али да нема власти продати је у туђ народ учинивши јој невјеру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Ако ли је заручи сину својему, да јој учини по праву које имају кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Ако ли узме другу, да јој не умали хране ни одијела ни заједнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Ако јој ово троје не учини, онда нек отиде без откупа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Ко удари човјека, те умре да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Ако ли не буде хтио, него му га Бог даде у руке, одредићу ти мјесто куда може утећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Ако би ко навалице устао на ближњега својега да га убије из пријеваре, одвуци га и од олтара мојега да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Ко удари оца својега или матер своју, да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Ко украде човјека и прода или се нађе у његовијем рукама, да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Ко опсује оца својега или матер своју, да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Кад се сваде људи, па један удари другога каменом или песницом, али онај не умре него падне у постељу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'Ако се придигне и изађе о штапу, да не буде крив онај који је ударио, само дангубу да му накнади и сву видарину да плати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Ко удари роба својега или робињу штапом тако да му умре под руком, да је крив;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Али ако преживи дан или два, да није крив, јер је његов новац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Кад се сваде људи, па који од њих удари трудну жену тако да изађе из ње дијете, али се не догоди смрт, да плати глобу колико муж женин рече, а да плати преко судија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Ако ли се догоди смрт, тада ћеш узети живот за живот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Око за око, зуб за зуб, руку за руку, ногу за ногу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Ужег за ужег, рану за рану, модрицу за модрицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Ако ко удари по оку роба својега или робињу своју, те му поквари око, да га отпусти слободна за око његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'И ако избије зуб робу својему или робињи својој, да га пусти слободна за зуб његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Ако во убоде човјека или жену, те умре, да се во заспе камењем и да се не једе месо од њега, а господар од вола да није крив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Али ако је во прије био бодач и господар његов знао за то па га није чувао, те убије човјека или жену, во да се заспе камењем, и господар његов да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Ако му се одреди да се откупи, нека да откуп за живот свој, колико му се одреди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Ако убоде сина или кћер, да му буде по истом закону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Ако ли роба убоде во или робињу, да да господару њихову тридесет сикала сребра и во да се заспе камењем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Ако ко открије јаму или ископа јаму а не покрије, па упадне во или магарац,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'Да накнади господар од јаме и плати новцем господару њихову, а што је угинуло да је његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Ако во једнога убоде вола другоме, те погине, онда да продаду вола живога и новце да подијеле, тако и убијенога вола да подијеле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Ако ли се знало да је во прије био бодач па га није чувао господар његов, да да вола за вола, а убијени нека буде њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Ко украде вола или овцу или козу, и закоље или прода, да врати пет волова за једнога вола, а четири овце или козе за једну овцу или козу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Ако се лупеж ухвати гдје поткопава, те буде рањен тако да умре, да не буде крив за крв онај који га буде убио;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Али ако се буде сунце родило, да је крив за крв. А лупеж све да накнади; ако ли не би имао, онда да се он прода за своју крађу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Ако се нађе што је покрао у његовој руци живо, био во или магарац или овца или коза, да врати двоструко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Ко потре њиву или виноград пустивши стоку своју да пасе по туђој њиви, да накнади најбољим са своје њиве и најбољим из свога винограда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Ако изађе ватра и наиђе на трње, па изгори стог или жито које још стоји или њива, да накнади онај који је запалио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Ако ко да ближњему својему новце или посуђе на оставу, па се украде из куће његове, ако се нађе лупеж, да плати двојином;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Ако ли се не нађе лупеж, онда господар од оне куће да стане пред судије да се закуне да није посегао руком својом на ствар ближњега својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'За сваку ствар за коју би била распра, или за вола или за магарца или за овцу или за козу, или за хаљину, за сваку ствар изгубљену, кад ко каже да је његова, пред судије да дође распра обојице, па кога осуде судије, онај да врати ближњему својему двојином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Ако ко да ближњему својему да чува магарца или вола или овцу или козу или како год живинче, па угине или охроне, или га ко отјера а да нико не види,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Заклетва Господња нека буде између њих, да није посегао руком својом на ствар ближњега својега, и господар од ствари нека пристане, а онај да не плати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Ако ли му буде украдено, нека плати господару његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Ако ли га буде растргла звјерка да донесе од њега свједоџбу, и да не плати што је растргнуто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Ако ко узме у ближњега својега живинче на послугу, па охроне или угине, а господар му не буде код њега, да плати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Ако ли господар буде код њега, да не плати. Ако ли буде најмљено, да плати само најам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Ко би преварио дјевојку, која није заручена, те би спавао с њом, да јој да прћију и узме је за жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'А ако му је отац њезин не би хтио дати, да да новаца колико иде у прћију дјевојци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Вјештици не дај да живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Ко би облежао живинче, да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Ко жртву приноси боговима другим осим јединога Господа, да се истријеби као проклетник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Дошљаку немој чинити криво нити га цвијелити, јер сте били дошљаци у земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Немојте цвијелити удовице и сироте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Ако ли коју цвијелиш у чем год, и повиче к мени, чућу вику њезину,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'И запалиће се гњев мој, и побићу вас мачем, па ће ваше жене бити удовице и ваша дјеца сироте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Кад даш у зајам новаца народу мојему, сиромаху који је код тебе, немој му бити као каматник, не ударајте на њ камате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Ако узмеш у залогу хаљину ближњему својему, врати му је прије него сунце зађе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Јер му је то све одијело чим заклања тијело своје; у чем ће спавати? па кад повиче к мени, ја ћу га чути, јер сам милостив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Немој псовати судија, и старјешини народа својега не говори ружно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Од љетине своје и од житких ствари својих немој се затезати да принесеш првине; првенца између синова својих мени да даш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Тако чини с волом својим и с овцом и с козом; седам дана нека буде с мајком својом, а осмога дана да га даш мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Бићете ми свети људи; меса у пољу растргнута не једите, баците га псима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Не износи лажнијех гласова; не пристај с безбожником да свједочиш криво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Не иди за множином на зло, и не говори на суду поводећи се за већим бројем да се изврне правда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Сиромаху у парници његовој не гледај што је сиромах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Ако наиђеш на вола непријатеља својега или на магарца његова, гдје је залутао, одведи га к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Ако видиш гдје је ненавиднику твојему пао магарац под теретом својим, немој да га оставиш, него му помози.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Немој изврнути правде сиромаху својему у парници његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Ријечи лажне клони се, и безазленога и правога немој убити, јер нећу оправдати безбожника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Не узимај поклона, јер поклон зашљепљује окате и изврће ријечи правима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Дошљаке не цвијели, јер ви знате кака је душа дошљаку, јер сте били дошљаци у земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Шест година засијевај земљу своју и сабирај род њезин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'А седме године остави је нека почине, да једу сиромаси народа твојега, а што иза њих остане нека једу звијери пољске; тако ради и с виноградом својим и с маслиником својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Шест дана ради послове своје, а у седми дан почини, да се одмори во твој и магарац твој, и да одахне син робиње твоје и дошљак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Држите се свега што сам вам казао. Не помињите имена богова туђих, и да се не чује из уста ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Три пута преко године светкуј ми:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Празник пријеснијех хљебова држи; седам дана једи хљебове пријесне, као што сам ти заповједио, на вријеме, мјесеца Авива, јер си тада изашао из Мисира; и нико да не изађе преда ме празан;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'И празник жетве првина од труда твојега што посијеш у пољу својем; и празник бербе на свршетку сваке године, кад сабереш труд свој с њиве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Три пута преко године све мушкиње твоје да излази пред Господа Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Крви од жртве моје не приноси уз хљебове киселе, и претилина празника мојега да не преноћи до јутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Првине од првога рода земље своје донеси у кућу Господа Бога својега; немој кухати јагњета у млијеку мајке његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Ево, ја шаљем анђела својега пред тобом да те чува на путу, и да те одведе на мјесто које сам ти приправио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Чувај га се, и слушај га, немој да га расрдиш, јер вам неће опростити гријеха, јер је моје име у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Него ако га добро узаслушаш и уствориш све што кажем, ја ћу бити непријатељ твојим непријатељима и противник твојим противницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Јер ће анђео мој ићи пред тобом и одвешће те у земљу Аморејску и Хетејску и Ферезејску и Хананејску и Јевејску и Јевусејску, и ја ћу их истријебити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Немој се клањати боговима њиховијем нити им служити, ни чинити што они чине, него их сасвијем обори и ликове њихове сасвијем изломи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'И служите Господу Богу својему, и он ће благословити хљеб твој и воду твоју; и уклонићу болест између вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Неће бити пометкиње ни нероткиње у земљи твојој; и број дана твојих напунићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Пустићу страх свој пред тобом, и уплашићу сваки народ на који дођеш, и обратићу к теби плећи свијех непријатеља твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Послаћу и стршљене пред тобом, да тјерају Јевеје, Хананеје и Хетеје испред тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Нећу их отјерати испред тебе за једну годину, да не опусти земља и да се звјерје пољско не намножи на тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Помало ћу их одгонити испред тебе докле се не намножиш и заузмеш земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'И поставићу међе твоје од мора црвенога до мора Филистејскога и од пустиње до ријеке; јер ћу вама у руке дати оне који живе у оној земљи да их отјераш испред себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Немој хватати вјере с њима ни с боговима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Нека не сједе у земљи твојој, да те не наврате да се огријешиш о мене, јер би служио боговима њиховијем, и то би ти била замка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'И рече Мојсију: изађи горе ка Господу ти и Арон и Надав и Авијуд и седамдесет старјешина Израиљевих, и поклоните се издалека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'И Мојсије сам нека приступи ка Господу, а они нека не приступе; и народ нека не иде на горе с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'И дође Мојсије, и каза народу све ријечи Господње и све законе. И одговори народ једнијем гласом и рекоше: чинићемо све што је рекао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'И написа Мојсије све ријечи Господње, и уставши рано начини олтар под гором и дванаест ступова за дванаест племена Израиљевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'И посла младиће између синова Израиљевих, који принесоше жртве паљенице и принесоше теоце на жртве захвалне Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'И узевши Мојсије половину крви, метну у здјеле, а половину крви изли на олтар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'И узе књигу завјетну и прочита народу. А они рекоше: што је год рекао Господ чинићемо и слушаћемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'А Мојсије узе крв, и покропи њом народ, и рече: ево крв завјета, који учини Господ с вама за све ријечи ове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Потом отиде горе Мојсије и Арон, Надав и Авијуд, и седамдесет старјешина Израиљевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'И видјеше Бога Израиљева, и под ногама његовијем као дјело од камена сафира и као небо кад је ведро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'И не пружи руке своје на изабране између синова Израиљевих, него видјеше Бога, па једоше и пише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'И рече Господ Мојсију: попни се к мени на гору, и остани овдје, и даћу ти плоче од камена, закон и заповијести, које сам написао, да их учиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Тада уста Мојсије с Исусом, који га служаше, и изађе Мојсије на гору Божију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'А старјешинама рече: сједите ту док се вратимо к вама; а ето Арон и Ор с вама; ко би имао што, нека иде к њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'И отиде Мојсије на гору, а облак покри гору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'И бјеше слава Господња на гори Синајској, и облак је покриваше шест дана; а у седми дан викну Мојсија испред облака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'И слава Господња бјеше по виђењу као огањ који сажиже на врх горе пред синовима Израиљевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'И Мојсије уђе усред облака, и попе се на гору; и оста Мојсије на гори четрдесет дана и четрдесет ноћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'И Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Реци синовима Израиљевим да ми скупе прилог: од свакога који драге воље да узмите прилог мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'А ово је прилог што ћете узимати од њих, злато и сребро и мјед,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'И порфиру и скерлет и црвац и танко платно и костријет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'И коже овнујске црвене обојене, и коже јазавчје, и дрво ситим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Уље за видјело, мирисе за уље помазања и за мирисави кад,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Камење онихово и камење за укивање на оплећак и напрсник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'И нека ми начине светињу, да међу њима наставам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Као што ћу ти показати слику од шатора и слику од свијех ствари његовијех, тако да начините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Нека начине ковчег од дрвета ситима, у дужину од два лакта и по, а у ширину од подруг лакта, и у висину од подруг лакта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'И покуј га чистим златом, изнутра и споља покуј га; и озго му начини златан вијенац унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'И салиј му четири биочуга од злата, и метни му их на четири угла, да му с једне стране буду два биочуга и с друге стране два биочуга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'И начини полуге од дрвета ситима, и окуј их у злато.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'И провуци полуге кроз биочуге с обје стране ковчегу, да се о њима носи ковчег;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'У биочузима на ковчегу нека стоје полуге, да се не ваде из њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Па у ковчег метни свједочанство, које ћу ти дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'И начини заклопац од чистога злата, у дужину од два лакта и по, а у ширину од подруг лакта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'И начини два херувима златна, једноставне их начини, на два краја заклопцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'И начини херувима једнога на једном крају а другога херувима на другом крају; на заклопцу начините два херувима на оба краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'И нека херувими рашире крила у вис да заклањају крилима заклопац, и нека буду лицем окренути један другом, према заклопцу нека су окренута лица херувимима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'И метнучеш заклопац озго на ковчег, а у ковчег ћеш метнути свједочанство, које ћу ти дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'И ту ћу се састајати с тобом и говорићу ти озго са заклопца између два херувима, који ће бити на ковчегу од свједочанства, све што ћу ти заповиједати за синове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Начини и сто од дрвета ситима, у дужину од два лакта, а у ширину од једног лакта, а у висину од подруг лакта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'И покуј га чистијем златом, и начини му вијенац златан унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'И начини му оплату унаоколо с подланице, и начини златан вијенац око оплате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'И начини му четири биочуга од злата, и метни му те биочуге на четири угла који ће му бити код четири ноге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Под оплатом нека буду биочузи, да у њима стоје полуге да се носи сто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'А полуге начини од дрвета ситима, и окуј их златом да се о њима носи сто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'И начини му здјеле и чаше и виједра и кутлиће, којима ће се прељевати, а начинићеш их од чистога злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'И метаћеш на сто хљебове, да су постављени свагда преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'И начини свијетњак од чистога злата, једноставан нека буде свијетњак; ступ и гране и чашице, јабуке, и цвјетови нека буду у њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'А шест грана нека му излази са страна, три гране с једне стране свијетњака а три гране с друге стране свијетњака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Три чашице као бадем нека буду на једној грани и јабука и цвијет, и три чашице као бадем и јабука и цвијет на другој грани; тако нека буде на шест грана што излазе из свијетњака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'И на самом свијетњаку нека буду четири чашице као бадем и јабуке и цвјетови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Једна јабука под двије гране што излазе из њега, и једна јабука под друге двије гране што излазе из њега, и једна јабука под друге двије гране што излазе из њега; тако ће бити под шест грана што ће излазити из свијетњака;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Јабуке и гране њихове из њега нека излазе; све једноставно од чистога злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'И начинићеш му седам жижака, и палићеш их да свијетле са сваке стране;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'И усекачи и спремице за гар нека буду од чистога злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Од таланта чистога злата нека буде начињен са свијем тијем справама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'И гледај, те начини све ово по слици која ти је показана на гори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'А шатор ћеш начинити од десет завјеса од танкога платна узведенога и од порфире и од скерлета и од црвца; и по њима да буду везени херувими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Један завјес нека буде двадесет и осам лаката дуг и четири лакта широк; сви завјеси да буду једне мјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Пет завјеса нека се састављају један с другим, и пет других завјеса нека се састављају један с другим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'И начини петље од порфире по крају једнога завјеса, гдје ће се крајеви састављати, и тако начини по крају другога завјеса, гдје ће се крајеви састављати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Педесет петаља начини на једном завјесу, а педесет петаља начини на крају другога завјеса, гдје ће се састављати с другим, а петље да буду једна према другој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'И начини педесет кука од злата, да запнеш завјесе један за други кукама, и тако ће бити шатор један.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'И начини завјесе од костријети за наслон над шатором; једанаест таких завјеса начини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Завјес један нека буде тридесет лаката дуг, а широк четири лакта; тијех једанаест завјеса да су једне мјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'И састави пет завјеса заједно, а шест осталијех заједно, на двоје ћеш превити шести завјес с предње стране наслону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'И начини педесет петаља на стражњем крају првога завјеса, гдје ће се састављати, а педесет петаља на крају другога завјеса, гдје ће се састављати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'И начини кука мједенијех педесет, и запни куке на петље, и састави наслон, да буде једно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'А што је више у завјеса на наслону, половина завјеса што претјече, нека виси на стражњој страни шатору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'И лакат с једне стране а лакат с друге стране што има више у дужину у завјеса на наслону, нека виси шатору са стране и тамо и амо, да га заклања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'И начини покривач наслону од кожа овнујских црвених обојених, и сврх њега покривач од кожа јазавчјих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'И начини за шатор даске од дрвета ситима, које ће стајати право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Десет лаката нека буде свака даска дуга а подруг лакта широка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Два чепа нека буду на дасци, један према другоме наједнако; тако начини на свакој дасци за шатор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Тако начини даске за шатор, двадесет дасака на јужној страни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'А под двадесет дасака начини четрдесет стопица од сребра: двије стопице под једну даску за два чепа њезина, и двије стопице под другу даску за два чепа њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'А на другој страни шатора према сјеверу двадесет дасака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Са четрдесет стопица сребрнијех, двије стопице под једну даску и двије стопице под другу даску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'А на западној страни шатора начини шест дасака,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'И двије даске на два угла од шатора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'И оне нека се састављају оздо и нека се састављају озго биочугом; тако нека буде у обје које ће бити на оба угла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Тако ће бити осам дасака са стопицама сребрнијем, са шеснаест стопица, двије стопице под једну даску, а двије стопице под другу даску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'И начини пријеворнице од дрвета ситима, пет за даске на једној страни шатора,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'И пет пријеворница за даске на другој страни шатора, и пет пријеворница за даске на западној страни шатора до оба угла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'А средња пријеворница да иде преко сриједе дасака од једнога краја до другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'А даске окуј златом, и биочуге им начини од злата, да се кроз њих провуку пријеворнице, а и пријеворнице окуј златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Тако ћеш подигнути шатор по слици која ти је показана на гори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'И начини завјес од порфире и од скерлета и од црвца и од танкога платна узведенога, и по њему нека буду везени херувими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'И објеси га о четири ступа од дрвета ситима, окована златом, са кукама златним, на четири стопице сребрне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'И објеси завјес о куке, и унеси за завјес ковчег од свједочанства, да вам завјес раставља светињу од светиње над светињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'И метни заклопац на ковчег од свједочанства у светињи над светињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'И намјести сто пред завјес а свијетњак према столу на јужној страни шатора, да сто стоји на сјеверној страни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'И на врата наслону начинићеш завјес од порфире и од скерлета и од црвца и од танкога платна узведенога, везен;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'И за тај завјес начинићеш пет ступова од дрвета ситима, које ћеш оковати златом, са кукама златнијем, и салићеш за њих пет стопица од мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'И начини олтар од дрвета ситима, пет лаката у дужину и пет лаката у ширину, четвороугласт да буде олтар, три лакта висок.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'И на четири угла начини му рогове, из њега да излазе рогови, и оковаћеш га у мјед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'И начинићеш му лонце за пепео и лопатице и котлиће и виљушке и машице; све му посуђе начини од мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'И начини му решетку од мједи као мрежу, и начини у решетке четири биочуга од мједи на четири угла њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'И метни је испод олтара унаоколо, да буде решетка до средине олтара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Начини и полуге олтару, полуге од дрвета ситима, и окуј их у мјед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'И полуге да се провуку кроз биочуге, да буду полуге с двије стране олтару, кад се носи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Начинићеш га од дасака да буде изнутра шупаљ; као што ти је показано на гори тако нека начине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'И начинићеш тријем шатору на јужној страни; завјеси тријему да буду од танкога платна узведенога, сто лаката у дужину на једној страни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'И двадесет ступова и под њих двадесет стопица од мједи, а куке на ступовима и пасови њихови од сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Тако и са западне стране да буду завјеси сто лаката дуги, и двадесет ступова и двадесет стопица од мједи, на ступовима куке и њихови пасови од сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'А ширина ће тријему имати са западне стране завјесе од педесет лаката, десет ступова за њих и десет стопица под њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'А на предњој страни према истоку биће тријем широк педесет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Од петнаест лаката нека буду завјеси на једној страни, и за њих три ступа и три стопице под њих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'На другој страни завјеси од петнаест лаката, и три ступа за њих и три стопице под њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'А над вратима од тријема завјес од двадесет лаката од порфире и од скерлета и од црвца и од танкога платна узведенога, везен, и четири ступа за њ, и под њих четири стопице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Сви ступови у тријему унаоколо да буду опасани сребром, и куке да су им сребрне а стопице од мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'У дужину ће тријем имати сто лаката, у ширину педесет свуда, а у висину пет лаката, да буде од танкога платна узведенога, а стопице од мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Све посуђе у шатору за сваку службу, и све коље у њему и све коље у тријему да буде од мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'И ти заповједи синовима Израиљевим да ти донесу уља маслинова чистога цијеђенога за видјело, да би жишци горјели свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'У шатору од састанка пред завјесом, који ће заклањати свједочанство, нека их Арон и синови његови спремају да горе од вечера до јутра пред Господом. То нека је уредба вјечна кољенима њиховијем међу синовима Израиљевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'А ти узми к себи Арона брата својега са синовима његовијем између синова Израиљевих да ми буду свештеници, Арон и Надав и Авијуд и Елеазар и Итамар, синови Аронови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'И начини свете хаљине Арону брату својему за част и дику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'И кажи свијем људима вјештијем, које сам напунио духа мудрости, нека начине хаљине Арону, да се посвети да ми буде свештеник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'А ово су хаљине што ће начинити: напрсник и оплећак и плашт, кошуља везена, капа и појас. Те хаљине свете нека направе Арону брату твојему и синовима његовијем, да ми буду свештеници,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'И нека узму злата и порфире и скерлета и црвца и танкога платна;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'И нека начине оплећак од злата и од порфире и од скерлета и од црвца и од танкога платна узведенога, везен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Двије пораменице нека буду на њему, које ће се састављати на два краја, да се држи заједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'А појас на њему нека буде направе исте као и он, од злата, од порфире, од скерлета, од црвца и од танкога платна узведенога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'И узми два камена ониха, и на њима изрежи имена синова Израиљевих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Шест имена њиховијех на једном камену, а шест имена осталијех на другом камену по реду како се који родио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Вјештином каменарском, којом се режу печати, изрезаћеш на та два камена имена синова Израиљевијех, и опточи их златом унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'И метни та два камена на пораменице оплећку, да буду камени за спомен синовима Израиљевијем, и Арон да носи имена њихова пред Господом на оба рамена своја за спомен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'И начини копче од злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'И два ланца од чистога злата начини једнака плетена, и објеси ланце плетене о копче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'И напрсник судски начини направе везене онаке као оплећак, од злата, од порфире, од скерлета, од црвца и од танкога платна узведенога начини га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Нека буде четвороугласт и двострук, у дужину с педи и у ширину с педи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'И удари по њему драго камење, у четири реда нека буде камење. У првом реду: сардоникс, топаз и смарагд;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'А у другом реду: карбункул, сафир и дијаманат;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'А у трећем реду; лигур и ахат и аметист;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'А у четвртом реду: хрисолит, оних и јаспид; нека буду уковани у злато у свом реду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'И тијех камена с именима синова Израиљевијех биће дванаест по именима њиховијем, да буду резани као печат, сваки са својим именом, за дванаест племена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'И на напрсник метни ланце једнаке, плетене, од чистога злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'И двије гривне златне начини на напрсник, и метни двије гривне на два краја напрснику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Па провуци два ланца златна кроз двије гривне на крајевима напрснику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'А друга два краја од два ланца запни за двије копче, и метни на пораменице од оплећка спријед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'И начини друге двије гривне златне, и метни их на друга два краја напрснику изнутра на страни која је од оплећка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'И начини још двије златне гривне, и метни их на пораменице од оплећка оздо према саставцима његовијем, више појаса на оплећку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Тако нека вежу напрсник гривне његове за гривне на оплећку врвцом од порфире, да стоји над појасом од оплећка, и да се не одваја напрсник од оплећка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'И нека носи Арон имена синова Израиљевих на напрснику судском на срцу свом кад улази у светињу за спомен пред Господом вазда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'И метни на напрсник судски Урим и Тумим, да буде на срцу Арону кад улази пред Господа, и Арон ће носити суд синова Израиљевих на срцу свом пред Господом вазда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'И начини плашт под оплећак сав од порфире.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'И озго нека буде прорез у сриједи, и нека буде опточен прорез свуда унаоколо траком тканијем, као прорез у оклопа, да се не раздре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'А по скуту му начини шипке од порфире и од скерлета и од црвца свуда унаоколо, и међу њима златна звонца свуда унаоколо:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Звонце златно па шипак, звонце златно па шипак по скуту од плашта свуда унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'И то ће бити на Арону кад служи, да се чује глас кад улази у светињу пред Господа и кад излази, да не погине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'И начини плочу од чистога злата, и на њој изрежи као на печату: светиња Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'И вежи је врвцом од порфире за капу, спријед на капи да стоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'И биће на челу Аронову, да носи Арон гријехе светијех приноса које принесу синови Израиљеви у свијем даровима својих светијех приноса; биће на челу његову вазда, да би били мили Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'И начини кошуљу од танкога платна изметанога, и начини капу од танкога платна, а појас начини везен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'И синовима Ароновијем начини кошуље, и начини им појасе, и капице им начини за част и дику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Па то обуци Арону брату својему и синовима његовијем, и помажи их и напуни им руке и посвети их да ми буду свештеници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'И начини им гаће ланене, да се покрије голо тијело; од бедара до дно стегна да буду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'И то нека је на Арону и на синовима његовијем кад улазе у шатор од састанка или кад приступају к олтару да служе у светињи, да не би носећи гријехе погинули. Ово ће бити уредба вјечна њему и сјемену његову након њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Учинићеш им ово кад их станеш освештавати да ми врше службу свештеничку: узми теле и два овна здрава,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'И хљебове пријесне и колаче пријесне замијешене с уљем, и погаче пријесне намазане уљем, од брашна пшеничнога умијеси их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'И метни их у једну котарицу, и принеси их у котарици с телетом и с два овна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'И доведи Арона и синове његове пред врата шатора од састанка, и умиј их водом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'И узевши хаљине обуци Арону кошуљу и плашт испод оплећка и оплећак и напрсник, и опаши га појасом од оплећка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'И метни му капу на главу и свету плочу на капу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'И узми уље за помазање, и излиј му на главу, и помазаћеш га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'И синове његове доведи и обуци им кошуље;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'И опаши их појасима, Арона и синове његове, и метни им капе на главе, да имају свештенство уредбом вјечном. Тако ћеш посветити руке Арону и синовима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'И доведи теле пред шатор од састанка, а Арон и синови његови нека метну руке телету на главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'И закољи теле пред Господом на вратима шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'И узевши крви од телета помажи рогове олтару прстом својим, а осталу крв сву пролиј на подножје олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'И узми све сало по цријевима, и мрежицу на јетри, и оба бубрега и сало око њих, и запали на олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'А месо од телета и кожу и балегу спали огњем изван окола; то је жртва за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Потом узми овна једнога, и на главу овну нека метну руке своје Арон и синови његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'И закољи овна и узми крви од њега и покропи олтар унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'А овна изуди, и опери дроб и ноге, и метни их на удове његове и на главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'И свега овна запали на олтару; то је жртва паљеница Господу, мирис угодан, жртва огњена Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Па узми и другога овна, и нека му метне Арон и синови његови руке своје на главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'И закољи тога овна, и узми крви од њега и помажи њом крај од деснога уха Арону и крај од деснога уха синовима његовијем, и палац у десне руке њихове и палац у десне ноге њихове, а осталом крвљу покропи олтар унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'И узми крви која буде на олтару и уља за помазање, и покропи Арона и хаљине његове, и синове његове и хаљине њихове, и биће свет он и хаљине његове и синови његови и хаљине њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Потом узми сало од овна и реп и сало што је по цријевима и мрежицу на јетри и оба бубрега и сало око њих, и десно плеће; јер је ован посветни;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'И један хљеб и један колач с уљем и једну погачу из котарице у којој буду пријесни хљебови пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'И то све метни у руке Арону и у руке синовима његовијем, и обрћи тамо и амо, да буде жртва обртана пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'По том узми им то из руку, и запали на олтару сврху жртве паљенице, да буде мирис угодан пред Господом; то је жртва огњена Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'И узми груди од овна посветнога, који буде за Арона, и обртаћеш их тамо и амо, да буде жртва обртана пред Господом; и то ће бити твој дио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Тако ћеш осветити груди од жртве обртане и плеће од жртве подизане, што је обртано и што је подизано од овна посветнога за Арона и за синове његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'И то ће бити Арону и синовима његовијем уредбом вјечном од синова Израиљевих, јер је жртва подизана. Кад је жртва подизана синова Израиљевих од њиховијех жртава захвалнијех, жртва подизана биће Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'А свете хаљине Аронове нека буду синовима његовијем након њега да се помазују у њима и да им се у њима посвећују руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Седам дана нека их облачи који на његово мјесто буде свештеник између синова његовијех, који ће улазити у шатор од састанка да служи у светињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'А овна посветнога узми и скухај месо од њега на мјесту светом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'И Арон и синови његови нека на вратима шатора од састанка једу месо од тога овна и хљеб што је у котарици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Нека га једу они за које је било очишћење да би им се посветиле руке да би били посвећени; а други да не једе, јер је ствар света.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Ако ли би остало што меса посветнога или хљеба до јутра, онда што остане сажежи огњем, а да се не једе, јер је ствар света.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'И тако учини Арону и синовима његовијем по свему што ти заповједих; седам дана светићеш им руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'И сваки ћеш дан приносити на жртву теле за гријех ради очишћења; и очистићеш олтар чинећи очишћење на њему, и помазаћеш га да се освети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Седам дана чинићеш очишћење на олтару и осветићеш га, те ће олтар бити светиња над светињама; што се год дотакне олтара, биће свето.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'И ово ћеш приносити на олтару: два јагњета од године сваки дан без прекида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Једно јагње приноси јутром а друго приноси вечером,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'И јоште десетину ефе пшеничнога брашна смијешана с уљем цијеђеним, којега да буде четврт ина, и наљев вина, четврт ина на једно јагње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'А друго јагње принеси увече; као са жртвом јутрењом и с наљевом њезинијем тако и с овом чини да буде мирис угодан, жртва огњена Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'То нека буде жртва паљеница свагда од кољена до кољена вашега на вратима шатора од састанка пред Господом, гдје ћу се састајати с вама да говорим с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'И ондје ћу се састајати са синовима Израиљевијем, да се освећује славом мојом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'И осветићу шатор од састанка и олтар; и Арона и синове његове осветићу да су ми свештеници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'И наставаћу међу синовима Израиљевијем, и бићу им Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'И познаће да сам ја Господ Бог њихов, који сам их извео из земље Мисирске да наставам међу њима, ја Господ Бог њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Јоште начини олтар кадиони, од дрвета ситима начини га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Дужина нека му буде лакат, и ширина лакат, четвороугласт да буде, и два лакта висок; из њега нека му излазе рогови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'И покуј га чистијем златом, озго са страна унаоколо, и рогове његове; и начини му вијенац златан унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'И начини му по два биочуга златна испод вијенца на два угла његова с обје стране, и кроз њих ћеш провући полуге да се може носити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'А полуге начини од дрвета ситима, и окуј их у злато.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'И метни га пред завјес који виси пред ковчегом од свједочанства према заклопцу који је над свједочанством, гдје ћу се с тобом састајати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'И нека кади на њему Арон кадом мирисним; свако јутро нека кади кад спреми жишке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'И кад запали Арон жишке увече, нека кади; нека буде кад свагдашњи пред Господом од кољена до кољена вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Не приносите на њему када туђега нити жртве паљенице нити приноса; ни наљева не љевајте на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Само очишћење нека чини над роговима његовијем Арон једном у години; крвљу од жртве за гријех у дан очишћења једном у години чиниће очишћења на њему од кољена до кољена вашега; јер је то светиња над светињама Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Јоште рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Кад станеш бројати синове Израиљеве, између онијех који иду у број сваки нека даде откуп за живот свој Господу, кад их станеш бројити, да не би дошло на њих како зло кад их станеш бројити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'А нека да сваки који иде у број по сикла, по сиклу светом (а тај је сикал двадесет новчића); по сикла биће прилог Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Ко год иде у бој, од двадесет година и више, нека да прилог Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Богати да не да више а сиромах да не да мање од по сикла, кад дају прилог Господу на очишћење душа ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'И узевши новце за очишћење од синова Израиљевијех остави их за потребу у шатору од састанка, и биће синовима Израиљевијем спомен пред Господом за очишћење душа ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Начини и умиваоницу од мједи и подножје јој од мједи за умивање; и метни је између шатора од састанка и олтара, и налиј у њу воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Да из ње пере Арон и синови његови руке своје и ноге своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Кад иду у шатор од састанка, нека се умивају водом, да не изгину, или кад приступају к олтару да служе и да пале жртву огњену Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Тада нека перу руке своје и ноге своје да не изгину. То нека им буде уредба вјечна Арону и сјемену његову од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Узми мириса најбољих: смирне најчистије пет стотина сикала и цимета мирисавога пола толико, двјеста педесет, и иђирота такође двјеста педесет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'И касије пет стотина мјером светом, и уља маслинова један ин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'И од тога начини уље за свето помазање, уље најбоље вјештином апотекарском; то да буде уље светога помазања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'И њим помажи шатор од састанка и ковчег од свједочанства,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'И сто и све справе његове, и свијетњак и справе његове, и олтар кадиони,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'И олтар на којем се приноси жртва паљеница, и све справе његове, и умиваоницу и подножје њезино.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Тако ћеш их осветити, те ће бити светиња над светињом, и што их се год дотакне биће свето.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Помажи и Арона и синове његове, и осветићеш их да ми буду свештеници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'А синовима Израиљевијем кажи и реци: ово нека ми буде уље светога помазања од кољена до кољена вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Тијело човјечије нека се не маже њим, нити правите такога уља како је оно; свето је, нека вам буде свето.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Ако ли би ко начинио тако уље или намазао њим другога, истријебиће се из народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'И рече Господ Мојсију: узми мириса, стакте, ониха и халвана мирисавога, и тамјана чистога, колико једнога толико другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'И од тога начини кад, састављен вјештином апотекарском, чист и свет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'И истуцавши га наситно, метаћеш га пред свједочанством у шатору од састанка, гдје ћу се састајати с тобом; то нека вам буде светиња над светињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'А таквога када какав начиниш немојте себи правити; то нека ти је светиња за Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Ако ли би ко начинио таки да га мирише, истријебиће се из народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Гле, позвах по имену Веселеила сина Урије сина Орова од племена Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'И напуних га духа светога, мудрости и разума и знања и сваке вјештине,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Да вјешто измишља како се што може начинити од злата и од сребра и од мједи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Да умије резати камење и укивати, да умије тесати дрво, и сваки посао радити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'И ево удружих с њим Елијава сина Ахисамахова од племена Данова, и свакому вјештом човјеку у срце дадох вјештину да израде све што сам ти заповиједио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Шатор од састанка, и ковчег за свједочанство и заклопац на њ, и све справе у шатору,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'И сто и справе његове, и свијетњак чисти са свијем справама његовијем, и олтар кадиони,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'И олтар за жртву паљеницу са свијем справама његовијем, и умиваоницу и подножје њезино,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'И хаљине службене и свете хаљине Арону свештенику и хаљине синовима његовијем, да врше службу свештеничку,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'И уље помазања, и кад мирисни за светињу. Све нека начине онако како сам ти заповједио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'А ти кажи синовима Израиљевијем и реци: али суботе мој чувајте, јер је знак између мене и вас од кољена до кољена, да знате да сам ја Господ који вас посвећујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Чувајте дакле суботу, јер вам је света; ко би је оскврнио, да се погуби; јер ко би год радио какав посао у њу, истријебиће се она душа из народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Шест дана нека се ради; а седми је дан субота, одмор, свет Господу; ко би год радио посао у дан суботни, да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Зато ће чувати синови Израиљеви суботу празнујући суботу од кољена до кољена завјетом вјечним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'То је знак између мене и синова Израиљевих довијека; јер је за шест дана створио Господ небо и земљу, а у седми дан почину и одмори се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'И изговоривши ово Мојсију на гори Синајској, даде му двије плоче свједочанства, плоче камене писане прстом Божијим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'А народ видјевши гдје Мојсије за дуго не слази с горе, скупи се народ пред Арона, и рекоше му: хајде, начини нам богове, који ће ићи пред нама, јер томе Мојсију који нас изведе из земље Мисирске не знамо шта би.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'А Арон им рече: поскидајте златне обоце што су у ушима жена ваших, синова ваших и кћери ваших, и донесите ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'И поскида сав народ златне обоце што им бијаху у ушима, и донесоше Арону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'А он узев из руку њиховијех, сали у калуп, и начини теле саливено. И рекоше: ово су богови твоји, Израиљу, који те изведоше из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'А кад то видје Арон, начини олтар пред њим; и повика Арон, и рече: сјутра је празник Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'И сјутрадан уставши рано принесоше жртве паљенице и жртве захвалне; и посједа народ, те једоше и пише, а послије усташе да се играју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'А Господ рече Мојсију: иди, сиђи, јер се поквари твој народ, који си извео из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Брзо зађоше с пута, који сам им заповједио; начинише себи теле ливено, и поклонише му се, и принесоше му жртву, и рекоше: ово су богови твоји, Израиљу, који те изведоше из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Још рече Господ Мојсију: погледах народ овај, и ето је народ тврда врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'И сада пусти ме, да се распали гњев мој на њих и да их истријебим; али од тебе ћу учинити народ велик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'А Мојсије се замоли Господу Богу својему, и рече: зашто се, Господе, распаљује гњев твој на народ твој, који си извео из земље Мисирске силом великом и руком крјепком?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Зашто да говоре Мисирци и реку: на зло их изведе, да их побије по планинама и да их истријеби са земље? Поврати се од гњева својега, и пожали народ свој ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Опомени се Аврама, Исака и Израиља, слуга својих, којима си се собом заклео и обрекао им: умножићу сјеме ваше као звијезде на небу, и земљу ову, за коју говорих, сву ћу дати сјемену вашему да је њихова довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'И ражали се Господу учинити зло народу својему, које рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Тада се врати Мојсије, и сиђе с горе са двије плоче свједочанства у рукама својим; и плоче бјеху писане с обје стране, отуд и одовуд писане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'И бјеху плоче дјело Божије, и писмо бјеше писмо Божије, урезано на плочама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'А Исус чувши вику у народу, кад викаху, рече Мојсију; вика убојна у околу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'А он рече: није то вика како вичу који су јачи, нити је вика како вичу који су слабији, него чујем вику онијех који пјевају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'И кад дође близу окола, угледа теле и игре, те се разгњеви Мојсије, и баци из руку својих плоче, и разби их под гором.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Па узе теле које бијаху начинили и спали га огњем, и сатр га у прах, и просу га по води, и запоји синове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'И рече Мојсије Арону: шта ти је учинио овај народ, те га ували у толики гријех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'А Арон му рече: немој се гњевити, господару; ти знаш овај народ да је брз на зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Јер рекоше ми: начини нам богове, који ће ићи пред нама, јер томе Мојсију који нас изведе из земље Мисирске не знамо шта би.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'А ја им рекох: ко има злата, нека га скида са себе. И дадоше ми, а ја га бацих у ватру, и изађе то теле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'А Мојсије видећи народ го, јер га оголи Арон на срамоту пред противницима његовијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Стаде Мојсије на врата од окола, и рече: к мени ко је Господњи. И скупише се пред њега сви синови Левијеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'И рече им: овако каже Господ Бог Израиљев: припашите сваки свој мач уз бедро своје, па прођите тамо и амо по околу од врата до врата, и побијте сваки брата својега и пријатеља својега и ближњега својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'И учинише синови Левијеви по заповијести Мојсијевој, и погибе народа у онај дан до три тисуће људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Јер Мојсије рече: посветите данас руке своје Господу, свак на сину свом и на брату свом, да би вам дао данас благослов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'А сјутрадан рече Мојсије народу: ви љуто сагријешисте; зато сада идем горе ка Господу, еда бих га умолио да вам опрости гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'И врати се Мојсије ка Господу, и рече: молим ти се; народ овај љуто сагријеши начинивши себи богове од злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Али опрости им гријех: ако ли нећеш, избриши ме из књиге своје, коју си написао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'А Господ рече Мојсију: ко ми је згријешио, онога ћу избрисати из књиге своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'А сада иди, води тај народ куда сам ти казао. Ево, мој ће анђео ићи пред тобом, а кад их походим, походићу на њима гријех њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'И Господ би народ зато што начинише теле, које сали Арон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'И рече Господ Мојсију: иди, дигни се одатле ти и народ, који си извео из земље Мисирске, пут земље за коју се заклех Авраму, Исаку и Јакову говорећи: сјемену твојему даћу је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'И послаћу пред тобом анђела, и изагнаћу Хананеје, Амореје и Хетеје и Ферезеје и Јевеје и Јевусеје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'И одвешће вас у земљу гдје тече млијеко и мед; јер нећу сам ићи с тобом зато што си народ тврдоврат, па бих те могао сатрти путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'А народ чувши ову злу ријеч ожалости се, и нико не метну на се својега накита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Јер Господ рече Мојсију: кажи синовима Израиљевијем: ви сте народ тврдоврат; доћи ћу часом усред тебе, и истријебићу те; а сада скини накит свој са себе, и знаћу шта ћу чинити с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'И поскидаше са себе синови Израиљеви наките своје код горе Хорива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'А Мојсије узе шатор и разапе га себи иза окола далеко, и назва га шатор од састанка, и ко год тражаше Господа, долажаше к шатору од састанка иза окола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'И кад Мојсије иђаше у шатор, сав народ устајаше, и свак стајаше на вратима својега шатора, и гледаху за Мојсијем док не уђе у шатор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'А кад Мојсије улажаше у шатор, спушташе се ступ од облака и устављаше се на вратима од шатора, и Господ говораше с Мојсијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'И сав народ видећи ступ од облака гдје стоји на вратима од шатора, устајаше сав народ, и свак се клањаше на вратима од својега шатора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'И Господ говораше с Мојсијем лицем к лицу као што говори човјек с пријатељем својим. Потом се враћаше Мојсије у око, а слуга његов Исус син Навин, момак, не излажаше из шатора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'И рече Мојсије Господу: гледај, ти ми кажеш: води тај народ. А нијеси ми казао кога ћеш послати са мном, а рекао си: знам те по имену и нашао си милост преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Ако сам дакле нашао милост пред тобом, покажи ми пут свој, да те познам и нађем милост пред тобом; и види да је овај народ твој народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'И рече Господ: моје ће лице ићи напријед, и даћу ти одмор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'А Мојсије му рече: ако неће ићи напријед лице твоје, немој нас кретати одавде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Јер по чему ће се познати да смо нашли милост пред тобом, ја и народ твој? зар не по томе што ти идеш с нама? тако ћемо се разликовати ја и народ твој од свакога народа на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'А Господ рече Мојсију: учинићу и то што си казао, јер си нашао милост преда мном и знам те по имену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Опет рече Мојсије: молим те, покажи ми славу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'А Господ му рече: учинићу да прође све добро моје испред тебе, и повикаћу по имену: Господ пред тобом. Смиловаћу се коме се смилујем, и пожалићу кога пожалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'И рече: али нећеш моћи видјети лица мојега, јер не може човјек мене видјети и остати жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'И рече Господ: ево мјесто код мене, па стани на стијену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'И кад стане пролазити слава моја, метнућу те у расјелину камену, и заклонићу те руком својом док не прођем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Потом ћу дигнути руку своју, и видјећеш ме с леђа, а лице се моје не може видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'И рече Господ Мојсију: истеши себи двије плоче од камена као што су биле прве, да напишем на тијем плочама ријечи које су биле на првијем плочама, које си разбио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'И буди готов за сјутра да рано изађеш на гору Синајску, и станеш преда ме на врх горе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Али нека нико не иде с тобом, и нико нека се не покаже на свој гори, ни овце ни говеда да не пасу близу горе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'И истеса Мојсије двије плоче од камена као што су биле прве, и уставши рано изађе на гору Синајску, као што му заповједи Господ, и узе у руку своју двије плоче камене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'А Господ сиђе у облаку, и стаде ондје с њим, и повика по имену: Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Јер пролазећи Господ испред њега викаше: Господ, Господ, Бог милостив, жалостив, спор на гњев и обилан милосрђем и истином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Који чува милост тисућама, прашта безакоња и неправде и гријехе, који не правда кривога, и походи гријехе отачке на синовима и на унуцима до трећега и четвртога кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'А Мојсије брже сави главу до земље и поклони се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'И рече: ако сам нашао милост пред тобом, Господе, нека иде Господ посред нас, јер је народ тврдоврат; и опрости нам безакоње наше и гријех наш, и узми нас за нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'А он рече: ево постављам завјет; пред цијелим народом твојим учинићу чудеса, која нијесу учињена нигдје на земљи ни у ком народу, и видјећете дјело Господње сав народ, међу којим си, јер ће бити страшно што ћу ја учинити с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Држи што ти данас заповједам; ево, ја ћу изагнати испред тебе Амореје и Хананеје и Хетеје и Ферезеје и Јевеје и Јевусеје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Чувај се да не хваташ вјере с онима који живе у земљи у коју ћеш доћи, да ти не буду замка усред тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Него олтаре њихове оборите, и ликове њихове изломите, и гајеве њихове исијеците.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Јер не ваља да се клањаш другому богу: јер се Господ зове ревнитељ, Бог је ревнитељ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Немој хватати вјере с онима који живе у оној земљи, да не би чинећи прељубу за боговима својим и приносећи жртву боговима својим позвали те, и ти јео жртве њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'И да не би кћерима њиховијем женио синове своје, и да не би кћери њихове чинећи прељубу за боговима својим учиниле да синови твоји чине прељубу за боговима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Ливених богова не гради себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Празник пријеснијех хљебова држи; седам дана једи пријесне хљебове, као што сам ти заповједио, на вријеме, мјесеца Авива, јер си тога мјесеца изашао из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Све што отвора материцу моје је, и свако мушко у стоци твојој што отвора материцу, говече или ситна стока.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Али магаре које отвори материцу откупи јагњетом или јаретом; ако ли га не би откупио, сломи му врат; и свакога првенца између синова својих откупи; и да се нико не покаже празан преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Шест дана ради, а у седми дан почини, и од орања и од жетве почини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Празнуј празник седмица, првина жетве пшеничне, и празник бербе на свршетку године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Три пута у години да се свако мушко између вас покаже пред Господом Богом Израиљевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Јер ћу изагнати народе испред тебе, и међе твоје раширићу, и нико неће пожељети земље твоје, кад станеш долазити да се покажеш пред Господом Богом својим три пута у години.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Немој приносити крви од жртве моје уз хљебове киселе, и да не преноћи до јутра жртва празника пасхе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Првине од првога рода земље своје донеси у кућу Господа Бога својега; немој кухати јарета у млијеку мајке његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'И рече Господ Мојсију: напиши себи те ријечи; јер по тијем ријечима учиних завјет с тобом и с Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'И Мојсије оста ондје код Господа четрдесет дана и четрдесет ноћи, хљеба не једући ни воде пијући; и написа Господ на плоче ријечи завјета, десет ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'И кад Мојсије слажаше с горе Синајске, и држаше у руци двије плоче свједочанства слазећи с горе, не знађаше да му кожа на лицу поста свијетла докле говораше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'И видје Арон и сви синови Израиљеви Мојсија, а то му се свијетли кожа на лицу, и не смјеше приступити к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Али их зовну Мојсије, и вратише се к њему Арон и сви главари у збору, и говори с њима Мојсије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Потом приступише сви синови Израиљеви, и заповједи им све што му каза Господ на гори Синајској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'А кад им Мојсије изговори, застрије лице своје покривалом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Али кад Мојсије долажаше пред Господа да с њим говори, скидаше покривало докле не би изашао; а изашавши казиваше синовима Израиљевијем што му се заповједаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Тада виђаху синови Израиљеви лице Мојсијево, гдје се свијетли кожа на лицу његову, те Мојсије опет застираше покривалом лице своје докле не би опет ушао да говори с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Потом сабра Мојсије сав збор синова Израиљевих, и рече им: ово је заповједио Господ да чините:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Шест дана да се ради, а седми да вам је свет, субота почивања Господњега; ко би радио у тај дан, да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Ватре не ложите по становима својим у дан суботни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Још рече Мојсије свему збору синова Израиљевих говорећи: ово је заповједио Господ и рекао:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Скупите између себе прилог Господу; ко год хоће драге воље, нека донесе прилог Господу: злато и сребро и мјед,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'И порфиру и скерлет и црвац и танко платно и костријет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'И коже овнујске црвене обојене и коже јазавчије и дрво ситим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'И уље за видјело, и мирисе за уље помазања и за кад мирисни,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'И камење онихово, и камење за укивање по оплећку и по напрснику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'И који су год вјешти међу вама нека дођу да раде што је заповједио Господ:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Шатор, и наслон његов, и покривач његов, и куке његове, и даске његове, пријеворнице његове, ступове његове и стопице његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'Ковчег, и полуге његове, и заклопац, и завјес,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'Сто, и полуге његове и све справе његове, и хљеб за постављање,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'И свијетњак за видјело са справама његовијем, и жишке његове, и уље за видјело,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'И олтар кадиони, и полуге његове, и уље помазања, и кад мирисни, и завјес на врата од шатора,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'Олтар за жртву паљеницу, и решетку његову од мједи, полуге његове и све справе његове, умиваоницу и подножје њезино,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'Завјесе за тријем, ступове његове и стопице његове, и завјес на врата од тријема,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'Коље за шатор, и коље за тријем с ужима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'Хаљине службене за службу у светињи, и хаљине свете Арону свештенику, и хаљине синовима његовијем за службу свештеничку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Тада отиде сав збор синова Израиљевијех од Мојсија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'И вратише се, сваки којега подиже срце његово и кога год дух покрете драговољно, и донесоше прилог Господу за грађење шатора од састанка и за сву службу у њему и за хаљине свете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Долазише људи и жене, ко год бјеше драговољна срца, и доносише споне и обоце и прстење и наруквице и свакојаке наките златне; и сваки донесе прилог злата Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Ко год имаше порфире, скерлета, црвца, танкога платна, костријети, кожа овнујских црвенијех обојених и кожа јазавчијих, сваки доношаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'И ко год прилагаше сребро или мјед, доношаше у прилог Господу; и у кога год бијаше дрвета ситима, за сваку употребу у служби доношаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'И све жене вјеште предоше својим рукама, и доносише што напредоше за порфиру, скерлет, црвац и танко платно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'И све жене које подиже срце њихово и бијаху вјеште, предоше костријет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'А главари доносише камење онихово и камење за укивање по оплећку и по напрснику,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'И мирисе и уље за видјело и уље за помазање и за кад мирисни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Сви људи и жене, које подиже драговољно срце да доносе што треба за све дјело које Господ заповједи преко Мојсија да се начини, донесоше синови Израиљеви драговољни прилог Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Тада рече Мојсије синовима Израиљевим: видите, Господ позва по имену Веселеила сина Урије сина Орова од племена Јудина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'И напуни га духа Божијега, мудрости, разума и знања и вјештине за сваки посао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Да вјешто измишља како се што ради од злата и сребра и од мједи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Да умије резати камење и укивати, да умије тесати дрво и радити сваки посао врло вјешто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'И даде му у срце, њему и Елијаву сину Ахисамахову од племена Данова, да могу учити друге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Напуни их вјештине да раде сваки посао, да кују, тешу, везу, и ткају порфиру, скерлет, црвац и танко платно, и да раде свакојаке послове вјешто измишљајући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'И стаде радити Веселеило и Елијав и сви људи вјешти, којима бјеше Господ дао мудрост и разум да умију радити сваки посао за службу у светињи, и све што је заповједио Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'И позва Мојсије Веселеила и Елијава и све људе вјеште, којима Господ даде мудрост у срце, које год подиже срце њихово да дођу да раде тај посао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'И узеше од Мојсија све прилоге, које донесоше синови Израиљеви да се уради дјело за службу у светињи. Али још доношаху к њему драговољне прилоге свако јутро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Тада дођоше сви вјешти људи, који рађаху дјело за светињу, сваки од својега посла, који рађаху,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'И рекоше Мојсију говорећи: више доноси народ него што треба да се уради дјело, које је Господ заповједио да се уради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'И заповједи Мојсије да се огласи по околу говорећи: ни човјек ни жена да не доноси више прилога за светињу. И забрани се народу да не доноси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Јер бијаше свега доста да се уради све дјело, и још претјецаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'И људи вјешти између онијех, који радише ово дјело, начинише шатор од десет завјеса од танкога платна узведенога и од порфире и од скерлета и од црвца, с херувимима, вјешто везеним начинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'У дужину бјеше један завјес од двадесет и осам лаката а у ширину од четири лакта; сви завјеси бјеху једне мјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'И саставише пет завјеса један с другим, и пет других завјеса саставише један с другим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'И начинише петље од порфире по крају првога завјеса на оној страни гдје ће се саставити с другим; и тако начинише на сваком завјесу по крају гдје ће се саставити с другим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Педесет петаља начинише на првом завјесу, и педесет петаља начинише на крају свакога завјеса гдје се саставља с другим; петље бјеху једна према другој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'И начинише педесет златнијех кука, и саставише кукама завјесе један с другим; тако се шатор састави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'И начинише завјесе од костријети за наслон над шатором; једанаест таких завјеса начинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'У дужину бјеше један завјес од тридесет лаката а у ширину од четири лакта; једне мјере бјеше свијех једанаест завјеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'И саставише пет завјеса заједно, а других шест завјеса заједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'И начинише педесет петаља по крају једнога завјеса гдје се саставља са другим, и педесет петаља начинише по крају другога завјеса да се састави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'И начинише педесет кука од мједи да се састави наслон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'И начинише покривач на наслон од кожа овнујских црвених обојених, и покривач од кожа јазавчјих озго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'И начинише даске шатору од дрвета ситима, које ће стајати право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Даска бјеше дуга десет лаката а подруг лакта широка свака даска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'По два чепа бјеху на дасци, један према другом; тако начинише на свијем даскама за шатор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'А овијех дасака за шатор начинише двадесет дасака за јужну страну;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'И четрдесет стопица сребрнијех начинише под двадесет дасака, двије стопице под једну даску за два чепа њезина, а двије стопице под другу даску за два чепа њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Тако и на другој страни шатора, према сјеверу, начинише двадесет дасака,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'И четрдесет стопица сребрнијех под њих, двије стопице под једну даску а двије стопице под другу даску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'А на западној страни шатора начинише шест дасака;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'И још двије даске начинише на углове шатору с обје стране;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Оне бијаху састављене оздо, и бијаху састављене озго биочугом; тако начинише с обје стране на два угла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'И тако бијаше осам дасака и шеснаест стопица њиховијех сребрнијех, по двије стопице под сваку даску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'И начинише пријеворнице од дрвета ситима: пет за даске на једној страни шатора,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'И пет пријеворница за даске на другој страни шатора, и пет пријеворница за даске на западној страни шатора до оба угла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'И начинише пријеворницу средњу да иде преко сриједе дасака од једнога краја до другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'А даске оковаше златом, и биочуге на њих начинише од злата, да у њима стоје пријеворнице, и оковаше златом пријеворнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'И начинише завјес од порфире и од скерлета и од црвца и од танкога платна узведенога, с херувимима вјешто везеним начинише га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'И начинише за њ четири ступа од дрвета ситима, и оковаше их златом, а куке на њима бјеху од злата, и салише им четири стопице од сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'И начинише завјес на врата наслону од порфире и од скерлета и од црвца и од танкога платна узведенога везен,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'И пет ступова за њ с кукама њиховијем, и врхове им и појасе оковаше златом, и пет стопица под њих од мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'И начини Веселеило ковчег од дрвета ситима, два и по лакта дуг и подруг лакта широк и подруг лакта висок.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'И покова га чистијем златом изнутра и споља; и начини му златан вијенац унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'И сали му четири биочуга од злата на четири угла његова: два биочуга с једне стране а два с друге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'И начини полуге од дрвета ситима, и окова их златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'И провуче полуге кроз биочуге с обје стране ковчегу, да се може носити ковчег.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'И начини заклопац од чистога злата, у дужину од два и по лакта, а у ширину од подруг лакта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'И начини два херувима од злата, једноставне начини их, на два краја заклопцу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Једнога херувима на крају одовуд, а другога херувима на крају одонуд; заклопцу на оба краја начини херувиме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'И у херувима бјеху крила раширена у вис, и заклањаху крилима својим заклопац, и лицем бјеху окренути један другом, и гледаху према заклопцу херувими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'И начини сто од дрвета ситима, у дужину од два лакта а у ширину од лакта, и од подруг лакта у висину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'И покова га чистим златом, и начини му вијенац златан унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'И начини му оплату с подланице унаоколо, и начини вијенац златан уз оплату унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'И сали му четири биочуга од злата, и метну биочуге на четири угла, који му бијаху на четири ноге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Према оплати бијаху биочузи, а у њима полуге, да се може носити сто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'А полуге начини од дрвета ситима, и окова их златом, да се може носити сто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'И начини од чистога злата посуђе што се меће на сто: здјеле и чаше и кутлиће и виједра, којим ће се прељевати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'И начини свијетњак од чистога злата, једноставан начини свијетњак; ступ му и гране, чашице и јабуке и цвјетови излажаху из њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Шест грана излажаху му са страна; три гране свијетњака с једне стране а три гране свијетњака с друге стране;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Три чашице као бадем на једној грани и јабука и цвијет, а три чашице као бадем на другој грани и јабука и цвијет; тако на свијех шест грана које излажаху из свијетњака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'А на самом свијетњаку бјеху четири чашице као бадем са својим јабукама и цвјетовима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Једна јабука бјеше под двије гране из њега, и једна јабука под друге двије гране из њега, и једна јабука под друге двије гране из њега; тако под шест грана које излажаху из њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Јабуке њихове и гране им излажаху из њега, све бјеше од чистога злата једноставно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'И начини му седам жижака и усекаче и спремице за гар од чистога злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Од таланта чистога злата начини га са свијем справама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'И начини олтар кадиони од дрвета ситима у дужину од једнога лакта, и у ширину од једнога лакта, четвороугласт, и од два лакта у висину; из њега излажаху му рогови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'И покова га чистијем златом озго и са стране унаоколо, и рогове; и начини му вијенац од злата унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'И два биочуга од злата начини му испод вијенца на два угла његова с обје стране, да у њима стоје полуге да се може носити о њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'А полуге начини од дрвета ситима, и окова их златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'И начини уље за свето помазање и чисти кад мирисни вјештином апотекарском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'И начини од дрвета ситима олтар за жртве паљенице у дужину од пет лаката, и у ширину од пет лаката, четвороугласт висок три лакта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'И начини му на четири угла његова рогове; из њега излажаху рогови, и окова га у мјед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'И начини све посуђе за олтар, лонце и лопатице и котлиће и виљушке и клијешта; све му посуђе начини од мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'И начини олтару решетку као мрежу од мједи испод олтара унаоколо ода дна до средине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'И сали четири биочуга за четири угла решетке мједене, да се кроз њих провуку полуге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'А полуге начини од дрвета ситима, и окова их у мјед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'И провуче полуге кроз биочуге с обје стране олтара, да се може носити, од дасака начини га шупља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'И начини умиваоницу мједену и подножје јој мједено од огледала која доношаху гомилама жене долазећи на врата шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'И начини тријем на јужној страни, и завјесе тријему од танкога платна узведенога од сто лаката,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'И двадесет ступова за њих и двадесет стопица под њих од мједи, а куке на ступове и пријеворнице од сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Тако и на сјеверној страни завјесе од сто лаката, двадесет ступова за њих и двадесет стопица под њих од мједи; а куке на ступове и пријеворнице њихове од сребра;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'А на западној страни завјесе од педесет лаката, десет ступова за њих и десет стопица њиховијех од мједи, куке на ступове и појасове њихове од сребра;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'А на предњој страни према истоку завјесе од педесет лаката;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'С једне стране завјесе од петнаест лаката, три ступа за њих и три стопице под њих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'А с друге стране, до врата од тријема и отуда и одовуда, завјесе од петнаест лаката, три ступа за њих и три стопице под њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Сви завјеси на тријему унаоколо бјеху од танкога платна узведенога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'А стопице под ступовима од мједи, куке на ступовима и појасови на њима од сребра; и врхови им бијаху сребрни; сви ступови у тријему бијаху опасани сребром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'А завјес на вратима од тријема бијаше од порфире и од скерлета и од црвца и од танкога платна узведенога, везен, у дужину од двадесет лаката а у висину по ширини пет лаката, као и други завјеси у тријему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'И четири ступа за њ, и четири стопице под њих од мједи, чепови на њима од сребра и врхови им и појасови од сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'А све коље шатору и тријему унаоколо бијаше од мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Те су ствари пребројене за шатор, шатор од свједочанства, које је пребројио по заповијести Мојсијевој Итамар син Арона свештеника за службу Левитску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'А Веселеило син Урије сина Орова од племена Јудина начини све то што заповједи Господ Мојсију,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'И с њим Елијав син Ахисамахов од племена Данова, дрводјеља и вјешт ткати и вести по порфири, по скерлету, по црвцу и по танком платну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'А свега злата што отиде на ово дјело, на све дјело за светињу, које злато бјеше приложено, свега га бјеше двадесет и девет таланата, седам стотина и тридесет сикала, по светом сиклу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'А сребра што дође од збора, сто таланата, и тусућа седам стотина и седамдесет и пет сикала, по светом сиклу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'По сикла од главе, по сиклу светом, од свакога који уђе у број, од двадесет година и више, од шест стотина и три тисуће и пет стотина и педесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Од сто таланата сребра салише се стопице за светињу и стопице за завјес; сто стопица од сто таланата, таланат на стопицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'А од тисућу и седам стотина и седамдесет и пет сикала начини куке на ступове, и окова им врхове и опаса их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'А мједи приложене бијаше седамдесет таланата, и двије тисуће и четири стотине сикала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'И од тога начини стопице на вратима шатора од састанка, и мједени олтар и решетку мједену за њ, и све справе за олтар,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'И стопице у тријему унаоколо, и стопице на вратима од тријема, и све коље за шатор и све коље за тријем унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'А од порфире и скерлета и црвца начинише хаљине за службу, да се служи у светињи; и начинише свете хаљине Арону, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Начинише оплећак од злата, и од порфире и од скерлета и од црвца и од танкога платна узведенога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Истеглише листове од злата, и исјекоше жице, те извезоше порфиру и скерлет и црвац и танко платно врло вјешто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Пораменице му начинише да се састављају, да се саставља на два краја своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'И појас на оплећку излажаше од њега и бјеше исте направе, од злата и од порфире и од скерлета и од црвца и од танкога платна узведенога; као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'И уковаше два камена ониха у злато, и изрезаше на њима имена синова Израиљевих, као што се режу печати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'И ударише их на пораменице од оплећка, да буду камени за спомен синовима Израиљевијем, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'И начинише напрсник врло вјеште направе као што је направа у оплећка, од злата и од порфире и од скерлета и од црвца и од танкога платна узведенога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Четвороугласт и двострук начинише напрсник, у дужину с педи и у ширину с педи, двострук.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'И ударише по њему четири реда камења; у првом реду: сардоникс, топаз и смарагд;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'А у другом реду: карбункул, сафир и дијаманат;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'А у трећем реду: лигур, ахат и аметист;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'А у четвртом реду: хрисолит, оних и јаспид, све опточено златом у својим редовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Тијех камена с именима синова Израиљевијех бјеше дванаест према њиховијем именима, резани као печати, за дванаест племена, свако по свом имену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'И начинише на напрсник ланце једнаке, плетене, од чистога злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'И начинише двије копче златне и двије гривне златне, и метнуше те двије гривне на два краја напрснику,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'И провукоше два златна ланца кроз двије гривне на крајевима напрснику,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'А друга два краја од два ланца запеше за двије копче, и притврдише их за пораменице на оплећку спријед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'И начинише још двије златне гривне, и метнуше их на два краја напрснику на страни према оплећку изнутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'И начинише још двије гривне златне, које метнуше на двије пораменице на оплећку оздо напријед гдје се саставља, више појаса на оплећку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Тако привезаше напрсник кроз гривне на њему и гривне на оплећку врвцом од порфире, да стоји сврх појаса од оплећка и да се не раздваја напрсник од оплећка, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'И начинише плашт под оплећак, ткан, сав од порфире.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'И прорез на плашту у сриједи као прорез на оклопу, и око прореза оплату да се не раздре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'И начинише по скуту од плашта шипке од порфире и од скерлета и од црвца и од танкога платна узведенога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'И начинише звонца од чистога злата, и метнуше звонца међу шипке, по скуту од плашта унаоколо између шипака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Звонце па шипак, звонце па шипак по скуту од плашта унаоколо, за службу, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'И начинише кошуље од танкога платна изметанога Арону и синовима његовијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'И капу од танкога платна, и капице кићене од танкога платна, и гаће платнене од танкога платна узведенога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'И појас од танкога платна узведенога и од порфире и од скерлета и од црвца, везен, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'И начинише плочицу за свето оглавље од чистога злата, и написаше на њој писмом како се реже на печатима: светиња Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'И притврдише за њу врвцу од порфире да се веже за капу озго, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'И тако се сврши сав посао око шатора и наслона од састанка. И начинише синови Израиљеви све; како бјеше заповједио Господ Мојсију, тако начинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'И донесоше к Мојсију шатор, наслон и све справе његове, куке, даске, пријеворнице, ступове и стопице,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'И покривач од кожа овнујских црвених обојених и покривач од кожа јазавчијих, и завјес,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'И ковчег од свједочанства и полуге за њ, и заклопац,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'Сто са свијем справама, и хљеб за постављање,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'Свијетњак чисти, жишке његове, жишке наређане, и све справе његове, и уље за видјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'И олтар златни, и уље помазања, и кад мирисни, и завјес на врата од шатора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'Олтар мједени и решетку мједену за њ, полуге његове и све справе његове, умиваоницу и подножје њезино,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Завјесе за тријем, ступове за њих и стопице њихове, и завјес на врата од тријема, ужа његова и коље његово, и све справе за службу у шатору, за шатор од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Хаљине за службу, да се служи у светињи, хаљине свете Арону свештенику и хаљине синовима његовијем, да врше службу свештеничку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Све како бјеше заповједио Господ Мојсију, онако урадише синови Израиљеви све ово дјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'И погледа Мојсије све то дјело, и гле, начинише га, као што бјеше заповједио Господ, тако га начинише; и благослови их Мојсије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'И Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Први дан првога мјесеца подигни шатор, шатор од састанка,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'И метни ондје ковчег од свједочанства, и заклони га завјесом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'И унеси сто, и уреди што треба уредити на њему; унеси и свијетњак, и запали жишке на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'И намјести златни олтар кадиони пред ковчегом од свједочанства; и објеси завјес на вратима од шатора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'И метни олтар за жртву паљеницу пред врата шатору, шатору од састанка,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'И метни умиваоницу између шатора од састанка и олтара, и у њу налиј воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'И подигни тријем унаоколо, и метни завјес на врата од тријема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'И узми уље помазања, и помажи шатор и све што је у њему, и освети га и све справе његове, и биће свет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Помажи и олтар за жртву паљеницу и све справе његове, те ћеш осветити олтар, и олтар ће бити светиња над светињом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Помажи и умиваоницу и подножје њезино, и освети је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'И кажи Арону и синовима његовијем да приступе на врата шатора од састанка, и умиј их водом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'И обуци Арона у свете хаљине и помажи га и освештај га, да ми врши службу свештеничку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'И синовима његовијем заповједи нека ми приступе, и обуци им кошуље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'И помажи их, као што помажеш оца њихова, да ми врше службу свештеничку; и помазање њихово биће им, за вјечно свештенство од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'И учини Мојсије све, како му заповједи Господ тако учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'И подиже се шатор друге године првога мјесеца први дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'И Мојсије подиже шатор, и подметну му стопице, и намјести даске, и повуче пријеворнице, и исправи ступове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Па разапе наслон над шатор, и метну покривач на наслон озго, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'И узев свједочанство метну га у ковчег, и провуче полуге на ковчегу, и метну заклопац озго на ковчег.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'И унесе ковчег у шатор, и објеси завјес, те заклони ковчег са свједочанством, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'И намјести сто у шатору од састанка на сјеверну страну шатора пред завјесом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'И постави на њему хљеб пред Господом као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'И намјести свијетњак у шатору од састанка, према столу на јужну страну шатора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'И запали жишке на њему пред Господом, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'И намјести олтар златни у шатору од свједочанства пред завјесом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'И покади на њему кадом мириснијем, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'И објеси завјес на врата од шатора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'И олтар за жртву паљеницу намјести на врата од шатора, шатора од састанка, и принесе на њему жртву паљеницу, и дар, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'И метну умиваоницу између шатора од састанка и олтара, и нали у њу воде за умивање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'И праше из ње руке и ноге своје Мојсије и Арон и синови његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Кад улажаху у шатор од свједочанства и кад приступаху к олтару, умиваху се најприје, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'И подиже тријем око шатора и олтара, и метну завјес на врата тријему. Тако сврши Мојсије посао тај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Тада облак покри шатор од састанка, и напуни се шатор славе Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'И не могаше Мојсије ући у шатор од састанка, јер бјеше на њему облак, и славе Господње бјеше пун шатор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'А кад се подизаше облак са шатора, тада полажаху синови Израиљеви, докле год путоваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'А кад се не подизаше облак, онда ни они не полажаху до дана кад се подиже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Јер облак Господњи бјеше на шатору дању, а ноћу огањ бјеше на њему пред очима свега дома Израиљева, докле год путоваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'И викну Господ Мојсија, и рече му из шатора од састанка говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Кажи синовима Израиљевим, и реци им: кад ко између вас хоће да принесе Господу жртву од стоке, принесите жртву своју од говеда или од оваца или од коза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Ако му је жртва паљеница од говеда, нека принесе мушко, здраво; на вратима шатора од састанка нека је принесе драге воље пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'И нека метне руку своју на главу жртви паљеници, и примиће му се, и очистиће га од гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'И нека закоље теле пред Господом, и нека синови Аронови свештеници принесу крв, и покропе олтар крвљу озго унаоколо, који је пред вратима шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Потом нека се одре жртва паљеница и нека се расијече на дијелове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'И синови Аронови свештеници нека наложе огањ на олтару, и метну дрва на огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Па онда синови Аронови свештеници нека намјесте дијелове, главу и сало на дрва на огњу, који је на олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'А цријева и ноге нека се оперу водом; и свештеник нека запали све то на олтару; то је жртва паљеница, жртва огњена на угодни мирис Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Ако ли би хтио принијети жртву паљеницу од ситне стоке, од оваца или од коза, нека принесе мушко, здраво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'И нека се закоље на сјеверној страни олтара пред Господом, и синови Аронови свештеници нека покропе крвљу олтар озго унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'И нека се расијече на дијелове с главом и са салом, и свештеник нека то намјести на дрва на огњу, који је на олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'А цријева и ноге нека се оперу водом; и свештеник нека принесе све то и нека запали на олтару; то је жртва паљеница, жртва огњена на угодни мирис Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Ако ли хоће да принесе птицу Господу на жртву паљеницу, нека принесе жртву од грлица или од голубића.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'И свештеник нека је метне на олтар, и главу нека јој засијече ноктом, и запали на олтару исциједивши јој крв низ олтар са стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'И нека јој извади вољу с нечистотом и баци крај олтара према истоку гдје је пепео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'И нека је задре за крила, али да не раскине; тако нека је свештеник запали на олтару на дрвима која су на огњу; то је жртва паљеница, жртва огњена на угодни мирис Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'А кад ко хоће да принесе на жртву Господу дар, бијело брашно нека буде жртва његова, и нека је полије уљем и метне на њу кад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'И нека је донесе синовима Ароновијем свештеницима, и нека свештеник узме тога брашна пуну шаку и уља и сав кад, и нека то запали свештеник на олтару за спомен њезин; то је жртва огњена на угодни мирис Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'А што остане од тога дара, нека буде Арону и синовима његовијем; то је светиња над светињама између жртава које се пале Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Ако ли хоћеш да принесеш дар печен у пећи, нека буду погаче пријесне од бијелога брашна, замијешене с уљем, или колачи пријесни, намазани уљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Ако ли ти је дар печено што у тави, нека је од бијелога брашна без квасца замијешено с уљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Разломи га на дијелове, и полиј уљем; то је дар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Ако ли ти је дар готовљен у котлићу, нека је од бијелога брашна с уљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'И донеси дар који начиниш од тога Господу, и подај га свештенику, и он ће га однијети на олтар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'И узеће свештеник од дара спомен његов, и запалиће га на олтару; то је жртва огњена на угодни мирис Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'А што остане од дара, нека буде Арону и синовима његовијем; то је светиња над светињама између жртава које се пале Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Ниједан дар који приносите Господу да не буде с квасцем; јер ни квасца ни меда не треба да палите на жртву огњену Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Само у жртви од првина можете принијети то Господу; али на олтар не мећите за угодни мирис.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'А сваки дар који приносиш осоли сољу, и немој оставити дара својега без соли завјета Бога својега; са сваким даром својим принеси соли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'А кад приносиш дар од првина Господу, класове нове осуши на огњу, а што истреш из класова нових принеси на дар од првина својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'И полиј га уљем и кад метни на њ; то је дар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'И свештеник узевши истрвенога жита и уља са свијем кадом нека запали спомен. То је жртва огњена Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Кад ко приноси жртву захвалну, ако од говеда приноси, мушко или женско нека принесе здраво пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'И нека метне руку своју на главу жртви својој, и нека је свештеник закоље на вратима шатора од састанка, и крвљу њезином нека синови Аронови свештеници покропе олтар озго унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Потом нека свештеник принесе од жртве захвалне оно што се пали Господу, сало што покрива цријева и све сало што је на њима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'И оба бубрега и сало што је на њима и на слабинама, и мрежицу што је на јетри, нека је извади с бубрезима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'И нека то запале синови Аронови на олтару заједно са жртвом паљеницом, која буде на дрвима на огњу. То је жртва огњена на угодни мирис Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Ако ли од ситне стоке приноси на жртву захвалну Господу, мушко или женско нека принесе здраво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Ако приноси јагње на жртву, нека га принесе пред Господом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'И нека метне руку своју на главу жртви својој, и нека је закоље пред шатором од састанка; и нека покропе синови Аронови крвљу њезином олтар озго унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Потом нека свештеник принесе од жртве захвалне оно што се пали Господу, сало, цио реп до леђа, сало што покрива цријева и све сало што је на цријевима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'И оба бубрега и сало што је на њима и на слабинама, и мрежицу на јетри, с бубрезима нека је извади;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'И нека запали свештеник на олтару; то је јело од жртве огњене Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Ако ли приноси козу, нека је принесе пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'И нека јој метне руку своју на главу, и нека је закоље пред шатором од састанка, и нека синови Аронови покропе крвљу њезином олтар озго унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Потом нека свештеник принесе од ње на жртву што се пали Господу, сало што покрива цријева и све сало што је на цријевима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'И оба бубрега, и сало што је на њима и на слабинама, и мрежицу на јетри, с бубрезима нека је извади;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'И нека запали свештеник на олтару; то је јело од жртве огњене за угодни мирис. Све је сало Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Вјечан закон нека вам буде од кољена до кољена у свијем становима вашим: да не једете сала ни крви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Кажи синовима Израиљевим, и реци: ако ко згријеши нехотице и учини штогод што је Господ забранио да се не чини,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Ако свештеник помазани згријеши, те буде на гријех народу, нека за гријех свој који је учинио принесе теле здраво Господу на жртву за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'И доведавши теле на врата шатору од свједочанства пред Господа, нека метне руку своју телету на главу, и закоље теле пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'И нека узме свештеник помазани крви од телета, и унесе је у шатор од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'И нека замочи свештеник прст свој у крв, и крвљу седам пута покропи пред Господом пред завјесом од светиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'И нека помаже свештеник том крвљу рогове олтару, на ком се кади мирисима пред Господом у шатору од састанка, а осталу крв од телета сву нека излије на подножје олтару, на ком се пале жртве на вратима шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'И нека извади све сало из телета за гријех, сало што покрива цријева и све сало што је на цријевима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'И оба бубрега, и сало што је на њима и на слабинама, и мрежицу на јетри с бубрезима нека извади,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Онако како се вади из говечета за жртву захвалну; и нека запали свештеник на олтару, на ком се жртва пали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'А кожу од телета и све месо с главом и с ногама и цријева и балегу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'И цијело теле нека изнесе напоље из окола на чисто мјесто, гдје се просипа пепео, и нека га спали огњем на дрвима; на мјесту гдје се просипа пепео нека се спали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Ако ли би сав збор синова Израиљевих згријешио нехотице и не би збор знао за то, И учинили би штогод што је Господ забранио да се не чини, те би скривили,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Кад се дозна за гријех који су учинили, онда нека збор принесе теле на жртву за гријех, и нека га доведу, и нека га доведу пред шатор од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'И старјешине од збора нека метну телету на главу руке своје пред Господом, и свештеник нека закоље теле пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'И свештеник помазани нека унесе крви од телета у шатор од састанка,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'И нека свештеник замочи прст свој у крв, и седам пута покропи пред Господом пред завјесом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'И том крвљу нека помаже рогове олтару који је пред Господом у шатору од састанка, а осталу крв сву нека излије на подножје олтару на ком се пали жртва, на вратима шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'А све сало извадивши из њега нека запали на олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'И с тијем телетом нека чини онако како чини с телетом за свој гријех, тако нека учини с њим; тако ће их свештеник очистити од гријеха, и опростиће им се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'А теле нека изнесе напоље из окола, и спали га као и прво теле; то је жртва за гријех свега збора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Ако ли поглавар згријеши, и учини нехотице штогод што је Господ Бог његов забранио да се не чини, те скриви,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Кад дозна за гријех свој, који је учинио, тада нека доведе на жртву јаре мушко, здраво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'И нека метне руку своју јарету на главу, и свештеник нека га закоље гдје се коље жртва паљеница пред Господом; то је жртва за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'И нека узме свештеник крви од жртве за гријех на прст свој, и помаже рогове олтару на ком се жртва пали; а осталу крв нека излије на подножје олтару на ком се жртва пали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'А све сало нека запали на олтару као сало од жртве захвалне; И тако ће га очистити свештеник од гријеха његова, и опростиће му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Ако ли ко из простога народа згријеши нехотице, и учини штогод што је Господ забранио да се не чини, те скриви,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Кад дозна за гријех свој, који је учинио, тада нека доведе на жртву јаре женско здраво за гријех, који је учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'И нека метне руку своју на главу жртви за гријех, и нека је свештеник закоље на мјесту гдје се коље жртва паљеница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'И нека узме свештеник крви од ње на прст свој, и помаже рогове олтару на ком се пали жртва; а осталу крв сву нека излије на подножје олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'И све сало из ње нека извади као што се вади сало из жртве захвалне, и нека га запали свештеник на олтару за угодни мирис Господу; а тако ће га очистити од гријеха свештеник, и опростиће му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Ако ли би довео између оваца на жртву за гријех, нека доведе женско здраво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'И нека метне руку своју на главу жртви за гријех, и нека је свештеник закоље на мјесту гдје се коље жртва паљеница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'И нека узме свештеник крви од жртве за гријех на прст свој, и нека помаже рогове олтару на ком се пали жртва; а осталу крв сву нека излије на подножје олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'И све сало нека извади као што се вади сало из јагњета за жртву захвалну; и нека га свештеник запали на олтару за жртву огњену Господу; и тако ће га очистити свештеник од гријеха његова, који је учинио, и опростиће му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'И кад ко згријеши што чује клетву и буде јој свједок видјевши или чувши, па не каже, носиће своје безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Или кад се ко дотакне нечисте ствари, стрва од нечисте звијерке или стрва од нечиста живинчета или стрва од нечисте животиње која гамиже, ако и у незнању учини, ипак ће се оскврнити, и биће крив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Или кад се дотакне нечистоте човјечије, била нечистота његова кака му драго, којом се оскврни, знајући или не знајући, крив је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Или кад се ко закуне говорећи својим устима да ће учинити што зло или добро, а за коју год ствар за коју човјек говори заклињући се, знао или не знао, крив је за једну од тијех ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Кад буде крив за коју од тијех ствари, нека призна гријех свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'И нека доведе на жртву Господу за гријех, што је згријешио, женско од ситне стоке, јагње или јаре, за гријех; и свештеник ће га очистити од гријеха његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Ако ли не би могао принијети јагњета или јарета, онда нека донесе на жртву Господу за пријеступ, којим је згријешио, двије грлице или два голубића, једно на жртву за гријех а друго на жртву паљеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Нека донесе свештенику, а он нека принесе прво оно што је за гријех, и ноктом нека му засијече главу к шији, али да не раздвоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'И крвљу жртве за гријех нека покропи стране олтару; а што остане крви нека се исциједи на подножје олтару. То је жртва за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'А од другога нека начини жртву паљеницу по обичају; тако ће га очистити свештеник од гријеха његова, који је учинио, и опростиће му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Ако ли не би могао принијети ни двије грлице или два голубића, онда нека за жртву за то што је згријешио донесе десетину ефе бијелога брашна да буде жртва за гријех, а нека не додаје уља и не меће када, јер је жртва за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'И кад донесе к свештенику, нека узме свештеник пуну шаку за спомен њезин, и нека запали на олтару поред жртве огњене Господу. То је жртва за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'И очистиће га свештеник од гријеха, којим се огријешио у чем год од овога, и опростиће му се; а остатак ће бити свештенику као од дара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Опет рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Ко се превари, те се огријеши нехотице о ствари посвећене Господу, нека принесе на жртву Господу за пријеступ свој овна здрава с цијеном, којом ти прецијениш свету ствар на сикле сребрне, по сиклима светим, према пријеступу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'И тако колико се огријешио о свету ствар нека накнади, и на то још нека дометне пети дио, и нека да свештенику; а свештеник ће га очистити овном принесенијем на жртву за пријеступ, и опростиће му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Ко згријеши и учини што год што је Господ забранио да се не чини, ако и није знао, ипак је крив, и носиће своје безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Нека доведе к свештенику овна здрава с цијеном којом прецијениш пријеступ; и очистиће га свештеник од гријеха његова, који је учинио не знајући, и опростиће му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Пријеступ је; згријешио је Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Опет рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Кад ко згријеши и учини зло дјело Господу ударивши у бах ближњему својему за оставу или за ствар предану у руке или отевши што или занесавши ближњега својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Или нађе изгубљено што, па удари у бах, или се криво закуне за коју год ствар коју може човјек учинити и огријешити се њом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Кад тако згријеши и скриви, нека врати што је отео или присвојио пријеваром или што му је било дано на оставу или што је изгубљено нашао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Или за што се заклео криво, нека плати цијело и још дометне пети дио ономе чије је; нека му да онај дан кад принесе жртву за свој гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'А на жртву за гријех свој нека принесе Господу овна здрава, са цијеном којом прецијениш кривицу нека га доведе свештенику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'И очистиће га свештеник пред Господом, и опростиће му се свака ствар коју је учинио, те скривио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Заповједи Арону и синовима његовијем, и реци им: ово је закон за жртву паљеницу: жртва паљеница нека стоји на огњу на олтару цијелу ноћ до јутра, и огањ на олтару нека гори једнако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Свештеник нека обуче своју хаљину ланену, и гаће ланене нека обуче на тијело своје, и нека згрне пепео кад огањ спали на олтару жртву паљеницу, и нека га изручи код олтара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Потом нека свуче хаљине своје и обуче друге хаљине, и нека изнесе пепео напоље из окола на чисто мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'А огањ што је на олтару нека гори на њему, нека се не гаси, него нека свештеник ложи на огањ дрва свако јутро, и нека намјешта на њ жртву паљеницу, и нека пали на њему сало од жртава захвалних.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Огањ нека једнако гори на олтару, нека се не гаси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'А ово је закон за дар: синови Аронови нека га приносе Господу пред олтаром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Узевши шаку бијелога брашна и уља од дара и сав кад који буде на дару, нека запали на олтару спомен његов на угодни мирис Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'А што претече, нека једе Арон и синови његови; нека се једе без квасца на светом мјесту; у тријему шатора од састанка нека једу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Нека се не мијеси с квасцем; то им дадох да им буде дио од жртава мојих огњених; то је светиња над светињама као жртва за гријех и као жртва за пријеступ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Свако мушко између синова Ароновијех нека то једе законом вјечним од кољена до кољена од жртава које се пале Господу; што се год дотакне тога, биће свето.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Ово је жртва Аронова и синова његовијех, коју ће приносити Господу онај дан кад се који помаже: десетину ефе бијелога брашна за дар свагдашњи, половину ујутру а половину увече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'У тави с уљем нека се готови; пржено нека се донесе; и пржене комаде дара нека принесе на угодни мирис Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'И свештеник између синова његовијех, који буде помазан након њега, нека чини тако исто законом вјечним; нека се пали Господу све то;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'И сваки дар свештеников нека се сав спали, а нека се не једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Кажи Арону и синовима његовијем, и реци: ово је закон за жртву ради гријеха: на мјесту гдје се коље жртва паљеница, нека се коље и жртва за гријех пред Господом; светиња је над светињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Свештеник који принесе жртву за гријех нека је једе; на светом мјесту нека се једе, у тријему од шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Што се год дотакне меса њезина, биће свето; и ако ко покапа крвљу њезином хаљину, оно што покапа нека опере на светом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'И суд земљани у којем буде кухано нека се разбије; ако ли је кухано у суду мједеном, нека се истре и водом опере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Свако мушко између свештеника нека то једе; светиња је над светињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Али ни једна жртва за гријех, од које се унесе крв у шатор од састанка да се учини очишћење од гријеха у светињи, нека се не једе, него нека се огњем сажеже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'А ово је закон за жртву ради пријеступа; светиња је над светињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'На којем се мјесту коље жртва паљеница, на оном нека се коље и жртва за пријеступ; и крвљу њезином нека се покропи олтар озго унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'А све сало њезино нека се принесе, и реп и сало што покрива цријева,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'И оба бубрега, и сало што је на њима и на слабинама, и мрежицу на јетри нека извади с бубрезима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'И нека запали то свештеник на олтару на жртву огњену Господу; то је жртва за пријеступ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Свако мушко између свештеника нека је једе; на светом мјесту нека се једе; светиња је над светињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Жртва је за пријеступ као жртва за гријех, један је закон за обје; који свештеник учини њом очишћење, његова је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'А кад свештеник принесе чију жртву паљеницу, кожа од жртве коју принесе његова је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'И сваки дар печен у пећи или зготовљен у котлићу или у тави, онога је свештеника који га принесе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'И сваки дар замијешен с уљем или сух, свијех је синова Ароновијех, како једнога тако другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'А ово је закон за жртву захвалну, која се принесе Господу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Ако би је ко приносио да захвали, нека принесе на жртву захвалну колаче без квасца замијешене с уљем и погаче без квасца намазане уљем, и бијелога брашна попржена с тијем колачима замијешеним с уљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Осим колача хљеб кисели нека принесе за принос свој са жртвом захвалном, којом захваљује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'И од свега што приноси нека принесе по једно за жртву подигнуту Господу; и то ће бити онога свештеника који покропи крвљу од жртве захвалне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'А месо од жртве захвалне, којом се захваљује, нека се поједе онај дан кад се принесе; и нека не остаје ништа до јутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Ако ли принесе жртву ради завјета или од воље, нека се једе онај дан кад се принесе; ако што остане, нека се поједе сјутрадан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Ако ли што меса од те жртве остане до трећега дана, нека се сажеже огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Ако ли би ко трећи дан јео меса од жртве захвалне, неће бити угодан онај који је принио, нити ће му се она примити, него ће бити мрска, и ко би је год јео, носиће гријех свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'И месо које би се дотакло чега нечистога, да се не једе, него нека се сажеже огњем; а друго месо може јести ко је год чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'А ко би јео меса од жртве захвалне принесене Господу, а не би био чист, тај да се истријеби из народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'И ко се дотакне чега нечистога, или нечиста човјека или нечиста живинчета, или којега му драго гада нечистога, па једе меса од жртве захвалне принесене Господу, тај да се истријеби из народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Кажи синовима Израиљевим, и реци: не једите сала од вола ни од овце ни од козе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Може се узети за сваку потребу сало од живинчета које цркне или га звјерка раздре; али га не једите;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Ко ли би јео сало од стоке коју приноси човјек на жртву огњену Господу, нека се истријеби из народа својега онај који једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Ни крви не једите у становима својим ни од птице нити од којега живинчета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Сваки који би јео какову крв, нека се истријеби из народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Опет рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Кажи синовима Израиљевим, и реци: ко приноси жртву своју захвалну Господу, нека донесе Господу принос свој од жртве захвалне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Својим рукама нека донесе што се сажиже Господу, сало с грудима нека донесе, и груди нека се обрну тамо и амо на жртву пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'А свештеник нека запали сало на олтару, груди пак нека буду Арону и синовима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'И десно плеће од својих жртава захвалних подајте свештенику да буде жртва подигнута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'А који између синова Ароновијех принесе крв и сало од жртве захвалне, њему нека буде десно плеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Јер груди што се обрћу и плеће што се подиже узех од синова Израиљевих од свијех њиховијех жртава захвалних, и дадох Арону свештенику и синовима његовијем законом вјечним да се узимају од синова Израиљевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'То је помазанога Арона и помазаних синова његовијех од огњених жртава Господњих од дана кад их доведе да врше службу свештеничку Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'То заповједи Господ да им од дана кад их помаза дају синови Израиљеви законом вјечним од кољена на кољено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'То је закон за жртву паљеницу, за дар, за жртву ради гријеха и за жртву ради пријеступа, и за освештање и за жртву захвалну,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'Што је Господ заповједио Мојсију на гори Синајској кад заповједи синовима Израиљевим у пустињи Синајској да приносе жртве своје Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Узми Арона и синове његове с њим и одијело и уље помазања и теле за жртву ради гријеха и два овна и котарицу пријесних хљебова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'И сабери сав збор пред врата шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'И учини Мојсије како му заповједи Господ, и сабра се збор пред врата шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'И рече Мојсије збору: ово је заповједио Господ да се учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'И доведе Мојсије Арона и синове његове, и опра их водом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'И обуче му кошуљу, и опаса га појасом, и огрну га плаштем, и метну му сврх њега оплећак, и стеже око њега појас од оплећка, и опаса га њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'И метну на њ напрсник, а на напрсник метну Урим и Тумим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Још му метну капу на главу, и на капу метну спријед плочу златну, круну свету, као што заповједи Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'И узе Мојсије уље помазања, и помаза шатор и све ствари у њему, и освети их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'И покропи њим олтар седам пута, и помаза олтар и све справе његове, и умиваоницу и подножје њезино, да се освети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'И изли уља помазања на главу Арону, и помаза га да се освети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'И доведе Мојсије синове Аронове, и обуче им кошуље, и опаса их појасом, и веза им капице на главе, као што му бјеше заповједио Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'И доведе теле за гријех, и Арон и синови његови метнуше руке своје на главу телету за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'И закла га Мојсије, и узевши крви његове помаза рогове олтару унаоколо прстом својим, и очисти олтар, а осталу крв изли на подножје олтару, и освети га да се на њему чини очишћење од гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'И узе све сало што је на цријевима, и мрежицу с јетре, и оба бубрега, и сало око њих, и запали Мојсије на олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'А теле с кожом и с месом и балегом спали огњем иза окола, као што бјеше Господ заповједио Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'И доведе овна за жртву паљеницу, и Арон и синови његови метнуше руке своје на главу овну;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'И закла га Мојсије, и покропи крвљу његовом олтар озго унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'И исјекавши овна на дијелове запали Мојсије главу и дијелове и сало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'А цријева и ноге опра водом, и тако спали Мојсије свега овна на олтару; и би жртва паљеница за угодни мирис, жртва огњена Господу, као што бјеше Господ заповједио Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'И доведе другога овна, овна за посвећење; и Арон и синови његови метнуше руке своје на главу овну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'И заклавши га Мојсије узе крви његове, и помаза њом крај деснога уха Арону и палац десне руке његове и палац десне ноге његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'И доведе Мојсије синове Аронове, па и њима помаза истом крвљу крај деснога уха и палац десне руке и палац десне ноге; а осталу крв изли Мојсије по олтару унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Потом узе сало и реп и све сало што је на цријевима, и мрежицу с јетре, и оба бубрега, и сало око њих, и плеће десно,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'А из котарице у којој стајаху пријесни хљебови пред Господом узе један колач пријесан, и један колач хљеба с уљем и једну погачу, и метну на сало и на плеће десно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'И метну то све Арону у руке, и синовима његовијем у руке, и обрну тамо и амо за жртву обртану пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Послије узевши то из руку њиховијех Мојсије запали на олтару сврх жртве паљенице; то је посвећење на угодни мирис, жртва огњена Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'И узе Мојсије груди, и обрну их тамо и амо за жртву обртану пред Господом; и од овна посветнога допаде Мојсију дио, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'И узе Мојсије уља за помазање и крви која бјеше на олтару, и покропи Арона и хаљине његове, и синове његове и хаљине њихове с њим; и тако посвети Арона и хаљине његове, и синове његове и хаљине њихове с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Потом рече Мојсије Арону и синовима његовијем: кухајте то месо на вратима шатора од састанка, и ондје га једите и хљеб посветни што је у котарици, као што сам заповједио рекавши: Арон и синови његови нека једу то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'А што остане меса или хљеба, огњем сажезите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'И не излазите с врата шатора од састанка седам дана, докле се не наврше дани посвећења вашега, јер ћете се седам дана посвећивати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Како је било данас, тако је Господ заповједио да се чини, да бисте се очистили од гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Зато на вратима шатора од састанка останите дању и ноћу за седам дана, и извршите што је Господ заповједио да извршите, да не помрете, јер ми је тако заповјеђено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'И Арон и синови његови учинише све што бјеше Господ заповједио преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'А у осми дан сазва Мојсије Арона и синове његове и старјешине Израиљске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'И рече Арону: узми теле за жртву ради гријеха и овна за жртву паљеницу, оба здрава; и принеси их пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'А синовима Израиљевим кажи и реци: узмите јаре за жртву ради гријеха, и теле и јагње, обоје од године дана, и здраво, за жртву паљеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'И вола и овна за жртву захвалну, да принесете пред Господом, и дар с уљем замијешен, јер ће вам се данас јавити Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'И узеше што заповједи Мојсије, и донесоше пред шатор од састанка, и приступивши сав збор стадоше пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'И рече Мојсије: учините што је заповједио Господ, и показаће вам се слава Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'И рече Мојсије Арону: приступи к олтару, и принеси жртву за гријех свој и жртву своју паљеницу, и очисти од гријеха себе и народ; и принеси жртву народу и очисти их од гријеха, као што је заповједио Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Тада Арон приступи к олтару, и закла теле за се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'И синови Аронови додаше му крв, а он замочи прст свој у крв, и помаза рогове олтару; а осталу крв изли на подножје олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'А сало и бубреге и мрежицу од јетре од жртве за гријех запали на олтару, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'А месо и кожу сажеже огњем иза окола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Потом закла жртву своју паљеницу, и синови Аронови додаше му крв од ње, и покропи њом олтар озго унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'И дадоше му жртву паљеницу исјечену на дијелове заједно с главом, и запали је на олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'И оправши цријева и ноге од ње, запали их на олтару сврх жртве паљенице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Потом принесе жртву народну: узе јаре за гријех које бјеше за народ, и закла га, и принесе за гријех као и прво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Иза тога принесе и жртву паљеницу, и сврши по закону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Принесе и дар, и узевши од њега пуну шаку запали на олтару сврх јутрење жртве паљенице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Потом закла вола и овна на жртву захвалну за народ; и дадоше му синови Аронови крв, и покропи њом олтар озго унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Па му додаше и сало од вола, и од овна реп, и сало што покрива цријева, и бубреге и мрежицу с јетре,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'И метнувши све сало на груди, и запали сало на олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'А груди и десно плеће обрну Арон тано и амо на жртву обртану пред Господом, као што бјеше Господ заповједио Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Тада подиже Арон руке своје према народу, и благослови их; и сиђе свршив жртву за гријех и жртву паљеницу и жртву захвалну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Потом уђе Мојсије с Ароном у шатор од састанка, а кад опет изађоше благословише народ; и слава се Господња показа свему народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Јер дође огањ од Господа, и спали на олтару жртву паљеницу и сало. И видјевши то сав народ повика и паде ничице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'А синови Аронови Надав и Авијуд узевши сваки своју кадионицу метнуше огањ у њих и на огањ метнуше кад, и принесоше пред Господом огањ туђ, а то им не бјеше заповједио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Тада дође огањ од Господа и удари их, те погибоше пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Тада рече Мојсије Арону: то је што је казао Господ говорећи: у онима који приступају к мени бићу свет и пред цијелим народом прославићу се. А Арон оћутје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'А Мојсије позва Мисаила и Елисафана синове Озила стрица Аронова, и рече им: ходите и изнесите браћу своју испред светиње напоље из окола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'И приступише и изнесоше их у кошуљама њиховијем напоље из окола, као што рече Мојсије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Тада рече Мојсије Арону и Елеазару и Итамару, синовима његовијем: немојте откривати глава својих, ни хаљина својих раздирати, да не изгинете и да се Господ не разгњеви на сав збор; него браћа ваша, сав род Израиљев, нека плаче ради пожара који учини Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'И с врата шатора од састанка немојте излазити, да не изгинете, јер је на вама уље помазања Господњега. И учинише по ријечи Мојсијевој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'И Господ рече Арону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Вина и силовита пића немој пити ти ни синови твоји с тобом, кад улазите у шатор од састанка да не изгинете. То нека вам је уредба вјечна од кољена на кољено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Да бисте могли распознавати шта је свето шта ли није, и шта је чисто шта ли нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'И да бисте учили синове Израиљеве свијем уредбама које им је казао Господ преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'А Мојсије рече Арону и Елеазару и Итамару синовима његовијем који осташе: узимајте дар што остане од огњених жртава Господњих, и једите с хљебом пријеснијем код олтара, јер је светиња над светињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Зато ћете га јести на светом мјесту, јер је дио твој и дио синова твојих од огњених жртава Господњих; јер ми је тако заповјеђено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'А груди од жртве обртане и плеће од жртве подизане једите на чистом мјесту, ти и синови твоји и кћери твоје с тобом; јер је тај дио дан теби и синовима твојим од захвалних жртава синова Израиљевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Плеће од жртве подизане и груди од жртве обртане доносиће се са салом што се сажиже, да се обрне тамо и амо пред Господом, и биће твоје и синова твојих с тобом законом вјечнијем, као што је заповједио Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'И Мојсије потражи јаре за гријех; али гле, бјеше изгорјело; за то се разгњеви на Елеазара и на Итамара синове Аронове који осташе, и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Зашто не једосте жртве за гријех на светом мјесту? светиња је над светињама, и даде вам је Господ да носите гријех свега збора, да би се очистили од гријеха пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'А ето крв њезина није унесена у светињу; ваљаше вам је јести на светом мјесту, као што сам заповједио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Тада рече Арон Мојсију: ето, данас принесоше жртву своју за гријех и жртву своју паљеницу пред Господом, и то ми се догоди. А да сам данас јео жртве за гријех, би ли било по вољи Господу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Кад чу то Мојсије, приста на то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'И рече Господ Мојсију и Арону говорећи им:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Кажите синовима Израиљевим и реците: ово су животиње које ћете јести између свијех животиња на земљи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Што год има папке и папци су му раздвојени и прежива између животиња, то једите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Али онијех што само преживају или што само имају папке раздвојене, не једите, као што је камила, јер прежива али нема папака раздвојених; да вам је нечиста;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'И питоми зец, јер прежива али нема папака раздвојених; нечист да вам је;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'И зец дивљи, јер прежива али нема папака раздвојених; нечист да вам је;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'И свиња, јер има папке раздвојене али не прежива; нечиста да вам је;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Меса од њих не једите нити се стрва њихова додијевајте; јер вам је нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'А између свега што је у води ово једите: што год има пера и љуску у води, по мору и по ријекама, једите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'А што нема пера и љуску у мору и у ријекама између свега што се миче по води и живи у води, да вам је гадно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Гадно да вам је, меса да им не једете, и на стрв њихов да се гадите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Што год нема пера и љуске у води, то да вам је гадно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'А између птица ове да су вам гадне и да их не једете: орао и јастријеб и морски орао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'Еја и крагуј по својем врстама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'И сваки гавран по својим врстама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'И совуљага и ћук и лиска и кобац по својим врстама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'И буљина и гњурац и ушара,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'И лабуд и гем и сврака,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'И рода и чапља по својим врстама, и пупавац и љиљак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Што год гамиже а има крила и иде на четири ноге, да вам је гадно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Али између свега што гамиже а има крила и иде на четири ноге једите што има стегна на ногама својим, којима скаче по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Између њих једите ове: арба по врстама његовим, салема по врстама његовим, аргола по врстама његовим и агава по врстама његовим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'А што гамиже а има крила и четири ноге, да вам је гадно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'И о њих ћете се оскврнити; ко се год дотакне мртва тијела њихова, да је нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'И ко би год носио мртва тијела њихова, нека опере хаљине своје, и да је нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Свака животиња која има папке али нераздвојене и не прежива, да вам је нечиста; ко их се год дотакне, да је нечист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'И што год иде на шапама између свијех животиња четвороногих, да вам је нечисто; ко би се дотакао стрва њихова, да је нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'И ко би носио стрв њихов, нека опере хаљине своје, и да је нечист до вечера; то да вам је нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'И између животиња које пужу по земљи да су вам нечисте: ласица и миш и корњача по својим врстама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'И јеж и гуштер и твор и пуж и кртица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'То вам је нечисто између животиња које пужу; ко их се дотакне мртвијех, да је нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'И свака ствар на коју падне које од њих мртво биће нечиста, била справа дрвена или хаљина или кожа или торба, и свака ствар која треба за какав посао, нека се метне у воду, и да је нечиста до вечера, послије да је чиста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'А сваки суд земљани, у који падне што од тога, и што год у њему буде, биће нечист, и разбијте га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'И свако јело што се једе, ако на њега дође онака вода, да је нечисто, и свако пиће што се пије у сваком таком суду, да је нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'И на што би пало што од тијела њихова мртва све да је нечисто, и пећ и огњиште да се развали, јер је нечисто и нека вам је нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'А студенац и убао, гдје се вода скупља, биће чист; али што се дотакне стрва њихова, биће нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Ако ли што од стрва њихова падне на сјеме, које се сије, оно ће бити чисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Али ако буде полито сјеме водом, па онда падне што од стрва њихова на сјеме, да вам је нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'И кад угине животиња од онијех које једете, ко се дотакне стрва њезина, да је нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'А ко би јео од стрва њезина, нека опере хаљине своје и да је нечист до вечера; и ко би однио стрв њезин, нека опере хаљине своје, и да је нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'И све што пуже по земљи, да вам је гадно, да се не једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Што год иде на трбуху и што год иде на четири ноге или има више нога између свега што пуже по земљи, то не једите, јер је гад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Немојте се поганити ничим што гамиже и немојте се скврнити њима, да не будете нечисти с њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Јер ја сам Господ Бог ваш; зато се освећујте и будите свети, јер сам ја свет; и немојте се скврнити ничим што пуже по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Јер ја сам Господ, који сам вас извео из земље Мисирске да вам будем Бог; будите дакле свети, јер сам ја свет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Ово је закон за звјери и за птице, и за све животиње што се мичу по води, и за сваку душу живу, која пуже по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Да се распознаје нечисто од чистога и животиња која се једе од животиње која се не једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Кажи синовима Израиљевијем, и реци: кад жена затрудни и роди мушко, нечиста да је седам дана; као у дане кад се одваја ради немоћи своје, биће нечиста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'А у осми дан нека се обреже дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'А она још тридесет и три дана нека остане чистећи се од крви; ни једне свете ствари да се не додијева и у светињу да не иде док се не наврше дани чишћења њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'А кад роди женско, онда да је нечиста двије недјеље дана, као кад се одваја ради немоћи своје, и шездесет и шест дана нека остане чистећи се од крви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'А кад се наврше дани чишћења њезина ради сина или ради кћери, нека донесе свештенику на врата шатора од састанка јагње од године за жртву паљеницу, и голупче или грлицу за жртву ради гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'И свештеник ће принијети жртву пред Господом, и очистиће је од гријеха њезина; и тако ће се очистити од течења крви своје. То је закон за жену кад роди мушко или женско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Ако ли не може дати јагњета, онда нека узме двије грлице или два голубића, једно за жртву паљеницу а друго за жртву ради гријеха; и очистиће је свештеник од гријеха њезина и биће чиста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Јоште рече Господ Мојсију и Арону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Човјек у кога би на кожи тијела његова био оток или краста или бубуљица, и било би на кожи тијела његова налик на губу, нека се доведе к Арону свештенику или ка којему сину његову свештенику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'И нека свештеник види бољетицу на кожи тијела његова; ако длака на бољетици буде побијељела и бољетица буде на очи нижа од остале коже тијела његова, онда је губа; па кад га види свештеник прогласиће га да је нечист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Ако ли буде бијела бубуљица на кожи тијела његова и не буде на очи нижа од остале коже нити длака на њој побијељела, онда нека затвори свештеник за седам дана човјека са таквом бољетицом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'А седмога дана нека види свештеник; ако опази да је бољетица остала како је била и није се даље разишла по кожи, нека га затвори свештеник опет за седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'И нека га свештеник опет види седмога дана, па ако опази да се бољетица смањила и није се даље разишла по кожи; краста је; и он нека опере хаљине своје и биће чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Ако ли се даље рашири краста по кожи његовој, пошто га свештеник види и прогласи да је чист, наново нека се покаже свештенику;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Ако види свештеник да се краста раширила по кожи његовој, прогласиће свештеник да је нечист; губа је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Кад је губа на човјеку, нека га доведу к свештенику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'И свештеник нека га види; ако буде бијел оток на кожи и длака буде побијељела, ако би и здраво месо било на отоку,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'Губа је застарјела на кожи тијела његова; зато ће га свештеник прогласити да је нечист, и неће га затворити, јер је нечист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Ако ли се губа изаспе по кожи и покрију сву кожу човјеку од главе до пете, гдје би год свештеник очима погледао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'Кад свештеник види да је губа покрила сву кожу на њему, прогласиће да је човјек чист, јер је све побијељело, па је чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Али ако се покаже на њему дивље месо, биће нечист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Па кад свештеник види дивље месо, прогласиће га да је нечист; оно је дивље месо нечисто, губа је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'А кад би се дивље месо промијенило и побијељело, нека дође к свештенику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'И кад види свештеник да је бољетица побијељела, свештеник ће прогласити да је чист; чист је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Кад у кога на кожи буде чир, па прође,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'А послије на мјесту гдје је био чир изађе оток бијел или бубуљица бијела и црвенкаста, нека се покаже свештенику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Ако свештеник види да је на очи нижа од остале коже и длака на њој побијељела, прогласиће га свештеник да је нечист, губа је, изашла је из чира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Ако ли свештеник гледајући види да није длака на њој побијељела нити је нижа од коже, него се смањила, онда ће га затворити свештеник за седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Ако се рашири по кожи, онда ће га свештеник прогласити да је нечист; болест је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Ако ли остане на свом мјесту бубуљица и не рашири се, ожиљак је од чира; зато ће га свештеник прогласити да је чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Ако се ко по кожи ожеже огњем, па пошто се залијечи остане бубуљица бијела и црвенкаста или само бијела,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'Нека га види свештеник; ако длака на бубуљици буде побијељела и ако на очи буде нижа него кожа, губа је, изашла је из ожеглине; зато ће га свештеник прогласити да је нечист; губа је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Ако ли свештеник види да на бубуљици нема бијеле длаке нити је нижа од коже, него се смањила, затвориће га за седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Па ће је седмога дана погледати свештеник; ако се буде раширила по кожи, тада ће га свештеник прогласити да је нечист; губа је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Ако ли бубуљица буде остала на свом мјесту, и не буде се раширила по кожи, него се смањила, онда је рана од тога што се ожегао; зато ће га свештеник прогласити да је чист, јер је ожиљак од ожеглине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Ако у човјека или у жене буде бољетица на глави или на бради,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'Свештеник нека види бољетицу; ако на очи буде нижа од остале коже и на њојзи длака жућкаста и танка, свештеник ће прогласити да је нечист; оспа је, губа на глави или на бради;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'А кад свештеник види бољетицу, и опази да на очи није нижа од остале коже и да нема на њој црне длаке, тада ће затворити свештеник за седам дана онога на ком је оспа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Па кад свештеник седми дан види а оспа се није даље разишла нити длака на њој пожутјела, нити је на очи оспа нижа од коже,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Тада нека се обрије, али оспу да не обрије, и свештеник нека затвори још за седам дана онога на ком је оспа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'И седмога дана нека свештеник опет види оспу; ако опази да се оспа није даље разишла по кожи нити је на очи нижа од остале коже, тада ће га прогласити свештеник да је чист, па нека опере хаљине своје, и биће чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Ако ли се рашири оспа по кожи, пошто буде проглашен да је чист,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Тада нека га види свештеник; ако се буде раширила оспа по кожи, нека више не гледа свештеник има ли жутијех длака; нечист је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Ако ли опази да је оспа остала гдје је била и да је црна длака израсла по њој, залијечила се оспа, чист је, и свештеник ће прогласити да је чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Кад у човјека или у жене буду бубуљице по кожи тијела њихова, бубуљице бијеле,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'Свештеник нека види; ако на кожи тијела његова буду бијеле бубуљице мале, бијела је оспа, изашла по кожи, чист је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Коме опадне коса с главе, ћелав је, чист је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Ако му сприједа опадне коса с главе, пола је ћелав, и чист је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Кад на глави сасвијем ћелавој или пола ћелавој буде бијела и црвенкаста бољетица, губа је, изашла на глави свој ћелавој или пола ћелавој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'И нека га види свештеник; ако опази да је бијел и црвенкаст оток на глави свој ћелавој или пола ћелавој налик на губу по кожи осталога тијела,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Човјек је губав, нечист је, и свештеник ће га прогласити да је нечист; губа му је на глави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'А губавац на ком је та болест, нека иде у хаљинама раздртијем и гологлав, и уста нека застре, и нека виче: нечист, нечист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Докле је год болест на њему, нека буде нечист; нечист је, нека живи сам, иза окола нека му буде стан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'И ако на хаљини буде губа, на хаљини вуненој или ланеној,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'Или на основи или на поучици од лана или од вуне, или на кожи, или на чем год од коже,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'И ако бољетица буде зеленкаста или црвенкаста на хаљини или на кожи или на основи или на поучици или на чем год од коже, губа је, и нека се покаже свештенику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'И кад види свештеник болест, нека затвори за седам дана ствар на којој је губа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'И седмога дана ако види да се даље разишла болест по хаљини или по основи или по поучици или по кожи или по чему год од коже, љута је губа болест она, ствар је нечиста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Зато нека спали ону хаљину или основу или поучицу од вуне или од лана, или што год буде од коже, на чем буде болест; јер је љута губа, огњем нека се спали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Ако ли опази свештеник да се болест није разишла по хаљини или по основи или по поучици, или по чему год од коже,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Тада нека заповједи свештеник да се опере оно на чем је болест, па онда нека затвори опет за седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Па нека види свештеник пошто се опере ствар на којој је болест, и ако опази да болест није промијенила боје своје, ако се и не буде даље разишла, ствар је нечиста, спали је огњем; јер је љута губа на горњој или на доњој страни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Ако ли види свештеник да се мјесто смањило пошто је опрано, онда нека откине од хаљине или од коже или од основе или од поучице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Ако ли се опет покаже на хаљини или на основи или на поучици или на чем год од коже, губа је која се шири, огњем спали оно на чем буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'А хаљину или основу или поучицу или што му драго од коже, кад опереш, па отиде с њега та болест, опери још једном, и биће чисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Ово је закон за губу на хаљини вуненој или ланеној, или на основи или на поучици, или на чем год од коже, како се може знати је ли што чисто или нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Ово је закон за губавца када се чисти: нека се доведе к свештенику,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'А свештеник нека изађе иза окола; и ако види да је излијечена губа на губавцу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'Онда ће заповједити свештеник ономе који се чисти да узме двије птице живе чисте, и дрво кедрово и црвца и исопа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'И нека заповједи свештеник да се једна птица закоље над судом земљаним над водом живом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Па нека узме живу птицу и дрво кедрово и црвац и исоп, и све то заједно са живом птицом нека замочи у крв од птице заклане над водом живом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'И нека покропи седам пута онога који се чисти од губе, и нека га прогласи да је чист, и нека пусти живу птицу у поље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Тада који се чисти нека опере хаљине своје и обрије све длаке своје, и нека се окупа у води, и биће чист; потом нека уђе у око, али да стоји напољу не улазећи у свој шатор седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'А у седми дан нека обрије све длаке своје, главу и браду и обрве над очима, и све длаке своје нека обрије, и нека опере хаљине своје, па нека се окупа у води и биће чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'А у осми дан нека узме два јагњета здрава и једну овцу од године здраву и три десетине ефе бијелога брашна замијешена с уљем за дар, и један лог уља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'А свештеник који га чисти нека постави онога који се чисти заједно с тијем стварима пред Господом на вратима шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'И узевши свештеник једно јагње нека га принесе на жртву за пријеступ заједно с логом уља, и нека обрне тамо и амо пред Господом на жртву обртану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'А послије нека закоље јагње на мјесту гдје се коље жртва за гријех и жртва паљеница на светом мјесту, јер жртва за пријеступ припада свештенику као и жртва за гријех; светиња је над светињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Тада нека свештеник узме крви од жртве за пријеступ и помаже крај деснога уха ономе који се чисти и палац десне руке његове и палац десне ноге његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Потом нека узме свештеник од лога уља и налије на длан свој лијеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Па нека замочи свештеник прст од десне руке своје у уље што му је на лијевом длану, и нека покропи уљем с прста својега седам пута пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'А осталијем уљем што му је на длану нека помаже свештеник крај деснога уха ономе који се чисти, и палац десне руке његове и палац десне ноге његове по крви од жртве за пријеступ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'А што још остане од уља на длану свештенику, онијем нека намаже главу ономе који се чисти, и тако ће га очистити свештеник пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Потом нека принесе свештеник жртву за гријех, и очистиће онога који се чисти од своје нечистоте; а послије нека закоље жртву паљеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'И нека принесе свештеник жртву паљеницу заједно с даром на олтару; и тако ће га очистити, и биће чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Али ако је сиромах те не може донијети толико, онда нека узме једно јагње за жртву ради пријеступа да се принесе жртва обртана за очишћење његово, и једну десетину ефе бијелога брашна замијешена с уљем за дар, и лог уља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'И двије грлице или два голубића, које може прискрбити, да буде једно жртва за гријех а друго жртва паљеница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'И то нека донесе у осми дан својега чишћења свештенику на врата шатора од састанка пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Тада свештеник нека узме јагње за пријеступ и лог уља, и то нека свештеник обрне пред Господом за жртву обртану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'И нека закоље јагње за жртву ради пријеступа, и узевши свештеник крви од жртве за пријеступ нека помаже крај деснога уха ономе који се чисти и палац десне руке његове и палац десне ноге његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'И уља нека налије свештеник на длан свој лијеви,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Па нека замочи прст од десне руке своје у уље што му је на лијевом длану, и нека покропи уљем с прста својега седам пута пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'И уљем што му је на длану нека помаже свештеник крај деснога уха ономе који се чисти, и палац десне руке његове и палац десне ноге његове по мјесту гдје је крв од жртве за пријеступ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'А што још остане од уља на длану свештенику, онијем нека намаже главу ономе који се чисти, и тако ће га очистити пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Тако нека учини и с једном грлицом или голупчетом од онијех које прискрби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'Што је прискрбио, једно ће бити жртва за гријех а друго жртва паљеница с даром; и тако ће свештеник очистити пред Господом онога који се чисти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'То је закон за губавца који не може прискрбити свега што треба за очишћење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'И рече Господ Мојсију и Арону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Кад дођете у земљу Хананску, коју ћу вам ја дати да је ваша, па кад пустим губу на коју кућу у земљи коју ћете држати,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Онда онај чија је кућа нека дође и јави свештенику говорећи: чини ми се као да је губа на кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'А свештеник нека заповједи да се испразни кућа прије него он дође да види губу, да се не би оскврнило што је у кући; потом нека дође свештеник да види кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Па кад види болест, ако буде болест на зидовима кућним као рупице зеленкасте или црвенкасте и на очи ниже од зида,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'Нека изађе свештеник из куће оне на врата кућна, и затвори кућу за седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Послије опет нека дође свештеник у седми дан, па ако види да се болест даље разишла по зидовима кућним,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Заповједиће свештеник да поваде камење на ком је болест и да га баце иза града на мјесто нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'А кућу заповједиће да остружу изнутра свуда унаоколо, и прах што састружу да проспу иза града на мјесто нечисто,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'И да узму друго камење и углаве на мјесто гдје је било пређашње камење; тако и блато друго узевши да олијепе кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Ако се поврати болест и опет израсте по кући, пошто се повади камење и оструже кућа и наново олијепи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Тада дошав свештеник ако види да се болест разишла по кући, љута је губа на кући, нечиста је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Нека се разруши она кућа, камење и дрва и сав лијеп од оне куће, и нека се изнесе иза града на мјесто нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'А ко би ушао у кућу ону док је затворена, да је нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'И ко би спавао у оној кући, нека опере хаљине своје; тако и ко би јео у оној кући, нека опере хаљине своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Ако ли свештеник дошав види да се није болест разишла по кући пошто је кућа наново олијепљена, нека прогласи свештеник да је чиста, јер се излијечила болест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'И нека узме да би се кућа очистила двије птице и дрво кедрово и црвца и исопа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'И нека закоље једну птицу над судом земљаним над водом живом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Па нека узме дрво кедрово и исоп и црвац и другу птицу живу, и нека замочи у крв од заклане птице и у воду живу, и покропи кућу седам пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'И тако ће очистити кућу ону крвљу птичијом и водом живом и птицом живом и дрветом кедровијем и исопом и црвцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Па онда нека пусти птицу живу иза града у поље; и очистиће кућу, и биће чиста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Ово је закон за сваку губу и за оспу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'За губу на хаљини и на кући,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'И за оток и за красту и за бубуљицу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'Да се зна кад је ко нечист и кад је ко чист. То је закон за губу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Још рече Господ Мојсију и Арону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Кажите синовима Израиљевијем и реците им: коме човјеку тече сјеме од тијела његова, нечист је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'А овака је нечистота његова од тога течења: ако испусти тијело његово течење своје, или се устави течење у тијелу његову, нечистота је на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Свака постеља на коју лијеже онај коме тече сјеме, да је нечиста; и све на што сједе, да је нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'И ко се год дотакне постеље његове, нека опере хаљине своје и нека се окупа у води, и биће нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'И ко сједе на оно на чим је сједио онај коме тече сјеме, нека опере хаљине своје и нека се окупа у води, и биће нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'И ко се дотакне тијела онога коме тече сјеме, нека опере хаљине своје и нека се окупа у води, и биће нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'И ако онај коме тече сјеме пљуне на чистога, он нека опере хаљине своје и нека се окупа у води, и биће нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'И свако седло на ком би сједио онај коме тече сјеме, да је нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'И ко би се дотакао чега год што је било под њим, да је нечист до вечера; и ко би што таково носио, нека опере хаљине своје и окупа се у води, и биће нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'И кога би се дотакао онај коме тече сјеме не оправши руку својих водом, нека опере хаљине своје и окупа се у води, и биће нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'И суд земљани којега би се дотакао онај коме тече сјеме, нека се разбије, а дрвени суд нека се опере водом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'А кад се онај коме тече сјеме очисти од течења својега, нека броји седам дана пошто се очисти, и нека опере хаљине своје и нека тијело своје опере водом живом, и биће чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'А у осми дан нека узме двије грлице или два голубића, и нека дође пред Господа на врата шатора од састанка, и нека их да свештенику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'И свештеник нека принесе једно од њих на жртву за гријех а друго на жртву паљеницу; тако ће га очистити свештеник пред Господом од течења његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'И човјек коме изађе сјеме кад спава са женом нека опере водом цијело тијело своје, и биће нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'И свака хаљина и свака кожа на којој буде тако сјеме, нека се опере водом и биће нечисто до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'И жена код које буде спавао таки човјек, и она и он нека се окупају у води и биће нечисти до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'А жена кад има вријеме, кад иде крв од тијела њезина, нека се одваја седам дана, и ко је се год дотакне, да је нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'И на што год легне док се одваја, да је нечисто, и на што год сједе, да је нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'И ко се дотакне постеље њезине, нека опере хаљине своје и нека се окупа у води, и биће нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'И ко се дотакне чега на чем је она сједела, нека опере хаљине своје и нека се окупа у води, и биће нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'И што би год било на посттељи њезиној или на чем је она сједјела, па се ко дотакне тога, да је нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'А ко би спавао с њом те би нечистота њезина дошла на њ, да је нечист седам дана, и постеља на којој лежи да је нечиста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'А жена, од које би ишла крв дуго времена или осим обичнога времена или у обично вријеме али дуже, докле год тече нечистота њезина биће нечиста као у вријеме када се одваја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Постеља на којој лежи докле јој год крв иде, да јој је као постеља кад се одваја; и на чем би год сједела да је нечисто као што је нечисто кад се одваја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'И ко се год дотакне тијех ствари, нечист је; зато нека опере хаљине своје и окупа се у води, и биће нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'А кад се очисти од течења крви своје, нека броји седам дана, па онда да је чиста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'И у осми дан нека узме двије грлице или два голубића, и нека их однесе свештенику на врата шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'И нека свештеник принесе једно на жртву за гријехе а друго на жртву паљеницу, и очистиће је свештеник пред Господом од течења нечистоте њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Тако ћете одлучивати синове Израиљеве од нечистота њиховијех, да не гину с нечистота својих скврнећи шатор мој што је усред њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'То је закон за онога коме тече сјеме и коме изађе сјеме кад спава са женом те буде нечист,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'И за жену кад болује од течења крви своје, и за свакога који болује од течења свога, било мушко или женско, и за човјека који би лежао са нечистом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'И рече Господ Мојсију пошто погибоше два сина Аронова, а погибоше кад приступише пред Господа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'И каза Господ Мојсију: реци Арону брату својему да не улази у свако доба у светињу за завјес пред заклопац који је на ковчегу, да не погине, јер ћу се у облаку над заклопцем јављати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'С овијем нека улази Арон у светињу: с јунцем за жртву ради гријеха и с овном за жртву паљеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Свету кошуљу ланену нека обуче, и гаће ланене нека су на тијелу његову, и нека се опаше појасом ланенијем и капу ланену нека метне на главу; то су хаљине свете, и нека опере тијело своје водом, па онда нека их обуче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'А од збора синова Израиљевијех нека узме два јарца за жртву ради гријеха, и једнога овна за жртву паљеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'И нека принесе Арон јунца својега на жртву за гријех и очисти себе и дом свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Потом нека узме два јарца, и нека их метне пред Господа на врата шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'И нека Арон баци ждријеб за та два јарца, један ждријеб Господу а други ждријеб Азазелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'И нека Арон принесе на жртву јарца на којега падне ждријеб Господњи, нека га принесе на жртву за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'А јарца на којега падне ждријеб Азазелов нека метне жива пред Господа, да учини очишћење на њему, па нека га пусти у пустињу Азазелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'И нека Арон принесе јунца својега на жртву за гријех и очисти себе и дом свој, и нека закоље јунца својега на жртву за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'И нека узме кадионицу пуну жеравице с олтара, који је пред Господом, и пуне прегршти када мириснога истуцанога, и нека унесе за завјес.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'И нека метне кад на огањ пред Господом, да дим од када заклони заклопац који је на свједочанству; тако неће погинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Послије нека узме крви од јунца и покропи с прста својега по заклопцу према истоку, а пред заклопцем нека седам пута покропи том крвљу с прста својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'И нека закоље јарца на жртву за гријех народни, и нека учини с крвљу његовом као што је учинио с крвљу јунчијом, и покропи њом по заклопцу и пред заклопцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'И тако ће очистити светињу од нечистота синова Израиљевих и од пријеступа њиховијех у свијем гријесима њиховијем; тако ће учинити и у шатору од састанка, који је међу њима усред нечистота њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'А нико да не буде у шатору од састанка кад он уђе да чини очишћење у светињи, докле не изађе и сврши очишћење за се и за дом свој и за сав збор Израиљски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'А нека изађе к олтару који је пред Господом, и очисти га; и узевши крви од јунца и крви од јарца нека помаже рогове олтару унаоколо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'И нека га покропи озго истом крвљу с прста својега седам пута; тако ће га очистити и посветити га од нечистота синова Израиљевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'А кад очисти светињу и шатор од састанка и олтар, тада нека доведе јарца живога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'И метнувши Арон обје руке своје на главу јарцу живому, нека исповједи над њим сва безакоња синова Израиљевих и све пријеступе њихове у свијем гријесима њиховијем, и метнувши их на главу јарцу нека га да човјеку спремном да га истјера у пустињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'И јарац ће однијети на себи сва безакоња њихова у пустињу; и пустиће онога јарца у пустињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Потом нека опет уђе Арон у шатор од састанка и свуче хаљине ланене које је обукао када је ишао у светињу, и ондје нека их остави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Па нека опере тијело своје на светом мјесту и обуче своје хаљине; и изашав нека принесе своју жртву паљеницу, и очисти себе и народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'А сало од жртве за гријех нека запали на олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'А ко одведе јарца за Азазела, нека опере хаљине своје и окупа тијело своје у води, па онда нека уђе у око.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'А јунца за гријех и јарца за гријех, од којих је крв унесена да се учини очишћење у светињи, нека изнесу напоље из окола, и нека спале огњем коже њихове и месо њихово и балегу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'А ко их спали, нека опере хаљине своје и окупа тијело своје у води, па онда нека дође у око.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'И ово нека вам буде вјечна уредба: десети дан седмога мјесеца мучите душе своје, и не радите никакога посла, ни домородац ни дошљак који се бави међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Јер у тај дан бива очишћење за вас, да се очистите; бићете очишћени од свијех гријеха својих пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'То нека вам је почивање суботно, и мучите душе своје по уредби вјечној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'А свештеник који буде помазан и који буде освећен да врши службу свештеничку на мјесто оца својега, он нека очишћа обукавши се у хаљине ланене, хаљине свете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'И нека очисти светињу свету и шатор од састанка; и олтар нека очисти; и свештенике и сав народ сабрани нека очисти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'И ово нека вам је вјечна уредба да очишћате синове Израиљеве од свијех гријеха њиховијех једанпут у години. И учини Мојсије како му заповједи Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Јоште рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Кажи Арону и синовима његовијем и свијем синовима Израиљевим, и реци им: ово је заповједио Господ говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Ко год од дома Израиљева закоље вола или јагње или козу у околу, или ко год закоље изван окола,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'А не доведе на врата шатора од састанка, да принесе принос Господу пред шатором Господњим, крив је за крв; зато да се истријеби онај човјек из народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Зато синови Израиљеви нека доведу жртве своје, које би клали у пољу, нека их доведу Господу на врата шатора од састанка к свештенику, и нека принесу жртве захвалне Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'И свештеник нека покропи крвљу по олтару Господњем на вратима шатора од састанка, и сало нека запали на угодни мирис Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'И нека више не приносе жртве своје ђаволима, за којима они чине прељубу. Ово нека им буде закон вјечан од кољена на кољено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Зато им реци: ко би год од дома Израиљева или између странаца који се баве међу њима принио жртву паљеницу или другу жртву,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'А не би је довео на врата шатора од састанка да је принесе Господу, тај човјек да се истријеби из народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'А ко би год од дома Израиљева или између странаца који се баве међу њима јео какве год крви, окренућу лице своје на супрот оному човјеку који буде јео крви, и истријебићу га из народа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Јер је душа тијелу у крви; а ја сам вам је одредио за олтар да се чисте душе ваше; јер је крв што душу очишћа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Зато рекох синовима Израиљевим: нико између вас да не једе крви; ни дошљак који се бави међу вама да не једе крви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'И ко би год између синова Израиљевих или између дошљака који се баве код њих уловио звјерку или птицу, која се једе, нека исциједи крв из ње, и заспе је земљом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Јер је душа свакога тијела крв његова, то му је душа. Зато рекох синовима Израиљевим: крви ниједнога тијела не једите, јер је душа свакога тијела крв његова. Ко би је год јео, да се истријеби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'А ко би јео месо од животиње која цркне или коју раскине звјерка, био домородац или дошљак, нека опере хаљине своје и окупа се у води, и биће нечист до вечера, а послије ће бити чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Ако ли их не опере, и тијела својега не окупа, носиће безакоње своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Још рече Господ говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Кажи синовима Израиљевим, и реци им: ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Немојте чинити што се чини у земљи Мисирској, у којој сте живјели, нити чините што се чини у земљи Хананској, у коју вас водим, и по уредбама њиховијем немојте живјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Него моје законе вршите и моје уредбе држите живећи по њима. Ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Држите уредбе моје и законе моје; ко их врши, жив ће бити кроз њих. Ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Нико да не приступа к родици својој по крви, да не открије голотињу њезину. Ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Голотиње оца својега ни голотиње матере своје не откриј; мати ти је; не откриј голотиње њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Голотиње жене оца својега не откриј; голотиња је оца твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Голотиње сестре своје, кћери оца својега или кћери матере своје, која је рођена у кући или изван куће, не откриј голотиње њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Голотиње кћери сина својега, или кћери кћери своје не откриј; јер је твоја голотиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Голотиње кћери жене оца својега, коју је родио отац твој, не откриј; сестра ти је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Голотиње сестре оца својега не откриј; једна је крв са оцем твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Голотиње сестре матере своје не откриј; јер је једна крв с матером твојом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Голотиње брата оца својега не откриј приступајући к жени његовој; стрина ти је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Голотиње жене сина својега не откриј; снаха ти је, не откриј голотиње њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Голотиње жене брата својега не откриј; голотиња је брата твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Голотиње жене и кћери њезине не откриј; кћери сина њезина ни кћери кћери њезине немој узети да откријеш голотињу њихову; једна су крв; зло је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Немој узети жене преко једне жене, да је уцвијелиш откривајући голотињу другој за живота њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'К жени докле се одваја ради нечистоте своје не иди да откријеш голотињу њезину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Са женом ближњега својега не лези скврнећи се с њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Од сјемена својега не дај да се однесе Молоху, да не оскврниш имена Бога својега; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'С мушкарцем не лези као са женом; гадно је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'ЖИвинчета никог немој облежати скврнећи се с њим; и жена да не легне под живинче; грдило је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Немојте се скврнити ни једном овом стварју; јер су се свијем тијем стварима оскврнили народи које ћу одагнати испред вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Јер се оскврнила земља, и неваљалство ћу њезино походити на њој, и изметнуће земља становнике своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Него ви држите законе моје и уредбе моје, и не чините ни једнога овога гада, ни домородац ни дошљак који се бави међу вама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Јер све ове гадове чинише људи у овој земљи који су били прије вас, и земља је од тога оскврњена;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Да не изметне земља вас, ако је оскврните, као што је изметнула народ који је био прије вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Јер ко учини штогод од овијех гадова, истријебиће се из народа својега душе које учине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Зато држите што сам наредио да се држи, да не чините што од гаднијех обичаја који су били прије вас, и да се не скврните о њих. Ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Кажи свему збору синова Израиљевих, и реци им: будите свети, јер сам ја свет, Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Сваки да се боји матере своје и оца својега; и држите суботе моје; ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Не обраћајте се к идолима, и богова ливенијех не градите себи; ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'А кад приносите жртву захвалну Господу, приносите је драге воље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'У који је дан принесете, нека се једе, и сјутрадан; а што остане до трећега дана, нека се огњем сажеже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'А ако би се што јело трећи дан, гад је, неће бити угодна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Ко би год јео, носиће своје безакоње, јер оскврни светињу Господу; зато ће се истријебити она душа из народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'А кад жањете род земље своје, немој пожети сасвијем њиве своје, нити пабирчи по жетви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Ни винограда својега немој пабирчити, и немој купити зрна која падну по винограду твојем; него остави сиромаху и дошљаку. Ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Не крадите; не лажите и не варајте ближњега својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Не куните се именом мојим криво; јер ћеш оскврнити име Бога својега. Ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Не закидај ближњега својега и не отимај му; плаћа надничарова да не преноћи код тебе до јутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Немој псовати глуха, ни пред слијепца метати што да се спотакне; него се бој Бога својега; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Не чините неправде на суду, не гледај што је ко сиромах, нити се поводи за богатијем; право суди ближњему својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Не иди као опадач по народу својем, и не устај на крв ближњега својега; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Немој мрзити на брата својега у срцу својем; слободно искарај ближњега својега, и немој трпјети гријеха на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Не буди осветљив, и не носи срдње на синове народа својега; него љуби ближњега својега као себе самога; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Уредбе моје држите; живинчета својега не пуштај на живинче друге врсте; не засијевај њиве своје двојаким сјеменом, и не облачи на се хаљине од двојаких ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Ако би ко облежао робињу која је испрошена али није откупљена ни ослобођена, обоје да се шибају, али да се не погубе; јер није била ослобођена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'И нека он принесе Господу жртву за пријеступ свој на врата шатора од састанка, овна за пријеступ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'И нека га очисти пред Господом свештеник овном принесеним за пријеступ од гријеха који је учинио; и опростиће му се гријех његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'А кад дођете у земљу и насадите свакојакога воћа, обрежите му окрајак, род његов; три године нека вам је необрезано, и не једите га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'А четврте године нека буде сав род његов посвећен у хвалу Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Па тек пете године једите воће с њега, да би вам се умножио род његов. Ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ништа не једите с крвљу. Немојте врачати, ни гатати по времену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Не стризите косе своје уокруг, ни грдите браде своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'За мртвацем не режите тијела својега, ни ударајте на се каквих биљега. Ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Немој скврнити кћери своје пуштајући је да се курва, да се не би земља прокурвала и напунила се безакоња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Држите суботе моје, и светињу моју поштујте. Ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Не обраћајте се к врачарима и гатарима, нити их питајте, да се не скврните о њих. Ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Пред сиједом главом устани, и поштуј лице старчево, и бој се Бога својега. Ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Ако је у тебе дошљак у земљи вашој, не чини му криво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Ко је дошљак међу вама, нека вам буде као онај који се родио међу вама, и љуби га као себе самога; јер сте и ви били дошљаци у земљи Мисирској. Ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Не чините неправде у суду, ни мјером за дужину, ни мјером за тежину, ни мјером за ствари које се сипају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Мјерила нека су вам права, камење право, ефа права, ин прав. Ја сам Господ Бог ваш, који сам вас извео из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Држите дакле све уредбе моје и све законе моје, и вршите их. Ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Још реци синовима Израиљевим: ко год између синова Израиљевих или између дошљака који се баве у Израиљу, да од сјемена својега Молоху, нека се погуби, народ у земљи нека га заспе камењем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'И ја ћу окренути лице своје на супрот таком човјеку, и истријебићу га из народа његова, што од сјемена својега даде Молоху, и запрзни светињу моју и оскврни свето име моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Ако ли народ како год затвори очи да не види тога човјека кад да од сјемена својега Молоху, и не убију га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'Ја ћу окренути лице своје насупрот оном човјеку и насупрот дому његову, и истријебићу га, и све који за њим чине прељубу чинећи прељубу за Молохом, из народа њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'А ко се обрати к врачарима и гатарима да чини прељубу за њима, окренућу лице своје насупрот њему, и истријебићу га из народа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Зато посвећујте се, и будите свети, јер сам ја Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'И чувајте уредбе моје и вршите их. Ја сам Господ који вас посвећујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Ко опсује оца својега или матер своју, да се погуби; опсовао је оца својега или матер своју; крв његова на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'А човјек који учини прељубу с туђом женом, што је учинио прељубу са женом ближњега својега, да се погуби и прељубочинац и прељубочиница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Ко би спавао са женом оца својега, открио је голотињу оца својега; обоје да се погубе; крв њихова на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Ко би спавао са женом сина својега, обоје да се погубе; учинише срамоту; крв њихова на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Ко би мушкарца облежао као жену, учинише гадну ствар обојица; да се погубе; крв њихова на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'И ко би узео жену и матер њезину, зло је, огњем да се спали и он и она, да не буде зла међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Ко би облежао живинче, да се погуби; убијте и живинче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'И ако би жена легла под живинче, убиј и жену и живинче, нека погину, крв њихова на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Ко би узео сестру своју, кћер оца својега или кћер матере своје, видио би голотињу њезину и она би видјела голотињу његову, срамота је; зато да се истријебе испред синова народа својега; открио је голотињу сестре своје, нека носи безакоње своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'И ко би спавао са женом кад има вријеме и открио голотињу њезину откривши течење њезино, и она би открила течење крви своје, да се истријебе обоје из народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Голотиње сестре матере своје и сестре оца својега не откриј, јер би открио своју крв; нека носе безакоње своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'А ко би спавао са женом стрица својега, открио би голотињу стрица својега, нека носе обоје гријех свој, нека помру без дјеце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Ко би узео жену брата својега, ружно је, открио је голотињу брата својега; без дјеце да буду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Чувајте све уредбе моје и све законе моје, и вршите их, да вас земља не изметне, у коју вас водим да живите у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Немојте живјети по уредбама народа које ћу отјерати испред вас, јер су чинили све то, зато ми омрзоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'И рекох вам: ви ћете наслиједити земљу њихову и ја ћу вам је дати у државу, земљу у којој тече млијеко и мед. Ја сам Господ Бог ваш, који вас одвојих од других народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Зато разликујте стоку чисту од нечисте, и птицу чисту од нечисте, и немојте скврнити душа својих стоком или птицом или чим год што пуже по земљи, што сам вам одвојио да је нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'И бићете ми свети, јер сам свет ја, Господ, и одвојих вас од других народа да будете моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'А човјек или жена, у којима би био дух врачарски или гатарски, да се погубе, камењем да се заспу, крв њихова на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Још рече Господ Мојсију: кажи свештеницима синовима Ароновијем, и реци им: за мртвацем да се не скврни ни један у народу својем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Осим за родом својим по крви, за матером својом или за оцем својим или за сином својим или за кћерју својом или за братом својим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'Или за рођеном сестром својом, дјевојком, која није имала мужа; за њом се може оскврнити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Ако је ожењен, да се не оскврни за женом својом у народу својем учинивши се нечист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Да се не начине ћелави чупајући косу с главе своје и да не брију браде своје, нити се режу по тијелу својем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Нека буду свети Богу својему, и нека не скврне имена Бога својега, јер приносе жртве огњене Господње, хљеб Бога својега, зато нека су свети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Нека се не жене женом курвом или силованом; ни пуштеницом нека се не жене; јер су свети Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'И теби нека је сваки свет, јер приноси хљеб Бога твојега; свет нека ти је, јер сам ја свет, Господ, који вас посвећујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'А кћи свештеничка која се оскврни курвајући се, скврни оца својега, огњем нека се спали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'А свештеник највиши између браће своје, којему се на главу излило уље помазања и који је посвећен да се облачи у свете хаљине, нека не открива главе своје, и хаљине своје нека не раздире.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'И к мртвацу ни једном нека не иде, ни за оцем својим ни за матером својом да се не оскврни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'И из светиње нека не излази, да не би оскврнио светињу Бога својега, јер је на њему вијенац, уље помазања Бога његова; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Он нека се жени дјевојком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Удовицом ни пуштеницом ни силованом ни курвом да се не жени; него дјевојком из народа својега нека се ожени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'И нека не скврни сјеме народа својега у народу својем, јер сам ја Господ, који га посвећујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Опет рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Кажи Арону и реци: у кога би из сјемена твојега од кољена до кољена била мана на тијелу, онај нека не приступа да приноси хљеб Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Јер нико на коме би била мана не ваља да приступа, ни слијеп, ни хром, ни у кога би био који уд превећ мали или превећ велики,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Ни у кога је сломљена нога или рука.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Ни грбав, ни дрљав, ни ко има биону на оку, ни шугав, ни лишајив, ни просут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'У кога би год из сјемена Арона свештеника била кака мана на тијелу, нека не приступа да приноси жртве огњене Господу; мана је на њему; да не приступа да приноси хљеб Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Али хљеб Бога својега од ствари пресветих и од ствари светих нека једе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Али за завјес нека не улази; к олтару нека се не приближује, јер је мана на њему, па нека не скврни светиње моје, јер сам ја Господ који их посвећујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'И Мојсије каза то Арону и синовима његовијем и свијем синовима Израиљевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Кажи Арону и синовима његовијем да се чувају од светијех ствари синова Израиљевих, да не би оскврнили свето име моје у оном што ми они посвећују; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Реци им: ко би год из сјемена вашега од кољена на кољено приступио к светијем стварима, које би посветили синови Израиљеви Господу, кад је нечистота његова на њему, тај нека се истријеби испред лица мојега; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Ко би год из сјемена Аронова био губав или би ишло сјеме од њега, нека не једе светијех ствари докле не буде чист; тако и који би се дотакао кога нечиста од мртва тијела или онога од кога је изашло сјеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Или ко би се дотакао чега што гамиже по земљи, од чега би се оскврнио, или човјека од којега би се оскврнио какве му драго нечистоте његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Ко би се дотакао такога чега, биће нечист до вечера; зато нека не једе светијех ствари ако не окупа тијела својега у води.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'А кад зађе сунце, биће чист, и онда може јести од светијех ствари; јер му је храна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Мрцинога или што раскине звјерка нека не једе, да се њим не скврни; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Тако нека држе што сам уредио да се држи, да не навуку на се гријеха и не умру од њега оскврнивши се. Ја сам Господ, који их посвећујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Нико други да не једе светијех ствари, ни укућанин свештеников ни надничар да не једе светијех ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'А кад свештеник купи кога за новце, тај нека их једе, и који се роди у кући његовој; они нека једу јела његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Али кћи свештеничка кад се уда за човјека другога племена, она да не једе од жртава подигнутијех светијех ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'А кћи свештеничка ако обудови, или је пусти муж, ако нема порода, нека се врати кући оца својега као што је била у дјетињству својем, хљеб оца својега нека једе; али нико другога племена да га не једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'А ко би нехотице јео свету ствар, нека дометне пети дио и накнади свештенику свету ствар,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Да не би оскврнили светијех ствари синова Израиљевих, које приносе Господу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'И да не би навлачили на њих кара за пријеступ једући свете ствари њихове, јер сам ја Господ, који их посвећујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Кажи Арону и синовима његовијем и свијем синовима Израиљевијем и реци им: ко год од дома Израиљева или од странаца који су у Израиљу хоће да принесе жртву своју по каквом год завјету свом, или од добре воље своје дар, што се приноси Господу на жртву паљеницу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'Нека принесе драге воље мушко здраво од говеда или од оваца или од коза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'На чем би била мана, оно не приносите, јер вам се не би примило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'И кад ко хоће да принесе жртву захвалну Господу, извршујући завјет или од своје воље дајући дар, од говеда или од ситне стоке, нека буде здраво, да би било примљено; никаке мане да нема на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Слијепо, или којему је што сломљено или одбијено, ни гутаво, ни краставо ни лишајиво, што је тако не приносите Господу, и не мећите их на олтар Господњи на жртву огњену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'А вола или овцу или козу са удом којим превеликим или премалим можеш принијети за добровољни дар; али за завјет неће се примити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Ујаловљено увртањем, тучењем, кидањем или резањем, не приносите Господу; и не чините тога у земљи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'И из руке туђинске немојте узимати ни једне ствари да принесете хљеб Богу својему; јер је квар њихов у њима; имају ману, неће вам се примити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Теле и јагње и јаре кад се омлади, нека буде седам дана код мајке своје, па од осмога дана и послије биће угодно за жртву огњену Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'А краве ни овце ни козе не кољите у један дан с младетом њезинијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'И кад приносите Господу жртву ради хвале, принесите је драговољно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Нека се једе истога дана, и не остављајте ништа до јутра; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Зато држите заповијести моје, и вршите их; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'И немојте скврнити светога имена мојега, и ја ћу се светити међу синовима Израиљевим; ја сам Господ, који вас посвећујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Који сам вас извео из земље Мисирске да вам будем Бог; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Кажи синовима Израиљевим, и реци им: празници Господњи, које ћете звати свети сабори, ово су празници моји:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Шест дана ради, а седми дан, који је субота за почивање, нека буде свети сабор, не радите ни једнога посла; субота је Господња по свијем становима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Ово су празници Господњи, сабори свети, на које ћете се сабирати у вријеме њихово:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Четрнаестога дана првога мјесеца у вече пасха је Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'А петнаестога дана истога мјесеца празник је пријеснијех хљебова Господу; седам дана једите хљебове пријесне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Први дан нека вам буде сабор свети, никаквога посла ропскога не радите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Него за седам дана приносите Господу жртве огњене; а седми дан нека је сабор свети; не радите ниједнога посла ропскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Кажи синовима Израиљевим, и реци им: кад дођете у земљу коју ћу вам дати, и станете жети у њој, тада донесите сноп првина од жетве своје к свештенику;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'А он нека обрће сноп пред Господом, да би вам се примио; сјутрадан по суботи нека га обрће свештеник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'А исти дан кад будете обртали сноп, принесите јагње од године дана здраво на жртву паљеницу Господу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'И дар уза њ, двије десетине ефе бијелога брашна замијешена с уљем, да буде жртва огњена Господу на угодни мирис; и наљев уза њ, вина четврт ина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'А хљеба, ни зрна пржена ни зрна у класу немојте јести до онога дана кад принесете жртву Богу својему; то да вам је вјечна уредба од кољена до кољена по свијем становима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Потом од првога дана по суботи, од дана кад принесете сноп за жртву обртану, бројте седам недјеља пунијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'До првога дана по седмој недјељи набројте педесет дана; онда принесите нов дар Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Из станова својих донесите два хљеба за жртву обртану; од двије десетине ефе бијелога брашна да буду, с квасцем нека буду печени; то су првине Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'А с тијем хљебом принесите седам јагањаца од године здравијех, и једно теле и два овна, да буде жртва паљеница Господу с даровима својим и наљевима својим, да буде жртва огњена на угодни мирис Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Закољите и јарца једнога за гријех и два јагњета од године за жртву захвалну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'И свештеник нека то обрне тамо и амо с хљебом од првина и са два јагњета на жртву обртану пред Господом; и биће свете ствари Господу за свештеника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'И саберите се у онај дан, сабор свети да вам је; ни једнога посла ропскога не радите законом вјечним по свијем становима својим од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'А кад станете жети у земљи својој, немој сасвијем пожети њиве своје, ни пабирчи по жетви; остави сиромаху и дошљаку; ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Кажи синовима Израиљевим, и реци им: први дан седмога мјесеца нека вам је одмор, спомен трубни, сабор свети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Ни једнога посла ропскога немојте радити, него принесите жртву огњену Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'А десети је дан тога мјесеца седмога дан очишћења; сабор свети нека вам је, и мучите душе своје, и принесите Господу жртву огњену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'У тај дан немојте радити ни једнога посла, јер је дан очишћења, да се очистите пред Господом Богом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'А свака душа која се не би мучила у тај дан, да се истријеби из народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'И сваку душу која би радила какав посао у тај дан, ја ћу затрти душу ону у народу њезину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Ниједнога посла немојте радити; то да је вјечна уредба од кољена до кољена у свијем становима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Субота почивања нека вам буде, и мучите душе своје; деветога дана истога мјесеца кад буде вече, од вечера до вечера празнујте починак свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Кажи синовима Израиљевим, и реци: петнаестога дана седмога мјесеца празник је сјеница за седам дана Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Први дан нека буде сабор свети, ниједнога посла ропскога немојте радити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'За седам дана приносите жртве огњене Господу; осми дан нека вам буде сабор свети, и принесите жртве огњене Господу; празник је, ниједнога посла ропскога немојте радити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'То су празници Господњи, које ћете празновати на саборима светим да принесете жртве огњене Господу: жртву паљеницу и дар и жртву захвалну и наљев, све кад је чему дан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Осим субота Господњих и осим дарова ваших и осим свијех завјета ваших и осим свијех добровољнијех приноса ваших, које ћете давати Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Али петнаести дан тога мјесеца седмога, кад саберете род земаљски, празнујте празник Господу седам дана; у први је дан одмор и у осми је дан одмор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'У први дан узмите воћа с лијепих дрвета, и грана палмовијех и грана с густијех дрвета и врбе с потока, и веселите се пред Господом Богом својим седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'И празнујте тај празник Господу седам дана сваке године законом вјечним од кољена до кољена, седмога мјесеца празнујте га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'И под сјеницама будите седам дана, ко је год рођен у Израиљу нека буде под сјеницама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Да би знало натражје ваше да сам ја учинио да живе под сјеницама синови Израиљеви кад сам их извео из земље Мисирске. Ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'И Мојсије каза празнике Господње синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Заповједи синовима Израиљевим нека ти донесу уља маслинова чиста, цијеђена, за видјело, да жишци горе вазда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Пред завјесом свједочанства у шатору од састанка Арон ће их намјештати да горе од вечера до јутра пред Господом вазда законом вјечним од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'На свијетњак чисти намјештаће жишке пред Господом вазда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'И узми бијелога брашна, и испеци дванаест колача, сваки колач да буде од двије десетине ефе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'И постави их у два реда, по шест у један ред, на чистом столу пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'И на сваки ред метни када чистога, да буде за сваки хљеб спомен, жртва огњена Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Сваке суботе нека их поставља свештеник пред Господом вазда узимајући од синова Израиљевих законом вјечним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'И биће Аронови и синова његовијех, који ће јести на мјесту светом, јер им је светиња над светињама од огњенијех жртава Господњих законом вјечним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'А изађе син једне Израиљке, којему је отац био Мисирац, међу синове Израиљеве, и свади се у околу син жене Израиљке с неким Израиљцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'И псујући син жене Израиљке похули на име Божије, те га доведоше к Мојсију; а мати му бјеше по имену Саломита, кћи Давријина, од племена Данова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'И метнуше га у затвор докле им се каже шта ће чинити с њим по ријечи Господњој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'А Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Изведи тога псовача напоље из окола, и нека сви који су чули метну руке своје на главу његову, и нека га сав народ заспе камењем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'А синовима Израиљевим кажи и реци: ко би год похулио Бога својега, носиће гријех свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Ко би ружио име Господње, да се погуби, сав народ да га заспе камењем; и дошљак и домородац који би ружио име Господње, да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'И ко убије човјека, да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'А ко убије живинче, нека врати друго, живинче за живинче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'И ко рани ближњега својега, како учини тако да му буде:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Улом за улом, око за око, зуб за зуб; како оштети тијело човјеку, онако да му се учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Ко убије живинче, да врати друго; али ко убије човјека, да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Закон да вам је један, дошљаку да буде као и рођеном у земљи. Јер сам ја Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'И Мојсије каза синовима Израиљевим, а они изведоше псовача напоље из окола, и засуше га камењем; и учинише синови Израиљеви како Господ заповједи Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Још рече Господ Мојсију на гори Синајској говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Кажи синовима Израиљевим, и реци им: кад дођете у земљу коју вам ја дајем, нека празнује земља суботу Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Шест година засијевај њиву своју, и шест година режи виноград свој и сабирај род.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'А седма година нека буде субота за одмор земљи, субота Господња; немој сијати у пољу својем ни резати винограда својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Што само од себе роди иза жетве твоје немој жети, и грожђа у винограду својем нерезаном немој брати; нека буде година одмора земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Али што роди земља за почивања својега, оно нека вам буде храна, теби и слузи твојему и слушкињи твојој и најамнику твојему и укућанину твојему који је код тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'И стоци твојој и свијем животињама што су у твојој земљи, сав род њезин нека буде храна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'И наброј седам седмина година, седам пута по седам година, тако да ти седам седмина година буде четрдесет и девет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Тада заповједи нека затруби труба десети дан седмога мјесеца, на дан очишћења нека труби труба по свој земљи вашој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'И посветите годину педесету, и прогласите слободу у земљи свима који живе у њој; то нека вам је опросна година, и тада се вратите сваки на своју баштину, и сваки у род свој вратите се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Опросна година да вам је та педесета година; немојте сијати, нити жањите што само роди те године, нити берите грожђа у виноградима нерезанијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Јер је опросна година; нека вам је света; са свакога поља једите род његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Те године опросне вратите се сваки на своју баштину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'И ако продаш што ближњему својему или купиш што од ближњега својега, не варајте један другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Према броју година по опросној години купуј од ближњега својега, и према броју година у које ћеш брати род нека ти продаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Што више буде година то ће цијена бити већа ономе што купујеш, а што мање буде година то ће мања бити цијена, јер ти се продаје број љетина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Зато не варајте један другога, него се бојте Бога својега; јер сам ја Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Држите уредбе моје и чувајте законе моје и вршите их, па ћете живјети у земљи без страха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'И земља ће рађати род свој, и јешћете га, и бићете сити, и живјећете у њој без страха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'И ако бисте рекли: шта ћемо јести седме године, ето нећемо сијати нити ћемо брати љетине?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Пустићу благослов свој на вас шесте године, те ће родити за три године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'И сијаћете осме године, а јешћете љетину стару до девете године, докле не приспије род њезин, јешћете стари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Али да се земља не продаје за свагда, јер је моја земља, а ви сте дошљаци и укућани код мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Зато по свој земљи државе ваше нека се откупљују земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Ако осиромаши брат твој и прода нешто од баштине своје, а послије дође ко од рода његова најближи њему да откупи, нека откупи што брат његов продаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Ако ли не би имао никога да откупи, него би се помогао и зглавио колико треба за откуп,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Онда нека одбије године откако је продао, па што остане нека исплати ономе коме је продао, и тако нека опет дође до своје баштине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Ако ли нема колико би требало вратити, онда остаје ствар продана у онога који је купио до године опросне, а опросне године оставиће се, и он ће се вратити на своју баштину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Ко прода кућу у којој се сједи у мјесту ограђену зидом, властан је откупити је докле се не наврши година дана откако је прода; цијелу годину дана има власт откупити је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'А ако не откупи за годину дана, онда остаје кућа у мјесту ограђену зидом ономе који је купио сасвијем од кољена на кољено, и неће је оставити опросне године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'А куће по селима, које нијесу ограђене зидом, нека се узимају као њиве, могу се откупити, и године опросне враћају се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'А мјеста Левитска и куће у мјестима њиховијем, свагда могу откупити Левити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Али ко купи од Левита, нека опросне године остави купљену кућу и што је имао у мјесту; јер куће по мјестима Левитским јесу њихове међу синовима Израиљевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Али поље под мјестима њиховијем да се не продаје; јер је њихово достојање довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Ако осиромаши брат твој и изнемогне рука његова поред тебе, прихвати га, и као странац и дошљак нека поживи уз тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Немој узимати од њега камате ни добити; него се бој Бога, да би поживио брат твој уз тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Новаца немој му давати на камату, нити му хране своје позаимај ради добити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Ја сам Господ Бог ваш, који сам вас извео из земље Мисирске да вам дам земљу Хананску и да вам будем Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'И ако осиромаши брат твој код тебе тако да ти се прода, немој га држати као роба;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Као најамник и као дошљак нека буде код тебе; до опросне године нека служи код тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'А онда нека иде од тебе са синовима својим, нека се врати у род свој, и на баштину отаца својих нека се врати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Јер су моје слуге, које сам извео из земље Мисирске, нека се не продају као робови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Немој господарити над њим жестоко, него се бој Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'А роб твој и робиња твоја што ћеш имати нека буду од онијех народа који ће бити око вас, од њих купујте роба и робињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'И између странаца који буду код вас, између њих купујте и из породица онијех који буду код вас, који се роде у земљи вашој, и ти нека вам буду имање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Они ће постати ваши и синова ваших након вас, и биће вам достојање, да вам сваку службу врше до вијека; али над браћом својом, синовима Израиљевим, нико над братом својим да не господари жестоко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Ако ли се обогати дошљак или гост који живи с тобом, а брат твој осиромаши код њега тако да се прода дошљаку, који живи с тобом, или коме год од туђега рода,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Кад се прода, може се откупити; ко год од браће његове нека га откупи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Или стриц његов, или син стрица његова нека га откупи, или ко други од крви његове у роду његову нека га откупи; или ако се помогне, нека се сам откупи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Нека се прорачуна с купцем својим од године кад се продао до године опросне, да цијена за коју се продао дође према броју година; као надничару нека му се рачуна вријеме које је отслужио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Ако остаје још много година, према њима нека плати откуп од цијене за коју је купљен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Ако ли остаје мало година до опросне године, нека се прорачуна с њим и нека плати откуп према тијем годинама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Као најамник годишњи нека буде у њега, и нека не господари над њим жестоко на твоје очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Ако ли се овако не откупи, нека отиде године опросне и он и синови његови с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Јер су синови Израиљеви моје слуге, моје су слуге, које сам извео из земље Мисирске; ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Немојте градити себи идола ни ликова резанијех, нити ступова подижите, ни камена са сликама мећите у својој земљи да му се клањате; јер сам ја Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Држите суботе моје, и светињу моју поштујте; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Ако уживите по мојим уредбама, и заповјести моје уздржите и ушчините,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Даваћу вам дажд на вријеме, и земља ће рађати род свој, и дрвета ће у пољу рађати род свој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'И вршидба ће вам стизати бербу виноградску, а берба ће виноградска стизати сијање, и јешћете хљеб свој до ситости, и живјећете без страха у земљи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Јер ћу дати мир земљи, те ћете спавати а неће бити никога да вас плаши; учинићу, те ће нестати зле звијери из земље, и мач неће пролазити преко ваше земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Него ћете тјерати непријатеље своје, и падаће пред вама од мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Вас ће петорица тјерати стотину, а вас стотина тјераће десет тисућа, и падаће непријатељи ваши пред вама од мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'И обратићу се к вама, и учинићу вам да растете, и умножићу вас, и утврдићу завјет свој с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'И јешћете жито старо, од много година, и изасипаћете старо кад дође ново.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'И намјестићу стан свој међу вама, и душа моја неће мрзити на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'И ходићу међу вама, и бићу вам Бог, и ви ћете бити мој народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ја сам Господ Бог ваш, који вас изведох из земље Мисирске да им не робујете, и поломих палице јарма вашега, и исправих вас да ходите право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Ако ли ме не узаслушате, и не учините све ове заповјести,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'Ако повргнете уредбе моје и души вашој омрзну закони моји да не творите све заповјести моје, и раскинете завјет мој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'И ја ћу вама учинити ово: пустићу на вас страх, суху болест и врућицу, које ће вам очи искварити и душу уцвијелити; и залуду ћете сијати сјеме своје, јер ће га јести непријатељи ваши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'И окренућу лице своје насупрот вама, и сјећи ће вас непријатељи ваши, и који мрзе на вас биће вам господари, и бјежаћете кад вас нико не тјера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Ако ме ни тада не станете слушати, караћу вас још седам пута више за гријехе ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Потрћу понос силе ваше, и учинићу да небо над вама буде као гвожђе а земља ваша као мјед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Снага ће се ваша трошити узалуд, јер земља ваша неће рађати рода својега, и дрвета по земљи неће рађати рода својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Ако ми узидете насупрот и не хтједбудете слушати ме, додаћу вам седам пута више мука према гријесима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Пустићу на вас звијери пољске, које ће вам дјецу изјести, и стоку потрти и вас умалити, и опустјеће путови ваши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Ако се ни од тога не поправите, него ми јоште узидете насупрот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'И ја ћу вама ићи на супрот, и бићу вас још седам пута више за гријехе ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Пустићу на вас мач, који ће осветити мој завјет; а кад се слежете у градове своје, тада ћу пустити помор међу вас, и бићете предани у руке непријатељу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'И кад вам сломим потпору у хљебу, десет ће жена пећи хљеб ваш у једној пећи, и даваће вам хљеб ваш на мјеру, и јешћете а нећете се наситити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Ако ме ни тако не станете слушати, него ми узидете насупрот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'И ја ћу вама с гњевом ићи насупрот, и седам пута већма караћу вас за гријехе ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'И јешћете месо од синова својих, и месо од кћери својих јешћете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Развалићу висине ваше, и оборићу идоле ваше, и метнућу трупове ваше на трупове гадних богова ваших, и мрзиће душа моја на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'И обратићу градове ваше у пустош, и разорићу светиње ваше, и нећу више мирисати мириса вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'И опустићу земљу да ће јој се чудити непријатељи ваши, који ће живјети у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'А вас ћу расијати по народима, и учинићу да вас гоне с голијем мачем; и земља ће ваша бити пуста и градови ваши раскопани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Тада ће земљи бити миле суботе њезине за све вријеме докле буде пуста; и кад будете у земљи својих непријатеља, земља ће почивати, и биће јој миле суботе њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'За све вријеме докле буде пуста почиваће, јер није почивала у ваше суботе, кад сте у њој живјели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'А који вас остану, метнућу страх у срца њихова у земљама непријатеља њиховијех, те ће их гонити лист кад шушне заљуљавши се, и они ће бјежати као испред мача, и падаће а нико их неће тјерати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'И падаће један преко другога као од мача, а нико их неће тјерати; и нећете се моћи држати пред непријатељима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Него ћете изгинути међу народима, и прождријеће вас земља непријатеља ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'А који вас остану, чиљеће за безакоње своје у земљи непријатеља својих, и за безакоње отаца својих чиљеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Али ако признаду безакоње своје и безакоње отаца својих по гријесима, којима ми гријешише и којима ми идоше насупрот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Те и ја њима идох насупрот и одведох их у земљу непријатеља њиховијех; ако се тада понизи срце њихово необрезано, и буде им право што су покарани за безакоње своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Тада ћу се опоменути завјета својега с Јаковом, и завјета својега с Исаком, и завјета својега с Аврамом опоменућу се, и земље ћу се опоменути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Кад се земља опрости њих и буду јој миле суботе њезине кад опусти с њих, и њима буде право што су покарани за безакоње своје, јер судове моје повргоше и души њиховој омрзоше уредбе моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'А зато ни онда кад буду у земљи непријатеља својих нећу их поврћи нити ћу тако омрзнути на њих да их потрем и раскинем завјет свој са њима; јер сам ја Господ Бог њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Него ћу се њих ради опоменути завјета са старима њиховијем, које изведох из земље Мисирске народима на видику да им будем Бог, ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Ово су уредбе и судови и закони, које постави Господ између себе и синова Израиљевих на гори Синајској преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Кажи синовима Израиљевим, и реци им: кад ко завјетује душу своју Господу, ти га уцијени:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'А овако ћеш цијенити: мушко од двадесет година до шездесет цијенићеш педесет сикала сребра, по сиклу светом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Ако буде женско, цијенићеш тридесет сикала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Ако је од пет до двадесет година,цијенићеш мушко двадесет сикала а женско десет сикала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Ако је од једнога мјесеца до пет година, цијенићеш мушко пет сикала сребра, а женско ћеш цијенити три сикла сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Ако ли буде од шездесет година и више, ако је мушко, цијенићеш петнаест сикала, а женско десет сикала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Ако је сиромах да не може платити цијене, онда нека дође к свештенику да га уцијени свештеник, и према ономе што може дати који се завјетовао, нека га свештеник уцијени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Ако би завјетовао живинче од онијех што се приносе Господу, што год да Господу, свето је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Да га не промијени ни даде друго за оно, ни добро за рђаво, ни рђаво за добро; ако ли би како промијенио живинче, онда ће бити свето и оно и друго које је дао за оно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Ако ли би завјетовао живинче нечисто од онијех што се не приносе Господу, нека се доведе живинче пред свештеника;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'И нека га прецијени свештеник, било добро или рђаво; и како га прецијени свештеник, тако да буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Ако би га хтио откупити, нека на цијену твоју дометне још пети дио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Кад би ко завјетовао кућу своју, да је света Господу, нека је прецијени свештеник, била добра или рђава; како је прецијени свештеник, тако да буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Ако би онај који завјетује хтио откупити кућу своју, нека на цијену твоју дометне још пети дио, па нека је његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Ако би ко завјетовао Господу дио њиве своје, цијенићеш је према усјеву: гомер јечма гдје се посије, цијенићеш педесет сикала сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Ако би од опросне године завјетовао њиву своју, нека остане по твојој цијени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Ако ли послије опросне године завјетује њиву своју, тада нека му свештеник прорачуна новце према броју година које остају до опросне године, и нека се одбије до твоје цијене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'И ако би хтио откупити њиву своју онај који је завјетује, нека дометне на цијену твоју још пети дио, и нека буде његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Али ако не откупи њиве, и њива се прода другоме, не може се више откупити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Него ће она њива, кад се опрости опросне године, бити света Господу, као њива завјетована, свештеникова нека буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Ако ли би ко завјетовао Господу њиву купљену, која није достојање његово,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Свештеник нека му прорачуна цијену до године опросне, и нека у онај дан да ту цијену да буде ствар света Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'А године опросне да се врати њива ономе од кога је купљена, чије је достојање она њива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'А свака цијена твоја нека буде на сикле свете, а у сиклу има двадесет новаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Али првина од стоке, које су Господње, нико да не завјетује, било говече или ситна стока, јер је Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Ако ли би било од животиња нечистијех, онда нека откупи по твојој цијени дометнув пети дио озго; ако ли се откупи, нека се прода по твојој цијени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Али ни једна ствар завјетована, што ко завјетује Господу од чега му драго што има, од људи или од стоке или од њиве своје, да се не продаје ни откупљује; свака ствар завјетована светиња је над светињама Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Живинче завјетовано, које човјек завјетује, да се не откупљује, него да се убије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'И сваки десетак земаљски од усјева земаљскога и од воћа, Господњи је, светиња је Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Али ко би хтио откупити што десетка својега, нека на цијену дометне још пети дио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'И десетак од говеда и од ситне стоке, које дође под штап пастирски десето, да је свето Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Да се не бира добро ни рђаво, да се не мијења; ако ли би се како год промијенило, онда нека буде и оно и друго промијењено света ствар, и да се не откупи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Ово су заповијести које заповједи Господ Мојсију за синове Израиљеве на гори Синајској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Још рече Господ Мојсију у пустињи Синајској у шатору од састанка први дан другога мјесеца друге године по изласку њихову из земље Мисирске, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Избројте сав збор синова Израиљевих по породицама њиховијем и по домовима отаца њиховијех и по именима њиховијем, све мушкиње, главу по главу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Од двадесет година и више, све који могу ићи на војску у Израиљу, избројте их по четама њиховијем ти и Арон;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'А с вама нека буде по један човјек од свакога племена, који је поглавар у дому отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'А ово су имена људи који ће бити с вама: од племена Рувимова Елисур син Седијуров;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Од Симеунова Саламило син Сурисадејев;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Од Јудина Насон син Аминадавов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Од Исахарова Натанаило син Согаров;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Од Завулонова Елијав Син Хелонов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Од синова Јосифовијех: од племена Јефремова Елисама син Емијудов; од Манасијина Гамалило син Фадасуров;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Од Венијаминова Авидан син Гадеонијев;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Од Данова Ахијезер син Амисадајев;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Од Асирова Фагаило син Ехранов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Од Гадова Елисаф син Рагуилов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Од Нефталимова Ахиреј син Енанов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'То су који се сазиваху на збор, кнезови у племенима отаца својих, тисућници Израиљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'И узе Мојсије и Арон те људе, који бише именовани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'И сабраше сав збор први дан другога мјесеца, и преписаше их по породицама њиховијем и по домовима отаца њиховијех и по именима њиховијем од двадесет година и више, главу по главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Како бјеше Господ заповједио Мојсију, тако их изброји у пустињи Синајској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'И бјеше синова првенца Израиљева Рувима, рода њихова по породицама њиховијем и по домовима отаца њиховијех, кад се изброји по именима с главе на главу све мушкиње од двадесет година и више, што могаше ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Бјеше их избројени од племена Рувимова четрдесет и шест тисућа и пет стотина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Синова Симеуновијех, рода њихова по породицама њиховијем и по домовима отаца њиховијех, кад се изброји по именима с главе на главу све мушкиње од двадесет година и више, што могаше ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Бјеше их избројенијех од племена Симеунова педесет и девет тисућа и три стотине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Синова Гадовијех, рода њихова по породицама њиховијем и по домовима отаца њиховијех, кад се избројише по именима од двадесет година и више сви што могаху ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Бјеше их избројенијех од племена Гадова четрдесет и пет тисућа, шест стотина и педесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Синова Јудинијех, рода њихова по породицама њиховијем и по домовима отаца њиховијех, кад се избројише по именима од двадесет година и више сви што могаху ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Бјеше их избројенијех од племена Јудина седамдесет и четири тисуће и шест стотина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Синова Исахаровијех, рода њихова по породицама њиховијем и по домовима отаца њиховијех, кад се избројише по именима од двадесет година и више сви што могаху ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Бјеше их избројенијех од племена Исахарова педесет и четири тисуће и четири стотине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Синова Завулоновијех, рода њихова по породицама њиховијем и по домовима отаца њиховијех, кад се избројише по именима од двадесет година и више сви што могаху ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Бјеше их избројенијех од племена Завулонова педесет и седам тисућа и четири стотине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Од синова Јосифовијех: синова Јефремовијех, рода њихова по породицама њиховијем и по домовима отаца њиховијех, кад се избројише по именима од двадесет година и више сви што могаху ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Бјеше их избројенијех од племена Јефремова четрдесет тисућа и пет стотина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Синова Манасијиних, рода њихова по породицама њиховијем и по домовима отаца њиховијех, кад се избројише по именима од двадесет година и више сви што могаху ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Бјеше их избројенијех од племена Манасијина тридесет и двије тисуће и двјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Синова Венијаминовијех, рода њихова по породицама њиховијем и по домовима отаца њиховијех, кад се избројише по именима од двадесет година и више сви што могаху ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Бјеше их избројенијех од племена Венијаминова тридесет и пет тисућа и четири стотине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Синова Дановијех, рода њихова по породицама њиховијем и по домовима отаца њиховијех, кад се избројише по именима од двадесет година и више сви што могаху ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Бјеше их избројенијех од племена Данова шездесет двије тисуће и седам стотина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Синова Асировијех, рода њихова по породицама њиховијем и по домовима отаца њиховијех, кад се избројише по именима од двадесет година и више сви што могаху ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Бјеше их избројенијех од племена Асирова четрдесет и једна тисућа и пет стотина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Синова Нефталимовијех, рода њихова по породицама њиховијем и по домовима отаца њиховијех, кад се избројише по именима од двадесет година и више сви што могаху ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Бјеше их избројенијех од племена Нефталимова педесет и три тисуће и четири стотине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Ово су они које Мојсије и Арон избројише с кнезовима Израиљским, с дванаест људи, који бијаху по један за сваки дом отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'И свега бјеше синова Израиљевијех избројенијех по домовима отаца својих од двадесет година и више, свијех што могаху ићи на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Бјеше их избројенијех шест стотина и три тисуће и пет стотина и педесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Али Левити по племену отаца својих не бише бројени међу њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Јер Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Племена Левијева немој бројати, нити броја њихова саставити са синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Него постави Левите над шатором од свједочанства и над свијем посуђем у њему и над свијем што припада њему; они нека носе шатор и све посуђе његово, нека служе у њему, и стају око шатора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'И кад се шатор крене, нека га сложе Левити; и кад шатор стане, онда нека га разапну Левити. А ко би други приступио, да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'И синови Израиљеви нека стају сваки у свом околу и сваки код своје заставе по четама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'А Левити нека стају око шатора од свједочанства, да не дође гњев на збор синова Израиљевијех; и нека Левити раде што треба око шатора од свједочанства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'И учинише синови Израиљеви како Господ заповједи, све тако учинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Потом рече Господ Мојсију и Арону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Синови Израиљеви нека стају у око сваки код своје заставе са знаком дома отаца својих, према шатору од састанка унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'С истока нека стаје у око застава војске Јудине по четама својим с војводом синова Јудинијех Насоном сином Аминадавовим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'А у војсци његовој седамдесет и четири тисуће и шест стотина избројенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'А до њега нека стаје у око племе Исахарово с војводом синова Исахаровијех Натанаилом сином Согаровијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'А у војсци његовој педесет и четири тисуће и четири стотине избројенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Па онда племе Завулоново с војводом синова Завулоновијех Елијавом сином Хелоновијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'А у војсци његовој педесет и седам тисућа и четири стотине избројенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Свега избројенијех у војсци Јудиној сто и осамдесет и шест тисућа и четири стотине по четама њиховијем. Они нека иду напријед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'А застава војске Рувимове по четама својим нека буде с југа, с војводом синова Рувимовијех Елисуром сином Седијуровијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'А у војсци његовој четрдесет и шест тисућа и пет стотина избројенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'А до њега нека стаје у око племе Симеуново с војводом синова Симеуновијех Саламилом сином Сурисадајевим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'А у војсци његовој педесет и девет тисућа и три стотине избројенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Па онда племе Гадово с војводом синова Гадовијех Елисафом сином Рагуиловим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'А у војсци његовој четрдесет и пет тисућа и шест стотина и педесет избројенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'А свега избројенијех у војсци Рувимовој сто и педесет и једна тисућа и четири стотине и педесет по четама њиховијем. И они нека иду други.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Потом нека иде шатор од састанка с војском синова Левијевих усред остале војске; како у око стају тако нека и иду, сваки својим редом под својом заставом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Застава војске Јефремове по четама својим нека буде са запада, с војводом синова Јефремовијех Елисамом сином Емијудовим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'А у војсци његовој четрдесет тисућа и пет стотина избројенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'А до њега племе Манасијино с војводом синова Манасијиних Гамалилом, сином Фадасуровим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'А у његовој војсци тридесет и двије тисуће и двјеста избројенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Па онда племе Венијаминово с војводом синова Венијаминовијех Авиданом сином Гадеонијевим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'А у војсци његовој тридесет и пет тисућа и четири стотине избројених.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'А свега избројенијех у војсци Јефремовој сто и осам тисућа и сто по четама њиховијем. И они нека иду трећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Застава војске Данове по четама својим нека буде са сјевера с војводом синова Дановијех Ахијезером сином Амисадајевим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'А у војсци његовој шездесет и двије тисуће и седам стотина избројених.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'А до њега нека стаје у око племе Асирово с војводом синова Асировијех Фагаилом сином Ехрановијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'А у војсци његовој четрдесет и једна тисућа и пет стотина избројенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'За њима племе Нефталимово с војводом синова Нефталимовијех Ахирејем сином Енановијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'А у његовој војсци педесет и три тисуће и четири стотине избројенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'А свега избројенијех у војсци Дановој сто и педесет и седам тисућа и шест стотина. И они нека иду најпослије уза заставе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'То су синови Израиљеви који бише избројени по домовима отаца својих. Свега избројенијех у цијелој војсци по четама њиховијем шест стотина и три тисуће и пет стотина и педесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Али Левити не бише бројени међу синове Израиљеве, као што Господ бјеше заповједио Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'И учинише синови Израиљеви све; како заповједи Господ Мојсију, тако стајаху у око, и тако иђаху сваки по породици својој и по дому отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'А ово је племе Ароново и Мојсијево, кад Господ говори с Мојсијем на гори Синајској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'И ово су имена синова Ароновијех: првенац Надав, па Авијуд и Елеазар и Итамар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'То су имена синова Ароновијех, свештеника, који бише помазани и посвећени да врше службу свештеничку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Али погибе Надав и Авијуд пред Господом, кад принесоше огањ туђ пред Господом у пустињи Синајској; и не имаше дјеце; зато Елеазар и Итамар отправљаху службу свештеничку за живота Арона оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'А Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Кажи нека приступи племе Левијево, и постави га пред Ароном свештеником да му служе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'И да раде за њ и за сав збор пред шатором од састанка служећи шатору,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'И да чувају све посуђе у шатору од састанка, и да страже за синове Израиљеве служећи шатору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Па ћеш дати Левите Арону и синовима његовијем; они су даровани њему између синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'А Арона и синове његове постави да врше свештеничку службу своју; ако ли би ко други приступио, да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Ево узех Левите између синова Израиљевијех за све првенце што отворају материцу међу синовима Израиљевијем; зато ће моји бити Левити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Јер је мој сваки првенац; од онога дана када побих све првенце у земљи Мисирској, посветих себи свакога првенца у Израиљу од човјека до живинчета; моји ће бити; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Још рече Господ Мојсију у пустињи Синајској говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Изброј синове Левијеве по домовима отаца њиховијех, по породицама њиховијем, све мушкиње од мјесеца дана и више изброј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'И Мојсије их изброји по заповијести Господњој, како му би заповјеђено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'И бјеху синови Левијеви по имену ови: Гирсон и Кат и Мерарије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'А ово су имена синова Гирсоновијех по породицама њиховијем: Ловеније и Семеј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'А синови Катови по породицама својим: Амрам и Исар, Хеврон и Озило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'А синови Мераријеви по породицама својим: Малије и Мусије. То су породице Левитске по домовима отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Од Гирсона породица Ловенијева и породица Семејева. То су породице Гирсонове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'А избројених међу њима, кад се изброји све мушкиње од мјесеца дана и више, бјеше их избројенијех свега седам тисућа и пет стотина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Породице Гирсонове стајаху у око иза шатора са запада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'А старјешина од дома отачкога у породицама Гирсоновим бјеше Елисаф син Даилов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'А синови Гирсонови чуваху у шатору од састанка шатор и наслон, покривач његов и завјес на вратима шатора од састанка,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'И завјесе од тријема и завјес на вратима од тријема што је око шатора и око олтара, и ужа његова за сваку потребу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'А од Ката бјеше породица Амрамова и породица Исарова и породица Хевронова и породица Озилова. То су породице Катове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Свега мушкиња од мјесеца дана и више бјеше на број осам тисућа и шест стотина, који служаху око светиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Породице синова Катовијех стајаху у око поред шатора с југа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'А старјешина од дома отачкога у породицама Катовијем бјеше Елисафан син Озилов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'А они чуваху ковчег и сто и свијетњак и олтар и посуђе у светињи којим служе, и завјес, и све што припада к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'А старјешина над старјешинама Левитским бјеше Елеазар син Арона свештеника, постављен над онима који чувају светињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'А од Мерарија бјеше породица Малијева и породица Мусијева. То су породице Мераријеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'И бјеше их избројенијех, кад се изброји све мушкиње од мјесеца дана и више, шест тисућа и двјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'А старјешина од дома отачкога у породицама Мераријевим бјеше Сурило син Авихејев; они стајаху у око поред шатора са сјевера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'И синови Мераријеви чуваху даске од шатора и пријеворнице његове и ступце његове и стопице његове и све справе његове и све што к њему припада,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'И ступце од тријема унаоколо и стопице њихове и коље и ужа њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'А пред шатором од састанка с истока стајаху у око Мојсије и Арон и синови његови чувајући светињу за синове Израиљеве; а да ко други приступи, погинуо би.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'А свега Левита кад их изброји Мојсије и Арон по заповијести Господњој по породицама њиховијем, свега мушкиња од мјесец дана и више, бјеше двадесет и двије тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'И Господ рече Мојсију: изброј све првенце мушке међу синовима Израиљевим од мјесеца дана и више, и сабери број имена њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'И узми Левите за мене (ја сам Господ) мјесто свијех првенаца међу синовима Израиљевим, и стоку Левитску мјесто свијех првенаца од стоке синова Израиљевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'И изброји Мојсије како му заповједи Господ, све првенце међу синовима Израиљевијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'И свега првенаца мушких, кад се избројише по именима од једнога мјесеца и више, бјеше избројенијех двадесет и двије тисуће и двјеста и седамдесет и три.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'И Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Узми Левите мјесто свијех првенаца међу синовима Израиљевим и стоку Левитску мјесто стоке њихове, да буду моји Левити; ја сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'А да се откупе они двјеста и седамдесет и три, што има првенаца међу синовима Израиљевијем више него Левита,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Узми по пет сикала од главе; узми по светом сиклу (а у тај сикал иде двадесет гера).');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'И подај те новце Арону и синовима његовијем, откуп за оне који прелазе број њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'И узе Мојсије откуп од онијех који осташе преко онијех који бише промијењени за Левите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'И узе новце од првенаца синова Израиљевијех, тисућу и триста и шездесет и пет сикала, по светом сиклу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'И даде Мојсије тај откуп Арону и синовима његовијем по заповијести Господњој, као што заповједи Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Још рече Господ Мојсију и Арону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Изброј синове Катове између синова Левијевих по породицама њиховијем и по домовима отаца њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Од тридесет година и више до педесет година све који су за посао да могу радити послове у шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'А ово ће бити посао синовима Катовијем у шатору од састанка у светињи над светињама:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Кад полази војска, доћи ће Арон са синовима својим, и скинуће завјес с врата, и покриће њим ковчег од свједочанства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Па ће по њему простријети покривач од кожа јазавчјих, и озго ће простријети простирач од саме порфире, и провући ће му полуге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'И по столу за хљебове постављене нека простру простирач од порфире, и нека метну на њ здјеле и чаше и виједра и кутлиће, и хљеб свагда нека је на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Па врх тога нека простру простирач од црвца, и нека покрију покривачем од кожа јазавчјих, и нека му провуку полуге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'И нека узму простирач од порфире и покрију свијетњак и жишке његове и усекаче његове лопатице његове и све судове за уље, којима служе око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'И нека га са свијем справама његовијем завију у покривач од кожа јазавчјих, и метну га на полуге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'И по златном олтару нека простру простирач од порфире и покрију га покривачем од кожа јазавчјих, и провуку му полуге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'И нек узму све справе за службу, којима служе у светињи, и нека их метну у простирач од порфире и завију у покривач од кожа јазавчјих, и метну на полуге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'И нека омету пепео с олтара и по олтару простру простирач од скерлета,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'И нека метну на њ све справе његове, којима служе на њему, машице, виљушке, лопатице и котлиће и све справе за олтар, и нека га покрију покривачем од кожа јазавчјих, па му провуку полуге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'И кад то сврши Арон и синови његови и завију светињу и све справе за светињу, да пође војска, онда нека дођу синови Катови да носе, али нека се не дотакну ниједне ствари свете, да не погину. То је посао синова Катовијех у шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'А Елеазар син Арона свештеника нека се стара за уље за видјело, и за кад мирисни, и за жртву свагдашњу, и за уље помазања, нека пази на сав шатор и на све што је у њему, на светињу и на посуђе њезино.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'И рече Господ Мојсију и Арону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Немојте да се истријеби кољено породица Катовијех између Левита;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Него им учините ово да би остали живи и не би помрли кад приступају к светињи над светињама: Арон и синови његови нека дођу и одреде свакому шта ће који радити и шта ће носити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'А они нека не долазе да гледају кад се завијају свете ствари, да не помру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Опет рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Изброј и синове Гирсонове по домовима отаца њиховијех и по породицама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Од тридесет година и више до педесет година изброј их све који су за службу да могу служити у шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Ово је посао породицама Гирсоновијем што ће радити и носити:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Нека носе завјесе од наслона и шатор од састанка, покривач његов и покривач од кожа јазавчјих што је озго на њему, и завјес на уласку у шатор од састанка,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'И завјесе од тријема и завјес на вратима од тријема што је око шатора и око олтара, и ужа њихова и све посуђе за службу њихову и што год треба око тога радити нека раде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'По наредби Ароновој и синова његовијех нека бива сва служба синова Гирсоновијех за све што ће носити и што ће радити, и оставите им нека чувају све што су дужни носити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'То је служба породица синова Гирсоновијех у шатору од састанка; а Итамар син Арона свештеника нека управља њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Изброј и синове Мераријеве по породицама њиховијем и по домовима отаца њиховијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Од тридесет година и више до педесет година изброј их све који су за службу да могу служити у шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'А ово им је дужност носити осим све службе њихове у шатору од састанка: даске од шатора и пријеворнице његове и ступце његове и стопице његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'И ступце од тријема унаоколо, и стопице њихове и коље њихово, и ужа њихова, и све справе њихове, и што год треба за те ствари; а поименце избројте све справе што ће они носити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'То је служба породица синова Мераријевих што су дужни радити у шатору од састанка под руком Итамара сина Арона свештеника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'И изброји Мојсије и Арон с кнезовима народним синове Катове по породицама њиховијем и по домовима отаца њиховијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Од тридесет година и више до педесет година све који су за службу да могу служити у шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'И бјеше их избројенијех по породицама њиховијем двије тисуће и седам стотина и педесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'То су избројени из породица Катовијех што бјеху за службу у шатору од састанка, које изброји Мојсије и Арон, као што заповједи Господ преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'А синова Гирсоновијех по породицама њиховијем и по домовима отаца њиховијех и по домовима отаца њиховијех бјеше избројенијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Од тридесет година и више до педесет година, свијех што бијаху за службу да служе у шатору од састанка,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Бјеше их избројенијех по породицама њиховијем и по домовима отаца њиховијех двије тисуће и шест стотина и тридесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'То су избројени из породица синова Гирсоновијех, што бјеху за службу у шатору од састанка, које изброји Мојсије и Арон по заповијести Господњој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'А из породица синова Мераријевих по породицама њиховијем и по домовима отаца њиховијех бјеше избројенијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Од тридесет година и више до педесет година, свијех што бијаху за службу да служе у шатору од састанка,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Бјеше их избројенијех по породицама њиховијем три тисуће и двјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'То су избројени из породица синова Мераријевих, које изброји Мојсије и Арон као што заповједи Господ преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'А свега бјеше избројенијех Левита, које изброји Мојсије и Арон с кнезовима Израиљевим по породицама њиховијем и по домовима отаца њиховијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'Од тридесет година и више до педесет година, што бјеху за службу да служе и да носе у шатору од састанка,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Свега их бјеше избројенијех осам тисућа и пет стотина и осамдесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Како Господ заповједи преко Мојсија, бише избројени, сваки за оно што треба да ради и да носи; и избројени бише они које је Господ заповједио Мојсију да се изброје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Заповједи синовима Израиљевијем нека истјерају из окола све губаве и све којима тече сјеме и све који су се оскврнили о мртваца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Био човјек или жена, истјерајте, иза окола истјерајте их, да не скврне окола онима међу којима наставам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'И учинише тако синови Израиљеви, и истјераше их из окола; како Господ каза Мојсију, тако учинише синови Израиљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Реци синовима Израиљевим: човјек или жена кад учини какав гријех људски, те згријеши Господу, и буде она душа крива,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Тада нека признаду гријех који су учинили, и ко је крив нека врати цијело чим је крив и нека дометне озго пети дио и да оному коме је скривио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'И ако онај нема никога кому би припала накнада за штету, нека се да Господу и нека буде свештенику осим овна за очишћење којим ће га очистити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Тако и сваки принос између свијех ствари које посвећују синови Израиљеви и доносе свештенику, његов нека буде;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'И што год ко посвети, нека је његово, и што год ко да свештенику, нека је његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Кажи синовима Израиљевим и реци им: чија би жена застранила те би му згријешила,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'И други би је облежао, а муж њезин не би знао, него би она затајила да се оскврнила, и не би било свједока на њу, нити би се затекла,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'А њему би дошла сумња љубавна, те би из љубави сумњао на своју жену, а она би била оскврњена; или би му дошла сумња љубавна те би из љубави сумњао на своју жену, а она не би била оскврњена;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Онда нека муж доведе жену своју к свештенику, и нека донесе за њу принос њезин, десети дио ефе брашна јечменога, али нека га не полије уљем и нека не метне на њ када, јер је принос за сумњу љубавну, дар за спомен да се спомене гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'И нека је свештеник приведе и постави пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'И нека узме свештеник свете воде у суд земљани; и праха с пода у шатору нека узме и успе у воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'И поставивши свештеник жену пред Господом нека јој открије главу и метне јој на руке дар за спомен који је дар за сумњу љубавну; а свештеник нека држи у руци својој горку воду, која носи проклетство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'И нека свештеник закуне жену, и рече јој: ако није нико спавао с тобом, и ако нијеси застранила од мужа својега на нечистоту, нека ти не буде ништа од ове воде горке, која носи проклетство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Ако ли си застранила од мужа својега и оскврнила се, и когод други осим мужа твојега спавао с тобом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'Тада свештеник заклињући жену нека је прокуне и рече жени: да те Господ постави за уклин и за клетву у народу твом учинивши да ти бедро спадне а трбух отече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'И нека ти ова вода проклета уђе у цријева да ти отече трбух и да ти бедро спадне. А жена нека рече: амин, амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Тада нека напише свештеник те клетве у књигу, и нека их спере водом горком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'И нека да жени да се напије горке воде проклете да уђе у њу вода проклета и буде горка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'И нека узме свештеник из руку жени дар за сумњу љубавну, и обрне дар пред Господом и принесе га на олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'И нека узме свештеник у шаку од дара њезина спомен, и запали на олтару, па онда нека да жени воду да попије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'А кад јој да воду да пије, ако се буде оскврнила и учинила невјеру мужу својему, онда ће ући вода проклета у њу и постаће горка, и трбух ће јој отећи и спасти бедро, и она ће жена постати уклин у народу својем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Ако ли се не буде оскврнила жена, него буде чиста, неће јој бити ништа и имаће дјеце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Ово је закон за сумњу љубавну, кад жена застрани од мужа својега и оскврни се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Или кад коме дође сумња љубавна те посумња из љубави на жену своју и постави је пред Господом и сврши јој свештеник све по овом закону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'И муж да је прост од гријеха, али жена да носи своје безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Реци синовима Израиљевијем, и кажи им: кад човјек или жена учини завјет назирејски, да буде назиреј Господу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Нека се уздржава од вина и силовита пића, и нека не пије оцта винскога ни оцта од силовита пића нити каквога пића од грожђа и нека не једе грожђа ни новога ни сухога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Докле год траје његово назирејство нека не једе ништа од винове лозе, ни зрна ни љуске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Докле траје његово назирејство, нека му бритва не пријеђе преко главе; докле се не наврше дани за које се учинио назиреј Господу, нека буде свет и нека оставља косу на глави својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Докле трају дани за које се учинио назиреј Господу, нека не приступа к мртвацу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Ни за оцем својим ни за матером својом ни за братом својим ни за сестром својом, нека се за њима не скврни кад умру; јер је назирејство Бога његова на глави његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Докле год траје назирејство његово, свет је Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Ако ли би ко умро до њега на пречац, те би оскврнио назирејство главе његове, нека обрије главу своју у дан чишћења својега, седми дан нека је обрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'А осми дан нека донесе двије грлице или два голубића свештенику на врата шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'И свештеник нека зготови од једнога жртву за гријех а од другога жртву паљеницу, и нека га очисти од онога што је згријешио код мртваца; тако ће посветити главу његову у тај дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'И нека одијели Господу дане назирејства својега, и донесе јагње од године за кривицу; а пређашњи дани пропадају, јер му се оскврнило назирејство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'А ово је закон за назиреје: кад се наврше дани назирејству његову, нека дође на врата шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'И нека донесе за жртву Господу јагње мушко од године здраво за жртву паљеницу, и јагње женско од године здраво за гријех, и овна здрава за жртву захвалну,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'И котарицу хљебова пријеснијех, колача од бијелога брашна замијешених с уљем, и погача пријеснијех намазанијех уљем, с даром њиховијем и с наљевом њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'А то ће свештеник принијети пред Господом и учинити жртву за гријех његов и жртву његову паљеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'А овна ће принијети на жртву захвалну Господу с котарицом пријеснијех хљебова; принијеће свештеник и дар његов и наљев његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Тада назиреј нека обрије главу својега назирејства на вратима шатора од састанка; и узев косу назирејства својега нека је метне у огањ који је под жртвом захвалном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'И свештеник нека узме плеће кухано од овна и један колач пријесан из котарице и једну погачу пријесну, и нека метне на руке назиреју, пошто обрије назирејство своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'И свештеник нека обрће те ствари на жртву обртану пред Господом; то је светиња, која припада свештенику осим груди обртаних и плећа подигнутога; а послије тога назиреј може пити вина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'То је закон за назиреја који се завјетује, и то је принос његов Господу за назирејство његово, осим онога што би више могао учинити; какав му буде завјет којим се завјетује, тако нека учини осим закона својега назирејства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Реци Арону и синовима његовијем и кажи: овако благосиљајте синове Израиљеве говорећи им:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Да те благослови Господ и да те чува!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Да те обасја Господ лицем својим и буде ти милостив!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Да Господ обрати лице своје к теби и даде ти мир!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'И нека призивљу име моје на синове Израиљеве, и ја ћу их благословити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'И онај дан кад Мојсије сврши и подиже шатор, и кад га помаза и освети са свијем посуђем његовијем и олтар са свијем посуђем његовијем, кад помаза и освети,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Донесоше кнезови Израиљеви, старјешине у домовима отаца својих, кнезови над племенима и поглавари од онијех који бише избројени,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Донесоше прилог свој пред Господа, шестора кола покривена и дванаест волова, једна кола два кнеза и по једнога вола сваки, и донесоше пред шатор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'А Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Узми то од њих да буде за службу у шатору од састанка, и подај Левитима, свакому према служби његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'И узе Мојсије кола и волове, и даде их Левитима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Двоја кола и четири вола даде синовима Гирсоновијем према служби њиховој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'А остала четвора кола и осам волова даде синовима Мераријевим према служби њиховој под управом Итамара сина Арона свештеника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'А синовима Катовијем не даде ништа, јер им посао бијаше служити светињи, и ношаху на раменима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'И донесоше кнезови да се посвети олтар кад би помазан, донесоше кнезови прилоге своје пред олтар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'А Господ рече Мојсију: један кнез у један дан а други кнез у други дан нека доносе своје прилоге да се посвети олтар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'И први дан донесе прилог свој Насон син Аминадавов од племена Јудина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'А прилог његов бјеше једна здјела сребрна од сто и тридесет сикала, једна чаша сребрна од седамдесет сикала, по сиклу светом; а обоје пуно брашна бијелога помијешана с уљем за дар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Једна кадионица златна од десет сикала, пуна када;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Једно теле, један ован, једно јагње од године за жртву паљеницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Један јарац за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'А за жртву захвалну два вола, пет овнова, пет јараца, пет јагањаца од године. То би прилог Насона сина Аминадавова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Други дан донесе Натанило син Согаров, кнез племена Исахарова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Донесе прилог свој: једну здјелу сребрну од сто и тридесет сикала, једну чашу сребрну од седамдесет сикала по сиклу светом, обоје пуно бијелога брашна помијешана с уљем за дар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Једну кадионица златну од десет сикала, пуна када;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Једно теле, једнога ован, једно јагње од године за жртву паљеницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Једнога јарца за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'А за жртву захвалну два вола, пет овнова, пет јараца, пет јагањаца од године. То би прилог Натанаила сина Согарова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Трећи дан донесе кнез синова Завулоновијех, Елијав син Хелонов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Његов прилог бјеше: једна здјела сребрна од сто и тридесет сикала, једна чаша сребрна од седамдесет сикала по сиклу светом, а обоје пуно бијелога брашна помијешана с уљем за дар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'Једна кадионица златна од десет сикала пуна када;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'Једно теле, један ован, једно јагње од године за жртву паљеницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'Један јарац за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'А за жртву захвалну два вола, пет овнова, пет јараца, пет јагањаца од године. То би прилог Елијава сина Хелонова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Четврти дан донесе кнез синова Рувимовијех Елисур син Седијуров;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Прилог његов бјеше: једна здјела сребрна од сто и тридесет сикала, једна чаша сребрна од седамдесет сикала, по сиклу светом, а обоје пуно бијелога брашна помијешана с уљем за дар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'Једна кадионица златна од десет сикала пуна када;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'Једно теле, један ован, једно јагње од године за жртву паљеницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'Један јарац за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'А за жртву захвалну два вола, пет овнова, пет јараца, пет јагањаца од године. То би прилог Елисура сина Седијурова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Пети дан донесе кнез синова Симеуновијех Саламило син Сурисадајев;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Прилог његов бјеше: једна здјела сребрна од сто и тридесет сикала, једна чаша сребрна од седамдесет сикала по сиклу светом, обоје пуно бијелога брашна помијешана с уљем за дар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'Једна кадионица златна од десет сикала пуна када;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'Једно теле, један ован, једно јагње од године за жртву паљеницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'Један јарац за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'А за жртву захвалну два вола, пет овнова, пет јараца, пет јагањаца од године. То би прилог Саламила сина Сурисадајева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Шести дан донесе кнез синова Гадовијех Елисаф син Рагуилов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Прилог његов бјеше: једна здјела сребрна од сто и тридесет сикала, једна чаша сребрна од седамдесет сикала, по сиклу светом, а обоје пуно бијелога брашна помијешана с уљем за дар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, 'Једна кадионица златна од десет сикала пуна када;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, 'Једно теле, један ован, једно јагње од године за жртву паљеницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, 'Један јарац за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, 'А за жртву захвалну два вола, пет овнова, пет јараца, пет јагањаца од године. То би прилог Елисафа сина Рагуилова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Седми дан донесе кнез синова Јефремовијех Елисама син Емијудов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Прилог његов бјеше: једна здјела сребрна од сто и тридесет сикала, једна чаша сребрна од седамдесет сикала, по сиклу светом, обоје пуно бијелога брашна помијешана с уљем за дар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'Једна кадионица златна од десет сикала пуна када;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'Једно теле, један ован, једно јагње од године за жртву паљеницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, 'Један јарац за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'А за жртву захвалну два вола, пет овнова, пет јараца, пет јагањаца од године. То би прилог Елисаме сина Емијудова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Осми дан донесе кнез синова Манасијиних Гамалило син Фадасуров;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Прилог његов бјеше: једна здјела сребрна од сто и тридесет сикала, једна чаша сребрна од седамдесет сикала, по сиклу светом, обоје пуно бијелога брашна помијешана с уљем за дар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'Једна кадионица златна од десет сикала пуна када;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'Једно теле, један ован, једно јагње од године за жртву паљеницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'Један јарац за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'А за жртву захвалну два вола, пет овнова, пет јараца, пет јагањаца од године. То би прилог Гамалила сина Фадасурова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Девети дан донесе кнез синова Венијаминових Авидан син Гадеонијев;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Прилог његов бјеше: једна здјела сребрна од сто и тридесет сикала, једна чаша сребрна од седамдесет сикала, по сиклу светом, обоје пуно бијелога брашна помијешана с уљем за дар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'Једна кадионица златна од десет сикала пуна када;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'Једно теле, један ован, једно јагње од године за жртву паљеницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'Један јарац за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'А за жртву захвалну два вола, пет овнова, пет јараца, пет јагањаца од године. То би прилог Авидана сина Гадеонијева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Десети дан донесе кнез синова Дановијех Ахијезер син Амисадајев;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Прилог његов бјеше: једна здјела сребрна од сто и тридесет сикала, једна чаша сребрна од седамдесет сикала, по сиклу светом, обоје пуно бијелога брашна помијешана с уљем за дар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'Једна кадионица златна од десет сикала пуна када;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'Једно теле, један ован, једно јагње од године за жртву паљеницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'Један јарац за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'А за жртву захвалну два вола, пет овнова, пет јараца, пет јагањаца од године. То би прилог Ахијезера сина Амисадајева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Једанаести дан донесе кнез синова Асировијех Фагаило син Ехранов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Прилог његов бјеше: једна здјела сребрна од сто и тридесет сикала, једна чаша сребрна од седамдесет сикала, по сиклу светом, обоје пуно бијелога брашна помијешана с уљем за дар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'Једна кадионица златна од десет сикала пуна када;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'Једно теле, један ован, једно јагње од године за жртву паљеницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'Један јарац за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'А за жртву захвалну два вола, пет овнова, пет јараца, пет јагањаца од године. То би прилог Фагаила сина Ехранова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Дванаести дан донесе кнез синова Нефталимовијех Ахиреј син Енанов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Прилог његов бјеше: једна здјела сребрна од сто и тридесет сикала, једна чаша сребрна од седамдесет сикала, по сиклу светом, обоје пуно бијелога брашна помијешана с уљем за дар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'Једна кадионица златна од десет сикала пуна када;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'Једно теле, један ован, једно јагње од године за жртву паљеницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'Један јарац за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'А за жртву захвалну два вола, пет овнова, пет јараца, пет јагањаца од године. То би прилог Ахиреја сина Енанова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'То је прилог од кнезова Израиљевијех да се посвети олтар пошто би помазан: дванаест здјела сребрнијех, дванаест чаша сребрнијех, дванаест кадионица златнијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Свака здјела сребрна од сто и тридесет сикала, и свака чаша од седамдесет сикала; свега сребра у тијем судовима двије тисуће и четири стотине сикала, по сиклу светом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Дванаест кадионица златнијех пунијех када, свака кадионица од десет сикала, по сиклу светом; свега злата у кадионицама сто и двадесет сикала;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Свега стоке за жртву паљеницу дванаест телаца, дванаест овнова, дванаест јагањаца од године с даром својим, и јараца дванаест за гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'А свега стоке за жртву захвалну двадесет и четири вола, шездесет овнова, шездесет јараца, шездесет јагањаца од године. То је прилог да се посвети олтар, пошто би помазан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'И кад Мојсије улажаше у шатор од састанка да говори пред Богом, тада чујаше глас гдје му говори са заклопца што бјеше на ковчегу од свједочанства између два херувима; и говораше му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Кажи Арону и реци му: кад запалиш жишке, седам жижака нека свијетли спријед на свијетњаку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'И учини Арон тако, и запали жишке да свијетле спријед на свијетњаку, као што Господ заповједи Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'А свијетњак бјеше скован од злата, и ступац му и цвијеће сковано; по прилици коју показа Господ Мојсију тако бјеше начинио свијетњак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Узми Левите између синова Израиљевијех, и очисти их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'А учини им ово да их очистиш: покропи их водом очишћења, а они нека обрију све тијело своје и оперу хаљине своје, и очистиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Потом нека узму теле с даром уз њега, бијелим брашном помијешаним с уљем; и друго теле узми за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Па доведи Левите пред шатор од састанка, и сазови сав збор синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'И доведи Левите пред Господа, и нека метну синови Израиљеви руке своје на Левите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'И Арон нека принесе Левите Господу за принос од синова Израиљевијех да врше службу Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'А Левити нека метну руке своје на главе теоцима, па принеси једно теле за гријех а друго на жртву паљеницу Господу да се очисте Левити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'И постави Левите пред Ароном и синовима његовијем, и принеси их за принос Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'И одвој Левите између синова Израиљевијех да буду моји Левити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'А послије нека дођу Левити да служе у шатору од састанка, кад их очистиш и принесеш за принос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Јер су мени дани између синова Израиљевијех; за све што отвора материцу, за све првенце између синова Израиљевијех узех њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Јер је мој сваки првенац међу синовима Израиљевијем и од људи и од стоке; онај дан кад побих све првенце у земљи Мисирској, посветио сам их себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'А Левите узех за све првенце синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'И дадох Левите на дар Арону и синовима његовијем између синова Израиљевијех, да служе мјесто синова Израиљевијех у шатору од састанка, и да буду откуп за синове Израиљеве, да не би долазио помор на синове Израиљеве, кад би приступали к светињи синови Израиљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'И учини Мојсије и Арон и сав збор синова Израиљевијех Левитима све што заповједи Господ Мојсију за Левите, тако им учинише синови Израиљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'И очистише се Левити, и опраше хаљине своје, и принесе их Арон за принос пред Господом, и очисти их Арон да би били чисти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'И онда тек приступише Левити да врше службу своју у шатору од састанка пред Ароном и пред синовима његовијем; као што заповједи Господ Мојсију за Левите, тако им учинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'И опет рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'И ово је за Левите: од двадесет и пет година и више нека ступају у службу да служе у шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'А кад коме буде педесет година, нека излази из те службе и више нека не служи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Али нека служи браћи својој у шатору од састанка радећи што треба радити, а сам нека не врши службе. Тако учини Левитима за послове њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Још рече Господ Мојсију у пустињи Синајској друге године по изласку њихову из земље Мисирске првога мјесеца, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Нека славе синови Израиљеви пасху у одређено вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Четрнаестога дана овога мјесеца увече славите је у одређено вријеме, по свијем законима и по свијем уредбама њезинијем славите је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'И рече Мојсије синовима Израиљевијем да славе пасху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'И славише пасху првога мјесеца четрнаестога дана увече у пустињи Синајској; како бјеше Господ заповједио Мојсију, све онако учинише синови Израиљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'А бијаху неки који се оскврнише о мртваца те не могаху славити пасхе онај дан; и дођоше исти дан пред Мојсија и пред Арона;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'И рекоше му људи они: ми смо нечисти од мртваца; зашто да нам није слободно принијети жртву Господу у вријеме заједно са синовима Израиљевијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'А Мојсије им рече: станите да чујем шта ће заповједити Господ за вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'А Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Кажи синовима Израиљевијем и реци: ко би био нечист од мртваца или би био на даљном путу између вас или између вашега натражја, нека слави пасху Господу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Другога мјесеца четрнаестога дана увече нека је славе с пријеснијем хљебом и с горким зељем нека је једу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Нека не остављају од ње ништа до јутра, и кости да јој не преломе, по свему закону за пасху нека је славе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'А ко је чист и није на путу, па би пропустио славити пасху, да се истријеби душа она из народа својега, јер не принесе Господу жртве на вријеме, гријех свој нека носи онај човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'И ако би међу вама живио странац и славио би пасху Господу, по закону и уредби за пасху нека је слави; а закон да вам је једнак и странцу и оному ко се родио у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'А у који дан би подигнут шатор, покри облак шатор над наслоном од свједочанства; а увече бјеше над шатором као огањ до јутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Тако бијаше једнако: облак га заклањаше, али ноћу бијаше као огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'И кад би се облак подигао изнад шатора, тада полажаху синови Израиљеви, а гдје би стао облак, ондје се устављаху синови Израиљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'По заповијести Господњој полажаху синови Израиљеви, и по заповијести Господњој устављаху се; докле год стајаше облак над шатором, они стајаху у околу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'И кад облак дуго стајаше над шатором, тада свршиваху синови Израиљеви што треба свршивати Господу и не полажаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'И кад облак бијаше над шатором мало дана, по заповјести Господњој стајаху у околу и по заповијести Господњој полажаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Кад би пак облак стајао од вечера до јутра, а ујутру би се подигао облак, тада полажаху; било дању или ноћу, кад би се облак подигао, они полажаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Ако ли би два дана или мјесец дана или годину облак стајао над шатором, стајаху у околу синови Израиљеви и не полажаху, а како би се подигао, они полажаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'По заповијести Господњој стајаху у око, и по заповијести Господњој полажаху; и свршиваху што треба свршивати Господу, као што бјеше заповједио Господ преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Начини себи двије трубе од сребра, коване да буду; њима ћеш сазивати збор и заповиједати да полази војска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Кад обје затрубе, тада нека се скупља к теби сав збор на врата шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'А кад једна затруби, тада нека се скупљају к теби кнезови, главари од тисућа Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'А кад затрубите потресајући, тада нека се креће око који лежи према истоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'А кад затрубите други пут потресајући, онда нека се креће око који је према југу; потресајући нека се труби кад треба да пођу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'А кад сазивате збор, трубите, али не потресајући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'А нека трубе у трубе синови Аронови свештеници; то да вам је уредба вјечна од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'И кад пођете на војску у земљи својој на непријатеља који удари на вас, трубите у трубе потресајући; и Господ Бог ваш опоменуће вас се, и сачуваћете се од непријатеља својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Тако и у дан весеља својега и на празнике своје и почетке мјесеца својих трубите у трубе приносећи жртве своје паљенице и жртве своје захвалне, и биће вам спомен пред Богом вашим. Ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'И у двадесети дан другога мјесеца друге године подиже се облак изнад шатора од свједочанства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'И пођоше синови Израиљеви својим редом из пустиње Синајске, и устави се облак у пустињи Фаранској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Тако пођоше први пут, као што Господ заповједи преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'И пође напријед застава војске синова Јудинијех у четама својим; и над војском њиховом бјеше Насон син Аминадавов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'А над војском племена синова Исахаровијех Натанаило син Согаров;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'А над војском племена синова Завулоновијех Елијав син Хелонов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'И сложише шатор, па пођоше синови Гирсонови и синови Мераријеви носећи шатор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Потом пође застава војске синова Рувимовијех, а над њиховом војском бјеше Елисур син Седијуров,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'А над војском племена синова Симеуновијех Саламило син Сурисадајев,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'А над војском племена синова Гадовијех Елисаф син Рагуилов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'И пођоше синови Катови носећи светињу, да би они подигли шатор докле ови дођу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Потом пође застава војске синова Јефремовијех у четама својим, а над војском њиховом бјеше Елисама син Емијудов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'А над војском племена синова Манасијиних Гамалило син Фадасуров,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'А над војском племена синова Венијаминових Авидан син Гадеонијев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Најпослије пође застава војске синова Дановијех у четама својим, задња војска, и над војском њиховом бјеше Ахијезер син Амисадајев,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'А над војском племена синова Асировијех Фагаило син Ехранов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'А над војском племена синова Нефталимовијех Ахиреј син Енанов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Тијем редом пођоше синови Израиљеви у четама својим, и тако иђаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'А Мојсије рече Јоваву сину Рагуилову Мадијанину, тасту својему: идемо на мјесто за које рече Господ: вама ћу га дати. Хајде с нама, и добро ћемо ти учинити, јер је Господ обећао Израиљу много добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'А он му рече: нећу ићи, него идем у своју земљу и у род свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'А Мојсије рече немој нас оставити, јер знаш мјеста у пустињи гдје бисмо могли стајати, па нам буди вођ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'И ако пођеш с нама кад дође добро које ће нам учинити Господ, учинићемо ти добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'И тако пођоше од горе Господње, и иђаху три дана, и ковчег завјета Господњега иђаше пред њима три дана тражећи мјесто гдје би починули.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'И облак Господњи бјеше над њима сваки дан кад полажаху с мјеста, гдје бијаху у околу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'И кад полажаше ковчег, говораше Мојсије: устани Господе, и нека се разаспу непријатељи твоји, и нека бјеже испред тебе који мрзе на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'А кад се устављаше, говораше: уврати се, Господе, к мноштву тисућа Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Послије стаде се тужити народ да му је тешко; а то не би по вољи Господу; и кад Господ чу, разгњеви се; и распали се на њих огањ Господњи, и сажеже крајње у околу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Тада завапи народ к Мојсију, а Мојсије се помоли Господу, и угаси се огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'И прозва се оно мјесто Тавера, јер се распали на њих огањ Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'А свјетина што бијаше међу њима, бјеше врло лакома, те и синови Израиљеви стадоше плакати говорећи: ко ће нас нахранити меса?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Опоменусмо се риба што јеђасмо у Мисиру забадава, и краставаца и диња и лука црнога и бијелога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'А сада посахну душа наша, нема ништа осим мане пред очима нашима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'А мана бјеше као сјеме коријандрово, а боја му бјеше као боја у бдела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'И излажаше народ, те купљаху, и мељаху на жрвњима или туцаху у ступама, и кухаху у котлу, или мијешаху погаче; а кус јој бијаше као кус од новога уља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'И кад падаше роса по околу ноћу, падаше с њом и мана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'И чу Мојсије гдје народ плаче у породицама својим, сваки на вратима од шатора својега; и Господ се разгњеви врло, и Мојсију би тешко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Па рече Мојсије Господу: зашто учини тако зло слузи својему? И зашто не нађох милости пред тобом, него метну на ме терет свега народа овога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Еда ли ја зачех сав овај народ? Еда ли га ја родих, кад ми кажеш: изнеси га у наручју својем, као што носи дојиља дијете, у ону земљу за коју си се заклео оцима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Откуда мени меса да дам свему овом народу? Јер плачу преда мном говорећи: дај нам меса да једемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Не могу ја сам носити свега народа овога, јер је тешко за мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Ако ћеш тако чинити са мном, убиј ме боље, ако сам нашао милост пред тобом, да не гледам зла својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'А Господ рече Мојсију: сабери ми седамдесет људи између старјешина Израиљевијех, које знаш да су старјешине народу и управитељи његови, и доведи их к шатору од састанка, нека ондје стану с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Тада ћу сићи и говорити ондје с тобом, и узећу од духа који је на теби и метнућу на њих, да носе с тобом терет народни и да не носиш ти сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'А народу реци: приправите се за сјутра да једете меса, јер плакасте да Господ чу, и рекосте: ко ће нас нахранити меса? Јер нам добро бијаше у Мисиру. Даће вам дакле Господ меса и јешћете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Нећете јести један дан, ни два дана, ни пет дана, ни десет дана, ни двадесет дана;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Него цио мјесец дана, докле вам на нос не удари и не огади вам се, зато што одбацисте Господа који је међу вама и плакасте пред њим говорећи: зашто изиђосмо из Мисира?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'А Мојсије рече: шест стотина тисућа пјешака има народа, у којем сам, па ти кажеш: даћу им меса да једу цио мјесец дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Еда ли ће им се поклати овце и говеда да им достане? Или ће им се покупити све рибе морске да им буде доста?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'А Господ рече Мојсију: зар рука Господња неће бити довољна? Видјећеш хоће ли бити што ти рекох или неће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'И Мојсије изиде и рече народу ријечи Господње; и сабра седамдесет људи између старјешина народнијех, и постави их око шатора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'И Господ сиђе у облаку, и говори к њему, и узевши од духа који бјеше на њему метну на онијех седамдесет људи старјешина; и кад дух дође на њих, пророковаху, али више никад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'А два човјека осташе у околу, једном бјеше име Елдад, а другом Модад, на које дође дух, јер и они бијаху записани али не дођоше к шатору, и стадоше пророковати у околу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'И дотрча момак, те јави Мојсију говорећи: Елдад и Модад пророкују у околу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'А Исус син Навин, слуга Мојсијев, један од момака његовијех, рече говорећи: Мојсије господару мој, забрани им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'А Мојсије му одговори: зар завидиш мене ради? Камо да сав народ Господњи постану пророци и да Господ пусти дух свој на њих!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Потом се врати Мојсије у око са старјешинама Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Тада се подиже вјетар од Господа, и потјера од мора препелице, и разасу их по околу на дан хода одовуда и на дан хода одонуда око окола, на два лакта од земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'И уставши народ цео онај дан и сву ноћ и цео други дан купљаше препелице: и ко накупи најмање накупи десет гомора; и повјешаше их себи редом око окола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Али месо још им бијаше у зубима, јоште га не поједоше, а Господ се разгњеви на народ и удари Господ народ помором врло великим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'И прозва се оно мјесто Киврот-Атава јер ондје укопаше народ који се бјеше полакомио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'И пође народ од Киврот-Атаве у Асирот, и стадоше у Асироту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'И стадоше викати Марија и Арон на Мојсија ради жене Мадијанке, којом се ожени, јер се ожени Мадијанком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'И рекоше: зар је само преко Мојсија говорио Господ? Није ли говорио и преко нас? И то чу Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'А Мојсије бјеше човјек врло кротак мимо све људе на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'И одмах рече Господ Мојсију и Арону и Марији: дођите вас троје у шатор од састанка. И отидоше њих троје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Тада сиђе Господ у ступу од облака, стаде на вратима од шатора. И викну Арона и Марију, и дођоше обоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'И рече им: чујте сада ријечи моје: пророк кад је међу вама, ја ћу му се Господ јављати у утвари и говорићу с њим у сну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Али није таки мој слуга Мојсије, који је вјеран у свем дому мојем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Њему говорим из уста к устима, и он ме гледа доиста, а не у тами нити у каквој прилици Господњој. Како се дакле не побојасте викати на слугу мојега, на Мојсија?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'И гњев се Господњи распали на њих, и он отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'И облак се подиже са шатора; и гле, Марија бјеше губава, бијела као снијег. И Арон погледа Марију, а она губава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Тада рече Арон Мојсију: господару, молим те, не мећи на нас гријеха овога, јер лудо учинисмо и згријешисмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Немој да ова буде као мртво дијете, којему је месо пола труло кад излази из утробе матере своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'И вапи Мојсије ка Господу говорећи: Боже, молим ти се, исцијели је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'А Господ одговори Мојсију: да јој је отац њезин пљунуо у лице, не би ли се стидјела седам дана? Нека буде одлучена седам дана изван окола, а послије нека буде опет примљена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Тако би Марија одлучена изван окола седам дана; и народ не пође оданде докле Марија не би опет примљена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'А потом пође народ од Асирота, и стадоше у пустињи Фаранској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'И Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Пошљи људе да уходе земљу Хананску, коју ћу дати синовима Израиљевијем; по једнога човјека од свакога племена отаца њиховијех пошљите, све главаре између њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'И посла их Мојсије из пустиње Фаранске по заповијести Господњој; и сви људи бјеху главари синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'А ово су им имена: од племена Рувимова Самуило син Захуров;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Од племена Симеунова Сафат син Сурин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Од племена Јудина Халев син Јефонијин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Од племена Исахарова Игал син Јосифов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Од племена Јефремова Авсије син Навин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Од племена Венијаминова Фалтије син Рафујев;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Од племена Завулонова Гудило син Судин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Од племена Јосифова, од племена Манасијина Гадије син Сусин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Од племена Данова Амило син Гамалин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Од племена Асирова Сатур син Михаилов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Од племена Нефталимова Навија син Савин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Од племена Гадова Гудило син Махилов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'То су имена људима које посла Мојсије да уходе земљу. И назва Мојсије Авсија сина Навина Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'И шаљући их Мојсије да уходе земљу Хананску рече им: идите овуда на југ, па изидите на гору;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'И видите земљу каква је и какав народ живи у њој, је ли јак или слаб, је ли мали или велик;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'И каква је земља у којој живи, је ли добра или рђава; и каква су мјеста у којима живи, еда ли под шаторима или у тврдим градовима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'И каква је сама земља, је ли родна или неродна, има ли у њој дрвета или нема; будите слободни, и узмите рода оне земље. А тада бјеше вријеме првом грожђу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'И отишавши уходише земљу од пустиње Синске до Реова како се иде у Емат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'И идоше на југ, и дођоше до Хеврона, гдје бијаху Ахиман и Сесије и Телиман, синови Енакови. А Хеврон бјеше сазидан на седам година прије Соана Мисирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Потом дођоше до потока Есхола, и ондје отсјекоше лозу с гроздом једнијем, и понесоше га двојица на моци; тако и шипака и смокава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'И прозва се оно мјесто поток Есхол од грозда, који ондје отсјекоше синови Израиљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'И послије четрдесет дана вратише се из земље коју уходише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'И вративши се дођоше к Мојсију и Арону и ка свему збору синова Израиљевијех у пустињу Фаранску, у Кадис; и приповједише њима и свему збору ствар, и показаше им род оне земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'И приповиједајући им рекоше: идосмо у земљу у коју си нас послао; доиста тече у њој млијеко и мед, и ево рода њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Али је јак народ који живи у оној земљи, и градови су им тврди и врло велики; а видјесмо ондје и синове Енакове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Амалик живи на јужној страни; а Хетеји и Јевусеји и Амореји живе у планини, а Хананеји живе на мору и на Јордану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'А Халев утишаваше народ пред Мојсијем; и говораше: хајде да идемо да је узмемо, јер је можемо покорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Али други људи који идоше с њим говораху: не можемо ићи на онај народ, јер је јачи од нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'И просуше зао глас о земљи коју уходише међу синовима Израиљевијем говорећи: земља коју прођосмо и уходисмо земља је која прождире своје становнике, и сав народ који видјесмо у њој јесу људи врло велики.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 34, 'Видјесмо ондје и дивове, синове Енакове, рода дивовскога, и чињаше нам се да смо према њима као скакавци, таки се и њима чињасмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Тада се подиже сав збор и стаде викати, и народ плакаше ону ноћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'И викаху на Мојсија и на Арона сви синови Израиљеви; и сав збор рече им: камо да смо помрли у земљи Мисирској или да помремо у овој пустињи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Зашто нас води Господ у ту земљу да изгинемо од мача, жене наше и дјеца наша да постану робље? Није ли боље да се вратимо у Мисир?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'И рекоше међу собом: да поставимо старјешину, па да се вратимо у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Тада Мојсије и Арон падоше ничице пред свијем збором синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'А Исус син Навин и Халев син Јефонијин између онијех што уходише земљу, раздријеше хаљине своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'И рекоше свему збору синова Израиљевијех говорећи: земља коју прођосмо и уходисмо, врло је добра земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Ако смо мили Господу, он ће нас одвести у ту земљу, и даће нам је; а то је земља у којој тече млијеко и мед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Само се не одмећите Господа, и не бојте се народа оне земље; јер их можемо појести; отступио је од њих заклон њихов, а с нама је Господ, не бојте их се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Тада рече сав збор да их побију камењем; али се показа слава Господња свијем синовима Израиљевијем у шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'И рече Господ Мојсију: докле ће ме вријеђати тај народ? Кад ли ће ми вјеровати послије толиких знака што сам учинио међу њима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Ударићу га помором, и расућу га; а од тебе ћу учинити народ велик и јачи од овога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'А Мојсије рече Господу: али ће чути Мисирци, између којих си извео овај народ силом својом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'И рећи ће с људима ове земље, који су чули да си ти, Господе, био усред народа и да си се очима виђао, Господе, и облак твој да је стајао над њима, и у ступу од облака да си ишао пред њима дању и у ступу огњеном ноћу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Па кад побијеш овај народ, све до једнога, говориће народи, који су чули приповијест о теби, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Није могао Господ довести народа овога у земљу коју им је са заклетвом обећао, зато их поби у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Нека се дакле прослави сила Господња, као што си рекао говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Господ дуго чека и обилан је милошћу, прашта безакоње и гријех, али не правда кривога, него походи безакоње отачко на синовима до трећега и четвртога кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Опрости безакоње овому народу ради велике милости своје, као што си праштао народу овому од Мисира довде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'А Господ рече: праштам по ријечи твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Али тако ја жив био, и тако сва земља била пуна славе Господње,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Ти људи који видјеше славу моју и знаке моје што сам учинио у Мисиру и у овој пустињи, и кушаше ме већ десет пута, и не послушаше ријечи моје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Неће видјети земље коју са заклетвом обећах оцима њиховијем, неће видјети ни један од оних који ме увриједише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'А слугу својега Халева, у којем бјеше други дух и који се сасвијем мене држао, њега ћу одвести у земљу у коју је ишао, и сјеме ће је његово наслиједити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Али Амалик и Хананеј сједе у долини, зато се сјутра вратите натраг, и идите у пустињу к Црвеном Мору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Још рече Господ Мојсију и Арону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Докле ће тај зли збор викати на ме? Чуо сам вику синова Израиљевијех, којом вичу на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Кажи им: тако ја жив био, каже Господ, учинићу вам онако како сте говорили и ја чух.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'У овој ће пустињи попадати мртва тјелеса ваша, и сви између вас који су избројени у свем броју вашем од двадесет година и више, који викасте на ме,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Нећете ући у земљу, за коју подигав руку своју заклех се да ћу вас населити у њој, осим Халева сина Јефонијина и Исуса сина Навина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'А дјецу вашу, за коју рекосте да ће постати робље, њих ћу одвести, и они ће познати земљу за коју ви не марите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'А ваша тјелеса мртва ће попадати у овој пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'А дјеца ваша биће пастири по пустињи четрдесет година, и носиће кар за прељубе ваше, докле не испропадају тјелеса ваша у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'По броју дана, за које уходисте земљу, четрдесет дана, на сваки дан по годину, носићете гријехе своје, четрдесет година, и познаћете да сам прекинуо с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Ја Господ рекох, и тако ћу учинити свему том збору злому, који се сабрао на ме: у пустињи ће пропасти и ту помријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'А људи које бјеше послао Мојсије да уходе земљу, и који вративши се побунише сав збор да виче на њ, просувши зао глас о земљи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Ти људи, који просуше зао глас о земљи, помријеше од помора пред Господом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'А Исус син Навин и Халев син Јефонијин осташе живи између људи који су ишли да уходе земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'И Мојсије каза све ове ријечи свијем синовима Израиљевијем, и народ плака веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'А сјутрадан уставши пођоше наврх горе, и рекоше: ево нас, идемо на мјесто за које је говорио Господ, јер згријешисмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Али Мојсије рече: зашто преступате заповијест Господњу? Од тога неће бити ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Не идите горе, јер Господ није међу вама; немојте да вас побију непријатељи ваши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Јер је Амалик и Хананеј тамо пред вама, и изгинућете од мача, јер одустависте Господа, па неће ни Господ бити с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Али они ипак навалише да иду наврх горе; али ковчег завјета Господњега и Мојсије не изађоше из окола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Тада сиђе Амалик и Хананеј, који живљаху у оној гори, и разбише их и бацише дори до Орме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Опет рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Реци синовима Израиљевијем и кажи им: кад дођете у земљу гдје ћете наставати, коју ћу вам ја дати,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'И станете приносити жртву огњену Господу, жртву паљеницу или жртву завјета ради или од драге воље, или о празницима својим, готовећи мирис угодни Господу од крупне или од ситне стоке,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Тада ко принесе принос свој Господу, нека донесе уза њ дар, десетину ефе бијелога брашна помијешана с четвртином ина уља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'И вина четврт ина за наљев донеси уз жртву паљеницу или уз другу жртву, на свако јагње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'А уз овна донеси дар, двије десетине бијелога брашна помијешана с трећином ина уља,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'И вина за наљев трећину ина принијећеш за мирис угодни Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'А кад приносиш теле на жртву паљеницу или на жртву ради завјета или на жртву захвалну Господу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'Онда нека се донесе уз теле дар, три десетине ефе бијелога брашна помијешана с по ина уља,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'И вина донеси за наљев по ина; то је жртва огњена за мирис угодни Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Тако нека буде уза свакога вола и уза свакога овна и уза свако живинче између оваца или коза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Према броју колико принесете, учините тако уза свако, колико их буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Сваки домородац тако нека чини приносећи жртву паљеницу за мирис угодни Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Тако ако буде међу вама и дошљак или ко би се бавио међу вама, па би принио жртву огњену за мирис угодни Господу, нека чини онако како ви чините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Зборе! Вама и дошљаку који је међу вама један да је закон, закон вјечан од кољена на кољено; дошљак ће бити као и ви пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Један закон и једна уредба да буде вама и дошљаку, који је међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Кажи синовима Израиљевијем и реци им: кад дођете у земљу, у коју ћу вас ја одвести,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'Па станете јести хљеб оне земље, тада принесите принос Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Од првина тијеста својега приносите у принос колач, као принос од гумна тако га приносите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Од првина тијеста својега дајите Господу принос од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'А кад бисте погријешили, те не бисте учинили свијех овијех заповијести, које каза Господ Мојсију,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Све што вам је заповједио Господ преко Мојсија, од дана кад заповједи Господ и послије од кољена до кољена,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Ако се буде учинило погрјешком, да збор не зна, онда сав збор нека принесе на жртву паљеницу за мирис угодни Господу теле с даром његовијем и с наљевом његовијем по уредби, и једно јаре на жртву за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'И свештеник нека очисти сав збор синова Израиљевијех, и опростиће им се, јер је погрјешка и они донесоше пред Господа свој принос за жртву огњену Господу и принос за гријех свој ради погрјешке своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Опростиће се свему збору синова Израиљевијех и дошљаку који се бави међу њима, јер је погрјешка свега народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Ако ли једна душа згријеши не знајући, нека принесе козу од године на жртву за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'И свештеник нека очисти душу која буде згријешила не знајући пред Господом, и кад је очисти опростиће јој се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'И за рођенога у земљи синова Израиљевијех и за дошљака, који се бави међу вама, један закон да буде кад ко згријеши не знајући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Али ко од силе згријеши између рођенијех у земљи или између дошљака, он ружи Господа; нека се истријеби душа она из народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Јер презре ријеч Господњу, и заповијест његову погази; нека се истријеби она душа; безакоње је њезино на њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'А кад бијаху синови Израиљеви у пустињи, нађоше једнога гдје купи дрва у суботу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'И који га нађоше гдје купи дрва, доведоше га к Мојсију и к Арону и ка свему збору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'И метнуше га под стражу, јер не бјеше казано шта ће се чинити с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'А Господ рече Мојсију: Нека се погуби тај човјек; нека га заспе камењем сав збор иза окола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'И сав збор изведе га иза окола и засуше га камењем, и умрије, као што заповједи Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Реци синовима Израиљевијем и кажи им, нека ударају ресе по скутовима од хаљина својих од кољена до кољена, и над ресе нека мећу врвцу плаву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'И имаћете ресе зато да се гледајући их опомињете свијех заповијести Господњих и творите их, и да се не заносите за срцем својим и за очима својима, за којима чините прељубу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Него да памтите и творите све заповијести моје, и будете свети Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Ја сам Господ Бог ваш, који сам вас извео из земље Мисирске, да вам будем Бог. Ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'А Кореј син Исара сина Ката сина Левијева, и Датан и Авирон синови Елијавови, и Авнан син Фалета сина Рувимова побунише се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'И усташе на Мојсија, и с њима двјеста и педесет људи између синова Израиљевијех, главара народнијех, који се сазиваху на збор и бијаху људи знатни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'И скупише се на Мојсија и на Арона, и рекоше им: доста нек вам је; сав овај народ, сви су свети, и међу њима је Господ; зашто се ви подижете над збором Господњим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Кад то чу Мојсије, паде ничице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Потом рече Кореју и свој дружини његовој говорећи: сјутра ће показати Господ ко је његов, и ко је свет, и кога је пустио к себи, јер кога је изабрао онога ће пустити к себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Ово учините: узмите кадионице, Кореј са свом дружином својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'И метните сјутра у њих огња и метните у њих када пред Господом, и кога избере Господ онај ће бити свет. Доста нек вам је, синови Левијеви!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'И рече Мојсије Кореју: чујте синови Левијеви!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Мало ли вам је што вас је Бог Израиљев одвојио од збора Израиљева пустивши вас к себи да вршите службу у шатору Господњем и да стојите пред збором и служите за њ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Пустио је к себи тебе и сву браћу твоју, синове Левијеве, с тобом, а ви тражите још и свештенство?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Зато ти и сва дружина твоја скуписте се на Господа. Јер Арон шта је да вичете на њ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'И посла Мојсије да дозову Датана и Авирона синове Елијавове. А они одговорише: нећемо да идемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Мало ли је што си нас извео из земље у којој тече млијеко и мед да нас побијеш у овој пустињи, него још хоћеш да владаш над нама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Јеси ли нас одвео у земљу гдје тече млијеко и мед? и јеси ли нам дао да имамо њива и винограда? хоћеш ли очи овим људима да ископаш? Нећемо да идемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Тада се расрди Мојсије врло, и рече Господу: немој погледати на дар њихов; ниједнога магарца нисам узео од њих, нити сам коме од њих учинио какога зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Потом рече Мојсије Кореју: ти и сви твоји станите сјутра пред Господом, ти и они и Арон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'И узмите сваки своју кадионицу, и метните у њих када, и станите пред Господом сваки са својом кадионицом, двјеста и педесет кадионица, и ти и Арон, сваки са својом кадионицом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'И узеше сваки своју кадионицу, и метнувши у њих огња метнуше у њих када, и стадоше на врата шатора од састанка с Мојсијем и Ароном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'А Кореј сабра на њих сав збор на врата шатора од састанка; тада се показа слава Господња свему збору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'И рече Господ Мојсију и Арону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Одвојте се из тога збора, да их одмах сатрем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'А они падоше ничице и рекоше: Боже, Боже духовима и сваком тијелу! овај један згријешио, и на сав ли ћеш се збор гњевити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Опет рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Реци збору и кажи: отступите од шатора Корејева и Датанова и Авиронова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'И уставши Мојсије отиде к Датану и Авирону, а за њим отидоше старјешине Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'И рече збору говорећи: отступите од шатора тијех безбожника, и не додијевајте се ничега што је њихово, да не изгинете са свијех гријеха њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'И отступише са свијех страна од шатора Корејева и Датанова Авиронова; а Датан и Авирон изашавши стадоше сваки на врата од шатора својега са женама својим и са синовима својим и с дјецом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Тада рече Мојсије: овако ћете познати да ме је Господ послао да чиним сва ова дјела, и да ништа не чиним од себе:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Ако ови помру као што мру сви људи, и ако буду покарани као што бивају покарани сви људи, није ме послао Господ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Ако ли што ново учини Господ, и земља отвори уста своја и прождре их са свијем што је њихово, и сиђу живи у гроб, тада знајте да су ови људи увриједили Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'А кад изговори ријечи ове, расједе се земља под њима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'И отворивши земља уста своја прождрије их, и домове њихове и све људе Корејеве и све благо њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'И тако сиђоше са свијем што имаху живи у гроб, и покри их земља и неста их из збора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'А сви Израиљци који бијаху око њих побјегоше од вике њихове, јер говораху: да нас не прождре земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'И изађе огањ од Господа, и сажеже онијех двјеста и педесет људи који принесоше кад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Тада рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Кажи Елеазару сину Арона свештеника нека покупи кадионице из тога гаришта, и угљевље из њих нека разбаци, јер су свете;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'Кадионице онијех који огријешише душе своје нека раскују на плоче да се окује олтар, јер кадише њима пред Господом, зато су свете, и нека буду синовима Израиљевијем знак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'И покупи Елеазар свештеник кадионице мједене, којима бјеху кадили они што изгорјеше, и расковаше их на оков олтару');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'За спомен синовима Израиљевијем, да не приступа нико други који није рода Аронова да кади пред Господом, да му не буде као Кореју и дружини његовој, као што му бјеше казао Господ преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'А сјутрадан викаше сав збор синова Израиљевијех на Мојсија и на Арона говорећи: побисте народ Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'А кад се стјецаше народ на Мојсија и на Арона, погледаше на шатор од састанка, а то облак на њему, и показа се слава Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'И дође Мојсије и Арон пред шатор од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Уклоните се из тога збора да их одмах потрем. А они падоше ничице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'И рече Мојсије Арону: узми кадионицу, и метни у њу огња с олтара, и метни када, и иди брже ка збору, и очисти их; јер гњев жесток изађе од Господа, и помор поче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'И узевши Арон кадионицу, као што му рече Мојсије, отрча усред збора, и гле, помор већ бјеше почео у народу; и окадив очисти народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'И стајаше међу мртвима и живима, и устави се помор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'А онијех који помријеше од тога помора бјеше четрнаест тисућа и седам стотина, осим онијех што изгибоше с Кореја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'И врати се Арон к Мојсију на врата шатора од састанка, кад се устави помор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Потом рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Реци синовима Израиљевијем, и узми од њих по једну палицу од свакога дома отаца њиховијех, од свијех кнезова њиховијех, по домовима отаца њиховијех, дванаест палица, и име свакога напиши на палици његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'А на палици Левијевој напиши име Ароново, јер је свака палица за једног поглавара од дома отаца њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'И остави их у шатору од састанка пред свједочанством, гдје се састајем с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'И кога изаберем, његова ће палица процвјетати; тако ћу утишати пред собом вику синова Израиљевијех што вичу на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Кад то рече Мојсије синовима Израиљевијем, дадоше му сви кнезови њихови палице, сваки кнез по палицу од дома оца својега, дванаест палица, и палица Аронова беше међу палицама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'И остави Мојсије палице пред Господом у шатору од свједочанства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'А сјутрадан дође Мојсије у шатор од свједочанства, и гле, процвјетала палица Аронова од дома Левијева; бјеше напупила и цвјетала, и бадеми зрели на њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'И изнесе Мојсије све оне палице испред Господа к свијем синовима Израиљевијем, и разгледавши их узеше сваки своју палицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'А Господ рече Мојсију: донеси опет палицу Аронову пред свједочанство да се чува за знак непокорнима, да престане вика њихова на ме, да не изгину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'И учини Мојсије, како му заповједи Господ тако учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Тада рекоше синови Израиљеви Мојсију говорећи: помријесмо, пропадосмо, сви пропадосмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Ко се год приближи к шатору Господњему гине; хоћемо ли сви изгинути?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'А Господ рече Арону: ти и синови твоји и дом оца твојега с тобом носите гријехе о светињу; ти и синови твоји с тобом носите гријехе свештенства својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'И браћу своју, племе Левијево, племе оца својега узми к себи да буду уза те и служе ти; а ти ћеш и синови твоји с тобом служити пред шатором од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Нека добро слушају заповијести твоје и раде што треба у свем шатору; али к судовима од светиње к олтару нека не приступају, да не изгину и они и ви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Нека буду дакле уза те, и нека раде све што треба у шатору од састанка у свакој служби у њему; али нико други да не приступи с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'А ви радите што треба у светињи и што треба на олтару, да више не дође гњев на синове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Јер ево ја узех браћу вашу Левите између синова Израиљевијех, и вама су дани на дар за Господа, да врше службу у шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'А ти и синови твоји с тобом вршите свештеничку службу своју у свему што припада к олтару и што бива иза завјеса, и служите; свештенство даровах вам, зато ко би други приступио, да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Још рече Господ Арону: ево, дајем ти и приносе своје што се увис подижу, између свијех ствари које посвећују синови Израиљеви дајем их теби ради помазања и синовима твојим законом вјечним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'То нека је твоје од ствари посвећенијех, које се не сажижу; сваки принос њихов између свих дарова њиховијех и између свијех приноса за гријех и свих приноса за кривицу, које ми донесу, светиња над светињама да је твоја и синова твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'У светињи га једи, све мушкиње нека га једе, света ствар да ти је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Твоје су дакле жртве дарова њиховијех које се у вис подижу; и сваку жртву синова Израиљевијех која се обрће теби дајем и синовима твојим и кћерима твојим с тобом законом вјечним; ко је год чист у дому твојем, нека једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Најбоље од уља и најбоље од вина и жита, првине које дају Господу, теби дајем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Првине од свега што роди у земљи њиховој, које донесу Господу, твоје нека буду; ко је год чист у дому твојем нека једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Све завјетовано Богу и Израиљу, твоје нека је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Што год отвара материцу између свакога тијела које приносе Господу, и између људи и између стоке, твоје да буде; али првенац човјечји нека се откупљује; и првенац нечисте стоке нека се откупљује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'А откуп нека му буде кад буде од мјесеца дана по твојој цијени пет сикала сребра, по сиклу светом; у њему је двадесет гера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'А првенца од краве или првенца од овце или првенца од козе не дај да се откупи; свете су ствари; крвљу њиховом покропи олтар, и сало њихово запали, да буде жртва огњена за мирис угодни Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'А месо од њих да је твоје, као груди што се обрћу и као плеће десно, да је твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Све приносе што се подижу од посвећенијех ствари, што приносе синови Израиљеви Господу, дајем теби и синовима твојим и кћерима твојим с тобом законом вјечним; то ће бити завјет осољен, вјечан пред Господом теби и сјемену твојему с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Још рече Господ Арону: у земљи њиховој да немаш нашљедства, ни дијела међу њима да немаш; ја сам дио твој и твоје нашљедство међу синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'А синовима Левијевим ево дајем у нашљедство све десетке од Израиља за службу њихову што служе у шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'А синови Израиљеви нека више не приступају к шатору од састанка, да се не огријеше и не изгину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Него сами Левити нека служе службу у шатору од састанка, и они нека носе гријех свој законом вјечним од кољена до кољена, па да немају нашљедства међу синовима Израиљевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Јер десетке синова Израиљевијех, што ће доносити Господу на жртву што се подиже, дајем Левитима у нашљедство; тога ради рекох за њих: међу синовима Израиљевијем да немају нашљедства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Реци Левитима и кажи им: кад узмете од синова Израиљевијех десетак који вам дадох од њих за нашљедство ваше, онда принесите од њега принос што се подиже Господу, десето од десетога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'И примиће вам се принос ваш као жито с гумна и као вино из каце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Тако и ви приносите принос што се подиже Господу од свијех десетака својих, које ћете узимати од синова Израиљевијех, и дајите од њих принос Господњи Арону свештенику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Од свега што вам се да приносите сваки принос што се подиже Господу, од свега што буде најбоље свети дио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'И реци им: кад принесете најбоље од тога, тада ће се примити Левитима као доходак од гумна и као доходак од каце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'А јести можете то на сваком мјесту и ви и породице ваше, јер вам је плата за службу вашу у шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'И нећете зато навући на се гријеха, кад станете приносити што је најбоље, и нећете оскврнити светијех ствари синова Израиљевијех, и нећете изгинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Још рече Господ Мојсију и Арону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Ово је уредба и закон што заповједи Господ говорећи: реци синовима Израиљевијем нека ти доведу јуницу црвену здраву, на којој нема мане, и која још није била у јарму;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'И подајте је Елеазару свештенику, а он нека је изведе напоље из окола да је закољу пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'И узевши Елеазар крви њезине на прст свој нека покропи крвљу према шатору од састанка седам пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Потом нека заповједи да се спали јуница пред његовијем очима; кожу њезину и месо њезино и крв њезину с балегом нека спале.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'И свештеник узевши дрвета кедрова, исопа и црвца, нека баци у огањ гдје гори јуница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Потом нека опере хаљине своје и опере тијело своје водом, па онда нека уђе у око, и нека буде свештеник нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Тако и ко је спали, нека опере хаљине своје водом, и тијело своје нека опере водом, и нека буде нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'А чист човјек нека покупи пепео од јунице и изручи га иза окола на чисто мјесто, да се чува збору синова Израиљевијех за воду очишћења; то је жртва за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'И онај који покупи пепео од јунице нека опере хаљине своје, и нека буде нечист до вечера. То нека је синовима Израиљевијем и дошљаку који се бави међу њима вјечан закон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Ко се дотакне мртва тијела човјечијега, да је нечист седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Он нека се очисти оном водом трећи дан и седми дан, и биће чист; ако ли се не очисти трећи дан и седми, неће бити чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Ко се дотакне мртва тијела човјечијега па се не очисти, онај је оскрвнио шатор Господњи; зато да се истријеби она душа из Израиља; јер није покропљен водом очишћења, зато је нечист, и нечистота је његова на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Ово је закон кад човјек умре у шатору: ко год уђе у онај шатор и ко год буде у шатору, нечист да је седам дана;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'И сваки суд откривен, који не буде добро заклопљен, нечист је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'И ко се год дотакне у пољу посјеченога мачем или умрлога или кости човјечије или гроба, нечист да је седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'И нека за нечистога узму пепела од јунице спаљене за гријех, и нека налију на њ воде живе у суд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Потом нека узме чист човјек исопа и замочи у ону воду, и покропи њом шатор и све суде и људе који су у њему били; тако и онога који би се дотакао кости или човјека посјечена или умрла или гроба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Чисти нечистога нека покропи трећи и седми дан; и кад га очисти седми дан, нека опере хаљине своје и себе нека опере водом, и биће чист увече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'А ко буде нечист па се не очисти, да се истријеби она душа из збора; јер је светињу Господњу оскврнио, а није покропљен водом очишћења; нечист је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'И ово нека им је закон вјечан: и који покропи водом очишћења, нека опере хаљине своје; и ко се год дотакне воде очишћења, да је нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'И чега се год дотакне ко је нечист, да је нечисто; и ко се њега дотакне, да је нечист до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'И синови Израиљеви, сав збор њихов, дођоше у пустињу Синску првога мјесеца, и стаде народ у Кадису; и ондје умрије Марија, и би погребена ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'А ондје немаше збор воде, те се скупише на Мојсија и на Арона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'И свађаше се народ с Мојсијем, и говораху: камо да смо помрли кад помријеше браћа наша пред Господом!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Зашто доведосте збор Господњи у ову пустињу да изгинемо овдје и ми и стока наша?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'И зашто нас изведосте из Мисира да нас доведете на ово зло мјесто, гдје не роди ни жито ни смоква ни грожђе ни шипак, а ни воде нема за пиће?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'И дође Мојсије и Арон испред збора на врата шатора од састанка, и падоше ничице; и показа им се слава Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Узми штап, и сазовите збор ти и Арон брат твој, и проговорите стијени пред њима, те ће дати воду своју; тако ћеш им извести воду из стијене, и напојићеш збор и стоку њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'И Мојсије узе штап испред Господа, како му заповједи Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'И сазваше Мојсије и Арон збор пред стијену, и он им рече: слушајте одметници! хоћемо ли вам из ове стијене извести воду?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'И диже Мојсије руку своју и удари у стијену штапом својим два пута, и изиде вода многа, те се напоји народ и стока њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'А Господ рече Мојсију и Арону: што ми не вјеровасте и не прослависте ме пред синовима Израиљевим, зато нећете одвести збора тога у земљу коју сам им дао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'То је вода од свађе, гдје се свађаше синови Израиљеви с Господом, и он се прослави међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Иза тога посла Мојсије посланике из Кадиса к цару Едомском да му реку: овако каже брат твој Израиљ: ти знаш све невоље које нас снађоше:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Како наши оци сиђоше у Мисир, и бијасмо у Мисиру дуго времена, и како Мисирци зло чинише нама и оцима нашим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'И викасмо ка Господу, и Господ чу глас наш, и посла анђела, који нас изведе из Мисира; и ево смо у Кадису, граду на твојој међи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Пусти нас да прођемо кроз твоју земљу; нећемо ићи преко поља ни преко винограда, нити ћемо пити воде из којега студенца; ићи ћемо царским путем, нећемо свртати ни надесно ни налијево док не пријеђемо међу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'А Едом му одговори: не иди преко моје земље, да не изидем с мачем преда те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'А синови Израиљеви рекоше му: ићи ћемо утреником, и ако се напијемо воде твоје, ми или стока наша, платићемо је; ништа више, само да пјешице прођемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'А он им одговори: нећете проћи. И изиде Едом пред њих с много народа и с великом силом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'И кад не хтје Едом допустити Израиљу да пријеђе преко међе његове, Израиљ отиде од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'И кренувши се од Кадиса дођоше синови Израиљеви, сав збор њихов, ка гори Ору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'И Господ рече Мојсију и Арону на гори Ору код међе Едомске говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Арон ваља да се прибере к роду својему, јер неће ући у земљу коју сам дао синовима Израиљевијем, јер не послушасте заповијести моје на води од свађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Узми Арона и Елеазара сина његова, и изведи их на гору Ор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'И свуци Арону хаљине његове и обуци их Елеазару сину његову, па ће се Арон прибрати и умријети ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'И учини Мојсије како заповједи Господ; и изидоше на гору Ор пред свијем збором.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'И свуче Мојсије с Арона хаљине његове и обуче их Елеазару сину његову, и умре ондје Арон наврх горе, а Мојсије и Елеазар сидоше с горе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'А кад видје сав збор да умрије Арон, плака сав дом Израиљев за Ароном тридесет дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'А кад чу Хананеј цар Арадски, који живљаше на југу, да иде Израиљ путем којим идоше уходе, он се поби с њима и зароби их неколико.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Тада се Израиљ завјетова Господу и рече: ако даш овај народ мени у руке, до темеља ћу раскопати градове њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'И услиши Господ глас Израиљев и даде му Хананеје, а он затр њих и градове њихове, и прозва оно мјесто Орма.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Потом пођоше од горе Ора к Црвеном Мору обилазећи земљу Едомску, и ослаби дух народу од пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'И викаше народ на Бога и на Мојсија: зашто нас изведосте из Мисира да изгинемо у овој пустињи? Јер нема ни хљеба ни воде, а овај се никаки хљеб већ огадио души нашој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'А Господ пусти на народ змије ватрене, које их уједаху, те помрије много народа у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Тада дође народ к Мојсију и рекоше: згријешисмо што викасмо на Господа и на тебе; моли Бога нека уклони змије од нас. И Мојсије се помоли за народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'И Господ рече Мојсију: начини змију ватрену, и метни је на мотку, и кога уједе змија, нека погледа у њу, па ће оздравити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'И начини Мојсије змију од мједи, и метну је на мотку, и кога год уједе змија он погледа у змију од мједи, и оздрави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Потом пођоше синови Израиљеви, и стадоше у око у Овоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'И из Овота отишавши стадоше у око на брдима Аваримским у пустињи која је према Моавској с истока.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Оданде отишавши стадоше у око у долини Зареду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'И одатле отишавши стадоше у око на брду на Арнону, који је у пустињи и излази од међе Аморејске. Јер је Арнон међа Моавска између Моаваца и Аморејаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Зато се каже у књизи о ратовима Господњим: на Вајева у Суфи и на потоке Арнонске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Јер ти потоци, који допиру до мјеста Ара, теку покрај међе Моавске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'А отуда дођоше к Виру; то је студенац за који бјеше рекао Господ Мојсију: скупи народ, и даћу им воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Тада пјева Израиљ пјесму ову: Дижи се, студенче; припијевајте га;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Студенче, који копаше кнезови, који ископаше поглавари народни с онијем који постави закон, палицама својим. А из пустиње отидоше у Мантанаил,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'А из Мантанаила, у Надил, а из Надила у Вамот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'А из Вамота у долину која је у пољу Моавском код горе Фазге и гледа у пустињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Тада посла Израиљ посланике к Сиону цару Аморејском говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Пусти да прођемо кроз твоју земљу, нећемо свртати ни у поље ни у виноград, нити ћемо пити воде из студенаца; ићи ћемо царским путем докле не пријеђемо међу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Али не даде Сион Израиљу да прође кроз земљу његову, него сабра Сион сав народ свој, и изађе на Израиља у пустињу, и дође у Јасу, и поби се с Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Али га исијече Израиљ оштрим мачем, и освоји земљу његову од Арона па до Јавока до синова Амоновијех, јер тврда бјеше међа синова Амоновијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'И узе Израиљ сва она мјеста и насели се у свим градовима Аморејским, у Есевону и у свијем селима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Јер Есевон бјеше град Сиона цара Аморејскога, који бјеше први завојштио на цара Моавскога и бјеше му узео сву земљу његову до Арнона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Зато говоре у причи: ходите у Есевон, да се сагради и подигне град Сионов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Јер огањ изађе из Есевона, пламен из града Сионова, и спали Ар Моавски и становнике на висини Арнонској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Тешко теби, Моаве; пропао си, народе Хамосов; дао је синове своје који утекоше и кћери своје у ропство Сиону цару Аморејском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Али их постријељасмо, пропаде Есевон до Девона, и потрсмо их до Нофе, која допире до Медеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'И тако живје Израиљ у земљи Аморејској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Потом посла Мојсије да уходе Јазир, и узеше села око њега, и изагнаше Аморејце који бијаху ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Потом обративши се пођоше у Васан; и изиде Ог цар Васански пред њих, он и сав народ његов на бој у Едрајин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'А Господ рече Мојсију: не бој га се; јер сам га дао у твоје руке и сав народ његов и земљу његову; и учини му како си учинио Сиону цару Аморејском који живљаше у Есевону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'И побише га и синове његове и сав народ његов, да не оста ниједан, и освојише земљу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Одатле се подигоше синови Израиљеви, и стадоше у око у пољу Моавском с ону страну Јордана према Јерихону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'И видје Валак син Сефоров све што учини Израиљ Амореју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'И уплаши се Моав од народа веома; јер га бјеше много, и притужи Моаву од синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Па рече Моав старјешинама Мадијанским: сада ће ова множина појести све што је око нас као во траву у пољу. А Валак син Сефоров бјеше у оно вријеме цар Моавски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'И посла посланике к Валаму сину Веорову у Фатуру, која је на ријеци у земљи народа његова, говорећи: ево народ изиде из Мисира, ево прекрилио је земљу, и стоји према мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Него ходи, прокуни ми овај народ, јер је јачи од мене, е да бих му одолио и побио га или истерао из земље ове; јер знам, кога благословиш биће благословен, а кога прокунеш биће проклет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'И отидоше старјешине Моавске и старјешине Мадијанске носећи дарове за врачање; и дођоше к Валаму, и казаше му ријечи Валакове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'А он им рече: останите овдје ову ноћ, и одговорићу вам како ми Господ каже. И осташе кнезови Моавски код Валама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'А Бог дође к Валаму и рече му: какви су то људи код тебе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'И рече Валам Богу: Валак син Сефоров, цар Моавски, посла их к мени говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Ево народ изиде из Мисира и прекрили земљу; него ходи, прокуни ми га, е да бих га надбио и отјерао га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'А Бог рече Валаму: не иди с њима, нити куни тога народа, јер је благословен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'И ујутру уставши Валам рече кнезовима Валаковијем; вратите се у своју земљу јер ми не да Бог да идем с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'И уставши кнезови Моавски дођоше к Валаку, и рекоше: не хтје Валам поћи с нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Тада опет посла Валак више кнезова и веће од првијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'И они дошавши к Валаму рекоше му: овако вели Валак син Сефоров: немој се затезати, молим те, него дођи к мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Јер ћу те добро даривати, и што ми год речеш чинићу; зато дођи, молим те, прокуни ми овај народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'А Валам одговори и рече слугама Валаковијем да ми да Валак кућу своју пуну сребра и злата, не бих могао преступити ријечи Господа Бога својега да учиним што мало или велико.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Али опет останите овдје и ви ову ноћ, да видим што ће ми сада казати Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'И дође Бог ноћу к Валаму и рече му: кад су дошли ти људи да те зову, устани, иди с њима, али што ти кажем оно да чиниш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'А ујутру уставши Валам осамари магарицу своју, и пође с кнезовима Моавским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Али се разгњеви Бог што он пође; и стаде анђео Господњи на пут да му не да; а он сјеђаше на магарици својој и имаше са собом два момка своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'А кад магарица видје анђела Господњега гдје стоји на путу с голијем мачем у руци, сврну магарица с пута и пође преко поља. А Валам је стаде бити да је врати на пут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'А анђео Господњи стаде на стазу међу виноградима, а бијаше зид и одовуд и одонуд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'И магарица видећи анђела Господњега приби се уз други зид, и притиште ногу Валамову о зид; а он је стаде опет бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Потом анђео Господњи отиде даље, и стаде у тјеснацу, гдје не бјеше мјеста да се сврне ни на десно ни налијево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'И магарица видећи анђела Господњега паде под Валамом, а Валам се врло разљути, и стаде бити магарицу својим штапом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Тада Господ отвори уста магарици, те она рече Валаму: шта сам ти учинила, те ме бијеш већ трећи пут?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'А Валам рече магарици: што ми пркосиш? да имам мач у руци, сад бих те убио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'А магарица рече Валаму: нијесам ли твоја магарица? јашеш ме од како сам постала твоја до данас; јесам ли ти кад тако учинила? А он рече: нијеси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Тада Господ отвори очи Валаму, који угледа анђела Господњега гдје стоји на путу с голијем мачем у руци. И он сави главу и поклони се лицем својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'И рече му анђео Господњи: зашто си био магарицу своју већ три пута? ево ја изидох да ти не дам, јер твој пут није мени по вољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Кад ме угледа магарица, она се уклони испред мене већ три пута; а да се није уклонила испред мене, тебе бих већ убио а њу бих оставио у животу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'А Валам рече анђелу Господњему: згријешио сам, јер нијесам знао да ти стојиш преда мном на путу; ако теби није по вољи, ја ћу се вратити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'А анђео Господњи рече Валаму: иди с тијем људима, али само оно говори што ти ја кажем. Тада Валам отиде с кнезовима Валаковим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'А кад чу Валак да иде Валам, изиде му на сусрет у град Моавски на међи Арнонској накрај међе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'И рече Валак Валаму: нијесам ли слао к теби и звао те? зашто ми не дође? еда ли те не могу даривати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'А Валам рече Валаку: ево сам дошао к теби; али хоћу ли моћи што говорити? Што ми Бог метне у уста, оно ћу говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'И отиде Валам с Валаком, и дођоше у град Узот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'И накла Валак волова и оваца, и посла Валаму и кнезовима, који бијаху с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'А ујутру узе Валак Валама и одведе га на висину Валову, и оданде му показа један крај народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'И рече Валам Валаку: начини ми овдје седам олтара, и приправи ми овдје седам телаца и седам овнова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'И учини Валак како му рече Валам; и принесе Валак с Валамом на сваком олтару по једно теле и овна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Па рече Валам Валаку: стој код своје жртве паљенице; а ја идем еда бих се срео с Господом, па што ми јави казаћу ти. И он отиде сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'И срете Бог Валама, а он му рече: седам олтара спремих, и принесох по теле и овна на сваком олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'А Господ метну ријечи у уста Валаму, и рече: врати се к Валаку и тако му реци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'И врати се к њему, а он стајаше код жртве своје паљенице и сви кнезови Моавски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'А он отвори причу своју, и рече: из Арама доведе ме Валак цар Моавски с планине источне, говорећи: ходи, прокуни ми Јакова, ходи, наружи Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Како бих клео онога кога не куне Бог? или како бих ружио онога кога Господ не ружи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Јер сврх стијена видим га, и с хумова гледам га. Гле, овај ће народ наставати сам, и с другим народима неће се помијешати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Ко ће избројити прах Јаковљев и број од четврти Израиља? Да бих ја умро смрћу праведничком, и крај мој да би био као њихов!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Тада рече Валак Валаму: шта то радиш од мене? Ја те дозвах да прокунеш непријатеље моје, а гле, ти благосиљаш једнако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'А он одговори и рече: зар нећу пазити и говорити оно што ми је Господ метнуо у уста?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Тада му рече Валак: ходи са мном на друго мјесто, одакле ћеш га видјети; само му крај видиш, а свега га не видиш; прокуни ми га оданде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'И доведе га у поље Зофим, наврх Фазге, и начини седам олтара, и принесе на сваком олтару по једно теле и овна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Тада Валам рече Валаку: стој ту код жртве своје паљенице, а ја идем онамо на сусрет Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'И срете Господ Валама, и метну му ријеч у уста, и рече: врати се к Валаку, и тако говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'И дође к њему, а он стајаше код жртве своје паљенице и с њим кнезови Моавски; и рече Валак: шта вели Господ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'А он отвори причу своју, и рече: устани Валаче, и послушај, чуј ме сине Сефоров!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Бог није човјек да лаже, ни син човјечји да се покаје. Што каже неће ли учинити, и што рече неће ли извршити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Гле, примих да благословим; јер је он благословио, а ја нећу порећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Не гледа на безакоње у Јакову ни на неваљалство у Израиљу; Господ је његов с њим, и граја у њему као цар кад надвлада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Бог га је извео из Мисира, он му је као снага једнорогова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Јер нема чини на Јакова ни врачања на Израиља; у ово доба говориће се о Јакову и о Израиљу, што је учинио Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Ево, народ ће устати као силан лав, и као лавић скочиће; неће лећи докле не поједе лова и попије крви побијенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Тада рече Валак Валаму: немој га ни клети ни благосиљати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'А Валам одговори Валаку: нијесам ли ти казао да ћу чинити што ми год Господ каже?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'А Валак рече Валаму: ходи, одвешћу те на друго мјесто; да ако Богу буде воља да ми га оданде прокунеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'И одведе Валак Валама наврх Фегора, који гледа у пустињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'И рече Валам Валаку: начини ми овдје седам олтара, и приправи ми овдје седам телаца и седам овнова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'И учини Валак како рече Валам и принесе жртву по теле и овна на сваком олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'И видјевши Валам да је Божја воља да благосиља Израиља, не хтје више ни ићи као прије по врачање, него се окрете лицем к пустињи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'И подигавши очи своје угледа Израиља гдје стоји по племенима својим; и дух Божји дође на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'И отвори причу своју, и рече: каже Валам син Веоров; каже човјек којему су отворене очи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Каже онај који чује ријечи Божје, који види утвару Свемогућега, који кад падне отворене су му очи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Како су лијепи шатори твоји, Јакове, и колибе твоје, Израиљу!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Пружили су се као потоци, као вртови крај ријеке, као мирисава дрвета која је посадио Господ, као кедри на води.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Потећи ће вода из виједра његова, и сјеме ће његово бити међу великим водама, и цар ће се његов подигнути сврх Агага, и царство ће се његово узвисити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Бог га је извео из Мисира, и он му је као снага једнорогова; појешће народе који су му непријатељи, и кости ће њихове потрти, и стријелама својим постријељати их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Спустио се, лежи као лавић и као љути лав; ко ће га пробудити? Ко тебе благосиља, биће благословен; а ко тебе куне, биће проклет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Тада се разгњеви Валак на Валама, и пљесну се рукама, и рече Валак Валаму: дозвах те да прокунеш непријатеље моје, а ти си благословио ето већ три пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Одлази у своје мјесто; рекох да ћу те даривати, а ето Господ не да ти дара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'А Валам рече Валаку: нијесам ли и посланицима твојим које си послао к мени рекао говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Да ми да Валак кућу своју пуну сребра и злата, не бих могао преступити ријечи Господње да учиним што добро или зло од себе; што каже Господ оно ћу казати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Ја сада ево идем к народу својему, али да ти кажем шта ће тај народ учинити народу твојему најпослије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Потом отвори причу своју, и рече: каже Валам син Веоров, каже човјек коме су отворене очи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Каже који чује ријечи Божје, и који зна знање о Вишњем, и који види утвару Свемогућега и кад падне отворене су му очи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Видим га, али не сад; гледам га, али не изблиза; изаћи ће звијезда из Јакова и устаће палица из Израиља, која ће разбити кнезове Моавске и разорити све синове Ситове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'И Едома ће освојити и Сира ће освојити непријатељи његови; јер ће Израиљ радити јуначки.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'И владаће који је од Јакова, и затрће остатак од града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'А угледав Амалика, отвори причу своју, и рече: Амалик је почетак народима, али ће најпослије пропасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'А угледав Кенеја, отвори причу своју, и рече: тврд ти је стан, и на стијени си савио гнијездо своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Али ће бити изагнан Кенеј; Асур ће га заробити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'И опет отвори причу своју, и рече: јаох! ко ће бити жив кад то учини Бог!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'И лађе из земље Китимске допловиће и досадиће Асирцима и досадиће Јеврејима; али ће и сами пропасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Потом уставши Валам отиде, и врати се у своје мјесто; и Валак отиде својим путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'И живљаше Израиљ у Ситиму, и народ стаде чинити прељубу са кћерима Моавским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Оне позиваху народ на жртве својих богова, и народ јеђаше, и клањаше се боговима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'И Израиљ приону уз Велфегора; и разгњеви се Господ на Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'И рече Господ Мојсију: узми све кнезове народне, и објеси их Господу према сунцу, да се одврати гњев Господњи од Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'И рече Мојсије судијама Израиљевијем: побијте сваки своје који су прионули уз Велфегора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'И гле, један између синова Израиљевијех дође и доведе к браћи својој једну Мадијанку на очи Мојсију и на очи свему збору синова Израиљевијех; а они заплакаше на вратима шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'А кад то видје Финес син Елеазара сина Арона свештеника, уста исред збора и узе копље у руку;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'И уђе за човјеком Израиљцем у шатор, и прободе их обоје, човјека Израиљца и ону жену, кроз трбух, и преста погибија међу синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'И изгибе их од те погибије двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Тада рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Финес син Елеазара сина Арона свештеника одврати гњев мој од синова Израиљевијех отворивши ревност за ме међу њима, да не бих истријебио синове Израиљеве у ревности својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Зато му кажи: ево дајем му свој завјет мирни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'И имаће он и сјеме његово након њега завјет свештенства вјечнога, јер ревнова за Бога својега и очисти синове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'А човјеку Израиљцу убијеноме, који би убијен с Мадијанком, бјеше име Замрије син Салмонов, кнез од дома оца својега од племена Симеунова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'А убијеној жени Мадијанци бјеше име Хазвија кћи Сура кнеза народнога у дому оца својега међу Мадијанцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'И рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Завојштите на Мадијанце, и бијте их;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Јер они завојштише на вас пријеварама својим, и претворише вас Велфегором и Хазвијом кћерју кнеза Мадијанскога, сестром својом, која би убијена у дан погибије која дође с Фегора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'А послије те погибије рече Господ Мојсију и Елеазару сину Аронову свештенику говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Избројте сав збор синова Израиљевијех од двадесет година и више по домовима отаца њиховијех, све који могу ићи на војску у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'И рече им Мојсије и Елеазар свештеник у пољу Моавском на Јордану према Јерихону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Да се изброје од двадесет година и више, како заповједи Господ Мојсију и синовима Израиљевијем, који изађоше из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Рувим бјеше првенац Израиљев; а синови Рувимови: од Еноха породица Енохова; од Фалуја породица Фалујева;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Од Асрона породица Асронова, од Хармије породица Хармијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'То су породице Рувимове; а избројенијех бјеше међу њима четрдесет и три тисуће и седам стотина и тридесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Син Фалујев бјеше Елијав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'А синови Елијавови: Намуило и Датан и Авирон. Овај Датан и овај Авирон који бијаху од онијех што се сазиваху на збор, усташе на Мојсија и Арона у буни Корејевој, кад бјеше буна на Господа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'И земља отворивши уста своја прождрије њих и Кореја, и изгибе та гомила, и спали их огањ двјеста и педесет људи, који посташе углед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'А синови Корејеви не погибоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Синови Симеунови по породицама својим: од Намуила породица Намуилова; од Јамина породица Јаминова; од Јахина породица Јахинова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Од Заре породица Зарина, од Саула породица Саулова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'То су породице Симеунове; од њих бјеше двадесет и двије тисуће и двије стотине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'А синови Гадови по породицама својим: од Сифона породица Сифонова; од Агија породица Агијева; од Сунија и породица Сунијева;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Од Азена породица Азенова; од Ирија породица Иријева;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Од Арода породица Ародова; од Арилија породица Арилијева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'То су породице синова Гадовијех, а међу њима бјеше избројенијех четрдесет тисућа и пет стотина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Синови Јудини: Ир и Авнан; али умријеше Ир и Авнан у земљи Хананској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Бијаху пак синови Јудини по породицама својим: од Силома породица Силомова; од Фареса породица Фаресова; од Заре породица Зарина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'А синови Фаресови бјеху: од Асрона породица Асронова; од Јамуила породица Јамуилова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'То су породице Јудине, а међу њима бјеше избројенијех седамдесет и шест тисућа и пет стотина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'А синови Исахарови по породицама својим: од Толе породицаТолина; од Фуве породица Фувина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Од Јасува породица Јасувова; од Амрама породица Амрамова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'То су породице Исахарове; а међу њима бјеше избројенијех шездесет и четири тисуће и три стотине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Синови Завулонови по породицама својим: од Сареда породица Саредова; од Алона породица Алонова; од Алила породица Алилова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'То су породице Завулонове, а међу њима бјеше избројенијех шездесет тисућа и пет стотина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Синови Јосифови по породицама својим: Манасија и Јефрем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Синови Манасијини: од Махира породица Махирова; а Махир роди Галада, од којега је породица Галадова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Ово су синови Галадови: од Ахијезера породица Ахијезерова; од Хелека породица Хелекова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Од Есрила породица Есрилова; од Сихема породица Сихемова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Од Симаера породица Симаерова; од Офера породица Оферова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'А Салпад син Оферов немаше синова него кћери, којима су имена Мала и Нуја и Егла и Мелха и Терса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'То су породице Манасијине, а од њих бјеше избројенијех педесет и двије тисуће и седам стотина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Синови пак Јефремови по породицама својим: од Сутала породица Суталова; од Вехера породица Вехерова; од Тахана породица Таханова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'А ово су синови Суталови: од Ерана породица Еранова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'То су породице синова Јефремовијех; а међу њима бјеше избројенијех тридесет и двије тисуће и пет стотина. То су синови Јосифови по породицама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'А синови Венијаминови по породицама својим: од Веле породица Велина; од Асвила породица Асвилова; од Ахирама породица Ахирамова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Од Суфама породица Суфамова; од Уфама породица Уфамова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'А Велини синови бјеху: Адер и Наман; од Адера породица Адерова; од Намана породица Наманова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'То су синови Венијаминови по породицама својим, а међу њима бјеше избројенијех четрдесет и пет тисућа и шест стотина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'А ово су синови Данови по породицама својим: од Самеја породица Самејева; то је род Данов по породицама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'У свијем породицама Самејевијем бјеше избројенијех шездесет и четири тисуће и четири стотине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Синови Асирови по породицама својим: од Јамина породица Јаминова; од Јесуја породица Јесујева; од Верија породица Веријина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Синови Веријини: од Ховера породица Ховерова; од Мелхила породица Мелхилова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'А кћери Асировој бјеше име Сара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'То су породице синова Асировијех; а међу њима бјеше избројенијех педесет и три тисуће и четири стотине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Синови Нефталимови по породицама својим: од Асила породица Асилова; од Гунија породица Гунијева;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Од Јесера породица Јесерова; од Селима породица Селимова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'То је род Нефталимов по породицама својим, а међу њима бјеше избројених четрдесет и пет тисућа и четири стотине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'То су избројени међу синовима Израиљевијем, шест стотина и једна тисућа и седам стотина и тридесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'А Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Тијем нека се подијели земља у нашљедство према броју имена;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Којих има више, подај им веће нашљедство, а којих има мање, њима мање; сви према броју избројенијех својих нека имају нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Али ждријебом нека се подијели земља: по именима племена отаца својих нека добију нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Ждријебом нека се подијели свакоме племену, било велико или мало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'А ово су избројени између Левита по породицама својим: од Гирсона породица Гирсонова; од Ката породица Катова; од Мерарија породица Мераријева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Ово су породице Левијеве: породица Ловенијева, породица Хевронова, породица Малијева, породица Мусијева, породица Корејева. А Кат је родио Амрама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'А име је жени Амрамовој Јохаведа, кћи Левијева, која му се родила у Мисиру; а она роди Амраму Арона и Мојсија, и Марију сестру њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'А Арону се роди Надав и Авијуд и Елеазар и Итамар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Али Надав и Авијуд погибоше кад принесоше туђ огањ пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'И бјеше их избројенијех двадесет и три тисуће, свега мушкиња од једнога мјесеца и више; и не бише бројени међу синове Израиљеве, јер им није дано нашљедство међу синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'То су избројени, кад Мојсије и Елеазар свештеник избројише синове Израиљеве у пољу Моавском на Јордану према Јерихону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'А међу њима не бјеше ниједан од онијех које избројише Мојсије и Арон свештеник кад бројише синове Израиљеве у пустињи Синајској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Јер Господ бјеше рекао за њих: помријеће у пустињи. И не оста их ни један осим Халева сина Јефонијина и Исуса сина Навина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Тада дођоше кћери Салпада сина Офера сина Галада сина Махира сина Манасијина, од племена Манасије сина Јосифова, а имена им бјеху Мала, Нуја, Егла, Мелха и Терса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'И стадоше пред Мојсија и пред Елеазара свештеника и пред кнезове и сав збор на вратима шатора од састанка, и рекоше:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Отац наш умрије у пустињи, али не бјеше у друштву с онима који се побунише на Господа у буни Корејевој, него умрије од гријеха својега, а не остави синова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Зашто да се истријеби име оца нашега из породице његове зато што није имао сина? Дај нам нашљедство међу браћом оца нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'И изнесе Мојсије ствар њихову пред Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'А Господ рече Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Право говоре кћери Салпадове; подај им право да имају нашљедство међу браћом оца својега, и пренеси нашљедство оца њихова на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'А синовима Израиљевијем кажи и реци: кад ко умре а нема сина, онда пренесите нашљедство његово на кћер његову;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Ако ли ни кћери нема, онда подајте нашљедство његово браћи његовој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Ако ли ни браће нема, онда подајте нашљедство његово браћи оца његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Ако ли нема ни браће очине, онда подајте нашљедство његово оному ко му је најближи у роду његову, и нека је његово. И то нека буде синовима Израиљевијем закон за суђење, како заповједи Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Још рече Господ Мојсију: изиди на гору ову Аваримску, и види земљу коју сам дао синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'И кад је видиш, прибраћеш се к роду својему и ти, као што се прибрао Арон брат твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Јер не послушасте ријечи моје у пустињи Сину у свађи народној, кад је требало да ме прославите на води пред очима њиховијем. То је вода од свађе у Кадису у пустињи Сину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'И рече Мојсије Господу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Господе Боже духовима и сваком тијелу, постави човјека над овијем збором,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'Који ће излазити пред њима и који ће долазити пред њима, који ће их изводити, и опет доводити, да не би био збор Господњи као овце које немају пастира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'А Господ рече Мојсију: узми к себи Исуса сина Навина, човјека у ком је дух мој, и метни руку своју на њ,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'И изведи га пред Елеазара свештеника и пред сав збор, и подај му заповјести пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'И подај му од славе своје, да га слуша сав збор синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'И нека стаје пред Елеазара свештеника да га пита за суд Урим пред Господом; по заповијести његовој нека полазе и по заповијести његовој нека долазе он и сви синови Израиљеви с њим и сав збор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'И учини Мојсије како му заповједи Господ; и узев Исуса постави га пред Елеазара свештеника и пред сав збор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'И метну руке своје на њ, и даде му заповијести, како бјеше заповједио Господ преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Заповједи синовима Израиљевијем, и реци им: приносе моје, хљеб мој, жртве што ми се сажижу за угодни мирис, пазите да ми приносите на вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Реци им дакле: ово је жртва огњена што ћете приносити Господу: два јагњета од године здрава, сваки дан на жртву паљеницу без престанка:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Једно јагње принеси ујутру, а друго јагње принеси увече,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'И десетину ефе бијелога брашна за дар смијешана с четвртином ина чистога уља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'То је жртва паљеница свагдашња, која би принесена на гори Синајској за мирис угодни, жртва огњена Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'И наљев њезин да буде четврт ина на свако јагње; у светињи приноси наљев добра пића Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'А друго јагње принеси увече; дар као ујутру и наљев његов принеси за жртву огњену, за угодни мирис Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'А у суботу два јагњета од године здрава, и двије десетине бијелога брашна смијешана с уљем за дар с наљевом његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'То је суботна жртва паљеница сваке суботе, осим свагдашње жртве паљенице и наљева њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'И у почетак мјесеца својих приносите Господу жртву паљеницу, по два телета и једнога овна и седам јагањаца од године здравијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'И три десетине бјелога брашна помијешана с уљем за дар на свако теле, и двије десетине бијелога брашна помијешана с уљем за дар на овна;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'И по једну десетину бијелога брашна помијешана с уљем за дар на свако јагње; то је жртва паљеница на угодни мирис, жртва огњена Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'А наљев њихов да буде вина по ина на теле, трећина ина на овна, и четврт ина на јагње. То је жртва паљеница у почетак мјесеца, свакога мјесеца у години.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'И јарца једнога за гријех, осим свагдашње жртве паљенице, приносите Господу с наљевом његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'А првога мјесеца четрнаести дан да је пасха Господу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'А петнаести дан тога мјесеца празник: седам дана једите пријесне хљебове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Први дан нека је сабор свети; никакога посла ропскога не радите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Него принесите Господу жртву паљеницу, два телета и једнога овна и седам јагањаца од године, све да вам је здраво;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'А дар уз њих бјелога брашна помијешана с уљем три десетине уза свако теле и двије десетине уз овна принесите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'По једну десетину принесите уза свако јагње од онијех седам јагањаца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'И једнога јарца за гријех, ради очишћења вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'То принесите осим јутрење жртве паљенице, која је жртва свагдашња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Тако приносите свако дан за онијех седам дана, да буде јело, жртва огњена на угодни мирис Господу, осим свагдашње жртве паљенице и њезина наљева приносите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'И седми дан да имате свети сабор; посла ропскога ниједнога не радите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'И на дан првина, кад приносите нов дар Господу послије својих недјеља, да имате сабор свети, ниједнога посла ропскога не радите;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Него принесите жртву паљеницу за угодни мирис Господу, два телета, једнога овна седам јагањаца од године;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'И дар уз њих: бијелога брашна помијешана с уљем по три десетине уз теле, двије десетине уз овна,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'По једну десетину уза свако јагње од онијех седам јагањаца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Једнога јарца, ради очишћења вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Принесите то, осим свагдашње жртве паљенице и дара њезина; а све нека вам је здраво с наљевом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'А седмога мјесеца први дан да имате свети сабор; посла ропскога ниједнога не радите; то да вам је трубни дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'И принесите жртву паљеницу за мирис угодни Господу, једно теле, једнога овна, седам јагањаца од године здравијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'А дар уз њих бијелога брашна смијешана с уљем три десетине уз теле и двије десетине уз овна,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'И по једну десетину уза свако јагње од седам јагањаца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'И једнога јарца за гријех, ради очишћења вашега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Осим жртве паљенице у почетку мјесеца и дара њезина, и осим свагдашње жртве паљенице и дара њезина и наљева њиховијех по уредби њиховој, за мирис угодни, за жртву огњену Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'И десети дан тога мјесеца седмога да имате свети сабор; и мучите душе своје; не радите никакога посла;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Него принесите Господу за мирис угодни жртву паљеницу, једно теле, једнога овна, седам јагањаца од године, а нека вам је здраво;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'И дар уз њих бијелога брашна помијешана с уљем три десетине уз теле, двије десетине уз овна,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'По једну десетину уза свако јагње од онијех седам јагањаца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Јарца једнога за гријех, осим жртве за гријех ради очишћења, и осим свагдашње жртве паљенице и дара њезина и наљева њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'И петнаести дан тога мјесеца седмога да имате свети сабор; ниједнога посла ропскога не радите; него празнујте празник Господу седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'И принесите жртву паљеницу, огњену жртву за угодни мирис Господу, тринаест телаца два овна, четрнаест јагањаца од године, а нека су здрави;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'И дар уз њих брашна бијелога смијешана с уљем по три десетине уза свако теле од тринаест телаца, по двије десетине уза свакога овна од она два овна,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'И по једну десетину уза свако јагње од онијех четранаест јагањаца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'И једнога јарца за гријех, осим свагдашње жртве паљенице и дара њезина и наљева њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'А други дан дванаест телаца, два овна, четранаест јагањаца од године здравијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'И дар њихов и наљев њихов, уз теоце, уз овнове и уз јагањце, по броју њихову, како је уређено;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'И јарца једнога за гријех, осим свагдашње жртве паљенице и дара њезина и наљева њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'А трећи дан једанаест телаца, два овна и четранаест јагањаца од године здравијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'И дарове њихове и наљеве њихове, уз теоце, уз овнове и уз јагањце, по броју њихову, како је уређено;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'И једнога јарца за гријех, осим свагдашње жртве паљенице и дара њезина и наљева њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'А четврти дан десет телаца, два овна, четрнаест јагањаца од године здравијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'И дар њихов и наљеве њихове, уз теоце, уз овнове и уз јагањце, по броју њихову, како је уређено;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'И једнога јарца за гријех, осим свагдашње жртве паљенице и дара њезина и наљева њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'А пети дан девет телаца, два овна, четрнаест јагањаца од године здравијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'И дар њихов и наљеве њихове, уз теоце, уз овнове и уз јагањце, по броју њихову, како је уређено;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'И једнога јарца за гријех, осим свагдашње жртве паљенице и дара њезина и наљева њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'А шести дан осам телаца, два овна, четрнаест јагањаца од године здравијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'И дар њихов и наљеве њихове, уз теоце, уз овнове и уз јагањце, по броју њихову, како је уређено;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'И једнога јарца за гријех, осим свагдашње жртве паљенице и дара њезина и наљева њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'А седми дан седам телаца, два овна, четрнаест јагањаца од године здравијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'И дар њихов и наљеве њихове, уз теоце, уз овнове и уз јагањце, по броју њихову, како је уређено;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'И јарца за гријех, осим свагдашње жртве паљенице и дара њезина и наљева њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'А осми дан да вам је празник; ниједнога посла ропскога не радите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Него принесите жртву паљеницу, жртву огњену за угодни мирис Господу, једно теле, једнога овна, седам јагањаца од године здравијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'И дар њихов и наљеве њихове, уз теле, уз овна и уз јагањце, по броју њихову, како је уређено;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'И једнога јарца за гријех, осим свагдашње жртве паљенице и дара њезина и наљева њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'То приносите Господу на празнике своје, осим онога што бисте по завјету или од своје воље принијели за жртве паљенице или дарове или наљеве или жртве захвалне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'И каза Мојсије синовима Израиљевијем све што заповједи Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'И рече Мојсије кнезовима од племена синова Израиљевијех говорећи: ово је заповједио Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Кад који човјек учини завјет Господу, или се закуне везавши се душом својом, нека не погази ријечи своје, него нека учини све што изађе из уста његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'А кад жена учини завјет Господу или се веже у младости својој, докле је у кући оца својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'И чује отац њезин за завјет њезин или како се везала душом својом, па јој отац не рече ништа, онда да су тврди сви завјети њезини, и све чим је везала душу своју да је тврдо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Ако ли отац њезин порече то онај дан кад чује, завјети њезини и чим је год везала душу своју, ништа да није тврдо; и Господ ће јој опростити, јер отац њезин порече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Ако ли се уда па има на себи завјет или изрече што на уста своја чим би се везала,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'А муж њезин чувши не рече јој ништа онај дан кад чује, онда да су тврди завјети њезини, и тврдо да је све чим је везала душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Ако ли муж њезин кад чује онај дан порече, укида с завјет који је био на њој или што је изрекла на уста своја те се везала; и Господ ће јој опростити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'А завјет који учини удовица или пуштеница, и све чим веже душу своју, да јој је тврдо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Али ако буде у кући мужа својега учинила завјет и за што везала душу своју заклетвом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'И муж њезин чувши оћути и не порече, тада да су тврди сви завјети њезини, и да је тврдо све за што је везала душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Ако ли то порече муж њезин онај дан кад чује, сваки завјет који би изашао из уста њезинијех и све чим би везала душу своју да није тврдо; муж је њезин порекао, и Господ ће јој опростити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Сваки завјет и све за што би се везала заклетвом да мучи душу своју, муж њезин потврђује и укида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Ако би муж њезин од дана до дана ћутао, онда потврђује све завјете њезине и све за што би се везала; потврђује, јер јој не порече у онај дан кад чу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Ако ли порече пошто чује, сам ће носити гријех њезин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 17, 'Ово су наредбе, које заповједи Господ Мојсију за мужа и жену, за оца и кћер у младости њезиној, докле је у кући оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Опет рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Освети синове Израиљеве на Мадијанцима, пак ћеш се онда прибрати к роду својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'И Мојсије рече народу говорећи: опремите између себе људе на војску да иду на Мадијанце да учине освету Господњу на Мадијанцима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'По тисућу од племена, од свакога племена Израиљева опремите на војску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'И дадоше од тисућа Израиљевијех по тисућу од свакога племена, дванаест тисућа опремише на војску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'И посла Мојсије по тисућу од свакога племена на војску, и с њима Финеса сина Елеазара свештеника, и у њега бјеху суди свети и трубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'И завојштише на Мадијанце, како заповједи Господ Мојсију, и побише све мушкиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Побише и цареве Мадијанске, с другима које им побише, Евина и Рокома и Сура и Ура и Ровока, пет царева Мадијанских, и Валама сина Веорова убише мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'И заробише синови Израиљеви жене Мадијанке и дјецу њихову, и заплијенише сву стоку њихову, крупну и ситну, и све благо њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'А мјеста њихова у којима живљаху и градове њихове све попалише огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'И све робље и сав плијен, људе и стоку, узеше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'И поведоше к Мојсију и Елеазару свештенику и ка збору синова Израиљевијех, и робље и остали плијен и добит у око на пољу Моавском, које је на Јордану према Јерихону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'А Мојсије и Елеазар свештеник и сви кнезови од збора изидоше им на сусрет из окола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'И Мојсије се разгњеви на војводе, на тисућнике и стотинаре, који се враћаху с војске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'И рече им Мојсије: а што остависте у животу све жене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Та оне по ријечи Валамовој навратише синове Израиљеве да згријеше Господу с Фегора, те дође она погибија на народ Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Зато сада побијте сву дјецу мушку, и све жене побијте, које су познале човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'А дјевојке, које не познаше човјека, оставите у животу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'А ви останите изван окола седам дана; сваки који је убио кога и који се дотакао убијенога очистите се трећи дан и седми дан, себе и робље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'И све хаљине и све ствари кожне и све што је од костријети и све судове дрвене очистите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'И рече Елеазар свештеник војницима, који бијаху ишли на војску: ово је наредба и закон што је Господ заповједио Мојсију:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Злато, сребро, мјед, гвожђе, коситер и олово,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'Што год подноси ватру, пропустите кроз ватру, и очистиће се, али пошто се очисти водом очишћења; а што год не подноси ватре, пропустите кроз воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'И оперите хаљине своје седми дан, и бићете чисти; и онда ћете ући у око.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Изброј све што је заплијењено, људе и стоку, ти и Елеазар свештеник и поглавари од племена народнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'И раздијели све заплијењено на двоје: на војнике који су ишли на војску и на сав збор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'И узми дио за Господа од војника који су ишли на војску, по једну душу од педесет, и од људи и од говеда и од магараца и од оваца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Од њихове половине то узмите, и подајте Елеазару свештенику за принос Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'И од половине која допаде синовима Израиљевијем узми по једно од педесет, и од људи и од говеда и од магараца и од оваца и од сваке стоке, и то подај Левитима који раде што треба за шатор Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'И учини Мојсије и Елеазар свештеник како заповједи Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'И бјеше плијена, што оста од плијена који заплијени војска: шест стотина и седамдесет и пет тисућа оваца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'И седамдесет и двије тисуће говеда,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'И шездесет и једна тисућа магараца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'И женскиња што не бјеше познало човјека, свега тридесет и двије тисуће душа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'А у половини, у дијелу онијех који бијаху ишли на војску, бјеше на број три стотине и тридесет и седам тисућа и пет стотина оваца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'А од тога дио Господу бјеше шест стотина и седамдесет и пет оваца:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'И тридесет и шест тисућа говеда, а од тога дио Господу седамдесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'И тридесет тисућа и пет стотина магараца, а од тога дио Господу шездесет и један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'И шеснаест тисућа душа људских, а од тога дио Господу тридесет и двије душе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'И даде Мојсије Елеазару свештенику дио за принос Господу, као што му заповједи Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'А од друге половине, која допаде синовима Израиљевијем, коју узе Мојсије од људи који бјеху ишли на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(А и у тој половини, која допаде збору, бјеше три стотине и тридесет и седам тисућа и пет стотина оваца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'Тридесет и шест тисућа говеда,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'Тридесет тисућа и пет стотина магараца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'И шеснаест тисућа душа људских.)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Од те половине, која допаде синовима Израиљевијем, узе Мојсије по једно од педесет, и од људи и од стоке, и даде Левитима који раде што треба за шатор Господњи, као што му Господ заповједи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'И приступише к Мојсију војводе, тисућници и стотинари,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'И рекоше му: слуге твоје пребројише војнике који бијаху под нашом руком, и ниједнога није мање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Зато приносимо Господу принос, сваки што је ко задобио, златнијех заклада, копача, наруквица, прстена, ободаца и ланчића, да би се очистиле душе наше пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'И узе Мојсије и Елеазар свештеник од њих злато, свакојаке закладе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'А бјеше свега злата принесенога, што принесоше Мојсију тисућници и стотинари, шеснаест тисућа и седам стотина и педесет сикала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'А војници задржаше себи што који бјеше заплијенио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'И узевши Мојсије и Елеазар злато од тисућника и стотинара, унесоше га у шатор од састанка за спомен синовима Израиљевијем пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'А синови Рувимови и синови Гадови имаху врло много стоке, и видјеше земљу Јазирску и земљу Галадску да је добра за стоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'И дошавши синови Гадови и синови Рувимови рекоше Мојсију и Елеазару свештенику и кнезовима од збора говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Атарот и Девон и Јазир и Намра и Есевон и Елеалија и Севама и Навав и Веан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'Та је земља, коју Господ покори збору Израиљском, добра за стоку, а слуге твоје имају стоке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Ако смо, рекоше, нашли милост пред тобом, нека се та земља даде слугама твојим у нашљедство, немој нас водити преко Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'А Мојсије рече синовима Гадовијем и синовима Рувимовијем: браћа ће ваша ићи на војску, а ви хоћете овдје да останете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Зашто обарате срце синовима Израиљевијем да не пријеђу у земљу коју им је дао Господ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Тако су учинили оци ваши, кад их послах из Кадис-Варније да уходе земљу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'И отидоше до потока Есхола, и уходише земљу; и оборише срце синовима Израиљевијем да не иду у земљу коју им даде Господ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'И разгњеви се онда Господ, и закле се говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Неће ти људи који изађоше из Мисира, од двадесет година и више, видјети земље за коју се заклех Авраму, Исаку и Јакову, јер се не држаше мене сасвијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Осим Халева сина Јефонијина Кенезеја и Исуса сина Навина, јер се сасвијем држаше Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'И разгњеви се Господ на Израиља, и учини те се потуцаше по пустињи четрдесет година, докле не помрије сав онај нараштај који чињаше зло пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'А ви сада изађосте на мјесто отаца својих, род гријешних људи, да умножавате жестину гњева Господњега на Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Ако се одвратите од њега, он ће га још оставити у пустињи, и тако ћете упропастити сав онај народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'А они приступише опет к њему, и рекоше му: ми смо ради само торове начинити овдје за стада своја и градове за дјецу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'А сами ћемо наоружани јуначки поћи пред синовима Израиљевијем, докле их не одведемо на њихово мјесто; а наша дјеца нека стоје у градовима тврдијем ради становника те земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Нећемо се вратити кућама својим докле синови Израиљеви не приме сваки своје нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Нити ћемо узети нашљедства с њима с ону страну Јордана ни даље, ако нам допадне нашљедство с ову страну Јордана према истоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Тада им рече Мојсије: ако ћете учинити тако и ићи под оружјем пред Господом на војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'Ако сваки од вас под оружјем пријеђе преко Јордана пред Господом, докле не отјера испред себе непријатеља својих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'И докле се не покори земља пред Господом, па се онда вратите и не згријешите Господу ни Израиљу, онда ће ова земља припасти вама у нашљедство пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Ако ли не учините тако, гле, згријешићете Господу, и знајте да ће вас гријех ваш стићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Градите себи градове за дјецу своју и торове за стоку своју; и што је изашло из уста ваших, учините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'И рекоше Мојсију синови Гадови и синови Рувимови говорећи: слуге ће твоје учинити како господар наш заповиједа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Дјеца наша и жене наше, стада наша и сва стока наша овдје ће остати у градовима Галадским;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'А слуге ће твоје пријећи сваки наоружан, да се бије пред Господом, као што говори господар наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Тада Мојсије заповједи за њих Елеазару свештенику и Исусу сину Навину и главарима од домова отачких међу синовима Израиљевијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'И рече им: ако пријеђу синови Гадови и синови Рувимови с вама преко Јордана, сви оружани, да се бију пред Господом, и кад вам буде земља покорена, онда подајте њима земљу Галадску у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Ако ли не пријеђу с вама под оружјем, онда нека им буде нашљедство међу вама у земљи Хананској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'И одговорише синови Гадови и синови Рувимови говорећи: како је Господ казао слугама твојим тако ћемо учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Пријећи ћемо под оружјем пред Господом у земљу Хананску, а наше нашљедство да буде с ову страну Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'И даде Мојсије синовима Гадовијем и синовима Рувимовијем и половини племена Манасије сина Јосифова царство Сиона цара Аморејскога и царство Ога цара Васанскога, земљу и градове по међама њезинијем, градове оне земље унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'И саградише синови Гадови Девон и Атарот и Ароир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'И Атрот-Софан и Јазир и Јогвеју,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'И Вет-Нимру и Вет-Аран, градове тврде, и торове за стоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'А синови Рувимови саградише Есевон и Елеалију и Киријатајим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'И Навон и Велмеон предјенувши им имена, и Сивму; и надјеше друга имена градовима које саградише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'А синови Махира сина Манасијина отидоше у Галад, и узеше га, и изагнаше Амореје који бијаху ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'И Мојсије даде Галад Махиру сину Манасијину, који се ондје насели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'И Јаир син Манасијин отиде и узе села њихова и прозва их села Јаирова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'И Навав отиде и узе Кенат са селима његовијем, и прозва га Навав по имену својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Ово су путови синова Израиљевијех кад изађоше из земље Мисирске у четама својим под управом Мојсијевом и Ароновом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'И Мојсије пописа како изидоше и гдје стајаше по заповијести Господњој; и ово су путови њихови како путоваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Пођоше из Рамесе првога мјесеца петнаести дан, сјутрадан послије пасхе, и изидоше синови Израиљеви руком подигнутом пред очима свијех Мисираца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'А Мисирци погребаваху првенце које поби Господ међу њима, кад и на боговима њиховијем изврши Господ судове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'И отишавши синови Израиљеви из Рамесе стадоше у око у Сохоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'А из Сохота отишавши стадоше у око у Етаму, који је на крај пустиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'А из Етама отишавши савише к Ироту, који је према Велсефону, и стадоше у око пред Магдалом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'А од Ирота отишавши пријеђоше преко мора у пустињу, и ишавши три дана преко пустиње Етама стадоше у око у Мери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'А из Мере отишавши дођоше у Елим, гдје бијаше дванаест студенаца и седамдесет палмовијех дрвета, и ондје стадоше у око.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'А из Елима отишавши стадоше у око код Црвенога Мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'И отишавши од Црвенога Мора стадоше у око у пустињи Сину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'А из пустиње Сина отишавши стадоше у око у Рафаку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'А из Рафака отишавши стадоше у око у Елусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'А из Елуса отишавши стадоше у око у Рафидину, гдје немаше народ воде да пије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'А из Рафидина отишавши стадоше у око у пустињи Синајској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'А из пустиње Синајске отишавши стадоше у око у Киврот-Атави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'А из Киврот-Атаве отишавши стадоше у око у Асироту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'А из Асирота отишавши стадоше у око у Ратаму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'А из Ратама отишавши стадоше у око у Ремнон-Фаресу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'А из Ремнон-Фареса отишавши стадоше у око у Лемвону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'А из Лемвона отишавши стадоше у око у Ресану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'А из Ресана отишавши стадоше у око у Макелату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'А из Макелата отишавши стадоше у око код горе Сафера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'А од горе Сафера отишавши стадоше у око у Хараду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'А из Харада отишавши стадоше у око у Макидоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'А из Макидота отишавши стадоше у око у Катату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'А из Катата отишавши стадоше у око у Тарату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'А из Тарата отишавши стадоше у око у Метеку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'А из Метека отишавши стадоше у око у Аселмону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'А из Аселмона отишавши стадоше у око у Мосироту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'А из Мосирота отишавши стадоше у око у Ванакану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'А из Ванакана отишавши стадоше у око у планини Гададу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'А из планине Гадада отишавши стадоше у око у Етавати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'А из Етавате отишавши стадоше у око у Еврону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'А из Еврона отишавши стадоше у око у Гесион-Гаверу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'А из Гесион-Гавера отишавши стадоше у око у пустињи Сину, а то је Кадис.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'А из Кадиса отишавши стадоше у око код горе Ора не међи земље Едомске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'И изиде Арон свештеник на гору Ор по заповјести Господњој, и умрије ондје четрдесете године по изласку синова Израиљевијех из земље Мисирске, први дан петога мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'А Арону бјеше сто и двадесет и три године кад умрије на гори Ору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Тада чу Хананеј цар Арадски, који живљаше на југу у земљи Хананској, да иду синови Израиљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Потом отишавши од горе Ора стадоше у око у Селмону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'А из Селмона отишавши стадоше у око у Финону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'А из Финона отишавши стадоше у око у Овоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'А из Овота отишавши стадоше у око на хумовима Аваримским на међи Моавској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'А од тијех хумова отишавши стадоше у око у Девон-Гаду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'А из Девон-Гада отишавши стадоше у око у Гелмон-Девлатаиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'А из Гелмон-Девлатаима отишавши стадоше у око у планинама Аваримским према Нававу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'А из планина Аваримских отишавши стадоше у око у пољу Моавском на Јордану према Јерихону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'И стајаху у околу крај Јордана од Есимота до Вел-Сатима у пољу Моавском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'И рече Господ Мојсију у пољу Моавском на Јордану према Јерихону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Кажи синовима Израиљевијем и реци им: кад пријеђете преко Јордана у земљу Хананску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'Отјерајте од себе све који живе у оној земљи, и потрите све слике њихове резане, и све слике њихове ливене потрите, и све висине њихове оборите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'А кад их истјерате из земље, населите се у њој; јер сам вама дао ону земљу да је ваша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'И раздијелите је у нашљедство ждријебом на породице своје; којих има више, њима веће нашљедство подајте; а којих има мање, њима подајте мање нашљедство; које мјесто коме ждријебом допадне, оно нека му буде; на племена отаца својих раздијелите нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Ако ли не отјерате од себе онијех који живе у оној земљи, онда ће они које оставите бити трње очима вашима и остани вашим боковима, и пакостиће вам у земљи у којој ћете живјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'И што сам мислио учинити њима, учинићу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Заповједи синовима Израиљевијем и реци им: кад дођете у земљу Хананску, та ће вам земља припасти у нашљедство, земља Хананска с међама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Јужни крај да вам је од пустиње Сина, уз међу Едомску, и да вам је јужна међа од бријега сланога мора на исток;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'И та међа нека се савије од југа к Акравиму и иде до Сина, и нека се пружи од југа преко Кадис-Варне, а отуда нека изиде на село Адар и иде до Аселмона;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Потом нека се савије та међа од Аселмона до потока Мисирскога и иде до мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'А западна међа да вам буде велико море; то да вам је западна међа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'А сјеверна међа ово да вам буде: од великога мора повуците себи међу до горе Ора;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'А од горе Ора повуците себи међу како се иде у Емат, и та међа нека иде на Седад;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'И нека иде та међа до Зефрона, и крај нека јој буде код села Енана; то да вам буде сјеверна међа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'А с истока повуците себи међу од села Енана до Сефама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'А од Сефама нека иде та међа к Ривли, с истока Аину, и нека иде даље та међа докле дође до мора Хинерота к истоку;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'И нека се спусти та међа ка Јордану, и нека изађе на слано море. Та ће земља бити ваша с међама својим унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'И каза Мојсије синовима Израиљевијем говорећи: то је земља коју ћете добити у нашљедство ждријебом, за коју је заповједио Господ да је добије девет племена и по.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Јер племе синова Рувимовијех по породицама отаца својих, и племе синова Гадовијех по породицама отаца својих, и половина племена Манасијина примише своје нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Ова два племена и по примише нашљедство своје с ову страну Јордана према Јерихону с источне стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Опет рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Ово су имена људи који ће вам раздијелити у нашљедство земљу: Елеазар свештеник и Исус син Навин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'И по једнога кнеза из свакога племена узмите да дијели земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'А ово су имена тијех људи: од племена Јудина Халев син Јефонијин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Од племена синова Симеуновијех Самуило син Емијудов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Од племена Венијаминова Елдад син Хаслонов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Од племена синова Дановијех кнез Вокор син Јеклинов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Од синова Јосифовијех: од племена синова Манасијиних кнез Анило син Суфидов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Од племена синова Јефремовијех, кнез Камуило син Сафтанов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Од племена синова Завулоновијех кнез Елисафан син Харнахов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Од племена синова Исахаровијех кнез Фалтило син Озаинов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Од племена синова Асировијех кнез Ахиор син Селемијин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'И од племена Нефталимова кнез Фадаило син Амијудов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Овима заповједи Господ да раздијеле нашљедство синовима Израиљевијем у земљи Хананској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Још рече Господ Мојсију у пољу Моавском на Јордану према Јерихону говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Заповједи синовима Израиљевијем нека даду од нашљедства својега Левитима градове, гдје ће живјети; и подграђа око градова подајте им,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Да у градовима живе, а у подграђима њиховијем да им стоји стока и имање њихово и све животиње њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'А подграђа која дате Левитима нека буду на тисућу лаката далеко од зидова градских унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Зато измјерите иза свакога града на исток двије тисуће лаката, и на југ двије тисуће лаката, и на запад двије тисуће лаката, и на сјевер двије тисуће лаката, тако да град буде у сриједи. Толика нека буду подграђа њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'А од градова које дате Левитима одвојте шест градова за уточиште, да онамо утече ко би кога убио; и осим њих подајте им четрдесет и два града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Свега градова, које ћете дати Левитима да буде четрдесет и осам градова, сваки са својим подграђем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'А тијех градова што ћете дати од нашљедства синова Израиљевијех, од онијех који имају више подајте више, а од онијех који имају мање подајте мање; сваки према нашљедству које ће имати нека да од својих градова Левитима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Још рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Реци синовима Израиљевијем и кажи им: кад пријеђете преко Јордана у земљу Хананску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'Од градова који вам допадну одвојте градове за уточиште да у њих утече крвник који убије кога нехотице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'И ти ће вам градови бити уточишта од осветника, да не погине крвник докле не стане на суд пред збор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'И тако од тијех градова које дате шест градова биће вам уточишта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Три така града подајте с ову страну Јордана, а три града подајте у земљи Хананској, ти градови нека буду уточишта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Синовима Израиљевијем и дошљаку и странцу, који се бави међу њима, нека тијех шест градова буду уточишта, да утече у њих ко год убије кога нехотице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Али ако гвожђем удари кога, те онај умре, крвник је, нека се погуби таки крвник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'И ако каменом из руке, од којега може човјек погинути, удари кога, те онај умре, крвник је, нека се погуби таки крвник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Или ако дрветом из руке, од којега може човјек погинути, удари кога, те онај умре, крвник је, нека се погуби таки крвник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Осветник нека погуби крвника; кад га удеси, нека га погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Ако га из мржње тури, или се баци чим на њ навалице, те онај умре,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Или ако га из непријатељства удари руком, те онај умре, нека се погуби таки убојица, крвник је; осветник нека погуби тога крвника кад га удеси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Ако ли га нехотице тури без непријатељства, или се баци на њ чим нехотице,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Или каменом од којега може човјек погинути, ако се баци на њ нехотице, те онај умре, а није му непријатељ, нити му тражи зла,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'Тада да суди збор између убојице и осветника по овом закону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'И збор нека избави крвника из руке осветникове и врати га у уточиште његово, куда је утекао, и ондје нека остане докле не умре поглавар свештенички, који је помазан светим уљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Ако крвник како год изиде преко међе својега уточишта, у које је утекао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'И нађе га осветник преко међе уточишта његова, ако крвника убије осветник, неће бити крив за крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Јер у уточишту својем ваља да стоји докле не умре поглавар свештенички; па кад умре поглавар свештенички, онда треба да се врати крвник у земљу нашљедства својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Ово да вам је уредба за суђење од кољена до кољена по свијем становима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Ко би хтио погубити човјека, по свједоцима нека погуби крвника; али један свједок не може свједочити да се ко погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Не узимајте откупа за крвника, који заслужи смрт, него нека се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Ни од онога не узимајте откупа који утече у уточиште, да би се вратио да живи у својој земљи прије него умре свештеник;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Да не бисте скврнили земљу у којој сте, јер крв она скврни земљу, а земља се не може очистити од крви која се пролије на њој друкчије него крвљу онога који је пролије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Зато не скврните земље у којој наставате и у којој ја наставам, јер ја Господ наставам усред синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Тада приступише старјешине из породице синова Галада сина Махира сина Манасијина од племена синова Јосифовијех, и рекоше пред Мојсијем и пред кнезовима, главарима од домова отачких међу синовима Израиљевијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'И говорише: господару нашему заповједи Господ да подијели ждријебом земљу у нашљедство синовима Израиљевијем; и господар наш има заповијест од Господа да да нашљедство Салпада брата нашега кћерима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Ако се оне удаду за кога из другога племена синова Израиљевијех, онда ће се нашљедство њихово откупити од нашљедства отаца наших и додаће се нашљедству онога племена у које се удаду, и тако ће се дио наш окрњити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'И кад буде опросна година синовима Израиљевијем, опет ће остати нашљедство њихово с нашљедством онога племена у које се буду удале, и тако ће од нашљедства племена отаца наших остати откинуто нашљедство њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Тада заповједи Мојсије синовима Израиљевијем по заповијести Господњој говорећи: право говори племе синова Јосифовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Ово заповједи Господ за кћери Салпадове и рече: нека се удаду за кога им буде воља, али у породици племена својега нека се удаду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Да се не би преносило нашљедство синова Израиљевијех од једнога племена на друго; јер ће синови Израиљеви држати сваки нашљедство племена отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'И свака кћи у племенима синова Израиљевијех којој допадне нашљедство, нека се удаје за кога из породице племена оца својега, да би синови Израиљеви држали сваки нашљедство отаца својих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Да се не би преносило нашљедство од једнога племена синова Израиљевијех да држи своје нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Како заповједи Господ Мојсију, тако учинише кћери Салпадове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Јер Мала и Терса и Егла и Мелха и Нуја, кћери Салпадове, удадоше се за синове стричева својих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'У породице синова Манасије сина Јосифова удадоше се, и оста нашљедство њихово у племену породице оца њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'То су заповијести и закони, које заповједи Господ преко Мојсија синовима Израиљевијем у пољу Моавском на Јордану према Јерихону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Ово су ријечи које говори Мојсије свему Израиљу с ону страну Јордана, у пустињи, у пољу према Црвеноме мору, између Фарана и Тофола и Ловона и Асирота и Дизава,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Једанаест дана хода од Хорива преко горе Сира до Кадис-Варније.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'А бјеше четрдесете године први дан једанаестога мјесеца, кад Мојсије каза синовима Израиљевијем све што му бјеше заповједио Господ да им каже,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Пошто уби Сиона цара Аморејскога који живљасе у Есевону, и Ога цара Васанскога који живљаше у Астароту и у Едрајину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'С ону страну Јордана у земљи Моавској поче Мојсије казивати овај закон говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Господ Бог наш рече нам на Хориву говорећи: доста сте били на овој гори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Обрните се и подигните се и идите ка гори Аморејској и у сву околину њезину, у равнице и у брда и у долине, и на југ и на брегове морске, у земљу Хананску и на Ливан и до ријеке велике, ријеке Ефрата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Ето, дао сам вам земљу, уђите у њу, и узмите земљу, за коју се заклео Господ оцима вашим, Авраму, Исаку и Јакову, да ће им је дати и сјемену њихову након њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'И рекох вам онда говорећи: не могу вас носити сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Господ Бог ваш умножио вас је, и ето вас данас има много као звијезда небеских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Господ Бог отаца ваших да вас умножи још тисућу пута више, и да вас благослови као што вам је казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Како бих ја сам носио муке ваше, бремена ваша и распре ваше?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Дајте из племена својих људе мудре и вјеште и познате да вам их поставим за старјешине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Тада ми одговористе и рекосте: добро је да се учини што си казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Тада узевши старјешине од племена ваших, људе мудре и познате, поставих вам их за старјешине, за тисућнике и стотинаре и педесетаре и десетаре и управитеље по племенима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'И заповједих онда судијама вашим говорећи: саслушавајте распре међу браћом својом и судите право између човјека и брата његова и између дошљака који је с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Не гледајте ко је ко на суду, саслушајте и малога и великога, не бојте се никога, јер је суд Божији, а ствар која би вам била тешка изнесите преда ме да је чујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'И заповједих вам онда све што ћете чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Потом отишавши од Хорива пријеђосмо сву ону пустињу велику и страшну, коју видјесте, идући ка гори Аморејској, као што нам заповједи Господ Бог наш, и дођосмо до Кадис-Варније.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Тада вам рекох: дођосте до горе Аморејске, коју нам даје Господ Бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Гле, дао ти је Господ Бог твој ту земљу, иди и узми је, као што ти је рекао Господ Бог отаца твојих; не бој се, и не плаши се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'А ви сви дођосте к мени и рекосте: да пошљемо људе пред собом да нам уходе земљу, и да нам јаве за пут којим ћемо ићи и за градове у које ћемо доћи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'И то ми би по вољи, и узех између вас дванаест људи, из свакога племена по једнога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'И они се подигоше и изашавши на гору дођоше до потока Есхола, и уходише земљу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'И набраше рода оне земље и донесоше нам, и јавише нам говорећи: добра је земља, коју нам даје Господ Бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Али не хтјесте ићи него се супротисте заповијести Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'И викасте у шаторима својим говорећи: мрзи на нас Господ, зато нас изведе из земље Мисирске, да нас да у руке Аморејцима и да нас потре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Куда да идемо? браћа наша уплашише срце наше говорећи: народ је већи и виши од нас, градови су велики и ограђени до неба, па и синове Енакове видјесмо овдје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'А ја вам рекох: не плашите се и не бојте их се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Господ Бог ваш, који иде пред вама, он ће се бити за вас онако како вам је учинио у Мисиру на ваше очи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'И у пустињи, гдје си видио како те је носио Господ Бог твој, као што човјек носи сина својега, цијелијем путем којим сте ишли докле дођосте до овога мјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Али зато опет не вјеровасте Господу Богу својему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'Који иђаше пред вама путем тражећи вам мјесто гдје бисте стали, иђаше ноћу у огњу да вам свијетли путем којим бисте ишли, а дању у облаку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'И чу Господ глас ријечи ваших, и разгњеви се и закле се говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Ниједан од овога рода злога неће видјети ове добре земље, за коју се заклех да ћу дати вашим оцима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Осим Халева сина Јефонијина; он ће је видјети, и њему ћу дати земљу по којој је ишао, и синовима његовијем, јер се сасвијем држао Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Па и на мене се разгњеви Господ с вас; и рече: ни ти нећеш ући онамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Исус син Навин, који те служи, он ће ући онамо, њега утврди; јер ће је он раздијелити синовима Израиљевијем у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'А дјеца ваша, за коју рекосте да ће постати робље, синови ваши, који данас не знају ни шта је добро ни шта је зло, они ће ући онамо, и њима ћу је дати и они ће је наслиједити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Ви пак вратите се и идите у пустињу к Црвеноме Мору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'А ви одговористе и рекосте ми: сагријешисмо Господу; ићи ћемо и бићемо се сасвијем како нам је заповиједио Господ Бог наш. И узевши сваки своје оружје хтјесте изаћи на гору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'А Господ ми рече: кажи им: не идите и не бијте се, јер нијесам међу вама, да не изгинете пред непријатељима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'И ја вам рекох, али не послушасте, него се опријесте заповијести Господњој, и навалисте на гору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Тада изидоше пред вас Амореји, који сјеђаху у оној планини, и погнаше вас као што чине пчеле, и побише вас на Сиру па до Орме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'И вративши се плакасте пред Господом, али Господ не послуша гласа вашега нити окрете уха својега к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'И остадосте у Кадису дуго времена докле ондје стајасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Потом се вратисмо, и идосмо у пустињу к Црвеноме Мору, као што ми заповједи Господ, и обилазисмо гору Сир дуго времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'И рече ми Господ:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Доста сте обилазили ту гору, обрните се на сјевер.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'И заповједи народу и реци: сада ће те пријећи преко међе браће своје, синова Исавових, који живе у Сиру; и они ће вас се бојати, али се и ви добро чувајте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Немојте заметати боја са њима, јер вам нећу дати земље њихове ни стопе, јер сам дао Исаву гору Сир у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Јела купујте од њих за новце, и једите; и воду купујте од њих за новце, и пијте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Јер те је Господ Бог твој благословио у сваком послу руку твојих; и зна пут твој по овој великој пустињи, и ово четрдесет година бијаше с тобом Господ Бог твој, и ништа ти није недостајало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'И прођосмо браћу своју, синове Исавове, који живе у Сиру, пољем од Елата и од Гесион-Гавера; и оданде савивши ударисмо преко пустиње Моавске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'И Господ ми рече: немој пакостити Моавцима ни заметати боја са њима, јер ти нећу дати земље њихове у нашљедство; јер дадох синовима Лотовијем у нашљедство Ар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(Пређе живљаху ондје Емеји, народ велик и јак и висок као Енакими;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'О њима се мислило да су дивови као и Енакими; али их Моавци зваху Емеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'И Хореји живљаху пређе у Сиру, али их синови Исавови истјераше и истријебише испред себе и населише се на њихово мјесто, као што учини Израиљ у земљи својега нашљедства, које му даде Господ.)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'А сада устаните и пријеђите преко потока Зареда. И пријеђосмо преко потока Зареда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'А времена за које идосмо од Кадис-Варније па докле пријеђосмо преко потока Зареда, бјеше тридесет и осам година, докле не изумрије у околу сав онај нараштај, људи за војску, као што им се бјеше заклео Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Јер и рука Господња бијаше противу њих потирући их из окола докле не помријеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'И кад сви ти људи за војску помријеше у народу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'Рече ми Господ говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Ти ћеш данас пријећи преко међе Моавске код Ара;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'И доћи ћеш близу синова Амоновијех; немој им пакостити ни заметати боја са њима, јер ти нећу дати земље Амонске у нашљедство, јер је дадох синовима Лотовим у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(И за њу се мислило да је земља дивовска; у њој пређе живљаху дивови, које Амонци зваху Замзуми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Бијаху народ велик и јак и висок као Енакими; али их истријеби Господ испред њих, те они преузеше земљу њихову и населише се на њихово мјесто;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Као што учини синовима Исавовијем, који живљаху у Сиру, јер истријеби Хореје испред њих, и преузеше земљу њихову и осташе на њихову мјесту до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'И Авеје, који живљаху у Асироту па до Газе, истријебише Кафтореји, који изађоше од Кафтора, и населише се на њихово мјесто.)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Устаните, идите и пријеђите преко потока Арнона; гле, дао сам ти у руке Сиона Аморејина цара Есевонскога и земљу његову; почни узимати нашљедство и завојшти на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Данас почињем задавати страх и трепет од тебе народима под цијелијем небом; који год чују за те, дрхтаће и препадаће се од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'И послах посленике из пустиње Кедамота к Сиону цару Есевонском с мирнијем ријечима говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Да пријеђем преко твоје земље; управо ћу путем ићи, нећу свртати ни надесно ни налијево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Храну да ми дајеш за новце да једем, и воду за новце да ми дајеш да пијем, само да прођем пјешице,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Као што ми учинише синови Исавови који живе у Сиру, и Моавци, који живе у Ару, докле не пријеђем преко Јордана у земљу коју нам даје Господ Бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Али не хтје Сион цар Есевонски пустити да прођемо кроз његову земљу, јер Господ Бог твој учини те отврдну дух његов и срце његово поста упорно, да би га предао у твоје руке, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'И рече ми Господ: гледај, почех предавати теби Сиона и земљу његову; почни узимати земљу његову да је наслиједиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'И изиде пред нас Сион и сав народ његов на бој у Јасу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'И даде нам га Господ Бог наш, и убисмо га са синовима његовијем и свијем народом његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'И узесмо тада све градове његове, и побисмо људе по свијем тијем градовима, и жене и дјецу, не остависмо жива ниједнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Само стоку заплијенисмо за се и плијен што бјеше по градовима које узесмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Од Ароира који је на потоку Арнону, и од града који је у долини, па до Галада не бјеше града који би нам одолио: све то даде нам Господ Бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Само к земљи синова Амонових ниси приступио нити ка којему крају на потоку Јавоку, ни ка градовима у гори нити којему мјесту што је забранио Господ Бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Потом обративши се идосмо к Васану. И изиде пред нас Ог цар Васански и сав народ његов на бој у Едрајин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'И Господ ми рече: не бој га се, јер га дадох у твоје руке са свијем народом његовијем и са земљом његовом, да учиниш с њим онако како си учинио са Сионом царом Аморејским, који сјеђаше у Есевону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Тако нам даде Господ Бог наш у руке и Ога цара Васанскога са свијем народом његовијем, и разбисмо га и не остависмо му ниједнога жива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'И узесмо тада све градове његове; не би ниједнога града којега не узесмо, шездесет градова, сав крај Арговски, царство Ога у Васану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Сви ти градови бјеху утврђени зидом високим, вратима и пријеворницама, осим других мјеста без зидова врло много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'И раскопасмо их као што учинисмо Сиону цару Есевонском, побивши по свијем мјестима и људе и жене и дјецу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'А сву стоку и плијен по градовима заплијенисмо за се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Тако узесмо онда земљу из руку двојице царева Аморејских, која је с ову страну Јордана од потока Арнона до горе Ермона,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(Сидонци зову Ермон Сирион, а Амореји га зову Сенир,)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'Сва мјеста у равни и сав Галад и сав Васан до Салхе и Едрајина, градове царства Ога у Васану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Јер само Ог цар Васански бјеше остао од дивова. Гле, одар његов, одар гвозден, није ли у Рави синова Амоновијех? девет је лаката дуг, а широк четири лакта, лакта човјечија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Тако наслиједисмо ту земљу онда; од Ароира, који је на потоку Арнону, и половину горе Галада с градовима њезинијем дадох синовима Рувимовијем и Гадовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'И остатак Галада и сав Васан, царство Огово, дадох половини племена Манасијина; сав крај Арговски по свему Васану зваше се земља дивовска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Јаир син Манасијин узе сав крај Арговски до међе Гесурске и Махатске; и прозва Васанску својим именом: села Јаирова до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'А Махиру дадох Галад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'А Рувимову племену и Гадову племену дадох од Галада до потока Арнона, како захвата поток с међама, па до потока Јавока, гдје је међа синова Амоновијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'И поље и Јордан с међама од Хинерота до мора уз поље, до мора сланога, испод Фазге према истоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'И заповједих вам онда и рекох: Господ Бог ваш дао вам је ову земљу у нашљедство; наоружани хајдете пред браћом својом, синовима Израиљевим, ко је год за војску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'А жене ваше и дјеца ваша и стока ваша (знам да имате много стоке) нека остану у градовима вашим, које вам дадох,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Докле не смири Господ и браћу вашу као вас, да и они наслиједе земљу, коју ће им Господ Бог ваш дати с ону страну Јордана; онда се вратите сваки на своје нашљедство, које вам дадох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'А Исусу онда заповједих говорећи: очи твоје виде све што је учинио Господ Бог ваш са она два цара; онако ће Господ учинити са свијем царствима у која дођеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Немојте их се бојати, јер ће се Господ Бог ваш бити за вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'И молих се Господу онда говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Господе Боже! ти си почео показивати слузи својему величину своју и крјепку руку своју, јер који је Бог на небу или на земљи који би творио дјела каква су твоја и у кога би била сила каква је твоја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Дај ми да пријеђем и видим земљу добру која је преко Јордана и гору добру, Ливан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Али Господ бјеше гњеван на ме с вас, и не услиши ме, него ми рече: доста; не говори ми више за то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Попни се на врх ове горе, и подигавши очи своје на запад и на сјевер и на југ и на исток, види очима својима, јер нећеш пријећи преко Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Него подај заповијести Исусу, и утврди га и укријепи га; јер ће он пријећи пред народом тијем, и он ће им раздијелити у нашљедство земљу коју видиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'И остасмо у овој долини према Вет-Фегору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'А сада, Израиљу, чуј уредбе моје и законе, које вас учим да творите, да бисте поживјели и ушли у земљу коју вам даје Господ Бог отаца ваших и да бисте је наслиједили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Ништа не додајте к ријечи коју вам ја заповиједам, нити одузмите од ње, да бисте сачували заповијести Господа Бога својега које вам ја заповиједам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Очи су ваше видјеле шта учини Господ с Велфегора; јер свакога човјека који пође за Велфегором истријеби Господ Бог твој између тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'А ви који се држасте Господа Бога својега, ви сте сви живи данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Гле, учио сам вас уредбама и законима, као што ми заповиједи Господ Бог мој, да бисте тако творили у земљи коју идете да је наслиједите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Држите дакле и извршујте их, јер је то мудрост ваша и разум ваш пред народима, који ће кад чују све ове уредбе рећи: само је овај велики народ мудар и разуман.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Јер који је велики народ којему је Господ близу као што је Господ Бог наш кад га год зазовемо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'И који је народ велики који има уредбе и законе праведне као што је сав овај закон који износим данас пред вас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Само пази на се и добро чувај душу своју, да не заборавиш онијех ствари које су видјеле очи твоје, и да не изиду из срца твојега докле си год жив; него да их обзнаниш синовима својим и синовима синова својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Онај дан кад стајасте пред Господом Богом својим код Хорива, кад ми Господ рече: сабери ми народ да им кажем ријечи своје, којима ће се научити да ме се боје док су живи на земљи, и да уче томе и синове своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Кад приступисте и стајасте под гором, а гора огњем гораше до самога неба и бјеше на њој тама и облак и мрак;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'И проговори Господ к вама исред огња; глас од ријечи чусте, али осим гласа лика не видјесте;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'И објави вам завјет свој, који вам заповједи да држите, десет ријечи, које написа на двије плоче камене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'И мени заповједи онда Господ да вас учим уредбама и законима да их творите у земљи у коју идете да је наслиједите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Зато чувајте добро душе своје; јер не видјесте никакога лика у онај дан кад вам говори Господ на Хориву исред огња,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'Да се не бисте покварили и начинили себи лик резан или каку год слику од човјека или од жене,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Слику од какога живинчета које је на земљи, или слику од каке птице крилате која лети испод неба;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Слику од чега што пуже по земљи, или слику од каке рибе која је у води под земљом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'И да не би подигавши очи своје к небу и видјевши сунце и мјесец и звијезде, сву војску небеску, преварио се и клањао им се и служио им; јер их Господ Бог твој даде свијем народима под цијелијем небом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'А вас узе Господ и изведе вас из пећи гвоздене, из Мисира, да му будете народ нашљедни, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Али се Господ разгњеви на ме за ваше ријечи, и закле се да нећу пријећи преко Јордана ни ући у добру земљу, коју ти Господ Бог твој даје у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'И ја ћу умријети у овој земљи и нећу пријећи преко Јордана; а ви ћете пријећи и наслиједити ону добру земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Пазите да не заборавите завјета Господа Бога својега, који учини с вама, и да не градите себи лика резанога, слике од које год твари, као што ти је забранио Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Јер је Господ Бог твој огањ који спаљује и Бог који ревнује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Кад изродиш синове и унуке, и остарите у оној земљи, ако се покварите и начините слику резану од каке твари и учините што није угодно Господу Богу вашему, дражећи га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'Свједочим вам данас небом и земљом да ће вас брзо нестати са земље у коју идете преко Јордана да је наслиједите, нећете бити дуго у њој, него ћете се истријебити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Или ће вас расијати Господ међу народе, и мало ће вас остати међу народима у које вас одведе Господ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'И служићете ондје боговима које су начиниле руке човјечије, од дрвета и од камена, који не виде ни чују, нити једу ни миришу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Али ако и ондје потражиш Господа Бога својега, наћи ћеш га, ако га потражиш свијем срцем својим и свом душом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Кад будеш у невољи и све те то снађе, ако се у пошљедње вријеме обратиш ка Господу Богу својему, и послушаш глас његов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Господ је Бог твој милостив Бог, неће те оставити ни истријебити, јер неће заборавити завјета с оцима твојим, за који им се заклео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Јер запитај сада за стара времена, која су била прије тебе, од онога дана кад створи Бог човјека на земљи, и од једнога краја неба до другога, је ли кад била овака ствар велика, и је ли се кад чуло што тако?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Је ли кад чуо који народ глас Божји гдје говори исред огња, као што си ти чуо и остао жив?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Или, је ли Бог покушао да дође те узме себи народ из другога народа кушањем, знацима и чудесима и ратом и руком крјепком и мишицом подигнутом и страхотама великим, као што је учинио све то за вас Господ Бог наш у Мисиру на ваше очи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Теби је то показано да познаш да је Господ Бог, и да нема другога осим њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Дао ти је да чујеш глас његов с неба да би те научио, и показао ти је на земљи огањ свој велики, и ријечи његове чуо си исред огња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'И што му мили бијаху оци твоји, зато изабра сјеме њихово након њих, и изведе те сам великом силом својом из Мисира,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'Да отјера испред тебе народе веће и јаче од тебе, и да тебе уведе у њихову земљу и даде ти је у нашљедство, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Знај дакле и памти у срцу својем да је Господ Бог, горе на небу и доље на земљи, нема другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'И држи уредбе његове и заповијести његове, које ти ја данас заповиједам, да би добро било теби и синовима твојим након тебе, да би ти се продуљили дани на земљи коју ти Господ Бог твој даје засвагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Тада одијели Мојсије три града с ову страну Јордана према истоку,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Да би утјецао у њих крвник који убије ближњега својега нехотице не мрзивши прије на њ, и кад утече у који од тијех градова, да би остао жив:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Восор у пустињи, на равници у земљи племена Рувимова, и Рамот у Галаду у племену Гадову, Голан у Васанској у племену Манасијину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Ово је закон који постави Мојсије синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Ово су свједочанства и уредбе и закони, које каза Мојсије синовима Израиљевијем кад изидоше из Мисира,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'С ову страну Јордана у долини према Вет-Фегору у земљи Сиона цара Аморејскога, који живљаше у Есевону, којега уби Мојсије и синови Израиљеви кад изидоше из Мисира,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'И освојише земљу његову и земљу Ога цара Васанскога, два цара Аморејска, која је с ону страну Јордана према истоку,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Од Ароира, који је на потоку Арнону, до горе Сиона, а то је Ермон,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'И све поље с ову страну Јордана према истоку до мора уз равницу под Аздот-Фазгом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'И Мојсије сазва сав народ Израиљев,и рече им чуј Израиљу уредбе и законе, које ћу данас казати да чујете, да их научите и држите их и творите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Господ Бог наш учини с нама завјет на Хориву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Није с оцима нашим учинио тај завјет, него с нама, који смо данас ту сви живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Лицем к лицу говорио вам је Господ на овој гори исред огња;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Ја тада стајах између Господа и вас, да вам јавим ријечи Господње, јер вас бјеше страх од огња и не изидосте на гору; и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Ја сам Господ Бог твој који сам те извео из земље Мисирске, из дома ропскога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Немој имати богова других до мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Не гради себи лика резанога, нити какве слике од твари које су горе на небу или које су доље на земљи или које су у води испод земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Немој им се клањати нити им служити, јер сам ја Господ Бог твој, Бог ревнитељ, који на синовима походим безакоња отаца њиховијех до трећега и до четвртога кољена, онијех који мрзе на ме,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'А чиним милост на тисућама онијех који ме љубе и чувају заповијести моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Не узимај узалуд имена Господа Бога својега, јер неће пред Господом бити прав ко узме име његово узалуд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Држи дан од одмора и светкуј га, као што ти је заповиједио Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Шест дана ради и свршуј све послове своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'А седми је дан одмор Господу Богу твојему; немој радити никакога посла ни ти ни син твој ни кћи твоја ни слуга твој ни слушкиња твоја, ни во твој ни магарац твој, нити које живинче твоје, ни дошљак који је код тебе, да би се одморио слуга твој и слушкиња твоја као и ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'И памти да си био роб у земљи Мисирској, и Господ Бог твој изведе те оданде руком крјепком и мишицом подигнутом. Зато ти је Господ Бог твој заповједио да светкујеш дан од одмора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Поштуј оца својега и матер своју, као што ти је заповиједио Господ Бог твој, да би се продуљили дани твоји и да би ти добро било на земљи, коју ти даде Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Не убиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Не чини прељубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Не кради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Не свједочи лажно на ближњега својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Не пожели жене ближњега својега, не пожели куће ближњега својега, ни њиве његове, ни слуге његова, ни слушкиње његове, ни вола његова, ни магарца његова, нити ишта шта је ближњега твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Те ријечи изговори Господ свему збору вашему на гори исред огња, облака и мрака, гласом великим, и ништа више, него их написа на двије плоче камене које ми даде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'А ви кад чусте глас исред таме, јер гора огњем гораше, приступисте к мени, сви главари од племена ваших и старјешине ваше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'И рекосте: гле, показа нам Господ Бог наш славу и величину своју, и чусмо глас његов исред огња; данас видјесмо гдје Бог говори с човјеком, и човјек оста жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Па сада зашто да помремо? јер ће нас спалити онај огањ велики; ако јоште чујемо глас Господа Бога својега, помријећемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Јер које је тијело чуло глас Бога живога гдје говори исред огња, као ми, и стало живо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Иди ти, и саслушај све што ће ти казати Господ Бог наш, па онда ти кажи нама што ти год рече Господ Бог наш, а ми ћемо слушати и творити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'И Господ чу глас од ријечи ваших кад ви говорасте, и рече ми Господ: чух глас од ријечи тога народа, које рекоше теби; што рекоше добро рекоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'О, кад би им било срце свагда тако да ме се боје и држе све заповијести моје свагда, да би било добро њима и синовима њиховијем довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Иди, реци им: вратите се у шаторе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'А ти стани овдје код мене, и казаћу ти све заповијести и уредбе и законе, које ћеш их научити да творе у земљи коју им дајем у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Гледајте, дакле да чините онако како вам је заповједио Господ Бог ваш, не сврћите ни надесно ни налијево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Цијелијем путем, који вам је заповједио Господ Бог ваш, идите, да бисте живи били и да би вам добро било, и да би вам се продуљили дани у земљи коју ћете наслиједити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'А ово су заповијести и уредбе и закони, које Господ Бог ваш заповједи да вас учим да их творите у земљи у коју идете да је наслиједите,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Да би се бојао Господа Бога својега држећи све уредбе његове и заповијести његове, које ти ја заповиједам, ти син твој и унук твој свега вијека својега, да би ти се продуљили дани твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Чуј дакле, Израиљу, и гледај да тако чиниш, да би ти добро било и да бисте се умножили веома у земљи у којој тече млијеко и мед, као што ти је рекао Господ Бог отаца твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Чуј, Израиљу: Господ је Бог наш једини Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Зато љуби Господа Бога својега из свега срца својега и из све душе своје и из све снаге своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'И нека ове ријечи који ти ја заповиједам данас буду у срцу твом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'И често их напомињи синовима својим, и говори о њима кад сједиш у кући својој и кад идеш путем, кад лијежеш и кад устајеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'И вежи их себи на руку за знак, и нека ти буду као почеоник међу очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'И напиши их на довратницима од куће своје и на вратима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'А кад те уведе Господ Бог твој у земљу за коју се заклео оцима твојим Авраму, Исаку и Јакову, да ће ти је дати, у градове велике и добре, којих ниси зидао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'И куће пуне свакога добра, којих нијеси пунио, и на студенце ископане, којих нијеси копао, у винограде и у маслинике, којих нијеси садио, и станеш јести и наситиш се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Чувај се да не заборавиш Господа, који те је извео из земље Мисирске, из куће ропске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Господа Бога својега бој се, и њему служи, и његовим се именом куни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Не идите за другим боговима између богова других народа, који су око вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'Јер је Бог ревнитељ, Господ Бог твој усред тебе, па да се не би разгњевио Господ Бог твој на те и истријебио те из земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Немојте кушати Господа Бога својега као што га кушасте у Маси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Држите добро заповијести Господа Бога својега и свједочанства његова и уредбе његове, које ти је заповједио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'И чини што је право и добро пред Господом, да би ти било добро и да би ушао у добру земљу, за коју се заклео Господ оцима твојим, и да би је наслиједио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'Да би отјерао све непријатеље твоје испред тебе, као што ти је рекао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Па кад те запита послије син твој говорећи: каква су то свједочанства и уредбе и закони, што вам је заповиједио Господ Бог наш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Онда кажи сину својему: бијасмо робови Фараонови у Мисиру, и изведе нас Господ из Мисира руком крјепком,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'И учини Господ знаке и чудеса велика и зла у Мисиру на Фараону и на свему дому његову пред нама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'А нас изведе оданде да нас уведе у земљу за коју се заклео оцима нашим да ће нам је дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'И заповједи нам Господ да вршимо све ове уредбе бојећи се Господа Бога својега, да би нам било добро свагда и да би нас сачувао у животу, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'И биће нам правда, ако уздржимо и устворимо све заповијести ове пред Господом Богом својим како нам је заповједио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Кад те Господ Бог твој уведе у земљу у коју идеш да је наслиједиш, и отјера испред тебе народе многе, Хетеје и Гергесеје и Амореје и Хананеје и Ферезеје и Јевеје и Јевусеје, седам народа већих и јачих од тебе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'И преда их Господ Бог твој теби, и ти их разбијеш, потри их, не хватај с њима вјере, нити се смилуј на њих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Нити се пријатељи с њима; кћери своје не даји за сина њихова, нити кћери њихове узимај за сина својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Јер би отпадила сина твојега од мене, и служио би боговима другим, те би се разгњевио Господ на вас и потро вас брзо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Него им ово учините: олтаре њихове раскопајте, и ликове њихове поломите, лугове њихове исијеците, и резане богове њихове огњем спалите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Јер си ти народ свет Господу Богу својему, тебе је изабрао Господ Бог твој да му будеш народ особит мимо све народе на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Не зато што би вас било више него других народа прихвати вас Господ и изабра вас; јер вас бијаше мање него икојега другога народа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Него што вас Господ милује и што држи заклетву којом се заклео оцима вашим, зато вас је Господ извео руком крјепком и избавио вас из куће ропске из руке Фараона цара Мисирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'И тако знај да је Господ Бог твој Бог, Бог вјеран, који држи завјет свој и милост своју до тисућу кољена онима који га љубе и држе заповијести његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'И плаћа онима који мрзе на њ, свакоме истребљујући га, и не одгађа ономе који мрзи на њ, плаћа свакоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Зато држи заповјести и уредбе и законе, које ти данас ја заповиједам, да их твориш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'И ако ове законе узаслушате и уздржите и устворите, и Господ ће Бог држати теби завјет и милост, за коју се заклео оцима твојим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'И миловаће те и благословиће те и умножиће те; благословиће плод утробе твоје и плод земље твоје, жито твоје и вино твоје и уље твоје, плод говеда твојих и стада оваца твојих у земљи за коју се заклео оцима твојим да ће ти је дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Бићеш благословен мимо све народе: неће бити у тебе ни мушкога ни женскога неплодна, ни међу стоком твојом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'И уклониће од тебе Господ сваку болест, од љутих зала Мисирских која знаш неће ниједнога пустити на тебе, него ће пустити на оне који мрзе на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'И истријеби све народе који ти Господ Бог твој преда, нека их не пожали око твоје, и немој служити боговима њиховијем, јер би ти то била замка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Ако би рекао у срцу свом: већи су ови народи од мене, како их могу изагнати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Не бој их се; памти добро што је учинио Господ Бог твој с Фараоном и са свијем Мисирцима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Велика кушања, која видјеше очи твоје, и знаке и чудеса и руку крјепку и мишицу подигнуту, којом те изведе Господ Бог твој; онако ће учинити Господ Бог твој са свијем народима од којих би се уплашио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'И стршљене ће послати Господ Бог твој на њих докле не изгину који би остали и сакрили се од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Не плаши се од њих, јер је Господ Бог твој усред тебе, Бог велики и страшни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Господ ће Бог твој мало по мало потрти те народе испред тебе; нећеш их моћи одједанпут истријебити, да се не би умножило на тебе звијерје пољско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Али ће их предати Господ Бог твој теби, и затираће их затирањем великим докле се не затру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'И предаће цареве њихове у твоје руке да затреш име њихово под небом, неће се ниједан одржати пред тобом, докле их не потреш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Резане богове њихове спали огњем, немој да се полакомиш на сребро или злато што је на њима и да га узмеш, да ти не буде замка, јер је гадно пред Господом Богом твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'И немој да унесеш гада у дом свој, да не будеш проклет као и он, него се гади на њ и грози се од њега, јер је проклето.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Држите и творите све заповијести које вам ја заповиједам данас, да бисте живи били и умножили се, и да бисте ушли у земљу за коју се Господ заклео оцима вашим, и да бисте је наслиједили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'И опомињи се свега пута којим те је водио Господ Бог твој четрдесет година по пустињи, да би те намучио и искушао, да се зна шта ти је у срцу, хоћеш ли држати заповијести његове или нећеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'И мучио те је, глађу те морио; али те је опет хранио маном, за коју ти нијеси знао ни оци твоји, да би ти показао да човјек не живи о самом хљебу него о свему што излази из уста Господњих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Одијело твоје не оветша на теби нити нога твоја отече за овијех четрдесет година;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Зато познај у срцу свом да те Господ Бог твој гаји као што човјек гаји своје дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'И држи заповијести Господа Бога својега ходећи путовима његовијем и бојећи се њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Јер Господ Бог твој увешће те сада у добру земљу, у земљу у којој има доста потока и извора и језера, што извиру по долинама и по брдима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'У земљу изобилну пшеницом и јечмом и виновом лозом и смоквама и шипцима, земљу изобилну маслином, од које бива уље, и медом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'У земљу, гдје нећеш сиротињски јести хљеба, гдје ти неће ништа недостајати; у земљу гдје је камење гвожђе и гдје ћеш из брда њезинијех сјећи мјед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Јешћеш и бићеш сит, па благосиљај Господа Бога својега за добру земљу коју ти да.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'И чувај се да не заборавиш Господа Бога својега бацивши у немар заповијести његове и законе његове и уредбе његове, које ти ја заповиједам данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'И кад узједеш и наситиш се, и добре куће начиниш и у њима станеш живјети,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'И кад се говеда твоја и овце твоје наплоде, и кад ти се намножи сребро и злато, и што год имаш кад ти се намножи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'Немој да се понесе срце твоје и заборавиш Господа Бога својега, који те је извео из земље Мисирске, из куће ропске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'Који те је водио преко оне пустиње велике и страшне гдје живе змије ватрене и скорпије, гдје је суша а нема воде; који ти је извео воду из тврдога камена;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Који те је хранио у пустињи маном, за коју не знаше оци твоји, да би те намучио и искушао те, и најпослије да би ти добро учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Нити говори у срцу својем: моја снага, и сила моје руке добавила ми је ово благо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Него се опомињи Господа Бога својега; јер ти он даје снагу да добављаш благо, да би потврдио завјет свој, за који се заклео оцима твојим, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Ако ли заборавиш Господа Бога својега, и пођеш за другим боговима и њима станеш служити и клањати се, свједочим вам данас да ћете зацијело пропасти,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Пропашћете као народи које Господ потире испред вас, јер не послушасте гласа Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Чуј, Израиљу! Ти данас прелазиш преко Јордана да уђеш и наслиједиш народе веће и јаче од себе, градове велике и ограђене до неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Велик и висок народ, синове Енакове, које знаш и за које си слушао:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Знај дакле данас да је Господ Бог твој, који иде пред тобом, огањ који спаљује; он ће их истријебити и он ће их оборити пред тобом, и изагнаћеш их и истријебити брзо, као што ти је казао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Кад их Господ Бог твој отјера испред тебе, немој да речеш у срцу свом: за правду моју уведе ме Господ у ову земљу да је наслиједим; јер Господ тјера оне народе испред тебе за неваљалство њихово!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Не идеш за правду своју ни за чистоту срца својега да наслиједиш ту земљу; него за неваљалство тијех народа Господ Бог твој тјера их испред тебе, и да одржи ријеч за коју се заклео оцима твојим, Авраму, Исаку и Јакову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Знај дакле да ти Господ Бог твој не даје те добре земље за правду твоју да је наслиједиш, јер си тврдоврат народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Памти и не заборави како си гњевио Господа Бога својега у пустињи; од онога дана кад изидосте из земље Мисирске па докле дођосте на ово мјесто, непокорни бијасте Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'И код Хорива разгњевисте Господа, и од гњева шћаше вас Господ да истријеби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Кад изидох на гору да примим плоче камене, плоче завјета, који с вама учини Господ, тада стајах на гори четрдесет дана и четрдесет ноћи хљеба не једући ни воде пијући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'И даде ми Господ двије плоче камене, исписане прстом Господњим, на којима бијаху ријечи све које вам изговори Господ на гори исред огња на дан збора вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Послије четрдесет дана и четрдесет ноћи даде ми Господ двије плоче камене, плоче завјетне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'И рече ми Господ: устани, сиђи брже одавде; јер се поквари народ твој који си извео из Мисира, сиђоше брзо с пута који им заповједих, и начинише себи ливен лик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Још ми рече Господ говорећи: погледах овај народ, и ето је народ тврда врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Пусти ме да их истријебим и име њихово затрем под небом; а од тебе ћу учинити народ јачи и већи него што је овај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'И ја се вратих и сиђох с горе, а гора огњем гораше, и двије поче завјетне бијаху ми у руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'И погледах, а то згријешисте Господу Богу својему саливши себи теле, и брзо сиђосте с пута који вам бјеше заповиједио Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Тада узех оне двије плоче и бацих их из руку својих, и разбих их пред вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Потом падох и лежах пред Господом као прије, четрдесет дана и четрдесет ноћи, хљеба не једући ни воде пијући, ради свијех гријеха ваших, којима се огријешисте учинивши што је зло пред Господом и разгњевивши га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Јер се бојах гњева и јарости, којом се бјеше Господ разљутио на вас да вас истријеби; и услиши ме Господ и тада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Бјеше се Господ и на Арона разгњевио веома да га шћаше убити; али се молих тада и за Арона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'И узех гријех ваш који учинисте, теле, и сажегох га огњем, и разбих га и сатрх га у прах, и просух прах његов у поток, који тече с оне горе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'И у Тавери и у Маси и у Киврот-Атави гњевисте Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'И кад вас посла Господ из Кадис-Варније говорећи: идите и узмите ту земљу коју сам вам дао, опет се супротисте ријечи Господа Бога својега, и не вјеровасте му и не послушасте гласа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Непокорни бијасте Господу откад вас познах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Зато падох и лежах пред Господом четрдесет дана и четрдесет ноћи, јер бјеше рекао Господ да ће вас потрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'И молих се Господу и рекох: Господе, Господе! немој потрти народа својега и нашљедства својега, које си избавио величанством својим, које си извео из Мисира крјепком руком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Опомени се слуга својих Аврама, Исака и Јакова, не гледај на тврђу народа овога, на неваљалство његово и на гријехе његове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Да не реку који живе у земљи одакле си нас извео: није их могао Господ увести у земљу коју им обећа, или мрзио је на њих, зато их изведе да их побије у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Јер су твој народ и твоје нашљедство, које си извео силом својом великом и мишицом својом подигнутом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'У то вријеме рече ми Господ: истеши двије поче од камена као што бјеху прве, и изиди к мени на гору, и начини ковчег од дрвета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'И написаћу на тијем плочама ријечи које су биле на првијем плочама што си их разбио, па ћеш их метнути у ковчег.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Тако начиних ковчег од дрвета ситима, и истесах двије плоче од камена, као што бјеху прве, и изидох на гору с двјема плочама у руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'И написа на тијем плочама што бјеше прво написао, десет ријечи, које вам изговори Господ на гори исред огња на дан збора вашега; и даде ми их Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'И вратив се сиђох с горе, и метнух плоче у ковчег који начиних, и осташе ондје, као што ми заповједи Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'А синови Израиљеви пођоше од Вирота синова Јакановијех у Мосеру. Ондје умрије Арон и ондје би погребен; а Елеазар син његов поста свештеник на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Оданде отидоше у Гадгад, а од Гадгада у Јотвату, земљу гдје има много потока.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'У то вријеме одвоји Господ племе Левијево да носе ковчег завјета Господњега, да стоје пред Господом и служе му и да благосиљају у име његово до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Зато нема племе Левијево дијела ни нашљедства с браћом својом; Господ је нашљедство његово, као што му Господ Бог твој каза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'А ја стајах на гори као прије, четрдесет дана и четрдесет ноћи; и услиши ме Господ и тада, и не хтје те Господ затрти,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Него ми рече Господ: устани и иди пред народом овијем да уђу у земљу за коју сам се заклео оцима њиховијем да ћу им је дати да је наслиједе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Сада дакле, Израиљу, шта иште од тебе Господ Бог твој, осим да се бојиш Господа Бога својега, да ходиш по свијем путовима његовијем и да га љубиш и служиш Господу Богу својему из свег срца својега и из све душе своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'Држећи заповијести Господње и уредбе његове, које ти ја данас заповиједам, да би ти било добро?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Гле, Господа је Бога твојега небо, и небо над небесима, земља, и све што је на њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Али само твоји оци омиљеше Господу, и изабра семе њихово након њих, вас између свијех народа, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Зато обрежите срце своје, и немојте више бити тврдоврати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Јер је Господ Бог ваш Бог над боговима и господар над господарима, Бог велики, силни и страшни, који не гледа ко је ко нити прима поклона;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Даје правицу сироти и удовици; и љуби дошљака дајући му хљеб и одијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Љубите дакле дошљака, јер сте били дошљаци у земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Бој се Господа Бога својега, њему служи и њега се држи, и његовијем се именом куни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Он је хвала твоја и он је Бог твој, који тебе ради учини велике и страшне ствари, које видјеше очи твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Седамдесет душа бјеше отаца твојих кад сиђоше у Мисир; а сада учини ти Господ Бог твој те вас има много као звијезда небеских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Љуби дакле Господа Бога својега, и извршуј једнако што је заповједио да извршујеш, и уредбе његове, и законе његове и заповијести његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'И познајте данас што ваши синови не знају нити видјеше, карање Господа Бога својега, величанство његово, крјепку руку његову и мишицу његову подигнуту,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'И знаке његове и дјела његова, што учини усред Мисира на Фараону цару Мисирском и на свој земљи његовој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'И што учини војсци Мисирској, коњма и колима њиховијем, како учини, те их вода Црвенога Мора потопи кад вас тјераху, и затр их Господ до данашњега дана,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'И што вама учини у пустињи докле не дођосте до овога мјеста,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'И Што учини Датану и Авирону синовима Елијава сина Рувимова, како земља отвори уста своја и прождрије њих и породице њихове и шаторе њихове и све благо њихово што имаху, усред Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Јер ваше очи видјеше сва дјела Господња велика, која учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Зато држите све заповијести, које вам ја данас заповиједам, да бисте се укријепили и наслиједили земљу, у коју идете да је наслиједите;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'И да би вам се продуљили дани у земљи, за коју се закле оцима вашим да ће је дати њима и сјемену њихову, земљу, у којој тече млијеко и мед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Јер земља у коју идеш да је наслиједиш није као земља Мисирска из које сте изишли, гдје си сијао своје сјеме и заљевао на својим ногама као врт од зеља;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Него је земља у коју идете да је наслиједите земља у којој су брда и долине, и натапа је дажд небески;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Земља којом се стара Господ Бог твој и на коју су једнако обраћене очи Господа Бога твојега од почетка године до краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Зато ако добро узаслушате заповијести, које вам ја заповиједам данас, љубећи Господа Бога својега и служећи му свијем срцем својим и свом душом својом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'Тада ћу давати дажд земљи вашој на вријеме, и рани и позни, и сабираћеш жито своје и вино своје и уље своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'И за стоку ћу твоју дати траву у пољу твојем; и јешћеш и бићеш сит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Чувајте се да се не превари срце ваше да се одметне и служите туђим боговима и поклањате им се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Да се не би разгњевио Господ на вас и затворио небо да не буде дажда, и земља да не да рода својега, те бисте брзо изгинули у доброј земљи коју вам Господ даје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Него сложите ове ријечи моје у срце своје и душу своју, и вежите их за знак себи на руку, и нека вам буду као почеоник међу очима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'И учите синове своје говорећи о њима кад сједиш у кући својој и кад идеш путем, и кад лијежеш и кад устајеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'И напиши их на довратницима дома својега и на вратима својим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Да би се умножили дани ваши и дани синова ваших по земљи, за коју се заклео Господ оцима вашим да ће им је дати, као дани небу над земљом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Јер ако добро уздржите све ове заповијести које вам ја заповиједам да творите љубећи Господа Бога својега, и ходећи свијем путовима његовијем и њега се држећи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Тада ће отјерати Господ све ове народе испред вас, и наслиједићете народе веће и јаче него што сте сами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Свако мјесто на које ступи стопало ноге ваше, ваше ће бити; од пустиње до Ливана, и од ријеке, ријеке Ефрата, до мора западнога биће међа ваша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Неће се нико одржати пред вама; страх и трепет ваш пустиће Господ Бог ваш на сву земљу на коју ступите, као што вам каза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Гле, износим данас пред вас благослов и проклетство:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Благослов, ако узаслушате заповијести Господа Бога својега, које вам ја данас заповиједам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'А проклетство, ако не узаслушате заповијести Господа Бога својега него сиђете с пута, који вам ја данас заповиједам, те пођете за другим боговима, којих не познајете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'И кад те уведе Господ Бог твој у земљу у коју идеш да је наслиједиш, тада изреци благослов онај на гори Гаризиму, а проклетство на гори Евалу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Оне су с ону страну Јордана, идући к западу, у земљи Хананеја који живе у равни према Галгалу код равнице Морешке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Јер ћете пријећи преко Јордана да уђете у земљу коју вам даје Господ Бог ваш да је наслиједите, и наслиједићете је и наставаћете у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Гледајте дакле да творите све ове уредбе и законе које ја данас износим пред вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Ово су уредбе и закони које ћете држати и творити у земљи коју ти је Господ Бог отаца твојих дао да је наслиједиш, докле сте год живи на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Раскопајте сасвијем сва мјеста у којима су служили боговима својим народи које ће те наслиједити, по високим брдима и по хумовима и под свакијем зеленијем дрветом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Оборите олтаре њихове и разбијте ликове њихове, и лугове њихове попалите огњем, и резане богове њихове изломите, и истријебите име њихово са онога мјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Не чините тако Господу Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Него га тражите у мјесту које изабере Господ Бог ваш између свијех племена ваших себи за стан да ондје намјести име своје, и онамо идите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Онамо носите жртве своје паљенице и друге жртве своје и десетке своје и приносе руку својих и завјете своје и драговољне приносе своје и првине стоке своје крупне и ситне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'И једите ондје пред Господом Богом својим, и веселите се ви и породице ваше свачим, за што се прихватите руком својом, чим те благослови Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Не чините како ми сада овдје чинимо, што је коме драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Јер још нијесте дошли до одмора и нашљедства, које ти даје Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Него кад пријеђете преко Јордана, и станете живјети у земљи коју вам даје Господ Бог ваш да је наслиједите, и смири вас од свијех непријатеља ваших унаоколо, те станете живјети без страха,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'Онда у мјесто које изабере Господ Бог ваш да у њему настани име своје, доносите све што вам ја заповиједам, жртве своје паљенице и друге жртве своје, десетке своје и приносе руку својих и све што буде најбоље у ономе што завјетујете Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'И веселите се пред Господом Богом својим ви и синови ваши и кћери ваше и слуге ваше и слушкиње ваше, и Левит који је у мјесту вашем, јер он нема дијела ни нашљедства с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Чувај се да не приносиш жртава својих паљеница на ком год мјесту, које угледаш;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Него на оном мјесту које изабере Господ Бог у једном од твојих племена, ондје приноси жртве своје паљенице, и ондје чини све што ти заповиједам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Али ћеш моћи клати и јести месо како ти душа зажели у сваком мјесту својем по благослову Господа Бога својега, који ти да; чист и нечист може јести као срну и јелена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Само крви не једите; пролијте је на земљу као воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Нећеш моћи јести у мјесту својем десетка од жита својега ни од вина својега ни од уља својега, ни првина од стоке своје крупне и ситне, ни онога што завјетујеш; ни приноса драговољнијех, ни приноса руку својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Него то једи пред Господом Богом својим на мјесту које изабере Господ Бог твој, ти син твој и кћи твоја и слуга твој и слушкиња твоја, и Левит који је у мјесту твом; и весели се пред Господом Богом својим свачим за што се прихватиш руком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Чувај се да не оставиш Левита док си год жив на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Кад рашири Господ Бог твој међе твоје, као што ти је казао, ако речеш: да једем меса, кад душа твоја жели да једе меса, једи меса по свој жељи душе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Ако би било далеко од тебе мјесто које Господ Бог твој изабере да ондје намјести име своје, закољи од стоке своје крупне или ситне, коју ти да Господ, као што сам ти заповједио, и једи у свом мјесту по жељи душе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Како се једе срна и јелен, онако једи; и чист и нечист нека једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Само пази да не једеш крви; јер је крв душа, па не једи душе с месом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Не једи је; него пролиј на земљу као воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Не једи је, да би добро било теби и синовима твојим након тебе, кад чиниш оно што је угодно Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Али ствари своје свете, које имаш, и што завјетујеш, узми и дођи на мјесто које изабере Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'И принеси жртве своје паљенице, месо и крв, на олтару Господа Бога својега; крв пак од других жртава твојих нека се пролије на олтар Господа Бога твојега, а месо једи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Чувај и слушај све ове ријечи које ти ја заповиједам, да би добро било теби и синовима твојим након тебе довијека кад чиниш што је добро и право пред Господом Богом твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Кад истријеби Господ Бог твој испред тебе народе ка којима идеш да наслиједиш земљу њихову, и наслиједивши је кад се настаниш у земљи њиховој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Чувај се да се не ухватиш у замку пошавши за њима пошто се потру испред тебе, и да не потражиш богова њиховијех, и речеш: како су ови народи служили својим боговима, тако ћу и ја чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Не чини тако Господу Богу својему; јер они чинише својим боговима све што је гадно пред Господом и на што он мрзи; јер су и синове своје и кћери своје сажизали боговима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Што вам год ја заповиједам све држите и творите, нити што додајте к томе ни одузмите од тога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Ако устане међу вама пророк или који сне сања, и каже ти знак или чудо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Па се збуде тај знак или чудо које ти каже, и он ти рече: хајде да идемо за другим боговима, којих не знаш, и њима да служимо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Немој послушати што ти каже тај пророк или сањач, јер вас куша Господ Бог ваш да би се знало љубите ли Господа Бога својега из свег срца својега и све душе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'За Господом Богом својим идите, и њега се бојте; његове заповијести чувајте, и глас његов слушајте, и њему служите и њега се држите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'А онај пророк или сањач да се погуби, јер вас је наговарао да се одметнете Господа Бога својега, који вас изведе из земље Мисирске и искупи вас из куће ропске, и одвраћао од пута који ти је заповједио Господ Бог твој да идеш њим; тако истријеби зло из себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Ако би те подбадао брат твој, син матере твоје, или син твој или кћи твоја, или жена твоја мила, или пријатељ твој који ти је као душа твоја, говорећи ти тајно: хајде да служимо другим боговима, којих нијеси знао ни ти ни оци твоји,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Између богова других народа који су око вас, близу или далеко од тебе, од једнога краја земље до другога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Не пристај с њим нити га послушај; нека га не жали око твоје, и немој му се смиловати нити га таји,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Него га убиј: твоја рука нек се прва дигне на њ да га убијеш, па онда рука свега народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Заспи га камењем да погине; јер те шћаше одвратити од Господа Бога твојега, који те је извео из земље Мисирске, из куће ропске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Да сав Израиљ чује и боји се, и да се више не учини тако зло међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Ако за какав град свој, који ти Господ Бог твој да да у њему живиш, чујеш гдје говоре:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Изидоше људи неваљали између тебе и отпадише све који живе у граду њихову, говорећи: хајде да служимо другим боговима, којих не познајете,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Тада истражи и распитај, извиди добро, па ако буде истина и доиста се учинила она гадна ствар међу вама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Побиј мачем све који живе у граду оном, и затри и њега и све што би у њему било, и стоку мачем побиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'И сав плијен из њега скупи насред улице његове, спали огњем и онај град и сав плијен из њега Господу Богу својему, да буде гомила довијека и да се више не сазида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'И нека ти од проклетијех ствари не прионе ништа за руку, еда би се Господ повратио од жестине гњева својега, учинио ти милост и смиловао се на те, и умножио те, као што се заклео оцима твојим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Кад слушаш глас Господа Бога својега држећи све заповијести његове, које ти ја данас заповиједам, да би чинио што је право пред Господом Богом твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Ви сте синови Господа Бога својега; немојте се резати нити бријати међу очима за мртвацем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Јер си народ свет Господу Богу својему, и тебе изабра Господ да си му народ особит између свијех народа на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Не једи ништа гадно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Ово су животиње које ћете јести: говече, овцу, козу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Јелена, срну, бивола, дивокозу, једнорога и козу камењачу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'И све животиње које имају папке расцијепљене на двоје, и које преживају између животиња, њих једите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Али не једите онијех које само преживају или које само имају папке расцијепљене на двоје, као: камиле, зеца, питомога зеца, јер преживају, а немају папака раздвојенијех; да вам је нечисто;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Ни свињчета, јер има раздвојене папке, али не прежива; да вам је нечисто; меса од њега не једите, и стрва се његова не дохватајте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'А између онијех што су у води, једите ове: што год има пера и љуске, једите;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'А што нема пера и љусака, не једите; да вам је нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Све птице чисте једите;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'А овијех не једите: орла, ни јастријеба, ни морскога орла,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'Ни сокола, ни еје, ни крагуја по врстама њиховијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'Ни гаврана по врстама његовијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'Ни ћука, ни совуљаге, ни лиске, ни копца по врстама његовијем, ни буљине, ни ражња, ни лабуда,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'НИ буљине, ни ражња, ни лабуда,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'Ни гема, ни свраке, ни гњурца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'Ни роде, ни чапље по врстама њезинијем, ни пупавца, ни љиљка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'И све бубине крилате да су вам нечисте; не једите их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'И све птице чисте једите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Ништа мрцино не једите; дошљаку који је код тебе подај нека једе или продај туђину; јер си народ свет Господу Богу својему. Не кухај јарета у млијеку матере његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Десетак даји од свега рода усјева својега, што дође с њиве твоје, сваке године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'И једи пред Господом Богом својим на мјесту које избере да ондје настани име своје, десетак од жита својега, од вина својега и уља својега, и првине стоке своје крупне и ситне, да се учиш бојати се Господа Бога својега свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Ако би ти пут био далек, те не би могао однијети зато што је далеко од тебе мјесто, које изабере Господ Бог твој да ондје намјести име своје, кад те Господ Бог твој благослови,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Онда учини у новац, и узев у руку своју отиди у мјесто које изабере Господ Бог твој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'И за те новце узми што зажели душа твоја, говеда, оваца, вина или другог јаког пића, и што год би зажелела душа твоја, па једи ондје пред Господом Богом својим, и весели се ти и дом твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Али Левита који би био у мјесту твом, немој оставити, јер нема дијела ни нашљедства с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Сваке треће године одвој сав десетак од доходака својих оне године, и остави га у свом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Па нека дођу Левити (јер немају дијела ни нашљедства с тобом) и дошљаци и сироте и удовице што су у мјесту твојем, и нека једу и насите се, да би те благословио Господ Бог твој у сваком послу руку твојих, који би радио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Сваке седме године опраштај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'А опраштање да бива овако: коме је ко дужан што, нека опрости што би могао тражити од ближњега својега; нека не тражи од ближњега својега и од брата својега, јер је опраштање Господње оглашено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Од туђина тражи, али што би имао у брата својега, оно нека му опрости рука твоја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Да не би било сиромаха међу вама, јер ће те обилно благословити Господ у земљи коју ти Господ Бог твој да у нашљедство да је твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Само ако добро узаслушаш глас Господа Бога својега гледајући да чиниш све ове заповијести, које ти ја заповиједам данас,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Благословиће те Господ Бог твој, као што ти је казао, те ћеш давати у зајам многим народима, а ни од кога нећеш узимати у зајам, и владаћеш многим народима, а они тобом неће владати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Ако буде у тебе који сиромах између браће твоје у ком мјесту твом, у земљи твојој, коју ти даје Господ Бог твој, немој да ти се стврдне срце твоје и да стиснеш руку своју брату својему сиромаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Него отвори руку своју и позајми му радо колико му год треба у потреби његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Чувај се да не буде какво неваљалство у срцу твом, па да речеш: близу је седма година, година опросна; и да око твоје не буде зло према брату твојему сиромаху, па да му не даш, а он зато да вапије ка Господу на те, и буде ти гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Подај му, и нека не жали срце твоје кад му даш; јер ће за ту ствар благословити тебе Господ Бог твој у сваком послу твом и у свему за што се прихватиш руком својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Јер неће бити без сиромаха у земљи; зато ти заповиједам и кажем: отварај руку своју брату својему, невољнику и сиромаху својему у земљи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Ако ти се прода брат твој Јеврејин или Јеврејка, нека ти служи шест година, а седме године отпусти га од себе слободна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'А кад га отпустиш од себе слободна, немој га отпустити празна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Даруј га чим између стоке своје и с гумна својега и из каце своје; подај му чим те је благословио Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'И опомињи се да си био роб у земљи Мисирској и да те је избавио Господ Бог твој; зато ти ја заповиједам ово данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Ако ли ти рече: нећу да идем од тебе, зато што те љуби и дом твој, јер му је добро код тебе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'Тада узми шило и пробуши му ухо на вратима, и биће ти слуга довијека; и слушкињи својој учини тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Немој да ти буде тешко кад га отпушташ од себе слободна, јер је двојином онолико колико најамник заслужио у тебе за шест година, да би те благословио Господ Бог твој у свему што радиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Све првенце у стоци својој крупној и ситној што буде мушко, посвети Господу Богу својему; не ради на првенцу од краве своје, и не стризи првенца од оваца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Пред Господом Богом својим једи их ти и породица твоја сваке године на мјесту које изабере Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Ако ли на њему буде мана, ако буде хромо или слијепо, или која год зла мана буде на њему, не кољи га Господу Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'У свом мјесту поједи га; и чист и нечист нека једе као срну и јелена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Само крви од њега не једи; пролиј је на земљу као воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Држи мјесец Авив, те слави пасху Господу Богу својему, јер мјесеца Авива извео те је Господ Бог твој из Мисира ноћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'И закољи пасху Господу Богу својему, од крупне и ситне стоке, на мјесту које изабере Господ да ондје настани име своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Не једи с њом хљеба киселога; седам дана једи с њом пријесан хљеб, хљеб невољнички, јер си хитећи изашао из земље Мисирске, па да се опомињеш дана кад си изашао из Мисира, док си год жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'И да се не види у тебе квасац за седам дана нигдје међу границама твојим, и да не остане преко ноћ ништа до јутра од меса које закољеш први дан увече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Не можеш клати пасхе на сваком мјесту свом који ти да Господ Бог твој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Него на мјесту које изабере Господ Бог твој да ондје настани име своје, ондје кољи пасху увече о сунчаном заходу у исто вријеме кад си пошао из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'А пеци је и једи на мјесту које изабере Господ Бог твој; и сјутрадан вративши се иди у своје шаторе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Шест дана једи пријесне хљебове, а седми дан да је празник Господњи, тада не ради ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Седам недјеља наброј; кад стане срп радити по љетини, онда почни бројити седам недјеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Тада празнуј празник недјеља Господу Богу својему; што можеш приносити драговољно како те буде благословио Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'И весели се пред Господом Богом својим ти и син твој и кћи твоја и слуга твој и слушкиња твоја, и Левит који буде у мјесту твојем, и дошљак и сирота и удовица, што буду код тебе, на мјесту које изабере Господ Бог твој да ондје настани име своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'И опомињи се да си био роб у Мисиру, те чувај и твори уредбе ове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Празник сјеница празнуј седам дана, кад збереш с гумна својега и из каце своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'И весели се на празник свој ти и син твој и слуга твој и слушкиња твоја, и Левит и дошљак и сирота и удовица, што буду у мјесту твојем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Седам дана празнуј празник Господу Богу својему на мјесту које изабере Господ, кад те благослови Господ Бог твој у свакој љетини твојој и у сваком послу руку твојих; и буди весео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Три пута у години нека дође свако мушко пред Господа Бога твојега на мјесто које изабере: на празник пријеснијех хљебова, на празник недјеља и на празник сјеница, али нико да не дође празан пред Господа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Него сваки с даром од онога што има, према благослову Господа Бога твојега којим те је даривао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Судије и управитеље постави себи по свијем мјестима која ти да Господ Бог твој по племенима твојим, и нека суде народу право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Не изврћи правде и не гледај ко је ко; не примај поклона; јер поклон зашљепљује очи мудрима и изврће ријечи праведнима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Сасвијем иди за правдом, да би био жив и наслиједио земљу коју ти даје Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Не сади луга ни од каквијех дрвета код олтара Господа Бога својега, који начиниш;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'И не подижи никакога лика; на то мрзи Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Не приноси Господу Богу својему ни вола ни јагњета ни јарета на ком има мана или како год зло; јер је гадно пред Господом Богом твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Ако се нађе код тебе у којем од мјеста твојих, која ти да Господ Бог твој, човјек или жена да учини зло пред Господом Богом твојим преступајући завјет његов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'И отиде те служи другим боговима и клања им се, или сунцу или мјесецу или чему год из војске небеске, што нијесам заповиједио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'И теби се то јави и ти чујеш, онда распитај добро; па ако буде истина и доиста се учинила она гадна ствар у Израиљу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Изведи онога човјека или ону жену, који учинише оно зло, на врата своја, човјека онога или жену, и заспи их камењем да погину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'На свједочанство два или три човјека да се погуби онај кога ваља погубити; али на свједочанство једнога човјека да се не погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Свједоци нека први дигну руке на њ да га убију; а потом сав народ; тако извади зло из себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Кад ти буде тешко расудити између крви и крви, између распре и распре, или између ране и ране, око којих буде парница у твојем мјесту, тада устани и иди у мјесто које изабере Господ Бог твој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'И отиди к свештеницима Левитима или к судији који онда буде, па их упитај, и они ће ти казати како ваља пресудити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'И учини онако како ти кажу у мјесту које изабере Господ, и гледај да учиниш сасвијем онако како те науче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'По закону којему те науче, и по пресуди, коју ти кажу, учини; не отступи од онога што ти кажу ни надесно ни налијево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Ако ли би се ко упро те не би хтио послушати свештеника који ондје стоји те служи Господу Богу твојему, или судије, таки човјек да се погуби; и извади зло из Израиља,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Да сав народ чује и боји се, и у напредак да не ради упорно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Кад уђеш у земљу коју ти даје Господ Бог твој да је наслиједиш, и населиш се у њој, ако речеш: да поставим себи цара, као што имају сви народи око мене,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'Само онога постави себи за цара, којега изабере Господ Бог твој; између браће своје постави цара себи; а немој поставити над собом човјека туђина, који није брат твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Али да не држи много коња, и да не враћа народа у Мисир да би имао много коња, јер вам је Господ казао: не враћајте се више овијем путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'И да нема много жена, да се не би отпадило срце његово, ни сребра ни злата да нема врло много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'А кад сједе на пријесто царства својега, нека препише себи у књигу овај закон од свештеника Левита;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'И нека га држи код себе и нека га чита док је жив, да се учи бојати се Господа Бога својега, држати све ријечи овога закона и ове уредбе, и творити их;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Да се не би подигло срце његово изнад браће његове, и да не би отступило од ове заповијести ни надесно ни налијево, да би дуго царовао он и синови његови у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Свештеници Левити и све племе Левијево да немају дијела ни нашљедства с осталијем синовима Израиљевијем; нека једу огњене жртве Господње и његово нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Нашљедства дакле да немају међу браћом својом: Господ је нашљедство њихово, као што им је казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Али ово припада свештеницима од народа, од онијех који принесу жртву, било вола или јагње: да се даје свештенику плеће и обје вилице и желудац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Првине од жита својега, од вина својега и од уља својега, и првине од вуне с оваца својих подај му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Јер њега изабра Господ Бог твој између свих племена твојих да стоји и служи у име Господње он и синови његови довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'И кад дође који Левит из којега год мјеста твојега из свега Израиља, гдје настава, кад дође по жељи душе своје у мјесто које изабере Господ,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Нека служи у име Господа Бога својега као и друга браћа његова Левити, који ондје стоје пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Нека једу једнак дио, осим онога што би које продао у породици отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Кад уђеш у земљу коју ти Господ Бог твој даје, не учи се чинити гадна дјела онијех народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Нека се не нађе у тебе који би водио сина својега или кћер своју кроз огањ, ни врачар, ни који гата по звијездама, ни који гата по птицама, ни урочник,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Ни бајач, ни који се договара са злијем духовима, ни опсјенар ни који пита мртве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Јер је гад пред Господом ко год тако чини, и за таке гадове тјера те народе Господ Бог твој испред тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Држи се сасвијем Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Јер ти народи које ћеш наслиједити, слушају гатаре и врачаре; а теби то не допушта Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Пророка исред тебе, између браће твоје, као што сам ја, подигнуће ти Господ Бог твој; њега слушајте,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'По свему што си искао од Господа Бога својега на Хориву на дан сабора својега говорећи: да више не чујем гласа Господа Бога својега и да више не гледам огња тога великога, да не погинем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Зато ми рече Господ: добро рекоше што рекоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Пророка ћу им подигнути између браће њихове, као што си ти, и метнућу ријечи своје у уста његова, и казиваће им све што му заповједим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'А ко год не би послушао ријечи мојих, које ће говорити у моје име, од тога ћу ја тражити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Али пророк који би се усудио говорити што у моје име што му ја не заповиједим да говори, или који би говорио у име других богова, таки пророк да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Ако ли речеш у срцу својем: како ћемо познати ријеч које није Господ рекао?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Што би пророк рекао у име Господње, па се не збуде и не наврши се, то је ријеч које није рекао Господ; него је из охолости рекао онај пророк, не бој га се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Кад Господ Бог твој потре народе којих земљу даје теби Господ Бог твој, и кад их наслиједиш и настаниш се по градовима њиховијем и по кућама њиховијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Одвој три града усред земље своје, коју ти даје Господ Бог твој да је наслиједиш,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Начини пут, и раздијели на троје крајеве земље своје, коју ти да Господ Бог твој у нашљедство, па нека бјежи онамо сваки крвник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'А овако нека буде с крвником који утече онамо, да би остао жив: ко убије ближњега својега нехотице, не мрзивши прије на њ,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Као кад би ко отишао с ближњим својим у шуму да сијече дрва, па би замахнуо сјекиром у руци својој да посијече дрво, а она би спала с држалице и погодила би ближњега његова тако да умре он нека утече у који од тијех градова да остане жив,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'Да не би осветник потјерао крвника док му је срце распаљено и да га не би стигао на далеку путу и убио га, премда није заслужио смрти, јер није прије мрзио на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Зато ти заповиједам и велим: три града одвој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'А кад рашири Господ Бог твој међе твоје као што се заклео оцима твојим, и да ти сву земљу коју је рекао дати оцима твојим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'Ако уздржиш и уствориш све ове заповијести, које ти ја данас заповиједам, да љубиш Господа Бога својега и ходиш путовима његовијем свагда, онда додај још три града осим она три,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Да се не прољева крв права у земљи твојој, коју ти Господ Бог твој даје у нашљедство, и да не буде на теби крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Али ако ко мрзи на ближњега својега и вреба га, и скочи на њ, и удари га тако да умре, а он утече у који од тијех градова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'Онда старјешине мјеста његова нека пошљу и узму га оданде, и предаду га у руке осветнику да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Нека га не жали око твоје него скини крв праву с Израиља, да би ти добро било.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Не помичи међе близњега својега коју поставе стари у нашљедству твојем које добијеш у земљи коју ти Господ Бог твој даје да је наслиједиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Нека не устаје један свједок на човјека ни за како зло и ни за какав гријех између свијех гријеха који се чине, него на ријечима два или три свједока да остаје ствар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Ако би устао лажан свједок на кога да свједочи на њега да се одмеће Бога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'Онда нека стану та два човјека, који имају ту распру, пред Господа, пред свештенике и пред судије које буду у то вријеме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'И нека добро испитају судије; ако свједок онај буде лажан свједок и лажно свједочи на брата својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'Учините му онако како је он мислио учинити брату својему; и извади зло из себе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Да се остали чувши то боје, и у напредак више не чине тако зло усред тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Нека не жали око твоје: живот за живот, око за око, зуб за зуб, руку за руку, ногу за ногу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Кад отидеш на војску на непријатеља својега и видиш коње и кола и народ већи од себе, немој се уплашити од њих, јер је с тобом Господ Бог твој, који те је извео из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'И кад пођете да се побијете, нека приступи свештеник и проговори народу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'И нека им рече: слушај Израиљу! ви полазите данас у бој на непријатеље своје, нека не трне срце ваше, не бојте се и не плашите се, нити се препадајте од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Јер Господ Бог ваш иде с вама и биће се за вас с непријатељима вашим да вас сачува.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Потом и војводе нека проговоре народу, и реку: ко је саградио нову кућу а није почео сједети у њој? нека иде нек се врати кући својој, да не би погинуо у боју, и други почео сједети у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'И ко је посадио виноград а још га није брао? нека иде, нек се врати кући својој, да не би погинуо у боју, и други га брао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'И ко је испросио дјевојку а још је није одвео? нека иде, нек се врати кући својој, да не би погинуо у боју, и други је одвео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Још и ово нека кажу војводе народу и реку: ко је страшив и трне му срце? нека иде, нек се врати кући својој, да не би трнуло срце браћи његовој као њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'И кад војводе изговоре народу, онда нека намјесте главаре од чета пред народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Кад дођеш под који град да га бијеш, прво га понуди миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Ако ти одговори миром и отвори ти врата, сав народ који се нађе у њему нека ти плаћа данак и буде ти покоран.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Ако ли не учини мира с тобом него се стане бити с тобом, тада га биј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'И кад га Господ Бог твој преда у руке твоје, побиј све мушкиње у њему мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'А жене и дјецу и стоку и што год буде у граду, сав плијен у њему отми, и једи плијен од непријатеља својих, који ти да Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Тако чини са свијем градовима, који су далеко од тебе и нијесу од градова овијех народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'А у градовима овијех народа, које ти Господ Бог твој даје у нашљедство, не остави у животу ниједне душе живе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Него их затри сасвијем Хетеје и Амореје и Хананеје и Ферезеје и Јевеје и Јевусеје, као што ти је заповједио Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'Да вас не науче чинити гадна дјела која чинише боговима својим, и да ме згријешите Господу Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Кад опколиш какав град и будеш дуго под њим бијући га да би га узео, не квари дрвета његовијех сјекиром; јер можеш с њих јести, зато их не сијеци; јер дрво пољско је ли човјек да уђе у град испред тебе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Него дрвета која знаш да им се род не једе, њих обаљуј и сијеци и гради заклон од града који се бије с тобом, докле не падне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Кад се нађе убијен човјек у земљи коју ти даје Господ Бог твој да је наслиједиш, гдје лежи у пољу, а не зна се ко га је убио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'Тада нека изиду старјешине твоје и судије твоје, и нека измјере од убијенога до градова који су око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Па који град буде најближе убијенога, старјешине онога града нека узму јуницу из говеда, на којој се још није радило, која није вукла у јарму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'И нека одведу старјешине онога града ту јуницу у пусту долину гдје се не копа ни сије, и нека закољу јуницу ондје у долини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Потом нека приступе свештеници синови Левијеви; јер њих изабра Господ Бог твој да му служе и да благосиљају у име Господње, и на њиховијем ријечима да остаје свака распра и свака штета;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'И све старјешине онога града који буду најближе убијенога нека оперу руке своје над закланом јуницом у оној долини,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'И тврдећи нека реку: руке наше нијесу пролиле ове крви нити су очи наше видјеле;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Милостив буди народу својему Израиљу, који си искупио, Господе, и не мећи праве крви на народ свој Израиља. Тако ће се очистити од оне крви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'И ти ћеш скинути праву крв са себе кад учиниш што је право пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Кад отидеш на војску на непријатеље своје, и преда их Господ Бог твој у руке твоје и заробиш их много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'И угледаш у робљу лијепу жену, и омили ти да би је хтио узети за жену,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Одведи је кући својој; и нека обрије главу своју и среже нокте своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'И нека скине са себе хаљине своје у којима је заробљена, и нека сједи у кући твојој, и жали за оцем својим и за матером својом цио мјесец дана; потом лези с њом, и буди јој муж и она нек ти буде жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Ако ти послије не би била по вољи, пусти је нека иде куда јој драго, али никако да је не продаш за новце ни да њом тргујеш, јер си је осрамотио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Ко би имао двије жене, једну милу а другу немилу, па би родила синове, и мила и немила, и првенац би био од немиле,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'Онда кад дође вријеме да подијели синовима својим што има, не може првенцем учинити сина од миле преко сина од немиле који је првенац;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Него за првенаца нека призна сина од немиле и даде му два дијела од свега што има, је је он почетак силе његове, његово је право првеначко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Ко би имао сина самовољна и непокорна, који на слуша оца својега ни матере своје, и којега они и караше па опет не слуша,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'Нека га узму отац и мати, и нека га доведу к старјешинама града својега на врата мјеста својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'И нека кажу старјешинама града својега: овај син наш самовољан је и непокоран, на слуша нас, изјелица је и пијаница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Тада сви људи онога мјеста нека га заспу камењем да погине; и тако извади зло из себе, да сав Израиљ чује и боји се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Ко згријеши тако да заслужи смрт, те буде осуђен на смрт и објесиш га на дрво,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Нека не преноћи тијело његово на дрвету, него га исти дан погреби, јер је проклет пред Богом ко је објешен; зато не скврни земље коју ти Господ Бог твој даје у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Кад видиш вола или овцу брата својега гдје лута, немој проћи мимо њих, него их одведи брату својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Ако ли ти брат твој није близу или га не знаш, одведи их својој кући нека буду код тебе докле их не потражи брат твој, и тада му их врати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Тако учини и с магарцем његовијем и с хаљином његовом; и тако учини са сваком стварју брата својега изгубљеном, кад је изгуби а ти је нађеш, немој проћи мимо њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Кад видиш магарца или вола брата својега гдје је пао на путу, немој их проћи, него их подигни с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Жена да не носи мушкога одијела нити човјек да се облачи у женске хаљине, јер је гад пред Господом Богом твојим ко год тако чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Кад наиђеш путем на гнијездо птичије, на дрвету или на земљи, са птићима или са јајцима, а мајка лежи на птићима или на јајцима, немој узети мајке с птићима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Него пусти мајку а птиће узми, да би ти добро било и да би ти се продуљили дани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Кад градиш нову кућу, начини ограду око стрехе своје, да не би навукао крви на дом свој, кад би ко пао с њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Не сиј у винограду својем другога сјемена да не би оскврнио и род од сјемена које посијеш и род виноградски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Не ори на волу и на магарцу заједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Не облачи хаљине ткане од вуне и од лана заједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Начини себи ресе на четири краја од хаљине коју облачиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Ко се ожени, па му жена омрзне пошто легне с њом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'Па да прилику да се говори о њој и проспе рђав глас о њој говорећи: ожених се овом, али легавши с њом не нађох у ње дјевојаштва;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Тада отац дјевојчин и мати нека узму и донесу знаке дјевојаштва њезина пред старјешине града својега на врата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'И нека рече отац дјевојчин старјешинама: ову кћер своју дадох овому човјеку за жену, а он мрзи на њу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'И даде прилику да се говори о њој рекав: не нађох у твоје кћери дјевојаштва; а ево знака дјевојаштва кћери моје. И нека разастру хаљину пред старјешинама градским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Тада старјешина града онога нека узму мужа њезина и накарају га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'И нека га оглобе сто сикала сребра, које нека даду оцу дјевојчину зато што је изнио рђав глас на дјевојку Израиљку, и нека му буде жена; да је не може пустити док је жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Али ако буде истина, да се није нашло дјевојаштво у дјевојке,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'Тада нека изведу дјевојку на врат оца њезина, и нека је заспу камењем људи онога мјеста да погине, зато што учини срамоту у Израиљу курвавши се у дому оца својега. Тако извади зло из себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Ако се ко ухвати гдје лежи са женом удатом, нека се погубе обоје, човјек који је лежао са женом и жена. Тако извади зло из Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Кад дјевојка буде испрошена за кога, па је нађе когод у мјесту и облежи је,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'Изведите их обоје на врата онога мјеста, и заспите их камењем да погину, дјевојку што није викала у мјесту, а човјека што је осрамотио жену ближњега својега. Тако извади зло из себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Ако ли у пољу нађе човјек дјевојку испрошену, и силом је облежи, тада да се погуби само човјек који је облежа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'А дјевојци не чини ништа, није учинила гријеха који заслужује смрт, јер као кад ко скочи на ближњега својега и убије га, таква је и та ствар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Јер нађе је у пољу, и дјевојка испрошена вика, али не би никога да је одбрани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Ако ко нађе дјевојку која није испрошена и ухвати је и легне с њом, и затеку се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'Тада човјек онај који је легао с њом да да оцу дјевојчину педесет сикала сребра, и нека му она буде жена зато што је осрамоти; да је не може пустити док је жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Нико да се не жени женом оца својега, ни да открије скута оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'У сабор Господњи да не улази ни утучен ни ушкопљен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'У сабор Господњи да не улази копиле, ни десето кољено његово да не улази у сабор Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Ни Амонац ни Моавац да не улази у сабор Господњи, ни десето кољено њихово, да не улази у сабор Господњи довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Зато што не изидоше пред вас с хљебом и водом на путу кад сте ишли из Мисира, и што најмише за новце на вас Валама сина Веорова из Феторе у Месопотамији да те прокуне,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Премда не хтје Господ Бог твој слушати Валама, него ти Господ Бог твој обрати проклетство у благослов јер те милова Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Не тражи мира њихова ни добра њихова нигда за свога вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Немој се гадити на Идумејца, јер ти је брат; немој се гадити на Мисирца, јер си био дошљак у земљи његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Синови који се роде од њих у трећем кољену нека долазе у сабор Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Кад отидеш на војску на непријатеље своје, тада се чувај од сваке зле ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Ако се међу вама ко оскврни од чега што му се ноћу догоди, нека изиде иза окола и не улази у око.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'А пред вече нека се опере водом, па кад сунце зађе нека уђе у око.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'И имај мјесто иза окола гдје ћеш излазити напоље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'И имај лопатицу у оправи својој, па кад изидеш напоље, закопај њом, а кад пођеш натраг, загрни нечист своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Јер Господ Бог твој иде усред окола твојега да те избави и да ти преда непријатеље твоје; зато нека је око твој свет, да не види у тебе никакве нечистоте, да се не би одвратио од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Немој издати слуге господару његову, који утече к теби од господара својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Него нека остане код тебе, усред тебе, у мјесту које изабере у којем граду твом, гдје му буде драго; немој га цвијелити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Да не буде курве између кћери Израиљевијех, ни аџувана између синова Израиљевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Не носи у дом Господа Бога својега ни по каком завјету плате курвине ни цијене од пса, јер је обоје гад пред Господом Богом твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Не даји на добит брату својему ни новаца ни хране нити ишта што се даје на добит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Странцу подај на добит, али брату својему немој давати на добит, да би те благословио Господ Бог твој у свему што се прихватиш руком својом у земљи у коју идеш да је наслиједиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Кад учиниш завјет Господу Богу својему, не оклијевај испунити га, јер ће га тражити од тебе Господ Бог твој, и биће на теби гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Ако ли се не завјетујеш, неће бити на теби гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Што ти изиде из уста, оно држи и учини, као што завјетујеш Господу Богу својему драговољно, што изречеш устима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Кад уђеш у виноград ближњега својега, можеш јести грожђа по вољи док се не наситиш; али га не мећи у суд свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Кад уђеш у усјев ближњега својега, можеш тргати класје руком својом; али да не зажњеш српом у усјев ближњега својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Кад ко узме жену и ожени се с њом, па се догоди да му она не буде по вољи, што он нађе на њојзи штогод ружно, нека јој напише књигу распусну и да јој у руке, па нека је отпусти из своје куће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'А она отишавши из куће његове, ако отиде и уда се за другога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Па ако овај други муж омрзне на њу и напише јој књигу распусну и да јој у руку, и отпусти је из своје куће, или ако умре овај други муж који се ожени њом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Тада пређашњи муж који је отпусти не може је опет узети за жену, пошто се с њега она оскврнила, јер је гад пред Господом. Тако не дај да се гријеши земља коју ти Господ Бог твој даје у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Ко се скоро буде оженио, нека не иде на војску, и не намећи на њ никакога посла; нека буде слободан у кући својој годину дана и нека се радује са женом својом коју је довео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Нико да не узима у залогу жрвња горњега ни доњега, јер би узео душу у залогу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Ко се нађе да је украо човјека између браће своје, синова Израиљевих, и трговао њим и продао га, нека погине онај крадљивац; и тако извади зло из себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Чувај се болести губе, и пази добро и чини све што вас уче Левити, као што сам им заповиједио, држите и чините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Опомињи се шта је учинио Господ Бог твој Марији на путу кад изидосте из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Кад ти је ближњи твој дужан што му драго, не иди у кућу његову да му узмеш залог;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Него стој напољу, а човјек који ти је дужан нека ти изнесе напоље залог свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Ако је сиромах, не спавај са залогом његовијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Него му врати залог његов до захода сунчанога, да би лежећи на својој хаљини благосиљао те, а то ће ти се примити у правду пред Господом Богом твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Немој занијети најамника, сиромаха и потребитога између браће своје, и дошљака који је код тебе у земљи твојој у мјесту твојем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Подај му најам његов исти дан, и да га не зађе сунце у тебе, јер је сиромах и тијем душу држи, да не би завикао на те ка Господу, и било би ти гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Нека не гину оцеви за синове ни синови за оцеве; сваки за свој гријех нека гине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Не изврћи правице дошљаку ни сироти, и не узимај у залогу хаљине удовици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Него се опомињи да си био роб у Мисиру, и да те је искупио оданде Господ Бог твој; зато ти заповиједам да ово чиниш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Кад жањеш љетину своју на њиви својој, ако заборавиш који сноп на њиви, не враћај се да га узмеш; нека га дошљаку, сироти и удовици, да би те благословио Господ Бог твој у сваком послу руку твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Кад тресеш маслине своје, не загледај грану по грану пошто отресеш; нека дошљаку, сироти и удовици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Кад береш виноград свој, не пабирчи што обереш; нека дошљаку, сироти и удовици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'И опомињи се да се био роб у земљи Мисирској; зато ти ја заповиједам да ово чиниш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Кад је распра међу људима па дођу на суд да им суде, тада правога нека оправдају а кривога нека осуде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'И ако криви заслужује бој, тада судија нека заповједи да га повале и бију пред њим, на број према кривици његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'До четрдесет удараца нека заповједи да му ударе, не више, да се не би поништио брат твој у твојим очима, кад би му се ударило више удараца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Немој завезати уста волу кад врше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Кад браћа живе заједно па умре један од њих без дјеце, онда жена умрлога да се не уда из куће за другога; брат његов нека отиде к њој и узме је за жену и учини јој дужност дјеверску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'И први син којега она роди нека се назове именом брата његова умрлога, да не погине име његово у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Ако ли онај човјек не би хтио узети снахе своје, онда снаха његова нека дође на врата пред старјешине, и рече: неће дјевер мој да подигне брату својему сјемена у Израиљу, неће да ми учини дужности дјеверске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Тада нека га дозову старјешине мјеста онога и разговоре се с њим; па ако се он упре и рече: нећу да је узмем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'Онда нека приступи к њему снаха његова пред старјешинама, и нека му изује обућу с ноге његове и пљуне му у лице, и проговоривши нека рече: тако ваља да буде човјеку који неће да зида куће брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'И он нека се зове у Израиљу: дом босога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Ако би се свадили људи, један с другим, па би дошла жена једнога да отме мужа својега из руке другога који га бије, и пруживши руку своју ухватила би га за мошнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'Отсијеци јој руку; нека не жали око твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Немој имати у торби својој двојаку мјеру, велику и малу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Немој имати у кући својој двојаку ефу, велику и малу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Мјера потпуна и права нека ти је; ефа потпуна и права нека ти је, да би ти се продуљили дани твоји у земљи коју ти даје Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Јер је гад пред Господом Богом твојим ко год чини тако, ко год чини криво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Опомињи се шта ти је учинио Амалик на путу кад иђасте из Мисира,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Како те дочека на путу и поби на крају све уморне који иђаху за тобом, кад си био сустао и изнемогао, и не боја се Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Зато кад те Господ Бог твој смири од свијех непријатеља твојих унаоколо у земљи коју ти даје Господ Бог твој да је наслиједиш, тада затри спомен Амалику под небом; не заборави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'А кад уђеш у земљу коју ти даје Господ Бог твој у нашљедство, и наслиједиш је и населиш се у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'Узми првина од свакога воћа оне земље, које ћеш приносити од земље своје коју ти Господ Бог твој даје, и метнувши у котарицу иди на мјесто које Господ Бог твој изабере да ондје настани име своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'И дошавши к свештенику који буде онда реци му: признајем данас пред Господом Богом твојим да сам ушао у земљу за коју се Господ Бог заклео оцима нашим да ће нам је дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'А свештеник нека узме котарицу из твоје руке и метне је пред олтаром Господа Бога твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Тада проговори и реци пред Господом Богом својим: отац мој бијаше сиромах Сирин и сиђе у Мисир с мало чељади, и би ондје дошљак, па поста народ велик и силан и обилан на броју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Али Мисирци стадоше зло поступати с нама, мучише нас и удараше на нас тешке послове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'И ми заваписмо ка Господу Богу отаца својих, и Господ чу глас наш, и погледа на муку нашу, на труд наш и на невољу нашу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'И изведе нас Господ из Мисира руком крјепком и мишицом подигнутом, и страхотом великом и знацима и чудесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'И доведе нас на ово мјесто, и даде нам земљу ову, земљу у којој тече млијеко и мед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Зато сад ево донесох првине од рода ове земље коју си ми дао, Господе. И остави их пред Господом Богом својим, и поклони се пред Господом Богом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'И весели се сваким добром које ти да Господ Бог твој и дому твојему, ти и Левит и дошљак који је код тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'А кад даш све десетке од доходака својих треће године, које је године десетка, и даш Левиту, дошљаку, сироти и удовици да једу у мјестима твојим и насите се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Онда реци пред Господом Богом својим: изнесох из дома својега што је свето, и дадох Левиту и дошљаку, сироти и удовици сасвијем по заповијести коју си ми заповиједио, не преступих заповијести твојих нити заборавих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Не једох од тога у жалости својој, нити узех од тога на потребу нечисту, нити дадох од тога на мртваца; слушах Господа Бога својега, учиних све како си ми заповједио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Погледај из светога стана својега с неба, и благослови народ свој Израиља и земљу коју се нам дао као што си се заклео оцима нашим, земљу у којој тече млијеко и мед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Данас ти Господ Бог твој заповиједа да извршујеш ове уредбе и ове законе. Пази дакле и извршуј их од свега срца својега и од све душе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Данас си се зарекао Господу да ће ти бити Бог и да ћеш ићи путовима његовијем и држати уредбе његове, и заповијести његове и законе његове, и да ћеш слушати глас његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'А Господ се теби данас зарекао да ћеш му бити народ особит, као што ти је говорио, да би држао све заповијести његове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'И да ће те подигнути над све народе, које је створио хвалом, именом и славом, да будеш народ свет Господу Богу својему, као што ти је говорио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'И заповједи Мојсије са старјешинама Израиљевијем народу говорећи: држите све ове заповијести које вам ја данас заповиједам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'И кад пријеђеш преко Јордана у земљу коју ти даје Господ Бог твој, подигни себи камење велико и намажи га кречем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'И напиши на њему све ријечи овога закона, кад пријеђеш да уђеш у земљу коју ти даје Господ Бог твој, у земљу гдје тече млијеко и мед, као што ти је казао Господ Бог отаца твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Када дакле пријеђеш преко Јордана, подигни то камење, за које ти заповиједам данас, на гори Евалу, и намажи га кречем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'И начини ондје олтар Господу Богу својему, олтар од камења, али га немој гвожђем тесати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Од цијела камења начини олтар Господу Богу својему, и на њему принеси Господу Богу својему жртве паљенице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Принеси и захвалне жртве, и једи их ондје, и весели се пред Господом Богом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'И напиши на том камењу све ријечи овога закона добро и разговијетно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'И рече Мојсије и свештеници Левити свему Израиљу говорећи: пази и чуј Израиљу, данас си постао народ Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Зато слушај глас Господа Бога својега, и твори заповијести његове и уредбе његове, које ти ја данас заповиједам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'И заповједи Мојсије у онај дан народу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Ови нека стану да благосиљају народ на гори Гаризину, кад пријеђете преко Јордана: Симеун, Левије, Јуда, Исахар, Јосиф и Венијамин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'А ови нека стану да проклињу на гори Евалу: Рувим, Гад, Асир, Завулон, Дан и Нефталим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'И нека проговоре Левити, гласовито и реку свјема у Израиљу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Проклет да је човјек који би начинио лик резан или ливен, ствар гадну пред Господом, дјело руку умјетничких, ако би и на скривену мјесту метнуо. А сав народ одговарајући нека рече: амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Проклет да је који би ружио оца својега или матер своју. А сав народ нека рече: амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Проклет да је који би помакао међу ближњига својега. А сав народ нека рече: амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Проклет да је који би завео слијепца с пута. А сав народ нека рече: амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Проклет да је који би изврнуо правицу дошљаку, сироти или удовици. А сав народ нека рече: амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Проклет да је који би облежао жену оца својега, те открио скут оца својега. А сав народ нека рече: амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Проклет да је који би облежао какво год живинче. А сав народ нека рече: амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Проклет да је који би облежао сестру своју, кћер оца својега или кћер матере своје. А сав народ нека рече: амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Проклет да је који би облежао ташту своју. А сав народ нека рече: амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Проклет да је који би убио ближњега својега из потаје. А сав народ нека рече: амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Проклет да је који би примио какав поклон да убије човјека права. А сав народ нека рече: амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Проклет да је који не би остао на ријечима овога закона, и творио их. А сав народ нека рече: амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Ако добро узаслушаш глас Господа Бога својега држећи и творећи све заповијести његове, које ти ја данас заповиједам, узвисиће те Господ Бог твој више свијех народа на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'И доћи ће на те сви ови благослови, и стећи ће ти се, ако узаслушаш глас Господа Бога својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Благословен ћеш бити у граду, и благословен ћеш бити у пољу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Благословен ће бити плод утробе твоје, и плод земље твоје и плод стоке твоје, млад говеда твојих и стада оваца твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Благословена ће бити котарица твоја и наћве твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Благословен ћеш бити кад долазиш и благословен ћеш бити кад полазиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Даће ти Господ непријатеље твоје који устану на те да их бијеш; једнијем ће путем доћи на те, а на седам ће путова бјежати од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Господ ће послати благослов да буде с тобом у житницама твојим и у свему зашто се прихватиш руком својом, и благословиће те у земљи коју ти даје Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Поставиће те Господ да му будеш народ свет, као што ти се заклео, ако уздржиш заповијести Господа Бога својега и узидеш путовима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'И видјеће сви народи на земљи да се име Господње призива на тебе, и бојаће се тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'И учиниће Господ да си обилан сваким добром, плодом утробе своје и плодом стоке своје и плодом земље своје на земљи за коју се заклео Господ оцима твојим да ће ти је дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Отвориће ти Господ добру ризницу своју, небо, да да дажд земљи твојој на вријеме, и благословиће свако дјело руку твојих, те ћеш давати у зајам многим народима, а сам нећеш узимати у зајам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'И учиниће те Господ Бог твој да си глава а не реп, и бићеш само горе а нећеш бити доље, ако узаслушаш заповијести Господа Бога својега, које ти ја данас заповиједам, да их држиш и твориш,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'И не отступиш ни од једне ријечи коју вам ја данас заповиједам, ни надесно ни налијево, пристајући за другим боговима да им служиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Али ако не узаслушаш гласа Господа Бога својега да држиш и твориш све заповијести његове у уредбе његове, које ти ја данас заповиједам, доћи ће на тебе све ове клетве и стигнуће те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Проклет ћеш бити у граду, и проклет ћеш бити у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Проклета ће бити котарица твоја и наћве твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Проклет ће бити плод утробе твоје и плод земље твоје, млад говеда твојих и стада оваца твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Проклет ћеш бити кад долазиш, и проклет ћеш бити кад полазиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Послаће Господ на тебе клетву, расап и погибао у свему за што се прихватиш руком својом и што узрадиш, докле се не затреш и не пропаднеш на пречац за зла дјела своја којима си ме одуставио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Учиниће Господ Бог твој да се прилијепи за те помор, докле те не истријеби са земље у коју идеш да је наслиједиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Удариће те Господ сухом болешћу и врућицом, и грозницом и жегом и мачем, и сушом и медљиком, које ће те гонити докле не пропаднеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'А небо над главом твојом биће од мједи а земља под тобом од гвожђа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Учиниће Господ да дажд земљи твојој буде прах и пепео, који ће падати с неба на те, докле се не истријебиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Даће те Господ Бог твој непријатељима твојим да те бију; једнијем ћеш путем изаћи на њих, а на седам ћеш путова бјежати од њих, и потуцаћеш се по свијем царствима на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'И мртво тијело твоје биће храна свијем птицама небеским и звијерју земаљском, нити ће бити ко да их поплаши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Удариће те Господ приштевима Мисирским и шуљевима и шугом и крастама да се нећеш моћи исцијелити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Удариће те Господ лудилом и шљепотом и бјеснилом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'И пипаћеш у подне, као што пипа слијепац по мраку, нити ћеш имати напретка на путовима својим; и чиниће ти се криво и отимаће се од тебе једнако, и неће бити никога да ти поможе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Оженићеш се, а други ће спавати са твојом женом; сазидаћеш кућу, а нећеш сједети у њој; посадићеш виноград, а нећеш га брати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Во твој клаће се на твоје очи, а ти га нећеш јести; магарац твој отеће се пред тобом, и неће ти се вратити; овце твоје даће се непријатељу твојему, и неће бити никога да ти поможе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Синови твоји и кћери твоје даће се другому народу, а очи ће твоје гледати и капаће једнако за њима, а неће бити снаге у руци твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Род земље твоје и сву муку твоју изјешће народ, којега не знаш, и чиниће ти криво и газиће те једнако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'И полудјећеш од онога што ћеш гледати својим очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Удариће те Господ приштем злим у кољенима и на голијенима, да се нећеш моћи исцијелити, од стопала ноге твоје до тјемена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Одвешће Господ тебе и цара твојега, којега поставиш над собом, у народ којега нијеси знао ти ни стари твоји, и ондје ћеш служити другим боговима, дрвету и камену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'И бићеш чудо и прича и потсмијех свијем народима, у које те одведе Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Много ћеш сјемена изнети у поље, а мало ћеш сабрати, јер ће га изјести скакавци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Винограде ћеш садити и радићеш их, а нећеш пити вина нити ћеш их брати, јер ће изести црви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Имаћеш маслина по свијем крајевима својим, али се нећеш уљем намазати, јер ће опасти маслине твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Родићеш синове и кћери, али неће бити твоји; јер ће отићи у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Све воће твоје и род земље твоје изјешће бубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Странац који је код тебе попеће се нада те високо, а ти ћеш сићи доље веома ниско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Он ће ти давати у зајам, а ти нећеш њему давати у зајам; он ће постати глава, а ти ћеш постати реп.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'И доћи ће на те све ове клетве и гониће те и стизаће те, докле се не истријебиш, јер нијеси слушао гласа Господа Бога својега и држао заповијести његове и уредбе његове, које ти је заповиједио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'И оне ће бити знак и чудо на теби и на сјемену твојему довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Јер нијеси служио Богу својему радосна и весела срца у сваком обиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'И служићеш непријатељу својему, којега ће Господ послати на тебе, у глади и у жеђи, у голотињи и у свакој оскудици; и метнуће ти гвозден јарам на врат, докле те не сатре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Подигнуће на тебе Господ народ из далека, с краја земље, који ће долетјети као орао, народ, којему језика нећеш разумјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Народ бездушан, који неће марити за старца нити ће дјетета жалити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'И изјешће плод стоке твоје и плод земље твоје, докле се не истријебиш; и неће ти оставити ништа, ни жита ни вина ни уља, ни плода говеда твојих ни стада оваца твојих, докле те не затре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'И стегнуће те по свијем мјестима твојим, докле не попадају зидови твоји високо и тврди, у које се уздаш, по свој земљи твојој; стегнуће те по свијем мјестима твојим, по свој земљи твојој, коју ти даје Господ Бог твој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Те ћеш у тјескоби и у невољи којом ће ти притужити непријатељи твоји јести плод утробе своје, месо од синова својих и од кћери својих, које ти да Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Човјек који је био мек и врло њежан међу вама прозлиће се према брату својему и према милој жени својој и према осталијем синовима, који му остану,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Те неће дати никоме између њих меса од синова својих које ће јести, јер неће имати ништа друго у невољи и тјескоби, којом ће ти притужити непријатељ твој по свијем мјестима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Жена која је била мека и врло њежна међу вама, која од мекоте и њежности није била навикла стајати ногом својом на земљу, прозлиће се према миломе мужу свом и према сину свом и према кћери својој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'И постељици, која изиде између ногу њезинијех, и дјеци коју роди; јер ће их јести кришом у оскудици свакој од невоље и од тјескобе, којом ће ти притужити непријатељ твој по свијем мјестима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Ако не уздржиш и не уствориш све ријечи овога закона, које су написане у овој књизи, не бојећи се славнога и страшнога имена Господа Бога својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Пустиће Господ на тебе и на сјеме твоје зла чудесна, велика и дуга, болести љуте и дуге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'И обратиће на тебе све поморе Мисирске, од којих си се плашио, и прилијепиће се за тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'И све болести и сва зла, која нијесу записана у књизи овога закона, пустиће Господ на тебе, докле се не истријебиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'И остаће вас мало, а пређе вас бијаше много као звијезда небеских; јер нијеси слушао гласа Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'И као што вам се Господ радовао добро вам чинећи и множећи вас, тако ће вам се Господ радовати затирући вас и истребљујући вас; и нестаће вас са земље у коју идете да је наслиједите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'И расијаће те Господ по свима народима с једнога краја земље до другога, и ондје ћеш служити другим боговима, којих нијеси знао ти ни оци твоји, дрвету и камену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Али у онијем народима нећеш одахнути, нити ће се стопало ноге твоје одморити; него ће ти Господ дати ондје срце плашљиво, очи ишчиљеле и душу изнемоглу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'И живот ће твој бити као да виси према теби, и плашићеш се ноћу и дању, и нећеш бити миран животом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Јутром ћеш говорити: камо да је вече! а вечером ћеш говорити: камо да је јутро! од страха којим ће се страшити срце твоје, и од онога што ћеш гледати очима својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'И вратиће те Господ у Мисир на лађама, путем за који ти рекох: нећеш га више видјети. И ондје ћете се продавати непријатељима својим да будете робови и робиње, а неће бити купца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Ово су ријечи завјета који заповиједи Господ Мојсију да учини са синовима Израиљевијем у земљи Моавској, осим завјета који је учинио с њима на Хориву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'И сазва Мојсије све синове Израиљеве и рече им: видјели сте све што учини Господ на ваше очи у земљи Мисирској Фараону и свијем слугама његовијем и свој земљи његовој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Кушања велика, која видјеше очи твоје, оне знаке и чудеса велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Али вам не даде Господ срца, да разумијете, ни очију, да видите, и ушију да чујете до овога дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'И водих вас четрдесет година по пустињи; не оветшаше хаљине ваше на вама, нити обућа твоја оветша на ногама твојима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Хљеба не једосте, ни писте вина и силовита пића, да бисте познали да сам ја Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'И кад дођосте на ово мјесто, изиде Сион цар Есевонски и Ог цар Васански пред нас у бој; и побисмо их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'И узесмо земљу њихову, и дадосмо је у нашљедство племену Рувимову и племену Гадову и половини племена Манасијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Зато држите ријечи овога завјета и творите их, да бисте напредовали у свему што радите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Ви стојите данас сви пред Господом Богом својим, главари од племена ваших, старјешине ваше и управитељи ваши, сви људи Израиљци,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Дјеца ваша, жене ваше, и дошљак који је у вашем околу, и онај који ти дрва сијече, и онај који ти воду носи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Да пристанеш на завјет Господа Бога својега и на клетву његову, коју учини с тобом данас Господ Бог твој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Да те данас постави себи за народ и да ти он буде Бог, као што ти је рекао и као што се заклео оцима твојим, Авраму, Исаку и Јакову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'И не с вама самима чиним овај завјет и ову клетву;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Него са сваким који данас стоји овдје с нама пред Господом Богом нашим, и са сваким који није данас овдје с нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Јер ви знате како смо живјели у земљи Мисирској, и како смо прошли кроз народе кроз које смо прошли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'И видјели сте гадове њихове и идоле њихове од дрвета и од камена, од сребра и од злата, који су код њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Нека не буде међу вама човјека ни жене ни породице ни племена, којему би се срце одвратило данас од Господа Бога нашега да иде да служи боговима онијех народа; нека не буде међу вама коријена на ком би растао отров или пелен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'И чувши ријечи ове клетве да се не похвали у срцу свом говорећи: бићу миран ако узидем за онијем што у срцу свом смислим, додајући пијанство жеђи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Неће Господ опростити такоме, него ће се онда распалити гњев Господњи и ревност његова на такога човјека, и пашће на њ сва клетва која је написана у овој књизи, и истријебиће Господ име његово под небом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'И одлучиће га Господ на зло од свијех племена Израиљевијех по свијем клетвама завјета написанога у књизи овога закона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Тада ће говорити потоњи нараштај, синови ваши који настану иза вас, и дошљак који дође из далеке земље, кад виде зла у земљи овој и болести, које ће Господ пустити на њу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Земљу ову опаљену сумпором и сољу, гдје се не сије нити што ниче нити на њој расте кака биљка, као гдје је пропао Содом и Гомор, Адама и Севојим, које затр Господ у гњеву својему и у јарости својој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Говориће сви народи: зашто учини ово Господ од ове земље? каква је то жестина великога гњева?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'И одговараће се: јер одуставише завјет Господа Бога отаца својих, који учини с њима кад их изведе из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Јер идоше и служише другим боговима и поклањаше им се, боговима којих не знаше и који им ништа не дадоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Зато се Господ разгњеви на ту земљу, и пусти на њу сва проклетства написана у овој књизи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'И истријеби их Господ Бог из земље њихове у гњеву и јарости и љутини великој, и избаци их у другу земљу, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Што је тајно оно је Господа Бога нашега, а јавно је наше и синова наших довијека, да бисмо извршивали све ријечи овога закона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'А кад дође на тебе све ово, благослов и клетва коју изнесох преда те, ако их се опоменеш у срцу свом, гдје би год био међу народима, у које те загна Господ Бог твој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'И обратиш се ка Господу Богу својему и послушаш глас његов у свему што ти ја заповиједам данас, ти и синови твоји, из свега срца својега и из све душе своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'Тада ће Господ Бог твој повратити робље твоје и смиловаће се на тебе, и опет ће те сабрати између свијех народа, по којима те буде расијао Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Ако би ко твој и на крај свијета загнан био, отуда ће те опет сабрати Господ Бог твој и отуда те узети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'И одвешће те опет Господ Бог твој у земљу коју бијаху наслиједили оци твоји, и наслиједићеш је. и учиниће ти добро и умножиће те већма него оце твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'И обрезаће Господ Бог твој срце твоје и срце сјемена твојега, да би љубио Господа Бога својега из свега срца својега и из све душе своје, да будеш жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'А све клетве ове обратиће Господ Бог твој на непријатеље твоје и на ненавидинике твоје, који су те гонили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'А ти кад се обратиш и станеш слушати глас Господа Бога својега и творити све заповијести његове, које ти ја данас заповиједам,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Даће ти Господ Бог твој срећу у сваком дјелу руку твојих, у плоду утробе твоје, у плоду стоке твоје, у плоду земље твоје; јер ће ти се Господ Бог твој опет радовати чинећи ти добро, као што се радовао оцима твојим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Ако узаслушаш глас Господа Бога својега држећи све заповијести његове и уредбе његове, написане у књизи овога закона; кад се обратиш ка Господу Богу својему свим срцем својим и свом душом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Јер заповијест коју ти ја заповиједам данас нити је високо ни далеко од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Није на небу, да речеш: ко ће нам се попети на небо да нам је скине и каже нам је, да бисмо је творили?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Нити је преко мора, да речеш ко ће нам отићи преко мора, да нам је донесе и каже нам је, да бисмо је творили?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Него ти је врло близу ова ријеч, у устима твојима и у срцу твојем, да би је творио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Гле, изнесох данас преда те живот и смрт, добро и зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Јер ти заповиједам данас да љубиш Господа Бога својега ходећи путовима његовијем и држећи заповијести његове и уредбе његове и законе његове, да би жив био и умножио се, и да би те благословио Господ Бог твој у земљи у коју идеш да је наслиједиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Ако ли се одврати срце твоје и не узаслушаш, него застраниш да се клањаш другим боговима и њима служиш,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Јављам вам данас да ћете заиста пропасти, нити ћете продуљити дана својих на земљи, у коју идеш преко Јордана да је наслиједиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Свједочим вам данас небом и земљом, да сам ставио пред вас живот и смрт, благослов и проклетство; зато изабери живот, да будеш жив ти и сјеме твоје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Љубећи Господа Бога својега, слушајући глас његов и држећи се њега; јер је он живот твој и дуљина дана твојих; да би наставао на земљи, за коју се заклео Господ оцима твојим, Авраму, Исаку и Јакову, да ће им је дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Потом дође Мојсије и каза ове ријечи свему Израиљу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'И рече им: мени има данас сто и двадесет година, не могу више одлазити ни долазити; а и Господ ми је рекао: нећеш пријећи преко тога Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Господ ће Бог твој ићи пред тобом, и истријебиће оне народе испред тебе, и ти ћеш их наслиједити; Исус ће ићи пред тобом, као што је казао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'И учиниће Господ с њима како је учинио са Сионом и Огом царевима Аморејским и са земљом њиховом, те их је истријебио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Зато кад вам их преда Господ учините им сасвијем онако како сам вам заповиједио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Будите слободни и храбри, и не бојте их се и не плашите се од њих; јер Господ Бог твој иде с тобом, неће отступити од тебе, нити ће те оставити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Потом дозва Мојсије Исуса, и рече му пред свијем Израиљем: буди слободан и храбар; јер ћеш ући с овијем народом у земљу за коју се заклео Господ оцима њиховијем да ће им је дати, а ти ћеш им је раздијелити у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Јер Господ који иде пред тобом биће с тобом, неће отступити од тебе, нити ће те оставити, не бој се и не плаши се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'И Мојсије написа овај закон, и даде га свештеницима, синовима Левијевим, који ношаху ковчег завјета Господњега, и свијем старјешинама Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'И заповједи им Мојсије говорећи: сваке седме године, у одређено вријеме године опросне, на празник сјеница,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Кад дође сав Израиљ и стане пред Господа Бога својега на мјесту које изабере, читај овај закон пред свијем Израиљем да чују,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Сабравши народ, људе и жене дјецу и дошљаке, који буду у мјестима твојим, да чују и уче да се боје Господа Бога вашега, и држе и творе све ријечи овога закона;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'И синови њихови, који још не знају, нека чују и уче бојати се Господа Бога вашега, докле сте год живи на земљи у коју идете пријеко Јордана да је наслиједите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'А Господ рече Мојсију: ево, приближи се вријеме да умреш. Дозови Исуса и станите обојица у шатору од састанка, да му дам заповијести. И отиде Мојсије и Исус, и стадоше у шатору од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'И јави се Господ у шатору у ступу од облака, над вратима од шатора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'И рече Господ Мојсију: ево, ти ћеш починути с оцима својим; а народ овај уставши чиниће прељубу за туђим боговима оне земље у коју иде, и оставиће ме и поквариће завјет мој, који учиних с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'И онда ће се распалити мој гњев на њих, и оставићу их, и сакрићу лице своје од њих; они ће се прождријети, и снаћи ће их зла многа и невоље; и онда ће рећи: да ме не снађоше ова зла зато што Бог мој није посред мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'А ја ћу онда сасвијем сакрити лице своје за сва зла која учинише обративши се к другијем боговима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Зато сад напишите себи ову пјесму, и научи је синове Израиљеве; метни им је у уста да ми та пјесма буде свједок на синове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Јер ћу га одвести у земљу за коју сам се заклео оцима његовијем, у којој тече млијеко и мед; ондје ће јести и наситиће се и угојиће се, па ће се онда обратити к другијем боговима и њима ће служити, а за мене неће марити, и поквариће завјет мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'А кад га снађу зла многа и невоље, онда ће та пјесма свједочити на њих; јер се неће заборавити нити ће је нестати из уста сјемена њихова. Јер знам мисли њихове и што ће још данас чинити, прије него их уведем у земљу за коју сам се заклео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'И написа Мојсије ту пјесму онај дан, и научи синове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'И Господ даде заповијести Исусу Навину говорећи: буди слободан и храбар, јер ћеш ти увести синове Израиљеве у земљу за коју сам им се заклео и ја ћу бити с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'И кад написа ријечи овога закона у књигу, све до краја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Заповиједи Мојсије Левитима, који ношаху ковчег завјета Господњега, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Узмите ову књигу закона и метните је покрај ковчега завјета Господа Бога својега, да буде ондје свједок на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Јер знам непокорност твоју и тврди врат твој. Ето, докле сам још жив с вама, до данас, бијасте непокорни Господу; акамоли кад ја умрем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Скупите мени све старјешине од племена својих и управитеље своје да им кажем да чују ове ријечи, и да им засвједочим небом и земљом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Јер знам да ћете се по смрти мојој покварити, и заћи с пута који вам заповједих; и зато ће вас задесити ово зло најпослије, кад станете чинити што је зло пред Господом гњевећи га дјелом руку својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'И изговори Мојсије да чује сав збор Израиљев ријечи ове пјесме до краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Слушај, небо, говорићу; и земља нека чује говор уста мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Нека се спусти као дажд наука моја, и нека падне као роса говор мој, као ситан дажд на младу траву и као крупан дажд на одраслу траву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Јер ћу јављати име Господње; величајте Бога нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Дјело је те стијене савршено, јер су сви путови његови правда; Бог је вјеран, без неправде; праведан је и истинит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Они се покварише према њему; њихово неваљалство није неваљалство синова његовијех; то је род зао и покварен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Тако ли враћате Господу, народе луди и безумни? није ли он отац твој, који те је задобио? он те је начинио и створио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Опомени се негдашњих дана, погледајте године свакога вијека; питај оца својега и он ће ти јавити, старије своје и казаће ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Кад вишњи раздаде нашљедство народима, кад раздијели синове Адамове, постави међе народима по броју синова Израиљевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Јер је дио Господњи народ његов, Јаков је уже нашљедства његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Нађе га у земљи пустој, на мјесту страшну гдје бучи пустош; води га унаоколо, учи га и чува као зјеницу ока својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Као што орао измамљује орлиће своје, диже се над птићима својим, шири крила своја, узима их и носи на крилима својим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Тако га Господ вођаше, и с њим не бјеше туђега бога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Вођаше га на висине земаљске да једе род пољски, и даваше му да сиса мед из стијене и уље из тврдога камена,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Масло од крава и млијеко од оваца с претилином од јагањаца и овнова Васанских и јараца, са срцем зрна пшеничних; и пио си вино, крв од грожђа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Али се Израиљ угоји, па се стаде ритати; утио си, удебљао и засалио; па остави Бога који га је створио, и презре стијену спасења својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'На ревност раздражише га туђим боговима, гадовима разгњевише га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Приносише жртве ђаволима, не Богу, боговима, којих нијесу знали, новим, који из близа дођоше, којих се нијесу страшили оци ваши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Стијену која те је родила заборавио си; заборавио си Бога створитеља својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Кад то видје Господ, разгњеви се на синове своје и на кћери своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'И рече: сакрићу од њих лице своје, видјећу какав ће им бити пошљедак, јер су род покварен, синови у којима нема вјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Они ме раздражише на ревност онијем што није Бог, разгњевише својим таштинама; и ја ћу њих раздражити на ревност онијем који није народ, народом лудијем разљутићу их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Јер се огањ разгорио у гњеву мојем, и горјеће до најдубљега пакла; спалиће земљу и род њезин, и попалиће темеље брдима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Згрнућу на њих зла, стријеле своје побацаћу на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Глад ће их циједити, врућице и љути помори прождираће их; и зубе звјерске послаћу на њих и јед змија земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Споља ће их убијати мач, а по клијетима страх, и момка и дјевојку, дијете на сиси и сиједа човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Рекао бих: расијаћу их по свијем угловима земаљским, учинићу да нестане спомена њихова између људи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Да ми није до мржње непријатељеве, да се не би непријатељи њихови понијели и рекли: рука се наша узвисила, а није Господ учинио све ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Јер су народ који пропада са својих намјера, и нема у њих разума.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Камо да су паметни, да разумију ово, и гледају на пошљедак свој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Како би један гонио тисућу а двојица тјерала десет тисућа, да их није стијена њихова продала и Господ их предао?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Јер стијена њихова није као наша стијена; непријатељи наши нека буду судије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Јер је чокот њихов од чокота Содомскога и из поља Гоморскога; грожђе је њихово грожђе отровно, пуца су му горка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Вино је њихово отров змајевски, и љути јед аспидин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Није ли то сакривено код мене, запечаћено у ризницама мојим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Моја је освета и плата, у своје вријеме попузнуће нога њихова, јер је близу дан пропасти њихове, и иде брзо што ће их задесити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Судиће Господ народу својему, и жао ће му бити слуга његовијех, кад види да је прошла снага и да нема ништа ни од ухваћенога ни од остављенога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'И рећи ће: гдје су богови њихови? стијена у коју се уздаше?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Који сало од жртава његовијех једоше и пише вино од наљева њиховијех. Нека устану и помогу вам, и нека вам буду заклон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Видите сада да сам ја, ја сам, и да нема Бога осим мене. Ја убијам и оживљујем, раним и исцјељујем, и нема никога ко би избавио из моје руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Јер подижем к небу руку своју и кажем: ја сам жив довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Ако наоштрим сјајни мач свој и узмем у руку суд, учинићу освету на непријатељима својим и вратићу онима који мрзе на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Опојићу стријеле своје крвљу, и мач ће се мој најести меса, крвљу исјеченијех и заробљенијех, кад почнем освету на непријатељима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Веселите се народи с народом његовијем, јер ће покајати крв слуга својих, и осветиће се непријатељима својим, и очистиће земљу своју и народ свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'И дође Мојсије и изговори све ријечи пјесме ове народу, он и Исус син Навин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'А кад изговори Мојсије све ријечи ове свему Израиљу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Рече им: привијте срце своје к свијем ријечима које вам ја данас засвједочавам, и казујте их синовима својим да би држали све ријечи овога закона и творили их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Јер није празна ријеч да за њу не марите, него је живот ваш; и том ћете ријечју продуљити дане своје на земљи, у коју идете преко Јордана да је наслиједите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'У исти дан рече Господ Мојсију говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Изиди на ову гору Аваримску, на гору Навав, која је у земљи Моавској према Јерихону, и види земљу Хананску коју дајем синовима Израиљевијем у државу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'И умри на гори на коју изидеш, и прибери с к роду својему, као што је умро Арон брат твој на гори Ору и прибрао се к роду својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Јер ми згријешисте међу синовима Израиљевијем на води од свађе у Кадису, у пустињи Сину, што ме не прослависте међу синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Пред собом ћеш видјети земљу, али нећеш у њу ући, у земљу коју дајем синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'А ово је благослов којим благослови Мојсије човјек Божји синове Израиљеве пред смрт своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'И рече: Господ изиде са Синаја, и показа им се са Сира; засја с горе Фаранске, и дође с мноштвом тисућа светаца, а у десници му закон огњени за њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Доиста љуби народе; сви су свети његови у руци твојој; и они се слегоше к ногама твојим да приме ријечи твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Мојсије нам даде закон, нашљедство збору Јаковљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Јер бијаше цар у Израиљу, кад се сабираху кнезови народни, племена Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Да живи Рувим и да не умре, а људи његовијех да буде мало!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'А за Јуду рече: услиши Господ глас Јудин, и доведи га опет к народу његову; руке његове нека војују на њ, а ти му помажи против непријатеља његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'И за Левија рече: твој Тумим и твој Урим нека буду у човјека твојега светога, којега си окушао у Маси и с којим си се препирао на води Мериви;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Који рече оцу својему и матери својој: не гледам на вас; који не познаје браће своје и за синове своје не зна; јер држе ријечи твоје и завјет твој чувају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Они уче уредбама твојим Јакова и закону твојему Израиља, и мећу кад под ноздрве твоје и жртву што се сажиже на олтар твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Благослови, Господе, војску његову, и нека ти мило буде дјело руку његовијех; поломи бедре онима који устају на њ и који мрзе на њ, да не устану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'За Венијамина рече: мили Господу наставаће без страха с њим; заклањаће га сваки дан, и међу плећима његовијем наставаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'И за Јосифа рече: благословена је земља његова од Господа благом с неба, росом, и из дубине одоздо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'И благом које долази од сунца, и благом које долази од мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'И благом старијех брда и благом вјечнијех хумова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'И благом на земљи и обиљем њезинијем, и милошћу онога који стоји у купини. Нека то дође не главу Јосифу и на тјеме одвојеноме између браће своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Красота је његова као у првенца телета, и рогови његови као рогови у једнорога; њима ће бости народе све до краја земље; то је мноштво тисућа Јефремовијех и тисуће Манасијине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'А за Завулона рече: весели се Завулоне изласком својим, и Исахаре шаторима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Народе ће сазвати на гору, ондје ће принети жртве праведне; јер ће обиље морско сисати и сакривено благо у пијеску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'А за Гада рече: благословен је који шири Гада; он настава као лав, и кида руку и главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Изабра себи прво, јер ондје доби дио од онога који даде закон; зато ће ићи с кнезовима народнијем, и извршавати правду Господњу и судове његове с Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'А за Дана рече: Дан је лавић, који ће искакати из Васана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'И за Нефталима рече: Нефталиме, сити милости и пуни благослова Господњега, запад и југ узми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'И за Асира рече: Асир ће бити благослов мимо друге синове, биће мио браћи својој, замакаће у уље ногу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Гвожђе и мјед биће под обућом твојом; и докле трају дани твоји трајаће снага твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Израиљу! нико није као Бог, који иде по небу теби у помоћ, и у величанству својем на облацима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Заклон је Бог вјечни и под мишицом вјечном; он ће одагнати испред тебе непријатеље твоје, и рећи ће: затри!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Да би наставао Израиљ сам безбрижно, извор Јаковљев, у земљи обилној житом и вином; и небо ће његово покропити росом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Благо теби народе Израиљу! ко је као ти, народ којега је сачувао Господ, штит помоћи твоје, и мач славе твоје? Непријатељи ће се твоји понизити, а ти ћеш газити висине њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Тада изиде Мојсије из поља Моавскога на гору Нава, на врх Фазге, која је према Јерихону; и показа му Господ сву земљу од Галада до Дана;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'И сву земљу Нефталимову, и земљу Јефремову и Манасијину, и сву земљу Јудину до мора западнога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'И јужну страну, и равницу, долину под Јерихоном мјестом гдје има много палмових дрвета, до Сигора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'И рече му Господ: ово је земља, за коју сам се заклео Авраму, Исаку и Јакову говорећи: сјемену твојему даћу је. Показах ти да је видиш очима својима, али у њу нећеш ући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'И умрије ондје Мојсије слуга Господњи у земљи Моавској по ријечи Господњој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'А погребе га Господ у долини у земљи Моавској према Вет-Фегору; и нико не дозна за гроб његов до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'И бјеше Мојсију сто и двадесет година кад умрије, и не бјеху потамњеле очи његове нити га снага издала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'И плакаше синови Израиљеви за Мојсијем у пољу Моавском тридесет дана; и прођоше плачни дани жалости за Мојсијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'А Исус син Навин бјеше пун духа мудрости, јер Мојсије бјеше метнуо на њ руке своје. И слушаше га синови Израиљеви, и творише као што заповједи Господ преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Али не уста више пророк у Израиљу као Мојсије, којега Господ позна лицем к лицу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'У свијем знацима и чудесима, за која посла Господ да их учини у земљи Мисирској на Фараону и на свијем слугама његовијем и на свој земљи његовој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'И у свијем дјелима крјепке руке и у свијем страхотама великим, које учини Мојсије пред свијем Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'А по смрти Мојсија слуге Господњега рече Господ Исусу сину Навину, слузи Мојсијеву, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Мојсије слуга мој умрије; зато сада устани, пријеђи преко тога Јордана ти и сав тај народ у земљу коју ја дајем синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Свако мјесто на које ступите стопама својим дао сам вам, као што рекох Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Од пустиње и од овога Ливана до ријеке велике, ријеке Ефрата, сва земља Хетејска до великога мора на западу, биће међа ваша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Нико се неће одржати пред тобом свега вијека твојега; с тобом ћу бити као што сам био с Мојсијем, нећу отступити од тебе нити ћу те оставити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Буди слободан и храбар, јер ћеш ти предати томе народу у нашљедство земљу за коју сам се заклео оцима њиховијем да ћу им је дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Само буди слободан и храбар да држиш и твориш све по закону који ти је заповједио Мојсије слуга мој, не отступај од њега ни надесно ни налијево, да би напредовао куда год пођеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Нека се не раставља од уста твојих књига овога закона, него размишљај о њему дан и ноћ, да држиш и твориш све како је у њему написано; јер ћеш тада бити срећан на путовима својим и тада ћеш напредовати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Нијесам ли ти заповједио: буди слободан и храбар? не бој се и не плаши се; јер је с тобом Господ Бог твој куда год идеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Тада заповједи Исус управитељима народнијем говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Прођите кроз око и заповједите народу говорећи: спремите себи брашњенице; јер ћете до три дана пријећи преко Јордана да уђете и узмете земљу коју вам Господ Бог ваш даје у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'А племену Рувимову и Гадову и половини племена Манасијина рече Исус говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Опомените се шта вам је заповједио Мојсије слуга Господњи рекав: Господ Бог ваш смири вас и даде вам ову земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Жене ваше, дјеца ваша и стока ваша нека остану у земљи коју вам даде Мојсије с ову страну Јордана; ви пак пријеђите под оружјем пред браћом својом, који сте год за војску, и помозите им,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'Докле не смири Господ и браћу вашу као вас, и наслиједе и они земљу коју им даје Господ Бог ваш; па се онда вратите на нашљедство своје које вам је дао Мојсије слуга Господњи с ову страну Јордана к истоку, и држите га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'А они одговорише Исусу говорећи: што си нам год заповједио чинићемо, и куда нас год пошљеш ићи ћемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Слушаћемо те како смо слушали Мојсија; само нека Господ Бог твој буде с тобом као што је био с Мојсијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Ко би се противио твојој заповијести и не би слушао ријечи твојих у свему што му заповједиш, нека се погуби; само буди слободан и храбар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'А Исус син Навин посла из Ситима потајно двије уходе рекавши им: идите, видите земљу и Јерихон. И они отидоше, и дођоше у кућу једној курви, којој име бјеше Рава, и починуше ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Али би јављено цару Јерихонском и казано: ево, људи дођоше овамо ноћас између синова Израиљевих да уходе земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'И посла цар Јерихонски к Рави и поручи: изведи људе који су дошли к теби и ушли у твоју кућу, јер су дошли да уходе сву земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Али жена узевши она два човјека сакри их; па рече: јест истина да су људи дошли к мени, али ја не знах одакле бијаху;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'И кад се врата затвораху у сумрак, људи изидоше; не знам куда отидоше; идите брзо за њима; стигнућете их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'А она их бјеше извела на кров, и скрила их под лан нетрвен, који бијаше разастрла по крову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'И људи пођоше за њима у потјеру пут Јордана до брода; и врата се затворише кад изиде потјера за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Они пак још не бјеху поспали, а она дође к њима на кров,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'И рече им: знам да вам је Господ дао ову земљу, јер нас попаде страх од вас, и препали су се од вас сви који живе у овој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Јер чусмо како је Господ осушио пред вама Црвено Море кад изидосте из Мисира, и шта сте учинили од два цара Аморејска који бијаху преко Јордана, од Сиона и Ога, које побисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'И кад то чусмо, растопи се срце наше, и ни у коме већ нема јунаштва од страха вашега; јер је Господ, Бог ваш, Бог горе на небу и доље на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Него сада закуните ми се Господом да ћете учинити милост дому оца мојега као што ја вама учиних милост, и дајте ми знак истинит,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'Да ћете сачувати живот мојему оцу и мојој матери и мојој браћи и мојим сестрама и свјема њиховијем, и да ћете избавити душе наше од смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'А људи јој одговорише: ми ћемо изгинути за вас, ако не издате ове наше ствари; и кад нам Господ да ову земљу, учинићемо ти милост и вјеру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Тада их она спусти кроз прозор по конопцу; јер кућа њезина бјеше на зиду градском, и она на зиду наставаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'И рече им: идите у гору да не наиђе на вас потјера, и ондје се кријте три дана докле се не врати потјера, па онда идите својим путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'А људи јој рекоше: бићемо прости од ове твоје заклетве којом си нас заклела;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Ево, кад дођемо у земљу, вежи ову врвцу од скерлета на прозор, кроз који си нас спустила, и скупи код себе у ту кућу оца својега и матер и браћу и сав дом оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'И ко би год изашао из твоје куће, крв његова нека буде на његову главу, а ми да нијесмо криви; а ко год буде с тобом у кући, крв његова нека дође на наше главе, ако га се ко руком дотакне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Али ако издаш ову ствар нашу, тада ћемо бити прости од твоје заклетве, којом си нас заклела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'А она одговори: како рекосте тако нека буде. Тада их пусти, и отидоше; и она веза врвцу од скерлета на прозор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'А они отишавши дођоше у гору, и осташе ондје три дана докле се не врати потјера; јер их потјера тражаше по свијем путовима, али их не нађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'И вратише се она два човјека, и сишавши с горе пребродише и дођоше к Исусу сину Навину, и приповједише му све што им се догодило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'И рекоше Исусу: заиста дао нам је Господ у руке сву ту земљу, и сви становници оне земље уплашили су се од нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'И уста Исус у јутру рано, и кретоше се од Ситима и дођоше до Јордана он и сви синови Израиљеви, и ноћише ондје а не пријеђоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'А послије три дана прођоше управитељи кроз око,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'И заповједише народу говорећи: кад видите ковчег завјета Господа Бога својега и свештенике Левите гдје га носе, пођите и ви с мјеста својега и идите за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Али нека буде даљина између вас и њега до двије тисуће лаката; ближе до њега не примичите се, да бисте познали пут којим ћете ићи, јер још никада нијесте ишли тијем путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'И Исус рече народу: освештајте се, јер ће сјутра учинити Господ чудеса међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Потом рече Исус свештеницима говорећи: узмите ковчег завјетни и идите пред народом. И узеше ковчег завјетни и пођоше пред народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'А Господ рече Исусу: данас те почињем узвишивати пред свијем Израиљем да познаду да ћу и с тобом бити као што сам био с Мојсијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Зато ти заповједи свештеницима који носе ковчег завјетни, и реци: кад дођете на крај воде Јордана, станите у Јордану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'И рече Исус синовима Израиљевим: приступите овамо, и чујте ријечи Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'По том рече Исус: по овом ћете познати да је Бог живи посред вас, и да ће доиста одагнати испред вас Хананеје и Хетеје и Јевеје и Ферезеје и Гергесеје и Јевусеје:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Ево, ковчег завјета Господа свој земљи поћи ће пред вама преко Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'За то сада изберите дванаест људи из племена Израиљева, по једнога човјека из свакога племена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'И чим свештеници носећи ковчег завјета Господа Господа свој земљи стану ногама својим у води Јорданској, вода ће се у Јордану раступити, те ће вода која тече озго стати у гомилу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'И кад се подиже народ из шатора својих да пријеђе преко Јордана, и свештеници понесошеше ковчег завјетни пред народом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'И кад они што ношаху ковчег дођоше до Јордана, и свештеници носећи ковчег оквасише ноге своје на крају воде (јер је Јордан пун преко брегова својих за цијело вријеме жетве),');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'Устави се вода што тецијаше озго, и стаде у једну гомилу врло на далеко, од града Адама, који је крај Заретана; а што тецијаше доље у море крај поља, море слано, отече сасвијем; и народ прелажаше према Јерихону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'А свештеници који ношаху ковчег завјета Господњега стајаху на суху усред Јордана тврдо, сав Израиљ иђаше по суху, докле сав народ не пријеђе преко Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'А кад сав народ пријеђе преко Јордана, рече Господ Исусу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Изберите из народа дванаест људи, по једнога човјека из свакога племена,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'И заповједите им и реците: узмите одавде, исред Јордана, с мјеста гдје стоје ногама својим свештеници, дванаест камена, и однесите их са собом, и метните их ондје гдје ћете ноћас ноћити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Тада дозва Исус дванаест људи, које бјеше одредио између синова Израиљевих, по једнога човјека из свакога племена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'И рече им Исус: идите пред ковчег Господа Бога својега усред Јордана, и узмите сваки по један камен на раме своје, према броју племена синова Израиљевих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Да буде знак међу вама. Кад вас послије запитају синови ваши говорећи: шта ће вам то камење?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Реците им: јер се вода у Јордану раступи пред ковчегом завјета Господњега, кад прелажаше преко Јордана, раступи се вода у Јордану, и ово је камење спомен синовима Израиљевим довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'И учинише синови Израиљеви како заповједи Исус; и узеше дванаест камена исред Јордана, како бјеше рекао Господ Исусу, према броју племена синова Израиљевих; и однесоше их са собом на ноћиште, и метнуше их ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'А и усред Јордана постави Исус дванаест камена на мјесту гдје стајаху ногама својим свештеници носећи ковчег завјетни, и ондје осташе до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Свештеници пак који ношаху ковчег стајаху усред Јордана докле се не сврши све што бјеше Господ заповједио Исусу да каже народу, сасвијем како бјеше Мојсије заповједио Исусу. И народ похитје и пријеђе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'А кад пријеђе сав народ, онда пријеђе и ковчег Господњи и свештеници, а народ гледаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Пријеђоше и синови Рувимови и синови Гадови и половина племена Манасијина под оружјем пред синовима Израиљевим, као што им бјеше казао Мојсије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Око четрдесет тисућа наоружанијех пријеђоше пред Господом преко Јордана на бој у поље Јерихонско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Тај дан узвиси Господ Исуса пред свијем Израиљем; и бојаху га се као што су се бојали Мојсија, свега вијека његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'И рече Господ Исусу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Заповједи свештеницима који носе ковчег од сведочанства нека изиду из Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'И заповједи Исус свештеницима говорећи: изидите из Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'А чим свештеници који ношаху ковчег завјета Господњега изидоше исред Јордана, и стадоше на сухо ногом својом свештеници, одмах се поврати вода у Јордану на мјесто своје, и потече као и прије поврх свијех брегова својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'А изиде народ из Јордана десетога дана првога мјесеца, и стадоше у око у Галгалу, с истока Јерихону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'А онијех дванаест камена, што изнесоше из Јордана, постави Исус у Галгалу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'И рече синовима Израиљевим говорећи: кад у напредак запитају синови ваши оце своје говорећи: шта ће то камење?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Тада обавијестите синове своје, и реците им: сухим пријеђе Израиљ преко овога Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Јер Господ Бог ваш осуши Јордан пред вама докле пријеђосте, као што је учинио Господ Бог ваш од Црвенога Мора осушивши га пред нама докле пријеђосмо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'Да би познали сви народи на земљи да је рука Господња крјепка, да бисте се свагда бојали Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'А кад чуше сви цареви Аморејски, који бијаху с ову страну Јордана к западу, и сви цареви Ханански, који бијаху покрај мора, да је Господ осушио Јордан пред синовима Израиљевијем докле пријеђоше, растопи се срце у њима и неста у њима јунаштва од страха синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'У то вријеме рече Господ Исусу: начини оштре ноже, и обрежи опет синове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'И начини Исус оштре ноже, и обреза синове Израиљеве на брдашцу Аралоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'А ово је узрок за што их Исус обреза: сав народ што изиде из Мисира, све мушкиње, сви људи војници помријеше у пустињи на путу, пошто изидоше из Мисира;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Јер бјеше обрезан сав народ који изиде, али не обрезаше никога у народу који се роди у пустињи на путу, по што изидоше из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Јер четрдесет година иђаху синови Израиљеви по пустињи докле не помрије сав народ, људи војници, што изидоше из Мисира, јер не слушаше гласа Господњега, те им се закле Господ да им неће дати да виде земљу, за коју се заклео Господ оцима њиховијем да ће нам је дати, земљу, гдје тече млијеко и мед;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'И на мјесто њихово подиже синове њихове; њих обреза Исус, јер бијаху необрезани, јер их не обрезаше на путу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'А кад се сав народ обреза, осташе на својем мјесту у околу докле не оздравише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Тада рече Господ Исусу: данас скидох с вас срамоту Мисирску. И прозва се оно мјесто Галгал до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'И синови Израиљеви стојећи у околу у Галгалу, славише пасху четрнаестог дана онога мјесеца увече у пољу Јерихонском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'И сјутрадан послије пасхе једоше од жита оне земље хљебове пријесна и зрна пржена, исти дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'И преста мана сјутрадан пошто једоше жита оне земље, и већ више не имаше мане синови Израиљеви, него једоше од рода земље Ханаске оне године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'И кад Исус бијаше код Јерихона, подиже очи своје и погледа, а то човјек стоји према њему с голијем мачем у руци. И приступи к њему Исус и рече му: јеси ли наш или наших непријатеља?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'А он рече: нијесам; него сам војвода војске Господње, сада дођох. И Исус паде ничице на земљу, и поклони се, и рече му: шта заповиједа господар слузи својему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'А војвода војске Господње рече Исусу: изуј обућу с ногу својих, јер је мјесто гдје стојиш свето. И учини Исус тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'А Јерихон се затвори, и чуваше се од синова Израиљевих; нико не излажаше, нити ко улажаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'А Господ рече Исусу: ево, дајем ти у руке Јерихон и цара његова и јунаке његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Зато обидите око града сви војници, идући око града једанпут на дан; тако учини шест дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'А седам свештеника нека носе седам труба од рогова овнујских пред ковчегом; а седмога дана обидите око града седам пута, и свештеници нека трубе у трубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Па кад отежући затрубе у рогове овнујске, чим чујете глас од трубе, нека повиче сав народ иза гласа; и зидови ће градски попадати на својем мјесту, а народ нека улази, сваки напрема се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Тада Исус син Навин дозва свештенике, и рече им: узмите ковчег завјетни, а седам свештеника нека носе седам труба од рогова овнујских пред ковчегом Господњим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'А народу рече: идите и обидите око града, и војници нека иду пред ковчегом Господњим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'А кад Исус рече народу, седам свештеника носећи седам труба од рогова овнујских пођоше пред Господом, и затрубише у трубе, а ковчег завјета Господњега пође за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'А војници пођоше пред свештеницима, који трубљаху у трубе, а остали пођоше за ковчегом; идући трубљаху у трубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'А народу заповједи Исус говорећи: не вичите, и немојте да вам се чује глас, и ниједна ријеч да не изиде из уста ваших до дана кад вам ја кажем: вичите; тада ћете викати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Тако обиде ковчег Господњи око града једном; па се вратише у око, и ноћише у околу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'А сјутрадан уста Исус рано, и свештеници узеше ковчег Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'И седам свештеника носећи седам труба од рогова овнујских иђаху пред ковчегом Господњим, и идући трубљаху у трубе; а војници иђаху пред њима, а остали иђаху за ковчегом Господњим; идући трубљаху у трубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'И обидише око града једном другога дана, па се вратише у око; тако учинише шест дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'А седмога дана усташе зором, и обидоше око града исто онако седам пута; само тога дана обидоше око града седам пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'А кад би седми пут да затрубе свештеници у трубе, Исус рече народу: вичите, јер вам Господ даде град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'А град да буде проклет Господу и што је год у њему; само Рава курва нек остане у животу и сви који буду код ње у кући, јер сакри посланике које бијасмо послали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Али се чувајте од проклетијех ствари да и сами не будете проклети узевши што проклето, и да не навучете проклетство на око Израиљев и сметете га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Него све сребро и злато и посуђе од мједи и од гвожђа нека буде свето Господу, нека уђе у ризницу Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Тада повика народ и затрубише трубе, и кад народ чу глас трубни и повика иза гласа, попадаше зидови на мјесту свом; и народ уђе у град, сваки напрема се; и узеше град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'И побише као проклето оштријем мачем све што бјеше у граду, и жене и људе, и дјецу и старце, и волове и овце и магарце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'А оној двојици што уходише земљу рече Исус: идите у кућу оне жене курве, и изведите њу и све што је њезино, као што сте јој се заклели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'И отишавши они момци што уходише земљу, изведоше Раву и оца јој и матер јој и браћу јој и што год бјеше њезино, и сав род њезин изведоше, и оставише их иза окола Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'А град спалише огњем и што бјеше у њему; само сребро и злато и посуђе од мједи и од гвожђа метнуше у ризницу дома Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'А Раву курву и дом оца њезина и све што бјеше њезино остави у животу Исус, и она оста међу Израиљцима до данас, јер сакри посланике које посла Исус да уходе Јерихон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'И у то вријеме прокле Исус говорећи: проклет да је пред Господом човјек који би устао да гради овај град Јерихон! на првенцу свом основао га, и на мјезинцу свом поставио му врата!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'И Господ бијаше са Исусом, и разгласи се име његово по свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Али се огријешише синови Израиљеви о проклетињу, јер Ахан син Хармије сина Завдије сина Зарина од племена Јудина узе од проклетијех ствари; зато се разгњеви Господ на синове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'А Исус посла људе из Јерихона у Гај, који бијаше близу Вет-Авена с истока Ветиљу, и рече им говорећи: идите и уходите земљу. И људи отидоше и уходише Гај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'И вративши се к Исусу рекоше му: нека не иде сав народ; до двије тисуће људи или до три тисуће људи нека иду, и освојиће Гај; немој трудити свега народа, јер их је мало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'И отиде их онамо из народа око три тисуће људи; али побјегоше од Гајана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'И Гајани посјекоше их до тридесет и шест људи; и гонише их од врата дори до Сиварима, и побише их на стрмени; и растопи се срце у народу, и поста као вода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'А Исус раздрије хаљине своје и паде лицем на земљу пред ковчегом Господњим, и лежа до вечера, он и старјешине Израиљеве, и посуше се прахом по глави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'И рече Исус: јаох! Господе Боже, зашто преведе онај народ преко Јордана да нас предаш у руке Аморејцима да нас побију? о, да шћасмо остати преко Јордана!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Јаох! Господе, шта да кажем, кад је Израиљ обратио плећи пред непријатељима својим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Чуће Хананеји и сви становници те земље, и слећи ће се око нас, и истријебиће име наше са земље; и шта ћеш учинити од великога имена својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'А Господ рече Исусу: устани; што си пао на лице своје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Згријешио је Израиљ, и преступио завјет мој који сам им заповједио: јер узеше од проклетијех ствари, и украдоше, и затајише, и метнуше међу своје ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Зато неће моћи синови Израиљеви стајати пред непријатељима својим; плећа ће обраћати пред непријатељима својим, јер су под проклетством; нећу више бити с вама, ако не истријебите између себе проклетиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Устани, освештај народ, и реци: освештајте се за сјутра; јер овако вели Господ Бог Израиљев: проклетство је усред тебе, Израиљу; нећеш моћи стајати пред непријатељима својим докле не уклоните проклетства између себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Приступићете ујутру по племенима својим; и које племе обличи Господ оно ће приступити по породицама својим, и коју породицу обличи Господ она ће приступити по домовима својим; и који дом обличи Господ, приступиће људи из њега један по један.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Па ко се нађе у проклетству, нека се спали огњем и он и све његово, јер преступи завјет Господњи и учини безакоње у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'И уставши Исус ујутру рано рече те приступи Израиљ по племенима својим; и обличи се племе Јудино.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Потом рече те приступише породице Јудине; и обличи се породица Зарина; потом рече те приступи породица Зарина, домаћин један по један, и обличи се Завдија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'И рече, те приступи његов дом, људи један по један, и обличи се Ахан син Хармије сина Завдије сина Зарина од племена Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'И рече Исус Ахану: сине, хајде дај хвалу Господу Богу Израиљеву, и признај пред њим, и кажи ми шта си учинио, немој тајити од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'А Ахан одговори Исусу и рече: истина је, ја згријеших Господу Богу Израиљеву, и учиних тако и тако:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Видјех у плијену један лијеп плашт Вавилонски, и двјеста сикала сребра, и једну шипку злата од педесет сикала, па се полакомих и узех; и ено је закопано у земљу усред мојега шатора, и сребро оздо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Тада Исус посла посланике, који отрчаше у шатор, и гле, бјеше закопано у шатору његову, и оздо сребро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'И узеше из шатора и донесоше к Исусу и свијем синовима Израиљевијем, и метнуше пред Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Тада Исус и сав Израиљ узеше Ахана сина Зарина, и сребро и плашт и шипку злата, и синове његове и кћери његове, и волове његове и магарце његове, и овце његове, и шатор и све што бјеше његово, и изведоше у долину Ахор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'И рече Исус: што си нас смео? Господ да те смете данас! И засу га камењем сав Израиљ, и спалише све огњем засувши камењем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Потом набацаше на њ велику гомилу камења, која стоји и данас. И Господ се поврати од жестине гњева својега. Отуда се прозва оно мјесто долина Ахор до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Иза тога рече Господ Исусу: не бој се и не плаши се; узми са собом сав народ што је за бој, па устани и иди на Гај; ево предадох ти у руке цара Гајскога и народ његов и град његов и земљу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'И учини с Гајем и царем његовијем како си учинио с Јерихоном и његовијем царем; али плијен из њега и стоку његову разграбите за се. Намјести засједу иза града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'И уста Исус и сав народ што бјеше за бој, да иду на Гај; и изабра Исус тридесет тисућа јунака, и посла их ноћу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'И заповједи им говорећи: гледајте ви који ћете бити у засједи иза града, да не будете врло далеко од града, него будите сви готови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'А ја и сав народ што је са мном примакнућемо се ка граду; па кад они изиду пред нас, ми ћемо као и прије побјећи испред њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Те ће они поћи за нама докле их не одвојимо од града, јер ће рећи: бјеже испред нас као и прије. И ми ћемо бјежати испред њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Тада ви изидите из засједе и истјерајте из града што буде остало. Јер ће вам га дати Господ Бог ваш у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'А кад узмете град, запалите га огњем; по ријечи Господњој учините. Ето, заповједио сам вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Тако их посла Исус, и они отидоше у засједу, и стадоше између Ветиља и Гаја, са запада Гају; а Исус преноћи ону ноћ међу народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'А ујутру уста Исус рано и преброји народ, па пође са старјешинама Израиљевијем пред народом на Гај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'И сва војска што бјеше с њим пође и примакавши се дођоше према граду и стадоше у око са сјевера Гају; а бијаше долина између њих и Гаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'И узе око пет тисућа људи, и намјести их у засједу између Ветиља и Гаја, са запада граду Гају..');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'И кад се намјести сав народ, сва војска, што бијаше са сјевера граду и што бијаше у засједи са запада граду, изиде Исус ону ноћ усред долине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'И кад то видје цар Гајски, људи у граду похитјеше и уранише; и изидоше онај час у поље пред Израиља у бој, цар и сав народ његов. А не знађаше да има засједа за њим иза града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Тада Исус и сав Израиљ, као да их побише, нагоше бјежати к пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'А они сазваше сав народ што бјеше у граду да их тјерају. И тјераше Исуса, и одвојише се од свога града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'И не оста нико у Гају ни у Ветиљу да не пође за Израиљем; и оставише град отворен, и тјераху Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Тада рече Господ Исусу: дигни заставу што ти је у руци према Гају, јер ћу ти га дати у руке. И подиже Исус заставу што му бјеше у руци према граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'А они што бијаху у засједи одмах усташе са својега мјеста, и потрчаше чим он подиже руку своју, и уђоше у град и узеше га, и брзо запалише град огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'А кад се Гајани обазреше, а то дим од града дизаше се до неба, и не имаху куда бјежати ни тамо ни амо; а народ који бјежаше у пустињу поврати се на оне који га тјераху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'И Исус и сав Израиљ видјевши да је засједа њихова узела град и гдје се диже дим од града, вратише се и ударише на Гајане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'А они из града изидоше пред њих, те бијаху међу Израиљцима одовуд и одонуд, и побише их тако да ниједан не оста жив нити утече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'А цара Гајскога ухватише жива и доведоше к Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'А кад побише Израиљци све Гајане у пољу, у пустињи, куда их гонише, и падоше сви од оштрога мача, те се истријебише, онда се вратише сви Израиљци у Гај, и исјекоше што још бјеше у њему оштријем мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'А свијех што изгибоше онај дан, и људи и жена, бјеше дванаест тисућа, самијех Гајана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'И Исус не спусти руке своје, коју бјеше подигао са заставом, док не побише све становнике Гајске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Само стоку и плијен из града онога разграбише Израиљци за се, као што бјеше Господ заповједио Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'И Исус спали Гај, и обрати га у гомилу вјечну, и у пустош до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'А цара Гајскога објеси на дрво и остави до вечера; а о заходу сунчаном заповиједи Исус те скидоше тијело његово с дрвета и бацише пред врата градска, и набацише на њ велику гомилу камења, која стоји и данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Тада Исус начини олтар Господу Богу Израиљеву на гори Евалу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'Као што бјеше заповједио Мојсије слуга Господњи синовима Израиљевим, као што пише у књизи закона Мојсијева, олтар од цијелога камења, преко којега није превучено гвожђе; и принесоше на њему жртве паљенице Господу, и принесоше жртве захвалне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'И преписа ондје на камењу закон Мојсијев, који је написао синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'И сав Израиљ и старјешине његове и управитељи и судије његове стадоше с обје стране ковчега, према свештеницима Левитима, који ношаху ковчег завјета Господњега, и странац и домородац; половина према гори Гаризину а половина према гори Евалу, као што бјеше заповједио Мојсије слуга Господњи да благослови народ Израиљев најприје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'И потом прочита све ријечи закона, благослов и проклетство, све како је написано у књизи закона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Не би ни једне ријечи од свега што је Мојсије написао, које не прочита Исус пред свијем збором Израиљевим, и женама и дјецом и странцима који иђаху међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'А кад то чуше сви цареви који бијаху с ову страну Јордана по брдима и по долинама и по свему бријегу великога мора дори до Ливана, Хетејин и Аморејин, Хананејин, Ферезејин, Јевејин и Јевусејин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Скупише се сви да се сложно бију с Исусом и с Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'А који живљаху у Гаваону чувши шта учини Исус од Јерихона и од Гаја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Учинише и они пријевару; јер отидоше и начинише се посланици, и узеше старе торбе на своје магарце и старе мјехове винске, подеране и искрпљене,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'И обућу стару и искрпљену на ноге своје, и хаљине старе на се; и сав хљеб што понесоше на пут бјеше сух и пљеснив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'И отидоше к Исусу у око у Галгалу, и рекоше њему и људима Израиљцима: дођосмо из даљне земље; хајде ухватите вјеру с нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'А људи Израиљци рекоше Јевејима: може бити да сједите усред нас, па како ћемо ухватити вјеру с вама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Али они рекоше Исусу: ми смо слуге твоје. А Исус им рече: ко сте и откуда идете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'А они му рекоше: из земље врло даљне дођоше слуге твоје у име Господа Бога твојега; јер чусмо славу његову и све што је учинио у Мисиру,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'И све што је учинио двојици царева Аморејских, који бијаху с ону страну Јордана, Сиону цару Есевонском и Огу цару Васанском који бијаше у Астароту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'И рекоше нам старјешине наше и сви становници наше земље говорећи: узмите брашњенице на пут, и идите им на сусрет и реците им: ми смо слуге ваше, хајде ухватите вјеру с нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Ово је хљеб наш: врућ смо понијели на пут од кућа својих кад смо пошли пред вас, а сад ето осушио се и упљеснивио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'А ово су мјехови вински: налисмо нове, и ето су се већ подерали; и хаљине наше и обућа наша оветша од даљнога пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'И повјероваше људи по брашњеници, а не упиташе Господа шта ће рећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'И Исус учини с њима мир, и зададе им вјеру да ће их оставити у животу; и заклеше им се кнезови од збора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Али послије три дана кад ухватише вјеру с њима, чуше да су им сусједи и да живе усред њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Јер пођоше синови Израиљеви и дођоше у градове њихове трећи дан; а градови им бијаху: Гаваон и Кефира и Вирот и Киријат-Јарим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'И не побише их синови Израиљеви, јер им се кнезови од збора заклеше Господом Богом Израиљевијем. Али сав збор викаше на кнезове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Тада сви кнезови рекоше свему збору: ми смо им се заклели Господом Богом Израиљевијем; зато сада не можемо дирати у њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Учинимо им то, и оставимо их у животу, да не дође гњев на нас ради заклетве којом им се заклесмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Још им рекоше кнезови: нека остану у животу, па нека сијеку дрва и носе воду свему збору како им кнезови казаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Потом их дозва Исус и рече им говорећи: зашто нас преваристе и рекосте: врло смо далеко од вас, кад ето живите усред нас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Зато сада да сте проклети и да сте довијека робови и да сијечете дрва и носите воду за дом Господа Бога мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'А они одговорише Исусу и рекоше: доиста је било јављено слугама твојим како је заповједио Господ Бог твој Мојсију слузи својему да вам да сву ову земљу и да истријеби све становнике ове земље испред вас; стога се врло побојасмо животу својему од вас и учинисмо тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'А сада ето смо ти у руку; чини што мислиш да је добро и право да с нама учиниш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'И учини им тако и сачува их од руку синова Израиљевијех, те их не побише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'И одреди их Исус у тај дан да сијеку дрва и носе воду збору и за олтар Господњи до данашњега дана на мјесту које избере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'А кад чу Адониседек цар Јерусалимски да је Исус узео Гај и раскопао га, као што је учинио с Јерихоном и његовијем царем, тако даје учинио и с Гајем и његовијем царем, и да су Гаваоњани учинили мир с Израиљем и стоје усред њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'Уплаши се врло; јер Гаваон бијаше велик град као какав царски град, и бијаше већи од Гаја, и сви људи у њему бијаху храбри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Зато посла Адониседек цар Јерусалимски к Оаму цару Хевронском и к Пираму цару Јармутском и к Јафији цару Лахиском и к Давиру цару Јеглонском, и поручи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Ходите к мени, и помозите ми да ударимо на Гаваон, јер учини мир с Исусом и са синовима Израиљевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'И скупи се и пође пет царева Аморејских, цар Јерусалимски, цар Хевронски, цар Јармутски, цар Лахиски, цар Јеглонски, они и сва војска њихова, и ставши у око под Гаваоном почеше га бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Тада Гаваоњани послаше к Исусу у око у Галгалу и рекоше: немој дигнути руку својих са слуга својих; ходи брзо к нама, избави нас и помози нам, јер се скупише на нас сви цареви Аморејски који живе у горама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'И изиде Исус из Галгала, он и с њим сав народ што бјеше за бој, сви јунаци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'И Господ рече Исусу: не бој их се; јер их дадох теби у руке, ниједан их се неће одржати пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'И Исус удари на њих изненада, ишавши цијелу ноћ од Галгала,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'И смете их Господ пред Израиљем, који их љуто поби код Гаваона, па их потјера путем како се иде у Вет-Орон, и сјекоше их до Азике и до Макиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'А кад бјежаху испред Израиља и бијаху низ врлет Вет-оронску, баци Господ на њих камење велико из неба дори до Азике, те гињаху: и више их изгибе од камења граднога него што их побише синови Израиљеви мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Тада проговори Исус Господу онај дан кад Господ предаде Аморејца синовима Израиљевијем, и рече пред синовима Израиљевијем: стани сунце над Гаваоном, и мјесече над долином Елонском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'И стаде сунце и устави се мјесец, докле се не освети народ непријатељима својим. Не пише ли то у књизи истинитога? И стаде сунце насред неба и не наже к западу скоро за цио дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'И не би такога дана ни прије ни послије, да Господ послуша глас човјечји, јер Господ војева за Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'И врати се Исус и сав Израиљ с њим у око у Галгал.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'А онијех пет царева утекоше и сакрише се у пећину код Макиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'И дође глас Исусу: нађе се пет царева сакривенијех у пећини код Макиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'А Исус рече: привалите велико камење на врата пећини, и намјестите људе од ње да их чувају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'А ви не стојте, него гоните непријатеље своје и бијте остатак њихов, не дајте им да уђу у градове своје, јер вам их даде у руке Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'А кад Исус и синови Израиљеви престаше бити их у боју врло великом, разбивши их сасвијем, а који их осташе живи, утекоше у тврде градове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Врати се сав народ здраво у око к Исусу у Макиду, и нико не маче језиком својим на синове Израиљеве, ни на једнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Тада рече Исус: отворите врата од оне пећине, и изведите к мени онијех пет царева из пећине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'И учинише тако, и изведоше к мени онијех пет царева из пећине: цара Јерусалимскога, цара Хевронскога, цара Јармутскога, цара Лахискога, цара Јеглонскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'А кад изведоше те цареве к Исусу, сазва Исус све људе Израиљце, и рече војводама од војске које бијаху ушле с њим: приступите и станите ногама својим на вратове овијем царевима. И они приступише и стадоше им на вратове ногама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'А Исус им рече: не бојте се и не плашите се; будите слободни и храбри, јер ће тако учинити Господ свијем непријатељима вашим на које завојштите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Потом их поби Исус и погуби их, и објеси их на пет дрвета, и осташе висећи на дрветима до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'А о заходу сунчаном заповједи Исус те их скидоше с дрвета и бацише их у пећину, у коју се бијаху сакрили, и метнуше велико камење на врата пећини, које оста ондје до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Истога дана узе Исус и Макиду, и све у њој исијече оштријем мачем, и цара њезина и њих поби, све душе које бјеху у њој, не остави ниједнога жива; и учини с царем Макидским као што учини с царем Јерихонским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Потом отиде Исус и сав Израиљ с њим из Макиде у Ливну, и стаде бити Ливну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Па и њу предаде Господ у руке Израиљу и цара њезина; и исијече све оштријем мачем, све душе које бијаху у њој, не остави у њој ниједнога жива; и учини с царем њезинијем као што учини с царем Јерихонским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Потом отиде Исус и сав Израиљ с њим из Ливне на Лахис, и стаде у око пред њим, и стаде га бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'И Господ предаде Лахис у руке Израиљу, и он га узе сјутрадан, и исијече све оштријем мачем, све душе што бијаху у њему, исто онако како учини с Ливном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Тада дође Орам цар Гезерски у помоћ Лахису; али поби Исус њега и народ његов да не оста ниједан жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Потом пође Исус и сав Израиљ с њим из Лахиса на Јеглон, и ставши у око према њему ударише на њ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'И узеше га исти дан, и исјекоше све оштријем мачем; све душе што бијаху у њему поби тај дан исто онако како учини с Лахисом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Потом се подиже исус и сав Израиљ с њим из Јеглона на Хеврон, и стадоше га бити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'И узеше га и исјекоше оштријем мачем, и цара његова и све градове његове, све душе што бијаху у њима; не остави ниједнога жива исто онако како учини с Јеглоном; затр га са свијем душама што бијаху у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Потом се обрати Исус и сав Израиљ с њим на Давир, и стаде га бити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'И узе га и цара његова и све градове његове, и исјекоше их оштријем мачем и згубише све душе што бијаху у њима; не остави ниједнога жива; као што учини с Хевроном, тако учини с Давиром и царом његовијем, и као што учини с Ливном и царем њезинијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Тако поби Исус сву земљу, горе и јужну страну и равнице и долине, и све цареве њихове; не остави ниједнога жива, него све душе живе згуби, као што бјеше заповједио Господ Бог Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'И поби их Исус од Кадис-Варније до Газе, и сву земљу Госенску до Гаваона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'А све те цареве и земљу њихову узе Исус уједанпут; јер Господ Бог Израиљев војеваше за Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Потом се врати Исус и сав Израиљ с њим у око у Галгал.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'А кад то чу Јавин цар Асорски, посла к Јоваву цару Мадонском и к цару Симронском и к цару Ахсавском,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'И к царевима који бијаху на сјеверу у горама и по равницама на југу од Хинерота и у долини и у Нафат-Дору на запад,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Ка Хананејину на истоку и западу, и Аморејину и Хетејину и Ферезејину и Јевусејину у горама, и к Јевејину под Ермоном у земљи Миспи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'И изидоше они и сва војска њихова с њима, многи народ као пијесак на бријегу морском, и коњи и кола многа веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Сви ти цареви договорише се и дођоше, и стадоше заједно у око на води Мерому, да ударе на Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'А Господ рече Исусу; не бој их се; јер сјутра у ово доба ја ћу учинити те ће сви бити побијени пред Израиљем; коњма њиховијем испресијецај жиле, и кола њихова попали огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'И изиде Исус и сва војска с њим на њих на воду Мером изненада, и ударише на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'И Господ их даде у руке Израиљу, те их разбише и тјераше их до Сидона великога и до воде Мисрефота и до поља Миспе на исток; и тако их побише да не оставише ниједнога жива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'И учини им Исус како му бјеше заповједио Господ: коњма њиховијем испресијеца жиле, и кола њихова попали огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'И вративши се Исус у то вријеме, узе Асор, и уби цара његова мачем; а Асор бјеше прије глава свијем тијем царствима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'И побише све живо што бјеше у њему оштријем мачем сијекући, те не оста ништа живо; а Асор спалише огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'И све градове онијех царева и све цареве њихове узе Исус и исијече их оштријем мачем и поби их, као што бјеше заповједио Мојсије слуга Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Али ниједнога града који оста у опкопима својим не попали Израиљ, осим самога Асора, који спали Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'А сав плијен из тијех градова и стоку пограбише за себе синови Израиљеви; само људе све исјекоше оштријем мачем, те их истријебише, не оставише ништа жива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Како заповједи Господ Мојсију слузи својему, тако Мојсије заповједи Исусу, а Исус тако учини; ништа не изостави од свега што бјеше Господ заповједио Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'И тако узе Исус сву ту земљу, горе и сав јужни крај и сву земљу Госенску, и равницу и поље, гору Израиљеву и равницу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'Од горе Алака, која се пружа к Сиру, до Вал-Гада у пољу Ливанском, под гором Ермоном; и све цареве њихове зароби и поби их и погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Дуго времена војева Исус на те цареве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Не би ниједнога града који учини мир са синовима Израиљевијем, осим Јевеја који живљаху у Гаваону; све их узеше ратом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Јер од Господа би, те отврдну срце њихово да изиду у бој на Израиља, да би их потро и да им не би било милости, него да би их истријебио, као што бјеше заповједио Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'У то вријеме дође Исус, те истријеби Енакиме из гора, из Хеврона, из Давира, из Анава и из све горе Јудине и из све горе Израиљеве, с градовима њиховијем потр их Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Ниједан Енаким не оста у земљи синова Израиљевих; само у Гази, у Гату и у Азоту осташе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Тако узе Исус сву земљу, као што бјеше казао Господ Мојсију; и даде је у нашљедство Израиљу према дијеловима њиховијем, по племенима њиховијем. И земља почину од рата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'А ово су цареви земаљски које побише синови Израиљеви и земљу њихову освојише с ону страну Јордана к истоку, од потока Арнона до горе Ермона и сву равницу к истоку:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Сион цар Аморејски који стајаше у Есевону и владаше од Ароира који је на бријегу потока Арнона, и од половине потока и половином Галада до потока Јавока, гдје је међа синова Амонских;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'И од равнице до мора Хинеротскога к истоку, и до мора уз поље, до мора сланога к истоку, како се иде к Ветсимоту, и с југа под гору Фазгу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'И сусјед му Ог цар Васански, који бјеше остао од Рафаја и сјеђаше у Астароту и у Едрајину,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'И владаше гором Ермоном и Салхом и свијем Васаном до међе Гесурске и Махатске, и половином Галада до међе Сиона цара Есевонскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Њих поби Мојсије слуга Господњи и синови Израиљеви; и ту земљу даде Мојсије слуга Господњи у нашљедство племену Рувимову и племену Гадову и половини племена Манасијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'А ово су цареви земаљски које поби Исус са синовима Израиљевијем с ону страну Јордана к западу, од Вал-Гада у пољу Ливанском па до горе Алака како се иде к Сиру; и ту земљу даде Исус племенима Израиљевијем у нашљедство према дијеловима њиховијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'По горама и по равницама, по пољима и по долинама, и у пустињи и на јужном крају, земљу Хетејску, Аморејску и Хананејску, Ферезејску, Јевејску и Јевусејску:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Цар Јерихонски један; цар Гајски до Ветиља један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Цар Јерусалимски један; цар Хевронски један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Цар Јармутски један, цар Лахиски један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Цар Јеглонски један; цар Гезерски један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Цар Давирски један; цар Гадерски један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Цар Орамски један; цар Арадски један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Цар од Ливне један; цар Одоламски један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Цар Макидски један; цар Ветиљски један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Цар Тифувски један; цар Еферски један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Цар Афечки један; цар Саронски један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Цар Мадонски један; цар Асорски један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Цар Симрон-Меронски један; цар Ахсавски један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Цар Танашки један; цар Мегидски један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Цар Кедески један; цар Јокнеамски код Кармела један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'Цар Дорски у Нафат-Дору један; цар Гојимски у Галгалу један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Цар Тераски један. Свега тридесет и један цар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'А Исус већ бијаше стар и временит. И рече му Господ: ти си стар и временит, а земље је остало врло много да се освоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Ово је земља што је остала: све међе Филистејске и сва Гесурска,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Од Сиора, који је пред Мисиром, до међе Акаронске на сјевер; то припада Хананејима; пет кнежевина Филистејских, Газејска, Азотска, Аскалонска, Гетејска и Акаронска, и Авеји;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'С југа сва земља Хананејска и Меара, што припада Сидонцима до Афека, до међе Аморејске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'И земља Гивлејска и сав Ливан к истоку, од Вал-Гада под гором Ермоном па до уласка Ематскога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Све који живе у тој гори од Ливана до воде Мисрефота, све Сидонце ја ћу отјерати испред синова Израиљевих; само је раздијели ждријебом Израиљу у нашљедство, као што сам ти заповједио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Раздијели дакле ту земљу у нашљедство међу девет племена и половину племена Манасијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Јер с другом половином племе Рувимово и Гадово примише свој дио, који им даде Мојсије с ону страну Јордана к истоку, како им даде Мојсије слуга Господњи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Од Ароира који је на бријегу потока Арнона и града насред потока, и сву равницу Медевску до Девона,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'И све градове Сиона цара Аморејскога, који царева у Есевону, до међе синова Амоновијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'И Галад и међу Гесурску и Махатску и сву гору Ермонску и сав Васан до Салхе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Све царство Огово у Васану, који Ог царова у Астароту и Едрајину и бјеше остао од Рафаја; а Мојсије их поби и истријеби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Али Гесуреја и Махатеја не изагнаше синови Израиљеви, него Гесуреји и Махатеји осташе међу Израиљем до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Само племену Левијеву не даде нашљедства; жртве огњене Господа Бога Израиљева јесу нашљедство његово, као што му је рекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'А даде Мојсије племену синова Рувимовијех по породицама њиховијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'И међе им бјеху од Ароира који је на бријегу потока Арнона, и град који је на сриједи потока, и сва раван до Медеве,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Есевон са свијем градовима својим у равни, Девон и Вамот-Вал и Вет-Валмеон,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'И Јаса и Кадимот и Мифат,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'И Киријатајим и Сивма и Зарет-Сар на гори код долине,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'И Вет-Фегор и Аздот-Фазга и Вет-Јесимот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'И сви градови у равни, и све царство Сиона цара Аморејскога, који царова у Есевону, којега уби Мојсије с кнезовима Мадијамским, Евијом и Рекемом и Суром и Уром и Ревом, кнезовима Сионовијем, који живљаху у оној земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'И Валама сина Веорова врача убише синови Израиљеви мачем с другима побијенијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'И бјеху међе синова Рувимовијех Јордан с међама својим. То је нашљедство синова Рувимовијех по породицама њиховијем, градови и села њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'И даде Мојсије племену Гадову синовима Гадовијем по породицама њиховијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'И бјеху им међе Јазир и сви градови Галадски и половина земље синова Амоновијех до Ароира који је према Рави,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'И од Есевона до Рамот-Миспе и Ветонима, и од Маханаима до међе Давирске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'И у долини Вет-Арам и Вет-Нимра и Сокот и Сафон; остатак царства Сиона цара Есевонскога, Јордан и међа његова до краја мора Хинеротскога с ону страну Јордана на исток.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'То је нашљедство синова Гадовијех по породицама њиховијем, градови и села њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'И даде Мојсије половини племена Манасијина, и доби половина племена синова Манасијиних по породицама својим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Међа им бјеше од Маханаима, сав Васан, све царство Ога цара Васанскога, и сва села Јаирова, што су у Васану, шездесет градова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'И половина Галада, и Астарот и Едрајин, градови царства Огова у Васану, допадоше синовима Махира сина Манасијина, половини синова Махировијех по породицама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'То је што раздијели у нашљедство Мојсије у пољу Моавском с ону страну Јордана према Јерихону на истоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'А племену Левијеву не даде Мојсије нашљедства; Господ је Бог Израиљев њихово нашљедство, као што им је рекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'А ово је што добише нашљедство синови Израиљеви у земљи Хананској, што раздијелише у нашљедство Елеазар свештеник и Исус син Навин и поглавари породица отачких по племенима синова Израиљевих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Ждријебом дијелећи им нашљедство, као што заповиједи Господ преко Мојсија, међу девет племена и половину племена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Јер Мојсије даде нашљедство двјема племенима и половини племена с ову страну Јордана, а Левитима не даде нашљедства међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Јер синова Јосифовијех бјеху два племена: Манасијино и Јефремово, и Левитима не дадоше дијела у земљи, осим градова у којима ће живјети и подграђа њиховијех за стоку њихову и за благо њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Како бјеше заповједио Господ Мојсију, тако учинише синови Израиљеви и подијелише земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'А синови Јудини дођоше к Исусу у Галгалу, и рече му Халев син Јефонијин Кенезеј: ти знаш шта је казао Господ Мојсију слузи Божијему за ме и за те у Кадис-Варнији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Било ми је четрдесет година кад ме посла Мојсије слуга Господњи из Кадис-Варније да уходим земљу, и јавих му ствар, како ми је било у срцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'А браћа моја што идоше са мном уплашише срце народу; али се ја једнако држах Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'И закле се Мојсије онај дан говорећи: заиста земља по којој си ходио ногама својима, допашће теби у нашљедство и синовима твојим до вијека; јер си се сасвијем држао Господа Бога мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'А сада, ето, сачува ме Господ у животу, као што је рекао; има већ четрдесет и пет година како то рече Господ Мојсију, кад Израиљ иђаше по пустињи; и сад, ето, има ми данас осамдесет и пет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'И данас сам јоште крјепак, као што сам био кад ме је Мојсије слао; крјепост ми је и сад онака кака је била онда за бој и да одлазим и долазим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Зато дај ми сада ову гору, за коју је говорио Господ у онај дан; јер си чуо у онај дан да су ондје Енакими и градови велики и тврди; да ако буде Господ са мном, те их истјерам, као што је Господ казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'И Исус га благослови, и даде Хеврон Халеву сину Јефонијину у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Зато припаде Хеврон Халеву сину Јефонијину Кенезеју у нашљедство до данашњега дана, јер се једнако држао Господа Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'А име Хеврону бијаше пређе Киријат-Арва, а Арва бијаше велик човјек међу Енакимима. И земља почину од рата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'А ово бјеше дио синова Јудинијех по породицама њиховијем: уз међу Едомску, пустиња Син к југу на крају јужне стране;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'И бјеше им јужна међа од краја сланога мора, од залива који иде к југу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'А отуда иде на југ на брдо Акравим, прелази преко Сина, и пружа се од југа на Кадис-Варнију, и допире до Есрона, а отуда иде на Адар и савија се на Карку;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Отуда идући до Аселмона излази на поток Мисирски, и крај тој међи удара у Море. То вам је јужна међа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'А међа к истоку слано море до краја Јордана; а међа са сјеверне стране од залива морскога, до краја Јордана;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Одатле иде та међа на Вет-Оглу, и пружа се од сјевера до Вет-Араве; и одатле иде та међа на камен Воана сина Рувимова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Одатле иде та међа до Давира од долине Ахора, и на сјевер иде на Галгал, према брду Адумимском на јужној страни потока; потом иде та међа до воде Ен-Семеса, и удара у студенац Рогил;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Одатле иде та међа преко долине синова Еномовијех Јевусеја с југа, а то је Јерусалим; отуда иде међа на врх горе која је према долини Еному к западу и која је накрај долине Рафајске к сјеверу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Потом се савија међа с врха те горе к извору воде Нефтоје и излази на градове у гори Ефрону; а одатле се пружа међа до Вала, а то је Киријат-Јарим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Потом иде међа до Вала на запад ка гори Сиру, и иде покрај горе Јарима са сјевера, а то је Хасалон, и спушта се на Вет-Семес, и долази до Тамне;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'И иде међа покрај Акарона к сјеверу, и допире до Сикрона, и иде преко горе Вала и пружа се до Јавнила, и излази та међа на море.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'А међа је западна покрај великога мора и његовијех међа. То су међе синова Јудинијих унаоколо по породицама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'А Халеву сину Јефонијину даде Исус дио међу синовима Јудинијем, као што му заповједи Господ: Киријат-Арву; а Арва је био отац Енаков, и то је Хеврон;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'И одатле изагна Халев три сина Енакова: Сесаја и Ахимана и Талмаја синове Енакове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'И одатле отиде на Давиране; а Давир се прије зваше Киријат-Сефер.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'И рече Халев: ко савлада Киријат-Сефер и узме га, даћу му за жену Ахсу кћер своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'И узе га Готонило син Кенезов, брат Халевов; и даде му Ахсу кћер своју за жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'И кад полажаше, наговараше га да иште поље у оца њезина; па скочи с магарца. А Халев јој рече: шта ти је?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'А она рече: дај ми дар; кад си ми дао сухе земље, дај ми и извора воденијех. И даде јој изворе горње и изворе доње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Ово је нашљедство племена синова Јудинијех по породицама њиховијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Ово су градови по крајевима племена синова Јудинијех, дуж међе Едомске к југу: Кавсеил и Едер и Јагур,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'И Кина и Димона и Адада,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'И Кадес и Асор и Итнан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Зиф и Телем и Валот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'И Асор-Адата и Кириот; Есрон је Асор;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Амам и Сама и Молада,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'И Асар-Гада и Есемон и Вет-Фалет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'И Асар-Суал и Вир-Савеја и Визиотија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Вала и Им и Асем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'И Елтолад и Хесил и Орма,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'И Сиклаг и Мадмана и Сансана,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'И Леваот и Силеим и Ајин и Римон; свега двадесет и девет градова са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'У равни Естаол и Сараја и Асна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'И Заноја и Ен-Ганим, Тафуја и Инам,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Јармут и Одолам, Сохот и Азика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'И Сагарим и Адитајим и Гедира и Гедиротајим; четрнаест градова са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Севан и Адаса и Магдал-Гад,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'И Дилан и Миспа и Јоктеил,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Лахис и Васкат и Јеглон,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'И Хавон и Ламас и Хитлис,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'И Гедирот, Вет-Дагон, и Нама и Макида; шеснаест градова са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Ливна и Етер и Асан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'И Јефта и Асна и Несив,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'И Кеила и Ахзив и Мариса девет градова са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Акарон са селима и засеоцима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Од Акарона до мора све што је покрај Азота са селима својим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Азот са селима и засеоцима, Газа са селима и засеоцима до потока Мисирскога и до великога мора с међама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'А у гори: Самир и Јатир и Сохот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'И Дана и Киријат-Сана, а то је Давир,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'И Анав и Естемон и Аним,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'И Госен и Олон и Гилон; једанаест градова са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Арав и Дума и Есан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'И Јанум и Вет-Тафуја и Афека,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'И Хумата и Киријат-Арва, а то је Хеврон, и Сиор; девет градова са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Маон, Кармел и Зиф и Јута,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Језраел и Јогдеам и Заноја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Кајин, Гаваја и Тамна; десет градова са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Алул, Вет-сур и Гедор,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'И Марат и Вет-Анот и Елтекон; шест градова са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Киријат-Вал, то је Киријат-Јарим, и Рава; два града са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'У пустињи: Вет-Арава, Мидин и Сехаха,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'И Нивсан, и град соли, и Енгадија; шест градова са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'А Јевусеја који живљаху у Јерусалиму не могоше истјерати синови Јудини; зато осташе Јевусеји са синовима Јудинијем у Јерусалиму до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'И допаде дио синовима Јосифовијем од Јордана код Јерихона, од воде Јерихонске к истоку, на пустињу која иде од Јерихона на гору Ветиљску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'А од Ветиља иде на Луз и долази до међе Архијске до Атарота,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Потом иде на запад до међе Јафлетске па до међе доњега Вет-Орона и до Гезера, и излази на море.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Тако добише нашљедство синови Јосифови, Манасија и Јефрем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'А бјеше међа синовима Јефремовијем по породицама њиховијем, бјеше међа нашљедства њихова к истоку Атарот-Адар до горњега Вет-Орона,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'И излази међа на море код Михмете са сјеверне стране, па се обрће међа к истоку до Танат-Силона, и пролази с истока до Јанохе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Потом слази од Јанохе до Атарота и Нарата, и дошавши до Јерихона удара у Јордан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Од Тафује иде међа к истоку до потока Кане и излази на море. То је нашљедство племена синова Јефремовијех по породицама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'А градови бијаху одвојени синовима Јефремовијем у нашљедству синова Манасијиних, сви градови са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'А не изагнаше Хананејина који живљаше у Гезеру; зато осташе Хананеји међу синовима Јефремовијем до данас плаћајући данак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'И допаде дио племену Манасијину, а он бјеше првенац Јосифов; Махиру првенцу Манасијину оцу Галадову, јер бјеше човјек јунак, зато му допаде Галад и Васан;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Добише дио и остали синови Манасијини по породицама својим, синови Авијезерови, и синови Хелекови, и синови Азрилови, и синови Сихемови, и синови Еферови, и синови Семидини. То су синови Манасије сина Јосифова; људи по породицама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'А Салпад син Ефера сина Галада сина Махира сина Манасијина није имао синова него кћери; и ово су имена кћерима његовијем: Мала и Нуја, Егла, Мелха и Терса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'И оне дођоше пред Елеазара свештеника и пред Исуса сина Навина и пред кнезове, и рекоше: Господ је заповједио Мојсију да нам се даде нашљедство међу браћом нашом. И даде им Исус по заповијести Господњој нашљедство међу браћом оца њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'И допаде Манасији десет дијелова, осим земље Галадске и Васанске, које су с ону страну Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Јер кћери Манасијине добише нашљедство међу синовима његовијем, а земља Галадска допаде другим синовима Манасијиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'А међа Манасијина бјеше од Асира к Михмети, која је према Сихему, потом иде та међа надесно к становницима Ен-Тафујским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'А Манасијина је земља Тафујска, али Тафуја на међи Манасијиној припада синовима Јефремовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Одатле слази међа на поток Кану, с јужне стране тога потока; и градови су Јефремови међу градовима Манасијиним; а међа је Манасијина са сјеверне стране потока и излази на море.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'С југа је Јефремово, а са сјевера Манасијино, а море им је међа; а с Асиром граниче на сјеверу а с Исахаром на истоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Јер је Манасијино у племену Исахараову и Асирову: Вет-Сан са селима својим, и Ивлеам са селима својим, и Дорани са селима својим, и Ен-Дорани са селима својим, и Танашани са селима својим, и Мегиђани са селима својим; та три краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Али синови Манасијини не могоше изагнати Хананеје из тијех градова, него Хананеји стадоше живјети у тој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Али кад ојачаше синови Израиљеви, ударише данак, на Хананеје, али их не изагнаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'А синови Јосифови рекоше Исусу говорећи: зашто си нам дао у нашљедство један дио и једно уже, кад је нас множина и Господ нас је благословио довде?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'А Исус им рече: кад вас је множина, идите у шуму, и ондје окрчите себи у земљи Ферезејској и Рафајској, ако вам је тијесна гора Јефремова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'А синови Јосифови рекоше: неће нам бити доста ова гора; а сви Хананеји који живе у долини имају гвоздена кола; и они који су у Вет-Сану и у селима његовијем и они који су у долини Језраелској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'А Исус рече дому Јосифову, Јефрему и Манасији, говорећи: велик си народ и силан си, нећеш имати једнога дијела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Него гора нека буде твоја; ако је шума, исијеци је, пак ћеш имати међе њезине; јер ћеш изагнати Хананеје, ако и имају гвоздена кола, ако и јесу јаки.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'И сабра се сав збор синова Израиљевијех у Силом и ондје намјестише шатор од састанка, пошто покорише земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Али још бијаше синова Израиљевијех седам племена, којима не би дато нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'И Исус рече синовима Израиљевијем: докле ћете оклијевати, те не идете и узмете земљу коју вам је дао Господ Бог отаца ваших?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Изберите између себе по три човјека из свакога племена, па нека се дигну и прођу земљу, и нека је препишу на нашљедства своја, па онда нека дођу к мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'И нека је раздијеле на седам дијелова; Јуда ће остати у својим међама с југа, и дом ће Јосифов остати у међама својим са сјевера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'А ви препишите земљу на седам дијелова, и донесите амо к мени, да бацим ждријеб за племена ваша овдје пред Господом Богом нашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Јер Левити немају дијела међу вама, јер је свештенство Господње њихово нашљедство; а Гад и Рувим и половина племена Манасијина примише нашљедство своје с ону страну Јордана на истоку, које им даде Мојсије слуга Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Тада усташе људи и пођоше; а Исус заповједи људима који отидоше да препишу земљу говорећи: идите и прођите земљу и препишите је, па онда дођите к мени, те ћу бацити ждријеб за вас овдје пред Господом у Силому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'И отидоше људи и прођоше земљу и преписаше је у књигу село по село на седам дијелова; потом се вратише к Исусу у око у Силом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'И Исус баци ждријеб за њих у Силому пред Господом, и ондје подијели Исус земљу међу синове Израиљеве по дијеловима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'И изиде ждријеб за племе синова Венијаминовијех по породицама њиховијем, и дође међа дијела њихова међу синове Јудине и синове Јосифове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'И би им међа са сјевера до Јордана, и она иде покрај Јерихона са сјевера и пружа се на гору к западу, и излази у пустињу Вет-Авен;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'А одатле иде та међа до Луза, с јужне стране Лузу, а то је Ветиљ, и слази до Атарот-Адара покрај горе која је с југа Вет-Орону доњему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Отуда излази међа и савија се покрај мора к југу од горе, која је према Вет-Орону на југ, и излази на Киријат-Вал, а то је Киријат-Јарим, град синова Јудинијех. То је западна страна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'А јужна страна од краја Киријат-Јарима, и излази та међа к западу, па иде на извор воде Нефтоје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'И слази та међа накрај горе која је према долини сина Еномова а у долини Рафајској к западу, и иде преко долине Еномове покрај Јевусеја к југу, и слази на извор Рогил;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Потом се обрће од сјевера и иде на Ен-Семес, а отуда иде на Галилот, који је према гори Адумимској, и слази на камен Воана сина Рувимова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Отуда иде страном која је према Арави к сјеверу и слази у Араву;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Потом иде покрај Вет-Огле к сјеверу и удара у залив сланога мора са сјеверне стране до краја Јордана на југу. То је јужна међа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'А Јордан је међа с источне стране. То је нашљедство синова Венијаминовијех с међама њиховијем унаоколо по породицама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'А градови племена синова Венијаминовијех по породицама њиховијем јесу: Јерихон и Вет-Огла и Емек-Кесис,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'И Вет-Арава и Семарајим и Ветиљ,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'И Авин и Фара и Офра,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'И Хефар-Амона и Офнија и Гава; дванаест градова са селима својим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Гаваон и Рама и Вирот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'И Миспа и Хефира и Моса,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'И Рекем и Јерфаил и Тарала,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'И Сила, Елеф и Јевус, а то је Јерусалим, Гават, Киријат; четрнаест градова са селима својим. То је нашљедство синова Венијаминовијех по породицама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Потом изиде други ждријеб за Симеуна, племе синова Симеуновијех по породицама њиховијем, и би нашљедство њихово усред нашљедства синова Јудинијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'И допаде им у нашљедство Вир-Савеја и Савеја и Молада,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'И Асар-Суал и Вала и Асем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'И Елтолад и Ветул и Орма,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'И Сиклаг и Вет-Маркавот и Асар-Суса,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'И Вет-Леваот и Саруен; тринаест градова са селима својим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ајин, Ремон и Етер и Асан, четири града са селима својим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'И сва села што бијаху око тијех градова дори до Валат-Вира, а то је Рамат јужни. То је нашљедство племена синова Симеуновијех по породицама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Од дијела синова Јудинијех допаде нашљедство синовима Симеуновијем, јер дио синова Јудинијех бијаше велик за њих, зато синови Симеунови добише нашљедство на њихову нашљедству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Потом изиде трећи ждријеб за синове Завулонове по породицама њиховијем; и међа нашљедству њихову би до Сарида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'А одатле иде међа њихова покрај мора на Маралу, и допире до Давасета, и иде на поток који је према Јокнеаму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Па се окреће од Сарида на исток до међе Кислот-Таворске, и иде на Даврат и излази до Јафе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Отуда иде опет к истоку до Гита-Ефера, а то је Ита-Касин, и излази на Ремон-Метоар, а то је Неја;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Отуда се савија међа к сјеверу на Анатон, и излази у долину Јефтаил,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'С Кататом и с Налалом и Симроном и Идалом и Витлејемом, дванаест градова са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'То је нашљедство синова Завулоновијех по породицама њиховијем, то су градови и села њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'За Исахара изиде ждријеб четврти, за синове Исахарове по породицама њиховијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'А међа им би: Језраел и Кесулот и Суним,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'И Аферајим и Сеон и Анахарат,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'И Равит и Кисион и Авес,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'И Ремет и Ен-Ганим и Ен-Ада и Вет-Фасис,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'А отуда иде међа на Тавор и на Сахасиму и Вет-Семес, и удара у Јордан; шеснаест градова са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'То је нашљедство племена синова Исахаровијех по породицама њиховијем; то су градови и села њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Потом изиде ждријеб пети за племе синова Асировијех по породицама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'И међа им би: Хелкат и Алија и Ветен, и Ахсаф,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'И Аламелех и Амад и Мисал, и пружа се до Кармела к мору и до Сихор-Ливната,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'И одатле се савија к истоку на Вет-Дагон, и допире до Завулона и до долине Јефтаила к сјеверу, и до Ветемека и Наила, и иде до Хавула налијево;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'И Хеврон и Реов и Амон и Кана дори до Сидона великога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Отуда се савија међа на Раму и до тврдога града Тира, а отуда се савија на Осу и излази на море покрај дијела Ахсивскога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'И Ама и Афек и Реов; двадесет и два града са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'То је нашљедство племена синова Асировијех по породицама њиховијем, то су градови и села њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'За синове Нефталимове изиде ждријеб шести, за синове Нефталимове по породицама њиховијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'И међа им би од Елафа и од Алона до Сананима, и од Адами-Некева и Јавнила до Лакума, и излази на Јордан;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Потом се обрће међа на запад к Азнот-Тавору, и иде на Укок, и допире до Завулона с југа и до Асира са запада и до Јуде на Јордану с истока.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'А тврди су градови: Сидим, Сер и Амат, Ракат и Хинерот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'И Адама и Рама и Асор,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'И Кедес и Едреј и Ен-Асор,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'И Ирон Мигдалил, Орем и Вет-Анат и Вет-Семес; деветнаест градова са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'То је нашљедство племена синова Нефталимовијех по породицама њиховијем, то су градови са селима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Седми ждријеб изиде за племе синова Дановијех по породицама њиховијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'И међа нашљедству њихову би Сара и Естаол и Ир-Семес,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'И Салавин и Ајалон и Јетла,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'И Елон и Тамната и Акарон,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'И Елтекон и Гиветон и Валат,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'И Јуд и Вани-Варак и Гат-Римон,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'И Ме-Јаркон и Ракон с међама својим према Јопи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Али међе синова Дановијех изидоше мале за њих; зато изидоше синови Данови и ударише на Лесем и узеше га и побише оштријем мачем и освојише га, и населише се у њему, и Лесем прозваше Дан по имену Дана оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'То је нашљедство племена синова Дановијех по породицама њиховијем; то су градови и села њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'А кад подијелише земљу по међама њезинијем, дадоше синови Израиљеви нашљедство Исусу сину Навину међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'По заповијести Господњој дадоше му град који заиска, Тамнат-Сарах у гори Јефремовој, а он сагради град и насели се у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'То су нашљедства која Елеазар свештеник и Исус син Навин и главари породица отачких у племенима синова Израиљевијех подијелише ждријебом у Силому пред Господом на вратима шатора од састанка, и тако подијелише земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Потом рече Господ Исусу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Кажи синовима Израиљевијем и реци: Одредите градове за уточишта, за које сам вам говорио преко Мојсија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Да онамо утече крвник који убије кога нехотице, не мислећи, да вам буду уточишта од осветника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Па кад ко утече у који од тијех градова, нека стане пред вратима градским и нека каже старјешинама онога града ствар своју, па нека га приме к себи, и даду му мјесто да сједи код њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'И ако дође за њим осветник, нека му не даду крвника у руке, јер је нехотице убио ближњега нити је прије мрзио на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Него нека сједи у граду оном докле не стане пред збор на суд, до смрти поглавара свештеничкога који буде онда, тада нека се крвник врати и иде у свој град и својој кући, у град из којега је утекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'И одијелише Кедес у Галилеји у Гори Нефталимовој и Сихем у гори Јефремовој и Киријат-Арву, то је Хеврон, у гори Јудиној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'А преко Јордана од Јерихона на исток одредише Восор у пустињи, у равни, од племена Рувимова, и Рамот у Галаду од племена Гадова, и Голан у Васану од племена Манасијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'То су градови одређени свијем синовима Израиљевијем и дошљаку који се бави међу њима, да утече у њих ко год убије кога нехотице и да не погине од руке осветникове докле не стане пред збор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Тада дођоше главари отачких породица Левитских к Елеазару свештенику и к Исусу сину Навину и главарима породица отачких и племенима синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'И рекоше им у Силому у земљи Хананској говорећи: Господ је заповједио преко Мојсија да нам се даду градови гдје ћемо живјети и подграђа њихова за стоку нашу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'И дадоше синови Израиљеви Левитима од нашљедства својега по заповијести Господњој ове градове и подграђа њихова:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Изиде ждријеб за породице Катове; и допаде синовима Арона свештеника између Левита ждријебом тринаест градова од племена Јудина и од племена Симеунова и од племена Венијаминова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'А осталијем синовима Катовијем допаде ждријебом десет градова од породица племена Јефремова и од племена Данова и од половине племена Манасијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'А синовима Гирсоновијем допаде ждријебом од породица племена Исахарова и од племена Асирова и од племена Нефталимова и од половине племена Манасијина у Васану тринаест градова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Синовима Мераријевим по породицама њиховијем од племена Рувимова и од племена Гадова и од племена Завулонова дванаест градова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Дадоше дакле синови Израиљеви Левитима те градове и подграђа њихова ждријебом, као што бјеше заповједио Господ преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'И дадоше од племена синова Јудинијех и од племена синова Симеуновијех ове градове који се казују по именима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'И допаде синовима Ароновијем од породица Катовијех између синова Левијевих, за које паде први ждријеб,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Њима допаде: Киријат-Арва, а Арва је отац Анаков, а тај је град Хеврон у гори Јудиној, с подграђем својим унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'А поље око тога града и села његова дадоше Халеву сину Јефонијину у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Дадоше дакле синовима Арона свештеника град за уточиште крвнику Хеврон с подграђем, и Ливну с подграђем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'И Јатир с подграђем, и Естемоју с подграђем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'И Олон с подграђем, и Давир с подграђем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'И Ајин с подграђем, и Јуту с подграђем, и Вет-Семес с подграђем: девет градова од та два племена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'А од племена Венијаминова Гаваон с подграђем, и Гавају с подграђем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Анатот с подграђем, и Алмон с подграђем: четири града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Свега градова синова Арона свештеника тринаест градова с пограђима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'А породицама синова Катовијех, Левитима, што их још бјеше од синова Катовијех, допадоше на њихов ждријеб градови од племена Јефремова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Допаде им град за уточиште крвнику Сихем с пограђем у гори Јефремовој, и Гезер с подграђем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'И Кивсајим с подграђем, и Вет-Орон с подграђем: четири града;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'А од племена Данова: Елтекон с подграђем, Гиветон с подграђем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ајалон с подграђем, Гат-Римом с подграђем: четири града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'А од половине племена Манасијина: Танах с подграђем и Гат-Римон с подграђем: два града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Свега десет градова с подграђима дадоше породицама синова Катовијех осталијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'А синовима Гирсоновијем између породица Левитских дадоше од половине племена Манасијина град за уточиште крвнику Голан у Васану с подграђем, и Вестеру с подграђем: два града;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'А од племена Исахарова: Кисон с подграђем, Даврат с подграђем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Јармут с подграђем, Ен-Ганим с подграђем: четири града;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'А од племена Асирова: Мисал с подграђем, Авдон с подграђем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Хелкат с подграђем, и Реов с подграђем: четири града;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'А од племена Нефталимова град за уточиште крвнику Кедес у Галилеји с подграђем, и Амот-Дор с подграђем, и Картан с подграђем: три града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Свега градова синова Гирсоновијех по породицама њиховијем тринаест градова с подграђима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'А породицама синова Мераријевих, осталијем Левитима, дадоше од племена Завулонова Јокнеам с подграђем, Карту с подграђем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Димну с подграђем, Налол с подграђем: четири града;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'А од племена Рувимова: Восор с подграђем, и Јазу с подграђем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Кедимот с подграђем, и Мифат с подграђем: четири града;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'А од племена Гадова: град за уточиште крвнику Рамот у Галаду с подграђем, и Маханајим с подграђем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Есевон с подграђем, Јазир с подграђем; свега четири града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Све ове градове дадоше синовима Мераријевим по породицама њиховијем, што још бијаху између породица Левитских; и дође на ждријеб њихов дванаест градова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Свега градова Левитских у нашљедству синова Израиљевијех бјеше четрдесет и осам градова с подграђима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'А сви градови имају своја подграђа унаоколо; тако је у свакога града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Тако даде Господ Израиљу сву земљу, за коју се закле оцима њиховијем да ће им је дати, и наслиједише је и населише се у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'И умири их Господ од свуда унаоколо, као што се заклео оцима њиховијем; и нико се не одржа пред њима од свијех непријатеља њиховијех; све непријатеље њихове предаде им Господ у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Ништа не изоста од свега добра што бјеше обрекао Господ дому Израиљеву; све се зби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Тада сазва Исус синове Рувимове и синове Гадове и половину племена Манасијина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'И рече им: ви држасте све што вам је заповједио Мојсије слуга Господњи, и слушасте глас мој у свему што сам вам заповиједао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Не остависте браће своје дуго времена, до овога дана, и добро чувасте заповијест Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'А сада Господ је Бог ваш смирио браћу вашу, како им је рекао; сада дакле вратите се и идите у шаторе своје у земљу нашљедства својега, коју вам је дао Мојсије слуга Господњи с ону страну Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Само пазите добро да вршите заповијест и закон, што вам је заповједио Мојсије слуга Господњи, да љубите Господа Бога својега и да ходите свијем путовима његовијем, и чувате заповијести његове и држите их се, и да му служите свијем срцем својим и свом душом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'И благослови их Исус, и отпусти их да иду у своје шаторе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'А половина племена Манасијина бјеше дао Мојсије нашљедство у Васану, а другој половини даде Исус с браћом њиховом с ову страну Јордана к западу. И отпуштајући их Исус у шаторе њихове благослови их,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'И рече им говорећи: с великим благом враћате се у шаторе своје, са стоком врло многом; са сребром и златом и мјеђу и гвожђем и одијелом врло многим; подијелите плијен од непријатеља својих с браћом својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'И вративши се синови Рувимови и синови Гадови и половина племена Манасијина отидоше од синова Израиљевијех из Силома, који је у земљи Хананској, идући у земљу Галадску, у земљу нашљедства својега, коју наслиједише, како бјеше Господ заповједио преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'А кад дођоше на међу Јорданску у земљи Хананској, начинише синови Рувимови и синови Гадови и половина племена Манасијина олтар ондје на Јордану, олтар велик и наочит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'И чуше синови Израиљеви гдје се говори: гле, синови Рувимови и синови Гадови и половина племена Манасијина начинише олтар према земљи Хананској на међи Јорданској, покрај синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'А кад чуше синови Израиљеви, скупи се сав збор синова Израиљевијех у Силом да иду да се бију с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'И послаше синови Израиљеви к синовима Рувимовијем и синовима Гадовијем и половини племена Манасијина у земљу Галадску Финеса сина Елеазара свештеника,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'И с њим десет кнезова, по једнога кнеза од дома отачкога од свијех племена Израиљевијех, а сваки их бјеше поглавар у дому отаца својих у тисућама Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'А они дођоше к синовима Рувимовијем и синовима Гадовијем и половини племена Манасијина у земљу Галадску, и рекоше им говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Овако вели сав збор Господњи, какав је то гријех којим се огријешисте Богу Израиљеву одвративши се данас од Господа начинивши олтар да се одметнете данас од Господа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Мало ли нам је гријеха Фегорова, од којега се још нијесмо очистили до данас и с којега дође погибао на збор Господњи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Те се данас одвраћате од Господа, и одмећете се данас од Господа, да се сјутра разгњеви на сав збор Израиљев?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Ако је земља нашљедства вашега нечиста, пријеђите у земљу нашљедства Господњега, у којој стоји шатор Господњи, и узмите нашљедство међу нама; само се не одмећите од Господа и не одмећите се од нас градећи себи олтар мимо олтар Господа Бога нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Није ли се Ахан син Зарин огријешио о ствари проклете, те дође гњев на сав збор Израиљев? и он не погибе сам за гријех свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'А синови Рувимови и синови Гадови и половина племена Манасијина одговорише и рекоше поглаварима тисућа Израиљевих:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Господ Бог над боговима, Господ Бог над боговима, он зна, и Израиљ нека зна. Ако смо ради одметати се и гријешити Господу, нека нас не сачува данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Ако смо начинили олтар да се одвратимо од Господа или да приносимо на њему жртве паљенице или даре или да приносимо на њему жртве захвалне, Господ нека тражи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Него то учинисмо бојећи се овога: рекосмо: сјутра ће рећи синови ваши синовима нашим говорећи: шта ви имате с Господом Богом Израиљевим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Међу је поставио Господ између нас и вас, синови Рувимови и Гадови, Јордан; ви немате дијела у Господа. Те ће синови ваши одбити синове наше да се не боје Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Зато рекосмо: учинимо тако, и начинимо олтар, не за жртву паљеницу ни за другу жртву,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Него да буде свједок међу нама и вама, и међу натражјем нашим након нас, да бисмо служили Господу пред њим жртвама својим паљеницама и приносима својим, и жртвама својим захвалним, и да не би рекли кадгод синови ваши синовима нашим: ви немате дијела у Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Јер рекосмо: ако кад реку тако нама или натражју нашему, тада ћемо им казати: видите слику од олтара Господњега коју начинише оци наши не за жртву паљеницу ни за другу жртву, него да је свједочанство међу нама и вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Не дај Боже да се одмећемо Господу и да се данас одвраћамо од Господа начинивши олтар за жртву паљеницу, за дар или за принос, мимо олтар Господа Бога нашега, који је пред шатором његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'А кад чу Финес свештеник и кнезови од збора, поглавари од тисућа Израиљевих који бијаху с њим, ријечи које им рекоше синови Рувимови и синови Гадови и синови Манасијини, би им по вољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'И рече Финес син Елеазара свештеника синовима Рувимовијем и синовима Гадовијем и синовима Манасијиним: данас познасмо да је међу нама Господ кад се огријешисте Господу тијем гријехом, и сачувасте синове Израиљеве од руку Господњих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'И Финес син Елеазара свештеника и они кнезови вратише се од синова Рувимовијех и од синова Гадовијех из земље Галадске у земљу Хананску к синовима Израиљевијем, и јавише им ствар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'И би по вољи синовима Израиљевијем; и хвалише Бога синови Израиљеви, и не говорише више да иду да се бију с њима да потру земљу, у којој живе синови Рувимови и синови Гадови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'И прозваше синови Рувимови и синови Гадови онај олтар Ед говорећи: свједок је међу нама да је Господ Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'А послије много времена, пошто Господ умири Израиља од свијех непријатеља његовијех унаоколо, и Исус би стар и временит,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Дозва Исус све синове Израиљеве, старјешине њихове и поглаваре њихове и судије и управитеље њихове, и рече им: ја сам стар и временит;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'А ви сте видјели све што је учинио Господ Бог ваш свијем овијем народима вас ради, јер је Господ Бог ваш сам војевао за вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Видите, раздијелио сам вам ждријебом ове народе, који осташе, у нашљедство по племенима вашим од Јордана, све народе које истријебих до великога мора на запад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'И Господ Бог ваш разагнаће их испред вас и истријебиће их испред вас, и наслиједићете земљу њихову, као што вам је рекао Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Зато укријепите се добро да држите и творите све што је написано у књизи закона Мојсијева, да не отступате од њега ни надесно ни налијево,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Да се не помјешате с тијем народима што су остали међу вама, и да не помињете имена богова њиховијех, и да се не кунете њима нити да им служите нити им се клањате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Него се држите Господа Бога својега, као што сте чинили до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Зато је Господ одагнао испред вас народе велике и јаке, и нико се није одржао пред вама до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Један човјек између вас гониће тисућу, јер Господ Бог ваш војује за вас, као што вам је рекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Пазите дакле добро да љубите Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Јер ако се одвратите и пристанете за остатком тијех народа што су још остали међу вама, и с њима се опријатељите и помијешате се с њима и они с вама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'Знајте заиста да Господ Бог ваш неће више изгонити тијех народа испред вас, него ће вам они постати замка и мрежа, и бич боковима вашим, и трње очима вашим, докле не изгинете на овој доброј земљи коју вам је дао Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'И ево, ја идем сада куда иде све на земљи; познајте дакле свијем срцем својим и свом душом својом да није изостало ништа од свега добра што вам је обрекао Господ Бог ваш, све вам се навршило, није изостало ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'А како вам се навршило свако добро што вам је обрекао Господ Бог ваш, тако ће Господ пустити на вас сва зла, докле вас не истријеби с ове добре земље, коју вам је дао Господ Бог ваш,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Ако преступите завјет Господа Бога својега који вам је заповједио, и отидете да служите другим боговима, и станете им се клањати; и распалиће се гњев Господњи на вас, и нестаће вас брзо с те добре земље, коју вам је дао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Потом сабра Исус сва племена Израиљева у Сихем, и сазва старјешине Израиљеве и поглаваре његове и судије његове и управитеље његове, и стадоше пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'И рече Исус свему народу: овако вели Господ Бог Израиљев: с ону страну ријеке живјеше негда оци ваши, Тара отац Аврамов и отац Нахоров, и слулжише другим боговима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Али узех оца вашега Аврама испреко ријеке и проведох га кроз сву земљу Хананску и умножих сјеме његово давши му Исака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'А Исаку дадох Јакова и Исава, и дадох Исаву гору Сир да је његова; а Јаков и синови његови сидоше у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'И послах Мојсија и Арона, и мучих Мисир, како учиних усред њега, потом вас изведох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'А кад изведох из Мисира оце ваше, дођоше на море, а Мисирци гнаше оце ваше с колима и с коњицима до Црвенога Мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Тада завапише ка Господу, и поставих таму између вас и Мисираца, и наведох на њих море које их затрпа, и очи ваше видјеше шта учиних од Мисираца; потом остасте у пустињи дуго времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Иза тога доведох вас у земљу Амореја који живљаху с ону страну Јордана; и они се побише с вама, али их дадох вама у руке, те наслиједисте земљу њихову, и истријебих их испред вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'А Валак син Сефоров цар Моавски подиже се да се бије с Израиљем, и посла те дозва Валама сина Веорова да вас прокуне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Али не хтјех послушати Валама, те вас он још благослови, и избавих вас из руке његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Потом пријеђосте преко Јордана, и дођосте под Јерихон, и бише се с вама Јерихоњани, Амореји и Ферезеји и Хананеји и Хетеји и Гергесеји и Јевеји и Јевусеји; и дадох их вама у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'И послах пред вама стршљене, који их изагнаше испред вас, два цара Аморејска; не мачем твојим ни луком твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'И дадох вам земљу, које не радисте, и градове, којих не градисте, и у њима живите; из винограда и из маслиника, којих нијесте садили, једете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Зато сада бојте се Господа и служите му вјерно и истинито; и поврзите богове, којима су служили оци ваши с ону страну ријеке и у Мисиру, па служите Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Ако ли вам није драго служити Господу, изберите себи данас коме ћете служити: или богове којима су служили оци ваши с ону страну ријеке, или богове Амореја у којих земљи живите; а ја и дом мој служићемо Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'А народ одговори и рече: не дај Боже да оставимо Господа да служимо другим боговима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Јер Господ Бог наш, он је извео нас и оце наше из земље Мисирске, из дома ропскога, и он је учинио пред нашим очима оне знаке велике, и чувао нас цијелијем путем којим идосмо, и по свијем народима кроз које прођосмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'И господ је истјерао испред нас све народе и Амореје, који живљаху у овој земљи; и ми ћемо служити Господу, јер је Бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'А Исус рече народу: не можете служити Господу, јер је свет Бог, Бог ревнитељ, неће подносити ваше невјере и ваши гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Кад оставите Господа и станете служити туђим боговима, окренуће се и зло ће вам учинити, и истријебиће вас, пошто вам је добро чинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'А народ рече Исусу: не, него ћемо Господу служити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'А Исус рече народу: сами сте себи свједоци да сте изабрали себи Господа да му служите. И они рекоше: свједоци смо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Поврзите дакле богове туђе што су међу вама, и привијте срце своје ка Господу Богу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'А народ рече Исусу: Господу Богу својем служићемо и глас његов слушаћемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Тако учини Исус завјет с народом онај дан и постави им уредбе и законе у Сихему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'И записа Исус ове ријечи у књигу закона Божијега; и узевши камен велик подиже га ондје под храстом који бијаше код светиње Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'И рече Исус свему народу: ево, камен овај нека вам буде свједочанство; јер је чуо све ријечи Господње, које нам је говорио; и нека вам буде свједочанство да не бисте слагали Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Потом распусти Исус народ, свакога на његово нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'А послије овијех ствари умрије Исус син Навин слуга Господњи, кад му бијаше сто и десет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'И погребоше га у међама нашљедства његова у Тамнат-Сараху, који је у гори Јефремовој са сјевера гори Гасу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'И служи Израиљ Господу свега вијека Исусова и свега вијека старјешина, које дуго живјеше иза Исуса и које знаху сва дјела Господња, која учини Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'И кости Јосифове, које донесоше синови Израиљеви из Мисира, погребоше у Сихему, у дијелу поља које је купио Јаков од синова Емора оца Сихемова за сто новаца; и бише у синова Јосифовијех у нашљедству њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'И Елеазар син Аронов умрије, и погребоше га на брду Финеса сина његова, које му бјеше дано у гори Јефремовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'А по смрти Исусовој упиташе синови Израиљеви Господа говорећи: ко ће између нас ићи први на Хананеје да се бије с њима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'И Господ рече: Јуда нека иде; ето дао сам му земљу у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'А Јуда рече Симеуну брату својему: хајде са мном на мој део да се бијемо с Хананејима; пак ћу и ја ићи с тобом на твој дио. И пође Симеун с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'И изиде Јуда; и даде им Господ Хананеје и Ферезеје у руке, и побише их у Везеку десет тисућа људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Јер нађоше Адони-Везека у Везеку, и ударише на њ, и побише Хананеје и Ферезеје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'И побјеже Адони-Везек, а они га потјераше и ухватише га отсјекоше му палце у руку и у ногу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Тада рече Адони-Везек: седамдесет царева отсјеченијех палаца у руку и у ногу купише што бјеше под мојим столом; како сам чинио, тако ми плати Бог. И одведоше га у Јерусалим, и ондје умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Јер синови Јудини ударише на Јерусалим и узеше га, и исјекоше грађане оштријем мачем, а град сажегоше огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Потом изидоше синови Јудини да војују на Хананеје, који живљаху у гори и на југу и у равни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'И Јуда изиде на Хананеје који живљаху у Хеврону, а Хеврону бијаше пређе име Киријат-Арва; и побише Сесаја и Ахимана и Талмаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'А одатле отидоше на Давиране, а Давиру прије бјеше име Киријат-Сефер.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'И рече Халев: ко савлада Киријат-Сефер и узме га, даћу му Ахсу кћер своју за жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'И узе га Готонило, син Кенезов, млађи брат Халевов; и даде му Ахсу кћер своју за жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'И кад полажаше, наговараше га да иште у оца њезина поље; па скочи с магарца. А Халев јој рече: што ти је?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'А она му рече: дај ми дар; кад си ми дао сухе земље, дај ми и извора воденијех. И даде јој Халев изворе горње и изворе доње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'А и синови Кенеја таста Мојсијева изидоше из града палмова са синовима Јудинијем у пустињу Јудину, која је на југу од Арада. И дошавши живљаху с народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Потом изиде Јуда са Симеуном братом својим, и побише Хананеје који живљаху у Сефату, и раскопаше га, и прозва се град Орма.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'И Газу узе Јуда с међама њезинијем, и Аскалон с међама његовијем, и Акарон с међама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Јер Господ бјеше с Јудом, те освоји гору; али не изагна онијех који живљаху у долини, јер имаху гвоздена кола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'И дадоше Халеву Хеврон, као што бјеше заповједио Мојсије, а он изагна оданде три сина Енакова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'А синови Венијаминови не изагнаше Јевусеја који живљаху у Јерусалиму; него Јевусеји осташе у Јерусалиму са синовима Венијаминовијем до овога дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Изидоше и синови Јосифови на Ветиљ, и Господ бијаше с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'И уходише Ветиљ синови Јосифови, а име граду бјеше прије Луз.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'И уходе видјеше човјека који иђаше из града и рекоше му: хајде покажи нам куда ћемо ући у град, па ћемо ти учинити милост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'А он им показа куда ће ући у град; и исјекоше у граду све оштријем мачем, а онога човјека пустише са свом породицом његовом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'И отиде онај човјек у земљу Хетејску, и ондје сазида град, и прозва га Луз; то му је име до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'А Манасија не изагна становника из Вет-Сана и села његовијех, ни из Танаха и села његовијех, ни становника из Дора и села његовијех, ни становника из Ивлеама и села његовијех, ни становника из Мегида и села његовијех; и Хананеји стадоше живјети у тој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'А кад ојача Израиљ, удари на Хананеје данак, али их не изагна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Ни Јефрем не изагна Хананеје који живљаху у Гезеру; него осташе Хананеји с њим у Гезеру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Завулон не изагна становника из Китрона, ни становника из Налола; него осташе Хананеји с њим, и плаћаху данак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Асир не изагна становника из Акона, ни становника из Сидона ни из Алава, ни из Ахазива, ни из Хелве, ни из Афика, ни из Реова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Него Асир живљаше међу Хананејима, становницима оне земље, јер их не изагна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Нефталим не изагна становника из Вет-Семеса, ни становника из Вет-Аната; него живљаше међу Хананејима становницима оне земље; и становници у Вет-Семесу и у Вет-Анату плаћаху им данак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'А Амореји притјешњаваху синове Данове у гори, и не дадијаху им слазити у долину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'И Амореји стадоше живјети у гори Ересу, у Ајалону и у Салвиму; а кад осили рука дома Јосифова, плаћаше данак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'А међа Аморејима бјеше од горе Акравимске, од стијене па на више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'И дође анђео Господњи од Галгала у Воким и рече: извео сам вас из Мисира и довео вас у земљу за коју сам се заклео оцима вашим; и рекох: нећу покварити завјета својега с вама довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'А ви не хватајте вјере са становницима те земље, олтаре њихове раскопајте. Али не послушасте гласа мојега. Шта сте то учинили?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Зато и ја рекох: нећу их одагнати испред вас, него ће вам бити као трње, и богови њихови биће вам замка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'А кад изговори анђео Господњи ове ријечи свијем синовима Израиљевијем, народ подиже глас свој и плака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Зато прозваше оно мјесто Воким; и ондје принесоше жртве Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'А Исус распусти народ, и разидоше се синови Израиљеви сваки на своје нашљедство, да наслиједе земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'И служи народ Господу свега вијека Исусова и свега вијека старјешина који живјеше дуго иза Исуса које бијаху видјеле сва велика дјела Господња што учини Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Али умрије Исус син Навин слуга Господњи, кад му бјеше сто и десет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'И погребоше га у међама нашљедства његова у Тамнат-Аресу у гори Јефремовој са сјевера гори Гасу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'И сав онај нараштај прибра се к оцима својим, и наста други нараштај иза њих, који не познаваше Господа ни дјела која је учинио Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'И синови Израиљеви, чинише што је зло пред Господом, и служише Валима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'И оставише Господа Бога отаца својих, који их је извео из земље Мисирске, и пођоше за другим боговима између богова онијех народа који бијаху око њих, и клањаше им се, и разгњевише Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'И оставише Господа, и служише Валу и Астаротама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'И разгњеви се Господ на Израиља, и даде их у руке људима који их плијењаху, и продаде их у руке непријатељима њиховијем унаоколо, и не могаше се више држати пред непријатељима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Куд год полажаху, рука Господња бјеше против њих на зло, као што бјеше рекао Господ и као што им се бјеше заклео Господ; и бијаху у великој невољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Тада им Господ подизаше судије, који их избављаху из руку онијех што их плијењаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Али ни судија својих не слушаше, него чинише прељубу за другим боговима, и клањаше им се; брзо зађоше с пута којим идоше оци њихови слушајући заповијести Господње; они не чинише тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'И кад им Господ подизаше судије, бијаше Господ са сваким судијом, и избављаше их из руку непријатеља њиховијех свега вијека судијина; јер се сажали Господу ради њихова уздисања на оне који им криво чињаху и који их цвијељаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'А кад судија умрије, они се враћаху опет и биваху гори од отаца својих идући за боговима другим и служећи им и клањајући им се; не остављаху се дјела својих нити путова својих опаких.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Зато се распали гњев Господњи на Израиља, и рече: кад је тај народ преступио мој завјет који сам заповједио оцима њиховијем, и не послушаше гласа мојега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'Ни ја нећу више ниједнога гонити испред њих између народа које остави Исус кад умрије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Да њима кушам Израиља хоће ли се држати пута Господњега ходећи по њему, као што су се држали оци њихови, или неће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'И Господ остави те народе и не изагна их одмах не предавши их у руке Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'А ово су народи које остави Господ да њима куша Израиљ, све оне који не знаху за ратове Хананске,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Да би барем натражје синова Израиљевијех знало и разумијело што је рат, барем они који од прије нијесу знали:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Пет кнежевина Филистејских, и сви Хананеји и Сидонци и Јевеји, који живљаху на гори Ливану од горе Вал-Ермона до Емата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Ти народи осташе да се Израиљ њима куша, да се види хоће ли слушати заповијести Господње, које је заповједио оцима њиховијем преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'И живљаху синови Израиљеви усред Хананеја и Хетеја и Амореја и Ферезеја и Јевеја и Јевусеја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'И жењаху се кћерима њиховијем и удаваху кћери своје за синове њихове, и служаху боговима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'И чињаху синови Израиљеви што је зло пред Господом, и заборавише Господа Бога својега и служаху Валима и луговима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Зато се разгњеви Господ на Израиља, и даде их у руке Хусан-Рисатајиму цару Месопотамском; и служаше синови Израиљеви Хусан-Рисатајиму осам година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Потом вапише синови Израиљеви ка Господу, и подиже Господ избавитеља синовима Израиљевијем да их избави, Готонила сина Кенезова, млађега брата Халевова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'И бијаше на њему дух Господњи, и суђаше Израиљу; и изиде на војску, и предаде му Господ у руке Хусан-Рисатајима цара Месопотамскога; и рука његова надјача Хусан-Рисатајима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'И земља би мирна четрдесет година. Потом умре Готонило син Кенезов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'А синови Израиљеви стадоше опет чинити што је зло пред Господом; а Господ укријепи Еглона цара Моавскога на Израиља, јер чињаху што је зло пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Јер скупи к себи синове Амонове и Амалике, и изашавши поби Израиља, и освојише град палмов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'И синови Израиљеви служише Еглону цару Моавском осамнаест година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Потом вапише синови Израиљеви ка Господу; и Господ им подиже избавитеља Аода сина Гире сина Венијаминова, човјека који бијаше љевак. И послаше синови Израиљеви по њему дар Еглону цару Моавском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'А Аод начини себи мач са обје стране оштар, од лакта у дужину; и припаса га под хаљине своје уз десну бедрицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'И однесе дар Еглону цару Моавском; а Еглон бјеше човјек врло дебео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'И кад предаде дар, отпусти људе који су носили дар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Па сам вратив се од ликова каменијех, који бијаху код Галгала, рече: имам, царе, неку тајну да ти кажем. А он рече: мучи! И отидоше од њега сви који стајаху пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'А Аод приступи к њему; а он сјеђаше сам у љетној соби; па рече Аод: ријеч Божију имам да ти кажем. Тада он уста с пријестола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'А Аод потеже лијевом руком својом и узе мач од десне бедрице и сатјера му га у трбух,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'И држак уђе за мачем, и сало се склопи за мачем, те не може извући мача из трбуха; и изиде нечист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Потом изиде Аод из собе, и затвори врата за собом и закључа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'А кад он отиде, дођоше слуге, и погледаше, а то врата од собе закључана, па рекоше: ваљда иде напоље у клијети до љетне собе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'И већ им се досади чекати а врата се од собе не отварају, те узеше кључ и отворише, а гле, господар им лежи на земљи мртав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'А Аод докле се они забавише побјеже и прође ликове камене, и утече у Сеирот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'А кад дође, затруби у трубу у гори Јефремовој; и сидоше с њим синови Израиљеви с горе, а он напријед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Па им рече: хајдете за мном, јер Господ предаде вам у руке непријатеље ваше Моавце. И сидоше за њим, и узеше Моавцима бродове Јорданске, и не дадијаху никоме пријећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'И тада побише Моавце, око десет тисућа људи, све богате и храбре, и ниједан не утече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Тако у тај дан потпадоше Моавци под руку Израиљеву; и земља би мирна осамдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'А после њега наста Самегар син Анатов, и поби шест стотина Филистеја останом волујским, и избави и он Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'А по смрти Аодовој опет синови Израиљеви чинише што је зло пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'И Господ их даде у руке Јавину цару Хананском, који владаше у Асору, а војсци његовој бјеше војвода Сисара, који живљаше у Аросету незнабожачком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'И синови Израиљеви вапише ка Господу; јер он имаше девет стотина гвозденијех кола, и веома притјешњаваше синове Израиљеве двадесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'У то вријеме Девора пророчица, жена Лафидотова, суђаше Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'И Девора становаше под палмом између Раме и Ветиља у гори Јефремовој, и долажаху к њој синови Израиљеви на суд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'А она пославши дозва Варака сина Авинејемова из Кедеса Нефталимова, и рече му: није ли заповједио Господ Бог Израиљев: иди, скупи народ на гору Тавор, и узми са собом десет тисућа људи између синова Нефталимовијех и синова Завулоновијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Јер ћу довести к теби на поток Кисон Сисару војводу Јавинова и кола његова и људство његово, и предаћу га теби у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'А Варак јој рече: ако ћеш ти ићи са мном, ићи ћу; ако ли нећеш ићи са мном, нећу ићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'А она рече: ја ћу ићи с тобом, али нећеш имати славе на путу којим ћеш ићи; јер ће жени у руку дати Господ Сисару. И уставши Девора отиде с Вараком у Кедес.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'И Варак сазвавши синове Завулонове и Нефталимове у Кедес, поведе са собом десет тисућа људи; и Девора иђаше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'А Евер Кенејин бјеше се одвојио од Кенеја, од синова Овава таста Мојсијева, и бјеше разапео свој шатор код храстова Занајимских, а то је код Кедеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'И јавише Сисари да је изашао Варак син Авинејемов на гору Тавор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'И Сисара скупи сва кола своја, девет стотина кола гвозденијех, и сав народ који бијаше с њим од Аросета незнабожачкога до потока Кисона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Тада рече Девора Вараку: устани, јер је ово дан, у који ти даде Господ Сисару у руке. Не иде ли Господ пред тобом? и Варак сиђе с горе Тавора, и десет тисућа људи за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'И Господ смете Сисару и сва кола његова и сву војску оштрим мачем пред Вараком; и Сисара сиђе с кола својих и побјеже пјешице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'А Варак потјера кола и војску до Аросета незнабожачкога; и паде сва војска Сисарина од оштрога мача, не оста ниједан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'А Сисара утече пјешице до шатора Јаиље жене Евера Кенејина; јер бијаше мир међу Јавином царем Асорским и домом Евера Кенејина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'И изиде Јаиља на сусрет Сисари, и рече му: склони се, господару, склони се код мене; не бој се. И он се склони код ње у шатор, и она га покри покривачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'А он јој рече: дај ми мало воде да се напијем, јер сам жедан. А она отвори мијех млијека и напоји га, па га покри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'А он јој рече: стој на вратима од шатора, и ако ко дође и запита те и рече: има ли ту ко? реци: нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Тада Јаиља жена Еверова узе колац од шатора, и узе маљ у руку, и приступи к њему полако, и сатјера му колац кроз слијепе очи, те прође у земљу, кад спаваше тврдо уморан, и умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'И гле, Варак тјераше Сисару, и Јаиља му изиде на сусрет, и рече му: ходи да ти покажем човјека којега тражиш. И уђе к њој, и гле Сисара лежаше мртав, и колац му у слијепијем очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Тако покори Бог у онај дан Јавина цара Хананскога пред синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'И рука синова Израиљевијех биваше све тежа Јавину цару Хананском, докле не истријебише Јавина цара Хананскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'И у тај дан пјева Девора и Варак син Авинејемов говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Благосиљајте Господа што учини освету у Израиљу и што народ драговољно приста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Чујте цареви, слушајте кнезови; ја, ја ћу Господу пјевати, попијеваћу Господу Богу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Господе! кад си слазио са Сира, кад си ишао из поља Едомскога, земља се тресијаше, и небеса капаху, облаци капаху водом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Брда се растапаху пред Господом; тај Синај пред Господом Богом Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'За времена Самегара сина Анатова, за времена Јаиљина неста путова, и који иђаху стазама, иђаху кривијем путовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Неста села у Израиљу, неста их, докле не настах ја, Девора, докле не настах мајка Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Он изабра нове богове, тада рат бијаше на вратима; виђаше ли се штит или копље међу четрдесет тисућа у Израиљу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Срце се моје привило к управитељима Израиљевијем, који драговољно присташе између народа. Благосиљајте Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Који јашете на бијелијем магарицама, који сједите у суду и који ходите по путовима, приповиједајте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Престала је праска стрељачка на мјестима гдје се вода црпе; ондје нека приповиједају правду Господњу, правду к селима његовијем у Израиљу; тада ће народ Господњи слазити на врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Устани, устани, Деворо; устани, устани, запјевај пјесму; устани, Вараче, води у ропство робље своје, сине Авинејемов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Сада ће потлачени обладати силнима из народа; Господ ми даде да владам силнима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Из Јефрема изиде коријен њихов на Амалике; за тобом бјеше Венијамин с народом твојим; од Махира изидоше који постављају законе, а од Завулона писари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'И кнезови Исахарови бише с Девором, Исахар као и Варак би послан у долину с људима које вођаше. У дијелу Рувимову бијаху људи високих мисли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Што си сједио међу торовима слушајући како блеје стада? У дијелу Рувимову бијаху људи високих мисли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Галад оста с ону страну Јордана; а Дан што се забави код лађа? Асир зашто сједе на бријегу морском и у кршевима својим оста?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Завулон је народ који даде душу своју на смрт, тако и Нефталим, на високом пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Дођоше цареви, бише се; бише се цареви Ханански у Танаху на води Мегидској; али ни мрве сребра не добише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'С неба се војева, звијезде с мјеста својих војеваше на Сисару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Поток Кисон однесе их, поток Кадимин, поток Кисон; погазила си, душо моја, снажно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Тада изотпадаше коњма копита од тјерања јунака њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Проклињите Мироз, рече анђео Господњи, проклињите становнике његове; јер не дођоше у помоћ Господу, у помоћ Господу с јунацима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Да је благословена мимо жене Јаиља жена Евера Кенејина; мимо жене у шаторима да је благословена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Заиска воде, млијека му даде, у господској здјели донесе му повлаку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Лијевом руком маши се за колац а десном за маљ ковачки, и удари Сисару, размрска му главу; прободе и проби му слијепе очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Међу ноге њезине сави се, паде, лежа; међу ноге њезине сави се, паде; гдје се сави, ондје паде мртав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'С прозора гледаше мајка Сисарина, и кроз решетку викаше: што се тако дуго не враћају кола његова? што се тако полако мичу точкови кола његовијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Најмудрије између дворкиња њезинијех одговараху јој, а и сама одговараше себи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Нијесу ли нашли? не дијеле ли плијен? по једну дјевојку, по двије дјевојке на свакога. Плијен шарен Сисари, плијен шарен, везен; шарен, везен с обје стране, око врата онима који заплијенише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Тако да изгину сви непријатељи твоји, Господе; а који те љубе да буду као сунце кад излази у сили својој. И земља би мирна четрдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'А синови Израиљеви чинише што је зло пред Господом, и Господ их даде у руке Мадијанима за седам година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'И осили рука Мадијанска над Израиљем, те од страха Мадијанскога начинише себи синови Израиљеви јаме које су по горама, и пећине и ограде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'И кад би Израиљци посијали, долажаху Мадијани и Амалици и источни народ, долажаху на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'И ставши у око против њих, потираху род земаљски дори до Газе, и не остављаху хране у Израиљу, ни овце ни вола ни магарца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Јер се подизаху са стадима својим и са шатором својим, и долажаху као скакавци, тако много, и не бјеше броја њима и камилама њиховијем, и долазећи у земљу пустошаху је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Тада осиромаши Израиљ веома од Мадијана, и повикаше ка Господу синови Израиљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'А кад повикаше синови Израиљеви ка Господу од Мадијана,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Господ посла пророка синовима Израиљевијем, а он им рече: овако вели Господ Бог Израиљев: ја сам вас извео из Мисира, и извео сам вас из дома ропскога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'И избавио сам вас из руке Мисирске и из руке свијех онијех који вас мучаху; и одагнао сам их испред вас, и дао сам вама земљу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Пак вам рекох: ја сам Господ Бог ваш, на бојте се богова Амореја у којих земљи живите. Али не послушасте гласа мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Потом дође анђео Господњи и сједе под храстом у Офри који бијаше Јоаса Авијезерита; а син његов Гедеон врсијаше пшеницу на гумну, да би побјегао с њом од Мадијана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'И јави му се анђео Господњи, и рече му: Господ је с тобом, храбри јуначе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'А Гедеон му рече: о господару мој! кад је Господ с нама, зашто нас снађе све ово? и гдје су сва чудеса његова, која нам приповиједаше оци наши говорећи: није ли нас Господ извео из Мисира? а сада нас је оставио Господ и предао у руке Мадијанима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'А Господ га погледа и рече му: иди у тој сили својој, и избавићеш Израиља из руку Мадијанских. Не послах ли те?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'А он му рече: о Господе, чим ћу избавити Израиљ? ето, род је мој најсиромашнији у племену Манасијину, а ја сам најмањи у дому оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Тада му рече Господ: ја ћу бити с тобом, те ћеш побити Мадијанце као једнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'А Гедеон му рече: ако сам нашао милост пред тобом, дај ми знак да ти говориш са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Немој отићи одавде докле се ја не вратим к теби и донесем дар свој и ставим преда те. А он рече: чекаћу докле се вратиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Тада отиде Гедеон, и зготови јаре и од ефе брашна хљебове пријесне, и метну месо у котарицу а јуху у лонац, и донесе му под храст, и постави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'А анђео Божји рече му: узми то месо и те хљебове пријесне, и метни на ону стијену, а јуху пролиј. И он учини тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Тада анђео Господњи пружи крај од штапа који му бјеше у руци и дотаче се меса и хљебова пријеснијех; и подиже се огањ са стијене и спали месо и хљебове пријесне. И анђео Господњи отиде испред очију његових.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'А Гедеон видјећи да бјеше анђео Господњи, рече: ах Господе Боже! зато ли видјех анђела Господњега лицем к лицу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'А Господ му рече: буди миран, не бој се, нећеш умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'И Гедеон начини ондје олтар Господу, и назва га мир Господњи. Стоји и данас у Офри Авијезеритској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'И исту ноћ рече му Господ: узми јунца, који је оца твојега, јунца другога од седам година; и раскопај олтар Валов који има отац твој, и исијеци луг који је код њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'И начини олтар Господу Богу својему наврх ове стијене, на згодну мјесту, па онда узми другога јунца, и принеси жртву паљеницу на дрвима онога луга који исијечеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Тада узе Гедеон десет људи између слуга својих, и учини како му заповједи Господ; али се бојаше дома оца својега и мјештана, те не учини дању него учини ноћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'А кад ујутру усташе мјештани, а то раскопан олтар Валов и луг код њега исјечен; а јунац други принесен на жртву паљеницу на олтару начињеном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'И рекоше један другому: ко то учини? И траживши и распитавши рекоше: Гедеон син Јоасов учини то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Па рекоше мјештани Јоасу: изведи сина својега да се погуби, што раскопа олтар Валов и што исијече луг код њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'А Јоас рече свјема који стајаху око њега: ви ли хоћете да браните Вала? ви ли хоћете да га избавите? ко га брани, погинуће јутрос. Ако је бог, нека сам расправи с њим што му је раскопао олтар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'И прозва га онога дана Јеровал говорећи: нека расправи с њим Вал што му је раскопао олтар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'А сви Мадијани и Амалици и источни народ бијаху се скупили и прешавши преко Јордана бијаху стали у око у долини Језраелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'А дух Господњи наоружа Гедеона, и он затруби у трубу, и скупи око себе породицу Авијезерову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'И посла гласнике по свему племену Манасијину, и скупише се око њега; посла гласнике и у племе Асирово и Завулоново и Нефталимово, те и они изидоше пред њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Тада рече Гедеон Богу: ако ћеш ти избавити мојом руком Израиља, као што си рекао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'Ево, ја ћу метнути руно на гумну: ако роса буде само на руну а по свој земљи сухо, онда ћу знати да ћеш мојом руком избавити Израиља, као што си рекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'И би тако; јер кад уста сјутрадан, исциједи руно, и истече роса из руна пуна здјела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Опет рече Гедеон Богу: немој се гњевити на ме, да проговорим још једном; да обидем руном још једном, нека буде само руно сухо, а по свој земљи нека буде роса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'И Бог учини тако ону ноћ; и би само руно сухо а по свој земљи би роса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'И урани Јеровал, то је Гедеон, и сав народ што бијаше с њим, и стадоше у око код извора Арода; а војска Мадијанска бјеше му са сјевера крај горе Мореха у долини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'А Господ рече Гедеону: много је народа с тобом, зато им нећу дати Мадијана у руке, да се не би хвалио Израиљ супрот мени говорећи: моја ме рука избави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Него сада огласи да чује народ и реци: ко се боји и кога је страх, нека се врати и нек иде одмах ка гори Галаду. И врати се из народа двадесет и двије тисуће; а десет тисућа оста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Опет рече Господ Гедеону: још је много народа; сведи их на воду, и ондје ћу ти их пребрати; за којега ти год речем: тај нека иде с тобом, нека иде с тобом; а за кога ти год речем: тај нека не иде с тобом, нека не иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'И сведе народ на воду; а Господ рече Гедеону: који стане лаптати језиком воду, као што лапће пас, метни га на страну; тако и свакога који клекне на колена да пије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'И онијех који лапташе, руком својом к устима принесавши воду, бјеше три стотине људи; а сав остали народ клече на кољена своја да пију воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Тада рече Господ Гедеону: с тијех триста људи који лапташе воду избавићу вас и предаћу ти у руке Мадијане; нека дакле одлази сав овај народ свако на своје мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'И народ узе брашњенице и трубе; и Гедеон отпусти све људе Израиљце да иду сваки у свој шатор, а онијех триста људи задржа. А око Мадијански бијаше ниже њега у долини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'И ону ноћ рече му Господ: устани, сиђи у око, јер ти га дадох у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Ако ли се бојиш сам сићи, сиђи у око са Фуром момком својим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'И чућеш шта говоре, па ће ти осилити руке и ударићеш на око. И сиђе он и Фура момак његов до краја војске која бијаше у околу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'А Мадијани и Амалици и сав народ источни лежаху по долини као скакавци, тако их бјеше много; и камилама њиховијем не бјеше броја; бјеше их много као пијеска по бријегу морском,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'И кад дође Гедеон, а то један приповиједаше другу својему сан, и говораше: гле, усних, а то печен хљеб јечмен котрљаше се к околу Мадијанском и дође до шатора и стаде ударати о њих, те падаху, и испремета их, и попадаше шатори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'А друг му одговори и рече: то није друго него мач Гедеона сина Јоасова човјека Израиљца; предао му је у руке Бог Мадијане и сав овај око.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'И кад Гедеон чу како онај приповједи сан и како га овај истумачи, поклони се и врати се у око Израиљски и рече: устајте, јер вам даде Господ у руке око Мадијански.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Потом раздијели триста људи у три чете, и даде свакоме по трубу у руку и по празан жбан и по луч у жбан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'И рече им: на мене гледајте, па тако чините; гле, је ћу доћи на крај окола, па шта ја ушчиним, то чините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Кад ја затрубим у трубу и сви који буду са мном, тада и ви затрубите у трубе око свега окола, и вичите: мач Господњи и Гедеонов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'И дође Гедеон и сто људи што бијаху с њим на крај окола, у почетак средње страже, истом бијаху промијенили стражу; а они затрубише у трубе и полупаше жбанове које имаху у рукама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Тако три чете затрубише у трубе и полупаше жбанове, и држаху у лијевој руци лучеве а у десној трубе трубећи, и повикаше: мач Господњи и Гедеонов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'И стадоше сваки на свом мјесту око војске; а сва се војска смете и стадоше викати и бјежати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'А кад затрубише у трубе онијех три стотине, Господ обрати мач свакоме на друга његова по свему околу, те побјеже војска до Вет-Асете, у Зерерат, до обале Авел-меолске код Тавата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'А Израиљци из племена Нефталимова и Асирова и из свега племена Манасијина стекоше се и гонише Мадијане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'И Гедеон посла гласнике по свој гори Јефремовој говорећи: сиђите пред Мадијане и ухватите им воде до Ветваре дуж Јордана. И стекоше се сви људи из племена Јефремова и ухватише воде до Ветваре дуж Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'И ухватише два кнеза Мадијанска, Орива и Зива, и убише Орива на стијени Оривовој, а Зива убише код тијеска Зивова; и гонише Мадијане, и донесоше главу Оривову и Зивову ка Гедеону преко Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'А људи од племена Јефремова рекоше му: шта нам то учини те нас не позва кад пође у бој на Мадијане? и викаху на њ жестоко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'А он им рече: па шта сам учинио тако као ви? Није ли пабирчење Јефремово боље него берба Авијезерова?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Вама је у руке дао Господ кнезове Мадијанске, Орива и Зива; па што ја могох учинити тако као ви? Тада се утиша дух њихов према њему кад тако говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'А кад Гедеон дође на Јордан, пријеђе преко њега с триста људи који бјеху с њим, а бјеху уморни гонећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Па рече људима Сокоћанима: дајте неколико хљебова народу који иде за мном, јер су уморни, а ја гоним Зевеја и Салмана цареве Мадијанске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'А главари Сокотски рекоше му: је ли песница Зевејева и Салманова већ у твојој руци да дамо хљеба твојој војсци?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'А Гедеон им рече: кад ми Бог преда Зевеја и Салмана у руку, тада ћу помлатити тјелеса ваша трњем из ове пустиње и драчом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'И отиде оданде у Фануил, и рече Фануиљанима исто онако, а они му одговорише као што одговорише људи у Сокоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Зато и људима Фануиљанима рече: кад се вратим здраво, развалићу ту кулу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'А Зевеј и Салман бијаху у Каркору, и војска њихова с њима, око петнаест тисућа, што их год оста од све војске источне; а побијенијех бијаше сто и двадесет тисућа људи који махаху мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'И отиде Гедеон преко онијех што живе под шаторима, с истока Нови и Јогвеји, и удари на војску кад војска стајаше безбрижна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'А Зевеј и Салман побјегоше, а он их потјера, и ухвати два цара Мадијанска, Зевеја и Салмана, и распуди сву војску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'И врати се Гедеон син Јоасов из боја прије сунчанога рођаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'И ухвати момка из Сокота, и испитива га; а он му пописа кнезове Сокотске и старјешине, седамдесет и седам људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Па кад дође к Сокоћанима, рече: ево Зевеја и Салмана, за које ми се ругасте говорећи: је ли песница Зевејева и Салманова већ у твојој руци, да дамо хљеба уморнијем људима твојим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'И узевши старјешине онога мјеста и трња из пустиње и драче даде на њима углед Сокоћанима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'И кулу Фануилску развали и поби људе тамошње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Потом рече Зевеју и Салману: каки бјеху људи које побисте на Тавору? А они рекоше: таки као ти; сваки бјеше као на очима као царски син.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'А он рече: то бјеху моја браћа, синови моје матере. Тако Господ био жив! да сте их оставили у животу, не бих вас погубио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Тада рече Јетеру првенцу својему: устани, погуби их. Али дијете не извуче мача својега, јер се бојаше, јер бјеше још дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Тада рече Зевеј и Салман: устани ти, уложи на нас; јер какав је човјек онака му је и снага. И уставши Гедеон погуби Зевеја и Салмана, и узе мјесечиће који бијаху о вратовима камила њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Потом рекоше Израиљци Гедеону: буди нам господар ти и син твој и син сина твојега, јер си нас избавио из руке Мадијанске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'А Гедеон им рече: нећу вам ја бити господар, нити ће вам син мој бити господар; Господ ће вам бити Господар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Још им рече Гедеон: једно ћу искати од вас: да ми дате сваки гривну од плијена својега. А гривне имаху златне, јер бјеху Исмаиљци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'И одговорише: даћемо драге воље. И разастрвши хаљину бацише на њу гривне, сваки од плијена својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'И бјеше на меру златнијех гривана што изиска тисућа и седам стотина сикала злата, осим мјесечића и ланчића и хаљина скерлетнијех, што ношаху цареви Мадијански, и осим литарова, што бијаху око врата камила њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'И Гедеон начини од тога оплећак, и остави га у својем граду Офри; и ондје сав Израиљ стаде чинити прељубу за њим, и би Гедеону и дому његову замка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Тако бише покорени Мадијани пред синовима Израиљевијем, и више не дигоше главе. И земља би мирна четрдесет година за вијека Гедеонова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'И отишав Јеровал син Јоасов оста у својој кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'И имаше Гедеон седамдесет синова, који изидоше од бедара његовијех, јер имаше много жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'И иноча његова, која бијаше у Сихему, и она му роди сина, и надје му име Авимелех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Потом умрије Гедеон син Јоасов у доброј старости, и би погребен у гробу Јоаса оца својега Авијезерита у Офри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'И кад умрије Гедеон, опет синови Израиљеви чинише прељубу за Валима, и поставише себи Вал-Верита за бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'И не сјећаше се синови Израиљеви Господа Бога својега, који их је избавио из руку свијех непријатеља њиховијех унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'И не учинише милости дому Јеровала Гедеона према свему добру што је он учинио Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'И Авимелех син Јеровалов отиде у Сихем к браћи матере своје и рече њима и свему роду отачкога дома матере своје говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Кажите свијем Сихемљанима: шта вам је боље, да су вам господари седамдесет људи, сви синови Јеровалови, или да вам је господар један човјек? и опомињите се да сам ја кост ваша и тијело ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Тада рекоше браћа матере његове за њ свијем Сихемљанима све те ријечи, и срце њихово приви се к Авимелеху, јер рекоше: наш је брат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'И дадоше му седамдесет сикала сребра из дома Вал-Веритова, за које најми Авимелех људи празнова и скитнице, те иђаху за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'И дође у кућу оца својега у Офру, и поби браћу своју, синове Јеровалове, седамдесет људи, на једном камену; али оста Јотам најмлађи син Јеровалов, јер се сакри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Тада се скупише сви Сихемљани и сав дом Милов, и отидоше и поставише Авимелеха царем код храста који стоји у Сихему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'А кад то јавише Јотаму, отиде и стаде наврх горе Гаризина, и подигавши глас свој повика и рече им: чујте ме, Сихемљани, тако вас Бог чуо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Ишла дрвета да помажу себи цара, па рекоше маслини: буди нам цар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'А маслина им рече: зар ја да оставим претилину своју, којом се част чини Богу и људима, па да идем да тумарам за друга дрвета?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Потом рекоше дрвета смокви: ходи ти, буди нам цар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'А смоква им рече: зар ја да оставим сласт своју и красни род свој, па да идем да тумарам за друга дрвета?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Тада рекоше дрвета виновој лози: ходи ти, буди нам цар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'А лоза им рече: зар ја да оставим вино своје, које весели Бога и људе, па да идем да тумарам за друга дрвета?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Тада сва дрвета рекоше трну: ходи ти, буди нам цар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'А трн одговори дрветима: ако доиста хоћете мене да помажете себи за цара, ходите склоните се у хлад мој; ако ли нећете, нека изиде огањ из трна и спали кедре Ливанске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Тако сада, јесте ли право и поштено радили поставивши Авимелеха царем? и јесте ли добро учинили Јеровалу и дому његову? и јесте ли му учинили како вас је задужио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'Јер је отац мој војевао за вас и није марио за живот свој, и избавио вас је из руку Мадијанских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'А ви данас устасте на дом оца мојега, и побисте синове његове, седамдесет људи, на једном камену, и постависте царем Авимелеха, сина слушкиње његове, над Сихемљанима зато што је брат ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Ако сте право и поштено радили данас према Јеровалу и његову дому, веселите се с Авимелеха и он нека се весели с вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Ако ли нијесте, нека изиде огањ од Авимелеха и спали Сихемљане и дом Милов, и нека изиде огањ од Сихемљана и од дома Милова и спали Авимелеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Тада побјеже Јотам, и побјегав дође у Вир, и ондје оста бојећи се Авимелеха брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'И влада Авимелех Израиљем три године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Али Бог пусти злу вољу међу Авимелеха и међу Сихемљане; и Сихемљани изневјерише Авимелеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Да би се осветила неправда учињена на седамдесет синова Јероваловијех, и крв њихова да би дошла на Авимелеха брата њихова, који их уби, и на Сихемљане, који укријепише руку његову да убије браћу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'И Сихемљани пометаше му засједе по врховима горским, па плијењаху све који пролажаху мимо њих онијем путем. И би јављено Авимелеху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Потом дође Гал син Еведов са својом браћом, и уљезоше у Сихем, и Сихемљани се поуздаше у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'И изишавши у поље браше винограде своје и газише грожђе, и веселише се; и уђоше у кућу бога својега, и једоше и пише, и псоваше Авимелеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'И Гал син Еведом рече: ко је Авимелех и шта је Сихем, да му служимо? Није ли син Јеровалов? А Зевул није ли његов пристав? Служите синовима Емора оца Сихемова. А што бисмо служили тому?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'О кад би тај народ био под мојом руком, да сметнем Авимелеха! И рече Авимелеху: прикупи војску своју, и изиди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'А кад чу Зевул, управитељ градски, ријечи Гала сина Еведова, разгњеви се врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'И посла тајно посланике к Авимелеху и поручи му: ево Гал син Еведов и браћа му дођоше у Сихем, и ево побунише град на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Него устани ноћу ти и народ што је с тобом, и засједи у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'А ујутру кад сунце огране, дигни се и удари на град; и ево он и народ који је с њим изићи ће преда те, па учини с њим што ти може рука.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'И Авимелех уста ноћу и сав народ што бјеше са њим; и засједоше Сихему у четири чете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'А Гал син Еведов изиде и стаде пред вратима градским; а Авимелех и народ што бјеше са њим изиде из засједе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'А Гал видјев народ рече Зевулу: ено народ слази сврх горе. А Зевул му одговори: од сјена горскога чине ти се људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Опет проговори Гал и рече: ено народ слази с виса, и чета једна иде путем к шуми Меоненимској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'А Зевул му рече: гдје су ти сада уста, којима си говорио: ко је Авимелех да му служимо? Није ли то онај народ који си презирао? Изиди сада, и биј се с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'И изиде Гал пред Сихемљанима, и поби се с Авимелехом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Али Авимелех га потјера, и он побјеже од њега; и падоше многи побијени до самијех врата градских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'И Авимелех оста у Аруми; а Зевул истјера Гала и браћу његову, те не могаху сједети у Сихему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'А сјутрадан изиде народ у поље, и би јављено Авимелеху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'А он узе народ свој и раздијели га у три чете, и намјести их у засједу у пољу; и кад видје гдје народ излази из града, скочи на њих и поби их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Јер Авимелех и чета која бијаше с њим ударише и стадоше код врата градских; а друге двије чете ударише на све оне који бијаху у пољу, и побише их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'И Авимелех бијаше град цео онај дан, и узе га, и поби народ који бјеше у њему, и раскопа град, и посија со по њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'А кад то чуше који бијаху у кули Сихемској, уђоше у кулу куће бога Верита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'И би јављено Авимелеху да су се ондје скупили сви који бијаху у кули Сихемској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Тада Авимелех изиде на гору Салмон, он и сав народ што бјеше с њим; и узев Авимелех сјекиру у руку отсијече грану од дрвета и метну је на раме, и рече народу који бијаше с њим: што видјесте да сам ја учинио, брзо чините као ја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'И сваки из народа отсијече себи грану, и пођоше за Авимелехом и пометаше гране око куле, и запалише њима град; и изгибоше сви који бијаху у кули Сихемској, око тисућу људи и жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Потом отиде Авимелех на Тевес, и стаде у око код Тевеса, и узе га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'А бијаше тврда кула усред града, и у њу побјегоше сви људи и жене и сви грађани, и затворивши се попеше се на кров од куле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'А Авимелех дође до куле и удари на њу, и дође до врата од куле да је запали огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Али једна жена баци комад жрвња на главу Авимелеху и разби му главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'А он брже викну момка који му ношаше оружје, и рече му: извади мач свој и убиј ме, да не реку за ме: жена га је убила. И прободе га слуга његов, те умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'А кад видјеше Израиљци гдје погибе Авимелех, отидоше сваки у своје мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Тако плати Бог Авимелеху за зло које је учинио оцу својему убивши седамдесет браће своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'И све зло људи Сихемљана поврати Бог на њихове главе, и стече им се клетва Јотама сина Јеровалова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'А после Авимелеха уста да избави Израиља Тола син Фуве сина Додова, човјек племена Исахарова, који сјеђаше у Самиру у гори Јефремовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'И би судија Израиљу двадесет и три године, па умрије и би погребен у Самиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Послије њега уста Јаир од племена Галадова, и би судија Израиљу двадесет и двије године;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'И имаше тридесет синова, који јахаху на тридесеторо магаради, и имаху тридесет градова, који се зову села Јаирова до данас и јесу у земљи Галадовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'И умрије Јаир, и би погребен у Камону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'А синови Израиљеви опет чинише што је зло пред Господом, и служише Валима и Астаротама, и боговима Сирским, и боговима Сидонским, и боговима Моавским, и боговима синова Амоновијех и боговима Филистејским; и оставише Господа и не служише му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Зато се разгњеви Господ на Израиља, те их даде у руке Филистејима и у руке синовима Амоновијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'А они газише и сатираше синове Израиљеве од оне године осамнаест година, све синове Израиљеве који бијаху с ону страну Јордана, у земљи Аморејској, која је у Галаду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'И пријеђоше синови Амонови преко Јордана да се бију и с Јудом и с Венијамином и с домом Јефремовијем; и би Израиљ у великој невољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Тада вапише синови Израиљеви ка Господу говорећи: сагријешисмо ти што остависмо Бога својега и служисмо Валима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'А Господ рече синовима Израиљевијем: од Мисираца и Амореја и од синова Амоновијех и од Филистеја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'И од Сидоњана и од Амалика и од Амонаца, који вас мучише, нијесам ли вас избављао кад вапијасте к мени?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Али ви остависте мене и служисте другим боговима; зато вас више нећу избављати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Идите и вичите оне богове које сте изабрали, нека вас они избаве у невољи вашој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'А синови Израиљеви рекоше Господу: сагријешисмо; чини с нама што ти је драго, само нас сада избави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'И побацаше између себе богове туђе, и стадоше служити Господу; и сажали му се ради муке синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'А синови Амонови скупише се и стадоше у око у Галаду; скупише се и синови Израиљеви и стадоше у око у Миспи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'А народ и кнезови Галадски рекоше један другому: ко ће почети бој са синовима Амоновијем? он нека буде поглавар свјема који живе у Галаду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'А Јефтај од Галада бијаше храбар јунак, али син једне курве, с којом Галад роди Јефтаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Али Галаду и жена његова роди синова, па кад дорастоше синови те жене, отјераше Јефтаја рекавши му: нећеш имати нашљедства у дому оца нашега, јер си син друге жене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Зато побјеже Јефтај од браће своје, и настани се у земљу Тову; и стекоше се к њему људи празнови, и иђаху с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'А послије некога времена завојштише синови Амонови на Израиља;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'И кад завојштише синови Амонови на Израиља, отидоше старјешине Галадске да доведу Јефтаја из земље Това.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'И рекоше Јефтају: ходи и буди нам војвода, да војујемо са синовима Амоновијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'А Јефтај рече старјешинама Галадским: не мрзите ли ви на ме, и не истјерасте ли ме из дома оца мојега? Што сте дакле дошли к мени сада кад сте у невољи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'А старјешине Галадске рекоше Јефтају: зато смо сада дошли опет к теби да пођеш с нама и да војујеш са синовима Амоновијем и да нам будеш поглавар свјема који живимо у Галаду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'А Јефтај рече старјешинама Галадским: кад хоћете да ме одведете натраг да војујем са синовима Амоновијем, ако ми их да Господ, хоћу ли вам бити поглавар?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'А старјешине Галадске рекоше Јефтају: Господ нека буде свједок међу нама, ако не учинимо како си казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Тада отиде Јефтај са старјешинама Галадским, и народ га постави поглаварем и војводом над собом: и Јефтај изговори пред Господом у Миспи све ријечи које бјеше рекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Потом посла Јефтај посланике к цару синова Амоновијех, и поручи: шта имаш ти са мном, те си дошао к мени да ратујеш по мојој земљи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'А цар синова Амоновијех рече посланицима Јефтајевим: што је узео Израиљ моју земљу кад дође из Мисира, од Арнона до Јавока и до Јордана; сада дакле врати ми је с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Али Јефтај посла опет посланике к цару синова Амоновијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'И поручи му: овако вели Јефтај: није узео Израиљ земље Моавске ни земље синова Амоновијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Него изашавши из Мисира пријеђе Израиљ преко пустиње до Црвенога Мора и дође до Кадиса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'И посла Израиљ посланике к цару Едомскому и рече: пусти да прођем кроз твоју земљу. Али не послуша цар Едомски. Посла такође к цару Моавскому; али ни он не хтје. И тако стаја Израиљ у Кадису.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Потом идући преко пустиње обиде земљу Едомску и земљу Моавску, и дошавши с Истока земљи Моавској стаде у око с ону страну Арнона; али не пријеђоше преко међе Моавске, јер Арнон бјеше међа Моавска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Него посла Израиљ посланике к Сиону цару Аморејскому, цару Есевонскому, и рече му Израиљ: допусти нам да прођемо кроз твоју земљу до својега мјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Али Сион не вјерова Израиљу да га пусти да пријеђе преко међе његове, него Сион скупи сав свој народ и стадоше у око у Јаси, и поби се са Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'А Господ Бог Израиљев предаде Сиона и сав народ његов у руке синовима Израиљевим, те их побише; и задоби Израиљ сву земљу Амореја, који живљаху у оној земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Задобише сву земљу Аморејску од Арнона до Јавока, и од пустиње до Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Тако је дакле Господ Бог Израиљев отјерао Амореје испред народа својега Израиља, па ти ли хоћеш да је земља њихова твоја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Није ли твоје оно што ти да да је твоје Хемос бог твој? тако кога год Господ Бог наш отјера испред нас, онога је земља наша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Или си ти по чем бољи од Валака сина Сефорова цара Моавскога? Је ли се он кад свађао с Израиљем? Је ли кад војевао с нама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Израиљ живи у Есевону и у селима његовијем и у Ароиру и селима његовијем и по свијем градовима дуж Арнона три стотине година; зашто не отесте за толико времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'И тако нијесам ја теби скривио, него ти мени чиниш зло ратујући на ме. Господ судија нек суди данас између синова Израиљевијех и синова Амоновијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Али цар синова Амоновијех не послуша ријечи које му поручи Јефтај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'И сиђе на Јефтаја дух Господњи, те прође кроз Галад и кроз Манасију, прође и Миспу Галадску, и од Миспе Галадске дође до синова Амоновијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'И завјетова Јефтај завјет Господу и рече: ако ми даш синове Амонове у руке,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'Што год изиде на врата из куће моје на сусрет мени, кад се вратим здрав од синова Амоновијех, биће Господње, и принијећу на жртву паљеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'И тако дође Јефтај до синова Амоновијех да се бије с њима; и Господ му их даде у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'И поби их од Ароира па до Минита у двадесет градова и до равнице виноградске у боју врло великом; и синови Амонови бише покорени пред синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'А кад се враћаше Јефтај кући својој у Миспу, гле, кћи његова изиде му на сусрет с бубњима и свиралама; она му бијаше јединица, и осим ње не имаше ни сина ни кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Па кад је угледа, раздрије хаљине своје и рече: ах кћери моја! веле ли ме обори! ти си од онијех што ме цвијеле; јер сам отворио уста своја ка Господу и не могу порећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'А она му рече: оче мој, кад си отворио уста своја ка Господу, учини ми, како је изашло из уста твојих, кад те је Господ осветио од непријатеља твојих, синова Амоновијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Још рече оцу својему: учини ми ово: остави ме до два мјесеца да отидем да се попнем на горе да оплачем своје дјевојаштво с другама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'А он јој рече: иди. И пусти је на два мјесеца, и она отиде с другама својим и оплакива дјевојаштво своје по горама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'А кад прођоше два мјесеца, врати се к оцу својему; и он сврши на њој завјет свој који бјеше завјетовао. А она не позна човјека. И поста обичај у Израиљу');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Да од године до године иду кћери Израиљеве да плачу за кћерју Јефтаја од Галада, четири дана у години.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'А људи од племена Јефремова скупише се, и прешавши на сјевер рекоше Јефтају: зашто си ишао у бој на синове Амонове а нас нијеси позвао да идемо с тобом? Спалићемо огњем дом твој и тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'А Јефтај им рече: имах велику распру са синовима Амоновијем ја и мој народ, и позвах вас, али ме не избависте из руку његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Па видећи да ме не избависте, ставих душу своју у руку своју, и отидох на синове Амонове, и Господ ми их даде у руке; па што сте сада дошли к мени да се бијете са мном?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Тада Јефтај скупи све људе од Галада, и удари на Јефрема; и људи од Галада побише Јефрема; јер говораху: бјегунци сте Јефремови ви, људи од Галада, који се бавите међу Јефремом и међу Манасијом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'И Галад узе Јефрему бродове Јорданске. И кад који од Јефрема добјеже и рече: пусти ме да пријеђем, рекоше му они од Галада: јеси ли од Јефрема? и кад он рече: нијесам,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Онда му рекоше: реци: Шиболет. А он рече: Сиболет, не могући добро изговорити. Тада га ухватише и заклаше на броду Јорданском. И погибе у оно вријеме из племена Јефремова четрдесет и двије тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'И Јефтај би судија Израиљу шест година; и умрије, и би погребен у граду Галадском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'А послије њега би судија Израиљу Авесан из Витлејема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'И имаше тридесет синова и тридесет кћери, које разуда из куће, а тридесет дјевојака доведе синовима својим из других кућа; и би судија Израиљу седам година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'И потом умрије Авесан, и би погребен у Витлејему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'А после њега би судија Израиљу Елон од Завулона; он би судија Израиљу десет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Потом умрије Елон од Завулона и би погребен у Ајалону у земљи Завулоновој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Послије њега би судија у Израиљу Авдон син Елилов Фаратоњанин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Он имаше четрдесет синова и тридесет унука, који јахаху седамдесеторо магаради. И би судија Израиљу осам година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Потом умрије Авдон син Елилов Фаратоњанин, и би погребен у Фаратону у земљи Јефремовој на гори Амаличкој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'А синови Израиљеви опет чинише што је зло пред Господом, и Господ их даде у руке Филистејима за четрдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'А бијаше један човјек од Сараје од племена синова Дановијех, по имену Маноје, и жена му бјеше нероткиња, и не рађаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Тој жени јави се анђео Господњи и рече јој: гле, ти си сад нероткиња, и нијеси рађала; али ћеш затрудњети и родићеш сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Него сада чувај се да не пијеш вина ни силовита пића, и да не једеш ништа нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Јер гле, затрудњећеш, и родићеш сина, и бритва да не пријеђе по његовој глави, јер ће дијете бити назиреј Божји од утробе материне, и он ће почети избављати Израиља из руку Филистејских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'И жена дође и рече мужу својему говорећи: човјек Божји дође к мени, и лице му бијаше као лице анђела Божјега, врло страшно; али га не запитах одакле је, нити ми он каза својега имена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Него ми рече: гле, ти ћеш затрудњети, и родићеш сина; зато сада не пиј вина ни силовита пића и не једи ништа нечисто; јер ће дијете бити назиреј Божји од утробе материне па до смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Тада се Маноје помоли Господу и рече: о Господе! нека опет дође к нама човјек Божји, којега си слао, да нас научи шта ћемо чинити са дјететом, кад се роди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'И услиши Господ глас Манојев; и дође опет анђео Господњи к жени кад сјеђаше у пољу; а Маноје муж њезин не бјеше код ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Тада жена брже отрча и јави мужу својему говорећи му: ево, јави ми се онај човјек, који ми је прије долазио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'А Маноје уставши пође са женом својом; и кад дође к човјеку, рече му: јеси ли ти онај човјек што је говорио овој жени? Он одговори: јесам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'А Маноје рече: кад буде што си казао, како ће бити правило за дијете и шта ће чинити с њим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'А анђео Господњи рече Маноју: жена нека се чува од свега што сам јој казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Нека не једе ништа што долази с винове лозе, и вина ни силовита пића нека не пије, и ништа нечисто нека не једе. Што сам јој заповједио све нека држи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Тада рече Маноје анђелу Господњему: ради бисмо те уставити да ти зготовимо јаре,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'А анђео Господњи одговори Маноју: да ме и уставиш, нећу јести твојега јела; него ако хоћеш зготови жртву паљеницу, принеси је Господу. Јер Маноје није знао да је анђео Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Опет рече Маноје анђелу Господњему: како ти је име? да ти захвалимо кад се збуде што си рекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'А анђео Господњи одговори му: што питаш за име моје? Чудно је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Тада Маноје узе јаре и дар, и принесе Господу на стијени; а анђео учини чудо пред Манојем и женом његовом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Јер кад се подиже пламен с олтара к небу, анђео Господњи подиже се у пламену с олтара; а Маноје и жена његова видећи то падоше ничице на земљу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'А анђео се Господњи не јави више Маноју ни жени његовој. Тада Маноје разумје да је анђео Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'И рече Маноје жени својој: зацијело ћемо умријети, јер видјесмо Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'А жена му рече: кад би хтио Бог да нас убије, не би примио из наших руку жртве паљенице ни дара, нити би нам показао свега овога, нити би нам сад објавио таких ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'И тако та жена роди сина, и надје му име Самсон; и дете одрасте, и Господ га благослови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'И дух Господњи поче ходити с њим по околу Данову, између Сараје и Естаола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'И сиђе Самсон у Тамнат, и видје ондје једну дјевојку између кћери Филистејских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'И вративши се каза оцу својему и матери својој говорећи: видјех дјевојку у Тамнату између кћери Филистејских; ожените ме њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'А отац и мати рекоше му: зар нема дјевојке међу кћерима твоје браће у свем народу мом, да идеш да се ожениш између Филистеја необрезанијех? А Самсон одговори оцу својему: њом ме ожени, јер ми је она омиљела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'А отац и мати његова не знадијаху да је то од Господа, и да тражи задјевицу с Филистејима; јер у оно вријеме Филистеји владаху синовима Израиљевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'И тако сиде Самсон с оцем својим и с матером својом у Тамнат, и кад дођоше до винограда Тамнатских, гле, млад лав ричући сукоби га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'И дух Господњи сиде на њ, те растрже лава као јаре немајући ништа у руци: и не каза оцу ни матери шта је учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'И тако дошавши говори с дјевојком, и она омиље Самсону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'А послије неколико дана идући опет да је одведе, сврне да види мртвога лава; а гле, у мртвом лаву рој пчела и мед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'И извади га у руку, и пође путем једући; и кад дође к оцу и матери, даде им те једоше; али им не рече да је из мртвога лава извадио мед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'И тако дође отац његов к оној дјевојци, и Самсон учини ондје весеље, јер тако чињаху момци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'И кад га видјеше Филистеји, изабраше тридесет друга да буду с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'И рече им Самсон: ја ћу вам загоненути загонетку, па ако ми је одгоненете за седам дана док је весеље и погодите, даћу вам тридесет кошуља и тридесеторе свечане хаљине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Ако ли не одгоненете, ви ћете дати мени тридесет кошуља и тридесеторе свечане хаљине. А они му рекоше: загонени загонетку своју, да чујемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Тада им рече: од онога који једе изиде јело, и од љутога изиде слатко. И не могаше одгоненути загонетке три дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'И седми дан рекоше жени Самсоновој: наговори мужа својега да нам каже загонетку, или ћемо спалити огњем тебе и дом оца твојега. Јесте ли нас зато позвали да нам узмете имање? Је ли тако?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'И стаде плакати жена Самсонова пред њим говорећи: ти мрзиш на ме, и ти ме не љубиш; загоненуо си загонетку синовима народа мојега, а нећеш мени да кажеш. А он јој рече: гле, ни оцу својему ни матери својој нијесам је казао, а теби да је кажем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'И она плака пред њим за седам дана докле трајаше весеље. А седми дан каза јој, јер бјеше навалила на њ; а она каза загонетку синовима народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Тада му рекоше људи града онога седми дан док сунце не зађе: шта је слађе од меда, и шта је љуће од лава? А он им рече: да нијесте орали на мојој јуници, не бисте погодили моје загонетке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'И дође на њ дух Господњи, те сиђе у Аскалон, и поби ондје тридесет људи, и узе одијело с њих и даде свечане хаљине онима који одгоненуше загонетку; и расрди се врло и отиде кући оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'А жена Самсонова удаде се за друга његова, с којим се бијаше удружио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'А послије неколико дана, о пшеничној жетви, дође Самсон да походи жену своју донесавши јој јаре, и рече: идем к жени својој у ложницу. Али му отац њезин не даде да уђе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Јер рече отац њезин: ја мишљах зацијело да ти није по вољи, па је дадох другу твојему; него млађа сестра њезина није ли љепша од ње? узми њу мјесто оне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'А Самсон им рече: ја нећу бити крив Филистејима кад им учиним зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'И отишавши Самсон ухвати триста лисица, и узе луча, и свеза по двије у репове, и метну по један луч међу два репа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Па запали лучеве, и пусти у љетину Филистејску, и попали љетину пожњевену и непожњевену, и винограде и маслинике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Тада Филистеји рекоше: ко је то учинио? И одговорише: Самсон зет Тамнаћанинов, јер му узе жену и даде је другу његову.Тада дођоше Филистеји и спалише огњем њу и оца њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'А Самсон им рече: ако сте и учинили тако, опет ћу вам се осветити, па ћу се онда оканити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'И поломи их љуто ногама по бедрима: потом отиде и настани се у пећини од стијене Итама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Тада изидоше Филистеји и стадоше у око према Јуди, и раширише се до Лехије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'А људи од Јуде рекоше: што сте изашли на нас? И одговорише: изашли смо да свежемо Самсона и да му учинимо како је он нама учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Тада изиде три хиљаде људи из Јуде к пећини у стијени Итаму, и рекоше Самсону: не знаш ли да Филистеји владају над нама?А он им рече: како су они мени учинили тако ја учиних њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Они му рекоше: дошли смо да те свежемо и предамо у руке Филистејима.А Самсон им рече: закуните ми се да нећете ви уложити на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Они му одговорише и рекоше: нећемо; него ћемо те само свезати и предати у њихове руке, али те нећемо погубити.И свезаше га у два нова ужа и одведоше га из стијене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'И кад он дође до Лехије, Филистеји га сретоше вичући од радости; а дух Господњи сиђе на њ, и ужа на рукама његовима посташе као конци изгорјели од ватре, и спадоше свезе с руку његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'И он нађе чељуст магарећу још сирову, и пружив руку своју узе је, и поби њом тисућу људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Потом рече Самсон: чељушћу магарећом једну гомилу, двије гомиле, чељушћу магарећом побих тисућу људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'А кад изрече, баци чељуст из руке своје, и назва оно мјесто Рамат-Лехија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'И бијаше жедан јако, те завапи ка Господу и рече: ти си учинио руком слуге својега ово избављење велико; а сад хоћу ли умријети од жеђи, или ћу пасти у руке необрезанима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Тада Бог расцијепи стијену у Лехији, и потече вода из ње, те се напи, и поврати му се дух и оживје. Зато се прозва онај извор Ен-Акоре, који је у Лехији до данашњег дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'И би судија Израиљу за времена Филистејскога двадесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Потом отиде Самсон у Газу, и ондје видје једну жену курву, и уђе к њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'И људима у Гази би казано: дође Самсон овамо.И опколише и вребаше га цијелу ноћ на вратима градским; и стајаху у потаји цијелу ноћ говорећи: док сване, убићемо га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Али Самсон спавав до поноћи уста у поноћи, и шчепа врата градска с оба довратка и ишчупа их с пријеворницом заједно, и метну их на рамена и однесе на врх горе која је према Хеврону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Послије тога замилова дјевојку на потоку Сорику, којој бјеше име Далида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'И дођоше к њој кнезови Филистејски и рекоше јој: превари га и искушај гдје му стоји велика снага и како би смо му досадили да га свежемо и свладамо; а ми ћемо ти дати сваки по хиљаду и сто сребрника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'И Далида рече Самсону: хајде кажи ми гдје стоји твоја велика снага и чим би се могао свезати и свладати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'А Самсон јој рече: да ме свежу у седам гужава сировијех неосушенијех, онда бих изгубио снагу и био као и други човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'И донесоше јој кнезови Филистејски седам гужава сировијех, још неосушенијех, и она га свеза њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'А код ње бијаше засједа у соби; и она му рече: ето Филистеја на те, Самсоне! А он покида гужве, као што се кида конац од кудеље кад осјети ватру; и не дозна се за снагу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Потом рече Далида Самсону: гле, преварио си ме, и слагао си ми; него хајде кажи ми чим би се могао свезати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'А он јој рече: да ме добро свежу новим ужима којима није ништа рађено, тада бих изгубио снагу и био бих као други човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'И Далида узе нова ужа, и свеза га њима, пак му рече: ето Филистеји на те Самсоне! А засједа бијаше у соби. А он раскиде с руку ужа као конац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Тада рече Далида Самсону: једнако ме вараш и лажеш ми; кажи ми чим би се могао свезати? А он јој рече: да седам прамена косе на глави мојој привијеш на вратило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'И она заглавивши вратило коцем, рече: ево Филистеја на те, Самсоне! А он се пробуди од сна, и истрже колац и основу и вратило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Опет му она рече: како можеш говорити: љубим те, кад срце твоје није код мене? Већ си ме три пута преварио не хотећи ми казати гдје ти је велика снага.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'И она му досађиваше својим ријечима сваки дан и наваљиваше на њ, и душа му пренеможе да умре,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Те јој отвори цијело срце своје, и рече јој: бритва није никад прешла преко главе моје, јер сам назиреј Божји од утробе матере своје; да се обријем, оставила би ме снага моја и ослабио бих, и био бих као сваки човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'А Далида видећи да јој је отворио цијело срце своје, посла и позва кнезове Филистејске поручивши им: ходите сада, јер ми је отворио цијело срце своје.Тада дођоше кнезови Филистејски к њој и донесоше новце у рукама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'А она га успава на крилу својем, и дозва човјека те му обрија седам прамена косе с главе, и она га прва свлада кад га остави снага његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'И она рече: ето Филистеја на те, Самсоне! А он пробудив се од сна рече: изаћи ћу као и прије и отећу се. Јер не знадијаше да је Господ отступио од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Тада га ухватише Филистеји, и ископаше му очи, и одведоше га у Газу и оковаше га у двоје вериге мједене; и мељаше у тамници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'А коса на глави његовој поче расти као што је била кад га обријаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'И кнезови Филистејски скупише се да принесу велику жртву Дагону богу својему, и да се провеселе, па рекоше: предаде нам бог наш у руке наше Самсона непријатеља нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Такођер и народ видјевши га хваљаше бога својега говорећи: предаде нам бог наш у руке наше непријатеља нашега и затирача земље наше и који поби толике између нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'И кад се развесели срце њихово рекоше: зовите Самсона да нам игра. И дозваше Самсона из тамнице да им игра, и намјестише га међу два стуба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Тада Самсон рече момку који га држаше за руку: пусти ме, да опипам стубове на којима стоји кућа, да се наслоним на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'А кућа бијаше пуна људи и жена и сви кнезови Филистејски бијаху ондје; и на крову бијаше око три тисуће људи и жена, који гледаху како Самсон игра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Тада Самсон завапи ка Господу и рече: Господе, Господе! опомени ме се, молим те, и укријепи ме, молим те, само сада, о Боже! да се осветим једанпут Филистејима за оба ока своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'И загрли Самсон два стуба средња, на којима стајаше кућа, и наслони се на њих, на један десном а на други лијевом руком својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Па онда рече Самсон: нека умрем с Филистејима. И належе јако, и паде кућа на кнезове и на сав народ који бјеше у њој; и би мртвијех које поби умирући више него онијех које поби за живота својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'После дођоше браћа његова и сав дом оца његова, и узеше га, и вративши се погребоше га између Сараје и Естола у гробу Маноја оца његова. А он би судија Израиљу двадесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'А бијаше један човјек из горе Јефремове по имену Миха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Он рече матери својој: тисућа и сто сребрника, што су ти украдени, за које си клела и говорила преда мном, ево, то је сребро у мене, ја сам га узео. А мати му рече: Господ да те благослови, сине!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'А кад врати тисућу и сто сребрника матери својој, рече мати његова: то сам сребро посветила Господу из своје руке за тебе, сине мој, да се начини од њега лик резан и ливен; зато ти га сада дајем натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Али он опет даде сребро матери својој, а мати узе двјеста сребрника и даде златару, а он начини од њега лик резан и ливен, те бијаше у кући Мишиној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'И тај Миха имаше кућу за богове, и начини оплећак и ликове, и посвети једнога између синова својих да му буде свештеник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'У то вријеме не бјеше цара у Израиљу: сваки чињаше што му бијаше драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'А бјеше један младић из Витлејема Јудина, од породице Јудине, који бјеше Левит и ондје борављаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Он отиде из тога града, Витлејема Јудина, да се настани гдје може; и идући својим путем дође у гору Јефремову до куће Мишине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'А Миха му рече: откуда идеш? Одговори му Левит: из Витлејема Јудина, идем да се настаним гдје могу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'А Миха му рече: остани код мене, и буди ми отац и свештеник, а ја ћу ти дати десет сребрника на годину и двоје хаљине и храну. И отиде Левит к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'И Левиту би по вољи да остане код њега, и би му тај младић као да му је син.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'И Миха посвети Левита да му је свештеник тај младић, и оста у кући Мишиној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Тада рече Миха: сада знам да ће ми Господ учинити добро зато што имам Левита свештеника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'У то вријеме не бјеше цара у Израиљу, и у то вријеме племе Даново тражаше себи нашљедство гдје би наставало, јер му дотада не бјеше допало нашљедство међу племенима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Зато послаше синови Данови из породице своје пет људи између себе, храбре људе од Сараје и Естаола, да уходе земљу и добро размотре, и рекоше им: идите, размотрите земљу. И они отидоше у гору Јефремову у кућу Мишину и заноћише ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'И кад бијаху код куће Мишине, познаше глас онога младића Левита, и свративши се онамо рекоше му: ко те доведе овамо? и шта радиш ту? и шта ћеш ту?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'А он им рече: тако и тако учини ми Миха, и најми ме да му будем свештеник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'А они му рекоше: упитај Бога да знамо хоће ли нам бити срећан пут на који пођосмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'А свештеник им рече: идите с миром; по вољи је Господу пут којим идете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'И тако пошавши онијех пет људи дођоше у Лаис, и видјеше тамошњи народ гдје живи без страха по обичају Сидонском, мирно и без страха, и да нема никога у земљи ко би им чимгод досађивао или отимао власт, и да су далеко од Сидоњана нити имају шта с ким.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Па кад се вратише к браћи својој у Сарају и Естаол, рекоше им браћа: што је?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'А они рекоше: устајте да идемо на њих; јер видесмо земљу, и врло је добра. И ви не марите? немојте се лијенити, него похитајте да узмете земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Кад дођете, доћи ћете к народу безбрижном и у земљу пространу; јер је предаде Бог у наше руке; то је мјесто гдје нема недостатака ни у чем што има на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Тада пођоше оданде из Сараје и Естаола шест стотина људи од породице Данове наоружанијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'И отишавши стадоше у око код Киријат-Јарима у Јуди; зато се прозва оно мјесто Махане-Дан до данас, и јест иза Киријат-Јарима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'А оданде пошавши у гору Јефремову дођоше у кућу Мишину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Тада проговорише петорица што бијаху ишли да уходе земљу Лаиску, и рекоше браћи својој: знате ли да у овијем кућама има оплећак и ликова, и лик резан и лик ливен? Сада дакле гледајте што ћете радити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'А они свративши се онамо уђоше у кућу гдје бјеше младић Левит, у кућу Мишину, и упиташе га за здравље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'А шест стотина људи наоружанијех од синова Дановијех стадоше пред вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'А пет људи што бјеху ишли да уходе земљу отишавши уђоше и узеше лик резан и оплећак и ликове и лик ливен; а свештеник стајаше на вратима са шест стотина људи наоружанијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'И они што уђоше у кућу Мишину кад узеше лик резани, оплећак, ликове и лик ливени, свештеник им рече: шта радите?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'А они му рекоше: мучи, метни руку на уста, па хајде с нама, и буди нам отац и свештеник. Што ти је боље, бити свештеник кући једнога човјека или бити свештеник племену и породици у Израиљу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'И свештеник се обрадова у срцу, и узе оплећак и ликове и лик резани, и уђе међу народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'И окренувши се пођоше пустивши дјецу и стоку и закладе напријед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'А кад бијаху далеко од куће Мишине, онда људи који живљаху у кућама близу куће Мишине скупише се и пођоше у потјеру за синовима Дановијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'И викаше за синовима Дановијем, а они обазревши се рекоше Миши: што ти је, те си скупио толике људе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'А он рече: узели сте моје богове које сам начинио, и свештеника, па отидосте. Шта још имам? па још кажете: што ти је?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'А синови Данови рекоше му: немој да ти се чује глас за нама, да не би ударили на вас људи гњевни, те ћеш изгубити душу своју и душу дома својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'И синови Данови отидоше својим путем, а Миха, видећи да су јачи од њега врати се и отиде кући својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'И они узевши што бјеше начинио Миха, и свештеника, којега имаше, дођоше у Лаис к народу мирном и безбрижном; па их исјекоше оштријем мачем, а град упалише огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'И не бјеше никога да их избави; јер бијаху далеко од Сидона и не имаху ништа ни с ким; а град бијаше у долини која је код Вет-Реова. Послије сазидаше град и населише се у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'И назваше град Дан по имену Дана оца својега, који се роди Израиљу; а прије се град зваше Лаис.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'И синови Данови намјестише себи онај лик резани; а Јонатан син Гирсона Манасијина и синови његови бијаху свештеници племену Данову докле се год не исели из земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'И намјештен им стајаше онај лик резани, који начини Миха, за све вријеме докле дом Божји бијаше у Силому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'И у то вријеме, кад не бјеше цара у Израиљу, бјеше један Левит који живљаше као дошљак крај горе Јефремове, и узе иночу из Витлејема Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'А иноча његова чињаше прељубу код њега, па отиде од њега кући оца својега у Витлејем Јудин, и оста ондје четири мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'А муж њезин уста и отиде за њом да јој лијепо говори и да је доведе натраг, имајући са собом момка својега, и два магарца; и она га уведе у кућу оца својега, и кад га видје отац њезин обрадова се доласку његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'И устави га таст његов, отац младичин, и оста код њега три дана, и ондје јеђаху и пијаху и ноћиваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'А четврти дан кад усташе рано, уста и он да иде; али отац младичин рече зету својему: поткријепи срце своје залогајем хљеба, па онда идите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'И тако сједоше и сједоше обојица заједно и напише се; па рече отац младичин мужу: хајде остани још ноћас, и буди весео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Али човјек уста да иде; али таст његов навали на њ, те опет ноћи ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Потом урани петога дана да иде; и рече му отац младичин: поткријепи срце своје. И једући заједно забавише се докле и дан наже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Тада уста човјек да иде, он и иноча му и момак; а таст његов, отац младичин, рече му: ето, дан је већ нагао, вече је, преноћите овдје; ето доцкан је, преноћи овдје, и буди весео, па сјутра ураните на пут, и иди к својему шатору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Али човјек не хтје ноћити; него уста и пође; и дође до Јевуса, а то је Јерусалим, и с њим два магарца натоварена и иноча његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'А кад бијаху близу Јевуса, дан бијаше нагао врло, па рече слуга господару својему: хајде брже да се свратимо у тај град Јевус, и ту да ноћимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'А господар му рече: нећемо свртати у туђ град, који није синова Израиљевијех, него ћемо ићи до Гаваје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Још рече момку својему: хајде брже да стигнемо у које од тијех мјеста и да ноћимо у Гаваји или у Рами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'И минуше онуда и отидоше; и сунце их зађе близу Гаваје Венијаминове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'И окретоше онамо да отиду и преноће у Гаваји, и кад уђе, сједе на улици градској; и не би никога да их прими у кућу да преноће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'И гле, један старац враћаше се с посла својега из поља увече, а бијаше из горе Јефремове и живљаше као дошљак у Гаваји; а људи онога мјеста бјеху синови Венијаминови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'И он подигав очи своје угледа онога човјека путника на улици градској; и рече му старац: куда идеш? и откуда идеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'А он му одговори: идемо до Витлејема Јудина до на крај горе Јефремове; оданде сам, па сам ишао до Витлејема Јудина, а сада идем к дому Господњему и нема никога да ме прими у кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'А имамо и сламе и пиће за магарце своје, и хљеба и вина за се и за слушкињу твоју и за момка који је са слугом твојим имамо свега доста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'А старац му рече: буди миран; што ти год недостаје, ја ћу се старати за то; само немој ноћити на улици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'И уведе га у своју кућу, и положи магарцима; потом опраше ноге, и једоше и пише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'А кад се развеселише, гле, људи онога града, безаконици, опколише кућу, и стадоше лупати у врата, и рекоше старцу, господару од куће, говорећи: изведи тога човјека што је ушао у твоју кућу, да га познамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'И изашав к њима онај човјек, господар од куће, рече им: не, браћо, не чините зла; кад је човјек ушао у моју кућу, не чините тога безумља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Ево кћи моја дјевојка и иноча његова, њих ћу вам извести, па њих осрамотите и чините с њима што вам је воља, само човјеку овому не чините тога безумља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Али га не хтјеше послушати они људи; тада онај човјек узе иночу своју и изведе је напоље к њима, и они је познаше, и злоставише је цијелу ноћ до зоре, и пустише је кад зора забијеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'И дошавши жена у зору паде код врата од куће онога човјека гдје бјеше господар њезин, и лежа докле се не расвану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'А господар њезин уста ујутру, и кад отвори врата и изађе да иде својим путем, а то жена иноча његова лежаше на вратима кућнијем, и руке јој на прагу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'И рече јој: устани да идемо. Али не би одговора; тада је метну на магарца, и уставши човјек пође у мјесто своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'И дошав кући својој узе мач, и узе иночу своју и исијече је с костима на дванаест комада и разасла у све крајеве Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'И ко год видје говораше: није се учинило нити се видјело тако што откад изидоше синови Израиљеви из Мисира до данас. Промислите о том и вијећајте и говорите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Тада изидоше сви синови Израиљеви, и сабра се сав народ једнодушно, од Дана до Вирсавеје и до земље Галадове, ка Господу у Миспу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'И главари свега народа, свијех племена Израиљевијех, дођоше на збор народа Божијега, четири стотине тисућа људи пјешака који махаху мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'А синови Венијаминови чуше да су синови Израиљеви отишли у Миспу. Синови Израиљеви рекоше: кажите како се догодило то зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'А Левит, муж убијене жене, одговори и рече: дођох с иночом својом у Гавају Венијаминову да преноћим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'А Гавајани усташе на ме, опколише ме у кући ноћу, и хтјеше ме убити; и иночу моју злоставише тако да умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Зато узев иночу своју исјекох је на комаде и разаслах је у све крајеве нашљедства Израиљева; јер учинише грдило и срамоту у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Ето, ви сте сви синови Израиљеви; промислите и вијећајте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'А сав народ уста једнодушно и рече: да не идемо ниједан к шатору својему, и ни један да се не враћа кући својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Него ово да учинимо Гаваји: да бацимо ждријеб за њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Да узмемо по десет људи од стотине по свијем племенима Израиљевијем, и по стотину од тисуће, и по тисућу од десет тисућа, да донесе храну народу, а он да иде да учини Гаваји Венијаминовој како је заслужила грдилом које је учинила Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'И скупи се сав народ Израиљев на онај град сложивши се једнодушно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Тада послаше племена Израиљева људе у све породице Венијаминове, и поручише им: какво се то зло учини међу вама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Сада дајте те безаконике што су у Гаваји, да их погубимо и извадимо зло из Израиља. Али не хтјеше синови Венијаминови послушати браће своје, синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Него се скупише синови Венијаминови из својих мјеста у Гавају да изиду да се бију са синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'И наброји се у то време синова Венијаминовијех из њиховијех градова двадесет и шест тисућа људи који махаху мачем осим становника Гавајских, којих бјеше на број седам стотина људи одабранијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'У свем том народу бјеше седам стотина људи одабранијех, који бјеху љеваци, и сваки гађаше каменом из праћке у длаку не промашујући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'А људи Израиљаца наброји се осим синова Венијаминовијех четири стотине тисућа људи који махаху мачем, самијех војника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'И уставши отидоше к дому Бога силнога, и упиташе Бога и рекоше синови Израиљеви: ко ће између нас ићи први у бој на синове Венијаминове? А Господ рече: Јуда нек иде први.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Потом уставши рано синови Израиљеви стадоше у око према Гаваји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'И изидоше синови Израиљеви у бој на синове Венијаминове, и уврсташе се синови Израиљеви да ударе на Гавају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'А синови Венијаминови изидоше из Гаваје, и поваљаше по земљи између Израиљаца у онај дан двадесет и двије тисуће људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Али се народ синова Израиљевијех ослободи, те се опет уврсташе на истом мјесту гдје се бијаху уврстали првога дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Јер синови Израиљеви отидоше те плакаше пред Господом до вечера, и упиташе Господа говорећи: хоћемо ли опет изаћи у бој на синове Венијамина брата својега? А Господ им рече: изидите на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'И изидоше синови Израиљеви на синове Венијаминове други дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'И синови Венијаминови изидоше пред њих из Гаваје други дан; и поваљаше по земљи између синова Израиљевијех опет осамнаест тисућа људи, који сви махаху мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Тада сви синови Израиљеви и сав народ изидоше и дођоше к дому Бога силнога, и плакаше и стајаше ондје пред Господом, и постише се онај дан до вечера, и принесоше жртве паљенице и жртве захвалне пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Па упиташе синови Израиљеви Господа; јер ондје бијаше ковчег завјета Божијега у оно вријеме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'И Финес син Елеазара сина Аронова стајаше пред њим у оно вријеме. И рекоше: хоћемо ли опет изаћи у бој на синове Венијаминове брата својега или ћемо се оканити? А Господ им рече: изидите, јер ћу их сјутра предати вама у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Тада намјести Израиљ засједе око Гаваје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'И синови Израиљеви изидоше трећи дан на синове Венијаминове, и уврсташе се према Гаваји као првом и другом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'А синови Венијаминови изашавши пред народ одвојише се од града, и стадоше бити и сјећи народ као првом и другом по путовима, од којих један иде к дому Бога силнога а други у Гавају, и по пољу, и убише до тридесет људи из Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'И рекоше синови Венијаминови: падају пред нама као прије. А синови Израиљеви рекоше: да бјежимо да их отргнемо од града на путове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Тада сви синови Израиљеви кретоше се са својега мјеста и уврсташе се у Вал-Тамару; и засједе Израиљеве искочише из мјеста својега, из лука Гавајских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'И дође на Гавају десет тисућа људи изабранијех из свега Израиља, и бој поста жешћи, а они не опазише да ће их зло задесити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'И Господ поби Венијамина пред Израиљем, и синови Израиљеви погубише онај дан од синова Венијаминовијех двадесет и пет тисућа и сто људи, који сви мачем махаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'И синови Венијаминови видјеше да су надбијени: јер синови Израиљеви узмакоше испред синова Венијаминовијех уздајући се у засједе које бијаху намјестили код Гаваје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'А они што бијаху у засједи брже навалише у Гавају, и ушавши исјекоше све по граду оштријем мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'А бијаху синови Израиљеви уговорили с онима у засједи да за знак запале ватру да се дигне велик дим из града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Тако синови Израиљеви стадоше бјежати из боја, а синови Венијаминови почеше убијати, и исјекоше до тридесет људи између синова Израиљевијех говорећи: доиста падају пред нама као у пређашњем боју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Али кад се пламен и дим као стуб диже из града, обазреше се синови Венијаминови, и гле, огањ се из града дизаше до неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Тада се вратише синови Израиљеви, а синови Венијаминови сметоше се видећи да их је зло задесило;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'И побјегоше испред синова Израиљевијех к пустињи; али их војска гоњаше, и који из градова излажаху, бише их међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Тако опколише синове Венијаминове, гонише их, тлачише их од Менује до Гаваје к истоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'И погибе синова Венијаминовијех осамнаест тисућа људи, самијех јунака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'А оних што се окретоше и побјегоше у пустињу к стијени Римону, напабирчише их по путовима пет тисућа људи, и тјераше их до Гидома и побише их двије тисуће људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'И тако свега погибе онај дан синова Венијаминовијех двадесет и пет тисућа људи који махаху мачем, све самијех јунака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'И бјеше шест стотина људи који се окретоше и утекоше у пустињу к стијени Римону, и осташе на стијени Римону четири мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Потом синови Израиљеви вративши се к синовима Венијаминовијем исјекоше оштријем мачем и људе по градовима и стоку и што се год нађе; и све градове који осташе попалише огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'А синови Израиљеви бијаху се заклели у Миспи рекавши: ниједан између нас да не да кћери своје за жену сину Венијаминову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Зато отиде народ к дому Божијему, и осташе ондје до вечера пред Богом, и подигавши глас свој плакаше врло,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'И рекоше: зашто се, Господе Боже Израиљев, догоди ово у Израиљу, данас да нестане једнога племена из Израиља?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'И сјутрадан урани народ, и начини ондје олтар, и принесоше жртве паљенице и жртве захвалне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Тада рекоше синови Израиљеви: има ли ко да није дошао на збор из свијех племена Израиљевијех ка Господу? Јер се бијаху тешко заклели за онога ко не дође у Миспу ка Господу рекавши: да се погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Јер се синовима Израиљевијем сажали за Венијамином братом њиховијем, и рекоше: данас се истријеби једно племе из Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Шта ћемо чинити с онима што су остали да би имали жене, кад се заклесмо Господом да им не дамо кћери својих за жене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Па рекоше: има ли ко из племена Израиљевијех да није дошао у Миспу ка Господу? и гле, не беше дошао на војску, на збор, нико из Јависа Галадова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Јер кад се народ преброји, гле, не бјеше ондје ниједнога од онијех који живе у Јавису Галадову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Зато посла збор онамо дванаест тисућа храбријех људи, и заповједи им говорећи: идите и побијте становнике у Јавису Галадову оштријем мачем и жене и дјецу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Ово ћете дакле учинити: све мушкиње и све женскиње што је познало човјека побијте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'И нађоше међу становницима Јависа Галадова четири стотине дјевојака, које не бјеху познале човјека, и доведоше их у око у Силом, који је у земљи Хананској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Тада посла сав збор, те говорише синовима Венијаминовијем који бјеху у стијени Римону, и објавише им мир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Тако се вратише синови Венијаминови у то вријеме, и дадоше им жене које оставише у животу између жена из Јависа Галадова; али их не бјеше доста за њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'А народу бјеше жао Венијамина што Господ окрњи племена Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Па рекоше старјешине од збора: шта ћемо чинити с овима што су остали да би имали жене? јер су изгинуле жене у племену Венијаминову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Потом рекоше: нашљедство Венијаминово припада онима што су остали, да се не би затрло племе из Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'А ми им не можемо дати жена између кћери својих; јер су се заклели синови Израиљеви рекавши: да је проклет ко да жену синовима Венијаминовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Потом рекоше: ево, годишњи је празник Господњи у Силому, који је са сјевера Ветиљу, к истоку, на путу који иде од Ветиља у Сихем, и с југа Левони.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'И заповједише синовима Венијаминовијем говорећи: идите, и засједите по виноградима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'И пазите: па кад изиду кћери Силомске да играју, изидите из винограда и отмите сваки себи жену између кћери Силомских; и идите у земљу Венијаминову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'А кад дођу оци њихови или браћа њихова к нама да се суде, ми ћемо им казати: смилујте им се нас ради, јер у овом рату нијесмо заробили жене за свакога њих; а ви им нијесте дали, и тако нећете бити криви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Тада синови Венијаминови учинише тако, и доведоше жене према броју свом између играчица које отеше, и отишавши вратише се на нашљедство своје, и сазидаше опет градове и населише се у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'И тако разидоше се синови Израиљеви оданде у оно време сваки у своје племе и у породицу своју, и отидоше оданде сваки на своје нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'У оно вријеме не бјеше цара у Израиљу; сваки чињаше што му бјеше драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'А у оно вријеме кад суђаху судије би глад у земљи; и један човјек из Витлејема Јудина отиде да живи као дошљак у земљи Моавској са женом својом и са два сина своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'А име тому човјеку бјеше Елимелех, а жени му име Нојемина, а имена двојице синова његовијех Малон и Хелеон; и бијаху Ефраћани, из Витлејема Јудина; и дођоше у земљу Моавску и настанише се ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Потом умрије Елимелех муж Нојеминин и она оста са два сина своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Они се оженише Моавкама; једној бјеше име Орфа а другој Рута; и ондје стајаху до десет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Потом умријеше обојица, Малон и Хелеон; и жена оста без два сина своја и без мужа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Тада се она подиже са снахама својима да се врати из земље Моавске, јер чу у земљи Моавској да је Господ походио народ свој давши им хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'И изиде из мјеста гдје бијаше, и обје снахе њезине с њом; пођоше путем да се врате у земљу Јудину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Тада рече Нојемина објема снахама својима: идите, вратите се свака у дом матере своје; Господ нека вам учини милост као што ви учинисте умрлима и мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Да вам да Господ да нађете починак свака у дому мужа својега. И пољуби их; а оне повикавши заплакаше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'И рекоше јој: не, него ћемо се с тобом вратити у твој народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'А Нојемина им рече: идите натраг, кћери моје; што бисте ишле са мном? зар ћу још имати синова у утроби својој да вам буду мужеви?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Вратите се, кћери моје, идите; јер сам остарјела и нијесам за удају. А и да кажем да се надам и да се још ноћас удам, и да родим синове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'Зар ћете их ви чекати док одрасту? зар ћете тога ради стајати неудате? Немојте, кћери моје; јер су моји јади већи од ваших, јер се рука Господња подигла на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Тада оне подигавши глас свој плакаше опет; и Орфа пољуби свекрву своју; а Рута оста код ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'А она јој рече: ето, јетрва се твоја вратила народу својему и к боговима својим; врати се и ти за јетрвом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Али Рута рече: немој ме наговарати да те оставим и од тебе отидем; јер куда год ти идеш, идем и ја; и гдје се год ти настаниш, настанићу се и ја; твој је народ мој народ, и твој је Бог мој Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Гдје ти умријеш, умријећу и ја, и ондје ћу бити погребена. То нека ми учини Господ и то нека ми дода, смрт ће ме само раставити с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'А она кад видје да је тврдо наумила ићи с њом, преста је одвраћати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Тако идоше обје док не дођоше у Витлејем; а кад дођоше у Витлејем, сав град узавре њих ради, и говораху: је ли то Нојемина?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'А она им говораше: не зовите ме више Нојемина, него ме зовите Мара, јер ми велике јаде зададе свемогући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Обилна сам отишла, а празну ме врати Господ. Зашто ме зовете Нојемина, кад ме Господ обори и свемогући ме уцвијели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Тако дође натраг Нојемина и с њом Рута Моавка, снаха њезина, вративши се из земље Моавске; а дођоше у Витлејем о почетку јечмене жетве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'А бијаше један човјек, род мужу Нојеминину, човјек богат од породице Елимелехове, којему име бијаше Воз.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'И Рута Моавка рече Нојемини: да идем у поље да пабирчим класје за онијем пред ким нађем милост. А она јој рече: иди, кћери моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'И она отиде, и дошавши стаде пабирчити по њиви за жетеоцима: и догоди се, те дође на њиву која припадаше Возу, који бијаше од породице Елимелехове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'И гле, дође Воз из Витлејема, а рече жетеоцима: Господ да је с вама! И они му рекоше: да те благослови Господ!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Тада рече Воз слузи својему који бијаше над жетеоцима: чија је оно младица?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'А слуга који бјеше над жетеоцима одговори му: Моавка је младица која се вратила с Нојемином из земље Моавске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'И рече: да пабирчим, да купим класје између снопова за жетеоцима. И дошавши бави се од јутра досада; само је мало била код куће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Тада Воз рече Рути: чујеш, кћери моја; немој ићи на другу њиву да пабирчиш, нити одлази одавде, него се држи мојих дјевојака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Пази на којој њиви они жању, па иди за њима; јер сам заповједио момцима својим да те нико не дира; а кад ожедниш, иди к судовима и пиј што моје слуге захитају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Тада она паде ничице и поклони се до земље, и рече му: како нађох милост пред тобом, да ме погледаш, кад сам туђинка?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'А Воз одговори и рече јој: чуо сам ја све што си чинила свекрви својој по смрти мужа својега, и како си оставила оца својега и матер своју и постојбину своју, па си дошла к народу којега нијеси знала прије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Господ да ти плати за дјело твоје, и да ти плата буде потпуна од Господа Бога Израиљева, кад си дошла да се под крилима његовијем склониш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'А она рече: нађох милост пред тобом, господару, јер си ме утјешио и милостиво проговорио слушкињи својој, ако и нијесам као једна од твојих слушкиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'А Воз јој рече: кад буде вријеме јести, дођи овамо и једи хљеба и умочи залогај свој у оцат. И она сједе покрај жетелаца, и он јој пружи прженијех зрна, и она једе и насити се, и претече јој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Потом уста да пабирчи. А Воз заповједи момцима својим говорећи: нека пабирчи и међу сноповима, немојте да је застидите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Него још навлаш испуштајте руковети и остављајте јој нека купи, и не корите је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'И она пабирчи на њиви до вечера, и оврше што напабирчи, и дође око ефе јечма.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'И узевши отиде у град, и видје свекрва њезина шта је напабирчила; а она извади и даде јој и оно што је претекло пошто се наситила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'И рече јој свекрва: гдје си пабирчила данас? и гдје си радила? Да је благословен који те је погледао! А она каза свекрви својој код кога је радила говорећи: име је човјеку код којега сам данас радила Воз.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'А Нојемина рече снаси својој: Господ да га благослови, кад није укратио милости своје к живима и к мртвима. И рече јој Нојемина: тај је човјек нама род, и један од осветника наших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'А Рута Моавка рече: још ми је рекао: држи се моје чељади докле не пожању све моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'А Нојемина рече Рути снаси својој: добро је, кћери моја, да идеш с његовијем дјевојкама, да те не би дирали на другој њиви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'И тако се држаше дјевојака Возовијех пабирчећи докле се не сврши жетва јечмена и жетва пшенична; и живљаше код свекрве своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Потом рече јој Нојемина свекрва њезина: кћери моја, не треба ли да ти потражим починка, да би ти добро било?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Ево, није ли нам род Воз, код којега си била са дјевојкама његовијем? ево, он ће ову ноћ вијати јечам на гумну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Умиј се дакле, и намажи се, и обуци хаљине своје на се, па иди на гумно; али да не дозна за те човјек докле не једе и не напије се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Па кад легне, запамти мјесто гдје легне, па онда отиди и дигни покривач с ногу његовијех, те лези ондје; а он ће ти казати шта ћеш радити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'А Рута јој рече: што ми год кажеш, учинићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'И отиде на гумно и учини све што јој заповједи свекрва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'А Воз једавши и пивши и провеселивши се отиде те леже код стога; а она дође полако, подиже покривач с ногу његовијех и леже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'А кад би око поноћи трже се човјек и обрну се, а гле, жена лежаше код ногу његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'И он јој рече: ко си? Одговори: ја сам Рута слушкиња твоја; рашири крило своје на слушкињу своју, јер си ми осветник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'А он рече: Господ да те благослови, кћери моја; ова потоња милост коју ми показујеш већа је од прве, што нијеси тражила младића, ни сиромашна ни богата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Зато сада, кћери моја, не бој се; што год речеш учинићу ти; јер зна цијело мјесто народа мојега да си поштена жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Јест истина, ја сам ти осветник; али има јоште ближи од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Преноћи овдје; па сјутра ако те хтједбуде узети, добро, нека узме; ако ли не хтједбуде узети, ја ћу те узети, тако жив био Господ! Спавај до јутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'И она спава код ногу његовијех до јутра; потом уста док још не могаше човјек човјека распознати, јер Воз рече: да се не дозна да је жена долазила на гумно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'И рече: дај огртач који имаш на себи; и држи га. И она га подржа, а он јој измјери шест мјерица јечма, и напрти јој и она отиде у град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'И дође свекрви својој, која јој рече: шта би кћери моја? А она јој каза све што јој учини онај човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'И рече: овијех шест мјерица јечма даде ми, јер ми рече: немој се вратити празна к свекрви својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'А она јој рече: почекај, кћери моја, док дознаш како ће изаћи; јер онај човјек неће се смирити док не сврши ствар данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'А Воз изиде на врата градска, и сједе ондје. И гле, наиђе онај осветник, за којега Воз говораше, и рече му Воз: ходи овамо, сједи овдје. И он дође и сједе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Потом узе Воз десет људи између старјешина градских и рече: посједајте овдје. И посједаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Тада рече оному осветнику: њиву која је била брата нашега Елимелеха продала је Нојемина, која се вратила из земље Моавске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Зато рекох: да јавим теби, и кажем ти: узми њиву пред овима што сједе овдје и пред старјешинама народа мојега; ако ћеш откупити, откупи; ако ли нећеш откупити, кажи ми да знам; јер осим тебе нема другога који би откупио, а послије тебе идем ја. А он рече: ја ћу откупити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'А Воз рече: у који дан узмеш њиву из руке Нојеминине, треба да узмеш и Руту Моавку жену умрлога, да подигнеш име умрлому у нашљедству његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Тада рече онај осветник: не могу откупити, да не распем својега нашљедства; откупи ти што би требало да ја откупим, јер ја не могу откупити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'А бијаше од старине обичај у Израиљу о откупљивању и промијењивању, да би свака ствар била тврда, да један изује обућу своју и да другому, и то бијаше сведоџба у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Кад дакле онај осветник рече Возу: узми ти, изу обућу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'А Воз рече старјешинама и свему народу: ви сте свједоци данас да сам откупио из руке Нојеминине што је год било Елимелехово и што је год било Хелеоново и Малоново;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'И да сам узео за жену Руту Моавку жену Малонову да подигнем име умрлому у нашљедству његову, да не би погинуло име умрлому међу браћом његовом и у мјесту његову; ви сте свједоци данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'И сав народ који бијаше на вратима градским и старјешине рекоше: свједоци смо; да да Господ да жена која долази у дом твој буде као Рахиља и Лија, које обје сазидаше дом Израиљев; богати су у Ефрати, и прослави име своје у Витлејему!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'И од сјемена које ти Господ да од те жене, да постане дом твој као дом Фареса којега роди Тамара Јуди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'И тако узе Воз Руту и би му жена, и он леже с њом, и Господ јој даде те затрудње, и роди сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'И рекоше жене Нојемини: да је благословен Господ који те није оставио данас без осветника, да се име његово слави у Израиљу!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Он ће ти утјешити душу и биће потпора старости твојој, јер га роди снаха твоја која те љуби и која ти је боља него седам синова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'И узе Нојемина дијете, и метну га на крило своје, и бјеше му дадиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'И сусједе надјенуше му име говорећи: роди се син Нојемини, и прозваше га Овид. Он би отац Јесеја оца Давидова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'А ово је племе Фаресово: Фарес роди Есрома;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'А Есром роди Арама; а Арам роди Аминадава;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'А Аминадов роди Насона; а Насон роди Салмона;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'А Салмон роди Воза; а Воз роди Овида;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'А Овид роди Јесеја; а Јесеј роди Давида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Бијаше један човјек из Раматајим-Софима, из горе Јефремове, којему име бјеше Елкана син Јероама, сина Елива, сина Това, сина Суфова, Ефраћанин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'И имаше двије жене, једној бјеше име Ана а другој Фенина; и Фенина имаше дјеце, а Ана немаше дјеце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'И иђаше тај човјек сваке године из својега града да се поклони и принесе жртву Господу над војскама у Силом; а ондје бијаху два сина Илијева, Офније и Финес, свештеници Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'И један дан кад Елкана принесе жртву, даде Фенини жени својој и свијем синовима њезинијем и кћерима њезинијем по дио;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Ани пак даде два дијела, јер љубљаше Ану, а њој Господ бјеше затворио материцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'И противница је њезина врло цвијељаше пркосећи јој што јој Господ бјеше затворио материцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Тако чињаше Елкана сваке године, и Ана хођаше у дом Господњи, а она је цвијељаше, те плакаше и не јеђаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'А Елкана муж њезин рече јој једном: Ана, зашто плачеш? и зашто не једеш? и зашто је срце твоје невесело? Нијесам ли ти ја бољи него десет синова?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'А Ана уста, пошто једоше и пише у Силому; а Илије свештеник сјеђаше на столици на прагу дома Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'И она тужна у срцу помоли се Господу плачући много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'И завјетова се говорећи: Господе над војскама! ако погледаш на муку слушкиње своје, и опоменеш ме се, и не заборавиш слушкиње своје, него даш слушкињи својој мушко чедо, ја ћу га дати Господу докле је год жив, и бритва неће пријећи преко главе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'И кад се она дуго мољаше пред Господом, Илије мотраше на уста њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Али Ана говораше у срцу својем, уста јој се само мицаху а глас јој се не чујаше; стога Илије помисли да је пијана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Па јој рече Илије: докле ћеш бити пијана? отријезни се од вина својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Али Ана одговори и рече: нијесам пијана, господару, него сам жена тужна у срцу; нијесам пила вина ни силовита пића; него излијевам душу своју пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Немој једначити слушкиње своје с неваљалом женом; јер сам од велике туге и жалости своје говорила досад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Тада одговори Илије и рече: иди с миром; а Бог Израиљев да ти испуни молбу, за што си га молила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'А она рече: нека нађе слушкиња твоја милост пред тобом! Тада отиде жена својим путем, и једе, и лице јој не бјеше више као прије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'И сјутрадан уранише, и поклонише се Господу, и вратише се и дођоше кући својој у Рамат. И Елкана позна Ану жену своју, и Господ се опомену ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'И кад би вријеме пошто Ана затрудње роди сина, и надје му име Самуило, јер, рече, испросих га у Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Потом пође онај човјек Елкана са свијем домом својим да принесе Господу годишњу жртву и завјет свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Али Ана не пође, јер рече мужу својему: докле одојим дијете, онда ћу га одвести да изиде пред Господа и остане ондје до вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'И рече јој Елкана муж њезин: чини како ти драго; остани докле год не одојиш; само да хоће Господ испунити ријеч своју. И тако жена оста; и дојаше сина својега докле га не одоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'А кад га одоји, одведе га са собом узевши три телета и ефу брашна и мијех вина, и уведе га у дом Господњи у Силому; а дијете бијаше још мало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'И заклаше теле и доведоше дете к Илију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'И она рече: чуј Господару, како је жива душа твоја, господару, ја сам она жена која је стајала овдје код тебе молећи се Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Молих се за ово дијете, и испуни ми Господ молбу моју, зашто сам га молила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Зато и ја дајем њега Господу, докле је год жив, да је дат Господу. И поклонише се ондје Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'И Ана се помоли и рече: развесели се срце моје у Господу; подиже се рог мој у Господу; отворише се уста моја на непријатеље моје, јер сам радосна ради спасења твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Нема светога као што је Господ; јер нема другога осим тебе; и нема стијене као што је Бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Не говорите више поносито, и нека не излазе из уста ваших ријечи охоле; јер је Господ Бог који све зна, и он удешава намјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Лук јунацима сломи се, и изнемогли опасаше се снагом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Који бијаху сити, наимају се за хљеб; а који бијаху гладни, нијесу више; и нероткиња роди седморо, а која имаше дјеце, изнеможе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Господ убија, и оживљује; спушта у гроб, и извлачи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Господ сиромаши, и богати; понижује, и узвишује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Сиромаха подиже из праха, и из буњишта узвишује убогога да га посади с кнезовима, и даје им да наслиједе пријесто славе; јер су Господњи темељи земаљски, и на њима је основао васиљену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Сачуваће ноге милијех својих, а безбожници ће умукнути у мраку; јер својом снагом неће човјек надјачати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Који се супроте Господу, сатрће се; на њих ће загрмјети с неба; Господ ће судити крајевима земаљским, и даће снагу цару својему, и узвисиће рог помазанику својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Потом отиде Елкана у Рамат кући својој, а дијете служаше Господу пред Илијем свештеником.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'А синови Илијеви бијаху неваљали, и не знадијаху за Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Јер у тијех свештеника бјеше обичај према народу: кад ко приношаше жртву, долажаше момак свештеников док се кухаше месо с виљушкама трокраким у руци,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'И забадаше у суд, или у котао, или у таву, или у лонац, и што се год набоде на виљушке узимаше свештеник. Тако чињаху свему Израиљу који долажаше у Силом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Тако и прије него би запалили сало, дошао би момак свештеников, те би рекао човјеку који приношаше жртву: дај месо да испечем свештенику, јер ти нећу примити меса кухана, него сирово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Ако би му тада човјек одговорио: нека се прво запали сало, па онда узми што ти год душа жели; он би рекао: не, него дај сада, ако ли не даш, узећу силом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'И гријех онијех младића бијаше врло велик пред Господом, јер људи не мараху за принос Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'А Самуило служаше пред Господом још дијете у оплећку ланеном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'А мати му начини мали плашт и донесе му, и тако чињаше сваке године долазећи с мужем својим да принесе жртву годишњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'А Илије благослови Елкану и жену његову говорећи: Господ да ти да порода од те жене за овога којега је дала Господу! И отидоше у своје мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'И Господ походи Ану, и она затрудње и роди три сина и двије кћери. А дијете Самуило растијаше пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'А Илије бијаше врло стар, и чу све што чињаху синови његови свему Израиљу, и како спаваху са женама које долажаху гомилама на врата шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'И говораше им: зашто то радите? јер чујем зле ријечи о вама од свега народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Немојте, дјецо моја; јер није добро што чујем; отпађујете народ Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Кад човјек згријеши човјеку, судиће му судија; али кад ко згријеши Господу, ко ће молити за њ? Али не послушаше оца својега, јер Господ шћаше да их убије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'А дијете Самуило растијаше и бијаше мио Господу и људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Тада дође човјек Божји к Илију, и рече му: овако вели Господ: не јавих ли се дому оца твојега, кад бијаху у Мисиру у кући Фараоновој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'И изабрах га између свијех племена Израиљевијех себи за свештеника да приноси жртве на олтару мојем и да кади кадом и носи оплећак преда мном, и дадох дому оца твојега све жртве огњене синова Израиљевијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Зашто газите жртву моју и принос мој, које сам заповједио да се приносе у шатору? и пазиш синове своје већма него мене, да се гојите првинама свијех приноса Израиља народа мојега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Зато Господ Бог Израиљев каже: рекао сам доиста: дом твој и дом оца твојега служиће преда мном до вијека; али каже Господ: неће бити тако, јер оне ћу поштовати који мене поштују, а који мене презиру, биће презрени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Гле, иду дани кад ћу одсјећи теби руку и руку дому оца твојега, да не буде старца у дому твојем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'И видјећеш невољу у шатору мјесто свега добра што је Господ чинио Израиљу; неће бити старца у дому твојем довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'А кога од твојих не истријебим испред олтара својега, онај ће остати да ти чиле очи и да ти се цвијели душа; и сав подмладак дома твојега умираће у најбољим годинама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'И ово да ти је знак што ће доћи на оба сина твоја, на Офнија и Финеса: у један дан погинуће обојица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'А себи ћу подигнути свештеника вјерна, он ће радити по срцу мојему и по души мојој; и сазидаћу му тврд дом, и он ће ходити пред помазаником мојим вазда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'И ко остане од дома твојега, доћи ће да му се поклони за сребрн новац и за комад хљеба, и говориће: прими ме у каку службу свештеничку да имам комад хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'А дијете Самуило служаше Господу пред Илијем; и ријеч Господња бјеше ријетка у оно вријеме, и не јављаху се утваре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Једном у то вријеме Илије лежаше на свом мјесту; а очи му почињаху тамњети те не могаше видјети;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'И Самуило лежаше у дому Господњем гдје бијаше ковчег Божији, и жишци Господњи још не бјеху погашени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'И викну Господ Самуила, а он рече: ево ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'И притрча к Илију, и рече му: ево ме, што си ме звао? А он рече: нијесам те звао, иди лези. И он отиде и леже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'А Господ опет викну Самуила, и Самуило уста, и отиде к Илију, и рече: ево ме, што си ме звао? А он рече: нијесам те звао, сине; иди лези.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'А Самуило још не познаваше Господа, и још му не бјеше јављена ријеч Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Тада опет викну Господ Самуила трећи пут, и он уста и отиде к Илију, и рече: ево ме, што си ме звао? Тада разумје Илије да Господ зове дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'И рече Илије Самуилу: иди лези; а ако те зовне, а ти реци: говори Господе, чује слуга твој. И Самуило отиде, и леже на своје мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'А Господ дође и стаде; и зовну као прије: Самуило! Самуило! А Самуило рече: говори, чује слуга твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'И рече Господ Самуилу: ево учинићу нешто у Израиљу да ће зујати оба уха свакоме ко чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'У тај дан ћу учинити Илију све што сам говорио за кућу његову, од почетка до краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Јер сам му јавио да ћу судити дому његову довијека за неваљалство, за које је знао да њим навлаче на се проклетство синови његови, па им није забранио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Зато се заклех дому Илијеву да се неће очистити неваљалство дома Илијева никаквом жртвом ни приносом довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'И Самуило спава до јутра, па отвори врата дома Господњега. Али се бојаше Самуило казати Илију за утвару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'А Илије зовну Самуила и рече: Самуило, сине! А он рече: ево ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'А он рече: какве су ријечи што ти је казао? немој затајити од мене; тако ти учинио Бог и тако ти додао, ако затајиш од мене што год ти је казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'И Самуило му каза све, и ништа не затаји од њега. А он рече: Господ је, нека чини оно што му је воља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'А Самуило растијаше, и Господ бијаше с њим, и не пусти да падне на земљу ниједна ријеч његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'И сав Израиљ од Дана до Вирсавеје позна да је Самуило вјеран пророк Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'И Господ се стаде опет јављати у Силому, јер се Господ јављаше Самуилу у Силому ријечју Господњом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'И што рече Самуило, зби се свему Израиљу. Јер Израиљ изиде на војску на Филистеје, и стадоше у око код Евен-Езера, а Филистеји стадоше у око у Афеку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'А Филистеји се уврсташе према Израиљу, и кад се отвори бој, разбише Филистеји Израиља, и изгибе их у боју у пољу око четири тисуће људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'И кад народ дође у око, рекоше старјешине Израиљеве: зашто нас данас разби Господ пред Филистејима? да донесемо из Силома ковчег завјета Господњега, да буде међу нама и избави нас из руку непријатеља наших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'И народ посла у Силом да донесу оданде ковчег завјета Господа над војскама, који сједи на херувимима; а бијаху ондје код ковчега завјета Господњега два сина Илијева, Офније и Финес.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'А кад дође ковчег завјета Господњега у око, повика сав Израиљ од радости да земља зајеча.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'А Филистеји чувши веселу вику рекоше: каква је то вика весела у околу Јеврејском? И разумјеше да је дошао ковчег Господњи у око њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'И уплашише се Филистеји кад рекоше: Бог је дошао у око. И говораху: тешко нама! јер то није бивало прије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Тешко нама! ко ће нас избавити из руку тијех силнијех богова? то су богови што побише Мисирце у пустињи свакојаким мукама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Охрабрите се, и будите људи, о Филистеји! да не служите Јеврејима као што су они вама служили; будите људи и удрите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'И Филистеји ударише, и Израиљци се опет разбише и побјегоше к шаторима својим; и бој бјеше врло велик, јер паде из Израиља тридесет тисућа пјешака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'И ковчег Божји би отет, и два сина Илијева Офније и Финес погибоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'А један између синова Венијаминових побјеже из боја, и дође у Силом исти дан раздртијех хаљина и главе посуте прахом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'И кад дође, гле, Илије сјеђаше на столици украј пута погледајући; јер срце његово бијаше у страху за ковчег Божји. И дошав онај човјек у град каза гласе, и стаде вика свега града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'А Илије чувши вику рече: каква је то врева? И човјек брже дотрча да јави Илију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'А Илију бијаше деведесет и осам година, и очи му бијаху потамњеле, те не могаше видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'И рече човјек Илију: ја идем из боја, утекох данас из боја. А он рече: шта би, сине?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'А гласник одговарајући рече: побјеже Израиљ испред Филистеја, и изгибе много народа, и оба сина твоја погибоше, Офније и Финес, и ковчег Божји отет је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'А кад спомену ковчег Божји, паде Илије са столице наузнако код врата и сломи врат и умрије, јер бијаше човјек стар и тежак. Он би судија Израиљу четрдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'А снаха његова, жена Финесова, бијаше трудна и на том доба, па чувши глас да је ковчег Божји отет и да јој је погинуо свекар и муж, сави се и породи, јер јој дођоше болови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'И кад умираше, рекоше јој које стајаху код ње: не бој се, родила си сина. Али она не одговори, нити хајаше за то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'Него дјетету надје име Ихавод говорећи: отиде слава од Израиља; јер ковчег Божји би отет, и свекар јој и муж погибоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Зато рече: отиде слава од Израиља; јер би отет ковчег Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'А Филистеји узеше ковчег Божји, и однесоше из Евен-Езера у Азот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'И узевши Филистеји ковчег Божји унесоше га у дом Дагонов, и намјестише га до Дагона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'А сјутрадан кад усташе Азоћани рано, а то Дагон лежаше ничице на земљи пред ковчегом Господњим; и они узеше Дагона и метнуше га опет на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'А кад сјутрадан рано усташе, гле, опет Дагон лежаше ничице на земљи пред ковчегом Господњим, а глава Дагону и обје руке отсјечене бијаху на прагу; само труп од Дагона бјеше остао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Зато свештеници Дагонови и који год улазе у дом Дагонов не стају на праг Дагонов у Азоту до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Тада отежа рука Господња Азоћанима, и мораше их и удараше их шуљевима у Азоту и међама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'А кад Азоћани видјеше шта је, рекоше да не стоји код нас ковчег Бога Израиљева; јер је рука његова тешка над нама и над Дагоном богом нашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'И послаше, те сабраше к себи све кнезове Филистејске, и рекоше им: што ћемо чинити с ковчегом Бога Израиљева? А они рекоше: да се пренесе у Гат ковчег Бога Израиљева. И пренесоше ковчег Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'А кад га пренесоше, би рука Господња на граду с муком врло великом, и стаде бити грађане од малога до великога, и дођоше на њих тајни шуљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Зато послаше ковчег Божји у Акарон; а кад дође ковчег Божји у Акарон, повикаше Акароњани говорећи: донесоше к нама ковчег Бога Израиљева да помори нас и наш народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Зато послаше, те сабраше све кнезове Филистејске, и рекоше: пошљите ковчег Бога Израиљева нека се врати на своје мјесто, да не помори нас и народа нашега. Јер бијаше смртан страх по цијелом граду, и врло тешка бијаше рука Господња ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Јер људи који остајаху живи боловаху од шуљева тако да се вика у граду подизаше до неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'И бијаше ковчег Господњи у земљи Филистејској седам мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Тада дозваше Филистеји свештенике и враче, па им рекоше: шта ћемо чинити с ковчегом Господњим? научите нас како ћемо га послати натраг на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'А они рекоше: ако ћете натраг послати ковчег Бога Израиљева, не шаљите га празна, него уза њ подајте принос за гријех; тада ћете оздравити и дознаћете зашто се рука његова није одмакла од вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'А они рекоше: какав ћемо му дати принос за гријех? А они рекоше: према броју кнежевина Филистејских пет златнијех шуљева и пет златнијех мишева; јер је зло једнако на свјема вама и на кнезовима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Начините дакле слике од својих шуљева и слике од мишева који кваре земљу, и подајте славу Богу Израиљеву. Може бити да ће улакшати руку своју над вама и над боговима вашим и над земљом вашом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'И зашто бисте били упорна срца као што бијаху упорна срца Мисирци и Фараон? и пошто учини чудеса на њима, еда ли их тада не пустише, те отидоше?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Зато начините једна кола нова, и узмите двије краве дојилице, на којима још није био јарам, па упрегните краве у кола, а телад њихову одведите од њих кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Па узмите ковчег Господњи и метните га на кола; а закладе златне што ћете му дати за гријех метните у ковчежић покрај њега, и пустите га нека иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'И гледајте: ако пође путем к међи својој у Вет-Семес, он нам је учинио ово велико зло; ако ли не пође тако, онда ћемо знати да нас се није дохватила рука његова, него нам се догодило случајно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'И учинише тако они људи; и узевши двије краве дојилице упрегоше их у кола, а телад њихову затворише код куће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'И метнуше ковчег Господњи на кола, и мали ковчежић с мишима златнијем и са сликама својих шуљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'И пођоше краве право путем у Вет-Семес, и једнако иђаху истијем путем мучући и не сврћући ни надесно ни налијево; а кнезови Филистејски иђаху за њима до међе Вет-Семеске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'А Вет-Семешани жњаху пшеницу у долини, и подигавши очи своје видјеше ковчег, и обрадоваше се видјевши га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'И дођоше кола на њиву Исуса Вет-Семешанина, и стадоше ондје. А бијаше ондје велик камен; и исцјепаше дрва од кола, и принесоше оне краве на жртву паљеницу Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'А Левити снимивши ковчег Господњи и ковчежић што бјеше покрај њега, у којем бијаху заклади златни, метнуше на онај велики камен; а људи из Вет-Семеса готовише жртве паљенице и принесоше жртве Господу онај дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'А то видјевши пет кнезова Филистејских вратише се у Акарон исти дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'А ово бјеху златни шуљеви које дадоше Филистеји Господу за гријех: за Азот један, за Газу један, за Аскалон један, за Гат један, за Акарон један.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'И миши златни бјеху према броју свијех градова Филистејских, у пет кнежевина, свијех зиданијех градова и села неограђенијех до великога камена, на који метнуше ковчег Господњи, и који је и данас у пољу Исуса Вет-Семешанина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Али поби Господ неке између Вет-Семешана који загледаше у ковчег Господњи, и поби из народа педесет тисућа и седамдесет људи. И плака народ што га Господ удари великом погибљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'И људи из Вет-Семеса рекоше: ко може остати пред тијем Господом Богом светијем? и ка коме ће отићи од нас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'И послаше посланике к становницима Киријат-Јаримским говорећи: донесоше натраг Филистеји ковчег Господњи, ходите, однесите га к себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Тада дођоше људи из Киријат-Јарима: и узеше ковчег Господњи, и однесоше га у кућу Авинадавову на брду, а Елеазара сина његова посветише да чува ковчег Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'А кад ковчег оста у Киријат-Јариму, прође много времена, двадесет година, и плакаше сав дом Израиљев за Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'А Самуило рече свему дому Израиљеву говорећи: ако се свијем срцем својим обраћате ка Господу, поврзите туђе богове између себе и Астароте, и спремите срце своје за Господа, њему јединому служите, па ће вас избавити из руку Филистејских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'И повргоше синови Израиљеви Вале и Астароте, и служише Господу јединому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Потом рече Самуило: скупите свега Израиља у Миспу, да се помолим Господу за вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'И скупише се у Миспу, и црпући воду прољеваше пред Господом, и постише онај дан, и ондје рекоше: сагријешисмо Господу. И Самуило суђаше синовима Израиљевијем у Миспи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'А Филистеји кад чуше да су се синови Израиљеви скупили у Миспу, изидоше кнезови Филистејски на Израиља. А кад то чуше синови Израиљеви, уплашише се од Филистеја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'И рекоше синови Израиљеви Самуилу: не престај вапити за нас ка Господу Богу нашему, еда би нас избавио из руку Филистејских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Тада Самуило узе једно јагње одојче, и принесе га свега Господу на жртву паљеницу; и вапи Самуило ка Господу за Израиља, и услиши га Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'И кад Самуило приношаше жртву паљеницу, приближише се Филистеји да ударе на Израиља; али загрмје Господ грмљавином великом у онај дан на Филистеје и смете их, и бише побијени пред Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'А Израиљци изидоше из Миспе, и потјераше Филистеје, и бише их до под Вет-Хар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Тада узе Самуило камен, и метну га између Миспе и Сена, и назва га Евен-Езер, јер рече: довде нам Господ поможе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Тако бише покорени Филистеји, и више не долазише на међу Израиљеву. И рука Господња бјеше против Филистеја свега вијека Самуилова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'И повратише се Израиљу градови, које бјеху узели Филистеји Израиљу, од Акарона до Гата, и међе њихове избави Израиљ из руку Филистејских; и би мир међу Израиљем и Аморејима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'А Самуило суђаше Израиљу свега вијека својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'И идући сваке године обилажаше Ветиљ и Галгал и Миспу, и суђаше Израиљу у свијем тијем мјестима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Потом се враћаше у Раму, јер ондје бијаше кућа његова, и суђаше ондје Израиљу, и ондје начини олтар Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'А кад Самуило остарје, постави синове своје за судије Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'А име сину његову првенцу бјеше Јоило, а другому Авија, и суђаху у Вирсавеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Али синови његови не хођаху путовима његовијем, него ударише за добитком, и примаху поклоне и извртаху правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Тада се скупише све старјешине Израиљеве и дођоше к Самуилу у Раму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'И рекоше му: ето, ти си остарио, а синови твоји не ходе твојим путовима: зато постави нам цара да нам суди, као што је у свијех народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Али Самуилу не би по вољи што рекоше: дај нам цара да нам суди. И Самуило се помоли Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'А Господ рече Самуилу: послушај глас народни у свему што ти говоре; јер не одбацише тебе него мене одбацише да не царујем над њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Како чинише од онога дана кад их изведох из Мисира до данас, и оставише ме и служише другим боговима, по свијем тијем дјелима чине и теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Зато сада послушај глас њихов; али им добро засвједочи и кажи начин којим ће цар царовати над њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'И каза Самуило све ријечи Господње народу који искаше од њега цара;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'И рече: ово ће бити начин којим ће цар царовати над вама: синове ваше узимаће и метати их на кола своја и међу коњике своје, и они ће трчати пред колима његовијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'И поставиће их да су му тисућници и педесетници, и да му ору њиве и жњу љетину, и да му граде ратне справе и што треба за кола његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Узимаће и кћери ваше да му граде мирисне масти и да му буду кухарице и хљебарице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'И њиве ваше и винограде ваше и маслинике ваше најбоље узимаће и раздавати слугама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Узимаће десетак од усјева ваших и од винограда ваших, и даваће дворанима својим и слугама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'И слуге ваше и слушкиње ваше и младиће ваше најљепше и магарце ваше узимаће, и обртати на своје послове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Стада ће ваша десетковати и ви ћете му бити робови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Па ћете онда викати, ради цара својега, којега изабрасте себи; али вас Господ неће онда услишити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Али народ не хтје послушати ријечи Самуиловијех, и рекоше: не, него цар нека буде над нама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Да будемо и ми као сви народи; и нека нам суди цар наш и иде пред нама и води наше ратове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'А Самуило чувши све ријечи народне, каза их Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'А Господ рече Самуилу: послушај глас њихов, и постави им цара. И Самуило рече Израиљцима: идите сваки у свој град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'А бјеше један човјек од племена Венијаминова, којему име бјеше Кис, син Авила, сина Серора, сина Вехората, сина Афије, сина једнога човјека од племена Венијаминова, храбар јунак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Он имаше сина по имену Саула, који бјеше млад и лијеп да не бјеше љепшега од њега међу синовима Израиљевијем, а главом бјеше виши од свега народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'А Кису оцу Саулову неста магарица, па рече Кис Саулу сину својему: узми са собом једнога момка, па устани и иди те тражи магарице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'И он прође гору Јефремову, и прође земљу Салиску; али не нађоше; па прођоше у земљу Салимску, и не бјеше их; па прођоше и земљу Венијаминову, и не нађоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'А кад дођоше у земљу Суфску, рече Саул момку својему који бјеше с њим: хајде да се вратимо, да се не би отац оканио магарица и забринуо се за нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'А он му рече: ево, у овом граду има човјек Божји, којега веома поштују; што год каже све се збива; хајдемо к њему, може бити да ће нас упутити куда бисмо ишли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'А Саул рече момку својему: хајде да идемо; али шта ћемо однијети човјеку? јер нам је хљеба нестало у торбама, а дара немамо да однесемо човјеку Божијему. Шта имамо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'А момак опет одговарајући рече Саулу: ето у мене четврт сикла сребра; то да дам човјеку Божијему да нас упути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'А у старо вријеме ко би ишао да пита Бога говораше: хајде да идемо к видиоцу. Јер ко се сада зове пророк у старо се вријеме зваше видјелац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'И Саул рече момку својему: добро велиш; хајде да идемо. И пођоше у град гдје бјеше човјек Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'И кад иђаху уз брдо градско, сретоше дјевојке које излажаху да захватају воду, па им рекоше: је ли ту видјелац?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'А оне одговарајући рекоше: јест, ето пред тобом; похитај, јер је данас дошао у град, јер данас народ има жртву на гори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Како уђете у град, наћи ћете га прије него пође на гору да једе; јер народ неће јести докле он не дође, јер он треба да благослови жртву, па онда ће званице јести; зато идите, јер ћете га сада наћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'И отидоше у град; а кад дођоше усред града, гле Самуило полазећи на гору срете их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'А Господ бјеше објавио Самуилу дан прије него дође Саул, рекавши:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Сјутра у ово доба послаћу к теби једнога човјека из земље Венијаминове, њега помажи да буде вођ народу мојему Израиљу, и он ће избавити мој народ из руку Филистејских. Јер погледах на народ свој, јер вика његова дође до мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'И кад Самуило угледа Саула, рече му Господ: ето човјека за којега ти рекох; тај ће владати мојим народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'И Саул приступи к Самуилу на вратима, и рече: кажи ми, гдје је кућа видиочева?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'А Самуило одговори Саулу и рече: ја сам видјелац. Хајде преда мном на гору, и данас ћете са мном јести; а сјутра ћу те отпустити, и што ти је год у срцу, казаћу ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'А за магарице, којих ти је нестало прије три дана, не брини се; јер су се нашле. И чије ће бити све што је најбоље у Израиљу? еда ли не твоје и свега дома оца твојега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'А Саул одговори и рече: нијесам ли од племена Венијаминова, најмањега племена Израиљева, и дом мој најмањи између свијех домова племена Венијаминова? што ми дакле говориш тако?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'А Самуило узе Саула и његова момка, и одведе их у собу, и посади их у зачеље међу званицама којих бјеше до тридесет људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'И Самуило рече кухару: донеси дио који ти дадох и за који ти рекох: остави га код себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Тада донесе кухар плеће и што бјеше на њему; а Самуило га метну пред Саула, и рече: ево што је остало, узми преда се, те једи, јер је сачувано дослије за тебе, кад рекох: позвао сам народ. Тако једе Саул са Самуилом онај дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Потом сиђоше с горе у град, и Самуило се разговара са Саулом на крову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'А ујутру уранише, и кад свиташе, зовну Самуило Саула на кров, и рече му: дигни се, да те отпустим. И кад се диже Саул, изидоше обојица, он и Самуило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'И кад дођоше на крај града, рече Самуило Саулу: реци момку нека иде напријед (и он прође напријед), а ти стани мало да ти јавим ријеч Божију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Тада Самуило узе уљаницу, и изли му уље на главу, па га цјелова, и рече му: ето, није ли те помазао Господ над нашљедством својим да му будеш вођ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Кад отидеш данас од мене, наћи ћеш два човјека код гроба Рахиљина у крају Венијаминову у Селси, који ће ти рећи: нашле су се магарице, које си пошао да тражиш, и ево отац твој не марећи за магарице забринуо се за вас говорећи: шта ћу чинити поради сина својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'И отишавши оданде даље кад дођеш у равницу Таворску, срешће те ондје три човјека идући к Богу у Ветиљ, носећи један три јарета, а други носећи три хљеба, а трећи носећи мјешину вина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Па ће те упитати за здравље, и даће ти два хљеба, које прими из руку њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Потом ћеш доћи на хум Божји, гдје је стража Филистејска, и кад уђеш у град, срешће те гомила пророка слазећи с горе, а пред њима псалтири и бубњи и свирале и гусле; и они ће пророковати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'И сићи ће на те дух Господњи, те ћеш пророковати с њима, и постаћеш други човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'И кад ти дођу ти знаци, чини што ти дође на руку, јер је Бог с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Потом ћеш отићи прије мене у Галгал, и гле, ја ћу доћи к теби да принесем жртве паљенице и да принесем жртве захвалне. Седам дана чекај докле дођем к теби и кажем ти шта ћеш чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'И кад се окрете да иде од Самуила, Бог му даде друго срце; и сви се они знаци збише онај дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'И кад дођоше на хум, гле, срете га гомила пророка, и дође на њ дух Божји, и пророкова међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'И кад га видјеше сви који га познаваху од пређе гдје пророкује с пророцима, рекоше један другоме: шта то би од сина Кисова? еда ли је и Саул међу пророцима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'А један оданде одговори и рече: ко ли им је отац? Отуда поста прича: еда ли је и Саул међу пророцима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'И преставши пророковати дође на гору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'А стриц Саулов рече њему и момку његову: куда сте ишли? А он одговори: да тражимо магарице; и кад видјесмо да их нигдје нема, отидосмо к Самуилу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'А стриц Саулов рече: кажи ми шта вам је рекао Самуило?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'А Саул рече стрицу својему: казао нам је да су се нашле магарице. Али му не рече за царство што му је казао Самуило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'А Самуило сазва народ у Миспу ка Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'И рече синовима Израиљевијем: овако вели Господ Бог Израиљев: ја изведох Израиља из Мисира, и избавих вас из руку Мисирских и избавих вас из руку свијех царстава која вас мучаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'А ви данас одбацисте Бога својега, који вас сам избавља од свијех зала ваших и невоља ваших, и рекосте му: постави цара над нама. Сада дакле станите пред Господом по племенима својим и по тисућама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'И приведе Самуило сва племена Израиљева, и паде на племе Венијаминово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Потом приведе племе Венијаминово по породицама његовијем, и паде на породицу Матријеву; потом паде на Саула сина Кисова. И тражише га, али се не нађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Тада опет упиташе Господа: хоће ли још доћи овамо тај човјек? А Господ рече: ето сакрио се за пртљагом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Тада отрчаше, и доведоше га оданде. И стаде усред народа, и бијаше главом виши од свега народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'И рече Самуило свему народу: видите ли кога је изабрао Господ да нико није као он у свему народу? И сав народ повика и рече: да живи цар!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Тада Самуило каза народу права царска и написа у књигу, и метну је пред Господом. Потом Самуило распусти народ да иде свак својој кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'И Саул такођер отиде својој кући у Гавају, и с њим отидоше војници, којима Бог такну срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'А људи неваљали рекоше: тај ли ће нас избавити? И презираху га, нити му донесоше дара. Али се он учини као да није чуо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Тада дође Нас Амонац, и стаде у око према Јавису Галадову. И сви људи из Јависа рекоше Насу: учини вјеру с нама, па ћемо ти служити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'А Нас Амонац одговори им: овако ћу учинити вјеру с вама: да вам свакоме ископам десно око и ту срамоту учиним свему Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'А старјешине Јависке рекоше му: остави нам седам дана, да пошљемо посланике у све крајеве Израиљеве; па ако не буде никога да нас избави тада ћемо изаћи к теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'И дођоше посланици у Гавају Саулову, и казаше ове ријечи народу; тада сав народ подиже глас свој, и плакаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'А гле, Саул иђаше за говедима својим из поља, и рече: шта је народу те плаче? И казаше му шта су поручили Јавишани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Тада сиђе дух Божји на Саула кад чу те ријечи, и он се разгњеви врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Па узе два вола, и исијече их на комаде, и разасла их у све крајеве Израиљеве по истијем посланицима поручивши: ко не пође за Саулом и за Самуилом, овако ће бити са говедима његовијем. И страх Господњи попаде народ, те изидоше једнодушно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'И изброји их у Везеку, и бјеше синова Израиљевих триста тисућа, а синова Јудинијех тридесет тисућа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Потом рекоше посланицима који бијаху дошли: овако реците људима у Јавису Галадову: сјутра ћете се избавити, кад огрије сунце. И посланици се вратише, и јавише ово Јавишанима, и они се обрадоваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'И рекоше Јавишани Амонцима: сјутра ћемо изаћи к вама, да учините од нас што вам буде драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'И сјутрадан раздијели Саул народ у три чете, и уђоше усред окола о јутрењој стражи, и бише Амонце докле сунце не огрија, и који осташе, распршаше се да не осташе ни двојица заједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Тада рече народ Самуилу: који је оно што рече: еда ли ће Саул царовати над нама? дајте их да их погубимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Али Саул рече: да се не погуби данас нико, јер је данас Господ учинио спасење у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Тад Самуило рече народу: хајдете да идемо у Галгал, да ондје поновимо царство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'И сав народ отиде у Галгал, и поставише ондје Саула царем пред Господом у Галгалу, и ондје принесоше жртве захвалне пред Господом. И провесели се ондје Саул и сав Израиљ веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Тада рече Самуило свему Израиљу: ето, послушао сам глас ваш у свему што ми рекосте, и поставих цара над вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'И сада ето, цар иде пред вама, а ја сам остарио и осиједио; и синови моји ето су међу вама; и ја сам ишао пред вама од младости своје до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Ево ме, одговорите ми пред Господом и пред помазаником његовијем. Коме сам узео вола или коме сам узео магарца? коме сам учинио насиље? коме сам учинио криво? или из чије сам руке узео поклон, да бих стискао очи њега ради? пак ћу вам вратити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'А они рекоше: нијеси нам учинио силе нити си коме учинио криво, нити си узео што из чије руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Јоште им рече: свједок је Господ на вас, и свједок је помазаник његов данас, да нијесте нашли ништа у мојим рукама. И рекоше: свједок је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Тада рече Самуило народу: Господ је који је поставио Мојсија и Арона, и који је извео оце ваше из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Сада дакле станите да се прем с вама пред Господом за сва добра што је чинио Господ вама и вашим оцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Пошто дође Јаков у Мисир, викаше оци ваши ка Господу, и Господ посла Мојсија и Арона, који изведоше оце ваше из Мисира и населише их на овом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Али заборавише Господа Бога својега, те их даде у руке Сисари војводи Асорском, и у руке Филистејима, и у руке цару Моавскому, који војеваше на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Али викаше ка Господу и рекоше: сагријешисмо што остависмо Господа и служисмо Валима и Астаротама; али сада избави нас из руку непријатеља наших, па ћемо ти служити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'И Господ посла Јеровала и Ведана и Јефтаја и Самуила, и оте вас из руку непријатеља ваших унаоколо, те живјесте без страха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Али кад видјесте Наса цара Амонскога гдје дође на вас, рекосте ми: не, него цар нека царује над нама, премда Господ Бог ваш бјеше цар ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Сада дакле, ето цара којега изабрасте, којега искасте; ево Господ је поставио цара над вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Ако се узбојите Господа, и њему узаслужите, и узаслушате глас његов и не успротивите се заповијести Господњој, тада ћете и ви и цар ваш који царује над вама ићи за Господом Богом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Ако ли не узаслушате гласа Господњега, него се успротивите заповијести Господњој, тада ће бити рука Господња против вас као што је била против отаца ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Али станите сада јоште, и видите ову ствар велику коју ће учинити Господ пред вашим очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Није ли данас жетва пшенична? Ја ћу призвати Господа, и спустиће громове и дажд, да разумијете и видите колико је зло што учинисте пред Господом искавши себи цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Тада Самуило завапи ка Господу, и Господ спусти громове и дажд у тај дан; и сав се народ побоја врло Господа и Самуила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'И рече сав народ Самуилу: моли се за слуге своје Господу Богу својему да не помремо; јер додасмо к свијем гријесима својим зло иштући себи цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Тад рече Самуило народу: не бојте се, ви сте учинили све ово зло; али не отступајте од Господа, него служите Господу свијем срцем својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Не отступајте; јер бисте пошли за ништавим стварима, које не помажу, нити избављају, јер су ништаве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Јер Господ неће оставити народа својега ради великога имена својега; јер Господу би воља да вас учини својим народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'А мени не дао Бог да згријешим Господу и престанем молити се за вас; него ћу вас упућивати на пут добар и прав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Само се Бојте Господа и служите му истинито, свијем срцем својим, јер видите, какве је велике ствари учинио за вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Ако ли зло ушчините, пропашћете и ви и цар ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Кад Саул би цар годину дана (а царова двије године над Израиљем),');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Изабра себи Саул три тисуће између синова Израиљевих; и бијаху код Саула двије тисуће у Михмасу и у гори Ветиљској, а једна тисућа с Јонатаном у Гаваји Венијаминовој; а остали народ распусти у шаторе њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'И Јонатан поби стражу Филистејску која бјеше у Гаваји, и чуше за то Филистеји. А Саул заповједи, те трубише у трубе по свој земљи говорећи: нека чују Јевреји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'И тако чу сав Израиљ гдје рекоше: поби Саул стражу Филистејску; и стога Израиљ омрзну Филистејима. И сазван би народ за Саулом у Галгал.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'А Филистеји се скупише да војују на Израиља, тридесет тисућа кола и шест тисућа коњика, и мноштво народа као пијесак на бријегу морском; и изашавши стадоше у око у Михмасу, с истока од Вен-Авена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'И Израиљци се видјеше у невољи, јер народ би притијешњен; те се сакри у пећине и у честе и у камењаке и у расјелине и у јаме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'А други Јевреји пријеђоше преко Јордана у земљу Гадову и Галадову. А Саул још бијаше у Галгалу, и сав народ што иђаше за њим бијаше у страху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'И почека седам дана до рока Самуилова. Али Самуило не дође у Галгал; те се народ стаде разлазити од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Тада рече Саул: додајте ми жртву паљеницу и жртве захвалне. И принесе жртву паљеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'И кад принесе жртву паљеницу, гле, дође Самуило. И Саул изиде му на сусрет да га поздрави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'А Самуило му рече: шта си учинио? А Саул одговори: кад видјех гдје се народ разлази од мене, а ти не дође до рока, и Филистеји се скупили у Михмасу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Рекох: сад ће ударити Филистеји на ме у Галгал, а ја се још не помолих Господу: те се усудих и принесох жртву паљеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Тада рече Самуило Саулу: лудо си радио што нијеси држао заповијести Господа Бога својега, коју ти је заповједио; јер би сада Господ утврдио царство твоје над Израиљем довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'А сада царство твоје неће се одржати. Господ је нашао себи човјека по срцу својему, и њему је заповједио Господ да буде вођ народу његову, јер нијеси држао што ти је заповједио Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Потом диже се Самуило и отиде из Галгала у Гавају Венијаминову. И Саул изброји народ који оста код њега, и бјеше га до шест стотина људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'И Саул и син му Јонатан и народ што бјеше с њима, стајаху у Гаваји Венијаминовој; а Филистеји стајаху у околу у Михмасу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'И изидоше три чете из окола Филистејскога да плијене: једна чета удари путем к Офри у земљу Совалску;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'А друга чета удари путем к Вет-Орону; а трећа удари путем к међи која гледа према долини Севојимској у пустињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'А у цијелој земљи Израиљској не бјеше ковача, јер Филистеји рекоше: да не би градили Јевреји мачева ни копаља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Зато слажаху сви Израиљци к Филистејима кад који шћаше поклепати раоник или мотику или сјекиру или срп.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'И бијаху се затупили раоници и мотике и виле тророге и сјекире, и саме остане требаше заоштрити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Зато кад дође вријеме боју, не нађе се мача ни копља ни у кога у народу који бјеше са Саулом и Јонатаном; само бијаше у Саула и у Јонатана сина његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'И стража Филистејска изиде у кланац код Михмаса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Један дан рече Јонатан син Саулов момку својему који му ношаше оружје: хајде да идемо к стражи Филистејској која је на оној страни. А оцу својему не каза ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'А Саул стајаше крај брда под шипком, који бијаше у Мигрону; и народа бјеше с њим око шест стотина људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'И Ахија син Ахитова брата Ихавода сина Финеса сина Илија свештеника Господњега у Силому ношаше оплећак. И народ не знадијаше да је отишао Јонатан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'А у кланцу којим шћаше Јонатан отићи к стражи Филистејској, бијаху двије стрмене стијене, једна с једне стране а друга с друге, и једна се зваше Восес а друга Сене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'И једна од њих стајаше са сјевера према Михмасу, а друга с југа према Гаваји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'И Јонатан рече момку који му ношаше оружје: хајде да отидемо к стражи тијех необрезанијех; може бити да ће нам учинити што Господ, јер Господу не смета избавити с множином или с малином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'А онај што му ношаше оружје одговори му: чини што ти је год у срцу, иди, ево ја ћу ићи с тобом куда год хоћеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'А Јонатан му рече: ево, отићи ћемо к тијем људима, и показаћемо им се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Ако нам реку: чекајте докле дођемо к вама, тада ћемо се уставити на свом мјесту, и нећемо ићи к њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Ако ли реку: ходите к нама, тада ћемо отићи; јер нам их Господ предаде у руке. То ће нам бити знак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'И показаше се обојица стражи Филистејској; а Филистеји рекоше: гле, излазе Јевреји из рупа у које су се сакрили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'И стражари рекоше Јонатану и момку који му ношаше оружје: ходите к нама да вам кажемо нешто. И Јонатан рече оному што му ношаше оружје: хајде за мном, јер их предаде Господ у руке Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Тако пузаше Јонатан рукама и ногама, а за њим момак што му ношаше оружје; и падаху пред Јонатаном, и убијаше их за њим онај што му ношаше оружје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'И то би први бој, у ком поби Јонатан и момак што му ношаше оружје око двадесет људи, отприлике на по рала земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'И уђе страх у око у пољу и у сав народ; и стража и они који бјеху изашли да плијене препадоше се, и земља се усколеба, јер бјеше страх од Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'А стража Саулова у Гаваји Венијаминовој опази гдје се мноштво узбунило и успропадало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Тада рече Саул народу који бијаше с њим: прегледајте и видите ко је отишао од нас. И кад прегледаше, гле, не бјеше Јонатана и момка његова који му ношаше оружје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'И рече Саул Ахији: донеси ковчег Божји; јер ковчег Божји бијаше тада код синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'А док говораше Саул свештенику, забуна у околу Филистејском биваше све већа, и Саул рече свештенику: остави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'И Саул и сав народ што бјеше с њим скупише се и дођоше до боја, и гле, повадили бјеху мачеве један на другога, и забуна бјеше врло велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'А бијаше с Филистејима Јевреја као прије, који иђаху с њима на војску свуда; па и они присташе уз Израиљце, који бијаху са Саулом и Јонатаном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'И сви Израиљци који се бијаху сакрили у гори Јефремовој кад чуше да бјеже Филистеји, наклопише се и они за њима бијући их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'И избави Господ Израиља у онај дан; и бој отиде дори до Вет-Авена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'И Израиљци се врло уморише онај дан; а Саул закле народ говорећи: да је проклет који једе што до вечера, да се осветим непријатељима својим. И не окуси народ ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'И сав народ оне земље дође у шуму, гдје бјеше много меда по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'И кад дође народ у шуму, видје мед гдје тече; али нико не принесе руке к устима својим: јер се народ бојаше заклетве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Али Јонатан не чу кад отац његов закле народ, те пружи штап који му бјеше у руци, и замочи крај у сат, и примаче руку своју к устима својим, и засвијетлише му се очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'А један из народа проговори и рече: отац је твој заклео народ рекавши: да је проклет ко би јео што данас; стога суста народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Тада рече Јонатан: смео је земљу отац мој; видите како ми се засвијетлише очи, чим окусих мало меда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'А да је још народ слободно јео данас од плијена непријатеља својих, који нађе! не би ли полом Филистејски био још већи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'И тако побише онај дан Филистеје од Михмаса до Ајалона, и народ се врло умори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'И наклопи се народ на плијен, и нахваташе оваца и волова и телаца, и поклаше их на земљи, и стаде народ јести с крвљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'И јавише Саулу говорећи: ево народ гријеши Господу једући с крвљу. А он рече: невјеру учинисте; доваљајте сада к мени велик камен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'За тијем рече Саул: разидите се међу народ и реците: доведите сваки к мени вола својега и овцу своју; и овдје закољите и једите, и нећете гријешити Господу једући с крвљу. И донесе сав народ, сваки свога вола својом руком оне ноћи, и ондје клаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'И начини Саул олтар Господу; то би први олтар који начини Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Потом рече Саул: хајдемо за Филистејима ноћас, да их плијенимо до јутра, и да их не оставимо ниједнога. А они рекоше: чини што ти је год воља. Али свештеник рече: да приступимо овдје к Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'И упита Саул Бога: хоћу ли ићи за Филистејима? хоћеш ли их дати у руке Израиљу? Али не одговори му онај дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Зато рече Саул: приступите овамо сви главари народни, и тражите и видите на ком је гријех данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Јер како је жив Господ који избавља Израиља, ако буде и на Јонатану сину мојем, погинуће заиста. И не одговори му нико из свега народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Потом рече свему Израиљу: ви будите с једне стране, а ја и Јонатан син мој бићемо с друге стране. А народ рече Саулу: чини што ти је драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Тада рече Саул Господу Богу Израиљеву: покажи правога. И обличи се Јонатан и Саул, а народ изиде прав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'И рече Саул: баците ждријеб за ме и за Јонатана сина мојега. И обличи се Јонатан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Тада рече Саул Јонатану: кажи ми шта си учинио? И каза му Јонатан и рече: само сам окусио мало меда накрај штапа који ми бјеше у руци; ево ме; хоћу ли погинути?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'А Саул рече: то нека ми учини Бог и то нека дода, погинућеш, Јонатане!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Али народ рече Саулу: зар да погине Јонатан, који је учинио ово спасење велико у Израиљу? Боже сачувај! Тако жив био Господ, неће пасти на земљу ниједна длака с главе његове. Јер је с помоћу Божјом учинио то данас. И тако избави народ Јонатана, те не погибе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Тада се врати Саул од Филистеја, а Филистеји отидоше у своје мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'И Саул царујући над Израиљем ратоваше на све непријатеље своје, на Моавце и на синове Амонове и на Едомце и на цареве Совске и на Филистеје, и куда се год обраћаше, надвлађиваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Скупи такођер војску и поби Амалика; и избави Израиља из руку онијех који га плијењаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'А Саул имаше синове: Јонатана и Исуја и Мелхисуја; а двјема кћерима његовијем бјеху имена првеници Мерава а млађој Михала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'А жени Сауловој бјеше име Ахиноама кћи Ахимасова; а војводи његову бјеше име Авенир син Нира стрица Саулова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Јер Кис отац Саулов и Нир отац Авениров бијаху синови Авилови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'И бијаше велики рат с Филистејима свега вијека Саулова; и кога год виђаше Саул храбра и јунака, узимаше га к себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'А Самуило рече Саулу: Господ ме је послао да те помажем за цара над народом његовијем, над Израиљем; слушај дакле ријечи Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Овако вели Господ над војскама: опоменух се шта је учинио Амалик Израиљу, како му се опро на путу кад је ишао из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Зато иди, и побиј Амалика, и затри као проклето све што год има; не жали га, него побиј и људе и жене и дјецу и што је на сиси и волове и овце и камиле и магарце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Тада Саул сазва народ, и изброји их у Телаиму, и бјеше их двјеста тисућа пјешака и десет тисућа људи од Јуде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'И дође Саул до града Амаличкога, и намјести засједу у потоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'И рече Саул Кенејима: идите, одвојите се, уклоните се од Амалика, да вас не би потро с њима; јер сте ви учинили милост свијем синовима Израиљевијем кад су ишли из Мисира. И отидоше Кенеји од Амалика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'И Саул поби Амалике од Авиле до Сура, који је према Мисиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'И ухвати Агага цара Амаличкога жива, а сав народ његов поби оштријем мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'И Саул и народ његов поштедје Агага и најбоље овце и најбоље волове и угојену стоку и јагањце и све што бијаше добро, и не хтјеше побити; него што бијаше зло и без цијене, оно побише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Зато дође ријеч Господња к Самуилу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Кајем се што сам Саула поставио царем, јер је отступио од мене, и није извршио мојих ријечи. И расрди се Самуило врло, и викаше ка Господу сву ноћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'И уставши рано Самуило пође пред Саула. И јавише Самуилу говорећи: Саул дође у Кармил, и ено подиже себи споменик, па се врати оданде и отиде даље и сиђе у Галгал.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Кад Самуило дође к Саулу, рече му Саул: благословен да си Господу! извршио сам ријеч Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'А Самуило рече: каква је то блека оваца у ушима мојим? и рика волова коју чујем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'А Саул рече: од Амалика догнаше их; јер народ поштедје најбоље овце и најбоље волове да принесе на жртву Господу Богу твојему; остало пак побисмо као проклето.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'А Самуило рече Саулу: стани да ти кажем што ми је рекао Господ ноћас. Рече му: говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Тада рече Самуило: нијеси ли био мали сам у својим очима, пак си постао глава племенима Израиљевијем, и Господ те помаза за цара над Израиљем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'И Господ те посла на овај пут и рече: иди, побиј грјешне Амалике, и војуј на њих докле их не истријебите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Зашто дакле не послуша гласа Господњега, него се наклопи на плијен, и учини зло пред Господом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'А Саул одговори Самуилу: та послушао сам глас Господњи, и ишао сам путем којим ме посла Господ, и довео сам Агага цара Амаличкога, а Амалике сам истријебио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Него народ узе од плијена овце и волове, најбоље између проклетијех ствари, да принесе на жртву Господу Богу твојему у Галгалу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Али Самуило рече: зар су миле Господу жртве паљенице и приноси као кад се слуша глас његов? гле, послушност је боља од жртве и покорност од претилине овнујске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Јер је непослушност као гријех од чарања, и непокорност као сујевјерство и идолопоклонство. Одбацио си ријеч Господњу, зато је и он тебе одбацио да не будеш више цар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Тада рече Саул Самуилу: згријешио сам што сам преступио заповијест Господњу и твоје ријечи; јер побојах се народа и послушах глас његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Него сада опрости ми гријех мој, и врати се са мном да се поклоним Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'А Самуило рече Саулу: нећу се вратити с тобом, јер си одбацио ријеч Господњу, и зато је тебе Господ одбацио да не будеш више цар над Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'И Самуило се окрете да иде, али га Саул ухвати за скут од плашта његова, те се одадрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Тада му рече Самуило: одадро је Господ царство Израиљево од тебе данас, и дао га ближњему твојему, који је бољи од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'И доиста јунак Израиљев неће слагати, нити ће се раскајати; јер није човјек да се каје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'А он рече: згријешио сам; али ми сад учини част пред старјешинама народа мојега и пред Израиљем, и врати се са мном да се поклоним Господу Богу твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'И вративши се Самуило отиде за Саулом, и поклони се Саул Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Потом рече Самуило: доведите ми Агага цара Амаличкога. И дође к њему Агаг весео, јер говораше Агаг: заиста, прошла је горчина смртна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Али Самуило рече: како је твој мач учинио те су жене остале без дјеце, тако ће остати без дјеце твоја мајка међу женама. И исијече Самуило Агага пред Господом у Галгалу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Потом отиде Самуило у Раму, а Саул отиде кући својој у Гавају Саулову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'И Самуило не видје више Саула до своје смрти, и плакаше Самуило за Саулом, што се Господ покаја што је поставио Саула царем над Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'А Господ рече Самуилу: докле ћеш ти плакати за Саулом кад га ја одбацих да не царује више над Израиљем? Напуни рог свој уља, и ходи да те пошљем к Јесеју Витлејемцу, јер између његовијех синова изабрах себи цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'А Самуило рече: како да идем? јер ће чути Саул, па ће ме убити. А Господ одговори: узми са собом јуницу из говеда, па реци: дођох да принесем жртву Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'И позови Јесеја на жртву, а ја ћу ти показати шта ћеш чинити, и помажи ми онога кога ти кажем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'И учини Самуило како му каза Господ, и дође у Витлејем; а старјешине градске уплашивши се истрчаше преда њ, и рекоше му: јеси ли дошао добро?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'А он рече: добро; дошао сам да принесем жртву Господу; освештајте се и ходите са мном на жртву. Па освешта и Јесеја и синове његове и позва их на жртву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'И кад дођоше видјевши Елијава рече: јамачно је пред Господом помазаник његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Али Господ рече Самуилу: не гледај на лице његово ни на висину раста његова, јер сам га одбацио; јер не гледам на што човјек гледа: човјек гледа што је на очима, а Господ гледа на срце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'И дозва Јесеј Авинадава, и рече му да иде пред Самуила. А он рече: ни тога није изабрао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Потом Јесеј рече Сами да иде. А он рече: ни тога није изабрао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Тако рече Јесеј те прођоше седам синова његовијех пред Самуила; а Самуило рече Јесеју: није Господ изабрао тијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Потом рече Самуило Јесеју: јесу ли ти то сви синови? А он рече: остао је још најмлађи; ено га, пасе овце. Тада рече Самуило Јесеју: пошљи, те га доведи, јер нећемо сједати за сто докле он не дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'И посла, те га доведе. А бијаше смеђ, лијепијех очију и лијепа стаса. И Господ рече: устани, помажи га, јер је то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Тада Самуило узе рог са уљем, и помаза га усред браће његове; и сиђе дух Господњи на Давида и оста на њему од тога дана. Потом уста Самуило и отиде у Раму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'А дух Господњи отиде од Саула, и узнемираваше га зао дух од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'И рекоше Саулу слуге његове: гле, сада те узнемирује зли дух Божији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Нека господар наш заповједи слугама својим које стоје пред тобом, да потраже човјека који зна ударати у гусле, па кад те нападне зли дух Божји, нека удара руком својом, и одлакшаће ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'И рече Саул слугама својим: потражите човјека који зна добро ударати у гусле, и доведите ми га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'А један између слуга његовијех одговори и рече: ево, ја знам сина Јесеја Витлејемца, који умије добро ударати у гусле, и храбар је јунак и убојник, и паметан је и лијеп, и Господ је с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'И Саул посла људе к Јесеју и поручи: пошљи ми Давида сина својега који је код оваца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'А Јесеј узе магарца и хљеба и мјешину вина и једно јаре, и посла Саулу по Давиду сину својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'И Давид дође к Саулу и изиде преда њ, и омиље Саулу веома, те га постави да му носи оружје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Потом посла Саул к Јесеју и поручи: нека Давид остане код мене, јер је нашао милост преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'И кад би дух Божји напао Саула, Давид узевши гусле ударао би руком својом, то би Саул одахнуо и било би му боље, јер би зли дух отишао од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Тада Филистеји скупише војску своју да војују, и скупише се у Сокоту Јудину, и стадоше у око између Сокота и Азике на међи Дамимској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'А Саул и Израиљци скупише се и стадоше у око у долини Или, и уврсташе се према Филистејима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'И Филистеји стајаху на брду одонуда а Израиљци стајаху на брду одовуда, а међу њима бјеше долина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'И изиде из окола Филистејскога један заточник по имену Голијат из Гата, висок шест лаката и пед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'И на глави му бјеше капа од мједи, и оклоп плочаст на њему од мједи; и бијаше оклоп тежак пет тисућа сикала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'И ногавице од мједи бјеху му на ногу, и штит од мједи на раменима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'А копљача од копља му бјеше као вратило, а гвожђа у копљу му бјеше шест стотина сикала; и који му оружје ношаше иђаше пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Он ставши викаше војску Израиљску, и говораше им: што сте изашли уврставши се? нијесам ли ја Филистејин а ви слуге Саулове? изберите једнога између себе, па нека изађе к мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Ако ме надјача и погуби ме, ми ћемо вам бити слуге; ако ли ја њега надјачам и погубим га, онда ћете ви бити нама слуге, и служићете нам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Још говораше Филистејин: ја осрамотих данас војску Израиљску: дајте ми човјека да се бијемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'А кад Саул и сав Израиљ чу шта рече Филистејин, препадоше се и уплашише се врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'А бијаше Давид син једнога Ефраћанина, из Витлејема Јудина, којему име бјеше Јесеј, који имаше осам синова и бијаше у вријеме Саулово стар и временит међу људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'И три најстарија сина Јесејева отидоше за Саулом на војску; а имена тројици синова његовијех који отидоше на војску бијаху првенцу Елијав а другоме Авинадав а трећему Сама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'А Давид бијаше најмлађи. И она три најстарија отидоше за Саулом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'А Давид отиде од Саула и врати се у Витлејем да пасе овце оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'А Филистејин излажаше јутром и вечером, и стаја четрдесет дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'А Јесеј рече Давиду сину својему: узми сада за браћу своју ефу овога прженога жита и овијех десет хљебова, и однеси брже у око браћи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'А овијех десет младијех сираца однеси тисућнику, и види браћу своју како су, и донеси од њих знак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'А Саул и они и сав Израиљ бијаху у долини Или ратујући с Филистејима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'И тако Давид уста рано и остави овце на чувару; па узе и отиде како му заповједи Јесеј; и дође на мјесто гдје бјеше око, и војска излажаше да се врста за бој, и подизаше убојну вику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'И стајаше војска Израиљска и Филистејска једна према другој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Тада остави Давид свој пртљаг код чувара, који чуваше пртљаг, и отрча у војску, и дође и запита браћу своју за здравље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'И докле говораше с њима, гле, онај заточеник по имену Голијат Филистејин из Гата, изиде из војске Филистејске и говораше као прије, и Давид чу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'А сви Израиљци кад видјеше тога човјека, узбјегоше од њега, и бјеше их страх веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'И говораху Израиљци: видјесте ли тога човјека што изиде? Јер изиде да срамоти Израиља. А ко би га погубио, цар би му дао силно благо, и кћер своју дао би му; и ослободио би дом оца његова у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Тада рече Давид људима који стајаху око њега говорећи: шта ће се учинити човјеку који погуби тога Филистејина и скине срамоту с Израиља? Јер ко је тај Филистејин необрезани да срамоти војску Бога живога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'А народ му одговори исте ријечи говорећи: то ће се учинити ономе ко га погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'А кад чу Елијав брат његов најстарији како се разговара с тијем људима, разљути се Елијав на Давида, и рече му: што си дошао? и на ком си оставио оно мало оваца у пустињи? знам ја обијест твоју и злоћу срца твојега; дошао си да видиш бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'А Давид рече: шта сам сад учинио? заповјеђено ми је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Потом окрену се од њега к другоме и запита као прије; и народ му одговори као прије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'И кад чуше ријечи које говораше Давид, јавише их Саулу, а он га дозва к себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'И Давид рече Саулу: нека се нико не плаши од онога; слуга ће твој изаћи и биће се с Филистејином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'А Саул рече Давиду: не можеш ти ићи на Филистејина да се бијеш с њим, јер си ти дијете а он је војник од младости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'А Давид рече Саулу: слуга је твој пасао овце оца својега; па кад дође лав или медвјед и однесе овцу из стада,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Ја потрчах за њим, и ударих га и отех му из чељусти; и кад би скочио на ме; ухватих га за грло, те га бих и убих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'И лава и медвједа убијао је твој слуга, па ће и тај Филистејин необрезани проћи као они; јер осрамоти војску Бога живога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Још рече Давид: Господ који ме је сачувао од лава и медвједа, он ће ме сачувати и од овога Филистејина. Тада рече Саул Давиду: иди, и Господ нека буде с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'И Саул даде Давиду своје оружје, и метну му на главу капу своју од мједи и метну оклоп на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'И припаса Давид мач његов преко својега одијела и пође, али не бјеше навикао, па рече Давид Саулу: не могу ићи с тијем, јер нијесам навикао. Па скиде Давид са себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'И узе штап свој у руку, и изабра на потоку пет глатких камена и метну их у торбу пастирску, коју имаше, и узе праћу своју у руку, и тако пође ка Филистејину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'А и Филистејин иђаше све ближе к Давиду, а човјек који му ношаше оружје, иђаше пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'А кад Филистејин погледа и видје Давида, потсмјехну му се, што бјеше млад и смеђ и лијепа лица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'И рече Филистејин Давиду: еда ли сам псето, те идеш на ме са штапом? И проклињаше Филистејин Давида боговима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'И рече Филистејин Давиду: ходи к мени да дам тијело твоје птицама небеским и звијерима земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'А Давид рече Филистејину: ти идеш на ме с мачем и с копљем и са штитом; а ја идем на те у име Господа над војскама, Бога војске Израиљеве, којега си ружио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Данас ће те Господ дати мени у руке, и убићу те, и скинућу главу с тебе, и даћу данас тјелеса војске Филистејске птицама небеским и звјерима земаљским, и познаће сва земља да је Бог у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'И знаће сав овај збор да Господ не спасава мачем ни копљем, јер је рат Господњи, зато ће вас дати нама у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'А кад се Филистејин подиже и дође ближе к Давиду, Давид брже истрча на бојиште пред Филистејина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'И Давид тури руку своју у торбу своју, и извади из ње камен, и баци га из праће, и погоди Филистејина у чело и уђе му камен у чело, те паде ничице на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Тако Давид праћом и каменом надјача Филистејина, и удари Филистејина и уби га; а немаше Давид мача у руци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'И притрчав Давид стаде на Филистејина, и зграби мач његов и извуче га из корица и погуби га и отсијече му главу. А Филистеји кад видјеше гдје погибе јунак њихов побјегоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'А Израиљци и Јудејци усташе и повикаше и потјераше Филистеје до долине и до врата Акаронских; и падаше побијени Филистеји по путу Сарајимском до Гата и до Акарона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Потом се вратише синови Израиљеви тјеравши Филистеје, и оплијенише око њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'А Давид узе главу Филистејинову, и однесе је у Јерусалим, а оружје његово остави у својој колиби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'А кад Саул видје Давида гдје иде пред Филистејина, рече Авениру војводи: чији је син тај младић, Авенире? А Авенир рече: како је жива душа твоја, царе, не знам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'А цар рече: питај чији је син тај младић.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'А кад се врати Давид погубивши Филистејина, узе га Авенир и изведе га пред Саула, а у руци му бјеше глава Филистејинова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'И Саул рече му: чији си син, дијете? А Давид рече: ја сам син слуге твојега Јесеја Витлејемца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'И кад сврши разговор са Саулом, душа Јонатанова приону за душу Давидову, и Јонатан га запази као своју душу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'И узе га Саул тај дан, и не даде му да се врати кући оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'И Јонатан учини вјеру с Давидом, јер га љубљаше као своју душу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'И скиде Јонатан са себе плашт, који ношаше, и даде га Давиду, и одијело своје и мач свој и лук свој и појас свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'И иђаше Давид на што га год Саул пошиљаше, и бијаше срећан, и постави га Саул над војницима, и омиље свему народу, па и слугама Сауловијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'А кад се враћаху, и кад се Давид враћаше убивши Филистејина, излазише жене из свакога града Израиљева пјевајући и играјући на сусрет цару Саулу, с бубњима и с весељем и гуслама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'И отпијевајући жене једне другима уза свирке говораху: Саул згуби своју тисућу, али Давид својих десет тисућа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'И разгњеви се Саул врло, и не бише му по вољи те ријечи, и рече: Давиду дадоше десет тисућа, а мени дадоше тисућу; још му само царство треба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'И од тога дана Саул гледаше попријеко Давида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'А сјутрадан нападе Саула зли дух Божји, те пророковаше у кући, а Давид му удараше руком својом у гусле као прије: а Саулу у руци бјеше копље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'И Саул баци копље говорећи: да прикујем Давида за зид. Али му се Давид измаче два пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'И Саула бјеше страх од Давида, јер Господ бјеше с њим, а од Саула бјеше отступио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Зато га уклони Саул од себе, и постави га тисућником; и он одлажаше и долажаше пред народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'И Давид бијаше срећан у свему што чињаше, јер Господ бијаше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'А Саул видећи да је веома срећан, бојаше га се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'А сав Израиљ и Јуда љубљаше Давида, јер он одлажаше и долажаше пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'И рече Саул Давиду: ево, кћер своју старију Мераву даћу ти за жену, само ми буди храбар и води ратове Господње. Јер Саул говораше: нећу да се дигне моја рука на њ, него Филистејска рука нека се дигне на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'А Давид рече Саулу: ко сам ја и какав је живот мој или дом оца мојега у Израиљу, да будем зет царев?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'А кад дође вријеме да Мераву кћер Саулову даду Давиду, дадоше је Адрилу Меолаћанину за жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Али Давида љубљаше Михала кћи Саулова; а кад то јавише Саулу, би му по вољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'И рече Саул: даћу му је да му буде замка и да се диже на њ рука Филистејска. А Давиду рече Саул: бићеш ми данас зет с другом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'И заповједи Саул слугама својим: реците Давиду тајно и говорите: гле, омилио си цару, и све слуге његове љубе те; буди сада зет царев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'И слуге Саулове рекоше те ријечи Давиду, а Давид рече: мислите ли да је лако бити зет царев? та ја сам сиромах и мали човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'И Саулу јавише ово слуге његове говорећи: овако рече Давид.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'А Саул рече: овако реците Давиду: не тражи цар уздарја, него сто окрајака Филистејских, да се цар освети својим непријатељима. А Саул мишљаше како би Давид пао у руке Филистејима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'И слуге његове казаше Давиду те ријечи, и Давиду би по вољи да постане царев зет. И вријеме се још не наврши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'А Давид уста и отиде са својим људима, и поби двјеста Филистеја. И донесе Давид окрајке њихове, и дадоше их на број цару да би постао царев зет. И Саул му даде за жену Михалу кћер своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'И Саул видје и позна да је Господ са Давидом; и Михала кћи Саулова љубљаше га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'А Саул се још већма побоја Давида; и бијаше Саул једнако непријатељ Давиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'А кнезови Филистејски удараху; и кад год удараху, Давид бијаше срећнији од свијех слуга Сауловијех, и име се његово врло прослави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'И Саул говори Јонатану сину својему и свијем слугама својим да убију Давида; али Јонатан син Саулов љубљаше веома Давида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'И јави Јонатан Давиду и рече му: Саул отац мој тражи да те убије; него се чувај сјутра, склони се гдјегод и прикриј се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'А ја ћу изаћи и стајаћу поред оца својега у пољу гдје ти будеш, и говорићу о теби с оцем својим, и што дознам јавићу ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'И Јонатан проговори за Давида Саулу оцу својему, и рече му: да се не огријеши цар о слугу својега Давида, јер се он није огријешио о тебе, него је још врло добро за те што је чинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Јер није марио за живот свој и побио је Филистеје, и Господ учини спасење велико свему Израиљу; видио си и радовао си се; па зашто би се огријешио о крв праву и убио Давида ни за што?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'И послуша Саул Јонатана, и закле се Саул: тако жив био Господ, неће погинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Тада Јонатан дозва Давида, и каза му Јонатан све ово; и доведе Јонатан Давида к Саулу, и опет би пред њим као пређе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'И наста опет рат, и Давид изиде и поби се с Филијстејима, и разби их веома, те бјежаше од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Потом зли дух Господњи нападе Саула кад сјеђаше код куће и држаше копље у руци, а Давид удараше руком о гусле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'И Саул шћаше Давида копљем приковати за зид, али се он измаче Саулу, те копље удари у зид, а Давид побјеже и избави се ону ноћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'А Саул посла људе ка кући Давидовој да га чувају и ујутру убију. А то јави Давиду жена његова Михала говорећи: ако ноћас не избавиш душе своје, ујутру ћеш погинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Тада Михала спусти Давида кроз прозор, те отиде и побјеже и избави се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'А Михала узе лик, и метну га у постељу, и метну му под главу узглавље од костријети, и покри га хаљином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'И кад Саул посла људе да ухвате Давида, она рече: болестан је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'А Саул посла опет људе да виде Давида говорећи: донесите ми га у постељи да га погубим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'А кад дођоше послани, гле, лик у постељи и узглавље од костријети под главом му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'И рече Саул Михали: што ме тако превари и пусти непријатеља мојега да утече? А Михала рече Саулу: он ми рече: пусти ме, или ћу те убити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Тако Давид утече и избави се, и дође к Самуилу у Раму, и приповједи му све што му је учинио Саул. и отидоше он и Самуило, и осташе у Најоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'А Саулу дође глас и рекоше му: ено Давида у Најоту у Рами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Тада посла Саул људе да ухвате Давида; и они видјеше збор пророка гдје пророкују а Самуило им старјешина. И дух Господњи дође на посланике Саулове, те и они пророковаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'А кад то јавише Саулу, он посла друге посланике, али и они пророковаху, те Саул опет посла треће посланике, али и они пророковаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Тада сам пође у Раму, и кад дође на велики студенац који је у Сокоту, запита говорећи: гдје је Самуило и Давид? И рекоше му: ено их у Најоту у Рами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'И пође у Најот у Рами; али и на њега сиђе дух Божји, те идући даље пророковаше докле дође у Најот у Рами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Па скиде и он хаљине своје са себе, и пророкова и он пред Самуилом, и паднувши лежаше го цео онај дан и сву ноћ. Стога се говори: еда ли је и Саул међу пророцима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'А Давид побјеже из Најота у Рами, и дође и рече Јонатану: шта сам учинио? каква је кривица моја? и шта сам згријешио оцу твојему, те тражи душу моју?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'А он му рече: сачувај Боже! нећеш ти погинути. Ево отац мој не чини ништа, ни велико ни мало, а да мени не каже; а како би то тајио од мене отац мој? Неће то бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'А Давид заклињући се опет рече: отац твој зна добро да сам нашао љубав у тебе, па вели: не треба да дозна за ово Јонатан, да се не ожалости. Али тако жив био Господ и тако жива била душа твоја, само је један корак између мене и смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'А Јонатан рече Давиду: шта жели душа твоја? Ја ћу ти учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'И Давид рече Јонатану: ево сјутра је младина, кад треба с царем да једем, пусти ме дакле да се сакријем у пољу до трећега вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Ако запита за ме отац твој, ти реци: врло ми се молио Давид да отрчи у Витлејем град свој, јер је ондје годишња жртва свега рода његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Ако рече: добро, биће миран слуга твој; ако ли се разгњеви, знај да је зло наумио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Учини дакле милост слузи својему, кад си вјеру Господњу ухватио са слугом својим; ако је кака кривица на мени, убиј ме сам, јер зашто би ме водио к оцу својему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'А Јонатан му рече: Боже сачувај; јер да дознам да је отац мој наумио зло да те задеси, зар ти не бих јавио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'А Давид рече Јонатану: ко ће ми јавити ако ти отац одговори што је зло?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'А Јонатан рече Давиду: ходи да изидемо у поље. И изидоше обојица у поље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'И Јонатан рече Давиду: Господе Боже Израиљев! кад искушам оца својега сјутра у ово доба или прекосјутра, и буде добро по Давида, ако не пошљем к теби и не јавим ти,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Нека Господ учини тако Јонатану и тако нека дода. Ако ли отац мој буде наумио да ти учини зло, ја ћу ти јавити, и оправићу те, и отићи ћеш с миром; и Господ нека буде с тобом као што је био с оцем мојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'А и ти, докле сам жив, чинићеш мени милост Господњу да не погинем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'И нећеш укратити милости своје дому мојему довијека, ни онда кад Господ истријеби све непријатеље Давидове са земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Тако Јонатан учини вјеру с домом Давидовијем говорећи: Господ нека тражи из руку непријатеља Давидовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'И још закле Јонатан Давида љубављу својом к њему, јер га љубљаше као своју душу');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Потом рече му Јонатан: сјутра је младина, и питаће се за те, јер ће твоје мјесто бити празно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'А ти чекај до трећега дана, па онда отиди брзо и дођи на мјесто гдје си се био сакрио кад се ово радило, и сједи код камена Езила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'А ја ћу бацити три стријеле украј тога камена, као да гађам биљегу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'И ево послаћу момка говорећи му: иди, нађи стријеле. Ако речем момку: ето стријеле су за тобом овамо ближе, дигни их; тада дођи, добро је по те, и неће ти бити ништа, тако жив био Господ!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Ако ли овако речем момку: ето стријеле су пред тобом тамо даље; онда иди, јер те Господ шаље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'А за ове ријечи што рекосмо ја и ти, ево, Господ је свједок између мене и тебе довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Потом се Давид сакри у пољу; и дође младина, и цар сједе за сто да једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'А кад цар сједе на своје мјесто по обичају на мјесто код зида, Јонатан уста, а Авенир сједе до Саула, а мјесто Давидово бјеше празно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'И Саул не рече ништа онај дан, јер мишљаше, догодило му се штогод, те није чист, зацијело није чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'А сјутрадан, други дан мјесеца, опет бјеше празно мјесто Давидово, а Саул рече Јонатану сину својему: зашто син Јесејев не дође на објед ни јуче ни данас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'А Јонатан одговори Саулу: врло ме је молио Давид да отиде до Витлејема,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'Рекавши: пусти ме, јер породица наша има жртву у граду, и сам ми је брат заповједио; ако сам дакле нашао милост пред тобом, да отидем и видим браћу своју. Зато није дошао на царев објед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Тада се разгњеви Саул на Јонатана, те му рече: неваљали и непослушни сине! зар ја не знам да си изабрао сина Јесејева себи на срамоту и на срамоту својој неваљалој мајци?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Јер, докле је жив син Јесејев на земљи, нећеш се утврдити ни ти ни царство твоје; зато пошљи сада и доведи га к мени, јер је заслужио смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'А Јонатан одговори Саулу оцу својему и рече му: зашто да се погуби? шта је учинио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Тада се Саул баци копљем на њ да га убије. Тада видје Јонатан да је отац његов наумио убити Давида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'И уста Јонатан од стола његова, и ништа не једе други дан по младини; јер се забрину за Давида, што га отац осрамоти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'А кад би ујутру, изиде Јонатан у поље у вријеме како бјеше уговорио с Давидом, и с њим једно момче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'И рече момку својему: трчи да ми нађеш стријеле које ћу пустити. И момче отрча, а он пусти стријелу преко њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'А кад дође момак до мјеста куда бјеше застријелио Јонатан, викну Јонатан за момком говорећи: није ли стријела даље напријед?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Још викну Јонатан за момком: брже, не стој. И момак Јонатанов покупи стријеле, и врати се господару својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Али момак не знаше ништа, само Јонатан и Давид знаху шта је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'И Јонатан даде оружје своје момку који бијаше с њим, и рече му: иди, однеси у град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'И кад момак отиде, Давид уста с јужне стране и паде ничице на земљу, и поклони се три пута, и пољубише се, и плакаше обојица, а Давид особито.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'И рече Јонатан Давиду: иди с миром, као што смо се заклели обојица именом Господњим рекавши: Господ да је свједок између мене и тебе и између мојега сјемена и твојега сјемена довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 43, 'И тако Давид уставши отиде, а Јонатан се врати у град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Тада Давид дође у Нов к Ахимелеху свештенику; а Ахимелех се уплаши и истрча пред Давида, и рече му: зашто си сам, и нема никога с тобом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'А Давид рече Ахимелеху свештенику: цар ми нешто заповједи, и рече ми: нико да не дозна зашто те шаљем и шта сам ти заповједио. А слуге сам оправио у то и то мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Него шта имаш при руци? дај ми пет хљебова, или шта имаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'А свештеник одговори Давиду и рече: немам при руци обичнога хљеба; него има светога хљеба; али јесу ли се момци чували од жена?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'А Давид одговори свештенику и рече му: није било жена код нас ни јуче ни ономадне, откако сам пошао, и судови су у момака били свети. А ако би пут и нечист био, осветиће се данас судовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Тада му даде свештеник хљебове свете, јер не бјеше хљеба осим хљебова постављенијех, који бијаху узети испред Господа да се поставе хљебови топли онај дан кад се они узеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'А ондје бијаше онај дан један од слуга Сауловијех бавећи се пред Господом, којему име бјеше Доик Идумејац, старјешина над пастирима Сауловијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'И Давид рече Ахимелеху: имаш ли ту како копље или мач? јер ни мача својега ни оружја не понесох, јер ствар царева бијаше хитна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'А свештеник рече: овдје је мач Голијата Филистејина, којега си убио у долини Или, увијен у платно иза оплећака; ако хоћеш, узми га, јер другога осим њега нема овдје. А Давид рече: такога више нема, дај ми га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Потом се подиже Давид, и побјеже онај дан од Саула, и дође к Ахису цару Гатском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'А Ахису рекоше слуге његове: није ли ово Давид цар земаљски? Нијесу ли о њему пјевали играјући и говорећи: Саул згуби своју тисућу, а Давид својих десет тисућа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'И Давид метну ове ријечи у срце своје, и побоја се веома Ахиса цара Гатскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'И претвори се пред њима и учини се луд у рукама њиховијем; и шараше по вратима, и бацаше пјену низ браду своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'И Ахис рече слугама својим: ето, видите да је човјек луд; што сте ми га довели?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Зар немам доста лудијех, него ми доведосте тога да лудује преда мном? зар ће тај ући у кућу моју?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Тада Давид отиде оданде и утече у пећину Одоламску. А кад то чуше браћа његова и сав дом оца његова, дођоше онамо к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'И скупише се око њега који год бијаху у невољи и који бијаху задужени и који год бијаху тужна срца; и он им поста поглавица; и бјеше их с њим око четири стотине људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'И оданде отиде Давид у Миспу Моавску, и рече цару Моавском: допусти да се отац мој и мати моја склоне код вас докле видим шта ће Бог учинити са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'И изведе их пред цара Моавскога, и осташе код њега за све вријеме докле Давид бјеше у ономе граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Али пророк Гад рече Давиду: немој остати у том граду, иди и врати се у земљу Јудину. И Давид отиде и дође у шуму Арет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'А Саул чу да се појавио Давид и људи што бијаху с њим. Тада Саул сјеђаше у Гаваји под шумом у Рами, с копљем у руци, а све слуге његове стајаху пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'И рече Саул слугама својим које стајаху пред њим: чујте синови Венијаминови; хоће ли вама свјема син Јесејев дати њиве и винограде? хоће ли све вас учинити тисућницима и стотиницима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Те сте се сви сложили на ме, и нема никога да ми јави да се мој син сложио са сином Јесејевијем, и нема никога међу вама да мари за ме и да ми јави да је син мој подигао слугу мојега на ме да ми засједа, као што се данас види.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Тада одговори Доик Идумејац, који стајаше са слугама Сауловијем, и рече: видио сам сина Јесејева гдје дође у Нов к Ахимелеху сину Ахитовову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Он пита за њ Господа, и даде му брашњенице: и мач Голијата Филистејина даде му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Тада цар посла да доведу Ахимелеха сина Ахитовова свештеника и сав дом оца његова, свештенике, који бијаху у Нову. И дођоше сви к цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Тада рече Саул: чуј сада сине Ахитовов. А он одговори: ево ме, господару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'А Саул му рече: зашто сте се сложили на ме ти и син Јесејев, те си му дао хљеба и мач, и питао си Бога за њ, да би устао на ме да ми засједа, као што се види данас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'А Ахимелех одговори цару и рече: а ко је између свијех слуга твојих као Давид, вјеран, и зет царев и послушан теби и поштован у кући твојој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Еда ли сам сад први пут питао Господа за њ? Сачувај Боже! нека цар не биједи таким чим слуге својега нити кога у дому оца мојега; јер није знао слуга твој од свега тога ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Али цар рече: погинућеш, Ахимелеше! и ти и сав дом оца твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Тада цар рече слугама које стајаху пред њим: окрените се и погубите свештенике Господње, јер је и њихова рука с Давидом, и знајући да је побјегао не јавише ми. Али слуге цареве не хтјеше подигнути руке своје да уложе на свештенике Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Тада рече цар Доику: окрени се ти, те уложи на свештенике. И окренувши се Доик Идумејац уложи на свештенике, и поби их онај дан осамдесет и пет, који ношаху оплећак ланени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'И у Нову, граду свештеничком, исијече оштријем мачем и људе и жене и дјецу и која сисаху, и волове, и магарице и ситну стоку оштријем мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Али утече један син Ахимелеха сина Ахитовова, по имену Авијатар, и побјеже к Давиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'И Авијатар јави Давиду да је Саул побио свештенике Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'А Давид рече Авијатару: знао сам онога дана кад је био ондје Доик Идумејац да ће зацијело казати Саулу; ја сам крив за све душе дома оца твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Остани код мене, не бој се; јер ко тражи моју душу тражиће и твоју; код мене ћеш бити сачуван.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Тада јавише Давиду говорећи: ево Филистеји ударише на Кеилу, и харају гумна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'И упита Давид Господа говорећи: хоћу ли ићи и ударити на те Филистеје? А Господ рече Давиду: иди, и побићеш Филистеје и избавити Кеилу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'А Давиду рекоше људи његови: ево нас је страх овдје у Јудиној земљи, а шта ће бити кад пођемо у Кеилу, на око Филистејски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Зато Давид опет упита Господа, а Господ му одговори и рече: устани, иди у Кеилу, јер ћу ја предати Филистеје у руке твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Тада отиде Давид са својим људима у Кеилу, и удари на Филистеје, и отјера им стоку, и поби их љуто; тако избави Давид становнике Кеилске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'А кад Авијатар син Ахимелехов побјеже к Давиду у Кеилу, донесе собом оплећак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Потом јавише Саулу да је Давид дошао у Кеилу; и рече Саул: дао га је Бог у моје руке, јер се затворио ушавши у град, који има врата и пријеворнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'И сазва Саул сав народ на војску да иде на Кеилу и опколи Давида и људе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Али Давид дознавши да му Саул зло кује, рече Авијатару свештенику: узми на се оплећак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'И рече Давид: Господе Боже Израиљев! чуо је слуга твој да се Саул спрема да дође на Кеилу да раскопа град мене ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Хоће ли ме Кеиљани предати у његове руке? хоће ли доћи Саул као што је чуо слуга твој? Господе Боже Израиљев! кажи слузи својему. А Господ одговори: доћи ће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Опет рече Давид: Кеиљани хоће ли предати мене и моје људе у руке Саулове? А Господ одговори: предаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Тада се Давид подиже са својим људима, око шест стотина људи, и отидоше из Кеиле, и идоше куда могоше. А кад Саулу јавише да је Давид побјегао из Кеиле, тада он не хтје ићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'А Давид се бављаше у пустињи по тврдијем мјестима, и намјести се на једном брду у пустињи Зифу. А Саул га тражаше једнако, али га Господ не даде у његове руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'И Давид видећи да је Саул изашао те тражи душу његову, оста у пустињи Зифу, у шуми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'А Јонатан син Саулов подиже се и дође к Давиду у шуму, и укријепи му руку у Господу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'И рече му: не бој се, јер те неће стигнути рука цара Саула оца мојега; него ћеш царовати над Израиљем, а ја ћу бити други за тобом; и Саул отац мој зна то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'И учинише њих двојица вјеру пред Господом; и Давид оста у шуми, а Јонатан отиде кући својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Тада дођоше Зифеји к Саулу у Гавају, и рекоше: не крије ли се Давид код нас по тврдијем мјестима у шуми на брду Ехели надесно од Гесимона?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Сада дакле по свој жељи душе своје, царе, изиди, а наше ће бити да га предамо у руке цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'А Саул рече: Господ да вас благослови, што ме пожалисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Идите сада и дознајте још боље и разберите и промотрите гдје се сакрио и ко га је ондје видио; јер ми кажу да је врло лукав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Промотрите и видите сва мјеста гдје се крије, па опет дођите к мени кад добро дознате, и ја ћу поћи с вама; и ако буде у земљи, тражићу га по свијем тисућама Јудинијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Тада усташе и отидоше у Зиф прије Саула; а Давид и људи његови бијаху у пустињи Маону у равници надесно од Гесимона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'И Саул изиде са својим људима да га тражи; а Давиду јавише, те он сиђе са стијене и стаде у пустињи Маону. А Саул кад то чу, отиде за Давидом у пустињу Маон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'И Саул иђаше једном страном планине, а Давид са својим људима другом страном планине; и Давид хићаше да утече Саулу, јер Саул са својим људима опкољаваше Давида и његове људе да их похвата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'У том дође гласник Саулу говорећи: брже ходи; јер Филистеји ударише на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Тада се врати Саул не тјерајући даље Давида, и отиде пред Филистеје. Отуда се прозва оно мјесто Села-Амалекот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'А Давид отишавши оданде стаде на тврдијем мјестима Енгадским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'И кад се Саул врати одагнавши Филистеје, рекоше му говорећи: ено Давида у пустињи Енгадској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Тада узе Саул три тисуће људи изабранијех из свега Израиља, и отиде да тражи Давида и људе његове по врлетима гдје су дивокозе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'И дође к торовима овчијим украј пута гдје бијаше пећина; и Саул уђе у њу рад себе; а Давид и његови људи сјеђаху у крају у пећини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'И рекоше Давиду људи његови: ево дана, за који ти рече Господ: ево ја ти предајем непријатеља твојега у руке да учиниш што ти је воља. И Давид уста, те полако отсијече скут од плашта Саулова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'А послије задрхта срце Давиду што отсијече скут Саулу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'И рече својим људима: не дао Бог да то учиним господару својему, помазанику Господњему, да подигнем руку своју на њ. Јер је помазаник Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'И одврати ријечима Давид људе своје и не даде им да устану на Саула. И Саул изашав из пећине пође својим путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Потом Давид уста, и изашав из пећине стаде викати за Саулом говорећи: царе господине! А Саул се обазре, а Давид се сави лицем до земље и поклони се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'И рече Давид Саулу: зашто слушаш што ти кажу људи који говоре: ето Давид тражи зло твоје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Ево, данас видјеше очи твоје да те је Господ био предао данас у моје руке у овој пећини, и рекоше ми да те убијем: али те поштедјех, и рекох: нећу дигнути руке своје на господара својега, јер је помазаник Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Ево, оче мој, ево види скут од плашта својега у мојој руци: отсјекох скут од плашта твојега, а тебе не убих; познај и види да нема зла ни неправде у руци мојој, и да ти нијесам згријешио; а ти вребаш душу моју да је узмеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Господ нека суди између мене и тебе, и нека ме освети од тебе; али рука се моја неће подигнути на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Како каже стара прича: од безбожнијех излази безбожност; зато се рука моје неће подигнути на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'За ким је изашао цар Израиљев? кога гониш? мртва пса, буху једну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Господ нека буде судија, и нека расуди између мене и тебе; он нека види и расправи моју парницу и избави ме из руке твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'А кад изговори Давид ове ријечи Саулу, рече Саул: је ли то твој глас, сине Давиде? И подигавши Саул глас свој заплака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'И рече Давиду: правији си од мене, јер си ми вратио добро за зло које сам ја теби учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'И данас си ми показао да ми добро чиниш; јер ме Господ даде теби у руке, а ти ме опет не уби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'И ко би нашавши непријатеља својега пустио га да иде добријем путем? Господ нека ти врати добро за ово што си ми учинио данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'И сада, ево, знам да ћеш зацијело бити цар, и јако ће бити у твојој руци царство Израиљево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Зато ми се сада закуни Господом да нећеш истријебити сјемена мојега послије мене, ни имена мојега затрти у дому оца мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 23, 'И закле се Давид Саулу; и Саул отиде кући својој, а Давид и људи његови отидоше на тврдо мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'У том умрије Самуило и сабра се сав Израиљ, и плакаше за њим, и погребоше га у дому његову у Рами. А Давид уста и сиђе у пустињу Фаранску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'А бијаше један човјек у Маону, а стока му бијаше на Кармилу; и бијаше човјек врло богат, јер имаше три тисуће оваца и тисућу коза, и тада стризијаше овце своје на Кармилу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'И бјеше име том човјеку Навал, а жени му име Авигеја; и она бијаше жена разумна и лијепа, а он бијаше тврда срца и опак, а бијаше од рода Халевова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'И Давид чу у пустињи да Навал стриже овце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'И посла Давид десет момака, и рече Давид момцима: идите на Кармил, и отидите к Навалу, и поздравите га од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'И реците му: здраво! и мир да ти је, и дому твојему да је мир, и свему што имаш да је мир!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Чуо сам да стрижеш овце; пастири су твоји бивали код нас, и не учинисмо им неправде, и ништа им није нестало докле год бијаху на Кармилу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Питај слуге своје, и казаће ти. Нека ови момци нађу милост пред тобом, јер дођосмо у добар дан. Дај слугама својим и Давиду сину својему што ти дође до руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'И дођоше момци Давидови, и казаше Навалу у име Давидово све ове ријечи, и умучаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'А Навал одговори слугама Давидовијем и рече: ко је Давид? и ко је син Јесејев? Данас има много слуга које бјеже од својих господара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Еда ли ћу узети хљеб свој и воду своју и месо што сам поклао за људе који ми стригу овце, па дати људима којих не знам одакле су?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Тада се вратише момци Давидови својим путем, вратише се, и дошавши казаше му све ове ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'А Давид рече својим људима: припашите сваки свој мач. И припасаше сваки свој мач, и Давид припаса свој мач; и пође за Давидом до четири стотине људи, а двјеста осташе код пртљага.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Али Авигеји жени Наваловој каза један између слуга његовијех говорећи: ево, Давид посла из пустиње посланике да поздрави господара нашега, а он их отјера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'А ти су нам људи били врло добри, нити нам учинише криво, нити нам чега неста докле год бијасмо код њих у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Него нам бијаху зидови и ноћу и дању, докле год бијасмо код њих пасући овце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Зато сада гледај и промисли шта ћеш чинити, јер је готово зло господару нашему и свему дому његову; а он је зао човјек, да му се не може говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Тада Авигеја брже узе двјеста хљебова и двије мјешине вина и пет оваца зготовљенијех и пет мјерица пржена жита, и сто гроздова сухога грожђа и двјеста груда сухих смокава, и метну на магарце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'И рече момцима својим: хајдете напријед, а ја ћу ићи за вама. А мужу својему Навалу ништа не рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'И сједавши на магарца иђаше испод горе, а гле, Давид и људи његови слажаху пред њу, и сукоби се с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'А Давид говораше: еле сам залуду чувао све што је тај имао у пустињи да му ништа не бјеше нестало од свега што има; јер ми врати зло за добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'То нека учини Бог непријатељима Давидовијем и то нека дода, ако му до зоре од свега што има оставим и оно што мокри уз зид.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'А кад Авигеја угледа Давида, брже сиђе с магарца, и паде пред Давидом на лице своје и поклони се до земље;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'И паднувши му к ногама рече: на мени, господару, нека буде та кривица; али да проговори слушкиња твоја теби, и чуј ријечи слушкиње своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Нека господар мој не гледа на тога неваљалога човјека, Навала, јер је као име што му је; Навал му је име, и безумље је код њега. А ја слушкиња твоја нијесам видјела момака господара својега које си слао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Зато сада, господару, тако жив био Господ и тако жива била душа твоја, Господ ти не да да идеш на крв и да се осветиш својом руком. Зато сада нека буде непријатељима твојим као Навалу и свјема који траже зла господару мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Ево дар што је донијела слушкиња господару својему, да се да момцима који иду за господаром мојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Опрости слушкињи својој кривицу; јер ће Господ зацијело начинити тврду кућу Господару мојему; јер ратове Господње води господар мој и није се нашло зло на теби никад твога вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'И да устане човјек да те гони и тражи душу твоју, душа ће господара мојега бити везана у свежњу живијех код Господа Бога твојега, а душе ће непријатеља твојих бацити као из праће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'И кад Господ учини господару мојему свако добро које ти је обрекао, и постави те вођем Израиљу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'Неће ти бити спотицања ни саблазни срцу господара мојега да је пролио крв ни за што и да се сам осветио господар мој. И кад учини Господ добро Господару мојему, опоменућеш се слушкиње своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Тада рече Давид Авигеји: да је благословен Господ Бог Израиљев, који те данас посла мени на сусрет!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'И да су благословене ријечи твоје, и ти да си благословена, која ме одврати данас да не идем на крв и осветим се својом руком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Доиста, тако жив био Господ Бог Израиљев, који ми не даде да ти учиним зло, да ми нијеси брже изашла на сусрет, не би остало Навалу до зоре ни оно што уза зид мокри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'И прими Давид из руке њезине што му бјеше донијела, и рече јој: иди с миром кући својој; ето, послушах те, и погледах на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Потом се Авигеја врати к Навалу; а гле, код њега гозба у кући, као царска гозба, и срце Навалу бјеше весело, и бијаше пијан врло. Зато му она не рече ништа до јутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'А ујутру кад се Навал отријезни, каза му жена све ово; а у њему обамрије срце његово, и он поста као камен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'А кад прође до десет дана, удари Господ Навала, те умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'А кад Давид чу да је умро Навал, рече: да је благословен Господ, који освети срамоту моју од Навала, и задржа слугу својега ода зла, а обрати Господ Навалу на главу злоћу његову. Потом посла Давид и поручи Авигеји да ће је узети за жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'И слуге Давидове дођоше к Авигеји на Кармил, и рекоше јој говорећи: Давид нас посла к теби да те узме за жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'А она уста и поклони се лицем до земље, и рече: ево слушкиње твоје, да служи и да пере ноге слугама господара својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Потом брже уста Авигеја, и сједе на магарца, и пет дјевојака њезинијех пође за њом, и отиде за посланицима Давидовијем, и поста му жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'А Давид узе и Ахиноаму из Језраела: и обје му беху жене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Јер Саул даде Михалу кћер своју, жену Давидову, Фалтију сину Лаисову из Галима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Опет дођоше Зифеји к Саулу у Гавају говорећи: не крије ли се Давид на брду Ехели према Гесимону?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'А Саул се подиже и сиђе у пустињу Зифску, и с њим три тисуће људи изабранијех из Израиља, да тражи Давида у пустињи Зифској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'И стаде Саул у око на брду Ехели према Гесимону крај пута; а Давид оста у пустињи, и опази да Саул иде за њим у пустињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'И посла Давид уходе, и од њих дозна зацијело да је дошао Саул.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Тада се подиже Давид и дође на мјесто гдје Саул бијаше с војском. И Давид видје мјесто гдје спаваше Саул и Авенир син Ниров војвода његов; а спаваше Саул међу колима а народ лежаше око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'И Давид проговори и рече Ахимелеху Хетејину и Ависају сину Серујину брату Јоавову: ко ће сићи са мном к Саулу у око? А Ависај одговори: ја ћу сићи с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'И тако Давид и Ависај дођоше ноћу к народу; а гле, Саул лежаше и спаваше између кола, и копље му бјеше чело главе пободено у земљу; Авенир пак и народ лежаху око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Тада рече Ависај Давиду: данас ти даде Бог непријатеља твојега у руке; зато сада да га прободем копљем за земљу једанпут, нећу више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'А Давид рече Ависају: немој га убити; јер ко ће подигнути руку своју на помазаника Господњега и бити прав?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Још рече Давид: тако жив био Господ, Господ ће га убити, или ће доћи дан његов да умре, или ће изаћи у бој и погинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Не дао ми Бог да дигнем руку своју на помазаника Господњега! Него узми сада копље што му је чело главе и чашу за воду, па да идемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'И Давид узе копље и чашу за воду, што бјеше чело главе Саулу, и отидоше; и нико их не видје и не осјети, нити се који пробуди, него сви спаваху; јер бјеше напао на њих тврд сан од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'И Давид прешав на другу страну стаде наврх брда издалека; и бјеше између њих много мјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'И стаде Давид викати народ и Авенира сина Нирова говорећи: што се не одзиваш, Авенире? А Авенир се одазва и рече: који си ти што вичеш цара?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'А Давид рече Авениру: нијеси ли ти јунак? и ко је као ти у Израиљу? зашто нијеси чувао цара господара својега? Јер је ишао један из народа да убије господара твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Нијеси добро радио. Тако да је жив Господ, заслужили сте смрт што нијесте чували господара својега, помазаника Господњега. Ето, гледај, гдје је копље царево и чаша за воду што му бјеше чело главе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Тада Саул позна глас Давидов, и рече: је ли то твој глас, сине Давиде? А Давид рече: мој је глас, царе господару!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Још рече: зашто господар мој гони слугу својега? јер шта сам учинио? и како је зло у руци мојој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Зато сада царе господару мој, послушај ријечи слуге својега. Ако те Господ дражи на мене, нека му је угодан принос твој; ако ли синови човјечији, проклети су пред Господом, јер ме изагнаше данас да се не држим нашљедства Господњега, и рекоше: иди, служи туђим боговима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Али сада да не падне крв моја на земљу далеко од очију Господњих; јер цар Израиљев изиде да тражи буху једну, као кад ко гони јаребицу по планини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Тада рече Саул: згријешио сам; врати се, сине Давиде, нећу ти отселе чинити зла, кад ти данас драга би душа моја; ево, лудо сам радио и погријешио сам веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'А Давид одговори и рече: ево копља царева; нека дође који од момака и нека га узме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'А Господ ће платити свакоме по правди његовој и по вјери његовој. Јер те бјеше предао Господ данас у руке моје, али не хтјех дигнути руке своје на помазаника Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'И зато, ево, како је данас мени драга била душа твоја, тако нека буде драга моја душа пред Господом, и нека ме избави из сваке невоље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'А Саул рече Давиду: да си благословен, сине мој Давиде! извршићеш и надвладаћеш. Тада Давид отиде својим путем, а Саул се врати у своје мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Али Давид рече у срцу својем: погинућу кадгод од руке Саулове; нема боље за ме него да побјегнем у земљу Филистејску, те ће ме се Саул оканити и неће ме више тражити по крајевима Израиљевијем; тако ћу се избавити из руку његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Тада се подиже Давид и отиде са шест стотина људи који бијаху с њим к Ахису сину Моахову цару Гатском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'И оста Давид код Ахиса у Гату и људи његови, сваки са својом породицом, Давид са двије жене своје, Ахиноамом из Језраела и Авигејом из Кармила женом Наваловом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'И кад јавише Саулу да је Давид утекао у Гат, преста га тражити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'А Давид рече Ахису: ако сам нашао милост пред тобом, нека ми даду мјесто у ком граду ове земље, да сједим ондје, јер зашто да сједи слуга твој с тобом у царском граду?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'И даде му Ахис онога дана Сиклаг. Зато Сиклаг припада царевима Јудинијем до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'И оста Давид у земљи Филистејској годину и четири мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'И излажаше Давид са својим људима, и удараше на Гесуреје и Герзеје и на Амалике; јер ти народи живљаху од старине у оној земљи од Сура па до земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'И пустошаше Давид ону земљу не остављајући у животу ни човјека ни жене, и отимаше овце и волове и магарце и камиле и рухо, и враћајући се долажаше к Ахису.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'И Ахис питаше: гдје сте данас ударали? А Давид говораше: на јужну страну Јудину, и на јужну страну Јерамеилску, и на јужну страну Кенејску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Али не остављаше Давид у животу ни човјека ни жене да доведе у Гат говорећи: да нас не туже говорећи: тако је урадио Давид. И таки му бијаше обичај за све вријеме докле бијаше у земљи Филистејској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'И Ахис вјероваше Давиду, и говораше: баш се омразио с народом својим Израиљем; зато ће ми бити слуга довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'И у оно вријеме скупише Филистеји војску своју да завојште на Израиља; и рече Ахис Давиду: знај да ћеш ићи са мном на војску ти и твоји људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'А Давид рече Ахису: сад ћеш видјети шта ће учинити твој слуга. А Ахис рече Давиду: зато ћу те поставити да си чувар главе моје свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'А Самуило бијаше умро, и плака за њим сав Израиљ, и погребоше га у Рами, у његову граду. И Саул бијаше истријебио из земље гатаре и врачаре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'И Филистеји скупивши се дођоше и стадоше у око код Сунима; скупи и Саул све Израиљце, и стадоше у око код Гелвује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Саул пак видећи војску Филистејску уплаши се, и срце му уздрхта веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'И упита Саул Господа, али му Господ не одговори ни у сну ни преко Урима, ни преко пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'И Саул рече слугама својим: тражите ми жену с духом врачарским, да отидем к њој и упитам је. А слуге му рекоше: ево у Ендору има жена у којој је дух врачарски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Тада се Саул преруши обукав друге хаљине, и отиде са два човјека, и дође к оној жени ноћу; и он јој рече: хајде врачај ми духом врачарским, и дозови ми онога кога ти кажем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Али му жена рече: та ти знаш шта је учинио Саул и како је истријебио из земље гатаре и врачаре; зашто дакле мећеш замку души мојој да ме убијеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'А Саул јој се закле Господом говорећи: тако жив био Господ! неће ти бити ништа за то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Тада рече жена: кога да ти дозовем? А он рече: Самуила ми дозови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'А кад жена видје Самуила, повика иза гласа, и рече жена Саулу говорећи: зашто си ме преварио? та ти си Саул.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'А цар јој рече: не бој се; него шта си видјела? А жена рече Саулу: богове сам видјела гдје излазе из земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Он јој опет рече: какав је? Она му рече: стар човјек излази огрнут плаштем. Тада разумје Саул да је Самуило, и сави се лицем до земље и поклони се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'А Самуило рече Саулу: зашто си ме узнемирио и изазвао? Одговори Саул: у невољи сам великој, јер Филистеји завојштише на ме, а Бог је отступио од мене, и не одговори ми више ни преко пророка ни у сну, зато позвах тебе да ми кажеш шта ћу чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'А Самуило рече: па што мене питаш, кад је Господ отступио од тебе и постао ти непријатељ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Господ је учинио како је казао преко мене; јер је Господ истргао царство из твоје руке и дао га ближњему твојему Давиду;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Јер нијеси послушао гласа Господњега, нити си извршио жестока гњева његова на Амалику; зато ти је данас Господ то учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'И Господ ће предати и Израиља с тобом у руке Филистејима; те ћеш сјутра ти и синови твоји бити код мене; и око Израиљски предаће Господ у руке Филистејима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'А Саул уједанпут паде на земљу колико је дуг, јер се врло уплаши од ријечи Самуиловијех, и не бјеше снаге у њему, јер не бјеше ништа јео вас дан и сву ноћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Тада жена приступи к Саулу, и видећи га врло уплашена рече му: ево, слушкиња те је твоја послушала, и нијесам за живот свој марила да бих те послушала што си ми казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Него сада и ти послушај шта ће ти слушкиња твоја казати: поставићу ти мало хљеба, те једи да се окријепиш да се можеш вратити својим путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'А он не хтје, и рече: нећу јести. Али навалише на њ слуге његове и жена, те их послуша, и уставши са земље сједе на постељу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'А жена имаше код куће теле угојено, и брже га закла, и узе брашна те умијеси и испече хљебове пријесне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Потом постави Саулу и слугама његовијем, те једоше. А послије усташе и отидоше исте ноћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'А Филистеји скупише сву војску своју код Афека, а Израиљ стаде у око код извора у Језраелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'И кнезови Филистејски иђаху са стотинама и тисућама; а Давид и његови људи иђаху најпослије с Ахисом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'И рекоше кнезови Филистејски: што ће ти Јевреји? А Ахис рече кнезовима Филистејским: није ли ово Давид слуга цара Израиљскога Саула, који је код мене толико времена, толико година, и не нађох на њему ништа откако је добјегао до овога дана?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Али се расрдише на њ кнезови Филистејски и рекоше му кнезови Филистејски: пошљи натраг тога човјека, нека се врати у своје мјесто гдје си га поставио, и нека не иде с нама у бој, да се не окрене на нас у боју; јер чим би се опет умилио господару својему ако не главама овијех људи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Није ли то Давид о којем се пјевало играјући и говорило: згуби Саул своју тисућу, али Давид својих десет тисућа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Тада Ахис дозва Давида, и рече му: тако био жив Господ, ти си поштен, и мило ми је да ходиш са мном у бој; јер не нађох никакога зла на теби откако си дошао до овога дана; али нијеси по вољи кнезовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Него врати се и иди с миром да не учиниш што што не би било мило кнезовима Филистејским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'А Давид рече Ахису: Али шта сам учинио? шта ли си нашао на слузи својем откако сам код тебе до овога дана, да не идем да се бијем с непријатељима господара својега цара?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'А Ахис одговарајући рече Давиду: знам; доиста си ми мио као анђео Божји; али кнезови Филистејски рекоше: нека не иде с нама у бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Него устани сјутра рано са слугама господара својега које су дошле с тобом; устаните рано чим сване, па идите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'И урани Давид и људи његови, и отиде рано, и врати се у земљу Филистејску; а Филистеји отидоше у Језраел.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'И трећи дан дође Давид са својим људима у Сиклаг, а Амалици бијаху ударили на јужну страну и на Сиклаг, и развалили Сиклаг и огњем га спалили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'И бјеху заробили женскиње које бјеше ондје, и мало и велико; али не бјеху убили никога, него их бјеху одвели и отишли својим путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'И кад Давид дође са својим људима у град, а то град спаљен огњем, и жене њихове и синови и кћери њихове заробљене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'И подиже Давид и народ који бијаше с њим глас свој, и плакаше докле већ не могоше плакати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'И обје жене Давидове заробише се, Ахиноама из Језраела и Авигеја из Кармила жена Навалова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'И Давид бјеше на муци великој, јер народ говораше да га заспу камењем; јер жалостан бјеше сав народ, сваки за синовима својим и за кћерима својим; али се Давид охрабри у Господу Богу својем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'И рече Давид Авијатару свештенику сину Ахимелехову: узми оплећак за ме. И узе Авијатар оплећак за Давида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'И упита Давид Господа говорећи: хоћу ли потјерати ту чету? хоћу ли је стигнути? А Господ му рече: потјерај, јер ћеш зацијело стигнути и избавићеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'И пође Давид са шест стотина људи што бијаху с њим, и дођоше до потока Восора; и ондје осташе једни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'А Давид са четири стотине људи потјера даље, а двјеста људи оста, који сусташе те не могоше пријећи преко потока Восора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'И нађоше једнога Мисирца у пољу, и доведоше га к Давиду, и дадоше му хљеба да једе и воде да пије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'И дадоше му груду смокава и два грозда суха. И поједавши опорави се, јер три дана и три ноћи не бјеше ништа јео нити воде пио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Тада му рече Давид: чији си ти? и одакле си? А он рече: ја сам родом Мисирац, слуга једнога Амалика, а господар ме остави, јер се разбољех прије три дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Ударисмо на јужну страну Херетејску и на Јудину и на јужну страну Халевову, и Сиклаг спалисмо огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'А Давид му рече: би ли ме могао одвести к тој чети? А он рече: закуни ми се Богом да ме нећеш погубити ни издати у руке мојему господару, па ћу те одвести к тој чети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'И одведе га; и гле, они се бијаху раширили по свој земљи оној једући и пијући и веселећи се великим плијеном који заплијенише из земље Филистејске и из земље Јудине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'И Давид их би од вечера до вечера другога дана, те нико не утече, осим четири стотине младића, који сједавши на камиле побјегоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'И тако избави Давид све што бијаху узели Амалици, и обје жене своје избави Давид.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'И ништа не изгубише, ни мало ни велико, ни синове ни кћери, ни што од плијена и од свега што им бијаху узели; све поврати Давид.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Такођер узе Давид и остале све овце и волове, које гонећи пред својом стоком говораху: ово је плијен Давидов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'И кад се врати Давид к онијем двјеста људи који бјеху сустали те не могаше ићи за Давидом, и које остави на потоку Восору, изидоше на сусрет Давиду и народу који бијаше с њим. И Давид приступивши к народу поздрави их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Тада проговорише сви зли и неваљали људи између онијех који су ишли с Давидом, и рекоше: што нијесу ишли с нама, зато да им не дамо од плијена који избависмо, него сваки жену своју и синове своје нека узму, па нек иду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Али Давид рече: немојте тако чинити, браћо моја, с онијем што нам је дао Господ који нас је сачувао и дао нам у руке чету која бјеше изашла на нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'И ко ће вас послушати у томе? јер какав је дио ономе који иде у бој таки је и ономе који остане код пртљага; једнако треба да подијеле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Тако би од тога дана унапредак, и то поста уредба и закон у Израиљу до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'И кад дође Давид у Сиклаг, посла он плијена старјешинама Јудинијем, пријатељима својим, говорећи: ево вам дар од плијена непријатеља Господњих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Онима у Ветиљу, и онима у Рамоту на југу, и онима у Јатиру,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'И онима у Ароиру, и онима у Сифмоту, и онима у Естемоји,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'И онима у Рахалу, и онима у градовима Јерамеилским, и онима у градовима Кенејским,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'И онима у Орми, и онима у Хор-Асану, и онима у Атаху,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'И онима у Хеврону и по свијем мјестима у која је долазио Давид с људима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'А Филистеји се побише с Израиљцима, и побјегоше Израиљци испред Филистеја, и падаху мртви на гори Гелвуји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'И стигоше Филистеји Саула и синове његове; и погубише Филистеји Јонатана и Авинадава и Мелхи-Сува, синове Саулове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'И бој поста жешћи око Саула, и нађоше га стријелци, и он се врло уплаши од стријелаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'И рече Саул момку који му ношаше оружје: извади мач свој и прободи ме, да не дођу ти необрезани и прободу ме и наругају ми се. Али не хтје момак што му ношаше оружје, јер га бјеше врло страх. Тада Саул узе мач, и баци се на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'А кад момак који ношаше оружје видје Саула мртва, баци се и он на свој мач и умрије с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Тако погибе Саул и три сина његова и момак који му ношаше оружје и сви људи његови заједно онога дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'А Израиљци који бијаху с ову страну потока и с ову страну Јордана кад видјеше гдје Израиљци побјегоше и гдје погибе Саул и његови синови, оставише градове и побјегоше, те дођоше Филистеји и осташе у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'А сјутрадан дођоше Филистеји да свлаче мртве; и нађоше Саула и три сина његова гдје леже на гори Гелвуји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'И отсјекоше му главу, и скидоше оружје с њега, и послаше у земљу Филистејску на све стране да се објави у кући њиховијех лажнијех богова и по народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'И оставише оружје његово у кући Астаротиној, а тијело његово објесише на зид Вет-сански.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'А чуше становници у Јавису Галадову шта учинише Филистеји од Саула.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'И подигоше се сви људи храбри, и ишавши сву ноћ скидоше тијело Саулово и тјелеса синова његовијех са зида Вет-санскога, па се вратише у Јавис, и ондје их спалише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'И узеше кости њихове и погребоше их под дрветом у Јавису, и постише седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'А по смрти Сауловој, кад се Давид врати побивши Амалике и оста у Сиклагу два дана,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Трећега дана, гле, дође један из војске Саулове раздртијех хаљина и главе посуте прахом; и дошав к Давиду паде на земљу и поклони се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'И рече му Давид: откуда идеш? А он му рече: из окола Израиљскога утекох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'А Давид му рече: шта би? кажи ми. А он рече: народ побјеже из боја; и много народа паде и изгибе, погибе и Саул и син му Јонатан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'А Давид рече момку који му донесе глас: како знаш да је погинуо и син му Јонатан?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'А момак који му донесе глас рече: случајно дођох на гору Гелвују, а то се Саул наслонио на копље своје, кола и коњици приближаваху се к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'А он обазревши се натраг угледа ме, па ме викну, а ја му рекох: ево ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'А он ми рече: ко си? А ја му рекох: Амалик сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'А он ми рече: приступи к мени убиј ме; јер ме обузеше муке, а још је сасвијем душа у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'И приступих к њему и убих га, јер сам знао да неће остати жив пошто паде; и узех вијенац царски који му бјеше на глави и гривну која му бјеше на руци, и ево донесох господару својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Тада Давид зграби хаљине на себи и раздрије их; тако и сви људи који бијаху с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'И ридаше и плакаше, и постише до вечери за Саулом и за Јонатаном сином његовијем и за народом Господњим и за домом Израиљевијем што изгибоше од мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'И рече Давид момку који му донесе глас: одакле си? А он рече: ја сам син једнога дошљака Амалика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Рече му Давид: како те није било страх подићи руку своју и убити помазаника Господњега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'И дозва Давид једнога између момака својих и рече: ходи, погуби га. А он га удари, те умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'И рече му Давид: крв твоја на твоју главу; јер твоја уста свједочише на те говорећи: ја сам убио помазаника Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Тада Давид нарица овако за Саулом и за Јонатаном сином његовијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'И изговори, да би се учили синови Јудини луку, и ето је написано у књизи истинитога:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Дико Израиљева! на твојим висинама побијени су; како падоше јунаци?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Не казујте у Гату, и не разглашујте по улицама Аскалонским, да се не веселе кћери Филистејске и да не играју кћери необрезанијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Горе Гелвујске! не падала роса ни дажд на вас, и не родило поље за принос, јер је ту бачен штит са јунака, штит Саулов, као да није помазан уљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Без крви побијенијех и без масти од јунака није се враћао лук Јонатанов, нити је мач Саулов долазио натраг празан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Саул и Јонатан, мили и драги за живота, ни за смрти се не раставише; лакши од орлова бијаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Кћери Израиљеве! плачите за Саулом, који вас је облачио у скерлет лијепо, и китио вас златнијем закладима по хаљинама вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Како падоше јунаци у боју! Јонатан како погибе на твојим висинама!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Жао ми је за тобом, брате Јонатане; био си ми мио врло; већа ми је била љубав твоја од љубави женске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Како падоше јунаци, и пропаде оружје убојито!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'А послије тога Давид упита Господа говорећи: хоћу ли отићи у који град Јудин? А Господ му рече: отиди. А Давид рече: у који да отидем? Рече: Хеврон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'И Давид отиде онамо са двије жене своје, Ахиноамом из Језраела и Авигејом која прије бјеше жена Навала из Кармила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'И људе који бијаху с њим одведе Давид, све с породицама њиховијем, и настанише се по градовима Хевронским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'И дођоше људи од Јуде, и помазаше ондје Давида за цара над домом Јудинијем. И јавише Давиду говорећи: људи из Јависа Галадова погребоше Саула.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'И Давид посла посланике к људима у Јавису Галадову, и рече им: да сте благословени Господу што учинисте милост господару својему, Саулу и погребосте га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Зато да учини Господ вама милост и вјеру; а ја ћу вам учинити добро, што сте то учинили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'И нека вам се укријепе руке и будите храбри; јер Саул господар ваш погибе, а дом Јудин помаза мене за цара над собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Али Авенир син Ниров војвода Саулов узе Исвостеја сина Саулова, и одведе га у Маханајим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'И зацари га над Галадом и над Асуром и Језраелом и Јефремом и Венијамином и над свијем Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Четрдесет година бјеше Исвостеју сину Саулову кад поче царовати над Израиљем; и царова двије године. Само дом Јудин држаше се Давида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'А Давид царова у Хеврону над домом Јудинијем седам година и шест мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Потом изиде Авенир син Ниров и слуге Исвостеја сина Саулова из Маханајима у Гаваон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Такође и Јоав син Серујин и слуге Давидове изидоше и сретоше се с њима код језера Гаваонскога, и стадоше један с једне стране а други с друге стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Тада рече Авенир Јоаву: нека устану момци и нека се проиграју пред нама. И рече Јоав: нека устану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'И усташе, и изидоше на број: дванаест од Венијамина са стране Исвостеја сина Саулова, и дванаест између слуга Давидовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'И ухватише један другога за главу, и тисну један другому мач свој у бок, и попадаше заједно. Отуда се прозва оно мјесто Халкат-Асурим код Гаваона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'И би жесток бој онога дана; и слуге Давидове разбише Авенира и Израиљце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'А ондје бијаху три сина Серујина: Јоав и Ависај и Асаило. А Асаило бијаше лак на ногу као срна у пољу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'И потјера Асаило Авенира, и не сврну ни надесно ни налијево иза Авенира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'И Авенир обазре се натраг и рече: јеси ли ти, Асаило? А он рече: ја сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'А Авенир му рече: сврни надесно или налијево, и узми једнога од тијех момака, и скини одору с њега. Али не хтје Асаило сврнути иза њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'И Авенир опет рече Асаилу: отступи од мене; зашто да те саставим са земљом? и како бих смео погледати у Јоава брата твојега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Али он не хтје отступити; и Авенир га удари копљем под пето ребро, и изађе му копље на леђа, те он паде ондје и умрије на мјесто. И ко год дође на оно мјесто гдје паде и погибе Асаило, устављаше се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Али Јоав и Ависај потјераше Авенира, и сунце зађе кад дођоше до брда Аме, која је према Гији на путу у пустињу Гаваонску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'И скупише се синови Венијаминови за Авениром, те се начини чета, и стадоше на врх једнога брда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'И Авенир викну Јоава и рече: хоће ли мач прождирати довијека? не знаш ли да јади бивају напошљетку? зашто већ не кажеш народу да се прођу браће своје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'А Јоав рече: тако жив био Бог, да нијеси казао, народ би још јутрос отишао, ниједан не би тјерао брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Тада затруби Јоав у трубу, и устави се сав народ и престаше тјерати Израиља, и не бише се више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'И тако Авенир и људи његови идоше преко поља цијелу ону ноћ, и пријеђоше преко Јордана, и прошавши сав Витрон дођоше у Маханајим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'А Јоав се врати од Авенира, и кад скупи сав народ, не бјеше од слуга Давидовијех деветнаест људи и Асаила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Али слуге Давидове побише синова Венијаминовијех, људи Авенировијех, три стотине и шездесет људи, који изгибоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'А Асаила узеше и погребоше у гробу оца његова који бијаше у Витлејему. И Јоав и људи његови идоше сву ноћ, и освануше у Хеврону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'И дуго бијаше рат између дома Саулова и дома Давидова; али Давид све већма јачаше а дом Саулов постајаше све слабији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'И Давиду се родише синови у Хеврону: првенац му бјеше Амнон од Ахиноаме Језраељанке;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Други бјеше Хилеав од Авигеје жене Навала Кармилца; трећи Авесалом син Махе кћери Талмаја цара Гесурскога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'Четврти Адонија син Агитин; и пети Сефатија син Авиталин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'И шести Итрам од Егле жене Давидове. Ти се родише Давиду у Хеврону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'И док бијаше рат између дома Саулова и дома Давидова, Авенир брањаше дом Саулов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'А Саул имаше иночу по имену Ресфу кћер Ајину; и Исвостеј рече Авениру: зашто си спавао код иноче оца мојега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'И Авенир се разгњеви на ријечи Исвостејеве и рече: јесам ли ја пасја глава, који сада чиним на Јуди милост дому Саула оца твојега и браћи његовој и пријатељима његовијем, и нијесам те пустио у руке Давидове, те данас тражиш на мени зло ради те жене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Тако нека учини Бог Авениру, и тако нека дода, ако не учиним Давиду како му се Господ заклео,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'Да се пренесе ово царство од дома Саулова, и да се утврди пријесто Давидов над Израиљем и над Јудом, од Дана до Вирсавеје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'И он не може више ништа одговорити Авениру, јер га се бојаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'И Авенир посла посланике к Давиду од себе и поручи: чија је земља? И поручи му: учини вјеру са мном, и ево рука ће моја бити с тобом, да обратим к теби свега Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'А он одговори: добро; ја ћу учинити вјеру с тобом; али једно иштем од тебе, и то: да не видиш лица мојега ако ми прво не доведеш Михалу кћер Саулову, кад дођеш да видиш лице моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'И посла Давид посланике к Исвостеју сину Саулову, и поручи му: дај ми жену моју Михалу, коју испросих за сто окрајака Филистејских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'И Исвостеј посла те је узе од мужа, од Фалтила, сина Лаисова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'А муж њезин пође с њом, и једнако плакаше за њом до Ваурима. Тада му рече Авенир: иди, врати се натраг. И он се врати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Потом Авенир говори старјешинама Израиљским, и рече им: пређе тражисте Давида да буде цар над вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Ето сада учините; јер је Господ рекао за Давида говорећи: преко Давида слуге својега избавићу народ свој Израиља из руку Филистејских и из руку свих непријатеља њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Тако говори Авенир и синовима Венијаминовијем. Потом отиде Авенир и у Хеврон да каже Давиду све што за добро нађе Израиљ и сав дом Венијаминов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'И кад дође Авенир к Давиду у Хеврон и с њим двадесет људи, учини Давид гозбу Авениру и људима који бијаху с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'И рече Авенир Давиду: да устанем и идем да скупим к цару господару својему сав народ Израиљев да учине вјеру с тобом, па да царујеш како ти душа жели. И Давид отпусти Авенира да иде с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'А гле, слуге Давидове враћаху се с Јоавом из боја, и тјераху са собом велик плијен; а Авенир већ не бјеше код Давида у Хеврону, јер га отпусти, те отиде с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Јоав дакле и сва војска што бјеше с њим дођоше онамо; и јавише Јоаву говорећи: Авенир син Ниров долазио је к цару, и он га отпусти те отиде с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'И Јоав отиде к цару и рече: шта учини? Гле, Авенир је долазио к теби; зашто га пусти те отиде?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Познајеш ли Авенира сина Нирова? долазио је да те превари, да види куда ходиш и да дозна све што радиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Потом отишав Јоав од Давида посла људе за Авениром да га врате од студенца Сире, а Давид не знадијаше за то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'И кад се врати Авенир у Хеврон, одведе га Јоав на страну под врата као да говори с њим насамо; ондје га удари под пето ребро, те умрије за крв Асаила брата његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'А кад Давид послије то чу, рече: ја нијесам крив ни царство моје пред Господом довијека за крв Авенира сина Нирова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Нека падне на главу Јоавову и на сав дом оца његова; и нека дом Јоавов не буде никад без човјека болна од течења или губава или који иде о штапу или који падне од мача или који нема хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Тако Јоав и Ависај брат његов убише Авенира што он погуби Асаила брата њихова код Гаваона у боју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'И рече Давид Јоаву и свему народу који бијаше с њим: раздерите хаљине своје и припашите костријет, и плачите за Авениром. И цар Давид иђаше за носилима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'А кад погребоше Авенира у Хеврону, цар подиже глас свој и плака на гробу Авенирову; плака и сав народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'И наричући за Авениром рече: умрије ли Авенир како умире безумник?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Руке твоје не бише везане, нити ноге твоје у оков оковане; пао си као што се пада од неваљалијех људи. Тада још већма плака за њим сав народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'И дође сав народ нудећи Давида да једе што, док још бијаше дан; али се Давид закле и рече: Бог нека ми учини тако, и тако нека дода, ако окусим хљеба или што друго док не зађе сунце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'И сав народ чу то, и би им по вољи; што год чињаше цар, бјеше по вољи свему народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'И позна сав народ и сав Израиљ у онај дан да није било од цара што погибе Авенир син Ниров.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'И цар рече слугама својим: не знате ли да је војвода и то велики погинуо данас у Израиљу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Али ја сам сада још слаб, ако и јесам помазани цар; а ови људи, синови Серујини, врло су ми силни. Нека Господ плати ономе који чини зло према злоћи његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'А кад чу син Саулов да је погинуо Авенир у Хеврону, клонуше му руке, и сав се Израиљ смете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'А имаше син Саулов двије војводе над четама; једном бјеше име Вана, другом бјеше име Рихав, синови Римона Вироћанина, од синова Венијаминовијех; јер се и Вирот бројаше Венијамину;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'А Вироћани бијаху побјегли у Гитајим, гдје осташе као дошљаци до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'И имаше Јонатан син Саулов сина хрома на ногу, којему бијаше пет година кад дође глас о смрти Сауловој и Јонатановој из Језраела, те га узе дадиља његова и побјеже, и кад брзо бјежаше, он паде и охрону; а име му бијаше Мефивостеј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'И пођоше синови Римона Вироћанина, Рихав и Вана, и дођоше у подне у кућу Исвостејеву; а он почиваше у подне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'И уђоше у кућу као да узму пшенице, и прободоше га под пето ребро Рихав и Вана, и побјегоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Кад уђоше у кућу, он лежаше на постељи својој у клијети гдје спаваше, те га прободоше и убише, и отсјекоше му главу и узеше је, па отидоше путем преко поља цијелу ону ноћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'И донесоше главу Исвостејеву Давиду у Хеврон, и рекоше цару: ево главе Исвостеја сина Саулова, непријатеља твојега, који је тражио душу твоју; и Господ освети данас цара господара мојега од Саула и сјемена његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Али Давид одговарајући Рихаву и Вани брату његову, синовима Римона Вироћанина, рече им: тако да је жив Господ, који је избавио душу моју из сваке невоље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Кад онога који ми јави говорећи: гле, погибе Саул, и мишљаше да ће ми јавити добре гласе, ухватих и убих у Сиклагу, и то му би од мене дар за гласе његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Акамоли људе безбожне, који убише човјека права, у кући његовој, на постељи његовој! нећу ли искати крви његове из ваших руку, и вас истријебити са земље?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'И заповједи Давид момцима својим, те их погубише, и отсјекоше им руке и ноге, и објесише код језера Хевронскога; а главу Исвостејеву узеше и погребоше у гробу Авенирову у Хеврону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Тада дођоше сва племена Израиљева к Давиду у Хеврон, и рекоше му говорећи: ево ми смо кост твоја и тијело твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'И прије, док Саул бијаше цар над нама, ти си одводио и доводио Израиља; и Господ ти је рекао: ти ћеш пасти народ мој Израиља и ти ћеш бити вођ Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Тако дођоше све старјешине Израиљеве к цару у Хеврон, и учини с њима цар Давид вјеру у Хеврону пред Господом; и помазаше Давида за цара над Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Тридесет година бијаше Давиду кад се зацари, и царова четрдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'У Хеврону царова над Јудом седам година и шест мјесеца; а у Јерусалиму царова тридесет и три године над свијем Израиљем и Јудом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'А цар отиде са својим људима у Јерусалим на Јевусеје, који живљаху у оној земљи. И они рекоше Давиду говорећи: нећеш ући овамо док не узмеш слијепе и хроме, хотећи казати: неће ући овамо Давид.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Али Давид узе кулу Сион, то је град Давидов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Јер рече Давид у онај дан: ко год побије Јевусеје и дође до јаза, и до слијепијех и хромијех, на које мрзи душа Давидова, биће војвода. Зато се каже: слијепи и хроми да не улазе у ову кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'И сједе Давид у кули, и назва је градом Давидовијем: и погради је Давид унаоколо од Милона и унутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'И Давид једнако напредоваше, јер Господ Бог над војскама бјеше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'И Хирам цар Тирски посла посланике к Давиду, и кедровијех дрва и дрводјеља и каменара, и саградише кућу Давиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'И разумје Давид да га је Господ утврдио за цара над Израиљем, и да је узвисио царство његово ради народа својега Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'И узе Давид још иноча и жена из Јерусалима, пошто дође из Хеврона; и роди се Давиду још синова и кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'И ово су имена онијех који му се родише у Јерусалиму:Самуја и Совав и Натан и Соломун,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'И Јевар и Елисуја и Нафиг и Јафија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'И Елисама и Елијада и Елифалет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'А Филистеји чувши да су помазали Давида за цара над Израиљем, изидоше сви Филистеји да траже Давида; а Давид чувши то, отиде у кулу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'И Филистеји дошавши раширише се по долини Рафајској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'Тада Давид упита Господа говорећи: хоћу ли изаћи на Филистеје? Хоћеш ли их дати у моје руке? А Господ рече Давиду: изађи; доиста ћу дати Филистеје у твоје руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Тада Давид дође у Вал-Ферасим, и поби их ондје, и рече: продрије Господ непријатеље моје преда мном као кад вода продире. Отуда се прозва оно мјесто Вал-Ферасим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'И оставише ондје лажне богове своје; а Давид и људи његови однесоше их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'И опет наново дођоше Филистеји, и раширише се у долини Рафајској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'И Давид упита Господа, који рече: не иди пред њих, него им зађи за леђа, па удари на њих према дудовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Па кад чујеш да зашушти по врховима од дудова, онда се крени, јер ће онда поћи Господ пред тобом да побије војску Филистејску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'И Давид учини тако како му заповједи Господ, и поби Филистеје од Гаваје до Гезера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Послије скупи опет Давид све људе изабране из Израиља, тридесет тисућа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Па се подиже Давид и сав народ што бијаше с њим и отиде из Вале Јудине да пренесе отуда ковчег Божји, код којега се призивље име, име Господа над војскама, који сједи на херувимима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'И метнуше ковчег Божји на нова кола, и повезоше га из куће Авинадавове, која бијаше на брду; а Уза и Ахијо синови Авинадавови управљаху новијем колима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'И одвезоше ковчег Божји из куће Авинадавове, која бијаше на брду, и Ахијо иђаше пред ковчегом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'А Давид и сав дом Израиљев удараху пред Господом у свакојаке справе од дрвета кедрова, у гусле, у псалтире, у бубње, у свирале и у кимвале.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'А кад дођоше до гумна Нахонова, Уза се маши за ковчег Божји и прихвати га, јер волови потегоше на страну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'И Господ се разгњеви на Узу, и удари га Бог ондје за ту непажњу, те умрије ондје код ковчега Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'И ожалости се Давид што Господ уби Узу. Зато се прозва оно мјесто Фарес-Уза до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'И уплаши се Давид од Господа у онај дан, и рече: како ће доћи к мени ковчег Господњи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'И не хтје Давид одвести ковчега Господњега к себи у град Давидов; него га склони Давид у кућу Овид-Едома Гетејина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'И оста ковчег Господњи у кући Овид-Едома Гетејина три мјесеца, и благослови Господ Овид-Едома и сав дом његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'И јавише цару Давиду говорећи: Господ благослови дом Овид-Едомов и све што има ради ковчега Божијега. Тада отиде Давид, и пренесе ковчег Божји из куће Овид-Едомове у град Давидов с весељем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'И кад они који ношаху ковчег Господњи поступише шест корака, принесе на жртву вола и дебела овна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'И Давид играше из све снаге пред Господом, и бјеше огрнут оплећком ланенијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Тако Давид и сав дом Израиљев ношаху ковчег Господњи подвикујући и трубећи у трубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'А кад ковчег Господњи улажаше у град Давидов, Михала кћи Саулова гледајући с прозора видје цара Давида гдје скаче и игра пред Господом, и подругну му се у срцу својем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'А кад донесоше ковчег Господњи, намјестише га на његово мјесто у шатору који му разапе Давид. И принесе Давид жртве захвалне пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Потом принесавши Давид жртве паљенице и жртве захвалне благослови народ у име Господа над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'И раздаде међу сав народ, међу све мноштво Израиљево, и људима и женама, свакоме по један хљеб и комад меса и жбан вина. Потом отиде народ, свак својој кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'И Давид се врати да благослови свој дом; а Михала кћи Саулова изиде на сусрет Давиду, и рече: како је славан био данас цар Израиљев, кад се данас откривао пред слушкињама слуга својих, као што се откривају никаки људи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'А Давид рече Михали: пред Господом, који ме је изабрао преко оца твојега и преко свега дома његова, те ми заповједио да будем вођ народу Господњему, Израиљу, играо сам, и играћу пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'И још ћу се већма понизити, и још ћу мањи себи бити; и опет ћу бити славан пред слушкињама, за које говориш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'И Михала кћи Саулова не има порода до смрти своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'А кад цар сјеђаше код куће своје, и Господ му даде мир свуда унаоколо од свијех непријатеља његовијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Рече цар Натану пророку: види, ја стојим у кући од кедрова дрвета, а ковчег Божји стоји под завјесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'А Натан рече цару: шта ти је год у срцу, иди, чини, јер је Господ с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Али ону ноћ дође ријеч Господња к Натану говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Иди и реци слузи мојему Давиду: овако вели Господ: ти ли ћеш ми начинити кућу да у њој наставам?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Кад нијесам наставао у кући од кад изведох синове Израиљеве из Мисира до данас, него сам ходио у шатору и у наслону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Куда сам год ходио са свијем синовима Израиљевим, јесам ли једну ријеч рекао коме од судија Израиљевијех, којима заповиједах да пасу народ мој Израиља, и казао: зашто ми не начините куће од кедра?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Овако дакле реци Давиду слузи мојему: овако вели Господ над војскама: ја те узех од тора, од оваца, да будеш вођ народу мојему, Израиљу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'И бјех с тобом куда си год ходио, и истријебих све непријатеље твоје испред тебе, и стекох ти име велико, као што је име великијех људи који су на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'И одредићу мјесто народу својему Израиљу, и посадићу га, те ће наставати у свом мјесту, и неће се више претресати, нити ће их више мучити неправедници као прије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'И од онога дана кад поставих судије над народом својим Израиљем; и смирићу те од свијех непријатеља твојих. Јоште ти јавља Господ да ће ти Господ начинити кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Кад се наврше дани твоји, и починеш код отаца својих, подигнућу сјеме твоје након тебе, које ће изаћи из утробе твоје, и утврдићу царство његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Он ће сазидати дом имену мојему, и утврдићу пријесто царства његова довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Ја ћу му бити отац, и он ће ми бити син: ако учини што зло, караћу га прутом људским и ударцима синова човјечијих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Али милост моја неће се уклонити од њега као што сам је уклонио од Саула, којега уклоних испред тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Него ће тврд бити дом твој и царство твоје довијека пред тобом, и пријесто ће твој стајати довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'По свијем овијем ријечима и по свој овој утвари каза Натан Давиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Тада дође цар Давид и стаде пред Господом, и рече: ко сам ја, Господе, Господе, и шта је мој дом, те си ме довео довде?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Па и то ти се још чини мало, Господе, Господе, него си говорио и за дом слуге својега на дуго времена. Је ли то закон човјечји, Господе, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Али шта ће јоште Давид да ти говори? та ти знаш слугу својега, Господе, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Ради ријечи своје и по срцу својему учинио си све ове велике ствари обзнањујући их слузи својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Зато си велик, Господе Боже, нема такога какав си ти; и нема Бога осим тебе, по свему што чусмо својим ушима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Јер који је народ на земљи као твој народ Израиљ? којега је ради Бог ишао да га искупи да му буде народ и да стече себи име и да вам учини велика и страшна дјела у земљи твојој, пред народом твојим, који си искупио себи из Мисира, од народа и богова њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Јер си утврдио себи народ свој Израиља да ти буде народ довијека; а ти си им, Господе, Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'И тако, Господе Боже, ријеч коју си обрекао слузи својему и дому његову, потврди засвагда, и учини како си рекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Нека се велича име твоје до вијека, да се говори: Господ је над војскама Бог над Израиљем; и дом слуге твојега Давида нека стоји тврдо пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Јер си ти, Господе над војскама, Боже Израиљев, јавио слузи својему говорећи: дом ћу сазидати теби. Зато слуга твој нађе у срцу својем да ти се помоли овом молитвом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Тако, Господе, Господе, ти си Бог, и ријечи су твоје истина; ти си ово добро обрекао слузи својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Буди дакле вољан и благослови дом слуге својега да буде довијека пред тобом; јер си ти Господе, рекао, и твојим ће благословом бити благословен дом слуге твојега довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Послије тога разби Давид Филистеје, и покори их, и узе Давид Метег-Аму из руку Филистејских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Разби и Моавце, и измјери их ужем поваљавши их по земљи, и измјери их два ужа да се погубе а једно уже да се оставе у животу. И Моавци посташе слуге Давидове, и плаћаху му данак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Давид разби и Адад-Езера сина Реовова цара Совскога, изашав да рашири власт своју до ријеке Ефрата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'И зароби их Давид тисућу и седам стотина коњаника и двадесет тисућа пјешака, и подреза Давид жиле свијем коњма колским, само остави за сто кола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'И бијаху дошли Сирци из Дамаска у помоћ Адад-Езеру цару Совском, и Давид поби двадесет и двије тисуће Сираца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'И намјести Давид војску у Сирији што је под Дамаском, и Сирци посташе слуге Давидове плаћајући му данак. И Господ чуваше Давида куда год иђаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'И Давид узе златне штитове које имаху слуге Адад-Езерове, и донесе их у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'И из Ветаха и из Виротаја градова Адад-Езеровијех однесе цар Давид силну мјед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'А кад чу Тоја цар Ематски да је Давид побио сву војску Адад-Езерову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Посла Тоја Јорама сина својега к цару Давиду да га поздрави и да му честита што је војевао на Адад-Езера и убио га, јер Тоја имаше рат с Адад-Езером; и донесе Јорам заклада златнијех и сребрнијех и мједенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Па и то цар Давид посвети Господу са сребром и златом што бјеше посветио од свијех народа које покори,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'Од Сираца и од Моаваца и од синова Амоновијех и од Филистеја и од Амалика, и од плијена Адад-Езера сина Реовова цара Совскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'И Давид стече име кад се врати побив Сирце, осамнаест тисућа, у сланој долини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'И намјести војску по Идумеји, по свој Идумеји намјести војску, и сви Едомци посташе слуге Давидове. И Господ чуваше Давида куда год иђаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Тако царова Давид над свијем Израиљем, судећи и дајући правду свему народу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'И Јоав син Серујин бјеше над војском; а Јосафат син Ахилудов паметар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'А Садок син Ихитовов и Ахимелех син Авијатаров свештеници; а Сераја писар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'А Венаја син Јодајев бјеше над Херетејима и Фелетејима; а синови Давидови кнезови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'И рече Давид: има ли јоште ко да је остао од дома Саулова? да му учиним милост ради Јонатана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'А бијаше један слуга дома Саулова, по имену Сива; и дозваше га к Давиду. И рече му цар: јеси ли ти Сива? А он рече: ја сам, слуга твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'А цар рече: има ли јоште ко од дома Саулова да му учиним милост Божију? А Сива рече цару: још има син Јонатанов, хром на ногу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'И рече му цар: гдје је? А Сива рече цару: ено га у дому Махира сина Амилова у Лодевару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Тада посла цар Давид да га доведу из Лодевара из дома Махира сина Амилова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'А кад дође к Давиду Мефивостеј син Јонатана сина Саулова, паде на лице своје и поклони се. А Давид рече: Мефивостеју! А он рече: ево слуге твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'А Давид му рече: не бој се; јер ћу ти учинити милост Јонатана ради оца твојега, даћу ти натраг све њиве Саула оца твојега; а ти ћеш свагда јести за мојим столом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'А он се поклони и рече: ко сам ја слуга твој, те си погледао на мртва пса као што сам ја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'И цар дозва Сиву слугу Саулова, и рече му: што је год било Саулово и свега дома његова, дао сам сину твојега господара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Ради му дакле земљу ти и синови твоји и слуге твоје, и доноси да син господара твојега има хљеб да једе; али Мефивостеј син господара твојега јешће свагда за мојим столом. Сива пак имаше петнаест синова и двадесет слуга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'И рече Сива цару: како је цар господар мој заповједио слузи својему, све ће чинити слуга твој. Али Мефивостеј, рече цар, јешће за мојим столом као царски син.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'А Мефивостеј имаше малога сина, којему име бјеше Миха; а сви који живљаху у дому Сивину бијаху слуге Мефивостејеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'А Мефивостеј сјеђаше у Јерусалиму, јер свагда јеђаше за царевијем столом, а бјеше хром на обје ноге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'А послије тога умрије цар синова Амоновијех, и зацари се Анун син његов на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'И рече Давид: да учиним милост Ануну сину Насову, као што је отац његов мени учинио милост. И посла Давид да га потјеши за оцем преко слуга својих. И дођоше слуге Давидове у земљу синова Амоновијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'А кнезови синова Амоновијех рекоше Ануну господару својему: мислиш да је Давид зато послао људе да те потјеше, што је рад учинити част оцу твојему? а није зато послао Давид к теби слуге своје да промотри град и уходи, па послије да га раскопа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Тада Анун ухвати слуге Давидове, и обрија им браде до пола и отсијече им хаљине по поле, до задњице, и оправи их натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'А кад то јавише Давиду, он посла пред њих, јер људи бијаху грдно осрамоћени, и поручи им цар: сједите у Јерихону докле вам нарасте брада, па онда дођите натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Тада синови Амонови видећи гдје се омразише с Давидом, послаше синови Амонови, те најмише Сираца од Вет-Реова и Сираца од Сове двадесет тисућа пјешака, и у цара Махе тисућу људи, и од Ис-Това дванаест тисућа људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'А Давид кад то чу, посла Јоава са свом храбром војском својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'И Изидоше синови Амонови, и уврсташе се пред вратима, а Сирци из Сове и из Реова и људи из Ис-Това и из Махе бијаху за себе у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'И Јоав видећи намјештену војску према себи спријед и озад, узе одабране из све војске Израиљске, и намјести их према Сирцима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'А остали народ предаде Ависају брату својему да их намјести према синовима Амоновијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'И рече: ако Сирци буду јачи од мене, дођи ми у помоћ; ако ли синови Амонови буду јачи од тебе, ја ћу доћи теби у помоћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Буди храбар, и држимо се храбро за свој народ и за градове Бога својега; а Господ нека учини што му је по вољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Тада Јоав и народ који бјеше с њим примакоше се да ударе на Сирце, али они побјегоше испред њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'А синови Амонови видећи гдје побјегоше Сирци, побјегоше и они испред Ависаја, и уђоше у свој град. И врати се Јоав од синова Амоновијех, и дође у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Али Сирци кад видјеше гдје их надбише Израиљци, скупише се опет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'И Адад-Езер посла, те доведе Сирце испреко ријеке, који дођоше у Елам; а Совак војвода Адад-Езеров иђаше пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Кад то јавише Давиду, он скупи све Израиљце, и пријеђе преко Јордана и дође у Елам; и Сирци се намјестише против Давида и побише се с Давидом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Али побјегоше Сирци испред Израиља, и поби Давид Сираца седам стотина и четрдесет тисућа коњика; и Совака војводу њихова уби, те погибе ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'И кад видјеше сви цареви, слуге Адад-Езерове, да их разби Израиљ, учинише мир с Израиљем, и служаху им, и Сирци не смијаху више помагати синовима Амоновијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'А кад прође година, у вријеме кад цареви иду на војску, посла Давид Јоава и слуге своје с њим, и свега Израиља, те потираху синове Амонове, и опколише Раву; а Давид оста у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'И пред вече уста Давид с постеље своје, и ходајући по крову царскога двора угледа с крова жену гдје се мије, а жена бијаше врло лијепа на очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'И Давид посла да пропитају за жену и рекоше: није ли то Витсавеја кћи Елијамова жена Урије Хетејина?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'И Давид посла посланике да је доведу; и кад дође к њему, он леже с њом, а она се бјеше очистила од нечистоте своје; послије се врати својој кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'И затрудње жена, те посла и јави Давиду говорећи: трудна сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Тада Давид посла к Јоаву и поручи: пошљи ми Урију Хетејина. И посла Јоав Урију к Давиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'И кад Урија дође к њему, запита га Давид како је Јоав и како је народ и како иде рат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Потом рече Давид Урији: иди кући својој, и опери ноге своје. И Урија изиде из царева двора, а за њим изнесоше јело царско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Али Урија леже на вратима двора царева са свијем слугама господара својега, и не отиде кући својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'И јавише Давиду говорећи: Урија није отишао кући својој. А Давид рече Урији: нијеси ли дошао с пута? зашто не идеш кући својој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'А Урија рече Давиду: ковчег и Израиљ и Јуда стоје по шаторима, и Јоав господар мој и слуге господара мојега стоје у пољу, па како бих ја ушао у кућу своју да једем и пијем и спавам са женом својом? Тако ти био жив и тако била жива душа твоја, нећу то учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Тада рече Давид Урији: остани овдје још данас, па ћу те сјутра отпустити. Тако оста Урија у Јерусалиму онај дан и сјутрадан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'И позва га Давид да једе и пије с њим, те га опије. А увече отиде, те леже на постељу своју са слугама господара својега, а кући својој не отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'А ујутру написа Давид књигу Јоаву, и посла по Урији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'А у књизи писа и рече: намјестите Урију гдје је најжешћи бој, па се узмакните од њега да би га убили да погине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'И Јоав опколивши град намјести Урију на мјесто гдје је знао да су најхрабрији људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'И изидоше људи из града и побише се с Јудом. И погибе из народа неколико слуга Давидовијех; погибе и Урија Хетејин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Тада Јоав посла к Давиду, и јави му све што би у боју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'И заповједи гласнику говорећи: кад приповједиш цару све што је било у боју,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'Ако се разгњеви цар и рече ти: зашто сте ишли тако близу града да се бијете? зар нијесте знали како се стријеља с града?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Ко је убио Авимелеха сина Јерувесетова? није ли жена бацила на њ комад жрвња са зида, те погибе у Тевесу? зашто сте ишли близу зида? тада реци: погинуо је и слуга твој Урија Хетејин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'И отиде гласник, и дошавши јави Давиду све за што га је послао Јоав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'И рече гласник Давиду: бијаху јачи од нас, и изидоше у поље на нас, али их узбисмо до врата градских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'А стријелци стадоше стријељати на слуге твоје са зида, и погибе неколико слуга царевијех, тако и слуга твој Урија Хетејин погибе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Тада рече Давид гласнику: овако реци Јоаву: не буди зловољан за то; јер мач прождире сад овога сад онога; удри још јаче на град и раскопај га. Тако га охрабри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'А жена Уријина чувши да је погинуо муж њезин Урија, плака за мужем својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'А кад прође жалост, посла Давид и узе је у кућу своју, и она му поста жена, и роди му сина. Али не бјеше по вољи Господу што учини Давид.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'И посла Господ Натана к Давиду; и он дошав к њему рече му: у једном граду бијаху два човјека, један богат а други сиромах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Богати имаше оваца и говеда врло много;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'А сиромах немаше ништа до једну малу овчицу, коју бјеше купио, и храњаше је, те одрасте уза њ и уз дјецу његову, и јеђаше од његова залогаја, и из његове чаше пијаше, и на крилу му спаваше, и бијаше му као кћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'А дође путник к богатоме човјеку, а њему би жао узети из својих оваца или говеда да зготови путнику који дође к њему; него узе овцу онога сиромаха, и зготови је човјеку, који дође к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Тада се Давид врло разгњеви на онога човјека, и рече Натану: тако жив био Господ, заслужио је смрт онај који је то учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'И овцу нека плати учетворо, што је то учинио и није му жао било.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Тада рече Натан Давиду: ти си тај. Овако вели Господ Бог Израиљев: ја сам те помазао за цара над Израиљем, и ја сам те избавио из руку Сауловијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'И дао сам ти дом господара твојега, и жене господара твојега на крило твоје, дао сам ти дом Израиљев и Јудин; и ако је мало, додао бих ти то и то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Зашто си презрео ријеч Господњу чинећи што њему није по вољи? Урију Хетејина убио си мачем и узео си жену његову себи за жену, а њега си убио мачем синова Амоновијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Зато неће се одмаћи мач од дома твојега довијека, што си ме презрео и узео жену Урије Хетејина да ти буде жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Овако вели Господ: ево, ја ћу подигнути на те зло из дома твојега, и узећу жене твоје на твоје очи, и даћу их ближњему твојему, те ће спавати са женама твојим на видику свакому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Јер ти си учинио тајно, али ћу ја ово учинити пред свијем Израиљем и свакому на видику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Тада рече Давид Натану: сагријеших Господу. А Натан рече Давиду: и Господ је пронио гријех твој; нећеш умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Али што си тијем дјелом дао прилику непријатељима Господњим да хуле, зато ће ти умријети син који ти се родио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Потом Натан отиде својој кући. А Господ удари дијете које роди жена Уријина Давиду, те се разбоље на смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'И Давид се мољаше Богу за дијете, и пошћаше се Давид, и дошавши лежаше преко ноћ на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'И старјешине дома његова усташе око њега да га подигну са земље, али он не хтје, нити једе што с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'А кад би седми дан, умрије дијете; и не смијаху слуге Давидове јавити му да је дијете умрло, јер говораху: ево, док дијете бијаше живо, говорасмо му, па нас не хтје послушати; а како ћемо му казати: умрло је дијете? хоће га уцвијелити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'А Давид видећи гдје слуге његове шапћу међу собом, досјети се да је умрло дијете; и рече Давид слугама својим: је ли умрло дијете? А они рекоше: умрло је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Тада Давид уста са земље, и уми се, и намаза се и преобуче се; и отиде у дом Господњи, и поклони се. Потом опет дође кући својој, и заиска да му донесу да једе; и једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'А слуге његове рекоше му: шта то радиш? док бијаше дијете живо, постио си и плакао; а кад умрије дијете, устао си и једеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'А он рече: док дијете бијаше живо, постио сам и плакао, јер говорах: ко зна, може се смиловати Господ на ме да дијете остане живо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'А сад умрло је; што бих постио? могу ли га повратити? ја ћу отићи к њему, али он неће се вратити к мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Потом Давид утјеши Витсавеју жену своју, и отиде к њој, и леже с њом. И она роди сина, којему надје име Соломун. И мио бјеше Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'И посла Натана пророка, те му надје име Једидија, ради Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'А Јоав бијући Раву синова Амонових, узе царски град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'И посла посланике к Давиду, и рече: бих Раву, и узех град на води.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Него сада скупи остали народ, и стани у око према граду, и узми га, да га не бих ја узео и моје се име спомињало на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'И Давид скупив сав народ отиде на Раву, и удари на њу, и узе је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'И узе цару њихову с главе круну, у којој бјеше таланат злата, с драгим камењем, и метнуше је на главу Давиду, и однесе из града плијен врло велик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'А народ који бијаше у њему изведе и метну их под пиле и под бране гвоздене и под сјекире гвоздене, и сагна их у пећи гдје се опеке пеку. И тако учини свијем градовима синова Амоновијех. Потом се врати Давид са свијем народом у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'А потом се догоди: Авесалом син Давидов имаше лијепу сестру по имену Тамару, и замилова је Амнон син Давидов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'И тужаше Амнон тако да се разбоље ради Тамаре сестре своје; јер бјеше дјевојка, те се Амнону чињаше тешко да јој учини што.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'А имаше Амнон пријатеља, којему име бјеше Јонадав син Саме брата Давидова; и Јонадав бјеше врло домишљат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'И рече му: што се тако сушиш, царев сине, од дана на дан? не би ли ми казао? А Амнон му рече: љубим Тамару сестру Авесалома брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Тада му рече Јонадав: лези у постељу своју, и учини се болестан; па кад дође отац твој да те види, ти му реци: нека дође Тамара сестра моја да ме нахрани, и да зготови пред мојим очима јело да гледам, и из њезине руке да једем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'И Амнон леже и учини се болестан; и кад дође цар да га види, рече Амон цару: нека дође Тамара сестра моја и зготови преда мном два јелца да једем из њезине руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Тада Давид посла к Тамари кући, и поручи јој: иди у кућу брата својега Амнона и зготови му јело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'И Тамара отиде у кућу брата својега Амнона, и он лежаше; и узе брашна и замијеси и зготови јело пред њим и скуха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Потом узе тавицу и изручи преда њ; али Амнон не хтје јести, него рече: кажите нека изиду сви који су код мене. И изидоше сви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Тада рече Амнон Тамари: донеси то јело у клијет да једем из твоје руке. И Тамара узе јело што бјеше зготовила, и донесе Амнону брату својему у клијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'А кад му пружи да једе, он је ухвати и рече јој: ходи, лези са мном, сестро моја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'А она му рече: не, брате, немој ме осрамотити, јер се тако не ради у Израиљу, не чини тога безумља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Куда бих ја са срамотом својом? а ти би био као који од најгорих људи у Израиљу. Него говори цару; он ме неће теби одрећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Али је он не хтје послушати, него савладавши је осрамоти је и облежа је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'А послије омрзе на њу Амнон веома, те мржња којом мржаше на њу бјеше већа од љубави којом је прије љубљаше. И рече јој Амнон: устани, одлази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'А она му рече: то ће бити веће зло од онога које си ми учинио што ме тјераш. Али је он не хтје послушати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Него викну момка који га слушаше, и рече му: води ову од мене напоље, и закључај врата за њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'А она имаше на себи шарену хаљину, јер таке хаљине ношаху царске кћери док су дјевојке. И слуга његов изведе је напоље, и закључа за њом врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Тада Тамара посу се пепелом по глави и раздрије шарену хаљину коју имаше на себи, и метну руку своју на главу, и отиде вичући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'А брат њезин Авесалом, рече јој: да није Амнон брат твој био с тобом? али, сестро моја, ћути, брат ти је, не мисли о том. И тако оста Тамара осамљена у кући брата својега Авесалома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'И цар Давид чувши све ово разгњеви се врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Авесалом пак не говораше с Амноном ни ружно ни лијепо; јер Авесалом мржаше на Амнона што му осрамоти сестру Тамару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'А послије двије године кад се стризијаху овце Авесаломове у Вал-Асору, који је код Јефрема, он позва све синове цареве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'И дође Авесалом к цару и рече му: ево, сад се стригу овце слузи твојему; нека пође цар и слуге његове са слугом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Али цар рече Авесалому: немој, сине, немој да идемо сви, да ти не будемо на теготу. И премда наваљиваше, опет не хтје ићи, него га благослови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'А Авесалом рече: кад ти нећеш, а оно нека иде с нама Амнон брат мој. А цар му рече: што да иде с тобом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Али навали Авесалом на њ, те пусти с њим Амнона и све синове царске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Тада Авесалом заповједи момцима својим говорећи: пазите, кад се срце Амнону развесели од вина, и ја вам речем: убијте Амнона; тада га убијте; не бојте се, јер вам ја заповиједам, будите слободни и храбри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'И учинише с Амноном слуге Авесаломове како им заповједи Авесалом. Тада усташе сви синови цареви и појахаше свак своју мазгу и побјегоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'А докле још бијаху на путу, дође глас Давиду да је Авесалом побио све синове цареве, да није остао од њих ни један.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Тада уставши цар раздрије хаљине своје, и леже на земљу, и све слуге његове које стајаху око њега раздријеше хаљине своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'А Јонадав син Саме брата Давидова проговори и рече: нека не говори господар мој да су побили сву дјецу, цареве синове; погинуо је само Амнон, јер Авесалом бјеше тако наумио од оног дана кад Амнон осрамоти Тамару сестру његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Нека дакле цар господар мој не мисли о том у срцу својем говорећи: сви синови цареви погибоше; јер је само Амнон погинуо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'А Авесалом побјеже. А момак на стражи подиже очи своје и угледа, а то многи народ иде к њему покрај горе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'И Јонадав рече цару: ево иду синови цареви; као што је казао слуга твој, тако је било.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'И кад изрече, а то синови цареви дођоше, и подигавши глас свој плакаше; а и цар и све слуге његове плакаше врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Авесалом пак побјеже и отиде к Талмају сину Амијудову цару Гесурском. А Давид плакаше за сином својим сваки дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'А кад Авесалом утече и дође у Гесур, оста ондје три године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Потом зажеље цар Давид отићи к Авесалому, јер се утјеши за Амноном што погибе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'А Јоав син Серујин опази да се срце царево обратило к Авесалому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'И посла Јоав у Текују те дозва отуда жену лукаву, па јој рече: учини се као да си у жалости, и обуци жалосне хаљине, и немој се намазати уљем, него буди као жена која одавна жали за мртвијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'И отиди к цару, и говори му тако и тако. И научи је Јоав шта ће говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'И кад отиде жена Текујанка к цару да говори, паде ничице на земљу и поклони се, и рече: помагај царе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'А цар јој рече: што ти је? А она рече: удовица сам, умро ми је муж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'А имаше слушкиња твоја два сина, па се свадише у пољу, а не бјеше никога да их развади, те један удари другога и уби га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'И гле сав дом уста на слушкињу твоју говорећи: дај тога што је убио брата својега да га погубимо за душу брата његова, којега је убио, и да истријебимо нашљедника; и тако хоће да угасе искру која ми је остала, да не оставе имена мужу мојему ни остатка на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'А цар рече жени: иди кући својој, а ја ћу наредити за те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'А жена Текујанка рече цару: царе господару! нека на ме и на дом оца мојега падне кривица, а цар и његов пријесто нека је прав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'А цар рече: ко узговори на те, доведи га к мени, и неће те се више дотаћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'А она рече: нека се опомене цар Господа Бога својега, да се не умноже осветници који убијају, и да не убију сина мојега. А он рече: тако жив био Господ, ниједна длака с твојега сина неће пасти на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'А жена рече: да каже слушкиња твоја нешто цару господару. А он рече: говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'А жена рече: а зашто си намислио таку ствар народу Божијему? јер цар као да је крив говорећи тако, јер неће цар да дозове натраг онога кога је одагнао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Јер ћемо доиста помријети, и јесмо као вода која се проспе на земљу и више се не може скупити; јер му Бог није узео живота, него је наумио да одагнани не остане одагнан од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'И тако дођох да кажем ово цару господару својему, јер ме народ уплаши; зато рече слушкиња твоја: да говорим цару, може бити да ће учинити цар што слушкиња његова каже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Јер ће цар услишити и избавити слушкињу своју из руке онога који хоће да истријеби мене и сина мојега из нашљедства Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'И слушкиња твоја рече: ријеч цара господара мојега биће ми утјеха, јер је цар господар мој као анђео Божји, те слуша и добро и зло, и Господ ће Бог твој бити с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'А цар одговори и рече жени: немој тајити од мене што ћу те питати. А жена рече: нека говори цар господар мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Тада цар рече: да није Јоавов посао у свему томе што чиниш? А жена одговори и рече: тако да је жива душа твоја, царе господару, не може се ни надесно ни налијево од свега што каза цар господар мој; јер слуга твој Јоав заповиједио ми је и научио слушкињу твоју све ово да говорим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Слуга је твој Јоав учинио, те сам овако извила бесједу своју; али је господар мој мудар као анђео Божји, те зна све што бива на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Тада рече цар Јоаву: ево, ти си учинио то, иди, доведи натраг дијете Авесалома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Тада паде Јоав лицем на земљу, и поклони се и благослови цара, и рече Јоав: данас види слуга твој да сам нашао милост пред тобом, царе господару, кад је цар учинио што му слуга његов рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Потом се подиже Јоав и отиде у Гесур, и доведе натраг у Јерусалим Авесалома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'И цар рече: нека иде својој кући, а лица мојега да не види. И отиде Авесалом својој кући, и не видје лица царева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'А не бјеше човјека тако лијепа као Авесалом у свем Израиљу, да га тако хвале; од пете до тјемена не бјеше на њему мане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'И кад би стригао главу (а имаше обичај сваке године стрићи је, јер му бијаше тешко), мјерио би косу с главе своје, и биваше је двјеста сикала царском мјером.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'И родише се Авесалому три сина и једна кћи, којој бијаше име Тамара, и она бијаше лијепа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'И Авесалом оста цијеле двије године у Јерусалиму, а лица царева не видје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Тада посла Авесалом по Јоава да га пошље к цару; али он не хтје доћи к њему; и посла опет други пут, али он не хтје доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Тада рече слугама својим: видите ли њиву Јоавову поред моје? на њој је јечам; идите и упалите је. И упалише слуге Авесаломове ону њиву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Тада се подиже Јоав, и дође к Авесалому у кућу, и рече му: зашто слуге твоје упалише моју њиву?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Авесалом рече Јоаву: ето слао сам к теби говорећи: ходи овамо да те пошљем к цару да му кажеш: зашто сам дошао из Гесура? боље би било да сам још ондје. Зато да видим лице царево; ако ли има кака кривица на мени, нека ме погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'И отиде Јоав к цару, и каза му. И дозва Авесалома; а он дошавши к цару поклони се лицем до земље пред царем, и цар цјелова Авесалома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'А послије тога набави себи Авесалом кола и коња и педесет људи, који трчаху пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'И устајаше рано Авесалом, и стајаше крај пута код врата; и ко год имаше парницу и иђаше цару на суд, Авесалом га дозиваше к себи и говораше: из кога си града? А кад би онај одговорио: слуга је твој из тога и тога племена Израиљева,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Тада би му рекао Авесалом: видиш, твоја је ствар добра и праведна, али те нема ко саслушати код цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Још говораше Авесалом: кад бих ја био постављен да судим у земљи! да сваки к мени долази који има посла на суду, ја бих му дао правицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'И кад би му ко приступио да му се поклони, он би пружио руку своју, те би га ухватио и пољубио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Тако чињаше Авесалом са сваким Израиљцем, који долажаше на суд к цару; и Авесалом примамљиваше срца људи Израиљаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'А кад прође четрдесет година, рече Авесалом цару: да отидем у Хеврон да извршим завјет који сам завјетовао Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Јер кад сјеђах у Гесуру у Сирији, учини завјет слуга твој рекавши: ако ме Господ одведе натраг у Јерусалим, послужићу Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'А цар му рече: иди с миром. И он се подиже и отиде у Хеврон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'И разасла Авесалом по свијем племенима Израиљевим уходе поручивши: кад чујете трубе да затрубе, реците: зацари се Авесалом у Хеврону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'А с Авесаломом отиде двјеста људи из Јерусалима позванијех; али отидоше у простоти својој не знајући ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'А Авесалом посла и по Ахитофела Гилоњанина, савјетника Давидова, да дође из града својега Гилона, кад приношаше жртве. И буна поста јака, и народ се све више стјецаше к Авесалому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Тада дође гласник к Давиду и рече: срце Израиљу приста за Авесаломом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'А Давид рече свијем слугама својим које бијаху с њим у Јерусалиму: устајте, да бјежимо; иначе нећемо утећи од Авесалома; брже похитајте, да не похита он и не стигне нас и обори на нас зло, и града не окрене под мач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'А слуге цареве рекоше цару: што је год воља цару господару нашему, ево слуга твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'И отиде цар пјешице и сав дом његов; само десет жена иноча остави цар да му чувају кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'И када отиде цар и сав народ пјешице, уставише се на једном мјесту подалеко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'А све слуге његове иђаху уза њ, и сви Херетеји и сви Фелетеји; и сви Гетеји, шест стотина људи, који бијаху дошли пјешке из Гата, иђаху пред царем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'И рече цар Итају Гетејину: што и ти идеш с нама? Врати се и остани код цара; јер си странац и опет ћеш отићи у своје мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Јуче си дошао, па зар данас да те крећем да се потуцаш с нама? Ја ћу ићи куда могу, а ти се врати и одведи натраг браћу своју. Нека милост и вјера буде с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'А Итај одговори цару и рече: тако жив да је Господ и тако да је жив цар господар мој, гдје буде цар господар мој, било на смрт или на живот, ондје ће бити и слуга твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Тада рече Давид Итају: а ти ходи. И тако пође Итај Гетејин са свијем људима својим и свом дјецом што бијаху с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'И сва земља плакаше иза гласа и сав народ прелажаше. И тако цар пријеђе преко потока Кедрона, и сав народ пријеђе идући к пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'А гле и Садок бијаше ондје и сви Левити с њим носећи ковчег завјета Божијега; и спустише ковчег Божји, а пође и Авијатар, докле сав народ изиде из града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'И рече цар Садоку: носи ковчег Божји натраг у град; ако нађем милост пред Господом, он ће ме довести натраг, и даће ми да опет видим њега и дом његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Ако ли овако рече: нијеси ми мио; ево ме, нека учини са мном што му буде воља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Још рече цар Садоку свештенику: нијеси ли ти видјелац? врати се у град с миром, и Ахимас син твој и Јонатан син Авијатаров, два сина ваша с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Видите, ја ћу се забавити у пољу у пустињи докле не дође од вас гласник да ми јави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'И тако Садок и Авијатар однесоше ковчег Божји натраг у Јерусалим, и осташе ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'А Давид иђаше уз гору Маслинску, и идући плакаше, и покривене главе и бос иђаше; тако и сав народ, који бјеше с њим, сваки покривене главе иђаше, и идући плакаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Тада јавише Давиду и рекоше му: Ахитофел је међу онима који се побунише с Авесаломом. А Давид рече: разбиј намјеру Ахитофелову, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'И кад Давид дође наврх горе, гдје се шћаше поклонити Богу, гле, срете га Хусај Архијанин раздрте хаљине и главе посуте прахом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'И рече му Давид: ако пођеш са мном бићеш ми на теготу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Али да се вратиш у град и речеш Авесалому: бићу твој слуга царе! био сам дуго слуга твоме оцу, а сада ћу тако бити теби слуга; разбићеш ми намјеру Ахитофелову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'И свештеници Садок и Авијатар неће ли бити с тобом? Што год чујеш из куће цареве, докажи Садоку и Авијатару свештеницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Ето, ондје су с њима два сина њихова, Ахимас Садоков и Јонатан Авијатаров, по њима ми јављајте што год дочујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'И отиде у град Хусај пријатељ Давидов, и Авесалом дође у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'А кад Давид пријеђе мало преко врха, гле, Сива, Мефивостејев, срете га, са два магарца натоварена, на којима бјеше двјеста хљебова и сто гроздова сухих и сто груда смокава и мијех вина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'И рече цар Сиви: шта ће ти то? А Сива му рече: магарци су за чељад цареву, да јашу, а хљебови и воће да једу момци, а вино да пије ко се умори у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'А цар му рече: а гдје је син твога господара? Рече Сива цару: ено га, остао је у Јерусалиму, јер рече: данас ће ми дом Израиљев вратити царство оца мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Тада рече цар Сиви: ево, твоје је све што је било Мефивостејево. А Сива рече: клањам ти се, да нађем милост пред тобом, царе господару!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'И дође цар Давид до Ваурима; а гле, изиде оданде један од рода дома Саулова, по имену Симеј, син Гирин, и идући псоваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'И бацаше се камењем на Давида и на слуге цара Давида, којему и с десне и с лијеве стране бијаше сав народ и сви јунаци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'А Симеј овако говораше псујући: одлази, одлази, крвопијо и зликовче!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Обрати Господ на тебе све крви дома Саулова, на чије си се мјесто зацарио, и предаде Господ царство у руке Авесалому сину твојему; ето те сада у твом злу, јер си крвопија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Тада рече цару Ависај син Серујин: зашто да псује овај мртви пас цара господара мојега? Идем да му скинем главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Али цар рече: шта је вама до мене, синови Серујини? нека псује; јер му је Господ рекао: псуј Давида. Па ко смије казати: зашто тако чиниш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Још рече Давид Ависају и свијем слугама својим: ето, мој син, који је изашао од бедара мојих, тражи душу моју, а како неће овај син Венијаминов? Оставите га нека псује, јер му је Господ заповједио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Да ако Господ погледа на невољу моју, и врати ми Господ добро за псовку његову данашњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'И тако Давид са својим људима иђаше својим путем; а Симеј иђаше покрај горе према њему једнако псујући и бацајући се камењем на њ, и подижући прах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'И дође цар и сав народ што бијаше с њим, уморни, и одморише се ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'А Авесалом и сав народ Израиљев дођоше у Јерусалим, и Ахитофел с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'А кад Хусај Архијанин пријатељ Давидов дође к Авесалому, рече Хусај Авесалому: да живи цар! да живи цар!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'А Авесалом рече Хусају: така ли је љубав твоја према пријатељу твојему? зашто нијеси отишао с пријатељем својим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'А Хусај рече Авесалому: не; него кога је изабрао Господ и овај народ и сви Израиљци, његов ћу бити и код њега ћу остати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Сврх тога, коме бих служио? еда ли не сину његову? како сам служио оцу твојему, тако ћу и теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'А Авесалом рече Ахитофелу: свјетуј шта ћемо чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'А Ахитофел рече Авесалому: лези с иночама оца својега, које је оставио да му чувају кућу, па кад чује сав Израиљ како си се омразио с оцем својим, осилиће рука свјема који су с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Тада разапеше Авесалому шатор на крову, и Авесалом леже с иночама оца својега на видику свјему Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'И свјет који даваше Ахитофел у оно вријеме бијаше као да би ко Бога упитао; таки бијаше сваки свјет Ахитофелов и у Давида и у Авесалома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Још рече Ахитофел Авесалому: да одаберем дванаест тисућа људи па да идем и тјерам Давида ноћас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'Па ћу га стигнути док је уморан и изнемоглијех руку; и уплашићу га, те ће побјећи сав народ што је с њим, па ћу убити цара самога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'И обратићу сав народ к теби; јер за онијем кога тражиш стоји да се сви врате к теби; тада ће се сав народ умирити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'И то се учини добро Авесалому и свијем старјешинама Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Али рече Авесалом: дозовите и Хусаја Архијанина да чујемо што ће и он рећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'А кад дође Хусај к Авесалому, рече му Авесалом говорећи: тако и тако рече Ахитофел; хоћемо ли чинити како он рече или нећемо? кажи ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'А Хусај рече Авесалому: није добар свјет што је сада свјетовао Ахитофел.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Још рече Хусај: ти знаш оца својега и људе његове да су храбри и да су љута срца као медвједица кад јој отму медвједиће у пољу; сврх тога, твој је отац ратник, неће ноћити с народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Гле, он се је сада сакрио у каку јаму или на друго како мјесто. Па ако у први мах који од овијех погину, ко год чује сваки ће рећи: побијен је народ који приста за Авесаломом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'А тада ће најхрабрији, у којијех је срце као срце лавово, клонути. Јер сав Израиљ зна да је твој отац јунак и да су храбри који су с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Зато ја свјетујем да скупиш к себи све Израиљце од Дана до Вирсавеје да их буде као пијеска на мору, па ти главом иди у бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Тада ћемо поћи на њ, гдје би се год налазио, и напашћемо на њ као што роса пада на земљу, да му не остане ниједан од свијех људи што су с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Ако ли утече у град, сав народ Израиљски нека донесе ужа под онај град, па ћемо га свући у поток, да се ни камен не нађе ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Тада рече Авесалом и сви Израиљци: бољи је свјет Хусаја Архијанина него свјет Ахитофелов. Јер Господ бјеше наредио да се разбије свјет Ахитофелов, који бјеше бољи, да би Господ навукао зло на Авесалома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Потом рече Хусај свештеницима Садоку и Авијатару: тако и тако свјетова Ахитофел Авесалома и старјешине Израиљеве, а ја свјетовах тако и тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Него брже пошљите, те јавите Давиду и реците: немој ноћас ноћити у пољу у пустињи, него пријеђи пријеко, да не буде прождрт цар и сав народ што је с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'А Јонатан и Ахимас стајаху код студенца Рогила, и дође једна слушкиња и каза им, да би отишли те јавили цару Давиду; јер се не смијаху показати ни ући у град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Али их видје један момак, те каза Авесалому; а они обојица брже отидоше, и дођоше у Ваурим у кућу једнога човјека, који имаше на двору студенац, те се спустише у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'И жена узе и разастрије поњаву поврх студенца, и поврх ње разасу прекрупу. И тако се не дозна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Јер дођоше слуге Авесаломове к оној жени у кућу, и рекоше јој: гдје је Ахимас и Јонатан? А жена им рече: отидоше преко потока. Тако траживши и не нашавши вратише се у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'А кад отидоше, они ижљезоше из студенца, и отидоше те јавише цару Давиду, и рекоше му: устаните и пријеђите брже преко воде; јер је тако и тако свјетовао Ахитофел на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Тада уста Давид и сав народ што бијаше с њим, и пријеђоше преко Јордана прије зоре, не оста ниједан да не пријеђе преко Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Ахитофел пак видећи гдје се не учини како он свјетова, оседла својега магарца, па се подиже и отиде кући својој, у свој град, и наредивши за своју кућу објеси се те умрије, и би погребен у гробу оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'А Давид дође у Маханајим; Авесалом пак пријеђе преко Јордана и сав Израиљ што бјеше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'И постави Авесалом Амасу над војском, на мјесто Јоавово; а Амаса бјеше син некога човјека по имену Итре Израиљца, који облежа Авигеју кћер Насову, сестру Серује матере Јоавове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'И стаде у око Израиљ с Авесаломом у земљи Галадовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'А кад дође Давид у Маханајим, Совије син Насов из Раве синова Амоновијех и Махир син Амилов из Лодевара и Варзелај од Галада из Рогелима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Донесоше постеље и чаша и судова земљанијех и пшенице и јечма и брашна и прекрупе и боба и лећа и прженијех зрна,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'И меда и масла и оваца и сира крављега; донесоше Давиду и народу што бјеше с њим да једу. Јер говораху: народ је гладан и уморан и жедан у тој пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'И преброји Давид народ што бијаше с њим, и постави им тисућнике и стотинике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'И предаде Давид трећину народа Јоаву, и трећину Ависају сину Серујину брату Јоавову, и трећину Итају Гетејину. Па онда рече цар народу: и ја ћу ићи с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Али народ рече: немој ти ићи; јер и да побјегнемо, неће марити за то; или да нас пола изгине, неће марити за то; јер си ти сам као нас десет тисућа, зато је боље да нам из града помажеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'А цар им рече: што вам се чини да је добро учинићу. И цар стаде код врата, и сав народ излажаше по сто и по тисућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'И заповједи цар Јоаву и Ависају и Итају, и рече: чувајте ми дијете Авесалома. И сав народ чу како цар заповједи свијем војводама за Авесалома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'И тако изиде народ у поље пред Израиља, и заметну се бој у шуми Јефремовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Ондје разбише народ Израиљев слуге Давидове, и много изгибе ондје у онај дан, двадесет тисућа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Јер се бој рашири по свој земљи, и више прождрије народа у онај дан шума него што прождрије мач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'А Авесалом се сукоби са слугама Давидовијем, и Авесалом јахаше на мазги, и мазга наиђе под гранат велики храст, те он запе главом за храст и оста висећи између неба и земље, а мазга испод њега отрча.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Видјевши то један човјек јави Јоаву, и рече: гле, видјех Авесалома гдје виси о храсту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'А Јоав рече човјеку који му то каза: гле, видје, па зашто га не уби и не свали га на земљу? Ја бих ти дао десет сикала сребра и један појас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'А човјек рече Јоаву: да ми је у рукама измјерено тисућа сикала сребра, не бих дигао руке своје на сина царева; јер смо чули како је цар заповједио теби и Ависају и Итају говорећи: чувајте ми сви дијете Авесалома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Или да сам учинио невјеру на своју душу, ништа се не може од цара затајити, и ти би сам устао на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'А Јоав рече: нећу ја дангубити с тобом. Па узев три стријеле у руку, застријели их у срце Авесалому, јоште живу о храсту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Потом опколише Авесалома десет момака, који ношаху оружје Јоаву, и бише га и убише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Тада Јоав затруби у трубу, и народ преста гонити Израиља, јер Јоав устави народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'И узеше Авесалома и бацише у шуми у велику јаму, и набацаше на њ врло велику гомилу камења; а Израиљци сви побјегоше сваки к своме шатору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Авесалом пак бјеше подигао себи споменик за живота у долини царској; јер говораше: немам сина, да се сачува спомен имену мојему. И назва онај споменик својим именом, који се зове мјесто Авесаломово до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Тада рече Ахимас син Садоков: да отрчим да однесем глас цару, да га је Господ избавио из руку непријатеља његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'А Јоав му рече: немој данас бити гласник, него ћеш јавити други дан; а данас немој носити гласа, јер је син царев погинуо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Затијем рече Јоав Хусију: иди, јави цару што си видио. И поклони се Хусије Јоаву, и отрча.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'А Ахимас син Садоков опет рече Јоаву: што му драго, да трчим и ја за Хусијем. Рече Јоав: што би трчао, сине, кад немаш добра гласа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'Опет рече: што му драго, да трчим. Одговори му: а ти трчи. И отрча Ахимас пречим путем, и претече Хусија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'А Давид сјеђаше међу двојим вратима, и стражар изиде на кров од врата, на зид, и подигавши очи своје угледа, а то један човјек трчи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Па повика стражар и јави цару. А цар рече: ако је један, глас носи. И онај иђаше све ближе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Потом угледа стражар другога човјека гдје трчи. И повика стражар к вратару и рече: ево још један, трчи сам. А цар рече: и он носи глас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'И рече стражар: трк првога чини ми се као да је трк Ахимаса сина Садокова. Рече цар: добар је човјек, и иде с добријем гласом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Тада повика Ахимас и рече цару: сретно! И поклони се цару лицем до земље, и рече: да је благословен Господ Бог твој, који предаде људе који подигоше руке своје на цара господара мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'А цар му рече: је ли здраво дијете Авесалом? Одговори Ахимас: видио сам велику вреву, кад Јоав посла слугу царева и мене слугу твојега, али не знам шта бјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'А цар му рече: уклони се, и стани тамо. И он се уклони, и стаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Тада, гле, дође Хусије и рече: глас цару и господару мојему да те је Господ избавио данас из руку свијех који усташе на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'А цар рече Хусију: је ли здраво дијете Авесалом? А Хусије рече: нека непријатељи господара мојега цара и који год устају на те зла ради, нека прођу као то дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Тада се цар сневесели, и попе се у горњу клијет над вратима, и стаде плакати, а идући говораше: сине мој Авесаломе, сине мој, сине мој Авесаломе! камо да сам ја умро мјесто тебе! Авесаломе сине мој, сине мој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'И јавише Јоаву: ево цар плаче и тужи за Авесаломом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'И побједа онога дана претвори се у жалост свему народу, јер народ чу у онај дан гдје говоре: жали цар сина својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'И народ се у онај дан кријаше улазећи у град као што се крије народ који се стиди кад побјегне из боја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'А цар покри лице своје; и викаше иза гласа: сине мој Авесаломе! Авесаломе сине мој, сине мој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Тада уђе Јоав к цару у кућу, и рече: посрамио си данас све слуге своје, које ти данас душу сачуваше, и синовима твојим и кћерима твојим и женама твојим и иночама твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Јер љубиш оне који мрзе на те, а мрзиш на оне који те љубе; јер си показао данас да не мариш за војводе и за слуге; и видим данас да би ти мило било да је Авесалом жив а ми сви да смо изгинули.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Зато устани сада, и изиди и проговори лијепо слугама својим; јер заклињем се Господом, ако не изидеш, неће ниједан остати код тебе ову ноћ, и то ће бити горе по те неголи сва зла која су те сналазила од младости твоје до сада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Тада уста цар, и сједе на вратима; и казаше свему народу говорећи: ево, сједи цар на вратима. И дође сав народ пред цара. Али Израиљци бјеху побјегли, свак у свој шатор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'И сав се народ свађаше међу собом по свијем племенима Израиљевим говорећи: цар нас је избавио из руку непријатеља наших, и избавио нас је из руку Филистејских; а сада је побјегао из земље од Авесалома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Авесалом пак, којега помазасмо за цара над собом, погибе у боју. Сада дакле зашто оклијевате те не доведете натраг цара?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Зато цар Давид посла к Садоку и Авијатару свештеницима и поручи: говорите старјешинама Јудинијем и реците: зашто ви да будете пошљедњи који ће цара натраг довести у кућу његову? Јер говор свега Израиља дође до цара у кућу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Ви сте моја браћа, ви сте кост моја и тијело моје. Зашто бисте дакле били пошљедњи који ће натраг довести цара?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Реците и Амаси: нијеси ли кост моја и тијело моје? Бог нека ми учини тако и тако нека дода, ако ми не будеш војвода док си жив намјесто Јоава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'И склони срца свијех људи од рода Јудина као једнога човјека, те послаше к цару говорећи: врати се са свијем слугама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'И тако се цар врати, и дође до Јордана; а Јуда дође до Галгала да срете цара и да га преведе преко Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Похитје и Симеј син Гирин од Венијамина, који бијаше из Ваурима, и сиђе с људима рода Јудина на сусрет цару Давиду;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'И тисућа људи бјеше с њим од рода Венијаминова; такођер и Сива слуга дома Саулова с петнаест синова својих и двадесет слуга својих; и пријеђоше преко Јордана пред цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Претурише и лађу да превезу чељад цареву и да учине што би му било угодно. А Симеј син Гирин паде пред царем, кад шћаше да пријеђе преко Јордана,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'И рече цару: не прими ми безакоња, господару мој, и не помињи пакости коју је учинио слуга твој у онај дан кад је цар господар мој изашао из Јерусалима; нека цар не мисли о том.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Јер слуга твој види да је згријешио; и ево дошао сам данас први из свега дома Јосифова да сретем цара господара својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Али одговори Ависај син Серујин и рече: еда ли тога ради неће погинути Симеј што је псовао помазаника Господњега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'А Давид рече: шта је вама до мене, синови Серујини, те сте ми данас противници? зар ће данас ко погинути у Израиљу, јер зар не знам да сам данас постао цар над Израиљем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'И рече цар Симеју: нећеш погинути. И закле му се цар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Тако и Мефивостеј син Саулов дође цару на сусрет; он пак не опра ногу својих, нити браде своје очешља, ни опра хаљине своје од онога дана кад отиде цар до дана кад се врати с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'И срете цара кад се враћаше у Јерусалим; и рече му цар: зашто не пође са мном, Мефивостеју?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'А он рече: цару господару мој, превари ме слуга мој; јер слуга твој рече: оседлаћу себи магарца и узјахаћу га и поћи ћу с царем; јер је хром слуга твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'И он опаде слугу твојега код господара мојега цара; али је цар господар мој као анђео Божји; зато чини што ти је драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Јер сав дом оца мојега бијаху људи који заслужише смрт пред царем господаром мојим, а ти посади слугу својега међу оне који једу за столом твојим, па како имаш још право, и како се могу још тужити цару?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'А цар му рече: шта би ми више говорио? казао сам: ти и Сива подијелите њиву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'А Мефивостеј рече цару: нека узме све, кад се цар господар мој вратио на миру у дом свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'И Варзелај од Галада дође из Рогелима, и пође с царем преко Јордана да га прати преко Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'А бјеше Варзелај врло стар, бјеше му осамдесет година, и храњаше цара док бијаше у Маханајиму, јер бјеше врло богат човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'И рече цар Варзелају: хајде са мном; ја ћу те хранити код себе у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Али Варзелај рече цару: колико има вијека мојега, да идем с царем у Јерусалим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Има ми данас осамдесет година; могу ли распознавати добро и зло? може ли слуга твој кусом разликовати што ће јести и што ће пити? могу ли јоште слушати глас пјевачима и пјевачицама? и зашто би слуга твој још био на теготу цару господару мојему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Мало ће проћи слуга твој преко Јордана с царем; а зашто би ми цар тако наплатио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Нека се слуга твој врати, да умрем у свом граду код гроба оца својега и матере своје. Него ево, слуга твој Химам нека иде с царем господарем мојим, и учини њему што ти буде драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'А цар рече: нека иде са мном Химам; ја ћу му учинити што буде теби драго, и што год заиштеш у мене, све ћу ти учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'И кад пријеђе сав народ преко Јордана и цар пријеђе, цјелова цар Варзелаја и благослови га, и он се врати у мјесто своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Отуда цар отиде у Галгал, и Химам отиде с њим. И тако сав народ Јудин допрати цара, и половина народа Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'А гле, сви људи Израиљци дођоше к цару и рекоше му: зашто те украдоше браћа наша, људи Јудини, и преведоше преко Јордана цара и дом његов и све људе Давидове с њим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'А сви људи од Јуде одговорише људима од Израиља: јер је цар нама род; па што се срдите тога ради? јесмо ли што појели цару? је ли нас даром даривао?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Тада одговорише људи од Израиља људима од Јуде, и рекоше: ми имамо десет дијелова у цара, и Давиду смо више него ви; зашто дакле не маристе за нас? нијесмо ли ми први говорили да доведемо натраг цара својега? Али бесједа људи од Јуде бјеше тврђа од бесједе људи од Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'А ондје се деси неваљао човјек, по имену Сева син Вихријев, од Венијамина. Он затруби у трубу и рече: ми немамо дијела с Давидом, ни нашљедства са сином Јесејевијем; свак у свој шатор, о Израиљу!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Тако сви Израиљци отступише од Давида и отидоше за Севом сином Вихријевим; људи пак од Јуде држаше се цара својега и отпратише га од Јордана до Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'А кад цар Давид дође у кућу своју у Јерусалим, узе цар десет жена иноча, које бјеше оставио да му чувају кућу, и метну их у затвор, гдје их храњаше али не лијегаше с њима, него осташе затворене до смрти своје и живљаху као удовице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Потом рече цар Амаси: сазови ми људе од Јуде до три дана, и нађи се и ти овдје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'И отиде Амаса да сазове народ Јудин; али се забави преко рока који му бјеше одређен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'А Давид рече Ависају: сад ће нам Сева син Вихријев чинити горе него Авесалом. Него узми слуге господара својега, и гони га да не нађе за се који тврд град и не умакне нам из очију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Тако изидоше за њим људи Јоавови, и Херетеји и Фелетеји и сви јунаци, изидоше из Јерусалима да гоне Севу сина Вихријева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'И кад бијаху код великога камена у Гаваону, срете их Амаса. А Јоав бијаше опасан преко хаљине коју имаше на себи, и озго бијаше припасао мач уз бедрицу у корицама. И кад пође, мач му испаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Тада рече Јоав Амаси: јеси ли здраво брате? И дохвати се Јоав десном руком својом браде Амаси да га цјелује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'А Амаса не узимаше на ум мача, који бијаше Јоаву у руци; а он га удари њим под пето ребро, и просу му цријева на земљу, те од једнога ударца умрије. Потом Јоав и Ависај брат његов отидоше у потјеру за Севом сином Вихријевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'А један од момака Јоавовијех стаде код њега и рече: ко љуби Јоава и ко је Давидов, за Јоавом!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'А Амаса се ваљаше у својој крви насред пута. И видјећи онај човјек гдје се уставља сав народ одвуче Амасу с пута у поље и баци хаљину на њ, кад видје гдје се уставља сваки ко наиђе на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'И кад би уклоњен с пута прођоше сви за Јоавом да тјерају Севу сина Вихријева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'И он прође кроз сва племена Израиљева до Авела и до Ветмахе са свијем Виранима, који се окупише те иђаху за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'И дошавши опколише га у Авел-Вет-Маси, и ископаше опкоп око града тако да стајаху пред зидом; и сав народ што бјеше с Јоавом наваљиваше да обори зид.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Тада викну једна мудра жена из града: чујте, чујте! Кажите Јоаву: приступи овамо да говорим с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'А кад он приступи к њој, рече жена: јеси ли ти Јоав? А он рече: јесам. А она рече: послушај ријечи слушкиње своје. А он рече: да чујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'А она рече говорећи: од старине се говори: ваља питати у Авелу. И тако се извршиваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Ја сам један од мирнијех и вјернијех градова у Израиљу, а ти хоћеш да затреш град, и то мајку у Израиљу. Зашто хоћеш да прождреш нашљедство Господње?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'А Јоав одговори и рече: сачувај Боже! сачувај Боже! нећу да прождрем ни да раскопам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Није тако; него један из горе Јефремове, по имену Сева син Вихријев, подигао је руку своју на цара Давида; дајте само њега, па ћу отићи од града. А жена рече Јоаву: ево, глава његова бациће ти се преко зида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'И жена отиде к свему народу с мудрошћу својом; и отсјекоше главу Севи сину Вихријеву, и бацише је Јоаву. А он затруби у трубу, те се разидоше од града свак у свој шатор. А Јоав се врати у Јерусалим к цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'А бијаше Јоав над свом војском Израиљевом; а Венаја син Јодајев бијаше над Хетејима и Фелетејима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'А Адорам бјеше над данцима; а Јосафат син Ахилудов бјеше паметар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Сеја писар; а Садок и Авијатар свештеници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'И Ира Јаиранин бјеше кнез Давиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'И би глад за времена Давидова три године засопце. И Давид потражи лице Господње; а Господ му рече: то је са Саула и с дома његова крвничкога, што погуби Гаваоњане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Тада цар сазва Гаваоњане и говори им. А Гаваоњани не бјеху од синова Израиљевијех, него остатак од Амореја, којима се бјеху заклели синови Израиљеви, али Саул гледаше да их побије ревнујући за синове Израиљеве и Јудине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'И рече Давид Гаваоњанима: шта да вам учиним и чим да вас намирим, да благословите достојање Господње?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'А Гаваоњани му рекоше: не тражимо ни сребра ни злата од Саула или од дома његова, нити да се ко погуби у Израиљу. А он рече: шта дакле велите да вам учиним?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Тада рекоше цару: ко нас је потро и радио да нас истријеби, да нас не буде нигдје у међама Израиљевијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Од његовијех синова нека нам се да седам људи да их објесимо Господу у Гаваји Саула избраника Господњега. И рече цар: ја ћу дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Али цар поштједе Мефивостеја сина Јонатана сина Саулова ради заклетве Господње, која би међу њима, међу Давидом и Јонатаном сином Сауловијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'И узе цар два сина Ресфе кћери Ајине, које роди Саулу, Армонија и Мефивостеја, и пет синова Михале кћери Саулове, које роди Адрилу сину Варзелаја Меолаћанина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'И даде их у руке Гаваоњанима, а они их објесише на гори пред Господом; и сва седморица погибоше заједно; а бише убијени првијех дана жетве, у почетку јечмене жетве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'А Ресфа кћи Ајина узе врећу, и прострије по стијени у почетку жетве докле не паде на њих дажд са неба, и не дадијаше птицама небеским да падају на њих дању ни звјерима пољским ноћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'И јавише Давиду шта учини Ресфа кћи Ајина, иноча Саулова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'И Давид отиде те узе кости Саулове и кости Јонатана сина његова од грађана у Јавису Галадову, који их бијаху украли с улице Вет-Санске, гдје их објесише Филистеји кад убише Филистеји Саула на Гелвуји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'И однесе оданде кости Саулове и кости Јонатана сина његова, па скупише и кости објешенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'И погребоше их с костима Сауловијем и Јонатана сина његова у земљи Венијаминовој у Сили у гробу Киса оца његова, и учинише све како заповједи цар. Тако се послије тога умилостиви Господ земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'И наста опет рат између Филистеја и Израиља, и Давид отиде са слугама својим, и бише се с Филистејима тако да Давид суста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Тада Јесви-Венов, који бјеше од синова Рафајевијех, и у копљу му бјеше триста сикала мједи, и имаше ново оружје, шћаше да убије Давида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Али му поможе Ависај син Серујин, и удари Филистејина и уби га. Тада се заклеше људи Давидови рекавши му: нећеш више ићи с нама у бој да не угасиш видјела Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Послије тога наста опет рат с Филистејима у Гову; и тада Сивехај Хусаћанин уби Сафа, који бијаше од синова Рафајевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'И опет наста други рат у Гову с Филистејима; и тада Елханан син Јаре-Орегимов Витлејемац уби брата Голијата Гетејина, којему копљача бјеше као вратило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'И опет наста рат у Гату, гдје бијаше један човјек врло висок, који имаше по шест прста на рукама и на ногама, свега двадесет и четири, и он бијаше такођер рода Рафајева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'И ружаше Израиља те га уби Јонатан син Саме брата Давидова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Та четворица бијаху синови истога Рафаја из Гата, и погибоше од руке Давидове и од руке слуга његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'И изговори Давид Господу ријечи ове пјесме, кад га избави Господ из руку свијех непријатеља његовијех и из руке Саулове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'И рече: Господ је моја стијена и град мој и избавитељ мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Бог и стијена моја, у њега ћу се уздати, штит мој и рог спасења мојега, заклон мој и уточиште моје, спаситељ мој, који ме избавља од силе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Призивљем Господа, којега ваља хвалити, и опраштам се непријатеља својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Јер обузеше ме смртни болови, потоци неваљалијех људи уплашише ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Болови гробни опколише ме, стегоше ме замке смртне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'У тјескоби својој призвах Господа, и к Богу својему повиках, он чу из двора својега глас мој, и вика моја дође му до ушију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Затресе се и поколеба се земља, темељи небесима задрмаше се и помјерише се, јер се он разгњеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Подиже се дим из ноздрва његовијех и из уста његовијех огањ који прождире, живо угљевље отскакаше од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Сави небеса и сиђе; а мрак бијаше под ногама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'И сједе на херувима и полетје, и показа се на крилима вјетрнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Од мрака начини око себе шатор, од мрачнијех вода, облака ваздушнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Од сијевања пред њим гораше живо угљевље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Загрмје с небеса Господ, и вишњи пусти глас свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Пусти стријеле своје, и разметну их; муње, и разасу их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Показаше се дубине морске, и открише се темељи васиљеној од пријетње Господње, од дихања духа из ноздрва његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Тада пружи с висине руку и ухвати ме, извуче ме из воде велике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Избави ме од непријатеља мојега силнога и од мојих ненавидника, кад бијаху јачи од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Усташе на ме у дан невоље моје, али ми Господ би потпора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'И изведе ме на пространо мјесто, избави ме, јер сам му мио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Даде ми Господ по правди мојој, по чистоти руку мојих дарива ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Јер се држах путова Господњих, и не одметнух се Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Него су сви закони његови преда мном, и заповијести његовијех не уклањам од себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'И бих му вјеран, и чувах се од безакоња својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Даде ми Господ по правди мојој, по чистоти мојој пред очима његовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Са светима поступаш свето, с човјеком вјернијем вјерно;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'С чистијем чисто поступаш, а с неваљалијем насупрот њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Јер помажеш народу невољном, а на поносите спушташ очи своје и понижаваш их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Ти си видјело моје, Господе, и Господ просвијетљује таму моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'С тобом разбијам војску, с Богом својим скачем преко зида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Пут је Божји вјеран, ријеч Господња чиста. Он је штит свјема који се уздају у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Јер ко је Бог осим Господа? и ко је стијена осим Бога нашега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Бог је кријепост моја и сила моја, и чини да ми је пут без мане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Даје ми ноге као у јелена, и на висине моје ставља ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Учи руке моје боју, те ломе лук мједени мишице моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Ти ми дајеш штит спасења својега, и милост твоја чини ме велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Шириш кораке моје пода мном, те се не омичу глежњи моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Тјерам непријатеље своје, и потирем их, и не враћам се докле их не истријебим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'И истребљујем их, и обарам их да не могу устати, него падају под ноге моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Јер ме ти опасујеш снагом за бој: који устану на ме, обараш их пода ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Непријатеља мојих плећи ти ми обраћаш, и потирем ненавиднике своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Обзиру се, али нема помагача: вичу ка Господу, али их не слуша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Сатирем их као прах земаљски, као блато по улицама газим их и размећем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Ти ме избављаш од буне народа мојега, чуваш ме да сам глава народима; народ којега не познавах служи ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Туђини ласкају ми, чујући покоравају ми се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Туђини блиједе,дршћу у градовима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Жив је Господ, и да је благословена стијена моја. Да се узвиси Бог, стијена спасења мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Бог, који ми даје освету, и покорава ми народе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Који ме изводи из непријатеља мојих, и подиже ме над оне који устају на ме, и од човјека жестока избавља ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Тога ради хвалим те, Господе, по народима, и појем имену твојему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Који славно избављаш цара својега, и чиниш милост помазанику својему Давиду и сјемену његову довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'А ово су пошљедње ријечи Давидове: Рече Давид син Јесејев, рече човјек који би постављен високо, помазаник Бога Јаковљева, и љубак у пјесмама Израиљевим:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Дух Господњи говори преко мене, и бесједа његова би на мојем језику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Рече Бог Израиљев, каза ми стијена Израиљева: који влада људима нека је праведан, владајући у страху Божијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'И биће као свјетлост јутрења, кад сунце излази јутром без облака, и као трава која расте из земље од свјетлости иза дажда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Ако и није таки дом мој пред Богом, ипак је учинио завјет вјечан са мном, у свему добро уређен и утврђен. И то је све спасење моје и сва жеља моја, ако и не да да расте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'А безаконици ће свиколики бити као трње почупани, које се не хвата руком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Него ко хоће да га се дохвати, узме гвожђе или копљачу; и сажиже се огњем на мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Ово су имена јунака Давидовијех: Јосев-Васевет Тахмонац први између тројице; њему милина би ударити копљем на осам стотина и поби их уједанпут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'За њим Елеазар син Додона сина Ахохова, између три јунака који бијаху с Давидом, и осрамотише Филистеје скупљене на бој, кад Израиљци отидоше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Он се подиже, и би Филистеје докле му се рука не умори и укочи се при мачу; и Господ даде велико спасење онај дан, те се народ врати за њим само да покупи плијен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'А за њим Сама син Агејев Араранин; кад се Филистеји скупише у гомилу, и ондје бјеше њива пуна лећа, и народ побјеже од Филистеја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Стаде усред њиве, и одбрани је, и поби Филистеје, и Бог даде велико спасење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'И та три прва између тридесет сиђоше и дођоше о жетви к Давиду у пећину Одоламску, кад војска Филистејска стајаше у околу у долини Рафајској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'А Давид бијаше онда у граду, и бјеше онда стража Филистејска у Витлејему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'А Давид зажеље, и рече: ко би ми донио воде да пијем из студенца Витлејемскога што је код врата!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Тада она три јунака продријеше кроз око Филистејски, и захватише воде из студенца Витлејемскога што је код врата, и донесоше и дадоше Давиду; али он је не хтје пити, него је проли пред Господом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'И рече: не дај Боже да бих то учинио. Није ли то крв овијех људи, који не марећи за живот свој идоше. И не хтје пити. То учинише ова три јунака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'И Ависај брат Јоавов син Серујин бјеше први између тројице; он махну копљем својим на три стотине, и поби их, и прослави се међу тројицом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Између те тројице бјеше најславнији, и поста им поглавар; али оне тројице не стиже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'И Венаја син Јодајев, син човјека јунака, велик дјелима, из Кавсеила; он погуби два јунака Моавска, и сишав уби лава у јами кад бјеше снијег.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Он уби и једнога Мисирца, знатна човјека; имаше Мисирац копље у руци, а он изиде на њ са штапом, и истрже Мисирцу копље из руке, и уби га његовијем копљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'То учини Венаја син Јодајев, и би славан међу ова три јунака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Бјеше најславнији између тридесеторице, али оне тројице не стиже; и Давид га постави над пратиоцима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Асаило брат Јоавов бјеше међу тридесеторицом, а то бјеху: Елханан син Додонов из Витлејема,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Сама Арођанин, Елика Арођанин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Хелис Фалћанин, Ира син Икисов Текојанин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Авијазер Анатоћанин, Мевунеј Хусаћанин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Салмон Ахошанин, Марај Нетофаћанин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Хелед син Ванин Нетофаћанин, Итај син Ривајев из Гаваје синова Венијаминових,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Венаја Пиратоњанин, Идај из долине Гаса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Ави-Алвон Арваћанин, Азмавет Варумљанин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Елијава Салвоњанин, Јонатан од синова Јасинових,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Сама Араранин, Ахијам син Сараров Араранин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Елифелет, син Асвеја Махаћанина, Елијем син Ахитофела Гилоњанина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Есрај Кармилац, Фареј Арвљанин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Игал син Натанов из Сове, Ванија од Гада,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Селек Амонац, Нарај Вироћанин, који ношаше оружје Јоаву сину Серујину,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ира Јетранин, Гарив Јетранин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Урија Хетејин; свега тридесет и седам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'А Господ се опет разгњеви на Израиља, и надражи Давида на њих говорећи: хајде изброј Израиља и Јуду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'И рече цар Јоаву, војводи свом: прођи по свијем племенима Израиљевијем од Дана до Вирсавеје, и избројте народ, да знам колико има народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'А Јоав рече цару: нека дода Господ Бог твој к народу колико га је сад још сто пута толико, и да цар господар мој види својим очима; али зашто цар господар мој хоће то?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Али ријеч царева би јача од Јоава и војвода; и отиде Јоав и војводе од цара да преброје народ Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'И прешавши преко Јордана стадоше у око у Ароиру, с десне стране града, који је на средини потока Гадова, и код Јазира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Потом дођоше у Галад, и у доњу земљу Одсију, а одатле отидоше у Дан-Јан и у околину Сидонску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Потом дођоше до града Тира и у све градове Јевејске и Хананејске; и отидоше на јужну страну Јудину у Вирсавеју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'И обишавши сву земљу вратише се у Јерусалим послије девет мјесеци и двадесет дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'И Јоав даде цару број преписанога народа; и бјеше од Израиља осам стотина тисућа људи за војску који махаху мачем, а људи од Јуде пет стотина тисућа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Тада Давида такну у срце, пошто преброји народ, и рече Давид Господу: сагријеших веома што то урадих. Али, Господе, узми безакоње слуге својега, јер веома лудо радих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'А кад Давид уста ујутру, дође ријеч Господња Гаду пророку, који бијаше Давиду видјелац, и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Иди и кажи Давиду: овако вели Господ: троје ти дајем, избери једно да ти учиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'И дође Гад к Давиду, и каза му говорећи: хоћеш ли ти да буде седам гладнијех година у земљи твојој, или да бјежиш три мјесеца од непријатеља својих и они да те гоне, или да буде три дана помор у твојој земљи? Сад промисли и гледај шта ћу одговорити ономе који ме је послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'А Давид рече Гаду: у тјескоби сам љутој; али нека западнемо Господу у руке, јер је милост његова велика; а људима да не западнем у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'И тако пусти Господ помор на Израиља од јутра до одређенога времена, и помрије народа од Дана до Вирсавеје седамдесет тисућа људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'А кад анђео пружи руку своју на Јерусалим да га убија, сажали се Господу са зла, и рече анђелу који убијаше народ: доста, спусти руку. А анђео Господњи бијаше код гумна Орне Јевусејина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'А Давид кад видје анђела гдје бије народ, проговори и рече Господу: ево, ја сам згријешио, ја сам зло учинио, а те овце што су учиниле? нека се рука твоја обрати на мене и на дом оца мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Потом опет дође Гад к Давиду исти дан, и рече му: иди, начини Господу олтар на гумну Орне Јевусејина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'И отиде Давид по ријечи Гадовој, како Господ заповједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Тада Орна обазревши се угледа цара и слуге његове гдје иду к њему; и отиде Орна и поклони се цару лицем до земље,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'И рече: што је дошао цар господар мој слузи својему? А Давид рече: да купим од тебе то гумно, да начиним на њему олтар Господу да би престао помор у народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'А Орна рече Давиду: нека узме цар господар мој и принесе на жртву што му је воља; ево волова за жртву паљеницу, и кола и јармова волујских за дрва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Све то даваше цару Орна као цар, и рече Орна цару: Господ Бог твој нека те милостиво прими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'А цар рече Орни: не; него ћу купити од тебе по цијени, нити ћу принијети Господу Богу својему жртве паљенице поклоњене. И тако купи Давид гумно и волове за педесет сикала сребра:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'И ондје начини Давид олтар Господу, и принесе жртве паљенице и жртве захвалне. И Господ се умилостиви земљи, и преста помор у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'А цар Давид остарје и би временит, и колико га покриваху хаљинама не могаше се загријати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Тада му рекоше слуге његове; нека потраже цару господару нашему младу дјевојку, па она нека стоји пред царем и двори га, и на крилу нека му спава, да се загријева цар господар наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'И потражише лијепу дјевојку по свијем крајевима Израиљским, и нађоше Ависагу Сунамку, те је доведоше цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'А та дјевојка бијаше врло лијепа, и двораше цара и служаше му: али је цар не позна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'А Адонија син Агитин подиже се говорећи: ја ћу бити цар. И набави себи кола и коњика, и педесет људи који трчаху пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'И отац га нигда не накара, нити му рече: зашто радиш тако? А он бјеше врло лијеп, и мати га роди иза Авесалома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'И договараше се с Јоавом сином Серујиним и с Авијатаром свештеником, који помагаху Адонији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Али Садок свештеник и Венаја син Јодајев и Натан пророк и Семај и Реј и јунаци Давидови не присташе за Адонијом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Тада накла Адонија оваца и волова и угојене стоке код камена Зоелета, који је код извора Рогила, и позва сву браћу своју, синове цареве, и све људе од Јуде, слуге цареве;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Али не позва Натана пророка, ни Венаје, ни осталијех јунака, ни Соломуна брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Тада рече Натан Витсавеји матери Соломуновој говорећи: јеси ли чула да се зацарио Адонија син Агитин? а господар наш Давид не зна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Него сада хајде, ја ћу те свјетовати како ћеш избавити душу своју и душу сина својега Соломуна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Хајде, отиди к цару Давиду и реци му: нијеси ли се ти, господару мој царе, заклео слушкињи својој говорећи: Соломун син твој биће цар послије мене, и он ће сједјети на пријестолу мојем? Зашто се дакле зацари Адонија?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'И гле, док ти још будеш ондје говорећи с царем, ја ћу доћи за тобом, и допунићу твоје ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'И тако уђе Витсавеја к цару у клијет. А цар бијаше врло стар; и Ависага Сунамка двораше га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'И савивши се Витсавеја поклони се цару; а цар јој рече: шта ћеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'А она му рече: господару мој, ти си се заклео Господом Богом својим слушкињи својој: Соломун син твој биће цар послије мене, и он ће сједјети на пријестолу мојем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'А сада ево Адонија се зацари, а ти, господару мој царе, и не знаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Наклао је волова и угојене стоке и оваца много, и позвао све синове цареве, и Авијатара свештеника и Јоава војводу; а Соломуна слуге твојега није позвао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Сада, царе господару мој, очи су свега Израиља упрте у тебе, да им кажеш ко ће сјести на пријесто твој, господару мој царе, послије тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Иначе кад господар мој цар почине код отаца својих, бићемо ја и син мој Соломун криви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'И гле, док она још говораше цару, дође пророк Натан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'И јавише цару говорећи: ево Натана пророка. И он ступивши пред цара поклони се цару лицем до земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'И рече Натан: царе, господару мој, јеси ли ти казао: Адонија ће бити цар послије мене, и он ће сједјети на пријестолу мојем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Јер отиде данас и накла волова и угојене стоке и оваца много, и позва све синове цареве и војводе и Авијатара свештеника; и ено једу и пију с њим и говоре: да живи цар Адонија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Мене пак, слуге твојега, не позва, ни Садока свештеника, ни Венаје сина Јодајева, ни Соломуна слуге твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Је ли то цар господар мој наредио? не казав слузи својему ко ће сјести на пријесто господара мојега цара послије њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'А цар Давид одговори и рече: зовите ми Витсавеју. И она дође пред цара, и стаде пред царем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Тада се закле цар говорећи: тако да је жив Господ, који је избавио душу моју од сваке невоље,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Како сам ти се заклео Господом Богом Израиљевим рекавши: Соломун син твој биће цар послије мене, и он ће сједјети на пријестолу мојем мјесто мене, тако ћу учинити данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Тада Витсавеја сави се лицем до земље и поклони се цару, па рече: да живи господар мој цар Давид довијека!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Потом рече цар Давид: зовите ми Садока свештеника и Натана пророка и Венају сина Јодајева. И они дођоше пред цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'А цар им рече: узмите са собом слуге господара својега, и посадите Соломуна сина мојега на моју мазгу и и одведите га до Гиона;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'И нека га ондје Садок свештеник и Натан пророк помажу за цара над Израиљем, и затрубите у трубу и реците: да живи цар Соломун!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Потом се вратите за њим, и он нека дође и сједе на пријесто мој и царује мјесто мене; јер сам њега одредио да буде вођ Израиљу и Јуди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'А Венаја син Јодајев одговори цару и рече: амин! нека тако рече Господ Бог господара мојега цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Како је Господ био с господарем мојим царем тако тако нека буде и са Соломуном, и нека подигне пријесто његов још више него пријесто господара мојега цара Давида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'И тако отиде Садок свештеник и Натан пророк и Венаја син Јодајев и Херетеји и Фелетеји, и посадише Соломуна на мазгу цара Давида и одведоше га до Гиона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'И Садок свештеник узе рог с уљем из шатора, и помаза Соломуна. Потом затрубише у трубу и сав народ рече: да живи цар Соломун!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'И сав народ пође за њим, и народ свираше у свирале и весељаше се веома да се земља разлијегаше од вике њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'И зачу Адонија и све званице које бијаху с њим, пошто једоше; зачу и Јоав глас трубни, па рече: кака је то вика и врева у граду?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'И докле он још говораше, гле, дође Јонатан син Авијатара свештеника; и Адонија му рече: ходи, јер си јунак и носиш добре гласе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'А Јонатан одговори и рече Адонији: та, господар наш цар Давид постави Соломуна царем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Јер цар посла с њим Садока свештеника и Натана пророка и Венају сина Јодајева, и Херетеје и Фелетеје, и посадише га на цареву мазгу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'И помазаше га Садок свештеник и Натан пророк код Гиона за цара, и отидоше оданде веселећи се тако да је град узаврео; то је вика коју чусте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'И Соломун је већ сјео на царски пријесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'И дошле су слуге цареве, и благословише господара нашега цара Давида говорећи: да Бог прослави име Соломуново још већма него твоје, и пријесто његов да подигне још више него твој. И поклони се цар на постељи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Још овако рече цар: да је благословен Господ Бог Израиљев, који даде данас ко ће сједети на пријестолу мојему, да виде моје очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Тада се препадоше, и усташе све званице Адонијине, и отидоше свак својим путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'А Адонија бојећи се Соломуна уста и отиде, и ухвати се за рогове олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'И јавише Соломуну говорећи: ено, Адонија се уплашио од цара Соломуна, и ено га, ухватио се за рогове олтару, и вели: нека му се закуне цар Соломун да неће убити слуге својега мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'А Соломун рече: ако буде поштен човјек, ни длака с главе његове неће пасти на земљу; али ако се нађе зло на њему, погинуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'И тако посла цар Соломун, те га доведоше од олтара; и кад дође, поклони се цару Соломуну; а Соломун му рече: иди кући својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'А кад дође време Давиду да умре, заповједи Соломуну сину својему говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Ја идем куд иде све на земљи; а ти буди храбар и буди човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'И држи што ти је Господ Бог твој заповједио да држиш, ходећи путовима његовим и држећи уредбе његове и заповијести његове и законе његове и свједочанства његова, како је написано у закону Мојсијеву, да би напредовао у свему што узрадиш и за чим се год окренеш,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'Да би Господ испунио ријеч своју коју ми је рекао говорећи: ако успазе синови твоји на пут свој ходећи преда мном вјерно, свијем срцем својим и свом душом својом, тада ти не ће нестати човјека на пријестолу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'А ти знаш шта ми је учинио Јоав син Серујин, шта је учинио двјема војводама Израиљевијем, Авениру сину Нирову и Амаси сину Јетерову, које уби проливши у миру крв као у рату, и окаља крвљу као у рату појас свој око себе, и обућу своју на ногу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Учини дакле по мудрости својој, и немој дати да се сиједа глава његова спусти с миром у гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Синовима пак Варзелаја од Галада учини милост, и нека буду међу онима који једу за твојим столом, јер су тако дошли к мени кад сам бјежао од Авесалома брата твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'И ето, код тебе је Симеј син Гирин од Венијамина из Ваурима, који ме је љуто ружио кад иђах у Маханајим; али ми дође на сусрет на Јордан, и заклех му се Господом рекавши: нећу те убити мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Али му ти немој опростити, јер си мудар човјек и знаћеш шта ћеш му учинити, да оправиш сиједу главу његову с крвљу у гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Тако почину Давид код отаца својих, и би погребен у граду Давидову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'А царова Давид над Израиљем четрдесет година: у Хеврону царова седам година, а у Јерусалиму царова тридесет и три године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'И Соломун сједе на пријесто Давида оца својега, и царство се његово утврди јако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Тада дође Адонија син Агитин к Витсавеји матери Соломуновој; а она рече: јеси ли добро дошао? А он рече: добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Потом рече: имам нешто да ти кажем. А она рече: говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Тада рече: ти знаш да је моје било царство, и да је у мене био упро очи сав Израиљ да ја будем цар; али се царство пренесе и допаде брату мојему, јер му га Господ даде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Зато те сад молим за једно; немој ме одбити. А она му рече: говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'А он рече: говори цару Соломуну, јер ти он неће одбити, нека ми да за жену Ависагу Сунамку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'А Витсавеја рече: добро, ја ћу говорити цару за те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'И дође Витсавеја к цару Соломуну да му говори за Адонију; а цар уста и срете је и поклонив јој се сједе на свој пријесто, и заповједи те намјестише столицу матери његовој, и она сједе њему с десне стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Тада она рече: искала би од тебе једну малу ствар, немој ме одбити. А цар јој рече: ишти, мајко, нећу те одбити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Она рече: подај Ависагу Сунамку Адонији брату својему за жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'А цар Соломун одговори матери својој и рече: зашто иштеш Ависагу Сунамку за Адонију? ишти и царство за њ, јер је он брат мој старији и има уза се Авијатара свештеника и Јоава сина Серујина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'И закле се цар Соломун Господом говорећи: тако да ми учини Бог и тако да дода, себи на смрт каза то Адонија данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'И зато, тако да је жив Господ, који ме је утврдио и посадио ме на пријестолу Давида оца мојега, и који ми је начинио кућу као што је рекао, данас ће погинути Адонија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'И посла цар Соломун Венају сина Јодајева, који уложи на њ, те погибе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'А Авијатару свештенику рече цар: иди у Анатот на њиву своју, јер си заслужио смрт, али те нећу данас погубити, јер си носио ковчег Господњи пред Давидом оцем мојим и подносио си све невоље које је подносио отац мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Тако Соломун свргне Авијатара да не буде свештеник Господњи, да испуни ријеч Господњу што рече у Силому за дом Илијев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'И овај глас дође до Јоава; а Јоав бјеше пристао за Адонијом, премда за Авесаломом не бјеше пристао; и утече Јоав у шатор Господњи и ухвати се за рогове олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'И јавише цару Соломуну: Јоав утече у шатор Господњи, и ено га код олтара. А Соломун посла Венају сина Јодајева говорећи: иди, уложи на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'И ушав Венаја у шатор Господњи рече му: цар је казао: изиди. А он рече: нећу; него овдје хоћу да умрем. А Венаја јави цару говорећи: тако рече Јоав и тако ми одговори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'А цар му рече: учини како је рекао, уложи на њ, и погреби га, и скини с мене и с дома оца мојега крв праву коју је пролио Јоав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'И нека Господ обрати крв његову на његову главу, што уложи на два човјека праведнија и боља од себе, и уби их мачем без знања оца мојега Давида: Авенира сина Нирова војводу Израиљева и Амасу сина Јетерова војводу Јудина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Нека се дакле крв њихова врати на главу Јоавову и на главу сјемена његова довијека; а Давиду и сјемену његову и дому његову и пријестолу његову нека буде мир довијека од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'И отиде Венаја син Јодајев, и уложи на њ и погуби га, и би погребен код куће своје у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Тада постави цар Венају сина Јодајева на његово мјесто над војском, а Садока свештеника постави цар на мјесто Авијатарово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Потом посла цар и дозва Симеја, и рече му: сагради себи кућу у Јерусалиму, па ту сједи, и не излази одатле никуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Јер у који дан изидеш и пријеђеш преко потока Кедрона, знај зацијело да ћеш погинути, и крв ће твоја пасти на твоју главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'А Симеј рече цару: добра је та ријеч; како је рекао господар мој цар, тако ће учинити слуга твој. И сједе Симеј у Јерусалиму дуго времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Али се догоди послије три године, те утекоше двије слуге Симејеве к Ахису сину Машину цару Гатском. И би јављено Симеју: ено ти слугу у Гату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Тада уста Симеј, и осамари свога магарца, и отиде у Гат к Ахису да тражи слуге своје. И врати се Симеј, и доведе натраг слуге своје из Гата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'И јавише Соломуну да је Симеј био отишао из Јерусалима у Гат, и да се вратио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Тада цар послав дозва Симеја, и рече му: нијесам ли те заклео Господом и нијесам ли ти тврдо рекао: у који дан изидеш куда му драго, знај зацијело да ћеш погинути? И ти ми рече: добра је та ријеч коју чух.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Зашто дакле нијеси држао заклетве Господње и заповијести коју сам ти заповједио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Потом рече цар Симеју: ти знаш све зло за које зна срце твоје, што си учинио Давиду оцу мојему; Господ враћа твоје зло на твоју главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'А цар ће Соломун бити благословен и пријесто Давидов утврђен пред Господом довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'И заповједи цар Венаји сину Јодајеву, те изиде и уложи на њ, те погибе. И царство се утврди у руци Соломуновој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'А Соломун се опријатељи с фараоном царем Мисирским, и ожени се кћерју фараоновом, и доведе је у град Давидов докле не доврши свој дом и дом Господњи и зид око Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Али народ приношаше жртве на висинама; јер још не бјеше сазидан дом имену Господњему до тада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'А Соломун љубљаше Господа ходећи по уредбама оца својега Давида, само што на висинама приношаше жртве и кађаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Зато отиде цар у Гаваон да ондје принесе жртву, јер то бијаше велика висина; и Соломун принесе тисућу жртава паљеница на оном олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'И јави се Господ Соломуну у Гаваону ноћу у сну, и рече Бог: ишти што хоћеш да ти дам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'А Соломун рече: ти си учинио велику милост слузи својему Давиду оцу мојему, као што је ходио пред тобом вјерно и праведно и с правијем срцем према теби; и сачувао си му ову велику милост, те му дао сина да сједи на пријестолу његову, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'И тако, Господе Боже мој, ти си поставио слугу својега царем на мјесто Давида оца мојега, а ја сам млад, нити знам полазити ни долазити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'И твој је слуга међу народом твојим, који си изабрао, народом великим, који се не може избројити ни прорачунати од множине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Дај дакле слузи својему срце разумно да може судити народу твојему и распознавати добро и зло. Јер ко може судити народу твојему тако великом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'И би мило Господу што Соломун то заиска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'И рече му Бог: кад то иштеш, а не иштеш дуга живота нити иштеш блага нити иштеш душа непријатеља својих него иштеш разума да умијеш судити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'Ево учиних по твојим ријечима; ево ти дајем срце мудро и разумно да такога какав си ти ни прије тебе није било нити ће послије тебе настати таки какав си ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'А сврх тога дајем ти и што нијеси искао, и благо и славу, да такога какав ћеш ти бити неће бити међу царевима свега вијека твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'И ако узидеш мојим путовима држећи уредбе моје и заповијести моје, као што је ишао Давид отац твој, продуљићу дане твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Тада се пробуди Соломун, и гле, оно бјеше сан. И дође у Јерусалим, и ставши пред ковчег завјета Господњега принесе жртве паљенице и жртве захвалне, и почасти све слуге своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Тада дођоше двије жене курве к цару, и стадоше пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'И рече једна жена: ах, господару; ја и ова жена сједимо у једној кући, и породих се код ње у истој кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'А трећи дан послије мога порођаја породи се и ова жена, и бијасмо заједно и не бијаше нико други с нама у кући, само нас двије бијасмо у кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'И умрије син ове жене ноћас, јер она леже на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Па уставши у поноћи узе сина мојега искрај мене, кад слушкиња твоја спаваше, и стави га себи у наручје, а сина свога мртвога стави мени у наручје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'А кад устах ујутру да подојим сина својега, а то мртав; али кад разгледах ујутру, а то не бјеше мој син, којега ја родих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Тада рече друга жена: није тако; него је мој син овај живи, а твој је син онај мртви. Али она рече: није тако, него је твој син онај мртви, а мој је син овај живи. Тако говораху пред царем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'А цар рече: ова каже: овај је живи мој син, а твој је син овај мртви; а она каже: није тако, него је твој син онај мртви, а мој је син овај живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'И рече цар: дајте ми мач. И донесоше мач пред цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Тада рече цар: расијеците живо дијете на двоје, и подајте половину једној и половину другој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Тада жена којој син бјеше живи рече цару, јер јој се усколеба утроба за сином: ах, господару, подајте њојзи дијете живо, а немојте га убијати. А она рече: нека не буде ни мени ни теби, расијеците га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Тада одговори цар и рече: подајте оној живо дијете, немојте га убити, она му је мати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'И сав Израиљ чу суд који изрече цар, и побојаше се цара; јер видјеше да је у њему мудрост Божја да суди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'А цар Соломун цароваше над свијем Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'А ово бијаху кнезови његови: Азарија, син Садоков, намјесник;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Елиореф и Ахија, синови Сисини, писари; Јосафат, син Ахилудов, паметар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Венаја, син Јодајев, војвода; а Садок и Авијатар свештеници;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'А Азарија син Натанов, бјеше над приставима; а Завуд, син Натанов, први вијећник, пријатељ царев;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'А Ахисар управитељ дворски; а Адонирам син Авдин над царским посленицима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'И имаше Соломун дванаест пристава по свему Израиљу, који храњаху цара и сав дом његов; по мјесец дана у години сваки бијаше дужан хранити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'А ово су им имена: син Уров у гори Јефремовој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Син Декеров у Макасу и у Салвиму и Вет-Семесу и Елону Вет-ананском;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Син Еседов у Арувоту; под њим бијаше Сохот и сва земља Еферова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Син Авинадавов над свијем крајем Дорским; жена му бјеше Тафата кћи Соломунова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Вана син Ахилудов над Тенахом и Мегидоном и свијем Вет-Саном, који је до Сартане под Језраелом, од Вет-Сана до Авел-Меола, до преко Јок-Меама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Син Геверов у Рамоту Галадском; имаше села Јаира сина Манасијина у Галаду и крај Арговски у Васану, шездесет великих градова са зидовима и пријеворницама мједенијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ахинадав син Идов у Маханајиму;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ахимас у Нефталиму; и он бјеше ожењен кћерју Соломуновом Васематом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Вана син Хусајев у Асиру и у Алоту;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Јосафат син Фарујин у Исахару;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Симеј син Илин у Венијамину;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Гевер син Уријев у земљи Галадској, у земљи Сиона цара Аморејскога и Ога цара Васанскога; један бјеше пристав у тој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Јуде и Израиља бијаше много као пијеска покрај мора; и јеђаху и пијаху и весељаху се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'А Соломун владаше свијем царствима од ријеке до земље Филистејске и до међе Мисирске, и доношаху даре и служаху Соломуну свега вијека његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'А храна Соломунова бијаше на дан тридесет кора бијелога брашна, и шездесет кора другога брашна;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'Двадесет волова угојенијех и двадесет с паше, и сто оваца, осим јелена и срна и дивокоза и угојенијех птица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Јер он владаше свуда с ову страну ријеке од Тапсе до Газе, над свијем царствима с ову страну ријеке, и бјеше миран са свију страна унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'И живљаху Јуда и Израиљ без страха, сваки под својом лозом и под својом смоквом, од Дана до Вирсавеје, свега вијека Соломунова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'И имаше Соломун четрдесет тисућа коња за јаслима за кола своја, и двадесет тисућа коњика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'И пристави храњаху цара Соломуна и све који долажаху за сто цара Соломуна, сваки свога мјесеца, и не дадијаху да се чега премакне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'А јечам и сламу за коње и за мазге доношаху на мјесто гдје бијаху, сваки како му бијаше одређено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'И Бог даде мудрост Соломуну и разум врло велик и срце пространо као пијесак на бријегу морском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Јер мудрост Соломунова бијаше већа од мудрости свијех источнијех народа и од све мудрости Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Мудрији бијаше од свакога човјека, и од Етана Езраита и од Емана и од Халкола и од Дарде, синова Маоловијех; и разгласи се име његово по свијем народима унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'И изговори три тисуће прича, и бијаше пјесама његовијех тисућа и пет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Говорио је и о дрвећу, од кедра на Ливану до исопа који ниче из зида; говорио је и о стоци и о птицама и о бубинама и о рибама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'И долажаху од свијех народа да чују мудрост Соломунову, од свијех царстава на земљи, који чуше за мудрост његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'И Хирам цар Тирски посла слуге своје к Соломуну чувши да су га помазали за цара на мјесто оца његова, јер Хирам љубљаше Давида свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'А Соломун посла ка Хираму и поручи му:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Ти знаш да Давид отац мој није могао саградити дома имену Господа Бога својега од ратова којима га опколише, докле их Господ не положи под ноге његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'А сада Господ Бог мој дао ми је мир отсвуда, немам ниједнога непријатеља ни зле сметње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Зато, ево, велим да саградим дом имену Господа Бога својега, као што је рекао Господ Давиду оцу мојему говорећи: син твој, којега ћу посадити мјесто тебе на пријесто твој, он ће саградити дом имену мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Зато заповједи сада нека ми насијеку дрва кедровијех на Ливану, а слуге ће моје бити са слугама твојим, а плату слугама твојим даћу ти како год речеш; јер ти знаш да у нас нема људи који умију сјећи дрва као Сидонци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'И кад Хирам чу ријечи Соломунове, обрадова се веома и рече: да је благословен Господ данас, који даде Давиду мудра сина над онијем народом великим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'И посла Хирам Соломуну, и поручи: чуо сам чега ради си слао к мени; ја ћу учинити сву вољу твоју за дрва кедрова и за дрва јелова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Моје ће слуге снијети с Ливана на море, и ја ћу их повезати у сплавове и спустити морем до мјеста које ми кажеш, и ондје ћу развезати, па их носи; а ти ћеш учинити моју вољу и дати храну чељади мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'И тако даваше Хирам Соломуну дрва кедрова и дрва јелова, колико му бјеше воља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'А Соломун даваше Хираму двадесет тисућа кора пшенице за храну чељади његовој, и двадесет кора уља цијеђенога; толико даваше Соломун Хираму сваке године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'И Господ даде мудрост Соломуну како му бјеше обрекао, и бјеше мир између Хирама и Соломуна, и ухватише вјеру међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'И одреди Соломун људе из свега Израиља, и би одређенијех тридесет тисућа људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'И слаше их на Ливан по десет тисућа свакога мјесеца наизмјенце; један мјесец бијаху на Ливану, а два мјесеца код кућа својих. А Адонирам бјеше над овијем посланицима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'И имаше Соломун седамдесет тисућа носилаца и осамдесет тисућа тесача у планини,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Осим настојника Соломуновијех, који бијаху над тијем послом, три тисуће и триста, који управљаху народом који пословаше тај посао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'И заповједи цар да сносе велико камење, скупоцјено камење за темељ дому, тесано камење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'И тесаху посленици Соломунови и посленици Хирамови и Гивлеји, и приправљаху дрво и камење да се зида дом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Четири стотине и осамдесете године по изласку синова Израиљевијех из земље Мисирске, четврте године царовања Соломунова над Израиљем, мјесеца Зифа, а то је други мјесец, поче зидати дом Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'А дом што га зида цар Соломун Господу бијаше у дужину од шездесет лаката, а у ширину од двадесет лаката, а у висину од тридесет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'И бијаше тријем пред црквом двадесет лаката дуг, према ширини дома, а десет лаката широк пред домом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'И начини прозоре на дому изнутра широке а споља уске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'И уза зид дому начини ходнике свуда унаоколо уза зид дому око цркве и светиње над светињама, и начини клијети свуда унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Најдоњи ходник бјеше пет лаката широк, а средњи шест лаката широк, а трећи седам лаката широк; јер начини засјеке на дому споља унаоколо, да се греде не улажу у зид од дома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'А кад зидаху дом, зидаху од камена, који довожаху сасвијем приготовљен, те се ни чекић ни сјекира нити како оруђе гвоздено не чу у дому кад се зидаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Врата од средњега ходника бијаху на десној страни дома, и излажаше се на завојницу на средњи ходник, и из средњега на трећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Тако сазида дом, и доврши га, и покри дом гредама и даскама кедровијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'И начини ходнике око цијелога дома од пет лаката у висину сваки, и састављаху их с домом греде кедрове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Тада дође ријеч Господња Соломуну говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'То је дом што градиш; ако узидеш по мојим уредбама, и уствориш моје законе и уздржиш све моје заповјести ходећи по њима, потврдићу ти ријеч своју, коју сам рекао Давиду оцу твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'И становаћу међу синовима Израиљевијем, и нећу оставити народа својега Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'И тако сазида Соломун дом, и доврши га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'И обложи зидове дому изнутра даскама кедровијем, од пода дома до врх зидова обложи дрветом изнутра; и под дому обложи даскама јеловијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'И начини преграду од двадесет лаката од једне стране дома до друге од дасака кедровијех, од пода до врх зидова; и то начини унутра за шатор, за светињу над светињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'А дом, црква напријед, бијаше од четрдесет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'А по даскама кедровијем унутра у дому бјеху изрезане јабуке и цвјетови развијени, све од кедра тако да се не виђаше нигдје камен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'И светињу над светињама уреди унутра у дому, да се ондје намјести ковчег завјета Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'А светиња над светињама унутра бјеше двадесет лаката дуга, и двадесет лаката широка, и двадесет лаката висока, и обложи је чистијем златом; тако обложи и олтар од кедра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'И тако обложи Соломун дом изнутра чистијем златом, и затеже златне ланце пред светињом над светињама, коју такође обложи златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'И сав дом обложи златом; тако и сав олтар пред светињом над светињама обложи златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'А у светињи над светињама начини два херувима од дрвета маслинова; десет лаката бјеше висок сваки.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'А од пет лаката бјеше једно крило у херувима, и од пет лаката бјеше друго крило у херувима; десет лаката бјеше од краја једнога крила до краја другога крила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Тако и други херувим бијаше од десет лаката; једне мјере и једне направе бјеху оба херувима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Десет лаката бјеше висок један херувим, тако и други.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'И намјести херувиме усред унутрашњег дома, и раширише херувими крила своја тако да крило једнога тицаше у један зид а крило другога херувима тицаше у други зид, а усред дома тицаху крила једно у друго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'И обложи херувиме златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'А све зидове дому унаоколо искити резанијем херувимима и палмама и развијенијем цвјетовима изнутра и споља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'И под дому обложи златом изнутра и споља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'И на уласку у светињу над светињама начини двокрилна врата од дрвета маслинова, којима прагови с довратницима бјеху на пет углова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'И на тијем двокрилнијем вратима од дрвета маслинова изреза херувиме и палме и развијене цвјетове, и обложи их златом, и херувиме и палме обложи златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Тако и на уласку у цркву начини прагове од дрвета маслинова на четири игла;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'И врата двокрилна од дрвета јелова; на двије се стране отвараше једно крило, и на двије стране отвараше се друго крило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'И изреза на њима херувиме и палме и развијене цвјетове, и обложи златом све што бјеше изрезано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Потом начини тријем унутрашњи од три реда тесанога камена и једнога реда дрвета кедрова стругана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Четврте године мјесеца Зифа би постављен темељ дому Господњему;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'А једанаесте године мјесеца Вула, који је осми мјесец, сврши се дом са свијем стварима својим и са свијем што му припада. Тако га сазида за седам година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Потом зида Соломун себи дом тринаест година, и сврши га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Сазида и дом из шуме Ливанске, сто лаката дуг и педесет лаката широк и тридесет лаката висок, на четири реда ступова кедровијех, с гредама кедровијем сврх ступова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'И бјеше покривен дрветом кедровијем горе на гредама, које бијаху на четрдесет и пет ступова, по петнаест у једном реду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'И прозора бијаху три реда, прозор над прозором у три реда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'И сва врата и прагови бјеху на четири угла, и прозори, и један прозор бјеше према другом у три реда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'И начини тријем од ступова, педесет лаката дуг и тридесет лаката широк; и тај тријем бјеше спријед, и ступови и греде бијаху спријед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'И начини тријем у којем бјеше пријесто, гдје суђаше, тријем судски, који бијаше обложен кедром од пода до врха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'И у његовој кући гдје живљаше бијаше други тријем иза онога тријема, посао бијаше исти. Начини дом и кћери Фараоновој, којом се ожени Соломун, као тај тријем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Све ово бјеше од скупоцјенога камена, тесанога на мјеру и пилом сјеченога, изнутра и споља од пода до крова, и споља до великога тријема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'И темељ бијаше од камења скупоцјенога, камења великога, од десет лаката и од осам лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'А озго бијаше камење скупоцјено на мјеру тесано и даске кедрове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'И велики тријем унаоколо имаше три реда камења тесанога и један ред кедровијех брвана, као тријем унутрашњи дома Господњега и као тријем истога дома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'И посла цар Соломун и позва Хирама из Тира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'А он бијаше син једне удовице од племена Нефталимова а отац му бјеше из Тира, умјетник мједарски, врло вјешт и разуман, те умијаше свашта градити од мједи; он дошав к цару Соломуну изради му сав посао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Сали два ступа од мједи, један ступ бјеше од осамнаест лаката у висину а унаоколо од дванаест лаката; таки бјеше и други ступ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'И начини два оглавља да се метну озго на ступове, саливена од мједи; пет лаката бјеше високо једно оглавље и пет лаката бјеше високо друго оглавље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'И плетенице испреплетане и врвце као вериге начини на оглавља, која бијаху на врх ступова, седам на једно оглавље и седам на друго оглавље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Тако начини и на ступове и два реда шипака на једну плетеницу унаоколо да покривају оглавље које бијаше на врху; тако начини и на другом оглављу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'И на та два оглавља наврх ступова у тријему бијаху начињени љиљани од четири лакта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'И на два оглавља на два ступа бијаху озго и према средини под плетеницама шипци, којих бијаше двјеста у два реда унаоколо на једном и на другом оглављу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'И постави те ступове у тријему црквеном, и поставивши десни ступ назва га Јахин, потом поставише ступ лијеви назва га Воас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'И наврх ступова намјести израђено цвијеће љиљаново. И тако се свршише ступови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'И сали море; десет лаката бјеше му од једнога краја до другога, округло унаоколо, а пет лаката бјеше високо, а унаоколо му бјеше тридесет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'И испод краја његова бијаху испупчене као јабуке свуда унаоколо по десет на један лакат, којима бјеше опточено море унаоколо, два реда јабука бјеше саливено с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'И стајаше на дванаест волова; три гледаху на сјевер, три гледаху на запад, три гледаху на југ, а три гледаху на исток; а море стајаше на њима озго, и задња страна свијех њих бијаше унутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Дебљина му бијаше с подланице, а крај му бијаше као крај у чаше, као цвијет љиљанов, а примаше двије тисуће вата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'И начини десет подножја од мједи, у дужину од четири лакта бјеше свако подножје, а у ширину од четири лакта, а у висину од три лакта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'А направа бјеше у свакога подножја овака: оплата бијаше у њих унаоколо, и оплата бијаше између углова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'А на оплати међу угловима бијаху лавови и волови и херувими; а на угловима бијаше ступац озго, а испод лавова и волова бијаше вијенац кован.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'И под сваким подножјем бијаху по четири точка од мједи с плочама мједенијем, и на четири угла бијаху као рамена, и под сваком умиваоницом бијаху та рамена саливена према сваком вијенцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Дубина умиваоници од врха до дна над ступцем бијаше с лакта, и у врху бијаше округла као и ступац који бијаше од подруг лакта, и по врху јој бијаше резано, а оплата јој бијаше на четири угла, не округла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'И тако по четири точка бијаху под том оплатом, и осовине точковима излажаху на подножју, и сваки точак бијаше висок подруг лакта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'И направа у тијех точкова бијаше као направа у точкова колских; осовине њихове, главчине, наплаци и паоци, све бјеше ливено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'И четири рамена бијаху на четири угла у свакога подножја, из подножја излажаху његова рамена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'А озго у подножја бијаше висине по лакта, која бјеше свуда округла, и озго на подножју бјеху стране његове и оплате које излажаху из њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'И по странама његовијем и по оплатама његовијем изрезах херувиме, лавове и палме, једно до другога уз вијенце унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'На тај начин начини десет подножја; сва бијаху једнако саливена, једне мјере и једне направе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'И начини десет умиваоница од мједи; по четрдесет вата узимаше једна умиваоница, и свака умиваоница бијаше од четири лакта; по једна умиваоница стајаше на сваком подножју од десет подножја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'И намјести пет подножја на десној страни дома, и пет на лијевој страни дома, а море намјести на десну страну дома према истоку с југа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Тако начини Хирам умиваонице и лопате и котлиће; и сврши Хирам сав посао који ради цару Соломуну за дом Господњи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'Два ступа и два оглавља округла наврх два ступа, и двије плетенице да покривају она два оглавља округла наврх ступова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'И четири стотине шипака на двије плетенице; два реда шипака на свакој плетеници, да покривају два оглавља округла наврх ступова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'И десет подножја, и десет умиваоница на њима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'И море једно, и волова дванаест под морем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'И лонце и лопате и котлиће; а сви судови што начини Хирам цару Соломуну за дом Господњи бјеху од мједи углађене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'То је цар саливао у равници Јорданској у земљи иловачи између Сохота и Сартана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'И Соломун не измјери тијех судова, јер их бјеше врло много, не тражише тежине мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Начини Соломун и све друго посуђе за дом Господњи: златни олтар, и златни сто, на ком стајаху хљебови постављени,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'И пет свијетњака с десне стране и пет с лијеве стране пред светињом од чистога злата, и цвјетове и жишке и усекаче од злата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'И чаше и виљушке и котлиће и кадионице и машице од чистога злата; и чепови на вратима унутрашњега дома, светиње над светињама, и чепови на вратима црквенијем бијаху од злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'И тако се сврши сав посао који уради цар Соломун дому Господњему; и унесе Соломун што бјеше посветио Давид отац његов, сребро и злато и судове, и остави у ризницу дома Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Тада сабра Соломун старјешине Израиљеве и све главаре племенске, кнезова домова отачких синова Израиљевијех, к себи у Јерусалим да се пренесе ковчег завјета Господњега из града Давидова, а то је Сион.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'И скупише се к цару Соломуну сви људи Израиљеви мјесеца Етанима на празник, а тај је мјесец седми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'И кад дођоше све старјешине Израиљеве, подигоше свештеници ковчег;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'И пренесоше ковчег Господњи и шатор од састанка и све суде свете што бјеху у шатору; пренесоше их свештеници и Левити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'А цар Соломун и сав збор Израиљев, који се сабра к њему, принесоше с њим пред ковчегом оваца и говеда толико да се не могаше ни избројити ни прорачунати од мноштва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'И унесоше свештеници ковчег завјета Господњега на његово мјесто, у унутрашњи дом, у светињу над светињама, под крила херувимима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Јер херувимима бијаху раширена крила над мјестом гдје ће стајати ковчег, и заклањаху херувими ковчег и полуге његове озго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'И повукоше му полуге тако да се крајеви виђаху на предњој страни светиње над светињама, али се напоље не виђаху; и ондје осташе до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'У ковчегу не бјеше ништа осим двије плоче камене, које метну у њ Мојсије на Хориву, кад Господ учини завјет са синовима Израиљевијем на што изидоше из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'А кад свештеници изидоше из светиње, облак напуни дом Господњи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Те не могаху свештеници стајати да служе од облака; јер се славе Господње напуни дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Тада рече Соломун: Господ је рекао да ће наставати у мраку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Сазидах дом теби за стан, мјесто, да у њему наставаш довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'И окренувши се лицем својим цар благослови сав збор Израиљев, а сав збор Израиљев стајаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'И рече: благословен да је Господ Бог Израиљев, који је говорио својим устима Давиду оцу мојему и испунио руком својом говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Од онога дана кад изведох из Мисира народ свој Израиља не изабрах ниједнога града међу свијем племенима Израиљевијем да се сазида дом гдје би било име моје, него изабрах Давида да буде над народом мојим Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'И науми Давид отац мој да сазида дом имену Господа Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Али Господ рече Давиду оцу мојему: што си наумио сазидати дом имену мојему, добро си учинио што си то наумио;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Али нећеш ти сазидати тога дома, него син твој, који ће изаћи из бедара твојих, он ће сазидати дом имену мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'И тако испуни Господ ријеч своју коју рече; јер устах на мјесто оца својега Давида, и сједох на пријесто Израиљев, као што рече Господ, и сазидах овај дом имену Господа Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'И одредих овдје мјесто ковчегу у ком је завјет Господњи што је учинио с оцима нашим кад их је извео из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Потом стаде Соломун пред олтар Господњи пред свијем збором Израиљевијем, и подиже руке своје к небу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'И рече: Господе Боже Израиљев! нема Бога такога какав си ти горе на небу ни доље на земљи, који чуваш завјет и милост слугама својим, које ходе пред тобом свијем срцем својим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Који си испунио слузи својему Давиду оцу мојему што си му рекао; што си устима својим рекао то си руком својом испунио, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Сада дакле, Господе Боже Израиљев, држи слузи својему Давиду оцу мојему што си му рекао говорећи: неће ти нестати човјека испред мене који би сједио на пријестолу Израиљеву, само ако синови твоји ушчувају пут свој ходећи преда мном, као што си ти ходио преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Сада дакле, Боже Израиљев, нека се потврди ријеч твоја коју си рекао слузи својему Давиду оцу мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Али хоће ли доиста Бог становати на земљи? Ето, небо и небеса над небесима не могу те обухватити, а камо ли овај дом што га сазидах?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Али погледај на молитву слуге својега и на молбу његову, Господе Боже мој, чуј вику и молитву, којим ти се моли данас слуга твој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'Да буду очи твоје отворене над домом овијем дан и ноћ, над овијем мјестом, за које си рекао: ту ће бити име моје; да чујеш молитву којом ће се молити слуга твој на овом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Чуј молбу слуге својега и народа својега Израиља, којом ће се молити на овом мјесту; чуј с мјеста гдје станујеш, с неба, чуј, и смилуј се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Кад ко згријеши ближњему својему те му се да заклетва да се закуне, и заклетва дође пред твој олтар у овом дому,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Ти чуј с неба, и учини и суди слугама својим, осуђујући кривца и дјела његова обраћајући на његову главу, а правога правдајући и плаћајући му по правди његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Кад разбију непријатељи твоји народ твој Израиља зато што ти згријеше, па се обрате к теби и даду славу имену твојему, и помоле ти се и замоле те у овом дому,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Ти чуј с неба, и опрости гријех народу својему Израиљу, и доведи их опет у земљу коју си дао оцима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Кад се затвори небо, те не буде дажда зато што згријеше теби, па ти се замоле на овом мјесту и даду славу имену твојему, и од гријеха се својега обрате, кад их намучиш,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Ти чуј с неба, и опрости гријех слугама својим и народу својему Израиљу показав им пут добри којим ће ходити, и пусти дажд на земљу своју, коју си дао народу својему у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Кад буде глад у земљи, кад буде помор, суша, медљика, скакавци, гусјенице, или кад га притијесни непријатељ његов у земљи његовој властитој, или како год зло, кака год болест,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'Сваку молбу и сваку молитву, која буде од кога год човјека или од свега твојега народа Израиља, ко позна муку срца својега и подигне руке своје у овом дому,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Ти чуј с неба, из стана својега, и смилуј се и учини и подај свакоме по свијем путовима његовијем, које знаш у срцу његову; јер ти сам знаш срца свијех синова човјечијих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'Да те се боје докле су год живи на земљи коју си дао оцима нашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'И странац, који није од твојега народа Израиља, него дође из даљње земље имена твојега ради,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(Јер ће се чути за име твоје велико и за руку твоју крјепку и мишицу твоју подигнуту) кад дође и помоли се у овом дому,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Ти чуј с неба, из стана својега, и учини све за што повиче к теби онај странац, да би познали име твоје сви народи на земљи и бојали се тебе као народ твој Израиљ, и да би знали да је име твоје призвано над овијем домом, који сазидах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Кад народ твој изиде на војску на непријатеља својега путем којим га пошљеш, и помоле се Господу обративши се ка граду, који си изабрао, и к дому, који сам сазидао имену твојему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'Чуј с неба молбу њихову, и подај им правицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Кад ти згријеше, јер нема човјека који не гријеши, и разгњевивши се на њих даш их непријатељима њиховијем, те их заробе и одведу у земљу непријатељску далеко или близу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'Ако се дозову у земљи у коју буду одведени у ропство, и обрате се и стану ти се молити у земљи онијех који их заробише, и реку: сагријешисмо и зло учинисмо, скривисмо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'И тако се обрате к теби свим срцем својим и свом душом својом у земљи непријатеља својих, који их заробе, и помоле ти се окренувши се к земљи својој, коју си дао оцима њиховијем, ка граду, који си изабрао, и к дому, који сам сазидао имену твојему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Тада чуј с неба, из стана својега, молбу њихову и молитву њихову, и подај им правицу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'И опрости народу својему што ти буду згријешили, и све пријеступе којима ти буду преступили, и умилостиви им оне који их заробе да се смилују на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Јер су твој народ и твоје нашљедство, које си извео из Мисира, исред пећи гвоздене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Нека буду очи твоје отворене на молбу слуге твојега и на молбу народа твојега Израиља, и чуј их кад те год призову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Јер си их ти одвојио себи за нашљедство од свијех народа на земљи, као што си рекао преко Мојсија слуге својега, кад си извео оце наше из Мисира, Господе, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'А кад Соломун молећи се Господу сврши сву ову молбу и молитву, уста испред олтара Господњега, гдје бјеше клекао и руке своје подигао к небу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'И стојећи благослови сав збор Израиљев, гласом великим говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Благословен да је Господ који је смирио народ свој Израиља, као што је говорио; није изостала ни једна ријеч од свијех добријех ријечи његовијех, које је говорио преко Мојсија слуге својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Да Господ Бог наш буде с нама као што је био с оцима нашим, да нас не остави и не напусти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Него нека пригне срце наше к себи да бисмо ходили свијем путовима његовијем и држали заповијести његове и уредбе његове и законе његове, што је заповједио оцима нашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'И нека буду ове ријечи моје, којима се молих Господу, близу Господа Бога нашега дан и ноћ да би давао правицу слузи својему и народу својему Израиљу у свако доба;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'Да би познали сви народи на земљи да је Господ сам Бог и да нема другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'И нека срце ваше буде цијело према Господу Богу нашем, да ходите по уредбама његовијем и држите заповијести његове као данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Тада цар и сав Израиљ с њим принесоше жртве пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'И Соломун принесе на жртву захвалну, коју принесе Господу, двадесет и двије тисуће волова и сто и двадесет тисућа оваца. Тако посветише дом Господњи цар и сви синови Израиљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'У тај дан посвети цар средину тријема који је пред домом Господњим; јер ондје принесе жртве паљенице и даре и претилину од жртава захвалнијех; јер мједени олтар који бијаше пред Господом бијаше мален и не могаху на њ стати жртве паљенице и дари и претилина од жртава захвалнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'И у то вријеме празнова Соломун празник и сав Израиљ с њим, сабор велик од уласка у Емат до потока Мисирскога, пред Господом Богом нашим, седам дана и опет седам дана, то је четрнаест дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'А у осми дан отпусти народ; и благословише цара и отидоше к шаторима својим радујући се и веселећи се у срцу за све добро што учини Господ Давиду слузи својему и Израиљу народу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'А кад Соломун сврши дом Господњи и дом царски и све што жељаше Соломун и рад бијаше начинити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Јави се Господ Соломуну други пут, као што му се бјеше јавио у Гаваону;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'И рече му Господ: услишио сам молбу твоју и молитву твоју, којом си ми се молио; посветио сам тај дом који си сазидао да ту намјестим име своје довијека; и очи ће моје и срце моје бити ондје вазда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'А ти ако узидеш преда мном како је ишао Давид отац твој с цијелијем и правијем срцем творећи све што сам ти заповједио и држећи уредбе моје и законе моје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Утврдићу пријесто царства твојега над Израиљем навијек, као што сам казао Давиду оцу твојему говорећи: неће ти нестати човјека на пријестолу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Али ако се ви и синови ваши одвратите од мене и не уздржите заповијести мојих и уредаба мојих које сам вам дао, и отидете и станете служити другим боговима и клањати им се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'Тада ћу истријебити Израиља са земље, коју сам вам дао, и овај дом, који сам посветио имену својему, одбацићу од себе, и Израиљ ће постати прича и потсмијех међу свијем народима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'А дом овај колико је славан, ко год прође мимо њ, зачудиће се и запиштаће, и рећи ће: зашто учини Господ ово од ове земље и од овога дома?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'И одговараће се: јер одусташе Господа Бога својега, који изведе оце њихове из земље Мисирске, и узеше друге богове, и клањаше им се и служише им; зато пусти на њих Господ све ово зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'А кад прође двадесет година, у које сазида Соломун ова два дома, дом Господњи и дом царски,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'А Хирам цар Тирски даде Соломуну дрва кедровијех и дрва јеловијех и злата колико му год воља бјеше, тада цар Соломун даде Хираму двадесет градова у земљи Галилејској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'И дође Хирам из Тира да види градове које му даде Соломун, али не бише му по вољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Па рече: какви су то градови што си ми их дао, брате? И назва их: земља Кавул; и оста им то име до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'А Хирам бјеше послао цару сто и двадесет таланата злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'И тако цар Соломун одреди људе, те сазида дом Господњи и дом свој и Милон, и зидове око Јерусалима, и Асор и Мегидон и Гезер.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Јер Фараон цар Мисирски изиде и узе Гезер, и спали га огњем и поби Хананеје који живљаху у граду, и даде га у прћију кћери својој, жени Соломуновој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'А Соломун сазида Гезер и Вет-Орон доњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'И Валат и Тадмор у пустињи у земљи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'И све градове у којима Соломун имаше житнице, и градове у којима му бијаху кола, и градове у којима му бијаху коњици, и што год Соломуну би воља зидати у Јерусалиму и на Ливану и у свој земљи царства својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'И сав народ који бјеше остао од Амореја, Хетеја, Ферезеја, Јевеја и Јевусеја, који не бијаху од синова Израиљевијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'Синове њихове, који бјеху остали иза њих у земљи, којих не могаше синови Израиљеви истријебити, њих Соломун нагна да плаћају данак и робују до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'А од синова Израиљевијех не учини ни једнога робом, него бијаху војници и слуге његове и кнезови, војводе његове, и заповједници над колима његовијем и над коњицима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'И бјеше главнијех настојника над послом Соломуновијем пет стотина и педесет, који управљаху народом који рађаше посао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'А кћи Фараонова пресели се из града Давидова у дом свој, који јој сазида. Тада сазида и Милон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'И Соломун приношаше три пута на годину жртве паљенице и жртве захвалне на олтару који начини Господу, и кађаше на олтару који бјеше пред Господом, кад сврши дом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'И лађе начини цар Соломун у Есион-Гаверу, који је код Елота на бријегу Црвенога Мора у земљи Едомској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'И посла Хирам на тијем лађама слуге своје, лађаре вјеште мору, са слугама Соломуновијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'И дођоше у Офир, и узеше оданде злата четири стотине и двадесет таланата, и донесоше цару Соломуну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'А царица Савска чу глас о Соломуну и о имену Господњем, и дође да га искуша загонеткама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'И дође у Јерусалим са силном пратњом, с камилама које ношаху мириса и злата врло много и драгога камења; и дошавши к Соломуну говори с њим о свему што јој беше у срцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'И Соломун јој одговори на све ријечи њезине; не бјеше од цара сакривено ништа да јој не би одговорио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'А кад царица Савска видје сву мудрост Соломунову и дом који бјеше сазидао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'И јела на столу његову и станове слуга његовијех и дворбу дворана његовијех и одијело њихово, и пехарнике његове и жртве његове паљенице које приношаше у дому Господњем, она дође изван себе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Па рече цару: истина је што сам чула у својој земљи о стварима твојим и о мудрости твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Али не хтјех вјеровати што се говораше докле не дође и видим својим очима; а гле, ни пола ми није казано; твоја мудрост и доброта надвишује глас који сам слушала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Благо људима твојим, благо слугама твојим, који једнако стоје пред тобом и слушају мудрост твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Да је благословен Господ Бог твој којему си омилио, те те посади на пријесто Израиљев; јер Господ љуби Израиља увијек, и постави те царем да судиш и дијелиш правицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Потом даде цару сто и двадесет таланата злата и врло много мириса и драгога камења: нигда више не дође толико таких мириса колико даде царица Савска цару Соломуну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'И лађе Хирамове, које доношаху злато из Офира, донесоше из Офира врло много дрвета алмугима и драгога камења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'И начини цар од тога дрвета алмугима заграду у дому Господњем и у дому царском и харфе и псалтире за пјеваче; нигдје се више није довезло такога дрвета алмугима нити се видјело до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'А цар Соломун даде царици Савској што год зажеље и заиска осим онога што јој даде сам по могућству цара Соломуна. Потом она отиде и врати се у земљу своју са слугама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'А злата што дохођаше Соломуну сваке године, бјеше шест стотина и шездесет и шест таланата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Осим онога што дохођаше од трговаца и онијех који продаваху мирисе и од свијех царева Арапских и управитеља земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'И цар Соломун начини двјеста штитова од кованога злата, шест стотина сикала злата дајући на један штит:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'И три стотине малијех штитова од кованога злата, по три мине злата дајући на сваки штитић; и остави их цар у дому од шуме Ливанске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'И начини цар велик пријесто од слонове кости, и обложи га чистијем златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Шест басамака бјеше у пријестола, и врх округао бјеше озад на пријестолу, и ручице бјеху с обје стране сједишта, и два лава стајаху покрај тијех ручица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'И дванаест лавова стајаху на шест басамака отуд и одовуд. Не би таки начињен ни у којем царству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'И сви судови из којих пијаше цар Соломун бијаху златни, и сви судови у дому од шуме Ливанске бијаху од чистога злата; од сребра не бјеше ништа; сребро бјеше ништа за времена Соломунова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Јер цар имаше лађе Тарсиске на мору с лађама Хирамовијем: једанпут у три године враћаху се лађе Тарсиске доносећи злато и сребро, слонове кости, мајмуне и пауне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Тако цар Соломун бијаше већи од свијех царева земаљских богатсвом и мудрошћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'И из цијеле земље тражаху да виде Соломуна, да чују мудрост његову, коју му даде Господ у срце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'И доношаху му сви даре, судове сребрне и судове златне, и хаљине и оружје и мирисе и коње и мазге, сваке године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Тако накупи Соломун кола и коњика, и имаше тисућу и четири стотине кола и дванаест тисућа коњика, које разреди по градовима, гдје му бијаху кола, и код себе у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'И учини цар, те у Јерусалиму бијаше сребра као камења, и кедровијех дрва као дивљих смокава које расту по пољу, тако много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'И довођаху Соломуну коње из Мисира и свакојаки трг, јер трговци цареви узимаху трг различан за цијену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'И долажаху кола из Мисира по шест стотина сикала сребра, а коњ по сто и педесет. И тако сви цареви Хетејски и цареви Сирски добијаху коње преко њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Али цар Соломун љубљаше многе жене туђинке осим кћери фараонове, Моавке, Амонке, Едомке, Сидонке и Хетејке,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'Од овијех народа за које бјеше рекао Господ синовима Израиљевијем: не идите к њима и они да не долазе к вама, јер ће занијети срце ваше за својим боговима. За њих приону Соломун љубећи их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Те имаше жена царица седам стотина, и три стотина иноча; и жене његове занесоше срце његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'И кад остарје Соломун, жене занесоше срце његово за туђим боговима; и срце његово не би цијело према Господу Богу његову као што је било срце Давида оца његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'И Соломун хођаше за Астаротом, богињом Сидонском, и за Мелхомом, гадом Амонским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'И чињаше Соломун што бјеше зло пред Господом, и не хођаше сасвијем за Господом као Давид отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Тада сагради Соломун висину Хемосу, гаду Моавском, на гори према Јерусалиму, и Молоху гаду Амонском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Тако учини свијем женама туђинкама, те кађаху и приношаху жртве својим боговима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'А Господ се разгњеви на Соломуна што се одврати срце његово од Господа Бога Израиљева, који му се бјеше јавио два пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'И бјеше му заповједио да не иде за другим боговима, а он не одржа што му Господ заповједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'И рече Господ Соломуну: што се то нађе на теби, и нијеси држао завјета мојега ни уредаба мојих, које сам ти заповједио, зато ћу отргнути од тебе царство и даћу га слузи твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Али за твојега вијека нећу то учинити ради Давида оца твојега; него ћу га отргнути из руку сина твојега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Али нећу отргнути свега царства; једно ћу племе дати сину твојему ради Давида слуге својега и ради Јерусалима, који изабрах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'И подиже Господ противника Соломуну, Адада Идумејца, који бијаше од царскога рода у Идумеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Јер кад Давид бијаше у Идумеји и Јоав војвода дође да покопа побијене, поби све мушкиње у Идумеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, 'Јер Јоав оста ондје шест мјесеца са свијем Израиљем докле не поби све мушкиње у Идумеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Тада утече Адад с неколико Идумејаца слуга оца својега, и отиде у Мисир; а Адад бјеше тада дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'И отишавши из Мадијама дођоше у Фаран; и узевши са собом људи из Фарана дођоше у Мисир к Фараону цару Мисирском, који му даде кућу и одреди му храну, и даде му и земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'И Адад нађе велику милост у Фараона, те га ожени сестром жене своје, сестром царице Тахпенесе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'И сестра Тахпенесина роди му сина Генувата, којега отхрани Тахпенеса у двору Фараонову, и бјеше Генуват у двору Фараонову међу синовима Фараоновијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'А кад Адад чу у Мисиру да је Давид починуо код отаца својих и да је умро Јоав војвода, рече Адад Фараону: пусти ме да идем у своју земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'А Фараон му рече: а шта ти је мало код мене, те хоћеш да идеш у своју земљу? А он рече: ништа; али ме пусти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Подиже му Бог још једнога противника, Резона сина Елијадина, који бјеше побјегао од господара својега Адад-Езера цара Совскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'И скупив к себи људе поста старјешина од чете кад их Давид убијаше; потом отишавши у Дамаск осташе ондје и обладаше Дамаском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'И бјеше противник Израиљев свега вијека Соломунова, и то осим зла које чињаше Адад; и мржаше на Израиља царујући у Сирији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'И Јеровоам син Наватов Ефраћанин из Сариде, чија мати бјеше по имену Серуја жена удовица, слуга Соломунов, подиже се на цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'А ово би узрок зашто се подиже на цара: Соломун грађаше Милон и зазиђиваше пролом града Давида оца својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'А Јеровоам бјеше крјепак и храбар; зато видјећи Соломун младића да настаје за послом постави га над свијем данцима дома Јосифова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Па у то вријеме кад Јеровоам отиде из Јерусалима, нађе га на путу Ахија Силомљанин пророк имајући на себи нову хаљину, и бијаху њих двојица сами у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'И Ахија узе нову хаљину која бјеше на њему, и раздрије је на дванаест комада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'И рече Јеровоаму: узми десет комада; јер овако вели Господ Бог Израиљев: ево истргнућу царство из руке Соломунове, и даћу теби десет племена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Само ће једно племе остати њему ради слуге мојега Давида и ради града Јерусалима, који изабрах између свијех племена Израиљевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Јер оставише мене и поклонише се Астароти богињи Сидонској и Хемосу богу Моавском и Мелхому богу синова Амоновијех, и не ходише путевима мојим чинећи што је право преда мном, уредбе моје и законе моје, као Давид отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Али нећу узети царства из руку његовијех, него ћу га оставити нека влада докле је год жив Давида ради слуге својега, којега изабрах, који је држао заповијести моје и уредбе моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Него ћу узети царство из руку сина његова, и даћу теби од њега десет племена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'А сину ћу његову дати једно племе да буде видјело Давиду слузи мојему вазда преда мном у граду Јерусалиму, који изабрах да у њему намјестим име своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Тебе ћу дакле узети да царујеш над свијем што ти душа жели, и бићеш цар над Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'И ако узаслушаш све што ти заповједим, и узидеш мојим путовима и ушчиниш што је право преда мном, држећи уредбе моје и заповијести моје, као што је чинио Давид слуга мој, бићу с тобом и сазидаћу ти тврд дом, као што сам сазидао Давиду, и даћу ти Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'И мучићу сјеме Давидиво за то, али не свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Зато тражаше Соломун да убије Јеровоама; али се Јеровоам подиже и побјеже у Мисир к Сисаку цару Мисирском, и би у Мисиру докле не умрије Соломун.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'А остала дјела Соломунова и што је год чинио, и мудрост његова, није ли то записано у књизи дјела Соломуновијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'А царова Соломун у Јерусалиму над свијем Израиљем четрдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'И почину Соломун код отаца својих, и би погребен у граду Давида оца својега; а Ровоам син његов зацари се на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Тада отиде Ровоам у Сихем: јер се ондје скупи сав Израиљ да га зацаре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'А Јеровоам син Наватов, који још бијаше у Мисиру побјегавши онамо од цара Соломуна, кад чу, он још оста у Мисиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Али послаше и дозваше га. Тако Јеровоам и сав збор Израиљев дођоше и рекоше Ровоаму говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Твој је отац метнуо на нас тежак јарам; него ти сада олакшај љуту службу оца својега и тешки јарам који је метнуо на нас, пак ћемо ти служити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'А он им рече: идите, па до три дана дођите опет к мени. И народ отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Тада цар Ровоам учини вијеће са старцима који стајаше пред Соломуном оцем његовијем док бијаше жив, и рече: како свјетујете да одговорим народу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'А они му одговорише говорећи: ако данас угодиш народу и послушаш их и одговориш им лијепим ријечима, они ће ти бити слуге свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Али он остави свјет што га свјетоваше старци, и учини вијеће са младићима, који одрастоше с њим и који стајаху пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'И рече им: шта ви свјетујете да одговоримо народу, који ми рекоше говорећи: олакшај јарам који је метнуо на нас твој отац?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Тада му одговорише младићи који одрастоше с њим, и рекоше: овако кажи народу што ти рече: твој је отац метнуо на нас тежак јарам, него нам ти олакшај; овако им реци: мој је мали прст дебљи од бедара оца мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Отац је мој метнуо на вас тежак јарам, а ја ћу још дометнути на ваш јарам; отац вас је мој шибао бичевима, а ја ћу вас шибати бодљивијем бичевима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'А трећи дан дође Јеровоам и сав народ к Ровоаму, како им бјеше казао цар рекавши: дођите опет к мени до три дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'И цар одговори оштро народу оставивши свјет што га свјетоваше старци;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'И рече им како га свјетоваше младићи говорећи: мој је отац метнуо на вас тежак јарам, а ја ћу још дометнути на ваш јарам; отац вас је мој шибао бичевима, а ја ћу вас шибати бодљивијем бичевима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'И цар оглуши се народа, јер Господ бјеше тако уредио да би потврдио ријеч своју што је рекао преко Ахије Силомљанина Јеровоаму сину Наватову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'А кад видје сав Израиљ гдје их се цар оглуши, одговори народ цару говорећи: какав дио ми имамо с Давидом? немамо нашљедства са сином Јесејевим. У шаторе своје, Израиљу! а ти Давиде, сад гледај своју кућу. Тако отиде Израиљ у шаторе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Само над синовима Израиљевијем, који живљаху по градовима Јудиним, зацари се Ровоам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'И цар Ровоам посла Адорама који бијаше над данком; али га сав Израиљ засу камењем, те погибе; а цар Ровоам брже сједе на кола, те побјеже у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Тако отпаде Израиљ од дома Давидова до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'И кад чу сав Израиљ да се вратио Јеровоам, пославши дозваше га на скупштину, и поставише га царем над свијем Израиљем. Не приста за домом Давидовијем ни једно племе осим самога племена Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'А Ровоам дошав у Јерусалим сазва сав дом Јудин и племе Венијаминово, сто и осамдесет тисућа одабранијех војника, да завојште на дом Израиљев да поврате царство Ровоаму сину Соломунову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Али дође ријеч Божја Семеју, човјеку Божијему, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Кажи Ровоаму сину Соломунову цару Јудину и свему дому Јудину и Венијаминову и осталоме народу, и реци:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Овако вели Господ: не идите, и не бијте се с браћом својом, синовима Израиљевијем; вратите се свак својој кући, јер сам ја наредио тако да буде. И они послушаше ријеч Господњу и вративши се отидоше како Господ рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Потом сазида Јеровоам Сихем у гори Јефремовој и насели се у њему; а послије отиде оданде и сазида Фануил.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'И рече Јеровоам у срцу свом: може се царство повратити дому Давидову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Ако овај народ стане ићи у Јерусалим да приноси жртве у дому Господњем, срце ће се народу обратити ка господару његову Ровоаму цару Јудину, те ће ме убити, и повратиће се к Ровоаму цару Јудину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Зато цар смисли, те начини два телета од злата, па рече народу: не треба више да идете у Јерусалим; ево богова твојих, Израиљу, који су те извели из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'И намјести једно у Ветиљу а друго намјести до Дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'И то би на гријех, јер народ иђаше к једноме од Дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'И начини кућу на висини, и постави свештенике од простога народа који не бијаху од синова Левијевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'И учини Јеровоам празник осмога мјесеца петнаестога дана, као што је празник у земљи Јудиној, и принесе жртве на олтару; тако учини и у Ветиљу приносећи жртве теоцима које начини; и постави у Ветиљу свештенике висинама које начини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'И петнаестога дана осмога мјесеца, који бјеше смислио у срцу свом, приношаше жртве на олтару који начини у Ветиљу, и празноваше празник са синовима Израиљевијем, и приступи к олтару да кади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'А гле, човјек Божји дође из земље Јудине с ријечју Господњом у Ветиљ, кад Јеровоам стајаше код олтара да кади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'И повика пут олтара ријечју Господњом говорећи: олтаре! олтаре! Овако вели Господ: ево, родиће се син дому Давидову по имену Јосија, који ће на теби клати свештенике висина, који каде на теби, и људске ће кости спалити на теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'И учини знак истога дана говорећи: ово је знак да је Господ то рекао: ето, олтар ће се распасти и просуће се пепео што је на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'А кад цар Јеровоам чу ријечи човјека Божијега које викаше олтару Ветиљском, пружи руку своју с олтара говорећи: држите га! Али усахну му рука коју пружи на њ, и не могаше је повратити к себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'А олтар се распаде, и просу се пепео с олтара по знаку који учини човјек Божји ријечју Господњом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Тада цар рече човјеку Божијему: припадни ка Господу Богу својему, и помоли се за ме да ми се поврати рука. И човјек се Божји помоли Господу, и поврати се цару рука и поста као што је била.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'И рече цар човјеку Божијему: ходи са мном кући мојој, и поткријепи се, и даћу ти дар. Али човјек Божји рече цару: да ми даш по куће своје, не бих ишао с тобом нити бих јео хљеба ни воде пио у овом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Али човјек Божји рече цару: да ми даш по куће своје, не бих ишао с тобом нити бих јео хљеба ни воде пио у овом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Јер ми је тако заповједио својом ријечју Господ говорећи: не једи хљеба ни пиј воде, нити се враћај истијем путем којим отидеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'И отиде другим путем, а не врати се онијем којим бјеше дошао у Ветиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'А у Ветиљу живљаше један стар пророк, којему дође син његов и приповједи све што учини пророк Божји онај дан у Ветиљу, и ријечи које рече цару; и приповједише синови тога пророка оцу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'А отац им рече: којим је путем отишао? И показаше синови пут којим отиде човјек Божји који бјеше дошао из земље Јудине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'А он рече синовима својим: осамарите ми магарца. И осамарише му магарца, те усједе на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'И пође за човјеком Божјим, и нађе га а он сједи под храстом, па му рече: јеси ли ти човјек Божји што дође из земље Јудине? Он му одговори: ја сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'А он му рече: ходи са мном мојој кући да једеш хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Али он одговори: не могу се вратити с тобом ни ићи с тобом; нити ћу јести хљеба ни пити воде с тобом у овом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Јер ми је речено ријечју Господњом: не једи хљеба ни пиј воде ондје, нити се враћај путем којим отидеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'А он му рече: и ја сам пророк као ти, и анђео Господњи рече ми ријечју Господњом говорећи: врати га са собом у своју кућу нека једе хљеба и пије воде. Али му слага.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'И врати се с њим, те једе хљеба у његовој кући и пи воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'А кад сјеђаху за столом, дође ријеч Господња пророку који га бјеше вратио;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'И повика на човјека Божјега који бјеше дошао из земље Јудине, и рече: овако вели Господ: што нијеси послушао ријечи Господње, и нијеси држао заповјести коју ти је заповједио Господ Бог твој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'Него си се вратио и јео хљеба и пио воде на мјесту за које ти је рекао: не једи хљеба ни пиј воде; зато неће твоје тијело доћи у гроб твојих отаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'И пошто се пророк којега бјеше вратио наједе хљеба и пошто се напи, осамари му магарца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'А кад отиде, удеси га лав на путу и закла га. И тијело његово лежаше на путу, и магарац стајаше код њега; такође и лав стајаше код тијела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'И гле, људи пролазећи видјеше тијело гдје лежи на путу и лава гдје стоји код тијела, и дошавши јавише у граду у којем живљаше стари пророк.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'А кад то чу пророк који га бјеше вратио с пута, рече: оно је човјек Божји, који не послуша ријечи Господње, зато га даде Господ лаву да га растргне и усмрти по ријечи Господњој коју му рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'И рече синовима својим говорећи: осамарите ми магарца. И осамарише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'И отишав нађе тијело гдје лежи на путу, и магарца и лава гдје стоје код тијела: лав не бјеше изјео тијела ни магарца растргао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Тада пророк подиже тијело човјека Божијега, и метнув га на магарца, однесе га натраг, и дође у град стари пророк да га ожали и погребе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'И метну тијело у свој гроб, и плакаху над њим говорећи: јаох брате!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'А пошто га погребе, рече синовима својим говорећи: кад умрем, погребите ме у гробу гдје је погребен човјек Божји, покрај костију његовијех метните кости моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Јер ће се зацијело збити што је огласио по ријечи Господњој за олтар Ветиљски и за све куће висина које су по градовима Самаријским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Пошто ово би, опет се Јеровоам не врати са својега злога пута; него опет начини из простога народа свештенике висинама; ко год хоћаше, томе он посвећиваше руке и тај постајаше свештеник висинама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'И то би на гријех дому Јеровоамову да би се истријебио и да би га нестало са земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'У то вријеме разбоље се Авија син Јеровоамов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'И Јеровоам рече жени својој: устани и преобуци се да те не познаду да си жена Јеровоамова; пак иди у Силом. Ето, ондје је Ахија пророк, који ми је казао да ћу бити цар над овијем народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'И понеси десет хљебова и колача и жбан меда, па отиди к њему; он ће ти казати шта ће бити од дјетета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'И учини тако жена Јеровоамова, и уставши отиде у Силом и уђе у кућу Ахијину. Ахија пак не могаше видјети, јер му очи бијаху потамњеле од старости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Али Господ рече Ахији: ето иде жена Јеровоамова да те пита за сина својега, јер је болестан; ти јој кажи то и то; а кад она дође учиниће се да је друга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'И Ахија чувши шуштање ногу њезинијех кад уђе на врата, рече: ходи, жено Јеровоамова; што се чиниш да си друга? Ја сам послан к теби да ти зло кажем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Иди, реци Јеровоаму: овако вели Господ Бог Израиљев: што сам те подигао између народа и поставио те вођем народу својему Израиљу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'И отргав царство од дома Давидова дадох теби, а ти не би као слуга мој Давид, који је држао заповијести моје и ходио за мном свијем срцем својим чинећи само што је право преда мном;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Него си радио горе од свијех који бише прије тебе, и отишао си и начинио себи друге богове и ликове ливене да би ме дражио, па си ме бацио на леђа своја;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Зато, ево, ја ћу пустити зло на дом Јеровоамов, и истријебићу Јеровоаму и оно што мокри уза зид, и ухваћенога и остављенога у Израиљу, и дом ћу Јеровоамов омести као што се мете као, да га не остане ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Ко Јеровоамов погине у граду, изјешће га пси, а ко погине у пољу, изјешће га птице небеске; јер Господ рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'А ти устани, иди кући својој; и кад ступиш ногама својим у град, одмах ће умријети дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'И сав ће Израиљ плакати за њим, и погрепшће га; јер ће он сам од дома Јеровоамова доћи у гроб, јер се на њему самом у дому Јеровоамову нађе нешто добра пред Господом Богом Израиљевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'А Господ ће подигнути себи цара над Израиљем, који ће истријебити дом Јеровоамов у онај дан; да, шта? сад већ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'И удариће Господ Израиља да ће се заљуљати као што се љуља трска у води, и ишчупаће Израиља из ове добре земље, коју је дао оцима њиховијем, и разасуће их далеко преко ријеке зато што начинише себи лугове гњевећи Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'И напустиће Израиља за гријехе Јеровоамове, којима је гријешио и на гријех навео Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Тада уста жена Јеровоамова, и отиде и дође у Терсу; и кад ступи на праг кућни умрије дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'И погребоше га, и сав Израиљ плака за њим по ријечи Господњој, коју рече преко слуге својега Ахије пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'А остала дјела Јеровоамова, како је војевао и како је царовао, ено записана су у дневнику царева Израиљевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'А царова Јеровоам двадесет и двије године; и почину код отаца својих, а Надав син његов зацари се на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'А Ровоам син Соломунов цароваше над Јудом; бјеше Ровоаму четрдесет и једна година кад поче царовати, и царова седамнаест у Јерусалиму граду, који изабра Господ између свијех племена Израиљевијех да ондје намјести име своје. Матери његовој бјеше име Нама Амонка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'И Јуда чињаше што је зло пред Господом; и гријесима својим којим гријешаху дражише га већма него оци њихови свијем што чинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Јер и они начинише себи висине и ступове и лугове на сваком високом хуму и под сваким зеленим дрветом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'А бијаше и аџувана у земљи, и чињаху све гадове народа које бјеше истјерао Господ испред синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'А пете године царовања Ровоамова дође Сисак цар Мисирски на Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'И узе благо из дома Господњега и благо из дома царева, све то узе; и узе све штитове златне које начини Соломун.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'И на њихово мјесто начини цар Ровоам штитове од мједи, и предаде их старјешинама над стражарима, који чуваху врата дома царева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'И кад цар иђаше у дом Господњи, ношаху их стражари, а послије их опет остављаху у ризницу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'А остала дјела Ровоамова, и све што је чинио, није ли записано у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'А бијаше рат између Ровоама и Јеровоама једнако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'И почину Ровоам код отаца својих, и би погребен код отаца својих у граду Давидову. А име метери његовој бјеше Нама Амонка. А на мјесто његово зацари се Авијам син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'А осамнаесте године царовања Јеровоама сина Наватова зацари се Авијам над Јудом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'И царова три године у Јерусалиму. А матери му бјеше име Маха кћи Авесаломова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Он хођаше у свијем гријесима оца својега, које је чинио пред њим, и не бјеше срце његово цијело према Господу Богу његову као срце Давида оца његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Али ради Давида даде му Господ Бог његов видјело у Јерусалиму подигав сина његова након њега и утврдив Јерусалим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Јер је Давид чинио што је право пред Господом нити је отступао од свега што му је заповједио свега вијека својега осим ствари с Уријом Хетејином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'А рат бјеше између Ровоама и Јеровоама до његова вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'А остала дјела Авијамова и све што је чинио није ли записано у дневнику царева Јудинијех? А бијаше рат између Авијама и Јеровоама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'И Авијам почину код отаца својих, и погребоше га у граду Давидову, а на његово мјесто зацари се Аса син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Године двадесете царовања Јеровоама над Израиљем зацари се Аса над Јудом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Четрдесет и једну годину царова у Јерусалиму. А матери му бјеше име Маха кћи Авесаломова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'И твораше Аса што је право пред Господом као Давид отац му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Јер истријеби аџуване из земље и укину све гадне богове које бјеху начинили оци његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'И матер своју Маху сврже с власти, јер она начини идола у лугу; и Аса изломи идола и сажеже на потоку Кедрону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Али висине не бише оборене; али срце Асино бјеше цијело према Господу свега вијека његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'И унесе у дом Господњи што бјеше посветио отац његов и што он посвети, сребро и злато и судове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'И бјеше рат између Асе и Васе цара Израиљева свега вијека њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Јер Васа цар Израиљев изиде на Јуду и стаде зидати Раму да не да никоме отићи к Аси цару Јудину ни од њега доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Али Аса узев све сребро и злато што бјеше остало у ризници Господњој и у ризници дома царева даде га слугама својим, и посла их цар Аса Вен-Ададу сину Тавримона сина Есионова, цару Сирском, који становаше у Дамаску, и поручи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Вјера је између мене и тебе, између оца твојега и оца мојега; ево шаљем ти дар, сребро и злато; хајде, поквари вјеру коју имаш са Васом царем Израиљевим, еда би отишао од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'И послуша Вен-Адад цара Асу, и посла војводе своје на градове Израиљеве и покори Ијон и Дан и Авел-Ветмаху и сав Хинерот и сву земљу Нефталимову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'А кад Васа то чу, преста зидати Раму, и врати се у Терсу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Тада цар Аса сазва сав народ Јудин, никога не изузимајући; те однесоше камење из Раме и дрва, чим зидаше Васа, и од њега сазида цар Аса Геву Венијаминову и Миспу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'А остала сва дјела Асина и сва јунаштва његова, и што је год чинио и које је градове саградио, није ли све записано у дневнику царева Јудинијех? Али у старости својој боловаше од ногу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'И Аса почину код отаца својих, и би погребен код отаца својих у граду Давида оца својега. А на његово мјесто зацари се Јосафат син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'А Надав син Јеровоамов поче царовати над Израиљем друге године царовања Асина над Јудом; и царова над Израиљем двије године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'И чињаше што је зло пред Господом ходећи путем оца својега и у гријеху његову, којим наведе на гријех Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'И подиже на њ буну Васа син Ахијин од дома Исахарова, и уби га Васа код Гиветона, који бијаше Филистејски, кад Надав и сав Израиљ бјеху опколили Гиветон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'И тако га уби Васа треће године царовања Асина над Јудом, и зацари се на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'А кад се зацари, поби сав дом Јеровоамов, и не остави ни једне душе од рода Јеровоамова докле све не истријеби по ријечи Господњој, коју рече преко слуге својега Ахије Силомљанина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'За гријехе Јеровоамове, којима је гријешио и којима је на гријех навео Израиља, и за дражење којим је дражио Господа Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'А остала дјела Надавова и све што је чинио, није ли то записано у дневнику царева Израиљевијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'И бјеше рат између Асе и Васе цара Израиљева свега вијека њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Треће године царовања Асина над Јудом зацари се Васа син Ахијин над свијем Израиљем у Терси, и царова двадесет и четири године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'И чињаше што је зло пред Господом ходећи путем Јеровоамовијем и у гријеху његову, којим наведе на гријех Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'И дође ријеч Господња Јују сину Ананијеву за Васу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Што те подигох из праха и поставих вођом народу својему Израиљу, а ти идеш путем Јеровоамовијем и наводиш на гријех народ мој Израиља да ме гњеви гријесима својим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Ево, ја ћу затрти натражје Васино и натражје дома његова, и учинићу с домом твојим као с домом Јеровоама сина Наватова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Ко Васин погине у граду, изјешће га пси, а ко погине у пољу, изјешће га птице небеске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'А остала дјела Васина и што је чинио, и јунаштво његово, није ли то записано у дневнику царева Израиљевијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'И почину Васа код отаца својих, и би погребен у Терси; а на његово мјесто зацари се Ила син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'И тако преко пророка Јуја сина Ананијева дође ријеч Господња против Васе и дома његова за све зло што учини пред Господом гњевећи га дјелима својих руку, те би као дом Јеровоамов, и зато што га поби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Двадесет шесте године царовања Асина над Јудом зацари се Ила син Васин над Израиљем, и царова двије године у Терси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'А слуга његов Зимрије, старјешина над половином кола, диже буну на Илу, кад пијаше у Терси и опи се у кући Арсе, који управљаше домом његовим у Терси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'И дође Зимрије и уби га и погуби га двадесет осме године царовања Асина над Јудом, и зацари се на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'А чим се зацари и сједе на пријесто свој, поби сав дом Васин, не остави му ни што уза зид мокри, и родбину његову и пријатеље његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Тако Зимрије затр сав дом Васин по ријечи Господњој коју рече за Васу преко Јуја пророка,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'За све гријехе Васине и за гријехе Иле сина његова, којима гријешише и којима на гријех наводише Израиља гњевећи Господа Бога Израиљева таштинама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'А остала дјела Илина и све што је чинио, није ли то записано у дневнику царева Израиљевих?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Године двадесет седме царовања Асина над Јудом зацари се Зимрије, и царова седам дана у Терси; а народ тада стајаше у околу код Гиветона, који бјеше Филистејски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'И народ што бјеше у околу кад чу да је Зимрије дигао буну и цара убио, исти дан сав Израиљ у околу постави царем над Израиљем Амрија војводу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'И Амрије и сав Израиљ с њим отидоше од Гиветона и опколише Терсу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'А Зимрије кад видје гдје освојише град, отиде у двор царски, и запали над собом двор царски, те погибе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'За гријехе своје којима је гријешио чинећи што је зло пред Господом, ходећи путем Јеромоамовијем и у гријеху његову, којим је гријешио наводећи на гријех Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'А остала дјела Зимријева и буна коју подиже, није ли то записано у дневнику царева Израиљевих?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Тада се раздијели народ Израиљев на двоје: половина народа приста за Тивнијом сином Гинатовијем да га учини царем, а друга половина приста за Амријем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Али народ који приста за Амријем би јачи од народа који приста за Тивнијом сином Гинатовијем. И умрије Тивнија, а царова Амрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Тридесет прве године царовања Асина над Јудом поче царовати Амрије над Израиљем, и царова дванаест година; у Терси царова шест година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'И купи гору Самаријску од Семера за два таланта сребра, и сагради град на гори, и назва град који сагради Самарија по имену Семера господара од горе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'А Амрије чињаше што је зло пред Господом, и горе чињаше од свијех који бијаху прије њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Јер хођаше свијем путовима Јеровоама сина Наватова и у гријеху његову, којим је навео на гријех Израиља гњевећи Господа Бога Израиљева таштинама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'А остала дјела Амријева и све што је чинио, и јунаштва која је чинио, није ли то записано у дневнику царева Израиљевијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'И почину Амрије код отаца својих, и би погребен у Самарији; а на његово се мјесто зацари Ахав син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'И Ахав син Амријев поче царовати над Израиљем тридесет осме године царовања Асина над Јудом, и царова Ахав син Амријев над Израиљем у Самарији двадесет и двије године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'И чињаше Ахав син Амријев што је зло пред Господом, више од свијех који бијаху прије њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'И мало му бијаше што хођаше у гријесима Јеровоама сина Наватова, него се још ожени Језавељом кћерју Етвала цара Сидонскога, и отиде, те служаше Валу и клањаше му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'И начини олтар Валу у дому Валову који сазида у Самарији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'И начини Ахав гај, и учини Ахав више од свијех царева Израиљевијех који бијаше прије њега, да би разгњевио Господа Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'За његова времена Хил Ветиљанин сазида Јерихон. На Авирону првенцу својему основа га, а на Сегуву мјезинцу својему метну му врата по ријечи Господњој, коју рече преко Исуса сина Навина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Тада рече Ахаву Илија Тесвићанин, један од насељеника Галадских: тако да је жив Господ Бог Израиљев, пред којим стојим, овијех година неће бити росе ни дажда докле ја не речем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Потом дође њему ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Иди одавде, и обрати се на исток, и сакриј се код потока Хората према Јордану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'И из онога потока пиј, а гавранима сам заповједио да те хране ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'И он отиде и учини по ријечи Господњој, и отишав стани се код потока Хората, који је према Јордану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'И ондје му гаврани доношаху хљеба и меса јутром и вечером, а из потока пијаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Али послије годину дана пресахну поток, јер не бјеше дажда у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Тада дође њему ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Устани, иди у Сарепту Сидонску, и сједи ондје; ево заповједио сам ондје жени удовици да те храни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'И уставши отиде у Сарепту; и кад дође на врата градска, гле, жена удовица купљаше ондје дрва; и он је дозва и рече јој: донеси ми мало воде у суду да се напијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'И она пође да донесе; а он је викну и рече: донеси ми и хљеба мало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'А она рече: тако да је жив Господ Бог твој, немам печена хљеба до грст брашна у здјели и мало уља у крчагу; и ето купим дрваца да отидем и зготовим себи и сину својему, да поједемо, па онда да умремо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'А Илија рече јој: не бој се, иди, зготови како си рекла; али умијеси прво мени један колачић од тога, и донеси ми, па послије готови себи и сину својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Јер овако вели Господ Бог Израиљев: брашно се из здјеле неће потрошити нити ће уља у крчагу нестати докле не пусти Господ дажда на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'И она отиде и учини како рече Илија; и једе и она и он и дом њезин годину дана;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Брашно се из здјеле не потроши нити уља у крчагу неста по ријечи Господњој, коју рече преко Илије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'А послије тога разбоље се син жени домаћици, и болест његова би врло тешка, тако да издахну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'И она рече Илији: шта је теби до мене, човјече Божји? јеси ли дошао к мени да споменеш безакоње моје и да ми умориш сина?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'А он јој рече: дај ми сина својега. И узев га из наручја њезина однесе га у горњу клијет, гдје он сјеђаше, и положи га на постељу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Тада завапи ка Господу и рече: Господе Боже мој, зар си и ову удовицу код које сам гост тако уцвијелио уморивши јој сина?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'И пружив се над дјететом три пута завапи ка Господу говорећи: Господе Боже мој, нека се поврати у дијете душа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'И Господ услиши глас Илијин, те се поврати у дијете душа његова, и оживје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'А Илија узев дијете снесе га из горње клијети у кућу, и даде га матери његовој, и рече Илија: види, жив је твој син.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'А жена рече Илији: сада знам да си човјек Божји и да је ријеч Господња у твојим устима истина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Послије много времена, треће године, дође ријеч Господња Илији говорећи: иди, покажи се Ахаву, и пустићу дажд на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'И отиде Илија да се покаже Ахаву, и бијаше велика глад у Самарији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'И Ахав дозва Авдију, који бијаше управитељ двора његова; а Авдија се бојаше Господа веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Јер кад Језавеља убијаше пророке Господње, узе Авдија сто пророка, и сакри их, по педесет у једну пећину, и храни их хљебом и водом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'И рече Ахав Авдији: пођи по земљи на изворе и на потоке, еда бисмо нашли траве да сачувамо у животу коње и мазге, да нам не изгине стока.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'И подијелише међу се земљу куда ће ићи; Ахав отиде једнијем путем сам, а Авдија отиде другим путем сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'А кад Авдија бијаше на путу, гле, срете га Илија; и он га позна, и паде ничице, и рече: јеси ли ти, господару мој Илија?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'А он му рече: ја сам; иди, кажи господару својему: ево Илије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'А он рече: шта сам згријешио, да слугу својега предаш у руке Ахаву да ме погуби?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Тако да је жив Господ Бог твој, нема народа ни царства куда није слао господар мој да те траже: и рекоше: нема га. А он закле царства и народе да те не могу да нађу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'А ти сада кажеш: иди, кажи господару својему: ево Илије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'А кад ја отидем од тебе, дух ће те Господњи однијети, а ја нећу знати куда; па да отидем и прокажем Ахаву, а он да те не нађе, убиће ме; а слуга се твој боји Господа од младости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Није ли казано господару мојему шта сам учинио кад Језавеља убијаше пророке Господње? Како сакрих стотину пророка Господњих, по педесет у једну пећину, и храних их хљебом и водом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'А ти сада кажеш: иди, кажи господару својему: ево Илије. Убиће ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'А Илија рече: тако да је жив Господ над војскама, пред којим стојим, данас ћу му се показати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Тада отиде Авдија пред Ахава, и каза му; и Ахав отиде пред Илију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'А кад видје Ахав Илију, рече му Ахав: јеси ли ти онај што несрећу доносиш на Израиља?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'А он рече: не доносим ја несреће на Израиља, него ти и дом оца твојега оставивши заповијести Господње и приставши за Валима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Него сада пошљи и сабери к мени свега Израиља на гору Кармилску, и четири стотине и педесет пророка Валовијех и четири стотине пророка из луга, који једу за столом Језавељиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'И посла Ахав к свијем синовима Израиљевијем, и сабра оне пророке на гору Кармилску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Тада приступи Илија ка свему народу и рече: докле ћете храмати на обје стране? Ако је Господ Бог, идите за њим; ако ли је Вал, идите за њим. Али народ не одговори му ни ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'А Илија рече народу: ја сам сам остао пророк Господњи; а пророка Валовијех има четири стотине и педесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Дајте нам два јунца, и нека они изаберу себи једнога, и нека га исијеку на комаде и метну на дрва, али огња да не подмећу; а ја ћу приготовити другога јунца, и метнућу га на дрва, али огња нећу подметати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Тада призовите име својих богова, а ја ћу призвати име Господње, па који се Бог одзове огњем онај нека је Бог. И сав народ одговори и рече: добро рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Потом рече Илија пророцима Валовијем: изаберите себи једнога јунца и приготовите га прво, јер је вас више; и призовите име богова својих, али огња не подмећите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'И узеше јунца, којега им даде, и приготовише, и стадоше призивати име Валово од јутра до подне говорећи: Вале, услиши нас! Али ни кака гласа ни кога да одговори. И скакаху око олтара, који начинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'А кад би у подне, стаде им се ругати Илија говорећи: вичите већма; јер је он бог! ваља да се нешто замислио, или је у послу, или на путу, или може бити спава, да се пробуди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'А они стадоше викати иза гласа, и парати се ножима и шилима по свом обичају, докле их крв не обли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'А кад дође подне, стадоше пророковати докле дође вријеме да се принесе дар, али ни кака гласа ни кога да одговори, ни кога да чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Тада рече Илија свему народу: приступите к мени. И приступи к њему сав народ. Тада он оправи олтар Господњи који бјеше разваљен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'И узе Илија дванаест камена према броју племена синова Јакова, којему дође ријеч Господња говорећи: Израиљ ће ти бити име.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'И начини од тога камења олтар у име Господње, и око олтара ископа опкоп широк да би се могле посијати двије мјере жита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'И намјести дрва, и јунца исјечена на комаде метну на дрва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'И рече: напуните четири виједра воде, и излијте на жртву у на дрва. Па опет рече: учините још једном. И учинише још једном. Па опет рече: учините и трећом. И учинише трећом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Те вода потече око олтара, и напуни се опкоп воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'А кад би вријеме да се принесе жртва, приступи Илија пророк и рече: Господе Боже Аврамов, Исаков и Израиљев, нека данас познаду да си ти Бог у Израиљу и ја да сам твој слуга, и да сам по твојој ријечи учинио све ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Услиши ме, Господе, услиши ме, да би познао овај народ да си ти Господе Бог, кад опет обратиш срца њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Тада паде огањ Господњи и спали жртву паљеницу и дрва и камен и прах, и воду у опкопу попи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'А народ кад то видје сав попада ничице, и рекоше: Господ је Бог, Господ је Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Тада им рече Илија: похватајте те пророке Валове да ниједан не утече. И похваташе их, и Илија их одведе на поток Кисон, и покла их ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'И рече Илија Ахаву: иди, једи и пиј, јер уји велики дажд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'И отиде Ахав да једе и пије; а Илија се попе на врх Кармила, и саже се к земљи и метну лице своје међу кољена своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'А момку својему рече: иди, погледај пут мора. А он отишав погледа, па рече: нема ништа. И рече му: иди опет седам пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'А кад би седми пут, рече: ено, мали облак као длан човјечији диже се од мора. Тада рече: иди, реци Ахаву: прежи и иди, да те не ухвати дажд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'У том се замрачи небо од облака и вјетра, и удари велики дажд. А Ахав сједавши на кола отиде у Језраел.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'А рука Господња дође над Илију, и он опасавши се отрча пред Ахавом докле дође у Језраел.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'А Ахав приповједи Језавељи све што је учинио Илија и како је све пророке исјекао мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Тада Језавеља посла гласнике к Илији и поручи му: тако да учине богови и тако да додаду, ако сјутра у ово доба не учиним од тебе што је од којега од тијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'А он видећи то уста и отиде душе своје ради, и дође у Вирсавеју Јудину, и ондје остави момка својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'А сам отиде у пустињу дан хода; и дошав сједе под смреку, и зажеље да умре, и рече: доста је већ, Господе, прими душу моју, јер нијесам бољи од отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Потом леже и заспа под смреком. А гле, анђео такну га и рече му: устани, једи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'А он погледа, и гле, чело главе му хљеб на угљену печен и крчаг воде. И једе и напи се, па леже опет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'А анђео Господњи дође опет другом, и такну га говорећи: устани, једи, јер ти је пут далек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'А он уставши једе и напи се; потом окријепив се онијем јелом иде четрдесет дана и четрдесет ноћи докле дође на гору Божију Хорив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'А ондје уђе у једну пећину и заноћи у њој; и гле, ријеч Господња дође му говорећи: шта ћеш ти ту, Илија?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'А он рече: ревновах веома за Господа Бога над војскама; јер синови Израиљеви оставише завјет твој, твоје олтаре развалише, и пророке твоје побише мачем; а ја остах сам, па траже душу моју да ми је узму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'А он рече: изиди и стани на гори пред Господом. И гле, Господ пролажаше, а пред Господом велик и јак вјетар, који брда разваљиваше и стијене разламаше; али Господ не бјеше у вјетру; а иза вјетра дође трус; али Господ не бјеше у трусу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'А иза труса дође огањ; али Господ не бјеше у огњу. А иза огња дође глас тих и танак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'А кад то чу Илија, заклони лице своје плаштем и изашав стаде на вратима од пећине. И гле, дође му глас говорећи: шта ћеш ти ту Илија?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'А он рече: ревновах веома за Господа Бога над војскама; јер синови Израиљеви оставише завјет твој, твоје олтаре развалише, и пророке твоје побише мачем; а ја остах сам, па траже душу моју да ми је узму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Тада му рече Господ: иди, врати се својим путем у пустињу Дамаштанску, и кад дођеш помажи Азаила за цара над Сиријом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'А Јуја сина Нимсијина помажи за цара над Израиљем, а Јелисија сина Сафатова из Авел-Меоле помажи за пророка мјесто себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Јер ко утече од мача Азаилова њега ће погубити Јуј; а ко утече од мача Јујева њега ће погубити Јелисије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Али сам оставио у Израиљу седам тисућа, који ниједан не савише кољена пред Валом, нити га устима својим цјеливаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'И отиде од њега, и нађе Јелисија сина Сафатова гдје оре, а дванаест јармова пред њим, а сам бијаше код дванаестога; и идући мимо њ Илија баци на њ плашт свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'А он остави волове, и отрча за Илијом и рече: да цјелујем оца својега и матер своју; па ћу ићи за тобом. А он му рече: иди, врати се, јер шта сам ти учинио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'И он се врати од њега, и узе јарам волова и закла их, и на дрвима од плуга скуха месо и даде га народу, те једоше; потом уставши отиде за Илијом и служаше му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'А Вен-Адад цар Сирски скупи војску своју, и имаше са собом тридесет и два цара, и коње и кола; и отишавши опколи Самарију и стаде је бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'И посла посланике к Ахаву цару Израиљеву у град,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'И поручи му: овако вели Вен-Адад: сребро твоје и злато твоје моје је, тако и жене твоје и твоји лијепи синови моји су.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'А цар Израиљев одговори и рече: као што си рекао, господару мој царе, ја сам твој и све што имам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'А посланици опет дођоше и рекоше: овако вели Вен-Адад: послао сам к теби и поручио: сребро своје и злато своје и жене своје и синове своје да ми даш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Зато ћу сјутра у ово доба послати слуге своје к теби да прегледају кућу твоју и куће слуга твојих, и што ти је год мило, оно ће узети и однијети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Тада дозва цар Израиљев све старјешине земаљске и рече: гледајте и видите како овај тражи зло; јер посла к мени по мене и по синове моје и по сребро моје и по злато моје, и ја му не браних.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'А све старјешине и сав народ рекоше му: не слушај га и не пристај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'И рече посланицима Вен-Ададовијем: кажите цару господару мојему: што си прво поручио слузи својему све ћу учинити; али ово не могу учинити. Тако отидоше посланици и однесоше му тај одговор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'А Вен-Адад посла к њему и поручи: тако да ми учине богови и тако додаду! неће бити доста праха од Самарије да свему народу који иде за мном допадне по једна грст.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'А цар Израиљев одговори и рече: кажите: нека се хвали онај који се опасује као онај који се распасује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'А кад он то чу пијући с царевима под шаторима, рече слугама својим: дижите се. И дигоше се на град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Тада гле, приступи један пророк к Ахаву цару Израиљеву, и рече: овако вели Господ: видиш ли све ово мноштво? ево, ја ћу ти га дати у руке данас да познаш да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'А Ахав рече: преко кога? А он рече: овако вели Господ: преко момака кнезова земаљских. Опет рече: ко ће заметнути бој? А он рече: ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Тада преброји момке кнезова земаљских, и бјеше их двјеста и тридесет и два; послије њих преброја сав народ, све синове Израиљеве, и бјеше их седам тисућа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'И изидоше у подне; а Вен-Адад пијући опи се у шаторима с тридесет и два цара који му дођоше у помоћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'И изидоше прво момци кнезова земаљских; а Вен-Адад посла, и јавише му и рекоше: изидоше људи из Самарије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'А он рече: ако су изашли мира ради, похватајте их живе; ако су изашли на бој, похватајте их живе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'И изидоше из града момци кнезова земаљских, и војска за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'И сваки уби с којим се сукоби, те Сирци побјегоше а Израиљци их потјераше. И Вен-Адад цар Сирски побјеже на коњу с коњицима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'И цар Израиљев изиде и поби коње и кола, и учини велик покољ међу Сирцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Потом дође пророк к цару Израиљеву и рече му: иди, буди храбар; и промисли и види шта ћеш чинити, јер ће до године опет доћи цар Сирски на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'А цару Сирском рекоше слуге његове: њихови су богови горски богови, зато нас надјачаше; него да се бијемо с њима у пољу, зацијело ћемо их надјачати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Учини дакле овако: уклони те цареве с мјеста њиховијех, и постави војводе мјесто њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Па скупи војску каква је била она која је изгинула, и коње какви су били они коњи, и кола као она кола; па да се побијемо с њима у пољу; зацијело ћемо их надјачати. И послуша их, и учини тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'А кад прође година, Вен-Адад преброји Сирце, и пође у Афек да војује на Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'А синови Израиљеви пребројише се, и понесавши хране изидоше пред њих. И стадоше у око синови Израиљеви према њима, као два мала стада коза, а Сирци бијаху прекрилили земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Тада дође човјек Божји, и проговори цару Израиљеву, и рече: овако вели Господ: што Сирци рекоше да је Господ горски Бог а није Бог пољски, зато ћу ти дати у руке све ово мноштво велико да знате да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'И стајаху у околу једни према другима седам дана; а седмога дана побише се, и синови Израиљеви побише Сираца сто тисућа пјешака у један дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'А остали побјегоше у град Афек, и паде зид на двадесет и седам тисућа људи који бјеху остали. И Вен-Адад побјегав у град уђе у најтајнију клијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'А слуге му рекоше: ево чули смо да су цареви дома Израиљева милостиви цареви; да вежемо костријет око себе и да метнемо узице себи око вратова, па да изидемо пред цара Израиљева, да ако остави у животу душу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'И везаше костријет око себе, и метнуше узице себи око вратова, и дођоше к цару Израиљеву и рекоше: слуга твој Вен-Адад вели: остави у животу душу моју. А он рече: је ли још жив? брат ми је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'А људи узеше то за добар знак, и одмах да би га ухватили за ријеч рекоше: брат је твој Вен-Адад. А он рече: идите, доведите га. Тада Вен-Адад изиде к њему; а он га посади на своја кола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Тада му рече Вен-Адад: градове које је узео отац мој твом оцу, вратићу, и начини себи улице у Дамаску као што је отац мој учинио у Самарији. А он одговори: с том вјером отпустићу те. И учини вјеру с њим, и отпусти га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Тада један између синова пророчких рече другоме по ријечи Господњој: биј ме. Али га онај не хтје бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'А он му рече: што не послуша гласа Господњега, зато, ево кад отидеш од мене, лав ће те заклати. И кад отиде од њега, сукоби га лав и закла га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Опет нашав другога рече му: биј ме. а онај га изби и израни га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Тада отиде пророк и стаде на пут куда ће цар проћи, и нагрди се пепелом по лицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'А кад цар пролажаше, он викну цара и рече: твој слуга бијаше изашао у бој, а један дошавши доведе ми човјека и рече: чувај овога човјека; ако ли га нестане, биће твоја душа за његову душу, или ћеш платити таланат сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'А кад твој слуга имаше посла тамо амо, њега неста. Тада му рече цар Израиљев: то ти је суд, сам си отсудио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'А он брже убриса пепео с лица, и цар Израиљев позна га да је један од пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'А он му рече: овако вели Господ: што си пустио из руку човјека којега сам ја осудио да се истријеби, душа ће твоја бити за његову душу и народ твој за његов народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'И отиде цар Израиљев кући својој зловољан и љутит, и дође у Самарију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'А послије овијех ствари догоди се: Навутеј Језраељанин имаше виноград у Језраелу до двора Ахава цара Самаријскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'И рече Ахав Навутеју говорећи: дај ми свој виноград да начиним од њега врт за зеље, јер је близу двора мојега; а ја ћу ти дати за њ бољи виноград, или ако волиш, даћу ти у новцу шта вриједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'А Навутеј рече Ахаву: Сачувај Боже да бих ти дао нашљедство отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Тада Ахав дође кући зловољан и љутит ради ријечи коју му рече Навутеј Језраељанин говорећи: не дам ти нашљедства отаца својих. И леже на постељу своју, и окрену лице своје на страну, и не једе хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Тада дође к њему Језавеља жена његова и рече му: зашто је душа твоја зловољна те не једеш хљеба?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'А он јој рече: јер говорих с Навутејем Језраељанином и рекох му: дај ми виноград свој за новце, или ако волиш, даћу ти други виноград за тај. А он рече: не дам ти свога винограда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Тада му рече Језавеља жена његова: ти ли си цар над Израиљем? Устани, једи хљеба и буди весео. Ја ћу ти дати виноград Навутеја Језраељанина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'И написа књигу на име Ахавово, и запечати је печатом његовијем и посла књигу старјешинама и главарима који бијаху у граду његову, који наставаху с Навутејем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'А у књизи написа ово: огласите пост, и посадите Навутеја међу главаре народне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'И поставите два неваљала човјека према њему, па нека засвједоче на њ говорећи: хулио си на Бога и на цара. Тада га изведите и заспите камењем, да погине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'И учинише људи онога града, старјешине и главари, који живљаху у граду његову, како им заповједи Језавеља, како бијаше написано у књизи коју им посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'И огласише пост, и посадише Навутеја међу главаре народне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'И дођоше два неваљала човјека, и стадоше према њему; и свједочише на Навутеја ти неваљали људи пред народом говорећи: Навутеј је хулио на Бога и на цара. И изведоше га иза града, и засуше га камењем, те погибе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Потом послаше к Језавељи и поручише јој: засут је камењем Навутеј, и погинуо је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'А кад Језавеља чу да је Навутеј засут камењем и погинуо, рече Ахаву Језавеља: устани, узми виноград Навутеја Језраељанина, којега ти не хтје дати за новце, јер Навутеј није жив него је умро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'А кад чу Ахав да је умро Навутеј, уста и пође у виноград Навутеја Језраељанина да га узме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Али дође ријеч Господња к Илији Тесвићанину говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Устани, изиди на сусрет Ахаву цару Израиљеву, који сједи у Самарији; ено га у винограду Навутејеву, куда је отишао да га узме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'И реци му и кажи: овако вели Господ: нијеси ли убио и нијеси ли присвојио? Па му кажи и реци: овако вели Господ: како пси лизаше крв Навутејеву, тако ће лизати пси и твоју крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'А Ахав рече Илији: нађе ли ме непријатељу мој? А он рече: нађох, јер си се продао да чиниш зло пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Ево, пустићу зло на те, и узећу натражје твоје, и истријебићу Ахаву и оно што уза зид мокри, и ухваћенога и остављенога у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'И учинићу с домом твојим као с домом Јеровоама сина Наватова и као с домом Васе цара Ахијина, што си ме гњевио и што си навео на гријех Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Такође и за Језавељу рече Господ говорећи: пси ће изјести Језавељу испод зидова Језраелских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Ко Ахавов погине у граду изјешће га пси, а ко погине у пољу изјешће га птице небеске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'И не би такога као Ахав, који се продаде да чини што је зло пред Господом, јер га подговараше жена његова Језавеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'И почини врло грдна дјела идући за гадним боговима сасвијем као што чинише Амореји, које изагна Господ испред синова Израиљевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'А кад Ахав чу те ријечи, раздрије хаљине своје, и привеза костријет око тијела својега, и пошћаше, и спаваше у костријети, и хођаше полагано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'И дође ријеч Господња Илији Тесвићанину говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Јеси ли видио како се Ахав понизио преда мном? Зато што се тако понизио преда мном, нећу пустити онога зла за његова живота; него за сина његова пустићу оно зло на дом његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'И прођоше три године без рата између Сираца и Израиљаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'А треће године дође Јосафат цар Јудин к цару Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'И рече цар Израиљев слугама својим: не знате ли да је наш Рамот у Галаду? А ми не радимо да га узмемо из руку цара Сирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'И рече Јосафату: хоћеш ли ићи са мном на војску на Рамот Галадски? А Јосафат рече цару Израиљеву: ја као ти, народ мој као твој народ, коњи моји као твоји коњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Још рече Јосафат цару Израиљеву: упитај данас шта ће Господ рећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Тада цар Израиљев сабра око четири стотине пророка, и рече им: хоћу ли ићи на војску на Рамот Галадски или ћу се оканити? А они рекоше: иди, јер ће га Господ дати у руке цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'А Јосафат рече: има ли ту још који пророк Господњи да га питамо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'А цар Израиљев рече Јосафату: има још један човјек, преко којега бисмо могли упитати Господа; али ја мрзим на њ, јер ми не прориче добра него зло; то је Михеја син Јемлин. А Јосафат рече: нека цар не говори тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Тада цар Израиљев дозва једнога дворанина, и рече му: брже доведи Михеју сина Јемлина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'А цар Израиљев и Јосафат цар Јудин сјеђаху сваки на својем пријестолу обучени у царске хаљине на пољани код врата Самаријских, и сви пророци пророковаху пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'И Седекија син Хананин начини себи гвоздене рогове, и рече: овако вели Господ: овијем ћеш побости Сирце докле их не истријебиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Тако и сви пророци пророковаху говорећи: иди на Рамот Галадски, и бићеш срећан, јер ће га Господ дати цару у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'А посланик који отиде да дозове Михеју рече му говорећи: ево, пророци проричу сви једнијем гласом добро цару; нека и твоја ријеч буде као ријеч њихова, говори добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'А Михеја рече: тако да је жив Господ, говорићу оно што ми Господ каже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'И кад дође к цару, рече му цар: Михеја! хоћемо ли ићи на војску на Рамот Галадски или ћемо се оканити? А он му рече: иди, бићеш срећан, јер ће га Господ дати цару у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'А цар му рече: колико ћу те пута заклињати да ми не говориш него истину у име Господње?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Тада рече: видјех сав народ Израиљев разасут по планинама као овце које немају пастира; јер рече Господ: ови немају господара; нека се врате свак својој кући с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Тада рече цар Израиљев Јосафату: нијесам ли ти рекао да ми неће пророковати добра него зло?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'А Михеја му рече: зато чуј ријеч Господњу; видјех Господа гдје сједи на пријестолу својем, а сва војска небеска стајаше му с десне и с лијеве стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'И рече Господ: ко ће преварити Ахава да отиде и падне код Рамота Галадскога? И један рече ово а други оно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Тада изиде један дух и ставши пред Господа рече: ја ћу га преварити. А Господ му рече: како?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Одговори: изаћи ћу и бићу лажљив дух у устима свијех пророка његовијех. А Господ му рече: преварићеш га и надвладаћеш, иди и учини тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Зато сада ето, Господ је метнуо лажљив дух у уста свијем твојим пророцима, а Господ је изрекао зло по те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Тада приступи Седекија син Хананин, и удари Михеју по образу говорећи: куда је отишао дух Господњи од мене да говори с тобом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'А Михеја му рече: ето, видјећеш у онај дан кад отидеш у најтајнију клијет да се сакријеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Тада цар Израиљев рече: ухвати Михеју и одведи га к Амону заповједнику градском и к Јоасу сину цареву;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'И реци им: овако вели цар: метните овога у тамницу, и дајте им по мало хљеба и по мало воде докле се не вратим у миру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'А Михеја рече: ако се вратиш у миру, није Господ говорио преко мене. Још рече: чујте, сви народи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'И отиде цар Израиљев с Јосафатом царем Јудиним на Рамот Галадски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'И рече цар Израиљев Јосафату: ја ћу се преобући кад пођем у бој; а ти обуци своје одијело. И преобуче се цар Израиљев и отиде у бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'А цар Сирски заповједи војводама, којих бијаху тридесет и двије над колима његовијем, и рече: не ударајте ни на малога ни на великога, него на самога цара Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'И кад војводе од кола видјеше Јосафата, рекоше: зацијело је цар Израиљев. И окренуше се на њ да ударе; али Јосафат повика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'А војводе од кола видјеше да није цар Израиљев, те отступише од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'А један застријели из лука нагоном, и устријели цара Израиљева гдје спуча оклоп. А он рече својему возачу: савиј руком својом и извези ме из боја, јер сам рањен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'И бој би жесток онога дана; а цар заоста на колима својим према Сирцима, па умрије увече, и крв из ране тецијаше у кола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'И прође гласник по војсци о заходу сунчаном говорећи: свак у свој град, и свак у своју земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Тако умрије цар, и однесоше га у Самарију; и погребоше цара у Самарији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'А кад праху кола на језеру Самаријском, лизаше пси крв његову, тако и кад праху оружје његово, по ријечи коју рече Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'А остала дјела Ахавова и све што је учинио, и за кућу од слонове кости коју је саградио, и за све градове што је саградио, није ли то записано у дневнику царева Израиљевијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Тако почину Ахав код отаца својих, и на његово се мјесто зацари Охозија син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'А Јосафат син Асин зацари се над Јудом четврте године царовања Ахавова над Израиљем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'И имаше Јосафат тридесет и пет година кад поче царовати, и царова двадесет и пет година у Јерусалиму. А матери му бјеше име Азува кћи Силејева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'И хођаше путем Асе оца својега сасвијем, и не отступи од њега чинећи све што је право пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Али висина не оборише; народ још приношаше жртве и кађаше на висинама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'И учини мир Јосафат с царем Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'А остала дјела Јосафатова и јунаштва што учини и како војева, није ли то записано у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Он истријеби из земље своје остатак аџувана, који бијаху остали за живота Асе оца његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'У то вријеме не бијаше цара у Идумеји, него бијаше намјесник царев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'И Јосафат начини лађе Тарсиске да иду у Офир по злато; али не отидоше; јер се лађе разбише у Есион-Гаверу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Тада рече Охозија син Ахавов Јосафату: нека иду моје слуге с твојим слугама на лађама. Али Јосафат не хтје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'И почину Јосафат код отаца својих, и погребоше га код отаца његовијех у граду Давида оца његова; а на његово се мјесто зацари Јорам син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Охозија син Ахавов зацари се над Израиљем у Самарији седамнаесте године царовања Јосафатова над Јудом; и царова над Израиљем двије године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'И чињаше што је зло пред Господом, и хођаше путем оца својега и путем матере своје и путем Јеровоама сина Наватова, који наведе на гријех Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 54, 'И служаше Валу и клањаше му се, и гњевљаше Господа Бога Израиљева са свијем како је чинио отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'А по смрти Ахавовој одметнуше се Моавци од Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'А Охозија паде кроз решетку из горње собе своје у Самарији, и разбоље се; па посла посланике и рече им: идите, питајте Велзевула бога Акаронскога хоћу ли оздравити од ове болести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Али анђео Господњи рече Илији Тесвићанину: устани, изиди на сусрет посланицима цара Самаријскога и реци им: еда ли нема Бога у Израиљу, те идете да питате Велзевула бога у Акарону?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'А зато овако вели Господ: нећеш се дигнути са постеље на коју си легао, него ћеш умријети. Потом отиде Илија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'А слуге се вратише к Охозији, и он им рече: што сте се вратили?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'А они му рекоше: срете нас један човјек, и рече нам: идите, вратите се к цару који вас је послао, и реците му: овако вели Господ: еда ли нема Бога у Израиљу, те шаљеш да питаш Велзевула бога у Акарону? Зато нећеш се дигнути с постеље на коју си легао, него ћеш умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'А он им рече: какав бјеше на очи тај човјек који вас срете и то вам рече?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'А они му одговорише: бјеше сав космат и опасан кожнијем појасом. А он рече: то је Илија Тесвићанин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Тада посла к њему педесетника с његовом педесеторицом; и он отиде к њему; и гле, он сјеђаше наврх горе; и педесетник му рече: човјече Божји, цар је заповједио, сиђи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'А Илија одговарајући рече педесетнику: ако сам човјек Божји, нека сиђе огањ с неба и прождре тебе и твоју педесеторицу. И сиђе огањ с неба и прождрије њега и његову педесеторицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Опет посла к њему другог педесетника с његовом педесеторицом, који проговори и рече му: човјече Божји, цар је тако заповједио, сиђи брже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'А Илија одговори и рече им: ако сам човјек Божји, нека сиђе огањ с неба и прождре тебе и твоју педесеторицу. И сиђе огањ Божји с неба и прождрије њега и његову педесеторицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Тада опет посла трећега педесетника с његовом педесеторицом. А овај трећи педесетник кад дође, клече на кољена своја пред Илијом, и молећи га рече му: човјече Божји, да ти је драга душа моја и душа ове педесеторице, слуга твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Ето, сишао је огањ с неба и прождро прва два педесетника с њиховом педесеторицом; али сада да ти је драга душа моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'А анђео Господњи рече Илији: иди с њим, и не бој га се. И уста Илија и отиде с њим к цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'И рече му: овако вели Господ: зато што си слао посланике да питају Велзевула бога у Акарону као да нема Бога у Израиљу да би га питао, нећеш се дигнути с постеље на коју си легао, него ћеш умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'И умрије по ријечи Господњој, коју рече Илија, а на његово се мјесто зацари Јорам друге године царовања Јорама сина Јосафатова над Јудом, јер он нема сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'А остала дјела Охозијина што је чинио, нијесу ли записана у дневнику царева Израиљевих?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'А кад Господ шћаше узети Илију у вихору на небо, пођоше Илија и Јелисије из Галгала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'И рече Илија Јелисију: остани ти овдје, јер мене Господ шаље до Ветиља. Али Јелисије рече: тако жив био Господ и тако жива била душа твоја, нећу те оставити. И дођоше у Ветиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Тада дођоше к Јелисију синови пророчки који бијаху у Ветиљу, и рекоше му: знаш ли да ће данас Господ узети господара твојега од тебе? А он рече: знам, мучите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Опет му рече Илија: Јелисије, остани ти ту, јер ме Господ шаље у Јерихон. А он рече: тако жив био Господ и тако жива била душа твоја, нећу те оставити. Тако дођоше у Јерихон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'А синови пророчки који бијаху у Јерихону приступише к Јелисију, и рекоше му: знаш ли да ће данас узети Господ од тебе господара твојега? А он рече: знам, мучите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Опет му рече Илија: остани ти ту, јер ме Господ шаље на Јордан. А он рече: тако жив био Господ и тако била жива твоја душа, нећу те оставити. Тако отидоше обојица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'И педесет људи између синова пророчких отидоше и стадоше према њима издалека, а они обојица уставише се код Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'И узе Илија плашт свој, и савив га удари њим по води, а она се раступи тамо и амо, те пријеђоше обојица сухим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'А кад пријеђоше, рече Илија Јелисију: ишти шта хоћеш да ти учиним, докле се нијесам узео од тебе. А Јелисије рече: да буду два дијела духа твојега у мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'А он му рече: заискао си тешку ствар; али ако ме видиш кад се узмем од тебе, биће ти тако; ако ли не видиш, неће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'И кад иђаху даље разговарајући се, гле, огњена кола и огњени коњи раставише их, и Илија отиде у вихору на небо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'А Јелисије видећи то викаше: оче мој, оче мој! кола Израиљева и коњици његови! И не видје га више; потом узе хаљине своје и раздрије их на два комада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'И подиже плашт Илијин, који бјеше спао с њега, и вратив се стаде на бријегу Јорданском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'И узев плашт Илијин, који бјеше спао с њега, удари по води и рече: гдје је Господ Бог Илијин? А кад и он удари по води, раступи се вода тамо и амо, и пријеђе Јелисије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'А кад с друге стране видјеше синови пророчки, који бијаху у Јерихону, рекоше: почину дух Илијин на Јелисију. И сретоше га и поклонише му се до земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'И рекоше му: ево има у слуга твојих педесет јунака, нека иду и траже твојега господара, да га не буде узео дух Господњи и бацио га на какво брдо или у какав до. А он рече: не шаљите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Али они наваљиваху на њ докле му се не досади, те рече: пошљите. И послаше педесет људи који га тражише три дана, али не нађоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'И вратише се к њему, а он бијаше у Јерихону, па им рече: нијесам ли вам говорио да не идете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Тада грађани рекоше Јелисију: гле, добро је живјети у овом граду, као што господар наш види; али је вода зла и земља неродна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'А он им рече: донесите ми нов котао, и метните у њ соли. И донесоше му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'А он изиде на извор и баци у њ со, говорећи: овако вели Господ: исцијелих ову воду, да не буде више од ње смрти ни неродности.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'И вода поста здрава до данашњега дана по ријечи Јелисијевој, коју изрече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Потом отиде оданде у Ветиљ; и кад иђаше путем, изидоше мала дјеца из града и ругаху му се говорећи му: ходи, ћело! ходи, ћело!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'А Јелисије обазре се и видећи их прокле их именом Господњим. Тада изидоше двије медвједице из шуме, и растргоше четрдесет и двоје дјеце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Оданде отиде на гору Кармилску, а оданде се врати у Самарију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'А Јорам син Ахавов зацари се над Израиљем у Самарији осамнаесте године царовања Јосафатова над Јудом, и царова дванаест година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'И чињаше што је зло пред Господом, али не као отац његов и као мати његова, јер обори лик Валов који бјеше начинио отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Али оста у гријесима Јеровоама сина Наватова, којима наведе на гријех Израиља, и не отступи од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'А Миса цар Моавски имаше много стоке, и даваше цару Израиљеву сто тисућа јагањаца и сто тисућа овнова под руном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Али кад умрије Ахав, одметну се цар Моавски од цара Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'А цар Јорам изиде у то вријеме из Самарије и преброји свега Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'И отиде, те посла к Јосафату цару Јудину и поручи му: цар Моавски одметну се од мене; хоћеш ли ићи са мном на војску на Моавце? А он рече: хоћу, ја као ти, мој народ као твој народ, моји коњи као твоји коњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Иза тога рече: а којим ћемо путем ићи? А он рече: преко пустиње Едомске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'И тако изиде цар Израиљев и цар Јудин и цар Едомски, и идоше путем седам дана, и не бијаше воде војсци ни стоци, која иђаше за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'И рече цар Израиљев: јаох! дозва Господ ова три цара да их преда у руке Моавцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'А Јосафат рече: има ли ту који пророк Господњи да упитамо Господа преко њега? А један између слуга цара Израиљева одговори и рече: овдје је Јелисије син Сафатов, који је Илији пољевао водом руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Тада рече Јосафату: у њега је ријеч Господња: И отидоше к њему цар Израиљев и Јосафат и цар Едомски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'А Јелисије рече цару Израиљеву: шта је мени до тебе? иди ка пророцима оца својега и ка пророцима матере своје. А цар Израиљев рече му: не, јер Господ дозва ова три цара да их преда у руке Моавцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'А Јелисије рече: тако да је жив Господ над војскама, пред којим стојим, да не гледам на Јосафата цара Јудина, не бих марио за те нити бих те погледао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Него сада доведите ми гудача. И кад гудач гуђаше, дође рука Господња нада њ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'И рече: овако вели Господ: начините по овој долини много јама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Јер овако вели Господ: нећете осјетити вјетра нити ћете видјети дажда, али ће се долина ова напунити воде, те ћете пити и ви и људи ваши и стока ваша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Па и то је мало Господу, него и Моавце ће вам предати у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'И раскопаћете све тврде градове, и све изабране градове, и посјећи ћете сва добра дрвета и заронити све изворе водене, и сваку њиву добру потрћете камењем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'А ујутру кад се приноси дар, гле, дође вода од Едомске, и напуни се земља воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'А сви Моавци чувши да су изишли цареви да ударе на њих, сазваше све који се почињаху пасати и старије и стадоше на међи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'А ујутру кад усташе и сунце ограну над оном водом, угледаше Моавци према себи воду гдје се црвени као крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'И рекоше: крв је; побили су се цареви, и један другога погубили; сада дакле на плијен, Моавци!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'А кад дођоше до окола Израиљева, подигоше се Израиљци и разбише Моавце, те побјегоше испред њих, а они уђоше у земљу Моавску бијући их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'И градове њихове раскопаше, и на сваку добру њиву бацајући сваки по камен засуше је, и све изворе водене заронише, и сва добра дрвета посјекоше тако да само оставише камење у Кирарасету. И опколивши га праћари стадоше га бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'А цар Моавски кад видје да ће га надвладати војска, узе са собом седам стотина људи, који махаху мачем, да продру кроз војску цара Едомскога, али не могоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Тада узе сина својега првенца који шћаше бити цар на његово мјесто, и принесе га на жртву паљеницу на зиду. Тада се подиже велики гњев на Израиља, те отидоше оданде и вратише се у своју земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'А једна између жена синова пророчких повика к Јелисију говорећи: слуга твој, муж мој, умрије, и ти знаш да се слуга твој бојао Господа; па сада дође рукодавалац да ми узме два сина у робље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'А Јелисије јој рече: што ћу ти? кажи ми шта имаш у кући? А она рече: слушкиња твоја нема у кући ништа до судић уља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'А он јој рече: иди, ишти у наруч празнијех судова у свијех сусједа својих, немој мало да иштеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Па отиди, и затвори се у кућу са синовима својим, па онда наљевај у све судове, и кад се који напуни, кажи нека уклоне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'И она отиде од њега, и затвори се у кућу са синовима својим; они јој додаваху а она наљеваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'А кад се судови напунише, она рече сину својему: дај још један суд. А он јој рече: нема више. Тада стаде уље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Потом она отиде и каза човјеку Божијему; а он јој рече: иди, продај уље, и одужи се; а што претече, онијем се храни са својим синовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Послије тога једном иђаше Јелисије кроз Сунам, а ондје бијаше богата жена, која га устави да једе хљеба; и отада кад год пролажаше, увраћаше се к њој да једе хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'И она рече мужу својему: гле, видим да је свет човјек Божји овај што све пролази овуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Да начинимо малу клијет, и да му намјестимо постељу и сто и столицу и свијетњак, па кад дође к нама, нека се ту склони.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Потом он дође једном онамо, и ушав у клијет почину ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'И рече момку својему Гијезију: зови Сунамку. И он је дозва; и она стаде пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'И он рече Гијезију: кажи јој: ето стараш се за нас свакојако; шта хоћеш да ти учиним? имаш ли што да говорим цару или војводи? А она рече: ја живим усред својега народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'А он рече: шта бих јој дакле учинио? А Гијезије рече: ето нема сина, а муж јој је стар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'А он рече: зови је. И он је дозва, и она стаде на вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'А он рече: до године у ово доба грлићеш сина. А она рече: немој господару мој, човјече Божји, немој варати слушкиње своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'И затрудње жена, и роди сина друге године у исто доба, као што јој рече Јелисије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'И дијете одрасте. И једном изиде к оцу својему к жетеоцима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'И рече оцу својему: јаох глава, јаох глава! А он рече момку: носи га матери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'И он га узе и однесе матери његовој, и лежа на крилу њезину до подне, па умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Тада отиде она горе, и намјести га у постељу човјека Божјега, и затворивши га изиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Потом викну мужа својега и рече му: пошљи ми једнога момка и једну магарицу да отрчим до човјека Божјега и да се вратим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'А он рече: зашто данас хоћеш да идеш к њему? нити је младина ни субота. А она рече: не брини се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'И она осамаривши магарицу рече момку својему: води и иди и немој застајати мене ради на путу докле ти не кажем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Тако пошавши дође човјеку Божјему на гору Кармилску. А кад је човјек Божји угледа гдје иде к њему, рече Гијезију слузи својему: ево Сунамке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Трчи сад пред њу и реци јој: јеси ли здраво? је ли здраво муж твој? је ли здраво син твој? А она рече: здраво смо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'А кад дође к човјеку Божјему на гору, загрли му ноге, а Гијезије приступи да је отјера; али човјек Божји рече: остави је, јер јој је душа у јаду, а Господ сакри од мене и не јави ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'А она рече: јесам ли искала сина од господара својега? нијесам ли казала: немој ме варати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'А он рече Гијезију: опаши се и узми штап мој у руку, па иди; ако сретнеш кога немој га поздрављати, и ако те ко поздрави, немој му одговарати, и метни мој штап на лице дјетету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'А мати дјетиња рече: тако да је жив Господ и тако да је жива душа твоја, нећу те се оставити. Тада он уста и пође за њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'А Гијезије отиде напријед и метну штап на лице дјетету, али не би гласа ни осјећања. Тада се врати преда њ, и јави му говорећи: не пробуди се дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'И Јелисије уђе у кућу, и гле, дијете мртво лежи на његовој постељи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'И ушав затвори се с дјететом, и помоли се Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Потом стаде на постељу и леже на дијете метнув уста своја на уста дјетету, и очи своје на очи његове, и дланове своје на његове дланове, и пружи се над њим, те се загрија тијело дјетету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Потом уста, и пријеђе по кући једном тамо и једном амо, потом отиде опет и пружи се над дјететом. И кихну дијете седам пута, и отвори дијете очи своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Тада дозва Гијезија и рече му: зови Сунамку. И он је дозва, те дође к њему. И он јој рече: узми сина својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'И она ушавши паде к ногама његовијем, и поклони му се до земље, и узевши сина својега отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Потом врати се Јелисије у Галгал. А бијаше глад у оној земљи, и синови пророчки сјеђаху пред њим; а он рече момку својему: пристави велики лонац и скухај зеља синовима пророчким.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'А један отиде у поље да набере зеља, и нађе дивљу лозу и набра с ње дивљих тиквица пун плашт, и дошавши сасијече их у лонац гдје бјеше зеље, јер их не познаваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'И усуше људима да једу; а кад стадоше јести онога зеља, повикаше говорећи: смрт је у лонцу, човјече Божји! И не могаху јести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'А он рече: донесите брашна. И сасу брашно у лонац, и рече: успи људима нека једу. И не би више никакога зла у лонцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'А дође неко из Вал-Салисе, и донесе човјеку Божијему хљеба од првина, двадесет хљебова јечменијех, и новијех зрна у класу. А он рече: постави народу, нека једу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'А слуга му рече: како ћу то поставити пред сто људи? Опет рече: постави народу, нека једу; јер је тако казао Господ: јешће, и претећи ће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'А он им постави, те једоше; и претече по ријечи Господњој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'И бјеше Неман војвода цара Сирскога човјек велик у господара својега и у части, јер преко њега сачува Господ Сирију; али тај велики јунак бјеше губав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'А из Сирије изиде чета и зароби у земљи Израиљској малу дјевојку, те она служаше жену Неманову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'И она рече својој госпођи: о да би мој господар отишао к пророку у Самарији! он би га опростио од губе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Тада он отиде к своме господару и јави му говорећи: тако и тако каже дјевојка из земље Израиљске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'А цар Сирски рече му: хајде иди, а ја ћу послати књигу цару Израиљеву. И он отиде, и понесе десет таланата сребра и шест тисућа сикала злата и десеторе стајаће хаљине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'И однесе књигу цару Израиљеву која овако говораше: ето, кад ти дође ова књига, знај да шаљем к теби Немана слугу својега да га опростиш губе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'А кад цар Израиљев прочита књигу, раздрије хаљине своје и рече: зар сам ја Бог да могу убити и повратити живот, те шаље к мени да опростим човјека губе! Пазите и видите како тражи задјевице са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'А кад чу Јелисије човјек Божји да је цар Израиљев раздро хаљине своје, посла к цару и поручи: зашто си раздро хаљине своје? нека дође к мени, да позна да има пророк у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'И тако дође Неман с коњма и колима својим, и стаде на вратима дома Јелисијева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'А Јелисије посла к њему и поручи: иди и окупај се седам пута у Јордану, и оздравиће тијело твоје, и очистићеш се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Тада се расрди Неман и пође говорећи: гле! ја мишљах, он ће изаћи к мени, и стаће, и призваће име Господа Бога својега, и метнути руку своју на мјесто, и очистити губу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Нијесу ли Авана и Фарфар воде у Дамаску боље од свијех вода Израиљских? не бих ли се могао у њима окупати и очистити? И окренувши се отиде гњеван.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Али слуге његове приступивши рекоше му говорећи: оче, да ти је казао пророк што велико, не би ли учинио? а зашто не би кад ти рече: окупај се, па ћеш се очистити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'И тако сиђе, и зарони у Јордан седам пута по ријечима човјека Божијега, и тијело његово поста као у малога дјетета, и очисти се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Тада се врати к човјеку Божијему са пратњом својом и дошав стаде пред њим, и рече: ево сад видим да нема Бога нигдје на земљи до у Израиљу. Него узми дар од слуге својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Али он рече: тако да је жив Господ, пред којим стојим, нећу узети. И он наваљиваше на њ да узме; али он не хтје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Тада рече Неман: кад нећеш, а оно нека се да слузи твојему ове земље колико могу понијети двије мазге. Јер слуга твој неће више приносити жртава паљеница ни других жртава другим боговима, него Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'А Господ нека опрости ово слузи твојему: кад господар мој уђе у дом Римонов да се поклони ондје, па се прихвати за моју руку, да се и ја поклоним у дому Римонову, нека опрости Господ слузи твојему кад се тако поклоним у дому Римонову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'А он му рече: иди с миром. И он отиде од њега, и пријеђе једно потркалиште.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Тада рече Гијезије слуга Јелисија човјека Божијега: гле, господар мој не хтје примити из руку тога Немана Сирца што бјеше донео. Али тако да је жив Господ потрчаћу за њим и узећу што од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'И Гијезије отрча за Неманом. А кад га видје Неман гдје трчи за њим, скочи с кола својих и срете га, па му рече: је ли добро?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'А он рече: добро је. Господар мој посла ме да ти кажем: ево, баш сад дођоше к мени два младића из горе Јефремове, пророчки синови, дај за њих таланат сребра и двоје стајаће хаљине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'А Неман рече: узми и два таланта. И натјера га; и свеза два таланта сребра у два тобоца, и двоје стајаће хаљине, и даде двојици момака својих, да носе пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'А он кад дође на брдо, узе из руку њиховијех и остави у једној кући, а људе отпусти, те отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Потом дошавши стаде пред господаром својим. А Јелисије му рече: откле Гијезије? А он рече: није ишао слуга твој никуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Али му он рече: зар срце моје није ишло онамо кад се човјек врати с кола својих преда те? Зар је то било вријеме узимати сребро и узимати хаљине, маслинике, винограде, овце, говеда, слуге и слушкиње?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Зато губа Неманова нека прионе за те и за сјеме твоје довијека. И отиде од њега губав, био као снијег.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'А синови пророчки рекоше Јелисију: гле, мјесто гдје седимо пред тобом тијесно нам је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Него хајде да отидемо на Јордан, па да узмемо ондје сваки по брвно и начинимо ондје мјесто гдје ћемо боравити. А он рече: идите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'А један рече: буди вољан, пођи и ти са слугама својим. А он рече: хоћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'И тако пође с њима. И дошавши на Јордан сјекоше дрва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'А кад један од њих сијецијаше дрво, паде му сјекира у воду; а он повика говорећи: авај господару, још је у наруч узета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'А човјек Божји рече му: гдје је пала? А кад му показа мјесто, он отсијече дрво и баци га онамо, и учини те сјекира исплива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'А он рече: узми је. И човјек пружи руку, те је узе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'А кад цар Сирски војеваше на Израиља, вијећаше са слугама својим, и рече: ту и ту нека стане војска моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'А човјек Божји посла к цару Израиљеву и поручи: чувај се да не идеш онуда, јер су ондје Сирци у засједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'И цар Израиљев посла на оно мјесто, за које рече човјек Божји и опомену га, те се чуваше. И то не би једанпут ни двапута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'И смути се срце цару Сирском зато, и сазвавши слуге своје рече им: хоћете ли ми казати ко од наших доказује цару Израиљеву?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'А један од слуга његовијех рече му: нико, царе господару мој; него Јелисије пророк у Израиљу доказује цару Израиљеву ријечи које говориш у ложници својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Тада рече: идите, видите гдје је, да пошљем да га ухвате. И јавише му говорећи: ено га у Дотану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'И посла онамо коње и кола с великом војском; и они дошавши ноћу опколише град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'А ујутру слуга човјека Божијега уставши изиде, а то војска око града и коњи и кола. И рече му слуга: јаох господару, шта ћемо сад?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'А он му рече: не бој се, јер је више наших него њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'И помоли се Јелисије говорећи: Господе, отвори му очи да види. И Господ отвори очи момку, те видје, а то гора пуна коња и кола огњенијех око Јелисија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'А кад пођоше Сирци к њему, помоли се Јелисије Господу и рече: ослијепи овај народ. И ослијепи их по ријечи Јелисијевој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Тада им рече Јелисије: није ово пут, није ово град; ходите за мном и одвешћу вас човјеку којега тражите. И одведе их у Самарију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'А кад дођоше у Самарију, рече Јелисије: Господе, отвори им очи да виде. И Господ им отвори очи, и видјеше, а то бијаху усред Самарије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'А цар Израиљев рече Јелисију кад их угледа: хоћу ли бити, хоћу ли бити, оче мој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'А он рече: немој бити; еда ли ћеш оне побити које заробиш мачем својим и луком својим? Изнеси им хљеба и воде нека једу и пију, па онда нека иду господару својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'И уготови им гозбу велику; те једоше и пише; па их отпусти, а они отидоше господару својему; и отада не долазише чете Сирске у земљу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'А послије тога Вен-Адад цар Сирски скупи сву војску своју, и изиде и опколи Самарију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'И наста велика глад у Самарији, јер гле, бјеше опкољена толико да глава магарећа бијаше за осамдесет сикала сребра, а четврт кава голубињега кала за пет сикала сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'И кад цар иђаше по зидовима, једна жена повика к њему говорећи: помагај, царе господару!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'А он рече: Господ ти не помаже, како ћу ти ја помоћи? с гумна ли, или из каце?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Још јој рече цар: што ти је? А она рече: ова жена рече ми: дај сина свога да га поједемо данас, а сјутра ћемо појести мога сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'И скухасмо сина мојега и поједосмо га, а сјутрадан рекох јој: дај сина својега да га поједемо. Али она сакри свога сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'А кад цар чу ријечи женине, раздрије хаљине своје; и кад иђаше по зиду, видје народ гдје костријет бијаше оздо на тијелу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Тада рече цар: тако да ми учини Бог и тако да дода, ако глава Јелисија сина Сафатова остане данас на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'А Јелисије сјеђаше у својој кући, и старјешине сјеђаху код њега. И посла цар једнога од онијех што стајаху пред њим; а док још не дође послани к њему, он рече старјешинама: видите ли гдје онај крвнички син посла да ми отсијече главу? Гледајте кад дође послани, закључајте врата, и одбијте га од врата; ето, и бахат ногу господара његова за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'И док још говораше с њима, гле, послани дође к њему, и рече; гле, ово је зло од Господа; чему ћу се још надати од Господа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Тада рече Јелисије: чујте ријеч Господњу: тако вели Господ: сјутра ће у ово доба бити мјера бијелога брашна за сикал а двије мјере јечма за сикал на вратима Самаријским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'А војвода на којега се руку цар наслањаше, одговори човјеку Божијему и рече: да Господ начини окна на небу, би ли могло то бити? А Јелисије рече: ето, ти ћеш видјети својим очима, али га нећеш јести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'А бијаху на вратима четири човјека губава, и рекоше један другому: што сједимо овдје да умремо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Да речемо: да уђемо у град, глад је у граду, те ћемо умријети ондје: а да останемо овдје, опет ћемо умријети; него хајде да ускочимо у око Сирски: ако нас оставе у животу, остаћемо у животу, ако ли нас погубе, погинућемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'И тако уставши у сумрак пођоше у око Сирски, и дођоше до краја окола Сирскога, и гле, не бјеше никога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Јер Господ учини те се у околу Сирском чу лупа кола и коња и велике војске, те рекоше један другому: ето цар је Израиљев најмио на нас цареве Хетејске и цареве Мисирске да ударе на нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Те се подигоше и побјегоше по мраку оставивши шаторе своје и коње своје и магарце своје и око као што је био, и побјегоше ради душа својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Па кад дођоше губавци на крај окола, уђоше у један шатор, и наједоше се и напише се, и покупише из њега сребро и злато и хаљине, и отидоше те сакрише. Па се вратише и уђоше у други шатор, па покупише и из њега, и отидоше те сакрише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Тада рекоше међу собом: не радимо добро; овај је дан дан добријех гласова; а ми шутимо. Ако ушчекамо до зоре, стигнуће нас безакоње. Зато сада хајде да идемо и јавимо дому цареву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'И тако дошавши дозваше вратара градскога и казаше му говорећи: идосмо у око Сирски, и гле, нема никога, ни гласа човјечијега; него коњи повезани и магарци повезани, и шатори како су били.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'А он дозва остале вратаре, и јавише у дом царев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'А цар уставши по ноћи рече слугама својим: казаћу вам сада шта су нам учинили Сирци. Знаду да гладујемо, зато отидоше из окола да се сакрију у пољу говорећи: кад изиду из града, похватаћемо их живе и ући ћемо у град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'А један од слуга његовијех одговори и рече: да узмемо пет осталијех коња што још има и у граду; гле, то је све што је остало од мноштва коња Израиљских; то је све што није изгинуло од мноштва коња Израиљских; да пошљемо да видимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'И узеше два коња колска, које посла цар за војском Сирском, говорећи: идите и видите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'И отидоше за њима до Јордана, и гле, по свему путу бијаше пуно хаљина и судова, које побацаше Сирци у хитњи. Тада се вратише посланици и јавише цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Тада изиде народ и разграби око Сирски; и бјеше мјера бијелога брашна за сикал, и двије мјере јечма за сикал, по ријечи Господњој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'И цар постави на врата онога војводу, на којега се руку наслањаше, а народ га изгази на вратима, те умрије, по ријечи човјека Божијега, коју рече кад цар к њему дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Јер кад човјек Божји рече цару: двије мјере јечма за сикал и мјера бијелога брашна за сикал биће сјутра у ово доба на вратима Самаријским,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'А онај војвода одговори човјеку Божијему говорећи: да Господ начини окна на небу, би ли могло бити што кажеш? А Јелисије рече: ти ћеш видјети својим очима, али га нећеш јести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'И зби му се то, јер га изгази народ на вратима, те умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'И говори Јелисије жени којој сина поврати у живот, и рече: устани и иди с домом својим, и склони се гдје можеш; јер је Господ дозвао глад која ће доћи и бити на земљи седам година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'А жена уста, и учини како рече човјек Божји, јер отиде с домом својим и оста у земљи Филистејској седам година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'А кад прође седам година, врати се жена из земље Филистејске, и отиде да моли цара за кућу своју и за њиву своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'А цар говораше с Гијезијем, момком човјека Божијега, и рече: приповједи ми сва велика дјела која је учинио Јелисије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'А кад он приповједаше цару како је мртва оживио, гле, жена, којој је сина оживио, стаде молити цара за кућу своју и за њиву своју. А Гијезије рече: господару мој, царе, ово је она жена и ово је син њезин, којега је Јелисије оживио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Тада цар запита жену, и она му приповједи. И цар јој даде једнога дворанина и рече му: поврати јој све што је њезино и све приходе од њива од дана кад је оставила земљу дори до сада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Послије тога дође Јелисије у Дамаск, а цар Сирски Вен-Адад бијаше болестан, и јавише му говорећи: дошао је човјек Божји овамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'А цар рече Азаилу: узми са собом дар и иди на сусрет човјеку Божијему, и преко њега питај Господа хоћу ли оздравити од ове болести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Тада отиде Азаило на сусрет њему понесавши дар, свакојаких добријех ствари из Дамаска натоваренијех на четрдесет камила; и дошав стаде пред њим и рече: син твој Вен-Адад цар Сирски посла ме к теби говорећи: хоћу ли оздравити од ове болести?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'А Јелисије му рече: иди, реци му: оздравићеш; али ми је Господ показао да ће умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'И упрвши очи у њ гледаше дуго и заплака се човјек Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'А Азаило му рече: што плаче господар мој? А он рече: јер знам какво ћеш зло учинити синовима Израиљевијем, градове ћеш њихове палити огњем, и младиће ћеш њихове сјећи мачем, и дјецу ћеш њихову разбијати и трудне жене њихове растрзати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'А Азаило рече: а шта је слуга твој, пас, да учини тако велику ствар? А Јелисије му рече: показао ми је Господ да ћеш ти бити цар у Сирији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Тада отишав од Јелисија дође ка господару својему; а он му рече: што ти рече Јелисије? А он одговори: рече ми да ћеш оздравити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Али сјутрадан узе Азаило покривач и замочивши га у воду прострије му по лицу, те умрије. А на његово мјесто зацари се Азаило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Пете године царовања Јорама сина Ахавова над Израиљем, кад Јосафат бјеше цар Јудин, поче царовати Јорам син Јосафатов цар Јудин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Имаше тридесет и двије године кад поче царовати, и царова осам година у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'И хођаше путем царева Израиљевијех, као што је чинио дом Ахавов; јер кћи Ахавова бјеше му жена, те он чињаше што је зло пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Али Господ не хтје затрти Јуде ради Давида слуге својега, као што му бјеше рекао да ће му дати видјело између синова његовијех довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'За његова времена одврже се Едом да не буде под Јудом, и постави цара над собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Зато отиде Јорам у Саир и сва кола његова с њим; и уста ноћу и удари на Едомце, који га бијаху опколили, и на заповиједнике од кола, и побјеже народ у своје шаторе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Ипак се одвргоше Едомци да не буду под Јудом, до данашњега дана. У исто вријеме одметну се и Ливна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'А остала дјела Јорамова и све што је чинио, није ли то записано у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'И Јорам почину код отаца својих, и би погребен код отаца својих у граду Давидову. А на његово се мјесто зацари син његов Охозија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Године дванаесте царовања Јорама сина Ахавова над Израиљем поче царовати Охозија син Јорамов, цар Јудин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Имаше Охозија двадесет и двије године кад се зацари, и царова годину дана у Јерусалиму. Матери му бјеше име Готолија, кћи Амрија цара Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Он хођаше путем дома Ахавова, и чињаше што је зло пред Господом, као дом Ахавов, јер бјеше зет дому Ахавову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Зато пође с Јорамом сином Ахавовијем на војску на Азаила цара Сирскога у Рамот Галадски; али Сирци разбише Јорама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'И врати се цар Јорам да се лијечи у Језраелу од рана које му задаше Сирци у Рами, кад се бијаше с Азаилом царем Сирским; а Охозија син Јорамов цар Јудин отиде да види Јорама сина Ахавова у Језраелу, јер бијаше болестан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'А Јелисије пророк дозва једнога између синова пророчких, и рече му: опаши се и узми ову уљаницу, па иди у Рамот Галадски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'И кад дођеш онамо, видјећеш ондје Јуја сина Јосафата сина Нимсијина, и ушавши изведи га између браће његове и одведи га у најтајнију клијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'И узми уљаницу и излиј му на главу, и реци: овако вели Господ: помазах те за цара над Израиљем. Затијем отвори врата и бјежи, и не забављај се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'И отиде младић, момак пророков, у Рамот Галадски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'И кад уђе, гле, сјеђаху војводе; а он рече: војводо, имам нешто да ти кажем. А Јуј му рече: коме између свијех нас? А он рече: теби, војводо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Тада уста, и уђе у кућу, а он му изли на главу уље, и рече му: овако вели Господ Бог Израиљев: помазах те за цара над народом Господњим, Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'И побиј дом Ахава господара својега, јер хоћу да покајем крв слуга својих пророка, и крв свијех слуга Господњијех од руке Језавељине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'И тако ће изгинути сав дом Ахавов, и истријебићу Ахаву и оно што уза зид мокри, и ухваћенога и остављенога у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'И учинићу с домом Ахавовијем као с домом Јеровоама сина Наватова и као с домом Васе сина Ахијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'И Језавељу ће изјести пси у пољу Језраелском и неће бити никога да је погребе. Потом отвори врата и побјеже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'А Јуј изиде к слугама господара својега, и запиташе га: је ли добро? што је дошао тај безумник к теби? А он им рече: знате човјека и бесједу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'А они рекоше: није истина; кажи нам. А он им рече: тако и тако рече ми говорећи: овако вели Господ: помазах те за цара над Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Тада брже узеше свак своју хаљину, и метнуше пода њ на највишем басамаку, и затрубише у трубу и рекоше: Јуј поста цар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Тако се побуни Јуј син Јосафата сина Нимсијина на Јорама; а Јорам чуваше Рамот Галадски са свијем Израиљем од Азаила цара Сирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'А бјеше се вратио цар Јорам да се лијечи у Језраелу од рана које му задаше Сирци, кад се бијаше с Азаилом царем Сирским. И рече Јуј: ако вам је воља, нека нико не излази из града да отиде и јави у Језраел.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'И Јуј сједе на кола и отиде у Језраел, јер Јорам лежаше ондје; и Охозија цар Јудин бјеше дошао да види Јорама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'А стражар који стајаше на кули у Језраелу, кад угледа људство Јујево гдје иде, рече: неко људство видим. Тада рече Јорам: узми коњика и пошљи га пред њих, и нека запита: је ли мир?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'И отиде коњик преда њ, и рече: овако вели цар: је ли мир? А Јуј рече: шта је теби до мира? хајде за мном. А стражар јави говорећи: гласник дође до њих, али се не враћа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'И посла другога коњика, који кад дође к њима рече: овако вели цар: је ли мир? А Јуј рече: шта је теби до мира? хајде за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Опет јави стражар говорећи: дође до њих, али се не враћа; а ход као да је ход Јујев, јер иде помамно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Тада рече Јорам: прежи. И упрегоше у кола његова. Тако изиде Јорам цар Израиљев и Охозија цар Јудин, сваки на својим колима, и отидоше на сусрет Јују, и сретоше га на њиви Навутеја Језраељанина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'И кад Јорам угледа Јуја, рече му: је ли мир, Јују? А он одговори: какав мир? док је толикога курвања Језавеље матере твоје и чарања њезинијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Тада Јорам окрете се и побјеже говорећи Охозији: издаја, Охозија!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Али Јуј зграби лук свој и устријели Јорама међу плећи да му стријела прође кроз срце, те паде у колима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Тада рече Јуј Вадекару војводи свом: узми га, и баци га на њиву Навутеја Језраељанина; јер опомени се кад ја и ти заједно јахасмо за Ахавом оцем његовијем, како Господ изрече за њ ово зло:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Заиста, крв Навутејеву и крв синова његовијех видјех синоћ, рече Господ, и платићу ти на овој њиви, рече Господ. Зато узми га сад и баци на ту њиву по ријечи Господњој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'А Охозија цар Јудин видјевши то побјеже к дому у врту; али га потјера Јуј, и рече: убијте и тога на његовијем колима. И ранише га на брду Гуру, које је код Ивлеама. И утече у Мегидон, и ондје умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'И слуге га његове метнуше на кола и одвезоше у Јерусалим, и погребоше га у гробу његову код отаца његовијех у граду Давидову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'А једанаесте године царовања Јорама сина Ахавова поче царовати Охозија над Јудом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Иза тога Јуј дође у Језраел. А Језавеља кад чу, намаза лице своје и накити главу своју, па гледаше с прозора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'И кад Јуј улажаше на врата, рече она: је ли мир, Зимрије, крвниче господара својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'А он погледа на прозор и рече: ко је са мном? ко? Тада погледаше у њ два три дворанина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'А он им рече: баците је доље. И бацише је, и прште крв њезина по зиду и по коњма, и погази је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Потом ушавши једе и пи, па рече: видите ону проклетницу, и погребите је, јер је царска кћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'И отидоше да је погребу, и не нађоше од ње ништа до лубању и стопала и шаке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'И дођоше натраг и јавише, а он рече: то је ријеч Господња, коју је рекао преко слуге својега Илије Тесвићанина говорећи: у пољу Језраелском изјешће пси тијело Језавељино.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Нека буде тијело Језавељино као гној на њиви у пољу Језраелском да се не може казати: ово је Језавеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'А Ахав имаше седамдесет синова у Самарији; и Јуј написа књигу и посла је у Самарију ка главарима Језраелским, старјешинама и хранитељима Ахавовијем, и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Како ова књига дође к вама, у којих су синови господара вашега и кола и коњи и град тврди и оружје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Гледајте који је најбољи и највјештији између синова господара вашега, те га посадите на пријесто оца његова, и бијте се за дом господара свога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Али се они врло уплашише и рекоше: ето, два цара не одољеше му, а како ћемо му ми одољети?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'И који бијаше над домом, и који бијаше над градом, и старјешине и хранитељи послаше к Јују говорећи: ми смо слуге твоје, чинићемо све што нам кажеш; нећемо никога постављати царем; чини што ти је воља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'И он им написа другу књигу говорећи: ако сте моји и слушате мене, узмите главе свијех синова господара својега и дођите к мени сјутра у ово доба у Језраел. А синови цареви, седамдесет људи, бијаху код најзнатнијех грађана, који их храњаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'И кад им дође ова књига, узеше синове цареве и поклаше, седамдесет људи, и метнувши главе њихове у котарице послаше му у Језраел.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'И дође гласник, који му јави говорећи: донесоше главе синова царевијех. А он рече: сложите их у двије гомиле на вратима, нека стоје до сјутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'А ујутру изашав стаде и рече свему народу: ви нијесте криви; ето, ја се подигох на господара својега и убих га; али ко поби све ове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Видите сада да није изостала ниједна ријеч Господња коју рече Господ за дом Ахавов, него је Господ учинио што је говорио преко слуге својега Илије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Потом поби Јуј све који бијаху остали од дома Ахавова у Језраелу и све властеље његове и пријатеље његове и свештенике његове, да не оста ниједан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Потом се подиже и пође да иде у Самарију; и кад бијаше код колибе пастирске на путу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Нађе Јуј браћу Охозије цара Јудина, и рече: ко сте? Они рекоше: ми смо браћа Охозијина и идемо да поздравимо синове цареве и синове царичине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Тада рече: похватајте их живе. И похваташе их живе и поклаше их на студенцу код колибе пастирске, њих четрдесет, и не остави ниједнога од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Потом отишав оданде нађе Јонадава сина Рихавова, који га срете. А он га поздрави и рече му: је ли срце твоје право као што је моје срце према твоме? А Јонадав одговори: јест. Ако јест, одговори Јуј, дај ми руку. И даде му руку; а он га узе к себи у кола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'И рече: хајде са мном, и види моју ревност за Господа. И одвезоше га на његовијем колима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'И кад дође у Самарију, поби све што бјеше остало од дома Ахавова у Самарији докле га не истријеби по ријечи коју Господ рече Илији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Потом сабра Јуј сав народ и рече му: Ахав је мало служио Валу, Јуј ће му служити више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Зато дозовите ми све пророке Валове, све слуге његове и све свештенике његове, ниједан да не изостане, јер велику жртву хоћу да принесем Валу; ко не дође, погинуће. А Јуј чињаше тако из пријеваре хотећи побити слуге Валове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'И рече Јуј: светкујте светковину Валу. И огласише је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'И посла Јуј по свему Израиљу, те дођоше све слуге Валове, и не изоста ниједан да не дође; и уђоше у кућу Валову, и напуни се кућа Валова од краја до краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Тада рече оному који бијаше над ризницом: изнеси хаљине свијем слугама Валовијем. И изнесе им хаљине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Затијем уђе Јуј с Јонадавом сином Рихавојијем у кућу Валову, и рече слугама Валовијем: промотрите и видите да није ту с вама који слуга Господњи, него само слуге Валове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'И тако уђоше да принесу приносе и жртве паљенице, а Јуј намјести напољу осамдесет људи, и рече: ако утече који од овијех људи које вам дајем у руке, душа ће ваша бити за душу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'А кад се сврши жртва паљеница, заповједи Јуј војницима и војводама: уђите, побијте их, да не изађе ниједан. И тако их побише оштријем мачем и побацаше их војници и војводе; потом отидоше у сваки град гдје бјеше кућа Валова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'И избацише ликове из куће Валове, и спалише их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'И изломише лик Валов и раскопаше кућу Валову, и од ње начинише проходе до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Тако Јуј истријеби Вала из Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Али не отступи Јуј од гријехова Јеровоама сина Наватова, којима наведе на гријех Израиља, од златнијех телаца, који бијаху у Ветиљу и у Дану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'А Господ рече Јују: што си добро свршио што је право преда мном, и што си учинио дому Ахавову све што ми је било у срцу, зато ће синови твоји сједјети на пријестолу Израиљеву до четвртога кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Али Јуј не пажаше да ходи по закону Господа Бога Израиљева свијем срцем својим, не отступи од гријехова Јеровоамовијех, којима наведе на гријех Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'У то вријеме поче Господ крњити Израиља, јер их поби Азаило по свијем међама Израиљевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'Од Јордана к истоку сунчаном, сву земљу Галадску, Гадову и Рувимову и Манасијину, од Ароира на потоку Арнону, и Галад и Васан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'А остала дјела Јујева и све што је чинио, и сва јунаштва његова, нијесу ли записана у дневнику царева Израиљевијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'И почину Јуј код отаца својих, и погребоше га у Самарији; а на његово се мјесто зацари Јоахаз син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'А царова Јуј над Израиљем у Самарији двадесет и осам година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'А Готолија мати Охозијина видјевши да јој погибе син уста и поби сав род царски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Али Јосавеја кћи цара Јорама сестра Охозијина, узе Јоаса сина Охозијина, и украде га између синова царевијех, које убијаху, и с дојкињом његовом сакри га од Готолије у ложницу, те не погибе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'И би сакривен с њом у дому Господњем шест година, а Готолија цароваше у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'А седме године посла Јодај и дозва стотинике и војводе и војнике, и уведе их к себи у дом Господњи, и ухвати вјеру с њима, и закле их у дому Господњем, и показа им сина царева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'И заповједи им говорећи: ово учините: вас трећина, који долазите у суботу, нека чувају стражу у дому царском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'А трећина нека буде на вратима Сурским, а трећина на вратима која су иза војника; и чувајте дом од силе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'А два дијела вас свијех који одлазе у суботу нека чувају стражу у дому Господњем око цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'И опколите цара сваки са својим оружјем у руци, и ко би навалио међу врсте нека се погуби, и будите с царем кад стане излазити и улазити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'И стотиници учинише све како заповједи Јодај свештеник; и узеше сваки своје људе који долажаху у суботу с онима који одлажаху у суботу, и дођоше к свештенику Јодају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'И свештеник даде стотиницима копља и штитове цара Давида, што бијаху у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'И војници стадоше сваки са својим оружјем у руци од десне стране дома до лијеве стране дома према олтару и према дому око цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Тада изведе сина царева, и метну му вијенац на главу, и даде му свједочанство, и поставише га царем, и помазаше га, и пљескајући рукама говораху: да живи цар!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'А кад Готолија чу вику народа, који се стјецаше, дође к народу у дом Господњи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'И погледа, и гле, цар стајаше код ступа по обичају, и кнезови и трубе око цара, и сав народ из земље радоваше се, и трубе трубљаху. Тада Готолија раздрије хаљине своје и повика: буна! буна!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'А свештеник Јодај заповједи стотиницима који бијаху над војском, и рече им: изведите је из врста напоље, и ко пође за њом погубите га мачем; јер рече свештеник: да не погине у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'И начинише јој мјесто; и кад дође на пут којим се иде у дом царски коњским вратима, ондје је убише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Тада Јодај учини завјет између Господа и цара и народа да ће бити народ Господњи, такођер и између цара и народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Потом сав народ земаљски отиде у дом Валов, и раскопаше дом и олтар, и изломише ликове његове сасвијем; а Матана свештеника Валова убише пред олтарима. А свештеник опет уреди службу у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'И узе стотинике и војводе и војнике и сав народ земаљски, и изведоше цара из дома Господњега, и уђоше у дом царски путем на врата војничка. И сједе на царски пријесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'И радоваше се сав народ земаљски, и град се умири пошто Готолију убише мачем код царскога дома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Јоасу бјеше седам година кад се зацари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Седме године Јујеве поче царовати Јоас, и царова четрдесет година у Јерусалиму. Матери му бјеше име Сивија из Вирсавеје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'И чињаше Јоас што је право пред Господом докле га год учаше свештеник Јодај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Али висине не бише оборене; народ још приношаше жртве и кађаше на висинама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'И Јоас рече свештеницима: сав новац посвећени, што се доноси у дом Господњи, новац онијех који иду у број, и новац од уцјене свачије, и сав новац што ко доноси од своје воље у дом Господњи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Нека свештеници узимају, сваки од својега познаника, и они нека оправљају што је трошно у дому гдје се год нађе да треба оправити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Али до године двадесет треће царовања Јоасова свештеници још не оправише што бијаше трошно у дому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Тада цар Јоас дозва Јодаја свештеника и остале свештенике, и рече им: зашто не оправљате што је трошно у дому? Отселе не узимајте новаца од својих познаника, јер треба да вратите да се оправи што је трошно у дому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'И свештеници присташе да не узимају новаца од народа и да не оправљају што је трошно у дому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Тада свештеник Јодај узе један ковчег, и прореза рупу на заклопцу, и метну га код олтара с десне стране како се улази у дом Господњи; и свештеници који чуваху врата меташе у њ све новце који се доношаху у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'А кад виђаху да има много новаца у ковчегу, тада долажаше писар царев с поглаваром свештеничким, и избројивши свезиваху новце који би се нашли у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Потом даваху готове новце онима који управљаху послом и стараху се за дом Господњи, а они их издаваху дрводјељама и посленицима који оправљаху дом Господњи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'И зидарима и каменарима, и да се добавља дрво и тесано камење, да се оправи што бјеше трошно у дому Господњем, и да се добави све што требаше да се оправи дом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Али новцима који доношаху у дом Господњи не грађаху чаша сребрнијех за дом Господњи, ни виљушака, ни котлића, ни труба, нити каких судова златнијех ни сребрнијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Него их даваху онима који бијаху над послом да се оправи за њих дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'И не тражаху рачуна од људи којима предаваху новце да издају посленицима, јер вјерно рађаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Новци за пријеступ и новци за гријехе не доношаху се у дом Господњи; припадаху свештеницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Тада изиде Азаило цар Сирски, и удари на Гат и узе га; потом се окрете Азаило да иде на Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'А Јоас цар Јудин узе све посвећене ствари, што Јосафат и Јорам и Охозија оци његови цареви Јудини бијаху посветили, и све што сам бјеше посветио, и све злато што се нађе у ризницама дома Господњега и дома царева, и посла Азаилу цару Сирском; и тако отиде од Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'А остала дјела Јоасова и све што је чинио, није ли то записано у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'А слуге његове подигоше се и побунише се, и убише Јоаса у дому Милону, куда се иде у Силу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Јоазахар син Симеатов и Јозавад син Сомиров, слуге његове, убише га, те умрије; и погребоше га код отаца његовијех у граду Давидову; а на његово мјесто зацари се Амасија син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Године двадесет треће царовања Јоаса сина Охозијина над Јудом зацари се Јоахаз син Јујев над Израиљем у Самарији, и царова седамнаест година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'И чињаше што је зло пред Господом, јер хођаше за гријесима Јеровоама сина Наватова, којима наведе на гријех Израиља и не отступи од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Зато се разгњеви Господ на Израиља и даде их у руке Азаилу цару Сирском и у руке Вен-Ададу сину Азаилову за све оно вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Али се Јоахаз помоли Господу, и Господ га услиши, јер видје невољу Израиљеву, како их мучи цар Сирски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'И даде Господ Израиљу избавитеља, те се опростише руке Сирске, и живљаху синови Израиљеви у шаторима својим као прије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Али не отступише од гријехова дома Јеровоамова којима на гријех наведе Израиља, него ходише у њима, и сам луг још стајаше у Самарији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'А не оста Јоахазу народа више од педесет коњика и десет кола и десет тисућа пјешака; него их поби цар Сирски и сатр их, те бише као прах кад се врше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'А остала дјела Јоахазова и све што је чинио, и јунаштва његова, није ли то записано у дневнику царева Израиљевијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'И почину Јоахаз код отаца својих, и погребоше га у Самарији; а на мјесто његово зацари се Јоас син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Године тридесет седме царовања Јоасова над Јудом зацари се Јоас син Јоахазов над Израиљем у Самарији, и царова шеснаест година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'И чињаше што је зло пред Господом, не отступи ни од једнога гријеха Јеровоама сина Наватова, који наведе Израиља на гријех, него у њима хођаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'А остала дјела Јоасова, и све што је чинио, и јунаштва његова, како је војевао с Амасијом царем Јудинијем, није ли то записано у дневнику царева Израиљевијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'И почину Јоас код отаца својих, а Јеровоам сједе на пријесто његов; и погребоше Јоаса у Самарији код царева Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'А Јелисије разбоље се од болести, од које и умрије; и Јоас цар Израиљев дође к њему, и плачући пред њим говораше: оче мој, оче мој, кола Израиљева и коњици његови!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'А Јелисије му рече: узми лук и стријеле. И он узе лук и стријеле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Тада рече цару Израиљеву: натегни лук руком својом. И натеже лук руком својом. А Јелисије метну руке своје цару на руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'И рече: отвори прозор с истока. И отвори, а Јелисије рече: пусти стријелу. И он пусти стријелу, а Јелисије рече: стријела избављења Господњега, стријела избављења од Сираца; јер ћеш побити Сирце у Афеку, и сатрћеш их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Још рече: узми стријеле. И узе, а он рече цару Израиљеву: удари у земљу. И удари три пута, па стаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Тада се расрди на њ човјек Божји и рече: да си ударио пет пута или шест пута, тада би побио Сирце сасвијем; а сада ћеш их само три пута разбити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Потом умрије Јелисије, и погребоше га. А друге године ударише чете Моавске на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'И догоди се кад погребаваху некога човјека, угледаше чету и бацише човјека у гроб Јелисијев; и кад човјек паде и дотаче се костију Јелисијевих, оживје и уста на ноге своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'А Азаило цар Сирски мучаше Израиља свега вијека Јоахазова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Али се Господу сажали за њима и смилова се на њих и погледа на њих завјета ради својега с Аврамом, Исаком и Јаковом, и не хтје их истријебити и не одврже их од себе досада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'И умрије Азаило цар Сирски, и на његово се мјесто зацари Вен-Адад син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'А Јоас син Јоахазов поврати из руке Вен-Адада сина Азаилова градове које бјеше Азаило узео ратом Јоахазу оцу његову; три пута га разби Јоас, и поврати градове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Друге године царовања Јоаса сина Јоахазова над Израиљем зацари се Амасија син Јоасов над Јудом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Бијаше му двадесет и пет година кад поче царовати, и царова двадесет и девет година у Јерусалиму. Матери му бјеше име Јоадана, из Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'И чињаше што је право пред Господом, али не као Давид отац његов; сасвијем чињаше онако како је чинио отац његов Јоас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Јер висине не бише оборене: народ још приношаше жртве и кађаше на висинама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'А кад се утврди царство у руци његовој, он поби слуге своје које су убиле цара оца његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Али синова тијех крвника не поби, као што пише у књизи закона Мојсијева, гдје је заповједио Господ говорећи: оцеви да не гину за синове нити синови за оцеве, него сваки за свој гријех нека гине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Он поби десет тисућа Едомаца у сланој долини, и узе Селу ратом, и прозва је Јоктеил, које оста до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Тада посла Амасија посланике к Јоасу сину Јоахаза сина Јујева, цару Израиљеву, и рече: дођи да се огледамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'А Јоас цар Израиљев посла к Амасији цару Јудину и поручи му: трн на Ливану посла ка кедру на Ливану, и поручи: дај своју кћер сину мојему за жену; али наиђе звијерје Ливанско, и изгази трн.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Побио си Едомце, па се понесе срце твоје; хвали се, и сједи код куће своје; зашто би се заплетао у зло да паднеш и ти и Јуда с тобом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Али не послуша Амасија; и подиже се Јоас цар Израиљев, и огледаше се, он и Амасија цар Јудин, у Вет-Семесу Јудину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Али Јуду разби Израиљ, те побјегоше сваки к својему шатору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'А Амасију цара Јудина, сина Јоаса сина Охозијина, ухвати Јоас цар Израиљев у Вет-Семесу; потом дође у Јерусалим и обори зид Јерусалимски од врата Јефремовијех до врата на углу четири стотине лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'И узе све злато и сребро и све посуђе што се нађе у дому Господњем и у ризницама дома царева, и таоце, па се врати у Самарију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'А остала дјела Јоасова, што је учинио, и јунаштва његова, и како је војевао с Амасијом царем Јудинијем, није ли то записано у дневнику царева Израиљевијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'И почину Јоас код отаца својих, и би погребен у Самарији код царева Израиљевијех, а на његово се мјесто зацари Јеровоам син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Амасија пак син Јоасов цар Јудин поживје петнаест година по смрти Јоаса сина Јоахазова, цара Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'А остала дјела Амасијина нијесу ли записана у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'И дигоше буну на њ у Јерусалиму, те побјеже у Лахис, а они послаше за њим у Лахис и убише га ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'А оданде га донесоше на коњма, и би погребен у Јерусалиму код отаца својих у граду Давидову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Тада сав народ Јудин узе Азарију, коме бијаше шеснаест година, и зацарише га на мјесто оца његова Амасије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Он сазида Елат повратив га Јуди пошто цар почину код отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Године петнаесте царовања Амасије сина Јоасова над Јудом зацари се Јеровоам син Јоасов над Израиљем у Самарији, и царова четрдесет и једну годину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'И чињаше што је зло пред Господом и не отступи ни од једнога гријеха Јеровоама сина Наватова којима наведе на гријех Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Он поврати међе Израиљеве од Емата до мора уз поље, по ријечи Господа Бога Израиљева, коју рече преко слуге својега Јоне сина Аматијина, пророка из Гетефера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Јер Господ видје да је у љутој невољи Израиљ, и да нема ништа ни од ухваћенога ни од остављенога, и да нема никога да поможе Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'И не бјеше рекао Господ да затре име Израиљево под небом; зато их избави преко Јеровоама сина Јоасова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'А остала дјела Јеровоамова, и све што је чинио, и јунаштва његова, како је војевао и како је повратио Дамасак и Емат од Јуде Израиљу, није ли то записано у дневнику царева Израиљевијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Потом почину Јеровоам код отаца својих, царева Израиљевијех а на његово се мјесто зацари Захарија син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Године двадесет седме царовања Јеровоамова над Израиљем зацари се Азарија син Амасијин над Јудом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Бјеше му шеснаест година кад се зацари, и царова педесет и двије године у Јерусалиму. Матери му бјеше име Јехолија, из Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Он чињаше што је право пред Господом сасвијем као што је чинио Амасија отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Али висине не бише оборене: народ још приношаше жртве и кађаше на висинама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'А Господ удари цара, те би губав до смрти своје; и живљаше у одвојеном дому; а Јотам син царев управљаше двором и суђаше народу у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'А остала дјела Азаријина и све што је чинио, није ли то записано у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'И почину Азарија код отаца својих, и погребоше га код отаца његовијех у граду Давидову; а на његово се мјесто зацари Јотам син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Тридесет осме године царовања Азаријина над Јудом зацари се Захарија син Јеровоамов над Израиљем у Самарији, и царова шест мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'И чињаше што је зло пред Господом као што су чинили оци његови; не отступи од гријехова Јеровоама сина Наватова, којима наведе на гријех Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'И побуни се на њ Салум син Јависов, и уби га пред народом и погуби га, и зацари се на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'А остала дјела Захаријина, ено записана су у дневнику царева Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'То је ријеч Господња коју рече Јују говорећи: синови твоји до четвртога кољена сједеће на пријестолу Израиљеву. И зби се тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Салум син Јависов зацари се тридесет девете године царовања Озијина над Јудом, и царова мјесец дана у Самарији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Јер Менајим син Гадијев из Терсе подиже се и дође у Самарију и уби Салума сина Јависова у Самарији, и погуби га, и зацари се на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'А остала дјела Салумова и буна коју подиже, ето, то је записано у дневнику царева Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Тада Менајим раскопа Тапсу и поби све који бијаху у њој и у међама њезинијем од Терсе, јер му не отворише, зато их поби и све трудне жене њихове распори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Године тридесет девете царовања Азаријина над Јудом зацари се Менајим син Гадијев над Израиљем, и царова десет година у Самарији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'И чињаше што је зло пред Господом, не отступи свега вијека својега од гријехова Јеровоама сина Наватова, којима наведе на гријех Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Тада Фул цар Асирски удари на земљу, а Менајим даде Фулу тисућу таланата сребра да би му помогао да утврди царство у својој руци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'А те новце узе Менајим од Израиља, од свијех богатијех људи, да их да цару Асирском, од свакога по педесет сикала. Тако се врати цар Асирски, и не забави се ондје у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'А остала дјела Менајимова и што је год чинио, није ли записано у дневнику царева Израиљевијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'И почину Менајим код отаца својих, а на његово се мјесто зацари Факија син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Године педесете царовања Азаријина над Јудом зацари се Факија син Менајимов над Израиљем у Самарији, и царова двије године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'И чињаше што је зло пред Господом, не отступи од гријехова Јеровоама сина Наватова, којима наведе на гријех Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'И побуни се на њ Фекај син Ремалијин, војвода његов, и уби га у Самарији у царском двору, с Арговом и Аријем и с педесет људи синова Галадовијех; и убивши га зацари се на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'А остала дјела Факијина и што је год чинио, ено је записано у дневнику царева Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Године педесет друге Азарије цара Јудина зацари се Фекај син Ремалијин над Израиљем у Самарији, и царова двадесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'И чињаше што је зло пред Господом, не отступи од гријехова Јеровоама сина Наватова, којима наведе на гријех Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'У вријеме Фекаја цара Израиљева дође Теглат-Феласар цар Асирски, и узе Ијон и Авел-Ветмаху и Јанох и Кедес и Асор и Гелад и Галилеју, сву земљу Нефталимову, и пресели народ оданде у Асирију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Тада се побуни Осија син Илин на Фекаја сина Ремалијина и уби га и погуби га, и зацари се на његово мјесто двадесете године Јотама сина Озијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'А остала дјела Фекајева и све што је чинио, ено је записано у дневнику царева Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Друге године царовања Фекаја сина Ремалијина над Израиљем зацари се Јотам син Озијин над Јудом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Бијаше му двадесет и пет година кад поче царовати, и царова шеснаест година у Јерусалиму. Матери му бјеше име Јеруса, кћи Садокова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'И чињаше што је право пред Господом, сасвијем чињаше како је чинио Озија отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Али висине не бише оборене: народ још приношаше жртве и кађаше на висинама. Он начини највиша врата на дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'А остала дјела Јотамова и све што је чинио, није ли записано у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'У то вријеме поче Господ пуштати на Јуду Ресина цара Сирскога и Фекаја сина Ремалијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'И Јотам почину код отаца својих, и би погребен код отаца својих у граду Давида оца својега; а на његово се мјесто зацари Ахаз син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Године седамнаесте Фекаја сина Ремалијина зацари се Ахаз син Јотамов цар Јудин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Двадесет година бијаше Ахазу кад поче царовати, и царова шеснаест година у Јерусалиму, али не чињаше што је право пред Господом Богом његовијем као Давид отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Јер хођаше путем царева Израиљевијех, па и сина својега пусти кроз огањ по гаднијем дјелима народа које одагна Господ испред синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'И приношаше жртве и кађаше на висинама и по хумовима и под сваким зеленијем дрветом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Тада дође Ресин цар Сирски и Фекај син Ремалијин цар Израиљев, дођоше да бију Јерусалим, и опколише Ахаза; али га не могоше освојити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'У то вријеме Ресин цар Сирски поврати Сирцима Елат, и изагна Јудеје из Елата, и дођоше Сирци у Елат и осташе ондје до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Али Ахаз посла посланике к Теглат-Феласару цару Асирском у поручи му: слуга сам твој, ходи и избави ме из руку цара Сирскога и из руку цара Израиљева, који се подигоше на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'И узе Ахаз злато и сребро што се нађе у дому Господњем и у ризницама дома царскога, и посла на дар цару Асирском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'И послуша га цар Асирски, и дође на Дамасак и узе га, и пресели народ оданде у Кир, а Ресина погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Тада цар Ахаз отиде на сусрет Теглат-Феласару цару Асирском у Дамасак; и видје цар Ахаз олтар који бијаше у Дамаску, па посла свештенику Урији слику од тога олтара и од све направе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'И начини свештеник Урија олтар сасвијем како посла цар Ахаз из Дамаска, онако начини Урија свештеник, докле се врати цар Ахаз из Дамаска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Па кад се цар врати из Дамаска и видје олтар, приступи к њему и принесе жртву на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'И запали жртву своју паљеницу и дар свој, и изли наљев свој, и покропи олтар крвљу захвалнијех жртава својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'А мједени олтар што бјеше пред Господом пренесе с предње стране дома да не стоји између његова олтара и дома Господњега, и намјести га покрај свога олтара к сјеверу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'И заповједи цар Ахаз Урији свештенику говорећи: на великом олтару пали жртву паљеницу јутрењу и дар вечерњи и жртву паљеницу цареву с даром њезинијем и жртву паљеницу свега народа земаљскога с даровима њиховијем и наљевима њиховијем; и по њему кропи сваком крвљу од жртава паљеница и сваком крвљу од других жртава. А за олтар мједени промислићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'И учини свештеник Урија све како му заповједи цар Ахаз.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'И оплате с подножја скиде цар Ахаз и узе с њих умиваонице, и море скиде с волова мједенијех који бијаху под њим, и метну га на под камени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'И стреху суботну, коју бијаху начинили у дому, и улазак царски, који бијаше споља, уклони такођер од дома Господњега, бојећи се цара Асирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'А остала дјела Ахазова што је чинио, нијесу ли записана у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'И почину Ахаз код отаца својих, и би погребен код отаца својих у граду Давидову; а на његово се мјесто зацари Језекија син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Дванаесте године царовања Ахазова над Јудом зацари се у Самарији над Израиљем Осија син Илин, и царова девет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'И чињаше што је зло пред Господом, али не као цареви Израиљеви који бише прије њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'На њега дође Салманасар цар Асирски, и Осија му поста слуга, те му плаћаше данак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Али цар Асирски опази да Осија хоће да се одметне, јер Осија посла посланике к Соју цару Мисирском и не посла данка годишњега цару Асирском; зато га опколи цар Асирски и свезавши баци га у тамницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'А цар Асирски прође сву земљу и дође на Самарију, и би је три године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Девете године Осијине узе цар Асирски Самарију и одведе Израиља у Асирију и насели у Алају и у Авору на води Гозану и у градовима Мидским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'А то би што синови Израиљеви гријешише Господу Богу својему, који их је извео из земље Мисирске испод руке Фараона цара Мисирскога, и бојаше се других богова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'И ходише по уредбама народа који одагна Господ испред синова Израиљевијех, и како чинише цареви Израиљеви;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'И тајно чинише синови Израиљеви што није право пред Господом Богом њиховијем, и поградише висине по свијем градовима својим, од куле стражарске до градова озиданијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'И подигоше ликове и лугове на сваком високом хуму и под сваким зеленијем дрветом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'И кађаху онуда по свијем висинама као народи које одагна Господ испред њих, и чињаху зле ствари гњевећи Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'И служаху гаднијем боговима, за које им бјеше Господ рекао: не чините то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'И Господ опомињаше Израиља и Јуду преко свијех пророка и свијех видјелаца говорећи: вратите се са злијех путова својих и држите заповијести моје и уредбе моје по свему закону који сам заповједио оцима вашим и који сам вам послао по слугама својим пророцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Али не послушаше; него бјеху тврдоврати као и оци њихови, који не вјероваше Господу Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'И одбацише уредбе његове и завјет његов, који учини с оцима њиховијем, и свједочанства његова, којима им свједочаше, и ходише за ништавилом и посташе ништави, и за народима који бијаху око њих, за које им бјеше заповједио Господ да не чине као они.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'И оставише све заповјести Господа Бога својега, и начинише себи ливене ликове, два телета, и лугове, и клањаше се свој војсци небеској, и служаше Валу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'И проводише синове своје и кћери своје кроз огањ, и даваше се на врачање и гатање, и продаше се да чине зло пред Господом гњевећи га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Зато се Господ разгњеви врло на Израиља, и одбаци их од себе, те не оста него само племе Јудино.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Па ни Јуда не држаше заповијести Господа Бога својега, него хођаше по уредбама које начинише Израиљци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Зато Господ поврже све сјеме Израиљево, и мучи их, и предаде их у руке онима који их плијене, докле их и одбаци од себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Јер се оцијепише Израиљци од дома Давидова, и поставише царем Јеровоама сина Наватова, а Јеровоам одби Израиљце од Господа и наведе их да гријеше гријехом великим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'И ходише синови Израиљеви у свијем гријесима Јеровоамовијем које је он чинио, и не отступише од њих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Докле Господ не одбаци Израиља од себе као што је говорио преко свијех слуга својих пророка, и тако пресељен би Израиљ из земље своје у Асирску до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Потом доведе цар Асирски људе из Вавилона и из Хуте и из Аве и из Емата и из Сефарвима, и насели их у градовима Самаријским мјесто Израиљаца, и наслиједише Самарију, и живљаху по градовима њезинијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'А кад почеше живјети ондје, не бојаху се Господа, а Господ посла на њих лавове, који их дављаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Зато рекоше цару Асирском говорећи: ови народи које си довео и населио у градовима Самаријским не знају закона Бога оне земље; зато посла на њих лавове, који их ето море, јер не знају закона Бога оне земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Тада заповједи цар Асирски и рече: одведите онамо једнога од свештеника које сте довели оданде, па нека иде и сједи ондје, нека их учи закону Бога оне земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'И тако један од свештеника, које бијаху одвели из Самарије, дође и настани се у Ветиљу, и учаше их како ће се бојати Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Али начинише себи сваки народ своје богове, и пометаше их у куће висина, које бијаху начинили Самарјани, сваки народ у својим градовима у којима живљаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Јер Вавилоњани начинише Сокот-Веноту, а Хућани начинише Нергала, а Емаћани начинише Асима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'И Ављани начинише Ниваза и Тартака, а Сефарвимци спаљиваху синове своје огњем Адрамелеху и Анамелеху боговима Сефарвимским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Али се бојаху Господа, и поставише између себе свештенике висинама, који им служаху у домовима висина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Бојаху се Господа, али и својим боговима служаху по обичају онијех народа из којих их преселише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'И до данашњега дана раде по старијем обичајима; не боје се Господа а не раде ни по својим уредбама и обичајима, ни по закону и заповијести што је заповједио Господ синовима Јакова, којему надје име Израиљ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'С којима учини Господ завјет и заповједи им и рече: не бојте се других богова нити им се клањајте нити им служите нити им приносите жртава;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Него Господа, који вас је извео из земље Мисирске силом великом и мишицом подигнутом, њега се бојте и њему се клањајте и њему приносите жртве;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'И уредбе и правила и закон и заповијести што вам је написао држите извршујући их вазда, и не бојте се других богова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'И не заборављајте завјета који је учинио с вама, и не бојте се других богова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Него Господа Бога својега бојте се, и он ће вас избавити из руку свијех непријатеља ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Али не послушаше, него радише по старом свом обичају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Тако ови народи бојаху се Господа и идолима својим служаху; и синови њихови и синови синова њиховијех чине до данашњега дана онако како су чинили оци њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'А треће године царовања Осије сина Илина над Израиљем зацари се Језекија син Ахазов над Јудом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Бијаше му двадесет и пет година кад поче царовати, и царова двадесет и девет година у Јерусалиму. Матери му бјеше име Авија, кћи Захаријина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'И чињаше што је право пред Господом сасвијем као што је чинио Давид отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Он обори висине, и изломи ликове и исјече лугове, и разби змију од мједи, коју бјеше начинио Мојсије, јер јој до тада кађаху синови Израиљеви; и прозва је Неустан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Уздаше се у Господа Бога Израиљева, и не би такога између свијех царева Јудинијех послије њега ни прије њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Јер приону за Господа, не отступи од њега, него држа заповијести које заповиједи Господ Мојсију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'И Господ бијаше с њим; куда год иђаше напредоваше; и одметну се од цара Асирскога, те му не би слуга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Он поби Филистеје до Газе и међе њезине, од кула стражарске до града озидана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'А четврте године царовања Језекијина, а то је седма година царовања Осије сина Илина над Израиљем, подиже се Салманасар цар Асирски на Самарију, и опколи је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'И послије три године узе је; шесте године царовања Језекијина, а девете године царовања Осијина над Израиљем, би узета Самарија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'И одведе цар Асирски Израиљце у Асирију, и насели их у Алају и у Авору на води Гозану и по градовима Мидским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Јер не слушаше гласа Господа Бога својега и преступаше завјет његов, све што им је заповједио Мојсије слуга Господњи, не слушаше нити творише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'А четрнаесте године царовања Језекијина подиже се Сенахирим цар Асирски на све тврде градове Јудине, и узе их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Тада Језекија цар Јудин посла у Лахис к цару Асирском и поручи му: згријешио сам; врати се од мене, што год наметнеш на ме носићу. А цар Асирски наметну на Језекију цара Јудина триста таланата сребра и тридесет таланата злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'И даде цар Језекија све сребро што се нађе у дому Господњем и у ризницама царскога двора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'У то вријеме цар Језекија раскопа врата на цркви Господњој и прагове које сам бјеше оковао, и даде цару Асирском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Али цар Асирски посла Тартана и Равсариса и Равсака из Лахиса к цару Језекији у Јерусалим с великом војском; и они се подигоше и дођоше у Јерусалим; и подигавши се и дошавши стадоше код јаза горњега језера, који је покрај пута у пољу бјељареву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'И стадоше викати цара. Тада дође к њима Елијаким син Хелкијин, који бијаше над двором и Сомна писар и Јоах син Асафов паметар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'И рече им Равсак: кажите цару Језекији: овако каже велики цар, цар Асирски: каква је то узданица, у коју се уздаш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Ти велиш, али су празне ријечи, да имаш свјета и силе за рат. У што се дакле уздаш, те си се одметнуо од мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Гле, уздаш се у Мисир, у штап од трске сломљене, на који ако се ко наслони, ући ће му у руку и пробошће је; таки је Фараон цар Мисирски свима који се уздају у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Ако ли ми речете: уздамо се у Господа Бога својега; није ли то онај чије је висине и олтаре оборио Језекија и заповједио Јуди и Јерусалиму: пред овијем олтаром клањајте се у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Хајде, затеци се мојему господару цару Асирском; и даћу ти двије тисуће коња, ако можеш добавити који ће јахати на њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Како ћеш дакле одбити и једнога војводу између најмањих слуга господара мојега? Али се ти уздаш у Мисир за кола и коњике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Сврх тога, еда ли сам ја без Господа дошао на ово мјесто да га затрем? Господ ми је рекао: иди на ту земљу, и затри је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Тада Елијаким син Хелкијин и Сомна и Јоах рекоше Равсаку: говори слугама својим Сирски, јер разумијемо, а немој нам говорити Јудејски да слуша народ на зиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'А Равсак им рече: еда ли ме је господар мој послао ка господару твојему или к теби да кажем ове ријечи? није ли к тијем људима, што сједе на зиду, да једу своју нечист и да пију своју мокраћу с вама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Тада стаде Равсак и повика иза гласа Јудејски, и рече говорећи: чујте ријеч великога цара, цара Асирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Овако каже цар: немојте да вас вара Језекија; јер вас не може избавити из моје руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Немојте да вас наговори Језекија да се поуздате у Господа, говорећи: Господ ће нас избавити, и овај се град неће дати у руке цару Асирском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Не слушајте Језекије; јер овако каже цар Асирски: учините мир са мном, и ходите к мени, па једите сваки са свога чокота и сваки са своје смокве, и пијте сваки из својега студенца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Докле не дођем и однесем вас у земљу као што је ваша, у земљу обилну житом и вином, у земљу обилну хљебом и виноградима, у земљу обилну маслином и уљем и медом, па ћете живјети и нећете изгинути. Не слушајте Језекије, јер вас вара говорећи: Господ ће нас избавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Је ли који између богова других народа избавио своју земљу из руке цара Асирскога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Гдје су богови Ематски и Арфадски? гдје су богови Сефарвимски, Енски и Авски? јесу ли избавили Самарију из мојих руку?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Који су између свијех богова овијех земаља избавили земљу своју из моје руке? а Господ ће избавити Јерусалим из моје руке?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Али народ мучаше, и не одговорише му ни ријечи, јер цар бјеше заповједио и рекао: не одговарајте му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Тада Елијаким син Хелкијин, који бијаше, над двором и Сомна писар и Јоах син Асафов, паметар, дођоше к Језекији раздрвши хаљине, и казаше му ријечи Равсакове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'А кад то чу цар Језекија, раздрије хаљине своје и веза око себе костријет, па отиде у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'И посла Елијакима, који бијаше над двором, и Сомну писара и најстарије свештенике обучене у костријет к Исаији пророку сину Амосову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'И рекоше му: овако вели Језекија: ово је дан невоље и кара и руга; јер приспјеше дјеца до порођаја, а нема снаге да се роде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Да ако је чуо Господ Бог твој све што рече Равсак, којега посла цар Асирски господар његов да ружи Бога живога и да га вријеђа ријечима, које је чуо Господ Бог твој; помоли се за остатак који се налази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'И дођоше к Исаији слуге цара Језекије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'И рече им Исаија: овако реците господару својему: овако вели Господ: не плаши се од ријечи које си чуо, којима хулише на ме слуге цара Асирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Ево, ја ћу пустити на њ дух, те ће чути глас и вратити се у своју земљу, и учинићу да погине од мача у својој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'И тако вративши се Равсак нађе цара Асирскога гдје бије Ливну, јер бјеше чуо да је отишао од Лахиса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'А он чу за Тираку цара Хускога гдје казаше: ево иде да се бије с тобом. Зато опет посла посланике к Језекији говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Овако реците Језекији цару Јудину: немој да те вара Бог твој, у којега се уздаш говорећи: неће се дати Јерусалим у руке цару Асирском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Ето чуо си шта су учинили цареви Асирски свијем земљама потрвши их сасвијем; а ти ли ћеш се избавити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Јесу ли народе које сатрше оци моји избавили богови њихови, Госанце, Харанце, Ресефе и синове Еденове, који бијаху у Теласару?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Гдје је цар Ематски и цар Арфадски и цар од града Сефарвима, од Ене и Аве?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'А кад Језекија прими књигу из руку посланика и прочита је, отиде у дом Господњи, и разви је Језекија пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'И помоли се Језекија Господу говорећи: Господе Боже Израиљев, који сједиш на херувимима, ти си сам, Бог свијем царствима на земљи, ти си створио небо и земљу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Пригни, Господе, ухо своје и чуј; отвори, Господе, очи своје и види; чуј ријечи Сенахирима, који посла да ружи Бога живога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Истина је, Господе, опустошили су цареви Асирски оне народе и земље њихове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'И побацали су богове њихове у огањ, јер не бијаху богови, него дјело руку човјечијих, дрво и камен; зато их потрше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'И зато, Господе Боже наш, избави нас из руку његовијех, да познаду сва царства на земљи да си ти Господе сам Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Тада посла Исаија син Амосов к Језекији, и поручи му: овако вели Господ Бог Израиљев: услишио сам зашто си ми се молио ради Сенахирима цара Асирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Ово је ријеч коју изрече Господ за њ: руга ти се и потсмијева ти се дјевојка, кћи Сионска, за тобом маше главом кћи Јерусалимска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Кога си ружио и хулио? и на кога си подигао глас? и подигао у вис очи своје? На свеца Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Преко посланика својих ружио си Господа и рекао си: с мноштвом кола својих изидох на високе горе, на стране Ливанске, и посјећи ћу високе кедре његове и лијепе јеле његове, и ући ћу у крајњи стан његов, у шуму његова Кармила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Ја сам копао и пио воду туђу, и исушио сам стопама својим све потоке градовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Нијеси ли чуо да ја то одавна чиним и од искона да сам тако уредио? сада пуштам то, да превратиш тврде градове у пусте гомиле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Зато који у њима живе изнемогоше, уплашише се и сметоше се, посташе као трава пољска, као зелена травица, као трава на крововима, која се суши прије него сазри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Знам сјеђење твоје, и полажење твоје и долажење твоје знам, и како бјесниш на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Јер бјесниш на ме, и твоја обијест дође до мојих ушију; зато ћу метнути брњицу своју на ноздрве твоје и узду своју у губицу твоју, па ћу те одвести натраг путем којим си дошао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'А теби ово нека буде знак: јешћете ове године што само од себе роди, и друге године што опет само од себе роди; а треће године сијте и жањите и садите винограде и једите род с њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Јер остатак дома Јудина, што остане, опет ће пустити жиле оздо и родити озго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Јер ће из Јерусалима изаћи остатак, и из горе Сиона, који се сачувају. Ревност Господа над војскама учиниће то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Зато овако вели Господ за цара Асирскога: нећу ући у овај град нити ће бацити амо стријеле, неће се примаћи ка њему са штитом, нити ће ископати опкопа око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Вратиће се путем којим је дошао, а у град овај неће ући, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Јер ћу бранити тај град, и сачуваћу га себе ради и ради Давида слуге својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'И исту ноћ анђео Господњи изиде и поби у околу Асирском сто и осамдесет и пет тусућа; и кад усташе ујутру, а то све сами мртваци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Те се подиже Сенахирим цар Асирски, и отиде, и вративши се оста у Ниневији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'И кад се клањаше у дому Нисрока бога својега, Адрамелех и Сарасар синови његови убише га мачем, а сами побјегоше у земљу Араратску, и на његово се мјесто зацари Есарадон син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'У то вријеме разбоље се Језекија на смрт; и дође к њему пророк Исаија син Амосов и рече му: овако вели Господ: нареди за кућу своју, јер ћеш умријети и нећеш остати жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'А он се окрете лицем к зиду, и помоли се Господу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Ох, Господе, опомени се да сам једнако ходио пред тобом вјерно и с цијелијем срцем, и творио што је теби угодно. И плака Језекија веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'И Исаија још не бјеше отишао до половине двора, а дође му ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Врати се и реци Језекији, вођу народа мојега: овако вели Господ Бог Давида оца твојега: чуо сам молитву твоју, и видио сам сузе твоје; ево исцијелићу те, до три дана ићи ћеш у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'И додаћу ти вијеку петнаест година, и избавићу тебе и овај град из руку цара Асирскога, и бранићу овај град себе ради и ради Давида слуге својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Потом рече Исаија: донесите груду сухих смокава. И донесавши привише му на оток, и исцијели се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'А Језекија рече Исаији: шта ће бити знак да ће ме Господ исцијелити и да ћу до три дана отићи у дом Господњи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'А Исаија рече: ово нека ти буде знак од Господа да ће учинити Господ што је рекао: хоћеш ли да отиде сјен десет кољенаца напријед или да се врати десет кољенаца натраг?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'А Језекија рече: лако је да сјен отиде напријед десет кољенаца; немој, него нека се врати сјен десет кољенаца натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'И Исаија пророк завапи ка Господу, и врати Господ сјен по кољенцима по којима бијаше отишао на сунчанику Ахазову натраг за десет кољенаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'У то вријеме Меродах-Валадан, син Валаданов, цар Вавилонски посла књигу с даром Језекији; јер бјеше чуо да је болестан Језекија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'И Језекија саслушав посланике показа им све ризнице своје, сребро и злато и мирисе, и најбоље уље, и кућу гдје му бјеше оружје, и што се год налажаше у ризницама његовијем, не оста ништа да им не показа Језекија у кући својој и у свему господству својем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Тада дође пророк Исаија к цару Језекији и рече му: шта су говорили ти људи и одакле су дошли к теби? А Језекија рече: из даљне земље дошли су, из Вавилона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'А он рече: шта су видјели у твом двору? А Језекија рече: видјели су све што има у мом двору; није остало ништа у ризницама мојим да им нијесам показао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Тада рече Исаија Језекији: чуј ријеч Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Ево доћи ће вријеме кад ће се однијети у Вавилон све што има у кући твојој, и што су сабирали оци твоји до данас, неће остати ништа, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'И синове твоје, који ће изаћи од тебе, које ћеш родити, узеће да буду дворани у двору цара Вавилонскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'А Језекија рече Исаији: добра је ријеч Господња, коју си рекао. Још рече: је ли? за мојега вијека биће мир и вјера?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'А остала дјела Језекијина и сва јунаштва његова, и како је начинио језеро, и воду довео у град, није ли записано у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'И почину Језекија код отаца својих, а на његово се мјесто зацари Манасија син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Дванаест година бјеше Манасији кад поче царовати, и царова педесет и пет година у Јерусалиму. Матери му бјеше име Ефсива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'И чињаше што је зло пред Господом по гаднијем дјелима народа, које Господ одагна испред синова Израиљевијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Јер опет начини висине, које бјеше потро Језекија отац његов, и подиже олтаре Валу, и начини луг као што бјеше начинио Ахав цар Израиљев, и клањаше се свој војсци небеској и служаше јој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'И начини олтаре у дому Господњем, за који бјеше рекао Господ: у Јерусалиму ћу намјестити име своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Начини олтаре свој војсци небеској у два тријема дома Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'И сина својега проведе кроз огањ, и врачаше и гаташе, и уреди оне што се договарају с духовима и врачаре; и чињаше врло много што је зло пред Господом, гњевећи га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'И постави резан лик шумски који начини у дому, за који бјеше рекао Господ Давиду и Соломуну сину његову: у овом дому и у Јерусалиму, који изабрах између свијех племена Израиљевијех, намјестићу име своје довијека;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'И нећу више дати да се макне нога синовима Израиљевијем из земље коју дадох оцима њиховијем, ако само уздрже и устворе све што сам им заповједио, и сав закон који им је заповједио мој слуга Мојсије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Али не послушаше, јер их заведе Манасија, те чинише горе него народи које истријеби Господ испред синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'А Господ говораше преко слуга својих пророка говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Што учини Манасија цар Јудин та гадна дјела чинећи горе од свега што су чинили Амореји који прије њега бише, и наведе на гријех и Јуду гаднијем боговима својим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Зато овако вели Господ Бог Израиљев: ево, ја ћу пустити зло на Јерусалим и на Јуду, да ће свакоме ко чује зујати оба уха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Јер ћу затегнути над Јерусалимом уже Самаријско и мјерила дома Ахавова, и збрисаћу Јерусалим, као што се брише здјела, и избише се па се изврне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'И оставићу остатак нашљедства својега, и даћу их у руке непријатељима њиховијем да буду плијен и грабеж свијем непријатељима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Јер чинише што је зло преда мном, и гњевише ме од дана кад изидоше оци њихови из Мисира до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Још и праву крв веома многу проли Манасија тако да напуни Јерусалим од краја до краја, осим гријеха својега којим наведе Јуду на гријех да чини што је зло пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'А остала дјела Манасијина и све што је чинио, и гријех, којим је гријешио, није ли то записано у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'И почину Манасија код отаца својих, и би погребен у врту код дома својега, у врту Озину; а на његово мјесто зацари се Амон син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Двадесет и двије године имаше Амон кад поче царовати, и царова двије године у Јерусалиму. Матери му бјеше име Месулемета, кћи Арусова, из Јотеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Он чињаше што је зло пред Господом, као што је чинио Манасија отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'И хођаше свијем путем којим је ходио отац његов, и служаше гаднијем боговима, којима је служио отац његов, и клањаше им се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'И остави Господа Бога отаца својих, и не ходи путем Господњим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'А слуге Амонове побунише се на њ, и убише цара у двору његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'А народ земаљски поби све који се бијаху побунили на цара Амона; и зацари народ земаљски на његово мјесто Јосију сина његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'А остала дјела Амонова, што је чинио, нијесу ли записана у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'И погребоше га у његову гробу у врту Озину; и Јосија син његов би цар на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Осам година бијаше Јосији кад поче царовати, и царова тридесет и једну годину у Јерусалиму. Матери му бјеше име Једида, кћи Адајева, из Воската.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Он чињаше што је право пред Господом, и хођаше свијем путем Давида оца својега и не отступаше ни надесно ни налијево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'А осамнаесте године царовања Јосијина посла цар Сафана сина Азалије сина Месуламова, писара, у дом Господњи, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Иди ка Хелкији поглавару свештеничком, нека изброји новце донесене у дом Господњи, што су накупили од народа вратари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'И нека их да посленицима који надгледају дом Господњи, па нека дају посленицима који раде око дома Господњега да се оправи што је трошно у дому,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'Дрводјељама и каменарима и зидарима, и да се купује дрво и камен тесани да се оправи дом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Али да им се не траже рачуни од новаца који им се даду, јер ће вјерно радити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Тада рече Хелкија поглавар свештенички Сафану писару: нађох законик у дому Господњем. И Хелкија даде књигу Сафану, и он је прочита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'А Сафан писар отиде к цару, и јави цару говорећи: покупише слуге твоје новце што се нађоше у дому, предаше их посленицима који надгледају дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'И каза Сафан писар цару говорећи: књигу ми даде Хелкија свештеник. И прочита је Сафан цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'А кад цар чу ријечи у законику, раздрије хаљине своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'И заповједи цар Хелкији свештенику и Ахикаму сину Сафанову и Ахвору сину Михејину и Сафану писару и Асаји слузи цареву, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Идите, упитајте Господа за ме и за народ и за свега Јуду ради ријечи ове књиге што се нађе; јер је велик гњев Господњи који се распалио на нас зато што оци наши не слушаше ријечи ове књиге да чине све онако као нам је написано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'И тако отиде Хелкија свештеник и Ахикам и Ахвор и Сафан и Асаја к пророчици Олди жени Салума сина Текуја сина Араса ризничара; а она стајаше у Јерусалиму у другом крају, и говораше с њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'А она им рече: овако вели Господ Бог Израиљев: кажите човјеку који вас је послао к мени:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Овако вели Господ: ево пустићу зло на то мјесто и на становнике његове, све што говори књига коју је прочитао цар Јудин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Зато што ме оставише, и кадише другим боговима да би ме гњевили свијем дјелима руку својих; зато се гњев мој распалио на то мјесто, и неће се угасити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'А цару Јудину, који вас је послао да упитате Господа, овако му кажите: овако вели Господ Бог Израиљев за ријечи које си чуо:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Што је умекнуло срце твоје, и понизио си се пред Господом кад си чуо шта сам говорио за то мјесто и за становнике његове да ће бити пустош и проклетиња, и што си раздро хаљине своје и плакао преда мном, зато и ја услиших тебе, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Зато, ево, ја ћу те прибрати к оцима твојим, и на миру ћеш бити прибран у гроб свој, и нећеш очима својим видјети зла које ћу пустити на то мјесто. И казаше то цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Тада посла цар, те се скупише к њему све старјешине Јудине и Јерусалимске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'И отиде цар у дом Господњи и с њим сви људи из земљи Јудине и сви Јерусалимљани и свештеници и пророци и сав народ, мало и велико, и прочита им све ријечи књиге завјетне, која се нађе у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'И цар стојећи код ступа учини завјет пред Господом да ће они ићи за Господом и држати заповијести његове и свједочанства његова и уредбе његове свијем срцем и свом душом, вршећи ријечи тога завјета написане у тој књизи. И сав народ приста на завјет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Тада заповједи цар Хелкији поглавару свештеничком и свештеницима другога реда и онима који чуваху врата, да изнесу из цркве Господње све ствари које бијаху начињене Валу и гају и свој војсци небеској; и спали их иза Јерусалима у пољу Кедронском, и однесе пепео од њих у Ветиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'И сврже свештенике идолске које бијаху поставили цареви Јудини да каде по висинама у градовима Јудинијем и око Јерусалима тако и оне који кађаху Валу, сунцу и мјесецу и звијездама и свој војсци небеској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'И изнесе гај из дома Господњега иза Јерусалима на поток Кедрон, и спали га на потоку Кедрону и сатр у прах, и просу прах на гробове синова народнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'И поквари куће курварске које бијаху у дому Господњем, у којима жене ткаху застираче за гај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'И доведавши све свештенике из градова Јудинијех оскврни висине гдје кађаху свештеници од Геве до Вирсавеје, и поквари висине на вратима, и која бијаше на уласку на вратима Исуса заповједника градскога налијево од врата градских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Али свештеници онијех висина не приступаху к олтару Господњему у Јерусалиму, него јеђаху пријесне хљебове међу браћом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Оскврни и Тофет, који бијаше у долини синова Еномовијех, да не би нико више водио сина својега ни кћери своје кроз огањ Молоху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'И уклони коње које бијаху поставили цареви Јудини сунцу од уласка у дом Господњи до куће Натан-Мелеха дворанина, која бијаше у Фаруриму; а кола сунчана сажеже огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'И олтаре на крову собе Ахазове, које бијаху начинили цареви Јудини, и олтаре које бијаше начинио Манасија у оба тријема дома Господњега, поквари цар, и узевши их оданде баци прах од њих у поток Кедрон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'И висине према Јерусалиму с десне стране на гори Маслинској, које бијаше начинио Соломун цар Израиљев Астароти гаду Сидонском и Хемосу гаду Моавском и Мелхому гаду синова Амоновијех, оскврни цар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'И изломи ликове и исијече гајеве, и мјеста њихова напуни костију људских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'И олтар, који бјеше у Ветиљу, висину, коју бјеше начинио Јеровоам син Наватов, који наведе на гријех Израиља, и олтар и висину поквари, и спаливши висину сатр је у прах, и спали гај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'И обазревши се Јосија видје гробове који бијаху ондје на гори, и посла те извадише кости из гробова, и сажеже их на олтару и оскврни га, по ријечи Господњој, коју рече човјек Божји, који напријед каза те ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'И рече: какав је оно споменик што видим? Рекоше му грађани: оно је гроб човјека Божијега који дође из Јуде и напријед каза то што си учинио на олтару у Ветиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'А он рече: оставите га, нико да му не креће кости. Тако се сачуваше кости његове с костима онога пророка који дође из Самарије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'И све домове висина по градовима Самаријским које начинише цареви Израиљеви гњевећи Господа, поквари Јосија; и учини с њима све онако како учини у Ветиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'И покла све свештенике висина, који бијаху онуда, на олтарима, и сажеже кости људске на њима; потом се врати у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Тада заповједи цар свему народу говорећи: празнујте пасху Господу Богу својему, као што пише у књизи завјетној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Јер не би празнована овако пасха од времена судија које судише Израиљу и за све вријеме царева Израиљевијех и царева Јудинијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Као што би осамнаесте године цара Јосије празнована пасха Господу у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'И оне што се договарају с духовима и врачаре, и ликове и гадне богове и све гадове који се виђаху у земљи Јудиној и у Јерусалиму истријеби Јосија да изврши ријечи закона написане у књизи коју нађе Хелкија свештеник у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Ни прије њега не бјеше таквога цара, који би се обратио ка Господу свијем срцем својим и свом душом својом и свом снагом својом, сасвијем по закону Мојсијеву, нити послије њега наста таки као он.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Али се Господ не поврати од жестине великога гњева својега, којом се бјеше распалио гњев његов на Јуду за све дражење којим га бјеше дражио Манасија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'И рече Господ: и Јуду ћу одбацити од себе као што сам одбацио Израиља, и град ћу овај одбацити, који сам изабрао, Јерусалим, и дом, за који рекох: ту ће бити име моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'А остала дјела Јосијина и све што је чинио, није ли записано у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'У његово вријеме изиде Фараон Нехаон цар Мисирски на цара Асирскога к ријеци Ефрату, и цар Јосија изиде преда њ, а он како га видје уби га у Мегидону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'И мртва метнуше га слуге његове на кола, и одвезоше га из Мегидона у Јерусалим, и погребоше га у гробу његову; и народ земаљски узе Јоахаза сина Јосијина, и помазаше га и зацарише га на мјесто оца његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Двадесет и три године бјеше Јоахазу кад поче царовати, и царова три мјесеца у Јерусалиму. Матери му бјеше име Амутала, кћи Јеремијина, из Ливне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Он чињаше што је зло пред Господом сасвијем како су чинили оци његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'И свеза га Фараон Нехаон у Ривли у земљи Ематској да више не царује у Јерусалиму, и оглоби земљу сто таланата сребра и таланат злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'А царем постави Фараон Нехаон Елијакима сина Јосијина на мјесто Јосије оца његова, и предје му име Јоаким; а Јоахаза узе и отиде у Мисир, а он умрије ондје');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'А оно сребро и злато даде Јоаким Фараону разрезавши на земљу да би дао новце по заповијести Фараоновој, од свакога узимајући како бјеше цијењен, сребро и злато по народу у земљи, да да Фараону Нехаону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Двадесет и пет година бијаше Јоакиму кад поче царовати, и царова једанаест година у Јерусалиму. Матери му бјеше име Зевуда, кћи Федајева, из Руме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'А он чињаше што је зло пред Господом сасвијем како су чинили оци његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'За његова времена дође Навуходоносор цар Вавилонски; и Јоаким му би слуга три године; потом одуста и одметну се од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'И Господ посла на њ чете Халдејске и чете Сирске и чете Моавске и чете синова Амоновијех; посла их на Јуду да га потру, по ријечи Господњој коју говори преко слуга својих пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'По заповијести Господњој зби се то Јуди да би га одбацио од себе за гријехе Манасијине по свему што бјеше учинио;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'И за крв праву коју бјеше пролио напунивши Јерусалим крви праве; зато Господ не хтје опростити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'А остала дјела Јоакимова и све што је учинио, није ли записано у дневнику царева Јудинијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'И почину Јоаким код отаца својих; а на његово се мјесто зацари Јоахин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'А цар Мисирски не изиде више из земље своје, јер цар Вавилонски узе од ријеке Мисирске до ријеке Ефрата све што бјеше цара Мисирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Осамнаест година бијаше Јоахину кад се зацари, и царова три мјесеца у Јерусалиму. Матери му бјеше име Неуста, кћи Елнатанова, из Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'И он чињаше зло пред Господом сасвијем како је чинио отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'У то вријеме дођоше слуге Навуходоносора цара Вавилонскога на Јерусалим, и град би опкољен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Дође и Навуходоносор цар Вавилонски на град кад га слуге његове опколише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Тада Јоахин цар Јудин изиде к цару Вавилонском с матером својом и са слугама својим и с кнезовима својим и с дворанима својим; а цар га Вавилонски зароби осме године својега царовања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'И однесе све благо дома Господњега и благо дома царскога, и полупа све судове златне, које бјеше начинио Соломун цар Израиљев за цркву Господњу, као што бјеше рекао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'И пресели сав Јерусалим, све кнезове и све јунаке, десет тисућа робова, и све дрводјеље и све коваче, не оста ништа осим сиромашнога народа по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Одведе и Јоахина у Вавилон и матер цареву и жене цареве и дворане његове, и главаре земаљске одведе у ропство из Јерусалима у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'И све јунаке на број седам тисућа, и дрводјеље и коваче, тисућу, све што бијаху за војску одведе цар Вавилонски у Вавилон у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'И постави царем цар Вавилонски на мјесто Јоахиново Матанију стрица његова, и предје му име Седекија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Двадесет и једна година бјеше Седекији кад поче царовати, и царова једанаест година у Јерусалиму. Матери му бјеше име Амутала, кћи Јеремијина, из Ливне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Он чињаше што је зло пред Господом сасвијем како је чинио Јоаким.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Јер од гњева Господњега зби се то Јерусалиму и Јуди, да их одбаци од себе. А Седекија се одметну од цара Вавилонскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'И тако девете године његова царовања, десетога мјесеца десетога дана дође Навуходоносор цар Вавилонски са свом војском својом на Јерусалим, и стадоше у око под њим, и начинише опкопе око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'И град би опкољен до једанаесте године царовања Седекијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'И деветога дана мјесеца четвртога поста велика глад у граду, те народ земаљски немаше хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Тада град би проваљен, а војници сви побјегоше ноћу на врата између два зида уз врт царев; а Халдеји бијаху свуда око града; и цар отиде путем к пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Али војска Халдејска потјера цара, и стигоше га у пољу Јерихонском, а сва војска што бијаше с њим разбјеже се од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'И ухватише цара, и одведоше га к цару Вавилонском у Ривлу, и ондје му судише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'И синове Седекијине поклаше на његове очи, па онда Седекији ископаше очи, и свезаше га у два ланца мједена, и одведоше га у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'А седмога дана петога мјесеца године деветнаесте царовања Навуходоносора цара Вавилонскога дође у Јерусалим Невузардан заповједник стражарски, слуга цара Вавилонскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'И попали дом Господњи и дом царски и све домове у Јерусалиму; све велике куће попали огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'И зидове Јерусалимске унаоколо развали сва војска Халдејска, која бијаше са заповједником стражарским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'А остатак народа што оста у граду, и пребјеге што пребјегоше к цару Вавилонском, и остали прости народ одведе Навузардан заповједник стражарски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Само од сиромаха у земљи остави заповједник стражарски који ће бити виноградари и ратари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'И ступове мједене што бијаху у дому Господњем, и подножја, и море мједено које бијаше у дому Господњем, изломише Халдејци, и мјед од њих однесоше у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'И лонце и лопате и виљушке и кадионице и све судове мједене којима служаху, узеше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'И клијешта и котлиће, што год бјеше златно и што год бјеше сребрно, узе заповједник стражарски,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Два ступа, једно море и подножја, што начини Соломун за дом Господњи; не бјеше мјере мједи од свијех тијех судова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Осамнаест лаката бијаше висок један ступ, и озго на њему бијаше оглавље мједено, и оглавље бијаше високо три лакта, и плетенице и шипци око оглавља, све од мједи; таки бијаше и други ступ с плетеницом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Узе заповједник стражарски и Серају првога свештеника и Софонију другога свештеника, и три вратара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'А из града узе једнога дворанина, који бијаше над војницима и пет људи који стајаху пред царем, који се нађоше у граду, и првога писара војничкога, који пописиваше народ по земљи у војску, и шездесет људи из народа земаљскога, који се нађоше у граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Узе их Невузардан заповједник стражарски, и одведе к цару Вавилонском у Ривлу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'А цар их Вавилонски поби и погуби у Ривли у земљи Ематској. Тако би пресељен Јуда из земље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'А над народом који оста у земљи Јудиној, који остави Навуходоносор цар Вавилонски, над њим постави Годолију сина Ахикама сина Сафанова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'А кад чуше све војводе и људи њихови да је цар Вавилонски поставио Годолију, дођоше ка Годолији у Миспу, на име: Исмаило син Нетанијин, и Јоанан син Каријајев и Сераја син Тануметов из Нетофата, и Јазанија син Махатов, они и људи њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'И Годолија се закле њима и људима њиховијем и рече: не бојте се службе Халдејима; сједите у земљи и служите цару Вавилонском, и биће вам добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Али седмога мјесеца дође Исмаило син Нетаније сина Елисамова, рода царскога, и десет људи с њим, и убише Годолију, те погибе; тако и Јудеје и Халдеје који бијаху с њим у Миспи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Тада се подиже сав народ, мало и велико, и војводе, те отидоше у Мисир, јер се побојаше Халдеја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'А тридесет седме године откако се зароби Јоахин цар Јудин, дванаестога мјесеца, двадесет седмога дана Евил-Меродах цар Вавилонски исте године зацарив се извади из тамнице Јоахина цара Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'И лијепо говори с њим, и намјести му пријесто више пријестола других царева који бијаху код њега у Вавилону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'И промијени му хаљине тамничке, и он јеђаше свагда с њим свега вијека својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'И храна му се једнако даваше од цара сваки дан свега вијека његова до смрти његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Адам, Сит, Енос,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Кајинан, Малелеило, Јаред,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Енох, Матусал, Ламех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Ноје, Сим, Хам и Јафет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Синови Јафетови: Гомер и Магог и Мадај и Јаван и Товел и Месех и Тирас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'А синови Гомерови: Асхенас и Рафат и Тогарма.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'А синови Јаванови: Елиса и Тарсис, Китим и Доданим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'А синови Хамови: Хус и Мисраим, Фут и Ханан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'А синови Хусови: Сава и Авила и Савата и Регма и Саватака. А синови Регмини: Сава и Дедан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'И Хус роди Неврода. Он први би силан на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'А Мисраим роди Лудеје и Анамеје и Леавеје и Нафтухеје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'И Патрусеје и Хаслухеје, од којих изидоше Филистеји и Кафтореји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'А Ханан роди Сидона првенца својега, и Хета,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'И Јевусеје и Амореје и Гергесеје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'И Јевеје и Арукеје и Асенеје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'И Арвадеје и Самареје и Аматеје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Синови Симови: Елам и Асур и Арфаксад и Луд и Арам и Уз и Ул и Гетер и Месех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'А Арфаксад роди Салу, а Сала роди Евера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'А Еверу се родише два сина; једноме беше име Фалек, јер се у његово време раздијели земља; а име брату његову Јектан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'А Јектан роди Алмодада и Салефа и Асармота и Јараха,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'И Адорама и Узала и Диклу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'И Евала и Авимаила и Саву,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'И Офира и Евилу и Јовава: ти сви бјеху синови Јектанови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Сим, Арфаксад, Сала,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Евер, Фалет, Рагав,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Серух, Нахор, Тара,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Аврам, то је Авраам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Синови Аврамови: Исак и Исмаило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Ово је племе њихово: првенац Исмаилов Навајот, па Кидар и Авдеило и Мивсам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Мисма и Дума, Маса, Адад и Тема,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Јетур, Нафис и Кедма; то су синови Исмаилови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'А синови Хетуре иноче Аврамове: она роди Земрана и Јоксана и Мадана и Мадијана и Јесвока и Суја. А синови Јоксанови: Сава и Дедан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'А синови Мадијанови: Гефа и Ефер и Енох и Авида и Елдага. Ти сви бјеху синови Хетурини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Тако Аврам роди Исака; а синови Исакови бјеху Исав и Израиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Синови Исавови: Елифас, Рагуило и Јеус и Јеглом и Кореј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Синови Елифасови: Теман и Омар, Софар и Готом, Кенез и Тамна и Амалик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Синови Рагуилови: Нахат, Зара и Сома и Моза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'А синови Сирови: Лотан и Совал и Севегон и Ана и Дисон и Есер и Дисан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'А синови Лотанови: Хорије и Еман; а сестра Лотанова Тамна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Синови Совалови: Елан и Манахат и Евал, Сефија и Онам. А синови Севегонови: Аја и Ана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Синови Анини: Дисон, и синови Дисонови Амрам и Асван и Итран и Харан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Синови Есерови: Валан и Заван и Јакан. Синови Дисанови: Уз и Аран.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'А ово су цареви који цароваше у земљи Едомској прије него се зацари цар над синовима Израиљевијем: Валак син Веоров, а граду му бјеше име Денава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'А кад умрије Валак, зацари се на његово мјесто Јовав син Зарин од Восоре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'А кад умрије Јовав, зацари се на његово мјесто Асом од земље Темановске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'А кад умрије Асом, зацари се на његово мјесто Адад син Варадов, који исијече Мадијанце у пољу Моавском; а граду му бјеше име Гетем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'А кад умрије Адад, зацари се на његово мјесто Самада из Масекаса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'А кад умрије Самада, зацари се на његово мјесто Саул из Ровота на ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'А кад умрије Саул, зацари се на његово мјесто Валенон син Аховоров.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'А кад умрије Валенон, зацари се на његово мјесто Адад; а град му се зваше Фогор, а жени му бјеше име Метевеила кћи Матраиде кћери Мезовове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'А кад умрије Адад, насташе кнезови у Едомској: кнез Тамна, кнез Алва, кнез Јетет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Кнез Оливема, кнез Ила, кнез Финон,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Кнез Кенез, кнез Теман, кнез Мивсар,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Кнез Магедило, кнез Ирам. То бјеху кнезови Едомски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Ово су синови Израиљеви: Рувим, Симеун, Левије и Јуда, Исахар и Завулон,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Дан, Јосиф и Венијамин, Нефталим, Гад и Асир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Синови Јудини: Ир и Авнан и Сила; та му три роди кћи Сувина Хананејка; али Ир првенац Јудин бјеше неваљао пред Господом, те га уби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'А Тамара снаха његова роди му Фареса и Зару. Свега пет бјеше синова Јудинијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Синови Фаресови: Есрон и Амул.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'А синови Зарини: Зимрије и Етан и Еман и Халкол и Дара; свега пет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'И синови Хармијини: Ахан, који смути Израиља огријешив се о ствари проклете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'А синови Етанови: Азарија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'А синови Есронови, што му се родише: Јерамеило и Арам и Халев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'А Арам роди Аминадава, а Аминадав роди Насона, кнеза синова Јудинијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'А Насон роди Салмона; а Салмон роди Воза;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'А Воз роди Овида; а Овид роди Јесеја;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'А Јесеј роди првенца својега Елијава, и Авинадава другога и Саму трећега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Натанаила четвртога, Радаја петога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Осема шестога, Давида седмога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'И сестре му Серују и Авигеју. А синови Серујини бјеху Ависај и Јоав и Асаило, тројица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'А Авигеја роди Амасу; а отац Амасин бјеше Јетер Исмаиљац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'А Халев син Есронов роди с Азувом женом својом и с Јериотом синове, и синови му бјеху Јесер и Совав и Ардон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'А кад умрије Азува, Халев се ожени Ефратом, која му роди Ора;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'А Ор роди Урију, а Урија роди Веселеила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Потом отиде Есрон ка кћери Мехира оца Галадова, и ожени се њом кад му бијаше шездесет година, и она му роди Сегува.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'А Сегув роди Јаира, који имаше двадесет и три града у земљи Галадској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Јер узе Гесурејима и Сирцима села Јаирова и Кенат са селима његовијем, шездесет градова. То све узеше синови Махира оца Галадова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'И кад умрије Есрон у Халев-Ефрати, жена Есронова Авија роди му Асхора оца Текојанима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'А синови Јерамеила првенца Есронова бјеху: првенац Арам, па Вуна и Орем и Осем и Ахија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Имаше и другу жену Јерамеило, по имену Атару, она је мати Онамова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'А синови Арама првенца Јерамеилова бјеху: Мас и Јамин и Екер.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'И синови Онамови бјеху: Самај и Јадај; а синови Самајеви: Надав и Ависур.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'И име жени Ависуровој бјеше Авихаила, која му роди Авана и Молида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'А синови Надавови: Селед и Апаим; али Селед умрије без дјеце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'А синови Апаилови: Јесеј; а синови Јесејеви: Сисан, и кћи Сисанова Алаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'А синови Јадаја брата Самајева: Јетер и Јонатан; али Јетер умрије без дјеце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'А синови Јонатанови: Фалет и Заза. Ти бијаху синови Јерамеилови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'А Сисан не имаше синова него кћери; и имаше Сисан слугу Мисирца по имену Јарају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Зато Сисан даде кћер своју Јараји слузи својему за жену; а она му роди Атаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'А Атај роди Натана; а Натан роди Завада;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'А Завад роди Ефлала; а Ефлал роди Овида;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'А Овид роди Јуја; а Јуј роди Азарију;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'А Азарија роди Хелиса; а Хелис роди Елеасу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'А Елеаса роди Сисамаја; а Сисамај роди Салума;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'А Салум роди Јекамију; а Јекамија роди Елисама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'А синови Халева брата Јерамеилова бјеху: Миса првенац његов, отац Зифејима; па синови Марисе оца Хевронова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'А синови Хевронови: Кореј и Тафуја и Рекем и Сема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'А Сема роди Рама оца Јоркоамова; а Рекем роди Самаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'А син Самајев бјеше Маон, а тај Маон би отац Вет-Суру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'И Гефа иноча Халевова роди Харана и Мосу и Газеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'А синови Јадајеви: Регем и Јотам и Гисан и Фелет и Гефа и Сагаф.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Маха иноча Халевова роди Севера и Тирхану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Роди и Сагафа оца Мадманцима и Севу оца Махвинцима и Гавајанима; а кћи Халевова бијаше Ахса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Ово бијаху синови Халева сина Ора првенца Ефратина; Совал отац Киријат-Јариму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Салма отац Витлејему, Ареф отац Вет-Гадеру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'А имаше синове Совал отац Киријат-Јариму: Ароја и Аси-Аменухота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'А породице Киријат-Јаримске бјеху: Јетрани и Фућани и Сумаћани и Мисрајани. Од њих изидоше Сараћани и Естаољани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Синови Салмини: Витлејемци и Нетофаћани, Атароћани од дома Јоавова, и Зорани, половина Манахаћана,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'И породице писарске у Јавису, Тираћани, Симеаћани, Сухаћани; то су Кенеји, који се народише од Емата, оца дома Рихавова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'А ово су синови Давидови који му се родише у Хеврону: првенац Амнон од Ахиноаме Језраељанке, други Данило од Авигеје Кармилке,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Трећи Авесалом, син Махе кћери Талмаја цара Гесурскога, четврти Адонија, син Агитин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Пети Сефатија од Авитале, шести Итрам од Егле жене његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Шест му се роди у Хеврону, гдје царова седам година и шест мјесеца, а тридесет и три царова у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'А ови му се родише у Јерусалиму: Самаја и Совав и Натан и Соломун, четири, од Витсавеје кћери Амилове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'И Јевар и Елисама и Елифалет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'И Нога и Нефег и Јафија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'И Елисама и Елијада и Елифелет, девет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Све синови Давидови осим синова иноча његовијех и осим Тамаре сестре његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'А син Соломунов бијаше Ровоам, а његов син Авија, а његов син Аса, а његов син Јосафат,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'А његов син Јорам, а његов син Охозија, а његов син Јоас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'А његов син Амасија, а његов син Азарија, а његов син Јотам,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'А његов син Ахаз, а његов син Језекија, а његов син Манасија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'А његов син Амон, а његов син Јосија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'А синови Јосијини: првенац Јоанан, други Јоаким, трећи Седекија, четврти Салум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'А синови Јоакимови: Јехонија син му, и његов син Седекија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'А синови Јехоније сужња: Салатило син му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'А његови синови Малхирам и Федаја и Сенасар, Јекамија, Осама и Недавија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'А синови Федајини: Зоровавељ и Симеј; а синови Зоровавељеви: Месулам и Ананија и сестра им Селомета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'А синови Месуламови: Асува и Оило и Варахија и Асадија и Јусавесед, пет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'А синови Ананијини: Фелатија и Јесаја, синови Рефајини, синови Арнанови, синови Овадијини, синови Сеханијини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'А синови Сеханијини: Семаја, и синови Семајини: Хатус и Игеал и Варија и Неарија и Сафат, шест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'А синови Неаријини: Елиоинај и Језекија и Азрикам, три.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'А синови Елиоинајеви: Одаја и Елиасив и Фелаја и Акув и Јоанан и Далаја и Анан, седам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Синови Јудини бјеху: Фарес, Есрон и Хармија и Ор и Совал.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'А Реаја син Совалов роди Јата, а Јат роди Ахумаја и Лада. То су породице Саратске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'А ово су од оца Итама: Језраел и Јесма и Једвас, а сестри њиховој бјеше име Аселелфонија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'И Фануило бјеше отац Гедору, и Есер отац Хусин. То бијаху синови Ора првенца Ефрате оца Витлејемцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'А Асхор отац Текујанима имаше двије жене, Елу и Нару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'И Нара му роди Ахузама и Ефера и Темана и Ахастара. То су синови Нарини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'А синови Елини: Серед, Јесоар и Етнан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'А Кос роди Анува и Совиву и породице Ахарила сина Арумова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'А Јавис бјеше славнији од своје браће, и мати му надје име Јавис говорећи: родих га с болом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'И Јавис призва Бога Израиљева говорећи: о да би ме благословио и раширио међе моје, и рука твоја да би била са мном, и да би ме сачувао ода зла да ме не уцвијели! И учини Бог за што га моли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'А Хелув брат Сујин роди Мехира. Он би отац Естонов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'А Естон роди Вет-Рафу и Фесеју и Техину оца граду Насу. То су људи Рихавови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'А синови Кенезови бјеху Готонило и Сераја. А синови Готонилови: Атат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'А Меонотај роди Офру; а Сераја роди Јоава, оца онијех што живе у долини дрводјељској, јер бијаху дрводјеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'А синови Халева сина Јефонијина бијаху Ир, Ила и Нам. А син Илин бјеше Кенез.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'А синови Јелелеилови: Зиф и Зифа, Тирија и Асареило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'А синови Езрини: Јетер и Меред и Ефер и Јалон; а жена Мередова роди Маријама и Самаја и Јесву, оца Естемоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'А жена његова Јудија роди Јереда оца Гедору, и Евера оца Сохоту, и Јекутила оца Заноји. А то бијаху синови Витије кћери Фараонове, којом се ожени Меред.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'А синови жене Одијине сестре Нама оца Кеили бијаху Гармија и Естемоја Махаћанин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'А синови Симонови: Амион и Рина и Вен-Анан и Тилон. А синови Јесејеви: Зохет и Вен-Зохет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'А синови Силе сина Јудина: Ир отац Лиху, и Лада отац Мариси, и породице дома платнарскога, дома Асвејина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'И Јоким и Хасивљани, и Јоас и Сараф, који владаху у Моавској, и Јасуви-Лехем. Али то су старе ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'То бијаху лончари и живљаху у садовима и забранима, и бијаху ондје код цара за његове послове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Синови Симеунови: Немуило и Јамин, Јарив, Зера, Саул;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'А његов син Салум, а његов син Мивсам, а његов син Мисма.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'А синови Мисмини: Амуило син му, и његов син Захур, и његов син Симеј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'А Симеј имаше шеснаест синова и шест кћери; а браћа његова немаху много синова, и све породице њихове не бјеше тако много као синова Јудинијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'А живљаху у Вирсавеји и Молади и Асар-Суалу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'И у Вали и у Асему и у Толаду,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'И у Ветуилу и у Орми и у Сиклагу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'И у Вет-Мархавоту И у Асар-Сусиму и у Вет-Виреју и у Сараиму. То бјеху градови њихови до цара Давида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'А села њихова бијаху Итам и Ајин, Римон и Тохен и Асан, пет градова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'И сва села њихова што бијаху око тијех градова до Вала. То бијаху станови њихови по роду њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'А Месовав и Јамлих и Јоса син Амасијин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'И Јоило и Јуј син Јосивије сина Сераје сина Асилова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'И Елиоинај и Јакова и Јесохаја и Асаја и Адило и Јесимило и Венаја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'И Зиса син Сифија сина Алона сина Једаје сина Симрија синова Семајина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Ти именовани бијаху кнезови у породицама својим, и домови отаца њиховијех умножише се веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'И зато отидоше у Гедор до источне стране долине да траже пашу стоци својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'И нађоше пашу обилату и добру и земљу пространу и мирну и родну, јер прије ондје живљаху који бијаху од Хама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Ти дакле записани по имену дошавши за Језекије цара Јудина разбише шаторе њихове и становнике који се нађоше ондје, и побише их као проклете да не оста ниједан до данас, и населише се мјесто њих, јер ондје бијаше паше за стоку њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'А између њих, синова Симеуновијех, изиде на гору Сир пет стотина људи, а поглавице им бијаху Фелатија и Неарија и Рефаја и Озило, синови Јесејеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'И побише остатак што бијаху утекли између Амалика, и населише се ондје до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'А синови Рувима првенца Израиљева, јер он бијаше првенац, али кад оскрвни постељу оца својега, дано би његово првенаштво синовима Јосифа сина Израиљева, али не тако да се броји првенац,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Јер Јуда би најсилнији међу браћом својом и од њега је вођ, али првенаштво доби Јосиф;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Синови Рувима првенца Израиљева бијаху: Анох и Фалуј, Есрон и Хармија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Синови Јоилови: Семаја син му, а његов син Гог, а његов син Симеј,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'А његов син Миха, а његов син Реаја, а његов син Вал,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'А његов син Веира, којега одведе Телгат-Фелнасар цар Асирски; он бијаше кнез племена Рувимова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'А браћи његовој по породицама њиховијем кад се избројише по кољенима својим, бјеше кнез Јеило и Захарија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'А Вела син Азаза сина Семе сина Јоилова; он живљаше у Ароиру и до Невона и Валмеона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Потом живљаше к истоку дори до пустиње од ријеке Ефрата, јер им се стока умножи у земљи Галадској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'И за времена Саулова војеваше на Агарене, који изгибоше од руке њихове; и тако се населише у шаторима њиховијем по свему источном крају земље Галадске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'А синови Гадови живљаху према њима у земљи Васанској до Салхе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Јоило им бијаше поглавар, а Сафан други, па Јанај и Сафат у Васану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'А браћа њихова по домовима отачким бијаху: Михаило и Месулам и Сева и Јорај и Јахан и Зије и Евер, седморица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Ти бијаху синови Авихаила сина Урија сина Јароје сина Галада сина Михаила сина Јесисаја сина Јадона сина Вузова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ахије син Авдила сина Гунијева бијаше поглавар у дому отаца њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'И живљаху у Галаду, у Васану и селима његовијем и у свијем подграђима Саронским до међа његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Сви ови бише избројени за времена Јотама цара Јудина и за време Јеровоама цара Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Синова Рувимовијех и Гадовијех и половине племена Манасијина, храбријех људи, што ношаху штит и мач, и затезаху лук, и вјештијех боју, бијаше четрдесет и четири тисуће и седам стотина и шездесет, који иђаху на војску;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'И војеваше на Агарене, на Јетуреје и Нафисеје и Нодавеје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'И дође им помоћ супрот њих, и Агарени им бише дани у руке и све што имаху; јер завапише Богу у боју, и услиши их, јер се поуздаше у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'И заплијенише стоку њихову, педесет тисућа камила и двјеста и педесет тисућа оваца и двије тисуће магараца и сто тисућа душа људских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'А рањенијех много паде; јер тај бој би од Бога; и наставаше на мјесту њихову до сеобе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'А синови половине племена Манасијина живљаху у тој земљи од Васана до Вал-Ермона и Сенира, до горе Ермона; бијаху се умножили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'А ово бијаху поглавари у дому отаца њиховијех: Ефер и Јесеј и Елило и Азрило и Јеремија и Одавија и Јадило, људи храбри и на гласу, поглавари у дому отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Али кад згријешише Богу отаца својих и чинише прељубу за Боговима народа оне земље, које Бог истријеби испред њих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Подиже Бог Израиљев дух Фула цара Асирскога и дух Телгат-Фелнасара цара Асирскога, и преселише племе Рувимово и племе Гадово и половину племена Манасијина, и одведоше их у Алу и у Авор и у Ару, и на ријеку Гозан, гдје осташе до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Синови Левијеви бијаху: Гирсон, Кат и Мерарије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'А синови Катови: Амрам, Исар и Хеврон и Озило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'А синови Амрамови: Арон и Мојсије, и кћи Марија. А синови Аронови: Надав и Авијуд и Елеазар и Итамар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Елеазар роди Финеса; а Финес роди Ависују;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'А Ависуја роди Вукија; а Вукије роди Озију;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'А Озија роди Зерају; а Зераја роди Мерајота;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'А Мерајот роди Амарију; а Амарија роди Ахитова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'А Ахитов роди Садока; а Садок роди Ахимаса;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'А Ахимас роди Азарију; а Азарија роди Јоанана;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'А Јоанан роди Азарију, који би свештеник у дому што сазида Соломун у Јерусалиму;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'А Азарија роди Амарију; а Амарија роди Ахитова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'А Ахитов роди Садока; а Садок роди Салума;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'А Салум роди Хелкију; а Хелкија роди Азарију;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'А Азарија роди Серају; а Сераја роди Јоседека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'А Јоседек отиде кад Господ пресели Јудеје и Јерусалим руком Навуходоносоровом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Синови Левијеви бијаху: Гирсон, Кат и Мерарије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'А ово су имена синовима Гирсоновијем: Ловеније и Симеј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'А синови Катови бјеху: Амрам и Исар и Хеврон и Озило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Синови Мераријеви: Молија и Мусија. И ово су породице Левитске по оцима својим:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Гирсонова: Левеније син му, а његов син Јат, а његов син Зима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'А његов син Јоах, а његов син Идо, а његов син Зера, а његов син Јетрај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Синови Катови: Аминадав син му, а његов син Кореј, а његов син Асир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'А његов син Елкана, а његов син Евијасаф, а његов син Асир,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'А његов син Тахат, а његов син Урило, а његов син Озија, а његов син Саул.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'А синови Елканини: Амасај и Ахимот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Елкана; синови Елканини: Суфија син му, а његов син Махат;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'А његов син Елијав, а његов син Јероам, а његов син Елкана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'А синови Самуилови: Васнија првенац, па Авија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Синови Мераријеви: Молија, а његов син Ловеније, а његов син Симеј, а његов син Уза,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'А његов син Симаја, а његов син Агија, а његов син Асаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'А ово су које постави Давид да пјевају у дому Господњем, кад се намјести ковчег,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'Који служаху пред шатором од састанка пјевајући, док не сазида Соломун дом Господњи у Јерусалиму, и стајаху по реду свом у служби својој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Ови су што стајаху и синови њихови: од синова Катовијех Еман пјевач, син Јоила сина Самуила,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Сина Елкане, сина Јероама, сина Елила, сина Тоје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Сина Суфа, сина Елкане, сина Мата, сина Амасаја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Сина Елкане, сина Јоила, сина Азарије, сина Софоније,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Сина Тахате, сина Асира, сина Авиасафа, сина Кореја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Сина Исара, сина Ката, сина Левија, сина Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'И брат му Асаф, који му стајаше с десне стране; а Асаф бијаше син Варахије, сина Симеје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Сина Михаила, сина Васије, сина Малхије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Сина Етнија, сина Зера, сина Адаје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Сина Етана, сина Зиме, сина Симеја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Сина Јата, сина Гирсона, сина Левијева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'А синови Мераријеви, браћа њихова, стајаху с лијеве стране: Етан син Кисије, сина Авдија, сина Малуха,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Сина Асавије, сина Амасије, сина Хелкије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Сина Амсије, сина Ваније, сина Самира,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Сина Молије, сина Мусије, сина Мерарије, сина Левијева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'А браћа њихова, остали Левити, бише одређени на сву службу и шатору дома Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'А Арон и синови његови паљаху на олтару за жртве паљенице и на олтару кадионом, вршећи све послове у светињи над светињама, и чинећи очишћење за Израиља по свему како је заповједио Мојсије слуга Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'А ово су синови Аронови: Елеазар син му, а његов син Финес, а његов син Ависуја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'А његов син Вукије, а његов син Озије, а његов син Зераја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'А његов син Мерајот, а његов син Амарија, а његов син Ахитов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'А његов син Садок, а његов син Ахимас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'А ово су им станови по градовима њиховијем у међама њиховијем: Синовима Ароновијем од породице Катове допаде ждријебом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'И дадоше им Хеврон у земљи Јудиној, и подграђа његова око њега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'А поље градско и села његова дадоше Халеву сину Јефонијину;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Дадоше дакле синовима Ароновијем градове Јудине: Хеврон уточиште, и Ливну и подграђа њезина и Јатир и Естемоју и подграђа њезина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'И Илон и подграђа његова, Девир и подграђа његова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'И Асан и подграђа његова, и Вет-Семес и подграђа његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'А од племена Венијаминова: Гавају и подграђа њезина, и Алемет и подграђа његова и Анатот и подграђа његова; свега градова њиховијех тринаест по породицама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'И осталијем синовима Катовијем од породице тога племена даше ждријебом од половине племена, од половине Манасијине десет градова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'А синовима Гирсоновијем по породицама њиховијем тринаест градова од племена Исахарова и од племена Асирова и од племена Нефталимова и од племена Манасијина у Васану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Синовима Мераријевим по породицама њиховијем даше ждријебом од племена Рувимова и од племена Гадова и од племена Завулонова дванаест градова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Тако даше синови Израиљеви Левитима те градове и подграђа њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'И даде ждријебом од племена синова Јудинијех и од племена сина Симеуновијех и од племена синова Венијаминовијех те градове, које именоваше поименце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'И онима који бијаху од рода синова Катовијех а градови њихови и међе њихове бијаху у племену Јефремову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Њима даше град за уточиште Сихем и подграђа његова у гори Јефремовој, и Гезер и подграђа његова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'И Јокнеам и подграђа његова, и Вет-Орон и подграђа његова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'И Ејалон и подграђа његова, и Гат-Римон и подграђа његова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'И од половине племена Манасијина Анир и подграђа његова, и Вилеам, и подграђа његова, породицама синова Катовијех осталијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'А синовима Гирсоновијем даше од породице половине племена Манасијина Голан у Васану и подграђа његова, и Асарот и подграђа његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'А од племена Исахарова Кедес и подграђа његова, Даврат и подграђа његова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'И Рамот и подграђа његова, и Аним и подграђа његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'А од племена Асирова Масал и подграђа његова, и Авдон и подграђа његова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'И Хукок и подграђа његова, и Реов и подграђа његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'А од племена Нефталимова Кедес у Галилеји и подграђа његова, и Амон и подграђа његова, и Киријатајим и подграђа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Синовима Мераријевим осталијем даше од племена Завулонова Римон и подграђа његова, Тавор и подграђа његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'А преко Јордана према Јерихону на источну страну Јордана, од племена Рувимова Восор у пустињи и подграђа његова, и Јасу и подграђа њезина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'И Кедимот и подграђа његова, и Мифат и подграђа његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'И од племена Гадова Рамот у Галилеји и подграђа његова, и Маханаим и подграђа његова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'И Есевон и подграђа његова, и Јазир и подграђа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'А синови Исахарови бијаху: Толам и Фуја и Јасуф и Симрон, четворица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'А синови Толини: Озије и Рефаја и Јерило и Јамај и Јефсам и Самуило, поглавари отачких домова својих од Толе, храбри људи у породицама својим; бјеше их за времена Давидова на број двадесет и двије тисуће и шест стотина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'А синови Озијеви: Израја, и синови Израјини: Михаило и Овадија и Јоило и Јесија, скупа пет поглавара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'И с њима у породицама њиховијем по домовима отаца њиховијех бјеше војника тридесет и шест тисућа, јер имаху много жена и синова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'И браће њихове по свијем домовима Исахаровијем, храбријех људи, бијаше осамдесет и седам тисућа, свега избројенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Синови Венијаминови: Вела и Вехер и Једиаило, тројица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'А синови Велини: Есвон и Озије и Озило и Јеримот и Ирије, пет поглавара домова отачких, храбри људи; на број их бјеше двадесет и двије тисуће и тридесет и четири.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'А синови Вехерови: Земира и Јоас и Елијезер и Елиоинај и Амрије и Јеримот и Авија и Анатот и Аламет, сви синови Вехерови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'И избројенијех по породицама својим, по поглаварима отачкога дома својега, бјеше их двадесет тисућа и двјеста храбријех људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'А синови Једиаилови: Валан, и синови Валанови: Јеус и Венијамин и Ехуд и Ханана и Зитан и Тарсис и Ахисар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Свијех овијех синова Једиаилових по поглаварима породица отачких, храбријех људи, бјеше седамдесет тисућа и двјеста, који иђаху на војску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'И Суфеји и Упеји бијаху синови Ирови, и Усеји синови Ахирови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Синови Нефталимови: Јасило и Гуније и Јесер и Салум, синови Валини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Синови Манасијини: Азрило, којега му жена роди; иноча његова Сирка роди Махира, оца Галадова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'А Махир се ожени од Упеја и Суфеја, а име сестри њиховој бјеше Маха; а име другому бјеше Салпад; а Салпад имаше кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'А Маха жена Махирова роди сина, којему надје име Фарес, а брату му надје име Серес, а његови синови бјеху Улам и Ракем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'И синови Уламови: Ведан. То су синови Галада сина Махира сина Манасијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'А сестра његова Амолекета роди Исуда и Авијезера и Малу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'А синови Семидини бејаху Ахијан и Сихем и Лихија и Анијам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'А синови Јефремови: Сутала, а његов син Веред, а његов син Тахат, а његов син Елеада, а његов син Тахат,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'А његов син Завад, а његов син Сутала и Есер и Елеад. А њих убише људи из Гата, рођени у земљи, јер сиђоше да им узму стоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Зато тужаше Јефрем отац њихов дуго време, и дођоше браћа његова да га тјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Потом леже са женом својом, а она затрудње и роди сина, и он му надје име Верија, јер несрећа задеси дом њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'И кћи му бјеше Сера, која сазида Вет-Орон доњи и горњи и Узен-Серу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'И син му бјеше Рефа и Ресеф, а његов син бјеше Тела, а његов син Тахан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'А његов син Ладан, а његов син Амијуд, а његов син Елисама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'А његов син Нон, а његов син Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'А достојање њихово и насеље бјеше Ветиљ и села његова, и с истока Наран, а са запада Гезер и села његова, и Сихем и села његова до Газе и села њезинијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'И покрај синова Манасијиних Вет-Сан и села његова, Танах и села његова, Мегидон и села његова, Дор и селова његова; ту наставаху синови Јосифа сина Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Синови Асирови бијаху Јемна и Јесва и Јесвај и Верија, и Сера сестра њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'И синови Веријини: Евер и Малхило; овај је отац Вирзавитов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'А Евер роди Јафлита и Сомира и Хотама и Сују сестру њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'А синови Јафлитови бијаху: Фасах и Витал и Асват; то бијаху синови Јафлитови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'А синови Сомирови: Ахије и Рога, Јехува и Арам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'А синови Елема брата његова: Софа и Јемна и Селис и Амал.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Синови Софини: Суја и Арнефер и Согал и Верије и Јемра,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'И Восор и Од и Сама и Силиса и Итран и Веира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'А синови Јетерови: Јефонија и Фиспа и Ара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'И синови Улини: Арах и Анило и Рисија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Сви ови бијаху синови Асирови, поглавари домова отачких, изабрани, храбри људи, поглавари међу кнезовима. Бјеше их за војску на број двадесет и шест тисућа људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'А Венијамин роди Велу првенца својега, Асвила другога, и Ару трећега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Ноја четвртога, и Рафу петога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'А синови Велини бијаху: Адар и Гира и Авијуд,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'И Ависуја и Наман и Ахоја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'И Гира и Сефуван и Урам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'А ови бијаху синови Ехудови, бијаху поглавари домова отачких онима који живљаху у Гаваји, те их преселише у Манахат:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'Наман и Ахија и Гира, он их пресели; и роди Узу и Ахијуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'А Сарајим, пошто их посла, роди синове у земљи Моавској с Усимом и Варом женама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Роди с Одесом женом својом Јовава и Сивију и Мису и Малхама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'И Јеуса и Сахију и Мирму; ти бијаху синови његови, поглавари домова отачких.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'А с Усимом роди Авитова и Елфала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'И синови Елфалови бјеху: Евер и Мисам и Самед; он сазида Онон и Лод и села његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'И Верија и Сема, који бијаху поглавари домова отачких онима који живљаху у Ејалону; он истјераше становнике Гатске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'А Ахио, Сасак и Јеремот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'И Зевадија и Арад и Адер,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'И Михаило и Јеспа и Јоха бјеху синови Веријини;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'А Завадија и Месулам и Езекије и Евер,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'И Исмерај и Језлија и Јовав бјеху синови Елфалови;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'А Јаким и Зихрије и Завдије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'И Елинај и Зилтај и Елило,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'И Адаја и Вераја и Симрат бјеху синови Семини;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'А Јесван и Евер и Елило,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'И Авдон и Зихрије и Анан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'И Ананија и Елам и Антонија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'И Јефедија и Фануило бјеху синови Сасакови;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'А Самсерај и Сеарија и Готолија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'И Јересија и Илија и Зихрије бјеху синови Јероамови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'То бјеху поглавари домова отачких по породицама својим, и наставаху у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'А у Гаваону наставаше отац Гаваону; а жени му бјеше име Маха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'А син првенац његов бјеше Авдон, па Сур и Кис и Вал и Надав,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'И Гедор и Ахијо и Захер,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'И Миклот, који роди Симеју. И они живљаху према браћи својој у Јерусалиму с браћом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'А Нир роди Киса; а Кис роди Саула; а Саул роди Јонатана и Малхисуја и Авинадава и Есвала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'А син Јонатанов бјеше Меривал; а Меривал роди Миху;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'А Мишини синови бјеху: Фитон и Мелех и Тареја и Ахаз.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'А Ахаз роди Јоаду; а Јоада роди Алемета и Азмавета и Зимрија. А Зимрије роди Мосу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'А Моса роди Винеју; а његов син бјеше Рафа, а његов син Елеаса, а његов син Асило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'А Асило имаше шест синова, којима су имена: Азрикам, Вохеруј и Исмаило и Сеарија, и Овадија и Анан. Ти сви бјеху синови Асилови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'А синови Исека брата његова: Улам првенац му, Јеус други, и Елифелет трећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'И бијаху синови Уламови јунаци, који натезаху лук, и имаху много синова и унука, сто и педесет. Сви ти бјеху од синова Венијаминовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'И тако сав Израиљ би избројен, и ето записани су у књизи о царевима Израиљевијем и Јудинијем; и бише пресељени у Вавилон за безакоње своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'А који прије наставаху на достојању својем по градовима својим, Израиљци, свештеници, Левити и Нетинеји,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Наставаху у Јерусалиму и од синова Јудинијех и синова Венијаминовијех и од синова Јефремовијех и Манасијиних:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Гутај син Амијуда сина Амрија, сина Имрија, сина Венија, од синова Фареса сина Јудина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'И од синова Силоновијех: Асаја првенац и синови његови;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'А од синова Зеринијех Јеуило и браће његове шест стотина и деведесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'А од синова Венијаминовијех Салуј син Месуама сина Одује, сина Асенујина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'И Јевнија син Јероамов, и Ила син Озија сина Махријева, и Месулам син Сефатије сина Рагуила, сина Ивнијина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'И браће њихове по породицама својим девет стотина педесет и шест; сви бјеху људи поглавари од породица по домовима отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'А од свештеника: Једаја и Јојарив и Јахин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'И Азарија син Хелкије сина Месулама, сина Садока сина Мерајота, сина Ахитовова, старјешина у дому Господњем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'И Адаја син Јероама сина Пасхора, сина Малхијина, и Масај син Адила сина Јазире, сина Месулама, сина Месилемота, сина Имирова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'И браће њихове, поглавара отачких домова својих, тисућа и седам стотина и шездесет људи вреднијих на послу у служби у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'А од Левита Семија син Асува, сина Азрикама, сина Асавијина, између синова Мераријевих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'И Ваквакар и Ерес и Галал и Матанија, син Михе сина Зихрија, сина Асафова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'И Овадија син Семеје сина Галала, сина Једутунова, и Варахија син Асе сина Елканина, који становаше у селима Нетофатским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'И вратари: Салум и Акув и Талмон и Ахиман, и браћа њихова; а Салум бјеше поглавар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Он до сада бијаше на вратима царским к истоку; то бијаху вратари по четама синова Левијевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'А Салум син Кореја сина Евијасафа, сина Корејева, и браћа његова од дома оца његова, синови Корејеви, у послу службеном чуваху прагове код шатора, као што оци њихови у околу Господњем чуваху улазак;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'А над њима бјеше старјешина Финес син Елеазаров, и Господ бјеше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Захарија син Меселемијин бијаше вратар шатора од састанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Свијех овијех изабранијех за вратаре на праговима бијаше двјеста и дванаест; бише пописани по селима својим; Давид и Самуило видјелац поставише их ради вјерности њихове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Да они и синови њихови чувају стражу на вратима дома Господњега, дома од шатора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'На четири стране бијаху вратари: на истоку, на западу, на југу и на сјеверу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'И браћа њихова по селима својим долажаху сваких седам дана за своје вријеме да су с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Јер у служби бијаху свагда четири прва вратара, Левита, и бијаху постављени над клијетима и над ризницама дома Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'И око дома Божијега ноћиваху, јер на њима бијаше стража и дужни бијаху отворати свако јутро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'И неки од њих бијаху над посуђем службенијем, јер га на број уношаху и на број изношаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'А неки од њих бијаху постављени над другим стварима и над свијем стварима посвећенијем, над брашном и вином и уљем и кадом и мирисима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'А неки синови свештенички готовљаху маст од тијех мириса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'А Мататија између Левита првенац Салумов од породице Корејеве, бијаше над стварима које се пеку у тави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'А између синова Катовијех, браће њихове, бијаху неки над хљебом постављенијем, готовећи га сваке суботе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Између њих бијаху и пјевачи поглавари домова отачких међу Левитима, који становаху по клијетима без другога посла, јер дан и ноћ бијаху у свом послу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'То су поглавари домова отачких међу Левитима, по породицама својим, поглавари, и живљаху у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'А у Гаваону становаше Јехило отац Гаваону; а име жени његовој бјеше Маха;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'А син му првенац бјеше Авдон, па Сур и Кис и Вал и Нир и Надав,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'И Гедор, и Ахајо и Захарија и Миклот;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'А Миклот роди Симеама; и они наставаху према браћи својој у Јерусалиму с браћом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'А Нир роди Киса; а Кис роди Саула; а Саул роди Јонатана и Малхисуја и Авинадава и Есвала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'И син Јонатанов бјеше Меривал; а Меривал роди Миху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'А синови Михини бјеху: Фитон и Мелех и Тареја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'А Ахаз роди Јару; а Јара роди Алемета и Азмавета и Зимрија; а Зимрије роди Мосу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'А Моса роди Винеју; а његов син бјеше Рефаја, а његов син Елеаса, а његов син Асило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Асило пак имаше шест синова, којима су имена: Азрикам, Вохеруј и Исмаило и Сеарија и Овадија и Анан. То су синови Асилови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'А Филистеји се побише с Израиљем, и побјегоше Израиљци испред Филистеја, и падаху мртви на гори Гелвуји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'И стигоше Филистеји Саула и синове његове, и погубише Филистеји Јонатана и Авинадава и Малхисуја, синове Саулове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'И бој поста жешћи око Саула, и нађоше га стријелци, и он се уплаши од стријелаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'И рече Саул момку који му ношаше оружје: извади мач свој, и прободи ме да не дођу ти необрезани и наругају ми се. Али не хтје момак који му ношаше оружје, јер га бјеше врло страх. Тада Саул узе мач и баци се на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'А кад момак који му ношаше оружје видје гдје умрије Саул, баци се и он на свој мач, и умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Тако погибе Саул; и три сина његова и сва чељад његова погибоше заједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'А кад сви Израиљци који бијаху у долини видјеше гдје побјегоше Израиљци и гдје погибе Саул и синови његови, оставише градове своје и побјегоше те дођоше Филистеји и осташе у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'А сјутрадан дођоше Филистеји да свлаче мртве, и нађоше Саула и синове његове гдје леже на гори Гелвуји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'И свукавши га узеше главу његову и оружје његово, и послаше у земљу Филистејску на све стране да се објави код лажнијех богова њиховијех и по народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'И оставише оружје његово у кући богова својих, а главу му објесише у кући Дагоновој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'А кад чуше сви у Јавису Галадском све што учинише Филистеји од Саула,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Подигоше се сви јунаци и узеше тијело Саулово и тјелеса синова његовијех, и донесоше их у Јавис, и погребоше кости њихове под храстом у Јавису, и постише седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'И тако погибе Саул за безакоње своје, које учини Господу што не слуша ријечи Господње и што тражи да пита дух врачарски,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'А не пита Господа; зато га уби, и пренесе царство на Давида сина Јесејева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'И сабраше се сви Израиљци к Давиду у Хеврон, и рекоше: ево, ми смо кост твоја и тијело твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'И пређе док Саул бијаше цар ти си одводио и доводио Израиља; и Господ Бог твој рекао ти је: ти ћеш пасти народ мој Израиља; и ти ћеш бити вођ народу мојему Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Тако дођоше све старјешине Израиљеве к цару у Хеврон, и учини с њима Давид вјеру у Хеврону пред Господом, и помазаше Давида за цара над Израиљем као што бјеше рекао Господ преко Самуила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Потом отиде Давид са свијем Израиљем на Јерусалим, а то је Јевус, јер ондје бијаху Јевусеји, који живљаху у оној земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'И рекоше Јевушани Давиду: нећеш ући овамо. Али Давид узе кулу Сион, то је град Давидов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Јер Давид рече: ко први надбије Јевусеје, биће кнез и војвода. И Јоав син Серујин изиде први, и поста кнез.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Послије сеђаше Давид у том граду, зато га прозваше град Давидов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'И сазида град унаоколо, од Милона унаоколо; а Јоав оправи остатак града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'И Давид једнако напредоваше и сиљаше се, јер Господ над војскама бјеше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'А ово су поглавице међу јунацима Давидовијем, који јуначки радише уза њ за царство његово са свијем Израиљем да буде цар над Израиљем по ријечи Господњој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'И ово је број јунака Давидовијех: Јасовеам син Ахмонијев, први између тридесет; он махну копљем својим на три стотине, и поби их уједанпут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'А за њим Елеазар син Додов Ахошанин, он бијаше један од три јунака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Он бијаше с Давидом у Фас-Дамиму, кад се Филистеји скупише на бој; и ондје бијаше њива пуна јечма, и народ побјеже од Филистеја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'А они стадоше усред њиве, и одбранише је побивши Филистеје; и Господ даде избављење велико.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'И та три прва између тридесет сидоше ка стијени к Давиду у пећину Одаламску, кад војска Филистејска стајаше у околу у долини Рафајској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'А Давид бијаше онда у граду, а стража Филистејска бијаше тада у Витлејему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'И Давид зажеље и рече: ко би ми донио воде да пијем из студенца Витлејемскога што је код врата?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Тада та тројица продријеше кроз око Филистејски, и захватише воде из студенца Витлејемскога који је код врата, и донесоше и дадоше Давиду; а Давид не хтје пити, него је изли Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'И рече: не дао ми Бог мој да то учиним! Еда ли ћу пити крв тијех људи који не марише за живот свој? Јер је донесоше не марећи за живот свој. И не хте је пити. То учинише та три јунака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'И Ависај брат Јоавов бјеше први између тројице. И он махну копљем својим на три стотине, и поби их, и прослави се међу тројицом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Међу тројицом бјеше славнији од друге двојице и бјеше им поглавица; али оне тројице не стиже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Венаја син Јодајев, син човјека јунака из Кавсеила, који учини велика дјела, он погуби два јунака Моавска, и сишав уби лава у јами кад бјеше снијег.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Он уби и некога Мисирца висока пет лаката. Имаше Мисирац у руци копље као вратило, а он изиде на њ са штапом, и истрже Мисирцу копље из руке, и уби га његовијем копљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'То учини Венаја син Јодајев, и би славан међу ова три јунака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Бјеше најславнији између тридесеторице, али оне тројице не стиже. И Давид га постави над пратиоцима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Јунаци између војника бијаху: Асаило брат Јоавов, Елханан син Додов из Витлејема,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Самот Арорарин, Хелис Фелоњанин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ира син Икисов из Текоје, Авијезер из Анатота,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Сивехај из Хусата, Илај из Ахоха,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Марај из Нетофата, Хелед син Ванин из Нетофата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Итај син Ривајев из Гаваје синова Венијаминових, Венаја из Фаратона,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Урај од потока Гаских, Авило из Арвата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Азмавет из Варума, Елијава из Салвона,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Синови Асима Гизоњанина, Јонатан син Сагијин Араранин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ахијам син Сахаров Араранин, Елифар син Уров,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Ефер из Мехирата, Ахија из Фелона,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Есро Кармилац, Нарав син Есвајев,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Јоило брат Натанов, Мивар син Агиријев,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Селек Амонац, Нарај Вироћанин, који ношаше оружје Јоаву сину Серујину,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ира Јетранин, Гарив Јетранин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Урија Хетејин, Завад син Алајев,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Адина син Сизин од синова Рувимовијех, поглавар синова Рувимовијех, и тридесет с њим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Анан син Машин, и Јосафат из Митне,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Озија из Астерота, Сама и Јехило синови Хотана Ароиранина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Једиаило син Симријев и Јоха брат му из Тисе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Елило Мављанин, и Јеривај и Јосавија синови Елнамови, и Јетема Моавац,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Елило и Овид и Јасило из Месоваје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'А ово су који дођоше Давиду у Сиклаг док се још кријаше од Саула сина Кисова, и бијаху међу јунацима помажући у рату,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Наоружани луком, из десне руке и из лијеве гађаху камењем и из лука стријелама, између браће Саулове, од племена Венијаминова:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Поглавар Ахијезер и Јоас синови Семаје из Гаваје, Језило и Фелет синови Азмаветови, и Вераха и Јуј из Анатота,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'И Исмаја Гаваоњанин, јунак међу тридесеторицом и над тридесеторицом, и Јеремија и Јазило и Јоанан и Јозавад од Гедирота,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Елузај и Јеримот и Валија и Семарија и Сефатија од Аруфа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Елкана и Јесија и Азареило и Јоезер и Јасовеам Коријани,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'И Јоила и Зевадија синови Јероамови из Гедора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'И од племена Гадова пребјегоше Давиду у град у пустињу храбри јунаци, вјешти боју, наоружани штитом и копљем, којима лице бијаше као лице лавовско и бијаху брзи као срне по горама:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Есер први, Овадија други, Елијав трећи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Мисмана четврти, Јеремија пети,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Атај шести, Елило седми,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Јоанан осми, Елзавал девети,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Јеремија десети, Мохванај једанаести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'То бијаху између синова Гадовијех поглавари у војсци, најмањи над стотином а највећи над тисућом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Они пријеђоше преко Јордана првога мјесеца кад се разли преко свијех брегова својих, и отјераше све из долина на исток и на запад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'А дођоше и од синова Венијаминовијех и Јудинијех к Давиду у град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'И изиде им Давид на сусрет, и говорећи рече им: ако мира ради идете к мени, да ми поможете, срце ће се моје здружити с вама; ако ли сте дошли да ме издате непријатељима мојим, неправде нема на мени, нека види Господ отаца наших и нека суди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Тада дух дође на Амасаја поглавара међу војводама, те рече: твоји смо, Давиде, и с тобом ћемо бити, сине Јесејев; мир, мир теби и помагачима твојим, јер ти помаже Бог твој. Тако их прими Давид, и постави их међу поглаваре над четама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'И од синова Манасијиних неки пребјегоше Давиду кад иђаше с Филистејима на Саула у бој, али им не помогоше; јер кнезови Филистејски договоривши се вратише га говорећи: на погибао нашу пребјегнуће господару својему Саулу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Кад се враћаше у Сиклаг, пребјегоше к њему из племена Манасијина: Адна и Јозавад и Једиаило и Михаило и Јозавад и Елиуј и Салтај, тисућници у племену Манасијину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'И они помагаху Давиду противу чети, јер храбри јунаци бјеху сви, те посташе војводе у његовој војсци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Јер сваки дан долажаху к Давиду у помоћ, докле поста велика војска као војска Божија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'А ово је број људи наоружанијех за војску који дођоше к Давиду у Хеврон да пренесу царство Саулово на њ по ријечи Господњој:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Синова Јудинијех који ношаху штит и копље шест тисућа и осам стотина наоружанијех за војску;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Синова Симеуновијех храбријех војника седам тисућа и сто;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Синова Левијевих четири тисуће и шест стотина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'И Јодај поглавар између синова Ароновијех и с њим три тисуће и седам стотина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'И Садок младић, храбар јунак, и од дома оца његова двадесет и два кнеза;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'И синова Венијаминових, браће Саулове, три тисуће; јер их се многи још држаху дома Саулова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'И синова Јефремовијех двадесет тисућа и осам стотина храбријех јунака, људи на гласу у породицама отаца својих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'А од половине племена Манасијина осамнаест тисућа, који бише именовани поименце да дођу да поставе Давида царем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'И синова Исахаровијех, који добро разумијеваху времена да би знали шта ће чинити Израиљ, кнезова њиховијех двјеста, и сва браћа њихова слушаху их;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Синова Завулоновијех, који иђаху на војску и наоружани бијаху за бој свакојаким оружјем, педесет тисућа, који се постављаху у врсте поуздана срца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'А од племена Нефталимова тисућа поглавара и с њима тридесет и седам тисућа са штитовима и копљима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'А од племена Данова двадесет и осам тисућа и шест стотина наоружанијех за бој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'А од племена Асирова четрдесет тисућа војника вјештијех поставити се за бој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'А онијех испреко Јордана од племена Рувимова и Гадова и од половине племена Манасијина, сто и двадесет тисућа са свакојаким оружјем убојитијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Сви ови војници у војничком реду дођоше цијела срца у Хеврон да поставе Давида царем над свијем Израиљем. А и остали сви Израиљци бијаху сложни да царем поставе Давида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'И бијаху ондје с Давидом три дана једући и пијући, јер им браћа бијаху приправила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'А и они који бијаху близу њих, дори до Исахара и Завулона и Нефталима, доношаху хљеба на магарцима и на камилама и на мазгама и на воловима, јела, брашна, смокава и сухога грожђа и вина и уља, волова, оваца изобила; јер бијаше радост у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'И Давид учини вијеће с тисућницима и са стотиницима и са свијем војводама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'И рече Давид свему збору Израиљеву: ако вам је по вољи, и ако је од Господа Бога нашега, да пошаљемо на све стране к браћи својој осталој по свијем крајевима Израиљевијем, и к свештеницима и Левитима по градовима и подграђима њиховијем да се скупе к нама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Па да донесемо к себи ковчег Бога својега, јер га не тражисмо за времена Саулова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'А сав збор рече да се тако учини, јер то би по вољи свему народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'И тако Давид сабра сав народ Израиљев од Сихора Мисирскога дори до Емата, да донесу ковчег Божији из Киријат-Јарима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'И отиде Давид са свијем Израиљем у Валу, у Киријат-Јарим Јудин, да пренесу оданде ковчег Бога Господа, који сједи на херувимима, чије се име призивље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'И повезоше ковчег Божији на новијем колима из куће Авинадавове; а Уза и Ахијо управљаху колима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'А Давид и сав народ Израиљев играху пред Богом из све снаге пјевајући и ударајући у гусле и у псалтире и у бубње и у кимвале и трубећи у трубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'А кад дођоше до гумна Хидонова, Уза се маши руком да прихвати ковчег, јер волови потегоше на страну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'И Господ се разгњеви на Узу, и удари га што се маши руком за ковчег, те умрије ондје пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'И ожалости се Давид што Господ уби Узу: зато се прозва оно мјесто Фарес-Уза до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'И уплаши се Давид од Бога у онај дан, и рече: како ћу донијети к себи ковчег Божји?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'И не пренесе Давид ковчега к себи у град Давидов, него га склони у кућу Овид-Едома Гетејина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'И оста ковчег Божји код породице Овид-Едомове у кући његовој три мјесеца. И Господ благослови дом Овид-Едомов и све што имаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'А Хирам цар Тирски посла посланике к Давиду и дрва кедровијех и зидара и дрводјеља да му саграде кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'И разумје Давид да га је Господ утврдио за цара над Израиљем и да се царство његово подиже високо ради народа његова Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'И Давид узе јоште жена у Јерусалиму и изроди још синова и кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'И ово су имена онијех који му се родише у Јерусалиму: Самуја и Совав, Натан и Соломун,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'И Јевар и Елисуја и Елфалет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'И Нога и Нефег и Јафија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'И Елисама и Велијада и Елифалет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'А Филистеји чувши да је Давид помазан за цара над свијем Израиљем, изидоше сви Филистеји да траже Давида; а Давид чувши то изиде пред њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'И Филистеји дошавши раширише се по долини Рафајској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'Тада Давид упита Господа говорећи: хоћу ли изаћи на Филистеје? И хоћеш ли их дати у моје руке? А Господ му рече: изађи, и даћу их у твоје руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Тада отидоше у Вал-Ферасим, и поби их ондје Давид, и рече Давид: продрије Бог непријатеље моје мојом руком, као што вода продире. Отуда се прозва мјесто Вал-Ферасим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'И оставише ондје богове своје; а Давид заповједи, те их спалише огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'А Филистеји опет по други пут раширише се по оном долу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'И Давид опет упита Бога, а Бог му рече: не иди за њима, него се врати од њих, па удари на њих према дудовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'И кад чујеш да зашушти по врховима од дудова, тада изиди у бој; јер ће поћи Бог пред тобом да побије војску Филистејску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'И учини Давид како му заповједи Бог и поби војску Филистејску од Гаваона до Гезера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'И разгласи се име Давидово по свијем земљама; и Господ зададе страх од њега свијем народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'И начини себи Давид куће у граду Давидову, и спреми мјесто за ковчег Божји, и разапе му шатор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Тада рече Давид: не ваља да носи ковчег Божји нико осим Левита, јер је њих изабрао Господ да носе ковчег Божји и да му служе довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'И скупи Давид све синове Израиљеве у Јерусалим да пренесу ковчег Господњи на мјесто његово, које му бјеше спремио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Скупи Давид и синове Аронове и Левите,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Од синова Катовијех: Урила поглавара и браће његове сто и двадесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Од синова Мераријевих: Асају поглавара и браће његове двјеста и двадесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Од синова Гирсоновијех: Јоила поглавара и браће његове сто и тридесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Од синова Елисафанових: Семају поглавара и браће његове двјеста;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Од синова Хевроновијех: Елила поглавара и браће његове осамдесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Од синова Озиловијех: Аминадава поглавара и браће његове сто и дванаест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Тада дозва Давид Садока и Авијатара свештенике, и Левите и Урила и Асају и Јоила и Самају и Елила и Аминадава,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'И рече им: ви сте поглавари породица отачких међу Левитима; освештајте себе и браћу своју да донесете ковчег Господа Бога Израиљева на мјесто које сам му спремио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Јер што пређе не учинисте тога, Господ Бог наш продрије нас, јер га не тражисмо како треба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'И освешташе се свештеници и Левити да пренесу ковчег Господа Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'И носише синови Левитски ковчег Божији као што је заповједио Мојсије по ријечи Господњој на раменима својим и полугама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'И рече Давид поглаварима Левитским да поставе између браће своје пјеваче са справама музицким, са псалтирима и гуслама и кимвалима, да пјевају у глас весело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'И поставише Левити Емана сина Јоилова, и од браће његове Асафа сина Варахијина, и од синова Мераријевих, браће њихове, Етана сина Кисајина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'И с њима браћу њихову другога реда: Захарију и Вена и Јазила и Семирамота и Јехила и Унија и Елијава и Венају и Масију и Мататију и Елифела и Микнеју и Овид-Едома и Јеила, вратаре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'И пјевачи Еман и Асаф и Етан удараху у кимвале мједене;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'А Захарија и Озило и Семирамот и Јехило и Уније и Елијав и Масија и Венаја у псалтире високо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'А Мататија и Елифел и Микнеја, и Овид-Едом, и Јеило и Азазија у гусле ниско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'А Хенанија поглавар међу Левитима који ношаху ковчег уређиваше како ће се носити, јер бјеше вјешт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'А Варахија и Елкана бјеху вратари код ковчега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'А Севанија и Јосафат и Натанаило и Амасај и Захарија и Венаја и Елијезер, свештеници, трубљаху у трубе пред ковчегом Божјим; а Овид-Едом и Јехија бјеху вратари код ковчега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'И тако Давид и старјешине Израиљеве и тисућници иђаху пратећи ковчег завјета Господњега из куће Овид-Едомове с весељем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'И кад Бог поможе Левитима који ношаху ковчег завјета Господњега принесоше седам волова и седам овнова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'И Давид бијаше огрнут плаштем од танкога платна, тако и сви Левити који ношаху ковчег и пјевачи, Хенанија који управљаше носиоцима међу пјевачима. И Давид имаше на себи оплећак ланен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'И тако сав народ Израиљев праћаше ковчег завјета Господњега кликујући и трубећи у трубе и у рогове и ударајући у кимвале и у псалтире и у гусле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'А кад ковчег завјета Господњега улажаше у град Давидов, Михала кћи Саулова гледајући с прозора виде цара Давида гдје скаче и игра, и подругну му се у срцу свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'И кад донесоше ковчег Божји, намјестише га усред шатора, који му разапе Давид; и принесоше жртве паљенице и жртве захвалне пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Потом принесавши Давид жртве паљенице и жртве захвалне, благослови народ у име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'И раздаде свијем Израиљцима, и људима и женама, сваком по један хљеб и комад меса и врч вина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Потом постави пред ковчегом Господњим слуге између Левита да помињу и славе и хвале Господа Бога Израиљева:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Асафа поглавара, а другога за њим Захарију, и Јеила и Семирамота и Јехила и Мататију и Елијава и Венају и Овид-Едома; и Јеило удараше у псалтире и гусле, а Асаф у кимвале,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'А Венаја и Јазило свештеници бијаху једнако с трубама пред ковчегом завјета Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'У тај дан нареди Давид први пут да хвале Господа Асаф и браћа његова:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Хвалите Господа; гласите име његово; јављајте по народима дјела његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Пјевајте му, славите га, казујте сва чудеса његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Хвалите се светијем именом његовијем; нека се весели срце онијех који траже Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Тражите Господа и силу његову; тражите лице његово без престанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Памтите чудеса његова, која је учинио, знаке његове и судове уста његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'Сјеме Израиљево слуге су његове, синови Јаковљеви избрани његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Он је Господ Бог наш, по свој су земљи судови његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Памтите увијек завјет његов, ријеч коју је дао на тисућу кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'Што је завјетовао Авраму и зашто се клео Исаку,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'То је поставио Јакову за закон и Израиљу за завјет вјечни,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Говорећи: теби ћу дати земљу Хананску у нашљедни дио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Тада вас бијаше мало на број, бијаше вас мало, и бијасте дошљаци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Иђаху од народа до народа, и из једнога царства к другому племену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Не даде никому да им науди, и караше за њих цареве:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Не дирајте у помазанике моје, и пророцима мојим не чините зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Пјевај Господу, сва земљо! јављајте од дана на дан спасење његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Казујте по народима славу његову, по свијем племенима чудеса његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Јер је велик Господ и ваља га хвалити веома; страшнији је од свијех богова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Јер су сви богови у народа ништа; а Господ је небеса створио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Слава је и величанство пред њим, сила и радост у стану његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Дајте Господу, племена народна, дајте Господу славу и част.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Дајте Господу славу према имену његову, носите даре и идите преда њ, поклоните се Господу и светој красоти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Стрепи пред њим, сва земљо; зато је васиљена тврда и неће се помјестити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Нек се веселе небеса и земља се радује; и нека говоре по народима: Господ царује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Нека пљеска море и што је у њему; нека скаче поље и све што је на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Тада нека се радују дрвета шумска пред Господом, јер иде да суди земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Хвалите Господа, јер је добар, јер је довијека милост његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'И реците: спаси нас, Боже спасења нашега, и скупи нас и избави нас од народа да славимо свето име твоје, да се хвалимо твојом славом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Благословен Господ Бог Израиљев од вијека и до вијека. Тада сав народ рече: амин; и хвалише Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'И остави ондје пред ковчегом завјета Господњега Асафа и браћу његову да служе пред ковчегом без престанка као што треба од дана на дан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'И Овид-Едома и браћу његову, шездесет и осам, Овид-Едома сина Једутунова и Осу, да буду вратари;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'А Садока свештеника и браћу његову свештенике пред шатором Господњим на висини у Гаваону,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Да приносе жртве паљенице Господу на олтару за жртве паљенице без престанка јутром и вечером, и да чине све што је написано у закону Господњем што је заповједио Израиљу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'И с њима Емана и Једутуна и друге изабране, који бише поименице именовани да хвале Господа, јер је довијека милост његова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'С њима Емана и Једутуна, да трубе у трубе и ударају у кимвале и у друге справе музичке Богу; а синове Једутунове да буду вратари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Потом се разиде сав народ, свак својој кући, а Давид се врати да благослови дом свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'А кад Давид сјеђаше код куће своје, рече Давид Натану пророку: гле, ја стојим у кући кедрова дрвета, а ковчег завјета Господњега под завјесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'А Натан рече Давиду: што ти је год у срцу, чини, јер је Бог с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Али ону ноћ дође ријеч Божија Натану говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Иди и реци Давиду слузи мојему: овако вели Господ: ти ми нећеш сазидати куће да у њој наставам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Кад нијесам наставао у кући откад изведох Израиља до данас, него сам ишао од шатора до шатора и од наслона до наслона,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Куда сам год ходио са свијем Израиљем, јесам ли једну ријеч рекао коме између судија Израиљевијех којима заповиједах да пасу народ мој, и казао: зашто ми не начините кућу од кедра?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Овако дакле реци слузи мојему Давиду: овако вели Господ над војскама: ја те узех од тора, од оваца, да будеш вођ народу мојему Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'И бјех с тобом куда си год ишао, и истријебих све непријатеље твоје испред тебе, и стекох ти име као што је име великих људи на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'И одредићу мјесто народу својему Израиљу, и посадићу га, те ће наставати у свом мјесту, и неће се више претресати; нити ће им више досађивати неправедници као прије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'И од онога дана када сам поставио судије над народом својим Израиљем; и покорих све непријатеље твоје; него ти јављам да ће ти Господ сазидати кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'И кад се наврше дани твоји да отидеш к оцима својим, подигнућу сјеме твоје након тебе, које ће бити између синова твојих, и утврдићу царство његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Они ће ми сазидати дом, и утврдићу пријесто његов довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Ја ћу му бити отац, и он ће ми бити син; а милости своје нећу уклонити од њега као што сам уклонио од онога који бјеше прије тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Него ћу га утврдити у дому свом и у царству свом довијека, и пријесто ће његов стајати довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'По свијем овијем ријечима и по свој овој утвари каза Натан Давиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Тада дође цар Давид и стаде пред Господом, и рече: ко сам ја, Господе Боже, и шта је дом мој, те си ме довео довде?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'И то ти се чини мало, Боже, него си говорио и за дом слуге својега на дуго времена, и постарао си се за ту славу законом човјечијим, Господе Боже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Шта ће још Давид да ти говори о части слуге твојега, кад ти знаш слугу својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Господе, слуге својега ради и по срцу својему чиниш сву ову велику ствар, обзнањујући све ове велике ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Господе, нема таквога какав си ти, и нема Бога осим тебе, по свему што чусмо својим ушима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Јер који је народ на земљи као твој народ Израиљ? ради којега је Бог ишао да га искупи да му буде народ, и да стече себи име великим и страшним дјелима изгонећи народе испред народа својега, који си искупио из Мисира');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Јер си учинио народ свој Израиља својим народом довијека; а ти си им, Господе, Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'И тако, Господе, ријеч коју си обрекао слузи својему и дому његову нека буде тврда довијека, и учини како си рекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Нека буде тврда, да се велича име твоје довијека и да се говори: Господ над војскама, Бог Израиљев јест Бог над Израиљем, и дом Давида слуге твојега нека стоји тврдо пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Јер си ти, Боже мој, јавио слузи својему да ћеш му сазидати дом, зато се слуга твој усуди да ти се помоли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Тако Господе, ти си Бог, и обрекао си слузи својему то добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Буди дакле вољан и благослови дом слуге својега да буде довијека пред тобом; јер кад ти, Господе, благословиш, биће благословен довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'А послије тога поби Давид Филистеје и покори их, и узе Гат и села његова из руку Филистејских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Поби и Моавце, и посташе Моавци слуге Давидове и плаћаху му данак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Разби Давид и Адад-Езера цара Совскога у Емату изашав да рашири власт своју до ријеке Ефрата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'И узе му Давид тисућу кола и седам тисућа коњика и двадесет тисућа пјешака, и подреза Давид жиле свијем коњима колским, само остави за сто кола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'А бијаху дошли Сирци из Дамаска у помоћ Адад-Езеру цару Совскому, и Давид поби двадесет и двије тисуће Сираца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'И намјести Давид војску у Сирији што је под Дамаском, и Сирци посташе слуге Давидове плаћајући му данак. И Господ чуваше Давида куда год иђаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'И Давид узе златне штитове које имаху слуге Адад-Езерове, и донесе их у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'И из Тивата и из Хуна градова Адад-Езеровијех однесе Давид силну мјед, од које Соломун начини море мједено и ступове и посуђе мједено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'А кад чу Тоја цар Ематски да је Давид побио сву војску Адад-Езера цара Совскога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Посла Адорама сина својега к цару Давиду да га поздрави и да му честита што је војевао на Адад-Езера и убио га, јер Тоја имаше рат са Адад-Езером и свакојаких заклада златнијех и сребрнијех и мједенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Па и то цар Давид посвети са сребром и златом што бјеше узео од свијех народа, од Едомаца и од Моаваца и од синова Амоновијех и од Филистеја и од Амалика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'И Ависај син Серујин поби осамнаест тисућа Идумејаца у сланој долини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'И намјести војску по Идумеји, и сви Идумејци посташе слуге Давидове. И Господ чуваше Давида куда год иђаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Тако царова Давид над свијем Израиљем судећи и дајући правду свему народу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'И Јоав син Серујин бјеше над војском, а Јосафат син Ахилудов паметар,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'А Садок син Ахитовов и Авимелех син Авијатаров свештеници, а Суса писар,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'А Венаја син Јодајев бјеше над Херетејима и Фелетејима, а синови Давидови први до цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'А послије тога умрије Нас цар синова Амоновијех, и зацари се син његов на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'И рече Давид: да учиним милост Ануну сину Насову, јер је отац његов начинио мени милост. И посла Давид посланике да га потјеше за оцем. И дођоше слуге Давидове у земљу синова Амоновијех к Ануну да га потјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'А кнезови синова Амоновијех рекоше Ануну господару својему: мислиш да је Давид зато послао људе да те потјеше што је рад учинити част оцу твојему? а нијесу зато дошле слуге његове к теби да промотре и уходе и оборе земљу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Тада Анун ухвати слуге Давидове, и обрија их и отсијече им хаљине по поле до задњице, и оправи их натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'А кад неки отидоше, те јавише Давиду за те људе, он посла пред њих, јер људи бијаху грдно осрамоћени, и поручи им цар: сједите у Јерихону док вам нарасте брада, па онда дођите натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'А кад видјеше синови Амонови гдје се омразише с Давидом, онда Анун и синови Амонови послаше тисућу таланата сребра да најме кола и коњика из Месопотамије и из Сирије Махе и из Сове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'И најмише тридесет и двије тисуће кола и цара од Махе с народом његовијем, који дођоше и стадоше у око према Медеви. А и синови Амонови скупише се из градова својих и дођоше на бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'А Давид кад то чу, посла Јоава са свом храбром војском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'И изидоше синови Амонови и уврсташе се пред вратима градским; а цареви који дођоше бијаху за се у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'И Јоав видјећи намјештену војску према себи спријед и састраг, узе одабране из све војске Израиљске, и намјести их према Сирцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'А остали народ предаде Ависају брату својему; и намјестише их према синовима Амоновијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'И рече: ако Сирци буду јачи од мене, дођи ми у помоћ; ако ли синови Амонови буду јачи од тебе, ја ћу теби доћи у помоћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Буди јунак и држимо се јуначки за свој народ и за градове Бога својега; а Господ нека учини што му је драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Тада Јоав и народ који бијаше с њим примакоше се да ударе на Сирце; али они побјегоше испред њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'А синови Амонови кад видјеше гдје побјегоше Сирци, побјегоше и они испред Ависаја брата његова и уђоше у свој град. Потом се Јоав врати у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Али Сирци кад видјеше гдје их надбише Израиљци, послаше посланике те доведоше Сирце испреко ријеке; а Софак војвода Адад-Езеров иђаше пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Кад то јавише Давиду, он скупи све Израиљце, и пријеђе преко Јордана, и дође к њима и намјести војску према њима; а кад намјести Давид војску према њима, побише се с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Али побјегоше Сирци испред Израиља, и поби Давид Сираца седам тисућа кола и четрдесет тисућа пјешака, и Софака војводу погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'И кад видјеше слуге Адад-Езерове да их разби Израиљ, учинише мир с Давидом и служаху му; и не хтјеше више Сирци помагати синовима Амоновијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'А кад прође година, у вријеме кад цареви иду на војску, Јоав изведе војску, па потираше земљу синова Амоновијех, и дошавши опколи Раву; а Давид бјеше остао у Јерусалиму. И Јоав освоји Раву и раскопа је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'И Давид узе цару њихову с главе круну, и нађе да потеже таланат злата, и драго камење бјеше у њој; и метнуше је на главу Давиду, и однесе из града плијен врло велик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'А народ што бијаше у њему изведе и исијече их пилама и гвозденијем бранама и сјекирама. И тако учини Давид свијем градовима синова Амоновијех. Потом се врати Давид са свијем народом у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'А послије тога наста рат у Гезеру у Филистејима; тада Сивехај Хусаћанин уби Сифаја који бијаше рода дивовскога, и бише покорени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Наста опет рат с Филистејима, у ком Елханан син Јаиров уби Ламију брата Голијата Гетејина, којему копљача бијаше као вратило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'И опет наста рат у Гату, гдје бијаше један човјек врло висок, који имаше по шест прста, скупа двадесет и четири; и он бијаше рода дивовскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'И ружаше Израиља, те га уби Јонатан син Самаје брата Давидова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ти бијаху синови истога дива из Гата, и погибоше од руке Давидове и од руке слуга његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Али уста сотона на Израиља и наврати Давида да изброји Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'И рече Давид Јоаву и кнезовима народнијем: идите, избројте синове Израиљеве од Вирсавеје дори до Дана, па ми јавите да знам колико их има.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Али Јоав рече: нека дода Господ народу својему колико га је сада још сто пута толико; нијесу ли, царе господару мој, сви слуге господару мојему? зашто тражи то господар мој? зашто да буде на гријех Израиљу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Али ријеч царева надјача Јоава. И тако отиде Јоав и обиђе свега Израиља, па се врати у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'И даде Јоав број преписанога народа Давиду; и бијаше свега народа Израиљева тисућа тисућа и сто тисућа људи који махаху мачем, а народа Јудина четири стотине и седамдесет тисућа људи који махаху мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'А племена Левијева и Венијаминова не изброји с њима, јер мрска бјеше Јоаву заповијест царева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'А не бјеше мила Богу та ствар; зато удари Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'И Давид рече Богу: сагријеших веома што то урадих; али узми безакоње слуге својега, јер веома лудо радих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'А Господ рече Гаду видиоцу Давидову говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Иди кажи Давиду и реци: овако вели Господ: троје ти дајем, изабери једно да ти учиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'И дође Гад к Давиду и рече му: тако вели Господ, бирај:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Или глад за три године, или три мјесеца да бјежиш од непријатеља својих и мач непријатеља твојих да те стиже, или три дана мач Господњи и помор да буде у земљи и анђео Господњи да убија по свијем крајевима Израиљевијем. Сада дакле гледај што ћу одговорити оному који ме је послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'А Давид рече Гаду: у тјескоби сам љутој; али нека западнем Господу у руке, јер је веома велика милост његова; а људима да не западнем у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'И тако пусти Господ помор на Израиља, те паде Израиља седамдесет тисућа људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'И посла Господ анђела у Јерусалим да га убија; и кад убијаше, погледа Господ и сажали му се са зла; и рече анђелу који убијаше: доста, спусти руку своју. А анђео Господњи стајаше код гумна Орнана Јевусејина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'А Давид подиже очи своје и видје анђела Господњега гдје стоји између земље и неба а у руци му го мач, којим бјеше замахнуо на Јерусалим; и паде Давид и старјешине ничице, обучени у костријет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'И рече Давид Богу: нијесам ли ја заповједио да се изброји народ? ја сам дакле згријешио и зло учинио; а те овце шта су учиниле? Господе Боже мој, нека се рука твоја обрати на ме и на дом оца мојега; али не на тај народ да га потре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Тада анђео Господњи рече Гаду да каже Давиду да изиде горе и начини олтар Господу на гумну Орнана Јевусејина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'И изиде Давид по ријечи Гадовој, коју му рече у име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'А Орнан окренув се угледа анђела, и сакри се са четири сина своја. Јер Орнан врсијаше пшеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Утом дође Давид до Орнана; и погледав Орнан кад видје Давида изиде из гумна и поклони се Давиду лицем до земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Тада рече Давид Орнану: дај ми то гумно да начиним на њему олтар Господу; за новце колико вриједи дај ми га, да би престао помор у народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'А Орнан рече Давиду: узми и нека чини господар мој цар што му је драго; ево дајем и волове за жртве паљенице, и кола за дрва, и пшеницу за дар; све то дајем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'А цар Давид рече Орнану: не, него ћу купити за новце шта вриједи, јер нећу да принесем Господу што је твоје ни да принесем жртве паљенице поклоњене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'И даде Давид Орнану за оно мјесто на мјеру шест стотина сикала злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'И ондје начини Давид олтар Господу, и принесе жртве паљенице и жртве захвалне; и призва Господа, и услиши га спустивши огањ с неба на олтар жртве паљенице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'И заповједи Господ анђелу, те врати мач свој у корице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'У оно вријеме видјев Давид да га Господ услиши на гумну Орнана Јевусејина приношаше жртве ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'А шатор Господњи, који начини Мојсије у пустињи, и олтар за жртве паљенице бијаше у то вријеме на висини у Гаваону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'И Давид не може ићи к њему да тражи Богу, јер се уплаши од мача анђела Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'И рече Давид: ово је кућа Господа Бога и ово је олтар за жртву паљеницу Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'И заповједи Давид да се скупе иностранци који бијаху у земљи Израиљевој, и одреди каменаре да тешу камен да се гради дом Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'И гвожђа много за клине на крила вратима и на саставке приправи Давид, и мједи много без мјере,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'И дрва кедровијех без броја; јер довожаху Сидонци и Тирци много дрва кедровијех Давиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Јер Давид говораше: Соломун је син мој дијете младо, а дом који треба зидати Господу треба да буде врло велик за славу и дику по свијем земљама; зато ћу му приправити што треба. И приправи Давид мноштво прије смрти своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Потом дозва сина својега Соломуна и заповједи му да сазида дом Господу Богу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'И рече Давид Соломуну: сине! био сам наумио да сазидам дом имену Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Али ми дође ријеч Господња говорећи: много си крви пролио и велике си ратове водио; нећеш ти сазидати дома имену мојему, јер си много крви пролио на земљу преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Ево, родиће ти се син, он ће бити миран човјек и смирићу га од свијех непријатеља његовијех унаоколо; зато ће му бити име Соломун; и мир и покој даћу Израиљу за његова времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Он ће сазидати дом имену мојему, и он ће ми бити син, а ја њему отац, и утврдићу пријесто царства његова над Израиљем довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Зато, сине, Господ ће бити с тобом, и бићеш срећан, те ћеш сазидати дом Господа Бога својега као што је говорио за те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Само да ти да Господ разум и мудрост кад те постави над Израиљем да држиш закон Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Тада ћеш бити срећан, ако уздржиш и уствориш уредбе и законе које је заповједио Господ преко Мојсија Израиљу. Буди слободан и храбар, не бој се и не плаши се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'И ево, у невољи својој приправио сам за дом Господњи сто тисућа таланата злата и тисућу тисућа таланата сребра; а мједи и гвожђа без мјере, јер га има много, такођер и дрва и камења приправио сам; а ти додај још.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'А имаш и посленика много, каменара и зидара и дрводјеља, и свакојаких људи вјештијех сваком послу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Има злата, сребра, и мједи и гвожђа без мјере; настани дакле и ради, и Господ ће бити с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Потом заповједи Давид свијем кнезовима Израиљевијем да помажу Соломуну сину његову:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Није ли с вама Господ Бог ваш, који вам је дао мир од свуда? јер је дао у руке моје становнике ове земље, и земља је покорена Господу и народу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Сада дакле управите срце своје и душу своју да тражите Господа Бога својега; настаните и зидајте светињу Господу Богу да унесете ковчег завјета Господњега и свето посуђе Божије у дом који ће се сазидати имену Господњему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'И тако Давид стар и сит живота постави Соломуна сина својега царем над Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'И сабра све кнезове Израиљеве и свештенике и Левите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'И бише избројани Левити од тридесет година и више, и бјеше их на број с главе на главу тридесет и осам тисућа људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Између њих бијаше двадесет четири тисуће одређенијех на посао у дому Господњем, а шест тисућа управитеља и судија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'А четири тисуће вратара и четири тисуће који хваљаху Господа уз оруђа која начини за хвалу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'И раздијели их Давид у редове по синовима Левијевим, Гирсону, Кату и Мерарију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Од Гирсона бијаху: Ладан и Симеј;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Синови Ладанови: поглавар Јехило и Зетам и Јоило, тројица;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, '(Синови Симејеви: Селомит и Азило и Харан, тројица.) То су поглавари отачких породица Ладановијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'А синови Симејеви: Јат, Зина и Јеус и Верија, та су четворица синови Симејеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'А Јат бијаше поглавар, а Зиза други; а Јеус и Верија немаху много дјеце, зато се бројаху у један дом отачки.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Синови Катови: Амрам, Исар, Хеврон и Озило, четворица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Синови Амрамови: Арон и Мојсије. Али Арон би одвојен да освећује светињу над светињама, он и синови његови довијека, да каде пред Господом, да му служе и да благосиљају у име његово довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'А синови Мојсија човјека Божијега броје се у племе Левијево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Синови Мојсијеви: Гирсам и Елиезер.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Синови Гирсамови: Севуило поглавар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'А синови Елиезерови. Реавија поглавар. А немаше Елиезер више синова, него се синови Реавијини умножише веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Синови Исарови: Селомит поглавар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Синови Хевронови: Јерија први, Амарија други, Јазило трећи, и Јекамеам четврти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Синови Озилови: Миха први и Јесија други.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Синови Мераријеви: Малије и Мусије. Синови Малијеви: Елеазар и Кис.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'А Елеазар умрије и не имаше синова него само кћери, и њима се оженише синови Кисови, браћа њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Синови Мусијеви: Малије и Едер и Јеремот, тројица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'То су синови Левијеви по отачким домовима својим, поглавари домова отачких, који бише избројени по броју имена с главе на главу, који рађаху посао за службу у дому Господњем, од двадесет година и више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Јер Давид рече: мир даде Господ Бог Израиљев народу својему, и наставаће у Јерусалиму довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'И Левити неће више носити шатора и посуђа његова за службу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Јер по пошљедњој наредби Давидовој бише избројени синови Левијеви од двадесет година и више;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Јер одређени бијаху да помажу синовима Ароновијем у служби у дому Господњем у тријемовима и у клијетима, и да чисте све свете ствари и да раде око службе у дому Господњем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'И око хљебова постављенијех, и око бијелога брашна за дар и око колача пријеснијех и око тавица, и око свега што се пржи, и око сваке мјере,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'И да стоје јутром и хвале и славе Господа, и тако вечером,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'И кад се год приносе жртве паљенице Господу, у суботе, и на младине и празнике, у броју по реду свом свагда пред Господом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'И да раде што треба радити у шатору од састанка и у светињи, и за синове Аронове, браћу своју, у служби у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'А међу синовима Ароновијем ово су редови: синови Аронови бјеху Надав и Авијуд, Елеазар и Итамар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Али Надав и Авијуд умријеше прије оца својега и немаху дјеце; зато бише свештеници Елеазар и Итамар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'И раздјели их Давид: Садока, који бијаше од синова Елеазаровијех, и Ахимелеха, који бијаше од синова Итамаровијех, по реду њихову у служби њиховој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'И нађе се синова Елеазаровијех више поглавица него синова Итамаровијех, кад их раздијелише: од синова Елеазаровијех бијаше поглавица по домовима отачким шеснаест, а од синова Итамаровијех осам по домовима отачким.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'И бише раздијељени ждријебом и један и други; јер поглавари у светињи и поглавари пред Богом бијаху и од синова Елеазаровијех и од синова Итамаровијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'И пописа их Семаја син Натанаилов писар од племена Левијева пред царем и кнезовима и Садоком свештеником и Ахимелехом сином Авијатаровијем и пред поглаварима породица отачких међу свештеницима и Левитима, један дом отачки узевши за Елеазара а један за Итамара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'И паде први ждријеб на Јојарива, други на Једају,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'Трећи на Харима, четврти на Сеорима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'Пети на Малхију, шести на Мејамина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'Седми на Акоса, осми на Авију,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'Девети на Исуја, десети на Сеханију,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'Једанаести на Елијасива, дванаести на Јакима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'Тринаести на Уфу, четрнаести на Јесевава,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'Петнаести на Вилгу, шеснаести на Имира,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'Седамнаести на Езира, осамнаести на Афисиса,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'Деветнаести на Петају, двадесети на Језекила,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'Двадесет први на Јахина, двадесет други на Гамула,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'Двадесет трећи на Делају, двадесет четврти на Мазију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'То је ред њихов за службу њихову, којим иду у дом Господњи на посао свој по наредби Арона оца својега, како му бјеше заповједио Господ Бог Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'А од осталијех синова Левијевих бијаше од синова Амрамовијех Суваило; од синова Суваиловијех Једаја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Од Реавије, од синова Реавијиних поглавар Јесија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Од синова Исаровијех Селомот, од синова Селомотовијех Јат;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'А од синова Јеријиних Амарија други, Јазило трећи, Јекамеам четврти;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Од синова Узиловијех Миха; од синова Мишинијех Самир;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Брат Мишин Јесија; од синова Јесинијих Захарија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Синови Мераријеви: Малије и Мусије; од синова Јазијиних Вено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Синови Мераријеви од Јазије: Вено и Соам и Захур и Иврије;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Од Малија Елеазар, који немаше синова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Од Киса, од синова Кисовијех: Јерамеило;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'И од синова Мусијевих Малије и Едер и Јеримот. То бијаху синови Левитски по домовима отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'И они бацаше ждријеб према браћи својој, синовима Ароновијем, пред Давидом и Садоком и Ахимелехом и поглаварима домова отачких међу свештеницима и Левитима, од домова отачких сваки поглавар према брату својему млађему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'И одвоји Давид с војводама за службу синове Асафове и Еманове и Једутунове, који ће пророковати уз гусле и псалтире и кимвале; и бише између њих избројани људи за посао у својој служби:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Од синова Асафовијех: Захур и Јосиф и Нетанија и Асарила, синови Асафови, под руком Асафа, који пророковаше по наредби царевој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Од Једутуна: шест синова Једутуновијех: Гедалија и Сорије и Јесаија, Асавија и Мататија и Симеј под руком оца својега Једутуна, који пророковаше уз гусле хвалећи и славећи Господа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Од Емана: синови Еманови: Вукија, Матанија, Озило, Севуило и Јеримот, Ананија и Ананије, Елијата, Гидалтија и Ромамти-Езер, Јосвекаса, Малотије, Отир и Мазиот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Ти сви бијаху синови Емана видиоца царева у ријечима Божијим да се узвишује рог; јер Бог даде Еману четрнаест синова и три кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Сви они бијаху под руком оца својега пјевајући у дому Господњем уз кимвале и псалтире и гусле, за службу у дому Божијем, како цар наређиваше Асафу и Једутуну и Еману.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'И бјеше их на број с браћом њиховом обученом пјесмама Господњим, двјеста и осамдесет и осам, самијех вјештака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'И бацише ждријеб за службу своју, мали као велики, учитељ као ученик;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'И паде први ждријеб за Асафа на Јосифа, други на Гедалију с браћом и синовима његовијем, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Трећи на Захура, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Четврти на Исерија, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Пети на Нетанију, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Шести на Вукију, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Седми на Јесарилу, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Осми на Јесаију, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Девети на Матанију, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Десети на Симеја, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Једанаести на Азареила, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Дванаести на Асавију, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Тринаести на Савуила, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Четрнаести на Мататију, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Петнаести на Јеремота, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Шеснаести на Ананију, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Седамнаести на Јосвекасу, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Осамнаести на Ананија, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Деветнаести на Малотија, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Двадесети на Елијату, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Двадесет први на Отира, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Двадесет други на Гидалтију, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Двадесет трећи на Мазиота, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Двадесет четврти на Ромамти-Езера, синове његове и браћу његову, њих дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'А редови вратарски бијаху: од синова Корејевих бијаше Меселемија син Корејев између синова Асафовијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'А синови Меселемијини: Захарија првенац, Једаило други, Завадија трећи, Јатнило четврти,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Елам пети, Јоанан шести, Елиоинај седми;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'И Овид-Едомови синови: Семаја првенац, Јозавад други, Јоах трећи и Сихар четврти и Натанаило пети,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Амило шести, Исахар седми, Феултај осми; јер га благослови Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'И Семаји сину његову родише се синови, који старјешоваху у дому оца својега, јер бијаху добри јунаци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Синови Семајини: Готније и Рафаило и Овид и Елзавад браћа његова, храбри људи, Елиуј и Семахија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Сви ови бијаху од синова Овид-Едомовијех, и они и синови њихови и браћа њихова, сви храбри људи, крјепки за службу, бијаше их шездесет и два од Овид-Едома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'А Меселемијиних синова и браће, храбријех људи, бијаше осамнаест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'А Осини синови, од синова Мераријевих: Симрије поглавар, премда не бјеше првенац, али га отац постави поглаварем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Хелкија други, Тевалија трећи, Захарија четврти; свијех синова и браће Осине бијаше тринаест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Од њих бијаху редови вратарски по поглаварима да чувају стражу наизмјенце с браћом својом служећи у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Јер меташе ждријеб за малога као и за великога по домовима својих отаца, за свака врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'И паде ждријеб на исток Селимији; а Захарији сину његову, мудрому савјетнику, кад бацише ждријеб, паде му ждријеб на сјевер;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'А Овид-Едому на југ, а синовима његовијем на ризницу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Суфиму и Оси на запад с вратима Салехетским на путу који иде горе; стража бјеше према стражи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'С истока шест Левита; са сјевера четири на дан; с југа на дан четири; а код ризнице по два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'На Парвару са запада четири на путу, два код Парвара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'То су редови вратарски међу синовима Корејевим и синовима Мераријевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'И ови још бијаху Левити: Ахија над благом дома Божијега, над благом од посвећенијех ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Од синова Ладановијех између синова Гирсоновијех од Ладана, између главара домова отачких од Ладана сина Гирсонова бијаше Јехило,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Синови Јехилови: Зетам и Јоило брат му бијаху над благом дома Господњега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Од синова Амрамовијех, Исаровијех, Хевроновијех, Озиловијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Бијаше Севуило син Гирсона сина Мојсијева старјешина над благом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'А браћа његова од Елијезера: Реавија син му, а његов син Јесаија, а његов син Јорам, а његов син Зихрије, а његов син Селомит;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Овај Селомит и браћа његова бијаху над свијем благом од посвећенијех ствари, које посвети цар Давид и поглавари домова отачких и тисућници и стотиници и војводе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Од ратова и од плијена посветише да се оправи дом Господњи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'И што год бјеше посветио Самуило видјелац и Саул син Кисов и Авенир син Ниров и Јоав син Серујин; ко год посвећиваше, даваше у руке Селомиту и браћи његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Од синова Исаровијех: Хенанија и синови његови бијаху над спољашњим пословима у Израиљу, управитељи и судије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Од синова Хевроновијех Асавија и браћа његова, тисућа и седам стотина храбријех људи, бијаху над Израиљем с ову страну Јордана на истоку за сваки посао Господњи и за службу царску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Између синова Хевроновијех бијаше Јерија поглавар синовима Хевроновијем по породицама њиховијем и домовима отачким. Четрдесете године царовања Давидова потражише их и нађоше међу њима храбријех јунака у Јазиру Галадском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'И браће његове, храбријех људи, бијаше двије тисуће и седам стотина главара у домовима отачким; и постави их цар Давид над синовима Рувимовијем и Гадовијем и половином племена Манасијина за све послове Божије и царске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'А синови Израиљеви по свом броју, главари домова отачких, тисућници и стотиници и управитељи њихови, служаху цару у сваком послу у редовима, који долажаху и одлажаху од мјесеца до мјесеца, свакога мјесеца у години; а у сваком реду бијаше их двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Над првијем редом првога мјесеца бијаше Јасовеам син Завдилов, и у његову реду бијаше двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Од синова Фаресовијех бијаше поглавар над свијем старјешинама у војсци првога мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'А над редом другога мјесеца бијаше Додај Ахошанин, и војвода у његову реду бјеше Миклот; и у његову реду бјеше двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Трећи војвода трећега мјесеца бјеше Венаја син Јодаја свештеника, поглавар; и у његову реду бјеше двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Овај Венаја бјеше јунак међу тридесеторицом и над тридесеторицом; и над редом његовијем бјеше Амнизавад син му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Четврти, четвртога мјесеца Асаило брат Јоавов, а за њим Зевадија син му; и у реду његову бјеше двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Пети, петога мјесеца, поглавар Самут Језрајанин, и у његову реду бјеше двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Шести, шестога мјесеца, Ира син Икисов Текојанин, а у његову реду бјеше двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Седми, седмога мјесеца, Хелис Фелоњанин од синова Јефремовијех, а у његову реду бјеше двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Осми, осмога мјесеца, Сивехај Хусаћанин од синова Заринијех, и у његову реду бјеше двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Девети, деветога мјесеца, Авијезер Анатоћанин од синова Венијаминових, и у његову реду бјеше двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Десети, десетога мјесеца, Марај Нетофаћанин од синова Заринијех, и у његову реду бјеше двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Једанаести, једанаестог мјесеца, Венаја Фаратоњанин од синова Јефремовијех, и у његову реду бјеше двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Дванаести, дванаестог мјесеца, Хелдај Нетофаћанин од Готонила, а у његову реду бјеше двадесет и четири тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'А над племенима Израиљевијем бијаху: над племеном Рувимовијем кнез Елијезер син Зихријев; над Симеуновијем Сефатија син Машин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Над Левијевим Асавија син Кемуилов; над Ароновијем Садок;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Над Јудинијем Елиуј од браће Давидове; над Исахаровијем Амрије син Михаилов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Над Завулоновијем Исмаја син Овадијин; над Нефталимовим Јеримот син Азрилов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Над синовима Јефремовијем Исус син Азазијев; над половином племена Манасијина Јоило син Федајин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'Над другом половином племена Манасијина у Галаду Идо син Захаријин; над Венијаминовим Јасило син Авениров;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Над Дановијем Азареило син Јероамов. То бијаху кнезови племена Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'А не изброји Давид онијех који имаху мање од двадесет година, јер Господ бјеше рекао да ће умножити синове Израиљеве као звијезде небеске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Јоав син Серујин поче бројити, али не доврши; јер дође гњев Божји за то на Израиља; зато тај број не дође у књигу о цару Давиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Над благом царевијем бијаше Азмавет син Адилов, а над благом по земљи, по градовима и по селима и по кулама Јонатан син Озијин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'А над ратарима, који рађаху земљу, бијаше Езрије син Хелувов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'А над виноградарима Симеј Рамаћанин; а над родом виноградским и над пивницама Завдије Сифмејин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'А над маслинама и смоквама по пољима Вал-Анан Гедеранин; а над уљем Јоас;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Над говедима што пасијаху у Сарону Ситрај Сароњанин, а над говедима по долинама Сафат Адлајев;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Над камилама Овил Исмаиљац; над магарцима Једаја Мероноћанин;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'А над овцама Јазиз Агарејин. Сви ови бијаху настојници над благом цара Давида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'А Јонатан стриц Давидов бијаше саветник, мудар човјек и књижевник; он и Јехило син Ахмонијев бијаху са синовима царевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'И Ахитофел бијаше савјетник царев, и Хусај Архијанин пријатељ царев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'А послије Ахитофела бијаше Јодај син Венајин и Авијатар, а војвода царев бјеше Јоав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'И Давид сабра у Јерусалим све поглаваре Израиљеве, поглаваре племенске и поглаваре од редова који служаху цару, и тисућнике и стотинике, и који бијаху над свијем благом и стоком царевом, и синове своје и дворане и јунаке и све људе храбре,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'И уставши цар Давид на ноге рече: чујте ме, браћо моја и народе мој! ја бих наумио да сазидам дом гдје би почивао ковчег Господњи и да буде подножје ногама Бога нашега, и приправих што треба за зидање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Али ми Бог рече: нећеш сазидати дома имену мојему, јер си ратник и крв си прољевао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Али Господ Бог Израиљев изабра ме из свега дома оца мојега да будем цар над Израиљем довијека; јер Јуду изабра за вођа, и из дома Јудина дом оца мојега; и између синова оца мојега би му воља да мене постави царем над свијем Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'А тако између свијех синова мојих (јер много синова даде ми Господ) изабра Соломуна сина мојега да сједи на пријестолу царства Господњега над Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'И рече ми: Соломун син твој сазидаће мој дом и тријемове моје, јер њега изабрах себи за сина, и ја ћу му бити отац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'И утврдићу царство његово довијека, ако буде постојан да извршује заповијести моје и законе моје као данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Сада дакле пред свијем Израиљем, збором Господњим, и да чује Бог наш, кажем вам: држите и тражите све заповијести Господа Бога својега, да бисте држали ову добру земљу и оставили је у нашљедство синовима својим након себе довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'А ти, Соломуне сине, знај Бога оца својега, и служи му цијелим срцем и душом драговољном; јер сва срца испитује Господ и сваку помисао зна; ако га устражиш, наћи ћеш га; ако ли га оставиш, одбациће те засвагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Види сада да те је Господ изабрао да сазидаш дом за светињу; буди храбар и ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Тада предаде Давид Соломуну сину својему слику од тријема и од кућа његовијех, и од ризница и од соба и од клијети унутрашњих, и од мјеста за заклопац очишћења,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'И слику од свега што бјеше смислио за тријемове дома Господњега и за све клијети унаоколо и за ризницу дома Божијега и за ризницу од светијех ствари,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'И за редове свештеничке и Левитске и за сваки посао у служби у дому Господњем и за све посуђе у дому Господњем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Злато под мјеру за судове златне за сваку службу, и сребро за све судове сребрне под мјеру, за све судове за сваку службу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Под мјеру за свијетњаке златне и жишке златне, по тежини свакога свијетњака и жижака његовијех, и за свијетњаке сребрне по тежини свакога свијетњака и жижака његовијех, према потреби свакога свијетњака;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'И злата под мјеру за столове на којима ће стајати хљебови постављени, за сваки сто; и сребра за столове сребрне;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'И за виљушке и за котлиће и за здјеле злата чистога, и за златне чаше под мјеру, за сваку чашу, и за сребрне чаше сребра под мјеру за сваку;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'И за олтар кадиони чистога злата под мјеру; и слику од кола златнијех херувима, који ће раширивши крила заклањати ковчег завјета Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'То ми је све дошло писано руком Господњом да бих знао све како што треба урадити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'И тако рече Давид Соломуну сину својему: буди слободан и храбар, и ради, не бој се и не плаши се, јер ће Господ Бог, Бог мој, бити с тобом, неће те оставити нити ће отступити од тебе, докле не свршиш сав посао за службу у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'А ево редови свештенички и Левитски за сваку службу у дому Божијем; и имаш уза се за сваки посао људи драговољнијех и вјештијех сваком послу, и поглаваре и сав народ за сваку заповијест своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Потом рече Давид свему збору: једнога Соломуна сина мојега изабрао је Господ, младо дијете, а ово је велик посао; јер неће бити човјеку тај дом него Господу Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Ја колико могох приправих за дом Бога својега злата за ствари златне, сребра за сребрне, мједи за мједене, гвожђа за гвоздене, и дрва за дрвене, камења онихова, и камења за укивање, и камења за накит и за вез, и свакојакога драгога камења, и камена мрамора изобила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'И још из љубави к дому Бога својега, што имам свога злата и сребра, осим свега што сам приправио за дом свети, дајем и то на дом Бога својега:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'Три тисуће таланата злата Офирскога, и седам тисућа таланата чистога сребра, да се обложе зидови домовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Злато за златне ствари, а сребро за сребрне и за свако дјело руку умјетничких. А би ли јоште ко хтио драговољно што данас приложити Господу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Тада драговољно приложише кнезови домова отачких и кнезови племена Израиљевијех и тисућници и стотиници и кнезови над пословима царским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'И дадоше за службу у дому Божијем злата пет тисућа таланата и десет тисућа златица, и сребра десет тисућа таланата, и мједи осамнаест тисућа таланата, и гвожђа сто тисућа таланата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'И камења у кога год бијаше сви дадоше у ризницу дома Господњега у руке Јехила од синова Гирсоновијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'И радоваше се народ што драговољно прилагаху, јер прилагаху цијелијем срцем Господу; и цар се Давид радоваше веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Потом Давид благослови Господа пред свијем збором, и рече Давид: благословен си Господе Боже Израиља оца нашега од вијека до вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Твоје је, Господе, величанство и сила и слава и вјечност и част, и све што је на небу и на земљи; твоје је, Господе, царство, и ти си узвишен сврх свега поглавар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Богатство и слава од тебе је, и ти владаш свијем, и у твојој је руци моћ и сила, и у твојој је руци узвисити и укријепити све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Сада дакле, Боже наш, хвалимо те и славимо име твоје славно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Јер ко сам ја и шта је мој народ да би смо могли оволико принијети теби драговољно? јер је од тебе све, и из твојих руку примивши дасмо ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Јер смо дошљаци пред тобом и гости као сви оци наши; дани су наши на земљи као сјен и нема стајања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Господе Боже наш, све ово благо што ти приправисмо за грађење дома имену твојему светоме, из твоје је руке, и све је твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Али знам, Боже мој, да ти испитујеш срца и што је право хоћеш; ја правијем срцем драговољно принесох све ово, и с радошћу видјех народ твој који је овдје како ти драговољно приноси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Господе Боже Аврама, Исака и Израиља, отаца наших, сачувај довијека ову вољу и помисао срдачну народа својега, и управљај срце њихово к себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'И Соломуну сину мојему подај срце право да би држао заповијести твоје, свједочанства твоја и уредбе твоје, и да би отворио све и да би сазидао двор овај за који сам приправио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Потом рече Давид свему збору: благословите сада Господа Бога својега. И сав збор благослови Господа Бога отаца својих, и савивши се поклонише се Господу и цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'И принесоше Господу жртве, и принесоше Господу жртве паљенице сјутрадан: тисућу волова, тисућу овнова, тисућу јагањаца с наљевима њиховијем, и других жртава много за сав народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'И једоше и пише пред Господом онај дан веселећи се веома. И поставише другом Соломуна сина Давидова царем, и помазаше га Господу за вођа а Садока за свештеника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'И тако сједе Соломун на пријесто Господњи да царује мјесто Давида оца својега, и бијаше срећан, и слушаше га сав Израиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'И сви кнезови и јунаци и сви синови цара Давида дадоше руке да ће бити покорни цару Соломуну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'И Господ узвиси веома Соломуна пред свијем Израиљем и даде му славу царску какве ниједан цар прије њега није имао у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Тако Давид син Јесејев царова над свијем Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'А времена за које царова над Израиљем бијаше четрдесет година: а у Хеврону царова седам година, а у Јерусалиму царова тридесет и три године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'И умрије у доброј старости, сит живота, богатства и славе; и зацари се Соломун син његов на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'А дјела цара Давида прва и пошљедња ено су записана у књизи Самуила видиоца и у књизи Натана пророка и у књизи Гада видиоца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Са свијем царовањем његовијем и силом његовом и с временима која прођоше преко њега и Израиља и свијех царевина земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'И Соломун син Давидов утврди се у царству свом, и Господ Бог његов бјеше с њим, и узвиси га веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'И Соломун рече свему Израиљу, тисућницима и стотиницима и судијама и свијем кнезовима свега Израиља, главарима домова отачких,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'Те отидоше, Соломун и сав збор с њим, на висину која бијаше у Гаваону; јер ондје бијаше шатор од састанка Божијега, који начини Мојсије слуга Господњи у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'А ковчег Божији бјеше пренио Давид из Киријат-Јарима на мјесто које му спреми Давид; јер му разапе шатор у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'И олтар мједени који начини Веселеило, син Урија сина Орова, бијаше ондје пред шатором Господњим. И потражи га Соломун и сав збор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'И принесе Соломун ондје пред Господом на олтару мједеном, који бијаше пред шатором од састанка, принесе на њему тисућу жртава паљеница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Ону ноћ јави се Бог Соломуну и рече му: ишти шта хоћеш да ти дам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'А Соломун рече Богу: ти си учинио велику милост Давиду оцу мојему и поставио си мене царем на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Нека дакле, Господе Боже, буде тврда ријеч твоја, коју си рекао Давиду оцу мојему, јер си ме поставио царем над народом којега има много као праха на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Зато дај ми мудрост и знање да полазим пред народом овијем и долазим, јер ко може судити народу твојему тако великому?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Тада рече Бог Соломуну: што ти је то у срцу, а не иштеш богатства, блага ни славе, ни душа ненавидника својих, нити иштеш дуга живота, него иштеш мудрости и знања да можеш судити народу мојему, над којим те поставих царем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'Мудрост и знање даје ти се; а даћу ти и богатства и славе, какове нијесу имали цареви прије тебе нити ће послије тебе имати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'И врати се Соломун с висине која бијаше у Гаваону испред шатора од састанка у Јерусалим, и цароваше над Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'И накупи Соломун кола и коњика, и имаше тисућу и четири стотине кола и дванаест тисућа коњика, које намјести по градовима гдје му бијаху кола и код себе у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'И учини цар те бијаше у Јерусалиму сребра и злата као камена, а кедровијех дрва као дивљих смокава које расту по пољу, тако много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'И довођаху Соломуну коње из Мисира и свакојаки трг, јер трговци цареви узимаху свакојаки трг за цијену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'И одлажаху, те догоњаху из Мисира кола по шест стотина сикала сребра, а коње по сто педесет; и тако сви цареви Хетејски и цареви Сирски преко њих добиваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'И науми Соломун да зида дом имену Господњему и дом царски себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'И одброји Соломун седамдесет тисућа носилаца и осамдесет тисућа који ће тесати у гори, и три тисуће и шест стотина настојника над њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'И посла Соломун ка Хираму цару Тирском и поручи му: како је чинио Давиду оцу мојему и слао му дрва кедровијех да зида себи кућу гдје ће сједети, учини тако и мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Ево рад сам зидати дом имену Господа Бога својега да му га посветим да се кади пред њим кадом мириснијем и да се постављају хљебови вазда и да се приносе жртве паљенице јутром и вечером, и у суботе и на младине и на празнике Господа Бога нашега, што треба да бива у Израиљу довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'А дом који ћу зидати биће велик, јер је Бог наш већи од свијех богова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'А ко би могао њему сазидати дом кад га небо и небеса над небесима не могу обухватити? и ко сам ја да му сазидам дом? него само да се кади пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Тако сада пошљи ми човјека вјешта, који умије радити од злата и од сребра и од мједи и од гвожђа и од скерлета и од црвца и од порфире, и који зна резати, да ради с умјетницима које имам код себе у Јудеји и у Јерусалиму, које је добавио Давид отац мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'И пошљи ми дрва кедровијех и јеловијех и алмугима с Ливана, јер знам да слуге твоје умију сјећи дрва Ливанска; а ево слуге ће моје бити с твојим слугама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Да ми приправе много дрва, јер дом што ћу зидати биће велик и диван.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'А ево, посленицима који ће сјећи дрво, слугама твојим, даћу пшенице овршене двадесет тисућа кора, и двадесет тисућа кора јечма, и вина двадесет тисућа вата, и уља двадесет тисућа вата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'И одговори Хирам цар Тирски у књизи коју посла Соломуну: што Господ љуби свој народ зато те постави царем над њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'И говораше Хирам: благословен да је Господ Бог Израиљев, који је створио небо и земљу, што је дао цару Давиду сина мудра, паметна и разумна, који ће сазидати дом Господу и царски дом себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Шаљем ти дакле човјека вјешта и разумна, Хирама Авива,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Сина једне жене између кћери Дановијех, којему је отац био Тирац; он умије радити од злата и од сребра, од мједи, од гвожђа, од камена и од дрвета, од скерлета, и од порфире, и од танкога платна и од црвца, и резати свашта, и измислити свашта вјешто што му се да, нека ради с твојим умјетницима и с умјетницима господара мојега Давида оца твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Нека дакле пшеницу и јечам, уље и вино, што је рекао господар мој, пошље слугама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'А ми ћемо насјећи дрва на Ливану колико ти год треба, и спустићемо их у сплавовима морем у Јопу, а ти их оданде вози у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Тада Соломун изброји све иностранце који бијаху у земљи Израиљевој послије бројања кад их изброји Давид отац његов, и нађе их се сто и педесет и три тисуће и шест стотина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'И одреди од њих седамдесет тисућа који ће носити, и осамдесет тисућа који ће тесати у планини, а три тисуће и шест стотина настојника да настоје да ради народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'И поче Соломун зидати дом Господњи у Јерусалиму на брду Морији, које би показано Давиду оцу његову на мјесту које бјеше приправио Давид, на гумну Орнана Јевусејина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'И поче зидати другога дана другога мјесеца четврте године царовања својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'А овако заснова Соломун да зида дом Божији: у дужину шездесет лаката по старој мјери, а у ширину двадесет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'А тријем који бијаше пред дужином уз ширину дома имаше двадесет лаката, а у висину сто и двадесет; и обложи га изнутра чистијем златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'А дом велики обложи дрветом јеловијем, потом га обложи чистијем златом, и озго начини палме и ланце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'И обложи дом камењем драгим да је накићен, а злато бијаше Парвајимско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Обложи златом дом, греде, прагове и зидове и врата, и изреза херувиме по зидовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'И начини дом за светињу над светињама, дуг уз ширину дома двадесет лаката, и широк двадесет лаката и обложи га чистијем златом, којега отиде до шест стотина таланата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'А на клине даде педесет сикала злата; и клијети обложи златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'И начини у дому светиње над светињама два херувима, направе умјетничке, и обложи их златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'И крила тијех херувима имаху у дужину двадесет лаката: једно крило бијаше од пет лаката, и тицаше у зид од дома и друго крило бијаше од пет лаката, и тицаше у крило другога херувима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Тако и другога херувима крило бијаше од пет лаката, и тицаше у зид од дома, и друго му крило бијаше од пет лаката и састављаше се с крилом другога херувима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Крила тијем херувимима бијаху раширена на двадесет лаката, а они стајаху на ногама својим, лицем окренутим у дом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'И начини завјес од порфире, од скерлета, од црвца и од танкога платна, и по њему начини херувиме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'И начини пред домом два ступа, у висину од тридесет и пет лаката, и оглавља озго на сваком од пет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'И начини ланце као у светињи, и метну их на врх ступова, и начини сто шипака, и метну их међу ланце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'И постави ступове пред црквом, један с десне стране а други с лијеве, и десни назва Јахин а лијеви Воас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'И начини олтар од мједи, двадесет лаката дуг и двадесет лаката широк, а десет лаката висок.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'И сали море, десет лаката бјеше му од једнога краја до другога, округло унаоколо, пет лаката високо; а унаоколо му бјеше тридесет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'А под њим бијаху ликови воловски, који стајаху свуда унаоколо, по десет на једном лакту, те окружаваху море: два реда бијаше тијех волова, саливенијех с морем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'И стајаше море на дванаест волова, три гледаху на сјевер, а три гледаху на запад, а три гледаху на југ, а три гледаху на исток, а море стајаше озго на њима, и задња страна свијех њих бијаше унутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Дебљина му бијаше с подланице, а крај му бијаше као крај у чаше, као цвијет љиљанов, а примаше три тисуће вата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'И начини десет умиваоница, и метну их пет с десне стране, а пет с лијеве, да се у њима пере, што год требаше за жртву паљеницу, у њима праху; а море бијаше за свештенике да се у њима умивају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'И начини десет свијетњака од злата, облика каки им требаше, и намјести их у цркви, пет с десне стране а пет с лијеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'И начини десет столова, и намјести их у цркви, пет с десне стране а пет с лијеве; и начини стотину чаша од злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'И начини тријем свештенички и велики тријем, и врата на тријему, и окова врата у мјед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'А море метну на десну страну к истоку с југа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Још начини Хирам лонце и лопате и котлиће, и сврши Хирам посао, који ради цару Соломуну за дом Божији:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'Два ступа, и два оглавља округла наврх ступова, и плетенице двије да покривају два оглавља наврх ступова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'И четири стотине шипака на двије плетенице, два реда шипака на свакој плетеници, да покривају два оглавља наврх ступова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'И начини подножја, и умиваонице начини на подножја;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Једно море, и дванаест волова под њим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'И лонце и лопате и виљушке, и све справе за њих начини Хирам Авив цару Соломуну за дом Господњи од углађене мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'То је цар саљевао у равни Јорданској у земљи иловачи између Сохота и Саридате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'И начини Солонун свега овога посуђа врло много, да се није тражило мјера мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Начини Соломун и све друге справе за дом Божји, и олтар од злата и столове на којима стајаху хљебови постављени;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'И свијетњаке са жишцима њиховијем од чистога злата да горе пред светињом над светињама по обичају;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'И цвијетове и жишке и усекаче од злата; а то злато бијаше веома добро;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'И ножеве и котлиће и кадионице и клијешта од чистога злата; и врата од дома, врата унутрашња од светиње над светињама, и врата од дома на која се улажаше у цркву, бијаху од злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'И тако се сврши сав посао што уради Соломун за дом Господњи; и унесе Соломун што бјеше посветио Давид отац његов, и сребро и злато и судове, и остави у ризницу дома Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Тада сабра Соломун старјешине Израиљеве и све главаре племенске, кнезове домова отачких синова Израиљевих у Јерусалим да пренесу ковчег завјета Господњега из града Давидова, које је Сион.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'И скупише се к цару сви људи Израиљеви на празник који бива седмога мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'И кад дођоше све старјешине Израиљеве, узеше Левити ковчег.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'И пренесоше ковчег и шатор од састанка и све судове свете што бијаху у шатору, пренесоше свештеници и Левити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'А цар Соломун и сав збор Израиљски који се сабра к њему принесоше к њему на жртву оваца и говеда толико да се не могаше од мноштва ни избројити ни прорачунати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'И унесоше свештеници ковчег завјета Господњега на мјесто његово, у унутрашњи дом, у светињу над светињама, под крила херувимима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Јер херувимима бијаху раширена крила над мјестом гдје ће стајати ковчег и заклањаху херувими ковчег и полуге његове озго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'И повукоше му полуге тако да им се крајеви виђаху од ковчега на предњој страни светиње над светињама, али се напоље не виђаху, и осташе ондје до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'У ковчегу не бјеше ништа осим двије плоче које метну Мојсије на Хориву кад Господ учини завјет са синовима Израиљевијем пошто изидоше из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'А кад свештеници изидоше из светиње, јер свештеници који се нађоше освешташе се не пазећи на ред,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'И Левити пјевачи сви, који бијаху уз Асафа и Емана и Једутуна, и синови њихови и браћа њихова, обучени у танко платно, стајаху с кимвалима и псалтирима и с гуслама с источне стране олтару, и с њима сто и двадесет свештеника, који трубљаху у трубе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'И кад они који трубљаху у трубе и који пјеваху, сложно једнијем гласом хваљаху и слављаху Господа, и подизаху глас уз трубе и кимвале и гусле, хвалећи Господа да је добар, да је довијека милост његова, тада се напуни облака дом Господњи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Те не могаху свештеници стајати да служе од облака, јер се славе Господње напуни дом Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Тада рече Соломун: Господ је рекао да ће наставати у мраку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'А ја сазидах дом теби за стан и мјесто да у њему наставаш довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'И окренувши се лицем својим цар благослови сав збор Израиљев, а сав збор Израиљев стајаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'И рече: благословен да је Господ Бог Израиљев, који је говорио својим устима Давиду оцу мојему и испунио руком својом, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Од онога дана кад изведох народ свој из земље Мисирске, не изабрах града међу свијем племенима Израиљевијем да се сазида дом гдје би било име моје, нити изабрах човјека који би био вођ народу мојему Израиљу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Него изабрах Јерусалим да у њему буде име моје, и изабрах Давида да буде над народом мојим Израиљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'И науми Давид отац мој да сазида дом имену Господа Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Али Господ рече Давиду оцу мојему: што си наумио сазидати дом имену мојему, добро си учинио што си то наумио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Али нећеш ти сазидати тога дома, него син твој који ће изаћи из бедара твојих, он ће сазидати дом имену мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'И тако испуни Господ ријеч своју коју је рекао, јер устах на мјесто оца својега Давида и сједох на пријесто Израиљев, као што је рекао Господ, и сазидах овај дом имену Господа Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'И намјестих овдје ковчег, у ком је завјет Господњи што је учинио синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'По том стаде Соломун пред олтар Господњи пред свијем збором Израиљевијем, и подиже руке своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'А бјеше начинио Соломун подножје од мједи и метнуо га насред тријема, пет лаката дуго и пет лаката широко, а три лакта високо; па стаде на њ, и клече на кољена пред свијем збором Израиљевијем, и подиже руке своје к небу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'И рече: Господе Боже Израиљев! нема Бога такога какав си ти ни на небу ни на земљи, који чуваш завјет и милост слугама, који ходе пред тобом свијем срцем својим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Који си испунио слузи својему Давиду оцу мојему што си му рекао; што си устима својим рекао то си руком својом испунио, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Сада дакле, Господе Боже Израиљев, држи Давиду оцу мојему што си му рекао говорећи: неће ти нестати човјека испред мене који би сједио на пријестолу Израиљеву, само ако ушчувају синови твоји пут свој ходећи по закону мојему, као што си ти ходио преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Сада дакле, Господе Боже Израиљев, нека се потврди ријеч твоја коју си рекао слузи својему Давиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Али хоће ли доиста Бог становати на земљи? Ето, небо, и небеса над небесима не могу те обухватити, акамоли овај дом што га сазидах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Али погледај на молитву слуге својега и на молбу његову, Господе Боже мој, чуј вику и молитву којом ти се данас моли слуга твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Да буду очи твоје отворене над домом овијем дању и ноћу, над овијем мјестом, гдје си рекао да ћеш намјестити име своје, да чујеш молитву којом ће се молити слуга твој на овом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Чуј молбе слуге својега и народа својега Израиља, којима ће се молити на овом мјесту, чуј с мјеста гдје станујеш, с неба, чуј и смилуј се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Кад ко згријеши ближњему својему, те му се да заклетва, да се закуне, и заклетва дође пред твој олтар у овом дому,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Ти чуј с неба, и учини, и суди слугама својим плаћајући кривцу и дјела његова обраћајући на његову главу, а правога правдајући и плаћајући му по правди његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'И кад се разбије пред непријатељем народ твој Израиљ зато што ти згријеше, па се обрате и даду славу имену твојему и помоле ти се и замоле те у овом дому,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Ти чуј с неба, и опрости гријех народу својему Израиљу, и доведи их опет у земљу, коју си дао њима и оцима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Кад се затвори небо, те не буде дажда зато што згријеше теби, па ти се замоле на овом мјесту и даду славу имену твојему и од гријеха се својега обрате, кад их намучиш,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Ти чуј с неба, и опрости гријех слугама својим и народу својему Израиљу показав им пут добри којим ће ходити, и пусти дажд на земљу своју коју си дао народу својему у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Кад буде глад у земљи, кад буде помор, суша или медљика, скакавци или гусјенице кад буду, или га стегне непријатељ његов у земљи његовој властитој, или како год зло и кака год болест,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'Сваку молбу и сваку молитву, која буде од кога год човјека или од свега народа твојега Израиља, ко позна муку своју и бол свој и подигне руке своје у овом дому,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Ти чуј с неба, из стана својега, и опрости и подај свакоме по путовима његовијем, што знаш у срцу његову, јер ти сам знаш срца синова човјечијих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Да те се боје ходећи путовима твојим докле су год живи на земљи, коју си дао оцима нашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'И иностранац који није од народа твојега Израиља, него дође из далеке земље имена ради твојега великога и руке твоје крјепке и мишице твоје подигнуте, кад дође и помоли се у овом дому,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Ти чуј с неба, из стана својега, и учини све за што повиче к теби онај странац, да би познали сви народи на земљи име твоје и бојали се тебе као народ твој Израиљ, и да би знали да је име твоје призвано над овај дом, који сазидах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Кад народ твој изиде на војску на непријатеље своје путем којим га пошљеш, и помоле ти се окренувши се ка граду овому, који си изабрао, и к овому дому, који сам сазидао имену твојему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Чуј с неба молбу њихову и молитву њихову, и добави им правицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Кад ти згријеше, јер нема човјека који не гријеши, и разгњевивши се на њих даш их непријатељима, те их заробе и и одведу у земљу даљну или која је близу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'Ако се дозову у земљи у коју буду одведени у ропство, и обрате се и стану ти се молити у земљи ропства својега, и реку: сагријешисмо и зло учинисмо и скривисмо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'И тако се обрате к теби свијем срцем својим и свом душом својом у земљи ропства својега, у коју буду одведени у ропство, и помоле ти се окренувши се к земљи својој, коју си дао оцима њиховијем, и ка граду, који си изабрао, и к дому, који сам сазидао имену твојему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Тада чуј с неба, из стана својега, молбу њихову и молитву њихову, и добави им правицу, и опрости народу својему што ти буду згријешили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Тако, Боже мој, нека буду очи твоје отворене и уши твоје пригнуте на молбу у овом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'И тако, стани, Господе Боже, на почивалишту својем, ти и ковчег силе твоје; свештеници твоји, Господе Боже, нека се обуку у спасење, и свеци твоји нека се радују добру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Господе Боже, немој одвратити лица својега од помазаника својега; опомињи се милости обећане Давиду слузи твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'А кад сврши Соломун молитву, сиђе огањ с неба и спали жртву паљеницу и друге жртве, и славе Господње напуни се дом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'Те не могаху свештеници ући у дом Господњи, јер се славе Господње напуни дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'А сви синови Израиљеви видећи гдје сиђе огањ и слава Господња на дом савише се лицем к земљи до пода и поклонише се и хвалише Господа, јер је добар, јер је довијека милост његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'И цар и сав народ принесоше жртве пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'И принесе цар Соломун на жртву двадесет и двије тисуће волова и сто и двадесет тисућа оваца, и тако посветише дом Божји цар и сав народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'А свештеници стајаху на служби својој, и Левити са справама за пјесме Господње што их бјеше начинио цар Давид да хвале Господа, јер је довијека милост његова, пјесмом Давидовом коју им даде; а други свештеници трубљаху у трубе према њима, а сви синови Израиљеви стајаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'И посвети Соломун средину тријема који је пред домом Господњим, јер ондје принесе жртве паљенице и претилину од жртава захвалнијех, јер на мједеном олтару који начини Соломун, не могоше стати жртве паљенице и дари и претилина њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'У то вријеме светкова Соломун светковину седам дана и сав Израиљ с њим, сабор веома велик од Емата до потока Мисирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'И у осми дан празноваше празник, јер посвећивање олтара светковаше седам дана, и светковину седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'А двадесет трећега дана седмога мјесеца отпусти народ к шаторима њиховијем, и бијаху радосни и весели ради добра што учини Господ Давиду и Соломуну и Израиљу народу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'И сврши Соломун дом Господњи и дом царски, и би срећан у свему што бјеше наумио да начини у дому Господњем и у дому свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Потом јави се Господ Соломуну ноћу и рече му: услишио сам молбу твоју и изабрао сам то мјесто да ми буде дом за жртве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Ако затворим небо да не буде дажда, или ако заповједим скакавцима да попасу земљу, или ако пустим помор на народ свој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'И понизи се народ мој, на који је призвано име моје, и помоле се, и потраже лице моје, и поврати се од злијех путова својих, и ја ћу тада услишити с неба и опростићу им гријех њихов, и исцијелићу земљу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'И очи ће моје бити отворене и уши моје пригнуте к молитви с тога мјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Јер сада изабрах и посветих дом тај да буде име моје ту довијека; и биће ту очи моје и срце моје вазда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'А ти ако узидеш преда мном како је ишао Давид отац твој, творећи све што сам ти заповједио и држећи уредбе моје и законе моје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'Утврдићу пријесто царства твојега како сам обећао Давиду оцу твојему говорећи: неће ти нестати човјека који би владао у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Али ако се одвратите, и оставите уредбе моје и заповјести моје, које сам вам дао, и отидете и станете служити другим боговима и клањати им се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Тада ћу их истријебити из земље своје коју сам им дао, и овај дом који сам посветио имену својему одбацићу од себе, и учинићу од њега причу и потсмијех међу свијем народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'И дом овај колико је славан, ко год прође мимо њ, зачудиће му се и рећи ће: зашто учини ово Господ од ове земље и од овога дома?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'И одговориће се: јер оставише Господа Бога отаца својих, који их изведе из земље Мисирске, и узеше друге богове и клањаше им се и служише им, зато пусти на њих све ово зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'А кад прође двадесет година, у које сазида Соломун дом Господњи и дом свој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Погради Соломун градове, које му даде Хирам, и насели онуда синове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Потом отиде Соломун на Емат Совски, и освоји га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'И сазида Тадмор у пустињи и све градове за житнице сазида у Емату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Сазида и Вет-Орон горњи и Вет-Орон доњи, тврде градове, са зидовима, вратима и пријеворницама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'И Валат и све градове у којима Соломун имаше житнице, и градове у којима му бијаху кола, и градове у којима бијаху коњици, и што год Соломуну би воља зидати у Јерусалиму и на Ливану и у свој земљи царства својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'И сав народ што бјеше остао од Хетеја и од Амореја и од Ферезеја и од Јевеја и од Јевусеја, који не бијаху од Израиља,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Од синова њиховијех који бјеху остали иза њих у земљи, којих не потрше синови Израиљеви, њих нагна Соломун да плаћају данак до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'А од синова Израиљевијех, којих не учини Соломун робовима за свој посао, него бијаху војници и поглавари над војводама његовијем, и заповједници над колима и коњицима његовијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Од њих бијаше главнијех настојника, које имаше цар Соломун, двјеста и педесет, који управљаху народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'И кћер фараонову пресели Соломун из града Давидова у дом који јој сазида, јер рече: неће сједјети жена моја у дому Давида цара Израиљева, јер је свет што је дошао у њ ковчег Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Тада приношаше Соломун жртве паљенице Господу на олтару Господњем који начини пред тријемом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Што требаше од дана на дан приносити по заповијести Мојсијевој, у суботе и на младине и на празнике, три пута у години, на празник пријеснијех хљебова и на празник седмица и на празник сјеница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'И постави по наредби Давида оца својега редове свештеничке према служби њиховој, и Левитске према дужности њиховој, да хвале Бога и служе пред свештеницима како треба сваки дан, и вратаре по редовима њиховијем како треба над сваким вратима; јер така бијаше заповијест Давида човјека Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'И не отступише од заповијести цареве за свештенике и Левите ни у чем, ни за ризнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Тако се сврши све дјело Соломуново од онога дана кад би основан дом Господњи па докле га не доврши, и готов би дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Тада отиде Соломун у Есион-Гавер и у Елот на бријегу морском у земљи Едомској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'А Хирам посла му по својим слугама лађе и слуге вјеште мору, и отидоше са слугама Соломуновијем у Офир и узеше оданде четири стотине и педесет таланата злата и донесоше цару Соломуну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'А царица Савска чу глас о Соломуну, па дође у Јерусалим да искуша Соломуна загонеткама са силном пратњом и с камилама које ношаху мириса и злата врло много и драгог камења; и дошавши к Соломуну говори с њим о свему што јој бјеше у срцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'И Соломун јој одговори на све ријечи њезине; не бјеше од цара сакривено ништа да јој не би одговорио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'А кад царица Савска видје мудрост Соломунову и дом који бјеше сазидао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'И јела на столу његову, и станове слуга његовијех и дворбу дворана његовијех и одијело њихово, и пехарнике његове, и њихово одијело, и њихове жртве паљенице које приношаху у дому Господњем, она дође изван себе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Па рече цару: истина је све што сам чула у својој земљи о стварима твојим и о мудрости твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Али не хтјех вјеровати што говораху докле не дођем и видим својим очима; а гле, ни пола ми није казано о великој мудрости твојој; надвисио си глас који сам слушала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Благо људима твојим и благо свијем слугама твојим, које једнако стоје пред тобом и слушају мудрост твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Да је благословен Господ Бог твој, којему си омилио, те те посади на пријесто свој да царујеш мјесто Господа Бога својега; јер Бог љуби Израиља да би га утврдио довијека, зато им постави тебе царем да судиш и дијелиш правицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Потом даде цару сто и двадесет таланата злата и врло много мириса и драгога камења; нигда више не би таквих мириса какве даде царица Савска цару Соломуну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'И слуге Хирамове и слуге Соломунове које донесоше злата из Офира, довезоше дрвета алмугима и драгога камења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'И начини цар од тога дрвета алмугима пут у дом Господњи и у дом царев, и гусле и псалтире за пјеваче; нигда се прије нијесу видјеле таке ствари у земљи Јудиној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'А цар Соломун даде царици Савској што год зажеље и заиска осим уздарја за оно што бјеше донијела цару. Потом она отиде и врати се у земљу своју са слугама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'А злата што дохођаше Соломуну сваке године бјеше шест стотина и шездесет и шест таланата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Осим онога што доношаху трговци и они који продаваху мирисе; и сви цареви арапски и главари земаљски доношаху Соломуну злато и сребро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'И начини цар Соломун двјеста штитова од кованога злата, шест стотина сикала кованога злата дајући на један штит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'И три стотине малијех штитова од кованога злата, дајући триста сикала злата на један штитић. и остави их цар у дому од шуме Ливанске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'И начини цар велик пријесто од слонове кости, и обложи га чистијем златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'А бијаше шест басамака у пријестола, и подножје од злата састављено с пријестолом, и ручице с обје стране сједишта, и два лава стајаху покрај ручица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'И дванаест лавова стајаше на шест басамака отуд и одовуд. Не би таки начињен ни у којем царству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'И сви судови из којих пијаше цар Соломун бијаху златни, и сви судови у дому од шуме Ливанске бијаху од чистога злата; од сребра не бјеше ништа; сребро бјеше ништа за времена Соломунова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Јер цареве лађе хођаху у Тарсис са слугама Хирамовијем: једанпут у три године враћаху се лађе Тарсиске доносећи злато и сребро, слонове кости и мајмуне и пауне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Тако цар Соломун бијаше већи од свијех царева земаљских богатством и мудрошћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'И сви цареви земаљски тражаху да виде Соломуна да чују мудрост његову, коју му даде Господ у срце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'И доношаху му сви даре, судове сребрне и судове златне, и хаљине и оружје и мирисе, коње и мазге сваке године,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Тако да имаше Соломун четири тисуће стаја за коње и кола, и дванаест тисућа коњика, које намјести по градовима гдје му бијаху кола и код себе у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'И владаше над свијем царевима од ријеке до земље Филистејске и до међе Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'И учини цар, те у Јерусалиму бјеше сребра као камена, а кедровијех дрва као дивљих смокава које расту по пољу, тако много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'И довођаху Соломуну коње из Мисира и из свијех земаља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'А остала дјела Соломунова прва и пошљедња нијесу ли записана у књизи Натана пророка и у пророчанству Ахије Силомљанина и у утвари Ида видиоца о Јеровоаму сину Наватову?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'А царова Соломун у Јерусалиму над свијем Израиљем четрдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'И почину Соломун код отаца својих, и погребоше га у граду Давида оца његова; а на његово мјесто зацари се Ровоам син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Тада отиде Ровоам у Сихем, јер се ондје скупи сав Израиљ да га зацаре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'А кад чу Јеровоам син Наватов, који бијаше у Мисиру побјегав онамо од цара Соломуна, врати се Јеровоам из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Јер послаше, те га дозваше; и дође Јеровоам и сав Израиљ и рекоше Ровоаму говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Твој је отац метнуо на нас тежак јарам; него ти сада олакшај љуту службу оца својега и тешки јарам који је метнуо на нас па ћемо ти служити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'А он им рече: до три дана дођите опет к мени. и народ отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Тада цар Ровоам учини вијеће са старцима који стајаше пред Соломуном оцем његовијем док бијаше жив, и рече: како свјетујете да одговорим народу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'А они му рекоше говорећи: ако се удобриш народу и угодиш им и одговориш им лијепим ријечима, они ће ти бити слуге свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Али он остави свјет што га свјетоваше старци, и учини вијеће с младићима који одрастоше с њим и који стајаху пред њим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'И рече им: шта ви свјетујете да одговоримо народу који ми рекоше говорећи: олакшај јарам који је метнуо на нас твој отац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Тада му одговорише младићи који одрастоше с њим, и рекоше: овако кажи народу што ти рече: отац је твој метнуо на нас тежак јарам, него ти нам олакшај; овако им реци: мој мали прст дебљи је од бедара оца мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Отац је мој метнуо на вас тежак јарам, а ја ћу још дометнути на ваш јарам; отац вас је мој шибао бичевима, а ја ћу вас шибати бодљивијем бичевима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'А трећи дан дође Јеровоам и сав народ к Ровоаму како им бјеше казао цар рекав: дођите опет к мени до три дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'И цар им одговори оштро, јер остави цар Ровоам свјет старачки,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'И одговори им како га свјетоваше младићи, говорећи: мој је отац метнуо на вас тежак јарам, а ја ћу још дометнути на њ; отац вас је мој шибао бичевима, а ја ћу бодљивијем бичевима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'И цар се оглуши народа, јер Бог бјеше тако уредио да би потврдио Господ ријеч своју што је рекао преко Ахије Силомљанина Јеровоаму сину Наватову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'А кад видје сав Израиљ да их се цар оглуши, одговори народ цару говорећи: какав дио ми имамо с Давидом? немамо нашљедства са сином Јесејевим. Свак у свој шатор, Израиљу! А ти, Давиде, сад гледај своју кућу. Тако отиде сав Израиљ у шаторе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Само над синовима Израиљевијем који живљаху по градовима Јудинијем зацари се Ровоам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'И цар Ровоам посла Адорама који бијаше над данком, али га синови Израиљеви засуше камењем, те погибе. Тада цар Ровоам брже сједе на кола, те побјеже у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Тако отпаде Израиљ од дома Давидова до данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'А кад дође Ровоам у Јерусалим, сазва дом Јудин и Венијаминов, сто и осамдесет тисућа одабранијех војника, да завојште на Израиља да поврате царство Ровоаму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Али дође ријеч Господња Семаји човјеку Божијему говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Кажи Ровоаму сину Соломунову цару Јудину и свијем синовима Израиљевијем од Јуде и Венијамина, и реци:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Овако вели Господ: не идите и не бијте се с браћом својом, вратите се свак к својој кући, јер сам ја наредио да тако буде. И они послушаше ријеч Господњу и вратише се и не идоше на Јеровоама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'И Ровоам сједе у Јерусалиму, и сазида тврде градове у земљи Јудиној;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Сазида Витлејем и Итам и Текују,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'И Вет-Сур и Сохот и Одолам,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'И Гат и Марису и Зиф,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'И Адораим и Ахис и Азику,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'И Сарају и Ејалон и Хеврон који је у земљи Јудиној и Венијаминовој тврди градови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'А кад утврди те градове, намјести у њима заповједнике, и стаје за жито и за уље и за вино,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'И у сваком граду штитова и копаља, и утврди их јако. Тако његов бијаше Јуда и Венијамин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'И свештеници и Левити, који бијаху по свему Израиљу, сабраше се к њему из свијех крајева својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Јер оставише Левити подграђа своја и достојања своја, и отидоше у Јудејску и у Јерусалим, јер их отјера Јеровоам и синови његови да не врше службе свештеничке Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'И постави себи свештенике за висине и за ђаволе и за теоце, које начини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'А за њима из свијех племена Израиљевијех који управише срце своје да траже Господа Бога Израиљева, дођоше и Јерусалим да принесу жртву Господу Богу отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'И тако утврдише царство Јудино, и укријепише Ровоама сина Соломунова за три године, јер за те три године хођаху путем Давидовијем и Соломуновијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'А Ровоам се ожени Маелетом кћерју Јеримота сина Давидова и Авихаилом кћерју Есијава сина Јесејева,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Која му роди синове: Јеуса и Самарију и Зама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'А послије ње ожени се Махом кћерју Авесаломовом, која му роди Авију и Атаја и Зиву и Селомита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'А љубљаше Ровоам Маху кћер Авесаломову већма од свијех жена својих и иноча својих; јер имаше осамнаест жена и шездесет иноча, и роди двадесет и осам синова и шездесет кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'И Ровоам постави Авију сина Машина поглаваром и кнезом над браћом његовом, јер га шћаше поставити царем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'И мудро радећи растури све синове своје по свијем крајевима Јудинијем и Венијаминовијем, по свијем тврдијем градовима, и даде им хране изобила, и доведе им много жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'А кад Ровоам утврди царство и кад осили, остави закон Господњи и сав Израиљ с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'А пете године царовања Ровоамова дође Сисак цар Мисирски на Јерусалим, јер згријешише Господу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'С тисућу и двије стотине кола и са шездесет тисућа коњика, и не бјеше броја народу који дође с њим из Мисира, Лувејима, Сухејима и Хусејима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'И узе тврде градове Јудине и дође до Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Тада дође Семаја пророк к Ровоаму и кнезовима Јудинијем, који се бијаху скупили у Јерусалим од Сисака, и рече им: овако вели Господ: ви остависте мене, зато и ја остављам вас у руке Сисаку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Тада се понизише кнезови Израиљеви и цар и рекоше: праведан је Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'А кад их видје Господ гдје се понизише, дође ријеч Господња Семаји говорећи: понизише се, нећу их потрти, него ћу им сада дати избављење, и неће се излити јарост моја на Јерусалим преко Сисака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Него ће му бити слуге да познаду шта је мени служити, шта ли служити царствима земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'И тако дође Сисак цар Мисирски у Јерусалим и узе благо дома Господњега и благо дома царева, све то узе; узе и штитове златне, које бјеше начинио Соломун;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'И на њихово мјесто начини цар Ровоам штитове од мједи, и предаде их старјешинама над стражарима који чувају врата домова царева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'И кад иђаше цар у дом Господњи долажаху стражари и ношаху их, а послије их опет остављаху у ризницу стражарску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Што се дакле понизи, одврати се од њега гњев Господњи, и не затр га сасвијем; јер још у Јуди бјеше добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'И утврди се цар Ровоам у Јерусалиму, и царова; јер бијаше Ровоаму четрдесет и једна година кад се зацари, и седамдесет година царова у Јерусалиму граду, који изабра Господ између свијех племена Израиљевијех да ондје намјести име своје. А матери његовој бјеше име Нама, Амонка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Али он чињаше зло, јер не управи срца својега да тражи Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Али дјела Ровоамова прва и пошљедња нијесу ли записана у књизи пророка Семаје и видиоца Ида, гдје се казују кољена а и ратови који бијаху једнако међу Ровоамом и Јеровоамом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'И почину Ровоам код отаца својих, и би погребен у граду Давидову; а на његово се мјесто зацари Авија син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Године осамнаесте царовања Јеровоамова зацари се Авија над Јудом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Три године царова у Јерусалиму. Матери му бјеше име Махаја, кћи Урилова из Гаваје. А бијаше рат између Авије и Јеровоама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'И Авија изиде на бој с храбром војском, четири стотине тисућа изабранијех војника; а Јеровоам уврста према њему војску, осам стотина тисућа изабранијех храбријех војника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'И стаде Авија наврх брда Семарајима у гори Јефремовој, и рече: чујте ме, Јеровоаме и сав Израиљу!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Не требаше ли вам знати да је Господ Бог Израиљев предао Давиду царство над Израиљем довијека, њему и синовима његовијем завјетом осољенијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Али уста Јеровоам син Наватов, слуга Соломуна сина Давидова, и одврже се од господара својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'И скупише се к њему људи празнови и неваљалци, и одапријеше се Ровоаму сину Соломунову, који бијаше дијете и страшљива срца, те им се не одаприје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Па ви сад велите да се опрете царству Господњему, које је у руку синова Давидовијех, јер вас је много и имате код себе златне теоце, које вам је начинио Јеровоам да су вам богови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Нијесте ли отјерали свештенике Господње синове Аронове и Левите? и начинили себи свештенике као народи по другим земљама? ко год дође да му се посвете руке с телетом и са седам овнова, постаје свештеник онима који нијесу богови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Али с нама је Господ Бог, нити смо га оставили, а свештеници који служе Господу јесу синови Аронови, и Левити раде свој посао;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'И пале Господу жртве паљенице свако јутро и свако вече, и каде мирисима, и хљебови постављени стоје на чистом столу, и пале се свако вече жишци на златном свијетњаку; јер држимо што је Господ Бог наш наредио, а ви га остависте,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Зато ево с нама је напријед Бог и свештеници његови и трубе гласне да трубе противу вас. Синови Израиљеви, не војујте на Господа Бога отаца својих, јер нећете бити срећни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Али Јеровоам заведе засједу да им зађу за леђа, и тако Јудејцима бијаху спријед једни а с леђа засједа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'И кад се обазреше Јудејци, а то бој и спријед и састраг, те повикаше ка Господу а свештеници затрубише у трубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'И народ Јудин опет повика, и кад викаше народ Јудин, разби Бог Јеровоама и свега Израиља пред Авијом и Јудом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'И побјегоше синови Израиљеви од Јуде, и даде их Бог њима у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'И поби их љуто Авија и народ његов, и паде од Израиља побијенијех пет стотина тисућа одабранијех људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Тако бише покорени синови Израиљеви у то вријеме, а синови Јудини осилише, јер се поуздаше у Господа Бога отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'И Авија потјера Јеровоама, и узе му градове Ветиљ и села његова, и Јесану и села њезина, и Ефрон и села његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'И Јеровоам се више не опорави за живота Авијина; и удари га Господ те умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'А Авија утврди се, и узе четрнаест жена, и роди двадесет два сина и шеснаест кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'А остала дјела Авијина и путови његови и бесједе његове записане су у књизи пророка Ида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'А кад почину Авија код отаца својих и погребоше га у граду Давидову, зацари се на његово мјесто Аса син његов. За његова времена почину земља десет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'И чињаше Аса што је добро и право пред Господом Богом његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Јер обори олтаре туђе и висине, и изломи ликове њихове и исјече лугове њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'И заповједи синовима Јудинијем да траже Господа Бога отаца својих и да извршују закон и заповијест његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Обори по свијем градовима Јудинијем висине и сунчане ликове, и почину царство за његова времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'И сазида тврде градове у земљи Јудиној, јер земља бијаше у миру, нити бјеше рата с њим онијех година, јер му Господ даде мир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'И рече Јуди: да сазидамо ове градове и да их опашемо зидом и кулама и вратима и пријеворницама, док је земља наша; јер тражимо Господа Бога својега, тражисмо га и даде нам мир отсвуда. И тако зидаше, и бише срећни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'И имаше Аса војске триста тисућа од Јуде са штитовима и копљима, и од Венијамина двјеста и осамдесет тисућа са штитовима и луковима. Сви бијаху храбри војници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'И изиде из њих Зара Етиопљанин с тисућу тисућа војске и с триста кола, и дође до Марисе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'И Аса изиде преда њ; и уврстише се војске у долини Сефати код Марисе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'И завапи Аса ка Господу Богу својему говорећи: Господе, теби је ништа помоћи множини или нејакому; помози нам, Господе Боже наш, јер се у те уздамо, и у твоје име дођосмо на ово мноштво. Господе, ти си Бог наш, не дај да може што на те човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'И разби Господ Етиопљане пред Асом и пред Јудом, и побјегоше Етиопљани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'И тјера их Аса и народ који бијаше с њим дори до Герара. и попадаше Етиопљани да их ни један не оста жив, јер се сатрше пред Господом и пред војском његовом; и они однесоше плијен велик веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'И побише све градове око Герара, јер дође на њих страх Господњи, и оплијенише све оне градове, јер бијаше у њима много плијена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Побише и по становима пастирским људе, и одведоше много оваца и камила; и вратише се у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Тада дух Божји дође на Азарију сина Одидова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Те отиде пред Асу и рече му: чујте ме, Асо и све племе Јудино и Венијаминово; Господ је с вама, јер сте ви с њим; и ако га устражите, наћи ћете га; ако ли га оставите, и он ће вас оставити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Дуго је Израиљ без правога Бога и без свештеника учитеља, и без закона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'А да су се у невољи својој обратили ка Господу Богу Израиљеву и тражили га, нашли би га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Али у ово вријеме не може се на миру одлазити ни долазити; јер је немир велик међу свијем становницима земаљским;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'И потиру народ један други, и градови један други, јер их Бог смете свакојаким невољама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Зато ви будите храбри и немојте да вам клону руке, јер има плата за ваш труд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'А кад чу Аса те ријечи и пророштво пророка Одида, охрабри се, и истријеби гадне богове из све земље Јудине и Венијаминове и из градова које бјеше узео у гори Јефремовој, и понови олтар Господњи који бијаше пред тријемом Господњим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Потом сазва све племе Јудино и Венијаминово и дошљаке који бијаху код њих од Јефрема и Манасије и Симеуна, јер их много пребјеже к њему из народа Израиљева кад видјеше да је Господ Бог његов с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'И искупише се у Јерусалим трећега мјесеца петнаесте године царовања Асина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'И у онај дан принесоше Господу жртве од плијена који догнаше, седам стотина волова и седам тисућа оваца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'И ухватише вјеру да траже Господа Бога отаца својих свијем срцем својим и свом душом својом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'А ко год не би тражио Господа Бога Израиљева, да се погуби, био мали или велики, човјек или жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'И заклеше се Господу гласом великим и уз кликовање и уз трубе и рогове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'И радоваше се сав народ Јудин ради те заклетве, јер из свега срца својега заклеше се, и од све воље своје тражише га и нађоше га; и Господ им даде мир отсвуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Јоште и Маху матер своју сврже Аса с власти, јер бјеше начинила у лугу идола; и Аса обали идола њезина и изломи га и сажеже на потоку Кедрону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Али висине не бише оборене у Израиљу, али срце Асино бјеше право свега вијека његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'И унесе у дом Божји што бјеше посветио отац његов и што бјеше сам посветио, сребро и злато и судове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'И не би рата од тридесет пете године царовања Асина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Године тридесет шесте царовања Асина изиде Васа цар Израиљев на Јуду, и стаде зидати Раму да не да никому отићи к Аси цару Јудину ни од њега доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Тада узе Аса сребро и злато из ризница дома Господњега и дома царева, и посла Вен-Ададу цару Сирскому, који живљаше у Дамаску, и поручи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Вјера је између мене и тебе, између оца мојега и оца твојега, ево шаљем ти сребра и злата, хајде поквари вјеру коју имаш са Васом царем Израиљевијем, еда би отишао од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'И послуша Вен-Адад цара Асу, и посла војводе своје на градове Израиљеве, и освојише Ијон и Дан и Авел-Мајим и све градове Нефталимове у којима бијаху житнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'А кад Васа то чу, преста зидати Раму и остави дјело своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Тада цар Аса узе сав народ Јудин, те однесоше камење из Раме и дрво, чим зидаше Васа, и од њега сазида Гавају и Миспу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'А у то вријеме дође Ананије видјелац к Аси цару Јудину и рече му: што си се поуздао у цара Сирскога а нијеси се поуздао у Господа Бога својега, зато се војска цара Сирскога измаче из твојих руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Нијесу ли Етиопљани и Лувеји имали велике војске с врло много кола и коњика? па кад си се поуздао у Господа, даде ти их у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Јер очи Господње гледају по свој земљи да би показивао силу своју према онима којима је срце цијело према њему. Лудо си у том радио; зато ће отселе бити ратови на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Тада се Аса разгњеви на пророка, и врже га у тамницу, јер се расрди на њ за то; и потлачи Аса неке из народа у то вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Али гле дјела Асина, прва и пошљедња, ено записана су у књизи о царевима Јудинијем и Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'И разбоље се Аса тридесет девете године царовања својега од ногу, и болест његова би врло тешка, али ни у болести својој не тражи Господа него љекаре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'И тако почину Аса код отаца својих, и умрије четрдесет прве године царовања својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'И погребоше га у гробу његову, који ископа себи у граду Давидову, и метнуше га на постељу коју бјеше напунио мирисавијех ствари и масти зготовљенијех вјештином апотекарском, и спалише му их врло много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Тада се зацари Јосафат син његов на његово мјесто, и укријепи се на Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'И понамјешта војску по свијем тврдијем градовима Јудинијем, и понамјешта страже по земљи Јудиној и по градовима Јефремовијем, које задоби Аса отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'И бијаше Господ с Јосафатом, јер хођаше првијем путовима Давида оца својега и не тражаше Вала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Него Бога оца својега тражаше и по заповијестима његовијем хођаше, и не чињаше као синови Израиљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Зато утврди Господ царство у руци његовој, и сав народ Јудин даваше даре Јосафату, те имаше велико благо и славу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'И срце се његово ослободи на путовима Господњим, те још обори висине и лугове у Јудеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'И треће године свога царовања посла кнезове своје Вен Аила и Овадију и Захарију и Натанаила и Михеју да уче по градовима Јудинијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'И с њима Левите: Семају и Натанију и Зевадију и Асаила и Семирамота и Јонатана и Адонију и Товију и Тов-Адонију, Левите, и с њима Елисаму и Јорама свештенике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'И учаху по Јудеји имајући при себи књигу закона Господњега, и прохођаху све градове Јудине учећи народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'И дође страх Господњи на сва царства по земљама око Јуде, те не војеваше на Јосафата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'И сами Филистеји доношаху Јосафату даре и данак у новцу; и Арапи догоњаху му стоку, по седам тисућа и седам стотина овнова и по седам тисућа и седам стотина јараца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Тако напредоваше Јосафат и подиже се веома; и сазида у Јудеји куле и градове за житнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'И имаше много добра по градовима Јудинијем, и војника, храбријех јунака у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'А ово је број њихов по домовима отаца њиховијех; од Јуде тисућници: Адна војвода, с којим бијаше три стотине тисућа храбријех јунака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'А за њим Јоанам војвода, с којим бијаше двјеста осамдесет тисућа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'А за њим Амасија син Зихријев, који се драговољно даде Господу, и с ким бијаше двјеста тисућа храбријех јунака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'А од Венијамина: храбри јунак Елијада, с којим бијаше двјеста тисућа наоружанијех луком и штитом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'А за њим Јозавад, с којим бијаше сто и осамдесет тисућа наоружанијех за бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Ови служаху цару осим онијех које понамјешта цар по тврдијем градовима у свој земљи Јудиној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'И Јосафат имајући велико благо и славу опријатељи се с Ахавом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'И послије неколико година отиде к Ахаву у Самарију; и накла му Ахав много оваца и волова и народу који бијаше с њим, и наговараше га да пође на Рамот Галадски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'И рече Ахав цар Израиљев Јосафату цару Јудину: хоћеш ли ићи са мном на Рамот Галадски? А он рече: ја као ти, народ мој као твој народ; хоћемо с тобом на војску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Још рече Јосафат цару Израиљеву: питај данас шта ће Господ рећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Тада сазва цар Израиљев пророке своје, четири стотине људи, и рече им: хоћемо ли ићи на војску на Рамот Галадски, или ћу се оканити? А они рекоше: иди, јер ће га Господ дати у руке цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'А Јосафат рече: има ли ту још који пророк Господњи да га питамо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'А цар рече Јосафату: има још један човјек преко којег бисмо могли упитати Господа; али ја мрзим на њ, јер ми не прориче добра него свагда зло; то је Михеја син Јемлин. А Јосафат рече: нека цар не говори тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Тада цар Израиљев дозва једнога дворанина, и рече му: брже доведи Михеју сина Јемлина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'А цар Израиљев и Јосафат цар Јудин сјеђаху сваки на свом пријестолу обучени у царске хаљине, сјеђаху на пољани код врата Самаријских, и сви пророци пророковаху пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'И Седекија син Хананин начини себи гвоздене рогове, и рече: овако вели Господ: овијем ћеш бити Сирце докле их не истријебиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Тако и сви пророци пророковаху говорећи: иди на Рамот Галадски, и бићеш срећан, јер ће га Господ предати цару у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'А посланик који отиде да дозове Михеју рече му говорећи: ево пророци проричу сви једнијем гласом добро цару; нека и твоја ријеч буде као њихова, и говори добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'А Михеја рече: тако да је жив Господ, говорићу оно што рече Бог мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'И кад дође к цару, рече му цар: Михеја! хоћемо ли ићи на војску на Рамот Галадски, или ћу се оканити? А он рече: идите, бићете срећни, и даће вам се у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'А цар му рече: колико ћу те пута заклањати да ми не говориш него истину у име Господње?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Тада рече: видио сам сав народ Израиљев разасут по планинама као овце које немају пастира, јер рече Господ: ови немају господара, нека се врате свак својој кући с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Тада рече цар Израиљев Јосафату: нијесам ли ти рекао да ми неће пророковати добра него зло?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'А Михеја рече: зато чујте ријеч Господњу: видјех Господа гдје сједи на пријестолу свом, а сва војска небеска стајаше му с десне и с лијеве стране;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'И Господ рече: ко ће преварити Ахава цара Израиљева да отиде и падне код Рамота Галадскога? Још рече: један рече ово а други оно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Тада изиде један дух, и ставши пред Господа рече: ја ћу га преварити. А Господ му рече: како?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Одговори: изићи ћу и бићу лажљив дух у устима свијех пророка његовијех. А Господ му рече: преварићеш га и надвладаћеш, иди учини тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Зато сада ето, Господ је метнуо лажљив дух у уста тијем пророцима твојим; а Господ је изрекао зло по те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Тада приступи Седекија син Хананин, и удари Михеју по образу говорећи: којим је путем отишао дух Господњи од мене да говори с тобом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'А Михеја му рече: ето, видјећеш у онај дан кад отидеш у најтајнију клијет да се сакријеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Тада цар Израиљев рече: ухватите Михеју, и одведите га к Амону заповједнику градском и к Јоасу сину цареву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'И реците им: овако вели цар: метните овога у тамницу, а дајите му по мало хљеба и по мало воде докле се не вратим у миру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'А Михеја рече: ако се вратиш у миру, није Господ говорио преко мене. Још рече: чујте сви народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'И отиде цар Израиљев с Јосафатом царем Јудинијем на Рамот Галадски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'И рече цар Израиљев Јосафату: ја ћу се преобући кад пођем у бој, а ти обуци своје одијело. И преобуче се цар Израиљев, и отидоше у бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'А цар Сирски заповједи војводама од кола својих говорећи: не ударајте ни на малога ни на великога, него на сама цара Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'А кад војводе од кола видјеше Јосафата, рекоше: то је цар Израиљев. И окренуше се на њ да га ударе. Али Јосафат повика, и Господ му поможе, и одврати их Бог од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Јер видјевши војводе од кола да није цар Израиљев, отступише од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'А један застријели из лука нагоном и устријели цара Израиљева гдје спуча оклоп. А он рече својему возачу: савиј руком својом и извези ме из боја, јер сам рањен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'И бој би жесток онога дана, а цар Израиљев заоста на колима својим према Сирцима до вечера, и умрије о сунчаном заходу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'А кад се Јосафат цар Јудин враћаше с миром кући својој у Јерусалим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Изиде преда њ Јуј син Ананијев, видјелац, и рече Јосафату: безбожнику ли помажеш, и оне који мрзе на Господа љубиш? Зато се подигао на те гњев Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Али се нашло добро на теби што си истријебио лугове из земље и што си управио срце своје да тражиш Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Потом Јосафат сјеђаше у Јерусалиму, и опет прође по народу од Вирсавеје до горе Јефремове, и поврати их ка Господу Богу отаца његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'И постави судије у земљи по свијем тврдијем градовима Јудинијем, у сваком граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'И рече судијама: гледајте шта ћете радити, јер нећете судити за човјека него за Господа, који је с вама кад судите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Зато нека буде страх Господњи у вама; пазите и радите, јер у Господа Бога нашега нема неправде, нити гледа ко је ко, нити прима поклона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Такођер у Јерусалиму постави Јосафат од Левита и свештеника и главара домова отачких у Израиљу за судове Господње и за распре; јер долажаху опет у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'И заповједи им говорећи: тако радите у страху Господњем, вјерно и цијела срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'И у свакој парници која дође к вама од браће ваше што сједе по градовима својим, да расудите између крви и крви, између закона и заповијести, између уредаба и судова, обавијестите их да не би гријешили Господу, да не би дошао гњев његов на вас и на браћу вашу; тако чините, те нећете згријешити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'И ево, Амарија поглавар свештенички биће над вама у свијем пословима Господњим, а Завдија син Исмаилов вођ дома Јудина у свијем пословима царским; такођер Левити управитељи биће уз вас. Будите слободни, и радите, и Господ ће бити с добријем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'А послије тога синови Моавови и синови Амонови и с њима који живе међу синовима Амоновијем, дођоше да војују на Јосафата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'И дођоше те јавише Јосафату говорећи: иде на те велико мноштво испреко мора, из Сирије; и ено их у Асасон-Тамару, а то је Ен-Гад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'А Јосафат се уплаши, и обрати лице своје да тражи Господа, и огласи пост по свој земљи Јудиној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'И скупише се сви синови Јудини да траже Господа, и из свијех градова Јудинијех дођоше да траже Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Тада стаде Јосафат у збору Јудину и Јерусалимском у дому Господњем пред тријемом новијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'И рече: Господе Боже отаца наших! нијеси ли ти Бог на небу и владаш свијем царствима народнијем? Није ли у твојој руци моћ и сила да ти нико не може одољети?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Нијеси ли ти, Боже наш, одагнао становнике ове земље испред народа својега Израиља, и дао је навијек сјемену Аврама пријатеља својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'Те се населише у њој, и саградише ти у њој светињу за име твоје говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Кад нас задеси како зло, мач осветни или помор или глад, стаћемо пред овијем домом и пред тобом, јер је име твоје у овом дому, и вапићемо теби у невољи својој, услиши и избави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'А сад ево, синови Амонови и Моавови и они из горе Сира, кроз које нијеси дао синовима Израиљевијем проћи кад иђаху из земље Мисирске, него их обидоше и не истријебише;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'А ево, они нам враћају дошавши да нас истјерају из нашљедства твојега, које си нам предао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Боже наш, зар им нећеш судити? јер у нама нема снаге да се опремо томе мноштву великом, које иде на нас, нити знамо што бисмо чинили, него су очи наше упрте у те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'А сви синови Јудини стајаху пред Господом и дјеца њихова, жене њихове и синови њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Тада сиђе дух Господњи усред збора на Јазила сина Захарије сина Венаје сина Јеила сина Матанијина, Левита између синова Асафовијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'И рече: слушајте, сви синови Јудини и Јерусалимљани, и ти царе Јосафате, овако вам вели Господ: не бојте се и не плашите се тога мноштва великога, јер није ваш рат него Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Сјутра изидите на њих; они ће поћи уз брдо Зис, и наћи ћете их накрај потока према пустињи Јеруилу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Не треба ви да се бијете у овом боју; поставите се, стојте па гледајте како ће вас избавити Господ, Јудо и Јерусалиме! не бојте се и не плашите се, сјутра изидите пред њих, и Господ ће бити с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Тада се Јосафат сави лицем к земљи, и сви Јудејци и Јерусалимљани падоше пред Господом, и поклонише се Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'А Левити од синова Катовијех и синова Корејевих усташе, те хвалише Господа Бога Израиљева гласом веома високим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'А ујутру уставши рано изидоше у пустињу Текујску; а кад излажаху, стаде Јосафат и рече: чујте ме, Јудејци и Јерусалимљани: вјерујте Господу Богу својему и бићете јаки, вјерујте пророцима његовијем и бићете срећни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'И тако договорив се с народом постави пјеваче Господње да хвале свету красоту идући пред војском и говорећи: хвалите Господа, јер је довијека милост његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'А кад почеше пјесму и хвалу, обрати Господ засједу на синове Амонове и синове Моавове и на оне из горе Сира, који изидоше на Јуду, те се разбише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Јер синови Амонови и синови Моавови усташе на оне из горе Сира да их побију и потру; и кад побише оне из горе Сира, ударише једни на друге, те се потрше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'А кад Јуда дође до стражаре према пустињи, и погледа на мноштво, а то мртва тјелеса леже по земљи, и ниједан не бјеше остао жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Зато дође Јосафат са народом својим да покупи плијен; и нађоше код њих много блага и драгоцјенијех накита на мртвацима, и наплијенише да већ не могоше носити; три дана купише плијен, јер га бјеше много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'А четврти дан скупише се у долини благословној, јер ондје благословише Господа; зато се прозва мјесто Долина Благословна до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Потом окренуше сви Јудејци и Јерусалимљани и Јосафат пред њима да се врате у Јерусалим с весељем, јер их овесели Господ непријатељима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'И дођоше у Јерусалим са псалтирима и гуслама и трубама у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'И страх Божји дође на сва царства земаљска кад чуше да је Господ војевао на непријатеље Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'И тако се смири царство Јосафатово, јер му Бог његов даде мир отсвуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'И цароваше Јосафат над Јудом; тридесет и пет година бијаше му кад поче царовати; и царова двадесет и пет година у Јерусалиму. Матери му бјеше име Азува, кћи Силејева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'И хођаше путем оца својега Асе, нити зађе с њега, чинећи што је право пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Али висине не бише оборене, јер још не бјеше народ управио срца својега к Богу отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'А остала дјела Јосафатова прва и пошљедња, ено записана су у књизи Јуја сина Ананијева, која је стављена у књигу о царевима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Потом здружи се Јосафат цар Јудин с Охозијом царем Израиљевијем, који чињаше безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'А здружи се с њим зато да начине лађе да иду у Тарсис; и начинише лађе у Есион-Гаверу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Тада пророкова Елијезер син Додавин из Марисе за Јосафата говорећи: што си се здружио с Охозијом, зато Господ разметну дјела твоја. И разбише се лађе и не могоше ићи у Тарсис.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Потом почину Јосафат код отаца својих, и би погребен код отаца својих у граду Давидову; а на његово се мјесто зацари Јорам син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'А браћа му, синови Јосафатови, бијаху: Азарија и Јехило и Захарија и Азарија и Михаило и Сефатија; ти сви бијаху синови Јосафата цара Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'И отац им даде велике дарове, сребра и злата и заклада с тврдијем градовима у земљи Јудиној; царство пак даде Јораму, јер бјеше првенац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'А Јорам ступив на царство оца својега и утврдив се, поби сву браћу своју мачем и неке кнезове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Имаше Јорам тридесет и двије године кад се зацари, и царова осам година у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'И хођаше путем царева Израиљевих, као што чињаше дом Ахавов, јер се ожени кћерју Ахавовом; и чињаше што је зло пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Али Господ не хтје затрти дома Давидова ради завјета који учини с Давидом и што му бјеше рекао да ће дати видјело њему и синовима његовим увијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'За његова времена одврже се Едом да не буде под Јудом, и поставише себи цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Зато отиде Јорам с војводама својим и са свијем колима својим; и уста ноћу, те поби Едомце који га бијаху опколили, и заповједнике од кола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Ипак се одвргоше Едомци да не буду под Јудом до данас. У исто вријеме одврже се Ливна да не буде под њим, јер остави Господа Бога отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Још и висине начини по брдима Јудинијем, и наведе на прељубу Јерусалимљане и преласти Јуду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Тада му дође књига од Илије пророка, гдје му говораше: овако вели Господ Бог Давида оца твојега: што нијеси ходио путовима Јосафата оца својега и путовима Асе цара Јудина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Него си ходио путем царева Израиљевијех и и навео си на прељубу Јуду и Јерусалимљане, као што је дом Ахавов навео на прељубу Израиља, и још си побио браћу своју, дом оца својега, боље од себе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Ево, Господ ће ударити великим злом народ твој и синове твоје и жене твоје и све што имаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'И ти ћеш боловати тешко, од болести у цријевима, да ће ти цријева изаћи од болести, која ће трајати двије године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'И тако подиже Господ на Јорама дух Филистејима и Арапима који живе од Етиопљана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'И они дошавши на земљу Јудину продријеше у њу, и однесоше све благо што се нађе у дому цареву, и синове његове и жене његове, да му не оста ниједан син осим Јоахаза најмлађега сина његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'И послије свега тога удари га Господ болешћу у цријевима, којој не бјеше лијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'И дан по дан пролажаше, и кад се навршише двије године, изидоше му цријева с болешћу и умрије од тешких болова, и народ му не пали мириса као што је чинио оцима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Имаше тридесет и двије године кад поче царовати, и царова осам година у Јерусалиму, и премину да нико не зажали за њим; и погребоше га у граду Давидову, али не у гробу царском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'А Јерусалимљани зацарише на његово мјесто Охозију најмлађег сина његова, јер старије све поби чета која дође с Арапима у око; и тако Охозија син Јорамов поста цар Јудин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Имаше Охозија четрдесет и двије године кад поче царовати, и царова годину дана у Јерусалиму. Матери му бјеше име Готолија, кћи Амријева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'И он хођаше путовима дома Ахавова, јер га мати наговараше на зла дјела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'И чињаше што је зло пред Господом као дом Ахавов; јер му они бијаху савјетници по смрти оца његова на погибао његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'И по њихову свјету ходећи изиде с Јорамом сином Ахавовијем царем Израиљевијем на војску на Азаила цара Сирскога у Рамот Галадски; и ондје Сирци ранише Јорама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'А он се врати да се лијечи у Језраелу од рана које му задаше у Рами, кад се бијаше с Азаилом царем Сирским. А Азарија син Јорамов цар Јудин дође у Језраел да види Јорама сина Ахавова, јер бијаше болестан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Али бијаше од Бога на пропаст Охозији што дође к Јораму; јер дошав отиде с Јорамом на Јуја сина Нимсијина, којега Господ помаза да истријеби дом Ахавов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Јер кад Јуј извршиваше освету на дому Ахавову, нађе кнезове Јудине и синове браће Охозијине, који служаху Охозији, и погуби их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Потом потражи Охозију, и ухватише га кад се кријаше у Самарији, и доведавши га к Јују погубише га, и погребоше га; јер рекоше: син је Јосафата који је тражио Господа свијем срцем својим. И тако не би никога од дома Охозијина који би могао бити цар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Зато Готолија мати Охозијина видјевши да јој син погибе, уста и поби све царско сјеме дома Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Али Јосавета кћи царева узе Јоаса сина Охозијина и украде га између синова царевијех, које убијаху; и сакри га с дојкињом његовом у ложницу. И тако Јосавета кћи цара Јорама жена Јодаја свештеника сакри га од Готолије, јер бијаше сестра Охозијина, те га не уби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'И бијаше с њима сакривен у дому Божијем шест година; а Готолија цароваше у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'А седме године ослободи се Јодај, и узе к себи стотинике Азарију сина Јероамова и Исмаила сина Јоананова и Азарију сина Овидова и Масију сина Адајева и Елисафата сина Зихријева, и ухвати вјеру с њима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Те пролазећи земљу Јудину сабраше Левите из свијех градова Јудинијех и главаре породица отачкијех у Израиљу, и дођоше у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'И сав збор учини вјеру у дому Божијем с царем; и Јодај им рече: ево, син ће царев царовати, као што је рекао Господ за синове Давидове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Ово учините: трећина вас који долазите у суботу између свештеника и Левита нека буду вратари на прагу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'А друга трећина нека буде у царском двору; а остала трећина на вратима од темеља, а сав народ у тријемовима дома Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Нико да не улази у дом Господњи осим свештеника и онијех Левита који служе; они нека улазе, јер су посвећени, а сав народ нека чини оно што је Господ заповједио да чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'И Левити нека опколе цара сваки с оружјем својим у руци; и ко би год ушао у дом, да се погуби; и будите уз цара кад стане улазити и излазити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'И учинише Левити и сав народ Јудин све што заповједи свештеник Јодај; и узеше сваки своје људе који долажаху у суботу и који одлажаху у суботу; јер Јодај свештеник не отпусти редова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'И даде Јодај свештеник стотиницима копља и штитове и штитиће цара Давида што бијаху у дому Божијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'И постави сав народ све с оружјем у руку, од десне стране дома до лијеве према олтару и према дому, око цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Тада изведоше сина царева, и метнуше му на главу вијенац, и дадоше му свједочанство, и зацарише га, и Јодај и синови његови помазаше га о рекоше: да живи цар!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'А кад Готолија чу вику народа који се стјецаше и хваљаше цара, дође к народу у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'И погледа, и гле, цар стајаше код својега ступа на уласку, а кнезови и трубе око цара, и сав народ земаљски радоваше се и трубе трубљаху и пјевачи пјеваху уз оруђа музичка и они који почињаху у пјевању. Тада раздрије Готолија хаљине своје и повика: буна! буна!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'А Јодај свештеник заповједи да изиду стотиници који бијаху над војском, и рече им: изведите је из врста напоље, и ко пође за њом нека се погуби мачем; јер рече свештеник: немојте је убити у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'И начинише јој мјесто, те отиде како се иде вратима коњским у дом царев, и ондје је погубише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Тада Јодај учини вјеру међу собом и свијем народом и царем да ће бити народ Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Потом сав народ отиде у дом Валов, и раскопаше га, и олтаре његове и ликове његове изломише, а Матана свештеника Валова убише пред олтарима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'И Јодај уреди опет службу у дому Господњем међу свештеницима и Левитима, које Давид бјеше одредио дому Господњему, да би приносили жртве паљенице Господу, као што пише у закону Мојсијеву, с весељем и пјесмама по наредби Давидовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Постави и вратаре на вратима дома Господњега да не би улазио нечист ода што му драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'И узе стотинике и знатније људе и који управљаху народом, сав народ земаљски, и изведе цара из дома Господњега и уђоше високим вратима у дом царски, и посадише цара на царски пријесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'И радоваше се сав народ земаљски, и град се умири, кад Готолију убише мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Бијаше Јоасу седам година кад се зацари, и царова четрдесет година у Јерусалиму. Матери му бјеше име Сивија из Вирсавеје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'И чињаше Јоас што је право пред Господом докле год бијаше жив Јодај свештеник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'И јодај га ожени двјема женама, те роди синове и кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Потом Јоас науми да оправи дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'И сазва свештенике и Левите, па им рече: пођите по градовима Јудинијем и купите од свега Израиља новац да се оправља дом Бога вашега од године до године, и ви похитајте с тијем. Али не хитјеше Левити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Зато цар дозва Јодаја поглавара и рече му: зашто не настојиш да Левити доносе из Јудеје и Јерусалима прилоге које је наредио Мојсије слуга Господњи збору Израиљеву на шатор од састанка?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Јер безбожна Готолија и синови њезини оплијенише дом Господњи и све ствари посвећене дому Господњем обратише на Вале.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'И тако заповједи цар те начинише ковчег, и метнуше га на врата дома Господњега споља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'И огласише по Јудеји и по Јерусалиму да доносе Господу прилог који је наредио Мојсије слуга Божји Израиљу у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'И обрадоваше се кнезови и сав народ, и доносећи метаху у ковчег докле се не сврши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'И кад доношаху Левити ковчег по заповијести царевој, видјевши да има много новца, долажаше писар царев и посланик поглавара свештеничкога, те изручиваху ковчег, потом га опет одношаху и остављаху на његово мјесто; и тако чињаху сваки дан, и накупише много новца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'И даваше га цар Јодај настојницима над послом око дома Господњега, а они наимаху каменаре и дрводјеље да се обнови дом Господњи, и коваче који раде од гвожђа и од мједи, да се оправи дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'И пословаху посленици, и оправљање напредоваше под њиховијем рукама, те повратише дому Божијему обличје његово, и утврдише га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'А кад свршише, донесоше пред цара и Јодаја новце што претекоше; и од тога новца начини судове за дом Господњи, судове за службу и за жртве, и кадионице, и друге судове златне и сребрне. И тако приношаху жртве паљенице у дому Господњем једнако свега вијека Јодајева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Потом остарјевши Јодај сит живота умрије; сто и тридесет година бјеше му кад умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'И погребоше га у граду Давидову код царева; јер чињаше добро Израиљу и Богу и дому његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'А кад умрије Јодај, дођоше кнезови Јудини и поклонише се цару; тада их послуша цар,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Те оставише дом Господа Бога отаца својих, и стадоше служити луговима и идолима; и подиже се гњев Господњи на Јуду и на Јерусалим за тај гријех њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'И слаше им пророке да их врате ка Господу, и они им сведочаху, али их не послушаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'И дође дух Господњи на Захарију сина Јодаја свештеника, те стаде више народа и рече им: овако вели Бог: зашто преступате заповијести Господње? нећете бити срећни; што остависте Господа, зато и он вас остави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'А они се побунише на њ, и засуше га камењем по заповијести царевој у тријему дома Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'И не опомену се Јоас милости коју му учини Јодај отац његов, него уби сина његова; а он умирући рече: Господ нека види и тражи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'А кад прође година, подиже се на њ војска Сирска и уђе у земљу Јудејску и у Јерусалим, и побише по народу све кнезове народне, и сав плијен од њих послаше цару у Дамаск.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Ако и мала бјеше војска Сирска која дође, ипак Господ даде у руке њихове врло велику војску, јер бјеху оставили Господа Бога отаца својих. И тако на Јоасу извршише суд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'А кад отидоше од њега оставивши га у тешкој болести, побунише се на њ слуге његове за крв синова Јодаја свештеника, и убише га на постељи његовој, те погибе; и погребоше га у граду Давидову, али га не погребоше у гробовима царским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'А ово су што се побунише на њ: Завад син Симеате Амонке и Јозавад син Симрите Моавке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'А о синовима његовијем и о великој порези што би под њим, и о грађењу дома Божијега, ето записано је у књизи о царевима. А зацари се на његово мјесто Амасија син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Бијаше Амасији двадесет и пет година кад поче царовати, и царова двадесет и девет година у Јерусалиму. Матери му бјеше име Јоадана из Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Он чињаше што је право пред Господом, али не цијелијем срцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'И кад се утврди у царству, поби слуге своје који убише цара оца његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Али синова њиховијех не погуби, него учини како пише у закону, у књизи Мојсијевој, гдје је заповједио Господ говорећи: оцеви да не гину за синове, ни синови за оцеве, него сваки за свој гријех нека гине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Иза тога скупи Амасија народ Јудин, и постави по домовима отачким тисућнике и стотинике по свој земљи Јудиној и Венијаминовој, и изброји их од двадесет година и више, и нађе их триста тисућа војника избранијех, који ношаху копље и штит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'И јоште најми између Израиљаца сто тисућа храбријех људи за сто таланата сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Али дође му човјек Божји и рече: царе, да не иде с тобом војска Израиљска, јер Господ није с Израиљцима нити са синовима Јефремовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Него иди ти, и буди храбар у боју; иначе ће те оборити Бог пред непријатељем, јер Бог може и помоћи и оборити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Тада рече Амасија човјеку Божијему: а што ће бити од сто таланата што сам дао војсци Израиљевој? А човјек Божји рече: има Господ да ти да више од тога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'И тако одвоји Амасија војску што му бјеше дошла од Јефрема да отиду у своје мјесто; а они се врло расрдише на Јуду, и вратише се у своје мјесто с великим гњевом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'А Амасија ослободивши се поведе народ свој и отиде у слану долину, и поби десет тисућа синова Сировијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'И десет тисућа живијех заробише Јудејци, и одведоше их на врх стијене, и побацаше их са врх стијене да се сви распадоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'А војници које Амасија посла натраг да не иду с њим у бој, навалише на градове Јудине од Самарије до Вет-Орона, и побише по њима три тисуће, и заплијенише велик плијен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'А кад се врати Амасија разбивши Идумеје, донесе богове синова Сировијех, и постави их себи за богове, и клањаше им се и кађаше им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Тада се разгњеви Господ на Амасију, и посла к њему пророка, који му рече: зашто тражиш богове тога народа, који не избавише својега народа из твоје руке?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'И кад говораше цару, он му рече: јеси ли постављен цару за савјетника? престани; зашто да погинеш? И тако преста пророк, али рече: знам да те је Бог наумио истријебити кад то радиш а не слушаш свјета мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Тада смисли Амасија цар Јудин, и посла к Јоасу сина Јоахаза сина Јујева, цару Израиљеву, и поручи: ходи да се огледамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'А јоас цар Израиљев посла к Амасији цару Јудину и поручи му: трн на Ливану посла ка кедру на Ливану, и поручи: дај своју кћер сину мојему за жену. Али наиђе звијерје Ливанско и изгази трн.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Велиш, побио си Едомце, па се понесе срце твоје, и тражиш славе; сједи код куће своје; зашто би се заплетао у зло да паднеш и ти и Јуда с тобом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Али не послуша Амасија, јер од Господа то би да их да у руке непријатељу, што тражише богове Едомске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'И отиде Јоас цар Израиљев, и огледаше се, он и Амасија цар Јудин, у Вет-Семесу Јудину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Али Јуду разби Израиљ, те побјегоше сваки ка својему шатору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'А Амасију цара Јудина сина Јоаса сина Јоахазова ухвати Јоас цар Израиљев у Вет-Семесу, и одведе га у Јерусалим; и обори зид Јерусалимски од врата Јефремовијех до врата на углу, четири стотине лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'И узе све злато и сребро и све посуђе што се нађе у дому Божијем у Овид-Едома и у ризници дома царскога, и таоце, па се врати у Самарију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'И поживје Амасија син Јоасов цар Јудин по смрти Јоаса сина Јоахаза цара Израиљева петнаест година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'А остала дјела Амасијина прва и пошљедња, ето нијесу ли записана у књизи о царевима Јудинијем и Израиљевијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'И пошто Амасија отступи од Господа, дигоше буну на њ у Јерусалиму, а он побјеже у Лахис. Али послаше за њим у Лахис, и убише га ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'И донесоше га на коњма и погребоше га код отаца његовијех у граду Јудину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Тада сав народ Јудин узе Озију, коме бијаше шеснаест година, и зацарише га на мјесто оца његова Амасије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Он сазида Елот повратив га Јуди пошто цар почину код отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Озији бјеше шеснаест година кад се зацари, и царова педесет и двије године у Јерусалиму. Матери му бјеше име Јехолија из Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Он чињаше што је право пред Господом сасвијем како је чинио Амасија отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'И тражаше Бога докле жив бијаше Захарија који разумијеваше утваре Божије; и докле год тражаше Господа, даваше му срећу Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Јер изашав војеваше с Филистејима, и обори зидове Гату и зидове Јавни и зидове Азоту; и сазида градове у земљи Азотској и по Филистејима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'И Бог му поможе против Филистеја и против Арапа, који живљаху у Гурвалу, и против Амонаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'И Амонци даваху дарове Озији, и разнесе се име његово до Мисира, јер осили веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'И сазида Озија куле у Јерусалиму на вратима на углу, и на вратима у долу, и на углу, и утврди их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Сазида и у пустињи куле, и ископа много студенаца, јер имаше много стоке у долинама и у равницама, и ратара и виноградара по брдима и на Кармилу, јер му мила бјеше пољска радња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'И имаше Озија убојиту војску, која иђаше у рат у четама бројем, како их изброји Јеило писар и Масија управитељ, под управом Ананије војводе царева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Свега на број бијаше главара домова отачких храбријех јунака двије тисуће и шест стотина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'А под њиховом руком војске три стотине и седам тисућа и пет стотина храбријех војника, да помажу цару против непријатеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'И начини Озија свој војсци штитове и копља и шљемове и оклопе и лукове и камење за праће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'И начини у Јерусалиму бојне справе врло вјешто измишљене да стоје на кулама и на угловима да мећу стријеле и велико камење; и разнесе се име његово далеко, јер му се дивно помагаше докле осили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Али кад осили, понесе се срце његово, те се поквари, и сагријеши Господу Богу својему, јер уђе у цркву Господњу да кади на олтару кадионом:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'А за њим уђе Азарија свештеник и с њим осамдесет свештеника Господњих храбријех људи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'И опријеше се цару Озији говорећи: није твоје, Озија, кадити Господу, него свештеника синова Ароновијех који су посвећени да каде; изиди из светиње, јер си згријешио, и неће ти бити на част пред Господом Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Тада се разгњеви Озија држећи у руци кадионицу да кади; и кад се гњевљаше на свештенике, изиде му губа на челу пред свијем свештеницима у дому Господњем код олтара кадионог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'И погледа га Азарија поглавар свештенички и сви свештеници, а он губав на челу; и брже га изведоше напоље, а и сам похитје да изиде, јер га Господ удари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'И оста цар Озија губав до смрти своје, и сјеђаше у одвојеном дому губав, јер би одлучен од дома Господњега; а Јотам син његов управљаше домом царевијем и суђаше народу у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'А остала дјела Озијина прва и пошљедна написао је пророк Исаија син Амосов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'И почину Озија код отаца својих, и погребоше га код отаца његовијех у гробном пољу царском, јер рекоше: губав је. И зацари се на његово мјесто Јотам син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Двадесет и пет година бијаше Јотаму кад поче царовати, и царова шеснаест година у Јерусалиму; матери му бјеше име Јеруса, кћи Садокова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Он чињаше што је право пред Господом сасвијем како је чинио Озија отац његов, само што не уђе у цркву Господњу; али народ још бијаше покварен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Он начини висока врата на дому Господњем, и на зиду Офилу много назида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Још сазида и градове у гори Јудиној, и у шумама погради дворове и куле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'И војева с царем синова Амоновијех и савлада их; и дадоше му синови Амонови оне године сто таланата сребра и десет тисућа кора пшенице и јечма десет тисућа. Толико му дадоше синови Амонови и друге и треће године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'И тако осили Јотам, јер управи путове своје пред Господом Богом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'А остала дјела Јотамова и ратови сви његови и путови његови, ено су записани у књизи о царевима Израиљевијем и Јудинијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Двадесет и пет година бјеше му кад поче царовати, и царова шеснаест година у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'И почину Јотам код отаца својих, и погребоше га у граду Давидову; а на његово се мјесто зацари Ахаз син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Двадесет година бијаше Ахазу кад поче царовати, и царова шеснаест година у Јерусалиму; али не чињаше што је право пред Господом као Давид отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Јер хођаше путовима царева Израиљевијех, и још сали ликове Валима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'И сам кађаше у долини сина Еномова, и сажизаше синове своје огњем по гаднијем дјелима онијех народа које одагна Господ испред синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'И приношаше жртве и кађаше на висинама и по брдима и под сваким зеленијем дрветом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Зато га даде Господ Бог његов у руке цару Сирскому, те га разбише и заробише му велико мноштво, и одведоше их у Дамасак. Још би дат у руке цару Израиљеву, те га разби љуто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Јер Фекај син Ремалијин поби сто и двадесет тисућа Јудејаца у један дан, све храбријех људи, јер оставише Господа Бога отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'И Зихрије јунак од Јефрема уби Масију сина царева и Азрикама управитеља дворскога и Елкану другога до цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'И заробише синови Израиљеви браћи својој двјеста тисућа жена и синова и кћери; и заплијенише велики плијен од њих, и однесоше плијен у Самарију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'А ондје бијаше пророк Господњи по имену Одид, и изиде пред војску која иђаше у Самарију, и рече им: гле, Господ Бог отаца ваших разгњеви се на Јудејце, зато их даде у ваше руке, те их побисте љуто да до неба доприје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'И још мислите подврћи синове Јудине и Јерусалимске да вам буду робови и робиње; а нијесте ли и ви сами скривили Господу Богу својему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Зато послушајте ме сада, и вратите натраг то робље што заробисте браћи својој, јер се распалио гњев Господњи на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Тада усташе поглавари синова Јефремовијех: Азарија син Јоананов, Варахија син Месилемотов и Језекија син Салумов и Амаса син Адлајев на оне што се враћаху с војске,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'И рекоше им: нећете довести овамо тога робља, јер би нам било на гријех пред Господом што ви мислите домећући на гријехе наше и на кривице наше, јер је велика кривица на нама и гњев се распалио на Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'И оставише војници робље и плијен свој пред кнезовима и свијем збором.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'И усташе људи именовани и узеше робље, и све голе између њих одјеше из плијена; и кад их одјеше и обуше, нахранише их и напојише и намазаше, и одведоше на магарцима све изнемогле, и доведоше их у Јерихон град гдје има много палама, к браћи њиховој, па се вратише у Самарију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'У то вријеме посла цар Ахаз к царевима Асирским да му помогу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Јер још и Идумејци дођоше и разбише Јуду и одведоше робље;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'И Филистеји ударише на градове по равни на јужном крају Јудину, и узеше Вет-Семес, и Ејалон и Гедирот и Сохот и села његова и Тамну и села њезина и Гимзон и села његова, и населише се у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Јер Господ обараше Јуду с Ахаза цара Израиљева, јер одвуче Јуду да грдно гријеши Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'И дође к њему Телгат-Фелнасар цар Асирски, и ојади га а не утврди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Јер Ахаз узе дио из дома Господњега и из дома царскога и од кнезова, и даде цару Асирском, али му не поможе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'И кад бијаше у невољи, он још већма гријешаше Господу; таки бијаше цар Ахаз.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'И приношаше жртве боговима Дамаштанским, који га разбише, и говораше: кад богови царева Сирских њима помажу, приносићу њима жртве да би ми помагали; али му они бише на то да падне он и сав Израиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'А Ахаз покупи судове дома Божијега, и изломи судове дома Божијега, и затвори врата дома Господњега и начини себи олтаре по свијем угловима у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'И у сваком граду Јудину начини висине да кади боговима туђим; и гњеви Господа Бога отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'А остала дјела његова и сви путови његови први и пошљедњи, ето записани су у књизи о царевима Јудинијем и Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'И почину Ахаз код отаца својих и погребоше га у граду Јерусалиму; али га не метнуше у гроб царева Израиљевијех. И зацари се на његово мјесто Језекија син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Језекији бјеше двадесет и пет година кад поче царовати, и царова двадесет и девет година у Јерусалиму. Матери му бјеше име Авија, кћи Захаријина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'И чињаше што је право пред Господом сасвијем како је чинио Давид отац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Прве године својега царовања, првога мјесеца, отвори врата на дому Господњем, и оправи их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'И сазва свештенике и Левите, и сабра их на источну улицу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'И рече им: чујте ме, Левити, освештајте се сада и осветите дом Господа Бога отаца својих, и изнесите нечистоту из светиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Јер сагријешише оци наши и чинише што је зло пред Господом Богом нашим, и оставише га; и одвратише лице своје од шатора Господњега и окренуше му леђа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'И затворише врата од тријема, и погасише жишке, и кадом не кадише, нити жртава паљеница приносише у светињи Богу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Зато се разгњеви Господ на Јуду и на Јерусалим, те их даде да се потуцају, и да буду чудо и потсмијех, како видите својим очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Јер ето падоше оци наши од мача, и синови наши и кћери наше и жене наше заробише се зато.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Сада дакле наумио сам задати вјеру Господу Богу Израиљеву, да би се одвратила од нас жестина гњева његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Синови моји, не оклијевајте више, јер је вас изабрао Господ да стојите пред њим и служите му, и да му будете слуге и да му кадите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Тада усташе Левити Мат син Амасајев и Јоило син Азаријин од синова Катовијех; а од синова Мераријевих Кис син Авдијев и Азарија син Јалелеилов; и од синова Гирсоновијех Јоах син Зимин и Еден син Јоахов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'И од синова Елисафановијех Симрије и Јеило, и од синова Асафовијех Захарија и Матанија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'И од синова Амоновијех Јеило и Симеј, и од синова Једутуновијех Семаја и Озило;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'И скупише браћу своју, и освештавши се дођоше, како бјеше заповједио цар по ријечи Господњој, да очисте дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'И ушавши свештеници у дом Господњи да га очисте, износише сву нечистоту што нађоше у цркви Господњој у тријем дома Господњега; а Левити купише и износише напоље на поток Кедрон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'А почеше освећивати првога дана првога мјесеца; а осмога дана тога мјесеца уђоше у тријем Господњи, и освећиваше дом Господњи осам дана, и шеснаестога дана првога мјесеца свршише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Потом дођоше к цару Језекији и рекоше: очистисмо сав дом Господњи и олтар за жртве паљенице и све судове његове и сто за постављање и све судове његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'И све судове које бјеше бацио цар Ахаз докле цароваше гријешећи, и спремисмо и осветисмо, и ено их пред олтаром Господњим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Потом цар Језекија уста рано, и сазва управитеље градске, и отиде у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'И доведе седам јунаца и седам овнова и седам јагањаца и седам јараца за гријех, за царство и за светињу и за Јуду; и рече синовима Ароновијем свештеницима да принесу на олтару Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Тада заклаше говеда, и свештеници узевши крв њихову покропише олтар; заклаше и овнове, и крвљу њиховом покропише олтар; и заклаше јагањце и крвљу њиховом покропише олтар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Потом доведоше јарце за гријех пред цара и пред збор, и они метнуше руке своје на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'И заклаше их свештеници, и очистише крвљу њиховом олтар на очишћење свему Израиљу, јер цар заповједи да се за сав народ Израиљев принесе жртва паљеница и жртва за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'И постави Левите у дому Господњем с кимвалима и псалтирима и гуслама, како бјеше заповједио Давид и Гад видјелац царев и Натан пророк; јер од Господа бјеше заповијест преко пророка његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'И тако стајаху Левити са справама Давидовијем а свештеници с трубама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Тада заповједи Језекија да принесу жртву паљеницу на олтару. И кад се поче жртва паљеница, поче се пјесма Господња уз трубе и справе Давида цара Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'И сав се збор клањаше, и пјевачи пјеваху и трубачи трубљаху, и то све докле се не сврши жртва паљеница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'А кад свршише жртву, цар и сви који бијаху с њим падоше и поклонише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Потом рече цар и кнезови Левитима да хвале Господа ријечима Давидовијем и Асафа видиоца; и хвалише с великим весељем, и савивши се поклонише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Тада Језекија проговори и рече: сада посветисте руке своје Господу, приступите и донесите приносе и жртве захвалне у дом Господњи. И донесе сав збор приносе и жртве захвалне, и ко год бјеше вољна срца жртве паљенице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'И на број бјеше жртава паљеница што донесе збор, седамдесет волова, сто овнова, двјеста јагањаца, све за жртву паљеницу Господу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'А других ствари посвећенијех бјеше шест стотина волова и три тисуће оваца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Али мало бијаше свештеника, те не могаху дријети свијех жртава паљеница; зато им помагаху браћа њихова Левити, докле се не сврши посао и докле се не освешташе други свештеници; јер Левити бијаху радији освештати се него свештеници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'И бијаше врло много жртава паљеница с претилином од жртава захвалнијех и наљева на жртве паљенице. Тако би повраћена служба у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'И радоваше се Језекија и сав народ, што Бог управи народ, јер ово би нагло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Потом посла Језекија к свему Израиљу и Јуди, и написа књиге синовима Јефремовијем и Манасијиним да дођу у дом Господњи у Јерусалим да прославе пасху Господу Богу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Јер цар и кнезови његови и сав збор свијећаше у Јерусалиму да славе пасху другога мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Јер је не могаше славити у то вријеме, јер не бијаше доста свештеника посвећенијех и народ се не бјеше скупио у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'И то би по вољи цару и свему збору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'И одредише да огласе по свему Израиљу од Вирсавеје до Дана да дођу у Јерусалим да прославе пасху Господу Богу Израиљеву, јер је одавна не бјеху славили како је написано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'И тако отидоше гласници с књигама од цара и од кнезова по свему Израиљу и Јуди, и по заповијести царевој говораху: синови Израиљеви, обратите се ка Господу Богу Аврамову, Исакову и Израиљеву, па ће се и он обратити к остатку који сте остали од руку царева Асирских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Не будите као оци ваши и као браћа ваша што гријешише Господу Богу отаца својих, те их даде да буду чудо, како видите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Не будите дакле тврдоврати као оци ваши, дајте руке Господу и ходите у светињу његову коју је осветио навијек, и служите Господу Богу својему, па ће се одвратити од вас жестина гњева његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Јер ако се обратите ка Господу, браћа ће ваша и синови ваши стећи милост у онијех који их заробише, те ће се вратити у ову земљу; јер је Господ Бог ваш милостив и жалостив, и неће одвратити лица од вас, ако се обратите к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'А кад ти гласници иђаху од града до града по земљи Јефремовој и Манасијиној дори до Завулона, потсмијеваху им се и ругаху им се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Али неки од Асира и од Манасије и од Завулона покоривши се дођоше у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'И над Јуду дође рука Господња, те им даде једно срце да учине што бјеше заповједио цар и кнезови по ријечи Господњој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'И скупи се у Јерусалим мноштво народа да празнују празник пријеснијех хљебова другог мјесеца, и би сабор веома велик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Тада се подигоше, и оборише олтаре што бијаху у Јерусалиму, и све олтаре кадионе оборише и бацише у поток Кисон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Потом заклаше пасху четрнаестог дана другога мјесеца; а свештеници и Левити постидјевши се освешташе се, и унесоше жртве паљенице у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'И стадоше својим редом како треба по закону Мојсија слуге Божијега; и свештеници кропише крвљу примајући из руке Левитима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'И јер их много бијаше у збору који се не бјеху освештали; зато Левити клаху пасху за свакога који не бјеше чист да би их посветили Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Јер мноштво народа, многи од Јефрема и од Манасије и од Исахара и од Завулона не очистише се, него једоше пасху не како је написано. Али се за њих помоли Језекија говорећи: Господ благи нека очисти свакога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'Ко је управио срце своје да тражи Бога Господа, Бога отаца својих, ако и не би био чист према светом очишћењу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'И услиши Господ Језекију, и сачува народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'И тако синови Израиљеви који бјеху у Јерусалиму празноваше празник преснијех хљебова седам дана у великом весељу, и хваљаху Господа сваки дан Левити и свештеници уз оруђа за славу Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'И Језекија говори љубазно са свијем Левитима који вјешти бијаху служби Господњој; и једоше о празнику седам дана приносећи жртве захвалне и славећи Господа Бога отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'И сав збор договори се да празнује још седам дана; и празноваше још седам дана у весељу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Јер Језекија цар Јудин даде збору тисућу јунаца и седам тисућа оваца; а кнезови дадоше збору тисућу јунаца и десет тисућа оваца; и освешта се много свештеника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'И тако се провесели сав збор Јудин и свештеници и Левити, и сав збор што бјеше дошао од Израиља, и дошљаци што бјеху дошли из земље Израиљеве и који живљаху у земљи Јудиној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'И би весеље велико у Јерусалиму; јер од времена Соломуна сина Давидова цара Израиљева не би тако у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Потом усташе свештеници и Левити и благословише народ; и услишен би глас њихов, и молитва њихова дође у стан светиње Господње на небо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Акад се све ово сврши, сви синови Израиљеви што се нађоше ондје, зађоше по градовима Јудинијем, и изломише ликове и исјекоше лугове, и оборише висине и олтаре по свој земљи Јудиној и Венијаминовој и по земљи Јефремовој и Манасијиној, докле све не свршише; потом се вратише сви синови Израиљеви свак на своје нашљедство, у своје градове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'А Језекија опет уреди редове свештеничке и Левитске по редовима њиховијем, свакога по служби његовој, свештенике и Левите, за жртве паљенице и захвалне, да служе, и да славе и хвале Господа на вратима окола његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'И одреди дио царски од блага својега за жртве паљенице, што се приносе јутром и вечером и за жртве паљенице што се приносе у суботе и на младине и на празнике, како је написано у закону Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'И заповједи народу, Јерусалимљанима, да дају дио свештеницима и Левитима, да се јаче држе закона Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'А чим се то разгласи, стадоше доносити синови Израиљеви силу првина од жита и од вина и од уља и од меда и свакога рода земаљскога; и десетка од свега доносише врло много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'И синови Израиљеви и Јудини који живљаху по градовима Јудинијем, доносише и они десетак од говеда и оваца, и десетак од светијех ствари посвећенијех Господу Богу њихову, и метнуше у гомиле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Трећега мјесеца почеше метати у гомиле, а седмога мјесеца свршише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'И дође Језекија с кнезовима, и видјевши гомиле благословише Господа и народ његов Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'И Језекија запита свештенике и Левите за гомиле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'А Азарија поглавар свештенички од дома Садокова рече му: откад почеше доносити ове прилоге у дом Господњи, једемо и сити смо и претјече много, јер је Господ благословио свој народ, те је претекло ово мноштво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Тада заповједи Језекија да се начине клијети у дому Господњем; и начинише;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'И ондје остављаху вјерно прилоге и десетке и ствари посвећене; и над тијем бјеше поглавар Хонанија Левит и Симеј брат му, други до њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'А Јехило и Азазија и Нахат и Асаило и Јеримот и Јозавад и Елило и Исмахија и Мат и Венаја бијаху настојници под руком Хонаније и брата му Симеја по наредби цара Језекије и Азарије старјешине у дому Божијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'А Кореј син Јемне Левита, вратар на истоку, бијаше над онијем што се драговољно приношаше Богу, да би раздјељивао принос Господњи и ствари свете над светијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'А под њим бјеше Еден и Минијамин и Исус и Семаја и Амарија и Сеханија по градовима свештеничким, људи поуздани, да раздају браћи својој дијелове, великому и малому,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Осим мушкиња у роду њихову од три године и више, свакому који улажаше у дом Господњи на посао свакидашњи по дужности њиховој у служби њиховој по реду њихову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'И онима који бише избројени у роду свештеничком по домовима отаца њиховијех, и Левитима од двадесет година и више по служби њиховој по редовима њиховијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'И породици њиховој, свој дјеци њиховој, женама њиховијем, синовима њиховијем и кћерима њиховијем, свему мноштву; јер се вјерно посветише светињи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'И синовима Ароновијем свештеницима у подграђима градова њиховијех, по свијем градовима, људи именовани даваху дијелове свакоме мушкарцу између свештеника и свакому рода Левитскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'И тако учини Језекија у свој земљи Јудиној; и чињаше што је добро и право и истинито пред Господом Богом његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'И у сваку послу који поче за службу дома Божијега и у закону и у заповијести тражећи Бога својега, труђаше се свијем срцем својим, и срећан бијаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Послије тијех ствари и пошто се оне утврдише, дође Сенахирим цар Асирски, и уђе у земљу Јудину, и опколи тврде градове, и мишљаше их освојити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'А кад видје Језекија гдје дође Сенахирим и гдје се окрену да удари на Јерусалим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Учини вијеће с кнезовима својим и с јунацима својим да зарони изворе водене, који бијаху иза града, и помогоше му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Јер се сабра мноштво народа, те заронише све изворе и поток који тече посред земље говорећи: зашто кад дођу цареви Асирски да нађу толико воде?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'И охрабри се, те озида вас зид оборени, и подиже куле, и споља озида још један зид; и утврди Милон у граду Давидову, и начини много оружја и штитова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'И постави војводе над народом, и сабра их к себи на улицу код врата градских, и говори им љубазно и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Будите слободни и храбри, не бојте се и не плашите се цара Асирскога ни свега мноштва што је с њим, јер је с нама већи него с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'С њим је мишица тјелесна а с нама је Господ Бог наш да нам поможе и да бије наше бојеве. И народ се ослони на ријечи Језекије цара Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Потом Сенахирим цар Асирски док бјеше на Лахису са свом силом својом, посла слуге своје у Јерусалим к Језекији цару Јудину и ка свему народу Јудину који бјеше у Јерусалиму, и поручи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Овако вели Сенахирим цар Асирски: у што се уздате, те стојите у Јерусалиму затворени?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Не наговара ли вас Језекија да вас помори глађу и жеђу говорећи: Господ Бог наш избавиће нас из руке цара Асирскога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Није ли тај Језекија оборио висине његове и олтаре његове, и заповједио Јуди и Јерусалимљанима говорећи: клањајте се само пред једнијем олтаром и на њему кадите?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Еда ли не знате шта сам учинио ја и моји стари од свијех народа на земљи? јесу ли богови народа земаљских могли избавити земљу своју из мојих руку?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Који је између свијех богова онијех народа које затрше оци моји, могао избавити свој народ из мојих руку, да би могао ваш бог вас избавити из моје руке?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Немојте дакле да вас вара Језекија и да вас тако наговара, и не вјерујте му; јер ниједан бог ниједнога народа или царства није могао избавити народа својега из мојих руку ни из руку мојих отаца, акамоли ће ваши богови избавити вас из мојих руку?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'И још више говорише слуге његове на Господа Бога и на Језекију слугу његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'А и књигу написа ружећи Господа Бога Израиљева и говорећи на њ ријечима: као што богови народа земаљских нијесу избавили својега народа из мојих руку, тако неће ни Бог Језекијин избавити народа својега из мојих руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'И виках иза гласа Јудејски народу Јерусалимском који бијаше на зиду да их уплаше и смету да би узели град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'И говораху о Богу Јерусалимском као о боговима народа земаљских, који су дјело руку човјечијих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Тада се помоли тога ради цар Језекија и пророк Исаија син Амосов, и вапише к небу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'И посла Господ анђела, који поби све јунаке и војводе и кнезове у војсци цара Асирскога, те се врати са срамотом у своју земљу. И кад уђе у кућу својега бога, убише га ондје мачем који изидоше из бедара његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Тако сачува Господ Језекију и народ Јерусалимски од руку Сенахирима цара Асирскога и од руку свијех других, и чува их на све стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'И многи доношаху даре Господу у Јерусалим и закладе Језекији цару Јудину; и од тада се узвиси пред свијем народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'У то вријеме разбоље се Језекија на смрт, и помоли се Господу, који му проговори и учини му чудо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Али Језекија не поступи према добру које му се учини, јер се понесе срце његово; зато се подиже на њ гњев и на Јуду и на Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Али се понизи Језекија зато што се бјеше понијело срце његово, и он и Јерусалимљани, те не дође на њих гњев Господњи за живота Језекијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'А имаше Језекија врло велико благо и славу; и начини себи ризнице за сребро и злато и за драго камење и за мирисе и за штитове и за свакојаке закладе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'И стаје за доходе од жита и од вина и од уља, и стаје за свакојаку стоку, и торове за овце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'И градове сазида себи, и имаше много стоке, и оваца и говеда, јер му Бог даде веома велико благо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Исти Језекија загради горњи извор воде Гиона, и право је сведе доље на западну страну града Давидова; и бијаше срећан Језекија у сваком послу свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Само кад дођоше посланици кнезова Вавилонских, који послаше к њему да распитају за чудо које би у земљи, остави га Бог да би га искушао да би се знало све што му је у срцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'А остала дјела Језекијина и милости његове, ето, то је записано у утвари пророка Исаије сина Амосова и у књизи о царевима Јудинијем и Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'И почину Језекија код отаца својих, и погребоше га више гробова синова Давидовијех; и учинише му на смрти част сви Јудејци и Јерусалимљани. А на његово се мјесто зацари Манасија син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Дванаест година бјеше Манасији кад поче царовати, и царова педесет и пет година у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'А чињаше што је зло пред Господом по гаднијем дјелима онијех народа које одагна Господ испред синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Јер опет погради висине, које бјеше раскопао Језекија отац његов, и подиже олтаре Валима, и начини лугове, и клањаше се свој војсци небеској и служаше јој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Начини олтаре и у дому Господњем, за који бјеше рекао Господ: у Јерусалиму ће бити име моје довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Начини олтаре свој војсци небеској у два тријема дома Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'И проводи синове своје кроз огањ у долини сина Еномова, и гледаше на времена и гаташе и врачаше, и уреди оне што се договарају с духовима и врачаре, и чињаше врло много што је зло пред Господом гњевећи га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'И постави лик резан који начини у дому Божијем, за који бјеше рекао Бог Давиду и Соломуну сину његову: у овом дому и у Јерусалиму, који изабрах између свијех племена Израиљевијех, намјестићу име своје довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'И нећу више кренути ноге синовима Израиљевијем из земље коју сам одредио оцима вашим, ако само уздрже и устворе све што сам им заповједио преко Мојсија, сав закон и уредбе и судове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Али Манасија заведе Јуду и Јерусалим, те чинише горе него народи које истријеби Господ испред синова Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'И Господ говораше Манасији и народу његову, али не хтјеше слушати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Зато доведе Господ на њих главаре од војске цара Асирскога, и ухватише Манасију у трњу, и свезавши га у двоје вериге мједене одведоше га у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'И кад бијаше у невољи, мољаше се Господу Богу својему, и понизи се веома пред Богом отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'И молећи се умоли му се, те услиши молитву његову и поврати га у Јерусалим на царство његово. Тада позна Манасија да је Господ Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'А послије тога озида зид иза града Давидова са запада Гиону, од самога потока па до рибљих врата и око Офила, и изведе га врло високо; и постави војводе по свијем тврдијем градовима Јудинијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'И изнесе из дома Господњега богове туђе и лик и све олтаре које бјеше начинио на гори дома Господњега и у Јерусалиму, и баци иза града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Па оправи олтар Господњи и принесе на њему жртве захвалне и у славу, и заповједи Јудејцима да служе Господу Богу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Али народ још приношаше жртве на висинама, али само Господу Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'А остала дјела Манасијина и молитва његова Богу његову и ријечи које му говорише видиоци у име Господа Бога Израиљева, то је све у књизи о царевима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'А молитва његова и како се умолио, и сви гријеси његови и пријеступи, и мјеста гдје је поградио висине и подигао лугове и ликове резане прије него се понизи, то је све записано у књигама пророчким.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'И почину Манасија код отаца својих, и погребоше га у дому његову. А на његово се мјесто зацари Амон син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Двадесет и двије године имаше Амон кад поче царовати, и царова двије године у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'И чињаше што је зло пред Господом као што је чинио Манасија отац му; јер свијем ликовима резанијем, које начини Манасија отац његов, приношаше Амон жртве и служаше им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Али се не понизи пред Господом, као што се понизи Манасија отац његов; него исти Амон још више гријешаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'И побунише се на њ слуге његове, и убише га у кући његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Тада поби народ земаљски све који се бијаху побунили на цара Амона, и зацари народ земаљски Јосију сина његова на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Осам година бјеше Јосији кад поче царовати, и царова тридесет и једну годину у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Он чињаше што је право пред Господом и хођаше путовима Давида оца својега и не отступаше ни надесно ни налијево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Јер осме године царовања својега, док још бјеше дијете, поче тражити Бога Давида оца својега; а дванаесте године поче чистити Јудеју и Јерусалим од висина и од лугова и од ликова резанијех и ливенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Јер пред њим раскопаше олтаре Валима, и ликове сунчане који бијаху на њима исијече, и гајеве, и ликове резане и ливене изломи и сатр, и разасу по гробовима онијех који им приносише жртве;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'А кости свештеничке сажеже на олтарима њиховијем; и очисти Јудеју и Јерусалим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Тако и градове Манасијине и Јефремове и Симеунове и до Нефталима, и пустоши њихове унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'И тако обори олтаре и гајеве, и ликове изломи и сатр, и све ликове сунчане исијече по свој земљи Израиљевој; потом се врати у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'А осамнаесте године царовања својега пошто очисти земљу и дом, посла Сафана сина Азалијина и Масију заповједника градскога и Јоаха сина Јоахазова, паметара, да се оправи дом Господа Бога његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'И они отидоше ка Хелкији поглавару свештеничком, и предаше новце донесене у дом Божји, које скупише Левити вратари од синова Манасијиних и Јефремовијех и од свега остатка Израиљева, и од свега Јуде и Венијамина, па се вратише у Јерусалим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'И дадоше настојницима над послом, који бијаху над домом Господњим, а они их даваху посленицима који рађаху у дому Господњем оправљајући што је трошно и утврђујући дом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'Даваху дрводјељама и каменарима да се купује камење тесано и дрво за греде и да се побрвнају куће које бијаху развалили цареви Јудини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'А ти људи рађаху вјерно посао; и над њима бијаху постављени Јат и Овадија Левити од синова Мераријевих, и Захарија и Месулам од синова Катовијех да настоје око посла; и ти Левити сви умијаху ударати у справе музичке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'И бијаху над носиоцима и над свијем посленицима у свакој служби, и писари и управитељи и вратари бијаху Левити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'И кад изношаху новце донесене у дом Господњи, нађе Хелкија свештеник књигу закона Господњега данога преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'И каза Хелкија Сафану писару и рече: нађох законик у дому Господњем. И даде Хелкија књигу Сафану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'А Сафан однесе књигу цару и јави му говорећи: слуге твоје раде све што им је заповјеђено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Јер покупивши новце што се нађоше у дому Господњем, дадоше их настојницима и посленицима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'И још каза Сафан писар цару говорећи: књигу ми даде Хелкија свештеник. И прочита је Сафан цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'А кад цар чу шта говори закон, раздрије хаљине своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'И заповједи цар Хелкији и Ахикаму сину Сафанову и Авдону сину Михејину и Сафану писару и Асаји слузи цареву, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Идите упитајте Господа за ме и за остатак у Израиљу и Јуди ради ријечи књиге ове што се нађе, јер је велик гњев Господњи који се излио на нас зато што оци наши не држаше ријечи Господње да чине све онако како је написано у овој књизи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'И тако отиде Хелкија и људи цареви к Олди пророчици, жени Салума сина Текуја сина Асре ризничара, а она сјеђаше у Јерусалиму у другом крају, и говорише с њом о том.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'А она им рече: овако вели Господ Бог Израиљев: кажите човјеку који вас је послао к мени:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Овако вели Господ: ево пустићу зло на то мјесто и на становнике његове, све клетве написане у књизи, коју су прочитали цару Јудину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Зато што ме оставише и кадише другим боговима да би ме гњевили свијем дјелима руку својих, зато ће се излити гњев мој на то мјесто и неће с угасити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'А цару Јудину који вас је послао да упитате Господа, овако му реците: овако вели Господ Бог Израиљев за ријечи које си чуо:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Што је одмекнуло срце твоје и понизио си се пред Богом кад си чуо што је рекао за то мјесто и за становнике његове, и понизивши се преда мном раздро си хаљине своје и плакао преда мном, зато и ја услиших тебе, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Ево, ја ћу те прибрати к оцима твојим, и на миру ћеш бити прибран у гроб свој, и нећеш видјети својим очима зла које ћу пустити на то мјесто и на становнике његове. И казаше то цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Тада посла цар те скупи све старјешине Јудине и Јерусалимске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'И отиде цар у дом Господњи и сви људи из земље Јудине и Јерусалимљани, и свештеници и Левити и вас народ, мало и велико, и прочита им све ријечи књиге завјетне, која се нађе у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'И цар стојећи на свом мјесту зададе вјеру пред Господом да ће ићи за Господом и држати заповијести његове и свједочанства његова и уредбе његове свијем срцем и свом душом својом вршећи ријечи тога завјета написане у тој књизи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'И каза, те присташе сви који се нађоше у Јерусалиму и у племену Венијаминову; и чињаху Јерусалимљани по завјету Бога Бога отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'И укиде Јосија све гадове по свијем крајевима синова Израиљевих, и учини, те сви који бијаху у Израиљу служаху Господу Богу својему. Свега вијека његова не отступише од Господа Бога отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'И празнова Јосија у Јерусалиму пасху Господу; и клаше пасху четрнаестога дана првога мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'И постави свештенике у службе њихове, и утврди их да служе у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'И рече Левитима, који учаху вас народ Израиљев и бијаху посвећени Господу: намјестих свети ковчег у дому који је сазидао Соломун син Давидов цар Израиљев, не треба више да га носите на раменима; сада служите Господу Богу својему и народу његову Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'И приправите се по домовима отаца својих по редовима својим како је наредио Давид цар Израиљев и Соломун син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'И стојте у светињи по редовима домова отачких браће своје, синова народнијех, и по редовима домова отачких међу Левитима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'И тако закољите пасху, и освештајте се и приправите браћу своју да би чинили како је рекао Господ преко Мојсија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'И Јосија даде народу од стоке јагањаца и јарића, све за пасху, свјема који бијаху ондје, на број двије тисуће и шест стотина, и три тисуће говеда, све од царева блага.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'И кнезови његови дадоше драговољно народу, свештеницима и Левитима: Хелкија и Захарија и Јехило старјешине у дому Божијем дадоше свештеницима за пасху двије тисуће и шест стотина јагањаца и јарића и три стотине говеда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Хонанија и Семаја и Натанаило браћа његова, и Асавија и Јеило и Јозавад, поглавари Левитски дадоше Левитима за пасху пет тисућа јагањаца и јарића, и пет стотина говеда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'И кад би спремљено за службу, стадоше свештеници на своје мјесто и Левити у редовима својим по заповијести царевој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'И клаху пасху, и свештеници кропљаху крвљу примајући из њиховијех руку, а Левити дераху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'И одвојише жртву паљеницу да даду народу по редовима домова отачких да се принесе Господу, како је написано у књизи Мојсијевој. Тако учинише и с говедима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'И пекоше пасху на огњу по обичају; а друге посвећене ствари кухаше у лонцима и у котловима и у тавама, и раздаваше брзо свему народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Потом готовише себи и свештеницима; јер свештеници синови Аронови имаху посла око жртава паљеница и претилина до ноћи; зато Левити готовише и себи и свештеницима синовима Ароновијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'И пјевачи синови Асафови стајаху на свом мјесту по заповијести Давидовој и Асафовој и Емановој и Једутуна видиоца царева; и вратари на сваким вратима; не мицаху се од службе своје, него браћа њихова, остали Левити, готовише им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Тако би уређена сва служба Господња у онај дан да се прослави пасха и принесу жртве паљенице на олтару Господњем по заповијести цара Јосије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'И празноваше синови Израиљеви који се нађоше ондје пасху у то вријеме и празник пријесних хљебова седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'И не би пасха празнована као ова у Израиљу од времена Самуила пророка, нити који царева Израиљевијех празнова пасху као што је празнова Јосија са свештеницима и Левитима и са свијем Јудом и Израиљем што га се нађе, и с Јерусалимљанима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Осамнаесте године царовања Јосијина празнована би та пасху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Послије свега тога, кад Јосија уреди дом, дође Нехаон цар Мисирски да бије Харкемис на Ефрату, и Јосија изиде преда њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'А он посла к њему посланике и поручи: шта ја имам с тобом, царе Јудин? не идем ја данас на тебе, него на дом који војује на мене, и Бог ми је заповједио да похитам. Прођи се Бога који је са мном, да те не убије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Али се Јосија не одврати од њега, него се преобуче да се бије с њим, и не послуша ријечи Нехаоновијех из уста Божјих, него дође да се побије у пољу Мегидонском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'И стријелци устријелише цара Јосију, и цар рече слугама својим: извезите ме одавде, јер сам љуто рањен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'И скидоше га слуге његове с кола, и метнуше на друга кола која имаше, и одвезоше га у Јерусалим; и умрије, и би погребан у гробљу отаца својих. И сав Јуда и Јерусалим плака за Јосијом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'И пророк Јеремија нарица за Јосијом. И сви пјевачи и пјевачице спомињаше у тужбалицама својим Јосију до данашњег дана, и уведоше их у обичај у Израиљу, и ето написане су у плачу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'А остала дјела Јосијина и милостиње његове, како пише у закону Господњем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'Дјела његова прва и пошљедња, ето записана су у књизи о царевима Израиљевијем и Јудинијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Тада узе народ земаљски Јоахаза сина Јосијина, и зацарише га мјесто оца његова у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Двадесет и три године имаше Јоахаз кад поче царовати, и царова три мјесеца у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Јер га сврже цар Мисирски у Јерусалиму и оглоби земљу сто таланата сребра и таланат злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'И постави цар Мисирски Елијакама брата његова царем над Јудом и Јерусалимом, и предје му име Јоаким; а Јоахаза брата његова узе Нехаон и одведе га у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Двадесет и пет година бијаше Јоакиму кад поче царовати, и царова једанаест година у Јерусалиму; и чињаше зло пред Господом Богом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'И дође на њ Навуходоносор цар Вавилонски, и свеза га у двоје вериге мједене и одведе га у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'И судове дома Господњега однесе Навуходоносор у Вавилон, и метну их у цркву своју у Вавилону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'А остала дјела Јоакимова и гадове које је чинио, и што се на њему нађе, ето, то је записано у књизи о царевима Израиљевијем и Јудинијем; и зацари се на његово мјесто Јоахин син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Бијаше Јоахину осам година кад поче царовати, и царова три мјесеца и десет дана у Јерусалиму; и чињаше што је зло пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'И кад прође она година, посла цар Навуходоносор, те га однесоше у Вавилон са закладама дома Господњега, а царем постави Седекију брата његова над Јудом и Јерусалимом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Двадесет и једна година бијаше Седекији кад поче царовати, и царова једанаест година у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'И чињаше зло пред Господом Богом својим, и не покори се пред Јеремијом пророком, који му говораше из уста Господњих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Него се још одврже од цара Навуходоносора, који га бјеше заклео Богом; и отврдну вратом својим и уприје се срцем својим да се не обрати ка Господу Богу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'И сви главари између свештеника и народ гријешаше веома много по свијем гаднијем дјелима другијех народа, скврнећи дом Господњи, који бјеше осветио у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'И Господ Бог отаца њиховијех слаше к њима зарана једнако гласнике своје, јер му бјеше жао народа његова и стана његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'А они се ругаху гласницима Божјим, и не мараху за ријечи његове, и смијаху се пророцима његовијем, докле се не распали гњев Господњи на народ његов, те не би лијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'И доведе на њих цара Халдејскога, који поби младиће њихове мачем у дому светиње њихове, и не пожали ни младића ни дјевојке, ни старца ни немоћна. Све му даде у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'И све судове дома Божијега, велике и мале, и благо дома Господњега и благо царево и кнезова његовијех, све однесе у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'И упалише дом Божји, и развалише зид Јерусалимски, и све дворове у њему попалише огњем, и искварише све драгоцјене закладе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'И што их оста од мача, однесе у Вавилон и бише робови њему и синовима његовијем, докле не наста царство Персијско,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Да се испуни ријеч Господња коју рече устима Јеремијинијем, докле се земља не издовољи суботама својим, јер почиваше све вријеме докле бјеше пуста, докле се не наврши седамдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Али прве године Кира цара Персијскога, да би се испунила ријеч Господња коју рече на уста Јеремијина, подиже Господ дух Кира цара Персијскога, те огласи по свему царству својему и расписа говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Овако вели Кир цар Персијски: сва царства земаљска дао ми је Господ Бог небески, и он ми је заповједио да му сазидам дом у Јерусалиму у Јудеји. Ко је између вас од свега народа његова? Господ Бог његов нека буде с њим, па нек иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Прве године Кира цара Персијскога, да би се испунила ријеч Господња, коју рече на уста Јеремијина, подиже Господ дух Кира цара Персијскога, те огласи по свему царству својему и расписа говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Овако вели Кир цар Персијски: сва царства земаљска дао ми је Господ Бог небески, и он ми је заповједио да му сазидам дом у Јерусалиму у Јудеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Ко је између вас од свега народа његова? Бог небески нека буде с њим, па нек иде у Јерусалим у Јудеји, и нека зида дом Господа Бога Израиљева, Бога који је у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'А ко би остао у којем год мјесту гдје се бави, нека га људи онога мјеста потпомогну сребром и златом и имањем и стоком осим драговољнога прилога на дом Божји у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Тада усташе главари породица отачких од Јуде и Венијамина, и свештеници и Левити и сви којима Бог подиже дух да иду да зидају дом Господњи у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'И потпомогоше их сви који бијаху око њих судовима сребрнијем и златнијем, имањем и стоком и стварима скупоцјенијем осим свега што драговољно приложише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'И цар Кир издаде судове дома Господњега које бијаше однио из Јерусалима цар Навуходоносор и метнуо у дом својих богова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'А издаде их Кир цар Персијски преко Митридата ризничара, који их изброји Сасавасару кнезу Јудејском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'А ово им је број: здјела златнијех тридесет, здјела сребрнијех тисућа, ножева двадесет и девет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Чаша златнијех тридесет, других чаша сребрнијех четири стотине и десет, других судова тисућа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Свега судова златнијех и сребрнијех пет тисућа и четири стотине; све то понесе Сасавасар кад се врати из Вавилона у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'А ово су људи оне земље што пођоше из ропства од онијех који бише пресељени, које пресели Навуходоносор цар Вавилонски у Вавилон, и вратише се у Јерусалим и у Јудеју, сваки у свој град:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Који дођоше са Зоровавељем, с Исусом, Немијом, Серајом, Релајом, Мардохејем, Вилсаном, Миспаром, Вигвајем, Реумом и Ваном; на број бјеше људи народа Израиљева:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Синова Фаросовијех двије тисуће, сто и седамдесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Синова Сефатијиних триста и седамдесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Синова Араховијех седам стотина и седамдесет и пет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Синова Фат-Моавовијех, од синова Исусовијех и Јоавовијех, двије тисуће осам стотина и дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Синова Еламовијех тисућа и двјеста и педесет и четири;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Синова Затујевих девет стотина и четрдесет и пет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Синова Захајевих седам стотина и шездесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Синова Ванијевих шест стотина и четрдесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Синова Вивајевих шест стотина и двадесет и три;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Синова Азгадовијех тисућа и двјеста и двадесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Синова Адоникамових шест стотина и шездесет и шест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Синова Вигвајевих двије тисуће педесет и шест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Синова Адиновијех четири стотине и педесет и четири;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Синова Атировијех од Језекије двадесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Синова Висајевих триста и двадесет и три;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Синова Јоринијех сто и дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Синова Асумовијех двјеста и двадесет и три;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Синова Гиваровијех двадесет и пет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Синова Витлејемских сто и двадесет и три;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Људи из Нетофата педесет и шест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Људи из Анатота сто и двадесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Синова Азмаветских четрдесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Синова Киријат-Аримских, Хефирских и Виротских седам стотина и четрдесет и три;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Синова Рамских и Гавајских шест стотина и двадесет и један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Људи из Михмаса сто и двадесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Људи из Ветиља и Гаја двјеста и двадесет и три;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Синова Невонских педесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Синова Магвисових сто и педесет и шест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'Синова Елама другога тисућа и двјеста и педесет и четири;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Синова Харимовијех триста и двадесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Синова Лодских, Адидских и Ононских седам стотина и двадесет и пет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Синова Јерихонских триста и четрдесет и пет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Синова Сенајских три тисуће и шест стотина и тридесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Свештеника: синова Једајиних од дома Исусова девет стотина и седамдесет и три;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Синова Имировијех тисућа и педесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Синова Пасхоровијех тисућа и двјеста и четрдесет и седам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Синова Харимовијех тисућа и седамнаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Левита: синова Исусових и Кадмилових између синова Одујиних седамдесет и четири;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Пјевача: синова Асафовијех сто и двадесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Синова вратарских: синова Салумовијех, синова Атировијех, синова Талмоновијех, синова Акувовијех, синова Атитиних, синова Совајевих, свега сто и тридесет и девет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Нетинеја: синова Сишинијех, синова Асуфинијех, синова Таваотовијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Синова Киросовијех, синова Сијајиних, синова Фадонових,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Синова Леваниних, синова Агавиних, синова Акувових,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Синова Агавовијех, синова Самлајевих, синова Анановијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Синова Гидиловијех, синова Гаровијех, синова Реајиних,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Синова Ресиновијех, синова Некодинијех, синова Газамовијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Синова Узинијех, синова Фасејиних, синова Висајевих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Синова Асениних, синова Меунимовијех, синова Нефусимовијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Синова Ваквуковијех, синова Акуфинијех, синова Аруровијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Синова Васлитовијех, синова Меидинијех, синова Арсинијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Синова Варкосовијех, синова Сисаринијех, синова Таминијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Синова Несијиних, синова Атифинијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Синова слуга Соломуновијех: синова Сотајевих, синова Соферетовијех, синова Ферудинијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Синова Јалинијех, синова Дарконовијех, синова Гидиловијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Синова Сефатијинијех, синова Атиловијех, синова Фохерета од Севајима, синова Амијевијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Свега Нетинеја и синова слуга Соломуновијех триста и деведесет и два.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'И ови пођоше из Тел-Мелаха и Тел-Арисе, Херув, Адан и Имир, али не могоше показати отачкога дома својега и сјемена својега, еда ли су од Израиља,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'И синови Делајини, синови Товијини, синови Некодини, њих шест стотина и педесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'И од синова свештеничких: синови Авајини, синови Акосови, синови Варзелаја, који се ожени једном између кћери Варзелаја Галађанина, те се прозва њиховијем именом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Они тражише по књигама да би показали род свој, али се не нађоше, зато бише одлучени од свештенства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'И запријети им Тирсата да не једу од светиње над светињама докле не настане свештеник с Уримом и Тумимом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Свега збора скупа бјеше четрдесет и двије тисуће и три стотине и шездесет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'Осим слуга њиховијех и слушкиња њиховијех, којих бијаше седам тисућа и три стотине и тридесет и седам, а међу њима бијаше двјеста пјевача и пјевачица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Имаху седам стотина и тридесет шест коња, двјеста и четрдесет и пет масака,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'Четири стотине и тридесет и пет камила, шест тисућа и седам стотина и двадесет магараца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'И неки између домова отачких дошавши к дому Господњему и Јерусалиму приложише драговољно да се гради дом Божји на свом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'По могућству својему дадоше у ризницу за посао: злата шездесет и једну тисућу драма, сребра пет тисућа мина, и хаљина свештеничких стотину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'И тако се населише свештеници и Левити и неки из народа и пјевачи и вратари и Нетинеји у градовима својим, и сав Израиљ у својим градовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'А кад дође седми мјесец и синови Израиљеви бијаху у својим градовима, сабра се народ једнодушно у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Тада уста Исус син Јоседеков с браћом својом свештеницима и Зоровавељ син Салатилов с браћом својом, и зградише олтар Бога Израиљева да приносе на њему жртве паљенице како пише у закону Мојсија човјека Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'И подигоше олтар на мјесту његову, ако и бијаху у страху од народа земаљских; и приносише на њему жртве паљенице Господу, жртве паљенице јутром и вечером;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'И празноваше празник сјеница, како је писано, приносећи жртве паљенице сваки дан на број како је уређено за сваки дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'А потом приносише жртву паљеницу свагдашњу, и на младине и на све празнике Господње освећене и од свакога који драговољно приношаше принос Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Од првога дана мјесеца седмога почеше приносити жртве паљенице Господу, а дом Господњи још не бјеше основан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'И дадоше новце каменарима и дрводјељама, и храну и пиће и уље Сидоњанима и Тирцима да довозе дрва кедрова с Ливана у море Јопско, како им бјеше пустио Кир цар Персијски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'И друге године по повратку њихову к дому Божијему у Јерусалим, другога мјесеца почеше Зоровавељ син Салатилов и Исус син Јоседеков и остала браћа њихова, свештеници и Левити, и сви који дођоше из ропства у Јерусалим и поставише Левите од двадесет година и више да настоје над послом око дома Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'И би постављен Исус и синови његови и браћа његова, и Кадмило и синови његови, синови Јудини, заједно да настоје над посленицима у дому Божијем, и синови Инададови и њихови синови и браћа њихова Левити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'И кад зидари полагаху темељ цркви Господњој, поставише свештенике обучене с трубама и Левите синове Асафове с кимвалима да хвале Господа по уредби Давида цара Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'И пјеваху наизмјенце хвалећи и славећи Господа: јер је довијека милост његова над Израиљем. И сав народ подвикиваше иза гласа хвалећи Господа што се осниваше дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'А многи од свештеника и Левита и главара домова отачких старци који бијаху видјели пређашњи дом, плакаху иза гласа гледајући овај дом који се осниваше, а многи опет подвикиваху од радости,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Те народ не могаше разазнати вике радосне од вике плачне у народу, јер народ подвикиваше иза гласа, и вика се чујаше далеко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'А кад чуше непријатељи Јудини и Венијаминови да они који се вратише из ропства зидају цркву Господу Богу Израиљеву,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Дођоше к Зоровавељу и ка главарима домова отачких, и рекоше им: да и ми зидамо с вама, јер ћемо као и ви тражити Бога вашега, и њему приносимо жртве од времена Есарадона цара Асирскога, који нас је довео овамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'А Зоровавељ и Исус и остали главари домова отачких у Израиљу рекоше им: не можете ви с нама зидати дома Богу нашему, него ћемо ми сами зидати Господу Богу Израиљу, како нам је заповједио Кир цар Персијски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Тада народ земаљски досађиваше народу Јудину и сметаше их у зидању;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'И наимаху савјетнике супрот њима да расипају намјеру њихову свега времена Кира цара Персијскога до владе Дарија цара Персијскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'А кад се зацари Асвир, у почетку његова царовања написаше тужбу на становнике Јудејске и Јерусалимске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'И за времена Артаксерксова писа Вислам, Митредат, Тавеило и остали другови његови Артаксерксу цару Персијском; а књига бјеше писана Сирским писмом и Сирским језиком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Реум старјешина у вијећу и Симсај писар написаше једну књигу против Јерусалима цару Артаксерксу овако:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Реум старјешина у вијећу и Симсај писар и остали другови њихови, Дињани, Афарсашани, Тарфаљани, Афаршани, Архевљани, Вавилоњани, Сусанашани, Деављани, Еламљани,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'И остали народ који пресели велики и славни Асенафар и насели по градовима Самаријским, и остали с ове стране ријеке, тада и тада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Ово је пријепис од књиге коју му послаше: Цару Артаксерксу. Слуге твоје, људи с ове стране ријеке, тада и тада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Да је на знање цару да Јудејци који пођоше од тебе к нама, дођоше у Јерусалим, и град одметнички и опаки зидају, зидове оправљају и из темеља подижу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Него да је на знање цару: ако се овај град сазида и зидови оправе, они неће давати данка ни порезе ни царине, те ће бити штета ризници царској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Што дакле плату од двора примамо, те нам не приличи да гледамо штету цареву, тога ради шаљемо и јављамо цару,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Да се потражи у књизи дневника отаца твојих, па ћеш наћи у књизи дневника и дознати да је овај град одметнички и да је на штету царевима и земљама и да су се у њему дизале буне од давнина, те зато би раскопан овај град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Дајемо на знање цару: ако се овај град сазида и зидови се његови оправе, онда овај дио преко ријеке неће више бити твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Тада цар посла одговор Реуму старјешини у вијећу и Симсају писару и осталијем друговима њиховијем који сеђаху у Самарији и осталијем с ону страну ријеке: Поздравље, тада и тада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'Књига коју нам посласте разговијетно би прочитана преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'И заповједих те потражише и нађоше да је тај град од давнина устајао на цареве и да су у њему бивали одмети и буне,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'И да су силни цареви бивали у Јерусалиму, који владаху свијем што је преко ријеке, и даваху им се данци и порезе и царине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Зато наредите да се забрани онијем људима да се онај град не зида докле ја не заповједим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'И пазите да не погријешите у том. Јер зашто би зло расло на штету царевима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'А кад се пријепис од књиге цара Артаксеркса прочита пред Реумом и Симсајем писарем и пред друговима њиховијем, они брже отидоше у Јерусалим к Јудејцима, те им забранише оружаном силом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Тада стаде посао око дома Божијега у Јерусалиму, и стаја до друге године царовања Дарија цара Персијскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Тада Агеј пророк и Захарија син Идов пророк пророковаху Јудејцима који бијаху у Јудеји и у Јерусалиму у име Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'И уста Зоровавељ син Салатилов И Исус син Јоседеков, и почеше опет зидати дом Божји у Јерусалиму, и бјеху с њима пророци Божји помажући им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'У то вријеме дође к њима Татнај управитељ с ову страну ријеке, и Сетар-Воснај и другови њихови, и рекоше им овако: ко вам је дао власт да зидате ту кућу и да оправљате те зидове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Тада им одговорисмо именујући људе који грађаху ту грађевину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Али бјеше око Божје на старјешинама Јудејским, те им не забранише докле не отиде ствар до Дарија и донесу одговор о том.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'А ово је пријепис од књиге који посла цару Дарију Татнај управитељ с ове стране ријеке и Сетар-Воснај с друговима својим Афарсашанима који бијаху с ове стране ријеке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Послаше му књигу, а у њојзи бјеше написано овако: Дарију цару свако добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Да је на знање цару да дођосмо у Јудејску земљу к дому Бога великога, који зидају од великога камена, и дрвље мећу у зидове, и посао се брзо ради и напредује у рукама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'И запитасмо тамошње старјешине рекавши им: ко вам је дао власт да зидате тај дом и да оправљате те зидове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Па их и за имена њихова запитасмо да бисмо ти јавили, и записасмо имена онијех који су главари међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'А они нам одговорише овако говорећи: ми смо слуге Бога небескога и земаљскога, и зидамо дом који је био сазидан прије много времена, који је зидао и подигао велики цар Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Али кад оци наши разгњевише Бога небескога, даде их у руке Навуходоносору цару Вавилонском Халдејцу, који раскопа овај дом а народ пресели у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Али прве године Кира цара Вавилонскога, цар Кир заповједи да се сазида овај дом Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Још и судове дома Божијега златне и сребрне које нам Навуходоносор бјеше узео из цркве Јерусалимске и однио у цркву Вавилонску, изнесе их цар Кир из цркве Вавилонске, и бише дани по имену Сасавасару, којега постави управитељем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'И рече му: узми ове судове па иди и однеси их у цркву која је у Јерусалиму, и дом Божји нека се сазида на својем мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Онда тај Сасавасар дође и постави темељ дому Божијему у Јерусалиму; и од тога времена досад зида се и још није довршен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Ако је дакле угодно цару, нека се потражи у ризници царској у Вавилону је ли цар Кир заповједио да се сазида овај дом Божји у Јерусалиму, и вољу своју о том нека нам цар пошље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Тада цар Дарије заповједи те тражише у књижици гдје се остављаше благо у Вавилону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'И нађоше у Ахмети у двору царском у земљи Мидској књигу у којој бјеше записан овај спомен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Прве године цара Кира заповједи цар Кир: дом Божји у Јерусалиму да се сазида да буде мјесто гдје ће се приносити жртве, и темељи да му се изидају, да буде висок шездесет лаката и широк шездесет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Три реда да буду од камења великога и један ред од дрвета новога, а трошак да се даје из царског дома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'И судови дома Божијега златни и сребрни што Навуходоносор бјеше узео из цркве Јерусалимске и донио у Вавилон, да се врате и опет однесу у цркву Јерусалимску на своје мјесто и да се оставе у дому Божијему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Зато Татнају управитељу с оне стране ријеке, Сетар-Воснају с друговима својим Афарсашанима, који сте с оне стране ријеке, уклоните се одатле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Оставите нека се гради тај дом Божји, управитељ Јудејски и старјешине њихове нека зидају тај дом Божји на мјесту његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Још заповједам шта ћете чинити старјешинама Јудејским да би се сазидао тај дом Божји; од блага царскога, од доходака с оне стране ријеке, да се даје без оклијевања трошак онијем људима да се не устављају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'И што треба, било јунаца или овнова или јагањаца за жртве паљенице Богу небескому, или пшенице, соли, вина и уља, како реку свештеници Јерусалимски, да им се даје сваки дан без одгађања,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Да приносе мирисне жртве Богу небескому и да се моле за живот царев и за синова његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Још заповиједам: ко би учинио друкчије, из његове куће да се узме брвно и пободе, и он на њему да се погуби, и његова кућа да буде буниште за то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'И Бог који је ондје настанио име своје, да обори свакога цара и сваки народ који би дигао руку да промијени ово и раскопа тај дом Божји у Јерусалиму. Ја Дарије заповиједам ово, одмах да се изврши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Тада Татнај управитељ с ове стране ријеке, Сетар-Воснај и другови њихови учинише одмах како заповједи Дарије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'И старјешине Јудејске зидаше и напредоваше по пророштву Агеја пророка и Захарије сина Идова, зидаше и довршише по заповијести Бога Израиљева и по заповијести Кира и Дарија и Артаксеркса цара Персијскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'И сврши се тај дом до трећега дана мјесеца Адара шесте године царовања цара Дарија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'И синови Израиљеви, свештеници и Левити и остали између онијех који се вратише из ропства посветише тај дом Божји радујући се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'И принесоше на посвећење тога дома Божијега сто јунаца, двјеста овнова, четири стотине јагањаца и дванаест јараца на жртву за гријех за свега Израиља према броју племена Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'И поставише свештенике по редовима њиховијем и Левите по редовима њиховијем да служе Богу у Јерусалиму како је написано у књизи Мојсијевој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Потом славише који се вратише из ропства пасху четрнаестог дана првога мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Јер се очистише и свештеници и Левити, те бијаху сви чисти, и клаше пасху за све који се вратише из ропства и за браћу своју свештенике и за себе саме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'И једоше синови Израиљеви који се вратише из ропства и сви који се од нечистоте народа земаљских одвојише к њима да траже Господа Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'И празноваше празник пријеснијех хљебова седам дана веселећи се; јер их развесели Господ и обрати срце цара Асирскога к њима да укријепи руке њихове у послу око дома Бога, Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'А послије овијех ствари за царовања Артаксеркса цара Персијскога Јездра, син Сераје сина Азарије, сина Хелкије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'Сина Салума, сина Садока, сина Ахитова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'Сина Амарије, сина Азарије, сина Мерајота,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'Сина Зераје, сина Озије, сина Вукија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'Сина Авузије, сина Финеса, сина Елеазара, сина Арона поглавара свештеничкога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Тај Јездра врати се из Вавилонске, а бијаше књижевник вјешт закону Мојсијеву, који даде Господ Бог Израиљев, и цар му даде све што заиска, јер рука Господа Бога његова бијаше над њим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'И вратише се у Јерусалим неки синови Израиљеви и свештеници и Левити и пјевачи и вратари и Нетинеји седме године цара Артаксеркса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'А дође у Јерусалим петога мјесеца седме године тога цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Јер првога дана првога мјесеца пође из Вавилонске, а првога дана петога мјесеца дође у Јерусалим, јер добра рука Бога његова бјеше над њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Јер Јездра бјеше управио срце своје да истражује закон Господњи и да га извршује и да учи Израиља уредбама и законима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'А ово је пријепис од књиге које даде цар Артаксерксо Јездри свештенику књижевнику вјештому стварима што је заповједио Господ и уредбама његовијем у Израиљу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Артаксерксо цар над царевима Јездри свештенику, књижевнику вјештому у закону Бога небескога, свако добро; тада и тада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Ја заповиједам: ко год у мом царству од народа Израиљева и од свештеника његовијех и Левита хоће од своје воље да иде с тобом у Јерусалим, нек иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Јер се шаљеш од цара и од седам савјетника његовијех да надгледаш Јудеју и Јерусалим по закону Бога својега који ти је у руку,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'И да однесеш сребро и злато што цар и савјетници његови драговољно приносе Богу Израиљеву, којему је стан у Јерусалиму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'И све сребро и злато што накупиш у својој земљи Вавилонској с драговољнијем прилозима које народ и свештеници драговољно приложе на дом Бога својега у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Па одмах за те новце купи јунаца и овнова и јагањца с даровима њиховијем и наљевима њиховијем, и принеси их на олтару дома Бога нашега у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'И што се теби и браћи твојој свиди учинити с осталијем сребром и златом, учините по вољи Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'И судови који су ти дати за службу у дому Бога твојега, остави пред Богом у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'И што би још требало дому Бога твојега, те би ваљало дати, подај из царске ризнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'И још заповједам ја цар Артаксерксо свијем ризничарима с оне стране ријеке, да што год заиште од вас Јездра свештеник, књижевник вјешти закону Бога небескога, одмах да се учини,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'До сто таланата сребра и до сто кора пшенице и до сто вата вина и до сто вата уља, а соли без мјере,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Што год заповједи Бог небески, одмах да се учини за дом Бога небескога, да не дође гњев на царство, на цара и на синове његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'И још вам јављамо да се ни од једнога између свештеника и Левита и пјевача и вратара и Нетинеја и других слуга тога дома Божијега не смије узимати данак ни пореза ни царина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'А ти, Јездра, по мудрости Бога својега која ти је дата постави управитеље и судије да суде свему народу што је с оне стране ријеке између свијех који знаду закон Бога твојега, и ко не зна, учите га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'А ко не би извршивао закона Бога твојега и закона царева, одмах да му се суди, било да се погуби или да се прогна или да се оглоби или да се баци у тамницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Благословен да је Господ Бог отаца наших, који даде то цару у срце да украси дом Господњи у Јерусалиму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'И даде ми, те нађох милост пред царем и савјетницима његовијем и пред свим силнијем кнезовима царевијем. И ја се ослободих, јер рука Господа Бога мојега бјеше нада мном, и скупих главаре из Израиља да иду са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'А ово су главари домова отачких и племе онијех што пођоше са мном из Вавилона за владе цара Артаксеркса:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Од синова Финесовијех Гирсом; од синова Итамаровијех Данило; од синова Давидовијех Хатус;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Од синова Сеханије, који бјеше од синова Фаросовијех, Захарија и с њим на број мушкиња сто и педесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Од синова Фат-Моавовијех Елиоинај син Зерајин и с њим мушкиња двјеста;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Од синова Сеханијиних син Јасилов и с њим мушкиња три стотине;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'И од синова Адиновијех Евед син Јонатанов и с њим мушкиња педесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'И од синова Еламовијех Исаија син Аталијин и с њим мушкиња седамдесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'И од синова Сефатијиних Зевадија син Михаилов и с њим мушкиња осамдесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Од синова Јоавовијех Овадија син Јехилов и с њим мушкиња двјеста и осамдесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'И од синова Селомитовијех син Јосифијин и с њим мушкиња сто и шездесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'И од синова Вивајевих Захарија син Вивајев и с њим мушкиња двадесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'И од синова Азгадовијех Јоанан син Акатанов и с њим мушкиња сто и десет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'И од синова Адоникамовијех пошљедњих по имену Елифелет, Јеило и Семаја и с њима мушкиња шездесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'И од синова Вигвајевих Гутај и Завуд и с њима мушкиња седамдесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'И сабра их код ријеке која тече у Аву, и ондје стајасмо у околу три дана; послије прегледах народ и свештенике, али не нађох ондје ни једнога од синова Левијевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Зато послах Елијезера, Арила, Семају и Елнатана и Јарива и Елнатана и Натана и Захарију и Месулама и главаре, и Јојарива и Елнатана учитеље,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'И оправи их к Иду поглавару у мјесту Касифији, и научих их шта ће говорити Иду и браћи његовој Нетинејима у мјесту Касифији да би нам довели слуге за дом Бога нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'И доведоше нам, јер добра рука Божија бјеше над нама, човјека разумна између синова Малија сина Левија сина Израиљева, Серевију са синовима његовијем и браћом његовом, њих осамнаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'И Асавију и с њим Исаију од синова Мераријевих, с браћом његовом и њиховијем синовима, њих двадесет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'И од Нетинеја, које одреди Давид и кнезови да служе Левитима, двјеста и двадесет Нетинеја, који сви бише именовани поименце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Тада огласих ондје на ријеци Ави пост, да бисмо се понизили пред Богом својим измолили у њега срећан пут себи и дјеци својој и свему благу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Јер ме бијаше стид искати од цара војске и коњика да нас бране од непријатеља путем, јер бијасмо рекли цару говорећи: рука је Бога нашега на добро над свима који га траже, и јачина је његова и гњев на све који га остављају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Тако постисмо и молисмо Бога својега за то, и умолисмо га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Тада одвојих између главара свештеничких дванаест, Серевију, Асавију и с њима десеторицу браће њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'И измјерих им сребро и злато и судове, прилоге дому Бога нашега што приложи цар и савјетници његови и кнезови његови и сав народ Израиљев који се нађе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Измјерих им у руке шест стотина и педесет таланата сребра, и судова сребрнијех сто таланата и сто таланата злата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'И двадесет чаша златнијех од тисућу драма, и два суда од мједи добре и скупоцјене као злато.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'И рекох им: ви сте свети Господу и ови су судови свети, и ово сребро и злато драговољан је прилог Господу Богу отаца ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Пазите и чувајте докле не измјерите пред главарима свештеничким и Левитима и главарима отачких домова Израиљевијех у Јерусалиму у клијетима дома Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'И тако примише свештеници и Левити измјерено сребро и злато и судове да однесу у Јерусалим у дом Бога нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'И пођосмо од ријеке Аве дванаестога дана првога мјесеца да идемо у Јерусалим, и рука Бога нашега бијаше над нама и избави нас из руку непријатељских и засједачких на путу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'И дођосмо у Јерусалим и стајасмо ондје три дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'А четврти дан измјери се сребро и злато и судови у дому Бога нашега у руке Меримоту сину Уријину свештенику, с којим бијаше Елеазар син Финесов, и с њима Јозавад син Исусов и Ноадија син Венујев, Левити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Све на број и на мјеру, и мјера би записана од свега у исто вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'И који бише у ропству па се вратише из ропства принесоше на жртву паљеницу Богу Израиљеву дванаест јунаца за свега Израиља, деведесет и шест овнова, седамдесет и седам јагањаца, дванаест јараца за гријех, све то на жртву паљеницу Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'И предаше заповијести цареве намјесницима царевијем и кнезовима с ове стране ријеке и они потпомогоше народ и дом Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'А кад се то сврши, приступише к мени кнезови говорећи: народ Израиљев и свештеници и Левити нијесу се одвојили од народа земаљских ради гадова њиховијех, од Хананеја, Хетеја, Ферезеја, Јевусеја, Амонаца, Моаваца, Мисираца и Амореја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Јер узеше кћери њихове себи и синовима својим, те се помијеша свето сјеме с народима земаљским; и рука свештеничка и главарска бјеше прва у том пријеступу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'И кад чух то, раздријех хаљину своју и плашт свој, и скубох косу с главе своје и браду своју, и сједох тужан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'И скупише се к мени сви који се бојаху ријечи Бога Израиљева за пријеступ онијех који дођоше из ропства, а ја сјеђах тужан до вечерње жртве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'А о вечерњој жртви устах од јада својега у раздртој хаљини и плашту, клекавши на кољена своја раширих руке своје ка Господу Богу својему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'И рекох: Боже мој! стидим се и срамим се подигнути очи своје к теби, Боже мој; јер безакоња наша намножише се сврх главе и кривице наше нарастоше до неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Од времена отаца својих до данас под кривицом смо великом, и за безакоња своја бисмо предани ми и цареви наши и свештеници наши у руке царевима земаљски под мач, у ропство, у грабеж и у срамоту, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'А сада зачас дође нам милост од Господа Бога нашега, те нам остави остатак и даде нам клин у светом мјесту свом да би просвијетлио очи наше Бог наш и дао нам да мало одахнемо у ропству својем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Јер робље смо, али у ропству нашем није нас оставио Бог наш, него нам даде те нађосмо милост пред царевима Персијским давши нам да одахнемо да подигнемо дом Бога својега и оправимо пустолине његове, и давши нам ограду у Јудеји у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Сада дакле шта да кажемо, Боже наш, послије тога? Јер остависмо заповијести твоје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'Које си заповједио преко слуга својих пророка говорећи: земља у коју идете да је наслиједите земља је нечиста од нечистоте народа земаљских, с гадова њиховијех, којима је напунише од краја до краја у нечистоти својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'И зато кћери својих не дајите за синове њихове, и кћери њиховијех не узимајте за синове своје, и не тражите мира њихова ни добра њихова довијека да бисте се окријепили јели добра оне земље и оставили је у нашљедство синовима својим довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'И послије свега што дође на нас за зла дјела наша и за велику кривицу нашу, јер си нас, Боже наш, покарао мање него што гријеси наши заслужују, и дао си нам остатак оваки,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Еда ли ћемо опет преступати заповијести твоје и пријатељити се с овијем гаднијем народима? Не би ли се разгњевио на нас докле нас не би потро да ни један не остане и не избави се?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Господе Боже Израиљев! ти си праведан, јер остасмо остатак, као што са види данас. Ево ми смо пред тобом с кривицом својом, премда се не може стајати пред тобом за то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'А кад се мољаше Јездра и исповиједаше гријехе плачући и лежећи пред домом Божјим, скупи се к њему из Израиља велико мноштва људи и жена и дјеце; и народ плакаше веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Тада проговори Сеханија син Јехилов од синова Еламовијех и рече Јездри: ми смо сагријешили Богу својему што узесмо жене туђинке из народа земаљских; али још има надања Израиљу за то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Да учинимо завјет Богу својему, да отпустимо све жене и пород њихов по вољи Господњој и онијех који се боје заповијести Бога нашега, и по закону нека буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Устани, јер је ово твој посао; а ми ћемо бити уза те, буди слободан и ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Тада уста Јездра, и закле главаре свештеничке и Левите и свега Израиља да учине тако. И заклеше се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Потом уста Јездра испред дома Божијега, и отиде у клијет Јоанана сина Елиасивова; и ушавши не једе хљеба нити воде пи, јер тужаше ради пријеступа онијех који бише у ропству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Потом огласише по Јудеји и Јерусалиму свијем који се вратише из ропства, да се скупе у Јерусалим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'А ко не би дошао за три дана по договору кнезовском и старјешинском, да се све имање његово разаспе а сам да се одлучи од збора онијех који се вратише из ропства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Тако се скупише сви људи од Јуде и Венијамина у Јерусалим за три дана, мјесеца деветога. И сјеђаше сав народ на улици пред домом Божјим дршћући ради те ствари и од дажда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Тада уставши Јездра свештеник рече им: ви сагријешисте што се оженисте туђинкама, те умножисте кривицу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Зато сада исповједите се Господу Богу отаца својих, и учините вољу његову, и одвојте се од народа земаљских и жена туђинака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'И сав збор одговори и рече иза гласа: како нам каза учинићемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Али народа има много и иде дажд, не може се стајати напољу, а тај посао није за један дан ни за два, јер нас има много који сагријешисмо у том.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Да се одреде кнезови наши из свега збора, па који су год у градовима нашим ожењени туђинкама нека долазе у одређено вријеме и с њима старјешине свакога града и судије докле не одвратимо жестоки гњев Бога својега за ту ствар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'И одређен би на то Јонатан син Асаилов и Јазија син Текујев; а Месулам и Саветај Левити помагаше им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'И учинише тако који се вратише из ропства. И одвојише се Јездра свештеник и главари домова отачких по домовима отаца својих, сви поименце, и сједоше првога дана десетога мјесеца да извиђају ствар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'И до првога дана првога мјесеца свршише са свима онима који се бијаху оженили туђинкама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'А нађоше се између синова свештеничких ожењени туђинкама између синова Исуса сина Јоседекова и браће његове: Масија и Елијезер и Јарив и Гедалија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'И дадоше руке да ће пустити жене своје; и који бијаху згријешили принесоше по једнога овна за кривицу своју;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'И од синова Имировијех Ананије и Зевадија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'И од синова Харимовијех Масија и Илија и Семаја и Јехило и Озија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'И од синова Пасхоровијех Елиоинај, Масија, Исмаило, Натанаило, Јозавад и Еласа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'И од Левита Јозавад и Симеј и Келаја, то је Келита, и Петаја и Јуда и Елијезер;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'И од пјевача Елијасив; и од вратара Салум и Телем и Урија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'А од Израиља, од синова Фаросовијех Рамија и Језија и Малхије и Мијамин и Елеазар и Малхија и Венаја;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'И од синова Еламовијех: Матанија, Захарија и Јехило и Авдија и Јеремот и Илија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'И од синова Затовијех Елиоинај, Елијасив, Матанија и Јеримот и Завад и Азиза;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'И од синова Вивајевијех Јоанан, Ананија, Завај, Атлај,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'И од синова Ванијевих Месулам, Малух и Адаја, Јасув и Сеал и Рамот;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'И од синова Фат-Моавовијех Адна и Хелал, Венаја, Масија, Матанија, Веселеило и Винуј и Манасија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'И од синова Харимовијех Елијезер, Јесија, Малхија, Семаја, Симеун,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Венијамин, Малух, Семарија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Од синова Асумовијех Матенај, Матата, Завад, Елифелет, Јеремај, Манасија, Симеј;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Од синова Ванијевих Мадаја, Амрам и Уило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Венаја, Ведеја, Хелуј,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Ванија, Меримот, Елијасив,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Матнија, Матенај и Јасав,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'И Ваније, Винуј, Симеј,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'И Селемија и Натан и Адаја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Махнадевај, Сасај, Сарај,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Азареило и Селемија, Семарија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Салум, Амарија, Јосиф;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Од синова Невовијех: Јесило, Матанија, Завад, Зевина, Јадав, Јоило и Венаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Сви се ови бијаху оженили туђинкама и неке између њих бијаху и дјецу изродиле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Ријечи Немије сина Ахалијина. Мјесеца Хислева године двадесете кад бијах у Сусану граду,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Дође Ананије један од браће моје с некима из Јудеје; и запитах их за Јудејце, за остатак што бјеше остао од ропства и за Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'А они ми рекоше: остатак што оста од ропства ондје у земљи, у великој је невољи и срамоти, и зид је Јерусалимски разваљен и врата су му огњем попаљена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'А кад чух те ријечи, сједох и плаках, и тужих неколико дана, и постих и молих се пред Богом небеским,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'И рекох: ох Господе Боже небески, Боже велики и страшни, који чуваш завјет и милост онима који те љубе и држе твоје заповијести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Нека буде ухо твоје пригнуто и очи твоје отворене да чујеш молитву слуге својега којом се сада молим пред тобом дан и ноћ за синове Израиљеве, слуге твоје, и исповиједам гријехе синова Израиљевијех којима ти згријешисмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Скривисмо ти и не држасмо заповијести ни уредаба ни закона које си заповиједио преко Мојсија слуге својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Али се опомени ријечи коју си заповједио Мојсију слузи својему говорећи: ви ћете згријешити и ја ћу вас расијати међу народе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Али ако се обратите к мени и станете држати заповијести моје и творити их, ако будете загнани и на крај свијета, сабраћу вас оданде и одвешћу вас на мјесто које сам изабрао да ондје настаним име своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'А ово су слуге твоје и народ твој, који си искупио силом својом великом и руком својом крјепком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Ох Господе! нека буде ухо твоје пригнуто и молитви слуге твојега и к молитви слуге твојега и к молитви слуга твојих, који су ради бојати се имена твојега, и дај данас срећу слузи свјему и учини да нађе милост пред овијем човјеком. А ја бијах пехарник царев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'А мјесеца Нисана године двадесете Артаксеркса цара бијаше вино пред њим, и ја узев вино дадох га цару. А пређе не бијах невесео пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'И рече ми цар: што си лица невесела, кад нијеси болестан? није друго него туга у срцу. А ја се уплаших врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'И рекох цару: да је жив цар довијека! како не бих био лица невесела, кад је град гдје су гробови мојих отаца опустио и врата му огњем спаљена?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'А цар ми рече: шта хоћеш? Тада се помолих Богу небескому,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'И рекох цару: ако је угодно цару и ако ти је мио слуга твој, пошљи ме у Јудеју у град гдје су гробови отаца мојих да га саградим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'А цар ми рече, а жена његова сјеђаше до њега: колико ти времена треба на пут, и кад ћеш се вратити? И би угодно цару, и пусти ме кад му казах вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Потом рекох цару: ако је угодно цару, да ми се да књига на кнезове преко ријеке да ме прате докле не дођем у Јудеју,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'И књига на Асафа чувара шуме цареве да ми да дрва за брвна на врата од двора уз дом Божји и за зид градски и за кућу у коју ћу ући. И даде ми цар, јер добра рука Бога мојега бјеше нада мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'И тако дођох на кнезовима преко ријеке, и дадох им књиге цареве. А цар посла са мном војводе и коњике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'А кад то чу Санавалат Ороњанин и Товија слуга Амонац, би им врло мрско што дође човјек да се постара за добро синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Потом дођох у Јерусалим, и бих ондје три дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'Па устах ноћу с неколико људи, а никому не казах што ми је Бог мој дао у срце да учиним у Јерусалиму; и не имах кљусета са собом осим оног на ком јахах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'И изидох ноћу на врата од долине, на извор змајевски, и на врата гнојна, и разгледах зидове Јерусалимске како бјеху разваљени и како му врата бјеху огњем попаљена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Отуда прођох на изворска врата и на царско језеро, а ондје не бјеше мјеста да кљусе пода мном пријеђе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'За то јахах уз поток по ноћи и разгледах зид, па се вратих на врата од долине, и тако дођох натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Али поглавари не знадијаху куда сам ишао ни шта сам радио, јер дотада не бијах ништа рекао ни Јудејцима ни свештеницима ни кнезовима ни поглаварима ни другима који управљаху послом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Зато им рекох: видите у каквом смо злу, Јерусалим пуст и врата му попаљена огњем; дајте да зидамо зидове Јерусалимске, да више не будемо руг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'И казах им како је добра рука Бога мојега нада мном и ријечи цареве које ми је рекао. Тада рекоше: устанимо и зидајмо. И укријепише им се руке на добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'А кад то чу Санавалат Ороњанин и Товија слуга Амонац и Гисем Арапин, потсмјеваше нам се и ругаше нам се говорећи: шта то радите? да се нећете одметнути цару?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'А ја им одговорих и рекох: Бог небески даће нам срећу, а ми слуге његове устасмо и зидамо; али ви немате дијела ни права ни спомена у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'И уста Елијасив поглавар свештенички и браћа његова свештеници и зидаше врата овчија, и осветише их и метнуше им крила, и осветише их до куле Меје, до куле Ананилове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'А до њега зидаше Јерихоњани, а до њих зида Захур син Имријев;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'А врата рибља зидаше синови Асенајини, они их побрвнаше и метнуше крила и браве и пријеворнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'А од њих оправља Меримот син Урије сина Акосова; а до њих оправља Месулам син Варахије сина Месизавеилова; а до њих оправља Садок син Ванин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'А до њих оправљаше Текојани, али поглавице њихове не савише врата својега на службу Господу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'А стара врата оправља Јодај син Фасејин и Месулам син Весодијин, они их побрвнаше и метнуше крила и браве и пријеворнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'А до њих оправљаше Мелатија Гаваоњанин и Јадон Мероњанин, људи из Гаваона и из Миспе до столице кнеза с ове стране ријеке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'До њих оправља Узило син Арахијин златар; а до њега оправља Ананија син апотекарски. И оставише Јерусалим до широкога зида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'А до њих оправља Рефаја син Оров поглавар над половином краја Јерусалимскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'А до њих оправља Једаја син Арумафов према својој кући, а до њега оправља Хатус син Асавнијин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Толико оправља Малхија сина Харимов и Асув син Фат-Моавов и кулу код пећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'А до њега оправља Салум син Лоисов, поглавар над половином краја Јерусалимскога са кћерима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Врата долинска оправља Анун са становницима Занојским; они их саградише и метнуше крила и браве и пријеворнице, и тисућу лаката зида до гнојнијех врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'А гнојна врата оправља Малхија син Рихавов поглавар над крајем Вет-Керемским, он их сагради и метну крила и браве и пријеворнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'А врата изворска оправља Салум син Хол-Озин, поглавар над крајем у Миспи, он их сагради и покри и метну им крила и браве и пријеворнице; и зид код бање Силоамске од врта царева до басамака који слазе из града Давидова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'За њим оправља Немија син Азвуков поглавар над половином краја Вет-Сурскога до према гробовима Давидовијем и до језера начињенога и до куће јуначке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'За њим оправљаше Левити, Реум син Ванијев, а до њега оправља Асавија поглавар над половином краја Кеилскога са својим крајем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'За њим оправљаше браћа њихова, Вавај син Инададов поглавар над половином краја Кеилскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'А до њега оправља Есер син Исусов поглавар од Миспе толико према мјесту куда се иде к ризницама на углу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'За њим разгоријевши се Варух син Завајев оправља толико од угла до врата од куће Елијасива поглавара свештеничкога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'За њим оправља Меримот син Урије сина Акосова толико од врата куће Елијасивове до краја куће Елијасивове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'А за њим оправљаше свештеници који живљаху у равници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'За њим оправља Венијамин и Асув према својим кућама; а за њим оправља Азарија син Масије сина Ананијина уз своју кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'За њим оправља Винуј син Инададов толико од куће Азаријине до савитка и до угла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Фалал син Узајев оправља према савитку и према кули која се издиже из горњега дома царева код тријема тамничкога; за њим Федаја син Фаросов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'И Нетинеји који живљаху у Офилу, до према вратима воденијем на исток и кули високој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'За њим оправљаше Текојани толико према великој кули високој до зида Офилскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Од врата коњских оправљаше свештеници сваки према својој кући;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'За њима оправља Садок син Имиров према својој кући; а за њим оправља Семаја син Сеханијин чувар врата источнијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'За њим оправља Ананија син Селемијин и Анун шести син Салафов, толико; за њима оправља Месулам син Варахијин према својој клијети;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'За њим оправља Малхија син златарев до куће Нетинејске и трговачке према вратима Мифкадским до узбрдице на углу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'А између узбрдице на углу и овчјих врата оправљаше златари и трговци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'А кад чу Санавалат да зидамо зид, разгњеви се и расрди се врло, и ругаше се Јеврејима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'И говораше пред браћом својом и војницима Самаријским: шта раде ти немоћни Јудејци? хоћемо ли их оставити? хоће ли приносити жртве? хоће ли сада свршити? еда ли ће у живот повратити из праха камење спаљено?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'А Товија Амонац који бијаше уза њ рече: нека зидају; да лисица дође провалиће камени зид њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Чуј, Боже наш, како нас презиру; обрати руг њихов на њихову главу, и дај да буду грабеж у земљи гдје би робовали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'И не покривај безакоња њихова, и гријех њихов да се не избрише пред тобом, јер те дражише за оне који зидају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'И тако зидасмо зид, и сав се зид састави до половине, и народ имаше вољу да ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'А кад чу Санавалат и Товија и Арапи и Амонци и Азоћани да се оправља зид Јерусалимски и да се почело затворати што је проваљено, разгњевише се врло;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'И сложише се сви заједно да дођу и да ударе на Јерусалим и да смету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'А ми се молисмо Богу својему и постављасмо стражу према њима дан и ноћ од страха њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'А Јудејци рекоше: клонула је снага носиоцима, а праха има много не можемо зидати зида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'А наши непријатељи рекоше: да не дознаду и не опазе докле не дођемо усред њих, па ћемо их побити и прекинути посао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Али дођоше Јудејци који код њих живљаху и казаше нам десет пута: чувајте сва мјеста куда се иде к нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Тада намјестих народ у низима иза зида и на стрменима, поставих народ по породицама са мачевима и копљима и луковима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'И разгледавши устах и рекох старјешинама и главарима и осталом народу: не бојте их се. Помените Господа великога и страшнога, и бијте се за браћу своју, за синове своје и кћери своје, за жене своје и куће своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'А кад чуше непријатељи наши да смо дознали, разби Господ њихову намјеру, и ми се вратисмо сви к зиду, сваки на свој посао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'И отада половина мојих момака пословаше, а друга половина држаше копља и штитове и лукове и оклопе, и кнезови стајаху иза свега дома Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'И који зидаху и који ношаху терет и који товараху сваки једном руком рађаше а у другој држаше копље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'А који зидаху, сваки имаху мач приписан уз бедрицу и тако зидаху. А трубач стајаше код мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Јер рекох старјешинама и главарима и осталом народу: посао је велик и дуг и ми смо се расули по зиду далеко један од другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'Гдје чујете трубу да труби, онамо трчите к нама; Бог наш војеваће за нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Тако рађасмо посао, и половина их држаше копља од зора па докле звјезде не изиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'У то вријеме још рекох народу: сваки са момком својим нека ноћује у Јерусалиму да би нам ноћу стражили а дању радили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'А ја и моја браћа и момци моји и стражари што иду за мном нећемо свлачити са себе хаљина; у свакога да је мач и вода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'И стаде велика вика људи и жена на браћу њихову Јудејце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Јер неки говораху: нас и синова наших и кћери наших има много; да добавимо жита да једемо и останемо живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Други опет говораху: да заложимо поља своја и винограде и куће да добијемо жита у овој глади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Још други говораху, да узајмимо новаца на поља своја и винограде за данак царски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'А тијело је наше као тијело браће наше, синови наши као њихови синови и ето треба да дамо синове своје и кћери своје у робље, и неке кћери наше већ су робиње, а ми не можемо ништа, јер поља наша и винограде наше држе други.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Зато се расрдих врло кад чух вику њихову и те ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'И смислих у срцу свом и укорих кнезове и поглаваре, и рекох им: ви мећете бремена сваки на брата својега. И сазвах велики збор њих ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'И рекох им: ми откуписмо колико могасмо браћу своју Јудејце што бјеху продани народима; а ви ли ћете продавати браћу своју или ће се продавати нама? А они умукоше и не нађоше што би одговорили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'И рекох: није добро што радите. Не треба ли вам ходити у страху Бога нашега да нам се не ругају народи, непријатељи наши?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'И ја и браћа моја и момци мој давали смо им новаца и жита; али опростимо им тај дуг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Хајде вратите им данас поља њихова и винограде и маслинике и куће и што им на стотину узимате од новца и жита и вина и уља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'А они одговорише: вратићемо и нећемо искати од њих; учинићемо како велиш. Тада сазвах свештенике, и заклех их да ће тако учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'И истресох њедра своја и рекох: овако да истресе Бог свакога из куће његове и из труда његова ко год не испуни ове ријечи, и овако да се истресе и буде празан. И сав збор рече: амин. И хвалише Господа, и учини народ по тој ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'И откад ми цар заповједи да им будем управитељ у земљи Јудиној, од године двадесете до тридесет друге године цара Артаксеркса, дванаест година, ја и браћа моја не једосмо хране управитељске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'А пређашњи управитељи који бијаху прије мене бијаху тешки народу узимајући од њега хљеба и вина осим четрдесет сикала сребра, и слуге њихове заповиједаху по народу. Али ја тако не чиних бојећи се Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Него и око грађења зида радих, и не куписмо њиве; и сви момци моји бијаху скупа ондје на послу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'И Јудејаца и поглавара сто и педесет људи и који долажаху к нама из околнијех народа бијаху за мојим столом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'И готовљаше се сваки дан по једно говече, шест оваца, избранијех, и птице готовљаху ми се, и сваких десет дана даваше се свакојакога вина изобила. И опет не исках хране управитељске; јер служба бјеше тешка народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Помени ме, Боже мој на добро за све што сам чинио овому народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'А кад чу Санавалат и Товија и Гисем Арапин и остали наши непријатељи да сам сазидао зид и да није остало у њему ништа проваљено, а до тада још не бијах намјестио крила на врата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Посла Санавалат и Гисем к мени и поручи: ходи да се састанемо у ком селу у пољу Ононском. А они мишљаху зло по ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'И послах к њима гласнике и поручих: у послу сам великом, зато не могу доћи. Јер би стао посао кад бих га оставио да дођем к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'И слаше тако к мени четири пута; и ја им онако одговорих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Тада Санавалат посла к мени тако пети пут слугу својега с књигом отвореном у руци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'А у њој писаше: чује се по народима и Гасмуј каже да се ти и Јудејци мислите одметнути, зато зидаш зид, и хоћеш да им будеш цар, како се говори,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'И да си поставио пророке да разглашују за тебе у Јерусалиму и говоре, цар је у Јудеји. А то ће доћи до цара; него ходи да се договоримо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Тада послах к њему и поручих: није тако како ти кажеш; него си сам измислио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Јер они сви шћаху нас уплашити говорећи: клонуће руке њихове од посла и неће се свршити. За то, Боже, укријепи руке моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Јоште отидох у кућу Семаји сину Далаје сина Метавелиова, који се бјеше затворио, и рече ми: да отидемо заједно у дом Божји усред цркве и да закључамо врата цркви, јер ће доћи да те убију, доћи ће ноћу да те убију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'А ја рекох: зар ће човјек какав сам ја бјежати? или ко би оваки какав сам ја ушао у цркву да остане у животу? нећу ићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'И разумјех да га није Бог послао, него то пророштво каза за ме, јер га Товија и Санавалат поткупише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Зато бјеше поткупљен да ме уплаши да онако учиним и згријешим да бих се осрамотио да ме могу ружити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Помени, Боже мој, Товију и Санавалата по овијем дјелима њиховијем, и Ноадију пророчицу и друге пророке који ме шћаху уплашити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'И тако доврши се зид двадесет петога дана мјесеца Елула за педесет и два дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'И кад чуше сви непријатељи наши и видјеше сви народи који бијаху око нас, уплашише се врло, јер познаше да је Бог наш учинио то дјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'И у оне дане многи главари Јудејски слаху књиге Товији, и од Товије њима долажаху књиге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Јер многи Јудејци бијаху му се заклели; јер бјеше зет Сеханији сину Арахову, и Јоанан син његов бјеше ожењен кћерју Меулама сина Варахијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'И говораху преда мном добро о њему, и ријечи моје доказиваху му; и Товија слаше књиге да ме уплаши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'А кад се сазида зид и намјестих врата, и постављени бише вратари и пјевачи и Левити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Заповједих Ананију брату својему и Ананији заповједнику од града Јерусалимскога, јер бјеше вјеран човјек и бојаше се Бога више него многи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'И рекох им: да се не отварају врата Јерусалимска докле сунце не огрије, и кад они што стоје ондје затворе врата, огледајте, и да се поставе стражари између становника Јерусалимских, сваки на своју стражу и сваки према својој кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'А град бијаше широк и велик, али народа бјеше мало у њему и куће не бјеху пограђене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'И Бог мој даде ми у срце, те сабрах главаре и старјешине и народ да се изброје по племенима. И нађох књигу, у којој бијаше пријепис онијех који се вратише први пут; и нађох у њој записано:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Ово су људи из овога краја што се вратише из ропства између онијех који бише пресељени, које пресели Навуходоносор цар Вавилонски, па се вратише у Јерусалим и у Јудеју, сваки у свој град,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Који дођоше са Зоровавељем, Исусом, Немијом, Азаријом, Рамијом, Наманијем, Мардохејем, Вилсаном, Мисперетом, Вигвајем, Неумом, Ваном; на број бјеше људи народа Израиљева:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Синова Фаросовијех двије тисуће и сто и седамдесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Синова Сефатијиних триста и седамдесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Синова Араховијех шест стотина и педесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Синова Фат-Моавовијех, од синова Исусовијех и Јоавових двије тисуће и осам стотина и осамнаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Синова Еламовијех тисућа и двјеста и педесет и четири;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Синова Затујевих осам стотина и четрдесет и пет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Синова Захајевих седам стотина и шездесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Синова Винујевих шест стотина и четрдесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Синова Вивајевих шест стотина и двадесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Синова Азгадовијех двије тисуће и три стотине и двадесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Синова Адоникамовијех шест стотина и шездесет и седам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Синова Вигвајевијех двије тисуће и шездесет и седам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Синова Адиновијех шест стотина и педесет и пет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Синова Атировијех од Језекије деведесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Синова Асумовијех триста и двадесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Синова Висајевијех триста и двадесет и четири;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Синова Арифовијех сто и дванаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Синова Гаваонских деведесет и пет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Људи из Витлејема и Нетофата сто и осамдесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Људи из Анатота сто и двадесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Људи из Вет-Асмавета четрдесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Људи из Киријат-Јарима, Хефире и Вирота седам стотина и четрдесет и три;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Људи из Раме и Гаваје шест стотина и двадесет и један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Људи из Михмаса сто и двадесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Људи из Ветиља и Гаја сто и двадесет и три;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'Људи из другога Невона педесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Синова Елама другога тисућа и двјеста и педесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Синова Харимовијх триста и двадесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Синова Јерихонских триста и четрдесет и пет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Синова Лодских, Адидских и Ононских седам стотина и двадесет и један;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Синова Сенајских три тисуће и девет стотина и тридесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Свештеника: синова Једајиних од дома Исусова девет стотина и седамдесет и три;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Синова Имировијех тисућа и педесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Синова Пасхоровијех тисућа и двјеста и четрдесет и седам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Синова Харимовијех тисућа и седамнаест;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Левита: синова Исусовијех и Кадмиловијех између синова Одавијиних седамдесет и четири;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Пјевача: синова Асафовијех сто и четрдесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Вратара: синова Салумовијех, синова Атировијех, синова Талмоновијех, синова Акувовијех, синова Атитинијех, синова Совајевијех сто и тридесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Нетинеја: синова Сишинијех, синова Асуфинијех, синова Тавотовијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Синова Киросовијех, синова Сијајиних, синова Фадановијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Синова Леваниних, синова Агавиних, синова Саламајевих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Синова Анановијех, синова Гидиловијех, синова Гаровијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Синова Реајиних, синова Ресиновијех, синова Некодинијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Синова Газамовијех, синова Узинијех, синова Фасејених,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Синова Висајевих, синова Меунимовијех, синова Нафусесимовијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Синова Ваквуковијех, синова Акуфинијех, синова Аруровијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Синова Васлитовијех, синова Меидинијех, синова Арсинијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Синова Варкосовијех, синова Сисаринијех, синова Таминијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Синова Несијиних, синова Атифиних;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Синова слуга Соломуновијех: синова Сотајевих, синова Соферетових, синова Феридинијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Синова Јалинијех, синова Дарконовијех, синова Гидиловијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Синова Сефатијиних, синова Атиловијех, синова Фохерета од Севајима, синова Амоновијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Свега Нетинеја и синова слуга Соломуновијех, триста и деведесет и два.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'И ови дођоше из Тел-Мелаха и Тел-Арисе, Херув, Адон и Имир, али не могаше показати отачкога дома својега и сјемена својега, еда ли су од Израиља,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'И синови Делајини, синови Товијини, синови Некодини, њих шест стотина и четрдесет и два,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'И од свештеника: синова Авајини, синови Акосови, синови Варзелаја, који се ожени између кћери Варзелаја Галађанина, те се прозва њиховијем именом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Они тражише по књигама да би показали род свој, али се не нађе, за то бише одлучени од свештенства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'И запријети им Тирсата да не једу од светиње над светињама докле не настане свештеник с Уримом и Тумимом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Свега збора скупа бјеше четрдесет и двије тисуће и три стотине и шездесет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'Осим слуга њиховијех и слушкиња њиховијех, којих бјеше седам тисућа и три стотине и тридесет и седам; и међу њима бјеше пјевача и пјевачица двјеста и четрдесет и пет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Имаху седам стотина и тридесет и шест коња, двије стотине и четрдесет и пет масака,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Четири стотине и тридесет и пет камила, шест тисућа и седам стотина и двадесет магараца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'Тада неки између главара дома отачких приложише на посао. Тирсата даде у ризницу тисућу драма злата, педесет чаша, шест стотина и тридесет хаљина свештеничких.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'А главари домова отачких дадоше у ризницу за посао двадесет тисућа драма злата, и сребра двије тисуће и двјеста мина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'А што даде остали народ бјеше двадесет тисућа драма злата, и двије тисуће мина сребра, и шездесет и седам хаљина свештеничких.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'И тако са населише свештеници и Левити вратари и пјевачи и људи из народа и Нетинеји и сав Израиљ у својим градовима; и кад дође седми мјесец, синови Израиљеви бијаху у својим градовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Тада се скупи сав народ једнодушно на улицу која је пред вратима воденијем, и рекоше Јездри књижевнику да донесе књигу закона Мојсијева који даде Господ Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'И донесе Јездра свештеник закон пред збор, у ком бјеху људи и жене и сви који могаху разумјети, првога дана седмога мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'И чита је на улици која је пред вратима воденијем од јутра до подне пред људима и женама и онијем који могаху разумјети, и уши свему народу бијаху обраћене на књизи законској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'А Јездра књижевник стајаше на мјесту повисоку, које бјеху начинили од дрвета за то; и до њега стајаше Мататија и Сема и Анаја и Урија и Хелкија и Масија с десне стране, а с лијеве Федаја и Мисаило и Малахија и Асум и Асвадана, Захарија и Месулам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'И отвори Јездра књигу на видику свему народу, јер бијаше више свега народа, и кад је отвори, уста сав народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'И Јездра благослови Господа Бога великога, а сав народ одговори: амин, амин, подигавши руке своје, па се савише и поклонише се Господу лицем до земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'А Исус и Ваније и Серевија, Јамин, Акув, Саветај, Одија, Масија, Келита, Азарија, Јозавад, Анан, Фелаја и други Левити поучаваху народ закону, и народ стајаше на мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'И читаху књигу, закон Божји, разговијетно и разлагаху смисао, те се разумијеваше што се читаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Потом Немија, који је Тирсата, и свештеник Јездра књижевник и Левити који поучаваху народ, рекоше свему народу: овај је дан свет Господу Богу вашему; не тужите ни плачите. Јер плакаше сав народ слушајући што говори закон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'И рече им: идите и једите претило и пијте слатко и шаљите дијелове онима који немају ништа зготовљено, јер је овај дан свет Господу нашему. Зато не будите жалосни, јер је радост Господња ваша сила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'И Левити утишаше народ говорећи: мучите, јер је овај дан свет, и не будите жалосни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'И отиде сав народ да једе и пије и да шаље дијелове, и веселише се веома што разумјеше ријечи које им се казаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'А сјутрадан скупише се главари домова отачких из свега народа, свештеници и Левити, к Јездри књижевнику да уче што закон говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'И нађоше написано у закону да је Господ заповједио преко Мојсија да синови Израиљеви бораве у сјеницама на празник седмога мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'И објавише и прогласише по свијем градовима својим и у Јерусалиму говорећи: идите у гору, и донесите грања маслинова и грања од дивље маслине и грања миртова и палмова и грања од шумнатијех дрвета, да начините сјенице, како је написано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'И народ изиде и донесе и начини сјенице сваки на свом крову и у свом тријему и у тријемовима дома Божијега и на улици код врата воденијех и на улици код врата Јефремовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'И тако начини сјенице сав збор, што се бјеше вратио из ропства, и борављаху под сјеницама. А од времена Исуса сина Навина до тога дана не чинише тако синови Израиљеви. И би весеље веома велико.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'И читаше се књига закона Божијега сваки дан, од првога дана до пошљедњега; и празноваше празник седам дана, а осми дан би сабор, како је уређено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Потом двадесет четвртога дана тога мјесеца скупише се синови Израиљеви постећи и у костријети и посувши се земљом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'И одвоји се сјеме Израиљево од свијех туђинаца, и стадоше те исповиједаху гријехе своје и безакоња отаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'И стајаху на свом мјесту, те им се читаше закон Господа Бога њихова четврт дана, а други четврт исповиједаху се и поклањаху се Господу Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'А Исус и Ваније, Кадмило, Севанија, Вуније, Серевија, Ваније и Хананије попевши се на мјесто подигнуто за Левите вапијаху гласом великим ка Господу Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'И рекоше Левити Исус и Кадмило, Ваније, Асавнија, Серевија, Одија, Севанија и Петаја: устаните, благосиљајте Господа Бога својега од вијека до вијека; и да се благосиља име твоје славно и узвишено сврх свакога благослова и хвале.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Ти си сам Господ; ти си створио небо, небеса над небесима и сву војску њихову, земљу и све што је на њој, мора и све што је у њима, и ти оживљаваш све то, и војска небеска теби се клања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Ти си Господ Бог, који си избрао Аврама и извео из Ура Халдејскога и надео му име Авраам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'И нашао си срце његово вјерно пред собом, и учинио си с њим завјет да ћеш дати земљу Хананску, Хетејску, Аморејску, Ферезејску и Јевусејску и Гергесејску, да ћеш дати сјемену његову, и испунио си ријечи своје, јер си праведан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Јер си погледао на муку отаца наших у Мисиру, и вику њихову си на Мору Црвеном;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'И учинио си знаке и чудеса на Фараону и на свијем слугама његовијем и на свем народу земље његове, јер си знао да су обијесно поступали с њима; и стекао си себи име, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'И море си раздвојио пред њима, те пријеђоше посред мора сухим, и бацио си у дубине оне који их гнаху као камен у воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'И у ступу од облака водио си их дању а ноћу у ступу огњеном свијетлећи им путем којим ће ићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'И сишао си на гору Синајску и говорио с њима с неба, и дао им судове праве и законе истините, уредбе и заповијести добре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'И обзнанио си им суботу своју свету, и дао им заповијести и уредбе и закон преко Мојсија слуге својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'И хљеб с неба дао си им у глади њиховој, и воду из камена извео си им у жеђи њиховој, и рекао си им да иду и наслиједе земљу за коју си подигао руку своју да ћеш им је дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Али они и оци наши узобијестише се и отврднуше вратом својим и не слушаше заповијести твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Не хтјеше слушати, и не опомињаше се чудеса твојих која си им чинио, него отврднуше вратом својим, и у одмету свом постављаше себи вођа да се врате у ропство своје. Али ти, Боже, који опрашташ, који си жалостив и милостив, који дуго трпиш и велике си милости, нијеси их оставио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'И онда кад начинише себи теле ливено и рекоше: ово је твој Бог који те је извео из Мисира, и хулише веома,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Ни онда их ради велике милости своје нијеси оставио у пустињи; ступ од облака није отступао од њих дању водећи их путем, нити ступ огњени ноћу свијетлећи им путем којим ће ићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'И дао си им добри свој дух да их уразумљује, и мане своје нијеси устегао од уста њиховијех, и воде си им дао у жеђи њиховој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'И четрдесет година хранио си их у пустињи, ништа им није недостајало: одијело им не оветша и ноге им не отекоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'И дао си им царства и народе, и подијелио си их по крајевима, јер наслиједише земљу Сионову, земљу цара Есевонскога, и земљу цара Васанскога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'И умножио си синове њихове као звијезде небеске, и увео си их у земљу за коју си рекао оцима њиховијем да ће ући у њу и наслиједити је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'И уђоше синови њихови и наслиједише земљу, и покорио си им Хананеје становнике земаљске и предао их у њихове руке, и цареве њихове и народе земаљске, да чине од њих што им је воља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'И тако узеше тврде градове и земљу родну, и наслиједише куће пуне свакога добра, студенце ископане, винограде, маслинике и воћке многе, и једоше и наситише се и угојише се, и благоваху по великој твојој доброти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Али те разгњевише и одметнуше се од тебе: бацише закон твој за леђа и пророке твоје побише, који им свједочаху да би их обратили ка теби, и хулише веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Зато си их давао у руке непријатељима њиховијем који их мучише. А кад у невољи својој викаше к теби ти си их услишио с неба и по великој милости својој давао си им избавитеље, који их избављаше из руку непријатеља њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Али чим отпочинуше, опет чинише зло пред тобом, зато си их остављао у руку непријатеља њиховијех да владају њима; а кад се обраћаше и викаше к теби, ти си их услишио с неба и избављао их по милости својој много пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'И опомињао си их да би их обратио к закону својему, али они бијаху обијесни и не слушаше заповијести твојих и гријешише о твоје законе које ко врши жив ће бити кроз њих; и измичући рамена своја отврднуше вратом својим и не слушаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'И трпио си их много година опомињући их духом својим преко пророка својих; али не слушаше; тада си их дао у руке народима земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Али ради милости своје велике нијеси дао да сасвијем пропадну нити си их оставио, јер си Бог милостив и жалостив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Сада дакле, Боже наш, Боже велики, силни и страшни, који чуваш завјет и милост, немој да је мало пред тобом што нас снађе сва ова мука, цареве наше, кнезове и свештенике наше и пророке наше и оце наше и сав народ твој од времена царева Асирских до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Ти си праведан у свему што нас је снашло, јер си ти право учинио а ми смо безбожно радили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'И цареви наши, кнезови наши и оци наши не извршиваше закона твојега нити марише за заповијести твоје и свједочанства твоја, којима си им свједочио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Јер у царству свом и у великом добру твом које си им чинио, и у земљи пространој и родној коју си им дао, не служише теби нити се повратише од злијех дјела својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Ево, ми смо данас робови; и још у земљи, коју си дао оцима нашим да једу род њезин и добра њезина, ево ми смо робови у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'И она род свој обилати рађа царевима које си поставио над нама за гријехе наше, и који господаре над нашим тјелесима и над стоком нашом по својој вољи, те смо у великој тјескоби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'А ради свега тога чинимо тврд завјет и пишемо, а кнезови наши, Левити наши, свештеници наши печате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'А који запечатише бјеху ови: Немија, Тирсата, син Ахалијин, и Седекија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Серај, Азарија, Јеремија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Пасхор, Амарија, Малхија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Хатус, Севанија, Малух,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Харим, Меримот, Овадија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Данило, Гинетон, Варух,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Месулам, Вија, Мијамин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Мазија, Вилгај, Семаја; то бјеху свештеници;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'А Левити: Исус син Азанијин Винуј између синова Инададовијех, Кадмило,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'И браћа њихова: Севанија, Одија, Келита, Фелаја, Анан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Миха, Реов, Асавија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Захур, Серевија, Севнија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Одија, Ваније, Венинуј;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Главари народни: Фарос, Фат-Моав, Елам, Затуј, Ваније,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Вуније, Азгад, Вивај,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Адонија, Вигвај, Адин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Атир, Језекија, Азур,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Одија, Асум, Висај,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Ариф, Анатот, Навај,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Магфија, Месулам, Езир,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Месизавеило, Садок, Јадва,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Фелатија, Анан, Анаја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Осија, Ананија, Асув,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Лоис, Филеја, Совик,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Реум, Асавна, Масија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Ахија, Анана, Ганан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Малух, Харим, Вана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'И остали народ, свештеници, Левити, вратари, пјевачи, Нетинеји и сви који се одвојише од народа земаљских к закону Божијему, жене њихове, синови њихови и кћери њихове, сви који знаху и разумјеваху,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Присташе с браћом својом, главарима својим, и дођоше те се заклеше и клетвом завезаше да ходимо по закону Божијему, који је дат преко Мојсија слуге Божијега, и да држимо и извршујемо све заповијести Господа Бога својега и законе његове и уредбе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'И да не дајемо кћери својих народима земаљским, нити кћери њиховијех да узимамо за синове своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'И од народа земаљских који донесу трг или каку год храну у суботу на продају, да не узимамо у суботу ни у други свети дан, и да остављамо седме године да почива земља и опраштамо сваки дуг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'И постависмо себи уредбу да дајемо сваке године трећину сикла на службу у дом Бога својега:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'На хљебове постављене, на дар свагдашњи и жртву паљеницу свагдашњу за суботе, за младине и за празнике, и на светињу и на жртве за гријех да се очишћа Израиљ, и на свако дјело у дому Бога нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'И бацасмо ждријеб за свештенике и Левите и народ ради ношења дрва да се доноси у дом Бога нашега по домовима отаца наших на вријеме од године до године, да гори на олтару Господа Бога нашега, како пише у закону;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'И да доносимо првине од земље своје и првине од свакога рода од свакога дрвета од године до године у дом Господњи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'И првенце од синова својих и стоке своје, како пише у закону, и првенце од говеда својих и од оваца својих да доносимо у дом Бога својега свештеницима који служе у дому Бога нашега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'И првине тијеста својега и приносе своје и род од свијех дрвета, вино и уље да доносимо свештеницима у клијети дома Бога својега, и Левитима десетак од земље своје, и Левити да узимају десетак по свијем мјестима гдје узрадимо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'И да буде свештеник син Аронов с Левитима кад Левити узимају десетак, и да Левити доносе десетак од десетка у дом Бога нашега, у клијети, у спреме његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Јер у те клијети дужни су синови Израиљеви и Левити доносити принос од жита, од вина и уља, гдје су свети судови, и свештеници који служе, и вратари и пјевачи, да не остављамо дома Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'И населише се кнезови народни у Јерусалиму, а остали народ мета ждријеб да узму једнога од десет да сједи у Јерусалиму светом граду, и осталијех девет дијелова по другим градовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'И благослови народ све људе који сами од своје воље присташе да сједе у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Ово су главари земаљски који се населише у Јерусалиму, а по осталијем градовима Јудејским настанише се сваки на својем нашљедству по градовима својим Израиљци свештеници и Левити, Нетинеји и синови слуга Соломуновијех:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'У Јерусалиму дакле населише се неки од синова Јудинијех и Венијаминовијех: од синова Јудинијех: Атаја син Озије, сина Захарије, сина Амарије, сина Сефатије, сина Малелеилова, од синова Фаресовијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'И Масија син Варуха сина Холозе сина Азаје, сина Адаје, сина Јојарива сина Захрије, сина Силонијева;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Свега синова Фаресовијех што се населише у Јерусалиму, четири стотине и шездесет и осам храбријех људи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'А између синова Венијаминовијех: Салуј син Месулама, сина Јоада, сина Федаје, сина Колаје, сина Масија, сина Итила, сина Исаијина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'И за њим Гавај, Салај девет стотина и двадесет и осам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'А Јоило син Захријев бјеше над њима, а Јуда син Сенујин бјеше други над градом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Од свештеника: Једаја син Јојавов, Јахин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Сераја син Хелкије, сина Месулама, сина Садока, сина Мерајота, сина Ахтивова, старјешина у дому Божијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'А браће њихове што служаху у дому осам стотина и двадесет и два; и Адаја син Јероама, сина Фелалије, сина Амсија, сина Захарије, сина Пасхора, сина Малхијина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'И браће његове главара у домовима отачким двјеста и четрдесет и два; и Амасај син Азреила, сина Азаја; сина Месилемота, сина Имирова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'И браће њихове храбријех људи сто и двадесет и осам, а над њима бјеше Завдило син Гедолимов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'И од Левита: Семаја сина Асува сина Азрикама, сина Асавије, сина Вунијева;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'И Саветај, И Јозавад бијаху над послом спољашњим за дом Божји између главара Левитских,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'А Матанија син Михе сина Завдије сина Асафова бијаше поглавар који почињаше хвалу у молитви, и Ваквукија други између браће своје, и Авда син Салије сина Галала сина Једутунова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Свега Левита у светом граду бјеше двије стотине и осамдесет и четири;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'А од вратара: Акув, Талмон, и браћа њихова што чуваху стражу на вратима, сто и седамдесет и два;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'А остатак народа Израиљева, свештеника, и Левита бјеше по свијем градовима Јудинијем, свак на свом нашљедству;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'А Нетинеји населише се у Офилу, и Сиха и Гиспа бјеху над Нетинејима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'А над Левитима у Јерусалиму бјеше Озија син Ванија, сина Асавије, сина Матаније, сина Мишина. Између синова Асафовијех пјевачи бијаху у служби за дом Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Јер бјеше царева заповијест за њих и бјеше одређена плата пјевачима за сваки дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'И Петаја син Месизавеилов од синова Заре сина Јудина бјеше мјесто цара за сваки посао с народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'А по селима и пољима њиховијем неки од синова Јудинијех настанише се у Киријат-Арви и засеоцима њезинијем, и у Дивону и засеоцима његовијем, и у Јекавсеилу и селима његовијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'И у Јесуји и Молади и Вет-Фелету,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'И у Асар-Суалу и Вирсавеји и засеоцима њезинијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'И у Сиклагу и у Мекони и засеоцима њезинијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'И у Ен-Римону и у Сареји и у Јармуту,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'У Заноји, у Одоламу и селима њиховијем, у Лахису с пољем његовијем, у Азици и засеоцима њезинијем. И тако се населише од Вирсавеје до долине Енома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'А синови Венијаминови населише се од Гаваје у Михмасу и Аји и Ветиљу и засеоцима његовијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'У Анатоту, у Нову, Ананији,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'У Асору, у Рами, у Гитајиму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'У Адиду, у Севојиму, у Невалату,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'У Лоду, у Онону, и у долини дрводјељској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'А Левити подијелише се међу Јудом и Венијамином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'А ово су свештеници и Левити који дођоше са Зоровавељем сином Салатиловијем и Исусом: Сераја, Јеремија, Јездра,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Амарија, Малух, Хатус,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Сеханија, Реум, Леримот,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Идо, Гинето, Авија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Мијамин, Мадија, Вилга,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Семаја, Јојарив, Једаја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Салуј, Амок, Хелкија, Једаја. То бјеху главари између свештеника и браће своје за времена Исусова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'А Левити: Исус, Винуј, Кадмило, Севија, Јуда и Матанија, који с браћом својом бјеше над пјевањем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'А Вавукија и Уније браћа њихова бијаху према њима у редовима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'А Исус роди Јоакима, а Јоаким роди Елијасива, а Елијасив роди Јојаду;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'А Јојада роди Јонатана, а Јонатан роди Јадву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'А за времена Јоакимова бјеху свештеници, главари домова отачких: од дома Серајина Мераја, од Јеремијина Ананија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Од Јездина Месулам, од Амаријина Јоанан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Ода Мелихујева Јонатан, од Севанијина Јосиф,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Од Харимова Адна, од Мерајотова Елкај,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Од Идова Захарија, од Гинетова Месулама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Од Авијина Зихрије, од Минијаминова и Моадијина Филтај,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Од Вилжина Самуја, од Семајина Јонатан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Од Јојаривова Матенај, од Једајина Озије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Од Салајева Калај, од Амокова Евер,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Од Хелкијина Асавија, од Једајина Натанаило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'А Левити главари дома отачких, за време Елијасива, Јојаде, Јоанана и Јадве бише пописани са свештеницима до царовања Дарија цара Персијскога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Синови Левијеви, главари домова отачких, бише пописани у књизи дневника до времена Јоанана сина Елијасивова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'И главари Левитски бјеху: Асавија, Серевија и Исус син Кадмилов и браћа њихова према њима да хвале и славе Бога по заповијести Давида човјека Божијега, ред према реду;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Матанија и Ваквукија, Овадија, Месулам, Талмон, Акув, бијаху вратари који чуваху стражу код ризница на вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Ти бијаху за времена Јоакима сина Исуса сина Јоседекова и за времена Немије кнеза и свештеника Јездре књижевника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'А кад се освећиваше зид Јерусалимски, тражише Левите по свијем мјестима њиховијем да их доведу у Јерусалим да се сврши посвећење с весељем, хвалом и пјесмама уз кимвале, псалтире и гусле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'И скупише се синови пјевачки и из равница око Јерусалима и из села Нетофатских,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'И из Вет-Гилгала и из поља Гевских и Азмаветских, јер пјевачи бијаху насели села око Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'И очистише се свештеници и Левити, и очистише народ и врата и зид.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Иза тога заповједих кнезовима Јудејским да изађу на зид, и поставих два велика збора пјевачка, и један од њих иђаше на десно с горње стране зида к вратима гнојнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'А за њима иђаше Осаја и половина кнезова Јудинијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'А Азарија, Јездра и Месулам,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Јуда и Венијамин и Семаја и Јеремија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'И од синова свештеничких с трубама Захарија син Јонатана, сина Семаје, сина Матаније, сина Захура, сина Асафова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'И браћа његова Семаја и Азареило, Милалај, Гилалај, Мај, Натанило и Јуда и Ананије са справама музичким Давида човјека Божијега, а Јездра књижевник пред њима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Потом к вратима код студенца, која бијаху према њима, иђаху уз басамаке града Давидова куда се ида на зид, изнад дома Давидова па до врата воденијех к истоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'А други збор пјевачки иђаше према онима, и ја за њим, и половица народа по зиду изнад куле пећске до широкога зида,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'И изнад врата Јефремовијех к вратима старијем и к вратима рибљим и ка кули Ананеиловој и кули Меји, па до врата овчијих; и стадоше код врата тамничких.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Потом стадоше оба збора пјевачка у дому Божијем, и ја и половица главара са мном,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'И свештеници Елијаким, Масија, Минијамин, Михаја, Елиоинај, Захарија, Ананија с трубама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'И Масија и Семаја и Елеазар и Озије и Јоанан и Малхија и Елам и Есер. И пјевачи пјеваху гласно с Језрајом начелником својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'И принесоше велике жртве тај дан, и веселише се; јер их Бог развесели весељем великим; и жене и дјеца веселише се, и весеље Јерусалимско чујаше се далеко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'И постављени бише тај дан људи над клијетима у којима се остављаху приноси, првине и десетак, да сабирају у њих с њива градских законите дијелове за свештенике и за Левите, јер се Јуда радоваше свештеницима и Левитима што стајаху на послу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'И извршиваху што им је Бог њихов заповједио да извршују и што требаше извршивати за очишћење, као и пјевачи и вратари по заповијести Давида и Соломуна сина његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Јер отприје, за времена Давидова и Асафова бише постављени главари пјевачки и пјесме у хвалу и славу Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'И за то сав Израиљ за времена Зоровавеља и за времена Немијина даваше дијелове пјевачима и вратарима, свакидашњи оброк, и Левитима што бјеше њима посвећено, а Левити синовима Ароновијем што њима бјеше посвећено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'У то вријеме чита се књига Мојсијева народу, и у њој се нађе написано да не улази Амонац ни Моавац у сабор Божји довијека;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Јер не сретоше синова Израиљевијех с хљебом и водом, него најмише на њих Валама да их прокуне, али Бог наш обрати ону клетву у благослов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'А кад чуше тај закон одлучише од Израиља све туђинце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'А прије тога Елијасив свештеник, који бјеше над клијетима дома Бога нашега, опријатељи се с Товијом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'И начини му велику клијет, гдје се прије остављаху дари и кад и судови и десетак од жита, вина и уља, одређени Левитима и пјевачима и вратарима, и приноси за свештенике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'А кад то све биваше, не бјех у Јерусалиму, јер тридесет друге године Артаксеркса цара Вавилонскога вратих се к цару, и послије неколико година измолих се опет у цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'И кад дођох у Јерусалим, видјех зло што учини Елијасив ради Товије начинивши му клијет у тријему дома Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'И би ми врло мрско, те избацих све покућство Товијино напоље из клијети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'И заповједих, те очистише клијети; и унесох у њих опет посуђе дома Божијега, даре и кад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Потом дознах да се Левитима нијесу давали дијелови, те су се разбјегли сваки на своју њиву и Левити и пјевачи, који рађаху посао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'И укорих старјешине и рекох: зашто је остављен дом Божји? И сабрах их опет и поставих на њихово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'И сви Јудејци доносише десетке од жита и вина и уља у спреме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'И поставих настојнике над спремама, Селемију свештеника и Садока књижевника, и између Левита Федају, и уз њих Анана сина Захура сина Матанијина, јер се за вјерне држаху; и бијаше им посао дијелити браћи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Помени ме, Боже мој, за то, и немој избрисати добара мојих која учиних дому Бога својега и служби његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'У то вријеме видјех у Јудеји гдје газе у кацама у суботу и носе снопове натоваривши на магарце, и вино, грожђе и смокве и свакојаке товаре, и носе у Јерусалим у суботу, и прекорих их онај дан кад продаваху житак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'И Тирци који живљаху у Јерусалиму доношаху рибу и свакојаки трг и продаваху у суботу синовима Јудинијем у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Зато прекорих главаре Јудејске и рекох им: како је то зло што чините те скврните суботу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Нијесу ли тако чинили оци ваши, те Бог наш пусти на нас и на овај град све ово зло? И ви још умножавате гњев на Израиља скврнећи суботу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'И кад дође сјен на врата Јерусалимска уочи суботе, заповједих те затворише врата, и заповједих да их не отварају до послије суботе; и поставих неколико својих момака на вратима да се не уноси никакав товар у суботу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'И преноћише трговци и који продаваху свакојаки трг иза Јерусалима једном и другом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'И опоменух их и рекох им: зашто ноћујете око зида? Ако још једном то учините, уложићу на вас. Од тада не долазише у суботу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'А Левитима заповједих да се очисте и да дођу и чувају врата да буде свет дан суботни. И за ово помни ме, Боже мој, и опрости ми по великој милости својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Још видјех у то вријеме Јудејце који се бијаху оженили Азоћанкама, Амонкама и Моавкама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'И синови њихови говораху пола Азотски, и не умијаху говорити Јудејски него језиком и једнога другога народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Зато их карах и псовах, и неке између њих бих и чупах, и заклех их Богом да не дају кћери својих синовима њиховијем нити да узимају кћери њиховијех за синове своје или за себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Није ли тијем згријешио Соломун цар Израиљев, ако и не бјеше у многим народима цара њему равна и мио бјеше Богу својему и Бог га бјеше поставио царем над свијем Израиљем? па опет га навратише на гријех жене туђинке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'А вама ли ћемо допустити да чините то све велико зло и гријешите Богу нашему узимајући жене туђинке?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'И од синова Јојаде сина Елијасива погавара свештеничкога један бјеше зет Санавалату Ороњанину, којега отјерах од себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Помени их, Боже мој, што оскврнише свештенство и завјет свештенички и Левитски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'И тако их очистих од свијех туђинаца, и опет поставих редове свештеничке и Левитске, свакога на посао његов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'И да се доносе дрва за жртве на рокове, и првине. Помени ме, Боже мој, на добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'У вријеме Асвирово, а тај Асвир цароваше од Индије до Етиопије у сто и двадесет и седам земаља,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'У то вријеме, кад сјеђаше цар Асвир на пријестолу царства својега у Сусану царском граду,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'Треће године царовања својега учини гозбу свијем кнезовима својим и слугама својим, та бијаше код њега сила Персијска и Мидска, властељи и управитељи земаљски;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'И он показиваше богатство и славу царства својега и дику и красоту величине своје много дана, сто и осамдесет дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'И послије тих дана учини цар свему народу што га бијаше у Сусану царском граду од малога до великога гозбу за седам дана у тријему у врту од царскога двора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Завјеси бијели, зелени и љубичасти бијаху објешени врвцама бијелијем, ланенијем и скерлетнијем о биочузима сребрнијем на ступовима мраморнијем; одри бијаху златни и сребрни по поду од зеленога, бијелога, жутога и црвенога мрамора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'А пиће даваху у судовима златнијем, и то у судовима другим и другим, а вина царскога бјеше изобила, како може бити у цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'И пићем нико не наваљиваше по наредби, јер цар бјеше заповједио свијем приставима дома својега да чине како ко хоће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'И царица Астина учини гозбу женама у царском двору цара Асвира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Седми дан кад се цар развесели од вина рече Меуману, Висати, Арвони, Викти, Авакти, Зетару и Харкасу, седморици дворана који двораху пред царем Асвиром,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Да доведу царицу Астину пред цара под царским вијенцем, да покаже народима и кнезовима љепоту њезину, јер бијаше лијепа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Али царица Астина не хтје доћи на ријеч цареву, коју јој поручи по дворанима; зато се цар врло разгњеви и гњев се његов распали у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'И рече цар мудрацима који разумијеваху времена (јер тако цар изношаше ствари пред све који разумијеваху закон и правду,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'А најближи до њега бијаху Карсена, Сетар, Адмата, Тарсис, Мерес, Марсена и Мемукан, седам кнезова Персијских и Мидских, који гледаху лице царево и сјеђаху на првијем мјестима у царству):');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Што треба по закону чинити с царицом Астином што није учинила што је заповједио цар Асвир преко дворана?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Тада рече Мемукан пред царем и кнезовима: није само цару скривила царица Астина него и свијем кнезовима и свијем народима по свијем земљама цара Асвира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Јер ће се дјело царичино разићи међу све жене, па ће презирати мужеве своје говорећи: цар Асвир заповједи да доведу преда њ царицу Астину, а она не дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'И од данас ће кнегиње Персијске и Мидске које чују шта је учинила царица тако говорити свијем кнезовима царевијем; те ће бити много пркоса и свађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Ако је угодно цару, да изиде царска заповијест од њега и да се упише међу законе Персијске и Мидске да је непромјенито, да Астина не излази више пред цара Асвира и да ће цар дати њезино царство другој бољој од ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'И кад се заповијест царева коју учини чује по царству његову свему коликоме, све ће жене поштовати своје мужеве од великога до малога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'И ово би по вољи цару и кнезовима, и учини цар како рече Мемукан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'И разасла књиге по свијем земљама царским, у сваку земљу њезинијем писмом и свакому народу његовијем језиком, да би сваки муж био господар у својој кући; и би проглашено језиком свакога народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Послије тога, кад се утиша гњев цара Асвира, он се опомену Астине и што је учинила и што је наређено за њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'И рекоше момци цареви, слуге његове: да потраже цару младијех дјевојака лијепијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'И нека одреди цар приставе по свијем земљама царства својега да скупе све дјевојке младе и лијепе у Сусан град царски у женски двор под руку Игаја дворанина царева, чувара женскога, и нека им се дају потребе за љепоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Па која дјевојка буде по вољи цару, нека буде царица на Астинино мјесто. И то би по вољи цару, и учини тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Бијаше у Сусану царском граду Јудејац по имену Мардохеј, син Јаира сина Симеја сина Кисова, од племена Венијаминова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Који би одведен у ропство из Јерусалима с робљем које би одведену у ропство с Јехонијом царем Јудинијем, којега зароби Навуходоносор цар Вавилонски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Он одгајаше Адасу, а то је Јестира, кћи стрица његова, јер не имаше оца ни матере; а дјевојка бијаше лијепа стаса и красна лица, и по смрти оца јој и матере узе је Мардохеј за кћер.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'И кад се разгласи ријеч царева и заповијест, и много се дјевојака скупи у Сусан град царски под руку Игајеву, би и Јестира доведена у двор царев под руку Игаја чувара женскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'И дјевојка му омиље и нађе милост у њега, те јој одмах даде потребе за љепоту и дио њезин, и седам присталијех дјевојака из царскога дома, и намјести је с њезинијем дјевојкама на најљепше мјесто у женском дому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Јестира не каза народа својега ни рода својега, јер јој Мардохеј бјеше забранио да не казује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'А Мардохеј ходаше сваки дан испред тријема од женскога дома да би дознао како је Јестира и што ће бити од ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'А кад би дошао ред на коју дјевојку да уђе к цару Асвиру, пошто би јој се чинило по женском закону дванаест мјесеца (јер толико времена требаше да се уљепшавају, шест мјесеца уљем од смирне а шест мјесеца мирисима и другим стварима за љепоту женску),');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Тада би дјевојка ишла к цару, и што би год рекла дало би јој се да с тијем иде из женске куће у дом царев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Увече би ушла а ујутру би се вратила у другу кућу женску под руку Сазгаза дворанина царева, чувара иночкога; више не би ишла к цару, већ ако би је хтио цар, те би била позвана по имену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'И тако кад дође ред на Јестиру кћер Авихаила стрица Мардохејева, коју бјеше узео за кћер, да уђе к цару, она не заиска ништа него што рече Игај дворанин царев, чувар женски; и Јестира налажаше милост у свакога ко је виђаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Тако би Јестира одведена к цару Асвиру у царски двор његов десетога мјесеца, које је мјесец Тевет, седме године царовања његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'И цару омиље Јестира мимо све друге жене, и придоби милост и љубав његову мимо све дјевојке, те јој метну царски вијенац на главу и учини је царицом на мјесто Астинино.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'И учини цар велику гозбу свијем кнезовима својим и слугама својим ради Јестире, и поклони земљама олакшице и раздаде дарове како цар може.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'А кад се другом скупљаху дјевојке, Мардохеј сјеђаше на вратима царевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'А Јестира не каза својега рода ни народа, као што јој бјеше заповједио Мардохеј, и Јестира чињаше што јој Мардохеј говораше, као кад се одгајаше код њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'У те дане, кад Мардохеј сјеђаше на вратима царевијем, расрдише се Вихтан и Терес два дворанина царева између онијех који стражаху на прагу, и гледаху да дигну руке на цара Асвира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'А то дозна Мардохеј и јави царици Јестири, а Јестира каза цару у име Мардохејево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'И кад се ствар извидје и нађе, бише објешена она обојица на дрво, и то се записа у књигу дневника пред царем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Послије тога подиже цар Асвир Амана сина Амедатина, Агагеја, и узвиси га, и намјести му пријесто више свијех кнезова што бијаху код њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'И све слуге цареве што бијаху на вратима царевијем клањаху се и падаху пред Аманом, јер тако бјеше цар заповједио за њ. Али Мардохеј не клањаше се нити падаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'И слуге цареве што бијаху на вратима царевијем говораху Мардохеју: зашто преступаш заповијест цареву?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'И пошто му од дана на дан говораше а он не послуша, јавише Аману да виде хоће ли остати ријечи Мардохејеве, јер им бјеше казао да је Јудејац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'А кад видје Аман да се Мардохеј не клања нити пада пред њим, напуни се гњева Аман.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Али мишљаше да није вриједно да дигне руку на Мардохеја самога, јер му казаше којега народа бјеше Мардохеј, него гледаше да истријеби све Јудејце што бијаху по свему царству Асвирову, народ Мардохејев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Првога мјесеца, а то је мјесец Нисан, године дванаесте царовања Асвирова, бацаше Фур, то јест ждријеб, пред Аманом, од дана до дана и од мјесеца до мјесеца, до дванаестога мјесеца, а то је мјесец Адар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'И Аман рече цару Асвиру: има народ расијан и расут по народима по свијем земљама царства твојега, којега су закони друкчији од закона свијех народа, и не извршују закона царевијех, па није пробитачно цару да их остави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Ако је цару угодно, да се пише да се истријебе; и ја ћу измјерити десет тисућа таланата сребра у руке приставима да донесу у цареву ризницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Тада цар сними прстен с руке своје и даде га Аману сину Амедатину Агагеју непријатељу Јудејском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'И рече Аману: то сребро нека теби, а од народа чини што ти је драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Зато дозваше писаре цареве првога мјесеца тринаестога дана, и написа се све како заповједи Аман, намјесницима царевијем и војводама у свакој земљи и кнезовима свакога народа, свакој земљи писмом њезинијем и свакому народу језиком његовијем, у име цара Асвира написа се и прстеном царевијем запечати се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'И разаслаше се књиге по гласницима у све земље цареве да потру, побију и истријебе све Јудејце, старо и младо, дјецу и жене у један дан, тринаестога дана дванаестога мјесеца, које је мјесец Адар, и да разграбе имање њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'У књигама се говораше да се огласи заповијест по свијем земљама и да се објави свијем народима да буду готови за онај дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Гласници отидоше брзо по заповијести царевој, и заповијест би оглашена у Сусану царском граду. А цар и Аман сјеђаху и пијаху, а град се Сусан смете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'А Мардохеј дознав све шта би, раздрије хаљине своје и обуче се у костријет и посу се пепелом и пође по граду вичући иза гласа горко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'И дође до пред врата царева, јер не бјеше слободно ући на врата царева у костријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'И у свијем земљама, у које год мјесто дође ријеч царева и заповијест његова, би велика жалост међу Јеврејима и пост и плач и јаук, и многи у костријети и пепелу лежаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'И дођоше дјевојке Јестирине и дворани њезини, и јавише јој: и царица се ожалости веома, и посла хаљине да преобуку Мардохеја и да скину с њега костријет; али он не прими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Тада дозва Јестира Атаха дворанина царева, којега јој бјеше дао да јој служи, и заповједи му за Мардохеја да разбере шта му је и зашто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'И отиде Атах к Мардохеју на улицу градску која бијаше пред вратима царевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'И Мардохеј му каза све што му се догодило и за сребро што је обрекао Аман дати у цареву ризницу за Јудејце да их истријеби;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'И пријепис од заповијести која би проглашена у Сусану да се истријебе, даде му да је покаже Јестири и јави, и да јој наручи да отиде к цару и да га умилостиви и да га моли за свој народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'И вративши се Атах каза Јестири ријечи Мардохејеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'А Јестира рече Атаху и заповједи му да каже Мардохеју:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Знају све слуге цареве и народ по земљама царевијем да ко би год, човјек или жена, ушао к цару унутра у двор не будући позван, један је закон за њ, да се погуби, осим коме би цар пружио златну палицу, тај остаје жив; а ја нијесам звана да уђем к цару, ово је тридесет дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'И казане бише Мардохеју ријечи Јестирине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'А Мардохеј опет поручи Јестири: немој мислити да ћеш се мимо све Јудејце избавити у дому цареву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Јер ако ти узмучиш сада, доћи ће помоћ и избављење Јудејцима с друге стране, а ти и дом оца твојега погинућете; и ко зна нијеси ли за овако вријеме дошла до царства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Тада рече Јестира да одговоре Мардохеју:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Иди, скупи све Јудејце што се налазе у Сусану, и постите за ме, и не једите ни пијте за три дана ни дању ни ноћу; и ја ћу са својим дјевојкама постити такођер, па ћу онда отићи к цару, ако и није по закону, и ако погинем, нека погинем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Тада отиде Мардохеј и учини све како му заповједи Јестира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'А трећи дан обуче се Јестира у царско одијело, и стаде у тријему унутрашњега двора царскога према стану цареву; а цар сјеђаше на царском пријестолу свом у двору царском према вратима од двора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'И кад цар угледа царицу Јестиру гдје стоји у тријему, она нађе милост пред њим, те цар пружи према Јестири златну палицу која му бјеше у руци, и Јестира приступи и дотаче се краја од палице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'И рече јој цар: што ти је, царице Јестиро? и шта желиш? ако је и до половине царства, даће ти се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'А Јестира рече: ако је угодно цару, нека дође цар с Аманом данас на објед који сам му зготовила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'А цар рече: зовите брже Амана да учини што рече Јестира. И дође цар с Аманом на објед који зготови Јестира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Потом цар напив се вина рече Јестири: шта желиш? даће ти се; и шта молиш? ако је и до половине царства, биће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'А Јестира одговарајући рече: желим и молим:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Ако сам нашла милост пред царем, и ако је угодно цару да ми да што желим и учини што молим, нека опет дође цар с Аманом на објед који ћу им зготовити, и сјутра ћу учинити по ријечи царевој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'И тако отиде Аман онај дан весео и добре воље. Али кад видје Аман Мардохеја на вратима царевијем а он не уста нити се маче пред њим, напуни се Аман гњева на Мардохеја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Али се уздржа Аман докле дође кући својој; потом посла и сазва пријатеље своје и Сересу жену своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'И приповједи им Аман о слави богатства својега и о мноштву синова својих и о свему чим га је подигао цар и како га је узвисио сврх кнезова и слуга царских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'И дода Аман: па и царица Јестира никога осим мене не позива с царем на објед, који бјеше зготовила, па и сјутра сам позван к њој с царем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Али све то није ми ни на што докле год гледам онога Мардохеја Јудејца гдје сједи на вратима царевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Тада му рече Сереса жена његова и сви пријатељи његови: нека начине вјешала висока педесет лаката, и ујутру реци цару да се на њима објеси Мардохеј, па иди с царем весео на објед. И то би по вољи Аману и приправи вјешала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Ону ноћ не могаше цар спавати, и заповједи те му донесоше књигу од знаменитијех догађаја, дневнике, те је читаше цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'И нађе се записано како је Мардохеј проказао за Вихтана и Тереса, два дворанина, који чуваху стражу на прагу, да гледају да дигну руке на цара Асвира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Тада рече цар: кака је част и како је добро учињено Мардохеју за то? а момци цареви, слуге његове, рекоше: није му учињено ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'А цар рече: ко је у тријему? А Аман бјеше дошао у спољашњи тријем двора царева да каже цару да се објеси Мардохеј на вјешала која му је приправио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'А момци цареви рекоше му: гле, Аман стоји у тријему. А цар рече: нека дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'И Аман дође, а цар му рече: шта треба учинити човјеку којега цар хоће да прослави? А Аман рече у себи: кога би цар хтио прославити ако не мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'И рече Аман цару: кога цар хоће да прослави,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Треба донијети царско одијело које цар носи, и довести коња на ком цар јаше, и метнути му на главу вијенац царски;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'И одијело и коња треба дати коме између највећих кнезова царевијех да обуку човјека онога којега цар хоће да прослави, па да га проведу на коњу по улицама градским и вичу пред њим: овако бива човјеку кога цар хоће да прослави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Тада рече цар Аману: брже узми одијело и коња као што рече, и учини тако Мардохеју, Јудејцу који сједи на вратима царевијем; немој изоставити ништа што си рекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'И узе Аман одијело и коња, и обуче Мардохеја и проведе га на коњу по улицама градским вичући пред њим: овако бива човјеку кога цар хоће да прослави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Потом се врати Мардохеј на врата царева, а Аман брже отиде кући својој жалостан и покривене главе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'И приповједи Аман Сереси жени својој и свијем пријатељима својим све што му се догоди. Тада му рекоше мудраци његови и Сереса жена његова: кад је од Јудејскога сјемена Мардохеј пред којим си почео падати, нећеш му одољети, него ћеш пасти пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'И док они још говораху с њим, дођоше дворани цареви и брже одведоше Амана на објед који зготови Јестира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'И тако дође цар и Аман на објед царици Јестири.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'И рече цар Јестири опет други дан напивши се вина: шта желиш, царице Јестиро? даће ти се и шта молиш? ако је и до половине царства, биће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Тада одговори царица Јестира и рече: ако сам нашла милост пред тобом, царе, и ако је цару угодно, нека ми се поклони живот мој на моју жељу и народ мој на моју молбу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Јер смо продани ја и мој народ да нас потру, побију и истријебе. Да смо продани да будемо слуге и слушкиње, мучала бих, премда непријатељ не би могао накнадити штете цару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'А цар Асвир проговори и рече царици Јестири: ко је тај? и гдје је тај који се усудио тако чинити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'А Јестира рече: противник и непријатељ овај је зликовац Аман. А Аман се уплаши од цара и од царице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Тада цар гњеван уста од вина и отиде у врт код двора, а Аман оста да моли за живот свој царицу Јестиру, јер видје да је цар наумио зло по њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Потом се цар врати из врта дворскога у кућу гдје бјеше пио вино; а Аман бјеше пао на одар гдје сјеђаше Јестира. И цар рече: еда ли ће и царицу осрамотити код мене у кући? Чим та ријеч изиде из уста царевијех, покрише лице Аману.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'И Арвона, један од дворана царевијех, рече: ево и вјешала што је начинио Аман за Мардохеја који је говорио добро по цара стоје код куће Аманове, висока педесет лаката. И рече цар: објесите га на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'И тако објесише Амана на вјешала која бјеше приправио Мардохеју. И гњев царев утиша се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Истога дана даде цар Асвир царици Јестири кућу Амана непријатеља Јудејскога. А Мардохеј изиде пред цара, јер Јестира каза шта јој је он;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'И цар снимив прстен свој, који бјеше узео од Амана, даде га Мардохеју; а Јестира постави Мардохеја над кућом Амановом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Потом Јестира опет говори цару и паднувши пред ноге његове и плачући мољаше га да уклони злоћу Амана Агагеја и мисао његову коју бјеше смислио на Јудејце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Тада цар пружи златну палицу према Јестири, и Јестира уста и стаде пред царем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'И рече: ако је угодно цару и ако сам нашла милост пред њим, и ако је право пред царем и ако сам му мила, нека се пише да се пореку књиге у којима је мисао Амана сина Амедатина, Агагеја, које је расписао да се истријебе Јудејци што су по свијем земљама царевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Јер како бих могла гледати зло које би задесило мој народ? и како бих могла гледати да се потре род мој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'А цар Асвир рече царици Јестири и Мардохеју Јудејцу: ето, дао сам кућу Амнонову Јестири а њега су објесили на вјешала зато што шћаше дигнути руку своју на Јудејце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Ви дакле пишите за Јудејце како вам је драго у име царево и запечатите прстеном царевијем; јер што се пише у име царево и запечати прстеном царевијем не може се порећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'И дозваше писаре цареве у исто вријеме, трећега мјесеца, који је мјесец Сиван, двадесет трећега дана, и писа се све, како заповједи Мардохеј, Јудејцима и намјесницима и кнезовима и управитељима по земљама, од Индије до Етиопије, сто и двадесет и седам земаља, у сваку земљу њезинијем писмом и сваком народу његовијем језиком, и Јудејцима њиховијем писмом и њиховијем језиком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'А написа у име цара Асвира и запечати прстеном царевијем, и разасла књиге по гласницима који јахаху на брзијем коњма и на младијем мазгама:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Да је цар допустио Јудејцима што су у коме год граду да се скупе и бране живот свој, да потру и побију и истријебе сваку војску којега му драго народа и земље, који би ударили на њих, и дјецу њихову и жене њихове, а имање њихово да разграбе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'У исти дан по свијем земљама цара Асвира, тринаестога дана мјесеца дванаестога, које је мјесец Адар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'У књигама се говораше да се огласи заповијест по свијем земљама и да се објави свијем народима да Јудејци буду готови за онај дан да се освете својим непријатељима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Гласници који јахаху на брзијем коњма и мазгама отидоше брзо и хитно по заповијести царевој; и заповијест би оглашена у Сусану царском граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'А Мардохеј отиде од цара у царском одијелу љубичастом и бијелом и под златнијем вијенцем великим и у плашту од танкога платна и скерлета, и град Сусан радоваше се и весељаше се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Јудејцима дође свјетлост и весеље и радост и слава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'И у свакој земљи и у сваком граду, гдје год дође заповијест царева и наредба његова, бјеше радост и весеље међу Јудејцима, гозба и благи дани, и многи из народа земаљских постајаху Јудејци, јер их попаде страх од Јевреја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'И тако дванаестога мјесеца, а то је мјесец Адар, тринаестога дана, кад дође да се изврши ријеч царева и заповијест његова, истога дана кад се непријатељи Јудејски надаху да ће обладати њима, преокрену се, те Јудејци обладаше својим ненавидницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Скупише се Јудејци у својим градовима по свијем земљама цара Асвира да дигну руке на оне који им тражаху зло; и нико не могаше стајати пред њима; јер страх од њих попаде све народе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'И сви кнезови земаљски, намјесници и управитељи и који оправљаху послове цареве, подупираху Јудејце, јер их попаде страх од Мардохеја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Јер велик бијаше Мардохеј у дому цареву, и слава његова пролажаше све земље, јер тај човјек Мардохеј биваше све већи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'И тако побише Јудејци све непријатеље своје мачем и потрше и истријебише, и учинише што хтјеше од ненавидника својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'И у Сусану царском граду убише Јудејци и истријебише пет стотина људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'И Фирсандату и Далфона и Аспату,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'И Порату и Адалију и Аридату,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'И Фармасту и Арисаја и Аридаја и Вајезату,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'Десет синова Амана сина Амедатина непријатеља Јудејскога побише, али на плијен не дигоше руке своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'У онај дан кад јавише цару број побијених у Сусану царском граду,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Рече цар Јестири царици: у Сусану царском граду побише и потрше Јудејци пет стотина људи и десет синова Амановијех, а шта су учинили по осталијем земљама царевијем? Шта желиш? даће ти се; и шта још молиш? биће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'А Јестира рече: ако је угодно цару, да се допусти Јудејцима у Сусану и сјутра да учине по данашњој наредби и десет синова Амановијех да објесе на вјешала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'И заповједи цар да буде тако. И оглашена би заповијест у Сусану, и објесише десет синова Амановијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'И Јудејци који бијаху у Сусану скупивши се и четрнаестога дана мјесеца Адара побише у Сусану три стотине људи, али на плијен не дигоше руке своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'А остали Јудејци који бијаху по земљама царевијем скупише се да бране живот свој и да се смире од непријатеља својих; и побише седамдесет и пет тисућа ненавидника својих; али на плијен не дигоше руке своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'То би тринаестога дана мјесеца Адара; а четрнаестога починуше, и празноваше тај дан гостећи се и веселећи се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'А Јудејци који бијаху у Сусану скупише се тринаестога и четрнаестога дана истога мјесеца, а починуше петнаестога, и празноваше тај дан гостећи се и веселећи се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Зато Јудејци сељани, који живе по мјестима неограђенијем, празнују четрнаести дан мјесеца Адара веселећи се и гостећи се и благујући, и шаљући дијелове један другом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Јер Мардохеј написа ово, и разасла књиге свијем Јудејцима који бијаху по свијем земљама цара Асвира, близу и далеко,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Наређујући им да празнују дан четрнаести мјесеца Адара и петнаести дан истога мјесеца сваке године;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Према данима у које се смирише Јудејци од непријатеља својих и према мјесецу кад им се претвори жалост у радост и туга у весеље, да те дане празнују гостећи се и веселећи се и шаљући дијелове један другом, и сиромасима дарове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'И примише сви Јудејци да чине што су почели и што им писа Мардохеј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Јер Аман син Амедатин Агагеј непријатељ свијех Јудејаца намисли за Јудејце да их истријеби, и баци Фур, то јест ждријеб, да их потре и истријеби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Али кад Јестира изиде пред цара, он заповједи књигом, те се зла мисао његова коју смисли на Јудејце обрати на његову главу, и објесише њега и синове његове на вјешала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Зато прозваше те дане Фурим од имена Фур; и ради својих ријечи те књиге и ради онога што видјеше, тако и ради онога што им се догоди,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Поставише Јудејци и примише на се и на сјеме своје и на све који се удруже с њима да је непромјенито да славе та два дана као што је написано за њих и на вријеме које је за њих одређено, сваке године,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'И да се ти дани спомињу и славе у сваком нараштају, у свакој породици, у свакој земљи и у сваком граду; и ти дани Фурим да не престану међу Јудејцима и спомен њихов да не погине у сјемену њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'И писа царица Јестира кћи Авихаилова и Мардохеј Јудејац сваком тврђом потврђујући књигу за Фурим други пут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'И разасла књигу свијем Јудејцима у сто и двадесет и седам земаља цара Асвира и ријечима љубазнијем и истинијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'Да тврдо држе дане Фурим на вријеме као што им је поставио Мардохеј Јудејац и царица Јестира и као што сами поставише себи и и сјемену својему за спомен посту њихову и викању њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Тако заповијест Јестирина потврди уредбу за Фурим, и би записано у књигу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Потом цар Асвир удари данак на земљу и на острва морска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'А сва дјела власти његове и силе, и приповијест о величини Мардохејевој како га је цар учинио великим, то је написано у књизи дневника царева Мидских и Персијских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Јер Мардохеј Јудејац бјеше други до цара Асвира и велик у Јудејаца и мио мноштву браће своје старајући се за добро својему народу и говорећи за срећу свега сјемена својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Бијаше човјек у земљи Узу по имену Јов; и тај човјек бијаше добар и праведан, и бојаше се Бога, и уклањаше се ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'И роди му се седам синова и три кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'И имаше стоке седам тисућа оваца и три тисуће камила и пет стотина јармова волова и пет стотина магарица, и чељади веома много; и бијаше тај човјек највећи од свијех људи на истоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'И синови његови састајаху се и даваху гозбе код куће, сваки свога дана, и слаху те позиваху три сестре своје да једу и пију с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'И кад би се обредили гозбом, пошиљаше Јов и освећиваше их, и устајући рано приношаше жртве паљенице према броју свијех њих; јер говораше Јов: може бити да су се огријешили синови моји и похулили на Бога у срцу свом. Тако чињаше Јов сваки пут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'А један дан дођоше синови Божји да стану пред Господом, а међу њих дође и Сотона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'И Господ рече Сотони: откуда идеш? А Сотона одговори Господу и рече: проходих земљу и обилазих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'И рече Господ Сотони: јеси ли видио слугу мојега Јова? нема онакога човјека на земљи, добра и праведна, који се боји Бога и уклања се ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'А Сотона одговори Господу и рече: еда ли се узалуд Јов боји Бога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Нијеси ли га ти оградио и кућу његову и све што има свуда унаоколо? дјело руку његовијех благословио си, и стока се његова умножила на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Али пружи руку своју и дотакни се свега што има, псоваће те у очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'А Господ рече Сотони: ево, све што има нека је у твојој руци; само на њега не дижи руке своје. И отиде Сотона од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'А један дан кад синови његови и кћери његове јеђаху и пијаху вино у кући брата својега најстаријега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Дође гласник Јову и рече: волови ораху и магарице пасијаху покрај њих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'А Савеји ударише и отеше их, и побише момке оштријем мачем; и само ја један утекох да ти јавим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Док овај још говораше, дође други и рече: огањ Божји спаде с неба и спали овце и момке, и прождрије их; и само ја један утекох да ти јавим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Докле овај још говораше, дође други и рече: Халдејци у три чете ударише на камиле и отеше их, и побише момке оштријем мачем; и само ја један утекох да ти јавим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Докле овај још говораше, дође други и рече: синови твоји и кћери твоје јеђаху и пијаху вино у кући брата својега најстаријега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'А то вјетар велик дође испреко пустиње и удари у четири угла од куће, те паде на дјецу и погибоше; и само ја један утекох да ти јавим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Тада уста Јов и раздрије плашт свој, и остриже главу, и паде на земљу и поклони се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'И рече: го нам изашао из утробе матере своје, го ћу се и вратити онамо. Господ даде, Господ узе, да је благословено име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Уза све то не сагријеши Јов, нити рече безумља за Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Опет један дан дођоше синови Божји да стану пред Господом, а дође и Сотона међу њих да стане пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'И Господ рече Сотони: откуда идеш? А Сотона одговори Господу и рече: проходих земљу и обилазих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'И рече Господ Сотони: јеси ли видио слугу мојега Јова? нема онакога човјека на земљи, добра и праведна, који се боји Бога и уклања се ода зла, и још се држи доброте своје, премда си ме наговорио, те га упропастих ни за што.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'А Сотона одговори Господу и рече: кожа за кожу, и све што човјек има даће за душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Него пружи руку своју и дотакни се костију његовијех и меса његова, псоваће те у очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'А Господ рече Сотони: ево ти га у руке; али му душу чувај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'И Сотона отиде од Господа, и удари Јова злијем приштем од пете до тјемена,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Те он узе цријеп па се стругаше, и сјеђаше у пепелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'И рече му жена: хоћеш ли се још држати доброте своје? Благослови Бога, па умри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'А он јој рече: говориш као луда жена; добро смо примали од Бога, а зла зар нећемо примати? Уза све то не сагријеши Јов уснама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'А три пријатеља Јовова чуше за све зло које га задеси, и дођоше сваки из својега мјеста, Елифас Теманац и Вилдад Сушанин и Софар Намаћанин, договорише се да дођу да га пожале и потјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'И подигавши очи своје издалека не познаше га; тада подигоше глас свој и стадоше плакати и раздријеше сваки свој плашт и посуше се прахом по глави бацајући га у небо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'И сјеђаху код њега на земљи седам дана и седам ноћи, и ни један му не проговори ријечи, јер виђаху да је бол врло велик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Потом отвори уста своја Јов и стаде клети дан свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'И проговорив Јов рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Не било дана у који се родих, и ноћи у којој рекоше: роди се дјетић!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Био тај дан тама, не гледао га Бог озго, и не осветљавала га свјетлост!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Мрак га запрзнио и сјен смртни, облак га обастирао, био страшан као најгори дани!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Ноћ ону освојила тама, не радовала се међу данима годишњим, не бројила се у мјесеце!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Гле, ноћ она била пуста, пјевања не било у њој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Клели је који куну дане, који су готови пробудити крокодила!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Потамњеле звијезде у сумрачје њезино, чекала видјело и не дочекала га, и не видјела зори трепавица;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Што ме није затворила врата од утробе и није сакрила муку од мојих очију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Зашто не умријех у утроби? не издахнух излазећи из утробе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Зашто ме прихватише кољена? зашто сисе, да сем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Јер бих сада лежао и почивао; спавао бих, и био бих миран,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'С царевима и савјетницима земаљским, који зидаше себи пустолине,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Или с кнезовима, који имаше злата, и куће своје пунише сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Или зашто не бих као недоношче сакривено, као дијете које не угледа видјела?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Ондје безбожници престају досађивати, и ондје почивају изнемогли,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'И сужњи се одмарају и не чују гласа настојникова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Мали и велики ондје је, и роб слободан од свога господара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Зашто се даје видјело невољнику и живот онима који су тужна срца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'Који чекају смрт а ње нема, и траже је већма него закопано благо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'Који играју од радости и веселе се кад нађу гроб?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'Човјеку, којему је пут сакривен и којега је Бог затворио отсвуда?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Јер прије јела мојега долази уздах мој, и као вода разљева се јаук мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Јер чега се бојах дође на мене, и чега се страшах задеси ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Не почивах нити имах мира нити се одмарах, и опет дође страхота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Тада одговори Елифас Теманац и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Ако ти проговоримо, да ти неће бити досадно? али ко би се могао уздржати да не говори?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Гле, учио си многе, и руке изнемогле кријепио си;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Ријечи су твоје подизале онога који падаше, и утврђивао си кољена која клецаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'А сада кад дође на тебе, клонуо си; кад се тебе дотаче, смео си се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Није ли побожност твоја била уздање твоје? и доброта путова твојих надање твоје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Опомени се, ко је прав погинуо, и гдје су праведни истријебљени?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Како сам ја видио, који ору муку и сију невољу, то и жању.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Од дихања Божијега гину, и од даха ноздара његовијех нестаје их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Рика лаву, и глас љутом лаву и зуби лавићима сатиру се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Лав гине немајући лова, и лавићи расипају се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Још дође тајно до мене ријеч, и ухо моје дочу је мало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'У мислима о ноћнијем утварама, кад тврд сан пада на људе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Страх подузе ме и дрхат, од којега устрепташе све кости моје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'И дух прође испред мене, и длаке на тијелу мом накостријешише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Стаде, али му не познах лица; прилика бијаше пред очима мојима, и мучећи чух глас:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Еда ли је човјек праведнији од Бога? еда ли је човјек чистији од Творца својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Гле, слугама својим не вјерује, и у анђела својих налази недостатака;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Акамоли у онијех који стоје у кућама земљанијем, којима је темељ на праху и сатиру се брже него мољац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Од јутра до вечера сатру се, и нестане их навијек да нико и не опази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Слава њихова не пролази ли с њима? Умиру, али не у мудрости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Зови; хоће ли ти се ко одазвати? и кому ћеш се између светијех обратити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Доиста безумнога убија гњев, и лудога усмрћује срдња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Ја видјех безумника гдје се укоријенио; али одмах проклех стан његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Синови су његови далеко од спасења и сатиру се на вратима а нема ко да избави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Љетину његову једе гладни и испред трња купи је, и лупеж ждере благо њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Јер мука не излази из праха нити невоља из земље ниче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Него се човјек рађа на невољу, као што искре из угљевља узлијећу у вис.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Али ја бих Бога тражио, и пред Бога бих изнио ствар своју,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Који чини ствари велике и неиспитљиве, дивне, којима нема броја;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Који спушта дажд на земљу и шаље воду на поља;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Који подиже понижене, и жалосне узвишује к спасењу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Који расипа мисли лукавијех да руке њихове не сврше ништа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Који хвата мудре у њихову лукавству, и намјеру опаких обара;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Дању наилазе на мрак, и у подне пипају као по ноћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Он избавља убогога од мача, од уста њиховијех и од руке силнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Тако има надања сиромаху, а злоћа затискује уста своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Гле, благо човјеку кога Бог кара; и зато не одбацуј карање Свемогућега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Јер он задаје ране, и завија; он удара, и руке његове исцјељују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Из шест невоља избавиће те; ни у седмој неће те се зло дотаћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'У глади избавиће те од смрти и у рату од мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Кад језик шиба, бићеш сакривен, нити ћеш се бојати пустоши кад дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Смијаћеш се пустоши и глади, нити ћеш се бојати звијерја земаљскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Јер ћеш с камењем пољским бити у вјери, и звијерје ће пољско бити у миру с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'И видјећеш да је мир у шатору твом, кућићеш кућу своју и нећеш се преварити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Видјећеш како ће ти се умножити сјеме твоје, и пород ће твој бити као трава на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Стар ћеш отићи у гроб као што се жито сноси у стог у своје вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Ето, разгледасмо то, тако је; послушај и разумиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'А Јов одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'О да би се добро измјерили јади моји, и заједно се невоља моја метнула на мјерила!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Претегла би пијесак морски; зато ми и ријечи недостаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Јер су стријеле Свемогућега у мени, отров њихов испија ми дух, страхоте Божије ударају на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Риче ли дивљи магарац код траве? муче ли во код пиће своје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Једе ли се бљутаво без соли? има ли сласти у биоцу од јајца?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Чега се душа моја није хтјела дотакнути, то ми је јело у невољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'О да би ми се испунила молба, и да би ми Бог дао што чекам!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'И да би Бог хтио сатрти ме, да би махнуо руком својом, и истријебио ме!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Јер ми је још утјеха, ако и горим од бола нити ме жали, што нијесам тајио ријечи светога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Кака је сила моја да бих претрпио? какав ли је крај мој да бих продуљио живот свој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Је ли сила моја камена сила? је ли тијело моје од мједи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Има ли још помоћи у мене? и није ли далеко од мене што би ме придржало?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Несрећному треба милост пријатеља његова, али је он оставио страх Свемогућега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Браћа моја изневјерише као поток, као бујни потоци прођоше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Који су мутни од леда, у којима се сакрива снијег;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Кад се откраве, отеку; кад се загрију, нестане их с мјеста њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Тамо амо сврћу од путова својих, иду у ништа и губе се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Путници из Теме погледаху, који иђаху у Севу уздаху се у њих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Али се постидјеше што се поуздаше у њих, дошавши до њих осрамотише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Тако и ви постасте ништа; видјесте погибао моју, и страх вас је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Еда ли сам вам рекао: дајте ми, или од блага својега поклоните ми;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'Или избавите ме из руке непријатељеве, и из руке насилничке искупите ме?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Поучите ме, и ја ћу мучати; и у чему сам погријешио, обавијестите ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Како су јаке ријечи истините! Али шта ће укор ваш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Мислите ли да ће ријечи укорити, и да је говор човјека без надања вјетар?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'И на сироту нападате, и копате јаму пријатељу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Зато сада погледајте ме, и видите лажем ли пред вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Прегледајте; да не буде неправде; прегледајте, ја сам прав у том.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Има ли неправде на језику мојем? не разбира ли грло моје зла?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Није ли човјек на војсци на земљи? а дани његови нијесу ли као дани надничарски?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Као што слуга уздише за сјеном и као што надничар чека да сврши,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Тако су мени дати у нашљедство мјесеци залудни и ноћи мучне одређене ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Кад легнем, говорим: кад ћу устати? и кад ће проћи ноћ? и ситим се преврћући се до сванућа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Тијело је моје обучено у црве и у груде земљане, кожа моја пуца и рашчиња се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Дани моји бржи бише од чунка, и прођоше без надања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Опомени се да је мој живот вјетар, да око моје неће више видјети добра,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Нити ће ме видјети око које ме је виђало; и твоје очи кад погледају на ме, мене неће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Као што се облак разилази и нестаје га, тако ко сиђе у гроб, неће изаћи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Неће се више вратити кући својој, нити ће га више познати мјесто његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Зато ја нећу бранити устима својим, говорићу у тузи духа својега, нарицати у јаду душе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Еда ли сам море или кит, те си намјестио стражу око мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Кад речем: потјешиће ме одар мој, постеља ће ми моја облакшати тужњаву,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Тада ме страшиш снима и препадаш ме утварама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Те душа моја воли бити удављена, воли смрт него кости моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Додијало ми је; нећу довијека живјети; прођи ме се; јер су дани моји таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Шта је човјек да га много цијениш и да мариш за њ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'Да га походиш свако јутро, и сваки час кушаш га?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Кад ћеш се одвратити од мене и пустити ме да прогутам пљуванку своју?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Згријешио сам; шта ћу ти чинити, о чувару људски? зашто си ме метнуо себи за биљегу, те сам себи на тегобу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Зашто ми не опростиш гријех мој и не уклониш моје безакоње? јер ћу сад лећи у прах, и кад ме потражиш, мене неће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Тада одговори Вилдад Сушанин и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Докле ћеш тако говорити? и ријечи уста твојих докле ће бити као силан вјетар?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Еда ли Бог криво суди? или Свемогући изврће правду?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Што су синови твоји згријешили њему, зато их је дао безакоњу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'А ти да потражиш Бога и помолиш се Свемогућему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Ако си чист и прав, заиста ће се пренути за те и честит ће учинити праведан стан твој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'И почетак ће твој бити мален, а пошљедак ће ти бити врло велик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Јер питај пређашњи нараштај, и настани да разабереш од отаца њиховијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Јер смо ми јучерашњи, и не знамо ништа, јер су наши дани на земљи сјен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Неће ли те они научити? неће ли ти казати и из срца својега изнијети ријечи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Ниче ли сита без влаге? расте ли рогоз без воде?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Док се још зелени, док се не покоси, суши се прије сваке траве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Таке су стазе свијех који заборављају Бога, и надање лицемјерово пропада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Његово се надање подлама и уздање је његово кућа паукова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Наслони се на кућу своју, али она не стоји тврдо; ухвати се за њу, али се она не може одржати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Зелени се на сунцу, и уврх врта његова пружају се огранци његови;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Жиле његове заплећу се код извора, и на мјесту камениту шири се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Али кад се ишчупа из мјеста својега, оно га се одриче: нијесам те видјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Ето, то је радост од његова пута; а из праха ниче други.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Гле, Бог не одбацује доброга, али не прихвата за руку зликовца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Још ће напунити уста твоја смијеха и усне твоје попијевања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Ненавидници твоји обући ће се у срамоту, и шатора безбожничкога неће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'А Јов одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Заиста, знам да је тако; јер како би могао човјек бити прав пред Богом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Ако би се хтио прети с њим, не би му могао одговорити од тисуће на једну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Мудар је срцем и јак снагом; ко се је опро њему и био срећан?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Он премјешта горе, да нико и не опази; превраћа их у гњеву свом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'Он креће земљу с мјеста њезина да јој се ступови дрмају;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Он кад запријети сунцу, не излази; он запечаћава звијезде;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'Он разапиње небо сам, и гази по валима морским;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'Он је начинио звијезде кола и штапе и влашиће и друге југу у дну;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'Он чини ствари велике и неиспитљиве и дивне, којима нема броја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Гле, иде мимо мене, а ја не видим; прође, а ја га не опазим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Гле, кад ухвати, ко ће га нагнати да врати? ко ће му казати: шта радиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Бог не устеже гњева својега, падају пода њ охоли помоћници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'А како би му ја одговарао и бирао ријечи против њега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Да сам и прав, нећу му се одговорити, ваља да се молим судији својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Да га зовем и да ми се одзове, још не могу вјеровати да је чуо глас мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Јер ме је вихором сатро и задао ми много рана ни за што.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Не да ми да одахнем, него ме сити грчинама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Ако је на силу, гле, он је најсилнији; ако на суд, ко ће ми свједочити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Да се правдам, моја ће ме уста осудити; да сам добар, показаће да сам неваљао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Ако сам добар, нећу знати за то; омрзао ми је живот мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Свеједно је; зато рекох: и доброга и безбожнога он потире.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Кад би још убио бич наједанпут! али се смије искушавању правијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Земља се даје у руке безбожнику; лице судија њезинијех заклања; ако не он, да ко?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Али дани моји бише бржи од гласника; побјегоше, не видјеше добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Прођоше као брзе лађе, као орао кад лети за храну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Ако речем: заборавићу тужњаву своју, оставићу гњев свој и окријепићу се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Страх ме је од свијех мука мојих, знам да ме нећеш оправдати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Бићу крив; зашто бих се мучио узалуд?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Да се измијем водом шњежницом, и да очистим сапуном руке своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Тада ћеш ме замочити у јаму да се гаде на ме моје хаљине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Јер није човјек као ја да му одговарам, да идем с њим на суд;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Нити има међу нама кмета да би ставио руку своју међу нас двојицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Нека одмакне од мене прут свој, и страх његов нека ме не страши;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Тада ћу говорити, и нећу га се бојати; јер овако не знам за себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Додијао је души мојој живот живот мој; пустићу од себе тужњаву своју, говорићу у јаду душе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Рећи ћу Богу: немој ме осудити; кажи ми зашто се преш са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Је ли ти мило да чиниш силу, да одбацујеш дјело руку својих и савјет безбожнички обасјаваш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Јесу ли у тебе очи тјелесне? видиш ли као што види човјек?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Јесу ли дани твоји као дани човјечји, и године твоје као вијек људски,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Те истражујеш моје безакоње и за гријех мој разбираш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Ти знаш да нијесам крив, и нема никога ко би избавио из твоје руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Твоје су ме руке створиле и начиниле, и ти ме отсвуда потиреш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Опомени се да си ме као од кала начинио, и опет ћеш ме у прах обратити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Нијеси ли ме као млијеко слио и као сир усирио ме?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Навукао си на ме кожу и месо, и костима и жилама сплео си ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Животом и милошћу даривао си ме; и старање твоје чувало је дух мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'И сакрио си то у срцу својему; али знам да је у тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Ако сам згријешио, опазио си ме, и нијеси ме опростио безакоња мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Ако сам скривио, тешко мени! ако ли сам прав, не могу подигнути главе, пун срамоте и видећи муку своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'И ако се подигне, гониш ме као лав, и опет чиниш чудеса на мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Понављаш свједочанства своја против мене, и умножаваш гњев свој на ме; војске једне за другом излазе на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Зашто си ме извадио из утробе? о да умријех! да ме ни око не видје!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Био бих као да нигда нијесам био; из утробе у гроб био бих однесен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Није ли мало дана мојих? престани дакле и окани ме се да се мало опоравим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Прије него отидем одакле се нећу вратити, у земљу тамну и у сјен смртни,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'У земљу тамну као мрак и у сјен смртни, гдје нема промјене и гдје је видјело као тама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'А Софар Намаћанин одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Зар на многе ријечи нема одговора? или ће човјек говорљив остати прав?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Хоће ли твоје лажи умучкати људе? и кад се ругаш, зар те неће нико посрамити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Јер си рекао: чиста је наука моја, и чист сам пред очима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Али кад би Бог проговорио и усне своје отворио на те,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'И показао ти тајне мудрости, јер их је двојином више, познао би да те Бог кара мање него што заслужује твоје безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Можеш ли ти тајне Божије докучити, или докучити савршенство Свемогућега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'То су висине небеске, шта ћеш учинити? дубље је од пакла, како ћеш познати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Дуже од земље, шире од мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Да преврати, или затвори или сабере, ко ће му бранити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Јер зна ништавило људско, и видећи неваљалство зар неће пазити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Човјек безуман постаје разуман, премда се човјек рађа као дивље магаре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Да ти управиш срце своје и подигнеш руке своје к њему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Ако је безакоње у руци твојој, да га уклониш, и не даш да неправда буде у шаторима твојим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Тада ћеш подигнути лице своје без мане и стајаћеш тврдо и нећеш се бојати;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Заборавићеш муку, као воде која протече опомињаћеш је се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Настаће ти вријеме ведрије него подне, синућеш, бићеш као јутро;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Уздаћеш се имајући надање, закопаћеш се, и мирно ћеш спавати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Лежаћеш, и нико те неће плашити, и многи ће ти се молити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Али очи ће безбожницима ишчиљети, и уточишта им неће бити, и надање ће им бити издисање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'А Јов одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Да, ви сте људи, и с вама ће умријети мудрост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'И ја имам срце као и ви, нити сам гори од вас; и у кога нема тога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'На потсмијех сам пријатељу свом, који кад зове Бога одазове му се; на потсмијех је праведни и добри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Бачен је луч по мишљењу срећнога онај који хоће да попузне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Мирне су колибе лупешке, и без страха су који гњеве Бога, њима Бог даје све у руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Запитај стоку, научиће те; или птице небеске, казаће ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Или се разговори са земљом, научиће те, и рибе ће ти морске приповједити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Ко не зна од свега тога да је рука Господња то учинила?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'Којему је у руци душа свега живога и дух свакога тијела човјечијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Не распознаје ли ухо ријечи као што грло куша јело?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'У старца је мудрост, и у дугом вијеку разум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'У њега је мудрост и сила, у њега је савјет и разум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Гле, он разгради, и не може се опет саградити; затвори човјека, и не може се отворити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Гле, устави воде, и пресахну; пусти их, и испреврћу земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'У њега је јачина и мудрост, његов је који је преварен и који вара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Он доводи савјетнике у лудило, и судије обезумљује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Он раздрешује појас царевима, и опасује бедра њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Он доводи кнезове у лудило, и обара јаке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Он узима бесједу рјечитима, и старцима узима разум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Он сипа срамоту на кнезове, и распасује јунаке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Он открива дубоке ствари испод таме, и изводи на видјело сјен смртни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Он умножава народе и затире их, расипа народе и сабира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Он одузима срце главарима народа земаљских, и заводи их у пустињу гдје нема пута,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Да пипају по мраку без видјела, и чини да тумарају као пијани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Ето, све је то видјело око моје, чуло ухо моје, и разумјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Што ви знате, знам и ја, нијесам гори од вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Ипак бих говорио са Свемогућим, и рад сам с Богом правдати се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Јер ви измишљате лажи, сви сте залудни љекари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'О да бисте сасвијем мучали! били бисте мудри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Чујте мој одговор, и слушајте разлоге уста мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Треба ли да говорите за Бога неправду или пријевару да говорите за њ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Треба ли да му гледате ко је? треба ли да се препирете за Бога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Хоће ли бити добро кад вас стане испитивати? хоћете ли га преварити као што се вара човјек?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Заиста ће вас карати, ако тајно узгледате ко је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Величанство његово неће ли вас уплашити? и страх његов неће ли вас спопасти?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Спомени су ваши као пепео, и ваше висине као гомиле блата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Мучите и пустите ме да ја говорим, па нека ме снађе шта му драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Зашто бих кидао месо своје својим зубима и душу своју метао у своје руке?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Гле, да ме и убије, опет ћу се уздати у њ, али ћу бранити путове своје пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'И он ће ми бити спасење, јер лицемјер неће изаћи преда њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Слушајте добро бесједу моју, и нека вам уђе у уши што ћу исказати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Ево, спремио сам парбу своју, знам да ћу бити прав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Ко ће се прети са мном? да сад умукнем, издахнуо бих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Само двоје немој ми учинити, па се нећу крити од лица твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Уклони руку своју од мене, и страх твој да ме не страши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Потом зови ме, и ја ћу одговарати; или ја да говорим, а ти ми одговарај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Колико је безакоња и гријеха мојих? покажи ми пријеступ мој и гријех мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Зашто скриваш лице своје и држиш ме за непријатеља својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Хоћеш ли скршити лист који носи вјетар или ћеш гонити суху сламку,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Кад ми пишеш грчине, и дајеш ми у нашљедство гријехе младости моје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'И мећеш ноге моје у кладе, и пазиш на све стазе моје и идеш за мном устопце?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'А он се распада као трулина, као хаљина коју једе мољац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Човјек рођен од жене кратка је вијека и пун немира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Као цвијет ниче, и одсијеца се, и бјежи као сјен, и не остаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'И на такога отвораш око своје, и мене водиш на суд са собом!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Ко ће чисто извадити из нечиста? Нико.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Измјерени су дани његови, број мјесеца његовијех у тебе је; поставио си му међу, преко које не може пријећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Одврати се од њега да почине докле не наврши као надничар дан свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Јер за дрво има надања, ако се посијече, да ће се још омладити и да неће бити без изданака;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Ако и остари у земљи коријен његов и у праху изумре пањ његов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'Чим осјети воду, опет напупи и пусти гране као присад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'А човјек умире изнемогао; и кад издахне човјек, гдје је?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Као кад вода отече из језера и ријека опадне и усахне,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Тако човјек кад легне, не устаје више; докле је небеса неће се пробудити нити ће се пренути ода сна својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'О да ме хоћеш у гробу сакрити и склонити ме докле не утоли гњев твој, и да ми даш рок кад ћеш ме се опоменути!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Кад умрије човјек, хоће ли оживјети? Све дане времена које ми је одређено чекаћу докле ми дође промјена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Зазваћеш, и ја ћу ти се одазвати; дјело руку својих пожељећеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'А сада бројиш кораке моје, и ништа не остављаш за гријех мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Запечаћени су у тобоцу моји пријеступи, и завезујеш безакоња моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Заиста, као што гора падне и распадне се, и као што се стијена одвали с мјеста својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'И као што вода спира камење и поводањ односи прах земаљски, тако надање човјечије обраћаш у ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Надвлађујеш га једнако, те одлази, мијењаш му лице и отпушташ га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Ако синови његови буду у части, он не зна; ако ли у срамоти, он се не брине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Само тијело док је жив болује, и душа његова у њему тужи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'А Елифас Теманац одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Хоће ли мудар човјек казивати празне мисли и пунити трбух вјетром источнијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Препирући се говором који не помаже и ријечима које нијесу ни на што?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'А ти уништаваш страх Божји и укидаш молитве к Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Јер безакоње твоје показују уста твоја, ако и јеси изабрао језик лукав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Осуђују те уста твоја, а не ја; и усне твоје свједоче на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Јеси ли се ти први човјек родио? или си прије хумова саздан?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Јеси ли тајну Божију чуо и покупио у себе мудрост?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Шта ти знаш што ми не бисмо знали? шта ти разумијеш што не би било у нас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'И сиједијех и старих људи има међу нама, старијих од оца твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Мале ли су ти утјехе Божије? или имаш што сакривено у себи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Што те је занијело срце твоје? и што сијевају очи твоје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Те обраћаш против Бога дух свој и пушташ из уста својих таке ријечи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Шта је човјек, да би био чист, и рођени од жене, да би био прав?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Гле, не вјерује свецима својим, и небеса нијесу чиста пред очима његовијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Акамоли гадни и смрдљиви човјек, који пије неправду као воду?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Ја ћу ти казати, послушај ме, и приповједићу ти што сам видио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'Што мудраци казаше и не затајише, што примише од отаца својих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'Којима самијем дана би земља, и туђин не прође кроз њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Безбожник се мучи свега вијека својега, и насилнику је мало година остављено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Страх му зуји у ушима, у мирно доба напада пустошник на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Не вјерује да ће се вратити из таме, отсвуда привиђа мач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Тумара за хљебом говорећи: гдје је? Зна да је за њ спремљен дан тамни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Туга и невоља страше га, и наваљују на њ као цар готов на бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Јер је замахнуо на Бога руком својом, и свемогућему се опро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Трчи исправљена врата на њ с многим високим штитовима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Јер је покрио лице своје претилином, и наваљао сало на бокове своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'И сједио је у градовима раскопанијем и у кућама пустијем, обраћенијем у гомилу камења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Неће се обратити нити ће остати благо његово, и неће се раширити по земљи добро његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Неће изаћи из мрака, огранке његове осушиће пламен, однијеће га дух уста његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Нека се не узда у таштину преварени, јер ће му таштина бити плата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Прије својега времена свршиће се, и грана његова неће зелењети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Откинуће се као с лозе незрео грозд његов и пупци ће се његови као с маслине побацати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Јер ће опустјети збор лицемјерски, и огањ ће спалити шаторе онијех који примају поклоне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Зачињу невољу и рађају муку, и трбух њихов саставља пријевару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'А Јов одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Слушао сам много таких ствари; сви сте досадни тјешиоци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Хоће ли бити крај празнијем ријечима? или шта те тјера да тако одговараш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'И ја бих могао говорити као ви, да сте на мом мјесту, гомилати на вас ријечи и махати главом на вас,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Могао бих вас храбрити устима својим, и мицање усана мојих облакшало би бол ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Ако говорим, неће одахнути бол мој; ако ли престанем, хоће ли отићи од мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'А сада ме је уморио; опустошио си сав збор мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Навукао си на ме мрштине за свједочанство; и моја мрша подиже се на ме, и свједочи ми у очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Гњев његов растрже ме, ненавиди ме, шкргуће зубима на ме, поставши ми непријатељ сијева очима својима на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Разваљују на ме уста своја, срамотно ме бију по образима, скупљају се на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Предао ме је Бог неправеднику, и у руке безбожницима бацио ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Бијах миран и затр ме, и ухвативши ме за врат смрска ме и метну ме себи за биљегу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Опколише ме његови стријелци, цијепа ми бубреге немилице, просипа на земљу жуч моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Задаје ми ране на ране, и удара на ме као јунак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Сашио сам костријет по кожи својој, и уваљао сам у прах славу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Лице је моје подбуло од плача, на вјеђама је мојим смртни сјен;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Премда нема неправде у рукама мојим, и молитва је моја чиста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Земљо, не криј крви што сам пролио, и нека нема мјеста викању мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'И сада ето је на небу свједок мој, свједок је мој на висини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Пријатељи се моји подругују мном; око моје рони сузе Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'О да би се човјек могао правдати с Богом, као син човјечији с пријатељем својим!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Јер године избројене навршују се, и полазим путем одакле се нећу вратити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Дух се мој квари, дана мојих нестаје; гробови су моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Код мене су ругачи, и око моје проводи ноћи у јаду који ми задају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Дај ми ко ће јамчити код тебе; ко је тај који ће се руковати са мном?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Јер си од њихова срца сакрио разум; зато их нећеш узвисити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Ко ласка пријатељима, његовијем ће синовима очи посахнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Учинио је од мене причу народима, и постао сам бубњање међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Потамњело је око моје од јада, и сви уди моји посташе као сјен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Зачудиће се томе прави, и безазлени ће устати на лицемјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Али ће се праведник држати својега пута, и ко је чистијех руку већма ће ојачати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'А ви вратите се свиколики и ходите; нећу наћи мудра међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Дани моји прођоше, мисли моје покидаше се, што имах у срцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Од ноћи начинише дан, и свјетлост је близу мрака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Да бих се надао, гроб ће ми бити кућа; у тами ћу простријети постељу себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Гробу вичем: ти си отац мој; црвима: ти си мати моја, ти си сестра моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'И гдје је сада надање моје? моје надање ко ће видјети?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'У гроб ће сићи, починуће са мном у гробу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'А Вилдад Сушанин одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Кад ћете свршити разговор? Оразумите се, па ћемо онда говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Зашто се мисли да смо као стока? зашто смо гадни у вашим очима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Који растржеш душу своју у јарости својој, хоће ли се тебе ради оставити земља и стијена се премјестити са својега мјеста?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Да, видјело безбожнијех угасиће се, и искра огња њихова неће сијати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Видјело ће помркнути у шатору његову, и жижак ће се његов угасити у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Силни кораци његови стегнуће се, и обориће га његова намјера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Јер ће се увалити у замку ногама својим и наићи ће на мрежу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Ухватиће га замка за пету и свладаће га лупеж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Сакривено му је пругло на земљи, и клопка на стази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Отсвуда ће га страхоте страшити и тјераће га устопце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Изгладњеће сила његова, и невоља ће бити готова уза њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Појешће жиле коже његове, појешће жиле његове првенац смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Ишчупаће се из стана његова узданица његова, и то ће га одвести к цару страшном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Наставаће се у шатору његову, који неће бити његов, посуће се сумпором стан његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Жиле ће се његове посушити оздо, и озго ће се сасјећи гране његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Спомен ће његов погинути на земљи, нити ће му имена бити по улицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Одагнаће се из свјетлости у мрак, и избациће се из свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Ни сина ни унука неће му бити у народу његову, нити какога остатка у становима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Чудиће се дану његову који буду послије њега, а који су били прије обузеће их страх.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Таки су станови безаконикови, и тако је мјесто онога који не зна за Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'А Јов одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Докле ћете мучити душу моју и сатирати ме ријечима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Већ сте ме десет пута наружили; није вас стид што тако наваљујете на ме?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Али ако сам доиста погријешио, погрјешка ће моја остати код мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Ако ли се још хоћете да дижете на ме и да ме корите мојом срамотом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Онда знајте да ме је Бог оборио и мрежу своју разапео око мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Ето, вичем на неправду, али се не слушам; вапијем, али нема суда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Заградио је пут мој да не могу проћи; на стазе моје метнуо је мрак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Свукао је с мене славу моју и скинуо вијенац с главе моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Порушио ме је отсвуда, да ме нема; и као дрво ишчупао је надање моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Распалио се на ме гњев његов, и узео ме је међу непријатеље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Војске његове дођоше све заједно и насуше к себи пут к мени, стадоше у око около шатора мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Браћу моју удаљио је од мене, и знанци моји туђе се од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Ближњи моји оставише ме, и знанци моји заборавише ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Домашњи моји и моје слушкиње гледају ме као туђина; странац сам у очима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Зовем слугу својега, а он се не одзива, а молим га устима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Дах је мој мрзак жени мојој, а преклињем је синовима утробе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Ни дјеца не хају за ме; кад устанем, руже ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Мрзак сам свјема невјернијем својим, и које љубљах посташе ми противници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'За кожу моју као за месо моје прионуше кости моје; једва оста кожа око зуба мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Смилујте се на ме, смилујте се на ме, пријатељи моји, јер се рука Божија дотакла мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Зашто ме гоните као Бог, и меса мојега не можете да се наситите?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'О кад би се написале ријечи моје! кад би се ставиле у књигу!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Писаљком гвозденом и оловом на камену за вјечни спомен кад би се урезале!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Али знам да је жив мој искупитељ, и на пошљедак да ће стати над прахом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'И ако се ова кожа моја и рашчини, опет ћу у тијелу свом видјети Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Ја исти видјећу га, и очи моје гледаће га, а не друге. А бубрега мојих нестаје у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Него би требало да речете: зашто га гонимо? кад је коријен бесједе у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Бојте се мача; јер је мач освета за безакоње; и знајте да има суд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'А Софар Намаћанин одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Зато ме мисли моје нагоне да одговорим, и зато хитим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Чуо сам укор који ме срамоти, али ће дух из разума мојега одговорити за ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Не знаш ли да је тако откако је вијека, од како је постављен човјек на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Да је слава безбожнијех за мало и радост лицемјерова зачас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Да би му висина допрла до неба, и глава се његова дотакла облака,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'Нестаће га за свагда као кала његова; и који га видјеше рећи ће: куда се дједе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Као сан одлетјеће, и неће се наћи, и ишчезнуће као ноћна утвара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Око које га је гледало неће више, нити ће га више видјети мјесто његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Синови његови умиљаваће се сиромасима и руке ће његове враћати што је отео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Кости ће његове бити пуне гријеха младости његове, и они ће лежати с њим у праху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Ако му је слатка у устима злоћа и крије је под језиком својим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'Чува је и не пушта је, него је задржава у грлу свом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Ипак ће се јело његово претворити у цријевима његовијем, постаће у њему јед аспидин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Благо што је прождро избљуваће, из трбуха његова истјераће га Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Јед ће аспидин сисати, убиће га језик гујињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Неће видјети потока ни ријека којима тече мед и масло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Вратиће муку, а неће је појести; према благу биће промјена, и неће се радовати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Јер је тлачио и остављао убоге, куће је отимао и није зидао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Јер није нигда осјетио мира у трбуху свом, ни што му је најмилије неће сачувати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Ништа му неће остати од хране његове. Зато не може добро његово трајати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Кад се испуни изобиље његово, тада ће бити у невољи; све руке невољнијех удариће на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Кад би напунио трбух свој, послаће на њ Бог јарост гњева својега, и пустиће је као дажд на њега и на јело његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Кад стане бјежати од оружја гвозденога, простријелиће га лук мједени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Стријела пуштена проћи ће кроз тијело његово, и свијетло гвожђе изаћи ће из жучи његове; кад пође, обузеће га страхоте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Све ће таме бити сакривене у тајним мјестима његовијем; прождријеће га огањ нераспирен, и ко остане у шатору његову зло ће му бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Откриће небеса безакоње његово, и земља ће устати на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Отићи ће љетина дома његова, расточиће се у дан гњева његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'То је дио од Бога човјеку безбожному и нашљедство од Бога за бесједу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'А Јов одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Слушајте добро ријечи моје, и то ће ми бити од вас утјеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Потрпите ме да ја говорим, а кад изговорим, потсмијевате ми се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Еда ли се ја човјеку тужим? и како не би био жалостан дух мој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Погледајте на ме, и дивите се, и метните руку на уста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Ја кад помислим, страх ме је, и гроза подузима тијело моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Зашто безбожници живе? старе? и богате се?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Сјеме њихово стоји тврдо пред њима заједно с њима, и натражје њихово пред њиховијем очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Куће су њихове на миру без страха, и прут Божји није над њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Бикови њихови скачу, и не промашују; краве њихове теле се, и не јалове се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Испуштају као стадо дјецу своју, и синови њихови поскакују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Подвикују уз бубањ и уз гусле, веселе се уза свиралу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Проводе у добру дане своје, и зачас слазе у гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'А Богу кажу: иди од нас, јер нећемо да знамо за путове твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Шта је Свемогући да му служимо? и кака нам је корист, да му се молимо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Гле, добро њихово није у њиховој руци; намјера безбожничка далеко је од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Колико се пута гаси жижак безбожнички и долази им погибао, дијели им муке у дијелу свом Бог?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Бивају као пљева на вјетру, као прах који разноси вихор?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Чува ли Бог синовима његовијем погибао њихову, плаћа им да осјете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Виде ли својим очима погибао своју, и пију ли гњев Свемогућега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Јер шта је њима стало до куће њихове након њих, кад се број мјесеца њиховијех прекрати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Еда ли ће Бога ко учити мудрости, који суди високима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Један умире у потпуној сили својој, у миру и у срећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Музилице су му пуне млијека, и кости су му влажне од мождина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'А други умире ојађене душе, који није уживао добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Обојица леже у праху, и црви их покривају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Ето, знам ваше мисли и судове, којима ми чините криво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Јер говорите: гдје је кућа силнога, и гдје је шатор у ком наставају безбожници?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Нијесте ли никад питали путника? и што вам казаше нећете да знате,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Да се на дан погибли оставља задац, кад се пусти гњев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Ко ће га укорити у очи за живот његов? и ко ће му вратити што је учинио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Али се износи у гробље и остаје у гомили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Слатке су му груде од долине, и вуче за собом све људе, а онима који га претекоше нема броја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Како ме дакле на празно тјешите кад у одговорима вашим остаје пријевара?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'А Елифас Теманац одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Може ли Богу бити човјек користан? Сам је себи користан човјек мудар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Је ли Свемогућему радост, ако си праведан? или му је добит, ако ходиш без мане?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Хоће ли те карати и ићи на суд с тобом зато што те се боји?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Није ли злоћа твоја велика? и неправдама твојим има ли краја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Јер си узимао залог од браће своје ни за што, и свлачио си хаљине с голијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Уморнога нијеси напојио воде, и гладноме нијеси дао хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Земља је била човјека силнога, и угледни је сједио у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Удовице си отпуштао празне, и мишице сиротама потирао си.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Зато су око тебе замке, и страши те страх изненада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'И мрак је око тебе да не видиш, и поводањ покрива те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Није ли Бог на висини небеској? погледај горе звијезде, како су високо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Али ти кажеш: шта зна Бог? еда ли ће кроз таму судити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Облаци га заклањају, те не види; хода по кругу небеском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Јеси ли запазио стари пут којим су ишли неправедници,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Који се искоријенише прије времена и вода се разли по темељу њихову?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'Говораху Богу: иди од нас. Шта би им учинио Свемогући?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'А он им је напунио куће добра. Али намјера безбожничка далеко је од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Видјеће праведници и радоваће се, и безазлени потсмијеваће им се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Да, још није уништено добро наше, а остатак је њихов прождро огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Сложи се с њим и помири се; тако ће ти бити добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Прими из уста његовијех закон, и сложи ријечи његове у срцу свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Ако се вратиш к Свемогућему, опет ћеш се назидати, ако удаљиш од шатора својих безакоње,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Тада ћеш метати по праху злато и Офирско злато по камењу из потока.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'И Свемогући биће ти злато и сребро и сила твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Јер ћеш се тада радовати о Господу, и подигнућеш к Богу лице своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Молићеш му се, и услишиће те, и завјете своје извршићеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Што год наумиш, излазиће ти; и на путовима твојим свијетлиће видјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Кад други буду понижени, рећи ћеш: да се подигну; и Бог ће избавити онога ко је оборенијех очију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Избавиће и онога који није без кривице; избавиће га чистотом руку твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'А Јов одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Још је тужњава моја одмет? а невоља је моја тежа од уздаха мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'О кад бих знао како бих нашао Бога! да отидем до пријестола његова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Да разложим пред њим парбу своју, и уста своја напуним разлога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Да знам шта би ми одговорио, и разумијем шта би ми рекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Би ли се према великој својој сили прео са мном? Не; него би ми помогао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Ондје би се праведан човјек могао правдати с њим, и ослободио бих се за свагда од свога судије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Гле, ако пођем напријед, нема га; ако ли натраг, не находим га;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Ако налијево ради, не видим га; ако надесно, заклонио се, не могу га видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Али он зна пут мој; кад ме окуша, изаћи ћу као злато.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'По стопама је његовијем ступала нога моја; пута његова држао сам се, и не зађох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Од заповијести уста његовијех нијесам отступао; чувао сам ријечи уста његовијех више него свој ужитак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Али кад он што науми, ко ће га одвратити? што душа његова зажели, оно чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'И извршиће што је наумио за ме; и тога има у њега много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'За то сам се уплашио од њега; и кад то мислим, страх ме је од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Бог је растопио срце моје, Свемогући ме је уплашио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Што не погибох прије мрака? и што не сакри мрак испред мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Зашто Свемогућему нијесу сакривена времена? и који га знају, не виде дана његовијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Међе помичу безбожни, отимају стадо и пасу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Магарца сиротама одгоне; у залогу узимају вола удовици;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Сиромахе одбијају с пута; убоги у земљи крију се сви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Гле, као дивљи магарци у пустињи излазе на посао свој устајући рано на плијен; пустиња је храна њима и дјеци њиховој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Жању њиву и беру виноград који није њихов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Гола нагоне да ноћује без хаљине, који се немају чим покрити по зими,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Окисли од пљуска у гори, немајући заклона, привијају се к стијени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Грабе сироче од дојке и са сиромаха скидају залог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Голога остављају да иде без хаљине, и оне који носе снопове да гладују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Који међу њиховијем зидовима уље циједе и грожђе у кацама газе, подносе жеђ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Људи у граду уздишу, и душе побијенијех вичу, а Бог не укида тога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Они се противе свјетлости, не знајући за путове њезине и не стају на стазама њезинијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Зором устајући крвник убија сиромаха и убога; а ноћу је као лупеж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'И око курварово пази на сумрак говорећи: да ме око не види. И сакрива лице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Прокопавају по мраку куће, које обдан себи забиљеже; не знајући за свјетлост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Јер је зора њима свјема сјен смртни; ако их ко позна, страх их је сјена смртнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Брзи су као поврх воде, проклет је дио њихов на земљи; неће видјети пута виноградскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Као што суша и врућина граби воде шњежне, тако гроб грјешнике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Заборавља их утроба материна, слатки су црвима, не спомињу се више; као дрво скршиће се неправедник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Здружује с њим нероткињу која не рађа, и удовици не чини добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Граби јаке својом силом; остане ли који, не узда се у живот свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Да му Бог у шта ће се поуздати; али очи његове пазе на њихове путе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Узвисе се за мало, па их нема; падају и гину као сви други, и као врх од класа одсијецају се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Није ли тако? ко ће ме утјерати у лаж и обратити у ништа ријечи моје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'А Вилдад Сушанин одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Власт је и страх у њега, чини мир на висинама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Војскама његовијем има ли броја? и кога не обасјава видјело његово?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'И како ће човјек бити праведан пред Богом? и како ће чист бити рођени од жене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Гле, ни мјесец не би сјао, ни звијезде не би биле чисте пред њим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Акамоли човјек, црв, и син човјечји, мољац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'А Јов одговори и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Како си помогао слабоме! како си избавио руку нејаку!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Како си свјетовао онога који је без мудрости и показао разум изобила!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Коме си говорио те ријечи? и чији је дух изашао из тебе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'И мртве ствари створене су под водама и становници њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Откривен је пакао пред њим, нити има покривача погибли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Он је разастро и сјевер над празнином, и земљу објесио ни о чем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Завезује воде у облацима својим, и не продире се облак под њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Држи пријесто свој, разапиње облак свој над њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Међу је поставио око воде докле не буде крај свјетлости и мраку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Ступови небески тресу се и дркћу од пријетње његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Силом је својом поцијепао море и разумом својим разбио бјеснило његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Духом је својим украсио небеса, и рука је његова створила пругу змију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Гле, то су дијелови путова његовијех; али како је мали дио што чусмо о њему? и ко ће разумјети гром силе његове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'И Јов настави бесједу своју и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Тако да је жив Бог, који је одбацио парбу моју, и Свемогући, који је ојадио душу моју,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Док је душа моја у мени, и дух Божји у ноздрвама мојим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Неће усне моје говорити безакоња, нити ће језик мој изрицати пријеваре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Не дао Бог да пристанем да имате право; докле дишем, нећу отступити од своје доброте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Држаћу се правде своје, нити ћу је оставити; неће ме прекорити срце моје докле сам жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Непријатељ мој биће као безбожник, и који устаје на ме, као безаконик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Јер како је надање лицемјеру, кад се лакоми а Бог ће ишчупати душу његову?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Хоће ли Бог услишити вику његову кад на њ дође невоља?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Хоће ли се Свемогућему радовати? хоће ли призивати Бога у свако вријеме?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Учим вас руци Божјој, и како је у Свемогућега не тајим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Ето, ви све видите, зашто дакле једнако говорите залудне ствари?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'То је дио човјеку безбожном од Бога, и нашљедство које примају насилници од Свемогућега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Ако му се множе синови, множе се за мач, и натражје његово неће се наситити хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Који остану иза њега, на смрти ће бити погребени, и удовице њихове неће плакати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Ако накупи сребра као праха, и набави хаљина као блата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Што набави, обући ће праведник, и сребро ће дијелити безазлени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Гради себи кућу као мољац, и као колибу коју начини чувар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Богат ће умријети а неће бити прибран; отвориће очи а ничега неће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Стигнуће га страхоте као воде; ноћу ће га однијети олуја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Узеће га вјетар источни, и отићи ће; вихор ће га однијети с мјеста његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'То ће Бог пустити на њ, и неће га жалити; он ће једнако бјежати од руке његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Други ће пљескати рукама за њим, и звиждаће за њим с мјеста његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Да, сребро има жице, и злато има мјесто гдје се топи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Гвожђе се вади из праха, и из камена се топи мјед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Мраку поставља међу, и све истражује човјек до краја, и камење у тами и у сјену смртном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Ријека навре с мјеста својега да јој нико не може приступити; али се одбије и одлази трудом човјечјим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Из земље излази хљеб, и под њом је друго, као огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'У камену је њезину мјесто сафиру, а ондје је прах златни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Те стазе не зна птица, нити је видје око крагујево;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Не угази је младо звијерје, нити њом прође лав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'На кремен диже руку своју; превраћа горе из дна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Из стијене изводи потоке, и свашта драгоцјено види му око.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Уставља ријеке да не теку, и што је сакривено износи на видјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Али мудрост гдје се налази? и гдје је мјесто разуму?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Не зна јој човјек цијене, нити се находи у земљи живијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Бездана вели: није у мени; и море вели: није код мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Не може се дати чисто злато за њу, нити се сребро измјерити у промјену за њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Не може се цијенити златом Офирским, ни драгим онихом ни сафиром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Не може се изједначити с њом ни злато ни кристал, нити се може промијенити за закладе златне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Од корала и бисера нема спомена, јер је вриједност мудрости већа него драгом камењу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Не може се с њом изједначити топаз Етиопски, нити се може цијенити чистијем златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Откуда дакле долази мудрост? и гдје је мјесто разуму?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Сакривена је од очију свакога живога, и од птица небеских заклоњена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Погибао и смрт говоре: ушима својима чусмо славу њезину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Бог зна пут њезин, и познаје мјесто њезино.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Јер гледа до крајева земаљских и види све што је под свијем небом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Кад даваше вјетру тежину, и мјераше воду мјером,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'Кад постављаше закон дажду и пут муњи громовној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'Још је онда видје и огласи је, уреди је и претражи је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'А човјеку рече: гле, страх је Божји мудрост, и уклањати се ода зла јест разум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Још настави Јов бесједу своју и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'О да бих био као пређашњих мјесеца, као онијех дана кад ме Бог чуваше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Кад свијетљаше свијећом својом над главом мојом, и при видјелу његову хођах по мраку,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Како бијах за младости своје, кад тајна Божија бијаше у шатору мом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Кад још бијаше Свемогући са мном, и дјеца моја око мене,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Кад се траг мој обливаше маслом, и стијена ми точаше уље потоцима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Кад излажах на врата кроз град, и на улици намјештах себи столицу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Младићи видећи ме уклањаху се, а старци устајаху и стајаху,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Кнезови престајаху говорити и метаху руку на уста своја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Управитељи устезаху глас свој и језик им приањаше за грло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Јер које ме ухо чујаше, називаше ме блаженијем; и које ме око виђаше, свједочаше ми');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Да избављам сиромаха који виче, и сироту и који нема никога да му поможе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Благослов онога који пропадаше долажаше на ме, и удовици срце распијевах;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'У правду се облачих и она ми бијаше одијело, као плашт и као вијенац бијаше ми суд мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Око бијах слијепцу и нога хрому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Отац бијах убогима, и разбирах за распру за коју не знах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'И разбијах кутњаке неправеднику, и из зуба му истрзах грабеж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Зато говорах: у својем ћу гнијезду умријети, и биће ми дана као пијеска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Коријен мој пружаше се крај воде, роса биваше по сву ноћ на мојим гранама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Слава моја подмлађиваше се у мене, и лук мој у руци мојој понављаше се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Слушаху ме и чекаху, и мучаху на мој свјет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Послије мојих ријечи нико не проговараше, тако их натапаше бесједа моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Јер ме чекаху као дажд, и уста своја отвараху као на позни дажд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Кад бих се насмијао на њих, не вјероваху, и сјајности лица мојега не разгоњаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Кад бих отишао к њима, сједах у зачеље, и бијах као цар у војсци, кад тјеши жалосне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'А сада смију ми се млађи од мене, којима отаца не бих хтио метнути са псима стада својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'А на што би ми и била сила руку њиховијех? у њима бјеше пропала старост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Од сиромаштва и глади самоћаваху бјежећи од суха, мрачна, пуста и опустошена мјеста;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Који браху лободу по честама, и смреково коријење бјеше им храна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Између људи бијаху изгоњени и викаше се за њима као за лупежем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Живљаху по страшнијем увалама, по јамама у земљи и у камену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'По грмовима рикаху, под трњем се скупљаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Бијаху људи никакви и без имена, мање вриједни него земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'И њима сам сада пјесма, и постах им прича.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Гаде се на ме, иду далеко од мене и не устежу се пљувати ми у лице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Јер је Бог одапео моју тетиву и муке ми задао те збацише узду преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'С десне стране устају момци, поткидају ми ноге, и насипају пут к мени да ме упропасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Раскопаше моју стазу, умножише ми муке, не треба нико да им помаже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Као широким проломом навиру, и наваљују преко развалина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Страхоте навалише на ме, и као вјетар тјерају душу моју, и као облак прође срећа моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'И сада се душа моја разљева у мени, стигоше ме дани мучни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Ноћу пробада ми кости у мени, и жиле моје не одмарају се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Од тешке силе промијенило се одијело моје, и као огрлица у кошуље моје стеже ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Бацио ме је у блато, те сам као прах и пепео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Вичем к теби, а ти ме не слушаш; стојим пред тобом, а ти не гледаш на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Претворио си ми се у љута непријатеља; силом руке своје супротиш ми се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Подижеш ме у вјетар, посађујеш ме на њ, и растапаш у мени све добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Јер знам да ћеш ме одвести на смрт и у дом одређени свјема живима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Али неће пружити руке своје у гроб; кад их стане потирати, они неће викати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Нијесам ли плакао ради онога који бијаше у злу? није ли душа моја жалосна бивала ради убогога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Кад се добру надах, дође ми зло; и кад се надах свјетлости, дође мрак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Утроба је моја узаврела, и не може да се умири, задесише ме дани мучни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Ходим црн, не од сунца, устајем и вичем у збору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Брат постах змајевима и друг совама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Поцрњела је кожа на мени и кости моје посахнуше од жеге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Гусле се моје претворише у запијевку, и свирала моја у плач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Вјеру учиних са очима својим, па како бих погледао на дјевојку?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Јер какав је дио од Бога озго? и како нашљедство од Свемогућега с висине?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Није ли погибао неваљаломе и чудо онима који чине безакоње?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Не виде ли он путове моје, и све кораке моје не броји ли?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Ако ходих с лажју или ако похитје нога моја на пријевару,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Нека ме измјери на мјерилима правијем, и нека Бог позна доброту моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Ако су кораци моји зашли с пута, и ако је за очима мојим пошло срце моје, и за руке моје прионуло штогод,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Нека ја сијем а други једе, и нека се искоријене изданци моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Ако се занијело срце моје за којом женом, и ако сам вребао на вратима ближњега својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Нека другому меље жена моја, и нека се други над њом повијају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Јер је то грдило и безакоње за судије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Јер би то био огањ који би прождирао до уништења, и сву би моју љетину искоријенио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Ако нијесам хтио доћи на суд са слугом својим или са слушкињом својом, кад би се тужили на мене;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'Јер шта бих чинио кад би се Бог подигао, и кад би потражио, шта бих му одговорио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Који је мене створио у утроби, није ли створио и њега? није ли нас он исти саздао у материци?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Ако сам одбио сиромасима жељу њихову, и очи удовици замутио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'И ако сам залогај свој сам јео а није га јела и сирота,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'Јер је од младости моје расла са мном као код оца, и од утробе матере своје водао сам је;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Ако сам гледао кога гдје гине немајући хаљине, и сиромаха гдје се нема чим покрити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Ако ме нијесу благосиљала бедра његова што се руном оваца мојих утоплио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Ако сам измахнуо руком на сироту, кад видјех на вратима помоћ своју,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Нека ми испадне раме из плећа, и рука моја нека се откине из зглоба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Јер сам се бојао погибли од Бога, којега величанству не бих одолио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Ако сам полагао на злато надање своје, или чистому злату говорио: узданицо моја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Ако сам се веселио што ми је имање велико и што много стиче рука моја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Ако сам гледао на сунце, кад сјаје, и на мјесец, кад поносито ходи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'И срце се моје потајно преварило и руку моју пољубила уста моја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'И то би било безакоње за судије, јер бих се одрекао Бога озго;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Ако сам се радовао несрећи ненавидника својега, и ако сам заиграо када га је зло задесило,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'Јер не дадох језику својему да гријеши тражећи душу његову с проклињањем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Ако не говораху домашњи моји: ко би нам дао меса његова? не можемо се ни најести;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Странац није ноћивао на пољу; врата своја отворао сам путнику;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Ако сам као што чине људи тајио пријеступе своје и крио своје безакоње у својим њедрима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'Ако сам и могао плашити велико мноштво, ипак од најмањега у дому бијаше ме страх; зато мучах и не одлажах од врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'О да бих имао кога да ме саслуша! Гле, жеља је моја да ми Свемогући одговори и супарник мој да ми напише књигу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Носио бих је на рамену свом, везао бих је себи као вијенац,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Број корака својих казао бих му, као кнез приступио бих к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Ако је на ме викала моја земља, и бразде њезине плакале,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Ако сам јео рода њезина без новаца и досађивао души господара њезинијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Мјесто пшенице нека ми рађа трње, и мјесто јечма кукољ. Свршише се ријечи Јовове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Тада престаше она три човјека одговарати Јову, јер се чињаше да је праведан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'А Елијуј си Варахилов од Вуза, рода Рамова, разгњеви се на Јова што се сам грађаше праведнији од Бога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'И на три пријатеља његова разгњеви се што не нађоше одговора и опет осуђиваху Јова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Јер Елијуј чекаше докле они говораху с Јовом, јер бијаху старији од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Па кад видје Елијуј да нема одговора у устима она три човјека, распали се гњев његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'И проговори Елијуј син Варахилов од Вуза, и рече: ја сам најмлађи, а ви сте старци, зато се бојах и не смијах вам казати што мислим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Мишљах: нека говори старост, и многе године нека објаве мудрост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Али је дух у људима, и дух Свемогућега уразумљује их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Велики нијесу свагда мудри, и старци не знају свагда шта је право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Зато велим: послушај ме да кажем и ја како мислим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Ето, чекао сам да ви изговорите, слушао сам разлоге ваше докле извиђасте бесједу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Пазио сам, али гле, ниједан од вас не сапре Јова, не одговори на његове ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Може бити да ћете рећи: нађосмо мудрост, Бог ће га оборити, не човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Није на ме управио бесједе, ни ја му нећу одговарати вашим ријечима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Смели су се, не одговарају више, нестало им је ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Чекао сам, али не говоре, стадоше, и више не одговарају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Одговорићу и ја за се, казаћу и ја како мислим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Јер сам пун ријечи, тијесно је духу у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Гле, трбух је мој као вино без одушке, и распукао би се као нов мијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Говорићу да одахнем, отворићу усне своје, и одговорићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Нећу гледати ко је ко, и човјеку ћу говорити без ласкања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Јер не умијем ласкати; одмах би ме узео Творац мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Чуј дакле, Јове, бесједу моју, и слушај све ријечи моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Ево, сад отварам уста своја; говори језик мој у устима мојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'По правом срцу мом биће ријечи моје, и мисао чисту изрећи ће усне моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Дух Божји створио ме је, и дах Свемогућега дао ми је живот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Ако можеш, одговори ми, приправи се и стани ми насупрот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Ево, ја ћу бити мјесто Бога, као што си рекао; од кала сам начињен и ја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Ето, страх мој неће те страшити, и рука моја неће те тиштати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Рекао си дакле преда мном, и чуо сам глас твојих ријечи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Чист сам, без гријеха, прав сам и нема безакоња на мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Ево, тражи задјевицу са мном, држи ме за свога непријатеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Меће у кладе ноге моје, вреба по свијем стазама мојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Ето, у том нијеси праведан, одговарам ти; јер је Бог већи од човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Зашто се преш с њим, што за сва дјела своја не одговара?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Једанпут говори Бог и два пута; али човјек не пази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'У сну, у утвари ноћној, кад тврд сан падне на људе, кад спавају у постељи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Тада отвора ухо људима и науку им запечаћава,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'Да би одвратио човјека од дјела његова, и заклонио од њега охолост;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Да би сачувао душу његову од јаме, и живот његов да не наиђе на мач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'И кара га боловима на постељи његовој, и све кости његове тешком болешћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Тако да се животу његову гади хљеб и души његовој јело најмилије;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Нестаје тијела његова на очиглед, и измалају се кости његове, које се прије нијесу видјеле,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'И душа се његова приближава гробу, и живот његов смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Ако има гласника, тумача, једнога од тисуће, који би казао човјеку дужност његову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Тада ће се смиловати на њ, и рећи ће: избави га да не отиде у гроб; нашао сам откуп.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'И подмладиће се тијело његово као у дјетета, и повратиће се на дане младости своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Молиће се Богу, и помиловаће га, и гледаће лице његово радујући се, и вратиће човјеку по правди његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Гледајући људи рећи ће: бијах згријешио, и што је право изврнуо, али ми не поможе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Он избави душу моју да не отиде у јаму, и живот мој да гледа свјетлост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Гле, све ово чини Бог два пута и три пута човјеку,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'Да би повратио душу његову од јаме, да би га обасјавала свјетлост живијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Пази, Јове, слушај ме, мучи, да ја говорим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Ако имаш што рећи, одговори ми; говори, јер сам те рад оправдати;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Ако ли не, слушај ти мене; мучи, и научићу те мудрости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Још говори Елијуј и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Чујте, мудри, бесједу моју, и разумни послушајте ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Јер ухо познаје бесједу као што грло куша јело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Разберимо што је право, извидимо међу собом што је добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Јер Јов рече: праведан сам, а Бог одбаци моју правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Хоћу ли лагати за своју правду? стријела је моја смртна, а без кривице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Који је човјек као Јов да као воду пије потсмијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'И да се дружи с онима који чине безакоње, и да ходи с безбожнијем људима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Јер рече: не помаже човјеку да угађа Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Зато, људи разумни, послушајте ме; далеко је од Бога злоћа и неправда од Свемогућега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Јер по дјелу плаћа човјеку и даје свакоме да нађе према путу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Доиста Бог не ради зло и Свемогући не изврће правде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Ко му је предао земљу? и ко је уредио васиљену?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Кад би на њ окренуо срце своје, узео би к себи дух његов и дихање његово;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Изгинуло би свако тијело, и човјек би се повратио у прах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Ако си дакле разуман, чуј ово: слушај глас ријечи мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Може ли владати онај који мрзи на правду? хоћеш ли осудити онога који је најправеднији?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Каже ли се цару: ниткове! и кнезовима: безбожници?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Акамоли оному који не гледа кнезовима ко су, нити у њега вриједи више богати од сиромаха, јер су сви дјело руку његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Умиру зачас, и у по ноћи усколеба се народ и пропадне, и однесе се јаки без руке људске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Јер су очи његове обраћене на путове човјечије и види све кораке његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Нема мрака ни сјена смртнога гдје би се сакрили који чине безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Јер никоме не одгађа кад дође да се суди с Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Сатире јаке недокучљиво, и поставља друге на њихово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Јер зна дјела њихова, и док обрати ноћ, сатру се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Као безбожне разбија их на видику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Јер отступише од њега и не гледаше ни на које путове његове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Те дође до њега вика сиромахова, и чу вику невољнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Кад он умири, ко ће узнемирити? и кад он сакрије лице, ко ће га видјети? и то бива и народу и човјеку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Да не би царовао лицемјер, да не би било замке народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Заиста, треба казати Богу: подносио сам, нећу више гријешити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'А што не видим, ти ме научи; ако сам чинио неправду, нећу више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Еда ли ће по теби плаћати, јер теби није по вољи, јер ти бираш а не он? Ако знаш што, говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Људи ће разумни са мном казати, и мудар ће човјек пристати,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Да Јов не говори разумно, и да ријечи његове нијесу мудре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Оче мој, нека се Јов искуша до краја, што одговара као зли људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Јер домеће на гријех свој безакоње, пљеска рукама међу нама, и много говори на Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Још говори Елијуј и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Мислиш ли да си право рекао: моја је правда већа од Божије?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Јер си рекао: шта ће ми помоћи, кака ће ми бити корист, да не гријешим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Ја ћу одговорити теби и друговима твојим с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Погледај небо, и види; погледај облаке, како су виши од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Ако гријешиш, шта ћеш му учинити? или ако се умноже безакоња твоја, шта ћеш му наудити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Ако си праведан, шта ћеш му дати? или шта ће примити из руке твоје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Човјеку какав си може наудити твоја злоћа, и сину човјечијему помоћи твоја правда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Вапију од великога насиља којима се чини, и вичу на руку силнијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'А ниједан не говори: гдје је Бог, Створитељ мој, који даје пјесму ноћу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'Који чини те смо разумнији од звијерја земаљскога, и мудрији од птица небеских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Тамо вичу с охолости злијех људи, али не бивају услишени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Јер Бог не слуша таштине, и Свемогући не гледа на њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Акамоли кад кажеш: не видиш то. Пред њим је суд; чекај га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'А сада чим те гњев походи, није ништа, нити је гледао на све што си учинио;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Зато Јов на празно отвора уста своја, и безумно умножава ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Још говори Елијуј и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Потрпи ме мало, и показаћу ти, јер још има што бих говорио за Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Почећу из далека бесједу своју, и показаћу да је Творац мој праведан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Доиста, неће бити лажне ријечи моје, код тебе је који право мисли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Гле, Бог је силан, али никога не одбацује, силан је снагом срчаном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Не да живјети безбожнику, а невољницима чини правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Не одвраћа од праведника очију својих, него још с царевима на пријесто посађује их навијек, те се узвишују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Ако ли су оковани у пута и свезани ужима невољничким,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Тада им напомиње дјела њихова и безакоња њихова како су силна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'И отвора му ухо да би се поправили, и говори им да се врате од безакоња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Ако послушају и стану им служити, довршују дане своје у добру и године своје у радости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Ако ли не послушају, гину од мача и умиру с безумља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'А који су лицемјерна срца, навлаче гњев и не вичу кад их повеже;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Умире у младости душа њихова и живот њихов међу курвама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Избавља невољника из невоље његове и отвора му ухо у муци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Тако би и тебе извео из тјескобе на пространо мјесто, гдје ништа не досађује, и мирни сто твој био би пун претилине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Али си заслужио суд безбожнички; и суд и правда снађе те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Доиста, гњев је на теби; гледај да те не одбаци у карању, те те велики откуп неће избавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Хоће ли гледати на твоје богатство? неће ни на злато ни на каку силу блага твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Не уздиши за ноћу у коју народи одлазе на своје мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Чувај се да не погледаш на таштину и волиш на њу него невољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Гле, Бог је највиши својом силом, ко је учитељ као он?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Ко му је одредио пут његов? или ко ће му рећи: чиниш неправо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Опомињи се да величаш дјела његова, која гледају људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Сви људи виде их, сваки их гледа издалека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Гле, Бог је велик, и не можемо га познати, број година његовијех не може се докучити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Јер он стеже капље водене, које лију дажд из облака његовијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Кад теку облаци, капљу на мноштво људско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'И ко би разумио простор облацима и грмљаву у шатору његову?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Како простире над њим свјетлост своју, и дубине морске покрива?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Тијем суди народима, даје хране изобила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Рукама заклања свјетлост, и наређује кога да срете,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Јављајући према њему добру вољу своју, и према стоци и према роду земаљском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'И од тога дркће срце моје, и отскаче са својега мјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Слушајте добро громовни глас његов и говор што излази из уста његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Под сва небеса пушта га, и свјетлост своју до крајева земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'За њом риче гром, грми гласом величанства својега, нити што одгађа кад се чује глас његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Дивно Бог грми гласом својим, чини ствари велике, да их не можемо разумјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Говори снијегу: падни на земљу; и дажду ситноме и дажду силноме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Запечаћава руку сваком човјеку, да позна све посленике своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Тада звијер улази у јаму, и остаје на својој ложи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'С југа долази олуја, и са сјевера зима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Од дихања Божијега постаје лед, и широке воде стискају се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'И да се натапа земља, натјерује облак, и расипа облак свјетлошћу својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'И он се обрће и тамо и амо по вољи његовој да чини све што му заповједи по васиљеној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Чини да се нађе или за кар или за земљу или за доброчинство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Чуј то, Јове, стани и гледај чудеса Божија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Знаш ли како их он уређује и како сија свјетлошћу из облака својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Знаш ли како висе облаци? Знаш ли чудеса онога који је савршен у сваком знању?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Како ти се хаљине угрију кад умири земљу с југа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Јеси ли ти с њим разапињао небеса, која стоје тврдо као саливено огледало?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Научи нас шта ћемо му рећи; не можемо од таме говорити по реду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Хоће ли му ко приповједити што бих ја говорио? Ако ли би ко говорио, заиста, био бих прождрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Али сада не могу људи гледати у свјетлост кад сјаји на небу, пошто вјетар прође и очисти га;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Са сјевера долази као злато; али је у Богу страшнија слава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Свемогућ је, не можемо га стигнути; велике је силе, али судом и великом правдом никога не мучи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Зато га се боје људи: не може га видјети никакав мудрац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Тада одговори Господ Јову из вихора и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Ко је то што замрачује савјет ријечима неразумно?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Опаши се сада као човјек; ја ћу те питати, а ти ми казуј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Гдје си ти био кад ја оснивах земљу? кажи, ако си разуман.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Ко јој је одредио мјере? знаш ли? или ко је растегао уже преко ње?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'На чем су подножја њезина углављена? или ко јој је метнуо камен угаони?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Кад пјеваху заједно звијезде јутарње и сви синови Божји кликоваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Или ко је затворио море вратима кад као из утробе изиде?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Кад га одјех облаком и пових тамом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Кад поставих за њ уредбу своју и метнух му пријеворнице и врата;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'И рекох: довде ћеш долазити, а даље нећеш, и ту ће се устављати поносити валови твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Јеси ли свога вијека заповједио јутру, показао зори мјесто њезино,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Да се ухвати земљи за крајеве, и да се растјерају с ње безбожници,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Да се она промијени као блато печатно, а они да стоје као хаљина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'Да се одузме безбожницима свјетлост њихова и рука подигнута да се сломи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Јеси ли долазио до дубина морских? и по дну пропасти јеси ли ходио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Јесу ли ти се отворила врата смртна, и врата сјена смртнога јеси ли видио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Јеси ли сагледао ширину земаљску? кажи, ако знаш све то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Који је пут к стану свјетлости? и гдје је мјесто тами,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Да би је узео и одвео до међе њезине, и знао стазе к дому њезину?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Знаш ти; јер си се онда родио, и број је дана твојих велик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Јеси ли улазио у ризнице шњежне? или ризнице градне јеси ли видио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'Које чувам за вријеме невоље, за дан боја и рата?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Којим се путем дијели свјетлост и устока се разилази по земљи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Ко је раздијелио јазове поводњу и пут свјетлици громовној?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Да би ишао дажд на земљу гдје нема никога, и на пустињу гдје нема човјека,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Да напоји пуста и неродна мјеста, и учини да расте трава зелена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Има ли дажд оца? или ко је родио капље росне?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Из чије је утробе изашао лед, и ко је родио слану небеску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Да се воде скривају и постају као камен и крајеви пропасти срастају?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Можеш ли свезати милине влашићима? или свезу штапима раздријешити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Можеш ли извести јужне звијезде на вријеме? Или кола са звијездама њиховијем хоћеш ли водити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Знаш ли ред небески? можеш ли ти уређивати владу његову на земљи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Можеш ли дигнути глас свој до облака да би те мноштво воде покрило?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Можеш ли пустити муње да иду, и да ти реку: ево нас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Ко је метнуо човјеку у срце мудрост? или ко је дао души разум?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Ко ће избројити облаке мудрошћу, и мјехове небеске ко ће излити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'Да се расквашен прах згусне и груде се слијепе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Ловиш ли ти лаву лов? и лавићима трбух пуниш,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Кад леже у пећинама и вребају у заклону свом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Ко готови гаврану храну његову кад птићи његови вичу к Богу и лутају немајући шта јести?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Знаш ли вријеме кад се дивокозе козе? и јеси ли видио кад се кошуте легу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Јеси ли избројио мјесеце, докле носе? знаш ли вријеме кад се легу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'Како се савијају, млад своју испуштају, и опраштају се болова?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Како јача млад њихова, расте по пољу и отишавши не враћа се к њима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Ко је пустио дивљега магарца да је слободан, и ремене дивљему магарцу ко је раздријешио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Којему одредих пустињу за кућу и за стан слатину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Он се смије вреви градској, и не слуша вике настојникове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Шта налази у горама, оно му је пића, и тражи сваку зелен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Би ли ти једнорог хтио служити? би ли ноћивао за јаслама твојим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Можеш ли везати ужем једнорога да оре? хоће ли влачити бразде за тобом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Хоћеш ли се ослонити на њ што му је снага велика? и оставити на њему свој посао?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Хоћеш ли се поуздати у њ да ће ти свести љетину и на гумно твоје сложити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Јеси ли ти дао пауну лијепа крила и перје чапљи или ноју?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Који снесе на земљи јајца своја, и остави их да их прах грије?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'И не мисли да ће их нога разбити и звијер пољска згазити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Немилостив је птићима својим као да нијесу његови, и да му труд не буде узалуд не боји се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Јер му Бог није дао мудрост нити му је удијелио разума.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Кад се подигне у вис, смије се коњу и коњику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Јеси ли ти дао коњу јачину? јеси ли ти окитио врат његов рзањем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Хоћеш ли га поплашити као скакавца? фркање ноздрва његовијех страшно је;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Копа земљу, весео је од силе, иде на сусрет оружју;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Смије се страху и не плаши се нити узмиче испред мача;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Кад звекће над њим тул и сијева копље и сулица;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Од немирноће и љутине копа земљу, и не може да стоји кад труба затруби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Кад труба затруби, он вришти, издалека чује бој, вику војвода и поклич.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Еда ли по твојему разуму лети јастријеб? шири крила своја на југ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Еда ли се на твоју заповијест диже у вис орао, и на висини вије гнијездо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 31, 'На стијени станује и бави се, на врх стијене, на тврду мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 32, 'Одатле гледа хране, далеко му виде очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 33, 'И птићи његови пију крв, и гдје су мртва тјелеса ондје је он.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 34, 'И тако одговарајући Господ Јову рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 35, 'Ко се препире с Богом, хоће ли га учити? који куди Бога, нека одговори на то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 36, 'Тада Јов одговори Господу и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 37, 'Гле, ја сам мален, шта бих ти одговорио? Мећем руку своју на уста своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 38, 'Једном говорих, али нећу одговарати; и другом, али нећу више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'А Господ опет одговарајући Јову из вихора рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Опаши се сада као човјек; ја ћу те питати, а ти ми казуј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Хоћеш ли ти уништити мој суд? хоћеш ли мене осудити да би себе оправдао?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Је ли у тебе мишица као у Бога? грмиш ли гласом као он?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Окити се сада чашћу и величанством, у славу и красоту обуци се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Проспи јарост гњева својега, и погледај све поносите, и обори их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Погледај све поносите, и понизи их, и потри безбожнике на мјесту њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Затрпај их све у прах, и повежи им лице на скривену мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Тада ћу те и ја хвалити да те чува десница твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'А гле, слон, којега сам створио с тобом, једе траву као во;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Гле, снага му је у бедрима његовијем, и сила му је у пупку трбуха његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Диже реп свој као кедар, жиле од јаја његовијех сплетене су као гране;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Кости су му као цијеви мједене, зглавци као полуге гвоздене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Он је прво између дјела Божијих, творац његов дао му је мач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Горе носе му пићу, и све звијерје пољско игра се ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'У хладу лијеже, у густој трсци и глибу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Граната дрвета заклањају га сјеном својим, и опкољавају га врбе на потоцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Гле, уставља ријеку да не тече, узда се да ће испити Јордан губицом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Хоће ли га ко ухватити на очи његове? замку му провући кроз нос?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Хоћеш ли удицом извући крокодила или ужем подвезати му језик?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Хоћеш ли му провући ситу кроз нос? или му шиљком провртјети чељусти?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Хоће ли те много молити, или ће ти ласкати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Хоће ли учинити вјеру с тобом да га узмеш да ти буде слуга довијека?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Хоћеш ли се играти с њим као са птицом, или ћеш га везати дјевојкама својим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 25, 'Хоће ли се њим частити другови? раздијелити га међу трговце?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 26, 'Хоћеш ли му напунити кожу шиљцима и главу оствама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 27, 'Дигни на њ руку своју; нећеш више помињати боја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 28, 'Гле, залуду је надати му се; кад га само угледа човјек, не пада ли?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Нема слободна који би га пробудио; а ко ће стати преда ме?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Ко ми је прије дао што, да му вратим? што је год под свијем небом, моје је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Нећу мучати о удима његовијем ни о сили ни о љепоти стаса његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Ко ће му узгрнути горњу одјећу? к чељустима његовијем ко ће приступити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Врата од грла његова ко ће отворити? страх је око зуба његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Крљушти су му јаки штитови спојени тврдо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Близу су једна до друге да ни вјетар не улази међу њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Једна је за другу прионула, држе се и не растављају се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Кад киха као да муња сијева, а очи су му као трепавице у зоре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Из уста му излазе лучеви, и искре огњене скачу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Из ноздрва му излази дим као из врелога лонца или котла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Дах његов распаљује угљевље и пламен му излази из уста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'У врату му стоји сила, и пред њим иде страх.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Уди меса његова спојени су, једноставно је на њему, не размиче се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Срце му је тврдо као камен, тврдо као доњи жрвањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Кад се дигне, дршћу јунаци, и од страха очишћају се од гријеха својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Да га удари мач, не може се одржати, ни копље ни стријела ни оклоп.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Њему је гвожђе као пљева, а мјед као труло дрво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Неће га потјерати стријела, камење из праће њему је као сламка;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Као слама су му убојне справе, и смије се баченом копљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Под њим су оштри црепови, стере себи оштре ствари у глибу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Чини, те ври дубина као лонац, и море се мути као у ступи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'За собом оставља свијетлу стазу, рекао би да је бездана осиједјела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Ништа нема на земљи да би се испоредило с њим, да би створено било да се ничега не боји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Што је год високо презире, цар је над свијем звијерјем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Тада Јов одговори Господу и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Знам да све можеш, и да се не може смести што наумиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Ко је то што замрачује савјет неразумно? Зато кажем да нијесам разумијевао; чудесно је то за ме, те не могу знати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Слушај кад узговорим, и кад запитам, кажи ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Ушима слушах о теби, а сада те око моје види.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Зато поричем, и кајем се у праху и пепелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'А кад Господ изговори оне ријечи Јову, рече Господ Елифасу Теманцу: распалио се гњев мој на тебе и на два пријатеља твоја што не говористе о мени право као слуга мој Јов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Зато сада узмите седам телаца и седам овнова, и идите к слузи мојему Јову и принесите жртве паљенице за се, и слуга мој Јов нека се помоли за вас, јер ћу доиста погледати на њ да не учиним с вама по вашој лудости, јер не говористе о мени право као слуга мој Јов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'И тако отиде Елифас Теманац и Вилдад Сушанин и Софар Намаћанин, и учинише како им заповједи Господ. И погледа Господ на Јова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'И Господ поврати што бјеше узето Јову пошто се помоли за пријатеље своје; и умножи Господ Јову двојином све што бјеше имао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'И дођоше к њему сва браћа његова и све сестре његове и сви пређашњи знанци његови, и једоше с њим у његовој кући и жалећи га тјешише га за све зло што бјеше Господ пустио на њ, и дадоше му сваки по новац и по гривну златну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'И Господ благослови пошљедак Јовов више него почетак, те имаше четрнаест тисућа оваца и шест тисућа камила и тисућу јармова волова и тисућу магарица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'И имаше седам синова и три кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'И првој надје име Јемима, а другој Кесија а трећој Керен-апуха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'И не нахођаше се у свој земљи тако лијепијех дјевојака као кћери Јовове, и отац им даде нашљедство међу браћом њиховом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'И послије поживје Јов сто и четрдесет година, и видје синове и унуке до четвртога кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'И умрије Јов стар и сит живота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Благо човјеку који не иде на вијеће безбожничко, и на путу грјешничком не стоји, и у друштву неваљалијех људи не сједи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Него му је омилио закон Господњи и о закону његову мисли дан и ноћ!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Он је као дрво усађено крај потока, које род свој доноси у своје вријеме, и којему лист не вене: што год ради, у свему напредује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Нијесу таки безбожници, него су као прах који расипа вјетар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Зато се неће безбожници одржати на суду, ни грјешници на збору праведничком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Јер Господ зна пут праведнички; а пут безбожнички пропашће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Зашто се буне народи и племена помишљају залудне ствари?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Устају цареви земаљски, и кнезови се скупљају на Господа и на помазаника његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '\"Раскинимо свезе њихове и збацимо са себе јарам њихов.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Онај, што живи на небесима, смије се, Господ им се потсмијева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Па им говори у гњеву својем и јарошћу својом збуњује их:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '\"Ја сам помазао цара својега на Сиону, на светој гори својој.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Казаћу наредбу Господњу; он рече мени: \"ти си син мој, ја те сад родих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Ишти у мене, и даћу ти народе у нашљедство, и крајеве земаљске теби у државу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Ударићеш их гвозденом палицом; разбићеш их као лончарски суд.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Сад цареви, оразумите се; научите се судије земаљске!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Служите Господу са страхом, и радујте се с трепетом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Поштујте сина, да се не разгњеви, и ви не изгинете на путу своме; јер ће се гњев његов брзо разгорјети. Благо свјема који се у њ уздају!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Господе! како је много непријатеља мојих! Многи устају на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Многи говоре за душу моју: нема му помоћи од Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Али ти си, Господе, штит који ме заклања, слава моја; ти подижеш главу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Гласом својим вичем ка Господу, и чује ме са свете горе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Ја лијежем, спавам и устајем, јер ме Господ чува.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Не бојим се много тисућа народа што са свијех страна наваљује на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Устани, Господе! помози ми, Боже мој! јер ти удараш по образу све непријатеље моје; разбијаш зубе безбожницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Од Господа је спасење; нека буде на народу твом благослов твој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 9, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Кад те зовем, чуј ме, Боже, правдо моја! у тјескоби дај ми простор; смилуј се на ме и услиши молитву моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Синови човјечији! докле ће слава моја бити у срамоти? докле ћете љубити ништавило и тражити лажи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Знајте да Господ дивно чува светога својега; Господ чује кад га зовем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Гњевећи се не гријешите; размислите у срцима својим на постељама својим, и утолите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Принесите жртву за правду, и уздајте се у Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Многи говоре: ко ће нам показати што је добро? Обрати к нама, Господе, свијетло лице своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'А мени си дао у срце радост већу него што је они имају, кад им роди пшеница и вино.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Ја мирно лијежем и спавам; јер ти, Господе, сам дајеш ми те сам без страха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 9, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Чуј, Господе, ријечи моје, разумиј помисли моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Слушај вику моју, царе мој и Боже мој! јер се теби молим, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Ујутру слушаш глас мој, ујутру стојим пред тобом, и чекам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Јер си ти Бог који неће безакоња; у тебе нема мјеста ко је зао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Безбожници неће изаћи пред очи твоје; ти ненавидиш све који чине безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Потиреш лажљивце; на крвопиоце и лукаве мрзи Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'А ја по великој милости твојој улазим у дом твој, и клањам се у светој цркви твојој са страхом твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Господе! води ме у правди својој; ради непријатеља мојих поравни преда мном пут свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Јер нема у устима њиховијем истине; у њима је неваљалство; грло им је гроб отворен; на језику им је дволичење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Боже! не дај им напретка, нека се разбију помисли њихове. За многа неваљалства њихова обори их, јер се побунише на тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Па ће се радовати сви који се у те уздају; довијека ће се веселити које ти заклањаш; дичиће се који љубе име твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Јер ти, Господе, благосиљаш праведника, као штитом заклањаш га милошћу својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 13, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Господе! немој ме покарати у јарости својој, нити ме у гњеву својем наказати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Смилуј се на ме, Господе, јер сам изнемогао; исцијели ме, јер су кости моје устрептале,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'И душа се моја врло уздрхтала. А ти, Господе, докле ћеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Обрати се, Господе, избави душу моју, помози ми ради милости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Јер мртве не спомињу тебе; у гробу ко ће те славити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Изнемогох уздишући; сваку ноћ квасим одар свој, сузама својим натапам постељу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Усахну од жалости око моје, постара се од множине непријатеља мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Идите од мене сви који чините безакоње, јер Господ чу плач мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Чу Господ молбу моју, Господ молитву моју прими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Нек се постиде и препадну сви непријатељи моји, нека се поврате и постиде одмах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 11, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Господе, Боже мој! у тебе се уздам, сачувај ме од свијех који ме гоне, и избави ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Да ми непријатељ не ишчупа душе као лав. Чупа, а нема ко да избави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Господе, Боже мој! ако сам то учинио, ако је неправда у рукама мојима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Ако сам зло вратио пријатељу својему, или криво учинио онима који на ме на правди нападаху;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Нека гони непријатељ душу моју, и нека је стигне, и погази на земљу живот мој и славу моју у прах обрати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Устани, Господе, у гњеву својем; дигни се на жестину непријатеља мојих; пробуди се мени на помоћ, и отвори суд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'И људство ће се слећи око тебе; изнад њега изађи у висину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Господ суди народима. Суди ми, Господе, по правди мојој, и по безазлености мојој нека ми буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Нек се прекине злоћа безбожника, а праведника потпомози, јер ти испитујеш срца и утробе, Боже праведни!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Штит је мени у Бога, који чува оне који су права срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Бог је праведан судија, и Бог је сваки дан готов на гњев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Ако се неће безбожник да обрати, он оштри мач свој, натеже лук свој, и наперује га;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'И запиње смртну стријелу, чини стријеле своје да пале.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Гле, безбожник заче неправду, трудан бијаше злочинством, и роди себи пријевару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Копа јаму и ископа, и паде у јаму коју је начинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Злоба његова обрати се на његову главу, и злочинство његово паде на тјеме његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Хвалим Господа за правду његову, и пјевам имену Господа вишњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 18, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Господе, Господе наш! како је величанствено име твоје по свој земљи! Подигао си славу своју више небеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'У устима мале дјеце и која сисају чиниш себи хвалу насупрот непријатељима својим, да би учинио да замукне непријатељ и немирник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Кад погледам небеса твоја, дјело прста твојих, мјесец и звијезде, које си ти поставио;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Шта је човјек, те га се опомињеш, или син човјечји, те га полазиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Учинио си га мало мањега од анђела, славом и чашћу вјенчао си га;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Поставио си га господаром над дјелима руку својих, све си метнуо под ноге његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Овце и волове све, и дивље звјериње,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Птице небеске и рибе морске, што год иде морским путовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Господе, Господе наш! како је величанствено име твоје по свој земљи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 10, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Хвалим те, Господе, из свега срца својега, казујем сва чудеса твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Радујем се и веселим се о теби, пјевам имену твојему, вишњи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Непријатељи се моји вратише натраг, спотакоше се и неста их испред лица твојега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Јер си свршио суд мој и одбранио ме; сио си на пријесто, судија праведни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Расрдио си се на народе и убио безбожника, име си им затро довијека, засвагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Непријатељу неста мачева сасвијем; градове ти си развалио; погибе спомен њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Али Господ увијек живи; спремио је за суд пријесто свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Он ће судити васиономе свијету по правди, усудиће народима право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Господ је уточиште убогоме, уточиште у невољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'У тебе се уздају који знају име твоје, јер не остављаш онијех који те траже, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Појте Господу, који живи на Сиону; казујте народу дјела његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Јер он освећује крв, памти је; не заборавља јаука невољнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Смилуј се на ме, Господе; погледај како страдам од непријатеља својих, ти, који ме подижеш од врата смртнијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Да бих казивао све хвале твоје на вратима кћери Сионове, и славио спасење твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Попадоше народи у јаму, коју су ископали; у замку, коју су сами намјестили, ухвати се нога њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Познаше Господа; он је судио; у дјела руку својих заплете се безбожник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Вратиће се у пакао безбожници, сви народи који заборављају Бога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Јер неће свагда бити заборављен убоги, и нада невољницима неће нигда погинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Устани, Господе, да се не посили човјек, и да приме народи суд пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Пусти, Господе, страх на њих; нека познаду народи да су људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 21, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Зашто, Господе, стојиш далеко, кријеш се кад је невоља?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'С охолости безбожникове муче се убоги; хватају се убоги пријеваром коју измишљају безбожници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Јер се безбожник дичи жељом душе своје, грабљивица похваљује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Безбожник у обијести својој не мари за Господа: \"он не види.\" Нема Бога у мислима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Свагда су путови његови криви; за судове твоје не зна; на непријатеље своје неће ни да гледа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'У срцу својем вели: нећу посрнути; зло неће доћи нигда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Уста су му пуна неваљалијех ријечи, пријеваре и увреде, под језиком је његовијем мука и погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Сједи у засједи иза куће; у потаји убија правога; очи његове вребају убогога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Сједи у потаји као лав у пећини; сједи у засједи да ухвати убогога; хвата убогога увукавши мрежу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Притаји се, прилегне, и убоги падају у јаке нокте његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Каже у срцу своме: \"Бог је заборавио, окренуо је лице своје, неће видјети нигда.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Устани Господе! дигни руку своју, не заборави невољнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Зашто безбожник да не мари за Бога говорећи у срцу свом да ти нећеш видјети?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Ти видиш; јер гледаш увреде и муке и пишеш их на руци. Теби предаје себе убоги; сироти ти си помоћник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Сатри мишицу безбожноме и зломе, да се тражи и не нађе безбожност његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Господ је цар свагда, довијека, нестаће незнабожаца са земље његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Господе! ти чујеш жеље ништих; утврди срце њихово; отвори ухо своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Да даш суд сироти и невољнику, да престану гонити човјека са земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'У Господа се уздам; зашто говорите души мојој: \"лети у гору као птица;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Јер ево грјешници натегоше лук, запеше стријелу своју за тетиву, да из мрака стријељају праве срцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Кад су раскопани темељи, шта ће чинити праведник?\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Господ је у светом двору свом, пријесто је Господњи на небесима; очи његове гледају; вјеђе његове испитују синове човјечије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Господ испитује праведнога; а безбожнога и којему је мило чинити зло ненавиди душа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Пустиће на безбожнике дажд од живога угљевља, огња и сумпора; и огњени вјетар биће им дио из чаше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Јер је Господ праведан, љуби правду; лице ће његово видјети праведници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Помагај, Господе; јер неста светијех, јер је мало вјернијех међу синовима човјечијим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Лаж говоре један другоме,уснама лажљивијем говоре из срца дволична.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Истријебиће Господ сва уста лажљива, језик величави,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Људе, који говоре: језиком смо јаки, уста су наша у нас, ко је господар над нама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Видећи страдање невољних и уздисање ништих, сад ћу устати, вели Господ, и избавити онога коме злобе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Ријечи су Господње ријечи чисте, сребро у ватри очишћено од земље, седам пута претопљено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Ти ћеш нас, Господе, одбранити, и сачувати нас од рода овога довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Безбожници иду наоколо; кад се они подижу, срамоте се синови човјечији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 9, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Докле ћеш ме, Господе, сасвијем заборављати? докле ћеш одвраћати лице своје од мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Докле ћу се домишљати у души својој, мутити се у срцу свом дан и ноћ? докле ће се непријатељ мој подизати нада мном?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Погледај, услиши ме, Господе, Боже мој! Просвијетли очи моје да не заспим на смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Да не рече непријатељ мој: надвладао сам га; да се не радују који ме гоне, ако посрнем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'А ја се уздам у милост твоју; радоваће се срце моје за спасење твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Пјеваћу Господу, који ми добро чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Рече безумник у срцу својем: нема Бога; неваљали су, гадна су дјела њихова;нема никога да добро твори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Господ погледа с неба на синове човјечије, да види има ли који разуман, тражи ли који Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Сви су зашли, сви се покварили, нема никога добро да твори, нема ниједнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Зар се неће опаметити који чине безакоње, једу народ мој као што једу хљеб, не призивају Господа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Ондје ће задрхтати од страха; јер је Господ у роду праведном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Смијете се ономе што убоги ради; али Господ њега заклања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Ко ће послати са Сиона помоћ Израиљу? Кад Господ поврати заробљени народ свој, онда ће се радовати Јаков и веселиће се Израиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Господе ко може сједјети у сјеници твојој? ко може наставати на светој гори твојој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Ко ходи без мане, твори правду, и говори истину из срца својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Ко не опада језиком својим, не чини другоме зла, и не ружи ближњега својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Ко не гледа онога кога је Бог одбацио, него поштује оне који се боје Господа; ко се куне ближњему па не пориче;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Ко не даје сребра својега на добит, и не прима мита на правога. Ко овако ради, неће посрнути довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Чувај ме, Боже; јер се у те уздам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Рекох Господу: ти си Господ мој, немам добра осим тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'У светима који су на земљи и у великима сва је утјеха моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Нека други умножавају идоле своје, нека трче к туђима; ја им не ћу љевати крвавих наљева, нити ћу метнути имена њиховијех у уста своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Господ је мој дио нашљедства и чаше; ти подижеш достојање моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Уже ми је захватило прекрасна мјеста, и дио ми је мој мио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Благосиљам Господа, који ме уразумљује; тому ме и ноћу учи што је у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Свагда видим пред собом Господа: он ми је с десне стране да не посрнем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Тога ради радује се срце моје, и весели се језик мој, још ће се и тијело моје смирити у уздању;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Јер нећеш оставити душе моје у паклу, нити ћеш дати да светац твој види трухлост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Показаћеш ми пут животни: обиље је радости пред лицем твојим, утјеха у десници твојој довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Услиши, Господе, правду, чуј глас мој, прими у уши молитву моју не из уста лажљивијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Од лица твојега нека изађе суд мој, очи твоје нека погледају на правицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Испитај срце моје, обиди ноћу; у огњу ме окушај, и нећеш наћи неправде моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Уста се моја не дохватају дјела људских; ради ријечи уста твојих држим се путова оштрих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Утврди стопе моје на стазама својим да не залазе кораци моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Тебе призивљем, јер ћеш ме услишити, Боже! пригни к мени ухо своје, и чуј ријечи моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Покажи дивну милост своју, који избављаш оне који се у те уздају од онијех који се противе десници твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Чувај ме као зјеницу ока: сјеном крила својих заклони ме');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'Од безбожника који ме нападају, од непријатеља душе моје, који су ме опколили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Срце своје затворише; устима својим говоре охоло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Изагнавши ме опет су око мене; очи су своје упрли да ме оборе на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Они су као лав који хоће да растрже, и као лавић који сједи у потаји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Устани, Господе, претеци их, обори их. Одбрани душу моју мачем својим од безбожника,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Руком својом, Господе, од људи овијех, од људи овога свијета, којима је дио овај живот, којима си трбух напунио свога богатства, да ће им и синови бити сити и остатак оставити својој дјеци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'А ја ћу у правди гледати лице твоје; кад се пробудим, бићу сит од прилике твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Љубићу те, Господе, крепости моја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Господе, граде мој, заклоне мој, који се оборити не може, избавитељу мој, Боже мој, камена горо, на којој се не бојим зла, штите мој, роже спасења мојега, уточиште моје!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Призивљем Господа, којему се клањати ваља, и опраштам се непријатеља својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Обузеше ме смртне болести, и потоци неваљалијех људи уплашише ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Опколише ме болести паклене, стегоше ме замке смртне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'У својој тјескоби призвах Господа, и к Богу својему повиках; он чу из двора својега глас мој, и вика моја дође му до ушију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Затресе се и поколеба се земља, задрмаше се и помјерише из темеља горе, јер се он разљути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Подиже се дим од гњева његова, из уста његовијех огањ, који прождире и живо угљевље отскакаше од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Сави небеса и сиђе. Мрак бјеше под ногама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Сједе на херувима и подиже се, и полетје на крилима вјетрнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Од мрака начини себи кров, сјеницу око себе, од мрачнијех вода, облака ваздушнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Од сијевања пред њим кроз облаке његове удари град и живо угљевље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Загрмје на небесима Господ, и вишњи пусти глас свој, град и живо угљевље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Пусти стријеле своје, и разметну их; силу муња, и расу их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'И показаше се извори водени, и открише се темељи васионој од пријетње твоје, Господе, од дихања духа гњева твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Тада пружи с висине руку, ухвати ме, извуче ме из воде велике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Избави ме од непријатеља мојега силнога и од мојих ненавидника, кад бијаху јачи од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Усташе на ме у дан невоље моје, али ми Господ би потпора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Изведе ме на пространо мјесто, и избави ме, јер сам му мио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Даде ми Господ по правди мојој, и за чистоту руку мојих дарива ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Јер се држах путова Господњих, и не одметнух се Бога својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Него су сви закони његови преда мном, и заповијести његовијех не уклањам од себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Бих му вјеран, и чувах се од безакоња својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Даде ми Господ по правди мојој, по чистоти руку мојих пред очима његовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Са светима поступаш свето, с човјеком вјерним вјерно,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'С чистим чисто, а с неваљалим насупрот њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Јер ти помажеш људима невољним, а очи поносите понижаваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Ти распаљујеш видјело моје; Господ мој просвјетљује таму моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'С тобом разбијам војску, и с Богом својим скачем преко зида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Пут је Господњи вјеран, ријеч Господња чиста. Он је штит свјема који се у њ уздају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Јер ко је Бог осим Господа, и ко је обрана осим Бога нашега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Овај Бог опасује ме снагом, и чини ми вјеран пут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Даје ми ноге као у јелена, и на висине ставља ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Учи руке моје боју, и мишице моје чини да су лук од мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Ти ми дајеш штит спасења својега; десница твоја држи ме, и милост твоја чини ме велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Ти шириш корак мој, те се не спотичу ноге моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Тјерам непријатеље своје и стижем их, и не враћам се док их не истријебим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Обарам их, и не могу устати, падају под ноге моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Јер ме ти опасујеш снагом за бој, и који устану на ме, обараш их преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Непријатеља мојих плећи ти ми обраћаш, и потирем ненавиднике своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Они вичу, али немају помагача, ка Господу, али их он не слуша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Расипам их као прах по вјетру, као блато по улицама газим их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Ти ме избављаш од буне народне, постављаш ме да сам глава туђим племенима; народ којега не познавах, служи ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'По самоме чувењу слушају ме, туђини покорни су ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Туђини блиједе, дршћу у градовима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Жив је Господ, и да је благословен бранич мој! Да се узвиси Бог спасења мојега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Бог, који ми даје освету, и покорава ми народе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Који ме избавља од непријатеља, подиже ме над оне који устају на ме и од човјека жестока избавља ме!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Тога ради хвалим те, Господе, пред народима, и појем имену твојему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Који славно избављаш цара, својега, и чиниш милост помазанику својему Давиду и натражју његову довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 51, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Небеса казују славу Божију, и дјела руку његовијех гласи свод небески.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Дан дану доказује, и ноћ ноћи јавља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Нема језика, нити има говора, гдје се не би чуо глас њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'По свој земљи иде казивање њихово и ријечи њихове на крај васиљене. Сунцу је поставио стан на њима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'И оно излази као женик из ложнице своје, као јунак весело тече путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Излазак му је накрај неба, и ход му до краја његова; и нико није сакривен од топлоте његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Закон је Господњи свршен, кријепи душу; свједочанство је Господње вјерно, даје мудрост невјештоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Наредбе су Господње праведне, веселе срце. Заповијест је Господња свијетла, просвјетљује очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Страх је Господњи чист, остаје довијека. Судови су његови истини, праведни свиколики.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Бољи су од злата и драгог камења, слађи од меда који тече из сата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'И слугу твојега они су просвијетлили; ко их држи има велику плату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Ко ће знати све своје погрјешке? Очисти ме и од тајнијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'И од вољнијех сачувај слугу својега, да не обладају мноме. Тада ћу бити свршен и чист од великога пријеступа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Да су му ријечи уста мојих угодне, и помисао срца мојега пред тобом, Господе, крјепости моја и избавитељу мој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 15, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Да те услиши Господ у дан жалости, да те заштити име Бога Јаковљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Да ти пошље помоћ из светиње, и са Сиона да те поткријепи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Да се опомене свијех приноса твојијех, и жртва твоја паљеница да се нађе претила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Да ти да Господ по срцу твојему; што год почнеш, да ти изврши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Радоваћемо се за спасење твоје, и у име Бога својега дигнућемо заставу. Да испуни Господ све молбе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Сад видим да Господ чува помазаника својега; слуша га са светога неба својега; јака је десница његова, која спасава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Једни се хвале колима, други коњма, а ми именом Господа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Они посрћу и падају, а ми стојимо и не колебамо се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Господе! помози цару, и услиши нас кад те зовемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 10, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Господе! с твоје се силе весели цар; и како му је велика радост што ти помажеш!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Што му је срце жељело, дао си му, и молитве уста његовијех нијеси одбио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Јер си га дочекао благословима милосним, метнуо си му на главу вијенац од драгога камења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Молио те је за живот и дао си му да му се продуље дани довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Велика је слава његова твојом помоћу; славу си и красоту метнуо на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Дао си му благослове довијека, развеселио си га радошћу лица својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Јер се цар узда у Господа и у милост вишњега; и не колеба се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Наћи ће рука твоја све непријатеље твоје, наћи ће десница твоја оне који мрзе на тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Учинићеш их као пећ зажарену, кад се разгњевиш; гњев ће их Господњи прогутати, и огањ ће их прождријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Род њихов истријебићеш са земље, и семе њихово између синова човјечијих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Јер подигоше на тебе зло, смислише и не могоше извршити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Јер ћеш их метнути за биљегу, из лукова својијех пустићеш стријеле у лице њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Подигни се, Господе, силом својом; ми ћемо пјевати и славити јакост твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 14, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Боже, Боже мој! зашто си ме оставио удаљивши се од спасења мојега, од ријечи вике моје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Боже мој! вичем дању, а ти ме не слушаш, и ноћу али немам мира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Свети, који живиш у похвалама Израиљевим!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'У тебе се уздаше оци наши, уздаше се, и ти си их избављао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Тебе призиваше, и спасаваше се; у тебе се уздаше, и не остајаше у срамоти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'А ја сам црв, а не човјек; потсмијех људима и руг народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Који ме виде, сви ми се ругају, разваљују уста, машу главом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'И говоре: ослонио се на Господа, нека му поможе, нека га избави, ако га милује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Та, ти си ме извадио из утробе; ти си ме умирио на сиси матере моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'За тобом пристајем од рођења, од утробе матере моје ти си Бог мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Не удаљуј се од мене; јер је невоља близу, а нема помоћника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Оптече ме мноштво телаца; јаки волови Васански опколише ме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Развалише на ме уста своја. Лав је гладан и риче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Као вода разлих се; расуше се све кости моје; срце моје поста као восак, растопило се у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Сасуши се као цријеп крјепост моја, и језик мој приону за грло, и у прах смртни мећеш ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Опколише ме пси многи; чета зликоваца иде око мене, прободоше руке моје и ноге моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Могао бих избројити све кости своје. Они гледају, и од мене начинише ствар за гледање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Дијеле хаљине моје међу собом, и за доламу моју бацају ждријеб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Али ти, Господе, не удаљуј се. Сило моја, похитај ми у помоћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Избави од мача душу моју, од пса јединицу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Сачувај ме од уста лавовијех, и од рогова биволових, чувши, избави ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Казујем име твоје браћи; усред скупштине хвалићу те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Који се бојите Господа, хвалите га. Све сјеме Јаковљево! поштуј га. Бој га се, све сјеме Израиљево!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Јер се не оглуши молитве ништега нити је одби; не одврати од њега лица својега, него га услиши кад га зазва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Тебе ћу хвалити на скупштини великој; завјете своје свршићу пред онима који се њега боје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Нека једу убоги и насите се, и нека хвале Господа који га траже; живо да буде срце ваше довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Опоменуће се и обратиће се ка Господу сви крајеви земаљски, и поклониће се пред њим сва племена незнабожачка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Јер је Господње царство; он влада народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Јешће и поклониће се сви претили на земљи; пред њим ће пасти сви који слазе у прах, који не могу сачувати душе своје у животу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Сјеме ће њихово служити њему. Казиваће се за Господа роду потоњему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Доћи ће, и казиваће правду његову људима његовијем, који ће се родити; јер је он учинио ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 32, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Господ је пастир мој, ништа ми неће недостајати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'На зеленој паши пасе ме, води ме на тиху воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Душу моју опоравља, води ме стазама праведним имена ради својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Да пођем и долином сјена смртнога, нећу се бојати зла; јер си ти са мном; штап твој и палица твоја тјеши ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Поставио си преда мном трпезу на видику непријатељима мојим; намазао си уљем главу моју, и чаша је моја преопуна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Да! доброта и милост твоја пратиће ме у све дане живота мојега, и ја ћу наставати у дому Господњем за дуго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Господња је земља и што је год у њој, васиљена и све што живи на њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Јер је на морима основа, и посред ријека утврди је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Ко ће изаћи на гору Господњу? и ко ће стати на светом мјесту његову?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'У кога су чисте руке и срце безазлено, ко не изриче имена његова узалуд и не куне се лажно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Он ће добити благослов од Господа, и милост од Бога спаса својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Таки је род онијех који га траже, и који су ради стајати пред лицем твојим, Боже Јаковљев!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Врата! узвисите врхове своје, узвисите се врата вјечна! Иде цар славе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Ко је тај цар славе? Господ крјепак и силан, Господ силан у боју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Врата! узвисите врхове своје, узвисите се врата вјечна! Иде цар славе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Ко је тај цар славе! Господ над војскама; он је цар славе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'К теби, Господе, подижем душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Боже мој! у тебе се уздам; не дај да се осрамотим, да ми се не свете непријатељи моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'И који се год у те уздају, неће се осрамотити; осрамотиће се они који се одмећу од тебе беспутно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Покажи ми, Господе, путове своје, научи ме ходити стазама твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Упути ме истини својој, и научи ме; јер си ти Бог спасења мојега, теби се надам сваки дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Опомени се милосрђа својега, Господе, и милости своје; јер су откако је вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Гријехова младости моје, и мојих пријеступа не помињи; по милости својој помени мене, ради доброте своје, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Добар је и праведан Господ; тога ради показује грјешницима пут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Упућује кротке истини, учи кротке ходити путем његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Сви су путови Господњи милост и истина онима који држе завјет његов и откривење његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Ради имена својега, Господе, опрости гријех мој, јер је велик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Који се човјек боји Господа? Он ће му показати који пут да изабере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Душа ће његова у добру почивати, и сјеме ће његово владати земљом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Тајна је Господња у онијех који га се боје, и завјет свој јавља им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Очи су ми свагда управљене ка Господу, јер он извлачи из замке ноге моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Погледај ме и смилуј се на ме, јер сам инокосан и невољник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Нек се рашири стиснуто срце моје, из тјескобе моје извади ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Види јаде моје и муку моју, и опрости ми све гријехове моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Погледај непријатеље моје како их је много и каквом ме пакосном ненавишћу ненавиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Сачувај душу моју и избави ме; не дај да се осрамотим, јер се у тебе уздам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Безазленост и правда нека ме сачува, јер се у тебе уздам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Избави, Боже, Израиља од свијех невоља његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Суди ми, Господе, јер у простоти својој ходим и у Господа се уздам; нећу се поколебати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Испитај ме, Господе, и искушај ме; претопи што је у мени и срце моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Јер је милост твоја пред очима мојима, и ходим у истини твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Не сједим с безумницима, и с лукавима се не мијешам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Ненавидим друштво безаконичко, и с безбожницима не сједим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Умивам правдом руке своје, и идем око жртвеника твојега, Господе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Да разглашујем хвалу твоју и казујем сва чудеса твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Господе! омилио ми је стан дома твојега, и мјесто насеља славе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Немој душе моје погубити, ни живота мојега с крвопилцима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'Којима је злочинство у рукама, и којима је десница пуна мита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'А ја ходим у простоти својој, избави ме, и смилуј се на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Нога моја стоји на правом путу; на скупштинама ћу благосиљати Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Господ је видјело моје и спасење моје; кога да се бојим? Господ је крјепост живота мојега; кога да се страшим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Ако навале на ме зликовци да поједу тијело моје, противници и непријатељи моји, спотаћи ће се и пашће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Ако против мене војска у око стане, неће се уплашити срце моје; ако се на ме рат дигне, ја се ни онда нећу бојати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'За једно само молим Господа, само то иштем, да живим у дому Господњем све дане живота својега, да гледам красоту Господњу и раним у цркву његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Јер би ме сакрио у колиби својој у зло доба; склонио би ме под кровом шатора својега; на камену гору попео би ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Тада бих подигао главу своју пред непријатељима који би ме опколили; принио бих у његову шатору жртву хвале; запјевао бих и хвалио Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Чуј, Господе, глас мој, тебе призивљем, смилуј се на ме и услиши ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Срце моје говори пред тобом што си рекао: \"тражите лице моје\"; тражим лице твоје, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Немој одвратити од мене лица својега, немој у гњеву оставити слуге својега; буди помоћник мој; немој ме одбити, и немој ме оставити, Боже, спаситељу мој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Јер отац мој и мати моја оставише ме; али Господ нека ме прихвати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Упути ме, Господе, на пут свој и води ме правом стазом поради онијех који ме вребају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Немој ме дати на вољу непријатељима мојим; јер усташе на ме лажни свједоци; али злоба говори сама против себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Вјерујем да ћу видјети доброту Господњу на земљи живијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Уздај се у Господа, буди слободан; нека буде срце твоје крјепко, уздај се у Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'К теби, Господе, вичем; граде мој, немој ми мучати, да не бих, ако узмучиш, био као они који одлазе у гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Чуј молитвени глас мој, кад вапијем к теби, кад дижем руке своје к светој цркви твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Немој ме захватити с грјешницима, и с онима који чине неправду, који с ближњима својима мирно говоре, а у срцу им је зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Подај им, Господе, по дјелима њиховијем, по злому поступању њихову; по дјелима руку њиховијех подај им, подај им што су заслужили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Јер не пазе на дјела Господња, и на дјела руку његовијех. Да их разори и не сазида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Да је благословен Господ, јер услиши глас мољења мојега!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Господ је крјепост моја и штит мој; у њега се поузда срце моје, и он ми поможе. Зато се весели срце моје, и пјесмом својом славим га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Господ је крјепост народа својега, и обрана која спасава помазаника његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Спаси народ свој, благослови достојање своје; спаси их и уздижи их довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Дајте Господу, синови Божји, дајте Господу славу и част.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Дајте Господу славу имена његова. Поклоните се Господу у светој красоти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Глас је Господњи над водом, Бог славе грми, Господ је над водом великом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Глас је Господњи силан, глас је Господњи славан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Глас Господњи ломи кедре, Господ ломи кедре Ливанске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Као теле скачу од њега; Ливан и Сирион као млад биво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Глас Господњи сипа пламен огњени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Глас Господњи потреса пустињу, потреса Господ пустињу Кадес.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Глас Господњи опрашта кошуте бремена, и са шума скида одијело; и у цркви његовој све говори о слави његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Господ је сједио над потопом, и сједјеће Господ као цар увијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Господ ће дати силу народу својему, Господ ће благословити народ свој миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Узвишиваћу те, Господе, јер си ме отео, и нијеси дао непријатељима мојим да ми се свете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Господе, Боже мој! завиках к теби, и исцијелио си ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Господе! извео си из пакла душу моју, и оживио си ме да не сиђем у гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Појте Господу, свеци његови, и славите свето име његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Гњев је његов за тренуће ока, а до живота милост његова, вечером долази плач, а јутром радост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'И ја рекох у добру свом: нећу посрнути довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Ти шћаше, Господе, те гора моја стајаше тврдо. Ти одврати лице своје, и ја се сметох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Тада тебе, Господе, зазивах, и Господа молих:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, '\"Каква је корист од крви моје, да сиђем у гроб? хоће ли те прах славити или казивати истину твоју?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Чуј, Господе, и смилуј се на ме; Господе! буди ми помоћник.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'И ти промијени плач мој на радост, скиде с мене врећу, опаса ме весељем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Зато ће ти пјевати слава слава моја и не ће умукнути; Господе, Боже мој! довијека ћу те хвалити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 13, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'У тебе се, Господе, уздам; немој ме оставити под срамотом довијека, по правди својој избави ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Пригни к мени ухо своје, похитај, помози ми. Буди ми камени град, тврда ограда, гдје бих се спасао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Јер си ти камена гора моја и ограда моја, имена својега ради води ме и управљај мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Извади ме из мреже коју ми тајно замјестише; јер си ти крјепост моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'У твоју руку предајем дух свој; избављао си ме, Господе, Боже истини!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Ненавидим оне који поштују пропадљиве идоле; ја се у Господа уздам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Радоваћу се и веселити се о милости твојој, кад погледаш на моју муку, познаш тугу душе моје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Не даш ме у руку непријатељу, поставиш ноге моје на пространом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Смилуј се на ме, Господе; јер ме је туга, од јада изнеможе око моје, душа моја и срце моје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Ишчиље у жалости живот мој, и године моје у уздисању; ослаби од муке крјепост моја, и кости моје сасахнуше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Од множине непријатеља својих постадох потсмијех и сусједима својим, и страшило знанцима својим; који ме виде на улици, бјеже од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Заборављен сам као мртав, нема ме у срцима; ја сам као разбијен суд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Јер слушам грдњу од многих, отсвуда страх, кад се договарају на ме, мисле ишчупати душу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'А ја се, Господе, у тебе уздам и велим: ти си Бог мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'У твојој су руци дани моји; отми ме из руку непријатеља мојијех, и од онијех, који ме гоне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Покажи свијетло лице своје слузи својему; спаси ме милошћу својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Господе! немој ме оставити под срамотом; јер тебе призивљем. Нек се посраме безбожници, нека замукну и падну у пакао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Нека онијеме уста лажљива, која говоре на праведника обијесно, охоло и с поругом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Како је много у тебе добра, које чуваш за оне који те се боје, и које дајеш онима који се у те уздају пред синовима човјечијим!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Сакриваш их под кров лица својега од буна људских; склањаш их под сјен од свадљивијех језика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Да је благословен Господ, што ми показа дивну милост као да ме уведе у тврд град!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Ја рекох у сметњи својој: одбачен сам од очију твојијех; али ти чу молитвени глас мој, кад те призвах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Љубите Господа сви свети његови; Господ држи вјеру; и увршено враћа онима који поступају охоло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Будите слободни, и нека буде јако срце ваше, сви који се у Господа уздате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 25, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Благо ономе, којему је опроштена кривица, којему је гријех покривен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Благо човјеку, којему Господ не прима гријеха и у чијем духу нема лукавства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Кад мучах, посахнуше кости моје од уздисања мојега по вас дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Јер дан и ноћ тишташе ме рука твоја; неста сока у мени као на љетној припеци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Гријех свој казах теби, и кривице своје не затајих; рекох: исповиједам Господу пријеступе своје; и ти скиде с мене кривицу гријеха мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Зато нека ти се моли сваки светац, кад се можеш наћи; и онда потоп велике воде неће га стигнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Ти си заклон мој, ти ме чуваш од тјескобе; окружаваш ме радостима у избављању.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Уразумићу те, и показаћу ти пут којим да идеш; свјетоваћу те, око је моје на теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Немојте бити као коњ, као мазга без разума, којима уздом и жвалама ваља обуздати губицу, кад не иду к теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Много муке има безбожник, а који се узда у Господа, око њега је милост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Радујте се о Господу, и пјевајте, праведници; веселите се сви који сте права срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Веселите се праведници пред Господом; праведнима доликује славити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Славите Господа гуслама, ударајте му у псалтир од десет жица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Пјевајте му пјесму нову, сложно ударајте подвикујући;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Јер је права ријеч Господња, и свако дјело његово истинито.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Он љуби правду и суд, доброте је Господње пуна земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Ријечју Господњом небеса се створише, и духом уста његовијех сва војска њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Као у гомилу сабра воду морску, и пропасти метну у спреме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Нек се боји Господа сва земља, и нека стрепи пред њим све што живи по васиљеној;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Јер он рече, и постаде; он заповједи, и показа се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Господ разбија намјере незнабошцима, уништава помисли народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Намјера је Господња тврда довијека, мисли срца његова од кољена на кољено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Благо народу, којему је Бог Господ, племену, које је он изабрао себи за наслијеђе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'С неба гледа Господ, види све синове људске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'С пријестола, на коме сједи, погледа на све који живе на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Он је створио сва срца њихова, он и зна сва дјела њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Неће помоћи цару велика сила, неће заштитити јакога велика снага;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Није у коњу уздање да ће помоћи; ако му је и велика снага; неће избавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Гле, око је Господње на онима који га се боје, и на онима који чекају милост његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Он ће душу њихову избавити од смрти, и прехранити их у гладне године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Душа се наша узда у Господа; он је помоћ наша и штит наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'О њему се весели срце наше; јер се у свето име његово уздамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Да буде милост твоја, Господе, на нама, као што се уздамо у тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Благосиљам Господа у свако доба, хвала је његова свагда у устима мојима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Господом се хвали душа моја; нека чују који страдају, па нека се радују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Величајте Господа са мном, узвишујмо име његово заједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Тражих Господа, и чу ме, и свијех невоља мојих опрости ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Који у њега гледају просвијетљују се, и лица се њихова неће постидјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Овај страдалац завика, и Господ га чу, и опрости га свијех невоља његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Анђели Господњи станом стоје око оних који се њега боје, и избављају их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Испитајте и видите како је добар Господ; благо човјеку који се узда у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Бојте се Господа, свети његови; јер који се њега боје, њима нема оскудице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Лавови су убоги и гладни, а који траже Господа, не премиче им се ниједнога добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Ходите, дјецо, послушајте ме; научићу вас страху Господњему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Који човјек жели живота, љуби дане да би видио добро?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Устављај језик свој ода зла, и уста своја од преварне ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Клони се ода зла, и чини добро, тражи мира и иди за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Очи су Господње обраћене на праведнике, и уши његове на јаук њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Али је страшно лице Господње за оне који чине зло, да би истријебио на земљи спомен њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Вичу праведни, и Господ их чује, и избавља их од свијех невоља њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Господ је близу онијех који су скрушена срца, и помаже онима који су смјерна духа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Много невоље има праведник, али га од свијех избавља Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Чува Господ све кости његове, ни једна се од њих неће сломити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Безбожника убиће зло, и који ненавиде праведника превариће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Господ искупљује душу слуга својих, и који се год у њега уздају, неће се преварити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 23, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Господе! буди супарник супарницима мојим; удри оне који ударају на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Узми оружје и штит, и дигни се мени у помоћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Потегни копље, и пресијеци пут онима који ме гоне, реци души мојој: ја сам спасење твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Нека се постиде и посраме који траже душу моју; нека се одбију натраг и постиде који ми зло хоће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Нека буду као прах пред вјетром, и анђео Господњи нека их прогони.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Нека буде пут њихов таман и клизав, и анђео Господњи нека их тјера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Јер низашто застријеше мрежом јаму за мене, ни за што ископаше јаму души мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Нека дође на њега погибао ненадна, и мрежа коју је намјестио нека улови њега, нека он у њу падне на погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'А душа ће се моја радовати о Господу, и веселиће се за помоћ његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Све ће кости моје рећи: Господе! ко је као ти, који избављаш страдалца од онога који му досађује, и ништега и убогога од онога који га упропашћује?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Усташе на ме лажни свједоци; што не знам, за оно ме питају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Плаћају ми зло за добро, и сиротовање души мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Ја се у болести њиховој облачих у врећу, мучих постом душу своју, и молитва се моја враћаше у прсима мојима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Као пријатељ, као брат поступах; бијах сјетан и с обореном главом као онај који за матером жали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'А они се радују кад се ја спотакнем, и купе се, купе се на ме, задају ране, не знам зашто, чупају и не престају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'С неваљалијем и подругљивијем беспосличарима шкргућу на ме зубима својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Господе! хоћеш ли дуго гледати? Отми душу моју од нападања њихова, од овијех лавова јединицу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Признаћу те у сабору великом, усред многога народа хвалићу те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Да ми се не би светили који ми злобе неправедно, и намигивали очима који мрзе на ме ни за што.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Јер они не говоре о миру, него на мирне на земљи измишљају лажне ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Разваљују на ме уста своја, и говоре: добро! добро! види око наше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Видиш, Господе! немој мучати; Господе! немој отступити од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Пробуди се, устани на суд мој, Боже мој и Господе, и на парницу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Суди ми по правди својој, Господе, Боже мој, да ми се не свете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Не дај да говоре у срцу својем: добро! то смо хтјели! Не дај да говоре: прождријесмо га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Нек се постиде и посраме сви који се радују злу мојему, нек се обуку у стид и у срам који се размећу нада мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Нека се радују и веселе који ми желе правду, и говоре једнако: велик Господ, који жели мира слузи својему!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'И мој ће језик казивати правду твоју, и хвалу теби сваки дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Безаконику је безбожна ријеч у срцу; нема страха Божијега пред очима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Али лаже себи у очи, мјесто да призна своје безакоње и омрзне на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Ријечи су уста његовијех неправда и лукавство, неће да се опамети да твори добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Безакоње смишља на постељи својој, стоји на путу рђавом, зло му није мрско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Господе! до неба је милост твоја, и истина твоја до облака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Правда је твоја као горе Божије, судови твоји бездана велика; људе и стоку ти чуваш, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Како је драгоцјена милост твоја, Боже! синови људски у сјену крила твојих не боје се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Хране се од изобила дома твојега, и из потока сладости својих ти их напајаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Јер је у тебе извор животу, твојом свјетлошћу видимо свјетлост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Рашири милост своју на оне који те знаду, и правду своју на добра срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Не дај да стане на мене нога охола, и рука безбожничка да ме заљуља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Онамо нека падну који чине безакоње, нека се стропоштају и не могу устати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 13, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Немој се жестити гледајући неваљале, немој завидјети онима који чине безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Јер се као трава брзо косе, и као зелено биље вену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Уздај се у Господа и твори добро; живи на земљи и храни истину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Тјеши се Господом, и учиниће ти што ти срце жели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Предај Господу пут свој, и уздај се у њега, он ће учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'И извешће као видјело правду твоју, и правицу твоју као подне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Ослони се на Господа, и чекај га. Немој се жестити гледајући кога гдје напредује на путу својем, човјека, који ради што намисли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Утишај гњев, и остави јарост; немој се дражити да зло чиниш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Јер ће се истријебити који чине зло, а који чекају Господа наслиједиће земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Још мало, па неће бити безбожника; погледаћеш на мјесто његово, а њега нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'А смјерни ће наслиједити земљу, и наслађиваће се множином мира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Зло мисли безбожник праведнику, и шкргуће на њ зубима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Али му се Господ смије, јер види да се примиче дан његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Мач потежу безбожници, запињу лук свој, да оборе убогога и ништега и покољу оне који иду правим путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Мач ће њихов ударити у њихово срце, и лукови њихови поломиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Боље је мало у праведника него богатство многих безбожника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Јер ће се мишице безбожницима потрти, а праведнике утврђује Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Зна Господ дане безазленима, и дио њихов траје довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Неће се постидјети у зло доба, у дане гладне биће сити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'А безбожници гину, и непријатељи Господњи као љепота шумска пролазе, као дим пролазе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Безбожник узаима и не враћа, а праведник поклања и даје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Јер које он благослови, они наслиједе земљу, а које он прокуне, они се истријебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Господ утврђује кораке свакога човјека и мио му је пут његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Кад посрне да падне, неће пасти, јер га Господ држи за руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Бијах млад и остарјех, и не видјех праведника остављена, ни дјеце његове да просе хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Сваки дан поклања и даје у зајам, и на натражју је његову благослов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Уклањај се ода зла, и чини добро, и живи довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Јер Господ љуби праведни суд, и не оставља светаца својијех; увијек се они чувају; а племе ће се безбожничко истријебити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Праведници ће наслиједити земљу, и живјеће на њој довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Уста праведникова говоре мудрост, и језик његов казује истину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Закон је Бога његова њему у срцу, стопала се његова не спотичу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Безбожник вреба праведника, и тражи да га убије;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Али га Господ неће пустити у руке његове, нити ће дати да га окриве кад се стану судити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Чекај Господа и држи се пута његова, и он ће те поставити да владаш земљом; видјећеш како ће се истријебити безбожници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Видјех безбожника страшна који се рашириваше као гранато дрво;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Али прође, и ево нема га; тражим га и не находим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Храни чистоту и пази правду, јер ће у човјека мирна остати натражје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'А безаконика ће нестати сасвијем; натражје ће се безбожничко затрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Од Господа је спасење праведницима; он је крјепост њихова у невољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Господ ће им помоћи, и избавиће их; избавиће их од безбожника, и сачуваће их, јер се у њега уздају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Господе! немој ме карати у гњеву својем, нити ме наказати у јарости својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Јер стријеле твоје устријелише ме, и рука ме твоја тишти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Нема здрава мјеста на тијелу мојем од гњева твојега; нема мира у костима мојим од гријеха мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Јер безакоња моја изађоше врх главе моје, као тешко бреме отежаше ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Усмрдјеше се и загнојише се ране моје од безумља мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Згрчио сам се и погурио веома, вас дан идем сјетан;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Јер сам изнутра пун огња, и нема здрава мјеста на тијелу мојем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Изнемогох и веома ослабих, ричем од трзања срца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Господе! пред тобом су све жеље моје, и уздисање моје није од тебе сакривено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Срце моје јако куца, остави ме снага моја, и вид очију мојих, ни њега ми нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Другови моји и пријатељи моји видећи ране моје отступише, далеко стоје ближњи моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Који траже душу моју намјештају замку, и који су ми злу ради, говоре о погибли и по вас дан мисле о пријевари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'А ја као глух не чујем и као нијем који не отвора уста својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Ја сам као човјек који не чује или нема у устима својим правдања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Јер тебе, Господе, чекам, ти одговарај за мене, Господе, Боже мој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Јер рекох: да ми се не свете, и да се не размећу нада мном, кад се спотакне нога моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Јер сам готов пасти, и туга је моја свагда са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Признајем кривицу своју, и тужим ради гријеха својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Непријатељи моји живе, јаки су, и сила их има што ме ненавиде на правди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Који ми враћају зло за добро, непријатељи су ми зато што сам пристао за добрим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Немој ме оставити, Господе, Боже мој! немој се удаљити од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Похитај у помоћ мени, Господе, спаситељу мој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 23, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Рекох: чуваћу се на путовима својим да не згријешим језиком својим; зауздаваћу уста своја, док је безбожник преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Бијах нијем и гласа не пустих; мучах и о добру. Али се туга моја подиже,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Запали се срце моје у мени, у мислима мојим разгорје се огањ; проговорих језиком својим:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Кажи ми, Господе, крај мој, и докле ће трајати дани моји? Да знам како сам ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Ево с педи дао си ми дане, и вијек је мој као ништа пред тобом. Баш је ништа сваки човјек жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Баш ходи човјек као утвара; баш се узалуд кида, сабира, а не зна коме ће допасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Па шта да чекам, Господе? Над је мој у теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Из свега безакоња мојега избави ме, не дај ме безумноме на потсмијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Нијем сам, нећу отворити уста својијех; јер си ме ти ударио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Олакшај ми ударац свој, силна рука твоја уби ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Ако ћеш карати човјека за пријеступе, расточиће се као од мољаца красота његова. Баш је ништа сваки човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Слушај молитву моју, Господе, и чуј јаук мој. Гледајући сузе моје немој мучати. Јер сам гост у тебе и дошљак као и сви стари моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Немој ме више гњевно гледати, па ћу одахнути прије него отидем и више ме не буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 14, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Дуго чеках Господа, и саже се к мени, и чу вику моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Извади ме из јаме, која бучи, и из глиба, и постави на камен ноге моје, и утврди стопе моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'И метну у уста моја пјесму нову, хвалу Богу нашему. Виде многи, и почињу се бојати Господа, и уздати се у њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Благо ономе који на Господа ставља надање своје, и не обраћа се охолима и онијем који теже на лаж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Многа су чудеса твоја, која си учинио Господе, Боже мој, и многе су мисли твоје с нама. Нема ти равна. Хтио бих јављати и казивати, али им броја нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Жртве и дарова нећеш; ти си ми уши отворио; жртве паљенице и која се за гријех приноси не тражиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'И по томе рекох: ево идем, као што је у књизи писано за мене;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Хоћу чинити вољу твоју, Боже мој, и закон је твој мени у срцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Казујем правду на сабору великом; ево, уста својих не устављам; Господе, ти знаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Правде твоје не сакривам у срцу свом, казујем вјерност твоју и спасење твоје; и не тајим милости твоје и истине твоје од сабора великог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Господе, немој затворити срца својега од мене; милост твоја и истина твоја једнако нека ме чувају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Јер ме опколише зла небројена; стигоше ме неправде моје, да не могу гледати; има их више него косе на глави мојој, срце ме моје остави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Господе, вољан буди избавити ме, Господе, похитај ми у помоћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Нек се постиде и посраме сви који траже погибао души мојој! Нек се врате натраг и постиде који ми желе зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Нек се поврате у сметњи својој који ми говоре: ха! ха!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Нека се тјеше и веселе тобом сви који траже тебе, Господе, и који љубе спасење твоје, нека једнако говоре: велик Господ!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Ја сам несрећан и ништ, нека се Господ постара за ме! Ти си помоћ моја и избавитељ мој, Боже мој, не часи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 18, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Благо ономе који разумије ништему! Господ ће га избавити у зли дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Господ ће га сачувати и поживиће га; биће блажен на земљи. Нећеш га дати на вољу непријатељима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Господ ће га укријепити болна на одру. Сасвијем мијењаш постељу његову у болести његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Ја вичем: Господе! смилуј се на ме, исцијели душу моју, сагријеших ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Непријатељи моји говоре злобно за мене: \"кад ће умријети, и име његово погинути?\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'И ако ко дође да ме види, ласка; срце његово слаже у себи неправду, и отишавши казује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Шапћу о мени међу собом непријатељи моји, и мисле ми зло:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, '\"Зла ствар дође на њега, легао је; неће више устати.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'И човјек мира мојега, у којега се уздах, који јеђаше хљеб мој, подиже на ме пету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Али ти, Господе, смилуј се на ме, и подигни ме; а ја ћу им вратити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'По томе ћу познати да сам ти мио, ако се не узрадује непријатељ мој нада мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'А мене цијела сачувај, и дај ми да стојим пред лицем твојим довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Благословен Бог Израиљев од вијека до вијека. Амин, амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 14, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Као што кошута тражи потоке, тако душа моја тражи тебе, Боже!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Жедна је душа моја Бога, Бога живога, кад ћу доћи и показати се лицу Божијему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Сузе су ми хљеб дан и ноћ, кад ми сваки дан говоре: гдје је Бог твој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Душа се моја прољева кад се опомињем како сам ходио сред многога људства; ступао у дом Божји, а људство празнујући пјеваше и подвикиваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Што си клонула, душо моја, и што си жалосна? Уздај се у Бога; јер ћу га још славити, спаситеља мојега и Бога мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Клонула је у мени душа зато што те помињем у земљи Јорданској, на Ермону, на гори малој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Бездана бездану дозивље гласом слапова твојих; све воде твоје и вали твоји на мене навалише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Дању је јављао Господ милост своју, а ноћу му је пјесма у мене, молитва Богу живота мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Рећи ћу Богу, граду својему: зашто си ме заборавио? зашто идем сјетан од пакости непријатељеве?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Који ми пакосте, пребијајући кости моје, ругају ми се говорећи ми сваки дан: гдје ти је Бог?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Што си клонула, душо моја, и што си жалосна? Уздај се у Бога; јер ћу га још славити, спаситеља мојега и Бога мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 12, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Суди ми, Боже, и расправи парбу моју с народом рђавим! од човјека неправеднога и лукавога избави ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Јер си ти Бог крјепости моје; зашто си ме одбацио? Зашто идем сјетан од пакости непријатељеве?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Пошљи видјело своје и истину своју, нека ме воде, и изведу на свету гору твоју и у дворове твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Онда ћу приступити к жртвенику Божијему, к Богу радости и весеља својега, и уз гусле славићу те, Боже, Боже мој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Што си клонула, душо моја, и што си жалосна? Уздај се у Бога; јер ћу га још славити, спаситеља мојега и Бога мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Боже, својим ушима слушасмо, оци нам наши приповиједаше дјело које си учинио у њихово вријеме, у старо вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Руком својом изгнао си народе, а њих посадио; искоријенио си племена, а њих намножио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Јер не задобише земље својим мачем, нити им мишица њихова поможе, него твоја десница и твоја мишица, и свјетлост лица твојега, јер ти бијаху омиљели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Боже, царе мој, ти си онај исти, пошљи помоћ Јакову!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'С тобом ћемо избости непријатеље своје, и с именом твојим изгазићемо оне који устају на нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Јер се не уздам у лук свој, нити ће ми мач мој помоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Него ћеш нас ти избавити од непријатеља нашијех, и ненавиднике наше посрамићеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Богом ћемо се хвалити сваки дан, и име твоје славићемо довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Али сад си нас повргао и посрамио, и не идеш с војском нашом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Обраћаш нас те бјежимо испред непријатеља, и непријатељи нас наши харају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Дао си нас као овце да нас једу, и по народима расијао си нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'У бесцјење си продао народ свој, и нијеси му подигао цијене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Дао си нас на потсмијех сусједима нашијем, да нам се ругају и срамоте нас који живе око нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Начинио си од нас причу у народа, гледајући нас машу главом туђинци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Сваки је дан срамота моја преда мном, и стид је попао лице моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Од ријечи потсмјевачевих и ругачевих, и од погледа непријатељевих и осветљивчевих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Све ово снађе нас; али не заборависмо тебе, нити преступисмо завјета твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Не отступи натраг срце наше, и стопе наше не зађоше с пута твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Кад си нас био у земљи змајевској, и покривао нас сјеном смртнијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Онда да бијасмо заборавили име Бога својега и подигли руке своје к Богу туђему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Не би ли Бог изнашао то? Јер он зна тајне у срцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'А убијају нас за тебе сваки дан; с нама поступају као с овцама кланицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Устани, што спаваш, Господе! Пробуди се, немој одбацити засвагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Зашто кријеш лице своје? заборављаш невољу и муку нашу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Душа наша паде у прах, тијело је наше бачено на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Устани, помоћи наша, и избави нас ради милости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 27, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Тече из срца мојега ријеч добра; рекох: дјело је моје за цара; језик је мој трска хитрога писара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Ти си најљепши између синова људских, благодат тече из уста твојих, јер те је благословио Бог довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Припаши, јуначе, уз бедру своју мач свој, част своју и красоту своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'И тако окићен похитај, сједи на кола за истину и кротку правду, и десница ће твоја показати чудеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Оштре су стријеле твоје; народи ће пасти под власт твоју; простријелиће срца непријатеља царевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Пријесто је твој, Боже, вјечан и непоколебљив; скиптар је царства твојега скиптар правице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Љубиш правду и мрзиш на безакоње; тога ради, помаза те, Боже, Бог твој уљем радости више него другове твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Све хаљине твоје миришу смирном, алојем и касијом. Који живе у дворима од Минијске слонове кости, они те веселе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Царске кћери дворе те; с десне ти стране стоји царица у Офирском злату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Чуј, кћери, погледај и обрати к мени ухо своје, заборави народ свој и дом оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'И цару ће омиљети љепота твоја; јер је он Господ твој, и њему се поклони.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Кћи Тирова доћи ће с даровима, најбогатији у народу тебе ће молити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Сва је украшена кћи царева изнутра, хаљина јој је златом искићена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'У везеној хаљини воде је к цару; за њом воде к теби дјевојке, друге њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Воде их весело и радосно, улазе у двор царев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Мјесто отаца твојих биће синови твоји, поставићеш их кнезовима по свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Учинићу да се не заборавља име твоје од кољена на кољено; потом ће те славити народи вавијек вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 18, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Бог нам је уточиште и сила, помоћник, који се у невољама брзо налази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Зато се нећемо бојати, да би се земља помјестила, и горе се превалиле у срце морима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Нека бучи и кипи вода њихова, нек се планине тресу од вала њиховијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Потоци веселе град Божји, свети стан вишњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Бог је усред њега, неће се помјестити, Бог му помаже од зоре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Узбучаше народи, задрмаше се царства; али он пусти глас свој и земља се растапаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Господ над војскама с нама је, бранич је наш Бог Јаковљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Ходите и видите дјела Господа, који учини чудеса на земљи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Прекиде ратове до краја земље, лук преби, копље сломи, и кола сажеже огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Утолите и познајте да сам ја Бог; ја сам узвишен по народима, узвишен на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Господ над војскама с нама је, бранич је наш бог Јаковљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 12, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Сви народи, запљештите рукама, покликните Богу гласом радоснијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Јер је вишњи Господ страшан, цар велики над свом земљом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Покори нам народе и племена под ноге наше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Избра нам достојање наше, красоту Јакова, који му омиље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Иде Бог уз подвикивање, Господ уз глас трубни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Појте Богу, појте; појте цару нашему, појте;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Јер је Бог цар од све земље, појте пјесму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Бог царује над народима; Бог сједи на светом пријестолу свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Кнезови народни састављају се с народом Бога Аврамова. Јер су штитови земаљски Божији. Да је узвишен!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 10, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Велик је Господ и славан веома у граду Бога нашега, на светој гори својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Прекрасна је висина, утјеха свој земљи гора Сион, на сјеверној страни њезиној град цара великога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Бог у дворима његовијем зна се да је бранич.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Јер, гле, цареви се земаљски сабраше, али прођоше сви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Видјеше и зачудише се, препадоше се и побјегоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Трепет обузе их ондје, мучише се као породиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Вјетром источним разбио си корабље Тарсиске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Што слушамо то и видимо у граду Господа над војскама, у граду Бога нашега, Бог га утврди довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Казујемо, Боже, милост твоју усред цркве твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Као што је име твоје, Боже, тако је и хвала твоја на крајевима земаљским; правде је пуна десница твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Нек се весели гора Сион, нек се радују кћери Јудејске судова ради твојијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Пођите око Сиона и обиђите га, избројте куле његове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Погледајте бедеме његове, размотрите дворове његове, да приповиједате млађим нараштајима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Јер је овај Бог наш Бог увијек и довијека, он ће бити вођ наш довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 15, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Слушајте ово сви народи, пазите сви који живите по васиљеној,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Простаци и господо, богати и сиромаси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Уста ће моја казати премудрост, и срце моје рећи ће разум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Пригнућу ухо своје к причи, уз гусле ћу отворити загонетку своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Чега да се бојим у зле дане, кад ме злоба мојих непријатеља опколи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Који се уздате у силу своју, и хвалите се великијем богатством својим!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Човјек неће никако брата ослободити, неће дати Богу откупа за њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Велик је откуп за душу, и неће бити нигда');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Да ко довијека живи, и не види гроба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Сви виде гдје умиру као и незналица и безумник што гину, и остављају другима имање своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Они мисле да ће куће њихове трајати довијека, и станови њихови од кољена на кољено; именима својим зову земље;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Али човјек у части неће дуго остати, изједначиће се са стоком, коју кољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Овај им се пут чини пробитачан, и који за њима иду, хвале мисли њихове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Али ће их као овце затворити у пакао, смрт ће им бити пастир; и ујутру ходиће по њима праведници, и облик њихов збрисаће пакао раставивши их с насељем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Али ће Бог душу моју избавити из руку паклених; јер ме он прима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Не бој се кад се ко богати; кад расте слава дома његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Јер кад умре, неће ништа понијети, нити ће поћи за њим слава његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Јер душу његову благосиљају за живота његова, и славе тебе, што угађаш себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Али ће он отићи у стан отаца својих, гдје свијета нигда не виде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Човјек у части, ако није разуман, изједначиће се са стоком, коју кољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 21, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Бог над боговима, Господ, говори и дозива земљу од истока сунчанога до запада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Са Сиона, који је врх красоте, јавља се Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Иде Бог наш, и не мучи; пред њим је огањ који прождире, око њега је бура велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Дозива небо озго и земљу, да суди народу својему:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '\"Скупите ми свеце моје, који су учинили са мном завјет на жртви.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, '(И небеса огласише правду његову, јер је тај судија Бог.)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Слушај, народе мој, што ћу ти казати, Израиљу, што ћу ти јавити. Ја сам Бог, Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Нећу те за жртве твоје карати; твоје жртве паљенице свагда су преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Не треба ми узимати телета из дома твојега, ни јарића из торова твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Јер је моје све горско звијерје, и стока по планинама на тисуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Знам све птице по горама, и красота пољска преда мном је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Да огладним, не бих теби рекао, јер је моја васиљена и све што је у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Зар ја једем месо волујско, или крв јарећу пијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Принеси Богу хвалу на жртву, и извршуј вишњему завјете своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Призови ме у невољи својој, избавићу те, и ти ме прослави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'А безбожнику рече Бог: зашто казујеш уредбе моје и носиш завјет мој у устима својима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'А сам мрзиш на науку, и ријечи моје бацаш за леђа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Кад видиш лупежа, пристајеш с њим, и с прељубочинцима имаш дијел.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Уста си своја пустио да говоре зло, и језик твој плете пријеваре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Сједиш и говориш на брата својега, сина матере своје опадаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Ти си то чинио, ја мучах, а ти помисли да сам ја као ти. Обличићу те, метну ћу ти пред очи гријехе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Разумијте ово који заборављате Бога! иначе ћу зграбити, па неће нико избавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Онај мене поштује који приноси хвалу на жртву и који је путем на опазу. Ја ћу му показати спасење Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Смилуј се на ме, Боже, по милости својој, и по великој доброти својој очисти безакоње моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Опери ме добро од безакоња мојега, и од гријеха мојега очисти ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Јер ја знам пријеступе своје, и гријех је мој једнако преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Самоме теби згријеших, и на твоје очи зло учиних, а ти си праведан у ријечима својим и чист у суду својем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Гле, у безакоњу родих се, и у гријеху затрудње мати моја мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Гле, истину љубиш у срцу, и изнутра јављаш ми мудрост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Покропи ме исопом, и очистићу се; умиј ме, и бићу бјељи од снијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Дај ми да слушам радост и весеље, да се прену кости које си потро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Одврати лице своје од гријеха мојих, и сва безакоња моја очисти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Учини ми, Боже, чисто срце, и дух прав понови у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Немој ме одвргнути од лица својега, и светога духа својега немој узети од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Врати ми радост спасења својега, и дух владалачки нека ме поткријепи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Научићу безаконике путовима твојим, и гријешници к теби ће се обратити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Избави ме од крви, Боже, Боже, спаситељу мој, и језик ће мој гласити правду твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Господе! отвори уста моја, и она ће казати хвалу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Јер жртве нећеш: ја бих је принио; за жртве паљенице не мариш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Жртва је Богу дух скрушен, срца скрушена и поништена не одбацујеш, Боже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'По доброти својој, Господе, чини добро Сиону, подигни зидове Јерусалимске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Онда ће ти бити миле жртве правде, приноси и жртве паљенице; онда ће метати на жртвеник твој теоце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 20, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 21, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Што се хвалиш неваљалством, силни? Милост је Божија сваки дан са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Неправду измишља језик твој; он је у тебе као бритва наоштрена, лукави!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Волиш зло него добро, волиш лагати него истину говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Љубиш свакојаке ријечи од погибли, и језик лукав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Тога ради Бог ће те поразити сасвијем, избациће те и ишчупаће те из стана, и коријен твој из земље живијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Видјеће праведници и побојаће се, и потсмијеваће му се:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Гле човјека који не држаше у Богу крјепости своје, него се уздаше у величину богатства својега и утврђиваше се злоћом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'А ја, као маслина зелена у дому Господњем, уздам се у милост Божију без престанка и довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Довијека ћу хвалити тебе, јер добро чиниш, и уздаћу се у име твоје; јер си добар к свецима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 10, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 11, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Рече безумник у срцу својему: нема Бога; проневаљалише се и загрдјеше у безакоњу, нема никога добро да твори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Бог с неба погледа на синове човјечије да види има ли који разуман, и тражи ли који Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Сви застранише, сви се покварише, нема никога добро да твори, нема ни једнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Зар неће да се оразуме који год чине безакоње, једу народ мој као што једу хљеб, и не призивају Бога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Дрктаће од страха гдје страха нема. Јер ће Бог расути кости онијех који устају на тебе. Ти ћеш их посрамити, јер их Бог одврже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Ко ће послати са Сиона спасење Израиљу? Кад Бог поврати заробљени народ свој, радоваће се Јаков, веселиће се Израиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 7, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Боже! именом својим помози ми, и крјепошћу својом одбрани ме на суду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Боже! услиши молитву моју, чуј ријечи уста мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Јер туђини усташе на ме; и силни траже душу моју; немају Бога пред собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Гле, Бог је помоћник мој, Господ даје снагу души мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Обратиће зло на непријатеље моје, истином својом истријебиће их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Радо ћу принијети жртву, прославићу име твоје, Господе, јер је добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Јер ме избављаш од сваке невоље, и на непријатеље моје без страха гледа око моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 8, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 9, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Услиши, Боже, молитву моју, и немој се сакрити од мољења мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Пази, и саслушај ме; цвилим у јаду свом и уздишем');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Од вике непријатељске и од досаде безбожничке; јер дижу на ме зло, и у гњеву гоне ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Срце је моје уздрктало у мени, и страх смртни попаде ме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Страх и трепет дође на ме, и гроза подузе ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'И рекох: ко би ми дао крила голубиња? ја бих одлетео и починуо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Далеко бих побјегао, и настанио се у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Похитао бих да утечем од вихора и од буре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Порази, Господе, и раздијели језике њихове, јер видим насиље и свађу у граду;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Дању и ноћу то ходи по зидовима његовијем; злочинство је и мука посред њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Усред њега је погибао, с улице његове не одлази пријевара и лукавство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Јер не ружи ме непријатељ мој, то бих поднио; не устаје на ме јавни ненавидник, од њега бих се сакрио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Него ти који си ми био то што ја сам, друг мој и знанац мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'С којим ми бјеше радост дијелити тајну, и у дом Божији ходих кроз сабор народни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Нека их уграби смрт, нека живи сиђу у пакао, јер је злочинство у стану њихову и у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Ја Бога призивљем, и Господ ће ме спасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Вечером и јутром и у подне тужим и уздишем, и чуће глас мој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Учиниће, те ће душа моја бити мирна од онијех који нападају на ме, јер их много имам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Да услиши, и укроти их Бог, који живи од вијека; јер се не мијењају и не боје се Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Дижу руке своје на оне који су с њима у миру, и раскидају своју дружбу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Уста су им мека као масло, а на срцу им је рат. Ријечи су им блаже од уља, али су голи мачеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Стави на Господа бреме своје, и он ће те поткријепити. Неће дати довијека праведнику да посрне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Ти ћеш их, Боже, свалити у јаму погибли; крвопије и лукави неће саставити половине дана својих. А ја се у теби уздам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 24, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Смилуј се на ме, Боже, јер човјек хоће да ме прогута, непријатељ ме сваки дан притјешњује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Непријатељи моји сваки дан траже да ме прогутају; јер многи нападају на ме охоло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Кад ме је страх, јер се у тебе уздам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Богом се хвалим за ријеч његову; у Бога се уздам, не бојим се; шта ће ми учинити тијело?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Сваки дан изврћу ријечи моје; што год мисле, све мени о злу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Скупљају се, прикривају се, пазе за петама мојима; јер траже душу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Код оваке злоће избави од њих, у гњеву обори народе, Боже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'У тебе је избројено моје потуцање, сузе се моје чувају у суду код тебе, оне су у књизи твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Непријатељи моји уступају натраг, кад тебе призивљем; по том знам да је Бог са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Богом се хвалим за ријеч његову, Господом се хвалим за ријеч његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'У Бога се уздам, не бојим се; шта ће ми учинити човјек?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Теби сам се, Боже, завјетовао; тебе ћу хвалити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Јер си избавио душу моју од смрти, ноге моје од спотицања, да бих ходио пред лицем Божјим, у свјетлости живијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 14, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Смилуј се на ме, Боже, смилуј се на ме; јер се у тебе узда душа моја, и под сјен крила твојих склањам се док не прођу невоље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Призивам Бога вишњега, Бога, који ми добро чини;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Да пошље с неба и сачува ме, да посрами онога који тражи да ме прождре; да пошље Бог милост своју и истину своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Душа је моја међу лавовима, лежим међу онима који дишу пламеном. Зуби су синова људских копља и стријеле, и њихов језик мач оштар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Узвиси се више небеса, Боже, по свој земљи нека буде слава твоја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Метнуше замку ногама мојима, и стегоше душу моју, ископаше преда мном јаму, и сами падоше у њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Утврдило се срце моје, Боже, утврдило се срце моје; пјеваћу те и славићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Пробуди се, славо моја, пробуди се, псалтире и гусле; устаћу рано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Хвалићу Господа по народима, пјеваћу ти по племенима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Јер је велика до небеса милост твоја, и истина твоја до облака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Узвиси се више небеса, Боже, по свој земљи нека буде слава твоја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 12, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Говорите ли заиста истину, силни, судите ли право, синови човјечији?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Та, безакоња састављате у срцу, мећете на мјерила злочинства руку својих на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Од самога рођења застранише безаконици, од утробе материне тумарају говорећи лаж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'У њима је јед као јед змијињи, као глухе аспиде, која затискује ухо своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Која не чује гласа бајачу, врачару, вјешту у врачању.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Боже! поломи им зубе у устима њиховијем; разбиј чељусти лавовима, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Нек се пролију као вода, и нестане их. Кад пусте стријеле, нека буду као сломљене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Као пуж, који се рашчиња, нека ишчиле; као дијете, које жена побаци, нека не виде сунца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Прије него котлови ваши осјете топлоту од потпаљена трња, и сирово и нагорјело нека разнесе вихор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Обрадоваће се праведник кад види освету, опраће ноге своје у крви безбожниковој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'И рећи ће људи: заиста има плода праведнику! заиста је Бог судија на земљи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 12, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Избави ме од непријатеља мојих, Боже мој, и од онијех, што устају на ме, заклони ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Избави ме од онијех који чине безакоње, и од крвопија сачувај ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Ево зло намишљају души мојој, скупљају се на ме силни, без кривице моје и без гријеха мојега, Господе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Без кривице моје стјечу се и оружају се; устани за мене, и гледај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Ти, Господе, Боже над војскама, Боже Израиљев, пробуди се, обиђи све ове народе, немој пожалити одметника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Нек се врате увече, лају као пси, и иду око града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Ево руже језиком својим, мач им је у устима, јер, веле, ко ће чути?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Али ти ћеш се, Господе, смијати њима и посрамити све ове народе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Они су јаки, али ја на тебе погледам, јер си ти Бог чувар мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Бог, који ме милује, иде преда мном, Бог ми даје без страха да гледам непријатеље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Немој их побити, да не би заборавио народ мој; распи их силом својом и обори их, Господе, браничу наш,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'За гријех уста њиховијех; за ријечи језика њихова; нек се ухвате у охолости својој за клетву и лаж коју су говорили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Распи у гњеву, распи, да их нема; и нека познаду да Бог влада над Јаковом и до крајева земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Нек се врате увече, лају као пси, и иду око града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Нека тумарају тражећи хране, и не наситивши се нека ноћи проводе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'А ја ћу пјевати силу твоју, рано ујутру гласити милост твоју; јер си ми био обрана и уточиште у дан невоље моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Сило моја! Теби ћу пјевати, јер си ти Бог чувар мој, Бог који ме милује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 18, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Боже, расрдио си се на нас, расуо си нас, гњевио си се; поврати нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Затресао си земљу, и развалио си је; стегни расјелине њезине, јер се њиха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Дао си народу својему да позна љуту невољу, напојио си нас вина од којега се занесосмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Подигни заставу за оне који те се боје, да утеку од лука,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Да се избаве мили твоји. Помози десницом својом и услиши ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Бог рече у светињи својој: веселићу се, раздијелићу Сихем, и долину Сокот размјерићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Мој је Галад, мој је Манасија, Јефрем је крјепост главе моје, Јуда скиптар мој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Моав чаша моја, из које се умивам, на Едома пружићу обућу своју. Пјевај ми, Филистејска земљо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Ко ће ме одвести у тврди град? Ко ће ме отпратити до Едома?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Зар нећеш ти, Боже, који си нас одбацио, и не идеш, Боже, с војском нашом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Дај нам помоћ у тјескоби. А обрана је човјечија узалуд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Богом смо јаки: он гази непријатеље наше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 13, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 14, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Чуј, Боже, вику моју, слушај молитву моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Од краја земље вичем к теби, кад клону срце моје. Изведи ме на гору, гдје се не могу попети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Јер си ти уточиште моје, тврди заклон од непријатеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Да живим у стану твом довијека, и починем под кровом крила твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Јер ти, Боже, чујеш завјете моје и дајеш ми достојање онијех који поштују име твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Додај дане к данима царевијем, и године његове продуљи од кољена на кољено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Нека царује довијека пред Богом; заповједи милости и истини нека га чувају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Тако ћу пјевати имену твојему свагда, извршујући завјете своје сваки дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 9, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Та, у Бога је мир души мојој, од њега је спасење моје!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Та, он је град мој и спасење моје, уточиште моје, нећу посрнути нимало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Докле ћете нападати на човјека? Сви хоћете да га оборите као зид наваљен, као ограду испроваљивану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Баш наумише да га свргну с висине, омиље им лаж, устима благосиљају а у срцу куну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Да, у Богу се смири, душо моја; јер је у њему над мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Он је град мој и спасење моје, уточиште моје, нећу посрнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'У Богу је спасење моје и слава моја, тврди град и пристаниште мени је у Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Народе! уздај се у њега у свако доба; изливајте пред њим срце своје; Бог је наше уточиште.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Та, синови су простачки ништа, синови су господски лаж, да се метну на мјерила, били би лакши него ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Не уздајте се у власт ни у отимање, немојте бити ништави; кад расте богатство, не дајте да вам срце прионе за њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Једном рече Бог и више пута чух, да је крјепост у Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'И у тебе је, Господе, милост; јер ти плаћаш свакоме по дјелима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 13, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Боже! ти си Бог мој, к теби раним, жедна је тебе душа моја, за тобом чезне тијело моје у земљи сухој, жедној и безводној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Тако бих те угледао у светињи, да бих видио силу твоју и славу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Јер је доброта твоја боља од живота. Уста би моја хвалила тебе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Тако бих те благосиљао за живота свога, у име твоје подигао бих руке своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Као салом и уљем наситила би се душа моја, и радоснијем гласом хвалила би те уста моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Кад те се сјећам на постељи, све ноћне страже размишљам о теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Јер си ти помоћ моја, и у сјену крила твојих веселим се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Душа се моја прилијепила за тебе, десница твоја држи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Који траже погибао души мојој, они ће отићи под земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Изгинуће од мача, и допашће лисицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'А цар ће се веселити о Богу, хвалиће се сваки који се куне њим, кад се затисну уста онима који говоре лаж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 12, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Чуј, Боже, глас мој у јаду мом; од страшнога непријатеља сачувај живот мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Сакриј ме од гомиле безаконика, од чете злочинаца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Који наоштрише језик свој као мач, стријељају ријечима, које задају ране,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'Да би из потаје убили правога. Изненада ударају на њ и не боје се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Утврђују себе у злијем намјерама, договарају се како ће замке сакрити, веле: ко ће их видјети?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Измишљају злочинства и говоре: свршено је! шта ће се радити, смишљено је! А што је унутра и срце у човјека дубоко је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Али ће их Бог поразити; удариће их стријела изненада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Обориће један другога језиком својим. Ко их год види, бјежаће од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Сви ће се људи бојати и казиваће чудо Божије, и познаће у томе дјело његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'А праведник ће се веселити о Господу и уздаће се у њега, и хвалиће се сви који су права срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 11, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'У теби је уздање, Боже, теби припада хвала на Сиону, и теби се извршују завјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Ти слушаш молитву; к теби долази свако тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Безакоња ме притискују, ти ћеш очистити гријехе наше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Благо ономе кога избираш и примаш, да живи у двору твом! Наситићемо се добром дома твојега, светињом цркве твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Дивно нам одговараш по правди својој, Боже, спаситељу наш, узданицо свијех крајева земаљских, и народа преко мора далеко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Који си поставио горе својом силом, опасао се јачином,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Који утишаваш хуку морску, хуку вала њиховијех и буну по народима!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Боје се твојих чудеса који живе на крајевима земаљским; све што се јавља јутром и вечером ти будиш да слави тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Надгледаш земљу и заливаш је, обилно је обогаћаваш; поток је Божји пун воде, спремаш за њих жито, јер си тако уредио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Бразде њезине напајаш, равниш груде њезине, кишним капљама размекшаваш је, благосиљаш је да рађа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Ти вјенчаваш годину, којој добро чиниш; стопе су твоје пуне масти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Тију паше по пустињама, и хумови се опасују радошћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Луке се осипају стадима, и поља се заодијевају пшеницом; веселе се и пјевају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 14, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Покликни Богу, сва земљо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Запјевајте славу имену његову, дајте му хвалу и славу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Реците Богу: како си страшан у дјелима својим! ради велике силе твоје ласкају ти непријатељи твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Сва земља нек се поклони теби и поје теби, нека поје имену твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Ходите и видите дјела Бога страшнога у дјелима својим над синовима људским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Он је претворио море у сухоту, преко ријеке пријеђосмо ногама; ондје смо се веселили о њему;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Влада силом својом увијек, очи његове гледају на народе. Бунтовници, да се нијесте подигли!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Благосиљајте, народи, Бога нашега, и гласите хвалу њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Он је даровао души нашој живот, и није дао да поклизне нога наша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Ти си нас окушао, Боже, претопио си нас, као сребро што се претапа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Увео си нас у мрежу, метнуо си бреме на леђа наша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Дао си нас у јарам човјеку, уђосмо у огањ и у воду; али си нас извео на одмор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Ући ћу у дом твој са жртвама што се сажижу, извршићу ти завјете своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Које рекоше уста моја, и каза језик мој у тјескоби мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Жртве паљенице претиле ћу ту принијети с димом од претилине овнујске, принијећу ти теоце с јарићима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Ходите, чујте сви који се бојите Бога, ја ћу вам казати шта је учинио души мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'К њему завиках устима својим, и језиком својим прославих га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Да сам видио у срцу свом безакоње, не би ме услишио Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Али Бог услиши, прими глас мољења мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Благословен Бог, који не одврже молитве моје и не остави ме без милости своје!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Боже, буди нам милостив и благосиљај нас, обасјавај нас лицем својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Да би се знао на земљи пут твој, по свима народима спасење твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Да те славе народи, Боже, да те славе сви народи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Да се веселе и радују племена; јер судиш народима право, и племенима на земљи управљаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Да те славе народи, Боже, да те славе сви народи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Земља даде плод свој. Да нас благосиља Бог, Бог наш!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Да нас благосиља Бог, и да га се боје сви крајеви земаљски!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 8, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Устаће Бог, и расуће се непријатељи његови, и побјећи ће од лица његова који мрзе на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Ти ћеш их разагнати као дим што се разгони; као што се восак топи од огња, тако ће безбожници изгинути од лица Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'А праведници ће се веселити, радоваће се пред Богом, и славити у радости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Појте Богу, попијевајте имену његову; равните пут ономе што иде преко пустиње; Господ му је име, радујте му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Отац је сиротама и судија удовицама Бог у светоме стану свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Бог самцима даје задругу, сужње изводи на мјеста обилна, а непокорни живе гдје је суша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Боже! кад си ишао пред народом својим, кад си ишао преко пустиње,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Земља се тресијаше, и небо се растапаше од лица Божијега, и овај Синај од лица Бога, Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Благодатни си дажд изливао, Боже, и кад изнемагаше достојање твоје, ти си га кријепио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Стадо твоје живљаше ондје; по доброти својој, Боже, ти си готовио храну јадноме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Господ даје ријеч; гласника велико је мноштво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Цареви над војскама бјеже, бјеже, а која сједи дома, дијели плијен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Смиривши се у својим крајевима, ви сте као голубица, којој су крила посребрена а перје јој се златни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Кад је свемогући расипао цареве на овој земљи, она се блисташе као снијег на Селмону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Гора је Васанска гора Божија; гора је Васанска гора хумовита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Зашто гледате завидљиво, горе хумовите? Ево гора, на којој омиље Богу живјети, и на којој ће Господ живјети довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Кола Божијих има сила, тисуће тисућа. Међу њима је Господ, Синај у светињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Ти си изашао на висину, довео си робље, примио дарове за људе, а и за оне који се противе да овдје наставаш, Господе Боже!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Благословен Господ сваки дан! Ако нас ко претовара, Бог нам помаже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Овај је Бог наш Бог спаситељ, у власти су Господу врата смртна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Господ сатире главу непријатељима својим и власато тјеме онога који остаје у безакоњу својем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Рече Господ: од Васана ћу довести, довешћу из дубине морске,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Да ти огрезне нога у крви непријатељској и језик паса твојих да је лиже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Видјеше како идеш, Боже, како свето иде Бог мој, цар мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Напријед иђаху пјевачи, за њима свирачи сред дјевојака с бубњима:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, '\"На сабору благосиљајте Господа Бога, који сте из извора Израиљева!\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Ондје млади Венијамин, старјешина њихов; кнезови Јудини, владаоци њихови; кнезови Завулонови, кнезови Нефталимови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Бог твој даровао ти је силу. Утврди, Боже, ово што си учинио за нас!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'У цркви твојој, у Јерусалиму, цареви ће приносити даре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Укроти звијер у риту, код волова с теоцима народа, да би попадали пред тобом са шипкама сребра; распи народе који желе бојеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Доћи ће властела из Мисира, Етиопија ће пружити руке своје к Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Царства земаљска, појте Богу, попијевајте Господу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Који сједи на небесима небеса исконских. Ево грми гласом јаким.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Дајте славу Богу; величанство је његово над Израиљем и сила његова на облацима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Диван си, Боже, у светињи својој! Бог Израиљев даје силу и крјепост народу. Благословен Бог!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 36, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Помози ми, Боже, јер дође вода до душе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Пропадам у дубоком глибу, гдје нема дна; тонем води у дубине, и вали ме затрпавају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Изнемогох вичући, промуче ми грло, побијељеше ми очи погледајући Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Онијех који мрзе на ме ни за што има више него косе на глави мојој; осилише који хоће да ме погубе, лажљиви непријатељи моји. Што нијесам отимао, ваља да вратим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Боже! ти знаш је ли у мени безумље, и кривице моје нијесу сакривене од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Немој да се постиде у мени који се уздају у тебе, Господе, Господе над војскама! Немој да се посраме у мени који траже тебе, Боже Израиљев!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Јер тебе ради подносим руг, и срамота попаде лице моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Туђин постадох браћи својој, и незнан синовима матере своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Јер ревност за кућу твоју једе ме и ружења онијех који тебе руже падају на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Плачем, постим се душом својом, и то ми се прима за зло;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Мјесто хаљине облачим врећу, и бивам им прича.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'О мени се разговарају сједећи на вратима, пијући вину пјевају ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'А ја се молим теби, Господе; вријеме је да се смилујеш, Боже; по великој милости својој услиши ме, јер је истинито спасење твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Извади ме из глиба, да не пропаднем; да се избавим од ненавидника и из дубоке воде;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Да ме не узме вода на матицу, да ме не прождре пучина, и да не склопи јама нада мном ждријела својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Услиши ме, Господе, јер је благост твоја милосрдна, по великој доброти својој погледај ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Немој одвратити лица својега од слуге својега; јер ме је туга; похитај, услиши ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Приближи се души мојој, избави је; насупрот непријатељима мојим избави ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Ти знаш под каквим сам ругом, стидом и срамотом; пред тобом су сви непријатељи моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Срамота сатр срце моје, изнемогох; чекам хоће ли се коме сажалити, али нема никога; хоће ли ме ко потјешити, али не налазим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Дају ми жуч да једем, и у жеђи мојој поје ме оцтом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Трпеза њихова нека им буде мрежа и замка, то нека им буде плата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Нека им потамне очи њихове, да не виде, и њихове бедре раслаби засвагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Излиј на њих јарост своју, и пламен гњева твојега нека их обузме!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Стан њихов нека опусти, и у њиховијем шаторима нека не буде никога да живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Јер кога си ти поразио, они гоне, и умножавају јаде онима које си ти ранио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Мећи на њих кривицу за кривицом, да не дођу до правде твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Нека се избришу из књиге живијех, и с праведницима нек не буду записани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'А ја сам ништ и болан; помоћ твоја, Боже, нек ме заклони.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Славићу име Божије у пјесми, величаћу га у хвали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'То је Богу милије од вола, од телета с роговима и с папцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Видјеће ништи и радоваће се. Који тражите Бога, оживјеће срце ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Јер Бог чује убоге, и сужања својих не оглуша се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Нека га хвале небеса и земља, мора и све што се у њима миче!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Јер ће Бог спасти Сион, сазидаће градове Јудине; и људи ће се ондје населити и наслиједиће га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'И натражје ће се слуга његовијех утврдити у њему и који љубе име његово наставаће на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 37, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Боже, похитај да ме избавиш, Господе, да ми поможеш!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Нек се постиде и посраме који траже душу моју! Нек уступе натраг, и осрамоте се који ми зло желе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Са стидом нек се врате натраг који ми говоре: ха! ха!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Нек се тјеше и веселе тобом који траже тебе, и који љубе спасење твоје, нека једнако говоре: велик је Бог!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'А ја сам ништ и убог, Боже, похитај к мени! ти си помоћ моја и избавитељ мој, Господе, не часи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 6, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'У тебе се, Господе, уздам, немој ме оставити под срамотом вјечном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Правдом својом избави ме, и опрости ме, пригни к мени ухо своје и помози ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Буди ми град гдје бих свагда долазио да живим, уреди спасење моје; јер си ти град мој и крјепост моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Боже мој! узми ме из руке безбожникове, из руке безаконикове и насилникове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Јер си ти надање моје, Господ је Господ поуздање моје од младости моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Тебе се држим од рођења, од утробе матере моје ти си бранич мој; тобом се хвалим свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Чудо сам многима, а ти си уточиште моје јако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Уста су моја пуна хвале твоје, славе твоје сваки дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Немој ме одбацити под старост, кад ме издаје снага моја, немој ме оставити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Јер непријатељи моји мисле о мени, и који вребају душу моју договарају се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Говорећи: Бог га је оставио, потјерајте и ухватите га, јер га нема ко избавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Боже! Не буди далеко од мене; Боже мој! похитај ми у помоћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Нек се постиде и погину противници душе моје; нека попадне стид и срамота на оне који ми траже зла!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'А ја ћу се свагда уздати, и понављаћу хвале теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Уста ће моја казивати правду твоју, сваки дан доброчинства твоја, јер им не знам броја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Ући ћу у сили Господа Господа, и славићу само твоју правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Боже! ти си ме учио од младости, и до данас казујем чудеса твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Ни у старости и кад осиједјех немој ме оставити, Боже, еда бих казивао мишицу твоју натражју, свој омладини силу твоју,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Правда је твоја, Боже, до највише висине; у великим дјелима, која си учинио, Боже, ко је као ти?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Колико си ме пута бацао у велике и љуте невоље, пак си ме опет оставио међу живима и из бездана ме земаљских опет извадио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Много си ме пута подизао и понављао утјехе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'И ја те хвалим уз псалтир, твоју вјерност, Боже мој; ударам ти у гусле, свече Израиљев!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Радују се уста моја кад пјевам теби, и душа моја, коју си избавио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'И језик мој сваки дан казује правду твоју; јер су постиђени и посрамљени они који ми траже зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Боже, дај цару суд свој, и правду своју сину цареву:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Он ће судити народу твојему по правди, и невољницима твојим по правици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Родиће народу горе миром, и хумови правдом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Он ће судити невољнима у народу, помоћи ће синовима ништега, и насилника ће оборити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Бојаће се тебе док је сунца и мјесеца, од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Сићи ће као дажд на покошену ливаду, као капље које порашају земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Процвјетаће у дане његове праведник и свуда мир докле тече мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Владаће од мора до мора, и од ријеке до крајева земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Пред њим ће попадати дивљаци, и непријатељи његови прах ће лизати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Цареви Тарсиски и острвљани донијеће даре, цареви Шавски и Савски даће данак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Клањаће му се сви цареви, сви народи биће му покорни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Јер ће избавити убогога који цвили и невољнога који нема помоћника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Биће милостив ништему и убогом, и душе ће јаднима спасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Од пријеваре и насиља искупиће душе њихове, и скупа ће бити крв њихова пред очима његовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Они ће добро живјети, и донијеће му злато из Шаве; и свагда ће се молити за њега, и сваки ће га дан благосиљати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Биће пшенице на земљи изобила; по врховима горским лелујаће се класје њезино као Ливанска шума, и по градовима цвјетаће људи као трава на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Име ће његово бити увијек; докле тече сунца, име ће његово расти. Благословиће се у њему, сви ће га народи звати блаженим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Благословен Господ Бог, Бог Израиљев, који један чини чудеса!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'И благословено славно име његово увијек! славе његове напуниће се сва земља. Аман и амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Свршише се молитве Давида, сина Јесејева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Та добар је Бог Израиљу, онима који су чиста срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'А ноге моје умало не зађоше, умало не попузнуше стопала моја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Јер се расрдих на безумнике видећи како безбожници добро живе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Јер не знају за невољу до саме смрти, и тијело је њихово претило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'На пословима човјечијим нема их, и не муче се с другим људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Тога ради опточени су охолошћу као огрлицом, и обучени у обијест као у стајаће рухо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Од дебљине избуљено им је око, срце пуно клапе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Потсмијевају се, пакосно говоре о насиљу, охоло говоре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Уста своја дижу у небо, и земљу пролази језик њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'И зато се онамо навраћају неки из народа његова, и пију воду из пуна извора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'И говоре: како ће разабрати Бог? зар вишњи зна?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Па ето, ови безбожници срећни на свијету умножавају богатство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Зар дакле узалуд чистим срце своје, и умивам безазленошћу руке своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Допадам рана сваки дан, и муке свако јутро?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Кад бих казао: говорићу као и они, изневјерио бих род синова твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'И тако стадох размишљати да бих ово разумио; али то бјеше тешко у очима мојима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Док најпослије уђох у светињу Божију, и дознах крај њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Та на клизавом мјесту поставио си их, и бацаш их у пропаст!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Како зачас пропадају, гину, нестаје их од ненадне страхоте!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Као сан, кад се човјек пробуди, тако пробудивши их, Господе, у ништа обраћаш утвару њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Кад кипљаше срце моје и растрзах се у себи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Тада бијах незналица и не разумијевах; као живинче бијах пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Али сам свагда код тебе, ти ме држиш за десну руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'По својој вољи водиш ме, и послије ћеш ме одвести у славу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Кога имам на небу? и с тобом ничега нећу на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Чезне за тобом тијело моје и срце моје; Бог је град срца мојега и дио мој довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Јер ево који отступише од тебе, гину; ти истребљаваш свакога који чини прељубу остављајући тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'А мени је добро бити близу Бога. На Господа полажем надање своје, и казиваћу сва чудеса твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Зашто се, Боже, срдиш на нас дуго; дими се гњев твој на овце паше твоје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Опомени се сабора својега, који си стекао од старине, искупио себи у нашљедну државу, горе Сиона, на којој си се населио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Подигни стопе своје на старе развалине: све је разрушио непријатељ у светињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Ричу непријатељи твоји на мјесту сабора твојих, своје обичаје постављају мјесто наших обичаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Видиш, они су као онај који подиже сјекиру на сплетене гране у дрвета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Све у њему што је резано разбише сјекирама и брадвама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Огњем сажегоше светињу твоју; на земљу обаливши оскврнише стан имена твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Рекоше у срцу својем: потримо их сасвијем. Попалише сва мјеста сабора Божијих на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Обичаја својих не видимо, нема више пророка, и нема у нас ко би знао докле ће то трајати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Докле ће се, Боже, ругати насилник? хоће ли довијека противник пркосити имену твојему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Зашто устављаш руку своју и десницу своју? Пружи из њедара својих, и истријеби их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Боже, царе мој, који од старине твориш спасење посред земље!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Ти си силом својом раскинуо море, и сатро главе воденим наказама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Ти си размрскао главу крокодилу, дао га онима који живе у пустињи да га једу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Ти си отворио изворе и потоке, ти си исушио ријеке које не пресишу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Твој је дан и твоја је ноћ, ти си поставио звијезде и сунце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Ти си утврдио све крајеве земаљске, љето и зиму ти си уредио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Опомени се тога, непријатељ се руга Господу, и народ безумни не мари за име твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Не дај звијерима душе грлице своје, немој заборавити стада страдалаца својих засвагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Погледај на завјет; јер су све пећине земаљске пуне станова безакоња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Невољник нек се не врати срамотан, ништи и убоги нека хвале име твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Устани, Боже, брани ствар своју, опомени се како ти се безумник руга сваки дан!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Не заборави обијести непријатеља својих, вике, коју једнако дижу противници твоји!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Хвалимо те, Боже, хвалимо; близу је име твоје. За тебе казују чудеса твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, '\"Кад видим да је вријеме, судићу право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Њиха се земља са свијема који живе на њој, ја утврђујем ступове њезине.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Кажем хвалишама: не хвалите се, и безаконицима: не дижите рога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Не дижите у вис рога својега, не говорите тврдоглаво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Јер узвишивање не долази ни од истока ни од запада ни од пустиње;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Него је Бог судија, једнога понижује а другога узвишује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Јер је чаша у руци Господу, вино ври, наточио је пуну, и раздаје из ње. И талог ће њезин прогутати, испиће сви безбожници на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'А ја ћу казивати довијека, пјеваћу Богу Јаковљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, '\"Све ћу рогове безбожницима поломити, а рогови праведникови узвисиће се.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 11, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Зна се у Јудеји за Бога, у Израиља је велико име његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'У Салиму је стан његов и насеље његово на Сиону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Ондје је поломио крилате стријеле луку, штит и мач и рат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Ти си свијетао; дивнији од гора хајдучких.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Који су јуначког срца посташе плијен, заспаше сном својим, и јунаци не нађоше руку својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Од пријетње твоје, Боже Јаковљев, дријемљу кола и коњ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Ти си страшан, и ко ће се одржати пред лицем твојим кад се разгњевиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'С неба јављаш суд; земља се препада и мучи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Кад Бог устаје на суд, да поможе свима који страдају на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'И гњев људски обраћа се у славу теби, кад се једном опашеш гњевом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Полажите и извршујте завјете Господу Богу својему; сви који сте око њега, носите даре страшноме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Он укроћава дух кнезовима, он је страшан царевима земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 13, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Глас мој иде к Богу, и ја призивљем њега; глас мој иде к Богу, и он ће ме услишити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'У дан туге своје тражих Господа; ноћу је рука моја подигнута, и не спушта се; душа моја неће да се утјеши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Помињем Бога, и уздишем; размишљам, и трне дух мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Држим очи своје да су будне; клонуо сам, и не могу говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Пребрајам старе дане и године од вијекова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Опомињем се пјесама својих ноћу; разговарам се са срцем својим, и испитујем дух свој:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, '\"Зар ће се довијека гњевити на нас Господ, и неће више љубити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Зар је засвагда престала милост његова, и ријеч се прекинула од кољена на кољено?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Зар је заборавио милостив бити и у гњеву затворио милосрђе своје?\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'И рекох: жалосна је за мене ова промјена деснице вишњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Памтим дјела Господња; памтим пређашње чудо твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Мислио сам о свијем дјелима твојим, размишљао о радњи твојој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Боже! пут је твој свет; који је Бог тако велик као Бог наш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Ти си Бог, који си чинио чудеса, показивао силу своју међу народима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Мишицом си одбранио народ свој, синове Јаковљеве и Јосифове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Видјеше те воде, Боже, видјеше те воде, и устрепташе, и бездане се задрмаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Из облака лијаше вода, облаци даваху глас, и стријеле твоје лећаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Грмљаху громови твоји по небу; муње твоје сијеваху по васиљеној, земља се тресијаше и њихаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'По мору бијаше пут твој, и стазе твоје по великој води, и траг твој не познаваше се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Водио си народ свој као овце руком Мојсијевом и Ароновом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 21, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Чуј, народе мој, наук мој, пригни ухо своје к ријечима уста мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Отворам за причу уста своја, казаћу старе приповијетке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Што слушасмо и дознасмо, и што нам казиваше оци наши,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Нећемо затајити од дјеце њихове, нараштају позном јавићемо славу Господњу и силу његову и чудеса која је учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Свједочанство подиже у Јакову, и у Израиљу постави закон, који даде оцима нашим да га предаду дјеци својој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Да би знао потоњи нараштај, дјеца која ће се родити, па и они да би казивали својој дјеци');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Да полажу на Бога надање своје, и не заборављају дјела Божијих, и заповијести његове да држе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'И да не буду као оци њихови, род неваљао и упоран, род који не бјеше тврд срцем својим, нити вјеран Богу духом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Синови Јефремови наоружани, који стријељају из лука, вратише се натраг, кад бијаше бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Не сачуваше завјета Божијега, и по закону његову не хтјеше ходити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Заборавише дјела његова, и чудеса, која им је показао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Како пред очима њиховијем учини чудеса у земљи Мисирској, на пољу Соану;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Раздвоји море, и проведе их, од воде начини зид;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'И води их дању облаком, и сву ноћ свијетлијем огњем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Раскида стијене у пустињи, и поји их као из велике бездане;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Изводи потоке из камена, и води воду ријекама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Али они још једнако гријешише њему, и гњевише вишњега у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'И кушаше Бога у срцу свом, иштући јела по вољи својој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'И викаше на Бога, и рекоше: \"може ли Бог зготовити трпезу у пустињи?\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Ево! он удари у камен, и потече вода, и ријеке устадоше; може ли и хљеба дати? хоће ли и меса поставити народу својему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Господ чу и разљути се, и огањ се разгорје на Јакова, и гњев се подиже на Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Јер не вјероваше Богу и не уздаше се у помоћ његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Тада заповједи облацима одозго, и отвори врата небеска,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'И пусти, те им подаждје мана за јело, и хљеб небески даде им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Хљеба анђелскога јеђаше човјек; посла им јела до ситости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Пусти небом устоку, и наведе силом својом југ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'И као прахом засу их месом, и као пијеском морским птицама крилатим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Побаца их сред окола њихова, око шатора њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'И наједоше се и даде им што су жељели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Али их још и не прође жеља, још бјеше јело у устима њиховијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'Гњев се Божји подиже на њих и помори најјаче међу њима, и младиће у Израиљу поби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Преко свега тога још гријешише, и не вјероваше чудесима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'И пусти, те дани њихови пролазише узалуд, и године њихове у страху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Кад их убијаше, онда притјецаху к њему, и обраћаху се и искаху Бога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'И помињаху да је Бог обрана њихова, и вишњи избавитељ њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Ласкаху му устима својима, и језиком својим лагаху му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'А срце њихово не бјеше њему вјерно, и не бијаху тврди у завјету његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Али он бјеше милостив, и покриваше гријех, и не помори их, често устављаше гњев свој, и не подизаше све јарости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Опомињаше се да су тијело, вјетар, који пролази и не враћа се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Колико га пута расрдише у пустињи, и увриједише у земљи гдје се не живи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Све наново кушаше Бога, и свеца Израиљева дражише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Не сјећаше се руке његове и дана, у који их избави из невоље,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'У који учини у Мисиру знаке своје и чудеса своја на пољу Соану;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'И проврже у крв ријеке њихове и потоке њихове, да не могоше пити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Посла на њих бубине да их кољу, и жабе да их море.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Љетину њихову даде црву, и муку њихову скакавцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Винограде њихове поби градом, и смокве њихове сланом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Граду предаде стоку њихову, и стада њихова муњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Посла на њих огњени гњев свој, јарост, срдњу и мржњу, чету злијех анђела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Равни стазу гњеву својему, не чува душа њиховијех од смрти, и живот њихов предаде помору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Поби све првенце у Мисиру, први пород по колибама Хамовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'И поведе народ свој као овце, и води их као стадо преко пустиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Води их поуздано, и они се не бојаше, а непријатеље њихове затрпа море.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'И доведе их на мјесто светиње своје, на ову гору, коју задоби десница његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Одагна испред лица њихова народе; ждријебом раздијели њихово достојање, и по шаторима њиховијем насели кољена Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Али они кушаше и срдише Бога вишњега и уредаба његовијех не сачуваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Одусташе и одвргоше се, као и оци њихови, слагаше као рђав лук.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Увриједише га висинама својим, и идолима својим раздражише га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Бог чу и разгњеви се и расрди се на Израиља веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Остави насеље своје у Силому, шатор, у којем живљаше с људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'И оправи у ропство славу своју и красоту своју у руке непријатељеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'И предаде мачу народ свој, и на достојање своје запламтје се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Младиће његове једе огањ, и дјевојкама његовијем не пјеваше сватовских пјесама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Свештеници његови падаше од мача, и удовице његове не плакаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Најпослије као иза сна пробуди се Господ, прену се као јунак кад се напије вина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'И поби непријатеље своје с леђа, вјечној срамоти предаде их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'И не хтје шатора Јосифова, и кољена Јефремова не изабра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Него изабра кољено Јудино, гору Сион, која му омиље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'И сагради светињу своју као горње своје станове, и као земљу утврди је довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'И изабра Давида слугу својега, и узе га од торова овчијих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'И од дојилица доведе га да пасе народ његов, Јакова, и нашљедство његово, Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'И он их пасе чистијем срцем, и води их мудријем рукама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Боже! незнабошци дођоше у достојање твоје; оскврнише свету цркву твоју, Јерусалим претворише у зидине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Трупље слуга твојих дадоше птицама небескијем да их једу, тијела светаца твојих звијерима земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Пролише крв њихову као воду око Јерусалима, и не бјеше ко да погребе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Постадосмо потсмијех у сусједа својих, ругају нам се и срамоте нас који су око нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Докле ћеш се, Господе, једнако гњевити, јарост твоја горјети као огањ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Излиј гњев свој на народе који те не знају, и на царства која не призивљу твојега имена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Јер изједоше Јакова, и насеље његово опустише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Не помињи пређашњих безакоња наших, већ похитај да нас пресретеш милосрђем својим, јер смо веома олошали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Помози нам, Боже, спаситељу наш, ради славе имена својега, избави нас и очисти од гријеха наших ради имена својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Зашто да говоре незнабошци: гдје је Бог њихов? Нека се покаже пред очима нашим освета над незнабошцима за пролиту крв слуга твојих!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Нека изађу пред лице твоје уздаси сужањски, силом мишице своје сачувај намијењене смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Седмином врати у њедра сусједима нашим ружење, којим те ружише, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'А ми народ твој и овце паше твоје довијека ћемо тебе славити и од кољена на кољено казивати хвалу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Пастире Израиљев, чуј! који водиш синове Јосифове као овце, који сједиш на херувимима, јави се!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Пред Јефремом и Венијамином и Манасијом пробуди крјепост своју, и ходи да нам поможеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Боже! поврати нас, нека засја лице твоје да се спасемо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Господе, Боже над војскама! докле ћеш се гњевити кад те моли народ твој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Храниш их хљебом сузнијем, и појиш их сузама троструком мјером.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Учинио си да се око нас свађају сусједи наши, и непријатељи се наши смију међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Боже над војскама! поврати нас, нека засја лице твоје да се спасемо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Из Мисира си пренио чокот, изагнао народе, и посадио га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Окрчио си за њ, и он пусти жиле, и заузе сву земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Горе се покрише његовијем сјеном, и лозе су му као кедри Божији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Пустио је лозе своје до мора и огранке своје до ријеке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Зашто си му развалио ограду, да га кида ко год прође?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Горски вепар подгриза га, и пољска звијер једе га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Боже над војскама! обрати се, погледај с неба и види, и обиђи виноград овај,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Сад онај, који је посадила десница твоја, и сина којега си укријепио себи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Попаљен је огњем, исјечен, од страшнога погледа твојега пропаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Нека буде рука твоја над човјеком деснице твоје, над сином човјечијим којега си утврдио себи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'И нећемо отступити од тебе, оживи нас, и име твоје призиваћемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Господе, Боже над војскама! поврати нас, нека засја лице твоје, да се спасемо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 20, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Радујте се Богу, који нам даје крјепост; покликујте Богу Јаковљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Подигните пјесме, дајте бубањ, слатке гусле са псалтиром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Трубите о мијени у трубу, о уштапу ради празника нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Јер је таки закон у Израиља, наредба од Бога Јаковљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'За свједочанство постави Јосифу ово, кад иђаше на земљу Мисирску. Језик, којега не знах, чух!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, '\"Уклонио сам рамена његова од бремена, руке његове опростише се котарица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'У невољи си ме зазвао, и избавих те, услиших те усред грома, на води Мериви искушах те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Слушај, народе мој, и засвједочићу ти, Израиљу, о кад би ме послушао:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Да не буде у тебе туђега Бога, и Богу страноме немој се клањати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Ја сам Господ, Бог твој, који сам те извео из земље Мисирске; отвори уста своја, и ја ћу их напунити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Али не послуша народ мој гласа мојега, Израиљ не мари за ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'И ја их пустих на вољу срца њихова, нека ходе по својим мислима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'О кад би народ мој слушао мене, и синови Израиљеви ходили путовима мојим!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Брзо бих покорио непријатеље њихове, и на противнике њихове дигао бих руку своју;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Који мрзе на Господа, били би им покорни, и добри дани њихови били би довијека;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Најбољом би пшеницом хранио њих, и медом бих из камена ситио их.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 17, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Бог стаде на сабору Божијем, усред богова изрече суд:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '\"Докле ћете судити неправо, и безбожницима гледати ко је ко?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Судите убогоме и сироти, онога кога гоне и ништега правдајте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Избављајте убогога и ништега, из руке безбожничке отимајте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Не познаше, нити разумјеше, ходе по тами; задрмаше се земљи сви темељи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Рекох: богови сте, и синови вишњега сви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Али ћете као људи помријети, и као сваки кнез пашћете.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Устани, Боже, суди земљи; јер су твоји по нашљедству сви народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Боже! немој замукнути, немој шутјети, нити почивај, Боже!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Јер ево непријатељи твоји узавреше, и који те ненавиде, подигоше главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'По народ твој зло наумише, и договарају се на избране твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Рекоше: ходите да их истријебимо између народа да се више не спомиње име Израиљево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Сложно присташе и супрот теби вјеру ухватише:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Насеља Едомова и Исмаиловци, Моав и Агарени,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Гевал и Амон и Амалик, Филистеји с Тирцима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'И Асур удружи се с њима; постадоше мишица синовима Лотовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Учини им онако као Мадијаму, као Сисари, као Јавину на потоку Кисону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Који су истријебљени у Аендору, нагнојише собом земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Уради с њима, с кнезовима њиховијем, као с Оривом и Зивом, и са свима главарима њиховијем као са Зевејем и Салманом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Јер говоре: освојимо насеља Божија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Боже мој! заповједи нека буду као прах, као пијесак пред вјетром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Као што огањ сажиже шуму, и као пламен што запаљује горе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Тако их погнај буром својом и вихором својим смети их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Покриј лице њихово срамотом, да би тражили име твоје, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Нека се стиде и сраме довијека, нека се смету и изгину!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'И нека знаду да си ти, којему је име Господ, једини највиши над свом земљом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 19, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Како су мили станови твоји, Господе над силама!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Гине душа моја желећи у дворе Господње; срце моје и тијело моје отима се к Богу живоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'И птица находи кућу, и ластавица гнијездо себи гдје леже птиће своје, код олтара твојих, Господе над силама, царе мој и Боже мој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Благо онима који живе у дому твом! Они те хвале без престанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Благо онима којима је сила у теби, и којима су у срцу путови твоји!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Идући долином плачевном, претварају је у изворе, и дажд је одијева благословима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Иду збор за збором, јављају се пред Богом на Сиону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Господе, Боже над силама! услиши молитву моју, Боже Јаковљев!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Боже, браничу наш! сагни се и види лице помазаника својега!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Јер је боље један дан у дворима твојим од хиљаде. Волим бити на прагу дома Божијега него живјети у шаторима безбожничким.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Јер је Господ Бог сунце и штит, Господ даје благодат и славу; онима који ходе у безазлености не украћује ниједнога добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Господе над силама! благо човјеку, који се у те узда!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 13, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Смиловао си се, Господе, на земљу своју, повратио си робље Јаковљево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Простио си неправду народу својему, покрио си све гријехе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Уставио си сву јарост своју, ублажио жестину гњева својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Поврати нас, Боже спаситељу наш, прекини срдњу своју на нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Зар ћеш се довијека гњевити на нас, и протегнути гњев свој од кољена на кољено?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Зар се нећеш повратити и оживити нас, да би се народ твој радовао о теби?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Покажи нам, Господе, милост своју, и помоћ своју дај нам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Да послушам што говори Господ Бог. Он изриче мир народу својему и свецима својим, и онима који се обраћају срцем к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Да, близу је онијех који га се боје помоћ његова, да би населио славу у земљи нашој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Милост и истина срешће се, правда и мир пољубиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Истина ће никнути из земље и правда ће с неба приникнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'И Господ ће дати добро, и земља наша даће плод свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Правда ће пред њим ићи, и поставиће на пут стопе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 14, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Пригни, Господе! ухо своје и услиши ме, јер сам невољан и ништ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Сачувај душу моју, јер сам твој поклоник. Спаси слугу својега, Боже мој, који се у те узда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Смилуј се на ме, Господе, јер к теби вичем вас дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Обесели душу слуге својега, јер к теби, Господе, подижем душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Јер си ти, Господе, добар и милосрдан и веома милостив свима који те призивљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Чуј, Господе, молитву моју, и слушај глас мољења мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'У дан туге своје призивљем те, јер ћеш ме услишити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Нема међу боговима такога какав си ти, Господе, и нема дјела такијех каква су твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Сви народи, које си створио, доћи ће и поклонити се пред тобом, Господе, и славити име твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Јер си ти велик и твориш чудеса; ти си један Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Покажи ми, Господе, пут свој, и ићи ћу у истини твојој; учини нека се мили срцу мојему бојати се имена твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Славићу те, Господе Боже мој, свијем срцем својим, и поштоваћу име твоје довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Јер је милост твоја велика нада мном, и извадио си душу моју из пакла најдубљега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Боже, охолице усташе на мене, и гомила насилника тражи душу моју, и немају тебе пред собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Али ти, Господе, Боже милостиви и благи, стрпљиви и богати добротом и истином,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Погледај на ме и смилуј ми се, дај силу своју слузи својему, и помози сину слушкиње своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Учини са мном чудо доброте. Нека виде који ме ненавиде, и постиде се, што си ми, Господе, помогао и утјешио ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Што је сам основао на горама светијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Врата Сионска љуби Господ више свијех станова Јаковљевијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Славно казују за тебе, граде Божји!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, '\"Међу оне, који ме знају, бројићу Мисир и Вавилон. Гле и Филистеји и Тир с Етиопском ондје су се родили.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'О Сиону ће се говорити: тај се и тај родио у њему; сам вишњи утврђује га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Господ ће у пријепису народа завикати: овај се родио у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'И који пјевају и веселе се, сви су извори моји у теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Господе Боже, спаситељу мој, дању вичем и ноћу пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Нек изађе преда те молитва моја, пригни ухо своје к јауку мојему;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Јер је душа моја пуна јада, и живот се мој примаче паклу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Изједначих се с онима који у гроб одлазе, постадох као човјек без силе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Као међу мртве бачен, као убијени, који леже у гробу, којих се више не сјећаш, и који су од руке твоје далеко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Метнуо си ме у јаму најдоњу, у таму, у бездану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Отежа ми гњев твој, и свима валима својим удараш ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Удаљио си од мене познанике моје, њима си ме омразио; затворен сам, и не могу изаћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Око моје усахну од јада, вичем те, Господе, вас дан, пружам к теби руке своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Еда ли ћеш на мртвима чинити чудеса? или ће мртви устати и тебе славити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Еда ли ће се у гробу приповиједати милост твоја, и истина твоја у трухљењу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Еда ли ће у тами познати чудеса твоја, и правду твоју гдје се све заборавља?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Али ја, Господе, к теби вичем, и јутром молитва моја срета те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Зашто, Господе, одбацујеш душу моју, и одвраћаш лице своје од мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Мучим се и издишем од удараца, подносим страхоте твоје, без надања сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Гњев твој стиже ме, страхоте твоје раздиру ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Оптјечу ме сваки дан као вода, стежу ме отсвуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Удаљио си од мене друга и пријатеља; познаници моји сакрили су се у мрак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 19, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Милости ћу Господње пјевати увијек, од кољена на кољено јављаћу истину твоју устима својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Јер знам да је зававијек основана милост, и на небесима да си утврдио истину своју, рекавши:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, '\"Учиних завјет с избраним својим, заклех се Давиду, слузи својему:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Довијека ћу утврђивати сјеме твоје и пријесто твој уређивати од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Небо казује чудеса твоја, Господе, и истину твоју сабор светијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Јер ко је над облацима раван Господу? ко ће се изједначити с Господом међу синовима Божијим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Богу се ваља клањати на сабору светијех, страшнији је од свијех који су око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Господе, Боже над војскама! ко је силан као ти, Боже? И истина је твоја око тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Ти владаш над силом морском; кад подигне вале своје, ти их укроћаваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Ти си оборио охоли Мисир као рањеника, крјепком мишицом својом расијао си непријатеље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Твоје је небо и твоја је земља; ти си саздао васиљену и што је год у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Сјевер и југ ти си створио, Тавор и Ермон о твом се имену радује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Твоја је мишица крјепка, силна је рука твоја, и висока десница твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Благост је и правда подножје пријестолу твојему, милост и истина иде пред лицем твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Благо народу који зна трубну поклич! Господе! у свјетлости лица твојега они ходе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Именом се твојим радују вас дан, и правдом твојом узвишују се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Јер си ти красота силе њихове, и по милости твојој узвишује се рог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Јер је од Господа обрана наша, и од светога Израиљева цар наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Тада си говорио у утвари вјернима својим, и рекао: \"послах помоћ јунаку, узвисих избранога својега из народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Нађох Давида слугу својега, светим уљем својим помазах га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Рука ће моја бити једнако с њим, и мишица моја кријепиће га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Неће га непријатељ надвладати, и син безакоња неће му досадити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Потрћу пред лицем његовијем непријатеље његове, и ненавиднике његове поразићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Истина је моја и милост моја с њим; и у моје име узвисиће се рог његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Пружићу на море руку његову, и на ријеке десницу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Он ће ме звати: ти си отац мој, Бог мој и град спасења мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'И ја ћу га учинити првенцем, вишим од царева земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Довијека ћу му хранити милост своју, и завјет је мој с њим вјеран.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Продуљићу сјеме његово довијека, и пријесто његов као дане небеске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Ако синови његови оставе закон мој, и не узиду у заповијестима мојим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Ако погазе уредбе моје, и заповијести мојих не сачувају,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Онда ћу их покарати прутом за непокорност, и ранама за безакоње њихово;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Али милости своје нећу узети од њега, нити ћу преврнути истином својом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Нећу погазити завјета својега, и што је изашло из уста мојих нећу порећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Једном се заклех светошћу својом; зар да слажем Давиду?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Сјеме ће његово трајати довијека, и пријесто његов као сунце преда мном;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Он ће стајати увијек као мјесец и вјерни свједок у облацима.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'А сад си одбацио и занемарио, разгњевио си се на помазаника својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Занемарио си завјет са слугом својим, бацио си на земљу вијенац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Развалио си све ограде његове, градове његове обратио си у зидине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Плијене га сви који пролазе онуда, поста потсмијех у сусједа својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Узвисио си десницу непријатеља његовијех, обрадовао си све противнике његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Завратио си оштрице мача његова, и нијеси га укријепио у боју;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Узео си му свјетлост, и пријесто његов оборио си на земљу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Скратио си дане младости његове и обукао га у срамоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Докле ћеш се, Господе, једнако одвраћати, докле ће као огањ пламтјети гњев твој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Опомени се какав је вијек мој, како си ни на што створио све синове Адамове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Који је човјек живио и није смрти видио, и избавио душу своју из руку пакленијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Гдје су пређашње милости твоје, Господе? Клео си се Давиду истином својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Опомени се, Господе, пријекора слуга својих, који носим у њедрима својим од свијех силнијех народа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Којим коре непријатељи твоји, Господе, којим коре траг помазаника твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Благословен Господ увијек! Амин, амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 53, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Господе! ти си нам уточиште од кољења до кољења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Прије него се горе родише и сазда се земља и васиљена, и од вијека до вијека, ти си Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Ти повраћаш човјека у трухлеж, и говориш: вратите се синови људски!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Јер је тисућа година пред очима твојима као дан јучерашњи, кад мине, и као стража ноћна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Ти их као поводњем односиш; они су као сан, као трава, која рано вене,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Ујутру цвјета и увене, увече се покоси и сасуши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Јер нас нестаје од гњева твојега, и од јарости твоје у сметњи смо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Ставио си безакоња наша преда се, и тајне наше на свјетлост лица својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Сви се дани наши прекраћују од срдње твоје, године наше пролазе као глас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Дана година наших свега има до седамдесет година, а у јачега до осамдесет година: и сам је цвијет њихов мука и невоља; јер теку брзо, и ми одлијећемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Ко зна силу гњева твојега и твоју јарост, да би те се као што треба бојао?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Научи нас тако бројити дане наше, да бисмо стекли срце мудро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Поврати се, Господе! Докле ћеш? Смилуј се на слуге своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Ујутру нас насити доброте своје, и радоваћемо се и веселити у све дане своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Обрадуј нас према данима, у које си нас мучио, и према годинама, у које смо гледали невољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Нека се покаже на слугама твојим дјело твоје, и слава твоја на синовима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Нека буде добра воља Господа Бога нашега с нама, и дјело руку наших доврши нам, и дјело руку наших доврши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Који живе у заклону вишњега, у сјену свемогућега почива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Говори Господу: ти си уточиште моје и бранич мој, Бог мој, у којега се уздам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Он ће те избавити из замке птичареве, и од љутога помора;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Перјем својим осјениће те, и под крилима његовијем заклонићеш се; истина је његова штит и ограда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Нећеш се бојати страхоте ноћне, стријеле, која лети дању,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'Помора, који иде по мраку, болести, која у подне мори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Пашће поред тебе тисућа и десет тисућа с десне стране теби, а тебе се неће дотаћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Само ћеш гледати очима својима, и видјећеш плату безбожницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Јер си ти, Господе, поуздање моје. Вишњега си изабрао себи за уточиште.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Неће те зло задесити, и ударац неће досегнути до колибе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Јер анђелима својим заповиједа за тебе да те чувају по свијем путовима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'На руке ће те узети да гдје не запнеш за камен ногом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'На лава и на аспиду наступаћеш и газићеш лавића и змаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, '\"Кад ме љуби, избавићу га; заклонићу га, кад је познао име моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Зазваће ме, и услишићу га; с њим ћу бити у невољи, избавићу га и прославићу га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Дуга живота наситићу га, и показаћу му спасење своје.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Лијепо је хвалити Господа, и пјевати имену твојему, вишњи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Јављати јутром милост твоју, и истину твоју ноћу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Уз десет жица и уз псалтир, и уз јасне гусле!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Јер си ме развеселио, Господе, дјелима својим, с дјела руку твојих радујем се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Како су велика дјела твоја, Господе! Веома су дубоке помисли твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Безумник не зна, и незналица не разумије тога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Кад безбожници ничу као трава и цвјетају сви који чине безакоње, то бива зато да би се истријебили довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'А ти си, Господе, висок увијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Јер ево непријатељи твоји, Господе, јер ево непријатељи твоји гину, и расипају се сви који чине безакоње;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'А мој рог ти узвишујеш као рог у једнорога, ја сам помазан новијем уљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'И око моје види непријатеље моје, и о безаконицима, који устају на мене, слушају уши моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Праведник се зелени као финик, као кедар на Ливану узвишује се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Који су засађени у дому Господњем, зелене се у дворовима Бога нашега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Родни су и у старости, једри и зелени,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Јављајући да је праведник Господ, бранич мој, и да нема у њему неправде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 16, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Господ царује. Обукао се у величанство, обукао се Господ у силу, и опасао се. Зато је васиљена тврда, и неће се помјерити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Пријесто твој стоји од искона; од вијека ти си.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Подижу ријеке, Господе, подижу ријеке глас свој, подижу ријеке вале своје:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Од хујања воде многе и силне, од вала морских силнији је на висини Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Свједочанства су твоја веома тврда; дому твојему припада светлост, Господе, на дуго вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Боже од освете, Господе, Боже од освете, покажи се!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Подигни се, судијо земаљски, подај заслугу охолима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Докле ће се безбожници, Господе, докле ће се безбожници хвалити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Руже и охоло говоре, величају се сви који чине безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Газе народ твој, Господе, и достојање твоје муче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Удовицу и дошљака убијају, и сироте море.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'И говоре: неће видјети Господ, и неће дознати Бог Јаковљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Оразумите се, прелуди људи! будале! кад ћете бити паметни?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Који је створио ухо, зар не чује? и који је око начинио, зар не види?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Зар неће обличити који народе уразумљује, који учи човјека да зна?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Господ зна мисли људима како су ништаве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Благо човјеку кога ти, Господе, уразумљујеш, и законом својим учиш;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Да би му дао мир у зле дане, док се ископа јама безбожнику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Јер неће одбацити Господ народа својега, и достојања својега неће оставити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Јер ће се суд вратити на правду, и њега ће наћи сви права срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Ко ће устати за мене супрот злима? ко ће стати за мене супрот онима који чине безакоње?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Кад ми Господ не би био помоћник, брзо би се душа моја преселила онамо гдје се мучи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Кад речем: дркће ми нога, милост твоја, Господе, прихвата ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Кад се умноже бриге у срцу мом, утјехе твоје разговарају душу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Еда ли ће се близу тебе стати пријесто крвнички, и онај који намишља насиље насупрот закону?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Спремају се на душу праведникову, и крв праву окривљују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Али је Господ моје пристаниште, и Бог је мој тврдо уточиште моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Он ће им вратити за безакоње њихово, за њихову злоћу истријебиће их, истријебиће их Господ, Бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Ходите, запјевајмо Господу, покликнимо Богу, граду спасења својега!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Изађимо пред лице његово с хвалом, у пјесмама покликнимо му!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Јер је Господ велик Бог и велик цар над свијем боговима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'У његовој су руци дубине земаљске, и висине горске његове су.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Његово је море и он га је створио, и сухоту руке су његове начиниле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Ходите, поклонимо се, припаднимо, клекнимо пред Господом творцем својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Јер је он Бог наш, и ми народ паше његове и овце руке његове. Сад кад бисте послушали глас његов:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, '\"Немојте да вам одрвени срце ваше као Мериви, као у дан кушања у пустињи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Гдје ме кушаше оци ваши, испиташе и видјеше дјело моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Четрдесет година срдих се на род онај, и рекох: ови људи тумарају срцем, и не знају путова мојих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'И зато се заклех у гњеву свом да неће ући у мир мој.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Пјевајте Господу пјесму нову, пјевај Господу, сва земљо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Пјевајте Господу, благосиљајте име његово, јављајте од дана на дан спасење његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Казујте по народима славу његову, по свијем племенима чудеса његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Јер је велик Господ и ваља га хвалити: страшнији је од свијех богова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Јер су сви богови у народа ништа; а Господ је небеса створио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Слава је и величанство пред лицем његовијем, сила и красота у светињи његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Дајте, Господу, племена народна, дајте Господу славу и част.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Дајте Господу славу према имену његову. Носите даре и идите у дворе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Поклоните се Господу у светој красоти. Стрепи пред њим, сва земљо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Реците народима: Господ царује; зато је васиљена тврда и неће се помјестити; он ће судити народима право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Нек се веселе небеса, и земља се радује; нек пљеска мора и што је у њему;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Нека скаче поље и све што је на њему; тада нек се радују сва дрвета шумска');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Пред лицем Господњим; јер иде, јер иде да суди земљи. Судиће васиљеној по правди, и народима по истини својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Господ царује: нек се радује земља! нек се веселе острва многа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Облак је и мрак око њега; благост и правда подножје пријестолу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Огањ пред њим иде, и пали наоколо непријатеље његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Муње његове сијевају по васиљеној; види и стрепи земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Горе као восак топе се од лица Господњега, од лица Господа свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Небеса казују правду његову, и сви народи виде славу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Нек се стиде сви који се клањају киповима, који се хвале идолима својим. Поклоните му се сви богови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Чује и радује се Сион, и кћери се Јудејске веселе ради судова твојих, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Јер си ти, Господе, висок над свом земљом и надвишујеш све богове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Који љубите Господа, мрзите на зло. Он чува душе светаца својих; из руку безбожничких отима их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Свјетлост се просипа на праведника, и весеље на оне који су права срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Радујте се праведни о Господу, и славите свето име његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Појте Господу пјесму нову, јер учини чудеса. Поможе му десница његова и света мишица његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Јави Господ спасење своје, пред народима откри правду своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Опомену се милости своје и вјерности своје к дому Израиљеву. Видјеше сви крајеви земаљски спасење Бога нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Радуј се Господу, сва земљо; пјевајте, покликујте и попијевајте!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Ударајте Господу у гусле, у гусле и с гласом псаламским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'У трубе и рогове затрубите пред царем Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Нека пљеска море и што је у њему, васиљена и који у њој живе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Ријеке нека пљескају рукама; скупа горе нек се радују');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Пред лицем Господњим; јер иде да суди земљи; судиће васиљеној праведно, и народима вјерно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Господ царује: нека стрепе народи; сједи на херувимима: нек се дрма земља!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Господ је на Сиону велик, и висок над свима народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Нека славе велико и страшно име твоје; да је свет!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Нека славе силу цара који љуби правду. Ти си утврдио правду; суд и правду ти си уредио у Јакову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Узвишујте Господа Бога нашега, и клањајте се подножју његову; да је свет!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Мојсије и Арон, свештеници његови, и Самуило један од онијех који призивљу име његово, призиваху Бога, и он их услиши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'У ступу од облака говораше њима; они чуваше заповијести његове и уредбу коју им даде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Господе, Боже наш, ти си их услишио; ти си им био Бог благ и плаћао за дјела њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Узвишујте Господа Бога нашега, и клањајте се на светој гори његовој, јер је свет Господ бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Радуј се Господу, сва земљо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Служите Господу весело; идите пред лице његово пјевајући!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Познајте Господ да је Бог. Он нас је створио, и ми смо достојање његово, народ његов и овце паше његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Улазите на врата његова са славом, у дворе његове с хвалом. Славите га, и благосиљајте име његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Јер је добар Господ; милост је његова увијек, и истина његова од кољена на кољено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Милост и правду пјевам; тебе, Господе, славим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Размишљам о путу правом, кад би год дошао к мени, ходим у безазлености срца својега у дому свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Не стављам пред очи своје ријечи непотребне, мрзим на дјела која су против закона, не пристајем за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Срце покварено далеко је од мене; злијех не знам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Ко тајно опада ближњега својега, тога изгоним; ко је охола ока и надута срца, тога не трпим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Очи су моје обраћене на вјерне на земљи, да би сједјели са мном. Ко ходи путем правијем, тај служи мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Не живи у дому мојем који ради лукаво; који говори лаж, не стоји пред очима мојима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Јутром затирем све безбожнике на земљи, да бих истријебио из града Господњега све који чине безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Господе! чуј молитву моју, и вика моја нек изађе преда те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Немој одвратити лица својега од мене; у дан кад сам у невољи пригни к мени ухо своје, у дан кад те призивам, похитај, услиши ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Јер прођоше као дим дани моји, кости моје као топионица огорјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Покошено је као трава и посахло срце моје, да заборавих јести хљеб свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Од уздисања мојега приону кост моја за месо моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Постадох као гем у пустињи; ја сам као сова на зидинама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Не спавам, и сједим као птица без друга на крову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Сваки дан руже ме непријатељи моји, и који су се помамили на мене, мном се уклињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Једем пепео као хљеб, и пиће своје растварам сузама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Од гњева твојега и срдње твоје; јер подигавши ме бацио си ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Дани су моји као сјен, који пролази, и ја као трава осуших се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'А ти, Господе, остајеш довијека, и спомен твој од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Ти ћеш устати, смиловаћеш се на Сион, јер је вријеме смиловати се на њ, јер је дошло вријеме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Јер слугама твојим омиље и камење његово, и прах његов жале.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Тада ће се незнабошци бојати имена Господњега, и сви цареви земаљски славе његове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Јер ће Господ сазидати Сион, и јавити се у слави својој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Погледаће на молитву онијех који немају помоћи, и неће се оглушити молбе њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Написаће се ово потоњему роду, и народ наново створен хвалиће Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Што је приникао са свете висине своје, Господ погледао с неба на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Да чује уздисање сужњево, и одријеши синове смртне;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Да би казивали на Сиону име Господње и хвалу његову у Јерусалиму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Кад се скупе народи и царства да служе Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Строшио је на путу крјепост моју, скратио дане моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Рекох: Боже мој! немој ме узети у половини дана мојих. Твоје су године од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Давно си поставио земљу, и небеса су дјело руку твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'То ће проћи, а ти ћеш остати; све ће то као хаљина оветшати, као хаљину промијенићеш их и промијениће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Али ти си тај исти и године твоје неће истећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Синови ће слуга твојих живјети, и сјеме ће се њихово утврдити пред лицем твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 29, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Благосиљај, душо моја, Господа, и све што је у мени свето име његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Благосиљај, душо моја, Господа, и не заборављај ниједнога добра што ти је учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Он ти прашта све гријехе и исцјељује све болести твоје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Избавља од гроба живот твој, вјенчава те добротом и милошћу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Испуња добрим жеље твоје, понавља се као у орла младост твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Господ твори правду и суд свима којима се криво чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Показа путове своје Мојсију, синовима Израиљевим дјела своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Милостив је и добар Господ, спор на гњев и веома благ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Не гњеви се једнако, нити се довијека срди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Не поступа с нама по гријесима нашим, нити нам враћа по неправдама нашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Него колико је небо високо од земље, толика је милост његова к онима који га се боје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Колико је исток далеко од запада, толико удаљује од нас безакоња наша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Како отац жали синове, тако Господ жали оне који га се боје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Јер зна грађу нашу, опомиње се да смо прах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Дани су човјечији као трава; као цвијет у пољу, тако цвјета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Дуне вјетар на њ, и нестане га, нити ће га више познати мјесто његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Али милост Господња остаје од вијека и до вијека на онима који га се боје, и правда његова на синовима синова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'Који држе завјет његов, и памте заповијести његове, да их извршују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Господ на небесима постави пријесто свој, и царство његово свијем влада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Благосиљајте Господа анђели његови, који сте силни крјепошћу, извршујете ријеч његову слушајући глас ријечи његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Благосиљајте Господа све војске његове, слуге његове, које творите вољу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Благосиљајте Господа сва дјела његова, по свијем мјестима владе његове! Благосиљај, душо моја Господа!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Благосиљај, душо моја, Господа! Господе, Боже мој, велик си веома, обукао си се у величанство и красоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Обукао си свјетлост као хаљину, разапео небо као шатор;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Водом си покрио дворове своје, облаке начинио си да су ти кола, идеш на крилима вјетрнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Чиниш вјетрове да су ти анђели, пламен огњени да су ти слуге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Утврдио си земљу на темељима њезиним, да се не помјести на вијек вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Безданом као хаљином одјенуо си је; на горама стоје воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Од пријетње твоје бјеже, од громовнога гласа твојега теку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Излазе на горе и слазе у долине, на мјесто које си им утврдио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Поставио си међу, преко које не прелазе, и не враћају се да покрију земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Извео си изворе по долинама, између гора теку воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Напајају све звијери пољске; дивљи магарци гасе жеђу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'На њима птице небеске живе; кроз гране разлијеже се глас њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Напајаш горе с висина својих, плодима дјела твојих сити се земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Дајеш те расте трава стоци, и зелен на корист човјеку, да би изводио хљеб из земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'И вино весели срце човјеку, и лице се свијетли од уља, и хљеб срце човјеку кријепи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Сите се дрвета Божија, кедри Ливански, које си посадио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'На њима птице вију гнијезда; станак је родин на јелама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Горе високе дивокозама, камен је уточиште зечевима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Створио си мјесец да показује времена, сунце познаје запад свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Стереш таму, и бива ноћ, по којој излази све звијерје шумско;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Лавови ричу за плијеном, и траже од Бога хране себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Сунце гране, и они се сакривају и лијежу у ложе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Излази човјек на посао свој, и на рад свој до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Како је много дјела твојих, Господе! Све си премудро створио; пуна је земља блага твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Гле, море велико и широко, ту гмижу без броја, животиња мала и велика;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Ту лађе плове, крокодил, којега си створио да се игра по њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Све тебе чека, да им дајеш пићу на вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Дајеш им, примају; отвориш руку своју, сите се добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Одвратиш лице своје, жалосте се; узмеш им дух, гину, и у прах свој повраћају се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Пошљеш дух свој, постају, и понављаш лице земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Слава Господу увијек; нек се весели Господ за дјела своја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Он погледа на земљу, и она се тресе; дотакне се гора, и диме се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Пјеваћу Господу за живота својега; хвалићу Бога својега док сам год.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Нека му буде мила бесједа моја! веселићу се о Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Нека нестане грјешника са земље, и безбожника нека не буде више! Благосиљај, душо моја, Господа! Алилуја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Хвалите Господа; гласите име његово; јављајте по народима дјела његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Пјевајте му и славите га; казујте сва чудеса његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Хвалите се светијем именом његовијем; нек се весели срце онијех који траже Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Тражите Господа и силу његову, тражите лице његово без престанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Памтите чудеса његова која је учинио, знаке његове и судове уста његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Сјеме Аврамово слуге су његове, синови Јаковљеви избрани његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Он је Господ Бог наш, по свој су земљи судови његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Памти увијек завјет свој, ријеч, коју је дао на тисућу кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Што је завјетовао Авраму, и за што се клео Исаку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'То је поставио Јакову за закон, и Израиљу за завјет вјечни,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Говорећи: теби ћу дати земљу Хананску у нашљедни дио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Тада их још бијаше мало на број, бијаше их мало, и бјеху дошљаци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Иђаху од народа до народа, из једнога царства к другоме племену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Не даде никоме да им науди, и караше за њих цареве:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, '\"Не дирајте у помазанике моје, и пророцима мојим не чините зла.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'И пусти глад на ону земљу; и потр сав хљеб што је за храну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Посла пред њима човјека; у робље продан би Јосиф.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Оковима стегоше ноге његове, гвожђе тишташе душу његову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Док се стече ријеч његова, и ријеч Господња прослави га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Посла цар и одријеши га; господар над народима, и пусти га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Постави га господаром над домом својим, и заповједником над свијем што имаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Да влада над кнезовима његовијем по својој вољи, и старјешине његове уразумљује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Тада дође Израиљ у Мисир, и Јаков се пресели у земљу Хамову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'И намножи Бог народ свој и учини га јачега од непријатеља његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Преврну се срце њихово те омрзнуше на народ његов, и чинише лукавство слугама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Посла Мојсија, слугу својега, Арона избраника својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Показаше међу њима чудотворну силу његову и знаке његове у земљи Хамовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Пусти мрак и замрачи, и не противише се ријечи његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Претвори воду њихову у крв, и помори рибу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Провре земља њихова жабама, и клијети царева њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Рече, и дођоше бубине, уши по свијем крајевима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Мјесто дажда посла на њих град, живи огањ на земљу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'И поби чокоте њихове и смокве њихове, и потр дрвета у крајевима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Рече, и дођоше скакавци и гусјенице небројене;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'И изједоше сву траву по земљи њиховој, и поједоше род у пољу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'И поби све првенце у земљи њиховој, првине свакога труда њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Изведе Израиљце са сребром и златом, и не бјеше сустала у племенима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Обрадова се Мисир изласку њихову, јер страх њихов бјеше на њ пао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Разастрије им облак за покривач, и огањ да свијетли ноћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Молише, и посла им препелице, и хљебом их небеским храни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Отвори камен и протече вода, ријеке протекоше по сухој пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Јер се опомињаше свете ријечи своје к Авраму, слузи својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'И изведе народ свој у радости, избране своје у весељу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'И даде им земљу народа и труд туђинаца у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'Да би чували заповијести његове, и законе његове пазили. Алилуја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Хвалите Господа, јер је добар, јер је довијека милост његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Ко ће исказати силу Господњу? испричати сву славу његову?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Благо онима који држе истину и творе право свагда!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Опомени ме се, Господе, по својој милости к народу својему; походи ме помоћу својом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Да бих видио у добру избране твоје, веселио се у весељу народа твојега, хвалио се заједно с нашљедством твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Згријешисмо с оцима својим, постасмо кривци, безаконици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Оци наши у Мисиру не разумјеше чудеса твојих, не опомињаше се великих милости твојих, и викаше крај мора, крај Црвенога Мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Али им он поможе имена својега ради, да би показао силу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Запријети Црвеном Мору, и пресахну; и преведе их преко бездане као преко пустиње;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'И сачува их од руке ненавидникове, и избави их из руке непријатељеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Покри вода непријатеље њихове, ниједан од њих не оста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Тада вјероваше ријечима његовијем, и пјеваше му хвалу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Али брзо заборавише дјела његова, и не почекаше воље његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Полакомише се у пустињи, и стадоше кушати Бога у земљи гдје се не живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Он испуни молбу њихову, али посла погибао на душу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Позавидјеше Мојсију и Арону, којега бјеше Господ осветио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Расједе се земља, и прождрије Датана и затрпа чету Авиронову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'И спали огањ чету њихову, и пламен сажеже безбожнике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Начинише теле код Хорива, и клањаху се кипу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Мијењаху славу своју на прилику вола, који једе траву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Заборавише Бога, спаситеља својега, који је учинио велика дјела у Мисиру,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Дивна у земљи Хамовој, страшна на Црвеном Мору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'И шћаше их истријебити, да Мојсије избраник његов не стаде као у расјелини пред њим, и не одврати јарост његову да их не истријеби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Послије не марише за земљу жељену, не вјероваше ријечи његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'Побунише се у шаторима својим, не слушаше гласа Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'И он подиже руку своју на њих, да их побије у пустињи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'Да побије племе њихово међу народима, и расије их по земљама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'И присташе за Велфегором, и једоше принесено на жртву мртвима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'И расрдише Бога дјелима својим, и удари у њих погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'И устаде Финес, и умилостиви, и престаде погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'И то му се прими у правду, од кољена до кољена довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'И разгњевише Бога на води Мериви, и Мојсије пострада њих ради;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Јер дотужише духу његову, и погријеши устима својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Не истријебише народа, за које им је Господ рекао;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Него се помијешаше с незнабошцима, и научише дјела њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Стадоше служити идолима њиховијем, и они им бише замка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Синове своје и кћери своје приносише на жртву ђаволима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Проливаше крв праву; крв синова својих и кћери својих, које приношаху на жртву идолима Хананским, и оскврни се земља крвнијем дјелима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Оскврнише себе дјелима својим, и чинише прељубу поступањем својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'И плану гњев Господњи на народ његов, и омрзну му дио његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'И предаде их у руке незнабожачке, и ненавидници њихови стадоше господарити над њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Досађиваше им непријатељи њихови, и они бише покорени под власт њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Много их је пута избављао, али га они срдише намјерама својим, и бише поништени за безакоње своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Али он погледа на невољу њихову, чувши тужњаву њихову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'И опомену се завјета својега с њима, и покаја се по великој милости својој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'И учини, те их стадоше жалити сви који их беху заробили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Спаси нас, Господе Боже наш, и покупи нас из незнабожаца, да славимо свето име твоје, да се хвалимо твојом славом!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Благословен Господ Бог Израиљев од вијека и до вијека! И сав народ нека каже: амин! Алилуја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Хвалите Господа, јер је добар; јер је довијека милост његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Тако нека реку које је избавио Господ, које је избавио из руке непријатељеве,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'Скупио их из земаља, од истока и запада, од сјевера и мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Луташе по пустињи гдје се не живи, пута граду насељеноме не находише;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Бјеху гладни и жедни, и душа њихова изнемагаше у њима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Али завикаше ка Господу у тузи својој; и избави их из невоље њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'И изведе их на прав пут, који иде у град насељени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Нека хвале Господа за милост његову, и за чудеса његова ради синова људских!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Јер сити душу ташту, и душу гладну пуни добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Сједјеше у тами и у сјену смртном, оковани у тугу и у гвожђе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Јер не слушаше ријечи Божијих, и не марише за вољу вишњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Он поништи срце њихово страдањем; спотакоше се, и не бјеше ко да поможе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Али завикаше ка Господу у тузи својој, и избави их из невоље њихове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Изведе их из таме и сјена смртнога, и раскиде окове њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Нека хвале Господа за милост његову, и за чудеса његова ради синова људских!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Јер разби врата мједена, и пријеворнице гвоздене сломи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Безумници страдаше за неваљале путове своје, и за неправде своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Свако се јело гадило души њиховој, и дођоше до врата смртнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Али завикаше ка Господу у тузи својој, и избави их из невоље њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Посла ријеч своју и исцијели их, и избави их из гроба њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Нека хвале Господа за милост његову, и за чудеса његова ради синова људских!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'И нека принесу жртву за хвалу, и казују дјела његова у пјесмама!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Који плове по мору на корабљима, и раде на великим водама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'Они су видјели дјела Господња, и чудеса његова у дубини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Каже, и диже се силан вјетар, и устају вали на њему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Дижу се до небеса и спуштају до бездана: душа се њихова у невољи разлива;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Посрћу и љуљају се као пијани; све мудрости њихове нестаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Али завикаше ка Господу у тузи својој, и изведе их из невоље њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Он обраћа вјетар у тишину, и вали њихови умукну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Веселе се кад се стишају, и води их у пристаниште које желе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Нека хвале Господа за милост његову, и за чудеса његова ради синова људских!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Нека га узвишују на сабору народном, на скупштини старјешинској славе га!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Он претвара ријеке у пустињу, и изворе водене у сухоту,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'Родну земљу у слану пустару за неваљалство онијех који живе на њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Он претвара пустињу у језера, и суху земљу у изворе водене,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'И насељава онамо гладне. Они зидају градове за живљење;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Сију поља, саде винограде и сабирају љетину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Благосиља их и множе се јако, и стоке им не умаљује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Прије их бијаше мало, падаху од зла и невоље, што их стизаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Он сипа срамоту на кнезове, и оставља их да лутају по пустињи гдје нема путова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Он извлачи убогога из невоље, и племена множи као стадо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Добри виде и радују се, а свако неваљалство затискује уста своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Ко је мудар, нека запамти ово, и нека познаду милости Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Готово је срце моје, Боже; пјеваћу и хвалићу заједно са славом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Прени се псалтире и гусле, устаћу рано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Славићу тебе, Господе, по народима, појаћу теби по племенима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Јер је сврх небеса милост твоја и до облака истина твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Узвиси се више небеса, Боже, и по свој земљи нека буде слава твоја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Да би се избавили мили твоји, помози десницом својом, и услиши ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Бог рече у светињи својој: \"веселићу се, раздијелићу Сихем, и долину Сокот размјерићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Мој је Галад, мој је Манасија, Јефрем је крјепост главе моје, Јуда скиптар мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Моав је чаша из које се умивам, Едому ћу пружити обућу своју; над земљом Филистејском попијеваћу.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Ко ће ме одвести у тврди град? ко ће ме отпратити до Едома?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Зар нећеш ти, Боже, који си нас одбацио, и не идеш, Боже, с војскама нашим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Дај нам помоћ у тјескоби, обрана је човјечија узалуд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Богом смо јаки; он гази непријатеље наше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 14, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Боже, славо моја, немој мучати,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Јер се уста безбожника и уста лукава на ме отворише; говоре са мном језиком лажљивијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Ријечима злобнијем са свијех страна гоне ме, и оружају се на ме ни за што.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'За љубав моју устају на мене, а ја се молим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Враћају ми зло за добро, и мржњу за љубав моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Постави над њим старјешину безбожника, и противник нека му стане с десне стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Кад се стане судити, нека изађе крив, и молитва његова нека буде гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Нека буду дани његови кратки, и власт његову нека добије други.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Дјеца његова нек буду сироте, и жена његова удовица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Дјеца његова нек се потуцају и просе, и нека траже хљеба изван својих пустолина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Нека му узме дужник све што има, и нека разграбе туђини муку његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Нек се не нађе нико ко би га љубио, ни ко би се смиловао на сироте његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Натражје његово нек се затре, у другом кољену нека погине име њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Безакоње старијех његовијех нек се спомене у Господа, и гријех матере његове нек се не избрише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Нека буду свагда пред Господом, и он нека истријеби спомен њихов на земљи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Зато што се није сјећао чинити милост, него је гонио човјека ништега и убогога, и тужноме у срцу тражио смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Љубио је клетву, нека га и стигне; није марио за благослов, нека и отиде од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Нек се обуче у клетву као у хаљину, и она нек уђе у њега као вода, и као уље у кости његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Нек му она буде као хаљина, у коју се облачи, и као појас, којим се свагда паше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Така плата нек буде од Господа онима који ме ненавиде, и који говоре зло на душу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'А мени, Господе, Господе, учини што приличи имену твојему. Ти си добар, милошћу својом избави ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Јер сам невољан и ништ, и срце је моје рањено у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Нестаје ме као сјена, кад се одмиче; тјерају ме као скакавце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Кољена моја изнемогоше од поста, и тијело моје омрша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Постадох потсмијех њима; видећи ме машу главом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Помози ми, Господе, Боже мој, спаси ме по милости својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Нека познаду да је ово твоја рука, и ти, Господе, да си ово учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Они куну, а ти благослови; устају, али нек се постиде, и слуга се твој обрадује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Нек се противници моји обуку у срамоту, и као хаљином нек се покрију стидом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Хвалићу Господа веома устима својима, и усред многих славићу га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Јер стоји с десне стране убогоме, да би га спасао од онијех који осуђују душу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Рече Господ Господу мојему: сједи мени с десне стране, док положим непријатеље твоје за подножје ногама твојима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Скиптар силе даје ти Господ са Сиона: владај сред непријатеља својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'У дан рата твојега народ је твој готов у светој красоти. Као роса зори из утробе, така је у тебе младост твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Господ се заклео, и неће се покајати: ти си свештеник довијека по реду Мелхиседекову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Господ је теби с десне стране. Побиће у дан гњева својега цареве;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Судиће народима, напуниће земљу трупова; сатрће главу на земљи широкој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Из потока ће на путу пити, и зато ће подигнути главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Хвалим те, Господе, од свега срца на вијећу праведничком и на сабору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Велика су дјела Господња, драга свима који их љубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Дјело је његово слава и красота, и правда његова траје довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Чудеса је своја учинио да се не забораве; добар је и милостив Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Храну даје онима који га се боје, памти увијек завјет свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Силу дјела својих јавио је народу својему давши им нашљедство народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Дјела су руку његовијех истина и правда; вјерне су све заповијести његове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Тврде су за вавијек вијека, основане на истини и правди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Избављење посла народу својему; постави зававијек завјет свој. Име је његово свето, и ваља му се клањати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Почетак је мудрости страх Господњи; добра су разума сви који их творе. Хвала његова траје довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Благо човјеку који се боји Господа, коме су веома омиљеле заповијести његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Силно ће бити на земљи сјеме његово, род праведнички биће благословен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Обиље је и богатство у дому његову, и правда његова траје довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'У тами сјаје видјело праведницима од доброга, милостивога и праведнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Благо ономе који је милостив и даје у зајам! Он ће дати тврђу ријечима својим на суду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Јер неће посрнути довијека, праведник ће се спомињати увијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Не боји се зла гласа; срце је његово стално, узда се у Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Утврђено је срце његово, неће се побојати, и видјеће како падају непријатељи његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Просипа, даје убогима; правда његова траје довијека, рог се његов узвишује у слави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Безбожник види, и једи се, шкргуће зубима својим, и сахне. Жеља ће безбожницима пропасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Хвалите, слуге Господње, хвалите име Господње,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Да буде име Господње благословено отсад и довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Од истока сунчанога до запада да се слави име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Узвишен је над свима народима Господ; сврх небеса је слава његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Ко је као Господ, Бог наш, који сједи на висини;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Који се сагиба да види што је на небесима и на земљи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Који из праха подиже убогога, и из кала узвишује ништега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'И посађује га с кнезовима, с кнезовима у народу његову;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Од нероткиње насељава кућу, учинивши је радосном мајком синовима. Алилуја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Кад изађе Израиљ из Мисира, дом Јаковљев из народа туђега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Јудеја постаде светиња Божија, Израиљ област његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Море видје и побјеже; Јордан се обрати натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Горе скакаше као овнови, брдашца као јагањци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Што ти би, море, те побјеже и теби, Јордане, те се обрати натраг?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Горе, што скачете као овнови, и брдашца, као јагањци?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Пред лицем Господњим дркћи, земљо, пред лицем Бога Јаковљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Који претвара камен у језеро водено, гранит у извор водени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Не нама, Господе, не нама, него имену својему дај славу, по милости својој, по истини својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Зашто да говоре народи: гдје ли је Бог њихов?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Бог је наш на небесима, твори све што хоће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Идоли су њихови сребро и злато, дјело руку човјечијих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Уста имају, а не говоре; очи имају, а не виде;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Уши имају, а не чују; ноздрве имају, а не миришу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Руке имају, а не хватају; ноге имају, а не ходе, и не пуштају гласа из грла својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Таки су и они који их граде, и сви који се уздају у њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Доме Израиљев, уздај се у Господа; он им је помоћ и штит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Доме Аронов, уздај се у Господа; он им је помоћ и штит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Који се бојите Господа, уздајте се у Господа; он им је помоћ и штит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Господ нас се опомиње, благосиља нас, благосиља дом Израиљев, благосиља дом Аронов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Благосиља оне који се боје Господа, мале и велике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Да вам Господ умножи благослове, вама и синовима вашим!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Господ да вас благослови, творац неба и земље!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Небо је небо Господње, а земљу је дао синовима човјечијим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Неће те мртви хвалити, Господе, нити они који сиђу онамо гдје се мучи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Него ћемо ми благосиљати Господа отсад и довијека. Алилуја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Мило ми је што Господ услиши молитвени глас мој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Што пригну к мени ухо своје; и зато ћу га у све дане своје призивати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Опколише ме болести смртне, и јади паклени задесише ме, наиђох на тугу и муку;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Али призвах име Господње: Господе! избави душу моју!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Добар је Господ и праведан, и Бог је наш милостив;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Чува просте Господ; бијах у невољи, и поможе ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Врати се душо моја, у мир свој! јер је Господ добротвор твој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Ти си избавио душу моју од смрти, око моје од суза, ногу моју од спотицања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Ходићу пред лицем Господњим по земљи живијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Вјеровах кад говорих: у љутој сам невољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Рекох у сметњи својој: сваки је човјек лажа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Шта ћу вратити Господу за сва добра што ми је учинио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Узећу чашу спасења, и призваћу име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Извршићу обећања своја Господу пред свијем народом његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Скупа је пред Господом смрт светаца његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'О Господе! ја сам слуга твој, ја сам слуга твој, син слушкиње твоје; расковао си с мене окове моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Жртву за хвалу принијећу теби, и име Господње призваћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Извршићу обећања своја Господу пред свијем народом његовијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'У двору дома Господњега, усред тебе, Јерусалиме. Алилуја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Хвалите Господа сви народи, славите га сва племена;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Јер је велика милост његова к нама, и истина Господња траје довијека. Алилуја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Хвалите Господа, јер је добар, јер је довијека милост његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Нека рече Израиљ да је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Нека рече дом Аронов да је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Нека реку сви који се боје Господа да је довијека милост његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Из тјескобе повиках ка Господу и услиши ме, изведе ме на пространо мјесто Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Господ је са мном, не бојим се; шта ће ми учинити човјек?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Господ ми је помоћник: слободно ћу гледати у непријатеље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Боље је уздати се у Господа него ли се ослањати на човјека;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Боље је уздати се у Господа неголи се ослањати на кнезове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Сви ме народи опколише; али их у име Господње разбих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Оптекоше, опколише ме; али их у име Господње разбих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Опколише ме као пчеле сат, и уласише се као огањ у трњу: у име их Господње разбих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Отиснуо си ме да паднем, али ме Господ прихвати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Господ је хвала моја и пјесма; он ми постаде спаситељ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Глас радости и спасења чује се у колибама праведничким: \"десница Господња даје силу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Десница Господња узвишује, десница Господња даје силу.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Нећу умријети, него ћу жив бити, и казивати дјела Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Карајући покара ме Господ; али ме смрти не даде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Отворите ми врата од правде, ући ћу на њих, славићу Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, '\"Ево врата Господња, на која улазе праведници!\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Хвалим те, што си ме услишио, и постао ми спаситељ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Камен који одбацише зидари, поста глава од угла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'То би од Господа и дивно је у нашим очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Ево дан, који створи Господ! Радујмо се и веселимо се у њ!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'О Господе, помози! о Господе, дај да буде у напредак!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Благословен који иде у име Господње! Благосиљамо вас из дома Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Господ је Бог крјепак, и он нас обасја; жртву празничну, везану врвцама, водите к роговима жртвенику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Ти си Бог мој, тебе хвалим, Боже мој, тебе узвишујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Хвалите Господа, јер је добар, јер је милост његова довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Благо онима којима је пут чист, који ходе у закону Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Благо онима који чувају откривења његова, свијем срцем траже га;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Који не чине безакоња, ходе путовима његовијем!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Ти си дао заповијести своје, да се чувају добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Кад би путови моји били управљени да чувам наредбе твоје!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Онда се не бих постидио, пазећи на заповијести твоје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Хвалио бих те с правијем срцем, учећи се праведнијем законима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Чуваћу наредбе твоје, немој ме оставити сасвијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Како ће младић очистити пут свој? Владајући се по твојим ријечима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Свијем срцем својим тражим тебе, не дај ми да зађем од заповијести твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'У срце своје затворио сам ријеч твоју, да ти не гријешим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Благословен си, Господе! научи ме наредбама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Устима својим јављам све судове уста твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'На путу откривења твојих радујем се као за велико богатство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'О заповијестима твојим размишљам, и пазим на путове твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Наредбама твојим тјешим се, не заборављам ријечи твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Учини милост слузи својему, да бих живио и чувао ријеч твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Отвори очи моје, да бих видио чудеса закона твојега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Гост сам на земљи, немој сакрити од мене заповијести својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Изнеможе душа моја желећи без престанка познати судове твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Ти си страшан проклетим охолицама, које застрањују од заповијести твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Одврати од мене руг и срамоту, јер чувам откривења твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Сједе кнезови и договарају се на мене; а слуга твој размишља о наредбама твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Откривења су твоја утјеха моја, савјетници моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Душа моја лежи у праху; оживи ме по ријечи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Казујем путове своје, и чујеш ме; научи ме наредбама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Уразуми ме о путу заповијести својих, и размишљаћу о чудесима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Сузе пролива душа моја од туге, откријепи ме по ријечи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Пут лажни уклони од мене и закон свој даруј ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Пут истини избрах, законе твоје тражим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Прионух за откривења твоја, Господе; немој ме осрамотити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Путем заповијести твојих трчим, јер си раширио срце моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Покажи ми, Господе, пут наредаба својих, да га се држим до краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Уразуми ме, и држаћу се закона твојега, и чувати га свијем срцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Постави ме на стазу заповијести својих, јер ми је она омиљела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Превиј срце моје к откривењима својим, а не к лакомству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Одврати очи моје да не гледају ништавила, путем својим оживи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Испуни слузи својему ријеч своју да те се боји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Уклони руг мој, којега се плашим; јер су судови твоји благи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Миле су ми заповијести твоје, правдом својом оживи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Нека дође на ме милост твоја, Господе, помоћ твоја по ријечи твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'И ја ћу одговорити ономе који ме ружи; јер се уздам у ријеч твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Немој узети нигда од уста мојих ријечи истине, јер чекам судове твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'И чуваћу закон твој свагда, довијека и без престанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Ходићу слободно, јер тражим заповијести твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Говорићу о откривењима твојим пред царевима, и нећу се стидјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Тјешићу се заповијестима твојим, које љубим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Руке своје пружам к заповијестима твојим, које љубим, и размишљам о наредбама твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Опомени се ријечи своје к слузи својему, на коју си ми заповједио да се ослањам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'У невољи мојој тјеши ме што ме ријеч твоја оживљава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Охоли ми се ругају веома; али ја не отступам од закона твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Памтим судове твоје од искона, Господе, и тјешим се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Гњев ме обузима на безбожнике, који остављају закон твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Наредбе су твоје пјесма моја у путничком стану мојем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Ноћу помињем име твоје, Господе, и чувам закон твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'То је моје, да чувам заповијести твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Дио мој ти си, Господе; наумио сам чувати ријечи твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Молим ти се из свега срца, смилуј се на ме по ријечи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Разматрам путове своје, и обраћам ноге своје к откривењима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Хитим, и не затежем се чувати заповијести твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Мреже безбожничке опколише ме, али закона твојега не заборављам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'У по ноћи устајем да те славим за праведне судове твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'У заједници сам са свима који се тебе боје и који чувају заповијести твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Доброте је твоје, Господе, пуна сва земља; наредбама својим научи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Учинио си добро слузи својему, Господе, по ријечи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Доброј мисли и знању научи ме, јер заповијестима твојим вјерујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Прије страдања својега лутах, а сад чувам ријеч твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Ти си добар, и добро чиниш; научи ме наредбама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Охоли плету на мене лаж, али се ја свијем срцем држим заповијести твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Задригло је срце њихово као сало, а ја се тјешим законом твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Добро ми је што страдам, да се научим наредбама твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Милији ми је закон уста твојих него тисуће злата и сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Руке твоје створиле су ме и начиниле ме; уразуми ме, и научићу се заповијестима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Који се тебе боје, видјеће ме, и радоваће се што се уздам у твоју ријеч.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Знам да су судови твоји, Господе, праведни, и по правди ме караш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Нека буде доброта твоја утјеха моја, као што си рекао слузи својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Нека дође к мени милосрђе твоје, и оживим; јер је закон твој утјеха моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Нек се постиде охоли; јер ме без кривице оборише. Ја размишљам о заповијестима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Нек се обрате к мени који се тебе боје, и који знаду откривења твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Срце моје нека буде савршено у наредбама твојим, да се не постидим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Чезне душа моја за спасењем твојим, ријеч твоју чекам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Чезну очи моје за ријечју твојом; говорим: кад ћеш ме утјешити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Постадох као мијех у диму, али твојих наредаба не заборавих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Колико ће бити дана слуге твојега? Кад ћеш судити онима који ме гоне?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Охоли ископаше ми јаму насупрот закону твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Све су заповијести твоје истина; без кривице ме гоне, помози ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Умало ме не убише на земљи, али ја не остављам заповијести твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'По милости својој оживи ме, и чуваћу откривења уста твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Довијека је, Господе, ријеч твоја утврђена на небесима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Од кољена до кољена истина твоја; ти си поставио земљу, и стоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'По твојој наредби све стоји сад; јер све служи теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Да није закон твој био утјеха моја, погинуо бих у невољи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Заповијести твојих нећу заборавити довијека, јер ме њима оживљаваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Ја сам твој, помози ми, јер тражим заповијести твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Безбожници гледају да ме убију; а ја размишљам о твојим откривењима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Свему савршеноме видјех крај; али је заповијест твоја веома широка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Како љубим закон твој! Вас дан мислим о њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Заповијест твоја чини ме мудријега од непријатеља мојих; јер је са мном увијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Разумнији постах од свијех учитеља својих; јер размишљам о твојим откривењима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Мудрији сам од стараца; јер заповијести твоје чувам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Од свакога злога пута заустављам ноге своје, да бих чувао ријеч твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Од наредаба твојих не отступам; јер си ме ти научио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Како су слатке језику мојему ријечи твоје, слађе од меда устима мојима!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Од заповијести твојих постадох разуман; тога ради мрзим на сваки пут лажни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Ријеч је твоја жижак нози мојој, и видјело стази мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Заклех се да ћу чувати наредбе правде твоје, и извршићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Поништен сам веома, Господе, оживи ме по ријечи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Нека ти буде угодна, Господе, добровољна жртва уста мојих, и судовима својим научи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Душа је моја у руци мојој непрестано у невољи; али закона твојега не заборављам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Безбожници су ми метнули замку; али од заповијести твојих не застраних.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Присвојих откривења твоја зававијек; јер су радост срцу мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Приволио сам срце своје да твори наредбе твоје навијек, до краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Који преступају закон, ја на њих мрзим, а закон твој љубим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Ти си заклон мој и штит мој; ријеч твоју чекам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Идите од мене, безаконици! И чуваћу заповијести Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Укријепи ме по ријечи својој и бићу жив, и немој ме осрамотити у надању мом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Утврди ме, и спашћу се, и размишљаћу о наредбама твојим без престанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Обараш све који отступају од наредаба твојих; јер су помисли њихове лаж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Као гар бацаш све безбожнике на земљи; тога ради омиљеше ми откривења твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Дркће од страха твојега тијело моје, и судова твојих бојим се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Чиним суд и правду, не дај ме онима који ме гоне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Одбрани слугу својега на добро његово, да ми не чине силе охоли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Очи моје чезну за спасењем твојим и за ријечју правде твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Учини слузи својему по милости својој, и наредбама својим научи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Ја сам слуга твој; уразуми ме, и познаћу откривења твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Вријеме је да Господ ради; оборише закон твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Тога ради љубим заповијести твоје већма него злато и драго камење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Тога ради заповијести твоје држим да су вјерне, на сваки пут лажни мрзим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Дивна су откривења твоја; зато их чува душа моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Ријечи твоје кад се јаве, просвјетљују и уразумљују просте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Отворам уста своја да одахнем, јер сам жедан заповијести твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Погледај на ме и смилуј се на ме, као што радиш с онима који љубе име твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Тврди стопе моје у ријечи својој, и не дај никакоме безакоњу да облада мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Избави ме од насиља људскога, и чуваћу заповијести твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Свјетлошћу лица својега обасјај слугу својега, и научи ме наредбама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Очи моје лију потоке, зато што не чувају закона твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Праведан си, Господе, и прави су судови твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Јавио си правду у откривењима својим, и истину цијелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Ревност моја једе ме, зато што моји непријатељи заборавише ријечи твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Ријеч је твоја веома чиста, и слуга је твој веома љуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Ја сам мален и поништен, али заповијести твојих не заборављам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Правда је твоја правда вјечна, и закон твој истина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Туга и невоља нађе ме, заповијести су твоје утјеха моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Вјечна је правда у откривењима твојим; уразуми ме, и бићу жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Вичем из свега срца: услиши ме, Господе; сачуваћу наредбе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Призивам те, помози ми; држаћу се откривења твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Претјечем свануће, и вичем; ријеч твоју чекам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Претјечу очи моје јутрењу стражу, да бих размишљао о ријечи твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Чуј глас мој по милости својој, Господе; по суду својему оживи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Прикучују се који љубе безакоње; удаљили су се од закона твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Ти си близу, Господе, и све су заповијести твоје истина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Одавна знам за откривења твоја, да си их поставио зававијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Погледај невољу моју, и избави ме, јер не заборављам закона твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Прими се ствари моје, и одбрани ме; по ријечи својој оживи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Далеко је од безбожника спасење, јер се не држе наредаба твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Милосрђе је твоје, Господе, велико; по правоме суду свом оживи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Много је противника мојих и непријатеља мојих; али ја не отступам од откривења твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Видим одметнике, и мрско ми је; јер не чувају ријечи твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Гледај, како љубим заповијести твоје, Господе, по милости својој оживи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Основа је ријечи твоје истина, и вјечан је сваки суд правде твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Кнезови ме гоне ни за што, али се срце моје боји ријечи твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Радујем се ријечи твојој као онај који задобије велик плијен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Мрзим на лаж и гадим се на њу, љубим закон твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Седам пута на дан хвалим те за судове правде твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Велик мир имају они који љубе закон твој, и у њих нема спотицања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Чекам спасење твоје, Господе, и заповијести твоје извршујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Душа моја чува откривења твоја, и ја их љубим веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Чувам заповијести твоје и откривења; јер су сви путови моји пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Нека изађе тужњава моја преда те, Господе! По ријечи својој уразуми ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Нека дође мољење моје преда те! По ријечи својој избави ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Уста ће моја пјевати хвалу, кад ме научиш наредбама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Језик ће мој казивати ријеч твоју, јер су све заповијести твоје праведне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Нека ми буде рука твоја у помоћи; јер ми омиљеше заповијести твоје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Жедан сам спасења твојега, Господе, и закон је твој утјеха моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Нека живи душа моја и тебе хвали, и судови твоји нека ми помогу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Зађох као овца изгубљена: тражи слугу својега; јер заповијести твојих не заборавих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Ка Господу завиках у невољи својој, и услиши ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Господе! избави душу моју од уста лажљивијех и од језика лукавога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Шта ће ти дати и шта ће ти принијети језик лукави?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Он је као оштре стријеле у јакога, као угљевље смреково.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Тешко мени кад сам туђин код Месеха, живим код шатора Кидарских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Дуго је живјела душа моја с онима који мрзе на мир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Ја сам миран; али кад станем говорити у њих је рат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Подижем очи своје ка горама, одакле ми долази помоћ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Помоћ је мени од Господа, који је створио небо и земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Неће дати да попузне нога твоја; не дријемље чувар твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Гле, не дријемље и не спава чувар Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Господ је чувар твој, Господ је сјен твој, он ти је с десне стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Дању те неће сунце убити ни мјесец ноћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Господ ће те сачувати од свакога зла, сачуваће душу твоју Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Господ ће чувати улазак твој и излазак твој, отсад и довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Обрадовах се кад ми рекоше: хајдемо у дом Господњи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Ево, стоје ноге наше на вратима твојим, Јерусалиме!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Јерусалим је изидан, као град сливен у једну зграду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'Онамо иду племена, племена Господња, по наредби Израиљевој да славе име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Ондје стоје пријестоли судски, пријестоли дома Давидова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Иштите мира Јерусалиму; нека буде добро онима који љубе тебе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Нека буде мир око зидова твојих, и честитост у дворима твојим!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Ради браће своје, и пријатеља својих говорим: мир ти!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Ради дома Господа Бога нашега желим ти добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'К теби подижем очи своје, који живиш на небесима!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Као што су очи слугама упрте у руку господара њиховијех, као очи слушкињине у руку госпође њезине, тако су очи наше у Господа Бога нашега, док се смилује на нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Смилуј се на нас, Господе, смилуј се на нас, јер смо се довољно напитали срамоте;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Довољно се напитала душа наша руга од поноситијех, и срамоте од охолијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Да није био Господ с нама, нека рече Израиљ,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'Да није био Господ с нама, кад људи усташе на нас,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Живе би нас прождрли, кад се распали гњев њихов на нас;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Потопила би нас вода, ријека би покрила душу нашу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Покрила би душу нашу силна вода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Благословен Господ, који нас не даде зубима њиховијем да нас растржу!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Душа се наша избави као птица из замке ловачке; замка се раскиде, и ми се избависмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Помоћ је наша у имену Господњем, који је створио небо и земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Ко се узда у Господа, он је као гора Сион, не помјеша се, остаје довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Око Јерусалима су горе, и Господ је око народа својега отсад и довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Јер неће остати скиптар безбожнички над дијелом праведничким, да не би праведници пружили своје на безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Учини, Господе, добро добрима и онима који су права срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'А који сврћу на криве путе, отјераће Господ с онима који чине безакоње. Мир Израиљу!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Кад враћаше Господ робље Сионско, бијасмо као у сну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Тада уста наша бијаху пуна радости, и језик наш пјевања. Тада говораху по народима: велико дјело чини Господ на њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Велико дјело чини Господ на нама; развеселисмо се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Враћај, господе, робље наше, као потоке на сасушену земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Који су са сузама сијали, нека жању с пјевањем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Иде и плаче који носи сјеме да сије; поћи ће с пјесмом носећи снопове своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Ако Господ неће градити дома, узалуд се муче који га граде; ако неће Господ чувати града, узалуд не спава стражар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Узалуд раните, доцкан лијежете, једете хљеб уморни; миломе својему он даје сан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Ево нашљедства од Господа: дјеца, пород је дар од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Што су стријеле у руци јакоме, то су синови млади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Благо човјеку који је њима напунио тул свој! Неће се осрамотити кад се стану разговарати с непријатељима на вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Благо свакоме, који се боји Господа, који ходи путовима његовијем!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Јер ће јести од трудова руку својих. Благо теби, и добро ти је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Жена је твоја као родна лоза усред дома твојега; синови твоји као гране маслинове око стола твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Гле, тако ће бити благословен човјек који се боји Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Благословиће те Господ са Сиона, и гледаћеш добро Јерусалимско у све дане живота својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Видјећеш синове у синова својих. Мир Израиљу!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Много ми досађиваше од младости моје нека рече Израиљ,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Много ми досађиваше од младости моје, али ме не свладаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'На леђима мојим ораше орачи, и водише дуге бразде своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Господ је праведан; исијече конопце безбожничке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Постидјеће се, одбиће се сви који ненавиде Сион.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Биће као трава на крововима, која се сасушује прије него се почупа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Од које неће жетелац напунити руке своје, нити наручја своја везилац;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'И који пролазе неће рећи: \"Благослов Господњи на вама! благосиљамо вас именом Господњим.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Из дубине вичем к теби, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Господе! чуј глас мој. Нека пазе уши твоје на глас мољења мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Ако ћеш на безакоње гледати, Господе: Господе, ко ће остати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Али је у тебе праштање, да би те се бојали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Чекам Господа; чека душа моја; уздам се у ријеч његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Душа моја чека Господа већма него страже јутарње, које страже јутром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Нека чека Израиљ Господа; јер је у Господа милост, и велик је у њега откуп.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'И он ће откупити Израиља од свијех безакоња његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Господе! не надима се срце моје, нити се узносе очи моје; нити идем на велико, ни на оно што је више од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Смјеран сам и кротак душом својом, као дијете крај матере; као дијете душа је моја у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Нек се узда Израиљ у Господа отсад и довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Опомени се, Господе, Давида и све смјерности његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Како се кунијаше Господу, и завјетоваше Богу Јаковљеву:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, '\"Нећу ући у шатор дома својега, нити ћу лећи на постељу одра својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'Нећу дати сна очима својима, ни вјеђама својима дријема;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Док не нађем мјеста Господу, стана Богу Јаковљеву.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Ево, чусмо да је у Јефремовој земљи, нађосмо га на пољима Киријат-Јаримским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Уђимо у стан његов, поклонимо се подножју ногу његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Стани, Господе, на почивалишту својем, ти и ковчег силе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Свештеници твоји нек се обуку у правду, и свеци твоји нек се радују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Ради Давида слуге својега немој одвратити лица од помазаника својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Закле се Господ Давиду у истини, од које неће отступити; од порода твојега посадићу на пријестолу твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Ако синови твоји ушчувају завјет мој и откривења моја којима ћу их научити, онда ће и синови њихови довијека сједјети на пријестолу свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Јер је изабрао Господ Сион, и омиље му живјети на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Ово је почивалиште моје увијек, овдје ћу се населити; јер ми је омиљело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Храну ћу његову благословити, ниште његове наситићу хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Свештенике ћу његове обући у спасење, и свети ће се његови радовати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Ту ћу учинити да узрасте рог Давиду, поставићу видјело помазанику својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Непријатеље ћу његове обући у срамоту; а на њему ће цвјетати вијенац његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Како је лијепо и красно кад сва браћа живе заједно!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Као добро уље на глави, које се стаче на браду, браду Аронову, које се стаче на скут од хаљине његове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Као роса на Ермону, која слази на горе Сионске. јер је ондје утврдио Господ благослов и живот довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Сад благосиљајте Господа, све слуге Господње, које стојите у дому Господњем ноћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Подигните руке своје к светињи, и благосиљајте Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Благословиће те са Сиона Господ, који је створио небо и земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Хвалите име Господње, хвалите, слуге Господње,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Који стојите у дому Господњем; у дворима дома Бога нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Хвалите Господа, јер је добар Господ; појте имену његову, јер је слатко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Јер Јакова изабра себи Господ, Израиља за достојање своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Јер познах да је велик Господ, и Господ наш сврх свијех богова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Што год хоће, све Господ чини, на небесима и на земљи, у морима и у свима безданима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Изводи облаке од краја земље, муње чини усред дажда, изводи вјетар из стаја његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Он поби првенце у Мисиру од човјека до живинчета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Показа знаке и чудеса усред тебе, Мисире, на Фараону и на свијем слугама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Поби народе велике, и изгуби цареве јаке:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Сиона, цара Аморејскога и Ога, цара Васанскога, и сва царства Хананска;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'И даде земљу њихову у достојање, у достојање Израиљу, народу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Господе! име је твоје вјечно; Господе! спомен је твој од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Јер ће судити Господ народу својему, и на слуге своје смиловаће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Идоли су незнабожачки сребро и злато, дјело руку човјечијих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Уста имају, а не говоре; очи имају, а не виде;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Уши имају, а не чују; нити има дихања у устима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Какви су они онаки су и они који их граде, и сви који се уздају у њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Доме Израиљев, благосиљај Господа; доме Аронов, благосиљај Господа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Доме Левијев, благосиљај Господа; који се бојите Господа, благосиљајте Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Благословен Господ на Сиону, који живи у Јерусалиму! Алилуја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Славите Господа, јер је добар; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Славите Бога над боговима; јер је довијека милост његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Славите господара над господарима; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Онога, који један твори чудеса велика; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Који је створио небеса премудро; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Утврдио земљу на води; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Створио велика видјела; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Сунце, да управља даном; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'Мјесец и звијезде, да управљају ноћу; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Који поби Мисир у првенцима његовијем; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'Изведе из њега Израиља; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Руком крјепком и мишицом подигнутом; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Који раздвоји Црвено Море; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'И проведе Израиља кроз сред њега; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'А Фараона и војску његову врже у Море Црвено; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Преведе народ свој преко пустиње; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Поби цареве велике; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'И изгуби цареве знатне; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Сиона цара Аморејскога; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'И Ога цара Васанскога; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'И даде земљу њихову у достојање; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'У достојање Израиљу, слузи својему; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Који нас се опомену у понижењу нашем; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'И избави нас од непријатеља наших; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Који даје храну свакому тијелу; јер је довијека милост његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Славите Бога небескога; јер је довијека милост његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'На водама Вавилонским сјеђасмо и плакасмо опомињући се Сиона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'О врбама сред њега вјешасмо харфе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Ондје искаху који нас заробише да пјевамо, и који нас оборише да се веселимо: \"пјевајте нам пјесму Сионску.\"');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Како ћемо пјевати пјесму Господњу у земљи туђој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Ако заборавим тебе, Јерусалиме, нека ме заборави десница моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Нека прионе језик мој за уста моја, ако тебе не успамтим, ако не уздржим Јерусалима сврх весеља својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Напомени, Господе, синовима Едомовијем дан Јерусалимски, кад говорише: раскопајте, раскопајте га до темеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Кћери Вавилонска, крвницо, благо ономе ко ти плати за дјело које си нама учинила!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Благо ономе који узме и разбије дјецу твоју о камен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Славим те, Господе, од свега срца својега, пред боговима пјевам теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Поклањам се пред светом црквом твојом, и славим име твоје, за доброту твоју и за истину твоју; јер си по сваком имену свом подигао ријеч своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'У дан, у који зазвах, ти си ме услишио, дунуо слободу у душу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Славиће те, Господе, сви цареви земаљски, кад чују ријечи уста твојих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'И пјеваће путове Господње, јер је велика слава Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Јер је висок Господ, и види нискога, и високога издалека познаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Ако пођем у тузи, ти ћеш ме оживити; на злоћу непријатеља мојих пружићеш руку своју и заклониће ме десница твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Господ ће свршити за мене. Господе! милост је твоја довијека; дјела руку својих не остављај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Господе! ти ме кушаш и знаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Ти знаш кад сједем и кад устанем; ти знаш помисли моје издалека;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Кад ходим и кад се одмарам, ти си око мене, и све путове моје видиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Још нема ријечи на језику мом, а ти, Господе, гле, већ све знаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Састраг и спријед ти си ме заклонио, и ставио на ме руку своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Чудно је за ме знање твоје, високо, не могу да га докучим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Куда бих отишао од духа твојега, и од лица твојега куда бих утекао?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Да изађем на небо, ти си ондје. Да сиђем у пакао, ондје си.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Да се дигнем на крилима од зоре, и преселим се на крај мора:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'И ондје ће ме рука твоја водити, и држати ме десница твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Да речем: да ако ме мрак сакрије; али је и ноћ као видјело око мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Ни мрак неће замрачити од тебе, и ноћ је свијетла као дан: мрак је као видјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Јер си ти створио што је у мени, саставио си ме у утроби матере моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Хвалим те, што сам дивно саздан. Дивна су дјела твоја, и душа моја то зна добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Ниједна се кост моја није сакрила од тебе, ако и јесам саздан тајно, откан у дубини земаљској..');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Заметак мој видјеше очи твоје, у књизи је твојој све то записано, и дани забиљежени, кад их још није било ниједнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Како су ми недокучљиве помисли твоје, Боже! Како им је велик број!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Да их бројим, више их је него пијеска. Кад се пробудим, још сам с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Да хоћеш, Боже, убити безбожника! Крвопије, идите од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Они говоре ружно на тебе; узимају име твоје узалуд непријатељи твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Зар да не мрзим на оне, који на те мрзе, Господе, и да се не гадим на оне који устају на тебе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Пуном мрзошћу мрзим на њих; непријатељи су ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Окушај ме, Боже, и познај срце моје, испитај ме, и познај помисли моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'И види јесам ли на злу путу, и води ме на пут вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Избави ме, Господе, од човјека злога, сачувај ме од насилника,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Који помишљају зло у срцу и сваки дан подижу рат;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Оштре језик свој као змија, јед је аспидин у устима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Сачувај ме, Боже, од руку безбожничких, од насилника сахрани ме, који мисле да поткину ноге моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Охоли ми намјестише замке и пругла, метнуше ми мрежу на пут, пређу разапеше ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Рекох Господу: ти си Бог мој, услиши, Господе, глас мољења мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Господе, Господе, крјепки спаситељу мој, заклони главу моју у дан ратни!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Не дај, Господе, безбожнику што жели, не дај му да докучи што је наумио, да се не узносе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Отров онијех што су око мене, погибао уста њиховијех нека се обрати на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Нека падне на њих живо угљевље; нека их он баци у огањ, у пропасти, да не устану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Човјек језичан неће се утврдити на земљи, неправеднога ће злоћа увалити у погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Знам да ће Господ показати правду невољноме и правицу убогима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Да! праведни ће славити име твоје, прави ће остати пред лицем твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 14, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Господе, вичем к теби, похити к мени, чуј глас мољења мојега, кад вичем к теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Нек изађе молитва моја као кад пред лице твоје, дизање руку мојих као принос, вечерњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Постави, Господе, стражу код језика мојега, чувај врата уста мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Не дај срцу мојему да застрани на зле помисли, да чини дјела безбожна с људима који поступају неправедно; и да не окусим сладости њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Нека ме бије праведник, то је милост; нека ме кара, то је уље за главу моју; глава моја неће одбацити, ако ће и више; него је молитва моја против злоће њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Расуше се по каменијем врлетима судије њихове, и чуше ријечи моје како су благе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Као кад ко сијече и теше, тако се разлетјеше кости наше до чељусти пакленијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Али су к теби, Господе, Господе, управљене очи моје, у тебе се уздам, немој одбацити душе моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Сачувај ме од замке, коју ми метнуше, од лукавства онијех, који чине безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Пашће у мреже своје безбожници, а ја ћу један проћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Гласом својим ка Господу вичем, гласом својим Господу се молим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Изливам пред њим мољење своје, тугу своју пред њим казујем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Кад изнемогне у мени дух мој. Ти знаш стазу моју. На путу, којим ходим, сакрише ми замку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Погледам надесно, и видим да ме нико не зна; нестаде ми уточишта, нико не мари за душу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Вичем к теби, Господе; велим: ти си уточиште моје, дио мој на земљи живијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Чуј тужњаву моју; јер се мучим веома. Избави ме од онијех који ме гоне, јер су јачи од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Изведи из тамнице душу моју, да славим име твоје. Око мене ће се скупити праведници, кад ми учиниш добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 8, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Господе, услиши молитву моју, прими мољење моје по истини својој, услиши ме по правди својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'И не иди на суд са слугом својим, јер се неће оправдати пред тобом нико жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Непријатељ гони душу моју, гази у прах живот мој, посађује ме у мрак, као давно помрле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Трне у мени дух мој, нестаје у мени срца мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Помињем дане старе, пребрајам све послове твоје, размишљам о дјелима руку твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Пружам к теби руке своје; душа је моја као суха земља пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Похитај, услиши ме; Господе, нестаје духа мојега, немој одвратити лица својега од мене; јер ћу бити као они који одлазе у гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Рано ми јави милост своју, јер се у тебе уздам. Покажи ми пут, којим да идем, јер к теби подижем душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Избави ме од непријатеља мојих, Господе, к теби притјечем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Научи ме творити вољу твоју, јер си ти Бог мој; дух твој благи нека ме води по стази правој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Имена ради својега, Господе, оживи ме, по правди својој изведи из муке душу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'И по милости својој истријеби непријатеље моје, и погуби све који муче душу моју, јер сам твој слуга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Благословен Господ, град мој, који учи руке моје боју, прсте моје рату,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Добротвор мој и ограда моја, уточиште моје и избавитељ мој, штит мој, онај, у кога се уздам, који ми покорава народ мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Господе! Шта је човјек, те знаш за њ, и син смртнога, те га пазиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Човјек је као ништа; дани су његови као сјен, који пролази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Господе! Савиј небеса своја, и сиђи; дотакни се гора, и задимиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Сијевни муњом, и разагнај их; пусти стријеле своје, и распи их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Пружи руку своју с висине, избави ме и извади ме из воде велике, из руку туђинаца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Којих уста говоре ништаве ствари, и којих је десница десница лажна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Боже! пјесму нову пјеваћу ти, у псалтир од десет жица удараћу теби,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Који дајеш спасење царевима, и Давида слугу својега избављаш од љутога мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Избави ме и отми ме из руке туђинаца, којих уста говоре ништаве ствари, и којих је десница десница лажна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Синови наши нека буду као биље, које весело одрасте у младости; кћери наше као ступови прекрасно израђени у двору;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Житнице наше пуне, обилне сваким житом; овце наше нек се множе на тисуће и на сто тисућа по становима нашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Волови наши нека буду товни; нека не буду нападања, ни бјежања, ни тужњаве по улицама нашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Благо народу, у којега је све овако! Благо народу, у којега је Господ Бог!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Узвишиваћу те, Боже мој, царе мој, благосиљаћу име твоје од вијека до вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Сваки ћу те дан благосиљати, и хвалићу име твоје довијека и без престанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Велик је Господ, и ваља га славити, и величанство његово не може се досегнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Од кољена до кољена хвалиће дјела твоја, и силу твоју казивати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'О високој слави твојега величанства, и о дивним дјелима твојим размишљам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Приповиједаће силу чудеса твојих, и ја ћу величанство твоје казивати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Хвалиће велику доброту твоју и правду твоју пјеваће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Податљив је и милосрдан Господ, дуго трпи и велике је милости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Добар је Господ према свима, и жалостив на сва дјела своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Нека те славе, Господе, сва дјела твоја, и свеци твоји нека те благосиљају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Нека казују славу царства твојега, и силу твоју приповиједају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Да би јавили синовима људским силу твоју, и високу славу царства твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Царство је твоје царство свијех вијекова, и влада твоја на сва кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Господ прихвата све који падају, и исправља све погнуте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Очи су свијех к теби управљене, и ти им дајеш храну на вријеме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Отвораш руку своју, и ситиш свашта живо по жељи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Праведан је Господ у свијем путовима својим, и свет у свијем дјелима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Господ је близу свијех који га призивају, свијех, који га призивају у истини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Жељу испуња онима који га се боје, тужњаву њихову чује, и помаже им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Чува Господ све који га љубе, а безбожнике све ће истријебити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Хвалу Господу нека говоре уста моја, и нека благосиља свако тијело свето име његово увијек и без престанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Хвали, душо моја, Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Хвалићу Господа за живота својега, пјеваћу Богу својему док ме је год.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Не уздајте се у кнезове, у сина човјечијега, у којега нема помоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Изиђе из њега дух, и врати се у земљу своју: тај дан пропадну све помисли његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Благо ономе, којему је помоћник Бог Јаковљев, којему је надање у Господу, Богу његову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Који је створио небо и земљу, море и све што је у њима; који држи вјеру увијек,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Чини суд онима којима се чини криво; даје храну гладнима. Господ дријеши свезане,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Господ отвора очи слијепцима, подиже оборене, Господ љуби праведнике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Господ чува дошљаке, помаже сироти и удовици; а пут безбожнички превраћа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Господ је цар довијека, Бог твој, Сионе, од кољена до кољена. Алилуја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Хвалите Господа, јер је слатко пјевати Бога нашега, јер благоме приликује хвала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Господ зида Јерусалим, сабира расијане синове Израиљеве;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Исцјељује оне који су скрушена срца, и лијечи туге њихове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Избраја мноштво звијезда, и све их зове именом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Велик је Господ наш и велика је крјепост његова, и разуму његову нема мјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Прихвата смјерне Господ, а безбожне понижава до земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Редом пјевајте Господу хвалу, ударајте Богу нашему у гусле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Он застире небо облацима, спрема земљи дажд, чини те расте на горама трава;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Даје стоци пићу њезину, и вранићима, који вичу к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Не мари за силу коњску, нити су му мили краци човјечији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Мили су Господу они који га се боје, који се уздају у милост његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Слави, Јерусалиме, Господа; хвали Бога својега, Сионе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Јер он утврђује пријеворнице врата твојих, благосиља синове твоје у теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Ограђује међе твоје миром, насићава те једре пшенице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Шаље говор свој на земљу, брзо тече ријеч његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Даје снијег као вуну, сипа иње као пепео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Баца град свој као залогаје, пред мразом његовијем ко ће остати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Пошље ријеч своју, и све се раскрави; дуне духом својим, и потеку воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Он је јавио ријеч своју Јакову, наредбе и судове своје Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Ово није учинио ниједноме другом народу, и судова његовијех они не знају. Алилуја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Хвалите Господа на небесима, хвалите га на висини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Хвалите га, сви анђели његови, хвалите га, све војске његове!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Хвалите га, сунце и мјесече, хвалите га, све звијезде сјајне!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Хвалите га, небеса над небесима и водо над небесима!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Нека хвале име Господње, јер он заповједи и створише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Постави их засвагда и зававијек, даде наредбу, која неће проћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Хвалите Господа на земљи, велике рибе и све бездане;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Огањ и град, снијег и магла, вјетар силни, који извршује ријеч његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Горе и сви хумови, родна дрвета и сви кедри,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Звијери и сва стока, бубине и птице крилате,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Цареви земаљски и сви народи, кнезови и све судије земаљске,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Момци и дјевојке, старци и дјеца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Нека хвале име Господње; јер је само његово име узвишено, слава његова на земљи и на небу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Он је узвисио рог народа својега, славу свијех светаца својих, синова Израиљевих, народа који је близу њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Појте Господу пјесму нову; хвала да му је на сабору светијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Нека се весели Израиљ о створитељу свом, синови Сионски нек се радују о цару свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Нека хвале име његово покликујући, у бубањ и гусле нека му ударају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Јер је мио Господу народ његов, украшава смјерне спасавајући их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Нек се веселе свеци у слави, и нек се радују на постељама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Слава је Божија у устима њиховијем, и мач с обје стране оштар у руци њиховој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Да се освете народима, и покарају племена;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Да свежу цареве њихове у ланце, и властелу њихову у окове гвоздене,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'И изврше на њима написани суд. Ова је част свима свецима његовијем. Алилуја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Хвалите Бога у светињи његовој, хвалите га на тврђи славе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Хвалите га према сили његовој, хвалите га према високоме величанству његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Хвалите га уз глас трубни, хвалите га уз псалтир и гусле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Хвалите га с бубњем и весељем, хвалите га уз жице и орган.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Хвалите га уз јасне кимвале, хвалите га уз кимвале громовне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Све што дише нека хвали Господа! Алилуја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Приче Соломуна сина Давидова, цара Израиљева,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Да се познаје мудрост и настава, да се разумију ријечи разумне,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Да се прима настава у разуму, у правди, у суду и у свему што је право,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Да се даје лудима разборитост, младићима знање и помњивост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Мудар ће слушати и више ће знати, и разуман ће стећи мудрост,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Да разумије приче и значење, ријечи мудријех људи и загонетке њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Почетак је мудрости страх Господњи; луди презиру мудрост и наставу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Слушај, сине, наставу оца својега, и не остављај науке матере своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Јер ће бити вијенац од милина око главе твоје, и гривна на грлу твом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Сине мој, ако би те мамили грјешници, не пристај;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Ако би рекли: ходи с нама да вребамо крв, да засједамо правоме ни за што;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Прождријећемо их као гроб живе, и свеколике као оне који слазе у јаму;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Свакојакога блага добићемо, напунићемо куће своје плијена;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Бацаћеш ждријеб свој с нама; један ће нам тоболац бити свјема;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Сине мој, не иди на пут с њима, чувај ногу своју од стазе њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Јер ногама својим трче на зло и хите да прољевају крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Јер се узалуд разапиње мрежа на очи свакој птици;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'А они вребају своју крв и засједају својој души.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Таки су путови свијех лакомијех на добитак, који узима душу својим господарима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Премудрост виче на пољу, на улицама пушта глас свој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'У највећој вреви виче, на вратима, у граду говори своје бесједе:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Луди, докле ћете љубити лудост? и потсмјевачима докле ће бити мио потсмијех? и безумни докле ће мрзити на знање?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Обратите се на карање моје; ево, изасућу вам дух свој, казаћу вам ријечи своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Што звах, али не хтјесте, пружах руку своју, али нико не мари,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'Него одбацисте сваки савјет мој, и карања мојега не хтјесте примити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Зато ћу се и ја смијати вашој невољи, ругаћу се кад дође чега се бојите;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'Кад као пустош дође чега се бојите, и погибао ваша као олуја кад дође, кад навали на вас невоља и мука.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Тада ће ме звати, али се нећу одазвати; рано ће тражити, али ме неће наћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Јер мрзише на знање, и страха Господњега не изабраше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Не присташе на мој свјет, и презираше сва карања моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Зато ће јести плод од путова својих, и наситиће се савјета својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Јер ће луде убити мир њихов, и безумне ће погубити срећа њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Али ко ме слуша, боравиће безбрижно, и биће на миру не бојећи се зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Сине мој, ако примиш ријечи моје, и заповијести моје сахраниш код себе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'Да пази ухо твоје на мудрост, и пригнеш срце своје к разуму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Ако призовеш мудрост, и к разуму подигнеш глас свој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Ако га устражиш као сребро, и као сакривено благо ако добро устражиш;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Тада ћеш разумјети страх Господњи, и познање Божије наћи ћеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Јер Господ даје мудрост, из његовијех уста долази знање и разум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Чува правима што доиста јест, штит је онима који ходе у безазлености,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Да би се држали стаза правијех, а он чува пут светаца својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Тада ћеш разумјети правду и суд и што је право, и сваки добри пут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Кад дође мудрост у срце твоје, и знање омили души твојој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Помњивост ће пазити на те, разум ће те чувати,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Избављајући те од зла пута, од људи који говоре опаке ствари,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'Који остављају праве путе да иду путовима мрачнијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'Који се радују зло чинећи, и играју у злијем опачинама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'Којих су путови криви, и сами су опаки на стазама својим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Избављајући те од жене туђе, од туђинке, која ласка својим ријечима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'Која оставља вођа младости своје, и заборавља завјет Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Јер к смрти води дом њезин, и к мртвима стазе њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Ко год уђе к њој не враћа се, нити излази на пут животни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Зато ходи путем добријех, и држи се стаза праведничких.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Јер ће праведници наставати на земљи, и безазлени ће остати на њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'А безбожни ће се истријебити са земље, и безаконици ће се ишчупати из ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Сине мој, не заборављај науке моје, и заповијести моје нека хране срце твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Јер ће ти донијети дуг живот, добре године и мир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Милост и истина нека те не оставља; привежи их себи на грло, упиши их на плочи срца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Те ћеш наћи милост и добру мисао пред Богом и пред људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Уздај се у Господа свијем срцем својим, а на свој разум не ослањај се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'На свијем путовима својим имај га на уму, и он ће управљати стазе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Не мисли сам о себи да си мудар; бој се Господа и уклањај се ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'То ће бити здравље пупку твојему и заљевање костима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Поштуј Господа имањем својим и првинама од свега дохотка својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'И биће пуне житнице твоје обиља, и пресипаће се вино из каца твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Сине мој, не одбацуј наставе Господње, и немој да ти досади карање његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Јер кога љуби Господ онога кара, и као отац сина који му је мио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Благо човјеку који нађе мудрост, и човјеку који добије разум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Јер је боље њом трговати него трговати сребром, и добитак на њој бољи је од злата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Скупља је од драгога камења, и што је год најмилијих ствари твојих не могу се изједначити с њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Дуг живот у десници јој је, а у љевици богатство и слава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Пути су њезини мили пути и све стазе њезине мирне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Дрво је животно онима који се хватају за њу, и ко је год држи срећан је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Господ је мудрошћу основао земљу, утврдио небеса разумом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Његовом мудрошћу развалише се бездане и облаци капљу росом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Сине мој, да ти то не одлази из очију; чувај праву мудрост и разборитост;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'И биће живот души твојој и накит грлу твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Тада ћеш ићи без бриге путем својим, и нога твоја неће се спотаћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Кад лијежеш, нећеш се плашити, и кад почиваш, сладак ће ти бити сан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Нећеш се плашити од нагле страхоте ни од погибли безбожничке кад дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Јер ће ти Господ бити узданица и чуваће ти ногу да се не ухвати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Не одреци добра онима којима треба, кад можеш учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Не говори ближњему својему: иди, и дођи други пут, и сјутра ћу ти дати, кад имаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Не куј зла ближњему својему који живи с тобом без бриге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Не свађај се ни с ким без узрока, ако ти није учинио зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Немој завидјети насилнику, ни изабрати којега пута његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Јер је мрзак Господу зликовац, а у праведних је тајна његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Проклетство је Господње у кући безбожниковој, а стан праведнички благосиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Јер потсмјевачима он се потсмијева, а кроткима даје милост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Мудри ће наслиједити славу, а безумнике ће однијети срамота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Слушајте, дјецо, наставу очину, и пазите да бисте познали мудрост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Јер вам добру науку дајем, не остављајте закона мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Кад бијах син у оца својега млад, и јединац у матере своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Он ме учаше и говораше ми: нека прими срце твоје ријечи моје, држи заповијести моје и бићеш жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Прибави мудрост, прибави разум; не заборављај и не отступај од ријечи уста мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Немој је оставити, и чуваће те, љуби је, и храниће те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Мудрост је главно; прибави мудрост, и за све имање своје прибави разум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Подижи је и она ће те узвисити, прославиће те кад је загрлиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Метнуће ти на главу вијенац од милина, красну круну даће ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Слушај, сине мој, и прими ријечи моје, и умножиће ти се године животу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Учим те путу мудрости, водим те стазама правијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Кад усходиш, неће се стезати кораци твоји, и ако потрчиш нећеш се спотакнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Држи се наставе и не пуштај, чувај је, јер ти је живот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Не иди на стазу безбожничку и путем неваљалијех људи не ступај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Остави га, не ходи по њему, уклони се од њега и мини га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Јер не спавају ако не учине зла, и не долази им сан ако кога не оборе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Јер једу хљеб безбожности и пију вино насиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'А пут је праведнички као свијетло видјело, које све већма свијетли док не буде прави дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'А пут је безбожнички као мрак, не знају на што ће се спотакнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Сине мој, слушај ријечи моје, пригни ухо своје бесједи мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Да ти не одлазе из очију; чувај их усред срца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Јер су живот онима који их налазе и здравље свему тијелу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Сврх свега што се чува чувај срце своје, јер из њега излази живот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Уклони од уста својих опачину и од усана својих неваљалство удаљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Очи твоје нека гледају управо и вјеђе твоје нека се управљају право пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Мјери стазу ногама својим, и сви путови твоји нека су поравњени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Не сврћи ни надесно ни налијево, одвраћај ногу своју ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Сине мој, слушај мудрост моју, к разуму мојему пригни ухо своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Да се држиш разборитости, и усне твоје да хране знање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Јер с усана туђе жене капље мед, и грло јој је мекше од уља;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Али јој је пошљедак горак као пелен, оштар као мач с обје стране оштар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Ноге јој слазе к смрти, до пакла допиру кораци њезини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Да не би мјерио пута животнога, савијају се стазе њезине да не знаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Зато, дјецо, послушајте мене, и не отступајте од ријечи уста мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Нека је далеко од ње пут твој, и не приближуј се к вратима куће њезине,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Да не би дао другима славе своје и година својих немилостивоме,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'Да се не би туђинци наситили твојега блага и труд твој да не би био у туђој кући,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'И да не ридаш на пошљедак, кад се строши месо твоје и тијело твоје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'И речеш: како мрзих на наставу, и како срце моје презира карање!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'И не послушах гласа учитеља својих, и не пригнух уха својега к онима који ме учаху!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Умало не западох у свако зло усред збора и скупштине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Пиј воду из својега студенца и што тече из твојега извора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Нека се разливају твоји извори на поље, и потоци по улицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Имај их сам за се, а не туђин с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Благословен да је извор твој, и весели се женом младости своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Нека ти је као кошута мила и као срна љупка; дојке њезине нека те опијају у свако доба, у љубави њезиној посрћи једнако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'А зашто би, сине, посртао за туђинком и голио њедра туђој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Кад су пред очима Господу путови свачији, и мјери све стазе његове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Безбожника ће ухватити његова безакоња, и у ужа гријеха својих заплешће се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Умријеће без наставе, и од мноштва лудости своје лутаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Сине мој, кад се подјемчиш за пријатеља својега, и даш руку своју туђинцу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Везао си се ријечима уста својих, ухватио си се ријечима уста својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Зато учини тако, сине мој, и опрости се, јер си допао у руке ближњему својему; иди, припадни, и навали на ближњега својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Не дај сна очима својима, ни вјеђама својима дријема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Отми се као срна из руке ловцу, и као птица из руке птичару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Иди к мраву, љенивче, гледај путове његове, и омудрај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Нема вођа ни управитеља ни господара;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'И опет приправља љети себи храну, збира уз жетву пићу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Докле ћеш, љенивче, лежати? кад ћеш устати од сна својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Док мало проспаваш, док мало продријемљеш, док мало склопиш руке да прилегнеш,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'Утом ће доћи сиромаштво твоје као путник и оскудица твоја као оружан човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Човјек неваљао и нитков ходи са злијем устима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Намигује очима, говори ногама, показује прстима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Свака му је опачина у срцу, кује зло свагда, замеће свађу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Зато ће уједанпут доћи погибао његова, часом ће се сатрти и неће бити лијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'На ово шесторо мрзи Господ, и седмо је гад души његовој:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Очи поносите, језик лажљив и руке које прољевају крв праву,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Срце које кује зле мисли, ноге које брзо трче на зло,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'Лажан свједок који говори лаж, и ко замеће свађу међу браћом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Чувај, сине мој, заповијест оца својега, и не остављај науке матере своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Привежи их себи на срце засвагда, и спучи их себи око грла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Куда год пођеш, водиће те; кад заспиш, чуваће те; кад се пробудиш, разговараће те;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Јер је заповијест жижак, и наука је видјело, и пут је животни карање које поучава;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Да те чувају од зле жене, од језика којим ласка жена туђа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Не зажели у срцу свом љепоте њезине, и немој да те ухвати вјеђама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Јер са жене курве спада човјек на комад хљеба, и жена пуста лови драгоцјену душу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Хоће ли ко узети огња у њедра а хаљине да му се не упале?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Хоће ли ко ходити по живом угљевљу а ногу да не ожеже?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Тако бива ономе који иде к жени ближњега својега; неће бити без кривице ко је се год дотакне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Не срамоте лупежа који украде да насити душу своју, будући гладан;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Него кад га ухвате плати самоседмо, да све имање дома својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Али ко учини прељубу са женом, безуман је, душу своју губи ко тако чини;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Муке и руга допада, и срамота се његова не може избрисати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Јер је љубавна сумња жестока у мужа и не штеди на дан освете;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Не мари ни за какав откуп, и не прима ако ћеш и много дарова давати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Сине, чувај ријечи моје, и заповијести моје сахрани код себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Чувај заповијести моје и бићеш жив, и науку моју као зјеницу очију својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Привежи их себи на прсте, напиши их на плочи срца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Реци мудрости: сестра си ми; и пријатељицом зови разборитост,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Да би те чувала од жене туђе, од туђинке, која ласка ријечима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Јер с прозора дома својега кроз решетку гледах,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'И видјех међу лудима, опазих међу дјецом безумна младића,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Који иђаше улицом покрај угла њезина, и корачаше путем ка кући њезиној,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'У сумрак, увече, кад се уноћа и смрче;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'А гле, срете га жена у одијелу курвинском и лукава срца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Плаха и пуста, којој ноге не могу стајати код куће,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Сад на пољу, сад на улици, код свакога угла вребаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'И ухвати га, и пољуби га, и безобразно рече му:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Имам жртве захвалне, данас изврших завјете своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Зато ти изидох на сусрет да те тражим, и нађох те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Настрла сам одар свој покривачим везенијем и простиркама Мисирским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Окадила сам постељу своју смирном, алојем и циметом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Хајде да се опијамо љубављу до зоре, да се веселимо миловањем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Јер ми муж није код куће, отишао је на пут даљни,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Узео је са собом тоболац новчани, вратиће се кући у одређени дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Наврати га многим ријечима, глатким уснама одвуче га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Отиде за њом одмах као што во иде на клање и као безумник у путо да буде каран,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'Докле му стријела не пробије јетру, као што птица лети у замку не знајући да јој је о живот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Зато дакле, дјецо, послушајте ме, и пазите на ријечи уста мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Немој да застрањује срце твоје не путове њезине, немој лутати по стазама њезинијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Јер је многе ранила и оборила, и много је онијех које је све побила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Кућа је њезина пут паклени који води у клијети смртне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Не виче ли мудрост? и разум не пушта ли глас свој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Наврх висина, на путу, на распутицама стоји,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Код врата, на уласку у град, гдје се отворају врата, виче:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Вас вичем, о људи, и глас свој обраћам к синовима људским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Научите се луди мудрости, и безумни оразумите се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Слушајте, јер ћу говорити велике ствари, и усне моје отворајући се казиваће што је право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Јер уста моја говоре истину, и мрска је уснама мојим безбожност.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Праве су све ријечи уста мојих, ништа нема у њима криво ни изопачено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Све су обичне разумному и праве су онима који налазе знање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Примите наставу моју а не сребро, и знање радије него најбоље злато.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Јер је боља мудрост од драгога камења, и што је год најмилијих ствари не могу се изједначити с њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Ја мудрост боравим с разборитошћу, и разумно знање налазим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Страх је Господњи мржња на зло; ја мрзим на поноситост и на охолост и на зли пут и на уста опака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Мој је савјет и што год јест; ја сам разум и моја је сила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Мном цареви царују, и владаоци постављају правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Мном владају кнезови и поглавари и све судије земаљске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Ја љубим оне који мене љубе, и који ме добро траже налазе ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'У мене је богатство и слава, постојано добро и правда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Плод је мој бољи од злата и од најбољега злата, и добитак је мој бољи и од најбољега сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Путем праведнијем ходим, посред стаза правице,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Да онима који ме љубе дам оно што јест, и ризнице њихове да напуним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Господ ме је имао у почетку пута својега, прије дјела својих, прије свакога времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Прије вијекова постављена сам, прије почетка, прије постања земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Кад јоште не бијаше бездана, родила сам се, кад још не бијаше извора обилатијех водом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Прије него се горе основаше, прије хумова ја сам се родила;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Још не бјеше начинио земље ни поља ни почетка праху васиљенском;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Кад је уређивао небеса, ондје бијах; кад је размјеравао круг над безданом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Кад је утврђивао облаке горе и кријепио изворе бездану;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Кад је постављао мору међу и водама да не преступају заповијести његове, кад је постављао темеље земљи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Тада бијах код њега храњеница, бијах му милина сваки дан, и весељах се пред њим свагда;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Весељах се на васиљеној његовој, и милина ми је са синовима људским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Тако дакле, синови, послушајте ме, јер благо онима који се држе путова мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Слушајте наставу, и будите мудри, и немојте је одбацити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Благо човјеку који ме слуша стражећи на вратима мојим сваки дан и чувајући прагове врата мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Јер ко мене налази, налази живот и добија љубав од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'А ко о мене гријеши, чини криво души својој; сви који мрзе на ме, љубе смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Премудрост сазида себи кућу, и отеса седам ступова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Покла стоку своју, раствори вино своје, и постави сто свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Посла дјевојке своје, те зове сврх висина градских:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Ко је луд, нека се уврати овамо. И безумнима вели:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Ходите, једите хљеба мојега, и пијте вина које сам растворила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Оставите лудост и бићете живи, и идите путем разума.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Ко учи потсмјевача, прима срамоту; и ко кори безбожника, прима руг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Не карај потсмјевача да не омрзне на те; карај мудра, и љубиће те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Кажи мудроме, и биће још мудрији; поучи праведнога, и знаће више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Почетак је мудрости страх Господњи, и знање је светијех ствари разум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Јер ће се мном умножити дани твоји и додаће ти се године животу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Ако будеш мудар, себи ћеш бити мудар; ако ли будеш потсмјевач, сам ћеш теглити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Жена безумна плаха је, луда и ништа не зна;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'И сједи на вратима од куће своје на столици, на висинама градским,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Те виче оне који пролазе, који иду право својим путем:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Ко је луд? нека се уврати овамо. И безумноме говори:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'Вода је крадена слатка, и хљеб је сакривен угодан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'А он не зна да су ондје мртваци и у дубоком гробу да су званице њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Мудар је син радост оцу својему, а луд је син жалост матери својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Не помаже неправедно благо, него правда избавља од смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Не да Господ да гладује душа праведникова, а имање безбожничко размеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Немарна рука осиромашава, а вриједна рука обогаћава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Ко збира у љето, син је разуман; ко спава о жетви, син је срамотан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Благослови су над главом праведнику, а уста безбожничка покрива насиље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Спомен праведников остаје благословен, а име безбожничко трухне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Ко је мудра срца, прима заповијести; а ко је лудијех усана, пашће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Ко ходи безазлено, ходи поуздано; а ко је опак на путовима својим, познаће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Ко намигује оком, даје муку; и ко је лудијех усана, пашће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Уста су праведникова извор животу, а уста безбожничка покрива насиље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Мрзост замеће свађе, а љубав прикрива све пријеступе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'На уснама разумнога налази се мудрост, а за леђа је безумнога батина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Мудри склањају знање, а уста лудога близу су погибли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Богатство је богатима тврд град, сиромаштво је сиромасима погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Рад је праведников на живот, добитак безбожников на гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Ко прима наставу, на путу је к животу; а ко одбацује кар, лута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Ко покрива мржњу, лажљивих је усана; и ко износи срамоту безуман је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'У многим ријечима не бива без гријеха; али ко задржава усне своје, разуман је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Језик је праведников сребро одабрано; срце безбожничко не вриједи ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Усне праведникове пасу многе, а безумни умиру с безумља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Благослов Господњи обогаћава а без муке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Безумнику је шала чинити зло, а разуман човјек држи се мудрости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Чега се боји безбожник, оно ће га снаћи; а што праведници желе Бог ће им дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Као што пролази олуја, тако безбожника нестаје; а праведник је на вјечитом темељу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Какав је оцат зубима и дим очима, таки је љенивац онима који га шаљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Страх Господњи додаје дане, а безбожницима се године прекраћују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Чекање праведнијех радост је, а надање безбожнијех пропада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Пут је Господњи крјепост безазленому, а страх онима који чине безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Праведник се неће нигда поколебати, а безбожници неће наставати на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Уста праведникова износе мудрост, а језик опаки истријебиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Усне праведникове знају што је мило, а безбожничка су уста опачина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Лажна су мјерила мрска Господу, а права мјера угодна му је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Кад дође охолост, дође и срамота; а у смјернијех је мудрост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Праведне води безазленост њихова, а безаконике сатире злоћа њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Неће помоћи богатство у дан гњева, а правда избавља од смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Правда безазленога управља пут његов, а безбожник пада од своје безбожности.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Праведне избавља правда њихова, а безаконици хватају се у својој злоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Кад умире безбожник, пропада надање, и најјаче уздање пропада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Праведник се избавља из невоље, а безбожник долази на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Лицемјер квари устима ближњега својега; али се праведници избављају знањем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Добру праведнијех радује се град; а кад пропадају безбожници, бива пјевање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Благословима праведнијех људи подиже се град, а с уста безбожничких раскопава се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Безумник се руга ближњему својему, а разуман човјек мучи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Опадач тумарајући издаје тајну; а ко је вјерна срца, таји ствар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Гдје нема савјета, пропада народ, а помоћ је у мноштву савјетника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Зло пролази ко се јамчи за туђина; а ко мрзи на јамство, без бриге је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Жена мила добија част, а силни добијају богатство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Милостив човјек чини добро души својој, а немилостив уди својему тијелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Безбожни ради посао пријеваран; а ко сије правду, поуздана му је плата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Ко се држи правде, на живот му је; а ко иде за злом, на смрт му је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Мрски су Господу који су опака срца; а мили су му који су безазлени на свом путу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Зао човјек неће остати без кара ако и друге узме у помоћ; а сјеме праведнијех избавиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Жена лијепа а без разума златна је брњица у губици свињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Жеља је праведнијех само добро, а очекивање безбожнијех гњев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Један просипа, и све више има; а други тврдује сувише, и све је сиромашнији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Подашна рука бива богатија, и ко напаја, сам ће бити напојен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Ко не да жита, проклиње га народ, а ко продаје, благослов му је над главом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Ко тражи добро, добија љубав; а ко тражи зло, задесиће га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Ко се узда у богатство своје, пропашће; а праведници ће се као грана зелењети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Ко затире кућу своју, наслиједиће вјетар; и безумник ће служити мудрому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Плод је праведников дрво животно, и мудри обучава душе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Гле, праведнику се на земљи плаћа, акамоли безбожнику и гријешнику?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Ко љуби наставу, љуби знање; а ко мрзи на укор, остаје луд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Добар човјек добија љубав од Господа, а човјека зликовца осуђује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Неће се човјек утврдити безбожношћу, а коријен праведнијех неће се помаћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Вриједна је жена вијенац мужу својему; а која га срамоти, она му је као трулеж у костима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Мисли су праведнијех праве, а савјети безбожнијех пријевара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Ријечи безбожнијех вребају крв, а праведне избављају уста њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Обарају се безбожни да их нема, а дом праведнијех остаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Према разуму свом хвали се човјек; а ко је опака срца, презреће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Ко се снебива, а има слугу, бољи је од онога који се велича а хљеба нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Праведник се брине за живот својега живинчета, а у безбожника је срце немилостиво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Ко ради своју земљу, биће сит хљеба; а ко иде за беспослицама, безуман је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Безбожник жели обрану ода зла, али коријен праведнијех даје је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Зломе је замка у гријеху усана његовијех, а праведник излази из тјескобе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Од плода уста својих сити се човјек добра, и плату за дјела своја прима човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Безумнику се чини прав пут његов; али ко слуша савјет, мудар је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Гњев безумников одмах се позна, али паметни покрива срамоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Ко говори истину, јавља што је право, а лажни свједок пријевару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Има ко говори као да мач пробада, а језик је мудријех лијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Истинита уста стоје тврдо довијека, а језик лажљиви за час.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Који зло мисле, пријевара им је у срцу, а радост је онима који свјетују на мир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Никаква несрећа неће задесити праведника, а безбожници ће се напунити зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Мрске су Господу лажљиве усне; а који раде вјерно, мили су му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Паметан човјек покрива знање, а срце безумнијех разглашује безумље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Рука радљива господариће, а лијена ће давати данак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Брига у срцу човјечијем обара; а добра ријеч развесељава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Праведнику је боље него ближњему његову; а безбожнике заводи пут њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Љенивац неће пећи лова свога, а у вриједна је човјека добро драгоцјено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'На путу правде живот је, и куда иде стаза њезина нема смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Мудар син слуша наставу оца својега; а потсмјевач не слуша укора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Од плода уста својих сваки ће јести добро, а душа неваљалијех људи насиље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Ко чува уста своја, чува своју душу; ко разваљује усне, пропада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Жељна је душа љенивчева, али нема ништа; а душа вриједнијех људи обогатиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'На лажну ријеч мрзи праведник; а безбожник се мрази и срамоти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Правда чува онога који ходи безазлено; а безбожност обара грјешника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Има ко се гради богат а нема ништа, и ко се гради сиромах а има велико благо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Откуп је за живот човјеку богатство његово, а сиромах не слуша пријетње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Видјело праведничко свијетли се, а жижак безбожнички угасиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Од охолости бива само свађа, а који примају свјет, у њих је мудрост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Благо које се таштином тече умаљава се, а ко сабира руком, умножава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Дуго надање мори срце, и жеља је испуњена дрво животно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Ко презире ријеч сам себи уди; а ко се боји заповијести, платиће му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Наука је мудрога извор животни да се сачува пругала смртнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Добар разум даје љубав, а пут је безаконички храпав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Сваки паметан човјек ради с разумом, а безуман разноси безумље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Гласник безбожан пада у зло, а вјеран је посланик лијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Сиромаштво и срамота доћи ће на онога који одбацује наставу; а ко чува карање, прославиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Испуњена је жеља сласт души, а безумнима је мрско отступити ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Ко ходи с мудрима постаје мудар, а ко се држи с безумницима постаје гори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Грјешнике гони зло, а праведницима се враћа добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Добар човјек оставља нашљедство синовима синова својих, а грјешниково имање чува се праведнику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Изобила хране има на њиви сиромашкој, а има ко пропада са зле управе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Ко жали прут, мрзи на сина својега; а ко га љуби, кара га за времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Праведник једе, и сита му је душа; а трбух безбожницима нема доста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Мудра жена зида кућу своју, а луда својим рукама раскопава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Ко ходи право, боји се Господа; а ко је опак на својим путовима, презире га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'У устима је безбожниковијем прут охолости, а мудре чувају уста њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Гдје нема волова, чисте су јасле; а обилата је љетина од силе воловске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Истинит свједок не лаже, а лажан свједок говори лаж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Потсмјевач тражи мудрост, и не находи је; а разумному је знање лако наћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Иди од човјека безумна, јер нећеш чути паметне ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Мудрост је паметнога да пази на пут свој, а безумље је безумнијех пријевара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Безумнима је шала гријех, а међу праведнима је добра воља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Срце свачије зна јад душе своје; и у весеље његово не мијеша се други.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Дом безбожнички раскопаће се, а колиба праведнијех цвјетаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Неки се пут чини човјеку прав, а крај му је пут к смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'И од смијеха боли срце, и весељу крај бива жалост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Путова својих наситиће се ко је изопачена срца, али га се клони човјек добар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Луд вјерује свашта, а паметан пази на своје кораке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Мудар се боји и уклања се од зла, а безуман навире и слободан је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Нагао човјек чини безумље, а пакостан је човјек мрзак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Луди нашљеђује безумље, а разборити вјенчава се знањем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Клањају се зли пред добрима и безбожни на вратима праведнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Убоги је мрзак и пријатељу свом, а богати имају много пријатеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Ко презире ближњега својега гријеши; а ко је милостив убогима, благо њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Који смишљају зло, не лутају ли? а милост и вјера биће онима који смишљају добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'У сваком труду има добитка, а говор уснама само је сиромаштво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Мудрима је вијенац богатство њихово, а безумље безумнијех остаје безумље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Истинит свједок избавља душе, а лажан говори пријевару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'У страху је Господњем јако поуздање, и синовима је уточиште.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Страх је Господњи извор животу да се човјек сачува од пругала смртнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'У мноштву је народа слава цару; а кад нестаје народа, пропаст је владаоцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Ко је спор на гњев, велика је разума; а ко је нагао показује лудост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Живот је тијелу срце здраво, а завист је трулеж у костима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Ко чини криво убогоме, срамоти створитеља његова; а поштује га ко је милостив сиромаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'За зло своје повргнуће се безбожник, а праведник нада се и на смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Мудрост почива у срцу разумна човјека, а што је у безумнима познаје се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Правда подиже народ, а гријех је срамота народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Мио је цару разуман слуга, али на срамотна гњеви се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Одговор благ утишава гњев, а ријеч пријека подиже срдњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Језик мудријех људи украшава знање, а уста безумнијех просипају безумље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Очи су Господње на сваком мјесту гледајући зле и добре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Здрав је језик дрво животно, а опачина с њега кршење од вјетра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Луд се руга наставом оца својега; а ко прима укор бива паметан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'У кући праведниковој има много блага; а у дохотку је безбожникову расап.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Усне мудријех људи сију знање, а срце безумничко не чини тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Жртва је безбожничка гад Господу, а молитва праведнијех угодна му је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Гад је Господу пут безбожников; а ко иде за правдом, њега љуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Карање је зло ономе ко оставља пут; који мрзи на укор, умријеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Пакао је и погибао пред Господом, акамоли срца синова човјечијих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Потсмјевач не љуби онога ко га кори, нити иде к мудрима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Весело срце весели лице, а жалост у срцу обара дух.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Срце разумно тражи знање, а уста безумнијех људи наслађују се безумљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Сви су дани невољникови зли; а ко је весела срца, на гозби је једнако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Боље је мало са страхом Господњим него велико благо с немиром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Боље је јело од зеља гдје је љубав него од вола угојена гдје је мржња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Човјек гњевљив замеће распру; а ко је спор на гњев, утишава свађу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Пут је лијенога као ограда од трња, а стаза је праведнијех насута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Мудар је син радост оцу, а човјек безуман презире матер своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Безумље је радост безумнику, а разуман човјек ходи право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Намјере се расипају кад нема савјета, а тврдо стоје гдје је много савјетника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Радује се човјек одговором уста својих, и ријеч у вријеме како је добра!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Пут к животу иде горе разумноме да се сачува од пакла оздо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Господ раскопава кућу поноситима, а међу удовици утврђује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Мрске су Господу мисли зле, а бесједе чистијех миле су.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Лакомац затире своју кућу, а ко мрзи на поклоне жив ће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Срце праведниково премишља шта ће говорити, а уста безбожничка ригају зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Далеко је Господ од безбожнијех, а молитву праведнијех чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Вид очињи весели срце, добар глас гоји кости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Ухо које слуша карање животно наставаће међу мудрима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Ко одбацује наставу, не мари за душу своју; а ко слуша карање, бива разуман.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Страх је Господњи настава к мудрости, и прије славе иде смјерност.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Човјек спрема срце, али је од Господа што ће језик говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Човјеку се сви путови његови чине чисти, али Господ испитује духове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Остави на Господа дјела своја, и биће тврде намјере твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Господ је створио све сам за се, и безбожника за зли дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Мрзак је Господу ко је год поносита срца, и неће остати без кара ако ће и друге узети у помоћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Милошћу и истином очишћа се безакоње, и страхом Господњим уклања се човјек ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Кад су чији путови мили Господу, мири с њим и непријатеље његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Боље је мало с правдом него много доходака с неправдом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Срце човјечије измишља себи пут, али Господ управља кораке његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Пророштво је на уснама царевијем, у суду неће погријешити уста његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Мјерила и потези прави од Господа су, и све камење у тобоцу његово је дјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Гадно је царевима чинити неправду, јер се правдом утврђује пријесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Миле су царевима усне праведне, и они љубе онога који говори право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Гњев је царев гласник, али мудар човјек ублажиће га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'У веселу је лицу цареву живот, и љубав је његова као облак с познијем даждем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Колико је боље тећи мудрост него злато! и тећи разум колико је љепше него сребро!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Пут је праведнијех уклањање ода зла; чува душу своју ко пази на пут свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Охолост долази пред погибао, и поносит дух пред пропаст.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Боље је бити понизна духа с кроткима него дијелити плијен с охолима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Ко пази на ријеч, налази добро, и ко се узда у Господа, благо њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Ко је мудра срца, зове се разуман, а сласт на уснама умножава науку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Извор је животу разум онима који га имају, а наука безумнијех безумље је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Срце мудрога разумно управља устима његовијем, и додаје науку уснама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Љубазне су ријечи сат меда, сласт души и здравље костима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Неки се пут чини човјеку прав, а крај му је пут к смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Ко се труди, себи се труди, јер га нагоне уста његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Човјек неваљао копа зло, и на уснама му је као огањ који пали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Опак човјек замеће свађу, и опадач раставља главне пријатеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Насилник мами друга својега и заводи га на пут који није добар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Намигује очима, кад мисли наопако; кад миче уснама, чини зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Сиједа је коса славна круна, налази се на путу праведном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Бољи је спор на гњев него јунак, и господар од свога срца бољи је него онај који узме град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Ждријеб се баца у крило, али је од Господа све што излази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Бољи је залогај суха хљеба с миром него кућа пуна поклане стоке са свађом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Разуман слуга биће господар над сином срамотнијем и с браћом ће дијелити нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Топионица је за сребро и пећ за злато, а срца искушава Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Зао човјек пази на усне зле, а лажљивац слуша језик пакостан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Ко се руга сиромаху, срамоти створитеља његова; ко се радује несрећи, неће остати без кара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Вијенац су старцима унуци, а слава синовима оци њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Не приличи безумном висока бесједа, акамоли кнезу лажљива бесједа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Поклон је драги камен ономе који га прима, куда се год окрене напредује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Ко покрива пријеступ, тражи љубав; а ко понавља ствар, раставља главне пријатеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Укор тишти разумнога већма него лудога сто удараца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Зао човјек тражи само одмет, али ће се љут гласник послати на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Боље је да човјека срете медвједица којој су отети медвједићи, него безумник у свом безумљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Ко враћа зло за добро, неће се зло одмаћи од куће његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Ко почне свађу, отвори уставу води; зато прије него се заметне, прођи се распре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Ко оправда кривога и ко осуди правога, обојица су гад Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'На што је благо безумноме у руци кад нема разума да прибави мудрост?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'У свако доба љуби пријатељ, и брат постаје у невољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Човјек безуман даје руку и јамчи се за пријатеља својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Ко милује свађу, милује гријех; ко подиже увис врата своја, тражи погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Ко је опака срца, неће наћи добра; и ко дволичи језиком, пашће у зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Ко роди безумна, на жалост му је, нити ће се радовати отац луда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Срце весело помаже као лијек, а дух жалостан суши кости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Безбожник прима поклон из њедара да преврати путове правди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Разумному је на лицу мудрост, а очи безумнику врљају накрај земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Жалост је оцу својему син безуман, и јад родитељци својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Није добро глобити праведника, ни да кнезови бију кога што је радио право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Устеже ријечи своје човјек који зна, и тиха је духа човјек разуман.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'И безуман кад мучи, мисли се да је мудар, и разуман, кад стискује усне своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Човјек самовољан тражи што је њему мило и мијеша се у свашта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Безумнику није мио разум него да се јавља срце његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Кад дође безбожник, дође и руг, и пријекор са срамотом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Ријечи су из уста човјечијих дубока вода, извор је мудрости поток који се разљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Није добро гледати безбожнику ко је, да се учини криво правом на суду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Усне безумникове пристају у свађу, и уста његова дозивљу бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Безумнику су уста његова погибао, и усне његове пругло души његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Ријечи су опадачеве као избијенијех, али слазе унутра у трбух');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'И ко је немаран у послу свом брат је распикући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Тврда је кула име Господње. к њему ће утећи праведник, и биће у високом заклону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Богатство је богатоме јак град и као висок зид у његовој мисли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Пред пропаст подиже се срце човјеку, а прије славе иде смјерност.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Ко одговара прије него чује, то му је лудост и срамота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Дух човјечији сноси бол свој; а дух оборен ко ће подигнути?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Срце разумна човјека добавља знање, и ухо мудријех тражи знање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Дар човјеку шири мјесто и води га пред властеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Праведан се чини ко је први у својој распри, али кад дође ближњи његов, испитује се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Распре прекида ждријеб, и између силнијех расуђује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Увријеђен је брат као тврд град, и свађа је као пријеворница на двору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Свакому се трбух сити плодом уста његовијех, дохотком од усна својих сити се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Смрт је и живот у власти језику, и ко га милује, јешће плод његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Ко је нашао жену, нашао је добро и добио љубав од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Сиромах говори молећи, а богат одговара оштро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Ко има пријатеља, ваља да поступа пријатељски, јер има пријатеља вјернијих од брата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Сиромах који ходи у безазлености својој бољи је него опаки уснама својим, који је безуман.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Кад је душа без знања, није добро; и ко је брзијех ногу, спотиче се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Лудост човјечија превраћа пут његов, а срце се његово гњеви на Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Богатство прибавља много пријатеља, а сиромаха оставља пријатељ његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Лажан свједок неће остати без кара, и ко говори лаж, неће утећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Многи угађају кнезу, и свак је пријатељ човјеку податљиву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'На сиромаха мрзе сва браћа његова, још више се пријатељи његови удаљују од њега; виче за њима, али их нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Ко прибавља разум, љуби душу своју; и ко пази на мудрост, наћи ће добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Свједок лажан неће остати без кара, и ко говори лаж, погинуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Не доликују безумном милине, ни слузи да влада кнезовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Разум задржава човјека од гњева, и част му је мимоићи кривицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Царева је срдња као рика младога лава, и љубав је његова као роса трави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Безуман је син мука оцу својему, и свадљивост женина непрестано прокисивање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Кућа и имање нашљеђује се од отаца; а од Господа је разумна жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Лијеност наводи тврд сан, и немарљива душа гладоваће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Ко држи заповијести, чува душу своју; а ко не мари за путове своје, погинуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Господу позаима ко поклања сиромаху, и платиће му за добро његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Карај сина својега докле има надања и на погибао његову да не прашта душа твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Велик гњев показује кад прашташ кар, и кад опростиш, послије већма покарај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Слушај свјет и примај наставу, да послије будеш мудар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Много има мисли у срцу човјечијем, али што Господ науми оно ће остати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Жеља човјеку треба да је да чини милост, а бољи је сиромах него лажа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Страх је Господњи на живот; у кога је он, борави сит, нити га походи зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Љењивац крије руку своју у њедра, ни к устима својим не приноси је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Удри потсмијевача да луди омудра, и разумнога накарај да разумије науку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Син срамотан и пријекоран упропашћује оца и одгони матер.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Немој, сине, слушати науке која одводи од ријечи разумнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Неваљао свједок потсмијева се правди, и уста безбожника прождиру на неправду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Готови су потсмјевачима судови и безумницима бој на леђа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Вино је потсмјевач и силовито пиће немирник, и ко год за њим лута неће бити мудар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Страх је царев као рика младога лава; ко га дражи, гријеши својој души.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Слава је човјеку да се окани свађе; а ко је год безуман, уплеће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Ради зиме љенивац не оре; проси о жетви, и ништа не добија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Савјет је у срцу човјечијем дубока вода, али човјек разуман црпе га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Највише људи хвали се својом добротом; али ко ће наћи човјека истинита?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Праведник једнако ходи у безазлености својој; благо синовима његовијем послије њега!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Цар сједећи на пријестолу судском расипа очима својим свако зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Ко може рећи: очистио сам срце своје, чист сам од гријеха својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Двојак потег и двојака мјера, обоје је мрско Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'По дјелима својим познаје се и дијете хоће ли бити чисто и хоће ли бити право дјело његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Ухо које чује, и око које види, обоје је Господ начинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Не љуби сна, да не осиромашиш; отварај очи своје, и бићеш сит хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Не ваља, не ваља, говори ко купује, а кад отиде онда се хвали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Има злата и много бисера, али су мудре усне најдрагоцјенији накит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Узми хаљину ономе који се подјемчи за туђина, узми залог од њега за туђинку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Сладак је човјеку хљеб од пријеваре, али му се послије напуне уста пијеска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Мисли се утврђују савјетом; зато разумно ратуј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Ко открива тајну, поступа невјерно; зато се не мијешај с онијем који разваљује уста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Ко псује оца својега или матер своју, његов ће се жижак угасити у црном мраку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Нашљедство које се из почетка брзо добија, не бива на пошљетку благословено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Не говори: вратићу зло. Чекај Господа, и сачуваће те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Мрзак је Господу двојак потег, мјерила лажна нијесу добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Од Господа су кораци човјечји, а човјек како ће разумјети пут његов?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Замка је човјеку да прождре светињу, и послије завјета опет да тражи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Мудар цар расипа безбожнике и пушта на њих коло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Видјело је Господње душа човјечија, истражује све што је у срцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Милост и истина чувају цара, и милошћу подупире свој пријесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Слава је младићима сила њихова, а старцима част сиједа коса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Модрице од боја и ударци који продиру до срца јесу лијек зломе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Срце је царево у руци Господу као потоци водени; куда год хоће, савија га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Сваки се пут човјеку чини прав, али Господ испитује срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Да се чини правда и суд, милије је Господу него жртва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Поносите очи и надуто срце и орање безбожничко гријех је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Мисли вриједна човјека доносе обиље, а свакога нагла сиромаштво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Благо сабрано језиком лажљивијем таштина је која пролази међу оне који траже смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Грабеж безбожнијех однијеће их, јер не хтјеше чинити што је право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Чији је пут крив, он је туђ; а ко је чист, његово је дјело право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Боље је сједјети у углу од крова него са женом свадљивом у кући заједничкој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Душа безбожникова жели зло, ни пријатељ његов не налази милости у њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Кад потсмјевач бива каран, луди мудра; и кад се мудри поучава, прима знање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Учи се праведник од куће безбожникове, кад се безбожници обарају у зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Ко затискује ухо своје од вике убогога, викаће и сам, али неће бити услишен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Дар у тајности утишава гњев, и поклон у њедрима жестоку срдњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Радост је праведнику чинити што је право, а страх онима који чине безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Човјек који зађе с пута мудрости починуће у збору мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Ко љуби весеље, биће сиромах; ко љуби вино и уље, неће се обогатити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Откуп за праведнике биће безбожник и за добре безаконик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Боље је живјети у земљи пустој него са женом свадљивом и гњевљивом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Драгоцјено је благо и уље у стану мудрога, а човјек безуман прождире га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Ко иде за правдом и милошћу, наћи ће живот, правду и славу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'У град јаких улази мудри, и обара силу у коју се уздају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Ко чува уста своја и језик свој, чува душу своју од невоља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Поноситом и обијесном име је потсмјевач, који све ради бијесно и охоло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Љенивца убија жеља, јер руке његове неће да раде;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Сваки дан жели; а праведник даје и не штеди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Жртва је безбожничка гад, акамоли кад је приносе у гријеху?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Лажни свједок погинуће, а човјек који слуша, говориће свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Безбожник је безобразан, а праведник удешава своје путе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Нема мудрости ни разума ни савјета насупрот Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Коњ се опрема за дан боја, али је у Господа спасење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Боље је име него велико богатство, и милост је боља него сребро и злато.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Богат и сиромах сретају се; обојицу је Господ створио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Паметан човјек види зло и склони се, а луди иду даље и плаћају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Смјерности и страху Господњем плата је богатство и слава и живот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Трње и замке су на путу опакога; ко чува душу своју, биће далеко од тога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Учи дијете према путу којим ће ићи, па неће отступити од њега ни кад остари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Богат господари над сиромасима, и ко узима у зајам бива слуга оному који даје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Ко сије безакоње жеће муку, и прута гњева његова нестаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Благо око биће благословено, јер даје хљеба својега убогому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Отјерај потсмјевача, и отићи ће распра и престаће свађа и срамота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Ко љуби чисто срце, и чије су усне љубазне, њему је цар пријатељ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Очи Господње чувају знање, а послове безаконикове обара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Љенивац говори: лав је напољу; насред улице погинуо бих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Уста су туђих жена јама дубока; на кога се гњеви Господ, онамо ће пасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Безумље је привезано дјетету на срце; прут којим се кара уклониће га од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Ко чини криво сиромаху да умножи своје, и ко даје богатоме, зацијело ће осиромашити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Пригни ухо своје и слушај ријечи мудријех људи, и срце своје привиј к науци мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Јер ће ти бити милина ако их сложиш у срце своје, ако све буду поређане на уснама твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Да би ти уздање било у Господа, казујем ти ово данас, а ти тако чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Нијесам ли ти написао знамените ствари за савјете и знање,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'Да бих ти показао тврђу истинитијех ријечи да би могао истинитијем ријечима одговарати онима који пошљу к теби?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Не отимај сиромаху зато што је сиромах, и не затири невољнога на вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Јер ће Господ бранити њихову ствар, и отеће душу онима који њима отимају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Не дружи се с човјеком гњевљивијем и не иди са жестоким,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'Да се не би навикао на путове његове и метнуо замке на душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Не буди од онијех који руку дају, који се јамче за дугове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Ако немаш чим платити, зашто да се однесе постеља испод тебе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Не помичи старе међе, коју су поставили оци твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Јеси ли видио човјека устаоца на послу? Таки ће пред царевима стајати, а неће стајати пред простацима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Кад сједеш да једеш с господином, пази добро што је пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'Иначе би сатјерао себи нож у грло, ако би био лаком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Не жели преслачака његовијех, јер су лажна храна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Не мучи се да се обогатиш, и прођи се своје мудрости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Хоћеш ли бацити очи своје на оно чега брзо нестаје? јер начини себи крила и као орао одлети у небо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Не једи хљеба у завидљивца, и не жели преслачака његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Јер како он тебе цијени у души својој тако ти јело његово. Говориће ти: једи и пиј; али срце његово није с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Залогај што поједеш избљуваћеш, и изгубићеш љубазне ријечи своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Пред безумнијем не говори, јер неће марити за мудрост бесједе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Не помичи старе међе, и не ступај на њиву сирочади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Јер је јак осветник њихов; браниће ствар њихову од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Обрати к науци срце своје и уши своје к ријечима мудријем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Не украћуј кара дјетету; кад га бијеш прутом, неће умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Ти га биј прутом, и душу ћеш му избавити из пакла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Сине мој, ако буде мудро срце твоје, веселиће се срце моје у мени;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'И играће бубрези моји кад усне твоје стану говорити што је право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Срце твоје нека не завиди грјешницима, него буди у страху Господњем вазда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Јер има плата, и надање твоје неће се затрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Слушај, сине мој, и буди мудар и управи путем срце своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Не буди међу пијаницама ни међу изјелицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Јер пијаница и изјелица осиромашиће, и спавач ходиће у ритама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Слушај оца својега који те је родио, и не презири матере своје кад остари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Купуј истину и не продаји је; купуј мудрост, знање и разум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Веома се радује отац праведников, и родитељ мудрога весели се с њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Нека се дакле весели отац твој и мати твоја, и нека се радује родитељка твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Сине мој, дај ми срце своје, и очи твоје нека пазе на моје путе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Јер је курва дубока јама, а тијесан студенац туђа жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Она и засједа као лупеж и умножава злочинце међу људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Коме: јаох? коме: куку? коме свађа? коме вика? коме ране ни за што? коме црвен у очима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Који сједе код вина, који иду те траже растворена вина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Не гледај на вино кад се румени, кад у чаши показује лице своје и управо искаче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'На пошљедак ће као змија ујести и као аспида упећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Очи ће твоје гледати на туђе жене, и срце ће твоје говорити опачине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'И бићеш као онај који лежи усред мора и као онај који спава поврх једра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'Рећи ћеш: избише ме, али ме не забоље; тукоше ме, али не осјетих; кад се пробудим, ићи ћу опет да тражим то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Не завиди злијем људима нити жели да си с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Јер о погибли мисли срце њихово и усне њихове говоре о муци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Мудрошћу се зида кућа и разумом утврђује се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'И знањем се пуне клијети свакога блага и драгоцјена и мила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Мудар је човјек јак, и разуман је човјек силан снагом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Јер мудријем савјетом ратоваћеш, и избављење је у мноштву савјетника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Високе су безумноме мудрости; неће отворити уста својих на вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Ко мисли зло чинити зваће се зликовац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Мисао безумникова гријех је, и потсмјевач је гад људски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Ако клонеш у невољи, скратиће ти се сила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Избављај похватане на смрт; и које хоће да погубе, немој се устегнути од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Ако ли речеш: гле, нијесмо знали за то; неће ли разумјети онај који испитује срца, и који чува душу твоју неће ли дознати и платити свакоме по дјелима његовијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Сине мој, једи мед, јер је добар, и сат, јер је сладак грлу твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Тако ће бити познање мудрости души твојој, кад је нађеш; и биће плата, и надање твоје неће се затрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Безбожниче, не вребај око стана праведникова, и не квари му почивања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Јер ако и седам пута падне праведник, опет устане, а безбожници пропадају у злу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Кад падне непријатељ твој, немој се радовати, и кад пропадне, нека не игра срце твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Јер би видио Господ и не би му било мило, и обратио би гњев свој од њега на тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Немој се жестити ради неваљалаца, немој завидјети безбожницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Јер нема плате неваљалцу, жижак ће се безбожницима угасити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Бој се Господа, сине мој, и цара, и не мијешај се с немирницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Јер ће се уједанпут подигнути погибао њихова, а ко зна пропаст која иде од обојице?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'И ово је за мудраце: гледати ко је ко на суду није добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Ко говори безбожнику: праведан си, њега ће проклињати људи и мрзиће на њ народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'А који га карају, они ће бити мили, и доћи ће на њих благослов добријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Ко говори ријечи истините, у уста љуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Уреди свој посао на пољу, и сврши своје на њиви, потом и кућу своју зидај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Не буди свједок на ближњега својега без разлога, и не варај уснама својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Не говори: како је он мени учинио тако ћу ја њему учинити; платићу овом човјеку по дјелу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Иђах мимо њиву човјека лијена и мимо виноград човјека безумна;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'И гле, бјеше све зарасло у трње и све покрио чкаљ, и ограда им камена разваљена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'И видјевши узех на ум, и гледах и поучих се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Док мало проспаваш, док мало продријемљеш, док мало склопиш руке да починеш,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'У том ће доћи сиромаштво твоје као путник, и оскудица твоја као оружан човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'И ово су приче Соломунове које сабраше људи Језекије цара Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Слава је Божија скривати ствар, а слава је царска истраживати ствар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Висина небу и дубина земљи и срце царевима не може се досегнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Узми од сребра троску, и изаћи ће ливцу заклад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Узми безбожника испред цара, и утврдиће се правдом пријесто његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Не величај се пред царем и не стај на мјесто гдје стоје властељи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Јер је боље да ти се каже: ходи горе, него да те понизе пред кнезом да видиш својим очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Не иди одмах да се преш, гледај шта би чинио напошљетку ако би те осрамотио ближњи твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Расправи ствар своју с ближњим својим, али туђе тајне не откривај,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'Да те не би псовао ко чује, и срамота твоја да не би остала на теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Златне јабуке у сребрнијем судима јесу згодне ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Златна је гривна и накит од најбољега злата мудри карач ономе који слуша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Вјеран је посланик као студен шњежна о жетви онима који га пошљу, и расхлађује душу својим господарима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Ко се хвали даром лажнијем, он је као облаци и вјетар без дажда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Стрпљењем се ублажава кнез, и мек језик ломи кости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Кад нађеш мед, једи колико ти је доста, да не би наједавши га се избљувао га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Ријетко нека ти нога ступа у кућу ближњега твојега, да не би наситивши се тебе омрзао на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Ко год говори лажно свједочанство на ближњега својега, он је као маљ и мач и оштра стријела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Уздање је у невјерника у невољи зуб сломљен и нога уганута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Ко пјева пјесме жалосном срцу, он је као онај који свлачи хаљину на зими, и као оцат на салитру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Ако је гладан ненавидник твој, нахрани га хљеба, и ако је жедан напој га воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Јер ћеш живо угљевље згрнути на главу његову, и Господ ће ти платити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Сјеверни вјетар носи дажд, а потајни језик лице срдито.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Боље је сједјети у углу од крова него са женом свадљивом у кући заједничкој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Добар је глас из даљне земље као студена вода жедној души.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Праведник који пада пред безбожником јест као извор ногама замућен и као студенац покварен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Јести много меда није добро, и истраживати славу није славно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Ко нема власти над духом својим, он је град разваљен без зидова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Као снијег у љето и дажд о жетви, тако не доликује безумноме част.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Као врабац кад прхне и ласта кад одлети, тако клетва незаслужена неће доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Бич коњу, узда магарцу, а батина безумницима на леђа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Не одговарај безумнику по безумљу његову, да не будеш и ти као он.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Одговори безумнику према безумљу његову, да не мисли да је мудар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Ко шаље безумника да му што сврши, он отсијеца себи ноге и пије неправду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Како хроми храмље ногама својим, така је бесједа у устима безумнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Као да баца драги камен у гомилу камења, тако ради ко чини част безумноме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Као трн кад дође у руку пијаноме, така је бесједа у устима безумнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Много муке задаје свјема ко плаћа безумнику и ко плаћа преступницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Као што се пас повраћа на своју бљувотину, тако безумник понавља своје безумље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Јеси ли видио човјека који мисли да је мудар? више има надања од безумнога него од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Љенивац говори: љути је лав на путу, лав је на улицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Као што се врата обрћу на чеповима својим, тако љенивац на постељи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Љенивац крије руку своју у њедра, тешко му је принијети је к устима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Љенивац мисли да је мудрији од седморице који одговарају разумно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Пса за уши хвата ко се пролазећи жести за туђу распру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Какав је безумник који баца искре и стријеле смртне,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'Таки је сваки који превари ближњега својега па онда вели: шалио сам се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Кад нестане дрва, угаси се огањ; тако кад нема опадача, престаје распра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Угаљ је за жеравицу, дрва за огањ, а човјек свадљивац да распаљује свађу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Ријечи су опадачеве као ријечи избијенијех, али слазе унутра у трбух.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Као сребрна пјена којом се обложи цријеп, таке су усне непријатељске и зло срце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Ненавидник се претвара устима својим, а у срцу слаже пријевару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Кад говори умиљатијем гласом, не вјеруј му, јер му је у срцу седам гадова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Мржња се покрива лукавством, али се злоћа њезина открива на збору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Ко јаму копа, у њу ће пасти; и ко камен ваља, на њега ће се превалити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Језик лажан мрзи на оне које сатире, и уста која ласкају граде погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Не хвали се сјутрашњим даном, јер не знаш шта ће дан донијети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Нека те хвали други, а не твоја уста, туђин, а не твоје усне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Тежак је камен, и пијесак је тежак; али је гњев безумников тежи од обојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Јарост је немилостива, и гњев је плах; али ко ће одољети зависти?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Бољи је јавни укор него тајна љубав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Ударци од пријатеља истинити су, а цјеливи ненавидникови лажни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Душа сита гази сат, а гладној души слатко је све што је горко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Кака је птица која одлети из својега гнијезда, таки је човјек који отиде из својега мјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Уље и кад весели срце, тако је пријатељ сладак свјетом срдачнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Не остављај пријатеља својега ни пријатеља оца својега, и у кућу брата својега не улази у несрећи својој: бољи је сусјед близу него брат далеко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Сине мој, буди мудар и обрадуј срце моје, да имам шта одговорити ономе ко ме ружи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Паметан човјек види зло и склони се, а луди иду даље и плаћају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Узми хаљину оному који се подјамчи за туђина, и узми залог од њега за туђинку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Ко благосиља пријатеља својега на глас рано устајући, примиће му се за клетву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Непрестано капање кад је велик дажд, и жена свадљива, једно су;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Ко је уставља, уставља вјетар, и она се одаје као мирисаво уље у десници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Гвожђе се гвожђем оштри, тако човјек оштри лице пријатеља својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Ко чува смокву, јешће рода њезина; тако ко чува господара својега, биће поштован.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Како је у води лице према лицу, тако је срце човјечије према човјеку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Гроб и пропаст нигда се не могу заситити, тако очи човјечије нигда нијесу сите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Сребро у топионици и злато у пећи а човјек у устима онога који га хвали познаје се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Да безумнога туцаш у ступи с тучком с прекрупом, не би отишло од њега безумље његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Добро гледај стоку своју и старај се за стада своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Јер богатство не траје довијека нити круна од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Кад трава нарасте и покаже се зелен, купи се трава по планинама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Јагањци су ти за одијело, и јарићи цијена за њиву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'И доста има млијека козјега теби за јело, и за јело твојему дому и за храну твојим дјевојкама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Бјеже безбожници кад их нико не гони, а праведници су као лавићи без страха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Кад се у земљи зла чине, настају јој многи кнезови; али кад се нађе човјек разуман и вјешт, остаје дуго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Човјек сиромах који чини криво убогима јест као силан дажд иза којега нестаје хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Који остављају закон, хвале безбожнике; а који држе закон, противе им се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Зли људи не разумију што је право; а који траже Господа, разумију све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Бољи је сиромах који ходи у безазлености својој него ко иде кривијем путовима ако је и богат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Ко чува закон, син је разуман; а ко се дружи с изјелицама, срамоти оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Ко умножава добро своје ујмом и придавком, сабира ономе који ће раздавати сиромасима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Ко одвраћа ухо своје да не чује закона и молитва је његова мрска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Ко заводи праве на зао пут, пашће у јаму своју, а безазлени наслиједиће добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Богат човјек мисли да је мудар, али разуман сиромах испитује га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Кад се радују праведни, велика је слава; а кад се подижу безбожници, тражи се човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Ко крије пријеступе своје, неће бити срећан; а ко признаје и оставља, добиће милост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Благо човјеку који се свагда боји; а ко је тврдоглав, упада у зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Безбожник који влада народом сиромашнијем, лав је који риче и медвјед гладан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Кнез без разума чини много неправде, а који мрзи на лакомство, живјеће дуго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Човјек који чини насиље крви људској, бјежаће до гроба, а нико га неће задржати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Ко ходи у безазлености, спашће се; а ко је опак на путовима, пашће у један мах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Ко ради своју земљу, биће сит хљеба; а ко иде за беспослицама, наситиће се сиротиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Човјек вјеран обилује благословима; а ко нагли да се обогати, неће бити без кривице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Није добро гледати ко је ко, јер за залогај хљеба човјек ће учинити зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Нагли да се обогати човјек завидљив, а не зна да ће му доћи сиромаштво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Ко укорава човјека наћи ће послије већу милост него који ласка језиком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Ко краде оца својега и матер своју, и говори: није гријех, он је друг крвнику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Охоли замеће свађу; а ко се узда у Господа, изобиловаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Ко се узда у своје срце, безуман је; а ко ходи мудро, избавиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Ко даје сиромаху, неће му недостајати; а ко одвраћа очи своје, биће му много клетава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Кад се подижу безбожници, сакрива се човјек; а кад гину, умножавају се праведни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Човјек који по карању остаје тврдоглав, уједанпут ће пропасти, да неће бити лијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Кад се умножавају праведници, весели се народ; а кад влада безбожник, уздише народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Ко љуби мудрост, весели оца својега; а ко се дружи с курвама, расипа своје добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Цар правдом подиже земљу; а ко узима мито, сатире је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Ко ласка пријатељу својему, разапиње мрежу ногама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'У гријеху је зла човјека замка, а праведник пјева и весели се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Праведник разумије парбу невољнијех, а безбожник не мари да зна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Потсмјевачи распаљују град, а мудри утишавају гњев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Мудар човјек кад се пре с лудијем, или се срдио или смијао, нема мира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Крвопије мрзе на безазленога, а прави се брину за душу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Сав гњев свој излива безумник, а мудри уставља га натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Који кнез слуша лажне ријечи, све су му слуге безбожне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Сиромах и који даје на добит сретају се; обојици Господ просвјетљује очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Који цар право суди сиромасима, његов ће пријесто стајати довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Прут и кар дају мудрост, а дијете пусто срамоти матер своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Кад се умножавају безбожници, умножавају се гријеси, а праведници ће видјети пропаст њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Карај сина својега, и смириће те, и учиниће милину души твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Кад нема утваре, расипа се народ; а ко држи закон, благо њему!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Ријечима се не поправља слуга, јер ако и разумије, опет не слуша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Јеси ли видио човјека нагла у бесједи својој? више има надања од безумна него од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Ако ко мази слугу од малена, он ће најпослије бити син.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Гњевљив човјек замеће свађу, и ко је напрасит, много гријеши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Охолост понижује човјека, а ко је смјеран духом, добија славу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Ко дијели с лупежем, мрзи на своју душу, чује проклетство и не проказује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Страшив човјек меће себи замку; а ко се у Господа узда, биће у високом заклону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Многи траже лице владаочево, али је од Господа суд свакоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Праведнима је мрзак неправедник, а безбожнику је мрзак ко право ходи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Ријечи Агура сина Јакејева; сабране ријечи тога човјека Итилу, Итилу и Укалу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Ја сам луђи од свакога, и разума човјечијега нема у мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'Нити сам учио мудрости нити знам светијех ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Ко је изашао на небо и опет сишао? ко је скупио вјетар у прегршти своје? ко је свезао воде у плашт свој? ко је утврдио све крајеве земљи? како му је име? и како је име сину његову? знаш ли?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Све су ријечи Божије чисте; он је штит онима који се уздају у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Ништа не додаји к ријечима његовијем, да те не укори и не нађеш се лажа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'За двоје молим те; немој ме се оглушити док сам жив:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Таштину и ријеч лажну удаљи од мене; сиромаштва ни богатства не дај ми, храни ме хљебом по оброку мом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Да не бих наједавши се одрекао се тебе и рекао: ко је Господ? или осиромашивши да не бих крао и узалуд узимао име Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Не опадај слуге господару његову, да те не би клео и ти био крив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Има род који псује оца својега и не благосиља матере своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Има род који мисли да је чист, а од свога кала није опран.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Има род који држи високо очи своје, и вјеђе му се дижу увис.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Има род којему су зуби мачеви и кутњаци ножеви, да прождире сиромахе са земље и убоге између људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Пијавица има двије кћери, које говоре: дај, дај. Има троје несито, и четврто никад не каже: доста:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Гроб, материца јалова, земља која не бива сита воде, и огањ, који не говори: доста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Око које се руга оцу и неће да слуша матере, кљуваће га гаврани с потока и јести орлићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Троје ми је чудесно, и четвртога не разумијем:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'Пут орлов у небо, пут змијин по стијени, пут лађин посред мора, и пут човјечији к дјевојци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Таки је пут курвин: једе, и убрише уста, па вели: нијесам учинила зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Од трога се потреса земља, и четвртога не може поднијети:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'Од слуге, кад постане цар, од безумника, кад се наједе хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'Од пуштенице, кад се уда, од слушкиње кад наслиједи госпођу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Четворо има малено на земљи, али мудрије од мудраца:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Мрави, који су слаб народ, али опет приправљају у љето себи храну;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Питоми зечеви, који су нејак народ, али опет у камену граде себи кућу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Скакавци, који немају цара, али опет иду сви јатом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'Паук, који рукама ради и у царским је дворима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Троје лијепо корача, и четврто лијепо ходи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Лав, најјачи између звјерова, који не узмиче ни пред ким,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'Коњ опасан по бедрима или јарац, и цар на кога нико не устаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Ако си лудовао понесавши се или си зло мислио, метни руку на уста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Кад се разбија млијеко, излази масло; и ко јако нос утире, изгони крв; тако ко дражи на гњев, замеће свађу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Ријечи цара Лемуила; сабране ријечи, којима га је учила мати његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Шта, сине мој, шта, сине утробе моје, и шта, сине завјета мојих?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Не дај кријепкости своје женама, ни путова својих онима што сатиру цареве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Није за цареве, Лемуило, није за цареве да пију вино, ни за кнезове да пију силовито пиће,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Да не би пијући заборавио уредбе, и измијенио правицу којему невољнику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Подајте силовито пиће ономе који хоће да пропадне, и вино онима који су тужна срца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Нека се напије и заборави своје сиромаштво, и да се више не сјећа своје муке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Отворај уста своја за нијемога, за ствар свијех намијењенијех смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Отворај уста своја, суди право, дај правицу невољноме и убогоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Ко ће наћи врсну жену? јер вриједи више него бисер.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Ослања се на њу срце мужа њезина, и добитка неће недостајати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Чини му добро, а не зло, свега вијека својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Тражи вуне и лана, и ради по вољи рукама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Она је као лађа трговачка, из далека доноси храну своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Устаје док је још ноћ, даје храну чељади својој и посао дјевојкама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Мисли о њиви, и узме је, од рада руку својих сади виноград.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Опасује снагом бедра своја и кријепи мишице своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Види како јој је добра радња, не гаси јој се ноћу жижак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Рукама својим маша се преслице, и прстима својима држи вретено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Руку своју отвора сиромаху, и пружа руке убогоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Не боји се снијега за своју чељад, јер сва чељад њезина има по двоје хаљине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Покриваче сама себи гради, тако платно и скерлет одијело јој је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Зна се муж њезин на вратима кад сједи са старјешинама земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Кошуље гради и продаје, и појасе даје трговцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Одијело јој је крјепост и љепота, и осмијева се на вријеме које иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Уста своја отвора мудро и на језику јој је наука блага.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Пази на владање чељади своје, и хљеба у лијености не једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Синови њезини подижу се и благосиљају је; муж њезин такођер хвали је;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Многе су жене биле врсне, али ти их надвишујеш све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Љупкост је пријеварна и љепота ташта; жена која се боји Господа, она заслужује похвалу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Подајте јој од плода руку њезинијех, и нека је хвале на вратима дјела њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Ријечи проповједника сина Давидова цара у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Таштина над таштинама, вели проповједник, таштина над таштинама, све је таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Кака је корист човјеку од свега труда његова, којим се труди под сунцем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Нараштај један одлази и други долази, а земља стоји увијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Сунце излази и залази, и опет хити на мјесто своје одакле излази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Вјетар иде на југ и обрће се, и у обртању свом враћа се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Све ријеке теку у море, и море се не препуња; одакле теку ријеке, онамо се враћају да опет теку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Све је мучно, да човјек не може исказати; око се не може нагледати, нити се ухо може наслушати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Што је било то ће бити, што се чинило то ће се чинити, и нема ништа ново под сунцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Има ли што за што би ко рекао: види, то је ново? Већ је било за вијекова који су били прије нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Не помиње се што је прије било; ни оно што ће послије бити неће се помињати у онијех који ће послије настати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Ја проповједник бијах цар над Израиљем у Јерусалиму;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'И управих срце своје да тражим и разберем мудрошћу све што бива под небом; тај мучни посао даде Бог синовима људским да се муче око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Видјех све што бива под сунцем, и гле, све је таштина и мука духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Што је криво не може се исправити, и недостаци не могу се избројити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Ја рекох у срцу свом говорећи: ево, ја постах велик, и претекох мудрошћу све који бише прије мене у Јерусалиму, и срце моје видје много мудрости и знања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'И управих срце своје да познам мудрост и да познам безумље и лудост; па дознах да је и то мука духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Јер гдје је много мудрости, много је бриге, и ко умножава знање умножава муку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Ја рекох у срцу свом: дај да те окушам весељем; уживај добра. Али гле и то бјеше таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Смијеху рекох: лудујеш; и весељу: шта то радиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Размишљах у срцу свом да пуштам тијело своје на пиће, и срцем својим управљајући мудро да се држим лудости докле не видим шта би добро било синовима људским да чине под небом док су живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Велика дјела учиних: сазидах себи куће, насадих себи винограде;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Начиних себи вртове и воћњаке, и насадих у њима свакојаких дрвета роднијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Начиних себи језера водена да заљевам из њих шуму гдје расту дрвета;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Набавих себи слуга и слушкиња, и имах слуга рођенијех у кући мојој; и имах говеда и оваца више од свијех који бише прије мене у Јерусалиму;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Такођер накупих себи сребра и злата и заклада од царева и земаља; набавих себи пјевача и пјевачица и милина људских, и справа музичких свакојаких.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'И тако постах већи и силнији од свијех који бише прије мене у Јерусалиму; и мудрост моја оста са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'И што год жељаху очи моје, не брањах им нити украћивах срцу својему какога весеља, него се срце моје весељаше са свакога труда мојега, и то ми бијаше дио од свакога труда мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'А кад погледах на сва дјела своја што урадише руке моје, и на труд којим се трудих да урадим, гле, све бјеше таштина и мука духу, и нема користи под сунцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Тада се обратих да видим мудрост и лудост и безумље, јер шта би чинио човјек који би настао послије цара? што је већ учињено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'И видјех да је боља мудрост од лудости, као што је боља свјетлост од мрака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Мудри има очи у глави, а безумни иде по мраку; али такођер дознах да једнако бива свјема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Зато рекох у срцу свом: мени ће бити као безумнику што бива; шта ће ми дакле помоћи што сам мудар? И рекох у срцу свом: и то је таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Јер се неће спомињати мудрац као ни безумник довијека; јер што сада јест, све се заборавља послије, и мудрац умире као и безумник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Зато ми омрзе живот, јер ми није мило што бива под сунцем, јер је све таштина и мука духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'И омрзе ми сав труд мој око којега се трудих под сунцем, јер ћу га оставити човјеку који ће настати након мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'И ко зна хоће ли бити мудар или луд? и опет ће бити господар од свега труда мојега око којега се трудих и мудровах под сунцем. И то је таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Зато дођох на то да ми срце изгуби надање о сваком труду око којега се трудих под сунцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Јер има људи који се труде мудро и разумно и право, па то остављају у дио другоме који се није трудио око тога. И то је таштина и велико зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Јер шта има човјек од свега труда свога и од муке срца свога, коју подноси под сунцем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Јер су сви дани његови мука а послови његови брига; ни ноћу се не одмара срце његово. И то је таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Није ли дакле добро човјеку да једе и пије и да гледа да му је души добро од труда његова? Ја видјех и то да је из руке Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Јер ко је јео и уживао више него ја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Јер човјеку који му је по вољи даје мудрост и разум и радост, а грјешнику даје муку да сабира и скупља да да ономе који је по вољи Богу. И то је таштина и мука духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Свему има вријеме, и сваком послу под небом има вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Има вријеме кад се рађа, и вријеме кад се умире; вријеме кад се сади, и вријеме кад се чупа посађено;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Вријеме кад се убија, и вријеме кад се исцјељује; вријеме кад се разваљује, и вријеме кад се гради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Вријеме плачу и вријеме смијеху; вријеме ридању и вријеме игрању;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Вријеме кад се размеће камење, и вријеме кад се скупља камење; вријеме кад се грли, и вријеме кад се оставља грљење;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Вријеме кад се тече, и вријеме кад се губи; вријеме кад се чува, и бријеме кад се баца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Вријеме кад се дере, и вријеме кад се сашива; вријеме кад се мучи, и вријеме кад се говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Вријеме кад се љуби, и вријеме кад се мрзи; вријеме рату и вријеме миру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Кака је корист ономе који ради од онога око чега се труди?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Видио сам послове које је Бог дао синовима људским да се муче око њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Све је учинио да је лијепо у своје вријеме, и свијет метнуо им је у срце, али да не може човјек докучити дјела која Бог твори, ни почетка ни краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Дознах да нема ништа боље за њих него да се веселе и чине добро за живота свога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'И кад сваки човјек једе и пије и ужива добра од свакога труда својега, то је дар Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Дознах да што год твори Бог оно траје довијека, не може му се ништа додати нити се од тога може што одузети; и Бог твори да би га се бојали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Што је било то је сада, и што ће бити то је већ било; јер Бог повраћа што је прошло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Још видјех под сунцем гдје је мјесто суда безбожност и мјесто правде безбожност.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'И рекох у срцу свом: Бог ће судити праведнику и безбожнику; јер има вријеме свему и сваком послу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Рекох у срцу свом за синове људске да им је Бог показао да виде да су као стока.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Јер што бива синовима људским то бива и стоци, једнако им бива; како гине она тако гину и они, и сви имају исти дух; и човјек ништа није бољи од стоке, јер је све таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Све иде на једно мјесто; све је од праха и све се враћа у прах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Ко зна да дух синова људских иде горе, а дух стоке да иде доље под земљу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Зато видјех да ништа нема боље човјеку него да се весели онијем што ради, јер му је то дио; јер ко ће га довести да види што ће бити послије њега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Опет видјех све неправде које се чине под сунцем, и гле, сузе онијех којима се чини неправда, и немају ко би их потјешио ни снаге да се избаве из руку онијех који им чине неправду; немају никога да их потјеши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Зато хвалих мртве који већ помријеше више него живе који још живе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Али је бољи и од једнијех и од другијех онај који још није постао, који није видио зла што бива под сунцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Јер видјех сваки труд и свако добро дјело да од њега бива завист човјеку од ближњега његова. И то је таштина и мука духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Безумник склапа руке своје, и једе своје тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Боља је једна грст у миру него обје грсти с трудом и муком у духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Опет видјех таштину под сунцем:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Има ко је сам, инокосан, нема ни сина ни брата, и опет нема краја труду његову, и очи његове не могу да се насите богатства; а не мисли: за кога се мучим и одузимам својој души добра? И то је таштина и зао посао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Боље је двојици него једному, јер имају добру добит од свога труда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Јер ако један падне, други ће подигнути друга својега; а тешко једному! ако падне, нема другога да га подигне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Јоште ако двојица спавају заједно, грије један другога; а један како ће се згријати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'И ако би ко надјачао једнога, двојица ће му одољети; и трострука врвца не кида се лако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Боље је дијете убого а мудро него цар стар а безуман, који се већ не зна поучити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Јер један излази из тамнице да царује, а други који се роди да царује осиромаши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Видјех све живе који ходе под сунцем гдје пристају за дјететом другим, које ће ступити на његово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Нема краја народу који бијаше пред њим, а који послије настану неће се радовати њему. И то је таштина и мука духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Чувај ногу своју кад идеш у дом Божји, и приступи да слушаш; то је боље него што безумни дају жртве, јер не знају да зло чине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Немој наглити устима својим, и срце твоје да не буде брзо изговорити што пред Богом, јер је Бог на небу а ти си на земљи, зато нека буде мало ријечи твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Јер сан долази од многога посла, а глас безумников од многих ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Кад учиниш завјет Богу, не оклијевај испунити га, јер му нијесу мили безумници; што год завјетујеш, испуни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Боље је да не завјетујеш неголи да завјетујеш па не испуниш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Не дај устима својима да на гријех наводе тијело твоје, и не говори пред анђелом да је било нехотице. Зашто би се гњевио Бог на ријечи твоје и потро дјело руку твојих?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Јер као што у мноштву санова има таштине, тако и у многим ријечима; него бој се Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Ако видиш гдје се чини неправда сиромаху и отима суд и правда у земљи, не чуди се томе, јер виши пази на високога, и има још виших над њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Али је земља кориснија од свега; и цар њиви служи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Ко љуби новце, неће се наситити новаца; и ко љуби богатство, неће имати користи од њега. И то је таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Гдје је много добра, много је и онијех који га једу; па кака је корист од тога господару? осим што гледа својим очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Сладак је сан ономе који ради, јео мало или много; а ситост богатоме не да спавати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Има љуто зло које видјех под сунцем: богатство које се чува на зло ономе чије је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Јер тако богатство пропадне злом незгодом, те сину којега је родио не остане ништа у руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Као што је изашао из утробе матере своје наг, тако опет одлази како је дошао; и ништа не узима од труда својега да понесе у руци својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'И то је љуто зло што одлази како је дошао; и кака му је корист што се трудио у вјетар,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'И свега вијека својега јео у мраку, и много се бринуо и жалостио и љутио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Ето, видјех да је добро и лијепо човјеку да једе и пије и ужива добро од свега труда својега којим се труди под небом за живота својега, који му Бог да, јер му је то дио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'И кад коме Бог да богатство и благо, и да му да ужива и узима свој дио и да се весели с труда својега, то је дар Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Јер се неће много опомињати дана живота својега, јер му Бог даје да му је срце весело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Има зло које видјех под сунцем и често је међу људима:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Некоме Бог да богатство и благо и славу, те душа његова има све што год жели, али му не да Бог да то ужива, него ужива други. То је таштина и љуто зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Да би ко родио сто синова и живио много година и дани би се вијека његова веома намножили, а душа се његова не би наситила добра, те ни погреба не би имао, кажем да је боље недоношче од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Јер узалуд дође и у таму отиде и име му је тамом покривено;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Ни сунца не видје, нити што позна, а почива боље него онај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'И да би живио двије тисуће година, а добра не би уживао, не одлазе ли сви на једно мјесто?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Сав је труд човјечји за уста његова, али се не може наситити душа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Јер шта има мудри више него безумни? шта ли сиромах, који се умије владати међу живима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Боље је видјети очима него ли жељети; и то је таштина и мука духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Што је ко, давно је тијем назван; и зна се да је човјек и да се не може судити с јачим од себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Кад дакле има много ствари које умножавају таштину, кака је корист човјеку?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Јер ко зна што је добро човјеку у животу, за мало дана таштега живота његова, који му пролазе као сјен? или ко ће казати човјеку шта ће бити послије њега под сунцем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Боље је име него добро уље, и дан смртни него дан у који се ко роди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Боље је ићи у кућу гдје је жалост него гдје је гозба, јер је ондје крај свакога човјека, и ко је жив, слаже срце своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Боља је жалост него смијех, јер кад је лице невесело, срце постаје боље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Срце је мудријех људи у кући гдје је жалост, а срце безумнијех у кући гдје је весеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Боље је слушати карање мудрога него да ко слуша пјесму безумнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Јер као што прашти трње под лонцем, тако је смијех безумников; и то је таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Насиље обезумљује мудрога, и поклон изопачује срце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Бољи је крај ствари него почетак јој; бољи је ко је стрпљива духа неголи ко је поносита духа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Не буди нагао у духу свом на гњев, јер гњев почива у њедрима безумнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Не говори: шта је то, те су пређашњи дани били бољи од овијех? јер не би било мудро да за то питаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Добра је мудрост с имањем, и корисна је онима који виде сунце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Јер је мудрост заклон, и новци су заклон; али је претежније знање мудрости тијем што даје живот ономе ко је има.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Погледај дјело Божије; јер ко може исправити што он искриви?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'У добро вријеме уживај добро, а у зло вријеме гледај, јер је Бог створио једно према другом зато да човјек не зна шта ће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Свашта видјех за времена таштине своје: праведника који пропада у правди својој, и безбожника који дуго живи у својој злоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Не буди сувише праведан ни сувише мудар; зашто би себе упропастио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Не буди сувише безбожан ни луд; зашто би умро прије времена?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Добро је да држиш једно а друго да не пушташ из руке; јер ко се боји Бога избавиће се од свега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Мудрост кријепи човјека више него десет кнезова који су у граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Доиста нема човјека праведна на земљи који твори добро и не гријеши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Не узимај на ум свашта што се говори, ако би и слугу својега чуо гдје те псује;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Јер срце твоје зна да си и ти више пута псовао друге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Све то огледах мудрошћу и рекох: бићу мудар; али мудрост бјеше далеко од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Што је тако далеко и врло дубоко, ко ће наћи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Окретох се срцем својим да познам и извидим и изнађем мудрост и разум, и да познам безбожност лудости и лудост безумља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'И нађох да је грча од смрти жена којој је срце мрежа и пругло, којој су руке окови; ко је мио Богу, сачуваће се од ње, а грјешника ће ухватити она.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Гле, то нађох, вели проповједник, једно према другом, тражећи да разумијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Још тражи душа моја, али не нађох. Човјека једнога у тисући нађох, али жене међу свјема не нађох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Само, гле, ово нађох: да је Бог створио човјека добра; а они траже свакојаке помисли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Ко је као мудри? и ко зна шта значе ствари? Мудрост просвјетљује човјеку лице, а тврдоћа лица његова мијења се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Ја ти кажем: извршуј заповијест цареву, и то заклетве Божије ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Не буди брз да отидеш испред њега; не стој у злој ствари, јер ће учинити што год хоће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Јер гдје је год ријеч царева ондје је власт, и ко ће му рећи: шта радиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Ко извршује заповјест, неће знати за зло, јер срце мудрога зна вријеме и начин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Јер свачему има вријеме и начин; али многа зла сналазе човјека,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Што не зна шта ће бити; јер кад ће што бити, ко ће му казати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Човјек није властан над духом да би уставио дух, нити има власти над даном смртнијем, нити има обране у тој борби; ни безбожност не избавља онога у кога је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Све ово видјех, и управих срце своје на све што се ради под сунцем. Каткад влада човјек над човјеком на зло његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'И тада видјех безбожнике погребене, гдје се вратише; а који добро чињаху отидоше са светога мјеста и бише заборављени у граду. И то је таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Што нема одмах осуде за зло дјело, зато срце синова људских кипи у њима да чине зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Нека грјешник сто пута чини зло и одгађа му се, ја ипак знам да ће бити добро онима који се боје Бога, који се боје лица његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'А безбожнику неће бити добро, нити ће му се продуљити дани, него ће бити као сјен ономе који се не боји лица Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Таштина је која бива на земљи што има праведника којима бива по дјелима безбожничким, а има безбожника којима бива по дјелима праведничким. Рекох: и то је таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Зато ја хвалих весеље, јер нема ништа боље човјеку под сунцем него да једе и пије и да се весели; и то му је од труда његова за живота његова, који му Бог да под сунцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Кад управих срце своје да познам мудрост и видим шта се ради на земљи, те ни дању ни ноћу не долази човјеку сан на очи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'Видјех на свијем дјелима Божијим да човјек не може докучити оно што се ради под сунцем, око чега се труди човјек тражећи, али не налази, и ако и мудрац рече да зна, ипак не може докучити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Доиста све ово сложих у срце своје да бих расвијетлио све то, како су праведни и мудри и дјела њихова у руци Божијој, а човјек не зна ни љубави ни мржње од свега што је пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Све бива свјема једнако: праведнику бива као безбожнику, доброму и чистому као нечистому, ономе који приноси жртву као ономе који не приноси, како доброму тако грјешнику, ономе који се куне као ономе који се боји заклетве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'А то је најгоре од свега што бива под сунцем што свјема једнако бива, те је и срце људско пуно зла, и лудост им је у срцу док су живи, а потом умиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Јер ко ће бити изабран? У живијех свијех има надања; и псу живу боље је него мртву лаву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Јер живи знају да ће умријети, а мртви не знају ништа нити им има плате, јер им се спомен заборавио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'И љубави њихове и мржње њихове и зависти њихове нестало је, и више немају дијела нигда ни у чему што бива под сунцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Хајде, једи хљеб свој с радошћу, и весела срца пиј вино своје, јер су мила Богу дјела твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Свагда нека су ти хаљине бијеле, и уља на глави твојој да се не премиче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Уживај живот са женом коју љубиш свега вијека својега таштега, који ти је дат под сунцем за све вријеме таштине твоје, јер ти је то дио у животу и од труда твојега којим се трудиш под сунцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Све што ти дође на руку да чиниш, чини по могућности својој, јер нема рада ни мишљења ни знања ни мудрости у гробу у који идеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Опет видјех под сунцем да није до брзијех трка, ни рат до храбријех, ни хљеб до мудријех, ни богатство до разумнијех, ни добра воља до вјештијех, него да све стоји до времена и згоде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Јер човјек не зна времена својега, него као што се рибе хватају мрежом несрећном и као што се птице хватају пруглом, тако се хватају синови човјечији у зао час, кад навали на њих изненада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Видјех и ову мудрост под сунцем, која ми се учини велика:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Бијаше мален град и у њему мало људи; и дође на њ велик цар, и опколи га и начини око њега велике опкопе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'А нађе се у њему сиромах човјек мудар, који избави град мудрошћу својом, а нико се не сјећаше тога сиромаха човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Тада ја рекох: боља је мудрост него снага, ако се и не мараше за мудрост онога сиромаха и ријечи се његове не слушаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Ријечи мудријех људи ваља с миром слушати више него вику онога који заповиједа међу лудима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Боља је мудрост него оружје убојито; али један грјешник квари многа добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Од мртвијех муха усмрди се и поквари уље апотекарско, тако од мало лудости цијена мудрости и слави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Срце је мудрому с десне стране, а лудом је с лијеве стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Безумник и кад иде путем, без разума је и казује свјема да је безуман.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Ако се подигне на те гњев онога који влада, не остављај мјеста својега, јер благост уклања велике гријехе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Има зло које видјех под сунцем, као погрјешка која долази од владаоца:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Лудост се посађује на највише мјесто, и богати сједе на ниском мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Видјех слуге на коњима, а кнезови иду пјешице као слуге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Ко јаму копа, у њу ће пасти, и ко разваљује ограду, ујешће га змија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Ко одмиче камење, удариће се о њих; ко цијепа дрва, није миран од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Кад се затупи гвожђе и оштрице му се не наоштри, тада треба више снаге; али мудрост може боље оправити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Ако уједе змија прије бајања, ништа неће помоћи бајач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Ријечи из уста мудрога љупке су, а безумнога прождиру усне његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Почетак је ријечима уста његовијех лудост, а свршетак говору његову зло безумље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Јер луди много говори, а човјек не зна што ће бити; и ко ће му казати што ће послије њега бити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Луде мори труд њихов, јер не знају ни у град отићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Тешко теби, земљо, кад ти је цар дијете и кнезови твоји рано једу!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Благо теби, земљо, кад ти је цар племенит и кнезови твоји једу на вријеме да се поткријепе а не да се опију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'С лијености угибље се кров и с немарнијех руку прокапљује кућа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Ради весеља готове се гозбе, и вино весели живе, а новци врше све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Ни у мисли својој не псуј цара, ни у клијети, у којој спаваш, не псуј богатога, јер птица небеска однијеће глас и што крила има доказаће ријеч.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Баци хљеб свој поврх воде; јер ћеш га наћи послије много времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Раздијели седморици и осморици; јер не знаш како ће зло бити на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Кад се напуне облаци, просипају дажд на земљу, и ако падне дрво на југ или на сјевер, гдје падне дрво ондје ће остати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Ко пази на вјетар, неће сијати, и ко гледа на облаке, неће жети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Како не знаш који је пут вјетру ни како постају кости у утроби трудне жене, тако не знаш дјела Божијега и како твори све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Изјутра сиј сјеме своје и увече немој да ти почивају руке, јер не знаш шта ће бити боље, ово или оно, или ће обоје бити једнако добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Слатка је свјетлост, и добро је очима гледати сунце;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Али да човјек живи много година и свагда се весели, па се опомене дана тамнијех како ће их бити много, све што је било биће таштина. Радуј се, младићу, за младости своје, и нека се весели срце твоје док си млад, и ходи куда те срце твоје води и куда очи твоје гледају; али знај да ће те за све то Бог извести на суд. Уклони дакле жалост од срца својега, и одрини зло од тијела својега, јер је дјетињство и младост таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Али опомињи се творца својега у младости својој прије него дођу дани зли и приспију године, за које ћеш рећи: нијесу ми миле;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'Прије него помркне сунце и видјело и мјесец и звијезде, и опет дођу облаци иза дажда,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'Кад ће дрхтати стражари кућни и погнути се јунаци, и стати млинарице, што их је мало, и потамњети који гледају кроз прозоре,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'И кад ће се затворити врата с улице, и слабити звека од мљевења, и кад ће се устајати на птичји глас и престати све пјевачице,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'И високога мјеста кад ће се бојати и страшити се на путу, кад ће бадем уцвијетати и скакавац отежати и жеља проћи, јер човјек иде у кућу своју вјечну, и покајнице ће ходити по улицама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'Прије него се прекине уже сребрно, чаша се златна разбије и распе се виједро на извору и сломи се точак на студенцу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'И врати се прах у земљу, како је био, а дух се врати Богу, који га је дао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Таштина над таштинама, вели проповједник, све је таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'А не само мудар бијаше проповједник, него још и народ учаше мудрости, и мотрећи и истражујући сложи много прича.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Стараше се проповједник да нађе угодне ријечи, и написа што је право, ријечи истине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Ријечи су мудријех људи као жалци и као клини ударени; ријечи онијех који их сложише дао је један пастир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'И тако, сине мој, чувај се онога што је преко овога, јер нема краја састављању многих књига, и много читање умор је тијелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Главно је свему што си чуо: Бога се бој, и заповијести његове држи, јер то је све човјеку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Јер ће свако дјело Бог изнијети на суд и сваку тајну, била добра или зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 15, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 16, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Соломунова пјесма над пјесмама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Да ме хоће пољубити пољупцем уста својих! Јер је твоја љубав боља од вина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Мирисом су твоја уља прекрасна; име ти је уље разлито; зато те љубе дјевојке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Вуци ме, за тобом ћемо трчати; уведе ме цар у ложницу своју; радоваћемо се и веселићемо се тобом, спомињаћемо љубав твоју више него вино; прави љубе те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Црна сам, али сам лијепа, кћери Јерусалимске, као шатори Кидарски, као завјеси Соломунови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Не гледајте ме што сам црна, јер ме је сунце опалило; синови матере моје расрдивши се на ме поставише ме да чувам винограде, и не чувах својега винограда, који ја имам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Кажи ми ти, којега љуби душа моја, гдје пасеш, гдје пландујеш? Јер зашто бих лутала међу стадима другова твојих?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Ако не знаш, најљепша између жена, пођи трагом за стадом, и паси јариће своје покрај станова пастирских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Ти си ми, драга моја, као коњи у колима Фараоновијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Образи су твоји окићени гривнама, и грло твоје низовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Начинићемо ти златне гривне са шарама сребрнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Док је цар за столом, нарад мој пушта свој мирис.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Драги ми је мој кита смирне, која међу дојкама мојим почива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Драги ми је мој грозд кипров из винограда Енгадских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Лијепа ти си, драга моја, лијепа ти си! очи су ти као у голубице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Лијеп ти си, драги мој, и љубак! и постеља наша зелени се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Греде су нам у кућама кедрове, даске су нам јелове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Ја сам ружа Саронска, љиљан у долу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Што је љиљан међу трњем, то је драга моја међу дјевојкама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Што је јабука међу дрветима шумским, то је драги мој међу момцима; жељех хлада њезина, и сједох, и род је њезин сладак грлу мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Уведе ме у кућу гдје је гозба а застава му је љубав к мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Поткријепите ме жбановима, придржите ме јабукама, јер сам болна од љубави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Лијева је рука његова мени под главом, а десном ме грли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Заклињем вас, кћери Јерусалимске, срнама и кошутама пољским, не будите љубави моје, не будите је, док јој не буде воља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Глас драгога мојега; ево га, иде скачући преко гора, поскакујући преко хумова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Драги је мој као срна или као јеленче; ево га, стоји иза нашега зида, гледа кроз прозор, вири кроз решетку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Проговори драги мој и рече ми: устани, драга моја, љепотице моја, и ходи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Јер гле, зима прође, минуше дажди, отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Цвијеће се види по земљи, дође вријеме пјевању, и глас грличин чује се у нашој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Смоква је пустила заметке своје, и лоза винова уцвала мирише. Устани, драга моја, љепотице моја, и ходи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Голубице моја у расјелинама каменијем, у заклону врлетном! дај да видим лице твоје, дај да чујем глас твој; јер је глас твој сладак и лице твоје красно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Похватајте нам лисице, мале лисице, што кваре винограде, јер наши виногради цвату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Мој је драги мој, и ја сам његова, он пасе међу љиљанима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Док захлади дан и сјенке отиду, врати се, буди као срна, драги мој, или као јеленче по горама раздијељеним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'На постељи својој ноћу тражих онога кога љуби душа моја, тражих га, али га не нађох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Сада ћу устати, па идем по граду, по трговима и по улицама тражићу онога кога љуби душа моја. Тражих га, али га не нађох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Нађоше ме стражари, који обилазе по граду. Видјесте ли онога кога љуби душа моја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Мало их заминух, и нађох онога кога љуби душа моја; и ухватих га, и нећу га пустити докле га не одведем у кућу матере своје и у ложницу родитељке своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Заклињем вас, кћери Јерусалимске, срнама и кошутама пољским, не будите љубави моје, не будите је, док јој не буде воља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Ко је она што иде горе из пустиње као ступови од дима, поткађена смирном и тамјаном и свакојаким прашком апотекарским?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Гле, одар Соломунов, а око њега шездесет јунака између јунака Израиљевијех:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Сви имају мачеве, вјешти су боју, у свакога је мач о бедру ради страха ноћнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Одар је начинио себи цар Соломун од дрвета Ливанскога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Ступце му је начинио од сребра, узглавље од злата, небо од скерлета, а изнутра настрт љубављу за кћери Јерусалимске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Изидите, кћери Сионске, и гледајте цара Соломуна под вијенцем којим га мати његова окити на дан свадбе његове и на дан весеља срца његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Лијепа ти си, драга моја, лијепа ти си, очи су ти као у голубице између витица твојих; коса ти је као стадо коза које се виде на гори Галаду;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Зуби су ти као стадо оваца једнаких, кад излазе из купала, које се све близне а ниједне нема јалове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Усне су ти као конац скерлета, а говор ти је љубак; као кришка шипка јагодице су твоје између витица твојих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Врат ти је као кула Давидова сазидана за оружје, гдје висе тисућама штитови и свакојако оружје јуначко;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Двије су ти дојке као два ланета близанца, који пасу међу љиљанима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Док дан захлади и сјенке отиду, ићи ћу ка гори смирновој и ка хуму тамјанову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Сва си лијепа драга моја, и нема недостатака на теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Ходи са мном с Ливана, невјесто, ходи са мном с Ливана, да гледаш с врха Аманскога, с врха Сенирскога и Ермонскога, из пећина лавовских, с гора рисовских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Отела си ми срце, сестро моја невјесто, отела си ми срце једнијем оком својим и једнијем ланчићем с грла својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Лијепа ли је љубав твоја, сестро моја невјесто, боља је од вина љубав твоја, и мирис уља твојих од свијех мириснијех ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'С усана твојих капље сат, невјесто, под језиком ти је мед и млијеко, и мирис је хаљина твојих као мирис Ливански.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Ти си као врт затворен, сестро моја невјесто, извор затворен, студенац запечаћен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Биље је твоје воћњак од шипака с воћем краснијем, од кипра и нарда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Од нарда и шафрана, од иђирота и цимета са свакојаким дрвљем за кад, од смирне и алоја и са сваким прекрасним мирисима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Изворе вртовима, студенче воде живе и која тече с Ливана!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Устани сјевере, и ходи јуже, и дуни по врту мом да капљу мириси његови; нека дође драги мој у врт свој, и једе красно воће своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Дођох у врт свој, сестро моја невјесто, берем смирну своју и мирисе своје, једем сат свој и мед свој, пијем вино своје и млијеко своје; једите, пријатељи, пијте, и опијте се, мили моји!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Ја спавам а срце је моје будно; ето гласа драгога мојега, који куца: отвори ми, сестро моја, драга моја, голубице моја, безазлена моја; јер је глава моја пуна росе и коса моја ноћнијех капи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'Свукла сам хаљину своју, како ћу је обући? опрала сам ноге своје, како ћу их каљати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Драги мој промоли руку своју кроз рупу, а што је у мени устрепта од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Ја устах да отворим драгоме својему, а с руку мојих прокапа смирна, и низ прсте моје потече смирна на држак од браве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Отворих драгому своме, али драгога мојега не бјеше, отиде. Бијах изван себе кад он проговори. Тражих га, али га не нађох; виках га, али ми се не одазва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Нађоше ме стражари, који обилазе по граду, бише ме, ранише ме, узеше пријевјес мој с мене стражари по зидовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Заклињем вас, кћери Јерусалимске, ако нађете драгога мојега, шта ћете му казати? Да сам болна од љубави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Што је твој драги бољи од других драгих, о најљепша међу женама? што је твој драги бољи од других драгих, те нас тако заклињеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Драги је мој био и румен, заставник између десет тисућа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Глава му је најбоље злато, коса му је кудрава, црна као гавран;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Очи су му као у голуба на потоцима воденијем, млијеком умивене, и стоје у обиљу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Образи су му као лијехе мириснога биља, као цвијеће мирисно; усне су му као љиљан, с њих капље смирна житка;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'На рукама су му златни прстени, на којима су уковани вирили; трбух му је као свијетла слонова кост обложена сафирима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Гњати су му као ступови од мрамора, углављени на златном подножју; стас му је Ливан, красан као кедри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Уста су му слатка и сав је љубак. Таки је мој драги, таки је мој мили, кћери Јерусалимске. Куда отиде драги твој, најљепша међу женама? куда замаче драги твој, да га тражимо с тобом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Драги мој сиђе у врт свој, к лијехама мириснога биља, да пасе по вртовима и да бере љиљане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Ја сам драгога својега, и мој је драги мој, који пасе међу љиљанима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Лијепа си, драга моја, као Терса, красна си као Јерусалим, страшна као војска са заставама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Одврати очи своје од мене, јер ме распаљују. Коса ти је као стадо коза које се виде на Галаду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Зуби су ти као стадо оваца кад излазе из купала, које се све близне а ниједне нема јалове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Јагодице су твоје између витица твојих као кришка шипка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Шездесет има царица и осамдесет иноча, и дјевојака без броја;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Али је једна голубица моја, безазлена моја, јединица у матере своје, изабрана у родитељке своје. Видјеше је дјевојке и назваше је блаженом; и царице и иноче хвалише је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Ко је она што се види као зора, лијепа као мјесец, чиста као сунце, страшна као војска са заставама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Сиђох у орашје да видим воће у долу, да видим цвате ли винова лоза, пупе ли шипци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Не дознах ништа, а душа ме моја посади на кола Аминадавова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Врати се, врати се Суламко, врати се, врати се, да те гледамо. Шта ћете гледати на Суламци? као чете војничке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Како су лијепе ноге твоје у обући, кћери кнежевска; саставци су бедара твојих као гривне, дјело руку умјетничких.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Пупак ти је као чаша округла, који није никад без пића; трбух ти је као стог пшенице ограђен љиљанима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Двије дојке твоје као два близанца срнчета;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Врат ти је као кула од слонове кости; очи су ти као језера у Есевону на вратима Ватравимским; нос ти је као кула Ливанска која гледа према Дамаску;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Глава је твоја на теби као Кармил, и коса на глави твојој као царска порфира у боре набрана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Како си лијепа и како си љупка, о љубави у милинама!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Узраст ти је као палма, и дојке као гроздови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Рекох: попећу се на палму, дохватићу гране њезине; и биће дојке твоје као гроздови на виновој лози, и мирис носа твојега као јабуке;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'И грло твоје као добро вино, које иде право драгому мојему и чини да говоре усне онијех који спавају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Ја сам драгога својега, и њега је жеља за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Ходи, драги мој, да идемо у поље, да ноћујемо у селима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Ранићемо у винограде да видимо цвате ли винова лоза, замеће ли се грожђе, цвату ли шипци; ондје ћу ти дати љубав своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Мандрагоре пуштају мирис, и на вратима је нашим свакојако красно воће, ново и старо, које за те дохраних, драги мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'О да би ми брат био, да би сао сисе матере моје! нашавши те на пољу пољубила бих те, и не бих била пријекорна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Повела бих те и довела бих те у кућу матере своје; ти би ме учио, а ја бих те појила вином мирисавијем, соком од шипака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Лијева је рука његове мени под главом а десном ме грли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Заклињем вас, кћери Јерусалимске, не будите љубави моје, не будите је, докле јој не буде воља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Ко је она што иде горе од пустиње наслањајући се на драгога свога? Под јабуком пробудих те, гдје те роди мати твоја, гдје те роди родитељка твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Метни ме као печат на срце своје, као печат на мишицу своју. Јер је љубав јака као смрт, и љубавна сумња тврда као гроб; жар је њезин као жар огњен, пламен Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Многа вода не може угасити љубави, нити је ријеке потопити. Да ко даје све имање дома својега за ту љубав, осрамотио би се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Имамо сестру малену, која још нема дојака. Шта ћемо чинити са сестром својом кад буде ријеч о њој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Ако је зид, заградићемо на њему двор од сребра; ако ли врата, утврдићемо их даскама кедровијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Ја сам зид и дојке су моје као куле. Тада постах у очима његовијем као она која нађе мир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Виноград имаше Соломун у Валамону; даде виноград чуварима да сваки доноси за род његов по тисућу сребрника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Мој виноград који ја имам, преда мном је. Нека теби, Соломуне, тисућа, и двије стотине онима који чувају род његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Која наставаш у вртовима! другови слушају глас твој, дај ми да га чујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Брже, драги мој! И буди као срна или као јеленче на горама мириснијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Утвара Исаије сина Амосова, коју видје за Јуду и за Јерусалим за времена Озије, Јоатама, Ахаза и Језекије, царева Јудинијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Чујте, небеса, и слушај, земљо; јер Господ говори: синове одгојих и подигох, а они се одвргоше мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Во познаје господара својега и магарац јасле господара својега, а Израиљ не познаје, народ мој не разумије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Да грјешна народа! народа огрезла у безакоњу! сјемена зликовачкога, синова покваренијех! оставише Господа, презреше свеца Израиљева, отступише натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Што бисте још били бијени кад се све више одмећете? Сва је глава болесна и све срце изнемогло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Од пете до главе нема ништа здрава, него убој и модрице и ране гнојаве, ни исцијеђене ни завијене ни уљем заблажене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Земља је ваша пуста, градови ваши огњем попаљени; ваше њиве једу туђини на ваше очи, и пустош је као што опустошавају туђини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'И оста кћи Сионска као колиба у винограду, као сјеница у градини од краставаца, као град опкољен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Да нам Господ над војскама није оставио мало остатка, били бисмо као Содом, изједначили бисмо се с Гомором.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Чујте ријеч Господњу, кнезови Содомски, послушајте закон Бога нашега, народе Гоморски!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Што ће ми мноштво жртава ваших? вели Господ. Сит сам жртава паљеница од овнова и претилине од гојене стоке, и не марим за крв јунчију и јагњећу и јарећу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Кад долазите да се покажете преда мном, ко иште то од вас, да газите по мом тријему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Не приносите више жртве залудне; на кад гадим се; а о младинама и суботама и о сазивању скупштине не могу подносити безакоња и светковине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'На младине ваше и на празнике ваше мрзи душа моја, досадише ми, додија ми подносити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Зато кад ширите руке своје, заклањам очи своје од вас; и кад множите молитве, не слушам; руке су ваше пуне крви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Умијте се, очистите се, уклоните злоћу дјела својих испред очију мојих, престаните зло чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Учите се добро чинити, тражите правду, исправљајте потлаченога, дајите правицу сироти, браните удовицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Тада дођите, вели Господ, па ћемо се судити: ако гријеси ваши буду као скерлет, постаће бијели као снијег; ако буду црвени као црвац, постаће као вуна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Ако хоћете слушати, добра земаљска јешћете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Ако ли нећете, него будете непокорни, мач ће вас појести, јер уста Господња рекоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Како поста курва вјерни град? Пун бијаше правице, правда наставаше у њему, а сада крвници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Сребро твоје поста троска, вино твоје помијеша се с водом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Кнезови су твоји одметници и другови лупежима; сваки милује мито и иде за даровима; сироти не дају правице, и парница удовичка не долази пред њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Зато говори Господ, Господ над војскама, силни Израиљев: аха! издовољићу се на противницима својим, и осветићу се непријатељима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'И окренућу руку своју на те, и сажећи ћу троске твоје да те пречистим, и уклонићу све олово твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'И поставићу ти опет судије као прије, и савјетнике као испочетка; тада ћеш се звати град праведни, град вјерни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Сион ће се откупити судом, и правдом они који се у њ врате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'А одметници и грјешници сви ће се сатрти, и који остављају Господа, изгинуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Јер ћете се посрамити од гајева које жељесте, и застидјети се од вртова које изабрасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Јер ћете бити као храст којему опада лишће и као врт у ком нема воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'И биће јунак као кучине и дјело његово као искра, и обоје ће се запалити, и неће бити никога да угаси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Ријеч која дође у утвари Исаији сину Амосову за Јуду и за Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Биће у потоња времена гора дома Господњега утврђена уврх гора и узвишена изнад хумова, и стјецаће се к њој сви народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'И ићи ће многи народи говорећи: ходите да идемо на гору Господњу, у дом Бога Јаковљева, и учиће нас својим путовима, и ходићемо стазама његовијем; јер ће из Сиона изаћи закон, и ријеч Господња из Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'И судиће међу народима, и караће многе народе, те ће расковати мачеве своје на раонике, и копља своја на српове, неће дизати мача народ на народ, нити ће се више учити боју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Доме Јаковљев, ходи да идемо по свјетлости Господњој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Али си оставио свој народ, дом Јаковљев, јер су пуни зала источнијех и гатају као Филистеји, и мили су им синови туђински.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'И земља је њихова пуна сребра и злата, и благу њихову нема краја; земља је њихова пуна коња, и колима њиховијем нема краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Пуна је земља њихова и идола; дјелу руку својих клањају се, што начинише прсти њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'И клањају се прости људи, и савијају се главни људи; немој им опростити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Уђи у стијену, и сакриј се у прах од страха Господњега и од славе величанства његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Поносите очи човјечије понизиће се, и висина људска угнуће се, а Господ ће сам бити узвишен у онај дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Јер ће доћи дан Господа над војскама на све охоле и поносите и на свакога који се подиже, те ће бити понижени,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'И на све кедре Ливанске велике и високе и на све храстове Васанске,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'И на све горе високе и на све хумове издигнуте,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'И на сваку кулу високу и на сваки зид тврди,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'И на све лађе Тарсиске и на све ликове миле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Тада ће се поноситост људска угнути и висина се људска понизити, и Господ ће сам бити узвишен у онај дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'И идола ће нестати сасвијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'И људи ће ићи у пећине камене и у рупе земаљске од страха Господњега и од славе величанства његова, кад устане да потре земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Тада ће бацити човјек идоле своје сребрне и идоле своје златне, које начини себи да им се клања, кртицама и слијепијем мишима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'Улазећи у расјелине камене и у пећине камене од страха Господњега и од славе величанства његова, кад устане да потре земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Прођите се човјека, којему је дах у носу; јер шта вриједи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Јер гле, Господ, Господ над војскама узеће Јерусалиму и Јуди потпору и помоћ, сваку потпору у хљебу и сваку потпору у води,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Јунака и војника, судију и пророка и мудраца и старца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Педесетника и угледна човјека, и савјетника и вјешта умјетника и човјека рјечита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'И даћу им кнезове младиће, и дјеца ће им бити господари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'И чиниће силу у народу један другоме и сваки ближњему својему; дијете ће устајати на старца и непоштен човјек на поштена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'И човјек ће ухватити брата својега из куће оца својега говорећи: имаш хаљину, буди нам кнез, овај расап нека је под твојом руком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'А он ће се заклети у онај дан говорећи: нећу бити љекар, нити имам код куће хљеба ни хаљине, не постављајте ме кнезом народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Јер се обори Јерусалим и Јуда паде, јер се језик њихов и дјела њихова противе Господу да драже очи славе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Што се види на лицу њихову свједочи на њих, разглашују гријех свој као Содом, не таје; тешко души њиховој! јер сами себи чине зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Реците праведнику да ће му добро бити, јер ће јести плод од дјела својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Тешко безбожнику! зло ће му бити, јер ће му се наплатити руке његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Народу мојему чине силу дјеца, и жене су им господари. Народе мој! који те воде, заводе те, и кваре пут хода твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Устаје Господ на парбу, стоји да суди народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Господ ће доћи на суд са старјешинама народа својега и с кнезовима његовијем, јер ви потрсте виноград, грабеж од сиромаха у вашим је кућама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Зашто газите народ мој и лице сиромасима сатирете? говори Господ, Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Још говори Господ: што се понијеше кћери Сионске и иду опружена врата и намигујући очима, ситно корачају и звекећу ногама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'Зато ће Господ учинити да оћелави тјеме кћерима Сионским, и откриће Господ голотињу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Тада ће Господ скинути накит с обуће и везове и мјесечиће,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Низове и ланчиће и трепетљике,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'Укоснике и подвезе и појасе и стакалца мирисна и обоце,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Прстене и почеонике,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'Свечане хаљине и огртаче и пријевјесе и тобоце,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'И огледала и кошуљице и оглавља и покривала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'И мјесто мириса биће смрад, и мјесто појаса распојасина, мјесто плетеница ћела, мјесто широких скута припасана врећа, и мјесто љепоте огорјелина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Твоји ће људи пасти од мача и јунаци твоји у рату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'И тужиће и плакаће врата његова, а он ће пуст лежати на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'И у оно вријеме седам ће жена ухватити једнога човјека говорећи: свој ћемо хљеб јести и своје ћемо одијело носити, само да се зовемо твојим именом, скини с нас срамоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'У оно вријеме биће клица Господња на славу и част, и плод земаљски на красоту и дику остатку Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'И ко остане у Сиону и ко још буде у Јерусалиму, зваће се свет, сваки ко буде записан за живот у Јерусалиму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Кад Господ опере нечистоту кћери Сионских и из Јерусалима очисти крв његову духом који суди и сажиже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Господ ће створити над сваким станом на Гори Сионској и над зборовима њезинијем облак дању с димом и свјетлост пламена огњенога ноћу, јер ће над свом славом бити заклон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'И биће колиба, да сјеном заклања дању од врућине и да буде уточиште и заклон од поплаве и од дажда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Запјеваћу сада драгоме својему пјесму драгога својега о винограду његову. Драги мој има виноград на родну брдашцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'И огради га, и отријеби из њега камење, и насади га племенитом лозом, и сазида кулу усред њега, и ископа пивницу у њему, и почека да роди грожђем, а он роди вињагом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Па сада, становници Јерусалимски и људи Јудејци, судите између мене и винограда мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Што је још требало чинити винограду мојему што му не учиних? кад чеках да роди грожђем, зашто роди вињагом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Сада ћу вам казати што ћу учинити винограду својему. Оборићу му ограду, нека опусти; развалићу му зид нека се погази;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Упарложићу га, неће се резати ни копати, него ће расти чкаљ и трње, и заповједићу облацима да не пуштају више дажда на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Да, виноград је Господа над војскама дом Израиљев, и људи су Јудејци мили сад његов; он чека суд, а гле насиља, чека правду, а гле вике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Тешко онима који састављају кућу с кућом, и њиву на њиву настављају, да већ не буде мјеста и ви сами останете у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Од Господа над војскама чух: многе куће опустјеће, у великим и лијепијем неће бити никога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Јер ће десет рала винограда дати један ват, и гомер сјемена даће ефу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Тешко онима који ране, те иду на силовито пиће и остају до мрака док их вино распали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'И на гозбама су им гусле и псалтири и бубњи и свирале и вино; а не гледају на дјела Господња и не виде рада руку његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Зато се народ мој одведе у ропство што не знају, и које поштује гладују, и људство његово гине од жеђи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Зато се раширио гроб и развалио ждријело своје превећ, и сићи ће у њ слава његова и мноштво његово и врева његова и који се веселе у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'И погнуће се прост човјек, и високи ће се понизити, и поносите очи обориће се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Господ над војскама узвисиће се судом, и Бог свети посветиће се правдом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'И јагањци ће пасти по свом обичају, и дошљаци ће јести с пустијех мјеста претилину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Тешко онима који вуку безакоње узицама од таштине, и гријех као ужем колским,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Који говоре: нека похити, нека брзо дође дјело његово, да видимо, и нека се приближи и дође што је наумио светац Израиљев, да познамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Тешко онима који зло зову добро, а добро зло, који праве од мрака свјетлост а од свјетлости мрак, који праве од горкога слатко а од слаткога горко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Тешко онима који мисле да су мудри, и сами су себи разумни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Тешко онима који су јаки пити вино и јунаци у мијешању силовита пића.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'Који правдају безбожника за поклон, а праведнима узимају правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Зато као што огањ прождире стрњику и сламе нестаје у пламену, тако ће коријен њихов бити као трулеж и цвијет њихов отићи ће као прах, јер одбацише закон Господа над војскама и презреше ријеч свеца Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Зато се распали гњев Господњи на народ његов, и махнув руком својом на њ удари га да се горе задрмаше и мртва тјелеса његова бише као блато по улицама. Код свега тога гњев се његов не одврати, него је рука његова још подигнута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'И подигнуће заставу народима даљнијем, и зазвиждаће им с краја земље; и гле, они ће доћи одмах, брзо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Неће бити међу њима уморна ни сустала, ни дремљива ни санљива, никоме се неће распасати појас око њега, нити ће се коме откинути ремен на обући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Стријеле ће им бити оштре, и сви лукови њихови запети; копита у коња њиховијех биће као кремен и точкови њихови као вихор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Рика ће им бити као у лава, и рикаће као лавићи; бучаће и уграбиће плијен и однијети га, и неће бити никога да отме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Бучаће над њим у то вријеме као што море бучи. Тада ће погледати на земљу, а то мрак и страх, и свјетлост ће се помрачити над погибљу њиховом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Године које умрије цар Озија видјех Господа гдје сједи на пријестолу високу и издигнуту, и скут му испуњаваше цркву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Серафими стајаху више њега, сваки их имаше шест крила: двјема заклањаше лице своје и двјема заклањаше ноге своје, а двјема лећаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'И викаху један другоме говорећи: свет, свет, свет је Господ над војскама; пуна је сва земља славе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'И задрмаше се прагови на вратима од гласа којим викаху, и дом се напуни дима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'И рекох: јаох мени! погибох, јер сам човјек нечистијех усана, и живим усред народа нечистијех усана, јер цара Господа над војскама видјех својим очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'А један од серафима долетје к мени држећи у руци жив угљен, који узе с олтара клијештима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'И дотаче се уста мојих, и рече: ево, ово се дотаче уста твојих, и безакоње твоје узе се, и гријех твој очисти се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Потом чух глас Господњи гдје рече: кога ћу послати? и ко ће нам ићи? А ја рекох: ево мене, пошљи мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'А он рече: иди, и реци томе народу: слушајте али нећете разумјети, гледајте али нећете познати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Учини да одебља срце томе народу и уши да им отежају, и очи им затвори, да не виде очима својим и ушима својим да не чују и срцем својим да не разумију и не обрате се и не исцијеле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'А ја рекох: докле Господе? А он рече: докле не опусте градови да буду без становника и куће да буду без људи, и земља докле сасвијем не опусти,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'И докле Господ оправи далеко људе и буде сама пустош у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Али ће још бити у њој десетина, па ће се и она затрти; али као храст или бријест којима и кад збаце лишће остаје стабло, тако ће свето сјеме бити њезино стабло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'У вријеме Ахаза сина Јотама сина Озије цара Јудина дође Ресин цар Сирски и Факеј син Ремалијин цар Израиљев на Јерусалим да га бију, али га не могоше узети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'И дође глас дому Давидову и рекоше: Сирија се сложи с Јефремом. А срце Ахазово и срце народа његова устрепта као дрвеће у шуми од вјетра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Тада рече Господ Исаији: изиди на сусрет Ахазу, ти и Сеар-јасув син твој, накрај јаза горњега језера, на пут код поља бјељарева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'И реци му: чувај се и буди миран, не бој се и срце твоје нека се не плаши од два краја овијех главања што се пуше, од распаљенога гњева Ресинова и Сирскога и сина Ремалијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Што се Сирци и Јефрем и син Ремалијин договорише на твоје зло говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Хајдемо на Јудејску да јој досадимо и да је освојимо и да поставимо у њој царем сина Тавеилова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Зато овако вели Господ Бог: неће се то учинити, неће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Јер је глава Сирији Дамаск, а Дамаску је глава Ресин; и до шездесет и пет година сатрће се Јефрем тако да више неће бити народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'И глава је Јефрему Самарија, а Самарији је глава син Ремалијин. Ако не вјерујете, нећете се одржати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'И још рече Господ Ахазу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Ишти знак од Господа Бога својега, ишти оздо из дубине или озго с висине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'А Ахаз рече: нећу искати, нити ћу кушати Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Тада рече Исаија: слушајте сада, доме Давидов; мало ли вам је што досађујете људима, него досађујете и Богу мојему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Зато ће вам сам Господ дати знак; ето дјевојка ће затрудњети и родиће сина, и надјенуће му име Емануило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Масло и мед јешће, докле не научи одбацити зло а изабрати добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Јер прије него научи дијете одбацити зло а изабрати добро, оставиће земљу, на коју се гадиш, два цара њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Господ ће пустити на те и на народ твој и на дом оца твојега дане, каких није било од кад се Јефрем одвоји од Јуде, преко цара Асирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'И тада ће Господ зазвиждати мухама које су накрај ријека Мисирских, и пчелама које су у земљи Асирској;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'И доћи ће и попадаће све у пусте долине и у камене расјелине и на све честе и на свако дрвце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Тада ће Господ обријати бритвом закупљеном испреко ријеке, царем Асирским, главу и длаке по ногама, и браду сву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'И тада ко сачува кравицу и двије овце,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'Од мноштва млијека што ће давати јешће масло; јер масло и мед јешће ко год остане у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'И тада ће свако мјесто гдје има тисућа чокота за тисућу сребрника зарасти у чкаљ и трње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Са стријелама и с луком ићи ће се онамо, јер ће сва земља бити чкаљ и трње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'А на све горе које су се копале мотиком, на њих неће доћи страх од чкаља и трња, него ће бити испуст воловима и газиће их овце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'И рече ми Господ: узми књигу велику и напиши у њој писмом човјечијим: брз на плијен, хитар на грабеж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'И узех вјерне свједоке, Урију свештеника и Захарију сина Јеверехијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Потом приступих к пророчици, и она затрудње и роди сина. А Господ ми рече: надјени му име: брз на плијен, хитар на грабеж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Јер прије него дијете научи викати: оче мој и мајко моја, однијеће се благо Дамаштанско и плијен Самаријски пред царем Асирским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'И још ми рече Господ говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Што овај народ не мари за воду Силоамску која тече тихо, и радује се Ресину и сину Ремалијину,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Зато, ево, Господ ће навести на њих воду из ријеке силну и велику, цара Асирскога и сву славу његову, те ће изаћи из свијех потока својих, и тећи ће поврх свијех брегова својих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'И навалиће преко Јуде, плавиће и разливаће се и доћи до грла, и крила ће јој се раширити преко свеколике земље твоје, Емануило!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Здружујте се, народи, али ћете се потрти; чујте сви који сте у даљној земљи: оружајте се, али ћете се потрти; оружајте се, али ћете се потрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Договарајте се, договор ће вам се разбити: реците ријеч, неће бити од ње ништа, јер је с нама Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Јер ми овако рече Господ ухвативши ме за руку и опоменувши ме да не идем путем овога народа, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Не говорите буна, кад год овај народ каже буна, и не бојте се чега се он боји, и не плашите се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Господа над војскама светите; и он нека вам је страх и бојазан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'И биће вам светиња, а камен за спотицање и стијена за саблазан објема домовима Израиљевијем, замка и мрежа становницима Јерусалимским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'И спотакнуће се многи и пашће и сатрће се, заплешће се и ухватиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Свежи свједочанство, запечати закон мојим ученицима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Чекаћу дакле Господа, који је сакрио лице своје од дома Јаковљева, и уздаћу се у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Ево ја и дјеца коју ми је дао Господ јесмо знак и чудо Израиљу од Господа над војскама, који настава на гори Сиону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'И ако вам реку: питајте враче и гатаре, који шапћу и мрмљају; реците: не треба ли народ да пита Бога својега? или ће питати мртве мјесто живијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'Закон и свједочанство тражите. Ако ли ко не говори тако, њему нема зоре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'И ходиће по земљи потуцајући се и гладујући; и кад буде гладан, љутиће се и псовати цара својега и Бога својега горе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'А кад погледа на земљу, а то невоља и мрак и тешка мука, и он загнан у таму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 23, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Али неће се онако замрачити притијешњена земља као прије кад се дотаче земље Завулонове и земље Нефталимове, или као послије кад досађиваше на путу к мору с оне стране Јордана Галилеји незнабожачкој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Народ који ходи у тами видјеће видјело велико, и онима који сједе у земљи гдје је смртни сјен засвијетлиће видјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Умножио си народ, а нијеси му увеличао радости; али ће се радовати пред тобом као што се радују о жетви, као што се веселе кад дијеле плијен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Јер си сломио јарам у ком вуцијаше, и штап којим га бијаху по плећима и палицу насилника његова као у дан Мадијански.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Јер ће обућа свакога ратника који се бије у граји и одијело у крв уваљано изгорјети и бити храна огњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Јер нам се роди дијете, син нам се даде, којему је власт на рамену, и име ће му бити: дивни, савјетник, Бог силни, отац вјечни, кнез мирни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Без краја ће расти власт и мир на пријестолу Давидову и у царству његову да се уреди и утврди судом и правдом отсада довијека. То ће учинити ревност Господа над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Господ посла ријеч Јакову, и она паде у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'И знаће сав народ, Јефрем и становници Самаријски, који охоло и поносита срца говоре:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Падоше опеке, али ћемо ми зидати од тесна камена; дудови су посјечени, али ћемо ми замијенити кедрима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Али ће Господ подигнути противнике Ресинове на њ, и скупиће непријатеље његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Сирце с истока и Филистеје са запада, те ће ждријети Израиља на сва уста. Код свега тога неће се одвратити гњев његов, него ће рука његова још бити подигнута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Јер се народ неће обратити к оному ко га бије, и неће тражити Господа над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Зато ће одсјећи Господ Израиљу главу и реп, грану и ситу у један дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Старјешина и угледан човјек то је глава, а пророк који учи лаж то је реп.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Јер који воде тај народ, они га заводе, а које воде, они су пропали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Зато се Господ неће радовати младићима његовијем, и на сироте његове и на удовице његове неће се смиловати, јер су свиколики лицемјери и зликовци, и свака уста говоре неваљалство. Код свега тога неће се одвратити гњев његов, него ће рука његова још бити подигнута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Јер ће се разгорјети безбожност као огањ, који сажеже чкаљ и трње, па упали густу шуму, те отиде у дим високо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Од гњева Господа над војскама замрачиће се земља и народ ће бити као храна огњу, нико неће пожалити брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'И зграбиће с десне стране, па ће опет бити гладан, и јешће с лијеве стране, па се опет неће наситити; сваки ће јести месо од мишице своје, Манасија Јефрема, и Јефрем Манасију, а обојица ће се сложити на Јуду. Код свега тога неће се одвратити гњев његов, него ће рука његова још бити подигнута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Тешко онима који постављају законе неправедне и који пишу неправду,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Да одбију од суда убоге, и да отимају правицу сиромасима народа мојега, да би им плијен биле удовице и сироте грабеж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'А шта ћете чинити у дан похођења и погибли која ће доћи из далека? коме ћете прибјећи за помоћ? гдје ли ћете оставити славу своју?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Да се не би унизила међу робље и међу побијене пала? Код свега тога неће се одвратити гњев његов, него ће рука његова још бити подигнута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Тешко Асиру, шиби гњева мојега, ако и јест палица у руци његовој моја јарост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'На народ лицемјерни послаћу га, и заповједићу му за народ на који се гњевим, да плијени и отима, и да га изгази као блато на улицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Али он неће тако мислити и срце његово неће тако судити, него му је у срцу да затре и истријеби многе народе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Јер ће рећи: кнезови моји нијесу ли сви цареви?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Није ли Халан као Хархемис? није ли Емат као Арфад? није ли Самарија као Дамаск?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Како је рука моја нашла царства лажнијех богова, којих ликови бијаху јачи од Јерусалимских и Самаријских,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'Нећу ли учинити Јерусалиму и његовијем лажнијем боговима онако како сам учинио Самарији и њезинијем лажнијем боговима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Али кад сврши Господ све дјело своје на гори Сионској и у Јерусалиму, тада ћу обићи плод охолога срца цара Асирскога и славу поноситијех очију његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Јер рече: крјепошћу руке своје учиних и мудрошћу својом, јер сам разуман; и премјестих међе народима и благо њихово заплијених и као јунак оборих становнике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'И рука моја нађе као гнијездо богатство у народа, и како се купе јајца остављена тако покупих сву земљу, и не би никога да махне крилом или да отвори уста и писне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Хоће ли се сјекира величати над онијем који њом сијече? хоће ли се пила разметати над онијем који њом ради? као да би прут махао онијем који га дигне, као да би се хвалио штап да није од дрвета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Зато ће Господ, Господ над војскама, пустити на претиле његове мршу, и славу ће његову потпалити да гори као огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Јер ће видјело Израиљево бити огањ, и светац ће његов бити пламен, и упалиће и сажећи трње његово и чкаљ његов у један дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'И красоту шуме његове и њиве његове, од душе до тијела, уништиће, и биће као бјегунац кад изнемогне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'И што остане дрвета шуме његове, биће мало, да би их дијете могло пописати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'И у то вријеме остатак Израиљев и који се избаве у дому Јаковљеву неће се више ослањати на онога ко их бије, него ће се ослањати на Господа свеца Израиљева истином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Остатак ће се обратити, остатак Јаковљев, к Богу силноме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Јер ако буде народа твојега, Израиљу, као пијеска морскога, остатак ће се његов обратити. Погибао је одређена, разлиће се правда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Јер ће Господ, Господ над војскама, извршити погибао одређену у свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Зато овако вели Господ, Господ над војскама: не бој се Асирца, народе мој, који наставаш на гори Сиону; прутом ће те ударити и штап свој подигнуће на те као у Мисиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Јер још мало, и гњев ће престати; тада ће се јарост моја обратити на њихову погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Јер ће подигнути на њ Господ над војскама бич, те ће бити као расап Мадијански код камена Орива и као штап његов на мору, и подигнуће га као у Мисиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'И тада ће се скинути бреме његово с рамена твојега и јарам његов с врата твојега, и изломиће се јарам од помазања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Дође у Ајат, прође у Мигрон, у Михмасу распрти пртљаг свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Пођоше кланцем, у Гаваји заноћише, препаде се Рама, Гаваја Саулова побјеже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Вичи иза гласа, кћери Галимова; нек се чује у Лаис, јадни Анатоте!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Мадмина побјеже, становници Гевимски утекоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Још један дан, па ће стајати у Нову, махнуће руком својом на гору кћери Сионске, на хум Јерусалимски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Гле, Господ, Господ над војскама, окресаће силом гране; што је високо посјећи ће, и што је уздигнуто снизиће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'И густу ће шуму исјећи сјекиром, и Ливан ће пасти од силнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Али ће изаћи шибљика из стабла Јесејева, и изданак из коријена његова изникнуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'И на њему ће почивати дух Господњи, дух мудрости и разума, дух савјета и силе, дух знања и страха Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'И мирисање ће му бити у страху Господњем, а неће судити по виђењу својих очију, нити ће по чувењу својих ушију карати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Него ће по правди судити сиромасима и по правици карати кротке у земљи, и удариће земљу прутом уста својих, и духом усана својих убиће безбожника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'И правда ће му бити појас по бедрима, и истина појас по боцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'И вук ће боравити с јагњетом, и рис ће лежати с јаретом, теле и лавић и угојено живинче биће заједно, и мало дијете водиће их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'И крава и медвједица заједно ће пасти, млад њихова лежаће заједно, и лав ће јести сламу као во.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'И дијете које сиса играће се над рупом аспидином, и дијете одбијено од сисе завлачиће руку своју у рупу змије василинске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Неће удити ни потирати на свој светој гори мојој, јер ће земља бити пуна познања Господњега као море воде што је пуно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'И у то ће вријеме за коријен Јесејев, који ће бити застава народима, распитивати народи, и почивалиште његово биће славно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'И тада ће Господ опет подигнути руку своју да задобије остатак народа својега, што остане од Асирске и од Мисира и од Патроса и од Етиопске и од Елама и од Сенара и од Емата и од острва морских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'И подигнуће заставу народима и прогнане Израиљеве и расијане Јудине сабраће с четири краја земаљска,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'И нестаће зависти Јефремове, и непријатељи Јудини истријебиће се; Јефрем неће завидјети Јуди, а Јуда неће злобити Јефрему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Него ће сложно летјети на плећа Филистејима к западу; заједно ће плијенити народе источне; на Едомце и Моавце дигнуће руке своје, и синови Амонови биће им покорни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'И Господ ће пресушити залив мора Мисирскога, и махнуће руком својом сврх ријеке са силнијем вјетром својим, и удариће је по седам кракова да се може прелазити у обући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'И биће пут остатку народа његова, што остане од Асирске, као што је био Израиљу кад изиде из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'И рећи ћеш у оно вријеме: хвалим те, Господе, јер си се био разгњевио на ме, па се одвратио гњев твој, и утјешио си ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Гле, Бог је спасење моје, уздаћу се и нећу се бојати, јер ми је сила и пјесма Господ Бог, он ми би спаситељ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'С радошћу ћете црпсти воду из извора овога спасења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'И тада ћете рећи: хвалите Господа, гласите име његово, јављајте по народима дјела његова, напомињите да је високо име његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Појте Господу, јер учини велике ствари, нека се зна по свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Кликуј и пјевај, која сједиш у Сиону, јер је светац Израиљев велик посред вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Бреме Вавилону, које видје Исаија син Амосов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'На гори високој подигните заставу, вичите им иза гласа, машите руком, нека уђу на врата кнежевска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Ја сам заповједио изабранима својим и дозвао сам јунаке своје да изврше гњев мој који се радују с величине моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Вика стоји људства на горама као да је велик народ, вика и врева царства скупљенијех народа; Господ над војскама прегледа војску убојиту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Долазе из даљне земље, с краја небеса, Господ и оруђа срдње његове, да затре сву земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Ридајте, јер је близу дан Господњи; доћи ће као пустош од свемогућега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Зато ће свака рука клонути, и свако срце човјечије растопити се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'И они ће се смести, муке и болови спопашће их, мучиће се као породиља, препашће се један од другога, лица ће им бити као пламен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Ево, иде дан Господњи љути с гњевом и јарошћу да обрати земљу у пустош, и грјешнике да истријеби из ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Јер звијезде небеске и прилике небеске неће пустити свјетлости своје, сунце ће помрчати о рођају свом, и мјесец неће пустити свјетлости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'И походићу васиљену за злоћу, и безбожнике за безакоње; и укинућу разметање охолијех, и понос силнијех оборићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Учинићу да ће човјек више вриједити него злато чисто, више него злато Офирско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Зато ћу затрести небо, и земља ће се покренути са свога мјеста од јарости Господа над војскама и у дан кад се распали гњев његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'И биће као срна поплашена и као стадо којега нико не сабира; свак ће гледати за својим народом, и свак ће бјежати у своју земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Ко се год нађе, биће прободен, и који се год скупе, погинуће од мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'И дјецу ћу им размрскати на њихове очи, куће ћу им оплијенити и жене ћу им срамотити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Ево, ја ћу подигнути на њих Миде, који неће марити за сребро, нити ће злата искати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Него ће из лукова дјецу убијати, ни на плод у утроби неће се смиловати, нити ће дјеце жалити око њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'И Вавилон, урес царствима и дика слави Халдејској, биће као Содом и Гомор кад их Бог затр.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Неће се у њему живјети нити ће се ко населити од кољена до кољена, нити ће Арапин разапети у њему шатора, нити ће пастири почивати онуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Него ће почивати ондје дивље звијери, и куће ће њихове бити пуне великих змија, и ондје ће наставати сове, и авети ће скакати онуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'И довикиваће се буљине у пустијем кућама и змајеви у дворовима веселијем. А доћи ће његово вријеме, и близу је, и дани његови његови неће се протегнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Јер ће се смиловати Господ на Јакова, и опет ће изабрати Израиља, и намјестиће их у земљи њиховој, и прилијепиће се к њима дошљаци и придружиће се дому Јаковљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Јер ће их узети народи и одвести на мјесто њихово, и наслиједиће их Израиљци у земљи Господњој да им буду слуге и слушкиње, и заробиће оне који их бјеху заробили, и биће господари својим насилницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'И кад те смири Господ од труда твојега и муке и од љутога ропства у ком си робовао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'Тада ћеш изводити ову причу о цару Вавилонском и рећи ћеш: како неста настојника, неста данка?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Сломи Господ штап безбожницима, палицу владаоцима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Која је љуто била народе без престанка, и гњевно владала над народима, и гонила немилице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Сва земља почива и мирна је; пјевају иза гласа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Веселе се с тебе и јеле и кедри Ливански говорећи: откако си пао, не долази нико да нас сијече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Пакао доље усколеба се тебе ради да те срете кад дођеш, пробуди ти мртваце и све кнезове земаљске, диже с пријестола њиховијех све цареве народне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Сви ће проговорити и рећи теби: и ти ли си изнемогао као ми? изједначио се с нама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Спусти се у пакао понос твој, звека псалтира твојих; прострти су пода те мољци, а црви су ти покривач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Како паде с неба, звијездо данице, кћери зорина? како се обори на земљу који си газио народе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'А говорио си у срцу свом: изаћи ћу на небо, више звијезда Божијих подигнућу пријесто свој, и сјешћу на гори зборној на страни сјеверној;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Изаћи ћу у висине над облаке, изједначићу се с вишњим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'А ти се у пакао сврже, у дубину гробну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Који те виде погледаће на те, и гледаће те говорећи: то ли је онај који је тресао земљу, који је дрмао царства,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Који је васиљену обраћао у пустињу, и градове њезине раскопавао? робље своје није отпуштао кући?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Сви цареви народни, свиколики, леже славно, сваки у својој кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'А ти се избаци из гроба својега, као гадна грана, као хаљина побијенијех, мачем прободенијех, који слазе у јаму камену, као погажен стрв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Нећеш се здружити с њима погребом, јер си земљу своју затро, народ си свој убио; неће се спомињати сјеме зликовачко док је вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Приправите покољ синовима његовијем за безакоње отаца њиховијех да се не подигну и не наслиједе земље и не напуне васиљене градовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Јер ћу устати на њих, говори Господ над војскама, и затрћу име Вавилону и остатак, и сина и унука, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'И начинићу од њега стан ћуковима и језера водена, и омешћу га метлом погибли, говори Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Закле се Господ над војскама говорећи: доиста, биће како сам смислио, и како сам наумио извршиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Потрћу Асирца у земљи својој, на горама својим изгазићу га; тада ће се скинути с њих јарам његов, и бреме његово с плећа њиховијех скинуће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'То је намишљено свој земљи, и то је рука подигнута на све народе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Јер је Господ над војскама наумио, ко ће разбити? и његову руку подигнуту ко ће одвратити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Године које умрије цар Ахаз би објављено ово бреме:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Немој се радовати, земљо Филистејска сваколика, што се сломи прут онога који те је био; јер ће из коријена змијињега никнути змија василинска, и плод ће му бити змај огњени крилати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'И првенци сиромашки нахраниће се, и убоги ће почивати без страха; а твој ћу коријен уморити глађу, и остатак твој он ће побити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Ридајте, врата; вичи, граде; растопила си се, сва земљо Филистијска, јер са сјевера иде дим и нико се неће осамити у зборовима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'И шта ће се одговорити посланицима народнијем? Да је Господ основао Сион и да ће у њ утјецати невољници народа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Бреме Моаву. Да, обноћ се раскопа Ар Моавски и пропаде; да, обноћ се раскопа Кир Моавски и пропаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Отиде у дом и у Девон, на висине, да плаче: Моав ће ридати за Невоном и за Медевом, све ће му главе бити ћелаве, свака брада оскубена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'По улицама ће његовијем припасивати костријет, на крововима његовијем и на улицама његовијем све ће ридати сузе лијући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'И викаће Есевон и Елеала, до Јасе чуће им се глас; и војници ће Моавски викати, душа ће се у сваком узмучити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Срце моје вапије за Моавом; бјегунци његови побјегоше дори до Сигора као јуница трећакиња; јер ће се ићи уз брдо Луитско плачући, и путем Оронаимским разлијегаће ће се јаук.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Јер ће нестати вода Нимримских, јер ће посахнути биље, нестаће траве, зелени неће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'И зато што су остављали и што су чували однијеће се на поток Арапски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Јер ће вика ићи око међа Моавских, до Еглаима јаук њихов, и до Вир-Елима јаук њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Јер ће се вода Димонска напунити крви; и још ћу дометнути Димону, на бјегунце Моавске и на остатак земаљски послаћу лавове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Шаљите јагањце господару земаљском, од Селе до пустиње, ка гори кћери Сионске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Јер ће бити кћери Моавске на бродовима Арнонским као птица која лута, отјерана с гнијезда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Учини вијеће, народе, начини сјен у подне као ноћ, заклони изагнане, немој издати бјегунаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Нека код тебе бораве изгнани моји, Моаве; буди им заклон од пустошника; јер ће нестати насилника, престаће пустошење, истријебиће се са земље који газе друге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'И утврдиће се пријесто милошћу, и на њему ће сједјети једнако у шатору Давидову који ће судити и тражити што је право и бити брз да чини правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Чусмо за охолост Моава врло поноситога, за понос његов и охолост и обијест његову; лажи његове неће бити тврде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Зато ће ридати Моавац над Моавцем, сви ће ридати; над темељима Кир-Аресетским уздисаћете јер су разваљени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'И поља Есевонска посушише се и чокот Сивамски; господа народна потрше красне лозе његове, које досезаху до Јазира и вијаху се по пустињи; одводе његове пружаху се и прелажаху преко мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Зато ћу плакати плачем Јазирским за чокотом Сивамским; заљеваћу те сузама својим, Есевоне и Елеало, јер пјесма о љетини твојој и о жетви твојој паде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'И неста радости и весеља с поља роднога, у виноградима се не пјева ни подвикује, вина у кацама не гази газилац; учиних крај пјесмама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Зато утроба моја јечи као гусле за Моавом, и срце моје за Кир-Ересом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'И кад се види да се уморио Моав на висини својој, ући ће у светињу своју да се помоли; али ништа неће свршити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Ово је ријеч што рече Господ за Моава давно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'А сада вели Господ говорећи: до три године, као што су године најамничке, олошаће слава Моавова са свијем мноштвом његовијем, и што остане биће врло мало и нејако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Бреме Дамаску. Гле, Дамаск ће се укинути да не буде више град, него ће бити гомила развалина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Градови Ароирски биће остављени, биће за стада, те ће у њима почивати, и нико их неће плашити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Нестаће градова Јефремовијех и царства у Дамаску и остатку Сирском, биће као слава синова Израиљевијех, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'И у тај ће дан истанчати слава Јаковљева, и дебело тијело његово омршаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Јер ће бити као кад жетелац сабира жито и руком жање класје, и биће као кад се купи класје у долини Рафајској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Али ће се оставити у њој пабирци као кад се отресе маслина, па двије три остану у врху, и четири пет на роднијем гранама, вели Господ Бог Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'У то ће вријеме човјек погледати на творца својега, и очи његове гледаће на свеца Израиљева;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'А неће погледати на олтаре, дјело руку својих, нити ће гледати на оно што су начинили прсти његови, ни на лугове ни на ликове сунчане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'У то ће вријеме тврди градови његови бити као остављен грм и огранак, јер ће се оставити ради синова Израиљевијех, и биће пустош.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Јер си заборавио Бога спасења својега, и нијеси се сјећао стијене силе своје; зато сади красне садове и лозу страну пресађуј;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'Дању ради да узрасте што посадиш, и јутром гледај да ти сјеме никне; али кад дође до брања разграбиће се, и остаће ти љута жалост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Тешко мноштву великих народа, што буче као што буче мора, и узаврелијем народима, којих стоји врева као силнијех вода;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Врева стоји народа као великих вода; али ће повикати на њих, и они ће побјећи далеко, и биће гоњени као пљева по брдима од вјетра и као прах од вихора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Увече ето страха, и прије него сване нема никога. То је дио онијех који нас газе, и нашљедство онијех који отимљу од нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Тешко земљи која сјен чини крилима с оне стране ријека Етиопских;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'Која шаље посланике преко мора, у лађама од сите по водама, говорећи: идите, брзи гласници, к народу расијану и оплијењену, к народу страшну откако је досад, к народу размјерену и погажену, којему земљу разносе ријеке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Сви који живите на свијету и станујете на земљи, кад се дигне застава на горама, гледајте, и кад затруби труба, слушајте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Јер овако ми рече Господ: умирићу се и гледаћу из стана својега, као врућина која суши послије дажда и као росан облак о врућини жетвеној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Јер прије бербе, кад напупе пупци и од цвијета постане грозд и стане зрети, окресаће одводе косијером, и узеће лозу и отсјећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Све ће се оставити птицама горским и звијерима земаљским; и птице ће љетовати на њима, а свакојаке звијери земаљске зимоваће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Тада ће се донијети дар Господу над војскама од народа расијанога и оплијењенога, од народа страшнога откако је досад, од народа размјеренога и погаженога, којему земљу разносе ријеке, к мјесту имена Господа над војскама, ка гори Сионској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Бреме Мисиру. Гле, Господ сједећи на облаку лаку доћи ће у Мисир; и затрешће се од њега идоли Мисирски, и срце ће се растопити у Мисирцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'И раздражићу Мисирце једне на друге, те ће војевати брат на брата и пријатељ на пријатеља, град на град, царство на царство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'И нестаће духа Мисиру, и намјеру његову разбићу; тада ће питати своје идоле и опсјенаре и враче и гатаре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'И предаћу Мисирце у руке жестоким господарима, и љут ће цар владати њима, вели Господ, Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'И нестаће воде из мора, и ријека ће пресахнути и засушити се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'И ријеке ће отећи, опашће и пресахнути потоци Мисирски, трска и сита посушиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Трава крај потока, на ушћу потока, и сви усјеви крај потока посахнуће и нестаће их и пропашће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'И тужиће рибари и сјетоваће сви који бацају удицу, и који разапињу мрежу по водама забринуће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'И стидјеће се који раде од танкога лана, и који ткају танко бијело платно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'И насипи ће му се развалити, и који заграђују рибњаке, сви ће бити жалосна срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Доиста, кнезови су Соански безумни, и савјет мудријех савјетника Фараоновијех луд је. Како можете говорити Фараону: ја сам син мудријех, син старијех царева?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Гдје су? гдје су мудраци твоји? Нека ти кажу ако знаду што је наумио за Мисир Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Полудјеше кнезови Саонски; преварише се кнезови Нофски; преластише Мисир главе племена његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Господ је излио међу њих дух пријеваран, те учинише да посрће Мисир у свијем пословима као што посрће пијан човјек бљујући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'И неће бити дјела у Мисиру што би учинила глава или реп, грана или сита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'Тада ће бити Мисирци као жене; бојаће се и дрктати од руке Господа над војскама кад замахне на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'И земља ће Јудина бити страх Мисиру; ко је се год опомене, препашће се ради намјере Господа над војскама што је наумио супрот њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'У то ће вријеме бити пет градова у земљи Мисирској који ће говорити језиком Хананским и заклињати се Господом над војскама; један ће се звати град Ахерес.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'У то ће вријеме бити олтар Господњи усред земље Мисирске, и споменик Господњи на међи њезиној;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'И биће знак и свједочанство Господу над војскама, у земљи Мисирској. Кад стану викати ка Господу на насилнике, он ће им послати спаситеља и кнеза и избавиће их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'И биће познат Господ Мисирцима, и познаће Мисирци Господа у то вријеме, и служиће му жртвама и дарима, и завјетоваће завјете Господу, и извршиваће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Тако ће Господ ударити Мисир, и ударив исцијелиће, јер ће се обратити ка Господу, умолиће му се, и исцијелиће их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'У то ће вријеме бити пут из Мисира у Асирску, и Асирац ће ићи у Мисир и Мисирац у Асирску, и служиће Господу Мисирци с Асирцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'У то ће вријеме Израиљ бити трећи с Мисирцима и Асирцима, и биће благослов посред земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Јер ће их благословити Господ над војскама говорећи: да је благословен мој народ Мисирски и Асирски, дјело руку мојих, и нашљедство моје, Израиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Године које дође Тартан на Азот, кад га посла Саргон цар Асирски, те би Азот и узе га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'У то вријеме рече Господ преко Исаије сина Амосова говорећи: иди, скини костријет са себе, и изуј обућу с ногу својих. И учини тако и иђаше го и бос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Тада рече Господ: како иде слуга мој Исаија го и бос за знак и чудо што ће бити до три године Мисиру и Етиопској,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'Тако ће одвести цар Асирски у ропство Мисирце, и Етиопљане у сужањство, дјецу и старце, голе и босе и голијех задњица, на срамоту Мисирцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'И препашће се и посрамиће се од Етиопске, узданице своје, и од Мисира, поноса својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'И рећи ће тада који живе на овом острву: гле, то је узданица наша, ка којој притјецасмо за помоћ да се сачувамо од цара Асирскога; како ћемо се избавити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Бреме пустињи на мору. Као вихори који пролазе на југ, тако ће доћи из пустиње, из земље страшне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Љута утвара јави ми се. Невјерник невјеру чини, пустошник пустоши; ходи, Еламе; опколи, Мидијо! свему уздисању учинићу крај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Зато су бедра моја пуна бола; муке ме обузеше као кад се мучи породиља; згурих се чујући, препадох се видећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Срце ми се смете, гроза ме подузе; ноћ милина мојих претвори ми се у страх.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Постави сто, стражар нека стражи; једи, пиј; устајте кнезови, мажите штитове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Јер овако ми рече Господ: иди, постави стражара да ти јави што види.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'И видје кола, и два реда коњика; кола с магарцима и кола с камилама; и пажаше добро великом пажњом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'И повика као лав: господару, ја стојим једнако на стражи дању, и стојим на стражи по сву ноћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'И ево дођоше на колима људи, у два реда коњици. Тада повика и рече: паде, паде Вавилон, и сви резани ликови богова његовијех разбише се о земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Вршају мој, и пшенице гумна мојега! што чух од Господа над војскама, Бога Израиљева, јавих вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Бреме Думи. Виче к мени неко са Сира: стражару! шта би ноћас? стражару! шта би ноћас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Стражар рече: доћи ће јутро, али и ноћ; ако ћете тражити, тражите, вратите се, дођите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Бреме Арапској. По шумама у Арапској ноћиваћете, путници Дедански!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Изнесите воде пред жедне, који живите у земљи Теми, сретите с хљебом бјегунца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Јер ће бјежати од мача, од мача голога, од лука запетога и од жестокога боја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Јер овако ми рече Господ: за годину, као што је година најамничка, нестаће све славе Кидарске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'И што остане храбријех стријелаца синова Кидарских, биће мало; јер Господ Бог Израиљев рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Бреме долини виђења. Што ти је те си сва изашла на кровове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Граде пуни вике и вреве, граде весели! твоји побијени нијесу побијени мачем нити погибоше у боју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Главари твоји узмакоше свиколики, повезаше их стријелци; што се год нађе твојих, сви су повезани, ако и побјегоше далеко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Зато рекох: прођите ме се, да плачем горко; не трудите се да ме тјешите за погибљу кћери народа мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Јер је ово дан муке и потирања и сметње од Господа, Господа над војскама, у долини виђења; обалиће зид, и вика ће бити до горе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'И Елам узе Тул, с колима људи и с коњицима, и Кир истаче штит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'И красне долине твоје напунише се кола, и коњици се намјестише пред вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'И одастрије се застирач Јудин; и погледао си у то вријеме на оружје у кући шумској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'И видјесте да је много пролома на граду Давидову, и сабрасте воду у доњем језеру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'И избројисте куће Јерусалимске, и развалисте куће да утврдите зид.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'И начинисте јаз међу два зида за воду из старога језера; али не погледасте на онога који је то учинио и не обазресте се на онога који је то одавна спремио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'И зва вас Господ над војскама у онај дан да плачете и ридате и да скубете косе и припашете костријет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'А гле, радост и весеље, убијају говеда, кољу овце, једу месо и пију вино говорећи: једимо и пијмо, јер ћемо сјутра умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Али Господ над војскама јави ми: неће вам се опростити ово безакоње до смрти, вели Господ, Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Овако вели Господ, Господ над војскама: иди к оному ризничару, к Сомни, управитељу дворском,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'И реци му: шта ћеш ти ту? и ко ти је ту? те си ту истесао себи гроб? истесао си себи гроб на високу мјесту и спремио си себи стан у камену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Ево, човјече, Господ ће те бацити далеко и затрпаће те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Завитлаће те и хитити као лопту у земљу пространу; ондје ћеш умријети и ондје ће бити кола славе твоје, срамото дому господара својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'И сврћи ћу те с мјеста твојега, и истјераћу те из службе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'И у то вријеме позваћу слугу својега Елијакима сина Хелкијина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'И обући ћу му твоју хаљину, и твојим ћу га појасом опасати, и твоју ћу му власт дати у руку, и биће отац Јерусалимљанима и дому Јудину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'И метнућу му кључ од дома Давидова на раме: кад он отвори, неће нико затворити, и кад он затвори, неће нико отворити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'И као клин углавићу га на тврду мјесту, и биће пријесто славе дому оца својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'И о њему ће се вјешати сва слава дома оца његова, синова и унука, свакојаки судови, и најмањи, и чаше и мјехови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'У то вријеме, вели Господ над војскама, помјериће се клин углављени на тврдом мјесту, и извадиће се и пашће, и тежа што је на њему пропашће; јер Господ рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Бреме Тиру. Ридајте лађе Тарсиске, јер је раскопан, да нема куће нити ко долази. Из земље Китимске јави им се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Умукните који живите на острву, које трговци Сидонски поморци пунише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'И доходи му бијаху по великим водама сјеме Сиорско, жетва с ријеке, и бјеше трг народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Стиди се, Сидоне, јер говори море, сила морска вели: не мучим се порођајем, не рађам, не одгајам момака, не подижем дјевојака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Као што се ожалостише кад чуше за Мисир, тако ће се ожалостити кад чују за Тир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Идите у Тарсис, ридајте острвљани!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Је ли то ваш весели град, којега је старина од давнина? његове ће га ноге занијети далеко у туђинство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Ко је то смислио на Тир, који раздаваше вијенце, чији трговци бјеху кнезови, и прекупци славни на земљи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Господ је над војскама то смислио, да осрамоти понос сваке славе и да поништи све славне на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Пријеђи преко земље своје као поток, кћери Тарсиска; нема више појаса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Руку своју подиже на море, задрма царства; Господ је заповједио за Ханан да се раскопају градови његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'И вели: нећеш се више веселити, осрамоћена дјевојко, кћери Сидонска. Устани, иди у Китим, ни ондје нећеш имати мира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Ето земље Халдејске; тога народа није било; Асур је основа за оне који живљаху у пустињама, подигоше куле у њој, поградише дворове; и обрати се у развалине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Ридајте лађе Тарсиске, јер је раскопан ваш град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'И тада ће Тир бити заробљен седамдесет година, за вијек једнога цара, а послије седамдесет година пјеваће се Тиру као курви:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Узми гусле, иди по граду, заборављена курво; добро ударај, пјевај и попијевај, еда би те се опет опоменули.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Јер послије седамдесет година Господ ће походити Тир, а он ће се вратити на курварску заслугу своју, и курваће се са свијем царствима на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Али ће трговина његова и заслуга његова бити посвећена Господу, неће се остављати ни чувати, него ће трговина његова бити онима који наставају пред Господом да једу до ситости и имају одијело добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Гле, Господ ће испразнити земљу и опустити је, преврнуће је и расијаће становнике њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'И биће свештеник као народ, господар као слуга, госпођа као слушкиња, продавац као купац, који даје у зајам као који узима у зајам, који узима добит као који даје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Сасвијем ће се испразнити земља, и сасвијем ће се оплијенити. Јер Господ рече ову ријеч.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Тужиће земља и опасти, изнемоћи ће васиљена и опасти; изнемоћи ће главари народа земаљскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Јер се земља оскврни под становницима својим, јер преступише законе, измијенише уредбе, раскидоше завјет вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Зато ће проклетство прождријети земљу, и затрће се становници њезини; зато ће изгорјети становници земаљски, и мало ће људи остати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Тужиће вино, увенуће лоза винова, уздисаће сви који су весела срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Престаће весеље уз бубње, нестаће граје онијех који се веселе, престаће весеље уз гусле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Неће пити вина уз пјесме, огркнуће силовито пиће онима који га пију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Разбиће се пусти град, затворене ће бити све куће да нико не улази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Тужњава ће бити по улицама ради вина, проћи ће свако весеље, отићи ће радост земаљска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Пустош ће остати у граду, и врата ће се развалити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Јер ће бити у земљи и у народима као кад се оберу маслине, и као кад се паљеткује послије бербе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Ови ће подигнути глас свој и пјеваће, ради величанства Господњега подвикиваће од мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Зато славите Господа у долинама, на острвима морским име Господа Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'С краја земље чусмо пјесме у славу праведноме; али рекох: олошах! олошах! тешко мени! невјерници невјеру чине, баш невјерници невјеру чине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Страхота и јама и замка пред тобом је, становниче земаљски!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'И ко утече чувши за страхоту, пашће у јаму; а ко ижљезе из јаме, ухватиће се у замку; јер ће се уставе на висини отворити и затрешће се темељи земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Сва ће се земља разбити, сва ће се земља распасти, сва ће се земља усколебати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Сва ће се земља љуљати као пијан човјек, и премјестиће се као колиба, јер ће јој отежати безакоње њезино, те ће пасти и неће више устати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'И у то ће вријеме походити Господ на висини војску високу и на земљи све цареве земаљске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'И скупиће се као што се скупљају сужњи у јаму, и биће затворени у тамницу, и послије много времена биће похођени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'И посрамиће се мјесец и сунце ће се застидјети кад Господ над војскама стане царовати на гори Сиону и у Јерусалиму, и пред старјешинама својим прослави се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Господе, ти си Бог мој, узвишиваћу те, славићу име твоје, јер си учинио чудеса; намјере твоје од старине вјера су и истина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Јер си од града начинио гомилу, и од тврдога града зидине; од града двор за странце, довијека се неће саградити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Зато ће те славити народ силан, град страшнијех народа бојаће те се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Јер си био крјепост убогоме, крјепост сиромаху у невољи његовој, уточиште од поплаве, заклон од жеге, јер је гњев насилнички као поплава која обаљује зид.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Вреву иностранаца прекинуо си као припеку на суху мјесту; као припека сјеном од облака, тако се пјевање насилника прекиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'И Господ ће над војскама учинити свијем народима на овој гори гозбу од претила меса, гозбу од чиста вина, од претила меса с можданима, од вина без талога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'И поквариће на овој гори застирач којим су застрти сви народи, и покривач којим су покривени сви народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Уништиће смрт заувијек, и утрће Господ Господ сузе са свакога лица, и срамоту народа својега укинуће са све земље; јер Господ рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'И рећи ће се у оно вријеме: гле, ово је Бог наш, њега чекасмо, и спашће нас; ово је Господ, њега чекасмо; радоваћемо се и веселићемо се за спасење његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Јер ће рука Господња починути на овој гори, а Моав ће се изгазити на свом мјесту као што се гази слама за гној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'И размахнуће рукама својим сред њега, као што размахује пливач да плива, и обориће охолост његову мишицама руку својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'И град и високе зидове твоје снизиће, обориће, бациће на земљу у прах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Тада ће се пјевати ова пјесма у земљи Јудиној: имамо тврд град; зидови су и опкоп спасење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Отворите врата да уђе народ праведни, који држи вјеру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Ко се тебе држи, чуваш га једнако у миру, јер се у тебе узда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Уздајте се у Господа довијека, јер је Господ Господ вјечна стијена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Јер понижује оне који наставају на висини, град високи обара, обара га на земљу, обраћа га у прах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Те га гази нога, ноге убогих, стопала невољнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Пут је праведнику прав, ти равниш стазу праведноме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'И на путу судова твојих, Господе, чекамо те; твоје име и твој спомен жуди душа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Душом својом жудим тебе ноћу, и духом својим што је у мени тражим те јутром; јер кад су судови твоји на земљи, уче се правди који живе у васиљеној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Ако се и помилује безбожник, не учи се правди, у земљи најправеднијој чини безакоње и не гледа на величанство Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Господе! рука је твоја високо подигнута, а они не виде; видјеће и посрамиће се од ревности за народ, и огањ ће прождријети непријатеље твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Господе! нама ћеш дати мир, јер сва дјела наша ти си нам учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Господе Боже наш, господарише над нама господари други осим тебе, али само тобом помињемо име твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Помријеше, неће оживјети, мртви будући неће устати, јер си их ти походио и истријебио, затро сваки спомен њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Господе, умножио си народ, умножио си народ и прославио си се, али си их загнао на све крајеве земаљске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Господе, у невољи тражише те, изливаше покорну молитву кад си их карао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Као трудна жена кад хоће да се породи па се мучи и виче од бола, таки бијасмо ми пред тобом, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Затрудњесмо, мучисмо се да родимо, и као да родисмо вјетра, никако не помогосмо земљи, нити падоше који живе у васиљеној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Оживјеће мртви твоји, и моје ће мртво тијело устати. Пробудите се, и пјевајте који станујете у праху; јер је твоја роса роса на трави, и земља ће изметнути мртваце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Хајде народе мој, уђи у клијети своје, и закључај врата своја за собом, прикриј се зачас, докле прође гњев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Јер, гле, Господ излази из мјеста својега да походи становнике земаљске за безакоње њихово, и земља ће открити крви своје нити ће више покривати побијенијех својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Тада ће Господ покарати мачем својим љутијем и великим и јаким левијатана, пругу змију, и левијатана, кривуљасту змију, и убиће змаја који је у мору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Тада пјевајте о винограду који рађа црвенијем вином:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Ја Господ чувам га, у свако доба заљеваћу га; дан ноћ чуваћу га да га ко не оштети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Нема гњева у мене; ко ће ставити у бој насупрот мени чкаљ и трње? ја ћу погазити и спалити све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Или нека се ухвати за силу моју да учини мир са мном; учиниће мир са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Једном ће се укоријенити Јаков, процвјетаће и узрасти Израиљ, и напуниће васиљену плодом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Је ли га ударио онако како је ударио оне који њега удараше? је ли га убио онако како су убијени они које је убио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'С мјером га је карао, кад га је одбацио, кад га је однио силнијем вјетром својим источнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Зато ће се тијем очистити безакоње Јаковљево и то ће бити сва корист што ће се узети гријех његов кад све камење олтарно разметне као раздробљено кречно камење и не буде више гајева ни сунчанијех ликова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Јер ће тврди град опустјети и биће стан остављен и занемарен као пустиња; ондје ће пасти теле и ондје ће лијегати, и појешће му гране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Кад се посуше гране, поломиће се; жене ће долазити и ложити их на огањ. Јер је народ неразуман; зато га неће жалити који га је створио, и који га је саздао неће се смиловати на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'У то ће вријеме Господ овијати од обале ријеке до потока Мисирскога, а ви, синови Израиљеви, сабраћете се један по један.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'И тада ће се затрубити у велику трубу, и који се бјеху изгубили у земљи Асирској и који бијаху загнани у земљу Мисирску, доћи ће и клањаће се Господу на светој гори у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Тешко гиздавоме вијенцу пијаница Јефремовијех, увелом цвијету краснога накита њихова, који су уврх роднога дола, пијани од вина!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Гле, у Господа има неко јак и силан као пљусак од града, као олуја која све ломи, као поплава силне воде, кад навали, обориће све на земљу руком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Ногама ће се изгазити гиздави вијенац, пијанице Јефремове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'И увели цвијет краснога накита њихова, што је уврх роднога дола, биће као воће узрело прије љета, које чим ко види, узме у руку и поједе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'У оно ће вријеме Господ над војскама бити славна круна и дичан вијенац остатку народа својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'И дух суда ономе који сједи да суди, и сила онима који узбијају бој до врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Али се и они заносе од вина, и посрћу од силовита пића: свештеник и пророк заносе се од силовита пића, освојило их је вино, посрћу од силовита пића, заносе се у пророковању, спотичу се у суђењу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Јер су сви столови пуни бљувотине и нечистоте, нема мјеста чиста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Кога ће учити мудрости, и кога ће упутити да разумије науку? Дјецу, којој се не даје више млијеко, која су одбијена од сисе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Јер заповијест по заповијест, заповијест по заповијест, правило по правило, правило по правило, овдје мало, ондје мало даваше се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Зато ће неразумљивом бесједом и туђим језиком говорити томе народу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'Јер им рече: ово је починак, оставите уморна да почине; ово је одмор; али не хтјеше послушати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'И биће им ријеч Господња, заповијест по заповијест, заповијест по заповијест, правило по правило, правило по правило, мало овдје, мало ондје, да иду и падају наузнако и разбију се, и да се заплету у замке и ухвате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Зато слушајте ријеч Господњу, људи потсмијевачи, који владате народом што је у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Што рекосте: ухватисмо вјеру са смрћу, и уговорисмо с гробом; кад зађе бич као поводањ, неће нас дохватити, јер од лажи начинисмо себи уточиште, и за пријевару заклонисмо се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Зато овако вели Господ Господ: ево, ја мећем у Сиону камен, камен изабран, камен од угла, скупоцјен, темељ тврд; ко вјерује неће се плашити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'И извршићу суд по правилу и правду по мјерилима; и град ће потрти лажно уточиште и вода ће потопити заклон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'И вјера ваша са смрћу уништиће се, и уговор ваш с гробом неће остати, а кад зађе бич као поводањ, потлачиће вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Чим зађе, однијеће вас, јер ће залазити свако јутро, дању и ноћу, и кад се чује вика, биће сам страх.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Јер ће одар бити кратак да се човјек не може пружити, и покривач узак да се не може умотати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Јер ће Господ устати као на гори Ферасиму, разгњевиће се као у долу Гаваонском, да учини дјело своје, необично дјело своје, да сврши посао свој, необичан посао свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Немојте се дакле више потсмијевати да не постану јачи окови ваши, јер чух од Господа Господа над војскама погибао одређену свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Слушајте, и чујте глас мој, пазите и чујте бесједу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Оре ли орач сваки дан да посије? или бразди и повлачи њиву своју?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Кад поравни озго, не сије ли грахор и ким? и не меће ли пшеницу на најбоље мјесто, и јечам на згодно мјесто, и крупник на његово мјесто?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'И Бог га његов учи и упућује како ће радити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Јер се грахор не врше браном, нити се точак колски обрће по киму, него се цијепом млати грахор и ким прутом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Пшеница се врше, али неће једнако вријећи нити ће је сатрти точком колским на зупцима раздробити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'И то долази од Господа над војскама, који је диван у савјету, велик у мудрости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Тешко Арилу, Арилу, граду гдје је стајао Давид. Додајте годину на годину, нека кољу жртве празничне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Али ћу притијеснити Арила, и биће жалост и туга, јер ће ми бити као Арил.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Јер ћу те опколити војском, и стегнућу те опкопима и подигнућу супрот теби куле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Те ћеш оборен говорити са земље и из праха ћеш муцати, и глас ће ти бити са земље као у бајача и из праха ћеш шапћући говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'А мноштво непријатеља твојих биће као ситан прах и мноштво насилника као пљева кад се размеће; и то ће бити зачас, изненада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Господ над војскама походиће га громом и трусом и хуком великом, вихором и буром и пламеном огњенијем који прождире.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'И мноштво свијех народа који војују на Арил и сви који ударају на њ и на зидове његове и који га притјешњују, биће као утвара ноћна у сну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Биће као кад гладан сни да једе, па кад се пробуди а душа му празна; или кад сни жедан да пије, па кад се пробуди, а он изнемогао и душа му жедна; тако ће бити мноштво свијех народа што војују на гору Сионску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Станите и чудите се; вапијте и вичите: пијани су, али не од вина; посрћу, али не од силовита пића.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Јер је Господ излио на вас дух тврдога сна и затворио вам очи, ослијепио пророке и видиоце, главаре ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'И свака утвара биће вам као ријечи у запечаћеној књизи, коју даду човјеку који зна читати говорећи: читај то; а он рече: не могу, јер је запечаћено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Или да даду књигу оном који не зна читати говорећи: читај то; а он рече: не знам читати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Зато рече Господ: што се овај народ приближује устима својима и уснама својим поштује ме, а срце им далеко стоји од мене, и страх којим ме се боје заповијест је људска којој су научени,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Зато ћу ево још радити чудесно с тијем народом, чудесно и дивно, и мудрост мудријех његовијех погинуће и разума разумнијех нестаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Тешко онима који дубоко сакривају од Господа намјеру, који раде у мраку и говоре: ко нас види? и ко нас зна?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Наопаке мисли ваше нијесу ли као као лончарски? Говори ли дјело за онога који га је начинио: није ме начинио? и лонац говори ли за онога који га је начинио: не разумије?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Неће ли се доскора и Ливан претворити у поље, и поље се узимати за шуму?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'И у тај ће дан глухи чути ријечи у књизи, и из таме и мрака видјеће очи слијепијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'И кротки ће се веома радовати у Господу, и ништи између људи веселиће се са свеца Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Јер насилника неће бити, и нестаће потсмјевача, и истријебиће се сви који гледају да чине безакоње,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'Који окривљују човјека за ријеч, и мећу замку ономе који кара на вратима, и обарају праведнога лажју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Зато Господ, који је откупио Аврама, овако говори за дом Јаковљев: неће се више Јаков постидјети, нити ће му лице поблиједјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Јер кад види усред себе дјецу своју, дјело руку мојих, тада ће они светити име моје, светиће свеца Јаковљева и бојаће се Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'И који лутају духом оразумиће се, и викачи ће примити науку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Тешко синовима одметницима, говори Господ, који саставлају намјере које нијесу од мене, заклањају се за заклон који није од мога духа, да домећу гријех на гријех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Који слазе у Мисир не питајући шта ћу ја рећи, да се укријепе силом Фараоновом и да се заклоне под сјеном Мисирским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Јер ће вам сила Фараонова бити на срамоту, и заклон под сјеном Мисирским на поругу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Јер кнезови његови бише у Соану, и посланици његови дођоше у Ханес.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Али ће се сви посрамити с народа, који им неће помоћи, нити ће им бити на корист ни на добит, него на срамоту и на поругу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Товар ће бити на стоци јужној: у земљу гдје је невоља и мука, гдје су лавови и лавићи, гује и змајеви огњени крилати, однијеће благо своје магарцима на раменима и богатство своје камилама на грбама, к народу који неће помоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Јер ће Мисирци узалуд и напразно помагати; зато вичем о том: јачина им је да сједе с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Сада иди, напиши ово пред њима на дашчицу, напиши у књигу, да остане за времена која ће доћи, довијека;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Јер су народ непокоран, синови лажљиви, синови који неће да слушају закона Господњега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Који говоре видиоцима: немојте виђати, и пророцима: немојте нам пророковати што је право, говорите нам миле ствари, пророкујте пријевару;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Сврните с пута, отступите од стазе, нека нестане испред нас свеца Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Зато овако вели светац Израиљев: кад одбацујете ову ријеч, и уздате се у пријевару и опачину и на њу се ослањате,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'Зато ће вам то безакоње бити као пукотина у зиду који хоће да падне, која издигне зид високо, те се нагло уједанпут обори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'И разбиће га као што се разбија разбијен суд лончарски, не жали се, те се не нађе ни цријепа кад се разбије да узмеш огањ с огњишта или да захватиш воде из јаме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Јер овако говори Господ Господ, светац Израиљев: ако се повратите и будете мирни, избавићете се, у миру и уздању биће сила ваша; али ви нећете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Него говорите: не; него ћемо на коњма побјећи. Зато ћете бјежати. Појахаћемо брзе коње. Зато ће бити бржи који ће вас тјерати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Бјежаће вас тисућа кад један повиче; кад повичу петорица, бјежаћете сви, докле не останете као окресано дрво наврх горе и као застава на хуму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'А зато чека Господ да се смилује на вас, и зато ће се узвисити да вас помилује; јер је Господ праведан Бог; благо свјема који га чекају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Јер ће народ наставати у Сиону, у Јерусалиму; нећеш више плакати, доиста ће те помиловати кад повичеш; чим те чује, одазваће ти се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Премда ће вам Господ дати хљеба тужнога и воде невољничке; али ти се више неће узимати учитељи твоји, него ће очи твоје гледати учитеље твоје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'И уши ће твоје слушати ријеч иза тебе гдје говори: то је пут, идите њим, ако бисте сврнули надесно или налијево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'И опрзнићете посребрене ликове своје резане и златно одијело ликова ливенијех, и бацићете их као нечистоту, и рећи ћеш им: одлазите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'И даће дажд сјемену твојему које посијеш на њиви, и хљеб од рода земаљскога биће обилат и сит; тада ће стока твоја пасти на паши пространој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Волови и магарци, што раде земљу, јешће чисту зоб овијану лопатом и решетом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'И на свакој гори високој и на сваком хуму високом биће извори и потоци, кад буде покољ велики, кад попадају куле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'И свјетлост ће мјесечна бити као свјетлост сунчана, а свјетлост ће сунчана бити седам пута већа, као свјетлост од седам дана, кад Господ завије улом народу својему и исцијели ране које му је задао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Гле, име Господње иде издалека, гњев његов гори и врло је тежак; усне су му пуне љутине и језик му је као огањ који сажиже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'А дух му је као поток који плави и допире до грла, да расије народе да отиду у ништа, и биће у чељустима народима узда која ће их гонити да лутају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Пјеваћете као ноћу уочи празника, и веселићете се од срца као онај који иде са свиралом на гору Господњу, к стијени Израиљевој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'И Господ ће пустити да се чује слава гласа његова, и показаће како маше руком својом с љутијем гњевом и пламеном огњенијем који прождире, с распом и са силнијем даждем и с градом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Јер ће се од гласа Господњега препасти Асирац, који је био палицом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'И куда год прође палица поуздана, којом ће Господ навалити на њ, биће бубњи и гусле, и ратовима жестоким ратоваће на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Јер је већ приправљен Тофет, и самом цару приправљен је, начинио је дубок и широк; мјеста, огња и дрва има много; дах Господњи као поток сумпорни упалиће га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Тешко онима који иду у Мисир за помоћ, који се ослањају на коње, и уздају се у кола што их је много, и у коњике што их је велико мноштво, а не гледају на свеца Израиљева и не траже Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Али је и он мудар, и навући ће зло, и неће порећи своје ријечи, него ће устати на дом неваљалијех људи и на оне који помажу онима који чине безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'А Мисирци су људи а не Бог, и коњи су њихови тијело а не дух; и зато ће Господ махнути руком својом, те ће пасти помагач, пашће и онај коме помаже, и сви ће заједно погинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Јер овако ми рече Господ: као што лав и лавић риче над ловом својим, и ако се и свиче на њ мноштво пастира, он се не плаши од вике њихове нити се покорава на буку њихову, тако ће Господ над војскама сићи да војује за гору Сионску и за хум њезин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Као птице крилима Господ ће над војскама заклањати Јерусалим, и заклањајући избавиће, и облазећи сачуваће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Вратите се к њему, од којега се сасвијем одвргосте, синови Израиљеви!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Јер ће у онај дан сваки одбацити идоле своје сребрне, и златне своје идоле, које вам руке ваше начинише на гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'И Асирац ће пасти од мача не човјечијега, и мач не човјечји појешће га, и бјежаће испред мача, и младићи ће његови плаћати данак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'И стијена ће његова проћи од страха, и кнезови ће се његови препасти од заставе, вели Господ, чији је огањ на Сиону и пећ у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Ево, цар ће царовати право и кнезови ће владати по правди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'И човјек ће бити као заклон од вјетра, и као уточиште од поплаве, као потоци на суху мјесту, као сјен од велике стијене у земљи сасушеној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'И очи онијех који виде неће бити заслијепљене, и уши онијех који чују слушаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'И срце неразумнијех разумјеће мудрост, и језик мутавијех говориће брзо и разговијетно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Неваљалац се неће више звати кнез, нити ће се тврдица називати подашнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Јер неваљалац о неваљалству говори, и срце његово гради безакоње, радећи лицемјерно и говорећи на Бога лаж, да испразни душу гладному и напој жедному да узме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'И справе тврдичине зле су; смишља лукавштине да затре ниште ријечима лажнијем и кад сиромах говори право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Али кнез смишља кнежевски, и устаје да ради кнежевски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Устаните, жене мирне, слушајте глас мој; кћери безбрижне, чујте ријечи моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'За много година бићете у сметњи, ви безбрижне; јер неће бити бербе, и сабирање неће доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Страшите се, ви мирне; дркћите, ви безбрижне, свуците се, будите голе, и припашите око себе костријет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Бијући се у прси за лијепијем њивама, за роднијем чокотима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Трње и чкаљ никнуће на земљи народа мојега, и по свијем кућама веселијем, у граду веселом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Јер ће се дворови оставити, вреве градске нестаће; куле и стражаре постаће пећине довијека, радост дивљим магарцима и паша стадима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Докле се не излије на нас дух с висине и пустиња постане њива а њива се стане узимати за шуму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Тада ће суд становати у пустињи, и правда ће стајати на њиви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'И мир ће бити дјело правде, што ће правда учинити биће покој и безбрижност довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'И мој ће народ сједјети у мирну стану и у шаторима поузданијем, на почивалиштима тихим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Али ће град пасти на шуму, и град ће се врло снизити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Благо вама који сијете покрај сваке воде, и пуштате волове и магарце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Тешко теби, који пустошиш а тебе не пустоше, и који чиниш невјеру а теби се не чини невјера; кад престанеш пустошити, бићеш опустошен, кад престанеш чинити невјеру, чиниће ти се невјера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Господе, смилуј се на нас, тебе чекамо; буди им мишица свако јутро, и спасење наше у невољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Народи побјегоше од јаке вике, расијаше се народи што се ти подиже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'И покупиће се плијен ваш као што се купе гусјенице, скочиће на њ као што скачу скакавци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Узвишен је Господ, јер настава на висини; напуниће Сион суда и правде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'И тврђа времена твојега, сила спасења твојега биће мудрост и знање; страх Господњи биће благо твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Ето, јунаци њихови вичу на пољу, и посланици мирни плачу горко:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Путови опустјеше, путници не путују; поквари уговор, одбаци градове, не мари за човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Земља тужи и чезне, Ливан се стиди и вене, Сарон је као пустиња, Васан и Кармил огољеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Сада ћу устати, вели Господ, сада ћу се узвисити, сада ћу се подигнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Затрудњећете сламом, родићете стрњику; гњев ваш прождријеће вас као огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'И народи ће бити као пећи кречне, изгорјеће огњем као трње посјечено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Слушајте који сте далеко што сам учинио, и који сте близу познајте моћ моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Грјешници у Сиону уплашиће се, дрхат ће спопасти лицемјере, и рећи ће: ко ће нас остати код огња који прождире? ко ће нас остати код вјечне жеге?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Ко ходи у правди и говори што је право; ко мрзи на добитак од насиља; ко отреса руке своје да не прими поклона; ко затискује уши своје да не чује за крв, и зажима очи своје да не види зла;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Он ће наставати на високим мјестима; градови на стјенама биће му уточиште, хљеб ће му се давати, воде му се неће премицати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Очи ће ти видјети цара у красоти његовој, гледаће земљу далеку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Срце ће твоје мислити о страху говорећи: гдје је писар? гдје бројач? гдје је онај што прегледа куле?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Нећеш видјети жестока народа, народа који говори из дубина да се не разбира, у кога је језик мутав да се не разумије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Погледај на Сион, град празника наших; очи твоје нека виде Јерусалим, мирни стан, шатор, који се неће однијети, којему се коље неће нигда помјерити, и ниједно му се уже неће откинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Него ће нам ондје Господ велики бити мјесто ријека и потока широких, по којима неће ићи лађа с веслима, нити ће велика лађа пролазити онуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Јер је Господ наш судија, Господ је који нам поставља законе, Господ је цар наш, он ће нас спасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Ослабише твоја ужа, не могу тврдо држати катарке своје ни разапети једра; тада ће се раздијелити велик плијен, хроми ће разграбити плијен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'И нико од становника неће рећи: болестан сам. Народу који живи у њему опростиће се безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Приступите, народи, да чујете; пазите, народи; нека чује земља и што је у њој, васиљена и што се год рађа у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Јер се Господ разгњевио на све наредбе, и разљутио се на сву војску њихову, затрће их, предаће их на покољ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'И побијени њихови бациће се, и од мртваца њиховијех дизаће се смрад и горе ће се расплинути од крви њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'И сва ће се војска небеска растопити, и савиће се небеса као књига, и сва војска њихова попадаће као што пада лист с винове лозе и као што пада са смокве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Јер је опојен на небу мач мој, ево, сићи ће на суд на Едомце и на народ који сам проклео да се затре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Мач је Господњи пун крви и тован од претилине, од крви јагњеће и јаричје, од претилине бубрега овнујских; јер Господ има жртву у Восору и велико клање у земљи Едомској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'И једнорози ће сићи с њима и јунци с биковима; земља ће се њихова опити од крви и прах ће њихов утити од претилине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Јер ће бити дан освете Господње, година плаћања, да би се осветио Сион.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'И потоци ће се њезини претворити у смолу, и прах њезин у сумпор, и земља ће њихова постати смола разгорјела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Неће се гасити ни ноћу ни дању, довијека ће се дизати дим њезин, од кољена до кољена остаће пуста, нико неће прелазити преко ње довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Него ће је наслиједити гем и ћук, сова и гавран населиће се у њој, и Господ ће растегнути преко ње уже погибли и мјерила пустоши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Племиће њезине зваће да царују, али неће бити ниједнога, и сви ће кнезови њезини отићи у ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'И трње ће изникнути у дворима њиховијем, коприва и чкаљ у градовима њиховијем, и биће стан змајевима и насеље совама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'И сретаће се дивље звијери с буљинама, авети ће се довикивати, ондје ће се населити вјештице и наћи почивалиште.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Ондје ће се гнијездити ћук и носити јаја и лећи птиће и сабирати их под сјен свој; ондје ће се састајати и јастребови један с другим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Тражите у књизи Господњој и читајте, ништа од овога неће изостати и ниједно неће бити без другога; јер што кажем, он је заповједио, и дух ће их његов сабрати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Јер им он баци ждријеб, и рука његова раздијели им земљу ужем, и њихова ће бити довијека, од кољена до кољена наставаће у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Радоваће се томе пустиња и земља сасушена, веселиће се пустош и процвјетати као ружа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Процвјетаће обилно, и веселиће се радујући се и попијевајући; слава Ливанска даће јој се и красота Кармилска и Саронска; та ће мјеста видјети славу Господњу красоту Бога нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Укријепите клонуле руке, и кољена изнемогла утврдите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Реците онима којима се срце уплашило: охрабрите се, не бојте се; ево Бога вашега; освета иде, плата Божија, сам иде, и спашће вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Тада ће се отворити очи слијепима, и уши глухима отвориће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Тада ће хромац скакати као јелен, и језик нијемога пјеваће, јер ће у пустињи проврети воде и потоци у земљи сасушеној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'И сухо ће мјесто постати језеро, и земља сасушена извори водени, у стану змајевском, по ложама њиховијем, биће трава, трска и сита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'И ондје ће бити насап и пут, који ће се звати свети пут; неће ићи по њему нечисти, него ће бити за њих; ко узиде њим, ни луд неће заћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Неће ондје бити лава, и љута звијер неће ићи по њему, нити ће се ондје наћи, него ће ходити избављени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'И које искупи Господ, вратиће се и доћи ће у Сион пјевајући, и вјечна ће радост бити над главом њиховом, добиће радост и весеље, а жалост и уздисање бјежаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Четрнаесте године царовање Језекијина подиже се Сенахирим цар Асирски на све тврде градове Јудине, и узе их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'И посла цар Асирски Равсака из Лахиса у Јерусалим к цару Језекији с великом војском; и он стаде код јаза горњега језера на путу код поља бјељарева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Тада изиде к њему Елијаким син Хелкијин, који бијаше над двором, и Сомна писар и Јоах син Асафов паметар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'И рече им Равсак: кажите Језекији: овако каже велики цар, цар Асирски: каква је то узданица у коју се уздаш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Да речем, али су празне ријечи, да имаш свјета и силе за рат. У што се дакле уздаш, те си се одметнуо од мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Гле, уздаш се у штап од трске сломљене, у Мисир, на који ако се ко наслони, ући ће му у руку и пробошће је; таки је Фараон цар Мисирски свјема који се уздају у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Ако ли ми речеш: уздамо се у Господа Бога својега; није ли то онај чије је висине и олтаре оборио Језекија и заповједио Јуди и Јерусалиму: пред овијем олтаром клањајте се?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Хајде затеци се мојему господару цару Асирском, и даћу ти двије тисуће коња, ако можеш добавити који ће јахати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Како ћеш дакле одбити и једнога војводу између најмањих слугу господара мојега? Али се ти уздаш у Мисир за кола и коњике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Сврх тога, еда ли сам ја без Господа дошао на ово мјесто да га затрем? Господ ми је рекао: иди на ту земљу, и затри је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Тада Елијаким и Сомна и Јоах рекоше Равсаку: говори слугама својим Сирски, јер разумијемо, а немој нам говорити Јудејски да слуша народ на зиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'А Равсак рече: еда ли ме је господар мој послао ка господару твојему или к теби да кажем ове ријечи? није ли к тијем људима, што сједе на зиду, да једу своју нечист и да пију своју мокраћу с вама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Тада стаде Равсак и повика иза гласа Јудејски и рече: чујте ријечи великога цара Асирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Овако каже цар: немојте да вас вара Језекија, јер вас не може избавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Немојте да вас наговори Језекија да се поуздате у Господа, говорећи: Господ ће нас избавити, овај се град неће дати у руке цару Асирском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Не слушајте Језекије; јер овако каже цар Асирски: учините мир са мном и ходите к мени, па једите сваки са свога чокота и сваки са своје смокве, и пијте сваки из својега студенца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'Докле не дођем и однесем вас у земљу као што је ваша, у земљу обилну житом и вином, у земљу обилну хљебом и виноградима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Немојте да вас вара Језекија говорећи: Господ ће нас избавити. Је ли који између богова других народа избавио своју земљу из руке цара Асирскога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Гдје су богови Ематски и Арфадски? гдје су су богови Сефарвимски? јесу ли избавили Самарију из мојих руку?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Који су између свијех богова овијех земаља избавили земљу своју из моје руке? а Господ ће избавити Јерусалим из моје руке?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Али они мучаху, и не одговорише му ни ријечи, јер цар бјеше заповједио и рекао: не одговарајте му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Тада Елијаким син Хелкијин, који бијаше над двором, и Сомна писар и Јоах син Асафов, паметар, дођоше к Језекији раздрвши хаљине, и казаше му ријечи Равсакове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'А кад то чу цар Језекија, раздрије хаљине своје и веза око себе костријет, па отиде у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'И посла Елијакима, који бијаше над двором, и Сомну писара и најстарије свештенике обучене у костријет к Исаији пророку сину Амосову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'И рекоше му: овако вели Језекија: ово је дан невоље и кара и руга, јер приспјеше дјеца до порођаја, а нема снаге да се роде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Да ако је чуо Господ Бог твој што рече Равсак, којега посла цар Асирски господар његов да ружи Бога живога и да га вријеђа ријечима које је чуо Господ Бог твој, помоли се за остатак који се налази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'И дођоше к Исаији слуге цара Језекије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'И рече им Исаија: овако реците господару својему: овако вели Господ: не плаши се од ријечи које си чуо, којима хулише на ме слуге цара Асирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Ево, ја ћу пустити на њ дух, те ће чути глас и вратити се у своју земљу, и учинићу да погине од мача у својој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'И тако вративши се Равсак нађе цара Асирскога гдје бије Ливну, јер бјеше чуо да је отишао од Лахиса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'А он чу за Тираку цара Хускога гдје казаше: иде да се бије с тобом. И чувши посла посланике к Језекији говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Овако реците Језекији цару Јудину: немој да те вара Бог твој, у којега се уздаш говорећи: неће се дати Јерусалим у руке цару Асирском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Ето, чуо си шта су учинили цареви Асирски свијем земљама потрвши их сасвијем; а ти ли ћеш се избавити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Јесу ли народе које сатрше оци моји избавили богови њихови, Госанце, Харанце, Ресефе и синове Еденове који бијаху у Теласару?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Гдје је цар Ематски и цар Арфадски и цар од града Сефарвима, од Ене и Аве?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'А кад Језекија прими књигу из руку посланика и прочита је, отиде у дом Господњи, и разви је Језекија пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'И помоли се Језекија Господу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Господе над војскама, Боже Израиљев, који сједиш на херувимима, ти си сам Бог свијем царствима на земљи, ти си створио небо и земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Пригни, Господе, ухо своје и чуј; отвори, Господе, очи своје и види; чуј све ријечи Сенахирима, који посла да ружи Бога живога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Истина је, опустошили су цареви Асирски све оне народе и земље њихове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'И побацали су богове њихове у огањ, јер не бијаху богови, него дјело руку човјечијих, дрво и камен, зато их потрше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'И зато, Господе Боже наш, избави нас из руку његовијех, да познаду сва царства на земљи да си ти сам Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Тада посла Исаија син Амосов к Језекији и поручи му: овако вели Господ Бог Израиљев: услишио сам за што си ми се молио ради Сенахирима цара Асирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Ово је ријеч коју изрече Господ за њ: руга ти се и потсмијева ти се дјевојка, кћи Сионска, за тобом маше главом кћи Јерусалимска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Кога си ружио и хулио? и на кога си подигао глас? и подигао увис очи своје? На свеца Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Преко слуга својих ружио си Господа и рекао си: с мноштвом кола својих изидох на високе горе, на стране Ливанске, и посјећи ћу високе кедре његове, и лијепе јеле његове, и доћи ћу на највиши крај његов, у шуму његова Кармила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Ја сам копао, и пио воду, и исушио сам стопама својим све потоке градовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Нијеси ли чуо да ја то одавна чиним и од искона да сам тако уредио? сада пуштам то, да превратиш тврде градове у пусте гомиле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Зато који у њима живе изнемогоше, уплашише се и сметоше се, посташе као трава пољска, као зелена травица, као трава на крововима, која се суши прије него сазри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Знам сјеђење твоје и полажење твоје и долажење твоје и како бјесниш на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Јер бјесниш на ме, и твоја обијест дође до мојих ушију, зато ћу метнути брњицу своју на ноздрве твоје, и узду своју у губицу твоју, па ћу те одвести натраг путем којим си дошао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'А теби ово нека буде знак: јешћете ове године што само од себе роди, а друге године што опет само од себе роди; а треће године сијте и жањите и садите винограде и једите род из њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Јер остатак дома Јудина, што остане, опет ће пустити жиле оздо и родити озго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Јер ће из Јерусалима изаћи остатак, и из горе Сиона, који се сачувају. Ревност Господа над војскама учиниће то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Зато овако вели Господ за цара Асирскога: неће ући у овај град, нити ће бацити амо стријеле, неће се примаћи к њему са штитом, нити ће ископати опкопа око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Вратиће се путем којим је дошао, а у град овај неће ући, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Јер ћу бранити тај град и сачуваћу га себе ради и ради Давида слуге својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Тада изиде анђео Господњи и поби у околу Асирском сто и осамдесет и пет тисућа; и кад усташе ујутру, а то све сами мртваци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Те се подиже Сенахирим цар Асирски, и отиде, и вративши се оста у Ниневији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'И кад се клањаше у дому Нисрока бога својега, Адрамелех и Сарасар синови његови убише га мачем, а сами побјегоше у земљу Араратску, и на његово се мјесто зацари Есарадон син његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'У то вријеме разбоље се Језекија на смрт; и дође к њему пророк Исаија син Амосов и рече му: овако вели Господ: нареди за кућу своју, јер ћеш умријети и нећеш остати жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'А Језекија се окрете лицем к зиду, и помоли се Господу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'И рече: ох, Господе, опомени се да сам једнако ходио пред тобом вјерно и с цијелим срцем, и творио што је теби угодно. И плака Језекија веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Тада дође ријеч Господња Исаији говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Иди и реци Језекији: овако вели Господ Бог Давида оца твојега: чуо сам молитву твоју, и видио сам сузе твоје, ево додаћу ти вијеку петнаест година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'И избавићу тебе и овај град из руку цара Асирскога, и бранићу овај град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'И ово нека ти буде знак од Господа да ће учинити Господ што је рекао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Ево ја ћу вратити сјен по кољенцима по којима је сишао на сунчанику Ахазову натраг за десет кољенаца. И врати се сунце за десет кољенаца по кољенцима по којима бијаше сишло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Ово написа Језекија цар Јудин кад се разбоље, и оздрави од болести своје:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Ја рекох, кад се пресјекоше дани моји: идем к вратима гробнијем, узе ми се остатак година мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Рекох: нећу видјети Господа Господа у земљи живијех, нећу више видјети човјека међу онима који станују на свијету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Вијек мој прође и пренесе се од мене као шатор пастирски; пресјекох живот свој као ткач, отсјећи ће ме од оснутка; од јутра до вечера учинићеш ми крај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Мишљах за јутра да ће као лав потрти све кости моје; од јутра до вечера учинићеш ми крај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Пиштах као ждрао и као ластавица, уках као голубица, очи ми ишчиљеше гледајући горе: Господе, у невољи сам, облакшај ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Шта да речем? Он ми каза, и учини. Проживјећу све године своје по јаду душе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Господе, о том се живи и у том је свему живот духа мојега, исцијелио си ме и сачувао у животу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Ево, на мир дође ми љут јад; али теби би мило да извучеш душу моју из јаме погибли, јер си бацио за леђа своја све гријехе моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Јер неће гроб тебе славити, неће те смрт хвалити, и који сиђу у гроб не надају се твојој истини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Живи, живи, они ће те славити као ја данас: отац ће синовима јављати истину твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Господ ме спасе, зато ћемо пјевати пјесме моје у дому Господњем док смо год живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'А Исаија бјеше рекао да узму груду сухих смокава и привију на оток, те ће оздравити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'И Језекија бјеше рекао: шта ће бити знак да ћу отићи у дом Господњи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'У то вријеме Меродах-Валадан, син Валаданов, цар Вавилонски, посла књигу с даром Језекији; јер бјеше чуо да је био болестан и оздравио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'И Језекија се обрадова томе, и показа им све ризнице своје, сребро и злато и мирисе, и најбоље уље, и кућу гдје му бјеше оружје, и што се год налажаше у ризницама његовијем, не оста ништа да им не показа Језекија у кући својој и у свему господству свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Тада дође пророк Исаија к цару Језекији и рече му: шта су говорили ти људи и одакле су дошли к теби? А Језекија рече: из даљне земље дошли су к мени, из Вавилона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'А он рече: шта су видјели у твом двору? А Језекија рече: видјели су све што има у мом двору; није остало ништа у ризницама мојим да им нијесам показао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Тада рече Исаија Језекији: чуј ријеч Господа над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Ево доћи ће вријеме кад ће се однијети у Вавилон све што има у кући твојој, и што су сабирали оци твоји до данас, неће остати ништа, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'И синове твоје, који ће изаћи од тебе, које ћеш родити, узеће да буду дворани у двору цара Вавилонскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'А Језекија рече Исаији: добра је ријеч Господња коју си рекао. Још рече: је ли? за мога вијека биће мир и вјера?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Тјешите, тјешите народ мој, говори Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Говорите Јерусалиму љубазно, и јављајте му да се навршио рок његов, да му се безакоње опростило, јер је примио из руке Господње двојином за све гријехе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Глас је некога који виче: приправите у пустињи пут Господњи, поравните у пустоши стазу Богу нашему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Све долине нека се повисе, и све горе и брегови нека се слегну, и што је криво нека буде право, и неравна мјеста нека буду равна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'И јавиће се слава Господња, и свако ће тијело видјети; јер уста Господња говорише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Глас говори: вичи. И рече: шта да вичем? Да је свако тијело трава и све добро његово као цвијет пољски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Суши се трава, цвијет опада кад дух Господњи дуне на њ; доиста је народ трава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Суши се трава, цвијет опада; али ријеч Бога нашега остаје довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Изиди на високу гору, Сионе, који јављаш добре гласе; подигни силно глас свој, Јерусалиме, који јављаш добре гласе; подигни, не бој се. Кажи градовима Јудинијем: ево Бога вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Ево, Господ Бог иде на јакога, и мишица ће његова обладати њим; ево плата је његова код њега и дјело његово пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Као пастир пашће стадо своје; у наручје своје сабраће јагањце, и у њедрима ће их носити, а дојилице ће водити полако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Ко је измјерио воду грстима својим и небеса премјерио пеђу? ко је мјером измјерио прах земаљски, и горе измјерио на мјерила и брегове на потег?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Ко је управљао дух Господњи? или му био савјетник и научио га?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'С ким се је договарао и ко га је уразумио и научио путу суда, и научио га знању и показао му пут разума?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Гле, народи су као кап из виједра, и као прашка на мјерилима броје се; гле, премјешта острва као прашак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Ни Ливан не би био доста за огањ, и животиње његове не би биле доста за жртву паљеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Сви су народи као ништа пред њим, мање неголи ништа и таштина вриједе му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'С ким ћете дакле изједначити Бога? и каку ћете му прилику наћи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Умјетник лије лик, и златар га позлаћује, и верижице сребрне лије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'А ко је сиромах, те нема шта принијети, бира дрво које не труне, и тражи вјешта умјетника да начини резан лик, који се не помиче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Не знате ли? не чујете ли? не казује ли вам се од искона? не разумијете ли од темеља земаљских?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Он сједи над кругом земаљским, и њезини су му становници као скакавци; он је разастро небеса као платно и разапео их као шатор за стан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Он обраћа кнезове у ништа, судије земаљске чини да су као таштина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Као да нијесу посађени ни посијани, и као да им се стабло није укоријенило у земљи, чим дуне на њих, посахну, и вихор као пљеву разнесе их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'С ким ћете ме дакле изједначити да бих био као он? вели свети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Подигните горе очи своје и видите; ко је то створио? ко изводи војску свега тога на број и зове свако по имену, и велике ради силе његове и јаке моћи не изостаје ниједно?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Зашто говориш, Јакове, и кажеш, Израиљу: сакривен је пут мој од Господа, и ствар моја не излази пред Бога мојега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Не знаш ли? нијеси ли чуо да Бог вјечни Господ, који је створио крајеве земаљске, не сустаје нити се утруђује? разуму његову нема мјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Он даје снагу уморноме, и нејакоме умножава крјепост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Дјеца се море и сустају, и младићи падају;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Али који се надају Господу, добијају нову снагу, подижу се на крилима као орлови, трче и не сустају, ходе и не море се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Умукните преда мном, острва; и народи нека се поткријепе, нека приступе, и тада нека реку: хајдемо да се судимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Ко је подигао правду с истока? ко је дозвао да иде за њим устопице? ко јој је покорио народе и дао јој власт над царевима и учинио те су као прах мачу њезину и као развијана пљева луку њезину?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Погна их, прође мирно путем, којим не бјеше ходио ногама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Ко је урадио и учинио то? и зове нараштаје од искона? Ја, Господ, први и пошљедњи, ја исти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Видјеше острва и уплашише се, крајеви земаљски задрхташе, приближише се и дођоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Један другом помагаше, и брату својему говораше: буди храбар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Дрводјеља храбраше златара: који клепље храбраше онога који кује на наковњу, говорећи: добро је за спајање. И притврђиваше клинцима да се не помиче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Али ти, Израиљу, слуго мој; Јакове, којега изабрах, сјеме Аврама пријатеља мојега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Ти, којега узех с крајева земаљских, и између избранијех њезинијех дозвах те, и рекох ти: ти си мој слуга, ја те изабрах, и не одбацих тебе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Не бој се, јер сам ја с тобом; не плаши се, јер сам ја Бог твој; укријепићу те и помоћи ћу ти, и подупријећу те десницом правде своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Гле, постидјеће се и посрамиће сви који се љуте на тебе; биће као ништа и изгинуће противници твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Потражићеш супарнике своје, али их нећеш наћи, биће као ништа, и који војују на те, нестаће их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Јер ја Господ Бог твој држим те за десницу, и кажем ти: не бој се, ја ћу ти помагати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Не бој се, црвићу Јаковљев, народићу Израиљев, ја ћу ти помагати, говори Господ и избавитељ твој, светац Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Гле, учинићу те да будеш као справа за вршење нова са зупцима: вријећи ћеш горе и сатрћеш их, и брда ћеш обратити у пљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Вијаћеш их, и вјетар ће их однијети и вихор ће их расути, а ти ћеш се веселити у Господу и хвалићеш се свецем Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Сиромахе и убоге, који траже воде а ње нема,којима се језик осушио од жеђи, њих ћу услишити ја Господ, ја Бог Израиљев нећу их оставити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Отворићу ријеке на висовима, и изворе усред долина, пустињу ћу обратити у језеро водено, и суху земљу у изворе водене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Посадићу у пустињи кедар, ситим, мирту и маслину; посадићу у пустој земљи јелу, бријест и шимшир,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Да виде и познаду и да промисле и разумију да је то урадила рука Господња, и светац Израиљев да је то створио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Изнесите парбу своју, вели Господ, покажите разлоге своје, вели цар Јаковљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Нека дођу и нека нам објаве шта ће бити; објавите нам шта је прво било, да промислимо и познамо шта ће бити иза тога; или кажите нам шта ће бити унапредак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Кажите шта ће бити послије, и познаћемо да сте богови; или учините што добро или зло, и дивићемо се и гледати сви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Гле, ви нијесте ништа, и дјело ваше није ништа; који вас избира, гад је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Подигох једнога са сјевера, и доћи ће; од истока сунчанога призваће име моје, ступаће по главарима као по калу и као што лончар гази блато.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Ко је објавио од искона, да бисмо знали, или од старина, да бисмо рекли: истина је? Али нема никога да би објавио, нити има кога да напријед казао, нити има кога да би чуо ријечи ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Ја први Сиону кажем: ето, ето тога. У Јерусалиму ћу дати ко ће јављати добре гласе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Јер погледам, али нема никога, нема међу њима ниједнога ко би свјетовао; питам их, али не одговарају ни ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Гле, сви су таштина, ништа су дјела њихова; ливени су ликови њихови вјетар и ништавило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Ево слуге мојега, којега подупирем, избраника мојега, који је мио души мојој; метнућу дух свој на њега, суд народима јављаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Неће викати ни подизати, нити ће се чути глас његов по улицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Трске стучене неће преломити, и свјештила које се пуши неће угасити; јављаће суд по истини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Неће му досадити, нити ће се уморити, докле не постави суд на земљи, и острва ће чекати науку његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Овако говори Бог Господ, који је створио небеса и разапео их, који је распростро земљу и што она рађа, који даје дисање народу што је на њој и дух онима што ходе по њој:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Ја Господ дозвах те у правди, и држаћу те за руку, и чуваћу те, и учинићу те да будеш завјет народу, видјело народима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Да отвориш очи слијепцима, да изведеш сужње из затвора и из тамнице који сједе у тами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Ја сам Господ, то је име моје, и славе своје нећу дати другоме ни хвале своје ликовима резанијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Ево, пређашње дође, и ја јављам ново, прије него настане казујем вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Пјевајте Господу пјесму нову, хвалу његову од краја земље, који се плавите по мору и све што је у њему, острва и који живите на њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Пустиња и градови њезини, села гдје станује Кидар, нека подигну глас, нека пјевају који живе по стијенама, нека кликују саврх гора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Нека дају славу Господу, и хвалу његову нека јављају по острвима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Господ ће изаћи као јунак, подигнуће ревност своју као војник, викаће и кликовати, надвладаће непријатеље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Мучах дуго, чињах се глух, устезах се; али ћу сада викати као жена кад се порађа, и све ћу потрти и истријебити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Опустићу горе и брегове, и сваку траву на њима осушићу, и од ријека ћу начинити острва, и језера ћу исушити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'И водићу слијепце путем којега нијесу знали; водићу их стазама којих нијесу знали; обратићу пред њима мрак у свјетлост и што је неравно у равно. То ћу им учинити, и нећу их оставити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Тада ће се вратити натраг и посрамити се који се уздају у лик резани, који говоре ликовима ливенијем: ви сте наши богови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Чујте, глухи; прогледајте, слијепи, да видите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Ко је слијеп осим слуге мојега? и ко је глух као посланик мој којега шаљем? ко је слијеп као савршени? ко је слијеп као слуга Господњи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Гледаш много, али не видиш; отворене су ти уши, али не чујеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Господу бијаше мио ради правде његове, учини закон великим и славним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'А народ је оплијењен и потлачен, сви су колики повезани у пећинама и сакривени у тамницама; посташе плијен, а нема никога да би избавио; посташе грабеж, а нема никога да би рекао: врати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Ко између вас чује ово и пази и слуша за послије?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Ко је дао Јакова да се потлачи и Израиља отимачима? Није ли Господ, којему згријешисмо? Јер не хтјеше ходити путовима његовијем нити слушаше закона његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Зато изли на њих жестоку јарост своју и силан рат, и запали га унаоколо, али он не разумје; запали га, али он не мари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Али сада овако вели Господ, који те је створио, Јакове, и који те је саздао, Израиљу: не бој се, јер те откупих, позвах те по имену твом; мој си.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Кад пођеш преко воде, ја ћу бити с тобом, или преко ријека, неће те потопити; кад пођеш кроз огањ, нећеш изгорјети и неће те пламен опалити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Јер сам ја Господ, Бог твој, светац Израиљев, спаситељ твој; дадох у откуп за те Мисир, Етиопску и Севу мјесто тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Откако си ми постао драг, прославио си се и ја те љубих; и дадох људе за те и народе за душу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Не бој се, јер сам ја с тобом; од истока ћу довести сјеме твоје, и од запада сабраћу те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Казаћу сјеверу: дај; и југу: не брани; доведи синове моје из далека и кћери моје с крајева земаљских,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'Све, који се зову мојим именом и које створих на славу себи, саздах и начиних.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Изведи народ слијепи који има очи, и глухи који има уши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Сви народи нека се скупе, и нека се саберу племена; ко је између њих напријед казао то или нам казао што је било прије? Нека доведу свједоке своје и оправдају се; или нека чују, и реку: истина је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Ви сте моји свједоци, вели Господ, и слуга мој којега изабрах, да бисте знали и вјеровали ми и разумјели да сам ја; прије мене није било Бога нити ће послије мене бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Ја сам, ја сам Господ, и осим мене нема спаситеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Ја објавих, и спасох, и напријед казах, и никоји туђ бог међу вама, и ви сте ми свједоци, вели Господ, и ја сам Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Ја сам од прије него дан поста, и нико не може избавити из моје руке; кад радим, ко ће смести?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Овако говори Господ избавитељ ваш, светац Израиљев: вас ради послаћу у Вавилон и побацаћу све пријеворнице, и Халдејце с лађама, којима се хвале.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Ја сам Господ светац ваш, створитељ Израиљев, цар ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Овако говори Господ који је начинио по мору пут и по силнијем водама стазу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'Који изводи кола и коње, војску и силу, да сви попадају и не могу устати, да се угасе као што се гаси свјештило:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Не помињите што је прије било и не мислите о старијем стварима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Ево, ја ћу учинити ново, одмах ће настати; нећете ли га познати? Још ћу начинити у пустињи пут, ријеке у сухој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Славиће ме звијери пољске, змајеви и сове, што сам извео у пустињу воде, ријеке у земљи сухој, да напојим народ свој, избраника својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Народ који саздах себи, приповједаће хвалу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'А ти, Јакове, не призива ме, и бијах ти досадан, Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Нијеси ми принио јагњета на жртву паљеницу, и жртвама својим нијеси ме почастио; нијесам те нагонио да ми служиш приносима, нити сам те трудио да ми кадиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Нијеси ми купио за новце када, нити си ме претилином жртава својих наситио, него си ме мучио својим гријесима, и досадио си ми безакоњем својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Ја, ја сам бришем твоје пријеступе себе ради, и гријеха твојих не помињем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Опомени ме, да се судимо, казуј, да се оправдаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Отац твој први сагријеши, и учитељи твоји скривише ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Зато ћу избацити из светиње кнезове, и даћу Јакова у проклетство и Израиља у срамоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Али сада чуј, Јакове, слуго мој, и Израиљу, којега изабрах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Овако вели Господ, који те је створио и саздао од утробе материне, и који ти помаже: не бој се, слуго мој Јакове, и мили, којега изабрах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Јер ћу излити воду на жеднога и потоке на суху земљу, излићу дух свој на сјеме твоје и благослов свој на твоје натражје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'И процвјетаће као у трави, као врбе покрај потока.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Овај ће рећи: ја сам Господњи, а онај ће се звати по имену Јаковљеву, а други ће се писати својом руком Господњи, и презиваће се именом Израиљевим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Овако говори Господ цар Израиљев и избавитељ његов, Господ над војскама: ја сам први и ја сам пошљедњи, и осим мене нема Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'И ко као ја оглашује и објављује ово, или ми уређује откако населих стари народ? Нека им јави што ће бити и што ће доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Не бој те се и не плашите се; нијесам ли ти давно казао и објавио? ви сте ми свједоци; има ли Бог осим мене? Да, нема стијене, не знам ни једне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Који граде резане ликове, сви су ништа, и миле ствари њихове не помажу ништа, и оне су им свједоци да не виде и не разумију, да би се посрамили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Ко гради бога и лије лик, није ни на каку корист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Гле, сви ће се другови његови посрамити, и умјетници више од других људи; нека се скупе сви и стану, биће их страх и посрамиће се сви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Ковач клијештима ради на живом угљевљу, и кује чекићем, и ради снагом своје руке, гладује, те изнемогне, и не пије воде, те сустане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Дрводјеља растеже врвцу и биљежи црвенилом, теше и заокружује, и начиња као лик човјечји, као лијепа човјека, да стоји у кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Сијече себи кедре, и узима чесвину и храст или што је најчвршће међу дрвљем шумским; сади јасен, и од дажда расте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'И бива човјеку за огањ, и узме га, те се грије; упали га, те пече хљеб; и још гради од њега бога и клања му се; гради од њега лик резан, и пада на кољена пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Половину ложи на огањ, уз половину једе месо испекавши печење, и бива сит, и грије се и говори: аха, огријах се, видјех огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'А од остатка гради бога, резан лик свој, пада пред њим на кољена и клања се, и моли му се и говори: избави ме, јер си ти бог мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Не знају, нити разумију, јер су им очи заслијепљене да не виде, и срца, да не разумију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Нити узимају на ум, нема знања ни разума да би који рекао: половину овога спалих на огањ, и на угљу од њега испекох хљеб, испекох месо и једох; и од остатка еда ли ћу начинити гад, и пању дрвеном хоћу ли се клањати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Таки се храни пепелом, преварено срце заводи га да не може избавити душе своје, нити рећи: није ли лаж што ми је у десници?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Памти то, Јакове и Израиљу, јер си мој слуга; ја сам те саздао, слуга си мој, Израиљу, нећу те заборавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Расућу као облак пријеступе твоје, и гријехе твоје као маглу; врати се к мени, јер сам те избавио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Пјевајте, небеса, јер Господ учини, подвикујте, низине земаљске, попијевајте, горе, шуме и сва дрва у њима, јер избави Господ Јакова и прослави се у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Овако говори Господ, избавитељ твој, који те је саздао од утробе материне: ја Господ начиних све: разапех небо сам, распростријех земљу сам собом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Уништујем знаке лажљивцима, и враче обезумљујем, враћам натраг мудраце, и претварам мудрост њихову у лудост;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Потврђујем ријеч слуге својега, и навршујем савјет гласника својих; говорим Јерусалиму: населићеш се; и градовима Јудинијем: сазидаћете се; и пустолине њихове подигнућу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Говорим дубини: пресахни и исушићу ријеке твоје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Говорим Киру: пастир си мој; и извршиће сву вољу моју, и казаће Јерусалиму: сазидаћеш се; и цркви: основаћеш се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Овако говори Господ помазанику својему Киру, којега држим за десницу, да оборим пред њим народе и цареве распашем, да се отварају врата пред њим и да не буду врата затворена:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Ја ћу ићи пред тобом, и путове неравне поравнићу, врата мједена разбићу и пријеворнице гвоздене сломићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'И даћу ти благо тајно и богатство сакривено, да познаш да сам ја Господ Бог Израиљев, који те зовем по имену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Ради слуге својега Јакова и Израиља избраника својега прозвах те именом твојим и презименом, премда ме не знаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Ја сам Господ, и нема другога, осим мене нема бога; опасах те, премда ме не знаш,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Да би познали од истока сунчанога и од запада да нема другога осим мене; ја сам Господ и нема другога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Који правим свјетлост и стварам мрак, градим мир и стварам зло; ја Господ чиним све то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Росите, небеса, озго, и облаци нека капљу правдом, нека се отвори земља и нека роди спасењем и заједно нека узрасте правда; ја Господ створих то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Тешко оном ко се свађа с творцем својим; цријеп с другим цреповима нека се свађа; али хоће ли као рећи лончару својему: шта радиш? за твој посао нема руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Тешко оном ко говори оцу: што рађаш? и жени: што се порађаш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Овако вели Господ светац Израиљев и творац његов: питајте ме што ће бити; за синове моје и за дјело руку мојих наређујте ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Ја сам начинио земљу и човјека на њој створио, ја сам разапео небеса својим рукама, и свој војсци њиховој дао заповијест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Ја га подигох у правди, и све путове његове поравнићу; он ће сазидати мој град и робље моје отпустиће, не за новце ни за дарове, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Овако вели Господ: труд Мисирски и трговина Етиопска и Саваца људи висока раста доћи ће к теби и бити твоја; за тобом ће пристати, у оковима ће ићи, и теби ће се клањати, теби ће се молити говорећи: доиста, Бог је у теби, и нема другога Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Да, ти си Бог, који се кријеш, Бог Израиљев, спаситељ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Они ће се сви постидјети и посрамити, отићи ће са срамотом свиколики који граде ликове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'А Израиља ће спасти Господ спасењем вјечнијем, нећете се постидјети нити ћете се осрамотити довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Јер овако вели Господ, који је створио небо, Бог, који је саздао земљу и начинио је и утврдио, и није је створио напразно, него је начинио да се на њој настава: ја сам Господ, и нема другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Нијесам говорио тајно ни на мрачну мјесту на земљи, нијесам рекао сјемену Јаковљеву: тражите ме узалуд. Ја Господ говорим правду, јављам што је право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Скупите се и дођите, приступите сви који сте се избавили између народа. Ништа не знају који носе дрво од својега лика и моле се богу који не може помоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Огласите, и доведите, нека вијећају заједно: ко је то од старине казао? ко је јавио још онда? Нијесам ли ја, Господ? Нема осим мене другога Бога, нема Бога праведнога и спаситеља другога осим мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Погледајте у мене, и спашћете се сви крајеви земаљски; јер сам ја Бог, и нема другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Собом се заклех; изиде из уста мојих ријеч праведна, и неће се порећи, да ће им се поклонити свако кољено, и заклињати се сваки језик,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'И говориће: у Господу је правда и сила; к њему ће доћи; али ће се посрамити сви који се гњеве на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'У Господу ће се оправдати и прославити све сјеме Израиљево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Паде Вил, извали се Нево; ликови њихови метнуше се на животињу и на стоку; што носите, тешко је, и умориће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Извалише се, падоше сви, не могоше избавити товара, него и сами отидоше у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Слушајте ме, доме Јаковљев и сви који сте остали од дома Израиљева, које носим од утробе, које држим од рођења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'И до старости ваше ја ћу бити исти, и ја ћу вас носити до сиједа вијека; ја сам створио и ја ћу носити, ја ћу вас носити и избавићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'С ким ћете ме изједначити и испоредити? кога ћете ми узети за прилику да би био као ја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Просипају злато из тобоца и мјере сребро на мјерила, плаћају златару да начини од њега бога, пред којим падају и клањају се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Мећу га на раме и носе га, и постављају га на мјесто његово, те стоји и не миче се с мјеста својега; ако га ко зове, не одзива се нити га избавља из невоље његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Памтите то, и покажите се да сте људи, узмите на ум, преступници!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Памтите што је било од старине; јер сам ја Бог, и нема другога Бога, и нико није као ја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Који од почетка јављам крај и издалека што још није било; који кажем: намјера моја стоји и учинићу све што ми је воља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Зовем с истока птицу и из даљне земље човјека који ће извршити што сам наумио. Рекох и довешћу то, наумих и учинићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Слушајте ме, који сте упорна срца, који сте далеко од правде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Приближих правду своју, није далеко, и спасење моје неће одоцнити, јер ћу у Сиону поставити спасење, у Израиљу славу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Сиђи и сједи у прах, дјевојко, кћери Вавилонска; сједи на земљу, нема пријестола, кћери Халдејска; јер се нећеш више звати њежна и љупка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Узми жрвње, и мељи брашно откриј косу своју, изуј се, загали голијени, иди преко ријека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Откриће се голотиња твоја, и видјеће се срамота твоја; осветићу се, и нико ми неће сметати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Име је избавитељу нашему Господ над војскама, светац Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Сједи мучећи, и уђи у таму, кћери Халдејска; јер се нећеш више звати госпођа царствима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Разгњевих се на народ свој, оскврних нашљедство своје и предадох га теби у руке; а ти им не показа милости; на старце си метала претешки јарам свој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'И говорила си: довијека ћу бити госпођа; али никад нијеси то узимала на ум, нити си помишљала шта ће бити на пошљедак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Сада дакле чуј ово, која живиш у сластима и без бриге сједиш и говориш у срцу свом: ја сам, и нема друге осим мене, нећу бити удовица нити ћу осиротјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'То ће ти обоје доћи уједанпут, у исти дан, да осиротиш и обудовиш, доћи ће ти потпуно, ради мноштва чини твојих и ради велике силе чарања твога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Јер си се поуздала у злоћу своју говорећи: нико ме не види. Мудрост твоја и знање твоје преварише те, те си говорила у срцу свом: ја сам, и осим мене нема друге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Зато ће доћи на те зло, а нећеш знати одакле излази, и попашће те невоља, да је нећеш моћи одбити, и доћи ће на те уједанпут погибао, за коју нећеш знати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Стани сада с врачањем својим и с мноштвом чини својих, око којих си се трудила од младости своје, не би ли се помогла, не би ли се окријепила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Уморила си се од мноштва намјера својих; нека стану сада звјездари, који гледају звијезде, који проричу свакога мјесеца, и нека те сачувају од онога што ће доћи на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Гле, они су као пљева, огањ ће их спалити, ни сами себе неће избавити из пламена; неће остати угља да се ко огрије, ни огња да би се посједјело код њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Таки ће бити они с којима си се трудила и с којима си трговала од младости своје, разбјећи ће се сваки на своју страну; неће бити никога да те избави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Чујте ово, доме Јаковљев, који се зовете именом Израиљевијем, и из воде Јудине изидосте, који се кунете именом Господњим, и Бога Израиљева помињете, али не по истини и по правди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Јер се именују по светом граду, ослањају се на Бога Израиљева, којему је име Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Што је пређе бивало, казивах напријед одавна, и што из мојих уста изиде и објавих, учиних брзо и зби се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Знао сам да си упоран, и врат да ти је гвоздена жила, и чело да ти је од мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'И зато ти одавна објавих, прије него се зби казах ти, да не би рекао: идол мој учини то, и лик мој резани и лик мој ливени заповједише тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Чуо си; погледај све то; а ви нећете ли објављивати? отселе ти јављам ново и сакривено, што нијеси знао;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Сада се створи, и недавно, и прије овога дана нијеси чуо, да не речеш: гле, знао сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Нити си чуо ни знао, и прије ти се уши не отворише, јер знадијах да ћеш чинити невјеру, и да се зовеш преступник од утробе материне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Имена својега ради устегнућу гњев свој, и ради хвале своје уздржаћу се према теби, да те не истријебим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Ево, претопићу те, али не као сребро, пребраћу те у пећи невоље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Себе ради, себе ради учинићу, јер како би се хулило на име моје? и славе своје нећу дати другоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Чуј ме, Јакове и Израиљу, којега ја позвах: ја сам први, ја сам и пошљедњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'И моја је рука основала земљу, и моја је десница измјерила небеса пеђу; кад их зовнем, сви дођу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Скупите се сви и чујте: ко је од њих објавио ово? Господ га милује, он ће извршити вољу његову на Вавилону, и мишица ће његова бити насупрот Халдејцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Ја, ја рекох, и позвах га, довешћу га, и биће срећан на свом путу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Приступите к мени, чујте ово: од почетка нијесам говорио тајно; откако то би, бијах ондје; а сада Господ Господ посла ме и дух његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Овако вели Господ, избавитељ твој, светац Израиљев: ја сам Господ Бог твој који те учим да би напредовао, водим те путем којим треба да идеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'О, да си пазио на заповјести моје! мир би твој био као ријека, и правда твоја као валови морски;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'И сјемена би твојега било као пијеска, и порода утробе твоје као зрна његовијех; име се њихово не би затрло ни истријебило испред мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Изидите из Вавилона, бјежите од Халдејаца; гласно пјевајући објављујте, казујте, разглашујте до крајева земаљских; реците: избави Господ слугу својега Јакова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Неће ожедњети кад их поведе преко пустиње; воду из стијене точиће им, јер ће расцијепити камен и потећи ће вода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Нема мира безбожницима вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Послушајте ме, острва, и пазите народи даљни. Господ ме позва од утробе; од утробе матере моје помену име моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'И учинио је уста моја да су као оштар мач, у сјену руке своје сакри ме; учинио ме је сјајном стријелом, и у тулу својем сакри ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'И рече ми: ти си слуга мој, у Израиљу ћу се тобом прославити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'А ја рекох: узалуд се трудих узалуд и напразно потроших силу своју; али опет суд је мој у Господа и посао мој у Бога мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'А сада говори Господ, који ме је саздао од утробе материне да сам му слуга, да му доведем натраг Јакова; ако се Израиљ и не сабере, опет ћу се прославити пред Господом, и Бог ће мој бити сила моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'И рече ми: мало је да ми будеш слуга да се подигне племе Јаковљево и да се врати остатак Израиљев, него те учиних видјелом народима да будеш моје спасење до крајева земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Овако вели Господ, избавитељ Израиљев, светац његов, ономе којега презиру, на кога се гади народ, слузи онијех који господаре: цареви ће видјети и устати, и кнезови ће се поклонити ради Господа, који је вјеран, ради свеца Израиљева, који те је изабрао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Овако вели Господ: у вријеме милосно услиших те, и у дан спасења помогох ти; и чуваћу те и даћу те да будеш завјет народу да утврдиш земљу и наслиједиш опустјело нашљедство;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Да кажеш сужњима: изидите; онима који су у мраку: покажите се. Они ће покрај путова пасти, и паша ће им бити по свијем високим мјестима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Неће бити гладни ни жедни, неће их бити врућина ни сунце; јер коме их је жао, он ће их водити, и покрај извора воденијех проводиће их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'И све горе своје обратићу у путове, и стазе ће моје бити повишене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Гле, ови ће из далека доћи, гле, и они од сјевера и од запада, и они из земље Синске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Пјевајте, небеса, и весели се, земљо, подвикујте, горе, весело; јер Господ утјеши свој народ, и на невољнике своје смилова се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Али Сион рече: остави ме Господ, и заборави ме Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Може ли жена заборавити пород свој да се не смилује на чедо утробе своје? А да би га и заборавила, ја нећу заборавити тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Гле, на длановима сам те изрезао; зидови су твоји једнако преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Похитјеће синови твоји, а који те раскопаваше и пустошише, отићи ће од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Подигни очи своје унаоколо, и види: сви се они скупљају и иду к теби. Тако био ја жив, вели Господ, свјема њима као накитом заодјенућеш се, и уресићеш се њима као невјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Јер развалине твоје и пустолине и потрвена земља твоја биће тада тијесна за становнике кад се удаље они који те прождираше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'И дјеца коју ћеш имати, пошто си била без дјеце, рећи ће да чујеш: тијесно ми је ово мјесто, помакни се да се могу настанити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'А ти ћеш рећи у срцу свом: ко ми их роди, јер бијах сирота и инокосна, заробљена и прогнана? и ко их отхрани? ето, ја бијах остала сама, а гдје они бијаху?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Овако вели Господ Господ: ево, подигнућу руку своју к народима, и к племенима ћу подигнути заставу своју, и донијеће синове твоје у наручју, и кћери твоје на раменима ће се носити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'И цареви ће бити хранитељи твоји и царице њихове твоје дојкиње, и клањаће ти се лицем до земље, и прах с ногу твојих лизаће, и познаћеш да сам ја Господ, и да се неће осрамотити они који мене чекају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Хоће ли се јунаку узети плијен и хоће ли се отети робље праведному?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Јер овако говори Господ: и робље јунаку узеће се и плијен јакому отеће се, јер ћу се ја прети с онима који се с тобом пру, и синове твоје ја ћу избавити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'И који ти криво чине, нахранићу их њиховијем месом и опиће се својом крвљу као новијем вином; И познаће свако тијело да сам ја Господ спаситељ твој и избавитељ твој, јаки Бог Јаковљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Овако вели Господ: гдје је распусна књига матере ваше којом је пустих? или који је између рукодавалаца мојих коме вас продадох? Гле, за безакоња своја продадосте се и за ваше пријеступе би пуштена мати ваша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Зашто кад дођох не би никога? кад звах, нико се не одазва? да није како год окрачала рука моја, те не може искупити? или нема у мене снаге да избавим? Гле, пријетњом својом исушујем море; обраћам ријеке у пустињу да се усмрде рибе њихове зато што нестане воде, и мру од жеђи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Облачим небеса у мрак, и костријет им дајем за покривач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Господ Господ даде ми језик учен да умијем проговорити згодну ријеч уморном; буди свако јутро, буди ми уши, да слушам као ученици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Господ Господ отвори ми уши, и ја се не противих, не отступих натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Леђа своја подметах онима који ме бијаху и образе своје онима који ме чупаху; не заклоних лица својега од руга ни од запљувања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Јер ми Господ Господ помаже, зато се не осрамотих, зато ставих чело своје као кремен, и знам да се нећу постидјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Близу је онај који ме правда; ко ће се прети са мном? станимо заједно; ко је супарник мој? нека приступи к мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Гле, Господ Господ помагаће ми: ко ће ме осудити? Гле, сви ће они као хаљина оветшати, мољац ће их изјести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Ко се међу вама боји Господа и слуша глас слуге његова? Ко ходи по мраку и нема видјела, нека се узда у име Господње и нека се ослања на Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Гле, сви који ложите огањ и опасујете се искрама, идите у свјетлости огња својега и у искрама које распалисте. То вам је из моје руке, у мукама ћете лежати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Послушајте ме који идете за правдом, који тражите Господа; погледајте стијену из које сте исјечени, и дубоку јаму из које сте ископани;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Погледајте Аврама, оца својега, и Сару, која вас је родила, како га инокосна позвах и благослових га и умножих га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Јер ће Господ утјешити Сион, утјешиће све развалине његове, и пустињу његову учиниће да буде као Едем и пустош његова као врт Господњи, радост ће се и весеље налазити у њему, захваљивање и пјевање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Послушај ме, народе мој, и чуј ме, роде мој; јер ће закон од мене изаћи и суд свој поставићу да буде видјело народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Близу је правда моја, изаћи ће спасење моје, и мишице ће моје судити народима; мене ће острва чекати и у моју ће се мишицу уздати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Подигните к небу очи своје и погледајте доље на земљу; јер ће небеса ишчезнути као дим и земља ће као хаљина оветшати, и који на њој живе помријеће такођер; а спасење ће моје остати довијека, а правде моје неће нестати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Послушајте ме који знате правду, народе, којему је у срцу закон мој. Не бојте се ружења људскога и од хуљења њихова не плашите се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Јер ће их мољац изјести као хаљину, и као вуну изјешће их црв; а правда моја остаје довијека и спасење моје од кољена на кољено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Пробуди се, пробуди се, обуци се у силу, мишицо Господња; пробуди се као у старо вријеме, за нараштаја прошлијех; нијеси ли ти исјекла Раву и ранила змаја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Нијеси ли ти исушила море, воду бездана великога, од дубине морске начинила пут да прођу избављени?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Тако они које искупи Господ нека се врате и дођу у Сион пјевајући, и весеље вјечно нека буде над главом њиховом; радост и весеље нека задобију, а жалост и уздисање нека бјежи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Ја, ја сам утјешитељ ваш; ко си ти да се бојиш човјека смртнога и сина човјечијега, који је као трава?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'И заборавио си Бога творца својега, који је разапео небеса и основао земљу? и једнако се бојиш сваки дан гњева онога који те притјешњује кад се спрема да затире? а гдје је гњев онога који притјешњује?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Брзо ће се опростити сужањ, неће умријети у јами, нити ће бити без хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Јер сам ја Господ Бог твој, који раскидам море, да валови његови буче; Господ над војскама име ми је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Ја ти метнух у уста ријечи своје и сјеном руке своје заклоних те, да утврдим небеса и оснујем земљу, и речем Сиону: ти си мој народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Пробуди се, пробуди се, устани, Јерусалиме! који си пио из руке Господње чашу гњева његова, пио си, и талог из страшне чаше испио си.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Од свијех синова које је родио ниједан га није водио, и од свијех синова које је отхранио ниједан га није прихватио за руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Ово те двоје задеси; ко те пожали? Пустош и расап, и глад и мач; ко ће те утјешити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Синови твоји обамрли леже по крајевима свијех улица као биво у мрежи пуни гњева Господњега, и карања Бога твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Зато чуј ово, невољни, и пијани, не од вина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Овако вели Господ твој, Господ и Бог твој, који брани свој народ: ево узимам из твоје руке чашу страшну, талог у чаши гњева својега; нећеш више пити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Него ћу је дати у руке онима који те муче који говорише души твојој: сагни се да пријеђемо, и ти си им подметао леђа своја да буду као земља и као улица онима који прелазе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Пробуди се, пробуди се, обуци се у силу своју, Сионе; обуци красне хаљине своје, Јерусалиме граде свети; јер неће више ући у тебе необрезани и нечисти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Отреси прах са себе, устани, сједи, Јерусалиме; скини окове с врата својега, заробљена кћери Сионска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Јер овако вели Господ: забадава се продадосте, и искуписте се без новаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Јер овако вели Господ Господ: у Мисир сиђе мој народ прије да ондје живе као дошљаци, али Асирци им чинише силу ни за што.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'А сада што ћу ту? вели Господ; јер је народ мој заборављен ни за што; који владају њим, цвијеле га, вели Господ, и једнако сваки дан хули се на име моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Зато ће познати народ мој име моје, зато ће познати у онај дан да сам ја који говорим: ево ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Како су красне на горама ноге онога који носи добре гласе, који оглашује мир, који јавља добро, оглашује спасење, говори Сиону: Бог твој царује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Стражари ће твоји подигнути глас, подигнуће глас, и сви ће запјевати, јер ће очима видјети гдје Господ води натраг Сион.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Кликујте и пјевајте, развалине Јерусалимске, јер Господ утјеши народ свој, избави Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Загали Господ свету мишицу своју пред свијем народима, да виде сви крајеви земаљски спасење Бога нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Отступите, отступите, изидите одатле, не дотичите се ничега нечиста; изидите испред њега, очистите се ви који носите суде Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Јер нећете изаћи у хитњи, нити ћете ићи бјежећи; јер ће Господ ићи пред вама, и задња војска биће вам Бог Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Гле, слуга ће мој бити срећан, подигнуће се и узвисиће се и прославиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Како се многи зачудише теби, што бијаше нагрђен у лицу мимо свакога човјека, и у стасу мимо синове човјечије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'Тако ће опет удивити многе народе, цареви ће пред њим затиснути уста своја, јер ће видјети што им није казивано и разумјеће што нијесу слушали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Ко вјерова проповиједању нашему, и мишица Господња коме се откри?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Јер изниче пред њим као шибљика, и као коријен из сухе земље; не би обличја ни љепоте у њега; и видјесмо га, и не бјеше ништа на очима, чега ради бисмо га пожељели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Презре бјеше и одбачен између људи, болник и вичан болестима, и као један од кога свак заклања лице, презрен да га ни за што не узимасмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'А он болести наше носи и немоћи наше узе на се, а ми мишљасмо да је рањен, да га Бог бије и мучи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Али он би рањен за наше пријеступе, избијен за наша безакоња; кар бјеше на њему нашега мира ради, и раном његовом ми се исцијелисмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Сви ми као овце зађосмо, сваки нас се окрену својим путем, и Господ пусти на њ безакоње свијех нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Мучен би и злостављен, али не отвори уста својих; као јагње на заклање вођен би и као овца нијема пред онијем који је стриже не отвори уста својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Од тјескобе и од суда узе се, а род његов ко ће исказати? јер се истрже из земље живијех и за пријеступе народа мојега би рањен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Одредише му гроб са злочинцима, али на смрти би с богатијем, јер не учини неправде, нити се нађе пријевара у устима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Али Господу би воља да га бије, и даде га на муке; кад положи душу своју у принос за гријех, видјеће натражје, продуљиће дане, и што је Господу угодно напредоваће његовом руком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Видјеће труд душе своје и наситиће се; праведни слуга мој оправдаће многе својим познањем, и сам ће носити безакоња њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Зато ћу му дати дио за многе, и са силнима ће дијелити плијен, јер је дао душу своју на смрт, и би метнут међу злочинце, и сам носи гријехе многих, и за злочинце се моли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Весели се, нероткињо која не рађаш, запјевај и покликни ти, која не трпиш мука од порођаја, јер пуста има више дјеце него ли она која има мужа, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Рашири мјесто шатора својега, и завјеси стана твојега нека се разастру, не брани, продуљи ужа своја, коље своје утврди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Јер ћеш се надесно и налијево распространити, и сјеме ће твоје наслиједити народе, и пусте ће градове населити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Не бој се, јер се нећеш осрамотити, и немој се стидјети, јер нећеш бити пријекорна, него ћеш заборавити срамоту младости своје, и пријекора удовишта својега нећеш се више сјећати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Јер ти је муж творац твој, име му је Господ над војскама, и избавитељ ти је светац Израиљев, Бог свој земљи зваће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Јер као жену остављену и у духу ожалошћену дозва те Господ, и као младу жену пуштену, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Замало оставих те, али с великом милошћу прибраћу те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'У малом гњеву сакрих за час лице своје од тебе, али ћу те вјечном милошћу помиловати, вели избавитељ твој Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Јер ми је то као потоп Нојев: јер као што се заклех да потоп Нојев неће више доћи на земљу, тако се заклех да се нећу разгњевити на те нити ћу те карати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Ако ће се и горе помакнути и хумови се поколебати, опет милост моја неће се одмакнути од тебе, и завјет мира мојега неће се поколебати, вели Господ, који ти је милостив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Невољнице, коју вјетар размеће, која си без утјехе, ево ја ћу намјестити камење твоје на мрамору порфирном, и основаћу те на сафирима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'И начинићу ти прозоре од кристала, и врата од камена рубина, и све међе твоје од драгога камења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'А синови ће твоји сви бити научени од Господа, и обилан мир имаће синови твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Правдом ћеш се утврдити, далеко ћеш бити од насиља, те се нећеш бојати, и од страхоте, јер ти се неће приближити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Гле, биће их који ће се сабирати на те, али неће бити од мене; који се год саберу на те, пашће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Гле, ја сам створио ковача који распаљује угљевље и вади оруђе за свој посао, ја сам створио и крвника да убија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Никако оружје начињено против тебе неће бити срећно, и сваки језик који се подигне на те на суду сапрећеш. То је нашљедство слуга Господњих и правда њихова од мене, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Ој жедни који сте год, ходите на воду, и који немате новаца, ходите, купујте и једите; ходите, купујте без новаца и без плате вина и млијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Зашто трошите новце своје на оно што није храна, и труд свој на оно што не сити? Слушајте ме, па ћете јести што је добро, и душа ће се ваша насладити претилине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Пригните ухо своје и ходите к мени; послушајте, и жива ће бити душа ваша, и учинићу с вама завјет вјечан, милости Давидове истините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Ево, дадох га за свједока народима, за вођа и заповједника народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Ево, зваћеш народ којега нијеси знао, и народи који те нијесу знали стећи ће се к теби, ради Господа Бога твојега и свеца Израиљева, јер те прослави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Тражите Господа, док се може наћи; призивајте га, докле је близу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Нека безбожник остави свој пут и неправедник мисли своје; и нека се врати ка Господу, и смиловаћу се на њ, и к Богу нашему, јер прашта много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Јер мисли моје нијесу ваше мисли, нити су ваши путови моји путови, вели Господ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Него колико су небеса више од земље, толико су путови моји виши од ваших путова, и мисли моје од ваших мисли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Јер како пада дажд или снијег с неба и не враћа се онамо, него натапа земљу и учини да рађа и да се зелени, да даје сјемена да се сије и хљеба да се једе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'Тако ће бити ријеч моја кад изиде из мојих уста: неће се вратити к мени празна, него ће учинити што ми је драго, и срећно ће свршити на што је пошљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Јер ћете с весељем изаћи, и у миру ћете бити вођени; горе и брегови пјеваће пред вама од радости, и сва ће дрвета пољска пљескати рукама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Мјесто трња никнуће јела, мјесто коприве никнуће мирта; и то ће бити Господу у славу, за вјечан знак, којега неће нестати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Овако вели Господ: пазите на суд, и творите правду, јер ће скоро доћи спасење моје, и правда ће се моја објавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Благо човјеку који тако чини, и сину човјечијему који се држи тога чувајући суботу да је не оскврни, чувајући руку своју да не учини зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'И нека не говори туђин који пристане уз Господа: Господ ме је одлучио од свога народа; и нека не говори ушкопљеник: гле, ја сам сухо дрво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Јер овако вели Господ за ушкопљенике: који држе суботе моје и избирају што је мени угодно, и држе завјет мој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Њима ћу дати у дому свом и међу зидовима својим мјесто и име боље него синова и кћери, име вјечно даћу свакоме од њих, које се неће затрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'А туђине који пристану уз Господа да му служе и да љубе име Господње, да му буду слуге, који год држе суботу да је не оскврне и држе завјет мој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Њих ћу довести на свету гору своју и развеселићу их у дому својем молитвеном; жртве њихове паљенице и друге жртве биће угодне на олтару мом, јер ће се дом мој звати дом молитве свијем народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Господ Господ говори, који сабира прогнанике Израиљеве: још ћу му сабрати осим онијех који су сабрани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Све звијери пољске, ходите да једете, све звијери шумске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Сви су му стражари слијепи, ништа не знају, сви су пси нијеми, не могу лајати, санљиви су, леже, мио им је дријемеж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'И пси су прождрљиви, који не знају за ситост; и пастири су који не знају за разум, сваки се окреће својим путем, сваки за својом коришћу са свога краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Ходите, узећу вина и напићемо се силовита пића, и сјутра ће бити као данас, и још много више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Праведник мре, и нико не мари; и побожни се људи узимају, а нико се не сјећа да се пред зло узима праведник;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Долази у мир и почива на постељи својој ко год ходи правијем путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'А ви синови врачарини, роде курварски, који се курвате, приступите овамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Ким се ругате? на кога разваљујете уста и плазите језик? нијесте ли синови преступнички, сјеме лажно?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Који се упаљујете за луговима, под сваким зеленијем дрветом, кољете синове своје у потоцима, под врлетима каменијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Дио ти је међу глатким камењем поточним; то је, то је твој дио; њему љеваш наљев свој, приносиш дар; тијем ли ћу се умирити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'На гори високој и узвишеној мећеш постељу своју; и онамо излазиш да принесеш жртву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'И иза врата и иза довратака мећеш спомен свој; отступивши од мене откриваш се, и изашавши горе шириш одар свој, уговараш с њима, мила ти је постеља њихова, гдје угледаш мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Идеш к цару с уљем, с многим мирисима својим; шаљеш посланике своје далеко и понизујеш се до гроба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Од даљнога пута свога уморна не кажеш: залуду. Налазиш живот руци својој, зато не сустајеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'И од кога си се уплашила и кога си се побојала, те си слагала и нијеси се мене опомињала нити си марила? што ја мучах одавна, зато ли ме се не бојиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Ја ћу објавити твоју правду и твоја дјела; али ти неће помоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Кад станеш викати, нека те избаве они које си сабрала; али ће их све вјетар однијети, и узеће их таштина. Али ко се у ме узда, наслиједиће земљу и добиће свету гору моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'И рећи ће се: поравните, поравните, приправите пут, уклоните сметње с пута народа мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Јер овако говори високи и узвишени, који живи у вјечности, којему је име свети: на висини и у светињи станујем и с онијем ко је скрушена срца и смјерна духа оживљујући дух смјернијех и оживљујући срце скрушенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Јер се нећу једнако прети нити ћу се довијека гњевити, јер би ишчезнуо преда мном дух и душе које сам створио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'За безакоње лакомости његове разгњевих се, и ударих га, сакрих се и разгњевих се, јер одметнувши се отиде путем срца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Видим путове његове, али ћу га исцијелити, водићу га и даћу опет утјеху њему и његовијем који туже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Ја стварам плод уснама: мир, мир оному ко је далеко и ко је близу, вели Господ, и исцијелићу га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'А безбожници су као море усколебано, које се не може умирити и вода његова измеће нечистоту и блато.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Нема мира безбожницима, вели Бог мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Вичи из грла, не устежи се, подигни глас свој као труба, и објави народу мојему безакоња његова и дому Јаковљеву гријехе њихове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Премда ме сваки дан траже и ради су знати путове моје, као народ који твори правду и не оставља суда Бога својега; ишту од мене судове праведне, желе приближити се к Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Зашто постисмо, веле, а ти не погледа, мучисмо душе своје, а ти не хтје знати? Гле, кад постите, чините своју вољу и изгоните све што вам је ко дужан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Ето постите да се прете и свађате и да бијете песницом безбожно. Немојте постити тако као данас, да би се чуо горе глас ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Таки ли је пост који изабрах да човјек мучи душу своју један дан? да савија главу своју као сита и да стере пода се костријет и пепео? То ли ћеш звати пост и дан угодан Господу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'А није ли ово пост што изабрах: да развежеш свезе безбожности, да раздријешиш ремење од бремена, да отпустиш потлачене, и да изломите сваки јарам?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Није ли да преламаш хљеб свој гладноме, и сиромахе прогнане да уведеш у кућу? кад видиш гола, да га одјенеш, и да се не кријеш од свога тијела?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Тада ће синути видјело твоје као зора, и здравље ће твоје брзо процвасти, и пред тобом ће ићи правда твоја, слава Господња биће ти задња стража.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Тада ћеш призивати, и Господ ће те чути: викаћеш, и рећи ће: ево ме. Ако избациш између себе јарам и престанеш пружати прст и говорити зло;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'И ако отвориш душу своју гладноме, и наситиш душу невољну; тада ће засјати у мраку видјело твоје и тама ће твоја бити као подне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Јер ће те Господ водити вазда, и ситиће душу твоју на суши, и кости твоје кријепиће, и бићеш као врт заливен и као извор којему вода не пресише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'И твоји ће сазидати старе пустолине, и подигнућеш темеље који ће стајати од кољена до кољена, и прозваћеш се: који сазида развалине и оправи путове за насеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Ако одвратиш ногу своју од суботе да не чиниш што је теби драго на мој свети дан, и ако прозовеш суботу милином, свети дан Господњи славнијем, и будеш га славио не идући својим путовима и не чинећи што је теби драго, ни говорећи ријечи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'Тада ћеш се веселити у Господу, и извешћу те на висине земаљске, и даћу ти да једеш нашљедство Јакова оца својега; јер уста Господња рекоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Гле, није окрачала рука Господња да не може спасти, нити је отежало ухо његово да не може чути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Него безакоња ваша раставише вас с Богом вашим, и гријеси ваши заклонише лице његово од вас, да не чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Јер су руке ваше оскврњене крвљу и прсти ваши безакоњем; усне ваше говоре лаж и језик ваш изриче опачину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Нема никога да виче за правду, нити има да се пре за истину; уздају се у ништавило, и говоре лаж; зачињу невољу, и рађају муку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Носе јаја аспидина и ткају паучину; ко поједе јаје њихово умре, и ако које разбије, ижљезе гуја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Платно њихово није за хаљине, нити ће се они одјести својим послом; посао је њихов безакоње и у рукама је њиховијем насиље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Ноге им трче на зло и брзе су на прољевање крви праве; мисли су њихове безакоње; на путовима је њиховијем пустош и расап.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Пута мирнога не знају, и на путовима њиховијем нема правде; начинили су себи криве стазе; ко год иде по њима, не зна за мир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Зато је суд далеко од нас, и правда не долази до нас; чекамо видјело, а оно, ето мрак; свјетлост, а оно ходимо по тами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Пипамо као слијепци зид, као они који немају очију пипамо; спотичемо се у подне као у сумрачје; у обиљу смо као мртви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Ричемо свиколики као медвједи, и једнако учемо као голубице; чекамо суд, а њега нема, спасење, а оно је далеко од нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Јер се пријеступи наши умножише пред тобом и гријеси наши свједоче на нас; јер су пријеступи наши код нас и безакоња своја знамо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Да невјеру учинисмо и слагасмо Господу, и отступисмо од Бога својега, говорисмо о насиљу и одмету, да састављасмо и износисмо из срца ријечи лажне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Зато суд отступи натраг, и правда стоји далеко; јер истина паде на улици и правда не може да прође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'И истине је нестало, и ко се уклања ода зла, постаје плијен. То видје Господ, и не би му мило што нема суда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'И видје гдје нема човјека, и зачуди се што нема посредника; зато учини му спасење мишица његова, и правда његова подуприје га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Јер се обуче у правду као у оклоп, и шљем спасења метну на главу; одједе се осветом као одијелом, и огрте се ревношћу као плаштем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'По дјелима, по дјелима да врати гњев противницима својим, плату непријатељима својим, острвима да плати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'И бојаће се имена Господњега са запада, и славе његове с истока сунчанога; јер ће непријатељ навалити као ријека, а дух ће Господњи подигнути заставу супрот њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'И доћи ће избавитељ у Сион и к онима од Јакова који се обраћају од гријеха, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'А ово ће бити завјет мој с њима, вели Господ: дух мој, који је у теби, и ријечи моје, које метнух у уста твоја, неће отићи од уста твојих ни од уста сјемена твојега, ни од уста сјемена сјемена твојега, вели Господ, отселе и довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Устани, свијетли се, јер дође свјетлост твоја, и слава Господња обасја те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Јер, гле, мрак ће покрити земљу и тама народе; а тебе ће обасјати Господ и слава његова показаће се над тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'И народи ће доћи к видјелу твојему и ка свјетлости која ће те обасјати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Подигни очи своје унаоколо, и види: сви се скупљају и иду к теби, синови ће твоји из далека доћи и кћери твоје носиће се у наручју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Тада ћеш видјети, и обрадоваћеш се, и срце ће ти се удивити и раширити, јер ће се к теби окренути мноштво морско и сила народа доћи ће к теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Мноштво камила прекрилиће те, дромедари из Мадијама и Ефе; сви из Саве доћи ће, злато и кад донијеће, и славу Господњу јављаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Сва стада Кидарска скупиће се к теби, овнови Навајотски биће ти за потребу; принесени на олтару мом биће угодни, и дом славе своје прославићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Ко су оно што лете као облаци и као голубови на прозоре своје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Острва ће ме чекати и прве лађе Тарсиске, да довезу синове твоје из далека, и с њима сребро њихово и злато њихово, имену Господа Бога твојега и свеца Израиљева, јер те прослави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'И туђини ће сазидати зидове твоје, и цареви њихови служиће ти; јер у гњеву свом ударих те, а по милости својој помиловаћу те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'И твоја ће врата бити свагда отворена, неће се затворити ни дању ни ноћу, да ти се доведе сила народа, и цареви њихови да се доведу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Јер народ и царство, које ти не би служило, погинуће, таки ће се народи сасвијем затрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Слава Ливанска теби ће доћи, јела, бријест и шимшир, да украсе мјесто светиње моје да би прославио мјесто ногу својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'И синови онијех који су те мучили доћи ће к теби клањајући се, и сви који те презираше падаће к стопалима ногу твојих, и зваће те градом Господњим, Сионом свеца Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Што си био остављен и мрзак тако да нико није пролазио кроза те, мјесто тога ћу ти учинити вјечну славу, и весеље од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Јер ћеш млијеко народа сати, и сисе царске дојићеш, и познаћеш да сам ја Господ спаситељ твој и избавитељ твој, силни Јаковљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Мјесто мједи донијећу злата, и мјесто гвожђа донијећу сребра, и мједи мјесто дрва, и гвожђа мјесто камења, и поставићу ти за управитеље мир и за настојнике правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Неће се више чути насиље у твојој земљи ни пустошење и потирање на међама твојим; него ћеш звати зидове своје спасењем и врата своја хвалом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Неће ти више бити сунце видјело дању, нити ће ти сјајни мјесец свијетлити; него ће ти Господ бити видјело вјечно и Бог твој биће ти слава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Неће више залазити сунце твоје, нити ће мјесец твој помрчати; јер ће ти Господ бити видјело вјечно, и дани жалости твоје свршиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'И твој ће народ бити сав праведан, наслиједиће земљу навијек; младица коју сам посадио, дјело руку мојих биће на моју славу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Од малога ће постати тисућа и од нејакога силан народ; ја Господ брзо ћу учинити то кад буде вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Дух је Господа Бога на мени, јер ме Господ помаза да јављам добре гласе кроткима, посла ме да завијем рањене у срцу, да огласим заробљенима слободу и сужњима да ће им се отворити тамница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Да огласим годину милости Господње и дан освете Бога нашега, да утјешим све жалосне,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Да учиним жалоснима у Сиону и дам им накит мјесто пепела, уље радости мјесто жалости, одијело за похвалу мјесто духа тужнога, да се прозову храстови правде, сад Господњи за славу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'И они ће сазидати давнашње пустолине, подигнуће старе развалине и поновиће градове пусте, што леже разваљени од много нараштаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'И туђини ће стајати и пасти стада ваша, и иностранци ће бити ваши орачи и виноградари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'А ви ћете се звати свештеници Господњи, слуге Бога нашега говориће вам се, благо народа јешћете и славом њиховом хвалићете се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'За двоструку срамоту вашу, и што се пјеваше: руг је дио њихов, зато ће у земљи њиховој наслиједити двојином и имаће вјечну радост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Јер ја Господ љубим правду и мрзим на грабеж са жртвом паљеницом, и даћу им плату уистину, и вјечан завјет учинићу с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'И сјеме ће се њихово знати у народима и натражје њихово међу племенима; ко их год види познаће их да су сјеме које је благословио Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Веома ћу се радовати у Господу, и душа ће се моја веселити у Богу мојем, јер ме обуче у хаљине спасења и плаштем правде огрте ме као кад женик намјести накит и као кад се невјеста уреси уресом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Јер као што из земље расте биље и у врту ниче што се посије, тако ће Господ Бог учинити да никне правда и похвала пред свијем народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Сиона ради нећу умукнути, и Јерусалима ради нећу се умирити, докле не изађе као свјетлост правда његова и спасење се његово разгори као свијећа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Тада ће видјети народи правду твоју и сви цареви славу твоју, и прозваћеш се новијем именом, које ће уста Господња изрећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'И бићеш красан вијенац у руци Господњој и царска круна у руци Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Нећеш се више звати остављена, нити ће се земља твоја звати пустош, него ћеш се звати милина моја и земља твоја удата, јер ћеш бити мио Господу и земља ће твоја бити удата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Јер као што се момак жени дјевојком, тако ће се синови твоји оженити тобом; и како се радује женик невјести, тако ће се теби радовати Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'На зидовима твојим, Јерусалиме, поставих стражаре, који неће умукнути нигда, ни дању ни ноћу. Који помињете Господа, немојте мучати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'И не дајте да се умукне о њему докле не утврди и учини Јерусалим славом на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Закле се Господ десницом својом и крјепком мишицом својом: нећу више дати жита твојега непријатељима твојим да једу, нити ће туђини пити вина твојега, око којега си се трудио;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Него који га жању, они ће га јести и хвалити Господа, и који га беру они ће га пити у тријемовима светиње моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Прођите, прођите кроз врата, приправите пут народу; поравните, поравните пут, уклоните камење, подигните заставу народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Ево, Господ огласи до крајева земаљских; реците кћери Сионској: ево, спаситељ твој иде; ево, плата је његова код њега и дјело његово пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'И они ће се прозвати народ свети, искупљеници Господњи; а ти ћеш се прозвати: тражени, град неостављени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Ко је оно што иде из Едома, из Восора, у црвенијем хаљинама? красно одјевен, корачајући у величини силе своје? Ја сам, који говорим правду и вриједан сам спасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Зашто ти је црвено одијело и хаљине ти као у онога који гази у каци?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Газих сам у каци, и нико између народа не бјеше са мном; али их изгазих у гњеву свом и потлачих у љутини својој; и крв њихова попрска ми хаљине и искаљах све одијело своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Јер је дан од освете у срцу мом, и дође година да се моји искупе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Погледах, а никога не бјеше да поможе, и зачудих се што никога не бјеше да подупре; али ме десница моја избави и јарост моја подуприје ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'И изгазих народе у гњеву свом, и опојих их јарошћу својом, и пролих на земљу крв њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Помињаћу доброту Господњу, хвалу Господњу за све што нам је учинио Господ, и мноштво добра што је учинио дому Израиљеву по милости својој и по великој доброти својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Јер рече: доиста су мој народ, синови, који неће изневјерити. И би им спаситељ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'У свакој тузи њиховој он бјеше тужан, и анђео, који је пред њим, спасе их. Љубави своје ради и милости своје ради он их избави, и подиже их и носи их све вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Али се одметаше и жалостише свети дух његов; зато им поста непријатељ, и ратова на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Али се опомену старијех времена, Мојсија, народа својега: гдје је онај који их изведе из мора с пастирем стада својега? гдје је онај што метну усред њих свети дух свој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Који их води славном мишицом својом за десницу Мојсијеву? који раздвоји воду пред њима, да стече себи вјечно име?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Који их води преко бездана као коња преко пустиње, да се не спотакоше?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Дух Господњи води их тихо, као кад стока слази у долину; тако си водио свој народ да стечеш себи славно име.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Погледај с неба, и види из стана светиње своје и славе своје, гдје је ревност твоја и сила твоја, мноштво милосрђа твојега и милости твоје? еда ли ће се мени устегнути?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Ти си заиста отац наш, ако и не зна Аврам за нас, и Израиљ нас не познаје; ти си, Господе, отац наш, име ти је откако је вијека избавитељ наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Зашто си нам дао да зађемо, Господе, с путова твојих? да нам отврдне срце да те се не бојимо? Врати се ради слуга својих, ради племена нашљедства својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Замало наслиједи народ светости твоје; непријатељи наши погазише светињу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Постасмо као они којима нијеси нигда владао нити је призивано име твоје над њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'О да би раздро небеса и сишао, да се растопе горе од тебе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Као што се на огњу разгори грање и вода узаври од огња, да име твоје познаду непријатељи твоји и да народи дркћу од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Кад си чинио страхоте којима се не надасмо, ти си слазио, и горе се растапаху од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Откако је вијека не чу се, нити се ушима дозна, нити око видје Бога осим тебе да би тако учинио онима који га чекају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Сретао си онога који се радује творећи правду; помињу те на путовима твојим; гле, ти си се разгњевио што гријешисмо; да на њима једнако остасмо, бисмо се спасли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Али сви бијасмо као нечисто што, и сва наша правда као нечиста хаљина; зато опадосмо сви као лист, и безакоња наша као вјетар однесоше нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Никога не би да призива име твоје, да устане да се тебе држи, јер си сакрио лице своје од нас и растопио си нас безакоњем нашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Али сада, Господе, ти си наш отац; ми смо као, а ти си наш лончар, и сви смо дјело руку твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Господе, не гњеви се веома, и не помињи довијека безакоња; ево, погледај; ми смо сви твој народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Градови светости твоје опустјеше; Сион опустје, Јерусалим поста пустош.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Дом наше светиње и наше красоте, у ком те славише оци наши, изгорје огњем, и све што нам бјеше драго потрвено је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Хоћеш ли се на то уздржати, Господе, и мучати, и једнако нас мучити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Потражише ме који не питаху за ме; нађоше ме који ме не тражаху; рекох народу који се не зове мојим именом: ево ме, ево ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Вас дан пружах руке своје народу непокорну, који иде за својим мислима путем који није добар,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Народу, који ме једнако гњеви у очи, који приноси жртве у вртовима и кади на опекама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Који сједе код гробова и ноћују у пећинама, једу месо свињеће и јуха им је нечиста у судовима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Који говоре: одлази, не дохватај ме се, јер сам светији од тебе. Ти су дим у ноздрвама мојим, огањ који гори вас дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Ето, написано је преда мном: нећу мучати, него ћу платити, платићу им у њедра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'За безакоња ваша и за безакоња отаца ваших, вели Господ, који кадише на горама, и на хумовима ружише ме, измјерићу им у њедра плату за дјела која чинише од почетка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Овако вели Господ: као кад ко нађе вина у грозду, па рече: не квари га, јер је благослов у њему, тако ћу учинити ради слуга својих, нећу их потрти свијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Јер ћу извести сјеме из Јакова и из Јуде нашљедника горама својим, и наслиједиће их избраници моји, и слуге моје населиће се ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'А Сарон ће бити тор за овце и долина Ахорска почивалиште за говеда народу мојему који ме тражи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'А ви, који остављате Господа, који заборављате свету гору моју, који постављате сто Гаду и љевате наљев Менију,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Вас ћу избројити под мач, и сви ћете припасти на клање, јер звах а ви се не одзивасте, говорих а ви не слушасте, него чинисте што је зло преда мном и изабрасте што мени није по вољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Зато овако вели Господ Господ: гле, слуге ће моје јести, а ви ћете гладовати; гле, слуге ће моје пити, а ви ћете бити жедни; гле, слуге ће се моје веселити, а ви ћете се стидјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Гле, слуге ће моје пјевати од радости у срцу, а ви ћете викати од жалости у срцу и ридаћете од туге у духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'И оставићете име своје избранима мојим за уклин; и Господ ће те Бог убити, а слуге ће своје назвати другим именом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Ко се узблагосиља на земљи, благосиљаће се Богом истинијем; а ко се ускуне на земљи, клеће се Богом истинијем; јер ће се прве невоље заборавити и сакривене ће бити од очију мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Јер, гле, ја ћу створити нова небеса и нову земљу, и што је прије било неће се помињати нити ће на ум долазити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Него се радујте и веселите се довијека ради онога што ћу ја створити; јер гле, ја ћу створити Јерусалим да буде весеље и народ његов да буде радост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'И ја ћу се веселити ради Јерусалима, и радоваћу се ради народа својега, и неће се више чути у њему плач ни јаук.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Неће више бити ондје малога дјетета ни старца који не би навршио дана својих; јер ће дијете умирати од сто година, а грјешник од сто година биће проклет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'И они ће градити куће и сједјеће у њима; и садиће винограде и јешће род њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Неће они градити а други се населити, неће садити а други јести, јер ће дани народу мојему бити као дани дрвету, и избраницима ће мојим оветшати дјела руку њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Неће радити узалуд, нити ће рађати за страх, јер ће бити сјеме благословенијех од Господа, и натражје ће њихово бити с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'И прије него повичу, ја ћу се одазвати; још ће говорити, а ја ћу услишити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Вук и јагње заједно ће пасти, и лав ће јести сламу као во; а змији ће бити храна прах; неће удити ни потирати на свој светој гори мојој, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Овако вели Господ: небо је пријесто мој и земља подножје ногама мојим: гдје је дом који бисте ми сазидали, и гдје је мјесто за моје почивање?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Јер је све то рука моја створила, то је постало све, вели Господ; али на кога ћу погледати? на невољнога и на онога ко је скрушена духа и ко дркће од моје ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Ко коље вола, то је као да убије човјека; ко коље овцу, то је као да закоље пса; ко приноси дар, то је као да принесе крв свињећу; ко кади кадом, то је као да благослови идола. То они изабраше на путовима својим, и души се њиховој миле гадови њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Изабраћу и ја према неваљалству њихову, и пустићу на њих чега се боје; јер звах а нико се не одазва, говорих а они не слушаше, него чинише што је зло преда мном и изабраше што мени није по вољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Слушајте ријеч Господњу, који дркћете од његове ријечи: браћа ваша, која мрзе на вас и изгоне вас имена мојега ради, говоре: нека се покаже слава Господња. И показаће се на вашу радост, а они ће се посрамити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Вика иде из града, глас из цркве, глас Господњи који плаћа непријатељима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Она се породи прије него осјети болове, прије него јој дођоше муке, роди дјетића.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Ко је игда чуо то? ко је видио тако што? Може ли земља родити у један дан? може ли се народ родити уједанпут? а Сион роди синове своје чим осјети болове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Еда ли ја, који отварам материцу, не могу родити? вели Господ: еда ли ћу ја, који дајем да се рађа, бити без порода? вели Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Радујте се с Јерусалимом и веселите се у њему сви који га љубите; радујте се с њим сви који га жалисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Јер ћете сати сисе од утјехе његове, и наситићете се, саћете и наслађиваћете се у свјетлости славе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Јер овако вели Господ: гле, ја ћу као ријеку довести к њему мир и славу народа као поток бујан, па ћете сати; бићете ношени на рукама и миловани на кољенима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Као кад кога мати његова тјеши тако ћу ја вас тјешити, и утјешићете се у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Видјећете и обрадоваће се срце ваше и кости ће се ваше помладити као трава, и знаће се рука Господња на слугама његовијем и гњев на непријатељима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Јер, гле, Господ ће доћи с огњем, и кола ће му бити као вихор, да излије гњев свој у јарости и пријетњу у пламену огњеном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Јер ће Господ судити огњем и мачем својим сваком тијелу, и много ће бити побијенијех од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Који се освештавају и који се очишћају у вртовима један за другим јавно, који једу месо свињеће и ствари гадне и мише, сви ће изгинути, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'А ја знам дјела њихова и мисли њихове, и доћи ће вријеме, те ћу сабрати све народе и језике, и доћи ће и видјеће славу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'И поставићу знак на њих, и послаћу између њих који се спасу к народима у Тарсис, у Фул и у Луд, који натежу лук, у Тувал и у Јаван и на даљна острва, која не чуше гласа о мени нити видјеше славе моје, и јављаће славу моју по народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'И сву ће браћу вашу из свијех народа довести Господу на дар на коњима и на колима и на носилима и на мазгама и на камилама ка светој гори мојој у Јерусалим, вели Господ, као што приносе синови Израиљеви дар у чисту суду у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'И између њих ћу узети свештенике и Левите, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Јер као што ће нова небеса и нова земља, што ћу ја начинити, стајати преда мном, вели Господ, тако ће стајати сјеме ваше и име ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'И од младине до младине, и од суботе до суботе долазиће свако тијело да се поклони преда мном, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'И излазиће и гледаће мртва тјелеса онијех људи који се одметнуше од мене; јер црв њихов неће умријети и огањ њихов неће се угасити, и биће гад сваком тијелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Ријечи Јеремије сина Хелкијина између свештеника који бијаху у Анатоту у земљи Венијаминовој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'Којему дође ријеч Господња у вријеме Јосије сина Амонова, цара Јудина, тринаесте године царовања његова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'И у вријеме Јоакима сина Јосијина, цара Јудина, до свршетка једанаесте године царовања Седекије сина Јосијина над Јудом, док не би пресељен Јерусалим, петога мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'И дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Прије него те саздах у утроби, знах те; и прије него изиде из утробе, посветих те; за пророка народима поставих те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'А ја рекох: ох, Господе, Господе! ево, не знам говорити, јер сам дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'А Господ ми рече: не говори: дијете сам; него иди куда те год пошљем, и говори што ти год кажем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Не бој их се, јер сам ја с тобом да те избављам, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'И пруживши Господ руку своју дотаче се уста мојих, и рече ми Господ: ето, метнух ријечи своје у твоја уста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Види, постављам те данас над народима и царствима да истребљујеш и обараш, и да затиреш и раскопаваш, и да градиш и да садиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Послије ми дође ријеч Господња говорећи: шта видиш, Јеремија? И рекох: видим прут бадемов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Тада ми рече Господ: добро си видио, јер ћу настати око ријечи своје да је извршим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Опет ми дође ријеч Господња другом говорећи: шта видиш? И рекох: видим лонац гдје ври, и предња му је страна према сјеверу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Тада ми рече Господ: са сјевера ће навалити зло на све становнике ове земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Јер, гле, ја ћу сазвати све породице из сјевернијех царстава, вели Господ, те ће доћи, и сваки ће метнути свој пријесто на вратима Јерусалимским и око свијех зидова његовијех и око свијех градова Јудинијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'И изрећи ћу им суд свој за сву злоћу њихову што ме оставише, и кадише другим боговима, и клањаше се дјелу руку својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Ти дакле опаши се и устани и говори им све што ћу ти заповиједити; не бој их се, да те не бих сатро пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Јер ево ја те постављам данас као тврд град и као ступ гвозден и као зидове мједене свој овој земљи, царевима Јудинијем и кнезовима његовијем и свештеницима његовијем и народу земаљском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Они ће ударити на те, али те не ће надвладати, јер сам ја с тобом, вели Господ, да те избављам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Иди и вичи Јерусалиму да чује и говори: овако вели Господ: опомињем те се по милости у младости твојој и по љубави о вјеридби твојој, кад иђаше за мном по пустињи, и по земљи гдје се не сије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Израиљ бјеше светиња Господу и првина од родова његовијех; који је јеђаху сви бијаху криви, зло долажаше на њих, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Чујте ријеч Господњу, доме Јаковљев и све породице дома Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Овако вели Господ: каку неправду нађоше оци ваши у мене, те отступише од мене, и присташе за ништавилом, и посташе ништави?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'И не рекоше: гдје је Господ који нас је извео из земље Мисирске, који нас је водио по пустињи, по земљи пустој и пуној пропасти, по земљи сухој и гдје је сјен смртни, по земљи преко које нико није ходио и у којој нико није живио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'И кад вас доведох у земљу родну да једете род њезин и добра њезина, дошавши оскврнисте земљу моју и од нашљедства мојега начинисте гад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Свештеници не рекоше: гдје је Господ? И који се баве законом не познаше ме, и пастири одусташе ме, и пророци пророковаше Валом и идоше за стварима залуднијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Зато ћу се још прети с вама, вели Господ, и са синовима синова ваших прећу се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Јер прођите острва Китимска и видите, и пошљите у Кидар, и разгледајте добро, и видите је ли било тако што:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Је ли који народ промијенио богове, ако и нијесу богови? а мој народ промијени славу своју на ствар залудну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Чудите се томе, небеса, и згрозите се и упропастите се! вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Јер два зла учини мој народ: оставише мене, извор живе воде, и ископаше себи студенце, студенце испроваљиване, који не могу да држе воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Је ли Израиљ роб? је ли роб у кући рођен? зашто поста грабеж?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Рикаше на њ лавићи и дизаше глас свој, и обратише земљу његову у пустош; градови су му попаљени, те нема никога да живи у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'И синови Нофски и Тафнески опасоше ти тјеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Нијеси ли то сам себи учинио оставив Господа Бога својега кад те вођаше путем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'А сада што ће ти пут Мисирски да пијеш воде Сиорске? што ли ће ти пут Асирски да пијеш воде из ријеке?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Твоја ће те злоћа покарати и твоје ће те одметање прекорити. Познај дакле и види да је зло и горко што си оставио Господа Бога својега и што нема страха мојега у теби, вели Господ Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Јер давно изломих јарам твој и раскидох свезе твоје, и ти рече: нећу бити слуга; а на сваки високи хум и под свако зелено дрво идеш да се курваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Ја те посадих лозу изабрану, све сјеме истинито; па како ми се промијени и изметну се одвода од туђе лозе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Да се измијеш салитром и узмеш много сапуна, опет ће се познавати безакоње твоје преда мном, вели Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Како можеш рећи: нијесам се оскврнио, нијесам ишао за Валима? Погледај пут свој по долу; познај шта си учинила, брза камило, која остављаш знаке на својим путовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Као дивља магарица, која је навикла на пустињу и по жељи душе своје вуче у се вјетар, кад навали, ко ће је вратити? који је траже неће се уморити, наћи ће је у мјесецу њезину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Чувај ногу своју, да није боса, и грло своје, да не жедни. Али ти велиш: од тога нема ништа; не, јер љубим туђе, и за њима ћу ићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Као што се лупеж посрами кад се ухвати, тако ће се посрамити дом Израиљев, они цареви њихови, кнезови њихови, и свештеници њихови и пророци њихови,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'Који говоре дрвету: ти си отац мој; и камену: ти си ме родио; јер ми окренуше леђа а не лице; а кад су у невољи говоре: устани и избави нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'А гдје су богови твоји које си начинио себи? нека устану, ако те могу избавити кад си у невољи, јер имаш, Јуда, богова колико градова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Зашто хоћете да се правдате са мном? ви сте се сви одметнули од мене, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Узалуд бих синове ваше, не примише науке; мач ваш прождрије пророке ваше као лав који дави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'О роде! видите ријеч Господњу; бијах ли пустиња Израиљу или мрачна земља? зашто говори мој народ: господари смо, нећемо више доћи к теби?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Заборавља ли дјевојка свој накит и невјеста урес свој? а народ мој заборави ме толико дана да им нема броја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Зашто говориш да је добар твој пут тражећи што љубиш? па си и неваљале жене научио својим путовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'И јоште на скутовима твојим налази се крв сиромаха правијех; не налазим копајући, него је на свјема њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'А ти говориш: нијесам крив, гњев се је његов одвратио од мене. Ево ја ћу се прети с тобом што говориш: нијесам згријешио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Зашто трчкаш тако мијењајући свој пут? Посрамићеш се од Мисирца како си се посрамио од Асирца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Отићи ћеш и одатле с рукама над главом својом, јер Господ одбацује узданице твоје, и нећеш бити срећан у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Говоре: ако ко пусти жену своју, и она отишавши од њега уда се за другога, хоће ли се онај вратити к њој? Не би ли се са свијем оскврнила она земља? А ти си се курвала с многим милосницима; али опет врати се к мени, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Подигни очи своје к висинама, и погледај гдје се нијеси курвала; на путовима си сједела чекајући их као Арапин у пустињи, и оскврнила си земљу курварством својим и злоћом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Зато се уставише дажди, и не би познога дажда; али у тебе бјеше чело жене курве, и не хтје се стидјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Хоћеш ли отселе викати к мени: оче мој, ти си вођ младости моје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Хоће ли се срдити једнако? хоће ли се гњевити довијека? Ето, говориш, а чиниш зло колико год можеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Још ми рече Господ за времена цара Јосије: јеси ли видио што учини одметница, Израиљ? како одлази на свако високо брдо и под свако зелено дрво, и курва се ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'И пошто учини све то, рекох: врати се к мени; али се не врати; и то видје невјерница, сестра њезина, Јуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'И свидје ми се за све то што учини прељубу одметница Израиљ да је пустим и дам јој књигу распусну; али се не побоја невјерница сестра јој Јуда, него отиде, те се и она прокурва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'И срамотнијем курвањем својим оскврни земљу, јер чињаше прељубу с каменом и с дрветом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'И код свега тога не врати се к мени невјерница сестра јој Јуда свијем срцем својим, него лажно, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Зато ми рече Господ: одметница Израиљ оправда се више него невјерница Јуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Иди и вичи ове ријечи к сјеверу, и реци: врати се, одметнице Израиљу, вели Господ, и нећу пустити да падне гњев мој на вас, јер сам милостив, вели Господ, нећу се гњевити довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Само познај безакоње своје, да си се одметнула Господу Богу својему, ти си тумарала к туђима под свако дрво зелено, и нијесте слушали гласа мојега, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Обратите се, синови одметници, вели Господ, јер сам ја муж ваш, и узећу вас, једнога из града и два из породице, и одвешћу вас у Сион.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'И даћу вам пастире по срцу својему, који ће вас пасти знањем и разумом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'И кад се умножите и народите у земљи, онда се, вели Господ, неће више говорити: ковчег завјета Господњега; нити ће им долазити на ум нити ће га помињати, нити ће ходити к њему, нити ће га више оправљати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'У то ће се вријеме Јерусалим звати пријесто Господњи, и сви ће се народи сабрати у њ, к имену Господњему у Јерусалиму, и неће више ићи по мисли срца својега злога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'У то ће вријеме дом Јудин ићи с домом Израиљевијем, и доћи ће заједно из земље сјеверне у земљу коју дадох у нашљедство оцима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Али ја рекох: како бих те поставио међу синове и дао ти земљу жељену, красно нашљедство мноштва народа? И рекох: ти ћеш ме звати: оче мој; и нећеш се одвратити од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Доиста као што жена изневјери друга својега, тако изневјеристе мене, доме Израиљев, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Глас по високим мјестима нека се чује, плач, молбе синова Израиљевијех, јер превратише пут свој, заборавише Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Вратите се, синови одметници, и исцијелићу одмете ваше. Ево, ми идемо к теби, јер си ти Господ Бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Доиста, залуду су хумови, мноштво гора; доиста, у Господу је Богу нашем спасење Израиљево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Јер та срамота прождрије труд отаца наших од дјетињства нашега, овце њихове и говеда њихова, синове њихове и кћери њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Лежимо у срамоти својој, и покрива нас руг наш; јер Господу Богу својему гријешисмо ми и оци наши од дјетињства својега до данас, и не слушасмо гласа Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Ако ћеш се вратити, Израиљу, вели Господ, к мени се врати, и ако уклониш гадове своје испред мене, нећеш се скитати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'И клећеш се истинито, вјерно и право: тако да је жив Господ. И народи ће се благосиљати њим, и њим ће се хвалити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Јер овако вели Господ Јудејцима и Јерусалимљанима: орите себи крчевину, и не сијте у трње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Обрежите се Господу, и скините окрајак са срца својега, Јудејци и Јерусалимљани, да не изиде јарост моја као огањ и разгори се да не буде никога ко би угасио за зла дјела ваша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Објавите у Јудеји и огласите у Јерусалиму и реците: трубите у трубу по земљи; вичите, сазовите народ и реците: скупите се, и уђимо у тврде градове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Подигните заставу према Сиону, бјежите и не стајте, јер ћу довести зло од сјевера и погибао велику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Излази лав из честе своје и који затире народе кренувши се иде с мјеста својега да обрати земљу твоју у пустош, градови твоји да се раскопају да не буде никога у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Зато припашите костријет, плачите и ридајте, јер се жестоки гњев Господњи није одвратио од нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'И тада ће, вели Господ, нестати срца цару и срца кнезовима, и свештеници ће се удивити и пророци ће се зачудити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'И рекох: ах Господе Господе! баш си преварио овај народ и Јерусалим говорећи: имаћете мир, а мач дође до душе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'У то ће се вријеме казати овоме народу и Јерусалиму: вјетар врућ с високих мјеста у пустињи дува ка кћери народа мојега, не да провије ни прочисти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Вјетар јачи од тијех доћи ће ми; и ја ћу им сада изрећи суд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Гле, као облак подиже се, и кола су му као вихор, коњи су му бржи од орлова. Тешко нама! пропадосмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Умиј срце своје ода зла, Јерусалиме, да би се избавио; докле ће стајати у теби мисли твоје ништаве?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Јер глас јавља од Дана, и оглашује зло од горе Јефремове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Казујте народима; ево оглашујте за Јерусалим да иду стражари из даљне земље, и пуштају глас свој на градове Јудине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Као чувари пољски стаће око њега, јер се одметну од мене, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Пут твој и дјела твоја то ти учинише; то је од зла твојега да је горко и да ти допире до срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Јаох утроба, јаох утроба! боли ме у срцу; срце ми бије; не могу мучати; јер глас трубни чујеш, душо моја, вику убојну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Погибао на погибао оглашује се; јер се пустоши сва земља, на једанпут ће се опустошити моји шатори, завјеси моји за час.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Докле ћу гледати заставу? слушати глас трубни?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Јер је народ мој безуман, не познаје ме, луди су синови и без разума, мудри су да зло чине, а добро чинити не умију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Погледах на земљу, а гле, без обличја је и пуста; и на небо, а свјетлости његове нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Погледах на горе, а гле, тресу се и сви хумови дрмају се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Погледах, а гле, нема човјека, и све птице небеске одлетјеле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Погледах, а гле, Кармил је пустиња и сви градови његови оборени од Господа, од жестокога гњева његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Јер овако говори Господ: сва ће земља опустјети; али нећу сасвијем затрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Зато ће тужити земља, и небо ће горе потамњети, јер рекох, намислих, и нећу се раскајати, нити ћу ударити натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Од вике коњика и стријелаца побјећи ће сви градови, отићи ће у густе шуме и на стијене ће се попети; сви ће градови бити остављени и нико неће у њима живјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'А ти, опустошена, шта ћеш чинити? Ако се и облачиш у скерлет, ако се и китиш накитом златнијем, и мажеш лице своје, залуду се красиш, презиру те милосници, траже душу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Јер чујем глас као породиљин, цвиљење као жене која се први пут порађа, глас кћери Сионске, која рида, пружа руке своје говорећи: тешко мени! јер ми нестаје душа од убилаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Прођите по улицама Јерусалимским, и видите сада и разберите и потражите по улицама његовијем, хоћете ли наћи човјека, има ли ко да чини што је право и да тражи истину, па ћу опростити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Ако и говоре: тако да је жив Господ! опет се криво куну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Господе! не гледају ли очи твоје на истину! Бијеш их, али их не боли; сатиреш их, али неће да приме науке, тврђе им је лице од камена, неће да се обрате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'И ја рекох: сиромаси су, лудо раде, јер не знају пута Господњега, закона Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Идем к властелима, и њима ћу говорити, јер они знају пут Господњи, закон Бога својега; али и они изломише јарам, покидаше свезе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Зато ће их побити лав из шуме, вук ће их вечерњи потрти, рис ће вребати код градова њиховијех, ко год изиде из њих биће растргнут, јер је много гријеха њиховијех и силни су одмети њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Како ћу ти опростити то? Синови твоји оставише мене, и куну се онима који нијесу богови. Како их наситих, стадоше чинити прељубу, и у кућу курвину стјечу се гомилом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Јутром су кад устају као товни коњи, сваки рже за женом ближњега својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Зато ли нећу походити? вели Господ, и душа моја неће ли се осветити таком народу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Изидите му на зидове и развалите, али немојте сасвијем затрти, скините му пријеворнице, јер нијесу Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Јер ме сасвијем изневјери дом Израиљев и дом Јудин, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Ударише у бах Господу и рекоше: није тако, неће нас зло задесити, и нећемо видјети мача ни глади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'А ти пророци отићи ће у вјетар, и ријечи нема у њима, њима ће бити тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Зато овако вели Господ Господ над војскама: кад тако говорите, ево ја ћу учинити да ријечи моје у устима твојим буду као огањ, а овај народ дрва, те ће их спалити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Гле, ја ћу довести на вас народ из далека, доме Израиљев, вели Господ, народ јак, народ стар, народ којем језика нећеш знати нити ћеш разумјети што говори;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Којему је тул као гроб отворен, сви су јаки.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'И појешће љетину твоју и хљеб твој, што синови твоји и кћери твоје шћаху јести, појешће овце твоје и говеда твоја, појешће винову лозу твоју и смокве твоје, и мачем ће затрти тврде градове твоје у које се уздаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Али ни тада вели Господ, нећу вас сасвијем затрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Јер кад речете: зашто нам чини Господ Бог наш све ово? тада им реци: како остависте мене и служисте туђим боговима у земљи својој, тако ћете служити туђинцима у земљи која није ваша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Јавите ово у дому Јаковљеву, и огласите у Јуди, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Чујте ово, луди и безумни народе, који имате очи а не видите, који имате уши а не чујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Мене ли се нећете бојати? вели Господ; од мене ли нећете дрктати? који поставих пијесак мору за међу вјечном наредбом, и неће пријећи преко ње; ако му и устају вали, неће надјачати, ако и буче, неће је пријећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Али је у народа овога срце упорно и непокорно; отступише и отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Нити рекоше у срцу свом: бојмо се Господа Бога својега, који нам даје дажд рани и позни на вријеме, и чува нам недјеље одређене за жетву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Безакоња ваша одвраћају то, и гријеси ваши одбијају добро од вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Јер се налазе у народу мом безбожници, који вребају као птичари кад се притаје, мећу замке да хватају људе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Као крлетка пуна птица тако су куће њихове пуне пријеваре; зато посташе велики и обогатише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Угојише се, сјају се, мимоилазе зло, не чине правде ни сирочету, и опет им је добро, и не дају правице убогима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Зато ли нећу походити? вели Господ, и душа моја неће ли се осветити таквом народу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Чудо и страхота бива у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Пророци пророкују лажно, и свештеници господују преко њих, и народу је мојему то мило. А шта ћете радити на пошљедак?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Скупите се из Јерусалима, синови Венијаминови, и у Текуји затрубите у трубу, и подигните знак огњен над Вет-Акеремом, јер се види зло од сјевера и велика погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Учиних кћер Сионску да је као лијепа и њежна дјевојка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'К њој ће доћи пастири са стадима својим, разапеће око ње шаторе, сваки ће опасти своје мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Спремите рат на њу, устаните да ударимо у подне. Тешко нама, јер дан наже, и сјенке вечерње одуљаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Устаните да ударимо обноћ и развалимо дворове њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Јер овако говори Господ над војскама: сијеците дрва, и начините опкопе према Јерусалиму; то је град који треба походити; колики је год, насиље је у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Као што извор точи воду своју, тако он точи злоћу своју; насиље и отимање чује се у њему, преда мном су једнако болови и ране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Поправи се, Јерусалиме, да се не отргне душа моја од тебе, да те не обратим у пустињу, у земљу гдје се не живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Овако говори Господ над војскама: остатак ће се Израиљев пабирчити као винова лоза. Турај руку своју као берач у котарице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Коме ћу говорити и свједочити да чују? Гле, ухо им је необрезано, те не могу чути; гле, ријеч је Господња њима потсмијех, није им мила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Зато сам пун гњева Господњега; изнемогох устежући га; просућу га на дјецу по улицама и на сабране младиће, и човјек и жена ухватиће се, и стари и временити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'И куће ће њихове припасти другима, и њиве и жене, кад махнем руком својом на становнике ове земље, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Јер од малога до великога сви се дадоше на лакомство, и пророк и свештеник, сви су варалице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'И лијече ране кћери народа мојега овлаш, говорећи: мир, мир; а мира нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Еда ли се постидјеше што чинише гад? Нити се постидјеше нити знају за стид; зато ће попадати међу онима који падају; кад их походим, попадаће, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Господ рече овако: станите на путовима и погледајте, и питајте за старе стазе, који је пут добра, па идите по њему, и наћи ћете мир души својој. А они рекоше: нећемо да идемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'И поставих вам стражаре говорећи: пазите на глас трубни. А они рекоше: нећемо да пазимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Зато чујте, народи, и познај, зборе, што је међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Чуј, земљо! ево ја ћу пустити зло на овај народ, плод мисли њиховијех, јер не пазе на моје ријечи, и одбацише закон мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Што ће ми тамјан, што долази из Саве, и добри цимет из далеке земље? Жртве ваше паљенице нијесу ми угодне, нити су ми приноси ваши мили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Зато овако говори Господ: ево ја ћу метнути овом народу сметње, о које ће се спотаћи и оцеви и синови, сусјед и пријатељ му, и погинуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Овако говори Господ: ево народ ће доћи из земље сјеверне, и велик ће народ устати од крајева земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Лук и копље носиће, жестоки ће бити и немилостиви, глас ће им бучати као море, и јахаће на коњма, спремни као јунаци да се бију с тобом, кћери Сионска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Кад чујемо глас о њему, клонуће нам руке, туга ће нас спопасти и болови као породиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Не излазите у поље, и путем не идите, јер је мач непријатељев и страх унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Кћери народа мојега, припаши костријет и ваљај се у пепелу, жали као за сином јединцем и ридај горко, јер ће брзо доћи на нас затирач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Поставих те да си стражара и град народу мом да дознајеш и извиђаш пут њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Сви су одметници над одметницима, иду те опадају, мјед су и гвожђе, сви су покварени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Изгорјеше мјехови, огањ сажеже олово, узалуд се претапа, јер се зла не могу одлучити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Они ће се звати сребро лажно, јер их Господ одбаци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Ријеч која дође Јеремији од Господа говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Стани на вратима дома Господњега, и огласи ондје ову ријеч, и реци: чујте ријеч Господњу, сви Јудејци, који улазите на ова врата да се поклоните Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Овако говори Господ над војскама, Бог Израиљев: поправите своје путове и дјела своја, па ћу учинити да станујете на овом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Не уздајте се у лажне ријечи говорећи: црква Господња, црква Господња, црква Господња ово је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Него доиста поправите своје путове и дјела своја, и судите право између човјека и ближњега његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Иностранцу, сироти и удовици не чините криво, и крви праве не прољевајте на овом мјесту, и не идите за другим боговима на своје зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Тада ћу учинити да станујете од вијека до вијека на овом мјесту, у земљи коју сам дао оцима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Ето, ви се уздате у ријечи лажне, које не помажу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Крадете, убијате и чините прељубу, кунете се криво, и кадите Валима, и идете за другим боговима, којих не знате;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Па онда доходите и стајете преда мном у овом дому, који се зове мојим именом, и говорите: избависмо се, да чините све ове гадове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Је ли овај дом, који се зове мојим именом, у вашим очима пећина хајдучка? Гле, и ја видим, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Него идите сада на моје мјесто, које је било у Силому, гдје намјестих име своје испочетка, и видите што сам му учинио за злоћу народа својега Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Зато сада, што чините сва она дјела, вели Господ, и што вам говорим зарана једнако, а ви не слушате, и кад вас зовем, а ви се не одзивате,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'Зато ћу учинити тому дому, који се зове мојим именом, у који се ви уздате, и овому мјесту, које дадох вама и оцима вашим, као што сам учинио Силому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'И одбацићу вас од лица својега, као што сам одбацио сву браћу вашу, све сјеме Јефремово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Ти се дакле не моли за тај народ, и не подижи вике ни молбе за њих, и не говори ми за њих; јер те нећу услишити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Зар не видиш шта чине по градовима Јудинијем и по улицама Јерусалимским?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Синови купе дрва, а оцеви ложе огањ, и жене мијесе тијесто, да пеку колаче царици небеској, и да љевају наљеве другим боговима, да би мене дражили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Мене ли драже? говори Господ; еда ли не себе, на срамоту лицу својему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Зато овако говори Господ Господ: гле, гњев мој и јарост моја излиће се на ово мјесто, на људе и на стоку и на дрвета пољска и на род земаљски, и распалиће се, и неће се угасити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Овако вели Господ над војскама Бог Израиљев: жртве своје паљенице саставите са приносима својим, и једите месо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Јер не говорих оцима вашим, нити им заповиједих, кад их изведох из земље Мисирске, за жртве паљенице ни за приносе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Него им ово заповједих говорећи: слушајте глас мој и бићу вам Бог и ви ћете ми бити народ, и идите свијем путовима које вам заповиједих, да би вам добро било.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Али не послушаше, нити уха својега пригнуше, него идоше по савјетима и мислима злога срца својега, и отидоше натраг а не напријед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Откад изиђоше оци ваши из земље Мисириске до данас, слах к вама све слуге своје пророке сваки дан зарана и без престанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Али не послушаше ме, нити уха својега пригнуше, него бијаху тврдоврати и чинише горе него оци њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Говорићеш им све ове ријечи, али те неће послушати; и зваћеш их, али ти се неће одазвати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Зато им реци: ово је народ који не слуша гласа Господа Бога својега, нити прима науке; пропаде вјера и неста је из уста њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Остризи косу своју и баци је, и заридај иза гласа на високим мјестима, јер одбаци Господ и остави род, на који се разгњеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Јер синови Јудини учинише што је зло преда мном, говори Господ, метнуше гадове своје у дом који се зове мојим именом, да би га оскврнили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'И саградише висине Тофету, који је у долини сина Еномова, да сажижу синове своје и кћери своје огњем, што нијесам заповиједио нити ми је дошло на ум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Зато ево, иду дани, вели Господ, кад се више неће звати Тофет ни долина сина Еномова, него долина крвна, и погребаваће се у Тофету, јер неће бити мјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'И мртва ће тјелеса народа овога бити храна птицама небеским и звијерју земаљском, и неће бити никога да их плаши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'И учинићу, те ће из градова Јудинијех и с улица Јерусалимских нестати гласа радосна и гласа весела, гласа женикова и гласа невјестина; јер ће земља опустјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'У то вријеме, говори Господ, извадиће се из гробова кости царева Јудинијех и кости кнезова његовијех и кости свештеничке и кости пророчке, и кости становника Јерусалимских;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'И разметнуће се према сунцу и мјесецу и свој војсци небеској, које љубише и којима служише и за којима идоше и које тражише и којима се клањаше; неће се покупити ни погрепсти, него ће бити гној по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'И вољеће смрт него живот сав остатак што их остане од овога рода злога, што их остане по свијем мјестима куда их разденем, говори Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Још им реци: овако вели Господ: ко падне, не устаје ли? ко зађе, не враћа ли се?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Зашто је зашао тај народ Јерусалимски засвагда? Држе се пријеваре, неће да се обрате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Пазио сам и слушао, не говоре право, нема никога да се каје за зло своје, да рече: што учиних? Сваки је окренуо својим трком, као коњ кад нагне у бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'И рода под небом зна своје вријеме, грлица и ждрао и ласта пазе на вријеме кад долазе; а народ мој не зна суда Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Како говорите: мудри смо, и закон је Господњи у нас? Доиста, гле, лаж учини лажљива писаљка књижевничка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Мудраци се осрамотише, уплашише се и ухватише се; ето, одбацише ријеч Господњу, па кака им је мудрост?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Зато ћу дати жене њихове другима, њиве њихове онима који ће их наслиједити, јер од малога до великога сви се дадоше на лакомство, и пророци и свештеници, сви су варалице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Јер лијече ране кћери народа мојега овлаш говорећи: мир, мир; а мира нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Еда ли се постидјеше што чинише гад? Нити се постидјеше нити знају за стид; зато ће попадати међу онима који падају; кад их походим, попадаће, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Сасвијем ћу их истријебити, говори Господ, нема грозда на лози, ни смокве на дрвету, и лишће је опало; и што сам им дао узеће им се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Што стојимо? скупите се и уђимо у тврде градове, и ондје мучимо; јер нас је Господ Бог наш умучкао напојивши нас жучи, јер згријешисмо Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Чекасмо мир, али нема добра; и вријеме да оздравимо, а гле, страх.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Од Дана чу се фркање коња његовијех, од рзања пастуха његовијех сва се земља затресе, дођоше и поједоше земљу и све што бјеше у њој, градове и који живљаху у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Јер, ево, ја ћу пустити на вас змије, аспиде, од којих нема бајања, те ће вас уједати, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Окријепио бих се у жалости, али је срце у мени изнемогло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Ето вике кћери народа мојега из даљне земље: зар Господ није у Сиону? цар његов зар није у њему? Зашто ме разгњевише својим ликовима резанијем, туђим таштинама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Жетва је прошла, љето минуло, а ми се не избависмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Сатрвен сам што је кћи народа мојега сатрвена, у жалости сам, чудо освоји ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Нема ли балсама у Галаду? нема ли ондје љекара? зашто се дакле не исцијели кћи народа мојега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'О, да би глава моја била вода, а очи моје извори сузни! да плачем дању и ноћу за побијенима кћери народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'О, да ми је у пустињи станак путнички! да оставим народ свој и да отидем од њих, јер су сви прељубочинци, збор невјернички;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'И запињу језик свој као лук да лажу, и осилише на земљи, али не за истину, него иду из зла у зло, нити знају за ме, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Чувајте се сваки пријатеља својега и ниједноме брату не вјерујте; јер сваки брат ради да поткине другога, и сваки пријатељ иде те опада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'И сваки вара пријатеља својега и не говори истине, уче језик свој да говори лаж, муче се да чине зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Стан ти је усред пријеваре; ради пријеваре неће да знају за ме, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Зато овако говори Господ над војскама: гле, претопићу их, и окушаћу их; јер што бих чинио ради кћери народа својега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Језик им је стријела смртна, говори пријевару; устима говоре о миру с пријатељем својим, а у срцу намјештају засједу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Зато ли их нећу походити? говори Господ; душа моја неће ли се осветити таком народу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'За овијем горама ударићу у плач и у ридање, и за торовима у пустињи у нарицање; јер изгорјеше да нико не пролази нити се чује глас од стада, и птице небеске и стока побјегоше и отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'И обратићу Јерусалим у гомилу, у стан змајевски; и градове Јудине обратићу у пустош, да неће нико онуда живјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Ко је мудар да би разумио? и кому говорише уста Господња, да би објавио зашто земља пропаде и изгорје као пустиња да нико не пролази?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Јер Господ рече: што оставише закон мој, који метнух пред њих, и не слушаше гласа мојега и не ходише за њим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Него ходише за мислима срца својега и за Валима, чему их научише оци њихови,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Зато овако вели Господ над војскама, Бог Израиљев: ево ја ћу нахранити тај народ пеленом и напојићу их жучи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'И расијаћу их међу народе, којих не познаваше ни они ни оци њихови; и пуштаћу за њима мач докле их не истријебим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Овако вели Господ над војскама: гледајте и зовите нарикаче нека дођу, и пошљите по вјеште нека дођу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'И нека брже наричу за нама, да се роне сузе од очију наших, и од вјеђа наших да тече вода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Јер се гласно ридање чу од Сиона: како пропадосмо! посрамисмо се врло, јер се растављамо са земљом, јер обарају станове наше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Зато, жене, чујте ријеч Господњу и нека прими ухо ваше ријеч уста његовијех, и учите кћери своје ридати и једна другу нарицати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Јер се попе смрт на прозоре наше и уђе у дворове наше да истријеби дјецу с улица и младиће с путова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Реци: овако говори Господ: и мртва ће тјелеса људска лежати као гној по њиви и као руковети за жетеоцем, којих нико не купи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Овако вели Господ: мудри да се не хвали мудрошћу својом, ни јаки да се не хвали снагом својом, ни богати да се не хвали богатством својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Него ко се хвали, нека се хвали тијем што разумије и познаје мене да сам ја Господ који чиним милост и суд и правду на земљи, јер ми је то мило, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Ето, иду дани, вели Господ, кад ћу походити све, обрезане и необрезане,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Мисирце и Јудејце и Едомце и синове Амонове и Моавце и све који се с краја стригу, који живе у пустињи; јер су сви ти народи необрезани, и сав је дом Израиљев необрезана срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Слушајте ријеч коју вам говори Господ, доме Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Овако вели Господ: не учите се путу којим иду народи, и од знака небеских не плашите се, јер се од њих плаше народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Јер су уредбе у народа таштина, јер сијеку дрво у шуми, дјело руку умјетничких сјекиром;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Сребром и златом украшују га, клинима и чекићима утврђују га да се не помиче;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Стоје право као палме, не говоре; треба их носити, јер не могу ићи; не бој их се, јер не могу зла учинити, а не могу ни добра учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Нико није као ти, Господе; велик си и велико је име твоје у сили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Ко се не би тебе бојао, царе над народима! јер теби то припада; јер међу свијем мудрацима у народа и у свијем царствима њиховијем нема такога какав си ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Него су сви луди и безумни, дрво је наука о таштини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Сребро ковано доноси се из Тарсиса и злато из Уфаза, дјело умјетничко и руку златарских, одијело им је од порфире и скерлета, све је дјело умјетничко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'А Господ је прави Бог, Бог живи и цар вјечни, од његове срдње тресе се земља, и гњева његова не могу поднијети народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Овако им реците: богова, који нијесу начинили неба ни земље, нестаће са земље и испод неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Он је начинио земљу силом својом, утврдио васиљену мудрошћу својом, и разумом својим разастро небеса;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Он кад пусти глас свој, буче воде на небесима, подиже пару с крајева земаљских, пушта муње с даждем, и изводи вјетар из стаја његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Сваки човјек поста безуман од знања, сваки се златар осрамоти ликом резанијем, јер су лаж ливени ликови његови, и нема духа у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Таштина су, дјело пријеварно; кад их походим, погинуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Није таки дио Јаковљев, јер је творац свему, и Израиљ му је нашљедство, име му је Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Покупи из земље трг свој ти, која сједиш у граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Јер овако вели Господ: гле, ја ћу избацити као праћом становнике ове земље, и притијеснићу их да осјете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Тешко мени од муке моје, рећи ће; љута је рана моја; а ја рекох: то је бол, треба да га подносим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Мој је шатор опустошен и сва ужа моја покидана, синови моји отидоше од мене и нема их, нема више никога да разапне шатор мој и дигне завјесе моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Јер пастири посташе безумни и Господа не тражише; зато не бише срећни, и све се стадо њихово распрша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Гле, иде глас и врева велика из сјеверне земље да обрати градове Јудине у пустош, у стан змајевски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Знам, Господе, да пут човјечји није у његовој власти нити је човјеку који ходи у власти да управља корацима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Карај ме, Господе, али с мјером, не у гњеву свом, да ме не би затро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Излиј гњев свој на народе који те не познају, и на племена која не призивљу имена твојега, јер прождријеше Јакова, прождријеше га да га нема, и насеље његово опустише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Ријеч која дође Јеремији од Господа говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Слушајте ријечи овога завјета, и казујте људима Јудинијем и становницима Јерусалимским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'И реци им: овако вели Господ Бог Израиљев: проклет да је ко не послуша ријечи овога завјета,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Који заповједих оцима вашим кад их изведох из земље Мисирске из пећи гвоздене говорећи: слушајте глас мој и творите ово све како вам заповиједам, па ћете ми бити народ и ја ћу вам бити Бог,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Да бих испунио заклетву којом се заклех оцима вашим да ћу им дати земљу у којој тече млијеко и мед, како се види данас. А ја одговорих и рекох: амин, Господе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Потом рече ми Господ: казуј све ове ријечи по градовима Јудинијем и по улицама Јерусалимским говорећи: слушајте ријечи овога завјета, и извршујте их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Јер тврдо засвједочавах оцима вашим од кад их изведох из земље Мисирске до данас, зарана једнако говорећи: слушајте глас мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Али не послушаше и не пригнуше уха својега, него ходише сваки за мислима злога срца својега; зато пустих на њих све ријечи овога завјета, који заповједих да врше а они не вршише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Тада ми рече Господ: буна је међу људима Јудинијем и становницима Јерусалимским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Вратили су се на безакоња старијех својих, који не хтјеше слушати мојих ријечи, и иду за другим боговима, те им служе; дом Израиљев и дом Јудин покварише завјет мој, који учиних с оцима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Зато овако вели Господ: ево, ја ћу пустити на њих зло, из којега неће моћи изаћи, и вапиће к мени, али их нећу услишити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Тада ће градови Јудини и становници Јерусалимски ићи и вапити к боговима којима каде, али им неће помоћи у невољи њиховој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Јер имаш богова, Јудо, колико градова, и колико има улица у Јерусалиму, толико подигосте олтара срамотнијех, олтара, да кадите Валу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Ти се дакле не моли за тај народ, и не подижи вике ни молбе за њих, јер их нећу услишити кад завапију к мени у невољи својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Што ће мили мој у дому мом, кад чини грдило с многима, и свето месо отиде од тебе, и веселиш се кад зло чиниш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Господ те назва маслином зеленом, лијепом ради доброга рода; али с хуком великога вјетра распали огањ око ње, и гране јој се поломише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Јер Господ над војскама, који те је посадио, изрече зло по те, за злоћу дома Израиљева и дома Јудина, коју чинише међу собом да би ме разгњевили кадећи Валу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Господ ми објави, те знам; ти ми показа дјела њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'А ја бијах као јагње и теле које се води на клање, јер не знадијах да се договарају на ме: оборимо дрво с родом његовијем, и истријебимо га из земље живијех, да му се име не спомиње више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Али, Господе над војскама, судијо праведни, који испитујеш бубреге и срце, дај да видим освету твоју на њима, јер теби казах парбу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Зато овако вели Господ за Анатоћане, који траже душу твоју говорећи: не пророкуј у име Господње, да не погинеш од наших руку;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Зато овако вели Господ над војскама: ево, ја ћу их походити; младићи ће њихови изгинути од мача, синови њихови и кћери њихове изгинуће од глади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'И неће бити од њих остатка; јер ћу пустити зло на Анатоћане кад их походим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Праведан си, Господе, ако бих се правдао с тобом; али ћу проговорити о судовима твојим. Зашто је пут безбожнички срећан? зашто живе у миру сви који чине невјеру?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Ти их посади, и они се укоријенише, расту и род рађају; ти си им близу уста али далеко од бубрега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Али, Господе, ти ме познајеш, разгледаш ме и окушао си срце моје како је према теби; одвуци их као овце на клање, и приправи их за дан кад ће се убити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Докле ће тужити земља, и трава свега поља сахнути са злоће онијех који живе у њој? неста све стоке и птица, јер говоре: не види краја нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Кад си трчао с пјешацима па те уморише, како ћеш се утркивати с коњма? и кад ти је тако у земљи мирној, у коју се уздаш, шта ћеш чинити кад устане Јордан?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Јер и браћа твоја и дом оца твојега, и они те изневјерише, и они вичу за тобом иза гласа. Не вјеруј им, ако би ти и пријатељски говорили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Оставих дом свој, напустих нашљедство своје; што бијаше мило души мојој, дадох га у руке непријатељима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Нашљедство моје поста ми као лав у шуми, пушта глас свој на мене, зато ми омрзну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Нашљедство моје поста ми птица грабљива; птице, слетите се на њу, скупите се сви звјерови пољски, ходите да једете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Пастири многи поквариће мој виноград, потлачиће дио мој, мили дио мој обратиће у голу пустош.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Обратиће га у пустош, опустошен плакаће преда мном; сва ће та земља опустјети, јер нико не узима на ум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'На сва висока мјеста по пустињи доћи ће затирачи; јер ће мач Господњи прождирати од једнога краја земље до другога, неће бити мира ниједном тијелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Сијаће пшеницу, а трње ће жети; мучиће се, а користи неће имати, и стидјеће се љетине своје, са жестокога гњева Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Овако говори Господ за све зле сусједе моје, који дирају нашљедство што дадох народу својему Израиљу: ево, ја ћу их почупати из земље њихове, и дом Јудин ишчупаћу исред њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'А кад их ишчупам, опет ћу се смиловати на њих, и довешћу опет свакога њих на нашљедство његово и свакога у земљу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'И ако добро науче путове народа мојега, да се заклињу мојим именом: тако да је жив Господ! као што су они учили мој народ да се куне Валом, тада ће се сазидати усред народа мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Ако ли не послушају, тада ћу ишчупати са свијем таки народ и затрти, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Овако ми рече Господ: иди и купи себи појас ланен и опаши се њим, а не мећи га у воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Тако купих појас по ријечи Господњој, и опасах се њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Потом дође ми опет ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Узми тај појас што си купио, што је око тебе, па се дигни и иди на Ефрат, и сакриј га ондје у каку расјелину камену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'И отидох и сакрих га код Ефрата, како ми заповједи Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'А послије много времена рече ми Господ: устани и иди на Ефрат, и узми појас који ти заповједих да сакријеш ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'И отидох на Ефрат и откопах и узех појас с мјеста гдје га бијах сакрио; а гле, појас отрухнуо, и не бјеше ни за што.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Тада ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Овако вели Господ: тако ћу учинити да отрухне понос Јудин и велики понос Јерусалимски,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Тога народа неваљалога, што неће да слуша мојих ријечи, што ходи по мислима срца својега и иде за другим боговима служећи им и клањајући им се; и биће као тај појас, који није ни за што.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Јер како се појас припоји око човјека, тако бијах припојио око себе сав дом Израиљев и сав дом Јудин, вели Господ, да би били мој народ на славу и хвалу и дику; али не послушаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Зато им реци ову ријеч: овако вели Господ Бог Израиљев: сви се мјехови пуне вина. А они ће рећи: зар не знамо да се сви мјехови пуне вина?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Тада им реци: овако вели Господ: ево, ја ћу напунити пјаности све становнике ове земље и цареве, који сједе мјесто Давида на пријестолу његову, и свештенике и пророке и све становнике Јерусалимске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'И разбићу их једнога о другога, и оцеве и синове, вели Господ; нећу пожалити ни поштедјети нити се смиловати, да их не потрем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Слушајте и чујте, немојте се поносити, јер Господ говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Дајте славу Господу Богу својему док није спустио мрак, докле се нијесу спотакле ноге ваше по горама мрачнијем, да чекате свјетлост а он је обрати у сјен смртни и претвори у таму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Ако ли ово не послушате, душа ће моја плакати тајно ради охолости ваше и ронити сузе, сузе ће тећи из ока мојега, јер ће се заробити стадо Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Реци цару и царици: доље сједите, јер ће се славни вијенац ваш скинути с ваше главе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Градови јужни затвориће се и неће бити никога да их отвори, одвешће се Јуда у ропство, сасвијем ће се одвести у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Подигните очи своје и видите оне што иду од сјевера. Гдје је стадо што ти је предано, стадо славе твоје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Шта ћеш рећи кад те походи? Јер си их ти научио да буду кнезови над тобом. Не ће ли те спопасти болови као жену кад се порађа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Ако ли речеш у срцу свом: зашто ме то задеси? за мноштво безакоња твојега узгрнуће се скути твоји и обућа ти се скинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Може ли Етиопљанин промијенити кожу своју или рис шаре своје? можете ли ви чинити добро научивши се чинити зло?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Зато ћу их разметнути као што размеће пљеву вјетар из пустиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'То је дио твој и оброк твој од мене, говори Господ, зато што си ме заборавио и поуздао се у лаж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Зато ћу ти ја узгрнути скуте на лице да се види срамота твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Прељубе твоје, рзање твоје, срамотна курварства твоја по хумовима, по пољима, гадове твоје видио сам; тешко теби, Јерусалиме! зар се нећеш очистити? докле још?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Ријеч Господња која дође Јеремији о суши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Јуда тужи, и врата су му жалосна; леже на земљи у црно завити; вика из Јерусалима подиже се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Највећи између њих шаљу најмање на воду; дошавши на студенце не налазе воде, враћају се с празнијем судовима својим, стиде се и сраме се и покривају главу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Земља је испуцала, јер не бјеше дажда на земљи; зато се тежаци стиде и покривају главу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'И кошута у пољу оставља младе своје, јер нема траве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'И дивљи магарци стојећи на висовима вуку у се вјетар као змајеви, очи им ишчиљеше, јер нема траве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Кад безакоња наша свједоче на нас, Господе, учини ради имена својега; јер је много одмета наших, теби сагријешисмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Наде Израиљев! спаситељу његов у невољи! зашто си као туђин у овој земљи и као путник који се уврати да преноћи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Зашто си као уморан човјек, као јунак, који не може избавити? Та, ти си усред нас, Господе, и име је твоје призвано на нас; немој нас оставити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Овако говори Господ за народ овај: мило им је да се скитају, не устављају ногу својих, зато нијесу мили Господу; сада ће се опоменути безакоња њихова и походиће гријехе њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Потом рече ми Господ: не моли се за тај народ да би му било добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Ако ће и постити, нећу услишити вике њихове; и ако ће принијети жртве паљенице и дар, неће ми то угодити, него мачем и глађу и помором поморићу их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Тада рекох: ох, Господе Господе, ево, пророци им говоре: нећете видјети мача, и неће бити глади у вас, него ћу вам дати мир поуздан на овом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'А Господ ми рече: лаж пророкују ти пророци у моје име, нијесам их послао, нити сам им заповједио, нити сам им говорио; лажне утваре и гатање и ништавило и пријевару срца својега они вам пророкују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Зато овако вели Господ за пророке који пророкују у моје име а ја их нијесам послао, и говоре: неће бити мача ни глади у овој земљи: од мача и глади изгинуће ти пророци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'А народ овај којему они пророкују биће поваљан по улицама Јерусалимским од глади и мача, и неће бити никога да их погребе, њих, жене њихове и синове њихове и кћери њихове; тако ћу излити на њих злоћу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Реци им дакле ову ријеч: нека очи моје лију сузе дању и ноћу и нека не престају, јер дјевојка кћи мојега народа сатр се веома, од ударца прељута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Ако изидем у поље, ето побијенијех мачем; ако уђем у град, ето изнемоглијех од глади; јер и пророк и свештеник отидоше у земљу које не знају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Еда ли си сасвијем одбацио Јуду? еда ли је омрзао души твојој Сион? Зашто си нас ударио тако да нам нема лијека? Чекасмо мир али нема добра; и вријеме да оздравимо, а гле, страх.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Признајемо, Господе, злоћу своју, безакоње отаца својих, згријешили смо ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Немој нас одврћи ради имена својега; немој наружити пријестола славе своје, опомени се завјета својега с нама, немој га укинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Има ли међу таштинама у народа који да даје дажд? или небеса дају ли ситан дажд? Нијеси ли ти то, Господе Боже наш? Зато тебе чекамо, јер ти чиниш све то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'И рече ми Господ: да стане Мојсије и Самуило преда ме, не би се душа моја обратила к томе народу; отјерај их испред мене, и нека одлазе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'И ако ти реку: куда ћемо ићи? тада им реци: овако вели Господ: ко је за смрт, на смрт; ко је за мач, под мач; ко за глад, на глад; ко за ропство, у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'И пустићу на њих четворо, говори Господ: мач, да их убија, и псе, да их развлаче, и птице небеске и звијери земаљске, да их једу и истријебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'И даћу их да се потуцају по свијем царствима земаљским ради Манасије сина Језекијина цара Јудина за оно што је учинио у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Јер ко би се смиловао на тебе, Јерусалиме? ко ли би те пожалио? ко ли би дошао да запита како ти је?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Ти си ме оставио, говори Господ, отишао си натраг; зато ћу махнути руком својом на те и погубићу те; досади ми жалити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Зато ћу их извијати вијачом на вратима земаљским, учинићу их сиротима, потрћу народ свој, јер се не враћају с путова својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Више ће ми бити удовица његовијех него пијеска морскога, довешћу им на мајке момачке затираче у подне, и пустићу изненада на њих сметњу и страхоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Изнемоћи ће која је родила седморо и испустиће душу, сунце ће јој заћи још за дана, срамиће се и стидјеће се, а остатак ћу њихов дати под мач пред непријатељима њиховијем, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Тешко мени, мајко моја, што си ме родила да се са мном препире и да се са мном свађа сва земља; не давах у зајам нити ми даваше у зајам, и опет ме сви проклињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Господ рече: доиста, остатку ће твојему бити добро, и бранићу те од непријатеља, кад будеш у невољи и у тјескоби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Еда ли ће гвожђе сломити гвожђе сјеверно и мјед?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Имање твоје и благо твоје даћу да се разграби без цијене по свијем међама твојим, и то за све гријехе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'И одвешћу те с непријатељима твојим у земљу које не познајеш, јер се распалио огањ од гњева мојега, и горјеће над вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Ти знаш, Господе, опомени ме се и походи ме и освети ме од онијех који ме гоне; немој ме зграбити докле се устежеш од гњева; знај да подносим руг тебе ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Кад се нађоше ријечи твоје, поједох их, и ријеч твоја би ми радост и весеље срцу мојему, јер је име твоје призвано на ме, Господе Боже над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Не сједим у вијећу потсмјевачком нити се с њима веселим; сједим сам ради руке твоје, јер си ме напунио срдње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Зашто бол мој једнако траје? и зашто је рана моја смртна, те неће да се исцијели? Хоћеш ли ми бити као варалица, као вода непостојана?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Зато овако вели Господ: ако се обратиш, ја ћу те опет поставити да стојиш преда мном, ако одвојиш што је драгоцјено од рђавога, бићеш као уста моја; они нека се обрате к теби, а ти се не обраћај к њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'И учинићу да будеш томе народу као јак зид мједен, и удараће на те, али те неће надвладати; јер сам ја с тобом да те чувам и избављам, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'И избавићу те из руку злијех људи, и искупићу те из руку насилничких.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Потом дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Немој се женити, и да немаш синова ни кћери на том мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Јер овако говори Господ за синове и кћери што се роде на том мјесту и за матере њихове које их роде, и за оце њихове који их роде у тој земљи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Љутом ће смрћу помријети, неће бити оплакани нити ће се погрепсти, биће гној по земљи, и од мача и од глади изгинуће, и мртва ће тјелеса њихова бити храна птицама небеским и звијерима земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Јер овако говори Господ: не улази у кућу у којој је жалост, и не иди да плачеш нити их жали; јер сам узео мир свој од тога народа, говори Господ, милост и жаљење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Помријеће мали и велики у овој земљи, неће бити погребени нити ће се оплакати, нити ће се ко резати ни главе стрићи за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Неће им се дати хљеба у жалости да се потјеше за мртвијем, нити ће их напојити из чаше ради утјехе за оцем или за матером.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Тако не улази у кућу у којој је жалост да сједеш с њима да једеш и пијеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Јер овако вели Господ над војскама Бог Израиљев: ево, ја ћу учинити да на овом мјесту пред вашим очима и за ваших дана не буде гласа радосна ни гласа весела, гласа женикова ни гласа невјестина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'А кад кажеш томе народу све ове ријечи, ако ти реку: зашто изрече Господ све то велико зло на нас? и како је безакоње наше или каки је гријех наш, којим згријешисмо Господу Богу својему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Тада им реци: јер оци ваши оставише мене, говори Господ, и идоше за другим боговима и служише им и клањаше им се, а мене оставише и закона мојега не држаше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'А ви још горе чините него оци ваши, јер ето идете сваки по мисли срца својега злога не слушајући мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Зато ћу вас избацити из ове земље у земљу које не познасте ни ви ни оци ваши, и ондје ћете служити другим боговима дан и ноћ докле вам не учиним милост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Зато, ево, иду дани, говори Господ, кад се неће више говорити: тако да је жив Господ који је извео синове Израиљеве из земље Мисирске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Него: тако да је жив Господ који је извео синове Израиљеве из земље сјеверне и из свијех земаља у које их бјеше разагнао! Јер ћу их опет довести у земљу њихову коју сам дао оцима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Гле, ја ћу послати многе рибаре, говори Господ да их лове, и послије ћу послати многе ловце да их лове по свакој гори и по сваком хуму и по расјелинама каменијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Јер очи моје пазе на све путове њихове, нијесу сакривени од мене, нити је безакоње њихово заклоњено од мојих очију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'И платићу им прво двојином за безакоње њихово и за гријех њихов, што оскврнише земљу моју стрвима гадова својих, и нашљедство моје напунише гнусобама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Господе, крјепости моја и граде мој и уточиште моје у невољи, к теби ће доћи народи од крајева земаљских, и рећи ће: доиста оци наши имаше лаж, и таштину и што ни мало не помаже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Еда ли ће човјек начинити себи богове, који ипак нијесу богови?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Зато, ево, ја ћу их научити сада, показаћу им руку своју и силу своју, да познаду да ми је име Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Гријех је Јудин записан гвозденом писаљком и врхом од дијаманта, урезан је на плочи срца њихова и на роговима олтара ваших,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Да се синови њихови сјећају олтара њиховијех и лугова њиховијех под зеленијем дрветима, на високим хумовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Горо с пољем, даћу имање твоје, све благо твоје даћу да се разграби, висине твоје, за гријех по свијем међама твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'И ти ћеш и који су с тобом оставити нашљедство своје које сам ти дао, и учинићу да служиш непријатељима својим у земљи које не познајеш; јер сте распалили огањ гњева мојега који ће горјети довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Овако вели Господ: да је проклет човјек који се узда у човјека и који ставља тијело себи за мишицу, а од Господа отступа срце његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Јер ће бити као вријес у пустињи, који не осјећа кад дође добро, него стоји у пустињи, на сухим мјестима у земљи сланој и у којој се не живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Благо човјеку који се узда у Господа и коме је Господ узданица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Јер ће бити као дрво усађено крај воде и које низ поток пушта жиле своје, које не осјећа кад дође припека, него му се лист зелени, и сушне године не брине се и не престаје рађати род.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Срце је пријеварно више свега и опако; ко ће га познати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Ја Господ испитујем срца и искушавам бубреге, да бих дао свакоме према путовима његовијем и по плоду дјела његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Као што јаребица лежи на јајима али не излеже, тако ко сабира богатство али с неправдом, у половини дана својих оставиће га и најпослије ће бити луд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Мјесто је светиње наше пријесто славе, високо мјесто од почетка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Наде Израиљев, Господе! сви који те остављају нека се посраме; који отступају од мене, нека се запишу на земљи, јер оставише извор воде живе, Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Исцијели ме, Господе, и бићу исцијељен; избави ме, и бићу избављен, јер си ти хвала моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Гле, они ми говоре: гдје је ријеч Господња? Нека дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'А ја се не затезах ићи за тобом као пастир, и дана жалоснога не жељех, ти знаш; што је год изашло из уста мојих, пред тобом је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Не буди ми страх, ти си уточиште моје у злу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Нека се посраме који ме гоне, а ја не; нека се они уплаше, а ја не; пусти на њих зли дан, и двоструким поломом поломи их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Овако ми рече Господ: иди, и стани на врата синова народнијех, на која улазе цареви Јудини и на која излазе, и на свака врата Јерусалимска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'И реци им: чујте ријеч Господњу, цареви Јудини и сви Јудејци и сви Јерусалимљани, који улазите на ова врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Овако вели Господ: чувајте се да не носите бремена у суботу и не уносите на врата Јерусалимска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'И не износите бремена из кућа својих у суботу, и никакога посла не радите, него светите суботу, као што сам заповједио оцима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Али не послушаше нити пригнуше уха својега, него отврднуше вратом својим да не послушају и не приме науке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Ако ме послушате говори Господ, да не носите бремена на врата овога града у суботу, него светите суботу не радећи у њу никакога посла,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'Тада ће улазити на врата града овога цареви и кнезови, који сједе на пријестолу Давидову, на колима и на коњма, они и кнезови њихови, Јудејци и Јерусалимљани, и стајаће овај град довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'И долазиће из градова Јудинијех и из околине Јерусалимске, и из земље Венијаминове, и из равнице и из гора и с југа, и доносиће жртве паљенице и приносе с даром и кадом, и жртве захвалне доносиће у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Ако ли ме не послушате да светите суботу и не носите бремена улазећи на врата Јерусалимска у суботу, онда ћу распалити огањ на вратима његовијем, који ће упалити дворове Јерусалимске и неће се угасити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Ријеч која дође Јеремији од Господа говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Устани, и сиђи у кућу лончареву, и ондје ћу ти казати ријечи своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Тада сиђох у кућу лончареву, и гле, он рађаше посао на свом колу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'И поквари се у руци лончару суд који грађаше од кала, па начини изнова од њега други суд, како бијаше воља лончару да начини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Тада дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Не могу ли чинити од вас као овај лончар, доме Израиљев? говори Господ; гле, што је као у руци лончаревој, то сте ви у мојој руци, доме Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Кад бих рекао за народ и за царство да га истријебим и разорим и затрем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Ако се обрати народ ода зла, за које бих рекао, и мени ће бити жао са зла, које мишљах да му учиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'А кад бих рекао за народ и за царства да га сазидам и насадим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Ако учини што је зло преда мном не слушајући гласа мојега, и мени ће бити жао добра које рекох да му учиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Зато сада реци Јудејцима и Јерусалимљанима говорећи: овако вели Господ: ево спремам на вас зло, и мислим мисли на вас; вратите се дакле сваки са својега пута злога, и поправите путове своје и дјела своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'А они рекоше: нема ништа од тога, него ћемо ићи за својим мислима и чинићемо сваки по мисли срца својега злога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Зато овако говори Господ: питајте по народима је ли ко чуо тако што? грдило велико учини дјевојка Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Оставља ли снијег Ливански са стијене моја поља? остављају ли се воде студене, које теку?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'А народ мој мене заборави, кади таштини, и спотичу се на својим путовима, на старијем стазама, да ходе стазама пута непоравњена,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Да бих обратио земљу њихову у пустош, на вјечну срамоту, да се чуди ко год прође преко ње и маше главом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Као устоком разметнућу их пред непријатељем; леђа а не лице показаћу им у невољи њиховој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'А они рекоше: ходите да смислимо што Јеремији, јер неће нестати закона свештенику ни свјета мудрацу ни ријечи пророку; ходите убијмо га језиком и не пазимо на ријечи његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Пази на ме, Господе, и чуј глас мојих противника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Еда ли ће се зло вратити за добро, кад ми копају јаму? Опомени се да сам стајао пред тобом говорећи за њихово добро, да бих одвратио гњев твој од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Зато предај синове њихове глади и учини да изгину од мача, и жене њихове да буду сироте и удове, и мужеви њихови да се погубе, младиће њихове да побије мач у боју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Нека се чује вика из кућа њиховијех, кад доведеш на њих војску изненада; јер ископаше јаму да ме ухвате, и замке намјестише ногама мојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'А ти, Господе, знаш све што су наумили мени да ме убију, немој им опростити безакоња ни гријеха њихова избрисати испред себе; него нека попадају пред тобом, у гњеву свом ради супрот њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Овако рече Господ: иди и купи крчаг земљан у лончара с неколико старјешина народнијех и старјешина свештеничких.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'И отиди у долину сина Еномова што је пред вратима источнијем, и ондје прогласи ријечи које ћу ти казати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'И реци: чујте ријеч Господњу, цареви Јудини и становници Јерусалимски; овако вели Господ над војскама Бог Израиљев: ево, ја ћу пустити зло на то мјесто да ће зујати уши свакоме ко га чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Јер ме оставише и оскврнише ово мјесто кадећи на њему другим боговима, којих не знаше ни они ни оци њихови, ни цареви Јудини, и напунише то мјесто крви праве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'И поградише висине Валу да сажижу синове своје огњем на жртве паљенице Валу, чега не заповједих нити о том говорих, нити ми на ум дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Зато, ево, иде вријеме, вели Господ, кад се ово мјесто неће више звати Тофет, ни долина сина Еномова, него крвна долина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Јер ћу уништити савјет Јудин и Јерусалимски на овом мјесту, и учинићу да падну од мача пред непријатељима својим и од руке онијех који траже душу њихову, и мртва ћу тјелеса њихова дати за храну птицама небеским и звијерима земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'И обратићу тај град у пустош и руг: ко год прође мимо њ, чудиће се и звиждаће за све муке његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'И учинићу да једу месо од својих синова и месо од својих кћери, и сваки ће јести месо од друга својега у невољи и тјескоби којом ће им досађивати непријатељи њихови и који траже душу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Потом разбиј крчаг пред људима који ће ићи с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'И реци им: овако вели Господ над војскама: тако ћу разбити тај народ и тај град као што се разбије суд лончарски, који се не може више оправити, и у Тофету ће се погребавати, јер не ће бити мјеста за погребавање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Тако ћу учинити томе мјесту, вели Господ, и становницима његовијем и учинићу тај град да буде као Тофет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'И куће Јерусалимске и куће царева Јудинијех биће нечисте као мјесто Тофет, све куће, гдје на крововима кадише свој војсци небеској и љеваше наљеве другим боговима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Потом се врати Јеремија из Тофета куда га бјеше послао Господ да пророкује, и стаде у тријему дома Господњега, и рече свему народу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Овако вели Господ над војскама Бог Израиљев: ево, ја ћу пустити на тај град и на све градове његове све зло које изрекох за њ, јер отврднуше вратом својим да не слушају ријечи мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'А Пасхор син Имиров свештеник, који бијаше старјешина у дому Господњем, чу Јеремију гдје пророкује те ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'И удари Пасхор пророка Јеремију, и метну га у тамницу на горњим вратима Венијаминовијем уз дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'А сјутрадан кад Пасхор изведе Јеремију из тамнице, рече му Јеремија: Господ ти надје име не Пасхор него Магор-Мисавив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Јер овако вели Господ: ево, ја ћу пустити на те страх, на те и на све пријатеље твоје, који ће пасти од мача непријатеља својих, и очи ће твоје видјети, и свега ћу Јуду дати у руке цару Вавилонском, који ће их одвести у Вавилон, и побиће их мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'И даћу све богатство тога града и сав труд његов и све што има драгоцјено, и све благо царева Јудинијех даћу непријатељима њиховијем у руке, и разграбиће и узети и однијети у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'И ти, Пасхоре, и сви који живе у твом дому отићи ћете у ропство; и доћи ћеш у Вавилон и ондје ћеш умријети и ондје ћеш бити погребен ти и сви пријатељи твоји, којима си пророковао лажно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Наговарао си ме, Господе, и дадох се наговорити; био си јачи од мене и надвладао си ме; на потсмијех сам сваки дан, свак ми се потсмијева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Јер откад говорим, вапијем, ради насиља и пустошења вичем, јер ми је ријеч Господња на поругу и на потсмијех сваки дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'И рекох: нећу га више помињати, нити ћу више говорити у име његово; али би у срцу мом као огањ разгорио, затворен у костима мојим, и уморих се задржавајући га, и не могох више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Јер чујем поруге од многих, страх отсвуда: прокажите да прокажемо; сви који бијаху у миру са мном, вребају да посрнем: да ако се превари, те ћемо га надвладати и осветићемо му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Али је Господ са мном као страшан јунак; зато они који ме гоне спотакнуће се и неће надвладати; посрамиће се врло; јер неће бити срећни, срамота вјечна неће се заборавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Зато, Господе над војскама, који кушаш праведника, који видиш бубреге и срце, дај да видим твоју освету на њима, јер теби казах парбу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Пјевајте Господу, хвалите Господа, јер избави душу сиромаху из руке зликовачке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Проклет да је дан у који се родих! дан, у који ме роди мати моја, да није благословен!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Проклет да је човјек који јави оцу мојему и врло га обрадова говорећи: роди ти се син.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'И тај човјек да би био као градови које Господ затр и не би му жао! нека слуша вику ујутру и вриску у подне,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'Што ме не усмрти у утроби материној да би ми мати моја била гроб, и утроба њезина да би остала довијека трудна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Зашто изидох из утробе да видим муку и жалост и да се сврше у срамоти дани моји?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Ријеч која дође Јеремији од Господа кад посла к њему цар Седекија Пасхора сина Мелхијина и Софонију сина Масијина свештеника, и поручи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Упитај Господа за нас, јер Навуходоносор цар Вавилонски завојшти на нас; еда би нам учинио Господ по свијем чудесима својим, да отиде од нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'А Јеремија им рече: овако реците Седекији:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Овако вели Господ Бог Израиљев: ево, ја ћу окренути натраг оружје што је у вашим рукама, којим се бијете с царем Вавилонским и с Халдејцима који су вас опколили иза зидова, и скупићу их усред тога града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'И ја ћу војевати на вас руком подигнутом и мишицом крјепком и гњевом и јарошћу и жестином великом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'И побићу становнике тога града, и људе и стоку; од помора великога помријеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'А послије, вели Господ, даћу Седекију цара Јудина и слуге њихове и народ, оне који остану у том граду од помора, од мача и од глади, у руке Навуходоносору цару Вавилонском и у руке непријатељима њиховијем и у руке онима који траже душу њихову, те ће их побити мачем, неће их жалити ни штедјети нити ће се смиловати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'А народу томе реци: овако вели Господ; ево ја стављам пред вас пут к животу и пут к смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Ко остане у том граду, погинуће од мача или од глади или од помора; а ко изађе и преда се Халдејцима који су вас опколили, остаће жив, и душа ће му бити мјесто плијена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Јер окретох лице своје томе граду на зло а не на добро, говори Господ; у руке цару Вавилонском биће предан, и он ће га спалити огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'А за дом цара Јудина чујте ријеч Господњу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Доме Давидов, тако вели Господ, судите свако јутро, и коме се отима избављајте га из руку насилниковијех да не изађе као огањ гњев мој и разгори се да га нико не може угасити за злоћу дјела ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Ево ме на тебе, који сједиш у долини, као стијена у равници, говори Господ, на вас, који говорите: ко ће доћи на нас? и ко ће ући у станове наше?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Јер ћу вас покарати по плоду дјела ваших, вели Господ, и распалићу огањ у шуми његовој, који ће прождријети све што је око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Овако говори Господ: сиђи у дом цара Јудина, и реци ондје ову ријеч,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'И кажи: слушај ријеч Господњу, царе Јудин, који сједиш на пријестолу Давидову, ти и слуге твоје и народ твој, који улазите на ова врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Овако вели Господ: чините суд и правду, и коме се отима избављајте га из руку насилниковијех, и не чините криво иностранцу ни сироти ни удовици, и не чините им силе, и крви праве не прољевајте на овом мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Јер ако доиста узрадите ово, улазиће на врата овога дома цареви, који сједе мјесто Давида на пријестолу његову, на колима и на коњма, они и слуге њихове и народ њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Ако ли не послушате овијех ријечи, заклињем се собом, вели Господ, да ћу опустјети тај дом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Јер овако вели Господ за дом цара Јудина: ти си ми Галад и врх Ливански, али ћу те обратити у пустињу, у градове у којима се не живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'И спремићу на тебе затираче, свакога с оружјем, и посјећи ће твоје красне кедре и побацати их у огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'И многи ће народи пролазити мимо тај град, и говориће један другоме: зашто учини ово Господ од тога града великога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'И рећи ће: јер оставише завјет Господа Бога својега и клањаше се другим боговима и служише им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Не плачите за мртвијем нити га жалите; него плачите за онијем који одлази, јер се неће више вратити нити ће видјети своје постојбине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Јер овако говори Господ о Салуму сину Јосије цара Јудина, који цароваше мјесто Јосије оца својега, који отиде из овога мјеста: неће се више вратити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Него ће умријети у мјесту куда га одведоше у ропство, и неће више видјети ове земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Тешко оному који гради своју кућу не по правди, и клијети своје не по правици, који се служи ближњим својим ни за што и плате за труд његов не даје му;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Који говори: саградићу себи велику кућу и простране клијети; и разваљује себи прозоре, и облаже кедром и маже црвенилом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Хоћеш ли царовати кад се мијешаш с кедром? Отац твој није ли јео и пио? кад чињаше суд и правду, тада му бијаше добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Даваше правицу сиромаху и убогоме, и бијаше му добро; није ли то познавати ме? говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Али очи твоје и срце твоје иду само за твојим добитком и да прољеваш крв праву и да чиниш насиље и кривду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Зато овако вели Господ за Јоакима сина Јосије цара Јудина: неће нарицати за њим: јаох брате мој! или: јаох сестро! неће нарицати за њим: јаох господару! или: јаох славо његова!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Погребом магарећим погрепшће се, извући ће се и бациће се иза врата Јерусалимских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Изиди на Ливан и вичи, и на Васану пусти глас свој, и вичи преко бродова, јер се сатрше сви који те љубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Говорих ти у срећи твојој, а ти рече: нећу да слушам; то је пут твој од дјетињства твојега да не слушаш гласа мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Све ће пастире твоје однијети вјетар, и који те љуби отићи ће у ропство; тада ћеш се посрамити и постидјети за сву злоћу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Ти сједиш на Ливану, гнијездо вијеш на кедрима, како ћеш бити љупка, кад ти дођу муке и болови као породиљи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Како сам ја жив, вели Господ, да би Хонија син Јоакима цара Јудина био прстен печатни на десној руци мојој, и оданде ћу те отргнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'И даћу те у руке онима који траже душу твоју, и у руке онима којих се бојиш, у руке Навуходоносору цару Вавилонском и у руке Халдејцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'И бацићу тебе и матер твоју која те је родила у земљу туђу, гдје се нијесте родили, и ондје ћете помријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'А у земљу у коју ћете жељети да се вратите, нећете се вратити у њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Је ли тај човјек Хонија ништав идол изломљен? је ли суд у ком нема милине? зашто бише истјерани, он и сјеме његово, и бачени у земљу, које не познају?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'О земљо, земљо, земљо! чуј ријеч Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Овако вели Господ: запишите да ће тај човјек бити без дјеце и да неће бити срећан до свога вијека; и нико неће бити срећан од сјемена његова, који би сједио на пријестолу Давидову и још владао Јудом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Тешко пастирима који потиру и размећу стадо паше моје! говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Зато овако вели Господ Бог Израиљев за пастире који пасу народ мој: ви разметнусте овце моје и разагнасте их, и не обилазисте их; ево, ја ћу вас обићи за злоћу дјела ваших, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'И остатак оваца својих ја ћу скупити из свијех земаља у које их разагнах, и вратићу их у торове њихове, гдје ће се наплодити и умножити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'И поставићу им пастире, који ће их пасти, да се не боје више и не плаше и да не погине ни једна, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Гле, иду дани, говори Господ, у које ћу подигнути Давиду клицу праведну, која ће царовати и бити срећна и чинити суд и правду на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'У његове дане спашће се Јуда, и Израиљ ће становати у миру, и ово му је име којим ће се звати: Господ правда наша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Зато, ево, иду дани, говори Господ, у које се неће више говорити: тако да је жив Господ, који је извео синове Израиљеве из земље Мисирске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Него: тако да је жив Господ, који је извео и довео сјеме дома Израиљева из сјеверне земље и из свијех земаља, у које их бијах разагнао. И они ће сједети у својој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Ради пророка пуца срце у мени, трепећу све кости моје, као пијан сам и као човјек којега је освојило вино, Господа ради и његовијех ради светијех ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Јер је земља пуна прељубочинаца, и с клетава тужи земља, посушише се паше у пустињи; трк је њихов зао и моћ њихова неправа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Јер и пророк и свештеник скврне је, налазим и у дому свом злоћу њихову, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Зато ће пут њихов бити као клизавица по тами, гдје ће попузнути и пасти; јер ћу пустити на њих зло године похођења њихова, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'У пророка Самаријских видио сам безумље, пророковаху Валом, прелашћиваху народ мој Израиља;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Али у пророка Јерусалимских видим страхоту: чине прељубу и ходе у лажи, укрјепљују руке зликовцима да се нитко не врати од своје злоће; сви су ми као Содом, и становници његови као Гомор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Зато овако вели Господ над војскама о тијем пророцима: ево, ја ћу их нахранити пеленом и напојићу их жучи; јер од пророка Јерусалимских изиде оскврњење по свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Овако вели Господ над војскама: не слушајте што говоре пророци који вам пророкују; варају вас, говоре утваре својега срца, не из уста Господњих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Једнако говоре онима који не маре за ме: Господ је рекао: имаћете мир; и свакоме који иде по мисли срца својега говоре: неће доћи на вас зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Јер ко је стајао у вијећу Господњем, и видио или чуо ријеч његову? ко је пазио на ријеч његову и чуо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Ево, вихор Господњи, гњев, изићи ће вихор, који не престаје, пашће на главу безбожницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Неће се одвратити гњев Господњи докле не учини и изврши што је у срцу наумио; најпослије ћете разумјети то сасвијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Не слах тијех пророка, а они трчаше; не говорих им, а они пророковаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Да су стајали у мом вијећу, тада би казивали моје ријечи народу мојему, и одвраћали би их с пута њихова злога и од злоће дјела њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Јесам ли ја Бог изблиза, говори Господ, а нијесам Бог и издалека?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Може ли се ко сакрити на тајно мјесто да га ја не видим? говори Господ; не испуњам ли ја небо и земљу? говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Чујем што говоре ти пророци који у име моје пророкују лаж говорећи: снио сам, снио сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Докле ће то бити у срцу пророцима који пророкују лаж, и пријевару срца својега пророкују?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Који мисле да ће учинити да народ мој заборави име моје уза сне њихове, које приповиједају један другому, као што заборавише оци њихови име моје уз Вала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Пророк који сни, нека приповиједа сан; а у кога је ријеч моја, нека говори ријеч моју истинито; шта ће пљева са пшеницом? говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Није ли ријеч моја као огањ, говори Господ, и као маљ који разбија камен?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Зато, ево ме на те пророке, говори Господ, који краду моје ријечи један од другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Ево ме на те пророке, вели Господ, који дижу језик свој и говоре: он вели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Ево ме на оне који пророкују лажне сне, вели Господ, и приповиједајући их заводе народ мој лажима својим и хитрином својом; а ја их нијесам послао нити сам им заповједио; и неће ништа помоћи томе народу, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Ако те запита овај народ или који пророк или свештеник говорећи: како је бреме Господње? тада им реци: како бреме? оставићу вас, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'А пророка и свештеника и народ који рече: бреме Господње, ја ћу покарати тога човјека и дом његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Него овако говорите сваки ближњему својему и сваки брату својему: шта одговори Господ? и: шта рече Господ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'А бремена Господњега не помињите више, јер ће свакоме бити бреме ријеч његова, јер изврћете ријечи Бога живога, Господа над војскама, Бога нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Овако реци пророку: шта ти одговори Господ? и: шта ти рече Господ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Али кад кажете: бреме Господње, зато овако вели Господ: шта говорите ту ријеч: бреме Господње, а ја слах к вама да вам кажу: не говорите: бреме Господње,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'Зато ево ме, ја ћу вас заборавити сасвијем и одбацићу од себе вас и град који сам дао вама и оцима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'И навалићу на вас поругу вјечну и срамоту вјечну која се неће заборавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Показа ми Господ, и гле, двије котарице смокава намјештене пред црквом Господњом, пошто Навуходоносор цар Вавилонски зароби Јехонију сина Јоакимова цара Јудина, и кнезове Јудине, и дрводјеље и коваче из Јерусалима и одведе их у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'У једној котарици бијаху смокве врло добре, каке бијаху ране смокве, а у другој котарици бијаху врло рђаве смокве, које се не могаху јести, тако бијаху рђаве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'И рече ми Господ: шта видиш, Јеремија? А ја рекох: смокве, једне добре смокве, врло добре, а друге рђаве, врло рђаве, које се не могу јести, тако су рђаве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'И дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Овако вели Господ Бог Израиљев: каке су те смокве добре, тако ће ми бити добра ради робље Јудино, које одаслах из овога мјеста у земљу Халдејску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'И обратићу очи своје на њих добра ради, и довешћу их опет у ову земљу, и сазидаћу их и нећу их разорити, и насадићу их и нећу их почупати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Јер ћу им дати срце да ме познаду да сам ја Господ, и биће ми народ и ја ћу им бити Бог, јер ће се обратити к мени свијем срцем својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'А каке су те рђаве смокве да се не могу јести, како су рђаве, таким ћу, вели Господ, учинити Седекију цара Јудина и кнезове његове и остатак Јерусалимљана који осташе у овој земљи и који живе у земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Учинићу да се потуцају по свијем царствима земаљским на зло, да буду срамота и прича и руг и уклин по свијем мјестима, куда их разденем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'И послаћу на њих мач, глад и помор, докле се не истријебе са земље, коју сам дао њима и оцима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Ријеч која дође Јеремији за сав народ Јудин четврте године Јоакима сина Јосијина цара Јудина, а то је прва година Навуходоносора цара Вавилонскога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'Коју рече Јеремија пророк свему народу Јудину и свијем становницима Јерусалимским, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Од тринаесте године Јосије сина Амонова цара Јудина до данас, за ове двадесет и три године, долази ми ријеч Господња и говорих вам зарана једнако, али не послушасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'И сла вам Господ све слуге своје пророке зарана једнако, али не послушасте, нити пригнусте уха својега да бисте чули.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'И говораху: вратите се сваки са својега пута злога и од злоће дјела својих, па ћете остати у земљи коју даде Господ вама и оцима вашим одвијека довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'И не идите за другим боговима да им служите и да им се клањате, и не гњевите ме дјелом руку својих, и нећу вам учинити зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Али ме не послушасте, говори Господ, него ме гњевисте дјелом руку својих на своје зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Зато овако вели Господ над војскама: што не послушасте мојих ријечи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Ево, ја ћу послати по све народе сјеверне, говори Господ, и по Навуходоносора цара Вавилонскога слугу својега, и довешћу их на ту земљу и на становнике њезине, и на све те народе околне, које ћу затрти, и учинићу да буду чудо и потсмијех и пустош вјечна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'И учинићу да нестане међу њима гласа радосна и гласа весела, гласа женикова и гласа невјестина, лупе од жрвања и свјетлости од жишка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'И сва ће та земља бити пустош и чудо, и ти ће народи служити цару Вавилонском седамдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'А кад се наврши седамдесет година, онда ћу походити цара Вавилонскога и онај народ, говори Господ, за безакоње њихово, и земљу Халдејску, и обратићу је у пустош вјечну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'И пустићу на ту земљу све што сам говорио о њој, све што је написано у овој књизи, што пророкова Јеремија за све народе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Јер ће велики народи и силни цареви и њих покорити; тада ћу им платити по дјелима њиховијем и по оном што су чинили рукама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Јер овако ми рече Господ Бог Израиљев: узми из моје руке чашу вина, овога гњева, и напој из ње све народе ка којима те ја пошљем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Нека пију и смету се и полуде од оштрога мача који ћу ја послати међу њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'И узех чашу из руке Господу, и напојих све те народе, ка којима ме посла Господ:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Јерусалим и градове Јудине и цареве његове и кнезове његове, да буду пустош и чудо и потсмијех и уклин, као што је данас,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Фараона цара Мисирскога и слуге његове и кнезове његове и сав народ његов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'И сву мјешавину, и све цареве земље Уза, све цареве земље Филистејске, и Аскалон и Газу и Акарон и остатак од Азота,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Едомце и Моавце и синове Амонове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'И све цареве Тирске и све цареве Сидонске и цареве на острвима преко мора,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Дедана и Тему и Вуза, и све који се с краја стригу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'И све цареве Арапске и све цареве од мјешавине који живе у пустињи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'И све цареве Зимријске, и све цареве Еламске, и све цареве Мидске,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'И све цареве сјеверне, који су близу и који су далеко, како једнога тако другога, и сва царства земаљска што су по земљи; а цар Сисашки пиће послије њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'И реци им: овако вели Господ над војскама Бог Израиљев: пијте и опијте се, и бљујте и падајте, да не устанете од мача који ћу пустити међу вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Ако ли не би хтјели узети чаше из руке твоје да пију, тада им реци: овако вели Господ над војскама: заиста ћете пити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Јер ево почињем пуштати зло на град који се назива мојим именом, а ви ли ћете остати без кара? нећете остати без кара, јер ћу дозвати мач на све становнике земаљске, говори Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Ти дакле пророкуј им све ове ријечи и реци им: Господ ће с висине рикнути, и из стана светиње своје пустиће глас свој, силно ће рикнути из стана својега, као они што газе грождје подигнуће вику на све становнике земаљске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Проћи ће граја до краја земље, јер распру има Господ с народима, суди се са сваким тијелом, безбожнике ће дати под мач, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Овако вели Господ над војскама: ево, невоља ће поћи од народа до народа, и велик ће се вихор подигнути од крајева земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'И у онај ће дан бити од краја до краја земље побијени од Господа, неће бити оплакани, нити ће се покупити и погрепсти, биће гној по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Ридајте, пастири, и вичите и ваљајте се по праху, главари стаду, јер се навршише ваши дани да будете поклани, и да се разаспете, и пашћете као скупоцјен суд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'И неће бити уточишта пастирима, ни избављења главарима од стада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Викаће пастири и ридаће главари од стада, јер ће потрти Господ пашу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'И развалиће се мирни торови од жестокога гњева Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Као лавић оставио је шатор свој, јер ће земља њихова опустјети од жестине насилникове и од љутога гњева његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'У почетку царовања Јоакима сина Јосијина цара Јудина дође ова ријеч од Господа говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Овако говори Господ: стани у тријему дома Господњега, и говори свијем градовима Јудинијем, који долазе да се поклоне у дому Господњем, све ријечи које ти заповиједам да им кажеш, не изостави ни ријечи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Не би ли послушали и вратили се сваки са свога злога пута, да ми се сажали са зла које им мислим учинити за злоћу дјела њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Реци им дакле: овако вели Господ: ако ме не послушате да ходите у мом закону који сам ставио пред вас,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'Да слушате ријечи слуга мојих пророка, које вам шаљем, које слах зарана једнако, али их не послушасте,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'Учинићу с домом овијем као са Силомом, и град овај даћу у проклетство свијем народима на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'А свештеници и пророци и сав народ чуше Јеремију гдје говори те ријечи у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'И кад Јеремија изговори све што му Господ заповједи да каже свему народу, ухватише га свештеници и пророци и сав народ говорећи: погинућеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Зашто пророкова у име Господње говорећи: овај ће дом бити као Силом, и овај ће град опустјети да неће у њему нико живјети? И скупи се сав народ на Јеремију у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'А кнезови Јудини чувши то дођоше из дома царскога у дом Господњи, и сједоше пред нова врата Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'И рекоше свештеници и пророци кнезовима и свему народу говорећи: овај је човјек заслужио смрт, јер пророкова против овога града, као што чусте својим ушима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Тада проговори Јеремија свијем кнезовима и свему народу говорећи: Господ ме посла да пророкујем против овога дома и против овога града све што чусте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Зато поправите путове своје и дјела своја, и послушајте ријеч Господа Бога својега, и сажалиће се Господу са зла које је изрекао за вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'А ја, ево сам у вашим рукама, чините од мене што мислите да је добро и право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Али знајте зацијело, ако ме убијете, крв праву свалићете на се и на овај град и на становнике његове, јер доиста Господ ме посла к вама да говорим све ове ријечи да чујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Тада рекоше кнезови и сав народ свештеницима и пророцима: није овај човјек заслужио смрти, јер нам је говорио у име Господа Бога нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'И усташе неки од старјешина земаљских, и проговорише свему збору народном и рекоше:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Михеј Морашћанин пророкова у вријеме Језекије цара Јудина и говори свему народу Јудину и рече: овако вели Господ над војскама: Сион ће се преорати као њива и град ће Јерусалим бити гомила камења, и гора овога дома висока шума.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Је ли га зато убио Језекија цар Јудин и сав Јуда? није ли се побојао Господа и молио се Господу? и Господу се сажали ради зла које бјеше изрекао на њих; ми дакле чинимо велико зло душама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'И још бјеше један који пророкова у име Господње, Урија син Семајин из Киријат-Јарима; он пророкова против овога града и против ове земље исто онако као Јеремија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'И кад чу цар Јоаким и све војводе његове и сви кнезови ријечи његове, тражи га цар да га убије; а Урија чувши побоја се и побјеже и дође у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'А цар Јоаким посла неке у Мисир, Елнатана сина Аховорова и друге с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'И они изведоше Урију из Мисира и доведоше к цару Јоакиму, и уби га мачем, и баци тијело његово у гробље простога народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Али рука Ахикама сина Сафанова би уз Јеремију, те га не предаше у руке народу да га погубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'У почетку царовања Јоакима сина Јосијина цара Јудина дође ова ријеч Јеремији од Господа говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Овако ми рече Господ: начини себи свезе и јарам, и метни себи око врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'По том пошљи их цару Едомском и цару Моавском и цару синова Амоновијех и цару Тирском и цару Сидонском, по посланицима који ће доћи у Јерусалим к Седекији цару Јудину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'И наручи им нека реку својим господарима: овако вели Господ над војскама Бог Израиљев: овако реците својим господарима:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Ја сам створио земљу и људе и стоку, што је по земљи, силом својом великом и мишицом својом подигнутом; и дајем је коме ми је драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'И сада ја дадох све те земље у руке Навуходоносору цару Вавилонском слузи својему, дадох му и звијерје пољско да му служи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'И сви ће народи служити њему и сину његову и унуку његову докле дође вријеме и његовој земљи, и велики народи и силни цареви покоре га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'А који народ или царство не би хтио служити Навуходоносору цару Вавилонском, и не би хтио савити врата својега у јарам цара Вавилонскога, таки ћу народ походити мачем и глађу и помором, говори Господ, докле их не истријебим руком његовом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Не слушајте дакле пророка својих ни врача својих ни сањача својих ни гатара својих ни бајача својих, који вам говоре и веле: нећете служити цару Вавилонском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Јер вам они лаж пророкују, како бих вас далеко одвео из земље ваше и изагнао вас да изгинете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'А народ који би савио врат свој под јарам цара Вавилонскога и служио му, оставићу га на земљи његовој, говори Господ, да је ради и станује у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'И Седекији цару Јудину рекох све ово говорећи: савијте врат свој под јарам цара Вавилонскога и служите њему и народу његову, па ћете остати живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Зашто да погинете ти и народ твој од мача и од глади и од помора, како рече Господ за народ који не би служио цару Вавилонском?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Не слушајте дакле што говоре пророци који вам кажу и веле: не ћете служити цару Вавилонском, јер вам они пророкују лаж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Јер их ја нијесам послао, говори Господ, него лажно пророкују у моје име, како бих вас прогнао да изгинете и ви и пророци који вам пророкују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'И свештеницима и свему народу говорих и рекох: овако вели Господ: не слушајте што говоре ваши пророци који вам пророкују говорећи: ево, посуђе дома Господњега вратиће се из Вавилона скоро. Јер вам они пророкују лаж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Не слушајте их; служите цару Вавилонском, и остаћете живи; зашто тај град да опусти?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Ако ли су пророци и ако је ријеч Господња у њих, нека моле Господа над војскама да судови што су остали у дому Господњем и у дому цара Јудина и у Јерусалиму не отиду у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Јер овако вели Господ над војскама за ступове и за море и за подножја и за друге судове што су остали у том граду,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'Којих не узе Навуходоносор цар Вавилонски кад одведе у ропство Јехонију сина Јоакимова цара Јудина из Јерусалима у Вавилон, и све главаре Јудине и Јерусалимске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Јер овако вели Господ над војскама Бог Израиљев за судове што осташе у дому Господњем и у дому цара Јудина у Јерусалиму:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'У Вавилон ће се однијети и ондје ће бити до дана кад ћу их походити, вели Господ, кад ћу их донијети и вратити на ово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'А исте године, у почетку царовања Седекије цара Јудина, четврте године, петога мјесеца, рече ми Ананија син Азоров, пророк из Гаваона, у дому Господњем пред свештеницима и свијем народом говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Овако вели Господ над војскама Бог Израиљев: сломих јарам цара Вавилонскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'До двије године ја ћу вратити на ово мјесто све судове дома Господњега, које узе Навуходоносор цар Вавилонски одавде и однесе у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'И Јехонију сина Јоакимова цара Јудина и све робље Јудино што отиде у Вавилон, ја ћу довести опет на ово мјесто, говори Господ, јер ћу сломити јарам цара Вавилонскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Тада рече Јеремија пророк Ананији пророку пред свештеницима и пред свијем народом, који стајаше у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Рече Јеремија пророк: амин, да Господ учини тако, да Господ испуни твоје ријечи што си пророковао да би вратио судове дома Господњега и све робље из Вавилона на ово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Али чуј ову ријеч коју ћу ја казати пред тобом и пред свијем народом:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Пророци који су били прије мене и прије тебе од старине, они пророковаше многим земљама и великим царствима рат и невољу и помор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Пророк који прориче мир, кад се збуде ријеч тога пророка, онда се познаје тај пророк да га је заиста послао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Тада Ананија пророк скиде јарам с врата Јеремији пророку и сломи га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'И рече Ананија пред свијем народом говорећи: овако вели Господ: овако ћу сломити јарам Навуходоносора цара Вавилонскога до двије године с врата свијех народа. И отиде пророк Јеремија својим путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Али дође ријеч Господња Јеремији, пошто сломи Ананија пророк јарам с врата Јеремији пророку, и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Иди и кажи Ананији и реци: овако вели Господ: сломио си јарам дрвени, али начини мјесто њега гвозден јарам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Јер овако вели Господ над војскама Бог Израиљев: гвозден ћу јарам метнути на врат свијем тијем народима да служе Навуходоносору цару Вавилонском, и служиће му, дао сам му и звијерје пољско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Потом рече Јеремија пророк Ананији пророку: чуј, Ананија; није те послао Господ, а ти си учинио да се народ овај поузда у лаж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Зато овако вели Господ: ево, ја ћу те скинути са земље, ове године ти ћеш умријети; јер си казивао одмет од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'И умрије пророк Ананија те године седмога мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'А ово су ријечи у посланици коју посла пророк Јеремија из Јерусалима к остатку старјешина заробљенијех и свештеницима и пророцима и свему народу што га пресели Навуходоносор из Јерусалима у Вавилон,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Пошто отиде из Јерусалима цар Јехонија и царица и дворани и кнезови Јудини и Јерусалимски, и дрводјеље и ковачи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'По Еласи сину Сафанову и Гемарији сину Хелкијину, које сла Седекија цар Јудин у Вавилон к Навуходоносору цару Вавилонском; и у књизи говораше:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Овако вели Господ над војскама, Бог Израиљев, свему робљу које преселих из Јерусалима у Вавилон:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Градите куће и сједите у њима; садите вртове и једите род њихов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Жените се и рађајте синове и кћери; и синове своје жените, и кћери своје удајите, нека рађају синове и кћери, и множите се ту и не умаљујте се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'И тражите добро граду, у који вас преселих, и молите се за њ Господу, јер у добру његову биће вама добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Јер овако вели Господ над војскама Бог Израиљев: немојте да вас варају ваши пророци што су међу вама и ваши врачи, и не гледајте на сне своје што сањате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Јер вам они лажно пророкују у моје име, ја их нијесам послао, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Јер овако вели Господ: кад се наврши у Вавилону седамдесет година, походићу вас, и извршићу вам добру ријеч своју да ћу вас вратити на ово мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Јер ја знам мисли које мислим за вас, говори Господ, мисли добре а не зле, да вам дам пошљедак какав чекате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Тада ћете ме призивати и ићи ћете и молићете ми се, и услишићу вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'И тражићете ме, и наћи ћете ме, кад ме потражите свијем срцем својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'И даћу вам се да ме нађете, говори Господ, и вратићу робље ваше, и сабраћу вас из свијех народа и из свијех мјеста у која сам вас разагнао, говори Господ, и довешћу вас опет на мјесто, одакле сам вас иселио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Јер рекосте: Господ нам подиже пророке у Вавилону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Јер овако вели Господ за цара који сједи на пријестолу Давидову и за сав народ који стоји у овом граду, за браћу вашу што не отидоше с вама у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Овако вели Господ над војскама: ево, ја ћу пустити на њих мач, глад и помор, и учинићу их да буду као смокве рђаве; које се не могу јести, како су рђаве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'И гонићу их мачем и глађу и помором, и учинићу да се потуцају по свијем царствима земаљским, да буду уклин и чудо и потсмијех и руг у свијех народа, у које их проженем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Јер не послушаше мојих ријечи, говори Господ, кад слах к њима слуге своје пророке зарана једнако; али не послушасте, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Слушајте дакле ријеч Господњу ви сви заробљени, које послах из Јерусалима у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Овако вели Господ над војскама Бог Израиљев за Ахава сина Колајина и за Седекију сина Масијина, који вам пророкују у моје име лаж: ево, ја ћу их предати у руке Навуходоносору цару Вавилонском, да их побије на ваше очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'И од њих ће се узети уклин међу све робље Јудино што је у Вавилону, те ће говорити: Господ да учини од тебе као од Седекије и као од Ахава, које испече цар Вавилонски на огњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Јер учинише грдило у Израиљу чинећи прељубу са женама ближњих својих и говорећи лаж на моје име, што им не заповједих; ја знам то, и свједок сам, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'И Семаји из Нелама реци говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Овако вели Господ над војскама Бог Израиљев говорећи: што си у своје име послао књиге свему народу који је у Јерусалиму, и Софонији сину Масијину свештенику и свијем свештеницима, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Господ те постави свештеником на мјесто Јодаја свештеника да пазите у дому Господњем на свакога човјека безумна и који се гради пророк, да их мећеш у тамницу и у кладе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Зашто дакле не укори Јеремије Анатоћанина, који се гради пророк међу вама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Јер посла к нама у Вавилон и поручи: дуго ће трајати; градите куће и сједите у њима, и садите вртове и једите род њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'И Софонија свештеник прочита ту књигу пред пророком Јеремијом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'И дође ријеч Господња Јеремији говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Пошљи ка свему робљу и поручи: овако вели Господ за Семају из Нелама: што вам пророкује Семаја, а ја га не послах, и чини да се уздате у лаж,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'Зато овако вели Господ: ево, ја ћу походити Семају Неламљанина и сјеме његово, неће од њега нико остати у овом народу нити ће видјети добра што ћу ја учинити народу својему, говори Господ, јер казива одмет од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Ријеч која дође Јеремији од Господа говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Овако вели Господ Бог Израиљев говорећи: напиши у књигу све ријечи које ти говорих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Јер ево иду дани, говори Господ, кад ћу повратити робље народа својега Израиља и Јуде, говори Господ, и довешћу их натраг у земљу коју сам дао оцима њиховијем, и држаће је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'И ово су ријечи које рече Господ за Израиља и Јуду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Јер овако вели Господ: чусмо вику од препадања, страха, а мира нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Питајте, и видите, еда ли мушко рађа? зашто дакле видим гдје се сваки човјек држи рукама својима за бедра своја као породиља и у свијех се промијенила лица и поблиједјела?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Јаох! јер је велик овај дан, није било такога, и вријеме је муке Јаковљеве, ипак ће се избавити из ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Јер у тај дан, говори Господ над војскама, сломићу јарам његов с врата твојега, и свезе твоје покидаћу; и неће га више туђини нагонити да им служи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Него ће служити Господу Богу својему и Давиду цару својему, којега ћу им подигнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Ти се дакле не бој, Јакове слуго мој, говори Господ, и не плаши се, Израиљу; јер, ево, ја ћу те избавити из даљне земље, и сјеме твоје из земље ропства твојега, и Јаков ће се вратити и почивати, и биће миран, и нико га неће плашити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Јер сам ја с тобом, говори Господ, да те избавим; и учинићу крај свијем народима, међу које сам те расијао, али теби нећу учинити краја, него ћу те покарати с мјером, а нећу те оставити сасвијем без кара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Јер овако вели Господ: смртан је полом твој и рана твоја љута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Нема никога који би се примио твоје ствари да те лијечи, нема лијека који би ти помогао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Сви који те љубе заборавише те, не траже те, јер те ударих ударцем непријатељским, каром жестоким, за мноштво безакоња твојега, за силне гријехе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Зашто вичеш ради ране своје, смртнога бола својега? за мноштво безакоња твојега, за силне гријехе твоје чиним ти то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Али сви који те прождиру, прождријеће се, и непријатељи твоји свиколики отићи ће у ропство, и који те газе, биће погажени, и све који те плијене, даћу их да се оплијене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Јер ћу те исцијелити, и ране ћу ти излијечити, говори Господ, јер те зваше отјераном: Сионом, којега нико не тражи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Овако вели Господ: ево, ја ћу повратити из ропства шаторе Јаковљеве и смиловаћу се на станове његове; и град ће се сазидати на мјесту свом, и двор ће стајати на свој начин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'И из њих ће излазити хвале и глас људи веселијех, јер ћу их умножити, и неће се умаљивати, и узвисићу их, и неће се понизити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'И синови ће његови бити као прије, и збор ће његов бити утврђен преда мном, и походићу све који му чине силу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'И кнез ће њихов бити од њих, и владалац ће њихов излазити исред њих; и даћу му да приступа, и приступаће к мени; јер ко је тај који се усуђује приступити к мени? говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'И бићете ми народ, и ја ћу вам бити Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Гле, вихор Господњи, гњев, изићи ће, вихор, који не престаје, пашће на главу безбожницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Неће се повратити жестоки гњев Господњи докле не учини и изврши што је наумио у срцу свом; напошљетку ћете разумјети то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'У то вријеме, говори Господ, ја ћу бити Бог свијем породицама Израиљевијем, и они ће ми бити народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Овако вели Господ: народ што оста од мача нађе милост у пустињи, кад иђах да дам одмор Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Одавна ми се јављаше Господ. Љубим те љубављу вјечном, зато ти једнако чиним милост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Опет ћу те сазидати, и бићеш сазидана, дјевојко Израиљева, опет ћеш се веселити бубњима својим, и излазићеш са збором играчким.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Опет ћеш садити винограде на брдима Самаријским, садиће виноградари и јешће род.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Јер ће доћи дан кад ће викати чувари на гори Јефремовој: устаните, да идемо на Сион, ка Господу Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Јер овако вели Господ: пјевајте весело ради Јакова, и подвикујте ради главе народима; јављајте, хвалите и говорите: спаси, Господе, народ свој, остатак Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Ево, ја ћу их довести из земље сјеверне, и сабраћу их с крајева земаљских, и слијепа и хрома, и трудну и породиљу, све заједно, збор велики вратиће се овамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Ићи ће плачући, и с молитвама ћу их довести натраг; водићу их покрај потока правијем путем, на ком се неће спотицати; јер сам отац Израиљу, и Јефрем је првенац мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Чујте, народи, ријеч Господњу, и јављајте по далеким острвима и реците: који расије Израиља, скупиће га, и чуваће га као пастир стадо своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Јер искупи Господ Јакова, и избави га из руку јачега од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'И доћи ће и пјеваће на висини Сионској, и стећи ће се к добру Господњем, к житу, к вину и к уљу, к јагањцима и теоцима; и душа ће им бити као врт заливен, и неће више тужити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Тада ће се веселити дјевојка у колу, и момци и старци заједно, и промијенићу жалост њихову на радост, и утјешићу их, и развеселићу их по жалости њиховој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'И напитаћу свештеницима душу претилином, и народ ће се мој наситити добра мојега, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Овако вели Господ: глас у Рами чу се, нарицање и плач велики; Рахиља плаче за дјецом својом, неће да се утјеши за дјецом својом, јер их нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Овако вели Господ: устави глас свој од плача и очи своје од суза, јер има плата дјелу твојему, говори Господ, и они ће се вратити из земље непријатељске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'И имаш нада за пошљедак, говори Господ, да ће се вратити синови твоји на међе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Чујем доиста Јефрема гдје тужи: покарао си ме, те сам покаран као јуне неуко; обрати ме да се обратим, јер си ти Господ Бог мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Јер пошто се обратих, покајах се; и пошто се научих, ударих се по бедру; јер се посрамих и стидим се што носим срамоту младости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Није ли ми Јефрем мио син? није ли дијете предраго? Откад говорих против њега, једнако га се опомињем; зато је срце моје устрептало њега ради, доиста ћу се смиловати на њ, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Подигни знаке, нанеси гомиле камења, запамти пут којим си ишла; врати се, дјевојко Израиљева, врати се у градове своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Докле ћеш лутати, кћери одметнице! јер је Господ учинио нешто ново на земљи: жена ће опколити човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Овако вели Господ над војскама, Бог Израиљев: још ћу ову ријеч говорити у земљи Јудиној и у градовима његовијем кад натраг доведем робље њихово: Господ да те благослови, стане правде, света горо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Јер ће се населити у њој Јуда, и сви градови његови, и ратари и који иду за стадом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Јер ћу напојити уморну душу, и наситити сваку клонулу душу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'У том се пробудих и погледах, и сан ми бјеше сладак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Ево иду дани, говори Господ, кад ћу засијати дом Израиљев и дом Јудин сјеменом човјечијим и сјеменом од стоке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'И као што сам пазио на њих да их истријебљујем и разваљујем, и кварим и затирем и мучим, тако ћу пазити на њих да их сазидам и посадим, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'У те дане неће се више говорити: оци једоше кисело грожђе, а синовима трну зуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Него ће сваки за свој гријех погинути; ко год једе кисело грожђе, томе ће зуби трнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Ево, иду дани, говори Господ, кад ћу учинити с домом Израиљевијем и с домом Јудинијем нов завјет,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Не као онај завјет који учиних с оцима њиховијем, кад их узех за руку да их изведем из земље Мисирске, јер онај завјет мој они покварише, а ја им бијах муж, говори Господ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Него ово је завјет што ћу учинити с домом Израиљевијем послије овијех дана, говори Господ: метнућу закон свој у њих, и на срцу њихову написаћу га, и бићу им Бог и они ће ми бити народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'И неће више учити пријатељ пријатеља ни брат брата говорећи: познајте Господа; јер ће ме знати сви од малога до великога, говори Господ; јер ћу им опростити безакоња њихова, и гријеха њиховијех нећу више помињати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Овако вели Господ, који даје сунце да свијетли дању, и уредбе мјесецу и звијездама да свијетле ноћу, који раскида море и буче вали његови, којему је име Господ над војскама:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Ако тијех уредаба нестане испред мене, говори Господ, и сјеме ће Израиљево престати бити народ преда мном навијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Овако вели Господ: ако се може измјерити небо горе и извидјети темељи земаљски доље, тада ћу и ја одбацити све сјеме Израиљево за све што су учинили, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Ево иду дани, говори Господ, у које ће се сазидати Господу овај град од куле Ананеилове до врата на углу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'И још ће даље отићи уже мјерачко до хума Гарива и обрнуће се на Гоат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'И сва долина од мртвијех тјелеса и пепела, и сва поља дори до потока Кедрона, до угла коњских врата к истоку, биће светиња Господу; неће се развалити ни потрти довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Ријеч која дође Јеремији од Господа десете године Седекије цара Јудина, које је осамнаеста година Навуходоносорова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'А тада војска цара Вавилонскога бјеше опколила Јерусалим, и пророк Јеремија бијаше затворен у тријему од тамнице, која бијаше у двору цара Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Јер га затвори Седекија цар Јудин говорећи: зашто да пророкујеш говорећи: овако вели Господ: ево, ја ћу предати тај град у руке цару Вавилонском и узеће га?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'И Седекија цар Јудин неће утећи из руку Халдејских, него ће зацијело бити предан у руке цару Вавилонском, и уста ће овога говорити с устима онога, очи ће се овога видјети с очима онога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'И одвешће Седекију у Вавилон, те ће остати ондје докле га не походим, говори Господ; ако се бијете с Халдејцима, нећете бити срећни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Рече дакле Јеремија: дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Ево, Анамеило син Салума стрица твојега иде к теби да ти каже: купи њиву моју што је у Анатоту, јер ти имаш по сродству право да је купиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'И дође к мени Анамеило син стрица мојега по ријечи Господњој у тријем од тамнице, и рече ми: хајде купи моју њиву што је у Анатоту у земљи Венијаминовој, јер теби припада по нашљедству и ти имаш право откупити је; купи. И разумјех да је ријеч Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'И купих од Анамеила сина стрица својега ту њиву која је у Анатоту, и измјерих му новце, седамнаест сикала сребра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'И написах књигу, и запечатих, и узех свједоке измјерив новце на мјеру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'И узех књигу о куповини запечаћену по закону и уредбама, и отворену,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'И дадох књигу о куповини Варуху сину Нирије сина Масијина пред Анамеилом братучедом својим и пред свједоцима који се потписаше на књизи о куповини и пред свијем Јудејцима који сијеђаху у тријему од тамнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'И заповједих Варуху пред њима говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Овако вели Господ над војскама Бог Израиљев: узми ову књигу, књигу о куповини, запечаћену и ову књигу отворену, и метни их у земљан суд да остану дуго времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Јер овако вели Господ над војскама Бог Израиљев: још ће се куповати куће и њиве и виногради у овој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'И давши књигу о куповини Варуху сину Ниријину, помолих се Господу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ах, Господе Господе! ето, ти си створио небо и земљу силом својом великом и мишицом својом подигнутом; ништа није теби тешко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Чиниш милост на тисућама, и враћаш за безакоње отачко у њедра синовима њиховијем након њих; Боже велики, силни, којему је име Господ над војскама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'Велики у намјерама и силни у дјелима; јер су очи твоје отворене на све путове људске да даш свакоме према путовима његовијем и према плоду дјела његовијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Који си чинио знаке и чудеса до данас у земљи Мисирској и у Израиљу и међу свијем људима, и стекао си себи име како је данас;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Јер си извео народ свој Израиља из земље Мисирске знацима и чудесима и руком крјепком и мишицом подигнутом и страхотом великом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'И дао си им ову земљу, за коју се закле оцима њиховијем да ћеш им је дати, земљу гдје тече млијеко и мед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Али ушавши у њу и наслиједивши је не послушаше гласа твојега, и по твом закону не ходише, и што си им год заповједио да чине, не чинише, зато си учинио те их снађе све ово зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Ево, опкопи дођоше до града да га узму; и од мача и глади и помора град ће се дати у руке Халдејцима који га бију; и што си год рекао, збива се, ето видиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'А ти ми велиш, Господе, Господе: купи ту њиву за новце и узми свједоке, а град се предаје у руке Халдејцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Тада дође ријеч Господња Јеремији говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Гле, ја сам Господ Бог свакога тијела, еда ли је мени што тешко?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Зато овако вели Господ: ево ја дајем тај град у руке Халдејцима и у руке Навуходоносору цару Вавилонском да га узме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'И Халдејци који бију тај град ући ће у њ, и упалиће огњем тај град и спалиће га и куће гдје на крововима кадише Валу и љеваше наљеве боговима другим да би ме разгњевили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Јер синови Израиљеви и синови Јудини чинише од дјетињства својега само што је зло преда мном, и синови Израиљеви само ме гњевише дјелима руку својих, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Јер тај град бјеше ми на гњев и на срдњу откад га сазидаше до данас да бих га одбацио испред себе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'За све зло синова Израиљевијех и синова Јудинијех што чинише гњевећи ме, они, цареви њихови, кнезови њихови, свештеници њихови и пророци њихови, Јудејци и Јерусалимљани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'И окренуше ми леђа а не лице; и кад их учах зарана једнако, не послушаше да би примили науку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Него метнуше своје гадове у дом који се зове мојим именом и оскврнише га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'И саградише висине Валу што су у долини сина Еномова да воде синове своје и кћери своје Молоху, што им ја не заповједих нити ми дође на ум, да би чинили тај гад, и тако Јуду наводили на гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Али зато опет овако вели Господ Бог Израиљев за тај град за који велите да ће се дати у руке цару Вавилонском од мача и глади и помора:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Ево, ја ћу их сабрати из свијех земаља у које их разагнах у гњеву свом и у јарости својој и у великој љутини, и довешћу их опет на ово мјесто и учинити да наставају без страха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'И биће ми народ и ја ћу им бити Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'И даћу им једно срце и један пут да би ме се бојали вазда на добро своје и синова својих након њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'И учинићу с њима завјет вјечан да се нећу одвратити од њих чинећи им добро, и даћу им страх свој у срце да не отступе од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'И радоваћу им се чинећи им добро и засадићу их у овој земљи тврдо свијем срцем својим и свом душом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Јер овако вели Господ: као што сам довео на тај народ све ово зло велико, тако ћу довести на њих све добро које им обричем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Тада ће се куповати њиве у овој земљи, за коју ви кажете да је пуста и да нема у њој ни живинчета и да је дана у руке Халдејцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Куповаће њиве за новце, и писаће књиге и печатити и узимати свједоке у земљи Венијаминовој и по околини Јерусалимској и у градовима Јудинијем и у градовима по горама и у градовима по равници и у градовима јужнијем, јер ћу повратити робље њихово, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'И дође ријеч Господња Јеремији други пут док још бијаше затворен у тријему од тамнице, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Овако вели Господ који чини то, Господ који удешава и потврђује то, којему је име Господ:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Зови ме, и одазваћу ти се, и казаћу ти велике и тајне ствари, за које не знаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Јер овако вели Господ Бог Израиљев за домове овога града и за домове царева Јудинијех који ће се развалити опкопима и мачем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'И за оне који дођоше да се бију с Халдејцима, али ће их напунити мртвијем тјелесима људи које ћу побити у гњеву свом и у јарости својој одвратив лице своје од тога града за сву злоћу њихову:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Ево, ја ћу га исцијелити и здравље му дати, исцијелићу их и показаћу им обиље мира, постојанога мира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Јер ћу повратити робље Јудино и робље Израиљево, и сазидаћу их као прије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'И очистићу их од свакога безакоња њихова којим ми сагријешише, и опростићу им сва безакоња њихова, којима ми сагријешише и којима се одметнуше од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'И биће ми мило име и хвала и слава у свијех народа на земљи који ће чути за све добро што ћу им учинити, и уплашиће се и дрктаће ради свега добра и ради свега мира што ћу им ја дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Овако вели Господ: на овом мјесту, за које ви велите да је пусто и нема у њему ни човјека ни живинчета, у градовима Јудинијем и по улицама Јерусалимским опустјелим да нема човјека ни становника ни живинчета опет ће се чути');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'Глас радостан и глас весео, глас жеников и глас невјестин, глас онијех који ће говорити: славите Господа над војскама, јер је добар Господ, јер је довијека милост његова; који ће приносити приносе захвалне у дому Господњем; јер ћу вратити робље ове земље као што је било прије, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Овако вели Господ над војскама: на овом мјесту пустом, гдје нема човјека ни живинчета, и у свијем градовима његовијем опет ће бити торови пастирски да почивају стада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'У градовима по горама, у градовима по равници и у градовима јужнијем и у земљи Венијаминовој и око Јерусалима и по градовима Јудинијем опет ће пролазити стада испод руку бројачевијех, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Ево, иду дани, говори Господ, кад ћу извршити ову добру ријеч коју рекох за дом Израиљев и за дом Јудин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'У те дане и у то вријеме учинићу да проклија Давиду клица права, која ће чинити суд и правду на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'У те дане спашће се Јуда, и Јерусалим ће стајати без страха, и зваће се: Господ правда наша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Јер овако вели Господ: неће нестати Давиду човјека који би сједио на пријестолу дома Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Ни свештеницима Левитима неће нестати преда мном човјека који би приносио жртву паљеницу и палио дар и клао жртву довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Потом дође ријеч Господња Јеремији говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Овако вели Господ: ако можете укинути завјет мој за дан и завјет мој за ноћ да не буде дана ни ноћи на вријеме,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'Онда ће се укинути и мој завјет с Давидом слугом мојим, да нема сина који би царовао на пријестолу његову, и с Левитима свештеницима слугама мојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Као што се не може избројити војска небеска ни измјерити пијесак морски, тако ћу умножити сјеме Давида слуге својега и Левита слуга својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Опет дође ријеч Господња Јеремији говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Нијеси ли видио што рече тај народ говорећи: двије породице, које бјеше изабрао Господ, одбаци их? И руже мој народ као да већ није народ пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Овако вели Господ: ако нијесам поставио завјета својега за дан и за ноћ и уредбе небесима и земљи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'Онда ћу и сјеме Јаковљево и Давида слуге својега одбацити да не узимам од сјемена његова онијех који ће владати сјеменом Аврамовијем, Исаковијем и Јаковљевијем; јер ћу повратити робље њихово и смиловаћу се на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Ријеч која дође Јеремији од Господа, кад Навуходоносор цар Вавилонски и сва војска његова, и сва царства земаљска која бијаху под његовом влашћу, и сви народи војеваху на Јерусалим и на све градове његове, и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Овако вели Господ Бог Израиљев: иди и кажи Седекији цару Јудину и реци му: овако вели Господ: ево, ја ћу предати тај град у руке цару Вавилонском, и он ће га спалити огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'А ти нећеш утећи из његове руке, него ћеш бити ухваћен и предан у његове руке, и очи ће се твоје видјети с очима цара Вавилонскога и његова ће уста говорити с твојим устима, и отићи ћеш у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Али чуј ријеч Господњу, Седекија царе Јудин; овако вели Господ за те: нећеш погинути од мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Него ћеш умријети на миру, и као што палише оцима твојима, пређашњим царевима, који су били прије тебе, тако ће палити и теби, и нарицаће за тобом: јаох господару! јер ја рекох ово, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'И каза Јеремија пророк Седекији цару Јудину све ове ријечи у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'А војска цара Вавилонскога удараше на Јерусалим и на све остале градове Јудине, на Лахис и Азику, јер ти бјеху остали тврди градови између градова Јудинијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Ријеч која дође Јеремији од Господа кад цар Седекија учини завјет са свијем народом који бјеше у Јерусалиму да им прогласи слободу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'Да сваки отпусти слободна роба својега и робињу своју, Јеврејина и Јеврејку, да ни у кога не буде роб Јудејац брат његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'И послушаше сви књезови и сав народ, који приста на завјет, да сваки отпусти слободна роба својега и робињу своју, да им не буду више робови, послушаше и отпустише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'А послије опет сташе узимати робове и робиње, које бијаху отпустили на вољу, и нагонише их да им буду робови и робиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'И дође ријеч Господња Јеремији од Господа говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Овако вели Господ Бог Израиљев: ја учиних завјет с оцима вашим кад вас изведох из земље Мисирске, из дома ропскога, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Кад се свршује седма година, отпуштајте сваки брата својега Јеврејина који ти се буде продао и служио ти шест година, отпусти га слободна од себе. Али не послушаше ме оци ваши нити пригнуше уха својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'И ви се бјесте сада обратили и учинили што је право преда мном прогласивши слободу сваки ближњему својему, учинивши завјет преда мном у дому који се зове мојим именом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Али ударисте натраг и погрдисте име моје узевши опет сваки роба својега и робињу своју, које бијасте отпустили слободне на њихову вољу, и натјерасте их да вам буду робови и робиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Зато овако вели Господ: ви не послушасте мене да прогласите слободу сваки брату својему и ближњему својему; ево, ја проглашујем слободу супрот вама, говори Господ, мачу, помору и глади, и предаћу вас да се потуцате по свијем царствима земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'И предаћу људе који преступише мој завјет, који не извршише ријечи завјета који учинише преда мном, расјекавши теле на двоје и прошавши између половина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Кнезове Јудине и кнезове Јерусалимске, дворане и свештенике и сав народ ове земље, који прођоше између половина онога телета,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Предаћу их у руке непријатељима њиховијем и у руке онима који траже душу њихову, и мртва ће тијела њихова бити храна птицама небеским и звијерима земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'И Седекију цара Јудина и кнезове његове предаћу у руке непријатељима њиховијем и у руке онима који траже душу њихову, у руке војсци цара Вавилонскога, која се вратила од вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Ево, ја ћу им заповједити, вели Господ, и довешћу их опет на овај град, и биће га и узеће га и спалиће га огњем; и градове Јудине обратићу у пустош да нико неће становати у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Ријеч која дође Јеремији од Господа у вријеме Јоакима сина Јосијина цара Јудина, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Иди к дому синова Рихавовијех и говори с њима, те их доведи у дом Господњи, у коју клијет, и подај им вина нека пију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Тада узех Јазанију сина Јеремије сина Ховасијина и браћу његову и све синове и сав дом синова Рихавовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'И доведох их у дом Господњи, у клијет синова Анана сина Игдалијина човјека Божијега, која је до клијети кнезовске, над клијећу Масије сина Салумова, вратара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'И метнух пред синове дома Рихавова крчаге пуне вина, и чаше, па им рекох: пијте вино.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'А они рекоше: нећемо пити вина, јер Јонадав, син Рихавов, отац наш забранио нам је рекавши: не пијте вина, ни ви ни синови ваши довијека;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'И куће не градите, ни сјемена сијте, ни винограда садите нити га држите, него у шаторима живите свега вијека својега, да бисте дуго живјели на земљи, гдје сте дошљаци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'И послушасмо глас Јонадава сина Рихавова оца својега у свему што нам заповиједи да не пијемо вина свега вијека својега, ни ми ни наше жене, ни синови наши ни кћери наше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'Ни да градимо кућа да у њима живимо, ни да имамо винограда ни њиве ни усјева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Него живимо у шаторима, и слушамо и чинимо све како нам је заповједио Јонадав отац наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'А кад дође Навуходоносор цар Вавилонски у ову земљу, рекосмо: хајде да отидемо у Јерусалим испред војске Халдејске и војске Сирске; и тако остасмо у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Тада дође ријеч Господња Јеремији говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Овако вели Господ над војскама Бог Израиљев: иди реци Јудејцима и Јерусалимљанима: зар нећете да примите науке да слушате ријечи моје? говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Извршују се ријечи Јонадава сина Рихавова, који забрани синовима својим да не пију вина, и не пију вина до данас, него слушају заповијест оца својега; а ја вам говорих зарана једнако, а ви ме не послушасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'И слах к вама све слуге своје пророке зарана једнако говорећи: вратите се сваки са свога пута злога, и поправите дјела своја и не идите за другим боговима служећи им, пак ћете остати у земљи коју сам дао вама и оцима вашим, али не пригнусте уха својега нити ме послушасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Да, синови Јонадава сина Рихавова извршују заповијест оца својега што им је заповиједио, а тај народ не слуша мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Зато овако вели Господ Бог над војскама, Бог Израиљев: ево, ја ћу пустити на Јуду и на све становнике Јерусалимске све зло што изрекох за њих; јер им говорих а они не послушаше, и звах их а они се не одазваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'А породици Рихавовој рече Јеремија: овако вели Господ над војскама Бог Израиљев: што слушате заповијест Јонадава оца својега и држите све заповијести његове и чините све како вам је заповиједио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'Зато овако вели Господ над војскама Бог Израиљев: неће нестати Јонадаву сину Рихавову човјека који би стајао преда мном довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'А четврте године Јоакима сина Јосијина цара Јудина дође ова ријеч Јеремији од Господа говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Узми књигу и напиши у њу све ријечи које сам ти рекао за Израиља и Јуду и за све народе, од када ти почех говорити, од времена Јосијина, до данас;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Еда би чуо дом Јудин све зло које им мислим учинити и вратио се свак са свога злога пута, да бих им опростио безакоње и гријех њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Тада Јеремија дозва Варуха сина Ниријина, и написа Варух у књигу из уста Јеремијиних све ријечи Господње које му говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Потом заповједи Јеремија Варуху говорећи: мени није слободно, те не могу отићи у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Него иди ти, и прочитај из књиге коју си написао из мојих уста, ријечи Господње, народу у дому Господњем у дан посни, и свијем Јудејцима који дођу из градова својих прочитај;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Не би ли молећи се припали ка Господу и вратили се сваки са својега пута злога, јер је велик гњев и јарост што је Господ изрекао за тај народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'И учини Варух син Ниријин све како му заповједи пророк Јеремија, и прочита из књиге ријечи Господње у дому Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'А пете године Јоакима сина Јосијина цара Јудина мјесеца деветога огласише пост пред Господом свему народу Јерусалимском и свему народу који дође из градова Јудинијех у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'И прочита Варух из књиге ријечи Јеремијине у дому Господњем, у клијети Гемарије сина Сафанова писара, у горњем тријему код новијех врата дома Господњега пред свијем народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'А кад чу Михеј син Гемарије сина Сафанова све ријечи Господње из књиге,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'Он сиђе у дом царев у клијет писареву, и гле, ондје сјеђаху сви кнезови, Елисама писар, и Делаја син Семајин, и Елнатан син Ахворов, и Гемарија син Сафанов, и Седекија син Ананијин, и сви кнезови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'И каза им Михеј све ријечи што чу кад Варух читаше књигу народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Тада сви кнезови послаше к Варуху Јудија сина Натаније сина Селемије сина Хусијева, и поручише му: књигу коју си читао народу узми у руку и дођи овамо. И узе књигу у руку Варух син Ниријин, и дође к њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'И они му рекоше: сједи и читај да чујемо. И Варух им је прочита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'А кад чуше све оне ријечи, сви се уплашише и рекоше Варуху: казаћемо цару све те ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'И запиташе Варуха говорећи: кажи нам како си написао све те ријечи из уста његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'А Варух им рече: из уста својих казива ми све те ријечи, а ја писах у књигу мастилом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Тада рекоше кнезови Варуху: иди, сакриј се и ти и Јеремија, да нико не зна гдје сте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Потом отидоше к цару у тријем оставивши књигу у клијети Елисаме писара, и казаше цару све те ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'А цар посла Јудија да донесе књигу; и донесе је из клијети Елисаме писара, и стаде читати Јудије пред царем и пред свијем кнезовима који стајаху око цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'А цар сјеђаше у зимној кући деветога мјесеца, и пред њим бијаше живо угљевље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'И кад Јудије прочита три четири листа, исијече је цар ножем писарским, и баци у огањ на жеравицу, те изгорје сва књига огњем на жеравици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Али се не уплашише, нити раздријеше хаљина својих цар нити који од слуга његовијех чувши све оне ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'И премда Елнатан и Делаја и Гемарија мољаху цара да не пали књиге, он их не послуша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Него заповједи цар Јерамеилу сину цареву и Сераји сину Азрилову и Селемији сину Авдилову да ухвате Варуха писара и Јеремију пророка; али их сакри Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'И дође ријеч Господња Јеремији, пошто цар сажеже књигу и ријечи које написа Варух из уста Јеремијиних, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Узми опет другу књигу, и напиши у њу све пређашње ријечи које бијаху у првој књизи, коју сажеже Јоаким цар Јудин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'А за Јоакима цара Јудина реци: овако вели Господ: ти си сажегао ону књигу говорећи: зашто си написао у њој и рекао: доћи ће цар Вавилонски и затрти ову земљу и истријебити из ње и људе и стоку?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Зато овако вели Господ за Јоакима цара Јудина: неће имати никога ко би сједио на пријестолу Давидову, и мртво ће тијело његово бити бачено на припеку обдан и на мраз обноћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Јер ћу походити њега и сјеме његово и слуге његове за безакоње њихово, и пустићу на њих и на становнике Јерусалимске и на Јудејце све зло, за које им говорих али не послушаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'И узе Јеремија другу књигу, и даде је Варуху сину Ниријину писару, а он написа у њу из уста Јеремијиних све ријечи што бијаху у оној књизи, коју сажеже Јоаким цар Јудин огњем; и још би додано к онијем много онаких ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Потом царова Седекија син Јосијин мјесто Хоније сина Јоакимова, којега постави царем у земљи Јудиној Навуходоносор цар Вавилонски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Али ни он ни слуге његове ни народ земаљски не слушаху ријечи Господњих које говораше преко Јеремије пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'И посла цар Седекија Јеухала сина Селемијина, и Софонију сина Масијина свештеника к Јеремији пророку, те му рекоше: помоли се за нас Господу Богу нашему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'И Јеремија иђаше међу народ и још га не бјеху метнули у тамницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'И војска Фароанова изиде из Мисира, а Халдејци који бијаху Јерусалим чувши глас о њој отидоше од Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'А ријеч Господња дође Јеремији пророку говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Овако вели Господ Бог Израиљев: овако реците цару Јудину, који вас је послао к мени да ме питате: ево војска Фараонова која пође вама у помоћ, вратиће се у своју земљу, у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'А Халдејци ће опет доћи и опколиће тај град и узеће га и спалиће га огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Овако вели Господ: не варајте се говорећи: отићи ће од нас Халдејци; јер неће отићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'И да побијете сву војску Халдејску, која ће се бити с вама, и да их остане неколико рањеника, и они ће устати из својих шатора и спалити тај град огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'А кад отиде војска Халдејска од Јерусалима ради војске Фараонове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Изиде Јеремија из Јерусалима да би отишао у земљу Венијаминову и уклонио се оданде међу народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Али кад бијаше на вратима Венијаминовијем, ондје бијаше старјешина стражарски по имену Јереја син Селемије сина Ананијина, те ухвати Јеремију пророка говорећи: ти бјежиш ка Халдејцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'А Јеремија рече: није истина, не бјежим ка Халдејцима. Али га не хтје слушати, него ухвати Јереја Јеремију и одведе ка кнезовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'А кнезови се разгњевише на Јеремију, и избише га, и метнуше га у тамницу у кући Јонатана писара, јер од ње бијаху начинили тамницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'А кад Јеремија уљезе у јаму, у тамницу, оста ондје дуго времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Потом посла цар Седекија, те га извади, и упита га у својој кући насамо, и рече му говорећи: има ли ријеч од Господа? А Јеремија рече: има. Још рече: бићеш предан у руке цару Вавилонскому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Потом рече Јеремија цару Седекији: шта сам ти скривио или слугама твојим или тому народу, те ме метнусте у тамницу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'И гдје су ваши пророци који вам пророкују говорећи: неће доћи цар Вавилонски на вас ни на ову земљу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Сада дакле послушај, царе господару мој, пусти преда се молбу моју, немој ме враћати у кућу Јонатана писара, да не умрем ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Тада заповједи цар Седекија да затворе Јеремију у тријем од тамнице и да му дају сваки дан по хљеб с улице хљебарске, докле траје хљеба у граду. Тако сјеђаше Јеремија у тријему од тамнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'А Сефатија син Матанов и Годолија син Пасхоров и Јухал син Селемијин и Пасхор син Малхијин чуше ријечи које говори Јеремија свему народу рекавши:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Овако вели Господ: ко остане у том граду, погинуће од мача, од глади или од помора; а ко отиде ка Халдејцима, остаће жив, и душа ће му његова бити мјесто плијена, и биће жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Овако вели Господ: доиста ће тај град бити предан у руке војсци цара Вавилонскога, и узеће га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'И рекоше кнезови цару: да се погуби тај човјек, јер он ослабљава руке војницима који осташе у овом граду, и руке свему народу говорећи им таке ријечи, јер тај човјек не тражи добра овом народу него зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'А цар Седекија рече: ето, у вашим је рукама; јер цар не може ништа супрот вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Тада узеше Јеремију, и бацише га у јаму Малхије сина Амелехова, која бијаше у тријему од тамнице, и спустише Јеремију о ужима; а у јами не бјеше воде, него глиб, и Јеремија се ували у глиб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Али кад чу Авдемелех Етиопљанин, дворанин, који бијаше у двору цареву, да су метнули Јеремију у ону јаму, а цар сјеђаше на вратима Венијаминовијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Изиде Авдемелех из двора царева и рече цару говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Царе господару мој, зло учинише ти људи у свему што учинише Јеремији пророку бацивши га у јаму, јер би и ондје гдје је био од глади умро, јер нема више хљеба у граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Зато цар заповједи Авдемелеху Етиопљанину говорећи: узми одавде тридесет људи и извади Јеремију пророка из јаме док није умро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Тада узе Авдемелех људе, и дође у дом царев под ризницу, и узе оданде изношенијех хаљина и старијех рита, и спусти их Јеремији у јаму о ужима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'И рече Авдемелех Етиопљанин Јеремији: подметни те старе хаљине и рите под пазуха испод ужа. И учини Јеремија тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'И извукоше Јеремију на ужима и извадише га из јаме; и оста Јеремија у тријему од тамнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Потом цар Седекија посла по Јеремију пророка, те га доведоше преда њ у трећи улазак који бијаше у дому Господњем; и рече цар Јеремији: запитаћу те нешто, немој ми затајити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'А Јеремија рече Седекији: да ти кажем, нећеш ли ме погубити? а да те свјетујем, нећеш ме послушати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Тада се цар Седекија закле Јеремији насамо говорећи: тако да је жив Господ, који нам је створио ову душу, нећу те погубити нити ћу те дати у руке људима који траже душу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Тада Јеремија рече Седекији: овако вели Господ Бог над војскама, Бог Израиљев: ако отидеш ка кнезовима цара Вавилонскога, жива ће остати душа твоја, и град овај неће изгорјети огњем, и тако ћеш остати у животу ти и дом твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Ако ли не отидеш ка кнезовима цара Вавилонскога, овај ће град бити предан у руке Халдејцима, који ће га спалити огњем, и ти нећеш утећи из руку њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'А цар Седекија рече Јеремији: ја се бојим Јудејаца који су пребјегли ка Халдејцима, да ме не предаду у њихове руке, те ће ми се наругати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'А Јеремија рече: неће те предати; послушај глас Господњи, који ти ја говорим, и добро ће ти бити и жива ће бити твоја душа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Ако ли нећеш да изидеш, ово је што ми показа Господ:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Гле, све жене које су остале у дому цара Јудина, одвешће се ка кнезовима цара Вавилонскога, и оне ће рећи: наговорише те и преварише те пријатељи твоји; ноге ти се увалише у глиб, а они се повукоше натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Све жене твоје и синови твоји одвешће се Халдејцима, и ти нећеш утећи из руку њиховијех; него ћеш допасти у руке цару Вавилонском, и овај ће град изгорјети огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Тада рече Седекија Јеремији: нико да не дозна за те ријечи, да не погинеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Ако ли кнезови чувши да сам говорио с тобом дођу к теби и реку ти: кажи нам шта си говори цару, немој тајити од нас, па те нећемо погубити, и шта је цар теби говорио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'Реци им: ја припадох к цару молећи се да ме не пошље натраг у дом Јонатанов да умрем ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'И дођоше сви кнезови к Јеремији и питаше га; а он им одговори сасвијем како му заповједи цар. И оканише га се, јер не дознаше ништа од тога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'А Јеремија оста у тријему од тамнице до дана кад узеше Јерусалим; и он бијаше ондје кад узеше Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Девете године Седекије цара Јудина мјесеца десетога дође Навуходоносор цар Вавилонски са свом војском својом на Јерусалим и стаде га бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'Једанаесте године Седекијине мјесеца четвртога, деветога дана тога мјесеца провалише у град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'И уђоше сви кнезови цара Вавилонскога, и стадоше код средњих врата Нергал-саресер, Самгарневон, Сарсехим, старјешина над дворанима, Нергал-саресер, старјешина над врачима, и сви други кнезови цара Вавилонскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'А кад их видје Седекија цар Јудин и сви војници, побјегоше и изидоше ноћу из града покрај врта царскога на врата међу два зида; и иђаху преко поља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'А војска Халдејска гоњаше их, и стиже Седекију у пољу Јерихонском, и ухвативши га доведоше га к Навуходоносору цару Вавилонском у Ривлу у земљи Ематској, те му суди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'И закла цар Вавилонски синове Седекијине у Ривли на његове очи, и све знатне људе од Јуде покла цар Вавилонски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Иза тога Седекији ископа очи, и свеза га у двоје вериге мједене, да га одведе у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'А дом царев и домове народне попалише Халдејци огњем, и зидове Јерусалимске раскопаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'А остатак народа што оста у граду и пребјеге који пребјегоше к њему, остатак народа што бјеше остао, одведе Невузардан заповједник стражарски у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Само најсиромашније из народа, који ништа немаху, остави Невузардан заповједник стражарски у земљи Јудиној, и даде им тада винограде и њиве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'А Навуходоносор цар Вавилонски заповједи за Јеремију Невузардану заповједнику стражарском говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Узми га и гледај га добро, и не чини му зла, него му чини што ти год каже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'И послаше Невузардан заповједник стражарски и Невусазван, старјешина над дворанима, и Нергал-саресер, старјешина над врачима, и сви кнезови цара Вавилонскога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'Послаше, те узеше Јеремију из тријема од тамнице, и предаше га Годолији сину Ахикама сина Сафанова да га одведе кући; тако оста међу народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'А Јеремији дође ријеч Господња кад бјеше затворен у тријему од тамнице говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Иди и реци Авдемелеху Етиопљанину говорећи: овако вели Господ над војскама Бог Израиљев: ево ја ћу учинити да се збуду ријечи моје томе граду на зло а не на добро, и навршиће се пред тобом у онај дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Али ћу тебе избавити у онај дан, говори Господ, и нећеш бити предан у руке људима којих се бојиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Јер ћу те доиста сачувати, те нећеш пасти од мача, и биће ти душа твоја мјесто плијена зато што си се поуздао у ме, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Ријеч која дође Јеремији од Господа кад га Невузардан заповједник стражарски пусти из Раме узевши га пошто бјеше окован у вериге међу свијем робљем Јерусалимски и Јудинијем, које се вођаше у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'И узевши заповједник стражарски Јеремију рече му: Господ Бог твој изрече ово зло за ово мјесто;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'И нанесе и учини како рече, јер згријешисте Господу и не слушасте гласа његова, зато вас снађе ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Али сада, ево, ја те опраштам данас верига што су ти на руку; ако ти је воља поћи са мном у Вавилон, ходи, ја ћу се бринути за те; ако ли ти није воља поћи са мном у Вавилон, а ти немој; ево, сва ти је земља отворена, иди куда год хоћеш и куда ти је драго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Или кад се он још не враћа, отиди к њему, Годолији сину Ахикама сина Сафанова, којега је поставио цар Вавилонски над градовима Јудинијем, и остани с њим међу народом, или иди куда ти је драго. И даде му заповједник стражарски брашњенице и дар, и отпусти га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'И тако дође Јеремија ка Годолији сину Ахикамову у Миспу, и оста с њим у народу, који још оста у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'А све војводе што бјеху у пољу и људи њихови кад чуше да је цар Вавилонски поставио Годолију сина Ахикамова над земљом, и да је на њему оставио људе и жене и дјецу између сиромашнога народа у земљи, који не би одведен у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Дођоше у Миспу ка Годолији Исмаило син Нетанијин и Јоанан и Јонатан синови Каријини, и Сераја син Тануметов, и синови Јофије Нетофаћанина, и Језанија син некога Махаћанина, они и људи њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'И закле се Годолија син Ахикама сина Сафанова њима и људима њиховијем говорећи: не бојте се службе Халдејцима; останите у земљи, и служите цару Вавилонском, и добро ће вам бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'А ја ево ћу стајати у Миспи да дочекујем Халдејце који ће долазити к нама; а ви берите винограде и воће и уље, и остављајте у судове своје, и стојте у градовима својим које држите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Тако и сви Јудејци, који бијаху међу Моавцима и синовима Амоновијем и Едомцима и по свијем земљама, чувши да је цар Вавилонски оставио остатак у Јудеји и поставио над њима Годолију сина Ахикама сина Сафанова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Вратише се сви Јудејци из свијех мјеста куда бијаху разагнани, и дођоше у земљу Јудину ка Годолији у Миспу, и набраше вина и воћа врло много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'А Јоанан син Каријин и све војводе што бјеху у пољу дођоше ка Годолији у Миспу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'И рекоше му: знаш ли да је Валис цар синова Амоновијех послао Исмаила сина Нетанијина да те убије? Али им не повјерова Годолија син Ахикамов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Тада Јоанан син Каријин рече Годолији насамо у Миспи говорећи: идем да убијем Исмаила сина Нетанијина, нико неће дознати. Зашто да те убије и да се расију сви Јудејци који су се скупили око тебе и да пропадне остатак Јудин?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Али Годолија син Ахикамов рече Јоанану сину Каријину: немој то чинити, јер није истина што кажеш за Исмаила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'А седмога мјесеца дође Исмаило син Нетаније сина Елисамина, царскога рода, и кнезови цареви, десет људи с њим, ка Годолији сину Ахикамову у Миспу, и једоше ондје у Миспи с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Потом уста Исмаило син Нетанијин и десет људи што бијаху с њим, и убише мачем Годолију сина Ахикама сина Сафанова; тако погубише онога кога бјеше поставио цар Вавилонски над земљом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'И све Јудејце који бијаху с њим, с Годолијом, у Миспи, и Халдејце који се затекоше ондје, војнике, поби Исмаило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'А сјутрадан пошто уби Годолију, док још нико не дозна,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Дођоше људи из Сихема, из Силома и из Самарије, осамдесет људи, обријане браде и раздртијех хаљина и испарани по тијелу, и имаху у рукама дар и кад, да принесу у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Тада Исмаило син Нетанијин изиде им на сусрет из Миспе и иђаше плачући, и сретавши се с њима рече им: ходите ка Годолији сину Ахикамову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'А кад дођоше усред града, покла их Исмаило син Нетанијин с људима који бијаху с њим и баци их у јаму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'А међу њима се нађе десет људи који рекоше Исмаилу: немој нас погубити, јер имамо сакривено благо у пољу, пшенице и јечма и уља и меда. И остави их, и не поби их с браћом њиховом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'А јама у коју побаца Исмаило сва тјелеса људи које поби уз Годолију бијаше она коју начини цар Аса бојећи се Васе цара Израиљева; и Исмаило син Нетанијин напуни је побијенијех људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'И зароби Исмаило сав остатак народа што бијаше у Миспи, кћери цареве и сав народ што бјеше остао у Миспи, над којим бјеше поставио Невузардан заповједник стражарски Годолију сина Ахикамова; и заробивши их Исмаило син Нетанијин пође да пријеђе к синовима Амоновијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Али Јоанан син Каријин и све војводе што бијаху с њим чуше све зло што учини Исмаило син Нетанијин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'Тада узеше све своје људе и пођоше да ударе на Исмаила сина Нетанијина, којега нађоше код велике воде у Гаваону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'И сав народ што бјеше с Исмаилом кад видје Јоанана сина Каријина и све војводе што бјеху с њим, обрадова се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'И сав народ што Исмаило зароби из Миспе обрну се и отиде к Јоанану сину Каријину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'А Исмаило син Нетанијин побјеже с осам људи од Јоанана, и отиде к синовима Амоновијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'И тако Јоанан син Каријин и све војводе што бијаху с њим узеше сав остатак народа што повратише од Исмаила сина Нетанијина, који убив Годолију сина Ахикамова бјеше их одвео из Миспе, војнике и жене и дјецу и дворане, и одведоше их из Гаваона;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'И отишавши стадоше у гостионици Химамовој код Витлејема, да би отишли и прешли у Мисир,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'Ради Халдејаца, јер их се бојаху, што Исмаило син Нетанијин уби Годолију сина Ахикамова, којега бјеше поставио цар Вавилонски над земљом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Потом дођоше све војводе и Јоанан син Каријин и Језанија син Осајин, и сав народ, мало и велико,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'И рекоше Јеремији пророку: пусти преда се нашу молбу, и помоли се за нас Господу Богу својему, за сав овај остатак, јер нас је остало мало од многих, као што нас очи твоје виде,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Да би нам показао Господ Бог твој пут којим ћемо ићи и шта ћемо радити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'А Јеремија пророк рече им: послушаћу; ево, помолићу се Господу Богу вашему по вашим ријечима, и што вам одговори Господ казаћу вам, нећу вам затајити ни ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'А они рекоше Јеремији: Господ нека нам је свједок истинит и вјеран да ћемо чинити све што ти Господ Бог твој заповједи за нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Било добро или зло, послушаћемо ријеч Господа Бога својега ка којему те шаљемо, да би нам добро било кад послушамо глас Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'А послије десет дана дође ријеч Господња Јеремији;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Те сазва Јоанана сина Каријина и све војводе што бијаху с њим, и сав народ, мало и велико,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'И рече им: овако вели Господ Бог Израиљев, ка којему ме посласте да изнесем преда њ молбу вашу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Ако останете у овој земљи, сазидаћу вас, и нећу вас разорити, и насадићу вас и нећу вас истријебити; јер ми је жао са зла које сам вам учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Не бојте се цара Вавилонскога, којега се бојите; не бојте га се, говори Господ, јер сам ја с вама да вас сачувам и да вас избавим из његове руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'И учинићу вам милост да се смилује на вас, и врати вас у земљу вашу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Ако ли речете: нећемо да останемо у тој земљи, не слушајући гласа Господа Бога својега');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'Говорећи: не, него идемо у земљу Мисирску, да не видимо рата и гласа трубнога не чујемо и не будемо гладни хљеба, и ондје ћемо се населити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'Онда чујте ријеч Господњу, који сте остали од Јуде; овако вели Господ над војскама Бог Израиљев: ако ви окренете лице своје да идете у Мисир и отидете да се населите ондје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'Ондје ће вас у земљи Мисирској стигнути мач којега се бојите, и глад, ради које се бринете, гониће вас ондје у Мисиру и ондје ћете помријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'И сви људи који су окренули лице своје да иду у Мисир да се ондје населе, изгинуће од мача и од глади и од помора, и ни један их неће остати нити ће који утећи од зла које ћу пустити на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Јер овако вели Господ над војскама Бог Израиљев: као што се гњев мој и јарост моја изли на становнике Јерусалимске, тако ће се излити гњев мој на вас, ако отидете у Мисир, и бићете уклин и чудо и клетва и руг, и нећете више видјети овога мјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Господ вам говори, останци Јудини! не идите у Мисир. Знајте да вам ја свједочим данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Јер варасте душе своје кад ме посласте ка Господу Богу својему рекавши: помоли се за нас Господу Богу нашему, и како рече Господ Бог наш, јави нам и учинићемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'А кад вам јавих данас, нећете да послушате гласа Господа Бога својега нити ишта што ми заповједи за вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Знајте дакле да ћете изгинути од мача и од глади и од помора на мјесту куда сте ради отићи да се станите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'А кад изговори Јеремија свему народу све ријечи Господа Бога њихова, које му Господ Бог њихов заповједи за њих, све те ријечи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Тада Азарија син Осајин и Јоанан син Каријин и сви они људи охоли рекоше Јеремији говорећи: није истина што говориш; није те послао Господ Бог наш да нам кажеш: не идите у Мисир да се ондје станите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Него Варух син Ниријин подговара те на нас да нас преда у руке Халдејцима да нас погубе или да нас преселе у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'И тако Јоанан син Каријин и све војводе и сав народ не послушаше гласа Господњега да остану у земљи Јудиној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Него Јоанан син Каријин и све војводе узеше сав остатак Јудин који се бијаше вратио да живи у земљи Јудиној из свијех народа у које бијаху разагнани,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Људе и жене и дјецу и кћери цареве, и све душе што бијаше оставио Невузардан заповједник стражарски с Годолијом сином Ахикама сина Сафанова, и Јеремију пророка и Варуха сина Ниријина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'И отидоше у земљу Мисирску, јер не послушаше гласа Господњега; и дођоше до Тафнеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'И дође ријеч Господња Јеремији у Тафнесу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Узми у руке великога камења, и покриј га калом у пећи за опеке што је на вратима дома Фараонова у Тафнесу да виде Јудејци;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'И реци им: овако вели Господ над војскама Бог Израиљев: ево, ја ћу послати и довести Навуходоносора цара Вавилонскога слугу својега, и метнућу пријесто његов на ово камење које сакрих, и разапеће царски шатор свој на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Јер ће доћи и затрти земљу Мисирску; ко буде за смрт отићи ће на смрт, ко за ропство, у ропство, ко за мач, под мач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'И распалићу огањ у кућама богова Мисирских; и попалиће их и одвешће их у ропство, и огрнуће се земљом Мисирском као што се пастир огрће плаштем својим, и отићи ће оданде с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'И изломиће ступове у дому сунчаном што је у земљи Мисирској, и куће богова Мисирских попалиће огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Ријеч која дође Јеремији за све Јудејце који живљаху у земљи Мисирској, који живљаху у Мигдолу и у Тафнесу и у Нофу и у земљи Патросу, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Овако вели Господ над војскама Бог Израиљев: ви видјесте све зло што наведох на Јерусалим и на све градове Јудине, и ево су данас пусти и нема никога да живи у њима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'За злоћу њихову коју чинише да би ме гњевили ходећи да каде и служе другим боговима, којих не знаше ни они ни ви ни оци ваши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'И слах к вама све слуге своје пророке зарана једнако говорећи: не чините тога гада, на који мрзим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Али не послушаше нити пригнуше уха својега да се врате од злоће своје, да не каде другим боговима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Зато се изли јарост моја и гњев мој, и разгорје се у градовима Јудинијем и по улицама Јерусалимским, те посташе развалине и пустош, као што се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'А сада овако вели Господ Бог над војскама, Бог Израиљев: зашто сами себи чините тако велико зло да истријебите из Јуде људе и жене, дјецу и која сисају, да не остане у вас остатка,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Гњевећи ме дјелима руку својих, кадећи другим боговима у земљи Мисирској, у коју дођосте да се станите да бисте се истријебили и постали клетва и руг у свијех народа на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Јесте ли заборавили зла отаца својих и зла царева Јудинијех и зла жена њиховијех, и своја зла и зла жена својих, која чинише у земљи Јудиној и по улицама Јерусалимским?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Не покорише се до данас нити се побојаше, нити ходише по мом закону и уредбама мојим, које ставих пред вас и пред оце ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Зато овако вели Господ над војскама Бог Израиљев: ево, ја ћу вам обратити лице своје на зло, да истријебим све Јудејце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'И узећу остатак Јудин, који окрену лице своје да иде у земљу Мисирску да се ондје стани, и изгинуће сви; у земљи ће Мисирској пасти и изгинути од мача и од глади, мало и велико, изгинуће од мача и од глади, и биће уклин и чудо и проклетство и руг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'И походићу оне који наставају у земљи Мисирској, као што сам походио Јерусалим, мачем, глађу и помором;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'И ниједан од остатка Јудина, што отидоше у земљу Мисирску да се ондје стане, неће утећи нити се избавити да се врате у земљу Јудину, у коју се желе вратити да се населе; јер се неће вратити, осим који побјегну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Тада одговорише Јеремији сви људи који знађаху да жене њихове каде другим боговима, и све жене, којих стајаше ондје велик збор, и сав народ што живљаше у земљи Мисирској, у Патросу, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Што нам каза у име Господње, нећемо те послушати;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Него ћемо чинити све што је изашло из наших уста кадећи царици небеској и љевајући јој наљеве, као што смо чинили ми и оци наши, цареви наши и кнезови наши по градовима Јудинијем и по улицама Јерусалимским, јер бијасмо сити хљеба и бијаше нам добро и зла не виђасмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'А од кад престасмо кадити царици небеској и љевати јој наљеве, ништа немамо и гинемо од мача и од глади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'И кад кадимо царици небеској и љевамо јој наљеве, еда ли јој без главара својих печемо колаче служећи јој и љевамо јој наљеве?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Тада рече Јеремија свему народу, људима и женама, и свему народу, који му онако одговорише, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Еда ли се не опомену Господ када, којим кадисте у градовима Јудинијем и по улицама Јерусалимском ви и оци ваши, цареви ваши и кнезови ваши и народ земаљски? и не дође ли му у срце?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'И не може Господ више подносити злоће дјела ваших и гадова које чинисте, те земља ваша поста пустош и чудо и проклетство, да нико не живи у њој, како се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Зато што кадисте и што гријешисте Господу и не слушасте гласа Господњега, и по закону његову и уредбама његовијем и свједочанствима његовијем не ходисте, зато вас задеси ово зло, како се види данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Још рече Јеремија свему народу и свијем женама: чујте ријеч Господњу, сви Јудејци, који сте у земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Овако вели Господ над војскама Бог Израиљев говорећи: ви и жене ваше рекосте устима својим и рукама својим извршисте говорећи: извршиваћемо завјете своје што завјетовасмо кадећи царици небеској и љевајући јој наљеве. Доиста испунисте завјете своје и извршисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Зато чујте Јудејци ријеч Господњу, сви Јудејци који станујете у земљи Мисирској: ево, ја се заклињем великим именом својим, вели Господ, да се име моје неће више изрицати устима ниједнога Јудејца у свој земљи Мисирској да би рекао: тако да је жив Господ Господ!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Ево, ја ћу пазити на њих зла ради, не добра ради, и Јудејци који су у земљи Мисирској сви ће гинути од мача и од глади, докле их не буде ниједнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'А који утеку од мача, вратиће се из земље Мисирске у земљу Јудину, мало њих, јер сав остатак Јудин, што отидоше у земљу Мисирску да се ондје настане, познаће чија ће се ријеч навршити, моја или њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'А ово да вам је знак, говори Господ, да ћу вас походити на том мјесту да знате да ће се доиста испунити ријечи моје вама на зло;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Овако вели Господ: ево, ја ћу дати Фараона Вафрија цара Мисирскога у руке непријатељима његовијем и у руке онијем који траже душу његову, као што сам дао Седекију цара Јудина у руке Навуходоносору цару Вавилонском, непријатељу његову и који тражаше душу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Ријеч коју рече Јеремија пророк Варуху сину Ниријину, кад писаше ове ријечи у књигу из уста Јеремијинијех, четврте године Јоакима сина Јосијина, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Овако вели Господ Бог израиљев за тебе, Варуше:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Рекао си: тешко мени! јер Господ додаде ми жалост на тугу; изнемогох уздишући, и мира не налазим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Реци му ово: овако вели Господ: ево, што сам саградио ја разграђујем, и што сам посадио искорењавам по свој тој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'А ти ли ћеш тражити себи велике ствари? Не тражи; јер ево, ја ћу пустити зло на свако тијело, говори Господ; али ћу теби дати душу твоју мјесто плијена у свијем мјестима, куда отидеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Ријеч Господња која дође Јеремији пророку за народе:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'За Мисирце, за војску Фараона Нехаона цара Мисирскога, која бијаше на реци Ефрату код Харкемиса, и разби је Навуходоносор цар Вавилонски четврте године Јоакима сина Јосијина цара Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Приправите штите и штитиће, и идите у бој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Прежите коње, и појашите, коњици; поставите се са шљемовима; утрите копља, облачите се у оклопе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Зашто их видим гдје се поплашише, враћају се натраг, јунаци њихови поломише се и бјеже без обзира? Страх је отсвуда, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Да не утече лаки, нити се избави јаки; да се на сјеверу на бријегу ријеке Ефрата спотакну и падну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Ко је то што се диже као поток, и воде му се колебају као ријеке?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Мисир се диже као поток и његове се воде колебају као ријеке; и вели: идем, покрићу земљу, затрћу град и оне који живе у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Излазите, коњи, бјесните, кола; и нека изађу јунаци, Хуси и Фуди, који носе штитове, и Лудеји, који носе и натежу лук.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Јер је овај дан Господу Господу над војскама дан освете, да се освети непријатељима својим; мач ће их прождријети и наситиће се и опиће се крвљу њиховом; јер ће бити жртва Господа Господа над војскама у земљи сјеверној на ријеци Ефрату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Изиди у Галад и узми балсама, дјевојко кћери Мисирска; залуду су ти многи лијекови, нећеш се излијечити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Народи чуше срамоту твоју, и вике твоје пуна је земља, јер се спотичу јунак о јунака, те обојица падају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Ријеч коју рече Господ Јеремији пророку о доласку Навуходоносора цара Вавилонскога да потре земљу Мисирску:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Јавите у Мисиру, и огласите у Мигдолу, огласите и у Нофу и у Тафнесу, и реците: стани и приправи се, јер мач прождрије што је око тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Зашто се поваљаше јунаци твоји? Не стоје, јер их Господ обара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Чини, те се многи спотичу и падају један на другога, и говоре: устани да се вратимо к народу својему и на постојбину своју испред мача насилникова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Вичу ондје: Фараон цар Мисирски пропаде, прође му рок.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Тако да сам ја жив, говори цар, којему је име Господ над војскама; као Тавор међу горама и као Кармил на мору доћи ће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Спреми што ти треба да се селиш, становнице, кћери Мисирска; јер ће Ноф опустјети и спалиће се да неће нико живјети у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Мисир је лијепа јуница; али погибао иде, иде са сјевера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'И најамници су његови усред њега као теоци угојени, али се и они обрнуше и побјегоше, не осташе, јер дође на њих дан несреће њихове, вријеме похођења њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Глас ће њихов ићи као глас змијињи, јер они иду с војском и доћи ће са сјекирама на њ као они који сијеку дрва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'И они ће посјећи шуму његову, говори Господ, ако јој и нема мјере, јер их је више него скакаваца и нема им броја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Посрами се кћи Мисирска, предана је у руке народу сјеверном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Говори Господ над војскама Бог Израиљев: ево, ја ћу походити људство у Ноји, и Фараона и Мисир и богове његове и цареве његове, Фараона и све који се уздају у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'И даћу их у руке онима који траже душу њихову, у руке Навуходоносору цару Вавилонском и у руке слугама његовијем; а послије ће бити насељен као прије, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'А ти се не бој, слуго мој Јакове, и не плаши се, Израиљу, јер ево ја ћу те избавити из даљне земље и сјеме твоје из земље ропства његова; и Јаков ће се вратити и почиваће, и биће миран и нико га неће плашити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Ти се не бој, слуго мој Јакове, говори Господ, јер сам ја с тобом; јер ћу учинити крај свијем народима, у које те прогнах, али теби нећу учинити краја, него ћу те покарати с мјером, а нећу те оставити сасвијем без кара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Ријеч Господња која дође Јеремији пророку за Филистеје прије него Фараон освоји Газу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Овако вели Господ: ево, вода долази са сјевера, и биће као поток који се разљева, и потопиће земљу и што је у њој, град и оне који живе у њему; и људи ће викати, и ридаће сви становници земаљски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Од топота копита јаких коња његовијех, од тутњаве кола његовијех, и праске точкова његовијех, неће се обазрети оцеви на синове, јер ће им руке клонути,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'Од онога дана који ће доћи да истријеби све Филистеје и да затре Тир и Сидон и све остале помоћнике, јер ће Господ истријебити Филистеје, остатак острва Кафтора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Оћелавиће Газа, пропашће Аскалон и остатак долине њихове; докле ћеш се резати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Јаох, мачу Господњи, кад ћеш се смирити? врати се у корице своје, стани и смири се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Али како би се смирио? јер му Господ даде заповијест на Аскалон и на приморје; онамо га одреди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'За Моава овако говори Господ над војскама Бог Израиљев: тешко Невону! јер ће се опустошити; Киријатајим ће се посрамити и узети; Мизгав ће се посрамити и препасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Неће се више хвалити Моав Есевоном; јер му зло мисле: ходите да га истријебимо да није више народ. И ти, Мадмене, опустјећеш; мач ће те гонити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Чује се вика из Оронајима, пустошење и сатирање велико.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Моав се сатр; стоји вика дјеце његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Јер ће се путем Луитским дизати плач без престанка; и како се слази у Оронајим, непријатељи ће чути страшну вику:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Бјежите, избавите душе своје, и будите као вријес у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Јер што се уздаш у своја дјела и у благо своје, зато ћеш се и ти узети, и Хамос ће отићи у ропство, свештеници његови и кнезови његови скупа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'И доћи ће затирач у сваки град, неће се сачувати ни један град; долина ће пропасти и равница ће се опустошити, јер Господ рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Подајте крила Моаву, нека брзо одлети; јер ће градови његови опустјети да неће нико живјети у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Проклет био ко немарно ради дјело Господње, и проклет ко устеже мач свој од крви!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Моав је био у миру од дјетињства својега и почивао на дрождини својој, нити се претакао из суда у суд, нити је у ропство ишао; зато му оста кус његов, и мирис се његов није промијенио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Зато, ево, иду дани, говори Господ, да му пошљем преметаче, који ће га преметнути, и судове његове испразнити и мјехове његове покидати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'И Моав ће се осрамотити с Хамоса, као што се осрамотио дом Израиљев с Ветиља, гада својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Како говорите: јаки смо и јунаци у боју?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Моав ће се опустошити и градови ће његови пропасти, и најбољи младићи његови сићи ће на заклање, говори цар, којему је име Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Близу је погибао Моавова, и зло његово врло хити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Жалите га сви који сте око њега, и који год знате за име његово, реците: како се сломи јаки штап, славна палица?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Сиђи са славе своје, и сједи на мјесто засушено, кћери, која живиш у Девону; јер ће затирач Моавов доћи на тебе и раскопаће градове твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Стани на путу, и погледај, која живиш у Ароиру, упитај онога који бјежи и ону која гледа да се избави, реци: што би?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Посрами се Моав; јер се разби; ридајте и вичите; јавите у Арнон да се Моав опустоши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Јер суд дође на земљу равну, на Олон и на Јасу и Мифат,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'И на Девон и на Невон и на Вет-Девлатајим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'И на Киријатајим и на Вет-Гамул и на Вет-Меон,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'И на Кериот и на Восору, и на све градове земље Моавске, који су далеко и који су близу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Одбијен је рог Моаву, и мишица се његова сломи, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Опојте га, јер се подигао на Господа; нека се ваља Моав у бљувотини својој, и буде и он потсмијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Јер није ли теби Израиљ био потсмијех? је ли се затекао међу лупежима, те кад год говориш о њему поскакујеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Оставите градове и населите се у стијени, становници Моавски, и будите као голубица која се гнијезди у крају и расјелини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Чусмо понос Моавов да је веома поносит, охолост његову и понос, разметање његово и обијест његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Знам ја, говори Господ, обијест његову; али неће бити тако; лажи његове неће учинити ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Зато ћу ридати за Моавом, викати за свијем Моавом, уздисаће се за онима у Кир-Ересу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Више него за Јазиром плакаћу за тобом, лозо Сивамска; одводе твоје пријеђоше море, допријеше до мора Јазирскога; затирач нападе на љетину твоју и на бербу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'И радост и весеље отиде с роднога поља, из земље Моавске, и учиних те неста у кацама вина; нико неће газити пјевајући; пјесма неће се више пјевати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Од вике Есевонске, која доприје до Елеале, подигоше вику до Јасе, од Сигора до Оронајима, као јуница од три године, јер ће и вода Нимримских нестати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'И учинићу, говори Господ, да не буде Моаву човјека који би приносио жртву на висини и кадио боговима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Зато ће срце моје пиштати за Моавом као свирала, и срце ће моје пиштати као свирала за људима у Кир-Ересу, јер ће му сва течевина пропасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Јер ће све главе бити ћелаве и све браде обријане, и све руке изрезане, и око бедара костријет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'На свијем крововима Моавовијем и по улицама његовијем биће сам плач, јер ћу разбити Моава као суд на ком нема милине, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Ридајте: како је сатрвен! како Моав обрну плећи срамотан? и поста Моав потсмијех и страхота свјема који су око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Јер овако говори Господ: ево, као орао долетјеће и рашириће крила своја над Моавом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Кериот је покорен и тврда се мјеста заузеше, и срца ће у јунака Моавовијех бити у онај дан као срце у жене која се порађа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'И Моав ће се истријебити да не буде народ, јер се подиже на Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Страх и јама и замка око тебе је, становниче Моавски, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Ко утече од страха, паше у јаму, а ко изљезе из јаме, ухватиће се у замку; јер ћу пустити на њега, на Моава, годину похођења њихова, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'У сјену Есевонском уставише се који бјежаху од силе; али ће огањ изаћи из Есевона и пламен исред Сиона, и опалиће крај Моаву и тјеме немирницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Тешко теби, Моаве, пропаде народ Хамосов, јер синове твоје заробише, и кћери твоје одведоше у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Али ћу повратити робље Моавово у пошљедње вријеме, говори Господ. Довде је суд Моаву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'За синове Амонове: овако вели Господ: зар Израиљ нема синова? зар нема нашљедника? зашто Малхом наслиједи земљу Гадову? и зашто се народ његов насели у његовијем градовима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Зато ево иду дани, говори Господ, кад ћу учинити да се чује вика убојна у Рави синова Амоновијех, и она да буде гомила развалина, и села њезина попаљена огњем; и Израиљ ће обладати онима који бјеху њим обладали, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Ридај Есевоне, јер је Гај опустошен; вичите села Равска; припашите око себе костријет, наричите и трчите око плотова; јер ће Малхом отићи у ропство, свештеници његови и кнезови његови скупа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Што се хвалиш долинама? Растопила се долина твоја, кћери одметницо! која се уздаш у благо своје: ко би ударио на ме?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Ево ја ћу пустити на те страх отсвуда унаоколо, говори Господ Господ над војскама, и распршаћете се сви, и неће бити никога да сакупи бјежан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Али ћу послије повратити робље синова Амоновијех, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'За Едома, овако вели Господ над војскама: зар нема више мудрости у Теману? неста ли свјета разумнима? ишчиље ли мудрост њихова?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Бјежите, обратите плећи, заврите се дубоко, становници Дедански, јер ћу пустити на Исава погибао његову у вријеме кад ћу га походити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Да ти дођу берачи, не би ли ти оставили пабирака? да дођу лупежи ноћу, не би ли однијели колико им је доста?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Али ја оголузних Исава, открих потаје његове да се не може сакрити; пропаде сјеме његово, браћа његова и сусједи његови, нико не оста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Остави сироте своје, ја ћу им живот сачувати, и удовице твоје нека се уздају у ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Јер овако вели Господ: ево, који не би требало да пију из чаше, доиста ће пити; а ти ли ћеш остати без кара? нећеш остати без кара, него ћеш зацијело пити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Јер собом се заклињем, говори Господ, да ће Восора бити пустош, руг, чудо и проклетство, и сви ће градови њезини бити пустиња вјечна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Чух глас од Господа, и гласник би послан к народима да рече: скупите се и идите на њу, и дигните се у бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Јер гле, учинићу те да будеш мали међу народима и презрен међу људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Обијест твоја и поноситост срца твојега превари тебе, који живиш у расјелинама каменијем и држиш се високих хумова; да начиниш себи гнијездо високо као орао, и оданде ћу те свалити, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'И земља ће Едомска бити пустиња, ко прође мимо њу, свак ће се чудити и звиждати ради свијех рана њезинијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Као кад се затр Содом и Гомор и сусједство њихово, вели Господ, неће се населити ондје нико нити ће се бавити ондје син човјечји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Гле, као лав изаћи ће подижући се више него Јордан на стан силнога; али ћу га брзо отјерати из те земље, и поставићу над њом онога ко је изабран; јер ко је као ја? и ко ће се прети са мном? и који ће ми пастир одољети?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Зато чујте намјеру Господњу што је наумио за Едомце и мисли његове што је смислио за становнике Теманске: заиста најмањи из стада развлачиће их, заиста ће опустјети стан с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Од праске падања њихова земља ће се трести, и вика ће се њима чути на црвеном мору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Гле, доћи ће и долетјеће као орао и рашириће крила своја над Восором, и биће срце у јунака Едомских као срце у жене која се порађа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'За Дамаск. Посрами се Емат и Арфад, јер чу зле гласе; растопише се, страх је на мору, не може се умирити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Дамаск клону, обрати се да бјежи, дрхат га подузе, туга и болови освојише га као породиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Како се не остави славни град? град радости моје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Зато ће попадати младићи његови на улицама његовијем, и сви ће војници његови изгинути у онај дан, говори Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'И распалићу огањ у зидовима Дамаштанским, и прождријеће дворе Вен-Ададове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'За Кидар и за царства Асорска, која разби Навуходоносор цар Вавилонски, овако вели Господ: устаните, идите на Кидар, и затрите синове источне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Узеће им шаторе и стада, завјесе њихове и судове њихове и камиле њихове отеће, и викаће на њих страшно отсвуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Бјежите, селите се далеко, заврите се дубоко, становници Асорски, говори Господ, јер је Навуходоносор цар Вавилонски намјерио намјеру против вас, и смислио мисао против вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Устаните, идите к народу мирноме, који живи без страха, говори Господ, који нема врата ни пријеворница, живе сами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'И камиле ће њихове бити плијен, и мноштво стоке њихове грабеж, и расијаћу их у све вјетрове, оне што се с краја стригу; и довешћу погибао на њих са свијех страна, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'И Асор ће бити стан змајевски, пустиња довијека: нико се неће ондје населити, нити ће се бавити у њему син човјечји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Ријеч Господња која дође Јеремији пророку за Елам, у почетку царовања Седекије цара Јудина, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Овако вели Господ над војскама: ево, ја ћу сломити лук Еламу, главну силу његову;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'И довешћу на Елам четири вјетра с четири краја небеса, и у све те вјетрове расијаћу их, тако да неће бити народа куда неће отићи прогнаници Еламски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'И уплашићу Еламце пред непријатељима њиховијем, и пред онима који траже душу њихову; и пустићу зло на њих, жестину гњева својега, говори Господ, и пустићу за њима мач докле их не затрем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'И намјестићу пријесто свој у Еламу, и истријебићу оданде цара и кнезове, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Али у пошљедње вријеме повратићу робље Еламско, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Ријеч коју рече Господ за Вавилон и за земљу Халдејску преко Јеремије пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Јавите народима и разгласите, подигните заставу, разгласите, не тајите, реците: узе се Вавилон, посрами се Вил, разби се Меродах; посрамише се идоли његови, разбише се гадни богови његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Јер се народ подиже на њ са сјевера, који ће му земљу опустити, да неће бити никога да живи у њој; и људи и стока побјећи ће и отићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'У те дане и у то вријеме, говори Господ, доћи ће синови Израиљеви и синови Јудини заједно, ићи ће плачући и тражиће Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Питаће за пут у Сион, и обративши се онамо рећи ће: ходите, сјединимо се с Господом завјетом вјечнијем, који се не заборавља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Народ је мој стадо изгубљено; пастири његови заведоше га, те лута по горама, иде с брда на хумове, заборавивши стан свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Ко их нађе, прождираше их, и непријатељи њихови говорише: не ћемо бити криви, јер згријешише Господу, стану правде, Господу, наду отаца њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Бјежите из Вавилона и изидите из земље Халдејске и будите као овнови пред стадом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Јер, ево, ја ћу подигнути и довешћу на Вавилон збор великих народа из земље сјеверне, који ће се уврстати да се бију с њим, и узеће га; стријеле су им као у добра јунака, не враћају се празне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'И земља ће се Халдејска оплијенити, сви који ће је плијенити наситиће се, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Јер се веселисте, јер се радовасте плијенећи моје нашљедство; јер бјешњесте као јуница на трави и рзасте као јаки коњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Мати се ваша осрамоти врло, родитељка ваша постидје се; ево биће пошљедња међу народима, пустиња, земља суха и пустош.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Од гњева Господњега неће се у њој живјети, него ће сва опустјети; ко год прође мимо Вавилона, чудиће се и звиждаће ради свијех рана његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Поставите се око Вавилона сви који натежете лук, стријељајте га, не жалите стријела; јер је сагријешио Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Вичите на њ унаоколо; пружа руку; темељи му падоше, зидови су му разваљени; јер је освета Господња; осветите му се; како је чинио, онако му чините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Истријебите из Вавилона сијача и онога који маше српом о жетви; од мача насилникова нека се врати сваки своме народу, и сваки у своју земљу нека бјежи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Израиљ је стадо разагнано, лавови га расплашише; најприје га једе цар Асирски, а послије му кости изломи Навуходоносор цар Вавилонски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Зато овако вели Господ над војскама, Бог Израиљев: ево, ја ћу походити цара Вавилонскога и земљу његову, као што сам походио цара Асирскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'И повратићу Израиља у торове његове, и пашће по Кармилу и Васану; и по гори Јефремовој и Галаду ситиће се душа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'У оне дане и у оно вријеме, говори Господ, тражиће се безакоње Израиљево, али га неће бити; и гријеси Јудини, али се неће наћи, јер ћу опростити онима које оставим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Изиди на земљу Мератајимску и на становнике Фекодске; затри и истријеби иза њих, говори Господ, и учини све како ти заповиједим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Вика је убојна у земљи и полом велик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Како се сломи и скрши маљ цијеле земље? како Вавилон поста чудо међу народима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Ја ти метнух замку, Вавилоне, и ти се ухвати не дознавши, нашао си се и ухватио си се, јер си се заратио с Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Господ отвори ризницу своју и извади оружје гњева својега; јер је то дјело Господа Господа над војскама у земљи Халдејској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Ходите на њу с краја земље, отворите житнице њезине; газите је као стогове, и потрите је да не остане од ње остатка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Покољите мачем све теоце њезине, нека сиђу на заклање; тешко њима! јер дође дан њихов, вријеме похођења њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Чује се глас онијех који бјеже и који утекоше из земље Вавилонске да јаве у Сиону освету Господа Бога нашега, освету двора његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Сазовите на Вавилон мноштво; сви који натежете лук, станите у око према њему унаоколо да не утече ниједан, платите му по дјелима његовијем; како је чинио, онако му учините, јер се је супрот Господу узносио, супрот свецу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Зато ће младићи његови пасти по улицама његовијем, и сви ће војници његови изгинути у онај дан, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Ево мене на тебе, поносити, говори Господ Господ над војскама, јер дође дан твој, вријеме да те походим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Поносити ће се спотаћи и пасти, и неће бити никога да га подигне; и распалићу огањ у градовима његовијем, и спалиће сву околину његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Овако вели Господ над војскама: сила се чини синовима Израиљевим и синовима Јудинијем; који их заробише, држе их, неће да их пусте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Избавитељ је њихов силан, име му је Господ над војскама,он ће доиста бранити ствар њихову да умири земљу и смете становнике Вавилонске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Мач на Халдејце, говори Господ, и на становнике Вавилонске и на кнезове његове и на мудраце његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Мач на лаже његове, и полудјеће; мач на јунаке његове, и препашће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Мач на коње његове, и на кола његова и на сву мјешавину што је усред њега, и постаће као жене; мач на благо његово, и разграбиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Суша на воде његове, и усахнуће, јер је земља идолска, и око лажнијех богова лудују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Зато ће се ондје настанити дивље звијери и буљине, и сове ће ондје становати; и неће се населити довијека и неће се у њој живјети нигда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Као кад Господ затр Содом и Гомор и сусједство њихово, говори Господ, неће се нико ондје населити, нити ће се бавити у њој син човјечји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Ево, народ ће доћи са сјевера, велик народ, и цареви силни подигнуће се од крајева земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Лук и копље носиће, жестоки ће бити, нити ће жалити; глас ће им као море бучати и јахаће на коњма, спремни као јунаци за бој, на тебе, кћери Вавилонска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Цар Вавилонски кад чује глас о њима, клонуће му руке, туга ће га спопасти и болови као породиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Гле, као лав изаћи ће подижући се више него Јордан на стан силнога; али ћу га брзо отјерати из те земље, и поставићу над њом онога ко је изабран; јер ко је као ја? и ко ће се прети са мном? и који ће ми пастир одољети?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Зато чујте намјеру Господњу што је наумио за Вавилон, и мисли његове што је смислио за земљу Халдејску; заиста најмањи из стада развлачиће их, заиста ће опустити стан с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Од праске кад се узме Вавилон потрешће се земља, и вика ће се чути по народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Овако говори Господ: ево, ја ћу подигнути на Вавилон и на оне који живе усред онијех који устају на ме вјетар који мори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Послаћу на Вавилон вијаче који ће га развијати и земљу његову испразнити, јер ће га опколити са свијех страна у дан невоље његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Стријелац нека натеже лук на стријелца и на онога који се поноси својим оклопом; и не жалите младића његовијех, потрите му сву војску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Нека падну побијени у земљи Халдејској и избодени на улицама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Јер није оставио Израиља и Јуде Бог њихов, Господ над војскама, ако и јест земља њихова пуна кривице свецу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Бјежите из Вавилона и избавите сваки душу своју да се не истријебите у безакоњу његову, јер је вријеме освете Господње, плаћа му што је заслужио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Вавилон бијаше златна чаша у руци Господњој, којом опоји сву земљу; вина његова пише народи, зато полудјеше народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Уједанпут паде Вавилон и разби се; ридајте за њим; донесите балсама за ране његове, не би ли се исцијелио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Лијечисмо Вавилон, али се не исцијели; оставите га, и да идемо сваки у своју земљу; јер до неба допире суд његов и диже се до облака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Господ је изнио правду нашу; ходите, да приповиједамо на Сиону дјело Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Чистите стријеле, узмите штитове; Господ подиже дух царева Мидских, јер је Вавилону намислио да га затре; јер је освета Господња, освета цркве његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'На зидовима Вавилонским подигните заставу, утврдите стражу, поставите стражаре, намјестите засједе; јер је Господ намислио, и учиниће што је рекао за становнике Вавилонске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'О ти, што станујеш крај воде велике и имаш много блага! дође крај твој и свршетак лакомству твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Господ над војскама закле се собом: напунићу те људима као скакавцима, и они ће ти пјевати пјесму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Он је створио земљу силом својом, утврдио васиљену мудрошћу својом, и разумом својим разапео небеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Кад пусти глас свој, буче воде на небесима, подиже пару с крајева земаљских, и пушта муње с даждем, и изводи вјетар из стаја његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Сваки човјек поста безуман од знања, сваки се златар осрамоти ликом резанијем; јер су лаж ликови његови ливени и нема духа у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Таштина су, дјело пријеварно; кад их походим погинуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Није таки дио Јаковљев; јер је он творац свему и он је дио нашљедства његова; име му је Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Ти си ми био маљ, оружје убојно, и тобом сатрх народе и тобом расух царства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'И тобом сатрх коња и јахача његова; и тобом сатрх кола и који сјеђаху на њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'И тобом сатрх човјека и жену, и сатрх тобом старца и дијете, и сатрх тобом момка и дјевојку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'И тобом сатрх пастира и стадо његово, и тобом сатрх орача и волове његове ујармљене, и сатрх тобом кнезове и властеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'И платићу Вавилону и свијем становницима Халдејским за све зло које учинише Сиону, на ваше очи, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Ево мене на тебе, горо, која сатиреш, говори Господ, која затиреш сву земљу, и замахнућу руком својом на те и свалићу те са стијена, и начинићу од тебе гору изгорјелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'И неће узети од тебе камена за угао ни камена за темељ, јер ћеш бити пустош вјечна, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Подигните заставу у земљи, затрубите у трубе међу народима, приправите народе на њ, сазовите на њ царство Араратско, Минијско и Асхананско; поставите војводу супрот њему, доведите коње као скакавце бодљикасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Приправите народе супрот њему, цареве Мидске и војводе њихове и све властеле њихове и сву земљу државе њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'И земља ће се затрести и узмучити, јер ће се мисао Господња извршити на Вавилону да обрати земљу Вавилонску у пустињу да нико не живи у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Престаше војевати јунаци Вавилонски, стоје у граду, неста силе њихове, посташе као жене, изгорјеше станови њихови, пријеворнице њихове поломише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Гласник ће сретати гласника, и посланик ће сретати посланика да јаве цару Вавилонском да му је узет град са свијех крајева,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'И да се бродови узеше и језера изгорјеше огњем и војници се препали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Јер овако вели Господ над војскама Бог Израиљев: кћи је Вавилонска као гумно; вријеме је да се набије, још мало, па ће доћи вријеме да се пожње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Изједе ме и потр ме Навуходоносор цар Вавилонски, начини од мене непотребан суд, прождрије ме као змај, напуни трбух свој милинама мојим, и отјера ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Неправда која се чини мени и мојему тијелу нека дође на Вавилон, рећи ће становница Сионска, и крв моја на становнике Халдејске, говориће Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Зато овако вели Господ: ево, ја ћу расправити парбу твоју и осветићу те; и осушићу море његово, и изворе ћу његове осушити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'И Вавилон ће постати гомила, стан змајевски, чудо и потсмијех, да нико неће живјети у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Рикаће сви као лавови и вити као лавићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Кад се угрију, изнијећу им да пију, и опојићу их да се развеселе и заспе вјечнијем сном, да се не пробуде, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Свешћу их на заклање као јагањце, као овнове с јарцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Како се придоби Сисах и узе се хвала све земље? како Вавилон поста чудо међу народима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Море уста на Вавилон, покри га мноштво вала његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Градови његови посташе пустош, земља сасушена и пуста, земља гдје нико не живи, нити пролази кроз њу син човјечји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'И походићу Вила у Вавилону и извући ћу из уста његовијех што је прождро, и неће се више стјецати к њему народи, и зид ће Вавилонски пасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Изиди из њега, народе мој, и избавите сваки своју душу од жестокога гњева Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Немојте да одмекне срце ваше и да се уплашите од гласа који ће се чути у земљи; а доћи ће глас једне године, а послије њега други глас друге године, и насиље ће бити у земљи, и господар ће устати на господара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Зато ево иду дани кад ћу походити резане ликове Вавилонске, и сва ће се земља његова посрамити, и сви ће побијени његови пасти усред њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Небо и земља и све што је у њима пјеваће над Вавилоном, јер ће доћи на њ са сјевера затирач, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'И као што је Вавилон учинио да падну побијени Израиљеви, тако ће пасти у Вавилону побијени све земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Који утекосте од мача, идите, не стојте; помињите Господа издалека, и Јерусалим нека вам је у срцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Посрамисмо се, што чусмо руг, стид попаде лице наше, што туђини уђоше у светињу дома Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Зато, гле, иду дани, говори Господ, кад ћу походити резане ликове његове, и по свој земљи његовој јечаће рањеници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Да се Вавилон и на небо попне, и на висини да утврди силу своју, доћи ће од мене на њ затирачи, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Чује се велика вика из Вавилона, и велик полом из земље Халдејске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Јер Господ затире Вавилон, и укида у њему велику вреву; и вали ће њихови бучати као велика вода, вика ће се њихова разлијегати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Јер дође на њ, на Вавилон, затирач, јунаци се његови заробише, лукови се њихови потрше; јер је Господ Бог који плаћа, доиста ће платити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Опојићу кнезове његове и мудраце његове, војводе његове и властеље његове и јунаке његове, да ће заспати вјечнијем сном и неће се пробудити, говори цар којему је име Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Овако вели Господ над војскама: широки зидови Вавилонски са свијем ће се раскопати, и висока врата његова огњем ће се спалити, те ће људи бити узалуд радили, и народи се трудили за огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Ријеч што заповиједи пророк Јеремија Сераји сину Нирије сина Масијина, кад пође од Седекије цара Јудина у Вавилон четврте године царовања његова; а Сераја бјеше главни постељник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'А Јеремија написа у једну књигу све зло које шћаше доћи на Вавилон, све ове ријечи што су написане за Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'И рече Јеремија Сераји: кад дођеш у Вавилон, тада гледај и прочитај све ове ријечи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'И реци: Господе, ти си говорио за ово мјесто да ћеш га затрти да нико не живи у њему, ни човјек ни живинче, него да је пустош довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'А кад прочиташ ову књигу, вежи камен за њу, и баци је у Ефрат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'И реци: тако ће потонути Вавилон и неће се подигнути ода зла које ћу пустити на њ, и они ће изнемоћи. Довде су ријечи Јеремијине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Двадесет и једна година бијаше Седекији кад поче царовати, и царова једанаест година у Јерусалиму. Матери му бјеше име Амутала кћи Јеремијина, из Ливне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Он чињаше што је зло пред Господом сасвијем како је чинио Јоаким.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Јер од гњева Господњега зби се Јерусалиму и Јуди, те их одбаци испред себе. А Седекија се одметну од цара Вавилонскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'И тако девете године његова царовања, десетога дана дође Навуходоносор цар Вавилонски са свом војском својом на Јерусалим; и стадоше у око под њим, и начинише опкопе око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'И град би опкољен до једанаесте године царовања Седекијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'И деветога дана четвртога мјесеца наста велика глад у граду, те народ земаљски немаше хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Тада град би проваљен, и војници сви побјегоше и изидоше из града ноћу на врата између два зида уз врт царев, а Халдејци бијаху свуда око града; и отидоше путем к пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Али војска Халдејска потјера цара, и стигоше Седекију у пољу Јерихонском, а сва војска што бијаше с њим разбјеже се од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'И ухватише цара и одведоше га к цару Вавилонском у Ривлу у земљи Ематској; и ондје му суди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'И покла цар Вавилонски синове Седекијине на његове очи, и све кнезове Јудине покла у Ривли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'И Седекији ископа очи, и свезав га у двоје вериге мједене одведе га цар Вавилонски у Вавилон и метну га у тамницу, гдје оста до смрти своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'А десетога дана петога мјесеца године деветнаесте царовања Навуходоносора цара Вавилонскога дође у Јерусалим Невузардан заповједник стражарски, који служаше цару Вавилонском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'И попали дом Господњи и дом царски и све домове у Јерусалиму; све велике куће попали огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'И све зидове Јерусалимске унаоколо развали сва војска Халдејска што бијаше са заповједником стражарским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'А народ сиромашни и остатак народа што оста у граду, и пребјеге што пребјегоше к цару Вавилонском, и остали прости народ, одведе Невузардан заповједник стражарски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Само од сиромашнога народа у земљи остави Невузардан заповједник стражарски који ће бити виноградари и ратари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'И ступове мједене што бијаху у дому Господњем, и подножја и море мједено које бијаше у дому Господњем, изломише Халдејци, и мјед од њих однесоше у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'И лонце и лопате и виљушке и котлиће и кадионице и све судове мједене којима служаху, узеше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'И умиваонице и клијешта с котлићима и лонцима и свијетњацима и кадионицама и чашама, што год бијаше златно и што год бијаше сребрно, узе заповједник стражарски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Два ступа, једно море, и дванаест волова мједенијех што бијаху под подножјима, што начини цар Соломун за дом Господњи, не бјеше мјере мједи од свијех тијех судова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'А ступови бијаху сваки од осамнаест лаката у висину, а у наоколо од дванаест лаката, а четири прста бјеше сваки дебео и шупаљ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'И озго на њему бијаше оглавље мједено, и оглавље бјеше високо пет лаката, и плетеница и шипци око оглавља, све од мједи; таки бијаше и други ступ са шипцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'И бијаше деведесет и шест шипака са сваке стране; свега шипака на плетеници унаоколо бијаше сто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Узе заповједник стражарски и Серају првога свештеника и Софонију другога свештеника, и три вратара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'А из града узе једнога дворанина, који бијаше над војницима и седам људи који стајаху пред царем, који се нађоше у граду, и првога писара војничкога, који пописиваше народ по земљи у војску, и шездесет људи из народа земаљскога, који се нађоше у граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Узе их Невузардан заповједник стражарски и одведе к цару Вавилонском у Ривлу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'А цар их Вавилонски поби и погуби у Ривли у земљи Ематској. Тако би пресељен Јуда из земље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Ово је народ што га пресели Навуходоносор: седме године три тисуће и двадесет и три Јудејца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'Године осамнаесте Навуходоносорове пресели из Јерусалима осам стотина и тридесет и двије душе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'Године двадесет треће Навуходоносорове пресели Невузардан заповједник стражарски Јудејаца седам стотина и четрдесет и пет душа; свега четири тисуће и шест стотина душа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'А тридесет седме године откако се зароби Јоахин цар Јудин, дванаестога мјесеца, двадесет петога дана, Евил-Меродах цар Вавилонски исте године зацарив се извади из тамнице Јоахина цара Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'И лијепо говори с њим, и намјести му пријесто више пријестола других царева који бијаху код њега у Вавилону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'И промијени му хаљине тамничке, и он јеђаше свагда с њим свега вијека својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'И храна му се једнако даваше од цара Вавилонскога сваки дан свега вијека његова до смрти његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Како сједи сам, поста као удовица, град који бјеше пун народа! велик међу народима, глава међу земљама потпаде под данак!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Једнако плаче ноћу, и сузе су му на образима, нема никога од свијех који га љубљаху да га потјеши; сви га пријатељи његови изневјерише, посташе му непријатељи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Исели се Јуда од муке и љутога ропства; сједи међу народима, не налази мира; сви који га гонише стигоше га у тјеснацу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Путови Сионски туже, јер нико не иде на празник; сва су врата његова пуста, свештеници његови уздишу, дјевојке су његове жалосне, и сам је јадан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Противници његови посташе глава, непријатељима је његовијем добро; јер га Господ уцвијели за мноштво безакоња његова; дјеца његова иду у ропство пред непријатељем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'И отиде од кћери Сионске сва слава њезина; и кнезови су њезини као јелени који не налазе паше, иду немоћни пред онијем који их гони.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Опомиње се Јерусалим у муци својој и у јаду свом свијех милина што је имао од старине, кад пада народ његов од руке непријатељеве а никога нема да му поможе; непријатељи гледају га и смију се престанку његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Тешко сагријеши Јерусалим, зато поста као нечиста жена; сви који су га поштовали презиру га, јер видјеше голотињу његову; а он уздише, и окреће се натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Нечистота му бјеше на скутовима, није мислио на крај свој; пао је за чудо а нема никога да га потјеши. Погледај, Господе, муку моју, јер се непријатељ понио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Непријатељ посеже руком на све драге ствари његове, и он гледа како народи улазе у светињу његову, за које си заповиједио: да не долазе на сабор твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Сав народ његов уздише тражећи хљеба, дају драгоцјене ствари своје да окријепе душу. Погледај, Господе, и види како сам поништен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Зар вам није стало, сви који пролазите овуда? погледајте и видите, има ли бола какав је мој, који је мени допао, којим ме уцвијели Господ у дан жестокога гњева својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'С висине пусти огањ у кости моје, који их освоји; разапе мрежу ногама мојима, обори ме наузнако, пустоши ме, те по вас дан тужим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Свезан је руком његовом јарам од гријеха мојих, усукани су и дођоше ми на врат; обори силу моју; предаде ме Господ у руке; из којих се не могу подигнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Полази Господ све јунаке моје усред мене, сазва на ме сабор да потре младиће моје; као грожђе у каци изгази Господ дјевојку кћер Јудину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Зато ја плачем, очи моје, очи моје лију сузе, јер је далеко од мене утјешитељ, који би укријепио душу моју; синови моји пропадоше, јер надвлада непријатељ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Сион шири руке своје, нема никога да га тјеши; Господ заповиједи за Јакова, те га опколише непријатељи; Јерусалим поста међу њима као нечиста жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Праведан је Господ, јер се супротих заповијести његовој; чујте, сви народи, и видите бол мој; дјевојке моје и младићи моји отидоше у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Звах пријатеље своје, они ме преварише; свештеници моји и старјешине моје помријеше у граду тражећи хране да окријепе душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Погледај, Господе, јер ми је туга, утроба ми се усколебала, срце се моје преврће у мени, јер се много супротих; на пољу учини ме сиротим мач, а код куће сама смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Чују гдје уздишем, али нема никога да ме потјеши; сви непријатељи моји чуше за несрећу моју и радују се што си то учинио; довешћеш дан који си огласио, те ће оно бити као ја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Нека изађе преда те сва злоћа њихова, и учини као што си учинио мени за све гријехе моје; јер је много уздаха мојих и срце је моје жалосно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Како обастрије Господ облаком у гњеву свом кћер Сионску! сврже с неба на земљу славу Израиљеву, и не опомену се подножја ногу својих у дан гњева својега!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Господ потр немилице све станове Јаковљеве, развали у гњеву свом градове кћери Јудине, и на земљу обори, оскврни царство и кнезове његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Одби у жестоком гњеву сав рог Израиљу, обрати натраг десницу своју од непријатеља, и распали се на Јакова као огањ пламени, који прождире све око себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Натеже лук свој као непријатељ, подиже десницу своју као противник, и поби све што бјеше драго очима; на шатор кћери Сионске просу као огањ гњев свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Господ поста као непријатељ; потр Израиља, потр све дворе његове, раскопа све градове његове, и умножи кћери Јудиној жалост и јад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Развали му ограду као врту; потр мјесто састанцима његовијем; Господ врже у заборав на Сиону празнике и суботу, и у жестини гњева својега одбаци цара и свештеника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Одбаци Господ олтар свој, омрзе на светињу своју, предаде у руке непријатељима зидове двора Сионских; стаде их вика у дому Господњем као на празник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Господ науми да раскопа зид кћери Сионске, растеже уже, и не одврати руке своје да не затре, и ојади опкоп и зид, изнемогоше скупа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Утонуше у земљу врата њезина, поломи и потр пријеворнице њезине; цар њезин и кнезови њезини међу народима су; закона нема, и пророци њезини не добијају утваре од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Старјешине кћери Сионске сједе на земљи и муче, посуле су прахом главу и припасале костријет; обориле су к земљи главе своје дјевојке Јерусалимске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Ишчиљеше ми очи од суза, утроба се моја усколебала, просипа се на земљу јетра моја од погибли кћери народа мојега, јер дјеца и која сисају обамиру на улицама градским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Говоре матерама својим: гдје је жито и вино? обамиру као рањеници на улицама градским, и испуштају душу своју у наручју матера својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Кога ћу ти узети за свједока? с чим ћу те изједначити, кћери Јерусалимска? каку ћу ти прилику наћи, да те утјешим, дјевојко, кћери Сионска? јер је несрећа твоја велика као море, ко ће те исцијелити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Пророци твоји пророковаше ти лаж и безумље, и не откриваше безакоња твојега да би одвратили ропство твоје; него ти казиваше утваре лажне и које ће те прогнати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Пљескају рукама над тобом сви који пролазе, звижде и машу главом за кћерју Јерусалимском: то ли је град, за који говораху да је права љепота, радост свој земљи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Разваљују уста на те сви непријатељи твоји, звижде и шкргућу зубима говорећи: прождријесмо; ово је доиста дан који чекасмо; дочекасмо, видјесмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Учини Господ што науми, испуни ријеч своју, коју каза одавна; разори немилице, и развесели тобом непријатеља, подиже рог противницима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Виче срце њихово ка Господу: зиде кћери Сионске, пољевај потоком сузе дан и ноћ, не дај себи мира, и зјеница ока твојега да не стаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Устани, вичи обноћ; у почетку страже, прољевај срце своје као воду пред Господом, подижи к њему руке своје за душу дјеце своје која обамиру од глади на угловима својих улица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Погледај, Господе, и види, коме си овако учинио. Еда ли жене једу пород свој, дјецу коју носе у наручју? еда ли се убија у светињи Господњој свештеник и пророк?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Леже на земљи по улицама дјеца и старци, дјевојке моје и младићи моји падоше од мача, побио си их у дан гњева својега и поклао не жалећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Сазвао си као на празник страхоте моје отсвуда, и у дан гњева Господњега нико не утече нити оста. Које на руку носих и отхраних, њих ми непријатељ мој поби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Ја сам човјек који видјех муку од прута гњева његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Одведе ме и оправи ме у таму а не на видјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Само се на ме обраћа, обраћа руку своју по вас дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Учини, те ми остарје тијело и кожа, потр кости моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Зазида ме, и опточи ме жучју и муком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Посади ме у таму као умрле одавна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Огради ме да не изађем, и метну на ме тешке окове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Кад вичем и вапијем, одбија молитву моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Загради путове моје тесанијем каменом, и преврати стазе моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Поста ми као медвјед у засједи, као лав у потаји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Помете путове моје, и раздрије ме, и уништи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Натеже лук свој, и метну ме стријели за биљегу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Устријели ме у бубреге стријелама из тула својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Постах потсмијех свему народу својему и пјесма њихова по вас дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Насити ме горчином, опоји ме пеленом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Поломи ми зубе камењем, ували ме у пепео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Удаљио си душу моју од мира, заборавих добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'И рекох: пропаде сила моја и надање моје од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Опомени се муке моје и јада мојега, пелена и жучи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Душа се моја опомиње без престанка, и поништила се у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Али ово напомињем срцу својему, те се надам:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Милост је Господња што не изгибосмо сасвијем, јер милосрђа његова није нестало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Понавља се свако јутро; велика је вјера твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Господ је дио мој, говори душа моја; зато ћу се у њега уздати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Добар је Господ онима који га чекају, души, која га тражи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Добро је мирно чекати спасење Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Добро је човјеку носити јарам за младости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Сам ће сједјети и мучати, јер Бог метну бреме на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Метнуће уста своја у прах, еда би било надања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Подметнуће образ свој ономе који га бије, биће сит срамоте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Јер Господ не одбацује за свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'Јер ако и уцвијели, опет ће се и смиловати ради мноштва милости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Јер не мучи из срца својега ни цвијели синова човјечјих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Кад газе ногама све сужње на земљи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'Кад изврћу правицу човјеку пред вишњим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Кад чине криво човјеку у парници његовој, не види ли Господ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Ко је рекао што и збило се, а Господ да није заповједио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Не долазе ли и зла и добра из уста вишњега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Зашто се тужи човјек жив, човјек на кар за гријехе своје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Претражимо и разгледајмо путе своје, и повратимо се ка Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Подигнимо срце своје и руке к Богу на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Згријешисмо и непокорни бисмо; ти не прашташ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Обастро си се гњевом, и гониш нас, убијаш и не жалиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Обастро си се облаком да не продре молитва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Начинио си од нас сметлиште и одмет усред тијех народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Разваљују уста своја на нас сви непријатељи наши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Страх и јама задеси нас, пустошење и затирање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Потоци теку из очију мојих ради погибли кћери народа мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Очи моје лију сузе без престанка, јер нема одмора,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'Докле Господ не погледа и не види с неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Око моје мучи ми душу ради свијех кћери града мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Тјерају ме једнако као птицу непријатељи моји ни за што.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Свалише у јаму живот мој и набацаше камење на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Дође ми вода сврх главе; рекох: погибох!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Призивах име твоје, Господе, из јаме најдубље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Ти чу глас мој; не затискуј уха својега од уздисања мојега, од вике моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Приступао си кад те призивах, и говорио си: не бој се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Расправљао си, Господе, парбу душе моје, и избављао си живот мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Видиш, Господе, неправду која ми се чини; расправи парбу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Видиш сву освету њихову, све што ми мисле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Чујеш руг њихов, Господе, све што ми мисле,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Што говоре они који устају на ме и што намишљају против мене по вас дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Види, кад сједају и кад устају, ја сам им пјесма.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Плати им, Господе, по дјелима руку њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Подај им упорно срце, проклетство своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Гони их гњевом, и истријеби их испод небеса Господњих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Како потамње злато, промијени се чисто злато? камење је од светиње разметнуто по угловима свијех улица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Драги синови Сионски, цијењени као најчистије злато, како се цијене земљани судови, као дјело руку лончаревијех!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'И звијери истичу сисе своје и доје млад своју, а кћи народа мојега поста немилостива као ној у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Језик дјетету које сиса приону за грло од жеђи; дјеца ишту хљеба, а нема никога да им ломи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Који јеђаху посластице, гину на улицама; који одрастоше у скерлету, ваљају се по буњишту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'И кар који допаде кћери народа мојега већи је од пропасти која допаде Содому, који се затр у часу и руке се не забавише око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Назиреји њезини бјеху чистији од снијега, бјељи од млијека; тијело им бјеше црвеније од драгога камења, глатки као сафир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'А сада им је лице црње од угља, не познају се на улицама; кожа им се прилијепила за кости, осушила се као дрво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Боље би онима који су побијени мачем него онима који мру од глади, који издишу убијени од несташице рода земаљскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Својим рукама жене жалостиве кухаше дјецу своју, она им бише храна у погибли кћери народа мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Наврши Господ гњев свој, изли жестоки гњев свој, и распали огањ на Сиону, који му прождрије темеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Не би вјеровали цареви земаљски и сви становници по васиљеној да ће непријатељ и противник ући на врата Јерусалимска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Али би за гријехе пророка његовијех и за безакоња свештеника његовијех, који прољеваху крв праведничку усред њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Лутаху као слијепци по улицама, каљају се крвљу, које не могаху да се не дотичу хаљинама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Отступите, нечисти, вичу им, отступите, отступите, не додијевајте се ничега. И одлазе и скитају се; и међу народима се говори: неће се више станити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Гњев Господњи расија их, неће више погледати на њих; не поштују свештеника, нијесу жалостиви на старце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Већ нам очи ишчиљеше изгледајући помоћ залудну; чекасмо народ који не може избавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Вребају нам кораке, да не можемо ходити по улицама својим, приближи се крај наш, навршише се дани наши, дође крај наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Који нас гонише, бијаху лакши од орлова небеских, по горама нас гонише, у пустињи нам засједаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Дисање ноздара наших, помазаник Господњи, за којега говорасмо: да ћемо живјети под сјеном његовијем међу народима, ухвати се у јаме њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Радуј се и весели се, кћери Едомска, која живиш у земљи Узу! доћи ће до тебе чаша, опићеш се, и открићеш се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Сврши се кар за безакоње твоје, кћери Сионска; неће те више водити у ропство; походиће твоје безакоње, кћери Едомска, откриће гријехе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Опомени се, Господе, што нас задеси; погледај и види срамоту нашу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Нашљедство наше привали се туђинцима, домови наши иностранцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Постасмо сироте, без оца, матере наше као удовице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Своју воду пијемо за новце, своја дрва купујемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'На врату нам је јарам, и гоне нас; уморени немамо одмора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Пружамо руку к Мисирцима и Асирцима, да се наситимо хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Оци наши згријешише, и нема их, а ми носимо безакоња њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Робови нам господаре, нема никога да избави из руку њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Са страхом за живот свој од мача у пустињи доносимо себи хљеб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Кожа нам поцрње као пећ од љуте глади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Срамоте жене на Сиону и дјевојке по градовима Јудинијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Кнезове вјешају својим рукама, не поштују лица старачкога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Младиће узимају под жрвње, и дјеца падају под дрвима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Стараца нема више на вратима, ни младића на пјевању.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Неста радости срцу нашему, игра наша претвори се у жалост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Паде вијенац с главе наше; тешко нама, што згријешисмо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'С тога је срце наше жалосно, с тога очи наше потамњеше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Са горе Сиона, што опустје, и лисице иду по њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Ти, Господе, остајеш довијека, пријесто твој од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Зашто хоћеш да нас заборавиш довијека, да нас оставиш задуго?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Обрати нас, Господе, к себи, и обратићемо се; понови дане наше како бијаху прије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Јер еда ли ћеш нас са свијем одбацити и гњевити се на нас веома?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Године тридесете, мјесеца четвртога, петога дана, кад бијах међу робљем на ријеци Хевару, отворише се небеса, и видјех утваре Божје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Петога дана тога мјесеца, пете године откако се зароби цар Јоахин,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'Дође ријеч Господња Језекиљу сину Вузијеву, свештенику, у земљи Халдејској на ријеци Хевару, и ондје дође рука Господња нада њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'И видјех, и гле, силан вјетар долажаше од сјевера, и велик облак и огањ који се разгоријеваше, и око њега свјетлост, а исред огња као јака свјетлост;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Исред њега још као четири животиње, које на очи бијаху налик на човјека;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'И у сваке бијаху четири лица, и четири крила у сваке;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'И ноге им бијаху праве, а у стопалу бијаху им ноге као у телета; и сијеваху као углађена мјед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'И руке им бијаху човјечије под крилима над четири стране, и лица им и крила бијаху на четири стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Састављена им бијаху крила једно с другим; и не окретаху се идући, него свака иђаше напрема се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'И лице бијаше у све четири лице човјечије и лице лавово с десне стране, а с лијеве стране лице волујско и лице орлово у све четири.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'И лица им и крила бијаху раздијељена озго; у сваке се два крила састављаху једно с другим, а два покриваху им тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'И свака иђаше право напрема се; иђаху куда дух иђаше, и не окретаху се идући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'И на очи бијаху те животиње као живо угљевље, гораху на очи као свијеће; тај огањ пролажаше између животиња и свијетљаше се, и из огња излажаше муња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'И животиње трчаху и враћаху се као муња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'И кад гледах животиње, гле, точак један бијаше на земљи уза сваку животињу према четири лица њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Обличјем и направом бијаху точкови као боје хрисолитове, и сва четири бијаху једнака, и обличјем и направом бијаху као да је један точак у другом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Кад иђаху, иђаху сва четири сваки на своју страну, и идући не скретаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'И наплаци им бијаху високи страхота; и бијаху наплаци пуни очију унаоколо у сва четири.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'И кад иђаху животиње, иђаху и точкови уз њих; и кад се животиње подизаху од земље, подизаху се и точкови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Куда дух иђаше, онамо иђаху, и подизаху се точкови према њима, јер дух животињски бјеше у точковима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Кад оне иђаху, иђаху и они; и кад оне стајаху, стајаху и они; и кад се оне подизаху од земље, подизаху се и точкови према њима, јер дух животињски бјеше у точковима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'А над главама животињама бијаше као небо, по виђењу као кристал, страшно, разастрто озго над главама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'А под тијем небом бијаху им крила пружена, једно према другом, а два крила свакој покриваху тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'И чујах хуку крила њиховијех кад иђаху као да бјеше хука велике воде, као глас свемогућега и као граја у околу; и кад стајаху, спуштаху крила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'И кад ставши спуштаху крила, чујаше се глас озго из неба, које бијаше над главама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'И озго на оном небу што им бијаше над главама, бијаше као пријесто, по виђењу као камен сафир, и на пријестолу бијаше по обличју као човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'И видјех као јаку свјетлост, и у њој унутра као огањ наоколо, од бедара горе, а од бедара доље видјех као огањ и свјетлост око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Као дуга у облаку кад је киша, така на очи бијаше свјетлост унаоколо. То бијаше виђење славе Божје на очима; и кад видјех, падох на лице своје, и чух глас некога који говораше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'И рече ми: сине човјечји, устани на ноге да говорим с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'И уђе у ме дух кад ми проговори, и постави ме на ноге, и слушах онога који ми говораше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'И рече ми: сине човјечји, ја те шаљем к синовима Израиљевијем, к народима одметничким, који се одметнуше мене; они и оци њихови бише ми невјерни до овога дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'К синовима тврда образа и упорна срца шаљем те ја, па им реци: тако вели Господ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'И послушали или не послушали, јер су дом одметнички, нека знају да је пророк био међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'И ти, сине човјечји, не бој их се нити се бој њиховијех ријечи, што су ти упорни и као трње и живиш међу скорпијама; не бој се њиховијех ријечи и не плаши се од њих, што су дом одметнички.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Него им кажи ријечи моје, послушали или не послушали, јер су одметници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Али ти, сине човјечји, слушај што ћу ти казати, не буди непокоран као тај дом непокорни; отвори уста, и поједи што ћу ти дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'И погледах, а то рука пружена к мени, и гле, у њој савијена књига.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'И разви је преда мном, и бјеше исписана изнутра и споља, и бјеше у њој написан плач и нарицање и јаох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'И рече ми: сине човјечји, поједи што је пред тобом, поједи ову књигу, па иди, говори дому Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'И отворих уста, и заложи ме оном књигом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'И рече ми: сине човјечји, нахрани трбух свој, и цријева своја напуни овом књигом коју ти дајем. И поједох је, и бјеше ми у устима слатка као мед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Затијем рече ми: сине човјечји, иди к дому Израиљеву, и говори им моје ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Јер се не шаљеш к народу непозната језика и неразумљива говора, него к дому Израиљеву;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Не к многим народима непозната језика и неразумљива говора, којима ријечи не би разумио; к њима да те пошљем, послушали би те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Али дом Израиљев неће те послушати, јер неће мене да послушају; јер је сав дом Израиљев тврда образа и упорна срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Ево дадох теби образ тврд према њихову образу, и чело тврдо према њихову челу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Као камен дијаманат, тврђе од стијене дадох ти чело; не бој их се, нити се плаши од њих, зато што су дом одметнички.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Потом рече ми: сине човјечји, све ријечи моје што ћу ти говорити примај у срце своје и слушај ушима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Иди к робљу, к синовима народа својега, и говори им и реци им: тако вели Господ Господ; послушали или не послушали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Тада подиже ме дух, и чух за собом глас гдје се силно разлијеже: благословена слава Господња с мјеста његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'И лупу крила онијех животиња, која удараху једно о друго, и праску точкова према њима, глас који се силно разлијегаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'И дух ме подиже и однесе, и иђах жалостан од срдње у духу свом; али рука Господња силна бјеше нада мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'И дођох к робљу у Телавив, које становаше на ријеци Хевару, и сједох гдје они сјеђаху, и сједјех ондје међу њима седам дана чудећи се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'А послије седам дана дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Сине човјечји, поставих те стражарем дому Израиљеву, да слушаш ријечи из мојих уста и опомињеш их од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Кад речем безбожнику: погинућеш, а ти га не опоменеш и не проговориш му да би одвратио безбожника од безбожнога пута његова, да би га сачувао у животу, онај ће безбожник погинути са својега безакоња; али ћу крв његову искати из твојих руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'А кад ти опоменеш безбожника, а он се и не врати од безбожности своје и са злога пута својега, он ће погинути с безакоња својега, а ти ћеш сачувати душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Ако ли се праведник одврати од правде своје, и стане чинити безакоње, и ја му подметнем на што ће се спотаћи, те погине, а ти га не опомену, он ће погинути са свога гријеха, и неће се поменути праведна дјела његова што је чинио, али ћу крв његову искати из твоје руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Ако ли ти опоменеш праведника да не гријеши праведник, и он престане гријешити, он ће живјети, јер прими опомену, и ти ћеш сачувати душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'И дође ондје нада ме рука Господња, и рече ми: устани, изиди у поље, и ондје ћу говорити с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'И уставши отидох у поље, а гле, слава Господња стајаше ондје као слава коју видјех на ријеци Хевару, и падох на лице своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'И уђе у ме дух, и постави ме на ноге; и проговори са мном и рече ми: иди, затвори се у кућу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Јер, сине човјечји, ево, метнуће на те узице, и свезаће те њима, и нећеш излазити међу њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'И ја ћу учинити да ти се језик прилијепи за грло, те ћеш онијемјети, и нећеш их карати, јер су дом одметнички.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Али кад ти проговорим, отворићу ти уста, и казаћеш им: овако вели Господ Господ; ко ће слушати, нека слуша, а ко неће слушати, нека не слуша; јер су дом одметнички.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'А ти, сине човјечји, узми опеку и метни је преда се, и изрежи на њој град Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'И постави око њега опсаду, и начини куле према њему, и ископај око њега опкоп, и постави војску око њега, и намјести убојне справе око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Потом узми тавицу гвоздену, и метни је као гвозден зид између себе и града, и окрени лице своје супрот њему, и он ће се опсјести, и ти ћеш га опсјести. То ће бити знак дому Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Потом лези на лијеву страну своју, и метни на њу безакоње дома Израиљева; колико дана узлежиш на њој, толико ћеш носити њихово безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'А ја ти дајем године безакоња њихова бројем дана, триста и деведесет дана, и толико ћеш носити безакоње дома Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'А кад их навршиш, онда лези на десну страну своју, и носи безакоње дома Јудина четрдесет дана; по један дан дајем ти за годину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'И окрени лице своје према опкољеном Јерусалиму загаливши мишицу своју, и пророкуј против њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'И ево везаћу те узицама да се не преврнеш с једне стране на другу докле не навршиш дане опсаде своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'И узми пшенице и јечма и боба и лећа и проса и крупника, и саспи све у један суд, и начини од тога себи хљеба према броју дана у које ћеш лежати на својој страни, три стотине и деведесет дана јешћеш га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'И јела твојега што ћеш јести нека буде мјером двадесет сикала на дан; на рокове једи га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'И воду пиј мјером, по шестину ина, пиј на рокове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'А хљеб пријесан јечмен једи, испекав га на калу човјечијем на њихове очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'И рече Господ: тако ће јести синови Израиљеви хљеб свој нечист међу народима у које ћу их разагнати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Тада рекох: ах Господе Господе, гле, душа се моја није оскврнила, јер од дјетињства својега досада нијесам јео мрцинога ни што би звијерка раздрла, нити је ушло у уста моја месо нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'А он ми рече: види, дајем ти говеђу балегу мјесто човјечијега кала, да на њој испечеш себи хљеб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Затијем рече ми: сине човјечји, ево ја ћу сломити потпору у хљебу у Јерусалиму, те ће јести хљеб на мјеру и у бризи, и воду ће пити на мјеру и у чуду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Јер ће им нестати хљеба и воде да ће се чудити међу собом и сасушиће се од безакоња својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Потом, сине човјечји, узми нож оштар, бритву бријачку узми, и пусти је по глави својој и по бради својој, па узми мјерила и раздијели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Трећину сажези огњем усред града, кад се наврше дани опсаде, а другу трећину узми и исијеци мачем око њега, а осталу трећину разметни у вјетар, и ја ћу извући мач за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Али узми мало, и завежи у скут свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'И од тога још узми и баци у огањ и сажези огњем; одатле ће изаћи огањ на сав дом Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Овако вели Господ Господ: ово је Јерусалим који поставих усред народа и опточих га земљама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Али промијени законе моје на безакоње већма него народи, и уредбе моје већма него земље што су око њега, јер одбацише моје законе, и не ходише по мојим уредбама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Зато овако вели Господ Господ: што постасте гори од народа који су око вас, не ходисте по мојим уредбама и не извршивасте мојих закона, па ни по уредбама народа који су око вас не чинисте,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Зато овако вели Господ Господ: ево и мене на те, и извршићу усред тебе судове на видику народима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'И учинићу ти што још нијесам учинио нити ћу више учинити за све гадове твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Зато оци ће јести синове усред тебе, и синови ће јести оце своје, и извршићу на теби судове и расијаћу сав остатак твој у све вјетрове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Зато, тако ја жив био, вели Господ Господ, што си оскврнио моју светињу свакојаким нечистотама својим и свакојаким гадовима својим, зато ћу и ја тебе потрти, и неће око моје жалити, нити ћу се смиловати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Трећина ће твоја помријети од помора, и од глади ће изгинути усред тебе, а друга ће трећина пасти од мача око тебе, а трећину ћу расијати у све вјетрове, и извући ћу мач за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'И тако ће се извршити гњев мој и намирићу јарост своју на њима и задовољићу се, и они ће познати да сам ја Господ говорио у ревности својој кад извршим гњев свој на њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'И учинићу од тебе пустош и руг међу народима који су око тебе пред сваким који пролази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'И бићеш руг и срамота и наук и чудо народима што су око тебе кад извршим судове на теби гњевом, јарошћу и љутијем карањем; ја Господ рекох;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Кад пустим на вас љуте стријеле глади, које ће бити смртне, које ћу пустити да вас затрем, и кад глад навалим на вас и сломим вам потпору у хљебу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Кад пустим на вас глад и љуте звијери, које ће ти дјецу изјести; и кад помор и крв прођу кроза те, и кад пустим мач на те. Ја Господ рекох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Сине човјечји, окрени лице своје према горама Израиљевијем, и пророкуј против њих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'И реци: горе Израиљеве, чујте ријеч Господ Господа, овако вели Господ Господ горама и хумовима, потоцима и долинама: ево ме, ја ћу пустити на вас мач и оборићу висине ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'И ваши ће се олтари раскопати, и сунчани ликови ваши изломиће се, и поваљаћу побијене ваше пред гаднијем боговима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'И побацаћу мртва тјелеса синова Израиљевијех пред гадне богове њихове, и разметнућу кости ваше око олтара ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Свуда гдје наставате градови ће се опустошити и висине ће опустјети, и олтари ће се ваши раскопати и опустјети, и гадни богови ваши изломиће се и неће их више бити, и сунчани ликови ваши исјећи ће се, и дјела ће се ваша уништити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'И побијени ће падати усред вас, и познаћете да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Али ћу вас оставити неколико који би утекли од мача међу народима кад се расијете по земљама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'И који вас утеку, опоменуће се мене међу народима, гдје буду у ропству, како ми дотужаше срцем својим курварским које отступи од мене, и очима својим курварским, којима идоше за гаднијем боговима својим, и сами ће себи бити мрски за зла која чинише у свијем градовима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'И познаће да сам ја Господ и да нијесам говорио узалуд да ћу им учинити то зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Овако вели Господ Господ: пљесни рукама и лупи ногом, и реци: јаох! ради свијех гаднијех зала дома Израиљева, јер ће пасти од мача, од глади и од помора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Ко буде далеко, умријеће од помора; а ко буде близу, пашће од мача; а ко остане и буде опкољен, умријеће од глади; тако ћу навршити гњев свој на њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'И познаћете да сам ја Господ кад буду побијени њихови међу гаднијем боговима њиховијем, око олтара њиховијех, на сваком високом хуму и на свијем врховима горским и под сваким зеленијем дрветом и под сваким гранатијем храстом, свуда гдје су кадили угоднијем мирисима свијем гаднијем боговима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Јер ћу замахнути руком својом на њих, и обратићу земљу њихову у пустош гору од пустиње Дивлате по свијем становима њиховијем; и познаће да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Потом дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Сине човјечји, овако каже Господ Господ за земљу Израиљеву: крај, дође крај на четири стране земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Дође ти крај, и пустићу гњев свој на те, и судићу ти по путовима твојим и обратићу на те све гадове твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'И око моје неће те пожалити, нити ћу се смиловати, него ћу путове твоје обратити на те, и гадови ће твоји бити усред тебе, и познаћете да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Овако вели Господ Господ: зло, једно зло, ево иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Крај дође, крај дође, уста на те, ево дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Дође јутро теби, становниче земаљски, дође вријеме, приближи се дан, кад ће бити полом а не јека горска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Сада ћу одмах излити јарост своју на те, и навршићу гњев свој на теби, и судићу ти по твојим путовима, и обратићу на те све гадове твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Неће жалити око моје, нити ћу се смиловати, даћу ти по путовима твојим, и гадови ће твоји бити усред тебе, и познаћете да сам ја Господ, који бије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Ево дана, ево дође, јутро наста, процвате прут, поноситост напупи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Насиље нарасте прут безакоња, нико неће остати од њих ни од мноштва њихова ни од буке њихове, нити ће бити нарицања за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Дође вријеме, приспје дан; ко купује нека се не радује, и ко продаје нека не жали, јер ће доћи гњев на све људство њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Јер ко продаје, неће опет доћи до онога што прода, ако и остане жив; јер утвара за све мноштво њихово неће се вратити натраг, и нико се неће окријепити безакоњем својим да сачува живот свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Затрубише у трубе, и спремише све; али нема никога да изађе у бој, јер се гњев мој распалио на све људство њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Напољу мач, а унутра помор и глад; ко буде у пољу, погинуће од мача; а ко буде у граду, њега ће глад и помор прождријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'А који их утеку, избавиће се и биће по горама као голубови из долина, сви ће уздисати, сваки за своје безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Све ће руке клонути и сва ће кољена постати као вода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'И припасаће око себе костријет, и дрхат ће их попасти, и на сваком ће лицу бити стид, и све ће им главе бити ћелаве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Сребро ће своје побацати по улицама, и злато ће њихово бити као нечистота; сребро њихово и злато њихово неће их моћи избавити у дан гњева Господњега; неће наситити душе своје нити ће напунити трбуха својега, јер им је безакоње њихово спотицање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Јер славни накит свој обратише на охолост, и начинише од њега ликове гадова својих, гнусобе своје; зато учиних да им је нечистота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'И даћу га у руке иностранцима да га разграбе, и безбожницима на земљи да је плијен, и оскврниће га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'И одвратићу лице своје од њих, и оскврниће светињу моју, и ући ће у њу лупежи и оскврниће је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Начини вериге, јер је земља пуна крвнога суда, и град је пун насиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Зато ћу довести најгоре између народа да наслиједе куће њихове, и укинућу охолост силнијех, и света мјеста њихова оскврниће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Иде погибао; они ће тражити мира, али га неће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Невоља за невољом долазиће, и глас за гласом стизаће; и они ће тражити утвару од пророка; закона ће нестати у свештеника и свјета у стараца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Цар ће тужити, и кнезови ће се обући у жалост, и руке народу земаљском дрктаће; учинићу им по путовима њиховијем и судићу им према судовима њиховијем; и познаће да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'А шесте године, шестога мјесеца, дана петога, кад сјеђах у својој кући и старјешине Јудине сјеђаху преда мном, паде ондје на ме рука Господа Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'И видјех, а то облик на очи као огањ, од бедара му доље бјеше огањ, а од бедара горе бјеше као свјетлост, као јака свјетлост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'И пружи као руку, и ухвати ме за косу на глави, и подиже ме дух међу небо и земљу, и однесе ме у Јерусалим у утвари Божјој на врата унутрашња која гледају на сјевер, гдје стајаше идол од ревности, који дражи на ревност.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'И гле, ондје бјеше слава Бога Израиљева на очи као она што је видјех у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'И рече ми: сине човјечји, подигни очи своје к сјеверу. И подигох очи своје к сјеверу, и гле, са сјевера на вратима олтарским бијаше онај идол од ревности на уласку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Потом ми рече: сине човјечји, видиш ли што ти раде? велике гадове које ту чини дом Израиљев да отидем далеко од светиње своје? Али ћеш још видјети већих гадова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'И одведе ме на врата од тријема, и погледах, а то једна рупа у зиду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'А он ми рече: сине човјечји, прокопај овај зид. И прокопах зид, а то једна врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Тада ми рече: уђи и види опаке гадове које чине ту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'И ушав видјех, и гле, свакојаке животиње што гамижу и свакојаки гадни скотови, и сви гадни богови дома Израиљева бијаху написани по зиду свуда унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'И пред њима стајаше седамдесет људи између старјешина дома Израиљева с Јазанијом сином Сафановијем, који стајаше међу њима, сваки с кадионицом својом у руци, и подизаше се густ облак од када.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Тада ми рече: видиш ли, сине човјечји, шта чине старјешине дома Израиљева у мраку свак у својој писаној клијети? јер говоре: не види нас Господ, оставио је Господ ову земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Потом ми рече: још ћеш видјети већих гадова које они чине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'И одведе ме на врата дома Господњега која су са сјевера; и гле, жене сјеђаху и плакаху за Тамузом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'И рече ми: јеси ли видио, сине човјечји? још ћеш видјети већих гадова од тијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'И одведе ме у тријем унутрашњи дома Господњега; и гле, на уласку у цркву Господњу између тријема и олтара бјеше око двадесет и пет људи окренутијех леђима к цркви Господњој лицем к истоку, и клањаху се сунцу према истоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Тада ми рече: јеси ли видио, сине човјечји? мало ли је дому Јудину што чине те гадове које чине овдје? него још напунише земљу насиља и окренуше се да ме драже; и ето држе грану пред носом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Зато ћу и ја учинити у гњеву, неће жалити око моје, нити ћу се смиловати, и кад стану викати иза гласа у моје уши, нећу их услишити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Потом повика иза гласа, те чух, и рече: приступите који сте послани на град сваки с оружјем својим смртнијем у руци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'И гле, шест људи дође до високих врата, која гледају на сјевер, сваки са својим оружјем смртнијем у руци, и међу њима бјеше један човјек обучен у платно с оправом писарском уз бедрицу; и дошавши стадоше код олтара мједенога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'А слава Бога Израиљева подиже се с херувима, на којима бијаше, на праг од дома, и викну човјека обученога у платно који имаше уз бедрицу оправу писарску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'И рече му Господ: прођи посред града, посред Јерусалима, и забиљежи биљегом чела онијем људима који уздишу и који ридају ради свијех гадова што се чине усред њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'А другима рече и чух: прођите за њим по граду, и побијте, нека не жали око ваше нити се смилујте;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Старце и младиће, и дјевојке и дјецу и жене побијте да се истријебе; али на коме год буде знак, к њему не приступајте; и почните од моје светиње. И почеше од моје светиње. И почеше од старјешина што бјеху пред домом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'И рече им: оскврните дом, и напуните тријемове побијенијех; идите. И изашавши стадоше убијати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'А кад убијаху и ја остах, падох на лице своје и повиках и рекох: јаох Господе Господе, еда ли ћеш затрти сав остатак Израиљев изливши гњев свој на Јерусалим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'А он им рече: безакоње дома Израиљева и Јудина превелико је, и пуна је земља крви, и град је пун опачине; јер рекоше: Господ је оставио земљу, и Господ не види.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Зато ни моје око неће жалити, нити ћу се смиловати; пут њихов обратићу на главу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'И гле, човјек, обучен у платно, којему уз бедрицу бијаше оправа писарска, јави говорећи: учинио сам како си ми заповједио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Потом видјех, и гле, на небу које бијаше над главама херувимима показа се над њима као камен сафир на очи као пријесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'И проговори човјеку обученом у платно, и рече: уђи међу точкове под херувимима, и узми пуне прегршти жеравице између херувима и разаспи на град. И уђе на моје очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'А херувими стајаху с десне стране дома кад уђе човјек, и облак напуни унутрашњи тријем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'И слава Господња подиже се с херувима на праг од дома, и напуни се дом облака, а тријем се напуни свјетлости славе Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'И лупа крила у херувима чујаше се до спољашњега тријема као глас Бога свемогућега кад говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'И кад заповједи човјеку обученоме у платно говорећи: узми огња између точкова између херувима; он уђе и стаде код точкова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'И један херувим пружи руку своју између херувима к огњу који бијаше међу херувимима, и узе и метну у прегршти обученоме у платно, и он прими и изиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'А виђаше се у херувима као рука човјечија под крилима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'И видјех, и гле, четири точка код херувима, по један точак код једнога херувима, и точкови бијаху на очи као камен хрисолит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'И на очи бијаху сва четири точка једнака, и као да је точак у точку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Кад иђаху, иђаху сва четири, сваки на своју страну, и идући не скретаху, него куда гледаше глава онамо иђаху и идући не скретаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'А све им тијело и леђа и руке и крила и точкови, сва четири точка њихова, бијаху пуна очију свуда унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'А точкови се зваху како чух: кола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'А четири лица имаше свака животиња: једно лице херувимско, друго лице човјечије и треће лице лавово и четврто лице орлово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'И подигоше се херувими у вис; то бијаху исте животиње које видјех на ријеци Хевару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'А кад иђаху херувими, иђаху и точкови уз њих, и кад херувими махаху крилима својим да се подигну од земље, точкови се не одмицаху од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Кад се они устављаху, устављаху се и точкови; а кад се они подизаху, подизаху се и точкови; јер бијаше дух животињски у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'И слава Господња отиде изнад прага од дома, и стаде над херувиме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'И херувими махнувши крилима подигоше се од земље преда мном полазећи, и точкови према њима; и стадоше на источнијем вратима дома Господњега, и слава Бога Израиљева бијаше озго над њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'То бијаху исте животиње које видјех под Богом Израиљевијем на ријеци Хевару, и познах да су херувими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Свака имаше четири лица и четири крила, и као рука човјечија бјеше им под крилима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'И лица им бијаху иста која видјех на ријеци Хевару; обличја бијаху иста, исти бијаху; сваки иђаше право напрема се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Тада ме подиже дух, и однесе ме на источна врата дома Господњега која гледају на исток, и гле, на вратима бијаше двадесет и пет људи, и међу њима видјех Језанију сина Азурова и Фелатију сина Венајина, поглаваре народне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'И рече ми: сине човјечји, ови људи смишљају безакоње, и зло свјетују у том граду,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Говорећи: није близу; да градимо куће; овај је град лонац а ми месо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Зато пророкуј против њих, пророкуј, сине човјечји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'И паде на ме дух Господњи и рече ми: реци: овако вели Господ: доме Израиљев, тако говористе, и знам мисли срца вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Многе побисте у том граду, и напунисте улице њихове побијенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Зато овако вели Господ Господ: које побисте и побацасте усред њега, они су месо, а он је лонац, а вас ћу извести из њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Бојите се мача; мач ћу пустити на вас, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'И извешћу вас из њега, и даћу вас у руке туђинцима, и извршићу на вама судове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Од мача ћете пасти, на међи Израиљевој судићу вам, и познаћете да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Овај град неће вам бити лонац нити ћете ви бити у њему месо; на међи Израиљевој судићу вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'И познаћете да сам ја Господ, јер по уредбама мојим не ходисте нити закона мојих извршивасте, него чинисте по законима тијех народа што су око вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'А кад пророковах, умрије Фелатија син Венајин; тада падох на лице своје и повиках иза гласа и рекох: јаох Господе Господе! хоћеш ли да истријебиш остатак Израиљев?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'А глас Господњи дође ми говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Сине човјечји, браћа су твоја, браћа твоја, родбина твоја и дом Израиљев васколики, којима говорише Јерусалимљани: идите далеко од Господа, нама је дата земља у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Зато реци: овако вели Господ Господ: ако их и одагнах далеко међу народе, ако их и расијах по земљама, опет ћу им бити светиња за мало у земљама у које отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Зато реци: овако вели Господ Господ: сабраћу вас из народа и покупићу вас из земаља у које се расијасте, и даћу вам земљу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'И кад дођу у њу, избациће из ње све гадове њезине и све гнусобе њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'И даћу им једно срце и нов дух метнућу у њих, и извадићу из тијела њихова камено срце и даћу им срце месно,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'Да би ходили по мојим уредбама и држали моје законе и извршивали их; и биће ми народ, и ја ћу им бити Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'А којима срце иде по жељи гнусоба њиховијех и гадова њиховијех, њихов ћу пут обратити на њихову главу, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Потом махнуше херувими крилима својим, и точкови отидоше према њима, и слава Бога Израиљева бјеше озго над њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'И подиже се слава Господња исред града, и стаде на гори која је с истока граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'А мене дух подиже и однесе у утвари духом Божјим у Халдејску к робљу; и утвара коју видјех отиде од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'И казах робљу све ријечи Господње што ми показа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Сине човјечји, усред дома одметничкога сједиш, који има очи да види и не види, има уши да чује и не чује; јер су дом одметнички.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Зато ти, сине човјечји, спреми што треба за сеобу, и сели се обдан на њихове очи; и исели се из својега мјеста на друго мјесто на њихове очи, не би ли видјели, јер су дом одметнички.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'И изнеси ствари своје као кад се ко сели обдан на њихове очи, а сам изиди увече на њихове очи као они који се селе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'На њихове очи прокопај зид, и изнеси своје ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'На њихове очи дигни на рамена и изнеси по мраку, лице своје покриј да не видиш земље, јер те дадох да будеш знак у дому Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'И учиних тако како ми се заповједи; ствари своје изнесох обдан као кад се сели; а увече прокопах зид руком; и по мраку изнесох на раменима носећи на њихове очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'А ујутру дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Сине човјечји, рече ли ти дом Израиљев, дом одметнички: што радиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Реци им: овако вели Господ Господ: ово је бреме за кнеза који је у Јерусалиму и за сав дом Израиљев што је ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Реци: ја сам вам знак, како ја учиних тако ће им бити; преселиће се и отићи у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'И кнез који је међу њима носећи на раменима по мраку ће изаћи; они ће прокопати зид да изнесу; он ће покрити лице своје да не види земље очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Али ћу му разапети мрежу своју и ухватиће се у замку моју, и одвешћу га у Вавилон, у земљу Халдејску, али је неће видјети, а ондје ће умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'И све који су око њега, помоћнике његове, и сву војску његову расијаћу у све вјетрове, и извући ћу мач за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'И познаће да сам ја Господ кад их расијем по народима и разаспем по земљама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'А оставићу их неколико људи који ће остати од мача и од глади и од помора да приповиједају све гадове своје међу народима у које отиду; и познаће да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Сине човјечји, хљеб свој једи презајући и воду своју пиј дркћући и бринући се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'И реци народу земаљском: овако вели Господ Господ за становнике Јерусалимске, за земљу Израиљеву: хљеб ће свој јести у бризи и воду ће своју пити препадајући се, јер ће земља опустјети и остати без свега што је у њој за безакоње свијех који живе у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'И градови у којима живе опустјеће, и земља ће бити пуста, и познаћете да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Сине човјечји, кака је то прича у вас о земљи Израиљевој што говорите: протежу се дани, и од утваре неће бити ништа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Зато им реци: овако вели Господ Господ: укинућу ту причу и нећу је више говорити у Израиљу; него им реци: близу су дани и ријеч сваке утваре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Јер неће више бити у дому Израиљеву залудне утваре ни гатања којим се ласка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Јер ћу ја Господ говорити, и што речем збиће се; неће се више одгађати, него за вашега времена, доме одметнички, рећи ћу ријеч и извршићу је, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Сине човјечји, гле, дом Израиљев говори: утвара коју тај види, до ње има много времена, и за далеко вријеме тај пророкује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Зато им реци: овако вели Господ Господ: неће се више одгађати ниједна моја ријеч; ријеч коју речем збиће се, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Сине човјечји, пророкуј против пророка Израиљевијех који пророкују, и реци тијем који пророкују из свога срца: чујте ријеч Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Овако говори Господ Господ: тешко лудијем пророцима који иду за својим духом а ништа нијесу видјели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Пророци су твоји, Израиљу, као лисице по пустињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Не излазите на проломе и не ограђујете дома Израиљева да би се одржао у боју у дан Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Виде таштину и гатање лажно, па говоре: Господ каже, а Господ их није послао, и дају над да ће се ријеч испунити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Не виђате ли ташту утвару и не говорите ли лажно гатање? а опет кажете: Господ рече; а ја не рекох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Зато овако вели Господ Господ: зато што говорите таштину и видите лаж, зато ево мене на вас, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'И рука ће моја бити против пророка који виде таштину и гатају лаж; неће их бити у збору народа мога, и у пријепису дома Израиљева неће бити записани, нити ће доћи у земљу Израиљеву; и познаћете да сам ја Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Зато, зато што преластише народ мој говорећи: мир је, а мира не бјеше; и један озида зид, а други га намазаше кречем неваљалијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Реци онијем што мажу неваљалијем кречем да ће пасти; доћи ће силан дажд, и ви, камење великога града, пашћете и олуја ће развалити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'И гле, кад падне зид, неће ли вам се рећи: гдје је креч којим мазасте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Зато овако вели Господ Господ: развалићу олујом у гњеву свом, и силан ће дажд доћи у гњеву мом, и камење великога града у јарости мојој да потре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'И развалићу зид који намазасте неваљалијем кречем, и оборићу га на земљу да ће му се открити темељ, и пашће, и ви ћете изгинути усред њега, и познаћете да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'И тако ћу навршити гњев свој на зиду и на онима који га мажу кречем неваљалијем, и рећи ћу вам: нема зида, нити онијех који га мазаше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Пророка Израиљевијех који пророкују Јерусалиму и виде му утваре за мир, а мира нема, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'А ти, сине човјечји, окрени лице своје према кћерима народа својега, које пророкују из свога срца, и пророкуј против њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'И реци: овако вели Господ Господ: тешко онима које шију узглавља под све лактове и граде покривала на главу свакога раста да лове душе. Ловите душе мојега народа, а своје ли ћете душе сачувати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'И скврните ме код народа мојега за грст јечма и за залогај хљеба убијајући душе, које не би требало да умру, и чувајући у животу душе које не треба да живе, лажући народу мојему, који слуша лаж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Зато овако вели Господ Господ: ево мене на ваша узглавља, на која ловите душе да вам долијећу, и подераћу их испод лаката ваших, и пустићу душе које ловите да вам долијећу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'И подераћу покривала ваша и избавићу свој народ из ваших руку, и неће више бити у вашим рукама да вам буду лов, и познаћете да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Јер жалостисте лажју срце праведнику, којега ја не ожалостих, и кријеписте руке безбожнику да се не врати са свога злога пута да се сачува у животу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Зато нећете виђати таштине и нећете више гатати, него ћу избавити народ свој из ваших руку, и познаћете да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Потом дођоше к мени неки од старјешина Израиљевијех и сједоше преда ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'И дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Сине човјечји, ови су људи ставили у срца своја гадне богове своје, и метнули су преда се о што се спотичу на безакоње своје; траже ли ме доиста?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Зато говори им и реци им: овако вели Господ Господ: ко је год од дома Израиљева ставио у срце своје гадне богове своје и метнуо преда се о што се спотиче на безакоње своје, па дође к пророку, ја Господ одговорићу му кад дође за мноштво гаднијех богова његовијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Да ухватим дом Израиљев за срце њихово што су се одвратили од мене сви за гаднијем боговима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Зато реци дому Израиљеву: овако вели Господ Господ: обратите се и отступите од гаднијех богова својих, одвратите лице своје од свијех гадова својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Јер ко би год од дома Израиљева или од иностранаца који живе у Израиљу отступио од мене, и ставио у срце своје гадне богове своје, и метнуо преда се о што ће се спотицати на безакоње своје, па би дошао к пророку да ме упита преко њега, њему ћу одговорити ја сам Господ собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'И окренућу лице своје према том човјеку, и учинићу од њега знак и причу, и истријебићу га из народа својега, те ћете познати да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'И ако би се пророк преварио, те рекао што, ја Господ преварих онога пророка, и дигнућу руку своју на њ, и истријебићу га из народа својега Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'И понијеће обојица своје безакоње: како је безакоње онога који пита тако ће бити и пророково безакоње,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'Да више дом Израиљев не отступа од мене и да се више не скврне свакојаким пријеступима својим, него да ми буду народ, и ја да им будем Бог, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Сине човјечји, ако ми која земља згријеши учинивши невјеру, и ја дигнем руку своју на њу и сломим јој потпору у хљебу, и пустим на њу глад и истријебим у њој људе и стоку,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'Ако би у њој била ова три човјека: Ноје, Данило и Јов, они ће правдом својом избавити душе своје, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Ако пустим љуте звијери у земљу, те поморе људе, и она опусти да нико не може пролазити од звијерја;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'Ако би у њој била та три човјека, тако ја жив био, говори Господ Господ, неће избавити синова ни кћери, него ће се сами избавити, а земља ће опустјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Или ако мач пустим на ту земљу, и речем: мачу, прођи ту земљу, да истријебим у њој људе и стоку;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'Ако би та три човјека била у њој, тако ја био жив, говори Господ Господ, неће избавити синова ни кћери, него ће се сами избавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Или ако пустим помор на земљу и излијем гњев свој на њу да би крв текла да истријебим у њој људе и стоку;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'Ако би Ноје, Данило и Јов били у њој, тако ја жив био, говори Господ Господ, неће избавити сина ни кћери, него ће своје душе избавити правдом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Јер овако вели Господ Господ: акамоли кад пустим четири љута зла своја, мач и глад и зле звијери и помор на Јерусалим, да истријебим у њему људе и стоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'И опет, гле, неколико ће их остати у њему који ће се избавити, синови или кћери, они ће изаћи к вама, и видјећете пут њихов и дјела њихова, и утјешићете се за зло које ћу пустити на Јерусалим, за све што ћу пустити на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'И они ће вас утјешити кад видите пут њихов и дјела њихова; и познаћете да нијесам без узрока учинио што сам год учинио у њему, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Сине човјечји, шта је дрво од лозе винове према сваком другом дрвету, или лоза винова према дрвећу у шуми?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Узима ли се од ње дрво да се начини што? узима ли се од ње клин да се објеси о њему какав суд?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Гле, меће се у огањ да изгори; кад јој оба краја сажеже огањ, и средина јој изгори, хоће ли још бити за што?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Гле, док бијаше цијела, не могаше се ништа од ње начинити, а камо ли ће бити за што кад је огањ прождрије и изгорје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Зато овако вели Господ Господ: какво је међу дрветима шумским дрво од винове лозе, које дадох огњу да га једе, таке ћу учинити становнике Јерусалимске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Јер ћу им насупрот окренути лице своје; кад изиду из једнога огња, други ће их огањ прождријети, и познаћете да сам ја Господ, кад окренем лице своје насупрот њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'И обратићу земљу у пустињу, јер учинише невјеру, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Сине човјечји, покажи Јерусалиму гадове његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'И реци: овако вели Господ Господ Јерусалиму: постањем и родом ти си из земље Хананске; отац ти бјеше Аморејац а мати Хетејка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'А о рођењу твом, кад си се родила, није ти пупак одрезан и нијеси окупана водом да би била чиста, нити си сољу натрвена ни пеленама повита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Око те не пожали да ти учини што од тога и да ти се смилује; него ти би бачена у поље, јер бијаше мрска душа твоја онога дана кад си се родила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'И идући мимо тебе и видјевши те гдје се ваљаш у својој крви, рекох ти: да си жива у својој крви! и опет ти рекох: да си жива у својој крви!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'И учиних да растеш на тисуће као трава у пољу; и ти нарасте и поста велика и дође до највеће љепоте; дојке ти напупише, и длаке те пробише; али ти бијаше гола нага.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'И идући мимо тебе погледах те, и гле, године ти бијаху године за љубљење; и раширих скут свој на те, и покрих голотињу твоју, и заклех ти се и учиних вјеру с тобом, говори Господ Господ, и ти поста моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'И окупах те водом, и спрах с тебе крв твоју, и помазах те уљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'И обукох ти везену хаљину, и обух ти цревље од јазавца, и опасах те танким платном и застријех те свилом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'И накитих те накитом, и метнух ти наруквице на руке и гривну око врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'И гривну око чела метнух ти, и обоце у уши, славан вјенац на главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'И ти бијаше окићена златом и сребром, и одијело ти бијаше од танкога платна и од свиле и везено, јеђаше бијело брашно и мед и уље, и бијаше врло лијепа, и приспје до царства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'И разиде се глас о теби по народима ради љепоте твоје, јер бјеше савршена красотом мојом, коју метнух на те, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Али се ти ослони на љепоту своју, и прокурва се с гласа својега, те си просипала курварство своје свакоме који пролажаше, и бивала си његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'И узевши од хаљина својих начинила си шарене висине, и курвала си се на њима, како нигда није било нити ће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'И узевши красни накит свој од мога злата и од мога сребра што ти дадох, начинила си себи мушке ликове, и курвала си се с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'И узевши везене хаљине своје заодјела си их, и уље моје и кад мој ставила си пред њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'И хљеб мој, који ти дадох, бијело брашно и уље и мед, чим те храњах, поставила си пред њих за мирис угодни. Тако је било, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'И узимала си синове своје и кћери своје које си родила, и њих си им приносила да се спале. Мало ли бјеше курварства твојега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Те си и синове моје клала и давала си их да им се проведу кроз огањ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'И уза све гадове своје и курварства своја нијеси се опомињала дана младости своје кад си била гола и нага и ваљала се у крви својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'И послије све злоће своје, тешко, (тешко теби! говори Господ Господ,)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'Саградила си себи кућу курварску, и начинила си себи висине на свакој улици,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'На свакој распутици начинила си себи висину, и нагрдила си своју љепоту, и разметала си ноге своје свакоме који пролажаше, и умножила си курварство своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Курвала си се са синовима Мисирским, сусједима својим велика тијела, и умножила си курварство своје да би ме разгњевила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Зато, гле, дигох руку своју на те и умалих оброк твој, и дадох те на вољу ненавидницима твојима, кћерима Филистејским, које бјеше стид од срамотнога пута твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Курвала си се са синовима Асирским, јер се не могаше наситити; курвала си се с њима, и опет се нијеси наситила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'И умножила си курварство своје у земљи Хананској дори до Халдејске, и ни тако се нијеси наситила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Како је изнемогло срце твоје, говори Господ Господ, кад чиниш све што чини најгора курва,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Кад си градила курварску кућу на свакој распутици и чинила висину на свакој улици! А ни као курва нијеси, јер нијеси марила за плату;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Него као жена прељубочиница, која мјесто мужа свога прима друге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Свијем курвама даје се плата, а ти си давала плату свијем милосницама својим и даривала си их да долазе к теби са свијех страна да се курвају с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'И тако је у тебе наопако према женама у твом курварству: јер нико не иде за тобом да се курва, и ти дајеш плату, а не даје се теби плата; то је наопако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Зато, курво, чуј ријеч Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Овако вели Господ Господ: што се отров твој просу, и што се у курвању твом откривала голотиња твоја твојим милосницама и свијем гаднијем идолима твојим, и за крв синова твојих, које си им дала,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'Зато, ево, ја ћу скупити све милоснике твоје, с којима си се миловала, и све које си љубила, и све на које си мрзила, скупићу их све око тебе, и открићу им голотињу твоју да виде сву голотињу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'И судићу ти како се суди онима које чине прељубу и онима које крв прољевају, и даћу те на смрт гњеву и ревности.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'И предаћу те у њихове руке, те ће разорити твоју кућу курварску и раскопати висине твоје, и свући ће хаљине с тебе, и узеће ти красни накит и оставиће те голу нагу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'И довешће на те људство, те ће те засути камењем, и избошће те мачевима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'И попалиће куће твоје огњем, и извршиће на теби суд пред многим женама, и учинићу те ћеш се оканити курвања и нећеш више давати плате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'И намирићу гњев свој над тобом, и ревност ће се моја уклонити од тебе, и умирићу се, и нећу се више гњевити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Зато што се нијеси опомињала дана младости своје, него си ме дражила свијем тијем, зато, ево, и ја ћу обратити пут твој на твоју главу, говори Господ Господ, те нећеш чинити грдила нити каквих гадова својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Гле, ко год говори приче, говориће о теби причу, и рећи ће: кака мати, така јој кћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Ти си кћи матере своје, која се одметнула мужа својега и дјеце своје, и сестра си сестара својих, које се одметнуше мужева својих и дјеце своје, мати вам је Хетејка а отац Аморејац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'А старија ти је сестра Самарија с кћерима својим, која ти сједи с лијеве стране, а млађа ти је сестра која ти сједи с десне стране Содом са кћерима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'А ти ни њиховијем путем нијеси ходила, нити си чинила по њиховијем гадовима, као да ти то бјеше мало, него си била гора од њих на свијем путовима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Тако ја жив био, говори Господ Господ, сестра твоја Содом и кћери њезине нијесу чиниле како си чинила ти и твоје кћери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Ево, ово бјеше безакоње сестре твоје Содома: у поносу, у изобиљу хљеба и безбрижном миру бјеше она и кћери њезине, а не помагаху сиромаху и убогоме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Него се понашаху и чињаху гадове преда мном, зато их затрх кад видјех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Самарије није згријешила ни пола колико ти, јер си починила гадова својих више него оне, те си оправдала сестре своје свијем гадовима својим које си учинила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'И ти дакле, која си судила сестрама својим, носи срамоту своју за гријехе своје, којима си постала грђа од њих; оне су праведније од тебе; и ти се дакле стиди и носи срамоту, кад си оправдала сестре своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Ако доведеш натраг њихово робље, робље Содомско и кћери њезинијех, и робље Самаријско и кћери њезинијех, довешћу и твоје робље из ропства међу њима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'Да носиш срамоту своју и да се стидиш за све што си чинила, и да им будеш утјеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Ако се сестре твоје, Содом и кћери њезине поврате као што су биле, и ако се Самарија и кћери њезине поврате као што су биле, повратићеш се и ти и кћери твоје као што сте биле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Јер уста твоја не помињаше Содома сестре твоје у вријеме охолости твоје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'Прије него се откри злоћа твоја као у вријеме срамоте од кћери Сирских и од свијех што су око њих, кћери Филистејских, које те срамоћаху са свијех страна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Носи неваљалство своје и гадове своје, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Јер овако вели Господ Господ: учинићу ти како си ти учинила презревши заклетву и преступивши завјет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Али ћу се ја опоменути завјета својега који сам учинио с тобом у вријеме младости твоје, и утврдићу ти вјечан завјет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Тада ћеш се опоменути путова својих и постидјећеш се кад примиш сестре своје старије од себе и млађе, које ћу ти дати за кћери, али не по твом завјету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'И ја ћу утврдити свој завјет с тобом, и познаћеш да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Да се опоменеш и постидиш и да не отвориш више уста од срамоте, кад ти опростим све што си учинила, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Сине човјечји, загонени загонетку и кажи причу о дому Израиљеву,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'И реци: овако вели Господ Господ: орао велик, великих крила, дугих пера, пун перја, шарен, дође на Ливан и узе врх од кедра,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Одломи врх од младијех грана његовијех, и однесе га у земљу трговачку, у град трговачки метну га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'И узе сјеме из оне земље, и метну га на њиву, однесе га гдје има много воде, и остави га добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'И изниче, и поста бусат чокот, низак, којему се лозе пружаху к њему а жиле бијаху под њим; поста чокот, и пусти гране и изби одводе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'А бијаше други орао велик, великих крила и пернат, и гле, тај чокот пусти к њему жиле своје и гране своје пружи к њему да би га заљевао из бразда свога сада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Посађен бијаше у доброј земљи код много воде, да пусти гране и рађа род и буде красна лоза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Кажи: овако вели Господ Господ: хоће ли напредовати? неће ли му почупати жиле и род му обломити да се посуши? Све ће му се гране што је пустио посушити, и без велике силе и без многога народа ишчупаће га из коријена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Ето, посађен је, хоће ли напредовати? и неће ли се сасвијем посушити чим га се дохвати устока? Посушиће се у бразди гдје је посађен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Потом дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Кажи томе дому одметничком: не знате ли шта је ово? Реци: ево, дође цар Вавилонски у Јерусалим, и узе му цара и кнезове, и одведе их са собом у Вавилон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'И узе једнога од царскога сјемена, и учини с њим вјеру, и закле га, и узе силне у земљи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'Да би царство било снижено да се не би подигло, него да би држећи вјеру с њим стајало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Али се одметну од њега послав посланике своје у Мисир да му да коња и много народа. Хоће ли бити срећан? хоће ли утећи ко тако чини? ко преступа вјеру хоће ли утећи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Тако ја жив био, говори Господ Господ, у мјесту онога цара који га је зацарио, којему је заклетву презрео и којему је вјеру преступио, код њега ће у Вавилону умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Нити ће му Фараон с великом војском и многим народом помоћи у рату, кад ископа опкопе и погради куле да погуби многе душе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Јер презре заклетву преступајући вјеру; и гле, давши руку чини све то; неће утећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Зато овако вели Господ Господ: тако ја жив био, обратићу му на главу заклетву своју коју презре и вјеру своју коју преступи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Јер ћу разапети над њим мрежу своју и ухватиће се у замку моју; и одвешћу га у Вавилон, и ондје ћу се судити с њим за безакоње које ми учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'И сва бјежан његова са свом војском његовом пашће од мача, а који остану распршаће се у све вјетрове, и познаћете да сам ја Господ говорио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Овако вели Господ Господ: али ћу ја узети с врха од тога високога кедра, и посадићу; с врха од младијех грана његовијех одломићу гранчицу, и посадићу на гори високој и уздигнутој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'На високој гори Израиљевој посадићу је, и пустиће гране, и родиће, и постаће красан кедар, и под њим ће наставати свакојаке птице, у хладу грана његовијех наставаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'И сва ће дрвета пољска познати да ја Господ снизих високо дрво и узвисих ниско дрво, посуших зелено дрво и учиних да озелени сухо дрво. Ја Господ рекох, и учинићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Шта хоћете ви који говорите причу о земљи Израиљевој говорећи: оци једоше кисело грожђе, а синовима трну зуби?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Тако ја био жив, говори Господ Господ, нећете више говорити те приче у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Гле, све су душе моје, како душа очина тако и душа синовља моја је, која душа згријеши она ће погинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Јер ако је ко праведан и чини суд и правду,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'На горама не једе и очију својих не подиже ка гаднијем боговима дома Израиљева, и не скврни жене ближњега својега и не иде к жени одвојеној ради нечистоте,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'И никоме не чини насиља, залог дужнику својему враћа, ништа не отима, хљеб свој даје гладноме и голога одијева,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Не даје на добит и не узима придавка, од неправде устеже руку своју, и право суди између једнога човјека и другога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'По уредбама мојим ходи, и држи законе моје творећи истину; тај је праведан, доиста ће живјети, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Ако роди сина лупежа, који би крв прољевао или би чинио тако што,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'А не би чинио свега онога, него би јео на горама, и жену ближњега својега скврнио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'Сиромаху и убогоме насиље чинио, отимао што, залога не би враћао, и ка гаднијем боговима подизао би очи своје чинећи гад,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Давао би на добит, и узимао придавак; хоће ли тај живјети? Неће живјети; учинио је све те гадове, доиста ће погинути, крв ће његова на њему бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Али гле, ако роди сина који би видио све гријехе оца својега што чини, и узео би на ум, те не би чинио онако,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Не би јео на горама, нити би очију својих подизао ка гаднијем боговима дома Израиљева, жене ближњега својега не би скврнио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'И никоме не би чинио насиља, залога не би узимао и не би ништа отимао, давао би хљеб свој гладноме и голога би одијевао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'Од сиромаха би устезао руку своју, не би узимао добити ни придавка, законе би моје извршивао и по уредбама мојим ходио; тај неће погинути за безакоње оца својега, доиста ће живјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'А отац његов, што је чинио насиље, отимао од брата својега и чинио што није добро у народу свом, гле, он ће погинути за своје безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Али говорите: зашто да не носи син безакоња очина? Јер син чини суд и правду, све уредбе моје држи и извршује; доиста ће живјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Која душа згријеши она ће умријети, син неће носити безакоња очина нити ће отац носити безакоња синовљега; на праведнику ће бити правда његова, а на безбожнику ће бити безбожност његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Ако ли би се безбожник обратио од свијех гријеха својих које учини, и држао би све уредбе моје и творио суд и правду, доиста ће живјети, неће погинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Безакоња његова што их је год учинио неће му се више спомињати, у правди својој коју чини живјеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Еда ли је мени мило да погине безбожник? говори Господ, а не да се одврати од путова својих и буде жив?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Али кад би се праведник одвратио од правде своје и чинио неправду, и радио по свијем гадовима које чини безбожник, хоће ли он живјети? праведна дјела његова, што је год чинио, неће се споменути; за безакоње своје које учини за гријех свој којим згријеши погинуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Још говорите: није прав пут Господњи. Чујте, доме Израиљев, мој ли пут није прав? нијесу ли ваши путови неправи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Кад се праведник одврати од правде своје и чини зло и умре зато, умријеће за зло своје које учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'А кад се безбожник одврати од безбожности своје коју је чинио, и чини суд и правду, он ће сачувати у животу душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Јер узевши на ум врати се од свијех безакоња својих која учини; доиста ће живјети, и неће погинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Али дом Израиљев вели: пут Господњи није прав. Моји ли путови нијесу прави? доме Израиљев, нијесу ли ваши путови неправи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Зато, доме Израиљев, судићу вам свакоме по путовима његовијем, говори Господ; обратите се и прођите се свијех гријеха својих, и неће вам безакоње бити на спотицање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Одбаците од себе сва безакоња која чинисте, и начините себи ново срце и нов дух; и зашто да мрете? доме Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Јер ми није мила смрт онога који мре, говори Господ Господ; обратите се дакле и будите живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'А ти наричи за кнезовима Израиљевијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'И реци: шта бјеше мати твоја? лавица; међу лавовима лежаше, млад своју међу лавовима храњаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'И отхрани једно младе своје, и поста лавић, и научив се ловити ждераше људе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'И чуше народи за њ; ухвати се у јаму њихову, и одведоше га у веригама у земљу Мисирску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'А она кад видје гдје се нада али јој над пропаде, узе једно младе своје, и учини од њега лавића.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'И он идући међу лавовима поста лавић, и научи се ловити и ждераше људе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'И позна дворе њихове, и пустошаше градове њихове тако да опустје земља и што је у њој од рике његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'И усташе на њ народи из околнијех земаља, и разапеше му мрежу своју, и ухвати се у јаму њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'И метнуше га у крлетку у веригама, и одведоше га цару Вавилонском, и метнуше га у град да му се више не чује глас по горама Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Док бијаше миран, мати твоја бијаше као винова лоза, посађена крај воде, родна и граната бијаше од многе воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'И бијаху на њој јаки прутови за палицу владалачку, и растом својим узвиси се изнад густијех грана, и би наочита висином својом, мноштвом грана својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Али би ишчупана у гњеву и на земљу бачена, и устока осуши род њезин; поломише се и посушише се јаки прутови њезини; огањ их прождрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'А сада је посађена у пустињи, у земљи сухој и безводној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'И изађе огањ из прута грана њезинијех и прождрије род њезин да нема на њој прута јака за палицу владалачку. То је нарицање, и биће нарицање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'А седме године, петога мјесеца, дана десетога, дођоше неки од старјешина Израиљевијех да упитају Господа, и сједоше преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'И дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Сине човјечји, кажи старјешинама Израиљевијем и реци им: овако вели Господ Господ: дођосте ли да ме питате? Тако ја жив био, нећете ме питати, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Хоћеш ли да им судиш? хоћеш ли да им судиш? сине човјечји. Покажи им гадове отаца њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'И реци им: овако вели Господ Господ: којега дана изабрах Израиља и подигох руку своју сјемену дома Јаковљева, и показах им се у земљи Мисирској, и подигох им руку своју говорећи: ја сам Господ Бог ваш;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Онога дана подигох им руку своју да ћу их одвести из земље Мисирске у земљу коју сам пронашао за њих, гдје тече млијеко и мед, која је дика свијем земљама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'И рекох им: одбаците сваки гадове испред својих очију, и немојте се скврнити о гадне богове Мисирске, ја сам Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Али се одвргоше од мене, и не хтјеше ме послушати, ниједан их не одбаци гадова испред очију својих, и гаднијех богова Мисирских не оставише; зато рекох да ћу излити јарост своју на њих да извршим гњев свој на њима усред земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Али имена својега ради, да се не оскврни пред онијем народима међу којима бијаху, пред којима им се показах, учиних да их изведем из земље Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'И изведох их из земље Мисирске, и доведох их у пустињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'И дадох им уредбе своје, и објавих им законе своје, које ко врши жив ће бити кроз њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'И суботе своје дадох им да су знак између мене и њих да би знали да сам ја Господ који их посвећујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Али се одврже од мене дом Израиљев у пустињи; не ходише по мојим уредбама, и законе моје одбацише, које ко врши живи кроз њих, и суботе моје грдно оскврнише; зато рекох да ћу излити гњев свој на њих у пустињи да их истријебим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Али учиних имена својега ради да се не оскврни пред народима пред којима их изведох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'И ја им још подигох руку своју у пустињи да их нећу одвести у земљу коју им дадох, гдје тече млијеко и мед, која је дика свијем земљама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Јер одбацише моје законе и по уредбама мојим не ходише, и суботе моје оскврнише, јер срце њихово иђаше за гаднијем боговима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Али их пожали око моје, те их не истријебих, и не затрх их у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Него рекох синовима њиховијем у пустињи: не идите по уредбама отаца својих и не држите њиховијех закона, и не скврните се гаднијем боговима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Ја сам Господ Бог ваш, по мојим уредбама ходите, и моје законе држите и извршујте;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'И суботе моје светкујте да су знак између мене и вас, да знате да сам ја Господ Бог ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Али се одвргоше од мене и синови, не ходише по мојим уредбама, и закона мојих не држаше да их извршују, које ко врши живи кроз њих; суботе моје оскврнише; зато рекох да ћу излити јарост своју на њих и навршити гњев свој на њима у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Али повратих руку своју и учиних имена својега ради да се не оскврни пред народима пред којима их изведох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'И ја им још подигох руку своју у пустињи да ћу их расијати по народима и разасути по земљама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Јер закона мојих не извршиваше и уредбе моје одбацише и суботе моје оскврнише, и очи им гледаху за гаднијем боговима отаца њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Зато им и ја дадох уредбе не добре и законе кроз које неће живјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'И оскврних их даровима њиховијем што пропуштаху кроз огањ све што отвори материцу, да их потрем, да познаду да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Зато говори дому Израиљеву, сине човјечји, и кажи им: овако вели Господ Господ: још ме и овијем ружише оци ваши чинећи ми безакоње:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Кад их одведох у земљу, за коју подигох руку своју да ћу им је дати, гдје год видјеше висок хум и дрво гранато, ондје приносише своје жртве и стављаше своје даре, којима дражаху, и меташе мирисе своје угодне, и ондје љеваше наљеве своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'И рекох им: шта је висина, на коју идете? И опет се зове висина до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Зато реци дому Израиљеву: овако вели Господ Господ: не скврните ли се на путу отаца својих? и за гадовима њиховијем не курвате ли се?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'И приносећи даре своје, проводећи синове своје кроз огањ не скврните ли се о све гадне богове своје до данас, и мене ли ћете питати, доме Израиљев? Тако ја жив био, говори Господ Господ, нећете ме питати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'А шта мислите, неће бити никако, што говорите: бићемо као народи, као племена по земљама, служећи дрвету и камену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Тако ја био жив, говори Господ Господ, руком крјепком и мишицом подигнутом и изливенијем гњевом цароваћу над вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'И извешћу вас из народа, и сабраћу вас из земаља по којима сте расијани, руком крјепком и мишицом подигнутом и изливенијем гњевом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'И одвешћу вас у пустињу тијех народа, и ондје ћу се судити с вама лицем к лицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Како сам се судим с оцима вашим у пустињи земље Мисирске, тако ћу се судити с вама, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'И пропустићу вас испод штапа и довести вас у свезе завјетне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'И одлучићу између вас одметнике и који одустају мене; извешћу их из земље гдје су дошљаци, али неће ући у земљу Израиљеву, и познаћете да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Ви дакле, доме Израиљев, овако вели Господ Господ: идите, служите сваки гаднијем боговима својим и унапредак, кад нећете да ме слушате; али имена мојега светога не скврните више даровима својим и гаднијем боговима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Јер на мојој гори светој, на високој гори Израиљевој, говори Господ Господ, ондје ће ми служити сав дом Израиљев, колико их год буде у земљи, ондје ће ми бити мили и ондје ћу искати приносе ваше и првине од дарова ваших са свијем светијем стварима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Мили ћете ми бити с угоднијем мирисом, кад вас изведем из народа и саберем вас из земаља у које сте расијани; и бићу посвећен у вама пред народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'И познаћете да сам ја Господ кад вас доведем у земљу Израиљеву, у земљу за коју подигох руку своју да ћу је дати оцима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'И ондје ћете се опоменути путова својих и свијех дјела својих, којима се оскврнисте, и сами ћете себи бити мрски за сва зла своја која чинисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'И познаћете да сам ја Господ кад вам учиним ради имена својега; не по вашим злијем путовима нити по опаким дјелима вашим, доме Израиљев, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Сине човјечји, окрени лице своје на југ и покапљи према југу, и пророкуј на шуму у јужном пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'И реци шуми јужној: чуј ријеч Господњу, овако вели Господ Господ: ево ја ћу распалити у теби огањ који ће прождријети у теби свако дрво зелено и свако дрво сухо; пламен разгорјели неће се угасити, и изгорјеће од њега све од југа до сјевера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'И свако ће тијело видјети да сам ја запалио; неће се угасити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'А ја рекох: јаох Господе Господе, они говоре за ме: не говори ли тај саме приче?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'И дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Сине човјечји, окрени лице своје према Јерусалиму, и покапљи према светијем мјестима, и пророкуј против земље Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'И реци земљи Израиљевој: овако вели Господ: ево ме на те; извући ћу мач свој из корица, и истријебићу из тебе праведнога и безбожнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Да истријебим из тебе праведнога и безбожнога, зато ће изаћи мач мој из корица својих на свако тијело од југа до сјевера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'И познаће свако тијело да сам ја Господ извукао мач свој из корица његовијех, неће се више вратити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'А ти, сине човјечји, уздиши као да су ти бедра поломљена, и горко уздиши пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'А када ти реку: зашто уздишеш? ти реци: за глас што иде, од којега ће се растопити свако срце и клонути све руке и свакога ће духа нестати, и свака ће кољена постати као вода; ево, иде, и навршиће се, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Потом дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Сине човјечји, пророкуј и реци: овако вели Господ Господ: реци: мач, мач је наоштрен, и углађен је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Наоштрен је да коље, углађен је да сијева; хоћемо ли се радовати кад прут сина мојега не хаје ни за како дрво?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Дао га је да се углади да се узме у руку; мач је наоштрен и углађен, да се да у руку убици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Вичи и ридај, сине човјечји; јер он иде на народ мој, на све кнезове Израиљеве; под мач ће бити окренути с народом мојим, зато удри се по бедру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Кад бјеше карање, шта би? еда ли ни од прута који не хаје неће бити ништа? говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Ти дакле, сине човјечји, пророкуј и пљескај рукама, јер ће мач доћи и другом и трећом, мач који убија, мач који велике убија, који продире у клијети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Да се растопе срца и умножи погибао, метнуо сам на сва врата њихова страх од мача; јаох! приправљен је да сијева, наоштрен да коље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Стегни се, удри на десно, на лијево, куда се год обрнеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Јер ћу и ја пљескати рукама, и намирићу гњев свој. Ја Господ рекох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Још ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'А ти, сине човјечји, начини два пута, куда ће доћи мач цара Вавилонскога; из једне земље нека излазе оба; и избери страну, гдје се почиње пут градски, избери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Начини пут, којим ће доћи мач на Раву синова Амоновијех, и у Јудеју на тврди Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Јер ће цар Вавилонски стати на распутици, гдје почињу два пута, те ће врачати, гладиће стријеле, питаће ликове, гледаће у јетру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Надесно ће му врачање показати Јерусалим да намјести убојне справе, да отвори уста на клање, да подигне глас подвикујући, да намјести убојне справе према вратима, да начини опкопе, да погради куле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'И учиниће се врачање залудно заклетима, а то ће напоменути безакоње да се ухвате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Зато овако вели Господ Господ: што напомињете своје безакоње, те се открива невјера ваша и гријеси се ваши виде у свијем дјелима вашим, зато што дођосте на памет, бићете похватани руком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'А ти, нечисти безбожниче, кнеже Израиљев, коме дође дан кад би на крају безакоње,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'Овако вели Господ Господ: скини ту капу и сврзи тај вијенац, неће га бити; нискога ћу узвисити а високога ћу понизити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Уништићу, уништићу, уништићу га, и неће га бити, докле не дође онај коме припада, и њему ћу га дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 33, 'А ти, сине човјечји, пророкуј и реци: овако вели Господ Господ за синове Амонове и за њихову срамоту; реци дакле: мач, мач је извучен, углађен да коље, да затире, да сијева,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 34, 'Докле ти виђају таштину, докле ти гатају лаж, да те метну на вратове побијенијем безбожницима, којима дође дан кад би крај безакоњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 35, 'Остави мач у корице; на мјесту гдје си се родио, у земљи гдје си постао, судићу ти;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 36, 'И излићу на те гњев свој, огњем гњева својега дунућу на те и предаћу те у руке жестоким људима, вјештим у затирању.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 37, 'Огњу ћеш бити храна, крв ће ти бити посред земље, нећеш се спомињати, јер ја Господ рекох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'А ти, сине човјечји, хоћеш ли судити, хоћеш ли судити граду крвничком? и хоћеш ли му показати све гадове његове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Реци: овако вели Господ Господ: иде вријеме граду који прољева крв у себи и гради гадне богове себи да се скврни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Скривио си крвљу коју си пролио, и оскврнио си се о гадне богове своје које си начинио; и учинио си те се приближише дани твоји, и дошао си до година својих, зато ћу учинити од тебе руг међу народима и потсмијех по свијем земљама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Које су близу тебе и које су далеко потсмијеваће ти се, гадни именом, велики сметњом!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Гле, кнезови Израиљеви у теби дадоше се да прољевају крв сваки свом силом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Оца и матер презиру у теби, чине криво иностранцу усред тебе, сироти и удовици чине насиље у теби;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Свете ствари моје презиреш, и суботе моје скврниш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'У теби су опадачи да прољевају крв, и на горама једу у теби, грдила чине усред тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Голотињу очину откривају у теби, лијежу у теби са женом за нечистоте њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'И један чини гад са женом ближњега својега; а други скврни снаху своју грдилом; а други силује сестру своју, кћер оца својега, у теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Мито примају у теби да прољевају крв; ујам и придавак узимаш, и тражиш добитак од ближњих својих пријеваром, а мене си заборавио, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Зато, ево, пљескам рукама својим ради твојега неправеднога добитка, који добијаш, и ради крви што је у теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Хоће ли се одржати срце твоје, или руке твоје хоће ли бити јаке у оне дане кад станем радити с тобом? Ја Господ рекох, и учинићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Јер ћу те расијати по народима и разасути по земљама, и истријебићу нечистоту твоју из тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'И бићеш скврнаван собом пред народима, и познаћеш да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Потом дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Сине човјечји, дом Израиљев поста ми дрождина; сви су мјед и коситер и гвожђе и олово у пећи; дрождина од сребра посташе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Зато овако вели Господ Господ: што сви ви постасте дрождина, зато, ево, ја ћу вас скупити у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Како се скупља сребро и мјед и гвожђе и олово и коситер усред пећи, те се распали огањ око њега да се истопи, тако ћу вас скупити гњевом својим и јарошћу, и сложивши растопићу вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Да, скупићу вас, и распалићу око вас огањ гњева својега, и истопићете се усред њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Како се топи сребро у пећи, тако ћете се ви истопити у њему, и познаћете да сам ја Господ излио гњев свој на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Сине човјечји, кажи јој: ти си земља која се нијеси очистила; неће пасти на те дажд у дан гњева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Пророци њезини сложише се у њој, као лав су, који риче и граби плијен, ждеру душе, отимају благо и драгоцјене ствари, умножавају удовице усред ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Свештеници њезини преступају закон мој и скврне моје свете ствари, не разликују свето од оскврњенога, и нечисто од чистога не распознају, крију очи своје од субота мојих, и бивам оскврњен међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Кнезови су њезини усред ње као вуци, који грабе плијен, прољевајући крв, губећи душе срамотнога добитка ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'И пророци њезини мажу је неваљалијем кречем, виђају таштину и гатају им лаж говорећи: тако рече Господ Господ; а Господ не рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Народ земаљски вара и отима, и сиромаху и убогоме чини насиље, и дошљаку чини криво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'И тражих међу њима који би оправио ограду и стао на пролому преда ме за ту земљу, да је не затрем; али не нађох никога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Зато ћу излити на њих гњев свој, огњем јарости своје истријебићу их, пут њихов обратићу им на главу, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Сине човјечји, бијаху двије жене, кћери једне матере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Оне се курваху у Мисиру, у младости својој курваху се, ондје им пипаше груди, и ондје им згњечише дојке дјевојачке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'А имена им бијаху, старијој Ола а сестри јој Олива; оне посташе моје, и родише синове и кћери. Имена им бијаху Ола Самарији, а Олива Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'И Ола кад бијаше моја курваше се, и упаљиваше се за својим милосницима, Асирцима сусједима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Који ношаху порфиру, и бијаху кнезови и властељи, све лијепи младићи, витезови, који јахаху на коњма.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'И удари у курвање с њима, који сви бијаху најљепши између синова Асирских, и за којима се год упаљиваше, скврњаше се о све гадне богове њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'А ни с Мисирцима не окани се курвања својега, јер спаваху с њом од младости њезине и они јој гњечише дјевојачке дојке и с њом се курваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Зато је дадох у руке милосницима њезинијем, у руке Асирцима, за којима се упаљиваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Они открише голотињу њезину, узеше јој синове и кћери, а њу мачем убише; и она изађе на глас међу женама кад судове извршише на њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'А сестра њезина Олива видећи то упаљиваше се још горе него она, и курварство њезино бијаше горе од курварства сестре јој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Упаљиваше се за Асирцима, кнезовима и властељима, сусједима, красно одјевенијем, витезима који јахаху на коњма и сви бијаху лијепи младићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'И видјех гдје се оскврни, и гдје обје иду једнијем путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'И ова се још више курваше; јер кад би видјела људе написане на зиду, ликове Халдејске написане црвенилом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Опасане појасима по бедрима, са шаренијем капама на глави, који сви бијаху на очи као војводе налик на синове Вавилонске из земље Халдејске, своје постојбине,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'Упаљиваше се за њима чим их виђаше очима својима, и слаше посланике к њима у Халдејску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'И Вавилоњани долажаху к њој на постељу љубавну, и скврњаху је курварством својим, и пошто би се оскврнила с њима, одвраћаше се душа њезина од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'И кад откри курварства своја и откри голотињу своју, одврати се душа моја од ње као што се одврати душа моја од сестре њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Јер умножи курварства своја опомињући се дана младости своје кад се курваше у земљи Мисирској,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'И упаљиваше се за својим милосницима, у којих је тијело као у магарца, и течење као у коња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'И тако си се вратила на неваљалство младости своје кад ти пипаху груди у Мисиру ради дјевојачких дојака твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Зато, Оливо, овако вели Господ Господ: ево, ја ћу подигнути милоснике твоје на те, оне од којих се одвратила душа твоја, и довешћу их на те отсвуда,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Вавилоњане и све Халдејце, Фекођане и Сојане и Којане, све Асирце с њима, лијепе младиће, кнезове и властеље све, витезове и људе чувене, који сви јашу на коњма.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'И доћи ће на те с колима и с колицима и с точковима и с мноштвом народа, и опколиће те са штитовима и штитићима и шљемовима; и њима ћу дати суд да ти суде својим судом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'И ставићу ревност своју теби насупрот, те ће радити с тобом гњевно, нос и уши одсјећи ће ти, и што те остане пашће од мача, и узеће синове твоје и кћери твоје, и што те остане прождријеће огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'И свући ће с тебе хаљине, и узеће красни накит твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Тако ћу учинити крај грдилу твојему и твојему курвању у земљи Мисирској, те нећеш подигнути очију својих к њима и нећеш се више сјећати Мисираца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Јер овако вели Господ Господ: ево, ја ћу те дати у руке онима на које мрзиш, у руке онима од којих се одвратила душа твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'И они ће радити с тобом непријатељски, и узеће сву муку твоју, и оставиће те голу нагу, те ће се открити голотиња курварства твога, и грдило твоје и курварство твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'То ћу ти учинити што си се курвала за народима, што си се оскврнила о њихове гадне богове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Путем сестре своје ишла си, зато ћу дати чашу њезину теби у руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Овако вели Господ Господ: чашу сестре своје испићеш дубоку и широку, бићеш потсмијех и руг, јер чаша много бере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Напунићеш се пијанства и жалости чашом пустошења и затирања, чашом сестре своје Самарије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'И испићеш је и исциједити, и разбићеш је, и дојке ћеш своје покидати, јер ја рекох, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Зато овако вели Господ Господ: што си ме заборавила и бацила ме за леђа своја, зато и ти носи грдило своје и курварства своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Потом рече ми Господ: сине човјечји, хоћеш ли судити Оли и Оливи? Покажи им гадове њихове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Да су чиниле прељубу и да је крв на рукама њиховијем и да су чиниле прељубу с гаднијем боговима својим и водиле кроз огањ синове своје које су ми родиле, да их једу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Још и ово ми чинише: скврнише светињу моју у исти дан, и суботе моје прзнише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Јер заклавши синове своје гаднијем боговима својим долазише у светињу моју истога дана да је оскврне; и гле, тако чинише усред дома мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'И још слаше по људе да би дошли издалека, и они, чим посланик би послан к њима, гле, одмах долазише, и њих ради си се купала, мазала очи своје и китила си се накитом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'И сједала си на красан одар, пред којим бјеше сто постављен, и на њ си метала кад мој и уље моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'И бијаше ондје вика веселога мноштва, и осим људи из гомиле довођаху Савеје из пустиње, који им метаху наруквице на руке и красне вијенце на главе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'И рекох за остарјелу у курварству: још ће се курвати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'И долажаху к њој као што иду к жени курви; тако долажаху к Оли и Оливи, женама неваљалијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Зато ће им праведни људи судити као што се суди женама прељубочиницама и као што се суди онима које прољевају крв; јер су прељубочинице и крв је на рукама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Зато овако говори Господ Господ: довешћу на њих људство, и даћу их да се злоставе и оплијене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'И људство ће их засути камењем, и исјећи ће их мачевима својим; синове ће њихове и кћери њихове побити, и куће ће њихове спалити огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'И тако ћу укинути неваљалство у земљи, и научиће се све жене да не раде по вашем неваљалству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'И врћи ће ваше неваљалство на вас, и носићете гријехе гаднијех богова својих, и познаћете да сам ја Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Потом године девете, десетога мјесеца, десетога дана, дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Сине човјечји, запиши име овога дана, овога истога дана; у тај дан дође цар Вавилонски на Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'И кажи причу томе дому одметничком, и реци им: овако вели Господ Господ: пристави лонац, пристави, и налиј у њ воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Сложи у њ дијелове, све добре дијелове, стегно и плеће, и напуни га најбољих костију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Узми најбоље из стада, и наложи кости испод њега, и узвари добро да се и кости раскухају у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Јер овако вели Господ Господ: тешко граду крвничком, лонцу, на ком стоји загоријел, с којега неће да сиђе загоријел; повади дио по дио; ждријеб да се не баци за њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Јер је крв његова усред њега; на го камен метну је, не проли је на земљу да се покрије прахом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Распаливши гњев да учиним освету, метнућу крв његову на го камен да се не покрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Зато овако вели Господ Господ: тешко граду крвничком! и ја ћу наложити велик огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Нанеси дрва, и распали огањ, нека се строши месо, зачини коријењем, и кости нека изгоре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Метни га празна на живо угљевље да се угрије и изгори мјед његова и да се стопи у њему нечистота његова и да нестане загоријели његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Лажима досадио ми је; зато неће изаћи из њега многа загоријел његова; у огањ ће загоријел његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'У нечистоти је твојој грдило твоје; јер сам те чистио, али се ти не очисти; нећеш се више чистити од нечистоте своје, докле не намирим гњев свој над тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Ја Господ говорих; доћи ће, и извршићу; нећу одустати нити ћу жалити нити ћу се раскајати, по путовима твојим и по дјелима твојим судиће ти, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Сине човјечји, ево ја ћу ти узети жељу очију твојих злом, али не тужи ни плачи, нити суза рони.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Немој уздисати, не жали како бива за мртвијем, метни капу на главу, и обућу своју обуј на ноге, и уста својих немој покрити и хљеба ничијега не једи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'И говорих ујутру народу, а увече ми умрије жена; и сјутрадан учиних како ми бјеше заповјеђено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'И рече ми народ: хоћеш ли нам казати шта нам је то што радиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'И одговорих им: дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Реци дому Израиљеву: овако вели Господ Господ: ево, ја ћу оскврнити светињу своју, величанство силе ваше, жељу очију ваших и што је мило души вашој; и синови ће ваши и кћери ваше које остависте пасти од мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'И чинићете како ја чиним: уста нећете покрити и хљеба ничијега нећете јести;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'И капе ће вам бити на главама и обућа на ногу; нећете тужити ни плакати, него ћете са безакоња својих чиљети и уздисаћете један с другим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'И Језекиљ ће вам бити знак: чинићете све што он чини; кад то дође, познаћете да сам ја Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'А ти, сине човјечји, у онај дан кад им узмем силу њихову, радост славе њихове, жељу очију њиховијех и за чим тежи душа њихова, синове њихове и кћери њихове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'У тај дан ко утече, неће ли доћи к теби да ти донесе глас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'У тај ће се дан отворити уста твоја према оном ко утече, и говорићеш и нећеш више бити нијем; и бићеш им знак, и они ће познати да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Сине човјечји, окрени лице своје према синовима Амоновијем и пророкуј на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'И реци синовима Амоновијем: чујте ријеч Господа Господа; овако вели Господ Господ: што си говорио: аха! за светињу моју, што се оскврни, и за земљу Израиљеву, што опустје, и за дом Јудин, што отиде у ропство;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'Зато, ево, ја ћу те дати у нашљедство источнијем народима, и поградиће у теби дворове себи, и начиниће себи колибе у теби; они ће јести плодове твоје и пити млијеко твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'И од Раве ћу начинити обор камилама и од земље синова Амоновијех тор овчји, и познаћете да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Јер овако вели Господ Господ: што си пљескао рукама и лупао ногом и веселио се из срца што си опустошио сву земљу Израиљеву,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Зато, ево, ја ћу дигнути руку своју на те, и даћу те народима да те плијене, и истријебићу те између народа и затрћу те између земаља, и искоријенићу те, и познаћеш да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Овако вели Господ Господ: што говори Моав и Сир: ето, дом је Јудин као сви народи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'Зато, ево, ја ћу отворити страну Моавову од градова, од градова на међи, красну земљу Вет-јесимотску, Валмеонску и Киријатајимску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Народима источнијем иза земље синова Амоновијех, и даћу им је у нашљедство да нема спомена синовима Амоновијем међу народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'И на Моавцима ћу извршити своје судове, и познаће да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Овако вели Господ Господ: што се Едом освети дому Јудину и тешко скриви осветивши им се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'Зато овако вели Господ Господ: дигнућу руку своју на Едомску и истријебићу из ње и људе и стоку, и обратићу је у пустош, од Темана до Дедана пашће од мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'И осветићу се Едомцима руком народа својега Израиља, и учиниће с Едомцима по гњеву мојему и по јарости мојој, и познаће моју освету, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Овако вели Господ Господ: што Филистеји радише из освете, и осветише се радујући се из срца и потирући из старе мржње,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'Зато овако вели Господ Господ: ево ја ћу дигнути руку своју на Филистеје, и истријебићу Херетеје, и потрћу остатак од приморја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'И учинићу на њима велику освету карањем гњевнијем, и познаће да сам ја Господ кад извршим освету своју на њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'А једанаесте године први дан мјесеца дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Сине човјечји, што Тир говори за Јерусалим: ха, ха! разбише се врата народима, обратише се к мени, напунићу се кад опустје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Зато овако вели Господ Господ: ево мене на те, Тире, и довешћу многе народе на те као да бих довео море с валима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'И они ће обалити зидове Тирске и куле у њему раскопати, и омешћу прах његов и претворићу га у го камен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'И постаће мјесто да се разастиру мреже усред мора, јер ја говорих, вели Господ Господ, и биће грабеж народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'И кћери његове по пољу изгинуће од мача, и познаће да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Јер овако вели Господ Господ: ево, ја ћу довести на Тир Навуходоносора цара Вавилонскога са сјевера, цара над царевима, с коњма и с колима и с коњицима и с војскама и многим народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Кћери твоје по пољу побиће мачем, и начиниће према теби куле, и ископаће опкопе према теби, и подигнуће према теби штитове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'И намјестиће убојне справе према зидовима твојим, и развалиће куле твоје оружјем својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Од мноштва коња његовијех покриће те прах, од праске коњика и точкова и кола затрешће се зидови твоји, кад стане улазити на твоја врата као што се улази у град испроваљиван.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Копитама коња својих изгазиће све улице твоје, побиће народ твој мачем, и ступови силе твоје попадаће на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'И поплијениће благо твоје и разграбити трг твој, и развалиће зидове твоје и лијепе куће твоје разорити, и камење твоје и дрва твоја и прах твој бациће у воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'И прекинућу јеку пјесама твојих, и глас китара твојих неће се више чути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'И учинићу од тебе го камен, бићеш мјесто гдје се разастиру мреже, нећеш се више сазидати; јер ја Господ говорих, вели Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Овако вели Господ Господ Тиру: неће ли се задрмати острва од праске падања твојега, кад зајаочу рањеници, кад покољ буде у теби?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Сви ће кнезови морски сићи с пријестола својих и скинуће са себе плаште и свући са себе везене хаљине, и обући ће се у страх; сједеће на земљи, и дрктаће сваки час и чудити се теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'И нарицаће за тобом и говориће ти: како пропаде, славни граде! у ком живљаху поморци, који бијаше јак на мору, ти и становници твоји, који страх задаваху свјема који живљаху у теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Сад ће се уздрхтати острва кад паднеш, и смешће се острва по мору од пропасти твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Јер овако вели Господ Господ: кад те учиним пустијем градом, као што су градови у којима се не живи, кад пустим на те бездану, и велика те вода покрије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'И кад те свалим с онима који слазе у јаму к старом народу, и намјестим те на најдоњим крајевима земље, у пустињи старој с онима који слазе у јаму, да се не живи у теби, тада ћу опет поставити славу у земљи живијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Учинићу да будеш страхота кад те нестане, и тражиће те и нећеш се наћи довијека, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'И ти, сине човјечји, наричи за Тиром,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'И реци Тиру, који стоји на уласку морском, који тргује с народима на многим острвима: овако вели Господ Господ: Тире, ти говораше: ја сам сасвијем лијеп.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Међе су ти у срцу морском; који те зидаше, начинише те сасвијем лијеп.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Од јела Сенирских градише ти даске, кедре с Ливана узимаше да ти граде ступове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Од храстова Васанских градише ти весла, сједишта ти градише од слонове кости и од шимшира с острва Китејских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Танко платно Мисирско изметано разапињао си да су ти једра; порфиром и скерлетом с острва Елиских покривао си се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Становници Сидонски и Арвадски бијаху ти веслари; мудраци твоји, Тире, што бијаху у теби, бијаху ти крмари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Старјешине и мудраци Гевалски оправљаху у теби што би ти се покварило; све лађе морске и лађари бијаху у теби тргујући с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Персијанци и Лудеји и Путеји бијаху у војсци твојој твоји војници; штитове и шљемове вјешаху у теби; они те украшаваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Синови Арвадски с твојом војском бијаху на зидовима твојим унаоколо, и Гамадеји бијаху у кулама твојим, штитове своје вјешаху на зидовима твојим унаоколо, они ти довршиваху љепоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Тарсис трговаше с тобом многим свакојаким благом; са сребром, с гвожђем, с коситером и с оловом долажаху на сајме твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Јаван, Тувал и Месех бијаху твоји трговци; с душама људским и судима мједенијем долажаху на сајме твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'А који су од дома Тогармина, с коњма и коњицима и мазгама долажаху на сајме твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Синови Деданови бијаху трговци твоји, многих острва трговина бијаше у твојим рукама; кости слонове и дрво евеново доношаху ти у промјену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Сирија трговаше с тобом мноштвом дјела твојих, долажаше на сајме твоје са смарагдом и порфиром и узводом и танким платном, и коралом и ахатом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Јуда и земља Израиљева бијаху твоји трговци, долажаху на сајме твоје са пшеницом Минитском и Финичком и медом и уљем и балсамом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Дамасак трговаше с тобом мноштвом дјела твојих, мноштвом свакога блага, вином Хелвонским и бијелом вуном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'И Дан и Јаван и Мосел долажаху на сајме твоје; урађено гвожђе и касију и цимет мијењаху с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Дедан трговаше с тобом скупоцјенијем простиркама за кола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Арапи и сви кнезови Кидарски трговаху с тобом; с јагањцима и овновима и јарцима долажаху на сајме твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Трговци Савски и Рамски трговаху с тобом; долажаху на сајме твоје са свакојаким мирисима и свакојаким драгим камењем и златом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Харан и Кана и Еден, трговци Савски, Асур и Хилмад трговаху с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Ти трговаху с тобом свакојаким стварима, порфиром и узводом и ковчезима богатијех накита, који се свезиваху ужима и бијаху од кедра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Лађе Тарсиске бијаху прве у твојој трговини, и ти бијаше веома пун и веома славан у срцу морском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Веслари твоји одвезоше те на пучину; вјетар источни разби те усред мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Благо твоје и сајми твоји, трговина твоја, лађари твоји и крмари твоји и који оправљаху кварне лађе твоје, и трговци твоји и сви војници твоји и сав народ што бјеше у теби пашће у срце мору кад ти пропаднеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Од вике твојих крмара усколебаће се вали морски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'И изаћи ће из лађа својих сви веслари, лађари, сви крмари морски, и стаће на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'И повикаће за тобом иза гласа и заридати горко, и посуће прахом главе своје и по пепелу ће се ваљати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'И за тобом ће се начинити ћелави, и припасаће костријет, и плакаће за тобом горко из срца, и горко ће ридати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'И за тобом ће запијевати у жалости својој и нарицаће за тобом; ко је био као Тир, оборени усред мора?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Кад излажаху тргови твоји из мора, ситио си многе народе, мноштвом својега богатства и трговине своје обогаћавао си цареве земаљске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Кад те разби море на дубокој води, трговина твоја и сав народ твој у теби паде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Сви острвљани препадоше се од тебе, и цареви њихови уздркташе се и преблиједише у лицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Трговци по народима зазвиждаше над тобом: постао си страхота, и неће те бити довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Сине човјечји, реци кнезу Тирскому: овако вели Господ Господ: што се понесе срце твоје, те велиш: ја сам Бог, сједим на пријестолу Божјем усред мора; а човјек си а не Бог и изједначујеш срце своје са срцем Божјим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Ето мудрији си од Данила, никака тајна није сакривена од тебе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Стекао си благо мудрошћу својом и разумом својим, и насуо си злата и сребра у ризнице своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Величином мудрости своје у трговини својој умножио си благо своје, те се понесе срце твоје благом твојим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Зато овако вели Господ Господ: што изједначујеш срце своје са срцем Божјим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'Зато, ево, ја ћу довести на тебе иностранце најљуће између народа, и они ће истргнути мачеве своје на љепоту мудрости твоје, и убиће свјетлост твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'Свалиће те у јаму, и умријећеш усред мора смрћу побијенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Хоћеш ли пред крвником својим казати: ја сам Бог, кад си човјек а не Бог у руци онога који ће те убити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Умријећеш смрћу необрезанијех од руке туђинске; јер ја рекох, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Сине човјечји, наричи за царем Тирским, и реци му: овако вели Господ Господ: ти си печат савршенства, пун си мудрости, и сасвијем си лијеп.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Био си у Едему врту Божјем; покривало те је свако драго камење: сарад, топаз, дијаманат, хрисолит, оних, јаспид, сафир, карбункул, смарагд и злато; онај дан кад си се родио начињени ти бише бубњи твоји и свирале.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Ти си био херувим, помазан да заклањаш; и ја те поставих; ти бјеше на светој гори Божијој, хођаше посред камења огњенога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Савршен бјеше на путовима својим од дана кад се роди докле се не нађе безакоње на теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Од мноштва трговине своје напунио си се изнутра насиља, и гријешио си; зато ћу те бацити као нечистоту с горе Божје, и затрћу те између камења огњенога, херувиме заклањачу!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Срце се твоје понесе љепотом твојом, ти поквари мудрост своју свјетлошћу својом; бацићу те на земљу, пред цареве ћу те положити да те гледају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Од мноштва безакоња својега, од неправде у трговини својој оскврнио си светињу своју; зато ћу извести огањ испред тебе, који ће те прождријети, и обратићу те у пепео на земљи пред свјема који те гледају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Сви који те познају међу народима препашће се од тебе; бићеш страхота, и неће те бити довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Сине човјечји, окрени лице своје према Сидону, и пророкуј против њега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'И реци: овако вели Господ Господ: ево ме на тебе, Сидоне, и прославићу се усред тебе, и познаће се да сам ја Господ кад извршим судове на њему и посветим се у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'И послаћу помор у њ, и крв на улице његове, и побијени ће падати усред њега од мача, који ће навалити на њих са свијех страна, и познаће да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'И неће више бити дому Израиљеву трн који боде ни жалац који задаје бол више од свијех сусједа њиховијех, који их плијене; и познаће да сам ја Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Овако вели Господ Господ: кад скупим дом Израиљев из народа међу које су расијани, и посветим се у њима пред народима и населе се у својој земљи коју дадох слузи својему Јакову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Тада ће живјети у њој без страха, и градиће куће, и садиће винограде, и живјеће без страха кад извршим судове на свјема који их плијенише са свијех страна, и познаће да сам ја Господ Бог њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Године десете, десетога мјесеца, дванаестога дана, дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Сине човјечји, окрени лице своје према Фараону цару Мисирском, и пророкуј против њега и против свега Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Говори и реци: овако вели Господ Господ: ево ме на те, Фараоне царе Мисирски, змају велики што лежиш усред ријека својих, који рече: моја је ријека; ја сам је начинио себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Зато ћу ти метнути у чељусти удицу, и учинићу да се рибе у ријекама твојим нахватају на крљушти твоје; и извући ћу те из ријека твојих и све рибе из ријека твојих нахватане на крљушти твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'И оставићу у пустињи тебе и све рибе из твојих ријека, и пашћеш на земљу и нећеш се покупити ни сабрати, звијерима земаљским и птицама небеским даћу те да те једу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'И сви ће становници Мисирски познати да сам ја Господ; јер су штап од трске дому Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Кад те ухватише у руку, ти се сломи и расијече им све раме; а кад се наслонише на те, ти се преби и прободе им сва бедра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Зато овако вели Господ Господ: ево, ја ћу пустити на те мач, и истријебићу из тебе људе и стоку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'И земља ће се Мисирска опустошити и бити пуста, и познаће се да сам ја Господ, јер рече: моја је ријека, и ја сам је начинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Зато ево ме на тебе и на ријеке твоје, и обратићу земљу Мисирску у пустош и саму пустињу, од куле Синске до међе Етиопске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Неће прелазити преко ње ногом својом човјек, нити ће живинче ногом својом прелазити преко ње, и неће се живјети у њој четрдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'И учинићу од земље Мисирске пустош међу земљама опустошеним, и градови ће њезини међу пустијем градовима бити пустош четрдесет година, и расијаћу Мисирце међу народе и разасућу их по земљама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Јер овако вели Господ Господ: послије четрдесет година скупићу Мисирце из народа у које буду расијани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'И повратићу робље Мисирско, и довешћу их опет у земљу Патрос, на постојбину њихову, и ондје ће бити мало царство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Мало ће бити мимо остала царства, нити ће се више уздигнути над народе, јер ћу их смањити да не владају народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'И неће више бити дому Израиљеву узданица да напомиње безакоње кад би гледали за њима; и познаће да сам ја Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'А двадесет седме године, првога мјесеца, првога дана, дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Сине човјечји, Навуходоносор цар Вавилонски зададе војсци својој тешку службу против Тира; свака глава оћелави и свако се раме одрије, а плате не би ни њему ни војсци његовој од Тира за службу којом служише против њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Зато овако вели Господ Господ: ево ја дајем Навуходоносору цару Вавилонском земљу Мисирску, и он ће одвести народ и однијети плијен и пограбити грабеж, и то ће бити плата његовој војсци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'За труд којим се трудио око тога дадох му земљу Мисирску, јер се за ме трудише, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'У онај ћу дан учинити да нарасте рог дому Израиљеву, и теби ћу отворити уста међу њима, и знаће да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Сине човјечји, пророкуј и реци: овако вели Господ Господ: ридајте: јаох дана!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Јер је близу дан, близу је дан Господњи, облачан дан, вријеме народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'И мач ће доћи на Мисир, и страх ће бити у Етиопској, кад стану падати побијени у Мисиру, кад се зароби мноштво његово и раскопају се темељи његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Етиопљани и Путеји и Лудеји и сва мјешавина и Хувеји и синови земаља међу којима је вјера, пашће с њима од мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Овако вели Господ: пашће који подупиру Мисир, и понос силе његове обориће се, од куле Синске пашће у њему, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'И биће пусти међу пустијем земљама, и градови ће његови бити међу пустијем градовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'И познаће да сам ја Господ кад запалим огањ у Мисиру и сви се помоћници његови сатру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'У онај ће дан изаћи посланици од мене на лађама да уплаше Етиопску безбрижну, и биће међу њима страх велик као дана Мисирскога; јер ево, иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Овако вели Господ Господ: погубићу мноштво Мисирско руком Навуходоносора цара Вавилонскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Он и народ његов с њим, најљући између народа, биће доведени да затру земљу, и извући ће мачеве своје на Мисир и напуниће земљу побијенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'И исушићу ријеке, и предаћу земљу у руке злијем људима; и опустићу земљу и што је у њој руком туђинском. Ја Господ говорих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Овако вели Господ Господ: и гадне ћу богове потрти, и истријебићу ликове у Нофу и неће више бити кнеза из земље Мисирске, и пустићу страх у земљу Мисирску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'И опустошићу Патрос, и упалићу Соан, и извршићу суд на Нову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'И излићу гњев свој на Син, град Мисирски, и истријебићу људство у Нову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Кад запалим огањ у Мисиру, љуто ће се узмучити Син, и Нов ће се распасти, и Ноф ће бити у тјескоби сваки дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Младићи Авински и Пи-весетски пашће од мача, а дјевојке ће отићи у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'И у Тафнису ће помркнути дан кад поломим ондје пријеворнице Мисирске и нестане у њему поноса силе његове; облак ће га покрити; а кћери ће његове отићи у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'И извршићу судове на Мисиру, и они ће познати да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Опет једанаесте године, првога мјесеца, седмога дана, дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Сине човјечји, сломих мишицу Фараону цару Мисирском, и ето неће се завити да се лијечи, неће се метнути завој нити ће се завити да би се окријепила и могла држати мач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Зато овако вели Господ Господ: ево ме на Фараона цара Мисирскога, и сломићу му мишице, и здраву и сломљену, и избићу му мач из руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'И расијаћу Мисирце по народима, и разасућу их по земљама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'И укријепићу мишицу цару Вавилонском, и даћу му у руку свој мач, и поломићу мишице Фараону, и јечаће пред њим као што јечи човјек рањен на смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Да, укријепићу мишице цару Вавилонском, а Фараону ће мишице клонути, и познаће се да сам ја Господ, кад дам мач свој у руку цару Вавилонском да њим замахне на земљу Мисирску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'И расијаћу Мисирце међу народе и разасућу их по земљама, и познаће да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'А једанаесте године, трећега мјесеца, првога дана, дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Сине човјечји, кажи Фараону цару Мисирском и народу његову: на што си налик у величини својој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Ето, Асирац бјеше кедар на Ливану, лијепих грана и дебела хлада и висока раста, којему врхови бијаху међу густијем гранама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Вода га одгоји, бездана га узвиси; она ријекама својим тецијаше око његова стабла и пушташе потоке своје к свијем дрветима пољским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Зато раст његов надвиси сва дрвета пољска, и умножише се гране његове, и од мноштва воде раширише се одводе његове кад их пушташе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'На гранама његовијем вијаху гнијезда све птице небеске, и под гранама његовијем све звијери пољске лезијаху се, и у хладу његову сјеђаху сви велики народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'И бијаше лијеп величином својом и дужином грана својих, јер му коријен бијаше код велике воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Кедри у врту Божијем не могаху га заклонити, јеле не могаху се изједначити с његовијем гранама, и јавори не бијаху као огранци његови; ниједно дрво у врту Божијем не бјеше на љепоту тако као он.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Учиних га лијепа мноштвом грана да му завиђаху сва дрвета Едемска што бијаху у врту Божијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Зато овако вели Господ Господ: што је висок нарастао, и дигао врх свој међу густе гране, и срце се његово понијело висином његовом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'Зато га дадох у руку најсилнијему међу народима да чини с њим што хоће, одвргох га за безбожност његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'И туђинци, најљући између народа, посјекоше га и оставише га; гране му попадаше по горама и по свијем долинама, и огранци му се изломише по свијем потоцима на земљи; и сви народи земаљски отидоше из хлада његова и оставише га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'На изваљеном пању његову станују све птице небеске, и на гранама су његовијем све звијери пољске,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'Да се не поноси висином својом ниједно дрво крај воде и не диже врха својега међу густе гране, и од свијех што се натапају да се ниједно не узда у се ради своје величине; јер су сви предани на смрт, бачени у најдоњи крај земље међу синове људске с онима који слазе у јаму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Овако вели Господ Господ: у који дан сиде у гроб, учиних жалост, покрих бездану њега ради, и уставих ријеке њезине, и велика вода стаде, и расцвијелих за њим Ливан, и сва дрвета пољска повенуше за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Праском падања његова устресох народе, кад га свалих у гроб с онима који слазе у јаму; и утјешише се на најдоњој страни земље сва дрвета Едемска, што је најбоље и најљепше на Ливану, сва што се натапаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'И они сидоше с њим у гроб к онима што су побијени мачем, и мишица његова, и који сјеђаху у хладу његову међу народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'На које си међу дрветима Едемским налик славом и величином? Али ћеш бити оборен с дрветима Едемским у најдоњи крај земље, међу необрезанима ћеш лежати с онима који су побијени мачем. То је Фараон и сав народ његов, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Опет дванаесте године, дванаестога мјесеца, првога дана, дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Сине човјечји, наричи за Фараоном царем Мисирским, и реци му: ти си као лавић међу народима и као змај у мору, и пролазиш ријеке своје и мутиш воду ногама својим и газиш по ријекама њезинијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Овако вели Господ Господ: разапећу ти мрежу своју са збором многих народа, и извући ће те у мојој мрежи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'И оставићу те на земљи, и бацићу те у поље, и пустићу све птице небеске да сједају на те, и наситићу тобом звијери са све земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'И разметнућу месо твоје по горама и напунићу долине гомилама од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'И земљу гдје пливаш напојићу крвљу твојом до врх гора, и потоци ће бити пуни тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'И кад те угасим, застријећу небо, и звијезде на њему помрачити, сунце ћу заклонити облаком, и мјесец неће свијетлити свјетлошћу својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Сва ћу свијетла видјела на небу помрачити за тобом, и пустићу таму на твоју земљу, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'И устрашићу срце многих народа кад објавим пропаст твоју међу народима, по земљама којих не знаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'И удивићу тобом многе народе, и цареви ће се њихови згрозити од тебе, кад махнем мачем својим пред њима, и дрктаће сваки час сваки за душу своју у дан кад паднеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Јер овако вели Господ Господ: мач цара Вавилонскога доћи ће на те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Мачевима јуначким поваљаћу мноштво твоје, мачевима најљућих између народа; они ће разорити понос Мисиру, и све ће се мноштво његово потрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'И потрћу сву стоку његову покрај великих вода, те их неће више мутити нога човјечија нити ће их папак од каке животиње мутити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Тада ћу стишати воду њихову, и учинићу да потоци њихови теку као уље, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Кад опустим земљу Мисирску и она буде без свега што је у њој, и побијем све који живе у њој, тада ће познати да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Ово је нарицање што ће се нарицати; тако ће нарицати кћери народне, за Мисиром и за свијем мноштвом његовијем нарицаће, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Потом дванаесте године, петнаести дан истога мјесеца, дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Сине човјечји, наричи за мноштвом Мисирским, и свали њих и кћери јаких народа у најдоњи крај земље с онима који слазе у јаму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Од кога си љепши? сиђи и лези с необрезанима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Пашће посред побијенијех мачем, мач је дат, вуците га и све мноштво његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Говориће му најхрабрији јунаци исред гроба с помоћницима његовијем, који сидоше и леже необрезани, побијени мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Ондје је Асирац и сав збор његов, гробови су му око њега, сви су побијени, пали од мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Гробови су му у дну јаме, а збор му је око његова гроба; сви су побијени, пали од мача, који задаваху страх земљи живијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Ондје је Елам и све мноштво његово око његова гроба; сви су побијени, пали од мача, који сидоше необрезани на најдоњи крај земље, који задаваху страх земљи живијех; и носе срамоту своју с онима који слазе у јаму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Међу побијенима намјестише постељу њему и свему мноштву његову, гробови су му око њега, сви су необрезани побијени мачем, који задаваху страх земљи живијех; и носе срамоту своју с онима који слазе у јаму, метнути су међу побијене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Ондје је Месех, Тувал и све мноштво његово, гробови су му око њега, сви су необрезани побијени мачем, који задаваху страх земљи живијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Али не леже међу јунацима који падоше између необрезанијех, који сидоше у гроб с оружјем својим, и метнуше мачеве под главе своје, и безакоње њихово лежи на костима њиховијем, ако и бијаху јунаци страшни на земљи живијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'И ти ћеш се сатрти међу необрезанима, и лежаћеш код побијенијех мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Ондје је Едом, цареви његови и сви кнезови његови, који су са силом својом метнути међу побијене мачем; леже међу необрезанима и с онима који сидоше у јаму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Ондје су сви кнезови сјеверни и сви Сидонци, који сидоше к побијенима са страхом својим, стидећи се силе своје; и леже необрезани с онима који су побијени мачем, и носе срамоту своју с онима који сидоше у јаму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Њих ће видјети Фараон, и утјешиће се за свијем мноштвом својим, Фараон и сва војска његова, побијени мачем, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Јер зададох свој страх земљи живијех, и Фараон ће и све мноштво његово лежати међу необрезанима с онима који су побијени мачем, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Сине човјечји, говори синовима народа својега, и кажи им: кад пустим на коју земљу мач, ако народ оне земље узме кога између себе, и поставе га себи за стражара,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'И он видјевши мач гдје иде на земљу затруби у трубу, и опомене народ,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'Ако се ко чувши трубу не узме на ум, и мач дошавши погуби га, крв ће његова бити на његовој глави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Јер чу глас трубни, и не узе се на ум, крв ће његова бити на њему; да се узе на ум, сачувао би душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Ако ли стражар видјевши мач гдје иде не затруби у трубу и народ не буде опоменут, а мач дошав погуби кога између њих, тај ће погинути за своје безакоње, али ћу крв његову искати из руке стражареве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'И тебе, сине човјечји, тебе поставих стражарем дому Израиљеву; слушај дакле ријеч из мојих уста и опомињи их од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Кад речем безбожнику: безбожниче, погинућеш; а ти не проговориш и не опоменеш безбожника да се прође пута својега; тај ће безбожник погинути за своје безакоње; али ћу крв његову искати из твоје руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Ако ли ти опоменеш безбожника да се врати са свога пута, а он се не врати са свога пута, он ће погинути за своје безакоње, а ти ћеш сачувати душу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Зато ти, сине човјечји, реци дому Израиљеву: ви говорите овако и кажете: пријеступи наши и гријеси наши на нама су, и с њих пропадамо; како бисмо живјели?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Реци им: тако био ја жив, говори Господ Господ, није ми мило да умре безбожник, него да се врати безбожник са свога пута и буде жив; вратите се, вратите се са злијех путова својих, јер зашто да мрете, доме Израиљев?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Зато ти, сине човјечји, реци синовима народа својега: праведнога неће избавити правда његова кад згријеши, и безбожник неће пропасти са безбожности своје кад се врати од безбожности своје, као што праведник не може с ње живјети кад згријеши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Кад речем праведнику да ће доиста живјети, а он се поузда у правду своју па учини неправду, од све правде његове ништа се неће споменути, него ће погинути с неправде своје коју учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'А кад речем безбожнику: доиста ћеш погинути, а он се обрати од гријеха својега и стане чинити суд и правду,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'И врати безбожник залог, и врати што је отео, и стане ходити по уредбама животнијем не чинећи безакоња, доиста ће бити жив, неће умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Од свијех гријеха што је згријешио ништа му се неће споменути; чинио је суд и правду, доиста ће жив бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'А синови народа твојега говоре: није прав пут Господњи; а њихов пут није прав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Кад се праведник одврати од правде своје и учини неправду, погинуће с тога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'А кад се безбожник одврати од своје безбожности и учини суд и правду, он ће жив бити с тога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'А ви говорите: није прав пут Господњи. Судићу вам, доме Израиљев, свакоме по путовима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'А дванаесте године робовања нашега, десетога мјесеца, петога дана дође к мени један који утече из Јерусалима, и рече: узе се град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'А рука Господња дође нада ме увече прије него дође онај што утече, и отвори ми уста докле онај дође к мени ујутру; отворише ми се уста, те више не мучах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'И дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Сине човјечји, који живе у онијем пустолинама у земљи Израиљевој говоре и кажу: Аврам бијаше један, и наслиједи ову земљу; а нас је много; нама је дата ова земља у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Зато им реци: овако вели Господ Господ: једете с крвљу, и очи своје подижете ка гаднијем боговима својим, и крв прољевате, и хоћете да наслиједите земљу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Опирете се на мач свој, чините гадове, и скврните сваки жену ближњега својега, и хоћете да наслиједите земљу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Овако им реци: овако вели Господ Господ: тако ја жив био, који су у пустолинама, пашће од мача; и који је у пољу, звијерима ћу га дати да га изједу; а који су по градовима и по пећинама, од помора ће помријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Тако ћу сасвијем опустити ту земљу, и нестаће поноса силе њезине, и опустјеће горе Израиљеве да неће нико пролазити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'И они ће познати да сам ја Господ кад земљу сасвијем опустим за све гадове њихове што чинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'А о теби, сине човјечји, синови народа твојега казују о теби уза зидове и на вратима кућнијем, и говоре један другому, сваки брату својему, и веле: ходите и чујте кака ријеч дође од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'И долазе к теби као кад се народ скупља, и народ мој сједа пред тобом, и слуша ријечи твоје, али их не извршује; у устима су им љупке а срце њихово иде за својим лакомством.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'И гле, ти си им као љупка пјесма, као човјек лијепа гласа и који добро свира; слушају ријечи твоје, али их не извршују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Али кад то дође, а ево иде, онда ће познати да је био пророк међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Сине човјечји, пророкуј против пастира Израиљевијех, пророкуј и реци тијем пастирима: овако вели Господ Господ: тешко пастирима Израиљевијем који пасу сами себе! Не треба ли стадо да пасу пастири?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Претилину једете и вуном се одијевате, кољете товно, стада не пасете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Слабијех не кријепите, и болесне не лијечите, рањене не завијате, одагнане не доводите натраг, изгубљене не тражите, него силом и жестином господарите над њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'И распршаше се немајући пастира, и распршавши се посташе храна свијем звијерима пољским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Овце моје лутају по свијем горама и по свијем високим хумовима; и по свој земљи распршане су овце моје, и нема никога да пита за њих, никога да их тражи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Зато, пастири, чујте ријеч Господњу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Тако ја био жив, говори Господ Господ, што стадо моје поста грабеж, и овце моје посташе храна свијем звијерима пољским немајући пастира, и пастири моји не траже стада мојега, него пастири пасу сами себе, а стада мојега не пасу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'Зато, пастири, чујте ријеч Господњу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Овако вели Господ Господ: ево ме на те пастире, и искаћу стадо своје из њиховијех руку, и нећу им дати више да пасу стадо, и неће више пастири пасти сами себе, него ћу отети овце своје из уста њиховијех и неће им бити храна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Јер овако вели Господ Господ: ево ме, ја ћу тражити овце своје и гледати их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Као што пастир тражи стадо своје кад је код оваца својих распршанијех, тако ћу тражити овце своје и отећу их из свијех мјеста куда се распршаше кад бијаше облачно и мрачно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'И извешћу их из народа, и покупићу их из земаља, и довешћу их у земљу њихову, и пашћу их на горама Израиљевијем покрај потока и по свијем мјестима насељенијем у земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'На доброј паши пашћу их, и тор ће им бити на високим горама Израиљевијем; ондје ће лежати у добром тору и по обилатој ће паши пасти на горама Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Ја ћу пасти стадо своје, и ја ћу их одмарати, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Тражићу изгубљену, и довешћу натраг одагнану, и рањену ћу завити и болесну окријепити; а товну ћу и јаку потрти, пашћу их право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'А вама, стадо моје, овако говори Господ Господ: ево ја ћу судити између овце и овце, између овнова и јараца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Мало ли вам је што пасете на доброј паши, него остатак паше своје газите ногама својим? и што пијете бистру воду, него остатак мутите ногама својим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'А моје овце пасу што ви ногама својим изгазите, и пију што ви замутите ногама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Зато овако им вели Господ Господ: ево ме, ја ћу судити између овце дебеле и овце мршаве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Што боцима и раменима отискујете и розима својим бодете све болесне тако да их разагнасте напоље,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Зато ћу избавити стадо своје да не буде више грабеж, и судићу између овце и овце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'И подигнућу им једнога пастира који ће их пасти, слугу својега Давида; он ће их пасти и биће им пастир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'А ја Господ бићу им Бог, и слуга мој Давид кнез међу њима. Ја Господ рекох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'И учинићу с њима завјет мирни, истријебићу зле звијери из земље, и они ће живјети у пустињи без страха и спаваће у шумама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'И благословићу њих и што је око горе моје, и пуштаћу дажд на вријеме; дажди ће благословни бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'И дрвета ће пољска рађати свој род, и земља ће рађати свој род; и они ће бити у својој земљи без страха, и познаће да сам ја Господ кад поломим палице јарма њихова, и избавим их из руку онијех који их заробише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'И неће више бити плијен народима, и звијери земаљске неће их јести, него ће живјети без страха и нико их неће плашити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'И подигнућу им биљку за славу, и неће више умирати од глади у земљи, нити ће подносити срамоте од народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'И познаће да сам ја Господ Бог њихов с њима, и они, дом Израиљев, да су мој народ, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'А ви сте стадо моје, овце паше моје, ви људи, а ја сам Бог ваш, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Сине човјечји, окрени лице своје према гори Сиру и пророкуј против ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'И реци: овако вели Господ Господ: ево ме на тебе, горо Сире! и дигнућу руку своју на те, и опустићу те сасвијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Градове ћу твоје опустити, и ти ћеш бити пустош, и познаћеш да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Што је у тебе вјечно непријатељство, и расипаш синове Израиљеве мачем у невољи њиховој, кад је крај безакоњу њихову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Зато, тако ја био жив, говори Господ Господ, крви ћу те предати и крв ће те гонити, јер не мрзиш на крв, крв ће те гонити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'И обратићу гору Сир сасвијем у пустош, да нико неће долазити ни одлазити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'И напунићу горе њезине побијенијех њезинијех; на хумовима твојим и у долинама твојим и по свијем потоцима твојим падаће побијени од мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Вјечну пустињу начинићу од тебе и градови се твоји неће оправити, и познаћете да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Што говориш: ова два народа и ове двије земље моје ће бити, и наслиједићемо их, ако и јест Господ био ондје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Зато, тако ја жив био, говори Господ Господ, учинићу по гњеву твом и по зависти твојој, с којом си поступала из мржње према њима, и бићу познат међу њима кад ти судим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'И познаћеш да сам ја Господ чуо све твоје хуле које си говорила на горе Израиљеве рекавши: опустјеше, нама су дане да их једемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'И величасте се супрот мени устима својим, и множисте на ме ријечи своје; чуо сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Овако вели Господ Господ: кад се сва земља стане веселити, тебе ћу опустити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Како си се ти веселила нашљедству дома Израиљева што опустје, тако ћу и теби учинити: опустјећеш, горо Сире, и сва земљо Едомска; и познаће се да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Ти, сине човјечји, пророкуј горама Израиљевијем, и реци: горе Израиљеве, чујте ријеч Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Овако вели Господ Господ: што непријатељ говори за вас: ха ха! вјечне висине посташе наше нашљедство;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'Зато пророкуј и реци: овако вели Господ Господ: што вас пустоше и прождиру са свијех страна, да постанете нашљедство осталијем народима, и постасте прича и руг народима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Зато, горе Израиљеве, чујте ријеч Господа Господа; овако вели Господ горама Израиљевијем и хумовима, потоцима и долинама, и пустијем развалинама и градовима остављенијем, које посташе грабеж и потсмијех осталијем народима унаоколо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Зато овако вели Господ Господ: у огњу ревности своје говорих против осталијех народа и против све Едомске, што освојише моју земљу радујући се из свега срца и ругајући се из душе да би је оплијенили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Зато пророкуј за земљу Израиљеву, и реци горама и хумовима, потоцима и долинама: овако вели Господ Господ: ево, ја говорих у ревности својој и у јарости својој; што подносите срамоту од народа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Зато овако вели Господ Господ: ја подигох руку своју да ће народи што су око нас носити срамоту своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'А ви, горе Израиљеве, пуштаћете гране своје, и род свој носићете народу мојему Израиљу, јер ће скоро доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Јер ево ме код вас, и гледаћу вас, и бићете рађене и засијеване.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'И умножићу у вама људе, дом Израиљев савколики, и градови ће се населити и пустолине саградити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Умножићу у вама људе и стоку, и намножиће се и наплодити, и населићу вас како бијасте прије; и учинићу вам добра више него прије; и познаћете да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'И довешћу к вама људе, народ свој Израиља, и наслиједиће вас, и бићете им нашљедство, и нећете их више затирати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Овако вели Господ Господ: што вам говоре да сте земља која прождире људе и затире своје народе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'Зато нећеш више прождирати људи, и народа својих нећеш више затирати, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'И нећу дати да се више у теби чује срамота од народа, и руга од народа нећеш више подносити, и нећеш више затирати својих народа, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Сине човјечји, дом Израиљев живећи у својој земљи оскврни је својим путем и својим дјелима; пут њихов бијаше преда мном као нечистота жене одвојене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Зато излих гњев свој на њих ради крви коју пролише на земљу и ради гаднијех богова њиховијех, којима је оскврнише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'И расијах их по народима, и разасуше се по земљама; по путовима њиховијем и по дјелима њиховијем судих им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'И кад дођоше међу народе, гдје год дођоше оскврнише свето име моје, а за њих се говораше да су Господњи народ и да су из земље његове изашли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Али ми се сажали ради светога имена мојега, које оскврни дом Израиљев у народима у које дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Зато реци дому Израиљеву: овако вели Господ Господ: нећу вас ради учинити, доме Израиљев, него ради светога имена својега, које оскврнисте у народима у које дођосте;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'И посветићу име своје велико оскврњено у народима, које ви оскврнисте међу њима; и народи ће познати да сам ја Господ, говори Господ Господ, кад се посветим у вама пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Јер ћу вас узети из народа, и покупићу вас из свијех земаља, и довешћу вас у вашу земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'И покропићу вас водом чистом, и бићете чисти; ја ћу вас очистити од свијех нечистота ваших и од свијех гаднијех богова ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'И даћу вам ново срце, и нов ћу дух метнути у вас, и извадићу камено срце из тијела вашега, и даћу вам срце месно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'И дух свој метнућу у вас, и учинићу да ходите по мојим уредбама и законе моје да држите и извршујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'И наставаћете у земљи коју сам дао оцима вашим, и бићете ми народ и ја ћу вам бити Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'И опростићу вас свијех нечистота ваших, и дозваћу жито и умножићу га, и нећу пустити на вас глади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'И умножићу род на дрветима и род на њиви, те нећете више подносити срамоте међу народима са глади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'И опоменућете се злијех путова својих и дјела својих која не бјеху добра, и сами ћете себи бити мрски за безакоња своја и за гадове своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Нећу вас ради учинити, говори Господ Господ; знајте; посрамите се и постидите се путова својих, доме Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Овако вели Господ Господ: кад вас очистим од свијех безакоња ваших, населићу градове, и пустолине ће се опет саградити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'И пуста ће се земља радити, што је била пуста пред сваким који пролажаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'И рећи ће се: земља ова што бјеше пуста поста као врт Едемски, и градови што бјеху пусти, разваљени и раскопани, утврдише се и населише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'И народи који остану око вас познаће да ја Господ саграђујем разваљено и засађујем опустјело. Ја Господ рекох, и учинићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Овако вели Господ Господ: још ће ме тражити дом Израиљев да им учиним, да их умножим људима као стадо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Као свето стадо, као стадо у Јерусалиму о празницима њиховијем, тако ће пусти градови бити пуни стада људи, и познаће да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Рука Господња дође нада ме, и Господ ме изведе у духу, и постави ме усред поља, које бијаше пуно кости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'И проведе ме покрај њих унаоколо, и гле, бијаше их врло много у пољу, и гле, бијаху врло сухе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'И рече ми: сине човјечји, хоће ли оживјети ове кости? А ја рекох: Господе Господе, ти знаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Тада ми рече: пророкуј за те кости, и кажи им: сухе кости, чујте ријеч Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Овако говори Господ Господ овијем костима: гле, ја ћу метнути у вас дух, и оживјећете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'И метнућу на вас жиле, и обложићу вас месом, и навући ћу на вас кожу, и метнућу у вас дух, и оживјећете, и познаћете да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Тада стадох пророковати, како ми се заповједи; а кад пророковах наста глас, и гле потрес, и кости се прибираху свака ка својој кости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'И погледах, и гле, по њима изидоше жиле и месо, и озго се кожа навуче; али духа не бјеше у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Тада ми рече: пророкуј духу, пророкуј, сине човјечји, и реци духу: овако вели Господ Господ: од четири вјетра дођи, душе, и дуни на ове побијене да оживе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'И пророковах, како ми се заповједи и уђе у њих дух, и оживјеше, и стадоше на ноге, бјеше војска врло велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Тада ми рече: сине човјечји, ове су кости сав дом Израиљев; гле, говоре: посахнуше кости наше и прође надање наше, пропадосмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Зато пророкуј, и кажи им: овако вели Господ Господ: ево, ја ћу отворити гробове ваше, и извешћу вас из гробова ваших, народе мој, и довешћу вас у земљу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'И познаћете да сам ја Господ, кад отворим гробове ваше, и изведем вас из гробова ваших, народе мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'И метнућу дух свој у вас да оживите, и населићу вас у вашој земљи, и познаћете да ја говорим и чиним, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Ти, сине човјечји, узми једно дрво, и напиши на њему: Јуди и синовима Израиљевијем, друговима његовијем. Па онда узми друго дрво, и на њему напиши: Јосифу дрво Јефремово и свега дома Израиљева, другова његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'И састави их једно с другим да буду као једно у твојој руци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'И кад ти реку синови твога народа говорећи: хоћеш ли нам казати шта ти је то?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Реци им: овако вели Господ Господ: ево, ја ћу узети дрво Јосифово, што је у Јефремовој руци, и племена Израиљевијех, другова његовијех, и саставићу га с дрветом Јудинијем, и начинићу од њих једно дрво, и биће једно у мојој руци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'И дрвета, на којима напишеш, нека ти буду у руци пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'И реци им: овако вели Господ Господ: ево, ја ћу узети синове Израиљеве из народа у које отидоше, и сабраћу их отсвуда, и довешћу их у земљу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'И начинићу од њих један народ у земљи, на горама Израиљевијем, и један ће цар бити цар свјема њима, нити ће више бити два народа, нити ће више бити раздијељени у два царства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'И неће се више скврнити гаднијем боговима својим ни гнусобама својим нити какијем пријеступима својим, и избавићу их из свијех станова њиховијех у којима гријешише, и очистићу их, и они ће ми бити народ и ја ћу им бити Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'И слуга мој Давид биће им цар, и сви ће имати једнога пастира, и ходиће по мојим законима, и уредбе ће моје држати и извршивати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'И сједјеће у земљи коју дадох слузи својему Јакову, у којој сједјеше оци ваши; у њој ће сједјети они и синови њихови и синови синова њиховијех довијека, и Давид слуга мој биће им кнез довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'И учинићу с њима завјет мирни, биће вјечан завјет с њима, и утврдићу их и умножићу их, и намјестићу светињу своју усред њих навијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'И шатор ће мој бити код њих, и ја ћу им бити Бог и они ће ми бити народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'И народ ће познати да сам ја Господ који посвећујем Израиља, кад светиња моја буде усред њих довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Опет ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Сине човјечји, окрени лице своје према Гогу у земљи Магогу, кнезу и глави у Месеху и Тувалу; и пророкуј на њ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'И реци: овако вели Господ Господ: ево ме на тебе, Гоже, кнеже и главо Месеху и Тувалу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'И вратићу те натраг, и метнућу ти жвале у чељусти, и извешћу тебе и сву војску твоју, коње и коњике, све добро одјевене, збор велики са штитовима и штитићима, све који мачем машу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'С њима Персијанце, Етиопљане и Путеје, све са штитовима и под шљемовима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Гомера и све чете његове, дом Тогармин са сјевернога краја и све чете његове, многе народе с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Приправи све и спреми се ти и све људство твоје, што се сабрало код тебе, и буди им стражар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Послије много времена бићеш похођен, и пошљедњих година доћи ћеш у земљу избављену од мача и сабрану из многих народа, у горе Израиљеве, које бјеху једнако пусте, а они ће изведени из народа сви живјети без страха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'И подигнућеш се, и доћи ћеш као бура, бићеш као облак да покријеш земљу ти и све чете твоје и многи народи с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Овако вели Господ Господ: и тада ће ти доћи у срце ствари, и смишљаћеш зле мисли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'И рећи ћеш: идем на земљу гдје су села, и ударићу на мирни народ који живи без страха, који сви живе у мјестима без зидова и немају ни пријеворница ни врата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Да наплијениш плијена и награбиш грабежа, да посегнеш руком својом на пустиње насељене и на народ сабрани из народа, који се бави стоком и имањем, и живи усред земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Сава и Дедан и трговци Тарсиски и сви лавићи његови казаће ти: јеси ли дошао да плијениш плијен? јеси ли скупио људство своје да грабиш грабеж? да однесеш сребро и злато, да узмеш стоку и трг, да наплијениш много плијена?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Зато пророкуј, сине човјечји, и реци Гогу: овако вели Господ Господ: у оно вријеме, кад ће мој народ Израиљ живјети без страха, нећеш ли знати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'И доћи ћеш из свога мјеста, са сјевернога краја, ти и многи народи с тобом, сви јашући на коњма, мноштво велико и војска велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'И подигнућеш се на мој народ Израиља као облак да покријеш земљу; у пошљедње вријеме довешћу те на земљу своју да ме познаду народи кад се посветим у теби пред њима, Гоже!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Овако вели Господ Господ: нијеси ли ти онај о ком говорих у старо вријеме преко слуга својих, пророка Израиљевијех, који пророковаше у оно вријеме годинама да ћу те довести на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'А кад дође Гог на земљу Израиљеву, говори Господ Господ, онда ће се подигнути јарост моја у гњеву мом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'И у ревности својој, у огњу гњева својега говорићу: доиста, тада ће бити дрхат велики у земљи Израиљевој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'И рибе морске и птице небеске и звијери пољске и све што гамиже по земљи, и сви људи по земљи задрхтаће од мене, и горе ће се развалити и врлети попадати, и сви ће зидови попадати на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'И дозваћу на њ мач по свијем горама својим, говори Господ Господ: мач ће се свакога обратити на брата његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'И судићу му помором и крвљу; и пустићу на њ и на чете његове и на многе народе, који буду с њим, силан дажд, камење од града, огањ и сумпор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'И прославићу се и посветићу се и бићу познат пред многим народима, и познаће да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Ти дакле, сине човјечји, пророкуј против Гога, и реци: овако вели Господ Господ: ево ме на те, Гоже, кнеже и главо Месеху и Тувалу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'И вратићу те натраг и водићу те, и извешћу те из сјевернијех крајева и довешћу те на горе Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'И избићу ти лук твој из лијеве руке, и просућу ти из десне руке стријеле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'На горама ћеш Израиљевијем пасти ти и све чете твоје и народи који буду с тобом; птицама, свакојаким птицама крилатијем и звијерима пољским даћу те да те изједу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'На пољу ћеш пасти, јер ја рекох, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'И пустићу огањ на Магога и на оне који живе на острвима без страха; и познаће да сам ја Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'И свето име своје обзнанићу усред народа својега Израиља, и нећу више дати да се скврни свето име моје, него ће познати народи да сам ја Господ, светац у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Ево, доћи ће, и збиће се, говори Господ Господ; то је дан за који говорих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Тада ће изаћи становници градова Израиљевијех, и наложиће на огањ и спалиће оружје и штитове и штитиће, лукове и стријеле, сулице и копља, и ложиће их на огањ седам година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'И неће носити дрва из поља, нити ће сјећи у шуми, него ће оружје ложити на огањ, и оплијениће оне који их плијенише, и поотимаће од онијех који од њих отимаше, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'И у то ћу вријеме дати Гогу мјесто за гроб ондје у Израиљу, долину којом се иде на исток к мору, и она ће стиснути уста путницима; ондје ће бити погребен Гог и све мноштво његово и прозваће се долина мноштва Гогова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'И укопаваће их дом Израиљев седам мјесеца, да би очистили земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'И укопаваће их сав народ, и биће им на славу у онај дан кад се прославим, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'И одвојиће људе који ће једнако ићи по земљи и с онима који пролазе укопавати оне који би остали по земљи да је очисте; послије седам мјесеца тражиће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'И проходиће земљу и ићи по њој, и ко види кости људске, начиниће код њих знак, докле их не укопају гробари у долини мноштва Гогова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'А и граду ће бити име Амона; и тако ће очистити земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Ти, дакле, сине човјечји, овако говори Господ Господ, реци птицама, свакојаким птицама и свијем звијерима пољским: скупите се и ходите, саберите се са свијех страна на жртву моју, коју кољем за вас, на велику жртву на горама Израиљевијем, и јешћете меса и пићете крви;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Јешћете меса јуначкога и пићете крви кнезова земаљских, овнова, јагањаца и јараца и телаца, све угојене стоке Васанске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'И јешћете претилине да ћете се наситити, и пићете крви да ћете се опити од жртава мојих што ћу вам наклати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'И наситићете се за мојим столом коња и коњика, јунака и свакојаких војника, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'И пустићу славу своју међу народе, и сви ће народи видјети суд мој који ћу учинити и моју руку коју ћу дигнути на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'И познаће дом Израиљев да сам ја Господ Бог њихов, од онога дана и послије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'И народи ће познати да се за своје безакоње зароби дом Израиљев, што мени згријешише, те сакрих лице своје од њих, и дадох их у руке непријатељима њиховијем, и сви падоше од мача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'По нечистоти њиховој и по пријеступу њихову учиних им и сакрих лице своје од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Тога ради овако говори Господ Господ: повратићу робље Јаковљево и смиловаћу се свему дому Израиљеву и ревноваћу за свето име своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Пошто поднесу срамоту своју и све пријеступе своје, којима ми преступише док сјеђаху у својој земљи без страха и никога не бјеше да их плаши,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Кад их доведем натраг из народа и саберем их из земаља непријатеља њиховијех, и посветим се у њима пред многим народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'И познаће да сам ја Господ Бог њихов кад одведавши их у ропство међу народе опет их саберем у земљу њихову не оставивши их ниједнога ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'И нећу више крити лица својега од њих кад излијем дух свој на дом Израиљев, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Двадесет пете године робовања нашега, у почетку године, десети дан мјесеца, четрнаесте године од како се узе град, исти дан дође нада ме рука Господња и одведе ме онамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'Утварама Божјим одведе ме у земљу Израиљеву, и постави ме на гору врло високу, на којој бијаше с југа као саграђен град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'И одведе ме онамо, и гле, човјек, који на очи бијаше као од мједи, с ужем ланенијем у руци и с трском мјерачком, и стајаше на вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'И проговори ми тај човјек: сине човјечји, гледај очима својим и слушај ушима својим, и узми на ум све што ћу ти показати, јер си доведен овамо да ти покажем; кажи дому Израиљеву све што видиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'И гле, бјеше зид споља око дома, а у руци оном човјеку трска мјерачка од шест лаката, а лакат бјеше с подланице дужи од обичнога; и измјери грађевину у ширину, и бјеше једна трска, и у висину, и бјеше једна трска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Па дође на врата која бијаху према истоку, и изиде уз басамаке, и измјери један праг вратима, и бјеше у ширину једна трска, и други праг, и бјеше у ширину једна трска;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'И клијети, и свака бјеше једну трску дуга и једну трску широка; а између клијети бјеше пет лаката; и праг на вратима код тријема на унутрашњим вратима, и бјеше с једне трске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'И измјери тријем на вратима унутрашњим, и бјеше једна трска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'И измјери тријем на вратима, и бјеше осам лаката; и довратнике им, и бјеху два лакта; а тријем на вратима бјеше изнутра;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'И клијети код врата према истоку бјеху три амо и три тамо, једне мјере све три, и једне мјере бјеху довратници тамо и амо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'И измјери ширину вратима, и бјеше десет лаката, и тринаест лаката бјеше у дужину вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'И пред клијетима бјеше мјеста један лакат, и за један лакат бјеше мјеста с друге стране, и у свакој клијети бјеше шест лаката отуда и шест лаката одовуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Послије измјери врата од крова једне клијети до крова друге, и бјеше у ширину двадесет и пет лаката, врата према вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'И начини довратнике од шездесет лаката, и пред довратницима тријем на вратима унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'И од лица врата на која се улази до лица тријема на унутрашњим вратима бијаше педесет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'И бијаху прозори на клијетима и на довратницима њиховијем сужени унутра око врата, тако и на тријемовима, прозори бијаху изнутра свуда унаоколо, и по довратницима палме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Потом ме уведе у спољашњи тријем, и гле, бијаху клијети и под начињен свуда унаоколо у тријему, тридесет клијети на поду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'А тај под покрај врата према дужини врата бијаше нижи под.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Потом измјери ширину од лица доњих врата до лица унутрашњега тријема споља, и бјеше сто лаката к истоку и сјеверу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'И врата која бјеху к сјеверу на тријему спољашњем измјери у дужину и у ширину;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'И бијаху три клијети тамо и три амо, и довратници им и тријемови бијаху исте мјере као у првијех врата; педесет лаката бијаше у дужину а у ширину двадесет и пет лаката;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'И прозори им и тријемови и палме бијаху на мјеру као на вратима која гледају на исток, и иђаше се к њима уз седам басамака, и тријемови бијаху пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'И врата од унутрашњега тријема бијаху према вратима сјевернијем и источнијем, и измјери од врата до врата, и бјеше сто лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Послије ме одведе к југу, и гле, бјеху врата према југу; и измјери им довратнике и тријемове, и бјеше иста мјера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'И бијаху прозори на њима и на тријемовима њиховијем унаоколо као они прозори; педесет лаката бијаше у дужину и двадесет и пет лаката у ширину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'И иђаше се к њима уза седам басамака, и тријемови бијаху пред њима, и палме једна отуда а једна одовуда по довратницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'И врата од унутрашњега тријема бијаху према југу; и измјери од врата до врата к југу, и бјеше сто лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Тада ме уведе у унутрашњи тријем јужнијем вратима; и измјери јужна врата, и бјеше иста мјера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'И клијети њихове и довратници и тријемови бијаху исте мјере, и прозори на њима и на тријемовима унаоколо; педесет лаката бијаше у дужину и двадесет и пет лаката у ширину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'И тријемови бијаху унаоколо, двадесет и пет лаката у дужину и пет лаката у ширину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'И тријемови им бијаху према спољашњем тријему, и палме по довратницима, и уз осам басамака иђаше се к њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Потом ме одведе у унутрашњи тријем к истоку, и измјери врата, и бјеше иста мјера;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'И клијети им и довратници и тријемови бјеху исте мјере; и бјеху прозори на њима и на тријемовима њиховијем унаоколо; у дужину бјеше педесет лаката а у ширину двадесет и пет лаката;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'И тријемови им бјеху према спољашњем тријему, и палме по довратницима и тамо и амо, и уз осам басамака иђаше се к њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Потом одведе ме на сјеверна врата и измјери их, и бјеху исте мјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Тако и клијети им и довратници и тријемови и прозори унаоколо; у дужину педесет лаката а у ширину двадесет и пет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'И довратници им бијаху према спољашњем тријему, и палме по довратницима и тамо и амо, и уз осам басамака иђаше се к њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'И клијети с вратима бијаху код довратника тијех врата, ондје се праху жртве паљенице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'А у тријему од врата бијаху два стола с једне стране и два стола с друге стране да се на њима кољу жртве паљенице и жртве за гријех и за кривицу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'И на страни споља како се улази на сјеверна врата бијаху два стола, и на другој страни у тријему од истијех врата бијаху два стола;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Четири стола бјеху с једне стране и четири с друге стране уз врата, осам столова, на којима се кољаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'А четири стола за жртву паљеницу бјеху од тесанога камена, у дужину подруг лакта, и подруг лакта у ширину а у висину један лакат, и на њима се остављаше оруђе којим се кољаху жртве паљенице и друге жртве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'И унутра бијаху куке с подланице свуда унаоколо, а на столове се меташе месо од жртава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'И споља пред вратима унутрашњим бјеху клијети за пјеваче у унутрашњем тријему; једне бјеху уз врата сјеверна и гледаху према југу а друге бјеху уз источна врата и гледаху према сјеверу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Тада ми рече: ове клијети што гледају на југ јесу за свештенике који служе око дома;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'А оне клијети што гледају на сјевер јесу за свештенике који служе код олтара; то су синови Садокови, који између синова Левијевих приступају ка Господу да му служе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Потом измјери тријем, и бјеше у дужину сто лаката и у ширину сто лаката, четвртаст; и олтар бијаше пред домом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Послије ме одведе у тријем од дома, и измјери довратнике тријему, и бјеше пет лаката отуд и пет лаката одовуд; а врата бјеху широка три лакта отуд и три лакта одовуд;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Дужина тријему бјеше двадесет лаката а ширина једанаест лаката, и уз басамаке се иђаше к њему, и ступови бијаху уз довратнике, један отуд и један одовуд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Послије ме одведе у цркву, и измјери довратнике, и бјеше шест лаката у ширину отуда и шест лаката у ширину одовуда, према ширини шатору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'А вратима ширина бјеше десет лаката, а стране вратима бјеху од пет лаката отуда и од пет лаката одовуда; потом измјери јој дужину, и бјеше четрдесет лаката, и ширину, и бјеше двадесет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Па уђе унутра и измјери довратнике, и бјеху од два лакта; а врата бјеху од шест лаката, а ширина вратима седам лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'И измјери дужину ондје, и бјеше двадесет лаката, а ширина двадесет лаката унутра у цркви; и рече ми: ово је светиња над светињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'И измјери зид дому, и бјеше шест лаката, и ширина клијети унаоколо у дому бјеше четири лакта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'А клијети бијаху по три једна над другом, и бјеше их тридесет, и допираху до зида који бијаше у дому унаоколо за клијети да их држи, а не држаше их зид од дома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Јер се рашириваше грађевина озго унаоколо за клијети које бијаху око дома озго свуда унаоколо, и зато грађевина бијаше озго шира, и најниже клијети бијаху озго шире за средње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'И видјех уз дом висину унаоколо; а под у клијети бијаше с цијеле трске, шест лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Ширина зиду уз клијети споља бјеше пет лаката, а бјеше празно мјесто клијетима које бјеху уз дом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'И међу клијетима бјеше двадесет лаката ширине око дома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'А врата од клијети бјеху к празном мјесту, једна према сјеверу а једна према југу, а ширина оном празном мјесту пет лаката свуда унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'А грађевина која бјеше пред одијељеном страном к западу имаше седамдесет лаката у ширину, а зид те грађевине бјеше пет лаката широк унаоколо, и деведесет лаката дуг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Потом измјери дом, и бијаше у дужину сто лаката; одијељена страна и грађевина и зидови јој, све заједно у дужину сто лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'И ширина пред домом и одијељеном страном к истоку имаше сто лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'И измјери дужину грађевини пред одијељеном страном што бијаше иза ње, и клијети њезине отуда и одовуда, и бјеше сто лаката; и унутрашњи дом и ходнике од тријема;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Прагове и прозоре сужене, и клијети унаоколо у три реда, према прагу, што бјеше обложено дрветом свуда унаоколо, од земље до прозора, и прозори бјеху обложени;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'До врх врата и до дома унутрашњега, и споља, и сав зид унаоколо изнутра и споља на мјеру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'И бјеху начињени херувими и палме, једна палма међу два херувима, и у свакога херувима бјеху два лица:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Лице човјечје према палми отуда, и лице лавово према палми одовуда; тако бјеше начињено по свему дому унаоколо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Од земље до врх врата бјеху херувими и палме начињене, тако и по зиду у цркви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'У цркве довратници бјеху на четири угла; и светињи лице бјеше онако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Олтар бјеше дрвен, три лакта висок, и два лакта дуг, с угловима, и дужина и стране бјеху од дрвета. И рече ми: то је сто, који стоји пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Двоја врата бјеху у цркви и светињи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'А у врата бјеху два крила, која се обртаху, два крила у једнијех врата и два у других.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'И на вратима црквенијем бјеху начињени херувими и палме, као по зидовима; и греде дрвене бијеху пред тријемом споља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'И бијаху уски прозори и палме отуда и одовуда по странама тријему и по клијетима у дому и по гредама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'И изведе ме у спољашњи тријем према сјеверу, и доведе ме ка клијетима, које бијаху према одијељеној страни и према грађевини на сјеверу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'С лица бјеше у дужину сто лаката код сјевернијех врата, а у ширину педесет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Према унутрашњем тријему од двадесет лаката и према поду спољашњега тријема бијаху клијети према клијетима у три реда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'И пред клијетима бијаше ходник у ширину од десет лаката, унутра, пут к њима од једнога лакта, и врата бјеху према сјеверу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'А најгорње клијети бјеху тјешње, јер клијети доње и средње у згради излажаху већма него оне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Јер бијаху на три пода, али немаху ступова као у тријему, и зато се суживаше изнад доњега и средњега од земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'А ограда која бијаше споља према клијетима к тријему спољашњем пред клијетима имаше у дужину педесет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Јер дужина клијетима, које бијаху у тријему спољашњем, бијаше педесет лаката. И гле, пред црквом бјеше сто лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'А под тијем клијетима бијаше улаз с истока, којим се улажаше у њих из спољашњега тријема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'У ширини ограде тога тријема к истоку пред одијељеном страном и пред грађевином бијеху клијети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'А пред њима бијаше пут као код сјевернијех клијети; једнаке дужине и једнаке ширине бијаху, и излази им и врата бијаху једнака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'И кака бијаху врата у клијети које бијаху према југу, така бијаху врата гдје се почињаше пут пред оградом право к истоку, кад се иде к њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'И рече ми: сјеверне клијети и јужне клијети пред одијељеном страном јесу свете клијети, гдје свештеници који приступају ка Господу једу пресвете ствари, ондје ће остављати пресвете ствари и дар и принос за гријех и принос за кривицу, јер је свето мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Кад свештеници уђу, неће излазити из светиње у спољашњи тријем, него ће ондје остављати хаљине своје у којима служе, јер су свете, и облачиће друге хаљине, па онда излазити к народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'И измјеривши дом унутрашњи одведе ме на врата источна и измјери свуда унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Измјери источну страну трском мјерачком, и бјеше пет стотина трсака, трском мјерачком унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Измјери сјеверну страну, и бјеше пет стотина трсака, трском мјерачком унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Измјери јужну страну, и бјеше пет стотина трсака, трском мјерачком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'И окренувши се на западну страну, измјери, и бјеше пет стотина трсака, трском мјерачком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Измјери са четири стране, и бјеше зид унаоколо пет стотина трсака дуг и пет стотина широк да раздваја свето мјесто од свјетскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Потом ме одведе к вратима која гледају на исток.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'И гле, слава Бога Израиљева дохођаше од истока, и глас јој бијаше као глас велике воде, и земља се сјаше од славе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'И утвара коју видјех бијаше као утвара коју видјех кад дођох да затрем град: бјеше утвара као она коју видјех на ријеци Хевару; и падох на лице своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'А слава Господња уђе у дом на врата која гледају на исток.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'И подиже ме дух и одведе ме у унутрашњи тријем; и гле, дом бијаше пун славе Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'И чух гдје ми проговори из дома, и човјек стајаше код мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'И рече ми: сине човјечји, ово је мјесто пријестола мојега и мјесто стопа ногу мојих, гдје ћу наставати усред синова Израиљевијех довијека; и дом Израиљев неће више скврнити светога имена мојега, ни они ни цареви њихови курварством својим и мртвијем тјелесима царева својих на висинама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Меташе праг свој до мога прага, и довратнике своје до мојих довратника и преграду између мене и себе, те скврнише свето име моје гадовима својим које чињаху; зато их сатрх у гњеву свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Сада нека уклоне далеко од мене курварство своје и мртва тјелеса царева својих и наставаћу усред њих довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Ти, сине човјечји, покажи дому Израиљеву овај дом, нека се постиде безакоња својега, и нека измјере све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'И кад се постиде свега што су чинили, покажи им облик од дома и ред и изласке и уласке, и све облике и сву уредбу, и све облике и све законе, и опиши им га да пазе на сав облик његов и на све уредбе, и тако чине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'А ово је закон за дом: наврх горе колико заузима унаоколо да буде светиња над светињама. Ето, то је закон за дом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'А ово је мјера за олтар на лакте, а у лакту је један обичан лакат и подланица: подножје му лакат високо и лакат широко, а оплата на њему по крају унаоколо с педи; така је горња страна олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'А од подножја на земљи до нижега појаса два лакта, и у ширину један лакат; а од мањега појаса до већега појаса четири лакта, и у ширину лакат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'А сам олтар да буде четири лакта висок, од олтара горе да буде четири рога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'А олтар да буде дванаест лаката дуг и дванаест лаката широк, и четвртаст на четири стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'И појас да је четрнаест лаката дуг и четрнаест лаката широк на четири стране, а оплата око њега од по лакта, и подножје му од лакта унаоколо, и басамаци му да буду окренути на исток.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'И рече ми: сине човјечји, овако вели Господ Господ, ово су наредбе за олтар кад се начини да се на њему приносе жртве паљенице и да се кропи крвљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'И свештеницима Левитима који су од сјемена Садокова, који приступају к мени, говори Господ Господ, да ми служе, даћеш јунца за жртву за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'И узми крви његове, и помажи му четири рога и четири угла од појаса и оплату унаоколо, тако ћеш га очистити и учинити очишћење за њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Потом узми јунца за гријех, и нека се спали на мјесту одређеном у дому изван светиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'А други дан принеси јарца здрава за гријех, и нека очисте њим олтар како су очистили јунцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'А кад очистиш, принеси јунца здрава и овна од стада здрава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'И кад их принесеш пред Господом, нека свештеници баце на њих соли и принесу их на жртву паљеницу Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Седам дана приноси јарца за гријех сваки дан; и јунца и овна из стада здрава нека приносе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Седам дана нека чине очишћење за олтар, и очисте га и посвете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'А кад се наврше ти дани, осмога дана и послије нека приносе свештеници на олтару жртве ваше паљенице и жртве ваше захвалне, и примићу вас, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'И одведе ме опет к вратима спољашњим од светиње, која гледају на исток, а она бјеху затворена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'И рече ми Господ: ова врата нека буду затворена и да се не отворају, и нико да не улази на њих, јер је Господ Бог Израиљев ушао на њих; зато нека буду затворена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'За кнеза су; сам кнез нека сједа на њима да једе хљеб пред Господом; кроз тријем од овијех врата нека улази и истијем путем нека излази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'И одведе ме к сјевернијем вратима пред дом; и видјех, и гле, дом Господњи бјеше пун славе Господње, и падох на лице своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'И рече ми Господ: сине човјечји, пази срцем својим и види очима својим и слушај ушима својим, што ћу ти казати за све уредбе дома Господњега и за све законе његове; пази срцем својим на све улазе у дом и на све излазе из светиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'И реци одметничком дому Израиљеву: овако вели Господ Господ: доста је гадова ваших, доме Израиљев,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Што уводисте туђинце необрезана срца и необрезана тијела да буду у мојој светињи да скврне дом мој, и приносисте мој хљеб, претилину и крв, и тамо преступаше мој завјет осим свијех гадова ваших;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'И не извршивасте што треба за моју светињу, него постависте људе по својој вољи да извршују што треба у мојој светињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Овако вели Господ Господ: ниједан туђин необрезана срца и необрезана тијела да не долази у моју светињу, ниједан од свијех туђинаца који су међу синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'А Левити који отступише од мене кад зађе Израиљ, који зађоше од мене за гаднијем боговима својим, носиће безакоње своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'И биће слуге у мојој светињи у служби на вратима од дома служећи дому; они ће клати жртве паљенице и друге жртве народу, и стајаће пред њима служећи им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Што им служише пред гаднијем боговима њиховијем и бише дому Израиљеву спотицање на безакоње, зато подигох руку своју на њих, говори Господ Господ, да ће носити безакоње своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'И неће приступати к мени да ми врше свештеничку службу, нити којој светињи мојој, ни светињи над светињама неће приступати, него ће носити срамоту своју и гадове своје, које чинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Него ћу их поставити за чуваре дому на сваку службу његову и на све што бива у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'А свештеници Левити синови Садокови, који извршиваху што треба у мојој светињи, кад синови Израиљеви зађоше од мене, они ће приступати к мени да ми служе, и стајаће преда мном приносећи ми претилину и крв, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Они нека улазе у моју светињу и они нека приступају к столу мојему да ми служе и нека извршују што сам заповједио да се извршује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'И кад улазе на врата унутрашњега тријема, нека обуку ланене хаљине, и ништа да не буде на њима вунено кад служе на вратима унутрашњега тријема и у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'На главама нека им буду капе ланене и гаће ланене по бедрима, и да се не пашу ничим ода шта би се знојили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'А кад излазе у тријем спољашњи, у спољашњи тријем к народу, нека свуку са себе хаљине у којима служе, и оставе их у клијетима светијем, па нека обуку друге хаљине, да не освећују народа хаљинама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'И главе своје да не брију, а ни косе да не остављају, него нека стригу главе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'И вина да не пије ни један свештеник кад хоће да уђе у унутрашњи тријем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'И удовицом ни пуштеницом да се не жене, него дјевојком од сјемена дома Израиљева или удовицом свештеничком нека се жене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'И народ мој нека уче што је свето што ли није свето, и нека их уче распознавати нечисто од чистога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'А у распри нека стану да суде, по мојим законима нека суде, и законе моје и уредбе моје нека држе о свијем празницима мојим, и суботе моје нека светкују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'И к мртвацу да не иду да се не оскврне; само за оцем и за матером и за сином и за кћерју, за братом и за сестром неудатом могу се оскврнити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'А кад се очисти, нека му се броји седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'И у који би дан ушао у светињу, у тријем унутрашњи, да служи у светињи, нека принесе жртву за гријех свој, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'А нашљедство што ће имати, ја сам њихово нашљедство; и ви им не дајте достојања у Израиљу, ја сам њихово достојање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Дар и жртву за гријех и жртву за кривицу они ће јести; и све завјетовано у Израиљу њихово ће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'И првине од свакога првога рода и сви приноси подизани од свега између свијех приноса ваших биће свештеницима; и првине од тијеста својега даваћете свештенику да би почивао благослов на домовима вашим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Свештеници да не једу мрцинога ни што звјерка раскине, било птица или што од стоке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'А кад станете дијелити земљу у нашљедство, принесите принос Господу, свет дио од земље, у дужину двадесет и пет тисућа лаката, и у ширину десет тисућа, то нека буде свето по свијем међама својим унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Од тога нека буде за светињу пет стотина лаката у дужину и пет стотина у ширину, четвртасто отсвуда, и педесет лаката унаоколо за подграђа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'По тој мјери измјери у дужину двадесет и пет тисућа и у ширину десет тисућа, и ту нека буде светиња и светиња над светињама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'То нека буде свет дио од земље свештеницима, који служе у светињи, који приступају да служе Господу, и нека им буде мјесто за куће и свето мјесто за светињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'А двадесет и пет тисућа лаката у дужину и десет тисућа у ширину нека буде Левитима који служе у дому у државу с двадесет клијети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'И граду подајте достојање пет тисућа лаката у ширину и двадесет и пет тисућа у дужину према светом дијелу; то нека је за сав дом Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'А кнезу нека буде с обје стране светога дијела и достојања градскога пред светијем дијелом и пред градским достојањем, са западне стране на запад и с источне стране на исток, а дужина да буде према сваком од тијех дијелова од западне међе до источне међе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Та земља да му је достојање у Израиљу, да више не отимају кнезови моји од народа мојега, него осталу земљу да даду дому Израиљеву по племенима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Овако вели Господ Господ: доста је, кнезови Израиљеви; прођите се насиља и отимања, и творите суд и правду, и скините тешке послове своје с мојега народа, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Мјерила да су вам права, и ефа права, и ват прав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Ефа и ват да су једне мјере, да ват бере десетину хомора, и ефа десетину хомора; мјера да им је према хомору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'И сикал да је двадесет гера, а мина да вам је двадесет сикала, двадесет и пет сикала, и петнаест сикала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Ово је принос што ћете приносити: шестина ефе од хомора пшенице, тако и од јечма дајите шестину ефе од хомора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'А за уље је уредба ова: ват је мјера за уље; десетина вата од једнога кора, који је хомор од десет вата, јер је десет вата хомор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'А од ситне стоке једно од двије стотине с добријех пасишта синова Израиљевијех за дар и за жртву паљеницу и за жртву захвалну, да се чини очишћење за њих говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Сав народ земаљски да даје овај принос кнезу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'А кнез је дужан давати жртве паљенице с даром и наљевом на празнике и на младине и у суботе, о свијем светковинама дома Израиљева; он нека приноси жртву за гријех с даром и жртву паљеницу и захвалну да чини очишћење за дом Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Овако вели Господ Господ: првога дана првога мјесеца узми јунца здрава, и очисти светињу њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'И нека свештеник узме крви од те жртве за гријех, и помаже њом довратнике на дому и четири угла од појаса на олтару и довратнике од врата на унутрашњем тријему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Тако учини и седмога дана истога мјесеца за свакога који згријеши из незнања и за простога; тако ћете очистити дом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Првога мјесеца четрнаестога дана да вам је пасха, празник седам дана, хљебови пријесни да се једу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'И тај дан нека принесе кнез за се и за сав народ земаљски јунца на жртву за гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'А за седам дана празника нека приноси на жртву паљеницу Господу по седам јунаца и седам овнова здравијех на дан, за онијех седам дана, и на жртву за гријех јарца на дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'И за дар по ефу на јунца и ефу на овна нека приноси, и ин уља на сваку ефу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Седмога мјесеца петнаестога дана на празник нека приноси исто тако за седам дана и жртву за гријех и жртву паљеницу и дар и уље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Овако вели Господ Господ: врата унутрашњега тријема, која гледају на исток, нека су затворена у шест дана тежатнијех, а у суботу нека се отворају, и на дан младине нека се отворају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'И кнез нека дође кроз тријем од врата спољашњих, и нека стане код довратника, а свештеници нека принесу његову жртву паљеницу и жртву захвалну, и он поклонив се на прагу нека отиде, а врата да се не затворају до вечера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'И народ земаљски нека се поклања Господу на истијем вратима у суботе и на младине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'А жртва паљеница, што ће приносити кнез Господу суботом, биће шест јагањаца здравијех и ован здрав;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'А дар ефа на овна, а на јагањце дар колико му рука може, и ин уља на ефу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'А о младини да буде јунац здрав, и шест јагањаца и ован, све здраво;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'И дар да принесе ефу на јунца и ефу на овна, а на јагањце колико му може рука, и уља ин на ефу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'А кнез кад иде, нека иде кроз тријем од врата, и истијем путем нека одлази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'А кад народ земаљски доходи пред Господа о празницима, ко уђе на сјеверна врата да се поклони, нека излази на јужна врата; а ко уђе на јужна врата, нека излази на сјеверна врата; нека се не враћа на врата на која уђе, него нека излази на она која су насупрот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'А кнез с њима нека улази кад они улазе, и нека излази кад они излазе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'И о празницима и о светковинама дар нека је ефа на јунца, и ефа на овна, а на јагањце колико му рука даде, а уља ин на ефу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'А кад кнез приноси драговољну жртву, паљеницу или захвалну, од своје воље Господу, тада нека му се отворе врата која гледају на исток, и нека принесе жртву своју паљеницу и захвалну, како чини суботом; потом нека изиде, и врата нека се затворе кад изиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'И приноси сваки дан Господу на жртву паљеницу јагње од године здраво; свако јутро приноси га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'И додај на њ дар свако јутро шестину ефе и уља трећину ина, да се покропи бијело брашно; то је ваздашњи дар Господу уредбом вјечном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'И тако нека приносе јагње и дар и уље свако јутро, жртву паљеницу свагдашњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Овако вели Господ Господ: ако кнез да дар коме сину свом од својега нашљедства, нека буде синовима његовијем, њихово је достојање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Ако ли да дар од својега нашљедства коме слузи својему, нека му буде до године опросне, а онда нека се врати кнезу, јер је његово нашљедство, синовима његовијем нека буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'И кнез да не узима народу ништа од нашљедства тјерајући их с њихова нашљедства; од својега достојања нека даје синовима својим нашљедство да се не разгони мој народ, нико са својега нашљедства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Потом ме одведе кроз улаз који је покрај врата у свете клијети свештеничке које гледају на сјевер, и гле, ондје бијаше неко мјесто у дну према западу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'И рече ми: ово је мјесто гдје ће свештеници варити принос за кривицу и за гријех, гдје ће пећи дар да не износе у спољашњи тријем и народ посвећују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Тада ме изведе у спољашњи тријем, и проведе ме у четири угла од тријема, и гле, у сваком углу од тријема бијаше тријем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'У четири угла од тријема бијаху тријемови с димњацима, у дужину од четрдесет лаката, а у ширину од тридесет лаката, сва четири на угловима бијаху једне мјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'У њима четирма бјеше зид унаоколо, а под тијем зидом бијаху огњишта свуда унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'И рече ми: ово су кухиње, гдје ће жртве народне кухати који служе дому.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Потом одведе ме опет к вратима од дома, и гле, вода излажаше испод прага од дома к истоку, јер лице дому бијаше према истоку; и вода тецијаше доље с десне стране дома, с јужне стране олтара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Потом ме изведе вратима сјевернијем, и проведе ме около спољашњим путем к спољашњим вратима, путем који гледа на исток, и гле, вода тецијаше с десне стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'И кад човјек изиде на исток с мјером у руци, измјери тисућу лаката, и преведе ме преко воде, и вода бијаше до глежања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Потом опет измјери тисућу лаката, и преведе ме преко воде, а вода бјеше до кољена; опет измјери тисућу лаката, и преведе ме, а вода бјеше до појаса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'И опет измјери тисућу лаката, и поста ријека, које не могох пријећи, јер вода устаде да требаше пливати, поста ријека која се не може прегазити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Тада ми рече: видје ли, сине човјечји? И одведе ме и поврати ме на бријег ријеци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'А кад се вратих, гле, по бријегу ријеци врло много дрва отуд и одовуд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'И рече ми: ова вода тече у Галилеју прву, и спушта се у поље, и утјече у море, и кад дође у море, његова ће вода постати здрава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'И све животиње што се мичу куда год дођу ове ријеке, биће живе и биће велико мноштво риба, јер кад дође ова вода онамо, друга ће постати здрава, и све ће бити живо гдје ова ријека дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'И рибари ће стајати крај њега од Енгада до Ен-Еглаима и разапињати мреже; и биће риба свакојаких врло много као у великом мору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'А баре његове и глибови неће бити здрави, него ће остати слани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'А крај ријеке по бријегу отуд и одовуд рашће дрвета свакојака родна, којима лишће неће опадати нити ће рода на њима нестајати; свакога ће мјесеца рађати нов род, јер јој вода тече из светиње; зато ће род њихов бити за јело и лишће њихово за лијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Овако вели Господ Господ: ово су међе у којима ћете наслиједити земљу по дванаест племена Израиљевијех: Јосифу два дијела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Наслиједићете је како један тако други, за коју подигох руку своју да ћу је дати оцима вашим; и припашће вам та земља у нашљедство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Ово је дакле међа земљи: на сјеверној страни од великога мора на Етлон како се иде у Седад,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Емат, Вирота, Сиврајим, који је између међе Дамаштанске и међе Ематске, Асаратихон, који је на међи Авранској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Тако ће бити међе од мора Асаренан, међа Дамаштанска и сјеверна страна на сјевер, и међа Ематска; то је сјеверна страна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'А источну страну измјерите од Аврана и од Дамаска и од Галада и од земље Израиљеве на Јордану, од те међе до мора источнога. И то је источна страна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'А јужна страна према југу од Тамара до воде Мериве у Кадису, дуж потока до великога мора. И то је јужна страна према југу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'А западна ће страна бити велико море, од те међе до према уласку у Емат; то је западна страна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'И раздијелите ту земљу међу се по племенима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'А раздијелите је у нашљедство међу се и међу иностранце који се баве међу вама, који би изродили синове међу вама, и они нека су вам као домородац међу синовима Израиљевијем, с вама нека добију нашљедство међу племенима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'И у ком се племену иностранац бави, у оном му подајте нашљедство, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'А ово су имена племенима. Од краја према сјеверу, уз пут Етлонски како се иде у Емат и Асаренан, на међу Дамаштанску на сјевер покрај Емата, од источне стране до западне, Даново, једно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'А уз међу Данову, од источне стране до западне, Асирово, једно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'А уз међу Асирову, од источне стране до западне, Нефталимово, једно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'А уз међу Нефталимову, од источне стране до западне, Манасијино, једно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'А уз међу Манасијину, од источне стране до западне, Јефремово, једно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'А уз међу Јефремову, од источне стране до западне, Рувимово, једно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'А уз међу Рувимову, од источне стране до западне, Јудино, једно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'А уз међу Јудину, од источне стране до западне, нека буде принос што ћете принијети, двадесет и пет тисућа лаката у ширину, а у дужину као који други дио, од источне стране до западне, и светиња да буде усред њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Принос који ћете принијети Господу, нека буде од двадесет и пет тисућа лаката у дужину и од десет тисућа у ширину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'И тај ће свети принос бити свештеницима, са сјевера двадесет и пет тисућа лаката у дужину, а са запада десет тисућа у ширину, и с истока десет тисућа у ширину, а с југа двадесет и пет тисућа у дужину; и светиња Господња да буде усред њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'То ће бити свештеницима посвећенијем између синова Садоковијех који држаше што сам наредио да се држи и не зађоше као други Левити, кад зађоше синови Израиљеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Њихов ће бити свети принос од земље, светиња над светињама, уз међе Левитске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'А Левити да имају уз међе свештеничке двадесет и пет тисућа лаката у дужину, и десет тисућа у ширину; сва дужина да буде двадесет и пет тисућа, а ширина десет тисућа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'А од тога ништа да не продају ни промијењују, ни да преносе првина земаљских, јер је светиња Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'А пет тисућа лаката што остаје у ширину према двадесет и пет тисућа биће мјесто посвећено, за град, за насеље, и за подграђа, и град да буде усред њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'А ово да му је мјера: са сјеверне стране четири тисуће и пет стотина лаката, и с јужне стране четири тисуће и пет стотина, и с источне стране четири тисуће и пет стотина, и са западне стране четири тисуће и пет стотина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'И подграђе ће бити двјеста и педесет лаката са сјевера, и двјеста и педесет с југа, и двјеста и педесет с истока, и двјеста и педесет са запада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'А што остане у дужину према светом приносу, десет тисућа лаката на исток и десет тисућа на запад према светом приносу, од тога доходак нека буде храна слугама градским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'А слуге које ће служити граду биће из свијех племена Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Сав овај принос, двадесет и пет тисућа лаката уз двадесет и пет тисућа, четвртаст, принијеће у принос свети за достојање граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'А што остане с обје стране светом приносу и достојању градском, према двадесет и пет тисућа лаката приноса до међе источне, и са запада према двадесет и пет тисућа лаката дуж западне међе према дијеловима, то да је кнежево; тако ће свети принос и светиња дома бити у сриједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'А од достојања Левитскога и од достојања градскога, усред онога што је кнежево, између међе Јудине и међе Венијаминове, да је кнежево.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'А остала племена биће: од источне стране до западне стране, Венијаминово, једно;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'А уз међу Венијаминову, од источне стране до западне, Симеуново, једно;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'А уз међу Симеунову, од источне стране до западне, Исахарово, једно;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'А уз међу Исахарову, од источне стране до западне, Завулоново, једно;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'А уз међу Завулонову, од источне стране до западне, Гадово, једно;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'А уз међу Гадову с јужне стране, на југ, међа је од Тамара до воде Мериве у Кадису, дуж потока до великога мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'То је земља коју ћете ждријебом раздијелити племенима Израиљевијем у нашљедство, и то су им дијелови, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'А ово су крајеви граду: са сјеверне стране четири тисуће и пет стотина лаката да буде мјера;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'А врата градска да се назову именима племена Израиљевијех, троја врата са сјевера; једна врата Рувимова, једна врата Јудина, једна врата Левијева;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'И с источне стране четири тисуће и пет стотина лаката, и троја врата: једна врата Јосифова, једна врата Венијаминова, једна врата Данова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'И с јужне стране четири тисуће и пет стотина лаката да буде мјера, и троја врата: једна врата Симеунова, једна врата Исахарова, једна врата Завулонова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Са западне стране четири тисуће и пет стотина лаката, и троја врата: једна врата Гадова, једна врата Асирова, једна врата Нефталимова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Унаоколо ће бити осамнаест тисућа лаката, а име ће граду од тога дана бити: Господ је ту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Године треће царовања Јоакима цара Јудина дође Навуходоносор цар Вавилонски на Јерусалим, и опколи га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'И Господ му даде у руку Јоакима цара Јудина и дио судова дома Божијега, и однесе их у земљу Сенар у дом бога својега, и метну судове у ризницу бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'И рече цар Асфеназу старјешини својих дворана да доведе између синова Израиљевијех, и од царског сјемена и од кнезова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Младиће на којима нема мане, и који су лијепа лица и научени свакој мудрости и вјешти знању и разумни и који могу стајати у царском двору, па да их учи књигу и језик Халдејски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'И одреди им цар оброк на дан од јела царскога и од вина које он пијаше, да се хране три године а послије да стоје пред царем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'А међу њима бјеху од синова Јудинијех Данило, Ананија, Мисаило и Азарија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'А старјешина над дворанима предје им имена, и Данилу надје име Валтасар, а Ананији Седрах, а Мисаилу Мисах, а Азарији Авденаго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Али Данило науми да се не скврни оброком јела царева и вином које он пијаше, и замоли се старјешини над дворанима да се не скврни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'И даде Бог Данилу те нађе милост и љубав у старјешине над дворанима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'И рече старјешина над дворанима Данилу: бојим се господара својега цара, који вам је одредио јело и пиће; јер кад цар види лица ваша лошија него у осталих младића, ваших врсника, зашто да ми учините да будем главом крив цару?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'А Данило рече Амелсару, којега старјешина над дворанима постави над Данилом, Ананијом, Мисаилом и Азаријом:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Огледај слуге своје за десет дана, нека нам се даје вариво да једемо и воде да пијемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Па онда нека нам се виде лица пред тобом и лица младићима који једу царско јело, па како видиш, онако чини са слугама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'И послуша их у том, и огледа их за десет дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'А послије десет дана лица им дођоше љепша и меснатија него у свијех младића који јеђаху царско јело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'И Амелсар узимаше јело њихово и вино које њима требаше пити, и даваше им варива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'И даде Бог свој четворици младића знање и разум у свакој књизи и мудрости; а Данилу даде да разумије сваку утвару и сне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'И кад прође вријеме по ком цар бјеше рекао да их изведу, изведе их старјешина над дворанима пред Навуходоносора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'И говори цар с њима, и не нађе се међу свјема њима ни један као Данило, Ананија, Мисаило и Азарија; и стајаху пред царем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'И у свему чему треба мудрост и разум, зашто их цар запита, нађе да су десет пута бољи од свијех врача и звјездара што их бјеше у свему царству његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'И оста Данило до прве године цара Кира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'А друге године царовања Навуходоносорова усни Навуходоносор сан, и узнемири му се дух и сан га прође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'И рече цар да дозову враче и звјездаре и гатаре и Халдеје да кажу цару сан његов. И дођоше и сташе пред царем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'И рече им цар: усних сан, и узнемири ми се дух како бих дознао што сам снио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'А Халдеји рекоше цару Сирски: царе, да си жив довијека! приповједи сан слугама својим, па ћемо ти казати што значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'А цар одговори и рече Халдејима: заборавио сам; ако ми не кажете што сам снио и што значи, бићете исјечени и куће ће ваше бити буништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Ако ли ми кажете што сам снио и што значи, добићете од мене даре и поклоне и велику част; кажите ми дакле што сам снио и што значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Одговорише опет и рекоше: нека цар приповједи сан слугама својим, па ћемо казати што значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Цар одговори и рече: доиста видим да хоћете времена да добијете; јер видите да сам заборавио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Али ако ми не кажете што сам снио и што значи, један вам је суд; јер сте се договорили да кажете преда мном лаж и пријевару док се промијени вријеме; зато кажите ми сан, па ћу видјети да ми можете казати што значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Одговорише Халдеји цару и рекоше: нема човјека на земљи који би могао казати цару то што иште; зато ниједан цар ни кнез ни властелин није нигда искао тако што од врача или звјездара или Халдејца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'И што цар иште врло је тешко; нити има другога који би могао казати цару осим богова, који не живе међу људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Зато се цар разљути и разгњеви врло, и заповједи да се погубе сви мудраци Вавилонски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'И кад изиде заповијест, те убијаху мудраце, тражаху и Данила и другове његове да их убију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Тада Данило одговори мудро и разумно Ариоху заповједнику стражарском, који бијаше изашао да убија мудраце Вавилонске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Одговори и рече Ариоху властелину цареву: зашто је тако нагла заповијест од цара? Тада Ариох каза ствар Данилу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'А Данило отиде и замоли цара да му остави времена, пак ће казати цару што сан значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Потом отиде Данило кући својој, и каза ствар Ананији, Мисаилу и Азарији, друговима својим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Да се моле за милост Богу небескому ради те тајне, да не би погинули Данило и другови му с осталијем мудрацима Вавилонским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'И објави се тајна Данилу у ноћној утвари; тада Данило благослови Бога небескога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Проговори Данило и рече: да је благословено име Господње од вијека до вијека; јер је његова мудрост и сила;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'И он мијења времена и часе; смеће цареве, и поставља цареве; даје мудрост мудрима и разум разумнима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Он открива што је дубоко и сакривено, зна што је у мраку, и свјетлост код њега станује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Тебе, Боже отаца мојих, хвалим и славим, што си ми дао мудрост и силу, и што си ми објавио зашто те молисмо објавив нам ствар цареву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Тада отиде Данило к Ариоху, којега цар бјеше одредио да погуби мудраце Вавилонске; и дошав овако му рече: не губи мудраца Вавилонских; изведи ме пред цара да кажем цару што сан значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Тада Ариох брже изведе Данила пред цара, и овако му рече: нађох човјека између робља Јудина, који ће казати цару што сан значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'А цар проговори и рече Данилу, који се зваше Валтасар: можеш ли ми казати сан који сам снио и што значи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Одговори Данило цару и рече: тајне које цар иште не могу казати цару мудраци ни звјездари ни врачи ни гатари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Него има Бог на небу који открива тајне и јавља цару Навуходоносору што ће бити до пошљетка. Сан твој и што ти је видјела глава на постељи твојој ово је:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Теби, царе, дођоше мисли на постељи што ће бити послије, и онај који објављује тајне показа ти што ће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'А мени се ова тајна није објавила мудрошћу која би у мене била мимо све живе, него зато да се јави цару што сан значи и да дознаш мисли срца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Ти, царе, видје а то лик велик; велик бијаше лик и свјетлост му силна, и стајаше према теби, и страшан бијаше на очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Глава томе лику бијаше од чистога злата, прси и мишице од сребра, трбух и бедра од мједи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Голијени му од гвожђа, а стопала које од гвожђа које од земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Ти гледаше докле се одвали камен без руку, и удари лик у стопала мједена и земљана, и сатр их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Тада се сатр и гвожђе и земља и мјед и сребро и злато, и поста као пљева на гумну у љето, те однесе вјетар, и не нађе му се мјесто; а камен, који удари лик, поста гора велика и испуни сву земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'То је сан; а сада ћемо казати цару што значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Ти си, царе, цар над царевима, јер ти Бог небески даде царство, силу и крјепост и славу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'И гдје год живе синови људски, звјери пољске и птице небеске, дао ти је у руке, и поставио те господарем над свијем тијем. Ти си она глава златна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'А након тебе настаће друго царство, мање од твојега; а потом треће царство, мједено, које ће владати по свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'А четврто ће царство бити тврдо као гвожђе, јер гвожђе сатире и троши све, и као гвожђе што све ломи, тако ће сатрти и поломити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'А што си видио стопала и прсте које од кала лончарскога које од гвожђа, биће царство раздјељено, али ће бити у њему тврђе од гвожђа, јер си видио гвожђе помијешано с калом лончарским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'И што прсти у ногу бијаху које од гвожђа које од кала, царство ће бити нешто јако а нешто трошно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'А што си видио гвожђе помијешано са калом лончарским, то ће се они помијешати сјеменом човјечијим, али неће прионути један за другога као што се гвожђе не може смијешати с калом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'А у вријеме тијех царева Бог ће небески подигнути царство које се довијека неће расути, и то се царство неће оставити другом народу; оно ће сатрти и укинути сва та царства, а само ће стајати довијека,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Како си видио гдје се од горе одвали камен без руку и сатр гвожђе, мјед, као, сребро и злато. Бог велики јави цару што ће бити послије; сан је истинит, и тумачење му вјерно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Тада цар Навуходоносор паде на лице своје, и поклони се Данилу, и заповједи да му принесу принос и кад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Цар проговори Данилу и рече: доиста, ваш је Бог Бог над боговима и господар над царевима, и који објављује тајне, кад си могао открити ову тајну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Тада цар узвиси Данила, и даде му многе велике дарове и учини га господарем свој земљи Вавилонској и поглаварем над свијем мудрацима Вавилонским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'И Данило измоли у цара, те постави над пословима земље Вавилонске Седраха, Мисаха и Авденага, а Данило оста на двору цареву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Цар Навуходоносор начини златан лик, којему висина бјеше шездесет лаката, а ширина шест лаката; и намјести га у пољу Дури у земљи Вавилонској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'И посла цар Навуходоносор да саберу кнезове, управитеље и војводе, старјешине, ризничаре, судије, настојнике и све властеље земаљске, да дођу да се освети лик што га постави цар Навуходоносор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Тада се скупише кнезови, управитељи и војводе, старјешине, ризничари, судије, настојници, и сви властељи земаљски, да се освети лик што га постави цар Навуходоносор; и стадоше пред ликом што га постави Навуходоносор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'А гласник повика иза гласа: народи, племена и језици, вама се говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Кад чујете рог, свирале, китаре, гусле, псалтире, пјевање и свакојаке свирке, попадајте и поклоните се златному лику, који постави цар Навуходоносор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'А ко не би пао и поклонио се, онај час биће бачен у пећ огњену ужарену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Зато сви народи како чуше рог, свирале, китаре, гусле, псалтире и свакојаке свирке, попадаше сви народи, племена и језици, и поклонише се златноме лику који постави цар Навуходоносор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'А неки Халдеји тај час дођоше и тужише Јевреје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'И проговорише и рекоше цару Навуходоносору: царе, да си жив довијека!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Ти си, царе, заповиједио, сваки ко чује рог, свирале, китаре, гусле, псалтире, и пјевање и свакојаке свирке, да падне и поклони се златноме лику;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'А ко не би пао и поклонио се, да се баци у пећ огњену ужарену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'А имају људи Јевреји, које си поставио над пословима земље Вавилонске, Седрах, Мисах и Авденаго; ти људи, царе, не хају за те, не поштују твојих богова, и не клањају се златном лику, који си поставио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Тада Навуходоносор у гњеву и љутини заповједи да доведу Седраха, Мисаха и Авденага. И доведоше те људе пред цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Навуходоносор проговори и рече им: је ли истина, Седраше, Мисаше и Авденаго, да ви не служите мојим боговима и да се не клањате златноме лику који поставих?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Јесте ли дакле готови, кад чујете рог, свирале, китаре, гусле, псалтире и пјевање и свакојаке свирке, да паднете и поклоните се лику који начиних? ако ли се не поклоните, онај час бићете бачени у пећ огњену ужарену; а који је бог што ће вас избавити из мојих руку?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Одговорише Седрах, Мисах и Авденаго, и рекоше цару Навуходоносору: није нам тријебе да ти одговоримо на то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Ево, Бог наш, којему ми служимо, може нас избавити из пећи огњене ужарене; и избавиће нас из твојих руку, царе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'А и да не би, знај, царе, да боговима твојим нећемо служити нити ћемо се поклонити златном лику, који си поставио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Тада се Навуходоносор напуни гњева, и лице му се промијени на Седраха, Мисаха и Авденага, и одговарајући заповједи да се ужари пећ седам пута већма него што бјеше обичај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'И заповједи најјачим људима што бијаху у војсци његовој да свежу Седраха, Мисаха и Авденага, и да их баце у пећ огњену ужарену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Тада свезаше оне људе у плаштима њиховијем и у обући и под капама и у свему одијелу њихову, и бацише их у пећ огњену ужарену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Како заповијест царева бјеше хитна и пећ врло ужарена, пламен огњени уби оне људе који бацаху Седраха, Мисаха и Авденага.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'А та три човјека, Седрах, Мисах и Авденаго, падоше усред пећи огњене ужарене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Тада се препаде цар Навуходоносор, и брже устав проговори и рече својим дворанима: не бацисмо ли три човјека свезана у огањ? Одговорише и рекоше цару: да, царе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Одговори и рече: ено, видим четири човјека одријешена гдје ходе посред огња и није им ништа, и четврти као да је син Божји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Тада приступи Навуходоносор на врата огњеној пећи ужареној, и проговори и рече: Седраше, Мисаше и Авденаго, слуге Бога вишњега, изидите и ходите. Тада Седрах, Мисах и Авденаго изидоше исред огња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'И сабраше се кнезови и управитељи и војводе и вијећници цареви, и видјеше те људе гдје им тијелу огањ ништа не може, нити им се коса на глави опали, нити им се плашти што промијенише, нити задах од огња приону за њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Проговори Навуходоносор и рече: да је благословен Бог Седрахов, Мисахов и Авденагов, који посла анђела својега и избави слуге своје, које се у њ поуздаше и не послушаше заповијести цареве и дадоше тјелеса своја да не би служили нити се поклонили другом богу осим својега Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Зато заповиједам да се сваки којега му драго народа и племена и језика, који би похулио на Бога Седрахова, Мисахова и Авденагова, да се исијече и кућа да му буде буниште, јер нема другог бога који може тако избавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Тада цар узвиси Седраха, Мисаха и Авденага у земљи Вавилонској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Цар Навуходоносор свијем народима, племенима и језицима што су по свој земљи, мир да вам се умножи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Свидје ми се да објавим знаке и чудеса што ми учини Бог вишњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Знаци његови како су велики! и чудеса његова како су силна! царство је његово царство вјечно, и власт његова од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Ја Навуходоносор бијах миран у кући својој и цватијах у двору свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Усних сан, који ме уплаши, и мисли на постељи мојој и утваре главе моје узнемирише ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'И заповједих да се доведу преда ме сви мудраци Вавилонски да ми кажу што значи сан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Тада дођоше врачари, звјездари, Халдеји и гатари, и приповједих им сан, али ми не могоше казати што значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Најпослије дође преда ме Данило, који се зове Валтасар по имену бога мојега, и у ком је дух светијех богова, и приповједих му сан:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Валтасаре, поглаваре врачарима, знам да је дух светијех богова у теби и никака тајна није ти тешка; кажи сан мој што сам снио и што значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'А утвара главе моје на постељи мојој бјеше: видјех, гле, дрво усред земље, и висина му велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Дрво бјеше велико и јако, и висина му досезаше до неба, и виђаше се до краја све земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Лишће му бјеше лијепо и род обилат, и на њему бјеше хране свему; звијерје пољско одмараше се у хладу његову, и на гранама његовијем становаху птице небеске, и од њега се храњаше свако тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Видјех у утварама главе своје на постељи својој, и гле, стражар и светац сиђе с неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Повика јако и рече овако: посијеците дрво, и окрешите му гране, покидајте му лишће и разметните му род; нека побјегну звијери испод њега и птице с грана његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Али пањ са жилама оставите му у земљи, у оковима гвозденијем и мједенијем у трави пољској, нека га кваси роса небеска и дио да му је са звијерјем од траве земаљске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Срце човјечје нека му се промијени, и срце животињско нека му се да, и седам времена нека прође преко њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'То су одредили стражари и изрекли свети да би познали живи да вишњи влада царством људским, и даје га коме хоће, и поставља над њим најнижега између људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Тај сан сних ја цар Навуходоносор; а ти, Валтасаре, кажи што значи, јер ни један мудрац у царству мом не може да ми каже што значи; а ти можеш, јер је у теби дух светијех богова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Тада Данило, који се зваше Валтасар, оста у чуду за један сахат, и мисли га узнемираваху. А цар проговори и рече: Валтасаре, сан и значење му да те не узнемирује. А Валтасар одговори и рече: господару мој, сан да буде твојим ненавидницима, и значење његово непријатељима твојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Дрво што си видио, велико и јако, којему висина досезаше до неба и које се виђаше по свој земљи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Којему лишће бјеше лијепо и род обилан, и на ком бјеше хране свему, под којим становаше звијерје пољско и на гранама му сјеђаху птице небеске,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'То си ти, царе, који си велик и силан, и величина је твоја висока и досеже до неба и власт твоја до крајева земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'А што цар видје стражара и свеца гдје слажаше с неба и говораше: посијеците дрво и потрите га, али му пањ са жилама оставите у земљи у оковима гвозденијем и мједенијем у трави пољској, да га кваси роса небеска, и са звијерјем пољским нека му је дио докле седам времена прође преко њега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Ово значи, царе, и ово је наредба вишњега која ће се извршити на мом господару цару:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Бићеш прогнан између људи, и са звијерима ћеш пољским живјети, и храниће те травом као говеда, и роса ће те небеска квасити, и седам ће времена проћи преко тебе докле познаш да вишњи влада царством људским и даје га коме хоће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'А што се рече да се остави пањ са жилама од дрвета, царство ће ти остати, кад познаш да небеса владају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Зато, царе, да ти је угодан мој свјет, опрости се гријеха својих правдом, и безакоња својих милошћу према невољнима, еда би ти се продуљио мир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Све ово дође на цара Навуходоносора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Послије дванаест мјесеца ходаше по царском двору у Вавилону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'И проговори цар и рече: није ли то Вавилон велики што га ја сазидах јаком силом својом да је столица царска и слава величанству мојему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Те ријечи још бјеху у устима цару, а глас дође с неба: теби се говори, царе Навуходоносоре: царство се узе од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'И бићеш прогнан између људи, и живјећеш са звијерјем пољским, храниће те травом као говеда, и седам ће времена проћи преко тебе докле познаш да вишњи влада царством људским и даје га коме хоће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'У тај час испуни се та ријеч на Навуходоносору; и би прогнан између људи и једе траву као говеда, и роса небеска кваси му тијело да му нарастоше длаке као пера у орла и нокти као у птица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Али послије тога времена ја Навуходоносор подигох очи своје к небу, и ум мој врати ми се, и благослових вишњега, и хвалих и славих онога који живи довијека, чија је власт власт вјечна и чије је царство од кољена до кољена;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'И сви становници земаљски ништа нијесу према њему, и ради што хоће с војском небеском и са становницима земаљским, и нема никога да би му руку уставио и рекао му: шта радиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'У то вријеме ум мој врати ми се, и на славу царстава мојега врати ми се величанство моје и свјетлост моја; и дворани моји и кнезови моји потражише ме, и утврдих се у царству свом, и дода ми се више величанства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Сада ја Навуходоносор хвалим, узвишујем и славим цара небескога, чија су сва дјела истина и чији су путови праведни и који може оборити оне који ходе поносито.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Цар Валтасар учини велику гозбу тисући кнезова својих, и пијаше вино пред тисућом њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Напив се вина Валтасар заповједи да се донесу судови златни и сребрни, које бјеше однио Навуходоносор отац му из цркве Јерусалимске, да из њих пију цар и кнезови му, и жене његове и иноче његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'И донесоше златне судове које бјеху однијели из цркве дома Господњега у Јерусалиму, и пијаху из њих цар и кнезови његови, жене његове и иноче његове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Пијаху вино, и хваљаху богове златне и сребрне и мједене и дрвене и камене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'У тај час изидоше прсти руке човјечије, и писаху према свијетњаку по окреченом зиду од царскога двора, и цар видје руку која писаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Тада се промијени лице цару, и мисли га његове узнемирише, и појас се око њега распаса и кољена му удараху једно о друго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Повика цар иза гласа, те доведоше звјездаре, Халдеје и гатаре; и проговори цар и рече мудрацима Вавилонским: ко прочита ово писмо и каже ми што значи, онај ће се обући у скерлет, и носиће златну верижицу о врату, и биће трећи господар у царству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Тада приступише сви мудраци цареви; али не могоше прочитати писма нити казати цару што значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Тада се цар Валтасар врло узнемири и лице му се сасвијем измијени; и кнезови се његови препадоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Дође царица ради тога што се догоди цару и кнезовима његовијем у кућу гдје бјеше гозба, и проговори царица и рече: царе, да си жив довијека! да те не узнемирују мисли твоје и да ти се лице не мијења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Има човјек у твом царству, у ком је дух светијех богова; и у вријеме оца твојега нађе се у њега видјело и разум и мудрост, какова је у богова, и цар Навуходоносор отац твој, царе, постави га главарем врачарима, звјездарима, Халдејима и гатарима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Јер велик дух и знање и разум за казивање санова и погађање загонетака и размршивање замршенијех ствари нађе се у Данила, којему цар надје име Валтасар; нека сада дозову Данила, и он ће казати што значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Тада Данило би доведен пред цара. Цар проговори Данилу и рече: јеси ли ти Данило између робља Јудина које доведе из Јудејске цар отац мој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Чух за тебе да је дух светијех богова у теби, и видјело и разум и мудрост велика да се нађе у тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'А сада су доведени преда ме мудраци, звјездари, да прочитају писмо и кажу ми што значи; али не могу да кажу што то значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'А за тебе ја чух да можеш протумачити, и замршене ствари размрсити. Ако дакле можеш прочитати ово писмо и казати ми што значи, обући ћеш се у скерлет, и златну верижицу носићеш о врату, и бићеш трећи господар у царству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Тада одговори Данило и рече пред царем: дарови твоји нека теби, и подај другому поклоне своје; а писмо ћу ја прочитати цару и казати што значи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Царе, Бог вишњи даде царство величину и славу и част Навуходоносору оцу твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'И од величине коју му даде сви народи, племена и језици дрктаху пред њим и бојаху га се; убијаше кога хоћаше, и остављаше у животу кога хоћаше, узвишиваше кога хоћаше, и пониживаше кога хоћаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Али када му се подиже срце и дух му се посили у охолости, би сметнут с царскога пријестола својега, и узеше му славу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'И би прогнан између људи и срце му поста као у звијери, и стан му бијаше с дивљим магарцима, хранише га травом као говеда, и роса небеска кваси му тијело, докле позна да Бог вишњи влада царством људским, и кога хоће поставља над њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'А ти, Валтасаре, сине његов, нијеси понизио срца својега премда си знао све ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Него си се подигао на Господа небескога, и судове дома његова донесоше преда те, и писте из њих вино ти и кнезови твоји, жене твоје и иноче твоје, и ти хвали богове сребрне и златне, мједене, гвоздене, дрвене и камене, који не виде нити чују нити разумију, а не слави Бога, у чијој је руци душа твоја и сви путови твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Зато од њега би послана рука и ово писмо би написано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'А ово је писмо написано: МЕНЕ, МЕНЕ, ТЕКЕЛ, УФАРСИН.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'А ово значе те ријечи: МЕНЕ, бројио је Бог твоје царство, и до краја избројио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'ТЕКЕЛ, измјерен си на мјерила, и нашао си се лак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'ФЕРЕС, раздијељено је царство твоје, и дано Мидијанима и Персијанима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Тада заповиједи Валтасар, те обукоше Данила у скерлет, и метнуше му златну верижицу око врата, и прогласише за њ да је трећи господар у царству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Исту ноћ би убијен Валтасар цар Халдејски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'А Дарије Мидијанин преузе царство и бјеше му око шездесет и двије године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Свидје се Дарију те постави над царством сто и педесет управитеља да буду над свијем царством;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'А над њима три старјешине, од којих један бјеше Данило, којима ће управитељи давати рачуне да не би цару било штете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'А тај Данило надвишиваше старјешине и управитеље, јер у њему бјеше велик дух и цар мишљаше да га постави над свијем царством својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Тада старјешине и управитељи гледаху како би нашли што да забаве Данилу ради царства; али не могаху наћи забаве ни погрешке, јер бјеше вјеран, и не налажаше се у њега погрјешке ни мане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Тада рекоше они људи: нећемо наћи на тога Данила ништа, ако не нађемо што на њ ради закона Бога његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Тада дођоше старјешине и управитељи к цару, и рекоше му овако: Дарије царе, да си жив довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Све старјешине у царству, поглавари и управитељи, вијећници и војводе договорише се да се постави царска наредба и оштра забрана да ко би се год замолио за што коме год богу или човјеку за тридесет дана осим теби, царе, да се баци у јаму лавовску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Зато, царе, постави ту забрану и напиши да се не може промијенити, по закону Мидском и Персијском, који је непромјенит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'И цар Дарије написа књигу и забрану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'А Данило кад дозна да је књига написана, отиде својој кући, гдје бијаху отворени прозори у његовој соби према Јерусалиму, и падаше на кољена своја три пута на дан и мољаше се и хвалу даваше Богу својему као што чињаше прије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Тада се сабраше они људи, и нађоше Данила гдје се моли и припада Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'И отидоше те рекоше цару за царску забрану: нијеси ли написао заповијест, да ко би се год замолио коме год богу или човјеку за тридесет дана, осим теби, царе, да се баци у јаму лавовску? Цар одговори и рече: тако је по закону Мидском и Персијском, који је непромјенит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Тада одговорише и рекоше цару: Данило, који је између робља Јудина, не хаје за те, царе, ни за забрану коју си написао, него се моли три пута на дан својом молитвом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Тада цар чувши то ожалости се врло, и науми да избави Данила, и труђаше се до захода сунчанога да га избави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Тада они људи сабраше се код цара и рекоше цару: знај, царе, да је закон у Мидијана и Персијана да се никаква забрана и наредба, коју постави цар, не мијења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Тада цар рече те доведоше Данила и бацише га у јаму лавовску; и цар проговори и рече Данилу: Бог твој, којему без престанка служиш, нека те избави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'И донесоше камен и метнуше јами на врата, и цар га запечати својим прстеном и прстеном својих кнезова да се ништа не промијени за Данила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Тада отиде цар у свој двор, и преноћи не једавши нити допустивши да му се донесе што чим би се развеселио и не може заспати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Потом цар уста ујутру рано и отиде брже к јами лавовској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'И кад дође к јами, викну Данила жалоснијем гласом; и проговори цар и рече Данилу: Данило, слуго Бога живога, Бог твој, којему служиш без престанка, може ли те избавити од лавова?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Тада Данило рече цару: царе, да си жив довијека!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Бог мој посла анђела својега и затвори уста лавовима, те ми не наудише; јер се нађох чист пред њим, а ни теби, царе, не учиних зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Тада се цар веома обрадова тому, и заповједи да изваде Данила из јаме. И извадише Данила из јаме, и не нађе се ране на њему, јер вјерова Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Потом заповједи цар, те доведоше људе који бијаху оптужили Данила, и бацише у јаму лавовску њих, дјецу њихову и жене њихове; и још не дођоше на дно јами, а лавови их зграбише и све им кости потрше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Тада цар Дарије писа свијем народима и племенима и језицима што живљаху у свој земљи: мир да вам се умножи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Од мене је заповијест да се у свој држави царства мојега свак боји и страши Бога Данилова, јер је он Бог живи, који остаје довијека, и царство се његово неће расути, и власт ће његова бити до краја;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Он избавља и спасава, и чини знаке и чудеса на небу и на земљи, он је избавио Данила од силе лавовске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'И тај Данило бијаше срећан за царовања Даријева и за царовања Кира Персијанца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Прве године Валтасара цара Вавилонскога усни Данило сан и видје утвару главе своје на постељи; тада написа сан и приповједи укратко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Данило проговори и рече: видјех у утвари својој ноћу, а то четири вјетра небеска ударише се на великом мору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'И четири велике звијери изидоше из мора, свака другачија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Прва бијаше као лав, и имаше крила орлова; гледах докле јој се крила поскубоше и подиже се са земље и стаде на ноге као човјек, и срце људско даде јој се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Потом, гле, друга звијер бијаше као медвјед, и стаде с једне стране, и имаше три ребра у устима међу зубима својим, и говораше јој се: устани, једи много меса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Потом видјех, и гле, друга, као рис, имаше на леђима четири крила као птица, и четири главе имаше звијер, и даде јој се власт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Потом видјех у утварама ноћнијем, и гле, четврта звијер, које се требаше бојати, страшна и врло јака, и имаше велике зубе гвоздене, јеђаше и сатираше, и гажаше ногама остатак, и разликоваше се од свијех звијери пређашњих, и имаше десет рогова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Гледах рогове, и гле, други мали рог израсте међу онијема, а три прва рога ишчупаше се пред њим; и гле, очи као очи човјечије бјеху на том рогу, и уста која говораху велике ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Гледах докле се поставише пријестоли, и старац сједе, на ком бјеше одијело бијело као снијег, и коса на глави као чиста вуна, пријесто му бијаше као пламен огњени, точкови му као огањ разгорио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Ријека огњена излажаше и тецијаше испред њега, тисућа тисућа служаше му, и десет тисућа по десет тисућа стајаху пред њим; суд сједе, и књиге се отворише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Тада гледах ради гласа великих ријечи које говораше онај рог; и гледах докле не би убијена звијер и тијело јој се рашчини и даде се да изгори огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'И осталијем звијерима узе се власт, јер дуљина животу бјеше им одређена до времена и до рока.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Видјех у утварама ноћнијем, и гле, као син човјечји иђаше са облацима небеским, и дође до старца и стаде пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'И даде му се власт и слава и царство да му служе сви народи и племена и језици; власт је његова власт вјечна, која неће проћи, и царство се његово неће расути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Мени Данилу пренеможе дух мој у тијелу мом, и утваре главе моје узнемирише ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Приступих к једноме од онијех који стајаху ондје, и замолих га за истину од свега тога. И проговори ми и каза ми шта то значи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Ове четири велике звијери јесу четири цара, који ће настати на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Али ће свеци вишњега преузети царство, и држаће царство навијек и довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Тада зажељех знати истину о четвртој звијери, која се разликоваше од свијех и бијаше врло страшна, и имаше зубе гвоздене и нокте мједене, и јеђаше и сатираше, а остатак ногама гажаше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'И о десет рогова што јој бјеху на глави, и о другом који израсте и три отпадоше пред њим, о рогу који имаше очи и уста која говораху велике ствари и бијаше по виђењу већи од других.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Гледах, и тај рог војеваше са свецима и надвлађиваше их,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Докле дође старац, и даде се суд свецима вишњега, и приспје вријеме да свеци преузму царство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Овако рече: четврта звијер биће четврто царство на земљи, које ће се разликовати од свијех царстава, и изјешће сву земљу и погазити и сатрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'И десет рогова јесу десет царева, који ће настати из тога царства, а послије њих настаће други, и он ће се разликовати од пређашњих, и покориће три цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'И говориће ријечи на Вишњега, и потираће свеце вишњега, и помишљаће да промијени времена и законе; и даће му се у руке за вријеме и за времена и за по времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Потом ће сјести суд, и узеће му се власт, те ће се истријебити и затрти сасвијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'А царство и власт и величанство царско под свијем небом даће се народу светаца Вишњега; његово ће царство бити вјечно царство, и све ће власти њему служити и слушати га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Овдје је крај овој ријечи. А мене Данила врло узнемирише мисли моје, и лице ми се све промијени; али ријеч сачувах у срцу свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Треће године царовања Валтасарова показа се мени Данилу утвара послије оне која ми се показала прије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'И видјех у утвари; а бјех у Сусану у граду који је у земљи Еламу, кад видјех, и видјех у утвари и бјех на води Улају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'И подигох очи своје и видјех, и гле, стајаше крај воде ован, који имаше два рога, а рогови бјеху високи, али један виши од другога, и виши нарасте послије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Видјех овна гдје боде на запад и на сјевер и на југ, и ни једна звијер не могаше му одољети, и не бијаше никога ко би избавио од њега, него чињаше шта хоћаше, и осили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'А кад ја мотрах, гле, иђаше јарац од запада поврх све земље а не дотицаше се земље; и тај јарац имаше рог знаменит међу очима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'И дође до овна који имаше два рога, којега видјех гдје стоји крај воде, и потрча на њ гњевно силом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'И видјех га гдје дође до овна, и разгњевив се на њ удари овна, те му сломи оба рога и не бјеше силе у овну да му одоли, него га обори на земљу и погази га, и не бјеше никога да избави овна од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'И јарац поста врло велик; а кад осили, сломи се велики рог, и мјесто њега нарастоше знаменита четири рога према четири вјетра небеска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'И из једнога њих изиде један рог мален и нарасте врло велик према југу и истоку према красној земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'И нарасте дори до војске небеске, и обори на земљу неке од војске и од звијезда, и погази их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'И нарасте дори до поглавара тој војсци, и узе му свагдашњу жртву, и свети стан његов обори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'И војска би дана у отпад од жртве свагдашње, и обори истину на земљу, и што чињаше напредоваше му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Тада чух једнога свеца гдје говораше, и један светац рече некоме који говораше: докле ће трајати та утвара за свагдашњу жртву и за отпад пустошни да се гази светиња и војска?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'И рече ми: до двије тисуће и три стотине дана и ноћи; онда ће се светиња очистити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'А кад видјех ја Данило ову утвару, и заисках да разумијем, гле, стаде преда ме као човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'И чух глас човјечји насред Улаја, који повика и рече: Гаврило, кажи овоме утвару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'И дође гдје ја стајах; и кад дође уплаших се, и падох на лице своје; а он ми рече: пази, сине човјечји, јер је ова утвара за пошљедње вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'А док ми он говораше, ја бијах изван себе лежећи ничице на земљи; а он ме се дотаче, и исправи ме, те стадох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'И рече: ево, ја ћу ти казати шта ће бити на крају гњева; јер ће у одређено вријеме бити крај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Ован што си га видио, који има два рога, то су цареви Мидски и Персијски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'А руњави је јарац цар Грчки; и велики рог што му бјеше међу очима, то је први цар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'А што се он сломи, и мјесто њега нарастоше четири, то су четири царства, која ће настати иза тога народа, али не с његовом силом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'А на пошљедак царовања њихова, кад безаконици наврше мјеру, настаће цар бестидан и лукав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Сила ће му бити јака, али не од његове јачине, и чудесно ће пустошити, и биће срећан и свршиваће, и губиће силне и народ свети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'И лукавством његовијем напредоваће пријевара у његовој руци, и подигнуће се у срцу свом, и у миру ће погубити многе, и устаће на кнеза над кнезовима, али ће се потрти без руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'А речена утвара о дану и ноћи истина је; зато ти запечати утвару, јер је за много времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Тада ја Данило занемогох, и боловах неко вријеме; послије устах и врших послове цареве; и чудих се утвари, али нико не дозна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Прве године Дарија сина Асвирова од племена Мидскога, који се зацари над царством Халдејским,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'Прве године његова царовања ја Данило разумјех из књига број година, које бјеше рекао Господ Јеремији пророку да ће се навршити развалинама Јерусалимским, седамдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'И окретох лице своје ка Господу Богу тражећи га молитвом и молбама с постом и с костријети и пепелом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'И помолих се Господу Богу својему и исповиједајући се рекох: о Господе, Боже велики и страшни, који држиш завјет и милост онима који те љубе и држе заповијести твоје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Згријешисмо и зло чинисмо и бисмо безбожни, и одметнусмо се и отступисмо од заповијести твојих и од закона твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'И не слушасмо слуга твојих пророка, који говораху у твоје име царевима нашим, кнезовима нашим и оцима нашим и свему народу земаљском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'У тебе је, Господе, правда а у нас срам на лицу, како је данас, у Јудејаца и у Јерусалимљана и у свијех Израиљаца, који су близу и који су далеко по свијем земљама куда си их разагнао за гријехе њихове, којима ти гријешише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Господе, у нас је срам на лицу, у царева наших, у кнезова наших и у отаца наших, јер ти згријешисмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'У Господа је Бога нашега милост и праштање, јер се одметнусмо од њега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'И не слушасмо гласа Господа Бога својега да ходимо по законима његовијем, које нам је дао преко слуга својих пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'И сав Израиљ преступи закон твој, и отступи да не слуша гласа твојега; зато се изли на нас проклетство и заклетва написана у закону Мојсија слуге Божијега, јер му згријешисмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'И он потврди ријечи своје које је говорио за нас и за судије наше, које су нам судиле, пустивши на нас зло велико, да тако не би под свијем небом како би у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Како је писано у закону Мојсијеву, све то зло дође на нас, и опет се не молисмо Господу Богу својему да бисмо се вратили од безакоња својега и пазили на истину твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'И Господ наста око зла и наведе га на нас; јер је праведан Господ Бог наш у свијем дјелима својим која чини, јер не слушасмо гласа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Али сада, Господе Боже наш, који си извео народ свој из земље Мисирске руком крјепком, и стекао си себи име, како је данас, згријешисмо, безбожни бисмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Господе, по свој правди твојој нека се одврати гњев твој и јарост твоја од града твојега Јерусалима, свете горе твоје; јер са гријеха наших и с безакоња отаца наших Јерусалим и твој народ поста руг у свијех који су око нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Сада дакле послушај, Боже наш, молитву слуге својега и молбе његове, и обасјај лицем својим опустјелу светињу своју, Господа ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Боже мој, пригни ухо своје, и чуј; отвори очи своје, и види пустош нашу и град, на који је призвано име твоје, јер не правде своје ради него ради милости твоје падамо пред тобом молећи се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Господе, услиши, Господе, опрости, Господе, пази и учини, не часи, себе ради, Боже мој, јер је твоје име призвано на овај град и на твој народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'А док ја још говорах и мољах се и исповиједах гријех свој и гријех народа својега Израиља, и падах молећи се пред Господом Богом својим за свету гору Бога својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Док још говорах молећи се, онај човјек Гаврило, којега видјех прије у утвари, долетје брзо и дотаче ме се о вечерњој жртви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'И научи ме и говори са мном и рече: Данило, сада изидох да те уразумим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'У почетку молитве твоје изиде ријеч, и ја дођох да ти кажем, јер си мио; зато слушај ријеч, и разумиј утвару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Седамдесет је недјеља одређено твоме народу и твоме граду светом да се сврши пријеступ и да нестане гријеха и да се очисти безакоње и да се доведе вјечна правда, и да се запечати утвара и пророштво, и да се помаже свети над светима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Зато знај и разумиј: откад изиде ријеч да се Јерусалим опет сазида до помазаника војводе биће седам недјеља, и шездесет и двије недјеље да се опет пограде улице и зидови, и то у тешко вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'А послије те шездесет и двије недјеље погубљен ће бити помазаник и ништа му неће остати; народ ће војводин доћи и разорити град и светињу; и крај ће му бити с потопом, и одређено ће пустошење бити до свршетка рата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'И утврдиће завјет с многима за недјељу дана, а у половину недјеље укинуће жртву и принос; и крилима мрским, која пустоше, до свршетка одређенога излиће се на пустош.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Треће године Кира цара Персијскога објави се ријеч Данилу, који се зваше Валтасар; и ријеч бјеше истинита и о великим стварима; и разабра ријеч и разумје утвару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'У то вријеме ја Данило бјех у жалости три недјеље дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Јела угодна не једох, ни месо ни вино не уђе у моја уста, нити се намазах уљем док се не навршише три недјеље дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'А двадесет четвртога дана првога мјесеца бијах на бријегу велике ријеке Хидекела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'И подигох очи своје и видјех, а то један човјек обучен у платно, и појас бјеше око њега од чистога злата из Уфаза;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'А тијело му бјеше као хрисолит, и лице му као муња а очи му као лучеви запаљени, а руке и ноге као мјед углађена, а глас од ријечи његовијех као глас многога људства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'И ја Данило сам видјех утвару, а људи што бијаху са мном не видјеше је, али их попаде страх велик, те побјегоше и сакрише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'И остах сам, и видјех ту велику утвару, и не оста снаге у мени, и љепота ми се нагрди, и не имах снаге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'И чух глас од ријечи његовијех, и кад чух глас од ријечи његовијех, изван себе падох ничице лицем на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'И гле, рука ме се дотаче и подиже ме на кољена моја и на дланове моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'И рече ми: Данило, мили човјече! слушај ријечи које ћу ти казати, и стани право, јер сам сада послан к теби. И кад ми рече ту ријеч, устах дркћући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'И рече ми: не бој се, Данило, јер првога дана кад си управио срце своје да разумјеваш и да мучиш себе пред Богом својим, услишене бише ријечи твоје, и ја дођох твојих ријечи ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Али кнез царства Персијскога стаја ми насупрот двадесет и један дан; али, гле, Михаило један од првијех кнезова дође ми у помоћ; тако ја остах ондје код царева Персијских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'И дођох да ти кажем шта ће бити твоме народу послије; јер ће још бити утвара за те дане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'И кад ми говораше тако, оборих очи своје на земљу и занијемјех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'И гле, као човјек дотаче се усана мојих, и отворих уста своја, и проговорих и рекох оному који стајаше према мени: господару мој, од ове утваре навалише моји болови на мене и нема снаге у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'А како може слуга мојега господара говорити с господарем мојим? Јер од овога часа у мени неста снаге и ни дихање не оста у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Тада онај што бијаше као човјек опет ме се дотаче и охрабри ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'И рече: не бој се, мили човјече; мир да ти је! охрабри се, охрабри се. И докле ми говораше, охрабрих се и рекох: нека говори господар мој, јер си ме охрабрио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'А он рече: знаш ли зашто сам дошао к теби? а сада ћу се вратити да војујем на кнеза Персијскога; потом ћу отићи, и гле, доћи ће кнез Грчки.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Али ћу ти казати што је написано у књизи истинитој. Нема никога да јуначки ради са мном у том осим Михаила кнеза вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'И ја прве године Дарија Мидијанина стадох да му поможем, и да га поткријепим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'А сада ћу ти казати истину. Ево, још ће три цара настати у Персији; и четврти ће бити богатији од свијех, и кад се укријепи богатством својим, све ће подигнути на Грчко царство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Потом ће настати силан цар, и владаће великом државом и радиће што хоће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'А како нестане, расуће се царство његово и раздијелиће се у четири вјетра небеска, не међу натражје његово нити с влашћу с којом је он владао, јер ће се царство његово укинути и допасти другима а не њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'И цар јужни осилиће, и један од кнезова његовијех, и биће силнији од њега, и владаће, и држава ће његова бити велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'И послије неколико година они ће се опријатељити, и кћи јужнога цара доћи ће к цару сјеверном да учини погодбу; али она неће сачувати силе мишици, нити ће се он одржати с мишицом својом, него ће бити предана и она и они који је доведу и син њезин и онај који јој буде помагао у то вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Потом ће од изданка из коријена њезина настати један на мјесто његово, који ће доћи с војском својом и ударити на градове цара сјевернога, и биће их и освојиће их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'И богове ће њихове и кнезове њихове са закладима њиховијем драгоцјенијем златнијем и сребрнијем однијети у ропство у Мисир, и остаће неколико година јачи од цара сјевернога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'И тако ће цар јужни доћи у своје царство, и вратиће се у своју земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Али ће синови његови заратити, и скупиће велику војску; и један ће доћи изненада, и поплавити и проћи; и вративши се ратоваће до града његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Тада ће се разљутити цар јужни, и изаћи ће и ратоваће с њим, с царем сјевернијем, и подигнуће велику војску, те ће му бити дата у руке војска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'И кад разбије војску, понијеће се срце његово, и побиће тисуће, али се неће укријепити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Јер ће цар сјеверни опет дигнути војску већу од прве; и послије неколико година доћи ће с великом војском и с великим благом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'И у то ће вријеме многи устати на цара јужнога; и зликовци од твојега народа подигнуће се да се потврди утвара, и попадаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'И доћи ће цар сјеверни, и начиниће опкопе, и узеће тврде градове, и мишице јужнога цара неће одољети ни изабрани народ његов, нити ће бити силе да се опре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'И онај дошав на њ чиниће што хоће, и неће бити никога да му се опре; и уставиће се у красној земљи, коју ће потрти својом руком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Потом ће окренути да дође са силом свега царства својега, али ће се погодити с њим, и даће му кћер за жену да би га упропастио, али се она неће држати, нити ће бити с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Потом ће се окренути на острва, и освојиће многа; али ће један војвода прекинути срамоту коју чини, и обориће на њ срамоту његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Потом ће се окренути ка градовима своје земље, и спотакнуће се и пашће, и неће се више наћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'И на његово ће мјесто настати који ће послати настојника у слави царској; али ће за мало дана погинути без гњева и без боја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'А на његово ће мјесто доћи незнатан човјек, коме није намијењена част царска; али ће доћи мирно и освојиће царство ласкањем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'И мишице које плаве он ће поплавити и поломити, па и кнеза с којим је учинио вјеру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Јер удруживши се с њим учиниће пријевару, и дошавши надвладаће с мало народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'И доћи ће мирно у родна мјеста у земљи, и учиниће што ни оцеви његови ни оцеви отаца његовијех не учинише, раздијелиће им плијен и грабеж и благо, и смишљаће мисли на градове, за неко вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Потом ће подигнути силу своју и срце своје на цара јужнога с великом војском; и цар ће јужни доћи у бој с великом и врло силном војском; али неће одољети, јер ће му се чинити невјера.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'И који једу хљеб његов сатрће га; војска ће његова поплавити, и многи ће пасти побијени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'И срце ће обојице царева радити о злу, и за једнијем ће столом лагати; али се неће извршити; јер ће крај још бити у одређено вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'И тако ће се вратити у своју земљу с великим благом; и срце ће се његово обратити на свети завјет, и кад изврши, вратиће се у своју земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'У одређено ће вријеме опет доћи на југ; али други пут неће бити као први пут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Јер ће доћи на њ лађе Китејске, и он ће се ојадити, те ће се вратити; и разљутиће се на свети завјет, и извршиће; и вративши се сложиће се с онима који остављају свети завјет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'И војска ће стајати уза њ, и оскврниће светињу у граду, и укинути жртву свагдашњу и поставиће гнусобу пустошну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'И који су безбожни према завјету, он ће их ласкањем отпадити; али народ који познаје Бога својега охрабриће се и извршиће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'И разумни у народу научиће многе, и падаће од мача и огња, ропства и грабежа много времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Али падајући добиће малу помоћ; и многи ће пристати с њима дволичећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'И од разумнијех ће пасти неки да би се окушали и очистили и убијелили до рока, јер ће још бити рок.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'И тај ће цар чинити што хоће, и подигнуће се и узвисиће се изнад свакога бога, и чудно ће говорити на Бога над боговима, и биће срећан докле се не сврши гњев, јер ће се извршити што је одређено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Неће марити ни за богове својих отаца ни за љубав женску, нити ће за кога бога марити, него ће се узвишивати нада све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'И на мјесто Бога најсилнијега славиће бога којега оци његови не знаше, славиће златом и сребром и драгим камењем и закладима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'И учиниће да градови Бога најсилнијега буду бога туђега; које позна умножиће им славу и учиниће их господарима над многима и раздјелиће земљу мјесто плате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'А у пошљедње вријеме јужни ће се цар побити с њим; и цар ће сјеверни ударити на њ као вихор с колима и коњицима и с многим лађама, и ушавши у земље поплавиће и проћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'И доћи ће у красну земљу, и многи ће пропасти, а ове ће се избавити од његовијех руку: Едомска, Моавска и главни дио синова Амоновијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'И посегнуће руком својом на земље, и земља Мисирска неће умакнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'И освојиће благо у злату и у сребру и све закладе Мисирске; и Ливијани и Етиопљани ићи ће за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Али ће га гласови с истока и са сјевера смести, те ће изаћи с великим гњевом да погуби и затре многе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'И разапеће шаторе двора својега међу морима на красној светој гори; и кад дође к своме крају, нико му неће помоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'А у то ће се вријеме подигнути Михаило велики кнез, који брани твој народ; и биће жалосно вријеме, какога није било откако је народа до тада; и у то ће се вријеме избавити твој народ, сваки који се нађе записан у књизи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'И много онијех који спавају у праху земаљском пробудиће се, једни на живот вјечни а други на срамоту и пријекор вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'И разумни ће се сјати као свјетлост небеска, и који многе приведоше к правди, као звијезде вазда и довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'А ти Данило затвори ове ријечи и запечати ову књигу до пошљедњега времена; многи ће претраживати, и знање ће се умножити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Тада погледах ја Данило, и гле, стајаху друга двојица, један с ове стране на бријегу ријеке, а други с оне стране на бријегу ријеке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'И један рече човјеку обученоме у платно, који стајаше над водом у ријеци: кад ће бити крај тијем чудесима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'И чух човјека обученога у платно, који стајаше над водом у ријеци, и подиже десницу своју и љевицу своју к небу, и закле се онијем који живи увијек да ће се све ово испунити по времену, по временима и по по времена, и кад се сврши расап силе светога народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'И ја чух али не разумјех; и рекох: господару мој, какав ће бити крај томе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'А он рече: иди Данило, јер су затворене и запечаћене ове ријечи до пошљедњега времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Многи ће се очистити, убијелити и окушати; а безбожници ће радити безбожно, нити ће који безбожник разумјети, али ће разумни разумјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'А од времена кад се укине жртва ваздашња и постави гнусоба пустошна, биће тисућа и двјеста и деведесет дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Благо ономе који претрпи и дочека тисућу и три стотине и тридесет и пет дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'А ти иди ка крају; и почиваћеш и остаћеш на дијелу свом до свршетка својих дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Ријеч Господња која дође Осији сину Веиријеву за времена Озије, Јоатама, Ахаза и Језекије царева Јудинијех и за времена Јеровоама сина Јоасова цара Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Кад Господ поче говорити Осији, рече Господ Осији: иди, ожени се курвом, и роди копилад, јер се земља прокурва отступивши од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'И отиде, и узе Гомеру кћер Дивлаимску, која затрудње и роди му сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Тада му рече Господ: надјени му име Језраел; јер још мало, па ћу походити крв Језраелску на дому Јујеву и укинућу царство дома Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'И у то ћу вријеме сломити лук Израиљев у долини Језраелској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'И она опет затрудње и роди кћер; и Господ му рече: надјени јој име Лорухама; јер се више нећу смиловати на дом Израиљев, него ћу их укинути сасвијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'А на дом Јудин смиловаћу се, и избавићу их Господом Богом њиховијем, а нећу их избавити луком ни мачем ни ратом ни коњма ни коњицима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Потом одбивши од сисе Лорухаму опет затрудње и роди сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'И рече Господ: надјени му име Лоамија; јер ви нијесте мој народ, нити ћу ја бити ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Али ће ипак број синова Израиљевијех бити као пијесак морски, који се не може измјерити ни избројити; и мјесто да им се рече: нијесте мој народ, рећи ће им се: синови Бога живога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'И сабраће се синови Јудини и синови Израиљеви уједно, и поставиће себи једнога поглавара и отићи ће из земље, јер ће бити велик дан Језраелски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Реците браћи својој: народе мој; и сестрама својим: помилована.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Прите се с матером својом, прите се, јер ми није жена, нити сам јој ја муж; нека одбаци курварства своја од лица својега, и прељубе своје од дојака својих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Да је не бих свукао голу и учинио је кака је била онај дан кад се родила, и да је не бих поставио да буде као пустиња и обратио је да буде као земља засушена, и уморио је жеђу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'И нећу се смиловати на дјецу њезину, јер су копилад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Јер се мати њихова курва, срамоти се родитељка њихова; јер говори: ићи ћу за милосницима својим који ми дају хљеб мој и воду моју, вуну моју и лан мој, уље моје и пиће моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Зато ево ја ћу јој заградити пут трњем и зазидаћу зидом да не нађе стаза својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'И трчаће за својим милосницима, али их неће стигнути; и тражиће их, али их неће наћи; па ће рећи: идем да се вратим к првому мужу својему, јер ми бјеше боље онда него сада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Јер она не зна да сам јој ја давао жито и вино и уље, и умножавао јој сребро и злато, од којега начинише Вала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Зато ћу узети натраг жито своје, кад буде вријеме, и вино своје, кад буде вријеме, и узећу вуну своју и лан свој, којим би покривала голотињу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'И открићу ругобу њезину пред милосницима њезинијем, и нико је неће избавити из моје руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'И укинућу сваку радост њезину, светковине њезине, младине њезине и суботе њезине и све празнике њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'И потрћу чокоте њезине и смокве, за које говори: плата су ми, што ми дадоше милосници моји; и обратићу их у шуму да их једе звијерје пољско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'И походићу на њој дане Валимске, у које им је кадила и китила се обоцима и гривнама, и ишла за својим милосницима, и мене заборавила, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Али ево, ја ћу је примамити и одвешћу је у пустињу, и говорићу с њом лијепо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'И даћу јој винограде њезине од тога мјеста, и долину Ахор за врата надању, и ондје ће пјевати као за младости своје и као кад је ишла из Мисира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'И тада ћеш ме, говори Господ, звати: мужу мој; а нећеш ме више звати: Вале мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Јер ћу уклонити из уста њезинијех имена Вала; и неће им се више помињати имена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'И тада ћу им учинити завјет са звијерјем пољским и са птицама небеским и с бубинама земаљским; и поломићу лук и мач и рат да их нестане у земљи, и учинићу да леже без страха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'И заручићу те себи довијека, заручићу те себи правдом и судом и милошћу и милосрђем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'И заручићу те себи вјером, и познаћеш Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'И тада ћу се одазвати, говори Господ, одазваћу се небесима, а она ће се одазвати земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'А земља ће се одазвати житу и вину и уљу, а то ће се одазвати Језраелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'И посијаћу је себи на земљи, и смиловаћу се на Лорухаму, и рећи ћу Лоамији: ти си мој народ, и он ће рећи: Боже мој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Потом рече ми Господ: иди опет, љуби жену коју љуби љубавник а она чини прељубу, као што Господ љуби синове Израиљеве а они гледају за туђим боговима и љубе жбанове винске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'И купих је за петнаест сикала сребра и гомор и по јечма.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'И рекох јој: сједи код мене дуго времена, и не курвај се, и не буди другога; тако ћу и ја бити твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Јер ће дуго времена синови Израиљеви сједјети без цара и без кнеза и без жртве и без ступа и без оплећка и ликова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Послије ће се обратити и тражиће Господа Бога својега и Давида цара својега, и у страху ће приступити ка Господу и благости његовој у пошљедња времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Чујте ријеч Господњу, синови Израиљеви, јер Господ има парбу са становницима земаљским; јер нема истине ни милости ни знања за Бога у земљи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Заклињу се криво и лажу и убијају и краду и чине прељубу, застранише, и једна крв стиже другу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Зато ће тужити земља, и што год живи на њој пренемоћи ће, и звијери пољске и птице небеске; и рибе ће морске помријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Али нико да се не препире ни да кога кори, јер је народ твој као они који се препиру са свештеником.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Зато ћеш пасти дању, и с тобом ће пророк пасти ноћу, и погубићу матер твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Изгибе мој народ, јер је без знања; кад си ти одбацио знање, и ја ћу тебе одбацити да ми не вршиш службе свештеничке; кад си заборавио Бога својега, и ја ћу заборавити синове твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Што се више множише, то ми више гријешише; славу њихову претворићу у срамоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Од гријеха народа мојега хране се, и лакоме се на безакоње њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Зато ће бити свештенику као народу; походићу га за путове његове и платићу му за дјела његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'И они ће јести, а неће се наситити; курваће се, а неће се множити; јер престаше служити Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Курварство и вино и маст одузима срце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Народ мој пита дрво своје, и палица му његова одговара; јер дух курварски заводи их да се курвају отступивши од Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Наврх гора приносе жртве, и на хумовима каде под храстовима, тополама и бријестовима, јер им је сјен добар; зато се курвају кћери ваше и снахе ваше чине прељубу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Нећу карати кћери ваших кад се курвају, ни снаха ваших кад чине прељубу; јер се они одвајају с курвама и приносе жртве с неваљалијем женама; и народ неразумни пропашће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Ако се ти курваш, Израиљу, нека не гријеши Јуда; и не идите у Галгал нити идите у Ветавен, и не куните се: тако да је жив Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Јер је Израиљ упоран као упорна јуница; сада ће их пасти Господ као јагње на пространу мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Јефрем се удружио с лажнијем боговима; остави га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Пиће се њихово преврну, једнако се курвају; мило им је: дајте. Браничи су његови срамота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Вјетар ће их стегнути крилима својим, и они ће се посрамити од жртава својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Чујте, свештеници, и пази, доме Израиљев, и слушај, доме царев, јер је вама суд, јер сте замка у Миспи и мрежа разапета на Тавору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Из потаје клаше оне који залазе; али ћу их ја покарати све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Ја познајем Јефрема и Израиљ није сакривен од мене; јер се сада курваш, Јефреме, Израиљ се оскврни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Не управљају дјела својих да се врате к Богу својему; јер је дух курварски у њима и не знају Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'И поноситост Израиљева свједочи му у очи; зато ће Израиљ и Јефрем пасти за безакоње своје, пашће и Јуда с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Ићи ће с овцама својим и с говедима својим да траже Господа, али га неће наћи; уклонио се је од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Изневјерише Господа, јер изродише туђе синове; зато ће их прождријети мјесец дана с достојањем њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Трубите у рог у Гаваји, у трубу у Рами; вичите у Ветавену: за тобом, Венијамине!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Јефрем ће опустјети у дан кара; објавих међу племенима Израиљевијем што ће зацијело бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Кнезови су Јудини као они који премјештају међу; излићу на њих као воду јарост своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Јефрему се чини насиље, сатрвен је судом, јер од своје воље отиде за заповијешћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Зато ћу ја бити Јефрему као мољац и као црв дому Јудину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'И Јефрем видје болест своју и Јуда своју рану, и отиде Јефрем к Асирцу, и Јуда посла к цару који би га бранио; али вас он не може исцијелити нити ће вас опростити ране ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Јер ћу ја бити као лав Јефрему, као лавић дому Јудину; ја, ја ћу зграбити, и отићи ћу, однијећу и нико неће избавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Отићи ћу и вратићу се на своје мјесто докле не признаду своју кривицу и потраже лице моје; кад буду у невољи тражиће ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Ходите да се вратимо ка Господу; јер он раздрије, и исцијелиће нас, рани, и завиће нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Повратиће нам живот до два дана, трећи дан подигнуће нас, и живјећемо пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Тада ћемо познати Господа и све ћемо га више познавати; јер му је излазак уређен као зора и доћи ће нам као дажд, као позни дажд који натапа земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Што да ти учиним, Јефреме? што да ти учиним, Јуда? јер је доброта ваша као облак јутарњи и као роса која у зору падне, па је нестане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Зато их сјекох преко пророка и убијах ријечима уста својих, и свјетлост судова твојих изиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Јер је мени милост мила а не жртва, и познавање Бога већма него жртва паљеница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Али они преступише завјет као Адам; ту ме изневјерише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Галад је град онијех који чине безакоње, по њему су крвави трагови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'А дружина је свештеничка као чета која дочекује људе, убијају на путу у Сихем, чине грдило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'У дому Израиљеву видим страхоту; ондје је курвање Јефремово, Израиљ се оскврни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'И теби је, Јуда, приправљена жетва, кад вратим робље народа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Кад лијечим Израиља, тада се показује безакоње Јефремово и злоћа Самаријска; јер чине лаж, и лупеж улази, и напољу удара чета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'И не говоре у срцу свом да ја памтим свако безакоње њихово; сада стоје око њих дјела њихова, преда мном су.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Неваљалством својим веселе цара и лажима својим кнезове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Сви чине прељубу; као пећ су коју ужари хљебар, који престане стражити кад замијеси тијесто па докле ускисне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'На дан цара нашега разбољеше се кнезови од мијеха вина, и он пружи руку своју потсмјевачима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Јер на засједе своје управљају срце своје, које је као пећ; хљебар њихов спава цијелу ноћ, ујутру гори као пламен огњени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Сви су као пећ угријани и прождиру своје судије; сви цареви њихови падају, ниједан између њих не виче к мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Јефрем се помијешао с народима; Јефрем је погача непреврнута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Иностранци једу му силу, а он не зна; сиједе косе попадају га, а он не зна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'И поноситост Израиљева свједочи му у очи, али се не враћају ка Господу Богу својему нити га траже уза све то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'И Јефрем је као голуб, луд, безуман; зову Мисир, иду у Асирску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Кад отиду, разапећу на њих мрежу своју, као птице небеске свући ћу их, караћу их како је казивано у збору њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Тешко њима, јер зађоше од мене; погибао ће им бити, јер ме изневјерише; ја их искупих, а они говорише на ме лаж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Нити ме призиваше из срца својега, него ридаше на одрима својим; жита и вина ради скупљајући се отступају од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Кад их карах, укријепих им мишице; али они мислише зло на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Враћају се, али не к вишњему, посташе као лук лажљив; кнезови ће њихови попадати од мача с обијести језика својега; то ће им бити потсмијех у земљи Мисирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Трубу на уста, и реци: као орао иде на дом Господњи; јер преступише завјет мој и отпадише се од закона мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Израиљ ће викати к мени: Боже мој; познајемо те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Израиљ је оставио добро; непријатељ ће га гонити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Постављају цареве, али не од мене; подижу кнезове, за које ја не знам; од сребра својега и од злата својега граде себи ликове, да се истријебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Оставило те је теле твоје, Самаријо; јарост се моја распалила на њих; докле се неће моћи очистити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Јер је и оно од Израиља; начинио га је умјетник, и није Бог; теле ће Самаријско отићи у комаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Јер сију вјетар, па ће жети олују; стабљике неће имати, клица неће дати брашна; да би и дала, прождријеће га туђинци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Прождријеће се Израиљ, биће међу народима као суд на ком нема милине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Јер отидоше к Асирцу, дивљему магарцу, који је сам за се; Јефрем наима љубавнике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'А што наимаше међу народима, ја ћу их сабрати; а већ и окусише мало ради бремена цара над кнезовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Што умножи Јефрем олтаре да гријеши, биће му олтари на гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Написах му велике ствари у закону свом; али му се чине као нешто туђе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'За жртве, које ми приносе, приносе месо, и једу га; Господ их не прима; сада ће се опоменути безакоња њихова и походиће гријехе њихове; они ће се вратити у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Израиљ заборави творца својега, и сагради дворове, и Јуда умножи тврде градове; али ћу пустити огањ у градове овому, и спалиће дворове оному.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Не радуј се, Израиљу, веселећи се као народи, што се курваш отступивши од Бога својега, милујеш плату курварску по свијем гумнима житнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Гумно и каца неће их хранити, и маст ће их преварити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Они неће наставати у земљи Господњој; него ће се вратити Јефрем у Мисир, и они ће јести нечистоту у Асирској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Неће приносити Господу вина, нити ће му бити угодне жртве њихове, него ће им бити као хљеб онијех који туже, ко га год једе оскврниће се, јер им је хљеб за жртве њихове, неће ући у дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Шта ћете чинити на дан светковине и на дан празника Господњега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Јер гле, отићи ће пустошења ради; Мисир ће их прибрати, Мемфис ће их погрепсти; закладе њихове од сребра наслиједиће коприва, трње ће им бити у шаторима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Дођоше дани похођењу, дођоше дани плаћању; познаће Израиљ; пророци су луди, безумни су у којима је дух, за мноштво безакоња твојега и велику мржњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Стражар је Јефремов с Богом мојим, пророк је замка птичарска по свијем путовима његовијем, мржња је у дому Бога његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Дубоко су се покварили као у вријеме Гавајско; опоменуће се безакоња њихова, и походиће гријехе њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Нађох Израиља као грожђе у пустињи; видјех оце ваше као прве смокве на дрвету у почетку његову; они отидоше к Велфегору, и одвојише се за срамотом, и посташе гадни како им бјеше мило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Јефремова ће слава одлетјети као птица од рођења и од утробе и од зачетка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Ако ли и отхрани синове своје, ја ћу их учинити да буду без дјеце, да не остане ниједан; и тешко њима кад отступим од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Јефрем, кад га гледах, бјеше као Тир, посађен на љупку мјесту; али ће Јефрем извести крвнику синове своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Подај им, Господе; шта ћеш им дати? подај им утробу пометљиву и дојке усахле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Сва је злоћа њихова у Галгалу; зато ондје мрзим на њих; за злоћу дјела њиховијех изагнаћу их из дома својега; нећу их више љубити: сви су кнезови њихови одметници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Ударен би Јефрем; коријен им посахну, неће родити рода; ако и роде, убићу мили пород утробе њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Одбациће их Бог мој, јер га не слушају, и скитаће се по народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Израиљ је празна лоза винова, оставља род за се; што више рода има, то више умножава олтаре; што му је боља земља, то више кити ликове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Срце им је раздијељено, зато су криви; он ће оборити олтаре њихове, поломиће ликове њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Јер сада говоре: немамо цара; не бојимо се Господа; и шта би нам учинио цар?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Говоре ријечи кунући се лажно кад уговарају вјеру, и суд као отров расте у браздама на њиви мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'За јунице Ветавенске уплашиће се становници Самаријски; јер ће за њима жалити народ њихов, и свештеници њихови, који им се радоваху, јер ће слава њихова отићи од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'И он ће сам бити одведен у Асирску на дар цару браничу; Јефрема ће попасти стид, и Израиљ ће се осрамотити намјером својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Цара ће Самаријскога нестати као пјене поврх воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'И обориће се висине Авенске, гријех Израиљев; трње ће и чкаљ расти по олтарима њиховијем, и говориће горама: покријте нас, и хумовима: падните на нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Од времена Гавајскога гријешио си, Израиљу; ондје осташе, не стиже их у Гаваји рат на безаконике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'По својој ћу их вољи покарати, и народи ће се скупити на њих да их заробе за двојако безакоње њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Јефрем је јуница научена, која радо врше; али ћу јој доћи на лијепи врат; упрегнућу Јефрема, Јуда ће орати, Јаков ће повлачити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Сијте правду, жећете милост; орите крчевину, јер је вријеме да тражите Господа, да би дошао и подаждио вам правдом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Орасте безбожност, жесте безакоње, једосте плод од лажи; јер си се поуздао у свој пут, у мноштво својих јунака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Зато ће се подигнути врева међу твојим народом, и сви ће се градови твоји раскопати као што Салман раскопа Вет-Арвел кад бијаше рат, мајка би размрскана са синовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Тако ће вам учинити Ветиљ за велику злоћу вашу; зором ће погинути цар Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Кад Израиљ бјеше дијете, љубљах га, и из Мисира дозвах сина својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Колико их зваше, толико они одлазише од њих; приносише жртве Валима, кадише ликовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Ја учих Јефрема ходити држећи га за руке, али не познаше да сам их ја лијечио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Вукох их узицама човјечјим, ужима љубавнијем; и бијах им као они који им скидају јарам с чељусти, и давах им храну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Неће се вратити у земљу Мисирску, него ће му Асирац бити цар, јер се не хтјеше обратити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'И мач ће стајати у градовима његовијем, и потрће пријеворнице његове и прождријети за намјере њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Народ је мој прионуо за отпад од мене; зову га к вишњему, али се ниједан не подиже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Како да те дам, Јефреме? да те предам, Израиљу? како да учиним од тебе као од Адаме? да те обратим да будеш као Севојим? Устрептало је срце моје у мени, усколебала се утроба моја од жалости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Нећу извршити љутога гњева својега, нећу опет затрти Јефрема; јер сам ја Бог а не човјек, светац усред тебе; нећу доћи на град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Ићи ће они за Господом; он ће рикати као лав; кад рикне, са страхом ће дотрчати синови с мора;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Са страхом ће дотрчати из Мисира као птица, и као голуб из земље Асирске; и населићу их у кућама њиховијем, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Опколио ме је Јефрем лажју и дом Израиљев пријеваром; али Јуда још влада с Богом и вјеран је са светима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Јефрем се храни вјетром, и иде за устоком; сваки дан множи лаж и погибао; и хватају вјеру с Асирцем и носе уље у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'И с Јудом има Господ парбу и походиће Јакова према путовима његовијем, платиће му по дјелима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'У утроби ухвати за пету брата својега, и у сили својој бори се с Богом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Бори се с анђелом, и надјача; плака, и моли му се; нађе га у Ветиљу, и ондје говори с нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Али је Господ Бог над војскама, Господ му је спомен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Ти дакле обрати се к Богу својему, чувај милост и правду, и уздај се вазда у Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Трговац је Јефрем, у руци су му мјерила лажна, мило му је да чини криво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'И говори Јефрем: баш се обогатих, стекох благо, ни у ком труду мом неће ми наћи неправде која би била гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'А ја сам Господ Бог твој од земље Мисирске, још ћу ти дати да сједиш у шаторима као о празницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'И говорићу преко пророка, и умножићу утваре, и даваћу причу преко пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Доиста је Галад безакоње, посташе сама таштина; у Галгалу приносе јунце на жртву, и олтари су им као гомиле камења по браздама на њиви мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'И Јаков побјеже у земљу Сирску, и Израиљ служи за жену, и за жену чува овце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'И пророком изведе Господ Израиља из Мисира, и пророком чува га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 15, 'Јефрем га љуто разгњеви; зато ће оставити на њему крв његову, и вратиће му срамоту његову Господ његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Кад Јефрем говораше, бјеше страх; бјеше се узвисио у Израиљу; али се огријеши о Вала, те умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'И сада једнако гријеше и граде себи лијући од сребра својега по разуму својему ликове, који су сви дјело умјетничко, а они говоре за њих: људи који приносе жртве нека цјелују теоце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Зато ће бити као облак јутарњи и као роса која у зору падне, па је нестане, као пљева, коју односи вјетар с гумна, и као дим из димњака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'А ја сам Господ Бог твој од земље Мисирске, и Бога осим мене нијеси познао, и осим мене нема ко би спасао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Ја те познах у пустињи, у земљи засушеној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Имајући добру пашу бијаху сити; али чим се наситише, понесе се срце њихово, зато ме заборавише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Зато ћу им бити као лав, као рис вребаћу их на путу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Срешћу их као медвједица којој узму медвједиће, и растргаћу им све срце њихово и изјешћу их ондје као лав; звијерје пољско раскинуће их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Пропао си, Израиљу; али ти је помоћ у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Гдје ти је цар? гдје је? нека те сачува у свијем градовима твојим; гдје ли су судије твоје, за које си говорио: дај ми цара и кнезове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Дадох ти цара у гњеву свом, и узех га у јарости својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Свезано је безакоње Јефремово, остављен је гријех његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Болови као у породиље спопашће га, син је неразуман, јер не би толико времена остао у утроби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Од гроба ћу их избавити, од смрти ћу их сачувати; гдје је, смрти, помор твој? гдје је, гробе, погибао твоја? кајање ће бити сакривено од очију мојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Родан ће бити међу браћом својом; али ће доћи источни вјетар, вјетар Господњи, који иде од пустиње, и усахнуће му извор, и студенац ће му засушити; он ће однијети благо од свијех драгих заклада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Самарија ће опустјети, јер се одметну од Бога својега; они ће пасти од мача, дјеца ће се њихова размрскати и трудне жене њихове распорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Обрати се, Израиљу, ка Господу Богу својему, јер си пао својега ради безакоња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Узмите са собом ријечи, и обратите се ка Господу; реците му: опрости све безакоње, и прими добро; и даћемо жртве усана својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Асирац нас не може избавити, нећемо јахати на коњма, нити ћемо више говорити дјелу руку својих: Боже наш; јер у тебе налази милост сирота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Исцијелићу отпад њихов, љубићу их драге воље; јер ће се гњев мој одвратити од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Бићу као роса Израиљу, процвјетаће као љиљан и пустиће жиле своје као дрвета Ливанска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Рашириће се гране његове, и љепота ће му бити као у маслине и мирис као Ливански.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Они ће се вратити и сједјети под сјеном његовијем, рађаће као жито и цвјетаће као винова лоза; спомен ће му бити као вино Ливанско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Јефреме, шта ће ми више идоли? Ја ћу га услишити и гледати; ја ћу му бити као јела зелена; од мене је твој плод.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Ко је мудар, нека разумије ово; и разуман нека позна ово; јер су прави путови Господњи, и праведници ће ходити по њима, а преступници ће пасти на њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Ријеч Господња која дође Јоилу сину Фатуилову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Чујте, старци; слушајте, сви становници земаљски; је ли овако што било за вашега времена или за времена ваших отаца?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Приповиједајте то синовима својим, и синови ваши својим синовима, и њихови синови потоњему кољену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Што оста иза гусјенице изједе скакавац, и што оста иза скакавца изједе хрушт, и што оста иза хрушта изједе црв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Отријезните се, пијанице, и плачите; и ридајте сви који пијете вино, за новијем вином, јер се оте из уста ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Јер дође на земљу моју силан народ и небројен; зуби су му као у лава и кутњаци као у лавице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Потр винову лозу моју, и смокве моје покида, сасвијем их огули и побаца, те им се гране бијеле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Ридај као младица опасана костријећу за мужем младости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Неста дара и наљева из дома Господњега; туже свештеници, слуге Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Опустје поље, тужи земље; јер је потрвено жито, усахло вино, нестало уља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Стидите се ратари, ридајте виноградари, пшенице ради и јечма ради, јер пропаде жетва на њиви;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Лоза посахну и смоква увену; шипак и палма и јабука и сва дрвета пољска посахнуше, јер неста радости између синова људских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Опашите се и плачите свештеници; ридајте који служите олтару, дођите, ноћујте у костријети, слуге Бога мојега; јер се уноси у дом Бога вашега дар и наљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Наредите пост, огласите празник, скупите старјешине, све становнике земаљске, у дом Господа Бога својега, и вапијте ка Господу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Јаох дана! јер је близу дан Господњи, и доћи ће као погибао од свемогућега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Није ли нестало хране испред очију наших, радости и весеља из дома Бога нашега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Сјеме иструхну под грудама својим, пусте су житнице, разваљене спреме, јер посахну жито.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Како уздише стока! како су се смела говеда! јер немају паше; и овце гину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'К теби, Господе, вичем, јер огањ сажеже паше у пустињи, и пламен попали сва дрвета у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'И звијерје пољско погледа за тобом, јер усахнуше потоци водени и огањ сажеже паше у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Трубите у трубу на Сиону, и вичите на светој гори мојој, нека дркћу сви становници земаљски, јер иде дан Господњи, јер је близу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Дан, када је мрак и тама, дан, када је облак и магла; како се зора разастире поврх гора, тако иде народ велик и силан, какога није било откад је вијека нити ће га послије кад бити од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Пред њим прождире огањ, а за њим пали пламен; земља је пред њим као врт Едемски, а за њим пустиња пуста, ништа неће утећи од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'На очима су као коњи и трчаће као коњици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Скакаће поврх гора топоћући као кола, праскајући као пламен огњени који сажиже стрњику, као силан народ спреман за бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Пред њим ће се препадати народи, свако ће лице поцрњети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Они ће трчати као јунаци, као војници скакаће на зид, и сваки ће ићи својим путем, нити ће отступати са своје стазе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'И један другога неће тискати, сваки ће ићи својим путем, и на мачеве навирући неће се ранити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'По граду ће ходити, по зидовима ће трчати, у куће ће се пети, улазиће кроз прозоре као лупеж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Пред њима ће се земља трести, небеса ће се поколебати, сунце ће и мјесец помркнути и звијезде ће устегнути свјетлост своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'А Господ ће пустити глас свој пред војском својом, јер ће око његов бити врло велик, јер ће бити силан онај који ће извршити вољу његову; јер ће дан Господњи бити велик и врло страшан, и ко ће га поднијети?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Зато још говори Господ: обратите се к мени свијем срцем својим и постећи и плачући и тужећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'И раздерите срца своја а не хаљине своје, и обратите се ка Господу Богу својему, јер је милостив и жалостив, спор на гњев и обилан милосрђем и каје се ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Ко зна, неће ли се повратити и раскајати се, и оставити иза тога благослов, дар и наљев за Господа Бога вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Трубите у трубу на Сиону, наредите пост, прогласите светковину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Саберите народ, освештајте сабор, скупите старце, саберите дјецу и која сисају; женик нека изиде из своје клијети и невјеста из ложнице своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Између тријема и олтара нека плачу свештеници, слуге Господње, и нека реку: прости, Господе, народу својему, и не дај нашљедства својега под срамоту, да њим обладају народи; зашто да реку у народима: гдје им је Бог?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'И Господ ће ревновати за земљу своју и пожалиће народ свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'И Господ ће одговорити и рећи ће своме народу: ево, ја ћу вам послати жита и вина и уља, и бићете га сити, и нећу вас више дати под срамоту међу народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Јер ћу удаљити од вас сјеверца, и одагнати га у земљу суху и пусту, предњу чету његову у источно море а задњу у море западно, и подигнуће се смрад његов, и трулеж ће се његов подигнути, пошто учини велике ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Не бој се, земљо, радуј се и весели се, јер ће Господ учинити велике ствари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Не бојте се, звијери пољске; јер ће се зелењети пасишта у пустињи и дрвета ће носити род свој, смоква ће и лоза винова давати силу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'И ви, синови Сионски, радујте се и веселите се у Господу Богу својем, јер ће вам дати дажд на вријеме, и спустиће вам дажд рани и позни на вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'И гумна ће се напунити жита, а каце ће се прељевати вином и уљем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'И накнадићу вам године које изједе скакавац, хрушт и црв и гусјеница, велика војска моја, коју слах на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'И јешћете изобила, и бићете сити и хвалићете име Господа Бога својега, који учини с вама чудеса, и народ мој неће се посрамити довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'И познаћете да сам ја усред Израиља, и да сам ја Господ Бог ваш, и да нема другога, и народ мој неће се посрамити довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'И послије ћу излити дух свој на свако тијело, и прорицаће синови ваши и кћери ваше, старци ће ваши сањати сне, младићи ће ваши виђати утваре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'И на слуге ћу и на слушкиње у оне дане излити дух свој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'И учинићу чудеса на небу и на земљи, крв и огањ и пушење дима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'Сунце ће се претворити у таму и мјесец у крв прије него дође велики и страшни дан Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'И сваки који призове име Господње спашће се; јер ће на гори Сиону и у Јерусалиму бити спасење, као што је рекао Господ, и у остатку који позове Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Јер, гле, у оне дане и у оно вријеме, кад вратим робље Јудино и Јерусалимско,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Сабраћу све народе, и свешћу их у долину Јосафатову, и ондје ћу се судити с њима за свој народ и за нашљедство своје Израиља, којега расијаше међу народе и раздијелише земљу моју;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'И за мој народ бацаше ждријеб, и даваше дијете за курву, и продаваше дјевојку за вино, те пише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'И шта хоћете ви са мном, Тире и Сидоне, и сви крајеви Палестински? хоћете ли да ми платите? и хоћете ли да ми вратите? Одмах ћу вам без оклијевања платити плату вашу на вашу главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Јер узесте сребро моје и злато моје, и најљепше закладе моје унесосте у своје цркве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'И синове Јудине и синове Јерусалимске продадосте синовима Грчким да бисте их отјерали далеко од међе њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Ево, ја ћу их дигнути с мјеста куда их продадосте, и платићу вам плату вашу на вашу главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'И продаћу ваше синове и ваше кћери у руке синовима Јудинијем, и они ће их продати Савејцима у народ даљни, јер Господ рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Објавите ово по народима, огласите рат, подигните јунаке нека дођу и иду сви војници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Раскујте раонике своје на мачеве, и српове своје на копља; ко је слаб, нека рече: јунак сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Скупите се и ходите, сви народи унаоколо, и саберите се! тамо сведи, Господе, јунаке своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Нека се подигну и дођу народи у долину Јосафатову; јер ћу ондје сјести да судим свијем народима унаоколо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Замахните српом, јер је жетва узрела; ходите, сиђите, јер је тијесак пун, каце се прељевају; јер је злоћа њихова велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Гомиле, гомиле у долини судској; јер је дан Господњи близу у долини судској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Сунце ће и мјесец помркнути, и звијезде ће устегнути своју свјетлост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'И Господ ће рикнути са Сиона, и из Јерусалима ће пустити глас свој, и затрешће се небо и земља; али ће Господ бити уточиште своме народу и крјепост синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'И познаћете да сам ја Господ Бог ваш, који наставам у Сиону, у светој гори својој; и Јерусалим ће бити свет, и туђинци неће више ићи по њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'И тада ће горе капати слатким вином, и хумови ће се топити од млијека, и свијем потоцима Јудинијем тећи ће вода, и изаћи ће извор из дома Господњега и натопиће долину Ситим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Мисир ће опустјети, и Едомска ће бити пуста пустиња за насиље учињено синовима Јудинијем, јер пролише крв праву у земљи њиховој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'А Јуда ће стајати довијека и Јерусалим од кољена до кољена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'И очистићу крв њихову, које не очистих; и Господ ће наставати у Сиону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Ријечи Амоса који бијаше између пастира из Текује, што видје за Израиља за времена Озије цара Јудина и за времена Јеровоама сина Јоасова цара Израиљева, двије године прије труса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Рече дакле: Господ ће рикнути са Сиона, и из Јерусалима ће пустити глас свој, и тужиће станови пастирски и посушиће се врх Кармилу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Овако вели Господ: за три зла и за четири што учини Дамасак, нећу му опростити, јер врхоше Галад гвозденом браном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Него ћу пустити огањ у дом Азаилов, те ће прождријети дворове Вен-Ададове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'И поломићу пријеворнице Дамаску, и истријебићу становнике из поља Авена, и онога који држи палицу из дома Еденова, и отићи ће у ропство народ Сирски у Кир, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Овако вели Господ: за три зла и за четири што учини Газа, нећу јој опростити, јер их заробише сасвијем и предадоше Едомцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Него ћу пустити огањ у зидове Гази, те ће јој прождријети дворове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'И истријебићу становнике из Азота и онога који држи палицу из Аскалона, и окренућу руку своју на Акарон, и изгинуће остатак Филистејски, вели Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Овако вели Господ: за три зла и за четири што учини Тир, нећу му опростити, јер сасвијем дадоше у ропство Едомцима и не сјећаше се братске вјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Него ћу пустити огањ у зидове Тиру, те ће прождријети дворове његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Овако вели Господ: за три зла и за четири што учини Едом, нећу му опростити, јер гони брата својега мачем потрвши у себи све жаљење, и гњев његов раздире једнако, и срдњу своју држи увијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Него ћу пустити огањ у Теман, и прождријеће дворе у Восори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Овако вели Господ: за три зла и за четири што учинише синови Амонови, нећу им опростити, јер параше трудне жене у Галаду да рашире међу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Него ћу запалити огањ у зидовима Рави, те ће јој прождријети дворове с виком у дан боја и с буром у дан вихора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'И цар ће њихов отићи у ропство, он и кнезови његови с њим, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Овако вели Господ: за три зла и за четири што учини Моав, нећу му опростити, јер сажеже кости цара Едомскога у креч.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Него ћу пустити огањ на Моава, те ће прождријети дворове у Кариоту, и Моав ће погинути с вревом, с виком и с гласом трубнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'И истријебићу судију из њега и све кнезове његове побићу с њим, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Овако вели Господ: за три зла и за четири што учини Јуда, нећу му опростити, јер презреше закон Господњи и уредаба његовијех не држаше, и преварише се лажима својим, за којима ходише оци њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Него ћу пустити огањ у Јуду, те ће прождријети дворе Јерусалимске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Овако вели Господ: за три зла и за четири што учини Израиљ, нећу му опростити, јер продаваше праведника за новце и убогога за једне опанке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Чезну за прахом земаљским на глави сиромасима, и превраћају пут смјернима; и син и отац одлазе к једној дјевојци да скврне свето име моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'И на хаљинама у залогу узетијем леже код свакога олтара, и вино оглобљенијех пију у кући богова својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'А ја истријебих испред њих Амореје, који бијаху високи као кедри и јаки као храстови, и потрх род њихов озго и жиле њихове оздо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'И ја вас изведох из земље Мисирске, и водих вас по пустињи четрдесет година да бисте наслиједили земљу Аморејску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'И подизах између синова ваших пророке и између младића ваших назиреје. Није ли тако? синови Израиљеви, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'А ви појисте назиреје вином, и пророцима забрањивасте говорећи: не пророкујте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Ево, ја ћу вас притиснути на мјесту вашем као што се притискују кола пуна снопља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'И неће бити бијега брзому, и јаки неће утврдити крјепости своје, и храбри неће спасти душе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'И стријелац неће се одржати, и лаки на ногу неће се избавити, нити ће коњик спасти душе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Него ће најхрабрији међу јунацима го побјећи у онај дан, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Чујте ријеч коју говори Господ за вас, синови Израиљеви, за све племе које сам извео из земље Мисирске, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Само вас познах између свијех племена земаљских, зато ћу вас походити за сва безакоња ваша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Хоће ли двојица ићи заједно, ако се не састану?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Хоће ли рикнути лав у шуми, ако нема лова? хоће ли лавић пустити глас свој из пећине своје, ако не ухвати што?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Хоће ли птица пасти у мрежу на земљу, ако нема замке? хоће ли се дигнути мрежа са земље, ако се ништа не ухвати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Хоће ли труба трубити по граду, а народ да не дотрчи уплашен? хоће ли бити несрећа у граду, а Господ да је не учини?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Јер Господ Господ не чини ништа не откривши тајне своје слугама својим пророцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Кад лав рикне, ко се неће бојати? кад Господ рече, ко неће пророковати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Огласите по дворовима Азотским и по дворовима у земљи Мисирској, и реците: скупите се на горе Самаријске и видите велике нереде у њој и насиље у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Не знају чинити право, говори Господ, сабирају благо насиљем и грабежем у дворима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Зато овако вели Господ Господ: непријатељ је око земље и обориће ти силу твоју, и оплијениће се дворови твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Овако вели Господ: као кад пастир истргне из уста лаву двије голијени или крај од уха, тако ће се истргнути синови Израиљеви који сједе у Самарији на углу од одра и накрај постеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Чујте и засвједочите у дому Јаковљеву, говори Господ Господ Бог над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Кад походим Израиља за гријехе његове, тада ћу походити и олтаре Ветиљске, и одбиће се рогови олтару и пашће на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'И ударићу кућу зимну и љетну кућу, и пропашће куће од слонове кости, и нестаће великих кућа, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Чујте ову ријеч, краве Васанске, које сте у гори Самаријској, које криво чините убогима и сатирете сиромахе, које говорите господарима својим: донесите да пијемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Закле се Господ Господ светошћу својом да ће вам ево доћи дани, те ће вас извлачити кукама, и остатак ваш удицама рибарским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'И кроз проломе ћете ижљести, свака на према се, и побацаћете што буде у дворовима, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Идите у Ветиљ, и чините безакоње, у Галгалу множите безакоње своје, и приносите свако јутро жртве своје, треће године десетке своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'И палите жртву захвалну од хљеба киселога, и огласите жртве драговољне и разгласите, јер вам је тако мило, синови Израиљеви, говори Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'И зато вам ја дадох да су вам чисти зуби по свијем градовима вашим и да нема хљеба нигдје по свијем мјестима вашим; али се не обратисте к мени, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'А ја вам устегох дажд, кад још три мјесеца бијаху до жетве, и пустих дажд на један град, а на други град не пустих дажда, један се крај накваси, а други крај, на који не даждје, посуши се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Тако два и три града иђаху у један град да пију воде, и не могаху се напити; ипак се не обратисте к мени, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Бих вас сушом и медљиком; гусјенице изједоше обиље у вртовима вашим и у виноградима вашим и на смоквама вашим и на маслинама вашим; ипак се не обратисте к мени, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Послах у вас помор као у Мисир, побих мачем младиће ваше и одведох коње ваше, и учиних те се подизаше смрад из окола вашега и у ноздрве ваше; ипак се не обратисте к мени, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Затирах вас као што Господ затр Содом и Гомор, и бијасте као главња истргнута из огња; ипак се не обратисте к мени, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Зато ћу ти тако учинити, Израиљу; и што ћу ти тако учинити, приправи се, Израиљу, да сретеш Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Јер ето онога који је саздао горе и који је створио вјетар и јавља човјеку што мисли, чини од зоре таму, и ходи по висинама земаљским; име му је Господ Бог над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Чујте ову ријеч, нарицање које подижем за вама, доме Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Паде, неће више устати дјевојка Израиљева; бачена је на земљу своју, нема никога да је подигне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Јер овако вели Господ Господ: у граду из којега је излазила тисућа остаће стотина, а из којега је излазила стотина у њему ће остати десет дому Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Јер овако вели Господ дому Израиљеву: тражите ме, и бићете живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'А не тражите Ветиља, и не идите у Галгал, и не пролазите у Вирсавеју, јер ће Галгал отићи у ропство, а Ветиљ ће се обратити у ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Тражите Господа и бићете живи, да не обузме дома Јосифова као огањ и спали и не буде никога да гаси Ветиљ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Који обраћате суд у пелен, и правду на земљу обарате,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Онога тражите који је створио звијезде кола и штапе, и који претвара сјен смртни у јутро а дан у тамну ноћ, који дозива воде морске и прољева их по земљи; име му је Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Који подиже погибао на јакога, те погибао дође на град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Мрзе на онога који кара на вратима, и гаде се на онога који говори право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Зато што газите сиромаха и узимате од њега жито у данак, саградисте куће од тесана камена, али нећете сједјети у њима; насадисте лијепе винограде, али нећете пити вина из њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Јер знам безакоња ваша, којих је много, и гријехе ваше, који су велики, који мучите праведника, примате поклоне и изврћете правду убогима на вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Зато ће праведни мучати у ово вријеме, јер је зло вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Тражите добро а не зло, да бисте били живи; и тако ће Господ Бог над војскама бити с вама, како рекосте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Мрзите на зло и љубите добро, и поставите на вратима суд, не би ли се Господ Бог над војскама смиловао на остатак Јосифов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Зато овако вели Господ Бог над војскама, Господ: биће тужњава по свијем улицама, и по свијем путовима говориће: јаох! јаох! и зваће ратаре на жалост и на тужњаву оне који умију нарицати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'И по свијем ће виноградима бити тужњава, јер ћу проћи посред тебе, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Тешко онима који желе дан Господњи! што ће вам дан Господњи? тада је мрак а не видјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Као да би ко бјежао од лава па би га срео медвјед; или као да би ко дошао у кућу и наслонио се руком на зид, па би га змија ујела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Није ли дан Господњи мрак а не видјело? и тама, без свјетлости?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Мрзим на ваше празнике, одбацио сам их, и нећу да миришем светковина ваших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Ако ми принесете жртве паљенице и приносе своје, нећу их примити, и нећу погледати на захвалне жртве од угојене стоке ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Уклони од мене буку пјесама својих, и свирања псалтира твојих нећу да чујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Него суд нека тече као вода и правда као силан поток.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Јесте ли мени приносили жртве и даре у пустињи четрдесет година, доме Израиљев?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Него сте носили шатор Молоха својега, и Хијуна, ликове своје, звијезду бога својега, које сами себи начинисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Зато ћу вас преселити иза Дамаска, говори Господ, којему је име Бог над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Тешко безбрижнима у Сиону и онима који су без страха у гори Самаријској, који су на гласу између поглавица народима, ка којима долази дом Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Прођите у Халну и видите, и оданде идите у велики Емат, послије сиђите у Гат Филистејски; је ли које царство боље од овијех? јесу ли им међе пространије од ваших међа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Тешко вама који мислите да је далеко зли дан, а примичете столицу на којој је насиље;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Који лијежете на одрима од слонове кости и пружате се на постељама својим, и једете јагањце из стада и теоце угојене;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Који пјевате уза псалтире, и измишљате справе музичке као Давид;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Који пијете вино великим чашама, и мажете се скупоцјенијем мирисима, а не марите за полом Јосифов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Зато ће сада отићи у ропство међу првима који ће отићи у ропство, и престаће радост онијех који се госте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Закле се Господ Господ собом, говори Господ Бог над војскама; ја се гадим на понос Јаковљев и мрзим на дворове његове; зато ћу предати град и све што је у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'И ако десет људи остане у једној кући, умријеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'И кад узме кога стриц му или који ће га спалити да изнесе кости његове из куће, рећи ће ономе који буде у куту у кући: има ли јоште ко код тебе? А он ће рећи: нема никога. А он ће рећи: мучи; јер не помињаше имена Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Јер ево, Господ заповиједа и удариће дом велики да се развали и мали дом да попуца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Трче ли коњи по стијени и оре ли се воловима? јер ви претвористе суд у жуч, и плод од правде у пелен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Ви се радујете ономе што није ништа, и говорите: нијесмо ли својом снагом добили рогове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Јер, гле, ја ћу подигнути на вас, доме Израиљев, говори Господ Бог над војскама, народ, који ће вас притијеснити од уласка у Емат до потока у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Ово ми показа Господ Господ: гле, саздаваше скакавце кад почињаше ницати отава, и гле, бијаше отава по царевој косидби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'А кад поједоше траву земаљску, тада рекох: Господе, Господе, смилуј се; како ће се подигнути Јаков? јер је мали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Господ се раскаја зато: неће бити, рече Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Тада ми показа Господ Господ, и гле, Господ Господ повика да ће судити огњем; и огањ прождрије велику бездану и прождрије дио земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'А ја рекох: Господе, Господе, престани; како ће се подигнути Јаков? јер је мали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Господ се раскаја зато: ни то неће бити, рече Господ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Тада ми показа, и гле, Господ стајаше на зиду сазиданом по мјерилима, и у руци му бјеху мјерила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'И рече ми Господ: што видиш, Амосе? И рекох: мјерила. А Господ ми рече: ево, ја ћу метнути мјерила посред народа својега Израиља, нећу га више пролазити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Јер ће се разорити висине Исакове, и светиње ће Израиљеве опустјети, и устаћу на дом Јеровоамов с мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Тада Амасија свештеник Ветиљски посла к Јеровоаму цару Израиљеву и поручи му: Амос диже буну на те усред дома Израиљева, земља не може поднијети свијех ријечи његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Јер овако говори Амос: Јеровоам ће погинути од мача, а Израиљ ће се одвести из земље своје у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Потом Рече Амасија Амосу: видиоче, иди, бјежи у земљу Јудину, и ондје једи хљеб и ондје пророкуј;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'А у Ветиљу више не пророкуј, јер је светиња царева и дом је царски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'А Амос одговори и рече Амасији: не бјех пророк ни пророчки син, него бјех говедар и брах дудове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'А Господ ме узе од стада и рече ми Господ: иди, пророкуј народу мојему Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Сада дакле чуј ријеч Господњу. Ти кажеш: не пророкуј у Израиљу, и не кропи по дому Исакову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Зато овако вели Господ: жена ће ти се курвати у граду, и синови ће твоји и кћери твоје пасти од мача, и земља ће се твоја раздијелити ужем, и ти ћеш умријети у нечистој земљи, а Израиљ ће се одвести из своје земље у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Ово ми показа Господ: гле, котарица љетнога воћа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'И рече: што видиш, Амосе? А ја рекох: котарицу љетнога воћа. А Господ ми рече: дође крај народу мојему Израиљу, нећу га више пролазити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'И пјесме ће црквене бити ридање у онај дан, говори Господ; биће мноштво мртвијех тјелеса, која ће се свуда побацати мучећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Чујте ово, који прождирете убоге и сатирете сиромахе у земљи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Говорећи: кад ће проћи младина да продајемо жито? и субота да отворимо пшеницу? умаљујући ефу и повећавајући сикал и варајући лажнијем мјерилима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Да купујемо сиромахе за новце и убогога за једне опанке, и да продајемо очинке од пшенице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Закле се Господ славом Јаковљевом: нећу нигда заборавити ниједнога дјела њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Неће ли се земља потрести од тога, и протужити сваки који живи на њој? и неће ли се сва разлити као ријека? и неће ли се однијети и потопити као од ријеке Мисирске?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'И у онај дан, говори Господ Господ, учинићу да сунце зађе у подне, и помрачићу земљу за бијела дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'И претворићу празнике ваше у жалост и све пјесме ваше у плач, и метнућу костријет око свијех бедара, и учинићу да свака глава оћелави и да буде жалост као за јединцем, и крај ће јој бити као горак дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Гле, иду дани, говори Господ Господ, кад ћу пустити глад на земљу, не глад хљеба ни жеђ воде, него слушања ријечи Господњих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'И потуцаће се од мора до мора, и од сјевера до истока трчаће тражећи ријеч Господњу, и неће је наћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'У то ће вријеме обамирати лијепе дјевојке и младићи од жеђи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Који се куну кривицом Самаријском и говоре: тако да је жив Бог твој, Дане, и тако да је жив пут у Вирсавеју. И пашће, и неће више устати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Видјех Господа, а он стајаше на олтару, и рече: удари у горњи праг од врата да се затресу довратници, и расцијепи их све од врха њихова; а што остане иза њих побићу мачем; неће утећи између њих ниједан, нити ће се који спасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Да се закопају у најдоњи крај земље, оданде ће их узети рука моја; и да изађу на небо, оданде ћу их скинути;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'И да се сакрију на врх Кармила, наћи ћу их и узећу их оданде; и да се сакрију испред мојих очију на дно морско, ондје ћу заповједити змији да их уједе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Да отиду у ропство пред непријатељима својим, и ондје ћу заповједити мачу да их побије, и обратићу очи своје њима на зло а не на добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Јер Господ Господ над војскама кад се дотакне земље, она се растапа и туже сви који живе на њој, и разљева се сва као ријека и потапа се као од ријеке Мисирске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Он је саградио себи клијети на небу и свод свој основао на земљи; зове воде морске и изљева их по земљи; име му је Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Нијесте ли ми, синови Израиљеви, као синови Етиопски? говори Господ; не изведох ли Израиља из земље Мисирске, а Филистеје из Кафтора и Сирце из Кира?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Гле, очи су Господње управљене на ово грјешно царство да га затресем са земље; али нећу сасвијем затрти дома Јаковљева, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Јер, ево, ја ћу заповједити и разметаћу међу свијем народима дом Израиљев као што се размеће жито у решету да ни зрно не падне на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Од мача ће погинути сви грјешници између мојега народа, који говоре: неће доћи, нити ће нас задесити зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'У то ћу вријеме подигнути опали шатор Давидов, и затворићу му пукотине, и оправићу му што је разваљено, и опет ћу га саградити као што је био прије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Да би наслиједили остатак Едомски и све народе на које се призива име моје, говори Господ, који чини ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Ево, иду дани, говори Господ, кад ће орач стизати жетеоца, и који гази грожђе сијача, и горе ће капати слатким вином, а сви ће се хумови растапати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'И повратићу робље народа својега Израиља, и опет ће саградити пусте градове и населиће се, и насадиће винограде и пити вино из њих, и начиниће вртове и јести род из њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'И посадићу их у земљи њиховој, и неће се више ишчупати из земље своје, коју им дадох, говори Господ Бог твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Утвара Авдијева. Овако вели Господ Господ за Едомску: чусмо глас од Господа, и гласник би послан к народима: устајте, да устанемо на њу у бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Гле, учинићу те малијем међу народима, бићеш врло презрен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Понос срца твојега превари те, тебе, који живиш у расјелинама каменијем, у високом стану свом, и говориш у срцу свом: ко ће ме оборити на земљу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Да подигнеш високо као орао и међу звијезде да метнеш гнијездо своје, оданде ћу те оборити, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Како си оплијењен? да су дошли к теби крадљивци или лупежи ноћу, не би ли покрали колико им је доста? да су дошли к теби берачи виноградски, не би ли оставили пабирака?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Како се претражи Исав, како се нађоше потаје његове!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'До границе те одведоше сви који бијаху с тобом у вјери, преварише те и надвладаше те који бијаху у миру с тобом; који једу хљеб твој подметнуше ти замку, да се не опази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'У онај дан, говори Господ, нећу ли погобити мудре у земљи Едемској и разумне у гори Исавовој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'И твоји ће се јунаци уплашити, Темане, да се истријебе покољем сви из горе Исавове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'За насиље учињено брату твојему Јакову покриће те стид и истријебићеш се засвагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Онај дан, кад ти стајаше насупрот; онај дан, кад иностранци одвођаху у ропство војску његову, и туђинци улажаху на врата његова и бацаху ждријеб за Јерусалим, бјеше и ти као који од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Али ти не требаше гледати дана брата својега, дана, кад се одвођаше у туђу земљу, нити се радовати синовима Јудинијем у дан кад пропадаху, нити разваљивати уста у дан невоље њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Не требаше ти ући на врата народа мојега у дан погибли њихове, не требаше да и ти гледаш зло њихово у дан погибли њихове ни да се машаш добра њихова у дан погибли њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Нити требаше да станеш на распутицу да убијаш бјежан њихову, нити да издајеш онијех који осташе у дан невоље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Јер је дан Господњи близу свијем народима; како си чинио, тако ће ти бити, плата ће ти се вратити на главу твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Јер као што сте ви пили на светој гори мојој, тако ће пити сви народи вазда, пиће, и ждријеће, и биће као да их није било.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'А на гори ће Сиону бити спасење, и биће света, и дом ће Јаковљев наслиједити нашљедство своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'И дом ће Јаковљев бити огањ и дом Јосифов пламен, а дом Исавов стрњика; и разгоријеће се на њих, и спалиће их; и неће бити остатака дому Исавову, јер Господ рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'И наслиједиће југ, гору Исавову, и равницу, Филистеје; и наслиједиће поље Јефремово и поље Самаријско и Венијаминово И Галад;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'И заробљена војска синова Израиљевијех наслиједиће што је било Хананејско до Сарепте; а робље Јерусалимско, што је у Сефараду, наслиједиће јужне градове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'И избавитељи ће изаћи на гору Сион да суде гори Исавовој, и царство ће бити Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Дође ријеч Господња Јони сину Аматијеву говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Устани, иди у Ниневију град велики, и проповиједај против њега, јер изађе злоћа њихова преда ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'А Јона уста да бјежи у Тарсис од Господа, и сишав у Јопу нађе лађу која иђаше у Тарсис, и платив возарину уђе у њу да отиде с њима у Тарсис од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Али Господ подиже велик вјетар на мору, и поста велика бура на мору да мишљаху да ће се разбити лађа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'И лађари уплашивши се призваху сваки својега бога, и бацаху што бјеше у лађи у море да би била лакша; а Јона бјеше сишао на дно лађи, и легав спаваше тврдо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'А управитељ од лађе приступи к њему и рече му: шта ти спаваш! устани, призивај Бога својега, не би ли нас се опоменуо Бог да не погинемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Потом рекоше један другоме: ходите, да бацимо ждријеб да видимо са кога дође на нас ово зло. И бацише ждријеб, и паде ждријеб на Јону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Тада му рекоше: кажи нам зашто дође ово зло на нас; које си радње? и одакле идеш? из које си земље? и од кога си народа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'А он им рече: Јеврејин сам, и бојим се Господа Бога небескога, који је створио море и суху земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Тада се врло уплашише људи, и рекоше му: што си учинио? Јер дознаше људи да бјежи од Господа, јер им он каза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'И рекоше му: што ћемо чинити с тобом, да би нам море утолило? Јер бура на мору биваше све већа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'А он им рече: узмите ме и баците ме у море, и море ће вам утолити, јер видим да је с мене дошла на вас ова велика бура.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'А људи стадоше веслати да би дошли ка крају; али не могаху, јер им бура на мору биваше све већа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Тада призваше Господа и рекоше: молимо ти се, Господе, да не погинемо ради душе овога човјека, и немој метнути на нас крви праве, јер ти, Господе, чиниш како хоћеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Потом узеше Јону и бацише га у море, и преста бура на мору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Тада се побојаше они људи Господа врло, и принесоше жртву Господу и учинише завјете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Али Господ заповједи, те велика риба прогута Јону; и Јона би у трбуху рибљем три дана и три ноћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'И замоли се Јона Господу Богу својему из трбуха рибљега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'И рече: завапих у невољи својој ка Господу, и услиши ме; из утробе гробне повиках, и ти чу глас мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Јер си ме бацио у дубине, у срце мору, и вода ме оптече; све поплаве твоје и вали твоји прелазише преко мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'И рекох: одбачен сам испред очију твојих; али ћу још гледати свету цркву твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Оптекоше ме воде до душе, бездана ме опколи, сита омота ми се око главе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Сидох до крајева горских, пријеворнице земаљске нада мном су довијека; али ти извади живот мој из јаме, Господе Боже мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Кад нестајаше душе моје у мени, поменух Господа, и молитва моја дође к теби, у свету цркву твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Који држе лажне таштине, остављају своју милост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'А ја ћу ти гласом захвалнијем принијети жртву, испунити што сам завјетовао; спасење је у Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 11, 'И Господ заповједи риби, те избљува Јону на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'И дође ријеч Господња Јони други пут говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Устани, и иди у Ниневију град велики, и проповиједај му оно што ти ја кажем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'И устав Јона отиде у Ниневију по ријечи Господњој; а Ниневија бјеше град врло велик, три дана хода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'И Јона поче ићи по граду један дан хода, и проповиједа и рече: јоште четрдесет дана, па ће Ниневија пропасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'И Ниневљани повјероваше Богу, и огласише пост, и обукоше се у костријет од највећега до најмањега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Јер кад дође та ријеч до цара Ниневијскога, он уста са својега пријестола, и скиде са себе своје одијело, и обуче се у костријет и сједе у пепео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'И прогласи се и каза се по Ниневији по заповијести царевој и кнезова његовијех говорећи: људи и стока, говеда и овце да не окусе ништа, ни да пасу ни да пију воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Него и људи и стока да се покрију костријећу, и да призивају Бога јако, и да се врати сваки са свога злога пута и од неправде која му је у руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Ко зна, еда се поврати и раскаје Бог и поврати се од љутога гњева својега, те не изгинемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'И Бог видје дјела њихова, гдје се вратише са злога пута својега; и раскаја се Бог ода зла које рече да им учини, и не учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'А Јони би врло недраго, и расрди се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'И помоли се Господу и рече: Господе! не рекох ли то кад још бијах у својој земљи? зато шћах прије побјећи у Тарсис; јер знах да си ти Бог милостив и жалостив, спор на гњев и обилан милосрђем, и кајеш се ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Сада Господе, узми душу моју од мене, јер ми је боље умријети него живјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'А Господ рече: је ли добро што се срдиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'И Јона изиде из града, и сједе с истока граду, и начини ондје колибу, и сјеђаше под њом у хладу да види што ће бити од града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'А Господ Бог заповједи, те узрасте тиква над Јоном да му буде сјен над главом да му поможе у муци његовој; и Јона се обрадова тикви веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Потом заповједи Бог, те дође црв у зору сјутрадан, и подгризе тикву, те усахну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'И кад ограну сунце, посла Бог сух источни вјетар; и сунце стаде жећи Јону по глави тако да обамираше и пожеље да умре говорећи: боље ми је умријети него живјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'А Бог рече Јони: је ли добро што се срдиш тикве ради? А он рече: добро је што се срдим до смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'А Господ му рече: теби је жао тикве, око које се нијеси трудио, и које нијеси одгајио, него једну ноћ узрасте а другу ноћ пропаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'А мени да не буде жао Ниневије, великога града, у ком има више од сто и двадесет тисућа људи који још не знају шта је десно шта ли лијево, и много стоке?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Ријеч Господња која дође Михеју Моресећанину за времена Јоатама, Ахаза и Језекије, царева Јудинијех, што видје за Самарију и за Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Чујте, сви народи, слушај, земљо и што је на њој, и Господ Бог да вам је свједок, Господ из свете цркве своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Јер, гле, Господ излази из мјеста својега, и сићи ће, и ходиће по висинама земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'И горе ће се растопити пред њим, и долине ће се расјести, као восак од огња и као вода што тече низ стрмен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Све је то за злочинство Јаковљево и за гријехе дома Израиљева. Које је злочинство Јаковљево? није ли Самарија? које су висине Јудине? није ли Јерусалим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Зато ћу учинити од Самарије гомилу у пољу да се саде виногради, и побацаћу камење њезино у долину и открићу јој темеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'И сви резани ликови њезини разбиће се, и сви ће се дарови њезини сажећи огњем, и све ћу идоле њезине потрти, јер од плате курварске накупи, и опет ће бити плата курварска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Зато ћу плакати и ридати; ходићу свучен и го; плакаћу као змајеви и тужићу као сове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Јер јој се ране не могу исцијелити, дођоше до Јуде, допријеше до врата мојега народа, до Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Не јављајте у Гату, не плачите; у Вит-Афри ваљај се по праху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Изиди, становнице Сафирска, с голом срамотом; становница Сананска неће изаћи; жалост Вет-езилска неће вам дати станка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Јер становница Маротска тужи за својим добром. Јер сиђе зло од Господа до врата Јерусалимских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Упрегни брзе коње у кола, становнице Лахиска, која си почетак гријеху кћери Сионској, јер се у теби нађоше злочинства Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Зато пошљи даре Моресету Гатском; домови Ахсивски превариће цареве Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Још ћу ти довести нашљедника, становнице Мариска; доћи ће до Одолама, славе Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Начини се ћелава и остризи се за милом дјецом својом; рашири ћелу своју као орао, јер се воде од тебе у ропство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Тешко онима који смишљају безакоње и о злу се труде на постељама својим, и кад сване извршују, јер им је сила у руци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Желе њиве, и отимају их; желе куће, и узимају; чине силу човјеку и кући његовој, човјеку и нашљедству његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Зато овако вели Господ: ево, ја мислим зло томе роду, из којега нећете извући вратова својих, нити ћете ходити поносито, јер ће бити зло вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'У оно вријеме говориће се прича о вама, и нарицаће се жалосно говорећи: пропадосмо; промијени дио народа мојега; како ми узе! узевши њиве наше раздијели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Зато нећеш имати никога ко би ти повукао уже за ждријеб у збору Господњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Немојте пророковати, нека они пророкују; ако им не пророкују, неће отступити срамота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'О ти, који се зовеш дом Јаковљев, је ли се умалио дух Господњи? јесу ли то дјела његова? еда ли моје ријечи нијесу добре ономе који ходи право?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'А народ се мој прије подиже као непријатељ; преко хаљине скидате плашт с онијех који пролазе не бојећи се, који се враћају из боја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Жене народа мојега изгоните из милијех кућа њиховијех, од дјеце њихове отимате славу моју навијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Устаните и идите, јер ово није почивалиште; што се оскврни, погубиће вас погибљу великом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Ако ко ходи за вјетром и казује лажи говорећи: пророковаћу ти за вино и за силовито пиће; тај ће бити пророк овоме народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Доиста ћу те сабрати свега, Јакове, доиста ћу скупити остатак Израиљев; поставићу их заједно као овце Восорске, као стадо усред тора њихова, биће врева од људства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Пред њима ће ићи који разбија; они ће разбити и проћи кроз врата, и изаћи ће; и цар ће њихов ићи пред њима, и Господ ће бити пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Зато рекох: чујте, поглавице Јаковљеве и кнезови дома Израиљева, не треба ли вам знати шта је право?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Који мрзите на добро а љубите зло, садирете кожу с њих и месо с кости њиховијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'И једете месо народа мојега и садирете кожу с њих и кости им пребијате, и сасијецате као у лонац и као месо у котао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Тада ће викати ка Господу, али их неће услишити, него ће сакрити лице своје од њих у оно вријеме, како они зло радише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Овако вели Господ за пророке који заводе мој народ, који гризу зубима својим и вичу: мир; и ако им ко не да ништа у уста, дижу рат на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Зато ће вам утвара бити ноћ и прорицање ваше тама; и сунце ће заћи тијем пророцима и дан ће им се смрачити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Тада ће се постидјети видиоци, и врачари ће се посрамити, и сви ће застријети усне своје, јер неће бити одговора Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Али ја сам пун силе од духа Господњега, и суда и храбрости да кажем Јакову злочинство његово и Израиљу гријех његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Чујте ово, поглавице дома Јаковљева и кнезови дома Израиљева, који се гадите на правду, и све што је право изврћете;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Који градите Сион крвљу и Јерусалим безакоњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Поглавари његови суде по миту, и свештеници његови уче за плату, и пророци његови гатају за новце, а на Господа се ослањају говорећи: није ли Господ усред нас? неће доћи зло на нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Зато ће се с вас Сион преорати као њива, и Јерусалим ће постати гомила, и гора од дома висока шума.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Али ће у пошљедња времена бити утврђена гора дома Господњега наврх гора и узвишена изнад хумова, и народи ће се стјецати к њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'И ићи ће многи народи говорећи: ходите, да идемо на гору Господњу и у дом Бога Јаковљева, и учиће нас својим путовима, и ходићемо његовијем стазама; јер ће из Сиона изаћи закон и ријеч Господња из Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'И судиће међу многим народима, и покараће јаке народе надалеко, и они ће расковати мачеве своје на раонике, и копља своја на српове; неће дизати мача народ на народ, нити ће се више учити рату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Него ће сједјети сваки под својом виновом лозом и под смоквом, и неће бити никога да их плаши; јер уста Господа над војскама рекоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Јер ће сви народи ходити сваки у име бога својега; а ми ћемо ходити у име Господа Бога својега увијек и довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'У то вријеме, говори Господ, сабраћу хроме, и скупићу одагнане и којима зло учиних.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'И учинићу од хромијех остатак и од одагнаних силан народ; и Господ ће царовати над њима на гори Сиону отсада и довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'И ти, куло стаду, стијено кћери Сионској, теби ће доћи, доћи ће прва власт, царство кћери Јерусалимске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Зашто вичеш тако јако? нема ли цара у теби? еда ли изгибоше твоји савјетници, те те обузеше болови као породиљу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Мучи се и вичи, кћери Сионска, као породиља, јер ћеш изаћи из града и становаћеш у пољу, и отићи ћеш у Вавилон; ондје ћеш се ослободити, ондје ће те искупити Господ из руку непријатеља твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'А сада се сабраше на те многи народи говорећи: да се оскврни, и да се очи наше нагледају Сиона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Али не знају мисли Господњих, нити разумију намјере његове, јер их је скупио као снопље на гумно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Устани и врси, кћери Сионска, јер ћу ти начинити рог гвозден, и копита ћу ти начинити мједена, те ћеш сатрти многе народе, и посветићу Господу благо њихово и имање њихово Господу све земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Сабери се сада у чете, четнице, опсједи нас, нека бију прутом по образу судију Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'А ти, Витлејеме Ефрато, ако и јеси најмањи међу тисућама Јудинијем, из тебе ће ми изаћи који ће бити господар у Израиљу, којему су изласци од почетка, од вјечнијех времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Зато ће их оставити докле не роди она која ће родити; тада ће се остатак браће његове вратити са синовима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'И стајаће и пашће их силом Господњом, величанством имена Господа Бога својега; и они ће наставати, јер ће он тада бити велик до крајева земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'И он ће бити мир; кад дође Асирац у нашу земљу, и кад ступи у дворе наше, тада ћемо подигнути на њ седам пастира и осам кнезова из народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'И они ће опасти земљу Асирску мачем и земљу Невродову на вратима његовијем; и он ће нас избавити од Асирца кад дође у нашу земљу и кад ступи на међу нашу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'И остатак ће Јаковљев бити усред многих народа као роса од Господа и као ситан дажд по трави, која не чека човјека нити се узда у синове човјечије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'И остатак ће Јаковљев бити међу народима, усред многих народа, као лав међу звијерима шумским, као лавић међу стадима оваца, који кад иде тлачи и растрже и нема никога да избави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Рука ће ти се узвисити над противницима твојим, и сви ће се непријатељи твоји истријебити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'И у оно ћу вријеме, говори Господ, истријебити коње исред тебе и потрћу кола твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'И затрћу градове у твојој земљи, и развалићу сва тврда мјеста твоја;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'И истријебићу врачање из руку твојих, и нећеш имати гатара;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'И истријебићу ликове твоје резане и ступове твоје исред тебе, и нећеш се више клањати дјелу руку својих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'И искоријенићу гајеве твоје исред тебе, и раскопаћу градове твоје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'И извршићу освету с гњевом и љутином на народима који не слушаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Слушајте шта говори Господ: устани, суди се с горама, и нека чују хумови глас твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Слушајте, горе и тврди темељи земаљски, парбу Господњу, јер Господ има парбу с народом својим, и с Израиљем се суди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Народе мој, шта сам ти учинио? и чим сам ти досадио? Одговори ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Јер те изведох из земље Мисирске и искупих из куће ропске и послах пред тобом Мојсија, Арона и Марију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Народе мој, опомени се што науми Валак цар Моавски и што му одговори Валам син Веоров, од Ситима до Галгала шта би, да познаш правду Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Су чим ћу доћи пред Господа да се поклоним Богу вишњему хоћу ли доћи преда њ са жртвама паљеницама? с теоцима од године?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Хоће ли Господу бити миле тисуће овнова? десетине тисућа потока уља? хоћу ли дати првенца својега за пријеступ свој? плод утробе своје за гријех душе своје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Показао ти је, човјече, што је добро; и шта Господ иште од тебе осим да чиниш што је право и да љубиш милост и да ходиш смјерно с Богом својим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Глас Господњи виче граду, и ко је мудар види име твоје; слушајте прут и онога који га је одредио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Није ли јоште у кући безбожниковој благо неправо? и ефа крња, гадна?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Хоће ли ми бити чист у кога су мјерила лажна и у тобоцу пријеварно камење?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Јер су богатуни његови пуни неправде, и становници говоре лаж, и у устима им је језик пријеваран.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Зато ћу те и ја бити да оболиш, пустошићу те за гријехе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Ти ћеш јести, али се нећеш наситити, и падање твоје биће усред тебе; и склањаћеш, али нећеш избавити, и што избавиш предаћу мачу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Ти ћеш сијати, али нећеш жети; ти ћеш циједити маслине, али се нећеш намазати уљем, и маст, али нећеш пити вина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Јер се држе уредбе Амријеве и сва дјела дома Ахавова, и ходите по савјетима њиховијем, да те предам у погибао, и становнике његове у потсмијех, и носићете срамоту народа мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Тешко мени! јер сам као кад се обере љетина, као кад се пабирчи послије брања виноградскога; нема грозда за јело, ранога воћа жели душа моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Неста побожнога са земље и нема правога међу људима, сви вребају крв, сваки лови брата својега мрежом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Да чине зло објема рукама што више могу, иште кнез; и судија суди за плату, и ко је велик говори опачину душе своје, и сплећу је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Најбољи је између њих као трн, најправији је гори од трњака; дан стражара твојих, похођење твоје, дође, сада ће се смести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Не вјерујте пријатељу, не ослањајте се на вођа; од оне која ти на крилу лежи, чувај врата уста својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Јер син грди оца, кћи устаје на матер своју, снаха на свекрву своју, непријатељи су човјеку домашњи његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Али ја ћу Господа погледати, чекаћу Бога спасења својега; услишиће ме Бог мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Немој ми се радовати, непријатељице моја; ако падох, устаћу; ако сједим у мраку, Господ ће ми бити видјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Подносићу гњев Господњи, јер му згријеших, док не расправи парбу моју и да ми правицу; извешће ме на видјело, видјећу правду његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Непријатељица ће моја видјети, и срам ће је покрити, која ми говори: гдје је Господ Бог твој? очи ће је моје видјети; сада ће се она погазити као блато на улицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'У које се вријеме сазидају зидови твоји, у то ће вријеме отићи заповијест надалеко;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'У то ће вријеме долазити к теби од Асирске до тврдијех градова, и од тврдијех градова до ријеке, и од мора до мора, и од горе до горе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'А земља ће бити пуста са становника својих, за плод дјела њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Паси народ свој с палицом својом, стадо нашљедства својега, које живи осамљено у шуми, усред Кармила; нека пасу по Васану и по Галаду, као у старо вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Као у вријеме кад си изашао из земље Мисирске показаћу му чудеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Народи ће видјети, и постидјеће се од све силе своје; метнуће руку на уста, уши ће им заглухнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Лизаће прах као змија; као бубине земаљске дркћући ижљешће из рупа својих; притрчаће уплашени ка Господу Богу нашему, и тебе ће се бојати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Ко је Бог као ти? који прашта безакоње и пролази пријеступе остатку од нашљедства својега, не држи довијека гњева својега, јер му је мила милост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Опет ће се смиловати на нас; погазиће наша безакоња; бацићеш у дубине морске све гријехе њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Показаћеш истину Јакову, милост Авраму, како си се заклео оцима нашим у старо вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Бреме Ниневији; књига од утваре Наума Елкошанина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Бог је ревнитељ и Господ је осветник; осветник је Господ и гњеви се; Господ се свети противницима својим, и држи гњев према непријатељима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Господ је спор на гњев и велике је моћи; али никако не правда кривца; пут је Господњи у вихору и бури, и облаци су прах од ногу његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Запрећује мору и исушује га, и све ријеке исушује, вене Васан и Кармил, и цвијет Васански вене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Горе се тресу од њега, и хумови се растапају, а земља гори пред њим и васиљена и све што живи у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Пред гњевом његовијем ко ће се одржати? и ко ће се опрети јарости гњева његова? јарост се његова излијева као огањ, и стијене се распадају пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Добар је Господ, град је у невољи, и познаје оне који се уздају у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Али ће силном поплавом учинити крај мјесту њезину, и тама ће гонити непријатеље његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Шта смишљате Господу? он ће учинити крај; неће се двапута подигнути погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Јер као трње сплетени и као од вина пијани прождријеће се као суха слама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Из тебе је изашао који смишља зло Господу, савјетник неваљао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Овако вели Господ: ако и јесу у сили и много их има, опет ће се исјећи и проћи. Мучио сам те, нећу те више мучити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Него ћу сада сломити јарам његов с тебе, и покидаћу твоје окове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Али за тебе заповједи Господ да се не сије више име твоје; из дома богова твојих истријебићу ликове резане и ливене; начинићу ти од њега гроб кад будеш презрен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Ето, на горама ноге онога који носи добре гласе, који оглашује мир. Празнуј, Јуда, своје празнике, испуњај завјете своје, јер зликовац неће више пролазити по теби; сасвијем се затро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Изађе затирач на те, чувај град, пази на пут, утврди бедра, укријепи се добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Јер Господ поврати славу Јаковљеву као славу Израиљеву, јер их пустошници опустошише и лозе им потрше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Штит је јунака његовијех црвен, војници су у скерлету; кола ће му бити као запаљени лучеви на дан кад се уврста, и јеле ће се љуљати страшно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Кола ће праскати по улицама и ударати једна о друга по путовима, биће као лучеви, и трчаће као муње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Помињаће јунаке своје, а они ће падати идући, похитјеће к зидовима његовијем, и заклон ће бити готов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Врата ће се ријекама отворити, и двор ће се развалити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'И која стоји, заробиће се и одвешће се, дјевојке њезине пратиће је уздишући као голубице, бијући се у прси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Ниневија бијаше као језеро водено откако је; али бјеже. Станите, станите. Али се нико не обзире.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Грабите сребро, грабите злато; благу нема краја, мноштво је свакојаких драгих заклада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Испразни се, и огоље, и опустје; и срце се растопи, кољена ударају једна о друго, и бол је у свијем бедрима, и лица су свјема поцрњела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Гдје је ложа лавовима и пасиште лавићима, куда иђаше лав и лавица и лавић, и никога не бјеше да плаши?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Лав ловљаше својим лавићима доста, и дављаше лавицама својим, и пуњаше пећине своје лова и ложе своје грабежа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Ево ме на те, говори Господ над војскама, и попалићу кола твоја у дим, и мач ће прождријети лавиће твоје, и истријебићу са земље грабеж твој, и неће се чути глас посланика твојих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Тешко граду крвничком, вас је пун лажи и отимања, грабеж не избива из њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Пуцају бичеви, и точкови праште, и коњи топоћу, и кола скачу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Коњаници поскакују, и мачеви се сјају, и копља сијевају, и мноштво је побијенијех и сила мртвијех тјелеса, нема броја мртвацима, и пада се преко мртваца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'За мноштво курварства љупке курве, вјеште бајачице, која продаје народе својим курвањем и племена врачањем својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Ево ме на те, говори Господ над војскама, и узгрнућу ти скуте твоје на лице, и показаћу народима голотињу твоју и царствима срамоту твоју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'И бацићу на тебе гадове и наружићу те, и начинићу од тебе углед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'И ко те год види, бјежаће од тебе, и говориће: опустје Ниневија; ко ће је жалити? гдје ћу тражити оне који би те тјешили?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Јеси ли боља од Но-Амона, који лежаше међу ријекама, опточен водом, којему предња кула бјеше море и зидови му бјеху море?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Јачина му бјеше Хуска земља и Мисир и народи без броја; Футеји и Ливеји бјеху ти помоћници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'И он би пресељен, отиде у ропство, и дјеца његова бише размрскана по угловима свијех улица; и за главаре његове бацаше ждријеб, и сви властељи његови бише оковани у пута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'И ти ћеш се опити и крићеш се, и ти ћеш тражити заклон од непријатеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Сви ће градови твоји бити као смокве с ранијем родом; кад се тресну, падају у уста ономе ко хоће да једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Ето, народ су ти жене усред тебе; непријатељима ће твојим бити широм отворена врата од земље твоје, огањ ће прождријети пријеворнице твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Нахватај себи воде за опсаду, утврди ограде своје; уђи у као и угази блато, оправи пећ за опеке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Ондје ће те прождријети огањ, мач ће те исјећи, изјешће те као хрушт; нека вас је много као хруштева, нека вас је много као скакаваца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Имаш трговаца више него што је звијезда на небу; хруштеви падоше, па одлетјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Главари су твоји као скакавци и војводе твоје као велики скакавци, који падају по плотовима кад је студено, а кад сунце гране, одлијећу, и мјесто им се не познаје гдје бјеху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Задријемаше твоји пастири, царе Асирски, полијегаше јунаци твоји, народ се твој распрша по горама, и нема никога да их збере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Нема лијека полому твом, љута је рана твоја; ко год чује глас о теби, пљескаће рукама над тобом, јер кога није стизала злоћа твоја једнако?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Бреме које видје пророк Авакум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Докле ћу, Господе, вапити а ти нећеш да чујеш? докле ћу ти викати: насиље! а ти нећеш да избавиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Зашто пушташ да видим безакоње, и да гледам муку и грабеж и насиље пред собом, и како подижу свађу и распру?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Зато се оставља закон, и суд не излази нигда, јер безбожник оптјече праведника, зато суд излази изопачен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Погледајте по народима и видите, и чудите се и дивите се, јер ћу учинити дјело у ваше дане којега нећете вјеровати кад се стане приповиједати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Јер, ево, ја ћу подигнути Халдејце, народ љут и нагао, који ће ићи по земљи широм да освоји насеља која нијесу његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Жесток је и страшан, суд његов и власт његова од њега излази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Коњи ће му бити бржи од рисова и љући од вукова увече, велико ће мноштво бити коњика његовијех, и идући издалека коњици његови долетјеће као орао кад хити на лов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Сви ће доћи на грабеж, с лица ће бити као источни вјетар, покупиће робље као пијесак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'И царевима ће се ругати и кнезови ће им бити потсмијех, смијаће се сваком граду, насуће земље, и узеће га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Тада ће му се промијенити дух, проћи ће и скривиће; та ће му сила његова бити од бога његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Нијеси ли ти од вијека, Господе Боже мој, свече мој? нећемо умријети; ти си га, Господе, одредио за суд; и утврдио си га, стијено, за карање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Чисте су очи твоје да не можеш гледати зла, и безакоња не можеш гледати; зашто гледаш безаконике? мучиш, кад безбожник прождире правијега од себе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'И хоћеш ли оставити људе као рибе морске, као бубине, које немају господара?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Извлачи их све удицом, хвата их у мрежу своју, и згрће их пређом својом, зато се весели и радује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Зато приноси жртву својој мрежи, и кади својој пређи; јер је тијем дио његов претио и храна му изабрана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Хоће ли зато извлачити мрежу своју и једнако убијати народе немилице?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'На стражи својој стадох, и стајах на кули, и мотрах да видим шта ће ми рећи и шта бих одговорио ономе који ме кораше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'И одговори ми Господ и рече: пиши утвару, и да буде разговијетно на плочама да се лако чита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Јер ће још бити утвара до одређенога времена, и говориће шта ће бити до пошљетка и неће слагати; ако оклијева, чекај је, јер ће зацијело доћи, и неће одоцнити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Гле, ко се поноси, његова душа није права у њему; а праведник ће од вјере своје жив бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'А како вино вара, таки је човјек охол, нити остаје у стану; јер раширује дух свој као гроб, и као смрт је, која се не може наситити и збира к себи све народе и скупља к себи сва племена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Неће ли га сви они узети у причу и у загонетке, и рећи: тешко оном који умножава што није његово! докле ће? и који трпа на се густо блато.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Неће ли наједанпут устати они који ће те гристи? и неће ли се пробудити они који ће те растрзати, и којима ћеш бити грабеж?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Што си ти оплијенио многе народе, тебе ће оплијенити сав остатак од народа, за крв људску и за насиље учињено земљи, граду и свјема који живе у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Тешко ономе који се лакоми на гадан добитак кући својој, да постави гнијездо своје на високом мјесту и сачува се ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Смислио си срамоту кући својој да затреш многе народе, и огријешио си се о своју душу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Јер ће камен из зида викати, и чвор из дрвета свједочиће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Тешко ономе који гради град крвљу и оснива град неправдом!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Гле, није ли од Господа над војскама да људи раде за огањ и народи се труде ни за што?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Јер ће се земља напунити познања славе Господње као што је море пуно воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Тешко ономе који поји ближњега својега, додаје мијех свој да би га опојио и гледао му голотињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Наситићеш се срамоте мјесто славе, пиј и ти, и откриј голотињу своју; доћи ће к теби чаша у десници Господњој, и бљувотина ће срамна бити на слави твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Јер насиље учињено Ливану покриће те и пустош међу звијерјем која га је плашила, за крв људску и насиље учињено земљи, граду и свјема који живе у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Шта помаже резан лик што га изреза умјетник његов? шта ливен лик и учитељ лажи, те се умјетник узда у дјело своје градећи нијеме идоле?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Тешко ономе који говори дрвету: прени се! и нијему камену: пробуди се! Хоће ли он учити? Ето, обложен је златом и сребром, а нема духа у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'А Господ је у светој цркви својој; мучи пред њим, сва земљо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Молитва пророка Авакума; за пјевање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Господе, чух ријеч твоју, и уплаших се; Господе, дјело своје усред година сачувај у животу, усред година објави га, у гњеву сјети се милости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Бог дође од Темана и светац с горе Фарана; слава његова покри небеса и земља се напуни хвале његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Свјетлост му бијаше као сунце, зраци излажаху му из руку, и ондје бјеше сакривена сила његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Пред њим иђаше помор, и живо угљевље иђаше испод ногу његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Стаде, и измјери земљу, погледа и разметну народе, распадоше се вјечне горе, слегоше се хумови вјечни; путови су му вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Видјех шаторе Етиопске у муци, устрепташе завјеси земљи Мадијанској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Еда ли се на ријеке разгњеви Господ? еда ли се на ријеке распали гњев твој? на море јарост твоја, кад си појездио на коњма својим и на колима својим за спасење?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Помоли се лук твој као што си се заклео племенима; раздро си земљу за ријеке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Видјеше те горе и уздркташе, поводањ навали; бездана пусти глас свој, увис подиже руке своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Сунце и мјесец стадоше у стану свом, идоше према свјетлости твоје стријеле, према сијевању сјајнога копља твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Срдито си ишао по земљи, гњевно си газио народе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Изашао си на спасење народу својему, на спасење с помазаником својим; размрскао си главу кући безбожничкој до врата откривши темељ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Његовијем копљима пробио си главу селима његовијем кад наваљиваху као вихор да ме разаспу, радоваху се као да ће прождријети сиромаха у потаји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Ишао си по мору на коњма својим, по гомили многе воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Чух, и утроба се моја усколеба, усне ми уздркташе на глас, у кости ми уђе трухлеж, и устресох се на мјесту свом; како ћу почивати у дан невоље, кад дође на народ који ће га опустошити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Јер смоква неће цвасти, нити ће бити рода на лози виновој; род ће маслинов преварити, и њиве неће дати хране, оваца ће нестати из тора, и говеда неће бити у обору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Али ћу се ја радовати у Господу, веселићу се у Богу спасења својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Господ је Господ сила моја, и даће ми ноге као у кошуте, и водиће ме по висинама мојим. Начелнику пјевачком уз жице моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Ријеч Господња која дође Софонији сину Хусија сина Годолије сина Амарије сина Језекијина, за времена Јосије сина Амонова, цара Јудина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Све ћу узети са земље, говори Господ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Узећу људе и стоку, узећу птице небеске и рибе морске и саблазни с безбожницима, и истријебићу људе са земље, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Јер ћу махнути руком својом на Јуду и на све становнике Јерусалимске, и истријебићу из мјеста овога остатак Валов и име свештеника идолских с другим свештеницима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'И оне који се клањају на крововима војсци небеској и који се клањају и куну се Господом и који се куну Мелхомом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'И оне који се одвраћају од Господа и који не траже Господа нити питају за њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Мучи пред Господом Господом, јер је близу дан Господњи, јер је Господ приготовио жртву и позвао своје званице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'И у дан жртве Господње походићу кнезове и царске синове и све који носе туђинско одијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'И походићу у тај дан све који скачу преко прага, који пуне кућу господара својих грабежем и пријеваром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'И у тај ће дан, вели Господ, бити вика од рибљих врата, и јаук с друге стране, и полом велик с хумова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Ридајте који живите у Мактесу, јер изгибе сав народ трговачки, истријебише се сви који носе сребро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'И у то ћу вријеме разгледати Јерусалим са жишцима, и походићу људе који леже на својој дрождини, који говоре у срцу свом: Господ не чини ни добро ни зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'И благо ће се њихово разграбити и куће њихове опустошити; граде куће, али неће сједјети у њима; и саде винограде, али неће пити вина из њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Близу је велики дан Господњи, близу је и иде врло брзо; глас ће бити дана Господњега, горко ће тада викати јунак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Тај је дан дан, када ће бити гњев, дан, када ће бити туга и мука, дан, када ће бити пустошење и затирање, дан, када ће бити мрак и тама, дан, када ће бити облак и магла,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Дан, када ће бити трубљење и поклич на тврде градове и на високе углове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'И притијеснићу људе, те ће ићи као слијепи, јер згријешише Господу; и крв ће се њихова просути као прах и тјелеса њихова као гној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Ни сребро њихово ни злато њихово неће их моћи избавити у дан гњева Господњега; и сву ће земљу прождријети огањ ревности његове; јер ће брзо учинити крај свјема становницима земаљским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Саберите се, саберите се, народе немили,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Док није изашао суд, и дан прошао као пљева, док није дошао на вас љути гњев Господњи, док није дошао на вас дан гњева Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Тражите Господа сви који сте кротки у земљи, који чините што је наредио; тражите правду, тражите кротост, еда бисте се сакрили на дан гњева Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Јер ће се Газа оставити и Аскалон ће опустјети; Азот ће се одагнати у подне и Акарон ће се искоријенити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Тешко онима који живе по бреговима морским, народу Херетејском: ријеч је Господња на вас, Ханане, земљо Филистејска, ја ћу те затрти да не буде становника у теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'И брегови ће морски бити станови и јаме пастирске и торови за стада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'И тај ће крај бити остатку дома Јудина; ондје ће пасти; у домовима ће Аскалонским лијегати увече; јер ће их походити Господ Бог њихов и повратити робље њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Чуо сам руг Моавов и укоре синова Амоновијех којима ружише мој народ, и раширише се преко међа њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Зато, тако ја био жив, говори Господ над војскама, Бог Израиљев, Моав ће бити као Содом и синови Амонови као Гомор, мјесто копривама, и сланица и вјечна пустош: остатак народа мојега оплијениће их, и који остану од народа мојега наслиједиће их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'То ће им бити за поноситост њихову; јер ружише народ Господа над војскама и подизаше се на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Страшан ће им бити Господ, јер ће истријебити све богове земаљске, и њему ће се клањати сваки из својега мјеста, сва острва народна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'И ви, Етиопљани, бићете побијени мачем мојим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'И дигнуће руку своју на сјевер, и затрће Асириску, и Ниневију ће опустити да буде суха као пустиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'И у њој ће лежати стада, свакојако звијерје између народа, и гем и ћук ноћиваће на довратницима њезинијем; гласом ће пјевати на прозорима; пустош ће бити на праговима; јер ће се поскидати кедровина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Таки ће бити весели град, који сједи без бриге, који говори у срцу свом: ја сам, и осим мене нема другога. Како опустје! поста ложа звијерју! Ко год прође мимо њ звиждаће и махати руком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Тешко граду одметничком и оскврњеном, насилничком!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Не слуша гласа, не прима наука, не узда се у Господа, не приступа к Богу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Кнезови су му у њему лавови који ричу; судије су му вуци вечерњи, који не глођу кости до јутра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Пророци су му хвалише, варалице; свештеници његови скврне светињу, изврћу закон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Господ је праведан усред њега, не чини неправде, свако јутро износи суд свој на видјело, не изостаје, али безбожник не зна за стид.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Истријебих народе, куле им се разорише, улице им опустих, те нико не пролази; градови им се раскопаше, да нема никога, нема становника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Рекох: побојаћеш ме се, примићеш наук; неће му се затрти стан ничим су чим бих га походио; али они уранише те покварише сва дјела своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Зато чекајте ме, говори Господ, до дана кад ћу се подигнути на плијен; јер је суд мој да саберем народе и покупим царства, да излијем на њих гњев свој, сву жестину јарости своје, јер ће огањ ревности моје прождријети сву земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Јер ћу тада промијенити народима усне, те ће бити чисте, да би сви призивали име Господње и служили му сложнијем раменима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Испреко ријека Хуских који се мени моле, расијани моји, донијеће ми даре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Тада се нећеш више стидјети ниједнога својих дјела, којима си ми згријешио; јер ћу онда узети из тебе оне који се хвале славом твојом, и нећеш се више величати на светој гори мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'И оставићу у теби народ невољан и сиромашан, и они ће се уздати у име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Остатак Израиљев неће чинити безакоња нити ће говорити лажи, нити ће се наћи у устима њиховијем језик пријеваран; него ће пасти и лежати и неће бити никога да их плаши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Пјевај, кћери Сионска; кликуј, Израиљу; радуј се и весели се из свега срца, кћери Јерусалимска!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Уклони Господ судове твоје, одврати непријатеље твоје; цар Израиљев Господ усред тебе је, нећеш се више бојати зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'У онај дан рећи ће се граду Јерусалиму: не бој се; Сиону: немој да ти клону руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Господ Бог твој, који је усред тебе, силни, спашће те; радоваће ти се веома, умириће се у љубави својој, веселиће се тебе ради пјевајући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Који туже за празницима, сабраћу их, који су из тебе, ради тешке срамоте која је на теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Гле, уништићу у оно вријеме све који те муче, и избавићу хроме и сабрати одагнане, и добавићу им хвалу и славу по свој земљи, гдје су били под срамотом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'У оно вријеме довешћу вас, у оно вријеме сабраћу вас; јер ћу вам добавити славу и хвалу по свијем народима на земљи, кад повратим робље ваше пред вашим очима, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Друге године цара Дарија шестога мјесеца првога дана дође ријеч Господња преко Агеја пророка Зоровавељу сину Салатилову, управитељу Јудејском, и Исусу сину Јоседекову, поглавару свештеничком, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Овако вели Господ над војскама говорећи: тај народ говори: још није дошло вријеме, вријеме да се сазида дом Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Зато дође ријеч Господња преко Агеја пророка говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Је ли вама вријеме да сједите у кућама својим обложенијем даскама, а овај је дом пуст?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Зато сада овако вели Господ над војскама: узмите на ум путове своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Сијете много, а увозите мало; једете, а не бивате сити; пијете, а не напијате се; одијевате се, а ниједан не може да се згрије; и који заслужује новце, меће их у продрт тоболац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Овако вели Господ над војскама: узмите на ум путове своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Идите на гору, и донесите дрва, те зидајте дом; и биће ми мило, и прославићу се, вели Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Изгледате много, а ето мало; и што унесете у кућу, ја раздухам; зашто? вели Господ над војскама; зато што је дом мој пуст, а ви сваки трчите за свој дом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Зато се затвори небо над вама да нема росе, и земља се затвори да нема рода њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'И дозвах сушу на земљу, и на горе, и на жито и на вино и на уље и на све што земља рађа, и на људе и на стоку и на сваки рад ручни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'И послуша Зоровавељ син Салатилов и Исус син Јоседеков, поглавар свештенички, и сав остатак народни глас Господа Бога својега и ријечи пророка Агеја, како га посла Господ Бог њихов, и побоја се народ Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'И говори Агеј, посланик Господњи, народу као што га посла Господ, и рече: ја сам с вама, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'И Господ подиже дух Зоровавељу сину Салатилову, управитељу Јудејском, и дух Исусу сину Јоседекову, поглавару свештеничком, и дух свему остатку народном, те дођоше и радише у дому Господа над војскама, Бога својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'Двадесет четвртога дана шестога мјесеца, друге године цара Дарија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Седмога мјесеца двадесет првога дана дође ријеч Господња преко Агеја пророка говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Кажи сада Зоровавељу сину Салатилову, управитељу Јудејском, и Исусу сину Јоседекову, поглавару свештеничком, и остатку народном говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Ко је међу вама остао који је видио овај дом у првој слави његовој? а какав ви сада видите? није ли према оном као ништа у вашим очима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Него сада буди храбар, Зоровавељу, говори Господ, и буди храбар Исусе сине Јоседеков, поглавару свештенички, и буди храбар сав народе земаљски, говори Господ, и радите; јер сам ја с вама, говори Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'По ријечи којом сам учинио завјет с вама кад изидосте из Мисира, дух ће мој стајати међу вама, не бојте се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Јер овако вели Господ над војскама: још једном, домало, и ја ћу потрести небеса и земљу и море и суху земљу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'И потрешћу све народе, и доћи ће изабрани из свијех народа, и напунићу овај дом славе, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Моје је сребро и моје је злато, говори Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Слава ће овога дома пошљедњега бити већа него онога првога, вели Господ над војскама; и поставићу мир на овом мјесту, говори Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Двадесет четвртога дана деветога мјесеца друге године Даријеве дође ријеч Господња преко Агеја пророка говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Овако вели Господ над војскама: упитај свештенике за закон, и реци:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Гле, ако би ко носио свето месо у скуту од хаљине своје, или би се скутом својим дотакао хљеба или варива или вина или уља или какога год јела, би ли се осветио? А свештеници одговорише и рекоше: не.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Потом рече Агеј: ако би се ко нечист од мртваца дотакао чега тога, хоће ли бити нечисто? А свештеници одговорише и рекоше: биће нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Тада Агеј одговори и рече: таки је тај народ и таки су ти људи преда мном, говори Господ, и тако је све дјело руку њиховијех, и што год приносе тамо, нечисто је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'А сада узмите на ум, од овога дана назад, прије него се положи камен на камен у цркви Господњој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Прије тога кад ко дође ка гомили од двадесет мјера, бјеше десет; кад дође ка каци да добије педесет вједара из каце, бјеше двадесет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Бих вас сушом и медљиком и градом, свако дјело руку ваших; али се ви не обратисте к мени, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Узмите на ум, од тога дана назад, од дана двадесет четвртога мјесеца деветога, од дана кад се основа црква Господња, узмите на ум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Има ли јоште сјемена у житници? ни винова лоза ни смоква ни шипак ни маслина још не роди; од овога ћу дана благословити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Потом дође ријеч Господња други пут Агеју двадесет четвртога дана мјесеца говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Кажи Зоровавељу управитељу Јудејском, и реци: ја ћу потрести небо и земљу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'И превалићу пријесто царствима, и сатрћу силу царствима народнијем, превалићу кола и оне који сједе на њима, и попадаће коњи и коњици, сваки од мача брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'У то вријеме, говори Господ над војскама, узећу тебе, Зоровавељу, сине Салатилов, слуго мој, говори Господ, и поставићу те као печат; јер сам те изабрао, говори Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Осмога мјесеца друге године Даријеве, дође ријеч Господња пророку Захарији сину Варахије сина Идова говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Господ се врло разгњеви на оце ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Зато им реци: овако вели Господ над војскама: вратите се к мени, говори Господ над војскама, и ја ћу се вратити к вама, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Не будите као оци ваши, којима викаху пређашњи пророци говорећи: овако вели Господ над војскама: вратите се са злијех путова својих и од злијех дјела својих; али не послушаше нити пазише на ме, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Оци ваши гдје су? и ти пророци живе ли довијека?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Али ријечи моје и уредбе моје које заповиједах слугама својим пророцима не стигоше ли оце ваше? те се они обратише и рекоше: како Господ над војскама бјеше намислио учинити нам према путовима нашим и по дјелима нашим, тако нам учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Двадесет четвртога дана једанаестога мјесеца, а то је мјесец Сават, друге године Даријеве, дође ријеч Господња пророку Захарији сину Варахије сина Идова говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Видјех ноћу, а то човјек јахаше на коњу риђу, и стајаше међу миртама које бијаху у долу, а за њим бијаху коњи риђи, шарени и бијели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'И рекох: шта је ово, господару мој? А анђео који говораше са мном рече ми: ја ћу ти показати што је ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Тада човјек који стајаше међу миртама проговори и рече: ово су које посла Господ да облазе земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'И они проговорише анђелу Господњему који стајаше међу миртама, и рекоше: ми обидосмо земљу, и гле, сва земља почива и мирна је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Тада анђео Господњи одговори и рече: Господе над војскама, кад ћеш се већ смиловати Јерусалиму и градовима Јудинијем, на које се гњевиш већ седамдесет година?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'А Господ одговори анђелу који говораше са мном, добријем ријечима, милијем ријечима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'И рече ми анђео који говораше са мном: вичи и реци: овако вели Господ над војскама: ревнујем за Јерусалим и за Сион веома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'И гњевим се силно на народе безбрижне, јер се мало разгњевих а они помогоше на зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Зато овако вели Господ: обратих се к Јерусалиму милошћу, дом ће се мој опет сазидати у њему, говори Господ над војскама, и уже ће се затегнуту преко Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Још вичи и реци: овако вели Господ над војскама: опет ће градови моји обиловати добром, и Господ ће опет утјешити Сион и опет ће изабрати Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Тада подигох очи своје и видјех, и гле, четири рога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'И рекох анђелу који говораше са мном: што је то? А он ми рече: то су рогови који разметнуше Јуду, Израиља и Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Потом показа ми Господ четири ковача.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'И рекох: шта су ти дошли да раде? А он одговори и рече: оно су рогови који разметнуше Јуду да нико не подиже главе; а ови дођоше да их уплаше, да одбију рогове народима, који подигоше рог на земљу Јудину да је разметну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Опет подигох очи своје и видјех, и гле, човјек, и у руци му уже мјерачко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'И рекох: куда идеш? А он ми рече: да измјерим Јерусалим да видим колика му је ширина и колика му је дужина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'И гле, анђео који говораше са мном изиде, и други анђео изиде му на сусрет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'И рече му: трчи, говори оном младићу и реци: Јерусалимљани ће се населити по селима ради мноштва људи и стоке што ће бити у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'И ја ћу му, говори Господ, бити зид огњен унаоколо и бићу за славу усред њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Еј, еј, бјежите из земље сјеверне, говори Господ, јер вас разасух у четири вјетра небеска, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Еј Сионе, који сједиш код кћери Вавилонске, избави се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Јер овако вели Господ над војскама: за славом посла ме к народима, који вас оплијенише; јер ко тиче у вас, тиче у зјеницу ока његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Јер ево ја ћу махнути руком својом на њих, и биће плијен слугама својим, и познаћете да ме је послао Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Пјевај и весели се, кћери Сионска, јер ево ја идем и наставаћу усред тебе, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'И многи ће се народи прилијепити ка Господу у тај дан, и биће ми народ, и ја ћу наставати усред тебе, и познаћеш да ме је послао к теби Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'И Господ ће наслиједити Јуду, свој дио, у земљи светој, и опет ће изабрати Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Нека мучи свако тијело пред Господом, јер уста из светога стана својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Послије ми показа Исуса поглавара свештеничкога, који стајаше пред анђелом Господњим, и Сотону, који му стајаше с десне стране да га пре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'А Господ рече Сотони: Господ да те укори, Сотоно, Господ да те укори, који изабра Јерусалим. Није ли он главња истргнута из огња?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'А Исус бијаше обучен у хаљине прљаве, и стајаше пред анђелом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'А он проговори и рече онима који стајаху пред њим: скините с њега те прљаве хаљине. И рече му: види, узех с тебе безакоње твоје, и обукох ти нове хаљине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'И рекох му: нека му метну чисту капу на главу. И метнуше му чисту капу на главу, и обукоше му хаљине; а анђео Господњи стајаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'И анђео Господњи засвједочи Исусу говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Овако вели Господ над војскама: ако узидеш мојим путовима, и ако уздржиш што сам наредио да се држи, тада ћеш ти судити дому мојему и чуваћеш тријемове моје, и даћу ти да ходиш међу овима што стоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Чуј, Исусе поглавару свештенички, ти и другови твоји што сједе пред тобом, јер су ти људи чудо; ево, ја ћу довести слугу својега, клицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Јер гле, камен који метнух пред Исуса, на том је једном камену седам очију; гле, ја ћу га отесати, говори Господ над војскама, и узећу безакоње те земље у један дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'У тај дан, говори Господ над војскама, зваћете сваки ближњега својега под винову лозу и под смокву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Потом врати се анђео који ми говораше, и пробуди ме као човјека који се буди ода сна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'И рече ми: шта видиш? А ја рекох: видим, ето свијећњак сав од злата, и горе на њему чаша, и седам жижака његовијех на њему, и седам лијевака за седам жижака што су горе на њему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'И двије маслине уза њ, једна с десне стране чаши а једна с лијеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'И проговорих анђелу који говораше са мном, и рекох: шта је то, господару мој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'А анђео који говораше са мном одговори и рече ми: зар не знаш што је то? И рекох: не, господару мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'А он одговори и рече ми говорећи: то је ријеч Господња Зоровавељу: не силом ни крјепошћу него духом мојим, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Што си ти, горо велика, пред Зоровавељем? равница; и он ће изнијети највиши камен, с усклицима: милост, милост њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'И дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Руке Зорововељеве основаше овај дом, руке ће његове и довршити, и познаћеш да ме је Господ над војскама послао к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Јер ко је презрео дан малијех ствари? јер ће се радовати кад виде камен мјерачки у руци Зоровавељу онијех седам очију Господњих које прелазе сву земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Тада одговарајући рекох му: што су оне двије маслине с десне стране свијећњаку и с лијеве?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'И опет проговорих и рекох му: што су оне двије гранчице маслинове, што су међу два лијевка златна, који точе злато?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'И рече ми говорећи: зар не знаш што је то? А ја рекох: не, господару мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Тада рече: то су двије маслине које стоје код Господа све земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Потом опет подигох очи своје и видјех, а то књига лећаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'И он ми рече: шта видиш? А ја рекох: видим књигу гдје лети, дужина јој двадесет лаката а ширина десет лаката.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Тада ми рече: то је проклетство које изађе на сву земљу, јер сваки који краде истријебиће се по њој с једне стране, и који се год куне криво истријебиће се по њој с друге стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Ја ћу је пустити, говори Господ над војскама, те ће доћи на кућу лупежу и на кућу ономе који се куне мојим именом криво, и стајаће му усред куће и сатрће је, и дрвље јој и камење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Потом изиде анђео који говораше са мном, и рече ми: подигни очи своје и види шта је ово што излази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'А ја рекох: шта је? А он рече: то је ефа што излази. И рече: то им је око по свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'И гле, подизаше се таланат олова, и једна жена сијеђаше усред ефе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'И он рече: то је безбожност. И врже је усред ефе, и врже онај комад олова озго на ждријело јој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'И подигох очи своје и видјех, а то двије жене излажаху, и вјетар им бијаше под крилима, а крила им бијаху као у роде, и дигоше ефу међу земљу и небо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'И рекох анђелу који говораше са мном: куда оне носе ефу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'А он ми рече: да јој начине кућу у земљи Сенару; и ондје ће се намјестити и поставити на своје подножје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Потом опет подигох очи своје, и видјех, а то четвора кола излажаху између двије горе, а те горе бијаху од мједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'У првијем колима бјеху коњи риђи, а у другим колима коњи врани,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'А у трећим колима коњи бијели, а у четвртијем колима коњи шарени, јаки.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'И проговорив рекох анђелу који говораше са мном: шта је то, господару мој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'А анђео одговори и рече ми: то су четири вјетра небеска, који излазе испред Господа све земље, гдје стајаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Коњи врани што су у једнијем, они иду у сјеверну земљу; а бијели иду за њима; а шарени иду у земљу јужну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'И јаки изашавши шћаху да иду и пролазе земљу; и рече: идите пролазите земљу. И стадоше пролазити земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Тада ме зовну, и рече ми: види, који отидоше у земљу сјеверну, умирише дух мој у земљи сјеверној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Потом ми дође ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Узми од робља, од Хелдаја и од Товије и од Једаје, који дођоше из Вавилонске, па дођи истога дана и уђи у дом Јосије сина Софонијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Узми сребра и злата, и начини вијенце, и метни на главу Исусу сину Јоседекову, поглавару свештеничком,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'И реци му говорећи: овако вели Господ над војскама: ево човјека, којему је име клица, која ће клијати с мјеста свога и саградиће цркву Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Јер ће он саградити цркву Господњу, и носиће славу, и сједјеће и владати на свом пријестолу, и биће свештеник на пријестолу свом, и свјет мирни биће међу објема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'И вијенци нека буду Елему и Товији и Једаји и Хену сину Софонијину за спомен у цркви Господњој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'И који су далеко, доћи ће и градиће цркву Господњу, и познаћете да ме је Господ над војскама послао к вама. И то ће бити ако узаслушате глас Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Потом четврте године цара Дарија дође ријеч Господња Захарији четвртога дана деветога мјесеца, Хаслева,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Кад послаше у дом Божји Сарасара и Регемелеха и људе своје да моле Господа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'И да говоре свештеницима, који бијаху у дому Господа над војскама, и пророцима, и реку: хоћемо ли плакати петога мјесеца одвајајући се, како чинисмо већ толико година?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'И дође ми ријеч Господња говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Кажи свему народу земаљском и свештеницима, и реци: кад постисте и тужисте петога и седмога мјесеца за седамдесет година, еда ли мени постисте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'А кад једете и пијете, не једете ли и не пијете ли сами?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Нијесу ли то ријечи које је Господ прогласио преко пређашњих пророка, кад Јерусалим бијаше насељен и миран и градови његови око њега, и кад бијаше насељен јужни крај и равница?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Дође ријеч Господња Захарији говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Овако говори Господ над војскама: судите право и будите милостиви и жалостиви један другом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'И не чините криво удовици ни сироти, иностранцу ни сиромаху, и не мислите зло један другом у срцу свом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Али не хтјеше слушати, и узмакоше раменом натраг, и затискоше уши своје да не чују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'И срцем својим отврднуше као дијаманат да не чују закона и ријечи које сла Господ над војскама духом својим преко пророка пређашњих; зато дође велик гњев од Господа над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Зато као што он вика а они не слушаше, тако и они викаше а ја их не слушах, говори Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Него их разметнух вихором по свијем народима, којих не познаваше, и земља опустје иза њих да нико у њу не дохођаше нити се из ње враћаше, и обратише милу земљу у пустош.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Опет дође ријеч Господа над војскама говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Овако вели Господ над војскама: ревнујем за Сион великом ревношћу, и великим гњевом ревнујем за њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Овако вели Господ: вратих се у Сион и населих се усред Јерусалима, и Јерусалим ће се звати град истинити, и гора Господа над војскама света гора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Овако вели Господ над војскама: опет ће сједјети старци и старице по улицама Јерусалимским, сватко са штаком у руци од велике старости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'И улице ће градске бити пуне дјетића и дјевојака, које ће се играти по улицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Овако вели Господ над војскама: ако је чудно у очима остатку тога народа у ово вријеме, еда ли ће бити чудно и у мојим очима? говори Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Овако вели Господ над војскама: ево, ја ћу избавити свој народ из земље источне и земље западне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'И довешћу их, и они ће наставати усред Јерусалима, и биће ми народ и ја ћу им бити Бог, истином и правдом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Овако вели Господ над војскама: нека вам се укријепе руке који слушате у ово вријеме ове ријечи из уста пророчких од дана кад се основа дом Господа над војскама да се сазида црква.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Јер прије тијех дана не бјеше плате ни за човјека ни за живинче, нити бјеше мира од непријатеља ни ономе који одлажаше ни ономе који долажаше и пустих све људе једнога на другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'А сада нећу бити као прије остатку тога народа, говори Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Него ће усјев бити миран, винова ће лоза носити плод свој, и земља ће рађати род свој, и небо ће давати росу своју; и све ћу то дати у нашљедство остатку тог народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'И као што бијасте уклин међу народима, доме Јудин и доме Израиљев, тако ћу вас избавити те ћете бити благослов; не бој те се, нека вам се окријепе руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Јер овако вели Господ над војскама: као што вам намислих зло учинити, кад ме разгњевише оци ваши, вели Господ над војскама, и не раскајах се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'Тако опет у ове дане намислих да добро чиним Јерусалиму и дому Јудину; не бојте се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Ово је што треба да чините: говорите истину један другом, судите право и мирно на вратима својим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'И не мислите један другоме зло у срцу свом, и не љубите криве заклетве, јер на све то мрзим, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Потом дође ми ријеч Господа над војскама говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Овако вели Господ над војскама: пост четвртога мјесеца, и пост петога и пост седмога и пост десетога обратиће се дому Јудину у радост и весеље и у празнике веселе; али љубите истину и мир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Овако вели Господ над војскама: још ће долазити народи и становници многих градова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'Долазиће становници једнога у други говорећи: хајдемо да се молимо Господу и да тражимо Господа над војскама; идем и ја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Тако ће доћи многи народи и силни народи да траже Господа над војскама у Јерусалиму и да се моле Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Овако вели Господ над војскама: у то ће вријеме десет људи од свијех језика народнијех ухватити једнога Јудејца за скут говорећи: идемо с вама, јер чујемо да је Бог с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Бреме ријечи Господње земљи Адраху и Дамаску, гдје ће починути, јер је Господње око на људима и на свијем племенима Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'И Емат ће захватити, и Тир и Сидон, ако и јесу веома мудри,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'И Тир сагради себи град, и сабра сребра као праха, и злата као кала по путу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Гле, Господ ће га отјерати, и врћи ће у море силу његову, и он ће огњем изгорјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Аскалон ће видјети и уплашиће се, и Газа ће се врло узмучити, и Акарон, што га осрамоти надање његово, и погинуће цар у Гази; и Аскалон се неће населити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'И у Азоту ће сједјети туђин, и понос ћу Филистејски затрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'И уклонићу крв њихову од уста њиховијех, и гадове њихове из зуба њиховијех, и ко остане биће и он Бога нашега, и биће као поглавар у Јуди, а Акарон као Јевусејац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'И поставићу око код дома својега супрот војсци, супрот онима који одлазе и долазе, и настојник неће више пролазити кроз њих, јер сада погледах својим очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Радуј се много, кћери Сионска, подвикуј, кћери Јерусалимска; ево, цар твој иде к теби, праведан је и спасава, кротак и јаше на магарцу, и на магарету, младету магаричину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Јер ћу истријебити из Јефрема кола и из Јерусалима коње; и истријебиће се лук убојити; и он ће казивати мир народима, и власт ће му бити од мора до мора и од ријеке до крајева земаљских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'А ти, за крв завјета твојега пустих сужње твоје из јаме, гдје нема воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Вратите се ка граду, сужњи, који се надате, још ти и данас јављам да ћу ти платити двојином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Јер запех себи Јуду као лук, и напуних Јефрема, и подигох синове твоје, Сионе, на синове твоје, Јаване, и учиних те да си као мач јуначки.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'И Господ ће се показати над њима, и стријела ће његова изаћи као муња, и Господ ће Господ затрубити у трубу и поћи ће с вихорима јужнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Господ над војскама заклањаће их, и они ће јести погазивши камење из праће, и пиће подвикујући као од вина, и биће пуни као чаша, као углови од олтара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'И Господ Бог њихов избавиће их у тај дан као стадо својега народа, јер ће се камење у вијенцу подигнути у земљи његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Јер колико ће бити добро његово и колика љепота његова! од жита ће расти момци а од слатког вина дјевојке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Иштите од Господа дажда у вријеме познога дажда, Господ ће пустити муње, и даће вам изобила дажда и свакоме траве у пољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Јер ликови говоре ништавило и врачи виде лаж и говоре залудне сне, тјеше таштином; зато отидоше као стадо, и ојадише се, јер не бјеше пастира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Гњев се мој распали на пастире, и покарах јарце; јер Господ над војскама обиде стадо своје, дом Јудин, и учини да су му као коњ окићен за бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Од њега је угао, од њега коље, од њега лук убојити, од њега излази и сваки настојник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'И они ће бити као јунаци, газиће у боју као блато по улицама, и биће се, јер је Господ с њима, и који јашу на коњма осрамотиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'И укријепићу дом Јудин, и дом ћу Јосифов спасти, и довешћу их натраг, јер ми их је жао, и биће као да их нијесам одбацио, јер сам ја Господ Бог њихов и услишићу их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'И они од Јефрема биће као јунак, и срце ће им бити весело као од вина, и синови њихови видјеће и веселиће се, и срце ће им се радовати о Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Зазвиждаћу им и сабраћу их, јер ћу их избавити, и они ће се умножити као што су се били умножили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'И расијаћу их међу народе да се у даљнијем мјестима опомињу мене, и живећи са синовима својима да се врате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'И довешћу их натраг из земље Мисирске, и сабраћу их из Асирске, и довешћу их у земљу Галадску и на Ливан; и неће им бити доста мјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'И од тјескобе ће пријећи преко мора, и разбиће вале у мору, и све ће дубине ријеци пресахнути, и обориће се понос Асирски и палица ће се Мисирска узети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'И укријепићу их Господом, и они ће ходати у име његово, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Отвори, Ливане, врата своја, и огањ нека прождре кедре твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Ридај, јело, јер паде кедар, јер красници пропадоше; ридајте, храстови Васански, јер се посијече шума ограђена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Стоји јаук пастира, јер се затр слава њихова; стоји рика лавова, јер се опустоши понос Јордански.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Овако вели Господ Бог мој: паси овце кланице,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'Које убијају они који их држе, нити их ко криви, и који их продају говоре: благословен да је Господ, обогатих се; и који их пасу, ниједан их не жали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Зато нећу више жалити становника земаљских, говори Господ, него ћу ево предати једнога другоме у руке и у руке цару њихову, и они ће потрти земљу а ја је нећу избавити из руку њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'И пасох овце кланице, невољне од стада, и узев два штапа назвах један благост, а други назвах свеза, и пасох стадо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'И погубих три пастира за мјесец дана, јер се душа моја љућаше на њих, и душа њихова мржаше на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'И рекох: нећу вас више пасти; која погине нека погине, и која пропадне нека пропадне, и које остану нека једу месо једна другој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'И узех свој штап, благост, и сломих га да укинем завјет свој који учиних са свијем народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'И укиде се онога дана, и невољни од стада, који гледаху на ме, познаше доиста да бјеше ријеч Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'И рекох им: ако вам је драго, дајте ми моју плату; ако ли није, немојте; и измјерише ми плату, тридесет сребрника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'И рече ми Господ: баци лончару ту часну цијену којом ме прецијенише. И узев тридесет сребрника бацих их у дом Господњи лончару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Потом сломих други штап свој, свезу, да укинем братство између Јуде и Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'И Господ ми рече: узми јоште оправу безумна пастира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Јер ево ја ћу подигнути пастира у земљи, који неће обилазити оне која гине, неће тражити нејаке, нити ће лијечити рањене, нити ће носити сустале, него ће јести месо од претилијех, и папке ће им кидати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Тешко пастиру никаком, који оставља стадо! Мач му је над мишицом и над деснијем оком; мишица ће му усахнути и десно ће му око потамњети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Бреме ријечи Господње за Израиља. Говори Господ, који је разапео небеса и основао земљу, и створио човјеку дух који је у њему:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Ево, ја ћу учинити Јерусалим чашом за опијање свијем народима унаоколо, који ће опсјести Јерусалим ратујући на Јуду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'И у тај ћу дан учинити Јерусалим тешким каменом свијем народима; који га год хтједбуду дигнути, сатрће се, ако би се и сви народи земаљски сабрали на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'У тај ћу дан, говори Господ, учинити да сви коњи буду плашљиви и сви коњаници безумни; и отвори ћу очи своје на дом Јудин, и ослијепићу све коње народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Те ће говорити главари Јудини у срцу свом: јаки су ми становници Јерусалимски Господом над војскама, Богом својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'У онај ћу дан учинити да главари Јудини буду као огњиште у дрвима и као луч запаљен у сноповима, те ће прождријети и надесно и налијево све народе унаоколо, а Јерусалим ће још остати на свом мјесту, у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'И Господ ће сачувати шаторе Јудине најприје, да се не диже над Јудом слава дома Давидова и слава становника Јерусалимских.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'У онај ће дан Господ заклањати становнике Јерусалимске, и најслабији међу њима биће у тај дан као Давид, и дом ће Давидов бити као Бог, као анђео Господњи пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'И у тај дан тражићу да истријебим све народе који дођу на Јерусалим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'И излићу на дом Давидов и на становнике Јерусалимске дух милости и молитава, и погледаће на мене којега прободоше; и плакаће за њим као за јединцем, и тужиће за њим као за првенцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'У оно ће вријеме бити тужњава велика у Јерусалиму као тужњава у Ададримону у пољу Мегидонском.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'И тужиће земља, свака породица напосе; породица дома Давидова напосе, и жене њихове напосе; породица дома Натанова напосе, и жене њихове напосе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'Породица дома Левијева напосе, и жене њихове напосе; породица Семејева напосе, и жене њихове напосе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'Све остале породице, свака напосе, и жене њихове напосе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'У тај ће дан бити отворен извор дому Давидову и становницима Јерусалимским за гријех и за нечистоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'И у тај ћу дан, говори Господ над војскама, истријебити из земље имена идолима да се више не спомињу, и пророке и нечисти дух уклониће из земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'И ако ко још успророкује, рећи ће му отац његов и мати његова, који га родише: нећеш бити жив, јер си говорио лаж у име Господње. И отац ће га његов и мати његова, који га родише, пробости, што пророкова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'И у тај ће се дан стидјети пророци сваки своје утваре, кад би пророковао, и неће се огртати плаштем од костријети да би лагали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Него ће сваки рећи: нијесам пророк, ратар сам, јер ме човјек најми од младости моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'И ако му ко рече: каке су ти то ране на руку? он ће одговорити: допадох их у кући пријатеља својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Мачу, устани на пастира мојега и на човјека друга мојега, говори Господ над војскама, удари пастира, и овце ће се разбјећи, али ћу окренути руку своју к малима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'И у свој земљи, говори Господ, два ће се дијела истријебити у њој и погинути, а трећи ће остати у њој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'И ту ћу трећину метнути у огањ, и претопићу их како се претапа сребро, и окушаћу их како се куша злато; они ће призвати име моје, и ја ћу им се одазвати и рећи ћу: то је мој народ; а они ће рећи: Господ је Бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Ево иде дан Господњи, и плијен ће се твој раздијелити усред тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Јер ћу скупити све народе на Јерусалим у бој, и град ће се узети, и куће оплијенити и жене осрамотити, и половина ће града отићи у ропство, а остали народ неће се истријебити из града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Јер ће Господ изаћи, и војеваће на народе као што војује на дан кад је бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'И ноге ће његове стати у тај дан на гори Маслинској која је према Јерусалиму с истока, и гора ће се Маслинска распасти по сриједи на исток и на запад да ће бити продол врло велика, и половина ће горе уступити на сјевер а половина на југ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'И бјежаћете у продол горску, јер ће продол горска допирати до Асала, и бјежаћете као што бјежасте од труса у вријеме Озије цара Јудина; и доћи ће Господ Бог мој, и сви ће свети бити с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'И у тај дан неће бити видјело свијетло и мрачно;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Него ће бити један дан, који је познат Господу, неће бити дан и ноћ, јер ће и увече бити свјетлост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'И у тај ће дан протећи из Јерусалима вода жива, пола к источном мору а пола к западном мору, и биће и љети и зими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'И Господ ће бити цар над свом земљом, у онај дан биће Господ један и име његово једно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'И сва ће се земља претворити у равницу од Гаваје до Римона с југа Јерусалиму, који ће се подигнути и населити на свом мјесту од врата Венијаминовијех до мјеста гдје су прва врата, до врата на углу, и од куле Ананеилове до тијеска царева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'И они ће наставати у њему, и неће више бити проклетства, и Јерусалим ће стајати без страха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'А ово ће бити зло којим ће Господ ударити све народе који би војевали на Јерусалим: тијело ће сваком посахнути док још стоји на ногу, и очи ће сваком посахнути у рупама својим, и језик ће сваком посахнути у устима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'И у то ће вријеме бити велика сметња међу њима од Господа, и хватаће један другога за руку, и рука ће се једнога подигнути на руку другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'А и Јуда ће војевати на Јерусалим, и благо свијех народа унаоколо сабраће се, злато и сребро и одијело врло много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'И зло као то зло снаћи ће коње, мазге, камиле и магарце и сву стоку која буде у том околу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'И ко год остане од свијех народа који дођу на Јерусалим, свак ће долазити од године до године да се поклони цару Господу над војскама и да празнује празник сјеница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'И ако који од племена земаљских не би дошли у Јерусалим да се поклоне цару Господу над војскама, на њих неће бити дажда;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'И ако се племе Мисирско не би подигло и дошло, на које не дажди, биће исто зло којим ће Господ ударити народе који не би долазили да празнују празник сјеница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Таки ће бити гријех Мисирцима и гријех свијем народима који не би долазили да празнују празник сјеница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'У тај ће дан бити на звонцима коњским: светиња Господу; и лонци ће у дому Господњем бити као здјеле пред олтаром;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'И сви ће лонци у Јерусалиму и у Јуди бити светиња Господу над војскама, и сви који хоће да принесу жртву долазећи узимаће их и кухати у њима; и у тај дан неће више бити Хананејца у дому Господа над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Бреме ријечи Господње Израиљу преко Малахије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Љубим вас, вели Господ; а ви говорите: у чем нас љубиш? Не бјеше ли Исав брат Јакову? говори Господ; али Јакова љубих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'А на Исава мрзих; зато горе његове опустих и нашљедство његово дадох змајевима из пустиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Што Едом говори: осиромашисмо, али ћемо се повратити и саградити пуста мјеста, овако вели Господ над војскама: нека они граде, али ћу ја разградити, и они ће се звати: крајина безаконичка и народ на који се гњеви Господ довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'И очи ће ваше видјети и ви ћете рећи: велик је Господ на међама Израиљевијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Син поштује оца и слуга господара својега; ако сам ја отац, гдје је част моја? и ако сам господар, гдје је страх мој? вели Господ над војскама вама, свештеници, који презирете име моје, и говорите: у чем презиремо име твоје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Доносите на мој олтар хљеб оскврњен, и говорите: чим те оскврнисмо? Тијем што говорите: сто је Господњи за презирање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'И кад доносите слијепо на жртву, није ли зло? и кад доносите хромо или болесно, није ли зло? однеси га старјешини својему, хоћеш ли му угодити и хоће ли погледати на те? вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Зато, молите се Богу да се смилује на нас; кад је то из ваших руку, хоће ли на кога од вас гледати? говори Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Ко је међу вама који би затворио врата или запалио огањ на мом олтару ни за што? Нијесте ми мили, вели Господ над војскама, и нећу примити дара из ваше руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Јер од истока сунчанога до запада велико ће бити име моје међу народима, и на сваком ће се мјесту приносити кад имену мојему и чист дар; јер ће име моје бити велико међу народима, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'А ви га скврните говорећи: сто је Господњи нечист, и што се поставља на њ, јело је за презирање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'И говорите: гле, колика мука! а могло би се одухнути, говори Господ над војскама; и доносите отето, и хромо и болесно доносите на дар; еда ли ћу примити из руке ваше? говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Проклет да је варалица, који има у свом стаду мушко и завјетује, па приноси Господу кварно; јер сам велик цар, вели Господ над војскама, и име је моје страшно међу народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'И тако сада вама је ова заповијест, свештеници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Ако не послушате и не ставите у срце да дате славу имену мојему, вели Господ над војскама, тада ћу пустити на вас проклетство и проклећу благослове ваше; и проклех их, јер не стављате у срце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Ево ја ћу вам покварити усјев, и бацићу вам балегу у лице, балегу празника ваших, да вас однесе са собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'И познаћете да сам вам ја послао ову заповијест да би био мој завјет с Левијем, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Завјет мој за живот и мир бјеше с њим, и дадох му то за страх, јер ме се бојаше и имена се мојега страшаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Закон истинити бјеше у устима његовијем, и безакоње се не нађе на уснама његовијем; у миру и право иде са мном и многе одврати од безакоња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Јер усне свештеникове треба да чувају знање и закон да се тражи из његовијех уста, јер је анђео Господа над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Али ви зађосте с пута, и учинисте те се многи спотакоше о закон, покваристе завјет Левијев, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Зато и ја вас учиних презреним и поништеним у свега народа, као што се ви не држите мојих путова и у закону гледате ко је ко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Није ли нам свјема један отац? није ли нас један Бог створио? зашто невјеру чинимо један другоме скврнећи завјет отаца својих?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Јуда чини невјеру, и гад се чини у Израиљу и у Јерусалиму; јер скврни Јуда светињу Господњу, коју би му ваљало љубити, женећи се кћерју туђега бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Господ ће истријебити из шатора Јаковљевијех човјека који чини тако, који стражи и који одговара, и који приноси принос Господу над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Још и ово чините: покривате сузама олтар Господњи, плачем и уздасима; зато не гледа више на принос, нити му је драго примити што из ваших руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'А ви говорите: зашто? Зато што је Господ свједок између тебе и жене младости твоје, којој ти чиниш невјеру, а она ти је другарица и жена, с којом си у вјери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Јер није ли учинио једно, ако и имаше још више духа? а зашто једно? да тражи сјеме Божије; зато чувајте дух свој, и жени младости своје не чините невјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Јер Господ Бог Израиљев вели да мрзи на пуштање, јер таки покрива насиље плаштем својим, говори Господ над војскама; зато чувајте дух свој да не чините невјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Досађујете Господу ријечима својим, и говорите: у чем му досађујемо? У том што говорите: ко год чини зло, по вољи је Господу, и таки су му мили; или: гдје је Бог који суди?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Ево, ја ћу послати анђела својега, који ће приправити пут преда мном, и изненада ће доћи у цркву своју Господ, којега ви тражите, и анђео завјетни, којега ви желите, ево доћи ће, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Али ко ће поднијети дан доласка његова? и ко ће се одржати кад се покаже? јер је он као огањ ливчев и као мило бјељарско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'И сјешће као онај који лије и чисти сребро, очистиће синове Левијеве, и претопиће их као злато и сребро, и они ће приносити Господу приносе у правди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'И угодан ће бити Господу принос Јудин и Јерусалимски као у старо вријеме и као пређашњих година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'И доћи ћу к вама на суд, и бићу брз свједок против врачара и против прељубочинаца, и против онијех који се куну криво и против онијех који закидају најам најамнику, и удовици и сироти и дошљаку криво чине и не боје се мене, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Јер ја Господ не мијењам се; зато ви, синови Јаковљеви, не изгибосте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Од времена отаца својих отступисте од уредаба мојих и не држасте их. Вратите се к мени, и ја ћу се вратити к вама, вели Господ над војскама. Али велите: у чем бисмо се вратили?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Еда ли ће човјек закидати Бога? а ви мене закидате; и говорите: у чем те закидамо? у десетку и у приносу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Проклети сте, јер ме закидате, ви, сав народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Донесите све десетке у спреме да буде хране у мојој кући, и окушајте ме у том, вели Господ над војскама, хоћу ли вам отворити уставе небеске и излити благослов на вас да вам буде доста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'И запријетићу вас ради прождрљивцу, те вам неће кварити рода земаљскога, и винова лоза у пољу неће вам бити неродна, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'И зваће вас блаженим сви народи, јер ћете бити земља мила, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Жестоке бјеху ваше ријечи на ме, вели Господ; а ви велите: шта говорисмо на тебе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Рекосте: залуду је служити Богу, и кака ће бити корист да држимо што је наредио да се држи, и да ходимо жалосни пред Господом над војскама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Зато хвалимо поносите да су срећни; напредују који чине безакоње, и који искушавају Бога, избављају се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Тада који се боје Господа говорише један другоме, и погледа Господ, и чу, и написа се књига за спомен пред њим за оне који се боје Господа и мисле о имену његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Ти ће ми бити благо, вели Господ над војскама, у онај дан кад ја учиним, и бићу им милостив као што је отац милостив своме сину који му служи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Тада ћете се обратити и видјећете разлику између праведника и безбожника, између онога који служи Богу и онога који му не служи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Јер, гле, иде дан, који гори као пећ, и сви ће поносити и сви који раде безбожно бити стрњика, и упалиће их дан који иде, вели Господ над војскама, и неће им оставити ни коријена ни гране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'А вама, који се бојите имена мојега, грануће сунце правде, и здравље ће бити на зрацима његовијем, и излазићете и скакаћете као теоци од јасала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'И изгазићете безбожнике, јер ће они бити пепео под вашим ногама у дан кад ја учиним, вели Господ над војскама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Памтите закон Мојсија слуге мојега, којему заповједих на Хориву за свега Израиља уредбе и законе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Ево, ја ћу вам послати Илију пророка прије него дође велики и страшни дан Господњи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'И он ће обратити срце отаца к синовима, и срце синова к оцима њиховијем, да не дођем и затрем земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Племе Исуса Христа, сина Давида Авраамова сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Авраам роди Исака. А Исак роди Јакова. А Јаков роди Јуду и браћу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'А Јуда роди Фареса и Зару с Тамаром. А Фарес роди Есрома. А Есром роди Арама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'А Арам роди Аминадава. А Аминадав роди Наасона. А Наасон роди Салмона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'А Салмон роди Вооза с Рахавом. А Вооз роди Овида с Рутом. А Овид роди Јесеја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'А Јесеј роди Давида цара. А Давид цар роди Соломуна с Уријницом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'А Соломун роди Ровоама. А Ровоам роди Авију. А Авија роди Асу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'А Аса роди Јосафата. А Јосафат роди Јорама. А Јорам роди Озију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'А Озија роди Јоатама. А Јоатам роди Ахаза. А Ахаз роди Езекију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'А Езекија роди Манасију. а Манасија роди Амона. А Амон роди Јосију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'А Јосија роди Јехонију и браћу његову, у сеоби Вавилонској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'А по сеоби Вавилонској, Јехонија роди Салатиила. А Салатиило роди Зоровавеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'А Зоровавељ роди Авиуда. А Авиуд роди Елиакима. А Елиаким роди Азора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'А Азор роди Садока. А Садок роди Ахима. А Ахим роди Елиуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'А Елиуд роди Елеазара. а Елеазар роди Матана. А Матан роди Јакова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'А Јаков роди Јосифа, мужа Марије, која роди Исуса прозванога Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Свега дакле кољена од Аврама до Давида, кољена четрнаест, а од Давида до сеобе Вавилонске, кољена четрнаест, а од сеобе Вавилонске до Христа, кољена четрнаест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'А рођење Исуса Христа било је овако: кад је Марија, мати његова, била испрошена за Јосифа, а још док се нијесу били састали, нађе се да је она трудна од Духа светога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'А Јосиф муж њезин, будући побожан, не хотећи је јавно срамотити, намисли је тајно пустити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Но кад он тако помисли, а то му се јави у сну анђео Господњи говорећи: Јосифе, сине Давидов! не бој се узети Марије жене своје; јер оно што је у њој зачело од Духа је светога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Па ће родити сина, и надјени му име Исус; јер ће он избавити свој народ од гријеха њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'А ово је све било да се изврши што је Господ казао преко пророка који говори:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, 'Ето, дјевојка ће затрудњети, и родиће сина, и надјенуће му име Емануило, које ће рећи: с нама Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Кад се Јосих пробуди од сна, учини како му је заповједио анђео Господњи, и узме жену своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'И не знадијаше за њу док не роди сина својега првенца, и надједе му име Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'А кад се роди Исус у Витлејему Јудејскоме, за времена цара Ирода, а то дођу мудраци с истока у Јерусалим, и кажу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Гдје је цар Јудејски што се родио? Јер смо видјели његову звијезду на истоку и дошли смо да му се поклонимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Кад то чује цар Ирод, уплаши се, и сав Јерусалим с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'И сабравши све главаре свештеничке и књижевнике народне, питаше их: гдје ће се родити Христос?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'А они му рекоше: у Витлејему Јудејскоме; јер је тако пророк написао:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'И ти Витлејеме, земљо Јудина! ни по чем ниси најмањи у држави Јудиној; јер ће из тебе изићи человођа који ће пасти народ мој Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Онда Ирод тајно дозва мудраце, и испитиваше их кад се појавила звијезда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'И пославши их у Витлејем, рече: идите и распитајте добро за дијете, па кад га нађете, јавите ми, да и ја идем да му се поклоним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'И они саслушавши цара, пођоше: а то и звијезда коју су видјели на истоку, иђаше пред њима док не дође и стаде одозго гдје бјеше дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'А кад видјеше звијезду гдје је стала, обрадоваше се веома великом радости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'И ушавши у кућу, видјеше дијете с Маријом матером његовом, и падоше и поклонише му се; па отворише даре своје и дариваше га: златом, и тамјаном, и смирном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'И примивши у сну заповијест да се не враћају к Ироду, другијем путем отидоше у своју земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'А пошто они отиду, а то анђео Господњи јави се Јосифу у сну и каза му: устани, узми дијете и матер његову па бјежи у Мисир, и буди онамо док ти не кажем; јер ће Ирод тражити дијете да га погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'И он уставши узе дијете и матер његову ноћу и отиде у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'И би тамо до смрти Иродове: да се изврши што је Господ рекао преко пророка који говори: из Мисира дозвах сина својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Тада Ирод кад видје да су га мудраци преварили, разгњеви се врло и посла те побише сву дјецу по Витлејему и по свој околини његовој од двије године и ниже, по времену које је добро дознао од мудраца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Тада се зби што је казао пророк Јеремија говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'Глас у Рами чу се, плач, и ридање, и јаукање много: Рахиља плаче за својом дјецом, и неће да се утјеши, јер их нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'А по смрти Иродовој, гле, анђео Господњи у сну јави се Јосифу у Мисиру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'И рече: устани, и узми дијете и матер његову и иди у земљу Израиљеву; јер су изумрли који су тражили душу дјетињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'И он уставши, узе дијете и матер његову, и дође у земљу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Али чувши да Архелај царује у Јудеји мјесто Ирода оца својега, побоја се онамо ићи; него примивши у сну заповијест, отиде у крајеве Галилејске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'И дошавши онамо, намјести се у граду који се зове Назарет, да се збуде као што су казали пророци да ће се Назарећанин назвати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'У оно пак доба дође Јован крститељ, и учаше у пустињи Јудејској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'И говораше: покајте се, јер се приближи царство небеско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Јер је то онај за кога је говорио пророк Исаија гдје каже: глас онога што виче у пустињи: приправите пут Господу, и поравните стазе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'А Јован имаше хаљину од длаке камиље и појас кожан око себе; а храна његова бијаше скакавци и мед дивљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Тада излажаше к њему Јерусалим и сва Јудеја, и сва околина Јорданска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'И он их кршћаваше у Јордану, и исповиједаху гријехе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'А кад видје (Јован) многе фарисеје и садукеје гдје иду да их крсти, рече им: породи аспидини! ко каза вама да бјежите од гњева који иде?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Родите дакле род достојан покајања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'И не мислите и не говорите у себи: имамо оца Авраама; јер вам кажем да може Бог и од камења овога подигнути дјецу Аврааму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Већ и сјекира код коријена дрвету стоји; свако дакле дрво које не рађа добра рода, сијече се и у огањ баца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Ја дакле кршћавам вас водом за покајање; а онај који иде за мном, јачи је од мене; ја нијесам достојан њему обуће понијети; он ће вас крстити Духом светијем и огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Њему је лопата у руци његовој, па ће отријебити гумно своје, и скупиће пшеницу своју у житницу, а пљеву ће сажећи огњем вјечнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Тада дође Исус из Галилеје на Јордан к Јовану да се крсти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'А Јован брањаше му говорећи: ти треба мене да крстиш, а ти ли долазиш к мени?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'А Исус одговори и рече му: остави сад, јер тако нам треба испунити сваку правду. Тада Јован остави га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'И крстивши се Исус изиђе одмах из воде; и гле, отворише му се небеса, и видје Духа Божијега гдје силази као голуб и дође на њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'И гле, глас с неба који говори: ово је син мој љубазни који је по мојој вољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Тада Исуса одведе Дух у пустињу да га ђаво куша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'И постивши се дана четрдесет и ноћи четрдесет, напошљетку огладње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'И приступи к њему кушач и рече: ако си син Божиј, реци да камење ово хљебови постану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'А он одговори и рече: писано је: не живи човјек о самом хљебу, но о свакој ријечи која излази из уста Божијих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Тада одведе га ђаво у свети град и постави га наврх цркве;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'Па му рече: ако си син Божиј, скочи доље, јер у писму стоји да ће анђелима својијем заповједити за тебе, и узеће те на руке, да гдје не запнеш за камен ногом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'А Исус рече њему: али и то стоји написано: немој кушати Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Опет га узе ђаво и одведе га на гору врло високу, и показа му сва царства овога свијета и славу њихову;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'И рече му: све ово даћу теби ако паднеш и поклониш ми се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Тада рече њему Исус: иди од мене, сотоно; јер стоји написано: Господу Богу својему поклањај се и њему једино служи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Тада остави га ђаво, и гле, анђели приступише и служаху му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'А кад чу Исус да је Јован предан, отиде у Галилеју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'И оставивши Назарет дође и намјести се у Капернауму приморскоме на међи Завулоновој и Нефталимовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Да се збуде што је рекао Исаија пророк говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Земља Завулонова и земља Нефталимова, на путу к мору с оне стране Јордана, Галилеја незнабожачка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Људи који сједе у тами, видјеше видјело велико, и онима што сједе на страни и у сјену смртноме, засвијетли видјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Отада поче Исус учити и говорити: покајте се, јер се приближи царство небеско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'И идући покрај мора Галилејског видје два брата, Симона, који се зове Петар, и Андрију брата његова, гдје мећу мреже у море, јер бијаху рибари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'И рече им: хајдете за мном, и учинићу вас ловцима људскијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'А они тај час оставише мреже и за њим отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'И отишавши одатле видје друга два брата, Јакова Заведејева, и Јована брата његова, у лађи са Заведејем оцем њиховијем гдје крпе мреже своје, и позва их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'А они тај час оставише лађу и оца својега и за њим отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'И прохођаше по свој Галилеји Исус учећи по зборницама њиховијем, и проповиједајући јеванђеље о царству, и исцијељујући сваку болест и сваку немоћ по људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'И отиде глас о њему по свој Сирији и приведоше му све болесне од различнијех болести и с различнијем мукама, и бијесне, и мјесечњаке, и узете, и исцијели их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'И за њим иђаше народа много из Галилеје, и из Десет Градова, и из Јерусалима, и Јудеје, и испреко Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'А кад он видје народ, попе се на гору, и сједе, и приступише му ученици његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'И отворивши уста своја учаше их говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Благо сиромашнима духом, јер је њихово царство небеско;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Благо онима који плачу, јер ће се утјешити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Благо кроткима, јер ће наслиједити земљу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Благо гладнима и жеднима правде, јер ће се наситити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Благо милостивима, јер ће бити помиловани;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Благо онима који су чистога срца, јер ће Бога видјети;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Благо онима који мир граде, јер ће се синови Божији назвати;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Благо прогнанима правде ради, јер је њихово царство небеско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Благо вама ако вас узасрамоте и успрогоне и реку на вас свакојаке рђаве ријечи лажући, мене ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Радујте се и веселите се, јер је велика плата ваша на небесима, јер су тако прогонили пророке прије вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Ви сте со земљи; ако со обљутави, чим ће се осолити? Она већ неће бити ни за што, осим да се проспе напоље и да је људи погазе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Ви сте видјело свијету; не може се град сакрити кад на гори стоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Нити се ужиже свијећа и меће под суд него на свијећњак, те свијетли свима који су у кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Тако да се свијетли ваше видјело пред људима, да виде ваша добра дјела, и славе оца вашега који је на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Не мислите да сам ја дошао да покварим закон или пророке: нијесам дошао да покварим, него да испуним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Јер вам заиста кажем: докле небо и земља стоји, неће нестати ни најмањега словца или једне титле из закона док се све не изврши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Ако ко поквари једну од овијех најмањијех заповијести и научи тако људе, најмањи назваће се у царству небескоме; а ко изврши и научи, тај ће се велики назвати у царству небескоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Јер вам кажем да ако не буде већа правда ваша него књижевника и фарисеја, нећете ући у царство небеско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Чули сте како је казано старима: не убиј; јер ко убије, биће крив суду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'А ја вам кажем да ће сваки који се гњеви на брата својега ни за што, бити крив суду; а ако ли ко рече брату својему: рака! биће крив скупштини; а ко рече: будало! биће крив паклу огњеном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Зато дакле ако принесеш дар свој к олтару, и ондје се опоменеш да брат твој има нешто на те,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'Остави ондје дар свој пред олтаром, и иди прије те се помири с братом својијем, па онда дођи и принеси дар свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Мири се са супарником својијем брзо, док си на путу с њим, да те супарник не преда судији, а судија да те не преда слузи и у тамницу да те не вргну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Заиста ти кажем: нећеш изаћи оданде док не даш до пошљедњега динара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Чули сте како је казано старима: не чини прељубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'А ја вам кажем да сваки који погледа на жену са жељом, већ је учинио прељубу у срцу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'А ако те око твоје десно саблажњава, ископај га и баци од себе: јер ти је боље да погине један од удова твојијех неголи све тијело твоје да буде бачено у пакао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'И ако те десна рука твоја саблажњава, отсијеци је и баци од себе: јер ти је боље да погине један од удова твојијех неголи све тијело твоје да буде бачено у пакао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Тако је казано: ако ко пусти жену своју, да јој да књигу распусну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'А ја вам кажем да сваки који пусти жену своју, осим за прељубу, наводи је те чини прељубу; и који пуштеницу узме прељубу чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Још сте чули како је казано старима: не куни се криво, а испуни што си се Господу заклео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'А ја вам кажем: не куните се никако: ни небом, јер је пријестол Божиј;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'Ни земљом, јер је подножје ногама његовијем; ни Јерусалимом, јер је град великога цара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Ни главом својом не куни се, јер не можеш длаке једне бијеле или црне учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Дакле нека буде ваша ријеч: да, да; не, не; а што је више од овога, ода зла је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Чули сте да је казано: око за око, и зуб за зуб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'А ја вам кажем да се не браните ода зла, него ако те ко удари по десноме твом образу, обрни му и други;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'И који хоће да се суди с тобом и кошуљу твоју да узме, подај му и хаљину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'И ако те потјера ко један сахат, иди с њиме два.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Који иште у тебе, подај му; и који хоће да му узајмиш, не одреци му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Чули сте да је казано: љуби ближњега својега, и мрзи на непријатеља својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'А ја вам кажем: љубите непријатеље своје, благосиљајте оне који вас куну, чините добро онима који на вас мрзе и молите се Богу за оне који вас гоне;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'Да будете синови оца својега који је на небесима; јер он заповиједа своме сунцу, те обасјава и зле и добре, и даје дажд праведнима и неправеднима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Јер ако љубите оне који вас љубе, какову плату имате? Не чине ли то и цариници?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'И ако Бога називате само својој браћи, шта одвише чините? Не чине ли тако и незнабошци?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Будите ви дакле савршени, као што је савршен отац ваш небески.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Пазите да правду своју не чините пред људима да вас они виде; иначе плате немате од оца својега који је на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Кад дакле дајеш милостињу, не труби пред собом, као што чине лицемјери по зборницама и по улицама да их хвале људи. Заисто вам кажем: примили су плату своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'А ти кад чиниш милостињу, да не зна љевака твоја шта чини десница твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Тако да буде милостиња твоја тајна; и отац твој који види тајно, платиће теби јавно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'И кад се молиш Богу, не буди као лицемјери, који радо по зборницама и на раскршћу по улицама стоје и моле се да их виде људи. Заисто вам кажем да су примили плату своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'А ти кад се молиш, уђи у клијет своју, и затворивши врата своја, помоли се оцу својему који је у тајности; и отац твој који види тајно, платиће теби јавно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'А кад се молите, не говорите много као незнабошци; јер они мисле да ће за многе ријечи своје бити услишени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Ви дакле не будите као они; јер зна отац ваш шта вам треба прије молитве ваше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Овако дакле молите се ви: Оче наш који си на небесима, да се свети име твоје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Да дође царство твоје; да буде воља твоја и на земљи као на небу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Хљеб наш потребни дај нам данас;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'И опрости нам дугове наше као и ми што опраштамо дужницима својијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'И не наведи нас у напаст; но избави нас ода зла. Јер је твоје царство, и сила, и слава вавијек. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Јер ако опраштате људима гријехе њихове, опростиће и вама отац ваш небески.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Ако ли не опраштате људима гријеха њиховијех, ни отац ваш неће опростити вама гријеха вашијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'А кад постите, не будите жалосни као лицемјери; јер они начине блиједа лица своја да их виде људи гдје посте. Заисто вам кажем да су примили плату своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'А ти кад постиш, намажи главу своју, и лице своје умиј,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Да те не виде људи гдје постиш, него отац твој који је у тајности; и отац твој који види тајно, платиће теби јавно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Не сабирајте себи блага на земљи, гдје мољац и рђа квари, и гдје лупежи поткопавају и краду;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Него сабирајте себи благо на небу, гдје ни мољац ни рђа не квари, и гдје лупежи не поткопавају и не краду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Јер гдје је ваше благо, ондје ће бити и срце ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Свијећа је тијелу око. Ако дакле буде око твоје здраво, све ће тијело твоје свијетло бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Ако ли око твоје кварно буде, све ће тијело твоје тамно бити. Ако је дакле видјело што је у теби тама, акамоли тама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Нико не може два господара служити: јер или ће на једнога мрзити, а другога љубити; или једноме вољети, а за другог не марити. Не можете Богу служити и мамони.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'За то вам кажем: не брините се за живот свој, шта ћете јести, или шта ћете пити; ни за тијело своје, у што ћете се обући. Није ли живот претежнији од хране, и тијело од одијела?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Погледајте на птице небеске како не сију, нити жњу, ни сабирају у житнице; па отац ваш небески храни их. Нијесте ли ви много претежнији од њих?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'А ко од вас бринући се може примакнути расту својему лакат један?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'И за одијело што се бринете? Погледајте на љиљане у пољу како расту; не труде се нити преду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Али ја вам кажем да ни Соломун у свој својој слави не обуче се као један од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'А кад траву у пољу, која данас јест, а сјутра се у пећ баца, Бог тако одијева, а акамоли вас, маловјерни?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Не брините се дакле говорећи: шта ћемо јести, или, шта ћемо пити, или, чим ћемо се одјенути?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Јер све ово незнабошци ишту; а зна и отац ваш небески да вама треба све ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Него иштите најприје царства Божијега, и правде његове, и ово ће вам се све додати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Не брините се дакле за сјутра; јер сјутра бринуће се за се. Доста је сваком дану зла свога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Не судите да вам се не суди;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Јер каковијем судом судите, онаковијем ће вам судити; и каковом мјером мјерите, онаком ће вам се мјерити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'А зашто видиш трун у оку брата својега, а брвна у оку својему не осјећаш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Или, како можеш рећи брату својему: стани да ти извадим трун из ока твојега; а ето брвно у оку твојему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Лицемјере! извади најприје брвно из ока својега, па ћеш онда видјети извадити трун из ока брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Не дајте светиње псима; нити мећите бисера својега пред свиње, да га не погазе ногама својима, и вративши се не растргну вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Иштите, и даће вам се; тражите, и наћи ћете; куцајте, и отвориће вам се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Јер сваки који иште, прима; и који тражи, налази; и који куца, отвориће му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Или који је међу вама човјек у кога ако заиште син његов хљеба камен да му да?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Или ако рибе заиште да му да змију?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Кад дакле ви, зли будући, умијете даре добре давати дјеци својој, колико ће више отац ваш небески дати добра онима који га моле?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Све дакле што хоћете да чине вама људи, чините и ви њима: јер је то закон и пророци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Уђите на уска врата; јер су широка врата и широк пут што воде у пропаст, и много их има који њим иду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Као што су уска врата и тијесан пут што воде у живот, и мало их је који га налазе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Чувајте се од лажнијех пророка, који долазе к вама у одијелу овчијему, а унутра су вуци грабљиви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'По родовима њиховијем познаћете их. Еда ли се бере с трња грожђе, или с чичка смокве?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Тако свако дрво добро родове добре рађа, а зло дрво родове зле рађа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Не може дрво добро родова злијех рађати, ни дрво зло родова добријех рађати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Свако дакле дрво које не рађа рода добра, сијеку и у огањ бацају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'И тако дакле по родовима њиховијем познаћете их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Не ће сваки који ми говори: Господе! Господе! ући у царство небеско; но који чини по вољи оца мојега који је на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Многи ће рећи мени у онај дан: Господе! Господе! нијесмо ли у име твоје пророковали, и твојијем именом ђаволе изгонили, и твојијем именом чудеса многа творили?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'И тада ћу им ја казати: никад вас нијесам знао; идите од мене који чините безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Сваки дакле који слуша ове моје ријечи и извршује их, казаћу да је као мудар човјек који сазида кућу своју на камену:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'И удари дажд, и дођоше воде, и дунуше вјетрови, и нападоше на кућу ону, и не паде; јер бјеше утврђена на камену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'А сваки који слуша ове моје ријечи а не извршује их, он ће бити као човјек луд који сазида кућу своју на пијеску:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'И удари дажд, и дођоше воде, и дунуше вјетрови, и ударише у кућу ону, и паде, и распаде се страшно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'И кад сврши Исус ријечи ове, дивљаше се народ науци његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'Јер их учаше као онај који власт има, а не као књижевници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'А кад сиђе с горе, за њим иђаше народа много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'И гле, човјек губав дође и клањаше му се говорећи: Господе! ако хоћеш, можеш ме очистити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'И пруживши руку Исус, дохвати га се говорећи: хоћу, очисти се. И одмах очисти се од губе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'И рече му Исус: гледај, никому не казуј, него иди и покажи се свештенику, и принеси дар који је заповједио Мојсије ради свједочанства њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'А кад уђе у Капернаум, приступи к њему капетан молећи га');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'И говорећи: Господе! слуга мој лежи дома узет, и мучи се врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'А Исус му рече: ја ћу доћи и исцијелићу га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'И капетан одговори и рече: Господе! нијесам достојан да под кров мој уђеш; него само реци ријеч, и оздравиће слуга мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Јер и ја сам човјек под власти, и имам под собом војнике, па речем једноме: иди, и иде; и другоме: дођи, и дође; и слузи својему: учини то, и учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'А кад чу Исус, удиви се и рече онима што иђаху за њим: заиста вам кажем: ни у Израиљу толике вјере не нађох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'И то вам кажем да ће многи од истока и запада доћи и сјешће за трпезу с Авраамом и Исаком и Јаковом у царству небескоме:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'А синови царства изгнаће се у таму најкрајњу; ондје ће бити плач и шкргут зуба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'А капетану рече Исус: иди, и како си вјеровао нека ти буде. И оздрави слуга његов у тај час.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'И дошавши Исус у дом Петров видје ташту његову гдје лежи и грозница је тресе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'И прихвати је за руку, и пусти је грозница, и уста, и служаше му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'А у вече доведоше к њему бијеснијех много, и изгна духове ријечју, и све болеснике исцијели:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Да се збуде што је казао Исаија пророк говорећи: он немоћи наше узе и болести понесе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'А кад видје Исус много народа око себе, заповједи ученицима својијем да иду на ону страну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'И приступивши један књижевник рече му: учитељу! ја идем за тобом кудгод ти пођеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Рече њему Исус: лисице имају јаме и птице небеске гнијезда; а син човјечји нема гдје главе заклонити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'А други од ученика његовијех рече му: Господе! допусти ми најприје да идем да укопам оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'А Исус рече њему: хајде за мном, а остави нека мртви укопавају своје мртваце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'И кад уђе у лађу, за њим уђоше ученици његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'И гле, олуја велика постаде на мору да се лађа покри валовима; а он спаваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'И прикучивши се ученици његови пробудише га говорећи: Господе! избави нас, изгибосмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'И рече им: зашто сте страшљиви, маловјерни? Тада уставши запријети вјетровима и мору, и постаде тишина велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'А људи чудише се говорећи: ко је овај да га слушају и вјетрови и море?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'А кад дође на ону страну у земљу Гергесинску, сретоше га два бијесна, који излазе из гробова, тако зла да не могаше нико проћи путем онијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'И гле, повикаше: што је теби до нас, Исусе, сине Божиј? зар си дошао амо прије времена да мучиш нас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'А далеко од њих пасијаше велики крд свиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'И ђаволи мољаху га говорећи: ако нас изгониш, пошљи нас да идемо у крд свиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'И рече им: идите. И они изишавши отидоше у свиње. И гле, навали сав крд с бријега у море, и потопише се у води.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'А свињари побјегоше; и дошавши у град казаше све, и за бијесне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'И гле, сав град изиђе на сусрет Исусу; и видјевши га молише да би отишао из њиховога краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'И ушавши у лађу пријеђе и дође у свој град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'И гле, донесоше му узета који лежаше на одру. И видјевши Исус вјеру њихову рече узетоме: не бој се, синко, опраштају ти се гријеси твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'И гле, неки од књижевника рекоше у себи: овај хули на Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'И видјећи Исус помисли њихове рече: за што зло мислите у срцима својијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Јер шта је лакше рећи: опраштају ти се гријеси; или рећи: устани и ходи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Али да знате да власт има син човјечиј на земљи опраштати гријехе (тада рече узетоме): устани, узми одар свој и иди дома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'И уставши отиде дома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'А људи видећи чудише се, и хвалише Бога, који је дао власт такову људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'И одлазећи Исус оданде видје човјека гдје сједи на царини, по имену Матеја, и рече му: хајде за мном. И уставши отиде за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'И кад јеђаше у кући, гле, многи цариници и грјешници дођоше и јеђаху с Исусом и с ученицима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'И видјевши то фарисеји говораху ученицима његовијем: зашто с цариницима и грјешницима учитељ ваш једе и пије?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'А Исус чувши то рече им: не требају здрави љекара него болесни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Него идите и научите се шта значи: милости хоћу, а не прилога. Јер ја нијесам дошао да зовем праведнике но грјешнике на покајање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Тада приступише к њему ученици Јованови говорећи: зашто ми и фарисеји постимо много, а ученици твоји не посте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'А Исус рече им: еда ли могу сватови плакати док је с њима женик? Него ће доћи вријеме кад ће се отети од њих женик, и онда ће постити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Јер нико не меће нове закрпе на стару хаљину; јер ће закрпа одадријети од хаљине, и гора ће рупа бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Нити се љева вино ново у мјехове старе; иначе мјехови продру се и вино се пролије, и мјехови пропадну. Него се љева вино ново у мјехове нове, и обоје се сачува.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Док он тако говораше њима, гле, кнез некакав дође и клањаше му се говорећи: кћи моја сад умрије; него дођи и метни на њу руку своју, и оживљеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'И уставши Исус за њим пође и ученици његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'И гле, жена која је дванаест година боловала од течења крви приступи састраг и дохвати му се скута од хаљине његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Јер говораше у себи: само ако се дотакнем хаљине његове, оздравићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'А Исус обазревши се и видјевши је рече: не бој се, кћери; вјера твоја помогла ти је. И оздрави жена од тога часа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'И дошавши Исус у дом кнежев и видјевши свираче и људе забуњене');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'Рече им: отступите, јер дјевојка није умрла, него спава. И потсмијеваху му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'А кад истјера људе, уђе, и ухвати је за руку, и уста дјевојка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'И отиде глас овај по свој земљи оној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'А кад је Исус одлазио оданде, за њим иђаху два слијепца вичући и говорећи: помилуј нас, сине Давидов!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'А кад дође у кућу, приступише к њему слијепци, и рече им Исус: вјерујете ли да могу то учинити? А они му рекоше: да Господе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Тада дохвати се очију њиховијех говорећи: по вјери вашој нека вам буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'И отворише им се очи. И запријети им Исус говорећи: гледајте да нико не дозна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'А они изишавши разгласише га по свој земљи оној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Кад они пак изиђу, гле, доведоше к њему човјека нијема и бијесна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'И пошто изгна ђавола, проговори нијеми. И дивљаше се народ говорећи: нигда се тога није видјело у Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'А фарисеји говораху: помоћу кнеза ђаволског изгони ђаволе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'И прохођаше Исус по свијем градовима и селима учећи по зборницама њиховијем и проповиједајући јеванђеље о царству, и исцјељујући сваку болест и сваку немоћ по људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'А гледајући људе сажали му се, јер бијаху сметени и расијани као овце без пастира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Тада рече ученицима својијем: жетве је много, а посленика мало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Молите се дакле господару од жетве да изведе посленике на жетву своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'И дозвавши својијех дванаест ученика даде им власт над духовима нечистијем да их изгоне, и да исцјељују од сваке болести и сваке немоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'А дванаест апостола имена су ова: први Симон, који се зове Петар, и Андрија брат његов; Јаков Зеведејев, и Јован брат његов;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Филип и Вартоломије; Тома и Матеј цариник; Јаков Алфејев, и Левеј прозвани Тадија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Симон Кананит, и Јуда Искариотски, који га и предаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Овијех дванаест посла Исус и заповједи им говорећи: на пут незнабожаца не идите, и у град Самарјански не улазите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Него идите к изгубљенијем овцама дома Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'А ходећи проповиједајте и казујте да се приближило царство небеско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Болесне исцјељујте, губаве чистите, мртве дижите, ђаволе изгоните; за бадава сте добили, за бадава и дајите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Не носите злата ни сребра ни мједи у појасима својијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Ни торбе на пут, ни двије хаљине ни обуће ни штапа; јер је посленик достојан свога јела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'А кад у који град или село уђете, испитајте ко је у њему достојан, и ондје останите док не изиђете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'А улазећи у кућу назовите јој: мир кући овој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'И ако буде кућа достојна, доћи ће мир ваш на њу; а ако ли не буде достојна, мир ће се ваш к вама вратити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'А ако вас ко не прими нити послуша ријечи вашијех, излазећи из куће или из града онога отресите прах с ногу својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Заисто вам кажем: лакше ће бити земљи Содомској и Гоморској у дан страшнога суда него ли граду ономе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Ето, ја вас шаљем као овце међу вукове: будите дакле мудри као змије и безазлени као голубови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'А чувајте се од људи; јер ће вас они предати судовима, и по зборницама својијем биће вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'И пред властеље и цареве водиће вас мене ради за свједочанство њима и незнабошцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'А кад вас предаду, не брините се како ћете или шта ћете говорити; јер ће вам се у онај час дати шта ћете казати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Јер ви не ћете говорити, него Дух оца вашега говориће из вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'А предаће брат брата на смрт и отац сина; и устаће дјеца на родитеље и побиће их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'И сви ће мрзити на вас имена мојега ради; али који претрпи до краја благо њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'А кад вас потјерају у једном граду, бјежите у други. Јер вам кажем заиста: нећете обићи градова Израиљевијех док дође син човјечиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Нема ученика над учитеља својега ни слуге над господара својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Доста је ученику да буде као учитељ његов и слузи као господар његов. Кад су домаћина назвали Веелзевулом, а камо ли домаће његове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Не бојте их се дакле; јер нема ништа сакривено што се неће открити, ни тајно што се неће дознати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Што вам говорим у тами, казујте на видику; и што вам се шапће на уши, проповиједајте с кровова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'И не бојте се онијех који убијају тијело а душе не могу убити; него се бојте онога који може и душу и тијело погубити у паклу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Не продају ли се два врапца за један динар? па ни један од њих не може пасти на земљу без оца вашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'А вама је и коса на глави сва избројена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Не бојте се дакле; ви сте бољи од много врабаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'А који год призна мене пред људима, признаћу и ја њега пред оцем својијем који је на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'А ко се одрече мене пред људима, одрећи ћу се и ја њега пред оцем својијем који је на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Не мислите да сам ја дошао да донесем мир на земљу; нијесам дошао да донесем мир него мач.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Јер сам дошао да раставим човјека од оца његова и кћер од матере њезине и снаху од свекрве њезине:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'И непријатељи човјеку (постаће) домашњи његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Који љуби оца или матер већма него мене, није мене достојан; и који љуби сина или кћер већма него мене, није мене достојан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'И који не узме крста својега и не пође за мном, није мене достојан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Који чува душу своју, изгубиће је; а који изгуби душу своју мене ради, наћи ће је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Који вас прима, мене прима; а који мене прима, прима онога који ме је послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Који прима пророка у име пророчко, плату пророчку примиће; а који прима праведника у име праведничко, плату праведничку примиће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'И ако ко напоји једнога од овијех малијех само чашом студене воде у име ученичко, заиста вам кажем, неће му плата пропасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'И кад сврши Исус заповијести дванаесторици ученика својијех, отиде оданде даље да учи и да проповиједа по градовима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'А Јован чувши у тамници дјела Христова посла двојицу ученика својијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'И рече му: јеси ли ти онај што ће доћи, или другога да чекамо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'А Исус одговарајући рече им: идите и кажите Јовану што чујете и видите:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Слијепи прогледају и хроми ходе, губави чисте се и глухи чују, мртви устају и сиромашнима проповиједа се јеванђеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'И благо ономе који се не саблазни о мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'А кад ови отидоше, поче Исус људима говорити о Јовану: шта сте изишли у пустињи да видите? Трску, коју љуља вјетар?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Или шта сте изишли да видите? Човјека у меке хаљине обучена? Ето, који меке хаљине носе по царскијем су дворовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Или шта сте изишли да видите? Пророка? Да, ја вам кажем, и више од пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Јер је ово онај за кога је писано: ето, ја шаљем анђела својега пред лицем твојијем, који ће приправити пут твој пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Заиста вам кажем: ни један између рођенијех од жена није изишао већи од Јована Крститеља; а најмањи у царству небескоме већи је од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'А од времена Јована Крститеља досад царство небеско на силу се узима, и силеџије добијају га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Јер су сви пророци и закон прорицали до Јована.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'И ако хоћете вјеровати, он је Илија што ће доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Који има уши да чује нека чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Али какав ћу казати да је овај род? Он је као дјеца која сједе по улицама и вичу својијем друговима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'И говоре: свирасмо вам, и не играсте; жалисмо вам се, и не јаукасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Јер Јован дође, који ни једе ни пије, а они кажу: ђаво је у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Дође син човјечиј, који и једе и пије, а они кажу: гле човјека изјелице и пијанице, друга цариницима и грјешницима. И оправдаше премудрост дјеца њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Тада поче Исус викати на градове у којима су се догодила највећа чудеса његова, па се нијесу покајали:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Тешко теби, Хоразине! Тешко теби, Витсаидо! Јер да су у Тиру и Сидону била чудеса која су била у вама, давно би се у врећи и пепелу покајали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Али вам кажем: Тиру и Сидону лакше ће бити у дан страшнога суда него вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'И ти, Капернауме! који си се до небеса подигао до пакла ћеш пропасти: јер да су у Содому била чудеса што су у теби била, остао би до данашњег дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Али вам кажем да ће земљи Содомској лакше бити у дан страшнога суда него теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'У то вријеме одговори Исус, и рече: хвалим те, оче, Господе неба и земље, што си ово сакрио од премудријех и разумнијех а казао си простима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Да, оче, јер је тако била воља твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Све је мени предао отац мој, и нико не зна сина до отац; нити оца ко зна до син и ако коме син хоће казати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Ходите к мени сви који сте уморни и натоварени, и ја ћу вас одморити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Узмите јарам мој на себе, и научите се од мене; јер сам ја кротак и смјеран у срцу, и наћи ћете покој душама својијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Јер је јарам мој благ, и бреме је моје лако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'У то вријеме иђаше Исус у суботу кроз усјеве: а ученици његови огладњеше, и почеше тргати класје, и јести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'А фарисеји видјевши то рекоше му: гле, ученици твоји чине што не ваља чинити у суботу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'А он рече им: нијесте ли читали што учини Давид кад огладње, он и који бијаху с њим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Како уђе у кућу Божију, и хљебове постављене поједе, којијех није ваљало јести њему ни онима што су били с њим, него самијем свештеницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Или нијесте читали у закону како у суботу свештеници у цркви суботу погане, па нијесу криви?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'А ја вам кажем да је овдје онај који је већи од цркве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Кад бисте пак знали шта је то: милости хоћу а не прилога, никад не бисте осуђивали правијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Јер је господар и од суботе син човјечиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'И отишавши оданде дође у зборницу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'И гле, човјек бијаше ту с руком сухом; и запиташе га говорећи: ваља ли у суботу лијечити? да би га окривили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'А он рече им: који је међу вама човјек који има овцу једну па ако она у суботу упадне у јаму неће је узети и извадити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'А колико је човјек претежнији од овце? Даклем ваља у суботу добро чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Тада рече човјеку: пружи руку своју. И пружи. И постаде здрава као и друга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'А фарисеји изишавши начинише вијећу о њему како би га погубили. Но Исус дознавши то уклони се оданде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'И за њим идоше људи многи, и исцијели их све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'И запријети им да га не разглашују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Да се збуде што је казао Исаија пророк говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Гле, слуга мој, кога сам изабрао, љубазни мој, који је по вољи душе моје: метнућу дух свој на њега, и суд незнабошцима јавиће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Неће се свађати ни викати, нити ће чути ко по распутицама гласа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Трске стучене неће преломити и свјештила запаљена неће угасити док правда не одржи побједе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'И у име његово уздаће се народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Тада доведоше к њему бијесна који бијаше нијем и слијеп; и исцијели га да нијеми и слијепи стаде говорити и гледати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'И дивљаху се сви људи говорећи: није ли ово Христос, син Давидов?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'А фарисеји чувши то рекоше: овај друкчије не изгони ђавола до помоћу Веелзевула кнеза ђаволскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'А Исус знајући мисли њихове рече им: свако царство које се раздијели само по себи, опустјеће; и сваки град или дом који се раздијели сам по себи, пропашће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'И ако сотона сотону изгони, сам по себи раздијелио се; како ће дакле остати царство његово?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'И ако ја помоћу Веелзевула изгоним ђаволе, синови ваши чијом помоћу изгоне? За то ће вам они бити судије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'А ако ли ја Духом Божијим изгоним ђаволе, дакле је дошло к вама царство небеско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Или како може ко ући у кућу јакога и покућтво његово отети, ако најприје не свеже јакога? и онда ће кућу његову оплијенити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Који није са мном, против мене је; и који не сабира са мном, просипа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Зато вам кажем: сваки гријех и хула опростиће се људима; а на Духа светога хула неће се опростити људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'И ако ко рече ријеч на сина човјечијега, опростиће му се; а који рече ријеч на Духа светога, неће му се опростити ни на овоме свијету ни на ономе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Или усадите дрво добро, и род његов биће добар; или усадите дрво зло, и род његов зао биће; јер се по роду дрво познаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Породи аспидини! како можете добро говорити, кад сте зли? јер уста говоре од сувишка срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Добар човјек из добре клијети износи добро; а зао човјек из зле клијети износи зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'А ја вам кажем да ће за сваку празну ријеч коју реку људи дати одговор у дан страшнога суда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Јер ћеш се својијем ријечима оправдати, и својијем ћеш се ријечима осудити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Тада одговорише неки од књижевника и фарисеја говорећи: учитељу! ми би ради од тебе знак видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'А он одговарајући рече им: род зли и прељуботворни тражи знак; и не ће му се дати знак осим знака Јоне пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Јер као што је Јона био у трбуху китовом три дана и три ноћи: тако ће бити и син човјечиј у срцу земље три дана и три ноћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Ниневљани изићи ће на суд с родом овијем, и осудиће га; јер се покајаше Јонинијем поучењем: а гле, овдје је већи од Јоне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Царица јужна изићи ће на суд с родом овијем, и осудиће га; јер она дође с краја земље да слуша премудрост Соломунову: а гле, овдје је већи од Соломуна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'А кад нечисти дух изиђе из човјека, иде кроз безводна мјеста тражећи покоја, и не нађе га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Онда рече: да се вратим у дом свој откуда сам изишао; и дошавши нађе празан, пометен и украшен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Тада отиде и узме седам другијех духова горијех од себе, и ушавши живе ондје; и буде потоње горе човјеку ономе од првога. Тако ће бити и овоме роду зломе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Док он још говораше с људима, гле, мати његова и браћа његова стајаху на пољу и чекаху да говоре с њиме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'И неко му рече: ево мати твоја и браћа твоја стоје напољу, ради су да говоре с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'А он одговори и рече ономе што му каза: ко је мати моја, и ко су браћа моја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'И пруживши руку своју на ученике своје рече: ето мати моја и браћа моја. Јер ко извршује вољу оца мојега који је на небесима, онај је брат мој и сестра и мати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'И онај дан изишавши Исус из куће сјеђаше крај мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'И сабраше се око њега људи многи, тако да мора ући у лађу и сјести; а народ сав стајаше по бријегу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'И он им казива много у причама говорећи: гле, изиђе сијач да сије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'И кад сијаше, једна зрна падоше крај пута, и дођоше птице и позобаше их;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'А друга падоше на каменита мјеста, гдје не бијаше много земље, и одмах изникоше; јер не бијаше у дубину земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'И кад обасја сунце, повенуше, и будући да немаху жила, посахнуше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'А друга падоше у трње, и нарасте трње, и подави их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'А друга падоше на земљу добру, и доношаху род, једно по сто, а једно по шесет, а једно по тридесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Ко има уши да чује нека чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'И приступивши ученици рекоше му: зашто им говориш у причама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'А он одговарајући рече им: вама је дано да знате тајне царства небескога, а њима није дано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Јер ко има, даће му се, и претећи ће му; а који нема, узеће му се и оно што има.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Зато им говорим у причама, јер гледајући не виде, и чујући не чују нити разумију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'И збива се на њима пророштво Исаијно, које говори: ушима ћете чути, и нећете разумјети; и очима ћете гледати, и нећете видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Јер је одрвенило срце овијех људи, и ушима тешко чују, и очи су своје затворили да како не виде очима, и ушима не чују, и срцем не разумију, и не обрате се да их исцијелим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'А благо вашијем очима што виде, и ушима вашијем што чују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Јер вам кажем заиста да су многи пророци и праведници жељели видјети што ви видите, и не видјеше; и чути што ви чујете, и не чуше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Ви пак чујте причу о сијачу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Свакоме који слуша ријеч о царству и не разумије, долази нечастиви и краде посијано у срцу његовом: то је око пута посијано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'А на камену посијано то је који слуша ријеч и одмах с радости прими је,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'Али нема коријена у себи, него је непостојан, па кад буде до невоље или га потерају ријечи ради, одмах удари натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'А посијано у трњу то је који слуша ријеч, но брига овога свијета и пријевара богатства загуше ријеч, и без рода остане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'А посијано на доброј земљи то је који слуша ријеч и разумије, који дакле и род рађа, и доноси један по сто, а један по шесет, а један по тридесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Другу причу каза им говорећи: царство је небеско као човјек који посија добро сјеме у пољу својему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'А кад људи поспаше, дође његов непријатељ и посија кукољ по пшеници, па отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'А кад ниче усјев и род донесе, онда се показа кукољ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Тада дођоше слуге домаћинове и рекоше му: господару! нијеси ли ти добро сјеме сијао на својој њиви? Откуда дакле кукољ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'А он рече им: непријатељ човјек то учини. А слуге рекоше му: хоћеш ли дакле да идемо да га почупамо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'А он рече: не; да не би чупајући кукољ почупали заједно с њиме пшеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Оставите нека расте обоје заједно до жетве; и у вријеме жетве рећи ћу жетеоцима: саберите најприје кукољ, и свежите га у снопље да га сажежем; а пшеницу свезите у житницу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Другу причу каза им говорећи: царство је небеско као зрно горушичино које узме човјек и посије на њиви својој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Које је истина најмање од свију сјемена, али кад узрасте, веће је од свега поврћа, и буде дрво да птице небеске долазе, и сједају на његовијем гранама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Другу причу каза им: царство је небеско као квасац који узме жена и метне у три копање брашна док све не ускисне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Све ово у причама говори Исус људима, и без приче ништа не говораше им:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'Да се збуде што је казао пророк говорећи: отворићу у причама уста своја, казаћу сакривено од постања свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Тада остави Исус људе, и дође у кућу. И приступише к њему ученици његови говорећи: кажи нам причу о кукољу на њиви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'А он одговарајући рече им: који сије добро сјеме оно је син човјечиј;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'А њива је свијет; а добро сјеме синови су царства, а кукољ синови су зла;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'А непријатељ који га је посијао јест ђаво; а жетва је пошљедак овога вијека; а жетеоци су анђели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Како што се дакле кукољ сабира, и огњем сажиже, тако ће бити на пошљетку овога вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Послаће син човјечиј анђеле своје, и сабраће из царства његова све саблазни и који чине безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'И бациће их у пећ огњену: ондје ће бити плач и шкргут зуба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Тада ће се праведници засјати као сунце у царству оца својега. Ко има уши да чује нека чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Још је царство небеско као благо сакривено у пољу, које нашавши човјек сакри и од радости зато отиде и све што има продаде и купи поље оно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Још је царство небеско као човјек трговац који тражи добра бисера,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Па кад нађе једно многоцјено зрно бисера, отиде и продаде све што имаше и купи га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Још је царство небеско као мрежа која се баци у море и заграби од сваке руке рибе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Која кад се напуни, извукоше је на крај, и сједавши, избраше добре у судове, а зле бацише напоље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Тако ће бити на пошљетку вијека: изићи ће анђели и одлучиће зле од праведнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'И бациће их у пећ огњену: ондје ће бити плач и шкргут зуба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Рече им Исус: разумјесте ли ово? Рекоше му: да, Господе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'А он им рече: зато је сваки књижевник који се научио царству небескоме као домаћин који износи из клијети своје ново и старо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'И кад сврши Исус приче ове, отиде оданде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'И дошавши на постојбину своју, учаше их по зборницама њиховијем тако да му се дивљаху, и говораху: откуд овоме премудрост ова и моћи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Није ли ово дрводјељин син? не зове ли се мати његова Марија, и браћа његова Јаков, и Јосија, и Симон, и Јуда?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'И сестре његове нијесу ли све код нас? Откуд њему ово све?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'И саблажњаваху се о њега. А Исус рече им: нема пророка без части осим на постојбини својој и у дому својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'И не створи ондје чудеса многијех за невјерство њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'У то вријеме дође глас до Ирода четворовласника о Исусу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'И рече слугама својијем: то је Јован крститељ; он устаде из мртвијех, и зато чини чудеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Јер Ирод ухвати Јована, свеза га и баци у тамницу Иродијаде ради жене Филипа брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Јер му говораше Јован: не можеш ти ње имати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'И шћаше да га убије, али се побоја народа; јер га држаху за пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'А кад бијаше дан рођења Иродова, игра кћи Иродијадина пред њима и угоди Ироду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Зато и с клетвом обрече јој дати што год заиште.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'А она научена од матере своје: дај ми, рече, овдје на кругу главу Јована крститеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'И забрину се цар; али клетве ради и онијех који се гошћаху с њим, заповједи јој дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'И посла те посјекоше Јована у тамници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'И донесоше главу његову на кругу, и дадоше дјевојци, и однесе је матери својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'И дошавши ученици његови, узеше тијело његово и укопаше га; и дођоше Исусу те јавише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'И чувши Исус, отиде оданде у лађи у пусто мјесто насамо. А кад то чуше људи, идоше за њим пјешице из градова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'И изашавши Исус видје многи народ, и сажали му се за њих, и исцијели болеснике њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'А пред вече приступише к њему ученици његови говорећи: овдје је пусто мјесто, а доцкан је већ; отпусти народ нека иде у села да купи себи хране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'А Исус рече им: не треба да иду; подајте им ви нека једу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'А они рекоше му: немамо овдје до само пет хљебова и двије рибе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'А он рече: донесите ми их овамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'И заповједи народу да посједају по трави; па узе онијех пет хљебова и двије рибе, и погледавши на небо благослови, и преломивши даде ученицима својијем, а ученици народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'И једоше сви, и наситише се, и накупише комада што претече дванаест котарица пунијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'А онијех што су јели бјеше људи око пет хиљада, осим жена и дјеце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'И одмах натјера Исус ученике своје да уђу у лађу и напријед да иду на ону страну док он отпусти народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'И отпустивши народ попе се на гору сам да се моли Богу. И увече бијаше ондје сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'А лађа бјеше насред мора у невољи од валова, јер бијаше противан вјетар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'А у четврту стражу ноћи отиде к њима Исус идући по мору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'И видјевши га ученици по мору гдје иде, поплашише се говорећи: то је утвара; и од страха повикаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'А Исус одмах рече им говорећи: не бојте се; ја сам, не плашите се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'А Петар одговарајући рече: Господе! ако си ти, реци ми да дођем к теби по води.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'А он рече: ходи. И изишавши из лађе Петар иђаше по води да дође к Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Но видјећи вјетар велики уплаши се, и почевши се топити, повика говорећи: Господе, помагај!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'И одмах Исус пруживши руку ухвати Петра, и рече му: маловјерни! зашто се посумња?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'И кад уђоше у лађу, преста вјетар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'А који бијаху у лађи приступише и поклонише му се говорећи: ваистину ти си син Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'И прешавши дођоше у земљу Генисаретску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'И познавши га људи из онога мјеста, послаше по свој оној околини, и донесоше к њему све болеснике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'И мољаху га да се само дотакну скута од његове хаљине; и који се дотакоше оздравише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Тада приступише к Исусу књижевници и фарисеји од Јерусалима говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Зашто ученици твоји преступају обичаје старијех? Јер не умивају руку својијех кад хљеб једу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'А он одговарајући рече им: зашто и ви преступате заповијест Божију за обичаје своје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Јер Бог заповиједа говорећи: поштуј оца и матер; и који опсује оца или матер смрћу да умре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'А ви кажете: ако који рече оцу или матери: прилог је чим бих ти ја могао помоћи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Може и да не поштује оца својега или матере. И укидосте заповијест Божију за обичаје своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Лицемјери! добро је за вас пророковао Исаија говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Ови људи приближавају се к мени устима својијем, и уснама поштују ме; а срце њихово далеко стоји од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Но залуду ме поштују учећи наукама и заповијестима људскима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'И дозвавши људе, рече им: слушајте и разумијте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Не погани човјека што улази у уста; него што излази из уста оно погани човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Тада приступише ученици његови и рекоше му: знаш ли да фарисеји чувши ту ријеч саблазнише се?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'А он одговарајући рече: свако дрво које није усадио отац мој небески, искоријениће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Оставите их: они су слијепи вођи слијепцима; а слијепац слијепца ако води, оба ће у јаму пасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'А Петар одговарајући рече му: кажи нам причу ову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'А Исус рече: еда ли сте и ви још неразумни?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Зар још не знате да све што улази у уста у трбух иде, и избацује се напоље?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'А што излази из уста из срца излази, и оно погани човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Јер од срца излазе зле мисли, убиства, прељубе, курварства, крађе, лажна свједочанства, хуле на Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'И ово је што погани човјека, а неумивенијем рукама јести не погани човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'И изишавши оданде Исус отиде у крајеве Тирске и Сидонске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'И гле, жена Хананејка изађе из онијех крајева, и повика к њему говорећи: помилуј ме Господе сине Давидов! моју кћер врло мучи ђаво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'А он јој не одговори ни ријечи. И приступивши ученици његови мољаху га говорећи: отпусти је, како виче за нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'А он одговарајући рече: ја сам послан само к изгубљенијем овцама дома Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'А она приступивши поклони му се говорећи: Господе помози ми!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'А он одговарајући рече: није добро узети од дјеце хљеб и бацити псима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'А она рече: да, Господе, али и пси једу од мрва што падају с трпезе њиховијех господара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Тада одговори Исус, и рече јој: о жено! велика је вјера твоја; нека ти буде како хоћеш. И оздрави кћи њезина од онога часа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'И отишавши Исус оданде, дође к мору Галилејском, и попевши се на гору, сједе ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'И приступише к њему људи многи који имаху са собом хромијех, слијепијех, нијемијех, узетијех и другијех многијех, и положише их к ногама Исусовијем, и исцијели их,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'Тако да се народ дивљаше, видећи нијеме гдје говоре, узете здраве, хроме гдје иду, и слијепе гдје гледају; и хвалише Бога Израиљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'А Исус дозвавши ученике своје рече: жао ми је овога народа, јер већ три дана стоје код мене и немају шта јести; а нијесам их рад отпустити гладне да не ослабе на путу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'И рекоше му ученици његови: откуда нам у пустињи толики хљеб да се насити толики народ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'И рече им Исус: колико хљебова имате? А они рекоше: седам, и мало рибице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'И заповједи народу да посједају по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'И узевши онијех седам хљебова и рибе, и давши хвалу, преломи, и даде ученицима својијем, а ученици народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'И једоше сви, и наситише се; и накупише комада што претече седам котарица пунијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'А онијех што су јели бијаше четири хиљаде људи, осим жена и дјеце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'И отпустивши народ уђе у лађу, и дође у околине Магдалске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'И приступише к њему фарисеји и садукеји, и кушајући га искаху да им покаже знак с неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'А он одговарајући рече им: увече говорите: биће ведро; јер је небо црвено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'И ујутру: данас ће бити вјетар, јер је небо црвено и мутно. Лицемјери! лице небеско умијете познавати, а знаке времена не можете познати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Род зли и курварски тражи знак, и знак неће му се дати осим знака Јоне пророка. И оставивши их отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'И полазећи ученици његови на ону страну заборавише узети хљеба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'А Исус рече им: чувајте се квасца фарисејскога и садукејскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'А они мишљаху у себи говорећи: то је што нијесмо хљеба узели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'А Исус разумјевши рече им: шта мислите у себи, маловјерни, што хљеба нијесте узели?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Зар још не разумијете нити памтите пет хљебова на пет хиљада, и колико котарица накуписте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Ни седам хљебова на четири хиљаде, и колико котарица накуписте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Како не разумијете да вам не рекох за хљебове да се чувате квасца фарисејскога и садукејскога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Тада разумјеше да не рече квасца хљебнога да се чувају, него науке фарисејске и садукејске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'А кад дође Исус у околине Ћесарије Филипове, питаше ученике своје говорећи: ко говоре људи да је син човјечији?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'А они рекоше: једни говоре да си Јован крститељ, други да си Илија, а други Јеремија, или који од пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Рече им Исус: а ви шта мислите ко сам ја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'А Симон Петар одговори и рече: ти си Христос, син Бога живога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'И одговарајући Исус рече му: благо теби, Симоне сине Јонин! Јер тијело и крв нијесу то теби јавили, него отац мој који је на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'А и ја теби кажем: ти си Петар, и на овоме камену сазидаћу цркву своју, и врата паклена неће је надвладати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'И даћу ти кључеве од царства небескога: и што свежеш на земљи биће свезано на небесима, и што раздријешиш на земљи биће раздријешено на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Тада запријети Исус ученицима својијем да ником не казују да је он Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Отада поче Исус казивати ученицима својијем да њему ваља ићи у Јерусалим, и много пострадати од старјешина и од главара свештеничкијех и књижевника, и да ће га убити, и трећи дан да ће устати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'И узевши га Петар поче га одвраћати говорећи: Боже сачувај! неће то бити од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'А он обрнувши рече Петру: иди од мене сотоно; ти си ми саблазан; јер не мислиш што је Божије него људско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Тада Исус рече ученицима својијем: ако ко хоће за мном ићи, нека се одрече себе, и узме крст свој и иде за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Јер ко хоће своју душу да сачува, изгубиће је; а ако ко изгуби душу своју мене ради, наћи ће је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Јер каква је корист човјеку ако сав свијет добије а души својој науди? или какав ће откуп дати човјек за своју душу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Јер ће доћи син човјечиј у слави оца својега с анђелима својијем, и тада ће се вратити свакоме по дјелима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Заиста вам кажем: имају неки међу овима што стоје овдје који неће окусити смрти док не виде сина човјечијега гдје иде у царству својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'И послије шест дана узе Исус Петра и Јакова и Јована брата његова, и изведе их на гору високу саме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'И преобрази се пред њима, и засја се лице његово као сунце а хаљине његове постадоше бијеле као свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'И гле, указаше им се Мојсије и Илија, који с њим говораху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'А Петар одговарајући рече Исусу: Господе! добро нам је овдје бити; ако хоћеш да начинимо овдје три сјенице: теби једну, а Мојсију једну, а једну Илији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Док он још говораше, гле, облак сјајан заклони их; и гле, глас из облака говорећи: ово је син мој љубазни, који је по мојој вољи; њега послушајте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'И чувши ученици падоше ничице, и уплашише се врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'И приступивши Исус дохвати их се, и рече: устаните, и не бојте се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'А они подигнувши очи своје никога не видјеше до Исуса сама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'И силазећи с горе заповједи им Исус говорећи: ником не казујте што сте видјели док син човјечиј из мртвијех не устане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'И запиташе их ученици његови говорећи: зашто дакле књижевници кажу да Илија најприје треба да дође?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'А Исус одговарајући рече им: Илија ће доћи најприје и уредити све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Али вам кажем да је Илија већ дошао, и не познаше га; него учинише с њиме шта хтјеше: тако и син човјечиј треба да пострада од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Тада разумјеше ученици да им говори за Јована крститеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'И кад дођоше к народу, приступи к њему човјек клањајући му се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'И говорећи: Господе! помилуј сина мојега; јер о мијени бјесни и мучи се врло; јер много пута пада у ватру, и много пута у воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'И доведох га ученицима твојијем, и не могоше га исцијелити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'А Исус одговарајући рече: о роде невјерни и покварени! докле ћу бити с вама? докле ћу вас трпљети? Доведите ми га амо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'И запријети му Исус; и ђаво изиђе из њега, и оздрави момче од онога часа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Тада приступише ученици к Исусу и насамо рекоше му: зашто га ми не могосмо изгнати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'А Исус рече им: за невјерство ваше. Јер вам кажем заиста: ако имате вјере колико зрно горушичино, рећи ћете гори овој: пријеђи одавде тамо, и пријећи ће, и ништа неће вам бити немогуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'А овај се род изгони само молитвом и постом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'А кад су ходили по Галилеји, рече им Исус: предаће се син човјечиј у руке људске;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'И убиће га, и трећи дан устаће. И невесели бијаху врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'А кад дођоше у Капернаум, приступише к Петру они што купе дидрахме, и рекоше: зар ваш учитељ неће дати дидрахме?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Петар рече: хоће. И кад уђе у кућу, претече га Исус говорећи: шта мислиш Симоне? Цареви земаљски од кога узимају порезе и хараче, или од својијех синова или од туђијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Рече њему Петар: од туђијех. Рече му Исус: дакле не плаћају синови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Али да их не саблазнимо, иди на море, и баци удицу, и коју прву ухватиш рибу, узми је; и кад јој отвориш уста наћи ћеш статир; узми га те им подај за ме и за се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'У тај час приступише к Исусу ученици говорећи: ко је дакле највећи у царству небескоме?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'И дозва Исус дијете, и постави га међу њих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'И рече им: заиста вам кажем, ако се не повратите и не будете као дјеца, нећете ући у царство небеско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Који се дакле понизи као дијете ово, онај је највећи у царству небескоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'И који прими таково дијете у име моје, мене прима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'А који саблазни једнога од овијех малијех који вјерују мене, боље би му било да се објеси камен воденични о врату његову, и да потоне у дубину морску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Тешко свијету од саблазни! јер је потребно да дођу саблазни; али тешко оном човјеку кроз кога долази саблазан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Ако ли те рука твоја или нога твоја саблажњава, отсијеци је и баци од себе: боље ти је ући у живот хрому или кљасту, него ли с двије руке и двије ноге да те баце у огањ вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'И ако те око твоје саблажњава, извади га и баци од себе: боље ти је с једнијем оком у живот ући, него с два ока да те баце у пакао огњени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Гледајте да не презрете једнога од малијех овијех; јер вам кажем да анђели њихови на небесима једнако гледају лице оца мојега небескога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Јер син човјечиј дође да изнађе и спасе изгубљено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Што вам се чини? Кад има један човјек сто оваца па зађе једна од њих, не остави ли он деведесет и девет у планини, и иде да тражи ону што је зашла?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'И ако се догоди да је нађе, заиста вам кажем да се њој више радује него онима деведесет и девет што нијесу зашле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Тако није воља оца вашега небескога да погине један од овијех малијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Ако ли ти сагријеши брат твој, иди и покарај га међу собом и њим самијем; ако те послуше, добио си брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Ако ли те не послуша, узми са собом још једнога или двојицу да све ријечи остану на устима два или три свједока.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Ако ли њих не послуша, кажи цркви; а ако ли не послуша ни цркве, да ти буде као незнабожац и цариник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Јер вам кажем заиста: што год свежете на земљи биће свезано на небу, и што год раздријешите на земљи биће раздријешено на небу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Још вам кажем заиста: ако се два од вас сложе на земљи у чему му драго, за што се узмоле, даће им отац мој који је на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Јер гдје су два или три сабрани у име моје ондје сам ја међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Тада приступи к њему Петар и рече: Господе! колико пута ако ми сагријеши брат мој да му опростим? до седам пута?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Рече њему Исус: не велим ти до седам пута, него до седам пута седамдесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Зато је царство небеско као човјек цар који намисли да се прорачуни са својијем слугама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'И кад се поче рачунити, доведоше му једнога дужника од десет хиљада таланата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'И будући да немаше чим платити, заповједи господар његов да га продаду, и жену његову и дјецу, и све што има; и да му се плати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Но слуга тај паде и клањаше му се говорећи: господару! причекај ме, и све ћу ти платити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'А господару се сажали за тијем слугом, пусти га и дуг опрости му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'А кад изиђе слуга тај, нађе једнога од својијех другара који му је дужан сто гроша, и ухвативши га дављаше га говорећи: дај ми што си дужан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Паде другар његов пред ноге његове и мољаше га говорећи: причекај ме, и све ћу ти платити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'А он не хтје, него га одведе и баци у тамницу док не плати дуга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Видјевши пак другари његови тај догађај жао им би врло, и отишавши казаше господару својему сав догађај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Тада га дозва господар његов, и рече му: зли слуго! сав дуг овај опростих теби, јер си ме молио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Није ли требало да се и ти смилујеш на свог другара, као и ја на те што се смиловах?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'И разгњеви се господар његов, и предаде га мучитељима док не плати сав дуг свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Тако ће и отац мој небески учинити вама, ако не опростите сваки брату својему од срца својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'И кад сврши Исус ријечи ове, отиде из Галилеје, и дође у околине Јудејске преко Јордана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'И за њим идоше људи многи и исцијели их ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'И приступише к њему фарисеји да га кушају, и рекоше му: може ли човјек пустити жену своју за сваку кривицу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'А он одговарајући рече им: нијесте ли читали да је онај који је у почетку створио човјека мужа и жену створио их?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'И рече: зато оставиће човјек оца својега и матер, и прилијепиће се к жени својој, и биће двоје једно тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Тако нијесу више двоје, него једно тијело; а што је Бог саставио човјек да не раставља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Рекоше му: зашто дакле Мојсије заповиједа да се да књига распусна, и да се пусти?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Рече им: Мојсије је вама допустио по тврђи вашега срца пуштати своје жене; а из почетка није било тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Него ја вама кажем: ако ко пусти своју жену, осим за курварство, и ожени се другом, чини прељубу; и који узме пуштеницу чини прељубу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Рекоше му ученици његови: ако је тако човјеку са женом, није се добро женити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'А он рече им: не могу сви примити тијех ријечи до они којима је дано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Јер има ушкопљеника који су се тако родили из утробе материне; а има ушкопљеника које су људи ушкопили; а има ушкопљеника који су сами себе ушкопили царства ради небескога. Ко може примити нека прими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Тада приведоше к њему дјецу да метне руке на њих, и да се помоли Богу; а ученици забрањиваху им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'А Исус рече: Оставите дјецу и не забрањујте им долазити к мени; јер је таковијех царство небеско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'И метнувши на њих руке отиде оданде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'И гле, неко приступивши рече му: учитељу благи! каково ћу добро да учиним да имам живот вјечни?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'А он рече му: што ме зовеш благијем? нико није благ осим једнога Бога. А ако желиш ући у живот, држи заповијести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Рече му: које? А Исус рече: да не убијеш; не чиниш прељубе; не украдеш; не свједочиш лажно;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'Поштуј оца и матер; и љуби ближњега свога као самог себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Рече му младић: све сам ово сачувао од младости своје; шта ми још треба?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Рече му Исус: ако хоћеш савршен да будеш, иди и продај све што имаш и подај сиромасима; и имаћеш благо на небу; па хајде за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'А кад чу младић ријеч, отиде жалостан; јер бијаше врло богат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'А Исус рече ученицима својијем: заиста вам кажем да је тешко богатоме ући у царство небеско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'И још вам кажем: лакше је камили проћи кроз иглене уши него ли богатоме ући у царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'А кад то чуше ученици, дивљаху се врло говорећи: ко се дакле може спасити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'А Исус погледавши на њих рече им: људима је ово немогуће, а Богу је све могуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Тада одговори Петар и рече му: ето ми смо оставили све и за тобом идемо: шта ће дакле бити нама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'А Исус рече им: заиста вам кажем да ће те ви који идете за мном, у другом рођењу, кад сједе син човјечиј на пријестолу славе своје, сјешћете и ви на дванаест пријестола и судити над дванаест кољена Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'И сваки, који остави куће, или браћу, или сестре, или оца, или матер, или жену, или дјецу, или земљу, имена мојега ради, примиће сто пута онолико, и добиће живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Али ће многи први бити пошљедњи и пошљедњи први.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Јер је царство небеско као човјек домаћин који ујутру рано изиђе да наима посленике у виноград свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'И погодивши се с посленицима по грош на дан посла их у виноград свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'И изишавши у трећи сахат, видје друге гдје стоје на чаршији беспослени,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'И њима рече: идите и ви у мој виноград, и што буде право даћу вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'И они отидоше. И опет изишавши у шести и девети сахат, учини тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'И у једанаести сахат изишавши нађе друге гдје стоје беспослени, и рече им: што стојите овдје вас дан беспослени?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Рекоше му: нико нас не најми. Рече им: идите и ви у мој виноград, и што буде право примићете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'А кад би у вече, рече господар од винограда к приставу својему: дозови посленике и подај им плату почевши од пошљедњијех до првијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'И дошавши који су у једанаести сахат најмљени примише по грош.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'А кад дођоше први, мишљаху да ће више примити: и примише и они по грош.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'И примивши викаху на господара');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Говорећи: Ови пошљедњи један сахат радише, и изједначи их с нама који смо се читав дан мучили и горјели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'А он одговарајући рече једноме од њих: пријатељу! ја теби не чиним криво; нијеси ли погодио са мном по грош?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Узми своје па иди; а ја хоћу и овоме пошљедњему да дам као и теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Или зар ја нијесам властан у својему чинити шта хоћу? Зар је око твоје зло што сам ја добар?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Тако ће бити пошљедњи први и први пошљедњи; јер је много званијех а мало избранијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'И пошавши Исус у Јерусалим узе насамо дванаест ученика на путу, и рече им:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Ево идем у Јерусалим, и син човјечиј биће предан главарима свештеничкијем и књижевницима; и осудиће га на смрт;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'И предаће га незнабошцима да му се ругају и да га бију и разапну; и трећи дан устаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Тада приступи к њему мати синова Зеведејевијех са својијем синовима клањајући му се и молећи га за нешто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'А он јој рече: шта хоћеш? Рече му: заповједи да сједу ова моја два сина, један с десне стране теби, а један с лијеве стране теби, у царству твојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'А Исус одговарајући рече: не знате шта иштете; можете ли пити чашу коју ћу ја пити, и крстити се крштењем којијем се ја крстим? Рекоше му: можемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'И рече им: чашу дакле моју испићете, и крстићете се крштењем којијем се ја крстим; али да сједете с десне стране мени и с лијеве, не могу ја дати, него коме је уготовио отац мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'И кад чуше осталијех десет ученика, расрдише се на та два брата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'А Исус дозвавши их рече: знајте да кнезови народни заповиједају народу, и поглавари управљају њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Али међу вама да не буде тако; него који хоће да буде већи међу вама, да вам служи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'И који хоће међу вама да буде први, да вам буде слуга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Као што ни син човјечиј није дошао да му служе, него да служи и да душу своју у откуп да за многе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'И кад је излазио из Јерихона за њим иде народ многи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'И гле, два слијепца сјеђаху крај пута, и чувши да Исус пролази повикаше говорећи: помилуј нас Господе, сине Давидов!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'А народ пријећаше им да ућуте; а они још већма повикаше говорећи: помилуј нас Господе, сине Давидов!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'И уставивши се Исус дозва их, и рече: шта хоћете да вам учиним?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Рекоше му: Господе, да се отворе очи наше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'И смилова се Исус, и дохвати се очију њиховијех, и одмах прогледаше очи њихове, и отидоше за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'И кад се приближише к Јерусалиму и дођоше у Витфагу к Маслинској гори, онда Исус посла два ученика');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'Говорећи им: идите у село што је према вама, и одмах ћете наћи магарицу привезану и магаре с њом: одријешите је и доведите ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'И ако вам ко рече што, кажите да они требају Господу; и одмах ће их послати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'А ово је све било да се збуде што је казао пророк говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, 'Кажите кћери Сионовој: ево цар твој иде теби кротак, и јаше на магарцу, и магарету сину магаричину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'И ученици отидоше, и учинивши како им заповједи Исус');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Доведоше магарицу и магаре, и метнуше на њих хаљине своје, и посадише га на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'А људи многи простријеше хаљине своје по путу; а други резаху грање од дрвета и простираху по путу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'А народ који иђаше пред њим и за њим, викаше говорећи: Осана Сину Давидову! благословен који иде у име Господње! Осана на висини!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'И кад он уђе у Јерусалим, узбуни се сав град говорећи: ко је то?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'А народ говораше: Ово је Исус пророк из Назарета Галилејскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'И уђе Исус у цркву Божију, и изгна све који продаваху и куповаху по цркви, и испремета трпезе онијех што мијењаху новце, и клупе онијех што продаваху голубове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'И рече им: у писму стоји: дом мој дом молитве нека се зове; а ви начинисте од њега пећину хајдучку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'И приступише к њему хроми и слијепи у цркви, и исцијели их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'А кад видјеше главари свештенички и књижевници чудеса што учини, и дјецу гдје вичу у цркви и говоре: Осана сину Давидову, расрдише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'И рекоше му: чујеш ли што ови говоре? А Исус рече им: да! зар нијесте никад читали: из уста мале дјеце и која сисају начинио си себи хвалу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'И оставивши их изађе напоље из града у Витанију, и заноћи ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'А ујутру враћајући се у град огладње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'И угледавши смокву једну крај пута дође к њој, и не нађе ништа на њој до лишће само, и рече јој: да никад на теби не буде рода довијека. И одмах усахну смоква.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'И видјевши то ученици дивише се говорећи: како одмах усахну смоква!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'А Исус одговарајући рече им: заиста вам кажем: ако имате вјеру и не посумњате, не само смоквено учинићете, него и гори овој ако речете: дигни се и баци се у море, биће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'И све што узиштете у молитви вјерујући, добићете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'И кад дође у цркву и стаде учити, приступише к њему главари свештенички и старјешине народне говорећи: каквом власти то чиниш? и ко ти даде власт ту?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'А Исус одговарајући рече им: ја ћу вас упитати једну ријеч, коју ако ми кажете, и ја ћу вама казати каквом власти ово чиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Крштење Јованово откуда би? или с неба, или од људи? А они помишљаваху у себи говорећи: а ако речемо: с неба, рећи ће нам: зашто му дакле не вјеровасте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Ако ли речемо: од људи, бојимо се народа! јер сви Јована држаху за пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'И одговарајући Исусу рекоше: не знамо. Рече и он њима: ни ја вама нећу казати каквом власти ово чиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Шта вам се чини? Човјек неки имаше два сина; и дошавши к првоме рече: сине! иди данас ради у винограду моме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'А он одговарајући рече: нећу; а послије се раскаја и отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'И приступивши к другоме рече тако. А он одговарајући рече: хоћу, господару; и не отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Који је од ове двојице испунио вољу очину? Рекоше му: први. Рече им Исус: заиста вам кажем да ће цариници и курве прије вас ући у царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Јер дође к вама Јован путем праведнијем, и не вјеровасте му; а цариници и курве вјероваше му; и ви пошто видјесте то, не раскајасте се да му вјерујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Другу причу чујте: бијаше човјек домаћин који посади виноград, и огради га плотом, и ископа у њему пивницу, и начини кулу, и даде га виноградарима и отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'А кад се приближи вријеме родовима, посла слуге своје к виноградарима да приме родове његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'И виноградари похватавши слуге његове једнога избише, а једнога убише, а једнога засуше камењем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Опет посла друге слуге, више него прије, и учинише им тако исто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'А потом посла к њима сина својега говорећи: постидјеће се сина мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'А виноградари видјевши сина рекоше међу собом: ово је нашљедник; ходите да га убијемо, и да нама остане достојање његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'И ухватише га, па изведоше га напоље из винограда, и убише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Кад дође дакле господар од винограда шта ће учинити виноградарима онијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Рекоше му: злочинце ће злом смрти поморити; а виноград даће другијем виноградарима, који ће му давати родове у своје вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'А рече им Исус: зар нијесте никад читали у писму: камен који одбацише зидари, он је постао глава од угла; то би од Господа и дивно је у вашијем очима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Зато вам кажем да ће се од вас узети царство Божије, и даће се народу који његове родове доноси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'И ко падне на овај камен разбиће се; а на кога он падне сатрће га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'И чувши главари свештенички и фарисеји приче његове разумјеше да за њих говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'И гледаху да га ухвате, али се побојаше народа, јер га држаху за пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'И одговарајући Исус опет рече им у причама говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Царство је небеско као човјек цар који начини свадбу сину својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'И посла слуге своје да зову званице на свадбу; и не хтјеше доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Опет посла друге слуге говорећи: кажите званицама: ево сам објед свој уготовио, и јунци моји и храњеници поклани су, и све је готово; дођите на свадбу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'А они не маривши отидоше овај у поље своје, а овај к трговини својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'А остали ухватише слуге његове, изружише их, и побише их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'А кад то чу цар онај, разгњеви се и пославши војску своју погуби крвнике оне, и град њихов запали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Тада рече слугама својима: свадба је дакле готова, а званице не бише достојне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Идите дакле на раскршћа и кога год нађете, дозовите на свадбу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'И изишавши слуге оне на раскршћа сабраше све које нађоше, зле и добре; и столови напунише се гостију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Изашавши пак цар да види госте угледа ондје човјека необучена у свадбено рухо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'И рече му: пријатељу! како си дошао амо без свадбенога руха? А он оћутје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Тада рече цар слугама: свежите му руке и ноге, па га узмите те баците у таму најкрајњу; ондје ће бити плач и шкргут зуба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Јер су многи звани, али је мало избранијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Тада отидоше фарисеји и начинише вијећу како би га ухватили у ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'И послаше к њему ученике своје с Иродовцима, те рекоше: учитељу! знамо да си истинит, и путу Божијему заиста учиш, и не мариш ни за кога, јер не гледаш ко је ко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Кажи нам дакле шта мислиш ти? Треба ли дати харач ћесару или не?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Разумјевши Исус лукавство њихово рече: што ме кушате, лицемјери?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Покажите ми новац харачки. А они донесоше му новац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'И рече им: чији је образ овај и натпис?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'И рекоше Му: ћесарев. Тада рече им: подајте дакле ћесарово ћесару, и Божије Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'И чувши дивише се, и оставивши га отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Тај дан приступише к њему садукеји који говоре да нема васкрсенија, и упиташе га');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'Говорећи: Учитељу! Мојсије рече: ако ко умре без дјеце, да узме брат његов жену његову и да подигне сјеме брату својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'У нас бјеше седам браће; и први оженивши се умрије, и не имавши порода остави жену своју брату својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'А тако и други, и трећи, тја до седмога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'А послије свију умрије и жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'О васкрсенију дакле кога ће од седморице бити жена? јер је за свима била.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'А Исус одговарајући рече им: варате се, не знајући писма ни силе Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Јер о васкрсенију нити ће се женити ни удавати; него су као анђели Божији на небу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'А за васкрсеније мртвијех нијесте ли читали што вам је рекао Бог говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Ја сам Бог Аврамов, и Бог Исаков, и Бог Јаковљев! Није Бог Бог мртвијех, него живијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'И чувши народ дивљаше се науци његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'А фарисеји чувши да посрами садукеје сабраше се заједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'И упита један од њих законик кушајући га и говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Учитељу! која је заповијест највећа у закону?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'А Исус рече му: љуби Господа Бога својега свијем срцем својијем, и свом душом својом, и свом мисли својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Ово је прва и највећа заповијест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'А друга је као и ова: љуби ближњега својега као самога себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'О овима двјема заповијестима виси сав закон и пророци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'А кад се сабраше фарисеји, упита их Исус');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'Говорећи: шта мислите за Христа, чији је син? Рекоше му: Давидов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Рече им: како дакле Давид њега духом назива Господом говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'Рече Господ Господу мојему: сједи мени с десне стране, док положим непријатеље твоје подножје ногама твојима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Кад дакле Давид назива њега Господом, како му је син?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'И нико му не могаше одговорити ријечи; нити смијаше ко од тога дана да га запита више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Тада Исус рече к народу и ученицима својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'Говорећи: на Мојсијеву столицу сједоше књижевници и фарисеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Све дакле што вам реку да држите, држите и творите; али што они чине не чините; јер говоре а не чине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Него свежу бремена тешка и незгодна за ношење, и товаре на плећа људска; а прстом својијем неће да их прихвате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'А сва дјела своја чине да их виде људи: раширују своје амајлије, и граде велике скуте на хаљинама својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'И траже зачеље на гозбама и прва мјеста по зборницама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'И да им се клања по улицама, и да их људи зову: рави! рави!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'А ви се не зовите рави; јер је у вас један рави Христос, а ви сте сви браћа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'И оцем не зовите никога на земљи; јер је у вас један отац који је на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Нити се зовите учитељи; јер је у вас један учитељ Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'А највећи између вас да вам буде слуга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Јер који се подиже, понизиће се, а који се понижује, подигнуће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Тешко вама књижевници и фарисеји, лицемјери, што затварате царство небеско од људи; јер ви не улазите нити дате да улазе који би хтјели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Тешко вама књижевници и фарисеји, лицемјери, што једете куће удовичке, и лажно се Богу молите дуго; зато ћете већма бити осуђени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Тешко вама књижевници и фарисеји, лицемјери, што преходите море и земљу да би присвојили једнога, и кад га присвојите, чините га сином пакленијем удвоје већијем од себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Тешко вама вођи слијепи који говорите: ако се ко куне црквом ништа је; а ако се ко куне златом црквенијем крив је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Будале слијепе! шта је веће, или злато, или црква која злато освети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'И ако се ко куне олтаром ништа је то, а који се куне даром који је на њему крив је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Будале слијепе! шта је веће, или дар, или олтар који дар освети?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Који се дакле куне олтаром, куне се њим и свијем што је на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'И који се куне црквом, куне се њом и онијем што живи у њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'И који се куне небом, куне се пријестолом Божјим и онијем који сједи на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Тешко вама књижевници и фарисеји, лицемјери, што дајете десетак од метвице и од копра и од кима, а остависте што је најпретежније у закону: правду и милост и вјеру; а ово је требало чинити и оно не остављати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Вођи слијепи који оцјеђујете комарца а камилу прождирете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Тешко вама књижевници и фарисеји, лицемјери што чистите споља чашу и здјелу а изнутра су пуне грабежа и неправде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Фарисеју слијепи! Очисти најприје изнутра чашу и здјелу да буду и споља чисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Тешко вама књижевници и фарисеји, лицемјери, што сте као окречени гробови, који се споља виде лијепи а унутра су пуни костију мртвачкијех и сваке нечистоте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Тако и ви споља се показујете људима праведним, а изнутра сте пуни лицемјерја и безакоња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Тешко вама књижевници и фарисеји, лицемјери, што зидате гробове пророцима и красите раке праведника,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'И говорите: да смо ми били у вријеме својијех отаца, не бисмо с њима пристали у крв пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Тијем само свједочите за себе да сте синови онијех који су побили пророке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'И ви допуните мјеру отаца својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Змије, породи аспидини! Како ћете побјећи од пресуде у огањ паклени?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Зато ево ја ћу к вама послати пророке и премудре и књижевнике; и ви ћете једне побити и распети, а једне бити по зборницама својима и гонити од града до града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'Да дође на вас сва крв праведна што је проливена на земљи од крви Авеља праведнога до крви Зарије сина Варахијина, којега убисте међу црквом и олтаром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Заиста вам кажем да ће ово све доћи на род овај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Јерусалиме, Јерусалиме, који убијаш пророке и засипаш камењем послане к себи! Колико пута хтјех да скупим чеда твоја као што кокош скупља пилиће своје под крила и не хтјесте!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Ето ће вам се оставити ваша кућа пуста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Јер вам кажем: нећете мене видјети отселе док не речете: Благословљен који иде у име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'И изишавши Исус иђаше од цркве, и приступише к њему ученици његови да му покажу грађевину црквену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'А Исус рече им: не видите ли све ово? Заиста вам кажем: неће остати овдје ни камен на камену који се неће разметнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'А кад сјеђаше на гори Маслинској приступише к њему ученици насамо говорећи: кажи нам кад ће то бити? и какав је знак твојега доласка и пошљетка вијека?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'И одговарајући Исус рече им: чувајте се да вас ко не превари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Јер ће многи доћи у име моје говорећи: ја сам Христос. И многе ће преварити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Чућете ратове и гласове о ратовима. Гледајте да се не уплашите; јер треба да то све буде. али није још тада пошљедак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Јер ће устати народ на народ и царство на царство; и биће глади и помори, и земља ће се трести по свијету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'А то је све почетак страдања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Тада ће вас предати на муке, и побиће вас, и сви ће народи омрзнути на вас имена мојега ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'И тада ће се многи саблазнити, и друг друга издаће, и омрзнуће друг на друга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'И изићи ће многи лажни пророци и превариће многе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'И што ће се безакоње умножити, охладњеће љубав многијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Али који претрпи до краја благо њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'И проповједиће се ово јеванђеље о царству по свему свијету за свједочанство свијем народима. И тада ће доћи пошљедак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Кад дакле угледате мрзост опушћења, о којој говори пророк Данило, гдје стоји на мјесту светоме (који чита да разумије):');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'Тада који буду у Јудеји нека бјеже у горе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'И који буде на крову да не силази узети што му је у кући;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'И који буде у пољу да се не врати натраг да узме хаљине своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'А тешко труднима и дојилицама у те дане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Него се молите Богу да не буде бјежан ваша у зиму ни у суботу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Јер ће бити невоља велика какова није била од постања свијета досад нити ће бити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'И да се они дани не скрате, нико не би остао; али избранијех ради скратиће се дани они.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Тада ако вам ко рече: ево овдје је Христос или ондје, не вјерујте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Јер ће изићи лажни христоси и лажни пророци, и показаће знаке велике и чудеса да би преварили, ако буде могуће, и избране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Ето вам казах напријед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Ако вам дакле реку: ево га у пустињи, не излазите; ево га у собама, не вјерујте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Јер како што муња излази од истока и показује се до запада, таки ће бити долазак сина човјечијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Јер гдје је стрвина онамо ће се и орлови купити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'И одмах ће по невољи дана тијех сунце помрчати, и мјесец своју свјетлост изгубити, и звијезде с неба спасти, и силе небеске покренути се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'И тада ће се показати знак сина човјечијега на небу; и тада ће проплакати сва племена на земљи; и угледаће сина човјечијега гдје иде на облацима небескима са силом и славом великом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'И послаће анђеле своје с великијем гласом трубнијем; и сабраће избране његове од четири вјетра, од краја до краја небеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Од смокве научите се причи: кад се већ њезине гране помладе и улистају, знате да је близу љето.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Тако и ви кад видите све ово, знајте да је близу код врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Заиста вам кажем: овај нараштај неће проћи док се ово све не збуде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Небо и земља проћи ће, али ријечи моје неће проћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'А о дану томе и часу нико не зна, ни анђели небески, до отац мој сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Јер како што је било у вријеме Нојево тако ће бити и долазак сина човјечијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Јер како што пред потопом јеђаху и пијаху, жењаху се и удаваху до онога дана кад Ноје уђе у ковчег,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'И не осјетише док не дође потоп и однесе све; тако ће бити и долазак сина човјечијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Тада ће бити два на њиви; један ће се узети, а други ће се оставити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Двије ће мљети на жрвњевима; једна ће се узети, а друга ће се оставити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Стражите дакле, јер не знате у који ће час доћи Господ ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Али ово знајте: кад би знао домаћин у које ће вријеме доћи лупеж, чувао би и не би дао поткопати куће своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Зато и ви будите готови; јер у који час не мислите доћи ће син човјечиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Ко је дакле тај вјерни и мудри слуга којега је поставио господар његов над својима домашњима да им даје храну на оброк?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Благо томе слузи којега дошавши господар његов нађе да извршује тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Заиста вам кажем: поставиће га над свијем имањем својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Ако ли тај рђави слуга рече у срцу своме: неће мој господар још задуго доћи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'И почне бити своје другаре, и јести и пити с пијаницама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'Доћи ће господар тога слуге у дан у који се не нада, и у час кад не мисли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'И расјећи ће га напола, и даће им плату као лицемјерима; ондје ће бити плач и шкргут зуба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Тада ће бити царство небеско као десет дјевојака које узеше жишке своје и изиђоше на сусрет женику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Пет од њих бијаху мудре а пет луде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'И луде узевши жишке своје не узеше са собом уља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'А мудре узеше уље у судовима са жишцима својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'А будући да женик одоцни, задријемаше све, и поспаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'А у поноћи стаде вика: ето женика гдје иде, излазите му на сусрет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Тада усташе све дјевојке оне и украсише жишке своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'А луде рекоше мудрима: дајте нам од уља својега, јер наши жишци хоће да се угасе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'А мудре одговорише говорећи: да не би недостало и нама и вама, боље је идите к трговцима и купите себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'А кад оне отидоше да купе, дође женик, и готове уђоше с њим на свадбу, и затворише се врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'А послије дођоше и оне друге дјевојке говорећи: господару! господару! отвори нам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'А он одговарајући рече им: заиста вам кажем: не познајем вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Стражите дакле, јер не знате дана ни часа у који ће син човјечиј доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Јер како што човјек полазећи дозва слуге своје и предаде им благо своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'И једноме дакле даде пет таланата, а другоме два, а трећему један, свакоме према његовој моћи; и отиде одмах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'А онај што прими пет таланата отиде те ради с њима, и доби још пет таланата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Тако и онај што прими два доби и он још два.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'А који прими један отиде те га закопа у земљу и сакри сребро господара својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'А по другом времену дође господар тијех слуга, и стаде се рачунити с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'И приступивши онај што је примио пет таланата, донесе још пет таланата говорећи: господару! предао си ми пет таланата; ево још пет таланата ја сам добио с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'А господар његов рече му: добро, слуго добри и вјерни! У малом био си ми вјеран, над многијем ћу те поставити; уђи у радост господара својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'А приступивши и онај што је примио два таланта рече: господару! предао си ми два таланта; ево још два таланта ја сам добио с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'А господар његов рече му: добро, слуго добри и вјерни! У малом био си ми вјеран, над многијем ћу те поставити; уђи у радост господара својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'А приступивши и онај што је примио један таланат рече: господару! знао сам да си ти тврд човјек: жњеш гдје нијеси сијао, и купиш гдје нијеси вијао;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Па се побојах и отидох те сакрих таланат твој у земљу; и ево ти своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'А господар његов одговарајући рече му: зли и љењиви слуго! знао си да ја жњем гдје нијесам сијао, и купим гдје нијесам вијао:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Требало је дакле моје сребро да даш трговцима; и ја дошавши узео бих своје с добитком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Узмите дакле од њега таланат, и подајте ономе што има десет таланата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Јер свакоме који има, даће се, и претећи ће му; а од онога који нема, и што има узеће се од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'И неваљалога слугу баците у таму најкрајњу; ондје ће бити плач и шкргут зуба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'А кад дође син човјечиј у слави својој и сви свети анђели с њиме, онда ће сјести на пријестолу славе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'И сабраће се пред њим сви народи, и разлучиће их између себе као пастир што разлучује овце од јараца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'И поставиће овце с десне стране себи, а јарце с лијеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Тада ће рећи цар онима што му стоје с десне стране: ходите благословени оца мојега; примите царство које вам је приправљено од постања свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Јер огладњех, и дасте ми да једем; ожедњех, и напојисте ме; гост бијах, и примисте ме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'Го бијах, и одјенусте ме; болестан бијах, и обиђосте ме; у тамници бијах, и дођосте к мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Тада ће му одговорити праведници говорећи: Господе! кад те видјесмо гладна, и нахранисмо? или жедна, и напојисмо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Кад ли те видјесмо госта, и примисмо? или гола, и одјенусмо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Кад ли те видјесмо болесна или у тамници, и дођосмо к теби?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'И одговарајући цар рећи ће им: заиста вам кажем: кад учинисте једноме од ове моје најмање браће, мени учинисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Тада ће рећи и онима што му стоје с лијеве стране: идите од мене проклети у огањ вјечни приправљен ђаволу и анђелима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Јер огладњех, и не дадосте ми да једем; ожедњех, и не напојисте ме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'Гост бијах, и не примисте ме; го бијах, и не одјенусте ме; болестан и у тамници бијах, и не обиђосте ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Тада ће му одговорити и они говорећи: Господе! кад те видјесмо гладна или жедна, или госта или гола, или болесна или у тамници, и не послужисмо те?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Тада ће им одговорити говорећи: заиста вам кажем: кад не учинисте једноме од ове моје мале браће, ни мени не учинисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'И ови ће отићи у муку вјечну, а праведници у живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'И кад сврши Исус ријечи ове, рече ученицима својима:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Знате да ће до два дана бити пасха, и сина човјечијега предаће да се разапне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Тада скупише се главари свештенички и књижевници и старјешине народне у двор поглавара свештеничкога по имену Кајафе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'И свјетоваше се како би Исуса из пријеваре ухватили и убили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'И говораху: али не о празнику, да се не би народ побунио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'А кад Исус бјеше у Витанији у кући Симона губавога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'Приступи к њему жена са скленицом мира многоцјенога, и изли на главу његову кад сјеђаше за трпезом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'А кад видјеше то ученици његови, расрдише се говорећи: зашто се чини така штета?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Јер се могаше ово продати скупо и новци дати сиромасима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'А кад разумје Исус, рече им: шта сметате жену? Она учини добро дјело на мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Јер сиромахе имате свагда са собом, а мене немате свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'А она изливши миро ово на тијело моје за укоп ме приготови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Заиста вам кажем: гдје се год успроповиједа ово јеванђеље по свему свијету, казаће се и то за спомен њезин што учини она.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Тада један од дванаесторице, по имену Јуда Искариотски, отиде ка главарима свештеничкијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'И рече: шта ћете ми дати да вам га издам? А они му обрекоше тридесет сребрника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'И отада тражаше згоду да га изда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'А у први дан пријеснијех хљебова приступише ученици к Исусу говорећи: гдје ћеш да ти зготовимо пасху да једеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'А он рече: идите у град к томе и томе, и кажите му: учитељ каже: вријеме је моје близу, у тебе ћу да учиним пасху с ученицима својијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'И учинише ученици како им заповједи Исус, и уготовише пасху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'А кад би увече, сједе за трпезу са дванаесторицом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'И кад јеђаху рече им: заиста вам кажем: један између вас издаће ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'И забринувши се врло почеше сваки говорити му: да нијесам ја, Господе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'А он одговарајући рече: који умочи са мном руку у здјелу онај ће ме издати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Син човјечиј дакле иде као што је писано за њега; али тешко ономе човјеку који изда сина човјечијега; боље би му било да се није ни родио онај човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'А Јуда, издајник његов, одговарајући рече: да нијесам ја, рави? Рече му: ти каза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'И кад јеђаху, узе Исус хљеб и благословивши преломи га, и даваше ученицима, и рече: узмите, једите; ово је тијело моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'И узе чашу и давши хвалу даде им говорећи: пијте из ње сви;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Јер је ово крв моја новога завјета која ће се пролити за многе ради отпуштења гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Кажем вам пак да нећу отсад пити од овога рода виноградскога до онога дана кад ћу пити с вама новога у царству оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'И отпојавши хвалу изиђоше на гору Маслинску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Тада рече им Исус: сви ћете се ви саблазнити о мене ову ноћ; јер у писму стоји: ударићу пастира и овце од стада разбјежаће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'А по васкрсенију својему ја идем пред вама у Галилеју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'А Петар рече му: ако се и сви саблазне о тебе ја се нећу никад саблазнити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Рече му Исус: заиста ти кажем: ноћас док пијетао не запјева три пута ћеш ме се одрећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Рече њему Петар: да бих знао и умријети с тобом нећу те се одрећи. Тако и сви ученици рекоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Тада дође Исус с њима у село које се зове Гетсиманија, и рече ученицима: сједите ту док ја идем тамо да се помолим Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'И узевши Петра и оба сина Заведејева забрину се и поче тужити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Тада рече им Исус: жалосна је душа моја до смрти; почекајте овдје, и стражите са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'И отишавши мало паде на лице своје молећи се и говорећи: оче мој! ако је могуће да ме мимоиђе чаша ова; али опет не како ја хоћу него како ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'И дошавши к ученицима нађе их гдје спавају, и рече Петру: зар не могосте један час постражити са мном?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Стражите и молите се Богу да не паднете у напаст; јер је дух срчан, али је тијело слабо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Опет по други пут отиде и помоли се говорећи:оче мој! ако ме не може чаша ова мимоићи да је не пијем, нека буде воља твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'И дошавши нађе их опет гдје спавају; јер им бијаху очи отежале.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'И оставивши их отиде опет и трећи пут те се помоли говорећи оне исте ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Тада дође к ученицима својијем и рече им: једнако спавате и почивате; ево се приближи час, и син човјечиј предаје се у руке грјешника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Устаните да идемо; ево се приближи издајник мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'И док он још тако говораше, гле, Јуда, један од дванаесторице, дође, и с њим људи многи с ножевима и с кољем од главара свештеничкијех и старјешина народнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'А издајник његов даде им знак говорећи: кога ја цјеливам онај је; држите га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'И одмах приступивши к Исусу рече: здраво, рави! и цјелива га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'А Исус рече му: пријатељу! шта ћеш ти овдје? Тада приступивши дигоше руке на Исуса и ухватише га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'И гле, један од онијех што бијаху са Исусом машивши се руком извади нож свој те удари слугу поглавара свештеничкога, и отсијече му ухо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Тада рече му Исус: врати нож свој на мјесто његово; јер сви који се маше за нож од ножа ће изгинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Или мислиш ти да ја не могу сад умолити оца својега да ми пошље више од дванаест легеона анђела?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Али како би се испунило што стоји у писму да ово треба да буде?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'У тај час рече Исус људима: као на хајдука изишли сте с ножевима и с кољем да ме ухватите, а сваки дан сам код вас сједио учећи у цркви, и не ухватисте ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'А ово све би да се збуду писма пророчка. Тада ученици сви оставише га, и побјегоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'И они што ухватише Исуса одведоше га поглавару свештеничкоме Кајафи, гдје се књижевници и старјешине сабраше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'А Петар иђаше за њим издалека до двора поглавара свештеничкога и ушавши унутра сједе са слугама да види свршетак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'А главари свештенички и старјешине и сав сабор тражаху лажна свједочанства на Исуса да би га убили;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'И не нађоше; и премда многи лажни свједоци долазише, не нађоше. Најпослије дођоше два лажна свједока,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'И рекоше: он је казао: ја могу развалити цркву Божију и за три дана начинити је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'И уставши поглавар свештенички рече му: зар ништа не одговараш што ови на тебе свједоче?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'А Исус мучаше. И поглавар свештенички одговарајући рече му: заклињем те живијем Богом да нам кажеш јеси ли ти Христос син Божиј?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Рече му Исус: ти каза. Али ја вам кажем: отселе ћете видјети сина човјечијега гдје сједи с десне стране силе и иде на облацима небескијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Тада поглавар свештенички раздрије хаљине своје говорећи: хули на Бога; шта нам требају више свједоци? ево сад чусте хулу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Шта мислите? А они одговарајући рекоше: заслужио је смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Тада пљунуше му у лице, и ударише га по лицу, а једни му даше и приушке');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'Говорећи: прореци нам, Христе, ко те удари?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'А Петар сјеђаше напољу на двору, и приступи к њему једна слушкиња говорећи: и ти си био с Исусом Галилејцем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'А он се одрече пред свима говорећи: не знам шта говориш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'А кад изиђе к вратима угледа га друга, и рече онима што бијаху ондје: и овај бјеше са Исусом Назарећанином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Он опет одрече се клетвом: не знам тог човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'А мало потом приступише они што стајаху и рекоше Петру: ваистину и ти си од њих; јер те и говор твој издаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Тада се поче клети и преклињати да не зна тог човјека. И одмах запјева пијетао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'И опомену се Петар ријечи Исусове што му је рекао: док пијетао не запјева три пута ћеш ме се одрећи. И изашавши напоље плака горко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'А кад би ујутру, учинише вијећу сви главари свештенички и старјешине народне за Исуса да га погубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'И свезавши га одведоше, и предаше га Понтију Пилату судији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Тада видјевши Јуда издајник његов да га осудише раскаја се, и поврати тридесет сребрника главарима свештеничкијем и старјешинама');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'Говорећи: ја сагријеших што издадох крв праву. А они рекоше: шта ми маримо за то? ти ћеш видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'И бацивши сребрнике у цркви изиђе, и отиде те се објеси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'А главари свештенички узевши сребрнике рекоше: не ваља их метнути у црквену хазну, јер је узето за крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Него се договорише те купише за њих лончареву њиву за гробље гостима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Од тога се и прозва она њива крвна њива и до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Тада се изврши што је казао пророк Јеремија говорећи: и узеше тридесет сребрника, цијену цијењенога кога су цијенили синови Израиљеви;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'И дадоше их за њиву лончареву, као што ми каза Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'А Исус стаде пред судијом, и запита га судија говорећи: ти ли си цар Јудејски? А Исус рече му: ти кажеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'И кад га тужаху главари свештенички и старјешине, ништа не одговори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Тада рече ми Пилат: чујеш ли шта на тебе свједоче?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'И не одговори му ни једну ријеч тако да се судија дивљаше врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'А о сваком празнику пасхе бијаше обичај у судије да пусти народу по једног сужња кога они хоће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'А тада имаху знатнога сужња по имену Варава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'И кад се сабраше, рече им Пилат: кога хоћете да вам пустим? Вараву или Исуса прозванога Христа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Јер знадијаше да су га из зависти предали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'А кад сјеђаше у суду, поручи му жена његова говорећи: немој се ти ништа мијешати у суд тога праведника, јер сам данас у сну много пострадала њега ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'А главари свештенички и старјешине наговорише народ да ишту Вараву, а Исуса да погубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'А судија одговарајући рече им: кога хоћете од ове двојице да вам пустим? А они рекоше: Вараву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Рече им Пилат: а шта ћу чинити с Исусом прозванијем Христом? Рекоше му сви: да се разапне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Судија пак рече: а какво је зло учинио? А они из гласа повикаше говорећи: да се разапне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'А кад видје Пилат да ништа не помаже него још већа буна бива, узе воду те уми руке пред народом говорећи: ја нијесам крив у крви овога праведника: ви ћете видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'И одговарајући сав народ рече: крв његова на нас и на дјецу нашу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Тада пусти им Вараву, а Исуса шибавши предаде да се разапне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Тада војници судијини узеше Исуса у судницу и скупише на њ сву чету војника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'И свукавши га обукоше му скерлетну кабаницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'И оплетавши вијенац од трња метнуше му на главу, и дадоше му трску у десницу; и клекнувши на кољена пред њим ругаху му се говорећи: здраво, царе Јудејски!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'И пљунувши на њ узеше трску и бијаше га по глави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'И кад му се наругаше, свукоше с њега кабаницу, и обукоше га у хаљине његове, и поведоше га да га разапну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'И излазећи нађоше човјека из Кирине по имену Симона и натјераше га да му понесе крст.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'И дошавши на мјесто које се зове Голгота, то јест коштурница,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'Дадоше му да пије оцат помијешан са жучи, и окусивши не хтје да пије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'А кад га разапеше, раздијелише хаљине његове бацивши коцке;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'И сјеђаху ондје те га чуваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'И метнуше му више главе кривицу његову написану: ово је Исус цар Јудејски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Тада распеше с њиме два хајдука, једнога с десне а једнога с лијеве стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'А који пролажаху хуљаху на њ машући главама својима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'И говорећи: ти који цркву разваљујеш и за три дана начињаш помози сам себи; ако си син Божиј, сиђи с крста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'А тако и главари свештенички с књижевницима и старјешинама потсмијевајући се говораху:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Другима поможе, а себи не може помоћи. Ако је цар Израиљев, нека сиђе сад с крста па ћемо га вјеровати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Он се уздао у Бога: нека му поможе сад, ако му је по вољи, јер говораше: ја сам син Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Тако исто и хајдуци разапети с њим ругаху му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'А од шестога сахата би тама по свој земљи до сахата деветога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'А око деветога сахата повика Исус иза гласа говорећи: Или! Или! лама савахтани? то јест: Боже мој! Боже мој! зашто си ме оставио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'А неки од онијех што стајаху ондје чувши то говораху: овај зове Илију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'И одмах отрча један од њих те узе сунђер, и напуни оцта, па натаче на трску, те га појаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'А остали говораху: стани да видимо хоће ли доћи Илија да му поможе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'А Исус опет повика иза гласа и испусти душу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'И гле, завјес црквени раздрије се надвоје од горњега краја до доњега; и земља се потресе, и камење се распаде;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'И гробови се отворише, и усташе многа тијела светијех који су помрли;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'И изашавши из гробова по васкрсенију његовом уђоше у свети град и показаше се многима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'А капетан и који с њим чуваху Исуса видјевши да се земља тресе и шта би, поплашише се врло говорећи: заиста овај бијаше син Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'И ондје бијаху и гледаху издалека многе жене које су ишле за Исусом из Галилеје и служиле му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Међу којима бијаше Марија Магдалина и Марија мати Јаковљева и Јосијина и мати синова Заведејевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'А кад би увече, дође човјек богат из Ариматеје, по имену Јосиф, који је такођер био ученик Исусов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Овај приступивши к Пилату замоли га за тијело Исусово. Тада Пилат заповједи да му даду тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'И узевши Јосиф тијело зави га у платно чисто;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'И метну га у нови свој гроб што је био исјекао у камену; и наваливши велики камен на врата од гроба отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'А ондје бијаше Марија Магдалина и друга Марија, и сјеђаху према гробу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Сјутрадан пак по петку сабраше се главари свештенички и фарисеји код Пилата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'И рекоше: господару! ми се опоменусмо да овај лажа каза још за живота: послије три дана устаћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Зато заповједи да се утврди гроб до трећега дана да не дођу како ученици његови ноћу и да га не украду и не кажу народу: уста из мртвијех; и биће пошљедња пријевара гора од прве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Рече им Пилат: ево вам страже, па идите те утврдите како знате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'А они отишавши са стражом утврдише гроб, и запечатише камен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'А по вечеру суботном на освитак првога дана недјеље дође Марија Магдалина и друга Марија да огледају гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'И гле, земља се затресе врло; јер анђео Господњи сиђе с неба, и приступивши одвали камен од врата гробнијех и сјеђаше на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'А лице његово бијаше као муња, и одијело његово као снијег.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'И од страха његова уздркташе се стражари, и постадоше као мртви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'А анђео одговарајући рече женама: не бојте се ви; јер знам да Исуса распетога тражите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Није овдје: јер устаде као што је казао. Ходите да видите мјесто гдје је лежао Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Па идите брже те кажите ученицима његовијем да је устао из мртвијех. И гле, он ће пред вама отићи у Галилеју; тамо ћете га видјети. Ето ја вам казах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'И изишавши брзо из гроба са страхом и радости великом потекоше да јаве ученицима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'А кад иђаху да јаве ученицима његовијем, и гле, срете их Исус говорећи: здраво! А оне приступивши ухватише се за ноге његове и поклонише му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Тада рече им Исус: не бојте се; идите те јавите браћи мојој нека иду у Галилеју; и тамо ће ме видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'А кад иђаху, гле, неки од стражара дођоше у град и јавише главарима свештеничкијем све што се догодило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'И они саставши се са старјешинама учинише вијећу, и дадоше војницима довољно новаца');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'Говорећи: кажите: ученици његови дођоше ноћу и украдоше га кад смо ми спавали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'И ако то чује судија, ми ћемо њега умирити, и учинити да вама ништа не буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'А они узевши новце учинише као што су научени били. И разгласи се ова ријеч по Јеврејима и до данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'А једанаест ученика отидоше у Галилеју у гору куда им је казао Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'И кад га видјеше, поклонише му се; а једни посумњаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'И приступивши Исус рече им говорећи: даде ми се свака власт на небу и на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Идите дакле и научите све народе крстећи их ва име оца и сина и светога Духа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'Учећи их да све држе што сам вам заповиједао; и ево ја сам с вама у све дане до свршетка вијека. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Почетак јеванђеља Исуса Христа сина Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Као што стоји у пророка: ево ја шаљем анђела својега пред лицем твојијем, који ће приправити пут твој пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Глас онога што виче у пустињи: приправите пут Господњи, поравните стазе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Појави се Јован крстећи у пустињи, и проповиједајући крштење покајања за опроштење гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'И излажаше к њему сва Јудејска земља и Јерусалимљани; и кршћаваше их све у Јордану ријеци, и исповиједаху гријехе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'А Јован бијаше обучен у камиљу длаку, и имаше појас кожан око себе; и јеђаше скакавце и мед дивљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'И проповиједаше говорећи: иде за мном јачи од мене, пред ком ја нијесам достојан сагнути се и одријешити ремена на обући његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Ја вас кршћавам водом, а он ће вас крстити Духом светијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'И у то вријеме дође Исус из Назарета Галилејскога, и крсти га Јован у Јордану,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'И одмах излазећи из воде видје небо гдје се отвори, и Дух као голуб сиђе на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'И глас дође с неба: ти си син мој љубазни који је по мојој вољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'И одмах Дух изведе га у пустињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'И би ондје у пустињи дана четрдесет, и куша га сотона, и би са звјерињем, и анђели служаху му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'А пошто предадоше Јована, дође Исус у Галилеју проповиједајући јеванђеље о царству Божијему');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'И говорећи: изиђе вријеме и приближи се царство Божије; покајте се и вјерујте јеванђеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'И ходећи покрај мора видје Симона, и Андрију брата његова гдје бацају мреже у море; јер бијаху рибари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'И рече им Исус: хајдете за мном, и учинићу вас ловцима људскијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'И одмах оставивши мреже своје пођоше за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'И отишавши мало оданде угледа Јакова Зеведејева, и Јована брата његова, и они у лађи крпљаху мреже;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'И одмах позва их; и оставивши оца својега Зеведеја у лађи с најамницима пођоше за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'И дођоше у Капернаум; и одмах у суботу ушавши у зборницу учаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'И дивљаху се науци његовој; јер их учаше као онај који власт има а не као књижевници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'И бијаше у зборници њиховој човјек с духом нечистијем, и повика');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'Говорећи: прођи се, што је теби до нас, Исусе Назарећанине? Дошао си да нас погубиш? Знам те ко си, светац Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'И запријети му Исус говорећи: умукни, и изиђи из њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'И стресе га дух нечисти, и повика иза гласа, и изиђе из њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'И уплашише се сви тако да питаху један другога говорећи: шта је ово? и каква је ово наука нова, да с власти и духовима нечистијем заповиједа, и слушају га?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'И отиде глас о њему одмах по свој околини Галилејској,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'И одмах изашавши из зборнице дођоше у дом Симонов и Андријин с Јаковом и Јованом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'А ташта Симонова лежаше од грознице; и одмах казаше му за њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'И приступивши подиже је узевши је за руку и пусти је грозница одмах, и служаше им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'А кад би пред вече, пошто сунце зађе, доношаху к њему све болеснике и бијесне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'И сав град бијаше се сабрао к вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'И исцијели многе болеснике од различнијех болести, и ђаволе многе истјера, и не дадијаше ђаволима да казују да га познаваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'А ујутру врло рано уставши изиђе, и отиде насамо, и ондје се мољаше Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'И за њим потрчаше Симон и који бијаху с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'И нашавши га рекоше му: траже те сви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'И рече им: хајдемо у оближња села и градове да и тамо проповједим: јер сам ја на то дошао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'И проповиједа по зборницама њиховијем по свој Галилеји, и ђаволе изгони.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'И дође к њему губавац молећи га и на кољенима клечећи пред њим и рече му: ако хоћеш, можеш ме очистити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'А Исус смиловавши се пружи руку, и дохвативши га се рече му: хоћу, очисти се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'И тек што му то рече, а губа отиде с њега, и оста чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'И запријетивши му одмах истјера га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'И рече му: гледај да никоме ништа не кажеш, него иди те се покажи свештенику, и принеси за очишћење своје што је заповједио Мојсије за свједочанство њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'А он изишавши поче много проповиједати и казивати шта је било тако да Исус не може јавно у град ући, него бијаше напољу у пустијем мјестима, и долажаху к њему са свију страна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'И уђе опет у Капернаум послије неколико дана; и чу се да је у кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'И одмах скупише се многи тако да не могаху ни пред вратима да се спрате; и казиваше им ријеч.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'И дођоше к њему с узетијем кога ношаше четворо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'И не могући приближити се к њему од народа открише кућу гдје он бијаше, и прокопавши спустише одар на коме узети лежаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'А Исус видјевши вјеру њихову рече узетоме: синко! опраштају ти се гријеси твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'А ондје сјеђаху неки од књижевника и помишљаху у срцима својима:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Шта овај тако хули на Бога? Ко може опраштати гријехе осим једнога Бога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'И одмах разумјевши Исус духом својијем да они тако помишљају у себи, рече им: што тако помишљате у срцима својијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Што је лакше? рећи узетоме: опраштају ти се гријеси? или рећи: устани и узми одар свој, и ходи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Но да знате да власт има син човјечиј на земљи опраштати гријехе, (рече узетоме:)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Теби говорим: устани и узми одар свој, и иди дома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'И уста одмах, и узевши одар изиђе пред свима тако да се сви дивљаху и хваљаху Бога говорећи: нигда тога видјели нијесмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'И изиђе опет к мору; и сав народ иђаше к њему, и учаше их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'И пролазећи видје Левију Алфејева гдје сједи на царини, и рече му: хајде за мном. И уставши отиде за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'И кад сјеђаше Исус за трпезом у кући његовој, и цариници и грјешници многи сјеђаху с њим и с ученицима његовијем: јер их бијаше много који иђаху за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'А књижевници и фарисеји видјевши га гдје једе с цариницима и с грјешницима говораху ученицима његовијем: зашто с цариницима и грјешницима једе и пије?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'И чувши Исус рече им: не требају здрави љекара него болесни. Ја нијесам дошао да дозовем праведнике но грјешнике на покајање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'И бијаху ученици Јованови и фарисејски који пошћаху; и дођоше и рекоше му: зашто ученици Јованови и фарисејски посте а твоји ученици не посте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'И рече им Исус: еда ли могу сватови постити док је женик с њима? Докле год имају са собом женика не могу постити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Него ће доћи дни кад ће се отети од њих женик, и тада ће постити у оне дне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'И нико не пришива нове закрпе на стару хаљину; иначе ће одадријети нова закрпа од старога, и гора ће рупа бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'И нико не љева нова вина у мјехове старе; иначе ново вино продре мјехове, и вино се пролије, и мјехови пропадну; него ново вино у нове мјехове љевати треба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'И догоди му се да иђаше у суботу кроз усјеве, и ученици његови тргаху путем класје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'И фарисеји говораху му: гледај, зашто чине у суботу што не ваља?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'А он рече им: нијесте ли никад читали шта учини Давид кад му би до невоље и огладње с онима што бијаху с њим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Како уђе у Божију кућу пред Авијатаром поглаваром свештеничкијем и хљебове постављене поједе којијех не бијаше слободно никоме јести осим свештеника, и даде их онима који бијаху с њим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'И говораше им: субота је начињена човјека ради, а није човјек суботе ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Дакле је господар син човјечиј и од суботе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'И уђе опет у зборницу, и ондје бјеше човјек са сухом руком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'И мотраху за њим неће ли га у суботу исцијелити да га окриве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'И рече човјеку са сухом руком: стани на сриједу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'И рече им: ваља ли у суботу добро чинити или зло чинити? душу одржати, или погубити? А они мучаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'И погледавши на њих с гњевом од жалости што су им онако срца одрвенила рече човјеку: пружи руку своју. И пружи; и поста рука здрава као и друга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'И изишавши фарисеји одмах учинише за њега вијећу с Иродовцима како би га погубили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'А Исус отиде с ученицима својијем к мору; и многи народ из Галилеје иде за њим и из Јудеје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'И из Јерусалима и из Идумеје и испреко Јордана и од Тира и Сидона мноштво велико чувши шта он чини дође к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'И рече ученицима својијем да буде лађа у њега готова због народа, да му не досађује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Јер многе исцијели тако да наваљиваху на њега који бијаху накажени болестима да га се дотакну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'И дуси нечисти кад га виђаху, припадаху к њему и викаху говорећи: ти си син Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'И много им пријећаше да га не прокажу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'И изиђоше на гору, и дозва које он шћаше; и дођоше му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'И постави дванаесторицу да буду с њим, и да их пошиље да проповиједају,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'И да имају власт да исцјељују од болести, и да изгоне ђаволе:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Првога Симона, и надједе му име Петар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'И Јакова Зеведејева и Јована брата Јаковљева, и надједе им имена Воанергес, које значи синови громови;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'И Андрију и Филипа и Вартоломија и Матеја и Тому и Јакова Алфејева и Тадију и Симона Кананита,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'И Јуду Искариотскога, који га и издаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'И дођоше у кућу, и сабра се опет народ да не могаху ни хљеба јести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'И чувши то род његов изиђоше да га ухвате; јер говораху да је изван себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'А књижевници који бијаху сишли из Јерусалима говораху: у њему је Веелзевул; и он помоћу кнеза ђаволскога изгони ђаволе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'И дозвавши их говораше им у причама: како може сотона сотону изгонити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'И ако се царство само по себи раздијели, не може остати царство оно;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'И ако се дом сам по себи раздијели, не може остати дом онај;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'И ако сотона устане сам на се и раздијели се, не може остати, него ће пропасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Нико не може покућство јакога, ушавши у кућу његову, отети ако најприје јакога не свеже: и онда ће кућу његову оплијенити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Заиста вам кажем: сви гријеси опростиће се синовима човјечијим, и хуљења на Бога, макар какова била:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'А који похули на Духа светога нема опроштења вавијек, него је крив вјечноме суду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Јер говораху: у њему је нечисти дух.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'И дође мати његова и браћа његова, и стојећи напољу послаше к њему да га зову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'И сјеђаше народ око њега. И рекоше му: ето мати твоја и браћа твоја и сестре твоје напољу питају за те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'И одговори им говорећи: ко је мати моја или браћа моја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'И погледавши на народ који сјеђаше рече: ево мати моја и браћа моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Јер ко изврши вољу Божију онај је брат мој и сестра моја и мати моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'И опет поче учити код мора, и скупише се око њега људи многи тако да мора ући у лађу, и сједити на мору; а народ сав бијаше на земљи крај мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'И учаше их у причама много, и говораше им у науци својој:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Слушајте: ево изиђе сијач да сије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'И кад сијаше догоди се да једно паде украј пута, и дођоше птице и позобаше га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'А друго паде на каменито мјесто гдје не бијаше много земље; и одмах изниче; јер не бијаше у дубину земље:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'А кад обасја сунце, увену, и будући да немаше коријена, усахну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'И друго паде у трње; и нарасте трње и удави га, и не донесе рода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'И друго паде на земљу добру; и даваше род који напредоваше и растијаше и доношаше по тридесет и по шесет и по сто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'И рече: ко има уши да чује нека чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'А кад оста сам, запиташе га који бијаху с њим и са дванаесторицом за ову причу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'И рече им: вама је дано да знате тајне царства Божијега, а онима напољу све у причама бива;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'Да очима гледају и да не виде, и ушима слушају и да не разумију; да се како не обрате и да им се не опросте гријеси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'И рече им: зар не разумијете ове приче? А како ћете све приче разумјети?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Сијач ријеч сије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'А оно су крај пута, гдје се сије ријеч и кад је чују одмах дође сотона и отме ријеч посијану у срцима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Тако су и оно што се сије на каменитијем мјестима који кад чују ријеч одмах је приме с радошћу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'Али немају коријена у себи, него су непостојани, па кад буде до невоље или их потјерају ријечи ради, одмах се саблазне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'А оно су што се у трњу сије који слушају ријеч,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'Али бриге овога свијета и пријевара богатства и остале сласти уђу и загуше ријеч, и без рода остане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'А оно су што се на доброј земљи сије који слушају ријеч и примају, и доносе род по тридесет и по шесет и по сто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'И говораше им: еда ли се свијећа ужиже да се метне под суд или под одар? а не да се на свијетњак метне?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Јер нема ништа тајно што неће бити јавно; нити има што сакривено што неће изићи на видјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Ако има ко уши да чује нека чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'И говораше им: памтите што чујете: каком мјером мјерите онаком ће вам се мјерити и дометнуће се вама који слушате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Јер ко има, даће му се; а који нема, узеће му се и оно што има.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'И говораше им: тако је царство Божије као човјек кад баци сјеме у земљу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'И спава и устаје ноћу и дању; и сјеме ниче и расте, да не зна он.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Јер земља сама од себе најприје донесе траву, потом клас, па онда испуни пшеницу у класу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'А кад сазри род, одмах пошље срп; јер наста жетва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'И говораше: какво ћемо казати да је царство Божије? или у каквој ћемо га причи исказати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Оно је као зрно горушичино које кад се посије у земљу мање је од свију сјемена на земљи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'А кад се посије, узрасте и буде веће од свега поврћа, и пусти гране велике да могу у његову хладу птице небеске живљети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'И таковијем многијем причама казиваше им ријеч колико могаху слушати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'А без прича не говораше им ни ријечи. А ученицима особито казиваше све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'И рече им онај дан увече: хајдемо на ону страну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'И отпустивши народ узеше га како бјеше у лађи; а и друге лађе бијаху с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'И постаде велика олуја; и валови тако заљеваху у лађу да се већ напуни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'А он на крми спаваше на узглављу; и пробудише га, и рекоше му: учитељу! зар ти не мариш што гинемо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'И уставши запријети вјетру, и рече мору: ћути, престани. И утоли вјетар, и постаде тишина велика.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'И рече им: зашто сте тако страшљиви? Како немате вјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'И уплашише се врло, и говораху један другоме: ко је овај дакле да га и вјетар и море слушају?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'И дођоше преко мора у околину Гадаринску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'И кад изиђе из лађе, одмах га срете човјек с духом нечистијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Који живљаше у гробовима и нико га не могаше свезати ни веригама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Јер је много пута био метнут у пута и у вериге, па је искидао вериге и пута изломио; и нико га не могаше укротити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'И једнако дан и ноћ бављаше се у гробовима и у горама вичући и бијући се камењем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'А кад видје Исуса из далека, потече и поклони му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'И повикавши иза гласа рече: шта је теби до мене, Исусе сине Бога вишњега? Заклињем те Богом, не мучи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Јер му говораше: изиђи, душе нечисти, из човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'И питаше га: како ти је име? И одговори му: легеон ми је име; јер нас је много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'И молише га много да их не шаље из оне околине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'А ондје по бријегу пасијаше велики крд свиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'И молише га сви ђаволи говорећи: пошљи нас у свиње да у њих уђемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'И допусти им Исус одмах. И изишавши духови нечисти уђоше у свиње; и навали крд с бријега у море; а бијаше их око двије хиљаде: и потопише се у мору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'А свињари побјегоше, и јавише у граду и по селима. И изиђоше људи да виде шта је било.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'И дођоше к Исусу, и видјеше бијеснога у коме је био легеон гдје сједи обучен и паметан; и уплашише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'А они што су видјели казаше им шта би од бијеснога и од свиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'И почеше га молити да иде из њиховијех крајева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'И кад уђе у лађу, мољаше га онај што је био бијесан да буде с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'А Исус не даде му, већ му рече: иди кући својој к својима и кажи им шта ти Господ учини, и како те помилова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'И отиде и поче приповиједати у Десет градова шта му учини Исус; и сви се дивљаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'И кад пријеђе Исус у лађи опет на ону страну, скупи се народ многи око њега; и бјеше крај мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'И гле, дође један од старјешина зборничкијех по имену Јаир; и видјевши га паде пред ноге његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'И мољаше га врло говорећи: кћи је моја на смрти; да дођеш и да метнеш на њу руке да оздрави и живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'И пође с њим; и за њим иђаше народа много и туркаху га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'И жена некаква која је дванаест година боловала од течења крви');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'И велику муку поднијела од многијех љекара, и потрошила све што је имала, и ништа јој нијесу помогли, него још горе начинили,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Кад је чула за Исуса, дође у народу састраг, и дотаче се хаљине његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Јер говораше: ако се само дотакнем хаљина његовијех оздравићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'И одмах пресахну извор крви њезине, и осјети у тијелу да оздрави од болести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'И одмах Исус осјети у себи силу што изиђе из њега, и обазревши се на народ рече: ко се то дотаче мојијех хаљина?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'И рекоше му ученици његови: видиш народ гдје те турка, па питаш: ко се дотаче мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'И он се обзираше да види ону која то учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'А жена уплашивши се дркташе, и знајући што јој се догоди, дође и клече пред њим, и каза му сву истину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'А он рече јој: кћери! вјера твоја поможе ти; иди с миром, и буди здрава од болести своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Још он говораше, а дођоше од старјешине зборничкога говорећи: кћи твоја умрије; шта већ трудиш учитеља?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'А Исус одмах чувши ријеч што рекоше рече старјешини: не бој се, само вјеруј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'И не даде за собом ићи никоме осим Петра и Јакова и Јована брата Јаковљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'И дође у кућу старјешине зборничкога, и видје вреву и плач и јаук велики.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'И ушавши рече им: шта сте узаврели те плачете? Дјевојка није умрла, него спава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'И потсмијеваху му се. А он истјеравши све узе оца дјевојчина и матер и који бијаху с њим, и уђе гдје лежаше дјевојка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'И узевши дјевојку за руку рече јој: Талита куми, које значи: дјевојко, теби говорим, устани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'И одмах уста дјевојка и хођаше; а бјеше од дванаест година. И зачудише се чудом великијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'И запријети им врло да нико не дозна за то, и рече: подајте јој нек једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'И изиђе оданде, и дође на своју постојбину; и за њим идоше ученици његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'И кад дође субота, поче учити у зборници. И многи који слушаху, дивљаху се говорећи: откуд овоме то? И каква му је премудрост дана? И чудеса такова рукама његовијем чине се?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Није ли ово дрводјеља, син Маријин, а брат Јаковљев и Јосијин и Јудин и Симонов? И нијесу ли сестре његове овдје међу нама? И саблажњаваху се о њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'А Исус рече им: нигдје није пророк без части до на постојбини својој и у роду и у дому своме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'И не могаше ондје ни једнога чуда да учини, осим што мало болесника исцијели метнувши на њих руке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'И дивљаше се невјерству њиховоме. И иђаше по околнијем селима и учаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'И дозва дванаесторицу, и поче их слати два и два, и даваше им власт над духовима нечистијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'И заповједи им да ништа не узимају на пут осим једнога штапа: ни торбе ни хљеба ни новаца у појасу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Него обувени у опанке, и не облачити двију хаљина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'И рече им: гдје уђете у дом ондје останите док не изиђете оданде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'И ако вас ко не прими и не послуша вас, излазећи оданде отресите прах с ногу својијех за свједочанство њима. Заиста вам кажем: лакше ће бити Содому и Гомору у дан страшнога суда него граду ономе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'И отишавши проповиједаху да се треба кајати;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'И ђаволе многе изгоњаху; и мазаху уљем многе болеснике; и исцјељиваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'И зачу цар Ирод за Исуса (јер његово име бијаше се разгласило), и рече: Јован крститељ из мртвијех уста, зато чини чудеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Други говораху: то је Илија. А други говораху: то је пророк или као који од пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'А кад чу Ирод, рече: то је Јован кога сам ја посјекао, он уста из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Јер овај Ирод посла те ухватише Јована, и свезавши баци га у тамницу Иродијаде ради жене Филипа брата својега, јер се ожени њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Јер Јован говораше Ироду: не можеш ти имати жене брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'А Иродијада расрди се на њега, и шћаше да га убије, али не могаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Јер се Ирод бојаше Јована знајући га да је човјек праведан и свет, и чуваше га, и много којешта чињаше како му он рече, и радо га слушаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'И догоди се дан згодан, кад Ирод на дан свога рођења даваше вечеру кнезовима својијем и војводама и старјешинама Галилејскијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'И ушавши кћи Иродијадина и игравши и угодивши Ироду и гостима његовијем рече цар дјевојци: ишти у мене шта год хоћеш, и даћу ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'И закле јој се: што год заиштеш у мене даћу ти, да би било и до по царства мога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'А она изишавши рече матери својој: шта ћу искати? А она рече: главу Јована крститеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'И одмах ушавши брзо к цару заиска говорећи: хоћу да ми даш сад на кругу главу Јована крститеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'И забрину се цар, али клетве ради и гостију својијех не хтје јој одрећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'И одмах посла цар џелата, и заповједи да донесе главу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'А он отишавши посијече га у тамници, и донесе главу његову на кругу, и даде дјевојци, а дјевојка даде је матери својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'И чувши ученици његови дођоше и узеше тијело његово, и метнуше га у гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'И скупише се апостоли к Исусу, и јавише му све и што учинише и шта људе научише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'И рече им: дођите ви сами насамо, и почините мало. Јер их бијаше много који долазе и одлазе, и не имаху кад ни јести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'И отидоше на лађи у пусто мјесто сами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'И видјеше их људи кад иђаху, и познаше их многи, и пјешице из свију градова стјецаху се онамо, и престигоше их, и скупише се око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'И изишавши Исус видје народ многи, и сажали му се, јер бијаху као овце без пастира; и поче их учити много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'И кад би већ пред ноћ, приступише к њему ученици његови говорећи: пусто је мјесто, а већ је доцкан;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Отпусти их нека иду у околна села и паланке да купе себи хљеба; јер немају шта јести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'А он одговарајући рече им: подајте им ви нека једу. И рекоше му: већ ако да идемо да купимо за двјеста гроша хљеба, и да им дамо да једу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'А он им рече: колико хљебова имате? Идите видите. И видјевши рекоше: пет хљебова и двије рибе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'И заповједи им да их посаде све на гомиле по зеленој трави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'И посадише се на гомиле по сто и по педесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'И узевши онијех пет хљебова и двије рибе погледа на небо, и благослови, па преломи хљебове, и даде ученицима својијем да метну испред њих; и оне двије рибе раздијели свима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'И једоше сви, и наситише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'И накупише комада дванаест котарица пунијех и од риба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'А бијаше онијех што су јели хљебове око пет хиљада људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'И одмах натјера ученике своје да уђу у лађу и да иду напријед на ону страну у Витсаиду док он отпусти народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'И отпустивши их отиде на гору да се помоли Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'И увече бијаше лађа насред мора, а он сам на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'И видје их гдје се мучаху веслајући: јер им бијаше противан вјетар. И око четврте страже ноћне дође к њима идући по мору; и шћадијаше да их мимоиђе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'А они видјевши га гдје иде по мору мишљаху да је утвара, и повикаше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'Јер га сви видјеше и поплашише се. И одмах проговори с њима, и рече им: не бојте се, ја сам, не плашите се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'И уђе к њима у лађу, и утоли вјетар; и врло се уплашише, и дивљаху се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Јер их не научише хљебови; јер се бијаше срце њихово окаменило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'И прешавши дођоше у земљу Генисаретску; и стадоше у крај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'И кад изиђоше из лађе, одмах га познаше људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'И оптрчавши сав онај крај почеше на одрима доносити болеснике гдје чујаху да је он.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'И кудгод иђаше у села или у градове или у паланке, на раскршћима метаху болеснике и мољаху га да се барем скута од хаљине његове дотакну: и оздрављаху сви који га се дотицаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'И скупише се око њега фарисеји и неки од књижевника који бијаху дошли из Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'И видјевши неке од ученика његовијех да нечистијем, то јест неумивенијем, рукама једу хљеб, укорише их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Јер фарисеји и сви Јевреји не једу док не умију руку до лаката, држећи се онога што им је остало од старијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'И кад дођу с пазара, не једу док се не умију; и још много има што су примили те држе: перу чаше и жбанове и котлове и клупе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'А потом питаху га фарисеји и књижевници: зашто ученици твоји не живе као што нам је остало од старијех, него једу хљеб неумивенијем рукама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'А он одговарајући рече им: добро је пророковао Исаија за вас лицемјере, као што је писано: ови људи уснама ме поштују, а срце њихово далеко стоји од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Но залуду ме поштују учећи наукама, заповијестима људскијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Јер остависте заповијести Божије, а држите обичаје људске, прање жбанова и чаша; и друга многа такова чините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'И рече им: добро укидате заповијест Божију да свој обичај сачувате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Јер Мојсије рече: поштуј оца својега и матер своју; и: који опсује оца или матер смрћу да умре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'А ви кажете: ако рече човјек оцу или матери: корван, то јест: прилог је чим бих ти ја могао помоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'И тако не дате му ништа учинити оцу својему или матери својој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Укидајући ријеч Божију својијем обичајем који сте поставили; и овако много којешта чините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'И дозвавши сав народ рече им: послушајте мене сви, и разумијте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Ништа нема што би човјека могло опоганити да уђе споља у њега, него што излази из њега оно је што погани човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Ако ко има уши да чује нека чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'И кад дође од народа у кућу питаху га ученици његови за причу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'И рече им: зар сте и ви тако неразумни? Не разумијете ли да што год у човјека споља улази не може га опоганити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Јер му не улази у срце него у трбух; и излази напоље чистећи сва јела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Још рече: што излази из човјека оно погани човјека;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Јер изнутра из срца људскога излазе мисли зле, прељубе, курварства, убиства,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Крађе, лакомства, пакости, злоће, лукавство, срамоте, зло око, хуљење на Бога, понос, безумље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Сва ова зла изнутра излазе, и погане човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'И уставши оданде отиде на крајеве Тирске и Сидонске, и ушавши у кућу шћадијаше да нико не чује за њ; и не може се сакрити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Јер чувши за њ жена што у њезиној кћери бијаше дух нечисти, дође и паде к ногама његовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'А жена та бијаше Гркиња родом Сирофиничанка, и мољаше га да истјера ђавола из кћери њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'А Исус рече јој: стани да се најприје дјеца нахране; јер није право узети хљеб од дјеце и бацити псима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'А она одговарајући рече му: да, Господе; али и пси под трпезом једу од мрва дјетињијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'И рече јој: за ту ријеч иди; изиђе ђаво из кћери твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'И дошавши кући нађе да је ђаво изишао, и кћи лежаше на одру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'И опет изиђе Исус из крајева Тирскијех и Сидонскијех и дође на море Галилејско у крајеве Десетоградске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'И доведоше к њему глуха и мутава, и мољаху га да метне на њ руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'И узевши га из народа насамо метну прсте своје у уши његове, и пљунувши дохвати се језика његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'И погледавши на небо уздахну, и рече му: Ефата, то јест: отвори се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'И одмах му се отворише уши, и раздријеши се свеза језика његова и говораше лијепо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'И запријети им да никоме не казују; али што им он забрањиваше они још већма разглашиваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'И врло се дивљаху говорећи: све добро чини; и глухе чини да чују и нијеме да говоре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'У то вријеме, кад бијаше врло много народа и не имадијаху шта јести, дозва Исус ученике своје и рече им:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Жао ми је народа, јер већ три дана стоје код мене и немају ништа јести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'И ако их отпустим гладне кућама њиховијем, ослабиће на путу; јер су многи од њих дошли издалека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'И одговорише му ученици његови: откуда ћемо узети хљеба овдје у пустињи да их нахранимо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'И запита их: колико имате хљебова? А они казаше: седам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'И заповједи народу да посједају по земљи; и узевши онијех седам хљебова и хвалу давши, преломи, и даде ученицима својијем да раздаду; и раздадоше народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'И имаху мало рибица; и њих благословивши рече да и њих раздаду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'И једоше, и наситише се, и накупише комада што претече седам котарица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'А онијех што су јели бијаше око четири хиљаде. И отпусти их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'И одмах уђе у лађу с ученицима својијем, и дође у околине Далманутске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'И изиђоше фарисеји, и почеше се препирати с њим, и кушајући га искаху од њега знак с неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'И уздахнувши духом својијем рече: зашто род овај знак тражи? Заиста вам кажем: неће се дати роду овоме знак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'И оставивши их уљезе опет у лађу, и отиде на ону страну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'И заборавише ученици његови узети хљеба, и немаху са собом у лађи до један хљеб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'И заповиједаше им говорећи: гледајте, чувајте се квасца фарисејскога и квасца Иродова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'И мишљаху један другоме говорећи: то је што хљеба немамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'И разумјевши Исус рече им: шта мислите што хљеба немате? Зар још не осјећате, нити разумијете? Зар је још окамењено срце ваше?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Очи имате и не видите? уши имате и не чујете? И не памтите ли');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Кад ја пет хљебова преломих на пет хиљада, колико котарица пунијех комада накуписте? Рекоше му: дванаест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'А кад седам на четири хиљаде, колико пунијех котарица накуписте комада? А они рекоше: седам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'И рече им: како не разумијете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'И дође у Витсаиду; и доведоше к њему слијепа, и мољаху га да га се дотакне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'И узевши за руку слијепога изведе га напоље из села, и пљунувши му у очи метну руке на њ, и запита га види ли што.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'И погледавши рече: видим људе гдје иду као дрва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'И потом опет метну му руке на очи, и рече му да прогледа: и исцијели се, и видје све лијепо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'И посла га кући његовој говорећи: не улази у село, нити казуј коме у селу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'И изиђе Исус и ученици његови у села Ћесарије Филипове; и путем питаше ученике своје говорећи им: ко говоре људи да сам ја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'А они одговорише: Јован крститељ; други: Илија; а други: који од пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'А он им рече: а ви шта мислите ко сам ја? А Петар одговарајући рече му: ти си Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'И запријети им да никоме не казују за њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'И поче их учити да сину човјечијему ваља много пострадати, и да ће га окривити старјешине и главари свештенички и књижевници, и да ће га убити, и трећи дан да ће устати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'И говораше о том не устручавајући се. И Петар узе га и поче га одвраћати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'А он обрнувши се и погледавши на ученике своје запријети Петру говорећи: иди од мене сотоно; јер ти не мислиш што је Божије него што је људско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'И дозвавши народ с ученицима својима рече им: ко хоће за мном да иде нека се одрече себе и узме крст свој, и за мном иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Јер ко хоће душу своју да сачува, изгубиће је; а ко изгуби душу своју мене ради и јеванђеља онај ће је сачувати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Јер каква је корист човјеку ако задобије сав свијет а души својој науди?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Или какав ће откуп дати човјек за душу своју?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Јер ко се постиди мене и мојијех ријечи у роду овоме прељуботворноме и грјешном, и син ће се човјечиј постидјети њега кад дође у слави оца својега с анђелима светима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'И рече им: заиста вам кажем: имају неки међу овима што стоје овдје који неће окусити смрти док не виде царство Божије да дође у сили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'И послије шест дана узе Исус Петра и Јакова и Јована и изведе их на високу гору саме; и преобрази се пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'И хаљине његове постадоше сјајне и врло бијеле као снијег, као што не може бјелиља убијелити на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'И указа им се Илија с Мојсијем гдје се разговараху с Исусом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'И Петар одговарајући рече Исусу: Рави! добро нам је овдје бити; и да начинимо три сјенице: теби једну и Мојсију једну и Илији једну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Јер не знадијаше шта говори; јер бијаху врло уплашени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'И постаде облак те их заклони; и дође глас из облака говорећи: ово је син мој љубазни; њега послушајте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'И у једанпут погледавши никога не видјеше осим Исуса сама са собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'А кад силажаху с горе запријети им да ником не казују шта су видјели, док син човјечиј не устане из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'И ријеч задржаше у себи питајући један другога: шта то значи устати из мртвијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'И питаху га говорећи: како говоре књижевници да Илија треба најприје да дође?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'А он одговарајући рече им: Илија ће доћи најприје, и уредити све; али и син човјечиј треба да много пострада и да се понизи, као што је писано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Али вам кажем да је и Илија дошао и учинише с њим шта хтједоше као што је писано за њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'И дошавши к ученицима својијем видје народ многи око њих и књижевнике гдје се препиру с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'И одмах видјевши га сав народ уплаши се и притрчавши поздрављаху га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'И упита књижевнике: шта се препирете с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'И одговарајући један од народа рече: учитељу! доведох к теби сина својега у коме је дух нијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'И сваки пут кад га ухвати ломи га, и пјену баца и шкргуће зубима; и суши се. И рекох ученицима твојијем да га истјерају; и не могоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'А он одговарајући му рече: о роде невјерни! докле ћу с вама бити? докле ћу вас трпљети? Доведите га к мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'И доведоше га к њему; и кад га видје одмах га дух стаде ломити; и панувши на земљу ваљаше се бацајући пјену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'И упита оца његова: колико има времена како му се то догодило? А он рече: из дјетињства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'И много пута баца га у ватру и у воду да га погуби; него ако што можеш помози нам, смилуј се на нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'А Исус рече му: ако можеш вјеровати: све је могуће ономе који вјерује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'И одмах повикавши отац дјетињи са сузама говораше: вјерујем, Господе! помози мојему невјерју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'А Исус видећи да се стјече народ запријети духу нечистоме говорећи му: душе нијеми и глухи! ја ти заповиједам, изиђи из њега и више не улази у њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'И повикавши и изломивши га врло изиђе; и учини се као мртав тако да многи говораху: умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'А Исус узевши га за руку подиже га; и уста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'И кад уђе у кућу питаху га ученици његови насамо: зашто га ми не могосмо истјерати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'И рече им: овај се род ничим не може истјерати до молитвом и постом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'И изишавши оданде иђаху кроз Галилеју; и не шћадијаше да ко дозна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Јер учаше ученике своје, и говораше им да ће се син човјечиј предати у руке људске, и убиће га, и пошто га убију устаће трећи дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'А они не разумијеваху ријечи, и не смедијаху да га запитају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'И дође у Капернаум, и кад бјеше у кући запита их: шта се препирасте путем међу собом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'А они мучаху; јер се путем препираше међу собом ко је највећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'И сједавши дозва дванаесторицу и рече им: који хоће да буде први нека буде од свију најзадњи и свима слуга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'И узевши дијете метну га међу њих и загрливши га рече им:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Ко једно оваково дијете прими у име моје, мене прима; а ко мене прими, не прима мене него онога који је мене послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Одговори му Јован говорећи: учитељу! видјесмо једнога гдје именом твојијем изгони ђаволе који не иде за нама: и забранисмо му, јер не иде за нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'А Исус рече: не браните му; јер нема никога који би именом мојијем чудо чинио да може брзо зло говорити за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Јер ко није против вас с вама је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Јер ко вас напоји чашом воде у име моје, зато што сте Христови, заиста вам кажем: неће му пропасти плата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'А који саблазни једнога од овијех малијех који вјерују мене, боље би му било да се објеси камен воденични о врату његову и да се баци у море.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'И ако те рука твоја саблажњава, отсијеци је: боље ти је без руке у живот ући, неголи с обје руке ући у пакао, у огањ вјечни,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'Гдје црв њихов не умире, и огањ се не гаси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'И ако те нога твоја саблажњава, отсијеци је: боље ти је ући у живот хрому, него ли с двије ноге да те баце у пакао, у огањ вјечни,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'Гдје црв њихов не умире, и огањ се не гаси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Ако те и око твоје саблажњава, ископај га: боље ти је с једнијем оком ући у царство Божије, него ли с два ока да те баце у пакао огњени,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'Гдје црв њихов не умире, и огањ се не гаси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Јер ће се сваки огњем посолити, и свака ће се жртва сољу посолити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Добра је со; али ако со буде неслана, чим ће се осолити? Имајте со у себи, и мир имајте међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 51, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'И уставши оданде дође у околине Јудејске преко Јордана, и стече се опет народ к њему; и као што обичај имаше, опет их учаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'И приступивши фарисеји упиташе га кушајући: може ли човјек пустити жену?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'А он одговарајући рече им: шта вам заповиједа Мојсије?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'А они рекоше: Мојсије допусти да јој се да распусна књига и да се пусти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'И одговарајући Исус рече им: по тврђи вашега срца написа вам он заповијест ову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'А у почетку створења мужа и жену створио их је Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Зато остави човјек оца својега и матер и прилијепи се к жени својој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'И буду двоје једно тијело. Тако нијесу више двоје него једно тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'А што је Бог саставио човјек да не раставља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'И у кући опет запиташе га за то ученици његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'И рече им: који пусти жену и ожени се другом, чини прељубу на њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'И ако жена остави мужа својега и пође за другога, чини прељубу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'И доношаху к њему дјецу да их се дотакне; а ученици брањаху онима што их доношаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'А Исус видјевши расрди се и рече им: пустите дјецу нека долазе к мени, и не браните им; јер је таковијех царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Заиста вам кажем: који не прими царства Божијега као дијете, неће ући у њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'И загрливши их метну на њих руке те их благослови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'И кад изиђе на пут, притрча неко, и клекнувши на кољена пред њим питаше га: учитељу благи! шта ми треба чинити да добијем живот вјечни?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'А Исус рече му: што ме зовеш благијем? нико није благ осим једнога Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Заповијести знаш: не чини прељубе; не убиј; не укради; не свједочи лажно; не чини неправде никоме; поштуј оца својега и матер.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'А он одговарајући рече му: учитељу! све сам ово сачувао од младости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'А Исус погледавши на њ, омиље му, и рече му: још ти једно недостаје: иди продај све што имаш и подај сиромасима; и имаћеш благо на небу; и дођи те хајде за мном узевши крст.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'А он поста зловољан од ове ријечи, и отиде жалостан; јер бијаше врло богат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'И погледавши Исус рече ученицима својима: како је тешко богатима ући у царство небеско!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'А ученици се уплашише од ријечи његовијех. А Исус опет одговарајући рече им: дјецо! како је тешко онима који се уздају у своје богатство ући у царство Божије!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Лакше је камили проћи кроз иглене уши него ли богатоме ући у царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'А они се врло дивљаху говорећи у себи: ко се дакле може спасти?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'А Исус погледавши на њих рече: људима је немогуће, али није Богу: јер је све могуће Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'А Петар му поче говорити: ето ми смо оставили све, и за тобом идемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'А Исус одговарајући рече: заиста вам кажем: нема никога који је оставио кућу, или браћу, или сестре, или оца, или матер, или жену, ли дјецу, или земљу, мене ради и јеванђеља ради,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'А да неће примити сад у ово вријеме сто пута онолико кућа, и браће, и сестара, и отаца, и матера, и дјеце, и земље, у прогоњењу, а на ономе свијету живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Али ће многи први бити пошљедњи, и пошљедњи први.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'А кад иђаху путем у Јерусалим, Исус иђаше пред њима, а они се чуђаху, и за њим иђаху са страхом. И узевши опет дванаесторицу поче им казивати шта ће бити од њега:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Ево идемо у Јерусалим, и син човјечиј предаће се главарима свештеничкијем и књижевницима и осудиће га на смрт, и предаће га незнабошцима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'И наругаће му се, и биће га, и попљуваће га, и убиће га, и трећи дан устаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'И пред њега дођоше Јаков и Јован, синови Зеведејеви, говорећи: учитељу! хоћемо да нам учиниш за што ћемо те молити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'А он рече: што хоћете да вам учиним?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'А они му рекоше: дај нам да сједемо један с десне стране теби а други с лијеве, у слави твојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'А Исус им рече: не знате шта иштете: можете ли пити чашу коју ја пијем, и крстити се крштењем којијем се ја крстим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'А они му рекоше: можемо. А Исус рече им: чашу дакле коју ја пијем испићете; и крштењем којијем се ја крстим крстићете се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'Али да сједете с десне стране мени и с лијеве, не могу ја дати него којима је уготовљено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'И чувши то десеторица почеше се срдити на Јакова и на Јована.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'А Исус дозвавши их рече им: знате да кнезови народни владају народом и поглавари његови управљају њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Али међу вама да не буде тако; него који хоће да буде већи међу вама, да вам служи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'И који хоће први међу вама да буде, да буде свима слуга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Јер син човјечиј није дошао да му служе него да служи, и да да душу своју у откуп за многе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'И дођоше у Јерихон. И кад излажаше из Јерихона, он и ученици његови и народ многи, син Тимејев Вартимеј слијепи сјеђаше крај пута и прошаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'И чувши да је то Исус Назарећанин стаде викати и говорити: сине Давидов Исусе! помилуј ме!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'И пријећаху му многи да ућути, а он још већма викаше: сине Давидов! помилуј ме!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'И ставши Исус рече да га зовну. И зовнуше слијепца говорећи му: не бој се; устани, зове те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'А он збацивши са себе хаљине своје устаде, и дође к Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'И одговарајући рече му Исус: шта хоћеш да ти учиним? А слијепи рече му: Равуни! да прогледам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'А Исус рече му: иди, вјера твоја поможе ти. И одмах прогледа, и отиде путем за Исусом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 53, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'И кад се приближи к Јерусалиму, к Витфази и Витанији, код горе Маслинске, посла двојицу од ученика својијех');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'И рече им: идите у село што је пред вама, и одмах како уђете у њега наћи ћете магаре привезано, на које нико од људи није усједао; одријешите га и доведите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'И ако вам ко рече: шта то чините? кажите: треба Господу; и одмах ће га послати амо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'А они отидоше, и нађоше магаре привезано код врата напољу на раскршћу, и одријешише га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'И неко од онијех што стајаху ондје рекоше им: зашто дријешите магаре?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'А они рекоше им као што им заповједи Исус; и оставише их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'И доведоше магаре к Исусу, и метнуше на њ хаљине своје; и усједе на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'А многи простријеше хаљине своје по путу; а једни резаху грање од дрвета, и простираху по путу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'А који иђаху пред њим и за њим, викаху говорећи: Осана! благословен који иде у име Господње!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Благословено царство оца нашега Давида које иде у име Господње! Осана на висини!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'И уђе Исус у Јерусалим, и у цркву; и промотривши све, кад би увече, изиђе у Витанију с дванаесторицом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'И сјутрадан кад изиђоше из Витаније, огладње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'И видјевши издалека смокву с лишћем дође не би ли што нашао на њој; и дошавши к њој ништа не нађе осим лишћа; јер још не бјеше вријеме смоквама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'И одговарајући Исус рече јој: да отсад од тебе нико не једе рода довијека. И слушаху ученици његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'И дођоше опет у Јерусалим; и ушавши Исус у цркву стаде изгонити оне који продаваху и куповаху по цркви; и испремета трпезе онијех што мијењаху новце, и клупе онијех што продаваху голубове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'И не дадијаше да ко пронесе суда кроз цркву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'И учаше говорећи им: није ли писано: дом мој нека се зове дом молитве свима народима? А ви начинисте од њега хајдучку пећину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'И чуше књижевници и главари свештенички, и тражаху како би га погубили; јер га се бојаху; јер се сав народ чуђаше науци његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'И кад би увече изиђе на поље из града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'И ујутру пролазећи видјеше смокву гдје се посушила из коријена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'И опоменувши се Петар рече му: Рави! гле, смоква што си је проклео посушила се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'И одговарајући Исус рече им:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Имајте вјеру Божију; јер вам заиста кажем: ако ко рече гори овој: дигни се и баци се у море, и не посумња у срцу својему, него узвјерује да ће бити као што говори: биће му што год рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Зато вам кажем: све што иштете у својој молитви вјерујте да ћете примити; и биће вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'И кад стојите на молитви, праштајте ако што имате на кога: да и отац ваш који је на небесима опрости вама погрјешке ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Ако ли пак ви не опраштате, ни отац ваш који је на небесима неће опростити вама погрјешака вашијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'И дођоше опет у Јерусалим; и кад хођаше по цркви дођоше к њему главари свештенички и књижевници и старјешине,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'И рекоше му: каквом власти то чиниш? и ко ти даде власт ту, да то чиниш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'А Исус одговарајући рече им: и ја ћу вас да упитам једну ријеч, и одговорите ми; па ћу вам казати каквом власти ово чиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Крштење Јованово или би с неба или од људи? одговорите ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'И мишљаху у себи говорећи: ако речемо: с неба; рећи ће: зашто му дакле не вјеровасте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Ако ли речемо: од људи; бојимо се народа; јер сви мишљаху за Јована да заиста пророк бјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'И одговарајући рекоше Исусу: не знамо. И Исус одговарајући рече њима: ни ја вама нећу казати каквом власти ово чиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'И поче им говорити у причама: посади човјек виноград, и огради плотом, и ископа пивницу, и начини кулу, и даде га виноградарима, па отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'И кад дође вријеме, посла к виноградарима слугу да прими од виноградара од рода виноградскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'А они ухвативши слугу избише га, и послаше празна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'И опет посла к њима другога слугу; и онога бише камењем и разбише му главу, и послаше га срамотна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'И опет посла другога; и онога убише; и многе друге, једне избише а једне побише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Још дакле имаше јединога својега милог сина, посла и њега најпослије к њима говорећи: постидјеће се сина мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'А виноградари рекоше у себи: ово је нашљедник, ходите да га убијемо, и нама ће остати очевина његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'И ухватише га, и убише, и избацише га напоље из винограда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Шта ће дакле учинити господар од винограда? Доћи ће и погубиће виноградаре, и даће виноград другима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Зар нијесте читали у писму ово: камен који одбацише зидари, онај поста глава од угла;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'То би од Господа и дивно је у нашијем очима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'И гледаху да га ухвате, али се побојаше народа; јер разумјеше да за њих говори причу; и оставивши га отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'И послаше к њему неке од фарисеја и Иродоваца да би га ухватили у ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'А они дошавши рекоше му: учитељу! знамо да си истинит, и да не мариш ни за кога; јер не гледаш ко је ко, него заиста путу Божијему учиш; треба ли ћесару давати харач или не? Хоћемо ли дати или да не дамо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'А он знајући њихово лицемјерје рече им: што ме кушате? Донесите ми новац да видим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'А они донесоше. И рече им: чиј је образ овај и натпис? А они му рекоше: ћесарев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'И одговарајући Исус рече им: подајте ћесарево ћесару, и Божије Богу. И чудише му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'И дођоше к њему садукеји који кажу да нема васкрсенија, и запиташе га говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Учитељу! Мојсије нам написа: ако коме брат умре и остави жену а дјеце не остави, да брат његов узме жену његову и да подигне сјеме брату својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Седам браће бјеше: и први узе жену, и умрије без порода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'И други узе је, и умрије, и ни он не остави порода; тако и трећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'И узеше је седморица, и не оставише порода. А послије свију умрије и жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'О васкрсенију дакле кад устану кога ће од њих бити жена? јер је за седморицом била.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'И одговарајући Исус рече им: зато ли се ви варате што не знате писма ни силе Божије?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Јер кад из мртвијех устану, нити ће се женити ни удавати, него су као анђели на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'А за мртве да устају нијесте ли читали у књигама Мојсијевијем како му рече Бог код купине говорећи: ја сам Бог Авраамов, и Бог Исаков, и Бог Јаковљев?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Није Бог Бог мртвијех, него Бог живијех. Ви се дакле врло варате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'И приступи један од књижевника који их слушаше како се препиру, и видје да им добро одговара, и запита га: која је прва заповијест од свију?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'А Исус одговори му: прва је заповијест од свију: чуј Израиљу, Господ је Бог наш Господ једини;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'И љуби Господа Бога својега свијем срцем својијем и свом душом својом и свијем умом својијем и свом снагом својом. Ово је прва заповијест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'И друга је као и ова: љуби ближњега својега као самога себе. Друге заповијести веће од овијех нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'И рече му књижевник: добро, учитељу! право си казао да је један Бог, и нема другога осим њега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'И љубити га свијем срцем и свијем разумом и свом душом и свом снагом, и љубити ближњега као самога себе, веће је од свију жртава и прилога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'А Исус видјевши како паметно одговори рече му: нијеси далеко од царства Божијега. И нико више не смијаше да га запита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'И одговори Исус и рече учећи у цркви: како говоре књижевници да је Христос син Давидов?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Јер сам Давид каза Духом светијем: рече Господ Господу мојему: сједи мени с десне стране, док положим непријатеље твоје подножје ногама твојима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Сам дакле Давид назива га Господом, и откуда му је син? И многи народ слушаше га с радошћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'И говораше им у науци својој: чувајте се књижевника који иду у дугачкијем хаљинама, и траже да им се клања по улицама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'И првијех мјеста по зборницама, и зачеља на гозбама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Ови што једу куће удовичке, и лажно се моле Богу дуго, биће још већма осуђени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'И сједавши Исус према Божијој хазни гледаше како народ меће новце у Божију хазну. И многи богати метаху много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'И дошавши једна сиромашна удовица метну двије лепте, које чине један кодрант.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'И дозвавши ученике своје рече им: заиста вам кажем: ова сиромашна удовица метну више од свију који мећу у Божију хазну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Јер сви метнуше од сувишка својега; а она од сиротиње своје метну све што имаше, сву храну своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'И кад излажаше из цркве рече му један од ученика његовијех: учитељу! гле какво је камење, и каква грађевина!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'И одговарајући Исус рече му: видиш ли ове велике грађевине? ни камен на камену неће овдје остати који се неће разметнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'И кад сјеђаше на гори Маслинској према цркви, питаху га сама Петар и Јаков и Јован и Андрија:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Кажи нам кад ће то бити? и какав ће знак бити кад ће се то све свршити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'А Исус одговарајући им поче говорити: чувајте се да вас ко не превари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Јер ће многи доћи на моје име говорећи: ја сам; и многе ће преварити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'А кад чујете ратове и гласове о ратовима, не плашите се; јер треба то да буде; али то још није пошљедак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Устаће народ на народ и царство на царство; и земља ће се трести по свијету; и биће глади и буне. То је почетак страдању.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'А ви се чувајте; јер ће вас предавати у судове и по зборницама биће вас, и пред краљеве и цареве изводиће вас мене ради за свједочанство њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'И у свима народима треба да се најприје проповједи јеванђеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'А кад вас поведу да предају, не брините се напријед шта ћете говорити, нити мислите; него што вам се да у онај час оно говорите; јер ви не ћете говорити него Дух свети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'И предаће брат брата на смрт и отац сина, и устаће дјеца на родитеље и побиће их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'И сви ће омрзнути на вас имена мојега ради. Али који претрпи до краја благо њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'А кад видите мрзост опушћења, за коју говори пророк Данило, да стоји гдје не треба (који чита да разумије): тада који буду у Јудеји нека бјеже у горе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'И који буде на крову да не силази у кућу, нити да улази да узме што из куће своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'И који буде у пољу да се не враћа натраг да узме хаљину своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Али тешко труднима и дојилицама у те дане!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Него се молите Богу да не буде бјежан ваша у зиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Јер ће у дане те бити невоља какова није била од почетка створења које је Бог створио досад, и неће ни бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'И да Господ не скрати дане нико не би остао; али избранијех ради, које избра, скратио је дане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Тада ако вам ко рече: ево овдје је Христос; или: ено ондје; не вјерујте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Јер ће изићи лажни христоси и лажни пророци, и показаће знаке и чудеса да би преварили, ако буде могуће, и избране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Али ви се чувајте: ето вам све казах напријед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Али у те дане, послије те невоље, сунце ће помрчати, и мјесец своју свјетлост изгубити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'И звијезде ће спадати с неба и силе небеске покренути се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'И тада ће угледати сина човјечијега гдје иде на облацима са силом и славом великом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'И тада ће послати анђеле своје и сабраће избране своје од четири вјетра, од краја земље до краја неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'А од смокве научите се причи: кад се већ њезина грана помлади и стане листати, знате да је близу љето.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Тако и ви кад видите ово да се збива, знајте да је близу код врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Заиста вам кажем да овај нараштај неће проћи док се ово све не збуде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Небо и земља проћи ће, али ријечи моје неће проћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'А о дану томе или о часу нико не зна, ни анђели који су на небесима, ни син, до отац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Пазите, стражите и молите се Богу; јер не знате кад ће вријеме настати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Као што човјек одлазећи остави кућу своју, и да слугама својима власт, и свакоме свој посао; и вратару заповједи да стражи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Стражите дакле; јер не знате кад ће доћи господар од куће, или увече или у поноћи, или у пијетле, или ујутру;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'Да не дође изненада и да вас не нађе а ви спавате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'А што вам кажем, свима кажем: стражите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Бијаху пак још два дана до пасхе и до дана пријеснијех хљебова; и тражаху главари свештенички и књижевници како би га из пријеваре ухватили и убили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Али говораху: не о празнику, да се не би народ побунио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'И кад бијаше он у Витанији у кући Симона губавога и сјеђаше за трпезом, дође жена са скленицом многоцјенога мира чистога нардова, и разбивши скленицу љеваше му на главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'А неки се срђаху говорећи: зашто се то миро просипа тако?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Јер се могаше за њ узети више од триста гроша и дати сиромасима. И викаху на њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'А Исус рече: оставите је; шта јој сметате? она учини добро дјело на мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Јер сиромахе имате свагда са собом, и кад год хоћете можете им добро чинити; а мене немате свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Она што може, учини: она помаза напријед тијело моје за укоп.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Заиста вам кажем: гдје се год успроповиједа јеванђеље ово по свему свијету, казаће се и то за спомен њезин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'И Јуда Искариотски, један од дванаесторице отиде ка главарима свештеничкијем да им га изда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'А они чувши обрадоваше се, и обрекоше му новце дати: и тражаше згоду да га изда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'И у први дан пријеснијех хљебова, кад клаху пасху, рекоше му ученици његови: гдје ћеш да идемо да ти зготовимо пасху да једеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'И посла двојицу од ученика својијех и рече им: идите у град, и срешће вас човјек који носи воду у крчагу; идите за њим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'И гдје уђе кажите господару од оне куће: учитељ вели: гдје је гостионица гдје ћу јести пасху с ученицима својијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'И он ће вам показати велику собу прострту готову: ондје нам зготовите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'И изиђоше ученици његови, и дођоше у град, и нађоше као што им каза, и уготовише пасху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'И кад би увече, дође са дванаесторицом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'И кад сјеђаху за трпезом и јеђаху рече Исус: заиста вам кажем: један од вас, који једе са мном, издаће ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'А они се забринуше, и стадоше говорити један за другијем: да не ја? и други: да не ја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'А он одговарајући рече им: један од дванаесторице који умочи са мном у здјелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Син човјечиј дакле иде као што је писано за њега; али тешко ономе човјеку који изда сина човјечијега; боље би му било да се није родио онај човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'И кад јеђаху узе Исус хљеб и благословивши преломи га, и даде им, и рече: узмите, једите; ово је тијело моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'И узе чашу и давши хвалу даде им; и пише из ње сви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'И рече им: ово је крв моја новога завјета која ће се пролити за многе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Заиста вам кажем: више нећу пити од рода виноградскога до онога дана кад ћу га пити новога у царству Божијему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'И отпојавши хвалу изиђоше на гору Маслинску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'И рече им Исус: сви ћете се ви саблазнити о мене ову ноћ; јер је писано: ударићу пастира и овце ће се разбјећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Али по васкрсенију својему ја идем пред вама у Галилеју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'А Петар му рече: ако се и сви саблазне, али ја нећу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'И рече му Исус: заиста ти кажем: ноћас док двапут пијетао не запјева три пута ћеш ме се одрећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'А он још већма говораше: да бих знао с тобом и умријети нећу те се одрећи. Тако и сви говораху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'И дођоше у село које се зове Гетсиманија, и рече ученицима својијем: сједите овдје док ја идем да се помолим Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'И узе са собом Петра и Јакова и Јована, и забрину се и поче тужити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'И рече им: жалосна је душа моја до смрти; почекајте овдје, и стражите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'И отишавши мало паде на земљу, и мољаше се да би га мимоишао час ако је могуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'И говораше: Ава оче! све је могуће теби; пронеси чашу ову мимо мене; али опет не како ја хоћу него како ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'И дође и нађе их гдје спавају, и рече Петру: Симоне! Зар спаваш? Не може ли једнога часа постражити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Стражите и молите се Богу да не паднете у напаст; јер је дух срчан али је тијело слабо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'И опет отишавши помоли се Богу оне исте ријечи говорећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'И вративши се нађе их опет гдје спавају; јер им бијаху очи отежале; и не знадијаху шта би му одговорили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'И дође трећи пут, и рече им: једнако спавате и почивате; доста је; дође час; ево се предаје син човјечиј у руке грјешницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Устаните да идемо; ево издајник се мој приближи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'И одмах док он још говораше, дође Јуда, један од дванаесторице, и с њим људи многи с ножевима и с кољем од главара свештеничкијех и од књижевника и старјешина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'И издајник његов даде им знак говорећи: кога ја цјеливам онај је: држите га, и водите га чувајући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'И дошавши одмах приступи к њему, и рече: Рави! рави! и цјелива га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'А они метнуше руке своје на њ и ухватише га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'А један од онијех што стајаху ондје извади нож те удари слугу поглавара свештеничкога, и отсијече му ухо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'И одговарајући Исус рече им: као на хајдука изишли сте с ножевима и с кољем да ме ухватите,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'А сваки дан сам био код вас у цркви и учио, и не ухватисте ме. Али да се збуде писмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'И оставивши га ученици сви побјегоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'И за њим иђаше некакав младић огрнут платном по голу тијелу; и ухватише онога младића.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'А он оставивши платно го побјеже од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'И доведоше Исуса к поглавару свештеничкоме, и стекоше се к њему сви главари свештенички и књижевници и старјешине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'И Петар иде за њим издалека до у двор поглавара свештеничкога, и сјеђаше са слугама, и гријаше се код огња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'А главари свештенички и сва скупштина тражаху на Исуса свједочанства да га убију; и не нађоше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Јер многи свједочаху лажно на њега и свједочанства не бијаху једнака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'И једни уставши свједочаху на њега лажно говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Ми смо чули гдје он говори: ја ћу развалити ову цркву која је рукама начињена, и за три дана начинићу другу која неће бити рукама начињена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'И ни ово свједочанство њихово не бијаше једнако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'И уставши поглавар свештенички на сриједу запита Исуса говорећи: зар ништа не одговараш што ови на тебе свједоче?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'А он мучаше и ништа не одговараше. Опет поглавар свештенички запита и рече: јеси ли ти Христос, син благословенога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'А Исус рече: јесам; и видјећете сина човјечијега гдје сједи с десне стране силе и иде на облацима небескијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'А поглавар свештенички раздрије своје хаљине, и рече: шта нам требају више свједоци?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Чусте хулу на Бога; шта мислите? А они сви казаше да је заслужио смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'И почеше једни пљувати на њ, и покривати му лице, и ћушати га, и говорити му: прореци; и слуге га бијаху по образима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'И кад бијаше Петар доље на двору, дође једна од слушкиња поглавара свештеничкога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'И видјевши Петра гдје се грије погледа на њ и рече: и ти си био с Исусом Назарећанином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'А он се одрече говорећи: не знам нити разумијем шта ти говориш. И изиђе напоље пред двор: и пијетао запјева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'И опет кад га видје слушкиња, поче говорити онима што стајаху ондје: овај је од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'А он се опет одрицаше. И мало затијем опет они што стајаху ондје рекоше Петру: ваистину си од њих: јер си Галилејац, и говор ти је онакови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'А он се поче клети и преклињати: не знам тога човјека за кога ви говорите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'И други пут запјева пијетао. И опомену се Петар ријечи што му рече Исус: док пијетао двапут не запјева одрећи ћеш ме се трипут. И стаде плакати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'И одмах ујутру учинише вијећу главари свештенички са старјешинама и књижевницима, и сав сабор, и свезавши Исуса одведоше га и предадоше Пилату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'И упита га Пилат: јеси ли ти цар Јудејски? А он одговарајући рече му: ти кажеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'И тужаху га главари свештенички врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'А Пилат опет упита га говорећи: зар ништа не одговараш? Гледај шта свједоче на тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Али Исус више не одговори ништа тако да се дивљаше Пилат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'А о сваком празнику пушташе им по једнога сужња кога искаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'А бијаше један затворен, по имену Варава, са својијем другарима који су у буни учинили крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'И повикавши народ стаде искати што им свагда чињаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'А Пилат им одговори говорећи: хоћете ли да вам пустим цара Јудејскога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Јер знадијаше да су га из зависти предали главари свештенички.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Али главари свештенички подговорише народ боље Вараву да ишту да им пусти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'А Пилат опет одговарајући рече им: а шта хоћете да чиним с тијем што га зовете царем Јудејскијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'А они опет повикаше: распни га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'А Пилат им рече: а какво је зло учинио? А они иза гласа викаху: распни га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'А Пилат желећи угодити народу пусти им Вараву, а Исуса шибавши предаде да га разапну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'А војници га одведоше у судницу, и сазваше сву чету војника,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'И обукоше му скерлетну кабаницу, и оплетавши вијенац од трња метнуше на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'И стадоше га поздрављати говорећи: здраво, царе Јудејски!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'И бијаху га по глави трском, и пљуваху на њ, и падајући на кољена поклањаху му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'И кад му се наругаше, свукоше с њега скерлетну кабаницу, и обукоше га у његове хаљине и изведоше га да га разапну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'И натјераше некога Симона из Кирине, оца Александрова и Руфова, који иђаше из поља, да му понесе крст.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'И доведоше га на мјесто Голготу, које ће рећи: коштурница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'И даваху му да пије вино са смирном, а он не узе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'И кад га разаспеше, раздијелише хаљине његове бацајући коцке за њих ко ће шта узети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'А бијаше сахат трећи кад га разапеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'И бијаше натпис његове кривице написан: цар Јудејски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'И с њим распеше два хајдука, једнога с десне а једнога с лијеве стране њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'И изврши се писмо које говори: и метнуше га међу злочинце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'И који пролажаху хуљаху на њ машући главама својима и говорећи: аха! ти што цркву разваљујеш и за три дана начињаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Помози сам себи и сиђи с крста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Тако и главари свештенички с књижевницима ругаху се говорећи један другоме: другима поможе, а себи не може помоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Христос цар Израиљев нека сиђе сад с крста да видимо, па ћемо му вјеровати. И они што бијаху с њим разапети ругаху му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'А у шестоме сахату би тама по свој земљи до сахата деветога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'И у деветоме сахату повика Исус иза гласа говорећи: Елои! Елои! лама савахтани? које значи: Боже мој! Боже мој! зашто си ме оставио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'И неки од онијех што стајаху ондје чувши то говораху: ено зове Илију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'А један отрча те напуни сунђер оцта, па натакнувши на трску појаше га говорећи: станите да видимо хоће ли доћи Илија да га скине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'А Исус повика иза гласа, и издахну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'И завјес црквени раздрије се на двоје с врха до на дно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'А кад видје капетан који стајаше према њему да с таком виком издахну, рече: заиста човјек овај син Божиј бјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'А бијаху и жене које гледаху издалека, међу којима бјеше и Марија Магдалина и Марија Јакова малога и Јосије мати, и Соломија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'Које иђаху за њим и кад бјеше у Галилеји, и служаху му; и друге многе које бијаху дошле с њим у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'И кад би у вече (јер бијаше петак, то јест у очи суботе),');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Дође Јосиф из Ариматеје, поштен савјетник, који и сам царства Божијега чекаше, и усуди се те уђе к Пилату и заиска тијело Исусово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'А Пилат се зачуди да је већ умро; и дозвавши капетана запита га: је ли давно умро?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'И дознавши од капетана, даде тијело Јосифу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'И купивши платно, и скинувши га, обави платном, и метну га у гроб који бјеше исјечен у камену, и навали камен на врата од гроба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'А Марија Магдалина и Марија Јосијина гледаху гдје га метаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'И пошто прође субота, Марија Магдалина и Марија Јаковљева и Соломија купише мириса да дођу и да помажу Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'И врло рано у први дан недјеље дођоше на гроб око сунчанога рођаја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'И говораху међу собом: ко ће нам одвалити камен од врата гробнијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'И погледавши видјеше да камен бјеше одваљен: јер бјеше врло велики.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'И ушавши у гроб видјеше младића обучена у бијелу хаљину гдје сједи с десне стране; и уплашише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'А он им рече: не плашите се, Исуса тражите Назарећанина распетога; уста, није овдје, ево мјесто гдје га метнуше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Него идите кажите ученицима његовијем и Петру да пред вама отиде у Галилеју: тамо ћете га видјети, као што вам рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'И изишавши побјегоше од гроба; јер их ухвати дрхат и страх; и ником ништа не казаше, јер се бојаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'А Исус уставши рано у први дан недјеље јави се најприје Марији Магдалини, из које је истјерао седам ђавола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'А она отиде те јави онима што су били с њим, који плакаху и ридаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'И они чувши да је жив и да га је она видјела не вјероваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'А потом јави се на путу двојици од њих у другоме обличју, кад су ишли у село.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'И они отишавши јавише осталима; и ни њима не вјероваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'А најпослије јави се кад њих једанаесторица бијаху за трпезом, и прекори их за њихово невјерје и тврђу срца што не вјероваше онима који су га видјели да је устао;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'И рече им: идите по свему свијету и проповједите јеванђеље свакоме створењу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Који узвјерује и покрсти се, спашће се; а ко не вјерује осудиће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'А знаци онима који вјерују биће ови: именом мојијем изгониће ђаволе; говориће новијем језицима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'Узимаће змије у руке, ако и смртно што попију, неће им наудити; на болеснике метаће руке, и оздрављаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'А Господ пошто им изговори узе се на небо, и сједе Богу с десне стране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'А они изиђоше и проповједаше свуда, и Господ их потпомага, и ријеч потврђива знацима који су се потом показивали. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Будући да многи почеше описивати догађаје који се испунише међу нама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'Као што нам предаше који испрва сами видјеше и слуге ријечи бише:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Намислих и ја, испитавши све од почетка, по реду писати теби, честити Теофиле,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Да познаш темељ онијех ријечи којима си се научио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'У вријеме Ирода цара Јудејскога бијаше неки свештеник од реда Авијна, по имену Зарија, и жена његова од племена Аронова, по имену Јелисавета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'А бијаху обоје праведни пред Богом, и живљаху у свему по заповијестима и уредбама Господњијем без мане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'И не имадијаху дјеце; јер Јелисавета бјеше нероткиња, и бијаху обоје већ стари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'И догоди се, кад он служаше по своме реду пред Богом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Да по обичају свештенства дође на њега да изиђе у цркву Господњу да кади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'И све мноштво народа бијаше напољу и мољаше се Богу у вријеме кађења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'А њему се показа анђео Господњи који стајаше с десне стране олтара кадионога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'И кад га видје Зарија уплаши се и страх нападе на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'А анђео рече му: не бој се, Зарија; јер је услишена твоја молитва: и жена твоја Јелисавета родиће ти сина и надјени му име Јован.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'И биће теби радост и весеље, и многи ће се обрадовати његову рођењу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Јер ће бити велики пред Богом, и неће пити вина ни сикера; и напуниће се Духа светога још у утроби матере своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'И многе ће синове Израиљеве обратити ка Господу Богу њиховоме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'И он ће напријед доћи пред њим у духу и сили Илијној да обрати срца отаца к дјеци и невјернике к мудрости праведника, и да приправи Господу народ готов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'И рече Зарија анђелу: по чему ћу ја то познати? јер сам стар и жена је моја временита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'И одговарајући анђео рече му: Ја сам Гаврило што стојим пред Богом, и послан сам да говорим с тобом и да ти јавим ову радост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'И ево, онијемићеш и нећеш моћи говорити до онога дана док се то не збуде; јер нијеси вјеровао мојим ријечима које ће се збити у своје вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'И народ чекаше Зарију, и чуђаху се што се забави у цркви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'А изишавши не могаше да им говори; и разумјеше да му се нешто утворило у цркви; и он намигиваше им; и оста нијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'И кад се навршише дани његове службе отиде кући својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'А послије овијех дана затрудње Јелисавета жена његова,и кријаше се пет мјесеци говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Тако ми учини Господ у дане ове у које погледа на ме да ме избави од укора међу људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'А у шести мјесец посла Бог анђела Гаврила у град Галилејски по имену Назарет');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'К дјевојци испрошеној за мужа, по имену Јосифа из дома Давидова; и дјевојци бјеше име Марија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'И ушавши к њој анђео рече: радуј се, благодатна! Господ је с тобом, благословена си ти међу женама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'А она видјевши га поплаши се од ријечи његове и помисли: какав би ово био поздрав?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'И рече јој анђео: не бој се, Марија! Јер си нашла милост у Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'И ево затрудњећеш, и родићеш сина, и надјени му име Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Он ће бити велики, и назваће се син највишега, и даће му Господ Бог пријесто Давидов оца његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'И цароваће у дому Јаковљеву вавијек, и царству његовом неће бити краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'А Марија рече анђелу: како ће то бити кад ја не знам за мужа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'И одговарајући анђео рече јој: дух свети доћи ће на тебе, и сила највишега осјениће те; зато и оно што ће се родити биће свето, и назваће се син Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'И ево Јелисавета твоја тетка, и она затрудње сином у старости својој, и ово је шести мјесец њојзи, коју зову нероткињом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Јер у Бога све је могуће што рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'А Марија рече: ево слушкиње Господње; нека ми буде по ријечи твојој. И анђео отиде од ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'А Марија уставши онијех дана отиде брзо у горњу земљу у град Јудин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'И уђе у кућу Заријину, и поздрави се с Јелисаветом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'И кад Јелисавета чу честитање Маријино, заигра дијете у утроби њезиној, и Јелисавета се напуни Духа светога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'И повика здраво и рече: благословена си ти међу женама, и благословен је плод утробе твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'И откуд мени ово да дође мати Господа мојега к мени?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Јер гле, кад дође глас честитања твојега у уши моје, заигра дијете радосно у утроби мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'И благо оној која вјерова; јер ће се извршити што јој каза Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'И рече Марија: велича душа моја Господа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'И обрадова се дух мој Богу спасу мојему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Што погледа на понижење слушкиње своје; јер гле, отсад ће ме звати блаженом сви нараштаји;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Што ми учини величину силни, и свето име његово;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'И милост је његова од кољена на кољено онима који га се боје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Показа силу руком својом; разасу поносите у мислима срца њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Збаци силне с пријестола, и подиже понижене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Гладне напуни блага, и богате отпусти празне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Прими Израиља слугу својега да се опомене милости;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'Као што говори оцима нашијем, Аврааму и сјемену његову довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Марија пак сједи с њом око три мјесеца, и врати се кући својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'А Јелисавети дође вријеме да роди, и роди сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'И чуше њезини сусједи и родбина да је Господ показао велику милост своју на њој, и радоваху се с њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'И у осми дан дођоше да обрежу дијете, и шћадијаху да му надјену име оца његова, Зарија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'И одговарајући мати његова рече не, него да буде Јован.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'И рекоше јој: никога нема у родбини твојој да му је такво име.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'И намигиваху оцу његову како би он хтио да му надјену име.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'И заискавши дашчицу, написа говорећи: Јован му је име. И зачудише се сви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'И одмах му се отворише уста и језик његов, и говораше хвалећи Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'И уђе страх у све сусједе њихове; и по свој горњој Јудеји разгласи се сав овај догађај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'И сви који чуше метнуше у срце своје говорећи: шта ће бити из овога дјетета? И рука Господња бјеше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'И Зарија отац његов напуни се Духа светога, и пророкова говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Благословен Господ Бог Јаковљев што походи и избави народ свој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'И подиже нам рог спасенија у дому Давида слуге својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'Као што говори устима светијех пророка својијех од вијека');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Да ће нас избавити од нашијех непријатеља и из руку свију који мрзе на нас;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Учинити милост оцима нашијем, и опоменути се светога завјета својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'Клетве којом се клео Аврааму оцу нашему да ће нам дати');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'Да се избавимо из руку непријатеља својијех, и да му служимо без страха,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'И у светости и у правди пред њим док смо год живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'И ти, дијете, назваћеш се пророк највишега; јер ћеш ићи напријед пред лицем Господњијем да му приправиш пут;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'Да даш разум спасенија народу његову за опроштење гријеха њиховијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'По дубокој милости Бога нашега, по којој нас је походио исток с висине;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'Да обасјаш оне који сједе у тами и у сјену смртноме; да упутиш ноге наше на пут мира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'А дијете растијаше и јачаше духом, и бијаше у пустињи дотле док се не показа Израиљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'У то вријеме пак изиђе заповијест од ћесара Августа да се препише сав свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Ово је био први пријепис за владања Киринова Сиријом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'И пођоше сви да се препишу сваки у свој град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Тада пође и Јосиф из Галилеје из града Назарета у Јудеју у град Давидов који се зваше Витлејем, јер он бијаше из дома и племена Давидова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Да се препише с Маријом, испрошеном за њега женом, која бјеше трудна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'И кад онамо бијаху, дође вријеме да она роди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'И роди сина својега првенца, и пови га, и метну га у јасле; јер им не бијаше мјеста у гостионици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'И бијаху пастири у ономе крају који чуваху ноћну стражу код стада својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'И гле, анђео Господњи стаде међу њима, и слава Господња обасја их; и уплашише се врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'И рече им анђео: не бојте се; јер гле, јављам вам велику радост која ће бити свему народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Јер вам се данас роди спас, који је Христос Господ, у граду Давидову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'И ето вам знака: наћи ћете дијете повито гдје лежи у јаслима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'И уједанпут постаде с анђелом мноштво војника небескијех, који хваљаху Бога говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Слава на висини Богу, и на земљи мир, међу људима добра воља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'И кад анђели отидоше од њих на небо, пастири говораху један другоме: хајдемо до Витлејема, да видимо то што се тамо догодило што нам каза Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'И дођоше брзо, и нађоше Марију и Јосифа и дијете гдје лежи у јаслима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'А кад видјеше, казаше све што им је казано за то дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'И сви који чуше дивише се томе што им казаше пастири.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'А Марија чуваше све ријечи ове и слагаше их у срцу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'И вратише се пастири славећи и хвалећи Бога за све што чуше и видјеше као што им би казано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'И кад се наврши осам дана да га обрежу, надјенуше му име Исус, као што је анђео рекао док се још није био ни заметнуо у утроби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'И кад дође вријеме да иду на молитву по закону Мојсијеву, донијеше га у Јерусалим да га метну пред Господа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(Као што је написано у закону Господњему: да се свако дијете мушко које најприје отвори материцу посвети Господу;)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'И да принесу прилог, као што је речено у закону Господњему, двије грлице, или два голубића.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'И гле, бијаше у Јерусалиму човјек по имену Симеун, и тај човјек бјеше праведан и побожан, који чекаше утјехе Израиљеве, и Дух свети бијаше у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'И њему бјеше свети Дух казао да неће видјети смрти док не види Христа Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'И каза му Дух те дође у цркву; и кад донесоше родитељи дијете Исуса да сврше за њега закон по обичају,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'И он га узе на руке своје, и хвали Бога и рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Сад отпушташ с миром слугу својега, Господе, по ријечи својој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'Јер видјеше очи моје спасеније твоје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'Које си уготовио пред лицем свију народа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Видјело, да обасја незнабошце, и славу народа твојега Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'И Јосиф и мати његова чуђаху се томе што се говораше за њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'И благослови их Симеун, и рече Марији матери његовој: гле, овај лежи да многе обори и подигне у Израиљу, и да буде знак против кога ће се говорити');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(А и теби самој пробошће нож душу), да се открију мисли многијех срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'И бјеше Ана пророчица, кћи Фануилова, од кољена Асирова; она је остарјела, а седам је година живљела с мужем од дјевојаштва својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'И удова око осамдесет и четири године, која не одлажаше од цркве, и служаше Богу дан и ноћ постом и молитвама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'И она у тај час дође, и хваљаше Господа и говораше за њега свима који чекаху спасенија у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'И кад свршише све по закону Господњему, вратише се у Галилеју у град свој Назарет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'А дијете растијаше и јачаше у духу, и пуњаше се премудрости, и благодат Божија бјеше на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'И родитељи његови иђаху сваке године у Јерусалим о празнику пасхе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'И кад му би дванаест година, дођоше они у Јерусалим по обичају празника;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'И кад дане проведоше и они се вратише, оста дијете Исус у Јерусалиму; и не знаде Јосиф и мати његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Него мислећи да је с друштвом, отидоше дан хода, и стадоше га тражити по родбини и по знанцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'И не нашавши га вратише се у Јерусалим да га траже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'И послије три дана нађоше га у цркви гдје сједи међу учитељима, и слуша их, и пита их,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'И сви који га слушаху дивљаху се његову разуму и одговорима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'И видјевши га зачудише се, и мати његова рече му: сине! шта учини нама тако? Ево отац твој и ја са страхом тражисмо те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'И рече им: зашто сте ме тражили? Зар не знате да мени треба у оном бити што је оца мојега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'И они не разумјеше ријечи што им рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'И сиђе с њима и дође у Назарет; и бијаше им послушан. И мати његова чуваше све ријечи ове у срцу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'И Исус напредоваше у премудрости и у расту и у милости код Бога и код људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'У петнаестој години владања ћесара Тиверија, кад бјеше Понтије Пилат судија у Јудеји, и Ирод четверовласник у Галилеји, а Филип брат његов четверовласник у Итуреји и у Трахонитској, и Лисанија четверовласник у Авилини,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'За поглавара свештеничкијех Ане и Кајафе, рече Бог Јовану сину Заријну у пустињи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'И дође у сву околину Јорданску проповиједајући крштење покајања за опроштење гријеха;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'Као што је написано у књизи ријечи пророка Исаије који говори: глас онога што виче у пустињи: приправите пут Господњи; поравните стазе његове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Све долине нека се испуне, и све горе и брегови нека се слегну; и што је криво нека буде право, и храпави путови нека буду глатки;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'И свако ће тијело видјети спасеније Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Јован пак говораше људима који излажаху да их крсти: породи аспидини! ко вам каза да бјежите од гњева који иде?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Родите дакле родове достојне покајања, и не говорите у себи: оца имамо Авраама; јер вам кажем да Бог може и од овога камења подигнути дјецу Аврааму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Јер већ и сјекира стоји дрвету код коријена; и свако дрво које добра рода не рађа сијече се и у огањ се баца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'И питаху га људи говорећи: шта ћемо дакле чинити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Он пак одговарајући рече им: који има двије хаљине нека да једну ономе који нема; и ко има хране нека чини тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Дођоше пак и цариници да их крсти, и рекоше му: учитељу! шта ћемо чинити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'А он им рече: не иштите више него што вам је речено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Питаху га пак и војници говорећи: а ми шта ћемо чинити? И рече им: никоме да не чините силе нити кога да опадате, и будите задовољни својом платом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'А кад народ бјеше у сумњи и помишљаху сви у срцима својијем за Јована: да није он Христос?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Одговараше Јован свима говорећи: ја вас крстим водом; али иде за мном јачи од мене, коме ја нијесам достојан одријешити ремена на обући његовој; он ће вас крстити Духом светијем и огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Он има лопату у руци својој, и очистиће гумно своје, и скупиће пшеницу своју, а пљеву ће сажећи огњем вјечнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'И друго много којешта јавља народу и напомиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Ирода пак четверовласника кораше Јован за Иродијаду, жену брата његова, и за сва зла што учини Ирод;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'И сврх свега учини и то те затвори Јована у тамницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'А кад се крсти сав народ, и Исус пошто се крсти и мољаше се Богу, отвори се небо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'И сиђе на њ Дух свети у тјелесноме облику као голуб, и чу се глас с неба говорећи: ти си син мој љубазни, ти си по мојој вољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'И тај Исус имаше око тридесет година кад поче; и бјеше, као што се мишљаше, син Јосифа сина Илијна,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'Сина Мататова, сина Левијна, сина Мелхијна, сина Јенејева, сина Јосифова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'Сина Мататијна, сина Амосова, сина Наумова, сина Еслијна, сина Нангејева,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'Сина Маатова, сина Мататијна, сина Семејина, сина Јосифова, сина Јудина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'Сина Јоанина, сина Рисина, сина Зоровавељева, сина Салатиилова, сина Ниријна,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'Сина Мелхијна, сина Адијна, сина Косамова, сина Ирова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'Сина Јосијна, сина Елиезерова, сина Јоримова, сина Мататова, сина Левијна,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'Сина Симеунова, сина Јудина, сина Јосифова, сина Јонанова, сина Елиакимова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'Сина Мелејина, сина Маинанова, сина Мататина, сина Натанова, сина Давидова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'Сина Јесејева, сина Овидова, сина Воозова, сина Салмонова, сина Наасонова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'Сина Аминадавова, сина Арамова, сина Есромова, сина Фаресова, сина Јудина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'Сина Јаковљева, сина Исакова, сина Авраамова, сина Тарина, сина Нахорова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'Сина Серухова, сина Рагавова, сина Фалекова, сина Еверова, сина Салина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'Сина Каинанова, сина Арфаксадова, сина Симова, сина Нојева, сина Ламехова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'Сина Матусалина, сина Енохова, сина Јаредова, сина Малелеилова, сина Каинанова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'Сина Еносова, сина Ситова, сина Адамова, сина Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Исус пак пун Духа светога врати се од Јордана, и одведе га Дух у пустињу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'И четрдесет дана куша га ђаво, и не једе ништа за то дана; и кад се они навршише, онда огладње,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'И рече му ђаво: ако си син Божиј, реци овоме камену да постане хљеб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'И одговори му Исус говорећи: у писму стоји: неће живљети човјек о самом хљебу, него о свакој ријечи Божијој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'И изведавши га ђаво на гору високу показа му сва царства овога свијета у тренућу ока,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'И рече му ђаво: теби ћу дати сву власт ову и славу њихову, јер је мени предана, и коме ја хоћу даћу је;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Ти дакле ако се поклониш преда мном биће све твоје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'И одговарајући Исус рече му: иди од мене, сотоно; у писму стоји: поклањај се Господу Богу својему, и њему јединоме служи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'И одведе га у Јерусалим, и постави га наврх цркве, и рече му: ако си син Божиј, скочи одавде доље;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'Јер у писму стоји да ће анђелима својијем заповједити за тебе да те сачувају,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'И узеће те на руке да гдје не запнеш за камен ногом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'И одговарајући Исус рече му: казано је: не кушај Господа Бога својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'И кад сврши ђаво све кушање, отиде од њега за неко вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'И врати се Исус у сили духовној у Галилеју; и отиде глас о њему по свему оном крају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'И он учаше по зборницама њиховијем, и сви га хваљаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'И дође у Назарет гдје бјеше одрастао, и уђе по обичају своме у дан суботни у зборницу, и устаде да чита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'И даше му књигу пророка Исаије, и отворивши књигу нађе мјесто гдје бјеше написано:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'Дух је Господњи на мени; зато ме помаза да јавим јеванђеље сиромасима; посла ме да исцијелим скрушене у срцу; да проповједим заробљенима да ће се отпустити, и слијепима да ће прогледати; да отпустим сужње;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'И да проповиједам пријатну годину Господњу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'И затворивши књигу даде слузи, па сједе: и сви у зборници гледаху на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'И поче им говорити: данас се изврши ово писмо у ушима вашима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'И сви му свједочаху, и дивљаху се ријечима благодати које излажаху из уста његовијех, и говораху: није ли ово син Јосифов?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'И рече им: ви ћете мени без сумње казати ову причу: љекару! излијечи се сам; што смо чули да си чинио у Капернауму учини и овдје на својој постојбини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Рече пак: заиста вам кажем: никакав пророк није мио на својој постојбини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'А заиста вам кажем: многе удовице бијаху у Израиљу у вријеме Илијно кад се небо затвори три године и шест мјесеци и би велика глад по свој земљи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'И ни к једној од њих не би послан Илија до у Сарепту Сидонску к жени удовици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'И многи бијаху губави у Израиљу за пророка Јелисија; и ниједан се од њих не очисти до Немана Сиријанина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'И сви се у зборници напунише гњева кад чуше ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'И уставши истјераше га напоље из града, и одведоше га наврх горе гдје бијаше њихов град сазидан да би га бацили одозго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Али он прође између њих, и отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'И дође у Капернаум град Галилејски, и учаше их у суботе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'И чуђаху се науци његовој; јер његова бесједа бјеше силна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'И у зборници бјеше човјек у коме бјеше нечисти дух ђаволски, и повика иза гласа');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'Говорећи: прођи се, шта је теби до нас, Исусе Назарећанине? Дошао си да нас погубиш? Знам те ко си, светац Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'И запријети му Исус говорећи: умукни, и изиђи из њега. И оборивши га ђаво на сриједу, изиђе из њега, и нимало му не науди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'И у све уђе страх, и говораху један другоме говорећи: каква је то ријеч, да влашћу и силом заповиједа нечистијем духовима, и излазе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'И отиде глас о њему по свима околнијем мјестима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Уставши пак из зборнице дође у кућу Симонову; а ташту Симонову бјеше ухватила велика грозница, и молише га за њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'И ставши више ње запријети грозници, и пусти је. И одмах устаде и служаше им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'А кад захођаше сунце, сви који имадијаху болеснике од различнијех болести довођаху их к њему; а он на свакога од њих меташе руке, и исцјељиваше их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'А и ђаволи излажаху из многијех вичући и говорећи: ти си Христос син Божиј. И запрећиваше им да не говоре да знаду да је он Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'А кад наста дан, изиђе и отиде у пусто мјесто; и народ га тражаше, и дође к њему, и задржаваху га да не иде од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'А он им рече: и другијем градовима треба ми проповједити јеванђеље о царству Божијему; јер сам на то послан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'И проповиједаше по зборницама Галилејским.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Једанпут пак кад народ належе к њему са слушају ријеч Божију он стајаше код језера Генисаретскога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'И видје двије лађе гдје стоје у крају, а рибари бијаху изишли из њих и испираху мреже:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'И уљезе у једну од лађи која бјеше Симонова, и замоли га да мало одмакне од краја; и сједавши учаше народ из лађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'А кад преста говорити, рече Симону: хајде на дубину, и баците мреже своје те ловите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'И одговарајући Симон рече му: учитељу! сву ноћ смо се трудили, и ништа не ухватисмо: али по твојој ријечи бацићу мрежу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'И учинивши то ухватише велико мноштво риба, и мреже им се продријеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'И намагоше на друштво које бјеше на другој лађи да дођу да им помогну; и дођоше, и напунише обје лађе тако да се готово потопе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'А кад видје Симон Петар, припаде ка кољенима Исусовијем говорећи: изиђи од мене, Господе! ја сам човјек гријешан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Јер бијаше ушао страх у њега и у све који бијаху с њим од мноштва риба које ухватише;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'А тако и у Јакова и Јована, синове Зеведејеве, који бијаху другови Симонови. И рече Исус Симону: не бој се; отселе ћеш људе ловити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'И извукавши обје лађе на земљу оставише све, и отидоше за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'И кад бјеше Исус у једном граду, и гле, човјек сав у губи: и видјевши Исуса паде ничице молећи му се и говорећи: Господе! ако хоћеш можеш ме очистити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'И пруживши руку дохвати га се. И рече: хоћу, очисти се. И одмах губа спаде с њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'И он му заповједи да ником не казује: него иди и покажи се свештенику, и принеси дар за очишћење своје, како је заповједио Мојсије за свједочанство њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Али се глас о њему још већма разлажаше, и мноштво народа стјецаше се да га слушају и да их исцјељује од њиховијех болести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'А он одлажаше у пустињу и мољаше се Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'И један дан учаше он, и ондје сјеђаху фарисеји и законици који бијаху дошли из свију села Галилејскијех и Јудејскијех и из Јерусалима; и сила Господња исцјељиваше их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'И гле, људи донесоше на одру човјека који бјеше узет, и тражаху да га унесу и метну преда њ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'И не нашавши куда ће га унијети од народа, попеше се на кућу и кроз кров спустише га с одром на сриједу пред Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'И видјевши вјеру њихову рече му: човјече! опраштају ти се гријеси твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'И почеше помишљати књижевници и фарисеји говорећи: ко је овај што хули на Бога? Ко може опраштати гријехе осим једнога Бога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'А кад разумје Исус помисли њихове, одговарајући рече им: шта мислите у срцима својијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Шта је лакше рећи: опраштају ти се гријеси твоји? или рећи: устани и ходи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Него да знате да власт има син човјечиј на земљи опраштати гријехе, (рече узетоме:) теби говорим: устани и узми одар свој и иди кући својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'И одмах устаде пред њима, и узе на чему лежаше, и отиде кући својој хвалећи Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'И сви се упропастише, и хваљаху Бога, и напунивши се страха говораху: чуда се нагледасмо данас!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'И потом изиђе, и видје цариника по имену Левија гдје сједи на царини, и рече му: хајде за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'И оставивши све, устаде и пође за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'И зготови му Левије код куће своје велику част; и бјеше много цариника и другијех који сјеђаху с њим за трпезом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'И викаху на њега књижевници и фарисеји говорећи ученицима његовијем: зашто с цариницима и грјешницима једете и пијете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'И одговарајући Исус рече им: не требају здрави љекара него болесни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Ја нијесам дошао да дозовем праведнике него грјешнике на покајање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'А они му рекоше: зашто ученици Јованови посте често и моле се Богу, тако и фарисејски; а твоји једу и пију?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'А он им рече: можете ли сватове натјерати да посте док је женик с њима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Него ће доћи дани кад ће се отети од њих женик, и онда ће постити у оне дане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Каза им пак и причу: нико не меће закрпе од нове хаљине на стару хаљину, иначе ће и нову раздријети, и старој не личи што је од новога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'И нико не љева вина новога у мјехове старе; иначе продре ново вино мјехове и оно се пролије, и мјехови пропадну;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Него вино ново у мјехове нове треба љевати, и обоје ће се сачувати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'И нико пивши старо неће одмах новога; јер вели: старо је боље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Догоди му се пак у прву суботу по другоме дану пасхе да иђаше кроз усјеве, и ученици његови тргаху класје, и сатираху рукама те јеђаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'А неки од фарисеја рекоше им: зашто чините што не ваља чинити у суботу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'И одговарајући Исус рече им: зар нијесте читали оно што учини Давид кад огладње, он и који бијаху с њим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Како уђе у кућу Божију, и узе хљебове постављене и изједе, и даде их онима што бијаху с њим, којијех никоме не ваљаше јести осим јединијех свештеника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'И рече им: син је човјечиј господар и од суботе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'А догоди се у другу суботу да он уђе у зборницу и учаше, и бјеше ондје човјек коме десна рука бјеше суха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Књижевници пак и фарисеји гледаху за њим неће ли у суботу исцијелити, да га окриве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'А он знадијаше помисли њихове, и рече човјеку који имаше суху руку: устани и стани на сриједу. А он устаде и стаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'А Исус рече им: да вас запитам: шта ваља у суботу чинити, добро или зло? одржати душу или погубити? А они мучаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'И погледавши на све њих рече му: пружи руку своју. А он учини тако; и рука поста здрава као и друга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'А они се сви напунише безумља, и говораху један другоме шта би учинили Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Тијех пак дана изиђе на гору да се помоли Богу; и проведе сву ноћ на молитви Божијој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'И кад би дан, дозва ученике своје, и изабра из њих дванаесторицу, које и апостолима назва:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Симона, кога назва Петром, и Андрију брата његова, Јакова и Јована, Филипа и Вартоломија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Матеја и Тому, Јакова Алфејева и Симона прозванога Зилота,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Јуду Јаковљева, и Јуду Искариотскога, који га и издаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'И изишавши с њима стаде на мјесту равном, и гомила ученика његовијех; и мноштво народа из све Јудеје и из Јерусалима, и из приморја Тирскога и Сидонскога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'Који дођоше да га слушају и да се исцјељују од својијех болести, и које мучаху духови нечисти; и исцјељиваху се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'И сав народ тражаше да га се дотакну; јер из њега излажаше сила и исцјељиваше их све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'И он подигнувши очи на ученике своје говораше: благо вама који сте сиромашни духом; јер је ваше царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Благо вама који сте гладни сад; јер ћете се наситити. Благо вама који плачете сад; јер ћете се насмијати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Благо вама кад на вас људи омрзну и кад вас раставе и осрамоте, и разгласе име ваше као зло сина ради човјечијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Радујте се у онај дан и играјте, јер гле, ваша је велика плата на небу. Јер су тако чинили пророцима оцеви њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Али тешко вама богати; јер сте већ примили утјеху своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Тешко вама сити сад; јер ћете огладњети. Тешко вама који се смијете сад; јер ћете заплакати и заридати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Тешко вама кад стану сви добро говорити за вама; јер су тако чинили и лажнијем пророцима оцеви њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Али вама кажем који слушате: љубите непријатеље своје, добро чините онима који на вас мрзе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'Благосиљајте оне који вас куну, и молите се Богу за оне који вас вријеђају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Који те удари по образу, окрени му и други; и који хоће да ти узме кабаницу, подај му и кошуљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'А свакоме који иште у тебе, подај; и који твоје узме, не ишти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'И како хоћете да чине вама људи чините и ви њима онако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'И ако љубите оне који вас љубе, каква вам је хвала? Јер и грјешници љубе оне који њих љубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'И ако чините добро онима који вама добро чине, каква вам је хвала? Јер и грјешници чине тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'И ако дајете у зајам онима од којијех се надате да ћете узети, каква вам је хвала? Јер и грјешници грјешницима дају у зајам да узму опет онолико.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Али љубите непријатеље своје, и чините добро, и дајите у зајам не надајући се ничему; и биће вам велика плата, и бићете синови највишега, јер је он благ и неблагодарнима и злима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Будите дакле милостиви као и отац ваш што је милостив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'И не судите, и неће вам судити; и не осуђујте, и нећете бити осуђени; опраштајте, и опростиће вам се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Дајите, и даће вам се: мјеру добру и набијену и стресену и преопуну даће вам у наручје ваше. Јер каквом мјером дајете онаком ће вам се вратити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'И каза им причу: може ли слијепац слијепца водити? Неће ли обадва пасти у јаму?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Нема ученика над учитеља својега, него и сасвијем кад се изучи, биће као и учитељ његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'А зашто видиш трун у оку брата својега, а брвна у својему оку не осјећаш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Или како можеш рећи брату својему: брате! стани да извадим трун који је у оку твојему, кад сам не видиш брвна у својему оку? Лицемјере! извади најприје брвно из ока својега, па ћеш онда видјети извадити трун из ока брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Јер нема дрвета добра да рађа зао род; нити дрвета зла да рађа добар род.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Јер се свако дрво по роду своме познаје: јер се смокве не беру с трња, нити се грожђе бере с купине,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Добар човјек из добре клијети срца својега износи добро, а зао човјек из зле клијети срца својега износи зло, јер уста његова говоре од сувишка срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'А што ме зовете: Господе! Господе! а не извршујете што вам говорим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Сваки који иде за мном и слуша ријечи моје и извршује их, казаћу вам какав је:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Он је као човјек који гради кућу, па ископа и удуби и удари темељ на камену; а кад дођоше воде, навали ријека на ону кућу и не може је покренути, јер јој је темељ на камену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'А који слуша и не извршује он је као човјек који начини кућу на земљи без темеља, на коју навали ријека и одмах је обори, и распаде се кућа она страшно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'А кад сврши све ријечи своје пред народом, дође у Капернаум.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'У капетана пак једнога бијаше слуга болестан на умору који му бјеше мио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'А кад чу за Исуса, посла к њему старјешине Јудејске молећи га да би дошао да му исцијели слугу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'А они дошавши к Исусу мољаху га лијепо говорећи: достојан је да му то учиниш;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'Јер љуби народ наш, и начини нам зборницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'А Исус иђаше с њима. И кад већ бијаху близу куће, посла капетан к њему пријатеље говорећи му: Господе! не труди се, јер нијесам достојан да уђеш под моју стреху;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Зато и не држах себе достојна да ти дођем, него само реци ријеч, и оздравиће слуга мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Јер и ја сам човјек под власти, и имам под собом војнике, па речем једноме: иди, и иде; и другоме: дођи, и дође; и слузи својему: учини то, и учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'А кад то чу Исус, зачуди му се, и окренувши се народу који иђаше за њим рече: кажем вам: ни у Израиљу толике вјере не нађох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'И вративши се послани нађоше болеснога слугу здрава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'И потом иђаше у град који се зови Наин, и с њим иђаху многи ученици његови и мноштво народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Кад се приближише к вратима градскијем, и гле, изношаху мртваца, јединца сина матере његове, и она бјеше удовица и народа из града много иђаше с њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'И видјевши је Господ сажали му се за њом, и рече јој: не плачи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'И приступивши прихвати за сандук; а носиоци стадоше, и рече: момче! теби говорим, устани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'И сједе мртвац и стаде говорити; и даде га матери његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'А страх обузе све, и хваљаху Бога говорећи: велики пророк изиђе међу нама, и Бог походи народ свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'И отиде глас овај о њему по свој Јудеји и по свој околини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'И јавише Јовану ученици његови за све ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'И дозвавши Јован два од ученика својијех посла их к Исусу говорећи: јеси ли ти онај што ће доћи, или другога да чекамо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Дошавши пак људи к њему рекоше: Јован крститељ посла нас к теби говорећи: јеси ли ти онај што ће доћи, или другога да чекамо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'А у тај час исцијели многе од болести и од мука и од злијех духова, и многима слијепијем дарова вид.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'И одговарајући Исус рече им: идите и кажите Јовану што видјесте и чусте: слијепи прогледају, хроми ходе, губави чисте се, глухи чују, мртви устају, сиромашнима проповиједа се јеванђеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'И благо ономе који се не саблазни о мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'А кад отидоше ученици Јованови, поче народу говорити за Јована: шта сте изишли у пустињи да видите? Трску, коју љуља вјетар?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Шта сте дакле изишли да видите? Човјека у меке хаљине обучена? Ето, који господске хаљине носе и у сластима живе по царскијем су дворовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Шта сте дакле изишли да видите? Пророка? Да, ја вам кажем, и више од пророка;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Јер је ово онај за кога је писано: ето ја шаљем анђела својега пред лицем твојијем који ће приправити пут твој пред тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Јер вам кажем: ниједан између рођенијех од жена није већи пророк од Јована крститеља; а најмањи у царству Божијему већи је од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'И сви људи који слушаху и цариници оправдаше Бога, и крстише се крштењем Јовановијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'А фарисеји и књижевници одбацише свјет Божиј за њих, и не хтјеше да их он крсти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'А Господ рече: какви ћу казати да су људи овога рода? И какви су?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Они су као дјеца која сједе по улицама и дозивају једно друго и говоре: свирасмо вам, и не играсте, жалисмо вам се, и не плакасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Јер дође Јован крститељ који ни једе хљеба ни пије вина, а ви кажете: ђаво је у њему;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Дође син човјечиј који и једе и пије, а ви кажете: гле човјека изјелице и пијанице, друга цариницима и грјешницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'И оправдаше премудрост сва дјеца њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Мољаше га пак један од фарисеја да би обједовао у њега; и ушавши у кућу фарисејеву сједе за трпезу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'И гле, жена у граду која бјеше грјешница дознавши да је Исус за трпезом у кући фарисејевој, донесе скленицу мира;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'И ставши састраг код ногу његовијех плакаше, и стаде прати ноге његове сузама, и косом од своје главе отираше, и цјеливаше ноге његове, и мазаше миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'А кад видје фарисеј који га је дозвао, рече у себи говорећи: да је он пророк, знао би ко и каква га се жена дотиче: јер је грјешница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'И одговарајући Исус рече му: Симоне! имам ти нешто казати. А он рече: учитељу! кажи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'А Исус рече: двојица бијаху дужни једноме дужнику, један бјеше дужан пет стотина динара а други педесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'А кад они не имадоше да му врате, поклони обојици. Кажи који ће га од њих двојице већма љубити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'А Симон одговарајући рече: мислим онај коме највише поклони. А он му рече: право си судио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'И окренувши се к жени рече Симону: видиш ли ову жену? Ја уђох у твоју кућу, ни воде ми на ноге нијеси дао; а она сузама обли ми ноге, и косом од главе своје отр.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Цјелива ми нијеси дао; а она откако уђох не преста цјеливати ми ногу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Уљем нијеси помазао главе моје; а она миром помаза ми ноге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Зато кажем ти: опраштају јој се гријеси многи, јер је велику љубав имала; а коме се мало опрашта има малу љубав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'А њој рече: опраштају ти се гријеси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'И стадоше у себи говорити они што сјеђаху с њим за трпезом: ко је овај што и гријехе опрашта?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'А жени рече: вјера твоја поможе ти; иди с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Послије тога иђаше он по градовима и по селима учећи и проповиједајући јеванђеље о царству Божијему, и дванаесторица с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'И неке жене које бијаху исцијељене од злијех духова и болести: Марија, која се зваше Магдалина, из које седам ђавола изиђе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'И Јована, жена Хузе пристава Иродова, и Сусана, и друге многе које служаху њему имањем својијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'А кад се сабра народа много, и из свију градова долажаху к њему, каза у причи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Изиђе сијач да сије сјеме своје; и кад сијаше, једно паде крај пута, и погази се, и птице небеске позобаше га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'А друго паде на камен, и изникавши осуши се, јер немаше влаге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'И друго паде у трње, и узрасте трње, и удави га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'А друго паде на земљу добру, и изникавши донесе род сто пута онолико. Говорећи ово повика: ко има уши да чује нека чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'А ученици његови питаху га говорећи: шта значи прича ова?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'А он рече: вама је дано да знате тајне царства Божијега; а осталима у причама, да гледајући не виде, и чујући не разумију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'А прича ова значи: сјеме је ријеч Божија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'А које је крај пута то су они који слушају, али потом долази ђаво, и узима ријеч из срца њиховога, да не вјерују и да се не спасу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'А које је на камену то су они који кад чују с радости примају ријеч; и ови коријена немају који за неко вријеме вјерују, а кад дође вријеме кушања отпадну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'А које у трње паде то су они који слушају, и отишавши од бриге и богатства и сласти овога живота загуше се, и род не сазри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'А које је на доброј земљи то су они који ријеч слушају, и у доброме и чистом срцу држе, и род доносе у трпљењу. Ово говорећи повика: ко има уши да чује нека чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Нико пак свијеће не поклапа судом кад је запали, нити меће под одар, него је метне на свијећњак да виде свјетлост који улазе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Јер нема ништа тајно што неће бити јавно, ни сакривено што се неће дознати и на видјело изићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Гледајте дакле како слушате; јер ко има, даће му се, а ко нема, узеће се од њега и оно што мисли да има.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Дођоше пак к њему мати и браћа његова, и не могаху од народа да говоре с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'И јавише му говорећи: мати твоја и браћа твоја стоје напољу, хоће да те виде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'А он одговарајући рече им: мати моја и браћа моја они су који слушају ријеч Божију и извршују је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'И догоди се у један дан он уљезе с ученицима својијем у лађу, и рече им: да пријеђемо на ону страну језера. И пођоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'А кад иђаху они он заспа. И подиже се олуја на језеру, и топљаху се, и бијаху у великој невољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'И приступивши пробудише га говорећи: учитељу! учитељу! изгибосмо. А он устаде, и запријети вјетру и валовима; и престадоше и поста тишина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'А њима рече: гдје је вјера ваша? А они се поплашише, и чуђаху се говорећи један другоме: ко је овај што и вјетровима и води заповиједа, и слушају га?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'И дођоше у околину Гадаринску која је према Галилеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'А кад изиђе он на земљу, срете га један човјек из града у коме бијаху ђаволи од много година, и у хаљине не облачаше се, и не живљаше у кући, него у гробовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'А кад видје Исуса, повика и припаде к њему и рече здраво: што је теби до мене, Исусе, сине Бога највишега? Молим те, не мучи ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Јер Исус заповједи духу нечистоме да изиђе из човјека: јер га мучаше одавно, и метаху га у вериге и у пута да га чувају, и искида свезе, и тјераше га ђаво по пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'А Исус га запита говорећи: како ти је име? А он рече: легеон; јер многи ђаволи бијаху ушли у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'И мољаху га да им не заповједи да иду у бездан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'А ондје пасијаше по гори велики крд свиња, и мољаху га да им допусти да у њих уђу. И допусти им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Тада изиђоше ђаволи из човјека и уђоше у свиње; и навали крд с бријега у језеро, и утопи се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'А кад видјеше свињари што би, побјегоше и јавише у граду и по селима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'И изиђоше људи да виде шта је било, и дођоше к Исусу, и нађоше човјека из кога ђаволи бијаху изишли а он сједи обучен и паметан код ногу Исусовијех; и уплашише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'А они што су видјели казаше им како се исцијели бијесни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'И моли га сав народ из околине Гадаринске да иде од њих; јер се бијаху врло уплашили. А он уљезе у лађу и отиде натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Човјек пак из кога изиђоше ђаволи мољаше да би с њим био; али га Исус отпусти говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Врати се кући својој, и казуј шта ти учини Бог. И отиде проповиједајући по свему граду шта му Исус учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'А кад се врати Исус, срете га народ, јер га сви очекиваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'И гле, дође човјек по имену Јаир, који бјеше старјешина у зборници, и паде пред ноге Исусове, и мољаше га да уђе у кућу његову;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'Јер у њега бјеше јединица кћи од дванаест година, и она умираше. А кад иђаше Исус, туркаше га народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'И бјеше једна болесна жена од течења крви дванаест година, која је све своје имање потрошила на љекаре и ниједан је није могао излијечити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'И приступивши састраг дотаче се скута од хаљине његове, и одмах стаде течење крви њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'И рече Исус: ко је то што се дотаче мене? А кад се сви одговараху, рече Петар и који бијаху с њим: учитељу! народ те опколио и турка те, а ти кажеш: ко је то што се дотаче мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'А Исус рече: неко се дотаче мене; јер ја осјетих силу која изиђе из мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'А кад видје жена да се није сакрила, приступи дрхћући, и паде пред њим, и каза му пред свијем народом зашто га се дотаче и како одмах оздрави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'А он јој рече: не бој се кћери! вјера твоја поможе ти; иди с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Док он још говораше дође неко од куће старјешине зборничкога говорећи му: умрије кћи твоја, не труди учитеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'А кад чу Исус, одговори му говорећи: не бој се, само вјеруј, и оживљеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'А кад дође у кућу, не даде ниједноме ући осим Петра и Јована и Јакова, и дјевојчина оца и матере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'А сви плакаху и јаукаху за њом; а он рече: не плачите, није умрла него спава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'И потсмијеваху му се знајући да је умрла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'А он изагнавши све узе је за руку, и зовну говорећи: дјевојко! устани!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'И поврати се дух њезин, и устаде одмах; и заповједи да јој даду нека једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'И дивише се родитељи њезини. А он им заповједи да никоме не казују шта је било.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Сазвавши пак дванаесторицу даде им силу и власт над свијем ђаволима, и да исцијељују од болести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'И посла их да проповиједају царство Божије, и да исцјељују болеснике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'И рече им: ништа не узимајте на пут, ни штапа ни торбе ни хљеба ни новаца, нити по двије хаљине да имате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'У коју кућу уђете ондје будите и оданде полазите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'И гдје вас не приме излазећи из града онога отресите и прах с ногу својијех, за свједочанство на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'А кад изиђоше, иђаху по селима проповиједајући јеванђеље и исцјељујући свуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'А кад чу Ирод четверовласник шта он чини, не могаше се начудити, јер неки говораху да је Јован устао из мртвијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'А једни да се Илија појавио, а једни да је устао који од старијех пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'И рече Ирод: Јована ја посјекох; али ко је то о коме ја таква чудеса слушам? И жељаше га видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'И вративши се апостоли казаше му шта су починили. И узевши их отиде насамо у пустињу код града који се зваше Витсаида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'А народ разумјевши пође за њим и примивши их говораше им о царству Божијему и исцјељиваше који требаху исцјељивања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'А дан стаде нагињати. Тада приступише дванаесторица и рекоше му: отпусти народ, нека иду на конак у околна села и паланке, и нек нађу јела, јер смо овдје у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'А он им рече: подајте им ви нека једу. А они рекоше: у нас нема више од пет хљебова и двије рибе; већ ако да идемо ми да купимо на све ове људе јела?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Јер бијаше људи око пет хиљада. Али он рече ученицима својијем: посадите их на гомиле по педесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'И учинише тако, и посадише их све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'А он узе онијех пет хљебова и обје рибе, и погледавши на небо благослови их и преломи, и даваше ученицима да раздаду народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'И једоше и наситише се сви, и накупише комада дванаест котарица што им претече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'И кад се једанпут мољаше Богу насамо, с њим бијаху ученици, и запита их говорећи: ко говоре људи да сам ја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'А они одговарајући рекоше: једни веле да си Јован крститељ, а други да си Илија; а други да је који устао од старијех пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'А он им рече: а ви шта мислите ко сам ја? А Петар одговарајући рече: Христос Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'А он им запријети и заповједи да никоме не казују тога');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'Говорећи да сину човјечијему треба много пострадати, и да ће га старјешине и главари свештенички и књижевници окривити, и да ће га убити, и трећи дан да ће устати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'А свима говораше: ко хоће да иде за мном нека се одрече себе и узме крст свој и иде за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Јер ко хоће душу своју да сачува, изгубиће је; а ко изгуби душу своју мене ради онај ће је сачувати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Јер какву ће корист имати човјек ако сав свијет придобије а себе изгуби или себи науди?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Јер ко се постиди мене и мојијех ријечи њега ће се син човјечиј постидјети кад дође у слави својој и очиној и светијех анђела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'А заиста вам кажем: имају неки међу овима што стоје овдје који неће окусити смрти док не виде царства Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'А кад прође осам дана послије онијех ријечи, узе Петра и Јована и Јакова и изиђе на гору да се помоли Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'И кад се мољаше постаде лице његово друкчије, и одијело његово бијело и сјајно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'И гле, два човјека говораху с њим, који бијаху Мојсије и Илија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Показаше се у слави, и говораху о изласку његову који му је требало свршити у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'А Петар и који бијаху с њим бијаху заспали; али пробудивши се видјеше славу његову и два човјека који с њим стајаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'И кад се одвојише од њега рече Петар Исусу: учитељу! добро нам је овдје бити; и да начинимо три сјенице: једну теби, и једну Мојсију, и једну Илији: не знајући шта говораше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'А док он то говораше дође облак и заклони их; и уплашише се кад зађоше у облак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'И чу се глас из облака говорећи: ово је син мој љубазни, њега послушајте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'И кад се чујаше глас нађе се Исус сам. И они умучаше, и ником не јавише ништа у оне дане од онога шта видјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'А догоди се други дан кад сиђоше с горе срете га мноштво народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'И гле, човјек из народа повика говорећи: учитељу! молим ти се, погледај на сина мојега, јер ми је јединац:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'И гле, хвата га дух, и уједанпут виче, и ломи га с пјеном, и једва отиде од њега кад га изломи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'И молих ученике твоје да га истјерају, па не могоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'И одговарајући Исус рече: о роде невјерни и покварени! докле ћу бити с вама и трпљети вас? Доведи ми сина својега амо:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'А док још иђаше к њему обори га ђаво, и стаде га ломити. А Исус запријети духу нечистоме, и исцијели момче, и даде га оцу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'И сви се дивљаху величини Божијој. А кад се сви чуђаху свему што чињаше Исус, рече ученицима својијем:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Метните ви у уши своје ове ријечи: јер син човјечиј треба да се преда у руке човјечије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'А они не разумјеше ријечи ове; јер бјеше сакривена од њих да је не могоше разумјети; и бојаху се да га запитају за ову ријеч.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'А уђе мисао у њих ко би био највећи међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'А Исус знајући помисли срца њиховијех узе дијете и метну га преда се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'И рече им: који прими ово дијете у име моје, мене прима; и који мене прима, прима онога који ме је послао; јер који је најмањи међу вама он је велики.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'А Јован одговарајући рече: учитељу! видјесмо једнога гдје именом твојијем изгони ђаволе, и забранисмо му, јер не иде с нама за тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'И рече му Исус: не браните; јер ко није против вас с вама је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'А кад се навршише дани узећа његова, он намјери да иде право у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'И посла гласнике пред лицем својијем; и они отидоше и дођоше у село Самарјанско да му уготове гдје ће ноћити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'И не примише га; јер видјеше да иде у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'А кад видјеше ученици његови Јаков и Јован, рекоше: Господе! хоћеш ли да речемо да огањ сиђе с неба и да их истријеби као и Илија што учини?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'А он окренувши се запријети им и рече: не знате каквога сте ви духа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Јер син човјечиј није дошао да погуби душе човјечије него да сачува. И отидоше у друго село.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'А кад иђаху путем рече му неко: Господе! ја идем за тобом куд год ти пођеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'И рече му Исус: лисице имају јаме и птице небеске гнијезда: а син човјечиј нема гдје заклонити главе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'А другоме рече: хајде за мном. А он рече: Господе! допусти ми да идем најприје да укопам оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'А Исус рече му: остави нека мртви укопавају своје мртваце; а ти хајде те јављај царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'А други рече: Господе! ја идем за тобом; али допусти ми најприје да идем да се опростим с домашњима својијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'А Исус рече му: ниједан није приправан за царство Божије који метне руку своју на плуг па се обзире натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'А потом изабра Господ и другијех седамдесеторицу, и посла их по два и два пред лицем својијем у сваки град и у мјесто куда шћаше сам доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'А рече им: жетва је дакле велика а посленика мало; него се молите господару од жетве да изведе посленике на жетву своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Идите; ето ја вас шаљем као јагањце међу вукове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Не носите кесе ни торбе ни обуће, и никога не поздрављајте на путу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'У коју год кућу уђете најприје говорите: мир кући овој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'И ако дакле буде ондје син мира, остаће на њему мир ваш; ако ли не буде, вратиће се к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'А у оној кући будите, и једите и пијте што у њих има; јер је посленик достојан своје плате; не прелазите из куће у кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'И у који год град дођете и приме вас, једите што се донесе пред вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'И исцјељујте болеснике који су у њему, и говорите им: приближи се к вама царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'И у који год град дођете и не приме вас, изишавши на улице његове реците:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'И прах од града вашега који је прионуо за нас отресамо вам; али ово знајте да се приближи к вама царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Кажем вам да ће Содому бити лакше у онај дан неголи граду ономе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Тешко теби, Хоразине! тешко теби, Витсаидо! Јер да су у Тиру и у Сидону била чудеса што су била у вама, давно би се у врећи и у пепелу сједећи покајали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Али Тиру и Сидону биће лакше на суду него вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'И ти, Капернауме! који си се до небеса подигао до пакла ћеш пропасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Ко вас слуша мене слуша; и ко се вас одриче мене се одриче; а ко се мене одриче, одриче се онога који је мене послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Вратише се пак седамдесеторица с радости говорећи: Господе! и ђаволи нам се покоравају у име твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'А он им рече: ја видјех сотону гдје спаде с неба као муња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Ево вам дајем власт да стајете на змије и на скорпије и на сваку силу непријатељску, и ништа вам неће наудити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Али се томе не радујте што вам се духови покоравају, него се радујте што су ваша имена написана на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'У тај час обрадова се Исус у духу и рече: хвалим те, оче, Господе неба и земље, што си ово сакрио од премудријех и разумнијех а казао си простима. Да, оче, јер је тако била воља твоја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'И окренувши се к ученицима рече: све је мени предао отац мој, и нико не зна ко је син осим оца, ни ко је отац осим сина, и ако син хоће коме казати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'И окренувши се к ученицима насамо рече: благо очима које виде што ви видите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Јер вам кажем да су многи пророци и цареви жељели видјети што ви видите, и не видјеше; и чути што ви чујете, и не чуше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'И гле, устаде један законик и кушајући га рече: учитељу! шта ћу чинити да добијем живот вјечни?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'А он му рече: шта је написано у закону? како читаш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'А он одговарајући рече: љуби Господа Бога својега свијем срцем својијем, и свом душом својом, и свом снагом својом, и свом мисли својом, и ближњега својега као самога себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Рече му пак: право си одговорио; то чини и бићеш жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'А он шћадијаше да се оправда, па рече Исусу: а ко је ближњи мој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'А Исус одговарајући рече: један човјек силажаше из Јерусалима у Јерихон, па га ухватише хајдуци, који га свукоше и изранише, па отидоше, оставивши га пола мртва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'А изненада силажаше онијем путем некакав свештеник, и видјевши га прође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'А тако и Левит кад је био на ономе мјесту, приступи, и видјевши га прође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'А Самарјанин некакав пролазећи дође над њега, и видјевши га сажали му се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'И приступивши зави му ране и зали уљем и вином; и посадивши га на своје кљусе доведе у гостионицу, и устаде око њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'И сјутрадан полазећи извади два гроша те даде крчмару, и рече му: гледај га, и што више потрошиш ја ћу ти платити кад се вратим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Шта мислиш дакле, који је од оне тројице био ближњи ономе што су га били ухватили хајдуци?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'А он рече: онај који се смиловао на њега. А Исус му рече: иди, и ти чини тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'А кад иђаху путем и он уђе у једно село, а жена нека, по имену Марта, прими га у своју кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'И у ње бјеше сестра, по имену Марија, која и сједе код ногу Исусовијех и слушаше бесједу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'А Марта се бјеше забунила како ће га дочекати, и прикучивши се рече: Господе! зар ти не мариш што ме сестра моја остави саму да служим? реци јој дакле да ми поможе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'А Исус одговарајући рече јој: Марта! Марта! бринеш се и трудиш за много,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'А само је једно потребно. Али је Марија добри дијел изабрала, који се неће узети од ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'И кад се мољаше Богу на једном мјесту па преста, рече му неки од ученика његовијех: Господе! научи нас молити се Богу, као што и Јован научи своје ученике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'А он им рече: кад се молите Богу говорите: оче наш који си на небесима, да се свети име твоје; да дође царство твоје; да буде воља твоја и на земљи као на небу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Хљеб наш потребни даји нам сваки дан;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'И опрости нам гријехе наше, јер и ми опраштамо свакоме дужнику својему; и не наведи нас у напаст; него нас избави ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'И рече им: који од вас има пријатеља, и отиде му у поноћи и рече му: пријатељу! дај ми три хљеба у зајам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Јер ми дође пријатељ с пута, и немам му шта поставити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'А он изнутра одговарајући да рече: не узнемируј ме; већ су врата затворена и дјеца су моја са мном у постељи, и не могу устати да ти дам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'И кажем вам: ако и не устане да му да зато што му је пријатељ, али за његово безобразно искање устаће и даће му колико треба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'И ја вама кажем: иштите и даће вам се: тражите и наћи ћете; куцајте и отвориће вам се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Јер сваки који иште, прима; и који тражи, налази; и који куца, отвара му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Који је међу вама отац у кога ако син заиште хљеба да му да камен? Или ако заиште рибе да му да мјесто рибе змију?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Или ако заиште јаје да му да скорпију?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Кад дакле ви, зли будући, умијете добре даре давати дјеци својој, колико ће више отац небески дати Духа светога онима који ишту у њега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'И једном изгна ђавола који бјеше нијем; кад ђаво изиђе проговори нијеми; и дивише се људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'А неки од њих рекоше: помоћу Веелзевула кнеза ђаволскога изгони ђаволе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'А други кушајући га искаху од њега знак с неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'А он знајући помисли њихове рече им: свако царство које се раздијели само по себи, опустјеће, и дом који се раздијели сам по себи, пропашће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Тако и сотона ако се раздијели сам по себи, како ће остати његово царство? као што кажете да помоћу Веелзевула изгоним ђаволе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Ако ли ја помоћу Веелзевула изгоним ђаволе, синови ваши чијом помоћу изгоне? Зато ће вам они бити судије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'А ако ли ја прстом Божијим изгоним ђаволе, дакле је дошло к вама царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Кад се јаки наоружа и чува свој двор, имање је његово на миру;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'А кад дође јачи од њега и надвлада га, узме све оружје његово у које се уздао, и раздијели што отме од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Који није са мном, против мене је; и који са мном не сабира, просипа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Кад нечисти дух изиђе из човјека, иде кроз безводна мјеста тражећи покоја, и не нашавши рече: да се вратим у дом свој откуда сам изишао;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'И дошавши нађе пометен и украшен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Тада отиде и узме седам другијех духова горијех од себе, и ушавши живе ондје; и буде потоње човјеку ономе горе од првога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'А кад то говораше, подиже глас једна жена из народа и рече му: благо утроби која те је носила, и сисама које си сао!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'А он рече: благо и онима који слушају ријеч Божију, и држе је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'А народу који се скупљаше стаде говорити: род је овај зао; иште знак, и неће му се дати знак осим знака Јоне пророка;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Јер како што Јона би знак Ниневљанима, тако ће и син човјечиј бити роду овоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Царица јужна изићи ће на суд с људима рода овога, и осудиће их; јер она дође с краја земље да слуша премудрост Соломунову: а гле, овдје је већи од Соломуна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Ниневљани изићи ће на суд с родом овијем, и осудиће га; јер се покајаше поучењем Јонинијем: а гле, овдје је већи од Јоне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Нико не меће запаљене свијеће на сакривено мјесто, нити под суд, него на свијећњак да виде свјетлост који улазе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Свијећа је тијелу око. Ако дакле око твоје буде здраво, све ће тијело твоје бити свијетло; ако ли око твоје буде кварно, и тијело је твоје тамно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Гледај дакле да видјело које је у теби не буде тама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Јер ако је све тијело твоје свијетло да нема никаквога уда тамна, биће свијетло као кад те свијећа обасјава свјетлошћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'А кад говораше, мољаше га некакав фарисеј да обједује у њега. А он ушавши сједе за трпезу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'А фарисеј се зачуди кад видје да се најприје не уми прије обједа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'А Господ рече му: сад ви фарисеји споља чистите чашу и здјелу, а изнутра вам је пуно грабежа и злобе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Безумни! није ли онај начинио и изнутра који је споља начинио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Али дајите милостињу од онога што је унутра; и гле, све ће вам бити чисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Али тешко вама фарисејима што дајете десетак од метвице и од руте и од свакога поврћа, а пролазите правду и љубав Божију: ово је требало чинити, и оно не остављати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Тешко вама фарисејима што тражите зачеља по зборницама и да вам се клања по улицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Тешко вама књижевници и фарисеји, лицемјери, што сте као сакривени гробови по којима људи иду и не знаду их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'А неки од законика одговарајући рече: учитељу! говорећи то и нас срамотиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'А он рече: тешко и вама законицима што товарите на људе бремена претешка за ношење, а ви једнијем прстом својијем нећете да их прихватите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Тешко вама што зидате гробове пророцима, а ваши су их оцеви побили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Ви дакле свједочите и одобравате дјела отаца својијех; јер их они побише, а ви им гробове зидате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Зато и премудрост Божија рече: послаћу им пророке и апостоле, и од њих ће једне побити, а друге протјерати;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'Да се иште од рода овога крв свију пророка која је проливена од постања свијета,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'Од крви Авељеве тја до крви Заријне, који погибе међу олтаром и црквом. Да, кажем вам, искаће се од рода овога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Тешко вама законици што узесте кључ од знања: сами не уђосте, а који шћадијаху да уђу, забранисте им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'А кад им он ово говораше, почеше књижевници и фарисеји врло наваљивати к њему и многијем питањем забуњивати га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'Вребајући и пазећи на њега не би ли што уловили из уста његовијех да га окриве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Кад се на њих скупише хиљаде народа да стадоше газити један другога, онда поче најприје говорити ученицима својијем: чувајте се квасца фарисејскога, који је лицемјерје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Јер ништа није сакривено што се неће открити, ни тајно што се неће дознати;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Јер што у мраку рекосте, чуће се на видјелу; и што на ухо шаптасте у клијетима, проповиједаће се на крововима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Али вам кажем, пријатељима својијем: не бојте се од онијех који убијају тијело и потом не могу ништа више учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Него ћу вам казати кога да се бојите: бојте се онога који има власт пошто убије бацити у пакао; да, кажем вам, онога се бојте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Не продаје ли се пет врабаца за два динара? и ниједан од њих није заборављен пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'А у вас је и коса на глави избројена. Не бојте се дакле; ви сте бољи од много врабаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Него вам кажем: који год призна мене пред људима признаће и син човјечиј њега пред анђелима Божијим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'А који се одрече мене пред људима њега ће се одрећи пред анђелима Божијим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'И сваки који рече ријеч на сина човјечијега опростиће му се, а који хули на светога Духа неће му се опростити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'А кад вас доведу у зборнице и на судове и пред поглаваре, не брините се како ћете или шта одговорити, или шта ћете казати;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Јер ће вас свети Дух научити у онај час шта треба рећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Рече му пак неки из народа: учитељу! реци брату мојему да подијели са мном достојање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'А он му рече: човјече! ко је мене поставио судијом или кметом над вама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'А њима рече: гледајте и чувајте се од лакомства; јер нико не живи онијем што је сувише богат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Каза им пак причу говорећи: у једнога богатог човјека роди њива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'И мишљаше у себи говорећи: шта ћу чинити? немам у што сабрати своје љетине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'И рече: ево ово ћу чинити: покварићу житнице своје и начинићу веће; и ондје ћу сабрати сва своја жита и добро своје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'И казаћу души својој: душо! имаш много имање на много година; почивај, једи, пиј, весели се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'А Бог њему рече: безумниче! ову ноћ узеће душу твоју од тебе; а што си приправио чије ће бити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Тако бива ономе који себи тече благо а не богати се у Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'А ученицима својијем рече: зато вам кажем: не брините се душом својом шта ћете јести; ни тијелом у што ћете се обући:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Душа је претежнија од јела и тијело од одијела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Погледајте гавране како не сију, ни жању, који немају подрума ни житница, и Бог их храни: а колико сте ви претежнији од птица?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'А ко од вас бринући се може примакнути расту својему лакат један?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'А кад ни најмање што не можете, зашто се бринете за остало?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Погледајте љиљане како расту: не труде се, нити преду; али ја вам кажем да ни Соломун у свој слави својој не обуче се као један од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'А кад траву по пољу, која данас јест а сјутра се у пећ баца, Бог тако одијева, акамоли вас, маловјерни!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'И ви не иштите шта ћете јести или шта ћете пити, и не брините се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Јер ово све ишту и незнабошци овога свијета; а отац ваш зна да вама треба ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Него иштите царства Божијега, и ово ће вам се све додати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Не бој се мало стадо! јер би воља вашега оца да вам да царство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Продајите што имате и дајите милостињу; начините себи торбе које неће оветшати, хазну која се никад неће испразнити, на небесима, гдје се лупеж не прикучује нити мољац једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Јер гдје је ваше благо ондје ће бити и срце ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Нека буду ваша бедра запрегнута и свијеће запаљене;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'И ви као људи који чекају господара својега кад се врати са свадбе да му одмах отворе како дође и куцне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Благо онијем слугама које нађе господар кад дође а они страже. Заиста вам кажем да ће се запрегнути, и посадиће их, и приступиће те ће им служити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'И ако дође у другу стражу, и у трећу стражу дође, и нађе их тако, благо онијем слугама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Али ово знајте: кад би знао домаћин у који ће час доћи лупеж, чувао би и не би дао поткопати куће своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'И ви дакле будите готови: јер у који час не мислите доћи ће син човјечиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'А Петар му рече: Господе! говориш ли нама ову причу или свима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'А Господ рече: ко је дакле тај вјерни и мудри пристав којега постави господар над чељади својом да им даје храну на оброк?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Благо томе слузи којега дошавши господар његов нађе да извршује тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Заиста вам кажем: над свијем својијем имањем поставиће га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Ако ли рече слуга у срцу својему: неће мој господар још задуго доћи; и стане бити слуге и слушкиње, и јести и пити, и опијати се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'Доћи ће господар тога слуге у дан кад се не нада, и у час кад не мисли, и расјећи ће га, и дијел његов метнуће с невјернима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'А онај слуга који зна вољу господара својега, и није се приправио, нити учинио по вољи његовој, биће врло бијен;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'А који не зна па заслужи бој, биће мало бијен. Коме је год много дано много ће се искати од њега; а коме предаше највише највише ће искати од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Ја сам дошао да бацим огањ на земљу; и како би ми се хтјело да се већ запалио!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Али се мени ваља крстити крштењем, и како ми је тешко док се не сврши!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Мислите ли да сам ја дошао да дам мир на земљу? Не, кажем вам, него раздор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Јер ће отселе пет у једној кући бити раздијељени, устаће три на два, и два на три.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Устаће отац на сина и син на оца; мати на кћер и кћи на матер; свекрва на снаху своју и снаха на свекрву своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'А народу говораше: кад видите облак гдје се диже од запада одмах кажете: биће дажд; и бива тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'И кад видите југ гдје дува кажете: биће врућина; и бива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Лицемјери! лице неба и земље умијете познавати, а времена овога како не познајете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Зашто пак и сами од себе не судите праведно?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Јер кад идеш са својијем супарником кнезу, гледај не би ли се на путу с њим поравнао да те не притегне судији, и судија да те не преда слузи, и слуга да те не баци у тамницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Кажем ти: нећеш оданде изићи док не даш и пошљедњега динара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'У то вријеме пак дођоше неки и казаше за Галилејце којијех крв помијеша Пилат са жртвама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'И одговарајући Исус рече им: мислите ли да су ти Галилејци били најгрјешнији од свију Галилејаца, јер тако пострадаше?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Не, кажем вам, него ако се не покајете, сви ћете тако изгинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Или они осамнаест што на њих паде кула Силоамска и поби их, мислите ли да су они најкривљи били од свију Јерусалимљана?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Не, кажем вам, него ако се не покајете, сви ћете тако изгинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Каза им пак ову причу: један човјек имадијаше смокву усађену у своме винограду, и дође да тражи рода на њој, и не нађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Онда рече виноградару: ево трећа година како долазим и тражим рода на овој смокви, и не налазим; посијеци је дакле, зашто земљи да смета?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'А он одговарајући рече му: господару! остави је и за ову годину док окопам око ње и обаспем гнојем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'Па да ако роди: ако ли не, посјећи ћеш је на годину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'А кад учаше у једној зборници у суботу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'И гле, бјеше ондје жена болесна од духа осамнаест година, и бјеше згрчена, и не могаше се исправити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'А кад је видје, дозва је Исус и рече јој: жено! опроштена си од болести своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'И метну на њу руке, и одмах се исправи и хваљаше Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'А старјешина од зборнице срђаше се што је Исус исцијели у суботу, и одговарајући рече народу: шест је дана у које треба радити, у оне дакле долазите те се лијечите, а не у дан суботни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'А Господ му одговори и рече: лицемјере! сваки од вас у суботу не одрешује ли својега вола или магарца од јасала, и не води да напоји?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'А ову кћер Авраамову коју свеза сотона ево осамнаеста година, не требаше ли је одријешити из ове свезе у дан суботни?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'И кад он ово говораше стиђаху се сви који му се противљаху; и сав народ радоваше се за сва његова славна дјела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'А он им рече: какво је царство Божије? и како ћу казати да је?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Оно је као зрно горушичино, које узевши човјек баци у врт свој, и узрасте и поста дрво велико, и птице небеске уселише се у гране његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Опет рече: какво ћу казати да је царство Божије?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Оно је као квасац који узевши жена метну у три копање брашна, док не ускисе све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'И пролажаше по градовима и селима учећи и путујући у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Рече му пак неко: Господе! је ли мало онијех који ће бити спасени? А он им рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Навалите да уђете на тијесна врата; јер вам кажем: многи ће тражити да уђу и неће моћи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Кад устане домаћин и затвори врата, и станете напољу стајати и куцати у врата говорећи: Господе! Господе! отвори нам; и одговарајући рећи ће вам: не познајем вас откуда сте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Тада ћете стати говорити: ми једосмо пред тобом и писмо, и по улицама нашијем учио си.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'А он ће рећи: кажем вам: не познајем вас откуда сте; отступите од мене сви који неправду чините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Ондје ће бити плач и шкргут зуба, кад видите Авраама и Исака и Јакова и све пророке у царству Божијему, а себе напоље истјеране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'И доћи ће од истока и запада и сјевера и југа и сјешће за трпезу у царству Божијему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'И гле, има пошљедњијех који ће бити први, и има првијех који ће бити пошљедњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'У тај дан приступише неки од фарисеја говорећи му: изиђи и иди одавде, јер Ирод хоће да те убије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'И рече им: идите те кажите оној лисици: ево изгоним ђаволе и исцијељујем данас и сјутра, а трећи дан свршићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Али данас и сјутра и прекосјутра треба ми ићи; јер пророк не може погинути изван Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Јерусалиме, Јерусалиме, који убијаш пророке и засипаш камењем послане к себи! колико пута хтјех да скупим чеда твоја као кокош гнијездо своје под крила, и не хтјесте!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Ето ће вам се оставити кућа ваша пуста; а ја вам кажем: нећете мене видјети док не дође да речете: благословен који иде у име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'И догоди му се да дође у суботу у кућу једнога кнеза фарисејскога да једе хљеб; и они мотраху на њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'И гле, бјеше пред њим некакав човјек на коме бјеше дебела болест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'И одговарајући Исус рече законицима и фарисејима говорећи: је ли слободно у суботу исцјељивати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'А они оћутјеше. И дохвативши га се исцијели га и отпусти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'И одговарајући рече им: који од вас не би својега магарца или вола да му падне у бунар одмах извадио у дан суботни?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'И не могоше му одговорити на то.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'А гостима каза причу, кад опази како избираху зачеља, и рече им:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Кад те ко позове на свадбу, не сједај у зачеље, да не буде међу гостима ко старији од тебе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'И да не би дошао онај који је позвао тебе и њега, и рекао ти: подај мјесто овоме: и онда ћеш са стидом сјести на ниже мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Него кад те ко позове, дошавши сједи на пошљедње мјесто, да ти рече кад дође онај који те позва: пријатељу! помакни се више; тада ће теби бити част пред онима који сједе с тобом за трпезом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Јер сваки који се подиже, понизиће се; а који се понижује, подигнуће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'А и ономе што их је позвао рече: кад дајеш објед или вечеру, не зови пријатеља својијех, ни браће своје, ни рођака својијех, ни сусједа богатијех, да не би и они тебе кад позвали и вратили ти;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Него кад чиниш гозбу, зови сиромахе, кљасте, хроме, слијепе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'И благо ће ти бити што ти они не могу вратити; него ће ти се вратити о васкрсенију праведнијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'А кад чу то неки од онијех што сјеђаху с њим за трпезом рече му: благо ономе који једе хљеба у царству Божијему!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'А он му рече: један човјек зготови велику вечеру, и позва многе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'И кад би вријеме вечери, посла слугу својега да каже званима: хајдете, јер је већ све готово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'И почеше се изговарати сви редом; први му рече: купих њиву, и ваља ми ићи да је видим; молим те изговори ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'И други рече: купих пет јармова волова, и идем да их огледам; молим те, изговори ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'И трећи рече: ожених се, и зато не могу доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'И дошавши слуга тај каза ово господару своме. Тада се расрди домаћин и рече слузи своме: иди брзо на раскршћа и улице градске, и доведи амо сиромахе, и кљасте, и богаљасте, и слијепе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'И рече слуга: господару, учинио сам како си заповједио, и још мјеста има.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'И рече господар слузи: изиђи на путове и међу ограде, те натјерај да дођу да ми се напуни кућа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Јер вам кажем да ниједан од онијех званијех људи неће окусити моје вечере. Јер је много званијех, али је мало изабранијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Иђаше пак с њим мноштво народа, и обазревши се рече им:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Ако ко дође к мени а не мрзи на својега оца, и на матер, и на жену, и на дјецу, и на браћу, и на сестре и на саму душу своју, не може бити мој ученик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'И ко не носи крста својега и за мном не иде, не може бити мој ученик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'И који од вас кад хоће да зида кулу не сједе најприје и не прорачуни шта ће га стати, да види има ли да може довршити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Да не би, кад постави темељ и не узможе довршити, сви који гледају стали му се ругати');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'Говорећи: овај човјек поче зидати, и не може да доврши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Или који цар кад пође с војском да се побије с другијем царем не сједе најприје и не држи вијећу може ли с десет хиљада срести онога што иде на њега са двадесет хиљада?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Ако ли не може, а он пошље посленике док је овај још далеко и моли да се помире.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Тако дакле сваки од вас који се не одрече свега што има не може бити мој ученик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Со је добра, али ако со обљутави, чим ће се осолити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Нити је потребна у земљу ни у гној; него је проспу напоље. Ко има уши да чује нека чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'И приближаваху се к њему сви цариници и грјешници да га чују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'И викаху на њега фарисеји и књижевници говорећи: овај прима грјешнике и једе с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'А он им каза причу ову говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Који човјек од вас имајући сто оваца и изгубивши једну од њих не остави деведесет и девет у пустињи и не иде за изгубљеном док је не нађе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'И нашавши дигне је на раме своје радујући се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'И дошавши кући сазове пријатеље и сусједе говорећи им: радујте се са мном: ја нађох своју овцу изгубљену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Кажем вам да ће тако бити већа радост на небу за једнога грјешника који се каје, неголи за деведесет и девет праведника којима не треба покајање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Или која жена имајући десет динара, ако изгуби један динар, не запали свијеће, и не помете куће, и не тражи добро док не нађе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'И нашавши сазове другарице и сусједе говорећи: радујте се са мном: ја нађох динар изгубљени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Тако, кажем вам, бива радост пред анђелима Божијима за једнога грјешника који се каје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'И рече: један човјек имаше два сина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'И рече млађи од њих оцу: оче! дај ми дио имања што припада мени. И отац им подијели имање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'И потом до неколико дана покупи млађи син све своје, и отиде у даљну земљу; и онамо просу имање своје живјећи беспутно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'А кад потроши све, постаде велика глад у оној земљи, и он се нађе у невољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'И отишавши приби се код једнога човјека у оној земљи; и он га посла у поље своје да чува свиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'И жељаше напунити трбух свој рошчићима које свиње јеђаху, и нико му их не даваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'А кад дође к себи, рече: колико најамника у оца мојега имају хљеба и сувише, а ја умирем од глади!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Устаћу и идем оцу својему, па ћу му рећи: оче! сагријеших небу и теби,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'И већ нијесам достојан назвати се син твој: прими ме као једнога од својијех најамника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'И уставши отиде оцу својему. А кад је још подалеко био, угледа га отац његов, и сажали му се, и потрчавши загрли га и цјелива га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'А син му рече: оче, сагријеших небу и теби, и већ нијесам достојан назвати се син твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'А отац рече слугама својијем: изнесите најљепшу хаљину и обуците га, и подајте му прстен на руку и обућу на ноге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'И доведите теле угојено те закољите, да једемо и да се веселимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Јер овај мој син бјеше мртав, и оживље; и изгубљен бјеше, и нађе се. И стадоше се веселити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'А син његов старији бијаше у пољу, и долазећи кад се приближи кући чу пјевање и подвикивање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'И дозвавши једнога од слугу запита: шта је то?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'А он му рече: брат твој дође; и отац твој закла теле угојено, што га је здрава видио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'А он се расрди и не шћадијаше да уђе. Тада изиђе отац његов и мољаше га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'А он одговарајући рече оцу: ето те служим толико година, и никад не преступих твоје заповијести, па мени никад нијеси дао јарета да бих се провеселио са својијем друштвом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'А кад дође тај твој син који ти је имање просуо с курвама, заклао си му теле угојено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'А он му рече: сине! ти си свагда са мном, и све је моје твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Требало се развеселити и обрадовати, јер овај брат твој мртав бјеше, и оживље; и изгубљен бјеше и нађе се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'А ученицима својијем говораше: бијаше један човјек богат који имаше пристава, и тога облагаше код њега да му просипа имање,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'И дозвавши га рече му: шта ово ја чујем за тебе? Дај рачун како си кућио кућу: јер више не можеш кућом управљати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'А пристав од куће рече у себи: шта ћу чинити? Господар мој узима од мене управљање куће: копати не могу, просити стидим се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Знам шта ћу чинити да би ме примили у куће своје кад ми се одузме управљање куће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'И дозвавши редом дужнике господара својега рече првоме: колико си дужан господару мојему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'А он рече: сто ока уља. И рече му: узми писмо своје и сједи брзо те напиши педесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'А потом рече другоме: а ти колико си дужан? А он рече: сто ока пшенице. И рече му: узми писмо своје и напиши осамдесет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'И похвали господар невјернога пристава што мудро учини; јер су синови овога вијека мудрији од синова видјела у својему нараштају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'И ја вама кажем: начините себи пријатеље неправеднијем богатством, да би вас кад осиромашите примили у вјечне куће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Који је вјеран у малом и у многом је вјеран; а ко је невјеран у малом и у многом је невјеран.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Ако дакле у неправедном богатству вјерни не бисте, ко ће вам у истином вјеровати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'И ако у туђем не бисте вјерни, ко ће вам дати ваше?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Никакав пак слуга не може два господара служити; јер или ће на једнога мрзити а другога љубити, или ће једноме вољети а за другога не марити. Не можете служити Богу и богатству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'А ово све слушаху и фарисеји, који бијаху среброљупци, и ругаху му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'И рече им: ви сте они који се градите праведни пред људима; али Бог зна срца ваша; јер што је у људи високо оно је мрзост пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Закон и пророци су до Јована; отселе се царство Божије проповиједа јеванђељем, и сваки наваљује да уђе у њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Лашње је пак небу и земљи проћи неголи једној титли из закона пропасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Сваки који пушта жену своју и узима другу, прељубу чини; и који се жени пуштеницом, прељубу чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Човјек неки пак бјеше богат, који се облачаше у скерлет и у свилу, и живљаше сваки дан господски и весељаше се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'А бијаше један сиромах, по имену Лазар, који лежаше пред његовијем вратима гнојав,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'И жељаше да се насити мрвама које падаху с трпезе богатога; још и пси долажаху и лизаху гној његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'А кад умрије сиромах, однесоше га анђели у наручје Авраамово; а умрије и богати, и закопаше га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'И у паклу кад бјеше у мукама подиже очи своје и угледа издалека Авраама и Лазара у наручју његову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'И повикавши рече: оче Аврааме! смилуј се на ме и пошљи ми Лазара нека умочи у воду врх од прста својега, и да ми расхлади језик; јер се мучим у овоме пламену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'А Авраам рече: синко! опомени се да си ти примио добра своја у животу своме, и Лазар опет зла; а сад се он тјеши, а ти се мучиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'И преко свега тога постављена је међу нама и вама велика пропаст, да ови који би хтјели одовуд к вама пријећи, не могу, нити они отуда к нама да прелазе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Тада рече: молим те дакле, оче, да га пошаљеш кући оца мојега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Јер имам пет браће: нека им посвједочи да не би и они дошли на ово мјесто мучења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Рече му Авраам: они имају Мојсија и пророке, нека њих слушају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'А он рече: не, оче Аврааме! него ако им дође ко из мртвијех покајаће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'А Авраам рече му: ако не слушају Мојсија и пророка, да ко и из мртвијех устане неће вјеровати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'А ученицима рече: није могуће да не дођу саблазни; али тешко ономе с кога долазе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Боље би му било да му се воденични камен објеси о врату, и да га баце у море, него да саблазни једнога од овијех малијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Чувајте се. Ако ти сагријеши брат твој, накарај га; па ако се покаје, опрости му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'И ако ти седам пута на дан сагријеши, и седам пута на дан дође к теби и рече: кајем се, опрости му.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'И рекоше апостоли Господу: дометни нам вјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'А Господ рече: кад бисте имали вјере колико зрно горушичино, и рекли бисте овоме дубу: ишчупај се и усади се у море, и послушао би вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Који пак од вас кад има слугу који оре или чува стоку па кад дође из поља, рече му: ходи брзо и сједи за трпезу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Него не каже ли му: уготови ми да вечерам, и запрегни се те ми служи док једем и пијем, па онда и ти једи и пиј?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Еда ли ће он захвалити слузи томе кад сврши што му се заповједи? Не вјерујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Тако и ви кад свршите све што вам је заповјеђено, говорите: ми смо залудне слуге, јер учинисмо што смо били дужни чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'И кад иђаше у Јерусалим, он пролажаше између Самарије и Галилеје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'И кад улажаше у једно село сретоше га десет губавијех људи, који сташе издалека,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'И подигоше глас говорећи: Исусе учитељу! помилуј нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'И видјевши их рече им: идите и покажите се свештеницима. И они идући очистише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'А један од њих видјевши да се исцијели поврати се хвалећи Бога иза гласа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'И паде ничице пред ноге његове, и захвали му. И то бјеше Самарјанин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'А Исус одговарајући рече: не исцијелише ли се десеторица? Гдје су дакле деветорица?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Како се међу њима који не нађе да се врати да захвали Богу, него сам овај туђин?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'И рече му: устани, иди; вјера твоја поможе ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'А кад га упиташе фарисеји: кад ће доћи царство Божије? одговарајући рече им: царство Божије неће доћи да се види;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Нити ће се казати: ево га овдје или ондје; јер гле, царство је Божије унутра у вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'А ученицима рече: доћи ће вријеме кад ћете зажељети да видите један дан сина човјечијега, и нећете видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'И рећи ће вам: ево овдје је, или: ено ондје; али не излазите, нити тражите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Јер како што муња сине с неба, и засвијетли се преко свега што је под небом, тако ће бити и син човјечиј у свој дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Али му најприје треба много пострадати, и окривљену бити од рода овога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'И како је било у вријеме Нојево онако ће бити у дане сина човјечијега:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Јеђаху, пијаху, жењаху се, удаваху се до онога дана кад Ноје уђе у ковчег, и дође потоп и погуби све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Тако као што би у дане Лотове: јеђаху, пијаху, куповаху, продаваху, сађаху, зидаху;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'А у дан кад изиђе Лот из Содома, удари огањ и сумпор из неба и погуби све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Тако ће бити и у онај дан кад ће се јавити син човјечиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'У онај дан који се деси на крову а покућство његово у кући, нека не силази да га узме; и који се деси у пољу, тако нека се не враћа натраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Опомињите се жене Лотове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Који пође да сачува душу своју, изгубиће је; а који је изгуби, оживљеће је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Кажем вам: у ону ноћ биће два на једноме одру, један ће се узети а други ће се оставити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Двије ће мљети заједно, једна ће се узети а друга ће се оставити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Два ће бити на њиви, један ће се узети а други ће се оставити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'И одговарајући рекоше му: гдје, Господе? А он им рече: гдје је стрвина онамо ће се и орлови скупити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Каза им пак и причу како се треба свагда молити Богу, и не дати да дотужи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Говорећи: у једноме граду бијаше један судија који се Бога не бојаше и људи не стиђаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'А у ономе граду бијаше једна удовица и долажаше к њему говорећи: не дај ме мојему супарнику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'И не шћадијаше задуго. А најпослије рече у себи: ако се и не бојим Бога и људи не срамим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'Но будући да ми досађује ова удовица, одбранићу је, да ми једнако не долази и не досађује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Тада рече Господ: чујте шта говори неправедни судија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Акамоли Бог неће одбранити избранијех својијех који га моле дан и ноћ?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Кажем вам да ће их одбранити брзо. Али син човјечиј кад дође хоће ли наћи вјеру на земљи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'А и другима који мишљаху за себе да су праведници и друге уништаваху каза причу ову:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Два човјека уђоше у цркву да се моле Богу, један фарисеј и други цариник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Фарисеј стаде и мољаше се у себи овако: Боже! хвалим те што ја нијесам као остали људи: хајдуци, неправедници, прељубочинци или као овај цариник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Постим двапут у недјељи; дајем десетак од свега што имам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'А цариник издалека стајаше, и не шћаше ни очију подигнути на небо, него бијаше прси своје говорећи: Боже! милостив буди мени грјешноме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Кажем вам да овај отиде оправдан кући својој, а не онај. Јер сваки који се сам подиже понизиће се; а који се сам понижује подигнуће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Доношаху к њему и дјецу да их се дотакне; а кад видјеше ученици, запријетише им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'А Исус дозвавши их рече: пустите дјецу нека долазе к мени, и не браните им; јер је таковијех царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'И кажем вам заиста: који не прими царства Божијега као дијете, неће ући у њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'И запита га један кнез говорећи: учитељу благи! шта да учиним да наслиједим живот вјечни?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'А Исус рече му: што ме зовеш благијем? нико није благ осим једнога Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Заповијести знаш: не чини прељубе; не убиј; не укради; не свједочи лажно; поштуј оца и матер своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'А он рече: све сам ово сачувао од младости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'А кад то чу Исус рече му: још ти једно недостаје: продај све што имаш и раздај сиромасима; и имаћеш благо на небу; и хајде за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'А кад он чу то постаде жалостан, јер бјеше врло богат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'А кад га видје Исус гдје постаде жалостан, рече: како је тешко ући у царство Божије онима који имају богатство!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Лакше је камили проћи кроз иглене уши неголи богатоме ући у царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'А они који слушаху рекоше: ко се дакле може спасти?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'А он рече: што је у људи немогуће у Бога је могуће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'А Петар рече: ето ми смо оставили све и за тобом идемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'А он им рече: заиста вам кажем: нема ниједнога који би оставио кућу, или родитеље, или браћу, или сестре, или жену, или дјецу царства ради Божијега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'Који неће примити више у ово вријеме, и на ономе свијету живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Узе пак дванаесторицу и рече им: ево идемо горе у Јерусалим, и све ће се свршити што су пророци писали за сина човјечијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Јер ће га предати незнабошцима, и наругаће му се, и ружиће га, и попљуваће га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'И биће га, и убиће га; и трећи дан устаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'И они ништа од тога не разумјеше, и бесједа ова бјеше од њих сакривена, и не разумјеше што им се каза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'А кад се приближи к Јерихону, један слијепац сјеђаше крај пута просећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'А кад чу народ гдје пролази запита: шта је то?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'И казаше му да Исус Назарећанин пролази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'И повика говорећи: Исусе, сине Давидов! помилуј ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'И пријећаху му они што иђаху напријед да ућути; а он још више викаше: сине Давидов! помилуј ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'И Исус стаде и заповједи да му га доведу; а кад му се приближи, запита га');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Говорећи: шта хоћеш да ти учиним? А он рече: Господе! да прогледам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'А Исус рече: прогледај; вјера твоја поможе ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'И одмах прогледа, и пође за њим хвалећи Бога. И сви људи који видјеше хваљаху Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'И кад уђе у Јерихон и пролажаше кроза њ,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'И гле, човјек по имену Закхеј, који бјеше старјешина царинички, и бјеше богат,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'И искаше да види Исуса да га позна; и не могаше од народа, јер бјеше малога раста;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'И потрчавши напријед, попе се на дуд да га види; јер му је онуда требало проћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'И кад дође Исус на оно мјесто, погледавши горе видје га, и рече му: Закхеју! сиђи брзо; јер ми данас ваља бити у твојој кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'И сиђе брзо; и прими га радујући се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'И сви, кад видјеше, викаху на њега говорећи да гријешноме човјеку дође у кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'А Закхеј стаде и рече Господу: Господе! ево пола имања својега даћу сиромасима, и ако сам кога занио вратићу онолико четворо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'А Исус му рече: данас дође спасеније кући овој; јер је и ово син Авраамов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Јер је син човјечиј дошао да нађе и спасе што је изгубљено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'А кад они то слушаху настави казивати причу; јер бјеше близу Јерусалима, и мишљаху да ће се одмах јавити царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Рече дакле: један човјек од добра рода отиде у даљну земљу да прими себи царство, и да се врати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Дозвавши пак десет својијех слуга даде им десет кеса, и рече им: тргујте док се ја вратим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'И грађани његови мржаху на њега, и послаше за њим посланике говорећи: нећемо да он царује над нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'И кад се он врати, пошто прими царство, рече да дозову оне слуге којима даде сребро, да види шта је који добио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Тада дође први говорећи: господару! кеса твоја донесе десет кеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'И рече му: добро, добри слуго; кад си ми у малом био вјеран ево ти власт над десет градова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'И дође други говорећи: господару! кеса твоја донесе пет кеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'А он рече и ономе: и ти буди над пет градова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'И трећи дође говорећи: господару! ево твоја кеса коју сам завезао у убрус и чувао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Јер сам се бојао тебе: јер си човјек тврд: узимаш што нијеси оставио, и жњеш што нијеси сијао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'А господар му рече: по твојијем ћу ти ријечима судити, зли слуго! знао си да сам ја тврд човјек, узимам што нијесам сијао:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Па зашто нијеси дао мојега сребра трговцима, и ја дошавши примио бих га с добитком?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'И рече онима што стајаху пред њим: узмите од њега кесу и подајте ономе што има десет кеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'И рекоше му: господару! он има десет кеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'А он им одговори: јер вам кажем да ће се свакоме који има дати: а од онога који нема узеће се од њега и оно што има.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'А оне моје непријатеље који нијесу хтјели да ја будем цар над њима, доведите амо, и исијеците преда мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'И казавши ово пође напријед, и иђаше горе у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'И кад се приближи Витфази и Витанији код горе која се зваше Маслинска, посла два од ученика својијех');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'Говорећи: идите у то село према вама, и кад уђете у њега наћи ћете магаре привезано на које никакав човјек никад није усједао; одријешите га и доведите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'И ако вас ко упита: зашто дријешите: овако му кажите: оно Господу треба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'А кад отидоше послани, нађоше као што им каза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'А кад они дријешаху магаре рекоше им господари од њега: зашто дријешите магаре?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'А они рекоше: оно Господу треба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'И доведоше га к Исусу, и бацише хаљине своје на магаре, и посадише Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'А кад иђаше, простираху хаљине своје по путу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'А кад се приближи већ да сиђе с горе Маслинске, поче све мноштво ученика у радости хвалити Бога иза гласа за сва чудеса што су видјели,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Говорећи: благословен цар који иде у име Господње! мир на небу и слава на висини!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'И неки фарисеји из народа рекоше му: учитељу! запријети ученицима својијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'И одговарајући рече им: кажем вам: ако они ућуте, камење ће повикати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'И кад се приближи, угледа град и заплака за њим');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'Говорећи: кад би и ти знао у овај твој дан што је за мир твој! али је сад сакривено од очију твојијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Јер ће доћи дани на тебе, и окружиће те непријатељи твоји опкопима, и опколиће те, и обузеће те са свију страна;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'И разбиће тебе и дјецу твоју у теби, и неће оставити у теби камена на камену, зато што нијеси познао времена у којему си похођен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'И ушавши у цркву стаде изгонити оне што продаваху у њој и куповаху,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'Говорећи им: у писму стоји: дом мој дом је молитве, а ви начинисте од њега пећину хајдучку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'И учаше сваки дан у цркви. А главари свештенички и књижевници и старјешине народне гледаху да га погубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'И не налажаху шта би му учинили; јер сав народ иђаше за њим, и слушаху га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'И кад он у један од онијех дана учаше народ у цркви и проповиједаше јеванђеље, дођоше главари свештенички и књижевници са старјешинама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'И рекоше му говорећи: кажи нам каквом власти то чиниш? Или ко ти је дао власт ту?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'А он одговарајући рече им: и ја ћу вас упитати једну ријеч, и кажите ми:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Крштење Јованово или би с неба или од људи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'А они помишљаху у себи говорећи: ако речемо с неба, рећи ће: зашто му дакле не вјеровасте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Ако ли речемо од људи, сав ће нас народ побити камењем; јер сви вјероваху да Јован бјеше пророк.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'И одговорише: не знамо откуда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'А Исус им рече: ни ја вама нећу казати каквом власти ово чиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'А народу поче казивати причу ову: један човјек посади виноград, и даде га виноградарима па отиде на подуго времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'И у вријеме посла к виноградарима слугу да му даду од рода виноградскога; али виноградари избише га, и послаше празна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'И посла опет другога слугу; а они и онога избише и осрамотивши послаше празна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'И посла опет трећега; а они и онога ранише, и истјераше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Онда рече господар од винограда: шта ћу чинити? Да пошљем сина својега љубазнога: еда се како застиде кад виде њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'А виноградари видјевши њега мишљаху у себи говорећи: ово је нашљедник; ходите да га убијемо да наше буде достојање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'И изведоше га напоље из винограда и убише. Шта ће дакле учинити њима господар од винограда?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Доћи ће и погубиће ове виноградаре, и даће виноград другима. А они што слушаху рекоше: не дао Бог!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'А он погледавши на њих рече: шта значи дакле оно у писму: камен који одбацише зидари онај поста глава од угла?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Сваки који падне на тај камен разбиће се; а на кога он падне сатрће га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'И гледаху главари свештенички и књижевници у онај час да дигну руке на њ; али се побојаше народа, јер разумјеше да њима ову причу каза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'И пажаху на њега, и послаше вребаче, који се грађаху као да су побожни, не би ли га ухватили у ријечи да га предаду поглаварима и власти судијиној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'И упиташе га говорећи: учитељу! знамо да право говориш и учиш, и не гледаш ко је ко, него заиста учиш путу Божијему:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Треба ли нам ћесару давати харач, или не?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'А он разумјевши њихово лукавство рече им: шта ме кушате?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Покажите ми динар; чији је на њему образ и натпис? А они одговарајући рекоше: ћесарев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'А он им рече: подајте дакле што је ћесарево ћесару, а што је Божије Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'И не могоше ријечи његове покудити пред народом; и дивише се одговору његову, и умукоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'А приступише неки од садукеја који кажу да нема васкрсенија, и питаху га');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Говорећи: учитељу! Мојсије нам написа: ако коме умре брат који има жену, и умре без дјеце, да брат његов узме жену, и да подигне сјеме брату својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Бијаше седам браће, и први узе жену, и умрије без дјеце;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'И узе други жену, и он умрије без дјеце;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'И трећи је узе; а тако и сви седам; и не оставише дјеце, и помријеше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'А послије свију умрије и жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'О васкрсенију дакле кога ће од њих бити жена? јер је она седморици била жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'И одговарајући Исус рече им: дјеца овога свијета жене се и удају;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'А који се удостоје добити онај свијет и васкрсеније из мртвих нити ће се женити ни удавати;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Јер више не могу умријети; јер су као анђели; и синови су Божији кад су синови васкрсенија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'А да мртви устају, и Мојсије показа код купине гдје назива Господа Бога Авраамова и Бога Исакова и Бога Јаковљева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'А Бог није Бог мртвијех него живијех; јер су њему сви живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'А неки од књижевника одговарајући рекоше: учитељу! добро си казао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'И већ не смијаху ништа да га запитају. А он им рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Како говоре да је Христос син Давидов?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Кад сам Давид говори у псалтиру: рече Господ Господу мојему: сједи мени с десне стране,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'Док положим непријатеље твоје подножје ногама твојима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Давид дакле њега назива Господом; па како му је син?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'А кад сав народ слушаше, рече ученицима својијем:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Чувајте се од књижевника, који хоће да иду у дугачкијем хаљинама, и траже да им се клања по улицама, и првијех мјеста по зборницама, и зачеља на гозбама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Који једу куће удовичке, и лажно се моле Богу дуго. Они ће још већма бити осуђени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Погледавши пак горе видје богате гдје мећу прилоге своје у хазну Божију;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'А видје и једну сиромашну удовицу која меташе ондје двије лепте;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'И рече: заиста вам кажем: ова сиромашна удовица метну више од свију:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Јер сви ови метнуше у прилог Богу од сувишка својега, а она од сиротиње своје метну сву храну своју што имаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'И кад неки говораху за цркву да је украшена лијепијем камењем и закладима, рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Доћи ће дани у које од свега што видите неће остати ни камен на камену који се неће разметнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Запиташе га пак говорећи: учитељу! а кад ће то бити? и какав је знак кад ће се то догодити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'А он рече: чувајте се да вас не преваре, јер ће многи доћи на име моје говорећи: ја сам, и вријеме се приближи. Не идите дакле за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'А кад чујете ратове и буне, не плашите се; јер то све треба најприје да буде; али још није тада пошљедак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Тада им рече: устаће народ на народ и царство на царство;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'И земља ће се трести врло по свијету, и биће глади и помори и страхоте и велики знаци биће на небу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'А прије свега овога метнуће на вас руке своје и гониће вас и предавати у зборнице и у тамнице; водиће вас пред цареве и краљеве имена мојега ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'А то ће вам се догодити за свједочанство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Метните дакле у срца своја, да се прије не приправљате како ћете одговарати:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Јер ћу вам ја дати уста и премудрост којој се неће моћи противити ни одговорити сви ваши противници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'А предаваће вас и родитељи и браћа и рођаци и пријатељи; и побиће неке од вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'И сви ће омрзнути на вас имена мојега ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'И длака с главе ваше неће погинути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'Трпљењем својијем спасавајте душе своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'А кад видите да Јерусалим опколи војска онда знајте да се приближило вријеме да опусти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Тада који буду у Јудеји нека бјеже у горе, и који буду у граду нека излазе напоље; и који су напољу нека не улазе у њега:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Јер су ово дани освете, да се изврши све што је написано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Али тешко труднима и дојилицама у те дане! Јер ће бити велика невоља на земљи, гњев на овом народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'И пашће од оштрица мача, и одвешће се у ропство по свијем народима; и Јерусалим ће газити незнабошци док се не изврше времена незнабожаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'И биће знаци у сунцу и у мјесецу и у звијездама; и људима на земљи туга од сметње и од хуке морске и валова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Људи ће умирати од страха и од чекања онога што иде на земљу; јер ће се и силе небеске покренути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'И тада ће угледати сина човјечијега гдје иде на облацима са силом и славом великом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'А кад се почне ово збивати, гледајте и подигните главе своје; јер се приближује избављење ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'И каза им причу: гледајте на смокву и на сва дрвета;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Кад видите да већ потјерају, сами знате да је близу љето.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Тако и ви кад видите ово да се збива, знајте да је близу царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Заиста вам кажем да овај нараштај неће проћи док се ово све не збуде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Небо и земља проћи ће, а ријечи моје неће проћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Али се чувајте да како ваша срца не отежају ждерањем и пијанством и бригама овога свијета, и да вам овај дан не дође изненада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Јер ће доћи као замка на све који живе по свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Стражите дакле једнако и молите се Богу да бисте се удостојили утећи од свега овога што ће се збити, и стати пред сином човјечијим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'И дању учаше у цркви, а ноћу излажаше и ноћиваше на гори која се зове Маслинска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'И сав народ долажаше изјутра к њему у цркву да га слушају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Приближаваше се пак празник пријеснијех хљебова који се зове пасха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'И гледаху главари свештенички и књижевници како би га убили; али се бојаху народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'А сотона уђе у Јуду, који се зваше Искариот, и који бјеше један од дванаесторице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'И отишавши говори с главарима свештеничкијем и са старјешинама како ће им га издати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'И они се обрадоваше, и уговорише да му даду новце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'И он се обрече, и тражаше згодна времена да им га преда тајно од народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'А дође дан пријеснијех хљебова у који требаше клати пасху;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'И посла Петра и Јована рекавши: идите уготовите нам пасху да једемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'А ови му рекоше: гдје хоћеш да уготовимо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'А он им рече: ето кад уђете у град, срешће вас човјек који носи воду у крчагу; идите за њим у кућу у коју он уђе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'И кажите домаћину: учитељ вели: гдје је гостионица гдје ћу јести пасху с ученицима својијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'И он ће вам показати велику собу прострту; ондје уготовите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'А они отидоше и нађоше као што им каза; и уготовише пасху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'И кад дође час, сједе за трпезу, и дванаест апостола с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'И рече им: врло сам жељео да ову пасху једем с вама прије него пострадам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Јер вам кажем да је отселе нећу јести док се не сврши у царству Божијему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'И узевши чашу даде хвалу, и рече: узмите је и раздијелите међу собом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Јер вам кажем да нећу пити од рода виноградскога док не дође царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'И узевши хљеб даде хвалу, и преломивши га даде им говорећи: ово је тијело моје које се даје за вас; ово чините за мој спомен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'А тако и чашу по вечери, говорећи: ова је чаша нови завјет мојом крви која се за вас прољева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Али ево рука издајника мојега са мном је на трпези.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'И син човјечиј дакле иде као што је уређено; али тешко човјеку ономе који га издаје!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'И они сташе тражити међу собом који би дакле од њих био који ће то учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'А поста и препирање међу њима који би се држао међу њима да је највећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'А он им рече: цареви народни владају народом, а који њим управљају, зову се добротвори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Али ви немојте тако; него који је највећи међу вама нека буде као најмањи, и који је старјешина нека буде као слуга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Јер који је већи, који сједи за трпезом или који служи? Није ли онај који сједи за трпезом? А ја сам међу вама као слуга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'А ви сте они који сте се одржали са мном у мојијем напастима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'И ја остављам вама царство као што је отац мој мени оставио:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'Да једете и пијете за трпезом мојом у царству мојему, и да сједите на пријестолима и судите над дванаест кољена Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Рече пак Господ: Симоне! Симоне! ево вас иште сотона да би вас чинио као пшеницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'А ја се молих за тебе да твоја вјера не престане; и ти кадгод обративши се утврди браћу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'А он му рече: Господе! с тобом готов сам и у тамницу и на смрт ићи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'А он рече: кажем ти, Петре! данас неће запјевати пијетао док се трипут не одречеш да ме познајеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'И рече им: кад вас послах без кесе и без торбе и без обуће, еда вам што недостаде? А они рекоше: ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'А он им рече: али сад који има кесу нека је узме, тако и торбу; а који нема нека прода хаљину своју и купи нож.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Јер вам кажем да још и ово треба на мени да се изврши што стоји у писму: и међу злочинце метнуше га. Јер што је писано за мене, свршује се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'А они рекоше: Господе! ево овдје два ножа. А он им рече: доста је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'И изишавши отиде по обичају на гору Маслинску; а за њим отидоше ученици његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'А кад дође на мјесто рече им: молите се Богу да не паднете у напаст.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'И сам отступи од њих како се може каменом добацити, и клекнувши на кољена мољаше се Богу');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'Говорећи: оче! кад би хтио да пронесеш ову чашу мимо мене! али не моја воља него твоја да буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'А анђео му се јави с неба, и кријепи га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'И будући у борењу, мољаше се боље; зној пак његов бијаше као капље крви које капаху на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'И уставши од молитве дође к ученицима својијем, и нађе их а они спавају од жалости,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'И рече им: што спавате? устаните, молите се Богу да не паднете у напаст.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Док он још пак говораше, гле, народ и један од дванаесторице, који се зваше Јуда, иђаше пред њима, и приступи к Исусу да га цјелива. Јер им ово бијаше дао знак: кога цјеливам онај је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'А Исус му рече: Јуда! зар цјеливом издајеш сина човјечијега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'А кад они што бијаху с њим видјеше шта ће бити, рекоше му: Господе! да бијемо ножем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'И удари један од њих слугу поглавара свештеничкога, и отсијече му десно ухо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'А Исус одговарајући рече: оставите то. И дохвативши се до уха његова исцијели га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'А главарима свештеничкијем и војводама црквенијем и старјешинама који бијаху дошли на њ рече Исус: зар као на хајдука изиђосте с ножевима и кољем да ме ухватите?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Сваки дан био сам с вама у цркви и не дигосте руку на мене; али је сад ваш час и област таме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'А кад га ухватише, одведоше га и уведоше у двор поглавара свештеничкога. А Петар иђаше за њим издалека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'А кад они наложише огањ насред двора и сјеђаху заједно, и Петар сјеђаше међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Видјевши га пак једна слушкиња гдје сједи код огња, и погледавши на њ рече: и овај бјеше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'А он га се одрече говорећи: жено! не познајем га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'И мало затијем видје га други и рече: и ти си од њих. А Петар рече: човјече! нијесам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'И пошто прође око једнога сахата други неко потврђиваше говорећи: заиста и овај бјеше с њим; јер је Галилејац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'А Петар рече: човјече! не знам шта говориш. И одмах док он још говораше запјева пијетао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'И обазревши се Господ погледа на Петра, и Петар се опомену ријечи Господње како му рече: прије него пијетао запјева одрећи ћеш ме се трипут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'И изишавши напоље плака горко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'А људи који држаху Исуса ругаху му се, и бијаху га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'И покривши га бијаху га по образу и питаху га говорећи: прореци ко те удари?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'И друге многе хуле говораху на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'И кад свану, сабраше се старјешине народне и главари свештенички и књижевници, и одведоше га у свој суд');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Говорећи: јеси ли ти Христос? кажи нам. А он им рече: ако вам и кажем, нећете вјеровати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'А ако вас и запитам, нећете ми одговорити, нити ћете ме пустити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Отселе ће син човјечиј сједити с десне стране силе Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Сви пак рекоше: ти ли си дакле син Божиј? А он им рече: ви кажете да сам ја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'А они рекоше: шта нам требају више свједочанства? јер сами чусмо из уста његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'И уставши њих све мноштво одведоше га к Пилату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'И почеше га тужити говорећи: овога нађосмо да отпађује народ наш, и забрањује давати ћесару данак, и говори да је он Христос цар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'А Пилат га запита: ти ли си цар Јудејски? А он одговарајући рече му: ти кажеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'А Пилат рече главарима свештеничкијем и народу: ја не налазим никакве кривице на овом човјеку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'А они наваљиваху говорећи: он буни људе учећи по свој Јудеји почевши од Галилеје довде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'А Пилат чувши за Галилеју запита: зар је он Галилејац?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'И разумјевши да је из подручја Иродова посла га Ироду, који такођер бијаше у Јерусалиму онијех дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'А Ирод видјевши Исуса би му врло мило; јер је одавно жељео да га види, јер је много слушао за њега, и надаше се да ће видјети од њега како чудо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'И пита га много које за што; али му он ништа не одговори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'А главари свештенички и књижевници стајаху, и једнако тужаху га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'А Ирод осрамотивши га са својијем војницима, и наругавши му се, обуче му бијелу хаљину, и посла га натраг Пилату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'И у тај се дан помирише Пилат и Ирод међу собом; јер прије бијаху у завади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'А Пилат сазвавши главаре свештеничке и кнезове и народ');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'Рече им: доведосте ми овога човјека као који народ отпађује, и ето ја га пред вама испитах, и не налазим на овом човјеку ниједне кривице што ви на њега говорите;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'А ни Ирод, јер сам га слао к њему; и ето се не налази ништа да је учинио што би заслуживало смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Дакле да га избијем па да пустим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'А требаше о сваком празнику пасхе да им пусти по једнога сужња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Али народ сав повика говорећи: узми овога, а пусти нам Вараву;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Који бијаше бачен у тамницу за некакву буну учињену у граду и за крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'А Пилат опет рече да би он хтио пустити Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'А они викаху говорећи: распни га, распни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'А он им трећи пут рече: какво је дакле он зло учинио? ја ништа на њему не нађох што би заслуживало смрт; даклем да га избијем па да пустим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'А они једнако наваљиваху с великом виком, и искхаху да се он разапне; и надвлада вика њихова и главара свештеничкијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'И Пилат пресуди да буде као што они ишту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'И пусти онога што искаху, који бјеше бачен у тамницу за буну и за крв; а Исуса остави на њихову вољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'И кад га поведоше, ухватише некога Симона Киринца који иђаше из поља, и метнуше на њега крст да носи за Исусом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'А за њим иђаше мноштво народа и жена, које плакаху и нарицаху за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'А Исус обазревши се на њих рече: кћери Јерусалимске! не плачите за мном, него плачите за собом и за дјецом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Јер гле, иду дани у које ће се рећи: благо нероткињама, и утробама које не родише, и сисама које не дојише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Тада ће почети говорити горама: падните на нас; и бреговима: покријте нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Јер кад се овако ради од сирова дрвета, шта ће бити од суха?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Вођаху пак и друга два злочинца да погубе с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'И кад дођоше на мјесто које се зваше коштурница, ондје разапеше њега и злочинце, једнога с десне стране а другога с лијеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'А Исус говораше: оче! опрости им; јер не знаду шта чине. А дијелећи његове хаљине бацаху коцке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'И народ стајаше те гледаше, а и кнезови с њима ругаху му се говорећи: другима поможе, нека поможе и себи, ако је он Христос, избраник Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'А и војници му се ругаху, и приступаху к њему и даваху му оцат,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'И говораху: ако си ти цар Јудејски помози сам себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'А бијаше над њим и натпис написан словима Грчкијем и Латинскијем и Јеврејскијем: ово је цар Јудејски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'А један од објешенијех злочинаца хуљаше на њега говорећи: ако си ти Христос помози себи и нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'А други одговарајући шуткаше га и говораше: зар се ти не бојиш Бога, кад си и сам осуђен тако?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'И ми смо још праведно осуђени; јер примамо по својијем дјелима као што смо заслужили; али он никаква зла није учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'И рече Исусу: опомени ме се, Господе! кад дођеш у царство своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'И рече му Исус: заиста ти кажем: данас ћеш бити са мном у рају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'А бијаше око шестога сахата, и тама би по свој земљи до сахата деветога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'И помрча сунце, и завјес црквени раздрије се напола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'И повикавши Исус иза гласа рече: оче! у руке твоје предајем дух свој. И рекавши ово издахну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'А кад видје капетан шта би, стаде хвалити Бога говорећи: заиста овај човјек бјеше праведник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'И сав народ који се бијаше скупио да гледа ово, кад видје шта бива, врати се бијући се у прси своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'А сви његови знанци стајаху издалека, и жене које бијаху ишле за њим из Галилеје, и гледаху ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'И гле, човјек, по имену Јосиф, савјетник, човјек добар и праведан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, '(Он не бијаше пристао на њихов савјет и на посао) из Ариматеје града Јудејскога, који и сам чекаше царства Божијега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Он приступивши к Пилату заиска тијело Исусово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'И скиде га, и обави платном, и метну га у гроб исјечен, у коме нико не бијаше никад метнут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'И дан бијаше петак, и субота освиташе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'А жене које бијаху дошле с Исусом из Галилеје, идоше за Јосифом, и видјеше гроб и како се тијело метну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Вративши се пак приправише мирисе и миро; и у суботу дакле осташе на миру по закону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'А у први дан недјељни дођоше врло рано на гроб, и донесоше мирисе што приправише, и неке друге жене с њима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Али нађоше камен одваљен од гроба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'И ушавши не нађоше тијела Господа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'И кад се оне чуђаху томе, гле, два човјека сташе пред њима у сјајнијем хаљинама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'А кад се оне уплашише и оборише лица к земљи, рекоше им: што тражите живога међу мртвима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Није овдје; него устаде; опомените се како вам каза кад бјеше још у Галилеји,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'Говорећи да син човјечиј треба да се преда у руке људи грјешника и да се разапне и трећи дан да устане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'И опоменуше се ријечи његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'И вративши се од гроба јавише све ово једанаесторици и свима осталијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'А то бијаше Магдалина Марија и Јована и Марија Јаковљева и остале с њима које казаше ово апостолима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'И њима се учинише њихове ријечи као лаж, и не вјероваше им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'А Петар уставши отрча ка гробу, и наткучивши се видје саме хаљине гдје леже, и отиде чудећи се у себи шта би.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'И гле, двојица од њих иђаху у онај дан у село које бијаше далеко од Јерусалима шесет потркалишта и зваше се Емаус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'А они говораху међу собом о свима овијем догађајима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'И кад се они разговараху и запитиваху један другога, и Исус приближи се, и иђаше с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'А очи им се држаху да га не познаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'А он им рече: какав је то разговор који имате међу собом идући, и што сте невесели?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'А један по имену Клеопа, одговарајући рече му: зар си ти један од црквара у Јерусалиму који нијеси чуо шта је у њему било овијех дана?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'И рече им: шта? А они му рекоше: за Исуса Назарећанина, који бјеше пророк, силан у дјелу и у ријечи пред Богом и пред свијем народом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'Како га предадоше главари свештенички и кнезови наши те се осуди на смрт, и разапеше га?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'А ми се надасмо да је он онај који ће избавити Израиља; али сврх свега тога ово је данас трећи дан како ти би.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'А уплашише нас и жене неке од нашијех које су биле рано на гробу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'И не нашавши тијела његова дођоше говорећи да су им се анђели јавили који су казали да је он жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'И идоше једни од нашијех на гроб, и нађоше тако као што и жене казаше, али њега не видјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'И он им рече: о безумни и спорога срца за вјеровање свега што говорише пророци!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Није ли то требало да Христос претрпи и да уђе у славу своју?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'И почевши од Мојсија и од свију пророка казиваше им што је за њега у свему писму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'И приближише се к селу у које иђаху, и он чињаше се да хоће даље да иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'И они га устављаху говорећи: остани с нама, јер је дан нагао, и близу је ноћ. И уђе с њима да ноћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'И кад сјеђаше с њима за трпезом, узе хљеб и благословивши преломи га и даде им.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Тада се њима отворише очи и познаше га. И њега нестаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'И они говораху један другоме: не гораше ли наше срце у нама кад нам говораше путем и кад нам казиваше писмо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'И уставши онај час, вратише се у Јерусалим, и нађоше у скупу једанаесторицу и који бијаху с њима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'Који говораху: заиста устаде Господ, и јави се Симону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'И они казаше што би на путу, и како га познаше кад преломи хљеб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'А кад они ово говораху, и сам Исус стаде међу њима, и рече им: мир вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'А они се уплашише, и поплашени будући, мишљаху да виде духа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'И рече им: шта се плашите? И зашто такове мисли улазе у срца ваша?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Видите руке моје и ноге моје: ја сам главом; опипајте ме и видите; јер дух тијела и костију нема као што видите да ја имам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'И ово рекавши показа им руке и ноге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'А док они још не вјероваху од радости и чуђаху се рече им: имате ли овдје што за јело?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'А они му даше комад рибе печене, и меда у сату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'И узевши изједе пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'И рече им: ово су ријечи које сам вам говорио још док сам био с вама, да све треба да се сврши што је за мене написано у закону Мојсијеву и у пророцима и у псалмима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Тада им отвори ум да разумију писмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'И рече им: тако је писано, и тако је требало да Христос пострада и да устане из мртвијех трећи дан;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'И да се проповиједа покајање у име његово и опроштење гријеха по свијем народима почевши од Јерусалима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'А ви сте свједоци овоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'И гле, ја ћу послати обећање оца својега на вас; а ви сједите у граду Јерусалимскоме док се не обучете у силу с висине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'И изведе их напоље до Витаније, и подигнувши руке своје благослови их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'И кад их благосиљаше, отступи од њих, и узношаше се на небо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'И они му су поклонише, и вратише се у Јерусалим с великом радошћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'И бијаху једнако у цркви хвалећи и благосиљајући Бога. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'У почетку бјеше ријеч, и ријеч бјеше у Бога, и Бог бјеше ријеч.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Она бјеше у почетку у Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Све је кроз њу постало, и без ње ништа није постало што је постало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'У њој бјеше живот, и живот бјеше видјело људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'И видјело се свијетли у тами, и тама га не обузе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Посла Бог човјека по имену Јована.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Овај дође за свједочанство да свједочи за видјело да сви вјерују кроза њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Он не бјеше видјело, него да свједочи за видјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Бјеше видјело истинито које обасјава свакога човјека који долази на свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'На свијету бјеше, и свијет кроза њ поста, и свијет га не позна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'К својима дође, и своји га не примише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'А који га примише даде им власт да буду синови Божији, који вјерују у име његово,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Који се не родише од крви, ни од воље тјелесне, ни од воље мужевље, него од Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'И ријеч постаде тијело и усели се у нас пуно благодати и истине; и видјесмо славу његову, славу, као јединороднога од оца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Јован свједочи за њега и виче говорећи: овај бјеше за кога рекох: који за мном иде преда мном постаде, јер прије мене бјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'И од пуности његове ми сви узесмо благодат за благодаћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Јер се закон даде преко Мојсија, а благодат и истина постаде од Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Бога нико није видио никад: јединородни син који је у наручју очином, он га јави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'И ово је свједочанство Јованово кад послаше Јевреји из Јерусалима свештенике и Левите да га запитају: ко си ти?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'И он призна, и не затаја, и призна: ја нијесам Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'И запиташе га: ко си дакле? Јеси ли Илија? И рече: нијесам. Јеси ли пророк? И одговори: нијесам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'А они му рекоше: ко си? да можемо казати онима што су нас послали: шта кажеш за себе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Рече: ја сам глас онога што виче у пустињи: поравните пут Господњи; као што каза Исаија пророк.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'И бијаху посланици од фарисеја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'И запиташе га говорећи му: зашто дакле кршћаваш кад ти нијеси Илија ни пророк?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Одговори им Јован говорећи: ја кршћавам водом а међу вама стоји кога ви не знате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'Он је онај што ће доћи за мном, који бјеше преда мном; коме ја нијесам достојан одријешити ремена на обући његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Ово би у Витанији преко Јордана гдје Јован кршћеваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'А сјутрадан видје Јован Исуса гдје иде к њему, и рече: гле, јагње Божије које узе на се гријехе свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Ово је онај за кога ја рекох: за мном иде човјек који преда мном постаде, јер прије мене бјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'И ја га не знадох: него да се јави Израиљу зато ја дођох да крстим водом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'И свједочи Јован говорећи: видјех Духа гдје силази с неба као голуб и стаде на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'И ја га не знадох; него онај који ме посла да крстим водом он ми рече: на кога видиш да силази Дух и стоји на њему то је онај који ће крстити Духом светијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'И ја видјех и засвједочих да је овај син Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'А сјутрадан опет стајаше Јован и двојица од ученика његовијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'И видјевши Исуса гдје иде, рече: гле, јагње Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'И чуше га оба ученика кад говораше, и отидоше за Исусом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'А Исус обазревши се и видјевши их гдје иду за њим, рече им: шта ћете? А они му рекоше: Рави! (које значи: учитељу) гдје стојиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'И рече им: дођите и видите. И отидоше, и видјеше гдје стајаше; и осташе у њега онај дан. А бијаше око деветога сахата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'А један од двојице који чуше од Јована и иђаху за њим бијаше Андрија брат Симона Петра;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Он нађе најприје брата својега Симона, и рече му: ми нађосмо Месију, које значи Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'И доведе га к Исусу. А Исус погледавши на њ рече: ти си Симон, син Јонин; ти ћеш се звати Кифа, које значи Петар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'А сјутрадан намисли изићи у Галилеју, и нађе Филипа, и рече му: хајде за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'А Филип бјеше из Витсаиде из града Андријина и Петрова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Филип нађе Натанаила, и рече му: за кога Мојсије у закону писа и пророци, нађосмо га, Исуса сина Јосифова из Назарета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'И рече му Натанаило: из Назарета може ли бити што добро? Рече му Филип: дођи и види.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'А Исус видјевши Натанаила гдје иде к њему рече за њега: ево правога Израиљца у коме нема лукавства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Рече му Натанаило: како ме познајеш? Одговори Исус и рече му: прије него те позва Филип видјех те кад бијаше под смоквом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Одговори Натанаило и рече му: Рави! ти си син Божиј, ти си цар Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Одговори Исус и рече му: што ти казах да те видјех под смоквом зато вјерујеш; видјећеш више од овога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'И рече му: заиста, заиста вам кажем: отселе ћете видјети небо отворено и анђеле Божије гдје се пењу и силазе к сину човјечијему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'И трећи дан би свадба у Кани Галилејској, и ондје бјеше мати Исусова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'А позван бјеше и Исус и ученици његови на свадбу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'И кад неста вина, рече мати Исусова њему: немају вина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Исус јој рече: што је мени до тебе жено? Још није дошао мој час.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Рече мати његова слугама: што год вам рече учините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'А ондје бијаше шест воденијех судова од камена, постављенијех по обичају Јеврејскога чишћења, који узимаху по два или по три ведра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Рече им Исус: напуните судове воде. И напунише их до врха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'И рече им: захватите сад и носите куму. И однесоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'А кад окуси кум од вина које је постало од воде, и не знадијаше откуда је (а слуге знадијаху које су захватиле воду), зовну кум женика,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'И рече му: сваки човјек најприје добро вино износи, а кад се опију онда рђавије; а ти си чувао добро вино дослије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Ово учини Исус почетак чудесима у Кани Галилејској, и показа славу своју; и ученици његови вјероваше га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Потом сиђе у Капернаум, он и мати његова, и браћа његова, и ученици његови, и ондје стајаше не много дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'И близу бјеше пасха Јеврејска, и изиђе Исус у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'И нађе у цркви гдје сједе они што продаваху волове и овце и голубове, и који новце мијењаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'И начинивши бич од узица, изгна све из цркве, и овце и волове; и мјењачима просу новце и столове испремета;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'И рече онима што продаваху голубове: носите то одавде, и не чините од дома оца мојега дома трговачкога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'А ученици се његови опоменуше да у писму стоји: ревност за кућу твоју изједе ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'А Јевреји одговарајући рекоше му: какав нам знак показујеш, да то можеш чинити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Исус одговори и рече им: развалите ову цркву, и за три дана ћу је подигнути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'А Јевреји рекоше: четрдесет и шест година грађена је ова црква, а ти за три дана да је подигнеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'А он говораше за цркву тијела својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'А кад уста из мртвијех, опоменуше се ученици његови да ово говораше, и вјероваше писму и ријечи коју рече Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'А кад бјеше у Јерусалиму на празник пасхе, многи вјероваше у име његово, видећи чудеса његова која чињаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Али Исус не повјераваше им себе; јер их све знадијаше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'И не требаше му да ко свједочи за човјека; јер сам знадијаше шта бјеше у човјеку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Бијаше пак човјек међу фарисејима, по имену Никодим, кнез Јеврејски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Овај дође к Исусу ноћу и рече му: Рави! знамо да си ти учитељ од Бога дошао; јер нико не може чудеса овијех чинити која ти чиниш ако није Бог с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Одговори Исус и рече му: заиста, заиста ти кажем: ако се ко наново не роди, не може видјети царства Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Рече Никодим њему: како се може човјек родити кад је стар? еда ли може по други пут ући у утробу матере своје и родити се?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Одговори Исус: заиста, заиста ти кажем: ако се ко не роди водом и Духом, не може ући у царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Што је рођено од тијела, тијело је; а што је рођено од Духа, дух је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Не чуди се што ти рекох; ваља вам се наново родити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Дух дише гдје хоће, и глас његов чујеш, а не знаш откуда долази и куда иде; тако је сваки човјек који је рођен од Духа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Одговори Никодим и рече му: како може то бити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Исус одговори и рече му: ти си учитељ Израиљев, и то ли не знаш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Заиста, заиста ти кажем да ми говоримо што знамо, и свједочимо што видјесмо, и свједочанства нашега не примате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Кад вам казах земаљско па не вјерујете, како ћете вјеровати ако вам кажем небеско?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'И нико се не попе на небо осим који сиђе с неба, син човјечиј који је на небу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'И као што Мојсије подиже змију у пустињи, тако треба син човјечиј да се подигне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'Да ниједан који га вјерује не погине, него да има живот вјечни:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Јер Богу тако омиље свијет да је и сина својега јединороднога дао, да ниједан који га вјерује не погине, него да има живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Јер Бог не посла сина својега на свијет да суди свијету, него да се свијет спасе кроза њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Који њега вјерује не суди му се, а који не вјерује већ је осуђен, јер не вјерова у име јединороднога сина Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'А суд је овај што видјело дође на свијет, и људима омиље већма тама неголи видјело; јер њихова дјела бијаху зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Јер сваки који зло чини мрзи на на видјело и не иде к видјелу да не покарају дјела његовијех, јер су зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'А ко истину чини иде к видјелу, да се виде дјела његова, јер су у Богу учињена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'А потом дође Исус и ученици његови у Јудејску земљу, и ондје живљаше с њима и кршћаваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'А Јован кршћаваше у Енону близу Салима, јер ондје бјеше много воде; и долажаху те их кршћаваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Јер још не бијаше Јован бачен у тамницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Тада постаде распра међу ученицима Јовановијем и Јеврејима око чишћења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'И дођоше к Јовану и рекоше му: Рави! онај што бјеше с тобом преко Јордана, за кога си ти свједочио, ево он кршћава, и сви иду к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Јован одговори и рече: не може човјек ништа примати ако му не буде дано с неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Ви сами мени свједочите да рекох: ја нијесам Христос, него сам послан пред њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Ко има невјесту женик је, а пријатељ жеников стоји и слуша га, и радошћу радује се гласу женикову. Ова дакле радост моја испуни се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Онај треба да расте, а ја да се умаљујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Који одозго долази над свима је; који је са земље од земље је, и говори од земље; који долази с неба над свима је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'И што видје и чу оно свједочи; и свједочанства његова нико не прима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Који прими његово свједочанство, потврди да је Бог истинит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Јер кога Бог посла, онај ријечи Божије говори: јер Бог Духа не даје на мјеру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Јер отац љуби сина, и све даде у руке његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Ко вјерује сина, има живот вјечни; а ко не вјерује сина, неће видјети живота, него гњев Божиј остаје на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Кад разумје дакле Господ да су чули фарисеји да Исус више ученика добија и кршћава него Јован');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(Исус пак сам не кршћаваше него ученици његови),');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Остави Јудеју, и отиде опет у Галилеју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'А ваљало му је проћи кроз Самарију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Тако дође у град Самаријски који се зове Сихар, близу села које даде Јаков Јосифу сину својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'А ондје бијаше извор Јаковљев; и Исус уморан од пута сјеђаше на извору; а бјеше око шестога сахата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Дође жена Самарјанка да захвати воде; рече јој Исус; дај ми да пијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, '(Јер ученици његови бијаху отишли у град да купе јела.)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Рече му жена Самарјанка: како ти, Јеврејин будући, можеш искати од мене жене Самарјанке да пијеш? Јер се Јевреји не мијешају са Самарјанима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Одговори Исус и рече јој: да ти знаш дар Божиј, и ко је тај који ти говори: дај ми да пијем, ти би искала у њега и дао би ти воду живу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Рече му жена: Господе! ни захватити немаш чим, а студенац је дубок; одакле ћеш дакле узети воду живу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Еда ли си ти већи од нашега оца Јакова, који нам даде овај студенац, и он из њега пијаше и синови његови и стока његова?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Одговори Исус и рече јој: сваки који пије од ове воде опет ће ожедњети;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'А који пије од воде коју ћу му ја дати неће ожедњети довијека; него вода што ћу му ја дати биће у њему извор воде која тече у живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Рече му жена: Господе! дај ми те воде да не жедним нити да долазим овамо на воду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Рече јој Исус: иди зовни мужа својега, и дођи овамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Одговори жена и рече му: немам мужа. Рече јој Исус: добро си казала: немам мужа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Јер си пет мужева имала, и сад кога имаш није ти муж; то си право казала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Рече му жена: Господе! видим да си ти пророк.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Оци наши молише се Богу на овој гори, а ви кажете да је у Јерусалиму мјесто гдје се треба молити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Рече јој Исус: жено! вјеруј ми да иде вријеме кад се нећете молити оцу ни на овој гори ни у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Ви не знате чему се молите; а ми знамо чему се молимо: јер је спасеније од Јевреја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Али иде вријеме, и већ је настало, кад ће се прави богомољци молити оцу духом и истином, јер отац хоће таковијех богомољаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Бог је дух; и који му се моле, духом и истином треба да се моле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Рече му жена: знам да ће доћи Месија који се зове Христос, кад он дође казаће нам све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Рече јој Исус: ја сам који с тобом говорим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'И тада дођоше ученици његови, и чуђаху се гдје говораше са женом; али ниједан не рече: шта хоћеш? или шта говориш с њом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'А жена остави судове своје и отиде у град и рече људима:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Ходите да видите човјека који ми каза све што сам учинила: да није то Христос?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Изиђоше дакле из града и пођоше к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'А ученици његови мољаху га међу тијем говорећи: Рави! једи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'А он им рече: ја имам јело да једем за које ви не знате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Тада ученици говораху међу собом: већ ако му ко донесе да једе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'А он им рече: јело је моје да извршим вољу онога који ме је послао, и да свршим његов посао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Не кажете ли ви да су још четири мјесеца па ће жетва приспјети? Ето, велим вам: подигните очи своје и видите њиве како су већ жуте за жетву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'И који жње прима плату, и сабира род за живот вјечни, да се радују заједно и који сије и који жње;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Јер је у том истинита бесједа да је други који сије а други који жње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Ја вас послах да жњете гдје се ви не трудисте; други се трудише, а ви у посао њихов уђосте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'И из града онога многи од Самарјана вјероваше га за бесједу жене која свједочаше: каза ми све што сам учинила.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Кад дођоше дакле Самарјани к њему, мољаху га да би остао код њих; и ондје оста два дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'И много их више вјерова за његову бесједу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'А жени говораху: сад не вјерујемо више за твоју бесједу, јер сами чусмо и познасмо да је овај заиста спас свијету, Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'А послије два дана изиђе оданде, и отиде у Галилеју:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Јер сам Исус свједочаше да пророк на својој постојбини нема части.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'А кад дође у Галилеју, примише га Галилејци који бијаху видјели све што учини у Јерусалиму на празник; јер и они идоше на празник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Дође пак Исус опет у Кану Галилејску, гдје претвори воду у вино. И бјеше неки царев човјек којега син боловаше у Капернауму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Овај чувши да Исус дође из Јудеје у Галилеју, дође к њему и мољаше га да сиђе и да му исцијели сина; јер бијаше на смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'И рече му Исус: ако не видите знака и чудеса, не вјерујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Рече му царев човјек: Господе! сиђи док није умрло дијете моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Рече му Исус: иди, син је твој здрав. И вјерова човјек ријечи коју му рече Исус, и пође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'И одмах кад он силажаше, гле, сретоше га слуге његове и јавише му говорећи: син је твој здрав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Тада питаше за сахат у који му лакше би; и казаше му: јуче у седмом сахату пусти га грозница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Тада разумје отац да бјеше онај сахат у који му рече Исус: син је твој здрав. И вјерова он и сва кућа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Ово опет друго чудо учини Исус кад дође из Јудеје у Галилеју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'А потом бјеше празник Јеврејски, и изиђе Исус у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'У Јерусалиму пак код Овчијех врата има бања, која се зове Јеврејски Витезда, и око ње пет покривенијех тријемова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'У којима лежаше мноштво болесника, слијепијех, хромијех, сухијех, који чекаху да се заљуља вода;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Јер анђео Господњи силажаше у одређено вријеме у бању и мућаше воду; и који најприје улажаше пошто се замути вода, оздрављаше, макар каква болест да је на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'А ондје бијаше један човјек који тридесет и осам година бјеше болестан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Кад видје Исус овога гдје лежи, и разумје да је већ одавно болестан, рече му: хоћеш ли да будеш здрав?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Одговори му болесни: да, Господе; али немам човјека да ме спусти у бању кад се замути вода; а док ја дођем други сиђе прије мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Рече му Исус: устани, узми одар свој и ходи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'И одмах оздрави човјек, и узевши одар свој хођаше. А тај дан бјеше субота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Тада говораху Јевреји ономе што оздрави: данас је субота и не ваља ти одра носити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'А он им одговори: који ме исцијели он ми рече: узми одар свој и ходи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'А они га запиташе: ко је тај човјек који ти рече: узми одар свој и ходи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'А исцијељени не знадијаше ко је; јер се Исус уклони, јер људства много бјеше на мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'А потом га нађе Исус у цркви и рече му: ето си здрав, више не гријеши, да ти не буде горе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'А човјек отиде и каза Јеврејима да је оно Исус који га исцијели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'И зато гоњаху Јевреји Исуса, и гледаху да га убију, јер чињаше то у суботу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'А Исус им одговараше: отац мој дослије чини, и ја чиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'И зато још више гледаху Јевреји да га убију што не само квараше суботу него и оцем својијем називаше Бога и грађаше се једнак Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'А Исус одговарајући рече им: заиста, заиста вам кажем: син не може ништа чинити сам од себе него што види да отац чини; јер што он чини оно и син чини онако;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Јер отац сина љуби, и све му показује што сам чини; и показаће му већа дјела од овијех да се ви чудите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Јер како што отац подиже мртве и оживљује, тако и син које хоће оживљује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Јер отац не суди никоме, него сав суд даде сину,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Да сви поштују сина као што оца поштују. Ко не поштује сина не поштује оца који га је послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Заиста, заиста вам кажем: ко моју ријеч слуша и вјерује ономе који је мене послао, има живот вјечни, и не долази на суд, него је прешао из смрти у живот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Заиста, заиста вам кажем: иде час и већ је настао, кад ће мртви чути глас сина Божијега, и чувши оживљети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Јер како што отац има живот у себи, тако даде и сину да има живот у себи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'И даде му власт да и суд чини, јер је син човјечиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Не дивите се овоме, јер иде час у који ће сви који су у гробовима чути глас сина Божијега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'И изићи ће који су чинили добро у васкрсеније живота, а који су чинили зло у васкрсеније суда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Ја не могу ништа чинити сам од себе; како чујем онако судим, и суд је мој праведан; јер не тражим воље своје него вољу оца који ме је послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Ако ја свједочим за себе, свједочанство моје није истинито.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Има други који свједочи за мене; и знам да је истинито свједочанство што свједочи за мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Ви посласте к Јовану, и посвједочи вам за истину;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'А ја не примам свједочанства од човјека, него ово говорим да се ви спасете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Он бјеше видјело које гораше и свијетљаше, а ви се хтјесте мало времена радовати његову свијетљењу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Али ја имам свједочанство веће од Јованова; јер послови које ми даде отац да их свршим, ови послови које ја радим свједоче за мене да ме отац посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'И отац који ме посла сам свједочи за мене. Ни гласа његова кад чусте ни лица његова видјесте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'И ријечи његове немате у себи да стоји; јер ви не вјерујете ономе кога он посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Прегледајте писма, јер ви мислите да имате у њима живот вјечни; и она свједоче за мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'И нећете да дођете к мени да имате живот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Ја не примам славе од људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Него вас познајем да љубави Божије немате у себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Ја дођох у име оца својега и не примате ме; ако други дође у име своје, њега ћете примити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Како ви можете вјеровати кад примате славу један од другога, а славе која је од јединога Бога не тражите?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Не мислите да ћу вас тужити оцу; има који вас тужи, Мојсије, у кога се ви уздате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Јер да сте вјеровали Мојсију тако бисте вјеровали и мени; јер он писа за мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'А кад његовијем писмима не вјерујете како ћете вјеровати мојијем ријечима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Потом отиде Исус преко мора мора Галилејскога код Тиверијаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'И за њим иђаше мноштво народа, јер виђаху чудеса његова која чињаше на болесницима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'А Исус изиђе на гору, и ондје сјеђаше са ученицима својијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'А бијаше близу пасха празник Јеврејски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Подигнувши дакле Исус очи, и видјевши да мноштво народа иде к њему, рече Филипу: гдје ћемо купити хљеба да ови једу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'А ово говораше кушајући га, јер сам знадијаше шта ће чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Одговори му Филип: двјеста гроша хљеба није доста да свакоме од њих помало допадне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Рече му један од ученика његовијех, Андрија, брат Симона Петра:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Овдје има једно момче које има пет хљебова јечменијех и двије рибе; али шта је то на толики свијет!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'А Исус рече: посадите људе. А бјеше траве много на ономе мјесту. Посади се дакле људи на број око пет хиљада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'А Исус узевши оне хљебове, и давши хвалу, даде ученицима, а ученици онима који бијаху посађени; тако и од риба колико хтјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'И кад се наситише, рече ученицима својијем: скупите комаде што претекоше да ништа не пропадне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'И скупише, и напунише дванаест котарица комада од пет хљебова јечменијех што претече иза онијех што су јели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'А људи видјевши чудо које учини Исус говораху: ово је заиста онај пророк који треба да дође на свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'А кад разумије Исус да хоће да дођу да га ухвате и да га учине царем, отиде опет у гору сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'А кад би увече сиђоше ученици његови на море,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'И уђоше у лађу, и пођоше преко мора у Капернаум. И већ се бијаше смркло, а Исус не бјеше дошао к њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'А море се подизаше од великога вјетра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Возивши пак око двадесет и пет или тридесет потркалишта угледаше Исуса гдје иде по мору и дошао близу до лађе, и уплашише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'А он им рече: ја сам; не бојте се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Онда га с радошћу узеше у лађу; и одмах лађа би на земљи у коју иђаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Сјутрадан пак народ који стајаше преко мора кад видје да лађе друге не бјеше ондје осим оне једне што у њу уђоше ученици његови, и да не уђе Исус с ученицима својијем у лађу него сами ученици његови отидоше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'А друге лађе из Тиверијаде дођоше близу оног мјеста гдје једоше хљеб кад Господ даде хвалу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Кад видје народ да Исуса не бјеше ондје ни ученика његовијех, уђоше и они у лађе, и дођоше у Капернаум да траже Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'И нашавши га преко мора рекоше му: Рави! кад си дошао овамо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Исус им одговори и рече: заиста, заиста вам кажем: не тражите ме што чудеса видјесте, него што једосте хљеба и наситисте се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Старајте се не за јело које пролази, него за јело које остаје за вјечни живот, које ће вас дати син човјечиј, јер овога потврди отац Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'А они му рекоше: шта ћемо чинити да радимо дјела Божија?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Одговори Исус и рече им: ово је дјело Божије да вјерујете онога кога он посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'А они му рекоше: какав дакле ти показујеш знак да видимо и да вјерујемо? шта радиш ти?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Оцеви наши једоше ману у пустињи, као што је написано: хљеб с неба даде им да једу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Тада им рече Исус: заиста, заиста вам кажем: Мојсије не даде вама хљеба с неба, него вам отац мој даје хљеб истинити с неба;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Јер је хљеб Божији онај који силази с неба и даје живот свијету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Тада му рекоше: Господе! дај нам свагда тај хљеб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'А Исус им рече: ја сам хљеб живота: који мени долази неће огладњети, и који мене вјерује неће никад ожедњети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Него вам казах да ме и видјесте и не вјерујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Све што мени даје отац к мени ће доћи; и који долази к мени нећу га истјерати напоље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Јер сиђох с неба не да чиним вољу своју, него вољу оца који ме посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'А ово је воља оца који ме посла да од онога што ми даде ништа не изгубим, него да га васкрснем у пошљедњи дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'А ово је воља онога који ме посла да сваки који види сина и вјерује га има живот вјечни; и ја ћу га васкрснути у пошљедњи дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Тада викаху Јевреји на њега што рече: ја сам хљеб који сиђе с неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'И говораху: није ли ово Исус син Јосифов којему ми знамо оца и матер? како дакле он говори: ја сиђох с неба?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Онда Исус одговори и рече им: не вичите међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Нико не може доћи к мени ако га не довуче отац који ме посла; и ја ћу га васкрснути у пошљедњи дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'У пророцима стоји написано: и биће сви научени од Бога. Сваки који чује од оца и научи, доћи ће к мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Не да је ко видио оца осим онога који је од Бога: он видје оца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Заиста, заиста вам кажем: који вјерује мене има живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Ја сам хљеб живота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Оцеви ваши једоше ману у пустињи, и помријеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Ово је хљеб који силази с неба: да који од њега једе не умре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Ја сам хљеб живи који сиђе с неба; који једе од овога хљеба живљеће вавијек; и хљеб који ћу ја дати тијело је моје, које ћу дати за живот свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'А Јевреји се препираху међу собом говорећи: како може овај дати нама тијело своје да једемо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'А Исус име рече: заиста, заиста вам кажем: ако не једете тијела сина човјечијега и не пијете крви његове, нећете имати живота у себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Који једе моје тијело и пије моју крв има живот вјечни, и ја ћу га васкрснути у пошљедњи дан:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Јер је тијело моје право јело и крв моја право пиће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Који једе моје тијело и пије моју крв стоји у мени и ја у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Као што ме посла живи отац, и ја живим оца ради; и који једе мене и он ће живљети мене ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Ово је хљеб који сиђе с неба: не као што ваши оцеви једоше ману, и помријеше; који једе хљеб овај живљеће вавијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Ово рече у зборници кад учаше у Капернауму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Тада многи од ученика његовијех који слушаху рекоше: ово је тврда бесједа! ко је може слушати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'А Исус знајући у себи да ученици његови вичу на то, рече им: зар вас ово саблажњава?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'А кад видите сина човјечијега да одлази горе гдје је прије био?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Дух је оно што оживљава; тијело не помаже ништа. Ријечи које вам ја рекох дух су и живот су.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Али имају неко међу вама који не вјерују. Јер знадијаше Исус од почетка који су што не вјерују, и ко ће га издати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'И рече: зато вам рекох да нико не може доћи к мени ако му не буде дано од оца мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Од тада многи од ученика његовијех отидоше натраг, и више не иђаху с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'А Исус рече дванаесторици: да нећете и ви отићи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Тада му одговори Симон Петар: Господе! коме ћемо ићи? Ти имаш ријечи вјечнога живота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'И ми вјеровасмо и познасмо да си ти Христос, син Бога живога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Исус им одговори: не избрах ли ја вас дванаесторицу, и један је од вас ђаво?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'А говораше за Јуду Симонова Искариота, јер га он шћаше издати, и бијаше један од дванаесторице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'И потом хођаше Исус по Галилеји; јер по Јудеји не шћадијаше да ходи, јер гледаху Јевреји да га убију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Бијаше пак близу празник Јеврејски грађење сјеница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Тада му рекоше браћа његова: изиђи одавде и иди у Јудеју, да и ученици твоји виде дјела која чиниш;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Јер нико не чини што тајно а сам тражи да је познат. Ако то чиниш јави себе свијету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Јер ни браћа његова не вјероваху га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Тада им рече Исус: вријеме моје још није дошло, а вријеме је ваше свагда готово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Не може свијет мрзити на вас: а на мене мрзи, јер ја свједочим за њ да су дјела његова зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Ви изиђите на празник овај: ја још нећу изићи на празник овај, јер се моје вријеме још није навршило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Рекавши им ово оста у Галилеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'А кад изиђоше браћа његова на празник, тада и сам изиђе, не јавно него као тајно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'А Јевреји га тражаху на празник и говораху: гдје је он?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'И бијаху за њ многе распре у народу: једни говораху да је добар, а други: није него вара народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Али нико не говораше јавно за њ од страха Јеврејскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Али одмах у половини празника изиђе Исус у цркву и учаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'И дивљаху се Јевреји говорећи: како овај зна књиге а није се учио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Тада им одговори Исус и рече: моја наука није моја, него онога које ме је послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Ко хоће његову вољу творити, разумјеће је ли ова наука од Бога или ја сам од себе говорим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Који говори сам од себе, славу своју тражи; а ко тражи славу онога који га је послао, он је истинит и у њему нема неправде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Не даде ли Мојсије вама закон и нико од вас не живи по закону? Зашто тражите да ме убијете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Одговори народ и рече: је ли ђаво у теби? ко тражи да те убије?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Одговори Исус и рече им: једно дјело учиних и сви се дивите томе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Мојсије вам даде да се обрезујете (не као да је од Мојсија него од отаца); и у суботу обрезујете човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Ако се човјек у суботу обрезује да се не поквари закон Мојсијев, срдите ли се на мене што свега човјека исцијелих у суботу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Не гледајте ко је ко кад судите, него праведан суд судите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Тада говораху неки од Јерусалимљана: није ли то онај којега траже да убију?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'И гле, како говори слободно и ништа му не веле: да не дознаше наши кнезови да је он заиста Христос?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Али овога знамо откуда је; а Христос кад дође, нико неће знати откуда је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Тада Исус повика у цркви учећи и рече: и мене познајете и знате откуда сам; и сам од себе не дођох, него има истинити који ме посла, којега ви не знате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Ја га знам, јер сам од њега и он ме посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Тада гледаху да га ухвате; и нико не метну на њ руке, јер још не бјеше дошао час његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'А од народа многи га вјероваше, и говораху: кад дође Христос еда ли ће више чудеса чинити него овај што чини?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Чуше фарисеји од народа такови говор за њега, и послаше фарисеји и главари свештенички слуге да га ухвате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Тада рече Исус: још сам мало времена с вама, па идем к ономе који ме посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Тражићете ме и нећете ме наћи; и гдје сам ја ви не можете доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'А Јевреји рекоше међу собом: куда ће овај ићи да га ми не нађемо? Неће ли ићи међу растркане Грке, и Грке учити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Шта значи ова ријеч што рече: тражићете ме и нећете ме наћи; и гдје сам ја ви не можете доћи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'А у пошљедњи велики дан празника стајаше Исус и викаше говорећи: ко је жедан нека дође к мени и пије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Који ме вјерује, као што писмо рече, из његова тијела потећи ће ријеке живе воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'А ово рече за Духа којега послије примише они који вјерују у име његово: јер Дух свети још не бјеше на њима, јер Исус још не бјеше прослављен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'А многи од народа чувши ове ријечи говораху: ово је заиста пророк.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Други говораху: ово је Христос. А једни говораху: зар ће Христос из Галилеје доћи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Не каза ли писмо да ће Христос доћи од сјемена Давидова, и из села Витлејема одакле бјеше Давид?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Тако распра постаде у народу њега ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'А неки од њих шћадијаху да га ухвате; али нико не метну руку на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Дођоше пак слуге ка главарима свештеничкијем и фарисејима; и они им рекоше: зашто га не доведосте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'А слуге одговорише: никад човјек није тако говорио као овај човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Тада им одговорише фарисеји: зар се и ви преваристе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Вјерова ли га ко од кнезова или од фарисеја?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Него народ овај, који не зна закона, проклет је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Рече им Никодим што долази к њему ноћу, који бјеше један од њих:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Еда ли закон наш суди човјеку докле га најприје не саслуша и дозна шта чини?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Одговорише му и рекоше: нијеси ли и ти из Галилеје? Разгледај и виђи да пророк из Галилеје не долази.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'И отидоше сваки својој кући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'А Исус отиде на гору Маслинску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'А ујутру опет дође у цркву, и сав народ иђаше к њему; и сједавши учаше их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'А књижевници и фарисеји доведоше к њему жену ухваћену у прељуби, и поставивши је на сриједу');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Рекоше му: учитељу! ова је жена ухваћена сад у прељуби;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'А Мојсије нам у закону заповједи да такове камењем убијамо; а ти шта велиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Ово пак рекоше кушајући га да би га имали за што окривити. А Исус саже се доље и писаше прстом по земљи (не гледајући на њих).');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'А кад га једнако питаху, исправи се и рече им: који је међу вама без гријеха нека најприје баци камен на њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Па се опет саже доље и писаше по земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'А кад они то чуше, и покарани будући од своје савјести излажаху један за другијем почевши од старјешина до пошљедњијех; и оста Исус сам и жена стојећи на сриједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'А кад се Исус исправи, и не видјевши ни једнога до саму жену, рече јој: жено! гдје су они што те тужаху? Ниједан те не осуди?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'А она рече: ниједан, Господе! А Исус јој рече: ни ја те не осуђујем, иди, и отселе више не гријеши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Исус им пак опет рече: ја сам видјело свијету: ко иде за мном неће ходити по тами, него ће имати видјело живота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Тада му рекоше фарисеји: ти сам за себе свједочиш: свједочанство твоје није истинито.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Исус одговори и рече им: ако ја свједочим сам за себе истинито је свједочанство моје: јер знам откуда дођох и куда идем; а ви не знате откуда долазим и куда идем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Ви судите по тијелу, ја не судим никоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'И ако судим ја, суд је мој прав: јер нијесам сам, него ја и отац који ме посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'А и у закону вашему стоји написано да је свједочанство двојице људи истинито.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Ја сам који свједочим сам за себе, и свједочи за мене отац који ме посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Тада му говораху: гдје је отац твој? Исус одговори: ни мене знате ни оца мојега; кад бисте знали мене, знали бисте и оца мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Ове ријечи рече Исус код хазне Божије кад учаше у цркви; и нико га не ухвати, јер још не бјеше дошао час његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'А Исус им опет рече: ја идем, и тражићете ме; и помријећете у својему гријеху; куд ја идем ви не можете доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Тада рекоше Јевреји: да се неће сам убити, што говори: куд ја идем ви не можете доћи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'И рече им: ви сте од нижијех, ја сам од вишијех; ви сте од овога свијета, ја нијесам од овога свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Тако вам казах да ћете помријети у гријесима својима; јер ако не узвјерујете да сам ја, помријећете у гријесима својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Тада му говораху: ко си ти? И рече им Исус: почетак, како вам и кажем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Много имам за вас говорити и судити; али онај који ме посла истинит је, и ја оно говорим свијету што чух од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Не разумјеше дакле да им говораше за оца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'А Исус им рече: кад подигнете сина човјечијега, онда ћете дознати да сам ја, и да ништа сам од себе не чиним; него како ме научи отац мој онако говорим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'И онај који ме посла са мном је. Не остави отац мене сама; јер ја свагда чиним што је њему угодно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Кад ово говораше, многи га вјероваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Тада Исус говораше онијем Јеврејима који му вјероваше: ако ви останете на мојој бесједи, заиста ћете бити ученици моји,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'И познаћете истину, и истина ће вас избавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Одговорише и рекоше му: ми смо сјеме Авраамово, и никоме нијесмо робовали никад; како ти говориш да ћемо се избавити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Исус им одговори: заиста, заиста вам кажем да је сваки који чини гријех роб гријеху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'А роб не остаје у кући вавијек, син остаје вавијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Ако вас дакле син избави, заиста ћете бити избављени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Знам да сте сјеме Авраамово; али гледате да ме убијете, јер моја бесједа не може у вас да стане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Ја говорим што видјех од оца својега; и ви тако чините што видјесте од оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Одговорише и рекоше му: отац је наш Авраам. Исус им рече: кад бисте ви били дјеца Авраамова, чинили бисте дјела Авраамова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'А сад гледате мене да убијете, човјека који вам истину казах коју чух од Бога: тако Авраам није чинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Ви чините дјела оца својега. Тада му рекоше: ми нијесмо рођени од курварства: једнога оца имамо Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'А Исус им рече: кад би Бог био ваш отац, љубили бисте мене; јер ја од Бога изиђох и дођох; јер не дођох сам од себе, него ме он посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Зашто не разумијете говора мојега? Јер не можете ријечи мојијех да слушате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Ваш је отац ђаво; и сласти оца својега хоћете да чините: он је крвник људски од почетка, и не стоји на истини; јер нема истине у њему; кад говори лаж, своје говори: јер је лажа и отац лажи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'А мени не вјерујете, јер ја истину говорим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Који ме од вас кори за гријех? Ако ли истину говорим, зашто ми ви не вјерујете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Ко је од Бога ријечи Божије слуша; зато ви не слушате, јер нијесте од Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Тада одговорише Јевреји и рекоше му: не говоримо ли ми право да си ти Самарјанин, и да је ђаво у теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Исус одговори: у мени ђавола нема, него поштујем оца својега; а ви мене срамотите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'А ја не тражим славе своје; има који тражи и суди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Заиста, заиста вам кажем: ко одржи ријеч моју неће видјети смрти довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Тада му рекоше Јевреји: сад видјесмо да је ђаво у теби: Авраам умрије и пророци, а ти говориш: ко одржи ријеч моју неће окусити смрти довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Еда ли си ти већи од оца нашега Авраама, који умрије? И пророци помријеше: ко се ти сам градиш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Исус одговори: ако се ја сам славим, слава је моја ништа: отац је мој који ме слави, за којега ви говорите да је ваш Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'И не познајете га, а ја га знам; и ако речем да га не знам бићу лажа као ви. Него га знам, и ријеч његову држим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Авраам, отац ваш, био је рад да види дан мој; и видје, и обрадова се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Тада му рекоше Јевреји: још ти нема педесет година, и Авраама ли си видио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'А Исус им рече: заиста, заиста вам кажем: ја сам прије него се Авраам родио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Тада узеше камење да баце на њ; а Исус се сакри, и изиђе из цркве прошавши између њих и отиде тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'И пролазећи видје човјека слијепа од рођења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'И запиташе га ученици његови говорећи: Рави! ко сагријеши, или овај или родитељи његови, те се роди слијеп?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Исус одговори: ни он сагријеши ни родитељи његови, него да се јаве дјела Божија на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Мени ваља радити дјела онога који ме посла док је дан: доћи ће ноћ кад нико не може радити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Док сам на свијету видјело сам свијету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Рекавши ово пљуну на земљу и начини као од пљуванке, и помаза калом очи слијепоме,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'И рече: иди умиј се у бањи Силоамској (које значи послан). Отиде дакле и уми се, и дође гледајући.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'А сусједи и који га бијаху видјели прије да бјеше слијеп говораху: није ли ово онај што сјеђаше и прошаше?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Једни говораху: он је; а други: налик је на њ. А он говораше: ја сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Тада му говораху: како ти се отворише очи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Он одговори и рече: човјек који се зове Исус начини као, и помаза очи моје, и рече ми: иди у бању Силоамску и умиј се. А кад отидох и умих се, прогледах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Тада му рекоше: гдје је он? Рече: не знам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Тада га поведоше к фарисејима, онога што бјеше некад слијеп.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'А бјеше субота кад начини Исус као и отвори му очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Тада га опет питаху фарисеји како прогледа. А он им рече: као метну ми на очи, и умих се, и видим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Тада говораху неки од фарисеја: није овај човјек од Бога, јер не светкује суботе. Други говораху: како може човјек грјешан такова чудеса чинити? И поста распра међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Рекоше дакле опет слијепцу: шта велиш ти за њега што ти отвори очи твоје? А он рече: пророк је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Тада Јевреји не вјероваше за њега да бјеше слијеп и прогледа, док не дозваше родитеље онога што је прогледао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'И запиташе их говорећи: је ли ово ваш син за кога ви говорите да се роди слијеп? како дакле сад види?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'А родитељи његови одговорише им и рекоше: знамо да је ово син наш и да се роди слијеп;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'А како сад види не знамо; или ко му отвори очи ми не знамо; он је велики, питајте њега нека сам каже за себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Ово рекоше родитељи његови, јер се бојаху Јевреја; јер се Јевреји бијаху договорили да буде одлучен од зборнице ко га призна за Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Зато рекоше родитељи његови: он је велики, питајте њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Тада по други пут дозваше човјека који је био слијеп, и рекоше му: подај Богу славу; ми знамо да је човјек онај грјешан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'А он одговори и рече: је ли грјешан не знам; само знам да ја бијах слијеп, а сад видим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Тада му опет рекоше: шта ти учини? како отвори очи твоје?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Одговори им: ја вам већ казах, и не слушасте; шта ћете опет слушати? Већ ако и ви хоћете ученици његови да будете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'А они га укорише, и рекоше му: ти си ученик његов, а ми смо ученици Мојсијеви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Ми знамо да с Мојсијем говори Бог; а овога не знамо откуда је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Човјек одговори и рече им: то и јест за чудо, што ви не знате откуда је а он отвори очи моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'А знамо да Бог не слуша грјешника; него ако ко поштује Бога и вољу његову твори, онога слуша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Откако је свијета није чувено да ко отвори очи рођеном слијепцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Кад он не би био од Бога не би могао ништа чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Одговорише и рекоше му: ти си се родио сав у гријесима, па зар ти да нас учиш? И истјераше га напоље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Чу Исус да га истјераше напоље; и нашавши га рече му: вјерујеш ли ти сина Божијега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Он одговори и рече: а ко је, Господе, да га вјерујем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'А Исус му рече: и видио си га, и који говори с тобом он је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'А он рече: вјерујем, Господе! И поклони му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'И рече Исус: ја дођох на суд на овај свијет, да виде који не виде, и који виде да постану слијепи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'И чуше ово неки од фарисеја који бијаху с њим, и рекоше му: еда ли смо и ми слијепи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Рече им Исус: кад бисте били слијепи, не бисте имали гријеха, а сад говорите да видите, тако ваш гријех остаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Заиста, заиста вам кажем: ко не улази на врата у тор овчиј него прелази на другом мјесту он је лупеж и хајдук;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'А који улази на врата јест пастир овцама:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Њему вратар отвора, и овце глас његов слушају, и своје овце зове по имену, и изгони их;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'И кад своје овце истјера, иде пред њима, и овце иду за њим, јер познају глас његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'А за туђином неће да иду, него бјеже од њега, јер не познају гласа туђега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Ову причу каза им Исус, али они не разумјеше шта то бијаше што им каза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Тада им рече Исус опет: заиста, заиста вам кажем: ја сам врата к овцама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Сви колико их год дође прије мене лупежи су и хајдуци; али их овце не послушаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Ја сам врата; ко уђе кроза ме спашће се, и ући ће и изићи ће, и пашу ће наћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Лупеж не долази ни за што друго него да украде и убије и погуби; ја дођох да имају живот и изобиље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Ја сам пастир добри; пастир добри душу своју полаже за овце,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'А најамник, који није пастир, коме нијесу овце своје, види вука гдје иде, и оставља овце, и бјежи: и вук зграби овце и распуди их;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'А најамник бјежи, јер је најамник и не мари за овце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Ја сам пастир добри и знам своје, и моје мене знају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Као што мене зна отац и ја знам оца; и душу своју полажем за овце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'И друге овце имам које нијесу из овога тора, и оне ми ваља довести; и чуће глас мој, и биће једно стадо и један пастир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Зато ме отац љуби, јер ја душу своју полажем да је опет узмем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Нико је не отима од мене, него је ја сам од себе полажем. Власт имам положити је и власт имам узети је опет. Ову сам заповијест примио од оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Тада опет поста распра међу Јеврејима за ове ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Многи од њих говораху: у њему је ђаво, и полудио је; шта га слушате?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Други говораху: ове ријечи нијесу лудога; зар може ђаво слијепима очи отворати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'А бијаше тада празник обновљења у Јерусалиму, и бјеше зима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'И ходаше Исус у цркви по тријему Соломунову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'А Јевреји га опколише, и говораху му: докле ћеш мучити душе наше? ако си ти Христос, кажи нам слободно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Исус им одговори: ја вам казах, па не вјерујете. Дјела која творим ја у име оца својега она свједоче за ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Али ви не вјерујете; јер нијесте од мојијех оваца, као што вам казах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Овце моје слушају глас мој, и ја познајем њих, и за мном иду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'И ја ћу им дати живот вјечни, и никад неће изгинути, и нико их неће отети из руке моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Отац мој који ми их даде већи је од свију; и нико их не може отети из руке оца мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Ја и отац једно смо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'А Јевреји опет узеше камење да га убију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Исус им одговори: многа вам добра дјела јавих од оца својега; за које од онијех дјела бацате камење на ме?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Одговорише му Јевреји говорећи: за добро дјело не бацамо камење на те, него за хулу на Бога, што ти, човјек будући, градиш се Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Исус им одговори: не стоји ли написано у закону вашему: ја рекох: богови сте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Ако оне назва боговима којима ријеч Божија би, и писмо се не може покварити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'Како ви говорите ономе којега отац посвети и посла на свијет: хулу на Бога говориш, што рекох: ја сам син Божиј?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Ако не творим дјела оца својега не вјерујте ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Ако ли творим, ако мени и не вјерујете, дјелима мојима вјерујте, да познате и вјерујете да је отац у мени и ја у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Тада опет гледаху да га ухвате; али им се измаче из руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'И отиде опет преко Јордана на оно мјесто гдје Јован прије кршћаваше; и оста ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'И многи дођоше к њему и говораху: Јован не учини ниједнога чуда, али све што каза Јован за овога истина бјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'И многи вјероваше га ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Бијаше пак један болесник, Лазар из Витаније из села Марије и Марте сестре њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, '(А Марија, које брат Лазар боловаше, бјеше она што помаза Господа миром и отр ноге његове својом косом.)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Онда послаше сестре к њему говорећи: Господе! гле, онај који ти је мио болестан је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'А кад чу Исус, рече: ова болест није на смрт, него на славу Божију, да се прослави син Божиј с ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'А Исус љубљаше Марту и сестру њезину и Лазара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'А кад чу да је болестан, тада оста два дана на оном мјесту гдје бјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'А потом рече ученицима: хајдемо опет у Јудеју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Ученици му рекоше: Рави! сад Јудејци шћадијаху да те убију камењем, па опет хоћеш да идеш онамо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Исус одговори: није ли дванаест сахата у дану? ко дању иде не спотиче се, јер види видјело овога свијета;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'А ко иде ноћу спотиче се, јер нема видјела у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Ово каза, и потом им рече: Лазар, наш пријатељ, заспа; него идем да га пробудим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Онда му рекоше ученици његови: Господе! ако је заспао, устаће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'А Исус им рече за смрт његову а они мишљаху да говори за спавање сна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Тада им Исус каза управо: Лазар умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'И мило ми је вас ради што нијесам био онамо да вјерујете; него хајдемо к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Онда Тома, који се зваше Близанац, рече ученицима: хајдемо и ми да помремо с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'А кад дође Исус, нађе га а он већ четири дана у гробу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, '(А Витанија бјеше близу Јерусалима око петнаест потркалишта.)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'И многи од Јудејаца бијаху дошли к Марти и Марији да их тјеше за братом њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Кад Марта дакле чу да Исус иде, изађе преда њ, а Марија сјеђаше дома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Онда рече Марта Исусу: Господе! да си ти био овдје не би мој брат умро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'А и сад знам да што заиштеш у Бога даће ти Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Исус јој рече: брат ће твој устати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Марта му рече: знам да ће устати о васкрсенију, у пошљедњи дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'А Исус јој рече: ја сам васкрсеније и живот; који вјерује мене ако и умре живљеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'И ниједан који живи и вјерује мене неће умријети вавијек. Вјерујеш ли ово?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Рече му: да, Господе! ја вјеровах да си ти Христос син Божиј који је требало да дође на свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'И ово рекавши отиде те зовну тајно Марију сестру своју говорећи: учитељ је дошао, и зове те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'А она кад чу, уста брзо и отиде к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Јер Исус још не бјеше дошао у село, него бијаше на оном мјесту гдје га срете Марта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'А Јудејци онда који бијаху с њом у кући и тјешаху је, кад видјеше Марију да брзо уста и изиђе, пођоше за њом говорећи да иде на гроб да плаче онамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'А Марија како дође гдје бјеше Исус, и видје га, паде на ноге његове говорећи му: Господе! да си ти био овдје, не би умро мој брат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Онда Исус кад је видје гдје плаче, и гдје плачу Јудејци који дођоше с њом, згрози се у духу, и сам постаде жалостан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'И рече: гдје сте га метнули? Рекоше му: Господе! хајде да видиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Ударише сузе Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Онда Јудејци говораху: гледај како га љубљаше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'А неки од њих рекоше: не могаше ли овај који отвори очи слијепцу учинити да и овај не умре?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'А Исус опет се згрози у себи, и дође на гроб; а бијаше пећина, и камен лежаше на њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Исус рече: узмите камен. Рече му Марта, сестра онога што је умро: Господе! већ смрди; јер су четири дана како је умро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Исус јој рече: не рекох ли ти да ако вјерујеш видјећеш славу Божију?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Узеше дакле камен гдје лежаше мртвац; а Исус подиже очи горе, и рече: оче! хвала ти што си ме услишио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'А ја знадох да ме свагда слушаш; него рекох народа ради који овдје стоји, да вјерују да си ме ти послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'И ово рекавши зовну иза гласа: Лазаре! изиђи напоље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'И изиђе мртвац обавит платном по рукама и по ногама, и лице његово убрусом повезано. Исус им рече: раздријешите га и пустите нек иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Онда многи од Јудејаца који бијаху дошли к Марији и видјеше шта учини Исус, вјероваше га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'А неки од њих отидоше к фарисејима и казаше им шта учини Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Онда главари свештенички и фарисеји сабраше скупштину, и говораху: шта ћемо чинити? Човјек овај чини многа чудеса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Ако га оставимо тако, сви ће га вјеровати; па ће доћи Римљани и узети нам земљу и народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'А један од њих, по имену Кајафа, који оне године бјеше поглавар свештенички, рече им: ви не знате ништа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'И не мислите да је нама боље да један човјек умре за народ, неголи да народ сав пропадне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'А ово не рече сам од себе, него, будући поглавар свештенички оне године, прорече да Исусу ваља умријети за народ;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'И не само за народ, него да и расијану дјецу Божију скупи уједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Од тога дакле дана договорише се да га убију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'А Исус више не хођаше јавно по Јудејцима, него оданде отиде у крај близу пустиње у град по имену Јефрем, и ондје хођаше с ученицима својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'А бјеше близу пасха Јеврејска, и многи из онога краја дођоше у Јерусалим прије пасхе да се очисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Тада тражаху Исуса, и стојећи у цркви говораху међу собом: шта мислите ви зашто не долази на празник?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'А главари свештенички и фарисеји издаше заповијест ако га ко опази гдје је, да јави да га ухвате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'А Исус прије пасхе на шест дана дође у Витанију гдје бјеше Лазар што умрије, кога подиже из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Ондје му пак зготовише вечеру, и Марта служаше, а и Лазар сјеђаше с њим за трпезом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'А Марија узевши литру правога нардова многоцјенога мира помаза ноге Исусове, и отр косом својом ноге његове; а кућа се напуни мириса од мира.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Онда рече један од ученика његовијех, Јуда Симонов Искариотски, који га послије издаде:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Зашто се ово миро не продаде за триста гроша и не даде сиромасима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'А ово не рече што се стараше за сиромахе, него што бјеше лупеж, и имаше ковчежић, и ношаше што се меташе у њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'А Исус рече: не дирајте у њу; она је то дохранила за дан мојега погреба;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Јер сиромахе свагда имате са собом, а мене немате свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Разумје пак многи народ из Јудеје да је ондје и дођоше не само Исуса ради него и да виде Лазара којега подиже из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'А главари свештенички договорише се да и Лазара убију;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Јер многи њега ради иђаху из Јудеје и вјероваху Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'А сјутрадан многи од народа који бјеше дошао на празник, чувши да Исус иде у Јерусалим');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Узеше гране од финика и изиђоше му на сусрет, и викаху говорећи: осана! благословен који иде у име Господње, цар Израиљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'А Исус нашавши магаре усједе на њ, као што је писано:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Не бој се кћери Сионова, ево цар твој иде сједећи на магарету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Али ово ученици његови не разумјеше прије: него кад се прослави Исус онда се опоменуше да ово бјеше за њега писано, и ово му учинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'А народ свједочаше који бјеше прије с њим кад Лазара изазва из гроба и подиже га из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Зато га и срете народ, јер чуше да он учини ово чудо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'А фарисеји говораху међу собом: видите да ништа не помаже? гле, свијет иде за њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'А бијаху неки Грци који бијаху дошли на празник да се моле Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Они дакле приступише к Филипу, који бјеше из Витсаиде Галилејске, и мољаху га говорећи: господине! ми бисмо хтјели да видимо Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Дође Филип и каза Андрији, а Андрија и Филип опет казаше Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'А Исус одговори им говорећи: дође час да се прослави син човјечиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Заиста, заиста вам кажем: ако зрно пшенично паднувши на земљу не умре, оно једно остане; ако ли умре много рода роди:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Који љуби душу своју изгубиће је, а ко мрзи на душу своју на овом свијету, сачуваће је за живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Ко мени служи, за мном нек иде, и гдје сам ја ондје и слуга мој нек буде; и ко мени служи онога ће поштовати отац мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Сад је душа моја жалосна; и шта да кажем? Оче! сачувај ме од овога часа; али зато дођох на час овај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Оче! прослави име своје! Тада глас дође с неба: и прославио сам и опет ћу прославити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'А кад чу народ који стајаше, говораху: гром загрми; а други говораху: анђео му говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Исус одговори и рече: овај глас не би мене ради него народа ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Сад је суд овоме свијету; сад ће бити истјеран кнез овога свијета напоље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'И кад ја будем подигнут од земље, све ћу привући к себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'А ово говораше да покаже каквом ће смрти умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Народ му одговори: ми чусмо из закона да ће Христос остати вавијек; како ти говориш да се сину човјечијему ваља подигнути? ко је тај син човјечији?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'А Исус им рече: још је мало времена видјело с вама; ходите док видјело имате да вас тама не обузме; јер ко ходи по тами не зна куда иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Док видјело имате вјерујте видјело, да будете синови видјела. Рекавши ово Исус отиде и сакри се од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Ако је и чинио толика чудеса пред њима, опет га не вјероваху;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'Да се збуде ријеч Исаије пророка који рече: Господе! ко вјерова говорењу нашему? и рука Господња коме се откри?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Зато не могаху вјеровати, јер опет рече Исаија:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Заслијепио је очи њихове и окаменио срца њихова, да не виде очима ни срцем разумију, и не обрате се да их исцијелим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Ово рече Исаија кад видје славу његову и говори за њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Али опет и од кнезова многи га вјероваше; него ради фарисеја не признаваху, да не би били изгнани из зборнице;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Јер им већма омиље слава људска него слава Божија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'А Исус повика и рече: ко мене вјерује не вјерује мене, него онога који ме посла;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'И ко види мене види онога који ме посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Ја дођох видјело на свијет, да ниједан који ме вјерује не остане у тами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'И ко чује моје ријечи и не вјерује, ја му нећу судити; јер ја не дођох да судим свијету, него да спасем свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Који се одрече мене, и не прима ријечи мојијех, има себи судију: ријеч коју ја говорих она ће му судити у пошљедњи дан;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Јер ја од себе не говорих, него отац који ме посла он ми даде заповијест шта ћу казати и шта ћу говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'И знам да је заповијест његова живот вјечни. Што ја дакле говорим онако говорим као што ми рече отац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'А пред празник пасхе знајући Исус да му дође час да пријеђе из овога свијета к оцу, како је љубио своје који бијаху на свијету, до краја их љуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'И по вечери кад већ ђаво бјеше метнуо у срце Јуди Симонову Искариотскоме да га изда,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Знајући Исус да му све отац даде у руке, и да од Бога изиђе, и к Богу иде,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Устаде од вечере, и скиде своје хаљине, и узе убрус те се запреже;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Потом усу воду у умиваоницу, и поче прати ноге ученицима и отирати убрусом којијем бјеше запрегнут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Онда дође к Симону Петру, и он му рече: Господе! зар ти моје ноге да опереш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Исус одговори и рече му: што ја чиним ти сад не знаш, али ћеш послије дознати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Рече му Петар: никад ти нећеш опрати мојијех ногу. Исус му одговори: ако те не оперем немаш дијела са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Рече му Симон Петар: Господе! не само ноге моје, него и руке и главу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Исус му рече: опраноме не треба до само ноге опрати, јер је сав чист; и ви сте чисти, али не сви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Јер знадијаше издајника својега, зато рече: нијесте сви чисти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'А кад им опра ноге, узе хаљине своје, и сједавши опет за трпезу рече им: знате ли што ја учиних вама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Ви зовете мене учитељем и Господом; и право велите: јер јесам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Кад дакле ја опрах вама ноге Господ и учитељ, и ви сте дужни један другоме прати ноге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Јер ја вам дадох углед да и ви тако чините као што ја вама учиних.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Заиста, заиста вам кажем: није слуга већи од господара својега, нити је посланик већи од онога који га је послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Кад ово знате, благо вама ако га извршујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Не говорим за све вас, јер ја знам које избрах; него да се збуде писмо: који са мном хљеб једе подиже пету своју на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Сад вам кажем прије него се збуде, да, кад се збуде, вјерујете да сам ја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Заиста, заиста вам кажем: који прима онога кога пошљем мене прима; а ко прима мене, прима онога који ме посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Рекавши ово Исус поста жалостан у духу, и посвједочи и рече: заиста, заиста вам кажем: један између вас издаће ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Онда се ученици згледаху међу собом, и чуђаху се за кога говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'А један од ученика његовијех, којега Исус љубљаше, сјеђаше за трпезом на крилу Исусову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Онда намаже на њега Симон Петар да запита ко би то био за кога говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'А он рече на прси Исусове и рече му: Господе! ко је то?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Исус одговори: онај је коме ја умочивши залогај дам. И умочивши залогај даде Јуди Симонову Искариотскоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'И по залогају тада уђе у њега сотона. Онда му рече Исус: шта чиниш чини брже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'А ово не разумје нико од онијех што сјеђаху за трпезом зашто му рече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'А неки мишљаху, будући да у Јуде бјеше кеса, да му Исус рече: купи што треба за празник; или да да што сиромашнима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'А он узевши залогај одмах изиђе; а бјеше ноћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Кад он изиђе, онда Исус рече: сад се прослави син човјечији и Бог се прослави у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Ако се Бог прослави у њему, и Бог ће њега прославити у себи, и одмах ће га прославити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Дјечице! још сам мало с вама; тражићете ме, и као што рекох Јудејцима: куда ја идем ви не можете доћи, и вама говорим сад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Нову вам заповијест дајем да љубите један другога, као што ја вас љубих, да се и ви љубите међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'По том ће сви познати да сте моји ученици ако узимате љубав међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Рече му Симон Петар: Господе! куда идеш? Исус му одговори: куда ја идем не можеш сад ићи за мном, али ћеш послије поћи за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Петар му рече: Господе! зашто сад не могу ићи за тобом? душу ћу своју положити за те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Одговори му Исус: душу ли ћеш своју положити за ме? Заиста, заиста ти кажем: неће пијетао запјевати док ме се трипут не одречеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Да се не плаши срце ваше, вјерујте Бога, и мене вјерујте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'Многи су станови у кући оца мојега. А да није тако, казао бих вам; идем да вам приправим мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'И кад отидем и приправим вам мјесто, опет ћу доћи, и узећу вас к себи да и ви будете гдје сам ја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'И куда ја идем знате, и пут знате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Рече му Тома: Господе! не знамо куда идеш; и како можемо пут знати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Исус му рече: ја сам пут и истина и живот; нико неће доћи к оцу до кроза ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Ка бисте мене знали онда бисте знали и оца мојега; и отселе познајете га, и видјесте га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Рече му Филип: Господе! покажи нам оца и биће нам доста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Исус му рече: толико сам вријеме с вама и нијеси ме познао, Филипе? који видје мене, видје оца; па како ти говориш: покажи нам оца?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Зар не вјерујеш да сам ја у оцу и отац у мени? Ријечи које вам ја говорим не говорим од себе; него отац који стоји у мени он твори дјела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Вјерујте мени да сам ја у оцу и отац у мени; ако ли мени не вјерујете, вјерујте ми по тијем дјелима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Заиста, заиста вам кажем: који вјерује мене, дјела која ја творим и он ће творити, и већа ће од овијех творити; јер ја идем к оцу својему;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'И шта год заиштете у оца у име моје, оно ћу вам учинити, да се прослави отац у сину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'И ако што заиштете у име моје, ја ћу учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Ако имате љубав к мени, заповијести моје држите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'И ја ћу умолити оца, и даће вам другога утјешитеља да буде с вама вавијек:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Духа истине, којега свијет не може примити, јер га не види нити га познаје; а ви га познајете, јер у вама стоји, и у вама ће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Нећу вас оставити сиротне; доћи ћу к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Још мало и свијет мене више неће видјети; а ви ћете ме видјети; јер ја живим, и ви ћете живљети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'У онај ћете ви дан дознати да сам ја у оцу својему, и ви у мени, и ја у вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Ко има заповијести моје и држи их он је онај што има љубав к мени; а који има љубав к мени имаће к њему љубав отац мој; и ја ћу имати љубав к њему, и јавићу му се сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'И рече му Јуда, не Искариотски: Господе! шта је то да ћеш се нама јавити а не свијету?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Исус одговори и рече му: ко има љубав к мени, држаће ријеч моју; и отац мој имаће љубав к њему: и к њему ћемо доћи, и у њега ћемо се станити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Који нема љубави к мени не држи мојијех ријечи; а ријеч што чујете није моја него оца који ме посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Ово вам казах док сам с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'А утјешитељ Дух свети, којега ће отац послати у име моје, он ће вас научити свему и напоменуће вам све што вам рекох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Мир вам остављам, мир свој дајем вам: не дајем вам га као што свијет даје, да се не плаши срце ваше и да се не боји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Чусте да вам ја казах: идем и доћи ћу к вама. Кад бисте имали љубав к мени, онда бисте се обрадовали што рекох: идем к оцу; јер је отац мој већи од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'И сад вам казах, прије док се није збило, да вјерујете кад се збуде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Већ нећу много говорити с вама; јер иде кнез овога свијета, и у мени нема ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Него да види свијет да имам љубав к оцу, и као што ми заповједи отац онако творим. Устаните, хајдемо одавде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Ја сам прави чокот, и отац је мој виноградар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Сваку лозу на мени која не рађа рода отсјећи ће је; и сваку која рађа род очистиће је да више рода роди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Ви сте већ очишћени ријечју коју вам говорих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Будите у мени и ја ћу у вама. Као што лоза не може рода родити сама од себе ако не буде на чокоту, тако и ви ако на мени не будете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Ја сам чокот а ви лозе: и који буде у мени и ја у њему он ће родити многи род; јер без мене не можете чинити ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Ко у мени не остане избациће се напоље као лоза, и осушиће се, и скупиће је, и у огањ бацити, и спалити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Ако останете у мени и ријечи моје у вама остану, шта год хоћете иштите, и биће вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Тијем ће се отац мој прославити, да род многи родите; и бићете моји ученици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Као што отац има љубав к мени, и ја имам љубав к вама; будите у љубави мојој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Ако заповијести моје уздижете остаћете у љубави мојој, као што ја одржах заповијести оца својега и остајем у љубави његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Ово вам казах, да радост моја у вама остане и радост ваша се испуни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Ово је заповијест моја да имате љубав међу собом, као што ја имадох љубав к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Од ове љубави нико веће нема, да ко душу своју положи за пријатеље своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Ви сте пријатељи моји ако творите што вам ја заповиједам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Више вас не називам слугама; јер слуга не зна шта ради господар његов: него вас назвах пријатељима; јер вам све казах што чух од оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ви мене не избрасте, него ја вас избрах, и поставих вас да ви идете и род родите; и да ваш род остане, да што год заиштете у оца у име моје да вам да.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Ово вам заповиједам да имате љубав међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Ако свијет на вас узмрзи, знајте да на мене омрзну прије вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Кад бисте били од свијета, онда би свијет своје љубио: а како нијесте од свијета, него вас ја од свијета избрах, зато мрзи на вас свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Опомињите се ријечи коју вам ја рекох: није слуга већи од господара својега. Ако мене изгнаше, и вас ће изгнати; ако моју ријеч одржаше, и вашу ће одржати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Али све ће вам ово чинити за име моје, јер не познају онога који ме посла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Да нијесам био дошао и говорио им не би гријеха имали; а сад изговора неће имати за гријех свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Који мрзи на мене и на оца мојега мрзи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Да нијесам био дјела творио међу њима којијех нико други не твори, не би гријеха имали: а сад и видјеше, и омрзнуше на мене и на оца мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Али да се збуде ријеч написана у закону њиховом: омрзнуше на ме ни за што.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'А кад дође утјешитељ, кога ћу вам послати од оца, Дух истине, који од оца излази, он ће свједочити за мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'А и ви ћете свједочити, јер сте од почетка са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Ово вам казах да се не саблазните.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Изгониће вас из зборница; а доћи ће вријеме кад ће сваки који вас убије мислити да Богу службу чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'И ово ће чинити, јер не познаше оца ни мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Него вам ово казах кад дође вријеме да се опоменете овога да вам ја казах; а испрва не казах вам ово, јер бијах с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'А сад идем к ономе који ме посла, и нико ме од вас не пита: куда идеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Него што вам ово казах жалости напуни се срце ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Него вам ја истину говорим: боље је за вас да ја идем: јер ако ја не идем, утјешитељ неће доћи к вама; ако ли идем, послаћу га к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'И кад он дође покараће свијет за гријех, и за правду, и за суд:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'За гријех дакле што не вјерују мене;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'А за правду што идем к оцу својему; и више ме нећете видјети;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'А за суд што је кнез овога свијета осуђен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Још вам много имам казати; али сад не можете носити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'А кад дође он, Дух истине, упутиће вас на сваку истину; јер неће од себе говорити, него ће говорити што чује, и јавиће вам што ће бити унапредак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Он ће ме прославити, јер ће од мојега узети, и јавиће вам:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Све што има отац моје је: зато рекох да ће од мојега узети, и јавити вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Још мало, и нећете ме видјети, и опет мало, па ћете ме видјети: јер идем к оцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'А неки од ученика његовијех рекоше међу собом: шта је то што нам каже: још мало, и нећете ме видјети; и опет мало па ћете ме видјети; и: ја идем к оцу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Говораху дакле: шта је то што говори: мало? не знамо шта говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'А Исус разумје да шћадијаху да га запитају, па им рече: зато ли се запитујете међу собом што рекох: још мало и нећете ме видјети, и опет мало па ћете ме видјети?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Заиста, заиста вам кажем да ћете ви заплакати и заридати, а свијет ће се радовати; и ви ћете жалосни бити, али ће се ваша жалост окренути на радост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Жена кад рађа трпи муку; јер дође час њезин: али кад роди дијете, више се не опомиње жалости од радости, јер се роди човјек на свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Тако и ви дакле имате сад жалост; али ћу вас опет видјети, и радоваће се срце ваше, и ваше радости неће нико узети од вас;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'И у онај дан нећете ме питати ни за што. Заиста, заиста вам кажем да што год узиштете у оца у име моје, даће вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Дослије не искасте ништа у име моје; иштите и примићете, да радост ваша буде испуњена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Ово вам говорих у причама; али ће доћи вријеме кад вам више нећу говорити у причама, него ћу вам управо јавити за оца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'У онај ћете дан у име моје заискати, и не велим вам да ћу ја умолити оца за вас;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Јер сам отац има љубав к вама као што ви имасте љубав к мени, и вјеровасте да ја од Бога изиђох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Изиђох од оца, и дођох на свијет; и опет остављам свијет, и идем к оцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Рекоше му ученици његови: ето сад управо говориш, а приче никакве не говориш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Сад знамо да све знаш, и не треба ти да те ко пита. По томе вјерујемо да си од Бога изишао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Исус им одговори: зар сад вјерујете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Ево иде час, и већ је настао, да се разбјегнете сваки на своју страну и мене сама оставите; али нијесам сам, јер је отац са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Ово вам казах, да у мени мир имате. У свијету ћете имати невољу; али не бојте се, јер ја надвладах свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Ово говори Исус, па подиже очи своје на небо и рече: оче! дође час, прослави сина својега, да и син твој прослави тебе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Као што си му дао власт над свакијем тијелом да свему што си му дао да живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'А ово је живот вјечни да познају тебе јединога истинога Бога, и кога си послао Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Ја тебе прославих на земљи; посао сврших који си ми дао да радим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'И сад прослави ти мене, оче, у тебе самога славом коју имадох у тебе прије него свијет постаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Ја јавих име твоје људима које си ми дао од свијета; твоји бијаху па си их мени дао, и твоју ријеч одржаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Сад разумјеше да је све што си ми дао од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Јер ријечи које си дао мени дадох им; и они примише, и познадоше истинито да од тебе изиђох, и вјероваше да си ме ти послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Ја се за њих молим: не молим се за (сав) свијет, него за оне које си ми дао, јер су твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'И моје све је твоје, и твоје моје; и ја се прославих у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'И више нијесам на свијету, а они су на свијету, а ја идем к теби. Оче свети! сачувај их у име своје, оне које си ми дао, да буду једно као и ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Док бијах с њима на свијету, ја их чувах у име твоје; оне које си ми дао сачувах, и нико од њих не погибе осим сина погибли, да се збуде писмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'А сад к теби идем, и ово говорим на свијету, да имају радост моју испуњену у себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Ја им дадох ријеч твоју; и свијет омрзну на њих, јер нијесу од свијета, као и ја што нијесам од свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Не молим те да их узмеш са свијета, него да их сачуваш ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Од свијета нијесу, као ни ја што нијесам од свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Освети их истином својом: ријеч је твоја истина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Као што си ти мене послао у свијет, и ја њих послах у свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Ја посвећујем себе за њих, да и они буду освећени истином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Не молим се пак само за њих, него и за оне који ме узвјерују њихове ријечи ради;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'Да сви једно буду, као ти, оче, што си у мени и ја у теби; да и они у нама једно буду, да и свијет вјерује да си ме ти послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'И славу коју си ми дао ја дадох њима, да буду једно као ми што смо једно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Ја у њима и ти у мени: да буду сасвијем уједно, и да позна свијет да си ме ти послао и да си имао љубав к њима као и к мени што си љубав имао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Оче! хоћу да и они које си ми дао буду са мном гдје сам ја; да виде славу моју коју си ми дао, јер си имао љубав к мени прије постања свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Оче праведни! свијет тебе не позна, а ја те познах, и ови познаше да си ме ти послао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'И показах им име твоје, и показаћу: да љубав којом си мене љубио у њима буде, и ја у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'И рекавши ово Исус изиђе с ученицима својијем преко потока Кедрона гдје бјеше врт, у који уђе он и ученици његови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'А Јуда издајник његов знадијаше оно мјесто; јер се Исус често скупљаше ондје с ученицима својијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Онда Јуда узе чету и од главара свештеничкијех и фарисеја момке, и дође онамо с фењерима и са свијећама и с оружјем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'А Исус знајући све што ће бити од њега изиђе и рече им: кога тражите?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Одговорише му: Исуса Назарећанина. Исус им рече: ја сам. А с њима стајаше и Јуда који га издаваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'А кад им рече: ја сам; измакоше се натраг и попадаше на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Онда их опет запита Исус: кога тражите? А они рекоше: Исуса Назарећанина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Исус им одговори: казах вам да сам ја. Ако дакле мене тражите, оставите ове нек иду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Да се изврши ријеч што рече: не изгубих ниједнога од онијех које си ми дао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'А Симон Петар имаше нож, па га извади и удари слугу поглавара свештеничкога, и отсијече му десно ухо. А слузи бјеше име Малхо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Онда рече Исус Петру: задјени нож у ножнице. Чашу коју ми даде отац зар да је не пијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'А чета и војвода и момци Јеврејски ухватише Исуса и свезаше га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'И одведоше га најпре Ани, јер бјеше таст Кајафи, који бјеше поглавар свештенички оне године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'А Кајафа бјеше онај што даде свјет Јудејцима да је боље да умре један човјек него народ да пропадне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'За Исусом пак иђаше Симон Петар и други ученик; а ученик онај бјеше познат код поглавара свештеничкога, и уђе с Исусом у двор поглавара свештеничкога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'А Петар стајаше напољу код врата. Онда изиђе онај ученик што бјеше познат код поглавара свештеничкога и рече вратарици те уведе Петра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Онда рече слушкиња вратарица Петру: да нијеси и ти ученик овога човјека? Он рече: нијесам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'А слуге и момци бијаху наложили огањ и стајаху те се гријаху, јер бјеше зима; а и Петар стајаше с њима и гријаше се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Поглавар пак свештенички запита Исуса за ученике његове и за његову науку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Исус му одговори: ја говорих јавно свијету, ја свагда учих у зборници и у цркви, гдје се свагда скупљају Јудејци, и ништа тајно не говорих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Што питаш мене? Питај оне који су слушали шта сам им говорио: ево ови знаду шта сам ја говорио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'А кад он ово рече, један од момака који стајаху ондје удари Исуса по образу, и рече: зар тако одговараш поглавару свештеничкоме?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Исус му одговори: ако зло рекох, докажи да је зло; ако ли добро, зашто ме бијеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'И Ана посла га свезана Кајафи поглавару свештеничкоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'А Симон Петар стајаше и гријаше се. Онда му рекоше: да нијеси и ти од ученика његовијех? А он се одрече и рече: нијесам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Рече један од слугу поглавара свештеничкога који бјеше рођак ономе што му Петар отсијече ухо: не видјех ли ја тебе у врту с њим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Онда се Петар опет одрече; и одмах пијетао запјева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'А Исуса поведоше од Кајафе у судницу. Али бјеше јутро, и они не уђоше у судницу да се не би опоганили, него да би могли јести пасху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Онда Пилат изађе к њима напоље и рече: какову кривицу износите на овога човјека?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Одговорише му и рекоше: кад он не би био злочинац не бисмо га предали теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'А Пилат им рече: узмите га ви и по закону својему судите му. А Јевреји му рекоше: ми не смијемо никога погубити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Да се збуде ријеч Исусова коју рече казујући каквом ће смрти умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Онда уђе Пилат опет у судницу, и дозва Исуса, и рече му: ти си цар Јудејски?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Исус му одговори: говориш ли ти то сам од себе, или ти други казаше за мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Пилат одговори: зар сам ја Јеврејин? Род твој и главари свештенички предаше те мени; шта си учинио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Исус одговори: царство моје није од овога свијета; кад би било од овога свијета царство моје, онда би слуге моје браниле да не бих био предан Јеврејима; али царство моје није одавде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Онда му рече Пилат: даклем си ти цар? Исус одговори: ти говориш да сам ја цар. Ја сам за то рођен, и зато дођох на свијет да свједочим истину. И сваки који је од истине слуша глас мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Рече му Пилат: шта је истина? И ово рекавши изиђе опет к Јеврејима, и рече им: ја никакве кривице не налазим на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'А у вас је обичај да вам једнога пустим на пасху, хоћете ли дакле да вам пустим цара Јудејскога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Онда сви повикаше опет говорећи: не овога, него Вараву. А Варава бјеше хајдук.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Тада дакле Пилат узе Исуса и шиба га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'И војници сплетавши вијенац од трња метнуше му на главу, и обукоше му скерлетну хаљину,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'И говораху: здраво, царе Јудејски! и бијаху га по образима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Онда Пилат изиђе опет напоље, и рече им: ево га изводим к вама напоље, да видите да на њему не налазим никакве кривице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'А Исус изађе напоље под вијенцем од трња и у скерлетној хаљини. И рече им Пилат: ево човјека!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'А кад га видјеше главари свештенички и момци, повикаше говорећи: распни га, распни. Пилат им рече: узмите га ви и распните, јер ја не налазим на њему кривице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Одговорише му Јевреји: ми имамо закон и по закону нашему ваља да умре, јер начини себе сином Божијим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Кад дакле Пилат чу ову ријеч, побоја се већма.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'И опет уђе у судницу, и рече Исусу: одакле си ти? А Исус му не даде одговора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'А Пилат му рече: зар мени не говориш? не знаш ли да имам власт распети те, и власт имам пустити те?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Исус одговори: не би имао власти никакве нада мном кад ти не би било дано одозго; зато онај има већи гријех који ме предаде теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Од тада гледаше Пилат да га пусти. Али Јевреји викаху говорећи: ако овога пустиш нијеси пријатељ ћесару. Сваки који себе царем гради противи се ћесару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Пилат дакле чувши ову ријеч изведе Исуса напоље, и сједе на судијску столицу на мјесту које се зове Калдрма а Јеврејски Гавата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'А бјеше петак уочи пасхе око шестога сахата; и Пилат рече Јеврејима: ево цар ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'А они викаху: узми, узми, распни га. Пилат им рече: зар цара вашега да разапнем? Одговорише главари свештенички: ми немамо цара осим ћесара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Тада им га дакле предаде да се разапне. А они узеше Исуса и одведоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'И носећи крст свој изиђе на мјесто које се зове Коштурница а Јеврејски Голгота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Ондје га разапеше, и с њим другу двојицу с једне и с друге стране, а Исуса у сриједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Пилат пак написа и натис и метну на крст; и бјеше написано: Исус Назарећанин цар Јудејски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'И онај натпис читаше многи од Јевреја; јер мјесто бјеше близу града гдје разапеше Исуса; и бјеше написано Јеврејски, Грчки, Латински.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'А Јеврејски главари свештенички говораху Пилату: не пиши: цар Јудејски, него да сам рече: ја сам цар Јудејски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Пилат одговори: што писах писах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'А војници кад разапеше Исуса узеше његове хаљине и начинише четири дијела, свакоме војнику по дијел, и доламу; а долама не бјеше шивена него изаткана сва с врха до дна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Онда рекоше међу собом: да је не деремо, него да бацамо коцке за њу коме ће допасти. Да се збуде писмо које говори: раздијелише хаљине моје међу собом, а за доламу моју бацише коцке. Војници дакле тако учинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'А стајаху код крста Исусова мати његова, и сестра матере његове Марија Клеопова, и Марија Магдалина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'А Исус видјевши матер и ученика кога љубљаше гдје стоји рече матери својој: жено! ето ти сина!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Потом рече ученику: ето ти матере! И од онога часа узе је ученик к себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Потом знајући Исус да се већ све сврши, да се збуде писмо рече: жедан сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Ондје стајаше суд пун оцта; и они напунише сунђер оцта, и натакнувши на трску, принесоше к устима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'А кад прими Исус оцат рече: сврши се. И преклонивши главу предаде дух.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'А будући да бјеше петак, па да не би тијела остала на крсту у суботу (јер бијаше велики дан она субота), Јевреји молише Пилата да им пребију голијени па да их скину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Онда дођоше војници, и првоме дакле пребише голијени, и другоме распетоме с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'А дошавши на Исуса, кад га видјеше да је већ умро, не пребише му голијени;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Него један од војника прободе му ребра копљем; и одмах изиђе крв и вода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'И онај што видје посвједочи, и свједочанство је његово истинито; и он зна да истину говори да ви вјерујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Јер се ово догоди да се збуде писмо: кост његова да се не преломи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'И опет друго писмо говори: погледаће онога кога прободоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'А потом Јосиф из Ариматеје, који бјеше ученик Исусов али крадом од страха Јеврејскога, моли Пилата да узме тијело Исусово, и допусти Пилат. Онда дође и узе тијело Исусово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'А дође и Никодим, који прије долази Исусу ноћу, и донесе помијешане смирне и алоја око сто литара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'И узеше тијело Исусово, и обавише га платном с мирисима, као што је обичај у Јевреја да укопавају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'А бијаше близу онога мјеста гдје бјеше разапет, врт, и у врту гроб нов, у који нико никад не бјеше метнут.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Ондје дакле петка ради Јеврејскога, јер бјеше близу гроб, метнуше Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'А у први дан недјеље дође Марија Магдалина на гроб рано, још док се не бјеше расвануло, и видје да је камен одваљен од гроба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Онда отрча, и дође к Симону Петру и к другом ученику кога љубљаше Исус, и рече им: узеше Господа из гроба; и не знамо гдје га метнуше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'А Петар изиђе и други ученик, и пођоше ка гробу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Трчаху пак оба заједно, и други ученик трчаше брже од Петра, и дође прије ка гробу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'И надвиривши се видје хаљине гдје леже; али не уђе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Дође пак Симон Петар за њим, и уђе у гроб, и видје хаљине саме гдје леже,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'И убрус који бјеше на глави његовој не с хаљинама да лежи него особито савит на једном мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Тада дакле уђе и други ученик који најприје дође ка гробу, и видје и вјерова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Јер још не знадијаше писма да њему ваља устати из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Онда отидоше опет ученици дома.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'А Марија стајаше напољу код гроба и плакаше. И кад плакаше надвири се над гроб,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'И видје два анђела у бијелијем хаљинама гдје сједе један чело главе а један чело ногу гдје бјеше лежало тијело Исусово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'И рекоше јој они: жено! што плачеш? Рече им: узеше Господа мојега, и не знам гдје га метнуше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'И ово рекавши обазре се натраг, и видје Исуса гдје стоји, и не знадијаше да је Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Исус јој рече: жено! што плачеш? кога тражиш? А она мислећи да је вртар рече му: господине! ако си га ти узео кажи ми гдје си га метнуо, и ја ћу га узети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Исус јој рече: Марија! А она обазревши се рече му: Равуни! које значи учитељу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Рече јој Исус: не дохватај се до мене, јер се још не вратих к оцу својему; него иди к браћи мојој, и кажи им: враћам се к оцу својему и оцу вашему, и Богу својему и Богу вашему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'А Марија Магдалина отиде, и јави ученицима да видје Господа и каза јој ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'А кад би увече онај први дан недјеље, и врата бијаху затворена гдје се бијаху ученици скупили од страха Јеврејскога, дође Исус и стаде на сриједу и рече им: мир вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'И ово рекавши показа им руке и ребра своја. Онда се ученици обрадоваше видјевши Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'А Исус им рече опет: мир вам; као што отац посла мене, и ја шаљем вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'И ово рекавши дуну, и рече им: примите Дух свети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Којима опростите гријехе, опростиће им се; и којима задржите, задржаће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'А Тома који се зове Близанац, један од дванаесторице, не бјеше ондје са њима кад дође Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'А други му ученици говораху: видјесмо Господа. А он им рече: док не видим на рукама његовијем рана од клина, и не метнем прста својега у ране од клина, и не метнем руке своје у ребра његова, нећу вјеровати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'И послије осам дана опет бијаху ученици његови унутра, и Тома с њима. Дође Исус кад бијаху врата затворена, и стаде међу њима и рече: мир вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Потом рече Томи: пружи прст свој амо и виђи руке моје; и пружи руку своју и метни у ребра моја, и не буди невјеран него вјеран.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'И одговори Тома и рече му: Господ мој и Бог мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Исус му рече: пошто ме видје вјеровао си; благо онима који не видјеше и вјероваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'А и многа друга чудеса учини Исус пред ученицима својијем која нијесу писана у књизи овој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'А ово се написаше, да вјерујете да Исус јест Христос син Божиј, и да вјерујући имате живот у име његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Послије тога опет се јави Исус ученицима својијем на мору Тиверијадском. А јави се овако:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Бијаху заједно Симон Петар и Тома који се зваше Близанац, и Натанаило из Кане Галилејске, и синови Зеведејеви, и друга двојица од ученика његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Рече им Симон Петар: идем да ловим рибу. Рекоше му: идемо и ми с тобом. Онда изиђоше и одмах сједоше у лађу, и ону ноћ не ухватише ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'А кад би јутро, стаде Исус на бријегу; али ученици не познаше да је Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'А Исус им рече: дјецо! еда што имате за јело? Одговорише му: немамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'А он им рече: баците мрежу с десне стране лађе, и наћи ћете. Онда бацише, и већ не могаху извући је од мноштва рибе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Онда ученик онај кога љубљаше Исус рече Петру: то је Господ. А Симон Петар кад чу да је Господ, запреже се кошуљом, јер бјеше го, и скочи у море.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'А други ученици дођоше на лађи, јер не бјеше далеко од земље него око двјеста лаката, вукући мрежу с рибом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Кад дакле изљезоше на земљу, видјеше огањ наложен, и на њему метнуту рибу и хљеб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Исус им рече: принесите од рибе што сад ухватисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'А Симон Петар уђе и извуче мрежу на земљу пуну великијех риба сто и педесет и три; и од толикога мноштва не продрије се мрежа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Исус им рече: ходите обједујте. А ниједан од ученика не смедијаше да га пита: ко си ти? видећи да је Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'А дође и Исус, и узе хљеб, и даде им, тако и рибу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Ово се већ трећи пут јави Исус ученицима својијем пошто устаде из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'А кад обједоваше, рече Исус Симону Петру: Симоне Јонин! љубиш ли ме већма него ови? Рече му: да, Господе! ти знаш да те љубим. Рече му Исус: паси јагањце моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Рече му опет другом: Симоне Јонин! љубиш ли ме? Рече му: да, Господе! ти знаш да те љубим. Рече му Исус: паси овце моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Рече му трећом: Симоне Јонин! љубиш ли ме? А Петар поста жалостан што му рече трећом: љубиш ли ме? и рече му: Господе! ти све знаш, ти знаш да те љубим. Рече му Исус: паси овце моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Заиста, заиста ти кажем: кад си био млад, опасивао си се сам и ходио си куд си хтио; а кад остариш, ширићеш руке своје и други ће те опасати и одвести куда нећеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'А ово рече показујући каком ће смрти прославити Бога. И рекавши ово рече му: хајде за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'А Петар обазревши се видје гдје за њим иде онај ученик којега Исус љубљаше, који и на вечери леже на прси његове и рече: Господе! ко је тај који ће те издати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Видјевши Петар овога рече Исусу: Господе! А шта ће овај?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Исус му рече: ако хоћу да он остане докле ја не дођем, што је теби до тога? Ти хајде за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Онда изиђе ова ријеч међу браћом да онај ученик неће умријети: али Исус не рече њему да неће умријети, него: ако хоћу да остане док ја не дођем, што је теби до тога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Ово је онај ученик који свједочи ово, који и написа ово: и знамо да је свједочанство његово истинито.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'А има и друго много што учини Исус, које кад би се редом пописало, ни у сами свијет, мислим, не би могле стати написане књиге. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Прву сам ти књигу написао о свему, о Теофиле, што поче Исус творити и учити');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'До дана кад се узнесе, пошто Духом светијем заповједи апостолима које изабра,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Пред којима и по страдању своме показа себе жива многијем и истинитијем знацима, и јавља им се четрдесет дана, и говори о царству Божијему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'И сабравши их заповједи им да не иду из Јерусалима, него да чекају обећање очино, које чусте, рече, од мене;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Јер је Јован крстио водом, а ви ћете се крстити Духом светијем не дуго после овијех дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'А они онда који заједно бијаху, питаху га говорећи: Господе! хоћеш ли сад начинити царство Израиљево?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'А он им рече: није ваше знати времена и љета које отац задржа у својој власти;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Него ћете примити силу кад сиђе Дух свети на вас; и бићете ми свједоци у Јерусалиму и по свој Јудеји и Самарији и тја до краја земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'И ово рекавши видјеше они гдје се подиже и однесе га облак из очију њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'И кад гледаху за њим гдје иде на небо, гле, два човјека стадоше пред њима у бијелијем хаљинама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Који и рекоше: људи Галилејци! шта стојите и гледате на небо? Овај Исус који се од вас узе на небо тако ће доћи као што видјесте да иде на небо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Тада се вратише у Јерусалим с горе која се зове Маслинска, која је близу Јерусалима један суботни дан хода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'И кад уђоше попеше се у собу гдје стајаху Петар и Јаков и Јован и Андрија, Филип и Тома, Вартоломије и Матеј, Јаков Алфејев и Симон Зилот, и Јуда Јаковљев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Ови сви једнодушно бијаху једнако на молитви и у мољењу са женама, и с Маријом матером Исусовом и браћом његовом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'И у дане оне уставши Петар између ученика рече (а бијаше народа заједно око сто и двадесет имена):');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Људи браћо! требало је да се изврши оно писмо што прорече Дух свети устима Давидовијем за Јуду који бјеше пред онима што ухватише Исуса;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Јер се бројаше с нама, и бијаше примио дијел ове службе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Он дакле стече њиву од плате неправедне, и објесивши се пуче по сриједи, и изасу се сва утроба његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'И постаде знано свима који живе у Јерусалиму да ће се та њива прозвати њиховијем језиком Акелдама, које значи њива крвна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Јер се пише у књизи псалтиру: да буде двор његов пуст, и да не буде никога ко би живљео у њему, и: владичанство његово да прими други.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Треба дакле од овијех људи који су били с нама за све вријеме како међу нас уђе и изиђе Господ Исус,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'Почевши од крштења Јованова до дана кад се узе од нас, да буде с нама свједок његова васкрсенија један од овијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'И поставише двојицу, Јосифа који се зваше Варсава презименом Јуст, и Матија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'И помоливши се Богу рекоше: ти, Господе! Који познајеш срца свију, покажи једнога од ове двојице кога си изабрао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'Да прими дијел ове службе и апостолства, из кога испаде Јуда да иде на мјесто своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'И бацише коцке за њих, и паде коцка на Матија и примише га међу једанаест апостола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'И кад се наврши педесет дана бијаху заједно сви апостоли једнодушно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'И уједанпут постаде хука с неба као духање силнога вјетра, и напуни сву кућу гдје сјеђаху;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'И показаше им се раздијељени језици као огњени; и сједе по један на свакога од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'И напунише се сви Духа светога, и стадоше говорити другијем језицима, као што им Дух даваше те говораху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'А у Јерусалиму стајаху Јевреји људи побожни из свакога народа који је под небом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'А кад постаде овај глас, скупи се народ, и смете се: јер сваки од њих слушаше гдје они говоре његовијем језиком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'И дивљаху се и чуђаху се говорећи један другоме: нијесу ли ово све Галилејци што говоре?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Па како ми чујемо сваки свој језик у коме смо се родили?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Парћани, и Миђани, и Еламљани, и који смо из Месопотамије, и из Јудеје и Кападокије, и из Понта и Азије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'И из Фригије и Памфилије, из Мисира и крајева Ливијскијех код Кирине, и путници из Рима, и Јудејци и дошљаци,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Крићани и Арапи, чујемо гдје они говоре нашијем језицима величине Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'И дивљаху се сви и не могаху се начудити говорећи један другоме: шта ће дакле ово бити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'А други потсмијевајући се говораху: накитили су се вина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'А Петар стаде са једанаесторицом и подиже глас свој и рече им: људи Јудејци и ви сви који живите у Јерусалиму! ово да вам је на знање, и чујте ријечи моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Јер ови нијесу пијани као што ви мислите, јер је тек трећи сахат дана;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Него је ово оно што каза пророк Јоило:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'И биће у пошљедње дане, говори Господ, излићу од Духа својега на свако тијело, и прорећи ће синови ваши и кћери ваше, и младићи ваши видјеће утваре и старци ваши сниће снове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Јер ћу на слуге своје и на слушкиње своје у те дане излити од Духа својега, и прорећи ће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'И даћу чудеса горе на небу и знаке доље на земљи: крв и огањ и пушење дима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Сунце ће се претворити у таму и мјесец у крв прије него дође велики и славни дан Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'И биће да ће се сваки спасти који призове име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Људи Израиљци! послушајте ријечи ове: Исуса Назарећанина, човјека од Бога потврђена међу вама силама и чудесима и знацима које учини Бог преко њега међу вама, као што и сами знате,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'Овога одређенијем савјетом и промислом Божијим предана примивши, преко руку безаконика приковасте и убисте;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Којега Бог подиже, раздријешивши везе смртне, као што не бијаше могуће да га оне држе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Јер Давид говори за њега: Господа једнако гледах пред собом: јер је с десне стране мене, да се не помакнем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Зато се развесели срце моје, и обрадова се језик мој, па још и тијело моје почиваће у наду;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Јер нећеш оставити душе моје у паклу, нити ћеш дати да светац твој види трухљења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Показао си ми путове живота: напунићеш ме весеља с лицем својијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Људи браћо! нека је слободно казати вам управо за старјешину Давида да и умрије, и укопан би, и гроб је његов међу нама до овога дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Пророк дакле будући, и знајући да му се Бог клетвом кле од рода бедара његовијех по тијелу подигнути Христа, и посадити га на пријестолу његову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'Предвидјевши говори за васкрсеније Христово да се не остави душа његова у паклу, ни тијело његово видје трухљења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Овога Исуса васкрсе Бог, чему смо ми сви свједоци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Десницом дакле Божијом подиже се, и обећање светога Духа примивши од оца, изли ово што ви сад видите и чујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Јер Давид не изиђе на небеса, него сам говори: рече Господ Господу мојему: сједи мени с десне стране,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'Док положим непријатеље твоје подножје ногама твојима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Тврдо дакле нека зна сав дом Израиљев да је и Господом и Христом Бог учинио овога Исуса кога ви распесте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'А кад чуше, ражали им се у срцу, и рекоше Петру и осталијем апостолима: шта ћемо чинити, људи браћо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'А Петар им рече: покајте се, и да се крстите сваки од вас у име Исуса Христа за опроштење гријеха; и примићете дар светога Духа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Јер је за вас обећање и за дјецу вашу, и за све даљне које ће год дозвати Господ Бог наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'И другијем многијем ријечима свједочаше, и мољаше их говорећи: спасите се од овога покваренога рода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Који дакле радо примише ријеч његову крстише се; и пристаде у тај дан око три хиљаде душа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'И осташе једнако у науци апостолској, и у заједници, и у ломљењу хљеба, и у молитвама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'И уђе страх у сваку душу; јер апостоли чинише многа чудеса и знаке у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'А сви који вјероваше бијаху заједно, и имаху све заједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'И течевину и имање продаваху и раздаваху свима као што ко требаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'И сваки дан бијаху једнако једнодушно у цркви, и ломљаху хљеб по кућама, и примаху храну с радости и у простоти срца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'Хвалећи Бога, и имајући милост у свију људи. А Господ сваки дан умножаваше друштво онијех који се спасаваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'А Петар и Јован иђаху заједно горе у цркву на молитву у девети сахат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'И бијаше један човјек хром од утробе матере своје, којега ношаху и сваки дан метаху пред врата црквена која се зову Красна да проси милостињу од људи који улазе у цркву;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Који видјевши Петра и Јована да хоће да уђу у цркву прошаше милостињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'А Петар погледавши на њ с Јованом, рече: погледај на нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'А он гледаше у њих мислећи да ће му они што дати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'А Петар рече: сребра и злата нема у мене, него што имам ово ти дајем: у име Исуса Христа Назарећанина устани и ходи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'И узе га за десницу и подиже. И одмах се утврдише његова стопала и глежњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'И скочивши устаде, и хођаше, и уђе с њима у цркву идући и скачући и хвалећи Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'И видјеше га сви људи гдје иде и хвали Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'А знадијаху га да онај бјеше што милостиње ради сјеђаше код Краснијех врата црквенијех, и напунише се чуда и страха за то што би од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'А кад се исцијељени хроми држаше Петра и Јована, навалише к њима сви људи у тријем, који се зваше Соломунов, и чуђаху се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'А кад видје Петар, одговараше људима: људи Израиљци! што се чудите овоме? или шта гледате на нас, као да смо својом силом или побожношћу учинили да он иде?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Бог Авраамов и Исаков и Јаковљев, Бог отаца нашијех, прослави сина својега Исуса, којега ви предадосте и одрекосте га се пред лицем Пилатовијем кад он суди да га пусти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'А ви свеца и праведника одрекосте се, и испросисте човјека крвника да вам поклони;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'А начелника живота убисте, којега Бог васксре из мртвијех, чему смо ми свједоци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'И за вјеру имена његова овога, кога видите и познајете, утврди име његово; и вјера која је кроза њ даде му цијело здравље ово пред свима вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'И сад, браћо, знам да из незнања оно учинисте, као и кнезови ваши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'А Бог како напријед јави устима свију пророка својијех да ће Христос пострадати, изврши тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Покајте се дакле, и обратите се да се очистите од гријеха својијех, да дођу времена одмарања од лица Господњега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'И да пошље напријед нареченога вам Христа Исуса,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Којега ваља дакле небо да прими до онога времена кад се све поправи, што Бог говори устима свију светијех пророка својијех од постања свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Мојсије дакле оцевима нашијем рече: Господ Бог ваш подигнуће вам пророка из ваше браће, као мене; њега послушајте у свему што вам каже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'И биће да ће се свака душа која не послуша тога пророка истријебити из народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'А и сви пророци од Самуила и потом колико их год говори, и за ове дане јављаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Ви сте синови пророка и завјета који учини Бог с оцевима вашијем говорећи Аврааму: и у сјемену твојему благословиће се сви народи на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Вама најприје Бог подиже сина својега Исуса, и посла га да вас благосиља да се сваки од вас обрати од пакости својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'А кад они говораху народу, наиђоше на њих свештеници и војвода црквени и садукеји;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'И расрдише се, што они уче људе и јављају у Исусу васкрсеније из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'И дигоше на њих руке, и метнуше их у затвор до ујутру: јер већ бјеше вече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'А од онијех који слушаху ријеч многи вјероваше, и постаде број људи око пет хиљада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'А кад би ујутру, скупише се кнезови њихови и старјешине и књижевници у Јерусалим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'А Ана поглавар свештенички и Кајафа и Јован и Александар и колико их год бјеше од рода свештеничкога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'И метнувши их на сриједу питаху: каком силом или у чије име учинисте ви ово?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Тада Петар напунивши се Духа светога рече им: кнезови народни и старјешине Израиљеве!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Ако нас данас питате за добро дјело које учинисмо болесну човјеку те он оздрави:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Да је на знање свима вама и свему народу Израиљеву да у име Исуса Христа Назарећанина, којега ви распесте, којега Бог подиже из мртвијех, стоји овај пред вама здрав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Ово је камен који ви зидари одбацисте, а постаде глава од угла: и нема ни у једноме другом спасенија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Јер нема другога имена под небом данога људима којијем би се ми могли спасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'А кад видјеше слободу Петрову и Јованову, и знајући да су људи некњижевни и прости, дивљаху се, и знадијаху их да бијаху с Исусом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'А видећи исцијељенога човјека гдје с њима стоји не могаху ништа противу рећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Онда им заповједише да изиђу напоље из савјета, па питаху један другога');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Говорећи: шта ћете чинити овијем људима? Јер велики знак што учинише они познат је свима који живе у Јерусалиму, и не можемо одрећи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Али да се даље не разилази по народу, да им оштро запријетимо да више не говоре за име ово никоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'И дозвавши их заповједише им да ништа не спомињу нити да уче у име Исусово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Петар и Јован одговарајући рекоше им: судите је ли право пред Богом да вас већма слушамо неголи Бога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Јер ми не можемо не говорити што видјесмо и чусмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'А они запријетивши им пустише их, не нашавши ништа како би их мучили, народа ради; јер сви хваљаху Бога за оно што се бјеше догодило.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Јер ономе човјеку бјеше више од четрдесет година на ком се догоди ово чудо здравља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'А кад их отпустише, дођоше к својима, и јавише им шта рекоше главари свештенички и старјешине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'А они кад чуше, једнодушно подигоше глас к Богу и рекоше: Господе Боже, ти који си створио небо и земљу и море и све што је у њима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Који устима Давида слуге својега рече: зашто се буне незнабошци, и народи измишљавају празне ријечи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Састаше се цареви земаљски, и кнезови се сабраше уједно на Господа и на Христа његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Заиста се сабраше у овоме граду на светога сина твојега Исуса, којега си помазао, Ирод и Понтијски Пилат с незнабошцима и с народом Израиљевијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Да учине што рука твоја и савјет твој напријед одреди да буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'И сад Господе! погледај на њихове пријетње, и дај слугама својима да говоре са сваком слободом ријеч твоју;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'И пружај руку своју на исцијељивање и да знаци и чудеса бивају именом светога сина твојега Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'И пошто се они помолише Богу затресе се мјесто гдје бијаху сабрани, и напунише се сви Духа светога, и говораху ријеч Божију са слободом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'А у народа који вјерова бјеше једно срце и једна душа; и ниједан не говораше за имање своје да је његово, него им све бјеше заједничко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'И апостоли с великом силом свједочаху за васкрсеније Господа Исуса Христа; и благодат велика бјеше на свима њима:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Јер ниједан међу њима не бјеше сиромашан, јер колико их год бијаше који имадијаху њиве или куће, продаваху и доношаху новце што узимаху за то,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'И метаху пред ноге апостолима; и даваше се свакоме као што ко требаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'А Јосија, прозвани од апостола Варнава, које значи син утјехе, Левит родом из Кипра,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'Он имадијаше њиву, и продавши је донесе новце и метну апостолима пред ноге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'А један човјек, по имену Ананија, са женом својом Сапфиром продаде њиву,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'И сакри од новаца са знањем и жене своје, и донесавши један дијел метну апостолима пред ноге.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'А петар рече: Ананија! зашто напуни сотона срце твоје да слажеш Духу светоме и сакријеш од новаца што узе за њиву?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Кад је била у тебе не бјеше ли твоја? И кад је продаде не бјеше ли у твојој власти? Зашто си дакле такову ствар метнуо у срце своје? Људима нијеси слагао него Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'А кад чу Ананија ријечи ове паде и издахну; и уђе велики страх у све који слушаху ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'А момци ушавши узеше га и изнесоше те закопаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'А кад прође око три сахата, уђе и жена његова не знајући шта је било.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'А Петар јој одговори: кажи ми јесте ли за толико дали њиву? А она рече: да, за толико.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'А Петар јој рече: зашто се договористе да искушате Духа Господњега? Гле, ноге онијех који твога мужа закопаше пред вратима су, и изнијеће те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'И одмах падну пред ногама његовијем и издахну. А момци ушавши нађоше је мртву и изнесоше је и закопаше код мужа њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'И уђе велики страх у сву цркву и у све који чуше ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'А рукама апостолскима учинише се многи знаци и чудеса међу људима; и бијаху сви једнодушно у тријему Соломунову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'А од осталијех нико не смијаше приступити њима; него их хваљаше народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'А све више пристајаху они који вјероваху Господа, мноштво људи и жена,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Тако да и по улицама изношаху болеснике и метаху на постељама и на носилима, да би кад прође Петар барем сјенка његова осјенила кога од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'А долажаху многи и из околнијех градова у Јерусалим, и доношаху болеснике и које мучаху нечисти духови; и сви оздрављаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Али устаде поглавар свештенички и сви који бијаху с њим, од јереси садукејске, и напунише се зависти,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'И дигоше руке своје на апостоле, и метнуше их у општи затвор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'А анђео Господњи отвори ноћу врата тамничка, и изведавши их рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Идите и станите у цркви те говорите народу све ријечи овога живота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'А кад они чуше, уђоше ујутру у цркву, и учаху. А кад дође поглавар свештенички и који бијаху с њим, сазваше сабор и све старјешине од синова Израиљевијех, и послаше у тамницу да их доведу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'А кад слуге отидоше, не нађоше их у тамници; онда се вратише и јавише им');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'Говорећи: тамницу нађосмо закључану са сваком тврђом и чуваре гдје стоје пред вратима; али кад отворисмо, унутра ниједнога не нађосмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'А кад чуше ове ријечи поглавар свештенички и војвода црквени и остали главари свештенички, не могаху им се начудити шта би то сад било.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'А неко дође и јави им говорећи: ено они људи што их бацисте у тамницу, стоје у цркви и уче народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Тада отиде војвода с момцима и доведе их не на силу: јер се бојаху народа да их не побије камењем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'А кад их доведоше, поставише их пред сабор, и запита их поглавар свештенички говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'Не запријетисмо ли вам оштро да не учите у ово име? и гле, напунисте Јерусалим својом науком, и хоћете да баците на нас крв овога човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'А Петар и апостоли одговарајућу рекоше: већма се треба Богу покоравати неголи људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Бог отаца нашијех подиже Исуса, којега ви убисте објесивши на дрво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Овога Бог десницом својом узвиси за поглавара и спаса, да да Израиљу покајање и опроштење гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'И ми смо његови свједоци овијех ријечи и Дух Свети којега Бог даде онима који се њему покоравају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'А кад они чуше врло се расрдише, и мишљаху да их побију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Али онда устаде у скупштини један фарисеј по имену Гамалиило, законик, поштован од свега народа, и заповједи да апостоли мало изиђу напоље,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'Па рече њима: људи Израиљци! гледајте добро за ове људе шта ћете чинити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Јер прије овијех дана уста Тевда, говорећи да је он нешто, за којијем пристаде људи на број око четири стотине; он би убијен, и сви који га слушаху разиђоше се и пропадоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Потом уста Јуда Галилејац, у дане пријеписа, и одвуче доста људи за собом; и он погибе, и сви који га слушаху разасуше се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'И сад вам кажем: прођите се овијех људи и оставите их; јер ако буде од људи овај савјет или ово дјело, поквариће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'Ако ли је од Бога, не можете га покварити, да се како не нађете као богоборци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Онда га послушаше, и дозвавши апостоле избише их, и запријетише им да не говоре у име Исусово, и отпустише их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'А они онда отидоше од сабора радујући се што се удостојише примити срамоту за име Господа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'А сваки дан у цркви и по кућама не престајаху учити и проповиједати јеванђеље о Исусу Христу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'А у ове дане, кад се умножише ученици, подигоше Грци вику на Јевреје што се њихове удовице заборављаху кад се дијељаше храна сваки дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Онда дванаесторица дозвавши мноштво ученика, рекоше: није прилично нама да оставимо ријеч Божију па да служимо око трпеза.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Нађите дакле, браћо, међу собом седам поштенијех људи, пунијех Духа светога и премудрости, које ћемо поставити над овијем послом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'А ми ћемо у молитви и у служби ријечи остати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'И ова ријеч би угодна свему народу. И изабраше Стефана, човјека напуњена вјере и Духа светога, и Филипа, и Прохора, и Никанора, и Тимона, и Пармена, и Николу покрштењака из Антиохије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Ове поставише пред апостоле и они помоливши се Богу метнуше руке на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'И ријеч Божија растијаше, и множаше се врло број ученика у Јерусалиму. И свештеници многи покораваху се вјери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'А Стефан пун вјере и силе чињаше знаке и чудеса велика међу људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Тада усташе неки из зборнице која се зове Ливерћанска и Кириначка и Александријначка и онијех који бијаху из Киликије и Азије, и препираху се са Стефаном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'И не могаху противу стати премудрости и Духу којијем говораше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Тада подговорише људе те казаше: чусмо га гдје хули на Мојсија и на Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'И побунише народ и старјешине и књижевнике, и нападоше и ухватише га, и доведоше га на сабор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'И изведоше лажне свједоке који говораху: овај човјек не престаје хулити на ово свето мјесто и на закон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Јер га чусмо гдје говори: овај Исус Назарећанин развалиће ово мјесто, и измијениће обичаје које нам остави Мојсије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'И погледавши на њ сви који сјеђаху на сабору видјеше лице његово као лице анђела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'А поглавар свештенички рече: је ли дакле тако?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'А он рече: људи браћо и оци! послушајте. Бог славе јави се оцу нашему Аврааму кад бјеше у Месопотамији, прије него се досели у Харан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'И рече му: изиђи из земље своје и од рода својега и из дома оца својега, и дођи у земљу коју ћу ти ја показати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Тада изиђе из земље Халдејске, и досели се у Харан; и оданде, по смрти оца његова, пресели га у ову земљу у којој ви сад живите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'И не даде му нашљедства у њој ни стопе; и обрече му је дати у држање и сјемену његову послије њега, док он још немаше дјетета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Али Бог рече овако: сјеме твоје биће дошљаци у земљи туђој, и натјераће га да служи, и мучиће га четири стотине година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'И народу коме ће служити ја ћу судити, рече Бог; и потом ће изићи, и служиће мени на овоме мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'И даде му завјет обрезања, и тако роди Исака, и обреза га у осми дан; и Исак Јакова, и Јаков дванаест старјешина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'И старјешине завиђаху Јосифу, и продадоше га у Мисир; и Бог бјеше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'И избави га од свију његовијех невоља, и даде му милост и премудрост пред Фараоном царем Мисирскијем, и постави га поглаваром над Мисиром и над свијем домом својијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'А дође глад на сву земљу Мисирску и Хананску и невоља велика, и не налажаху хране оци наши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'А Јаков чувши да има пшенице у Мисиру посла најприје оце наше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'И кад дођоше други пут, познаше Јосифа браћа његова, и род Јосифов поста познат Фараону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'А Јосиф посла и дозва оца својега Јакова и сву родбину своју, седамдесет и пет душа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'И Јаков сиђе у Мисир, и умрије, он и оцеви наши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'И пренесоше их у Сихем, и метнуше у гроб који купи Авраам за новце од синова Еморовијех у Сихему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'И кад се приближи вријеме обећања за које се Бог закле Аврааму, народ се народи и умножи у Мисиру,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'Док наста други цар у Мисиру, који не знаше Јосифа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Овај намисли зло за наш род, измучи оце наше да своју дјецу бацаху да не живе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'У то се вријеме роди Мојсије, и бјеше Богу угодан, и би три мјесеца храњен у кући оца својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'А кад га избацише, узе га кћи Фараонова, и одгаји га себи за сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'И научи се Мојсије свој премудрости Мисирској, и бјеше силан у ријечима и у дјелима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'А кад му се навршиваше четрдесет година, дође му на ум да обиђе браћу своју, синове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'И видјевши једноме гдје се чини неправда, поможе, и покаја онога што му се чињаше неправда, и уби Мисирца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Мишљаше пак да браћа његова разумију да Бог његовом руком њима спасеније даде: али они не разумјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'А сјутрадан дође међу такове који се бијаху свадили, и мираше их говорећи: људи, ви сте браћа, зашто чините неправду један другоме?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'А онај што чињаше неправду ближњему отури га говорећи: ко је тебе поставио кнезом и судијом над нама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Или и мене хоћеш да убијеш као што си јуче убио Мисирца?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'А Мојсије побјеже од ове ријечи, и поста дошљак у земљи Мадијамској, гдје роди два сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'И кад се наврши четрдесет година, јави му се у пустињи горе Синајске анђео Господњи у пламену огњеном у купини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'А кад Мојсије видје, дивљаше се утвари. А кад он приступи да види, би глас Господњи к њему:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Ја сам Бог отаца твојијех, Бог Авраамов и Бог Исаков и Бог Јаковљев. А Мојсије се бјеше уздрктао и не смијаше да погледа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'А Господ му рече: изуј обућу своју са својијех ногу: јер је мјесто на коме стојиш света земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Ја добро видјех муку својега народа који је у Мисиру, и чух њихово уздисање, и сиђох да их избавим: и сад ходи да те пошљем у Мисир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Овога Мојсија, којега отурише рекавши: ко те постави кнезом и судијом? овога Бог за кнеза и избавитеља посла руком анђела који му се јави у купини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Овај их изведе учинивши чудеса и знаке у земљи Мисирској и у Црвеном Мору и у пустињи четрдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Ово је Мојсије који каза синовима Израиљевијем: Господ Бог ваш подигнуће вам пророка из ваше браће, као мене: њега послушајте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Ово је онај што бјеше у цркви у пустињи с анђелом, који му говори на гори Синајској, и с оцима нашијем; који прими ријечи живе да их нама да;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Којега не хтјеше послушати оци наши, него га одбацише, и окренуше се срцем својијем у Мисир,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'Рекавши Арону: начини нам богове који ће ићи пред нама, јер овоме Мојсију, који нас изведе из земље Мисирске, не знамо шта би.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'И тада начинише теле, и принесоше жртву идолу, и радоваху се рукотворини својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'А Бог се окрену од њих, и предаде их да служе војницима небескијем, као што је писано у књизи пророка: еда заклања и жртве принесосте ми на четрдесет година у пустињи, доме Израиљев?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'И примисте чадор Молохов, и звијезду бога својега Ремфана, кипове које начинисте да им се молите; и преселићу вас даље од Вавилона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Оцеви наши имаху чадор свједочанства у пустињи, као што заповједи онај који говори Мојсију да га начини по оној прилици као што га видје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Који и примише оцеви наши и донесоше с Исусом Навином у земљу незнабожаца, које отури Бог испред лица нашијех отаца, тја до Давида,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Који нађе милост у Бога, и измоли да нађе мјесто Богу Јаковљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'А Соломун му начини кућу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Али највиши не живи у рукотворенијем црквама, као што говори пророк:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, 'Небо је мени пријестол а земља подножје ногама мојима: како ћете ми кућу сазидати? говори Господ; или које је мјесто за моје почивање?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Не створи ли рука моја све ово?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Тврдоврати и необрезанијех срца и ушију! ви се једнако противите Духу светоме; како ваши оци, тако и ви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Којега од пророка не протјераше оци ваши? И побише оне који напријед јавише за долазак праведника, којега ви сад издајници и крвници постадосте;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'Који примисте закон наредбом анђелском, и не одржасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Кад ово чуше, расрдише се врло у срцима својима, и шкргутаху зубима на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'А Стефан будући пун Духа светога погледа на небо и видје славу Божију и Исуса гдје стоји с десне стране Богу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'И рече: ево видим небеса отворена и сина човјечијега гдје стоји с десне стране Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'А они повикавши иза гласа затискиваху уши своје, и навалише једнодушно на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'И изведавши га из града стадоше га засипати камењем, и свједоци хаљине своје метнуше код ногу младића по имену Савла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'И засипаху камењем Стефана, који се мољаше Богу и говораше: Господе Исусе! прими дух мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Онда клече на кољена и повика иза гласа: Господе! не прими им ово за гријех. И ово рекавши умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Савле пак бјеше пристао на његову смрт. А у тај дан постаде велико гоњење на цркву Јерусалимску, и сви се расијаше по крајевима Јудејскијем и Самаријскијем осим апостола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'А људи побожни укопаше Стефана и велики плач учинише над њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'А Савле досађиваше цркви, јер иђаше по кућама, и вуцијаше људе и жене те предаваше у тамницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'А они што се бијаху расијали пролажаху проповиједајући ријеч.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'А Филип сишавши у град Самаријски проповиједаше им Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'А народ пажаше једнодушно на оно што говораше Филип, слушајући и гледајући знаке које чињаше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Јер духови нечисти с великом виком излажаху из многијех у којима бијаху, и многи узети и хроми оздравише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'И би велика радост у граду ономе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'А бјеше један човјек, по имену Симон, који прије чараше у граду и довођаше у чудо народ Самаријски, говорећи да је он нешто велико;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'На којега гледаху сви, и мало и велико, говорећи: ово је велика сила Божија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'А зато гледаху на њега што их много времена чинима удивљаваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Кад пак вјероваше Филипу који проповиједаше јеванђеље о царству Божијему, и о имену Исуса Христа, кршћаваху се и људи и жене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Тада и Симон вјерова, и крстивши се оста код Филипа; и видећи дјела и знаке велике који се чињаху дивљаше се врло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'А кад чуше апостоли који бијаху у Јерусалиму да Самарија прими ријеч Божју, послаше к њима Петра и Јована.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Који сишавши помолише се Богу за њих да приме Духа светога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Јер још ни на једнога не бјеше дошао, него бијаху само крштени у име Господа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Тада апостоли метнуше руке на њих, и они примише Духа светога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'А кад видје Симон да се даје Дух свети кад апостоли метну руке, донесе им новце');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Говорећи: дајте и мени ову власт да кад метнем руке на кога прими Духа светога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'А Петар му рече: новци твоји с тобом да буду у погибао, што си помислио да се дар Божиј може добити за новце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Нема теби дијела ни исета у овој ријечи; јер срце твоје није право пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Покај се дакле од ове своје пакости, и моли се Богу да би ти се опростила помисао срца твога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Јер те видим да си у гркој жучи и у свези неправде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'А Симон одговарајући рече: помолите се ви Господу за мене да не наиђе на мене ништа од овога што рекосте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Тако они посвједочивши и говоривши ријеч Господњу вратише се у Јерусалим, и многијем селима Самаријскијем проповједише јеванђеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'А анђео Господњи рече Филипу говорећи: устани и иди на подне на пут који силази од Јерусалима у Газу и пуст је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'И уставши пође. И гле, човјек Арапин, ушкопљеник, властелин Кандакије царице Арапске, што бјеше над свима њезинијем ризницама, који бјеше дошао у Јерусалим да се моли Богу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'Па се враћаше, и сједећи на колима својијем читаше пророка Исаију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'А Дух рече Филипу: приступи и прилијепи се тијем колима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'А Филип притрчавши чу га гдје чита пророка Исаију, и рече: а разумијеш ли што читаш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'А он рече: како бих могао разумјети ако ме ко не упути? И умоли Филипа те се попе и сједе с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'А мјесто из писма које читаше бјеше ово: као овца на заклање одведе се, и нијем као јагње пред онијем који га стриже, тако не отвори уста својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'У његовом понижењу укиде се суд његов. А род његов ко ће исказати? Јер се његов живот узима од земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Онда ушкопљеник одговори Филипу и рече: молим те, за кога ово говори пророк? или за себе или за кога другога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'А Филип отворивши уста своја, и почевши од писма овога, приповједи му јеванђеље Исусово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Како иђаху путем дођоше на некаку воду; и рече ушкопљеник: ево воде, шта брани мени да се крстим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'А Филип му рече: ако вјерујеш од свега срца својега, можеш. А он одговарајући рече: вјерујем да је Исус Христос син Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'И заповједи да стану кола, и сиђоше оба на воду, и Филип и ушкопљеник, и крсти га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'А кад изиђоше из воде, Дух свети паде на ушкопљеника, а анђео Господњи узе Филипа, и више га не видје ушкопљеник; него отиде путем својијем радујући се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'А Филип се обрете у Азоту; и пролазећи проповиједаше јеванђеље свима градовима, док не дође у Ћесарију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'А Савле још дишући пријетњом и смрћу на ученике Господње приступи к поглавару свештеничкоме,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'И измоли у њега посланице у Дамаск на зборнице, ако кога нађе од овога пута, и људе и жене свезане да доведе у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'А кад бјеше на путу и дође близу Дамаска, уједанпут обасја га свјетлост с неба,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'И паднувши на земљу чу глас гдје му говори: Савле! Савле! зашто ме гониш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'А он рече: ко си ти, Господе? А Господ рече: ја сам Исус, којега ти гониш: тешко ти је противу бодила праћати се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'А он дркћући од страха рече: Господе! шта хоћеш да чиним? И Господ му рече: устани и уђи у град, па ће ти се казати шта ти треба чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'А људи који иђаху с њим стајаху и чуђаху се, јер чујаху глас а не виђаху никога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'А Савле уста од земље, и отворенијем очима својијем никога не виђаше. А они га узеше за руку и уведоше у Дамаск.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'И бјеше три дана слијеп, и не једе, нити пи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'А у Дамаску бјеше један ученик, по имену Ананија, и рече му Господ у утвари: Ананија! А он рече: ево ме, Господе!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'А Господ му рече: устани и иди у улицу која се зове Права, и тражи у дому Јудином по имену Савла Таршанина; јер гле, он се моли Богу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'И видје у утвари човјека, по имену Ананију, гдје уђе и метну руку на њ да прогледа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'А Ананија одговори: Господе! ја чух од многијех за тога човјека колика зла почини светима твојима у Јерусалиму;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'И овдје има власт од главара свештеничкијех да веже све који призивају име твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'А Господ му рече: иди, јер ми је он суд избрани да изнесе име моје пред незнабошце и цареве и синове Израиљеве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'А ја ћу му показати колико му ваља пострадати за име моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'И пође Ананија, и уђе у кућу, и метнувши руке на њ рече: Савле, брате! Господ Исус, који ти се јави на путу којијем си ишао, посла ме да прогледаш и да се напуниш Духа светога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'И одмах отпаде од очију његовијех као крљушт, и одмах прогледа, и уставши крсти се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'И пошто поједе окријепи се; и би Савле неколико дана с ученицима који бијаху у Дамаску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'И одмах по зборницама проповиједаше Исуса да је он син Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'А сви који слушаху дивљаху се и говораху: није ли ово онај што гоњаше у Јерусалиму оне који спомињаху име ово, и овдје зато дође да их повезане води главарима свештеничкијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'А Савле се већма сиљаше и забуњиваше Јевреје који живе у Дамаску, доказујући да је ово Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'А кад се наврши подоста дана, договорише се Јевреји да га убију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Али Савле дознаде њихов договор; а они чуваху врата дан и ноћ да би га убили;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'А ученици га узеше ноћу и спустише преко зида у котарици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'А кад дође Савле у Јерусалим, огледаше да се прибије уз ученике; и сви га се бојаху, јер не вјероваху да је ученик.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'А Варнава га узе и доведе к апостолима, и каза им како на путу видје Господа, и како му говори, и како у Дамаску слободно проповиједа име Исусово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'И бијаше с њима и улази у Јерусалим и излази и слободно приповиједаше име Господа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'И говораше и препираше се с Грцима; а они гледаху да га убију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'А кад разумјеше браћа, сведоше га у Ћесарију, и отпустише га у Тарс.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'А цркве по свој Јудеји и Галилеји и Самарији бијаху на миру, и напредоваху, и хођаху у страху Господњем, и умножаваху се утјехом светога Духа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'И догоди се кад Петар обилажаше све, да дође и к светима који живљаху у Лиди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'И нађе тамо једнога човјека по имену Енеју, који већ осам година лежаше на одру, јер бјеше узет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'И рече му Петар: Енеја! исцјељује те Исус Христос, устани и простри сам себи. И одмах уста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'И видјеше га сви који живљаху у Лиди и у Асарону, и обратише се ка Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'А у Јопи бјеше једна ученица по имену Тавита, које значи срна, и она бјеше пуна добријех дјела и милостиње што чињаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'И догоди се у те дане да се она разбоље и умрије; онда је окупаше и метнуше у горњу собу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'А будући да је Лида близу Јопе, онда ученици чувши да је Петар у њој послаше два човјека молећи га да не пожали труда доћи до њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'А Петар уставши отиде с њима, и кад дође, изведоше га у горњу собу и скупише се око њега све удовице плачући у показујућу сукње и хаљине што је радила Срна док је била с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'А Петар изгнавши све напоље клече на кољена и помоли се Богу, и окренувши се к тијелу рече: Тавито! устани. А она отвори очи своје, и видјевши Петра сједе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Петар пак пруживши јој руку подиже је; и дозвавши свете и удовице показа је живу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'И ово се разгласи по свој Јопи, и многи вјероваше Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'И догоди се да он оста много дана у Јопи у некога Симона кожара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'А у Ћесарији бјеше један човјек по имену Корнилије, капетан од чете која се зваше Талијанска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Побожан и богобојазан са цијелијем домом својијем, који даваше милостињу многијем људима и мољаше се Богу без престанка;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Он видје на јави у утвари око деветога сахата дневи анђела Божијега гдје сиђе к њему и рече му: Корнилије!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'А он погледавши на њ и уплашивши се рече: што је Господе? А он му рече: молитве твоје и милостиње твоје изиђоше на памет Богу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'И сад пошљи у Јопу људе и дозови Симона прозванога Петра:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Он стоји у некога Симона кожара, којега је кућа код мора: он ће ти казати ријечи којима ћеш се спасти ти и сав дом твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'И кад отиде анђео који говори Корнилију, дозвавши двојицу од својијех слугу и једнога побожна војника од онијех који му служаху,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'И казавши им све посла их у Јопу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'А сјутрадан кад они иђаху путем и приближише се ка граду, изиђе Петар у горњу собу да се помоли Богу у шести сахат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'И огладње, и шћаше да једе; а кад му они готовљаху, дође изван себе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'И видје небо отворено и суд некакав гдје силази на њега, као велико платно, завезан на четири рогља и спушта се на земљу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'У коме бијаху сва четвороножна на земљи, и звјериње и бубине и птице небеске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'И постаде глас к њему: устани, Петре! покољи и поједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'А Петар рече: нипошто, Господе! јер никад не једох што погано или нечисто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'И гле, глас опет к њему другом: што је Бог очистио ти не погани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'И ово би трипут, и суд се опет узе на небо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'А кад се Петар у себи дивљаше шта би била утвара коју видје, и гле, људи послани од Корнилија, напитавши и нашавши дом Симонов стадоше пред вратима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'И зовнувши питаху: стоји ли овдје Симон прозвани Петар?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'А док Петар размишљаваше о утвари, рече му Дух: ево три човјека траже те;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Него устани и сиђи и иди с њима не премишљајући ништа, јер их ја послах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'А Петар сишавши к људима посланијем к себи од Корнилија рече: ево ја сам кога тражите; што сте дошли?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'А они рекоше: Корнилије капетан, човјек праведан и богобојазан, познат код свега народа Јеврејскога, примио је заповијест од анђела светога да дозове тебе у свој дом и да чује ријечи од тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Онда их дозва унутра и угости. А сјутрадан уставши Петар пође с њима, и неки од браће која бјеше у Јопи пођоше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'И сјутрадан уђоше у Ћесарију. А Корнилије чекаше их сазвавши родбину своју и љубазне пријатеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'А кад Петар шћаше да уђе, срете га Корнилије, и паднувши на ноге његове поклони се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'И Петар га подиже говорећи: устани, и ја сам човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'И с њим говорећи уђе, и нађе многе који се бијаху сабрали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'И рече им: ви знате како је неприлично човјеку Јеврејину дружити се или долазити к туђину; али Бог мени показа да ниједнога човјека не зовем погана или нечиста;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Зато и без сумње дођох позван. Питам вас дакле зашто посласте по мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'И Корнилије рече: од четвртога дана до овога часа ја постих, и у девети сахат мољах се Богу у својој кући; и гле, човјек стаде преда мном у хаљини сјајној,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'И рече: Корнилије! услишена би молитва твоја и милостиње твоје поменуше се пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Пошљи дакле у Јопу и дозови Симона који се зове Петар: он стоји у кући Симона кожара код мора, који кад дође казаће ти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Онда ја одмах послах к теби; и ти си добро учинио што си дошао. Сад дакле ми сви стојимо пред Богом да чујемо све што је теби од Бога заповјеђено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'А Петар отворивши уста рече: заиста видим да Бог не гледа ко је ко;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'Него у сваком народу који се боји њега и твори правду мио је њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Ријеч што посла синовима Израиљевијем, јављајући мир по Исусу Христу, она је Господ свима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Ви знате говор који је био по свој Јудеји почевши од Галилеје по крштењу које проповиједа Јован:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Исуса из Назарета како га помаза Бог Духом светијем и силом, који прође чинећи добро и исцјељујући све које ђаво бјеше надвладао; јер Бог бијаше с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'И ми смо свједоци свему што учини у земљи Јудејској и Јерусалиму; којега и убише објесивши на дрво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Овога Бог васкрсе трећи дан, и даде му да се покаже,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'Не свему народу него нама свједоцима напријед избранима од Бога, који с њим једосмо и писмо по васкрсенију његовом из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'И заповједи нам да проповиједамо народу и да свједочимо да је он наречени од Бога судија живијем и мртвијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'За ово свједоче сви пророци да ће именом његовијем примити опроштење гријеха сви који га вјерују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'А док још Петар говораше ове ријечи, сиђе Дух свети на све који слушаху ријеч.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'И удивише се вјерни из обрезања који бијаху дошли с Петром, видећи да се и на незнабошце изли дар Духа светога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Јер их слушаху гдје говораху језике, и величаху Бога. Тада одговори Петар:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Еда може ко воду забранити да се не крсте они који примише Духа светога као и ми?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'И заповједи им да се крсте у име Исуса Христа. Тада га молише да остане код њих неколико дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'А чуше и апостоли и браћа који бијаху у Јудеји да и незнабошци примише ријеч Божију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'И кад изиђе Петар у Јерусалим, препираху се с њим који бијаху из обрезања,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Говорећи: ушао си к људима који нијесу обрезани, и јео си с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'А Петар почевши казиваше им редом говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Ја бијах у граду Јопи на молитви, и дошавши изван себе видјех утвару, гдје силази суд некакав као велико платно на четири рогља и спушта се с неба, и дође до преда ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Погледавши у њ опазих и видјех четвороножна земаљска, и звјериње и бубине и птице небеске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'А чух глас који ми говори: устани, Петре! покољи и поједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'А ја рекох: нипошто Господе! јер ништа погано и нечисто никад не уђе у уста моја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'А глас ми одговори другом с неба говорећи: што је Бог очистио ти не погани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'А ово би трипут; и узе се опет све на небо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'И гле, одмах три човјека сташе пред кућом у којој бијах, послани из Ћесарије к мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'А Дух ми рече да идем с њима не премишљајучи ништа. А дођоше са мном и ово шест браће, и уђосмо у кућу човјекову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'И каза нам како видје анђела у кући својој који је стао и казао му: пошљи људе у Јопу и дозови Симона прозванога Петра,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Који ће ти казати ријечи којима ћеш се спасти ти и сав дом твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'А кад ја почех говорити, сиђе Дух свети на њих, као и на нас у почетку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Онда се опоменух ријечи Господње како говораше: Јован је крстио водом, а ви ћете се крстити Духом светијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Кад им дакле Бог даде једнак дар као и нама који вјерујемо Господа својега Исуса Христа; ја ко бијах да би могао забранити Богу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'А кад чуше ово, умукоше, и хваљаху Бога говорећи: дакле и незнабошцима Бог даде покајање за живот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'А они што се расијаше од невоље која поста за Стефана, прођоше тја до Финикије и Кипра и Антиохије, никому не говорећи ријечи до самијем Јеврејима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'А неки од њих бијаху Кипрани и Киринци, који ушавши у Антиохију говораху Грцима проповиједајући јеванђеље о Господу Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'И бјеше рука Божија с њима; и много их вјероваше и обратише се ка Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'А дође ријеч о њима до ушију цркве која бјеше у Јерусалиму; и послаше Варнаву да иде тја до Антиохије;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Који дошавши и видјевши благодат Божију, обрадова се, и мољаше све да тврдијем срцем остану у Господу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Јер бјеше човјек благ и пун Духа светога и вјере. И обрати се многи народ ка Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Варнава пак изиђе у Тарс да тражи Савла; и кад га нађе, доведе га у Антиохију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'И они се цијелу годину састајаше ондје с црквом, и учише многи народ; и најприје у Антиохији назваше ученике хришћанима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'А у те дане сиђоше из Јерусалима пророци у Антиохију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'И уставши један од њих, по имену Агав, објави глад велики који шћаше бити по васионом свијету; који и би за Клаудија ћесара.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'А од ученика одреди сваки колико који могаше да пошљу у помоћ браћи која живљаху у Јудеји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Које и учинише пославши старјешинама преко руке Варнавине и Савлове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'У оно пак вријеме подиже Ирод цар руке да мучи неке од цркве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'И погуби Јакова брата Јованова мачем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'И видјевши да је то по вољи Јеврејима настави да ухвати и Петра (а бијаху дани пријеснијех хљебова),');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Којега и ухвати и баци у тамницу, и предаде га четворици четвртника војничкијех да га чувају, и мишљаше га по пасхи извести пред народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'И тако Петра чуваху у тамници; а црква мољаше се за њега Богу без престанка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'А кад шћаше Ирод да га изведе, ону ноћ спаваше Петар међу двојицом војника, окован у двоје вериге, а стражари пред вратима чуваху тамницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'И гле, анђео Господњи приступи, и свјетлост обасја по соби, и куцнувши Петра у ребра пробуди га говорећи: устани брже. И спадоше му вериге с руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'А анђео му рече: опаши се, и обуј опанке своје. И учини тако. И рече му анђео: обуци хаљину своју, па хајде за мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'И изишавши иђаше за њим, и не знадијаше да је то истина што анђео чињаше, него мишљаше да види утвару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'А кад прођоше прву стражу и другу и дођоше к вратима гвозденијем која вођаху у град, она им се сама отворише; и изишавши прођоше једну улицу, и анђео одмах отступи од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'И кад дође Петар к себи рече: сад заиста видим да Бог посла анђела својега те ме избави из руку Иродовијех и од свега чекања народа Јеврејскога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'И размисливши дође кући Марије матере Јована који се зваше Марко, гдје бијаху многи сабрани и мољаху се Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'А кад куцну Петар у врата од двора, приступи дјевојка по имену Рода, да чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'И познавши глас Петров од радости не отвори врата, него утрча и каза да Петар стоји пред вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'А они јој рекоше: јеси ли ти луда? А она потврђиваше да је тако. А они говораху: анђео је његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'А Петар једнако куцаше. А кад отворише, видјеше га, и удивише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'А он махнувши на њих руком да ћуте, каза им како га Господ изведе из тамнице; и рече: јавите ово Јакову и браћи. И изишавши отиде на друго мјесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'А кад би дан, бјеше не мала буна међу војницима, шта то би од Петра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'А кад га Ирод заиска и не нађе, онда испита стражаре, и заповједи да их одведу; и изишавши из Јудеје у Ћесарију онамо живљаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Јер се Ирод срђаше на Тирце и Сидонце. Али они једнодушно дођоше к њему, и узевши на своју руку Власта, постељника царева, искаху мира, јер се њихове земље храњаху од његова царства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'А у одређени дан обуче се Ирод у царску хаљину, и сједавши на пријесто говораше им;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'А народ викаше: ово је глас Божиј, а не човјечиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Али уједанпут удари га анђео Господњи: јер не даде славе Богу; и будући изједен од црви издахну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'А ријеч Божија растијаше и множаше се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'А Варнава и Савле предавши помоћ вратише се из Јерусалима у Антиохију, узевши са собом Јована који се зваше Марко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'А у цркви која бјеше у Антиохији бијаху неки пророци и учитељи, то јест: Варнава и Симеун који се зваше Нигар, и Лукије Киринац, и Манаил одгајени с Иродом четверовласником, и Савле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'А кад они служаху Господу и пошћаху, рече Дух свети: одвојте ми Варнаву и Савла на дјело на које их позвах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Тада постивши и помоливши се Богу метнуше руке на њих, и отпустише их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Ови дакле послани од Духа светога сиђоше у Селеукију, и оданде отпловише у Кипар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'И дошавши у Саламин јавише ријеч Божију у зборницама Јеврејскима; а имаху и Јована слугу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'А кад прођоше острво тја до Пафа, нађоше некаквога човјека врачара, и лажна пророка, Јеврејина, коме бјеше име Варисус,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Који бјеше с намјесником Срђем Павлом, човјеком разумнијем. Овај дозвавши Варнаву и Савла заиска да чује ријеч Божију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'А Елима врачар (јер то значи име његово) стаде им се супротити, гледајући да одврати намјесника од вјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'А Савле који се зваше и Павле, пун Духа светога погледавши на њ');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'Рече: о напуњени свакога лукавства и сваке пакости, сине ђавољи! непријатељу сваке правде! зар не престајеш кварити правијех путова Господњијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'И сад ето руке Господње на те, и да будеш слијеп да не видиш сунца за неко вријеме. И уједанпут нападе на њ мрак и тама, и пипајући тражаше вођа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Тада намјесник, кад видје шта би, вјерова, дивећи се науци Господњој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'А кад се Павле са својијем друштвом одвезе из Пафа, дођоше у Пергу Памфилијску; а Јован се одвоји од њих, и врати се у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'А они отишавши из Перге дођоше у Антиохију Писидијску, и ушавши у зборницу у дан суботни сједоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'А по читању закона и пророка послаше старјешине зборничке к њима говорећи: људи браћо! ако је у вама ријеч утјехе за народ, говорите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'А Павле уставши и махнувши руком рече: људи Израиљци и који се Бога бојите! чујте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Бог народа овога изабра оце наше, и подиже народ кад бијаху дошљаци у земљи Мисирској, и руком високом изведе их из ње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'И до четрдесет година прехрани их у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'И затрвши седам народа у земљи Ханаанској на коцке раздијели им земљу њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'И потом на четири стотине и педесет година даде им судије до Самуила пророка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'И од тада искаше цара, и даде им Бог Саула, сина Кисова, човјека од кољена Венијаминова, за четрдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'И уклонивши њега подиже им Давида за цара, коме и рече свједочећи: нађох Давида сина Јесејева, човјека по срцу мојему, који ће испунити све воље моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Од његова сјемена подиже Бог по обећању Израиљеву спаса Исуса;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Кад Јован пред његовијем доласком проповиједа крштење покајања свему народу Израиљеву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'И кад свршиваше Јован течење своје, говораше: ко мислите да сам ја нијесам ја; него ево иде за мном, коме ја нијесам достојан раздријешити ремена на обући његовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Људи браћо! синови рода Авраамова, и који се међу вама Бога боје! вама се посла ријеч овога спасенија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Јер они што живе у Јерусалиму, и кнезови њихови, не познаше овога и гласове пророчке који се читају сваке суботе, осудивши га извршише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'И не нашавши ниједне кривице смртне молише Пилата да га погуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'И кад свршише све што је писано за њега, скинуше га с дрвета и метнуше у гроб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'А Бог васкрсе га из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'И показива се много дана онима што излазише с њим из Галилеје у Јерусалим, који су сад свједоци његови пред народом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'И ми вам јављамо обећање које би оцевима нашима да је ово Бог испунио нама, дјеци њиховој, подигнувши Исуса;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Као што је написано и у другом псалму: ти си мој син, ја те данас родих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'А да га из мртвијех васкрсе да се више не врати у трухљење овако рече: даћу вам светињу Давидову вјерну.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Зато и на другом мјесту говори: нећеш дати да твој светац види трухљења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Јер Давид послуживши роду својему по вољи Божијој умрије, и метнуше га код отаца његовијех, и видје трухљења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'А којега Бог подиже не видје трухљења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Тако да вам је на знање, људи браћо! да се кроза њ вама проповиједа опроштење гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'И од свега, ода шта се не могосте оправдати у закону Мојсијеву, оправдаће се у њему сваки који вјерује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Гледајте дакле да не дође на вас оно што је казано у пророцима:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, 'Видите, немарљиви! и чудите се, и нек вас нестане; јер ја чиним дјело у ваше дане, дјело које нећете вјеровати ако вам ко усказује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'А кад излажаху из зборнице Јеврејске, мољаху незнабошци да им се ове ријечи у другу суботу говоре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'А кад се сабор разиђе, пођоше за Павлом и за Варнавом многи од Јевреја и побожнијех дошљака; а они говорећи им свјетоваху их да остану у благодати Божијој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'А у другу суботу сабра се готово сав град да чују ријечи Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'А кад видјеше Јевреји народ, напунише се зависти, и говораху противно ријечима Павловијем насупрот говорећи и хулећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'А Павле и Варнава ослободивши се рекоше: вама је најприје требало да се говори ријеч Божија; али кад је одбацујете, и сами се показујете да нијесте достојни вјечнога живота, ево се обрћемо к незнабошцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Јер нам тако заповједи Господ: поставих те за видјело незнабошцима, да будеш спасеније до самога краја земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'А кад чуше незнабошци, радоваху се и слављаху ријеч Божију, и вјероваше колико их бјеше приправљено за живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'И ријеч се Божија разношаше по свој околини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Али Јевреји подговорише побожне и поштене жене и старјешине градске те подигоше гоњење на Павла и Варнаву, и истјераше их из своје земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'А они отресавши на њих прах са својијех ногу дођоше у Иконију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'А ученици пуњаху се радости и Духа светога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'У Иконији пак догоди се да они заједно уђоше о зборницу Јеврејску, и говораху тако да вјерова велико мноштво Јевреја и Грка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'А Јевреји који не вјероваху подбунише и раздражише душе незнабожаца на браћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Али они осташе доста времена говорећи слободно у Господу који свједочаше ријеч благодати своје и даваше те се твораху знаци и чудеса рукама њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'А мноштво градско раздијели се, и једни бијаху с Јеврејима, а једни с апостолима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'А кад навалише и незнабошци и Јевреји са својијем поглаварима да им досаде и камењем да их побију,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Они дознавши побјегоше у градове Ликаонске, у Листру и у Дерву и у околину њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'И онамо проповиједаху јеванђеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'И један човјек у Листри сјеђаше немоћан у ногама, и бјеше хром од утробе матаре своје, и не бјеше никад ходио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Овај слушаше Павла гдје говори. Павле погледавши на њ и видјевши да вјерује да ће оздравити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Рече великијем гласом: теби говорим у име Господа Исуса Христа, устани на своје ноге управо. И скочи, и хођаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'А кад видје народ шта учини Павле, подигоше глас свој говорећи Ликаонски: богови начинише се као људи, и сиђоше к нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'И називаху Варнаву Јупитером, а Павла Меркуријем, јер он управљаше ријечју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'А свештеник Јупитера који бјеше пред градом њиховијем доведе јунце, и донесе вијенце пред врата, и с народом шћадијаше да приноси жртву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'А кад чуше апостоли, Варнава и Павле, раздријеше хаљине своје, и скочише међу народ вичући и говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'Људи! шта то чините? И ми смо као и ви смртни људи, који вам проповиједамо јеванђеље да се од овијех лажних ствари обратите к Богу живоме, који створи небо и земљу и море и све што је у њима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Који у прошавшијем нараштајима бјеше пустио све народе да иду својијем путовима:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'И опет не остави себе непосвједочена, чинећи добро, дајући нам с неба дажд и године родне, пунећи срца наша јелом и весељем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'И ово говорећи једва уставише народ да им не приносе жртве, него да иде сваки својој кући. А док они живљаху ондје и учаху,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Дођоше из Антиохије и из Иконије некаки Јевреји, и кад се они препираху слободно, подговорише народ да их одустану, говорећи да ништа право не говоре, него све лажу. И подговоривши народ засуше Павла камењем и извукоше га из града мислећи да је мртав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'А кад га опколише ученици његови, устаде и уђе у град, и сјутрадан изиђе с Варнавом у Дерву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'И проповједивши јеванђеље граду оном и научивши многе вратише се у Листру и Иконију и Антиохију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Утврђујући душе ученика и свјетујући их да остану у вјери, и да нам кроз многе невоље ваља ући у царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'И поставивши им старјешине по свијем црквама, и помоливши се Богу с постом, предадоше их Господу кога вјероваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'И прошавши Писидију дођоше у Памфилију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'И говоривши ријеч Господњу у Перзи сиђоше у Аталију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'И оданде отпловише у Антиохију, одакле бијаху предани благодати Божијој на дјело које свршише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'А кад дођоше и сабраше цркву, казаше све шта учини Бог с њима, и како отвори незнабошцима врата вјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'И осташе ондје не мало времена с ученицима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'И неки сишавши из Јудеје учаху браћу: ако се не обрежете по обичају Мојсијеву, не можете се спасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'А кад поста распра, и Павле и Варнава не мало се препираше с њима, одредише да Павле и Варнава и други неки од њих иду горе к апостолима и старјешинама у Јерусалим за ово питање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'А они онда спремљени од цркве, пролажаху кроз Финикију и Самарију казујући обраћање незнабожаца, и чињаху велику радост свој браћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'А кад дођоше у Јерусалим, прими их црква и апостоли и старјешине, и казаше све што учини Бог с њима, и како отвори незнабошцима врата вјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Онда усташе неки од јереси фарисејске који бијаху вјеровали, и говораху да их ваља обрезати, и заповједити да држе закон Мојсијев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'А апостоли и старјешине сабраше се да извиде ову ријеч.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'И по многом вијећању уста Петар и рече: људи браћо! ви знате да Бог од првијех дана изабра између нас да из мојијех уста чују незнабошци ријеч јеванђеља и да вјерују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'И Бог, који познаје срца, посвједочи им и даде им Духа светога као и нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'И не постави никакве разлике међу нама и њима, очистивши вјером срца њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Сад дакле шта кушате Бога и хоћете да метнете ученицима јарам на врат, којега ни оцеви наши ни ми могосмо понијети?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Него вјерујемо да ћемо се спасти благодаћу Господа Исуса Христа као и они.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Онда умуче све мноштво, и слушаху Варнаву и Павла који приповиједаху колике знаке и чудеса учини Бог у незнабошцима преко њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'А кад они умукоше, одговори Јаков говорећи: људи браћо! послушајте мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Симон каза како Бог најприје походи и прими из незнабожаца народ к имену својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'И с овијем се ударају ријечи пророка, као што је написано:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Потом ћу се вратити, и сазидаћу дом Давидов, који је пао, и његове развалине поправићу, и подигнућу га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Да потраже Господа остали људи и сви народи у којима се име моје спомену, говори Господ који твори све ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Богу су позната од постања свијета сва дјела његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Зато ја велим да се не дира у незнабошце који се обраћају к Богу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'Него да им се заповједи да се чувају од прилога идолскијех и од курварства и од удављенога и од крви, и што њима није мило другима да не чине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Јер Мојсије има од старијех времена у свијем градовима који га проповиједају, и по зборницама чита се сваке суботе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Тада нађоше за добро апостоли и старјешине са свом црквом да изберу између себе двојицу и да пошљу у Антиохију с Павлом и Варнавом, Јуду који се зваше Варсава, и Силу, људе знамените међу браћом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'И написаше рукама својима ово: Апостоли и старјешине и браћа поздрављају браћу која су по Антиохији и Сирији и Киликији што су од незнабожаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Будући да ми чусмо да неки од нас изишавши сметоше вас ријечима, и раслабише душе ваше говорећи вам да се обрезујете и да држите закон, којима ми не заповједисмо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'Зато нађосмо за добро ми једнодушно сабрани избране људе послати вама с љубазнијем нашијем Варнавом и Павлом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'С људима који су предали душе своје за име Господа нашега Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Посласмо дакле Јуду и Силу, који ће то и ријечима казати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Јер нађе за добро свети Дух и ми да никаквијех тегоба више не мећемо на вас осим овијех потребнијех:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'Да се чувате од прилога идолскијех и од крви и од удављенога и од курварства, и што нећете да се чини вама не чините другима; од чега ако се чувате, добро ћете чинити. Будите здрави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'А кад их опремише, дођоше у Антиохију, и сабравши народ предаше посланицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'А кад прочиташе, обрадоваше се утјеси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'А Јуда и СИла, који и пророци бијаху, многијем ријечима утјешише браћу и утврдише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'И пошто бише онамо неко вријеме, отпустише их браћа с миром к апостолима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'Сила нађе за добро да остане онамо, А Јуда се врати у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'А Павле и Варнава живљаху у Антиохији и учаху и проповиједаху ријеч Господњу с многима другијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'А послије неколико дана рече Павле Варнави: хајде да се вратимо и да обиђемо браћу по свијем градовима по којима проповиједасмо ријеч Господњу како живе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'А Варнава шћаше да узму са собом Јована прозванога Марка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Павле пак говораше: онога који нас је одустао у Памфилији и није ишао с нама на дјело на које смо били одређени, да не узимамо са собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Тако постаде распра да се они раздвојише, и Варнава узевши Марка отплови у Кипар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'А Павле избравши Силу изиђе предан благодати Божијој од браће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'И пролажаше кроз Сирију и Киликију утврђујући цркве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Дође пак у Дерву и у Листру, и гле, ондје бјеше неки ученик, по имену Тимотије, син неке жене Јеврејке која вјероваше, а оца Грка;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'За њега добро свједочаху браћа која бијаху у Листри и у Иконији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Овога намисли Павле да узме са собом; и узе га, и обреза Јевреја ради који бијаху у онијем мјестима: јер сви знадијаху оца његова да бјеше Грк.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'И кад пролажаху по градовима, предаваше им да држе уредбе које уредише апостоли и старјешине у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'А цркве се утврђиваху у вјери, и сваки дан биваше их више.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'А кад прођоше Фригију и Галатијску земљу, забрани им Дух свети говорити ријеч у Азији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'А кад дођоше у Мисију шћадијаху да иду у Витинију, и Дух не даде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'А кад прођоше Мисију, сиђоше у Троаду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'И Павлу се јави утвара ноћу: бјеше један човјек из Маћедоније, и стајаше молећи га и говорећи: дођи у Маћедонију и помози нам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'А кад видје утвару, одмах гледасмо да изиђемо у Маћедонију, дознавши да нас Господ позва да им проповиједамо јеванђеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'А кад се одвезосмо из Троаде, дођосмо у Самотрак, и сјутрадан у Неапољ,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'А оданде у Филибу, које је први град земље Маћедоније, насеље Римско; и у оном граду остасмо неколико дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'А у дан суботни изиђосмо из града к води гдје бјеше богомоља; и сједавши говорисмо к женама које се бијаху сабрале.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'И једна богобојазна жена, по имену Лидија, из града Тијатирскога, која продаваше скерлет, слушаше: и Господ отвори срце њезино да пази на ријечи Павлове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'А кад се крсти она и кућа њезина, мољаше нас говорећи: ако мислите да ја вјерујем Господа, уђите у моју кућу и живите. И натјера нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'А догоди се кад иђасмо на молитву да нас срете једна робиња која имаше дух погађачки и врачајући доношаше велики добитак својијем господарима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Ова пође за Павлом и за нама, и викаше говорећи: ови су људи слуге Бога највишега, који јављају нама пут спасенија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'И овако чињаше много дана. А кад се Павлу досади, окрену се и рече духу: заповиједам ти именом Исуса Христа, изиђи из ње. И изиђе у тај час.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'А кад видјеше њезини господари да изиђе над њихова добитка, узеше Павла и Силу и одвукоше их на пазар ка кнезовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'И доведавши их к војводама, рекоше: ови су људи Јевреји, и муте по нашему граду,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'И проповиједају обичаје које нама не ваља примати ни творити, јер смо Римљани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'И слеже се народ на њих, и војводе издријеше им хаљине, и заповједише да их шибају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'И пошто их здраво избише бацише их у тамницу, и заповједише тамничару да их добро чува.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Примивши такову заповијест он их баци у најдоњу тамницу и ноге им метну у кладе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'А у поноћи бијаху Павле и Сила на молитви и хваљаху Бога; а сужњи их слушаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'А уједанпут тако се врло затресе земља да се помјести темељ тамнички; и одмах се отворише сва врата и свима спадоше окови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'А кад се пробуди тамничар и видје отворена врата тамничка, извади нож и шћаше да се убије, мислећи да су побјегли сужњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'А Павле повика здраво говорећи: не чини себи зла никаква, јер смо ми сви овдје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'А он заискавши свијећу улетје и дркћући припаде к Павлу и Сили;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'И изведавши их напоље рече: господо! шта ми треба чинити да се спасем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'А они рекоше: вјеруј Господа Исуса Христа и спашћеш се ти и сав дом твој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'И казаше му ријеч Господњу, и свима који су у дому његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'И узе их у онај сахат ноћи и опра им ране; и крсти се он и сви његови одмах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'И уведавши их у свој дом постави трпезу, и радоваше се са свијем домом својијем што вјерова Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'А кад би дан, послаше војводе пандуре говорећи: пустите ова два човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'А тамничар каза ријечи ове Павлу: послаше војводе да се пустите; сад дакле изиђите и идите с миром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'А Павле рече њима: избивши нас пред народом без суда, људе Римљане, бацише у тамницу: и сад хоће да нас пусте? Није тако, него сами нека дођу и изведу нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'А пандури казаше војводама ове ријечи; и уплашише се кад чуше да су Римљани;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'И дошавши умолише их, и изведоше молећи да изиђу из града.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'А кад изиђоше из тамнице, дођоше к Лидији, и видјевши браћу утјешише их, и отидоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Прошавши пак Амфипољ и Аполонију дођоше у Солун, гдје бјеше зборница Јеврејска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'И Павле по обичају своме уђе к њима, и три суботе разговара се с њима из писма,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Показујући и доказујући им да је требало Христос да пострада и васкрсе из мртвијех, и да овај Исус којега ја, рече, проповиједам вама, јест Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'И неки од њих вјероваше, и присташе с Павлом и са Силом, и од побожнијех Грка мноштво велико, и од жена господскијех не мало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Али тврдоврати Јевреји завиђаху, и узевши неке зле људе од простога народа, и сабравши чету, узбунише по граду, и нападоше на кућу Јасонову, и тражаху да их изведу пред народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'А кад њих не нађоше, повукоше Јасона и неке од браће пред старјешине градске вичући: ови што замутише васиони свијет дођоше и овдје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Које Јасон прими; и ови сви раде против ћесаревијех заповијести, говорећи да има други цар, Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'И смутише народ и старјешине градске који ово чуше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Али кад их Јасон и остали задовољише одговором, пустише их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'А браћа одмах ноћу оправише Павла и Силу у Верију. Дошавши онамо уђоше у зборницу Јеврејску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Ови пак бијаху племенитији од оних што живе у Солуну; они примише ријеч са свијем срцем, и сваки дан истраживаху по писму је ли то тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Тако вјероваше многи од њих, и од поштенијех Грчкијех жена и од људи не мало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'А кад разабраше Јевреји Солунски да Павле у Верији проповиједи ријеч Божију, дођоше и онамо те уздигоше и побунише народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'А браћа онда одмах отправише Павла да иде у приморје; а Сила и Тимотије осташе ондје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'А пратиоци доведоше Павла до Атине: и примивши заповијест на Силу и Тимотија да дођу к њему што брже, вратише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'А кад их Павле чекаше у Атини, раздражи се дух његов у њему гледајући град пун идола;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'И препираше се с Јеврејима и богобојазнима у зборници, и на пазару сваки дан с онима с којима се удешаваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'А неки од Епикуроваца и од Стојичкијех мудраца препираху се с њим; и једни говораху: шта хоће овај беспослица? А други: види се као да хоће нове богове да проповиједа. Јер им проповиједаше јеванђеље о Исусу и о васкрсенију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Па га узеше и одведоше на Ареопаг говорећи: можемо ли разумјети каква је та нова наука што ти казујеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Јер нешто ново мећеш у наше уши; хоћемо дакле да видимо шта ће то бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'А Атињани сви и путници из другијех земаља не бијаху ни за што друго него да што ново казују или слушају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'А Павле ставши насред Ареопага рече: људи Атињани! по свему вас видим да сте врло побожни;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Јер пролазећи и мотрећи ваше светиње нађох олтар на коме бјеше написано: Богу непознатоме. Којега дакле не знајући поштујете онога вам ја проповиједам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Бог који је створио свијет и све што је у њему, он будући господар неба и земље, не живи у рукотворенијем црквама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Нити прима угађања од руку човјечијех, као да би ономе требало што који сам даје свима живот и дихање и све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'И учинио је да од једне крви сав род човјечиј живи по свему лицу земаљскоме, и поставио је напријед одређена времена и међе њиховога живљења:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Да траже Господа, не би ли га барем опипали и нашли, премда није далеко ни од једнога нас;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Јер кроз њега живимо, и мичемо се, и јесмо; као што и неки од вашијех пјевача рекоше: јер смо и род његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Кад смо дакле род Божиј, не треба да мислимо да је Божанство као иконе златне или сребрне или камене, које су људи мајсторски начинили по смишљању своме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Не гледајући дакле Бог на времена незнања, сад заповиједа свима људима свуда да се покају;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Јер је поставио дан у који ће судити васиономе свијету по правди преко човјека кога одреди, и даде свима вјеру васкрснувши га из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'А кад чуше васкрсеније из мртвијех, онда се једни ругаху; а једни рекоше: да те чујемо опет о том.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'Тако Павле отиде између њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'А неки људи присташе уза њ и вјероваше; међу којима бјеше и Ђонисије Ареопагитски, и жена по имену Дамара, и други с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Потом се одлучи Павле од Атине и дође у Коринт,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'И нађе једнога Јеврејина, по имену Акилу, родом из Понта, који бјеше скоро дошао из Талијанске са женом својом Прискилом (јер бјеше заповједио Клаудије да сви Јевреји иду из Рима), и дође к њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'И будући да бјеше онога истог заната, оста код њих и рађаше, јер бијаху ћилимарског заната.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'А препираше се у зборницама сваке суботе, и надговараше Јевреје и Грке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'И кад сиђоше из Маћедоније Сила и Тимотије, навали Дух свети на Павла да свједочи Јеврејима да је Исус Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'А кад се они противљаху и хуљаху, отресе хаљине своје и рече им: крв ваша на ваше главе; ја сам чист, отсад идем у незнабошце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'И отишавши оданде дође у кућу некога по имену Јуста, који поштовеше Бога, и којега кућа бјеше крај зборнице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'А Крисп, старјешина зборнички, вјерова Господа са свијем домом својијем; и од Коринћана многи који слушаху вјероваше и крстише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'А Господ рече Павлу ноћу у утвари: не бој се, него говори, и да не ућутиш;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Јер сам ја с тобом, и нико се неће усудити да ти што учини; јер ја имам велики народ у овоме граду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'И он сједи ондје годину и шест мјесеци учећи их ријечи Божијој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'А кад бјеше Галион намјесник у Ахаји, нападоше Јевреји једнодушно на Павла и доведоше на суд');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'Говорећи: овај наговара људе да поштују Бога против закона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'А кад Павле шћаше да отвори уста, рече Галион Јеврејима: да је каква неправда била или зло дјело, по дужности послушао бих вас, о Јевреји!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Али кад су препирања за ријечи и за имена и за закон ваш, гледајте сами; јер ја судија томе нећу да будем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'И изагна их из суднице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Онда сви Грци ухватише Состена, старјешину зборничкога, и бише га пред судницом; и Галион није ништа за то марио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'А Павле оста још позадуго, и опростивши се с браћом отплови у Сирију и с њиме Прискила и Акила, и остриже главу у Кенхреји, јер се бјеше завјетовао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'И дође у Ефес; и њих остави ондје, а он уђе у зборницу, и препираше се с Јеврејима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'А кад га они молише да остане код њих више времена, не хтједе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Него се опрости с њима говорећи: ваља ми, макар како било, овај празник што иде провести у Јерусалиму; него, ако Бог хтједбуде, вратићу се опет к вама. И одвезе се из Ефеса; а Акила и Прискила осташе у Ефесу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'И дошавши у Ћесарију, изиђе и поздрави се с црквом, и сиђе у Антиохију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'И проведавши неколико времена изиђе и прође редом Галатијску земљу и Фригију утврђујући све ученике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'А дође у Ефес један Јеврејин, по имену Аполос, родом из Александрије, човјек рјечит и силан у књигама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Овај бјеше упућен на пут Господњи, и горећи духом, говораше и учаше право о Господу, а знадијаше само крштење Јованово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'И овај поче слободно проповиједати по зборницама. А кад га чуше Акила и Прискила, примише га и још му боље показаше пут Господњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'А кад он шћаше да пријеђе у Ахају, послаше браћа напријед и писаше ученицима да га приме. И он дошавши онамо поможе много онима који вјероваху благодаћу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Јер здраво надвлађиваше Јевреје једнако пред народом доказујући из писма да је Исус Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Догоди се пак, кад бјеше Аполос у Коринту, да Павле пролажаше горње земље, и дође у Ефес, и нашавши неке ученике');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Рече им: јесте ли примили Духа светога кад сте вјеровали? А они му рекоше: нијесмо ни чули да има Дух свети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'А он им рече: на што се дакле крстисте? А они рекоше: на крштење Јованово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'А Павле рече: Јован крсти крштењем покајања, говорећи народу да вјерују онога који ће за њим доћи, то јест, Христа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'А кад то чуше, крстише се у име Господа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'А кад Павле метну руке на њих, сиђе Дух свети на њих, и говораше језике и прорицаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'А бијаше људи свега око дванаест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'И ушавши у зборницу говораше слободно три мјесеца учећи и увјеравајући за царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'А кад неки бијаху отврднули и свађаху се хулећи на пут Господњи пред народом, отступи од њих и одлучи ученике, па се препираше сваки дан у школи некога Тирана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'И ово је бивало двије године, тако да сви који живљаху у Азији, и Јевреји и Грци, чуше ријеч Господа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'И Бог чињаше не мала чудеса рукама Павловијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'Тако да су и чалме и убрушчиће знојаве од тијела његова носили на болеснике, и они се исцјељиваху од болести, и духови зли излажаху из њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'И почеше неки од Јевреја, који се скитаху и заклињаху ђаволе, спомињати над онима у којима бијаху зли духови име Господа Исуса говорећи: заклињемо вас Исусом кога Павле проповиједа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'А бијаху некијех седам синова Скеве Јеврејина, поглавара свештеничкога, који ово чињаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'А дух зли одговарајући рече: Исуса познајем, и Павла знам; али ви ко сте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'И скочивши на њих човјек у коме бјеше зли дух надвлада их, и притиште их пода се тако да голи и израњени утекоше из оне куће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'И ово дознадоше сви који живљаху у Ефесу, и Јевреји, и Грци; и уђе страх у све њих, и величаше се име Господа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'И многи од онијех што вјероваху, долажаху те се исповиједаху и казиваху шта су учинили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'А многи од онијех који чараху, сабравши књиге своје спаљиваху их пред свима; и прорачунише и нађоше да су вриједеле педесет хиљада гроша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Тако здраво растијаше и надвлађиваше ријеч Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'И кад се ово сврши, намисли Павле да прође преко Маћедоније и Ахаје, и да иде у Јерусалим, и рече: пошто будем тамо, ваља ми и Рим видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'И посла у Маћедонију двојицу од онијех који га служаху, Тимотија и Ераста; а он оста неко вријеме у Азији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'А у оно вријеме подиже се не мала буна пута ради Господњега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Јер некакав златар, по имену Димитрије, који грађаше Дијани сребрне црквице и даваше мајсторима не мали посао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Он скупи ове и другијех оваковијех ствари мајсторе, и рече: људи! ви знате да од овога посла ми имамо добитак за своје живљење;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'И видите и чујете да не само у Ефесу него готово по свој Азији овај Павле одврати народ многи, говорећи: то нијесу богови што се рукама човјечијим граде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'И не само што ће ова несрећа доћи на наш занат да не пролази, него се неће марити ни за цркву велике богиње Дијане, и пропашће величанство оне коју сва Азија и васиони свијет поштује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'А кад они ово чуше, напунише се гњева, и викаху говорећи: велика је Дијана Ефеска!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'И сав се град напуни буне; и наваливши једнодушно на збориште ухватише Гаја и Аристарха из Маћедоније, другове Павлове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'А кад Павле шћаше да иде међу народ, не дадоше му ученици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'А неки и од Азијскијех поглавара који му бијаху пријатељи, послаше к њему свјетујући га да не излази на збориште.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Једни пак викаху једно а други друго; јер бијаше сабор смућен, и највише их не знадијаху зашто су се скупили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'А једни од народа извукоше Александра, кад га Јевреји изведоше. А Александар махнувши руком шћаше да одговори народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'А кад га познаше да је Јеврејин, повикаше сви у глас, и викаху око два сахата: велика је Дијана Ефеска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'А писар утишавши народ рече: људи Ефесци! Ко је тај човјек који не зна да град Ефес слави велику богињу Дијану и њезин кип небески?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Кад дакле то не може нико одрећи, ваља ви да будете мирни, и ништа нагло да не чините;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Јер доведосте ове људе који нити су цркву Дијанину покрали, нити хуле на вашу богињу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'А Димитрије и мајстори који су с њим ако имају какву тужбу, имају судови, и имају намјесници, нека туже један другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Ако ли што друго иштете, нека се извиди на правој скупштини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Јер се бојимо да не будемо тужени за данашњу буну; а ниједнога узрока нема којијем бисмо се могли оправдати за ову буну. И ово рекавши распусти народ који се бјеше сабрао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'А пошто се утиша буна, дозва Павле ученике, и утјешивши их опрости се с њима, и изиђе да иде у Маћедонију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'И прошавши оне земље, и свјетовавши их многијем ријечима, дође у Грчку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Поживљевши пак онамо три мјесеца стадоше му Јевреји радити о глави кад шћаше да се одвезе у Сирију, и намисли да се врати преко Маћедоније.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'И пође с њим до Азије Сосипатар Пиров из Верије, и Аристарх и Секунд из Солуна, и Гај из Дерве и Тимотије, и Тихик и Трофим из Азије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Ови отишавши напријед чекаху нас у Троади.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'А ми се одвезосмо послије дана пријеснијех хљебова из Филибе, и дођосмо к њима у Троаду за пет дана, и ондје остасмо седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'А у први дан недјеље, кад се сабраше ученици да ломе хљеб, говораше им Павле, јер шћаше сјутрадан да пође, и протеже бесједу до поноћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'И бијаху многе свијеће горе у соби гдје се бијасмо сабрали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'А сјеђаше на прозору једно момче, по имену Евтих, надвладано од тврдога сна, и кад Павле говораше много, наже се у сну и паде доље с трећега пода, и дигоше га мртва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'А Павле сишавши паде на њ, и загрливши га рече: не буните се, јер је душа његова у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Онда изиђе горе, и преломивши хљеб окуси, и довољно говори до саме зоре, и тако отиде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'А момче доведоше живо, и утјешише се не мало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'А ми дошавши у лађу одвезосмо се у Ас, и оданде шћасмо да узмемо Павла; јер тако бјеше заповједио, хотећи сам да иде пјешице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'А кад се саста с нама у Асу, узесмо га, и дођосмо у Митилину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'И оданде одвезавши се дођосмо сјутрадан према Хију; а други дан одвезосмо се у Сам, и ноћисмо у Тригилију; и сјутрадан дођосмо у Милит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Јер Павле намисли да прођемо мимо Ефес да се не би задржао у Азији; јер хићаше, ако буде могуће, да буде о Тројичину дне у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Али из Милита посла у Ефес и дозва старјешине црквене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'И кад дођоше к њему, рече им: ви знате од првога дана кад дођох у Азију како с вама једнако бих');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Служећи Господу са сваком понизности и многијем сузама и напастима које ми се догодише од Јевреја који ми рађаху о глави;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Како ништа корисно не изоставих да вам не кажем и да вас научим пред народом и по кућама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Свједочећи и Јеврејима и Грцима покајање к Богу и вјеру у Господа нашега Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'И сад ево ја свезан Духом идем у Јерусалим не знајући шта ће ми се у њему догодити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'Осим да Дух свети по свијем градовима свједочи, говорећи да ме окови и невоље чекају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Али се ни за што не бринем, нити марим за свој живот, него да свршим течење своје с радошћу и службу коју примих од Господа Исуса: да посвједочим јеванђеље благодати Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'И ево сад знам да више нећете видјети мојега лица, ви сви по којима пролазих проповиједајући царство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Зато вам свједочим у данашњи дан да сам ја чист од крви свију;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Јер не изоставих да покажем вољу Божију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Пазите дакле на себе и на све стадо у коме вас Дух свети постави владикама да пасете цркву Господа и Бога коју стече крвљу својом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Јер ја ово знам да ће по одласку моме ући међу вас тешки вуци који неће штедјети стада;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'И између вас самијех постаће људи који ће говорити изврнуту науку да одвраћају ученике за собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Зато гледајте и опомињите се да три године дан и ноћ не престајах учећи са сузама свакога од вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'И сад вас, браћо, предајем Богу и ријечи благодати његове, који може назидати и дати вам нашљедство међу свима освећенима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Сребра, или злата, или руха ни у једнога не заисках.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Сами знате да потреби мојој и онијех који су са мном били послужише ове руке моје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Све вам показах да се тако ваља трудити и помагати немоћнима, и опомињати се ријечи Господа Исуса коју он рече: много је блаженије давати неголи узимати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'И ово рекавши клече на кољена своја са свима њима и помоли се Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'А свију стаде велики плач и загрливши Павла цјеливаху га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Жалосни највише за ријеч коју рече да више неће видјети лица његова; и отпратише га у лађу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'И кад би те се одвезосмо отргнувши се од њих, идући право дођосмо у Ко, и други дан у Род и оданде у Патару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'И нашавши лађу која полази у Финикију, уђосмо и одвезосмо се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'А кад нам се указа Кипар, остависмо га налијево, и пловљасмо у Сирију, и стадосмо у Тиру; јер ондје ваљаше да се истовари лађа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'И нашавши ученике остасмо ондје седам дана: они Павлу говораху Духом да не иде горе у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'А кад би те ми дане навршисмо, изишавши иђасмо, и праћаху нас сви са женама и дјецом до иза града, и клекнувши на бријегу помолисмо се Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'И опростивши се један с другијем уђосмо у лађу; а они се вратише својијем кућама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'А ми почевши пловљење од Тира, дођосмо у Птолемаиду; и поздравивши се с браћом остасмо код њих један дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'А сјутрадан пошавши Павле и који бијасмо с њим дођосмо у Ћесарију; и ушавши у кућу Филипа јеванђелиста, који бјеше један од седам ђакона, остасмо у њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'И овај имаше четири кћери дјевојке које прорицаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Стојећи ми пак ондје много дана, дође одозго из Јудеје један пророк, по имену Агав;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'И дошавши к нама узе појас Павлов и свезавши своје руке и ноге рече: тако вели Дух свети: човјека којега је овај појас, овако ће га свезати у Јерусалиму Јевреји, и предаће га у руке незнабожаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'И кад чусмо ово, молисмо и ми и ондашњи да не иде горе у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'А Павле одговори и рече: шта чините те плачете и цијепате ми срце? Јер ја не само свезан бити хоћу, него и умријети у Јерусалиму готов сам за име Господа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'А кад га не могасмо одвратити, умукосмо рекавши: воља Божија нека буде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'А послије овијех дана спремивши се изиђосмо у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'А дођоше с нама и неки ученици из Ћесарије водећи са собом некога Мнасона из Кипра, старога ученика, у којега бисмо ми стајали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'И кад дођосмо у Јерусалим, примише нас браћа љубазно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'А сјутрадан отиде Павле с нама к Јакову, и дођоше све старјешине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'И поздравивши се с њима казиваше све редом шта учини Бог у незнабошцима његовом службом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'А они чувши хваљаху Бога и рекоше му: видиш ли, брате! колико је хиљада Јевреја који вјероваше, и сви теже на стари закон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'А дознали су за тебе да учиш отпадању од закона Мојсијева све Јевреје који живе међу незнабошцима, казујући да им не треба обрезивати дјеце своје, нити држати обичаја отачкијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Шта ћемо дакле сад? народ ће се сабрати јамачно; јер ће чути да си дошао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'Ово дакле учини што ти речемо: у нас имају четири човјека који су се завјетовали Богу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Ове узми и очисти се с њима, и потроши на њих нека остригу главе своје, и сви ће дознати да оно што су чули за тебе ништа није, него да и сам држиш закон и живиш по њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'А за незнабошце који вјероваше ми посласмо пресудивши да они таково ништа не држе осим да се чувају од прилога идолскијех, и од крви, и од удављенога, и од курварства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Тада Павле узе оне људе, и сјутрадан очистивши се с њима, уђе у цркву, и показа како извршује дане очишћења докле се не принесе жртва за свакога њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'А кад шћаше да се наврши седам дана, видјевши га у цркви они Јевреји што бијаху из Азије, побунише сав народ, и метнуше руке на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Вичући: помагајте, људи Израиљци! ово је човјек који против народа и закона и против овога мјеста учи све свуда; па још и Грке уведе у цркву и опогани свето мјесто ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Јер бијаху видјели с њим у граду Трофима из Ефеса, којега мишљаху да је увео Павле у цркву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'И сав се град подиже, и навали народ са свију страна, и ухвативши Павла вуцијаху га напоље из цркве; и одмах се затворише врата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'А кад шћаху да га убију, дође глас горе к војводи од чете да се побуни сав Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'А он одмах узевши војнике и капетане дотрча на њих. А они видјевши војводу и војнике престаше бити Павла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'А војвода приступивши узе га, и заповједи да га метну у двоје вериге, и питаше ко је и шта је учинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'А један викаше једно, а други друго по народу. А кад не може од буне ништа да разумије управо, заповједи да га одведу у око.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'А кад би на басамацима, мораше га војници носити силе ради народа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Јер за њим приста мноштво народа који викаху: погуби га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'А кад шћаше Павле да уђе у око, рече војводи: је ли ми слободно говорити што теби? А он рече: зар умијеш Грчки?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Нијеси ли ти Мисирац који прије овијех дана подбуни и изведе у пустињу четири хиљаде хајдука?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'А Павле рече: ја сам човјек Јеврејин из Тарса, грађанин познатога града у Киликији; него те молим допусти ми да говорим к народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'А кад му допусти, стаде Павле на басамацима и махну руком на народ; и кад поста велика тишина проговори Јеврејским језиком говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Људи, браћо и оцеви! чујте сад мој одговор к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'А кад чуше да им Јеврејскијем језиком проговори, још већа тишина поста. И рече:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Ја сам човјек Јеврејин, који сам рођен у Тарсу Киликијскоме, и одгајен у овоме граду код ногу Гамалииловијех, научен управо отачком закону, и бијах ревнитељ Божиј као што сте ви сви данас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Ја овај пут гоних до саме смрти, вежући и предајући у тамницу и људе и жене,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Као што ми свједочи и поглавар свештенички и све старјешине; од којијех и посланице примих на браћу која живе у Дамаску; и иђах да доведем оне што бијаху онамо свезане у Јерусалим да се муче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'А кад иђах и приближих се к Дамаску, догоди ми се око подне да ме уједанпут обасја велика свјетлост с неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'И падох на земљу, и чух глас, који ми говори: Савле! Савле! зашто ме гониш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'А ја одговорих: ко си ти, Господе? А он ми рече: ја сам Исус Назарећанин, којега ти гониш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'А који бијаху са мном видјеше свјетлост и уплашише се; али не чуше гласа који ми говораше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'А ја рекох: шта ћу чинити, Господе? А Господ ми рече: устани и иди у Дамаск, и тамо ће ти се казати за све шта ти је одређено да чиниш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'И кад обневидјех од силне свјетлости оне, вођаху ме за руку они који бијаху са мном, и дођох у Дамаск.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'А неки Ананија човјек побожан по закону, посвједочен од свију Јевреја који живе у Дамаску,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Дошавши к мени стаде и рече ми: Савле брате! прогледај. И ја у тај час погледах на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'А он ми рече: Бог отаца нашијех изабра те да познаш вољу његову, и да видиш праведника, и да чујеш глас из уста његовијех:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Да му будеш свједок пред свијем људима за ово што си видио и чуо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'И сад шта оклијеваш? Устани и крсти се, и опери се од гријеха својијех, призвавши име Господа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'А догоди се, кад се вратих у Јерусалим и мољах се у цркви Богу, да постадох изван себе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'И видјех га гдје ми говори: похити те изиђи из Јерусалима, јер неће примити свједочанства твојега за мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'И ја рекох: Господе! сами знаду да сам ја метао у тамнице и био по зборницама оне које те вјерују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'И кад се прољеваше крв Стефана свједока твојега, и ја стајах и пристајах на смрт његову, и чувах хаљине онијех који га убијају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'И рече ми: иди, јер ћу ја далеко да те пошљем у незнабошце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'А они га слушаху до ове ријечи, па подигоше глас свој говорећи: узми са земље таковога; јер не треба да живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'А кад они викаху и збациваху хаљине и бацаху прах у небо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'Заповједи војвода да га одведу у око, и рече да га бојем испитају да дозна за какву кривицу тако викаху на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'И кад га притегоше узицама, рече Павле капетану, који стајаше ондје: зар ви можете бити човјека Римљанина, и још без суда?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'А кад чу капетан, приступи к војводи и каза говорећи: гледај шта ћеш чинити; јер је овај човјек Римљанин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'А војвода приступивши рече му: кажи ми јеси ли ти Римљанин? А он рече: да.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'А војвода одговори: ја сам за велику цијену име овога грађанства добио. А Павле рече: а ја сам се и родио с њиме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Онда отступише одмах од њега они што шћадијаху да га испитују; а војвода се уплаши кад разумје да је Римљанин и што га бјеше свезао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'А сјутрадан, желећи дознати истину зашто га туже Јевреји, пусти га из окова, и заповједи да дођу главари свештенички и сав сабор њихов; и сведавши Павла постави га пред њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'А Павле погледавши на скупштину рече: људи браћо! ја са свом добром савјести живљех пред Богом до самога овог дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'А поглавар свештенички Ананија заповједи онима што стајаху код њега да га бију по устима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Тада му рече Павле: тебе ће Бог бити, зиде окречени! И ти сједиш те ми судиш по закону, а преступајући закон заповиједаш да ме бију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'А они што стојаху наоколо рекоше: зар псујеш Божијег поглавара свештеничкога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'А Павле рече: не знадох, браћо, да је поглавар свештенички, јер стоји написано: старјешини народа својега да не говориш ружно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'А знајући Павле да је један дио садукеја а други фарисеја повика на скупштини: људи браћо! ја сам фарисеј и син фарисејев: за над и за васкрсеније из мртвијех доведен сам на суд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'А кад он ово рече, постаде распра међу садукејима и фарисејима, и раздијели се народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Јер садукеји говоре да нема васкрсенија, ни анђела ни духа; а фарисеји признају обоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'И постаде велика вика, и уставши књижевници од стране фарисејске препираху се међу собом говорећи: никакво зло не налазимо на овоме човјеку; ако ли му говори дух или анђео, да се не супротимо Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'А кад поста распра велика, побојавши се војвода да Павла не раскину, заповједи да сиђу војници и да га отму између њих, и да га одведу у око.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'А ону ноћ стаде Господ преда њега и рече: не бој се, Павле, јер као што си свједочио за мене у Јерусалиму, тако ти ваља и у Риму свједочити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'А кад би дан, учинише неки од Јевреја вијећу и заклеше се говорећи да неће ни јести ни пити докле не убију Павла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'А бјеше их више од четрдесет који ову клетву учинише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Ови приступивши ка главарима свештеничкијем и старјешинама, рекоше: клетвом заклесмо се да нећемо ништа окусити док не убијемо Павла;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Сад дакле ви са сабором кажите војводи да га сјутра сведе к вама, као да бисте хтјели дознати боље за њега; а ми смо готови да га убијемо прије него се он приближи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'А син сестре Павлове чувши ову засједу дође и уђе у око и каза Павлу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'А Павле дозвавши једнога од капетана рече: ово момче одведи к војводи, јер има нешто да му каже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'А он га узе и доведе к војводи, и рече: сужањ Павле дозва ме и замоли да ово момче доведем к теби које има нешто да ти говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'А војвода узевши га за руку, и отишавши насамо, питаше га: шта је што имаш да ми кажеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'А оно рече: Јевреји договорише се да те замоле да сјутра сведеш Павла к њима на скупштину, као да би хтјели боље испитати за њега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Али ти их немој послушати, јер га чекају од њих више од четрдесет људи који су се заклели да неће ни јести ни пити докле га не убију; и сад су готови, и чекају твоје обећање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'А војвода онда отпусти момче заповједивши му: ником не казуј да си ми ово јавио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'И дозвавши двојицу од капетана рече: приправите ми двјеста војника да иду до Ћесарије, и седамдесет коњика и двјеста стријелаца, по трећему сахату ноћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'И нека доведу коње да посаде Павла, и да га прате до Филикса судије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'И написа посланицу у којој овако говораше:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Од Клаудија Лисије честитоме Филиксу поздравље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Човјека овога ухватише Јевреји и шћаху да га убију; ја пак дођох с војницима и отех га дознавши да је Римљанин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'И желећи дознати узрок за који га криве сведох га на њихову скупштину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'Тада нађох да га криве за питања закона њихова, а да нема никакве кривице која заслужује смрт или окове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'И дознавши ја уговор Јеврејски о глави овога човјека одмах га послах к теби заповједивши и супарницима његовијем да пред тобом кажу што имају на њ. Здрав буди!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'А војници онда, као што им се заповједи, узеше Павла и одведоше га ноћу у Антипатриду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'А сјутрадан оставивши коњике да иду с њим, вратише се у око.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'А они дошавши у Ћесарију, предаше посланицу судији и изведоше Павла преда њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'А судија прочитавши посланицу запита одакле је; и дознавши да је из Киликије');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Рече: испитаћу те кад супарници твоји дођу. И заповједи да га чувају у двору Иродовом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'А послије пет дана сиђе поглавар свештенички Ананија са старјешинама и с ритором некијем Тертулом, који изиђоше пред судију против Павла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'А кад њега дозваше, поче Тертул тужити га говорећи: што живимо под тобом у великом миру, и правице које се овоме народу чине твојијем промишљањем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'У сваком догађају и свуда, честити Филиксе! примамо са сваком захвалношћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Али да ти много не досађујем, молим те да нас укратко послушаш са својом кротошћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Јер нађосмо овога човјека да је куга, и подиже буну против свију Јевреја по васионом свијету, и да је коловођа јереси Назаретској;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Који се усуди и цркву поганити; кога ми и ухватисмо, и шћасмо да му судимо по закону својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Али дође Лисија војвода, и оте га из нашијех руку на велику силу, и посла к теби,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Заповједивши и нама, који га тужимо, да идемо к теби; а од њега можеш сам испитавши дознати за све ово за што га ми тужимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'А и Јевреји се сложише говорећи да је ово тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'А Павле одговори кад му намаже судија да говори: знајући од много година да си ти праведни судија овоме народу, слободно одговарам за себе:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Ти можеш дознати да нема више од дванаест дана како ја изиђох у Јерусалим да се помолим Богу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'И нити ме у цркви нађоше да коме говорим, или буну да чиним у народу, ни по зборницама, ни у граду,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Нити они могу посвједочити шта теби сад на мене говоре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Ово ти пак признајем да у путу, који ови називају јерес, тако служим Богу отачкоме, вјерујући све што је написано у закону и у пророцима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'И имајући надање на Бога да ће бити васкрсеније мртвима, и праведницима и грјешницима, које и сами ови чекају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'А за ово се и ја трудим да имам чисту савјест свагда и пред Богом и пред људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'И послије много година дођох и донесох милостињу народу своме и приносе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'У томе ме нађоше очишћена у цркви, ни с народом, ни с виком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'А имају и Јевреји неки из Азије којима је требало да дођу преда те, и да се туже ако имају што на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Или ови сами нека кажу, ако су нашли на мени какву кривицу, кад сам стајао на скупштини,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'Осим једнога овога гласа којијем повиках стојећи међу њима: за васкрсеније мртвијех доведосте ме данас на суд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'А кад Филикс чу ово, одгоди им знајући врло добро за овај пут и рече: кад дође Лисија војвода, извидјећу вашу ствар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'А капетану заповједи да се чува Павле, и да му се облакша, и ниједноме од његовијех да се не забрањује послуживати га или долазити к њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'А послије неколико дана дође Филикс са Друсилом женом својом, која бјеше Јеврејка, и дозва Павла да чује од њега вјеру у Христа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'А кад Павле говораше о правди и чистоти и о суду који ће бити, уплаши се Филикс и одговори: иди засад; а кад узимам кад, дозваћу те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'А уз то се и надаше да ће му Павле дати новаца да би га пустио; зато га и често дозиваше и разговараше се с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'А кад се навршише двије године, измијени Филикса Поркије Фист. А Филикс, хотећи Јеврејима учинити на вољу, остави Павла у сужањству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 28, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'А Фист онда примивши власт послије три дана изиђе из Ћесарије у Јерусалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Онда главари свештенички и старјешине Јеврејске тужише му се на Павла, и мољаху га,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Иштући милости против њега, да га пошље у Јерусалим; и наређиваху засједу да га убију на путу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'А Фист одговори да се Павле чува у Ћесарији, а и он ће сам скоро онамо да иде:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Који дакле могу од вас, рече, нека иду са мном, и ако има каква кривица на том човјеку нека га туже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'А пошто би у њих не више од десет дана, сиђе у Ћесарију, и сјутрадан сједавши на судијску столицу заповједи да доведу Павла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'А кад га доведоше, стадоше унаоколо Јевреји који бијаху дошли из Јерусалима, и многе тешке кривице изношаху на Павла, којијех не могаху посвједочити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Кад се он одговараше: нити закону Јеврејскоме, ни цркви, ни ћесару што сагријеших.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Али Фист, хотећи Јеврејима учинити на вољу, одговори Павлу и рече: хоћеш да идеш горе у Јерусалим и ондје да ти судим за то?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'А Павле рече: ја стојим на суду ћесареву, овдје треба да ми се суди: Јеврејима ништа нијесам скривио, као што и ти најбоље знаш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Ако ли сам скривио, или учинио што што заслужује смрт, не марим умријети; ако ли пак ништа нема на мени шта ови на мене потворају, нико ме не може њима предати. Ћесару идем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Тада Фист, поговоривши са савјетницима, одговори: ћесару рече да хоћеш: ћесару ћеш поћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'А пошто прође неколико дана, Агрипа цар и Верникија сиђоше у Ћесарију да походе Фиста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'И будући да ондје много дана осташе, каза Фист цару за Павла говорећи: човјека једнога оставио је Филикс у тамници,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'За којега, кад ја бијах у Јерусалиму, изиђоше преда ме главари свештенички и старјешине Јеврејске молећи да га осудим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Ја им одговорих да није обичај у Римљана да се прије поклони какав човјек на смрт док се оптужени не суочи с онима који га туже, и не прими мјесто да одговара за своју кривицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'А кад се они овдје састаше, никаквога одлагања не учиних, и сјутрадан сједавши на судијску столицу заповједих да доведу човјека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'А око њега ставши супарници ни једне кривице које ја мишљах не изнесоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Него имаху против њега некаква питања о својему сујеверју, и о некаквом Исусу, који је умро па Павле говораше да је жив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'А ја не знајући у овоме послу шта ћу чинити, рекох би ли хтио ићи у Јерусалим и онамо да му се суди за ово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'А кад Павле рече да га чувамо до суда Августова, заповједих да га чувају докле га пошљем к ћесару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'А Агрипа рече Фисту: и ја бих рад чути тога човјека. А он рече: сјутра ћеш га чути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Сјутрадан пак, кад Агрипа и Верникија дођоше с великијем поносом, и уђоше у судницу с војводама и са старјешинама онога града, и кад заповједи Фист, доведоше Павла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'И рече Фист: Агрипа царе! и сви који сте с нама! Видите овога за којега ми све мноштво Јевреја досађиваше и у Јерусалиму и овдје, вичући да не ваља да он више живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'А ја дознавши да он ништа није учинио што заслужује смрт, а и он сам рече да ће да иде к свијетломе ћесару, намислих да га пошљем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'За којега немам шта управо писати господару. Зато га и доведох пред вас, а особито преда те, Агрипа царе, да бих, пошто буде испитивање, имао шта писати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Јер ми се чини лудо сужња послати, а кривице његове не јавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'А Агрипа рече Павлу: допушта ти се да говориш сам за се. Онда Павле пруживши руку одговараше:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'За срећу своју држим, царе Агрипа! што се данас пред тобом одговарам за све што ме потворају Јевреји,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'А највише што знам да ти познајеш све Јеврејске обичаје и препирања. Зато те молим да ме послушаш милостиво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Моје дакле живљење од младости, које је испрва било међу народом мојијем у Јерусалиму, знаду сви Јевреји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Како ме знаду испрва, ако хоће посвједочити, да по познатој јереси наше вјере живљех фарисејски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'И сад стојим пред судом за надање обећања које Бог обрече оцевима нашијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'Коме се сви дванаест кољена нашијех једнако дан и ноћ служећи надају да ће доћи. За ово надање оптужен сам, царе Агрипа, од Јевреја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Шта? зар ви мислите да се не може вјеровати да Бог мртве подиже?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Тако и ја мишљах да ми ваља многа зла чинити против имена Исуса Назарећанина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Као што и учиних у Јерусалиму; и многе од светијех ја затворах у тамнице, примивши власт од главара свештеничкијех; и кад их убијаху, пристајах на суд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'И по свијем зборницама мучећи их често, нагоњах да хуле на Исуса; и одвише мрзећи на њих гоњах их тја и до туђијех градова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'За које идући у Дамаск с влашћу и заповијешћу од главара свештеничкијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'У подне, царе, видјех на путу с неба свјетлост већу од сијања сунчанога, која обасја мене и оне што иђаху са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'А кад ми сви падосмо на земљу, чух глас гдје говори мени и казује Јеврејскијем језиком: Савле! Савле! зашто ме гониш? Тешко ти је противу бодила праћати се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'А ја рекох: ко си ти, Господе? А он рече: ја сам Исус, којега ти гониш;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Него устани и стани на ноге своје; јер ти се за то јавих да те учиним слугом и свједоком овоме што си видио и што ћу ти показати,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Избављајући те од народа Јеврејскога и од незнабожаца, којима ћу те послати,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Да им отвориш очи да се обрате од таме к видјелу и од области сотонине к Богу, да приме опроштење гријеха и достојање међу освећенима вјером мојом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Зато, царе Агрипа! не бих непокоран небеској утвари;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'Него најприје онима који су у Дамаску и у Јерусалиму, потом и по свој земљи Јеврејској, и незнабошцима проповиједах да се покају, и да се обрате к Богу чинећи дјела достојна покајања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Зато ме Јевреји ухватише у цркви и шћаху да ме раскину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Али добивши помоћ Божију стојим до самога овог дана, и свједочим и малом и великом, не казујући ништа осим што пророци казаше да ће бити, и Мојсије:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'Да ће Христос пострадати, и да ће бити први из васкрсенија мртвијех и проповиједати видјело народу Јеврејскоме и незнабошцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'А кад он ово одговараше, рече Фист великијем гласом: зар лудујеш, Павле? Многе те књиге изводе из памети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'А он рече: не лудујем, честити Фисте, него ријечи истине и разума казујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Јер за ово зна цар, којему и говорим слободно; јер не вјерујем да му је што од овога непознато; јер ово није било у углу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Вјерујеш ли, царе Агрипа, пророцима? Знам да вјерујеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'А Агрипа рече Павлу: још мало па ћеш ме наговорити да будем хришћанин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'А Павле рече: молио бих Бога и за мало и за много да би не само ти него и сви који ме слушају данас били такови као и ја што сам, осим окова овијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'И кад он ово рече, уста цар и судија и Верникија, и који сјеђаху с њима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'И отишавши разговараху се међу собом говорећи: овај човјек није учинио ништа што заслужује смрт или окове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'А Агрипа рече Фисту: овај човјек могаше бити пуштен да не рече да хоће к ћесару. И тако судија намисли да га пошље к ћесару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'И као што би одређено да идемо у Талијанску, предаше и Павла и друге неке сужње капетану, по имену Јулију, од ћесареве чете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'А кад уђосмо у лађу Адрамитску да пловимо у Азијска мјеста, отискосмо се; и с нама бјеше Аристарх Маћедонац из Солуна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'И други дан дођосмо у Сидон. И Јулије држаше Павла лијепо, и допусти му да одлази к својијем пријатељима и да га послужују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'И оданде одвезавши се допловисмо у Кипар, јер вјетрови бијаху противни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'И препловивши пучину Киликијску и Памфилијску дођосмо у Миру Ликијску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'И ондје нашавши капетан лађу Александријску која плови у Талијанску, метну нас у њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'И пловивши много дана споро, и једва дошавши према Книду, јер нам вјетар не дадијаше, допловисмо под Крит код Салмоне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'И једва се возећи поред краја, дођосмо на једно мјесто које се зове Добра Пристаништа, код којега близу бјеше град Ласеја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'А пошто прође много времена, и већ пловљење не бијаше без страха, јер и пост већ бјеше прошао, свјетоваше Павле');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Говорећи им: људи! видим да ће пловљење бити с муком и великом штетом не само товара и лађе него и душа нашијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Али капетан послуша већма корманоша и господара од лађе неголи Павлове ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'А не будући пристаниште згодно за зимовник, свјетоваху многи да се одвезу оданде, не би ли како могли доћи до Финика, и ондје да зимују у пристаништу Критском, које гледа к југу и к западу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'И кад дуну југ, мишљаху да им се воља испуни, и подигнувши једра пловљаху покрај Крита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Али не задуго потом дуну насупрот њему буран вјетар који се зове Евроклидон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'А кад се лађа оте, и не могаше се вјетру противити, предадосмо је валовима и ношаху нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'А кад прођосмо мимо једно острво које се зове Клауда, једва могосмо удржати чамац,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Који извукавши, свакојако помагаху, те га привезасмо одозго за лађу; а бојећи се да не удари на пруд, спустисмо једра, и тако се плављасмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'А кад нам веома досађиваше бура сјутрадан избациваху товаре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'И у трећи дан својима рукама избацисмо алат лађарски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'А кад се ни сунце ни звијезде за много дана не показаше, и бура не мала навалила, бијаше пропао сав над да ћемо се избавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'И кад се задуго није јело, онда Павле ставши преда њих рече: требаше дакле, о људи! послушати мене, и не отискивати се од Крита, и не имати ове муке и штете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'И ево сад вас молим да будете добре воље: јер ниједна душа од вас неће пропасти осим лађе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Јер у ову ноћ стаде преда ме анђео Бога којега сам ја и коме служим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'Говорећи: не бој се, Павле! ваља ти доћи пред ћесара; и ево ти дарова Бог све који се возе с тобом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Зато не бојте се, људи; јер вјерујем Богу да ће тако бити као што ми би речено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Али ваља нам доћи на једно острво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'А кад би четрнаеста ноћ, и ми се у поноћи плављасмо по Адријанској пучини, помислише лађари да се приближују к некаквој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'И измјеривши дубину нађоше двадесет хвати; и прошавши мало опет измјерише, и нађоше петнаест хвати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Онда бојећи се да како не ударе на прудовита мјеста бацише са стражњега краја лађе четири ленгера, па се мољасмо Богу да сване.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'А кад лађари гледаху да побјегну из лађе, и спустише чамац у море изговарајући се као да хоће с предњега краја да спусте ленгере,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Рече Павле капетану и војницима: ако ови не остану у лађи, ви не можете живи остати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Тада војници одрезаше ужа на чамцу и пустише га те паде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'А кад шћаше да сване, мољаше Павле све да једу, говорећи: четрнаести је дан данас како чекате и не једући живите ништа не окусивши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Зато вас молим да једете: јер је то за ваше здравље. А ни једноме од вас длака с главе неће отпасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'И рекавши ово узе хљеб, и даде хвалу Богу пред свима, и преломивши стаде јести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Онда се сви развеселивши и они једоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'А у лађи бијаше нас душа свега двјеста и седамдесет и шест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'И наситивши се јела, облакшаше лађу избацивши пшеницу у море.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'А кад би дан не познаваху земље; него угледаше некакав залив с пијеском, на који се договорише ако буде могуће, да извуку лађу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'И подигнувши ленгере вожаху се по мору, и одријешивши ужа на крмама, и раширивши мало једро према вјетрићу који духаше, вожасмо се крају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'А кад дођосмо као на један језик, гдје се море као раздјељује, насади се лађа; и предњи крај, који се насади, оста тврд да се не може помакнути, а крма се разбијаше од силе валова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'А војници се договорише да побију сужње, да који не исплива и не утече.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Али капетан желећи сачувати Павла забрани њихов договор, и заповједи онима који знаду пливати да искоче најприје, и да изиђу на земљу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'А остали једни на даскама а једни на чему од лађе. И тако изиђоше сви живи на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'И кад изиђоше срећно из лађе, тада разумјеше да се острво зове Мелит.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'А дивљаци чињаху нам не малу љубав, јер наложише огањ и примише нас све због дажда који иђаше, и због зиме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'А Павле зграбивши гомилу грања наложи на огањ, и изишавши змија од врућине скочи му на руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'И кад видјеше дивљаци змију гдје виси о руци његовој, говораху један другоме: јамачно је овај човјек крвник, којега избављена од мора суд Божиј не остави да живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'А он отресавши змију у огањ не би му ништа зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'А они чекаху да он отече или уједанпут да падне мртав. А кад задуго чекаше, и видјеше да му ништа зло не би, промијенише се, и говораху да је он Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'А наоколо око онога мјеста бијаху села поглавара од острва по имену Поплија, који нас прими и угости љубазно три дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'А догоди се да отац Поплијев лежаше од грознице и од срдобоље, којему ушавши Павле помоли се Богу и метну руке своје на њ и исцијели га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'А кад то би, долажаху и други који бијаху болесни на острву ономе, и исцјељиваху се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'И поштоваху нас великијем частима; и кад пођосмо, спремише нам што је од потребе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'А послије три мјесеца одвезосмо се на лађи Александријској, која је била презимила на острву, и бијаху на њој написани Диоскури.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'И допловивши у Сиракузу остасмо ондје три дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'А онанде отпловивши дођосмо у Ригију; и послије једнога дана кад дуну југ, дођосмо други дан у Потиоле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Ондје нађемо браћу, и они нас замоле те останемо код њих седам дана; и тако пођосмо у Рим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'И оданде чувши браћа за нас изиђоше нам на сусрет тја до Апијева пазара и три крчме. И кад их видје Павле, даде хвалу Богу, и ослободи се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'А кад дођосмо у Рим, капетан предаде сужње војводи. Али се Павлу допусти да живи гдје хоће с војником која га чуваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'А послије три дана Павле сазва старјешине Јеврејске. И кад се они скупише, говораше им: људи браћо! ја ништа не учиних противно народу или обичајима отачкијем; и Јерусалимљани предаше ме као сужња у руке Римљанима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Који извидјевши за мене шћаху да ме пусте, јер се не нађе на мени ниједна смртна кривица.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Али кад Јудејци говораху насупрот, натјера ме невоља да се иштем пред ћесара, не као да бих свој народ имао што тужити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Тога ради узрока замолих вас да се видимо и да се разговоримо; јер нада ради Израиљева окован сам у ово гвожђе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'А они му рекоше: ми нити примисмо писма за те из Јудеје; нити дође ко од браће да јави или да говори што зло за тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Него молимо да чујемо од тебе шта мислиш; јер нам је познато за ову јерес да јој се свуда насупрот говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'И одредивши му дан дођоше к њему у гостионицу многи; којима казиваше свједочећи царство Божије и увјеравајући их за Исуса из закона Мојсијева и из пророка од јутра до самога мрака.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'И једни вјероваху ономе што говораше а једни не вјероваху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'А будући несложни међу собом, одлажаху кад рече Павле једну ријеч: добро каза Дух свети преко пророка Исаије оцевима нашијем');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Говорећи: иди к народу овоме и кажи: ушима ћете чути и нећете разумјети; и очима ћете гледати и нећете видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Јер одрвени срце овога народа, и ушима тешки чују, и очима својијем зажмурише да како не виде очима, и ушима не чују, и да се не обрате да их исцијелим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Да вам је дакле на знање да се незнабошцима посла спасеније Божије, они ће и чути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'И кад он ово рече, отидоше Јевреји препирући се међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'А Павле остаде пуне двије године о своме трошку, и дочекиваше све који му долажаху,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Проповиједајући царство Божије, и учећи о Господу нашему Исусу Христу слободно, и нико му не брањаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Од Павла, слуге Исуса Христа, позванога апостола изабранога за јеванђеље Божије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'Које Бог напријед обећа преко пророка својијех у светијем писмима');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'О сину својему, који је по тијелу рођен од сјемена Давидова,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'А посвједочен силно за сина Божијега Духом светиње по васкрсенију из мртвијех, Исусу Христу Господу нашему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Преко којега примисмо благодат и апостолство, да покоримо све незнабошце вјери имена његова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Међу којима сте и ви позвани Исусу Христу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Свима који су у Риму, љубазнима Богу, и позванима светима: благодат вам и мир од Бога оца нашега и Господа Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Прво дакле захваљујем Богу својему кроз Исуса Христа за све вас што се вјера ваша гласи по свему свијету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Јер ми је свједок Бог, којему служим духом својијем у јеванђељу сина његова, да вас се опомињем без престанка,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Молећи се свагда Богу у молитвама својијем да би ми кад Божија воља помогла да дођем к вама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Јер желим видјети вас, да вам дам какав духовни дар за ваше утврђење,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'То јест, да се с вама утјешим вјером општом, и вашом и мојом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Али вам нећу затајити, браћо, да сам много пута хтио да вам дођем, па бих задржан дослије, да и међу вама имам какав плод, као и међу осталијем незнабошцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Дужан сам и Грцима и дивљацима, и мудрима и неразумнима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Зато, од моје стране, готов сам и вама у Риму проповједати јеванђеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Јер се не стидим јеванђеља Христова; јер је сила Божија на спасење свакоме који вјерује, а најприје Јеврејину и Грку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Јер се у њему јавља правда Божија из вјере у вјеру, као што је написано: праведник ће од вјере жив бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Јер се открива гњев Божиј с неба на сваку безбожност и неправду људи који држе истину у неправди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Јер што се може дознати за Бога познато је њима: јер им је Бог јавио;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Јер што се на њему не може видјети, од постања свијета могло се познати и видјети на створењима, и његова вјечна сила и божанство, да немају изговора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Јер кад познаше Бога, не прославише га као Бога нити му захвалише, него залудјеше у својијем мислима, и потамње неразумно срце њихово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Кад се грађаху мудри, полудјеше,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'И претворише славу вјечнога Бога у обличје смртнога човјека и птица и четвороножнијех животиња и гадова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Зато их предаде Бог у жељама њиховијех срца у нечистоту, да се погане тјелеса њихова међу њима самима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Који претворише истину Божију у лаж, и већма поштоваше и послужише твар него творца, који је благословен вавијек. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Зато их предаде Бог у срамне сласти; јер жене њихове претворише путно употребљавање у беспутно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'Тако и људи оставивши путно употребљавање женскога рода, распалише се жељом својом један на другога, и људи с људима чињаху срам, и плату која требаше за пријевару њихову примаху на себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'И као што не мараху да познаду Бога, зато их Бог предаде у покварен ум да чине што не ваља,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'Да буду напуњени сваке неправде, курварства, злоће, лакомства, пакости; пуни зависти, убиства, свађе лукавства, злоћудности;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Шаптачи, опадачи, богомрсци, силеџије, хвалише, поносити, измишљачи зала, непокорни родитељима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Неразумни, невјере, нељубавни, непримирљиви, немилостиви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'А неки правду Божију познавши да који то чине заслужују смрт, не само то чине, него пристају на то и онима који чине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Зато се не можеш изговорити, о човјече који год судиш! јер којијем судом судиш другоме, себе осуђујеш; јер то чиниш судећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'А знамо да је суд Божиј прав на оне који то чине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Него помишљаш ли, о човјече који судиш онима који то чине, и сам чиниш то! да ћеш ти побјећи од суда Божијега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Или не мариш за богатство његове доброте и кротости и трпљења, не знајући да те доброта Божија на покајање води?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Него својом дрвености и непокајанијем срцем сабираш себи гњев за дан гњева у који ће се показати праведни суд Бога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Који ће дати свакоме по дјелима његовијем:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Онима дакле који су трпљењем дјела доброга тражили славу и част и нераспадљивост, живот вјечни;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'А онима који се уз пркос супроте истини а покоравају се неправди, немилост и гњев.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Невоља и туга на сваку душу човјека који чини зло, а најприје Јеврејина и Грка;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'А слава и част и мир свакоме који чини добро, а најприје Јеврејину и Грку;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Јер Бог не гледа ко је ко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Јер који без закона сагријешише, без закона ће и изгинути; и који у закону сагријешише, по закону ће се осудити');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '(Јер пред Богом нијесу праведни они који слушају закон, него ће се они оправдати који га творе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Јер кад незнабошци не имајући закона сами од себе чине што је по закону, они закона не имајући сами су себи закон:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Они доказују да је оно написано у срцима њиховијем што се чини по закону, будући да им савјест свједочи, и мисли међу собом туже се или правдају)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'На дан када Бог узасуди тајне људске по јеванђељу мојему преко Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Гле, ти се зовеш Јеврејин, а ослањаш се на закон и хвалиш се Богом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'И познајеш вољу, и избираш што је боље, јер си научен од закона;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'И мислиш да си вођ слијепима, видјело онима који су у мраку,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'Наказатељ безумнима, учитељ дјеци, који имаш углед разума и истине у закону.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Учећи дакле другога себе не учиш;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Проповједајући да се не краде, крадеш; говорећи: не чини прељубе, чиниш прељубу: гадећи се на идоле, крадеш светињу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Који се хвалиш законом, а пријеступом закона срамотиш Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Јер се име Божије због вас хули у незнабошцима, као што стоји написано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Обрезање помаже ако закон држиш; ако ли си преступник закона, обрезање је твоје необрезање постало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Ако дакле необрезање правду закона држи, зашто се не би његово необрезање за обрезање узело?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'И онај који је од рода необрезан и извршује закон, осудиће тебе који си са словима и обрезањем преступник закона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Јер оно није Јеврејин који је споља Јеврејин, нити је оно обрезање који је споља на тијелу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Него је оно Јеврејин који је изнутра, и обрезање срца духом а не словима, то је обрезање; коме је хвала не од људи него од Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Шта је дакле бољи Јеврејин од другијех људи? Или шта помаже обрезање?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Много свакојако; прво што су им повјерене ријечи Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'А што неки не вјероваше, шта је за то? Еда ће њихово невјерство вјеру Божију укинути?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Боже сачувај! него Бог нека буде истинит, а човјек сваки лажа, као што стоји написано: да се оправдаш у својијем ријечима, и да побиједиш кад ти стану судити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Ако ли неправда наша Божију правду подиже, шта ћемо рећи? Еда ли је Бог неправедан кад се срди? По човјеку говорим:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Боже сачувај! Јер како би могао Бог судити свијету?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Јер ако истина Божија у мојом лажи већа постане на славу његову, зашто још и ја као грјешник да будем осуђен?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Зашто дакле (као што вичу на нас, и као што кажу неки да ми говоримо) да не чинимо зла да дође добро? Њима ће суд бити праведан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Шта дакле? Јесмо ли бољи од њих? Нипошто! Јер горе доказасмо да су и Јевреји и Грци сви под гријехом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'Као што стоји написано: ниједнога нема праведна;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Ниједнога нема разумна, и ниједнога који тражи Бога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Сви се уклонише и заједно неваљали посташе: нема га који чини добро, нема ниједнога циглог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Њихово је грло гроб отворен, језицима својима варају, и јед је аспидин под уснама њиховима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Њихова су уста пуна клетве и грчине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Њихове су ноге брзе да прољевају крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'На путовима је њиховима раскопавање и невоља;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'И пута мирнога не познаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Нема страха Божијега пред очима њиховима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'А знамо да оно што закон говори, говори онима који су у закону, да се свака уста затисну, и сав свијет да буде крив Богу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Јер се дјелима закона ниједно тијело неће оправдати пред њим; јер кроз закон долази познање гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'А сад се без закона јави правда Божија, посвједочена од закона и од пророка;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'А правда Божија вјером Исуса Христа у све и на све који вјерују; јер нема разлике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Јер сви сагријешише и изгубили славу Божију,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'И оправдаће се забадава благодаћу његовом, откупом Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Којега постави Бог очишћење вјером у крви његовој да покаже своју правду опроштењем пређашњијех гријеха;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'У подношењу Божијему, да покаже правду своју у садашње вријеме да је он праведан и да правда онога који је од вјере Исусове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Гдје је дакле хвала? Прође. Какијем законом? је ли законом дјела? Не, него законом вјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Мислимо дакле да ће се човјек оправдати вјером без дјела закона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Или је само Јеврејски Бог, а не и незнабожачки? Да, и незнабожачки.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Јер је један Бог који ће оправдати обрезање из вјере и необрезање вјером. Кваримо ли дакле закон вјером? Боже сачувај! него га још утврђујемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Шта ћемо дакле рећи за Авраама, оца својега, да је по тијелу нашао?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Јер ако се Авраам дјелима оправда, има хвалу, али не у Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Јер шта говори писмо? Вјерова Авраам Богу, и прими му се у правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'А ономе који ради не броји се плата по милости него по дугу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'А ономе који не ради а вјерује онога који правда безбожника, прима се вјера његова у правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Као што и Давид говори да је благо човјеку коме Бог прима правду без дјела закона:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Благо онима који се опростише безакоња, и којима се гријеси прикрише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Благо човјеку коме Господ не прима гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Ово дакле блаженство или је у обрезању или у необрезању? Јер говоримо да се Аврааму прими вјера у правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Како му се дакле прими? или кад је био у обрезању или необрезању? Не у обрезању него у необрезању.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'И прими знак обрезања као печат правде вјере коју имаше у необрезању, да би био отац свију који вјерују у необрезању; да се и њима прими у правду;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'И да би био отац обрезања не само онима који су од обрезања, него и онима који ходе по стопама вјере која бјеше у необрезању оца нашега Авраама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Јер обећање Аврааму или сјемену његову да буде нашљедник свијету не би законом него правдом вјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Јер ако су нашљедници они који су од закона, пропаде вјера, и поквари се обећање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Јер закон гради гњев; јер гдје нема закона нема ни пријеступа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Зато од вјере да буде по милости да обећање тврдо остане свему сјемену, не само који је од закона него и који је од вјере Авраама, који је отац свима нама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(Као што стоји написано: поставих те оца многијем народима) пред Богом коме вјерова, који оживљује мртве, и зове оно што није као оно што јест:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Он вјерова на над кад се није било ничему надати да ће он бити отац многијем народима, као што му бјеше речено: тако ће бити сјеме твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'И не ослабивши вјером не погледа ни на своје већ уморено тијело, јер му бјеше негдје око сто година, ни на мртвост Сарине материце.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'И за обећање Божије не посумња се невјеровањем, него ојача у вјери, и даде славу Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'И знадијаше јамачно да што обећа кадар је и да учини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Зато се и прими њему у правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Али није писано за њега једнога само да му се прими,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Него и за нас, којима ће се примити ако вјерујемо онога који васкрсе Исуса Христа Господа нашега из мртвијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Који се предаде за гријехе наше, и устаде за оправдање наше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Оправдавши се дакле вјером, имамо мир с Богом кроз Господа својега Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Кроз којега и приступ нађосмо вјером у ову благодат у којој стојимо, и хвалимо се надањем славе Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Не само пак то, него се хвалимо и невољама, знајући да невоља трпљење гради;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'А трпљење искуство, а искуство надање;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'А надање неће се осрамотити, јер се љубав Божија изли у срца наша Духом светијем који је дат нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Јер Христос још кад слаби бјесмо умрије у вријеме своје за безбожнике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Јер једва ко умре за праведника; за доброга може бити да би се ко усудио умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Али Бог показује своју љубав к нама што Христос још кад бијасмо грјешници умрије за нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Много ћемо дакле већма бити кроза њ спасени од гњева кад смо се сад оправдали крвљу његовом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Јер кад смо се помирили с Богом смрћу сина његова док смо још били непријатељи, много ћемо се већма спасти у животу његову кад смо се помирили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Не само пак то, него се хвалимо и Богом кроз Господа својега Исуса Христа, кроз којега сад примисмо помирење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Зато као што кроз једнога човјека дође на свијет гријех, и кроз гријех смрт, и тако смрт уђе у све људе, јер сви сагријешише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Јер гријех бјеше на свијету до закона; али се гријех не примаше кад не бјеше закона;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Него царова смрт од Адама тја до Мојсија и над онима који нијесу сагријешили преступивши као Адам, који је прилика онога који шћадијаше доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Али дар није тако као гријех; јер кад кроз гријех једнога помријеше многи, много се већа благодат Божија и дар изли изобилно на многе благодаћу једнога човјека Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'И дар није као гријех једнога: јер за гријех једнога би осуђење, а дар од многијех гријехова оправдање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Јер кад за гријех једнога царова смрт кроз једнога, колико ће већма они који примају изобиље благодати и дар правде у животу царовати кроз једнога Исуса Христа!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Зато дакле као што за гријех једнога дође осуђење на све људе, тако и правдом једнога дође на све људе оправдање живота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Јер као што непослушањем једнога човјека посташе многи грјешни, тако ће и послушањем једнога бити многи праведни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'А закон дође уз то да се умножи гријех; јер гдје се умножи гријех ондје се још већма умножи благодат,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'Да као што царова гријех за смрт, тако и благодат да царује правдом за живот вјечни, кроз Исуса Христа Господа нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Шта ћемо дакле рећи? Хоћемо ли остати у гријеху да се благодат умножи? Боже сачувај!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Јер који умријесмо гријеху како ћемо још живљети у њему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Или не знате да сви који се крстисмо у Исуса Христа, у смрт његову крстисмо се?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Тако се с њим погребосмо крштењем у смрт да као што уста Христос из мртвијех славом очином, тако и ми у новом животу да ходимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Јер кад смо једнаки с њим једнаком смрћу, бићемо и васкрсенијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'Знајући ово да се стари наш човјек разапе с њиме, да би се тијело грјешно покварило, да више не бисмо служили гријеху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Јер који умрије опрости се од гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'А ако умријесмо с Христом, вјерујемо да ћемо и живљети с њим,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Знајући да Христос уста из мртвијех, већ више не умире; смрт више неће обладати њиме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Јер што умрије, гријеху умрије једанпут; а што живи, Богу живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Тако и ви дакле држите себе да сте мртви гријеху а живи Богу у Христу Исусу Господу нашему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Да не царује дакле гријех у вашему смртном тијелу, да га слушате у сластима његовијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Нити дајите удова својијех гријеху за оружје неправде; него дајите себе Богу, као који сте живи из мртвијех, и уде своје Богу за оружје правде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Јер гријех неће вама обладати, јер нијесте под законом него под благодаћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Шта дакле? Хоћемо ли гријешити кад нијесмо под законом него под благодаћу? Боже сачувај!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Не знате ли да коме дајете себе за слуге у послушање, слуге сте онога кога слушате, или гријеха за смрт, или послушања за правду?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Хвала дакле Богу што бивши робови гријеху послушасте од срца ту науку којој се и предадосте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Опростивши се пак од гријеха постасте слуге правди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Као човјек говорим, за слабост вашега тијела. Јер као што дадосте уде своје за робове нечистоти и безакоњу на безакоње, тако сад дајите уде своје за слуге правди на посвећење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Јер кад бијасте робови гријеху, прости бијасте од правде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Какав дакле онда имадосте плод за који се сад стидите? Јер је онога крај смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'А сад опростивши се од гријеха, и поставши слуге Божије, имате плод свој на посвећење, а крај живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Јер је плата за гријех смрт, а дар Божиј је живот вјечни у Христу Исусу Господу нашему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Или не знате, браћо (јер говорим онима који знаду закон), да закон влада над човјеком докле је жив?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Јер је удата жена привезана законом за мужа докле год он живи; а ако ли муж њезин умре, раздријеши се од закона мужевљега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Зато дакле док јој је муж жив бива прељубочиница ако пође за другог мужа; а ако јој умре муж проста је од закона да не буде прељубочиница ако пође за другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'За то, браћо моја, и ви умријесте закону тијелом Христовим, да будете другога, онога што уста из мртвијех, да плод донесемо Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Јер кад бијасмо у тијелу, бијаху сласти грјеховне, које закон рађаху у удима нашима да се смрти плод доноси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'А сад умрвши избависмо се од закона који нас држаше, да служимо (Богу) у обновљењу Духа а не у старини слова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Шта ћемо дакле рећи? Је ли закон гријех? Боже сачувај! него ја гријеха не познах осим кроз закон; јер не знадох за жељу да закон не каза: не зажели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'А гријех узе почетак кроз заповијест, и начини у мени сваку жељу; јер је гријех без закона мртав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'А ја живљах некад без закона; а кад дође заповијест, онда гријех оживље,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'А ја умријех, и нађе се да ми заповијест би за смрт која бјеше дата за живот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Јер гријех узевши почетак кроз заповијест превари ме, и уби ме њоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Тако је дакле закон свет и заповијест света и праведна и добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Добро ли дакле би мени смрт? Боже сачувај! него гријех, да се покаже гријех добром чинећи ми смрт, да буде гријех одвише грјешан заповијешћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Јер знамо да је закон духован; а ја сам тјелесан, продан под гријех:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Јер не знам шта чиним, јер не чиним оно шта хоћу, него на што мрзим оно чиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Ако ли оно чиним шта нећу, хвалим закон да је добар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'А ово више ја не чиним него гријех који живи у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Јер знам да добро не живи у мени, то јест у тијелу мојему. Јер хтјети имам у себи, али учинити добро не налазим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Јер добро шта хоћу не чиним, него зло што нећу оно чиним.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'А кад чиним оно што нећу, већ ја то не чиним него гријех који живи у мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Налазим дакле закон, кад хоћу добро да чиним, да ме на зло нагони.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Јер имам радост у закону Божијему по унутрашњему човјеку;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Али видим други закон у удима својима, који се супроти закону ума мојега, и заробљава ме законом грјеховнијем који је у удима мојима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Ја несрећни човјек! Ко ће ме избавити од тијела смрти ове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Захваљујем Богу својему кроз Исуса Христа Господа нашега. Тако дакле ја сам умом својијем служим закону Божијему а тијелом закону грјеховноме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Никаква дакле сад нема осуђења онима који су у Христу Исусу и не ходе по тијелу него по Духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Јер закон духа који оживљава у Христу Исусу, опростио ме је од закона грјеховнога и смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Јер што закону бјеше немогуће, јер бјеше ослабљен тијелом, посла Бог сина својега у обличју тијела грјеховнога, и за гријех осуди гријех у тијелу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'Да се правда закона испуни у нама који не живимо по тијелу него по духу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Јер који су по тијелу тјелесно мисле, а који су по духу духовно мисле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Јер тјелесно мудровање смрт је, а духовно мудровање живот је и мир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Јер тјелесно мудровање непријатељство је Богу, јер се не покорава закону Божијему нити може.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'А који су у тијелу не могу Богу угодити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'А ви нијесте у тијелу него у духу; јер Дух Божиј у вама живи. А ако ко нема Духа Христова, он није његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'А ако је Христос у вама, онда је тијело мртво гријеха ради а Дух жив правде ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'А ако ли живи у вама Дух онога који је васкрсао Исуса из мртвијех, онај који је подигао Христа из мртвијех оживљеће и ваша смртна тјелеса Духом својијем који живи у вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Тако дакле, браћо, нијесмо дужни тијелу да по тијелу живимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Јер ако живите по тијелу, помријећете; ако ли духом послове тјелесне морите, живљећете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Јер који се владају по духу Божијему они су синови Божији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Јер не примисте духа ропства, опет да се бојите; него примисте Духа посиначкога, којијем вичемо: Ава, оче!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Овај дух свједочи нашему духу да смо дјеца Божија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'А кад смо дјеца и нашљедници смо: нашљедници дакле Божији, а сунашљедници Христови: јер с њим страдамо да се с њим и прославимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Јер мислим да страдања садашњега времена нијесу ништа према слави која ће нам се јавити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Јер чекање твари чека да се јаве синови Божији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Јер се твар покори пропадљивости (не од своје воље него за вољу онога који је покори) на над,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Да ће се и сама твар опростити од ропства распадљивости на слободу славе дјеце Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Јер знамо да сва твар уздише и тужи с нама до сад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'А не само она, него и ми који новину духа имамо, и ми сами у себи уздишемо чекајући посињења и избављења тијелу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Јер се надом спасосмо. А над који се види није над; јер кад ко види што, како ће му се надати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Ако ли се надамо ономе што не видимо, чекамо с трпљењем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'А тако и Дух помаже нам у нашијем слабостима: јер не знамо за што ћемо се молити као што треба, него сам Дух моли се за нас уздисањем неисказанијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'А онај што испитује срца зна што је мисао Духа, јер по вољи Божијој моли се за свете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'А знамо да онима који љубе Бога све иде на добро, који су позвани по намјерењу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Јер које напријед позна оне и одреди да буду једнаки обличју сина његова, да би он био прворођени међу многом браћом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'А које одреди оне и дозва; а које дозва оне и оправда; а које оправда оне и прослави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Шта ћемо дакле рећи на ово? Ако је Бог с нама, ко ће на нас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Који дакле свога сина не поштедје, него га предаде за све нас, како дакле да нам с њим све не дарује?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Ко ће оптужити избране Божије? Бог који правда?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Ко ће осудити? Христос Исус који умрије, па још и васкрсе, који је с десне стране Богу, и моли за нас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Ко ће нас раставити од љубави Божије? Невоља ли или туга? или гоњење? или глад? или голотиња? или страх? или мач? као што стоји написано:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'За тебе нас убијају вас дан, држе нас као овце које су за клање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Али у свему овоме побјеђујемо онога ради који нас је љубио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Јер знам јамачно да ни смрт, ни живот, ни анђели, ни поглаварства, ни силе, ни садашње, ни будуће, Ни висина, ни дубина, ни друга каква твар може нас раставити од љубави Божије, која је у Христу Исусу Господу нашему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Истину говорим тако ми Христа, не лажем, то ми свједочи савјест моја Духом светијем:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'Да ми је врло жао и срце ме моје боли без престанка;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Јер бих жељео да ја сам будем одлучен од Христа за браћу своју која су ми род по тијелу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'Која су Израиљци, којијех је посинаштво и слава, и завјет и закон, и богомољство, и обећања;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Којијех су и оци, и од којијех је Христос по тијелу, који је над свима Бог благословен вавијек. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'А није могуће да ријеч Божија прође: јер нијесу сви Израиљци који су од Израиља;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Нити су сви дјеца који су сјеме Авраамово, него у Исаку, рече, назваће ти се сјеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'То јест, нијесу оно дјеца Божија што су по тијелу дјеца, него дјеца обећања примају се за сјеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Јер је ово ријеч обећања: у ово вријеме доћи ћу и у Саре ће бити син.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Не само пак она него и Ревека, кад затрудње од самога Исака оца нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Јер још док се дјеца не бијаху родила, ни учинила добра ни зла, да остане Божија наредба по избору,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'Не за дјела, него онога ради који позива рече јој се: већи ће служити мањему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Као што стоји написано: Јаков ми омиље, а на Исава омрзох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Шта ћемо дакле на то рећи? Еда ли је неправда у Бога? Боже сачувај!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Јер Мојсију говори: кога ћу помиловати, помиловаћу, и на кога ћу се смиловати, смиловаћу се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'Тако дакле нити стоји до онога који хоће, ни до онога који трчи, него до Бога који помилује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Јер писмо говори Фараону: за то те исто подигох да на теби покажем силу своју, и да се разгласи име моје по свој земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Тако дакле кога хоће милује, а кога хоће отврдоглави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Рећи ћеш ми: зашто нас још криви? јер ко се може супротити вољи његовој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'А ко си ти, о човјече! Да противно одговараш Богу? Еда ли рукотворина говори мајстору своме: зашто си ме тако начинио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Или зар лончар нема власти над калом да од једне гуке начини један суд за част а други за срамоту?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'А кад шћаше Бог да покаже гњев свој и да објави силу своју, поднесе с великијем трпљењем судове гњева који су приправљени за погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'И да покаже богатство славе своје на судима милости које приправи за славу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'Које нас и дозва не само од Јевреја него и од незнабожаца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Као што и у Јосији говори: назваћу народ својијем који није мој народ, и нељубазницу љубазницом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'И биће на мјесту, гдје им се рече: ви нијесте мој народ; тамо ће се назвати синови Бога живога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'А Исаија виче за Израиља: ако буде број синова Израиљевијех као пијесак морски, остатак ће се спасти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Јер ће он извршити ријеч своју, и наскоро ће извршити по правди, да, испуниће Господ наскоро ријеч своју на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'И као што прорече Исаија: да нам није Господ Саваот оставио сјемена, онда бисмо били као Содом и Гомор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Шта ћемо дакле рећи? Да незнабошци који не тражише правде докучише правду, али правду од вјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'А Израиљ тражећи закон правде не докучи закона правде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Зашто? Јер не тражи из вјере него из дјела закона; јер се спотакоше на камен спотицања,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'Као што стоји написано: ево мећем у Сиону камен спотицања и стијену саблазни; и који га год вјерује неће се постидјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Браћо! жеља је мојега срца и молитва к Богу за спасеније Израиља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Јер им свједочим да имају ревност за Бога, али не по разуму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Јер не познајући правде Божије и гледајући да своју правду утврде не покоравају се правди Божијој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Јер је Христос свршетак закона: који га год вјерује оправдан је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Јер Мојсије пише за правду која је од закона: који човјек тако чини живљеће у том.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'А правда која је од вјере овако говори: да не речеш у срцу својему: ко ће изићи на небо? то јест да сведе Христа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Или: ко ће сићи у бездан? то јест да изведе Христа из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Али шта говори писмо? Близу ти је ријеч у устима твојима и у срцу твојему, то јест ријеч вјере коју проповједамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Јер ако признајеш устима својима да је Исус Господ, и вјерујеш у срцу својему да га Бог подиже из мртвијех, бићеш спасен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Јер се срцем вјерује за правду а устима се признаје за спасеније.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Јер писмо говори: који га год вјерује неће се постидјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Јер нема разлике међу Јеврејином и Грком: јер је он Бог свију, и богат за све који га призивљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Јер који год призове име Господње спашће се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Како ће дакле призвати кога не вјероваше? А како ће вјеровати кога не чуше? А како ће чути без проповједника?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'А како ће проповиједати ако не буду послани? Као што стоји написано: како су красне ноге онијех који доносе глас за мир, који доносе глас за добро!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Али сви не послушаше јеванђеља: јер Исаија говори: Господе! ко вјерова нашему проповиједању?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Тако дакле вјера бива од проповиједања, а проповиједање ријечју Божијом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Него велим: зар не чуше? Још отиде по свој земљи глас њихов, и по крајевима васионога свијета ријечи њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Него велим: зар не разумје Израиљ? Први Мојсије говори: ја ћу раздражити, не својијем народом, неразумнијем народом расрдићу вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'А Исаија говори слободно: нађоше ме који ме не траже; и јавих се онима који за ме не питају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'А к Израиљу говори: вас дан пружах руке своје к народу који не да да му се каже и одговара насупрот.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Говорим дакле: еда ли Бог одбаци народ свој? Боже сачувај! Јер сам и ја Израиљац од сјемена Авраамова од кољена Венијаминова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Не одбаци Бог народа својега, који напријед позна. Или не знате шта говори писмо за Илију како се тужи Богу на Израиља говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Господе! пророке твоје побише и олтаре твоје раскопаше, а ја остах један и траже душу моју да је изваде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'А шта му говори Божиј одговор? Оставих себи седам хиљада људи који не преклонише кољена пред Ваалом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Тако дакле и у садашње вријеме остатак би по избору благодати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Ако ли је по благодати, онда није од дјела, јер благодат већ не би била благодат; ако ли је од дијела није више благодат, јер дјело већ не би било дјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Шта дакле? Шта искаше Израиљ оно не доби; а избор доби; остали пак заслијепише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'Као што је написано: даде им Бог духа неосјетљивога, очи да не виде, и уши да не чују до самога данашњега дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'И Давид говори: да буде трпеза њихова замка и гвожђа, и саблазан и плата њима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Да се њихове очи заслијепе да не виде, и леђа њихова једнако да су погнута.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Говорим дакле: еда ли се спотакоше да падну? Боже сачувај! Него је њихова погрјешка спасење незнабошцима, да би се и они раздражили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'А кад је погрјешка њихова богатство свијету и штета њихова богатство незнабошцима, а камо ли да се испуне?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Јер вама говорим незнабошцима; јер, будући да сам ја апостол незнабожаца, хоћу да хвалим своју службу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Не бих ли како раздражио свој род, и спасао кога од њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Јер кад је одмет њихов примирење свијету, шта шта би било примљење, осим живот из мртвијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Ако је квасац свет, то је и тијесто; и ако је коријен свет, то су и гране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Ако ли се неке од грана одломише, и ти, који си дивља маслина, прицијепио си се на њих, и постао си заједничар у коријену и у масти од маслине;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'Не хвали се гранама; ако ли се пак хвалиш, не носиш ти коријена него коријен тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'А рећи ћеш: одломише се гране да се ја прицијепим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Добро! невјерством одломише се, а ти вјером стојиш; не поноси се, него се бој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Јер кад Бог рођенијех грана не поштедје, да и тебе како не непоштеди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Гледај дакле доброту и непоштеђење Божије: непоштеђење на онима што отпадоше, а на себи доброту Божију, ако останеш у доброти; ако ли пак не, и ти ћеш бити отсјечен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'А и они, ако не остану у невјерству, прицијепиће се; јер их је Бог кадар опет прицијепити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Јер кад си ти отсјечен од рођене маслине, и прицијепио се на нерођену питому маслину; а камо ли ови који ће се прицијепити на рођену своју маслину!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Јер вам, браћо, нећу затајити тајне ове (да не будете поносити), шљепота Израиљу паде у дијел докле не уђе незнабожаца колико треба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'И тако ће се спасти сав Израиљ, као што је написано: доћи ће од Сиона избавитељ и одвратиће безбожност од Јакова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'И ово им је мој завјет кад отмем њихове гријехе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'По јеванђељу дакле непријатељи су вас ради; а по избору љубазни су отаца ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Јер се Бог неће раскајати за своје дарове и звање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Јер као и ви што се некад супроћасте Богу а сад бисте помиловани њиховога ради супроћења,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'Тако и они сад не хтјеше да вјерују вашега ради помиловања да би и они били помиловани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Јер Бог затвори све у невјерство, да све помилује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'О дубино богатства и премудрости и разума Божијега! како су неиспитљиви његови судови и неистражљиви његови путови!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Јер ко позна мисао Господњу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Или ко му би савјетник? Или ко му напријед даде што, да му се врати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Јер је од њега и кроз њега и у њему све. Њему слава вавијек. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Молим вас дакле, браћо, милости Божије ради, да дате тјелеса своја у жртву живу, свету, угодну Богу; то да буде ваше духовно богомољство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'И не владајте се према овоме вијеку, него се промијените обновљењем ума својега, да бисте могли кушати које је добра и угодна и савршена воља Божија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Јер кроз благодат која је мени дата кажем свакоме који је међу вама да не мислите за себе више него што ваља мислити; него да мислите у смјерности као што је коме Бог удијелио мјеру вјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Јер као у једном тијелу што имамо многе уде а уди сви немају један посао,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Тако смо многи једно тијело у Христу, а по себи смо уди један другоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'А имамо различите дарове по благодати која нам је дана: ако пророштво, нека буде по мјери вјере;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Ако ли службу, нека служи; ако је учитељ, нека учи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Ако је тјешитељ, нека тјеши; који даје нека даје просто; који управља нека се брине; који чини милост нека чини с добром вољом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Љубав да не буде лажна. Мрзећи на зло држите се добра.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Братском љубави будите један к другоме љубазни. Чашћу један другога већег чините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Не будите у послу лијени; будите огњени у духу, служите Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Надањем веселите се, у невољи трпите, у молитви будите једнако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Дијелите потребе са светима; примајте радо путнике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Благосиљајте оне који вас гоне: благосиљајте, а не куните.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Радујте се с радоснима, и плачите с плачнима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Будите једне мисли међу собом. Не мислите о високијем стварима, него се држите нискијех. Не мислите за себе да сте мудри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'А никоме не враћајте зла за зло; промишљајте о том што је добро пред свијем људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Ако је могуће, колико до вас стоји, имајте мир са свијем људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Не освећујте се за себе, љубазни, него подајте мјесто гњеву, јер стоји написано: моја је освета, ја ћу вратити, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Ако је дакле гладан непријатељ твој, нахрани га; ако је жедан, напој га; јер чинећи то угљевље огњено скупљаш на главу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Не дај се злу надвладати, него надвладај зло добрим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Свака душа да се покорава властима које владају; јер нема власти да није од Бога, а што су власти, од Бога су постављене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Тако који се супроти власти супроти се наредби Божијој; а који се супроте примиће гријех на себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Јер кнезови нијесу страх добријем дјелима него злијем. Хоћеш ли пак да се не бојиш власти, чини добро, и имаћеш хвалу од ње;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Јер је слуга Божиј теби за добро. Ако ли зло чиниш, бој се; јер узалуд не носи мача, јер је Божиј слуга, осветник на гњев ономе који зло чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Тако се ваља покоравати не само од страха него и по савјести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Јер за то и порезе дајете; јер су слуге Божије које су за то исто постављене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Подајте дакле свакоме шта сте дужни: коме дакле порезу, порезу; а коме царину, царину; а коме страх, страх; а коме част, част.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'И не будите никоме ништа дужни осим да љубите један другога; јер који љуби другога закон испуни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Јер ово: не чини прељубе, не убиј, не укради, не свједочи лажно, не зажели, и ако има још каква друга заповјест, у овој се ријечи извршује, то јест: љуби ближњега својега као самога себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Љубав не чини зла ближњему; даклем је љубав извршење закона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'И знајући ово вријеме да је већ час дошао да устанемо од сна; јер нам је сад ближе спасеније неголи кад вјеровасмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Ноћ прође а дан се приближи: да одбацимо дакле сва дјела тамна, и да се обучемо у оружје видјела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Да ходимо поштено као по дану: не у ждерању и пијанству, не у курварству и нечистоти, не у свађању и зависти;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Него се обуците и Господа Исуса Христа; и тијелу не угађајте по жељама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'А слабога у вјери примајте лијепо, да се не смета савјест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Јер један вјерује да смије свашта јести, а који је слаб једе зеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Који једе нека не укорава онога који не једе; и који не једе нека не осуђује онога који једе; јер га Бог прими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Ко си ти који судиш туђему слузи? Он својему господару стоји или пада. Али ће устати; јер је Бог кадар подигнути га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Тако један разликује дан од дана, а други држи све дане да су једнаки: сваки да буде увјерен за своју мисао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Који разликује дане, Господу разликује; и који не разликује дана, Господу не разликује. Који једе, Господу једе: јер хвали Бога; и који не једе, Господу не једе, и хвали Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Јер ниједан од нас не живи себи, и ниједан не умире себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Јер ако живимо, Господу живимо; а ако умиремо, Господу умиремо. Ако дакле живимо, ако умиремо, Господњи смо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Јер зато Христос и умрије и васкрсе и оживље да облада и мртвима и живима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'А ти зашто осуђујеш брата својега? Или ти зашто укораваш брата својега? Јер ћемо сви изићи на суд пред Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Јер је писано: тако ми живота, говори Господ, поклониће ми се свако кољено, и сваки језик славиће Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Тако ће дакле сваки од нас дати Богу одговор за себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Зато да не осуђујемо више један другога, него мјесто тога ово гледајте да не постављате брату спотицања или саблазни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Знам и увјерен сам у Христу Исусу да ништа није погано по себи, осим кад ко мисли да је погано, ономе је погано.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'А ако је брат твој јела ради жалостан, већ се не владаш по љубави: не губи јелом својијем онога за којега Христос умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Гледајте дакле да се не хули на ваше добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Јер царство Божије није јело и пиће, него правда и мир и радост у Духу светоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Јер који овијем служи Христу угодан је Богу и мио људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Тако дакле да се старамо за мир и за оно чим водимо на боље један другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Не раскопавај дјела Божијега јела ради; јер је све чисто; него је погано за човјека који једе са спотицањем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Добро је не јести меса, и вина не пити, и оно не чинити на што се твој брат спотиче, или ода шта гори постаје или слаби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Ти имаш вјеру? Имај је сам у себи пред Богом. Благо ономе који не осуђује себе за оно шта нађе за добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'А који се сумња осуђен је ако једе, јер не чини по вјери: а шта год није по вјери гријех је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Дужни смо дакле ми јаки слабости слабијех носити, и не себи угађати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'И сваки од вас да угађа ближњему на добро за добар углед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Јер и Христос не угоди себи, него као што је писано: ружења онијех који тебе руже падоше на ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Јер што се напријед написа, за нашу се науку написа, да трпљењем и утјехом писма над имамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'А Бог трпљења и утјехе да вам да да сложно мислите међу собом по Христу Исусу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'Да једнодушно једнијем устима славите Бога и оца Господа нашега Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Зато примајте један другога као што и Христос прими вас на славу Божију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Али кажем да је Исус Христос био слуга обрезања истине ради Божије, да утврди обећање оцевима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'А незнабошци по милости да прославе Бога, као што стоји написано: зато ћу те хвалити међу незнабошцима, Господе, и пјеваћу име твоје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'И опет говори: веселите се незнабошци, с народом његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'И опет: хвалите Господа сви незнабошци, и славите га сви народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'И опет Исаија говори: биће коријен Јесејев, и који устане да влада над незнабошцима у онога ће се уздати незнабошци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'А Бог нада да испуни вас сваке радости и мира у вјери, да имате изобиље у наду силом Духа светога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'А ја сам и сам увјерен за вас, браћо, да сте и ви сами пуни благодати, напуњени свакога разума, да можете друге научити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Али вам опет, браћо, слободно писах неколико да вам напоменем ради благодати која ми је дана од Бога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'Да будем слуга Исуса Христа у незнабошцима, да служим јеванђељу Божијему, да буду незнабошци принос повољан и освећен Духом светијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Имам дакле хвалу у Христу Исусу код Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Јер не смијем говорити што које Христос не учини кроза ме за послушање незнабожаца ријечју и дјелом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'У сили знака и чудеса силом Духа Божијега; тако да од Јерусалима и наоколо тја до Илирика напуних јеванђељем Христовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'И тако се потрудих да проповиједим јеванђеље не гдје се спомињаше Христос, да на туђој закопини не зидам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'Него као што је писано: којима се не јави за њега, видјеће; и који не чуше разумјеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'То ме задржа много пута да не дођем к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'А сад више не имајући мјеста у овијем земљама, а имајући жељу од много година да дођем к вама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'Ако пођем у Шпањолску, доћи ћу вам; јер се надам да ћу туда проћи и вас видјети, и ви ћете ме отпратити онамо кад се најприје неколико наситим вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'А сад идем у Јерусалим служећи светима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Јер Маћедонија и Ахаја учинише драговољно неку порезу за сиромахе свете који живе у Јерусалиму.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Они учинише драговољно, а и дужни су им; јер кад незнабошци добише дијел у њиховијем духовнијем имањима, дужни су и они њима у тјелесним послужити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Кад ово дакле свршим, и овај им плод запечатим, поћи ћу преко вас у Шпањолску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'А знам да кад дођем к вама, доћи ћу с обилнијем благословом јеванђеља Христова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Али вас молим, браћо, заради Господа нашега Исуса Христа, и заради љубави Духа, помозите ми у молитвама за ме к Богу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'Да се избавим од онијех који се противе у Јудеји, и да служба моја за Јерусалим буде по вољи светима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Да с радошћу дођем к вама, с вољом Божијом, и да се развеселим с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'А Бог мира са свима вама. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Препоручујем вам пак Фиву сестру нашу, која је слушкиња код цркве у Кенхреји,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Да је примите у Господу као што приликује светима, и да јој будете у помоћи у свакој ствари коју од вас затреба; јер је она многима помогла, и самоме мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Поздравите Прискилу и Акилу, помоћнике моје у Христу Исусу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'Који за душу моју своје вратове положише, којима не ја један захваљујем, него и све цркве незнабожачке, и домашњу цркву њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Поздравите Епенета, мени љубазнога, који је новина из Ахаје у Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Поздравите Марију, која се много трудила за нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Поздравите Андроника и Јунију, родбину моју, и моје другаре у сужањству који су знаменити међу апостолима, који и прије мене вјероваше Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Поздравите Амплија, мени љубазнога у Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Поздравите Урбана, помоћника нашега у Христу, и Стахија, мени љубазнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Поздравите Апелија, окушанога у Христу. Поздравите домаће Аристовулове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Поздравите Иродијона, рођака мојега. Поздравите домаће Наркисове, који су у Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Поздравите Трифену и Трифосу, које се труде у Господу. Поздравите Персиду љубазну, која се много трудила у Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Поздравите Руфа избранога у Господу, и матер његову и моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Поздравите Асинкрита, Флегонта, Ерма, Патрова, Ермија, и браћу која су с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Поздравите Филолога и Јулију, Ниреја и сестру његову, и Олимпана, и све свете који су с њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Поздравите један другога цјеливом светијем. Поздрављају вас све цркве Христове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Молим вас пак, браћо, чувајте се од онијех који чине распре и раздоре на штету науке коју ви научисте, и уклоните се од њих;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Јер такови не служе Господу нашему Исусу Христу него својему трбуху, и благијем ријечима и благословима прелашћују срца безазленијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Јер ваше слушање разгласи се свуда. И радујем се за вас; али хоћу да сте ви мудри на добро а прости на зло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'А Бог мира да сатре сотону под ноге ваше скоро. Благодат Господа нашега Исуса Христа с вама. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Поздравља вас Тимотије, помоћник мој, и Лукије и Јасон и Сосипатар, рођаци моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Поздрављам вас и ја Тертије, који написах ову посланицу у Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Поздравља вас Гај, домаћин мој и цијеле цркве. Поздравља вас Ераст, хазнадар градски, и брат Кварт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Благодат Господа нашега Исуса Христа са свима вама. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'А ономе који вас може утврдити по јеванђељу мојему и проповиједању Исуса Христа, по откривењу тајне која је била сакривена од постања свијета,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'А сад се јавила и обзнанила кроз писма пророчка, по заповијести вјечнога Бога, за послушање вјере међу свима незнабошцима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'Јединоме премудроме Богу, кроз Исуса Христа, слава вавијек. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Од Павла вољом Божијом позванога апостола Исуса Христа, и од Состена брата,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Цркви Божијој која је у Коринту, освећенима у Христу Исусу, позванима светима, са свима који призивљу име Господа нашега Исуса Христа на свакоме мјесту и њиховоме и нашему:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Благодат вам и мир од Бога оца нашега и Господа Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Захваљујем свагда Богу својему за вас што вам је дана благодат Божија у Христу Исусу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Те се у свему обогатисте кроза њ, у свакој ријечи и сваком разуму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Као што се свједочанство Христово утврди међу вама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Тако да немате недостатка ни у једноме дару, ви који чекате откривења Господа нашега Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Који ће вас и утврдити до самога краја да будете прави на дан Господа нашега Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Вјеран је Бог који вас позва у заједницу сина својега Исуса Христа Господа нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Молим вас пак, браћо, именом Господа нашега Исуса Христа да сви једно говорите, и да не буду међу вама распре, него да будете утврђени у једном разуму и у једној мисли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Јер сам чуо за вас, браћо моја, од Хлојинијех домашњијех да су свађе међу вама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'А то кажем да један од вас говори: ја сам Павлов; а други: ја сам Аполов; а трећи: ја сам Кифин; а четврти: ја сам Христов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Еда ли се Христос раздјели? Еда ли се Павле разапе за вас? или се у име Павлово крстисте?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Хвала Богу што ја ниједнога од вас не крстих осим Криспа и Гаја;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Да не рече ко да у своје име крстих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'А крстих и Стефанин дом: даље не знам јесам ли кога другог крстио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Јер Христос не посла мене да крстим, него да проповиједам јеванђеље, не премудријем ријечима, да не изгуби силу крст Христов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Јер је ријеч крстова лудост онима који гину; а нама је који се спасавамо сила Божија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Јер је писано: погубићу премудрост премудријех, и разум разумнијех одбацићу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Гдје је премудри? Гдје је књижевник? Гдје је препирач овога вијека? Не претвори ли Бог мудрост овога свијета у лудост?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Јер будући да у премудрости Божијој не позна свијет премудрошћу Бога, била је Божија воља да лудошћу поучења спасе оне који вјерују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Јер и Јевреји знаке ишту, и Грци премудрости траже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'А ми проповиједамо Христа разапета, Јеврејима дакле саблазан а Грцима безумље;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Онима пак који су позвани, и Јеврејима и Грцима, Христа, Божију силу и Божију премудрост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Јер је лудост Божија мудрија од људи, и слабост је Божија јача од људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Јер погледајте знање своје, браћо, да нема ни много премудријех по тијелу, ни много силнијех ни много племенитијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Него што је лудо пред свијетом оно изабра Бог да посрами премудре; и што је слабо пред свијетом оно изабра Бог да посрами јако;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'И што је неплеменито пред свијетом и уништено изабра Бог, и што није, да уништи оно што јест,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Да се не похвали ниједно тијело пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Из којега сте ви у Христу Исусу, који нам поста премудрост од Бога и правда и освећење и избављење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Да (као што се пише) ко се хвали, Господом да се хвали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'И ја дошавши к вама, браћо, не дођох с високом ријечи или премудрости да вам јављам свједочанство Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Јер нијесам мислио да знам што међу вама осим Исуса Христа, и тога распета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'И ја бијах међу вама у слабости, и у страху и у великом дрктању.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'И ријеч моја, и поучење моје не бијаше у надговорљивијем ријечима људске премудрости, него у доказивању Духа и силе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Да вјера ваша не буде у мудрости људској него у сили Божијој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Али премудрост говоримо која је у савршенима, а не премудрост вијека овога ни кнезова вијека овога који пролазе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Него говоримо премудрост Божију у тајности сакривену, коју одреди Бог прије свијета за славу нашу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Које ниједан од кнезова вијека овога не позна; јер да су је познали, не би Господа славе разапели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Него као што је писано: што око не видје, и ухо не чу, и у срце човјеку не дође, оно уготови Бог онима, који га љубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'А нама је Бог открио Духом својијем; јер Дух све испитује, и дубина Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Јер ко од људи зна шта је у човјеку осим духа човјечијега који живи у њему? Тако и у Богу што је нико не зна осим Духа Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'А ми не примисмо духа овога свијета, него Духа који је из Бога, да знамо што нам је даровано од Бога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Које и говоримо не ријечима што је научила човјечија премудрост, него што учи Дух свети; и духовне ствари духовно радимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'А тјелесни човјек не разумије што је од Духа Божијега; јер му се чини лудост и не може да разумије, јер треба духовно да се разгледа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Духовни пак све разгледа, а њега сама нико не разгледа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Јер ко позна ум Господњи да га поучи? А ми ум Христов имамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'И ја, браћо, не могох с вама говорити као с духовнима него као с тјелеснима, као с малом дјецом у Христу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Млијеком вас напојих а не јелом, јер још не могасте, и ни сад још не можете,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Јер сте још тјелесни. Јер гдје су међу вама зависти и свађе и неслоге, нијесте ли тјелесни, и не живите ли по човјеку?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Јер кад говори ко: ја сам Павлов; а други: ја сам Аполов; нијесте ли тјелесни?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Ко је дакле Павле а ко ли Аполо до само слуге кроз које вјеровасте, као што и свакоме Господ даде?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Ја посадих, Аполо зали, а Бог даде те узрасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Тако нити је онај што који сади, ни онај који заљева, него Бог који даје те расте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'А онај који сади и који заљева једнаки су; и сваки ће примити своју плату по својему труду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Јер ми смо Богу помагачи, а ви сте Божија њива, Божија грађевина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'По благодати Божијој која ми је дана ја као премудри неимар поставих темељ, а други зида у висину; али сваки нека гледа како зида.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Јер темеља другога нико не може поставити осим онога који је постављен, који је Исус Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Ако ли ко зида на овоме темељу, злато, сребро, драго камење, дрва, сијено, сламу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'Свакога ће дјело изићи на видјело; јер ће дан показати, јер ће се огњем открити, и свако дјело показаће огањ као што јест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'И ако остане чије дјело што је назидао, примиће плату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'А чије дјело изгори, отићи ће у штету: а сам ће се спасти тако као кроз огањ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Не знате ли да сте ви црква Божија, и Дух Божиј живи у вама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Ако поквари ко цркву Божију, поквариће њега Бог: јер је црква Божија света, а то сте ви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Нико нека се не вара: ако ко међу вама мисли да је мудар на овоме свијету, нека буде луд да буде мудар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Јер је премудрост овога свијета лудост пред Богом, јер је писано: хвата премудре у њихову лукавству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'И опет: Господ зна помисли мудријех да су ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Зато нико да се не хвали човјеком, јер је све ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Био Павле, или Аполо, или Кифа, или свијет, или живот или смрт, или садашње, или будуће: све је ваше; А ви сте Христови а Христос Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Тако да нас држе људи као слуге Христове и приставе тајна Божијих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'А од пристава се не тражи више ништа, него да се ко вјеран нађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'А ја мало марим што ме судите ви или човјечиј дан; а ни сам себе не судим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Јер не знам ништа на себи; но за то нијесам оправдан, али онај који мене суди Господ је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Зато не судите ништа прије времена, докле Господ не дође, који ће изнијети на видјело што је сакривено у тами и објавиће савјете срдачне и тада ће похвала бити свакоме од Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'А ово, браћо моја, приговорих себи и Аполу вас ради, да се од нас научите да не мислите за себе више него што је написано, и да се кога ради не надимате један на другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Јер ко тебе повишује? Шта ли имаш што нијеси примио? А ако си примио, што се хвалиш као да нијеси примио?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Ето сте сити, ето се обогатисте, без нас царујете. О да бисте царовали, да бисмо и ми с вама царовали!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Јер мислим да Бог нас апостоле најстражње постави, као оне који су на смрт осуђени; јер бисмо гледање и свијету и анђелима и људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Ми смо будале Христа ради, а ви сте мудри у Христу; ми слаби, а ви јаки; ви славни, а ми срамотни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'До овога часа и гладујемо, и трпимо жеђу, и голотињу, и муке и потуцамо се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'И трудимо се радећи својијем рукама. Кад нас псују, благосиљамо; кад нас гоне трпимо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Кад хуле на нас, молимо; постасмо као сметлиште свијета, по којему сви газе досад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Не пишем ја ово да посрамим вас, него вас учим као своју љубазну дјецу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Јер ако имате и триста учитеља у Христу, али немате много отаца. Јер вас ја у Христу Исусу родих јеванђељем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Него вас молим, угледајте се на мене као и ја на Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Зато послах к вама Тимотија, који ми је син љубазни и вјерни у Господу; он ће вам опоменути путове моје који су у Христу Исусу, као што свуда и у свакој цркви учим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Неки се надуше као да ја нећу доћи к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Али ћу вам доћи скоро, ако Бог да, и нећу гледати на ријечи онијех што су се надули, него на силу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Јер царство Божије није у ријечи него у сили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Шта хоћете? да дођем к вама с прутом или с љубави и духом кротости?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Врло се гласи да је курварство међу вама, и таково курварство каково се ни међу незнабошцима не чује, да некакав има жену очину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'И ви се још надимате, мјесто да плачете, да се извади између вас онај који је учинио то дјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Јер ја, који ако нијесам код вас тијелом али духом ту живим, већ отсудих као да сам тамо, да се онај који је то тако учинио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'У име Господа нашега Исуса Христа кад се саберете ви и мој дух, са силом Господа нашега Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Да се он преда сотони на мучење тијела, да би се дух спасао у дан Господа нашега Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Није добра хвала ваша. Не знате ли да мало квасца све тијесто укисели?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Очистите дакле стари квасац, да будете ново тијесто, као што сте пријесни; јер и пасха наша закла се за нас, Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Зато да празнујемо не у староме квасцу, ни у квасцу пакости и лукавства, него у пријесноме хљебу чистоте и истине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Писах вам у посланици да се не мијешате с курварима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'И то ја не рекох за курваре овога свијета, или тврдице или идолопоклонике; јер бисте морали изићи из свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'А сад вам писах да се не мијешате ако који који се брат зове, постане курвар, или тврдица, или идолопоклоник, или кавгаџија, или пијаница, или хајдук; с таковима да и не једете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Јер шта је мени стало да судим оне који су напољу? Не судите ли ви оне који су унутра?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'А оне који су напољу судиће Бог. Извадите злога између себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Смије ли који од вас, кад има тужбу на другога, ићи на суд неправеднима, а не светима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Не знате ли да ће свети судити свијету? Кад ћете дакле ви свијету судити нијесте ли вриједни судити мањијем стварима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Не знате ли да ћемо анђелима судити, акамоли стварима овога свијета?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'А ви кад имате тужбе за ствари овога свијета, узмете за судије оне које у цркви не броји нико у што!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'На срамоту вашу говорим: зар нема међу вама ниједнога мудра који може расудити међу браћом својом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Него се брат с братом суди, и то пред невјернима!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'И то је већ врло срамно за вас да имате тужбе међу собом. Зашто радије не трпите неправду? Зашто радије не прегорите штету?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Него ви сами чините неправду и штету, па још браћи!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Или не знате да неправедници неће наслиједити царства Божијега? Не варајте се: ни курвари, ни идолопоклоници, ни прељубочинци, ни аџувани, ни мужеложници,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Ни лупежи, ни лакомци, ни пијанице, ни кавгаџије, ни хајдуци, царства Божијега неће наслиједити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'И овакови бијасте неки; него се опрасте и посветисте и оправдасте именом Господа нашега Исуса Христа и Духом Бога нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Све ми је слободно, али није све на корист; све ми је слободно, али нећу да што облада мноме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Јела су за трбух, и трбух је за јела; али ће Бог и ова и онога покварити. А тијело није за курварство, него за Господа, и Господ за тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'А Бог и Господа подиже, и нас ће подићи силом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Не знате ли да су тјелеса ваша уди Христови? Хоћу ли дакле узети уде Христове и од њих начинити уде курвине? Боже сачувај!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Или не знате да ко се с курвом свеже једно тијело с њом постане? Јер, рече, биће двоје једно тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'А ко се Господа држи један је дух с Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Бјежите од курварства; јер сваки гријех који човјек чини осим тијела је; а који се курва он гријеши своме тијелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Или не знате да су тјелеса ваша црква светога Духа који живи у вама, којега имате од Бога, и нијеста своји?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Јер сте купљени скупо. Прославите дакле Бога у тјелесима својијем и у душама својијем, што је Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'А за оно што ми писасте: добро је човјеку да се не дохвата до жене:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Али због курварства сваки да има своју жену, и свака жена да има својега мужа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Муж да чини жени дужну љубав, тако и жена мужу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Жена није господар од својега тијела, него муж; тако и муж није господар од својега тијела, него жена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Не забрањујте се једно од другога, већ ако у договору за вријеме, да се постите и молите Богу; и опет да се састанете, да вас сотона не искуша вашијем неуздржањем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Али ово говорим по свјету а не по заповијести;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Јер хоћу да сви људи буду као и ја; али сваки има свој дар од Бога: овај дакле овако а онај онако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'А неожењенијем и удовицама велим: добро им је ако остану као и ја што сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Ако ли се не уздрже, нека се жене и удају; јер је боље женити се неголи упаљивати се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'А ожењенијем заповиједам, не ја него Господ, да се жена од мужа не раздваја');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, '(Ако се се пак и раздвоји, да се више не удаје, или да се помири са својијем мужем); и муж да не пушћа жене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'А осталима говорим ја а не Господ: ако који брат има жену некрштену и она се приволи живљети с њим, да је не оставља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'И жена ако има мужа некрштена и он се приволи живљети с њом, да га не оставља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Јер се посвети муж некрштен женом крштеном, и посвети се жена некрштена од мужа крштенога; јер иначе дјеца ваша била би нечиста, а сад су света.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Ако ли се некрштени раздваја, нека се раздвоји; јер се брат или сестра у таковом догађају не зароби; јер нас на мир дозва Господ Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Јер шта знаш, жено, да ако мужа спасеш? или шта знаш, мужу, да ако жену спасеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Само као што је Бог раздијелио свакоме, и као што је свакога позвао Господ онако нека живи. И тако заповиједам по свијем црквама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Је ли ко позват обрезан, нека се не гради необрезан; ако ли је ко позват необрезан, нека се не обрезује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Обрезање је ништа, и необрезање је ништа; него држање заповијести Божијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Сваки нека остане у ономе звању у коме је позван.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Јеси ли позван роб, не брини се; него ако и можеш свој бити, још радије буди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Јер који је позван у Господу роб, слободњак је Господњи, тако и који је позван слободњак, роб је Христов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Купљени сте скупо, не будите робови људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Сваки, браћо, у чему је ко позван у ономе нека остане пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'А за дјевојке немам заповијести Господње, него дајем свјет, као који сам помилован од Господа, да будем вјеран.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Мислим дакле ово да ће бити добро за садашњу невољу да је човјеку добро тако бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Јеси ли се привезао за жену, не тражи да се раздријешиш; јеси ли се одријешио од жене, не тражи жене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'А ако ли се и ожениш, нијеси сагријешио; и дјевојка ако се уда, није сагријешила: али ће имати такови невоље тјелесне; а ја вас жалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'А ово говорим, браћо, јер је остало вријеме прекраћено, да ће и они који имају жене бити као они који немају;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'И који плачу као који не плачу; и који се радују као који се не радују; и који купују као који немају;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'И који овај свијет употребљавају као да га не употребљавају: јер пролази обличје овога свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'А ја хоћу да сте ви безбрижни. Ко је неожењен брине се за Господње, како ће угодити Господу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'А који је ожењен брине се за свјетско, како ће угодити жени. Друго је жена, а друго је дјевојка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Која је неудата брине се за Господње, како ће угодити Господу, да буде света и тијелом и духом; а која је удата брине се за свјетско, како ће угодити мужу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'А оно говорим на корист вама самијем, не да вам наметнем замку на врат, него за лијепу и пристојну службу Господу без сметње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Ако ли пак ко мисли да је срамота за његову дјевојку кад остане усидјелица, и не може друкчије бити, нека чини шта хоће, не гријеши ако се уда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'А који стоји тврдо у срцу, и нема невоље, а има власт над својом вољом, и ово је расудио у срцу својему да задржи дјевојку, добро чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Тако и онај који удаје своју дјевојку добро чини; али који не удаје боље чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Жена је привезана законом докле јој год живи муж; а ако јој умре муж, слободна је за кога хоће да се уда, само у Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Али је блаженија ако остане тако по мојему свјету; јер мислим да и ја имам Духа Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'А за месо што је клато идолима знамо, јер сви разум имамо. Разум дакле надима, а љубав поправља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Ако ли ко мисли да што зна, не зна још ништа као што треба знати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'А ако ко љуби Бога, Бог га је научио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'А за јело идолскијех жртава, знамо да идол није ништа на свијету, и да нема другога Бога осим јединога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Јер ако и има који се богови зову, или на небу или на земљи, као што има много богова и много господа:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Али ми имамо само једнога Бога оца, од којега је све, и ми у њему, и једнога Господа Исуса Христа, кроз којега је све, и ми кроза њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Али нема сватко разума; јер неки који још и сад мисле да су идоли нешто, као идолске жртве једу, и савјест њихова, слаба будући, погани се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Али јело нас не поставља пред Богом: јер нити ћемо бити већи ако једемо, ни мањи ако не једемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Али се чувајте да како ова слобода ваша не постане спотицање слабима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Јер ако тебе, који имаш разум, види ко у идолској цркви гдје сједиш за трпезом, неће ли његова савјест, слаба будући, ослободити се да једе идолске жртве?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'И с твога разума погинуће слаби брат, за којега Христос умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Тако кад се гријешите о браћу, и бијете њихову слабу савјест, о Христа се гријешите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Зато ако јело саблажњава брата мојега, нећу јести меса довијека, да не саблазним брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Нијесам ли ја апостол? Нијесам ли сам свој? Не видјех ли ја Исуса Христа, Господа нашега? Нијесте ли ви дјело моје у Господу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Ако другима и нијесам апостол, али вама јесам, јер сте ви печат мојега апостолства у Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Мој одговор онима који ме успитају ово је:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Еда ли немамо власти јести и пити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Еда ли немамо власти сестру жену водити, као и остали апостоли, и браћа Господња, и Кифа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Или један ја и Варнава немамо власти ово чинити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Ко војује кад о своме трошку? Или ко сади виноград и од родова његовијех да не једе? Или ко пасе стадо и од млијека стада да не једе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Еда ли ово говорим по човјеку? Не говори ли ово и закон?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Јер је у Мојсијеву закону написано: да не завежеш уста волу који врше. Еда ли се Бог брине за волове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Или јамачно говори за нас? Јер се за нас написа: који оре треба у надању да оре; и који врше у надању да ће добити од онога што врше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Када ми вама духовна сијасмо, је ли то што велико ако ми вама тјелесна пожњемо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Кад се други мијешају у вашу власт, акамоли не би ми? Али не учинисмо по власти овој него све трпимо да не учинимо каке сметње јеванђељу Христову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Не знате ли да они који чине свету службу од светиње се хране? и који олтару служе с олтаром дијеле?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Тако и Господ заповједи да они који јеванђеље проповиједају од јеванђеља живе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'А ја то ниједно не учиних. И не пишем ово да тако буде за мене; јер бих вољео умријети него да ко славу моју уништи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Јер ако проповиједам јеванђеље, нема ми хвале: јер ми је за невољу; и тешко мени ако јеванђеља не проповиједам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Ако дакле ово чиним од своје воље, плату имам; а ако ли чиним за невољу, служба ми је предата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Каква ми је дакле плата? Да проповиједајући јеванђеље учиним без плате јеванђеље Христово, да не чиним по својој власти у проповиједању јеванђеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Јер премда сам слободан од свију, свима себе учиних робом, да их више придобијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Јеврејима сам био као Јеврејин да Јевреје придобијем; онима који су под законом био сам као под законом, да придобијем оне који су под законом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Онима који су без закона био сам као без закона, премда нијесам Богу без закона него сам у закону Христову, да придобијем оне који су без закона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Слабима био сам као слаб, да слабе придобијем; свима сам био све, да какогод спасем кога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'А ово чиним за јеванђеље, да бих имао дијел у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Не знате ли да они што трче на трку, сви трче, а један добије дар? Тако трчите да добијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Сваки пак који се бори од свега се уздржава: они дакле да добију распадљив вијенац, а ми нераспадљив.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Ја дакле тако трчим, не као на непоуздано; тако се борим, не као онај који бије вјетар;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'Него морим тијело своје и трудим да како сам другима проповиједајући избачен не будем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Али нећу вам затајити, браћо, да оцеви наши сви под облаком бише, и сви кроз море прођоше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'И сви се у Мојсија крстише у облаку и мору;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'И сви једно јело духовно једоше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'И сви једно пиће духовно пише; јер пијаху од духовне стијене која иђаше за њима: а стијена бјеше Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Али многи од њих не бијаху по Божијој вољи, јер бише побијени у пустињи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'А ово бише угледи нама, да ми не желимо зала, као и они што жељеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Нити бивајте идолопоклоници, као неки од њих, као што стоји написано: сједоше људи да једу и да пију, и усташе да играју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Нити да се курвамо, као неки од њих што се курваше, и паде их у један дан двадесет и три хиљаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Нити да кушамо Христа, као што неки од њих кушаше, и од змија изгибоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Нити да вичемо на Бога, као неко од њих што викаше, и изгибоше од крвника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Ово се пак све догађаше угледи њима, а написа се за науку нама, на које пошљедак свијета дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Јер који мисли да стоји нека се чува да не падне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Друго искушење не дође на вас осим човјечијега; али је вјеран Бог који вас неће пустити да се искушате већма него што можете, него ће учинити с искушењем и крај, да можете поднијети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Зато, љубазна браћо моја, бјегајте од идолопоклонства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Као мудрима говорим; судите ви шта говорим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Чаша благослова коју благосиљамо није ли заједница крви Христове? Хљеб који ломимо није ли заједница тијела Христова?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Јер смо један хљеб, једно тијело многи; јер сви у једноме хљебу имамо заједницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Гледајте Израиља по тијелу: који једу жртве нијесу ли заједничари олтара?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Шта дакле говорим? да је идол што? или идолска жртва да је што?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Није; него што жртвују незнабошци, да ђаволима жртвују, а не Богу; а ја нећу да сте ви заједничари са ђаволима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Не можете пити чаше Господње и чаше ђаволске; не можете имати заједнице у трпези Господњој и у трпези ђаволској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Или да пркосимо Господу? Еда ли смо ми јачи од њега?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Све ми је слободно, али није све на корист; све ми је слободно, али све не иде на добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Нико да не гледа што је његово, него сваки да гледа што је другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Све што се продаје на месарници, једите, и ништа не испитујете савјести ради;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Јер је Господња земља и што је на њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Ако ли вас ко од невјерника позове, и хоћете ићи, једите све што се пред вас донесе, и не премишљајте ништа савјести ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Ако ли вам пак ко рече: ово је идолска жртва, не једите ради онога који вам каже, и ради савјести; јер је Господња земља и што је на њој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Али не говорим за савјест твоју, него другога; јер зашто да моју слободу суди савјест другога?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Ако ја с благодаћу уживам, зашто да се хули на мене за оно за што ја захваљујем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Ако дакле једете, ако ли пијете, ако ли што друго чините, све на славу Божију чините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Не будите на саблазан ни Јеврејима, ни Грцима, ни цркви Божијој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Као што ја у свачему свима угађам, не тражећи своје користи него многијех, да се спасу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Угледајте се на мене, као и ја на Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Хвалим вас пак, браћо, што све моје памтите и држите заповијести као што вам предадох.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Али хоћу да знате да је свакоме мужу глава Христос; а муж је глава жени; а Бог је глава Христу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Сваки муж који се с покривеном главом моли Богу или пророкује, срамоти главу своју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'И свака жена које се гологлава моли Богу или пророкује, срамоти главу своју; јер је све једно као да је обријана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Ако се дакле не покрива жена, нека се стриже; ако ли је ружно жени стрићи се или бријати се, нека се покрива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Али муж да не покрива главе, јер је обличје и слава Божија; а жена је слава мужевља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Јер није муж од жене него жена од мужа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Јер муж није саздан жене ради него жена мужа ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Зато жена треба да има власт на глави, анђела ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Али нити је муж без жене ни жена без мужа у Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Јер како је жена од мужа, тако је и муж од жене; а све је од Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Сами међу собом судите је ли лијепо да се жена гологлава моли Богу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Или не учи ли вас и сама природа да је мужу срамота ако гаји дугачку косу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'А жени је слава ако гаји дугачку косу? Јер јој је коса дана мјесто покривала.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Ако ли је ко свадљив, ми таковога обичаја немамо, нити цркве Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Али ово заповиједајући не хвалим да се не на боље него на горе сабирате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Прво дакле кад се сабирате у цркву, чујем да имају распре међу вама, и нешто вјерујем од овога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Јер треба и јереси да буду међу вама, да се покажу поштени који су међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'А кад се скупите на једно мјесто, не једе се вечера Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Јер сваки своју вечеру узме најприје и једе, и тако један гладује а други се опија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Еда ли дакле немате кућа да једете и пијете? Или не марите за цркву Божију, и срамотите оне који немају? Шта ћу вам рећи? Хоћу ли вас похвалити за то? Нећу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Јер ја примих од Господа што вам и предадох, да Господ Исус ону ноћ у коју биваше предан узе хљеб.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'И захваливши преломи и рече: узмите, једите, ово је тијело моје које се за вас ломи; ово чините мени за спомен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Тако и чашу, по вечери, говорећи: ово је чаша нови завјет у мојој крви; ово чините, кад год пијете, мени за спомен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Јер кад год једете овај хљеб и чашу ову пијете, смрт Господњу обзнањујете, докле не дође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Тако који недостојно једе овај хљеб или пије чашу Господњу, крив је тијелу и крви Господњој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Али човјек да испитује себе, па онда од хљеба да једе и од чаше да пије;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Јер који недостојно једе и пије, суд себи једе и пије, не разликујући тијела Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Зато су међу вама многи слаби и болесни, и довољно их спавају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Јер кад бисмо себе расуђивали, не бисмо осуђени били.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Али кад смо суђени, наказује нас Господ, да се не осудимо са свијетом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Зато, браћо моја, кад се састајете да једете, ишчекујте један другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Ако ли је ко гладан, нека једе код куће, да се на гријех не састајете. А за остало уредићу кад дођем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'А за духовне дарове нећу вам, браћо, затајити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Знате, да кад бијасте незнабошци, идосте к идолима безгласнима, како вас вођаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Зато вам дајем на знање да нико ко духом Божијим говори неће рећи: анатемате Исуса; и нико не може Исуса Господом назвати осим Духом светијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Дарови су различни, али је Дух један.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'И различне су службе, али је један Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'И различне су силе, али је један Бог који чини све у свему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'А у свакоме се појављује Дух на корист;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Јер једноме се даје Духом ријеч премудрости; а другоме ријеч разума по истоме Духу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'А другоме вјера, тијем истијем Духом; а другоме дар исцјељивања, по томе истом Духу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'А другоме да чини чудеса, а другоме пророштво, а другоме да разликује духове, а другоме различни језици, а другоме да казује језике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'А ово све чини један и тај исти Дух раздјељујући по својој власти свакоме како хоће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Јер као што је тијело једно и уде има многе, а сви уди једнога тијела, премда су многи, једно су тијело: тако и Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Јер једнијем духом ми се сви крстисмо у једно тијело, били Јевреји, или Грци, или робови, или сами своји; и сви се једнијем Духом напојисмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Јер тијело није један уд, него многи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Ако рече нога: ја нијесам рука, нијесам од тијела; еда ли зато није од тијела?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'И ако рече ухо: ја нијесам око, нијесам од тијела; еда ли зато није од тијела? Кад би све тијело било око, гдје је чувење?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'А кад би све било чувење, гдје је мирисање?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Али Бог постави све уде у тијелу како је кога хтио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'А кад би сви били један уд, гдје је тијело?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Сад су пак многи уди а једно тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Али око не може рећи руци: не требаш ми; или опет глава ногама: не требате ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Него још који се уди тијела чине да су најслабији најпотребнији су.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'И који нам се чине да су најсрамотнији на тијелу, на оне ударамо највећу част;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'И непоштени наши уди највеће поштење имају; а поштени уди не требају. Али Бог сложи тијело и најхуђему уду даде највећу част,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'Да не буде распре у тијелу, него да се уди једнако брину један за другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'И ако страда један уд, с њим страдају сви уди; а ако ли се један уд слави, с њим се радују сви уди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'А ви сте тијело Христово, и уди међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'И једне дакле постави Бог у цркви прво апостоле, друго пророке, треће учитеље, а потом чудотворце, онда дарове исцјељивања, помагања, управљања, различне језике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Еда ли су сви апостоли? Еда ли су сви пророци? Еда ли су сви учитељи? Еда ли су сви чудотворци?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Еда ли сви имају дарове исцјељивања? Еда ли сви говоре језике? Еда ли сви казују?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Старајте се пак за веће дарове; па ћу вам још бољи пут показати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Ако језике човјечије и анђелске говорим а љубави немам, онда сам као звоно које звони, или прапорац који звечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'И ако имам пророштво и знам све тајне и сва знања, и ако имам сву вјеру да и горе премјештам, а љубави немам, ништа сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'И ако раздам све имање своје, и ако предам тијело своје да се сажеже, а љубави немам, ништа ми не помаже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Љубав дуго трпи, милокрвна је; љубав не завиди; љубав се не велича, не надима се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'Не чини што не ваља, не тражи своје, не срди се, не мисли о злу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Не радује се неправди, а радује се истини,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Све сноси, све вјерује, свему се нада, све трпи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Љубав никад не престаје, а пророштво ако ће и престати, језици ако ће умукнути, разума ако ће нестати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Јер нешто знамо и нешто пророкујемо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'А кад дође савршено, онда ће престати што је нешто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Кад ја бијах мало дијете као дијете говорах, као дијете мишљах, као дијете размишљавах; а кад постадох човјек, одбацих дјетињство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Тако сад видимо као кроз стакло у загонетки, а онда ћемо лицем к лицу; сад познајем нешто, а онда ћу познати као што сам познат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'А сад остаје вјера, над, љубав, ово троје; али је љубав највећа међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Држите се љубави, а старајте се за духовне дарове, а особито да пророкујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Јер који говори језике, не говори људима него Богу: јер нико не слуша, а он духом говори тајне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'А који пророкује говори људима за поправљање и утјеху и утврђење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Јер који говори језике себе поправља, а који пророкује цркву поправља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Али ја бих хтио да ви сви говорите језике, а још више да пророкујете: јер је већи онај који пророкује неголи који говори језике, већ ако ко казује, да се црква поправља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'А сад, браћо, ако дођем к вама језике говорећи, каку ћу корист учинити ако вам не говорим или у откривењу, или у разуму, или у пророштву, или у науци?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Као неке ствари бездушне које дају глас, била свирала или гусле, ако различна гласа не дају, како ће се разумјети шта се свира или гуди?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Јер ако труба да неразговијетан глас, ко ће се приправити на бој?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Тако и ви ако неразумљиву ријеч речете језиком, како ће се разумјети шта говорите? Јер ћете говорити у вјетар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Има на свијету богзна колико различнијех гласова, али ниједан није без значења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Ако дакле не знам силе гласа, бићу нијемац ономе коме говорим, и онај који говори биће мени нијемац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Тако и ви, будући да се старате за духовне дарове, гледајте да будете онима богати који су на поправљање цркве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Зато који говори језиком нека се моли Богу да казује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Јер ако се језиком молим Богу, мој се дух моли, а ум је мој без плода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Шта ће се дакле чинити? Молићу се Богу духом, а молићу се и умом; хвалићу Бога духом, а хвалићу и умом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Јер кад благословиш духом како ће онај који стоји мјесто простака рећи амин по твоме благослову, кад не зна шта говориш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Ти добро захваљујеш, али се други не поправља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Хвала Богу мојему што говорим језике већма од свију вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Али у цркви волим пет ријечи умом својијем рећи, да се и други помогну, неголи хиљаду ријечи језиком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Браћо! не будите дјеца умом, него пакошћу дјетињите, а умом будите савршени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'У закону пише: другијем језицима и другијем уснама говорићу народу овоме, и ни тако ме неће послушати, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Зато су језици за знак не онима који вјерују, него који не вјерују; а пророштво не онима који не вјерују, него који вјерују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Ако се дакле скупи црква сва на једно мјесто, и сви узговорите језицима, а дођу и простаци, или невјерници, неће ли рећи да сте полудјели?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'А ако сви пророкују, и дође какав невјерник или простак, буде покаран од свију и суђен од свију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'И тако тајне срца његова бивају јављене, и тако паднувши ничице поклониће се Богу, и казаће да је заиста Бог с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Шта ће се дакле чинити, браћо? Кад се сабирате сваки од вас има псалам, има науку, има језик, има откривење, има казивање; а све да бива на поправљање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Ако ко говори језиком, или по двојица, или највише по тројица и то поредом; а један да казује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Ако ли не буде никога да казује, нека ћути у цркви, а себи нека говори и Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'А пророци два или три нека говоре, и други нека расуђују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Ако ли се открије што другоме који сједи, нека чека док први ућути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Јер можете пророковати сви, један по један, да се сви уче, и сви да се тјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'И духови пророчки покоравају се пророцима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Јер Бог није Бог буне, него мира, као по свима црквама светијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Жене ваше да ћуте у црквама; јер се њима не допусти да говоре, него да слушају, као што и закон говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Ако ли хоће чему да се науче, код куће мужеве своје нека питају; јер је ружно жени да говори у цркви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Еда ли од вас ријеч Божија изиђе? или самијем вама дође?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Ако ко мисли да је пророк или духован, нека разумије што вам пишем, јер су Господње заповијести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Ако ли ко не разумије, нека не разумије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Зато, браћо моја, старајте се да пророкујете, и не забрањујте говорити језицима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'А све нека бива поштено и уредно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Али вам напомињем, браћо, јеванђеље, које вам објавих, које и примисте, у коме и стојите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'Којијем се и спасавате, ако држите како вам објавих; већ ако да узалуд вјеровасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Јер вам најприје предадох што и примих да Христос умрије за гријехе наше, по писму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'И да би укопан, и да уста трећи дан, по писму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'И да се јави Кифи, потом једанаесторици апостола;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'А потом га видјеше једном више од пет стотина браће, од којијех многи живе и сад, а неки и помријеше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'А потом се јави Јакову, па онда свима апостолима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'А послије свију јави се и мени као каквом недоношчету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Јер ја сам најмлађи међу апостолима, који нијесам достојан назвати се апостол, јер гоних цркву Божију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Али по благодати Божијој јесам што јесам, и благодат његова што је у мени не оста празна, него се потрудих више од свију њих, али не ја него благодат Божија која је са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Био дакле ја или они, тако проповиједамо, и тако вјеровасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'А ако се Христос проповиједа да устаде из мртвијех, како говоре неки међу вама да нема васкрсенија мртвијех?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'И ако нема васкрсенија мртвијех, то ни Христос не уста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'А ако Христос не уста, узалуд дакле проповиједање наше, а узалуд и вјера ваша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'А налазимо се и лажни свједоци Божији што свједочимо на Бога да васкрсе Христа, којега не васкрсе кад мртви не устају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Јер ако мртви не устају, ни Христос не уста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'А ако Христос не уста, узалуд вјера ваша: још сте у гријесима својијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Дакле и они који помријеше у Христу, изгибоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'И ако се само у овом животу уздамо у Христа, најнесрећнији смо од свију људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Али Христос уста из мртвијех, и би новина онима који умријеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Јер будући да кроз човјека би смрт, кроз човјека и васкрсеније мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Јер како по Адаму сви умиру, тако ће и по Христу сви оживљети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Али сваки у свом реду: новина Христос; а потом они који вјероваше Христу о његову доласку;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Онда крај, кад преда царство Богу и оцу, и кад укине свако поглаварство и сваку власт и силу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Јер њему ваља царовати докле не положи све непријатеље своје под ноге своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'А пошљедњи ће се непријатељ укинути смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Јер све покори под ноге његове. Али кад вели да је све њему покорено, показује се да је осим онога који му покори све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'А кад му све покори, онда ће се и сам син покорити ономе који му све покори, да буде Бог све у свему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Шта дакле чине они који се крсте мртвијех ради? Кад мртви јамачно не устају, што се и кршћавају мртвијех ради?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'И ми зашто подносимо муке и невоље сваки час?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Сваки дан умирем, тако ми, браћо, ваше славе, коју имам у Христу Исусу Господу нашему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Јер ако сам се по човјеку борио са звјеровима у Ефесу, кака ми је корист ако мртви не устају? Да једемо и пијемо, јер ћемо сутра умријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Не варајте се: зли разговори кваре добре обичаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Отријезните се једанпут као што треба, и не гријешите; јер неки не знаду за Бога, на срамоту вама кажем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Али ће вам рећи ко: како ће устати мртви? и у каком ће тијелу доћи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Безумниче! то што сијеш неће оживљети ако не умре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'И што сијеш не сијеш тијело које ће бити, него голо зрно, било пшенично или друго како.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'А Бог му даје тијело како хоће, и сваком сјемену своје тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Није свако тијело једно тијело, него је друго тијело човјечије, а друго скотско, а друго рибље, а друго птичије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'И имају тјелеса небеска и тјелеса земаљска: али је друга слава небескима, а друга земаљскима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Друга је слава сунцу, а друга слава мјесецу, и друга слава звијездама; јер се звијезда од звијезде разликује у слави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Тако и васкрсеније мртвијех: сије се за распадљивост, а устаје за нераспадљивост;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Сије се у срамоти, а устаје у слави; сије се у слабости, а устаје у сили;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Сије се тијело тјелесно, а устаје тијело духовно. Има тијело тјелесно, и има тијело духовно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Тако је и писано: први човјек Адам постаде у тјелесном животу, а пошљедњи Адам у духу који оживљује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Али духовно тијело није прво, него тјелесно, па онда духовно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Први је човјек од земље, земљан; други је човјек Господ с неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Какав је земљани таки су и земљани; и какав је небески таки су и небески.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'И како носимо обличје земљанога тако ћемо носити и обличје небескога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'А ово говорим, браћо, да тијело и крв не могу наслиједити царства Божијега, нити распадљивост нераспадљивости нашљеђује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Ево вам казујем тајну: јер сви нећемо помријети, а сви ћемо се претворити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'Уједанпут, у тренућу ока у пошљедњој труби; јер ће затрубити и мртви ће устати нераспадљиви, и ми ћемо се претворити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Јер ово распадљиво треба да се обуче у нераспадљивост, и ово смртно да се обуче у бесмртност.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'А кад се ово распадљиво обуче у нераспадљивост и ово се смртно обуче у бесмртност, онда ће се збити она ријеч што је написана: побједа прождрије смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Гдје ти је, смрти, жалац? Гдје ти је, пакле, побједа?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'А жалац је смрти гријех, а сила је гријеха закон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'А Богу хвала који нам даде побједу кроз Господа нашега Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Зато, браћо моја љубазна, будите тврди, не дајте се помакнути, и напредујте једнако у дјелу Господњему знајући да труд ваш није узалуд пред Господом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'А за милостињу светима, као што уредих по црквама Галатијскијем онако и ви чините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Сваки први дан недјеље нека сваки од вас оставља код себе и скупља колико може, да не бивају збирања кад дођем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'А кад дођем, које нађете за вриједне оне ћу с посланицама послати у Јерусалим нека однесу вашу помоћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'А ако буде вриједно да и ја идем, поћи ће са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'А к вама ћу доћи кад прођем Маћедонију, јер ћу проћи кроз Маћедонију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'А у вас може бити да ћу се забавити, или и зимовати, да ме ви пратите куд пођем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Сад вас у пролажењу нећу видјети, а надам се неко вријеме остати код вас, ако Господ допусти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'А у Ефесу ћу остати до Тројичина дне;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Јер ми се отворише велика и богата врата, и противника има много.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'А ако дође Тимотије, гледајте да буде код вас без страха; јер он ради дјело Господње као и ја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Да га нико дакле не презре, него га испратите с миром да дође к мени; јер га чекам с браћом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'А за брата Апола, много га молих да дође к вама с браћом: и никако не бјеше му воља да сад дође; али ће доћи кад имадбуде кад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Пазите, стојте у вјери, мушки се држите, утврђујте се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Све да вам бива у љубави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Молим вас пак, браћо, знате дом Стефанин да је новина од Ахаје, и на служење светима одреди се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'Да сте и ви покорни таковима, и свакоме који помаже и труди се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Али се обрадовах доласку Стефанину и Фортунатову и Ахајикову, јер ми они накнадише што сам био без вас;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Јер умирише дух мој и ваш. Припознајте дакле такове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Поздрављају вас цркве Азијске. Поздрављају вас у Господу много Акила и Прискила с домашњом својом црквом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Поздрављају вас браћа сва. Поздравите један другога цјеливом светијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Поздрављам вас ја Павле својом руком.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Ако ко не љуби Господа Исуса Христа да буде проклет, маран ата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Благодат Господа нашега Исуса Христа с вама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'И љубав моја се свима вама у Христу Исусу. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Од Павла, апостола Исуса Христа по вољи Божијој и брата Тимотија цркви Божјој у Коринту, са свима светима који су у свој Ахаји:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Благодат вам и мир од Бога оца нашега, и Господа Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Благословен Бог и отац Господа нашега Исуса Христа, отац милости и Бог сваке утјехе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Који нас утјешава у свакој невољи нашој, да бисмо могли утјешити оне који су у свакој невољи утјехом којом нас саме Бог утјешава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Јер како се страдања Христова умножавају на нама тако се и утјеха наша умножава кроз Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Ако ли смо пак у невољи, за вашу је утјеху и спасеније, које постаје у трпљењу тијех истијех страдања која и ми подносимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'И надање наше тврдо је за вас. Ако ли се утјешавамо, за вашу је утјеху и спасеније, знајући да као што сте заједничари у нашему страдању тако и у утјеси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Јер вам нећемо, браћо, затајити невоље наше која нам се догоди у Азији кад нам је било претешко и преко силе тако да се нијесмо надали ни живљети;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Него сами у себи осудисмо да нам ваља помријети да се већ не уздасмо у себе него у Бога који подиже мртве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Који нас је од толике смрти избавио, и избавља; и у њега се уздамо да ће нас и још избавити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'С помоћу и ваше молитве за нас; да многи људи многу хвалу дају Богу за даре који су нама дати вас ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Јер је наша слава ово: свједочанство савјести наше да смо у простоти и чистоти Божијој а не у мудрости тјелесној него по благодати Божијој живљели на свијету, а особито међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Јер вам друго не пишемо него што читате и разумијевате. А надам се да ћете и до краја разумјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Као што неки и разумјесте да смо вам слава као и ви нама за дан Господа нашега Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'И у овом поуздању шћадијах да вам дођем прије, да другу благодат имате;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'И кроз вас да дођем у Маћедонију, и опет из Маћедоније да дођем к вама, и ви да ме пратите у Јудеју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Али кад сам ово хтио, еда ли сам дакле што непристојно чинио? Или што се накањујем, да се по тијелу накањујем, да буде у мене да да, а не не?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Али је Бог вјеран, те ријеч наша к вама не би да и не.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Јер син Божиј Исус Христос, којега ми вама приповиједасмо ја и Силван и Тимотије, не би да и не, него у њему би да.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Јер колико је обећања Божијех, у њему су да, и у њему амин, Богу на славу кроз нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'А Бог је који нас утврди с вама у Христу, и помаза нас,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Који нас и запечати, и даде залог Духа у срца наша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'А ја за свједока Бога призивам на своју душу да штедећи вас не дођох више у Коринт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Не као да ми владамо вјером вашом, него смо помагачи ваше радости; јер у вјери стојите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Ово пак судих у себи да опет не дођем к вама у жалости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Јер ако ја чиним жалост вама, ко је који ће мене веселити осим онога који прима жалост од мене?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'И писах вам ово исто, да кад дођем не примим жалост на жалост, а за које би ваљало да се веселим надајући се на све вас да је моја радост свију вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Јер од бриге многе и туге срца написах вам с многијем сузама, не да бисте се ожалостили него да бисте познали љубав коју имам изобилно к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Ако ли је ко мене ражалио, не ражали мене, до неколико, да не отежам свима вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Јер је довољно таковоме кар овај од многијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Зато ви насупрот већма да опраштате и тјешите, да такови како не падне у превелику жалост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Зато вас молим, утврдите к њему љубав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Јер вам зато и писах, да познам поштење ваше јесте ли у свачему послушни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'А коме ви што опростите ономе опраштам и ја; јер ја ако што коме опростих, опростих му вас ради мјесто Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Да нас не превари сотона; јер знамо шта он мисли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'А кад дођох у Троаду да проповиједам јеванђеље Христово, и отворише ми се врата у Господу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Не имадох мира у духу својему, не нашавши Тита, брата својега; него опростивши се с њима изиђох у Маћедонију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Али хвала Богу који свагда нама даје побједу у Христу Исусу, и кроз нас јавља мирис познања својега на сваком мјесту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Јер смо ми Христов мирис Богу и међу онима који се спасавају и који гину:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Једнима дакле мирис смртни за смрт, а другима мирис животни за живот. И за ово ко је вриједан?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Јер ми нијесмо као многи који нечисто проповиједају ријеч Божију, него из чистоте, и као из Бога, пред Богом, у Христу говоримо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Почињемо ли се опет сами хвалити вама? Или требамо као неки препорученијех посланица на вас или од вас?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Јер сте ви наша посланица написана у срцима нашима, коју познају и читају сви људи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Који сте се показали да сте посланица Христова, коју смо ми служећи написали не мастилом него Духом Бога живога, не на каменијем даскама него на меснијем даскама срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'А таково поуздање имамо кроз Христа у Бога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Не да смо врсни од себе помислити што, као од себе, него је наша врсноћа од Бога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'Који и учини нас врсне да будемо слуге новом завјету, не по слову него по духу; јер слово убија, а дух оживљује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Ако ли служба смрти која је у камењу изрезана словима, би у слави да синови Израиљеви не могоше погледати на лице Мојсијево од славе лица његова која престаје:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Акамоли неће много већма служба духа бити у слави?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Јер кад је служба осуђења слава, много већма изобилује служба правде у слави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Јер и није славно што се прослави с ове стране према превеликој слави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Јер кад је славно оно што престаје, много ће већма бити у слави оно што остаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Имајући дакле такови над с великом слободом радимо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'И не као што Мојсије меташе покривало на лице своје, да не би могли синови Израиљеви гледати свршетка ономе што престаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Но заслијепише помисли њихове; јер до самога овог дана стоји оно покривало неоткривено у читању старог завјета, јер у Христу престаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Него да данас кад се чита Мојсије, покривало на срцу њиховом стоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'А кад се обрате ка Господу, узеће се покривало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'А Господ је Дух: а гдје је Дух ондје је слобода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Ми пак сви који откривенијем лицем гледамо славу Господњу, преображавамо се у оно исто обличје из славе у славу, као од Господњега Духа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Зато имајући ову службу као што бисмо помиловани, не досађује нам се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Него се одрекосмо тајнога срама да не живимо у лукавству, нити да изврћемо ријеч Божију, него јављањем истине да се покажемо свакој савјести човјечијој пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Ако ли је пак покривено јеванђеље наше у онима је покривено који гину,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'У којима Бог свијета овога ослијепи разуме невјерника, да им не засвијетли видјело јеванђеља славе Христове, који је обличје Бога, који се не види.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Јер себе не проповиједамо него Христа Исуса Господа, а себе саме ваше слуге Исуса Господа ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Јер Бог који рече да из таме засвијетли видјело, засвијетли у срцима нашима на свјетлост познања славе Божије у лицу Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Али ово благо имамо у земљанијем судовима, да премноштво силе буде од Бога а не од нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'У свему имамо невоље, али нам се не досађује; збуњени смо, али не губимо нада;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Прогоне нас, али нијесмо остављени; обаљују нас, али не гинемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'И једнако носимо на тијелу смрт Господа Исуса, да се и живот Исусов на тијелу нашему покаже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Јер ми живи једнако се предајемо на смрт за Исуса, да се и живот Исусов јави на смртноме тијелу нашему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Зато дакле смрт влада у нама, а живот у вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Имајући пак онај исти дух вјере као што је написано: вјеровах, зато говорих; ми вјерујемо, зато и говоримо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'Знајући да ће онај који подиже Исуса, и нас подигнути с Исусом, и поставити с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Јер је све вас ради, да благодат умножена изобилује хвалама на славу Божију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Зато нам се не досађује; но ако се наш спољашњи човјек и распада, али се унутрашњи обнавља сваки дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Јер наша лака садашња брига доноси нам вјечну и од свега претежнију славу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Нама који не гледамо на ово што се види, него на оно што се не види; јер је ово што се види, за вријеме, а оно што се не види, вјечно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Јер знамо да кад се земаљска наша кућа тијела раскопа, имамо зграду од Бога, кућу нерукотворену, вјечну на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Јер за тијем уздишемо, желећи обући се у свој небески стан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'И да се обучени, не голи нађемо!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Јер будући у овоме тијелу, уздишемо отежали; јер нећемо да се свучемо, него да се преобучемо, да живот прождере смртно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'А онај који нас за ово исто створи, Бог је, који нам и даде залог Духа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Добре смо дакле воље једнако, јер знамо да путујемо у тијелу, далеко од Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Јер по вјери живимо а не по гледању.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Али се не бојимо, и много волимо отићи од тијела, и ићи ка Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Зато се и старамо, или улазили или одлазили, да будемо њему угодни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Јер нам се свима ваља јавити на суду Христову, да примимо сваки што је који у тијелу чинио, или добро или зло;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Знајући дакле страх Господњи људе свјетујемо; а Богу смо познати, а надамо се да смо и у вашијем савјестима познати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Јер се не хвалимо опет пред вама, него вама дајемо узрок да се хвалите нама, да имате што одговорити онима који се хвале онијем што је споља а не што је у срцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Јер ако се одвише хвалимо, Богу се хвалимо; ако ли смо смјерни, вама смо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Јер љубав Божија нагони нас, кад мислимо ово: ако један за све умрије, то дакле сви умријеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'Христос за све умрије, да они који живе не живе више себи, него ономе који за њих умрије и васкрсе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Зато и ми отсад никога не познајемо по тијелу; и ако Христа познасмо по тијелу, али га сад више не познајемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Зато ако је ко у Христу, нова је твар: старо прође, гле, све ново постаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Али је све од Бога, који помири нас са собом кроз Исуса Христа, и даде нам службу помирења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Јер Бог бјеше у Христу, и свијет помири са собом не примивши им гријеха њиховијех, и метнувши у нас ријеч помирења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Тако смо ми послани мјесто Христа, као да Бог говори кроз нас; молимо вас у име Христово помирите се с Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Јер онога које не знадијаше гријеха нас ради учини гријехом, да ми будемо правда Божија у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Молимо вас пак као помагачи да не примите узалуд благодат Божију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Јер он говори: у вријеме најбоље послушах те, и у дан спасенија помогох ти. Ево сад је вријеме најбоље, ево сад је дан спасенија!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Никакво ни у чему не дајете спотицање, да се служба не куди;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Него у свему покажите се као слуге Божије, у трпљењу многом, у невољама, у биједама, у тјеснотама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'У ранама, у тамницама, у бунама, у трудовима, у неспавању, у посту,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'У чистоти, у разуму, у подношењу, у доброти, у Духу светом, у љубави истинитој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'У ријечи истине, у сили Божијој, с оружјем правде и надесно и налијево,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Славом и срамотом, куђењем и похвалом, као варалице и истинити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Као незнани и познати, као они који умиру и ево смо живи, као накажени а не уморени,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'Као жалосни а који се једнако веселе, као сиромашни, а који многе обогаћавају, као они који ништа немају а све имају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Уста наша отворише се к вама, Коринћани, и срце наше распространи се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Вама није тијесно мјесто у нама, али вам је тијесно у срцима вашијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'А да ми вратите (као дјеци говорим), распространите се и ви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Не вуците у туђем јарму невјерника; јер шта има правда с безакоњем? или какву заједницу има видјело с тамом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Како ли се слаже Христос с Велијаром? или какав дијел има вјерни с невјерником?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Или како се удара црква Божија с идолима? Јер сте ви цркве Бога живога, као што рече Бог: уселићу се у њих, и живљећу у њима, и бићу им Бог, и они ће бити мој народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Зато изиђите између њих и одвојте се, говори Господ, и не дохватајте се до нечистоте, и ја ћу вас примити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'И бићу вам отац, и ви ћете бити моји синови и кћери, говори Господ сведржитељ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Имајући дакле овака обећања, о љубазни! да очистимо себе од сваке поганштине тијела и духа, и да творимо светињу у страху Божијему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Примите нас, ником не учинисмо нажао, никога не покварисмо, никога не занесосмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Не говорим на осуђене, јер прије рекох да сте у срцима нашијем, да бих с вама и умро и живљео.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Врло слободно говорим к вама, много се хвалим вама, напунио сам се утјехе, изобилан сам радошћу поред свију брига нашијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Јер кад дођосмо у Маћедонију, никака мира немаше тијело наше, него у свему бијаше у невољи: споља борбе, изнутра страх.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Али Бог, који тјеши понижене, утјеши нас доласком Титовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'А не само доласком његовијем, него и утјехом којом се он утјеши за вас казујући вашу жељу, ваше плакање, ваше страдање за мене, тако да се још већма обрадовах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Јер ако сам вас и ражалио посланицом, не кајем се, ако се и бијах раскајао: јер видим да она посланица, ако и за мало, ражали вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Али се сад радујем, не што бисте жалосни, него што се ожалостисте на покајање: јер се ожалостисте по Богу, да од нас ни у чему не штетујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Јер жалост која је по Богу доноси за спасеније покајање, за које се нигда не каје; а жалост овога свијета смрт доноси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Јер, гле, ово само што се по Богу ожалостисте, колико учини старање међу вама? каково правдање, каку неповољност, какав страх, каку жељу, каку ревност, каку освету? У свему показасте се да сте чисти у дјелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Јер ако вам и писах, не овога ради који је скривио, нити онога ради коме је криво учињено, него да се покаже међу вама старање наше за вас пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Зато се утјешисмо утјехом вашом; а још се већма обрадовасмо радости Титовој, јер ви сви умиристе дух његов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Јер што сам му се за вас похвалио, нијесам се посрамио; него како је све истина што говорисмо вама, тако и похвала наша к Титу истинита би.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'И срце је његово пуно љубави к вама кад се опомиње послушања свију вас, како сте га са страхом и дрктањем примили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Радујем се дакле што се у свему смијем ослонити на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Дајемо вам пак на знање, браћо, благодат Божију која је дана у црквама Маћедонскима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Да у многоме кушању невоља сувишак радости њихове и пуко сиромаштво њихово изобилова у богатству простоте њихове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Јер по могућству њихову (ја сам свједок) и преко могућства добровољни бијаху,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'И с многијем мољењем молише нас да примимо благодат и заједницу службе к светима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'И не као што се надасмо него најприје себе предаше Господу и нама, по вољи Божијој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Да ми умолисмо Тита да као што је почео онако и сврши и међу вама благодат ову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'А ви како сте у свему изобилни, у вјери, и у ријечи, и у разуму, и у сваком старању, и у љубави својој к нама, да и у овој благодати изобилујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Не говорим по заповијести, него кад се други старају, и вашу љубав кушам је ли истинита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Јер знате благодат Господа нашега Исуса Христа да, богат будући, вас ради осиромаши, да се ви његовијем сиромаштвом обогатите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'И свјет дајем у том; јер је ово на корист вама, који не само чините него и хтјети почесте још од лањске године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'А сад довршите то и чинити, да као што би добра воља хтјети тако да буде и учинити, од тога што имате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Јер ако има ко добру вољу, мио је по ономе што има, а не по ономе што нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Јер се не жели да другима буде радост а вама жалост, него једнако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Да у садашње вријеме ваш сувишак буде за њихов недостатак, да и њихов сувишак буде за ваш недостатак; да буде једнакост,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Као што је писано: ко је много скупио, није му претекло; и ко је мало скупио, није му недостало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'А хвала Богу, који је дао таково старање за вас у срце Титово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Јер прими мољење; а будући да се тако врло стара, својевољно отиде к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Посласмо пак с њим и брата, којега је похвала у јеванђељу по свијем црквама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'А не само то, него је и изабран од цркава да иде с нама у ову благодат у којој ми служимо за самога Господа славу и вашу добру вољу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Чувајући се тога да нас ко не покуди за ово обиље у коме ми служимо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'И промишљајући за добро не само пред Богом него и пред људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'А посласмо с њима и брата својега, којега много пута познасмо у многијем стварима да је усталац, а сад много већи због великога надања на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'А за Тита, он је мој друг и помагач међу вама; а за браћу нашу, они су посланици црквени и слава Христова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Покажите дакле на њима свједочанство своје љубави и наше хвале вама и пред црквама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Јер за такову порезу која се купи светима није ми тријебе писати вам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Јер познајем вашу добру вољу, за коју се о вама хвалим Маћедонцима да се Ахаја приготови од лањске године, и ваша ревност раздражи многе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'А браћу послах да се хвала наша вама не испразни у овој ствари, него да будете приготовљени, као што сам говорио;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Да се, ако дођу са мном Маћедонци и нађу вас неприготовљене, не осрамотимо ми (да не речем ви) у тој хвали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Тако нађох да је потребно умолити браћу да напријед иду к вама, и да приправе овај напријед обречени ваш благослов да буде готов тако каконо ти благослов, а не као лакомство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Ово пак велим: који с тврђом сије, с тврђом ће и поожњети; а који благослов сије, благослов ће и пожњети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Сваки по вољи својега срца, а не са жалошћу или од невоље; јер Бог љуби онога који драговољно даје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'А Бог је кадар учинити да је међу вама изобилна свака благодат, да у свему свагда свако довољство имајући изобилујете за свако добро дјело;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Као што је писано: просу, даде сиромасима; правда његова остаје вавијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'А који даје сјеме сијачу, даће и хљеб за јело: и умножиће сјеме ваше, и даће да узрасту жита правде ваше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Да се у свему обогатите за сваку простоту која кроз нас чини хвалу Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Јер служба ове порезе не испуњује само недостатак светијех, него чини те се и многе хвале дају Богу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Огледом порезе ове хвалећи Бога за ваше покорно признање јеванђеља Христова, и за простоту подјеле к њима и к свима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'И да се моле Богу за вас и да чезну за вама за премногу благодат Божју на вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'А хвала Богу на његову неисказаноме дару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'А сам ја Павле молим вас кротости ради и тишине Христове, који сам пред вама понижен према вама, а кад нијесам код вас, слободан сам према вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Молим пак да ми не буде тријебе кад будем код вас, онако слободан бити као што мислим да смијем против некијех који мисле за нас да по тијелу живимо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Јер ако и живимо по тијелу, не боримо се по тијелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Јер оружје нашега војевања није тјелесно, него силно од Бога на раскопавање градова, да кваримо помисли');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'И сваку висину која се подиже на познање Божије, и робимо сваки разум за покорност Христу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'И у приправности имамо освету за сваку непокорност, кад се изврши ваша покорност.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Гледате ли на оно што вам је пред очима? Ако се ко узда да је Христов нека мисли опет у себи да како је он Христов тако смо и ми Христови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Јер ако се што и више похвалим влашћу нашом коју нам даде Господ на поправљање, а не на кварење ваше, нећу се постидјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Али да се не покажем као да вас плашим посланицама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Јер су посланице, вели, тешке и јаке, а кад је тијелом пред нама, слаб је, и ријеч његова не ваља ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Ово нека помисли такови да каки смо у ријечи по посланицама кад нијесмо код вас, таки смо и у дјелу кад смо ту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Јер не смијемо себе мијешати или се поредити с другима који хвале сами себе; али кад сами по себи себе мјере и пореде сами себе са собом, не разумијевају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'А ми се нећемо хвалити преко мјере, него по мјери правила којега нам Бог мјеру раздијели да допремо и до вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Јер се ми далеко не простиремо, као да не досежемо до вас; јер допријесмо и до вас с јеванђељем Христовијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Не хвалећи се преко мјере у туђијем пословима, имајући пак над кад узрасте вјера ваша да ћемо се у вама величати по правилу својему изобилно,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Да у даљнијем странама од вас проповједимо јеванђеље, и да се не похвалимо онијем што је по туђему правилу урађено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'А који се хвали, Господом нека се хвали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Јер онај није ваљан који се сам хвали, него којега Господ хвали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'О да бисте мало потрпљели моје безумље! но и потрпите ме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Јер ревнујем за вас Божијом ревности, јер вас обрекох мужу једноме, да дјевојку чисту изведем пред Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Али се бојим да како као што змија Еву превари лукавством својијем тако и разуми ваши да се не одврате од простоте која је у Христу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Јер ако онај који долази другога Исуса проповиједа којега ми не проповиједасмо, или другога Духа примите којега не примисте, или друго јеванђеље које не примисте, добро бисте потрпљели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Јер мислим да ни у чему нијесам мањи од превеликијех апостола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Јер ако сам и простак у ријечи, али у разуму нијесам. Но у свему смо познати међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Или гријех учиних понижујући себи да се ви повисите? Јер вам забадава Божије јеванђеље проповједих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Од другијех цркава отех узевши плату за служење вама; и дошавши к вама, и бивши у сиротињи, и досадих никоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Јер моју сиротињу попунише браћа која дођоше из Маћедоније, и у свему без досаде вама себе држах и држаћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Као што је истина Христова у мени тако се хвала ова неће узети од мене у Ахајскијем крајевима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Зашто? Што вас не љубим? Бог зна. А што чиним и чинићу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Да отсијечем узрок онима који траже узрок, да би у ономе чим се хвале нашли се као и ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Јер такови лажни апостоли и преварљиви посленици претварају се у апостоле Христове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'И није чудо, јер се сам сотона претвара у анђела свијетла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Није дакле ништа велико ако се и слуге његове претварају као слуге правде, којима ће свршетак бити по дјелима њиховијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Опет велим да нико не помисли да сам ја безуман; ако ли не, а оно барем као безумна примите ме, да се и ја што похвалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'А што говорим не говорим по Господу, него као у безумљу, у овој струци хвале.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Будући да се многи хвале по тијелу, и ја ћу да се хвалим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Јер љубазни примате безумне кад сте сами мудри.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Јер примате ако вас ко натјера да будете слуге, ако вас ко једе, ако ко узме, ако вас ко по образу бије, ако се ко велича.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'На срамоту говорим, јер као да ми ослабисмо. На што је ко слободан (по безумљу говорим), и ја сам слободан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Јесу ли Јевреји? и ја сам; Јесу ли Израиљци? и ја сам? јесу ли семе Авраамово? и ја сам;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Јесу ли слуге Христове? (не говорим по мудрости) ја сам још више. Више сам се трудио, више сам боја поднио, више пута сам био у тамници, много пута сам долазио до страха смртнога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Од Јевреја примио сам пет пута четрдесет мање један ударац;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Трипут сам био шибан, једном су камење бацали на ме, три пута се лађа са мном разбијала, ноћ и дан провео сам у дубини морској.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Много пута сам путовао, био сам у страху на водама, у страху од хајдука, у страху од родбине, у страху од незнабожаца, у страху у градовима, у страху у пустињи, у страху на мору, у страху међу лажном браћом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'У труду и послу, у многом неспавању, у гладовању и жеђи, у многом пошћењу, у зими и голотињи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Осим што је споља, наваљивање људи сваки дан, и брига за све цркве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Ко ослаби, и ја да не ослабим? Ко се саблазни, и ја да се не распалим?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Ако ми се ваља хвалити, својом ћу се слабошћу хвалити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Бог и отац Господа нашега Исуса Христа, који је благословен вавијек, зна да не лажем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'У Дамаску незнабожачки кнез цара Арете чуваше град Дамаск и шћаше да ме ухвати; и кроз прозор спустише ме у котарици преко зида, и избјегох из његовијех руку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Али ми се не помаже хвалити, јер ћу доћи на виђења и откривења Господња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Знам човјека у Христу који прије четрнаест година (или у тијелу не знам; или осим тијела, не знам: Бог зна) би однесен до трећега неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'И знам за таковог човјека (или у тијелу, или осим тијела, не знам: Бог зна)');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'Да би однесен у рај, и чу неисказане ријечи којијех човјеку није слободно говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Тијем ћу се хвалити, а собом се нећу хвалити, већ ако слабостима својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Јер кад бих се и хтио хвалити, не бих био безуман, јер бих истину казао; али штедим да не би ко више помислио за мене него што ме види или чује што од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'И да се не бих понио за премнога откривења, даде ми се жалац у месо, анђео сотонин, да ме ћуша да се не поносим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Зато трипут Господа молих да отступи од мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'И рече ми: доста ти је моја благодат; јер се моја сила у слабости показује сасвијем. Даклем ће се најслађе хвалити својијем слабостима, да се усели у мене сила Христова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Зато сам добре воље у слабостима, у ружењу, у невољама, у прогоњењима, у тугама за Христа: јер кад сам слаб онда сам силан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Постадох безуман хвалећи се: ви ме натјерасте; јер је требало да ме ви хвалите; јер ни у чему нијесам мањи од превеликијех апостола, ако и јесам ништа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Јер знаци апостолови учинише се међу вама у сваком трпљењу, у знацима и чудесима и силама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Јер шта је у чему сте мањи од осталијех цркава, осим само што вам ја сам не досадих? Баците на мене ову кривицу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Ево сам готов трећи пут да вам дођем, и не досађујем вам; јер не тражим што је ваше него вас. Јер дјеца нијесу дужна родитељима имања тећи него родитељи дјеци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'А ја драговољно потрошићу и бићу потрошен за душе ваше, ако и љубим ја вас одвише, а ви мене мање љубите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Али нека буде, ја не досадих вама, него лукав будући добих вас пријеваром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Еда ли вас што закидох преко кога од онијех које слах к вама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Умолих Тита, и с њим послах брата: еда ли вас Тит што закиде? Не ходисмо ли једнијем духом? не једнијем ли стопама?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Мислите ли опет да вам се одговарамо? Пред Богом у Христу говоримо, а све је, љубазни, за ваше поправљање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Јер се бојим да кад по чем дођем нећу вас наћи какове хоћу, и ја ћу се наћи вама какова ме нећете: да како не буду свађе, зависти, срдње, пркоси, опадања, шаптања, надимања, буне:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Да ме опет кад дођем не понизи Бог мој у вас, и не усплачем за многима који су прије сагријешили и нијесу се покајали за нечистоту и курварство и срамоту, што починише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Ово трећи пут идем ка вама; у устима два или три свједока остаће свака ријеч.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Напријед казах и напријед говорим како у вас бивши други пут, и сад не будући код вас пишем онима који су прије сагријешили и свима осталима да ако дођем опет нећу поштедјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Јер тражите да искушате Христа што у мени говори, који међу вама није слаб, него је силан међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Јер ако и распет би по слабости, али је жив по сили Божијој; јер смо и ми слаби у њему, али ћемо бити живи с њим силом Божијом међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Сами себе окушајте јесте ли у вјери, сами себе огледајте. Или не познајете себе да је Исус Христос у вама? већ ако да у чему нијесте ваљани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'А надам се да ћете познати да ми нијесмо неваљани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'А молимо се Богу да ви не чините никаква зла, не да се ми ваљани покажемо, него да ви добро чините, а ми као неваљани да будемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Јер ништа не можемо на истину него за истину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Јер се радујемо кад ми слабимо а ви јачате. А зато се и молимо Богу, за ваше савршенство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Зато, не будући код вас, пишем ово да кад дођем не учиним без штеђења по власти коју ми је Господ дао на поправљање а не на раскопавање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'А даље, браћо, радујте се, савршујте се, утјешавајте се, једнако мислите, мир имајте: и Бог љубави и мира биће с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Поздравите један другога цјеливом светијем. Поздрављају вас сви свети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Благодат Господа нашега Исуса Христа и љубав Бога и оца и заједница светога Духа са свима вама. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Павле апостол, ни од људи, ни кроз човјека, него кроз Исуса Христа и Бога оца, који га васкрсе из мртвијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'И сва браћа која су са мном, црквама Галатијскијем:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Благодат вам и мир од Бога оца и Господа нашега Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Који даде себе за гријехе наше да избави нас од садашњега свијета злога, по вољи Бога и оца нашега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Којему слава вавијек вијека. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Чудим се да се тако одмах одвраћате на друго јеванђеље од онога који вас позва благодаћу Христовом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Које није друго, само што неки сметају вас, и хоће да изврну јеванђеље Христово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Али ако и ми, или анђео с неба јави вам јеванђеље друкчије него што вам јависмо, проклет да буде!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Као што прије рекосмо и сад опет велим: ако вам ко јави јеванђеље друкчије него што примисте, проклет да буде!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Зар ја сад људе наговарам или Бога? Или тражим људима да угађам? Јер кад бих ја још људима угађао, онда не бих био слуга Христов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Али вам дајем на знање, браћо, да оно јеванђеље које сам ја јавио, није по човјеку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Јер га ја не примих од човјека, нити научих, него откривењем Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Јер сте чули моје живљење некад у Јеврејству, да сам одвише гонио цркву Божију и раскопавао је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'И напредовах у Јеврејству већма од многијех врсника својијех у роду своме, и одвише ревновах за отачке своје обичаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'А кад би угодно Богу, који ме изабра од утробе матере моје и призва благодаћу својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'Да јави сина својега у мени, да га јеванђељем објавим међу људима незнабошцима; одмах не питах тијела и крви,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'Нити изиђох у Јерусалим к старијим апостолима од себе него отидох у Арапску, и опет се вратих у Дамаск.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'А послије тога на три године изиђох у Јерусалим да видим Петра, и остадох у њега петнаест дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Али другога од апостола не видјех, осим Јакова брата Господњега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'А што вам пишем ево Бог види да не лажем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'А потом дођох у земље Сирске и Киликијске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'А бијах лицем непознат Христовијем црквама Јудејскима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Него само бијаху чули да онај који нас некад гони сад проповиједа вјеру коју некад раскопаваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'И слављаху Бога за мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'А потом на четрнаест година опет изиђох у Јерусалим с Варнавом, узевши са собом и Тита.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Али изиђох по откривењу, и разговорих се с њима за јеванђеље које проповиједам у незнабошцима, али насамо с онима који се бројаху као најстарији, да узалуд не трчим или не бих трчао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Али ни Тит, који бјеше са мном, и бјеше Грк, не би натјеран да се обреже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'И за лажну браћу која дођоше и привукоше се да уходе слободу нашу коју имамо у Христу Исусу, да нас заробе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Којима се ни сахат не подасмо у покорност, да истина јеванђеља остане међу нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'А за оне који се бројаху да су нешто, какови били да били, ја не марим ништа; јер Бог не гледа ко је ко; јер они који се бројаху као најстарији, мени ништа не додаше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Него насупрот дознавши да је мени повјерено јеванђеље у необрезанима, као Петру у обрезанима');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(Јер онај који помаже Петру у апостолству међу обрезанима онај помаже и мени међу незнабошцима),');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'И познавши благодат која је мени дана, Јаков и Кифа и Јован, који се бројаху да су стубови, дадоше деснице мени и Варнави, и пристадоше да ми проповиједамо у незнабошцима, а они у обрезанима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Само да се опомињемо сиромашнијех, за које сам се и старао тако чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'А кад дође Петар у Антиохију, у очи њему против стадох; јер бјеше зазоран.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Јер прије док не дођоше неки од Јакова, јеђаше с незнабошцима, а кад дођоше, устручаваше се и одвајаше бојећи се онијех који су из обрезања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'И дволичаху с њим и остали Јудејци, тако да и Варнава приста у њихово дволичење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'А кад ја видјех да не иду право к истини јеванђеља, рекох Петру пред свима: кад ти који си Јеврејин, незнабожачки а не Јеврејски живиш, зашто незнабошце нагониш да живе Јеврејски?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Ми који смо рођени Јевреји, а не грјешници из незнабожаца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Па дознавши да се човјек неће оправдати дјелима закона, него само вјером Исуса Христа, и ми вјеровасмо Христа Исуса да се оправдамо вјером Христовом, а не дјелима закона: јер се дјелима закона никакво тијело неће оправдати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Ако ли се ми који тражимо да се оправдамо Христом, нађосмо и сами грјешници, дакле је Христос гријеху слуга? Боже сачувај!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Јер ако опет зидам оно што развалих, показујем се да сам преступник.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Јер ја законом закону умријех да Богу живим; с Христом се разапех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'А ја више не живим, него живи у мени Христос. А што сад живим у тијелу, живим вјером сина Божјега, којему омиљех, и предаде себе за мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Не одбацујем благодати Божије; јер ако правда кроз закон долази, то Христос узалуд умрије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'О неразумни Галати! ко вас је опчинио да се не покоравате истини? Ви, којима пред очима бјеше написан Исус Христос, а сад се међу вама разапе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Ово једно хоћу од вас да дознам, или Духа примисте кроз дјела закона или кроз чувење вјере?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Тако ли сте неразумни? Почевши Духом, сад тијелом свршујете?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Тако ли узалуд пострадасте? Кад би било само узалуд!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Који вам дакле даје Духа и чини чудеса међу вама, чини ли дјелима закона или чувењем вјере?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Као што Авраам вјерова Богу, и прими му се у правду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Познајте дакле да су они синови Авраамови који су од вјере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'А писмо видјевши у напредак да Бог вјером незнабошце правда, напријед објави Аврааму: у теби ће се благословити сви незнабошци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Тако који су од вјере, благословиће се с вјернијем Авраамом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Јер који су год од дјела закона под клетвом су, јер је писано: проклет сваки који не остане у свему што је написано у књизи законској да чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'А да се законом нико не оправдава пред Богом, познато је: јер праведник од вјере живљеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'А закон није од вјере; него човјек који то твори живљеће у томе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Христос је нас искупио од клетве законске поставши за нас клетва, јер је писано: проклет сваки који виси на дрвету:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'Да међу незнабошцима буде благослов Авраамов у Христу Исусу, да обећање Духа примимо кроз вјеру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Браћо, по човјеку говорим, нико човјечијега потврђена завјета не одбацује нити му што домеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'А Аврааму и сјемену његову речена бише обећања. А не вели: и сјеменима, као за многа, него као за једно: и сјемену твојему, које је Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Ово пак велим: завјета, који је од Бога потврђен за Христа, не одбацује закон, који је постао послије четири стотине и тридесет година, да укине обећање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Јер ако је нашљедство од закона, онда већ није од обећања, а Аврааму обећањем дарова Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Шта ће дакле закон? Ради гријеха додаде се докле дође сјеме које му се обећа, и поставили су га анђели руком посредника.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Али посредник није једнога; а Бог је један.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Еда ли је дакле закон противан обећањима Божијим? Боже сачувај! Јер да је дан закон који може оживљети, заиста би од закона била правда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Али писмо затвори све под гријех, да се обећање даде кроз вјеру Исуса Христа онима који вјерују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'А прије доласка вјере бисмо под законом чувани и затворени за вјеру која се хтјела показати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Тако нам закон би чувар до Христа, да се вјером оправдамо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'А кад дође вјера, већ нијесмо под чуваром.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Јер сте ви сви синови Божији вјером Христа Исуса;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Јер који се год у Христа крстисте, у Христа се обукосте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Нема ту Јеврејина ни Грка, нема роба ни господара, нема мушкога рода ни женскога; јер сте ви сви једно у Христу Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'А кад сте ви Христови, онда сте сјеме Авраамово, и по обећању нашљедници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Али велим: док је нашљедник млад ништа није бољи од роба, ако и јест господар од свега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Него је под заповједницима и чуварима тја до рока очина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Тако и ми кад бијасмо млади, бијасмо под стихијама свијета заробљени;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'А кад се наврши вријеме, посла Бог сина својега јединороднога, који је рођен од жене и покорен закону,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Да искупи оне који су под законом, да примимо посинаштво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'И будући да сте синови, посла Бог Духа сина својега у срца ваша, који виче: Ава оче!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Тако већ нијеси роб, него син; а ако си син, и нашљедник си Божиј кроз Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Али тада не знајући Бога, служисте онима који по себи нијесу богови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'А сад познавши Бога, и још познати бивши од Бога, како се враћате опет на слабе и рђаве стихије, којима опет изнова хоћете да служите?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Гледате на дане и мјесеце, и времена и године.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Бојим се за вас да се не будем узалуд трудио око вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Будите као ја што сам; јер сам ја ко ви што сте. Браћо! молим вас, ништа ми не учинисте нажао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'А знате да вам у слабости тијела најприје проповједих јеванђеље;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'И напасти моје, која бијаше тијелу моме, не презресте, ни попљувасте, него ме примисте као анђела Божијега, као Христа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Каково бијаше онда ваше блаженство? Јер вам свједочим да бисте, кад би могуће било, извадили очи своје и дали мени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Тијем ли вам постадох непријатељ истину вам говорећи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Они не ревнују добро за вас него хоће да вас одвоје, да им ревнујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'А добро је ревновати свагда у добру, и не само кад сам ја код вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Дјечице моја, коју опет с муком рађам, докле Христово обличје не постане у вама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Али бих хтио сад да сам код вас, и да измјеним глас свој, јер не могу да се начудим за вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Кажите ми, ви који хоћете под законом да будете, не слушате ли закона?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Јер је писано да Авраам два сина имаде, једнога од робиње, а другога од слободне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Али који бјеше од робиње, по тијелу се роди; а који од слободне, по обећању.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Које значи друго: јер су ово два завјета: један дакле од горе Синајске, која рађа за робовање а то је Агар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Јер Агар значи Синај гора у Арапској, и пореди се са садашњијем Јерусалимом, и служи са дјецом својом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'А горњи Јерусалим слободна је, који је мати свима нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Јер је писано: развесели се, нероткињо која не рађаш; прокини и повичи, ти која не трпиш муке порођаја; јер пуста има много више дјеце неголи она која има мужа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'А ми смо, браћо, по Исаку дјеца обећања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Но како онда онај што се роди по тијелу гоњаше духовнога, тако и сад.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Али шта говори писмо? Истјерај робињу и сина њезина; јер син робињин неће наслиједити са сином слободне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Тако, браћо, нијесмо дјеца робињина него слободне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Стојте дакле у слободи којом нас Христос ослободи, и не дајте се опет у јарам ропства ухватити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Ево ја Павле кажем вам да ако се обрежете Христос вам ништа неће помоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'А опет свједочим свакоме човјеку који се обрезује да је дужан сав закон творити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Изгубисте Христа, ви који хоћете законом да се оправдате, и отпадосте од благодати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Јер ми духом чекамо од вјере над правде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Јер у Христу Исусу нити што помаже обрезање ни необрезање, него вјера, која кроз љубав ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Добро трчасте; ко вам забрани да се не покоравате истини?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'То одвраћање није од онога који вас позва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Мало квасца укисели све тијесто.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Ја се за вас надам у Господу да ништа друго нећете мислити. А који вас смета понијеће гријех, макар ко био.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'А ја, браћо, ако још обрезање проповиједам, зашто ме гоне? Тако се укиде саблазан крстова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'О да би отсјечени били они који вас кваре!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Јер сте ви, браћо, на слободу позвани: само да ваша слобода не буде на жељу тјелесну, него из љубави служите један другоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Јер се сав закон извршује у једној ријечи, то јест: љуби ближњега својега као себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Али ако се међу собом кољете и једете, гледајте да један другога не истријебите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Велим пак: по духу ходите, и жеља тјелеснијех не извршујте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Јер тијело жели против духа, а дух против тијела; а ово се противи једно другоме, да не чините оно шта хоћете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Ако ли вас дух води, нијесте по законом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'А позната су дјела тјелесна, која су прељубочинство, курварство, нечистота, бесрамност,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'Идолопоклонство, чарања, непријатељства, свађе, пакости, срдње, пркоси, распре, саблазни, јереси,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Зависти, убиства, пијанства, ждерања, и остала овакова за која вам напријед казујем као што и казах напријед, да они који такова чине неће наслиједити царства Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'А род је духовни љубав, радост, мир, трпљење, доброта, милост, вјера,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Кротост, уздржање; на то нема закона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'А који су Христови, распеше тијело са сластима и жељама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Ако у духу живимо по духу и да ходимо,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Да не тражимо лажне славе раздражујући један другога, и завидећи један другоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Браћо! ако и упадне човјек у какав гријех, ви духовни исправљајте таковога духом кротости, чувајући себе да и ти не будеш искушан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Носите бремена један другога, и тако ћете испунити закон Христов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Јер ако ко мисли да је што а није ништа, умом вара себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'А сваки да испита своје дјело, и тада ће сам у себи имати славу, а не у другоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Јер ће сваки своје бреме носити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'А који се учи ријечи нека даје дијел од свакога добра ономе који га учи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Не варајте се: Бог се не да ружити; јер шта човјек посије оно ће и пожњети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Јер који сије у тијело своје, од тијела ће пожњети погибао; а који сије у дух, од духа ће пожњети живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'А добро чинити да нам се не досади; јер ћемо у своје вријеме пожњети ако се не уморимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Зато дакле док имамо времена да чинимо добро свакоме, а особити онима који су с нама у вјери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Видите колико вам написах руком својом!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Који хоће да се хвале по тијелу они вас нагоне да се обрезујете, само да не буду гоњени за крст Христов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Јер ни они сами који се обрезују не држе закона, него хоће да се ви обрезујете да се вашијем тијелом хвале.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'А ја Боже сачувај да се чим другијем хвалим осми крстом Господа нашега Исуса Христа, којега ради разапе се мени свијет, и ја свијету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Јер у Христу Исусу нити што помаже обрезање ни необрезање, него нова твар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'И колико их год по овоме правилу живе, на њима биће мир и милост, и на Израиљу Божијему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Више да ми нико не досађује, јер ја ране Господа Исуса на тијелу својему носим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Благодат Господа нашега Исуса Христа са духом вашијем, браћо. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Од Павла, по вољи Божијој апостола Исуса Христа, светима који су у Ефесу, и вјернима у Христу Исусу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Благодат вам и мир од Бога оца нашега и Господа Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Благословен Бог и отац Господа нашега Исуса Христа, који нас је благословио свакијем благословом духовнијем на небесима кроз Христа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Као што нас изабра кроз њега прије постања свијета, да будемо свети и праведни пред њим у љубави,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Одредивши нас напријед кроз Исуса Христа себи на посинаштво, по угодности воље своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'На похвалу славне благодати своје којом нас облагодати у љубазноме,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'У коме имамо избављење крвљу његовом, и опроштење гријеха, по богатству благодати његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Коју је преумножио у нама у свакој премудрости и разуму,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Показавши нам тајну воље своје, по угодности својој коју напријед показа у њему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'За уредбу извршетка времена, да се све састави у Христу што је на небесима и на земљи; у њему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'Кроз којега и нашљедници постасмо, напријед одређени бивши по наредби Бога који све чини по савјету воље своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Да бисмо били на хвалу славе његове, ми који смо се напријед уздали у Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'Кроз којега и ви, чувши ријеч истине, јеванђеље спасенија својега, у којему и вјеровавши запечатисте се светијем духом обећања,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Који је залог нашљедства нашега за избављење течевине на хвалу славе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Зато и ја чувши вашу вјеру у Христа Исуса, и љубав к свима светима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Не престајем захваљивати за вас, и спомињати вас у својијем молитвама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Да Бог Господа нашега Исуса Христа, отац славе, даде вам Духа премудрости и откривења да га познате,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'И бистре очи срца вашега да бисте могли видјети које је над његова звања, и које је богатство славе нашљедства његова у светима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'И каква је изобилна величина силе његове на нама који вјерујемо по чињењу превелике силе његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Коју учини у Христу, кад га подиже из мртвијех и посади себи с десне стране на небесима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Над свијем поглаварствима, и властима, и силама, и господствима, и над свакијем именом што се може назвати, не само на овоме свијету него и на ономе који иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'И све покори под ноге његове, и њега даде за главу цркви, над свима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Која је тијело његово, пунина онога који све испуњава у свему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'И вас који бијасте мртви за преступљења и гријехе своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'У којима некад ходисте по вијеку овога свијета, по кнезу који влада у вјетру, по духу који сад ради у синовима противљења;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'У којима и ми сви живљесмо негда по жељама тијела својега, чинећи вољу тијела и посмисли, и бијасмо рођена дјеца гњева, као и остали;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Али Бог, који је богат у милости, за премногу љубав своју, коју има к нама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'И нас који бијасмо мртви од гријехова оживље с Христом (благодаћу сте спасени),');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'И с њим васкрсе и посади на небесима у Христу Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'Да покаже у вијековима који иду превелико богатство благодати своје добротом на нама у Христу Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Јер сте благодаћу спасени кроз вјеру; и то није од вас, дар је Божиј,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Не од дјела, да се нико не похвали.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Јер смо његов посао, саздани у Христу Исусу за дјела добра, која бог напријед приправи да у њима ходимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Зато се опомињите да ви који сте негда по тијелу незнабошци били и називани необрезање од онијех који су се звали по тијелу обрезање, које се руком радило,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Да бијасте у оно вријеме без Христа, одвојени од друштва Израиљева, и без дијела у завјетима обећања, нада не имајући, и безбожни на свијету:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'А сад у Христу Исусу, ви који сте негда били далеко, близу постадосте крвљу Христовом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Јер је он мир наш, који обоје састави у једно, и развали плот који је растављао, непријатељство, тијелом својијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Закон заповијести наукама укинувши; да из обога начини собом једнога новог човјека, чинећи мир;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'И да помири с Богом обоје у једном тијелу крстом, убивши непријатељство на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'И дошавши проповиједи у јеванђељу мир вама даљнима и онима који су близу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Јер он доведе к оцу обоје у једном духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Тако дакле више нијесте туђи и дошљаци, него живите са светима и домаћи сте Богу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Назидани на темељу апостола и пророка, гдје је камен од угла сам Исус Христос,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'На коме сва грађевина састављена расте за цркву свету у Господу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'На коме ћете се и ви сазидати за стан Божиј у духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Тога сам ради ја Павле сужањ Исуса Христа за вас незнабошце,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Будући да чусте службу благодати Божије која је мени дана међу вама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Да се мени по откривењу каза тајна; као што горе написах укратко,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Одакле можете читајући познати мој разум у тајни Христовој,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Која се у другијем нараштајима не каза синовима човјечијим, како се сад откри светијем његовијем апостолима и пророцима Духом светијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Да незнабошци кроз јеванђеље постану сунашљедници и сутјелесници и заједничари у обећању његовом у Христу Исусу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Којему постадох слуга по дару благодати Божије, која ми је дана по чињењу силе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Мени најмањему од свију светијех даде се ова благодат да објавим међу незнабошцима неисказано богатство Христово,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'И да откријем свима што је служба тајне од постања свијета сакривене у Богу, који је саздао све кроз Исуса Христа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Да се кроз цркву сад обзнани поглаварствима и властима на небу многоразлична премудрост Божија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'По наредби вијекова, коју учини у Христу Исусу Господу нашему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'У коме имамо слободу и приступ у наду вјером његовом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Зато вас молим да се не ослабите због невоља мојијех за вас, које су слава ваша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Тога ради преклањам кољена своја пред оцем Господа нашега Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'По коме се сва чељад и на небесима и на земљи зову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Да вам да силу по богатству славе своје, да се утврдите ДУхом његовијем за унутрашњег човјека,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Да се Христос усели вјером у срца ваша, да будете у љубави укоријењени и утемељени;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Да бисте могли разумјети са свима светима што је ширина и дужина и дубина и висина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'И познати претежнију од разума љубав Христову, да се испуните сваком пунином Божијом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'А ономе који може још изобилније све чинити што иштемо или мислимо, по сили која чини у нама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Ономе слава у цркви по Христу Исусу у све нараштаје ва вијек вијека. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Молим вас дакле ја сужањ у Господу, да се владате као што приликује вашему звању у које сте позвани,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'Са сваком понизношћу и кротошћу, с трпљењем, трпећи један другога у љубави,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Старајући се држати јединство Духа у свези мира;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Једно тијело, један дух, као што сте и позвани у једном наду звања својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Један Господ, једна вјера, једно крштење,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'Један Бог и отац свију, који је над свима, и кроза све, и у свима нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'А свакоме се од нас даде благодат по мјери дара Христова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Зато говори: изишавши на висину заплијенио си плијен, и даде даре људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'А што изиђе, шта је, осим да и сиђе у најдоња мјеста земље?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Који сиђе то је онај који и изиђе више свију небеса да испуни све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'И он је дао једне апостоле, а једне пророке, а једне јеванђелисте, а једне пастире и учитеље,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Да се свети приправе за дјело службе, на сазидање тијела Христова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Докле достигнемо сви у јединство вјере и познање сина Божијега, у човјека савршена, у мјеру раста висине Христове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Да не будемо више мала дјеца, коју љуља и заноси сваки вјетар науке, у лажи човјечијој, путем пријеваре;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Него владајући се по истини у љубави да у свему узрастемо у ономе који је глава, Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Из којега је све тијело састављено и склопљено свакијем зглавком, да једно другоме помаже добро по мјери свакога уда, и чини да расте тијело на поправљање самога себе у љубави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'Ово дакле говорим и свједочим у Господу да више не ходите као што ходе и остали незнабошци у празности ума својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Који имају смисао тамом покривен, и удаљени су од живота Божијега за незнање које је у њима, за окамењење срца својијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Који оставивши поштење предадоше се бесрамности, на чињење сваке нечистоте и лакомства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Али ви тако не познасте Христа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Јер га чусте и у њему се научисте, као што је истина у Исусу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Да одбаците, по првоме живљењу, старога човјека, који се распада у жељама преварљивијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'И да се обновите духом ума својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'И обучете у новога човјека, који је саздан по Богу у правди и у светињи истине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Зато одбаците лаж, и говорите истину сваки са својијем ближњијем; јер смо уди један другоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Гњевите се и не гријешите; сунце да не зађе у гњеву вашему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Нити дајите мјеста ђаволу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Који је крао више да не краде, него још да се труди, чинећи добро рукама својима да има шта давати потребноме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Никаква рђава ријеч да не излази из уста вашијех, него само што је добро за напредовање вјере, да да благодат онима који слушају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'И не ожалошћавајте светога Духа Божијега, којијем сте запечаћени за дан избављења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Свака горчина, и гњев, и љутина, и вика, и хула, да се узме од вас, са сваком пакошћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'А будите један другоме благи, милостиви, праштајући један другоме, као што је и Бог у Христу опростио вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Угледајте се дакле на Бога, као љубазна дјеца,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'И живите у љубави, као што је и Христос љубио нас, и предаде себе за нас у прилог и жртву Богу на слатки мирис.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'А курварство и свака нечистота и лакомство да се и не спомиње међу вама, као што се пристоји светима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Тако и срамотне и луде ријечи, или шале, што се не пристоји; него још захваљивање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Јер ово да знате да ниједан курвар, или нечист, или тврдица (који је идолопоклоник), неће имати дијела у царству Христа и Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Нико да вас не вара празнијем ријечима; јер овијех ради иде гњев Божиј на синове непокорности.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Не бивајте дакле заједничари њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Јер бијасте негда тама, а сад сте видјело у Господу: као дјеца видјела живите;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'Јер је род духовни у свакој доброти и правди и истини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Истражујте што је Богу угодно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'И не пристајте на безродна дјела таме, него још карајте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Јер је срамно и говорити шта они тајно чине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'А све за што се кара, видјело објављује; јер све што се објављује, видјело је;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Зато говори: устани ти који спаваш и васкрсни из мртвијех, и обасјаће те Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Гледајте дакле да уредно живите не као немудри, него као мудри;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Пазите на вријеме, јер су дани зли,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Тога ради не будите неразумни, него познајте што је воља Божија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'И не опијајте се вином, у коме је курварство, него се још испуњавајте духом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Говорећи међу собом у псалмима и појању и пјесмама духовнијем, пјевајући и припијевајући у срцима својијем Господу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Захваљујући за свашто у име Господа нашега Исуса Христа Богу и оцу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Слушајући се међу собом у страху Божијему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Жене! слушајте своје мужеве као Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Јер је муж глава жени као што је и Христос глава цркви, и он је спаситељ тијела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Но као што црква слуша Христа тако и жене своје мужеве у свему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Мужеви! љубите своје жене као што и Христос љуби цркву, и себе предаде за њу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'Да је освети очистивши је купањем воденијем у ријечи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'Да је метне преда се славну цркву, која нема мане ни мрштине, или такога чега, него да буде света и без мане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Тако су дужни мужеви љубити своје жене као своја тјелеса; јер који љуби своју жену, себе самога љуби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Јер нико не омрзну кад на своје тијело, него га храни и грије, као и Господ цркву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Јер смо уди тијела његова, од меса његова, и од костију његовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Тога ради оставиће човјек оца својега и матер, и прилијепиће се к жени својој, и биће двоје једно тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Тајна је ово велика; а ја говорим за Христа и за цркву.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Али и ви сваки да љуби онако своју жену као и себе самога; а жена да се боји својега мужа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Дјецо! слушајте своје родитеље у Господу: јер је ово право.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Поштуј оца својега и матер: ово је прва заповијест с обећањем:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Да ти благо буде, и да живиш дуго на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'И ви оцеви! не раздражујте дјеце своје, него их гајите у науци и у страху Господњему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Слуге! слушајте господаре своје по тијелу, са страхом и дрктањем, у простоти срца својега, као и Христа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Не само пред очима радећи као људима да угађате, него као слуге Христове, творећи вољу Божију од срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Драговољно служите, као Господу а не као људима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Знајући да сваки што учини добро оно ће и примити од Господа, био роб или слободњак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'И ви господари, тако чините њима остављајући пријетње, знајући да је и вама самијем и њима господар на небесима, и он не гледа ко је ко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'А даље, браћо моја, јачајте у Господу и у сили јачине његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Обуците се у све оружје Божије, да бисте се могли одржати против лукавства ђаволскога:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Јер наш рат није с крвљу и с тијелом, него с поглаварима и властима, и с управитељима таме овога свијета, с духовима пакости испод неба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Тога ради узмите све оружје Божије, да бисте се могли бранити у зли дан, и свршивши све одржати се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Станите дакле опасавши бедра своја истином и обукавши се у оклоп правде,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'И обувши ноге у приправу јеванђеља мира;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'А сврх свега узмите штит вјере о који ћете моћи погасити све распаљене стријеле нечастивога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'И кацигу спасенија узмите, и мач духовни који је ријеч Божија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'И сваком молитвом и мољењем молите се Богу духом без престанка, и уз то стражите са свакијем трпљењем и молитвом за све свете,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'И за мене, да ми се да ријеч кад отворим уста своја, да обзнаним са слободом тајну јеванђеља,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'За које сам посланик у оковима, да у њему говорим слободно, као што ми се пристоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'А да и ви знате како сам ја и шта радим, све ће вам казати Тихик, љубазни брат и вјерни слуга у Господу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Којега послах к вама за то исто да знате како смо ми, и да утјеши срца ваша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Мир браћи и љубав с вјером од Бог оца и Господа Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Благодат са свима који љубе Господа нашега Исуса Христа једнако. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Од Павла и Тимотија, слугу Исуса Христа, свима светима у Христу Исусу који су у Филиби, с владикама и ђаконима:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Благодат вам и мир од Бога оца нашега и Господа Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Захваљујем Богу својему кад се год опоменем вас,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Свагда у свакој молитви својој за све вас с радошћу молећи се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Што ви постадосте заједничари у јеванђељу, од првога дана и до данас;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Уздајући се у ово исто да ће онај који је почео добро дјело у вама довршити га тја до дана Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Као што је право да ја ово мислим за све вас, јер вас имам у срцу у оковима својима и у одговору и потврђивању јеванђеља, као све заједничаре са мном у благодати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Јер Бог ми је свједок да вас љубим љубављу Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'И зато се молим Богу да љубав ваша још више и више изобилује у разуму и свакој вољи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Да кушате шта је боље, да будете чисти и без спотицања на дан Христов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Напуњени плодова правде кроз Исуса Христа, на славу и хвалу Божију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Хоћу пак да знате, браћо, да ово што се ради са мном изиђе за напредак јеванђеља,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Тако да се разгласи у свој судници и код свију осталијех да су моји окови за Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'И многа браћа у Господу ослободивши се оковима мојима већма смију говорити ријеч Божију без страха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Истина, једни из зависти и свађе, а једни од добре воље Христа проповиједају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Тако ови упркос Христа објављују нечисто, мислећи да ће нанијети жалост мојијем оковима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'А ови из љубави, знајући да за обрану јеванђеља лежим у тамници.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Шта дакле? Било како му драго, дволичењем или истином, Христос се проповиједа; и зато се радујем, а и радоваћу се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Јер знам да ће ми се ово збити на спасеније вашом молитвом и помоћу Духа Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Као што чекам и надам се да се ни у чему нећу постидјети, него да ће се и сад као свагда са сваком слободом Христос величати у тијелу мојему, било животом или смрћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Јер је мени живот Христос а смрт добитак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'А кад ми живљење у тијелу плод доноси, то не знам шта ћу изабрати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'А обоје ми је мило, имајући жељу отићи и с Христом бити, које би много боље било;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Али остати у тијелу потребније је вас ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'И ово знам јамачно да ћу бити и остати код свију вас на ваш напредак и радост вјере,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Да хвала ваша мноме изобилује у Христу Исусу кад вам опет дођем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Само живите као што се пристоји јеванђељу Христову, да вас видим кад дођем или ако вам не дођем да чујем за вас да стојите у једноме духу и једнодушно борите се за вјеру јеванђеља,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'И ни у чем да се не плашите од противника; које је њима знак погибли а вама спасенија, и то од Бога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Јер се вама дарова Христа ради не само да га вјерујете него и да страдате за њ,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Имајући ону исту борбу какову у мени видјесте и сад чујете за мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Ако има дакле које поучење у Христу, или ако има која утјеха љубави, ако има која заједница духа, ако има које срце жалостиво и милост,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'Испуните моју радост, да једно мислите, једну љубав имате, једнодушни и једномислени:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Ништа не чините успркос или за празну славу; него понизношћу чините један другога већег од себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Не гледајте сваки за своје, него и за другијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Јер ово да се мисли међу вама што је и у Христу Исусу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Који, ако је и био у обличју Божијему, није се отимао да се испореди с Богом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Него је понизио сам себе узевши обличје слуге, поставши као и други људи и на очи нађе се као човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Понизио сам себе поставши послушан до саме смрти, а смрти крстове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Зато и Бог њега повиси, и дарова му име које је веће од свакога имена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Да се у име Исусово поклони свако кољено онијех који су на небу и на земљи и под земљом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'И сваки језик да призна да је Господ Исус Христос на славу Бога оца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Тако, љубазни моји, као што ме свагда слушасте, не само кад сам код вас, него и сад много већма кад нијесам код вас, градите спасеније своје са страхом и дрктањем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Јер је Бог што чини у вама да хоћете и учините као што му је угодно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Све чините без вике и премишљања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'Да будете прави и цијели, дјеца Божија без мане усред рода неваљалога и покваренога, у којему свијетлите као видјела на свијету,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Придржавајући ријеч живота, на моју хвалу за дан Христов, да ми не буде узалуд трчање и труд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Но ако и жртвован будем на жртву и службу вјере ваше, радујем се, и радујем се с вама свима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Тако и ви радујте се и будите са мном радосни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'А надам се у Господа Исуса да ћу скоро послати к вама Тимотија, да се и ја развеселим разабравши како сте ви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Јер ниједнога немам једнаке мисли са собом који се управо брине за вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Јер сви траже што је њихово, а не што је Христа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'А његово поштење познајете, јер као дијете оцу са мном је послужио у јеванђељу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Њега дакле надам се да ћу послати одмах како разберем што је за мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'А надам се у Господа да ћу и сам скоро доћи к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Али нађох за потребно да пошљем к вама брата Епафродита, својега помагача и другара у војевању, а вашега посланика и слугу моје потребе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Јер жељаше од срца вас све да види, и жаљаше што сте чули да је боловао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Јер бјеше болестан до смрти; но Бог помилова га, не само њега него и мене, да ми не дође жалост на жалост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Зато га послах скорије, да се обрадујете кад га опет видите, и мени да олакша мало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Примите га дакле у Господу са сваком радости, и такове поштујте;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Јер за дјело Христово дође до саме смрти, не маривши за свој живот да накнади у служби мојој што вас немам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'А даље, браћо моја, радујте се у Господу. Јер све једно да вам пишем мени није досадно, а вама је потребно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Чувајте се од паса, чувајте се од злијех посленика, чувајте се од сијечења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Јер ми смо обрезање који духом Богу служимо и хвалимо се Христом Исусом, а не уздамо се у тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Премда бих се и ја могао уздати у тијело. Ако ко други мисли да се може уздати у тијело, ја још већма,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Који сам обрезан осми дан, од рода Израиљева, кољена Венијаминова, Јеврејин од Јевреја, по закону фарисеј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'По ревности гоних цркву Божију, по правди законској бих без мане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Но што ми бјеше добитак оно примих за штету Христа ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Јер све држим за штету према преважноме познању Христа Исуса Господа својега, којега ради све оставих, и држим све да су трице, само да Христа добијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'И да се нађем у њему, не имајући своје правде која је од закона, него која је од вјере Исуса Христа, правду која је од Бога у вјери;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Да познам њега и силу васкрсенија његова и заједницу његовијех мука, да будем налик на смрт његову,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Да бих, како достигао у васкрсеније мртвијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Не као да већ достигох или се већ саврших, него тјерам не бих ли достигао као што ме достиже Христос Исус.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Браћо! ја још не мислим да сам достигао; једно пак велим: што је остраг заборављам, а за онијем што је напријед сежем се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'И трчим к биљези, к дару горњега звања Божијега у Христу Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Који смо год дакле савршени овако да мислимо; ако ли што друго мислите, и ово ће вам Бог открити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Али шта достигосмо у ономе једнако да мислимо, и по ономе правилу да живимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Угледајте се на мене, браћо, и гледајте на оне који тако живе као што нас имате за углед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Јер многи ходе, за које вам много пута говорих, а сад и плачући говорим, непријатељи крста Христова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Којима је свршетак погибао, којима је Бог трбух, и слава у сраму њихову, који земаљски мисле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Јер је наше живљење на небесима, откуда и спаситеља очекујемо Господа својега Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Који ће преобразити наше понижено тијело да буде једнако тијелу славе његове, по сили да може све себи покорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Зато, браћо моја љубазна и пожељна, радости и вијенче мој! тако стојте у Господу, љубазни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Еводију молим, и Синтихију молим да једно мисле у Господу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Да, молим и тебе, друже прави, помажи њима који се у јеванђељу трудише са мном, и Клементом, и с осталима помагачима мојима, којијех су имена у књизи живота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Радујте се свагда у Господу, и опет велим: радујте се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Кротост ваша да буде позната свијем људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Господ је близу. Не брините се ни за што него у свему молитвом и мољењем са захваљивањем да се јављају Богу искања ваша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'И мир Божиј, који превазилази сваки ум, да сачува срца ваша и мисли ваше у Господу Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'А даље, браћо моја, што је год истинито, што је год поштено, што је год праведно, што је год пречисто, што је год прељубазно, што је год славно, и још ако има која добродјетељ, и ако има која похвала, то мислите,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Што и научисте, и примисте, и чусте, и видјесте у мени, оно чините, и Бог мира биће с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Обрадовах се пак врло у Господу што се опет опоменусте старати се за мене; као што се и старасте, али се незгоднијем временом задржасте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Не говорим због недостатка, јер се ја навикох бити довољан онијем у чему сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Знам се и понизити, знам и изобиловати; у свему и свакојако навикох, и сит бити, и гладовати, и изобиловати, и немати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Све могу у Исусу Христу који ми моћ даје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Али добро учинисте што се примисте моје невоље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'А знате и ви, Филибљани, да од почетка јеванђеља, кад изиђох из Маћедоније, ниједна ми црква не приста у ствар давања и узимања осим вас једнијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Јер и у Солун и једном и другом посласте ми у потребу моју.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Не као да тражим дара, него тражим плода који се множи на корист вашу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'А ја сам примио све и имам изобила. Испунио сам се примивши од Епафродита што сте ми послали, слатки мирис, прилог пријатан, угодан Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'А Бог мој да испуни сваку потребу вашу по богатству својему у слави, у Христу Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'А Богу и оцу нашему слава ва вијек вијека. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Поздравите свакога светог у Христу Исусу. Поздрављају вас браћа што су са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Поздрављају вас сви свети, а особито који су из дома Ћесарева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Благодат Господа нашега Исуса Христа са свима вама. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Од Павла, по вољи Божијој апостола Исуса Христа и брата Тимотија,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'Светима који су у Колосима и вјерној браћи у Христу Исусу: благодат вам и мир од Бога оца нашега и Господа Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Захваљујемо Богу и оцу Господа својега Исуса Христа, молећи се свагда за вас,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Чувши вјеру вашу у Христа Исуса, и љубав коју имате к свима светима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'За над остављени вама на небесима, за који напријед чусте у ријечи истине јеванђеља,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Које је у вама, као и у свему свијету, и плодно је и расте, као и у вама, од онога дана како чусте и разумјесте благодат Божију у истини,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Као што и дознасте од Епафраса, љубазнога нашег другара у служењу, који је за вас вјерни слуга Христов,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Који нам и јави вашу љубав у духу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Тога ради и ми од онога дана како чусмо не престајемо за вас молити се Богу и искати да се испуните познањем воље његове у свакој премудрости и разуму духовноме,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Да живите пристојно Богу на свако угађање и у свакоме добром дјелу да будете плодни, и да растете у познању Божијему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'Јачајући сваком снагом по сили славе његове, и у сваком трпљењу и дугом подношењу с радошћу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Захваљујући Богу и оцу, који нас призва у дијел нашљедства светијех у видјелу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Који нас избави од власти тамне, и премјести нас у царство сина љубави своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'У коме имамо избављење крвљу његовом и опроштење гријеха;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Који је обличје Бога што се не види, који је рођен прије сваке твари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Јер кроз њега би саздано све што је на небу и што је на земљи, што се види и што се не види, били пријестоли или господства или поглаварства, или власти: све се кроза њ и за њ сазда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'И он је прије свега, и све је у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'И он је глава тијелу цркве, који је почетак и прворођени из мртвијех, да буде он у свему први;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Јер би воља очина да се у њ усели сва пунина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'И кроза њ да примири све са собом, умиривши крвљу крста његова, кроз њ све, било на земљи или на небу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'И вас који сте некад били одлучени и непријатељи кроз помисли у злијем дјелима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'А сад вас примири у тијелу меса његова смрћу његовом, да вас свете и без мане и без кривице изведе преда се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Ако само останете у вјери утемељени и тврди, и непокретни од нада јеванђеља, које чусте, које је проповиједано свој твари под небом, којему ја Павле постадох слуга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Сад се радујем у својему страдању за вас, и довршујем недостатак невоља Христовијех на тијелу својему за тијело његово које је црква,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Којој ја постадох слуга по наредби Божијој која ми је дана међу вама да испуним ријеч Божију,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'Тајну која је била сакривена од постања свијета и нараштаја, а сад се јави светима његовијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Којима Бог науми показати како је богата слава тајне ове међу незнабошцима, које је Христос у вама, над славе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Којега ми проповиједамо свјетујући свакога човјека, и учећи свакој премудрости, да покажемо свакога човјека савршена у Христу Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'Зашто се и трудим и борим по његовој моћи која у мени силно чини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Хоћу дакле да ви знате колику борбу имам за вас и за оне што су у Лаодикији и у Јерапољу, и за све који не видјеше лица мојега у тијелу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'Да се утјеше срца њихова, и да се стегну у љубави, и у свакоме богатству пунога разума, на познање тајне Бога и оца и Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'У којој је све благо премудрости и разума сакривено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'А ово говорим, да вас нико не превари слаткијем ријечима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Јер ако тијелом и нијесам код вас, али сам духом с вама, радујући се и видећи ваш ред и тврђу ваше вјере у Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Како дакле примисте Христа Исуса Господа онако живите у њему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Укоријењени и назидани у њему и утврђени вјером као што научисте, изобилујући у њој захвалношћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Браћо! чувајте се да вас ко не зароби филозофијом и празном пријеваром, по казивању човјечијему, по науци свијета, а не по Христу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Јер у њему живи свака пунина Божанства тјелесно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'И да будете испуњени у њему који је глава свакоме поглаварству и власти;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'У коме и обрезани бисте обрезањем нерукотворенијем, одбацивши тијело гријеха меснијех обрезањем Христовијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Закопавши се с њим крштењем, у којему с њим и устасте вјером силе Бога који га васкрсну из мртвијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'И вас који сте били мртви у гријесима и у необрезању тијела својега, оживљео је с њим, поклонивши нам све гријехе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'И избрисавши писмо уредбе која бјеше против нас, и то узевши са сриједе прикова га на крсту;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'И свукавши поглаварства и власти изведе их на углед слободно, и побиједи их на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Да вас дакле нико не осуђује за јело или за пиће, или за какав празник, или за младине, или за суботе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Које је све било сјен од онога што шћаше да дође, и тијело је Христово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Нико да вас не вара по својој вољи изабраном понизношћу и службом анђела, истражујући и што не видје, и узалуд надимајући се умом тијела својега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'А не држећи се главе, из које је све тијело с помоћу зглавака и свеза састављено, и расте за раст Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Ако дакле умријесте с Христом стихијама свијета, зашто се као живећи у свијету препирете:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Не дохвати се, не окуси, не опипај; које је све на погибао ономе који чини,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'По заповијестима и наукама људскима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Које је само по ријечи премудрост самовољно избране службе и понизности и нештеђења тијела, не за част каку, за пуњење тијела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Ако дакле васкрснусте с Христом, тражите оно што је горе гдје Христос сједи с десне стране Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Мислите о ономе што је горе а не што је на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Јер умријесте, и ваш је живот сакривен с Христом у Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'А кад се јави Христос, живот ваш, онда ћете се и ви с њиме јавити у слави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Поморите дакле уде своје који су на земљи: курварство, нечистоту, сласт, злу жељу и лакомство, које је идолопоклонство;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'За које иде гњев Божиј на синове противљења;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'У којима и ви негда хођасте кад живљасте међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'А сад одбаците и ви то све: гњев, љутину, пакост, хуљење, срамотне ријечи из уста својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Не лажите један на другога; свуците старога човјека с дјелима његовијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'И обуците новога, које се обнавља за познање по обличју онога који га је саздао:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Гдје нема Грка ни Јеврејина, обрезања ни необрезања, дивљака ни Скита, роба ни слободњака, него све и у свему Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Обуците се дакле као избрани Божији, свети и љубазни, у срдачну милост, доброту, понизност, кротост, и трпљење,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Сносећи један другога, и опраштајући један другоме ако има ко тужбу на кога: као што је и Христос вама опростио тако и ви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'А сврх свега тога обуците се у љубав, која је свеза савршенства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'И мир Божиј да влада у срцима вашима, на који сте и позвани у једном тијелу, и захвални будите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Ријеч Христова се богато усели међу вас, у свакој премудрости учећи и свјетујући сами себе са псалмима и појањем и пјесмама духовнијем, у благодати пјевајући у срцима својима Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'И све што год чините ријечју или дјелом, све чините у име Господа Исуса Христа хвалећи Бога и оца кроза њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Жене! слушајте своје мужеве као што треба у Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Мужеви! љубите жене своје и не срдите се на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Дјецо! слушајте родитеље своје у свачему; јер је ово угодно Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Оцеви! не раздражујте дјеце своје, да не губе воље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Слуге! слушајте у свему своје тјелесне господаре, не само пред очима радећи као да људима угађате, него у простоти срца, бојећи се Бога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'И све шта год чините, од срца чините као Господу а не као људима:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Знајући да ћете од Господа примити плату нашљедства; јер Господу Христу служите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'А који скриви примиће што је скривио: и нема гледања ко је ко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Господари! правду и једнакост чините слугама знајући да и ви имате господара на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Да вам се не досади молитва; и стражите у њој са захваљивањем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Молећи се и за нас уједно да нам Бог отвори врата ријечи, да проповиједамо тајну Христову, за коју сам и свезан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Да је јавим као што ми треба говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Мудро живите према онима који су напољу, пазећи на вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Ријеч ваша да бива свагда у благодати, сољу зачињена, да знате како вам свакоме треба одговарати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'За мене казаће вам све Тихик љубазни брат и вјерни слуга и другар у Господу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Којега послах к вама за то исто да разбере ко сте ви, и да утјеши срца ваша,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'С Онисимом вјернијем и љубазнијем братом нашијем, који је од вас. Они ће вам све казати како је овдје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Поздравља вас Аристарх, који је са мном у сужањству, и Марко нећак Варнавин, за којега примисте заповијести (ако дође к вама, примите га);');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'И Исус прозвани Јуст, који су из обрезања. Ово су једнини моји помагачи у царству Божијему који ми бише утјеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Поздравља вас Епафрас, који је од вас, слуга Исуса Христа; он се једнако труди за вас у молитвама да будете савршени и испуњени сваком вољом Божијом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Јер ја свједочим за њега да има велику ревност и бригу за вас и за оне који су у Лаодикији и у Јерапољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Поздравља вас Лука љекар љубазни, и Димас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Поздравите браћу у Лаодикији, и Нимфана и домашњу цркву његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'И кад се ова посланица прочита код вас, учините да се прочита и у Лаодикијској цркви, и ону што је писана у Лаодикију да и ви прочитате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'И кажите Архипу: гледај на службу коју си примио у Господу да је довршиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Поздрав мојом руком Павловом. Опомињите се мојијех окова. Благодат са свима вама. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Од Павла и Силвана и Тимотија, цркви Солунској у Богу оцу и Господу Исусу Христу: благодат вам и мир од Бога оца нашега и Господа Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Захваљујемо Богу свагда за све вас спомињући вас у молитвама својима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'И спомињући без престанка ваше дјело вјере, и труд љубави, и трпљење нада Господа нашега Исуса Христа, пред Богом и оцем нашијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Знајући, браћо љубазна, од Бога избор ваш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Јер јеванђеље наше не би к вама само у ријечи него и у сили и у Духу светоме, и у великом признању, као што знате какови бисмо међу вама вас ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'И ви се угледасте на нас и на Господа примивши ријеч у великој невољи с радошћу Духа светога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Тако да постадосте углед свима који вјерују у Маћедонији и у Ахаји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Јер се од вас прочу ријеч Господња не само у Маћедонији и Ахаји, него и у свако мјесто изиђе вјера ваша у Бога тако да нам није тријебе што говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Јер они обзнањују за вас какав улазак имасмо к вама, и како се обратисте Богу од идола, да служите Богу живу и истину,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'И да чекате сина његова с небеса којега васкрсе из мртвијех, Исуса, који нас избавља од гњева који ће доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Јер сами знате, браћо, улазак наш к вама да не би узалуд;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Него пострадавши прије и осрамоћени бивши, као што знате, у Филиби, ослободисмо се у Богу својему казивати вама јеванђеље Божије с великом борбом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Јер утјеха наше није од пријеваре, ни од нечистоте, ни у лукавству;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Него како нас окуша Бог да смо вјерни да примимо јеванђеље, тако говоримо, не као људима угађајући него Богу који куша срца наша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Јер нигда из ласкања не говорисмо к вама, као што знате, нити из узрока лакомства: Бог је свједок;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Нити тражећи од људи славе, ни од вас, ни од другијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Могли смо вам бити на досаду, као Христови апостоли; али бисмо кротки међу вама, као што дојилица његује своју дјецу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Тако смо вас радо имали да смо готови били дати вам не само јеванђеље Божије, него и душе своје, јер сте нам омиљели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Јер памтите, браћо, труд наш и посао: јер дан и ноћ радећи да не досадимо ниједноме од вас, проповиједасмо вам јеванђеље Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Ви сте свједоци и Бог како свети и праведни и без кривице бисмо вама који вјерујете,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Као што знате да свакога вас као отац дјецу своју');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'Молисмо и утјешавасмо, и свједочисмо вам да живите као што се пристоји Богу, који вас је призвао у своје царство и славу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Тога ради и ми захваљујемо Богу без престанка што ви примивши од нас ријеч чувења Божијега примисте не као ријеч човјечију, него (као што заиста јест) ријеч Божију, која и чини у вама који вјерујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Јер ви, браћо, прођосте као цркве Божије које су у Јудеји у Христу Исусу; јер тако и ви пострадасте од својега рода као и они од Јевреја,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Који убише и Господа Исуса и пророке његове, и који нас истјераше, и Богу не угодише, и који се свијем људима противе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'И забрањују нам казивати незнабошцима да се спасу; да испуне гријехе своје свагда; али напошљетку дође гњев на њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'А ми, браћо, осиротјевши за вама неко вријеме лицем а не срцем, већма хићасмо да видимо лице ваше с великом жељом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Зато шћадијасмо да дођемо к вама, ја Павле једном и другом, и забрани нам сотона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Јер ко је наш над или радост, или вијенац славе? Нијесте ли и ви пред Господом нашијем Исусом Христом о његову доласку?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Јер сте ви наша слава и радост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Зато не могући више трпљети наумисмо сами остати у Атини,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'И посласмо Тимотија, брата својега и слугу Божијега, и помагача својега у јеванђељу Христову, да вас утврди и утјеши у вјери вашој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'Да се нико не смете у овијем невољама; јер сами знате да смо на то одређени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Јер кад бијасмо код вас казасмо вам напријед да ћемо падати у невоље, које и би, и знате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Тога ради и је не могући више трпљети послах да познам вјеру вашу, да вас како не искуша кушач, и да узалуд не буде труд наш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'А сад кад дође Тимотије к нама од вас и јави нам вашу вјеру и љубав, и да имате добар спомен о нама свагда, желећи нас видјети, као и ми вас,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Зато се утјешисмо, браћо, вама у свакој жалости и невољи својој вашом вјером;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Јер смо ми сад живи кад ви стојите у Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Јер какву хвалу можемо дати Богу за вас, за сваку радост, којом се радујемо вас ради пред Богом својијем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Дан и ноћ молимо се Богу преизобилно да видимо лице ваше, и да испунимо недостатак вјере ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'А сам Бог и отац наш и Господ наш Исус Христос да управи пут наш к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'А вас Господ да умножи, и да имате изобилну љубав један к другоме и к свима, као и ми к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Да би се утврдила срца ваша без кривице у светињи пред Богом и оцем нашијем, за долазак Господа нашега Исуса Христа са свима светима његовијем. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Даље, браћо, молимо вас и свјетујемо у Христу Исусу, као што примисте од нас, како вам треба живљети и угађати Богу, као што живите, да бивате све изобилнији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Јер знате какве вам заповијести дадосмо кроз Господа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Јер је ово воља Божија, светост ваша, да се чувате од курварства,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'И сваки од вас да зна држати свој суд у светињи и у части,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'А не у сласти жеља, као и незнабошци, који не познају Бога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'И да не преступате и закидате у ствари брата својега; јер ће Господ покајати све то, као што вам и прије казасмо и посвједочисмо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Јер Бог нас не дозва на нечистоту, него у светост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Који дакле одбацује, не одбацује човјека него Бога, који је дао светога Духа својега у вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'А за братољубље не требујете да вам се пише, јер сте сами од Бога научени да се љубите међу собом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Јер то чините са свом браћом по цијелој Маћедонији. Али вас молимо, браћо, да још изобилније чините,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'И да се љубазно старате да сте мирни, и да гледате свој посао, и да радите својијем рукама, као што вам заповједисмо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'Да се владате поштено према онима што су напољу, и да од њих ништа не потребујете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Нећу вам пак затајити, браћо, за оне који су умрли, да не жалите као и остали који немају нада;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Јер ако вјерујемо да Исус умрије и васкрсе, тако ће Бог и оне који су умрли у Исусу довести с њим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Јер вам ово казујемо ријечју Господњом да ми који живимо и останемо за долазак Господњи, нећемо претећи онијех који су помрли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Јер ће сам Господ са заповијешћу, са гласом арханђеловијем, и с трубом Божијом сићи с неба; и мртви у Христу васкрснуће најприје;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'А потом ми живи који смо остали, заједно с њима бићемо узети у облаке на сусрет Господу на небо, и тако ћемо свагда с Господом бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Тако утјешавајте један другога овијем ријечима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'А за часе и времена, браћо, није вам тријебе писати;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Јер сами знате јамачно да ће дан Господњи доћи као лупеж по ноћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Јер кад реку: мир је, и нема се шта бојати, онда ће изненада напасти на њих погибао као бол на трудну жену, и неће утећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Али ви, браћо, нијесте у тами да вас дан као лупеж застане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Јер сте ви сви синови видјела и синови дана: нијесмо ноћи нити таме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Тако дакле да не спавамо као и остали, него да пазимо и да будемо тријезни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Јер који спавају, у ноћи спавају, и који се опијају, у ноћи се опијају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Али ми који смо синови дана да будемо тријезни и обучени у оклоп вјере и љубави, и с кацигом нада спасенија;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Јер нас Бог не постави за гњев, него да добијемо спасеније кроз Господа својега Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'Који умрије за нас да ми, стражили или спавали, заједно с њим живимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Тога ради утјешавајте један другога, и поправљајте сваки ближњега, као што и чините.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Молимо вас пак, браћо, припознајте оне који се труде међу вама, и настојнике своје у Господу и учитеље своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'И имајте их у изобилној љубави за дјело њихово. Будите мирни међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Молимо вас пак, браћо, поучавајте неуредне, утјешавајте малодушне, браните слабе, сносите свакога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Гледајте да нико не враћа коме зла за зло;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Него свагда идите за добром, и међу собом, према свима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Радујте се свагда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Молите се Богу без престанка. На свачему захваљујте; јер је ово воља Божија у Христу Исусу од вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Духа не гасите. Пророштва не презирите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'А све кушајући добро држите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Уклањајте се од свакога зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'А сам Бог мира да посвети вас цијеле у свачему;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'И цијел ваш дух и душа и тијело да се сачува без кривице за долазак Господа нашега Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Вјеран је онај који вас дозва, који ће и учинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Браћо! молите се Богу за нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Поздравите браћу сву цијеливом светијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Заклињем вас Господом да прочитате ову посланицу пред свом браћом светом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Благодат Господа нашега Исуса Христа с вама. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Од Павла и Силвана и Тимотија цркви Солунској у Богу оцу нашему и Господу Исусу Христу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Благодат вам и мир од Бога оца нашега и Господа Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Дужи смо свагда захваљивати Богу за вас, браћо, као што треба; јер расте врло вјера ваша, и множи се љубав свакога вас међу вама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Тако да се ми сами хвалимо вама црквама Божијима, вашијем трпљењем и вјером у свима вашијем гоњењима и невољама које подносите,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'За знак праведнога суда Божијега да се удостојите царства Божијега, за које и страдате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Јер је праведно у Бога да врати муке онима који вас муче;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'А вама које муче покој с нама кад се покаже Господ Исус с неба с анђелима силе своје');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'У огњу пламеноме, који ће дати освету онима који не познају Бога и не слушају јеванђеља Господа нашега Исуса Христа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Који ће примити муку, погибао вјечну од лица Господњега и од славе његове,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Кад дође да се прослави у светима својима, и диван да буде у свима који га вјероваше; јер се прими свједочанство наше међу вама у онај дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Зато се и молимо свагда за вас да вас удостоји Бог наш звања, и испуни сваку радост доброте и дјело вјере у сили;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Да се прослави име Господа нашега Исуса Христа у вама и ви у њему, по благодати Бога нашега и Господа Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Али вас молимо, браћо, за долазак Господа нашега Исуса Христа, и за наш састанак у њему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'Да се не дате ласно покренути од ума, нити да се плашите, ни духом ни ријечју, ни посланицом, као да је од нас послана, да је већ настао дан Христов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Да вас нико не превари никакијем начином; јер неће доћи док не дође најприје отпад, и не покаже се човјек безакоња, син погибли,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'Који се противи и подиже више свега што се зове Бог или се поштује, тако да ће он сјести у цркви Божијој као Бог показујући себе да је Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Не памтите ли да сам вам ово казивао још кад сам код вас био?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'И сад знате што задржава да се не јави у своје вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Јер се већ ради тајна безакоња, само док се уклони онај који сад задржава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Па ће се онда јавити безаконик, којега ће Господ Исус убити духом уста својијех, и искоријенити свјетлошћу доласка својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Којега је долазак по чињењу сотонину са сваком силом, и знацима и лажнијем чудесима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'И са сваком пријеваром неправде међу онима који гину: јер љубави истине не примише, да би се спасли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'И зато ће им Бог послати силу пријеваре, да вјерују лажи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'Да приме суд сви који не вјероваше истини, него вољеше неправду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'А ми смо дужни свагда захваљивати Богу за вас, браћо љубазна Господу! што вас је Бог од почетка изабрао за спасеније у светињи Духа и вјери истине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'У које вас дозва јеванђељем нашијем, да добијете славу Господа нашега Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Тако дакле, браћо, стојте и држите уредбе којима се научисте или ријечју или из посланице наше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'А сам Господ наш Исус Христос, и Бог и отац наш, којему омиљесмо и даде нам утјеху вјечну и над добри у благодати,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'Да утјеши срца ваша и да вас утврди у свакој ријечи и дјелу доброме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Даље, браћо, молите се Богу за нас да ријеч Господња трчи, и да се слави као и међу вама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'И да се избавимо од беспутнијех и злијех људи: јер вјера није свију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'А Господ је вјеран, који ће вас утврдити и сачувати ода зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'А уздамо се у Господа за вас да оно што вам заповиједамо и чините и чинићете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'А Господ да управи срца ваша на љубав Божију и на трпљење Христово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Заповједамо вам пак, браћо, у име Господа нашега Исуса Христа, да се одвојите од свакога брата који живи неуредно, а не по уредби коју примише од нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Јер сами знате како треба да се угледате на нас, јер не живљесмо неуредно међу вама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Нити забадава хљеб једосмо у кога, него у труду и у послу, дан и ноћ радећи, да не будемо на досаду никоме од вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Не као да немамо власти, него да себе дамо вама за углед, да будете као и ми.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Јер кад бијасмо у вас, ово вам заповиједасмо да ако ко неће да ради да и не једе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Јер чујемо да неки неуредно живе међу вама, ништа не радећи, него окрајче и мијешају се у туђе послове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Таковима заповиједамо и молимо их у Господу нашему Исусу Христу да мирно радећи свој хљеб једу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'А вама, браћо, да не дотужи добро чинити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'А ако ко не послуша ријечи наше, онога посланицом назначите, и не мијешајте се с њима, да се посрами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Али га не држите као непријатеља, него га свјетујте као брата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'А сам Господ мира да вам да мир свагда у сваком догађају. Господ са свима вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Поздрав мојом руком Павловом, које је знак у свакој посланици, овако пишем:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Благодат Господа нашега Исуса Христа са свима вама. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Од Павла, апостола Исуса Христа, по заповијести Бога спаса нашега и Господа Исуса Христа, нада нашега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Тимотију, правоме сину у вјери, благодат, милост, мир од Бога оца нашега и Христа Исуса Господа нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Као што те молих да останеш у Ефесу, кад иђах у Маћедонију, да заповједиш некима да не уче друкчије,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'Нити да гледају на лажи и на тефтере од племена којима нема краја, и који прије чине препирања неголи Божиј напредак у вјери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'А намјера је заповијести љубав од чиста срца и добре савјести и вјере нелицемјерне;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'У којима неки погријешивши сврнуше у празне говоре,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'И хтјели би да буду законици, а не разумију ни шта говоре, ни шта утврђују.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'А знамо да је закон добар ако га ко држи као што треба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Знајући ово да праведнику закон није постављен, него безаконицима и непокорнима и безбожницима и грјешницима, неправеднима и поганима, крвницима оца и матере, крвницима људскима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Курварима, мужеложницима, људокрадицама, лажљивцима, клетвопреступницима, и ако што има противно здравој науци,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'По јеванђељу славе блаженога Бога, које је мени повјерено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'И захваљујем Христу Исусу Господу нашему који ми даје моћ, што ме за вјерна прими и постави ме у службу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Који сам прије био хулник и гонитељ и силеџија; али бих помилован, јер не знајући учиних у невјерству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Али се још већма умножи благодат Господа нашега Исуса Христа с вјером и љубави у Христу Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Истинита је ријеч и свакога примања достојна да Христос Исус дође на свијет да спасе грјешнике, од којијех сам први ја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Али тога ради ја бих помилован да на мени првоме покаже све трпљење Исус Христос за углед онима који му хоће вјеровати за живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'А цару вјечноме, нераспадљивоме, који се не види, јединоме премудроме Богу част и слава вавијек вијека. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Ову пак заповијест предајем ти, сине Тимотије, по пређашњијем пророштвима за тебе: да ратујеш у у њима добар рат,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Имајући вјеру и добру савјест, коју неки одбацивши отпадоше од вјере;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Међу којима су Именеј и Александар које предадох сотони да се науче не хулити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Молим дакле прије свега да се чине искања, молитве, мољења, захваљивања за све људе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'За цареве, и за све који су у власти, да тихи и мирни живот поживимо у свакој побожности и поштењу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Јер је ово добро и пријатно пред спаситељем нашијем Богом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Који хоће да се сви људи спасу, и да дођу у познање истине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Јер је један Бог, и један посредник Бога и људи, човјек Христос Исус,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Који себе даде у откуп за све, за свједочанство у своје вријеме,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'За које сам постављен проповједник и апостол (истину говорим у Христу, не лажем), учитељ незнабожаца, у вјери и истини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Хоћу дакле да молитве чине људи на свакоме мјесту, подижући свете руке без гњева и премишљања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Тако и жене у пристојном одијелу, са стидом и поштењем да украшују себе, не плетеницама, ни златом, или бисером, или хаљинама скупоцјенима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Него добријем дјелима као што се пристоји женама које се обећавају побожности.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Жена на миру да се учи са сваком покорношћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Али жени не допуштам да учи нити да влада мужем, него да буде мирна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Јер је Адам најприје саздан па онда Ева;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'И Адам се не превари, а жена преваривши се постаде преступница;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Али ће се спасти рађањем дјеце, ако остане у вјери и љубави и у светињи с поштењем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Истинита је ријеч: ако ко владичанства жели добру ствар жели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Али владика треба да је без мане, једне жене муж, тријезан, паметан, поштен, гостољубив, вриједан да учи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Не пијаница, не бојац, не лаком, него кротак, миран, не среброљубац;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Који својијем домом добро управља, који има послушну дјецу са сваким поштењем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'А ако ко не умије својијем домом управљати, како ће се моћи старати за цркву Божију?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Не новокрштен, да се не би надуо, и упао у суд ђавољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'А ваља да има и добро свједочанство од онијех који су напољу, да не би упао у срамоту и у замку ђавољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Тако и ђакони треба да буду поштени, не двојезични, не који много вина пију, не лакоми на добитак поган,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Који имају тајну вјере у чистој савјести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'А и ови да се кушају најприје, па онда да служе, ако су без мане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Тако и жене треба да су поштене, не које опадају, тријезне, вјерне у свему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Ђакони да бивају јединијех жена мужеви, који добро управљају дјецом и својијем домовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Јер који добро служе они добивају себи добар поступ, и велику слободу у вјери Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Ово ти пишем надајући се да ћу скоро доћи к теби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'Ако ли се забавим, да знаш како треба живљети у дому Божијему, који је црква Бога живога, ступ и тврђа истине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'И, као што је признато, велика је тајна побожности: Бог се јави у тијелу, оправда се у Духу, показа се анђелима, проповједи се незнабошцима, вјерова се на свијету, узнесе се у слави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'А Дух разговијетно говори да ће у пошљедња времена отступити неки од вјере слушајући лажне духове и науке ђаволске,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'У лицемјерју лажа, жигосанијех на својој савјести,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Који забрањују женити се, и заповиједају уздржавати се од јела која Бог створи за јело са захвалношћу вјернима и онима који познаше истину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Јер је свако створење Божије добро и ништа није на одмет кад се прима са захвалношћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Јер се освећује ријечју Божијом и молитвом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Ово све казујући браћи бићеш добар слуга Исуса Христа, одгајен ријечима вјере и добром науком коју си примио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'А поганијех и бапскијех гаталица клони се; а обучавај се у побожности.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Јер тјелесно обучавање мало је корисно, а побожност је корисна за свашто, имајући обећање живота садашњега и онога који иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Ово је истинита ријеч и достојна свакога примања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Јер се зато и трудимо и бивамо срамотни, јер се уздамо у Бога жива, који је спаситељ свима људима, а особито вјернима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Ово заповиједај и учи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Нико да не постане немарљив за твоју младост; него буди углед вјернима у ријечи, у живљењу, у љубави, у духу, у вјери, у чистоти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Докле дођем пази на читање, утјешавање и учење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Не пусти у немар дар у себи који ти је дан по пророштву метнувши старјешине руке на тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'У овом се поучавај, у овом стој, да се напредак твој покаже у свему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Пази на себе и на науку, и стој у томе; јер ово чинећи спашћеш и самога себе и оне који те слушају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Старца не карај, него му говори као оцу; момчадма као браћи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'Старицама као матерама; младима као сестрама, са сваком чистотом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Удовице поштуј, које су праве удовице.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Ако ли која удовица има дјецу или унучад, да се уче најприје свој дом поштовати, и зајам враћати родитељима; јер је ово угодно пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'А права удовица и усамљена узда се у Бога, и живи у молитвама и у мољењу дан и ноћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'А која живи у сладостима, жива је умрла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'И ово заповиједај, да буду без мане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Ако ли ко за своје а особито за домаће не промишља, одрекао се вјере, и гори је од незнабошца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'А удовица да се не прима млађа од шездесет година, и која је била једноме мужу жена;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'И која има свједочанство у добријем дјелима, ако је дјецу одгајила, ако је гостољубива била, ако је светима ноге прала, ако је невољнима помагала, ако је ишла за свакијем добријем дјелом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'А младијех удовица прођи се; јер кад побјесне против Христа, хоће да се удају,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'И имају гријех што прву вјеру одбацише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'А к томе и беспослене уче се скитати по кућама, не само пак беспослене, него и језичне и свезнале, па говоре што не треба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Хоћу дакле да се младе удовице удају, дјецу рађају, кућу куће, а никаква узрока да не дају противнику за хуљење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Јер се ево неке окренуше за сотоном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Ако који вјерни или вјерна има удовице, нека се стара за њих, и да не досађују цркви да оне које су праве удовице може задовољити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'А свештеницима који се добро старају да се даје двогуба част, а особито онима који се труде у ријечи и у науци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Јер писмо говори: волу који врше не завезуј уста, и: радин је достојан своје плате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'На свештеника не примај тужбе, осим кад имају два или три свједока.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'А који гријеше покарај их пред свима, да и други имају страх.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Заклињем те пред Богом и Господом Исусом Христом и избранима његовијем анђелима да ово држиш без лицемјерја, не чинећи ништа по хатеру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Руку одмах не мећи ни на кога, нити пристај у туђе гријехе. Држи себе чиста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Више не пиј воде, него пиј по мало вина, желуца ради својега и честијех својијех болести.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'А некијех су људи гријеси познати који напријед воде на суд, а некијех иду за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Тако су и добра дјела позната, и која су друкчија не могу се сакрити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Робови који су год под јармом да показују сваку част својијем господарима, да се не хули на име Божије и на науку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'А који имају крштене господаре, да не постају немарљиви за њих што су браћа, него још боље да служе, јер су вјерни и љубазни, заједничари у благодати. Ово учи и свјетуј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Ако ли ко друкчије учи, и не пристаје на здраве ријечи Господа нашега Исуса Христа и на науку побожну,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'Наду се не знајући ништа, него болујући од запиткивања и празнијех препирања, ода шта постаје завист, свађа, хуљење, зле мисли,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Залудна препирања онаковијех људи који имају ум изопачен и немају истине, који мисле да је побожност трговина. Клони се таковијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Али јест велика трговина побожност са задовољством.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Јер ништа не донесосмо на овај свијет, дакле не можемо ништа ни однијети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'А кад имамо храну и одјећу, овијем да будемо довољни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'А који хоће да се обогате они упадају у напасти и замке, и у многе луде шкодљиве жеље, које потапају човјека у пропаст и погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Јер је коријен свију зала среброљубље којему неки предавши се зађоше од вјере и на себе навукоше муке велике.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'А ти, о човјече Божиј! бјегај од овога, а иди за правдом, побожности, вјером, љубави, трпљењем, кротости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Бори се у доброј борби вјере, мучи се за вјечни живот на који си и позван, и признао си добро признање пред многијем свједоцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Заповиједам ти пред Богом који све оживљује, и Христом Исусом који свједочи за владања Понтија Пилата добро признање,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Да држиш заповијест чисту и незазорну до доласка Господа нашега Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Који ће у своје вријеме показати блажени и једини силни цар над царевима и господар над господарима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Који сам има бесмртност, и живи у свјетлости којој се не може приступити, којега нико од људи није видио, нити може видјети, којему част и држава вјечна. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Богатима на овоме свијету заповиједај да се не поносе нити уздају у богатство пропадљиво, него у Бога живога, који нам све даје изобилно за ужитак;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Нека добро чине, нека се богате у добријем дјелима, нека буду подашни, заједнични,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Сабирајући себи темељ добар за унапредак, да приме живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'О Тимотије! сачувај што ти је предано, клони се поганијех, празнијех разговора и препирања лажно названога разума,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Којијем се неки хвалећи отпадоше од вјере. Благодат с тобом. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Од Павла, апостола Исуса Христа по вољи Божијој за обећање живота у Исусу Христу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Тимотију, љубазноме сину, благодат, милост, мир од Бога оца и Христа Исуса Господа нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Захваљујем Богу којему служим од прародитеља чистом савјести, што без престанка имам спомен за тебе у молитвама својијем дан и ноћ,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Желећи да те видим, опомињући се суза твојијех, да се радости испуним;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Опомињући се нелицемјерне у теби вјере која се усели најприје у бабу твоју Лоиду и у матер твоју Евникију; а увјерен сам да је и у теби;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Заради којега узрока напомињем ти да погријеваш дар Божиј који је у теби како сам метнуо руке своје на тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Јер нам Бог не даде духа страха, него силе и љубави и чистоте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Не постиди се дакле свједочанства Господа нашега Исуса Христа, ни мене сужња његова; него пострадај с јеванђељем Христовијем по сили Бога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Који нас спасе и призва звањем светијем, не по дјелима нашима, него по својој наредби и благодати, која нам је дана у Христу Исусу прије времена вјечнијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'А сад се показа у доласку спаситеља нашега Исуса Христа, који раскопа смрт, и обасја живот и нераспадљивост јеванђељем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'За које сам ја постављен апостол и учитељ незнабожаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Заради којега узрока и ово страдам; али се не стидим, јер знам коме вјеровах, и увјерен сам да је кадар аманет мој сачувати за дан онај.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Имај у памети образ здравијех ријечи које си чуо од мене, у вјери и љубави Христа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Добри аманет сачувај Духом светијем који живи у нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Знаш ово да се одвратише од мене сви у Азији, међу којима и Фигел и Ермоген.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'А Господ да да милост Онисифорову дому; јер ме много пута утјеши, и окова мојијех не постидје се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Него дошавши у Рим потражи ме још с већијем старањем и нађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Да да њему Господ да нађе милост у Господа у дан онај. И у Ефесу колико ми послужи, ти знаш добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Ти дакле, сине мој, јачај у благодати Исуса Христа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'И што си чуо од мене пред многијем свједоцима, оно предај вјернијем људима, који ће бити вриједни и друге научити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Ти дакле трпи зло као добар војник Исуса Христа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Јер се никакав војник не заплеће у трговине овога свијета да угоди војводи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Ако и војује, не добија вијенца ако право не војује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Радин који се труди најприје треба да окуси од рода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Разумиј што говорим; а Господ да ти да разум у свему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Опомињи се Господа Исуса Христа који уста из мртвијех, од сјемена Давидова, по јеванђељу мојему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'У којему трпим зло до самијех окова као злочинац; али се ријеч Божија не веже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Зато трпим све избранијех ради да и они добију спасеније у Христу Исусу са славом вјечном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Истинита је ријеч: ако с њим умријесмо, то ћемо с њим и оживљети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Ако трпимо, с њим ћемо и царовати. Ако се одречемо, и он ће се нас одрећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Ако не вјерујемо, он остаје вјеран; јер се сам себе не може одрећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Ово напомињи, и посвједочи пред Господом да се не препиру, које ништа не помаже, него смета оне који слушају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Постарај се да се покажеш поштен пред Богом, као радин који се нема шта стидјети, и право управља ријечју истине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'А поганијех празнијех разговора клони се; јер највише помажу у безбожности,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'И ријеч њихова као живина точи: међу којима је Именеј и Филит,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'Који у истини погријешише говорећи да је васкрсеније већ било; и сметају вјеру некијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Тврдо дакле стоји темељ Божиј имајући овај печат: позна Господ своје; и: да отступи од неправде сваки који спомиње име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'А у великоме дому нијесу суди само златни и сребрни, него и дрвени и земљани: и једни за част, а једни за срамоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Ако дакле ко очисти себе од овога, биће суд за част, освећен, и потребан домаћину, приправљен за свако добро дјело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Бјежи од жеља младости, а држи се правде, вјере, љубави, мира, са свима који призивљу Господа од чистога срца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'А лудијех и празнијех запиткивања клони се знајући да рађају свађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'А слуга Господњи не треба да се свађа, него да буде кротак к свима, поучљив, који неправду може подносити,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'И с кротошћу поучавати оне који се противе: еда би им како Бог дао покајање за познање истине,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'И да се ископају из замке ђавола, који их је уловио живе за своју вољу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Али ово знај да ће у пошљедње дане настати времена тешка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Јер ће људи постати саможиви, среброљупци, хвалише, поносити, хулници, непокорни родитељима, неблагодарни, неправедни, нељубавни,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'Непримирљиви, опадачи, неуздржници, бијесни, недоброљубиви,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Издајници, нагли, надувени, који више маре за сласти него за Бога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Који имају обличје побожности, а силе су се њезине одрекли. И овијех се клони.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Јер су од овијех они који се завлаче по кућама, и робе женице које су натоварене гријесима и воде их различне жеље,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Које се свагда уче, и никад не могу да дођу к познању истине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Као што се Јаније и Јамврије противише Мојсију, тако се и ови противе истини, људи изопаченога ума, невјешти у вјери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Али неће дуго напредовати; јер ће њихово безумље постати јавно пред свима, као и онијех што поста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'А ти си се угледао на моју науку, живљење, намјеру, вјеру, сношење, љубав, трпљење,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'Протјеривања, страдања, какова ми се догодише у Антиохији, и у Иконији, и у Листри, какова протјеривања поднесох, и од свију ме избави Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'А и сви који побожно хоће да живе у Христу Исусу, биће гоњени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'А зли људи и варалице напредоваће на горе, варајући и варајући се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Али ти стој у томе што си научио и што ти је повјерено, знајући од кога си се научио,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'И будући да из малена умијеш света писма, која те могу умудрити на спасеније у Христа Исуса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Све је писмо од Бога дано, и корисно за учење, за карање, за поправљање, за поучавање у правди,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'Да буде савршен човјек Божиј, за свако добро дјело приправљен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Заклињем те дакле пред Богом и Господом нашијем Исусом Христом, који ће судити живима и мртвима, доласком његовијем и царством његовијем:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Проповиједај ријеч, настој у добро вријеме и у невријеме, покарај, запријети, умоли са свакијем сношењем и учењем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Јер ће доћи вријеме кад здраве науке неће слушати, него ће по својијем жељама накупити себи учитеље, као што их уши сврбе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'И одвратиће уши од истине, и окренуће се ка гаталицама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'А ти буди тријезан у свачему, трпи зло, учини дјело јеванђелиста, службу своју сврши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Јер ја се већ жртвујем, и вријеме мојега одласка наста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Добар рат ратовах, трку сврших, вјеру одржах.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Даље дакле мени је приправљен вијенац правде, који ће ми дати Господ у дан онај, праведни судија; али не само мени, него свима који се радују његову доласку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Постарај се да дођеш брзо к мени;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Јер ме Димас остави, омиљевши му садашњи свијет, и отиде у Солун; Крискент у Галатију, Тит у Далмацију; Лука је сам код мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Марка узми и доведи га са собом; јер ми је добар за службу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'А Тихика послао сам у Ефес.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Кад дођеш донеси ми кабаницу што сам оставио у Троади код Карпа, и књиге, а особито кожне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Александар ковач много ми зла учини. Да му Господ плати по дјелу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Чувај се и ти од њега; јер се врло противи нашијем ријечима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'У први мој одговор нико не оста са мном, него ме сви оставише. Да им се не прими!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Али Господ би са мном и даде ми помоћ да се кроза ме сврши проповиједање, и да чују сви незнабошци; и избавих се од уста лавовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'И Господ ће ме избавити од свакога зла дјела, и сачуваће ме за царство своје небеско; којему слава ва вијек вијека. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Поздрави Прискилу и Акилу, и Онисифоров дом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Ераст оста у Коринту. А Трофима оставих у Милету болесна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Постарај се да дођеш прије зиме. Поздравља те Еувул, и Пуд, и Лин, и Клаудија, и браћа сва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Господ Исус Христос са духом твојијем. Благодат с вама. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Од Павла, слуге Божијега, а апостола Исуса Христа по вјери избранијех Божијих, и по познању истине побожности,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'За над вјечнога живота, који обећа нелажни Бог прије времена вјечнијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'А јави у времена своја ријеч своју проповиједањем, које је мени повјерено по заповијести спаситеља нашега Бога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Титу, правоме сину по вјери нас обојице, благодат, милост, мир од Бога оца и Господа Исуса Христа, спаса нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Зато те оставих у Криту да поправиш што је недовршено, и да поставиш по свијем градовима свештенике, као што ти ја заповједих,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Ако је ко без мане, једне жене муж, и има вјерну дјецу, коју не коре за курварство или за непокорност.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Јер владика треба да је без мане, као Божиј пристав; не који себи угађа, не гњевљив, не пијаница, не бојац, не лаком на погани добитак;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Него гостољубив, благ, поштен, праведан, свет, чист;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Који се држи вјерне ријечи по науци, да буде кадар и свјетовати са здравом науком, и покарати оне који се противе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Јер има много непослушнијех, празноговорљивијех, и умом преваренијех, а особито који су из обрезања,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Којима треба уста затворити; који цијеле куће изопачују учећи што не треба, поганога добитка ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'А рече неко од њих, њихов пророк: Крићани свагда лажљиви, зли звјерови, беспослени трбуси.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Сведочанство је ово истинито; заради тога узрока карај их без штеђења, да буду здрави у вјери,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'Не слушајући Јеврејскијех гаталица ни заповијести људи који се одвраћају од истине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Чистима је све чисто; а поганима и невјернима ништа није чисто, него је опогањен њихов и ум и савјест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Говоре да познају Бога, а дјелима га се одричу; јер су мрски и непослушни, и ни за какво добро дјело ваљани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'А ти говори што пристоји здравој науци:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Старцима да буду тријезни, поштени, чисти, здрави у вјери, у љубави, у трпљењу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Старицама такођер да живе као што се пристоји светима, да не буду опадљиве, да се не предају врло вину, да уче добру,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Да уче младе да љубе мужеве, да љубе дјецу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'Да буду поштене, чисте, добре кућанице, благе, покорне својијем мужевима, да се не хули на ријеч Божију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Тако и младиће свјетуј да буду поштени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'А у свему сам себе подаји за углед добријех дјела, у науци цијелост, поштење,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Ријеч здраву, незазорну: да се посрами онај који се противи, не имајући ништа зло говорити за нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Слуге да слушају своје господаре, да буду угодни у свачему, да не одговарају,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Да не краду, него у свачему да показују добру вјеру, да науку спаситеља нашега Бога украшују у свачему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Јер се показа благодат Божија која спасава све људе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Учећи нас да се одречемо безбожности и жеља овога свијета, и да поштено и праведно и побожно поживимо на овоме свијету,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Чекајући блажена нада и јављања славе великога Бога и спаса нашега Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'Који је дао себе за нас да нас избави од свакога безакоња, и да очисти себи народ избрани који чезне за добријем дјелима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Ово говори, и свјетуј, и карај са сваком заповијешћу да те нико не презире.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Опомињи их да буду покорни и послушни господарима и заповједницима, и готови на свако добро дјело;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Ни на кога да не хуле, да се не свађају, него да буду мирни, сваку кротост да показују свијем људима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Јер и ми бијасмо негда луди, и непокорни, и преварени, служећи различнијем жељама и сластима, у пакости и зависти живећи, мрски будући и мрзећи један на другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'А кад се показа благодат и човјекољубље спаса нашега Бога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Не за дјела праведна која ми учинисмо, него по својој милости спасе нас бањом прерођења и обновљењем Духа светога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Којега изли на нас обилно кроз Исуса Христа спаситеља нашега,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'Да се оправдамо благодаћу његовом, и да будемо нашљедници живота вјечнога по наду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Сине Тите! истинита је ријеч, и у овоме хоћу да утврђујеш, да се они који вјероваше Богу труде и старају за добро дјело: ово је корисно људима и добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'А лудијех запиткивања и тефтера од племена, и свађа и препирања о закону клони се; јер је то некорисно и празно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Човјека јеретика по првоме и другом свјетовању клони се,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Знајући да се такови изопачио, и гријеши, и сам је себе осудио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Кад пошљем к теби Артему или Тихика, постарај се да дођеш к мени у Никопољ, јер сам намислио да ондје зимујем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Зину законика и Апола лијепо опреми да имају све што им треба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Али и наши нека се уче напредовати у добријем дјелима, ако гдје буде од потребе да не буду без рода.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Поздрављају те сви који су са мном. Поздрави све који нас љубе у вјери. Благодат са свима вама. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Од Павла, сужња Исуса Христа, и Тимотија брата, Филимону љубазноме и помагачу нашему,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'И Апфији, сестри љубазној, и Архипу, нашему другару у војевању, и домашњој твојој цркви:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Благодат вам и мир од Бога оца нашега, и Господа Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Захваљујем Богу својему спомињући те свагда у молитвама својима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Чувши љубав твоју и вјеру коју имаш ка Господу Исусу и к свима светима:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Да твоја вјера, коју имамо заједно, буде силна у познању свакога добра, које имате у Христу Исусу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Јер имам велику радост и утјеху ради љубави твоје, што срца светијех починуше кроза те, брате!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Тога ради ако и имам велику слободу у Христу да ти заповиједам што је потребно,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Али опет молим љубави ради, ја који сам такови као старац Павле, а сад сужањ Исуса Христа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Молимо те за својега сина Онисима, којега родих у оковима својима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Који је теби негда био непотребан, а сад је и теби и мени врло потребан, којега послах теби натраг;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'А ти га, то јест, моје срце прими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Ја га шћадијах да задржим код себе, да ми мјесто тебе послужи у оковима јеванђеља;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Али без твоје воље не хтједох ништа чинити, да не би твоје добро било као за невољу, него од добре воље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Јер може бити да се за то растаде с тобом на неко вријеме да га добијеш вјечно,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Не више као роба, него више од роба, брата љубазнога, а особито мени, акамоли теби, и по тијелу и у Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Ако дакле држиш мене за својега другара, прими њега као мене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Ако ли ти у чему скриви, или је дужан, то на мене запиши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Ја Павле написах руком својом, ја ћу платити: да ти не речем да си и сам себе мени дужан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Да брате! да имам корист од тебе у Господу, развесели срце моје у Господу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Уздајући се у твоју послушност написах ти знајући да ћеш још више учинити него што говорим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'А уз то уготови ми и конак; јер се надам да ћу за ваше молитве бити дарован вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Поздравља те Епафрас који је са мном сужањ у Христу Исусу, Марко, Аристарх, Димас, Лука, помагачи моји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Благодат Господа нашега Исуса Христа са духом вашијем. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Бог који је негда много пута и различнијем начином говорио оцевима преко пророка, говори и нама у пошљедак дана овијех преко сина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'Којега постави нашљедника свему, кроз којега и свијет створи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Који будући сјајност славе и обличје бића његова, и носећи све у ријечи силе своје, учинивши собом очишћење гријеха нашијех, сједе с десне стране пријестола величине на висини,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'И толико бољи поста од анђела колико преславније име од њихова доби.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Јер коме од анђела рече кад: син мој ти си, ја те данас родих? И опет: ја ћу му бити отац, и он ће ми бити син.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'И опет уводећи првороднога у свијет говори: и да му се поклоне сви анђели Божији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Тако и анђелима говори: који чини анђеле своје духове, и слуге своје пламен огњени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'А сину: пријестол је твој, Боже, ва вијек вијека; палица је правде палица царства твога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Омиљела ти је правда, и омрзао си на безакоње: тога ради помаза те, Боже, Бог твој уљем радости већма од другова твојијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'И опет: ти си, Господе, у почетку основао земљу, и небеса су дјела руку твојијех:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Она ће проћи, а ти остајеш: и сва ће остарјети као хаљина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'И савићеш их као хаљину, и измијениће се: а ти си онај исти, и твојијех година неће нестати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'А коме од анђела рече кад: сједи мени с десне стране док положим непријатеље твоје подножје ногама твојима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Нијесу ли сви службени духови који су послани на службу онима који ће наслиједити спасеније?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Тога ради ваља нам већма пазити на ријечи које слушамо, да како не отпаднемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Јер ако је оно што је говорено преко анђела утврђено, и сваки преступак и оглушак праведну плату примио:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Како ћемо побјећи на маривши за толико спасеније? које поче Господ проповиједати, и они који су чули потврдише међу нама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Кад и Бог посвједочи и знацима и чудесима и различнијем силама, и Духа светога раздијељивањем по својој вољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Јер Бог не покори анђелима васинога свијета, који иде и о коме говоримо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Али неко посвједочи негдје говорећи: шта је човјек да га се опоменеш, или син човјечиј да га обиђеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Умалио си га малијем нечим од анђела, славом и части вјенчао си га, и поставио си га над дјелима руку својијех:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Све си покорио под ноге његове. А кад му покори све, ништа не остави њему непокорено; али сад још не видимо да му је све покорено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'А умаљенога малијем чим од анђела видимо Исуса, који је за смрт што поднесе вјенчан славом и части, да би по благодати Божијој за све окусио смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Јер приликоваше њему за којега је све и кроз којега је све, који доведе многе синове у славу, да доврши поглавара спасенија њихова страдањем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Јер и онај који освећује, и они који се освећују, сви су од једнога; заради тога узрока не стиди се назвати их браћом');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Говорећи: објавићу име твоје браћи својој, и посред цркве запјеваћу те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'И опет: ја ћу се у њега уздати. И опет: ево ја и дјеца моја коју ми је дао Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Будући пак да дјеца имају тијело и крв, тако и он узе дијел у томе, да смрћу сатре онога који има државу смрти, то јест ђавола;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'И да избави оне који год од страха смрти у свему животу бише робови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Јер се заиста не прима анђела, него се прима сјемена Авраамова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Зато бјеше дужан у свему да буде као браћа, да буде милостив и вјеран поглавар свештенички пред Богом, да очисти гријехе народне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Јер у чему пострада и искушан би у ономе може помоћи и онима који се искушавају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Зато, браћо света, заједничари звања небескога, познајте посланика и владику, којега ми признајемо, Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Који је вјеран ономе који га створи, као и Мојсије у свему дому његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Јер овај поста толико достојан веће части од Мојсија, колико већу од дома част има онај који га је начинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Јер сваки дом треба неко да начини; а ко је све створио оно је Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'И Мојсије дакле бјеше вјеран у свему дому његову, као слуга, за свједочанство онога што је требало да се говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Али је Христос као син у дому својему: којега смо дом ми, ако слободу и славу нада до краја тврдо одржимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Зато, као што говори Дух свети: данас ако глас његов чујете,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Не будите дрвенастијех срца, као кад се прогњевисте у дане напасти у пустињи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Гдје ме искушаше оцеви ваши, искушаше ме, и гледаше дјела моја четрдесет година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Тога ради расрдих се на тај род, и рекох: једнако се мету у срцима, али они не познаше путова мојијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Зато се заклех у гњеву својему да неће ући у покој мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Гледајте, браћо, да не буде кад у коме од вас зло срце невјерства да отступи од Бога живога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Него се утјешавајте сваки дан, докле се данас говори, да који од вас не одрвени од пријеваре грјеховне;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Јер постадосмо заједничари Христу, само ако како смо почели у њему бити до краја тврдо одржимо;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Докле се говори: данас, ако глас његов чујете, не будите дрвенастијех срца, као кад се прогњевисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Јер неки чувши прогњевише се, али не сви који изиђоше из Мисира с Мојсијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'А на које мрзи четрдесет година? Није ли на оне који сагријешише, који оставише кости у пустињи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'А којима се закле да неће ући у покој његов, него онима који не хтјеше да вјерују?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'И видимо да не могоше ући за невјерство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Да се бојимо дакле да како док је још остављено обећање да се улази у покој његов, не одоцни који од вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Јер је нама објављено као и онима; али онима не помаже чувена ријеч, јер не вјероваше они који чуше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Јер ми који вјеровасмо улазимо у покој, као што рече: зато се заклех у гњеву својему да неће ући у покој мој, ако су дјела и била готова од постања свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Јер негдје рече за седми дан овако: и почину Бог у дан седми од свију дјела својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'И на овом мјесту опет: неће ући у покој мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Будући пак да неки имају да уђу у њега, и они којима је најприје јављено не уђоше за непослушање;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Опет одреди један дан, данас, говорећи у Давиду по толиком времену, као што се прије каза: данас ако глас његов чујете, не будите дрвенастијех срца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Јер да је Исус оне довео у покој, не би за други дан говорио по том.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Даклем је остављено још почивање народу Божијему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Јер који уђе у покој његов, и он почива од дјела својијех, као и Бог од својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Да се постарамо дакле ући у тај покој, да не упадне ко у ону исту гатку невјерства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Јер је жива ријеч Божија, и јака, и оштрија од свакога мача оштра с обје стране, и пролази тја до растављања и душе и духа, и зглавака и мозга, и суди мислима и помислима срдачнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'И нема твари непознате пред њим, него је све голо и откривено пред очима онога којему говоримо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Имајући дакле великога поглавара свештеничкога, који је прошао небеса, Исуса сина Божијега, да се држимо признања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Јер немамо поглавара свештеничкога који не може пострадати с нашијем слабостима, него који је у свачему искушан, као и ми осим гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Да приступимо дакле слободно к пријестолу благодати, да примимо милост и нађемо благодат за вријеме кад нам затреба помоћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Јер сваки поглавар свештенички који се из људи узима, за људе се поставља на службу к Богу, да приноси даре и жртве за гријехе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Који може пострадати с онима који не знаду и залазе; јер је и он под слабошћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'И зато је дужан како за народне тако и за своје гријехе приносити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'И нико сам себи не даје части, него који је позван од Бога, као и Арон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Тако и Христос не прослави сам себе да буде поглавар свештенички, него онај који му рече: ти си мој син, ја те данас родих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Као што и на другоме мјесту говори: ти си свештеник вавијек по реду Мелхиседекову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Он у дане тијела својега мољења и молитве к ономе који га може избавити од смрти с виком великом и са сузама приношаше, и би утјешен по својој побожности.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Иако и бијаше син Божиј, али од онога што пострада научи се послушању.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'И савршивши се, постаде свима који га послушаше узрок спасенија вјечнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'И би наречен од Бога поглавар свештенички по реду Мелхиседекову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'За којега бисмо вам имали много говорити што је тешко исказати; јер сте постали слаби на слушању.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Јер ви који би ваљало да сте учитељи по годинама, опет требујете да учите које су прва слова ријечи Божије; и постадосте да требате млијека, а не јаке хране.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Јер који се год храни млијеком, не разумије ријечи правде, јер је дијете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'А савршенијех је тврда храна, који имају осјећања дугијем учењем обучена за разликовање и добра и зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Зато да оставимо почетак Христове науке и да се дамо на савршенство: да не постављамо опет темеља покајања од мртвијех дјела, и вјере у Бога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Науке крштења, и метања руку, и васкрсенија мртвијех, и суда вјечнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'И ово ћемо учинити ако Бог допусти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Јер није могуће оне који су једном просвијетљени, окусили дара небескога, постали заједничари Духа светога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'И окусили добре ријечи Божије, и силе онога свијета, и отпали,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'Опет обновити на покајање, јер сами себи наново распињу и руже сина Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Јер земља која пије дажд што често на њу пада, и која рађа поврће добро онима који је раде, прима благослов од Бога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'А која износи трње и чичак, непотребна је и клетве близу, која се најпослије сажеже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Али од вас, љубазни, надамо се бољему и што се држи спасенија, ако и говоримо тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Јер Бог није неправедан да заборави дјело ваше и труд љубави коју показасте у име његово, послуживши светима и служећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Али желимо да сваки од вас покаже то исто старање да се над одржи тврдо до самога краја;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Да не будете љениви, него да се угледате на оне који вјером и трпљењем добијају обећања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Јер кад Бог Аврааму обећа, не имајући ничим већијем да се закуне, закле се собом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Говорећи: заиста благосиљајући благословићу те, и умножавајући умножићу те.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'И тако трпећи дуго, доби обећање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Јер се људи већијем куну, и свакој њиховој свађи свршетак је заклетва за потврђење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Зато и Бог кад шћаше нашљедницима обећања обилније да покаже тврђу савјета својега, учини посредника клетву:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Да би у двјема непоколебљивијем стварима, у којима Богу није могуће слагати, имали јаку утјеху ми који смо прибјегли да се ухватимо за над који нам је дан,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Који имамо као тврд и поуздан ленгер душе, који улази и за најдаље завјесе,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Гдје Исус уђе напријед за нас, поставши поглавар свештенички довијека по реду Мелхиседекову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Јер овај Мелхиседек бјеше цар Салимски, свештеник Бога највишега, који срете Авраама кад се враћаше с боја царева, и благослови га;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Којему и Авраам даде десетак од свега. Прво дакле значи цар правде, потом и цар Салимски, то јест цар мира:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Без оца, без матере, без рода, не имајући ни почетка данима, ни свршетка животу, а испоређен са сином Божијим, и остаје свештеник довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Али погледајте колики је овај коме је и Авраам патријарх дао десетак од плијена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Истина, и они од синова Левијевијех који примише свештенство, имају заповијест да узимају по закону десетак од народа, то јест од браће своје, ако су и изишли из бедара Авраамовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Али онај који се не броји од њихова рода, узе десетак од Авраама, и благослови онога који има обећање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Али без свакога изговора мање благослови веће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'И тако овдје узимају десетак људи који умиру, а онамо онај за којега се посвједочи да живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'И, да овако речем, Левије који узе десетак, дао је десетак кроз Авраама:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Јер бијаше још у бедрима очинима кад га срете Мелхиседек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Ако је дакле савршенство постало кроз Левитско свештенство (јер је народ под њим закон примио), кака је још потреба била говорити да ће други свештеник постати по реду Мелхиседекову а не по реду Аронову?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Јер кад се промијени свештенство, мора се и закон промијенити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Јер за кога се ово говори он је од другога кољена, од којега нико не приступи к олтару.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Јер је познато да Господ наш од кољена Јудина изађе, за које кољено Мојсије не говори ништа о свештенству.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'И још је више познато да ће по реду Мелхиседекову други свештеник постати,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'Који није постао по закону тјелесне заповијести него по сили живота вјечнога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Јер свједочи: ти си свештеник вавијек по реду Мелхиседекову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Тако се укида пређашња заповијест, што би слаба и залудна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Јер закон није ништа савршио; а постави бољи над, кроз који се приближујемо к Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'И још не без заклетве:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'Јер они без заклетве посташе свештеници; а овај са заклетвом кроз онога који му говори: закле се Господ и неће се раскајати: ти си свештеник вавијек по реду Мелхиседекову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Толико бољега завјета поста Исус јамац.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'И они многи бише свештеници, јер им смрт не даде да остану.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'А овај, будући да остаје вавијек, има вјечно свештенство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Зато и може вавијек спасти оне који кроза њ долазе к Богу, кад свагда живи да се може молити за њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Јер таков нама требаше поглавар свештенички: свет, безазлен, чист, одвојен од гријешника, и који је био више небеса;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Којему није потребно сваки дан, као свештеницима, најприје за своје гријехе жртве приносити, а потом за народне, јер он ово учини једном, кад себе принесе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Јер закон поставља људе за свештенике који имају слабост; а ријеч заклетве које је речена по закону, постави сина вавијек савршена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'А ово је глава од тога што говоримо: имамо таковога поглавара свештеничкога који сједи с десне стране пријестола величине на небесима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'Који је слуга светињама и истинитој скинији, коју начини Господ, а не човјек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Јер се сваки поглавар свештенички поставља да приноси даре и жртве; зато ваља да и овај што има што ће принијети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Јер да је на земљи, не би био свештеник, кад имају свештеници који приносе даре по закону,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Који служе обличју и сјену небескијех ствари, као што би речено Мојсију кад шћаше скинију да начини: гледај, рече, да начиниш све по прилици која ти је показана на гори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'А сад доби бољу службу, као што је и посредник бољега завјета, који се на бољијем обећањима утврди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Јер да је онај први без мане био, не би се другоме тражило мјеста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Јер кудећи их говори: ево дани иду, говори Господ, и начинићу с домом Израиљевијем и с домом Јудинијем нов завјет;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Не по завјету који начиних с оцевима њиховима у онај дан кад их узех за руку да их изведем из земље Мисирске; јер они не осташе у завјету моме, и ја не марих за њих, говори Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Јер је ово завјет који ћу начинити с домом Израиљевијем послије онијех дана, говори Господ: даћу законе своје у мисли њихове, и на срцима њиховима написаћу их, и бићу им Бог, и они ће бити мени народ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'И ниједан неће учити својега ближњега, и ниједан брата својега, говорећи: познај Господа; јер ће ме сви познати од малога до великога међу њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Јер ћу бити милостив неправдама њиховима, и гријеха њиховијех и безакоња њиховијех нећу више спомињати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'А кад вели: нов завјет, први начини ветхијем; а што је ветхо и остарјело, близу је краја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Тако и први завјет имаше правде богомољства и светињу земаљску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Јер скинија бјеше начињена прва, у којој бијаше свијећњак и трпеза и постављени хљебови, што се зове светиња.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'А за другијем завјесом бијаше скинија, која се зове светиња над светињама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Која имаше златну кадионицу, и ковчег завјета окован свуда златом, у коме бијаше златан суд с маном, и палица Аронова, која се бјеше омладила, и плоче завјета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'А више њега бијаху херувими славе, који осјењаваху олтар; о чему се не може сад говорити редом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'А кад ово бијаше тако уређено, улажаху свештеници свагда у прву скинију и савршиваху службу Божију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'А у другу улажаше једном у години сам поглавар свештенички, не без крви, коју приноси за себе и за народна незнања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Овијем показиваше Дух свети да се још није отворио пут светијех, докле прва скинија стоји;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Која остаде прилика за садашње вријеме, у које се приносе дари и жртве, и не могу да се сврше по савјести онога који служи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Осим у јелима и пићима, и различном умивању и правдању тијела, које је постављено до времена поправљења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Али дошавши Христос, поглавар свештенички добара која ће доћи, кроз бољу и савршенију скинију, која није руком грађена, то јест, није овога створења,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Ни с крвљу јарчијом, нити телећом, него кроз своју крв уђе једном у светињу, и нађе вјечни откуп.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Јер ако крв јунчија и јарчија, и пепео јуничин, покропивши њом опогањене, освећује на тјелесну чистоту;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'Акамоли неће крв Христа, који Духом светијем себе принесе без кривице Богу, очистити савјест нашу од мртвијех дјела, да служимо Богу живоме и истиноме?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'И зато је новоме завјету посредник, да кроз смрт, која би за откуп од преступака у првоме завјету, обећање вјечнога нашљедства приме звани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Јер гдје је завјет ваља да буде и смрт онога који чини завјет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Јер је завјет по смрти потврђен: будући да нема никакве силе док је жив онај који га је начинио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Јер ни први није утврђен без крви.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Јер кад Мојсије изговори све заповијести по закону свому народу, онда узе крви јарчије и телеће, с водом и вуном црвеном и исопом, те покропи и књигу и сав народ');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Говорећи: ово је крв завјета који Бог начини с вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'А тако и скинију и све судове службене покропи крвљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'И готово све се крвљу чисти по закону, и без прољева крви не бива опроштење.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Тако је требало да се обличја небескијех овима чисте, а сама небеска бољијем жртвама од овијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Јер Христос не уђе у рукотворену светињу, која је прилика праве, него у само небо, да се покаже сад пред лицем Божијим за нас;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Нити да много пута приноси себе, као што поглавар свештенички улази у светињу сваке године с крвљу туђом:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Иначе би он морао много пута страдати од постања свијета; а сад једном на свршетку вијека јави се да својом жртвом сатре гријех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'И као што је људима одређено једном умријети, а потом суд:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'Тако се и Христос једном принесе, да узме многијех гријехе; а другом ће се јавити без гријеха на спасеније онима који га чекају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Јер закон имајући сјен добара која ће доћи, а не само обличје ствари, не може никада савршити оне који приступају сваке године и приносе оне исте жртве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Иначе би престале приносити се, кад они који служе не би више имали никаке савјести за гријехе, кад се једном очисте;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Него се њима сваке године чини спомен за гријехе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Јер крв јунчија и јарчија не може узети гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Зато улазећи у свијет говори: жртава и дарова нијеси хтио, али си ми тијело приправио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Жртве и прилози за гријех нијесу ти били угодни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Тада рекох: ево дођох, у почетку књиге писано је за мене, да учиним вољу твоју, Боже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'И више казавши: прилога и приноса и жртава, и жртава за гријехе нијеси хтио, нити су ти били угодни, што се по закону приносе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Тада рече: ево дођох да учиним вољу твоју, Боже. Укида прво да постави друго.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'По којој смо вољи ми освећени приносом тијела Исуса Христа једном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'И сваки свештеник стоји сваки дан служећи и једне жртве много пута приносећи које никад не могу узети гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'А он принесавши једину жртву за гријехе сједи свагда с десне стране Богу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Чекајући даље док се положе непријатељи његови подножје ногама његовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Јер једнијем приносом савршио је вавијек оне који бивају освећени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'А свједочи нам и Дух свети; јер као што је напријед казано:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Ово је завјет који ћу начинити с њима послије онијех дана, говори Господ: даћу законе своје у срца њихова, и у мислима њиховијем написаћу их;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'И гријеха њиховијех и безакоња њиховијех нећу више спомињати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'А гдје је опроштење овијех ондје више нема прилога за гријехе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Имајући дакле слободу, браћо, улазити у светињу крвљу Исуса Христа, путем новијем и живијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Који нам је обновио завјетом, то јест тијелом својијем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'И свештеника великога над домом Божијим:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Да приступамо с истинијем срцем у пуној вјери, очишћени у срцима од зле савјести, и умивени по тијелу водом чистом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Да се држимо тврдо признања нада: јер је вјеран онај који је обећао;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'И да разумијевамо једни другога у подбуњивању к љубави и добријем дјелима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Не остављајући скупштине своје, као што неки имају обичај, него један другога свјетујући, и толико већма колико видите да се приближује дан судни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Јер кад ми гријешимо навалице пошто смо примили познање истине, нема више жртве за гријехе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Него страшно чекање суда, и ревност огња који ће да поједе оне које се супроте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Ко преступи закон Мојсијев, без милости умире код два или три свједока.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Колико мислите да ће горе муке заслужити онај који сина Божијега погази, и крв завјета којом се освети за погану уздржи, и Духа благодати наружи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Јер знамо онога који рече: моја је освета, ја ћу вратити, говори Господ; и опет: Господ ће судити народу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Страшно је упасти у руке Бога живога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Опомињите се пак првијех дана својијех, у које се просвијетлисте и многу борбу страдања поднесосте,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Које поставши гледање са срамота и невоља, а које поставши другови онима који живе тако.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Јер се на окове моје сажалисте, и дадосте с радошћу да се разграби ваше имање, знајући да имате себи имање боље и непропадљиво на небесима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Не одбацујте дакле слободе своје, која има велику плату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Јер вам је трпљење од потребе да вољу Божију савршивши примите обећање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Јер још мало, врло мало, пак ће доћи онај који треба да дође и неће одоцнити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'А праведник живљеће од вјере; ако ли отступи неће бити по вољи моје душе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'А ми, браћо, нијесмо од онијех који отступају на погибао, него он онијех који вјерују да спасу душе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Вјера је пак тврдо чекање онога чему се надамо, и доказивање онога што не видимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Јер у њој стари добише свједочанство.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Вјером познајемо да је свијет ријечју Божјом свршен, да је све што видимо из ништа постало.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Вјером принесе Авељ Богу већу жртву него Каин, кроз коју доби свједочанство да је праведник, кад Бог посвједочи за даре његове; и кроз њу он мртав још говори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Вјером би Енох пренесен да не види смрти; и не нађе се, јер га Бог премјести, јер прије него га премјести, доби свједочанство да угоди Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'А без вјере није могуће угодити Богу; јер онај који хоће да дође к Богу, ваља да вјерује да има Бог и да плаћа онима који га траже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Вјером Ноје примивши заповијест и побојавши се онога што још не видје, начини ковчег за спасеније дома својега, којијем осуди сав свијет, и поста нашљедник правде по вјери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Вјером послуша Авраам кад би позван да изиђе у земљу коју шћаше да прими у нашљедство, и изиђе не знајући куда иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Вјером дође Авраам у земљу обећану, као у туђу, и у колибама живљаше с Исаком и с Јаковом, сунашљедницима обећања тога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Јер чекаше град који има темеље, којему је зидар и творац Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Вјером и сама Сара нероткиња прими силу да затрудни, и роди преко времена старости; јер држаше за вјерна онога који обећа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Зато се и родише од једнога, још готово мртвога, као звијезде небеске мноштвом, и као небројени пијесак покрај мора.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'У вјери помријеше сви ови не примивши обећања, него га видјевши издалека, и поклонивши му се, и признавши да су гости и дошљаци на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Јер који тако говоре показују да траже отачанства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'И да би се они опоменули онога из којега изиђоше, имали би вријеме да се врате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Али сад боље желе, то јест небеско. Зато се Бог не стиди њих назвати се Бог њихов; јер им приправи град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Вјером приведе Авраам Исака кад би кушан, и јединороднога приношаше, пошто бјеше примио обећање,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'У којему бјеше казано: у Исаку назваће ти се сјеме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Помисливши да је Бог кадар и из мртвијех васкрснути; зато га и узе за прилику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Вјером благослови Исак Јакова и Исава у стварима које ће доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Вјером благослови Јаков умирући свакога сина Јосифова, и поклони се врху палице његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Вјером се опомиња Јосиф умирући изласка синова Израиљевијех, и заповиједа за кости своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Вјером Мојсија, пошто се роди, крише три мјесеца родитељи његови, јер видјеше красно дијете, и побојаше се заповијести цареве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Вјером Мојсије, кад би велики, не хтједе да се назива син кћери Фараонове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'И воље страдати с народом Божијим, неголи имати земаљску сладост гријеха:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Државши срамоту Христову за веће богатство од свега блага Мисирскога; јер гледаше на плату.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Вјером остави Мисир, не побојавши се љутине цареве; јер се држаше онога који се не види, као да га виђаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Вјером учини пасху и прољев крви, да се онај који губљаше прворођене не дотакне до њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Вјером пријеђоше Црвено Море као по сухој земљи; које и Мисирци окушавши потопише се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Вјером падоше зидови Јерихонски, кад се обилази око њих седам дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Вјером Раав курва не погибе с невјерницима, примивши уходе с миром, и изведавши их другијем путем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'И шта ћу још да кажем? Јер ми не би достало времена кад бих стао приповиједати о Гедеону, и о Вараку и Самсону и Јефтају, о Давиду и Самуилу, и о другијем пророцима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Који вјером побиједише царства, учинише правду, добише обећања, затворише уста лавовима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'Угасише силу огњену, утекоше од оштрица мача, ојачаше од немоћи, посташе јаки у биткама, растјераше војске туђе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Жене примише своје мртве из васкрсенија; а други бише побијени, не примивши избављења, да добију боље васкрсеније;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'А други ругање и бој поднесоше, па још и окове и тамнице;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Камењем побијени бише, претрвени бише, искушани бише, од мача помријеше; идоше у кожусима и у козјим кожама, у сиротињи, у невољи, у срамоти;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'Којијех не бијаше достојан свијет, по пустињама потуцаше се, и по горама и по пећинама и по рупама земаљскијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'И ови сви добивши свједочанство вјером не примише обећања;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Јер Бог нешто боље за нас одреди, да не приме без нас савршенства.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Зато дакле и ми имајући око себе толику гомилу свједока, да одбацимо свако бреме и гријех који је за нас прионуо, и с трпљењем да трчимо у битку која нам је одређена,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Гледајући на начелника вјере и свршитеља Исуса, који мјесто одређене себи радости претрпље крст, не марећи за срамоту, и сједе с десне стране пријестола Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Помислите дакле на онога који је таково противљење против себе од грјешника поднио, да не ослабе душе ваше и да вам не дотужи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Јер још до крви не дођосте борећи се против гријеха,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'И заборависте утјеху коју вам говори, као синовима: сине мој! не пуштај у немар карања Господња, нити губи воље кад те он покара;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Јер кога љуби Господ онога и кара; а бије свакога сина којега прима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Ако трпите карање, као синовима показује вам се Бог: јер који је син којега отац не кара?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Ако ли сте без карања, у којему сви дијел добише, даклем сте копилад, а не синови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Ако су нам дакле тјелесни оцеви наши карачи, и бојимо их се, како да не слушамо оца духова, да живимо?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Јер они за мало дана, како им угодно бјеше, караху нас; а овај на корист, да добијемо дијел од његове светиње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Јер свако карање кад бива не чини се да је радост, него жалост; али послије даће миран род правде онима који су научени њиме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Зато ослабљене руке и ослабљена кољена исправите,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'И стазе поравните ногама својима, да не сврне што је хромо, него још да се исцијели.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Мир имајте и светињу са свима; без овога нико неће видјети Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Гледајте да ко не остане без благодати Божије: да не узрасте какав коријен грчине, и не учини пакост, и тијем да се многи не опогане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Да не буде ко курвар или опогањен, као Исав, који је за једно јело дао првородство своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Јер знате да је и потом, кад шћаше да прими благослов, одбачен; јер покајање не нађе мјеста, ако га и са сузама тражаше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Јер не приступисте ка гори која се може опипати, и огњу разгорјелом, облаку, и помрчини и олуји,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'И трубном гласу, и гласу ријечи, којега се одрекоше они који чуше, да не чују више ријечи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Јер не могаху да поднесу оно што се заповиједаше: ако се и звијер дотакне до горе, биће камењем убијена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'И тако страшно бјеше оно што се видје да Мојсије рече: уплашио сам се и дркћем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Него приступисте к Сионској гори, и ка граду Бога живога, Јерусалиму небескоме, и многијем хиљадама анђела,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'К сабору и цркви првороднијех који су написани на небесима, и Богу, судији свију, и духовима савршенијех праведника,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'И к Исусу, посреднику завјета новога, и крви кропљења, која боље говори неголи Авељева.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Али гледајте да се не одречете онога који говори; јер кад они не утекоше који се одрекоше онога који пророковаше на земљи, акамоли ми који се одричемо небескога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Којега глас потресе онда земљу, а сад обећа говорећи; још једном ја ћу потрести не само земљу него и небо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'А што вели: још једном, показује да ће се укинути оно што се помиче, као створено, да остане оно што се не помиче.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Зато, примајући царство непоколебано, да имамо благодат којом служимо за угодност Богу, с поштовањем и са страхом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Јер је Бог наш огањ који спаљује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Љубав братинска да остане међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Гостољубивости не заборављајте; јер неки не знајући из гостољубивости примише анђеле на конак.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Опомињите се сужња као да сте с њима свезани, онијех којима се неправда чини као да сте и сами у тијелу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Женидбу да држе сви у части, и постеља женидбена да буде чиста; а курварима и прељубочинцима судиће Бог.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Не будите среброљупци; будите задовољни онијем што имате. Јер он рече: нећу те оставити, нити ћу од тебе отступити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Тако да смијемо говорити: Господ је мој помоћник, и нећу се бојати; шта ће ми учинити човјек?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Опомињите се својијех учитеља који вам казиваше ријеч Божију; гледајте на свршетак њихова живљења, и угледајте се на вјеру њихову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Исус Христос јуче је и данас онај исти и вавијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'У науке туђе и различне не пристајте; јер је добро благодаћу утврђивати срца, а не јелима, од којијех не имаше користи они који живљаше у њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Имамо пак олтар од којега они не смију јести који служе скинији.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Јер којијех животиња крв уноси поглавар свештенички у светињу за гријехе, онијех се тјелеса спаљују изван окола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Зато Исус, да освети народ крвљу својом, изван града пострада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Зато дакле да излазимо к њему изван окола, носећи његову срамоту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Јер овдје немамо града који ће остати, него тражимо онај који ће доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Кроз њега дакле, да свагда приносимо Богу жртву хвале, то јест плод усана које признају име његово.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'А добро чинити и давати милостињу не заборављајте; јер се таковијем жртвама угађа Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Слушајте учитеље своје и покоравајте им се, јер се они старају за душе ваше, као који ће дати одговор, да то с радошћу чине, а не уздишући; јер вам ово не помаже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Молите се Богу за нас. Јер се надамо да имамо добру савјест, старајући се у свему добро да живимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'А одвише молим чините ово, да бих се прије вратио к вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'А Бог мира, који изведе из мртвијех великога пастира овцама, крвљу завјета вјечнога, Господа нашега Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Да вас саврши у свакоме дјелу добром, да учините вољу његову, чинећи у вама што је угодно пред њим, кроз Исуса Христа, којему слава ва вијек вијека. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Молим вас пак, браћо, примите ријеч поучења; јер укратко написах и послах вам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Знајте да је отишао наш брат Тимотије, с којијем, ако скоро дође, видјећу вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Поздравите све учитеље своје и све свете. Поздрављају вас браћа, која су из Талијанске.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Благодат са свима вама. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Од Јакова, Бога и Господа Исуса Христа слуге, свима дванаест кољена расијанијем по свијету поздравље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Сваку радост имајте, браћо моја, кад падате у различне напасти,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Знајући да кушање ваше вјере гради трпљење;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'А трпљење нека дјело довршује, да будете савршени и цијели без икаке мане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Ако ли коме од вас недостаје премудрости, нека иште у Бога који даје свакоме без разлике и не кори никога, и даће му се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Али нека иште с вјером, не сумњајући ништа; јер који се сумња он је као морски валови, које вјетрови подижу и размећу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Јер такови човјек нека не мисли да ће примити што од Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Који двоуми непостојан је у свима путовима својијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'А понижени брат нека се хвали висином својом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'А богати својом понизношћу; јер ће проћи као цвијет травни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Јер сунце огрија с врућином, и осуши траву, и цвијет њезин отпаде, и красота лица њезина погибе; тако ће и богати у хођењу својему увенути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Благо човјеку који претрпи напаст; јер кад буде кушан примиће вијенац живота, који Бог обрече онима који га љубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Ниједан кад се куша да не говори: Бог ме куша; јер се Бог не може злом искушати, и он не куша никога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Него свакога куша његова сласт, која га вуче и мами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Тада затрудњевши сласт рађа гријех; а гријех учињен рађа смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Не варајте се, љубазна браћо моја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Сваки добри дар и сваки поклон савршени одозго је, долази од оца свјетлости, у којега нема промијењивања ни мијењања видјела и мрака;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Јер нас драговољно породи ријечју истине, да будемо новина од његова створења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Зато, љубазна браћо моја, нека буде сваки човјек брз чути а спор говорити и спор срдити се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Јер срдња човјечија не чини правде Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Зато одбаците сваку нечистоту и сувишак злобе, и с кротошћу примите усађену ријеч која може спасти душе ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Будите пак творци ријечи, а не само слушачи, варајући сами себе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Јер ако ко слуша ријеч а не твори, он је као човјек који гледа лице тијела својега у огледалу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Јер се огледа па отиде, и одмах заборави какав бјеше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Али који провиди у савршени закон слободе и остане у њему, и не буде заборавни слушач, него творац дјела, онај ће бити блажен у дјелу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Ако који од вас мисли да вјерује, и не зауздава језика својега, него вара срце своје, његова је вјера узалуд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Јер вјера чиста и без мане пред Богом и оцем јест ова: обилазити сироте и удовице у њиховијем невољама, и држати себе неопогањена од свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Браћо моја! у вјери Господа нашега славнога Исуса Христа не гледајте ко је ко;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Јер ако дође у цркву вашу човјек са златнијем прстеном и у свијетлој хаљини, а дође и сиромах у рђавој хаљини,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'И погледате на онога у свијетлој хаљини, и речете му: ти сједи овдје лијепо, а сиромаху речете: ти стани тамо, или сједи овдје ниже подножја мојега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'И не расудисте у себи, него бисте судије злијех помисли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Чујте, љубазна браћо моја, не изабра ли Бог сиромахе овога свијета да буду богати вјером, и нашљедници царства које обрече онима који њега љубе?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'А ви осрамотисте сиромаха. Нијесу ли то богати који вас муче и вуку вас на судове?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Не хуле ли они на добро име ваше којијем сте се назвали?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Ако дакле закон царски извршујете по писму: љуби ближњега као самога себе, добро чините;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Ако ли гледате ко је ко, гријех чините, и бићете покарани од закона као преступници;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Јер који сав закон одржи а сагријеши у једноме, крив је за све,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Јер онај који је рекао: не чини прељубе, рекао је и: не убиј. Ако дакле не учиниш прељубе а убијеш, постао си преступник закона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Тако говорите и тако творите као они који ће законом слободе бити суђени;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Јер ће ономе бити суд без милости који не чини милости; и хвали се милост на суду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Каква је корист, браћо моја, ако ко рече да има вјеру а дјела нема? Зар га може вјера спасти?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Ако, на прилику, брат или сестра голи буду, или немају шта да једу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'И рече им који од вас: идите с миром, гријте се, и наситите се, а не да им потребе тјелесне, шта помаже?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Тако и вјера ако нема дјела, мртва је по себи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Но може ко рећи: ти имаш вјеру, а ја имам дјела. Покажи ми вјеру своју без дјела својијех, а ја ћу теби показати вјеру своју из дјела својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Ти вјерујеш да је један Бог; добро чиниш; и ђаволи вјерују, и дркћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Али хоћеш ли разумјети, о човјече сујетни! да је вјера без дјела мртва?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Авраам отац наш не оправда ли се дјелима кад принесе Исака сина својега на олтар?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Видиш ли да вјера поможе дјелима његовијем, и кроз дјела сврши се вјера?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'И изврши се писмо које говори: Авраам вјерова Богу, и прими му се у правду, и пријатељ Божиј назва се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Видите ли дакле да се дјелима правда човјек, а не самом вјером?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'А тако и Раав курва не оправда ли се дјелима кад прими уходе, и изведе их другијем путем?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Јер као што је тијело без духа мртво, тако је и вјера без добријех дјела мртва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Не тражите, браћо моја, да будете многи учитељи, знајући да ћемо већма бити осуђени,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Јер сви погрешујемо много пута. Али ко у ријечи не погрјешује, онај је савршен човјек, може зауздати и све тијело.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Јер гле, и коњма мећемо жвале у уста да нам се покоравају, и све тијело њихово окрећемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Гле и лађе, ако су и велике и силни их вјетрови гоне, окрећу се малом крмицом куда хоће онај који управља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'А тако је и језик мали уд, и много чини. Гле, мала ватра, и колике велике шуме сажеже.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'И језик је ватра, свијет пут неправде. Тако и језик живи међу нашијем удима, поганећи све тијело, и палећи вријеме живота нашега, и запаљујући се од пакла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Јер сав рог звјериња и птица, и бубина и риба, припитомљава се и припитомио се роду човјечијему;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'А језика нико од људи не може припитомити, јер је немирно зло, пуно иједа смртоноснога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Њим благосиљамо Бога и оца, и њим кунемо људе, који су створени по обличју Божијему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Из једнијех уста излази благослов и клетва. Не ваља, љубазна браћо моја, да ово тако бива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Еда ли може извор из једне главе точити слатко и грко?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Може ли, браћо моја, смоква маслине рађати или винова лоза смокве? Тако ниједан извор не даје слане и слатке воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Ко је међу вама мудар и паметан нека покаже од добра живљења дјела своја у кротости и премудрости.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Ако ли имате грку завист и свађу у срцима својијем, не хвалите се, ни лажите на истину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Ово није она премудрост што силази одозго, него земаљска, људска, ђаволска.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Јер гдје је завист и свађа ондје је неслога и свака зла ствар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'А која је премудрост одозго она је најприје чиста, а потом мирна, кротка, покорна, пуна милости и добријех плодова, без хатера, и нелицемјерна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'А плод правде у миру сије се онима који мир чине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Откуда ратови и распре међу нама? Не отуда ли, од сласти вашијех, које се боре у вашијем удима?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Желите и немате; убијате и завидите, и не можете да добијете; борите се и војујете, и немате, јер не иштете.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Иштете, и не примате, јер зло иштете, да у сластима својијем трошите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Прељубочинци и прељубочинице! не знате ли да је пријатељство овога свијета непријатељство Богу? Јер који хоће свијету пријатељ да буде, непријатељ Божиј постаје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Или мислите да писмо узалуд говори: дух који у нама живи мрзи на завист?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'А он даје већу благодат. Јер говори: Господ супроти се поноситима, а пониженима даје благодат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Покорите се дакле Богу, а противите се ђаволу и побјећи ће од вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Приближите се к Богу, и он ће се приближити к вама. Очистите руке, грјешници, поправите срца своја, непостојани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Будите жалосни и плачите и јаучите: смијех ваш нека се претвори у плач, и радост у жалост.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Понизите се пред Господом, и подигнуће вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Не опадајте један другога, браћо; јер ко опада брата или осуђује брата својега опада закон и осуђује закон, а ако закон осуђујеш, нијеси творац закона, него судија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Један је законодавац и судија, који може спасти и погубити; а ти ко си што другога осуђујеш?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Слушајте сад ви који говорите: данас или сјутра поћи ћемо у овај или онај град, и сједећемо ондје једну годину, и трговаћемо и добијаћемо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'ВИ који не знате шта ће бити сјутра. Јер шта је ваш живот? Он је пара, која се замало покаже, а потом нестане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Мјесто да говорите: ако Господ хтједбуде, и живи будемо учинићемо ово или оно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'А сад се хвалите својијем поносом. Свака је хвала такова зла.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Јер који зна добро чинити и не чини, гријех му је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Ходите ви сад, богати, плачите и ридајте за своје љуте невоље које иду на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Богатство ваше иструхну, и хаљине ваше поједоше мољци;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Злато ваше и сребро зарђа, и рђа њихова биће свједочанство на вас: изјешће тијело ваше као огањ. Стекосте богатство у пошљедње дане.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Гле, виче плата вашијех посленика који су радили њиве ваше и ви сте им откинули; и вика жетелаца дође до ушију Господа Саваота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Веселисте се на земљи, и насладисте се; ухранисте срца своја, као на дан заклања.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Осудисте, убисте праведника, и не брани вам се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Трпите дакле, браћо моја, до доласка Господњега. Гле, тежак чека племенитога рода из земље, и радо трпи док не прими дажд рани и позни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Трпите дакле и ви, и утврдите срца своја, јер се долазак Господњи приближи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Не уздишите један на другога, браћо, да не будете осуђени: гле, судија стоји пред вратима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Узмите, браћо моја, за углед страдања пророке који говорише у име Господа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Гле, блажене називамо оне који претрпљеше. Трпљење Јовљево чусте, и пошљедак Господњи видјесте: јер је Господ милостив и смилује се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'А прије свега, браћо моја, не куните се ни небом ни земљом, ни другом каквом клетвом; него нека буде што јест да, и што није не, да не паднете под суд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Мучи ли се ко међу вама, нека се моли Богу; је ли ко весео нека хвали Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Болује ли ко међу вама, нека дозове старјешине црквене, те нека читају молитву над њим, и нека га помажу уљем у име Господње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'И молитва вјере помоћи ће болеснику, и подигнуће га Господ; и ако је гријехе учинио, опростиће му се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Исповиједајте дакле један другоме гријехе, и молите се Богу један за другога, да оздрављате; јер непрестана молитва праведнога много може помоћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Илија бјеше човјек смртан као и ми, и помоли се Богу да не буде дажда, и не удари дажд на земљи за три године и шест мјесеци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'И опет се помоли и небо даде дажд, и земља изнесе род свој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Браћо! ако ко од вас зађе с пута истине, и обрати га ко,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Нека зна да ће онај који обрати грјешника с кривога пута његова спасти душу од смрти, и покрити мноштво гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Од Петра, апостола Исуса Христа, избранијем дошљацима, расијанијем по Понту, Галатији, Кападокији, Азији и Витинији;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'По привиђењу Бога оца, светињом Духа доведенијем у послушање и кропљење крви Исуса Христа: да вам се умножи благодат и мир.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Благословен Бог и отац Господа нашега Исуса Христа, који нас по великој милости својој прероди за жив над васкрсенијем Исуса Христа из мртвијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'За нашљедство непропадљиво, које неће иструхнути ни увенути, сачувано на небесима за вас,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Које је сила Божија вјером сачувала за спасеније, приправљено да се јави у пошљедње вријеме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Којему радујте се, премда сте сад мало (гдје је потребно) жалосни у различнијем напастима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Да се кушање ваше вјере много вредније од злата пропадљивога које се куша огњем нађе на хвалу и част и славу, кад се покаже Исус Христос;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Којега не видјевши љубите и којега сад не гледајући но вјерујући га радујете се радошћу неисказаном и прослављеном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Примајући крај своје вјере, спасеније душама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Које спасеније тражише и испитиваше за њ пророци, који за вашу благодат прорекоше;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Испитујући у каково или у које вријеме јављаше Дух Христов у њима, напријед свједочећи за Христове муке и за славе по томе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Којима се откри да не самијем себи него нама служаху овијем што вам се сад јави по онима који вам проповједише јеванђеље посланијем с неба Духом светијем, у које анђели желе завирити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Зато, љубазни, запрегнувши бедра својега ума будите тријезни, и зацијело се надајте благодати која ће вам се принијети кад дође Исус Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Као послушна дјеца, не владајући се по првијем жељама у својему незнању,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Него по свецу који вас је позвао, и ви будите свети у свему живљењу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Јер је писано: будите свети, јер сам ја свет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'И ако зовете оцем онога, који не гледајући ко је ко, суди свакоме по дјелу, проводите вријеме својега живљења са страхом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Знајући да се пропадљивијем сребром или златом не искуписте из сујетнога својег живљења, које сте видјели од отаца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Него скупоцјеном крвљу Христа, као безазлена и пречиста јагњета;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Који је одређен још прије постања свијета, а јавио се у пошљедња времена вас ради,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Који кроз њега вјерујете Бога који га подиже из мртвијех, и даде му славу, да би ваша вјера и надање било у Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Душе своје очистивши у послушању истине Духом за братољубље недволично, од чиста срца љубите добро један другога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Као прерођени не од сјемена које трухне, него од оног које не трухне, ријечју живога Бога, која остаје довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Јер је свако тијело као трава, и свака слава човјечија као цвијет травни: осуши се трава, и цвијет њезин отпаде;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Али ријеч Господња остаје довијека. А ово је ријеч што је објављена међу вама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Одбаците дакле сваку пакост и сваку пријевару и лицемјерје и завист и сва опадања,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'И будите жељни разумнога и правога млијека, као новорођена дјеца, да о њему узрастете за спасеније;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Јер окусисте да је благ Господ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'А кад дођете к њему, као камену живу, који је, истина, од људи одбачен, али од Бога изабран и прибран:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'И ви као живо камење зидајте се у кућу духовну и свештенство свето, да се приносе приноси духовни, који су Богу повољни, кроз Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Јер у писму стоји написано: ево мећем у Сиону камен крајеугалан избрани, и скупоцјени; и ко њега вјерује неће се постидјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Вама дакле који вјерујете част је; а онима који се противе камен који одбацише зидари он поста глава од угла, и камен спотицања и стијена саблазни:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'На који се и спотичу који се противе ријечи, на што су и одређени.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'А ви сте избрани род, царско свештенство, свети народ, народ добитка, да објавите добродјетељи онога који вас дозва из таме к чудноме видјелу своме;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Који некад не бијасте народ, а сад сте народ Божиј; који не бијасте помиловани, а сад сте помиловани.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Љубазни! молим вас, као дошљаке и госте, да се чувате од тјелеснијех жеља, које војују на душу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'А владајте се добро међу незнабошцима, да би за оно за што вас опадају као злочинце, видјевши ваша добра дјела, хвалили Бога у дан похођења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Будите дакле покорни свакој власти човјечијој, Господа ради: ако цару, као господару;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Ако ли кнезовима, као његовијем посланицима за освету злочинцима, а за хвалу добротворима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Јер је тако воља Божија да добријем дјелима задржавате незнање безумнијех људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Као слободни, а не као да бисте имали слободу за покривач пакости, него као слуге Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Поштујте свакога: браћу љубите, Бога се бојте, цара поштујте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Слуге! будите покорни са свакијем страхом господарима не само добрима и кроткима него и злима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Јер је ово угодно пред Богом ако Бога ради поднесе ко жалости, страдајући на правди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Јер каква је хвала ако за кривицу муке трпите? Него ако добро чинећи муке трпите, ово је угодно пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Јер сте на то и позвани, јер и Христос пострада за нас, и нама остави углед да идемо његовијем трагом:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Који гријеха не учини, нити се нађе пријевара у устима његовијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Који не псова кад га псоваше; не пријети кад страда; него се ослањаше на онога који право суди;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Који гријехе наше сам изнесе на тијелу својему на дрво, да за гријехе умремо, и за правду живимо; којега се раном исцијелисте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Јер бијасте као изгубљене овце, које немају пастира; но сад се обратисте к пастиру и владици душа својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'А тако и ви жене будите покорне својијем мужевима, да ако који и не вјерују ријечи, женскијем живљењем без ријечи да се добију,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Кад виде чисто живљење ваше са страхом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Ваша љепота да не буде споља у плетењу косе, и у ударању злата, и облачењу хаљина;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Него у тајноме човјеку срца, у једнакости кроткога и тихога духа, што је пред Богом многоцјено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Јер се тако некад украшаваху и свете жене, које се уздаху у Бога и покораваху се својијем мужевима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Као што Сара слушаше Авраама, и зваше га господаром; које сте ви кћери постале, ако чините добро, и не бојите се никаквога страха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Тако и ви мужеви живите са својијем женама по разуму, и поштујте их као слабији женски суд, и као сунашљеднице благодати живота, да се не смету молитве ваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'А најпослије будите сви сложни, жалостиви, братољубиви, милостиви, понизни;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Не враћајте зла за зло, ни псовке за псовку; него насупрот благосиљајте, знајући да сте на то позвани да наслиједите благослов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Јер који је рад да живи и да види дане добре, нека задржи језик свој од зла, и усне своје, да не говоре пријеваре;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Нека се уклони од зла, и нека учини добро; нека тражи мира и нека се држи њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Јер очи Господње гледају на праведнике, и уши његове на молитву њихову; а лице Господње на оне који зло чине да их истријеби са земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'И ко може вама наудити ако узидете за добром?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Него ако и страдате правде ради, блажени сте. Али страха њихова не бојте се, нити се плашите;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Него Господа Бога светите у срцима својијем. А будите свагда готови на одговор свакоме који вас запита за ваше надање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'С кротошћу и страхом имајте добру савјест, да ако вас опадају за што као злочинце да се постиде они што куде ваше добро живљење по Христу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Јер је боље, ако хоће воља Божија, да страдате добро чинећи, неголи зло чинећи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Јер и Христос једанпут за гријехе наше пострада, праведник за неправеднике, да нас приведе к Богу, убијен, истина, бивши тијелом, но оживљевши Духом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Којијем сишавши проповиједа и духовима који су у тамници,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Који некад не хтјеше да слушају кад их очекиваше Божије трпљење у вријеме Нојево, кад се грађаше ковчег, у коме мало, то јест осам душа, остаде од воде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'За спомен тога и нас сад спасава крштење, али не прање тјелесне нечистоте, него обећање добре савјести Богу васкрсенијем Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Који је с десне стране Богу, отишавши на небо, и слушају га анђели и власти и силе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Кад дакле Христос пострада за нас тијелом, и ви се том мисли наоружајте: јер који пострада тијелом, престаје од гријеха,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'Да остало вријеме живота у тијелу не живи више жељама човјечијим, него вољи Божијој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Јер је доста што смо прошавше вријеме живота провели по вољи незнабожачкој, живећи у нечистотама, у сластима, у пијењу и богомрскијем незнабоштвима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Зато се чуде што ви не трчите с њима у то исто неуредно живљење, и хуле на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Они ће дати одговор ономе који је готов да суди живима и мртвима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Зато се и мртвима проповједи јеванђеље, да приме суд по човјеку тијелом а по Богу да живе духом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'А свему се крај приближи. Будите дакле мудри и тријезни у молитвама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'А прије свега имајте непрестану љубав међу собом; јер љубав покрива мноштво гријеха,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Будите гостољубиви међу собом без мрмљања;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'И служите се међу собом, сваки даром који је примио, као добри пристави различне благодати Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Ако ко говори, нека говори као ријечи Божије; ако ко служи нека служи као по моћи коју Бог даје: да се у свачему слави Бог кроз Исуса Христа, коме је слава и држава ва вијек вијека. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Љубазни! не чудите се врућини која вам се догађа за кушање ваше, као да вам се што ново догађа;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Него се радујте што страдате с Христом, да бисте, и кад се јави слава његова, имали радост и весеље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Ако бивате укорени за име Христово, благо вама! јер Дух славе и Бога почива на вама: они дакле хуле на њ, а ви га прослављате.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Само да не пострада који од вас као крвник, или као лупеж, или као злочинац, или као онај који се мијеша у туђе послове;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'А ако ли као хришћанин, нека се не стиди, већ нека слави Бога у овом догађају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Јер је вријеме да се почне суд од куће Божије; ако ли се најприје од вас почне, какав ће бити пошљедак онима што се противе Божијему јеванђељу?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'И кад се праведник једва спасе, безбожник и грјешник гдје ће се јавити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Зато и који страдају по вољи Божијој нека му као вјерноме творцу предаду душе своје у добријем дјелима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Старјешине које су међу вама молим који сам и сам старјешина и свједок Христова страдања, и имам дјел у слави која ће се јавити:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Пасите стадо Божије, које вам је предато, и надгледајте га, не силом, него драговољно, и по Богу, нити за неправедне добитке, него из добра срца;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Нити као да владате народом; него бивајте угледи стаду;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'И кад се јави поглавар пастирски, примићете вијенац славе који неће увенути.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Тако ви млади слушајте старјешине; а сви се слушајте међу собом, и стеците понизност; јер се Бог поноситима супроти, а пониженима даје благодат.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Понизите се дакле под силну руку Божију, да вас повиси кад дође вријеме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Све своје бриге баците на њ, јер се он брине за вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Будите тријезни и пазите, јер супарник ваш, ђаво, као лав ричући ходи и тражи кога да прождере.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Браните се од њега тврђом у вјери, знајући да се такова страдања догађају вашој браћи по свијету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'А Бог сваке благодати, који вас позва на вјечну своју славу у Христу Исусу, он да вас, пошто мало пострадате, саврши, да утврди, да укријепи, да утемељи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Њему слава и држава ва вијек вијек. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'По Силвану, вашему вјерном брату, као што мислим, пишем вам ово мало, свјетујући и свједочећи да је ово права благодат Божија у којој стојите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Поздравља вас црква с вама избрана у Вавилону, и Марко син мој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Поздравите један другога цјеливом љубави. Мир вам свима у Христу Исусу. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Од Симона Петра, слуге и апостола Исуса Христа, онима што су примили с нама једну часну вјеру у правди Бога нашега и спаса Исуса Христа:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Благодат и мир да вам се умножи познавањем Бога и Христа Исуса Господа нашега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Будући да су нам све божанствене силе његове, које требају к животу и побожности, дароване познањем онога који нас позва славом и добродјетељу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Кроз које се нама дароваше часна и превелика обећања, да њих ради имате дијел у Божијој природи, ако утечете од тјелеснијех жеља овога свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'И не само ово окрените све старање своје да покажете у вјери својој добродјетељ, а у добродјетељи разум,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'А у разуму уздржање, а у уздржању трпљење, а у трпљењу побожност,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'А у побожности братољубље, а у братољубљу љубав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Јер кад је ово у вама, и множи се, неће вас оставити лијене нити без плода у познању Господа нашега Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'А ко нема овога слијеп је, и пипа заборавивши очишћење од старијех својијех гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Зато, браћо, постарајте се још већма да своју службу и избор утврдите; јер чинећи ово нећете погријешити никад;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Јер вам се тако обилно допусти улазак у вјечно царство Господа нашега и спаса Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Зато се нећу олијенити опомињати вам једнако ово, ако и знате и утврђени сте у овој истини;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Јер мислим да је право докле сам год у овом тијелу да вас будим опомињањем,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Знајући да ћу скоро тијело своје одбацити као што ми каза и Господ наш Исус Христос.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'А трудићу се свакојако да се и по растанку мојему можете опомињати овога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Јер вам не показасмо силе и доласка Господа нашега Исуса Христа по приповијеткама мудро измишљенијем, него смо сами видјели славу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Јер он прими од Бога оца част и славу кад дође к њему такови глас: ово је син мој љубазни, који је по мојој вољи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'И овај глас ми чусмо гдје сиђе с неба кад бијасмо с њим на светој гори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'И имамо најпоузданију пророчку ријеч, и добро чините што пазите на њу, ако на видјело које свијетли у тамноме мјесту, докле дан не осване и даница се не роди у срцима вашима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'И ово знајте најприје да ниједно пророштво књижевно не бива по своме казивању;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Јер никад пророштво не би од човјечије воље, него научени од светога Духа говорише свети Божији људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'А бијаше и лажнијех пророка у народу, као што ће и међу вама бити лажнијех учитеља, који ће унијети јереси погибли, и одрицаће се господара који их искупи и доводиће себи наглу погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'И многи ће поћи за њиховијем нечистотама којима ће се хулити на пут истине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'И у лакомству ловиће вас измишљенијем ријечима. Њихов суд одавно не доцни, и погибао њихова не дријема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Јер кад Бог не поштедје анђела који сагријешише, него их метну у окове мрака пакленога, и предаде да се чувају за суд;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'И првога свијета не поштедје, него сачувавши самосмога Ноја, проповједника правде, наведе потоп на свијет безбожнички;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'И градове Содом и Гомор сажеже и развали и осуди, и постави углед безбожницима који би постали;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'И избави праведнога Лота, кога осрамотише безаконици нечистотом живљења;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Јер кад живљаше праведник међу њима, гледајући и слушајући безакона дјела, мучаше од дана до дана праведну душу;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Зна Господ побожне избављати од напасти, а неправеднике мучећи чувати за дан судни;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'А особито оне који иду за тјелеснијем жељама нечистоте, и не маре за поглаварство, и који су безобразни и самовољни, и не дркћу хулећи на славу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Кад анђели, који већу снагу и силу имају, не изговарају на њих пред Господом хулнога суда;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'А они, као неразумна животиња, која је од природе на то створена да се хвата и коље, хуле на оно што не разумију, и у погибли својој пропашће');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Примајући плату неправде. Они мисле да је сласт частити се сваки дан; они су срамота и гријех, који се хране својијем пријеварама, једући с вама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Имајући очи пуне прељубочинства и непрестанога гријеха; прелашћујући неутврђене душе; имају срце научено лакомству, дјеца клетве;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Оставивши прави пут, зађоше, и иду путем Валаама Восорова, коме омиље плата неправедна;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Али би покаран за своје безакоње: скот нијеми проговоривши гласом човјечијим забрани безумље пророково.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ово су безводни извори, и облаци и магле које прогоне вјетрови, за које се чува мрак тамни вавијек.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Јер говорећи поносите и лажљиве ријечи прелашћују на нечистоте тјелеснијех жеља оне који отскора бјеже од онијех што живе у пријевари.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'И обећавају им слободу а сами су робови погибли; јер кога ко надвлада онај му и робује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Јер ако одбјегну од нечистоте свијета познањем Господа и спаса нашега Исуса Христа, па се опет заплету у њих и буду надвладани, буде им пошљедње горе од првога;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Јер им бјеше боље да не познаше пута правде, неголи кад познаше да се врате натраг од свете заповијести која им је предана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Јер им се догоди истинита приповијест: пас се повраћа на своју бљувотину, и: свиња окупавши се, у каљужу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Ево вам, љубазни, већ пишем другу посланицу у којима будим напомињањем ваш чисти разум,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Да се опомињете ријечи које су напријед казали свети пророци, и заповијести својијех апостола од Господа и спаса.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'И ово знајте најприје да ће у пошљедње дане доћи ругачи који ће живљети по својијем жељама,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'И говорити: гдје је обећање доласка његова? Јер откако оци помријеше све стоји тако од почетка створења.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Јер навалице неће да знаду да су небеса била отприје и земља из воде и усред воде Божијом ријечи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Зато тадашњи свијет би водом потопљен и погибе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'А садашња небеса и земља том истом ријечи задржана су те се чувају за дан страшнога суда и погибли безаконијех људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Али ово једно да вам не буде непознато, љубазни, да је један дан пред Господом као хиљада година, и хиљада година као један дан.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Не доцни Господ с обећањем, као што неки мисле да доцни, него нас трпи, јер неће да ко погине, него сви да дођу у покајање.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Али ће доћи дан Господњи као лупеж ноћу, у који ће небеса с хуком проћи, а стихије ће се од ватре распасти а земља и дјела што су на њој изгорјеће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Кад ће се дакле ово све раскопати, каковијем треба вама бити у светом живљењу и побожности,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Чекајући и желећи да буде скорије долазак Божијега дана, којега ће се ради небеса спалити и раскопати, и стихије од ватре растопити?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Али чекамо по обећању његову ново небо и нову земљу, гдје правда живи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Зато љубазни, чекајући ово старајте се да вас он нађе чисте и праве у миру.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'И трпљење Господа нашега држите за спасење; као што вам и љубазни наш брат Павле по даној му премудрости писа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Као што говори о овоме и у свима својијем посланицама, у којима имају неке ствари тешке разумјети, које ненаучени и неутврђени изврћу, као и остала писма, на своју погибао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'А ви дакле, љубазни, знајући напријед, чувајте се да пријеваром безаконика не будете одведени с њима, и не отпаднете од своје тврђе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Него напредујте у благодати и у познању Господа нашега и спаса Исуса Христа. Њему слава и сад и у вјечна времена. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Што бјеше испочетка, што чусмо, што видјесмо очима својима, што размотрисмо и руке наше опипаше, о ријечи живота:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'И живот се јави, и видјесмо, и свједочимо, и јављамо вам живот вјечни, који бјеше у оца, и јави се нама;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Што видјесмо и чусмо то јављамо вама да и ви с нама имате заједницу; а наша је заједница с оцем и са сином његовијем Исусом Христом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'И ово вам пишемо да радост ваша буде испуњена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'И ово је обећање које чусмо од њега и јављамо вама, да је Бог видјело, и таме у њему нема никакве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Ако речемо да имамо заједницу с њим а у тами ходимо, лажемо и не творимо истине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'Ако ли у видјелу ходимо, као што је он сам у видјелу, имамо заједницу један с другијем, и крв Исуса Христа, сина његова, очишћава нас од свакога гријеха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Ако речемо да гријеха немамо, себе варамо, и истине нема у нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Ако признајемо гријехе своје, вјеран је и праведан да нам опрости гријехе наше, и очисти нас од сваке неправде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Ако речемо да не сагријешисмо, градимо га лажом, и ријеч његова није у нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Дјечице моја! ово вам пишем да не гријешите; и ако ко сагријеши, имамо заступника код оца, Исуса Христа праведника,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'И он очишћа гријехе наше, и не само наше него и свега свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'И по том разумијемо да га познасмо, ако заповијести његове држимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Који говори: познајем га, а заповијести његовијех не држи, лажа је, и у њему истине нема;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'А који држи ријеч његову, у њему је заиста љубав Божија савршена; по том познајемо да смо у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Који говори да у њему стоји, и тај треба да ходи као што је он ходио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Љубазни! не пишем вам нове заповијести, него заповијест стару коју имасте испочетка. Заповијест стара јест ријеч коју чусте испочетка.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Опет вам пишем нову заповијест, која је заиста у њему и у вама; јер тама пролази, и видјело право већ свијетли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Који говори да је у видјелу, а мрзи на својега брата, још је у тами.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Који љуби брата својега, у видјелу живи, и саблазни у њему нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'А који мрзи на својега брата, у тами је, и у тами ходи, и не зна куда иде, јер му тама заслијепи очи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Пишем вам, дјечице, да вам се опраштају гријеси имена његова ради.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Пишем вам, оци, јер познасте онога који нема почетка. Пишем вам, младићи, јер надвладасте нечастивога. Пишем вам, дјецо, јер познасте оца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Писах вам, оци, јер познасте онога који је од почетка. Писах вам, младићи, јер сте јаки, и ријеч Божија у вама стоји, и надвладасте нечастивога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Не љубите свијета ни што је на свијету. Ако ко љуби свијет, нема љубави очине у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Јер све што је на свијету, тјелесна жеља, и жеља очију, и понос живота, није од оца, него је од овога свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'И свијет пролази и жеља његова; а који твори вољу Божију остаје довијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Дјецо! Пошљедње је вријеме, и као што чусте да ће доћи антихрист, и сад многи антихристи посташе; по том познајемо да је пошљедњи час.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Од нас изиђоше, али не бише од нас: кад би били од нас онда би остали с нама; али да се јаве да нијесу сви од нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'И ви имате помазање од светога, и знате све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Не писах вам као да не знате истине, него што је знате, и знате да никаква лаж није од истине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Ко је лажљивац осим онога који одриче да Исус није Христос? Ово је антихрист, који се одриче оца и сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Који се год одриче сина ни оца нема; а који признаје сина, и оца има.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Ви дакле што чусте испочетка у вама нека стоји; ако у вама остане што чусте испочетка, и ви ћете остати у сину и у оцу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'И ово је обећање које нам он обећа, живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Ово вам писах за оне који вас варају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'И ви помазање што примисте од њега, у вама стоји, и не требујете да вас ко учи; него како вас то само помазање учи у свему, и истинито је, и није лаж, и као што вас научи останите у њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'И сад, дјечице, останите у њему да имамо слободу кад се јави, и да се не осрамотимо пред њим о његову доласку.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Ако знате да је праведник, познајте да је сваки који твори правду од њега рођен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Видите какву нам је љубав дао отац, да се дјеца Божија назовемо и будемо; зато свијет не познаје нас, јер њега не позна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Љубазни! сад смо дјеца Божија, и још се не показа шта ћемо бити; него знамо да кад се покаже, бићемо као и он, јер ћемо га видјети као што јест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'И сваки који овај над има на њега, чисти се, као и он што је чист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Сваки који чини гријех и безакоње чини: и гријех је безакоње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'И знате да се он јави да гријехе наше узме; и гријеха у њему нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Који год у њему стоји не гријеши; који год гријеши не видје га нити га позна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Дјечице! нико да вас не вара: који правду твори праведник је, као што је он праведан;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Који твори гријех од ђавола је, јер ђаво гријеши од почетка. Зато се јави син Божиј да раскопа дјела ђавоља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Који је год рођен од Бога не чини гријеха, јер његово сјеме стоји у њему, и не може гријешити, јер је рођен од Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'По том се познају дјеца Божија и дјеца ђавоља: који год не твори правде, није од Бога, и који не љуби брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Јер је ово заповијест, коју чусте испочетка, да љубимо један другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Не као што Каин бјеше од нечастивога и закла брата својега. И за који га узрок закла? Јер дјела његова бијаху зла, а брата му праведна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Не чудите се, браћо моја, ако свијет мрзи на вас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Ми знамо да пријеђосмо из смрти у живот, јер љубимо браћу; јер ко не љуби брата остаје у смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Сваки који мрзи на брата својега крвник је људски; и знате да ниједан крвник људски нема у себи вјечнога живота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'По том познасмо љубав што он за нас душу своју положи: ми смо дужни полагати душе за браћу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Који дакле има богатство овога свијета, и види брата својега у невољи и затвори срце своје од њега, како љубав Божија стоји у њему?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Дјечице моја! да се не љубимо ријечју ни језиком, него дјелом и истином.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'И по том дознајемо да смо од истине, и пред њим тјешимо срца своја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Јер ако нам зазире срце наше, Бог је већи од срца нашега и зна све.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Љубазни! ако нам срце наше не зазире, слободу имамо пред Богом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'И што год заиштемо, примићемо од њега, јер заповијести његове држимо и чинимо што је њему угодно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'И ово је заповијест његова да вјерујемо у име сина његова Исуса Христа, и да љубимо један другога као што нам је дао заповијест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'И који држи заповијести његове у њему стоји, и он у њему. И по том познајемо да стоји у нама, по Духу кога нам је дао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Љубазни! не вјерујте свакоме духу, него кушајте духове јесу ли од Бога; јер многи лажни пророци изиђоше на свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'По овоме познајте Духа Божијега, и духа лажнога; сваки дух који признаје да је Исус Христос у тијелу дошао, од Бога је;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'А сваки дух који не признаје да је Исус Христос у тијелу дошао, није од Бога: и овај је антихристов, за којега чусте да ће доћи, и сад је већ на свијету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Ви сте од Бога, дјечице, и надвладасте их, јер је већи који је у вама неголи који је на свијету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Они су од свијета, зато говоре од свијета, и свијет их слуша.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Ми смо од Бога; који познаје Бога слуша нас, а који није од Бога не слуша нас. По овом познајемо духа истине и духа пријеваре.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Љубазни! да љубимо један другога; јер је љубав од Бога, и сваки који има љубав од Бога је рођен, и познаје Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'А који нема љубави не позна Бога; јер је Бог љубав.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'По том се показа љубав Божија к нама што Бог сина својега јединороднога посла на свијет да живимо кроза њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'У овом је љубав не да ми показасмо љубав к Богу, него да он показа љубав к нама, и посла сина својега да очисти гријехе наше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Љубазни! кад је овако Бог показао љубав к нама, и ми смо дужни љубити један другога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Бога нико не видје никад: ако имамо љубав међу собом, Бог у нама стоји, и љубав је његова савршена у нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'По том дознајемо да у њему стојимо, и он у нама, што нам је дао од Духа својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'И ми видјесмо и свједочимо да отац посла сина да се спасе свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Који призна да је Исус син Божиј, Бог у њему стоји и он у Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'И ми познасмо и вјеровасмо љубав коју Бог има к нама. Бог је љубав, и који стоји у љубави, у Богу стоји и Бог у њему стоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Тијем се љубав у нама савршује да имамо слободу на дан судни; јер као што је он и ми смо на свијету овом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'У љубави нема страха, него савршена љубав изгони страх напоље; јер страх има муку. А ко се боји није савршен у љубави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Да имамо ми љубав к њему, јер он најприје показа љубав к нама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Ако ко рече: ја љубим Бога, а мрзи на брата својега, лажа је; јер који не љуби брата својега, кога види, како може љубити Бога, кога не види?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'И ову заповијест имамо од њега: који љуби Бога да љуби и брата својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Који год вјерује да је Исус Христос, од Бога је рођен; и који год љуби онога који је родио, љуби и онога који је рођен од њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'По том знамо да љубимо дјецу Божију кад Бога љубимо и његове заповијести држимо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Јер је ово љубав Божија да заповијести његове држимо; и заповијести његове нијесу тешке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Јер сваки који је рођен од Бога побјеђује свијет; и вјера је наша ова побједа која побиједи свијет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Ко је који свијет побјеђује осим онога који вјерује да је Исус син Божиј?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Ово је Исус Христос што дође водом и крвљу и Духом, не само водом него водом и крвљу; и Дух је који свједочи, јер је Дух истина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Јер је троје што свједочи на небу: Отац, Ријеч, и свети Дух; и ово је троје једно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'И троје је што свједочи на земљи: дух, и вода, и крв; и троје је заједно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Кад примамо свједочанство човјечије, свједочанство је Божије веће; јер је ово свједочанство Божије што свједочи за сина својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Који вјерује сина Божијега има свједочанство у себи; који не вјерује Богу начинио га је лажом, јер не вјерова свједочанству које свједочи Бог за сина својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'И ово је свједочанство да нам је Бог дао живот вјечни; и овај живот вјечни у сину је његовом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Ко има сина Божијега има живот; ко нема сина Божијега нема живота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Ово писах вама који вјерујете у име сина Божијега, да знате да имате живот вјечни и да вјерујете у име сина Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'И ово је слобода коју имамо к њему да ако што молимо по вољи његовој послуша нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'И кад знамо да нас слуша што год молимо, знамо да ће нам дато што иштемо у њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Ако ко види брата својега гдје гријеши гријех не к смрти, нека моли, и даће му живот, онима који гријеше не к смрти. Има гријех к смрти: за тај не говорим да моли.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Свака је неправда гријех; и има гријех не к смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Знамо да ниједан који је рођен од Бога, не гријеши, него који је рођен од Бога чува се, и нечастиви не дохвата се до њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Знамо да смо од Бога и сва свијет лежи у злу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'А знамо да син Божиј дође, и дао нам је разум да познамо Бога истинога, и да будемо у истиноме сину његовом Исусу Христу. Ово је истини Бог и живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Дјечице! чувајте се од незнабоштва. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Од старјешине избраној госпођи и дјеци њезиној коју ја љубим ва истину, и не само ја него сви који познаше истину,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'За истину која у нама стоји и биће с нама довијека:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Да буде с вама благодат, милост, мир од Бога оца и од Господа Исуса Христа, сина очина, у истини и у љубави.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Обрадовах се врло што нађох неке од твоје дјеце који ходе у истини, као што примисмо заповијест од оца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'И сад молим те, госпођо, не као да ти нову заповијест пишем, него коју имамо испочетка, да имамо љубав међу собом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'И ова је љубав да живимо по заповијестима његовијем. Ова је заповијест, као што чусте испочетка, да у њој живите.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Јер многе варалице изиђоше на свијет који не признају Исуса Христа да је дошао у тијелу; ово је варалица и антихрист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Чувајте се да не изгубимо што смо зарадили, него да примимо плату потпуно.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Који год преступа и не стоји у науци Христовој онај нема Бога; а који стоји у науци Христовој онај има и оца и сина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Ако ко долази к вама и ове науке не доноси, не примајте га у кућу, и не питајте се с њим;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Јер ко се упита с њим, прима дијел у његовијем злијем дјелима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Много бих вам имао писати, али не хтједох хартијом и мастилом; јер се надам да ћу доћи к вама и из уста говорити, да радост ваша буде испуњена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Поздрављају те дјеца твоје сестре избране. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Од старјешине Гају љубазноме, којега ја љубим ва истину.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Љубазни! молим се Богу да ти у свему буде добро, и да будеш здрав, као што је твојој души добро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Обрадовах се врло кад дођоше браћа и посвједочише твоју истину, како ти у истини живиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Немам веће радости од ове да чујем моја дјеца у истини да ходе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Љубазни! вјерно радиш што чиниш браћи и гостима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Који посвједочише твоју љубав пред црквом; и добро ћеш учинити ако их спремиш као што треба пред Богом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Јер имена његова ради изиђоше не примивши ништа од незнабожаца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Ми смо дакле дужни примати такове, да будемо помагачи истини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Ја писах цркви; али Диотреф, који жели да буде најстарији међу нама, не прима нас.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Зато, ако дођем, споменућу његова дјела која твори ружећи нас злијем ријечима; и није му то доста, него сам браће не прима, и забрањује онима који би хтјели да их примају, и изгони их из цркве.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Љубазни! не угледај се на зло, него на добро: који добро чини од Бога је, а који зло чини не видје Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Димитрију свједочише сви, и сама истина; а и ми свједочимо; и знате да је свједочанство наше истинито.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Много имадох да пишем; али нећу мастилом и пером да ти пишем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Него се надам да ћу те скоро видјети; и из уста говорити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Мир ти! поздрављају те пријатељи. Поздрави пријатеље по имену. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Од Јуде, Исуса Христа слуге, а брата Јаковљева, званима, који су освећени Богом оцем и одржани Исусом Христом:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Милост и мир и љубав да вам се умножи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Љубазни! старајући се једнако да вам пишем за опште ваше спасеније, би ми потребно да вам пишем молећи да се борите за праведну вјеру, која је једанпут дана светима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Јер се увукоше неки безбожни људи, који су давно одређени на ово суђење, и Бога нашега благодат претварају у нечистоту, и јединога господара Бога и Господа нашега Исуса Христа одричу се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Али ћу вам напоменути, кад и ви знате ово једанпут, да Господ избави народ из земље Мисирске, потом погуби оне који не вјероваше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'И анђеле који не држаше својега старјешинства него оставише свој стан чува у вјечнијем оковима под мраком за суд великога дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Као што Содом и Гомор, и околни њихови градови, који су се прокурвали онако као и они, и ходили за другијем месом, поставише се углед и муче се у вјечном огњу:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Тако дакле и ови што сањајући тијело погане, а поглаварства се одричу, и на славу хуле.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'А МИхаило Аранђел, кад се препираше с ђаволом и говораше за Мојсијево тијело, не смијаше проклета суда да изговори, него рече: Господ нека ти запријети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'А ови хуле на оно што не знаду; а што знаду по природи као неразумна животиња, у оном се распадају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Тешко њима! јер путем Каиновим пођоше и у пријевару Валаамове плате падоше, и у буни Кореовој изгибоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Ово су они што погане ваше милостиње једући с вама без страха и гојећи се; облаци безводни, које вјетрови преносе; јесенска дрвета неродљива, која су двапут умрла, и из коријена ишчупана;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Бијесни валови морски, који се пјене својијем срамотама, звијезде лажне, којима се чува мрак вјечне таме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Али и за овакве пророкова Енох, седми од Адама, говорећи: гле, иде Господ с хиљадама светијех анђела својијех');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Да учини суд свима, и да покара све безбожнике за сва њихова безбожна дјела којима безбожност чинише, и за све ружне ријечи њихове које безбожни грјешници говорише на њ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Ово су незадовољни викачи, који по жељама својијем живе, и уста њихова говоре поносите ријечи, и за добитак гледају ко је ко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'А ви, љубазни, опомињите се ријечи које напријед казаше апостоли Господа нашега Исуса Христа,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Јер вам казаше да ће у пошљедње вријеме постати ругачи, који ће ходити по својијем жељама и безбожностима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Ово су они што се одвајају (од јединости вјере), и јесу тјелесни, који духа немају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'А ви, љубазни, назиђујте се својом светом вјером, и молите се Богу Духом светијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'И сами себе држите у љубави Божијој, чекајући милости Господа нашега Исуса Христа за живот вјечни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'И тако разликујући једне милујте.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'А једне страхом избављајте и из огња вадите; а карајте са страхом, мрзећи и на хаљину опогањену од тијела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'А ономе који вас може сачувати без гријеха и без мане, и поставити праве пред славом својом у радости,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'Јединоме премудроме Богу и спасу нашему, кроз Исуса Христа Господа нашега, слава и величанство, држава и власт прије свију вијекова и сад и у све вијекове. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Откривење Исуса Христа, које даде њему Бог, да покаже слугама својима шта ће скоро бити, и показа, пославши по анђелу својему слузи својему Јовану,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Који свједочи ријеч Божију и свједочанство Исуса Христа, и шта год видје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Благо ономе који чита и онима који слушају ријечи пророштва, и држе што је написано у њему; јер је вријеме близу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Од Јована на седам цркава које су у Азији: благодат вам и мир од онога који јест, и који бјеше, и који ће доћи; и од седам духова који су пред пријестолом његовијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'И од Исуса Христа, који је свједок вјерни, и првенац из мртвијех, и кнез над царевима земаљскима, који нас љуби, и уми нас од гријеха нашијех крвљу својом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'И учини нас цареве и свештенике Богу и оцу својему; томе слава и држава ва вијек вијека. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Ено, иде с облацима, и угледаће га свако око, и који га прободоше; и заплакаће за њим сва кољена земаљска. Да, заиста.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Ја сам алфа и омега, почетак и свршетак, говори Господ, који јест, и који бјеше, и који ће доћи, сведржитељ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Ја Јован, који сам и брат ваш и друг у невољи, и у царству и трпљењу Исуса Христа, бијах на острву које се зове Патам, за ријеч Божију и за свједочанство Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Бијах у духу у дан недјељни, и чух за собом глас велики као трубе које говораше: ја сам алфа и омега, први и пошљедњи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'И: што видиш напиши у књигу, и пошљи црквама које су у Азији: у Ефес, и у Смирну, и у Пергам, и у Тијатир, и у Сард, и у Филаделфију, и у Лаодикију.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'И обазрех се да видим глас који говораше са мном; и обазревши се видјех седам свијећњака златнијех,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'И усред седам свијећњака као сина човјечијега, обучена у дугачку хаљину, и опасана по прсима појасом златнијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'А глава његова и коса бијаше бијела као бијела вуна, као снијег; и очи његове као пламен огњени;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'И ноге његове као мјед кад се растопи у пећи; и глас његов као хука вода многијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'И држаше у својој десној руци седам звијезда, и из уста његовијех излажаше мач оштар с обје стране, и лице његово бијаше као што сунце сија у сили својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'И кад га видјех, падох к ногама његовијем као мртав, и метну десницу своју на ме говорећи ми: не бој се, ја сам први и пошљедњи,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'И живи: и бијах мртав и ево сам жив ва вијек вијека, амин. И имам кључеве од пакла и од смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Напиши дакле што си видио, и шта је, и шта ће бити потом;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Тајна седам звијезда које си видио на десници мојој, и седам свијећњака златнијех: седам звијезда јесу анђели седам цркава; и седам свијећњака које си видио јесу седам цркава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Анђелу Ефеске цркве напиши: тако говори онај што држи седам звијезда у десници својој, и што ходи посред седам свијећњака златнијех:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Знам твоја дјела, и труд твој, и трпљење твоје, и да не можеш сносити злијех, и искушао си оне који говоре да су апостоли а нијесу, а нашао си их лажне;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'И поднио си много, и трпљење имаш, и за име моје трудио си се, и нијеси сустао.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Но имам на тебе, што си љубав своју прву оставио.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Опомени се дакле откуда си спао, и покај се, и прва дјела чини; ако ли не, доћи ћу ти скоро, и дигнућу свијећњак твој с мјеста његова, ако се не покајеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Но ово имаш што мрзиш на дјела Николинаца, на која и ја мрзим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Ко има ухо нека чује шта говори Дух црквама: који побиједи даћу му да једе од дрвета животнога које је насред раја Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'И анђелу цркве Смиранске напиши: тако говори први и пошљедњи, који бјеше мртав, и ево је жив:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Знам твоја дјела, и невољу и сиромаштво (али си богат), и хуле онијех који говоре да су Јевреји а нијесу, него зборница сотонина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Не бој се ни ода шта што ћеш пострадати. Гле, ђаво ће неке од вас метати у тамницу, да се искушате, и имаћете невољу до десет дана. Буди вјеран до саме смрти, и даћу ти вијенац живота.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Ко има ухо да чује нека чује шта говори Дух црквама:који побиједи неће му наудити друга смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'И анђелу Пергамске цркве напиши: тако говори онај што има мач оштар с обје стране:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Знам дјела твоја, и гдје живиш, гдје је пријесто сотонин; и држиш име моје, и нијеси се одрекао вјере моје и у оне дане у које је Антипа, вјерни свједок мој, убијен код вас, гдје живи сотона.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Но имам на тебе мало, што имаш ту који држе науку Валаама, који учаше Валака да положи саблазан пред синовима Израиљевијем, да једу жртве идолске, и да се курвају.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Тако имаш и ти који држе науку Николинаца, на коју ја мрзим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Покај се дакле; ако ли не, доћи ћу ти скоро, и војеваћу с њима мачем уста својих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Ко има ухо да чује нека чује шта говори Дух црквама: који побиједи даћу му да једе од мане сакривене, и даћу му камен бијел, и на камену ново име написано, којега нико не зна осим онога који прими.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'И анђелу Тијатирске цркве напиши: тако говори син Божиј, који има очи своје као пламен огњени, и ноге његове као мјед:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Знам твоја дјела, и љубав, и службу, и вјеру, и трпљење твоје, и дјела твоја, и да пошљедњијех има више од првијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Но имам на тебе мало, што допушташ жени Језавељи, која говори да је пророчица, да учи и да вара слуге моје да чине прељубу и да једу жртву идолску.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'И дадох јој вријеме да се покаје од курварства својега, и не покаја се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Ево је ја мећем на одар, и оне који чине прељубу с њом у невољу велику, ако се не покају од својијех дјела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'И дјецу њезину побићу на мјесто; и познаће све цркве да сам ја који испитујем срца и бубреге, и даћу вам свакоме по дјелима вашим:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'А вама говорим и осталима који су у Тијатиру који немају науке ове, и који не познају дубина сотонинијех (као што говоре): нећу метнути на вас другога бремена,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Осим који имате, држите докле дођем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'И који побиједи и одржи дјела моја до краја, даћу му власт над незнабошцима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'И пашће их гвозденом палицом, и они ће се раздробити као судови лончарски; као и ја што примих од оца својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'И даћу му звијезду даницу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Ко има ухо да чује нека чује шта говори Дух црквама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'И анђелу Сардске цркве напиши: тако говори онај што има седам Духова Божијих, и седам звијезда: знам твоја дјела, да имаш име да си жив, а мртав си.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Стражи, и утврђуј остале који хоће да помру; јер не нађох твојијех дјела савршенијех пред Богом својијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Опомињи се дакле, како си примио и како си чуо, и држи и покај се. Ако ли не узастражиш, доћи ћу на тебе као лупеж, и нећеш чути у који ћу час доћи на тебе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Али имаш мало имена и у Сарду, који не опоганише својијех хаљина, и ходиће са мном у бијелима, јер су достојни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Који побиједи он ће се обући у хаљине бијеле, и нећу избрисати имена његова из књиге живота, и признаћу име његово пред оцем својијем и пред анђелима његовима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Ко има ухо нека чује шта говори Дух црквама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'И анђелу Филаделфијске цркве напиши: тако говори свети истинити, који има кључ Давидов, који отвори и нико не затвори, који затвори и нико не отвори.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Знам твоја дјела; гле, дадох пред тобом врата отворена, и нико их не може затворити; јер имаш мало силе, и држао си моју ријеч, и нијеси се одрекао имена мојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Ево дајем оне из зборнице сотонине који говоре да су Јевреји и нијесу, него лажу; ево ћу их учинити да дођу и да се поклоне пред ногама твојим, и да познаду да те ја љубим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Јер си одржао ријеч трпљења мојега, и ја ћу тебе сачувати од часа искушења, који ће доћи на сав васиони свијет да искуша оне који живе на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Ево ћу доћи брзо: држи што имаш, да нико не узме вијенца твојега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Који побиједи учинићу га стуб у цркви Бога својега, и више неће изићи напоље; и написаћу на њему име Бога својега, и име новога Јерусалима, града Бога мојега, који силази с неба од Бога мојега, и име моје ново.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Ко има ухо нека чује шта говори Дух црквама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'И анђелу Лаодикијске цркве напиши: тако говори Амин, свједок вјерни и истинити, почетак створења Божијега:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Знам твоја дјела да нијеси ни студен ни врућ. О да си студен или врућ!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Тако, будући млак, и нијеси ни студен ни врућ, избљуваћу те из уста својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Јер говориш: богат сам, и обогатио сам се, и ништа не потребујем; а не знаш да си ти несрећан, и невољан, и сиромах, и слијеп, и го.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Свјетујем те да купиш у мене злата жеженога у огњу, да се обогатиш; и бијеле хаљине, да се обучеш, и да се не покаже срамота голотиње твоје; и масти очињом помажи очи своје да видиш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Ја које год љубим оне и карам и поучавам; постарај се дакле, и покај се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Ево стојим на вратима и куцам: ако ко чује глас мој и отвори врата, ући ћу к њему и вечераћу с њиме, и он са мном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Који побиједи даћу му да сједе са мном на пријестолу мојему, као и ја што побиједих и сједох с оцем својијем на пријестолу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Ко има ухо нека чује шта говори Дух црквама.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Потом видјех: и гле, врата отворена на небу, и глас први који чух као трубу гдје говори са мном, рече: попни се амо, и показаћу ти шта ће бити за овијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'И одмах бих у духу; и гле, пријесто стајаше на небу, и на пријестолу сјеђаше неко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'И онај што сјеђаше бијаше по виђењу као камен јаспис и сард; и око пријестола бјеше дуга по виђењу као смарагд.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'И око пријестола бијаху двадесет и четири пријестола; и на пријестолима видјех двадесет и четири старјешине гдје сједе, обучене у бијеле хаљине, и имаху круне златне на главама својим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'И од пријестола излажаху муње и громови и гласови; и седам жижака огњенијех гораху пред пријестолом, које су седам духова Божијих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'И пред пријестолом бијаше стаклено море, као кристал; и насред пријестола и око пријестола четири животиње, пуне очију спријед и састраг.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'И прва животиња бјеше као лав, и друга животиња као теле, и трећа животиња имаше лице као човјек, и четврта животиња бјеше као орао кад лети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'И свака од четири животиње имаше по шест крила наоколо, и унутра пуна очију, и мира не имају дан и ноћ говорећи: свет, свет, свет Господ Бог сведржитељ, који бјеше, и који јест, и који ће доћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'И кад даше животиње славу и част и хвалу ономе што сјеђаше на пријестолу, што живи ва вијек вијека,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Падоше двадесет и четири старјешине пред онијем што сјеђаше на пријестолу, и поклонише се ономе што живи ва вијек вијека, и метнуше круне своје пред пријестолом говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Достојан си, Господе, да примиш славу и част и силу; јер си ти саздао све, и по вољи твојој јест и створено је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'И видјех у десници онога што сјеђаше на пријестолу књигу написану изнутра и споља, запечаћену са седам печата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'И видјех анђела јака гдје проповиједа гласом великијем: ко је достојан да отвори књигу и да разломи печате њезине?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'И нико не могаше ни на небу ни на земљи, ни под земљом да отвори књиге ни да загледа у њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'И ја плаках много што се нико не нађе достојан да отвори и да прочита књигу, нити да загледа у њу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'И један од старјешина рече ми: не плачи, ево је надвладао лав, који је од кољена Јудина, коријен Давидов, да отвори књигу и разломи седам печата њезинијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'И видјех, и гле, насред пријестола и четири животиње, и посред старјешина јагње стајаше као заклано, и имаше седам рогова, и седам очију, које су седам духова Божијих посланијех по свему свијету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'И дође и узе књигу из деснице онога што сјеђаше на пријестолу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'И кад узе књигу, четири животиње и двадесет и четири старјешине падоше пред јагњетом, имајући сваки гусле, и златне чаше пуне тамјана, које су молитве светијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'И пјеваху пјесму нову говорећи: достојан си да узмеш књигу, и да отвориш печате њезине; јер си се заклао, и искупио си нас Богу крвљу својом од свакога кољена и језика и народа и племена,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'И учинио си нас Богу нашему цареве и свештенике, и цароваћемо на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'И видјех, и чух глас анђела многијех око пријестола и животиња и старјешина, и бјеше број њихов хиљада хиљада.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Говорећи гласом великијем: достојно је јагње заклано да прими силу и богатство и премудрост и јачину и част и славу и благослов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'И свако створење, што је на небу, и на земљи, и под земљом, и што је на мору, и што је у њима, све чух гдје говоре: ономе што сједи на пријестолу, и јагњету благослов и част и слава и држава ва вијек вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'И четири животиње говораху: амин. И двадесет и четири старјешине падоше и поклонише се ономе што живи ва вијек вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'И видјех кад отвори јагње један од седам печата, и чух једну од четири животиње гдје говори као глас громовни: дођи и виђи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'И видјех, и гле, коњ бијел, и онај што сјеђаше на њему имадијаше стријелу; и њему се даде вијенац, и изиђе побјеђујући, и да побиједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'И кад отвори други печат, чух другу животињу гдје говори: дођи и виђи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'И изиђе други коњ риђ, и ономе што сјеђаше на њему даде се да узме мир са земље, и да убија један другога, и даде му се мач велики.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'И кад отвори трећи печат, чух трећу животињу гдје говори: дођи и виђи. И видјех, и гле, коњ вран, и онај што сјеђаше на њему имађаше мјерила у руци својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'И чух глас између четири животиње гдје говори: ока пшенице за грош, и три оке јечма за грош; а уља и вина неће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'И кад отвори четврти печат, чух глас четврте животиње гдје говори: дођи и виђи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'И видјех, и гле, коњ блијед, и ономе што сјеђаше на њему бјеше име смрт, и пакао иђаше за њим; и њему се даде област на четвртом дијелу земље да убије мачем и глађу и смрћу и звјерињем земаљскијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'И кад отвори пети печат, видјех под олтаром душе побијенијех за ријеч Божију и за свједочанство које имаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'И повикаше гласом великијем говорећи: докле, господару свети и истинити! не судиш и не кајеш крви наше на онима што живе на земљи?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'И дане бише свакоме од њих хаљине бијеле, и речено им би да почину још мало времена, докле се наврше и другари њихови и браћа њихова, који ваља да буду побијени као и они.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'И видјех кад отвори шести печат, и гле, затресе се земља врло, и сунце поста црно као врећа од костријети, и мјесец поста као крв;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'И звијезде небеске падоше на земљу као што смоква одбацује пупке своје кад је велики вјетар заљуља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'И небо се измаче као књига кад се савије, и свака гора и острво с мјеста својијех покренуше се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'И цареви земаљски, и бољари, и богати, и војводе, и силни, и сваки роб, и сваки слободњак, сакрише се по пећинама и по камењацима горскијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'И говорише горама и камењу: падните на нас, и сакријте нас од лица онога што сједи на пријестолу, и од гњева јагњетова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Јер дође велики дан гњева његова, и ко може остати?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'И потом видјех четири анђела гдје стоје на четири угла земље, и држе четири вјетра земаљска, да не душе вјетар на земљу, ни на море, ни на икако дрво.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'И видјех другога анђела гдје се пење од истока сунчанога, који имаше печат Бога живога; и повика гласом великијем на четири анђела којима бјеше дано да кваре земљу и море, говорећи:');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Не кварите ни земље, ни мора, ни дрвета, докле запечатим слуге Бога нашега на челима њиховима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'И чух број запечаћенијех, сто и четрдесет и четири хиљаде запечаћенијех од свију кољена синова Израиљевијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Од кољена Јудина дванаест хиљада запечаћенијех; од кољена Рувимова дванаест хиљада запечаћенијех; од кољена Гадова дванаест хиљада запечаћенијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'Од кољена Асирова дванаест хиљада запечаћенијех; од кољена Нефталимова дванаест хиљада запечаћенијех; од кољена Манасијина дванаест хиљада запечаћенијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'Од кољена Симеунова дванаест хиљада запечаћенијех; од кољена Левијева дванаест хиљада запечаћенијех; од кољена Исахарова дванаест хиљада запечаћенијех;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'Од кољена Завулонова дванаест хиљада запечаћенијех; од кољена Јосифова дванаест хиљада запечаћенијех; од кољена Венијаминова дванаест хиљада запечаћенијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Потом видјех, и гле, народ многи, којега не може нико избројити, од свакога језика и кољена и народа и племена, стајаше пред пријестолом и пред јагњетом, обучен у хаљине бијеле, и палме у рукама њиховима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'И повикаше гласом великијем говорећи: спасеније Богу нашему, који сједи на пријестолу, и јагњету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'И сви анђели стајаху око пријестола и старјешине и четири животиње, и падоше на лице пред пријестолом, и поклонише се Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'Говорећи: амин; благослов и слава и премудрост и хвала и част и сила и јачина Богу нашему ва вијек вијека. Амин.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'И одговори један од старјешина говорећи ми: ови обучени у бијеле хаљине ко су, и откуда дођоше?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'И рекох му: господару! ти знаш. И рече ми: ово су који дођоше од невоље велике, и опраше хаљине своје и убијелише хаљине своје у крви јагњетовој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'За то су пред пријестолом Божијим, и служе му дан и ноћ у цркви његовој; и онај што сједи на пријестолу уселиће се у њих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Више неће огладњети, и неће на њих пасти сунце, нити икаква врућина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Јер јагње, које је насред пријестола, пашће их, и упутиће их на изворе живе воде; и Бог ће отрти сваку сузу од очију њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'И кад отвори седми печат, поста тишина на небу око по сахата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'И видјех седам анђела који стајаху пред Богом, и даде им се седам труба.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'И други анђео дође и стаде пред олтаром, и имаше кадионицу златну; и бијаше му дано много тамјана да да молитвама свију светијех на олтар златни пред пријестолом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'И дим од кађења у молитвама светијех изиђе од руке анђелове пред Бога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'И узе анђео кадионицу, и напуни је огња са олтара, и баци је на земљу, и посташе гласови и громови и сијевање муња и тресење земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'И седам анђела који имаху седам труба, приправише се да затрубе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'И први анђео затруби, и поста град и огањ, смијешани с крвљу, и падоше на земљу; и трећина дрва изгорје, и свака трава зелена изгорје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'И други анђео затруби; и као велика гора огњем запаљена паде у море; и трећина мора поста крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'И умрије трећина створења које живи у мору, и трећина лађи пропаде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'И трећи анђео затруби, и паде с неба велика звијезда, која гораше као свијећа, и паде на трећину ријека и на изворе водене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'И име звијезди бјеше Пелен; и трећина вода поста пелен, и многи људи помријеше од вода, јер бијаху грке.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'И четврти анђео затруби, и ударена би трећина сунца, и трећина мјесеца, и трећина звијезда, да помрча трећина њихова, и трећина дана да не свијетли, тако и ноћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'И видјех, и чух једног анђела гдје лети посред неба и говори гласом великијем: тешко, тешко, тешко онима који живе на земљи од осталијех гласова трубнијех тројице анђела, који ће трубити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'И пети анђео затруби, и видјех звијезду гдје паде с неба на земљу, и даде јој се кључ од студенца бездана;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'И отвори студенац бездана, и изиђе дим из студенца као дим велике пећи, и поцрње сунце и небо од дима студенчева;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'И из дима изиђоше скакавци на земљу, и даде им се област, као што и скорпије имају област на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'И рече им се да не уде трави земаљској нити икакој зелени, нити икаку дрвету, него само људима који немају печата Божијега на челима својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'И даде им се да их не убијају, него да их муче пет мјесеци; и мучење њихово бијаше као мучење скорпијино кад уједе човјека;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'И у те дане тражиће људи смрт, и неће је наћи; и жељеће да умру, и смрт ће од њих бјежати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'И скакавци бијаху као коњи спремљени на бој; и на главама њиховима као круне од злата, и лица њихова као лица човјечија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'И имаху косе као косе женске, и зуби њихови бијаху као у лавова;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'И имаху оклопе као оклопе гвоздене, и глас крила њиховијех бијаше као глас кола кад многи коњи трче на бој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'И имаху репове као скорпијине, и жалци бијаху на реповима њиховима; и дана им бјеше област да уде људима пет мјесеци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'И имаху над собом цара анђела бездана којему је име Јеврејски Авадон, а Грчки Аполион.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Једно зло прође, ево иду још два зла за овијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'И шести анђео затруби, и чух глас један од четири рогља златнога олтара који је пред Богом,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Гдје говори шестоме анђелу који имаше трубу: одријеши четири анђела који су свезани код ријеке велике Еуфрата.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'И бише одријешена четири анђела који бијаху приправљени на сахат, и дан, и мјесец, и годину, да побију трећину људи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'И број војника на коњима бијаше двјеста хиљада хиљада; и чух број њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'И тако видјех у утвари коње, и оне што сјеђаху на њима, који имаху оклопе огњене и плаветне и сумпорне; и главе коња њиховијех бијаху као главе лавова, и из уста њиховијех излажаше огањ и дим и сумпор.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'И од ова три зла погибе трећина људи, од огња и од дима и од сумпора што излажаше из уста њиховијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Јер сила коња бјеше у устима њиховима, и у реповима њиховима; јер репови њихови биваху као змије и имаху главе, и њима иђаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'И остали људи који не бише побијени злима овима, не покајаше се од дјела руку својијех да се не поклањају ђаволима, ни идолима златнима и сребрнима и мједенима и каменима и дрвенима, који ни могу видјети, ни чути, ни ходити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'Нити се покајаше од убиства својијех, ни од чарања својијех, ни од курварства својега, ни од крађа својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'И видјех другога анђела јака гдје силази с неба, који бјеше обучен у облак, и дуга бјеше на глави његовој, и лице његово бјеше као сунце, и ноге његове као стубови огњени;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'И имаше у руци својој књижицу отворену, и метну ногу своју десну на море, а лијеву на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'И повика гласом великијем, као лав кад риче; и кад он повика, говораше седам громова гласове своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'И кад говорише седам громова гласове своје, шћадијах да пишем; и чух глас с неба који ми говори: запечати шта говорише седам громова, и ово не пиши.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'И анђео којега видјех гдје стоји на мору и на земљи, подиже руку своју к небу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'И закле се онијем који живи ва вијек вијека, који сазда небо и што је на њему, и земљу и што је на њој, и море и што је у њему, да времена већ неће бити;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'Него у дане гласа седмога анђела кад затруби, онда ће се свршити тајна Божија, као што јави својијем слугама пророцима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'И глас који чух с неба, опет проговори са мном и рече: иди и узми књижицу отворену из руке онога анђела што стоји на мору и на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'И отидох к анђелу, и рекох му: дај ми књижицу. И рече ми: узми и изједи је; и грка ће бити у трбуху твојему, али у устима биће ти слатка као мед.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'И узех књижицу из руке анђелове, и изједох је; и бјеше у устима мојима као мед слатка, а кад је изједох, бијаше грка у трбуху мојему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'И рече ми: ваља ти опет пророковати народима и племенима и језицима и царевима многима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'И даде ми се трска као палица говорећи: устани и измјери цркву Божију и олтар, и оне што се клањају у њој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'А порту што је изван цркве, избаци напоље, нити је мјери, јер је дана незнабошцима; и град свети газиће четрдесет и два мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'И даћу двојици својијех свједока, и прорицаће хиљаду и двјеста и шездесет дана обучени у вреће.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Ови су двије маслине и два жишка што стоје пред господаром земаљскијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'И ако им ко неправду учини, огањ излази из уста њиховијех, и појешће непријатеље њихове; и ко хтједбуде да им учини нажао онај ваља да буде убијен.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'И ови ће имати власт да затворе небо, да не падне дажд на земљу у дане њихова прорицања; и имаће власт над водама да их претварају у крв, и да ударе земљу сваком муком, кад год хтједбуду.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'И кад сврше свједочанство своје, онда ће звијер што излази из бездана учинити с њима рат, и побиједиће их и убиће их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'И тјелеса њихова оставиће на улици града великога, који се духовно зове Содом и Мисир, гдје и Господ наш разапет би.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'И гледаће неки од народа и племена и језика и кољена тјелеса њихова три дана и по, и неће дати да се њихова тјелеса метну у гробове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'И који живе на земљи, обрадоваће се и развеселиће се за њих, и слаће даре један другоме, јер ова два пророка мучише оне што живе на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'И послије три дана и по дух живота од Бога уђе у њих; и сташе оба на ногама својима, и страх велики нападе на оне који их гледаху.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'И чуше глас велики с неба, који им говори: изиђите амо. И изиђоше на небо на облацима, и видјеше их непријатељи њихови.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'И у тај час затресе се земља врло, и десети дјел града паде, и тресење земље поби седам хиљада имена човјечијих; и остали се уплашише, и даше славу Богу небескоме.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Зло друго прође; ево зло треће иде брзо.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'И седми анђео затруби и посташе велики гласови на небесима говорећи: поста царство свијета Господа нашега и Христа његова, и цароваће ва вијек вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'И двадесет и четири старјешине које сјеђаху пред Богом на пријестолима својима, падоше на лица своја и поклонише се Богу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Говорећи: хвалимо те Господе Боже сведржитељу, који јеси, и бјеше, и бићеш, што си примио силу своју велику, и царујеш.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'И незнабошци се прогњевише, и дође гњев твој и вријеме мртвима да се суди, и да се да плата слугама твојима, пророцима и светима, и онима који се боје имена твојега, малима и великима, и да се погубе они који земљу погубише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'И отвори се црква Божија на небу, и показа се ћивот завјета његова у цркви његовој; и бише сијевања муња, и гласови, и громови, и тресење земље, и град велики.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'И знак велики показа се на небу: жена обучена у сунце, и мјесец под ногама њезинијем, и на глави њезиној вијенац од дванаест звијезда.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'И бјеше трудна, и викаше од муке, и мучаше се да роди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'И показа се други знак на небу, и гле, велика црвена аждаха, која имаше седам глава, и десет рогова; и на главама њезинијем седам круна;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'И реп њезин одвуче трећину звијезда небескијех, и баци их на земљу. И аждаха стајаше пред женом која шћаше да се породи, да јој прождере дијете кад роди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'И роди мушко, сина, који ће пасти све народе с палицом гвозденом; и дијете њезино би узето к Богу и пријестолу његову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'А жена утече у пустињу гдје имаше мјесто приправљено од Бога, да се онамо храни хиљаду и двјеста и шездесет дана.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'И поста рат на небу. Михаило и анђели његови ударише на аждаху, и би се аждаха и анђели њезини.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'И не надвладаше, и више им се не нађе мјеста на небу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'И збачена би аждаха велика, стара змија, која се зове ђаво и сотона, која вара сав васиони свијет, и збачена би на земљу, и анђели њезини збачени бише с њом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'И чух глас велики на небу који говори: сад поста спасеније и сила и царство Бога нашега, и област Христа његова; јер се збаци опадач браће наше, који их опадаше пред Богом нашијем дан и ноћ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'И они га побиједише крвљу јагњетовом и ријечју свједочанства својега, и не марише за живот свој до саме смрти.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Зато веселите се небеса и ви који живите на њима. Тешко вама који живите на земљи и мору, јер ђаво сиђе к вама, и врло се расрдио, знајући да времена мало има.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'И кад видје аждаха да збачена би на земљу, гоњаше жену која роди мушко.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'И жени дана бише два крила орла великога да лети у пустињу на своје мјесто, гдје ће се хранити вријеме и времена и по времена, сакривена од лица змијина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'И испусти змија за женом из уста својијех воду као ријеку, да је утопи у ријеци.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'И поможе земља жени, и отвори земља уста своја, и прождрије ријеку коју испусти змија из уста својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'И разгњеви се змија на жену, и отиде да се побије са осталијем сјеменом њезинијем, које држи заповијести Божије и има свједочанство Исуса Христа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 18, '');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'И стадох на пијеску морскоме; и видјех звијер гдје излази из мора, која имаше седам глава, и рогова десет, и на роговима њезинијем десет круна, а на главама њезинијем имена хулна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'И звијер коју видјех бијаше као рис, и ноге јој као у медвједа, и уста њезина као уста лавова, и даде јој змија силу своју, и пријестол свој, и област велику.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'И видјех једну од глава њезинијех као рањену на смрт, и рана смрти њезине излијечи се. И чуди се сва земља иза звијери, и поклонише се змији, која даде област звијери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'И поклонише се звијери говорећи: ко је као звијер? и ко може ратовати с њом?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'И дана јој бише уста која говоре велике ствари и хуљења, и дана јој би област да чини четрдесет и два мјесеца.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'И отвори уста своја за хуљење на Бога, да хули на име његово, и на кућу његову, и на оне који живе на небу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'И дано јој би да се бије са светима, и да их побиједи; и дана јој би област над свакијем кољеном и народом и језиком и племеном.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'И поклонише јој се сви који живе на земљи којима имена нијесу записана у животној књизи јагњета, које је заклано од постања свијета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Ако ко има ухо нека чује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Ко у ропство води, биће у ропство одведен; ко ножем убије ваља да он ножем буде убијен. Овдје је трпљење и вјера светијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'И видјех другу звијер гдје излази из земље, и имаше два рога као у јагњета; и говораше као аждаха.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'И сву власт прве звијери чињаше пред њом; и учини да земља и који живе на њој поклони се првој звијери којој се исцијели рана смртна.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'И учини чудеса велика, и учини да и огањ силази с неба на земљу пред људима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'И вара оне који живе на земљи знацима, који јој бише дани да чини пред звијери, говорећи онима што живе на земљи да начине икону звијери која имаде рану смртну и оста жива.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'И би јој дано да даде дух икони звијериној, да проговори икона звијерина, и да учини да се побију који се год не поклоне икони звијериној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'И учини све, мале и велике, богате и сиромашне, слободњаке и робове, те им даде жиг на десној руци њиховој или на челима њиховима,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'Да нико не може ни купити ни продати, осим ко има жиг, или име звијери, или број имена њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Овдје је мудрост. Ко има ум нека израчуна број звијери: јер је број човјеков и број њезин шест стотина и шездесет и шест.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'И видјех, и гле, јагње стајаше на гори Сионској, и с њим сто и четрдесет и четири хиљаде, који имаху име оца његова написано на челима својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'И чух глас с неба као глас вода многијех, и као глас грома великога; и чух глас гудача који гуђаху у гусле своје.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'И пјеваху као нову пјесну пред пријестолом и пред четири животиње и пред старјешинама: и нико не могаше научити пјесне, осим онијех сто и четрдесет и четири хиљаде који су откупљени са земље.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Ово су који се не опоганише са женама, јер су дјевственици, они иду за јагњетом куд год оно пође. Ови су купљени од људи првенци Богу и јагњету.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'И у њиховијем устима не нађе се пријевара, јер су без мане пред пријестолом Божијим.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'И видјех другога анђела гдје лети посред неба, који имаше вјечно јеванђеље да објави онима који живе на земљи, и свакоме племену, и језику и кољену и народу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'И говораше великијем гласом: бојте се Бога, и подајте му славу, јер дође час суда његова; и поклоните се ономе који је створио небо и земљу и море и изворе водене.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'И други анђео за њим иде говорећи: паде, паде Вавилон град велики: јер отровнијем вином курварства својега напоји све народе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'И трећи анђео за њим иде говорећи гласом великијем: ко се год поклони звијери и икони њезиној, и прими жиг на чело своје или на руку своју,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'И он ће пити од вина гњева Божијега, које је непомијешано уточено у чашу гњева његова, и биће мучен огњем и сумпором пред анђелима светима и пред јагњетом.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'И дим мучења њихова излазиће ва вијек вијека; и неће имати мира дан и ноћ који се поклањају звијери и икони њезиној, и који примају жиг имена њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Овдје је трпљење светијех, који држе заповијести Божије и вјеру Исусову.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'И чух глас с неба гдје ми говори: напиши: благо мртвима који умиру у Господу отсад. Да, говори Дух, да почину од трудова својијех; јер дјела њихова иду за њима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'И видјех, и гле, облак бијел, и на облаку сјеђаше као син човјечиј, и имаше на глави својој круну златну, и у руци својој срп оштар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'И други анђео изиђе из цркве вичући великијем гласом ономе што сједи на облаку: замахни српом својијем и жњи, јер дође вријеме да се жње, јер се осуши жито земаљско.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'И онај што сјеђаше на облаку баци срп свој на земљу, и пожњевена би земља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'И други анђео изиђе из цркве што је на небу, и имаше и он косијер оштар.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'И други анђео изиђе из олтара, који имаше област над огњем, и повика с великом виком ономе који имаше косијер оштри, говорећи: замахни косијером својијем оштријем, и одрежи грожђе винограда земаљскога; јер већ сазреше пуца његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'И баци анђео косијер свој на земљу, и обра виноград земаљски, и метну у кацу великога гњева Божијега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'И оточи се каца изван града, и изиђе крв из каце тја до узда коњма хиљаду и шест стотина потркалишта.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'И видјех други велики знак на небу и чудо: седам анђела који имаху седам пошљедњијех зала, јер се у њима саврши гњев Божиј.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'И видјех као стаклено море смијешано с огњем, и оне што побиједише звијер и икону њезину, и жиг њезин, и број имена њезина, гдје стоје на мору стакленоме и имају гусле Божије;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'И пјеваху пјесму Мојсија слуге Божијега, и пјесму јагњетову, говорећи: велика су и дивна дјела твоја, Господе Боже сведржитељу, праведни су и истинити путови твоји, царе светијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Ко се неће побојати тебе, Господе, и прославити име твоје? Јер си ти један свет; јер ће сви незнабошци доћи и поклонити се пред тобом; јер се судови твоји јавише.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'И послије овога видјех, и гле, отвори се црква скиније свједочанства на небу,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'И изиђоше седам анђела из цркве, који имаху седам зала, обучени у чисте и бијеле хаљине од платна, и опасани по прсима појасима златнијем;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'И једна од четири животиње даде седморици анђела седам чаша златнијех напуњенијех гњева Бога, који живи ва вијек вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'И напуни се црква дима од славе Божије и од силе његове; и нико не могаше доћи у цркву, док се не сврши седам зала седморице анђела.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'И чух глас велики из цркве гдје говори седморици анђела: идите, и излијте седам чаша гњева Божијега на земљу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'И отиде први анђео, и изли чашу своју на земљу; и посташе ране зле и љуте на људима који имају жиг звијерин и који се клањају икони њезиној.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'И други анђео изли чашу своју у море; и поста крв као од мртваца, и свака душа жива умрије у мору.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'И трећи анђео изли чашу своју на ријеке и на изворе водене; и поста крв.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'И чух анђела воденога гдје говори: праведан си Господе, који јеси, и који бјеше, и свет, што си ово судио;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Јер пролише крв светијех и пророка, и крв си им дао да пију, јер су заслужили.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'И чух другога из олтара гдје говори: да, Господе Боже сведржитељу, истинити су и прави судови твоји.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'И четврти анђео изли чашу своју на сунце, и дано му би да жеже људе огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'И опалише се људи од велике врућине, и хулише на име Бога који има област над злима овима, и не покајаше се да му даду славу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'И пети анђео изли чашу своју на пријесто звијерин; и царство њезино поста тамно, и жвакаху језике своје од бола.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'И хулише на име Бога небескога од бола и од рана својијех, и не покајаше се од дјела својијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'И шести анђео изли чашу своју на велику ријеку Еуфрат; и пресахну вода њезина, да се приправи пут царевима од истока сунчанога.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'И видјех из уста аждахинијех, и из уста звијеринијех, и из уста лажнога пророка, гдје изиђоше три нечиста духа, као жабе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Јер су ово духови ђаволски који чине чудеса и излазе к царевима свега васионога свијета да их скупе на бој за онај велики дан Бога сведржитеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Ево идем као лупеж; благо ономе који је будан и који чува хаљине своје, да го не ходи и да се не види срамота његова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'И сабра их на мјесто које се Јеврејски зове Армагедон.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'И седми анђео изли чашу своју по небу, и изиђе глас велики из цркве небеске од пријестола говорећи: сврши се.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'И бише сијевања муња и громови, и гласови, и би велико тресење земље, каково никад не би откако су људи на земљи, толико тресење, тако велико.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'И град велики раздијели се на три дијела, и градови незнабожачки падоше; и Вавилон велики спомену се пред Богом да му да чашу вина љутога гњева својега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'И сва острва побјегоше, и горе се не нађоше.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'И град велики као глава паде с неба на људе; и људи хулише на Бога од зла граднога, јер је велика мука његова врло..');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'И дође један од седам анђела који имаху седам чаша, и говори са мном говорећи ми: ходи да ти покажем суд курве велике, која сједи на водама многима;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'С којом се курваше цареви земаљски, и који живе на земљи опише се вином курварства њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'И уведе ме дух у пусто мјесто; и видјех жену гдје сједи на звијери црвеној која бјеше пуна имена хулнијех и имаше седам глава и десет рогова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'И жена бјеше обучена у порфиру и скерлет и накићена златом и камењем драгијем и бисером, и имаше чашу у руци својој пуну мрзости и поганштине курварства својега;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'И на челу њезину написано име: тајна, Вавилон велики, мати курвама и мрзостима земаљскима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'И видјех жену пијану од крви светијех и од крви свједока Исусовијех; и зачудих се чудом великијем кад је видјех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'И рече ми анђео: што се чудиш? Ја ћу ти казати тајну ове жене, и звијери што је носи и има седам глава и десет рогова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Звијер коју си видио бјеше и није, и изићи ће из бездана и отићи ће у пропаст; и удивиће се који живе на земљи, којима имена написана нијесу у књигу живота од постања свијета, кад види звијер која бјеше, и није, и доћи ће опет.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Овдје је ум, који има мудрост. Седам глава, то су седам гора на којима жена сједи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'И јесу седам царева. Пет је њих пало, и један јест, а други још није дошао; а кад дође за мало ће остати.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'И звијер која бјеше и није, и она је осми, и јест од седморице и у пропаст иде.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'И десет рогова, које си видио, то су десет царева, који царства још не примише, него ће област као цареви на једно вријеме примити са звијери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Ови једну вољу имају, и силу и област своју даће звијери.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Ови ће се побити с јагњетом и јагње ће их побиједити, јер је господар над господарима и цар над царевима; и који су с њим, јесу позвани и избрани и вјерни.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'И рече ми: воде, што си видио, гдје сједи курва, оно су људи и народи, и племена и језици.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'И десет рогова, што си видио на звијери, они ће омрзнути на курву, и опустошиће је и оголузнити, и месо њезино појешће и сажећи ће је огњем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Јер је Бог дао у срца њихова да учине вољу његову, и да учине вољу једну, и да даду царство своје звијери, док се сврше ријечи Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'И жена, коју си видио, јест град велики, који има царство над царствима земаљскима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'И послије овога видјех другога анђела гдје силази са неба, који имаше област велику; и земља се засвијетли од славе његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'И повика јакијем гласом говорећи: паде, паде Вавилон велики, и поста стан ђаволима, и тамница свакоме духу нечистоме, и тамница свију птица нечистијех и мрскијех; јер отровнијем вином курварства својега напоји све народе;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'И цареви земаљски с њом се курваше, и трговци земаљски обогатише се од богатства сласти њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'И чух глас други с неба који говори: изиђите из ње, народе мој, да се не помијешате у гријехе њезине, и да вам не науде зла њезина.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Јер гријеси њезини допријеше тја до неба, и Бог се опомену неправде њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Платите јој као што и она плати вама, и подајте јој двојином онолико по дјелима њезинима: којом чашом захвати вама захватајте јој по два пута онолико.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Колико се прослави и наслади толико јој подајте мука и жалости; јер говори у срцу својему: сједим као царица, и нијесам удовица, и жалости нећу видјети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'За то ће у један дан доћи зла њезина: смрт и плач и глад, и сажећи ће се огњем; јер је јак Господ Бог који јој суди.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'И заплакаће и зајаукати за њом цареви земаљски који се с њом курваше и бјеснише, кад виде дим горења њезина,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Издалека стојећи од страха мука њезинијех и говорећи: јаох! јаох! граде велики Вавилоне, граде тврди, јер у један час дође суд твој!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'И трговци земаљски заплакаће и зајаукати за њом, што њиховијех товара нико више не купује;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'Товара злата и сребра и камења драгога и бисера и узвода и порфире и свиле и скерлета, и свакога мирисног дрвета, и свакојакијех судова од филдиша, и свакојакијех судова од најскупљега дрвета, мједи и гвожђа и мермера,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'И цимета и тамјана и мира и ливана, и вина и уља, и нишестета и пшенице, и говеда и оваца, и коња и кола, и тјелеса и душа човјечијих.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'И воћа жеља душе твоје отидоше од тебе, и све што је масно и добро отиде од тебе, и више га нећеш наћи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Трговци који се овијем товарима обогатише од ње, стаће издалека од страха мучења њезина, плачући и јаучући,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'И говорећи: јаох! јаох! граде велики, обучени у свилу и порфиру и скерлет, и накићени златом и камењем драгијем и бисером;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Јер у један час погибе толико богатство! И сви господари од лађи, и сав народ у лађама, и лађари, и који год раде на мору, стадоше издалека,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'И викаху, видјевши дим горења њезина, и говораху: ко је био као овај град велики?');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'И бацише прах на главе своје, и повикаше плачући и ридајући, говорећи: јаох! јаох! граде велики, у коме се обогатише сви који имају лађе на мору од богатства његова, јер у један час опустје!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Весели се над њим небо, и свети апостоли и пророци, јер Бог покаја суд ваш на њему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'И узе један анђео јак камен велики, као камен воденични, и баци у море говорећи: тако ће са хуком бити бачен Вавилон град велики, и неће се више наћи;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'И глас гудача и пјевача и свирача и трубача неће се више чути у теби; и никакав мајстор ни од каква заната неће се више наћи у теби, и хука камења воденичнога неће се чути у теби;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'И видјело жишка неће се више свијетлити у теби, и глас женика и невесте неће више бити чувен у теби; јер трговци твоји бијаху бољари земаљски, јер твојијем чарањем преварени бише сви народи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'И у њему се нађе крв пророчка и светијех, и свију који су побијени на земљи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'И послије овога чух глас велики народа многога на небу гдје говори: алилуја! спасеније и слава и част и сила Господу нашему;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Јер су истинити и прави судови његови, што је осудио курву велику, која поквари земљу курварством својијем, и покајао крв слугу својијех од руке њезине.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'И другом рекоше: алилуја! И дим њезин излажаше ва вијек вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'И падоше двадесет и четири старјешине, и четири животиње, и поклонише се Богу који сјеђаше на пријестолу, говорећи: амин, алилуја!');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'И глас изиђе од пријестола који говори: хвалите Бога нашега све слуге његове, и који га се бојите, и мали и велики.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'И чух као глас народа многога, и као глас вода многијех, и као глас громова јакијех, који говоре: алилуја! јер царује Господ Бог сведржитељ.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Да се радујемо и веселимо, и да дамо славу њему; јер дође свадба јагњетова, и жена његова приправила се;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'И дано јој би да се обуче у свилу чисту и бијелу: јер је свила правда светијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'И рече ми: напиши: благо онима који су позвани на вечеру свадбе јагњетове. И рече ми: ове су ријечи истините Божије.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'И паднувши пред ногама његовима поклоних му се; и рече ми: гле, немој, ја сам слуга као и ти и браћа твоја која имају свједочанство Исусово. Богу се поклони; јер је свједочанство Исусово Дух Пророштва.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'И видјех небо отворено, и гле, коњ бијел, и који сјеђаше на њему зове се вјеран и истинит, и суди по правди и војује.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'А очи су му као пламен огњени, и на глави његовој круне многе, и имаше име написано, којега нико не зна до он сам.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'И бјеше обучен у хаљину црвену од крви, и име се његово зове: ријеч Божија.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'И војске небеске иђаху за њим на коњима бијелијем, обучене у свилу бијелу и чисту.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'И из уста његовијех изиђе мач оштар, да њиме побије незнабошце; и он ће их пасти с палицом гвозденом; и он гази кацу вина и срдње и гњева Бога сведржитеља.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'И има на хаљини и на стегну своме име написано: цар над царевима и господар над господарима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'И видјех једнога анђела гдје стоји на сунцу и повика гласом великијем говорећи свима птицама које лете испод неба: дођите и скупите се на велику вечеру Божију,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Да једете меса од царева, и меса од војвода, и меса од јунака, и меса од коња и од онијех који сједе на њима, и меса од свију слободњака и робова, и од малијех и од великијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'И видјех звијер и цареве земаљске и војнике њихове скупљене да се побију с онијем што сједи на коњу и с војскама његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'И би ухваћена звијер, и с њом лажни пророк који учини пред њом знаке којима превари оне који примише жиг звијерин и који се поклањају икони њезиној: живи бише бачени обоје у језеро огњено, које гори сумпором.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'А остали побијени бише мачем онога што сједи на коњу, који изиђе из уста његовијех: и све се птице наситише од меса њихова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'И видјех анђела гдје силази с неба, који имаше кључ од бездана и вериге велике у руци својој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'И ухвати аждаху, стару змију, која је ђаво и сотона, и свеза је на хиљаду година,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'И у бездан баци је, и затвори је, и запечати над њом, да више не прелашћује народа, док се не наврши хиљада година; и потом ваља да буде одријешена на мало времена.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'И видјех пријестоле, и сјеђаху на њима, и даде им се суд, и душе исјеченијех за свједочанство Исусово и за ријеч Божију, који се не поклонише звијери ни икони њезиној, и не примише жига на челима својима и руци својој; и оживљеше и цароваше с Христом хиљаду година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'А остали мртваци не оживљеше, докле се не сврши хиљада година. Ово је прво васкрсеније.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Блажен је и свет онај који има дијел у првом васкрсенију; над њима друга смрт нема области, него ће бити свештеници Богу и Христу, и цароваће с њим хиљаду година.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'И кад се сврши хиљада година, пустиће се сотона из тамнице своје,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'И изићи ће да вара народе по сва четири краја земље, Гога и Магога, да их скупи на бој, којијех је број као пијесак морски.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'И изиђоше на ширину земље, и опколише око светијех, и град љубазни; и сиђе огањ од Бога с неба, и поједе их.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'И ђаво који их вараше би бачен у језеро огњено и сумпорито, гдје је звијер и лажни пророк; и биће мучени дан и ноћ ва вијек вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'И видјех велики бијел пријестол, и онога што сјеђаше на њему, од чијега лица бјежаше небо и земља, и мјеста им се не нађе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'И видјех мртваце мале и велике гдје стоје пред Богом, и књиге се отворише; и друга се књига отвори, која је књига живота; и суд примише мртваци као што је написано у књигама, по дијелима својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'И море даде своје мртваце, и смрт и пакао дадоше своје мртваце; и суд примише по дјелима својима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'И смрт и пакао бачени бише у језеро огњено. И ово је друга смрт.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'И ко се не нађе написан у књизи живота, бачен би у језеро огњено.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'И видјех небо ново и земљу нову; јер прво небо и прва земља прођоше, и мора више нема.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'И ја Јован видјех град свети, Јерусалим нов, гдје силази од Бога с неба, приправљен као невјеста украшена мужу својему.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'И чух глас велики с неба гдје говори: ево скиније Божије међу људима, и живљеће с њима, и они ће бити народ његов, и сам Бог биће с њима Бог њихов.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'И Бог ће отрти сваку сузу од очију њиховијех, и смрти неће бити више, ни плача, ни вике, ни болести неће бити више; јер прво прође.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'И рече онај што сјеђаше на пријестолу: ево све ново творим. И рече ми: напиши, јер су ове ријечи истините и вјерне.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'И рече ми: сврши се. Ја сам алфа и омега, почетак и свршетак. Ја ћу жедноме дати из извора воде живе за бадава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Који побиједи, добиће све, и бићу му Бог, и он ће бити мој син.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'А страшљивима и невјернима и поганима и крвницима, и курварима, и врачарима, и идолопоклоницима, и свима лажама, њима је дијел у језеру што гори огњем и сумпором; које је смрт друга.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'И дође к мени један од седам анђела који имаху седам чаша напуњенијех седам зала пошљедњијех, и рече ми говорећи: ходи да ти покажем невјесту, јагњетову жену.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'И одведе ме у духу на гору велику и високу, и показа ми град велики, свети Јерусалим, гдје силази с неба од Бога,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'И имаше славу Божију; и свјетлост његова бијаше као драги камен, као камен јаспис свијетли,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'И имаше зид велики и висок, и имаше дванаестора врата, и на вратима дванаест анђела, и имена написана, која су имена дванаест кољена Израиљевијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Од истока врата троја, и од сјевера врата троја, од југа врата троја, и од запада врата троја.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'И зид градски имаше дванаест темеља, и на њима имена дванаест апостола јагњетовијех.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'И онај што говораше са мном, имаше трску златну да измјери град и врата његова и зидове његове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'И град на четири угла стоји, и дужина је његова толика колика и ширина. И измјери град трском на дванаест хиљада потркалишта: дужина и ширина и висина једнака је.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'И размјери зид његов на сто и четрдесет и четири лакта, по мјери човјечијој, која је анђелова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'И бјеше грађа зидова његова јаспис, и град злато чисто, као чисто стакло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'И темељи зидова градскијех бијаху украшени свакијем драгијем камењем: први темељ бијаше јаспис, други сапфир, трећи халкидон, четврти смарагд,');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'Пети сардоникс, шести сард, седми хрисолит, осми вирил, девети топаз, десети хрисопрас, једанаести јакинт, дванаести аметист.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'И дванаест врата, дванаест зрна бисера: свака врата бијаху од једнога зрна бисера: и улице градске бијаху злато чисто, као стакло пресвијетло.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'И цркве не видјех у њему: јер је њему црква Господ Бог сведржитељ, и јагње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'И град не потребује ни сунца ни мјесеца да свијетле у њему; јер га слава Божија просвијетли, и жижак је његов јагње.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'И народи који су спасени ходиће у видјелу његову, и цареви земаљски донијеће славу и част своју у њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'И врата његова неће се затворати дању, јер ондје ноћи неће бити.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'И донијеће славу и част незнабожаца у њега.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'И неће у њега ући ништа погано, и што чини мрзост и лаж, него само који су написани у животној књизи јагњета.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'И показа ми чисту ријеку воде живота, бистру као кристал, која излажаше од пријестола Божијега, и јагњетова.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Насред улица његовијех и с обје стране ријеке дрво живота, које рађа дванаест родова дајући свакога мјесеца свој род; и лишће од дрвета бијаше за исцјељивање народима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'И више неће бити никакве проклетиње; и пријестол Божиј и јагњетов биће у њему; и слуге његове послуживаће га.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'И гледаће лице његово, и име његово биће на челима њиховима.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'И ноћи тамо неће бити, и неће потребовати видјела од жишка, ни видјела сунчанога, јер ће их обасјавати Господ Бог, и цароваће ва вијек вијека.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'И рече ми: ово су ријечи вјерне и истините, и Господ Бог светијех пророка посла анђела својега да покаже слугама својима шта ће бити скоро.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Ево ћу доћи скоро: благо ономе који држи ријечи пророштва књиге ове.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'И ја Јован видјех ово и чух; и кад чух и видјех, падох да се поклоним на ноге анђела који ми ово показа.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'И рече ми: гле, немој, јер сам и ја слуга као и ти и браћа твоја пророци и они који држе ријечи пророштва књиге ове. Богу се поклони.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'И рече ми: не запечаћавај ријечи пророштва књиге ове; јер је вријеме близу.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Ко чини неправду, нека чини још неправду; и ко је поган, нека се још погани; и ко је праведан, нека још чини правду; и ко је свет нека се још свети.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'И ево ћу доћи скоро, и плата моја са мном, да дам свакоме по дјелима његовијем.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Ја сам алфа и омега, почетак и свршетак, први и пошљедњи.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Благо ономе који твори заповијести његове, да им буде власт на дрво живота, и да уђу на врата у град.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'А напољу су пси и врачари и курвари и крвници и идолопоклоници и сваки који љуби и чини лаж.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Ја Исус послах анђела својега да вам ово посвједочи у црквама. Ја сам коријен и род Давидов, и сјајна звијезда Даница.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'И Дух и невјеста говоре: дођи. И који чује нека говори: дођи. И ко је жедан нека дође, и ко хоће нека узме воду живота забадава.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Јер свједочим свакоме који чује ријечи пророштва књиге ове; ако ко дометне овоме, Бог ће наметнути на њега зла написана у књизи овој;');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'И ако ко одузме од ријечи књиге пророштва овога, Бог ће одузети његов дијел од књиге живота, и од града светога, и од онога што је написано у књизи овој.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Говори онај који свједочи ово: да, доћи ћу скоро! Амин. Да, дођи, Господе Исусе.');
INSERT INTO `SrKDIjekav_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Благодат Господа нашега Исуса Христа са свима вама. Амин.');
